func TestAgentNeedsAControllerToTalkTo(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	isolateHost(t)
	path := writeConfig(t, "agent:\n  embedded: false\n")

	if code := dispatch(context.Background(), e, []string{"agent", "--config", path}); code != exitError {
		t.Fatalf("exit code = %d, want %d", code, exitError)
	}
	for _, want := range []string{"agent.controller_url", "--controller", "ZOOMIES_CONTROLLER_URL"} {
		if !strings.Contains(errOut.String(), want) {
			t.Errorf("the error does not mention %q:\n%s", want, errOut)
		}
	}
}

func TestAgentJoinRejectsAnUnknownBackendBeforeTouchingTheHost(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	isolateHost(t)

	code := dispatch(context.Background(), e, []string{
		"agent", "join", "https://zoomies.example.com", "--token", "zoojoin_x", "--backend", "wibble",
	})
	if code != exitUsage {
		t.Fatalf("exit code = %d, want %d", code, exitUsage)
	}
	if !strings.Contains(errOut.String(), "docker, podman or process") {
		t.Errorf("the error does not list the backends:\n%s", errOut)
	}
}

func TestAgentJoinNeedsAControllerURL(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	isolateHost(t)

	if code := dispatch(context.Background(), e, []string{"agent", "join", "--token", "zoojoin_x"}); code != exitUsage {
		t.Fatalf("exit code = %d, want %d", code, exitUsage)
	}
	if !strings.Contains(errOut.String(), "controller URL") {
		t.Errorf("the error does not say what is missing:\n%s", errOut)
	}
}

// A host enrolled through a private connection has no local way to invent a
// tunnel address, so a missing or incomplete credentials file has to fail
// with one message naming the state file and pointing at the UI -- not the
// low-level "no private connection address" error a half-built transport
// used to produce before anything checked the credentials existed at all.
func TestAgentWithNoCredentialsExplainsHowToRejoinAPrivateConnection(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	dir := isolateHost(t)
	path := writeConfig(t, "agent:\n  embedded: false\n  controller_url: tailcat://controller\n  work_dir: "+filepath.Join(dir, "work")+"\n")

	if code := dispatch(context.Background(), e, []string{"agent", "--config", path}); code != exitError {
		t.Fatalf("exit code = %d, want %d\n%s", code, exitError, errOut)
	}
	for _, want := range []string{"this host cannot start", "Add a host", "Private connection"} {
		if !strings.Contains(errOut.String(), want) {
			t.Errorf("the error does not mention %q:\n%s", want, errOut)
		}
	}
	if strings.Contains(errOut.String(), "no private connection address; re-join") {
		t.Errorf("the low-level transport error leaked through instead of the daemon's own check:\n%s", errOut)
	}
}

// The same failure, but with a credentials file that exists and carries a
// host ID and agent token -- just not the tunnel address a private
// connection needs. This is what a truncated or partially restored agent.json
// looks like, and the daemon should name that specifically rather than
// reporting the host as simply unjoined.
func TestAgentWithATailcatHostMissingItsAddressNamesTheStateFile(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	dir := isolateHost(t)
	workDir := filepath.Join(dir, "work")
	if err := os.MkdirAll(workDir, 0o700); err != nil {
		t.Fatal(err)
	}
	statePath := filepath.Join(workDir, "agent.json")
	if err := os.WriteFile(statePath, []byte(`{"host_id":"host_x","agent_token":"tok","controller_url":"tailcat://controller"}`), 0o600); err != nil {
		t.Fatal(err)
	}
	path := writeConfig(t, "agent:\n  embedded: false\n  controller_url: tailcat://controller\n  work_dir: "+workDir+"\n")

	if code := dispatch(context.Background(), e, []string{"agent", "--config", path}); code != exitError {
		t.Fatalf("exit code = %d, want %d\n%s", code, exitError, errOut)
	}
	for _, want := range []string{statePath, "no private connection address", "Add a host"} {
		if !strings.Contains(errOut.String(), want) {
			t.Errorf("the error does not mention %q:\n%s", want, errOut)
		}
	}
}

func TestServiceChoice(t *testing.T) {
	if got := serviceChoice(true); got != installer.ServiceNone {
		t.Errorf("--no-service gave %q, want %q", got, installer.ServiceNone)
	}
	// An empty kind means "detect one", which is what a plain join should do.
	if got := serviceChoice(false); got != "" {
		t.Errorf("without --no-service the supervisor should be detected, got %q", got)
	}
}

// `agent install` takes no positional argument: the machine it prepares is
// the one it runs on, and a stray word is more likely a join command typed on
// the wrong line than anything this should guess at.
func TestAgentInstallTakesNoArguments(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"agent", "install", "https://zoomies.example.com"}); code != exitUsage {
		t.Fatalf("exit code = %d, want %d\n%s", code, exitUsage, errOut)
	}
	if !strings.Contains(errOut.String(), "unexpected argument") {
		t.Errorf("the error does not name the stray argument:\n%s", errOut)
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/url"
	"strings"
	"time"
)

// runAudit is `zoomies audit ...`.
func runAudit(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "audit", "Who did what.", []*subcommand{
		{"list", "", "Recent audit rows, with filters", auditList},
		{"tail", "", "Print recent rows and then follow the live stream", auditTail},
	}, args)
}

func auditList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies audit list [filters]", "List audit rows, newest first.")
	cf := registerClientFlags(fs, true)
	page := registerPageFlags(fs, 50)
	actors, actions, kinds := &listValue{}, &listValue{}, &listValue{}
	fs.Var(actors, "actor", "only this actor's rows (repeatable)")
	fs.Var(actions, "action", "only this action, e.g. pool.create (repeatable)")
	fs.Var(kinds, "target-kind", "only this kind of target, e.g. pool (repeatable)")
	target := fs.String("target", "", "only rows about this target ID")
	query := fs.String("q", "", "substring match")
	since := fs.String("since", "", "only rows since then: a duration like 24h, or a timestamp")
	until := fs.String("until", "", "only rows before then")
	fs.example("zoomies audit list --action pool.create", "zoomies audit list --since 24h --output json")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	q := url.Values{}
	addList(q, "actor_id", *actors)
	addList(q, "action", *actions)
	addList(q, "target_kind", *kinds)
	if *target != "" {
		q.Set("target_id", *target)
	}
	if *query != "" {
		q.Set("q", *query)
	}
	for name, raw := range map[string]string{"since": *since, "until": *until} {
		if raw == "" {
			continue
		}
		when, err := parseWhen(raw)
		if err != nil {
			return usagef("audit list", "--%s %q: %v", name, raw, err)
		}
		q.Set(name, when.UTC().Format(time.RFC3339))
	}
	page.apply(q)

	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[auditItem]
	raw, err := client.get(ctx, "/audit", q, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No audit rows match.")
		return nil
	}
	p.table([]string{"when", "actor", "action", "target", "from"}, auditRows(p, out.Items))
	p.footer(len(out.Items), out.Total, out.Offset)
	return nil
}

// auditLine renders one row at fixed widths.
//
// A tail cannot use the table renderer: that measures every row before it
// prints any of them, and a stream has no last row. Fixed columns keep the
// backlog and the live rows in the same shape.
func auditLine(p *printer, a auditItem) string {
	actor := a.ActorName
	if a.ActorKind != "" && a.ActorKind != "user" {
		actor += " (" + a.ActorKind + ")"
	}
	target := strings.TrimSpace(a.TargetKind + " " + a.TargetID)
	return fmt.Sprintf("%-10s  %-22s  %-24s  %s",
		p.relTime(a.CreatedAt), truncate(dash(actor), 22), truncate(a.Action, 24), truncate(dash(target), 34))
}

func auditRows(p *printer, items []auditItem) [][]string {
	rows := make([][]string, 0, len(items))
	for _, a := range items {
		actor := a.ActorName
		if a.ActorKind != "" && a.ActorKind != "user" {
			actor += " (" + a.ActorKind + ")"
		}
		target := a.TargetKind
		if a.TargetID != "" {
			target = strings.TrimSpace(target + " " + a.TargetID)
		}
		rows = append(rows, []string{
			p.relTime(a.CreatedAt),
			dash(actor),
			a.Action,
			dash(target),
			dash(a.IP),
		})
	}
	return rows
}

// auditTail prints the recent rows and then follows the live event stream.
//
// It is `tail -f` for the audit log: the backlog first, so the screen is not
// empty while nothing is happening, then every new row as it is written.
func auditTail(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies audit tail [--limit 10]",
		"Print the most recent audit rows, then follow the live stream until interrupted.")
	cf := registerClientFlags(fs, false)
	limit := fs.Int("limit", 10, "how many recent rows to print before following")
	fs.example("zoomies audit tail", "zoomies audit tail --limit 50")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := newPrinter(e, fs.Name(), outputTable)
	if err != nil {
		return err
	}
	fmt.Fprintf(e.out, "%-10s  %-22s  %-24s  %s\n", "WHEN", "ACTOR", "ACTION", "TARGET")

	if *limit > 0 {
		q := url.Values{}
		q.Set("limit", fmt.Sprint(*limit))
		var out listResponse[auditItem]
		if _, err := client.get(ctx, "/audit", q, &out); err != nil {
			return err
		}
		// The list arrives newest first; a tail reads downwards in time.
		items := make([]auditItem, 0, len(out.Items))
		for i := len(out.Items) - 1; i >= 0; i-- {
			items = append(items, out.Items[i])
		}
		for _, a := range items {
			fmt.Fprintln(e.out, auditLine(p, a))
		}
	}

	q := url.Values{}
	q.Set("kinds", "audit")
	resp, err := client.stream(ctx, "/events", q, "text/event-stream")
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	err = readSSE(resp.Body, func(f sseFrame) error {
		if f.event != "audit" {
			return nil
		}
		var a auditItem
		if err := json.Unmarshal(f.data, &a); err != nil {
			// One unreadable frame must not end the tail.
			return nil
		}
		fmt.Fprintln(e.out, auditLine(p, a))
		return nil
	})
	// Ending a tail with ctrl-C is how a tail ends, not a failure.
	if stopped(ctx, err) {
		return nil
	}
	return err
}

package main

import (
	"context"
	"fmt"
	"io"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The backup's own names, so the command and its tests speak of one layout.
// The implementation is internal/backup, shared with the controller's
// scheduled copies and the settings page: one copy taken by any of them is
// restorable by the command below.
const (
	backupManifestVersion = backup.ManifestVersion
	backupDBName          = backup.DBName
	backupDirPrefix       = backup.DirPrefix
	backupManifestName    = backup.ManifestName
	backupKeyName         = backup.KeyName
)

type backupManifest = backup.Manifest

// runBackup is `zoomies backup`.
//
// It opens the database file rather than talking to a controller, and that is
// deliberate: a backup is taken on the machine that holds the data, by whoever
// can read it, and it has to work when the controller will not start. The API
// route that takes one from the settings page is the other way in, and both
// write the same directory.
func runBackup(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies backup [--dir /var/backups/zoomies] [--keep 7] [--include-key] [--no-offsite]",
		"Take a consistent copy of the database, with a manifest saying what it is and what it needs.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	dir := fs.String("dir", "", "where to put the backup (default: backup.directory, or a `backups` directory beside the database)")
	keep := fs.Int("keep", 0, "delete all but the newest N backups in --dir; 0 keeps every one")
	includeKey := fs.Bool("include-key", false,
		"copy the encryption key into the backup as well. Convenient and dangerous: the copy then decrypts itself")
	remote := fs.String("remote", "", "send the copy to this backup remote only, instead of every one backup.remotes enables")
	noOffsite := fs.Bool("no-offsite", false, "keep the copy on this host, whatever backup.remotes says")
	fs.example("zoomies backup",
		"zoomies backup --dir /var/backups/zoomies --keep 7",
		"zoomies backup --include-key",
		"zoomies backup --remote offsite")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	cfg, err := config.Load(*cfgPath)
	if err != nil {
		return err
	}
	root := strings.TrimSpace(*dir)
	if root == "" {
		root = backup.Dir(cfg)
	}

	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path, ReadOnly: true})
	if err != nil {
		return fmt.Errorf("opening %s: %w", cfg.Database.Path, err)
	}
	defer func() { _ = st.Close() }()

	entry, err := backup.Take(ctx, st, backup.TakeOptions{
		Config: cfg, Dir: root, IncludeKey: *includeKey, Source: backup.SourceCLI,
	})
	if err != nil {
		return err
	}

	fmt.Fprintf(e.out, "Backed up to %s\n\n", entry.Dir)
	printBackupSummary(e.out, entry.Manifest, entry.Dir)

	if *keep > 0 {
		removed, err := backup.Prune(root, *keep)
		if err != nil {
			return err
		}
		if len(removed) > 0 {
			fmt.Fprintf(e.out, "\nRemoved %s, keeping the newest %d.\n", countOf(len(removed), "older backup"), *keep)
		}
	}

	// And then off the machine, because a copy beside the database is a backup
	// against a mistake rather than against the disk. It is the copy the
	// configuration already asked for: --no-offsite is how an operator taking a
	// one-off copy says this one stays here.
	if *noOffsite {
		return nil
	}
	return shipFromCLI(ctx, e, cfg, st, entry, *remote)
}

// shipFromCLI copies one backup to the remotes and says what happened, in the
// shape the command's other output takes.
//
// A failure here is reported and is not the command's exit status: the backup
// was taken, it is on the disk, and telling an operator their backup failed
// because a bucket refused a signature would be a lie about the thing they
// asked for.
func shipFromCLI(ctx context.Context, e *env, cfg *config.Config, st *store.Store, entry *backup.Entry, only string) error {
	resolved, err := remotesFor(ctx, cfg, st)
	if err != nil {
		return err
	}
	var remotes []config.BackupRemote
	for _, r := range resolved {
		switch {
		case only != "" && r.Remote.Name != only:
			continue
		case r.Shadowed:
			// Named explicitly, this is worth saying: the row exists and the
			// file is what is being used instead.
			if only != "" {
				return fmt.Errorf("the backup remote %q is described in zoomies.yaml as well, and the file wins; nothing was sent to the stored one", only)
			}
			continue
		case r.Problem != "":
			if only != "" {
				return fmt.Errorf("the backup remote %q cannot be used: %s", only, r.Problem)
			}
			fmt.Fprintf(e.out, "\n%s  NOT sent: %s\n", r.Remote.Name, r.Problem)
			continue
		case !r.Remote.Enabled():
			// A destination that is switched off stays switched off when it is
			// named: disabled is an answer about the destination, not about
			// which copies go to it.
			if only != "" {
				return fmt.Errorf("the backup remote %q is disabled or incomplete, so nothing was sent to it", only)
			}
			continue
		}
		remotes = append(remotes, r.Remote)
	}
	if only != "" && len(remotes) == 0 {
		return fmt.Errorf("no backup remote is called %q; this fleet has %s", only, remoteNames(resolved))
	}
	if len(remotes) == 0 {
		return nil
	}
	fmt.Fprintln(e.out)
	failed := false
	for _, cfgRemote := range remotes {
		remote, err := backup.NewRemote(cfgRemote, nil)
		if err != nil {
			failed = true
			fmt.Fprintf(e.out, "%s  NOT sent: %v\n", cfgRemote.Name, err)
			continue
		}
		copied, err := remote.Upload(ctx, entry)
		if err != nil {
			failed = true
			fmt.Fprintf(e.out, "%s  NOT sent: %v\n", remote.Name(), err)
			continue
		}
		sealed := "unencrypted"
		if copied.Encrypted {
			sealed = "encrypted"
		}
		fmt.Fprintf(e.out, "%s  sent to %s as %s (%s, %s)\n",
			remote.Name(), remote.Where(), copied.Key, humanBytes(int(copied.Bytes)), sealed)
		if remote.Keep() > 0 {
			removed, err := remote.Prune(ctx, remote.Keep())
			if err != nil {
				fmt.Fprintf(e.out, "%s  old copies were not removed: %v\n", remote.Name(), err)
			} else if len(removed) > 0 {
				fmt.Fprintf(e.out, "%s  removed %s, keeping the newest %d\n",
					remote.Name(), countOf(len(removed), "older copy"), remote.Keep())
			}
		}
	}
	if failed {
		fmt.Fprintf(e.out, "\nThe backup itself is on this host and is sound. What failed is getting a copy\n"+
			"off it, which is the half that survives the disk -- read the reason above.\n")
	}
	return nil
}

// remotesFor is every destination this host can see: the file's, and the ones
// stored in the database when it can be opened. The command is run on a host
// whose controller may not be running, so a database that will not open is not
// fatal -- the file's destinations are the ones that work in that case anyway.
func remotesFor(ctx context.Context, cfg *config.Config, st *store.Store) ([]backup.ResolvedRemote, error) {
	key, err := backup.ConfiguredKey(cfg)
	if err != nil {
		// Without the key the stored secrets cannot be opened, and
		// ResolveRemotes says so per destination rather than here.
		key = nil
	}
	var rows backup.RemoteLister
	if st != nil {
		rows = st
	}
	return backup.ResolveRemotes(ctx, cfg, rows, key)
}

// remoteNames lists what this fleet has, for the error that says a name is not
// one of them.
func remoteNames(resolved []backup.ResolvedRemote) string {
	var names []string
	for _, r := range resolved {
		names = append(names, r.Remote.Name)
	}
	if len(names) == 0 {
		return "no backup remotes"
	}
	return strings.Join(names, ", ")
}

// printBackupSummary says what is in the backup and, when the key is not, what
// is missing from it.
func printBackupSummary(w io.Writer, m *backupManifest, dest string) {
	rows := [][2]string{
		{"Database", fmt.Sprintf("%s (%s), integrity %s", filepath.Join(dest, backupDBName), humanBytes(int(m.Database.Bytes)), m.Database.Integrity)},
		{"Schema", lastMigration(m.Database.Migrations)},
		{"Taken by", strings.TrimSpace(m.Zoomies.Version + " " + m.Zoomies.OS + "/" + m.Zoomies.Arch)},
	}
	if m.Key.Fingerprint != "" {
		included := "not included"
		if m.Key.Included {
			included = "included in this backup"
		}
		rows = append(rows, [2]string{"Encryption key", m.Key.Fingerprint + ", " + included})
	}
	if n := len(m.Secrets); n > 0 {
		rows = append(rows, [2]string{"Needs the key for", countOf(n, "installation")})
	}
	width := 0
	for _, r := range rows {
		width = max(width, len(r[0]))
	}
	for _, r := range rows {
		fmt.Fprintf(w, "%s%s  %s\n", r[0], strings.Repeat(" ", width-len(r[0])), r[1])
	}

	// The one sentence that decides whether this backup is usable, said every
	// time rather than only when something is wrong: an operator who reads
	// "backed up" and stops has a database nobody can decrypt.
	if m.Key.Fingerprint != "" && !m.Key.Included {
		fmt.Fprintf(w, "\nThe encryption key is NOT in this backup. Without it the GitHub App credentials above\n"+
			"cannot be decrypted by anything, ever. Keep %s wherever you keep your secrets,\n"+
			"and check its fingerprint against %s when you restore.\n",
			keySourceOrPhrase(m), m.Key.Fingerprint)
	}
	if m.Key.Included {
		fmt.Fprintf(w, "\nThe encryption key is IN this backup, so the backup decrypts itself. Store it as you\n"+
			"would store the GitHub App's private key, because that is what it now contains.\n")
	}
}

func keySourceOrPhrase(m *backupManifest) string {
	if m.Key.SourcePath != "" {
		return m.Key.SourcePath
	}
	return "the key"
}

func lastMigration(names []string) string {
	if len(names) == 0 {
		return "none recorded"
	}
	return fmt.Sprintf("%s (%s applied)", names[len(names)-1], countOf(len(names), "migration"))
}

// countOf renders "1 backup" and "3 backups". The CLI has no plural helper of
// its own, and the controller's is not exported.
func countOf(n int, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	return fmt.Sprintf("%d %ss", n, noun)
}

// describeStaged says what a staged restore is waiting for, for the startup
// output: the operator who asked for it is watching the page, and the one who
// is reading the log should be able to tell why the database changed hands.
func describeStaged(s *backup.Staged) string {
	when := ""
	if !s.TakenAt.IsZero() {
		when = ", taken " + s.TakenAt.Format(time.RFC3339)
	}
	by := ""
	if s.RequestedBy != "" {
		by = " by " + s.RequestedBy
	}
	return fmt.Sprintf("%s%s, requested%s at %s", s.BackupID, when, by, s.RequestedAt.Format(time.RFC3339))
}

package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
	_ "modernc.org/sqlite"
)

// backupHost prepares a host with a database that has something sealed in it
// and a key file that opens it, which is the only configuration where the
// manifest has anything interesting to say.
func backupHost(t *testing.T) (dir string, key *cryptox.Key) {
	t.Helper()
	dir = isolateHost(t)
	ctx := context.Background()

	dbPath := filepath.Join(dir, "zoomies.db")
	t.Setenv("ZOOMIES_DB_PATH", dbPath)

	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	keyPath := filepath.Join(dir, "encryption.key")
	if err := cryptox.WriteKeyFile(keyPath, key); err != nil {
		t.Fatalf("WriteKeyFile: %v", err)
	}
	t.Setenv("ZOOMIES_ENCRYPTION_KEY_FILE", keyPath)

	st, err := store.Open(ctx, store.Options{Path: dbPath})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	sealed, err := key.SealString("-----BEGIN RSA PRIVATE KEY-----\nthe-app-key\n-----END RSA PRIVATE KEY-----")
	if err != nil {
		t.Fatalf("sealing: %v", err)
	}
	if err := st.CreateInstallation(ctx, &store.Installation{
		AppID: 4242, InstallationID: 99, Target: "acme", TargetType: store.TargetOrg,
		PrivateKeyEnc: sealed,
	}); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	return dir, key
}

func readManifest(t *testing.T, dir string) backupManifest {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(dir, backupManifestName))
	if err != nil {
		t.Fatalf("reading the manifest: %v", err)
	}
	var m backupManifest
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatalf("parsing the manifest: %v", err)
	}
	return m
}

// onlyBackup returns the single backup directory under root, failing when
// there is not exactly one.
func onlyBackup(t *testing.T, root string) string {
	t.Helper()
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Fatalf("reading %s: %v", root, err)
	}
	var dirs []string
	for _, e := range entries {
		if e.IsDir() {
			dirs = append(dirs, filepath.Join(root, e.Name()))
		}
	}
	if len(dirs) != 1 {
		t.Fatalf("want one backup under %s, found %v", root, dirs)
	}
	return dirs[0]
}

// The manifest exists because none of what it holds can be recovered from the
// database file once the instance that produced it is gone: which build wrote
// it, how far the schema had got, and whether the key file in the operator's
// hand is the one that opens it.
func TestABackupCarriesWhatARestoreWillNeedToKnow(t *testing.T) {
	_, key := backupHost(t)
	root := t.TempDir()

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"backup", "--dir", root}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	dir := onlyBackup(t, root)
	m := readManifest(t, dir)

	if m.ManifestVersion != backupManifestVersion || m.TakenAt.IsZero() {
		t.Errorf("the manifest does not say what it is or when: %+v", m)
	}
	// The build, because a restore has to run this release or a later one: the
	// store refuses a database whose ledger names migrations it does not have.
	if m.Zoomies.Version == "" || m.Zoomies.OS == "" {
		t.Errorf("the manifest does not name the build that took it: %+v", m.Zoomies)
	}
	if len(m.Database.Migrations) == 0 {
		t.Error("the manifest carries no migration ledger, so nothing says which release can open this")
	}
	if m.Database.Integrity != "ok" || m.Database.SHA256 == "" || m.Database.Bytes == 0 {
		t.Errorf("the copy was not checked or measured: %+v", m.Database)
	}
	// The fingerprint answers "is this the right key?" without the alternative,
	// which is finding out when the first GitHub call fails.
	if m.Key.Fingerprint != key.Fingerprint() {
		t.Errorf("key fingerprint = %q, want %q", m.Key.Fingerprint, key.Fingerprint())
	}
	// What the key is needed for, so an operator who has lost it knows exactly
	// what they have lost rather than guessing.
	if len(m.Secrets) != 1 || m.Secrets[0].Target != "acme" || !m.Secrets[0].PrivateKey {
		t.Errorf("the manifest does not say what the key opens: %+v", m.Secrets)
	}
	if len(m.Config) == 0 {
		t.Error("the manifest carries no configuration, which is the record of what this instance was")
	}

	// And the copy is a database, not a file: it opens on its own.
	copied, err := store.Open(context.Background(), store.Options{Path: filepath.Join(dir, backupDBName), ReadOnly: true})
	if err != nil {
		t.Fatalf("the copy does not open: %v", err)
	}
	defer copied.Close()
	insts, err := copied.ListInstallations(context.Background())
	if err != nil || len(insts) != 1 {
		t.Fatalf("the copy does not have the installation: %v, %d", err, len(insts))
	}
	if !strings.Contains(out.String(), dir) {
		t.Errorf("the terminal does not name the backup it wrote:\n%s", out)
	}
}

// The key is the difference between a backup and a folder of unreadable bytes,
// and between a backup and a credential. Both halves of that have to be true
// by default and said out loud, because an operator who reads "backed up" and
// stops has a database nobody can ever decrypt.
func TestTheKeyIsLeftOutUnlessItIsAskedForAndTheOperatorIsTold(t *testing.T) {
	t.Run("left out by default", func(t *testing.T) {
		dir, _ := backupHost(t)
		root := t.TempDir()
		e, out, errOut := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"backup", "--dir", root}); code != exitOK {
			t.Fatalf("exit code = %d\n%s", code, errOut)
		}
		b := onlyBackup(t, root)
		if _, err := os.Stat(filepath.Join(b, backupKeyName)); !os.IsNotExist(err) {
			t.Error("the encryption key was copied into a backup nobody asked to include it in")
		}
		if m := readManifest(t, b); m.Key.Included {
			t.Error("the manifest claims the key is included when it is not")
		}
		// Naming the file is the point: the operator has to go and keep it.
		if !strings.Contains(out.String(), filepath.Join(dir, "encryption.key")) {
			t.Errorf("the summary does not name the key file to keep:\n%s", out)
		}
		if !strings.Contains(out.String(), "NOT in this backup") {
			t.Errorf("the summary does not say the key is missing:\n%s", out)
		}
	})

	t.Run("included when asked", func(t *testing.T) {
		_, key := backupHost(t)
		root := t.TempDir()
		e, out, errOut := newTestEnv(t)
		if code := dispatch(context.Background(), e, []string{"backup", "--dir", root, "--include-key"}); code != exitOK {
			t.Fatalf("exit code = %d\n%s", code, errOut)
		}
		b := onlyBackup(t, root)
		copied, err := cryptox.LoadKeyFile(filepath.Join(b, backupKeyName))
		if err != nil {
			t.Fatalf("the key was not copied: %v", err)
		}
		if copied.Encode() != key.Encode() {
			t.Error("the copied key is not this instance's key")
		}
		info, err := os.Stat(filepath.Join(b, backupKeyName))
		// Windows has no mode bits to check; the backup directory's ACL is
		// what keeps the copied key private there.
		if err != nil || (runtime.GOOS != "windows" && info.Mode().Perm() != 0o600) {
			t.Errorf("the copied key is mode %v (%v); it is a credential", info.Mode().Perm(), err)
		}
		// The backup now decrypts itself, which is a different object from the
		// one the default produces, and the operator has to know that.
		if !strings.Contains(out.String(), "IN this backup") {
			t.Errorf("the summary does not say the backup now carries its own key:\n%s", out)
		}
	})
}

// Retention deletes, so it only ever deletes what this command made. The
// directory an operator points --dir at is often shared with somebody else's
// copies, and a retention rule that guessed would eventually take one.
func TestRetentionRemovesOnlyThisCommandsOwnBackups(t *testing.T) {
	backupHost(t)
	root := t.TempDir()

	// A stranger's directory, named plausibly, with no manifest in it.
	strangers := filepath.Join(root, backupDirPrefix+"00000000-000000")
	if err := os.MkdirAll(strangers, 0o700); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
	if err := os.WriteFile(filepath.Join(strangers, "notes.txt"), []byte("somebody else's"), 0o600); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	// Three of ours, distinguishable because the name carries the timestamp.
	for _, stamp := range []string{"20250101-000001", "20250101-000002", "20250101-000003"} {
		d := filepath.Join(root, backupDirPrefix+stamp)
		if err := os.MkdirAll(d, 0o700); err != nil {
			t.Fatalf("MkdirAll: %v", err)
		}
		if err := os.WriteFile(filepath.Join(d, backupManifestName), []byte("{}"), 0o600); err != nil {
			t.Fatalf("WriteFile: %v", err)
		}
	}

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"backup", "--dir", root, "--keep", "2"}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}

	if _, err := os.Stat(filepath.Join(strangers, "notes.txt")); err != nil {
		t.Errorf("retention deleted a directory this command did not write: %v", err)
	}
	names, err := os.ReadDir(root)
	if err != nil {
		t.Fatalf("ReadDir: %v", err)
	}
	var ours []string
	for _, n := range names {
		if n.Name() != filepath.Base(strangers) {
			ours = append(ours, n.Name())
		}
	}
	// The new one and the newest old one.
	if len(ours) != 2 {
		t.Errorf("--keep 2 left %v", ours)
	}
	if !strings.Contains(out.String(), "keeping the newest 2") {
		t.Errorf("the summary does not say what it removed:\n%s", out)
	}
}

// plantFutureMigration records a migration this build does not embed, which is
// what a database written by a later release looks like to this one.
func plantFutureMigration(path string) error {
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		return err
	}
	defer db.Close()
	_, err = db.Exec(`INSERT INTO schema_migrations (name, applied_at) VALUES ('9999_from_the_future.sql', 0)`)
	return err
}

package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/version"
	"gopkg.in/yaml.v3"
)

// The commands in this file and the per-resource files beside it are pure API
// clients: they open no database and call into no controller, only the HTTP
// routes in api/openapi.yaml. That is what keeps the CLI honest -- anything it
// can do, the web UI can do, because both go through the same surface -- and it
// is worth preserving deliberately, since the daemon half of this binary sits
// in the same package and the compiler will not stop anyone reaching for it.

// defaultRequestTimeout bounds an ordinary call. Streams -- a followed log tail,
// the event stream -- set no deadline of their own and are bounded by the
// operator's patience and ctrl-C instead.
const defaultRequestTimeout = 30 * time.Second

// importRequestTimeout is what an installation import waits for. The archive
// is the installation's whole history and can run to hundreds of megabytes, so
// the upload alone can outlast an ordinary call's thirty seconds.
const importRequestTimeout = 30 * time.Minute

// ---------------------------------------------------------------------------
// Credentials
// ---------------------------------------------------------------------------

// cliConfig is ~/.config/zoomies/cli.yaml: the credentials of last resort, for
// an operator who does not want ZOOMIES_TOKEN in their shell history.
type cliConfig struct {
	URL      string `yaml:"url"`
	Token    string `yaml:"token"`
	CAFile   string `yaml:"ca_file"`
	Insecure bool   `yaml:"insecure"`
}

// cliConfigPath is where that file lives.
//
// It is resolved explicitly rather than with os.UserConfigDir so that the path
// is the documented ~/.config/zoomies/cli.yaml on every platform, including
// macOS, where UserConfigDir would answer with an Application Support
// directory no documentation mentions.
func cliConfigPath() string {
	if p := strings.TrimSpace(os.Getenv("ZOOMIES_CLI_CONFIG")); p != "" {
		return p
	}
	if dir := strings.TrimSpace(os.Getenv("XDG_CONFIG_HOME")); dir != "" {
		return filepath.Join(dir, "zoomies", "cli.yaml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(".config", "zoomies", "cli.yaml")
	}
	return filepath.Join(home, ".config", "zoomies", "cli.yaml")
}

// loadCLIConfig reads the credentials file. A missing file is not an error:
// most people use the environment, and complaining about a file they never
// created would be noise.
func loadCLIConfig(path string) (cliConfig, error) {
	var c cliConfig
	raw, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return c, nil
		}
		return c, fmt.Errorf("reading %s: %w", path, err)
	}
	dec := yaml.NewDecoder(bytes.NewReader(raw))
	dec.KnownFields(true)
	if err := dec.Decode(&c); err != nil && !errors.Is(err, io.EOF) {
		return c, fmt.Errorf("%s: %w (it should hold url, token and optionally ca_file and insecure)", path, err)
	}
	return c, nil
}

// clientFlags are the flags every command that talks to a controller accepts.
type clientFlags struct {
	url      *string
	token    *string
	caFile   *string
	insecure *bool
	timeout  *time.Duration
	output   *string
	// cmd names the command these flags belong to, so that a bad --output
	// points at `zoomies pools list --help` rather than something vaguer.
	cmd string
}

// registerClientFlags adds them to a command's flag set. withOutput is false
// for the commands that change something: --output on a delete would promise a
// document that does not exist.
func registerClientFlags(fs *flagSet, withOutput bool) *clientFlags {
	cf := &clientFlags{
		cmd:      fs.Name(),
		url:      fs.String("url", "", "the controller, e.g. https://zoomies.example.com (or ZOOMIES_URL)"),
		token:    fs.String("token", "", "an API token (or ZOOMIES_TOKEN)"),
		caFile:   fs.String("ca-file", "", "PEM file holding the controller's certificate"),
		insecure: fs.Bool("insecure", false, "do not verify the controller's certificate"),
		timeout:  fs.Duration("timeout", defaultRequestTimeout, "how long to wait for one request"),
	}
	if withOutput {
		cf.output = fs.String("output", outputTable, "table, json or yaml")
	}
	return cf
}

// defaultTimeoutTo raises --timeout for a command whose one request is
// legitimately long, unless the operator set it: an explicit value is the only
// way to ask for less, so it is never overridden. Call it after parsing and
// before client().
func (cf *clientFlags) defaultTimeoutTo(fs *flagSet, d time.Duration) {
	set := false
	fs.Visit(func(f *flag.Flag) {
		if f.Name == "timeout" {
			set = true
		}
	})
	if !set {
		*cf.timeout = d
	}
}

// printer builds the renderer for this command's --output.
func (cf *clientFlags) printer(e *env) (*printer, error) {
	format := outputTable
	if cf.output != nil {
		format = *cf.output
	}
	return newPrinter(e, cf.cmd, format)
}

// client resolves credentials and builds the API client.
//
// The order is flags, then environment, then the file: the most specific thing
// the operator typed wins, and the file is what makes a plain `zoomies status`
// work at all.
func (cf *clientFlags) client() (*apiClient, error) {
	file, err := loadCLIConfig(cliConfigPath())
	if err != nil {
		return nil, err
	}

	base := firstNonBlank(*cf.url, os.Getenv("ZOOMIES_URL"), file.URL)
	if base == "" {
		return nil, missingCredential("no controller URL", "url", "https://zoomies.example.com", "")
	}
	if !strings.Contains(base, "://") {
		// A bare host is what people type first. Assume https, because
		// silently downgrading somebody's credentials to http would be worse
		// than an error they can fix with six characters.
		base = "https://" + base
	}
	parsed, err := url.Parse(base)
	if err != nil || parsed.Host == "" {
		return nil, fmt.Errorf("%q is not a controller URL; use something like https://zoomies.example.com", base)
	}

	token := firstNonBlank(*cf.token, os.Getenv("ZOOMIES_TOKEN"), file.Token)
	caFile := firstNonBlank(*cf.caFile, os.Getenv("ZOOMIES_CA_FILE"), file.CAFile)
	insecure := *cf.insecure || file.Insecure

	httpc, err := httpClient(caFile, insecure, *cf.timeout)
	if err != nil {
		return nil, err
	}
	return &apiClient{
		base:    strings.TrimRight(parsed.String(), "/"),
		token:   token,
		http:    httpc,
		timeout: *cf.timeout,
	}, nil
}

func firstNonBlank(vals ...string) string {
	for _, v := range vals {
		if s := strings.TrimSpace(v); s != "" {
			return s
		}
	}
	return ""
}

// missingCredential writes the one error message that has to be complete: it
// names all three places the value is looked for, in the order they are
// consulted, and -- for a token -- how to get one.
func missingCredential(what, key, example, why string) error {
	var b strings.Builder
	b.WriteString(what)
	if why != "" {
		b.WriteString(": ")
		b.WriteString(why)
	}
	b.WriteString(".\nSet one of these, in the order zoomies looks at them:\n")
	fmt.Fprintf(&b, "  --%s %s\n", key, example)
	fmt.Fprintf(&b, "  ZOOMIES_%s=%s\n", strings.ToUpper(key), example)
	fmt.Fprintf(&b, "  %s: %s   in %s\n", key, example, cliConfigPath())
	if key == "token" {
		b.WriteString("Mint a token in the UI under Settings -> API tokens, where it is shown once,\n")
		b.WriteString("or, with an admin token already to hand:\n")
		b.WriteString("  zoomies tokens create --name my-laptop --role operator")
	}
	return errors.New(strings.TrimRight(b.String(), "\n"))
}

// ---------------------------------------------------------------------------
// The client
// ---------------------------------------------------------------------------

// apiClient speaks the REST API in api/openapi.yaml and nothing else.
type apiClient struct {
	base    string
	token   string
	http    *http.Client
	timeout time.Duration
}

// endpoint builds an absolute URL for an API path such as "/pools".
func (c *apiClient) endpoint(path string, q url.Values) string {
	u := c.base + "/api/v1" + path
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	return u
}

// apiError is a response the controller refused, kept whole so that the field
// errors from a 422 survive to the operator's terminal.
type apiError struct {
	status  int
	method  string
	path    string
	code    string
	message string
	field   string
	detail  string
	fields  []struct {
		Field   string `json:"field"`
		Message string `json:"message"`
	}
}

func (e *apiError) Error() string {
	var b strings.Builder
	msg := e.message
	if msg == "" {
		msg = http.StatusText(e.status)
	}
	switch e.status {
	case http.StatusUnauthorized:
		return msg + "\n" + missingCredential("the controller rejected this request", "token", "zoo_...", "no usable API token was sent").Error()
	case http.StatusForbidden:
		return msg + " (this token's role is not enough for " + e.method + " " + e.path + ")"
	}
	b.WriteString(msg)
	if e.field != "" {
		fmt.Fprintf(&b, " (field %s)", e.field)
	}
	if e.detail != "" {
		fmt.Fprintf(&b, "\n  %s", e.detail)
	}
	for _, f := range e.fields {
		fmt.Fprintf(&b, "\n  %s: %s", f.Field, f.Message)
	}
	return b.String()
}

// notFound reports whether the controller said there is no such thing, which a
// few commands turn into a friendlier sentence naming what was looked for.
func notFound(err error) bool {
	var ae *apiError
	return errors.As(err, &ae) && ae.status == http.StatusNotFound
}

// do performs one request and returns the body. out, when not nil, is decoded
// from it.
func (c *apiClient) do(ctx context.Context, method, path string, q url.Values, body, out any) ([]byte, error) {
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			return nil, err
		}
		reader = bytes.NewReader(encoded)
	}

	reqCtx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	target := c.endpoint(path, q)
	req, err := http.NewRequestWithContext(reqCtx, method, target, reader)
	if err != nil {
		return nil, err
	}
	c.decorate(req)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}

	resp, err := c.http.Do(req)
	if err != nil {
		if stopped(ctx, err) {
			return nil, context.Canceled
		}
		return nil, c.transportError(method, path, err)
	}
	defer resp.Body.Close()

	raw, err := io.ReadAll(io.LimitReader(resp.Body, 32<<20))
	if err != nil {
		return nil, fmt.Errorf("reading the answer to %s %s: %w", method, path, err)
	}
	if resp.StatusCode >= 400 {
		return raw, parseAPIError(method, path, resp.StatusCode, raw)
	}
	if out != nil && len(bytes.TrimSpace(raw)) > 0 {
		if err := json.Unmarshal(raw, out); err != nil {
			return raw, fmt.Errorf("the controller's answer to %s %s was not the JSON this version expects: %w", method, path, err)
		}
	}
	return raw, nil
}

func (c *apiClient) get(ctx context.Context, path string, q url.Values, out any) ([]byte, error) {
	return c.do(ctx, http.MethodGet, path, q, nil, out)
}

func (c *apiClient) post(ctx context.Context, path string, q url.Values, body, out any) ([]byte, error) {
	return c.do(ctx, http.MethodPost, path, q, body, out)
}

func (c *apiClient) patch(ctx context.Context, path string, q url.Values, body, out any) ([]byte, error) {
	return c.do(ctx, http.MethodPatch, path, q, body, out)
}

func (c *apiClient) del(ctx context.Context, path string, q url.Values, out any) ([]byte, error) {
	return c.do(ctx, http.MethodDelete, path, q, nil, out)
}

// stream opens a response the caller reads until it ends: an SSE stream or a
// log download. It sets no timeout of its own, which is the whole point.
func (c *apiClient) stream(ctx context.Context, path string, q url.Values, accept string) (*http.Response, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.endpoint(path, q), nil)
	if err != nil {
		return nil, err
	}
	c.decorate(req)
	req.Header.Set("Accept", accept)

	resp, err := c.http.Do(req)
	if err != nil {
		if stopped(ctx, err) {
			return nil, context.Canceled
		}
		return nil, c.transportError(http.MethodGet, path, err)
	}
	if resp.StatusCode >= 400 {
		raw, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
		resp.Body.Close()
		return nil, parseAPIError(http.MethodGet, path, resp.StatusCode, raw)
	}
	return resp, nil
}

func (c *apiClient) decorate(req *http.Request) {
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", "zoomies-cli/"+version.Version)
	if c.token != "" {
		// A bearer token is exempt from the same-origin check, which is why
		// the CLI never has to think about Origin headers.
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
}

// stopped reports whether an error is only the operator's ctrl-C.
//
// It asks the context rather than inspecting the error, because a cancelled
// request surfaces as whatever the transport was doing at the time -- and
// because signal.NotifyContext attaches a cause of its own, so the error a
// stream ends with is not context.Canceled and must not be printed as a
// failure.
func stopped(ctx context.Context, err error) bool {
	if err == nil {
		return false
	}
	return ctx.Err() != nil || errors.Is(err, context.Canceled)
}

// transportError turns a dial or TLS failure into something actionable. "connection
// refused" on its own does not say which address was tried or how it was chosen.
func (c *apiClient) transportError(method, path string, err error) error {
	if errors.Is(err, context.Canceled) {
		return context.Canceled
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return fmt.Errorf("%s %s timed out after %s; raise --timeout, or check that %s is reachable from here", method, path, c.timeout, c.base)
	}
	return fmt.Errorf("cannot reach the controller at %s: %w\n"+
		"  check that it is running, that --url (or ZOOMIES_URL) is right, and that nothing between you and it is blocking the port", c.base, err)
}

// parseAPIError decodes the error envelope every route returns.
func parseAPIError(method, path string, status int, raw []byte) error {
	e := &apiError{status: status, method: method, path: path}
	var envelope struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
			Field   string `json:"field"`
			Detail  string `json:"detail"`
		} `json:"error"`
		Errors []struct {
			Field   string `json:"field"`
			Message string `json:"message"`
		} `json:"errors"`
	}
	if err := json.Unmarshal(raw, &envelope); err == nil {
		e.code = envelope.Error.Code
		e.message = envelope.Error.Message
		e.field = envelope.Error.Field
		e.detail = envelope.Error.Detail
		e.fields = envelope.Errors
	}
	if e.message == "" {
		// Not our envelope at all: a proxy's error page, most likely. Show a
		// little of it, because "502" without the body is a mystery.
		body := strings.TrimSpace(string(raw))
		if len(body) > 200 {
			body = body[:200] + "…"
		}
		e.message = fmt.Sprintf("%s %s answered %d %s", method, path, status, http.StatusText(status))
		if body != "" {
			e.detail = body
		}
	}
	return e
}

// ---------------------------------------------------------------------------
// Server-Sent Events
// ---------------------------------------------------------------------------

// sseFrame is one event off a stream.
type sseFrame struct {
	event string
	data  []byte
}

// readSSE parses an event stream and calls fn for each complete frame. It
// returns when the stream ends, when fn returns an error, or when the reader is
// closed under it -- which is what cancelling the context does.
//
// bufio.Reader rather than Scanner because a single line of a build's output
// can be longer than Scanner's maximum token, and a log tail that stops on the
// one interesting line would be worse than useless.
func readSSE(r io.Reader, fn func(sseFrame) error) error {
	br := bufio.NewReaderSize(r, 64<<10)
	var frame sseFrame
	var data bytes.Buffer

	for {
		line, err := br.ReadString('\n')
		if line != "" {
			line = strings.TrimRight(line, "\r\n")
			switch {
			case line == "":
				// Blank line: the frame is complete.
				if frame.event != "" || data.Len() > 0 {
					frame.data = bytes.Clone(data.Bytes())
					if ferr := fn(frame); ferr != nil {
						return ferr
					}
				}
				frame = sseFrame{}
				data.Reset()
			case strings.HasPrefix(line, ":"):
				// A comment, which is how the server keeps the connection warm.
			case strings.HasPrefix(line, "event:"):
				frame.event = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
			case strings.HasPrefix(line, "data:"):
				if data.Len() > 0 {
					data.WriteByte('\n')
				}
				data.WriteString(strings.TrimPrefix(strings.TrimPrefix(line, "data:"), " "))
			}
		}
		if err != nil {
			if !errors.Is(err, io.EOF) {
				return err
			}
			// A stream that ends without a final blank line still has a frame
			// worth delivering: the last chunk of a job's output should not be
			// lost because the connection closed a byte early.
			if frame.event != "" || data.Len() > 0 {
				frame.data = bytes.Clone(data.Bytes())
				return fn(frame)
			}
			return nil
		}
	}
}

