// discardLogger keeps the key-generation warning out of the test output while
// still exercising the code path that emits it.
func discardLogger() *slog.Logger {
	return slog.New(slog.NewTextHandler(io.Discard, nil))
}

// secretShaped reports whether a `yaml` name reads like something that must
// never be printed. A path to a secret is not a secret: an operator debugging
// a deployment needs to see which file the key is read from, and printing that
// discloses nothing, so anything ending in _file is deliberately out.
//
// The word list is the weak point, and agent.registry_auth is what proved it:
// a base64 registry credential whose name holds none of secret, token, key or
// password, so this test called it harmless and `config print` disclosed it in
// full, as did every backup manifest. auth and credential are here for that.
// The lesson generalises past the two words -- a credential is not obliged to
// be named like one -- so a new secret-bearing field is worth a thought here
// rather than a hope that its name happens to match.
func secretShaped(name string) bool {
	if strings.HasSuffix(name, "_file") {
		return false
	}
	for _, word := range []string{"secret", "token", "key", "password", "passphrase", "auth", "credential"} {
		if strings.Contains(name, word) {
			return true
		}
	}
	return false
}

// blankSecrets is a hand-written list of fields, and the capacity-demand
// signing secret shows what that costs: it was added to the configuration and
// not to the list, so `zoomies config print` disclosed it for as long as the
// feature has existed. Nobody notices a field that is missing from a list.
//
// So this test does not check the list. It walks the whole configuration by
// reflection, puts a distinctive value in every string field whose name reads
// like a secret, and asserts that none of those values survives the blanking
// anywhere in the output. A secret added tomorrow fails here on the day it is
// added, and a secret copied into some other field fails too, which checking
// the fields one by one would not catch.
func TestEverySecretShapedFieldIsBlanked(t *testing.T) {
	var cfg config.Config
	planted := map[string]string{}
	plant(t, reflect.ValueOf(&cfg).Elem(), "", planted)
	if len(planted) < 5 {
		t.Fatalf("the walk found %d secret-shaped fields, which is fewer than the configuration has: %v", len(planted), planted)
	}

	printed, err := yaml.Marshal(blankSecrets(&cfg))
	if err != nil {
		t.Fatalf("marshalling the blanked configuration: %v", err)
	}
	for path, value := range planted {
		if strings.Contains(string(printed), value) {
			t.Errorf("%s was printed in full; add it to blankSecrets", path)
		}
	}
	// And the operator can still tell that one is set, which is the whole
	// reason the placeholder is not an empty string.
	if !strings.Contains(string(printed), secretPlaceholder) {
		t.Errorf("nothing says a secret is configured:\n%s", printed)
	}
}

// plant fills every secret-shaped string field with a value naming its own
// path, so a failure says which field leaked rather than only that one did.
func plant(t *testing.T, v reflect.Value, prefix string, into map[string]string) {
	t.Helper()
	if v.Kind() != reflect.Struct {
		return
	}
	for i := range v.NumField() {
		f := v.Type().Field(i)
		if !f.IsExported() {
			continue
		}
		name, _, _ := strings.Cut(f.Tag.Get("yaml"), ",")
		if name == "" || name == "-" {
			continue
		}
		path := name
		if prefix != "" {
			path = prefix + "." + name
		}
		field := v.Field(i)
		switch field.Kind() {
		case reflect.Struct:
			plant(t, field, path, into)
		case reflect.Slice:
			// A list of structs is a place secrets hide from a walk that only
			// follows fields: backup.remotes carries an S3 secret and the
			// archive passphrase and was never entered. One element is enough
			// to stand for the list.
			if field.Type().Elem().Kind() == reflect.Struct {
				field.Set(reflect.MakeSlice(field.Type(), 1, 1))
				plant(t, field.Index(0), path+"[0]", into)
			}
		case reflect.String:
			if secretShaped(name) {
				value := "planted-secret-" + strings.ReplaceAll(path, ".", "-")
				field.SetString(value)
				into[path] = value
			}
		}
	}
}

// A restore that brought the database back and left the key behind is
// indistinguishable from a first run at the key file: no file, so generate
// one. The instance that produced would start, report itself healthy, and fail
// inside its first GitHub call with a decryption error nobody could connect to
// the restore that caused it.
func TestAMissingKeyOverASealedDatabaseIsRefusedAtStartup(t *testing.T) {
	dir := isolateHost(t)
	ctx := context.Background()
	st := keyStore(t)
	if err := st.CreateInstallation(ctx, &store.Installation{
		AppID: 1, InstallationID: 2, Target: "acme", TargetType: store.TargetOrg,
		PrivateKeyEnc: []byte("sealed with the key that was not restored"),
	}); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	cfg := config.Default()
	cfg.Security.EncryptionKeyFile = filepath.Join(dir, "encryption.key")

	_, err := loadOrCreateKey(ctx, st, cfg, discardLogger())
	if err == nil {
		t.Fatal("a new key was generated over a database whose secrets only the old one opens")
	}
	// The message has to name the file to put back, because the operator
	// reading it is mid-restore and has the backup open.
	for _, want := range []string{cfg.Security.EncryptionKeyFile, "ZOOMIES_ENCRYPTION_KEY"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not mention %q: %v", want, err)
		}
	}
	if _, serr := os.Stat(cfg.Security.EncryptionKeyFile); !os.IsNotExist(serr) {
		t.Error("a key file was written anyway, so the next start would find one and read nothing")
	}
}

func TestOnlyALoopbackHealthCheckIsMovedToHTTPS(t *testing.T) {
	for in, want := range map[string]string{
		"http://127.0.0.1:8080/healthz": "https://127.0.0.1:8080/healthz",
		"http://[::1]:8080/healthz":     "https://[::1]:8080/healthz",
		"http://localhost:8080/healthz": "https://localhost:8080/healthz",
		// Off the host, plain HTTP is what the operator asked for, and a
		// certificate left unchecked there would be a real risk.
		"http://10.0.0.5:8080/healthz":       "",
		"http://zoomies.example.com/healthz": "",
		"https://127.0.0.1:8080/healthz":     "",
	} {
		got, ok := loopbackHTTPS(in)
		if ok != (want != "") || got != want {
			t.Errorf("loopbackHTTPS(%q) = %q, %v; want %q", in, got, ok, want)
		}
	}
}

// TestConfigPrintBlanksBackupRemoteSecretsWithoutMutatingTheConfig covers the
// one list of structs in the configuration.
//
// A backup remote carries the bucket's secret key and the passphrase that seals
// every offsite copy, so together they open the whole fleet's database, and
// `config print` is the command whose output gets pasted into an issue. The
// copy blankSecrets returns shares its slice with the configuration it was
// given, so blanking in place would also have blanked the live one.
func TestConfigPrintBlanksBackupRemoteSecretsWithoutMutatingTheConfig(t *testing.T) {
	cfg := config.Default()
	cfg.Backup.Remotes = []config.BackupRemote{{
		Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "zoomies-backups",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "bucket-secret-value", Passphrase: "archive-passphrase-value",
	}}

	for _, format := range []string{"yaml", "json"} {
		var printed []byte
		var err error
		if format == "yaml" {
			printed, err = yaml.Marshal(blankSecrets(cfg))
		} else {
			printed, err = json.Marshal(blankSecrets(cfg))
		}
		if err != nil {
			t.Fatalf("marshalling as %s: %v", format, err)
		}
		for _, leaked := range []string{"bucket-secret-value", "archive-passphrase-value", "AKIAEXAMPLE"} {
			if strings.Contains(string(printed), leaked) {
				t.Errorf("%s output printed %q:\n%s", format, leaked, printed)
			}
		}
		// What an operator debugging a destination needs is still there.
		for _, kept := range []string{"offsite", "https://s3.example.com", "zoomies-backups", secretPlaceholder} {
			if !strings.Contains(string(printed), kept) {
				t.Errorf("%s output lost %q:\n%s", format, kept, printed)
			}
		}
	}

	got := cfg.Backup.Remotes[0]
	if got.SecretAccessKey != "bucket-secret-value" || got.Passphrase != "archive-passphrase-value" || got.AccessKeyID != "AKIAEXAMPLE" {
		t.Errorf("blankSecrets blanked the caller's configuration as well: %+v", got)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
	"text/tabwriter"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/installer"
	"github.com/eyupio/zoomies/internal/store"
)

// `zoomies config get|set|unset|list`: the fleet's settings, from a terminal.
//
// The settings page is where these are normally changed. This exists for the
// two moments when it is not reachable: a stored value that stops the
// controller starting, and a stored value that binds it somewhere nobody can
// get to. Both are recoverable through an environment variable, which is the
// layer above the database -- but a variable is a workaround that has to be
// remembered at every restart, and this is the fix.
//
// It works on a stopped controller. A running one holds the database lock, and
// writing settings under a process that has already read them would leave that
// process and the row disagreeing with no way for either to know.

// openForSettings loads the configuration far enough to open the database and
// the key that unseals what is in it, which is all these commands need.
func openForSettings(ctx context.Context, cfgPath string) (*config.Config, *store.Store, *cryptox.Key, func(), error) {
	cfg, err := config.Load(cfgPath)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	unlock, err := store.Lock(cfg.Database.Path)
	if err != nil {
		if errors.Is(err, store.ErrLocked) {
			return nil, nil, nil, nil, fmt.Errorf(
				"a controller is running against %s, and it has already read the settings this would change; "+
					"stop it first, or change the setting on the settings page", cfg.Database.Path)
		}
		return nil, nil, nil, nil, err
	}
	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path})
	if err != nil {
		_ = unlock()
		return nil, nil, nil, nil, err
	}
	// A missing key is not fatal here: everything but a credential can still be
	// read and written without one, and refusing the whole command would take
	// away the tool somebody uses when the key is the thing that is wrong.
	key, _ := loadSettingsKey(cfg)
	return cfg, st, key, func() { st.Close(); _ = unlock() }, nil
}

func loadSettingsKey(cfg *config.Config) (*cryptox.Key, error) {
	if raw := strings.TrimSpace(cfg.Security.EncryptionKey); raw != "" {
		return cryptox.ParseKey(raw)
	}
	if path := strings.TrimSpace(cfg.Security.EncryptionKeyFile); path != "" {
		return cryptox.LoadKeyFile(path)
	}
	return nil, os.ErrNotExist
}

// effective assembles the configuration the way the controller does, so these
// commands answer about what a controller would actually run rather than about
// one layer of it.
func effective(ctx context.Context, cfg *config.Config, st *store.Store, key *cryptox.Key) ([]store.InstanceSetting, error) {
	rows, err := st.InstanceSettings(ctx)
	if err != nil {
		return nil, err
	}
	if _, err := cfg.Rebuild(rows, key); err != nil {
		return nil, err
	}
	return rows, nil
}

func runConfigList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config list [--config path] [--all]",
		"List what this fleet has stored. --all lists every setting, including the ones nobody has changed.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	all := fs.Bool("all", false, "list every setting, not only the ones with a value")
	fs.example("zoomies config list", "zoomies config list --all")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	cfg, st, key, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, key); err != nil {
		return err
	}

	w := tabwriter.NewWriter(e.out, 0, 0, 2, ' ', 0)
	fmt.Fprintln(w, "SETTING\tVALUE\tFROM")
	shown := 0
	for _, s := range config.Settings() {
		source := cfg.Source(s.Key)
		if !*all && source == config.SourceDefault {
			continue
		}
		value, err := cfg.Value(s.Key)
		if err != nil {
			continue
		}
		text := config.Text(s, value)
		if s.Secret {
			text = secretPlaceholder
			if text == "" {
				text = "(not set)"
			}
		}
		if text == "" {
			text = "(not set)"
		}
		fmt.Fprintf(w, "%s\t%s\t%s\n", s.Key, text, source)
		shown++
	}
	if err := w.Flush(); err != nil {
		return err
	}
	if shown == 0 {
		fmt.Fprintln(e.out, "Nothing is set: this fleet is running on the defaults.")
	}
	return nil
}

func runConfigGet(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config get <key> [--config path]",
		"Print one setting's effective value, and which layer it came from.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config get server.bind")
	if err := fs.parse(args); err != nil {
		return err
	}
	key, err := fs.oneArg("a setting, for example server.bind")
	if err != nil {
		return err
	}
	setting, ok := config.LookupSetting(key)
	if !ok {
		return usagef("config get", "%q is not a setting this version has; `zoomies config list --all` lists them", key)
	}

	cfg, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, encKey); err != nil {
		return err
	}

	value, err := cfg.Value(key)
	if err != nil {
		return err
	}
	if setting.Secret {
		if config.Text(setting, value) == "" {
			fmt.Fprintln(e.out, "(not set)")
		} else {
			fmt.Fprintln(e.out, secretPlaceholder)
		}
	} else {
		fmt.Fprintln(e.out, config.Text(setting, value))
	}
	fmt.Fprintf(e.err, "%s -- %s\nfrom: %s\n", setting.Label, setting.Summary, sourceSentence(cfg, setting))
	return nil
}

// sourceSentence says where a value came from in a way that names what to
// change, because "environment" on its own leaves somebody looking for which
// variable.
func sourceSentence(cfg *config.Config, s config.Setting) string {
	switch cfg.Source(s.Key) {
	case config.SourceEnvironment:
		return s.Env + " in the environment, which overrides both the database and the file"
	case config.SourceDatabase:
		return "this fleet's database"
	case config.SourceFile:
		if p := cfg.Path(); p != "" {
			return p
		}
		return "the configuration file"
	default:
		return "the built-in default"
	}
}

func runConfigSet(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config set <key> <value> [--config path]",
		"Store one setting in this fleet's database. The controller must be stopped.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example(
		"zoomies config set server.bind 127.0.0.1:8080",
		"zoomies config set oidc.scopes openid,profile,email",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	rest, err := fs.atLeastOneArg("a setting and its value, for example server.bind 127.0.0.1:8080")
	if err != nil {
		return err
	}
	if len(rest) != 2 {
		return usagef("config set", "takes a setting and one value; quote a value that contains spaces")
	}
	key, raw := rest[0], rest[1]

	setting, ok := config.LookupSetting(key)
	if !ok {
		return usagef("config set", "%q is not a setting this version has; `zoomies config list --all` lists them", key)
	}
	if !setting.Stored() {
		return usagef("config set", "%s cannot live in the database -- %s; set it in the configuration file or as %s",
			key, scopeReason(setting), setting.Env)
	}

	cfg, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()
	if _, err := effective(ctx, cfg, st, encKey); err != nil {
		return err
	}

	// Parsed against a copy first, so a value that will not do stops here
	// rather than in the next start.
	candidate := *cfg
	candidate.SetSources(cfg.Sources())
	if _, err := candidate.SetValueString(key, raw); err != nil {
		return err
	}
	parsed, err := candidate.Value(key)
	if err != nil {
		return err
	}
	row, err := config.EncodeStored(setting, parsed, encKey)
	if err != nil {
		return err
	}
	if err := st.PutInstanceSettings(ctx, "zoomies config set", []store.InstanceSetting{row}); err != nil {
		return err
	}

	fmt.Fprintf(e.out, "%s is now %s.\n", setting.Key, displayFor(setting, parsed))
	if cfg.Source(key) == config.SourceEnvironment {
		fmt.Fprintf(e.err, "It will not take effect while %s is set in the environment, which overrides the database.\n", setting.Env)
	} else if !setting.Live {
		fmt.Fprintln(e.err, "It takes effect when the controller next starts.")
	}
	return nil
}

func runConfigUnset(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config unset <key> [--config path]",
		"Forget a stored setting, so the configuration file or the built-in default decides it again.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config unset server.bind")
	if err := fs.parse(args); err != nil {
		return err
	}
	key, err := fs.oneArg("a setting, for example server.bind")
	if err != nil {
		return err
	}
	if _, ok := config.LookupSetting(key); !ok {
		return usagef("config unset", "%q is not a setting this version has; `zoomies config list` lists what is stored", key)
	}

	_, st, _, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()

	if _, err := st.GetInstanceSetting(ctx, key); errors.Is(err, store.ErrNotFound) {
		fmt.Fprintf(e.out, "%s was not stored, so nothing changed.\n", key)
		return nil
	} else if err != nil {
		return err
	}
	if err := st.DeleteInstanceSettings(ctx, []string{key}); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "%s is no longer stored; the configuration file or the built-in default decides it now.\n", key)
	return nil
}

func scopeReason(s config.Setting) string {
	switch s.Scope {
	case config.ScopeBootstrap:
		return "it is read before the database can be opened"
	case config.ScopeLocal:
		return "it belongs to a standalone agent's own host"
	default:
		return "it is not a setting this fleet stores"
	}
}

func displayFor(s config.Setting, value any) string {
	if s.Secret {
		return secretPlaceholder
	}
	text := config.Text(s, value)
	if text == "" {
		return "empty"
	}
	return text
}

// runConfigImportEnv stores every setting an environment file sets, in one
// write.
//
// It is how a container deployment's settings leave its .env: the installer
// runs it in a one-off container of the new image, against the deployment's
// volume, with the variables on standard input -- never as arguments, which
// any process on the host can read. It is also the command an operator runs
// by hand on an .env of their own. Anything in the file that cannot live in
// the database -- the encryption key, the database path, Compose's own
// variables -- is left alone and named, so nothing is silently dropped.
func runConfigImportEnv(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies config import-env [file] [--config path]",
		"Store the settings an environment file sets in this fleet's database. Reads standard input when no file, or -, is given. The controller must be stopped.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	fs.example("zoomies config import-env /opt/zoomies/.env", "zoomies config import-env < .env")
	if err := fs.parse(args); err != nil {
		return err
	}
	rest := fs.Args()
	if len(rest) > 1 {
		return usagef("config import-env", "takes at most one file")
	}
	var vars map[string]string
	var err error
	if len(rest) == 0 || rest[0] == "-" {
		if e.in == nil {
			return usagef("config import-env", "give a file, or the variables on standard input")
		}
		vars, err = installer.ParseEnv(e.in)
	} else {
		vars, err = installer.ParseEnvFile(rest[0])
	}
	if err != nil {
		return err
	}

	_, st, encKey, done, err := openForSettings(ctx, *cfgPath)
	if err != nil {
		return err
	}
	defer done()

	rows, imported, left, err := config.ImportEnvironment(vars, encKey)
	if err != nil {
		return err
	}
	if len(rows) > 0 {
		if err := st.PutInstanceSettings(ctx, "zoomies config import-env", rows); err != nil {
			return err
		}
	}
	for _, im := range imported {
		value := im.Text
		switch {
		case im.Setting.Secret:
			value = secretPlaceholder
		case value == "":
			value = "empty"
		}
		fmt.Fprintf(e.out, "%s is now %s (from %s)\n", im.Setting.Key, value, im.Env)
	}
	for _, name := range left {
		fmt.Fprintf(e.err, "left %s where it is: it is not a setting this fleet stores\n", name)
	}
	if len(imported) == 0 {
		fmt.Fprintln(e.out, "Nothing to store: the file sets no setting that lives in the database.")
	}
	return nil
}

package main

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/cryptox"
)

// settingsHost prepares a state directory with a configuration file, so a test
// can run `zoomies config …` against a real database the way an operator does.
func settingsHost(t *testing.T, body string) string {
	t.Helper()
	dir := isolateHost(t)
	path := filepath.Join(dir, "zoomies.yaml")
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	t.Setenv("ZOOMIES_STATE_DIR", dir)
	t.Setenv("ZOOMIES_CONFIG_DIR", dir)
	return path
}

// The command an operator reaches for when the settings page is the thing that
// is broken: a stored bind address nothing can connect to.
//
// It is the fix rather than the workaround. The environment layer already wins
// over the database, so a bad value is always recoverable by exporting a
// variable -- but a variable has to be remembered at every restart, and this
// puts the database right.
func TestConfigSetStoresASettingWithoutAControllerRunning(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, out, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"server.bind", "127.0.0.1:9999", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}
	if !strings.Contains(out.String(), "server.bind is now 127.0.0.1:9999") {
		t.Errorf("config set said: %q", out.String())
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigGet(ctx, e, []string{"server.bind", "--config", path}); err != nil {
		t.Fatalf("config get: %v", err)
	}
	if got := strings.TrimSpace(out.String()); got != "127.0.0.1:9999" {
		t.Errorf("config get printed %q", got)
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigUnset(ctx, e, []string{"server.bind", "--config", path}); err != nil {
		t.Fatalf("config unset: %v", err)
	}
	if !strings.Contains(out.String(), "no longer stored") {
		t.Errorf("config unset said: %q", out.String())
	}
}

// A key that is read before the database opens cannot be stored in it, and the
// refusal says where to put it instead -- because an operator who has just been
// told "no" is about to go looking for the right place.
func TestConfigSetRefusesAKeyThatOpensTheDatabase(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e, []string{"database.path", "/tmp/elsewhere.db", "--config", path})
	if err == nil {
		t.Fatal("database.path was stored in the database it names")
	}
	for _, want := range []string{"before the database can be opened", "ZOOMIES_DB_PATH"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not mention %q: %v", want, err)
		}
	}
}

// A value that will not parse stops at the command rather than at the next
// start, when whoever typed it is no longer watching.
func TestConfigSetRefusesAValueThatWillNotParse(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e, []string{"scheduler.interval", "soon", "--config", path})
	if err == nil {
		t.Fatal("a nonsense duration was stored")
	}
	if !strings.Contains(err.Error(), "is not a duration") {
		t.Errorf("the refusal does not say what was wrong: %v", err)
	}
}

// The listing says where each value came from, which is the question that
// makes a configuration problem hard: a value in the file and a value in the
// environment are identical once the process is running.
func TestConfigListSaysWhereEachValueCameFrom(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+
		"\nscheduler:\n  interval: 25s\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"retention.jobs", "720h", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}

	t.Setenv("ZOOMIES_LOG_LEVEL", "debug")
	e, out, _ := newTestEnv(t)
	if err := runConfigList(ctx, e, []string{"--config", path}); err != nil {
		t.Fatalf("config list: %v", err)
	}
	text := out.String()
	for _, want := range []string{
		"scheduler.interval", "25s", "file",
		"retention.jobs", "720h", "database",
		"log.level", "debug", "environment",
	} {
		if !strings.Contains(text, want) {
			t.Errorf("the listing does not mention %q:\n%s", want, text)
		}
	}
}

// A credential is never printed, and the listing still says one is set --
// which is the fact an operator debugging a configuration actually needs.
func TestConfigCommandsNeverPrintACredential(t *testing.T) {
	dir := t.TempDir()
	keyFile := filepath.Join(dir, "encryption.key")
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	if err := cryptox.WriteKeyFile(keyFile, key); err != nil {
		t.Fatalf("WriteKeyFile: %v", err)
	}
	path := settingsHost(t, "database:\n  path: "+filepath.Join(dir, "z.db")+
		"\nsecurity:\n  encryption_key_file: "+keyFile+"\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	if err := runConfigSet(ctx, e, []string{"capacity_demand.signing_secret", "hunter2", "--config", path}); err != nil {
		t.Fatalf("config set: %v", err)
	}

	for _, run := range []func() string{
		func() string {
			e, out, _ := newTestEnv(t)
			_ = runConfigList(ctx, e, []string{"--config", path})
			return out.String()
		},
		func() string {
			e, out, _ := newTestEnv(t)
			_ = runConfigGet(ctx, e, []string{"capacity_demand.signing_secret", "--config", path})
			return out.String()
		},
	} {
		text := run()
		if strings.Contains(text, "hunter2") {
			t.Errorf("a credential was printed:\n%s", text)
		}
		if !strings.Contains(text, secretPlaceholder) {
			t.Errorf("nothing says the credential is set:\n%s", text)
		}
	}
}

// Setting a credential before there is a key to seal it with is refused, and
// the refusal says what to do. Generating a key here would be the wrong tool
// doing it: only the controller knows whether the database already holds
// something sealed with a different one, and minting a second key over that
// leaves an instance that starts, looks healthy, and cannot read its own
// GitHub credentials.
func TestConfigSetRefusesACredentialWithNoKeyToSealItWith(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")

	e, _, _ := newTestEnv(t)
	err := runConfigSet(context.Background(), e,
		[]string{"capacity_demand.signing_secret", "hunter2", "--config", path})
	if err == nil {
		t.Fatal("a credential was stored with nothing to seal it")
	}
	if !strings.Contains(err.Error(), "encryption key") {
		t.Errorf("the refusal does not name what is missing: %v", err)
	}
}

// The upgrade hands a deployment's variables to a one-off container on
// standard input, and this is what stores them. Every setting lands in the
// database; the variables that cannot live there are named and left.
func TestConfigImportEnvStoresWhatAnEnvFileSets(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, out, errOut := newTestEnv(t)
	e.in = strings.NewReader("ZOOMIES_BIND=0.0.0.0:8080\nZOOMIES_AGENT_CAPACITY=6\nZOOMIES_IMAGE=ghcr.io/eyupio/zoomies:v1\nDOCKER_GID=998\n")
	if err := runConfigImportEnv(ctx, e, []string{"--config", path}); err != nil {
		t.Fatalf("config import-env: %v", err)
	}
	for _, want := range []string{"server.bind is now 0.0.0.0:8080 (from ZOOMIES_BIND)", "agent.capacity is now 6 (from ZOOMIES_AGENT_CAPACITY)"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("output does not say %q:\n%s", want, out.String())
		}
	}
	if !strings.Contains(errOut.String(), "left ZOOMIES_IMAGE") || strings.Contains(errOut.String(), "DOCKER_GID") {
		t.Errorf("stderr = %q, want ZOOMIES_IMAGE named and Compose's own variables not", errOut.String())
	}

	e, out, _ = newTestEnv(t)
	if err := runConfigGet(ctx, e, []string{"agent.capacity", "--config", path}); err != nil {
		t.Fatalf("config get: %v", err)
	}
	if got := strings.TrimSpace(out.String()); got != "6" {
		t.Errorf("agent.capacity = %q after the import, want 6", got)
	}
}

// One value the controller could not run with stores nothing at all.
func TestConfigImportEnvStoresNothingWhenAValueIsWrong(t *testing.T) {
	path := settingsHost(t, "database:\n  path: "+filepath.Join(t.TempDir(), "z.db")+"\n")
	ctx := context.Background()

	e, _, _ := newTestEnv(t)
	e.in = strings.NewReader("ZOOMIES_BIND=0.0.0.0:8080\nZOOMIES_AGENT_CAPACITY=lots\n")
	if err := runConfigImportEnv(ctx, e, []string{"--config", path}); err == nil || !strings.Contains(err.Error(), "ZOOMIES_AGENT_CAPACITY") {
		t.Fatalf("err = %v, want a refusal naming the variable", err)
	}
	e, out, _ := newTestEnv(t)
	if err := runConfigList(ctx, e, []string{"--config", path}); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out.String(), "server.bind") {
		t.Errorf("server.bind was stored although the import was refused:\n%s", out.String())
	}
}

