// stopGrace must outlast the embedded agent's admitted create, cleanup and
// result reporting. Exiting sooner can strand a DinD sidecar halfway through
// creation. Existing CI jobs keep running; only lifecycle tasks are awaited.
const stopGrace = agent.ShutdownTimeout + time.Minute

// runController is `zoomies controller`: the control plane, the API, the UI,
// the webhook endpoint and -- unless agent.embedded is false -- an agent.
func runController(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies controller [--config path]",
		"Run the control plane: the scheduler, the API, the web UI and the webhook endpoint.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+", and a missing file is not an error)")
	takeover := fs.Bool("takeover", false, "start even though another controller holds this database's lease, and take it from them")
	fs.example(
		"zoomies controller --config /etc/zoomies/zoomies.yaml",
		"ZOOMIES_BIND=0.0.0.0:8080 zoomies controller     # no file at all: defaults plus environment",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}

	cfg, err := config.Load(*cfgPath)
	if err != nil {
		return err
	}

	// The configuration is not validated yet, and cannot be: most of it lives
	// in the database, and the database is not open. What Load has produced so
	// far is enough to open it -- the path, and the key that unseals what is
	// inside -- and the whole configuration is assembled and checked below,
	// once both are in hand. A file that fails to parse still stops here,
	// because that is a fault in the one layer this early step does read.

	log, level := setupLogging(cfg)
	startFormat := cfg.Log.Format

	// One controller per database, checked before the store opens.
	//
	// Two schedulers over one database both mint runner credentials, both
	// reclaim hosts they think are lost, and both reap the workloads the other
	// created; every symptom of it looks like a bug somewhere else. The lock
	// catches a second process on this host and the lease catches a copy on a
	// shared filesystem or another machine, which no lock here can see.
	unlock, err := store.Lock(cfg.Database.Path)
	if err != nil {
		if errors.Is(err, store.ErrLocked) {
			return fmt.Errorf("another controller is already running against %s on this host; "+
				"stop it before starting this one", cfg.Database.Path)
		}
		return err
	}
	defer func() { _ = unlock() }()

	// A restore staged from the settings page is applied here, in the gap
	// between the last controller closing the database and this one opening
	// it. The lock above is what makes the gap real: nothing else has the
	// file. Whatever the outcome, this controller then starts -- on the
	// restored database, or on the one it had, with the reason recorded for
	// the page to show.
	if err := applyStagedRestore(ctx, cfg, log); err != nil {
		return err
	}

	st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path})
	if err != nil {
		return err
	}
	defer st.Close()

	lease, err := takeControllerLease(ctx, st, *takeover)
	if err != nil {
		return err
	}
	defer func() {
		// Handed back on a clean stop so the next controller starts at once
		// rather than waiting out a lease nobody holds.
		if err := st.ReleaseControllerLease(context.WithoutCancel(ctx), lease.Holder); err != nil {
			log.Warn("could not hand the controller lease back", "error", err)
		}
	}()

	key, err := loadOrCreateKey(ctx, st, cfg, log)
	if err != nil {
		return err
	}

	// Now the whole configuration exists: the file underneath, this fleet's
	// own settings over it, and the environment over both. Everything from
	// here reads the assembled thing.
	seeded, err := seedSettingsFromFile(ctx, st, cfg, key, log)
	if err != nil {
		return err
	}
	stored, err := st.InstanceSettings(ctx)
	if err != nil {
		return err
	}
	storedFindings, err := cfg.Rebuild(stored, key)
	if err != nil {
		return err
	}
	applyLogLevel(level, cfg)
	if cfg.Log.Format != startFormat {
		// The format is chosen before the database is open, so one stored
		// there -- where a container deployment keeps it -- takes over here,
		// from the first line that says what the configuration is.
		log, level = setupLogging(cfg)
	}

	log.Info("configuration assembled",
		"file", configSource(cfg), "stored", len(stored), "pinned_by_environment", len(cfg.PinnedByEnvironment()))

	findings := append(storedFindings, seeded...)
	findings = append(findings, cfg.Validate()...)
	printFindings(e.err, findings)
	if err := findings.Err(); err != nil {
		return err
	}

	// The registry is built only for an embedded agent. A controller that runs
	// no runners itself has no business probing this host's Docker socket, and
	// building one anyway would produce backend warnings about a host that is
	// never going to start a container.
	var backends *backend.Registry
	if cfg.Agent.Embedded {
		backends, err = buildBackends(ctx, cfg, log)
		if err != nil {
			return err
		}
	}

	providers, err := buildProviders()
	if err != nil {
		return err
	}

	ctrl, err := controller.New(controller.Options{
		Store:     st,
		Config:    cfg,
		Key:       key,
		Backends:  backends,
		Providers: providers,
		Logger:    log,
		LogLevel:  level,
		Lease:     lease,
	})
	if err != nil {
		return err
	}

	srv, err := api.New(api.Options{Controller: ctrl, Logger: log})
	if err != nil {
		return err
	}

	// SIGHUP re-reads the log level and nothing else. Everything else in the
	// configuration is either safe to change through PATCH /settings or needs
	// the process restarted, and pretending otherwise -- rebinding a listener
	// under live connections, say -- is how a reload becomes an outage. The
	// level goes through the controller's live configuration, the same way a
	// PATCH does, so the settings page shows the level the process is at.
	stopHUP := watchSIGHUP(ctx, *cfgPath, func(level string) string {
		var previous string
		ctrl.UpdateConfig(func(c *config.Config) { previous, c.Log.Level = c.Log.Level, level })
		return previous
	}, log)
	defer stopHUP()

	if err := ctrl.Start(ctx); err != nil {
		return err
	}
	// Stop runs on every path out, including a failed listen. It shuts the
	// loops down without touching a single runner: restarting a controller
	// must never kill somebody's build.
	defer func() {
		shutdownCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), stopGrace)
		defer cancel()
		if err := ctrl.Stop(shutdownCtx); err != nil {
			log.Warn("the controller did not shut down cleanly", "error", err)
		}
	}()

	if cfg.Agent.Embedded {
		if err := ctrl.StartEmbeddedAgent(ctx, cfg); err != nil {
			return fmt.Errorf("starting the embedded agent: %w (set agent.embedded to false to run a controller that hosts no runners)", err)
		}
	}

	printBanner(e.out, cfg, backends)
	// The environment's first account is made before the setup token is
	// considered, so an instance that bootstrapped itself never prints a
	// token nobody needs.
	if err := ctrl.BootstrapFromEnvironment(ctx); err != nil {
		return err
	}
	printSetupToken(ctx, e.out, ctrl, log)

	// The settings page can ask this process to stop so that its service
	// manager starts the next one, which is how a staged restore is applied.
	// The request cancels the listener's context exactly as a signal would,
	// and the exit code says which it was.
	serveCtx, stopServing := context.WithCancel(ctx)
	defer stopServing()
	go func() {
		select {
		case <-ctrl.RestartRequested():
			stopServing()
		case <-serveCtx.Done():
		}
	}()
	err = srv.ListenAndServe(serveCtx)
	if restarting, reason := ctrl.Restarting(); restarting {
		if err != nil {
			log.Warn("the listener did not stop cleanly on the way to a restart", "error", err)
		}
		return &restartRequested{reason: reason}
	}
	return err
}

// applyStagedRestore performs the restore the settings page staged, if there
// is one, and says what happened in the log -- loudly, because a database
// changing hands is the one startup event an operator reading the log later
// must not be able to miss.
func applyStagedRestore(ctx context.Context, cfg *config.Config, log *slog.Logger) error {
	staged, err := backup.LoadStaged(cfg.Database.Path)
	if err != nil {
		return err
	}
	if staged == nil {
		return nil
	}
	log.Warn("applying a restore staged from the settings page", "restore", describeStaged(staged))
	outcome, err := backup.ApplyStaged(ctx, cfg, nil)
	if err != nil {
		return err
	}
	if outcome == nil {
		return nil
	}
	if !outcome.OK {
		log.Error("the staged restore did not finish; the error says which database this controller is starting on",
			"backup", outcome.BackupID, "error", outcome.Error,
			"fix", "put right what the error names and stage the restore again from the Backups tab")
		return nil
	}
	log.Warn("restored the database from a backup; this fleet is fenced until an administrator lifts it",
		"backup", outcome.BackupID, "moved_aside", outcome.Report.MovedAside)
	for _, line := range outcome.Report.Invalidated {
		log.Info(line)
	}
	return nil
}

// restartRequested is the error a controller returns when it stopped because
// the settings page asked it to: not a failure, but not a clean exit either,
// because a service manager set to restart on failure has to see a non-zero
// code to bring it back.
type restartRequested struct{ reason string }

func (e *restartRequested) Error() string {
	return "stopped for a restart: " + e.reason
}

// takeControllerLease claims this database for this controller, or refuses to
// start and says who has it.
//
// The message is the whole point of the lease: an operator who has just been
// refused needs to know which machine to go and look at, and "the database is
// locked" would send them to the wrong one.
func takeControllerLease(ctx context.Context, st *store.Store, takeover bool) (*store.ControllerLease, error) {
	host, _ := os.Hostname()
	lease := &store.ControllerLease{
		Holder:  store.NewID(store.PrefixController),
		Host:    host,
		PID:     os.Getpid(),
		Version: version.Version,
	}
	held, err := st.AcquireControllerLease(ctx, lease, controller.LeaseTTL, takeover)
	if errors.Is(err, store.ErrConflict) {
		return nil, fmt.Errorf("another controller holds this database: %s, last seen %s ago. "+
			"Stop it, or start this one with --takeover if you know it is gone",
			held.Describe(), time.Since(held.RenewedAt).Round(time.Second))
	}
	if err != nil {
		return nil, fmt.Errorf("taking the controller lease: %w", err)
	}
	return lease, nil
}

// ---------------------------------------------------------------------------
// Logging
// ---------------------------------------------------------------------------

// setupLogging installs the process logger and returns the level it is filtered
// at, so that SIGHUP can move it without rebuilding every logger the controller
// and the API have already captured.
// applyLogLevel re-tunes the gate after the configuration has been assembled.
//
// The level is set once before the store opens, because the store's own startup
// has things to say and there is nowhere else to say them. That first setting
// can only know the file and the environment, so it has to be made again once
// the layer between them has been read -- otherwise the one setting the
// registry calls live is the one a fresh start ignores.
func applyLogLevel(level *slog.LevelVar, cfg *config.Config) {
	level.Set(config.ParseLogLevel(cfg.Log.Level))
}

func setupLogging(cfg *config.Config) (*slog.Logger, *slog.LevelVar) {
	level := new(slog.LevelVar)
	level.Set(config.ParseLogLevel(cfg.Log.Level))

	// The inner handler is built at debug so that it never filters anything
	// out itself; the wrapper below is the only gate, and it is the one whose
	// mind can be changed at runtime.
	inner := logging.Setup(logging.Options{Level: "debug", Format: cfg.Log.Format}).Handler()
	log := slog.New(&levelHandler{Handler: inner, level: level})
	slog.SetDefault(log)
	return log, level
}

// levelHandler gates a handler on a level that can change while the process
// runs. slog.HandlerOptions.Level accepts a Leveler for exactly this, but the
// handler underneath is built by internal/logging, which owns the redaction
// rules; wrapping is how both stay true.
type levelHandler struct {
	slog.Handler
	level *slog.LevelVar
}

func (h *levelHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level.Level() }

func (h *levelHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &levelHandler{Handler: h.Handler.WithAttrs(attrs), level: h.level}
}

func (h *levelHandler) WithGroup(name string) slog.Handler {
	return &levelHandler{Handler: h.Handler.WithGroup(name), level: h.level}
}

// watchSIGHUP re-reads the configuration on SIGHUP and hands the log level from
// it to apply, which sets it and returns the level that was in force. It
// returns a function that stops watching.
func watchSIGHUP(ctx context.Context, cfgPath string, apply func(level string) (previous string), log *slog.Logger) func() {
	hup := make(chan os.Signal, 1)
	signal.Notify(hup, syscall.SIGHUP)

	var once sync.Once
	stop := func() { once.Do(func() { signal.Stop(hup); close(hup) }) }

	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case _, ok := <-hup:
				if !ok {
					return
				}
				fresh, err := config.Load(cfgPath)
				if err != nil {
					log.Error("SIGHUP: the configuration did not re-read, so nothing changed",
						"error", err, "fix", "correct the file and send SIGHUP again")
					continue
				}
				was := config.ParseLogLevel(apply(fresh.Log.Level))
				now := config.ParseLogLevel(fresh.Log.Level)
				if was == now {
					log.Info("SIGHUP: log level re-read and unchanged", "log_level", now.String())
				} else {
					// Logged at the new level's own severity would risk the
					// message being filtered out; Info is always visible at
					// debug and info, and Warn covers the rest.
					log.Warn("SIGHUP: log level changed", "from", was.String(), "to", now.String())
				}
			}
		}
	}()
	return stop
}

// ---------------------------------------------------------------------------
// Keys and backends
// ---------------------------------------------------------------------------

// loadOrCreateKey resolves the instance encryption key, generating one the
// first time.
//
// Generating rather than refusing is deliberate: a first run should work. What
// must not happen is a key appearing silently, so the path it went to and the
// fact that it is the only copy are logged at warning level, once.
//
// It takes the store because "a first run" is a question about the database
// rather than about the key file. A restore that brought the database back and
// left the key behind looks identical from here -- no key file, so generate one
// -- and the instance it produces starts, reports itself healthy, and fails
// inside its first GitHub call with a decryption error. Asking whether anything
// is sealed turns that into a refusal at startup that names the missing file.
func loadOrCreateKey(ctx context.Context, st *store.Store, cfg *config.Config, log *slog.Logger) (*cryptox.Key, error) {
	if raw := strings.TrimSpace(cfg.Security.EncryptionKey); raw != "" {
		key, err := cryptox.ParseKey(raw)
		if err != nil {
			return nil, fmt.Errorf("security.encryption_key (or ZOOMIES_ENCRYPTION_KEY) is not usable: %w", err)
		}
		return key, nil
	}

	path := strings.TrimSpace(cfg.Security.EncryptionKeyFile)
	if path == "" {
		return nil, errors.New("no encryption key: GitHub App private keys and webhook secrets are sealed with one, " +
			"so set security.encryption_key_file to a path this process may write, or pass the key itself in ZOOMIES_ENCRYPTION_KEY")
	}

	key, err := cryptox.LoadKeyFile(path)
	switch {
	case err == nil:
		return key, nil
	case !errors.Is(err, os.ErrNotExist):
		return nil, err
	}

	// The one check that separates a first run from a restore missing its key.
	sealed, serr := st.HasSealedSecrets(ctx)
	if serr != nil {
		return nil, serr
	}
	if sealed {
		return nil, fmt.Errorf("this database holds secrets sealed with an encryption key, and %s does not exist: "+
			"generating a new key here would leave them unreadable. Restore the key file from your backup, "+
			"or pass the key in ZOOMIES_ENCRYPTION_KEY; if the key is genuinely lost, delete and re-add the GitHub installations, "+
			"provider credentials and offsite backup remotes, and have an administrator reset two-step for "+
			"the accounts that have it", path)
	}

	key, err = cryptox.GenerateKey()
	if err != nil {
		return nil, fmt.Errorf("generating an encryption key: %w", err)
	}
	if err := cryptox.WriteKeyFile(path, key); err != nil {
		return nil, fmt.Errorf("writing the new encryption key to %s: %w (set security.encryption_key_file to a path this process may write)", path, err)
	}
	log.Warn("generated a new encryption key",
		"path", path,
		"detail", "it is the only copy, and without it the stored GitHub App private keys, webhook secrets, two-step secrets and backup remote credentials cannot be decrypted",
		"fix", "back up "+path+" now, alongside your database")
	return key, nil
}

// seedSettingsFromFile carries an existing zoomies.yaml into the database, once.
//
// It is the upgrade path. An instance that has been running on a configuration
// file meets this build with an empty settings table, and without this it would
// get a settings page showing every value as "From the file" and offering to
// store a second copy of each one. Instead the file's settings are copied in,
// the file stays as the layer underneath them, and nothing about what the
// controller is running changes -- the operator simply gains the ability to
// change them.
//
// It happens once and leaves a note saying so, in the store's own settings
// table rather than in the fleet's: an operator who then clears every setting
// back to its defaults must not have the file silently poured back in at the
// next start.
func seedSettingsFromFile(ctx context.Context, st *store.Store, cfg *config.Config, key *cryptox.Key, log *slog.Logger) (config.Findings, error) {
	if cfg.Path() == "" {
		return nil, nil
	}
	done, err := st.GetSetting(ctx, config.SeedKey)
	if err != nil {
		return nil, err
	}
	if done != "" {
		return nil, nil
	}
	// A database that already holds settings was configured through the API, so
	// there is nothing to import and the file is not in charge of it.
	if has, err := st.HasInstanceSettings(ctx); err != nil {
		return nil, err
	} else if has {
		return nil, st.SetSetting(ctx, config.SeedKey, "skipped: settings were already stored", false)
	}

	rows, err := config.SeedFromFile(cfg, key)
	if err != nil {
		// A file this process has already parsed cannot fail to parse here, so
		// this is a read error -- worth saying, not worth refusing to start
		// over, since the file is still the layer underneath.
		log.Warn("could not import the configuration file into the database",
			"path", cfg.Path(), "error", err)
		return nil, nil
	}
	if len(rows) == 0 {
		return nil, st.SetSetting(ctx, config.SeedKey, "skipped: the file set nothing that belongs in the database", false)
	}
	if err := st.PutInstanceSettings(ctx, "the configuration file", rows); err != nil {
		return nil, err
	}
	if err := st.SetSetting(ctx, config.SeedKey, cfg.Path(), false); err != nil {
		return nil, err
	}
	log.Info("imported the configuration file into the database",
		"path", cfg.Path(), "settings", len(rows),
		"detail", "they can now be changed on the settings page, and the file remains the layer underneath them")
	return config.Findings{config.SeedFinding(cfg.Path(), len(rows))}, nil
}

// socketExists reports whether a unix socket path is present. A TCP endpoint
// has no path and is taken on trust.
func socketExists(path string) bool {
	if path == "" {
		return true
	}
	_, err := os.Stat(path)
	return err == nil
}

// buildProviders is every infrastructure provider this build can rent machines
// from.
//
// It is built whatever the configuration says, and unconditionally: a
// deployment that rents nothing still has to be able to show which kinds it
// could, and a provider row whose kind has no factory here is answered with a
// problem naming the kind rather than with silence. Registering one is a line
// in this list; the registry refuses a factory whose contract range does not
// contain this build's, which is the earliest that mismatch can be caught.
func buildProviders() (*provider.Registry, error) {
	registry, err := provider.NewRegistry(proxmox.NewFactory())
	if err != nil {
		return nil, fmt.Errorf("preparing the infrastructure providers: %w", err)
	}
	return registry, nil
}

// sharedDirFor creates this host's shared folder and the layout this release
// keeps in it, and returns the folder -- or "" and the reason when it cannot be
// used, which leaves every pool's tool cache off on this host rather than
// stopping it.
func sharedDirFor(log *slog.Logger) (string, string) {
	return sharedDirIn(log, inContainer(), backend.IsMountPoint)
}

// inContainer is backend.InContainer, a variable so that a test run inside a
// container can still describe a host that is not one.
var inContainer = backend.InContainer

// sharedDirIn is sharedDirFor with the questions about the host passed in,
// which is what lets a test ask them of a host that is not the one it runs on.
func sharedDirIn(log *slog.Logger, inContainer bool, isMount func(string) bool) (string, string) {
	dir := config.SharedDir()
	// Checked before anything is created: in a container that does not mount
	// it, the folder would be made inside the data volume, where the host's
	// daemon -- which binds it for runners by this path -- cannot see it.
	if problem := backend.SharedFolderProblem(dir, inContainer, isMount); problem != "" {
		log.Warn("the shared folder is not mounted from the host; pools' tool caches are off on this host", "dir", dir, "fix", problem)
		return "", problem
	}
	if err := config.EnsureSharedDir(); err != nil {
		log.Warn("could not create the shared folder; pools' tool caches are off on this host until it exists and is writable",
			"dir", dir, "error", err,
			"fix", "create it and give it to the user Zoomies runs as, or run zoomies upgrade, which offers to")
		return "", fmt.Sprintf("the shared folder %s could not be created (%v); give it to the account Zoomies runs as, or run `zoomies upgrade --yes`, which does", dir, err)
	}
	return dir, ""
}

// buildBackends prepares the runner backends this host can use.
//
// Construction does not contact a daemon -- that is Probe's job -- so a host
// whose Docker is stopped still starts, reports the backend as unavailable and
// says why, instead of refusing to boot.
func buildBackends(ctx context.Context, cfg *config.Config, log *slog.Logger) (*backend.Registry, error) {
	var backends []backend.Backend
	opts := backend.DockerOptions{
		Network:      cfg.Agent.Network,
		WorkDir:      cfg.Agent.WorkDir,
		RegistryAuth: cfg.Agent.RegistryAuth,
		ExtraCAFile:  cfg.Agent.ExtraCAFile,
		Logger:       log,
	}
	opts.SharedDir, opts.SharedDirProblem = sharedDirFor(log)
	// An explicit agent.docker_host belongs to the backend it was configured
	// for; the other container backend keeps autodetecting its own socket.
	// Handing one socket to both made the Hosts page report the same denial
	// twice -- once as docker, once as "podman" at /var/run/docker.sock -- and,
	// once the socket was reachable, made a Docker host claim it offered Podman
	// too, since the two speak the same API.
	hostFor := func(kind store.BackendKind) string {
		if cfg.Agent.Backend == "" || cfg.Agent.Backend == string(kind) {
			return cfg.Agent.DockerHost
		}
		return ""
	}
	// A backend nobody configured is registered only when the host visibly
	// has it: a socket that exists, a shell to run the runner with. The
	// configured one is registered regardless, so that a daemon which is not
	// up yet is still re-probed and reported on. Registering the rest anyway
	// put a red row with install advice on every Docker host's Hosts page --
	// "install Podman", "apt-get install libicu" into a distroless image --
	// when the honest answer is that the host does not offer them.
	configured := func(kind store.BackendKind) bool {
		return cfg.Agent.Backend == "" || cfg.Agent.Backend == string(kind)
	}
	docker := opts
	docker.Host = hostFor(store.BackendDocker)
	if b, err := backend.NewDocker(docker); err != nil {
		log.Debug("the Docker backend is not available on this host", "error", err)
	} else if configured(b.Kind()) || socketExists(b.SocketPath()) {
		backends = append(backends, b)
	}
	podman := opts
	podman.Host = hostFor(store.BackendPodman)
	if b, err := backend.NewPodman(podman); err != nil {
		log.Debug("the Podman backend is not available on this host", "error", err)
	} else if configured(b.Kind()) || socketExists(b.SocketPath()) {
		backends = append(backends, b)
	}
	if b, err := backend.NewProcess(backend.ProcessOptions{
		WorkDir:                 cfg.Agent.WorkDir,
		RunnerVersion:           cfg.GitHub.RunnerVersion,
		RunnerSHA256:            cfg.Agent.RunnerSHA256,
		AllowUnverifiedDownload: cfg.Agent.AllowUnverifiedRunnerDownload,
		DownloadBaseURL:         cfg.Agent.RunnerDownloadURL,
		Logger:                  log,
	}); err != nil {
		log.Debug("the process backend could not be prepared", "error", err)
	} else if configured(b.Kind()) || backend.HasShell() {
		backends = append(backends, b)
	}

	reg := backend.NewRegistry(backends...)
	if len(reg.Kinds()) == 0 {
		return nil, errors.New("no runner backend could be prepared on this host, so the embedded agent would have no way to start a runner: " +
			"install Docker or Podman, make sure agent.work_dir is writable, or set agent.embedded to false")
	}
	if kind := strings.TrimSpace(cfg.Agent.Backend); kind != "" {
		if _, err := reg.Get(store.BackendKind(kind)); err != nil {
			return nil, fmt.Errorf("agent.backend is %q, which this host cannot provide: %w", kind, err)
		}
	}
	// Probing here rather than at first use means the startup log says what is
	// actually usable, which is the difference between "why is nothing
	// scheduling" and one line naming the stopped daemon.
	probeCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	for _, info := range reg.Probe(probeCtx) {
		if info.Available {
			log.Info("backend available", "kind", info.Kind, "version", info.Version, "rootless", info.Rootless, "endpoint", info.Endpoint)
		} else {
			log.Warn("backend not available", "kind", info.Kind, "detail", info.Detail)
		}
	}
	return reg, nil
}

// ---------------------------------------------------------------------------
// Startup banner
// ---------------------------------------------------------------------------

// printBanner prints the six facts an operator checks when a controller comes
// up, in one block, once. Everything else is a log line.
func printBanner(w io.Writer, cfg *config.Config, backends *backend.Registry) {
	external := cfg.Server.ExternalURL
	if external == "" {
		external = "(not set -- webhook URLs and the UI's links need server.external_url)"
	}
	webhook := cfg.WebhookURL()
	if webhook == "" {
		webhook = "(needs server.external_url) " + cfg.GitHub.WebhookPath
	}

	runners := "none -- this controller hosts no runners (agent.embedded is false)"
	if cfg.Agent.Embedded {
		kind := cfg.Agent.Backend
		if kind == "" && backends != nil {
			if kinds := backends.Kinds(); len(kinds) == 1 {
				kind = string(kinds[0])
			}
		}
		if kind == "" {
			kind = "autodetected"
		}
		runners = fmt.Sprintf("%s, embedded agent %q, capacity %d", kind, cfg.Agent.Name, cfg.Agent.Capacity)
	}

	scheme := "http"
	if cfg.Server.TLS.Mode != config.TLSOff {
		scheme = "https"
	}

	// The block paw mirrors the project's icon without reproducing its fine speed
	// ring, which would muddy the silhouette at terminal resolution.
	fmt.Fprintln(w, "\n        ▄██▄     ▄██▄")
	fmt.Fprintf(w, "       ██████   ██████        zoomies %s\n", version.Short())
	fmt.Fprintln(w, "  ▄██▄ ██████   ██████ ▄██▄  off the lead, on the job.")
	fmt.Fprintln(w, " █████  ▀██▀     ▀██▀  █████")
	fmt.Fprintln(w, "  ▀██▀      ▄██▄       ▀██▀")
	fmt.Fprintln(w, "         ▄████████▄")
	fmt.Fprintln(w, "       ▄████████████▄")
	fmt.Fprintln(w, "      ████████████████")
	fmt.Fprintln(w, "       ▀████████████▀")
	fmt.Fprintln(w, "          ▀▀██▀▀")
	fmt.Fprintln(w)
	for _, row := range [][2]string{
		{"listening on", fmt.Sprintf("%s://%s", scheme, cfg.Server.Bind)},
		{"external URL", external},
		{"webhook URL", webhook},
		{"backend", runners},
		{"database", cfg.Database.Path},
		{"config", configSource(cfg)},
	} {
		fmt.Fprintf(w, "  %-14s %s\n", row[0], row[1])
	}
	fmt.Fprintln(w)
}

// printSetupToken shows the credential the first-run form asks for, but only
// while there is nobody to sign in as.
//
// It goes to both the banner and the log: an operator watching a terminal sees
// it there, and one who ran `docker compose up -d` finds it with
// `docker compose logs`. Printing it on every start while the instance is empty
// is deliberate -- an operator who lost the first one should not have to reset
// anything, and once an account exists the line stops appearing for good.
func printSetupToken(ctx context.Context, w io.Writer, ctrl *controller.Controller, log *slog.Logger) {
	svc := ctrl.Auth()
	need, err := svc.NeedsBootstrap(ctx)
	if err != nil {
		log.Warn("could not check whether this instance has any accounts", "error", err)
		return
	}
	if !need {
		return
	}
	token := svc.SetupToken()
	log.Info("setup token: "+token,
		"why", "this instance has no accounts yet; the first-run page asks for this token",
		"note", "it changes on every restart, and this line stops once an account exists")
	fmt.Fprintf(w, "  %-14s %s\n", "setup token", token)
	fmt.Fprintf(w, "  %-14s %s\n", "", "paste this into the first-run page to create the first administrator")
	fmt.Fprintln(w)
}

// configSource names the file the configuration came from, or says there was
// not one -- which is a supported way to run and should not look like a fault.
func configSource(cfg *config.Config) string {
	if p := cfg.Path(); p != "" {
		if abs, err := filepath.Abs(p); err == nil {
			return abs
		}
		return p
	}
	return "(no file: defaults plus ZOOMIES_* environment)"
}

package main

import (
	"bytes"
	"context"
	"log/slog"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

func leaseTestStore(t *testing.T) *store.Store {
	t.Helper()
	st, err := store.Open(t.Context(), store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st
}

// The message is the whole point of the lease: an operator who has just been
// refused needs to know which machine to go and look at, and "the database is
// locked" would send them to the wrong one.
func TestTheSecondControllerIsToldWhichMachineHasTheDatabase(t *testing.T) {
	ctx := context.Background()
	st := leaseTestStore(t)

	// A live lease held by another machine. It has to be another machine:
	// a predecessor on this host is deliberately not a rival, since whoever is
	// asking holds the file lock and so nothing here is still running.
	other := &store.ControllerLease{
		Holder: store.NewID(store.PrefixController), Host: "vm-elsewhere",
		PID: 4242, Version: "1.0.0",
	}
	if _, err := st.AcquireControllerLease(ctx, other, controller.LeaseTTL, false); err != nil {
		t.Fatalf("seeding the other controller's lease: %v", err)
	}

	_, err := takeControllerLease(ctx, st, false)
	if err == nil {
		t.Fatal("a second controller took a database another machine holds")
	}
	msg := err.Error()
	if !strings.Contains(msg, "another controller holds this database") {
		t.Fatalf("error = %v, want it to name the conflict", err)
	}
	// The two things the operator needs: which machine, and how to proceed if
	// that machine is actually gone.
	if !strings.Contains(msg, "vm-elsewhere") {
		t.Errorf("the refusal must identify the holder: %v", err)
	}
	if !strings.Contains(msg, "--takeover") {
		t.Errorf("the refusal must name the way out: %v", err)
	}

	// --takeover exists for the machine that is really gone, and it has to
	// actually work -- otherwise the advice above is a dead end.
	mine, err := takeControllerLease(ctx, st, true)
	if err != nil {
		t.Fatalf("takeover: %v", err)
	}
	if mine.Holder == "" || mine.PID == 0 {
		t.Fatalf("the takeover produced a lease that says nothing about who holds it: %+v", mine)
	}
}

// A controller that restarts fast enough to beat its own lease's expiry must
// not refuse to start, which is the opposite of what the lease is for. The
// caller holds the file lock, so a predecessor on this host is already gone.
func TestRestartingOnTheSameHostIsNotAConflict(t *testing.T) {
	ctx := context.Background()
	st := leaseTestStore(t)

	first, err := takeControllerLease(ctx, st, false)
	if err != nil {
		t.Fatalf("taking the first lease: %v", err)
	}
	again, err := takeControllerLease(ctx, st, false)
	if err != nil {
		t.Fatalf("a restart on the same host was refused: %v", err)
	}
	if again.Host != first.Host {
		t.Fatalf("host = %q, want this machine's own", again.Host)
	}
}

// The configured level is where logging starts, and the gate it starts behind
// is the one SIGHUP later moves.
func TestSetupLoggingHonoursTheConfiguredLevel(t *testing.T) {
	cfg := config.Default()
	cfg.Log.Level = "warn"

	log, level := setupLogging(cfg)
	if log == nil || level == nil {
		t.Fatal("setupLogging returned nothing to log with")
	}
	if level.Level() != slog.LevelWarn {
		t.Fatalf("level = %v, want warn", level.Level())
	}

	// The inner handler is built at debug so that it never filters anything
	// itself; the wrapper is the only gate, which is what lets SIGHUP move it
	// without rebuilding loggers the controller already captured.
	level.Set(slog.LevelDebug)
	if !log.Enabled(context.Background(), slog.LevelDebug) {
		t.Fatal("the level change did not reach the logger")
	}
}

// A group on a level-gated handler must keep the gate, or a component that
// groups its attributes would quietly log at a level nobody asked for.
func TestGroupingALevelGatedHandlerKeepsTheGate(t *testing.T) {
	level := new(slog.LevelVar)
	level.Set(slog.LevelError)

	var buf bytes.Buffer
	inner := slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelDebug})
	log := slog.New(&levelHandler{Handler: inner, level: level}).WithGroup("agent")

	log.Info("suppressed")
	if buf.Len() != 0 {
		t.Fatalf("a grouped logger ignored the level: %s", buf.String())
	}

	level.Set(slog.LevelInfo)
	log.Info("allowed", "host", "vm-1")
	body := buf.String()
	if !strings.Contains(body, "allowed") {
		t.Fatalf("the grouped logger dropped a line it should have kept: %s", body)
	}
	if !strings.Contains(body, "agent.host") {
		t.Fatalf("the group was lost: %s", body)
	}
}

