func TestBannerSaysWhenThereIsNoExternalURL(t *testing.T) {
	// An empty webhook URL is the single most common reason a fleet does not
	// scale, so the banner has to name it rather than print a blank.
	cfg := config.Default()
	cfg.Agent.Embedded = false

	var buf bytes.Buffer
	printBanner(&buf, cfg, nil)

	if !strings.Contains(buf.String(), "server.external_url") {
		t.Errorf("a missing external URL was not called out:\n%s", buf.String())
	}
	if !strings.Contains(buf.String(), "hosts no runners") {
		t.Errorf("a controller without an embedded agent should say so:\n%s", buf.String())
	}
}

func TestLogLevelCanBeChangedWhileRunning(t *testing.T) {
	level := new(slog.LevelVar)
	level.Set(slog.LevelInfo)

	var buf bytes.Buffer
	inner := slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelDebug})
	log := slog.New(&levelHandler{Handler: inner, level: level})

	log.Debug("not yet")
	if buf.Len() != 0 {
		t.Errorf("a debug line escaped at info level: %s", buf.String())
	}

	level.Set(slog.LevelDebug)
	log.Debug("now")
	if !strings.Contains(buf.String(), "now") {
		t.Errorf("the level change did not take effect: %s", buf.String())
	}

	// Loggers derived before the change must follow it too: the controller and
	// the API both capture their own With(...) loggers at startup.
	derived := log.With("component", "test")
	buf.Reset()
	level.Set(slog.LevelError)
	derived.Warn("suppressed")
	if buf.Len() != 0 {
		t.Errorf("a derived logger ignored the level change: %s", buf.String())
	}
}

func TestBuildBackendsRefusesABackendThisHostCannotProvide(t *testing.T) {
	cfg := config.Default()
	cfg.Agent.WorkDir = t.TempDir()
	cfg.Agent.Backend = "wibble"

	t.Setenv("ZOOMIES_STATE_DIR", t.TempDir())
	_, err := buildBackends(context.Background(), cfg, discardLogger())
	if err == nil {
		t.Fatal("an unknown backend was accepted")
	}
	if !strings.Contains(err.Error(), "agent.backend") {
		t.Errorf("the error does not name the setting: %v", err)
	}
}

// The compose deployment names one socket, for one backend. Giving that socket
// to the Podman backend as well made the Hosts page show the same permission
// denial twice, and -- worse -- a reachable Docker socket answered the Podman
// probe too, so a Docker host advertised a Podman backend it did not have.
func TestBuildBackendsGivesTheExplicitSocketOnlyToTheConfiguredBackend(t *testing.T) {
	cfg := config.Default()
	cfg.Agent.WorkDir = t.TempDir()
	cfg.Agent.Backend = "docker"
	cfg.Agent.DockerHost = "unix://" + filepath.Join(t.TempDir(), "docker.sock")

	t.Setenv("ZOOMIES_STATE_DIR", t.TempDir())
	reg, err := buildBackends(context.Background(), cfg, discardLogger())
	if err != nil {
		t.Fatalf("buildBackends: %v", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	for _, info := range reg.Probe(ctx) {
		switch info.Kind {
		case store.BackendDocker:
			if info.Endpoint != cfg.Agent.DockerHost {
				t.Errorf("docker endpoint = %q, want the configured %q", info.Endpoint, cfg.Agent.DockerHost)
			}
		case store.BackendPodman:
			if info.Endpoint == cfg.Agent.DockerHost {
				t.Errorf("the podman backend was given the docker socket %q", info.Endpoint)
			}
		}
	}
}

// The compose deployment configures docker and nothing else, and the image it
// runs in has neither a Podman socket nor a shell. Registering Podman and the
// process backend anyway gave the Hosts page two red rows of advice that could
// not be followed -- "install Podman", "apt-get install libicu" -- on every
// such host.
func TestBuildBackendsLeavesOutBackendsThisHostVisiblyLacks(t *testing.T) {
	cfg := config.Default()
	cfg.Agent.WorkDir = t.TempDir()
	cfg.Agent.Backend = "docker"
	cfg.Agent.DockerHost = "unix://" + filepath.Join(t.TempDir(), "docker.sock")
	// No shell, and nowhere a per-user Podman socket could be found.
	t.Setenv("PATH", t.TempDir())
	t.Setenv("XDG_RUNTIME_DIR", t.TempDir())

	t.Setenv("ZOOMIES_STATE_DIR", t.TempDir())
	reg, err := buildBackends(context.Background(), cfg, discardLogger())
	if err != nil {
		t.Fatalf("buildBackends: %v", err)
	}
	kinds := reg.Kinds()
	if len(kinds) != 1 || kinds[0] != store.BackendDocker {
		t.Fatalf("registered %v, want only the configured docker backend (its socket may be down, and is still reported on)", kinds)
	}
}

// The upgrade path: an instance that has been running on a configuration file
// meets this build with an empty settings table.
//
// Without the import it would get a settings page showing every value as "from
// the file" and offering to store a second copy of each one. With it, the
// file's settings are the fleet's settings, the file stays as the layer
// underneath them, and nothing about what the controller runs changes.
func TestAConfigurationFileIsCarriedIntoTheDatabaseOnce(t *testing.T) {
	dir := isolateHost(t)
	ctx := context.Background()
	path := filepath.Join(dir, "zoomies.yaml")
	if err := os.WriteFile(path, []byte(
		"scheduler:\n  interval: 25s\nretention:\n  jobs: 1440h\n"), 0o600); err != nil {
		t.Fatalf("writing the file: %v", err)
	}

	cfg, err := config.Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	st := keyStore(t)
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}

	findings, err := seedSettingsFromFile(ctx, st, cfg, key, discardLogger())
	if err != nil {
		t.Fatalf("seedSettingsFromFile: %v", err)
	}
	if len(findings) != 1 || findings[0].Code != "settings.imported_from_file" {
		t.Errorf("the import said nothing an operator would see: %v", findings)
	}
	rows, err := st.InstanceSettings(ctx)
	if err != nil {
		t.Fatalf("InstanceSettings: %v", err)
	}
	if len(rows) != 2 {
		t.Fatalf("imported %d settings, want 2: %+v", len(rows), rows)
	}

	// Once, and only once. An operator who then clears a setting back to its
	// default must not find the file poured back in at the next start.
	if err := st.DeleteInstanceSettings(ctx, []string{"scheduler.interval"}); err != nil {
		t.Fatalf("DeleteInstanceSettings: %v", err)
	}
	again, err := seedSettingsFromFile(ctx, st, cfg, key, discardLogger())
	if err != nil {
		t.Fatalf("the second import: %v", err)
	}
	if len(again) != 0 {
		t.Errorf("the import ran a second time: %v", again)
	}
	if _, err := st.GetInstanceSetting(ctx, "scheduler.interval"); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("a cleared setting came back from the file: %v", err)
	}
}

// A fleet already configured through the settings page is not one the file has
// anything to say about, so nothing is imported over it.
func TestAFleetWithStoredSettingsIsNotOverwrittenByItsFile(t *testing.T) {
	dir := isolateHost(t)
	ctx := context.Background()
	path := filepath.Join(dir, "zoomies.yaml")
	if err := os.WriteFile(path, []byte("scheduler:\n  interval: 25s\n"), 0o600); err != nil {
		t.Fatalf("writing the file: %v", err)
	}
	cfg, err := config.Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}

	st := keyStore(t)
	if err := st.PutInstanceSettings(ctx, "an administrator", []store.InstanceSetting{
		{Key: "scheduler.interval", Value: "5s"},
	}); err != nil {
		t.Fatalf("PutInstanceSettings: %v", err)
	}

	key, _ := cryptox.GenerateKey()
	if _, err := seedSettingsFromFile(ctx, st, cfg, key, discardLogger()); err != nil {
		t.Fatalf("seedSettingsFromFile: %v", err)
	}
	row, err := st.GetInstanceSetting(ctx, "scheduler.interval")
	if err != nil {
		t.Fatalf("GetInstanceSetting: %v", err)
	}
	if row.Value != "5s" {
		t.Errorf("the file overwrote a stored setting: %q", row.Value)
	}
}

// A log level stored in the database is in force from the first line the
// assembled configuration could have affected.
//
// The gate is set before the store opens -- the store's own startup has things
// to say, and there is nowhere else to say them -- so that first setting knows
// only the file and the environment. Without a second one after the rows are
// read, log.level would be the one setting the registry calls live and the one
// a fresh start quietly ignored.
func TestAStoredLogLevelIsInForceAfterTheDatabaseIsRead(t *testing.T) {
	isolateHost(t)
	cfg := config.Default()
	_, level := setupLogging(cfg)
	if level.Level() != slog.LevelInfo {
		t.Fatalf("the default level is %s, want info", level.Level())
	}

	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	if _, err := cfg.Rebuild([]store.InstanceSetting{{Key: "log.level", Value: "debug"}}, key); err != nil {
		t.Fatalf("Rebuild: %v", err)
	}
	applyLogLevel(level, cfg)

	if level.Level() != slog.LevelDebug {
		t.Errorf("the gate is at %s after a stored debug level, want debug", level.Level())
	}
}

func TestControllerShutdownOutlastsEmbeddedAgent(t *testing.T) {
	if stopGrace <= agent.ShutdownTimeout {
		t.Fatalf("controller grace %s must exceed agent shutdown %s", stopGrace, agent.ShutdownTimeout)
	}
}

// An agent lays out the shared folder when it starts, so a release that adds a
// folder to config.SharedLayout has it on every host by the next start, and a
// pool's tool cache has somewhere to live.
func TestBuildBackendsLaysOutTheSharedFolder(t *testing.T) {
	notInAContainer(t)
	state := t.TempDir()
	t.Setenv("ZOOMIES_STATE_DIR", state)
	cfg := config.Default()
	cfg.Agent.WorkDir = t.TempDir()
	if _, err := buildBackends(context.Background(), cfg, discardLogger()); err != nil {
		t.Fatalf("buildBackends: %v", err)
	}
	for _, sub := range config.SharedLayout {
		if fi, err := os.Stat(filepath.Join(state, "shared", filepath.FromSlash(sub))); err != nil || !fi.IsDir() {
			t.Errorf("shared/%s was not created: %v", sub, err)
		}
	}
}

// notInAContainer makes this process describe a host that is not a container,
// whatever the machine running the tests is.
func notInAContainer(t *testing.T) {
	t.Helper()
	was := inContainer
	inContainer = func() bool { return false }
	t.Cleanup(func() { inContainer = was })
}

// A containerised agent whose container does not mount the shared folder from
// the host would create it inside its own data volume, and hand runners a path
// the host's daemon resolves to an empty folder of root's. It leaves the tool
// cache off instead, creates nothing, and says how to mount it.
func TestAContainerWithoutTheSharedMountKeepsNoToolCache(t *testing.T) {
	state := t.TempDir()
	t.Setenv("ZOOMIES_STATE_DIR", state)
	dir, problem := sharedDirIn(discardLogger(), true, func(string) bool { return false })
	if dir != "" {
		t.Errorf("dir = %q, want none", dir)
	}
	if !strings.Contains(problem, "not mounted into this container") || !strings.Contains(problem, "zoomies upgrade --yes") {
		t.Errorf("problem = %q, want one saying it is not mounted and how to mount it", problem)
	}
	if _, err := os.Stat(filepath.Join(state, "shared")); !os.IsNotExist(err) {
		t.Error("the folder was created inside the container anyway")
	}

	// Mounted from the host, it is used.
	dir, problem = sharedDirIn(discardLogger(), true, func(string) bool { return true })
	if dir == "" || problem != "" {
		t.Errorf("a mounted folder was refused: %q, %q", dir, problem)
	}
}

package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"
)

// defaultDemoPort is where a controller lives everywhere else in the
// documentation, so an address that is already in somebody's head works for the
// demo too. A machine that has one running on it gets the next free port
// instead of a refusal: the person asking to look around should not have to
// work out what is listening on 8080 first.
const defaultDemoPort = 8080

// demoReadyWithin is how long the demo waits for its own controller to answer
// before it stops saying "starting" and says something is wrong. Seeding the
// fleet and opening the database take about a second; a minute is a machine
// with something badly wrong with it.
const demoReadyWithin = time.Minute

// runDemo is `zoomies demo`: a throwaway controller with a fleet already in it,
// for somebody who wants to see the product before deciding whether to give it
// a machine and a GitHub organisation.
//
// The install is up to eighteen questions and two round trips to github.com
// before the first screen with anything on it, and the populated screen is the
// best argument for the product there is. Until this command the only way to
// reach it was an environment variable mentioned in a migration paragraph.
//
// It is the configuration the browser test suite already runs, and for the same
// reasons: authentication off, which the validator permits only on loopback; no
// agent, so no container runtime is needed; the seeded fleet, whose fixtures
// have no GitHub behind them and never call it; and a database in a directory
// that is removed when the controller stops. Nothing it does outlives it.
func runDemo(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies demo [--port N] [--no-browser]",
		"Run a throwaway controller on this machine with a fleet already in it, to look around.")
	port := fs.Int("port", defaultDemoPort, "port to listen on, on this machine only; if it is taken and was not asked for, a free one is used")
	noBrowser := fs.Bool("no-browser", false, "print the address instead of opening it")
	fs.example(
		"zoomies demo",
		"zoomies demo --port 9000 --no-browser",
		"curl -fsSL https://zoomies.sh/install.sh | sh -s -- --demo     # without installing anything",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if *port < 1 || *port > 65535 {
		return usagef("demo", "--port must be from 1 to 65535, or left out")
	}

	chosen, err := chooseDemoPort(*port, fs.changed("port"), listenLoopback)
	if err != nil {
		return err
	}
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(chosen))
	url := "http://" + addr

	dir, err := os.MkdirTemp("", "zoomies-demo-")
	if err != nil {
		return fmt.Errorf("making somewhere to keep the demo's data: %w", err)
	}
	// Removed whichever way this returns, so the demo leaves nothing behind on a
	// clean stop or a failed start. A process killed outright cannot do this, and
	// what it leaves is a directory under the temporary one.
	defer os.RemoveAll(dir)

	// The controller says a good deal at startup -- a banner, and a finding for
	// every setting that is not the safe default, such as authentication being
	// off, which here is on purpose -- and none of it helps somebody who is only
	// looking. It is kept, and shown only if the start fails, which is when it is
	// the explanation.
	var startup bytes.Buffer
	quiet := &env{out: io.Discard, err: &startup, in: e.in}

	pollCtx, stopPolling := context.WithCancel(ctx)
	defer stopPolling()
	announced := make(chan struct{})
	go func() {
		defer close(announced)
		if err := waitForDemo(pollCtx, url, demoReadyWithin); err != nil {
			return
		}
		announceDemo(e.out, url)
		if !*noBrowser {
			// Best effort, and the address is printed either way: half the
			// machines this runs on have no desktop to open it on.
			_ = openBrowser(url)
		}
	}()

	err = withEnvironment(demoSettings(dir, addr), func() error {
		return runController(ctx, quiet, nil)
	})
	// Waited for, so that nothing is written to the terminal after this
	// returns, and so that what is printed below is not interleaved with the
	// announcement of a demo that was stopped a moment after it came up.
	stopPolling()
	<-announced

	var restart *restartRequested
	switch {
	case err == nil, errors.As(err, &restart):
		// A restart is something only the settings page can ask for, and a
		// throwaway controller has nobody to start the next one.
	default:
		if startup.Len() > 0 {
			fmt.Fprint(e.err, startup.String())
		}
		return err
	}
	// Deleted before it is said to be, not after.
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("the demo stopped, but its data could not be deleted from %s: %w", dir, err)
	}
	fmt.Fprintln(e.out, "\nStopped. The demo's data was deleted.")
	return nil
}

// demoSettings is everything the demo says about its own configuration, as the
// environment layer: the one above the file and the database, and the only one
// that is certain to be read by a controller whose database did not exist a
// moment ago.
func demoSettings(dir, addr string) [][2]string {
	return [][2]string{
		// Loopback, and not a choice: authentication is off, and the validator
		// refuses that on anything a neighbour could reach.
		{"ZOOMIES_BIND", addr},
		{"ZOOMIES_DISABLE_AUTH", "true"},
		{"ZOOMIES_SEED_DEMO", "true"},
		// No agent, so no container runtime is wanted and none is probed.
		{"ZOOMIES_AGENT_EMBEDDED", "false"},
		// The one thing a controller does that is not about its own fleet: it
		// asks github.com, once a day, which release is current. The demo says
		// it talks to nothing outside this machine, so it does not ask. (The
		// fallback poller is left as it is by default: it skips the fixtures,
		// which have no GitHub behind them, and with it on the demo does not
		// open with an error saying nothing is scaling.)
		{"ZOOMIES_UPDATE_CHECK_INTERVAL", "0"},
		{"ZOOMIES_DB_PATH", filepath.Join(dir, "zoomies.db")},
		{"ZOOMIES_STATE_DIR", dir},
		{"ZOOMIES_CONFIG_DIR", dir},
		{"ZOOMIES_WORK_DIR", filepath.Join(dir, "work")},
		{"ZOOMIES_LOG_FORMAT", "text"},
		// Errors only: the seeded hosts have no agent behind them either, and
		// the controller notes that every forty seconds at any lower level.
		{"ZOOMIES_LOG_LEVEL", "error"},
	}
}

// withEnvironment runs fn with the demo's settings and nobody else's.
//
// Every other ZOOMIES_ variable is taken out for the duration and put back
// after. A machine that already runs Zoomies has some of them set -- an
// external URL, an encryption key, a database path -- and any one of them would
// change what the demo is: an external URL alone turns "authentication is off"
// from a warning into a refusal to start, and the person looking around would
// be told to fix a configuration they did not know they had.
func withEnvironment(settings [][2]string, fn func() error) error {
	held := map[string]string{}
	for _, entry := range os.Environ() {
		name, value, _ := strings.Cut(entry, "=")
		if strings.HasPrefix(name, "ZOOMIES_") {
			held[name] = value
			_ = os.Unsetenv(name)
		}
	}
	for _, s := range settings {
		_ = os.Setenv(s[0], s[1])
	}
	defer func() {
		for _, s := range settings {
			_ = os.Unsetenv(s[0])
		}
		for name, value := range held {
			_ = os.Setenv(name, value)
		}
	}()
	return fn()
}

// chooseDemoPort picks the port the demo listens on. One that was asked for is
// used or refused; one that was not is 8080 where that is free and any free
// port where it is not.
func chooseDemoPort(port int, asked bool, listen func(addr string) (net.Listener, error)) (int, error) {
	try := func(port int) (int, bool) {
		l, err := listen(net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
		if err != nil {
			return 0, false
		}
		defer l.Close()
		if tcp, ok := l.Addr().(*net.TCPAddr); ok {
			return tcp.Port, true
		}
		return port, true
	}
	if got, ok := try(port); ok {
		return got, nil
	}
	if asked {
		return 0, fmt.Errorf("port %d on this machine is already in use; pick another with --port, or leave it out and the demo finds a free one", port)
	}
	if got, ok := try(0); ok {
		return got, nil
	}
	return 0, errors.New("could not find a free port on this machine to listen on")
}

func listenLoopback(addr string) (net.Listener, error) { return net.Listen("tcp", addr) }

// waitForDemo returns once the controller answers its health check, or says why
// it stopped waiting.
func waitForDemo(ctx context.Context, url string, within time.Duration) error {
	client := &http.Client{Timeout: 2 * time.Second}
	deadline := time.NewTimer(within)
	defer deadline.Stop()
	tick := time.NewTicker(150 * time.Millisecond)
	defer tick.Stop()
	for {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url+"/healthz", nil)
		if err != nil {
			return err
		}
		if resp, err := client.Do(req); err == nil {
			_ = resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				return nil
			}
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-deadline.C:
			return fmt.Errorf("the demo did not answer within %s", within)
		case <-tick.C:
		}
	}
}

// announceDemo says where the demo is, and what it is, in the words a person
// who has never heard of the product needs: the address, that it is sample
// data, that nothing is asked of them and how to end it.
func announceDemo(w io.Writer, url string) {
	fmt.Fprintf(w, "\nZoomies demo is running.\n\n  %s\n\n", url)
	fmt.Fprintln(w, "  It is a controller on this machine only, with a fleet already in it: pools,")
	fmt.Fprintln(w, "  hosts, runners and a morning's worth of jobs. Nobody has to sign in, GitHub")
	fmt.Fprintln(w, "  is not involved, and everything is deleted when you stop it with Ctrl-C.")
	fmt.Fprintln(w)
}

// openBrowser asks the desktop to open a page, and says whether it could.
//
// The opener is deliberately not tied to the demo's context. A context that is
// cancelled kills the process it started, and on a desktop where xdg-open hands
// itself over to the browser, that process is the browser -- so stopping the
// demo would close somebody's other tabs along with it.
func openBrowser(target string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", target)
	case "windows":
		cmd = exec.Command("rundll32", "url.dll,FileProtocolHandler", target)
	default:
		cmd = exec.Command("xdg-open", target)
	}
	detachFromTerminal(cmd)
	if err := cmd.Start(); err != nil {
		return err
	}
	// Reaped in the background: the opener is a short-lived process of its own,
	// and a demo can run for hours.
	go func() { _ = cmd.Wait() }()
	return nil
}

package main

import (
	"bytes"
	"context"
	"errors"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"
)

// settings turns demoSettings into something a test can ask questions of.
func settings(t *testing.T, dir, addr string) map[string]string {
	t.Helper()
	got := map[string]string{}
	for _, s := range demoSettings(dir, addr) {
		if _, dup := got[s[0]]; dup {
			t.Errorf("%s is set twice, so which one wins depends on the order", s[0])
		}
		got[s[0]] = s[1]
	}
	return got
}

// The demo switches authentication off, which the validator permits only where
// nobody else can reach the listener. Whatever else changes, this must not.
func TestTheDemoListensOnLoopbackAndNowhereElse(t *testing.T) {
	got := settings(t, t.TempDir(), "127.0.0.1:8080")
	host, _, err := net.SplitHostPort(got["ZOOMIES_BIND"])
	if err != nil {
		t.Fatalf("the demo's bind address %q is not host:port: %v", got["ZOOMIES_BIND"], err)
	}
	if ip := net.ParseIP(host); ip == nil || !ip.IsLoopback() {
		t.Errorf("the demo listens on %q, and authentication is off", host)
	}
	if got["ZOOMIES_DISABLE_AUTH"] != "true" {
		t.Error("the demo asks people to sign in, which is the one thing it exists to avoid")
	}
}

// "Nothing leaves this machine" is a claim the announcement makes, and it holds
// only while nothing in the configuration asks the outside world a question.
// The release check is the one a controller makes unprompted, once a day, to
// github.com whatever its own GitHub is.
func TestTheDemoAsksNothingOutsideThisMachine(t *testing.T) {
	got := settings(t, t.TempDir(), "127.0.0.1:8080")
	if got["ZOOMIES_UPDATE_CHECK_INTERVAL"] != "0" {
		t.Errorf("the demo still checks github.com for a new release (interval %q)", got["ZOOMIES_UPDATE_CHECK_INTERVAL"])
	}
	if got["ZOOMIES_AGENT_EMBEDDED"] != "false" {
		t.Error("the demo starts an agent, which wants a container runtime that most people looking around do not have")
	}
	if got["ZOOMIES_SEED_DEMO"] != "true" {
		t.Error("the demo does not seed its fleet, so it opens on an empty controller")
	}
}

// Everything the demo writes is under the directory it deletes. A path that
// escaped it would be data left on somebody's machine by a command that said it
// would leave none.
func TestEverythingTheDemoWritesIsInsideItsOwnDirectory(t *testing.T) {
	dir := t.TempDir()
	for name, value := range settings(t, dir, "127.0.0.1:8080") {
		if !strings.HasSuffix(name, "_PATH") && !strings.HasSuffix(name, "_DIR") {
			continue
		}
		rel, err := filepath.Rel(dir, value)
		if err != nil || strings.HasPrefix(rel, "..") {
			t.Errorf("%s is %q, which is outside the demo's directory %q", name, value, dir)
		}
	}
}

// A machine that already runs Zoomies has some of these set, and any of them
// would change what the demo is: an external URL alone turns "authentication is
// off" from a warning into a refusal to start.
func TestTheDemoIgnoresAndRestoresTheEnvironmentItWasStartedIn(t *testing.T) {
	t.Setenv("ZOOMIES_EXTERNAL_URL", "https://zoomies.example.com")
	t.Setenv("ZOOMIES_BIND", "0.0.0.0:9999")

	var inside, bindInside string
	err := withEnvironment([][2]string{{"ZOOMIES_BIND", "127.0.0.1:8080"}}, func() error {
		inside = os.Getenv("ZOOMIES_EXTERNAL_URL")
		bindInside = os.Getenv("ZOOMIES_BIND")
		return errors.New("passed through")
	})
	if err == nil || err.Error() != "passed through" {
		t.Errorf("what the function returned was not handed back: %v", err)
	}
	if inside != "" {
		t.Errorf("the external URL %q reached the demo's controller", inside)
	}
	if bindInside != "127.0.0.1:8080" {
		t.Errorf("the demo's own bind address was %q while it ran", bindInside)
	}
	if got := os.Getenv("ZOOMIES_EXTERNAL_URL"); got != "https://zoomies.example.com" {
		t.Errorf("the external URL was %q afterwards, so the demo changed this shell's environment", got)
	}
	if got := os.Getenv("ZOOMIES_BIND"); got != "0.0.0.0:9999" {
		t.Errorf("the bind address was %q afterwards", got)
	}
}

func TestThePortIsTheDefaultWhereThatIsFreeAndAnyFreeOneWhereItIsNot(t *testing.T) {
	busy := func(addr string) (net.Listener, error) {
		if strings.HasSuffix(addr, ":8080") {
			return nil, errors.New("address already in use")
		}
		return net.Listen("tcp", addr)
	}
	port, err := chooseDemoPort(8080, false, busy)
	if err != nil {
		t.Fatal(err)
	}
	if port == 8080 || port == 0 {
		t.Errorf("a busy 8080 gave port %d", port)
	}

	free := func(addr string) (net.Listener, error) { return net.Listen("tcp", "127.0.0.1:0") }
	if _, err := chooseDemoPort(8080, false, free); err != nil {
		t.Errorf("a free default was refused: %v", err)
	}
}

// Somebody who typed a port wants that port. Quietly giving them another one
// means the address in their bookmark, their tunnel or their notes is wrong.
func TestAPortThatWasAskedForIsUsedOrRefused(t *testing.T) {
	busy := func(string) (net.Listener, error) { return nil, errors.New("address already in use") }
	_, err := chooseDemoPort(9000, true, busy)
	if err == nil {
		t.Fatal("a port that was asked for and is taken was swapped for another")
	}
	for _, want := range []string{"9000", "--port"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not say %q: %v", want, err)
		}
	}
}

func TestTheDemoRefusesAPortThatIsNotOne(t *testing.T) {
	e, _, _ := newTestEnv(t)
	for _, port := range []string{"0", "70000", "-1"} {
		if code := dispatch(context.Background(), e, []string{"demo", "--port", port}); code != exitUsage {
			t.Errorf("--port %s exited %d, want %d", port, code, exitUsage)
		}
	}
}

// lockedBuffer is what the demo writes to while the test is reading it: the
// announcement comes from a goroutine, and the test has to wait for it to find
// out where the demo is.
type lockedBuffer struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (l *lockedBuffer) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}

func (l *lockedBuffer) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.String()
}

// The whole thing, end to end: it starts, it says where it is, it answers with
// the seeded fleet in it, it stops when it is told to, and it leaves nothing on
// the machine.
func TestTheDemoServesASeededFleetAndLeavesNothingBehind(t *testing.T) {
	if testing.Short() {
		t.Skip("starts a controller")
	}
	e, _, _ := newTestEnv(t)
	out := &lockedBuffer{}
	e.out = out
	// Where the demo's directory is made, so that "nothing is left behind" is
	// something this test can look at rather than hope for.
	scratch := t.TempDir()
	t.Setenv("TMPDIR", scratch)
	t.Setenv("TMP", scratch)
	t.Setenv("TEMP", scratch)

	ctx, stop := context.WithCancel(context.Background())
	defer stop()
	exit := make(chan int, 1)
	go func() { exit <- dispatch(ctx, e, []string{"demo", "--no-browser"}) }()

	// It says where it is only once it answers, so this is the wait.
	where := regexp.MustCompile(`http://127\.0\.0\.1:\d+`)
	var base string
	for deadline := time.Now().Add(60 * time.Second); base == "" && time.Now().Before(deadline); {
		base = where.FindString(out.String())
		select {
		case code := <-exit:
			t.Fatalf("the demo stopped by itself with exit code %d before it said where it was:\n%s", code, out)
		case <-time.After(100 * time.Millisecond):
		}
	}
	if base == "" {
		t.Fatalf("the demo did not say where it was within a minute:\n%s", out)
	}

	get := func(path string) (int, string) {
		t.Helper()
		resp, err := http.Get(base + path)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		return resp.StatusCode, string(body)
	}
	// Signed in as nobody, because there is nobody to sign in as, and the fleet
	// on the page is the seeded one.
	if code, body := get("/api/v1/pools"); code != http.StatusOK || !strings.Contains(body, "zoomies-demo-linux-x64") {
		t.Errorf("the demo's pools: HTTP %d\n%s", code, body)
	}
	if code, _ := get("/api/v1/stats"); code != http.StatusOK {
		t.Errorf("the demo's stats asked for a sign-in: HTTP %d", code)
	}

	stop()
	select {
	case code := <-exit:
		if code != exitOK {
			t.Fatalf("stopping the demo exited %d, want %d", code, exitOK)
		}
	case <-time.After(60 * time.Second):
		t.Fatal("the demo did not stop within a minute of being asked to")
	}

	for _, want := range []string{"Ctrl-C", "deleted"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("what the demo said does not mention %q:\n%s", want, out)
		}
	}
	left, err := os.ReadDir(scratch)
	if err != nil {
		t.Fatal(err)
	}
	if len(left) != 0 {
		var names []string
		for _, f := range left {
			names = append(names, f.Name())
		}
		t.Errorf("the demo left %v behind in the temporary directory", names)
	}
}

package main

import (
	"context"
	"fmt"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/installer"
)

func runDeployment(ctx context.Context, e *env, args []string) error {
	subs := []*subcommand{
		{"status", "", "Show the installed container and image state", deploymentAction(installer.DeploymentStatus)},
		{"logs", "", "Show the latest 100 controller log lines", deploymentAction(installer.DeploymentLogs)},
		{"start", "", "Start a stopped deployment", deploymentAction(installer.DeploymentStart)},
		{"stop", "", "Stop containers without removing them", deploymentAction(installer.DeploymentStop)},
		{"restart", "", "Restart the current containers", deploymentAction(installer.DeploymentRestart)},
		{"update", "", "Pull matching controller and runner images and safely recreate the controller", runDeploymentUpdate},
		{"down", "", "Stop and remove containers while keeping the database volume", deploymentAction(installer.DeploymentDown)},
	}
	return runGroup(ctx, e, "deployment", "Operate the Docker or Compose deployment recorded by `zoomies init`.", subs, args)
}

func deploymentAction(action installer.DeploymentAction) func(context.Context, *env, []string) error {
	return deploymentActionNamed("deployment "+string(action), action)
}

func deploymentActionNamed(command string, action installer.DeploymentAction) func(context.Context, *env, []string) error {
	return func(ctx context.Context, e *env, args []string) error {
		fs := newFlagSet(e, "zoomies "+command+" [--config-dir path]",
			"Use the saved deployment record, so container names and Compose files are never guessed.")
		configDir := fs.String("config-dir", "", "directory containing deployment.json (default: "+config.ConfigDir()+")")
		fs.example("zoomies "+command, "zoomies "+command+" --config-dir /etc/zoomies")
		if err := fs.parse(args); err != nil {
			return err
		}
		if err := fs.noMoreArgs(); err != nil {
			return err
		}
		return installer.ControlDeployment(ctx, installer.DeploymentControlOptions{
			ConfigDir: *configDir, Action: action, Out: e.out,
		})
	}
}

// runLogs is the short spelling operators reach for during setup and incident
// response. The nested command remains available for backwards compatibility.
func runLogs(ctx context.Context, e *env, args []string) error {
	return deploymentActionNamed("logs", installer.DeploymentLogs)(ctx, e, args)
}

func runDeploymentUpdate(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies deployment update [flags]",
		"Pull matching controller and cached runner images, then safely recreate the controller with rollback on failure.")
	configDir := fs.String("config-dir", "", "directory containing deployment.json (default: "+config.ConfigDir()+")")
	image := fs.String("image", "", "replacement image for a custom deployment; stock images follow this binary's release channel")
	dockerHost := fs.String("docker-host", "", "container runtime endpoint; empty uses the recorded/default endpoint")
	runtime := fs.String("runtime", "", "docker or podman; empty derives it from the deployment")
	fs.example("zoomies deployment update", "zoomies deployment update --image registry.example.com/zoomies:v2")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if *runtime != "" && *runtime != "docker" && *runtime != "podman" {
		return fmt.Errorf("--runtime must be docker or podman")
	}
	return installer.ControlDeployment(ctx, installer.DeploymentControlOptions{
		ConfigDir: *configDir, Action: installer.DeploymentUpdate, Image: *image,
		DockerHost: *dockerHost, Runtime: *runtime, Out: e.out,
	})
}

