package main

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// runDiagnostics fetches the support bundle and, by default, writes it to a
// file.
//
// It is deliberately thin. The document is the server's bytes written through
// unchanged, so a section added to the bundle tomorrow reaches a support case
// today without this being rebuilt; what the CLI adds is the file and a summary
// of what is in it, because the one question an operator has before attaching a
// bundle to a public issue is what they are about to hand over.
func runDiagnostics(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies diagnostics [--file zoomies-bundle.json]",
		"Collect a support bundle: this instance, its fleet and what is wrong, in one JSON document.")
	cf := registerClientFlags(fs, true)
	file := fs.String("file", "", "write the document here; \"-\" means stdout. The default names a file in the working directory")
	stdout := fs.Bool("stdout", false, "write the document to stdout instead of a file, the same as --file -")
	fs.example("zoomies diagnostics", "zoomies diagnostics --file /tmp/bundle.json", "zoomies diagnostics --stdout")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var bundle bundleResponse
	raw, err := client.get(ctx, "/diagnostics/bundle", nil, &bundle)
	if err != nil {
		return err
	}

	// --output json or yaml is a pipe, and a pipe wants the document rather
	// than a file it would then have to find.
	if p.structured() {
		return p.emit(raw)
	}
	if *stdout || *file == "-" {
		_, err := e.out.Write(append(raw, '\n'))
		return err
	}

	path := *file
	if path == "" {
		path = bundleFileName(bundle.GeneratedAt)
	}
	// 0600 because a bundle carries the whole configuration and the fleet's
	// shape: it is not a secret, and it is nobody else's on a shared host.
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		return fmt.Errorf("writing the bundle to %s: %w", path, err)
	}
	if abs, aerr := filepath.Abs(path); aerr == nil {
		path = abs
	}
	printBundleSummary(p, &bundle, path, len(raw))
	return nil
}

// bundleFileName names the file after the instant the controller took the
// bundle, so two bundles from one afternoon are told apart by the thing that
// distinguishes them.
func bundleFileName(at time.Time) string {
	if at.IsZero() {
		return "zoomies-bundle.json"
	}
	return "zoomies-bundle-" + at.UTC().Format("20060102-150405") + ".json"
}

// printBundleSummary says what went into the file.
func printBundleSummary(p *printer, b *bundleResponse, path string, size int) {
	p.note("Wrote %s (%s).", path, humanBytes(size))
	p.note("")
	p.keyValues([][2]string{
		{"Instance", strings.TrimSpace(b.Instance.Version + " " + b.Instance.OS + "/" + b.Instance.Arch)},
		{"Taken", b.GeneratedAt.UTC().Format(time.RFC3339)},
		{"Problems", fmt.Sprintf("%d", len(b.Problems.Items))},
		{"Config findings", fmt.Sprintf("%d", len(b.Findings))},
		{"Installations", fmt.Sprintf("%d", len(b.Installations))},
		{"Pools", fmt.Sprintf("%d", len(b.Pools))},
		{"Hosts", fmt.Sprintf("%d", len(b.Hosts))},
		{"Runners", fmt.Sprintf("%d", len(b.Runners))},
		{"Unfinished jobs", fmt.Sprintf("%d, %d explained", len(b.Jobs), len(b.Explanations))},
		{"Scaling decisions", fmt.Sprintf("%d", len(b.ScalingEvents))},
		{"Log pointers", fmt.Sprintf("%d", len(b.Logs.Runners))},
	})

	// The two things a reader of the bundle would otherwise have to discover
	// by finding a section short and guessing why.
	if len(b.Errors) > 0 {
		p.note("")
		p.note("Some sections could not be gathered, and the bundle says so in its errors array:")
		for _, e := range b.Errors {
			p.note("  %s: %s", e.Section, e.Error)
		}
	}
	for _, t := range b.Truncated {
		p.note("")
		p.note("%s was shortened: %s", t.Section, t.Reason)
	}

	p.note("")
	p.note("No workflow log is in it. Attach the ones a support case needs from the runners the")
	p.note("bundle's logs section names, so you choose what leaves this fleet.")
}

// humanBytes renders a size the way an operator about to attach a file thinks
// about one.
func humanBytes(n int) string {
	switch {
	case n >= 1<<20:
		return fmt.Sprintf("%.1f MB", float64(n)/(1<<20))
	case n >= 1<<10:
		return fmt.Sprintf("%.0f KB", float64(n)/(1<<10))
	default:
		return fmt.Sprintf("%d bytes", n)
	}
}

package main

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The bundle body a test controller answers with. It is deliberately not the
// shape this CLI declares: the extra section is there to prove the document is
// written through rather than re-marshalled from what the CLI understood.
const testBundle = `{
  "bundle_version": 1,
  "generated_at": "2026-01-02T03:04:05Z",
  "instance": {"version": "v1.2.3", "os": "linux", "arch": "amd64", "goroutines": 42},
  "problems": {"ok": false, "items": [{"code": "hosts.unhealthy", "title": "A host is silent"}]},
  "pools": [{"id": "pool_a"}],
  "hosts": [{"id": "hst_a"}],
  "a_section_this_cli_has_never_heard_of": {"kept": true},
  "logs": {"note": "not here", "runners": [{"runner_id": "run_a"}]},
  "errors": [{"section": "stats", "error": "the database is locked"}],
  "truncated": [{"section": "runners", "kept": 500, "reason": "the fleet has more"}]
}`

func bundleServer(t *testing.T) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/v1/diagnostics/bundle" {
			t.Errorf("the CLI asked for %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(testBundle))
	}))
	t.Cleanup(srv.Close)
	return srv
}

// The document written to disk is the server's, byte for byte. That is what
// lets a section added to the bundle tomorrow reach a support case without
// this CLI being rebuilt -- and re-marshalling from the partial type the CLI
// declares would silently drop exactly the section nobody has support for yet.
func TestTheBundleFileIsTheServersDocument(t *testing.T) {
	srv := bundleServer(t)
	path := filepath.Join(t.TempDir(), "bundle.json")

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"diagnostics", "--url", srv.URL, "--file", path}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}

	written, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading the bundle: %v", err)
	}
	var got map[string]any
	if err := json.Unmarshal(written, &got); err != nil {
		t.Fatalf("the written bundle is not JSON: %v", err)
	}
	if _, ok := got["a_section_this_cli_has_never_heard_of"]; !ok {
		t.Error("a section the CLI does not declare was dropped on the way to the file")
	}
	if !strings.Contains(out.String(), path) {
		t.Errorf("the terminal does not name the file it wrote:\n%s", out)
	}
}

// An operator about to attach a bundle to a public issue has one question, and
// it is what they are handing over. A short section is the other half: a reader
// who cannot tell a section that failed from a fleet that has nothing in it
// will draw the wrong conclusion from the same document.
func TestTheSummarySaysWhatWentInAndWhatDidNot(t *testing.T) {
	srv := bundleServer(t)

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"diagnostics", "--url", srv.URL, "--file", filepath.Join(t.TempDir(), "b.json")}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	for _, want := range []string{
		"v1.2.3 linux/amd64",
		"stats: the database is locked",
		"runners was shortened",
		"No workflow log is in it",
	} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("the summary does not mention %q:\n%s", want, out)
		}
	}
}

// --output json is a pipe, and a pipe wants the document rather than a file it
// would then have to go and find.
func TestStructuredOutputEmitsTheBundleRatherThanWritingAFile(t *testing.T) {
	srv := bundleServer(t)
	dir := t.TempDir()
	t.Chdir(dir)

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"diagnostics", "--url", srv.URL, "--output", "json"}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	var got map[string]any
	if err := json.Unmarshal(out.Bytes(), &got); err != nil {
		t.Fatalf("--output json did not emit the document: %v\n%s", err, out)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("reading the working directory: %v", err)
	}
	if len(entries) != 0 {
		t.Errorf("--output json left a file behind: %v", entries)
	}
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

// runExport is `zoomies export --installation ID`.
//
// The archive is written by the controller, through the same route the API
// documents, so the CLI holds no second idea of what "everything about an
// installation" means.
func runExport(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies export --installation <installation-id> [--passphrase-file FILE] [--out FILE]",
		"Write everything about one installation -- its pools, runners, jobs, deliveries, scaling events, runner sessions "+
			"and the audit rows that name them -- as one archive another instance can import.")
	cf := registerClientFlags(fs, false)
	id := fs.String("installation", "", "the installation to export, as shown by `zoomies installations list`")
	passFile := fs.String("passphrase-file", "", "seal the App's private key and webhook secret under the passphrase in this file, so the archive can be imported without this instance's key")
	out := fs.String("out", "", "where to write the archive (default zoomies-installation-<id>.json in the current directory)")
	fs.example(
		"zoomies export --installation ins_k3f9qz2m --passphrase-file ./move.pass",
		"zoomies export --installation ins_k3f9qz2m --out history.json   # history only, no credentials",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if strings.TrimSpace(*id) == "" {
		return usagef("export", "needs --installation, the ID `zoomies installations list` shows")
	}
	passphrase, err := readPassphraseFile(*passFile)
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	dest := *out
	if dest == "" {
		dest = "zoomies-installation-" + *id + ".json"
	}

	var body any
	if passphrase != "" {
		body = map[string]string{"passphrase": passphrase}
	}
	// Written beside the destination and renamed into place, so an export
	// that fails half way never leaves a truncated archive under the name an
	// operator will later import from.
	tmp, err := os.CreateTemp(filepath.Dir(dest), ".zoomies-export-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if err := client.postInto(ctx, "/installations/"+url.PathEscape(*id)+"/export", body, tmp); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(0o600); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmp.Name(), dest); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Wrote %s.\n", dest)
	if passphrase == "" {
		fmt.Fprintln(e.out, "It carries no credentials: an import of it will need the App's private key entered by hand.")
	} else {
		fmt.Fprintln(e.out, "The App's credentials are in it, sealed under the passphrase. Keep the two apart.")
	}
	return nil
}

// runImport is `zoomies import <archive>`.
func runImport(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies import <archive> [--passphrase-file FILE]",
		"Write an installation archive from `zoomies export` onto this instance, all of it or none.")
	cf := registerClientFlags(fs, true)
	passFile := fs.String("passphrase-file", "", "the passphrase the archive was exported with")
	fs.example("zoomies import zoomies-installation-ins_k3f9qz2m.json --passphrase-file ./move.pass")
	if err := fs.parse(args); err != nil {
		return err
	}
	path, err := fs.oneArg("the archive `zoomies export --installation` wrote")
	if err != nil {
		return err
	}
	passphrase, err := readPassphraseFile(*passFile)
	if err != nil {
		return err
	}
	archive, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !json.Valid(archive) {
		return fmt.Errorf("%s is not an installation archive: it is not JSON", path)
	}
	cf.defaultTimeoutTo(fs, importRequestTimeout)
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	var done struct {
		Installation installationItem `json:"installation"`
		Rows         map[string]int   `json:"rows"`
		Skipped      map[string]int   `json:"skipped"`
	}
	raw, err := client.post(ctx, "/installations/import", nil,
		map[string]any{"archive": json.RawMessage(archive), "passphrase": passphrase}, &done)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	total := 0
	for _, n := range done.Rows {
		total += n
	}
	p.note("Imported %s (%s): %d rows.", done.Installation.Target, done.Installation.ID, total)
	if n := done.Skipped["runners"]; n > 0 {
		p.note("%d runner rows stayed behind: they name hosts only the old instance has. Their history came as sessions.", n)
	}
	p.note("Run `zoomies installations verify %s` to check the App's credentials here.", done.Installation.ID)
	return nil
}

// readPassphraseFile reads a passphrase from a file rather than a flag,
// because a flag's value is in the shell history and the process list.
func readPassphraseFile(path string) (string, error) {
	if path == "" {
		return "", nil
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	pass := strings.TrimRight(string(raw), "\r\n")
	if strings.TrimSpace(pass) == "" {
		return "", fmt.Errorf("%s is empty; put the passphrase in it, or leave --passphrase-file out", path)
	}
	return pass, nil
}

// postInto sends a JSON body and copies a successful answer straight to w, for
// a response that may be larger than do is prepared to hold in memory.
func (c *apiClient) postInto(ctx context.Context, path string, body any, w io.Writer) error {
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(encoded)
	}
	reqCtx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()
	req, err := http.NewRequestWithContext(reqCtx, http.MethodPost, c.endpoint(path, nil), reader)
	if err != nil {
		return err
	}
	c.decorate(req)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := c.http.Do(req)
	if err != nil {
		if stopped(ctx, err) {
			return context.Canceled
		}
		return c.transportError(http.MethodPost, path, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 400 {
		raw, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		return parseAPIError(http.MethodPost, path, resp.StatusCode, raw)
	}
	_, err = io.Copy(w, resp.Body)
	return err
}

package main

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"
)

// The passphrase travels in the request body, read from a file, and the
// archive lands where --out says with nothing but its owner able to read it:
// with a passphrase in it, it is a credential.
func TestExportSendsThePassphraseFromItsFileAndWritesTheArchive(t *testing.T) {
	var got map[string]string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != "/api/v1/installations/ins_1/export" {
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
		}
		raw, _ := io.ReadAll(r.Body)
		_ = json.Unmarshal(raw, &got)
		_, _ = w.Write([]byte(`{"kind":"zoomies-installation","tables":[]}`))
	}))
	t.Cleanup(srv.Close)

	dir := t.TempDir()
	pass := filepath.Join(dir, "move.pass")
	if err := os.WriteFile(pass, []byte("correct horse\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	dest := filepath.Join(dir, "archive.json")
	out, _ := runCLI(t, "export", "--installation", "ins_1", "--passphrase-file", pass, "--out", dest, "--url", srv.URL)

	if got["passphrase"] != "correct horse" {
		t.Errorf("the passphrase sent was %q, want the file's contents without its newline", got["passphrase"])
	}
	body, err := os.ReadFile(dest)
	if err != nil || !strings.Contains(string(body), "zoomies-installation") {
		t.Fatalf("the archive was not written: %q, %v", body, err)
	}
	// Windows has no mode bits to check; the directory's ACL is what keeps
	// the archive private there, as for the backup's copied key.
	if st, _ := os.Stat(dest); runtime.GOOS != "windows" && st.Mode().Perm() != 0o600 {
		t.Errorf("the archive is mode %v, want 0600", st.Mode().Perm())
	}
	if !strings.Contains(out, "sealed under the passphrase") {
		t.Errorf("the output does not say the credentials are in it:\n%s", out)
	}
}

// A refused export must not leave a file behind under the name an operator
// would later import from.
func TestARefusedExportWritesNoArchive(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`{"error":{"code":"not_found","message":"installation ins_1: not found"}}`))
	}))
	t.Cleanup(srv.Close)
	dest := filepath.Join(t.TempDir(), "archive.json")
	e, _, _ := newTestEnv(t)
	if code := dispatch(t.Context(), e, []string{"export", "--installation", "ins_1", "--out", dest, "--url", srv.URL}); code == exitOK {
		t.Fatal("a refused export exited cleanly")
	}
	if _, err := os.Stat(dest); !os.IsNotExist(err) {
		t.Errorf("a refused export left %s behind", dest)
	}
}

// Import sends the archive as it was written, not re-encoded, with the
// passphrase beside it.
func TestImportSendsTheArchiveAndItsPassphrase(t *testing.T) {
	var got struct {
		Archive    json.RawMessage `json:"archive"`
		Passphrase string          `json:"passphrase"`
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/v1/installations/import" {
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
		}
		raw, _ := io.ReadAll(r.Body)
		_ = json.Unmarshal(raw, &got)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"installation":{"id":"ins_1","target":"acme"},"rows":{"jobs":3},"skipped":{"runners":2}}`))
	}))
	t.Cleanup(srv.Close)
	dir := t.TempDir()
	archive := filepath.Join(dir, "a.json")
	_ = os.WriteFile(archive, []byte(`{"kind":"zoomies-installation","tables":[]}`), 0o600)
	pass := filepath.Join(dir, "p")
	_ = os.WriteFile(pass, []byte("correct horse"), 0o600)

	out, _ := runCLI(t, "import", archive, "--passphrase-file", pass, "--url", srv.URL)
	if got.Passphrase != "correct horse" || !strings.Contains(string(got.Archive), "zoomies-installation") {
		t.Errorf("sent %+v", got)
	}
	for _, want := range []string{"acme", "3 rows", "2 runner rows", "installations verify ins_1"} {
		if !strings.Contains(out, want) {
			t.Errorf("the output does not say %q:\n%s", want, out)
		}
	}
}

// An archive is a year of history and can be hundreds of megabytes, so the
// thirty seconds that suit a list call would cut a large import off on a slow
// link. The operator's own --timeout still wins, because it is the only way to
// ask for less.
func TestImportWaitsLongerThanAnOrdinaryCallUnlessToldOtherwise(t *testing.T) {
	for _, tc := range []struct {
		name string
		args []string
		want time.Duration
	}{
		{"nothing given", nil, importRequestTimeout},
		{"an explicit shorter timeout", []string{"--timeout", "5s"}, 5 * time.Second},
		{"an explicit timeout equal to the default", []string{"--timeout", "30s"}, defaultRequestTimeout},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e, _, _ := newTestEnv(t)
			fs := newFlagSet(e, "zoomies import", "test")
			cf := registerClientFlags(fs, true)
			if err := fs.parse(tc.args); err != nil {
				t.Fatal(err)
			}
			cf.defaultTimeoutTo(fs, importRequestTimeout)
			if *cf.timeout != tc.want {
				t.Fatalf("timeout = %s, want %s", *cf.timeout, tc.want)
			}
		})
	}
}

package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

// errFlagHelp is returned when the operator asked for help rather than made a
// mistake. It exits 0: `zoomies pools list --help | less` should not look like
// a failure to a shell.
var errFlagHelp = errors.New("help requested")

// flagSet is a flag.FlagSet with the usage text this CLI prints. Every command
// builds one; there are no global flags, so `zoomies runners list --help`
// describes exactly the flags that command accepts and no others.
type flagSet struct {
	*flag.FlagSet
	// usageLine is the synopsis, e.g. "zoomies runners drain <runner-id>".
	usageLine string
	// summary is the one-line description printed above the flags.
	summary string
	// examples are printed after the flags, and are worth more than the flags.
	examples []string
	out      io.Writer
}

// newFlagSet builds a flag set that writes to stderr and prints a synopsis, a
// summary and the flags when asked.
func newFlagSet(e *env, usageLine, summary string) *flagSet {
	fs := &flagSet{
		FlagSet:   flag.NewFlagSet(commandName(usageLine), flag.ContinueOnError),
		usageLine: usageLine,
		summary:   summary,
		out:       e.err,
	}
	fs.SetOutput(e.err)
	fs.Usage = func() { fs.printUsage(fs.out) }
	return fs
}

// commandName extracts "pools list" from "zoomies pools list [--output ...]".
//
// It is derived from the usage line rather than passed separately so that the
// name in an error message and the name in the synopsis cannot drift: there is
// one string, and it is the one the operator was shown.
func commandName(usageLine string) string {
	var words []string
	for _, w := range strings.Fields(usageLine) {
		if w == "zoomies" {
			continue
		}
		if strings.HasPrefix(w, "-") || strings.HasPrefix(w, "<") || strings.HasPrefix(w, "[") {
			break
		}
		words = append(words, w)
	}
	return strings.Join(words, " ")
}

// example records a line worth copying. Examples go after the flags because
// that is where an operator's eye lands last and stays.
func (fs *flagSet) example(lines ...string) { fs.examples = append(fs.examples, lines...) }

func (fs *flagSet) printUsage(w io.Writer) {
	if fs.summary != "" {
		fmt.Fprintf(w, "%s\n\n", fs.summary)
	}
	fmt.Fprintf(w, "Usage:\n  %s\n", fs.usageLine)

	var flags []*flag.Flag
	fs.VisitAll(func(f *flag.Flag) { flags = append(flags, f) })
	if len(flags) > 0 {
		sort.Slice(flags, func(i, j int) bool { return flags[i].Name < flags[j].Name })
		fmt.Fprintln(w, "\nFlags:")
		for _, f := range flags {
			name := "--" + f.Name
			if f.DefValue != "" && f.DefValue != "false" {
				name += "=" + f.DefValue
			}
			fmt.Fprintf(w, "  %-26s %s\n", name, f.Usage)
		}
	}
	if len(fs.examples) > 0 {
		fmt.Fprintln(w, "\nExamples:")
		for _, ex := range fs.examples {
			fmt.Fprintf(w, "  %s\n", ex)
		}
	}
}

// parse parses args, translating a help request into errFlagHelp and any other
// failure into a usage error so that both exit with the right code.
//
// Arguments are permuted first. The standard flag package stops parsing at the
// first non-flag word, which would make `zoomies runners drain run_k3f9 --url
// https://...` treat the URL as a second runner ID -- a footgun with real
// consequences on a command that acts on runners.
func (fs *flagSet) parse(args []string) error {
	// -h and --help are handled by flag itself, but it writes the default
	// usage to the output we set; ours is better, so print it and stop.
	if err := fs.FlagSet.Parse(fs.permute(args)); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			// flag has already called Usage for us.
			return errFlagHelp
		}
		return &usageError{cmd: fs.Name(), err: err}
	}
	return nil
}

// permute moves flags ahead of positional arguments, leaving the order within
// each group alone.
//
// A flag that takes a value carries the following word with it. Whether a flag
// takes one is asked of the flag set itself, so a boolean stays boolean and an
// unknown flag is left where it is for flag.Parse to complain about by name.
func (fs *flagSet) permute(args []string) []string {
	flags := make([]string, 0, len(args))
	positional := make([]string, 0, len(args))

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			// Everything after it is positional by definition.
			positional = append(positional, args[i+1:]...)
			break
		}
		if len(arg) < 2 || arg[0] != '-' {
			positional = append(positional, arg)
			continue
		}
		flags = append(flags, arg)

		name := strings.TrimLeft(arg, "-")
		if _, _, found := strings.Cut(name, "="); found {
			// --flag=value carries its own value, so there is no following
			// argument to consume.
			continue
		}
		f := fs.Lookup(name)
		if f == nil {
			continue // unknown; flag.Parse will name it
		}
		if b, ok := f.Value.(interface{ IsBoolFlag() bool }); ok && b.IsBoolFlag() {
			continue // --verbose takes no value
		}
		if i+1 < len(args) {
			i++
			flags = append(flags, args[i])
		}
	}
	if len(positional) == 0 {
		return flags
	}
	// The separator matters: without it a positional that begins with a dash
	// -- a runner named "-x", or an argument after an explicit "--" -- would be
	// re-read as a flag once it had been moved to the end.
	return append(append(flags, "--"), positional...)
}

// noMoreArgs refuses trailing arguments rather than ignoring them, because a
// silently dropped argument is how somebody drains the wrong runner.
func (fs *flagSet) noMoreArgs() error {
	if fs.NArg() > 0 {
		return usagef(fs.Name(), "unexpected argument %q", fs.Arg(0))
	}
	return nil
}

// oneArg requires exactly one positional argument and names it in the error.
func (fs *flagSet) oneArg(what string) (string, error) {
	switch fs.NArg() {
	case 0:
		return "", usagef(fs.Name(), "needs %s", what)
	case 1:
		return fs.Arg(0), nil
	default:
		return "", usagef(fs.Name(), "takes one %s, but %d were given", what, fs.NArg())
	}
}

// atLeastOneArg requires one or more positional arguments.
func (fs *flagSet) atLeastOneArg(what string) ([]string, error) {
	if fs.NArg() == 0 {
		return nil, usagef(fs.Name(), "needs at least one %s", what)
	}
	return fs.Args(), nil
}

// changed reports whether a flag was given on the command line, as opposed to
// left at its default. Partial updates depend on the difference: PATCHing a
// pool must send the fields the operator typed and nothing else.
func (fs *flagSet) changed(name string) bool {
	seen := false
	fs.Visit(func(f *flag.Flag) {
		if f.Name == name {
			seen = true
		}
	})
	return seen
}

// ---------------------------------------------------------------------------
// Flag value types
// ---------------------------------------------------------------------------

// listValue collects a repeatable, comma-separated flag: --state busy --state
// idle and --state busy,idle mean the same thing, because both are what people
// type.
type listValue []string

func (l *listValue) String() string {
	if l == nil {
		return ""
	}
	return strings.Join(*l, ",")
}

func (l *listValue) Set(v string) error {
	for _, part := range strings.Split(v, ",") {
		if part = strings.TrimSpace(part); part != "" {
			*l = append(*l, part)
		}
	}
	return nil
}

// exactList is a repeatable flag whose values are kept whole. listValue splits
// on commas, which is right for a repository or a state and wrong for a matrix
// job's name, "test (ubuntu-latest, 3.12)", which has one in it.
type exactList []string

func (l *exactList) String() string {
	if l == nil {
		return ""
	}
	return strings.Join(*l, "; ")
}

func (l *exactList) Set(v string) error {
	if v = strings.TrimSpace(v); v != "" {
		*l = append(*l, v)
	}
	return nil
}

// kvValue collects repeatable key=value pairs: --label arch=arm64 --label
// tier=fast, or one flag with both separated by a comma.
type kvValue map[string]string

func (m kvValue) String() string {
	if len(m) == 0 {
		return ""
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, k+"="+m[k])
	}
	return strings.Join(parts, ",")
}

func (m kvValue) Set(v string) error {
	for _, part := range strings.Split(v, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		k, val, ok := strings.Cut(part, "=")
		if !ok || strings.TrimSpace(k) == "" {
			return fmt.Errorf("%q is not key=value, for example arch=arm64", part)
		}
		m[strings.TrimSpace(k)] = strings.TrimSpace(val)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Paging
// ---------------------------------------------------------------------------

// pageFlags are the four query parameters every list route accepts. They are
// declared in one place so that --limit means the same thing on runners, jobs
// and the audit log, and so that a new list command cannot forget one.
type pageFlags struct {
	limit  *int
	offset *int
	sort   *string
	order  *string
}

func registerPageFlags(fs *flagSet, defaultLimit int) *pageFlags {
	return &pageFlags{
		limit:  fs.Int("limit", defaultLimit, "rows to return (max 500)"),
		offset: fs.Int("offset", 0, "rows to skip, for paging"),
		sort:   fs.String("sort", "", "column to sort by; an unknown one falls back to the default"),
		order:  fs.String("order", "", "asc or desc"),
	}
}

// apply adds whichever of them the operator set. Sending an empty sort would
// be sending a value, and the server would have to guess what it meant.
func (pf *pageFlags) apply(q url.Values) {
	if pf.limit != nil && *pf.limit > 0 {
		q.Set("limit", strconv.Itoa(*pf.limit))
	}
	if pf.offset != nil && *pf.offset > 0 {
		q.Set("offset", strconv.Itoa(*pf.offset))
	}
	if pf.sort != nil && *pf.sort != "" {
		q.Set("sort", *pf.sort)
	}
	if pf.order != nil && *pf.order != "" {
		q.Set("order", *pf.order)
	}
}

// addList adds a repeatable query parameter the OpenAPI document declares as
// style: form, explode: true -- that is, one key repeated, never a joined
// string, which is what the server parses.
func addList(q url.Values, key string, values []string) {
	for _, v := range values {
		if v != "" {
			q.Add(key, v)
		}
	}
}

// footer says how much of a list was shown, but only when there is more to see.
// A count under every table would be noise; a count when 50 of 812 rows came
// back is the difference between a complete answer and a misleading one.
func (p *printer) footer(shown, total, offset int) {
	if total <= shown+offset {
		return
	}
	fmt.Fprintf(p.out, "\nShowing %d-%d of %d. Use --limit and --offset for the rest.\n", offset+1, offset+shown, total)
}

package main

import (
