	labels, _ := body["labels"].(map[string]any)
	if labels["arch"] != "arm64" {
		t.Errorf("labels = %v", body["labels"])
	}
	for _, want := range []string{"zoojoin_abc_secret", "install.sh", "only time the token is shown"} {
