	"net/url"
	"strconv"
	"strings"
)

// runProviders is `zoomies providers ...`: where machines are rented from, and
// the machines themselves, over the same routes the UI uses.
//
// Every verb here is one an operator reaches for when something is wrong at an
// hour when nobody wants to open a browser: is this hypervisor answering, stop
// buying machines, what is out there that we have lost track of.
func runProviders(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "providers", "Where machines are rented from, and the machines themselves.", []*subcommand{
		{"list", "", "Every provider, with its machines and whether it is buying", providersList},
		{"kinds", "", "What this build can rent from, and the settings each kind asks for", providersKinds},
		{"add", "<kind> [flags]", "Add a provider from the terminal, then ask it what it would refuse", providersAdd},
		{"edit", "<name|id> [flags]", "Change the settings you name and nothing else", providersEdit},
		{"check", "<name|id>", "Ask a provider what it would refuse, changing nothing", providersCheck},
		{"pause", "<name|id>", "Stop buying new machines; drains and deletes continue", providersPause},
		{"resume", "<name|id>", "Let it buy machines again", providersResume},
		{"machines", "", "The machines that exist right now", providersMachines},
		{"orphans", "<name|id>", "Resources and rows that disagree, for a person to decide", providersOrphans},
	}, args)
}

func providersList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers list [--output table|json|yaml]",
		"List every provider, with how many machines it has and whether it may buy more.")
	cf := registerClientFlags(fs, true)
	fs.example("zoomies providers list", "zoomies providers list --output json | jq '.items[].name'")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[providerItem]
	raw, err := client.get(ctx, "/providers", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No providers. Add one with: zoomies providers add proxmox --name <n> --endpoint <url> ... (or in the UI under Providers); a credential belongs in the database, sealed, rather than in a configuration file.")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, item := range out.Items {
		buying := p.paint(colourGreen, "yes")
		switch {
		case item.Paused:
			buying = p.paint(colourYellow, "paused")
		case !item.Enabled:
			buying = p.paint(colourDim, "disabled")
		case item.Held != "":
			buying = p.paint(colourYellow, "held")
		}
		rows = append(rows, []string{
			item.Name,
			item.ID,
			item.Kind,
			dash(item.Endpoint),
			fmt.Sprintf("%d/%d", item.Owned, item.MaxMachines),
			machineStates(item.Machines),
			buying,
			p.relTimePtr(item.LastCheckAt),
		})
	}
	p.table([]string{"name", "id", "kind", "endpoint", "machines", "states", "buying", "last check"}, rows)

	// Why a provider is buying nothing is the question this table exists to
	// answer, and it is a sentence rather than a column.
	for _, item := range out.Items {
		if item.Held != "" {
			p.note("%s: %s", item.Name, item.Held)
		}
		if item.LastCheckError != "" {
			p.note("%s: the last check said: %s", item.Name, item.LastCheckError)
		}
	}
	return nil
}

// providersCheck runs the live preflight and prints it with printFindings, so
// the terminal and the wizard say the same words about the same provider.
func providersCheck(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers check <name|id>",
		"Ask a provider what it would refuse. It changes nothing, and exits non-zero if anything would stop a machine being created.")
	cf := registerClientFlags(fs, true)
	fs.example("zoomies providers check proxmox-lab")
	if err := fs.parse(args); err != nil {
		return err
	}
	ref, err := fs.oneArg("a provider name or ID, as shown by `zoomies providers list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	provider, err := resolveProvider(ctx, client, ref)
	if err != nil {
		return err
	}
	if p.structured() {
		var report providerCheckItem
		raw, err := client.post(ctx, "/providers/"+url.PathEscape(provider.ID)+"/check", nil, nil, &report)
		if err != nil {
			return err
		}
		return p.emit(raw)
	}
	return checkProvider(ctx, e, p, client, provider)
}

func providersPause(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers pause <name|id> [--reason \"...\"]",
		"Stop a provider buying new machines. Draining, deleting and recovering carry on.")
	cf := registerClientFlags(fs, true)
	reason := fs.String("reason", "", "why, for the card and the audit row")
	fs.example(`zoomies providers pause proxmox-lab --reason "the cluster is being patched"`)
	if err := fs.parse(args); err != nil {
		return err
	}
	ref, err := fs.oneArg("a provider name or ID")
	if err != nil {
		return err
	}
	return setProviderPaused(ctx, e, cf, ref, true, *reason)
}

func providersResume(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers resume <name|id>",
		"Let a provider buy machines again.")
	cf := registerClientFlags(fs, true)
	fs.example("zoomies providers resume proxmox-lab")
	if err := fs.parse(args); err != nil {
		return err
	}
	ref, err := fs.oneArg("a provider name or ID")
	if err != nil {
		return err
	}
	return setProviderPaused(ctx, e, cf, ref, false, "")
}

// setProviderPaused is both halves of the kill switch. Pressing it twice is not
// an error on the server and is not one here either: the person doing it wants
// the fleet in a known state, not an argument about whether it was already.
func setProviderPaused(ctx context.Context, e *env, cf *clientFlags, ref string, paused bool, reason string) error {
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	provider, err := resolveProvider(ctx, client, ref)
	if err != nil {
		return err
	}
	verb := "resume"
	var body any
	if paused {
		verb = "pause"
		body = map[string]string{"reason": reason}
	}

	var out providerItem
	raw, err := client.post(ctx, "/providers/"+url.PathEscape(provider.ID)+"/"+verb, nil, body, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if paused {
		p.note("%s is buying no new machines. Machines it already has keep running, and drains, deletes and recovery carry on.", out.Name)
		if out.Held != "" {
			p.note("%s", out.Held)
		}
		return nil
	}
	p.note("%s may buy machines again.", out.Name)
	if out.Held != "" {
		// Resuming one switch does not mean the fleet is buying: the fence,
		// the configuration and the ceiling each hold it too.
		p.note("It still is not: %s", out.Held)
	}
	return nil
}

func providersMachines(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers machines [--provider X] [--state ready]",
		"List the machines that exist right now, and what each one is waiting on.")
	cf := registerClientFlags(fs, true)
	provider := fs.String("provider", "", "only this provider's machines, by name or ID")
	state := fs.String("state", "", "only machines in this state, e.g. ready, creating, quarantined")
	includeDeleted := fs.Bool("include-deleted", false, "keep machines whose resource is confirmed gone")
	fs.example("zoomies providers machines --state quarantined", "zoomies providers machines --provider proxmox-lab")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	q := url.Values{}
	if strings.TrimSpace(*provider) != "" {
		row, err := resolveProvider(ctx, client, *provider)
		if err != nil {
			return err
		}
		q.Set("provider", row.ID)
	}
	if s := strings.TrimSpace(*state); s != "" {
		q.Set("state", s)
	}
	if *includeDeleted {
		q.Set("include_deleted", "true")
	}

	var out listResponse[machineItem]
	raw, err := client.get(ctx, "/machines", q, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No machines.")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, m := range out.Items {
		rows = append(rows, []string{
			m.Name,
			m.ID,
			dash(m.ProviderName),
			p.paint(machineStateColour(m.State), m.State),
			dash(m.HostName),
			dash(resourceOf(m)),
			dash(m.Address),
			p.relTime(m.CreatedAt),
		})
	}
	p.table([]string{"name", "id", "provider", "state", "host", "resource", "address", "age"}, rows)

	// A machine that is stuck says why here rather than making somebody open
	// the page: the operation handle is what an operator pastes into the
	// provider's own task log.
	for _, m := range out.Items {
		switch {
		case m.ProviderError != "":
			p.note("%s: %s", m.Name, m.ProviderError)
		case m.BootstrapError != "":
			p.note("%s: %s", m.Name, m.BootstrapError)
		case m.Message != "" && (m.State == "failed" || m.State == "quarantined"):
			p.note("%s: %s", m.Name, m.Message)
		}
		if m.Operation != "" && m.OperationHandle != "" {
			p.note("%s: %s in flight, provider task %s", m.Name, m.Operation, m.OperationHandle)
		}
	}
	return nil
}

// providersOrphans prints the review page in a terminal. It offers to delete
// nothing: every row here is something for a person to look at, and the one
// destructive act needs the machine's name typed into the API.
func providersOrphans(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers orphans <name|id>",
		"Show the resources and rows that disagree: untracked resources, rows holding nothing, and machines nobody can vouch for.")
	cf := registerClientFlags(fs, true)
	fs.example("zoomies providers orphans proxmox-lab")
	if err := fs.parse(args); err != nil {
		return err
	}
	ref, err := fs.oneArg("a provider name or ID")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	provider, err := resolveProvider(ctx, client, ref)
	if err != nil {
		return err
	}

	var out orphanReport
	raw, err := client.get(ctx, "/providers/"+url.PathEscape(provider.ID)+"/orphans", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}

	if len(out.Untracked) == 0 && len(out.NoResource) == 0 && len(out.Unverified) == 0 {
		p.note("Every machine %s has is accounted for. Last swept %s.", provider.Name, p.relTimePtr(out.LastSweepAt))
		return nil
	}
	if len(out.Untracked) > 0 {
		fmt.Fprintf(e.out, "\nResources with no row (Zoomies will never delete these):\n")
		for _, o := range out.Untracked {
			fmt.Fprintf(e.out, "  - %s\n      %s\n", o.Name, o.Note)
		}
	}
	if len(out.NoResource) > 0 {
		fmt.Fprintf(e.out, "\nRows holding no resource (releasing one loses nothing):\n")
		for _, m := range out.NoResource {
			fmt.Fprintf(e.out, "  - %s (%s) %s\n", m.Name, m.ID, dash(m.Message))
		}
	}
	if len(out.Unverified) > 0 {
		fmt.Fprintf(e.out, "\nMachines nobody can vouch for (nothing will act on these until you do):\n")
		for _, m := range out.Unverified {
			detail := m.OwnershipError
			if detail == "" {
				detail = m.SafeToDeleteWhy
			}
			fmt.Fprintf(e.out, "  - %s (%s) at %s\n      %s\n", m.Name, m.ID, dash(resourceOf(m)), dash(detail))
		}
	}
	fmt.Fprintln(e.out)
	p.note("Last swept %s.", p.relTimePtr(out.LastSweepAt))
	return nil
}

// resolveProvider turns what an operator typed into a provider, accepting
// either the name they know it by or the ID a log line quoted.
func resolveProvider(ctx context.Context, client *apiClient, ref string) (providerItem, error) {
	ref = strings.TrimSpace(ref)
	var out listResponse[providerItem]
	if _, err := client.get(ctx, "/providers", nil, &out); err != nil {
		return providerItem{}, err
	}
	var names []string
	for _, item := range out.Items {
		if item.ID == ref || strings.EqualFold(item.Name, ref) {
			return item, nil
		}
		names = append(names, item.Name)
	}
	if len(names) == 0 {
		return providerItem{}, fmt.Errorf("there are no providers configured, so %q is not one", ref)
	}
	return providerItem{}, fmt.Errorf("no provider called %q; this fleet has: %s", ref, strings.Join(names, ", "))
}

// machineStates renders the by-state counts a provider carries, in the order a
// machine lives through them so the line reads as a pipeline.
func machineStates(counts map[string]int) string {
	order := []string{"planned", "creating", "starting", "bootstrapping", "enrolling", "ready", "draining", "deleting", "failed", "quarantined"}
	parts := make([]string, 0, len(order))
	for _, state := range order {
		if n := counts[state]; n > 0 {
			parts = append(parts, strconv.Itoa(n)+" "+state)
		}
	}
	if len(parts) == 0 {
		return "-"
	}
	return strings.Join(parts, ", ")
}

// machineStateColour is the fixed status mapping the UI uses, in the four
// colours a terminal has: pending states are the ones still being waited on,
// ready is good, and the two that need a person are red.
func machineStateColour(state string) string {
	switch state {
	case "ready":
		return colourGreen
	case "failed", "quarantined":
		return colourRed
	case "draining", "deleting":
		return colourYellow
	case "deleted":
		return colourDim
	}
	return colourCyan
}

// resourceOf names the resource behind a machine the way its provider does, so
// it can be pasted into the provider's own console.
func resourceOf(m machineItem) string {
	switch {
	case m.ResourceZone != "" && m.ResourceID != "":
		return m.ResourceZone + "/" + m.ResourceID
	case m.ResourceID != "":
		return m.ResourceID
	}
	return ""
}

func pluralWarnings(n int) string {
	if n == 1 {
		return "1 warning"
	}
	return strconv.Itoa(n) + " warnings"
}

package main

import (
	"context"
	"fmt"
	"net/url"
	"os"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
)

// providerSpec holds the flags `providers add` and `providers edit` share.
// Keeping them in one place is what makes `edit` accept exactly the settings
// `add` does, as the pool commands do.
//
// The wizard asks its questions over five steps. Here they are one line, and
// the line is the same shape as `hosts join-token create`: what to connect to,
// what to build, what it may spend. The answers the wizard discovers from the
// cluster -- nodes, storages, bridges, templates -- have to be typed, because
// discovery needs a saved credential and this command has not saved one yet.
// `zoomies providers check` says afterwards which of them the cluster refuses.
type providerSpec struct {
	name        *string
	endpoint    *string
	tokenFile   *string
	caFile      *string
	insecure    *bool
	gateway     *string
	nodes       *listValue
	template    *string
	storage     *string
	bridge      *string
	vmidRange   *string
	settings    kvValue
	labels      kvValue
	capacity    *int
	backend     *string
	cpus        *float64
	memoryMB    *int64
	diskMB      *int64
	pools       kvValue
	maxMachines *int
	maxInFlight *int
	idleTimeout *string
	costPerHour *float64
	enabled     *bool
}

// registerProviderFlags declares them, with the API's own defaults so that a
// provider created here is the same as one the wizard made.
func registerProviderFlags(fs *flagSet) *providerSpec {
	spec := &providerSpec{
		nodes:    &listValue{},
		settings: kvValue{},
		labels:   kvValue{},
		pools:    kvValue{},
	}
	spec.name = fs.String("name", "", "the provider's name, as the machines page and the audit log will call it, e.g. proxmox-lab")
	spec.endpoint = fs.String("endpoint", "", "where the controller reaches it, e.g. https://pve.example.com:8006")
	spec.tokenFile = fs.String("credential-file", "", "a file holding the API token (user@realm!tokenid=secret); otherwise it is asked for, or read from standard input when that is not a terminal")
	spec.caFile = fs.String("endpoint-ca-file", "", "the CA certificate to verify the endpoint against, e.g. pve-root-ca.pem, instead of turning verification off")
	spec.insecure = fs.Bool("endpoint-insecure", false, "skip certificate verification of the endpoint; the token then crosses to anybody in the middle, and the provider warns for as long as this is on")
	spec.gateway = fs.String("gateway", "", "the address `zoomies gateway` printed, for a provider on a network the controller cannot reach")
	fs.Var(spec.nodes, "nodes", "the cluster nodes machines may be built on (repeatable, or comma-separated)")
	spec.template = fs.String("template", "", "the VMID of the prepared template every machine is cloned from")
	spec.storage = fs.String("storage", "", "the storage a clone's disk lands on")
	spec.bridge = fs.String("bridge", "", "the network bridge a machine attaches to (default vmbr0)")
	spec.vmidRange = fs.String("vmid-range", "", "the block of VM identifiers only Zoomies allocates from, e.g. 9000-9099 (the default)")
	fs.Var(spec.settings, "setting", "any other driver setting, as key=value; `zoomies providers kinds` lists them")
	fs.Var(spec.labels, "labels", "labels every machine reports as a host, e.g. arch=amd64")
	spec.capacity = fs.Int("capacity", 2, "how many runners one machine may run at once")
	spec.backend = fs.String("backend", "docker", "the runner backend the machines offer: docker, podman or process")
	spec.cpus = fs.Float64("cpus", 0, "CPUs per machine; 0 keeps the template's")
	spec.memoryMB = fs.Int64("memory-mb", 0, "memory per machine, in MiB; 0 keeps the template's")
	spec.diskMB = fs.Int64("disk-mb", 0, "disk per machine, in MiB; 0 keeps the template's")
	fs.Var(spec.pools, "pool-selector", "only buy for pools whose labels match, e.g. tier=large; empty means every pool")
	spec.maxMachines = fs.Int("max-machines", 0, "the most machines this provider may own at once; 0 rents nothing")
	spec.maxInFlight = fs.Int("max-in-flight", 1, "how many machines may be being built at once")
	spec.idleTimeout = fs.String("idle-timeout", "15m", "how long a machine may sit idle before it is drained and deleted")
	spec.costPerHour = fs.Float64("cost-per-hour", 0, "what one machine costs an hour, for the page to add up")
	spec.enabled = fs.Bool("enabled", true, "whether the provider may buy machines at all")
	return spec
}

// body renders the flags as the request the API takes. On a create every flag
// is sent so the row carries the documented defaults; on an edit only the
// flags the operator typed are, because a PATCH that resent the defaults would
// quietly reset the settings they did not name.
//
// The driver's settings come back separately: a create sends them as they
// are, and an edit merges them over the row's, because the API replaces the
// whole map and an edit that named one key would otherwise drop the rest.
func (spec *providerSpec) body(e *env, fs *flagSet, create bool) (body map[string]any, settings map[string]string, err error) {
	body = map[string]any{}
	want := func(flag string) bool { return create || fs.changed(flag) }

	if want("name") {
		body["name"] = strings.TrimSpace(*spec.name)
	}
	if want("endpoint") {
		body["endpoint"] = strings.TrimSpace(*spec.endpoint)
	}
	if fs.changed("endpoint-ca-file") {
		pem, err := os.ReadFile(*spec.caFile)
		if err != nil {
			return nil, nil, fmt.Errorf("reading the CA certificate: %w", err)
		}
		body["ca_pem"] = string(pem)
	}
	if want("endpoint-insecure") {
		body["insecure_skip_verify"] = *spec.insecure
	}
	if fs.changed("gateway") {
		if addr := strings.TrimSpace(*spec.gateway); addr != "" {
			body["connection"] = "tailcat"
			body["tailcat_address"] = addr
		} else {
			body["connection"] = "direct"
		}
	} else if create {
		body["connection"] = "direct"
	}

	// The driver's settings. The named flags are the Proxmox form's required
	// questions spelled as flags; --setting reaches everything else, and a
	// --setting naming one of these keys is the same answer given twice.
	settings = map[string]string{}
	for k, v := range spec.settings {
		settings[k] = v
	}
	if len(*spec.nodes) > 0 {
		settings["nodes"] = strings.Join(*spec.nodes, ",")
	}
	if fs.changed("template") {
		settings["template_id"] = strings.TrimSpace(*spec.template)
	}
	if fs.changed("storage") {
		settings["storage"] = strings.TrimSpace(*spec.storage)
	}
	if fs.changed("bridge") {
		settings["bridge"] = strings.TrimSpace(*spec.bridge)
	} else if create {
		settings["bridge"] = "vmbr0"
	}
	if fs.changed("vmid-range") || create {
		lo, hi, err := parseVMIDRange(*spec.vmidRange)
		if err != nil {
			return nil, nil, err
		}
		settings["vmid_min"], settings["vmid_max"] = lo, hi
	}
	if create {
		body["settings"] = settings
	}

	if create || len(spec.labels) > 0 {
		body["machine_labels"] = map[string]string(spec.labels)
	}
	if want("capacity") {
		body["machine_capacity"] = *spec.capacity
	}
	if want("backend") {
		body["machine_backend"] = strings.TrimSpace(*spec.backend)
	}
	if want("cpus") {
		body["machine_cpus"] = *spec.cpus
	}
	if want("memory-mb") {
		body["machine_memory_mb"] = *spec.memoryMB
	}
	if want("disk-mb") {
		body["machine_disk_mb"] = *spec.diskMB
	}
	if create || len(spec.pools) > 0 {
		body["pool_selector"] = map[string]string(spec.pools)
	}
	if want("max-machines") {
		body["max_machines"] = *spec.maxMachines
	}
	if want("max-in-flight") {
		body["max_creates_in_flight"] = *spec.maxInFlight
	}
	if want("idle-timeout") {
		body["idle_timeout"] = strings.TrimSpace(*spec.idleTimeout)
	}
	if want("cost-per-hour") {
		body["cost_per_machine_hour"] = *spec.costPerHour
	}
	if want("enabled") {
		body["enabled"] = *spec.enabled
	}

	// The credential last, and only when asked for: an edit that names no
	// token keeps the one that is sealed.
	if fs.changed("credential-file") {
		raw, err := os.ReadFile(*spec.tokenFile)
		if err != nil {
			return nil, nil, fmt.Errorf("reading the API token: %w", err)
		}
		body["credential"] = strings.TrimSpace(string(raw))
	} else if create {
		token, err := readSecret(e, "API token (user@realm!tokenid=secret): ")
		if err != nil {
			return nil, nil, err
		}
		if token == "" {
			return nil, nil, fmt.Errorf("a provider needs an API token; paste it when asked, pipe it on standard input, or give --credential-file")
		}
		body["credential"] = token
	}
	return body, settings, nil
}

// parseVMIDRange reads "9000-9099" into the two settings the driver keeps,
// because one flag for a range is what people type and two numbers that can
// disagree is what the row stores.
func parseVMIDRange(s string) (lo, hi string, err error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "9000", "9099", nil
	}
	a, b, ok := strings.Cut(s, "-")
	if !ok {
		return "", "", fmt.Errorf("--vmid-range %q is not a range; write it as 9000-9099", s)
	}
	a, b = strings.TrimSpace(a), strings.TrimSpace(b)
	lo64, errA := strconv.Atoi(a)
	hi64, errB := strconv.Atoi(b)
	switch {
	case errA != nil || errB != nil:
		return "", "", fmt.Errorf("--vmid-range %q is not two numbers; write it as 9000-9099", s)
	case lo64 > hi64:
		return "", "", fmt.Errorf("--vmid-range %q runs backwards; the lower VMID comes first", s)
	}
	return a, b, nil
}

// providersAdd is `zoomies providers add <kind>`: the wizard in one command.
//
// It runs the same dry run the wizard's review step does before it writes
// anything, so a typo is refused with a field name and no row; then it
// creates the provider; then it runs the live preflight and prints what the
// cluster would refuse, in the same words the page uses. A provider is
// created renting nothing unless --max-machines says otherwise, for the
// reason the API gives: a connection test should not start an invoice.
func providersAdd(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers add proxmox --name <n> --endpoint <url> --nodes <n> --template <vmid> --storage <s> [flags]",
		"Add a provider from the terminal: validate the answers, save them, and ask the cluster what it would refuse.")
	cf := registerClientFlags(fs, true)
	spec := registerProviderFlags(fs)
	noCheck := fs.Bool("no-check", false, "save the provider without asking the cluster anything; `zoomies providers check` does that later")
	fs.example(
		"zoomies providers add proxmox --name proxmox-lab --endpoint https://pve.example.com:8006 \\\n"+
			"      --nodes pve1 --template 9000 --storage local-lvm --bridge vmbr0 \\\n"+
			"      --endpoint-ca-file pve-root-ca.pem --max-machines 4",
		"zoomies providers add proxmox --name lab --endpoint https://pve.home:8006 --nodes pve1,pve2 \\\n"+
			"      --template 9000 --storage ceph --vmid-range 9100-9199 --credential-file token.txt \\\n"+
			"      --gateway <address zoomies gateway printed>",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	kind, err := fs.oneArg("a provider kind, e.g. proxmox; `zoomies providers kinds` lists them")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	body, _, err := spec.body(e, fs, true)
	if err != nil {
		return err
	}
	body["kind"] = strings.ToLower(strings.TrimSpace(kind))

	// The dry run first. It is what refuses a bad answer before a row exists
	// and, unlike the POST, it lists every field that is wrong at once.
	var verdict providerValidation
	if _, err := client.post(ctx, "/providers/validate", nil, body, &verdict); err != nil {
		return err
	}
	if !verdict.Valid {
		for _, f := range verdict.Errors {
			fmt.Fprintf(e.err, "  %s: %s\n", f.Field, f.Message)
		}
		return fmt.Errorf("this provider cannot be created as described; nothing was saved. Fix what is above and run it again")
	}

	var created providerItem
	raw, err := client.post(ctx, "/providers", nil, body, &created)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	p.note("Created %s (%s), a %s provider at %s.", created.Name, created.ID, created.Kind, dash(created.Endpoint))
	printFindings(e.out, verdict.Warnings)

	if !*noCheck {
		p.note("")
		p.note("Asking %s what it would refuse...", created.Name)
		if err := checkProvider(ctx, e, p, client, created); err != nil {
			return err
		}
	}

	p.note("")
	if created.MaxMachines == 0 {
		p.note("It rents nothing yet: raise the ceiling when you are ready with\n  zoomies providers edit %s --max-machines 4", created.Name)
	} else {
		p.note("It may own up to %d machines at once. `zoomies providers pause %s` stops it buying more.", created.MaxMachines, created.Name)
	}
	return nil
}

// providersEdit is `zoomies providers edit <name|id>`: change the settings you
// name and nothing else. It exists so that the ceiling `add` left at zero can
// be raised from the same terminal, rather than the one step that spends money
// being the one that needs a browser.
func providersEdit(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers edit <name|id> [flags]",
		"Change the settings you name on a provider and leave the rest alone.")
	cf := registerClientFlags(fs, true)
	spec := registerProviderFlags(fs)
	fs.example(
		"zoomies providers edit proxmox-lab --max-machines 8",
		"zoomies providers edit proxmox-lab --credential-file token.txt",
		"zoomies providers edit proxmox-lab --endpoint-ca-file pve-root-ca.pem --endpoint-insecure=false",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	ref, err := fs.oneArg("a provider name or ID")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	body, settings, err := spec.body(e, fs, false)
	if err != nil {
		return err
	}
	if len(body) == 0 && len(settings) == 0 {
		return usagef(fs.Name(), "nothing to change; name at least one setting, e.g. --max-machines 4")
	}
	provider, err := resolveProvider(ctx, client, ref)
	if err != nil {
		return err
	}
	if len(settings) > 0 {
		merged := map[string]string{}
		for k, v := range provider.Settings {
			merged[k] = v
		}
		for k, v := range settings {
			merged[k] = v
		}
		body["settings"] = merged
	}

	var out providerItem
	raw, err := client.patch(ctx, "/providers/"+url.PathEscape(provider.ID), nil, body, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	p.note("Updated %s.", out.Name)
	if out.Held != "" {
		p.note("It is buying nothing right now: %s", out.Held)
	} else if out.MaxMachines > 0 {
		p.note("It may own up to %d machines at once.", out.MaxMachines)
	}
	return nil
}

// checkProvider runs the live preflight and prints it with printFindings, so
// the terminal and the wizard say the same words about the same provider. It
// returns an error when something found would stop a machine being created.
func checkProvider(ctx context.Context, e *env, p *printer, client *apiClient, provider providerItem) error {
	var report providerCheckItem
	if _, err := client.post(ctx, "/providers/"+url.PathEscape(provider.ID)+"/check", nil, nil, &report); err != nil {
		return err
	}
	if !report.Reachable {
		p.note("%s could not be reached at %s.", provider.Name, dash(provider.Endpoint))
	} else if report.Version != "" {
		p.note("%s answered: %s.", provider.Name, report.Version)
	}
	printFindings(e.out, report.Findings)
	if !report.OK {
		return fmt.Errorf("%s would refuse to create a machine as configured; fix what is above and run `zoomies providers check %s`", provider.Name, provider.Name)
	}
	if n := len(config.Findings(report.Findings).Warnings()); n > 0 {
		p.note("%s is usable, with %s above.", provider.Name, pluralWarnings(n))
		return nil
	}
	p.note("%s is usable and nothing above weakens the defaults.", provider.Name)
	return nil
}

// providersKinds is `zoomies providers kinds`: what this build can rent from,
// and the settings each driver asks for, so that --setting has a list to
// choose from without opening the wizard.
func providersKinds(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies providers kinds", "List the kinds of provider this build can add, and the settings each one asks for.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	var out listResponse[providerKindItem]
	raw, err := client.get(ctx, "/providers/kinds", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	for i, k := range out.Items {
		if i > 0 {
			p.note("")
		}
		p.note("%s  (%s)", k.Kind, k.Label)
		rows := make([][]string, 0, len(k.Settings))
		for _, s := range k.Settings {
			need := "optional"
			if s.Required {
				need = "required"
			}
			rows = append(rows, []string{s.Key, s.Kind, need, dash(s.Default), s.Help})
		}
		p.table([]string{"setting", "type", "", "default", "what it is"}, rows)
	}
	return nil
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
)

// providerAddServer is a controller that accepts the wizard's three calls --
// validate, create, check -- and records the bodies it was sent, so a test
// can say what the terminal turned the flags into.
type providerAddServer struct {
	mu       sync.Mutex
	validate map[string]any
	created  map[string]any
	patched  map[string]any
	checked  bool
	verdict  string
	check    string
}

func newProviderAddServer(t *testing.T) (*httptest.Server, *providerAddServer) {
	t.Helper()
	rec := &providerAddServer{
		verdict: `{"valid":true,"errors":[],"warnings":[]}`,
		check:   `{"provider_id":"prv_new","ok":true,"reachable":true,"version":"pve-manager/8.2.2","findings":[],"checked_at":"2026-09-14T10:00:00Z"}`,
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		rec.mu.Lock()
		defer rec.mu.Unlock()
		body := map[string]any{}
		if r.Body != nil {
			raw, _ := io.ReadAll(r.Body)
			_ = json.Unmarshal(raw, &body)
		}
		switch {
		case r.Method == http.MethodPost && r.URL.Path == "/api/v1/providers/validate":
			rec.validate = body
			_, _ = w.Write([]byte(rec.verdict))
		case r.Method == http.MethodPost && r.URL.Path == "/api/v1/providers":
			rec.created = body
			w.WriteHeader(http.StatusCreated)
			_, _ = w.Write([]byte(`{"id":"prv_new","kind":"proxmox","name":"proxmox-lab","endpoint":"https://pve.example.com:8006",
				"credentials_configured":true,"max_machines":` + jsonNumber(body["max_machines"]) + `,"enabled":true,"paused":false,"machines":{},"owned":0}`))
		case r.Method == http.MethodPost && r.URL.Path == "/api/v1/providers/prv_new/check":
			rec.checked = true
			_, _ = w.Write([]byte(rec.check))
		case r.Method == http.MethodGet && r.URL.Path == "/api/v1/providers":
			_, _ = w.Write([]byte(`{"items":[{"id":"prv_new","kind":"proxmox","name":"proxmox-lab","endpoint":"https://pve.example.com:8006",
				"settings":{"nodes":"pve1","template_id":"9000","storage":"local-lvm","bridge":"vmbr0","vmid_min":"9000","vmid_max":"9099"},
				"credentials_configured":true,"max_machines":0,"enabled":true,"paused":false,"machines":{},"owned":0}]}`))
		case r.Method == http.MethodPatch && r.URL.Path == "/api/v1/providers/prv_new":
			rec.patched = body
			_, _ = w.Write([]byte(`{"id":"prv_new","kind":"proxmox","name":"proxmox-lab","endpoint":"https://pve.example.com:8006",
				"credentials_configured":true,"max_machines":8,"enabled":true,"paused":false,"machines":{},"owned":0}`))
		default:
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
			w.WriteHeader(http.StatusNotFound)
		}
	}))
	t.Cleanup(srv.Close)
	return srv, rec
}

func jsonNumber(v any) string {
	if v == nil {
		return "0"
	}
	raw, _ := json.Marshal(v)
	return string(raw)
}

// The point of the command is that the five-step wizard becomes one line, so
// the test is that one line turns into the same request the wizard would send:
// the Proxmox questions land in the driver's settings under the keys the
// driver reads, the token pasted on standard input becomes the credential, and
// the cluster is asked what it would refuse before the terminal says done.
func TestAddingAProviderSendsTheWizardsRequestFromOneLine(t *testing.T) {
	srv, rec := newProviderAddServer(t)
	e, out, errOut := newTestEnv(t)
	e.in = strings.NewReader("zoomies@pve!ci=secret-token\n")

	code := dispatch(context.Background(), e, []string{"providers", "add", "proxmox", "--url", srv.URL,
		"--name", "proxmox-lab", "--endpoint", "https://pve.example.com:8006",
		"--nodes", "pve1,pve2", "--template", "9000", "--storage", "local-lvm",
		"--vmid-range", "9100-9199", "--labels", "arch=amd64", "--max-machines", "4",
		"--setting", "pool=zoomies"})
	if code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}

	rec.mu.Lock()
	defer rec.mu.Unlock()
	if rec.validate == nil {
		t.Fatal("the draft was not validated before it was saved")
	}
	if rec.created == nil {
		t.Fatal("no provider was created")
	}
	if !rec.checked {
		t.Error("the new provider was not asked what it would refuse")
	}
	settings, _ := rec.created["settings"].(map[string]any)
	for key, want := range map[string]string{
		"nodes": "pve1,pve2", "template_id": "9000", "storage": "local-lvm", "bridge": "vmbr0",
		"vmid_min": "9100", "vmid_max": "9199", "pool": "zoomies",
	} {
		if got, _ := settings[key].(string); got != want {
			t.Errorf("settings[%q] = %q, want %q", key, got, want)
		}
	}
	if got := rec.created["credential"]; got != "zoomies@pve!ci=secret-token" {
		t.Errorf("credential = %v, want the token read from standard input", got)
	}
	if got := rec.created["kind"]; got != "proxmox" {
		t.Errorf("kind = %v", got)
	}
	if got := rec.created["max_machines"]; got != float64(4) {
		t.Errorf("max_machines = %v, want 4", got)
	}
	if got := rec.created["connection"]; got != "direct" {
		t.Errorf("connection = %v, want direct", got)
	}
	labels, _ := rec.created["machine_labels"].(map[string]any)
	if labels["arch"] != "amd64" {
		t.Errorf("machine_labels = %v", labels)
	}
	text := out.String()
	for _, want := range []string{"Created proxmox-lab (prv_new)", "pve-manager/8.2.2", "up to 4 machines"} {
		if !strings.Contains(text, want) {
			t.Errorf("the output does not say %q:\n%s", want, text)
		}
	}
	if strings.Contains(text, "secret-token") || strings.Contains(errOut.String(), "secret-token") {
		t.Error("the token was echoed")
	}
}

// A provider created with the ceiling left at zero rents nothing, which is the
// API's safe default and easy to miss from a terminal. The command says so,
// and names the command that raises it, so the one step that spends money does
// not need a browser.
func TestAddingAProviderWithNoCeilingSaysItRentsNothing(t *testing.T) {
	srv, _ := newProviderAddServer(t)
	e, out, errOut := newTestEnv(t)
	e.in = strings.NewReader("zoomies@pve!ci=secret\n")

	code := dispatch(context.Background(), e, []string{"providers", "add", "proxmox", "--url", srv.URL,
		"--name", "proxmox-lab", "--endpoint", "https://pve.example.com:8006",
		"--nodes", "pve1", "--template", "9000", "--storage", "local-lvm", "--no-check"})
	if code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	text := out.String()
	if !strings.Contains(text, "rents nothing yet") || !strings.Contains(text, "zoomies providers edit proxmox-lab --max-machines") {
		t.Errorf("the output does not say the ceiling is zero and how to raise it:\n%s", text)
	}
}

// The dry run is what makes a typo cheap: every wrong field is named at once
// and nothing is written, so the operator fixes the line rather than deleting
// a half-made provider.
func TestAddingAProviderTheValidatorRefusesSavesNothing(t *testing.T) {
	srv, rec := newProviderAddServer(t)
	rec.verdict = `{"valid":false,"errors":[{"field":"settings.template_id","message":"the template VMID is required"},
		{"field":"endpoint","message":"\"pve\" is not an address this controller can reach"}],"warnings":[]}`
	e, _, errOut := newTestEnv(t)
	e.in = strings.NewReader("zoomies@pve!ci=secret\n")

	code := dispatch(context.Background(), e, []string{"providers", "add", "proxmox", "--url", srv.URL,
		"--name", "proxmox-lab", "--endpoint", "pve", "--nodes", "pve1", "--storage", "local-lvm"})
	if code == exitOK {
		t.Fatal("a draft the validator refused was accepted")
	}
	rec.mu.Lock()
	defer rec.mu.Unlock()
	if rec.created != nil {
		t.Error("a provider was created from a draft the validator refused")
	}
	text := errOut.String()
	for _, want := range []string{"settings.template_id: the template VMID is required", "endpoint:", "nothing was saved"} {
		if !strings.Contains(text, want) {
			t.Errorf("the error does not say %q:\n%s", want, text)
		}
	}
}

// A live check that fails still leaves the provider saved: the row is right and
// the cluster is what needs fixing, so the exit code says so and the message
// names the command to run once it is.
func TestAddingAProviderTheClusterWouldRefuseExitsNonZeroButKeepsIt(t *testing.T) {
	srv, rec := newProviderAddServer(t)
	rec.check = `{"provider_id":"prv_new","ok":false,"reachable":true,"version":"pve-manager/8.2.2",
		"findings":[{"severity":"error","code":"provider.proxmox.privilege_missing","title":"the token lacks VM.Clone on /vms/9000","fix":"grant VM.Clone to zoomies@pve!ci on /vms/9000"}],
		"checked_at":"2026-09-14T10:00:00Z"}`
	e, out, errOut := newTestEnv(t)
	e.in = strings.NewReader("zoomies@pve!ci=secret\n")

	code := dispatch(context.Background(), e, []string{"providers", "add", "proxmox", "--url", srv.URL,
		"--name", "proxmox-lab", "--endpoint", "https://pve.example.com:8006",
		"--nodes", "pve1", "--template", "9000", "--storage", "local-lvm"})
	if code == exitOK {
		t.Fatal("a provider the cluster would refuse exited zero")
	}
	rec.mu.Lock()
	created := rec.created != nil
	rec.mu.Unlock()
	if !created {
		t.Error("the provider should have been saved before the check ran")
	}
	if !strings.Contains(out.String(), "VM.Clone") {
		t.Errorf("the finding was not printed:\n%s", out)
	}
	if !strings.Contains(errOut.String(), "zoomies providers check proxmox-lab") {
		t.Errorf("the error does not name the command to run again:\n%s", errOut)
	}
}

// The token and the certificate are files as often as they are pasted, and a
// token read from a file must not be asked for again on the terminal.
func TestAddingAProviderReadsTheTokenAndCertificateFromFiles(t *testing.T) {
	srv, rec := newProviderAddServer(t)
	dir := t.TempDir()
	tokenFile := filepath.Join(dir, "token")
	caFile := filepath.Join(dir, "ca.pem")
	if err := os.WriteFile(tokenFile, []byte("zoomies@pve!ci=from-file\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(caFile, []byte("-----BEGIN CERTIFICATE-----\nabc\n-----END CERTIFICATE-----\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	e, _, errOut := newTestEnv(t)
	// Nothing on standard input: a prompt that fired would read "" and fail.
	e.in = &bytes.Buffer{}

	code := dispatch(context.Background(), e, []string{"providers", "add", "proxmox", "--url", srv.URL,
		"--name", "proxmox-lab", "--endpoint", "https://pve.example.com:8006",
		"--nodes", "pve1", "--template", "9000", "--storage", "local-lvm",
		"--credential-file", tokenFile, "--endpoint-ca-file", caFile, "--gateway", "tc-abc123", "--no-check"})
	if code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}
	rec.mu.Lock()
	defer rec.mu.Unlock()
	if got := rec.created["credential"]; got != "zoomies@pve!ci=from-file" {
		t.Errorf("credential = %v, want the file's contents trimmed", got)
	}
	if got, _ := rec.created["ca_pem"].(string); !strings.Contains(got, "BEGIN CERTIFICATE") {
		t.Errorf("ca_pem = %q", got)
	}
	if rec.created["connection"] != "tailcat" || rec.created["tailcat_address"] != "tc-abc123" {
		t.Errorf("a --gateway should make the connection private: %v", rec.created)
	}
}

// An edit sends what was typed and nothing else, and a driver setting it names
// is merged over the row's rather than replacing them: the API takes the whole
// map, and an operator changing the storage did not ask to lose the nodes.
func TestEditingAProviderSendsOnlyWhatChangedAndKeepsTheOtherSettings(t *testing.T) {
