package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// remoteNamed resolves one destination from everything this host can see.
//
// The database is opened read-only and its failure is not fatal: this command
// is most useful on a host whose database is gone, and the destinations that
// still work there are the ones zoomies.yaml describes. A destination stored
// in the database is found when there is a database to find it in, which is
// the ordinary case of restoring one fleet's backup onto another host.
func remoteNamed(ctx context.Context, cfg *config.Config, name string) (*backup.Remote, error) {
	var rows *store.Store
	if st, err := store.Open(ctx, store.Options{Path: cfg.Database.Path, ReadOnly: true}); err == nil {
		defer func() { _ = st.Close() }()
		rows = st
	}
	key, err := backup.ConfiguredKey(cfg)
	if err != nil {
		key = nil
	}
	var lister backup.RemoteLister
	if rows != nil {
		lister = rows
	}
	resolved, err := backup.FindResolvedRemote(ctx, cfg, lister, key, name)
	if err != nil {
		return nil, err
	}
	return backup.NewRemote(resolved.Remote, nil)
}

// listRemoteCopies prints what one remote holds. It is what `zoomies restore
// --from-remote offsite` with no id does, because the alternative on a machine
// that has lost everything is an operator guessing at timestamps.
func listRemoteCopies(ctx context.Context, e *env, cfg *config.Config, name string) error {
	remote, err := remoteNamed(ctx, cfg, name)
	if err != nil {
		return err
	}
	copies, err := remote.List(ctx)
	if err != nil {
		return err
	}
	if len(copies) == 0 {
		fmt.Fprintf(e.out, "%s holds no backups of this fleet.\n", remote.Where())
		return nil
	}
	fmt.Fprintf(e.out, "%s holds %s:\n\n", remote.Where(), countOf(len(copies), "backup"))
	for _, c := range copies {
		sealed := ""
		if c.Encrypted {
			sealed = ", encrypted"
		}
		fmt.Fprintf(e.out, "  %s  %s  taken %s%s\n",
			c.ID, humanBytes(int(c.Bytes)), c.TakenAt.Format(time.RFC3339), sealed)
	}
	fmt.Fprintf(e.out, "\nRestore one with:\n  zoomies restore --from-remote %s %s --replace\n",
		name, copies[0].ID)
	return nil
}

// fetchFromRemote brings one copy back into the backup directory, where it is
// an ordinary backup that the rest of this command restores exactly as it
// restores one that was already there.
func fetchFromRemote(ctx context.Context, e *env, cfg *config.Config, name, id, passphrase string) (*backup.Entry, error) {
	remote, err := remoteNamed(ctx, cfg, name)
	if err != nil {
		return nil, err
	}
	if id == "latest" {
		copies, err := remote.List(ctx)
		if err != nil {
			return nil, err
		}
		if len(copies) == 0 {
			return nil, fmt.Errorf("%s holds no backups of this fleet", remote.Where())
		}
		id = copies[0].ID
	}
	fmt.Fprintf(e.out, "Fetching %s from %s...\n", id, remote.Where())
	entry, err := remote.Fetch(ctx, backup.Dir(cfg), id, backup.FetchOptions{
		Passphrase: passphrase, TakenBy: "zoomies restore --from-remote " + name,
	})
	if err != nil {
		return nil, err
	}
	fmt.Fprintf(e.out, "Fetched to %s (%s), verified.\n\n", entry.Dir, humanBytes(int(entry.Bytes)))
	return entry, nil
}

// restorePassphrase resolves the passphrase a fetched copy was sealed with.
//
// The file is the way to give it: a flag's value is in the shell history and
// readable from /proc/<pid>/cmdline for as long as the download runs, and this
// is the passphrase that opens the whole fleet's database copy. --passphrase
// keeps working, because a disaster-recovery script is the last thing to
// break on an upgrade, but it says so on stderr and is refused beside the file
// rather than one silently winning.
func restorePassphrase(e *env, flagValue, file string) (string, error) {
	if flagValue != "" && file != "" {
		return "", errors.New("give the backup passphrase with --passphrase-file, not both it and --passphrase")
	}
	if flagValue != "" {
		fmt.Fprintln(e.err, "zoomies: --passphrase is deprecated, because its value stays in the shell history and the "+
			"process list. Put the passphrase in a file and use --passphrase-file instead.")
		return flagValue, nil
	}
	return readPassphraseFile(file)
}

// runRestore is `zoomies restore <backup-directory>`.
//
// Every check and every refusal lives in internal/backup, shared with the
// restore the settings page stages: the command adds the lock, the flags and
// the words. It restores the database and nothing else. The encryption key,
// the configuration and the service unit are the operator's to put back,
// because each of them is a decision about this host rather than a copy of the
// data.
func runRestore(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies restore <backup-directory> [--replace]",
		"Put a backup's database in place, invalidating the credentials it froze and fencing the fleet.")
	cfgPath := fs.String("config", "", "path to zoomies.yaml (default: "+config.DefaultConfigFile()+")")
	replace := fs.Bool("replace", false, "overwrite the database already at database.path, keeping a copy of it first")
	revokeTokens := fs.Bool("revoke-api-tokens", false, "revoke every API token as well; they are valid credentials the backup froze")
	resetAgents := fs.Bool("reset-agent-tokens", false, "forget every host's agent credential, so each agent joins again")
	from := fs.String("from-remote", "", "bring the copy back from this backup remote first; the argument is then a backup id, or `latest`, and naming no backup lists what the remote holds")
	passphrase := fs.String("passphrase", "", "deprecated: use --passphrase-file; a flag's value is in the shell history and the process list")
	passFile := fs.String("passphrase-file", "", "a file holding the passphrase that copy was sealed with, when it is not the one in backup.remotes")
	fs.example("zoomies restore /var/backups/zoomies/zoomies-20260908-181718",
		"zoomies restore /var/backups/zoomies/zoomies-20260908-181718 --replace",
		"zoomies restore --from-remote offsite",
		"zoomies restore --from-remote offsite latest --replace",
		"zoomies restore --from-remote offsite latest --passphrase-file ./backup.pass --replace",
		"zoomies restore ... --revoke-api-tokens --reset-agent-tokens")
	if err := fs.parse(args); err != nil {
		return err
	}
	sealedWith, err := restorePassphrase(e, *passphrase, *passFile)
	if err != nil {
		return err
	}

	cfg, err := config.Load(*cfgPath)
	if err != nil {
		return err
	}

	var src string
	if *from != "" {
		// The disaster path: a host with the configuration file, the key, and
		// nothing else. Naming no backup lists what is there rather than
		// failing, because an operator standing in front of an empty machine
		// has no way to know the ids.
		if fs.NArg() == 0 {
			return listRemoteCopies(ctx, e, cfg, *from)
		}
		id, err := fs.oneArg("the backup id to bring back, or `latest`")
		if err != nil {
			return err
		}
		entry, err := fetchFromRemote(ctx, e, cfg, *from, id, sealedWith)
		if err != nil {
			return err
		}
		src = entry.Dir
	} else {
		if src, err = fs.oneArg("the backup directory to restore"); err != nil {
			return err
		}
	}
	if _, err := os.Stat(filepath.Join(src, backup.DBName)); err != nil {
		return fmt.Errorf("%s does not look like a Zoomies backup: %w", src, err)
	}

	live := cfg.Database.Path

	// Nothing moves under a running controller. This is the same lock a
	// controller takes before it opens the database, so holding it for the rest
	// of the restore both proves none is running now and stops one starting
	// halfway through the swap.
	//
	// The check earns its place because the damage it prevents is silent.
	// Renaming a file does not reach a process that already has it open: a live
	// controller goes on reading the database that was moved aside, every
	// connection it opens after the swap reads the restored one instead, and
	// the writes it makes in between land in the file nobody will look at
	// again. Nothing fails at the time, and what is lost is whatever the fleet
	// did during the restore.
	//
	// The directory is created first because the lock sits beside the database,
	// and restoring onto a host that has never run one is the ordinary case.
	if err := os.MkdirAll(filepath.Dir(live), 0o750); err != nil {
		return fmt.Errorf("creating %s: %w", filepath.Dir(live), err)
	}
	unlock, err := store.Lock(live)
	if err != nil {
		if errors.Is(err, store.ErrLocked) {
			return fmt.Errorf("a controller is running on %s, and restoring under it would lose "+
				"whatever the fleet does while the file is being replaced. Stop the controller "+
				"(systemctl stop zoomies), restore, then start it again", live)
		}
		return fmt.Errorf("checking whether a controller is running on %s: %w", live, err)
	}
	defer func() { _ = unlock() }()

	report, err := backup.Restore(ctx, cfg, src, backup.RestoreOptions{
		Replace: *replace, RevokeAPITokens: *revokeTokens, ResetAgentTokens: *resetAgents,
	})
	if err != nil {
		return err
	}
	printRestoreReport(e, report, live)
	return nil
}

// printRestoreReport is the restore's own words, in the order things happened.
func printRestoreReport(e *env, report *backup.RestoreReport, live string) {
	if report.KeyChecked {
		fmt.Fprintf(e.out, "The encryption key on this host matches the backup.\n")
	}
	if report.MovedAside != "" {
		fmt.Fprintf(e.out, "Moved the database that was there to %s\n", report.MovedAside)
	}
	if len(report.MovedLogs) > 0 {
		fmt.Fprintf(e.out, "Moved a write-ahead log that had outlived its database to %s\n", strings.Join(report.MovedLogs, ", "))
	}
	fmt.Fprintf(e.out, "Restored %s to %s\n\n", report.Source, live)
	if report.ManifestProblem != "" {
		fmt.Fprintf(e.out, "There was no readable manifest in the backup (%s), so the key fingerprint\n"+
			"and the build that wrote it could not be checked. The database itself passed its integrity check.\n\n", report.ManifestProblem)
	}
	for _, line := range report.Invalidated {
		// The command has flags the page does not, so the sentence that
		// offers the choice names them here.
		line = strings.Replace(line, "may have been read by anyone else, revoke them.", "may have been read by anyone else, re-run with --revoke-api-tokens.", 1)
		fmt.Fprintln(e.out, line)
	}
	fmt.Fprintf(e.out, "\nMarked the restored database for recovery (%s), with the reason above.\n"+
		"Before you start the controller, check the three things a restore does not bring with it:\n"+
		"the external URL this fleet answers on, the agents, and the runners that were live when the\n"+
		"backup was taken. docs/backup-and-restore.md walks through each.\n", store.SettingRecoveryFenced)
}

package main

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The passphrase that opens an offsite backup protects the whole fleet's
// database copy. As a flag value it is in the shell history and readable from
// /proc/<pid>/cmdline for as long as the download runs, which on a large bucket
// is minutes, on a host that during disaster recovery is often shared. Every
// other command that takes a passphrase reads it from a file.
func TestRestoreRefusesAPassphraseGivenBothWays(t *testing.T) {
	file := filepath.Join(t.TempDir(), "backup.pass")
	if err := os.WriteFile(file, []byte("correct horse\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	e, _, errOut := newTestEnv(t)
	code := dispatch(context.Background(), e, []string{"restore", "--from-remote", "offsite", "latest",
		"--passphrase", "correct horse", "--passphrase-file", file})
	if code != exitError {
		t.Fatalf("exit code = %d, want %d\n%s", code, exitError, errOut)
	}
	if !strings.Contains(errOut.String(), "not both") {
		t.Errorf("the refusal does not say only one may be given:\n%s", errOut)
	}
}

func TestRestorePassphraseFileMustHoldAPassphrase(t *testing.T) {
	file := filepath.Join(t.TempDir(), "empty.pass")
	if err := os.WriteFile(file, []byte("\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	e, _, errOut := newTestEnv(t)
	code := dispatch(context.Background(), e, []string{"restore", "--from-remote", "offsite", "latest",
		"--passphrase-file", file})
	if code != exitError {
		t.Fatalf("exit code = %d, want %d\n%s", code, exitError, errOut)
	}
	if !strings.Contains(errOut.String(), "is empty") {
		t.Errorf("an empty passphrase file was not refused as such:\n%s", errOut)
	}
}

func TestRestorePassphraseComesFromItsFileWithoutTheTrailingNewline(t *testing.T) {
	file := filepath.Join(t.TempDir(), "backup.pass")
	if err := os.WriteFile(file, []byte("correct horse\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	e, _, errOut := newTestEnv(t)
	got, err := restorePassphrase(e, "", file)
	if err != nil {
		t.Fatal(err)
	}
	if got != "correct horse" {
		t.Errorf("passphrase = %q, want the file's contents without its newline", got)
	}
	if errOut.Len() != 0 {
		t.Errorf("reading the file warned about something:\n%s", errOut)
	}
}

// Scripts written against the old flag keep working for a release, but they
// are told, on stderr, that the value they pass is being exposed.
func TestRestorePassphraseFlagStillWorksButIsDeprecated(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	got, err := restorePassphrase(e, "correct horse", "")
	if err != nil {
		t.Fatal(err)
	}
	if got != "correct horse" {
		t.Errorf("passphrase = %q, want the flag's value", got)
	}
	if !strings.Contains(errOut.String(), "--passphrase-file") || !strings.Contains(errOut.String(), "deprecated") {
		t.Errorf("no deprecation notice pointing at --passphrase-file:\n%s", errOut)
	}
}

package main

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// takeBackup runs `zoomies backup` on the host prepared by backupHost and
// returns the directory it wrote. Restoring what this command actually
// produces, rather than a fixture shaped like it, is the point: the two halves
// have to agree about the manifest and the file names.
func takeBackup(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"backup", "--dir", root}); code != exitOK {
		t.Fatalf("backup exit code = %d\n%s", code, errOut)
	}
	return onlyBackup(t, root)
}

// The database at database.path is the fleet. Overwriting it because somebody
// typed a command is the one mistake a restore must not make on its own, and
// the copy it moves aside is what makes --replace recoverable.
func TestRestoreWillNotOverwriteADatabaseWithoutBeingTold(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)
	live := filepath.Join(dir, "zoomies.db")

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src}); code != exitError {
		t.Fatalf("restore over a live database exit code = %d, want %d", code, exitError)
	}
	if !strings.Contains(errOut.String(), "--replace") {
		t.Errorf("the refusal does not name the flag that allows it:\n%s", errOut)
	}

	e2, out, errOut2 := newTestEnv(t)
	if code := dispatch(context.Background(), e2, []string{"restore", src, "--replace"}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut2)
	}
	// The database that was there is beside it, not gone: a restore of the
	// wrong backup is survivable only if the old one is still on disk.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	var kept bool
	for _, en := range entries {
		if strings.HasPrefix(en.Name(), "zoomies.db.before-restore-") {
			kept = true
		}
	}
	if !kept {
		t.Errorf("--replace deleted the database that was there; %v", entries)
	}
	if !strings.Contains(out.String(), "Moved the database that was there") {
		t.Errorf("the summary does not say where the old database went:\n%s", out)
	}
	if _, err := os.Stat(live); err != nil {
		t.Errorf("nothing was restored to %s: %v", live, err)
	}
}

// A key that does not open the restored database produces a fleet that starts,
// reports itself healthy and fails inside its first GitHub call -- by which
// time the original may be gone. The fingerprint in the manifest is what lets
// this be caught before anything is moved.
func TestRestoreRefusesAKeyThatDidNotSealTheBackup(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)

	// A different key on this host, and the live database out of the way so
	// the key check is the only thing that can refuse.
	other, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatal(err)
	}
	wrong := filepath.Join(dir, "wrong.key")
	if err := cryptox.WriteKeyFile(wrong, other); err != nil {
		t.Fatal(err)
	}
	t.Setenv("ZOOMIES_ENCRYPTION_KEY_FILE", wrong)
	live := filepath.Join(dir, "zoomies.db")
	if err := os.Remove(live); err != nil {
		t.Fatal(err)
	}

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src}); code != exitError {
		t.Fatalf("exit code = %d, want %d", code, exitError)
	}
	// Both fingerprints, because the operator's next act is to go and find the
	// right key and they need to know what they are looking for.
	for _, want := range []string{other.Fingerprint(), "not the one that sealed this backup"} {
		if !strings.Contains(errOut.String(), want) {
			t.Errorf("the refusal does not mention %q:\n%s", want, errOut)
		}
	}
	if _, err := os.Stat(live); !os.IsNotExist(err) {
		t.Error("the refusal happened after the database had already been put in place")
	}
}

// A backup that did not survive being copied somewhere is worse than no backup,
// because it is restored with confidence. The check happens before anything is
// moved, while the original is still there.
func TestRestoreRefusesACopyThatIsNotSound(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)

	// Truncating is what a half-finished transfer looks like.
	whole, err := os.ReadFile(filepath.Join(src, backupDBName))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(src, backupDBName), whole[:len(whole)/3], 0o600); err != nil {
		t.Fatal(err)
	}

	live := filepath.Join(dir, "zoomies.db")
	before, err := os.ReadFile(live)
	if err != nil {
		t.Fatal(err)
	}

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src, "--replace"}); code != exitError {
		t.Fatalf("a truncated backup was restored; exit code = %d", code)
	}
	after, err := os.ReadFile(live)
	if err != nil || len(after) != len(before) {
		t.Errorf("the live database was touched before the copy had been checked: %v", err)
	}
	if errOut.Len() == 0 {
		t.Error("the refusal said nothing")
	}
}

// The credentials a backup froze are still valid when it is restored, and a
// cookie from the day it was taken signs somebody in. What is a default and
// what is a flag is the judgement here: ending sessions costs a sign-in, and
// revoking API tokens breaks whatever automation holds one.
func TestRestoreInvalidatesTheCredentialsTheBackupFroze(t *testing.T) {
	dir, _ := backupHost(t)
	ctx := context.Background()
	live := filepath.Join(dir, "zoomies.db")

	// A session, an unredeemed join token, a redeemed one, and an API token,
	// all of them in the backup because they are in the database when it is
	// taken.
	st, err := store.Open(ctx, store.Options{Path: live})
	if err != nil {
		t.Fatal(err)
	}
	user := &store.User{Username: "ops", Role: store.RoleAdmin, PasswordHash: "x"}
	if err := st.CreateUser(ctx, user); err != nil {
		t.Fatal(err)
	}
	if err := st.CreateSession(ctx, &store.Session{UserID: user.ID, TokenHash: "sess", ExpiresAt: st.Now().Add(time.Hour)}); err != nil {
		t.Fatal(err)
	}
	if err := st.CreateJoinToken(ctx, &store.JoinToken{TokenHash: "unused", ExpiresAt: st.Now().Add(time.Hour)}); err != nil {
		t.Fatal(err)
	}
	if err := st.CreateAPIToken(ctx, &store.APIToken{Name: "ci", Role: store.RoleViewer, TokenHash: "api"}); err != nil {
		t.Fatal(err)
	}
	if err := st.Close(); err != nil {
		t.Fatal(err)
	}

	src := takeBackup(t)
	e, out, errOut := newTestEnv(t)
	if code := dispatch(ctx, e, []string{"restore", src, "--replace"}); code != exitOK {
		t.Fatalf("exit code = %d\n%s", code, errOut)
	}

	restored, err := store.Open(ctx, store.Options{Path: live})
	if err != nil {
		t.Fatal(err)
	}
	defer restored.Close()

	if _, _, err := restored.GetSessionByTokenHash(ctx, "sess"); err == nil {
		t.Error("a session survived the restore, so a cookie from the day of the backup is still signed in")
	}
	joins, err := restored.ListJoinTokens(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(joins) != 0 {
		t.Errorf("an unredeemed join token survived the restore: %+v", joins)
	}
	// API tokens are a flag, not a default: revoking them breaks automation,
	// and that is the operator's call rather than this command's.
	tokens, err := restored.ListAPITokens(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(tokens) != 1 || tokens[0].Revoked {
		t.Errorf("the API token was revoked without being asked for: %+v", tokens)
	}
	if !strings.Contains(out.String(), "--revoke-api-tokens") {
		t.Errorf("the summary does not offer the flag that would revoke them:\n%s", out)
	}

	// And the restored database says it is in recovery, with a reason naming
	// where it came from.
	fence, err := restored.RecoveryFenced(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !fence.Fenced {
		t.Fatal("the restored database is not marked for recovery")
	}
	if !strings.Contains(fence.Reason, src) {
		t.Errorf("the reason does not say where this came from: %q", fence.Reason)
	}
	// An audit row, in the restored database, where anyone asking why this
	// fleet is fenced will look.
	rows, _, err := restored.ListAudit(ctx, store.AuditFilter{Actions: []string{"instance.restore"}}, store.Page{Limit: 10})
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 1 {
		t.Errorf("the restore wrote %d audit rows, want 1", len(rows))
	}
}

// Restoring a backup from a later release onto an older binary is a rollback,
// which is a thing people do under pressure. The store refuses the schema and
// this names the release, before anything is moved.
func TestRestoreRefusesABackupFromANewerRelease(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)

	// A migration this build does not have, planted in the copy: what a backup
	// taken by a newer release looks like from here.
	st, err := store.Open(context.Background(), store.Options{Path: filepath.Join(src, backupDBName)})
	if err != nil {
		t.Fatal(err)
	}
	if err := st.SetSetting(context.Background(), "unused", "x", false); err != nil {
		t.Fatal(err)
	}
	if err := st.Close(); err != nil {
		t.Fatal(err)
	}
	if err := plantFutureMigration(filepath.Join(src, backupDBName)); err != nil {
		t.Fatalf("planting a future migration: %v", err)
	}

	live := filepath.Join(dir, "zoomies.db")
	before, err := os.ReadFile(live)
	if err != nil {
		t.Fatal(err)
	}

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src, "--replace"}); code != exitError {
		t.Fatalf("a backup from a newer release was restored; exit code = %d", code)
	}
	if !strings.Contains(errOut.String(), "9999_from_the_future.sql") {
		t.Errorf("the refusal does not name the migration this build lacks:\n%s", errOut)
	}
	after, err := os.ReadFile(live)
	if err != nil || len(after) != len(before) {
		t.Errorf("the live database was replaced anyway: %v", err)
	}
}

// TestRestoreRefusesWhileAControllerIsRunning covers the window in which a
// restore does its damage without failing.
//
// Renaming a file does not reach a process that already has it open. A
// controller running through a --replace goes on reading the database that was
// moved aside, every connection it opens afterwards reads the restored one
// instead, and the writes it makes in between land in the file nobody will look
// at again. Nothing errors at the time; what is lost is whatever the fleet did
// while the operator was restoring.
func TestRestoreRefusesWhileAControllerIsRunning(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)
	live := filepath.Join(dir, "zoomies.db")

	// Stand in for the running controller: it takes this same lock before it
	// opens the database, and holds it for as long as it is up.
	unlock, err := store.Lock(live)
	if err != nil {
		t.Fatalf("taking the controller's lock: %v", err)
	}
	defer func() { _ = unlock() }()

	e, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src, "--replace"}); code != exitError {
		t.Fatalf("restore under a running controller exit code = %d, want %d", code, exitError)
	}
	// The operator has to be told what to do about it, not just that it failed.
	for _, want := range []string{"controller is running", "Stop the controller"} {
		if !strings.Contains(errOut.String(), want) {
			t.Errorf("the refusal does not say %q:\n%s", want, errOut)
		}
	}
	// And it refused before touching anything.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, en := range entries {
		if strings.HasPrefix(en.Name(), "zoomies.db.before-restore-") {
			t.Errorf("the live database was moved aside despite the refusal: %s", en.Name())
		}
	}
}

// TestRestoreWorksOnceTheControllerHasStopped is the other half: the lock is a
// gate, not a wall, and it must not leave a host unable to restore because a
// controller was running when the operator first tried.
func TestRestoreWorksOnceTheControllerHasStopped(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)
	live := filepath.Join(dir, "zoomies.db")

	unlock, err := store.Lock(live)
	if err != nil {
		t.Fatalf("taking the controller's lock: %v", err)
	}
	e, _, _ := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src, "--replace"}); code != exitError {
		t.Fatalf("restore under a running controller exit code = %d, want %d", code, exitError)
	}

	// The controller stops, which is what releases the lock.
	if err := unlock(); err != nil {
		t.Fatalf("releasing the lock: %v", err)
	}

	e2, _, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e2, []string{"restore", src, "--replace"}); code != exitOK {
		t.Fatalf("restore after the controller stopped exit code = %d\n%s", code, errOut)
	}
}

// A write-ahead log that has outlived its database must not be replayed into
// the restored copy, and must not be destroyed either.
//
// This is the state restore exists to be run in: a corrupt-database recovery
// leaves the .db gone and its -wal beside it. setAsideLiveDatabase already knew
// the rule -- SQLite replays a log it finds beside a database, whatever
// database wrote it -- but it only ran when the .db was still there, so this
// path fell straight through to the copy.
//
// Two things went wrong then, and the second is the worse one. The restored
// database was opened on top of somebody else's log and came back "database
// disk image is malformed"; and the replay consumed and unlinked the log doing
// it, so the committed transactions that existed nowhere else were destroyed by
// a command that then reported failure.
func TestRestoreDoesNotReplayOrDestroyALogThatOutlivedItsDatabase(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)
	live := filepath.Join(dir, "zoomies.db")

	// The state a crash leaves: no database, a log still there. Its contents
	// stand in for the transactions only that log holds.
	if err := os.Remove(live); err != nil {
		t.Fatalf("removing the database: %v", err)
	}
	for _, ext := range []string{"-wal", "-shm"} {
		_ = os.Remove(live + ext)
	}
	const onlyCopy = "the transactions that exist nowhere else"
	walPath := live + "-wal"
	if err := os.WriteFile(walPath, []byte(onlyCopy), 0o600); err != nil {
		t.Fatalf("writing the orphan log: %v", err)
	}

	// Without --replace the operator is stopped and told why, rather than
	// finding out from a corrupt database afterwards.
	e, _, _ := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src}); code != exitError {
		t.Fatalf("restore over an orphan log exit code = %d, want %d", code, exitError)
	}
	if _, err := os.Stat(walPath); err != nil {
		t.Fatalf("the refusal removed the log anyway: %v", err)
	}

	e, out, errOut := newTestEnv(t)
	if code := dispatch(context.Background(), e, []string{"restore", src, "--replace"}); code != exitOK {
		t.Fatalf("restore --replace exit code = %d\n%s\n%s", code, out, errOut)
	}

	// The log is gone from beside the database -- otherwise the next open
	// replays it -- but it still exists, under a name the report names.
	if _, err := os.Stat(walPath); !os.IsNotExist(err) {
		t.Errorf("the log is still beside the database, so the next open replays it")
	}
	kept, err := filepath.Glob(live + ".before-restore-*-wal")
	if err != nil || len(kept) != 1 {
		t.Fatalf("the log was not kept: glob=%v err=%v", kept, err)
	}
	body, err := os.ReadFile(kept[0])
	if err != nil {
		t.Fatalf("reading the kept log: %v", err)
	}
	if string(body) != onlyCopy {
		t.Errorf("the kept log = %q, want the bytes that were there", body)
	}
	if report := out.String(); !strings.Contains(report, kept[0]) {
		t.Errorf("the report does not say where the log went:\n%s", report)
	}

	// And the restored database is sound, rather than a hybrid of two.
	st, err := store.Open(context.Background(), store.Options{Path: live})
	if err != nil {
		t.Fatalf("the restored database does not open: %v", err)
	}
	defer func() { _ = st.Close() }()
	if _, err := st.ListInstallations(context.Background()); err != nil {
		t.Errorf("the restored database does not read: %v", err)
	}
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/url"
	"strconv"
	"strings"
)

// runRunners is `zoomies runners ...`.
func runRunners(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "runners", "The runners that exist right now.", []*subcommand{
		{"list", "", "List runners, with filters", runnersList},
		{"get", "<runner-id>", "One runner in full, with its timeline", runnersGet},
		{"drain", "<runner-id>...", "Stop taking work; a job still running is given five minutes", runnersDrain},
		{"delete", "<runner-id>...", "Remove a runner and deregister it from GitHub", runnersDelete},
		{"logs", "<runner-id>", "The runner's output, optionally followed", runnersLogs},
	}, args)
}

func runnersList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies runners list [filters]", "List runners. Terminal ones are hidden unless you ask for them.")
	cf := registerClientFlags(fs, true)
	page := registerPageFlags(fs, 50)
	pools := &listValue{}
	hosts := &listValue{}
	states := &listValue{}
	fs.Var(pools, "pool", "only runners in this pool (repeatable)")
	fs.Var(hosts, "host", "only runners on this host (repeatable)")
	fs.Var(states, "state", "provisioning, registering, idle, busy, draining, removed or failed (repeatable)")
	query := fs.String("q", "", "substring match on name, ID or container ID")
	includeRemoved := fs.Bool("include-removed", false, "include runners that have finished; a busy fleet accumulates thousands")
	fs.example(
		"zoomies runners list --state busy",
		"zoomies runners list --pool pool_k3f9qz2m --output json",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	q := url.Values{}
	addList(q, "pool_id", *pools)
	addList(q, "host_id", *hosts)
	addList(q, "state", *states)
	if *query != "" {
		q.Set("q", *query)
	}
	if *includeRemoved {
		q.Set("include_removed", "true")
	}
	page.apply(q)

	var out listResponse[runnerItem]
	raw, err := client.get(ctx, "/runners", q, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No runners match. Without --include-removed, only live runners are listed.")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, r := range out.Items {
		r.sanitise()
		job := "-"
		if r.CurrentJob != nil {
			job = truncate(r.CurrentJob.Repo+" "+r.CurrentJob.JobName, 36)
		}
		rows = append(rows, []string{
			r.Name,
			r.ID,
			p.state(r.State),
			dash(r.PoolName),
			dash(r.HostName),
			job,
			p.relTime(r.CreatedAt),
		})
	}
	p.table([]string{"name", "id", "state", "pool", "host", "job", "age"}, rows)
	p.footer(len(out.Items), out.Total, out.Offset)
	return nil
}

func runnersGet(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies runners get <runner-id>", "Show one runner, its current job and how it got here.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a runner ID, as shown by `zoomies runners list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var r runnerDetail
	raw, err := client.get(ctx, "/runners/"+url.PathEscape(id), nil, &r)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	r.sanitise()

	rows := [][2]string{
		{"name", r.Name},
		{"id", r.ID},
		{"state", p.state(r.State)},
		{"pool", dash(r.PoolName)},
		{"host", dash(r.HostName)},
		{"ephemeral", p.yesNo(r.Ephemeral, false)},
		{"labels", dash(strings.Join(r.Labels, ", "))},
		{"image", dash(r.Image)},
		{"container", dash(r.ContainerID)},
		{"jobs handled", strconv.Itoa(r.JobsHandled)},
		{"created", p.relTime(r.CreatedAt)},
		{"started", p.relTimePtr(r.StartedAt)},
		{"finished", p.relTimePtr(r.FinishedAt)},
		{"logs available", p.yesNo(r.LogsAvailable, false)},
	}
	if r.CurrentJob != nil {
		rows = append(rows, [2]string{"current job", r.CurrentJob.Repo + " / " + r.CurrentJob.Workflow + " / " + r.CurrentJob.JobName})
	}
	if r.Message != "" {
		rows = append(rows, [2]string{"message", r.Message})
	}
	p.keyValues(rows)

	if len(r.Timeline) > 0 {
		fmt.Fprintln(p.out, "\nTimeline")
		tl := make([][]string, 0, len(r.Timeline))
		for _, entry := range r.Timeline {
			tl = append(tl, []string{p.state(entry.State), p.relTime(entry.At), millis(entry.DurationMS), truncate(plain(entry.Message), 48)})
		}
		p.table([]string{"state", "when", "for", "message"}, tl)
	}
	return nil
}

func runnersDrain(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies runners drain <runner-id>...",
		"Ask runners to stop taking work and exit. A job still running is given five minutes to finish and the runner is then stopped, so draining a busy runner needs --yes.")
	cf := registerClientFlags(fs, false)
	yes := fs.Bool("yes", false, confirmBusyHelp)
	fs.example("zoomies runners drain run_k3f9qz2m", "zoomies runners drain run_a run_b run_c", "zoomies runners drain run_k3f9qz2m --yes")
	if err := fs.parse(args); err != nil {
		return err
	}
	ids, err := fs.atLeastOneArg("runner ID")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}

	if len(ids) == 1 {
		var r runnerItem
		q := url.Values{}
		if *yes {
			q.Set("confirm", "true")
		}
		if _, err := client.post(ctx, "/runners/"+url.PathEscape(ids[0])+"/drain", q, nil, &r); err != nil {
			return withYesHint(err, *yes)
		}
		fmt.Fprintf(e.out, "Draining %s; it will exit once its current job finishes.\n", dash(r.Name))
		return nil
	}
	return bulkRunners(ctx, e, client, "drain", ids, false, *yes)
}

func runnersDelete(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies runners delete <runner-id>... [--force|--yes]",
		"Remove runners and deregister them from GitHub. Without --force this drains first, so removing a busy runner needs --yes.")
	cf := registerClientFlags(fs, false)
	force := fs.Bool("force", false, "destroy the runner now, interrupting any job it is running")
	yes := fs.Bool("yes", false, confirmBusyHelp)
	fs.example("zoomies runners delete run_k3f9qz2m", "zoomies runners delete run_k3f9qz2m --yes", "zoomies runners delete run_k3f9qz2m --force")
	if err := fs.parse(args); err != nil {
		return err
	}
	ids, err := fs.atLeastOneArg("runner ID")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}

	if len(ids) == 1 {
		q := url.Values{}
		if *force {
			q.Set("force", "true")
		}
		if *yes {
			q.Set("confirm", "true")
		}
		if _, err := client.del(ctx, "/runners/"+url.PathEscape(ids[0]), q, nil); err != nil {
			return withYesHint(err, *yes)
		}
		fmt.Fprintf(e.out, "Removing %s.\n", ids[0])
		return nil
	}
	return bulkRunners(ctx, e, client, "delete", ids, *force, *yes)
}

// confirmBusyHelp is shared by every command that can end a busy runner's job.
const confirmBusyHelp = "accept that a busy runner's job is stopped if it is still running after five minutes"

// asksForConfirmation reports whether a controller refusal is the busy-runner
// one, which tells the caller to send confirm=true. The CLI has no option by
// that name, so the message alone would leave an operator stuck.
func asksForConfirmation(msg string) bool {
	return strings.Contains(msg, "confirm=true")
}

// withYesHint turns the controller's "send confirm=true" refusal into the flag
// that does it, unless --yes was already given.
func withYesHint(err error, yes bool) error {
	if !yes && err != nil && asksForConfirmation(err.Error()) {
		return fmt.Errorf("%w (rerun with --yes to accept that)", err)
	}
	return err
}

// bulkRunners uses the bulk route, which answers per ID. Reporting each one is
// the point: a partial failure across twenty runners must not look like either
// a complete success or a complete failure.
//
// confirm is the operator's --yes. It is sent only when set, so the default
// stays refuse-if-busy.
func bulkRunners(ctx context.Context, e *env, client *apiClient, action string, ids []string, force, confirm bool) error {
	var out struct {
		Results []struct {
			ID    string `json:"id"`
			OK    bool   `json:"ok"`
			Error string `json:"error"`
		} `json:"results"`
	}
	body := map[string]any{"action": action, "ids": ids, "force": force}
	if confirm {
		body["confirm"] = true
	}
	if _, err := client.post(ctx, "/runners/bulk", nil, body, &out); err != nil {
		return err
	}

	failed, needConfirm := 0, false
	for _, r := range out.Results {
		if r.OK {
			fmt.Fprintf(e.out, "  %-24s ok\n", r.ID)
			continue
		}
		failed++
		needConfirm = needConfirm || (!confirm && asksForConfirmation(r.Error))
		fmt.Fprintf(e.out, "  %-24s %s\n", r.ID, r.Error)
	}
	if needConfirm {
		fmt.Fprintf(e.out, "A busy runner is only %sed with --yes, which accepts that its job is stopped after five minutes.\n",
			strings.TrimSuffix(action, "e"))
	}
	fmt.Fprintf(e.out, "%s: %d of %d succeeded.\n", action, len(out.Results)-failed, len(out.Results))
	if failed > 0 {
		return fmt.Errorf("%d runner(s) were not %sed", failed, strings.TrimSuffix(action, "e"))
	}
	return nil
}

func runnersLogs(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies runners logs <runner-id> [--follow]",
		"Print a runner's output. With --follow, keep printing it as the job produces it.")
	cf := registerClientFlags(fs, false)
	follow := fs.Bool("follow", false, "keep the stream open and print output as it arrives")
	tail := fs.Int("tail", 1000, "lines of backlog before following; 0 means everything")
	fs.example("zoomies runners logs run_k3f9qz2m", "zoomies runners logs run_k3f9qz2m --follow --tail 50")
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a runner ID")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}

	// Without --follow this is a snapshot, and the API has a route that ends by
	// itself. Reading the live stream and guessing when to stop would give a
	// truncated file and no way to tell.
	if !*follow {
		resp, err := client.stream(ctx, "/runners/"+url.PathEscape(id)+"/logs/download", nil, "text/plain")
		if err != nil {
			return explainLogError(err, id)
		}
		defer resp.Body.Close()
		if _, err := io.Copy(e.out, resp.Body); err != nil && !stopped(ctx, err) {
			return err
		}
		return nil
	}

	q := url.Values{}
	q.Set("follow", "true")
	q.Set("tail", strconv.Itoa(max(*tail, 0)))
	resp, err := client.stream(ctx, "/runners/"+url.PathEscape(id)+"/logs", q, "text/event-stream")
	if err != nil {
		return explainLogError(err, id)
	}
	defer resp.Body.Close()

	// The relay sends each chunk as a JSON string, and one "end" event when
	// the runner's output finishes -- which, for an ephemeral runner, is the
	// job ending. Stopping there is what makes this command terminate.
	err = readSSE(resp.Body, func(f sseFrame) error {
		switch f.event {
		case "log":
			var chunk string
			if err := json.Unmarshal(f.data, &chunk); err != nil {
				// A frame this client cannot read is not a reason to drop the
				// rest of the job's output.
				return nil
			}
			_, err := io.WriteString(e.out, chunk)
			return err
		case "end":
			return io.EOF
		default:
			return nil
		}
	})
	if errors.Is(err, io.EOF) || stopped(ctx, err) {
		return nil
	}
	return err
}

// explainLogError turns "404" into the two things that actually cause it.
func explainLogError(err error, id string) error {
	if notFound(err) {
		return fmt.Errorf("no output for %s: either there is no runner with that ID, or its host is not reachable, so nothing can be relayed", id)
	}
	return err
}

package main

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

// The controller refuses to drain a busy runner unless the caller says it
// understands the job is stopped after five minutes, and the help promises
// --yes as the way to say so. Without it the terminal had no way to finish a
// graceful drain: the only exit was `runners delete --force`, which is the
// harsher thing the operator was trying to avoid.
func TestYesReachesTheAPIAsConfirmOnEveryDrainAndDeletePath(t *testing.T) {
	type seen struct {
		path    string
		confirm string // "" when the query carries none
		body    map[string]any
	}
	cases := []struct {
		name string
		args []string
		want bool
	}{
		{"one runner drained with --yes", []string{"runners", "drain", "run_1", "--yes"}, true},
		{"one runner drained without --yes", []string{"runners", "drain", "run_1"}, false},
		{"one runner deleted with --yes", []string{"runners", "delete", "run_1", "--yes"}, true},
		{"one runner deleted without --yes", []string{"runners", "delete", "run_1"}, false},
		{"several runners drained with --yes", []string{"runners", "drain", "run_1", "run_2", "--yes"}, true},
		{"several runners drained without --yes", []string{"runners", "drain", "run_1", "run_2"}, false},
		{"several runners deleted with --yes", []string{"runners", "delete", "run_1", "run_2", "--yes"}, true},
		{"a host drained with --yes", []string{"hosts", "drain", "hst_a", "--yes"}, true},
		{"a host drained without --yes", []string{"hosts", "drain", "hst_a"}, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var mu sync.Mutex
			var got []seen
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "application/json")
				switch {
				case strings.HasSuffix(r.URL.Path, "/cordon"):
					_, _ = w.Write([]byte(`{"id":"hst_a","name":"vm-1","cordoned":true}`))
				case r.URL.Path == "/api/v1/runners":
					_, _ = w.Write([]byte(`{"items":[{"id":"run_1"}],"total":1}`))
				case r.URL.Path == "/api/v1/runners/bulk":
					var body map[string]any
					_ = json.NewDecoder(r.Body).Decode(&body)
					mu.Lock()
					got = append(got, seen{path: r.URL.Path, body: body})
					mu.Unlock()
					_, _ = w.Write([]byte(`{"results":[{"id":"run_1","ok":true}]}`))
				default:
					mu.Lock()
					got = append(got, seen{path: r.URL.Path, confirm: r.URL.Query().Get("confirm")})
					mu.Unlock()
					_, _ = w.Write([]byte(`{"id":"run_1","name":"r"}`))
				}
			}))
			defer srv.Close()

			e, _, errOut := newTestEnv(t)
			if code := dispatch(context.Background(), e, append(tc.args, "--url", srv.URL)); code != exitOK {
				t.Fatalf("exit code = %d\n%s", code, errOut)
			}
			mu.Lock()
			defer mu.Unlock()
			if len(got) != 1 {
				t.Fatalf("requests = %+v, want exactly one drain or delete", got)
			}
			confirmed := got[0].confirm == "true"
			if c, ok := got[0].body["confirm"]; ok {
				confirmed = c == true
				if !tc.want {
					t.Errorf("the bulk body carried confirm=%v without --yes; the default has to stay refuse-if-busy", c)
				}
			}
			if confirmed != tc.want {
				t.Errorf("confirm reached the API = %v, want %v (%+v)", confirmed, tc.want, got[0])
			}
		})
	}
}

// A 409 that says "send it again with confirm=true" is no use to someone
// whose CLI has no such option, so a refused busy runner names the flag.
func TestABusyRunnerRefusedForWantOfYesSaysToRerunWithIt(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"results":[{"id":"run_1","ok":false,"error":"runner run_1 is busy; send it again with confirm=true"}]}`))
	}))
	defer srv.Close()

	e, out, _ := newTestEnv(t)
	code := dispatch(context.Background(), e, []string{"runners", "drain", "run_1", "run_2", "--url", srv.URL})
	if code == exitOK {
		t.Fatal("a refused drain exited 0")
	}
	if !strings.Contains(out.String(), "--yes") {
		t.Errorf("the refusal does not name --yes:\n%s", out)
	}
}

