// A restore staged from the settings page is applied by the next controller
// to start, before it opens the database. The controller command runs this
// between taking the lock and opening the store, so the database it goes on
// to open is the restored one.
func TestAStagedRestoreIsAppliedBeforeTheDatabaseIsOpened(t *testing.T) {
	dir, _ := backupHost(t)
	src := takeBackup(t)
	ctx := context.Background()
	cfg, err := config.Load("")
	if err != nil {
		t.Fatal(err)
	}
	live := filepath.Join(dir, "zoomies.db")

	// Something after the backup, which the restore takes away.
	st, err := store.Open(ctx, store.Options{Path: live})
	if err != nil {
		t.Fatal(err)
	}
	if err := st.CreateInstallation(ctx, &store.Installation{AppID: 1, InstallationID: 2, Target: "later", TargetType: store.TargetOrg}); err != nil {
		t.Fatal(err)
	}
	st.Close()

	entry, err := backup.Get(filepath.Dir(src), filepath.Base(src))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := backup.Stage(ctx, cfg, entry, backup.Staged{RequestedBy: "alice"}); err != nil {
		t.Fatalf("Stage: %v", err)
	}

	if err := applyStagedRestore(ctx, cfg, slog.New(slog.DiscardHandler)); err != nil {
		t.Fatalf("applyStagedRestore: %v", err)
	}
	restored, err := store.Open(ctx, store.Options{Path: live})
	if err != nil {
		t.Fatal(err)
	}
	defer restored.Close()
	insts, _ := restored.ListInstallations(ctx)
	if len(insts) != 1 || insts[0].Target != "acme" {
		t.Errorf("the database at start is not the backup: %+v", insts)
	}
	if f, _ := restored.RecoveryFenced(ctx); !f.Fenced {
		t.Error("the restored fleet is not fenced")
	}
	if outcome, _ := backup.LastOutcome(live); outcome == nil || !outcome.OK {
		t.Errorf("the outcome was not recorded for the page: %+v", outcome)
	}
	// And a start with nothing staged does nothing.
	if err := applyStagedRestore(ctx, cfg, slog.New(slog.DiscardHandler)); err != nil {
		t.Errorf("a second start: %v", err)
	}
}

// A restart the settings page asked for is not a failure and not a clean
// exit: a service manager set to restart on failure has to see a non-zero
// code, and a script has to be able to tell it from a crash.
func TestARequestedRestartHasItsOwnExitCode(t *testing.T) {
	e, _, errOut := newTestEnv(t)
	code := report(e, "controller", &restartRequested{reason: "restoring zoomies-20260916-120000"})
	if code != exitRestart {
		t.Fatalf("exit code = %d, want %d", code, exitRestart)
	}
	if !strings.Contains(errOut.String(), "restoring zoomies-20260916-120000") || !strings.Contains(errOut.String(), "Start it again") {
		t.Errorf("the message does not say why or what to do:\n%s", errOut)
	}
	if code := report(e, "controller", errors.New("bind: address in use")); code != exitError {
		t.Errorf("an ordinary failure exits %d", code)
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/url"
	"strings"
	"time"
)

// runStatus renders the Overview page in a terminal.
//
// It is four calls to the same routes the UI uses, arranged so that the answer
// to "is my fleet all right?" is the last thing on the screen. When there is
// nothing wrong it says so in one line, because an operator who runs this every
// morning needs the quiet case to be unmistakable.
func runStatus(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies status [--window 1h]", "The Overview, in a terminal: counts, pools, recent scaling and anything wrong.")
	cf := registerClientFlags(fs, true)
	window := fs.String("window", "1h", "the window the completed/failed counts and queue waits cover")
	scalingLimit := fs.Int("scaling", 5, "how many recent scaling decisions to show")
	fs.example("zoomies status", "zoomies status --window 24h", "zoomies status --output json")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var meta metaResponse
	metaRaw, err := client.get(ctx, "/meta", nil, &meta)
	if err != nil {
		return err
	}

	q := url.Values{}
	q.Set("window", *window)
	var stats statsResponse
	statsRaw, err := client.get(ctx, "/stats", q, &stats)
	if err != nil {
		return err
	}

	var problems problemsResponse
	problemsRaw, err := client.get(ctx, "/problems", nil, &problems)
	if err != nil {
		return err
	}

	scalingQuery := url.Values{}
	scalingQuery.Set("limit", fmt.Sprint(max(*scalingLimit, 1)))
	var scaling listResponse[scalingItem]
	scalingRaw, err := client.get(ctx, "/scaling-events", scalingQuery, &scaling)
	if err != nil {
		return err
	}

	if p.structured() {
		// One document rather than four, so `zoomies status --output json`
		// can be piped somewhere without four separate invocations.
		combined, err := json.Marshal(map[string]json.RawMessage{
			"meta":           metaRaw,
			"stats":          statsRaw,
			"problems":       problemsRaw,
			"scaling_events": scalingRaw,
		})
		if err != nil {
			return err
		}
		return p.emit(combined)
	}

	printStatus(p, client.base, meta, stats, scaling.Items, problems)
	return nil
}

func printStatus(p *printer, base string, meta metaResponse, stats statsResponse, scaling []scalingItem, problems problemsResponse) {
	fmt.Fprintf(p.out, "\n%s   %s\n\n", base, p.paint(colourDim, meta.Version))

	window := prettyWindow(stats.Window)
	p.keyValues([][2]string{
		{"jobs", fmt.Sprintf("%d queued, %d running   (%d completed in %s: %d succeeded, %d failed, %d cancelled, %d unknown)",
			stats.QueuedJobs, stats.RunningJobs, stats.Completed, window, stats.Succeeded, stats.Failed, stats.Cancelled, stats.Unknown)},
		{"queue wait", fmt.Sprintf("median %s, p95 %s", millis(stats.MedianWaitMS), millis(stats.P95WaitMS))},
		{"runners", fmt.Sprintf("%d live: %d busy, %d idle, %d starting, %d draining, %d failed",
			stats.Runners.Total, stats.Runners.Busy, stats.Runners.Idle,
			stats.Runners.Provisioning+stats.Runners.Registering, stats.Runners.Draining, stats.Runners.Failed)},
		{"hosts", fmt.Sprintf("%d of %d healthy, %d cordoned, %d of %d slots used",
			stats.Hosts.Healthy, stats.Hosts.Total, stats.Hosts.Cordoned, stats.Hosts.Used, stats.Hosts.Capacity)},
	})

	if meta.PollingOnly {
		fmt.Fprintf(p.out, "\n%s\n", p.paint(colourYellow,
			"No webhook has ever arrived: this fleet is scaling on the fallback poller, which is slower."))
	}

	if len(stats.Pools) > 0 {
		fmt.Fprintln(p.out, "\nPools")
		rows := make([][]string, 0, len(stats.Pools))
		for _, pool := range stats.Pools {
			rows = append(rows, []string{
				"  " + pool.PoolName,
				p.bar(pool.Utilisation, 16),
				fmt.Sprintf("%3.0f%%", pool.Utilisation*100),
				fmt.Sprintf("%d/%d runners", pool.Live, pool.Max),
				fmt.Sprintf("%d busy", pool.Busy),
				queuedNote(pool.Queued),
			})
		}
		p.table(nil, rows)
	}

	if len(scaling) > 0 {
		fmt.Fprintln(p.out, "\nRecent scaling")
		for _, ev := range scaling {
			fmt.Fprintf(p.out, "  %-9s %s\n", p.relTime(ev.CreatedAt), ev.Reason)
		}
	}

	fmt.Fprintln(p.out)
	if problems.OK || len(problems.Items) == 0 {
		fmt.Fprintln(p.out, p.paint(colourGreen, "Nothing needs your attention."))
		return
	}
	fmt.Fprintf(p.out, "%d thing(s) need your attention:\n", len(problems.Items))
	for _, item := range problems.Items {
		label := item.Severity
		switch item.Severity {
		case "error":
			label = p.paint(colourRed, label)
		case "warning":
			label = p.paint(colourYellow, label)
		default:
			label = p.paint(colourDim, label)
		}
		setting := ""
		if item.Setting != "" {
			setting = "  (" + item.Setting + ")"
		}
		fmt.Fprintf(p.out, "  [%s] %s%s\n", label, item.Title, setting)
		if item.Detail != "" {
			fmt.Fprintf(p.out, "          %s\n", item.Detail)
		}
		if item.Fix != "" {
			fmt.Fprintf(p.out, "          fix: %s\n", item.Fix)
		}
	}
}

// prettyWindow tidies the duration the server echoes back. Go renders an hour
// as "1h0m0s", which is correct and reads like a stack trace; the operator
// asked for "1h" and should see "1h".
func prettyWindow(raw string) string {
	d, err := time.ParseDuration(strings.TrimSpace(raw))
	if err != nil || d <= 0 {
		if raw == "" {
			return "the window"
		}
		return raw
	}
	switch {
	case d >= 48*time.Hour && d%(24*time.Hour) == 0:
		return fmt.Sprintf("%dd", d/(24*time.Hour))
	case d%time.Hour == 0:
		return fmt.Sprintf("%dh", d/time.Hour)
	case d%time.Minute == 0:
		return fmt.Sprintf("%dm", d/time.Minute)
	default:
		return d.String()
	}
}

// queuedNote keeps the quiet case quiet: a pool with nothing waiting should not
// have a column shouting zero at the operator.
func queuedNote(queued int) string {
	if queued == 0 {
		return ""
	}
	return fmt.Sprintf("%d queued", queued)
}

package main

import (
	"context"
	"fmt"
	"net/url"
	"strings"
	"time"
)

// runTokens is `zoomies tokens ...`: the credentials that let this CLI, and
// anything else, talk to the API.
func runTokens(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "tokens", "API tokens. The value exists in plaintext exactly once, at creation.", []*subcommand{
		{"list", "", "Your tokens' metadata, or everybody's for an administrator; never the value", tokensList},
		{"create", "--name <n> --role <r>", "Mint a token and print it once", tokensCreate},
		{"revoke", "<token-id>", "Revoke a token immediately", tokensRevoke},
		{"delete", "<token-id>", "Remove a revoked or expired token from the list", tokensDelete},
		{"purge", "[--user <id> | --all]", "Remove every revoked or expired token", tokensPurge},
	}, args)
}

func tokensList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens list", "List API tokens: your own, or everybody's for an administrator. Metadata only -- the value is not stored.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[tokenItem]
	raw, err := client.get(ctx, "/tokens", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No API tokens. Mint one with: zoomies tokens create --name my-laptop --role operator")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, t := range out.Items {
		state := "active"
		switch {
		case t.Revoked:
			state = p.paint(colourDim, "revoked")
		case t.ExpiresAt != nil && t.ExpiresAt.Before(time.Now()):
			state = p.paint(colourRed, "expired")
		}
		expires := "never"
		if t.ExpiresAt != nil {
			expires = p.relTime(*t.ExpiresAt)
		}
		rows = append(rows, []string{
			t.Name,
			t.ID,
			t.Role,
			dash(t.Prefix),
			dash(strings.Join(t.Scopes, ",")),
			state,
			expires,
			p.relTimePtr(t.LastUsedAt),
		})
	}
	p.table([]string{"name", "id", "role", "prefix", "scopes", "state", "expires", "last used"}, rows)
	return nil
}

func tokensCreate(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens create --name <name> --role <viewer|operator|admin|platform>",
		"Mint an API token of your own, at a role no higher than yours. It is printed once and only its hash is kept.")
	cf := registerClientFlags(fs, true)
	name := fs.String("name", "", "what this token is for, e.g. my-laptop or prometheus (required)")
	role := fs.String("role", "viewer", "viewer, operator, admin or platform")
	scopes := &listValue{}
	fs.Var(scopes, "scope", "narrow the token within its role, e.g. runners:read (repeatable)")
	expiresIn := fs.Duration("expires-in", 0, "how long the token lasts; zero means never, which is worth avoiding")
	fs.example(
		"zoomies tokens create --name my-laptop --role operator --expires-in 2160h",
		"zoomies tokens create --name prometheus --role viewer --scope metrics:read",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if strings.TrimSpace(*name) == "" {
		return usagef("tokens create", "needs --name; a token nobody can identify is a token nobody dares revoke")
	}
	if !validRole(*role) {
		return usagef("tokens create", "--role %q is not a role; use viewer, operator or admin", *role)
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	body := map[string]any{"name": *name, "role": *role}
	if len(*scopes) > 0 {
		body["scopes"] = []string(*scopes)
	}
	if *expiresIn > 0 {
		body["expires_in"] = expiresIn.String()
	}

	var token tokenItem
	raw, err := client.post(ctx, "/tokens", nil, body, &token)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}

	fmt.Fprintf(e.out, "%s\n\n", token.Token)
	p.keyValues([][2]string{
		{"name", token.Name},
		{"id", token.ID},
		{"role", token.Role},
		{"expires", map[bool]string{true: "never", false: p.relTimePtr(token.ExpiresAt)}[token.ExpiresAt == nil]},
	})
	fmt.Fprintln(e.out, "\nThis is the only time the token is shown. To use it from here:")
	fmt.Fprintf(e.out, "  export ZOOMIES_TOKEN=%s\n", token.Token)
	return nil
}

func tokensRevoke(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens revoke <token-id>", "Revoke a token. It stops working immediately.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a token ID, as shown by `zoomies tokens list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/tokens/"+url.PathEscape(id), nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Revoked token %s.\n", id)
	return nil
}

func tokensDelete(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens delete <token-id>",
		"Remove a revoked or expired token from the list for good. A token that still works is refused: revoke it first.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a token ID, as shown by `zoomies tokens list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/tokens/"+url.PathEscape(id), url.Values{"purge": {"true"}}, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Deleted token %s. The audit log still records it.\n", id)
	return nil
}

func tokensPurge(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies tokens purge [--user <user-id> | --all]",
		"Remove every revoked or expired token: your own, one account's, or all of them. Tokens that still work are left alone.")
	cf := registerClientFlags(fs, true)
	user := fs.String("user", "", "purge this account's spent tokens instead of your own")
	all := fs.Bool("all", false, "purge every spent token you can see")
	fs.example("zoomies tokens purge", "zoomies tokens purge --all")
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if *all && *user != "" {
		return usagef("tokens purge", "--user and --all ask different questions; give one")
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}
	body := map[string]any{}
	if *all {
		body["all"] = true
	}
	if *user != "" {
		body["user_id"] = *user
	}
	var out struct {
		Deleted []tokenItem `json:"deleted"`
	}
	raw, err := client.post(ctx, "/tokens/purge", nil, body, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Deleted) == 0 {
		p.note("Nothing to delete: no revoked or expired tokens.")
		return nil
	}
	for _, t := range out.Deleted {
		fmt.Fprintf(e.out, "Deleted %s (%s)\n", t.Name, t.ID)
	}
	return nil
}

package main

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"strings"

	"golang.org/x/term"
)

// runUsers is `zoomies users ...`. The API refuses to leave an instance with no
// enabled administrator, so this command does not have to police that itself --
// it just has to report the refusal clearly when it comes.
func runUsers(ctx context.Context, e *env, args []string) error {
	return runGroup(ctx, e, "users", "User accounts.", []*subcommand{
		{"list", "", "Every account and its role", usersList},
		{"create", "--username <n> --role <r>", "Create an account", usersCreate},
		{"passwd", "<user-id>", "Set an account's password", usersPasswd},
		{"reset-two-step", "<user-id>", "Turn off an account's two-step verification", usersResetTwoStep},
		{"delete", "<user-id>", "Delete an account", usersDelete},
	}, args)
}

// usersPasswd is the administrator's reset, from a terminal.
//
// The password is read from the terminal, or from standard input when it is
// piped in; there is deliberately no --password flag. A password in argv is a
// password in /proc/<pid>/cmdline, which every account on the host can read,
// and in the operator's shell history afterwards.
func usersPasswd(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users passwd <user-id>",
		"Set an account's password. Every session it had ends, and its owner is asked to choose their own at the next sign-in.")
	cf := registerClientFlags(fs, false)
	fs.example(
		"zoomies users passwd usr_7f3a",
		`printf '%s' "$new" | zoomies users passwd usr_7f3a`,
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	password, err := readSecret(e, "New password: ")
	if err != nil {
		return err
	}
	if password == "" {
		return usagef("users passwd", "no password was given; type one at the prompt or pipe one in")
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	body := map[string]any{"new_password": password}
	if _, err := client.post(ctx, "/users/"+url.PathEscape(id)+"/password", nil, body, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Set a new password for %s. Their sessions have ended, and they choose their own at the next sign-in.\n", id)
	return nil
}

// readSecret reads one line, without echoing it when there is a terminal to
// turn the echo off on, and from standard input otherwise -- which is what
// makes the piped form work in a script.
func readSecret(e *env, prompt string) (string, error) {
	if f, ok := e.in.(*os.File); ok && term.IsTerminal(int(f.Fd())) {
		fmt.Fprint(e.err, prompt)
		typed, err := term.ReadPassword(int(f.Fd()))
		fmt.Fprintln(e.err)
		if err != nil {
			return "", fmt.Errorf("reading the password: %w", err)
		}
		return strings.TrimSpace(string(typed)), nil
	}
	line, err := bufio.NewReader(e.in).ReadString('\n')
	if err != nil && !errors.Is(err, io.EOF) {
		return "", fmt.Errorf("reading the password from standard input: %w", err)
	}
	return strings.TrimSpace(line), nil
}

func usersList(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users list", "List the accounts that can sign in.")
	cf := registerClientFlags(fs, true)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	var out listResponse[userItem]
	raw, err := client.get(ctx, "/users", nil, &out)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	if len(out.Items) == 0 {
		p.note("No users. This instance still needs its first administrator; open the UI to create one.")
		return nil
	}

	rows := make([][]string, 0, len(out.Items))
	for _, u := range out.Items {
		state := "enabled"
		if u.Disabled {
			state = p.paint(colourDim, "disabled")
		}
		if u.MustChangePassword {
			state += p.paint(colourYellow, " (must change password)")
		}
		rows = append(rows, []string{
			u.Username,
			u.ID,
			u.Role,
			dash(u.DisplayName),
			dash(u.Email),
			state,
			p.relTimePtr(u.LastLoginAt),
		})
	}
	p.table([]string{"username", "id", "role", "name", "email", "state", "last login"}, rows)
	return nil
}

func usersCreate(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users create --username <name> --role <viewer|operator|admin|platform>",
		"Create an account. Omit --password for one that will sign in through single sign-on.")
	cf := registerClientFlags(fs, true)
	username := fs.String("username", "", "the account's login name (required)")
	password := fs.String("password", "", "an initial password of at least 12 characters; omit for an SSO-only account")
	email := fs.String("email", "", "the account's email address")
	displayName := fs.String("display-name", "", "how the account's name is shown")
	role := fs.String("role", "viewer", "viewer, operator, admin or platform")
	fs.example(
		"zoomies users create --username alex --role operator --email alex@example.com",
		"zoomies users create --username ci-readonly --role viewer",
	)
	if err := fs.parse(args); err != nil {
		return err
	}
	if err := fs.noMoreArgs(); err != nil {
		return err
	}
	if strings.TrimSpace(*username) == "" {
		return usagef("users create", "needs --username")
	}
	if !validRole(*role) {
		return usagef("users create", "--role %q is not a role; use viewer, operator or admin", *role)
	}

	client, err := cf.client()
	if err != nil {
		return err
	}
	p, err := cf.printer(e)
	if err != nil {
		return err
	}

	body := map[string]any{"username": *username, "role": *role}
	if *password != "" {
		body["password"] = *password
	}
	if *email != "" {
		body["email"] = *email
	}
	if *displayName != "" {
		body["display_name"] = *displayName
	}

	var user userItem
	raw, err := client.post(ctx, "/users", nil, body, &user)
	if err != nil {
		return err
	}
	if p.structured() {
		return p.emit(raw)
	}
	fmt.Fprintf(e.out, "Created %s (%s) as %s.\n", user.Username, user.ID, user.Role)
	if *password == "" {
		fmt.Fprintln(e.out, "No password was set, so this account can only sign in through single sign-on.")
	}
	return nil
}

// usersResetTwoStep is the administrator's answer to a lost phone: the
// account's authenticator secret and recovery codes are removed and its
// sessions end, so its owner signs in with the password alone -- or, where the
// instance requires two-step, sets it up again at that sign-in.
func usersResetTwoStep(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users reset-two-step <user-id>",
		"Turn off two-step verification for an account whose owner has lost their authenticator and their recovery codes. Its sessions end, and the reset is audited.")
	cf := registerClientFlags(fs, false)
	fs.example("zoomies users reset-two-step usr_7f3a")
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/users/"+url.PathEscape(id)+"/two-step", nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Reset two-step verification for %s. Their sessions have ended; they sign in with their password next time.\n", id)
	return nil
}

func usersDelete(ctx context.Context, e *env, args []string) error {
	fs := newFlagSet(e, "zoomies users delete <user-id>",
		"Delete an account. Refused if it would leave the instance with no enabled administrator.")
	cf := registerClientFlags(fs, false)
	if err := fs.parse(args); err != nil {
		return err
	}
	id, err := fs.oneArg("a user ID, as shown by `zoomies users list`")
	if err != nil {
		return err
	}
	client, err := cf.client()
	if err != nil {
		return err
	}
	if _, err := client.del(ctx, "/users/"+url.PathEscape(id), nil, nil); err != nil {
		return err
	}
	fmt.Fprintf(e.out, "Deleted user %s.\n", id)
	return nil
}

func validRole(role string) bool {
	switch strings.ToLower(strings.TrimSpace(role)) {
	case "viewer", "operator", "admin", "platform":
		return true
	}
	return false
}

//go:build ignore

// Command gen_toolcache_lock resolves the language toolchains the runner-full
// image carries to exact releases and digests, and writes deploy/toolcache.lock.
//
// The image unpacks every one of these into the tool cache, and a job runs
// whatever it finds there -- so what goes in has to be what its publisher
// released, not whatever a mirror or a proxy between the build and the
// publisher handed over on the day. deploy/runner-toolcache.sh refuses an
// archive whose digest is not the one written here.
//
// Most publishers say what the digest is: nodejs.org's SHASUMS256.txt, go.dev's
// release feed, Adoptium's API, .NET's release metadata, Apache's .sha512 files,
// Gradle's .sha256 and rustup's own. actions/python-versions publishes none, so
// a Python archive's digest is the one this command computed when it first
// pinned it. That is trust on first use, and the lock is what makes the first
// use the only one: an archive that changes afterwards fails the build rather
// than shipping.
//
// Which lines of each toolchain the image carries is the table below. Each
// run moves every line to its newest release, which is what the scheduled
// workflow does; a line that is no longer published is an error, not a quiet
// drop, so retiring one is an edit here.
//
// Run it from the repository root:
//
//	go run deploy/gen_toolcache_lock.go
//
// An archive whose URL the current lock already carries keeps the digest it
// has, so a run that moves one Python patch downloads that one archive rather
// than all thirty.
package main

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
)

const lockPath = "deploy/toolcache.lock"

// The lines the image carries. Each is a release line its project still
// supports; the newest release on it is what gets pinned.
var (
	pythonMinors   = []string{"3.10", "3.11", "3.12", "3.13", "3.14"}
	nodeMajors     = []string{"22", "24"}
	javaMajors     = []string{"17", "21", "25"}
	dotnetChannels = []string{"8.0", "10.0"}
	// Go is every release go.dev lists as stable, which is the two it
	// supports; Maven is the newest 3.x, Gradle the current release, and Rust
	// the stable channel.
)

// arches maps the image's architectures (Docker's TARGETARCH) to the names
// each publisher uses for them.
var arches = []struct{ docker, python, node, java, dotnet, rust string }{
	{"amd64", "x64", "x64", "x64", "x64", "x86_64-unknown-linux-gnu"},
	{"arm64", "arm64", "arm64", "aarch64", "arm64", "aarch64-unknown-linux-gnu"},
}

// entry is one line of the lock.
type entry struct {
	tool, version, platform, arch, digest, url string
}

func (e entry) String() string {
	return strings.Join([]string{e.tool, e.version, e.platform, e.arch, e.digest, e.url}, " ")
}

var client = &http.Client{Timeout: 10 * time.Minute}

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "gen_toolcache_lock:", err)
		os.Exit(1)
	}
}

func run() error {
	known := readLock()

	var platforms []string
	for _, img := range naming.Images() {
		if img.Full {
			platforms = append(platforms, img.Version)
		}
	}
	if len(platforms) == 0 {
		return errors.New("no catalogue row in internal/naming is Full, so there is nothing to build a tool cache for")
	}

	var out []entry
	steps := []struct {
		name string
		fn   func() ([]entry, error)
	}{
		{"Python", func() ([]entry, error) { return python(platforms, known) }},
		{"Node.js", node},
		{"Go", golang},
		{"Java", java},
		{".NET", dotnet},
		{"Maven", maven},
		{"Gradle", gradle},
		{"Rust", rust},
	}
	for _, s := range steps {
		es, err := s.fn()
		if err != nil {
			return fmt.Errorf("%s: %w", s.name, err)
		}
		fmt.Fprintf(os.Stderr, "%s: %d archives\n", s.name, len(es))
		out = append(out, es...)
	}
	return writeLock(out)
}

// --- Python -------------------------------------------------------------------

// python pins the newest stable release of each minor from the manifest
// setup-python itself reads, for every Ubuntu the catalogue marks Full. The
// free-threaded builds are left out: they are a separate interpreter a
// workflow has to ask for by name.
func python(platforms []string, known map[string]string) ([]entry, error) {
	var manifest []struct {
		Version string `json:"version"`
		Stable  bool   `json:"stable"`
		Files   []struct {
			Filename        string `json:"filename"`
			Arch            string `json:"arch"`
			Platform        string `json:"platform"`
			PlatformVersion string `json:"platform_version"`
			URL             string `json:"download_url"`
		} `json:"files"`
	}
	if err := getJSON("https://raw.githubusercontent.com/actions/python-versions/main/versions-manifest.json", &manifest); err != nil {
		return nil, err
	}
	var out []entry
	for _, minor := range pythonMinors {
		found := false
		for _, rel := range manifest {
			if !rel.Stable || !strings.HasPrefix(rel.Version, minor+".") {
				continue
			}
			found = true
			for _, platform := range platforms {
				for _, a := range arches {
					// The Ubuntu 26.04 x64 Python archives are built with a
					// newer CPU ISA than older x64 hosts provide. Its userspace
					// can run the 24.04 archive, which keeps the full image's
					// tool cache compatible with the supported x86-64 baseline.
					sourcePlatform := platform
					if platform == "26.04" && a.docker == "amd64" {
						sourcePlatform = "24.04"
					}
					url := ""
					for _, f := range rel.Files {
						if f.Platform == "linux" && f.PlatformVersion == sourcePlatform && f.Arch == a.python {
							url = f.URL
						}
					}
					if url == "" {
						return nil, fmt.Errorf("Python %s has no build for Ubuntu %s %s", rel.Version, sourcePlatform, a.docker)
					}
					digest, ok := known[url]
					if !ok {
						var err error
						if digest, err = hashURL(url); err != nil {
							return nil, err
						}
					}
					out = append(out, entry{"python", rel.Version, platform, a.docker, digest, url})
				}
			}
			break // the manifest lists newest first
		}
		if !found {
			return nil, fmt.Errorf("no stable Python %s in the manifest", minor)
		}
	}
	return out, nil
}

// --- Node.js ------------------------------------------------------------------

func node() ([]entry, error) {
	var index []struct {
		Version string `json:"version"`
	}
	if err := getJSON("https://nodejs.org/dist/index.json", &index); err != nil {
		return nil, err
	}
	var out []entry
	for _, major := range nodeMajors {
		version := ""
		for _, r := range index { // newest first
			if strings.HasPrefix(r.Version, "v"+major+".") {
				version = r.Version
				break
			}
		}
		if version == "" {
			return nil, fmt.Errorf("no Node.js %s release", major)
		}
		sums, err := getText("https://nodejs.org/dist/" + version + "/SHASUMS256.txt")
		if err != nil {
			return nil, err
		}
		for _, a := range arches {
			file := fmt.Sprintf("node-%s-linux-%s.tar.gz", version, a.node)
			sum := sumFor(sums, file)
			if sum == "" {
				return nil, fmt.Errorf("SHASUMS256.txt for %s does not list %s", version, file)
			}
			out = append(out, entry{"node", strings.TrimPrefix(version, "v"), "-", a.docker,
				"sha256:" + sum, "https://nodejs.org/dist/" + version + "/" + file})
		}
	}
	return out, nil
}

// --- Go -----------------------------------------------------------------------

func golang() ([]entry, error) {
	var releases []struct {
		Version string `json:"version"`
		Stable  bool   `json:"stable"`
		Files   []struct {
			Filename, OS, Arch, SHA256, Kind string
		} `json:"files"`
	}
	if err := getJSON("https://go.dev/dl/?mode=json", &releases); err != nil {
		return nil, err
	}
	var out []entry
	for _, r := range releases {
		if !r.Stable {
			continue
		}
		for _, a := range arches {
			var file, sum string
			for _, f := range r.Files {
				if f.OS == "linux" && f.Arch == a.docker && f.Kind == "archive" {
					file, sum = f.Filename, f.SHA256
				}
			}
			if file == "" {
				return nil, fmt.Errorf("%s has no linux-%s archive", r.Version, a.docker)
			}
			out = append(out, entry{"go", strings.TrimPrefix(r.Version, "go"), "-", a.docker,
				"sha256:" + sum, "https://go.dev/dl/" + file})
		}
	}
	if len(out) == 0 {
		return nil, errors.New("go.dev lists no stable release")
	}
	return out, nil
}

// --- Java ---------------------------------------------------------------------

// java pins Eclipse Temurin, the distribution GitHub's runners carry. The
// version recorded is the one setup-java names its tool-cache directory
// after: Adoptium's semver with the + turned into a -, because a + in a path
// breaks Kotlin.
func java() ([]entry, error) {
	var out []entry
	for _, major := range javaMajors {
		for _, a := range arches {
			var assets []struct {
				Binary struct {
					Package struct {
						Checksum string `json:"checksum"`
						Link     string `json:"link"`
					} `json:"package"`
				} `json:"binary"`
				Version struct {
					Semver string `json:"semver"`
				} `json:"version"`
			}
			url := fmt.Sprintf("https://api.adoptium.net/v3/assets/latest/%s/hotspot?architecture=%s&image_type=jdk&os=linux&vendor=eclipse", major, a.java)
			if err := getJSON(url, &assets); err != nil {
				return nil, err
			}
			if len(assets) != 1 {
				return nil, fmt.Errorf("Temurin %s %s: want one release, got %d", major, a.docker, len(assets))
			}
			pkg := assets[0].Binary.Package
			if !isHex(pkg.Checksum, 64) || pkg.Link == "" {
				return nil, fmt.Errorf("Temurin %s %s: no checksum or link", major, a.docker)
			}
			out = append(out, entry{"java", strings.Replace(assets[0].Version.Semver, "+", "-", 1), "-", a.docker,
				"sha256:" + pkg.Checksum, pkg.Link})
		}
	}
	return out, nil
}

// --- .NET ---------------------------------------------------------------------

func dotnet() ([]entry, error) {
	var index struct {
		Releases []struct {
			Channel   string `json:"channel-version"`
			LatestSDK string `json:"latest-sdk"`
			JSON      string `json:"releases.json"`
		} `json:"releases-index"`
	}
	if err := getJSON("https://builds.dotnet.microsoft.com/dotnet/release-metadata/releases-index.json", &index); err != nil {
		return nil, err
	}
	var out []entry
	for _, channel := range dotnetChannels {
		var sdk, releasesURL string
		for _, r := range index.Releases {
			if r.Channel == channel {
				sdk, releasesURL = r.LatestSDK, r.JSON
			}
		}
		if sdk == "" {
			return nil, fmt.Errorf("no .NET %s channel", channel)
		}
		type file struct{ Name, URL, Hash string }
		var releases struct {
			Releases []struct {
				SDKs []struct {
					Version string `json:"version"`
					Files   []file `json:"files"`
				} `json:"sdks"`
			} `json:"releases"`
		}
		if err := getJSON(releasesURL, &releases); err != nil {
			return nil, err
		}
		var files []file
		for _, r := range releases.Releases {
			for _, s := range r.SDKs {
				if s.Version == sdk && files == nil {
					files = s.Files
				}
			}
		}
		if files == nil {
			return nil, fmt.Errorf(".NET %s: SDK %s is not in its releases.json", channel, sdk)
		}
		for _, a := range arches {
			name := "dotnet-sdk-linux-" + a.dotnet + ".tar.gz"
			var f *file
			for i := range files {
				if files[i].Name == name {
					f = &files[i]
				}
			}
			if f == nil || !isHex(f.Hash, 128) {
				return nil, fmt.Errorf(".NET SDK %s has no %s with a SHA-512", sdk, name)
			}
			out = append(out, entry{"dotnet", sdk, "-", a.docker, "sha512:" + strings.ToLower(f.Hash), f.URL})
		}
	}
	return out, nil
}

// --- Maven and Gradle ---------------------------------------------------------

func maven() ([]entry, error) {
	const base = "https://repo.maven.apache.org/maven2/org/apache/maven/apache-maven/"
	body, err := getText(base + "maven-metadata.xml")
	if err != nil {
		return nil, err
	}
	var meta struct {
		Versions []string `xml:"versioning>versions>version"`
	}
	if err := xml.Unmarshal([]byte(body), &meta); err != nil {
		return nil, err
	}
	stable := regexp.MustCompile(`^3\.\d+\.\d+$`)
	var best string
	for _, v := range meta.Versions {
		if stable.MatchString(v) && (best == "" || versionLess(best, v)) {
			best = v
		}
	}
	if best == "" {
		return nil, errors.New("no Maven 3.x release")
	}
	url := fmt.Sprintf("%s%s/apache-maven-%s-bin.tar.gz", base, best, best)
	sum, err := getText(url + ".sha512")
	if err != nil {
		return nil, err
	}
	sum = strings.Fields(sum + " ")[0]
	if !isHex(sum, 128) {
		return nil, fmt.Errorf("Maven %s: %s.sha512 is not a SHA-512", best, url)
	}
	return []entry{{"maven", best, "-", "-", "sha512:" + sum, url}}, nil
}

func gradle() ([]entry, error) {
	var cur struct {
		Version     string `json:"version"`
		DownloadURL string `json:"downloadUrl"`
		ChecksumURL string `json:"checksumUrl"`
	}
	if err := getJSON("https://services.gradle.org/versions/current", &cur); err != nil {
		return nil, err
	}
	sum, err := getText(cur.ChecksumURL)
	if err != nil {
		return nil, err
	}
	sum = strings.TrimSpace(sum)
	if !isHex(sum, 64) {
		return nil, fmt.Errorf("Gradle %s: %s is not a SHA-256", cur.Version, cur.ChecksumURL)
	}
	return []entry{{"gradle", cur.Version, "-", "-", "sha256:" + sum, cur.DownloadURL}}, nil
}

// --- Rust ---------------------------------------------------------------------

// rust pins rustup-init by digest and the stable toolchain by version. The
// toolchain itself is rustup's to verify: it checks every component against
// the channel manifest it downloads, which is what rustup exists to do.
func rust() ([]entry, error) {
	rel, err := getText("https://static.rust-lang.org/rustup/release-stable.toml")
	if err != nil {
		return nil, err
	}
	rustup := tomlString(rel, "version")
	if rustup == "" {
		return nil, errors.New("release-stable.toml names no rustup version")
	}
	var out []entry
	for _, a := range arches {
		url := fmt.Sprintf("https://static.rust-lang.org/rustup/archive/%s/%s/rustup-init", rustup, a.rust)
		sum, err := getText(url + ".sha256")
		if err != nil {
			return nil, err
		}
		sum = strings.Fields(sum + " ")[0]
		if !isHex(sum, 64) {
			return nil, fmt.Errorf("rustup %s %s: no SHA-256", rustup, a.docker)
		}
		out = append(out, entry{"rustup", rustup, "-", a.docker, "sha256:" + sum, url})
	}
	channel, err := getText("https://static.rust-lang.org/dist/channel-rust-stable.toml")
	if err != nil {
		return nil, err
	}
	_, rest, ok := strings.Cut(channel, "\n[pkg.rust]\n")
	if !ok {
		return nil, errors.New("channel-rust-stable.toml has no [pkg.rust]")
	}
	// "1.90.0 (1159e78c4 2025-09-14)": the toolchain rustup installs is the
	// number, and the channel is where it gets the rest.
	version := strings.Fields(tomlString(rest, "version") + " ")[0]
	if version == "" {
		return nil, errors.New("channel-rust-stable.toml names no rust version")
	}
	out = append(out, entry{"rust", version, "-", "-", "-", "-"})
	return out, nil
}

// --- the lock file ------------------------------------------------------------

const header = `# The language toolchains the runner-full image unpacks into its tool cache.
#
# Generated by ` + "`go run deploy/gen_toolcache_lock.go`" + `; do not edit. The
# scheduled toolcache workflow reruns it and opens a pull request when a line
# moves. deploy/runner-toolcache.sh installs from these rows and nothing else,
# and refuses an archive whose digest is not the one written here.
#
# tool  version  platform  arch  digest  url
#
# platform is the Ubuntu release a Python build is for, and - for everything
# that runs on any of them; arch is Docker's TARGETARCH, and - for what is not
# architecture-specific. Python's digests are this generator's own, taken when
# the archive was first pinned: actions/python-versions publishes none.

`

func writeLock(es []entry) error {
	var b strings.Builder
	b.WriteString(header)
	for _, e := range es {
		b.WriteString(e.String())
		b.WriteByte('\n')
	}
	return os.WriteFile(lockPath, []byte(b.String()), 0o644)
}

// readLock returns the digests the current lock holds, by URL.
func readLock() map[string]string {
	known := map[string]string{}
	f, err := os.Open(lockPath)
	if err != nil {
		return known
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		if len(fields) == 6 && !strings.HasPrefix(fields[0], "#") && fields[4] != "-" {
			known[fields[5]] = fields[4]
		}
	}
	return known
}

// --- helpers ------------------------------------------------------------------

func get(url string) (*http.Response, error) {
	req, err := http.NewRequest(http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "zoomies-gen-toolcache-lock")
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		resp.Body.Close()
		return nil, fmt.Errorf("GET %s: %s", url, resp.Status)
	}
	return resp, nil
}

func getText(url string) (string, error) {
	resp, err := get(url)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	return string(b), err
}

func getJSON(url string, v any) error {
	resp, err := get(url)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if err := json.NewDecoder(resp.Body).Decode(v); err != nil {
		return fmt.Errorf("GET %s: %w", url, err)
	}
	return nil
}

func hashURL(url string) (string, error) {
	fmt.Fprintf(os.Stderr, "  hashing %s\n", url)
	resp, err := get(url)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	h := sha256.New()
	if _, err := io.Copy(h, resp.Body); err != nil {
		return "", fmt.Errorf("GET %s: %w", url, err)
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
}

// sumFor finds a file's digest in a SHASUMS-style listing.
func sumFor(sums, file string) string {
	for _, line := range strings.Split(sums, "\n") {
		f := strings.Fields(line)
		if len(f) == 2 && f[1] == file && isHex(f[0], 64) {
			return f[0]
		}
	}
	return ""
}

// tomlString reads the first `key = "value"` line of a TOML document, in
// either of TOML's string quotes: rustup's release file uses single quotes and
// the channel manifest double.
func tomlString(doc, key string) string {
	re := regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(key) + `\s*=\s*(?:"([^"]*)"|'([^']*)')`)
	if m := re.FindStringSubmatch(doc); m != nil {
		return m[1] + m[2]
	}
	return ""
}

func isHex(s string, n int) bool {
	if len(s) != n {
		return false
	}
	_, err := hex.DecodeString(s)
	return err == nil
}

// versionLess orders dotted numeric versions.
func versionLess(a, b string) bool {
	as, bs := strings.Split(a, "."), strings.Split(b, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		x, _ := strconv.Atoi(as[i])
		y, _ := strconv.Atoi(bs[i])
		if x != y {
			return x < y
		}
	}
	return len(as) < len(bs)
}

//go:build ignore

// Command gen_lock resolves every image reference this deployment package
// depends on to the digest it points at today, and writes images.lock.
//
// A marketplace artefact promises a particular build, and a tag cannot keep
// that promise: tags move, and the person deploying six months from now has no
// way to tell that the controller they got is not the one that was tested. The
// lock file is the record that makes the promise checkable -- it is what an
// operator, an auditor or a provider's security review compares a running
// deployment against.
//
// The catalogue in internal/naming is the source for which runner variants
// exist, so a new operating system is picked up here by adding its row there
// rather than by remembering this file.
//
// Run it from the repository root after changing the release in release.env:
//
//	make marketplace-lock
//
// It needs network access to the registry and nothing else: the manifests it
// asks for are public, and it pulls no layers.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
)

const (
	dir      = "deploy/marketplace"
	lockFile = "images.lock"
	envFile  = "release.env"
)

// manifestTypes is every media type the registry may answer a manifest request
// with. A multi-architecture image is an index, a single-architecture one is a
// manifest, and both spellings of each are still in the wild; asking for only
// one of them gets a 404 that looks like a missing tag.
const manifestTypes = "application/vnd.oci.image.index.v1+json, " +
	"application/vnd.docker.distribution.manifest.list.v2+json, " +
	"application/vnd.oci.image.manifest.v1+json, " +
	"application/vnd.docker.distribution.manifest.v2+json"

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "gen_lock:", err)
		os.Exit(1)
	}
}

func run() error {
	env, err := readEnv(filepath.Join(dir, envFile))
	if err != nil {
		return err
	}
	release := env["ZOOMIES_RELEASE"]
	if release == "" {
		return fmt.Errorf("%s names no ZOOMIES_RELEASE", envFile)
	}

	refs := []string{stripDigest(env["ZOOMIES_CONTROLLER_IMAGE"])}
	for _, key := range []string{"ZOOMIES_PROXY_IMAGE", "ZOOMIES_TUNNEL_IMAGE"} {
		if ref := stripDigest(env[key]); ref != "" {
			refs = append(refs, ref)
		}
	}
	for _, img := range naming.Images() {
		tag := img.Tag() + "-" + release
		refs = append(refs,
			env["ZOOMIES_RUNNER_REPO"]+":"+tag,
			env["ZOOMIES_RUNNER_DOCKER_REPO"]+":"+tag,
		)
	}
	sort.Strings(refs)

	client := &http.Client{Timeout: 30 * time.Second}
	digests := make(map[string]string, len(refs))
	width := 0
	for _, ref := range refs {
		d, err := resolve(client, ref)
		if err != nil {
			return fmt.Errorf("resolving %s: %w", ref, err)
		}
		digests[ref] = d
		if len(ref) > width {
			width = len(ref)
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "# Every image %s deploys, and the digest its tag resolved to.\n", release)
	b.WriteString("#\n")
	b.WriteString("# Generated by `make marketplace-lock`; do not edit. Each line is one image\n")
	b.WriteString("# reference and the digest it pointed at when this release was locked, so a\n")
	b.WriteString("# deployment can be audited against what was published rather than against\n")
	b.WriteString("# whatever the tag means today.\n#\n")
	b.WriteString("# The runner images are here for that audit, not because the bootstrap picks\n")
	b.WriteString("# one: a controller resolves its runners from its own build tag, so pinning\n")
	b.WriteString("# the controller pins every line below with it.\n\n")
	for _, ref := range refs {
		fmt.Fprintf(&b, "%-*s  %s\n", width, ref, digests[ref])
	}
	return os.WriteFile(filepath.Join(dir, lockFile), []byte(b.String()), 0o644)
}

// resolve asks the registry what a tag points at, without pulling anything.
// GHCR wants a token even for a public repository, and hands one out for the
// asking; the digest is the header the registry answers a manifest request
// with, which is exactly the value `docker pull` would pin.
func resolve(client *http.Client, ref string) (string, error) {
	host, repo, tag, err := split(ref)
	if err != nil {
		return "", err
	}
	token, err := pullToken(client, host, repo)
	if err != nil {
		return "", err
	}
	req, err := http.NewRequest(http.MethodHead, "https://"+registryHost(host)+"/v2/"+repo+"/manifests/"+tag, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Accept", manifestTypes)
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("the registry answered %s", resp.Status)
	}
	d := resp.Header.Get("Docker-Content-Digest")
	if !strings.HasPrefix(d, "sha256:") {
		return "", fmt.Errorf("the registry returned no digest")
	}
	return d, nil
}

// split breaks a reference into the registry it lives on, the repository path
// that registry knows it by, and the tag. Docker Hub is the awkward one: its
// references carry no host at all, official images live under an implied
// library/ prefix, and its API is on a different name from its references.
func split(ref string) (host, repo, tag string, err error) {
	rest := ref
	host = "docker.io"
	if i := strings.Index(ref, "/"); i >= 0 && strings.Contains(ref[:i], ".") {
		host, rest = ref[:i], ref[i+1:]
	}
	repo, tag, ok := strings.Cut(rest, ":")
	if !ok {
		return "", "", "", fmt.Errorf("%q names no tag", ref)
	}
	if host == "docker.io" && !strings.Contains(repo, "/") {
		repo = "library/" + repo
	}
	return host, repo, tag, nil
}

// registryHost is where the API lives, which is not always where references say
// the image does.
func registryHost(host string) string {
	if host == "docker.io" {
		return "registry-1.docker.io"
	}
	return host
}

// pullToken asks for anonymous pull access. Both registries hand one out for
// the asking on a public repository; neither serves a manifest without it.
func pullToken(client *http.Client, host, repo string) (string, error) {
	authURL := "https://" + host + "/token?scope=repository:" + repo + ":pull&service=" + host
	if host == "docker.io" {
		authURL = "https://auth.docker.io/token?scope=repository:" + repo + ":pull&service=registry.docker.io"
	}
	resp, err := client.Get(authURL)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", err
	}
	var out struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(body, &out); err != nil {
		return "", fmt.Errorf("reading the registry's token: %w", err)
	}
	if out.Token == "" {
		return "", fmt.Errorf("the registry issued no token for %s", repo)
	}
	return out.Token, nil
}

// readEnv reads the KEY=value lines of release.env. It is deliberately not a
// shell: the file is sourced by the bootstrap, so anything that needed quoting
// or expansion to be understood here would be a trap there.
func readEnv(path string) (map[string]string, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("%s: %q is not KEY=value", path, line)
		}
		out[strings.TrimSpace(k)] = strings.TrimSpace(v)
	}
	return out, nil
}

// stripDigest turns a tag-and-digest reference back into the tag alone, which
// is the question the registry answers.
func stripDigest(ref string) string {
	if i := strings.Index(ref, "@"); i >= 0 {
		return ref[:i]
	}
	return ref
}

