/* Progressive enhancement for Material's instant navigation. No animation
   library, per-frame JavaScript, remote assets or persistent tracking. */
(() => {
  const gestures = ["hello", "curious", "zoom", "spin"];
  const duration = 6000; // Matches the finite CSS performances.
  let dispose = () => {};

  function mount() {
    dispose();
    const root = document.querySelector("[data-zoomies-brand]");
    if (!root) return;
    const image = root.querySelector("img");
    const button = root.querySelector("button");
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    let alive = true;
    let ready = false;
    let visible = !("IntersectionObserver" in window);
    let paused = false;
    let timer = null;
    let started = 0;
    let remaining = 500;
    let active = false;
    let previous = "";
    let bag = [];

    function nextGesture() {
      if (!bag.length) {
        bag = [...gestures];
        for (let i = bag.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [bag[i], bag[j]] = [bag[j], bag[i]];
        }
        // Do not repeat across the boundary of two shuffled bags either.
        if (bag[bag.length - 1] === previous)
          [bag[0], bag[bag.length - 1]] = [bag[bag.length - 1], bag[0]];
      }
      previous = bag.pop();
      return previous;
    }

    function tick() {
      timer = null;
      if (active) {
        root.removeAttribute("data-gesture");
        remaining = 2600 + Math.random() * 4000;
      } else {
        root.dataset.gesture = nextGesture();
        remaining = duration;
      }
      active = !active;
      sync();
    }

    function sync() {
      const running =
        alive &&
        ready &&
        visible &&
        !document.hidden &&
        !reduced.matches &&
        !paused;
      root.dataset.paused = String(!running);
      if (!running && timer !== null) {
        clearTimeout(timer);
        timer = null;
        remaining = Math.max(0, remaining - (performance.now() - started));
      } else if (running && timer === null) {
        started = performance.now();
        timer = setTimeout(tick, remaining);
      }
      button.hidden = !ready || reduced.matches;
    }

    function toggle() {
      paused = !paused;
      button.textContent = paused
        ? "Resume logo animation"
        : "Pause logo animation";
      button.setAttribute("aria-pressed", String(paused));
      sync();
    }

    function motionChange() {
      sync();
      // A preference change returns to the canonical static mark immediately.
      if (reduced.matches) {
        root.removeAttribute("data-gesture");
        active = false;
        remaining = 500;
      }
    }

    const observer =
      "IntersectionObserver" in window
        ? new IntersectionObserver((entries) => {
            visible = entries.some((entry) => entry.isIntersecting);
            sync();
          })
        : null;
    observer?.observe(root);
    document.addEventListener("visibilitychange", sync);
    reduced.addEventListener("change", motionChange);
    button.addEventListener("click", toggle);
    dispose = () => {
      alive = false;
      if (timer !== null) clearTimeout(timer);
      observer?.disconnect();
      document.removeEventListener("visibilitychange", sync);
      reduced.removeEventListener("change", motionChange);
      button.removeEventListener("click", toggle);
      image.removeEventListener("load", enhance);
      root.classList.remove("is-ready");
      root.removeAttribute("data-gesture");
      button.hidden = true;
    };

    // Reuse the already-decoded source for every SVG layer. If it fails, the
    // ordinary accessible logo remains; never replace it with an empty canvas.
    //
    // Two things used to fetch a 176 KB file thousands of pixels below the fold
    // on every visit to the home page. decode() on a lazy image that has not
    // started loading starts it, and so does an SVG <image> that already has an
    // address, because SVG ignores loading="lazy". So the layers ship without
    // one: wait for the browser to load the <img> as the reader approaches,
    // decode what has arrived, give the layers its address (a cache hit), and
    // only then swap the static mark for the animated one.
    const layers = [...root.querySelectorAll("svg image")];

    function loadLayer(layer) {
      return new Promise((resolve, reject) => {
        layer.addEventListener("load", resolve, { once: true });
        layer.addEventListener("error", reject, { once: true });
        layer.setAttributeNS(
          "http://www.w3.org/1999/xlink",
          "xlink:href",
          image.currentSrc || image.src,
        );
      });
    }

    function enhance() {
      image
        .decode()
        .then(() => Promise.all(layers.map(loadLayer)))
        .then(() => {
          if (!alive) return;
          ready = true;
          root.classList.add("is-ready");
          sync();
        })
        .catch(() => {});
    }
    if (image.complete) enhance();
    else image.addEventListener("load", enhance, { once: true });
  }

  if (typeof document$ !== "undefined") document$.subscribe(mount);
  else if (document.readyState === "loading")
    document.addEventListener("DOMContentLoaded", mount, { once: true });
  else mount();
})();

/* The original monochrome logo and wordmark stay intact. All four performances
   start and finish at the identical neutral pose, so switching cannot jump. */
.zoomies-brand {
  width: min(320px, 100%);
  position: relative;
  padding-bottom: 44px;
}
.zoomies-brand__art {
  width: 100%;
  aspect-ratio: 1;
  position: relative;
}
.zoomies-brand__fallback,
.zoomies-brand__svg {
  display: block;
  width: 100%;
  height: 100%;
  filter: none;
}
.zoomies-brand__svg {
  position: absolute;
  inset: 0;
  visibility: hidden;
  overflow: visible;
}
.zoomies-brand.is-ready .zoomies-brand__svg {
  visibility: visible;
}
.zoomies-brand.is-ready .zoomies-brand__fallback {
  visibility: hidden;
}
.zoomies-brand .zoomies-brand__pause {
  display: block;
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  max-width: 100%;
  padding: 0.45rem 0.7rem;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 0.4rem;
  background: transparent;
  color: #f4f5f7;
  font: inherit;
  font-size: 0.6rem;
  min-height: 36px;
  cursor: pointer;
}
.zoomies-brand .zoomies-brand__pause[hidden] {
  display: none;
}
.zoomies-brand__pause:is(:hover, :focus-visible) {
  background: rgba(255, 255, 255, 0.1);
}
.zoomies-brand__pause:focus-visible {
  outline: 2px solid var(--z-brand-fast-cyan);
  outline-offset: 3px;
}
.zoomies-brand .zb-body,
.zoomies-brand .zb-head,
.zoomies-brand .zb-tail,
.zoomies-brand .zb-ear-left,
.zoomies-brand .zb-ear-right,
.zoomies-brand .zb-paw-front,
.zoomies-brand .zb-paw-back,
.zoomies-brand .zb-eyes,
.zoomies-brand .zb-tongue {
