  animation: zb-wag 0.52s ease-in-out infinite;
}
.zoomies-brand .zb-ear-left {
  transform-origin: 505px 325px;
  animation: zb-ear-left 2.4s ease-in-out infinite;
}
.zoomies-brand .zb-ear-right {
  transform-origin: 643px 303px;
  animation: zb-ear-right 2.4s ease-in-out infinite;
}
.zoomies-brand .zb-paw-front {
  transform-origin: 548px 566px;
  animation: zb-wave 5.6s ease-in-out infinite;
}
.zoomies-brand .zb-paw-back {
  transform-origin: 437px 560px;
}
.zoomies-brand .zb-eyes {
  transform-origin: 584px 350px;
