  animation: zb-stride 0.42s ease-in-out -0.21s infinite;
}
.zoomies-brand[data-gesture="spin"] .zb-ear-left {
  animation: zb-fly-left 0.42s ease-in-out infinite;
}
.zoomies-brand[data-gesture="spin"] .zb-ear-right {
  animation: zb-fly-right 0.42s ease-in-out infinite;
}
.zoomies-brand[data-gesture="spin"] .zb-tail {
  animation-duration: 0.26s;
}
@keyframes zb-spin {
  0% {
    transform: rotate(0);
  }
  8% {
    transform: rotate(-12deg);
  }
  34% {
    transform: rotate(360deg);
  }
  60% {
    transform: rotate(720deg);
  }
  70% {
    transform: rotate(736deg);
  }
  82%,
  100% {
    transform: rotate(720deg);
  }
}

/* One clock gives every layer a neutral boundary before the next gesture. */
.zoomies-brand[data-gesture] [class^="zb-"] {
  animation-duration: calc(6000ms / var(--zb-cycles, 1));
  animation-iteration-count: var(--zb-cycles, 1);
  animation-delay: 0s;
  animation-fill-mode: both;
}
.zoomies-brand .zb-body,
.zoomies-brand .zb-ear-left,
.zoomies-brand .zb-ear-right {
  --zb-cycles: 3;
}
.zoomies-brand .zb-tail {
  --zb-cycles: 12;
}
.zoomies-brand .zb-tongue {
  --zb-cycles: 6;
}
.zoomies-brand[data-gesture="curious"] .zb-tail {
  --zb-cycles: 6;
}
.zoomies-brand[data-gesture="curious"] .zb-ear-left {
  --zb-cycles: 1;
}
.zoomies-brand:is([data-gesture="zoom"], [data-gesture="spin"])
  :is(.zb-body, .zb-paw-front, .zb-paw-back, .zb-ear-left, .zb-ear-right) {
  --zb-cycles: 10;
}
.zoomies-brand[data-gesture="spin"] .zb-tail {
  --zb-cycles: 20;
}
.zoomies-brand:not([data-gesture]) [class^="zb-"] {
  animation: none;
}
@media (prefers-reduced-motion: reduce) {
  .zoomies-brand.is-ready .zoomies-brand__svg {
    visibility: hidden;
  }
  .zoomies-brand.is-ready .zoomies-brand__fallback {
    visibility: visible;
  }
  .zoomies-brand .zoomies-brand__pause {
    display: none;
  }
  .zoomies-brand [class^="zb-"] {
    animation: none !important;
  }
}
@media (pointer: coarse) {
  .zoomies-brand .zoomies-brand__pause {
    min-height: 44px;
  }
}

/*
 * The Zoomies theme for Material for MkDocs.
 *
 * The site and the product are meant to look like one family, so every value
 * in here is the one web/src/lib/styles/tokens.css uses: the same cool
 * near-black spine, the same darkened Runner Blue for interactive text, the
 * same radii, shadows and motion. Somebody who has spent a day in the
 * dashboard should find the docs familiar, and the other way round.
 *
 * See docs/brand.md for why Runner Blue is darkened for text -- #2F80ED is
 * 3.87:1 on white, which fails AA for body copy, so links use #1A63D8 and the
 * pure brand blue is kept for large shapes and glows.
 */

:root {
  --z-brand-black: #080808;
  --z-brand-cool-grey: #b9bcc2;
  --z-brand-mid-grey: #666a73;
  --z-brand-runner-blue: #2f80ed;
  --z-brand-fast-cyan: #22d3ee;

  /* Shape and motion are shared by both schemes; only the colours change. */
  --z-radius-sm: 4px;
  --z-radius-md: 8px;
  --z-radius-lg: 12px;
  --z-radius-xl: 16px;
  --z-motion-fast: 120ms;
  --z-motion-base: 200ms;
  --z-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* Motion is decoration. Anyone who has asked for less of it gets none. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --z-motion-fast: 1ms;
    --z-motion-base: 1ms;
  }
}

/* Light ------------------------------------------------------------------ */
[data-md-color-scheme='default'] {
  /* The header and footer sit on the page's own ground rather than on a black
     bar, so a reader sees one surface top to bottom and the sidebar and the
     article read as one page. The identity is still a monochrome mark with
     blue as an accent: the black lives in the stage the logo stands on, and
     the mark itself is swapped per scheme (overrides/partials/logo.html). */
  --md-primary-fg-color: #ffffff;
  --md-primary-fg-color--light: #f6f7f9;
  --md-primary-fg-color--dark: #eef0f3;
  --md-primary-bg-color: #0b0c0e;
  --md-primary-bg-color--light: #5b6069;
  --md-accent-fg-color: #154fb0;
  --md-accent-fg-color--transparent: rgba(26, 99, 216, 0.08);

  --md-default-bg-color: #f6f7f9;
  --md-default-fg-color: #0b0c0e;
  --md-default-fg-color--light: #5b6069;
  /* 5.0:1 on the page ground. The old #6e737c was 4.45:1 -- a hair under the
     4.5 that WCAG AA asks of text this small -- and it is what the sidebar's
     section titles and the footer's secondary line are set in. */
  --md-default-fg-color--lighter: #666b74;
  --md-default-fg-color--lightest: rgba(11, 12, 14, 0.08);
  --md-typeset-a-color: #1a63d8;
  --md-code-bg-color: #eef0f3;
  --md-code-fg-color: #1c1f26;
  /* Material picked its syntax colours for a near-white code ground. On ours
     (#eef0f3) its keyword blue is 4.32:1 and its string, constant, number,
     function and special colours are 4.3 to 4.5:1 -- under the 4.5 that
     WCAG AA asks of text this small, on every page that shows a workflow or a
     command. Each below is the same hue a few points darker, at 4.8 to 5.1:1. */
  --md-code-hl-keyword-color: #3a66b8;
  --md-code-hl-string-color: #1a7447;
  --md-code-hl-constant-color: #6750d7;
  --md-code-hl-number-color: #c82828;
  --md-code-hl-function-color: #9a41aa;
  --md-code-hl-special-color: #cd1351;
  --md-footer-bg-color: #f6f7f9;
  --md-footer-bg-color--dark: #ffffff;
  --md-footer-fg-color: #0b0c0e;
  --md-footer-fg-color--light: #5b6069;
  --md-footer-fg-color--lighter: #666b74;

  --z-surface: #ffffff;
  --z-surface-raised: #ffffff;
  --z-line: #e2e5ea;
  --z-line-strong: #c7cbd3;
  --z-accent: #1a63d8;
  --z-accent-hover: #154fb0;
  --z-accent-subtle: #e8f0fd;
  --z-accent-border: #bcd4f8;
  --z-accent-contrast: #ffffff;
  --z-shadow-sm: 0 1px 2px rgb(8 12 20 / 0.06);
  --z-shadow-md: 0 4px 12px -2px rgb(8 12 20 / 0.1);
  --z-shadow-lg: 0 16px 40px -8px rgb(8 12 20 / 0.16);
}

/* Dark: the identity's own ground, and the default. ---------------------- */
[data-md-color-scheme='slate'] {
  --md-hue: 220;
  --md-primary-fg-color: #0a0b0d;
  --md-primary-fg-color--light: #131519;
  --md-primary-fg-color--dark: #050607;
  --md-primary-bg-color: #f4f5f7;
  --md-primary-bg-color--light: #b9bcc2;
  --md-accent-fg-color: #78b4ff;
  --md-accent-fg-color--transparent: rgba(120, 180, 255, 0.1);

  --md-default-bg-color: #0a0b0d;
  --md-default-fg-color: #f4f5f7;
  --md-default-fg-color--light: #b9bcc2;
  --md-default-fg-color--lighter: #868b94;
  --md-default-fg-color--lightest: rgba(244, 245, 247, 0.09);
  --md-typeset-a-color: #78b4ff;
  --md-code-bg-color: #131519;
  --md-code-fg-color: #f4f5f7;
  --md-footer-bg-color: #0a0b0d;
  --md-footer-bg-color--dark: #0a0b0d;
  --md-footer-fg-color: #f4f5f7;
  --md-footer-fg-color--light: #b9bcc2;
  --md-footer-fg-color--lighter: #868b94;

  --z-surface: #131519;
  --z-surface-raised: #1b1e23;
  --z-line: #262a31;
  --z-line-strong: #363b44;
  --z-accent: #78b4ff;
  --z-accent-hover: #9bc9ff;
  --z-accent-subtle: #10203a;
  --z-accent-border: #1e3a63;
  --z-accent-contrast: #08131f;
  --z-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
  --z-shadow-md: 0 4px 12px -2px rgb(0 0 0 / 0.6);
  --z-shadow-lg: 0 16px 40px -8px rgb(0 0 0 / 0.7);
}

/* ------------------------------------------------------------------------ */
/* Type. Inter and JetBrains Mono, per the brand.                            */
/* ------------------------------------------------------------------------ */

/*
 * Self-hosted, exactly as the product does, rather than fetched from Google
 * Fonts by the theme's default font block. A third-party stylesheet in the head
 * is render-blocking: where fonts.googleapis.com is slow, blocked or blackholed
 * the browser waits on it with the tab still spinning, and where it is merely
 * reachable the reader's IP is still handed to Google to read documentation.
 * The faces are the two the interface uses, subset to Latin, copied from the
 * same @fontsource packages web/ builds against.
 */
@font-face {
  font-family: 'InterVariable';
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url('fonts/inter-latin-wght-normal.woff2') format('woff2-variations');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'InterVariable';
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url('fonts/inter-latin-ext-wght-normal.woff2') format('woff2-variations');
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329,
    U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F,
    U+A720-A7FF;
}
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-display: swap;
  font-weight: 400;
  src: url('fonts/jetbrains-mono-latin-400-normal.woff2') format('woff2');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-display: swap;
  font-weight: 500;
  src: url('fonts/jetbrains-mono-latin-500-normal.woff2') format('woff2');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

body,
input,
.md-typeset {
  font-feature-settings: 'cv05' 1, 'ss03' 1;
}
.md-typeset {
  line-height: 1.65;
}
.md-typeset code,
.md-typeset pre {
  font-variant-ligatures: none;
}
::selection {
  background: rgba(47, 128, 237, 0.3);
}

/* Headings carry the structure of a long reference page, so they are given
   more weight and more air than Material's defaults, and every h2 sits on a
   hairline so a reader scrolling fast can see where a section starts. */
.md-typeset h1 {
  font-size: 2.1em;
  font-weight: 700;
  letter-spacing: -0.024em;
  line-height: 1.15;
  margin: 0 0 1em;
  color: var(--md-default-fg-color);
}
.md-typeset h2 {
  font-size: 1.45em;
  font-weight: 640;
  letter-spacing: -0.018em;
  line-height: 1.25;
  margin: 2.4em 0 0.9em;
  padding-bottom: 0.35em;
  border-bottom: 1px solid var(--z-line);
}
.md-typeset h3 {
  font-size: 1.12em;
  font-weight: 600;
  letter-spacing: -0.012em;
  line-height: 1.3;
  margin: 2em 0 0.7em;
}
.md-typeset h4 {
  font-size: 0.95em;
  font-weight: 600;
  margin-top: 1.6em;
}
.md-typeset h1 + h2,
.md-typeset h2 + h3 {
  margin-top: 1.4em;
}
.md-typeset .headerlink {
  transition: opacity var(--z-motion-fast) var(--z-ease);
}

.md-typeset a {
  text-underline-offset: 0.16em;
  text-decoration-thickness: 1px;
  transition: color var(--z-motion-fast) var(--z-ease);
}
.md-typeset a:not(.md-button):is(:hover, :focus-visible) {
  text-decoration: underline;
}

/* Inline code is set on its own chip, so a key name or a flag is visibly a
   thing to type and not a word in the sentence. */
.md-typeset :not(pre) > code {
  padding: 0.1em 0.4em;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-sm);
  font-size: 0.82em;
}
.md-typeset h1 code,
.md-typeset h2 code,
.md-typeset h3 code {
  font-size: 0.82em;
  font-weight: 500;
}
.md-typeset a code {
  color: inherit;
}

/* Code blocks: a rounded, bordered panel, matching the product's surfaces. */
.md-typeset pre:not(.mermaid) > code {
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-md);
  padding: 0.9em 1.15em;
  line-height: 1.55;
}
.md-typeset .highlight span.filename {
  border: 1px solid var(--z-line);
  border-bottom: 0;
  border-radius: var(--z-radius-md) var(--z-radius-md) 0 0;
  font-family: var(--md-code-font-family);
  font-size: 0.7em;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--md-default-fg-color--light);
}
.md-typeset .highlight span.filename + pre > code {
  border-top: 0;
}
/* The copy button sits in a chip Material pins to the block's top-right corner,
   offset for its own padding. Ours is deeper and has a border, so the chip is
   pushed in far enough to stay centred on the first line of code and clear of
   the rounded corner rather than riding high against it. */
.md-typeset .md-code__nav {
  top: 0.5em;
  right: 0.5em;
  border-radius: var(--z-radius-sm);
  transition: background-color var(--z-motion-fast) var(--z-ease);
}
.md-typeset .md-code__button {
  transition: color var(--z-motion-fast) var(--z-ease);
}

/* Tables: a bordered card with a quiet header row, rather than lines drawn
   across the page. The configuration reference is mostly tables. */
.md-typeset table:not([class]) {
  font-size: 0.7rem;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
  box-shadow: var(--z-shadow-sm);
}
.md-typeset table:not([class]) th {
  padding: 0.8em 1.1em;
  min-width: 0;
  background: var(--md-code-bg-color);
  border-bottom: 1px solid var(--z-line);
  color: var(--md-default-fg-color--light);
  font-size: 0.66rem;
  font-weight: 600;
  vertical-align: bottom;
}
.md-typeset table:not([class]) td {
  padding: 0.8em 1.1em;
  border-top: 1px solid var(--z-line);
}
.md-typeset table:not([class]) tbody tr {
  transition: background-color var(--z-motion-fast) var(--z-ease);
}
.md-typeset table:not([class]) tbody tr:hover {
  background: var(--md-accent-fg-color--transparent);
  box-shadow: none;
}

/* Admonitions and collapsible details take the product's radius and lose
   Material's drop shadow: on this near-black ground a shadow is invisible
   and on the light one it makes a note float off the page it belongs to. */
.md-typeset .admonition,
.md-typeset details {
  border-radius: var(--z-radius-md);
  border-width: 1px;
  border-left-width: 3px;
  box-shadow: none;
  background: var(--z-surface);
}
.md-typeset .admonition-title,
.md-typeset summary {
  font-weight: 600;
}
.md-typeset .admonition-title,
.md-typeset summary {
  border-radius: calc(var(--z-radius-md) - 1px) calc(var(--z-radius-md) - 1px) 0 0;
}

.md-typeset .tabbed-labels > label {
  font-weight: 550;
}

.md-typeset hr {
  border-bottom: 1px solid var(--z-line);
  margin: 2em 0;
}

.md-typeset blockquote {
  border-left: 3px solid var(--z-line-strong);
  color: var(--md-default-fg-color--light);
}

/* Diagrams. Material derives every --md-mermaid-* colour from the palette
   above, so a diagram follows whichever theme the reader is in without any
   colour of its own. What it does not do is bound the width: a topology drawn
   for a laptop is wider than a phone, and it has to scroll inside its own box
   rather than push the article sideways. The box is a panel like a code block,
   so a diagram and the fenced YAML beside it look like they belong together. */
.md-typeset .mermaid {
  overflow-x: auto;
  overflow-y: hidden;
  padding: 1rem 1.2rem;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
}

/* Buttons. The product's, in the docs: a filled accent primary and a quiet
   bordered secondary, both on the same radius as everything else here. */
.md-typeset .md-button {
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  padding: 0.6em 1.15em;
  border: 1px solid var(--z-line-strong);
  border-radius: var(--z-radius-md);
  background: var(--z-surface);
  color: var(--md-default-fg-color);
  font-size: 0.72rem;
  font-weight: 550;
  letter-spacing: -0.005em;
  line-height: 1.3;
  box-shadow: var(--z-shadow-sm);
  transition:
    background-color var(--z-motion-fast) var(--z-ease),
    border-color var(--z-motion-fast) var(--z-ease),
    color var(--z-motion-fast) var(--z-ease),
    box-shadow var(--z-motion-fast) var(--z-ease),
    transform var(--z-motion-fast) var(--z-ease);
}
.md-typeset .md-button:is(:hover, :focus-visible) {
  background: var(--z-surface-raised);
  border-color: var(--md-default-fg-color--lighter);
  color: var(--md-default-fg-color);
  box-shadow: var(--z-shadow-md);
  transform: translateY(-1px);
}
.md-typeset .md-button--primary {
  background: var(--z-accent);
  border-color: var(--z-accent);
  color: var(--z-accent-contrast);
}
.md-typeset .md-button--primary:is(:hover, :focus-visible) {
  background: var(--z-accent-hover);
  border-color: var(--z-accent-hover);
  color: var(--z-accent-contrast);
}
.md-typeset .md-button .twemoji {
  height: 1em;
  vertical-align: -0.1em;
}
.md-typeset .md-button .twemoji svg {
  width: 1em;
}

/* ------------------------------------------------------------------------ */
/* Chrome: header, navigation, table of contents, footer.                    */
/* ------------------------------------------------------------------------ */

/* The page is a little wider than Material's default: the article column is
   the one that grows, and a reference table or a diagram gets the room. */
.md-grid {
  max-width: 66rem;
}

/* The header is the page's ground with a hairline under it, frosted so the
   article shows through as it scrolls under. */
.md-header {
  background: color-mix(in srgb, var(--md-default-bg-color) 86%, transparent);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--z-line);
}
.md-header--shadow {
  box-shadow: var(--z-shadow-sm);
}
.md-header__title {
  font-weight: 640;
  letter-spacing: -0.01em;
}
/* One mark per scheme, drawn by overrides/partials/logo.html and the footer:
   white line art for the dark ground, black for the light one. The drawer's
   selector matches Material's own for the phone drawer's title, which would
   otherwise outrank this one and draw the mark at 2.4rem. */
.md-header__button.md-logo img,
.md-nav__title .md-nav__button.md-logo img {
  height: 1.5rem;
  width: 1.5rem;
}
/* Material's `.md-nav__title .md-nav__button.md-logo img` sets `display` too,
   and outranks a scheme attribute and two classes: in the phone drawer both
   marks showed, one stacked under the other, and the visible one landed on
   the site name. Naming `.md-logo` as well puts this rule above it. */
[data-md-color-scheme='default'] .md-logo .zoomies-logo.zoomies-logo--dark,
[data-md-color-scheme='slate'] .md-logo .zoomies-logo.zoomies-logo--light,
[data-md-color-scheme='default'] .zoomies-logo.zoomies-logo--dark,
[data-md-color-scheme='slate'] .zoomies-logo.zoomies-logo--light {
  display: none;
}
.md-header__button.md-logo:is(:hover, :focus-visible) {
  opacity: 1;
}
/* The second header topic holds the page title before the theme's script runs.
   A long title must stay inside its flex item, including with JavaScript off. */
.md-header__title {
  min-width: 0;
  overflow: hidden;
}
.md-search__form {
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-md);
  background: var(--md-code-bg-color);
  transition:
    background-color var(--z-motion-fast) var(--z-ease),
    border-color var(--z-motion-fast) var(--z-ease);
}
.md-search__form:hover {
  background: var(--z-surface-raised);
  border-color: var(--z-line-strong);
}
[data-md-toggle='search']:checked ~ .md-header .md-search__form {
  border-color: transparent;
  border-radius: var(--z-radius-md) var(--z-radius-md) 0 0;
}
.md-search__output {
  border-radius: 0 0 var(--z-radius-md) var(--z-radius-md);
}
.md-search-result__meta {
  font-size: 0.6rem;
}
.md-source {
  border-radius: var(--z-radius-md);
  transition: background-color var(--z-motion-fast) var(--z-ease);
}
.md-source:hover {
  background: var(--md-code-bg-color);
  opacity: 1;
}

/* The sidebar is a list of pills. A section's name is set bold at reading
   size, the pages under it carry their icon, and the current page is the one
   filled with the accent's tint -- the same signal the product's navigation
   uses for the current section. */
.md-nav--primary .md-nav__item--section > .md-nav__link {
  margin-top: 1.1em;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: var(--md-default-fg-color);
}
.md-nav--secondary .md-nav__title {
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--md-default-fg-color--lighter);
}
.md-nav__link {
  border-radius: var(--z-radius-md);
  transition:
    color var(--z-motion-fast) var(--z-ease),
    background-color var(--z-motion-fast) var(--z-ease);
}
.md-sidebar--primary .md-nav__link {
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.1em;
  padding: 0.32em 0.55em;
}
.md-sidebar--primary .md-nav__link svg {
  width: 0.8rem;
  height: 0.8rem;
  margin: 0;
  color: var(--md-default-fg-color--lighter);
}
.md-sidebar--primary .md-nav__link:not(.md-nav__container):is(:hover, :focus-visible) {
  background: var(--md-code-bg-color);
  color: var(--md-default-fg-color);
}
.md-sidebar--primary .md-nav__item--section > .md-nav__link:is(:hover, :focus-visible) {
  background: none;
}
.md-sidebar--primary .md-nav__item .md-nav__link--active {
  background: var(--z-accent-subtle);
  color: var(--z-accent);
  font-weight: 550;
}
.md-sidebar--primary .md-nav__item .md-nav__link--active:is(:hover, :focus-visible) {
  background: var(--z-accent-subtle);
  color: var(--z-accent);
}
.md-sidebar--primary .md-nav__link--active svg {
  color: var(--z-accent);
}

/* The table of contents is a rail: a hairline down its left, and the heading
   in view lifts its stretch of the rail to the accent. */
.md-nav--secondary .md-nav__link {
  margin-top: 0;
  padding: 0.22em 0 0.22em 0.65em;
  border-left: 2px solid var(--z-line);
  border-radius: 0;
  transition:
    color var(--z-motion-fast) var(--z-ease),
    border-color var(--z-motion-fast) var(--z-ease);
}
.md-nav--secondary .md-nav__item .md-nav__item .md-nav__link {
  padding-left: 1.4em;
}
.md-nav--secondary .md-nav__link--active {
  border-left-color: var(--z-accent);
  color: var(--z-accent);
  font-weight: 550;
}

@media screen and (min-width: 76.25em) {
  .md-sidebar--primary .md-nav--primary > .md-nav__title {
    font-size: 0.6rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--md-default-fg-color--lighter);
  }
  /* The rail's title is sticky and paints over what scrolls under it; the
     first entry needs this much room not to start underneath it. */
  .md-nav--secondary > .md-nav__list {
    padding-top: 0.35rem;
    padding-bottom: 0;
  }
}

/* The back-to-top pill. */
.md-top {
  border: 1px solid var(--z-line);
  border-radius: 999px;
  box-shadow: var(--z-shadow-md);
  font-weight: 550;
}

/* The footer is the page's ground too, so a page is one surface from the
   header down. Previous and next are a pair of cards. */
.md-footer {
  border-top: 1px solid var(--z-line);
}
.md-footer__inner.md-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
  padding: 1.2rem 0.6rem 0.4rem;
}
.md-footer__link {
  width: 100%;
  margin: 0;
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface);
  opacity: 1;
  transition:
    border-color var(--z-motion-fast) var(--z-ease),
    box-shadow var(--z-motion-fast) var(--z-ease);
}
.md-footer__link--next {
  grid-column: 2;
}
.md-footer__link:is(:hover, :focus-visible) {
  border-color: var(--z-accent-border);
  box-shadow: var(--z-shadow-sm);
  opacity: 1;
}
.md-footer__direction {
  font-size: 0.56rem;
  font-weight: 550;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.7;
}
.md-footer__title {
  font-size: 0.76rem;
}
.md-footer-meta {
  border-top: 1px solid var(--z-line);
}
.md-footer-meta__inner {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: start;
  gap: 0.5rem 1.5rem;
  padding: 1.1rem 0.8rem 1.3rem;
}
.md-copyright {
  width: auto;
  margin: 0;
  padding: 0;
}
.md-social {
  margin: 0;
  padding: 0;
}
.md-social__link {
  border-radius: var(--z-radius-md);
  transition: background-color var(--z-motion-fast) var(--z-ease);
}
.md-social__link:is(:hover, :focus-visible) {
  background: var(--md-code-bg-color);
}

/* What overrides/partials/copyright.html renders. */
.zoomies-footer {
  display: grid;
  gap: 0.6rem;
  color: var(--md-footer-fg-color--lighter);
  font-size: 0.62rem;
}
.zoomies-footer__brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.zoomies-footer__brand img {
  width: 1.4rem;
  height: 1.4rem;
}
.zoomies-footer__name {
  font-size: 0.8rem;
  font-weight: 640;
  letter-spacing: -0.01em;
  color: var(--md-footer-fg-color);
}
.zoomies-footer__descriptor {
  font-size: 0.56rem;
  font-weight: 550;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--md-default-fg-color--lighter);
}
/* The footer sits inside .md-typeset, whose list rules would otherwise turn
   this row of links into a bulleted list -- and its `ul:not([hidden])` rule
   outranks a plain class, hence the extra ancestor here. */
.md-typeset .zoomies-footer .zoomies-footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.md-typeset .zoomies-footer .zoomies-footer__links li {
  margin: 0;
  padding: 0;
}
.md-typeset .zoomies-footer__links a {
  font-size: 0.66rem;
  color: var(--md-footer-fg-color--light);
}
.zoomies-footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.6rem;
}
.zoomies-footer__legal > * + *::before {
  content: '·';
  margin-right: 0.6rem;
  opacity: 0.6;
}
.zoomies-footer .md-copyright__highlight {
  color: inherit;
}
.zoomies-footer a {
  color: var(--md-footer-fg-color--light);
  transition: color var(--z-motion-fast) var(--z-ease);
}
.zoomies-footer a:is(:hover, :focus-visible) {
  color: var(--md-footer-fg-color);
  text-decoration: underline;
  text-underline-offset: 0.16em;
}
.zoomies-footer__credit a {
  font-weight: 550;
  color: var(--md-footer-fg-color);
}

/* ------------------------------------------------------------------------ */
/* The home page.                                                            */
/* ------------------------------------------------------------------------ */

/* The hero's own heading is the page's h1, so MkDocs generates no "Home" title
   above it. Should a future layout reintroduce one outside the hero, it is a
   second and worse title and is hidden -- but the one inside the hero is the
   real heading and is styled below. */
.md-content__inner:has(.zoomies-hero) > h1:first-of-type {
  display: none;
}

/* The hero sits on the page like everything under it: an eyebrow, the
   headline, the install command, what to do about it and the pages people come
   for. The identity's full lockup, animated, closes the page (.zoomies-cta). */
.zoomies-hero {
  position: relative;
  isolation: isolate;
  display: grid;
  /* One column that may shrink below its content: the install command is a
     single unbreakable line, and on a phone it must scroll inside its own box
     rather than widen the column and push everything else off the edge. */
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  gap: 1.1rem;
  text-align: center;
  padding: 2.5rem 0 1rem;
  margin: 0 0 2.5rem;
}
.zoomies-hero > * {
  min-width: 0;
  max-width: 100%;
}
/* A glow behind the headline, and a dot grid that fades out before it reaches
   the words, so the top of the page has texture and the text sits on a plain
   surface. Both are the accent at low alpha, so they read in either theme.
   It bleeds above the hero but not past its sides. A side bleed of 2rem ran 24px
   beyond the article's gutters at every width up to about 1366px, which on a
   phone widened the layout viewport to 399px on a 375px screen (the page then
   pans, or renders zoomed out) and on a laptop gave the page a sideways
   scrollbar -- for a glow that has faded to nothing long before the edge. */
.zoomies-hero::before {
  content: '';
  position: absolute;
  inset: -3rem 0 30%;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(rgba(47, 128, 237, 0.16) 1px, transparent 1.3px) 0 0 / 22px 22px,
    radial-gradient(55% 60% at 50% 0%, rgba(47, 128, 237, 0.16) 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(60% 70% at 50% 15%, #000 0%, transparent 100%);
  mask-image: radial-gradient(60% 70% at 50% 15%, #000 0%, transparent 100%);
}
/* The eyebrow: what is new, one line, above the headline. */
.md-typeset .zoomies-hero .eyebrow {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5em;
  margin: 0;
  padding: 0.3em 0.85em 0.3em 0.35em;
  border: 1px solid var(--z-line);
  border-radius: 999px;
  background: var(--z-surface);
  font-size: 0.66rem;
  font-weight: 500;
  color: var(--md-default-fg-color--light);
}
/* The left padding is smaller only to sit a badge snugly inside the pill; a
   pill that holds plain text keeps the padding on both ends the same. */
.md-typeset .zoomies-hero .eyebrow:not(:has(strong)) {
  padding-left: 0.85em;
}
.md-typeset .zoomies-hero .eyebrow strong {
  padding: 0.1em 0.6em;
  border-radius: 999px;
  background: var(--z-accent);
  color: var(--z-accent-contrast);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.md-typeset .zoomies-hero .eyebrow a {
  color: inherit;
}
.md-typeset .zoomies-hero .eyebrow a:is(:hover, :focus-visible) {
  color: var(--md-default-fg-color);
}
/* The hero's headline. It is an h1 rather than a paragraph because it is the
   page's real title, and Material's own h1 rules have to be overridden for it
   to be set this large. The second line is quieter than the first. */
.md-typeset .zoomies-hero h1 {
  margin: 0;
  font-size: clamp(2rem, 5.6vw, 3.6rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.06;
  color: var(--md-default-fg-color);
  text-wrap: balance;
}
.md-typeset .zoomies-hero h1 .quiet {
  color: var(--md-default-fg-color--lighter);
}
/* The permalink Material appends to every heading is invisible until hovered,
   but it still takes room: it pushed the last line of the headline 25px left of
   centre on a desktop and 16px on a phone, and it was a stop in the tab order
   with nothing to see. The hero's heading is not a section anyone links to. */
.md-typeset .zoomies-hero h1 .headerlink {
  display: none;
}

/* The proof line under the hero: one sentence of evidence, for the reader who
   has taken in the panel and wants a reason to believe it. */
.md-typeset .zoomies-proof {
  max-width: 46rem;
  margin: 0 auto 2.5rem;
  font-size: 0.9rem;
  line-height: 1.65;
  text-align: center;
  text-wrap: pretty;
  color: var(--md-default-fg-color--light);
}
.zoomies-hero .lede {
  max-width: 40rem;
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--md-default-fg-color--light);
  text-wrap: pretty;
}

/* The article under the hero. Its column is 1288px wide at 1440px, which is
   right for a table, a grid or a screenshot and wrong for a sentence: a
   paragraph ran to 172 characters a line, and nobody finds their place again at
   that length. Prose is held to a little under a hundred characters; 72ch is
   that, since the zero this unit is measured in is wider than the average
   letter. The hero, the proof line, the screenshots and their caption keep the
   width they were given. */
.md-content__inner:has(.zoomies-hero)
  > :is(p, ul, ol):not(.zoomies-proof, .zoomies-shot-caption, :has(> .zoomies-shot)) {
  max-width: 72ch;
}
/* The tables, on the other hand, take the whole column. Material draws each as
   an inline-block that shrinks to its content, so the page's three were 983,
   1288 and 656px wide, which read as three different mistakes -- and a box
   stretched to the column over columns that were not would only have put empty
   white beside the last of them. So a table here is a real table, as wide as
   the column. The radius still clips the cells' fills at the corners, which is
   what `overflow` on an inline-block was there for. (The article is itself the
   `.md-typeset`, which is why `table` follows `.md-content__inner` directly in
   this selector rather than `.md-typeset` as it does everywhere else.) */
.md-content__inner:has(.zoomies-hero) .md-typeset__table {
  display: block;
}
.md-content__inner:has(.zoomies-hero) table:not([class]) {
  display: table;
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
}

/* The install command, which is the one thing most visitors came for: a
   single line in a raised box, with the copy button as a filled chip. */
.zoomies-install {
  width: min(30rem, 100%);
  text-align: left;
}
.zoomies-install .md-typeset,
.zoomies-install pre,
.md-typeset .zoomies-install .highlight {
  margin: 0;
}
.md-typeset .zoomies-install pre > code {
  /* Room on the right for the chip, so on a phone the command's tail scrolls
     clear of it instead of disappearing under it. */
  padding: 0.95em 4.4em 0.95em 1.1em;
  border: 1px solid var(--z-line-strong);
  border-radius: var(--z-radius-lg);
  background: var(--z-surface);
  color: var(--md-default-fg-color);
  font-size: 0.78rem;
  box-shadow: var(--z-shadow-md);
}
/* The command is a single line, so its copy button is centred on it the way an
   input's button would be, not pinned to the top corner as on a block that may
   run to many lines. */
.md-typeset .zoomies-install .md-code__nav {
  top: 50%;
  right: 0.45em;
  transform: translateY(-50%);
  border-radius: var(--z-radius-md);
  background: var(--z-accent);
}
.md-typeset .zoomies-install pre:hover > .md-code__nav {
  background: var(--z-accent-hover);
}
.zoomies-install .md-code__button,
.zoomies-install pre:hover .md-code__button {
  color: var(--z-accent-contrast);
}

/* The two things a visitor can do about the command, side by side: read how to
   install it, or see the product first. Same row as the closing call to
   action's, so the page asks the same thing the same way twice. */
.md-typeset .zoomies-hero .actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.6rem;
  margin: 0;
}

/* What the command assumes, in one quiet line, so a visitor can tell whether
   this is for them before they paste anything. Set in the body's secondary
   text colour, not the quieter one: it is small, and the quieter one is under
   4.5:1 on the light ground. */
.md-typeset .zoomies-hero .prereq {
  max-width: 34rem;
  margin: 0;
  font-size: 0.66rem;
  line-height: 1.5;
  color: var(--md-default-fg-color--light);
  text-wrap: balance;
}

/* The pages people come for, as a row of chips under the command. */
.md-typeset .zoomies-hero .popular {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.4rem;
  margin: 0.15rem 0 0;
  font-size: 0.66rem;
  color: var(--md-default-fg-color--lighter);
}
.md-typeset .zoomies-hero .popular a {
  padding: 0.3em 0.7em;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-md);
  background: var(--md-code-bg-color);
  color: var(--md-default-fg-color--light);
  font-weight: 500;
  transition:
    color var(--z-motion-fast) var(--z-ease),
    border-color var(--z-motion-fast) var(--z-ease);
}
.md-typeset .zoomies-hero .popular a:is(:hover, :focus-visible) {
  color: var(--md-default-fg-color);
  border-color: var(--z-line-strong);
  text-decoration: none;
}

/* Feature cards: a three-across grid, each with an icon on the accent chip. */
.zoomies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 0.9rem;
  margin: 1.5rem 0 2.5rem;
}
/* Nine cards divide into three columns and into nothing else that fits. The
   auto-fit layout above counts four columns from 1366px up and laid the grid
   out 4 / 4 / 1, leaving one card alone on the last row beside three empty
   cells; asking for three says what the content is. Below this width the cards
   stack or pair, and the card that would be left on its own takes the row. */
@media screen and (min-width: 48em) {
  .zoomies-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media screen and (min-width: 40.625em) and (max-width: 47.9375em) {
  .zoomies-grid > div:nth-last-child(2) {
    grid-column: 1 / -1;
  }
}
.zoomies-grid > div {
  padding: 1.15rem 1.2rem 1.25rem;
  border: 1px solid var(--z-line);
  border-radius: var(--z-radius-xl);
  background: var(--z-surface);
  box-shadow: var(--z-shadow-sm);
  transition:
    border-color var(--z-motion-base) var(--z-ease),
    box-shadow var(--z-motion-base) var(--z-ease),
    transform var(--z-motion-base) var(--z-ease);
}
.zoomies-grid > div:hover {
  border-color: var(--z-accent-border);
  box-shadow: var(--z-shadow-md);
  transform: translateY(-2px);
}
.md-typeset .zoomies-grid p:has(> .icon) {
  margin: 0 0 0.8rem;
  line-height: 0;
}
.md-typeset .zoomies-grid .icon {
  display: inline-grid;
  place-items: center;
  width: 2.1rem;
  height: 2.1rem;
  border: 1px solid var(--z-accent-border);
  border-radius: var(--z-radius-md);
  background: var(--z-accent-subtle);
  color: var(--z-accent);
  vertical-align: top;
}
.md-typeset .zoomies-grid .icon svg {
  width: 1.15rem;
  height: 1.15rem;
}
.md-typeset .zoomies-grid h3 {
  margin: 0 0 0.35rem;
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
}
.md-typeset .zoomies-grid p {
  margin: 0;
  font-size: 0.74rem;
  line-height: 1.55;
  color: var(--md-default-fg-color--light);
}
/* One card is a sentence longer than the rest and spans the row, with the
   icon beside the text rather than above it. */
.zoomies-grid .wide {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 1rem;
  align-items: start;
}
.md-typeset .zoomies-grid .wide p:has(> .icon) {
  grid-row: 1 / span 2;
  margin: 0;
}
.zoomies-grid .wide h3,
.zoomies-grid .wide p:not(:has(> .icon)) {
  grid-column: 2;
}

/* The comparison table: the Zoomies column is the one the reader is here for,
   so it is the second column, next to the row labels. It used to be the last,
   and on a 375px phone the table scrolls sideways inside its box: the reader
   saw "Zoomi", "ye" and "defau" at the cut and never the column the table
   exists to show. */
.md-typeset .zoomies-compare table:not([class]) th:nth-child(2),
.md-typeset .zoomies-compare table:not([class]) td:nth-child(2) {
  background: var(--z-accent-subtle);
  font-weight: 550;
}
.md-typeset .zoomies-compare table:not([class]) th:nth-child(2) {
  color: var(--z-accent);
}
.md-typeset .zoomies-compare .twemoji {
  height: 1em;
  margin-right: 0.15em;
  vertical-align: -0.12em;
}
.md-typeset .zoomies-compare .twemoji svg {
  width: 1em;
}
.md-typeset .zoomies-compare .yes {
  color: var(--z-accent);
}
.md-typeset .zoomies-compare .no,
.md-typeset .zoomies-compare .partial {
  color: var(--md-default-fg-color--lighter);
}
/* On a narrow phone four columns need 387px and the column the phone has is
   343px, so the last of them was cut off at the edge of the screen with nothing
   to say there was more -- 28px of it at 375px and 83px at 320px. The table
   scrolls inside its own box instead: every column is still there and the page
   does not move. 30em is 480px, which is every phone in portrait and no tablet. */
@media screen and (max-width: 30em) {
  .md-typeset .zoomies-compare .md-typeset__table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
  }
}

/* The closing call to action is the identity's own ground: Zoomies Black in
   both themes, the animated lockup on the left, and the one place on the page
   the pure brand blue is allowed to glow. The primary button is white here
   rather than blue -- the brand is a monochrome mark with blue as an accent,
   and the accent is already spent on the glow behind the logo. */
.zoomies-cta {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  /* A fixed first column: the lockup's fallback image is 1254px wide, and an
     auto track would size itself to that and starve the copy beside it. */
  grid-template-columns: 12rem minmax(0, 1fr);
  align-items: center;
  gap: 1.5rem 2.5rem;
  margin: 3rem 0 1rem;
  padding: 2rem 2.25rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--z-radius-xl);
  background:
    radial-gradient(60% 80% at 15% 50%, rgba(47, 128, 237, 0.3) 0%, transparent 70%),
    radial-gradient(45% 40% at 90% 100%, rgba(34, 211, 238, 0.09) 0%, transparent 70%),
    var(--z-brand-black);
  color: #f4f5f7;
  box-shadow: 0 30px 80px -40px rgba(47, 128, 237, 0.35);
  text-align: left;
}
/* A dot grid that fades towards the edges, so the panel has texture where the
   logo sits and reads as a plain surface where the text does. */
.zoomies-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
