}

/* ------------------------------------------------------------------------ */
/* Phones.                                                                   */
/* ------------------------------------------------------------------------ */

@media screen and (max-width: 44.9375em) {
  .zoomies-hero {
    padding: 1.25rem 0 0.5rem;
  }
  /* The glow is drawn two rem wider than the hero on each side so that it
     bleeds past the text column. On a phone the column already reaches the
     gutter, so the bleed is 24px of page that scrolls sideways, and the browser
     answers by zooming out until nothing can be pressed. It stops at the edge. */
  .zoomies-hero::before {
    inset: -3rem 0 30%;
  }
  /* The install command wraps, at a space, instead of scrolling away under its
     own copy chip: a phone shows the whole of the one string this page exists
     to hand over, and the chip still copies it as a single line. */
  .md-typeset .zoomies-install pre > code {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    /* Small enough that the address itself stays in one piece at the common
       phone widths, so the break falls at a space and not inside "install.sh". */
    font-size: 0.7rem;
  }
  .zoomies-hero .lede {
    font-size: 0.8rem;
  }
  .md-typeset .zoomies-hero .eyebrow {
    font-size: 0.6rem;
  }
  /* The headline is two clauses, white then grey, with a forced break between
     them. On a phone the forced break left "own." stranded on a line of its
     own, and taking the break out made the colour change in the middle of a
     line, after "runners". Making the grey clause a block gives each its own
     balanced lines -- four on every phone from 320px to 430px -- so the colour
     changes where a line does. The break is redundant once the clause is a
     block, and would add an empty line if it stayed. */
  .md-typeset .zoomies-hero h1 br {
    display: none;
  }
  .md-typeset .zoomies-hero h1 .quiet {
    display: block;
    text-wrap: balance;
  }
  /* A fingertip covers about 44px. The two buttons were 38px tall and the chips
     under them 32px, which is where a thumb lands on a phone's first screen.
     Material sets the root size to 20px, so 2.2rem is the 44px. */
  .md-typeset .md-button,
  .md-typeset .zoomies-hero .popular a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.2rem;
  }
  /* The command wraps (above), so nothing needs the room the desktop rule keeps
     on its right for the copy chip. The chip moves below the text, where it can
     be a 44px target instead of a 24px one beside the characters. The room is in
     rem, not em: the command is set smaller than the page, and room measured in
     its own em shrank with it until the chip sat on the last word. */
  .md-typeset .zoomies-install pre > code {
    padding: 0.95em 1.1em 3.4rem;
  }
  .md-typeset .zoomies-install .md-code__nav {
    top: auto;
    bottom: 0.5rem;
    right: 0.5rem;
    transform: none;
  }
  .md-typeset .zoomies-install .md-code__button {
    width: 2.2rem;
    height: 2.2rem;
  }
  .zoomies-grid .wide {
    display: block;
  }
  .md-typeset .zoomies-grid .wide p:has(> .icon) {
    margin: 0 0 0.8rem;
  }
  .md-footer-meta__inner {
    grid-template-columns: 1fr;
    gap: 0.9rem;
  }
  .zoomies-cta {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    padding: 1.75rem 1rem;
    text-align: center;
  }
  .md-typeset .zoomies-cta .actions {
    justify-content: center;
  }
}

/* The drawer Material shows below 1220px. Its rows were 31 to 34px tall and sit
   a finger's width apart on the screen a thumb reaches first. */
@media screen and (max-width: 76.1875em) {
  .md-nav--primary .md-nav__link {
    align-items: center;
    min-height: 2.2rem;
  }
}

/* ------------------------------------------------------------------------ */
/* Screenshots.                                                              */
/* ------------------------------------------------------------------------ */

/* docs/screenshots/ is captured from the real product by `make screenshots`,
   in both themes, and a page shows whichever matches the reader's palette
   (Material's #only-dark / #only-light). The frame is the hairline and radius
   the product's own panels use, so a screenshot reads as a window onto it
   rather than a picture pasted in. No `display` here on purpose: Material
   hides the other theme's image with a rule of equal specificity, and setting
   display would win over it and show both. */
.md-typeset .zoomies-shot {
