// Delivery is at-least-once: a create whose result was lost is offered again
// once its lease expires. The backend's Create begins by removing a workload of
// the same name, so the redelivery used to destroy a runner that might be
// mid-job and rebuild it with a JIT configuration GitHub had already used.
func TestARedeliveredCreateReportsTheRunnerThatAlreadyExists(t *testing.T) {
	h := newHarness(t, 2)
	h.tr.tasks <- []Task{createTask("task-1", "runner-1")}
	first := h.nextResult()
	if !first.OK || first.Handle == "" {
		t.Fatalf("first create: %+v", first)
	}

	h.tr.tasks <- []Task{createTask("task-1-again", "runner-1")}
	again := h.nextResult()
	if !again.OK || again.TaskID != "task-1-again" || again.RunnerID != "runner-1" {
		t.Fatalf("redelivered create: %+v", again)
	}
	if again.Handle != first.Handle {
		t.Fatalf("the redelivery reported handle %q, want the existing %q", again.Handle, first.Handle)
	}
	if created, _, _ := h.be.counts(); created != 1 {
		t.Fatalf("Create called %d times, want the one that made the runner", created)
	}
}

// The controller sheds load by asking every agent it is holding to wait, so it
// asks them all in the same instant. Waiting exactly as long as it asked would
// bring the whole fleet back together and re-form the queue the backoff was
// spreading out, so the wait is jittered.
func TestAShedBackoffIsSpreadRatherThanWaitedExactly(t *testing.T) {
	const asked = 10 * time.Second
	batch := &TaskBatch{Backoff: asked}

	seen := map[time.Duration]bool{}
	for range 50 {
		got := pollWait(batch, 0)
		if got <= 0 || got > asked {
			t.Fatalf("wait of %s for a %s backoff: it should be shorter, and it should still be a wait", got, asked)
		}
		seen[got] = true
	}
	if len(seen) == 1 {
		t.Fatal("every agent asked to wait would return in the same instant, which is the queue the backoff exists to spread")
	}
}

// A backoff is the controller's answer, not a suggestion to weigh against the
// spin guard: an agent that found no work still waits for it.
func TestABackoffOutranksTheSpinGuard(t *testing.T) {
	if got := pollWait(&TaskBatch{Backoff: time.Second}, time.Hour); got < 500*time.Millisecond {
		t.Fatalf("wait = %s after a poll that took an hour, want most of the second the controller asked for", got)
	}
}

// A batch with work in it is dispatched and polled again straight away: the
// spin guard exists for an idle loop, and applying it to a busy one would put
// a floor under how fast a host can be given its next task.
func TestABatchWithWorkIsPolledAgainImmediately(t *testing.T) {
	batch := &TaskBatch{Tasks: []Task{{ID: "t1", Kind: TaskCreateRunner}}}
	if got := pollWait(batch, 0); got != 0 {
		t.Fatalf("wait = %s after a batch with work in it, want none", got)
	}
}

// An idle poll the controller answered instantly is held off, or the loop
// would spin at whatever rate it can dial.
func TestAnInstantIdlePollIsHeldOff(t *testing.T) {
	if got := pollWait(&TaskBatch{}, 0); got != minPollInterval {
		t.Fatalf("wait = %s after an instant empty poll, want the %s floor", got, minPollInterval)
	}
	if got := pollWait(&TaskBatch{}, minPollInterval); got != 0 {
		t.Fatalf("wait = %s after a poll that already took the floor, want none", got)
	}
}

// TestEveryPrewarmInABatchIsPulled covers a collision between tasks that have
// no runner between them.
//
// dispatch claims a task by its runner ID so that two lifecycle tasks for one
// runner cannot race on the host. A prewarm carries no runner, so every prewarm
// claimed the same empty key: the first took it and the rest returned at once,
// reporting nothing. Two Docker pools on one host is all it takes, and the loss
// is permanent rather than a retry away -- a task that reports no result stays
// outstanding on the controller, and enqueue refuses a key that is already in
// flight, so that pool is never prewarmed on that host again.
func TestEveryPrewarmInABatchIsPulled(t *testing.T) {
	h := newHarness(t, 2)

	h.tr.tasks <- []Task{
		{ID: "prewarm-a", Kind: TaskPrewarmImage, PoolID: "pool_a", Backend: h.be.Kind(), Image: "img-a", PullPolicy: store.PullIfNotPresent},
		{ID: "prewarm-b", Kind: TaskPrewarmImage, PoolID: "pool_b", Backend: h.be.Kind(), Image: "img-b", PullPolicy: store.PullIfNotPresent},
	}

	// Both have to report, or the controller's lease on the silent one never
	// clears.
	seen := map[string]bool{}
	for range 2 {
		res := h.nextResult()
		if !res.OK {
			t.Errorf("prewarm %s failed: %s", res.TaskID, res.Error)
		}
		seen[res.TaskID] = true
	}
	for _, id := range []string{"prewarm-a", "prewarm-b"} {
		if !seen[id] {
			t.Errorf("%s reported no result; the controller will wait on it for ever", id)
		}
	}

	pulls := h.be.pulls()
	slices.Sort(pulls)
	if !slices.Equal(pulls, []string{"img-a", "img-b"}) {
		t.Errorf("images pulled = %v, want both img-a and img-b", pulls)
	}
}

// A remove task that finds the daemon still removing the workload answers
// that it is pending rather than failed. The controller counted every such
// answer as a failed cleanup, and it re-sends a remove on every scheduling
// pass while a host's cleanup is outstanding, so one slow sidecar climbed
// through "attempts" while the daemon was finishing the job.
func TestARemoveTaskFindingTheDaemonStillRemovingAnswersPending(t *testing.T) {
	a, tr, be, clock := newAgent(t, 2)
	track(a, "runner-1", "wl-1", true)
	be.setWorkloads(exited("wl-1", "runner-1", 0))
	be.mu.Lock()
	be.removeErr = errStillRemoving
	be.mu.Unlock()
	ctx := context.Background()
	remove := func(id string) TaskResult {
		t.Helper()
		a.handleRemove(ctx, Task{ID: id, Kind: TaskRemoveRunner, RunnerID: "runner-1"}, func() {})
		select {
		case res := <-tr.results:
			return res
		default:
			t.Fatalf("task %s was not answered", id)
		}
		return TaskResult{}
	}

	res := remove("task-1")
	if res.OK || !res.CleanupPending || !strings.Contains(res.Error, "still removing") {
		t.Fatalf("a removal under way was not answered as pending: %+v", res)
	}
	if got := a.Runners(); len(got) != 1 {
		t.Fatalf("forgot a runner whose workload is still being removed: %+v", got)
	}

	// Past the bound it is stuck, and answered as the failure it has become.
	clock.advance(removalSettle)
	res = remove("task-2")
	if res.OK || res.CleanupPending || !strings.Contains(res.Error, "restart") {
		t.Fatalf("a removal stuck past its bound was still answered as pending: %+v", res)
	}

	be.mu.Lock()
	be.removeErr = nil
	be.mu.Unlock()
	res = remove("task-3")
	if !res.OK || res.CleanupPending || res.State != store.RunnerRemoved {
		t.Fatalf("the finished removal was not confirmed: %+v", res)
	}
}

// A remove task for a runner the agent no longer tracks still finds its
// sidecar, and a sidecar the daemon is still removing is pending there too --
// not a backend that "would not answer".
func TestARemoveTaskForAnUntrackedRunnerWaitsOutItsSidecar(t *testing.T) {
	a, tr, be, clock := newAgent(t, 2)
	be.setWorkloads(backend.Workload{Handle: "dind-1", RunnerID: "runner-1", Sidecar: true,
		Status: backend.Status{Handle: "dind-1", Phase: backend.PhaseRunning}})
	be.mu.Lock()
	be.removeErr = errStillRemoving
	be.mu.Unlock()
	remove := func(id string) TaskResult {
		t.Helper()
		a.handleRemove(context.Background(), Task{ID: id, Kind: TaskRemoveRunner, RunnerID: "runner-1"}, func() {})
		return <-tr.results
	}

	if res := remove("task-1"); !res.CleanupPending || strings.Contains(res.Error, "would not answer") {
		t.Fatalf("a sidecar still being removed = %+v, want pending", res)
	}
	clock.advance(removalSettle)
	res := remove("task-2")
	if res.OK || res.CleanupPending || !strings.Contains(res.Error, StuckRemoval) {
		t.Fatalf("a sidecar stuck past its bound = %+v, want the stuck failure", res)
	}
	// There is no workload handle to name, so none is printed.
	if strings.Contains(res.Error, "()") {
		t.Fatalf("the report names an empty handle: %s", res.Error)
	}
}

// A plain refusal is still a failure the controller must hear about at once.
func TestARemoveTaskThatFailsIsNotAnsweredAsPending(t *testing.T) {
	a, tr, be, _ := newAgent(t, 2)
	track(a, "runner-1", "wl-1", true)
	be.setWorkloads(exited("wl-1", "runner-1", 0))
	be.mu.Lock()
	be.removeErr = errors.New("sidecar is in use")
	be.mu.Unlock()

	a.handleRemove(context.Background(), Task{ID: "task-1", Kind: TaskRemoveRunner, RunnerID: "runner-1"}, func() {})
	res := <-tr.results
	if res.OK || res.CleanupPending || !strings.Contains(res.Error, "sidecar is in use") {
		t.Fatalf("a refused removal = %+v, want an ordinary failure", res)
	}
}

// An operator removing a runner while its create is still running must still
// get the runner removed.
//
// The two tasks arrive together -- the controller queues the remove the moment
// the row is deleted, which can be seconds after the create was issued -- and
// the claim that stops two creates racing used to drop the remove with them.
// Nothing then reported on it, so the container ran on the host until the
// task's lease expired minutes later, long after the runner had gone from the
// UI. The later task waits for the claim instead of being thrown away.
func TestARemoveArrivingDuringACreateRunsOnceTheCreateIsDone(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		a.dispatch(ctx, createTask("task-create", "runner-1"))
		synctest.Wait()
		startupEntered(t, b, "runner-1")
		// Deliver after the backend has begun, to distinguish cancellation
		// of active work from a create still waiting for its startup slot.
		a.dispatch(ctx, Task{ID: "task-remove", Kind: TaskRemoveRunner, RunnerID: "runner-1"})
		b.finish <- nil
		synctest.Wait()
		a.tasks.Wait()

		results := map[string]TaskResult{}
		for range 2 {
			res := <-tr.results
			results[res.TaskID] = res
		}
		if !results["task-create"].OK || !results["task-remove"].OK {
			t.Fatalf("lifecycle tasks failed: %+v", results)
		}
		if results["task-remove"].State != store.RunnerRemoved {
			t.Fatalf("remove did not confirm removal: %+v", results)
		}
		if _, _, removed := b.counts(); removed == 0 {
			t.Fatal("the runner's workload was left on the host")
		}
		if !a.claim("runner-1") {
			t.Fatal("runner-1 is still claimed after both tasks finished")
		}
		a.release("runner-1")
	})
}

// A duplicate of the task already running is still dropped. The controller
// redelivers what it has not seen a result for, and doing that work twice --
// two creates for one runner racing on the host -- is what the claim exists to
// prevent.
func TestADuplicateOfTheTaskInFlightIsStillDropped(t *testing.T) {
	a, _, _, _ := newAgent(t, 1)
	first := createTask("task-1", "runner-1")
	if claimed, held := a.claimOrQueue(first); !claimed || held {
		t.Fatalf("first create: claimed=%v held=%v, want claimed", claimed, held)
	}
	if claimed, held := a.claimOrQueue(createTask("task-2", "runner-1")); claimed || held {
		t.Fatalf("duplicate create: claimed=%v held=%v, want dropped", claimed, held)
	}

	// A remove supersedes it, and a second remove behind that one does not.
	remove := Task{ID: "task-3", Kind: TaskRemoveRunner, RunnerID: "runner-1"}
	if claimed, held := a.claimOrQueue(remove); claimed || !held {
		t.Fatalf("remove during a create: claimed=%v held=%v, want held", claimed, held)
	}
	if claimed, held := a.claimOrQueue(Task{ID: "task-4", Kind: TaskRemoveRunner, RunnerID: "runner-1"}); claimed || held {
		t.Fatalf("second remove: claimed=%v held=%v, want dropped", claimed, held)
	}
}

// Only one task waits, so when two supersede the create in flight it is the
// later of them that stays: a remove does everything the stop it replaces
// would have, and the controller redelivers the stop if it still wants it.
func TestTheLaterOfTwoWaitingTasksIsTheOneKept(t *testing.T) {
	a, _, _, _ := newAgent(t, 1)
	if claimed, _ := a.claimOrQueue(createTask("task-1", "runner-1")); !claimed {
		t.Fatal("the create did not take the claim")
	}
	if claimed, held := a.claimOrQueue(Task{ID: "task-2", Kind: TaskStopRunner, RunnerID: "runner-1"}); claimed || !held {
		t.Fatalf("stop during a create: claimed=%v held=%v, want held", claimed, held)
	}
	if claimed, held := a.claimOrQueue(Task{ID: "task-3", Kind: TaskRemoveRunner, RunnerID: "runner-1"}); claimed || !held {
		t.Fatalf("remove behind the waiting stop: claimed=%v held=%v, want held", claimed, held)
	}

	a.mu.Lock()
	waiting := a.waiting["runner-1"]
	a.mu.Unlock()
	if waiting.ID != "task-3" {
		t.Fatalf("the task waiting is %q, want the remove that supersedes the stop", waiting.ID)
	}

	// A log relay is not lifecycle work and ranks below all of them, so it is
	// never what a runner's claim is handed to.
	if claimed, held := a.claimOrQueue(Task{ID: "task-4", Kind: TaskStreamLogs, RunnerID: "runner-1", StreamID: "str_1"}); claimed || held {
		t.Fatalf("stream during a create: claimed=%v held=%v, want dropped", claimed, held)
	}
}

// A task that never got a capacity slot before the agent shut down is
// reported as such rather than dropped. Silence is the one outcome the
// controller cannot act on: it would hold the task in flight until its lease
// expired, where this answer has it redelivered to the next host that polls.
func TestATaskShutDownBeforeItStartedIsReportedAsRedeliverable(t *testing.T) {
	h := newHarness(t, 1)
	h.be.mu.Lock()
	h.be.createDelay = 3 * time.Second
	h.be.mu.Unlock()

	// The first create takes the host's only slot and holds it, so the second
	// is still waiting for one when the agent is asked to stop.
	h.tr.tasks <- []Task{createTask("task-slow", "runner-1")}
	waitFn(t, "the first create to take the host's only slot", 5*time.Second, func() bool {
		h.be.mu.Lock()
		defer h.be.mu.Unlock()
		return h.be.inflight == 1
	})
	h.tr.tasks <- []Task{createTask("task-waiting", "runner-2")}
	time.Sleep(200 * time.Millisecond)
	go h.stop()

	deadline := time.After(10 * time.Second)
	for {
		select {
		case res := <-h.tr.results:
			if res.TaskID != "task-waiting" {
				continue
			}
			if res.OK || !res.NotStarted || !strings.Contains(res.Error, "safe to redeliver") {
				t.Fatalf("result = %+v, want the waiting task reported as redeliverable", res)
			}
			// A failed state would have the controller fail a runner nothing
			// happened to, which is what every upgrade used to do.
			if res.State != "" {
				t.Fatalf("state = %q, want none: the runner was never touched", res.State)
			}
			return
		case <-deadline:
			t.Fatal("the task that never started was never reported")
		}
	}
}

// A claim released by an agent whose task loop is not running still hands the
// task waiting behind it on. The handover carries a context of its own rather
// than checking for a missing one, which is why this is the case that proves
// it: the agent here has never started, so there is no poll loop to borrow
// from, and a nil context would panic the goroutine the release starts.
func TestAHandoverWorksBeforeTheTaskLoopIsRunning(t *testing.T) {
	a, tr, _, _ := newAgent(t, 1)
	if err := a.Join(context.Background(), "join-token"); err != nil {
		t.Fatalf("Join: %v", err)
	}
	if claimed, _ := a.claimOrQueue(createTask("task-1", "runner-1")); !claimed {
		t.Fatal("the create did not take the claim")
	}
	remove := Task{ID: "task-2", Kind: TaskRemoveRunner, RunnerID: "runner-1"}
	if _, held := a.claimOrQueue(remove); !held {
		t.Fatal("the remove was not held behind the create")
	}

	a.release("runner-1")

	select {
	case res := <-tr.results:
		if res.TaskID != "task-2" || !res.OK {
			t.Fatalf("result = %+v, want the waiting remove reported", res)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the task waiting on the claim was never started")
	}
}

// The reconciler's claim is not one anything can queue behind: it hands the
// claim to nobody, so a task left waiting on it would never start. Those are
// dropped, and the controller's redelivery is what brings them back.
func TestATaskArrivingDuringReconcilerWorkIsDroppedRatherThanHeld(t *testing.T) {
	a, _, _, _ := newAgent(t, 1)
	if !a.claim("runner-1") {
		t.Fatal("could not take the reconciler's claim")
	}
	if claimed, held := a.claimOrQueue(Task{ID: "task-1", Kind: TaskRemoveRunner, RunnerID: "runner-1"}); claimed || held {
		t.Fatalf("remove during reconciler work: claimed=%v held=%v, want dropped", claimed, held)
	}
	a.release("runner-1")
}

// Model an upgrade while Docker is between sidecar creation and runner start.
// The old 30-second grace let Run return before the create result existed.
func TestShutdownFinishesAdmittedCreateAndKeepsReporting(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		if err := a.Join(context.Background(), "join-token"); err != nil {
			t.Fatal(err)
		}
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		done := make(chan error, 1)
		go func() { done <- a.Run(ctx) }()
		tr.tasks <- []Task{createTask("create", "runner-1")}
		synctest.Wait()
		startupEntered(t, b, "runner-1")
		cancel()
		synctest.Wait()
		for len(tr.beats) > 0 {
			<-tr.beats
		}
		time.Sleep(time.Minute)
		synctest.Wait()
		select {
		case err := <-done:
			t.Fatalf("agent exited with an unfinished create: %v", err)
		default:
		}
		if len(tr.beats) == 0 {
			t.Fatal("agent stopped reporting while its admitted create was running")
		}
		b.finish <- nil
		synctest.Wait()
		if err := <-done; err != nil {
			t.Fatal(err)
		}
		select {
		case res := <-tr.results:
			if !res.OK || res.Handle == "" {
				t.Fatalf("create was not completed and reported: %+v", res)
			}
		default:
			t.Fatal("agent exited before reporting its create result")
		}
		if created, stopped, removed := b.counts(); created != 1 || stopped != 0 || removed != 0 {
			t.Fatalf("upgrade changed workloads: create=%d stop=%d remove=%d", created, stopped, removed)
		}
	})
}

func TestShutdownTaskWaitRemainsBounded(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, _, _, _ := newAgent(t, 1)
		a.tasks.Add(1)
		start := time.Now()
		if a.waitForTasks(context.Background(), time.Minute) {
			t.Fatal("unfinished work reported complete")
		}
		a.tasks.Done()
		synctest.Wait()
		if elapsed := time.Since(start); elapsed != time.Minute {
			t.Fatalf("wait took %s, want one minute", elapsed)
		}
	})
}

package agent

import "math"

// diskFromStatfs turns a filesystem's raw block counts into bytes, and refuses
// figures that cannot describe one.
//
// Separate from the syscall so that it can be tested at all: the values that
// break it -- a block count wide enough to overflow a signed 64-bit multiply,
// an available count above the total -- cannot be staged on a real filesystem,
// and every check here would otherwise be a line nothing could ever fail.
//
// The counts arrive unsigned because that is what every platform's statfs uses,
// and the danger is exactly there: converted straight to int64 a large enough
// value arrives as a negative, and a negative number of bytes free would pass
// every "was this measured" test downstream and read as a host with room.
func diskFromStatfs(blocks, bavail uint64, bsize int64) (total, avail int64, ok bool) {
	if bsize <= 0 {
		return 0, 0, false
	}
	if blocks > math.MaxInt64/uint64(bsize) || bavail > math.MaxInt64/uint64(bsize) {
		return 0, 0, false
	}
	total, avail = int64(blocks)*bsize, int64(bavail)*bsize
	if total <= 0 || avail < 0 || avail > total {
		return 0, 0, false
	}
	return total, avail, true
}

//go:build !(linux || darwin || windows)

package agent

// diskSpace has no portable answer away from the platforms Zoomies ships for.
// A host that cannot measure its own disk reports none, which the controller
// reads as "unknown" rather than as "empty" -- the difference between placing
// nothing there and placing everything there.
func diskSpace(string) (total, avail int64, ok bool) { return 0, 0, false }

package agent

import (
	"context"
	"math"
	"os"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/machine"
	"github.com/eyupio/zoomies/internal/store"
)

// The work directory is where a runner's checkout and its caches land, so it
// is that filesystem that decides whether a job has anywhere to go -- not the
// root one, and not the one the agent's binary happens to sit on.
//
// The figures are asserted against the bytes they are converted from rather
// than for being plausible. "Positive, and free no larger than total" holds
// whatever the unit is, so it would have passed just as well on raw bytes --
// and the columns these land in are called disk_total_mb and disk_free_mb, the
// controller's write-suppression floor is denominated in MB, and a 1,048,576x
// slip would read a 250 GB volume as 250 PB.
func TestTheAgentMeasuresTheDiskItsRunnersWillUse(t *testing.T) {
	dir := t.TempDir()
	rawTotal, rawAvail, ok := diskSpace(dir)
	if !ok {
		t.Skip("this platform has no portable way to measure a filesystem")
	}
	a := &Agent{opts: Options{WorkDir: dir}}

	total, free := a.workDirSpace()

	const mb = 1 << 20
	if total != rawTotal/mb {
		t.Errorf("total = %d, want %d: the figure is reported in MB, not bytes", total, rawTotal/mb)
	}
	// Free space moves under us -- anything else on this machine may write
	// between the two measurements -- so it is checked for being the same
	// quantity rather than the same number. A unit slip is six orders of
	// magnitude and nowhere near this tolerance.
	if delta := free - rawAvail/mb; delta > 64 || delta < -64 {
		t.Errorf("free = %d MB, want about %d MB", free, rawAvail/mb)
	}
	if free <= 0 || free > total {
		t.Errorf("free = %d MB of %d MB total, which is not a filesystem", free, total)
	}
}

// And it is that filesystem, not whichever one the process happens to be
// standing on. A work directory is very often a dedicated data volume -- it is
// the reason the setting exists -- so measuring the root filesystem instead
// would report a number that has nothing to do with where the jobs will run.
func TestTheAgentMeasuresTheWorkDirectorysOwnFilesystem(t *testing.T) {
	// A second mount to tell the two apart. /dev/shm is a tmpfs on Linux and
	// is sized quite differently from the root filesystem, which is what makes
	// it usable as the distinguishing one.
	const other = "/dev/shm"
	if _, err := os.Stat(other); err != nil {
		t.Skip("no second filesystem to distinguish the work directory from")
	}
	elsewhere, _, ok := diskSpace(other)
	if !ok {
		t.Skip("this platform has no portable way to measure a filesystem")
	}
	root, _, ok := diskSpace(string(os.PathSeparator))
	if !ok || root == elsewhere {
		t.Skip("the two candidate paths are the same filesystem, so this proves nothing")
	}

	dir, err := os.MkdirTemp(other, "zoomies-workdir-")
	if err != nil {
		t.Skipf("cannot create a directory on %s: %v", other, err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })

	a := &Agent{opts: Options{WorkDir: dir}}
	total, _ := a.workDirSpace()

	const mb = 1 << 20
	if total != elsewhere/mb {
		t.Errorf("total = %d MB, want %s's %d MB rather than the root filesystem's %d MB",
			total, other, elsewhere/mb, root/mb)
	}
}

// A directory that is not there yet cannot be measured, and saying "zero" for
// it would read as a full disk. Nothing is the honest answer, and the
// controller keeps whatever it already knew.
func TestAWorkDirectoryThatIsNotThereMeasuresNothing(t *testing.T) {
	missing := t.TempDir() + string(os.PathSeparator) + "not-created-yet"
	a := &Agent{opts: Options{WorkDir: missing}}

	if total, free := a.workDirSpace(); total != 0 || free != 0 {
		t.Fatalf("measured %d MB total and %d MB free of a directory that does not exist", total, free)
	}
	// Asserted at the measurement too, not only after the conversion to
	// megabytes: a wrong answer smaller than a megabyte rounds to the same
	// zero as no answer, so the megabyte figures alone cannot tell them apart.
	if total, avail, ok := diskSpace(missing); ok {
		t.Fatalf("diskSpace reported %d/%d bytes for a directory that does not exist", avail, total)
	}
}

// A runner started through Docker or Podman is a sibling on the host, outside
// whatever cgroup the agent is held to. A containerised controller -- the usual
// deployment -- would otherwise describe a sixty-four core host as the two cores
// its own container may use, and the fleet would be placed at a fraction of its
// real size.
func TestAHostIsSizedByTheDaemonThatWillRunTheRunners(t *testing.T) {
	self := machine.Facts{CPUs: 2, MemoryMB: 2048}
	infos := []backend.Info{
		{Kind: store.BackendDocker, Available: true, CPUs: 64, MemoryMB: 262_144},
	}

	cpus, memoryMB := hostSize(infos, self)

	if cpus != 64 || memoryMB != 262_144 {
		t.Fatalf("host = %d cpus, %d MB; want the daemon's view of the machine", cpus, memoryMB)
	}
}

// Where no daemon answers, the agent's own view is the honest one: a runner the
// process backend starts is a child of the agent and is held to the same cgroup.
func TestAHostWithNoDaemonIsSizedByWhatTheAgentMayUse(t *testing.T) {
	self := machine.Facts{CPUs: 2, MemoryMB: 2048}

	for _, name := range []string{"no backends at all", "a backend that is not there"} {
		t.Run(name, func(t *testing.T) {
			var infos []backend.Info
			if name != "no backends at all" {
				// Unavailable, and reporting a machine anyway: a stale probe
				// must not size a host the agent cannot place anything on.
				infos = []backend.Info{
					{Kind: store.BackendDocker, Available: false, CPUs: 64, MemoryMB: 262_144},
				}
			}
			cpus, memoryMB := hostSize(infos, self)
			if cpus != 2 || memoryMB != 2048 {
				t.Fatalf("host = %d cpus, %d MB; want the agent's own view", cpus, memoryMB)
			}
		})
	}
}

// A daemon on a smaller machine than the agent's sizes the host, because the
// runners run there: Docker Desktop's VM on a ten-core laptop has four cores,
// and a CPU share sized from the laptop is a quota the VM's daemon refuses.
func TestADaemonOnASmallerMachineSizesTheHost(t *testing.T) {
	self := machine.Facts{CPUs: 10, MemoryMB: 32_768}
	infos := []backend.Info{{Kind: store.BackendDocker, Available: true, CPUs: 4, MemoryMB: 8192}}

	cpus, memoryMB := hostSize(infos, self)

	if cpus != 4 || memoryMB != 8192 {
		t.Fatalf("host = %d cpus, %d MB; want the daemon's smaller machine", cpus, memoryMB)
	}
}

// A daemon that says nothing about its machine -- an older one, or a backend
// that is not a container runtime -- leaves the agent's own view standing
// rather than zeroing the host.
func TestADaemonThatSaysNothingDoesNotShrinkTheHost(t *testing.T) {
	self := machine.Facts{CPUs: 8, MemoryMB: 16_384}
	infos := []backend.Info{{Kind: store.BackendDocker, Available: true}}

	cpus, memoryMB := hostSize(infos, self)

	if cpus != 8 || memoryMB != 16_384 {
		t.Fatalf("host = %d cpus, %d MB; a silent daemon must not shrink it", cpus, memoryMB)
	}
}

// The arithmetic on its own, because the figures that break it cannot be
// staged on a real filesystem: a block count wide enough to overflow a signed
// multiply, or an available count above the total. Without this every check in
// diskFromStatfs would be a line nothing could ever fail.
func TestWhatCannotBeAFilesystemIsRefused(t *testing.T) {
	const tb = 1 << 40
	tests := []struct {
		name           string
		blocks, bavail uint64
		bsize          int64
		total, avail   int64
		ok             bool
	}{
		{"an ordinary disk", 66_053_021, 5_419_506, 4096, 270_553_174_016, 22_198_296_576, true},
		{"a full disk", 1000, 0, 4096, 4_096_000, 0, true},
		{"no block size at all", 1000, 500, 0, 0, 0, false},
		{"a negative block size", 1000, 500, -4096, 0, 0, false},
		{"a block count that overflows the multiply", math.MaxUint64, 1, 4096, 0, 0, false},
		// The one that matters: this wraps to 4096 bytes, which passes every
		// check on the result. A four-petabyte volume would be reported as a
		// four-kilobyte one and every host on it declared out of room.
		{"an overflow that wraps to a plausible size", (1 << 52) + 1, 1, 4096, 0, 0, false},
		{"an available count that overflows the multiply", 1000, math.MaxUint64, 4096, 0, 0, false},
		{"more available than exists", 100, 200, 4096, 0, 0, false},
		{"a filesystem of no size", 0, 0, 4096, 0, 0, false},
		{"a large but honest disk", tb, tb / 2, 1, tb, tb / 2, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			total, avail, ok := diskFromStatfs(tc.blocks, tc.bavail, tc.bsize)
			if ok != tc.ok || total != tc.total || avail != tc.avail {
				t.Fatalf("diskFromStatfs(%d, %d, %d) = %d, %d, %v; want %d, %d, %v",
					tc.blocks, tc.bavail, tc.bsize, total, avail, ok, tc.total, tc.avail, tc.ok)
			}
		})
	}
}

// TestTheAgentReportsTheHostItCanActuallyFill is the wiring between measuring a
// host and telling the controller about it.
//
// hostSize and workDirSpace were each tested as functions, and both requests
// were built by hand in every other test, so nothing connected the two: the two
// lines that put the figures on the wire could be deleted and the whole suite
// stayed green. A containerised agent would then go back to reporting its
// two-core cgroup share for a sixty-four-core host, and the fleet would be
// placed at a fraction of its size.
func TestTheAgentReportsTheHostItCanActuallyFill(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend(store.BackendDocker)
	// The agent is in a small container; the daemon it drives is on the real
	// machine. A Docker runner is a sibling on that machine rather than a
	// child in this cgroup, so the daemon's figures are the ones that decide
	// what can be placed here.
	be.cpus, be.memoryMB = 64, 262_144
	workDir := t.TempDir()

	a, err := New(Options{
		Name:              "vm-1",
		WorkDir:           workDir,
		Capacity:          2,
		Backends:          backend.NewRegistry(be),
		DefaultBackend:    store.BackendDocker,
		Transport:         tr,
		HeartbeatInterval: time.Second,
		Logger:            testLogger(),
		Machine:           &machine.Facts{OS: "linux", Arch: "amd64", CPUs: 2, MemoryMB: 2048},
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	if err := a.Join(context.Background(), "join-token"); err != nil {
		t.Fatalf("Join: %v", err)
	}
	if tr.joinReq == nil {
		t.Fatal("the agent sent no join request")
	}
	if tr.joinReq.CPUs != 64 || tr.joinReq.MemoryMB != 262_144 {
		t.Errorf("join reported %d CPUs and %d MB; the agent sent its own cgroup share rather than the host",
			tr.joinReq.CPUs, tr.joinReq.MemoryMB)
	}

	wantTotal, wantFree := a.workDirSpace()
	if wantTotal == 0 {
		t.Skip("this platform has no portable way to measure a filesystem")
	}
	if tr.joinReq.DiskTotalMB != wantTotal {
		t.Errorf("join reported %d MB of disk, want the work directory's %d MB",
			tr.joinReq.DiskTotalMB, wantTotal)
	}
	if tr.joinReq.DiskFreeMB == 0 {
		t.Errorf("join reported no free disk, though %d MB was measurable", wantFree)
	}

	// And every beat carries it too, or a host that grew -- or a disk that
	// filled -- would be believed at its joining size until it re-joined.
	if err := a.heartbeat(context.Background()); err != nil {
		t.Fatalf("heartbeat: %v", err)
	}
	select {
	case beat := <-tr.beats:
		if beat.CPUs != 64 || beat.MemoryMB != 262_144 {
			t.Errorf("the beat reported %d CPUs and %d MB; the agent sent its own cgroup share rather than the host",
				beat.CPUs, beat.MemoryMB)
		}
		if beat.DiskTotalMB != wantTotal {
			t.Errorf("the beat reported %d MB of disk, want the work directory's %d MB",
				beat.DiskTotalMB, wantTotal)
		}
		if beat.DiskFreeMB == 0 {
			t.Error("the beat reported no free disk, so a filling disk would never be noticed")
		}
	case <-time.After(time.Second):
		t.Fatal("no heartbeat was sent")
	}
}

//go:build linux || darwin

package agent

import "syscall"

// diskSpace reports the total and available bytes on the filesystem holding
// path, and whether the question could be answered at all.
//
// Available rather than free: the two differ by the reserve a filesystem keeps
// for root, and a runner is not root. Reporting the larger number would let the
// controller place work into space the job cannot actually write to.
//
// The build tag names the two platforms Zoomies ships for rather than `unix`,
// because `unix` is a promise this file cannot keep: syscall.Statfs does not
// exist on NetBSD, which has Statvfs1, nor on Solaris and illumos, which have
// Statvfs. A tag that covers them would not compile there, and a build failure
// is a worse answer than the honest "cannot measure" the other file gives.
//
// f_bsize rather than f_frsize, which is the unit POSIX defines f_blocks in:
// Darwin's Statfs_t has no Frsize field at all, and on every filesystem this
// will meet the two are equal. Where they are not, the figure is wrong by the
// ratio between them -- worth knowing, not worth a per-platform file for a
// number used at megabyte granularity to choose a host.
func diskSpace(path string) (total, avail int64, ok bool) {
	var st syscall.Statfs_t
	if err := syscall.Statfs(path, &st); err != nil {
		return 0, 0, false
	}
	// Bsize is signed on some platforms and unsigned on others, so it goes
	// through int64 before it multiplies anything; the counts are unsigned
	// everywhere. What the numbers mean, and which of them cannot be a
	// filesystem, is diskFromStatfs's business.
	return diskFromStatfs(uint64(st.Blocks), uint64(st.Bavail), int64(st.Bsize))
}

//go:build linux || darwin

package agent

import (
	"syscall"
	"testing"
)

// TestTheAgentReportsSpaceARunnerCanActuallyWriteTo is the distinction
// diskSpace exists to make, and the one thing about it a comment cannot keep
// true: f_bavail rather than f_bfree.
//
// The two differ by the reserve the filesystem keeps for root, and a runner is
// deliberately not root. Reporting the larger number would have the controller
// place work into space the job cannot write to -- a build that fills the disk
// and fails at the end, on a host the fleet thought had room.
//
// Swapping one identifier for the other is a one-token change that reads as a
// tidy-up, so it needs a test rather than the comment above it.
//
// Which field, not which byte. diskSpace makes its own Statfs call, so this
// compares two readings of a live filesystem taken moments apart -- and
// anything writing to it in between moves f_bavail by a block. Demanding they
// match exactly made this fail on a busy machine for a reason that has nothing
// to do with what it is testing: CI reported a difference of 4096 bytes, which
// is one block, on a runner that was writing test databases throughout.
//
// The reserve the two fields differ by is a percentage of the filesystem --
// gigabytes where the drift is kilobytes -- so "nearer f_bavail than f_bfree"
// separates them with room to spare, and says exactly what the comment above
// promises.
func TestTheAgentReportsSpaceARunnerCanActuallyWriteTo(t *testing.T) {
	dir := t.TempDir()
	var st syscall.Statfs_t
	if err := syscall.Statfs(dir, &st); err != nil {
		t.Skipf("this platform cannot measure a filesystem here: %v", err)
	}
	if st.Bfree == st.Bavail {
		t.Skip("this filesystem keeps no reserve, so free and available are the same number")
	}

	_, avail, ok := diskSpace(dir)
	if !ok {
		t.Fatal("diskSpace could not measure a directory that exists")
	}

	bsize := int64(st.Bsize)
	wantAvail, wantFree := int64(st.Bavail)*bsize, int64(st.Bfree)*bsize
	if avail == wantFree {
		t.Fatalf("available = %d bytes, which is f_bfree: %d of that is reserved and a runner cannot write to it",
			avail, wantFree-wantAvail)
	}
	// Half the reserve as the tolerance: wide enough that a filesystem moving
	// under the two calls cannot fail this, and narrower than the distance to
	// the number it must not be.
	reserve := wantFree - wantAvail
	if drift := avail - wantAvail; drift < -reserve/2 || drift > reserve/2 {
		t.Fatalf("available = %d bytes, want f_bavail's %d (out by %d, and the reserve is only %d)",
			avail, wantAvail, drift, reserve)
	}
}

//go:build windows

package agent

import "golang.org/x/sys/windows"

// diskSpace reports the total and available bytes on the volume holding path.
//
// The first figure GetDiskFreeSpaceEx returns is the space available to the
// calling user, after quotas, which is the Windows spelling of the reserve
// disk_unix.go explains: what a runner can actually write, not what the
// volume has free.
func diskSpace(path string) (total, avail int64, ok bool) {
	p, err := windows.UTF16PtrFromString(path)
	if err != nil {
		return 0, 0, false
	}
	var availToCaller, totalBytes, totalFree uint64
	if err := windows.GetDiskFreeSpaceEx(p, &availToCaller, &totalBytes, &totalFree); err != nil {
		return 0, 0, false
	}
	return int64(totalBytes), int64(availToCaller), true
}

package agent

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// fakeBackend is a Backend that never touches a container runtime, so the whole
// agent can be exercised on a machine with no Docker daemon.
type fakeBackend struct {
	kind store.BackendKind

	mu          sync.Mutex
	nextHandle  int
	created     []backend.Spec
	stopped     []backend.Handle
	removed     []backend.Handle
	workloads   []backend.Workload
	createErr   error
	createDelay time.Duration
	// createFailTimes, when positive, makes only the next N calls to Create
	// return createErr; the (N+1)th and later calls succeed. Zero, the
	// default, keeps createErr failing every call, as it always did.
	createFailTimes int
	removeErr       error
	listErr         error
	// listErrAfter is how many listings fail before the daemon answers
	// again; zero means listErr holds for good.
	listErrAfter int
	listings     int
	stats        backend.Stats
	logs         func() io.ReadCloser
	inflight     int
	maxInflight  int
	// unavailable makes Probe answer as a daemon that is not there, which is
	// what a host looks like before its Docker is up. probes counts how often
	// the agent has asked.
	unavailable bool
	probes      int
	// cpus and memoryMB are the machine the daemon says it is running on,
	// which on a containerised agent is larger than the agent's own share.
	cpus     int
	memoryMB int64
	// prewarmed records every image this backend was asked to pull, in order,
	// so a test can prove a batch of prewarms all arrived rather than only the
	// first.
	prewarmed []string
	// updates records every UpdateResources call, in order, and updateErr
	// makes each one fail the way a daemon without the endpoint would.
	updates   []resourceUpdate
	updateErr error
	// updateGate holds UpdateResources open, and updateEntered says when a
	// caller has arrived in it. Both nil unless a test is deliberately racing
	// two callers over one runner.
	updateGate    chan struct{}
	updateEntered chan struct{}
}

// resourceUpdate is one UpdateResources call the fake backend received.
type resourceUpdate struct {
	handle backend.Handle
	res    store.Resources
}

func newFakeBackend(kind store.BackendKind) *fakeBackend {
	return &fakeBackend{kind: kind}
}

func (f *fakeBackend) Kind() store.BackendKind { return f.kind }

// PrewarmImage makes this backend a backend.ImagePrewarmer, which is what
// handlePrewarm requires of one.
func (f *fakeBackend) PrewarmImage(_ context.Context, image string, _ store.PullPolicy) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.prewarmed = append(f.prewarmed, image)
	return "sha256:" + image, nil
}

// pulls returns the images prewarmed so far.
func (f *fakeBackend) pulls() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]string(nil), f.prewarmed...)
}

func (f *fakeBackend) Probe(context.Context) backend.Info {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.probes++
	if f.unavailable {
		return backend.Info{
			Kind:   f.kind,
			Detail: "cannot connect to the daemon: no such file or directory",
		}
	}
	return backend.Info{Kind: f.kind, Available: true, Version: "fake", Endpoint: "memory",
		CPUs: f.cpus, MemoryMB: f.memoryMB}
}

// setUnavailable flips what the next probe will find.
func (f *fakeBackend) setUnavailable(v bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.unavailable = v
}

func (f *fakeBackend) probeCount() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.probes
}

func (f *fakeBackend) Create(ctx context.Context, spec backend.Spec) (backend.Handle, error) {
	f.mu.Lock()
	f.inflight++
	if f.inflight > f.maxInflight {
		f.maxInflight = f.inflight
	}
	f.created = append(f.created, spec)
	f.nextHandle++
	handle := backend.Handle(fmt.Sprintf("wl-%d", f.nextHandle))
	delay, err := f.createDelay, f.createErr
	if err != nil && f.createFailTimes > 0 {
		f.createFailTimes--
		if f.createFailTimes == 0 {
			f.createErr = nil
		}
	}
	f.mu.Unlock()

	if delay > 0 {
		select {
		case <-time.After(delay):
		case <-ctx.Done():
		}
	}

	f.mu.Lock()
	f.inflight--
	if err == nil {
		f.workloads = append(f.workloads, backend.Workload{
			Handle:    handle,
			Name:      spec.Name,
			RunnerID:  spec.RunnerID,
			PoolID:    spec.PoolID,
			Status:    backend.Status{Handle: handle, Phase: backend.PhaseRunning},
			Resources: spec.Resources,
		})
	}
	f.mu.Unlock()

	if err != nil {
		return "", err
	}
	return handle, nil
}

func (f *fakeBackend) CreateWithResult(ctx context.Context, spec backend.Spec) (backend.CreateResult, error) {
	h, err := f.Create(ctx, spec)
	return backend.CreateResult{Handle: h, Digest: "sha256:resolved"}, err
}

func (f *fakeBackend) Status(_ context.Context, h backend.Handle) (backend.Status, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, w := range f.workloads {
		if w.Handle == h {
			return w.Status, nil
		}
	}
	return backend.Status{}, backend.ErrNotFound
}

func (f *fakeBackend) Stats(context.Context, backend.Handle) (backend.Stats, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.stats, nil
}

func (f *fakeBackend) Logs(context.Context, backend.Handle, backend.LogOptions) (io.ReadCloser, error) {
	f.mu.Lock()
	fn := f.logs
	f.mu.Unlock()
	if fn == nil {
		return io.NopCloser(bytes.NewReader(nil)), nil
	}
	return fn(), nil
}

func (f *fakeBackend) Stop(_ context.Context, h backend.Handle, _ time.Duration) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.stopped = append(f.stopped, h)
	return nil
}

func (f *fakeBackend) Remove(_ context.Context, h backend.Handle) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.removeErr != nil {
		return f.removeErr
	}
	f.removed = append(f.removed, h)
	f.workloads = slicesDelete(f.workloads, h)
	return nil
}

// UpdateResources makes this backend a backend.ResourceUpdater, which is what
// a throttle needs of one. It records the call and touches nothing.
func (f *fakeBackend) UpdateResources(_ context.Context, h backend.Handle, res store.Resources) error {
	f.mu.Lock()
	gate, entered := f.updateGate, f.updateEntered
	f.mu.Unlock()
	// Held open so a test can run a second caller while this one is inside the
	// daemon call, which is the window the throttle's in-flight marker exists
	// to close. Nil in every other test, where this is an ordinary call.
	if gate != nil {
		if entered != nil {
			entered <- struct{}{}
		}
		<-gate
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if f.updateErr != nil {
		return f.updateErr
	}
	f.updates = append(f.updates, resourceUpdate{handle: h, res: res})
	return nil
}

// resourceUpdates returns every UpdateResources call so far.
func (f *fakeBackend) resourceUpdates() []resourceUpdate {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]resourceUpdate(nil), f.updates...)
}

func (f *fakeBackend) List(context.Context) ([]backend.Workload, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.listings++
	if f.listErr != nil && (f.listErrAfter == 0 || f.listings <= f.listErrAfter) {
		return nil, f.listErr
	}
	out := make([]backend.Workload, len(f.workloads))
	copy(out, f.workloads)
	return out, nil
}

func slicesDelete(ws []backend.Workload, h backend.Handle) []backend.Workload {
	out := ws[:0]
	for _, w := range ws {
		if w.Handle != h {
			out = append(out, w)
		}
	}
	return out
}

func (f *fakeBackend) setWorkloads(ws ...backend.Workload) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.workloads = ws
}

func (f *fakeBackend) counts() (created, stopped, removed int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.created), len(f.stopped), len(f.removed)
}

func (f *fakeBackend) peakConcurrency() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.maxInflight
}

// fakeTransport stands in for the controller. Task batches are pushed onto
// tasks; everything the agent sends back lands on a buffered channel the test
// reads.
type fakeTransport struct {
	tasks   chan []Task
	results chan TaskResult
	reports chan []RunnerReport
	beats   chan HeartbeatRequest

	mu        sync.Mutex
	hostID    string
	token     string
	joinReq   *JoinRequest
	joinResp  *JoinResponse
	joinErr   error
	beatResp  *HeartbeatResponse
	beatErr   error
	reportErr error
	pollErr   error
	streams   map[string]*fakeStream
	openErr   error
	writeHold time.Duration
	polls     int
	// onResult stands in for a controller that acts on a result the instant it
	// arrives, which is the only way to observe what the agent's state looks
	// like at the moment it publishes one.
	onResult func(TaskResult)
}

func newFakeTransport() *fakeTransport {
	return &fakeTransport{
		tasks:    make(chan []Task, 8),
		results:  make(chan TaskResult, 64),
		reports:  make(chan []RunnerReport, 64),
		beats:    make(chan HeartbeatRequest, 64),
		joinResp: &JoinResponse{HostID: "host-1", AgentToken: "agent-token", ControllerVersion: "test"},
		beatResp: &HeartbeatResponse{OK: true},
		streams:  make(map[string]*fakeStream),
	}
}

func (f *fakeTransport) Join(_ context.Context, req JoinRequest) (*JoinResponse, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.joinReq = &req
	if f.joinErr != nil {
		return nil, f.joinErr
	}
	return f.joinResp, nil
}

func (f *fakeTransport) Heartbeat(_ context.Context, req HeartbeatRequest) (*HeartbeatResponse, error) {
	select {
	case f.beats <- req:
	default:
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.beatErr != nil {
		return nil, f.beatErr
	}
	return f.beatResp, nil
}

func (f *fakeTransport) PollTasks(ctx context.Context, wait time.Duration) (*TaskBatch, error) {
	f.mu.Lock()
	f.polls++
	err := f.pollErr
	f.mu.Unlock()
	if err != nil {
		return nil, err
	}
	select {
	case batch := <-f.tasks:
		return &TaskBatch{Tasks: batch}, nil
	case <-time.After(wait):
		return &TaskBatch{}, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

func (f *fakeTransport) ReportResult(_ context.Context, res TaskResult) error {
	f.mu.Lock()
	hook := f.onResult
	f.mu.Unlock()
	if hook != nil {
		hook(res)
	}
	select {
	case f.results <- res:
	default:
	}
	return nil
}

func (f *fakeTransport) ReportRunners(_ context.Context, reports []RunnerReport) error {
	f.mu.Lock()
	err := f.reportErr
	f.mu.Unlock()
	if err != nil {
		return err
	}
	select {
	case f.reports <- reports:
	default:
	}
	return nil
}

func (f *fakeTransport) OpenLogStream(_ context.Context, streamID string) (io.WriteCloser, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.openErr != nil {
		return nil, f.openErr
	}
	s := &fakeStream{hold: f.writeHold}
	f.streams[streamID] = s
	return s, nil
}

func (f *fakeTransport) SetCredentials(hostID, agentToken string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.hostID, f.token = hostID, agentToken
}

func (f *fakeTransport) Describe() string { return "fake://controller" }

func (f *fakeTransport) stream(id string) *fakeStream {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.streams[id]
}

// fakeStream is the controller's side of one log relay.
type fakeStream struct {
	hold time.Duration

	mu     sync.Mutex
	buf    bytes.Buffer
	closed bool
	writes int
}

func (s *fakeStream) Write(p []byte) (int, error) {
	if s.hold > 0 {
		time.Sleep(s.hold)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return 0, errors.New("stream closed")
	}
	s.writes++
	return s.buf.Write(p)
}

func (s *fakeStream) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.closed = true
	return nil
}

func (s *fakeStream) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.String()
}

func (s *fakeStream) isClosed() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closed
}

// testClock is a clock the tests move by hand, so grace periods can be crossed
// without sleeping through them.
type testClock struct {
	mu  sync.Mutex
	now time.Time
}

func newTestClock() *testClock {
	return &testClock{now: time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)}
}

func (c *testClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *testClock) advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

package agent

import (
	"context"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The one-shot report is not the only way the controller learns a runner has
// failed: when it is not delivered, the heartbeat's copy of the runner is the
// retry, and delivering it marks the report as sent. If that copy dropped the
// classification the controller would file an OOM kill or a refused
// configuration as a generic "runner exited", and nothing could correct it.
func TestAFailedRunnersHeartbeatCopyKeepsItsFaultClassification(t *testing.T) {
	tests := []struct {
		name string
		code int
		want store.FaultKind
	}{
		{"an out-of-memory kill", 137, store.FaultOutOfMemory},
		{"a runner that could not register", 64, store.FaultRegistration},
		{"a daemon that never became ready", 69, store.FaultBackend},
		{"a refused configuration", 78, store.FaultConfig},
		{"an exit nobody has a meaning for", 1, store.FaultRunnerExited},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			a, _, be, _ := newAgent(t, 2)
			track(a, "runner-1", "wl-1", true)
			be.setWorkloads(exited("wl-1", "runner-1", tc.code))
			reports, err := a.ReconcileOnce(context.Background())
			if err != nil || len(reports) != 1 || reports[0].Fault != tc.want {
				t.Fatalf("observe report = %+v, %v; want fault %q", reports, err, tc.want)
			}

			// The report is never delivered, so the heartbeat is all the
			// controller will ever hear.
			beat := a.Runners()
			if len(beat) != 1 || beat[0].State != store.RunnerFailed {
				t.Fatalf("heartbeat copy = %+v", beat)
			}
			if beat[0].Fault != tc.want {
				t.Fatalf("heartbeat copy fault = %q, want %q", beat[0].Fault, tc.want)
			}
		})
	}
}

package agent

import (
	"bytes"
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net"
	"net/http"
	"net/url"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// ErrUnauthorized reports that the controller rejected this agent's token. It
// is terminal: retrying with the same token will fail forever, so the agent
// stops rather than hammering the controller with credentials it has revoked.
var ErrUnauthorized = errors.New("agent: the controller rejected this agent's token; re-join the host with a fresh join token (zoomies agent join <controller-url> --token <join-token>)")

// ErrHostGone reports that the controller no longer has a record of this host,
// which happens when the host was deleted in the UI while the agent was down.
// The agent cannot invent itself back into the fleet; an operator must re-join.
var ErrHostGone = errors.New("agent: the controller no longer knows this host; re-join it with a fresh join token (zoomies agent join <controller-url> --token <join-token>)")

// ErrRetryable marks a failure that is worth trying again: a controller
// restart, a proxy hiccup, a flapping link. The agent backs off on these rather
// than exiting, because a host that gives up on a transient network fault takes
// its runners out of the fleet for no reason.
var ErrRetryable = errors.New("agent: transient failure talking to the controller")

// HeaderHostID carries the agent's host ID alongside its bearer token, so that
// a controller log line can name the host without first looking the token up.
const HeaderHostID = "X-Zoomies-Host"

// HeaderAgentSession carries the identity of the agent *process*, minted fresh
// when it starts and never reused.
//
// It is what makes a duplicated credential visible. A cloned VM or a copied
// state directory gives two agents one host id, and from the controller's side
// they are indistinguishable -- both hold a valid token for that host and both
// report real work. What they cannot hide is handing the session back and
// forth: a single agent moves its session forward when it restarts and never
// back, so a session this host has already left behind can only be a second
// one still running.
//
// A header rather than a field because the runner report's body is a bare JSON
// array, and the alternative was three body shapes changing instead of one
// place that every authenticated agent request already passes through.
const HeaderAgentSession = "X-Zoomies-Agent-Session"

// Sizes and deadlines for the request path.
const (
	// defaultCallTimeout bounds every request except a task long poll, which
	// sets its own deadline from the wait it asked for.
	defaultCallTimeout = 30 * time.Second
	// pollMargin is added to the requested wait when a long poll's deadline is
	// set. The request must outlive the wait the controller was asked for:
	// giving a long poll an ordinary timeout is the classic bug that turns it
	// into a tight retry loop hammering the controller once per timeout.
	pollMargin = 15 * time.Second
	// logStreamCloseWait bounds how long Close waits for the controller to
	// acknowledge a finished log stream before abandoning the request.
	logStreamCloseWait = 30 * time.Second

	maxResponseBytes = 8 << 20
	maxErrorBytes    = 4 << 10
)

// userAgent identifies this agent to the controller, which logs it and uses it
// to spot a fleet that was only half upgraded.
var userAgent = "zoomies-agent/" + version.Version

// HTTPOptions configures an HTTPTransport.
type HTTPOptions struct {
	// ControllerURL is where the controller answers, e.g.
	// https://zoomies.internal:8080.
	ControllerURL  string
	TailcatAddress string
	// CAFile pins the certificate the controller presents. For the usual
	// self-signed controller this is certificate pinning, not a public CA: it
	// is what makes a private deployment verifiable without buying a name.
	CAFile string
	// ClientCertFile and ClientKeyFile enable mTLS. Both or neither.
	ClientCertFile string
	ClientKeyFile  string
	// InsecureSkipVerify disables verification entirely. Every construction
	// with it set logs what it costs.
	InsecureSkipVerify bool
	// AllowInsecureHTTP permits an http:// controller URL that is not on
	// loopback. It is refused by default: the agent token rides on every
	// request, and the JIT runner configuration in a create task is a live
	// registration credential for the organisation's runner group, so a
	// plaintext hop hands both to anyone on the path.
	AllowInsecureHTTP bool
	// HTTPClient replaces the transport's own client. Tests use it; production
	// leaves it nil so that the TLS settings above take effect.
	HTTPClient *http.Client
	Logger     *slog.Logger
}

// HTTPTransport is the Transport a standalone agent uses: every call is an
// outbound request to the controller, so the host needs no inbound firewall
// rule and can sit behind NAT.
//
// It is safe for concurrent use; the agent heartbeats, polls and streams logs
// at the same time.
type HTTPTransport struct {
	base           string
	tailcatAddress string
	closeTunnel    func()
	http           *http.Client
	log            *slog.Logger

	// session identifies this agent process for the life of it. It is minted
	// here rather than passed in because "one agent process" is exactly what a
	// transport is, and it is never rotated: an id that changed under a
	// running agent would look like the duplicate it exists to find.
	session string

	mu         sync.RWMutex
	hostID     string
	agentToken string
}

// NewHTTPTransport builds a transport pointed at one controller.
func NewHTTPTransport(opts HTTPOptions) (*HTTPTransport, error) {
	raw := strings.TrimSpace(opts.ControllerURL)
	if strings.HasPrefix(strings.ToLower(raw), "tailcat:") {
		opts.ControllerURL = raw
		return newTailcatTransport(opts)
	}
	if raw == "" {
		return nil, errors.New("agent: no controller URL; set agent.controller_url in zoomies.yaml or pass it to `zoomies agent join`")
	}
	u, err := url.Parse(raw)
	if err != nil {
		return nil, fmt.Errorf("agent: %q is not a URL; use something like https://zoomies.example.com:8080: %w", raw, err)
	}
	switch u.Scheme {
	case "http", "https":
	default:
		return nil, fmt.Errorf("agent: controller URL %q must start with http:// or https://", raw)
	}
	if u.Host == "" {
		return nil, fmt.Errorf("agent: controller URL %q has no host; use something like https://zoomies.example.com:8080", raw)
	}

	log := opts.Logger
	if log == nil {
		log = slog.Default()
	}
	log = log.With("component", "agent.transport")

	if strings.EqualFold(u.Scheme, "http") && !isLoopbackHost(u.Hostname()) {
		if !opts.AllowInsecureHTTP {
			return nil, fmt.Errorf("agent: refusing to talk to %s over plain HTTP: this agent's token and the runner "+
				"registration credentials in every create task would cross the network in the clear. "+
				"Use https://, or set agent.allow_insecure_http (ZOOMIES_AGENT_ALLOW_INSECURE_HTTP=true) if the hop is "+
				"already private and you accept that", raw)
		}
		log.Warn("talking to the controller over plain HTTP",
			"controller", raw,
			"cost", "this agent's token and every runner's registration credentials cross the network in the clear",
			"fix", "use https://, or terminate TLS closer to this host")
	}

	tlsCfg, err := buildTLSConfig(opts, u, log)
	if err != nil {
		return nil, err
	}

	client := opts.HTTPClient
	if client == nil {
		// No Client.Timeout on purpose. A global timeout would abort a task
		// long poll and a followed log stream, both of which are idle for
		// minutes by design; every call sets its own deadline on the context
		// instead.
		client = &http.Client{
			Transport: &http.Transport{
				TLSClientConfig:       tlsCfg,
				Proxy:                 http.ProxyFromEnvironment,
				DialContext:           (&net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}).DialContext,
				MaxIdleConns:          8,
				MaxIdleConnsPerHost:   4,
				IdleConnTimeout:       90 * time.Second,
				TLSHandshakeTimeout:   10 * time.Second,
				ExpectContinueTimeout: time.Second,
				ForceAttemptHTTP2:     true,
			},
		}
	}

	return &HTTPTransport{
		base:    strings.TrimSuffix(u.String(), "/"),
		http:    client,
		log:     log,
		session: "ses_" + store.NewSecret(8),
	}, nil
}

// isLoopbackHost reports whether a URL's host names this machine, which is the
// one case where plain HTTP carries nothing off the box.
//
// "localhost" is matched by name as well as by address because that is what an
// operator types, and it is required to resolve to a loopback address.
func isLoopbackHost(host string) bool {
	host = strings.TrimSpace(strings.Trim(host, "[]"))
	if strings.EqualFold(host, "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// buildTLSConfig turns the operator's certificate settings into a tls.Config,
// failing early with a message that names the setting at fault.
func buildTLSConfig(opts HTTPOptions, u *url.URL, log *slog.Logger) (*tls.Config, error) {
	cfg := &tls.Config{MinVersion: tls.VersionTLS12}

	if opts.InsecureSkipVerify {
		// Warned on every construction, not once at startup, because the
		// failure mode is silent: anything that can intercept this connection
		// sees the JIT configurations flowing to this host and can hand the
		// agent tasks of its own.
		log.Warn("controller certificate verification is disabled; anything able to intercept this connection can read runner credentials and issue tasks to this host",
			"setting", "agent.insecure_skip_verify",
			"controller", u.Redacted(),
			"fix", "pin the controller's certificate with agent.ca_file instead")
		cfg.InsecureSkipVerify = true
	}

	if opts.CAFile != "" {
		pem, err := os.ReadFile(opts.CAFile)
		if err != nil {
			return nil, fmt.Errorf("agent: reading agent.ca_file %s: %w", opts.CAFile, err)
		}
		pool := x509.NewCertPool()
		if !pool.AppendCertsFromPEM(pem) {
			return nil, fmt.Errorf("agent: %s contains no PEM certificate; agent.ca_file must be the controller's certificate (or its CA) in PEM form -- copy /var/lib/zoomies/tls/cert.pem from the controller", opts.CAFile)
		}
		cfg.RootCAs = pool
	}

	switch {
	case opts.ClientCertFile != "" && opts.ClientKeyFile != "":
		cert, err := tls.LoadX509KeyPair(opts.ClientCertFile, opts.ClientKeyFile)
		if err != nil {
			return nil, fmt.Errorf("agent: loading the client certificate from agent.client_cert_file %s and agent.client_key_file %s: %w", opts.ClientCertFile, opts.ClientKeyFile, err)
		}
		cfg.Certificates = []tls.Certificate{cert}
	case opts.ClientCertFile != "":
		return nil, errors.New("agent: agent.client_cert_file is set without agent.client_key_file; mTLS needs both")
	case opts.ClientKeyFile != "":
		return nil, errors.New("agent: agent.client_key_file is set without agent.client_cert_file; mTLS needs both")
	}

	return cfg, nil
}

// HTTPError is a controller response the agent could not use. It carries the
// status so that callers can react to a specific one (a 404 on heartbeat means
// something quite different from a 404 on a result).
type HTTPError struct {
	Status int
	Method string
	Path   string
	// Body is a truncated copy of the response, which is usually the
	// controller's own error message and the most useful thing in the log.
	Body string
	// Retry records whether trying the same request again could work.
	Retry bool
}

func (e *HTTPError) Error() string {
	detail := ""
	if e.Body != "" {
		detail = ": " + e.Body
	}
	switch e.Status {
	case http.StatusUnauthorized:
		return fmt.Sprintf("agent: %s %s was rejected: the controller does not accept this agent's token; re-join the host with a fresh join token (zoomies agent join <controller-url> --token <join-token>)%s", e.Method, e.Path, detail)
	case http.StatusForbidden:
		return fmt.Sprintf("agent: %s %s was refused: this agent's token is not allowed to do that; check the host has not been cordoned or its token scoped down%s", e.Method, e.Path, detail)
	case http.StatusNotFound:
		return fmt.Sprintf("agent: %s %s: the controller has no such endpoint or object; it may be older than this agent (agent protocol %d) -- upgrade the controller%s", e.Method, e.Path, ProtocolVersion, detail)
	default:
		return fmt.Sprintf("agent: %s %s returned HTTP %d%s", e.Method, e.Path, e.Status, detail)
	}
}

// Is lets callers match the sentinels without unwrapping a status code, so the
// agent's loops read as "unauthorized" and "retryable" rather than as numbers.
func (e *HTTPError) Is(target error) bool {
	switch target {
	case ErrUnauthorized:
		return e.Status == http.StatusUnauthorized
	case ErrRetryable:
		return e.Retry
	}
	return false
}

// Retryable reports whether err is worth trying again. Rejected credentials and
// a deleted host are not; everything else that went wrong on the wire is.
func Retryable(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, ErrUnauthorized) || errors.Is(err, ErrHostGone) {
		return false
	}
	if errors.Is(err, context.Canceled) {
		return false
	}
	if errors.Is(err, ErrRetryable) || errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	var ne net.Error
	return errors.As(err, &ne)
}

// SetCredentials installs the identity Join returned, or the one restored from
// the agent's state file.
func (t *HTTPTransport) SetCredentials(hostID, agentToken string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.hostID, t.agentToken = hostID, agentToken
}

// Describe returns the controller URL, for the startup banner and log lines.
func (t *HTTPTransport) Describe() string {
	if t.tailcatAddress != "" {
		return TailcatController
	}
	return t.base
}

func (t *HTTPTransport) credentials() (string, string) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return t.hostID, t.agentToken
}

// request is one call to the controller, described declaratively so that the
// header, deadline and error handling live in exactly one place.
type request struct {
	method string
	path   string
	query  url.Values
	body   any
	out    any
	// anonymous omits the credentials. Only Join is anonymous, because it is
	// the call that mints them.
	anonymous bool
	timeout   time.Duration
}

func (t *HTTPTransport) call(ctx context.Context, r request) (int, error) {
	var body io.Reader
	if r.body != nil {
		raw, err := json.Marshal(r.body)
		if err != nil {
			return 0, fmt.Errorf("agent: encoding the %s request body: %w", r.path, err)
		}
		body = bytes.NewReader(raw)
	}

	target := t.base + r.path
	if len(r.query) > 0 {
		target += "?" + r.query.Encode()
	}

	timeout := r.timeout
	if timeout <= 0 {
		timeout = defaultCallTimeout
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, r.method, target, body)
	if err != nil {
		return 0, fmt.Errorf("agent: building a %s request to %s: %w", r.method, target, err)
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", userAgent)
	if r.body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if !r.anonymous {
		hostID, token := t.credentials()
		if token == "" {
			return 0, fmt.Errorf("%w: no agent token loaded yet for %s %s", ErrNotJoined, r.method, r.path)
		}
		req.Header.Set("Authorization", "Bearer "+token)
		req.Header.Set(HeaderHostID, hostID)
		req.Header.Set(HeaderAgentSession, t.session)
	}

	resp, err := t.http.Do(req)
	if err != nil {
		// A dial failure or a dropped connection is a controller restart or a
		// flapping network, both of which come back on their own.
		return 0, fmt.Errorf("agent: %s %s: %w: %w", r.method, r.path, ErrRetryable, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 300 {
		return resp.StatusCode, statusError(r.method, r.path, resp)
	}
	if r.out == nil || resp.StatusCode == http.StatusNoContent {
		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxErrorBytes))
		return resp.StatusCode, nil
	}
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxResponseBytes)).Decode(r.out); err != nil {
		if errors.Is(err, io.EOF) {
			// An empty 200 is the controller saying "nothing to tell you".
			return resp.StatusCode, nil
		}
		return resp.StatusCode, fmt.Errorf("agent: %s %s returned a body this agent could not read; the controller may be a different version (agent protocol %d): %w", r.method, r.path, ProtocolVersion, err)
	}
	return resp.StatusCode, nil
}

func statusError(method, path string, resp *http.Response) error {
	snippet, _ := io.ReadAll(io.LimitReader(resp.Body, maxErrorBytes))
	return &HTTPError{
		Status: resp.StatusCode,
		Method: method,
		Path:   path,
		Body:   strings.TrimSpace(string(snippet)),
		Retry: resp.StatusCode >= 500 ||
			resp.StatusCode == http.StatusTooManyRequests ||
			resp.StatusCode == http.StatusRequestTimeout,
	}
}

// Join redeems a join token. It is the one call made without credentials,
// because it is the call that issues them.
func (t *HTTPTransport) Join(ctx context.Context, req JoinRequest) (*JoinResponse, error) {
	if req.ProtocolVersion == 0 {
		req.ProtocolVersion = ProtocolVersion
	}
	var out JoinResponse
	status, err := t.call(ctx, request{method: http.MethodPost, path: PathJoin, body: req, out: &out, anonymous: true})
	if err != nil {
		// A refused join token is 422 here, not 401: the route is anonymous, so
		// there is no credential to be unauthorised -- what was rejected is the
		// token in the body. The installer's remedy for a spent or mistyped
		// token keys on ErrUnauthorized, so without this it never fired for the
		// one case it was written for, and an operator whose token had expired
		// was shown "returned HTTP 422" and left to work it out.
		//
		// Only on this route: 422 anywhere else is a malformed request, and
		// calling that a credential problem would send the next person to
		// re-mint a token that was never the trouble.
		if status == http.StatusUnprocessableEntity {
			return nil, fmt.Errorf("%w: %w", ErrUnauthorized, err)
		}
		return nil, err
	}
	if out.HostID == "" || out.AgentToken == "" {
		return nil, fmt.Errorf("agent: %s accepted the join but returned no host ID or agent token; the controller is probably older than this agent (agent protocol %d)", t.base, ProtocolVersion)
	}
	return &out, nil
}

// Heartbeat reports liveness and the agent's own view of its runners.
func (t *HTTPTransport) Heartbeat(ctx context.Context, req HeartbeatRequest) (*HeartbeatResponse, error) {
	if req.ProtocolVersion == 0 {
		req.ProtocolVersion = ProtocolVersion
	}
	if req.Version == "" {
		req.Version = version.Version
	}
	var out HeartbeatResponse
	status, err := t.call(ctx, request{method: http.MethodPost, path: PathHeartbeat, body: req, out: &out})
	if err != nil {
		// A 404 here is specifically "I have no host with that ID": the row was
		// deleted, and no amount of retrying will bring it back.
		if status == http.StatusNotFound {
			hostID, _ := t.credentials()
			return nil, fmt.Errorf("%w (host %s): %w", ErrHostGone, hostID, err)
		}
		return nil, err
	}
	return &out, nil
}

// PollTasks long-polls for work. An empty batch after the full wait is the
// normal idle case.
func (t *HTTPTransport) PollTasks(ctx context.Context, wait time.Duration) (*TaskBatch, error) {
	if wait <= 0 {
		wait = DefaultPollWait
	}
	seconds := int((wait + time.Second - 1) / time.Second)
	if seconds < 1 {
		seconds = 1
	}

	var out TaskBatch
	// The deadline is the wait plus a margin, never the ordinary call timeout:
	// a long poll that is cut off at its own wait can never return work.
	_, err := t.call(ctx, request{
		method:  http.MethodGet,
		path:    PathTasks,
		query:   url.Values{"wait": {strconv.Itoa(seconds)}},
		out:     &out,
		timeout: wait + pollMargin,
	})
	if err != nil {
		return nil, err
	}
	return &out, nil
}

// ReportResult reports the outcome of one task.
func (t *HTTPTransport) ReportResult(ctx context.Context, res TaskResult) error {
	_, err := t.call(ctx, request{method: http.MethodPost, path: PathResults, body: res})
	return err
}

// ReportRunners pushes runner observations outside the heartbeat cycle so a
// state change shows up in the UI immediately.
func (t *HTTPTransport) ReportRunners(ctx context.Context, reports []RunnerReport) error {
	if len(reports) == 0 {
		return nil
	}
	_, err := t.call(ctx, request{method: http.MethodPost, path: PathReport, body: reports})
	return err
}

// OpenLogStream starts a chunked POST the agent writes a runner's output into.
// The controller fans the body out to whoever is watching in the browser, which
// is how log streaming works at all when the controller can never dial in.
func (t *HTTPTransport) OpenLogStream(ctx context.Context, streamID string) (io.WriteCloser, error) {
	if strings.TrimSpace(streamID) == "" {
		return nil, errors.New("agent: cannot open a log stream without a stream ID; the controller must set one on the stream_logs task")
	}
	hostID, token := t.credentials()
	if token == "" {
		return nil, fmt.Errorf("%w: no agent token loaded yet, cannot open a log stream", ErrNotJoined)
	}

	ctx, cancel := context.WithCancel(ctx)
	pr, pw := io.Pipe()
	target := t.base + PathLogs + "/" + url.PathEscape(streamID)

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, target, pr)
	if err != nil {
		cancel()
		pr.Close()
		pw.Close()
		return nil, fmt.Errorf("agent: building the log stream request to %s: %w", target, err)
	}
	// Length is unknown, so net/http chunks the body and the controller sees
	// output as it is produced instead of when the runner exits.
	req.ContentLength = -1
	req.Header.Set("Content-Type", "application/octet-stream")
	req.Header.Set("User-Agent", userAgent)
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set(HeaderHostID, hostID)

	s := &logStreamWriter{pw: pw, cancel: cancel, done: make(chan struct{}), streamID: streamID}
	go func() {
		defer close(s.done)
		resp, err := t.http.Do(req)
		if err != nil {
			s.fail(fmt.Errorf("agent: log stream %s to %s: %w: %w", streamID, target, ErrRetryable, err))
			return
		}
		defer resp.Body.Close()
		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxErrorBytes))
		if resp.StatusCode >= 300 {
			s.fail(statusError(http.MethodPost, PathLogs+"/"+streamID, resp))
		}
	}()
	return s, nil
}

// logStreamWriter is the writer half of one relayed log stream. Errors from the
// request goroutine are surfaced from Write and Close rather than swallowed: a
// relay that silently stopped delivering looks exactly like a quiet runner.
type logStreamWriter struct {
	streamID string
	pw       *io.PipeWriter
	cancel   context.CancelFunc
	done     chan struct{}

	mu        sync.Mutex
	err       error
	closeOnce sync.Once
}

func (s *logStreamWriter) fail(err error) {
	s.mu.Lock()
	if s.err == nil {
		s.err = err
	}
	s.mu.Unlock()
	// Unblock a writer sitting in Write: the request is over, so nothing will
	// ever read from the pipe again.
	s.pw.CloseWithError(err)
}

func (s *logStreamWriter) result() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.err
}

func (s *logStreamWriter) Write(p []byte) (int, error) {
	if err := s.result(); err != nil {
		return 0, err
	}
	n, err := s.pw.Write(p)
	if err != nil {
		// Prefer the request's own error: "the controller returned 503" is
		// actionable, "io: read/write on closed pipe" is not.
		if reqErr := s.result(); reqErr != nil {
			return n, reqErr
		}
		return n, fmt.Errorf("agent: writing to log stream %s: %w", s.streamID, err)
	}
	return n, nil
}

// Close ends the request, waits for the controller's response so that a
// rejected stream is reported to the caller, and gives up after
// logStreamCloseWait so a wedged controller cannot hold the agent's shutdown.
func (s *logStreamWriter) Close() error {
	s.closeOnce.Do(func() {
		s.pw.Close()
		abandon := time.AfterFunc(logStreamCloseWait, s.cancel)
		<-s.done
		abandon.Stop()
		s.cancel()
	})
	return s.result()
}

package agent

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"
)

func newTestTransport(t *testing.T, h http.Handler) (*HTTPTransport, *httptest.Server) {
	t.Helper()
	srv := httptest.NewServer(h)
	t.Cleanup(srv.Close)
	tr, err := NewHTTPTransport(HTTPOptions{ControllerURL: srv.URL, Logger: testLogger()})
	if err != nil {
		t.Fatalf("NewHTTPTransport: %v", err)
	}
	tr.SetCredentials("host-1", "agent-token")
	return tr, srv
}

func TestHTTPTransportSendsCredentialsAndIdentifiesItself(t *testing.T) {
	var mu sync.Mutex
	seen := map[string]http.Header{}
	mux := http.NewServeMux()
	record := func(path string, body any) {
		mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
			mu.Lock()
			seen[path] = r.Header.Clone()
			mu.Unlock()
			_ = json.NewEncoder(w).Encode(body)
		})
	}
	record(PathJoin, JoinResponse{HostID: "host-1", AgentToken: "agent-token"})
	record(PathHeartbeat, HeartbeatResponse{OK: true})
	record(PathResults, struct{}{})

	tr, _ := newTestTransport(t, mux)
	ctx := context.Background()
	if _, err := tr.Join(ctx, JoinRequest{Name: "h"}); err != nil {
		t.Fatalf("Join: %v", err)
	}
	if _, err := tr.Heartbeat(ctx, HeartbeatRequest{Capacity: 2}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	if err := tr.ReportResult(ctx, TaskResult{TaskID: "t1", OK: true}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	// Join is the one call made without credentials, because it is what mints
	// them.
	if got := seen[PathJoin].Get("Authorization"); got != "" {
		t.Fatalf("join sent Authorization %q", got)
	}
	for _, path := range []string{PathHeartbeat, PathResults} {
		if got := seen[path].Get("Authorization"); got != "Bearer agent-token" {
			t.Fatalf("%s Authorization = %q", path, got)
		}
		if got := seen[path].Get(HeaderHostID); got != "host-1" {
			t.Fatalf("%s %s = %q", path, HeaderHostID, got)
		}
	}
	for path, h := range seen {
		if !strings.HasPrefix(h.Get("User-Agent"), "zoomies-agent/") {
			t.Fatalf("%s User-Agent = %q", path, h.Get("User-Agent"))
		}
	}
	if tr.Describe() == "" {
		t.Fatal("Describe returned nothing to print in the banner")
	}
}

func TestHTTPTransportHasNoGlobalTimeout(t *testing.T) {
	tr, err := NewHTTPTransport(HTTPOptions{ControllerURL: "https://controller.example:8080", Logger: testLogger()})
	if err != nil {
		t.Fatalf("NewHTTPTransport: %v", err)
	}
	// A client-wide timeout would abort long polls and followed log streams,
	// which is the classic way long-polling turns into a tight retry loop.
	if tr.http.Timeout != 0 {
		t.Fatalf("http.Client.Timeout = %s, want 0 with per-request deadlines instead", tr.http.Timeout)
	}
}

func TestHTTPTransportLongPollOutlivesTheRequestedWait(t *testing.T) {
	var gotWait string
	mux := http.NewServeMux()
	mux.HandleFunc(PathTasks, func(w http.ResponseWriter, r *http.Request) {
		gotWait = r.URL.Query().Get("wait")
		// The controller answers after the wait the agent asked for, which is
		// exactly the case a wait-length deadline would break.
		time.Sleep(300 * time.Millisecond)
		_ = json.NewEncoder(w).Encode(TaskBatch{Tasks: []Task{{ID: "t1", Kind: TaskCreateRunner}}})
	})

	tr, _ := newTestTransport(t, mux)
	batch, err := tr.PollTasks(context.Background(), 200*time.Millisecond)
	if err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if len(batch.Tasks) != 1 {
		t.Fatalf("batch = %+v, want one task", batch)
	}
	if gotWait != "1" {
		t.Fatalf("wait query = %q, want the wait in whole seconds", gotWait)
	}
}

func TestHTTPTransportPollTreats204AsIdle(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc(PathTasks, func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusNoContent) })

	tr, _ := newTestTransport(t, mux)
	batch, err := tr.PollTasks(context.Background(), time.Second)
	if err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if len(batch.Tasks) != 0 {
		t.Fatalf("batch = %+v, want empty", batch)
	}
}

func TestHTTPTransportUnauthorizedIsTerminal(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc(PathTasks, func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "unknown agent token", http.StatusUnauthorized)
	})

	tr, _ := newTestTransport(t, mux)
	_, err := tr.PollTasks(context.Background(), time.Second)
	if !errors.Is(err, ErrUnauthorized) {
		t.Fatalf("error = %v, want ErrUnauthorized", err)
	}
	if Retryable(err) {
		t.Fatal("a rejected token was reported as retryable, which would hammer the controller forever")
	}
	if !strings.Contains(err.Error(), "zoomies agent join") {
		t.Fatalf("error does not say how to recover: %v", err)
	}
}

func TestHTTPTransportHeartbeat404IsHostGone(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc(PathHeartbeat, func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "no such host", http.StatusNotFound)
	})

	tr, _ := newTestTransport(t, mux)
	_, err := tr.Heartbeat(context.Background(), HeartbeatRequest{})
	if !errors.Is(err, ErrHostGone) {
		t.Fatalf("error = %v, want ErrHostGone", err)
	}
	if Retryable(err) {
		t.Fatal("a deleted host was reported as retryable")
	}
}

func TestHTTPTransportServerErrorsAreRetryable(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc(PathHeartbeat, func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "database is locked", http.StatusServiceUnavailable)
	})

	tr, _ := newTestTransport(t, mux)
	_, err := tr.Heartbeat(context.Background(), HeartbeatRequest{})
	if err == nil {
		t.Fatal("a 503 was reported as success")
	}
	if !Retryable(err) || !errors.Is(err, ErrRetryable) {
		t.Fatalf("error = %v, want a retryable one", err)
	}
	var he *HTTPError
	if !errors.As(err, &he) || he.Status != http.StatusServiceUnavailable {
		t.Fatalf("error does not carry the status: %v", err)
	}
}

func TestHTTPTransportNetworkFailureIsRetryable(t *testing.T) {
	tr, srv := newTestTransport(t, http.NewServeMux())
	srv.Close() // nothing is listening any more

	_, err := tr.Heartbeat(context.Background(), HeartbeatRequest{})
	if !Retryable(err) {
		t.Fatalf("error = %v, want a retryable one", err)
	}
}

func TestHTTPTransportLogStreamRoundTrip(t *testing.T) {
	type delivery struct {
		path string
		auth string
		body string
	}
	got := make(chan delivery, 1)
	mux := http.NewServeMux()
	mux.HandleFunc(PathLogs+"/", func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		got <- delivery{path: r.URL.Path, auth: r.Header.Get("Authorization"), body: string(body)}
		w.WriteHeader(http.StatusOK)
	})

	tr, _ := newTestTransport(t, mux)
	w, err := tr.OpenLogStream(context.Background(), "stream-1")
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	if _, err := io.WriteString(w, "first line\n"); err != nil {
		t.Fatalf("Write: %v", err)
	}
	if _, err := io.WriteString(w, "second line\n"); err != nil {
		t.Fatalf("Write: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	select {
	case d := <-got:
		if d.body != "first line\nsecond line\n" {
			t.Fatalf("controller received %q", d.body)
		}
		if d.path != PathLogs+"/stream-1" {
			t.Fatalf("stream posted to %q", d.path)
		}
		if d.auth != "Bearer agent-token" {
			t.Fatalf("stream Authorization = %q", d.auth)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the controller never received the log stream")
	}
}

func TestHTTPTransportLogStreamSurfacesARejection(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc(PathLogs+"/", func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.Copy(io.Discard, r.Body)
		http.Error(w, "no such stream", http.StatusGone)
	})

	tr, _ := newTestTransport(t, mux)
	w, err := tr.OpenLogStream(context.Background(), "stream-1")
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	if _, err := io.WriteString(w, "output\n"); err != nil {
		t.Fatalf("Write: %v", err)
	}
	// A relay that quietly stopped delivering looks exactly like a quiet
	// runner, so the failure has to come back out of Close.
	if err := w.Close(); err == nil {
		t.Fatal("Close hid the controller's rejection")
	}
}

func TestNewHTTPTransportValidatesItsOptions(t *testing.T) {
	cases := map[string]HTTPOptions{
		"no url":       {},
		"bad scheme":   {ControllerURL: "ftp://controller"},
		"no host":      {ControllerURL: "https://"},
		"cert only":    {ControllerURL: "https://c:8080", ClientCertFile: "/tmp/cert.pem"},
		"key only":     {ControllerURL: "https://c:8080", ClientKeyFile: "/tmp/key.pem"},
		"missing ca":   {ControllerURL: "https://c:8080", CAFile: "/nonexistent/ca.pem"},
		"unparsed url": {ControllerURL: "://controller"},
	}
	for name, opts := range cases {
		t.Run(name, func(t *testing.T) {
