// The agent's token rides on every request, and a create task carries a JIT
// runner configuration -- a live registration credential for the organisation's
// runner group. Neither may cross the network in the clear by accident, so a
// plaintext controller URL is refused rather than warned about.
func TestHTTPTransportRefusesPlaintextToARemoteController(t *testing.T) {
	cases := []struct {
		url     string
		allow   bool
		wantErr bool
	}{
		{url: "https://zoomies.example.com:8080"},
		{url: "http://127.0.0.1:8080"},
		{url: "http://[::1]:8080"},
		{url: "http://localhost:8080"},
		{url: "http://zoomies.example.com:8080", wantErr: true},
		{url: "http://10.0.0.5:8080", wantErr: true},
		// An operator who has decided the hop is already private can say so.
		{url: "http://zoomies.example.com:8080", allow: true},
	}
	for _, tc := range cases {
		name := tc.url
		if tc.allow {
			name += " (opted in)"
		}
		t.Run(name, func(t *testing.T) {
			_, err := NewHTTPTransport(HTTPOptions{ControllerURL: tc.url, AllowInsecureHTTP: tc.allow})
			if (err != nil) != tc.wantErr {
				t.Fatalf("NewHTTPTransport(%q) = %v; want error=%v", tc.url, err, tc.wantErr)
			}
			if tc.wantErr && !strings.Contains(err.Error(), "allow_insecure_http") {
				t.Errorf("the refusal should name the way out: %v", err)
			}
		})
	}
}

// The session is what makes a duplicated credential visible, and it is only
// any use if the agent sends it on every authenticated call: a duplicate that
// only ever polled for tasks would go unseen if the header rode on heartbeats
// alone. It must also be stable for the life of the process -- an id that
// changed under a running agent would look exactly like the duplicate it
// exists to find -- and absent from join, which is what mints the credentials
// the session belongs to.
func TestTheAgentSendsOneStableSessionOnEveryAuthenticatedCall(t *testing.T) {
	var mu sync.Mutex
	seen := map[string]http.Header{}
	mux := http.NewServeMux()
	record := func(path string, body any) {
		mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
			mu.Lock()
			seen[path] = r.Header.Clone()
			mu.Unlock()
			_ = json.NewEncoder(w).Encode(body)
		})
	}
	record(PathJoin, JoinResponse{HostID: "host-1", AgentToken: "agent-token"})
	record(PathHeartbeat, HeartbeatResponse{OK: true})
	record(PathResults, struct{}{})
	record(PathReport, struct{}{})

	tr, _ := newTestTransport(t, mux)
	ctx := context.Background()
	if _, err := tr.Join(ctx, JoinRequest{Name: "h"}); err != nil {
		t.Fatalf("Join: %v", err)
	}
	if _, err := tr.Heartbeat(ctx, HeartbeatRequest{Capacity: 2}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	if err := tr.ReportResult(ctx, TaskResult{TaskID: "t1", OK: true}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if err := tr.ReportRunners(ctx, []RunnerReport{{RunnerID: "run_1"}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	if got := seen[PathJoin].Get(HeaderAgentSession); got != "" {
		t.Fatalf("join sent %s = %q; join is what mints the credentials the session belongs to", HeaderAgentSession, got)
	}
	first := seen[PathHeartbeat].Get(HeaderAgentSession)
	if first == "" {
		t.Fatalf("the heartbeat sent no %s", HeaderAgentSession)
	}
	for _, path := range []string{PathResults, PathReport} {
		if got := seen[path].Get(HeaderAgentSession); got != first {
			t.Fatalf("%s %s = %q, want the same session as the heartbeat (%q)", path, HeaderAgentSession, got, first)
		}
	}
}

// A refused join token is what an operator meets most often, and it is a 422
// rather than a 401: the join route is anonymous, so there is no credential to
// be unauthorised -- what was rejected is the token in the body.
//
// The installer's remedy for it ("expired, or already used; mint another")
// keys on ErrUnauthorized, so until the transport mapped this status the
// sentence never fired for the case it was written for and the operator was
// shown "returned HTTP 422" instead.
func TestARefusedJoinTokenIsUnauthorisedToTheCaller(t *testing.T) {
	tr, _ := newTestTransport(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusUnprocessableEntity)
		_, _ = io.WriteString(w, `{"error":{"code":"unprocessable","message":"this join token has expired; create a new one"}}`)
	}))

	_, err := tr.Join(context.Background(), JoinRequest{Name: "vm-1", Capacity: 2})
	if err == nil {
		t.Fatal("a refused join token was accepted")
	}
	if !errors.Is(err, ErrUnauthorized) {
		t.Fatalf("join error = %v; the installer keys its \"expired, or already used\" remedy on ErrUnauthorized and would not have printed it", err)
	}
	// The controller's own sentence survives the wrapping, because it is the
	// half that says which of the two happened.
	if !strings.Contains(err.Error(), "expired") {
		t.Errorf("the error drops what the controller said: %v", err)
	}
}

// And 422 anywhere else is a malformed request, not a credential problem:
// calling it one would send the next person to re-mint a token that was never
// the trouble.
func TestAnUnprocessableHeartbeatIsNotACredentialProblem(t *testing.T) {
	tr, _ := newTestTransport(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnprocessableEntity)
	}))

	_, err := tr.Heartbeat(context.Background(), HeartbeatRequest{})
	if err == nil {
		t.Fatal("a rejected heartbeat body was accepted")
	}
	if errors.Is(err, ErrUnauthorized) {
		t.Fatalf("heartbeat error = %v, reported as a credential problem: the agent would re-join over a malformed request", err)
	}
}

package agent

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

const (
	// relayChunkSize is how much output one read moves.
	relayChunkSize = 32 << 10
	// relayQueueDepth is how far the relay may run ahead of the controller:
	// about 2 MiB of buffered output before anything is dropped.
	relayQueueDepth = 64
	// relayStopWait bounds how long stopping a stream waits for its copy to
	// wind down before the agent gets on with shutting down.
	relayStopWait = 10 * time.Second
)

// logRelay owns the log streams this agent has open. There is one per viewer
// watching a runner in the browser: the controller cannot dial in, so the agent
// pushes the output out.
type logRelay struct {
	tr  Transport
	log *slog.Logger

	mu      sync.Mutex
	streams map[string]*logStream
}

// logStream is one running relay.
type logStream struct {
	cancel context.CancelFunc
	done   chan struct{}
	once   sync.Once
}

func (s *logStream) finish() { s.once.Do(func() { close(s.done) }) }

func newLogRelay(tr Transport, log *slog.Logger) *logRelay {
	return &logRelay{tr: tr, log: log.With("component", "agent.logs"), streams: make(map[string]*logStream)}
}

// start opens a runner's output and copies it to the controller until the
// runner stops producing, the controller closes its side, or cancel is called.
//
// Starting a stream that is already running is a no-op: the controller
// redelivers tasks, and a second copy of one stream would interleave output.
func (r *logRelay) start(ctx context.Context, streamID string, h backend.Handle, b backend.Backend, opts backend.LogOptions) error {
	r.mu.Lock()
	if _, ok := r.streams[streamID]; ok {
		r.mu.Unlock()
		return nil
	}
	sctx, cancel := context.WithCancel(ctx)
	s := &logStream{cancel: cancel, done: make(chan struct{})}
	r.streams[streamID] = s
	r.mu.Unlock()

	src, err := b.Logs(sctx, h, opts)
	if err != nil {
		r.close(streamID, s)
		return fmt.Errorf("agent: opening logs for %s from the %s backend: %w", h, b.Kind(), err)
	}
	dst, err := r.tr.OpenLogStream(sctx, streamID)
	if err != nil {
		src.Close()
		r.close(streamID, s)
		return fmt.Errorf("agent: opening log stream %s to the controller: %w", streamID, err)
	}

	go r.pump(sctx, streamID, s, src, dst)
	return nil
}

// cancel stops one stream, which is what a viewer closing the browser tab
// becomes on the host.
func (r *logRelay) cancel(streamID string) {
	r.mu.Lock()
	s, ok := r.streams[streamID]
	r.mu.Unlock()
	if !ok {
		return
	}
	s.cancel()
	select {
	case <-s.done:
	case <-time.After(relayStopWait):
		r.log.Warn("log stream did not stop promptly", "stream", streamID, "waited", relayStopWait)
	}
}

// stopAll ends every stream, called on shutdown.
func (r *logRelay) stopAll() {
	r.mu.Lock()
	ids := make([]string, 0, len(r.streams))
	for id := range r.streams {
		ids = append(ids, id)
	}
	r.mu.Unlock()
	for _, id := range ids {
		r.cancel(id)
	}
}

func (r *logRelay) close(streamID string, s *logStream) {
	r.mu.Lock()
	if cur, ok := r.streams[streamID]; ok && cur == s {
		delete(r.streams, streamID)
	}
	r.mu.Unlock()
	s.cancel()
	s.finish()
}

// pump moves output from the runner to the controller through a bounded queue.
//
// When the queue is full the relay drops output and says so, rather than
// blocking. Blocking would push back on the runner's own output pipe, and a
// container whose stdout nobody drains eventually stops making progress: one
// operator on a slow connection would then be able to stall a build. Losing the
// middle of a log with a marker saying what was lost is the cheaper failure.
func (r *logRelay) pump(ctx context.Context, streamID string, s *logStream, src io.ReadCloser, dst io.WriteCloser) {
	defer r.close(streamID, s)

	// Unblock a backend read that is not watching the context.
	stopWatch := context.AfterFunc(ctx, func() { src.Close() })
	defer stopWatch()

	queue := make(chan []byte, relayQueueDepth)
	var writer sync.WaitGroup
	writer.Add(1)
	go func() {
		defer writer.Done()
		defer func() {
			if err := dst.Close(); err != nil {
				r.log.Debug("closing log stream reported an error", "stream", streamID, "error", err)
			}
		}()
		failed := false
		for chunk := range queue {
			if failed {
				// Keep draining: the reader must never block on a controller
				// that has gone away.
				continue
			}
			if _, err := dst.Write(chunk); err != nil {
				failed = true
				r.log.Debug("controller closed a log stream", "stream", streamID, "error", err)
				// A write that failed once never recovers, and a cancel_logs
				// can have arrived before the stream existed, so nothing else
				// would end this one: it would follow the job's output for
				// hours, discarding every byte. Cancelling closes the source
				// through the AfterFunc above; the drain loop keeps the reader
				// from blocking while it winds down.
				s.cancel()
			}
		}
	}()

	buf := make([]byte, relayChunkSize)
	var dropped int64
	for {
		n, err := src.Read(buf)
		if n > 0 {
			chunk := make([]byte, 0, n+64)
			if dropped > 0 {
				chunk = append(chunk, fmt.Sprintf("\n[log stream fell behind, %d bytes dropped]\n", dropped)...)
			}
			chunk = append(chunk, buf[:n]...)
			select {
			case queue <- chunk:
				dropped = 0
			default:
				dropped += int64(n)
			}
		}
		if err != nil {
			if err != io.EOF && ctx.Err() == nil {
				r.log.Debug("log stream ended", "stream", streamID, "error", err)
			}
			break
		}
		if ctx.Err() != nil {
			break
		}
	}
	if dropped > 0 {
		// The runner has stopped producing, so waiting for room here throttles
		// nothing: a viewer must always be told what was lost, even when the
		// drop happened in the last moments of the stream.
		select {
		case queue <- []byte(fmt.Sprintf("\n[log stream fell behind, %d bytes dropped]\n", dropped)):
		case <-time.After(relayStopWait):
		}
	}

	src.Close()
	close(queue)
	writer.Wait()
}

package agent

import (
	"context"
	"errors"
	"io"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

// rejectingTransport answers every log stream the way a controller does that
// has already forgotten it: the first write fails.
type rejectingTransport struct {
	*fakeTransport
}

func (rejectingTransport) OpenLogStream(context.Context, string) (io.WriteCloser, error) {
	return rejectedStream{}, nil
}

type rejectedStream struct{}

func (rejectedStream) Write([]byte) (int, error) { return 0, errors.New("stream unknown") }
func (rejectedStream) Close() error              { return nil }

// A viewer who closes the tab before the agent acts leaves a stream the
// controller no longer knows, and a cancel_logs that found nothing to cancel.
// Nothing else ends that stream, so without this the relay follows a job's
// output for hours and throws every byte away.
func TestLogRelayStopsFollowingOnceTheControllerRejectsTheStream(t *testing.T) {
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(rejectingTransport{newFakeTransport()}, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}
	// The runner's next line is the first the relay learns the stream is dead.
	go pw.Write([]byte("a line nobody is reading\n"))

	waitFn(t, "the abandoned stream to be released without a cancel", 5*time.Second, func() bool {
		relay.mu.Lock()
		defer relay.mu.Unlock()
		return len(relay.streams) == 0
	})
	// The source has been closed, so a further write has nowhere to go.
	if _, err := pw.Write([]byte("more\n")); err == nil {
		t.Fatal("the relay is still following the runner's log")
	}
}

package agent

import (
	"context"
	"io"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
)

// burstReader produces a fixed number of full chunks as fast as it is read, and
// says when it has been drained.
type burstReader struct {
	mu        sync.Mutex
	remaining int
	drained   chan struct{}
	once      sync.Once
}

func newBurstReader(chunks int) *burstReader {
	return &burstReader{remaining: chunks, drained: make(chan struct{})}
}

func (r *burstReader) Read(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.remaining == 0 {
		r.once.Do(func() { close(r.drained) })
		return 0, io.EOF
	}
	r.remaining--
	for i := range p {
		p[i] = 'x'
	}
	return len(p), nil
}

func (r *burstReader) Close() error { return nil }

func waitFn(t *testing.T, what string, d time.Duration, fn func() bool) {
	t.Helper()
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if fn() {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("timed out after %s waiting for %s", d, what)
}

func TestLogRelayCopiesOutputEndToEnd(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return io.NopCloser(strings.NewReader("cloning repository\nrunning job\n")) }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}

	waitFn(t, "the stream to finish", 5*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && s.isClosed()
	})
	if got := tr.stream("stream-1").String(); got != "cloning repository\nrunning job\n" {
		t.Fatalf("relayed %q", got)
	}
}

func TestLogRelayCancelStopsTheStream(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}
	if _, err := pw.Write([]byte("still going\n")); err != nil {
		t.Fatalf("write: %v", err)
	}
	waitFn(t, "the first chunk to arrive", 5*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && strings.Contains(s.String(), "still going")
	})

	relay.cancel("stream-1")
	if !tr.stream("stream-1").isClosed() {
		t.Fatal("cancel did not close the controller's side of the stream")
	}
	relay.mu.Lock()
	open := len(relay.streams)
	relay.mu.Unlock()
	if open != 0 {
		t.Fatalf("%d streams still registered after cancel", open)
	}
	pw.Close()
}

func TestLogRelayDropsRatherThanBlockingOnASlowController(t *testing.T) {
	tr := newFakeTransport()
	// Every write to the controller takes 10ms: writing all 300 chunks would
	// take three seconds, far longer than the runner should ever wait.
	tr.mu.Lock()
	tr.writeHold = 10 * time.Millisecond
	tr.mu.Unlock()

	be := newFakeBackend("docker")
	src := newBurstReader(300)
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return src }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
		t.Fatalf("start: %v", err)
	}

	// The copy out of the runner must finish at the runner's pace, not the
	// controller's: a slow viewer must never throttle a job.
	select {
	case <-src.drained:
	case <-time.After(2 * time.Second):
		t.Fatal("the copy from the runner blocked on the slow controller")
	}

	waitFn(t, "the stream to finish", 10*time.Second, func() bool {
		s := tr.stream("stream-1")
		return s != nil && s.isClosed()
	})
	relayed := tr.stream("stream-1").String()
	if !strings.Contains(relayed, "log stream fell behind") {
		t.Fatal("output was dropped without telling the viewer that it was")
	}
	if len(relayed) >= 300*relayChunkSize {
		t.Fatal("nothing was dropped, so the relay must have blocked")
	}
}

func TestLogRelayIgnoresARedeliveredStart(t *testing.T) {
	tr := newFakeTransport()
	be := newFakeBackend("docker")
	pr, pw := io.Pipe()
	t.Cleanup(func() { pw.Close() })
	be.mu.Lock()
	be.logs = func() io.ReadCloser { return pr }
	be.mu.Unlock()

	relay := newLogRelay(tr, testLogger())
	for range 3 {
		if err := relay.start(context.Background(), "stream-1", "wl-1", be, backend.LogOptions{Follow: true}); err != nil {
			t.Fatalf("start: %v", err)
		}
	}
	relay.mu.Lock()
	open := len(relay.streams)
	relay.mu.Unlock()
	if open != 1 {
		t.Fatalf("%d streams open, want 1: a redelivered stream_logs task must not open a second copy", open)
	}
	relay.stopAll()
}

func TestAgentStreamsAndCancelsLogsForARunner(t *testing.T) {
	h := newHarness(t, 1)
	h.be.mu.Lock()
	h.be.logs = func() io.ReadCloser { return io.NopCloser(strings.NewReader("job output\n")) }
	h.be.mu.Unlock()

	h.tr.tasks <- []Task{createTask("task-1", "runner-1")}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("create failed: %+v", res)
	}

	h.tr.tasks <- []Task{{ID: "task-2", Kind: TaskStreamLogs, RunnerID: "runner-1", StreamID: "stream-1"}}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("stream_logs failed: %+v", res)
	}
	waitFn(t, "the log output to arrive", 5*time.Second, func() bool {
		s := h.tr.stream("stream-1")
		return s != nil && strings.Contains(s.String(), "job output")
	})

	h.tr.tasks <- []Task{{ID: "task-3", Kind: TaskCancelLogs, RunnerID: "runner-1", StreamID: "stream-1"}}
	if res := h.nextResult(); !res.OK {
		t.Fatalf("cancel_logs failed: %+v", res)
	}
}

func TestStreamLogsForAnUnknownRunnerIsReported(t *testing.T) {
	h := newHarness(t, 1)
	h.tr.tasks <- []Task{{ID: "task-1", Kind: TaskStreamLogs, RunnerID: "runner-404", StreamID: "stream-1"}}

	res := h.nextResult()
	if res.OK || !strings.Contains(res.Error, "runner-404") {
		t.Fatalf("unexpected result: %+v", res)
	}
}

package agent

import (
	"context"
	"time"
)

type logMaintainer interface {
	PruneLogs(context.Context, int64) error
}

func (a *Agent) nativeLogLoop(ctx context.Context) error {
	t := time.NewTicker(time.Minute)
	defer t.Stop()
	for {
		for _, kind := range a.opts.Backends.Kinds() {
			b, err := a.opts.Backends.Get(kind)
			if err != nil {
				continue
			}
			if m, ok := b.(logMaintainer); ok {
				work, cancel := context.WithTimeout(ctx, 10*time.Second)
				err := m.PruneLogs(work, 10<<20)
				cancel()
				if err != nil {
					a.log.Warn("could not bound native runner logs", "backend", kind, "error", err)
				}
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-t.C:
		}
	}
}

package agent

import (
	"testing"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// An out-of-memory kill is the fleet's failure however the runner ended, and
// the controller can only put it on the job if the agent says so: exit 137,
// the daemon's OOMKilled on any other code, and OOMKilled on a clean exit --
// the step killed under a runner that went on to finish the job.
func TestAnOutOfMemoryKillIsClassifiedWhateverTheRunnerDidNext(t *testing.T) {
	for _, tc := range []struct {
		name      string
		status    backend.Status
		stopping  bool
		wantState store.RunnerState
		wantFault store.FaultKind
	}{
		{"exit 137", backend.Status{Phase: backend.PhaseFailed, ExitCode: 137}, false, store.RunnerFailed, store.FaultOutOfMemory},
		{"killed with another code", backend.Status{Phase: backend.PhaseFailed, ExitCode: 1, OOMKilled: true}, false, store.RunnerFailed, store.FaultOutOfMemory},
		{"a step killed under a runner that finished", backend.Status{Phase: backend.PhaseFailed, OOMKilled: true}, false, store.RunnerRemoved, store.FaultOutOfMemory},
		{"a clean exit is no fault", backend.Status{Phase: backend.PhaseExited}, false, store.RunnerRemoved, ""},
		{"an ordinary failure is not memory", backend.Status{Phase: backend.PhaseFailed, ExitCode: 1}, false, store.RunnerFailed, store.FaultRunnerExited},
		// A kill Zoomies asked for is not the job's, and not memory.
		{"a stop is not a kill", backend.Status{Phase: backend.PhaseFailed, ExitCode: 137}, true, store.RunnerRemoved, ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			state, msg, fault := terminalOutcome(tracked{ephemeral: true, stopping: tc.stopping}, tc.status)
			if state != tc.wantState || fault != tc.wantFault {
				t.Fatalf("terminalOutcome = %s, %q (%s); want %s, %q", state, fault, msg, tc.wantState, tc.wantFault)
			}
		})
	}
}

package agent

import (
	"context"
	"fmt"
	"runtime"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

type warmKey struct {
	platform string
	kind     store.BackendKind
	image    string
	policy   store.PullPolicy
	dind     bool
}

type warmResult struct {
	digest       string
	at           time.Time
	refreshAfter time.Duration
}

type prewarmResult struct {
	digest   string
	cached   bool
	duration time.Duration
}

// Pools sharing an image often refresh together. Reuse successful preparation
// for one minute, including its dependencies, rather than extracting it again.
// This only coalesces background prewarming; creates still apply their policy.
func (a *Agent) prewarm(ctx context.Context, b backend.Backend, p backend.ImagePrewarmer, task Task) (result prewarmResult, err error) {
	started := a.now()
	defer func() {
		if err != nil {
			result.digest = ""
		}
		result.duration = a.now().Sub(started)
		outcome := "refresh"
		if result.cached {
			outcome = "cache_hit"
		}
		a.log.Info("background image preparation", "outcome", outcome, "backend", b.Kind(), "duration", result.duration, "ok", err == nil, "digest", result.digest)
	}()
	key := warmKey{platform: runtime.GOOS + "/" + runtime.GOARCH, kind: b.Kind(), image: task.Image, policy: task.PullPolicy,
		dind: task.Spec != nil && task.Spec.DockerMode == store.DockerDinD}
	a.mu.Lock()
	cached, found := a.warmed[key]
	a.mu.Unlock()
	if found && a.now().Sub(cached.at) >= 0 && a.now().Sub(cached.at) < cached.refreshAfter {
		result.digest = cached.digest
		result.cached = true
		return result, nil
	}
	result.digest, err = p.PrewarmImage(ctx, task.Image, task.PullPolicy)
	if err != nil {
		return result, err
	}
	if key.dind {
		dependencies, ok := b.(interface {
			PrewarmDinD(context.Context) error
		})
		if !ok {
			return result, fmt.Errorf("the %s backend cannot prewarm the required Docker sidecar", b.Kind())
		}
		if err := dependencies.PrewarmDinD(ctx); err != nil {
			return result, err
		}
	}
	a.mu.Lock()
	if a.warmed == nil || len(a.warmed) >= 128 {
		a.warmed = make(map[warmKey]warmResult)
	}
	a.warmed[key] = warmResult{digest: result.digest, at: a.now(), refreshAfter: time.Minute - time.Duration(a.randomFraction()*float64(15*time.Second))}
	a.mu.Unlock()
	return result, nil
}

// Package agent implements the half of Zoomies that runs runners: the agent
// daemon, its transport to the controller, and the reconciliation loop that
// keeps a host's workloads matching what the controller asked for.
//
// Agents only ever connect outbound. The controller never dials an agent, so a
// host behind NAT or a restrictive firewall needs no inbound rule -- which is
// the usual reason "multi-host" support turns into a VPN project.
package agent

import (
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// ProtocolVersion is bumped when the agent/controller wire format changes in a
// way an older peer cannot tolerate. The controller refuses a mismatched agent
// with a message telling the operator to upgrade it.
const ProtocolVersion = 1

// FeatureElasticCPU is advertised by an agent that can apply per-runner CPU
// targets. It lets a new controller coexist with older agents without
// claiming a live quota moved when that agent could not understand the order.
const FeatureElasticCPU = "elastic-cpu"

// FeatureToolCacheFill is advertised by an agent that understands
// TaskFillToolCache. An older agent refuses a kind it does not know, which is
// safe but would read on the controller as a fill that failed on every host.
const FeatureToolCacheFill = "tool-cache-fill"

// JoinRequest redeems a short-lived join token and enrols a new host.
type JoinRequest struct {
	Connection      string `json:"-"`
	ProtocolVersion int    `json:"protocol_version"`
	JoinToken       string `json:"join_token"`
	Name            string `json:"name"`
	Address         string `json:"address,omitempty"`
	Capacity        int    `json:"capacity"`
	OS              string `json:"os"`
	// Distro and OSVersion say which Linux this is. The controller cannot
	// place a pool that asks for Ubuntu 24.04 without them, and an agent too
	// old to send them is simply a host that makes no platform promise.
	Distro    string `json:"distro,omitempty"`
	OSVersion string `json:"os_version,omitempty"`
	Arch      string `json:"arch"`
	// CPUs and MemoryMB are how much machine this host is, which is not always
	// how much this agent may use. An agent in a container sees its cgroup's
	// share, but a Docker runner is a sibling on the host and outside that
	// cgroup, so the daemon's view of the machine is the one that decides what
	// can be placed here; the larger of the two is sent. A process-backend
	// runner is a child inside the cgroup, and there the two are the same.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	// DiskTotalMB and DiskFreeMB measure the filesystem holding the work
	// directory, which is where a runner's checkout and its caches land. Free
	// is what is available to a runner rather than what is unused: the two
	// differ by the reserve the filesystem keeps for root, and placing work
	// into space the job cannot write to is the failure that distinction
	// exists to prevent. Zero means the agent could not measure it, which is
	// not the same as a full disk.
	DiskTotalMB int64  `json:"disk_total_mb,omitempty"`
	DiskFreeMB  int64  `json:"disk_free_mb,omitempty"`
	Version     string `json:"version"`
	// Features is sent at join as well as on every heartbeat, so a host is
	// not shown as unable to lend CPU for the thirty seconds between the two.
	Features []string          `json:"features,omitempty"`
	Labels   map[string]string `json:"labels,omitempty"`
	Backends []backend.Info    `json:"backends"`
	// PreviousToken is the agent token this host was issued the last time it
	// joined, sent when the credentials file still holds one. It is what lets
	// a rebuilt machine reclaim its own row: without it the controller refuses
	// to replace an existing host of the same name, because a join token on its
	// own must not be enough to take over somebody else's machine.
	PreviousToken string `json:"previous_token,omitempty"`
	// PreviousHostID is the row this host was last enrolled as, sent from the
	// same credentials file as PreviousToken.
	//
	// The token proves ownership; this says what is owned. Without it the
	// controller can only find the old row by name, and the name is not
	// stable: it is derived from what the machine is, so an agent that has
	// learnt to measure its own CPUs and memory computes a different one from
	// an agent that had not. Upgrading such a host therefore enrolled it a
	// second time -- a new row with the correct figures, beside the old row
	// still being kept alive by the process that had not been restarted yet.
	//
	// Empty from an agent too old to send it, and the name lookup still stands
	// behind it for exactly that case.
	PreviousHostID string `json:"previous_host_id,omitempty"`
}

// JoinResponse hands back the host's identity and its long-lived agent token.
// The token is shown exactly once; the controller stores only its hash.
type JoinResponse struct {
	HostID     string `json:"host_id"`
	AgentToken string `json:"agent_token"`
	// ControllerVersion lets the agent warn about a version skew.
	ControllerVersion string `json:"controller_version"`
	HeartbeatInterval string `json:"heartbeat_interval"`
}

// HeartbeatRequest is sent on every interval. It carries the agent's own view
// of its runners so the controller can detect drift without polling.
type HeartbeatRequest struct {
	Usage           *store.HostUsage `json:"usage,omitempty"`
	ProtocolVersion int              `json:"protocol_version"`
	// Capacity is the agent's configured value, sent for the log and for
	// older controllers. The controller does not write it: capacity is set
	// at join and belongs to the operator after that.
	Capacity int `json:"capacity"`
	// CPUs and MemoryMB are facts about the machine rather than the operator's
	// choice, so unlike Capacity the controller does record them: a host
	// resized in place must stop describing itself as the machine it used to be.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	// DiskTotalMB and DiskFreeMB are the work directory's filesystem, sent on
	// every beat because free space is the one of these that moves on its own.
	// The controller writes them under a tolerance rather than on every
	// change, or a fleet would take one row write per host per beat for a
	// figure that is never exactly the same twice.
	DiskTotalMB int64          `json:"disk_total_mb,omitempty"`
	DiskFreeMB  int64          `json:"disk_free_mb,omitempty"`
	Version     string         `json:"version"`
	Features    []string       `json:"features,omitempty"`
	Backends    []backend.Info `json:"backends,omitempty"`
	Runners     []RunnerReport `json:"runners,omitempty"`
	// Runtime is the container-runtime cooldown this agent is in, absent
	// when it is in none. It used to be a log line on the host and nothing
	// else, so a fleet whose daemon kept falling over saw only runners that
	// were slow to appear. Absent from an agent too old to send it, which the
	// controller reads the same way as a healthy runtime -- the only thing it
	// ever knew about such a host -- and an older controller ignores it.
	Runtime *RuntimeReport `json:"runtime,omitempty"`
}

// RuntimeReport is the agent's runtime cooldown as it stands at this beat.
type RuntimeReport struct {
	// Failures is how many runtime failures in a row, capped at five.
	Failures int `json:"failures"`
	// Kind is RuntimeUnavailable or RuntimeTimeout.
	Kind string `json:"kind"`
	// Error is the last failure as the backend worded it, which carries the
	// socket path or the start hint the operator needs.
	Error string `json:"error,omitempty"`
	// RetryIn is how long until the one recovery attempt, rather than when:
	// the controller turns it into a time on its own clock, so a host whose
	// clock has drifted cannot tell the Hosts page something untrue.
	RetryIn time.Duration `json:"retry_in"`
}

// The two kinds of runtime failure that open the cooldown.
const (
	// RuntimeUnavailable is a daemon the agent could not reach at all.
	RuntimeUnavailable = "unavailable"
	// RuntimeTimeout is a daemon that was reached and did not answer.
	RuntimeTimeout = "timeout"
)

// HeartbeatResponse tells the agent whether the controller still recognises it.
type HeartbeatResponse struct {
	// MutationsPaused preserves observed workloads during fenced recovery.
	MutationsPaused bool `json:"mutations_paused,omitempty"`
	OK              bool `json:"ok"`
	// Cordoned mirrors the host's cordon flag so the agent can stop asking for
	// work without waiting for the next task poll.
	Cordoned bool `json:"cordoned"`
	// ControllerVersion is echoed for skew detection.
	ControllerVersion string `json:"controller_version"`
	// Incompatible says this agent speaks a protocol the controller does not,
	// with IncompatibleReason as the sentence to log. It is separate from
	// Cordoned because they are separate facts -- one is an operator's
	// decision, the other this controller's conclusion about the binary --
	// even though the controller sets Cordoned too, so an agent that predates
	// these fields still stops asking for work.
	Incompatible       bool   `json:"incompatible,omitempty"`
	IncompatibleReason string `json:"incompatible_reason,omitempty"`
	// ProtocolVersion is what the controller speaks, so the agent can say
	// which way the gap runs rather than only that there is one.
	ProtocolVersion int `json:"protocol_version,omitempty"`
	// ResyncRequested asks the agent to send a full runner report next time,
	// which the controller sets after its own restart.
	ResyncRequested bool `json:"resync_requested"`
	// Throttle is the controller's current throttle for this host: how far
	// it has stepped the CPU quota of every runner here down, after the
	// host's own measurements said it was overwhelmed. The agent applies the
	// factor to each live container it can, and applies it again when the
	// factor moves. It is sent on every beat rather than only when it changes,
	// so an agent that restarted or missed the beat the throttle lifted on
	// still restores its runners. Nil from a controller too old to send it,
	// which an agent reads as no throttle at all.
	Throttle *ThrottleDirective `json:"throttle,omitempty"`
	// ElasticCPU is the per-runner CPU target set. Missing means restore every
	// previous boost to its base, so a controller downgrade cannot strand a
	// job at a stale quota. Older agents ignore this additive field.
	ElasticCPU []ElasticCPUDirective `json:"elastic_cpu,omitempty"`
	// UnknownRunners names the runners this host reported that the controller
	// has no live row for. They are the ones whose workloads may be removed.
	//
	// An agent adopts what it finds running when it starts, so that a restart
	// does not destroy the jobs on its host. That adoption is also what stops
	// it recognising genuine litter -- a workload whose runner the controller
	// deleted while the agent was down -- so the controller answers with the
	// ones it does not know, and only those are reaped. Additive: an older
	// controller sends nothing here, and an agent that receives nothing simply
	// keeps what it adopted, which is the safe direction.
	UnknownRunners []string `json:"unknown_runners,omitempty"`
}

// ElasticCPUDirective lends otherwise idle CPU to one runner. The factor is
// relative to its creation allocation, which also works for DinD: an
// automatic slot is split into two containers and both halves use the factor.
type ElasticCPUDirective struct {
	RunnerID   string  `json:"runner_id"`
	CPUFactor  float64 `json:"cpu_factor"`
	BaseCPUs   float64 `json:"base_cpus"`
	TargetCPUs float64 `json:"target_cpus"`
	Reason     string  `json:"reason,omitempty"`
}

// ThrottleDirective is what a throttled host's agent is told to do about it.
type ThrottleDirective struct {
	// Level is the rung the host is on, for the log line; zero is none.
	Level int `json:"level"`
	// CPUFactor is the share of its allocated CPU each runner is to be left:
	// 1 restores every runner to what it was created with.
	CPUFactor float64 `json:"cpu_factor"`
}

// RunnerReport is the agent's observation of one runner. The controller merges
// it into the runner's authoritative state.
type RunnerReport struct {
	// HostRemoved is positive confirmation that Remove completed, not merely exit.
	HostRemoved  bool              `json:"host_removed,omitempty"`
	CleanupError string            `json:"cleanup_error,omitempty"`
	RunnerID     string            `json:"runner_id"`
	State        store.RunnerState `json:"state"`
	Handle       backend.Handle    `json:"handle,omitempty"`
	Phase        backend.Phase     `json:"phase,omitempty"`
	ExitCode     int               `json:"exit_code,omitempty"`
	Message      string            `json:"message,omitempty"`
	// Fault categorises a failure, decided here rather than by the controller
	// because this is the side holding the evidence: the exit code, the
	// daemon's own reply, the entrypoint's reserved codes. By the time a
	// message has reached the controller it has been reworded twice and the
	// only thing left to classify from is prose. An agent older than this
	// field sends none, which the controller reads as unclassified -- honest,
	// and exactly what it knew before.
	Fault store.FaultKind `json:"fault,omitempty"`
	Stats backend.Stats   `json:"stats,omitempty"`
	// GitHubRunnerID is filled in once the runner has registered.
	GitHubRunnerID int64     `json:"github_runner_id,omitempty"`
	ObservedAt     time.Time `json:"observed_at"`
}

// TaskKind names one lifecycle command.
type TaskKind string

const (
	// TaskCreateRunner asks the agent to materialise a runner.
	TaskCreateRunner TaskKind = "create_runner"
	// TaskStopRunner asks the agent to let the runner finish its current job
	// and then exit. This is what a drain becomes on the host.
	TaskStopRunner TaskKind = "stop_runner"
	// TaskRemoveRunner tears the workload down immediately.
	TaskRemoveRunner TaskKind = "remove_runner"
	// TaskStreamLogs opens an outbound log relay for a UI viewer.
	TaskStreamLogs TaskKind = "stream_logs"
	// TaskCancelLogs closes one.
	TaskCancelLogs   TaskKind = "cancel_logs"
	TaskPrewarmImage TaskKind = "prewarm_image"
	// TaskFillToolCache puts the toolchain versions a pool's jobs ask for in
	// its kept tool cache on this host, ahead of the jobs.
	TaskFillToolCache TaskKind = "fill_tool_cache"
)

// Task is one unit of work handed to an agent. Tasks are idempotent: the
// controller may redeliver one after a restart, and applying it twice must
// leave the host in the same place.
type Task struct {
	startupWait *time.Duration
	ID          string   `json:"id"`
	Kind        TaskKind `json:"kind"`
	// RunnerID is the runner this task concerns.
	RunnerID string `json:"runner_id,omitempty"`
	// Spec is set for TaskCreateRunner and carries the credentials the runner
	// needs. It is the only place a JIT config crosses the wire, which is why
	// the agent transport requires TLS in any non-loopback deployment.
	Spec *backend.Spec `json:"spec,omitempty"`
	// Backend selects which registered backend handles this task.
	Backend    store.BackendKind `json:"backend,omitempty"`
	PoolID     string            `json:"pool_id,omitempty"`
	Image      string            `json:"image,omitempty"`
	PullPolicy store.PullPolicy  `json:"pull_policy,omitempty"`
	// StopTimeout bounds a graceful stop.
	StopTimeout time.Duration `json:"stop_timeout,omitempty"`
	// StreamID identifies a log relay for TaskStreamLogs and TaskCancelLogs.
	StreamID string `json:"stream_id,omitempty"`
	// LogOptions configures a log relay.
	LogOptions *backend.LogOptions `json:"log_options,omitempty"`
	// Tools is what a TaskFillToolCache installs; its Spec names the pool.
	Tools    []backend.ToolRequest `json:"tools,omitempty"`
	IssuedAt time.Time             `json:"issued_at"`
	// Attempt counts deliveries of this task, from 1. A create that cannot
	// establish whether its runner already exists reads it to tell the first
	// delivery -- when no workload of that runner's can exist yet, so failing
	// promptly costs nothing -- from a redelivery, where a workload may be
	// mid-job and only silence is safe. Zero is a controller from before the
	// field, which is treated like a redelivery.
	Attempt int `json:"attempt,omitempty"`
}

// TaskResult reports the outcome of a task back to the controller.
type TaskResult struct {
	StartupWait       *time.Duration `json:"startup_wait,omitempty"`
	DinDReadyDuration *time.Duration `json:"dind_ready_duration,omitempty"`
	// PrewarmCached distinguishes preparation reused on the host from work sent
	// to the runtime. The pointer keeps results from older agents identifiable
	// rather than silently calling every one a refresh.
	PrewarmCached   *bool          `json:"prewarm_cached,omitempty"`
	PrewarmDuration *time.Duration `json:"prewarm_duration,omitempty"`
	// ToolFills is what a TaskFillToolCache did with each request, including
	// when the fill as a whole failed part way.
	ToolFills []backend.ToolFill `json:"tool_fills,omitempty"`
	TaskID    string             `json:"task_id"`
	// Kind is the kind of the task this answers. The controller uses it to
	// tell a lifecycle task that failed -- which leaves the runner unusable --
	// from a log relay that could not be opened, which leaves it exactly as it
	// was. An agent from before this field is read from the controller's own
	// record of the task instead.
	Kind     TaskKind       `json:"kind,omitempty"`
	RunnerID string         `json:"runner_id,omitempty"`
	OK       bool           `json:"ok"`
	Error    string         `json:"error,omitempty"`
	Handle   backend.Handle `json:"handle,omitempty"`
	// ImagePullDuration is nil when the backend cannot distinguish pulling
	// from creation. ContainerStartedAt is the end of workload creation.
	ImagePullDuration  *time.Duration `json:"image_pull_duration,omitempty"`
	CreateDuration     time.Duration  `json:"create_duration,omitempty"`
	ContainerStartedAt *time.Time     `json:"container_started_at,omitempty"`
	Digest             string         `json:"digest,omitempty"`
	// State is the runner state the agent believes the runner reached.
	State store.RunnerState `json:"state,omitempty"`
	// Fault categorises a lifecycle task that failed, for the same reason
	// RunnerReport carries one: the backend's answer is here and nowhere else.
	Fault store.FaultKind `json:"fault,omitempty"`
	// NotStarted says the agent gave the task back untouched -- it was
	// shutting down before the task began -- so the controller should offer
	// it again rather than fail the runner. Without it a routine upgrade
	// failed every create still waiting for a startup slot, with a message
	// that said it was safe to redeliver while the runner was marked failed.
	NotStarted bool `json:"not_started,omitempty"`
	// CleanupPending says a remove did not complete because the daemon is
	// still carrying out a removal of the workload -- one it will finish
	// without being asked again -- so the controller should record nothing
	// against the runner. It is only ever set with OK false. Without it every
	// attempt that found a slow removal still going was counted as a failed
	// cleanup, and the runner was reported as something left behind while
	// the daemon was deleting it. A controller from before the field reads
	// the result as the failure it always did.
	CleanupPending bool      `json:"cleanup_pending,omitempty"`
	CompletedAt    time.Time `json:"completed_at"`
}

// TaskBatch is the response to a task poll.
type TaskBatch struct {
	Tasks []Task `json:"tasks"`
	// Backoff asks the agent to wait before polling again, used when the
	// controller wants to shed load.
	Backoff time.Duration `json:"backoff,omitempty"`
}

// LogChunk is one frame of a relayed log stream.
type LogChunk struct {
	StreamID string `json:"stream_id"`
	Data     string `json:"data"`
	// EOF marks the final frame; Error explains an abnormal end.
	EOF   bool   `json:"eof,omitempty"`
	Error string `json:"error,omitempty"`
}

// Endpoints are the controller paths the agent uses. They live here so that the
// agent client and the controller's router cannot drift apart.
const (
	PathJoin      = "/api/v1/agent/join"
	PathHeartbeat = "/api/v1/agent/heartbeat"
	PathTasks     = "/api/v1/agent/tasks"
	PathResults   = "/api/v1/agent/results"
	PathReport    = "/api/v1/agent/report"
	PathLogs      = "/api/v1/agent/logs"
)

// DefaultPollWait is how long a task poll blocks before returning empty. It is
// short enough to keep proxies from timing the connection out and long enough
// that an idle agent makes very few requests.
const DefaultPollWait = 25 * time.Second

// DefaultStopTimeout is how long a graceful stop waits for a runner to finish
// its current job before the workload is killed.
const DefaultStopTimeout = 5 * time.Minute

// MaxRunnersPerReport is the most runners one heartbeat or runner report may
// carry. It lives here so both halves of the protocol agree on it.
//
// A host runs as many runners as it has slots, which is tens and never
// thousands, so the number is far above anything a working agent sends. What
// it bounds is the other case: every entry in a report is a store read and
// possibly a write behind the single writer, so an unbounded array is a way
// for one host to hold the writer for every other host.
const MaxRunnersPerReport = 1000

package agent

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// reconcileLoop keeps the host and the agent's beliefs about it in step.
func (a *Agent) reconcileLoop(ctx context.Context) error {
	ticker := time.NewTicker(defaultReconcileInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}

		reports, err := a.ReconcileOnce(ctx)
		if err != nil {
			// A backend that cannot be listed is worth saying out loud, but it
			// is not fatal: the other backends still work, and the daemon may
			// simply be restarting.
			a.log.Warn("reconcile did not complete", "error", err)
		}
		if len(reports) == 0 {
			continue
		}
		a.sendReports(ctx, reports)
	}
}

// sendReports delivers one pass's observations and, once the controller has
// accepted them, remembers which finished runners it now knows about.
func (a *Agent) sendReports(ctx context.Context, reports []RunnerReport) {
	rctx, cancel := context.WithTimeout(ctx, reportTimeout)
	defer cancel()
	if err := a.tr.ReportRunners(rctx, reports); err != nil {
		a.log.Warn("could not report runner observations", "runners", len(reports), "error", err)
		return
	}
	a.markReported(reports)
}

// ReconcileOnce compares every backend's workloads against what the agent
// believes and returns the observations worth sending to the controller.
//
// It is exported so the behaviour that deletes things can be tested directly
// rather than through a ticker.
func (a *Agent) ReconcileOnce(ctx context.Context) ([]RunnerReport, error) {
	now := a.now()
	var reports []RunnerReport
	var errs []error
	seen := make(map[string]bool)

	// A backend that could not be listed says nothing about the runners on
	// it. Treating "not listed" like "not seen" would let a transient daemon
	// error a minute into a runner's life declare it gone, have the controller
	// mark its job lost, and then reap the live container as an orphan once
	// the daemon answered again.
	unlisted := make(map[store.BackendKind]bool)

	kinds := a.opts.Backends.Kinds()
	slices.Sort(kinds)
	for _, kind := range kinds {
		b, err := a.opts.Backends.Get(kind)
		if err != nil {
			errs = append(errs, err)
			unlisted[kind] = true
			continue
		}
		workloads, err := b.List(ctx)
		if err != nil {
			errs = append(errs, fmt.Errorf("agent: listing %s workloads on this host: %w", kind, err))
			unlisted[kind] = true
			continue
		}

		a.mu.Lock()
		pending := a.inventoryPending[kind]
		delete(a.inventoryPending, kind)
		a.mu.Unlock()
		if pending {
			for _, w := range workloads {
				if w.RunnerID != "" && !w.Sidecar {
					a.adopt(w.RunnerID, kind, w)
				}
			}
		}
		for _, w := range workloads {
			if w.Sidecar {
				// A sidecar carries its runner's id, so it must never be
				// looked up as one. The backend only lists it once that
				// runner has gone, and what is left is a privileged daemon
				// nobody is using. What that is worth reporting is reapOrphan's
				// decision, not this loop's.
				if rep, ok := a.reapOrphan(ctx, b, kind, w, now); ok {
					reports = append(reports, rep)
				}
				continue
			}
			r, tracked := a.snapshot(w.RunnerID)
			if !tracked {
				if rep, ok := a.reapOrphan(ctx, b, kind, w, now); ok {
					reports = append(reports, rep)
				}
				continue
			}
			seen[w.RunnerID] = true
			a.forgetOrphan(w.Handle)
			if rep, ok := a.observe(ctx, b, r, w, now); ok {
				reports = append(reports, rep)
			}
		}
	}

	// A runner the agent tracks whose workload appears nowhere has been removed
	// behind the agent's back -- by an operator with docker rm, or by a daemon
	// restart with cleanup.
	for _, r := range a.trackedRunners() {
		if r.hostRemoved {
			// Delivery of a completed removal does not depend on the backend
			// still answering, or on the startup grace for missing workloads.
			if !seen[r.runnerID] {
				reports = append(reports, r.report())
			}
			continue
		}
		if seen[r.runnerID] || unlisted[r.kind] {
			continue
		}
		if now.Sub(r.createdAt) < missingGrace {
			// A workload created moments ago may not be listed yet; declaring
			// it gone would fail a runner that is starting perfectly well.
			continue
		}
		if r.terminal {
			if r.reported {
				a.untrack(r.runnerID)
			} else {
				reports = append(reports, r.report())
			}
			continue
		}
		msg := fmt.Sprintf("workload %s is no longer on host %s", r.handle, a.opts.Name)
		a.markTerminal(r.runnerID, store.RunnerRemoved, backend.PhaseGone, 0, msg, "", now)
		a.log.Info("runner workload disappeared", "runner", r.runnerID, "handle", r.handle, "backend", r.kind)
		reports = append(reports, RunnerReport{
			RunnerID:   r.runnerID,
			State:      store.RunnerRemoved,
			Handle:     r.handle,
			Phase:      backend.PhaseGone,
			Message:    msg,
			ObservedAt: now,
		})
	}

	return reports, errors.Join(errs...)
}

// observe turns one live workload into a report, and decides the fate of one
// that has stopped.
func (a *Agent) observe(ctx context.Context, b backend.Backend, r tracked, w backend.Workload, now time.Time) (RunnerReport, bool) {
	if r.hostRemoved {
		return r.report(), true
	}
	switch w.Status.Phase {
	case backend.PhaseExited, backend.PhaseExitUnknown, backend.PhaseFailed, backend.PhaseGone:
		if r.terminal {
			// Its end of life has been reported; what is left is the workload
			// itself, and it is this agent's job to get rid of it.
			return a.cleanUp(ctx, b, r, w, now)
		}
		state, msg, fault := terminalOutcome(r, w.Status)
		a.markTerminal(r.runnerID, state, w.Status.Phase, w.Status.ExitCode, msg, fault, now)
		a.log.Info("runner reached the end of its life",
			"runner", r.runnerID, "handle", w.Handle, "state", state, "exit_code", w.Status.ExitCode, "detail", msg)
		return RunnerReport{
			RunnerID:   r.runnerID,
			State:      state,
			Handle:     w.Handle,
			Phase:      w.Status.Phase,
			ExitCode:   w.Status.ExitCode,
			Fault:      fault,
			Message:    msg,
			ObservedAt: now,
		}, true

	default:
		// Resource sampling runs separately, so a slow stats endpoint cannot
		// delay noticing exits or returning lifecycle observations.
		stats := r.stats
		a.markRunning(r.runnerID, w, stats, now)
		// No lifecycle state is claimed for a live runner. Whether it is idle
		// or busy is GitHub's answer, not the host's, and guessing here would
		// fight the controller's state machine.
		return RunnerReport{
			RunnerID:   r.runnerID,
			Handle:     w.Handle,
			Phase:      w.Status.Phase,
			Stats:      stats,
			ObservedAt: now,
		}, true
	}
}

// terminalOutcome works out whether a stopped workload finished or failed.
//
// An ephemeral runner exiting after one job is the normal, successful end of
// life and by far the commonest event in the system, so it must never be
// reported as a failure -- an operator who sees "failed" for every completed
// job stops reading the fleet's health at all.
func terminalOutcome(r tracked, s backend.Status) (store.RunnerState, string, store.FaultKind) {
	switch {
	case s.Phase == backend.PhaseExitUnknown:
		// Removed describes the runner's lifecycle, not its job's outcome.
		// GitHub remains authoritative about whether the job succeeded.
		return store.RunnerRemoved, "runner process exited; its exit status is unknown after an agent restart; check the job's GitHub outcome", ""
	case s.ExitCode == 0 && s.OOMKilled:
		// The runner finished, and the daemon says the kernel killed
		// something in it for memory on the way: a step's process, which the
		// job then failed on like any test. The lifecycle is a clean end; the
		// fault is what lets the controller put it on the job.
		return store.RunnerRemoved, "runner exited after its job, but the kernel killed a process in it for its memory limit", store.FaultOutOfMemory
	case s.ExitCode == 0:
		if r.ephemeral {
			return store.RunnerRemoved, "ephemeral runner exited cleanly after its job", ""
		}
		return store.RunnerRemoved, "runner exited cleanly", ""
	case r.stopping:
		// Zoomies asked this workload to stop, so the non-zero code is the
		// backend's kill, not the job's.
		return store.RunnerRemoved, fmt.Sprintf("runner was stopped by the controller and exited with code %d", s.ExitCode), ""
	default:
		msg := fmt.Sprintf("runner exited with code %d", s.ExitCode)
		if s.Message != "" {
			msg += ": " + s.Message
		} else if hint := entrypointExitHint(s.ExitCode); hint != "" {
			msg += ": " + hint
		}
		fault := exitFault(s.ExitCode)
		if s.OOMKilled {
			fault = store.FaultOutOfMemory
		}
		return store.RunnerFailed, msg, fault
	}
}

// exitFault categorises a runner's exit code.
//
// The codes carry real information and this is the only place holding it: 137
// is the kernel's OOM killer via the daemon, and the entrypoint's reserved
// sysexits codes each name a reason the runner never took a job at all. The
// controller sees only the sentence these produce, by which point the code is
// gone.
//
// Anything else is FaultRunnerExited on purpose. A code we have no meaning for
// is a runner that stopped for a reason nobody here observed, and inventing a
// category would send an operator to fix something that is not broken.
func exitFault(code int) store.FaultKind {
	switch code {
	case 137:
		// 128+SIGKILL. The commonest cause by a distance is the memory limit;
		// the message carries the daemon's own words where it had any, so an
		// operator reading "out of memory" against a kill that was not one
		// still has the sentence that says so.
		return store.FaultOutOfMemory
	case 7:
		// actions/runner refuses jobs when its version is no longer supported.
		return store.FaultConfig
	case 64:
		// EX_USAGE: started with no credentials, so it could not register.
		return store.FaultRegistration
	case 69:
		// EX_UNAVAILABLE: the pool's Docker daemon never became ready.
		return store.FaultBackend
	case 78:
		// EX_CONFIG: the entrypoint refused its configuration.
		return store.FaultConfig
	}
	return store.FaultRunnerExited
}

// entrypointExitHint says what a runner image's entrypoint meant by an exit
// code of its own. The codes are sysexits.h values the entrypoint reserves --
// separate from actions/runner exit codes -- and each one is a runner that never
// took a job, so the container's log is short and says exactly what was
// wrong. A bare "exited with code 69" sent operators to GitHub's job log
// instead, where there is nothing, because the runner never registered.
func entrypointExitHint(code int) string {
	switch code {
	case 7:
		return "GitHub rejected the runner version as outdated; update the pool's runner image or process runner version, and check its pull policy before retrying"
	case 64:
		return "the image was started with no credentials, so the entrypoint could not register a runner; read the container's log"
	case 69:
		return "the pool's Docker daemon never became ready, so the entrypoint refused to take a job it could not run; " +
			"read the container's log, and on a slow host raise runners.docker_wait on the Settings page to allow the daemon longer"
	case 78:
		return "the entrypoint refused its configuration; read the container's log for the setting it named"
	}
	return ""
}

// cleanUp deletes a finished runner's workload from the host once nothing needs
// it any more: the controller has been told how the runner ended, and the
// window an operator gets to read its output has passed.
//
// Nothing else does this. A clean exit is the normal end of an ephemeral
// runner's life, and the controller marks the row removed and moves on -- it
// has no reason to send a task for a runner it already considers gone. Left to
// that, every finished job would leave its container on the host for ever:
// the writable layer with the checkout in it, the runner's own log, and a
// docker-in-docker sidecar that is still running. A host that has been busy
// for a week would be a host with no disk left.
//
// The report gate is what keeps the exit code safe. A workload deleted before
// the controller has heard how it ended takes the code with it, and the row it
// belongs to would sit in idle or busy until the reconciler declared it
// vanished, with nothing to say why.
func (a *Agent) cleanUp(ctx context.Context, b backend.Backend, r tracked, w backend.Workload, now time.Time) (RunnerReport, bool) {
	if a.mutationsPaused.Load() {
		return RunnerReport{}, false
	}
	if !r.reported || now.Sub(r.terminalAt) < a.retention {
		return RunnerReport{}, false
	}
	if ctx.Err() != nil {
		// The agent is shutting down. A removal started now would hold the
		// shutdown for as long as the daemon takes; the workload will still
		// be there for the next agent to find.
		return RunnerReport{}, false
	}
	// A stop or remove task for this runner may be in flight. The task owns
	// the workload until it reports, and two removals racing over one
	// container is exactly what claim exists to prevent.
	if !a.claim(r.runnerID) {
		return RunnerReport{}, false
	}
	defer a.release(r.runnerID)

	// Shutdown must not cut a removal in half; the backend converges on a
	// retry, but a sidecar left behind by a cancelled context is a privileged
	// container running for nobody until the next pass.
	rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), RemoveTimeout)
	defer cancel()
	if err := removeRunnerWorkload(rctx, b, r.runnerID, w.Handle); err != nil {
		// A removal the daemon is still carrying out is not reported until
		// it has had removalSettle to finish; the next pass asks again.
		since, pending := a.removalPending(r.runnerID, err, now)
		if pending {
			a.log.Info("the daemon is still removing a finished runner's workload; checking again on the next pass",
				"runner", r.runnerID, "handle", w.Handle, "backend", r.kind, "removing_for", now.Sub(since), "error", err)
			return RunnerReport{}, false
		}
		if !since.IsZero() {
			err = stuckRemoval(now.Sub(since), err)
		}
		a.log.Warn("could not remove a finished runner's workload; it is still taking up disk on this host and will be retried",
			"runner", r.runnerID, "handle", w.Handle, "backend", r.kind, "error", err)
		return RunnerReport{RunnerID: r.runnerID, State: r.state, CleanupError: err.Error(), ObservedAt: now}, true
	}
	a.removalPending(r.runnerID, nil, now)
	a.mu.Lock()
	if tracked := a.runners[r.runnerID]; tracked != nil {
		tracked.hostRemoved = true
		tracked.phase = backend.PhaseGone
		tracked.observedAt = now
	}
	a.mu.Unlock()
	a.log.Info("removed a finished runner's workload from this host",
		"runner", r.runnerID, "name", r.name, "handle", w.Handle, "backend", r.kind,
		"state", r.state, "kept_for", now.Sub(r.terminalAt))
	return RunnerReport{RunnerID: r.runnerID, State: r.state, Phase: backend.PhaseGone, HostRemoved: true, ObservedAt: now}, true
}

// A missing parent container does not establish that its DinD sidecar is
// gone. Verify the managed inventory and remove only companions of this
// runner before reporting a positive host confirmation.
func removeRunnerWorkload(ctx context.Context, b backend.Backend, runnerID string, handle backend.Handle) error {
	if handle != "" {
		if err := b.Remove(ctx, handle); err != nil && !errors.Is(err, backend.ErrNotFound) {
			return err
		}
	}
	workloads, err := b.List(ctx)
	if err != nil {
		return fmt.Errorf("confirming removal of %s: %w", runnerID, err)
	}
	for _, w := range workloads {
		if w.RunnerID != runnerID {
			continue
		}
		if !w.Sidecar {
			return fmt.Errorf("runner workload %s is still present after removal", w.Handle)
		}
		if err := b.Remove(ctx, w.Handle); err != nil && !errors.Is(err, backend.ErrNotFound) {
			return fmt.Errorf("removing companion %s: %w", w.Handle, err)
		}
	}
	return nil
}

// markReported records that the controller has accepted a report carrying
// these runners' end of life, which is what makes their workloads eligible for
// removal. Only a terminal report counts: a live runner's report says nothing
// about how it ended, and a runner that finished after the report was
// assembled has not been reported yet.
func (a *Agent) markReported(reports []RunnerReport) {
	a.mu.Lock()
	defer a.mu.Unlock()
	for _, rep := range reports {
		if !rep.State.Terminal() {
			continue
		}
		if r, ok := a.runners[rep.RunnerID]; ok && r.terminal && r.state == rep.State {
			r.reported = true
			if rep.HostRemoved && r.hostRemoved {
				delete(a.runners, rep.RunnerID)
			}
		}
	}
}

// reapOrphan removes a managed workload that nothing claims, reporting whether
// it produced an observation worth sending.
//
// Two guards, because the failure mode of getting this wrong is deleting a
// working fleet:
//
//  1. the agent must have completed at least one task poll since start, so a
//     controller that is down (or a task queue that has not been read yet) can
//     never be mistaken for "nobody owns these runners";
//  2. the workload must have gone unclaimed for orphanGrace, so a create whose
//     task result is still in flight is not reaped out from under the
//     controller.
//
// Backend.List only returns workloads carrying the io.zoomies.managed label, so
// nothing an operator started by hand is ever a candidate.
func (a *Agent) reapOrphan(ctx context.Context, b backend.Backend, kind store.BackendKind, w backend.Workload, now time.Time) (RunnerReport, bool) {
	if a.mutationsPaused.Load() {
		return RunnerReport{}, false
	}
	if !a.polled.Load() {
		return RunnerReport{}, false
	}
	// A slow create is not tracked until it returns. In particular, its DinD
	// sidecar can appear long before the runner. Never race a lifecycle task
	// over those partially created resources.
	if w.RunnerID != "" {
		if !a.claim(w.RunnerID) {
			return RunnerReport{}, false
		}
		defer a.release(w.RunnerID)
	}
	first := a.markOrphan(w.Handle, now)
	if now.Sub(first) < orphanGrace {
		return RunnerReport{}, false
	}

	if ctx.Err() != nil {
		// The agent is shutting down, and a removal started now would hold
		// the shutdown for as long as the daemon takes. The orphan will still
		// be there for the next agent to find.
		return RunnerReport{}, false
	}
	// The budget cleanUp gives a removal, and for the same reasons: a
	// sidecar's DELETE is held until the daemon has finished it, and a
	// shutdown must not cut it in half.
	rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), RemoveTimeout)
	defer cancel()
	var err error
	if w.Sidecar || w.RunnerID == "" {
		err = b.Remove(rctx, w.Handle)
	} else {
		err = removeRunnerWorkload(rctx, b, w.RunnerID, w.Handle)
	}
	// The window is kept per runner, so one a remove task opened carries on
	// here once the heartbeat has released the runner; a workload with no
	// runner ID is kept by its handle.
	key := w.RunnerID
	if key == "" {
		key = "handle:" + string(w.Handle)
	}
	since, pending := a.removalPending(key, err, now)
	if pending {
		// Not a failure: the daemon is finishing a removal it has started.
		// The orphan record stays, so the next pass asks again.
		a.log.Info("the daemon is still removing an orphaned runner workload; checking again on the next pass",
			"backend", kind, "handle", w.Handle, "name", w.Name, "removing_for", now.Sub(since), "error", err)
		return RunnerReport{}, false
	}
	if !since.IsZero() {
		// Stuck, and this is the only place left that will say so. A runner
		// the controller removed while it was still up is released here by
		// the heartbeat, and the remove task that found its sidecar still
		// going answered pending, which recorded nothing on its row -- so
		// nothing on the controller will ever ask about it again.
		err = stuckRemoval(now.Sub(since), err)
		a.log.Warn("could not remove an orphaned runner workload; it is still consuming capacity on this host",
			"backend", kind, "handle", w.Handle, "name", w.Name, "error", err)
		if w.RunnerID == "" {
			return RunnerReport{}, false
		}
		// No state: the row is already terminal, and a cleanup error on a
		// terminal row is recorded without moving it -- which is also what
		// makes the controller send the remove again.
		return RunnerReport{RunnerID: w.RunnerID, CleanupError: err.Error(), ObservedAt: now}, true
	}
	if err != nil && !errors.Is(err, backend.ErrNotFound) {
		// Keep the orphan record so the next pass tries again rather than
		// restarting the grace period.
		a.log.Warn("could not remove an orphaned runner workload; it is still consuming capacity on this host",
			"backend", kind, "handle", w.Handle, "name", w.Name, "error", err)
		return RunnerReport{}, false
	}
	a.forgetOrphan(w.Handle)
	what := "runner workload"
	if w.Sidecar {
		what = "docker-in-docker sidecar"
	}
	a.log.Warn("removed an orphaned "+what+" left behind by an earlier agent",
		"backend", kind, "handle", w.Handle, "name", w.Name, "runner", w.RunnerID, "unclaimed_for", now.Sub(first))

	if w.RunnerID == "" {
		// Nothing to report: the workload carried no runner ID, so the
		// controller has no row to move.
		return RunnerReport{}, false
	}
	if w.Sidecar {
		// The sidecar's removal is not the runner's. Its runner container has
		// its own way of being declared gone, and reporting this one as the
		// runner would move a row on the strength of the wrong container.
		return RunnerReport{}, false
	}
	return RunnerReport{
		RunnerID:    w.RunnerID,
		State:       store.RunnerRemoved,
		Handle:      w.Handle,
		Phase:       backend.PhaseGone,
		HostRemoved: true,
		Message:     fmt.Sprintf("removed orphaned %s workload %s that no task claimed", kind, w.Name),
		ObservedAt:  now,
	}, true
}

// snapshot returns a copy of what the agent believes about one runner, so
// reconciliation can do I/O without holding the lock.
func (a *Agent) snapshot(runnerID string) (tracked, bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	r, ok := a.runners[runnerID]
	if !ok {
		return tracked{}, false
	}
	return *r, true
}

func (a *Agent) trackedRunners() []tracked {
	a.mu.Lock()
	defer a.mu.Unlock()
	out := make([]tracked, 0, len(a.runners))
	for _, r := range a.runners {
		out = append(out, *r)
	}
	return out
}

func (a *Agent) markRunning(runnerID string, w backend.Workload, stats backend.Stats, now time.Time) {
	a.mu.Lock()
	defer a.mu.Unlock()
	r, ok := a.runners[runnerID]
	if !ok {
		return
	}
	r.handle = w.Handle
	r.phase = w.Status.Phase
	// The stats loop owns r.stats; this observation may carry an older copy.
	r.observedAt = now
	if r.name == "" {
		r.name = w.Name
	}
	if r.phase == backend.PhaseRunning && r.state == store.RunnerRegistering {
		// The workload is up; whether GitHub has given it a job is not this
		// agent's call, so stop asserting a state at all from here on.
		r.state = ""
	}
}

func (a *Agent) markTerminal(runnerID string, state store.RunnerState, phase backend.Phase, exitCode int, msg string, fault store.FaultKind, now time.Time) {
	a.mu.Lock()
	defer a.mu.Unlock()
	r, ok := a.runners[runnerID]
	if !ok {
		return
	}
	r.state = state
	r.phase = phase
	r.exitCode = exitCode
	r.message = msg
	r.fault = fault
	r.observedAt = now
	if !r.terminal {
		r.terminalAt = now
	}
	r.terminal = true
}

// markOrphan records when an unclaimed workload was first seen and returns that
// time, which is how the grace period is measured.
func (a *Agent) markOrphan(h backend.Handle, now time.Time) time.Time {
	a.mu.Lock()
	defer a.mu.Unlock()
	if first, ok := a.orphans[h]; ok {
		return first
	}
	a.orphans[h] = now
	return now
}

func (a *Agent) forgetOrphan(h backend.Handle) {
	a.mu.Lock()
	delete(a.orphans, h)
	a.mu.Unlock()
}

