	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// An explicit gate keeps the first operation in flight without wall-clock
// sleeps. synctest.Wait proves the other goroutines have reached their waits.
type startupBackend struct {
	*fakeBackend
	entered chan string
	finish  chan error
}

func (b *startupBackend) CreateWithResult(ctx context.Context, spec backend.Spec) (backend.CreateResult, error) {
	b.entered <- spec.RunnerID
	if err := <-b.finish; err != nil {
		return backend.CreateResult{}, err
	}
	return b.fakeBackend.CreateWithResult(ctx, spec)
}

func (b *startupBackend) PrewarmImage(ctx context.Context, image string, policy store.PullPolicy) (string, error) {
	b.entered <- image
	if err := <-b.finish; err != nil {
		return "", err
	}
	return b.fakeBackend.PrewarmImage(ctx, image, policy)
}

func startupAgent(t *testing.T) (*Agent, *fakeTransport, *startupBackend) {
	t.Helper()
	a, tr, be, _ := newAgent(t, 4)
	b := &startupBackend{fakeBackend: be, entered: make(chan string, 8), finish: make(chan error, 8)}
	a.opts.Backends = backend.NewRegistry(b)
	return a, tr, b
}

func startupEntered(t *testing.T, b *startupBackend, want string) {
	t.Helper()
	select {
	case got := <-b.entered:
		if got != want {
			t.Fatalf("started %q, want %q", got, want)
		}
	default:
		t.Fatalf("%q did not start", want)
	}
}

func startupBlocked(t *testing.T, b *startupBackend) {
	t.Helper()
	select {
	case got := <-b.entered:
		t.Fatalf("%q started while this host's startup slot was occupied", got)
	default:
	}
}

func TestRunnerStartsAreSerialAcrossPoolsAndReleaseAfterFailure(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		a.dispatch(ctx, createTask("first", "run-first"))
		synctest.Wait()
		startupEntered(t, b, "run-first")

		second := createTask("second", "run-second")
		second.Spec.PoolID = "another-pool"
		a.dispatch(ctx, second)
		synctest.Wait()
		startupBlocked(t, b)
		b.finish <- errors.New("daemon refused the first start")
		synctest.Wait()
		startupEntered(t, b, "run-second")
		if res := <-tr.results; res.OK {
			t.Fatal("the first failure was not reported")
		}
		b.finish <- nil
		synctest.Wait()
		if res := <-tr.results; !res.OK {
			t.Fatalf("the next start failed: %+v", res)
		}
		a.tasks.Wait()
	})
}

func TestPrewarmingSharesTheStartupSlotButRemovalDoesNot(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx := context.Background()
		a.dispatch(ctx, Task{
			ID: "warm", Kind: TaskPrewarmImage, PoolID: "pool",
			Backend: store.BackendDocker, Image: "runner-image", PullPolicy: store.PullIfNotPresent,
		})
		synctest.Wait()
		startupEntered(t, b, "runner-image")
		a.dispatch(ctx, createTask("create", "new-runner"))
		a.dispatch(ctx, Task{ID: "remove", Kind: TaskRemoveRunner, RunnerID: "old-runner"})
		synctest.Wait()
		startupBlocked(t, b)
		select {
		case res := <-tr.results:
			if res.TaskID != "remove" || !res.OK {
				t.Fatalf("removal did not bypass startup: %+v", res)
			}
		default:
			t.Fatal("removal was blocked behind startup")
		}
		b.finish <- nil
		synctest.Wait()
		startupEntered(t, b, "new-runner")
		b.finish <- nil
		synctest.Wait()
		a.tasks.Wait()
	})
}

func TestDifferentHostsCanStartTogether(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, _, first := startupAgent(t)
		other, _, second := startupAgent(t)
		a.dispatch(context.Background(), createTask("first", "run-first"))
		other.dispatch(context.Background(), createTask("second", "run-second"))
		synctest.Wait()
		startupEntered(t, first, "run-first")
		startupEntered(t, second, "run-second")
		first.finish <- nil
		second.finish <- nil
		synctest.Wait()
		a.tasks.Wait()
		other.tasks.Wait()
	})
}

func TestShutdownCancelsWaitingStartsWithoutCallingTheBackend(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		a.dispatch(ctx, createTask("first", "run-first"))
		synctest.Wait()
		startupEntered(t, b, "run-first")
		a.dispatch(ctx, createTask("waiting", "run-waiting"))
		synctest.Wait()
		cancel()
		synctest.Wait()
		startupBlocked(t, b)
		if res := <-tr.results; res.TaskID != "waiting" || res.OK {
			t.Fatalf("waiting start was not cancelled: %+v", res)
		}
		b.finish <- nil
		synctest.Wait()
		if res := <-tr.results; res.TaskID != "first" || !res.OK {
			t.Fatalf("already-started work did not finish: %+v", res)
		}
		a.tasks.Wait()
	})
}

func TestQueuedCreateHonoursRemovalAndCordonBeforeStarting(t *testing.T) {
	for _, mode := range []string{"remove", "cordon"} {
		t.Run(mode, func(t *testing.T) {
			synctest.Test(t, func(t *testing.T) {
				a, tr, b := startupAgent(t)
				ctx := context.Background()
				a.dispatch(ctx, createTask("first", "run-first"))
				synctest.Wait()
				startupEntered(t, b, "run-first")
				a.dispatch(ctx, createTask("waiting", "run-waiting"))
				synctest.Wait()
				if mode == "remove" {
					a.dispatch(ctx, Task{ID: "remove", Kind: TaskRemoveRunner, RunnerID: "run-waiting"})
				} else {
					a.mu.Lock()
					a.cordoned = true
					a.mu.Unlock()
				}
				b.finish <- nil
				synctest.Wait()
				startupBlocked(t, b)
				a.tasks.Wait()
				seen := map[string]TaskResult{}
				for len(tr.results) > 0 {
					res := <-tr.results
					seen[res.TaskID] = res
				}
				res, ok := seen["waiting"]
				if !ok || res.OK != (mode == "remove") {
					t.Fatalf("unexpected queued create result: %+v", seen)
				}
				if mode == "remove" && !seen["remove"].OK {
					t.Fatalf("queued removal did not finish: %+v", seen)
				}
			})
		})
	}
}

func TestStaggeredPrewarmDoesNotHoldForegroundAndCancels(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		a, tr, b := startupAgent(t)
		a.opts.PrewarmJitter = time.Minute
		a.opts.RandomFloat64 = func() float64 { return 1 }
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		a.dispatch(ctx, Task{ID: "background", Kind: TaskPrewarmImage, PoolID: "pool", PullPolicy: store.PullIfNotPresent, Image: "background", Backend: store.BackendDocker})
		synctest.Wait()
		startupBlocked(t, b)
		a.dispatch(ctx, createTask("foreground", "runner"))
		synctest.Wait()
		startupEntered(t, b, "runner")
		b.finish <- nil
		synctest.Wait()
		if res := <-tr.results; !res.OK {
			t.Fatalf("foreground: %+v", res)
		}
		cancel()
		synctest.Wait()
		a.tasks.Wait()
		startupBlocked(t, b)
		if res := <-tr.results; res.OK {
			t.Fatal("cancelled prewarm reported success")
		}
	})
}

package agent

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
)

// ErrNotJoined reports that this host has no usable credentials yet. Callers
// distinguish it from a genuine failure so that "not joined" can be an
// instruction to the operator rather than a crash loop.
var ErrNotJoined = errors.New("agent: this host has not joined a controller")

// StateFile is the name of the credentials file inside the agent's work
// directory.
const StateFile = "agent.json"

// StatePath returns where an agent with this work directory keeps its
// credentials. It lives beside the runner scratch space so that an operator
// backing up or wiping one host touches exactly one directory.
func StatePath(workDir string) string { return filepath.Join(workDir, StateFile) }

// Load reads the credentials a previous Join persisted.
//
// The file holds a bearer token that speaks for the whole host, so a file any
// other local user can read is refused rather than used: on a shared build host
// that token is the interesting thing to steal. A missing or incomplete file is
// reported as ErrNotJoined.
func Load(path string) (Credentials, error) {
	info, err := os.Stat(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return Credentials{}, fmt.Errorf("%w: no credentials at %s; run `zoomies agent join <controller-url> --token <join-token>` on this host first: %w", ErrNotJoined, path, err)
		}
		return Credentials{}, fmt.Errorf("agent: reading credentials %s: %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return Credentials{}, fmt.Errorf("agent: %s is not a regular file; agent credentials must be a JSON file written by `zoomies agent join`", path)
	}
	// The mode bits are POSIX facts. Windows reports every writable file as
	// 0666 whatever its ACL says, so the check would refuse every credentials
	// file on the one platform where the bits mean nothing; there, the ACL
	// `zoomies agent join` sets on the directory is what keeps other accounts
	// out, and the check is skipped rather than made to lie.
	if perm := info.Mode().Perm(); runtime.GOOS != "windows" && perm&0o077 != 0 {
		return Credentials{}, fmt.Errorf("agent: refusing to read %s: it is mode %04o, so other users on this host can read this agent's token; run: chmod 600 %s", path, perm, path)
	}

	raw, err := os.ReadFile(path)
	if err != nil {
		return Credentials{}, fmt.Errorf("agent: reading credentials %s: %w", path, err)
	}
	var c Credentials
	if err := json.Unmarshal(raw, &c); err != nil {
		return Credentials{}, fmt.Errorf("agent: %s is not valid JSON; delete it and re-join this host with a fresh join token: %w", path, err)
	}
	if c.HostID == "" || c.AgentToken == "" {
		return Credentials{}, fmt.Errorf("%w: %s has no host ID or agent token; delete it and run `zoomies agent join <controller-url> --token <join-token>` again", ErrNotJoined, path)
	}
	if !c.Valid() {
		// A host ID and agent token with no tunnel address is not a file that
		// ever came whole out of Save: it was edited, truncated, or restored
		// from a backup that predates this host's private enrolment. There is
		// no address to recover locally -- the capability lives only in the
		// enrolment command the controller minted, which is single use and
		// already spent.
		return Credentials{}, fmt.Errorf("%w: %s has a host ID and agent token but no private connection address; mint a fresh enrolment command in the UI under Hosts -> Add a host and run it on this host", ErrNotJoined, path)
	}
	return c, nil
}

// syncFile and syncDir are how Save reaches the disk. They are variables only so
// a test can watch the order they are called in: a power cut cannot be staged,
// but the order is what makes the rename safe.
var (
	syncFile = func(f *os.File) error { return f.Sync() }
	syncDir  = func(dir string) error {
		d, err := os.Open(dir)
		if err != nil {
			return err
		}
		defer d.Close()
		return d.Sync()
	}
)

// Save persists credentials for the next run of the agent.
//
// The write is to a temporary file followed by a rename, because a half-written
// credentials file after a crash would look like a valid identity that the
// controller has never heard of, and the operator would have no way to tell
// that from a revoked one.
func Save(path string, c Credentials) error {
	if !c.Valid() {
		return errors.New("agent: refusing to save credentials without a host ID and agent token; the controller's join response was incomplete")
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("agent: creating agent state directory %s: %w", dir, err)
	}

	raw, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return fmt.Errorf("agent: encoding credentials for %s: %w", path, err)
	}
	raw = append(raw, '\n')

	tmp, err := os.CreateTemp(dir, ".agent-*.json")
	if err != nil {
		return fmt.Errorf("agent: creating a temporary file in %s: %w", dir, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) // no-op once the rename has succeeded

	if err := tmp.Chmod(0o600); err != nil {
		tmp.Close()
		return fmt.Errorf("agent: setting permissions on %s: %w", tmpName, err)
	}
	if _, err := tmp.Write(raw); err != nil {
		tmp.Close()
		return fmt.Errorf("agent: writing %s: %w", tmpName, err)
	}
	// A rename is only atomic against a crashed process. After a power cut the
	// filesystem may keep the new name and lose the data behind it, leaving an
	// empty agent.json for a token that is shown once and stored only as a hash.
	if err := syncFile(tmp); err != nil {
		tmp.Close()
		return fmt.Errorf("agent: syncing %s to disk: %w", tmpName, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("agent: closing %s: %w", tmpName, err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("agent: installing credentials at %s: %w", path, err)
	}
	// Best effort, and skipped where a directory cannot be opened for syncing
	// (Windows) or the filesystem refuses it: the rename has happened, and the
	// worst a lost directory entry does is leave the old file or none, which
	// Load reports as not joined rather than as garbage.
	if runtime.GOOS != "windows" {
		_ = syncDir(dir)
	}
	return nil
}

