// A viewer must not read admin-only documents out of the audit log.
//
// audit.read is a viewer action; users.read, tokens.read, joins.read and
// settings.read are all admin ones. Returning every row's before/after exactly
// as stored made the audit log a way around that split: a viewer who was
// refused GET /users could read a user's email, display name and OIDC subject
// out of the row that recorded the change to them.
//
// The row itself is not the problem and is not withheld. Who did what, to which
// thing, and when is what a viewer is given the audit log for; it is the
// document describing the thing that is admin-only.
func TestTheAuditLogDoesNotLetAViewerReadAdminOnlyDocuments(t *testing.T) {
	h := newHarness(t)
	_, adminCookie := h.user("root@example.com", store.RoleAdmin)

	created := h.do(request{method: http.MethodPost, path: "/api/v1/users", cookie: adminCookie,
		body: map[string]any{"username": "dana", "password": testPassword, "role": "operator",
			"email": "dana@example.com"}})
	created.mustStatus(t, http.StatusCreated, "create user")

	// The admin who can call GET /users still sees the whole row.
	asAdmin := h.do(request{method: http.MethodGet, path: "/api/v1/audit?target_kind=user", cookie: adminCookie})
	asAdmin.mustStatus(t, http.StatusOK, "audit as admin")
	if !strings.Contains(string(asAdmin.body), "dana@example.com") {
		t.Fatalf("an admin lost the document they are allowed to read:\n%s", string(asAdmin.body))
	}

	_, viewerCookie := h.user("watcher@example.com", store.RoleViewer)
	asViewer := h.do(request{method: http.MethodGet, path: "/api/v1/audit?target_kind=user", cookie: viewerCookie})
	asViewer.mustStatus(t, http.StatusOK, "audit as viewer")
	if strings.Contains(string(asViewer.body), "dana@example.com") {
		t.Errorf("a viewer read a user's email out of the audit log:\n%s", string(asViewer.body))
	}
	// The row is still there, or the viewer has lost the audit trail itself.
	if !strings.Contains(string(asViewer.body), "user.create") {
		t.Errorf("the viewer lost the row as well as the document:\n%s", string(asViewer.body))
	}

	// And the direct route is refused, which is the promise being kept.
	direct := h.do(request{method: http.MethodGet, path: "/api/v1/users", cookie: viewerCookie})
	if direct.status != http.StatusForbidden {
		t.Errorf("GET /users as viewer = %d, want 403", direct.status)
	}
}

// The join command has to install an agent that matches this controller.
//
// Unpinned, the installer resolves "latest", which is the newest published
// release rather than this build. A fleet whose controller had moved past that
// release enrolled every new host on an older agent, and the host arrived
// reading "Different build" for good: re-running the command changed nothing,
// because the version it asked for was the version already there. Where the
// older agent predates the machine measurement code it also arrives permanently
// "Size unknown", which no argument to the command could fix.
//
// Main is a published channel too. CI keeps a rolling dev binary beside the
// dev images, so a main-sha-* controller can enrol a host from the same channel
// instead of silently falling back to the newest release.
func TestJoinCommandPinsTheControllersOwnRelease(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	mint := func(t *testing.T) createJoinTokenResponse {
		t.Helper()
		created := h.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: cookie,
			body: map[string]any{"controller_url": "https://zoomies.internal:8443"}})
		created.mustStatus(t, http.StatusCreated, "create")
		var minted createJoinTokenResponse
		created.into(t, &minted)
		return minted
	}

	was := version.Version
	t.Cleanup(func() { version.Version = was })

	for _, tc := range []struct {
		name    string
		stamped string
		want    string
		tag     string
	}{
		{"a release tag", "1.0.0", "--version v1.0.0", "v1.0.0"},
		{"a tag with a v", "v1.0.0", "--version v1.0.0", "v1.0.0"},
		{"a prerelease", "0.2-beta", "--version v0.2-beta", "v0.2-beta"},
		{"main", "main-sha-117bc18", "--version dev", "dev"},
		{"an unstamped development build", "dev", "--version dev", "dev"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			version.Version = tc.stamped
			minted := mint(t)
			if !strings.Contains(minted.Command, tc.want) {
				t.Errorf("a controller stamped %q handed out a command without %q, so the host it enrols "+
					"will not match it:\n%s", tc.stamped, tc.want, minted.Command)
			}
			if minted.VersionNote != "" {
				t.Errorf("a pinned command still carried a note: %q", minted.VersionNote)
			}
			if minted.InstallTag != tc.tag {
				t.Errorf("install_tag = %q, want %q", minted.InstallTag, tc.tag)
			}
			if !strings.Contains(minted.ControllerVersion, tc.stamped) {
				t.Errorf("controller_version = %q, want it to name %q", minted.ControllerVersion, tc.stamped)
			}
		})
	}

	for _, stamped := range []string{"v0.2-beta-276-g394254b", "some-fork-build"} {
		t.Run("unreleased "+stamped, func(t *testing.T) {
			version.Version = stamped
			minted := mint(t)
			// No pin: there is no asset with this version, and a pin that 404s
			// is worse than an agent that merely differs.
			if strings.Contains(minted.Command, "--version") {
				t.Errorf("a controller stamped %q pinned a version that can never be downloaded:\n%s",
					stamped, minted.Command)
			}
			if minted.InstallTag != "" {
				t.Errorf("an unpublished build advertised install tag %q", minted.InstallTag)
			}
			// But it must not be silent about it.
			if minted.VersionNote == "" {
				t.Errorf("a controller stamped %q gave no reason for handing out an unpinned command; "+
					"the operator finds out when the host reads \"Different build\"", stamped)
			}
			if !strings.Contains(minted.VersionNote, stamped) {
				t.Errorf("the note does not name the build it is about: %q", minted.VersionNote)
			}
		})
	}
}

// The kill switch and the two ceilings are settings an operator reaches for
// while the fleet is misbehaving, which is the one moment nobody wants to
// restart the controller. Each is writable at runtime, and each takes effect in
// the running configuration rather than only in the response.
func TestTheMachineLimitsAreChangeableWithoutARestart(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	patched := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"provider": map[string]any{
			"paused":                true,
			"max_machines":          6,
			"max_creates_in_flight": 3,
			"idle_timeout":          "20m",
		}}})
	patched.mustStatus(t, http.StatusOK, "patch the provider limits")

	cfg := h.ctrl.Config()
	if !cfg.Provider.Paused {
		t.Error("the kill switch was not pressed in the running configuration")
	}
	if cfg.Provider.MaxMachines != 6 || cfg.Provider.MaxCreatesInFlight != 3 {
		t.Errorf("ceilings = %d and %d, want 6 and 3", cfg.Provider.MaxMachines, cfg.Provider.MaxCreatesInFlight)
	}
	if cfg.Provider.IdleTimeout.String() != "20m0s" {
		t.Errorf("provider.idle_timeout = %s, want 20m0s", cfg.Provider.IdleTimeout)
	}

	var after settingsResponse
	patched.into(t, &after)
	provider, _ := after.Config["provider"].(map[string]any)
	if provider["paused"] != true || provider["max_machines"] != float64(6) {
		t.Errorf("the response does not show the change: %v", provider)
	}
	// No provider credential is ever in this document. The endpoints and tokens
	// are rows, sealed, and this is readable by an administrator and copied
	// verbatim into a diagnostics bundle.
	for key := range provider {
		if strings.Contains(key, "credential") || strings.Contains(key, "token") || strings.Contains(key, "secret") {
			t.Errorf("the settings document carries %q", key)
		}
	}
}

// A boolean setting accepts what both clients send: JSON's own true and false,
// and the string a form field produces before anything has parsed it. Anything
// else is refused by field, rather than being read as false and quietly leaving
// the fleet provisioning.
func TestTheKillSwitchAcceptsABooleanOrTheWordForIt(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	for _, tc := range []struct {
		name string
		send any
		want bool
	}{
		{"a JSON boolean", true, true},
		{"the word", "false", false},
		{"the word again", "true", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			res := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
				body: map[string]any{"provider.paused": tc.send}})
			res.mustStatus(t, http.StatusOK, "patch provider.paused")
			if got := h.ctrl.Config().Provider.Paused; got != tc.want {
				t.Errorf("provider.paused = %v, want %v", got, tc.want)
			}
		})
	}

	refused := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"provider.paused": "maybe"}})
	refused.mustStatus(t, http.StatusUnprocessableEntity, "patch provider.paused with nonsense")
	var env errorEnvelope
	refused.into(t, &env)
	if len(env.Errors) == 0 || env.Errors[0].Field != "provider.paused" {
		t.Fatalf("expected a field error on provider.paused: %+v", env)
	}
}

// A ceiling of zero rents nothing, so it is a legal value and must not be
// refused -- but a negative one is nonsense, and saying so names the value that
// means "none" rather than leaving an operator to guess.
func TestAMachineCeilingMayBeZeroButNotNegative(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	ok := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"provider.max_machines": 0}})
	ok.mustStatus(t, http.StatusOK, "patch provider.max_machines to zero")
	if h.ctrl.Config().Provider.MaxMachines != 0 {
		t.Error("a ceiling of none was not applied")
	}

	bad := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"provider.max_machines": -1}})
	bad.mustStatus(t, http.StatusUnprocessableEntity, "patch provider.max_machines to a negative")
	var env errorEnvelope
	bad.into(t, &env)
	if len(env.Errors) == 0 || !strings.Contains(env.Errors[0].Message, "negative") {
		t.Fatalf("the refusal does not say what is wrong: %+v", env)
	}
}

// The bounds a restart has to honour are still named as such, and the UI renders
// them from that list rather than discovering one at a time by being refused.
//
// What changed with settings moving into the database is what happens when one
// is sent anyway: it is stored and reported as waiting, not refused. A deadline
// bounds an operation that may already be in flight, so a running controller
// cannot adopt a new one without two passes disagreeing about when to give up on
// a half-built machine -- but wanting it changed is not a mistake, and making an
// operator edit a file and restart to express that was never the safety, only
// the friction.
func TestTheProviderDeadlinesNeedARestart(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	res := h.do(request{method: http.MethodGet, path: "/api/v1/settings", cookie: cookie})
	res.mustStatus(t, http.StatusOK, "settings")
	var settings settingsResponse
	res.into(t, &settings)
	for _, key := range []string{"provider.enabled", "provider.create_timeout", "provider.ambiguity_timeout"} {
		if !slices.Contains(settings.RestartRequiredKeys, key) {
			t.Errorf("%s is neither writable at runtime nor listed as needing a restart", key)
		}
	}

	stored := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"provider.create_timeout": "5m"}})
	stored.mustStatus(t, http.StatusOK, "patch a restart-only provider setting")

	var after settingsResponse
	stored.into(t, &after)
	if !slices.Contains(after.PendingRestart, "provider.create_timeout") {
		t.Errorf("it was stored but is not reported as waiting: %v", after.PendingRestart)
	}
	// The running controller is untouched, which is the half that matters: a
	// machine already being built keeps the deadline it was given.
	if got := h.ctrl.Config().Provider.CreateTimeout.String(); got == "5m0s" {
		t.Error("a deadline was changed under an operation already in flight")
	}
}

// findSetting picks one key out of a settings response, so a test can assert
// about the metadata the UI draws its editors from.
func findSetting(t *testing.T, res settingsResponse, key string) settingView {
	t.Helper()
	for _, v := range res.Settings {
		if v.Key == key {
			return v
		}
	}
	t.Fatalf("%s is not in the settings response", key)
	return settingView{}
}

// A stored value that will not parse is reported on the page it is about.
//
// config.Validate cannot produce these: it works on an in-memory snapshot and
// has never seen the rows. Printing them once at startup and dropping them left
// the one page where each is actionable as the one place it did not appear.
func TestAStoredRowThatCannotBeUsedIsReportedOnTheSettingsPage(t *testing.T) {
	h := newHarness(t)
	// Platform: this exercises keys on both sides of the audience split,
	// and its subject is the behaviour, not who may reach it.
	admin, _ := h.user("root", store.RolePlatform)
	cookie := h.session(admin)

	// Written straight to the store, because the API would have refused it --
	// which is exactly how such a row arrives in practice: from a different
	// version, or a hand-edited database.
	if err := h.ctrl.Store().PutInstanceSettings(t.Context(), "a newer version", []store.InstanceSetting{
		{Key: "retention.jobs", Value: "forever"},
		{Key: "a.setting.from.the.future", Value: "1"},
	}); err != nil {
		t.Fatalf("PutInstanceSettings: %v", err)
	}

	res := h.do(request{method: http.MethodGet, path: "/api/v1/settings", cookie: cookie})
	res.mustStatus(t, http.StatusOK, "settings")
	var settings settingsResponse
	res.into(t, &settings)

	codes := map[string]bool{}
	for _, f := range settings.Findings {
		codes[f.Code] = true
	}
	if !codes["settings.stored_invalid"] {
		t.Errorf("a stored value that will not parse is invisible on the settings page: %v", codes)
	}
	if !codes["settings.stored_unknown"] {
		t.Errorf("a key this version does not have is invisible on the settings page: %v", codes)
	}
	// And the setting itself still shows what the controller is actually
	// running, which is the value underneath the unusable row.
	if view := findSetting(t, settings, "retention.jobs"); view.Value == "forever" {
		t.Error("the page shows a value the controller is not using")
	}
}

// A join token that names no capacity leaves the figure to the agent, which
// is the only party in the exchange that has seen the machine.
//
// It used to default to two. That pinned every host enrolled without an
// explicit figure to two slots however large it was -- and under automatic
// sizing the capacity is no longer only a slot count but the divisor that
// gives each runner its CPU and memory, so two slots on a thirty-two core box
// is half the machine per runner and two jobs at a time.
func TestAJoinTokenWithNoCapacityLeavesItToTheAgent(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	created := h.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: cookie,
		body: map[string]any{"ttl": "1h"}})
	created.mustStatus(t, http.StatusCreated, "create join token")
	var token createJoinTokenResponse
	created.into(t, &token)
	if token.Capacity != 0 {
		t.Errorf("capacity = %d, want 0: the agent decides from the machine it measures", token.Capacity)
	}

	// A figure the operator did name is still theirs, and still wins over the
	// agent's own derivation.
	named := h.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: cookie,
		body: map[string]any{"ttl": "1h", "capacity": 12}})
	named.mustStatus(t, http.StatusCreated, "create with a capacity")
	var pinned createJoinTokenResponse
	named.into(t, &pinned)
	if pinned.Capacity != 12 {
		t.Errorf("capacity = %d, want the 12 the operator asked for", pinned.Capacity)
	}
}

package api

import (
	"net/http"
	"strconv"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
)

// A host over its budget is told so with a status its transport already
// retries, a wait it can honour, and a message and code a person can act on --
// on each of the three routes the budget covers, and before the body is read.
func TestAHostOverItsCallBudgetIsAnswered429WithRetryAfter(t *testing.T) {
	routes := []struct {
		name string
		path string
		body any
	}{
		{"heartbeat", agent.PathHeartbeat, agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}},
		{"results", agent.PathResults, agent.TaskResult{TaskID: "tsk_nosuchtask"}},
		{"report", agent.PathReport, []agent.RunnerReport{}},
	}
	for _, rt := range routes {
		t.Run(rt.name, func(t *testing.T) {
			h := newHarness(t)
			hostID, token := h.agentToken("vm-noisy")
			for i := 0; ; i++ {
				if ok, _ := h.ctrl.AllowAgentCall(hostID); !ok {
					break
				}
				if i > 100_000 {
					t.Fatal("a host was never refused however many calls it made")
				}
			}
			resp := h.do(request{method: http.MethodPost, path: rt.path, token: token, body: rt.body})
			resp.mustStatus(t, http.StatusTooManyRequests, rt.name+" over budget")
			if code := resp.errorCode(t); code != codeRateLimited {
				t.Errorf("error code = %q, want %q", code, codeRateLimited)
			}
			if secs, err := strconv.Atoi(resp.header.Get("Retry-After")); err != nil || secs < 1 {
				t.Errorf("Retry-After = %q, want a whole number of seconds", resp.header.Get("Retry-After"))
			}
			if resp.errorMessage(t) == "" {
				t.Error("the refusal carried no message for the operator")
			}

			// Another host is not held to this one's budget.
			_, other := h.agentToken("vm-quiet")
			h.do(request{method: http.MethodPost, path: rt.path, token: other, body: rt.body}).
				mustStatus(t, statusFor(rt.name), rt.name+" from another host")
		})
	}
}

// statusFor is what each budgeted route answers the smallest body it accepts.
func statusFor(route string) int {
	if route == "heartbeat" {
		return http.StatusOK
	}
	return http.StatusNoContent
}

// The runner cap reaches the agent as a 413, the status the body limit already
// uses, rather than a 500 that reads as the controller's own failure.
func TestAReportCarryingMoreRunnersThanTheCapIsAnswered413(t *testing.T) {
	h := newHarness(t)
	_, token := h.agentToken("vm-1")
	tooMany := make([]agent.RunnerReport, agent.MaxRunnersPerReport+1)

	for _, c := range []struct {
		name string
		path string
		body any
	}{
		{"report", agent.PathReport, tooMany},
		{"heartbeat", agent.PathHeartbeat, agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Runners: tooMany}},
	} {
		resp := h.do(request{method: http.MethodPost, path: c.path, token: token, body: c.body})
		resp.mustStatus(t, http.StatusRequestEntityTooLarge, c.name)
		if code := resp.errorCode(t); code != codeTooLarge {
			t.Errorf("%s: error code = %q, want %q", c.name, code, codeTooLarge)
		}
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
)

// The session travels as a header rather than a body field, so that one place
// -- the agent middleware every authenticated agent request already passes
// through -- sees it, instead of three request shapes changing. This is the
// test that the wire actually carries it: the store rule and the problem are
// both tested on their own, and neither would notice a header nobody reads.
func TestAnAgentsSessionHeaderReachesTheHostRow(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("vm-1")

	beat := func(session string) {
		t.Helper()
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
			headers: map[string]string{agent.HeaderAgentSession: session},
			body:    agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}})
		resp.mustStatus(t, http.StatusOK, "heartbeat")
	}

	beat("ses_one")
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.AgentSessionID != "ses_one" {
		t.Fatalf("agent_session_id = %q, want the session the header carried", host.AgentSessionID)
	}

	// Forward once is a restart; back again is the duplicate.
	beat("ses_two")
	beat("ses_one")
	host, err = h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.AgentSessionAlternations != 1 {
		t.Fatalf("alternations = %d, want 1 after the sessions swapped back", host.AgentSessionAlternations)
	}
}

// A huge session value is dropped before it reaches the hosts row, so a
// misbehaving agent that holds a token cannot keep bloating the database by
// alternating two very long strings.
func TestAnOversizedAgentSessionHeaderIsNotRecorded(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("vm-1")

	oversize := "ses_" + strings.Repeat("a", maxAgentSessionBytes)
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
		headers: map[string]string{agent.HeaderAgentSession: oversize},
		body:    agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}})
	resp.mustStatus(t, http.StatusOK, "a heartbeat with an oversized session header")

	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.AgentSessionID != "" {
		t.Fatalf("agent_session_id = %q, want empty for a header past the %d-byte cap", host.AgentSessionID, maxAgentSessionBytes)
	}
}

// An agent from before the header sends nothing, and must keep working: a
// controller upgraded ahead of its agents is the normal state during a rolling
// upgrade.
func TestAnAgentThatSendsNoSessionIsStillServed(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("vm-1")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
		body: agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}})
	resp.mustStatus(t, http.StatusOK, "a heartbeat with no session header")

	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.AgentSessionID != "" || host.AgentSessionAlternations != 0 {
		t.Fatalf("host = %+v, want no session recorded for an agent that sent none", host)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// agentRoute is one of the five routes behind s.agentAuth. The bodies are the
// smallest thing each handler will accept, because what is under test is the
// middleware in front of them and not the handler's own validation.
type agentRoute struct {
	name   string
	method string
	path   string
	body   any
	// raw is the log relay's body, which is a byte stream rather than JSON.
	raw string
}

// agentRoutes is written out by hand rather than read off the router for the
// same reason routeTable is: a list derived from the thing it checks would
// agree with a mistake. Its length is asserted against the router below.
func agentRoutesUnderTest() []agentRoute {
	return []agentRoute{
		{name: "heartbeat", method: http.MethodPost, path: "/api/v1/agent/heartbeat",
			body: agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}},
		// The long poll is given the shortest wait it will honour, so a
		// refused call costs nothing and an accepted one returns promptly.
		{name: "tasks", method: http.MethodGet, path: "/api/v1/agent/tasks?wait=1"},
		{name: "results", method: http.MethodPost, path: "/api/v1/agent/results",
			body: agent.TaskResult{TaskID: "tsk_nosuchtask"}},
		{name: "report", method: http.MethodPost, path: "/api/v1/agent/report",
			body: []agent.RunnerReport{}},
		{name: "logs", method: http.MethodPost, path: "/api/v1/agent/logs/log_nosuchstream",
			raw: "chunk"},
	}
}

// TestAgentRoutesRefuseAUserCredential is the separation the whole agent
// surface rests on: an agent token reaches /api/v1/agent/* and nothing else,
// and a user token does not reach the agent routes at all.
//
// It walks all five authenticated agent routes. The earlier version of this
// test walked three, which left the task poll and the log relay -- the two
// that carry a runner's work and a runner's output -- with no negative test
// at all.
func TestAgentRoutesRefuseAUserCredential(t *testing.T) {
	h := newHarness(t)
	adminToken := h.token("admin", store.RoleAdmin)
	admin, _ := h.user("root", store.RoleAdmin)
	adminCookie := h.session(admin)
	_, agentToken := h.agentToken("vm-1")

	callers := []struct {
		name  string
		apply func(*request)
	}{
		{"anonymous", func(*request) {}},
		{"an admin API token", func(r *request) { r.token = adminToken }},
		{"an admin browser session", func(r *request) { r.cookie = adminCookie }},
		{"a made-up bearer", func(r *request) { r.token = "zag_notarealtokenatall" }},
	}

	for _, rt := range agentRoutesUnderTest() {
		for _, caller := range callers {
			t.Run(rt.name+"/"+caller.name, func(t *testing.T) {
				req := request{method: rt.method, path: rt.path, body: rt.body, rawBody: rt.raw}
				caller.apply(&req)
				resp := h.do(req)
				resp.mustStatus(t, http.StatusUnauthorized, caller.name+" on "+rt.path)
			})
		}

		// The positive half of the same walk: the host's own token is not
		// refused anywhere, which is what makes the four refusals above about
		// the credential rather than about the route being broken.
		t.Run(rt.name+"/its own agent token", func(t *testing.T) {
			resp := h.do(request{method: rt.method, path: rt.path, body: rt.body,
				rawBody: rt.raw, token: agentToken})
			if resp.status == http.StatusUnauthorized {
				t.Fatalf("the host's own agent token was refused on %s: %s", rt.path, truncate(resp.body))
			}
		})
	}

	// And the agent's own credential is refused on the user API.
	onUserAPI := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: agentToken})
	onUserAPI.mustStatus(t, http.StatusUnauthorized, "agent token on the user API")
	if !strings.Contains(onUserAPI.errorMessage(t), "agent token") {
		t.Errorf("the refusal does not say what kind of credential it was: %q", onUserAPI.errorMessage(t))
	}
}

// TestAgentRoutesUnderTestCoverTheRouter keeps the walk above honest: a sixth
// authenticated agent route added without a row here would otherwise ship with
// no negative test, which is exactly how tasks and logs came to be missing.
func TestAgentRoutesUnderTestCoverTheRouter(t *testing.T) {
	// PathJoin is deliberately absent: it is the one anonymous agent route,
	// and it is walked by TestAgentJoinRefusesASpentToken instead.
	want := map[string]bool{
		agent.PathHeartbeat: false,
		agent.PathTasks:     false,
		agent.PathResults:   false,
		agent.PathReport:    false,
		agent.PathLogs:      false,
	}
	for _, rt := range agentRoutesUnderTest() {
		path, _, _ := strings.Cut(rt.path, "?")
		matched := false
		for known := range want {
			if path == known || strings.HasPrefix(path, known+"/") {
				want[known] = true
				matched = true
				break
			}
		}
		if !matched {
			t.Errorf("%s is not one of the agent paths the transport declares", rt.path)
		}
	}
	for path, covered := range want {
		if !covered {
			t.Errorf("%s has no row in agentRoutesUnderTest, so nothing proves it refuses a user credential", path)
		}
	}
}

// TestADeletedHostsAgentTokenIsRefused covers revocation on the agent side.
//
// A host's token hash lives on the host row, so removing the host is how an
// operator revokes a machine's access to the fleet. Every agent route has to
// honour that, not only the heartbeat that happens to notice first.
func TestADeletedHostsAgentTokenIsRefused(t *testing.T) {
	h := newHarness(t)
	hostID, agentToken := h.agentToken("vm-doomed")

	if _, err := h.st.DeleteHost(h.ctx, hostID); err != nil {
		t.Fatalf("DeleteHost: %v", err)
	}

	for _, rt := range agentRoutesUnderTest() {
		t.Run(rt.name, func(t *testing.T) {
			resp := h.do(request{method: rt.method, path: rt.path, body: rt.body,
				rawBody: rt.raw, token: agentToken})
			resp.mustStatus(t, http.StatusUnauthorized, "a deleted host's token on "+rt.path)
			// The message has to name the fix, because the agent operator is
			// the only person who can carry it out.
			if !strings.Contains(resp.errorMessage(t), "re-join") {
				t.Errorf("the refusal does not tell the operator to re-join: %q", resp.errorMessage(t))
			}
		})
	}
}

// TestAgentJoinAndHeartbeat covers enrolment and the liveness beat, including
// the 404 an agent's transport turns into "re-join me".
func TestAgentJoinAndHeartbeat(t *testing.T) {
	h := newHarness(t)
	hostID, token := h.agentToken("vm-1")

	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.Name != "vm-1" || host.Capacity != 2 {
		t.Fatalf("the join did not record the host as described: %+v", host)
	}
	if len(host.Backends) != 1 || host.Backends[0] != "docker" {
		t.Errorf("backends = %v, want [docker]", host.Backends)
	}

	beat := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
		body: agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2, Version: "test"}})
	beat.mustStatus(t, http.StatusOK, "heartbeat")
	var resp agent.HeartbeatResponse
	beat.into(t, &resp)
	if !resp.OK {
		t.Errorf("heartbeat response = %+v", resp)
	}

	// A host deleted under a running agent must answer 404, not 500: the
	// agent's transport reads that specific status as "you no longer exist".
	if _, err := h.st.DeleteHost(h.ctx, hostID); err != nil {
		t.Fatalf("DeleteHost: %v", err)
	}
	gone := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
		body: agent.HeartbeatRequest{ProtocolVersion: 1, Capacity: 2}})
	// The token went with the row, so this is refused before the handler runs;
	// either answer tells the agent to stop, and 401 is the stronger of the two.
	if gone.status != http.StatusUnauthorized && gone.status != http.StatusNotFound {
		t.Fatalf("heartbeat after the host was deleted answered %d, want 401 or 404", gone.status)
	}
}

func TestAgentJoinRefusesASpentToken(t *testing.T) {
	h := newHarness(t)
	_, plaintext, err := h.ctrl.Auth().CreateJoinToken(h.ctx, time.Hour, nil, 2, "test")
	if err != nil {
		t.Fatalf("CreateJoinToken: %v", err)
	}
	body := map[string]any{
		"protocol_version": 1, "join_token": plaintext, "name": "vm-1",
		"capacity": 2, "os": "linux", "arch": "amd64", "version": "test",
	}

	first := h.do(request{method: http.MethodPost, path: "/api/v1/agent/join", body: body})
	first.mustStatus(t, http.StatusOK, "first join")

	body["name"] = "vm-2"
	second := h.do(request{method: http.MethodPost, path: "/api/v1/agent/join", body: body})
	second.mustStatus(t, http.StatusUnprocessableEntity, "second join with the same token")
	if !strings.Contains(second.errorMessage(t), "join token") {
		t.Errorf("the refusal does not name the problem: %q", second.errorMessage(t))
	}
}

// TestAgentTaskPollAndResult walks a task from the queue to its outcome.
func TestAgentTaskPollAndResult(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	hostID, token := h.agentToken("vm-1")
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	run := h.runner(pool, host, store.RunnerIdle)

	// An empty long poll returns quickly when asked to wait a second, which is
	// the idle case; nothing is queued yet.
	idle := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=1", token: token})
	idle.mustStatus(t, http.StatusOK, "idle poll")
	var empty agent.TaskBatch
	idle.into(t, &empty)
	if len(empty.Tasks) != 0 {
		t.Fatalf("an idle poll returned %d tasks", len(empty.Tasks))
	}

	// Draining the runner queues a stop task for its host.
	u, _ := h.user("operator", store.RoleOperator)
	drain := h.do(request{method: http.MethodPost, path: "/api/v1/runners/" + run.ID + "/drain", cookie: h.session(u)})
	drain.mustStatus(t, http.StatusAccepted, "drain")

	poll := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=2", token: token})
	poll.mustStatus(t, http.StatusOK, "task poll")
	var batch agent.TaskBatch
	poll.into(t, &batch)
	if len(batch.Tasks) == 0 {
		t.Fatal("the drain queued no task for the agent")
	}
	task := batch.Tasks[0]
	if task.Kind != agent.TaskStopRunner || task.RunnerID != run.ID {
		t.Fatalf("task = %+v, want a stop for %s", task, run.ID)
	}

	result := h.do(request{method: http.MethodPost, path: "/api/v1/agent/results", token: token,
		body: agent.TaskResult{TaskID: task.ID, RunnerID: run.ID, OK: true, CompletedAt: time.Now()}})
	result.mustStatus(t, http.StatusNoContent, "task result")
}

// TestAgentReportTakesABareArray keeps the two halves of the protocol agreeing
// about the wire format: the agent sends []RunnerReport, not an object.
func TestAgentReportTakesABareArray(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	hostID, token := h.agentToken("vm-1")
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	run := h.runner(pool, host, store.RunnerProvisioning)

	reports := []agent.RunnerReport{{
		RunnerID: run.ID, State: store.RunnerRegistering, ObservedAt: time.Now(),
	}}
	raw, err := json.Marshal(reports)
	if err != nil {
		t.Fatalf("marshalling reports: %v", err)
	}
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/agent/report", token: token,
		rawBody: string(raw), headers: map[string]string{"Content-Type": "application/json"}})
	resp.mustStatus(t, http.StatusNoContent, "runner report")

	after, err := h.st.GetRunner(h.ctx, run.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if after.State != store.RunnerRegistering {
		t.Errorf("state = %q after the report, want registering", after.State)
	}
}

// TestAgentLogPostForAnUnknownStream is the ordinary case of a viewer who
// closed the tab: the relay is gone and the agent is told to stop.
func TestAgentLogPostForAnUnknownStream(t *testing.T) {
	h := newHarness(t)
	_, token := h.agentToken("vm-1")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/agent/logs/log_nobody", token: token,
		rawBody: "some output", headers: map[string]string{"Content-Type": "application/octet-stream"}})
	resp.mustStatus(t, http.StatusNotFound, "log post for an unknown stream")
}

// The two halves of the agent protocol are the same binary at different
// versions while an upgrade rolls across a fleet. A newer agent that adds one
// optional field to its heartbeat used to be answered 400 by an older
// controller, and stopped heartbeating -- every host unhealthy at once, for a
// change ProtocolVersion was never meant to cover.
func TestAgentRoutesTolerateFieldsTheyDoNotKnow(t *testing.T) {
	h := newHarness(t)
	_, token := h.agentToken("vm-1")

	beat := h.do(request{method: http.MethodPost, path: "/api/v1/agent/heartbeat", token: token,
		body: map[string]any{"protocol_version": 1, "capacity": 2, "version": "test", "load_average": 0.42}})
	beat.mustStatus(t, http.StatusOK, "a heartbeat carrying a field this controller does not know")

	// The user API keeps its strictness: there the unknown field is a typo
	// that would otherwise be silently ignored.
	admin, _ := h.user("root", store.RoleAdmin)
	typo := h.do(request{method: http.MethodPost, path: "/api/v1/users", cookie: h.session(admin),
		body: map[string]any{"username": "sam", "password": "correct-horse-battery", "rolle": "viewer"}})
	typo.mustStatus(t, http.StatusBadRequest, "a typo in a user API field")
}

// TestAgentJoinIsRateLimited closes the last unauthenticated route that says
// whether the credential it was handed was right.
//
// A join token is a bearer credential with nothing else in front of it, so
// without a limit a guess costs an attacker one request and the only thing
// standing in the way is the token's entropy. A machine joins once, so a limit
// generous enough that no operator ever meets it still costs every attempt.
func TestAgentJoinIsRateLimited(t *testing.T) {
	// One attempt, so the second is refused and the test does not depend on
	// the shipped default.
	h := newHarness(t, func(c *config.Config) { c.Security.RateLimitLogins = 1 })

	body := map[string]any{
		"protocol_version": 1, "join_token": "zjoin_a_guess", "name": "vm-guess",
		"capacity": 1, "os": "linux", "arch": "amd64", "version": "test",
	}

	first := h.do(request{method: http.MethodPost, path: "/api/v1/agent/join", body: body})
	if first.status == http.StatusTooManyRequests {
		t.Fatalf("the first attempt was rate limited: %s", truncate(first.body))
	}

	second := h.do(request{method: http.MethodPost, path: "/api/v1/agent/join", body: body})
	second.mustStatus(t, http.StatusTooManyRequests, "a second join attempt from the same address")
	if second.header.Get("Retry-After") == "" {
		t.Error("the refusal carries no Retry-After, so an agent's backoff has nothing to read")
	}

	// The limiter is the join route's own. An attacker hammering enrolment
	// must not be able to lock the operators out of the page they would use to
	// stop it, which sharing the login counter would do.
	admin, _ := h.user("root", store.RoleAdmin)
	_ = admin
	login := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "root", "password": testPassword}})
	login.mustStatus(t, http.StatusOK, "signing in while enrolment is rate limited")
}

