		t.Fatal(err)
	}
	draft, err := h.ctrl.CreateAIContextDraft(h.ctx, controller.AIContextDraftRequest{InstallationID: inst.ID, RepositoryID: discovery.Repositories[0].ID})
	if err != nil {
		t.Fatal(err)
	}
