// TestRouteAuthorisation walks every route with five callers.
//
// This is the test that catches an endpoint added without a role: an
// unauthenticated request must be refused, a viewer must not be able to
// write, and each role in turn must get through to exactly the handlers its
// authority reaches. The platform caller is the fifth, and the rows it alone
// may reach -- the fence and the backups -- are the ones that would otherwise
// silently fall back to an administrator.
func TestRouteAuthorisation(t *testing.T) {
	h := newHarness(t)
	ids := h.fixtures()

	viewer, _ := h.user("viewer", store.RoleViewer)
	operator, _ := h.user("operator", store.RoleOperator)
	admin, _ := h.user("admin", store.RoleAdmin)
	platform, _ := h.user("platform", store.RolePlatform)

	callers := []struct {
		name string
		role store.Role
		user *store.User
	}{
		{name: "anonymous"},
		{name: "viewer", role: store.RoleViewer, user: viewer},
		{name: "operator", role: store.RoleOperator, user: operator},
		{name: "admin", role: store.RoleAdmin, user: admin},
		{name: "platform", role: store.RolePlatform, user: platform},
	}

	for _, rt := range routeTable(ids) {
		for _, caller := range callers {
			t.Run(rt.method+" "+rt.path+"/"+caller.name, func(t *testing.T) {
				// A session per request: POST /auth/logout ends the one it is
				// given, and every later route would otherwise be testing a
				// cookie this test itself invalidated.
				cookie := ""
				if caller.user != nil {
					cookie = h.session(caller.user)
				}
				resp := h.do(request{
					method: rt.method, path: rt.path, body: rt.body, cookie: cookie,
				})
				switch {
				case rt.public:
					if resp.status == http.StatusForbidden {
						t.Fatalf("public route answered 403: %s", truncate(resp.body))
					}
					if resp.status == http.StatusUnauthorized && !rt.checksCredentials {
						t.Fatalf("public route answered 401: %s", truncate(resp.body))
					}
				case cookie == "":
					if resp.status != http.StatusUnauthorized {
						t.Fatalf("unauthenticated request answered %d, want 401: %s", resp.status, truncate(resp.body))
					}
				case !caller.role.AtLeast(rt.role):
					if resp.status != http.StatusForbidden {
						t.Fatalf("%s answered %d, want 403: %s", caller.name, resp.status, truncate(resp.body))
					}
					if msg := resp.errorMessage(t); !strings.Contains(msg, string(rt.role)) {
						t.Errorf("403 message does not name the %s role: %q", rt.role, msg)
					}
				default:
					if resp.status == http.StatusUnauthorized || resp.status == http.StatusForbidden {
						t.Fatalf("%s was refused with %d: %s", caller.name, resp.status, truncate(resp.body))
					}
				}
			})
		}
	}
}

// TestScopedTokenRouteAuthorisation is the walk for the second gate.
//
// A role says how much of the fleet an identity may touch; a scope narrows a
// token below its role, and it is the mechanism behind every "give CI a token
// that can only drain runners". Until now exactly one route had a test for it,
// and that one was really testing a handler's second check on its body. The
// route gate itself -- s.require, on sixty-odd routes -- had none, so a token
// scoped to nothing in particular would have reached all of them.
//
// Every token here carries the admin role, so a refusal can only be about the
// scope: if the role gate fired instead, the message would name a role and the
// assertion below would catch it.
func TestScopedTokenRouteAuthorisation(t *testing.T) {
	h := newHarness(t)
	ids := h.fixtures()

	// One token per resource, carrying every scope in the system except that
	// resource's. That is stronger than a single decoy scope: it proves the
	// route is gated on its own permission and not merely on holding some
	// scope, and it survives a new action being added elsewhere.
	elsewhere := map[string]string{}
	tokenWithoutResource := func(res string) string {
		if tok, ok := elsewhere[res]; ok {
			return tok
		}
		var scopes []string
		for _, a := range auth.AllActions() {
			if a.Resource() != res {
				scopes = append(scopes, a.Scope())
			}
		}
		// Minted at the top role on purpose: the only thing this token is
		// missing must be the scope, or the refusal it collects is about
		// the role gate and the scope gate goes untested.
		tok := h.token("everything-but-"+res, store.RolePlatform, scopes...)
		elsewhere[res] = tok
		return tok
	}

	gated := 0
	for _, rt := range routeTable(ids) {
		if rt.action == "" {
			continue
		}
		gated++
		t.Run(rt.method+" "+rt.path, func(t *testing.T) {
			refused := h.do(request{method: rt.method, path: rt.path, body: rt.body,
				token: tokenWithoutResource(rt.action.Resource())})
			refused.mustStatus(t, http.StatusForbidden, "a token scoped to every other resource")
			// The message names the scope that is missing, because the person
			// reading it has to know what to add to the token.
			if msg := refused.errorMessage(t); !strings.Contains(msg, rt.action.Scope()) {
				t.Errorf("the refusal does not name the %q scope: %q", rt.action.Scope(), msg)
			}

			// The positive half, three ways of holding the permission. Without
			// it, a gate that refused everything would pass the walk.
			for _, scope := range []string{rt.action.Scope(), rt.action.Resource() + ":*", "*"} {
				// At the route's own role, so this half tests the scope
				// and nothing else.
				allowed := h.do(request{method: rt.method, path: rt.path, body: rt.body,
					token: h.token(scope+" for "+rt.method+" "+rt.path, rt.role, scope)})
				if rt.accountOnly {
					allowed.mustStatus(t, http.StatusForbidden, "source membership cannot be inferred from a token scope")
					continue
				}
				if allowed.status == http.StatusForbidden || allowed.status == http.StatusUnauthorized {
					t.Errorf("a token scoped to %q was refused %d: %s", scope, allowed.status, truncate(allowed.body))
				}
			}
		})
	}
	if gated == 0 {
		t.Fatal("no route in the table carries an action, so this walked nothing")
	}
}

// TestEveryActionIsReachableThroughARoute keeps the column above honest in the
// direction the walk cannot: an action nothing in the table claims is either a
// permission no route enforces -- so a token scoped to it grants nothing and an
// operator has been sold a scope that does not exist -- or a route that arrived
// without a row, which is the same hole the role walk exists to close.
func TestEveryActionIsReachableThroughARoute(t *testing.T) {
	h := newHarness(t)
	claimed := map[auth.Action]bool{}
	for _, rt := range routeTable(h.fixtures()) {
		if rt.action != "" {
			claimed[rt.action] = true
		}
	}
	// Checked inside a handler rather than on a route, because the route is
	// everybody's and these widen it: tokens.read and tokens.write reach
	// every account's tokens where tokens.own reaches the caller's.
	claimed[auth.ActionTokensRead] = true
	claimed[auth.ActionTokensWrite] = true
	for _, a := range auth.AllActions() {
		if !claimed[a] {
			t.Errorf("%s is a permission no route in the table checks", a)
		}
	}
}

// TestScopesAreNarrowerThanRoles is the property the two walks together imply
// and neither states: a scope may take permissions away from a role and must
// never add one back. An admin-scoped token held by a viewer is still a viewer.
func TestScopesAreNarrowerThanRoles(t *testing.T) {
	h := newHarness(t)
	ids := h.fixtures()

	// A viewer holding the widest scope there is.
	viewer := h.token("wide-open viewer", store.RoleViewer, "*")

	resp := h.do(request{method: http.MethodDelete, path: "/api/v1/pools/" + ids.pool, token: viewer})
	resp.mustStatus(t, http.StatusForbidden, "a viewer with the * scope deleting a pool")
	if msg := resp.errorMessage(t); !strings.Contains(msg, string(store.RoleOperator)) {
		t.Errorf("the refusal does not name the role that is missing: %q", msg)
	}
	// And the reading it may do is unaffected.
	read := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: viewer})
	read.mustStatus(t, http.StatusOK, "a viewer with the * scope listing pools")
}

// TestRouteTableCoversTheSpec checks the hand-written table against the
// OpenAPI document, so a path added to the contract without a test here is
// reported rather than quietly untested.
func TestRouteTableCoversTheSpec(t *testing.T) {
	placeholders := fixtureIDs{
		installation: "ins_x", pool: "pool_x", runner: "run_x", host: "host_x", job: "job_x",
		provider: "prv_x", machine: "mach_x",
	}
	tested := map[string]bool{}
	for _, rt := range routeTable(placeholders) {
		tested[rt.method+" "+normalisePath(rt.path)] = true
	}

	spec, err := openapiSpec()
	if err != nil {
		t.Fatalf("openapiSpec: %v", err)
	}
	for _, op := range specOperations(t, spec) {
		if op.internal {
			// The agent routes carry a different credential class and are
			// exercised by agents_test.go with agent tokens.
			continue
		}
		key := op.method + " " + op.path
		if !tested[key] {
			t.Errorf("%s is in api/openapi.yaml but not in the route table", key)
		}
	}
}

// TestTheSpecCoversTheRouter is the other direction. The document's info block
// says it is the whole surface, and until this test the check ran one way
// only: everything in the spec had a route, while eight routes had no spec.
func TestTheSpecCoversTheRouter(t *testing.T) {
	h := newHarness(t)
	spec, err := openapiSpec()
	if err != nil {
		t.Fatalf("openapiSpec: %v", err)
	}
	documented := map[string]bool{}
	for _, op := range specOperations(t, spec) {
		documented[op.method+" "+op.path] = true
	}
	routes, ok := h.api.handler.(chi.Routes)
	if !ok {
		t.Fatalf("the server's handler is a %T, not a chi router", h.api.handler)
	}
	err = chi.Walk(routes, func(method, route string, _ http.Handler, _ ...func(http.Handler) http.Handler) error {
		if !strings.HasPrefix(route, "/api/v1/") {
			// Health, the spec itself, the webhook, metrics and the UI are
			// not API operations; docs/api-surface.md describes them.
			return nil
		}
		path := strings.TrimPrefix(route, "/api/v1")
		if len(path) > 1 {
			// chi reports the root of a Route group with a trailing slash.
			path = strings.TrimSuffix(path, "/")
		}
		if !documented[method+" "+path] {
			t.Errorf("%s %s is served but not in api/openapi.yaml", method, route)
		}
		return nil
	})
	if err != nil {
		t.Fatalf("chi.Walk: %v", err)
	}
}

// TestEveryOperationRecordsItsRole holds the info block to its word: each
// operation names its minimum role, unless it is anonymous or an agent route.
// Three operations shipped without one and nothing noticed.
func TestEveryOperationRecordsItsRole(t *testing.T) {
	spec, err := openapiSpec()
	if err != nil {
		t.Fatalf("openapiSpec: %v", err)
	}
	for _, op := range specOperations(t, spec) {
		switch {
		case op.internal:
			if op.role != "" {
				t.Errorf("%s %s is an agent route but names a user role %q", op.method, op.path, op.role)
			}
		case op.anonymous:
			if op.role != "" {
				t.Errorf("%s %s is anonymous but names a role %q", op.method, op.path, op.role)
			}
		case op.role == "":
			t.Errorf("%s %s has no x-zoomies-role", op.method, op.path)
		}
	}
}

// normalisePath turns a concrete test path back into the template the OpenAPI
// document uses, so the two can be compared.
func normalisePath(p string) string {
	p = strings.TrimPrefix(p, "/api/v1")
	parts := strings.Split(p, "/")
	for i, part := range parts {
		if i == 0 || part == "" {
			continue
		}
		// A backup remote is named by its own name rather than by a
		// prefixed id, so the segment after "remotes" is the parameter
		// whatever it is called. The two verbs among them -- /backups/offsite
		// and /backups/remotes/check -- stay themselves, which is also why a
		// remote may not be called "check".
		if i > 0 && parts[i-1] == "remotes" && part != "check" {
			parts[i] = "{name}"
			continue
		}
		if strings.HasPrefix(part, "ins_") || strings.HasPrefix(part, "pool_") ||
			strings.HasPrefix(part, "run_") || strings.HasPrefix(part, "host_") ||
			strings.HasPrefix(part, "job_") || strings.HasPrefix(part, "prv_") ||
			strings.HasPrefix(part, "mach_") || strings.HasPrefix(part, "zoomies-") || part == "missing" {
			parts[i] = "{id}"
		}
	}
	return strings.Join(parts, "/")
}

// specOperation is one method-and-path pair from the OpenAPI document, with
// the three things the checks here ask of it.
type specOperation struct {
	method string
	path   string
	// internal marks an agent route: x-internal: true.
	internal bool
	// anonymous marks an operation with security: [].
	anonymous bool
	// role is the x-zoomies-role, or empty.
	role string
}

// specOperations reads the paths out of the spec with a deliberately small
// parser: the document's shape is fixed and known, and pulling in a YAML
// dependency to read two levels of it would be more machinery than the check
// is worth.
func specOperations(t *testing.T, spec []byte) []specOperation {
	t.Helper()
	var out []specOperation
	var path string
	inPaths := false
	for _, line := range strings.Split(string(spec), "\n") {
		switch {
		case line == "paths:":
			inPaths = true
			continue
		case line == "components:":
			inPaths = false
		}
		if !inPaths || strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		if strings.HasPrefix(line, "  /") && strings.HasSuffix(strings.TrimSpace(line), ":") {
			path = strings.TrimSuffix(strings.TrimSpace(line), ":")
			continue
		}
		trimmed := strings.TrimSpace(line)
		// An operation's own keys sit exactly six spaces in.
		if path != "" && len(out) > 0 && strings.HasPrefix(line, "      ") && !strings.HasPrefix(line, "       ") {
			op := &out[len(out)-1]
			switch {
			case trimmed == "x-internal: true":
				op.internal = true
			case trimmed == "security: []":
				op.anonymous = true
			case strings.HasPrefix(trimmed, "x-zoomies-role:"):
				op.role = strings.TrimSpace(strings.TrimPrefix(trimmed, "x-zoomies-role:"))
			}
			continue
		}
		if path == "" || !strings.HasPrefix(line, "    ") || strings.HasPrefix(line, "     ") {
			continue
		}
		method := strings.TrimSuffix(trimmed, ":")
		switch method {
		case "get", "post", "patch", "delete", "put":
			out = append(out, specOperation{method: strings.ToUpper(method), path: path})
		}
	}
	if len(out) == 0 {
		t.Fatal("no operations found in the OpenAPI document; the parser above is wrong")
	}
	return out
}

// API responses are authenticated and change by the second; a proxy or a
// browser cache that kept one would show a signed-out user the previous
// user's fleet. Every route under /api/v1 says so.
func TestAPIResponsesAreNeverCached(t *testing.T) {
	h := newHarness(t)
	token := h.token("cache", store.RoleViewer)
	for _, rt := range []request{
		{method: http.MethodGet, path: "/api/v1/meta"},
		{method: http.MethodGet, path: "/api/v1/pools", token: token},
		{method: http.MethodGet, path: "/api/v1/agent/tasks"},
	} {
		resp := h.do(rt)
		if cc := resp.header.Get("Cache-Control"); cc != "no-store" {
			t.Errorf("%s %s: Cache-Control = %q, want no-store", rt.method, rt.path, cc)
		}
	}
}

// TestOversizeRequestBodyIsRefused covers the limit that stops a caller making
// the controller buffer memory on purpose.
//
// The status is the point as much as the refusal is. A 400 tells a client its
// JSON is wrong, and the JSON is not wrong -- there is simply too much of it,
// which is a different thing to do about it. The webhook endpoint has answered
// 413 for the same condition since it was written, so this is also the two
// halves of the surface giving one answer.
func TestOversizeRequestBodyIsRefused(t *testing.T) {
	h := newHarness(t)
	token := h.token("bulky", store.RoleAdmin)
	_, agentToken := h.agentToken("vm-1")

	// Built from the production constant, so raising the limit does not
	// quietly leave this test asserting nothing.
	oversize := `{"name":"` + strings.Repeat("a", maxBodyBytes) + `"}`
	json := map[string]string{"Content-Type": "application/json"}

	for _, tc := range []struct {
		name string
		req  request
	}{
		{"the user API", request{method: http.MethodPost, path: "/api/v1/pools",
			token: token, rawBody: oversize, headers: json}},
		{"the anonymous agent join", request{method: http.MethodPost, path: "/api/v1/agent/join",
			rawBody: oversize, headers: json}},
		{"an authenticated agent route", request{method: http.MethodPost, path: "/api/v1/agent/heartbeat",
			token: agentToken, rawBody: oversize, headers: json}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(tc.req)
			resp.mustStatus(t, http.StatusRequestEntityTooLarge, "an oversize body on "+tc.req.path)
			if code := resp.errorCode(t); code != codeTooLarge {
				t.Errorf("code = %q, want %q", code, codeTooLarge)
			}
			// The message names the limit, because a client that has just been
			// refused needs to know what it has to fit inside.
			if msg := resp.errorMessage(t); !strings.Contains(msg, strconv.Itoa(maxBodyBytes)) {
				t.Errorf("the refusal does not name the %d byte limit: %q", maxBodyBytes, msg)
			}
		})
	}

	// A body just under the limit is not refused for its size. It is refused
	// for being a nonsense pool, which is the handler's business and proves
	// the middleware let it through.
	t.Run("a body under the limit", func(t *testing.T) {
		under := `{"name":"` + strings.Repeat("a", maxBodyBytes/2) + `"}`
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/pools",
			token: token, rawBody: under, headers: json})
		if resp.status == http.StatusRequestEntityTooLarge {
			t.Fatalf("a body inside the limit was refused as too large: %s", truncate(resp.body))
		}
	})

	// The log relay's exemption is asserted where it can be observed, in
	// TestARunnerThatPrintsMoreThanTheBodyLimitIsNotCutOff: a relay for a
	// stream nobody is watching answers 404 before it reads a byte, so it
	// would answer the same whether the limit applied to it or not.
}

// The Overview reads the poller's state from /meta, and the two facts it needs
// are different questions: whether the fallback poller is running at all, and
// whether it is still sweeping. A controller that has never swept says so by
// omitting the stamp rather than by sending a zero time, because "1 January
// year 1" rendered on a page is worse than a blank.
func TestMetaSaysWhetherTheFallbackPollerIsRunning(t *testing.T) {
	h := newHarness(t)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/meta"})
	resp.mustStatus(t, http.StatusOK, "meta")
	var out struct {
		PollerEnabled    bool       `json:"poller_enabled"`
		PollerLastPollAt *time.Time `json:"poller_last_poll_at"`
	}
	resp.into(t, &out)
	if !out.PollerEnabled {
		t.Error("the fallback poller is on by default and /meta says it is not")
	}
	if out.PollerLastPollAt != nil {
		t.Errorf("a controller that has not swept reported a last poll: %v", out.PollerLastPollAt)
	}
}

// The capacity map's layouts are settings, and every browser reads them from
// /meta rather than from the settings route only an administrator may see.
// The two are live, so the answer moves in the same request that changed it,
// and the two pages move separately: a fleet may want the Overview glanced
// at as one chart and the Hosts page opened a chart per machine.
func TestMetaCarriesTheCapacityMapLayoutsAndAChangeIsLive(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	read := func() (overview, hosts string) {
		t.Helper()
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/meta"})
		resp.mustStatus(t, http.StatusOK, "meta")
		var out struct {
			CapacityMap struct {
				Overview string `json:"overview_layout"`
				Hosts    string `json:"hosts_layout"`
			} `json:"capacity_map"`
		}
		resp.into(t, &out)
		return out.CapacityMap.Overview, out.CapacityMap.Hosts
	}
	if o, hl := read(); o != "overlay" || hl != "overlay" {
		t.Fatalf("the defaults are %q and %q, want overlay for both", o, hl)
	}

	patched := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"ui.capacity_map.hosts_layout": "split"}})
	patched.mustStatus(t, http.StatusOK, "patch the hosts layout")
	if o, hl := read(); o != "overlay" || hl != "split" {
		t.Errorf("after setting the hosts layout, meta says %q and %q; want overlay and split", o, hl)
	}
	// It is stored, so the next start reads it from the database rather than
	// forgetting what the administrator chose.
	if row, err := h.ctrl.Store().GetInstanceSetting(t.Context(), "ui.capacity_map.hosts_layout"); err != nil {
		t.Errorf("the layout was not written: %v", err)
	} else if row.Value != "split" {
		t.Errorf("stored %q, want split", row.Value)
	}

	// A layout that is not one of the two is refused, and the refusal names
	// the two, because "not a capacity map layout" alone sends somebody to
	// the documentation for a menu of two items.
	refused := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"ui.capacity_map.overview_layout": "sideways"}})
	refused.mustStatus(t, http.StatusUnprocessableEntity, "a layout that does not exist")
	for _, want := range []string{"overlay", "split"} {
		if !strings.Contains(string(refused.body), want) {
			t.Errorf("the refusal does not offer %q: %s", want, refused.body)
		}
	}
	if o, _ := read(); o != "overlay" {
		t.Errorf("a refused change moved the overview layout to %q", o)
	}
}

package api

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// The event stream carries every audit row as it is written, and GET /audit
// filters what a caller may read of one. The stream did not: a viewer with the
// Overview open was sent the whole document of a settings change, backup
// directory and all, the moment the platform made it. The browser-level
// audience test found it.
func TestAnAuditFrameIsFilteredAsTheAuditLogIs(t *testing.T) {
	h := newHarness(t)
	viewer, _ := h.user("watcher", store.RoleViewer)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	plat, _ := h.user("operator-of-record", store.RolePlatform)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	asViewer, _ := h.openStream(t, ctx, "/api/v1/events", h.session(viewer), nil)
	asAdmin, _ := h.openStream(t, ctx, "/api/v1/events", h.session(admin), nil)
	asPlatform, _ := h.openStream(t, ctx, "/api/v1/events", h.session(plat), nil)
	for _, frames := range []<-chan sseFrame{asViewer, asAdmin, asPlatform} {
		await(t, frames, "the opening comment", func(f sseFrame) bool { return f.comment != "" })
	}

	const where = "/srv/the-platforms-backups"
	h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(plat),
		body: map[string]any{"backup.directory": where, "scheduler.interval": "12s"},
	}).mustStatus(t, http.StatusOK, "change a platform and a fleet setting together")

	isSettings := func(f sseFrame) bool {
		return f.event == string(events.KindAudit) && strings.Contains(f.data, `"target_kind":"settings"`)
	}
	if f := await(t, asViewer, "the viewer's audit frame", isSettings); strings.Contains(f.data, where) || strings.Contains(f.data, "12s") {
		t.Errorf("a viewer's audit frame carries the settings document: %s", f.data)
	}
	f := await(t, asAdmin, "the administrator's audit frame", isSettings)
	if strings.Contains(f.data, where) {
		t.Errorf("an administrator's audit frame carries the platform's backup directory: %s", f.data)
	}
	if !strings.Contains(f.data, "12s") {
		t.Errorf("an administrator's audit frame lost the fleet's own change: %s", f.data)
	}
	if f := await(t, asPlatform, "the platform's audit frame", isSettings); !strings.Contains(f.data, where) {
		t.Errorf("the platform's audit frame is missing its own change: %s", f.data)
	}

	// And the list says the same thing to the same people.
	listed := h.do(request{method: http.MethodGet, path: "/api/v1/audit", cookie: h.session(admin)})
	listed.mustStatus(t, http.StatusOK, "list the audit log as admin")
	if strings.Contains(string(listed.body), where) {
		t.Errorf("an administrator's audit log carries the platform's backup directory")
	}
}

package api

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/logging"
)

// SessionCookie is the name of the cookie a browser session lives in. It is
// exported because the OpenAPI document names it and the CLI's browser-login
// helper has to read it back.
const SessionCookie = "zoomies_session"

// maxAgentSessionBytes bounds the X-Zoomies-Agent-Session header before it is
// folded into a host's row. The legitimate value is `ses_` plus sixteen hex
// characters, so 128 bytes is a generous ceiling that still refuses one that
// could have come only from an agent trying to pad its own host's row.
const maxAgentSessionBytes = 128

// ctxKey is this package's private context key type, so nothing outside can
// collide with -- or forge -- what the middleware attaches.
type ctxKey int

const (
	ctxRequestInfo ctxKey = iota
	// ctxAgentHost carries the host an agent request authenticated as.
	ctxAgentHost
	// ctxInProcess carries the identity an in-process MCP tool call acts as.
	// It is set only by inProcessAPI, on a request that never touched the
	// network, and the key is private to this package, so nothing a client
	// sends can produce it.
	ctxInProcess
)

// requestInfo is what the middleware chain learns about a request, in one
// place.
//
// It is a pointer in the context and filled in as the chain goes, because the
// outermost middleware (which logs the request) needs the identity that an
// inner one resolves, and a middleware cannot see a context its own callee
// replaced.
type requestInfo struct {
	id string
	ip string
	// identity is nil until the authentication middleware has run, and stays
	// nil on the unauthenticated routes.
	identity *auth.Identity
	log      *slog.Logger
}

func infoFrom(ctx context.Context) *requestInfo {
	info, _ := ctx.Value(ctxRequestInfo).(*requestInfo)
	return info
}

// Identity returns the authenticated caller, or nil on an unauthenticated
// route. Handlers use it for audit attribution and for the checks that depend
// on who is asking rather than on the route alone.
func Identity(ctx context.Context) *auth.Identity {
	if info := infoFrom(ctx); info != nil {
		return info.identity
	}
	return nil
}

// clientIP returns the address a request came from, resolved through the proxies
// the operator has said to trust.
func ClientIP(ctx context.Context) string {
	if info := infoFrom(ctx); info != nil {
		return info.ip
	}
	return ""
}

// RequestID returns the identifier this request is logged under, which is what
// an internal error hands back so an operator can find the log line.
func RequestID(ctx context.Context) string {
	if info := infoFrom(ctx); info != nil {
		return info.id
	}
	return ""
}

// logger returns the request-scoped logger.
func (s *Server) logger(r *http.Request) *slog.Logger {
	if info := infoFrom(r.Context()); info != nil && info.log != nil {
		return info.log
	}
	return s.log
}

// ---------------------------------------------------------------------------
// Authentication
// ---------------------------------------------------------------------------

// authenticate resolves the caller and refuses the request when it cannot.
//
// When security.disable_auth is set, auth.Authenticate hands back the
// "auth-disabled" administrator for every request; the warning about that is
// logged once at startup rather than here, because a line per request is a line
// nobody reads.
func (s *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		info := infoFrom(r.Context())
		id, err := s.resolveIdentity(r)
		if err != nil {
			// A credential the controller could not check is not one it
			// refused: a 401 makes the UI drop a session that is still good,
			// and quoting the driver's error hands a caller the database's
			// wording.
			if errors.Is(err, auth.ErrAuthBackend) {
				s.internal(w, r, "checking your credentials", err)
				return
			}
			unauthorized(w, err.Error())
			return
		}
		if info != nil {
			info.identity = id
			info.log = info.log.With("identity", id.String())
		}
		next.ServeHTTP(w, r)
	})
}

// optionalAuth resolves the caller when a credential is present but lets the
// request through when it is not. It is what /meta and the login routes use, so
// that a signed-in operator's actions are still attributed in the audit log.
func (s *Server) optionalAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if id, err := s.resolveIdentity(r); err == nil {
			if info := infoFrom(r.Context()); info != nil {
				info.identity = id
			}
		}
		next.ServeHTTP(w, r)
	})
}

// resolveIdentity turns the request's credentials into an identity.
func (s *Server) resolveIdentity(r *http.Request) (*auth.Identity, error) {
	if check, ok := r.Context().Value(contextCredentialCheck{}).(func(context.Context) (*auth.Identity, error)); ok {
		return check(r.Context())
	}
	if id := inProcessIdentity(r); id != nil {
		return id, nil
	}
	in := auth.AuthInput{
		Authorization: r.Header.Get("Authorization"),
		IP:            ClientIP(r.Context()),
	}
	if c, err := r.Cookie(SessionCookie); err == nil {
		in.SessionCookie = c.Value
	}
	return s.auth.Authenticate(r.Context(), in)
}

func hasBearer(r *http.Request) bool {
	scheme, _, ok := strings.Cut(strings.TrimSpace(r.Header.Get("Authorization")), " ")
	return ok && strings.EqualFold(scheme, "bearer")
}

// require refuses a caller whose role or scopes do not reach the action.
//
// The policy lives in internal/auth's table, not here: this middleware only
// asks. That is what makes "every route has a role" a property a test can walk,
// and what stops a new endpoint from shipping without anyone deciding who may
// call it.
func (s *Server) require(action auth.Action) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			id := Identity(r.Context())
			if id == nil {
				unauthorized(w, auth.ErrNoCredentials.Error())
				return
			}
			if !auth.Allowed(id, action) {
				forbidden(w, auth.Explain(id, action))
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

// ---------------------------------------------------------------------------
// Cross-site request forgery
// ---------------------------------------------------------------------------

// csrf refuses an unsafe cross-origin request that carries the session cookie.
//
// Bearer requests are exempt, and deliberately so: a browser cannot attach an
// Authorization header to a cross-origin request without a CORS preflight,
// which this server never grants, so a token-authenticated call cannot be made
// by a page the operator merely visited. A cookie, by contrast, rides along on
// its own, which is exactly what makes the check necessary here.
//
// The check runs on the whole /api/v1 subtree rather than only on
// cookie-authenticated routes, because POST /auth/login mints the cookie and a
// login CSRF -- signing the victim into the attacker's account -- is worth
// refusing too.
func (s *Server) csrf(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet, http.MethodHead, http.MethodOptions:
			next.ServeHTTP(w, r)
			return
		}
		if hasBearer(r) {
			next.ServeHTTP(w, r)
			return
		}
		if msg := s.checkOrigin(r); msg != "" {
			forbidden(w, msg)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// checkOrigin returns "" when the request is same-origin (or from an origin the
// operator allowed), and otherwise the sentence to refuse it with.
func (s *Server) checkOrigin(r *http.Request) string {
	// Sec-Fetch-Site is the browser's own answer and cannot be set by script.
	// "none" is a user-initiated navigation, which is not a forged request.
	switch strings.ToLower(r.Header.Get("Sec-Fetch-Site")) {
	case "same-origin", "none":
		return ""
	case "":
		// Not sent: either an older browser or a non-browser client. Fall
		// through to the Origin header.
	default:
		if s.originAllowed(r.Header.Get("Origin")) || s.sameOriginAsRequest(r, r.Header.Get("Origin")) {
			return ""
		}
		from := strings.TrimSpace(r.Header.Get("Origin"))
		if from == "" {
			from = "another site"
		}
		return "this request came from " + from + " (Sec-Fetch-Site: " + r.Header.Get("Sec-Fetch-Site") +
			"), which is not this controller's origin. Add it to server.allowed_origins if that is deliberate, or use an API token."
	}

	origin := strings.TrimSpace(r.Header.Get("Origin"))
	if origin == "" {
		if r.Header.Get("Referer") == "" && !hasCookie(r, SessionCookie) && !hasCookie(r, SignInCookie) {
			// No cookie, no browser headers: a plain client that is about to be
			// asked for credentials anyway.
			return ""
		}
		return "this request carried no Origin or Sec-Fetch-Site header, so it cannot be shown to have come from the Zoomies UI. " +
			"Use a browser, or authenticate with an API token, which is exempt from this check."
	}
	if s.originAllowed(origin) || s.sameOriginAsRequest(r, origin) {
		return ""
	}
	return "this request came from " + origin + ", which is not this controller's origin. " +
		"Add it to server.allowed_origins if that is deliberate, or use an API token."
}

// originAllowed reports whether an Origin header names this controller or one
// of the origins the operator listed.
func (s *Server) originAllowed(origin string) bool {
	origin = strings.TrimSpace(origin)
	if origin == "" {
		return false
	}
	for _, allowed := range s.cfg().Server.AllowedOrigins {
		if strings.EqualFold(strings.TrimRight(strings.TrimSpace(allowed), "/"), strings.TrimRight(origin, "/")) {
			return true
		}
		if allowed == "*" {
			return true
		}
	}
	if ext := s.cfg().Server.ExternalURL; ext != "" {
		if u, err := url.Parse(ext); err == nil && sameOrigin(u, origin) {
			return true
		}
	}
	return false
}

// sameOrigin compares an Origin header with a URL's scheme and host.
func sameOrigin(u *url.URL, origin string) bool {
	o, err := url.Parse(origin)
	if err != nil {
		return false
	}
	return strings.EqualFold(o.Scheme, u.Scheme) && strings.EqualFold(o.Host, u.Host)
}

// sameOriginAsRequest reports whether origin matches the host the request was
// addressed to. It is the fallback when server.external_url is not configured,
// which is the common case on a loopback development instance.
func (s *Server) sameOriginAsRequest(r *http.Request, origin string) bool {
	o, err := url.Parse(origin)
	if err != nil || o.Host == "" {
		return false
	}
	if !strings.EqualFold(o.Host, r.Host) {
		return false
	}
	return strings.EqualFold(o.Scheme, s.requestScheme(r))
}

func hasCookie(r *http.Request, name string) bool {
	_, err := r.Cookie(name)
	return err == nil
}

// ---------------------------------------------------------------------------
// The session cookie
// ---------------------------------------------------------------------------

// setSessionCookie installs a browser session.
//
// SameSite=Lax rather than Strict so that following a link into Zoomies from
// another tab does not land on a login page; the same-origin check above is
// what defends the unsafe methods, and it does not depend on the cookie policy.
func (s *Server) setSessionCookie(w http.ResponseWriter, token string) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    token,
		Path:     "/",
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteLaxMode,
		MaxAge:   int(s.auth.SessionTTL() / time.Second),
	})
}

// clearSessionCookie expires the cookie. The attributes have to match the ones
// it was set with or the browser keeps the old cookie alongside the new one.
func (s *Server) clearSessionCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    "",
		Path:     "/",
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteLaxMode,
		MaxAge:   -1,
		Expires:  time.Unix(0, 0),
	})
}

// ---------------------------------------------------------------------------
// Agent authentication
// ---------------------------------------------------------------------------

// agentAuth resolves an agent's own token to its host.
//
// Agent credentials are a separate class from user ones: they are accepted on
// /api/v1/agent/* and nowhere else, and an identity from here carries the
// viewer role purely so that audit rows have an actor. The host is what the
// handlers actually work with, which is why it goes into the context too.
func (s *Server) agentAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h, err := s.auth.AuthenticateAgent(r.Context(), r.Header.Get("Authorization"))
		if err != nil {
			switch {
			case errors.Is(err, auth.ErrNoCredentials):
				unauthorized(w, "this endpoint is for agents; send the agent token issued at join as a bearer token")
			case errors.Is(err, auth.ErrInvalidCredentials):
				unauthorized(w, "this controller does not recognise that agent token; re-join the host with a fresh join token (zoomies agent join <controller-url> --token <join-token>)")
			default:
				s.internal(w, r, "authenticating an agent", err)
			}
			return
		}
		info := infoFrom(r.Context())
		id := auth.AgentIdentity(h, ClientIP(r.Context()))
		if info != nil {
			info.identity = id
			info.log = info.log.With("host", h.ID, "host_name", h.Name)
		}
		// Every authenticated agent request carries the session, so recording
		// it here catches a duplicate whichever call it makes first rather
		// than only on the heartbeat.
		//
		// The header is capped so that an authenticated agent cannot keep
		// writing arbitrarily large values into its host's row by alternating
		// them: a legitimate session is `ses_` plus sixteen hex characters,
		// well under this ceiling.
		if session := r.Header.Get(agent.HeaderAgentSession); len(session) <= maxAgentSessionBytes {
			s.ctrl.NoteAgentSession(r.Context(), h.ID, session)
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxAgentHost, h)))
	})
}

// ---------------------------------------------------------------------------
// Client addresses
// ---------------------------------------------------------------------------

// resolveClientIP is the real-IP resolver.
//
// X-Forwarded-For is believed only when the connection itself came from a CIDR
// in server.trusted_proxies, and then only the right-most entry that is not
// itself a trusted proxy is taken. Anything else lets a client pick its own
// address, and with it defeat the login rate limiter and forge the address in
// every audit row it causes.
func (s *Server) resolveClientIP(r *http.Request) string {
	remote, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		remote = r.RemoteAddr
	}
	if len(s.trusted) == 0 || !s.isTrustedProxy(remote) {
		return remote
	}

	// Cloudflare sets CF-Connecting-IP to the true client address and cannot be
	// talked out of it, whereas X-Forwarded-For arrives as whatever the client
	// sent with Cloudflare's own value appended. Both resolve correctly here,
	// but only one of them is a single unambiguous value, so prefer it -- and
	// only when the connection itself came from one of Cloudflare's own
	// addresses. A trusted proxy that is not Cloudflare -- nginx, HAProxy --
	// forwards a header it does not recognise untouched, so from behind one of
	// those the header is whatever the client chose to send, and believing it
	// would let anyone pick the address the rate limiter and the audit log see.
	if cf := strings.TrimSpace(r.Header.Get("CF-Connecting-IP")); cf != "" && s.isCloudflare(remote) {
		if ip := net.ParseIP(strings.Trim(cf, "[]")); ip != nil {
			return ip.String()
		}
	}

	forwarded := r.Header.Values("X-Forwarded-For")
	var chain []string
	for _, header := range forwarded {
		for _, part := range strings.Split(header, ",") {
			if part = strings.TrimSpace(part); part != "" {
				chain = append(chain, part)
			}
		}
	}
	for i := len(chain) - 1; i >= 0; i-- {
		if ip := net.ParseIP(strings.Trim(chain[i], "[]")); ip != nil && !s.isTrustedProxy(chain[i]) {
			return ip.String()
		}
	}
	if real := strings.TrimSpace(r.Header.Get("X-Real-IP")); real != "" {
		if ip := net.ParseIP(real); ip != nil {
			return ip.String()
		}
	}
	return remote
}

// isCloudflare reports whether addr is one of Cloudflare's published edge
// addresses -- the only peer whose CF-Connecting-IP means anything.
func (s *Server) isCloudflare(addr string) bool {
	ip := net.ParseIP(strings.Trim(addr, "[]"))
	if ip == nil {
		return false
	}
	return slices.ContainsFunc(s.cloudflare, func(n *net.IPNet) bool { return n.Contains(ip) })
}

// requestScheme is the scheme the client actually used, as far as this
// controller can honestly tell.
//
// X-Forwarded-Proto is believed only when the connection itself came from a
// CIDR in server.trusted_proxies, exactly as X-Forwarded-For is. Anything else
// lets a client choose the scheme the controller thinks it was reached on --
// and that scheme decides whether an https:// Origin counts as same-origin,
// which is a CSRF check, and whether the response carries HSTS.
//
// A deployment behind a TLS-terminating proxy that has set neither
// trusted_proxies nor external_url now reads as http here. That is the honest
// answer: nothing about such a request distinguishes the proxy from anyone
// else who can reach the listener. It costs little in practice -- an Origin
// matching server.external_url is allowed before this is consulted, and a
// browser new enough to send Sec-Fetch-Site never reaches it at all -- and a
// missing external_url already raises a startup warning of its own.
func (s *Server) requestScheme(r *http.Request) string {
	if r.TLS != nil {
		return "https"
	}
	remote, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		remote = r.RemoteAddr
	}
	if len(s.trusted) == 0 || !s.isTrustedProxy(remote) {
		return "http"
	}
	// The left-most value, which is the scheme the original client used: a
	// chain of proxies appends, and the entries after the first describe hops
	// inside the operator's own network.
	proto := r.Header.Get("X-Forwarded-Proto")
	if i := strings.IndexByte(proto, ','); i >= 0 {
		proto = proto[:i]
	}
	if strings.EqualFold(strings.TrimSpace(proto), "https") {
		return "https"
	}
	return "http"
}

func (s *Server) isTrustedProxy(addr string) bool {
	ip := net.ParseIP(strings.Trim(addr, "[]"))
	if ip == nil {
		return false
	}
	return slices.ContainsFunc(s.trusted, func(n *net.IPNet) bool { return n.Contains(ip) })
}

// withRequestLogger attaches the request-scoped logger to the context so that
// anything downstream -- including the controller, which reads it through
// logging.FromContext -- logs with the request ID attached.
func withRequestLogger(ctx context.Context, l *slog.Logger) context.Context {
	return logging.WithLogger(ctx, l)
}

