func TestChangeOwnPassword(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("alice", store.RoleViewer)
	cookie := h.session(u)

	wrong := h.do(request{method: http.MethodPost, path: "/api/v1/auth/password", cookie: cookie,
		body: map[string]any{"old_password": "nope", "new_password": "another-good-password"}})
	wrong.mustStatus(t, http.StatusUnprocessableEntity, "change with the wrong current password")

	ok := h.do(request{method: http.MethodPost, path: "/api/v1/auth/password", cookie: cookie,
		body: map[string]any{"old_password": testPassword, "new_password": "another-good-password"}})
	ok.mustStatus(t, http.StatusNoContent, "change password")
	if ok.cookie == nil || ok.cookie.Value == "" {
		t.Fatal("changing a password did not issue a fresh session for this browser")
	}

	// The old cookie is gone; the new one works.
	old := h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: cookie})
	old.mustStatus(t, http.StatusUnauthorized, "the old session after a password change")
	fresh := h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: ok.cookie.Value})
	fresh.mustStatus(t, http.StatusOK, "the new session after a password change")
}

// TestChangeOwnPasswordIsRateLimited is the 429 the OpenAPI spec promises for
// the route: a stolen session cookie must not be a free oracle for the account
// password, so wrong "current password" guesses are charged to the login limits
// and told when to come back.
func TestChangeOwnPasswordIsRateLimited(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("alice", store.RoleViewer)
	cookie := h.session(u)

	var last *response
	for range h.cfg.Security.RateLimitLogins + 2 {
		last = h.do(request{method: http.MethodPost, path: "/api/v1/auth/password", cookie: cookie,
			body: map[string]any{"old_password": "nope", "new_password": "another-good-password"}})
	}
	last.mustStatus(t, http.StatusTooManyRequests, "change password after too many guesses")
	if code := last.errorCode(t); code != codeRateLimited {
		t.Errorf("error code = %q, want %q", code, codeRateLimited)
	}
	if secs, err := strconv.Atoi(last.header.Get("Retry-After")); err != nil || secs <= 0 {
		t.Errorf("Retry-After = %q, want the seconds left of the window", last.header.Get("Retry-After"))
	}
}

// ---------------------------------------------------------------------------
// Single sign-on
// ---------------------------------------------------------------------------

// The OIDC state is minted server-side and remembered in a cookie on the
// browser that began the handshake. Without that binding, a state an attacker
// obtained by signing in as themselves is one this controller would accept from
// anybody's browser -- and the victim would end up signed in as the attacker.
//
// The provider here is a bare value: Enabled() only asks whether there is one,
// and the state check happens before anything touches it, which is the point.
func TestOIDCCallbackRefusesAStateThisBrowserDidNotStart(t *testing.T) {
	h := newHarness(t)
	h.api.useOIDC(&auth.OIDCProvider{})

	cases := []struct {
		name   string
		cookie string
		state  string
	}{
		{name: "no cookie at all", state: "state-from-somewhere-else"},
		{name: "a state from another browser", cookie: "ours", state: "theirs"},
		{name: "a cookie but no state", cookie: "ours"},
		{name: "neither"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			req := request{method: http.MethodGet, path: "/api/v1/auth/oidc/callback?code=abc&state=" + tc.state}
			if tc.cookie != "" {
				req.headers = map[string]string{"Cookie": oidcStateCookie + "=" + tc.cookie}
			}
			resp := h.do(req)
			resp.mustStatus(t, http.StatusFound, "callback with "+tc.name)
			if loc := resp.header.Get("Location"); !strings.HasPrefix(loc, "/login?error=") {
				t.Fatalf("Location = %q; want a redirect back to the login page", loc)
			}
			if resp.cookie != nil && resp.cookie.Value != "" {
				t.Fatal("a refused callback issued a session")
			}
		})
	}
}

// Whatever the outcome, the state cookie is spent: leaving it in place would
// let the same callback be replayed against this browser.
func TestOIDCCallbackClearsTheStateCookie(t *testing.T) {
	h := newHarness(t)
	h.api.useOIDC(&auth.OIDCProvider{})

	resp := h.do(request{
		method:  http.MethodGet,
		path:    "/api/v1/auth/oidc/callback?code=abc&state=theirs",
		headers: map[string]string{"Cookie": oidcStateCookie + "=ours"},
	})
	resp.mustStatus(t, http.StatusFound, "refused callback")

	var cleared bool
	for _, c := range resp.header.Values("Set-Cookie") {
		if strings.HasPrefix(c, oidcStateCookie+"=;") || strings.Contains(c, oidcStateCookie+"=;") {
			cleared = true
		}
	}
	if !cleared {
		t.Fatalf("the state cookie was not cleared: %v", resp.header.Values("Set-Cookie"))
	}
}

// The bootstrap route has to be open on a fresh install and closed to everybody
// who is not the operator, and "no account exists yet" does not tell those two
// apart. The setup token does: it is printed in this controller's log, so
// holding it means having deployed the thing.
func TestBootstrapNeedsTheSetupToken(t *testing.T) {
	h := newHarness(t)

	cases := []struct {
		name string
		body map[string]any
	}{
		{name: "no token at all", body: map[string]any{"username": "root", "password": testPassword}},
		{name: "an empty token", body: map[string]any{"username": "root", "password": testPassword, "setup_token": "  "}},
		{name: "somebody else's guess", body: map[string]any{"username": "root", "password": testPassword, "setup_token": "zoo-not-the-token"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/auth/bootstrap", body: tc.body})
			resp.mustStatus(t, http.StatusUnprocessableEntity, "bootstrap with "+tc.name)

			var env errorEnvelope
			resp.into(t, &env)
			if len(env.Errors) == 0 || env.Errors[0].Field != "setup_token" {
				t.Fatalf("expected a field error on setup_token, got %+v", env)
			}
			if resp.cookie != nil && resp.cookie.Value != "" {
				t.Fatal("a refused bootstrap issued a session")
			}
		})
	}

	// Nothing was created, so the instance is still waiting for its first
	// account rather than quietly belonging to whoever tried.
	if meta := h.do(request{method: http.MethodGet, path: "/api/v1/meta"}); meta.json(t)["bootstrap_required"] != true {
		t.Fatal("a refused bootstrap created an account")
	}
	users, err := h.st.ListUsers(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(users) != 0 {
		t.Fatalf("accounts = %d after refused bootstraps; want none", len(users))
	}
}

// The compose deployment is https on the outside and plain http inside, and an
// operator checking the container by IP before DNS exists would otherwise
// create the one administrator and lose the session in the same second: the
// browser will not keep a Secure cookie from an insecure page, and the endpoint
// that made the account has closed for good. The browser's Origin is the one
// fact that says which page the request came from.
func TestBootstrapRefusesAPageThatWouldDropTheSecureCookie(t *testing.T) {
	secure := true
	h := newHarness(t, func(c *config.Config) {
		c.Server.ExternalURL = "https://zoomies.test"
		c.Server.AllowedOrigins = []string{"http://10.0.0.5"}
		c.Security.CookieSecure = &secure
	})

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/auth/bootstrap", origin: "http://10.0.0.5",
		body: map[string]any{"username": "root", "password": testPassword, "setup_token": h.setupToken()}})
	resp.mustStatus(t, http.StatusBadRequest, "bootstrap from a plain-http page")
	for _, want := range []string{"http://10.0.0.5", "https://zoomies.test", "Secure", "ZOOMIES_COOKIE_SECURE=false"} {
		if !strings.Contains(resp.errorMessage(t), want) {
			t.Errorf("the refusal does not say %q: %s", want, resp.errorMessage(t))
		}
	}

	// Nothing was created by the refused request: the same account can still
	// be made from the https page.
	ok := h.do(request{method: http.MethodPost, path: "/api/v1/auth/bootstrap", origin: "https://zoomies.test",
		body: map[string]any{"username": "root", "password": testPassword, "setup_token": h.setupToken()}})
	ok.mustStatus(t, http.StatusCreated, "bootstrap from the https page")
	if ok.cookie == nil || !ok.cookie.Secure {
		t.Fatal("the session cookie from the https page is not Secure")
	}
}

// Login gets the same refusal, and a loopback page does not: browsers treat
// localhost as a secure context and keep the cookie there, which is how a
// developer runs this over plain http on purpose.
func TestLoginRefusesAPageThatWouldDropTheSecureCookieButNotLocalhost(t *testing.T) {
	secure := true
	h := newHarness(t, func(c *config.Config) {
		c.Server.ExternalURL = "https://zoomies.test"
		c.Server.AllowedOrigins = []string{"http://10.0.0.5", "http://localhost:8080"}
		c.Security.CookieSecure = &secure
	})
	h.user("alice", store.RoleAdmin)

	refused := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login", origin: "http://10.0.0.5",
		body: map[string]any{"username": "alice", "password": testPassword}})
	refused.mustStatus(t, http.StatusBadRequest, "login from a plain-http page")

	local := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login", origin: "http://localhost:8080",
		body: map[string]any{"username": "alice", "password": testPassword}})
	local.mustStatus(t, http.StatusOK, "login from localhost")
}

// A database that stops answering used to come back through the anonymous
// routes as a 422 quoting the driver's error, as though the caller had typed
// something wrong; it never reached the error log either, because the 422
// path does not log. The cause belongs in the log and the caller gets a
// request ID to quote.
func TestDatabaseFailuresAreInternalErrorsNotValidationMessages(t *testing.T) {
	h := newHarness(t)
	if err := h.st.Close(); err != nil {
		t.Fatalf("closing the store: %v", err)
	}

	boot := h.do(request{method: http.MethodPost, path: "/api/v1/auth/bootstrap", body: map[string]any{
		"username": "root", "password": testPassword, "setup_token": h.setupToken(),
	}})
	boot.mustStatus(t, http.StatusInternalServerError, "bootstrap against a closed database")
	if msg := boot.errorMessage(t); strings.Contains(strings.ToLower(msg), "sql") || strings.Contains(msg, "closed") {
		t.Fatalf("the database error reached an anonymous caller: %q", msg)
	}

	ready := h.do(request{method: http.MethodGet, path: "/readyz"})
	ready.mustStatus(t, http.StatusServiceUnavailable, "readiness against a closed database")
	body := ready.json(t)
	if msg, _ := body["message"].(string); strings.Contains(strings.ToLower(msg), "sql") || strings.Contains(msg, "closed") {
		t.Fatalf("the readiness probe quoted the database error: %q", msg)
	}
}

// A 401 tells every client to sign in again, and the web client acts on it by
// dropping a perfectly good session. A database that stops answering while a
// credential is being looked up used to come back as exactly that, with the
// driver's own error in the body. It is the controller that is broken, not the
// credential, so it is a 500 with a request ID and the cause in the log only.
func TestDatabaseFailuresWhileCheckingACredentialAreInternalErrorsNotSignOuts(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(u)
	token := h.token("ci", store.RoleViewer)
	if err := h.st.Close(); err != nil {
		t.Fatalf("closing the store: %v", err)
	}

	for _, tc := range []struct {
		name string
		req  request
	}{
		{"a session cookie", request{method: http.MethodGet, path: "/api/v1/pools", cookie: cookie}},
		{"an API token", request{method: http.MethodGet, path: "/api/v1/pools", token: token}},
		{"an API token on the MCP endpoint", request{
			method: http.MethodPost, path: "/mcp", token: token, noOrigin: true,
			body: map[string]any{"jsonrpc": "2.0", "id": 1, "method": "tools/list"},
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(tc.req)
			resp.mustStatus(t, http.StatusInternalServerError, "a credential check against a closed database")
			if code := resp.errorCode(t); code != codeInternal {
				t.Errorf("error code = %q, want %q", code, codeInternal)
			}
			msg := strings.ToLower(resp.errorMessage(t))
			for _, leak := range []string{"looking up", "sql", "closed"} {
				if strings.Contains(msg, leak) {
					t.Errorf("the database error reached the caller: %q", msg)
				}
			}
			if detail, _ := resp.json(t)["error"].(map[string]any)["detail"].(string); !strings.HasPrefix(detail, "request ") {
				t.Errorf("detail = %q, want a request ID the operator can quote", detail)
			}
			// A challenge on a 500 would send an MCP client off to start a
			// sign-in that cannot help.
			if got := resp.header.Get("WWW-Authenticate"); got != "" {
				t.Errorf("WWW-Authenticate = %q on a server error, want none", got)
			}
		})
	}
}

// The other half of the rule above: a credential the database answered about
// and refused stays a 401, so the UI still signs out an expired session.
func TestARefusedCredentialIsStillA401(t *testing.T) {
	h := newHarness(t)
	for _, tc := range []struct {
		name string
		req  request
	}{
		{"an unknown session cookie", request{method: http.MethodGet, path: "/api/v1/pools", cookie: "not-a-session"}},
		{"an unknown API token", request{method: http.MethodGet, path: "/api/v1/pools", token: "zoo_not-a-token"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h.do(tc.req).mustStatus(t, http.StatusUnauthorized, tc.name)
		})
	}
}

// TestForwardedProtoIsBelievedOnlyFromATrustedProxy is the header's side of the
// rule X-Forwarded-For has always followed.
//
// The scheme is not decoration. It decides whether an https:// Origin counts as
// this controller's own -- which is a CSRF check -- and whether the response
// carries HSTS. Believing a header any client can set let a caller choose the
// answer to both.
func TestForwardedProtoIsBelievedOnlyFromATrustedProxy(t *testing.T) {
	// The harness's requests come from loopback, so a loopback CIDR is what
	// makes this test server "behind a proxy".
	const loopback = "127.0.0.0/8"

	secureOrigin := func(h *harness) string {
		return "https://" + strings.TrimPrefix(h.srv.URL, "http://")
	}

	t.Run("a forged header does not make an https origin same-origin", func(t *testing.T) {
		h := newHarness(t)
		u, _ := h.user("operator", store.RoleOperator)

		resp := h.do(request{
			method: http.MethodPost, path: "/api/v1/pools/validate",
			cookie: h.session(u), origin: secureOrigin(h),
			headers: map[string]string{"X-Forwarded-Proto": "https"},
			body:    map[string]any{"name": "x"},
		})
		resp.mustStatus(t, http.StatusForbidden, "a cookie POST claiming https over a plain connection")
	})

	t.Run("the same header from a trusted proxy is believed", func(t *testing.T) {
		h := newHarness(t, func(c *config.Config) {
			c.Server.TrustedProxies = []string{loopback}
		})
		u, _ := h.user("operator", store.RoleOperator)

		resp := h.do(request{
			method: http.MethodPost, path: "/api/v1/pools/validate",
			cookie: h.session(u), origin: secureOrigin(h),
			headers: map[string]string{"X-Forwarded-Proto": "https"},
			body:    map[string]any{"name": "x"},
		})
		if resp.status == http.StatusForbidden {
			t.Fatalf("a request through a configured proxy was refused: %s", truncate(resp.body))
		}
	})

	t.Run("HSTS is not emitted because a client asked for it", func(t *testing.T) {
		h := newHarness(t)
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/meta",
			headers: map[string]string{"X-Forwarded-Proto": "https"}})
		if got := resp.header.Get("Strict-Transport-Security"); got != "" {
			t.Errorf("Strict-Transport-Security = %q on a plain connection; anyone who can reach "+
				"the listener could pin this host in a browser for a year", got)
		}
	})

	t.Run("HSTS is emitted behind a proxy that terminates TLS", func(t *testing.T) {
		h := newHarness(t, func(c *config.Config) {
			c.Server.TrustedProxies = []string{loopback}
		})
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/meta",
			headers: map[string]string{"X-Forwarded-Proto": "https"}})
		if got := resp.header.Get("Strict-Transport-Security"); got == "" {
			t.Error("no Strict-Transport-Security behind a configured TLS-terminating proxy, " +
				"which is the deployment the header exists for")
		}
	})

	// A chain appends, and the entries after the first are hops inside the
	// operator's own network. The client's own scheme is the left-most one, so
	// a plain request that crossed an internal TLS hop is still plain.
	t.Run("a chain is read left to right", func(t *testing.T) {
		h := newHarness(t, func(c *config.Config) {
			c.Server.TrustedProxies = []string{loopback}
		})
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/meta",
			headers: map[string]string{"X-Forwarded-Proto": "http, https"}})
		if got := resp.header.Get("Strict-Transport-Security"); got != "" {
			t.Errorf("Strict-Transport-Security = %q, though the client reached the first proxy over http", got)
		}
	})
}

package api

import (
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
)

// Adding a destination from the page, which is the half a file could not do:
// typed, tested, stored with its secret sealed, and used by the next pass.
func TestADestinationAddedOnThePageIsTestedStoredAndUsed(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	h.installation()
	cookie := h.platform()

	// Distinctive values, so "is the secret in the response?" is a question
	// with an exact answer rather than a search for the word "secret" among
	// field names that also contain it.
	const (
		secretKey  = "s3cr3t-value-never-served"
		passphrase = "passphrase-value-never-served"
	)
	body := map[string]any{
		"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
		"prefix": "fleet", "access_key_id": "AKIAEXAMPLE", "secret_access_key": secretKey,
		"passphrase": passphrase, "keep": 30,
	}

	// Tested before it is saved, which is the whole reason the button is there.
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/check", cookie: cookie, body: body})
	resp.mustStatus(t, http.StatusOK, "test a destination that is not saved yet")
	var check remoteCheckResponse
	resp.into(t, &check)
	if !check.OK {
		t.Fatalf("the draft was refused: %+v", check)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: body})
	resp.mustStatus(t, http.StatusCreated, "add a destination")
	var added controller.RemoteBackupStatus
	resp.into(t, &added)
	if added.Source != controller.RemoteSourceDatabase || added.ID == "" {
		t.Fatalf("what came back is %+v; a destination added here is a stored one", added)
	}
	if !added.Encrypted || !added.HasSecretKey || added.Keep != 30 {
		t.Errorf("the destination reads %+v", added)
	}

	// Neither secret ever comes back, in any shape. They are sealed at rest
	// and one-way on the wire: what a page can act on is whether one is set.
	if strings.Contains(string(resp.body), secretKey) || strings.Contains(string(resp.body), passphrase) {
		t.Fatalf("a secret was served back: %s", string(resp.body))
	}
	listing := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	if strings.Contains(string(listing.body), secretKey) || strings.Contains(string(listing.body), passphrase) {
		t.Fatalf("the backups page carries a secret: %s", string(listing.body))
	}

	// And it is a destination the fleet actually uses: taking a backup and
	// running the pass puts a copy in the bucket.
	taken := h.takeBackup(t, cookie)
	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy offsite")
	var shipped shipResponse
	resp.into(t, &shipped)
	if shipped.Error != "" || len(shipped.Sent) != 1 || shipped.Sent[0].ID != taken.ID {
		t.Fatalf("the pass sent %+v (%s)", shipped.Sent, shipped.Error)
	}
	if keys := fake.Keys(); len(keys) != 1 || !strings.HasSuffix(keys[0], ".tar.gz"+backup.EncryptedExt) {
		t.Errorf("the bucket holds %v; the destination has a passphrase, so the archive is sealed", keys)
	}
}

// The two secrets follow the credential convention, and the difference between
// "leave it" and "clear it" is the difference between a sealed archive and a
// readable one -- so it is pinned rather than assumed.
func TestChangingADestinationLeavesTheSecretsItDoesNotMention(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	create := map[string]any{
		"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
		"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret", "passphrase": "a long passphrase",
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: create}).
		mustStatus(t, http.StatusCreated, "add a destination")

	// A PATCH about the retention says nothing about the secrets, so both stay.
	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"keep": 3}})
	resp.mustStatus(t, http.StatusOK, "change the retention")
	var patched controller.RemoteBackupStatus
	resp.into(t, &patched)
	if !patched.Encrypted || !patched.HasSecretKey || patched.Keep != 3 {
		t.Fatalf("the destination reads %+v after a change about the retention alone", patched)
	}

	// An explicit empty passphrase clears it, which is how a destination is
	// told to send the plain archive.
	resp = h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"passphrase": ""}})
	resp.mustStatus(t, http.StatusOK, "clear the passphrase")
	resp.into(t, &patched)
	if patched.Encrypted {
		t.Error("an explicit empty passphrase did not clear the stored one")
	}
	if !patched.HasSecretKey {
		t.Error("clearing the passphrase also cleared the secret key")
	}
}

// A destination the file describes is not editable here, and a stored one may
// not take a name the file has: the file has the last word, and a page that
// let somebody write a row which would then be ignored would be lying.
func TestTheConfigurationFileHasTheLastWordOnADestinationsName(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, func(c *config.Config) {
		c.Backup.Remotes = []config.BackupRemote{{
			Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(),
			AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
		}}
		c.Normalize()
	})
	cookie := h.platform()

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "a", "secret_access_key": "b",
		}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "add a destination the file already names")
	if !strings.Contains(string(resp.body), "zoomies.yaml") {
		t.Errorf("the refusal reads %s, which does not say where the other one is", string(resp.body))
	}

	// And editing the file's destination is refused with the same explanation
	// rather than a 404, which would read as "it is not there".
	resp = h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"keep": 3}})
	resp.mustStatus(t, http.StatusConflict, "edit a destination the file describes")

	// The page says which is which.
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 1 || listed.Remotes[0].Source != controller.RemoteSourceFile {
		t.Fatalf("the page shows %+v", listed.Remotes)
	}
}

// A destination that cannot work is refused with the reason under the field
// that is wrong, because the alternative is a form that saves and a bucket
// that never receives anything.
func TestADestinationThatCouldNotWorkIsRefusedByField(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()

	for _, tc := range []struct {
		name  string
		body  map[string]any
		field string
	}{
		{"no bucket", map[string]any{"name": "offsite", "endpoint": "https://s3.example.com", "secret_access_key": "s"}, "bucket"},
		{"an endpoint that is not a URL", map[string]any{"name": "offsite", "endpoint": "s3.example.com", "bucket": "b", "secret_access_key": "s"}, "endpoint"},
		{"no secret key", map[string]any{"name": "offsite", "endpoint": "https://s3.example.com", "bucket": "b"}, "secret_access_key"},
		{"a name that is not a name", map[string]any{"name": "Off Site!", "endpoint": "https://s3.example.com", "bucket": "b", "secret_access_key": "s"}, "name"},
		{"a name the API already uses", map[string]any{"name": "check", "endpoint": "https://s3.example.com", "bucket": "b", "secret_access_key": "s"}, "name"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: tc.body})
			resp.mustStatus(t, http.StatusUnprocessableEntity, tc.name)
			if !strings.Contains(string(resp.body), `"`+tc.field+`"`) {
				t.Errorf("the refusal is %s, which does not name the %s field", string(resp.body), tc.field)
			}
		})
	}
}

// Removing a destination forgets where the copies are; it does not delete
// them. An operator who meant the other thing removes them from the listing,
// where each one is named.
func TestRemovingADestinationLeavesTheCopiesInTheBucket(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
		}}).mustStatus(t, http.StatusCreated, "add a destination")

	h.takeBackup(t, cookie)
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie}).
		mustStatus(t, http.StatusOK, "copy offsite")
	if fake.Count() != 1 {
		t.Fatalf("the bucket holds %d copies before the destination is removed", fake.Count())
	}

	h.do(request{method: http.MethodDelete, path: "/api/v1/backups/remotes/offsite", cookie: cookie}).
		mustStatus(t, http.StatusNoContent, "remove the destination")
	if fake.Count() != 1 {
		t.Errorf("removing the destination deleted %d copies from the bucket", 1-fake.Count())
	}

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 0 {
		t.Errorf("the page still shows %+v", listed.Remotes)
	}
}

// "Backups are taken but never leave this host" is raised by the validator,
// which reads the configuration file and cannot see a destination stored in
// the database. Telling somebody to do a thing they have already done is how a
// page teaches them to stop reading it, so the settings API drops that finding
// once the fleet has a destination -- wherever it came from.
func TestTheNoRemoteFindingGoesAwayWhenADestinationIsAdded(t *testing.T) {
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, allowPrivateEgress)
	cookie := h.platform()

	codes := func() []string {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/settings", cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "read the settings")
		var out struct {
			Findings []struct {
				Code string `json:"code"`
			} `json:"findings"`
		}
		resp.into(t, &out)
		var found []string
		for _, f := range out.Findings {
			found = append(found, f.Code)
		}
		return found
	}

	if !slices.Contains(codes(), config.NoRemoteFinding) {
		t.Fatalf("a fleet whose backups never leave the host is not told: %v", codes())
	}

	h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie,
		body: map[string]any{
			"name": "offsite", "endpoint": fake.Endpoint(), "bucket": fake.Bucket(),
			"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
		}}).mustStatus(t, http.StatusCreated, "add a destination")

	if slices.Contains(codes(), config.NoRemoteFinding) {
		t.Errorf("the fleet added a destination and is still told its backups never leave the host: %v", codes())
	}

	// Switched off is not answered: a destination nothing is sent to is not a
	// destination.
	h.do(request{method: http.MethodPatch, path: "/api/v1/backups/remotes/offsite", cookie: cookie,
		body: map[string]any{"enabled": false}}).mustStatus(t, http.StatusOK, "switch it off")
	if !slices.Contains(codes(), config.NoRemoteFinding) {
		t.Errorf("a fleet whose only destination is switched off is told nothing: %v", codes())
	}
}

// allowPrivateEgress is what a harness needs to talk to a fake that httptest
// has bound to 127.0.0.1 -- the same switch an operator with a MinIO beside
// the controller sets, rather than a hole in the guard only tests can use.
func allowPrivateEgress(c *config.Config) { c.Security.AllowPrivateEgress = true }

// A destination on this machine or its network is somewhere the controller
// would send the whole fleet's backup and its access key on an
// administrator's say-so, so it is refused by field, naming the switch, and
// admitted once the platform has set it.
func TestADestinationOnAPrivateAddressIsRefusedUntilThePlatformAllowsIt(t *testing.T) {
	for _, tc := range []struct {
		name  string
		allow bool
		want  int
	}{
		{"refused by default", false, http.StatusUnprocessableEntity},
		{"admitted by security.allow_private_egress", true, http.StatusCreated},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, func(c *config.Config) { c.Security.AllowPrivateEgress = tc.allow })
			h.installation()
			cookie := h.platform()
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes", cookie: cookie, body: map[string]any{
				"name": "lan", "endpoint": "http://169.254.169.254", "bucket": "b",
				"access_key_id": "AKIAEXAMPLE", "secret_access_key": "secret",
			}})
			resp.mustStatus(t, tc.want, "create a destination at the metadata address")
			if tc.allow {
				return
			}
			if body := string(resp.body); !strings.Contains(body, `"field":"endpoint"`) || !strings.Contains(body, "security.allow_private_egress") {
				t.Errorf("the refusal does not name the field and the setting that would allow it: %s", body)
			}
		})
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// The Backups tab's offsite half. What these protect is the sequence an
// operator actually performs on the day the local copies are gone: see which
// destinations exist, prove one can be reached, look at what it holds, and
// bring a copy back -- landing as an ordinary backup, so that the restore is
// still the staged, confirmed one rather than something that happened inside a
// download.

// withRemote gives the harness a fleet whose backups go to a fake bucket.
func withRemote(t *testing.T) (*harness, *backup.FakeS3) {
	t.Helper()
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)
	h := newHarness(t, func(c *config.Config) {
		c.Backup.Remotes = []config.BackupRemote{{
			Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(), Prefix: "fleet",
			AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
		}}
		c.Normalize()
	})
	return h, fake
}

func TestABackupIsSentOffsiteListedThereAndBroughtBack(t *testing.T) {
	h, fake := withRemote(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	// The page says where copies go before any has gone.
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 1 || listed.Remotes[0].Name != "offsite" || listed.Remotes[0].Encrypted {
		t.Fatalf("the page shows %+v as its destinations", listed.Remotes)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/offsite/check", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "check the remote")
	var check remoteCheckResponse
	resp.into(t, &check)
	if !check.OK || check.Where != "backups/fleet" {
		t.Errorf("the check says %+v about a bucket that answers", check)
	}

	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy the backups offsite")
	var shipped shipResponse
	resp.into(t, &shipped)
	if shipped.Error != "" || len(shipped.Sent) != 1 || shipped.Sent[0].ID != taken.ID {
		t.Fatalf("the pass sent %+v (%s)", shipped.Sent, shipped.Error)
	}

	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups/remotes/offsite/copies", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list what the remote holds")
	var copies remoteCopiesResponse
	resp.into(t, &copies)
	if len(copies.Items) != 1 || copies.Items[0].ID != taken.ID || copies.Bytes == 0 {
		t.Fatalf("the remote lists %+v", copies)
	}
	if copies.Remote.Name != "offsite" {
		t.Errorf("the listing does not say which remote it came from: %+v", copies.Remote)
	}

	// The local copy goes, as it would if the disk had. What comes back is an
	// ordinary backup: verified, listed, and marked as having come from
	// offsite so that retention leaves it alone.
	if err := backup.Delete(h.ctrl.BackupDir(), taken.ID); err != nil {
		t.Fatalf("Delete: %v", err)
	}
	resp = h.do(request{
		method: http.MethodPost,
		path:   "/api/v1/backups/remotes/offsite/copies/" + taken.ID + "/fetch",
		cookie: cookie,
	})
	resp.mustStatus(t, http.StatusCreated, "bring the copy back")
	var back backupView
	resp.into(t, &back)
	if back.ID != taken.ID || back.Source != backup.SourceFetched || !back.Restorable {
		t.Fatalf("what came back reads %+v", back)
	}

	// And removing the offsite copy is a write, audited like any other.
	resp = h.do(request{
		method: http.MethodDelete,
		path:   "/api/v1/backups/remotes/offsite/copies/" + taken.ID,
		cookie: cookie,
	})
	resp.mustStatus(t, http.StatusNoContent, "remove the offsite copy")
	if fake.Count() != 0 {
		t.Errorf("the bucket still holds %d objects", fake.Count())
	}
}

// A bucket that refuses is not this API failing. The check reports it as a
// result, and the listing as a refusal the operator can act on -- both
// carrying the service's own words, because "500" is not a fix.
func TestARemoteThatRefusesIsReportedRatherThanHidden(t *testing.T) {
	h, fake := withRemote(t)
	cookie := h.platform()
	fake.BreakWith(http.StatusForbidden, "SignatureDoesNotMatch", "no")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/remotes/offsite/check", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "check a remote that refuses")
	var check remoteCheckResponse
	resp.into(t, &check)
	if check.OK || check.Error == "" {
		t.Fatalf("the check says %+v about a bucket that refused it", check)
	}

	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups/remotes/offsite/copies", cookie: cookie})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "list a remote that refuses")
}

// A name that is not a remote is a 404 rather than a 500, and a fleet with no
// remotes configured says so in its listing rather than pretending.
func TestAnUnknownRemoteIsNotFoundAndNoRemotesIsAnEmptyList(t *testing.T) {
	h, _ := withRemote(t)
	cookie := h.platform()
	for _, path := range []string{
		"/api/v1/backups/remotes/nowhere/copies",
		"/api/v1/backups/remotes/nowhere/check",
	} {
		method := http.MethodGet
		if path == "/api/v1/backups/remotes/nowhere/check" {
			method = http.MethodPost
		}
		resp := h.do(request{method: method, path: path, cookie: cookie})
		resp.mustStatus(t, http.StatusNotFound, "a remote that is not configured")
	}

	plain := newHarness(t)
	resp := plain.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: plain.platform()})
	resp.mustStatus(t, http.StatusOK, "list backups with no remotes")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Remotes) != 0 {
		t.Errorf("a fleet with no remotes reports %+v", listed.Remotes)
	}
}

// Retention on demand, which exists because lowering the number of copies a
// fleet keeps otherwise does nothing at all until the next backup -- and on a
// fleet with the schedule off, nothing ever. The route has to reach both
// halves, and say what it removed from each: the local ceiling and the
// bucket's are separate numbers and a single total would read as a fault.
func TestRetentionIsAppliedOnDemandToBothHalves(t *testing.T) {
	h, fake := withRemote(t)
	h.installation()
	cookie := h.platform()

	h.ctrl.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 0 })
	var taken []string
	for range 3 {
		taken = append(taken, h.takeBackup(t, cookie).ID)
		// The directory name carries the clock's second.
		time.Sleep(1100 * time.Millisecond)
	}
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/offsite", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "copy the backups offsite")
	if got := fake.Count(); got != 3 {
		t.Fatalf("setting up: the bucket holds %d copies", got)
	}

	h.ctrl.UpdateConfig(func(c *config.Config) {
		c.Backup.Keep = 1
		c.Backup.Remotes[0].Keep = 2
	})
	resp = h.do(request{method: http.MethodPost, path: "/api/v1/backups/prune", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "apply retention")
	var report controller.BackupPruning
	resp.into(t, &report)

	if report.Keep != 1 || len(report.Removed) != 2 || report.Error != "" {
		t.Errorf("the local half of the report reads %+v", report)
	}
	if len(report.Remotes) != 1 || report.Remotes[0].Keep != 2 || len(report.Remotes[0].Removed) != 1 {
		t.Fatalf("the offsite half of the report reads %+v", report.Remotes)
	}
	if got := fake.Count(); got != 2 {
		t.Errorf("the bucket holds %d copies with keep: 2", got)
	}

	// And the page agrees: one backup left here, the newest.
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Items) != 1 || listed.Items[0].ID != taken[len(taken)-1] {
		t.Errorf("the page lists %d backups after retention was applied", len(listed.Items))
	}
}

// Pruning deletes copies of the whole fleet, so it is a write rather than
// something a read-only token can set off.
func TestRetentionOnDemandNeedsTheAdministratorRole(t *testing.T) {
	h, _ := withRemote(t)
	h.installation()
	u, _ := h.user("viewer", store.RoleViewer)
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/prune", cookie: h.session(u)})
	resp.mustStatus(t, http.StatusForbidden, "prune as a viewer")
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/store"
)

// The Backups tab is the one place in the product where a copy of the whole
// database leaves the machine and where one comes back to replace the fleet,
// so what these tests protect is the sequence: a backup taken from the page is
// the same backup the command line restores, a download round-trips through
// an upload, and a restore is staged with every check made now and nothing
// moved until the restart.

// admin is a signed-in administrator's cookie.
// platform is a session for the role the backup routes now need. A backup is
// the whole database under the key this host holds, so it belongs to whoever
// runs the process rather than to the fleet's administrator.
func (h *harness) platform() string {
	h.t.Helper()
	u, _ := h.user("platform", store.RolePlatform)
	return h.session(u)
}

// takeBackup presses the button and returns what the page would show.
func (h *harness) takeBackup(t *testing.T, cookie string) backupView {
	t.Helper()
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusCreated, "take a backup")
	var v backupView
	resp.into(t, &v)
	return v
}

func TestABackupTakenFromThePageIsListedWithWhatARestoreNeedsToKnow(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()

	taken := h.takeBackup(t, cookie)
	if taken.Source != backup.SourceManual || taken.TakenBy != "platform" || taken.Bytes == 0 {
		t.Errorf("taken = %+v", taken)
	}
	if taken.KeyMatches == nil || !*taken.KeyMatches || taken.Secrets != 1 || !taken.Restorable {
		t.Errorf("the row does not say the key matches and the backup is restorable: %+v", taken)
	}

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "list backups")
	var listed backupsResponse
	resp.into(t, &listed)
	if len(listed.Items) != 1 || listed.Items[0].ID != taken.ID {
		t.Fatalf("listed = %+v", listed.Items)
	}
	if listed.Directory != h.ctrl.BackupDir() || listed.DatabaseBytes == 0 && listed.Directory == "" {
		t.Errorf("the page does not know where backups go: %+v", listed)
	}
	if !listed.Schedule.Enabled || listed.Schedule.Interval != "24h" || listed.Schedule.NextDueAt == nil {
		t.Errorf("schedule = %+v", listed.Schedule)
	}
	if listed.StagedRestore != nil || listed.LastRestore != nil || listed.Restarting {
		t.Errorf("a fresh instance claims a restore is in progress: %+v", listed)
	}

	// The manifest on disk is the one the command line reads.
	m, err := backup.ReadManifest(filepath.Join(listed.Directory, taken.ID))
	if err != nil || m.Source != backup.SourceManual {
		t.Errorf("the backup on disk is not what the page reported: %+v, %v", m, err)
	}

	// And the whole page's shape is what the contract promises.
	doc := loadSpec(t)
	assertShape(t, doc, "Backups", resp.body)
	one := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	one.mustStatus(t, http.StatusOK, "get backup")
	assertShape(t, doc, "Backup", one.body)
}

// A download is the backup leaving the machine and an upload is it coming
// back, so the two have to agree exactly: plain, and encrypted with a
// passphrase that is then required.
func TestADownloadRoundTripsThroughAnUploadPlainAndEncrypted(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	plain := h.do(request{method: http.MethodGet, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie})
	plain.mustStatus(t, http.StatusOK, "download")
	if cd := plain.header.Get("Content-Disposition"); !strings.Contains(cd, taken.ID+".tar.gz") {
		t.Errorf("Content-Disposition = %q", cd)
	}
	if !bytes.HasPrefix(plain.body, []byte("\x1f\x8b")) {
		t.Fatal("the download is not a gzipped archive")
	}

	enc := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie,
		body: map[string]any{"passphrase": "correct horse battery staple"}})
	enc.mustStatus(t, http.StatusOK, "encrypted download")
	if cd := enc.header.Get("Content-Disposition"); !strings.Contains(cd, ".tar.gz.enc") {
		t.Errorf("Content-Disposition = %q", cd)
	}
	if bytes.HasPrefix(enc.body, []byte("\x1f\x8b")) || bytes.Contains(enc.body, []byte("manifest.json")) {
		t.Fatal("the encrypted download is readable")
	}
	short := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/download", cookie: cookie,
		body: map[string]any{"passphrase": "1234"}})
	short.mustStatus(t, http.StatusUnprocessableEntity, "a four-character passphrase")

	// The original gone, both come back under the original's name.
	del := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	del.mustStatus(t, http.StatusNoContent, "delete")

	up := h.upload(t, cookie, "backup.tar.gz", plain.body, "")
	up.mustStatus(t, http.StatusCreated, "plain upload")
	var uploaded backupView
	up.into(t, &uploaded)
	if uploaded.ID != taken.ID || uploaded.Source != backup.SourceUploaded || uploaded.TakenBy != "platform" {
		t.Errorf("uploaded = %+v", uploaded)
	}

	wrong := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "not the passphrase")
	wrong.mustStatus(t, http.StatusUnprocessableEntity, "encrypted upload with the wrong passphrase")
	if msg := string(wrong.body); !strings.Contains(msg, "passphrase") {
		t.Errorf("the refusal does not name the passphrase: %s", msg)
	}
	missing := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "")
	missing.mustStatus(t, http.StatusUnprocessableEntity, "encrypted upload with no passphrase")

	right := h.upload(t, cookie, "backup.tar.gz.enc", enc.body, "correct horse battery staple")
	right.mustStatus(t, http.StatusCreated, "encrypted upload")
	var second backupView
	right.into(t, &second)
	if second.ID == uploaded.ID || !strings.HasPrefix(second.ID, taken.ID) {
		t.Errorf("a second upload of the same backup landed as %s", second.ID)
	}

	// The uploads are audited as what they are, and so was the download.
	audit := h.do(request{method: http.MethodGet, path: "/api/v1/audit?action=backup.download&action=backup.upload", cookie: cookie})
	audit.mustStatus(t, http.StatusOK, "audit")
	var rows struct {
		Total int `json:"total"`
	}
	audit.into(t, &rows)
	if rows.Total != 4 {
		t.Errorf("audit rows = %d, want two downloads and two uploads", rows.Total)
	}
}

// Garbage in is refused as garbage, and nothing lands in the directory.
func TestAnUploadThatIsNotABackupIsRefused(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	resp := h.upload(t, cookie, "notes.txt", []byte("not an archive"), "")
	resp.mustStatus(t, http.StatusUnprocessableEntity, "upload of a text file")
	if !strings.Contains(string(resp.body), "gzipped") {
		t.Errorf("the refusal does not say what was wrong: %s", resp.body)
	}
	if entries, _ := os.ReadDir(h.ctrl.BackupDir()); len(entries) != 0 {
		t.Errorf("something was left behind: %v", entries)
	}
	raw := h.do(request{method: http.MethodPost, path: "/api/v1/backups/upload", cookie: cookie,
		rawBody: "raw bytes", headers: map[string]string{"Content-Type": "application/octet-stream"}})
	raw.mustStatus(t, http.StatusBadRequest, "a non-multipart upload")
}

// upload posts a multipart form the way the page does.
func (h *harness) upload(t *testing.T, cookie, filename string, archive []byte, passphrase string) *response {
	t.Helper()
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	if passphrase != "" {
		if err := mw.WriteField("passphrase", passphrase); err != nil {
			t.Fatal(err)
		}
	}
	fw, err := mw.CreateFormFile("file", filename)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := fw.Write(archive); err != nil {
		t.Fatal(err)
	}
	if err := mw.Close(); err != nil {
		t.Fatal(err)
	}
	return h.do(request{method: http.MethodPost, path: "/api/v1/backups/upload", cookie: cookie,
		rawBody: body.String(), headers: map[string]string{"Content-Type": mw.FormDataContentType()}})
}

// Verify re-reads the file. A backup somebody has altered has to come back as
// not OK with a sentence, not as a 500.
func TestVerifyNoticesAnAlteredBackup(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	ok := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/verify", cookie: cookie})
	ok.mustStatus(t, http.StatusOK, "verify")
	var v backup.Verification
	ok.into(t, &v)
	if !v.OK || !v.DigestMatches {
		t.Errorf("a fresh backup does not verify: %+v", v)
	}
	assertShape(t, loadSpec(t), "BackupVerification", ok.body)

	db := filepath.Join(h.ctrl.BackupDir(), taken.ID, backup.DBName)
	f, err := os.OpenFile(db, os.O_WRONLY|os.O_APPEND, 0)
	if err != nil {
		t.Fatal(err)
	}
	_, _ = f.Write([]byte("altered"))
	f.Close()
	bad := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/verify", cookie: cookie})
	bad.mustStatus(t, http.StatusOK, "verify an altered backup")
	bad.into(t, &v)
	if v.OK || v.DigestMatches || len(v.Problems) == 0 {
		t.Errorf("an altered backup verified: %+v", v)
	}
}

// Staging is the whole of what the page can do about a restore, and it is
// checked now: the wrong key is refused with the sentence, a good backup is
// written down for the next start, the page says so, and cancelling forgets it.
func TestARestoreIsStagedWithEveryCheckMadeNowAndNothingMoved(t *testing.T) {
	h := newHarness(t)
	h.installation()
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)

	// A backup that says it was sealed with another key.
	other := h.takeBackup(t, cookie)
	manifestPath := filepath.Join(h.ctrl.BackupDir(), other.ID, backup.ManifestName)
	raw, _ := os.ReadFile(manifestPath)
	var m map[string]any
	_ = json.Unmarshal(raw, &m)
	m["key"] = map[string]any{"fingerprint": "deadbeefcafe", "from": "elsewhere"}
	raw, _ = json.Marshal(m)
	_ = os.WriteFile(manifestPath, raw, 0o600)

	listed := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	var page backupsResponse
	listed.into(t, &page)
	for _, item := range page.Items {
		if item.ID == other.ID && (item.Restorable || !strings.Contains(item.RestoreProblem, "deadbeefcafe")) {
			t.Errorf("the list does not warn about the wrong key: %+v", item)
		}
	}
	refused := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + other.ID + "/restore", cookie: cookie})
	refused.mustStatus(t, http.StatusUnprocessableEntity, "restore with the wrong key")
	if !strings.Contains(refused.errorMessage(t)+string(refused.body), "not the one that sealed this backup") {
		t.Errorf("the refusal does not say why: %s", refused.body)
	}
	// Nothing to apply yet, and a restart with nothing to apply is refused.
	nothing := h.do(request{method: http.MethodPost, path: "/api/v1/backups/restore/apply", cookie: cookie})
	nothing.mustStatus(t, http.StatusConflict, "apply with nothing staged")

	staged := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/restore", cookie: cookie,
		body: map[string]any{"revoke_api_tokens": true}})
	staged.mustStatus(t, http.StatusAccepted, "stage a restore")
	assertShape(t, loadSpec(t), "StagedRestore", staged.body)
	var s backup.Staged
	staged.into(t, &s)
	if s.BackupID != taken.ID || s.RequestedBy != "platform" || !s.RevokeAPITokens || s.ResetAgentTokens {
		t.Errorf("staged = %+v", s)
	}
	// The live database is untouched: the fleet is still running on it.
	if f := h.ctrl.Fenced(); f.Fenced {
		t.Error("staging fenced the running fleet")
	}
	// The staged backup cannot be deleted from under the restart.
	held := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/" + taken.ID, cookie: cookie})
	held.mustStatus(t, http.StatusConflict, "delete a staged backup")
	// A second backup cannot be staged over it.
	over := h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + other.ID + "/restore", cookie: cookie})
	over.mustStatus(t, http.StatusConflict, "stage a second restore")

	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.StagedRestore == nil || page.StagedRestore.BackupID != taken.ID {
		t.Errorf("the page does not show the staged restore: %+v", page.StagedRestore)
	}
	problems := h.do(request{method: http.MethodGet, path: "/api/v1/problems", cookie: cookie})
	if !strings.Contains(string(problems.body), "backup.restore_staged") {
		t.Error("the staged restore is not in the problems drawer")
	}

	cancel := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore", cookie: cookie})
	cancel.mustStatus(t, http.StatusNoContent, "cancel")
	if staged, _ := backup.LoadStaged(h.ctrl.DatabasePath()); staged != nil {
		t.Error("the staged restore survived being cancelled")
	}
	again := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore", cookie: cookie})
	again.mustStatus(t, http.StatusNoContent, "cancel when nothing is staged")
}

// Applying is the one act that stops the process. It answers before it does,
// and the command that runs the controller sees the request.
func TestApplyingAStagedRestoreAsksForARestart(t *testing.T) {
	h := newHarness(t)
	cookie := h.platform()
	taken := h.takeBackup(t, cookie)
	h.do(request{method: http.MethodPost, path: "/api/v1/backups/" + taken.ID + "/restore", cookie: cookie}).
		mustStatus(t, http.StatusAccepted, "stage")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/backups/restore/apply", cookie: cookie})
	resp.mustStatus(t, http.StatusAccepted, "apply")
	assertShape(t, loadSpec(t), "Restarting", resp.body)
	select {
	case <-h.ctrl.RestartRequested():
	default:
		t.Fatal("the controller was not asked to restart")
	}
	listed := h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	var page backupsResponse
	listed.into(t, &page)
	if !page.Restarting {
		t.Error("the page does not say the controller is restarting")
	}

	// The next start applies it, and the outcome is what the page shows.
	outcome, err := backup.ApplyStaged(context.Background(), h.cfg, nil)
	if err != nil || outcome == nil || !outcome.OK {
		t.Fatalf("ApplyStaged = %+v, %v", outcome, err)
	}
	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.LastRestore == nil || !page.LastRestore.OK || page.LastRestore.BackupID != taken.ID {
		t.Errorf("last restore = %+v", page.LastRestore)
	}
	dismiss := h.do(request{method: http.MethodDelete, path: "/api/v1/backups/restore/outcome", cookie: cookie})
	dismiss.mustStatus(t, http.StatusNoContent, "dismiss")
	listed = h.do(request{method: http.MethodGet, path: "/api/v1/backups", cookie: cookie})
	listed.into(t, &page)
	if page.LastRestore != nil {
		t.Error("the outcome survived being dismissed")
	}
}

