package api

import (
	"bytes"
	"compress/gzip"
	"io"
	"mime"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// gzipMinSize is the smallest body worth compressing. Below this the gzip
// header and the round trip through the encoder cost more than they save, and
// a 200-byte error body would arrive larger than it left.
const gzipMinSize = 1024

// acceptsGzip reports whether the client will take a gzip body. It reads the
// q-values, because "gzip;q=0" is a refusal and a substring match would send a
// client that said so a body it asked not to have.
func acceptsGzip(r *http.Request) bool {
	for _, part := range strings.Split(strings.Join(r.Header.Values("Accept-Encoding"), ","), ",") {
		coding, params, _ := strings.Cut(strings.TrimSpace(part), ";")
		if !strings.EqualFold(strings.TrimSpace(coding), "gzip") {
			continue
		}
		q := 1.0
		if _, v, ok := strings.Cut(params, "="); ok {
			if f, err := strconv.ParseFloat(strings.TrimSpace(v), 64); err == nil {
				q = f
			}
		}
		return q > 0
	}
	return false
}

// compressibleType is whether a response of this media type is text a gzip
// body suits. Anything already compressed (an archive, an image) or streamed
// (text/event-stream, the log relay's text/plain chunks) is left alone.
func compressibleType(contentType string) bool {
	media, _, err := mime.ParseMediaType(contentType)
	if err != nil {
		return false
	}
	switch media {
	case "application/json", "application/yaml", "application/x-yaml", "text/csv":
		return true
	}
	return false
}

var gzipWriters = sync.Pool{New: func() any {
	zw, _ := gzip.NewWriterLevel(io.Discard, 5)
	return zw
}}

// gzipPath says which requests may have their answers compressed at all.
//
// The answer is no for anything that carries a credential. Compressing a body
// that mixes a secret with text an attacker can influence is the BREACH
// pattern, and the session endpoint, token creation and the sign-in handshake
// are exactly the bodies that do. Excluding them costs nothing -- they are a
// few hundred bytes -- and leaves the question of whether a given body is safe
// to compress to the only people who can answer it: whoever adds an endpoint
// here has to decide, rather than inherit a yes.
func gzipPath(p string) bool {
	for _, prefix := range []string{
		"/api/v1/auth/", "/api/v1/tokens", "/api/v1/join-tokens", "/api/v1/users",
		"/api/v1/mcp-clients", "/api/v1/mcp-connections", "/api/v1/backups",
		"/api/v1/agent/", "/api/v1/events",
	} {
		if strings.HasPrefix(p, prefix) {
			return false
		}
	}
	return true
}

// compressResponses gzips JSON and CSV answers to GET requests that ask for it.
//
// It decides at the moment the handler commits to a status, from what the
// handler said about the body: the media type and, for the handlers that know
// it (writeJSON does), the length. Everything else -- a stream, an archive, a
// body declared too small to be worth it, a response that is already encoded --
// passes through untouched, still flushable, which is what keeps the event stream and
// the log relay working behind it.
func compressResponses(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet || !gzipPath(r.URL.Path) || !acceptsGzip(r) {
			next.ServeHTTP(w, r)
			return
		}
		// A cache that stores the identity body must not serve it to a client
		// that wanted gzip, nor the reverse.
		w.Header().Add("Vary", "Accept-Encoding")
		cw := &compressWriter{ResponseWriter: w}
		defer cw.finish()
		next.ServeHTTP(cw, r)
	})
}

type compressWriter struct {
	http.ResponseWriter
	zw      *gzip.Writer
	decided bool
}

func (c *compressWriter) decide(status int) {
	if c.decided {
		return
	}
	c.decided = true
	h := c.Header()
	if status != http.StatusOK || h.Get("Content-Encoding") != "" || !compressibleType(h.Get("Content-Type")) {
		return
	}
	// A declared length is the best evidence of size, and a body under the
	// threshold is not worth the encoder. A handler that declared none wrote a
	// body it did not buffer -- the CSV and YAML exports, which are among the
	// largest answers there are -- and the media types this accepts are never
	// streams (those are text/event-stream and the log relay's text/plain, which
	// compressibleType refuses), so it is compressed from the first byte.
	if declared := h.Get("Content-Length"); declared != "" {
		if n, err := strconv.Atoi(declared); err != nil || n < gzipMinSize {
			return
		}
	}
	h.Del("Content-Length")
	h.Set("Content-Encoding", "gzip")
	zw := gzipWriters.Get().(*gzip.Writer)
	zw.Reset(c.ResponseWriter)
	c.zw = zw
}

func (c *compressWriter) WriteHeader(status int) {
	c.decide(status)
	c.ResponseWriter.WriteHeader(status)
}

func (c *compressWriter) Write(p []byte) (int, error) {
	c.decide(http.StatusOK)
	if c.zw != nil {
		return c.zw.Write(p)
	}
	return c.ResponseWriter.Write(p)
}

// Flush keeps http.Flusher working for the responses that pass through, and
// is what http.ResponseController reaches for.
func (c *compressWriter) Flush() {
	c.decide(http.StatusOK)
	if c.zw != nil {
		_ = c.zw.Flush()
	}
	// Through the controller, not a type assertion: the writers above this one
	// (the access log's, for one) reach the connection by Unwrap and do not
	// all implement http.Flusher themselves.
	_ = http.NewResponseController(c.ResponseWriter).Flush()
}

// Unwrap lets http.NewResponseController reach the connection beneath, for
// the deadlines and hijacks the streaming handlers ask for.
func (c *compressWriter) Unwrap() http.ResponseWriter { return c.ResponseWriter }

func (c *compressWriter) finish() {
	if c.zw == nil {
		return
	}
	_ = c.zw.Close()
	gzipWriters.Put(c.zw)
	c.zw = nil
}

// gzipBody compresses a static body once, at the best ratio, for the UI's
// files: they are served thousands of times and compressed once.
func gzipBody(body []byte) []byte {
	var buf bytes.Buffer
	zw, _ := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	_, _ = zw.Write(body)
	_ = zw.Close()
	return buf.Bytes()
}

package api

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"testing"
	"testing/fstest"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func gunzip(t *testing.T, b []byte) []byte {
	t.Helper()
	zr, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		t.Fatalf("the body is not gzip: %v", err)
	}
	out, err := io.ReadAll(zr)
	if err != nil {
		t.Fatalf("reading the gzip body: %v", err)
	}
	return out
}

func TestAcceptEncodingIsReadByItsQValues(t *testing.T) {
	for header, want := range map[string]bool{
		"":                         false,
		"gzip":                     true,
		"br, gzip;q=0.8":           true,
		"deflate, GZIP":            true,
		"gzip;q=0":                 false,
		"identity":                 false,
		"br":                       false,
		"x-gzip-not-really, other": false,
	} {
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		if header != "" {
			r.Header.Set("Accept-Encoding", header)
		}
		if got := acceptsGzip(r); got != want {
			t.Errorf("acceptsGzip(%q) = %v, want %v", header, got, want)
		}
	}
}

// The UI's files are the bulk of a first visit, and they are served from the
// binary as they were embedded -- uncompressed until this. A client that asks
// gets a gzip body that decodes to the file; one that does not, or one that
// refuses it by q-value, or one that asks for a byte range, gets the file.
func TestStaticFilesAreServedGzippedToClientsThatAsk(t *testing.T) {
	script := strings.Repeat("export const answer = 42; // padding that compresses well\n", 200)
	h := &spaHandler{
		files: fstest.MapFS{
			"index.html":        {Data: []byte("<html></html>")},
			"assets/app.abc.js": {Data: []byte(script)},
			"assets/font.woff2": {Data: []byte(strings.Repeat("x", 4000))},
			"assets/tiny.js":    {Data: []byte("1")},
		},
		index:   []byte("<html></html>"),
		modTime: buildTime(),
		gz:      &sync.Map{},
	}
	get := func(path string, headers map[string]string) *httptest.ResponseRecorder {
		r := httptest.NewRequest(http.MethodGet, path, nil)
		for k, v := range headers {
			r.Header.Set(k, v)
		}
		w := httptest.NewRecorder()
		h.ServeHTTP(w, r)
		return w
	}

	gz := get("/assets/app.abc.js", map[string]string{"Accept-Encoding": "gzip"})
	if gz.Code != http.StatusOK || gz.Header().Get("Content-Encoding") != "gzip" {
		t.Fatalf("status %d, Content-Encoding %q; want a gzip body", gz.Code, gz.Header().Get("Content-Encoding"))
	}
	if got := string(gunzip(t, gz.Body.Bytes())); got != script {
		t.Fatal("the gzip body does not decode to the file")
	}
	if gz.Body.Len() >= len(script)/4 {
		t.Errorf("the body is %d bytes for a %d-byte script; it was not compressed", gz.Body.Len(), len(script))
	}
	if !strings.Contains(gz.Header().Get("Cache-Control"), "immutable") {
		t.Errorf("Cache-Control = %q; the hashed asset lost its year-long cache", gz.Header().Get("Cache-Control"))
	}
	if n, _ := strconv.Atoi(gz.Header().Get("Content-Length")); n != gz.Body.Len() {
		t.Errorf("Content-Length %d does not describe the %d bytes sent", n, gz.Body.Len())
	}
	if !strings.Contains(gz.Header().Get("Vary"), "Accept-Encoding") {
		t.Errorf("Vary = %q; a shared cache would serve one encoding to everyone", gz.Header().Get("Vary"))
	}

	for name, headers := range map[string]map[string]string{
		"no Accept-Encoding": nil,
		"gzip;q=0":           {"Accept-Encoding": "gzip;q=0"},
		"a byte range":       {"Accept-Encoding": "gzip", "Range": "bytes=0-9"},
	} {
		w := get("/assets/app.abc.js", headers)
		if w.Header().Get("Content-Encoding") != "" {
			t.Errorf("%s was answered with Content-Encoding %q", name, w.Header().Get("Content-Encoding"))
		}
		if name != "a byte range" && w.Body.String() != script {
			t.Errorf("%s did not get the file as it is", name)
		}
		if !strings.Contains(w.Header().Get("Vary"), "Accept-Encoding") {
			t.Errorf("%s: the identity answer must say Vary too, or a cache will keep it for everybody", name)
		}
	}

	// Fonts are already compressed and a one-byte file is not worth it.
	for _, name := range []string{"/assets/font.woff2", "/assets/tiny.js"} {
		w := get(name, map[string]string{"Accept-Encoding": "gzip"})
		if w.Header().Get("Content-Encoding") != "" {
			t.Errorf("%s was compressed", name)
		}
	}
}

func TestAPIAnswersAreGzippedWhenTheyAreWorthIt(t *testing.T) {
	h := newHarness(t)
	token := h.token("reader", store.RoleViewer)
	inst := h.installation()

	small := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: token,
		headers: map[string]string{"Accept-Encoding": "gzip"}})
	small.mustStatus(t, http.StatusOK, "GET /pools with none")
	if small.header.Get("Content-Encoding") != "" {
		t.Error("an answer under a kilobyte was compressed")
	}

	for i := 0; i < 20; i++ {
		h.pool(inst, "pool-"+strconv.Itoa(i))
	}
	plain := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: token})
	plain.mustStatus(t, http.StatusOK, "GET /pools")
	if plain.header.Get("Content-Encoding") != "" || len(plain.body) < gzipMinSize {
		t.Fatalf("the fixture is wrong: encoding %q, %d bytes", plain.header.Get("Content-Encoding"), len(plain.body))
	}

	gz := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: token,
		headers: map[string]string{"Accept-Encoding": "gzip"}})
	gz.mustStatus(t, http.StatusOK, "GET /pools, gzip")
	if gz.header.Get("Content-Encoding") != "gzip" {
		t.Fatalf("Content-Encoding = %q, want gzip", gz.header.Get("Content-Encoding"))
	}
	if !strings.Contains(gz.header.Get("Vary"), "Accept-Encoding") {
		t.Errorf("Vary = %q", gz.header.Get("Vary"))
	}
	var a, b map[string]any
	if err := json.Unmarshal(gunzip(t, gz.body), &a); err != nil {
		t.Fatalf("the gzip body is not JSON: %v", err)
	}
	if err := json.Unmarshal(plain.body, &b); err != nil {
		t.Fatal(err)
	}
	if len(a["items"].([]any)) != 20 || len(b["items"].([]any)) != 20 {
		t.Fatal("compression changed what the list says")
	}
	if len(gz.body) >= len(plain.body) {
		t.Errorf("the gzip body (%d bytes) is not smaller than the plain one (%d)", len(gz.body), len(plain.body))
	}
}

// The three kinds of body that must never be compressed: anything that carries
// a credential (BREACH), anything that is not a GET, and a stream, which has to
// reach the client as it is written rather than when the encoder's buffer fills.
func TestCompressionLeavesCredentialsAndStreamsAlone(t *testing.T) {
	big := []byte(`{"csrf":"` + strings.Repeat("a", 2000) + `"}`)
	json200 := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.Header().Set("Content-Length", strconv.Itoa(len(big)))
		_, _ = w.Write(big)
	})
	h := compressResponses(json200)
	for _, tc := range []struct {
		method, path string
		want         bool
	}{
		{http.MethodGet, "/api/v1/pools", true},
		{http.MethodGet, "/api/v1/auth/session", false},
		{http.MethodGet, "/api/v1/tokens", false},
		{http.MethodGet, "/api/v1/join-tokens", false},
		{http.MethodGet, "/api/v1/backups", false},
		{http.MethodPost, "/api/v1/pools", false},
	} {
		r := httptest.NewRequest(tc.method, tc.path, nil)
		r.Header.Set("Accept-Encoding", "gzip")
		w := httptest.NewRecorder()
		h.ServeHTTP(w, r)
		if got := w.Header().Get("Content-Encoding") == "gzip"; got != tc.want {
			t.Errorf("%s %s compressed = %v, want %v", tc.method, tc.path, got, tc.want)
		}
	}

	// An export written without a declared length -- the usage CSV is one -- is
	// the biggest kind of answer there is, and has to be compressed too.
	csv := compressResponses(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
		_, _ = io.WriteString(w, "pool,jobs\n")
		_, _ = w.Write(bytes.Repeat([]byte("pool-a,12\n"), 500))
	}))
	r := httptest.NewRequest(http.MethodGet, "/api/v1/usage.csv", nil)
	r.Header.Set("Accept-Encoding", "gzip")
	w := httptest.NewRecorder()
	csv.ServeHTTP(w, r)
	if w.Header().Get("Content-Encoding") != "gzip" {
		t.Error("a CSV written without a Content-Length was not compressed")
	} else if got := gunzip(t, w.Body.Bytes()); !bytes.HasPrefix(got, []byte("pool,jobs\npool-a,12\n")) || len(got) != len("pool,jobs\n")+500*len("pool-a,12\n") {
		t.Errorf("the compressed CSV does not decode to what was written (%d bytes)", len(got))
	}

	// A stream: the first event must be readable while the handler is still
	// holding the connection open.
	release := make(chan struct{})
	stream := compressResponses(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		_, _ = io.WriteString(w, "event: ping\n\n")
		w.(http.Flusher).Flush()
		<-release
	}))
	srv := httptest.NewServer(stream)
	defer srv.Close()
	defer close(release)
	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/api/v1/logs", nil)
	req.Header.Set("Accept-Encoding", "gzip")
	resp, err := http.DefaultTransport.RoundTrip(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.Header.Get("Content-Encoding") != "" {
		t.Fatal("a stream was compressed")
	}
	buf := make([]byte, 13)
	if _, err := io.ReadFull(resp.Body, buf); err != nil || string(buf) != "event: ping\n\n" {
		t.Fatalf("the first event did not arrive while the stream was open: %q, %v", buf, err)
	}
}

// onlyUnwrap is a ResponseWriter like the access log's: it reaches the
// connection by Unwrap and does not implement http.Flusher itself.
type onlyUnwrap struct{ inner http.ResponseWriter }

func (o onlyUnwrap) Header() http.Header         { return o.inner.Header() }
func (o onlyUnwrap) Write(p []byte) (int, error) { return o.inner.Write(p) }
func (o onlyUnwrap) WriteHeader(code int)        { o.inner.WriteHeader(code) }
func (o onlyUnwrap) Unwrap() http.ResponseWriter { return o.inner }

// A stream flushed through a writer that only unwraps used to hang: the
// compression layer looked for http.Flusher underneath it, did not find one,
// and held the first frame back for ever. Every live view in the UI is such a
// stream.
func TestAStreamFlushesThroughWritersThatOnlyUnwrap(t *testing.T) {
	release := make(chan struct{})
	stream := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		w.WriteHeader(http.StatusOK)
		if err := http.NewResponseController(w).Flush(); err != nil {
			t.Errorf("Flush: %v", err)
		}
		<-release
	})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		compressResponses(stream).ServeHTTP(onlyUnwrap{w}, r)
	}))
	defer srv.Close()
	defer close(release)

	req, _ := http.NewRequest(http.MethodGet, srv.URL+"/api/v1/runners/run_1/logs", nil)
	req.Header.Set("Accept-Encoding", "gzip")
	done := make(chan error, 1)
	go func() {
		resp, err := http.DefaultTransport.RoundTrip(req)
		if err == nil {
			resp.Body.Close()
		}
		done <- err
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("the response headers never arrived: the flush did not reach the connection")
	}
}

package api

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The support bundle is the document an operator attaches to a bug report, so
// what these tests protect is what a stranger reading it can work out: that
// the fleet is described, that a section which could not be gathered says so
// by name rather than taking the rest of the document with it, and that no
// workflow log body is in there for either of them to have to think about.

func TestTheBundleDescribesTheInstanceAndTheFleet(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	h.runner(pool, host, store.RunnerBusy)
	h.job(pool, store.JobQueued)
	// Platform: this is about what a whole bundle carries, and the whole one
	// is the platform's. What a fleet's administrator gets instead -- the
	// build it all ran on, and not the machine -- is
	// TestTheFleetsBundleIdentifiesTheBuildAndNotTheMachine.
	u, _ := h.user("admin", store.RolePlatform)
	cookie := h.session(u)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "support bundle")

	var b supportBundle
	resp.into(t, &b)

	if len(b.Errors) != 0 {
		t.Errorf("a healthy instance produced section errors: %+v", b.Errors)
	}
	if b.BundleVersion != bundleVersion {
		t.Errorf("bundle_version = %d, want %d", b.BundleVersion, bundleVersion)
	}
	if b.GeneratedAt.IsZero() {
		t.Error("the bundle does not say when it was taken, which is the first thing a reader asks")
	}
	// The build and the process. A bug report without them is a report about
	// an unknown binary.
	if b.Instance.Go == "" || b.Instance.OS == "" || b.Instance.Goroutines == 0 {
		t.Errorf("the instance section is not describing this process: %+v", b.Instance)
	}
	if b.Instance.SchemaApplied == 0 {
		t.Error("the instance section does not say which migrations this database has taken")
	}
	// The fleet.
	if len(b.Pools) == 0 || len(b.Hosts) == 0 || len(b.Runners) == 0 || len(b.Installations) == 0 {
		t.Errorf("the bundle is missing a fleet section: %d pools, %d hosts, %d runners, %d installations",
			len(b.Pools), len(b.Hosts), len(b.Runners), len(b.Installations))
	}
	if b.Config == nil {
		t.Error("the bundle carries no configuration, which is half of every support case")
	}
	if b.Problems == nil {
		t.Error("the bundle carries no problems section")
	}

	// The work in flight, with the controller's own answer beside it -- the
	// same answer the drawer and the CLI render, so a bundle and the page the
	// operator was looking at cannot disagree.
	if len(b.Jobs) == 0 {
		t.Fatal("the queued job is not in the bundle")
	}
	if len(b.Explanations) == 0 {
		t.Fatal("the queued job has no explanation in the bundle")
	}
	if b.Explanations[0].Summary == "" {
		t.Error("the explanation carries no sentence")
	}
}

// A bundle is taken at the moment a query is most likely to fail, so a section
// that cannot be gathered costs its own contents and nothing else. Before this,
// the alternative was a 500: a support case with no document at all, on the one
// instance whose trouble somebody was trying to report.
func TestABundleSurvivesTheSectionsItCannotGather(t *testing.T) {
	h := newHarness(t)
	h.pool(h.installation(), "linux-x64")

	// A cancelled context is every store read failing at once, which is the
	// hardest version of the case: nothing at all can be gathered.
	ctx, cancel := context.WithCancel(h.ctx)
	cancel()
	b := h.api.supportBundle(ctx)

	if len(b.Errors) == 0 {
		t.Fatal("nothing could be read and the bundle reported no errors")
	}
	for _, e := range b.Errors {
		if e.Section == "" || e.Error == "" {
			t.Errorf("an error entry does not name its section and cause: %+v", e)
		}
	}
	// What survives is what does not need the database: the build, the
	// process, and the configuration this controller is running.
	if b.Instance.Go == "" {
		t.Error("the instance section went with the database, and it is the half that did not need it")
	}
	if b.Config == nil {
		t.Error("the configuration went with the database, and it is read from memory")
	}
	if b.GeneratedAt.IsZero() {
		t.Error("a bundle that gathered nothing still has to say when it was taken")
	}
}

// Workflow logs are never in a bundle: there is no redaction pass for them and
// a log holds whatever a workflow printed. What replaces them has to be enough
// to act on, which means the runners worth looking at and the route that
// fetches each one.
func TestTheBundlePointsAtLogsRatherThanCarryingThem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	failed := h.runner(pool, host, store.RunnerFailed)
	h.runner(pool, host, store.RunnerBusy)
	u, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(u)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "support bundle")
	var b supportBundle
	resp.into(t, &b)

	if b.Logs == nil {
		t.Fatal("the bundle has no logs section, so nothing tells a reader where the logs are")
	}
	if b.Logs.Note == "" {
		t.Error("the logs section does not say why the bodies are absent, which reads as an omission rather than a decision")
	}
	var found *bundleLogPointer
	for i, p := range b.Logs.Runners {
		if p.RunnerID == failed.ID {
			found = &b.Logs.Runners[i]
		}
	}
	if found == nil {
		t.Fatalf("the failed runner %s is not among the log pointers", failed.ID)
	}
	if !strings.HasSuffix(found.Download, "/runners/"+failed.ID+"/logs/download") {
		t.Errorf("the pointer does not name the route that fetches the log: %q", found.Download)
	}
	// A runner that is doing its job is not what a support case is about, and
	// a pointer per runner would bury the ones that are.
	for _, p := range b.Logs.Runners {
		if p.State == store.RunnerBusy || p.State == store.RunnerIdle {
			t.Errorf("a healthy runner (%s, %s) is in the log pointers", p.RunnerID, p.State)
		}
	}
}

// The byte cap is the backstop for the fleet whose rows are individually
// enormous, which no row-count cap can see. What matters as much as the cap is
// that a shortened bundle says so: a reader who cannot tell a capped section
// from an empty one will conclude the fleet has no runners.
func TestAnOversizeBundleShedsSectionsAndSaysWhichOnes(t *testing.T) {
	huge := strings.Repeat("x", 1024)
	b := supportBundle{BundleVersion: bundleVersion, Errors: []bundleError{}}
	for len(b.ScalingEvents)*len(huge) < bundleMaxBytes*2 {
		b.ScalingEvents = append(b.ScalingEvents, &store.ScalingEvent{ID: huge, Reason: huge})
	}
	b.Hosts = append(b.Hosts, hostResponse{})

	raw, err := marshalBundle(&b)
	if err != nil {
		t.Fatalf("marshalBundle: %v", err)
	}
	if len(raw) > bundleMaxBytes {
		t.Errorf("the bundle is %d bytes, over its %d-byte cap", len(raw), bundleMaxBytes)
	}

	var got supportBundle
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatalf("the shed bundle is not valid JSON: %v", err)
	}
	var shed bool
	for _, tr := range got.Truncated {
		if tr.Section == "scaling_events" {
			shed = true
			if tr.Reason == "" {
				t.Error("a shed section does not say why it went")
			}
		}
	}
	if !shed {
		t.Error("the scaling history was dropped and the bundle does not say so")
	}
	// The fleet's own shape is what a bundle is for, and is never what goes.
	if len(got.Hosts) == 0 {
		t.Error("the hosts section was shed; only the recomputable sections may be")
	}
}

// TestTheBundleKeepsAPoolsEnvKeysAndNotItsValues covers the one section of the
// bundle that was not "secret-free on its own route".
//
// A pool's env is where a registry password or a deploy key ends up. An
// administrator may read those values on the pool's own route, but the bundle
// is a file made to be attached to an issue or sent to whoever runs the
// platform, so a routine "send me a bundle" handed the values to a third
// party. The keys stay, because which variables a pool sets is what a reader
// diagnosing it needs, and the pool export carries the same.
func TestTheBundleKeepsAPoolsEnvKeysAndNotItsValues(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "linux-x64")
	pool.Env = store.StringMap{"NEXUS_PW": "hunter2", "DEPLOY_KEY": "deploy-key-value-9f3"}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// Both roles that may take a bundle: an administrator holds pools.write,
	// so a role-based blanking would have let their bundle keep the values.
	for _, role := range []store.Role{store.RoleAdmin, store.RolePlatform} {
		u, _ := h.user("bundler-"+string(role), role)
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(u)})
		resp.mustStatus(t, http.StatusOK, "support bundle as "+string(role))
		body := string(resp.body)
		if strings.Contains(body, "hunter2") || strings.Contains(body, "deploy-key-value-9f3") {
			t.Errorf("the bundle taken by a %s carries a pool env value:\n%s", role, body)
		}
		for _, key := range []string{"NEXUS_PW", "DEPLOY_KEY"} {
			if !strings.Contains(body, key) {
				t.Errorf("the bundle taken by a %s dropped the env key %s as well as its value", role, key)
			}
		}
	}
}

// Package api is Zoomies' HTTP surface: the REST API described by
// api/openapi.yaml, the Server-Sent Events streams the UI lives on, the
// Prometheus endpoint, the GitHub webhook receiver, and the embedded operator
// UI.
//
// Everything here is transport. Decisions about the fleet belong to
// internal/controller, authorisation policy to internal/auth and SQL to
// internal/store; a handler in this package reads a request, asks one of those
// three, and renders the answer in the shape the OpenAPI document promises.
// Keeping it that thin is what makes the contract checkable: the surface can be
// walked route by route in a test, and nothing behind it has an opinion about
// HTTP.
package api

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"strconv"
	"time"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// Error codes. They are the enum in the OpenAPI document's ErrorEnvelope, and
// the UI switches on them, so they are part of the contract rather than free
// text.
const (
	codeBadRequest    = "bad_request"
	codeUnauthorized  = "unauthorized"
	codeForbidden     = "forbidden"
	codeNotFound      = "not_found"
	codeConflict      = "conflict"
	codeUnprocessable = "unprocessable"
	codeTooLarge      = "too_large"
	codeRateLimited   = "rate_limited"
	codeLimitReached  = "limit_reached"
	codeInternal      = "internal"
)

// statusClientClosed is nginx's 499: the client hung up before the response.
// No client ever reads it -- by then there is none -- but the access log
// separates a request the browser abandoned from one the controller failed.
const statusClientClosed = 499

// fieldError names one thing wrong with a request body, in the words the form
// field it belongs to should display.
type fieldError struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

// errorBody is the inner object of the error envelope.
type errorBody struct {
	Code    string `json:"code"`
	Message string `json:"message"`
	Field   string `json:"field,omitempty"`
	Detail  string `json:"detail,omitempty"`
}

// errorEnvelope is every failure this API returns.
//
// The message is written for a person to read and act on, which is why nothing
// in this package answers with a bare status code: an operator who gets a 403
// from a script needs to be told which role they are missing, not left to guess.
type errorEnvelope struct {
	Error errorBody `json:"error"`
	// Errors carries per-field messages on a 422, so a form can attach each one
	// to the input that caused it.
	Errors []fieldError `json:"errors,omitempty"`
}

// writeJSON renders v as the whole response body.
//
// The value is marshalled before anything is written, so a value that cannot be
// encoded produces a 500 rather than a truncated 200 that a client would parse
// as a successful, empty answer.
func writeJSON(w http.ResponseWriter, status int, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		slog.Default().Error("could not encode an API response", "error", err)
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.WriteHeader(http.StatusInternalServerError)
		_, _ = w.Write([]byte(`{"error":{"code":"internal","message":"the server built a response it could not encode; check the controller logs"}}`))
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Length", strconv.Itoa(len(b)+1))
	w.WriteHeader(status)
	_, _ = w.Write(b)
	_, _ = w.Write([]byte("\n"))
}

// noContent answers a mutation that has nothing to return.
func noContent(w http.ResponseWriter) { w.WriteHeader(http.StatusNoContent) }

func writeError(w http.ResponseWriter, status int, e errorEnvelope) {
	writeJSON(w, status, e)
}

// badRequest is for a request this server could not parse at all.
func badRequest(w http.ResponseWriter, message string) {
	writeError(w, http.StatusBadRequest, errorEnvelope{Error: errorBody{Code: codeBadRequest, Message: message}})
}

// badRequestField is badRequest when one named parameter is at fault, which is
// what a query-string mistake usually is.
func badRequestField(w http.ResponseWriter, field, message string) {
	writeError(w, http.StatusBadRequest, errorEnvelope{Error: errorBody{
		Code: codeBadRequest, Message: message, Field: field,
	}})
}

// payloadTooLarge is the refusal for a body over the limit.
//
// It is 413 rather than 400 because the two say different things to a client:
// a 400 invites it to fix its JSON, and there is nothing wrong with the JSON.
// The webhook endpoint has always answered 413 for the same condition, so this
// is also the two halves of the surface agreeing.
func payloadTooLarge(w http.ResponseWriter, message string) {
	writeError(w, http.StatusRequestEntityTooLarge, errorEnvelope{Error: errorBody{
		Code: codeTooLarge, Message: message,
	}})
}

// unauthorized means "no usable credential", never "wrong role".
func unauthorized(w http.ResponseWriter, message string) {
	if message == "" {
		message = "sign in to use this API"
	}
	writeError(w, http.StatusUnauthorized, errorEnvelope{Error: errorBody{Code: codeUnauthorized, Message: message}})
}

// forbidden means the caller is known but not allowed. The message comes from
// auth.Explain, which names the role or scope that is missing.
func forbidden(w http.ResponseWriter, message string) {
	if message == "" {
		message = "your account is not allowed to do that"
	}
	writeError(w, http.StatusForbidden, errorEnvelope{Error: errorBody{Code: codeForbidden, Message: message}})
}

func notFound(w http.ResponseWriter, message string) {
	if message == "" {
		message = "no such thing; it may have been removed since the page loaded"
	}
	writeError(w, http.StatusNotFound, errorEnvelope{Error: errorBody{Code: codeNotFound, Message: message}})
}

func conflict(w http.ResponseWriter, message string) {
	writeError(w, http.StatusConflict, errorEnvelope{Error: errorBody{Code: codeConflict, Message: message}})
}

// limitReached is the refusal from one of the limits.* ceilings. It is a 409
// with a code of its own rather than a plain conflict because a client can do
// something different about it -- nothing it resends will help until somebody
// removes a resource or raises the setting the message names -- and the
// setting travels in field so a script need not parse the sentence.
func limitReached(w http.ResponseWriter, err *controller.LimitError) {
	writeError(w, http.StatusConflict, errorEnvelope{Error: errorBody{
		Code: codeLimitReached, Message: err.Error(), Field: err.Setting,
	}})
}

// asLimit reports whether err is a limits.* refusal, and answers it if so.
func asLimit(w http.ResponseWriter, err error) bool {
	var le *controller.LimitError
	if errors.As(err, &le) {
		limitReached(w, le)
		return true
	}
	return false
}

// unprocessable is the validation failure: the request was understood and is
// wrong. Every caller passes the fields, because "invalid request" tells an
// operator nothing about which box to go back and fix.
func unprocessable(w http.ResponseWriter, message string, fields []fieldError) {
	if message == "" {
		message = "that is not a valid request"
	}
	env := errorEnvelope{Error: errorBody{Code: codeUnprocessable, Message: message}, Errors: fields}
	if len(fields) == 1 {
		env.Error.Field = fields[0].Field
	}
	writeError(w, http.StatusUnprocessableEntity, env)
}

// rateLimited answers a caller that has been trying too often. Retry-After is
// set so a client can wait exactly as long as it needs to.
func rateLimited(w http.ResponseWriter, message string, retryAfter time.Duration) {
	if secs := int(retryAfter.Seconds()); secs > 0 {
		w.Header().Set("Retry-After", strconv.Itoa(secs))
	}
	writeError(w, http.StatusTooManyRequests, errorEnvelope{Error: errorBody{Code: codeRateLimited, Message: message}})
}

// internal logs the cause and returns a message that carries only the request
// ID.
//
// The cause is what an operator needs and an attacker would like, so it goes to
// the log; the request ID goes to the client, which is enough to find the log
// line. doing is a present participle -- "listing pools" -- so the log line and
// the response read as sentences.
func (s *Server) internal(w http.ResponseWriter, r *http.Request, doing string, err error) {
	info := infoFrom(r.Context())
	id := ""
	if info != nil {
		id = info.id
	}
	// A browser that leaves the page cancels whatever it still had in flight,
	// and the query comes back context.Canceled. Nothing is wrong with the
	// controller and nobody is left to read a 500, so it is noted at debug:
	// at error level a page of them teaches an operator to scroll past the
	// failures that do need them.
	if errors.Is(err, context.Canceled) && r.Context().Err() != nil {
		s.logger(r).Debug("the client went away before its response", "doing", doing, "request_id", id)
		w.WriteHeader(statusClientClosed)
		return
	}
	s.logger(r).Error("request failed", "doing", doing, "error", err, "request_id", id)
	detail := ""
	if id != "" {
		detail = "request " + id
	}
	writeError(w, http.StatusInternalServerError, errorEnvelope{Error: errorBody{
		Code:    codeInternal,
		Message: "something went wrong while " + doing + ". " + supportHint(),
		Detail:  detail,
	}})
}

// supportHint is the one sentence every "something went wrong" ends with.
//
// It used to say the cause was in the controller's log, which assumes the
// reader can read that log. On an instance one team operates while another
// uses the fleet, they cannot: the log belongs to the process, and the person
// reading this runs pools on it. So it names the request ID and who to give it
// to, which is true for both -- an operator running their own instance is
// "whoever operates this instance", and the log is theirs to open.
//
// One function rather than nine sentences, because nine sentences is how the
// ninth came to say something the other eight had stopped saying.
func supportHint() string {
	return "Quote the request ID to whoever operates this instance; the cause is in its log."
}

// fail maps the errors the store and the controller return onto status codes.
//
// It exists so that no handler has to remember that a runner in a terminal
// state comes back as store.ErrInvalidTransition and must be a 409: the mapping
// is stated once, here, and every handler funnels its unexpected errors through
// it.
func (s *Server) fail(w http.ResponseWriter, r *http.Request, doing string, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		notFound(w, err.Error())
	case errors.Is(err, store.ErrConflict):
		conflict(w, err.Error())
	case errors.Is(err, store.ErrInvalidTransition):
		conflict(w, err.Error())
	case errors.Is(err, controller.ErrStreamUnknown):
		notFound(w, err.Error())
	case errors.Is(err, controller.ErrConfirmationRequired):
		// Not a failure: the operator asked for something whose cost they have
		// not accepted yet. 409 rather than 422, because the request is well
		// formed and it is the runner's state that decides.
		conflict(w, err.Error()+". Send it again with confirm=true to accept that, "+
			"or wait for the job to finish and drain it then.")
	default:
		s.internal(w, r, doing, err)
	}
}

package api

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// The capacity map reloads its samples on every window change, and a browser
// that moves on cancels the request it left behind. That is the client's
// doing, not a fault in the controller: logging each one as a failed request
// filled the log with errors nobody could act on, which is how the errors
// that matter get scrolled past.
func TestAnAbandonedRequestIsNotLoggedAsAFailure(t *testing.T) {
	h := newHarness(t)

	ctx, cancel := context.WithCancel(h.ctx)
	cancel()
	r := httptest.NewRequest(http.MethodGet, "/api/v1/hosts/samples?window=1h", nil).WithContext(ctx)
	w := httptest.NewRecorder()
	h.api.internal(w, r, "reading host samples", context.Canceled)

	if w.Code != statusClientClosed {
		t.Errorf("status = %d, want %d for a client that hung up", w.Code, statusClientClosed)
	}
	if body := strings.TrimSpace(w.Body.String()); body != "" {
		t.Errorf("body = %q, want nothing: there is no one left to read it", body)
	}
	if logged := h.logs.text(); strings.Contains(logged, "ERROR request failed") {
		t.Errorf("logged an error for an abandoned request:\n%s", logged)
	}
}

// A cancellation that is not the client's -- the store giving up on its own
// while the request is still live -- is a real failure, and an operator needs
// the log line and the request ID to chase it.
func TestACancellationTheClientDidNotCauseIsStillAFailure(t *testing.T) {
	h := newHarness(t)

	r := httptest.NewRequest(http.MethodGet, "/api/v1/hosts/samples?window=1h", nil)
	w := httptest.NewRecorder()
	h.api.internal(w, r, "reading host samples", errors.New("context canceled"))

	if w.Code != http.StatusInternalServerError {
		t.Errorf("status = %d, want 500", w.Code)
	}
	if logged := h.logs.text(); !strings.Contains(logged, "request failed") {
		t.Errorf("did not log the failure:\n%s", logged)
	}
}

//go:build ignore

// Command gen_openapi copies api/openapi.yaml into this package as Go source.
//
// The API has to be able to serve the contract it implements, and go:embed
// cannot reach outside its own package directory -- api/openapi.yaml lives at
// the top of the repository, deliberately, because it is the document the UI's
// TypeScript client is generated from as well. Copying the file into
// internal/api would leave two files that could disagree, so the copy is
// generated, compressed, and checked against the original by a test that fails
// with the command to run.
//
// Run it from the repository root after editing the spec:
//
//	go run internal/api/gen_openapi.go
package main

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"fmt"
	"os"
	"strings"
)

const (
	defaultSource = "api/openapi.yaml"
	target        = "internal/api/openapi_spec.go"
	// lineWidth keeps the generated literal reviewable in a diff.
	lineWidth = 96
)

func main() {
	source := defaultSource
	if len(os.Args) > 1 {
		source = os.Args[1]
	}
	raw, err := os.ReadFile(source)
	if err != nil {
		fail("reading %s: %v", source, err)
	}

	var buf bytes.Buffer
	zw, err := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	if err != nil {
		fail("compressing: %v", err)
	}
	if _, err := zw.Write(raw); err != nil {
		fail("compressing: %v", err)
	}
	if err := zw.Close(); err != nil {
		fail("compressing: %v", err)
	}

	encoded := base64.StdEncoding.EncodeToString(buf.Bytes())

	var out strings.Builder
	out.WriteString("// Code generated by gen_openapi.go; DO NOT EDIT.\n")
	out.WriteString("// Source: " + defaultSource + "\n\n")
	out.WriteString("package api\n\n")
	out.WriteString("// openapiSpecGzB64 is api/openapi.yaml, gzipped and base64 encoded.\n")
	out.WriteString("//\n")
	out.WriteString("// It is generated rather than embedded because go:embed cannot reach a file\n")
	out.WriteString("// outside its package directory. openapi_spec_test.go compares it with the\n")
	out.WriteString("// original on every test run, so the two cannot drift apart unnoticed; when it\n")
	out.WriteString("// fails, run `go run internal/api/gen_openapi.go` from the repository root.\n")
	out.WriteString("const openapiSpecGzB64 = \"\" +\n")
	for i := 0; i < len(encoded); i += lineWidth {
		end := min(i+lineWidth, len(encoded))
		out.WriteString("\t\"" + encoded[i:end] + "\"")
		if end < len(encoded) {
			out.WriteString(" +")
		}
		out.WriteString("\n")
	}

	if err := os.WriteFile(target, []byte(out.String()), 0o644); err != nil {
		fail("writing %s: %v", target, err)
	}
	fmt.Printf("wrote %s (%d bytes of YAML, %d bytes encoded)\n", target, len(raw), len(encoded))
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "gen_openapi: "+format+"\n", args...)
	os.Exit(1)
}

package api

import (
	"errors"
	"fmt"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// ---------------------------------------------------------------------------
// Users
// ---------------------------------------------------------------------------

// userResponse is an account. The password hash is not a field here and cannot
// become one by accident: the type is written out rather than derived from the
// domain model.
type userResponse struct {
	ID                 string     `json:"id"`
	Username           string     `json:"username"`
	Email              string     `json:"email,omitempty"`
	DisplayName        string     `json:"display_name,omitempty"`
	Role               store.Role `json:"role"`
	OIDCSubject        string     `json:"oidc_subject,omitempty"`
	Disabled           bool       `json:"disabled"`
	MustChangePassword bool       `json:"must_change_password"`
	CreatedAt          time.Time  `json:"created_at"`
	LastLoginAt        *time.Time `json:"last_login_at"`
	// TwoStepEnabled is whether the account signs in with a code after its
	// password. It is here so an administrator can see who a reset is for.
	TwoStepEnabled bool `json:"two_step_enabled"`
}

// withTwoStep fills in two_step_enabled for one account. A failure to read
// it is logged and shown as off: the users page is not worth refusing over
// one column.
func (s *Server) withTwoStep(r *http.Request, out userResponse) userResponse {
	ts, err := s.ctrl.Store().GetTwoStep(r.Context(), out.ID)
	if err != nil && !errors.Is(err, store.ErrNotFound) {
		s.logger(r).Warn("could not read an account's two-step state", "user_id", out.ID, "error", err)
	}
	out.TwoStepEnabled = err == nil && ts.Enabled()
	return out
}

func newUserResponse(u *store.User) userResponse {
	return userResponse{
		ID: u.ID, Username: u.Username, Email: u.Email, DisplayName: u.DisplayName,
		Role: u.Role, OIDCSubject: u.OIDCSubject, Disabled: u.Disabled,
		MustChangePassword: u.MustChangePassword, CreatedAt: u.CreatedAt,
		LastLoginAt: u.LastLoginAt,
	}
}

// handleListUsers answers GET /api/v1/users.
func (s *Server) handleListUsers(w http.ResponseWriter, r *http.Request) {
	users, err := s.ctrl.Store().ListUsers(r.Context())
	if err != nil {
		s.internal(w, r, "listing accounts", err)
		return
	}
	enabled, err := s.ctrl.Store().TwoStepEnabledUsers(r.Context())
	if err != nil {
		s.internal(w, r, "listing accounts", err)
		return
	}
	out := make([]userResponse, 0, len(users))
	for _, u := range users {
		row := newUserResponse(u)
		row.TwoStepEnabled = enabled[u.ID]
		out = append(out, row)
	}
	writeJSON(w, http.StatusOK, newList(out))
}

// handleGetUser answers GET /api/v1/users/{id}.
func (s *Server) handleGetUser(w http.ResponseWriter, r *http.Request) {
	u, err := s.ctrl.Store().GetUser(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the account", err)
		return
	}
	writeJSON(w, http.StatusOK, s.withTwoStep(r, newUserResponse(u)))
}

type createUserRequest struct {
	Username    string `json:"username"`
	Password    string `json:"password"`
	Email       string `json:"email"`
	DisplayName string `json:"display_name"`
	Role        string `json:"role"`
}

// handleCreateUser adds an account.
//
// The password may be omitted for an account that will sign in through the
// identity provider: the first single sign-on with that username links it.
// That is only allowed while SSO is on, which is what stops an account being
// created that nobody can ever use.
func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	var req createUserRequest
	if !decode(w, r, &req) {
		return
	}

	var fields []fieldError
	if strings.TrimSpace(req.Username) == "" {
		fields = append(fields, fieldError{"username", "an account needs a name to sign in with"})
	}
	role := store.Role(strings.ToLower(strings.TrimSpace(req.Role)))
	if role == "" {
		role = store.RoleViewer
	}
	if !role.Valid() {
		fields = append(fields, fieldError{"role", fmt.Sprintf("%q is not a role; use %s", req.Role, store.RoleList())})
	}
	if req.Password != "" {
		if err := auth.CheckPassword(req.Password); err != nil {
			fields = append(fields, fieldError{"password", err.Error()})
		}
	} else if !s.oidcProvider().Enabled() {
		fields = append(fields, fieldError{"password", "this instance has no single sign-on configured, so an account needs a password"})
	}
	if len(fields) > 0 {
		unprocessable(w, "this account could not be created", fields)
		return
	}
	if err := auth.ManageWithin(Identity(r.Context()), role); err != nil {
		forbidden(w, err.Error())
		return
	}

	u, err := s.auth.CreateUser(r.Context(), auth.NewUser{
		Username:    req.Username,
		Password:    req.Password,
		Email:       req.Email,
		DisplayName: req.DisplayName,
		Role:        role,
		SSOOnly:     req.Password == "",
		// Somebody else chose this password, so its owner picks their own at
		// first sign-in.
		MustChangePassword: req.Password != "",
	})
	if err != nil {
		switch {
		case errors.Is(err, store.ErrConflict):
			conflict(w, err.Error())
		case errors.Is(err, auth.ErrInvalidInput):
			unprocessable(w, err.Error(), nil)
		default:
			s.fail(w, r, "creating the account", err)
		}
		return
	}

	s.auth.Auditor().Created(r.Context(), Identity(r.Context()), "user", u.ID, newUserResponse(u))
	writeJSON(w, http.StatusCreated, newUserResponse(u))
}

type updateUserRequest struct {
	Email       *string `json:"email"`
	DisplayName *string `json:"display_name"`
	Role        *string `json:"role"`
	Disabled    *bool   `json:"disabled"`
}

// handleUpdateUser changes an account.
//
// Demoting or disabling the last enabled administrator is refused by the auth
// service, which is the invariant behind "you cannot lock yourself out of your
// own controller".
func (s *Server) handleUpdateUser(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	u, err := s.ctrl.Store().GetUser(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the account", err)
		return
	}

	var req updateUserRequest
	if !decode(w, r, &req) {
		return
	}
	if err := auth.ManageWithin(Identity(r.Context()), u.Role); err != nil {
		forbidden(w, err.Error())
		return
	}
	before := *u
	if req.Email != nil {
		u.Email = strings.TrimSpace(*req.Email)
	}
	if req.DisplayName != nil {
		u.DisplayName = strings.TrimSpace(*req.DisplayName)
	}
	if req.Role != nil {
		role := store.Role(strings.ToLower(strings.TrimSpace(*req.Role)))
		if !role.Valid() {
			unprocessable(w, "this account could not be changed", []fieldError{
				{"role", fmt.Sprintf("%q is not a role; use %s", *req.Role, store.RoleList())},
			})
			return
		}
		if err := auth.ManageWithin(Identity(r.Context()), role); err != nil {
			forbidden(w, err.Error())
			return
		}
		u.Role = role
	}
	if req.Disabled != nil {
		u.Disabled = *req.Disabled
	}

	if err := s.auth.UpdateUser(r.Context(), u); err != nil {
		if errors.Is(err, auth.ErrLastAdmin) || errors.Is(err, store.ErrConflict) {
			conflict(w, err.Error())
			return
		}
		s.fail(w, r, "saving the account", err)
		return
	}
	s.auth.Auditor().Updated(r.Context(), Identity(r.Context()), "user", id, newUserResponse(&before), newUserResponse(u))
	writeJSON(w, http.StatusOK, s.withTwoStep(r, newUserResponse(u)))
}

// handleDeleteUser removes an account, refusing to remove the last admin.
func (s *Server) handleDeleteUser(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	u, err := s.ctrl.Store().GetUser(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the account", err)
		return
	}
	if err := auth.ManageWithin(Identity(r.Context()), u.Role); err != nil {
		forbidden(w, err.Error())
		return
	}
	if err := s.auth.DeleteUser(r.Context(), id); err != nil {
		if errors.Is(err, auth.ErrLastAdmin) {
			conflict(w, err.Error())
			return
		}
		s.fail(w, r, "deleting the account", err)
		return
	}
	s.auth.Auditor().Deleted(r.Context(), Identity(r.Context()), "user", id, newUserResponse(u))
	noContent(w)
}

type resetPasswordRequest struct {
	NewPassword string `json:"new_password"`
}

// handleResetPassword is the administrator's reset. It flags the account so its
// owner chooses their own password at the next sign-in, and ends every session
// the account had.
func (s *Server) handleResetPassword(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	var req resetPasswordRequest
	if !decode(w, r, &req) {
		return
	}
	if err := auth.CheckPassword(req.NewPassword); err != nil {
		unprocessable(w, "that password cannot be used", []fieldError{{"new_password", err.Error()}})
		return
	}
	target, err := s.ctrl.Store().GetUser(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the account", err)
		return
	}
	if err := auth.ManageWithin(Identity(r.Context()), target.Role); err != nil {
		forbidden(w, err.Error())
		return
	}
	if err := s.auth.ResetPassword(r.Context(), id, req.NewPassword); err != nil {
		s.fail(w, r, "resetting the password", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "user.password_reset", "user", id, nil)
	noContent(w)
}

// ---------------------------------------------------------------------------
// API tokens
// ---------------------------------------------------------------------------

// tokenResponse is a token's metadata. The value itself exists in plaintext
// exactly once, in the response to the call that created it.
type tokenResponse struct {
	ID         string     `json:"id"`
	Name       string     `json:"name"`
	Role       store.Role `json:"role"`
	Scopes     []string   `json:"scopes"`
	Prefix     string     `json:"prefix"`
	Revoked    bool       `json:"revoked"`
	CreatedAt  time.Time  `json:"created_at"`
	ExpiresAt  *time.Time `json:"expires_at"`
	LastUsedAt *time.Time `json:"last_used_at"`
	// UserID is the account the token was minted by, so an administrator
	// looking at everybody's can tell whose each one is.
	UserID string `json:"user_id,omitempty"`
}

type createdTokenResponse struct {
	tokenResponse
	Token string `json:"token"`
}

func newTokenResponse(t *store.APIToken) tokenResponse {
	return tokenResponse{
		ID: t.ID, Name: t.Name, Role: t.Role, Scopes: emptySlice(t.Scopes),
		Prefix: t.Prefix, Revoked: t.Revoked, CreatedAt: t.CreatedAt,
		ExpiresAt: t.ExpiresAt, LastUsedAt: t.LastUsedAt, UserID: t.UserID,
	}
}

// tokenVisibleTo says whether this caller may see a token at all.
//
// A token minted by a platform account is the platform's -- the metrics
// scraper reading an instance it operates for another team, the verifier
// checking its backups -- and on the Tokens page it used to sit beside the
// fleet's own, revocable by any administrator. A fleet that can switch off the
// monitoring of a process it does not run is a fleet that can do so by
// accident.
//
// A token from before the column existed has no owner recorded, and stays
// visible to whoever could see it before. Guessing an owner from the token's
// role would hide the fleet's own automation from it, because 0045 promoted
// those tokens to platform for an unrelated reason.
func tokenVisibleTo(t *store.APIToken, who store.Role) bool {
	if t.OwnerRole == store.RolePlatform {
		return who.AtLeast(store.RolePlatform)
	}
	return true
}

// tokenReachable says whether this caller may see and revoke a token: any it
// can see when it holds tokens.read (or tokens.write, to act), and otherwise
// only its own. A token nobody owns is nobody's but an administrator's.
func tokenReachable(r *http.Request, t *store.APIToken, everyone auth.Action) bool {
	if !tokenVisibleTo(t, callerRole(r)) {
		return false
	}
	id := Identity(r.Context())
	if id.Can(everyone) {
		return true
	}
	return id != nil && id.UserID != "" && t.UserID == id.UserID
}

// handleListTokens answers GET /api/v1/tokens: everybody's for an
// administrator, and the caller's own for anybody else.
func (s *Server) handleListTokens(w http.ResponseWriter, r *http.Request) {
	tokens, err := s.ctrl.Store().ListAPITokens(r.Context())
	if err != nil {
		s.internal(w, r, "listing API tokens", err)
		return
	}
	out := make([]tokenResponse, 0, len(tokens))
	for _, t := range tokens {
		if !tokenReachable(r, t, auth.ActionTokensRead) {
			continue
		}
		out = append(out, newTokenResponse(t))
	}
	writeJSON(w, http.StatusOK, newList(out))
}

type createTokenRequest struct {
	Name      string   `json:"name"`
	Role      string   `json:"role"`
	Scopes    []string `json:"scopes"`
	ExpiresIn string   `json:"expires_in"`
}

// handleCreateToken mints an API token and shows it once.
func (s *Server) handleCreateToken(w http.ResponseWriter, r *http.Request) {
	var req createTokenRequest
	if !decode(w, r, &req) {
		return
	}

	var fields []fieldError
	if strings.TrimSpace(req.Name) == "" {
		fields = append(fields, fieldError{"name", "a token needs a name; it is how you will recognise it in the list later"})
	}
	role := store.Role(strings.ToLower(strings.TrimSpace(req.Role)))
	if role == "" {
		role = store.RoleViewer
	}
	if !role.Valid() {
		fields = append(fields, fieldError{"role", fmt.Sprintf("%q is not a role; use %s", req.Role, store.RoleList())})
	}
	if err := auth.ValidateScopes(req.Scopes); err != nil {
		fields = append(fields, fieldError{"scopes", err.Error()})
	}
	var expiresAt *time.Time
	if raw := strings.TrimSpace(req.ExpiresIn); raw != "" {
		d, err := time.ParseDuration(raw)
		switch {
		case err != nil:
			fields = append(fields, fieldError{"expires_in", fmt.Sprintf("%q is not a duration; write it like 720h for 30 days", raw)})
		case d <= 0:
			fields = append(fields, fieldError{"expires_in", "an expiry has to be in the future; leave it empty for a token that never expires"})
		default:
			t := s.auth.Now().Add(d)
			expiresAt = &t
		}
	}
	if len(fields) > 0 {
		unprocessable(w, "this token could not be created", fields)
		return
	}

	// A token is attributed to the account behind the caller -- the person
	// signed in, or the owner of the token being used -- so that disabling or
	// deleting that account ends every credential descended from it. A token
	// with no owner has nobody to attribute to, and minting from it would
	// produce credentials that outlive every revocation, so it cannot.
	id := Identity(r.Context())
	if id == nil || id.UserID == "" {
		unprocessable(w, "this token has no owner, so it cannot mint tokens; sign in as a user, or use a token created by one", nil)
		return
	}
	if err := auth.MintWithin(id, role, req.Scopes); err != nil {
		unprocessable(w, err.Error(), nil)
		return
	}
	token, plaintext, err := s.auth.CreateAPIToken(r.Context(), auth.NewToken{
		Name: strings.TrimSpace(req.Name), Role: role, UserID: id.UserID,
		Scopes: req.Scopes, ExpiresAt: expiresAt, OwnerRole: id.Role,
	})
	if err != nil {
		if errors.Is(err, auth.ErrInvalidInput) {
			unprocessable(w, err.Error(), nil)
			return
		}
		s.fail(w, r, "creating the token", err)
		return
	}
	// The audit row records that a credential was minted, never the credential.
	s.auth.Auditor().Created(r.Context(), id, "token", token.ID, newTokenResponse(token))

	writeJSON(w, http.StatusCreated, createdTokenResponse{
		tokenResponse: newTokenResponse(token),
		Token:         plaintext,
	})
}

// handleRevokeToken answers DELETE /api/v1/tokens/{id}. Without ?purge it
// disables a token while keeping its row, so the list and the audit trail can
// still resolve the actions it took. With ?purge=true it removes a token that
// is already revoked or expired; a live one is a 409, because deleting is
// tidying up after a revocation and never a quieter way to do one.
func (s *Server) handleRevokeToken(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	tokens, err := s.ctrl.Store().ListAPITokens(r.Context())
	if err != nil {
		s.internal(w, r, "listing API tokens", err)
		return
	}
	idx := slices.IndexFunc(tokens, func(t *store.APIToken) bool { return t.ID == id })
	// A token this caller cannot see answers exactly as one that is not there.
	// Refusing with a 403 would confirm the platform holds a credential by
	// this ID, which is the fact being withheld.
	// Somebody else's token, to a caller who may only manage their own, is
	// not there either, for the same reason.
	if idx < 0 || !tokenReachable(r, tokens[idx], auth.ActionTokensWrite) {
		notFound(w, "there is no API token "+id)
		return
	}
	token := tokens[idx]
	if purge, _ := strconv.ParseBool(r.URL.Query().Get("purge")); purge {
		live := fmt.Sprintf("%s (%s) still works, so it cannot be deleted; revoke it first", token.Name, token.Prefix)
		if !tokenSpent(token, s.auth.Now()) {
			conflict(w, live)
			return
		}
		if err := s.deleteToken(r, token); err != nil {
			if errors.Is(err, store.ErrConflict) {
				conflict(w, live)
				return
			}
			s.fail(w, r, "deleting the token", err)
			return
		}
		noContent(w)
		return
	}
	if err := s.auth.RevokeAPIToken(r.Context(), id); err != nil {
		s.fail(w, r, "revoking the token", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "token.revoke", "token", id, tokenAuditDetail(token))
	noContent(w)
}

// tokenSpent says whether a token can no longer authenticate, which is the
// only kind that may be deleted.
func tokenSpent(t *store.APIToken, now time.Time) bool {
	return t.Revoked || (t.ExpiresAt != nil && t.ExpiresAt.Before(now))
}

// tokenAuditDetail is what an audit row says about a token: enough to match it
// to a leaked string or a line in a log, and never the secret. It is written
// before a deletion, so the row still names the token once the token is gone.
func tokenAuditDetail(t *store.APIToken) map[string]any {
	return map[string]any{"name": t.Name, "prefix": t.Prefix, "user_id": t.UserID, "revoked": t.Revoked}
}

// deleteToken removes one spent token and writes the audit row for it.
func (s *Server) deleteToken(r *http.Request, t *store.APIToken) error {
	if err := s.auth.DeleteAPIToken(r.Context(), t.ID); err != nil {
		return err
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "token.delete", "token", t.ID, tokenAuditDetail(t))
	return nil
}

type purgeTokensRequest struct {
	UserID string `json:"user_id"`
	All    bool   `json:"all"`
}

type purgeTokensResponse struct {
	Deleted []tokenResponse `json:"deleted"`
}

// handlePurgeTokens answers POST /api/v1/tokens/purge: delete every revoked or
// expired token the caller owns, one account's, or -- with all -- every one
// the caller can see. Tokens that still work are never touched, so this is
// safe to press without reading the list first.
func (s *Server) handlePurgeTokens(w http.ResponseWriter, r *http.Request) {
	var req purgeTokensRequest
	if r.ContentLength != 0 && !decode(w, r, &req) {
		return
	}
	owner := strings.TrimSpace(req.UserID)
	// Both at once is ambiguous, and reading it as "all" would purge every
	// account's tokens for a caller who meant one.
	if req.All && owner != "" {
		unprocessable(w, "user_id and all ask different questions; give user_id to purge one account's spent tokens, or all to purge every one", []fieldError{{"all", "cannot be combined with user_id"}})
		return
	}
	// Somebody who may manage only their own tokens may purge only those.
	if caller := Identity(r.Context()); !caller.Can(auth.ActionTokensWrite) &&
		(req.All || (owner != "" && (caller == nil || owner != caller.UserID))) {
		forbidden(w, fmt.Sprintf("purging anybody's spent tokens but your own needs the %s role; you are signed in as %s, so purge your own by leaving out user_id and all",
			auth.ActionTokensWrite.MinRole(), callerRole(r)))
		return
	}
	if !req.All && owner == "" {
		id := Identity(r.Context())
		if id == nil || id.UserID == "" {
			unprocessable(w, "this caller has no account, so it owns no tokens; name one with user_id, or pass all to purge every spent token", nil)
			return
		}
		owner = id.UserID
	}
	tokens, err := s.ctrl.Store().ListAPITokens(r.Context())
	if err != nil {
		s.internal(w, r, "listing API tokens", err)
		return
	}
	now := s.auth.Now()
	out := purgeTokensResponse{Deleted: []tokenResponse{}}
	for _, t := range tokens {
		if !tokenReachable(r, t, auth.ActionTokensWrite) || !tokenSpent(t, now) || (!req.All && t.UserID != owner) {
			continue
		}
		if err := s.deleteToken(r, t); err != nil {
			// Gone already, or un-spent by a clock that moved: neither is a
			// reason to stop tidying the rest.
			if errors.Is(err, store.ErrNotFound) || errors.Is(err, store.ErrConflict) {
				continue
			}
			s.fail(w, r, "deleting the token", err)
			return
		}
		out.Deleted = append(out.Deleted, newTokenResponse(t))
	}
	writeJSON(w, http.StatusOK, out)
}

package api

import (
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// agentHost returns the host an agent request authenticated as.
func agentHost(r *http.Request) *store.Host {
	h, _ := r.Context().Value(ctxAgentHost).(*store.Host)
	return h
}

// agentBudget spends one call from the authenticated host's budget for
// heartbeats, results and reports, and answers 429 when it is gone.
//
// It runs before the body is read, so a host over its budget costs a header
// parse and nothing else -- no decode, and above all no write queued behind
// the single writer every other host's heartbeat is waiting on.
func (s *Server) agentBudget(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		host := agentHost(r)
		if ok, retry := s.ctrl.AllowAgentCall(host.ID); !ok {
			s.logger(r).Warn("agent rate limit hit", "host", host.ID, "path", r.URL.Path)
			rateLimited(w, "this host is calling the controller far more often than an agent does; "+
				"it is being slowed down, and if it keeps happening check the agent's log and version", retry)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// failReport answers a heartbeat or report the controller refused, naming the
// cap when that was the reason.
func (s *Server) failReport(w http.ResponseWriter, r *http.Request, err error) bool {
	if errors.Is(err, controller.ErrReportTooLarge) {
		s.logger(r).Warn("refused an oversized agent report", "host", agentHost(r).ID, "error", err)
		payloadTooLarge(w, err.Error())
		return true
	}
	return false
}

// handleAgentJoin redeems a join token and enrols a host.
//
// It is the one anonymous agent route, because it is the call that mints the
// credential every other one carries. The join token is single-use and
// short-lived, and the agent token it returns is shown exactly once.
func (s *Server) handleAgentJoin(w http.ResponseWriter, r *http.Request) {
	// The one anonymous agent route, and one that says whether the credential
	// it was given was right -- so it is guessable the way a sign-in is, and it
	// is bounded the same way. A machine joins once, so a limit generous enough
	// to be invisible to an operator still costs an attacker every attempt.
	if ip := ClientIP(r.Context()); !s.auth.AllowJoin(ip) {
		s.logger(r).Warn("join rate limit hit", "ip", ip)
		rateLimited(w, "too many enrolment attempts from this address; wait a minute and try again",
			s.auth.JoinRetryAfter(ip))
		return
	}
	var req agent.JoinRequest
	if !decodeLenient(w, r, &req) {
		return
	}
	req.Connection = connectionKind(r.Context())
	resp, err := s.ctrl.Join(r.Context(), req, ClientIP(r.Context()))
	if err != nil {
		// A refused join is almost always a spent or mistyped token, which is
		// the agent operator's to fix and is told to them in as many words.
		// Anything else -- the database not answering -- is this controller's
		// failure, logged with a request ID and never quoted to an anonymous
		// caller as though it were their mistake.
		if errors.Is(err, auth.ErrInvalidInput) {
			s.logger(r).Warn("refused an agent join", "name", req.Name, "error", err)
			unprocessable(w, err.Error(), nil)
			return
		}
		if asLimit(w, err) {
			s.logger(r).Warn("refused an agent join at limits.hosts", "name", req.Name)
			return
		}
		s.internal(w, r, "enrolling a host", err)
		return
	}
	// The controller's join already wrote the host.join audit row, with the
	// host as its own actor; a second one here showed every enrolment twice.
	s.ctrl.Nudge()
	writeJSON(w, http.StatusOK, resp)
}

// handleAgentHeartbeat records that a host is alive.
//
// A host the controller no longer knows about is a 404, and the agent's
// transport turns that specific status into "re-join me": no amount of retrying
// brings back a row an operator deleted.
func (s *Server) handleAgentHeartbeat(w http.ResponseWriter, r *http.Request) {
	host := agentHost(r)
	var req agent.HeartbeatRequest
	if !decodeLenient(w, r, &req) {
		return
	}
	resp, err := s.ctrl.Heartbeat(r.Context(), host.ID, req)
	if err != nil {
		if s.failReport(w, r, err) {
			return
		}
		if errors.Is(err, agent.ErrHostGone) || errors.Is(err, store.ErrNotFound) {
			notFound(w, err.Error())
			return
		}
		s.internal(w, r, "recording a heartbeat", err)
		return
	}
	kind := connectionKind(r.Context())
	if host.Connection != kind {
		if err := s.ctrl.Store().SetHostConnection(r.Context(), host.ID, kind); err != nil {
			s.internal(w, r, "recording the host connection", err)
			return
		}
		if updated, err := s.ctrl.Store().GetHost(r.Context(), host.ID); err == nil {
			s.ctrl.PublishHost(updated)
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// handleAgentTasks is the long poll.
//
// It blocks until this host has work or the wait elapses, which is what makes a
// task reach an agent in the same instant it is queued while an idle agent
// makes two or three requests a minute. The request's own read deadline is
// cleared for the same reason the server's WriteTimeout is zero.
func (s *Server) handleAgentTasks(w http.ResponseWriter, r *http.Request) {
	host := agentHost(r)
	wait := agent.DefaultPollWait
	if raw := strings.TrimSpace(r.URL.Query().Get("wait")); raw != "" {
		if secs, err := strconv.Atoi(raw); err == nil && secs > 0 {
			wait = time.Duration(secs) * time.Second
		}
	}
	// The poll outlives an ordinary request by design, so the deadline that
	// bounds an ordinary request must not apply to it.
	_ = http.NewResponseController(w).SetReadDeadline(time.Time{})

	batch, err := s.ctrl.PollTasks(r.Context(), host.ID, wait)
	if err != nil {
		s.internal(w, r, "waiting for tasks", err)
		return
	}
	if batch.Tasks == nil {
		batch.Tasks = []agent.Task{}
	}
	writeJSON(w, http.StatusOK, batch)
}

// handleAgentResult applies the outcome of one task.
func (s *Server) handleAgentResult(w http.ResponseWriter, r *http.Request) {
	host := agentHost(r)
	var res agent.TaskResult
	if !decodeLenient(w, r, &res) {
		return
	}
	if err := s.ctrl.ReportResult(r.Context(), host.ID, res); err != nil {
		s.fail(w, r, "applying a task result", err)
		return
	}
	noContent(w)
}

// handleAgentReport merges an agent's observations of its runners.
//
// The body is a bare JSON array rather than an object with one field: the agent
// sends []RunnerReport, and wrapping it here would mean the two halves of the
// protocol disagreeing about the wire format.
func (s *Server) handleAgentReport(w http.ResponseWriter, r *http.Request) {
	host := agentHost(r)
	var reports []agent.RunnerReport
	if !decodeLenient(w, r, &reports) {
		return
	}
	if err := s.ctrl.ReportRunners(r.Context(), host.ID, reports); err != nil {
		if s.failReport(w, r, err) {
			return
		}
		s.fail(w, r, "applying runner reports", err)
		return
	}
	noContent(w)
}

// handleAgentLogs consumes an agent's outbound log relay.
//
// This is the inverted half of log streaming: the controller can never dial an
// agent, so a viewer's request makes the controller queue a task, and the agent
// answers by opening this chunked POST. The body is read for as long as the
// runner produces output, which is why it is exempt from the body-size limit
// and clears the read deadline.
func (s *Server) handleAgentLogs(w http.ResponseWriter, r *http.Request) {
	streamID := chiURLParam(r, "stream_id")
	if streamID == "" {
		badRequest(w, "a log relay needs the stream ID from the stream_logs task")
		return
	}
	// A relayed stream lasts as long as the job does.
	_ = http.NewResponseController(w).SetReadDeadline(time.Time{})

	if err := s.ctrl.AcceptLogStream(agentHost(r).ID, streamID, r.Body); err != nil {
		if errors.Is(err, controller.ErrStreamUnknown) {
			// Nobody is watching any more -- the tab was closed between the
			// task being issued and the agent acting on it. That is ordinary,
			// and the agent stops when it sees the 404.
			notFound(w, err.Error())
			return
		}
		s.internal(w, r, "relaying a log stream", err)
		return
	}
	noContent(w)
}

