	"github.com/eyupio/zoomies/internal/auth"
)

func (s *Server) contextSourceAccess(w http.ResponseWriter, r *http.Request, id string) bool {
	actor, err := s.resolveIdentity(r)
	if err != nil {
		if errors.Is(err, auth.ErrAuthBackend) {
			s.internal(w, r, "checking source credentials", err)
			return false
		}
		unauthorized(w, "source credentials are no longer valid")
		return false
	}
	if !auth.Allowed(actor, auth.ActionContextRead) {
		forbidden(w, "source credentials no longer allow context.read")
		return false
	}
	allowed, err := s.auth.ContextAccess(r.Context(), actor, id)
	if err != nil {
		s.internal(w, r, "checking source access", err)
		return false
	}
	if !allowed {
		if actor.UserID == "" {
			forbidden(w, "source access requires an owned account")
			return false
		}
		notFound(w, "source repository is unavailable to this credential")
		return false
	}
	return true
}

func (s *Server) handleAIContextSource(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	id := chiURLParam(r, "id")
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	q := r.URL.Query()
	number := func(name string, fallback, min, max int) (int, bool) {
		text := q.Get(name)
		if text == "" {
			return fallback, true
		}
		n, err := strconv.Atoi(text)
		if err != nil || n < min || n > max {
			unprocessable(w, "choose a valid "+name, nil)
			return 0, false
		}
		return n, true
	}
	budget, ok := number("budget", 8000, 1024, aicontext.MaxResponseBytes)
	if !ok {
		return
	}
	offset, ok := number("offset", 0, 0, 1000000)
	if !ok {
		return
	}
	maxLimit := 100
	if strings.HasSuffix(r.URL.Path, "/search") {
		maxLimit = 12
	}
	limit, ok := number("limit", 12, 1, maxLimit)
	if !ok {
		return
	}
	if offset > 0 && q.Get("commit") == "" {
		unprocessable(w, "pin the returned commit when continuing a page", nil)
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 45*time.Second)
	defer cancel()
	snapshot, fresh, err := s.ctrl.VerifiedAIContextSnapshot(ctx, id)
	// Revocation during network verification must close the response as well.
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	if err != nil {
		conflict(w, "current source could not be verified; ask an administrator to recheck AI Context")
		return
	}
	if expected := q.Get("commit"); expected != "" && expected != snapshot.Manifest.SourceCommit {
		conflict(w, "source changed; restart retrieval using the current commit")
		return
	}
	var body []byte
	switch r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:] {
	case "overview":
		body, err = snapshot.FilePage(fresh.Digest, offset, limit, budget)
	case "read":
		body, err = snapshot.ReadPage(fresh.Digest, []string{q.Get("path")}, offset, budget)
	case "pack":
		body, err = snapshot.ReadPage(fresh.Digest, q["path"], offset, budget)
	case "search":
		body, err = snapshot.SearchResult(fresh.Digest, q.Get("query"), q.Get("prefix"), offset, limit, budget)
	default:
		notFound(w, "source operation")
		return
	}
	if err != nil {
		unprocessable(w, err.Error(), nil)
		return
	}
	if !s.contextSourceAccess(w, r, id) {
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(body)
}

package api

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// handleAIContextUpload receives a Zoomies-only snapshot from the managed
// workflow. It has no session and no API token: the only credential is the
// run's GitHub Actions OIDC token, minted for this controller's upload address,
// which the controller checks before it reads anything else the request says.
// It is mounted outside the API's body limit because a snapshot can be up to
// aicontext.MaxSnapshotBytes; this handler bounds the body itself.
func (s *Server) handleAIContextUpload(w http.ResponseWriter, r *http.Request) {
	audience := aicontext.UploadURLFor(s.cfg().Server.ExternalURL)
	if audience == "" {
		notFound(w, "this controller accepts Zoomies-only uploads only when server.external_url is an https address GitHub's runners can reach")
		return
	}
	raw, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
	if !ok || raw == "" {
		unauthorized(w, "send the workflow run's GitHub Actions OIDC token, minted for this upload address, as a bearer token")
		return
	}
	// The token first: nobody without one gets the controller to buffer a body.
	if err := s.ctrl.CheckAIContextUploadToken(r.Context(), raw, audience); err != nil {
		if errors.Is(err, github.ErrActionsToken) {
			unauthorized(w, "the GitHub Actions OIDC token is not valid for this controller: check that the workflow requests it for this upload address and that it has not expired")
			return
		}
		s.fail(w, r, "verifying the upload's GitHub Actions token", err)
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, aicontext.MaxSnapshotBytes+1))
	if err != nil {
		badRequest(w, "the upload body could not be read")
		return
	}
	if len(body) > aicontext.MaxSnapshotBytes {
		payloadTooLarge(w, "the snapshot is larger than 32 MiB; add exclusions to the repository's AI Context configuration")
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Minute)
	defer cancel()
	out, err := s.ctrl.IngestAIContextUpload(ctx, raw, audience, body)
	switch {
	case err == nil:
	case errors.Is(err, github.ErrActionsToken):
		unauthorized(w, "the GitHub Actions OIDC token is not valid for this controller: check that the workflow requests it for this upload address and that it has not expired")
		return
	case errors.Is(err, store.ErrNotFound):
		notFound(w, "no repository on this controller is set up for Zoomies-only output with this GitHub repository ID")
		return
	case errors.Is(err, controller.ErrAIContextUploadSuperseded):
		conflict(w, err.Error())
		return
	case errors.Is(err, controller.ErrAIContextUploadRefused):
		forbidden(w, err.Error())
		return
	default:
		s.fail(w, r, "verifying the uploaded AI context", err)
		return
	}
	var commit, snapshot string
	if out.Freshness != nil {
		commit, snapshot = out.Freshness.PublishedCommit, out.Freshness.Digest
	}
	s.auth.Auditor().Act(r.Context(), &auth.Identity{Kind: auth.KindSystem, Name: "github-actions"}, "context.upload", "ai_context", out.ID,
		map[string]any{"commit": commit, "snapshot_id": snapshot})
	writeJSON(w, http.StatusAccepted, map[string]any{"repository_id": out.ID, "commit": commit, "snapshot_id": snapshot})
}

package api

import (
	"encoding/json"
	"net/http"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// auditReadActions names, for each audited target kind, the action that lets a
// caller read that kind directly.
//
// Only the kinds an ordinary viewer cannot reach are listed. Pools, hosts,
// runners, installations and webhook deliveries are all readable at viewer, so
// their rows say nothing the caller could not fetch from the resource itself.
var auditReadActions = map[string]auth.Action{
	"user":       auth.ActionUsersRead,
	"api_token":  auth.ActionTokensRead,
	"join_token": auth.ActionJoinsRead,
	"settings":   auth.ActionSettingsRead,
	// Providers and machines are readable at viewer like pools are, so these
	// two rows withhold nothing from a person. They are here for the other
	// gate: a token narrowed to a few scopes is refused the documents for a
	// resource it was not given, and a token that cannot read providers
	// should not read a provider's whole configuration out of the row
	// recording a change to it.
	"provider": auth.ActionProvidersRead,
	"machine":  auth.ActionMachinesRead,
}

// handleListAudit answers GET /api/v1/audit.
//
// Two separate things keep a secret out of the response, and they are worth
// telling apart.
//
// A credential is gone before the row is ever written -- auth.Redact on the way
// in, plus the callers that strip what a name-based redaction cannot see. That
// is the half that has to happen at write time, because a row is kept for the
// life of the database and read by every viewer from then on.
//
// The other half is this one, and it is about reach rather than secrecy.
// audit.read is a viewer action while users.read, tokens.read, joins.read and
// settings.read are all admin ones, so returning every document as stored made
// the audit log a way around that: a viewer who could not call GET /users could
// read a user's email, display name and OIDC subject out of the row recording
// the change to it. Those documents are withheld from a caller who could not
// have fetched them directly. The row itself stays -- who did what to which
// thing and when is the part a viewer is meant to see.
func (s *Server) handleListAudit(w http.ResponseWriter, r *http.Request) {
	filter := store.AuditFilter{
		ActorIDs:    queryList(r, "actor_id"),
		Actions:     queryList(r, "action"),
		TargetKinds: queryList(r, "target_kind"),
		TargetID:    r.URL.Query().Get("target_id"),
		Search:      r.URL.Query().Get("q"),
	}
	var err error
	if filter.Since, err = queryTime(r, "since"); err != nil {
		badRequestField(w, "since", err.Error())
		return
	}
	if filter.Until, err = queryTime(r, "until"); err != nil {
		badRequestField(w, "until", err.Error())
		return
	}

	p := parsePage(r)
	events, total, err := s.ctrl.Store().ListAudit(r.Context(), filter, p)
	if err != nil {
		s.internal(w, r, "reading the audit log", err)
		return
	}
	id := Identity(r.Context())
	for i := range events {
		row := auditRowFor(*events[i], id)
		events[i] = &row
	}
	writeJSON(w, http.StatusOK, newPage(events, total, p))
}

// auditRowFor is an audit row as this caller may read it. The list and the
// event stream both answer through it, because the stream carries every new
// row as it is written and a filter applied only to the list was no filter.
//
// The documents are withheld by what the row is about; the address is
// withheld by rank, in the same pass. An audit row's ip says where a
// colleague was working from, which is a fact about a person rather than
// about the fleet -- an operator who can read that their administrator
// signed in from a hotel has learned something the audit log exists to
// record, not to publish. Administrators keep it, because chasing a
// suspicious sign-in is the reason the column is there.
//
// A settings row is narrowed once more for anybody but the platform: the
// settings page does not show an administrator the platform's keys, so the
// row recording a change to backup.directory must not either.
func auditRowFor(ev store.AuditEvent, id *auth.Identity) store.AuditEvent {
	action, guarded := auditReadActions[ev.TargetKind]
	if guarded && !auth.Allowed(id, action) {
		ev.Before, ev.After = "", ""
	}
	if ev.TargetKind == "settings" && (id == nil || !id.Role.AtLeast(store.RolePlatform)) {
		ev.Before, ev.After = withoutPlatformKeys(ev.Before), withoutPlatformKeys(ev.After)
	}
	if id == nil || !id.Role.AtLeast(store.RoleAdmin) {
		ev.IP = ""
	}
	return ev
}

// withoutPlatformKeys drops the platform's settings from a settings row's
// document. A document it cannot read is dropped whole: failing open here
// would be the leak this exists to close.
func withoutPlatformKeys(doc string) string {
	if doc == "" {
		return ""
	}
	var keys map[string]json.RawMessage
	if err := json.Unmarshal([]byte(doc), &keys); err != nil {
		return ""
	}
	for k := range keys {
		if st, ok := config.LookupSetting(k); ok && platformsOwn(st) {
			delete(keys, k)
		}
	}
	if len(keys) == 0 {
		return ""
	}
	out, err := json.Marshal(keys)
	if err != nil {
		return ""
	}
	return string(out)
}

// handleAuditActions lists the distinct action names, for the filter menu.
func (s *Server) handleAuditActions(w http.ResponseWriter, r *http.Request) {
	actions, err := s.ctrl.Store().AuditActions(r.Context())
	if err != nil {
		s.internal(w, r, "reading the audit log's action names", err)
		return
	}
	writeJSON(w, http.StatusOK, newList(actions))
}

package api

import (
	"crypto/subtle"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// oidcStateCookie carries the state of a single sign-on handshake in the
// browser that started it, so that the callback can only be finished from
// there. The server's own record of the state proves the handshake was begun
// on this controller; the cookie proves it was begun by this browser, which
// is what stops an attacker from handing their own half-finished sign-in to
// a victim and signing the victim in as them.
const oidcStateCookie = "zoomies_oidc_state"

// oidcCookiePath scopes the cookie to the two SSO routes, so it rides along
// with nothing else.
const oidcCookiePath = "/api/v1/auth/oidc"

// identityResponse is the caller, as the UI's session store holds it.
type identityResponse struct {
	Kind               string     `json:"kind"`
	ID                 string     `json:"id"`
	Name               string     `json:"name"`
	Role               store.Role `json:"role"`
	Scopes             []string   `json:"scopes"`
	MustChangePassword bool       `json:"must_change_password"`
}

func newIdentityResponse(id *auth.Identity, mustChange bool) identityResponse {
	scopes := id.Scopes
	if scopes == nil {
		scopes = []string{}
	}
	return identityResponse{
		Kind: id.Kind, ID: id.ID, Name: id.Name, Role: id.Role,
		Scopes: scopes, MustChangePassword: mustChange,
	}
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

type bootstrapRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
	Email    string `json:"email"`
	// SetupToken is printed in the controller's log while no account exists.
	SetupToken string `json:"setup_token"`
}

// handleBootstrap creates the first administrator.
//
// It is unauthenticated because on a fresh install there is nobody to
// authenticate as, and it closes permanently once any account exists -- the
// auth service checks that under a mutex.
//
// "No account exists yet" is not by itself a safe condition, though: it is one
// a stranger can satisfy too, and on a controller published to the internet the
// first person to load this page would otherwise become its administrator. So
// the request also has to carry the setup token this process printed at
// startup, which proves the caller can read the controller's log. Whoever
// deployed it can; a passer-by cannot.
func (s *Server) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	var req bootstrapRequest
	if !decode(w, r, &req) {
		return
	}

	var fields []fieldError
	if strings.TrimSpace(req.Username) == "" {
		fields = append(fields, fieldError{"username", "the first administrator needs a name to sign in with"})
	}
	if err := auth.CheckPassword(req.Password); err != nil {
		fields = append(fields, fieldError{"password", err.Error()})
	}
	if strings.TrimSpace(req.SetupToken) == "" {
		fields = append(fields, fieldError{"setup_token", "paste the setup token from the controller's log; it is on a line beginning \"setup token\""})
	}
	if len(fields) > 0 {
		unprocessable(w, "the first administrator could not be created", fields)
		return
	}
	// Refused before the account exists: this endpoint closes for good the
	// moment it succeeds, and an administrator whose session the browser then
	// throws away has no second try at it.
	if msg := s.cookieWouldBeDropped(r); msg != "" {
		badRequest(w, msg)
		return
	}

	u, err := s.auth.CreateFirstAdminWithSetupToken(r.Context(), req.Username, req.Password, req.SetupToken)
	if err != nil {
		switch {
		case errors.Is(err, auth.ErrAlreadyBootstrapped):
			conflict(w, err.Error())
		case errors.Is(err, auth.ErrBadSetupToken):
			// Worth a line of its own: a burst of these is somebody guessing.
			s.logger(r).Warn("a bootstrap attempt carried the wrong setup token", "ip", ClientIP(r.Context()))
			unprocessable(w, err.Error(), []fieldError{{"setup_token", err.Error()}})
		case errors.Is(err, auth.ErrInvalidInput):
			unprocessable(w, err.Error(), nil)
		default:
			// This route is anonymous, so a database error must not come back
			// as the text of a validation message.
			s.fail(w, r, "creating the first administrator", err)
		}
		return
	}

	// The address is stored separately from the account itself so that the
	// admin can be created without an email and add one later.
	if email := strings.TrimSpace(req.Email); email != "" {
		u.Email = email
		if err := s.auth.UpdateUser(r.Context(), u); err != nil {
			s.logger(r).Warn("could not save the first administrator's email address", "error", err)
		}
	}

	id := &auth.Identity{Kind: auth.KindUser, ID: u.ID, Name: u.Username, Role: u.Role, IP: ClientIP(r.Context())}
	s.auth.AuditBootstrap(r.Context(), id, u, auth.BootstrapSetupToken, "")

	token, err := s.auth.NewSession(r.Context(), u, ClientIP(r.Context()), r.UserAgent())
	if err != nil {
		// The account exists, which is the important half. Say so rather than
		// leaving the operator wondering whether to try again.
		s.logger(r).Error("created the first administrator but could not start a session", "error", err)
		writeJSON(w, http.StatusCreated, newIdentityResponse(id, u.MustChangePassword))
		return
	}
	s.setSessionCookie(w, token)
	writeJSON(w, http.StatusCreated, newIdentityResponse(id, u.MustChangePassword))
}

// ---------------------------------------------------------------------------
// Password login
// ---------------------------------------------------------------------------

type loginRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

// handleLogin signs a person in with a password.
//
// A wrong password and an unknown username are the same 401 with the same
// message and, thanks to the auth service's dummy verification, very nearly the
// same timing: telling an attacker which usernames exist is a gift for nothing
// in return.
func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	var req loginRequest
	if !decode(w, r, &req) {
		return
	}
	if msg := s.cookieWouldBeDropped(r); msg != "" {
		badRequest(w, msg)
		return
	}
	ip := ClientIP(r.Context())

	u, token, err := s.auth.Login(r.Context(), req.Username, req.Password, ip, r.UserAgent())
	var pending *auth.SecondStepRequired
	if errors.As(err, &pending) {
		// Not a failure and not yet a sign-in: the password was right and the
		// account has a code to give, or an authenticator to set up.
		s.startSecondStep(w, pending)
		return
	}
	if err != nil {
		// The auth service writes the audit row, because what may be recorded
		// about a username nobody recognises is its decision, not this layer's.
		s.auth.AuditLoginFailure(r.Context(), req.Username, ip, err)
		switch {
		case errors.Is(err, auth.ErrRateLimited):
			rateLimited(w, err.Error(), s.auth.LoginRetryAfter(ip))
		case errors.Is(err, auth.ErrPasswordSignInOff):
			forbidden(w, err.Error())
		case errors.Is(err, auth.ErrInvalidCredentials),
			errors.Is(err, auth.ErrAccountDisabled),
			errors.Is(err, auth.ErrSSOOnly):
			unauthorized(w, err.Error())
		default:
			s.internal(w, r, "signing in", err)
		}
		return
	}

	s.setSessionCookie(w, token)
	id := &auth.Identity{Kind: auth.KindUser, ID: u.ID, Name: u.Username, Role: u.Role, IP: ip}
	s.auth.Auditor().Auth(r.Context(), id, "auth.login", map[string]any{"role": u.Role})
	writeJSON(w, http.StatusOK, newIdentityResponse(id, u.MustChangePassword))
}

// cookieWouldBeDropped says why a session minted for this request would never
// be seen again, or "" when it would be kept.
//
// The compose deployment tells Zoomies its external URL is https, because a
// proxy terminates TLS in front of it, and the session cookie is marked Secure
// accordingly. An operator who then opens the container directly -- by IP,
// over plain http, to check it is up before DNS exists -- creates the first
// administrator, is signed in by a 201, and is immediately signed out again:
// the browser refuses to keep a Secure cookie from an insecure page, every
// later request is anonymous, and each login answers 200 and changes nothing.
// Nothing in that loop is an error anyone sees.
//
// The browser's own Origin header says which scheme the page was loaded over,
// which is the one fact the server cannot otherwise know: the request itself
// may arrive over plain http from a perfectly good TLS-terminating proxy. A
// loopback origin is left alone, because browsers treat localhost as a secure
// context and do keep the cookie there.
func (s *Server) cookieWouldBeDropped(r *http.Request) string {
	if !s.cfg().CookieSecureValue() {
		return ""
	}
	from := strings.TrimSpace(r.Header.Get("Origin"))
	if from == "" {
		from = strings.TrimSpace(r.Header.Get("Referer"))
	}
	u, err := url.Parse(from)
	if err != nil || !strings.EqualFold(u.Scheme, "http") || u.Host == "" {
		return ""
	}
	host := u.Hostname()
	if host == "localhost" || strings.HasSuffix(host, ".localhost") {
		return ""
	}
	if ip := net.ParseIP(host); ip != nil && ip.IsLoopback() {
		return ""
	}
	where := s.cfg().Server.ExternalURL
	if where == "" {
		where = "the https address"
	}
	return fmt.Sprintf("this page was opened over plain http (%s), and the session cookie is marked Secure "+
		"(security.cookie_secure, which an https server.external_url turns on), so your browser would throw the cookie away "+
		"and signing in would appear to do nothing. Open %s instead, through whatever terminates TLS in front of this controller; "+
		"to test over plain http, set security.cookie_secure to false (ZOOMIES_COOKIE_SECURE=false).",
		u.Scheme+"://"+u.Host, where)
}

// handleLogout ends the session behind the cookie and clears it.
func (s *Server) handleLogout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie(SessionCookie); err == nil {
		if err := s.auth.Logout(r.Context(), c.Value); err != nil {
			s.logger(r).Warn("could not delete a session on sign-out", "error", err)
		}
	}
	s.clearSessionCookie(w)
	s.auth.Auditor().Auth(r.Context(), Identity(r.Context()), "auth.logout", nil)
	noContent(w)
}

// logoutOthersResponse says what "sign out other sessions" ended beyond the
// sessions, so the page can say it.
type logoutOthersResponse struct {
	MCPConnectionsEnded int `json:"mcp_connections_ended"`
}

// handleLogoutOthers answers POST /api/v1/auth/logout-others: every other
// session this account has is ended, and so is every MCP connection, while
// this browser stays signed in.
func (s *Server) handleLogoutOthers(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	if id.Kind != auth.KindUser || id.ID == "" {
		forbidden(w, "only a signed-in account has other sessions to end; an API token has none")
		return
	}
	keep := ""
	if c, err := r.Cookie(SessionCookie); err == nil {
		keep = c.Value
	}
	n, err := s.auth.LogoutOthers(r.Context(), id, keep)
	if err != nil {
		s.fail(w, r, "ending other sessions", err)
		return
	}
	s.auth.Auditor().Auth(r.Context(), id, "auth.logout_others", map[string]any{"mcp_connections_ended": n})
	writeJSON(w, http.StatusOK, logoutOthersResponse{MCPConnectionsEnded: n})
}

// handleSession returns who the caller is. The UI calls it on boot to decide
// between the app and the login page.
func (s *Server) handleSession(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	must := false
	if id.Kind == auth.KindUser && id.ID != "" {
		if u, err := s.ctrl.Store().GetUser(r.Context(), id.ID); err == nil {
			must = u.MustChangePassword
		}
	}
	writeJSON(w, http.StatusOK, newIdentityResponse(id, must))
}

const maxPreferenceBytes = 64 << 10

type tableLayoutPreference struct {
	Widths map[string]float64 `json:"widths,omitempty"`
	Order  []string           `json:"order,omitempty"`
}

type userPreferences struct {
	TableLayouts map[string]tableLayoutPreference `json:"table_layouts,omitempty"`
}

// handleGetPreferences returns choices belonging to this account rather than
// to the fleet. API tokens and auth-disabled sessions have no account to carry
// them, so those clients continue to use the browser fallback.
func (s *Server) handleGetPreferences(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	if id.Kind != auth.KindUser || !store.HasPrefix(id.ID, store.PrefixUser) {
		writeJSON(w, http.StatusOK, userPreferences{})
		return
	}
	raw, err := s.ctrl.Store().UserPreferences(r.Context(), id.ID)
	if err != nil {
		s.internal(w, r, "reading account preferences", err)
		return
	}
	var preferences userPreferences
	if err := json.Unmarshal(raw, &preferences); err != nil {
		s.internal(w, r, "reading account preferences", err)
		return
	}
	writeJSON(w, http.StatusOK, preferences)
}

// handlePutPreferences replaces the small, private table-layout document. A
// whole replacement makes two open tabs converge on the latest deliberate
// layout and avoids a patch language for data that is never collaboratively
// edited.
func (s *Server) handlePutPreferences(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	if id.Kind != auth.KindUser || !store.HasPrefix(id.ID, store.PrefixUser) {
		forbidden(w, "only a signed-in account can save preferences")
		return
	}
	var preferences userPreferences
	if !decode(w, r, &preferences) {
		return
	}
	if len(preferences.TableLayouts) > 100 {
		unprocessable(w, "too many table layouts", nil)
		return
	}
	for tableID, layout := range preferences.TableLayouts {
		if len(tableID) == 0 || len(tableID) > 100 || len(layout.Widths) > 100 || len(layout.Order) > 100 {
			unprocessable(w, "a table layout is too large", nil)
			return
		}
		for columnID, width := range layout.Widths {
			if len(columnID) == 0 || len(columnID) > 100 || width < 40 || width > 1000 {
				unprocessable(w, "a table column width is outside the supported range", nil)
				return
			}
		}
		for _, columnID := range layout.Order {
			if len(columnID) == 0 || len(columnID) > 100 {
				unprocessable(w, "a table column id is invalid", nil)
				return
			}
		}
	}
	raw, err := json.Marshal(preferences)
	if err != nil {
		s.internal(w, r, "encoding account preferences", err)
		return
	}
	if len(raw) > maxPreferenceBytes {
		unprocessable(w, "table preferences are too large", nil)
		return
	}
	if err := s.ctrl.Store().SetUserPreferences(r.Context(), id.ID, raw); err != nil {
		s.internal(w, r, "saving account preferences", err)
		return
	}
	writeJSON(w, http.StatusOK, preferences)
}

type changePasswordRequest struct {
	OldPassword string `json:"old_password"`
	NewPassword string `json:"new_password"`
}

// handleChangePassword changes the caller's own password.
//
// Every other session for the account is ended by the auth service, so a stolen
// cookie does not survive the change. This browser gets a fresh one, because
// asking someone to sign in again immediately after choosing a new password
// reads as a failure.
func (s *Server) handleChangePassword(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	if id.Kind != auth.KindUser || id.ID == "" {
		forbidden(w, "only a signed-in account can change its own password; an API token has none to change")
		return
	}

	var req changePasswordRequest
	if !decode(w, r, &req) {
		return
	}
	if err := auth.CheckPassword(req.NewPassword); err != nil {
		unprocessable(w, "that password cannot be used", []fieldError{{"new_password", err.Error()}})
		return
	}

	ip := ClientIP(r.Context())
	if err := s.auth.ChangePassword(r.Context(), id.ID, req.OldPassword, req.NewPassword, ip); err != nil {
		switch {
		case errors.Is(err, auth.ErrRateLimited):
			rateLimited(w, err.Error(), s.auth.LoginRetryAfter(ip))
		case errors.Is(err, store.ErrNotFound):
			notFound(w, "this account no longer exists")
		case errors.Is(err, auth.ErrSSOOnly):
			unprocessable(w, err.Error(), []fieldError{{"new_password", err.Error()}})
		case errors.Is(err, auth.ErrWrongPassword):
			// The common case, and the caller's to fix, not an internal failure.
			unprocessable(w, err.Error(), []fieldError{{"old_password", err.Error()}})
		case errors.Is(err, auth.ErrInvalidInput):
			unprocessable(w, err.Error(), []fieldError{{"new_password", err.Error()}})
		default:
			s.fail(w, r, "changing the password", err)
		}
		return
	}

	s.auth.Auditor().Auth(r.Context(), id, "auth.password_changed", nil)

	// Every session for this account has just been ended, this browser's
	// included, so failing to mint the replacement signs the operator out at
	// the moment they were told the change worked. Nothing here can put that
	// right in the response -- the change did happen, and reporting it as a
	// failure would be worse -- but it must not pass in silence: the operator
	// is about to land on the login page with no idea why.
	u, err := s.ctrl.Store().GetUser(r.Context(), id.ID)
	if err != nil {
		s.logger(r).Warn("could not re-read the account after a password change, so this browser was not given a new session",
			"user", id.Name, "error", err)
	} else if token, terr := s.auth.NewSession(r.Context(), u, ClientIP(r.Context()), r.UserAgent()); terr != nil {
		s.logger(r).Warn("could not issue a new session after a password change", "user", id.Name, "error", terr)
	} else {
		s.setSessionCookie(w, token)
	}
	noContent(w)
}

// ---------------------------------------------------------------------------
// Single sign-on
// ---------------------------------------------------------------------------

// handleOIDCStart sends the browser to the identity provider.
//
// The state is remembered twice: once by the provider, which holds the nonce
// that goes with it, and once in a cookie on this browser. The cookie is what
// ties the handshake to the person who began it -- without it, a state minted
// by an attacker's own sign-in is one this controller would happily accept from
// anybody's browser, which is a login CSRF: the victim ends up signed in as the
// attacker, and everything they then do happens in the attacker's account.
func (s *Server) handleOIDCStart(w http.ResponseWriter, r *http.Request) {
	sso := s.oidcProvider()
	if !sso.Enabled() {
		s.ssoUnavailable(w)
		return
	}
	// Bound how often an address may open a fresh handshake, or an attacker
	// fills the pending-state cache (bounded, in memory) in one burst and
	// every real SSO sign-in comes back ErrTooManyPendingSignIns until states
	// expire. The login limiter is shared: both endpoints begin a sign-in.
	ip := ClientIP(r.Context())
	if !s.auth.AllowSSOStart(ip) {
		rateLimited(w, auth.ErrRateLimited.Error(), s.auth.SSOStartRetryAfter(ip))
		return
	}
	authURL, state, err := sso.Start()
	if err != nil {
		if errors.Is(err, auth.ErrTooManyPendingSignIns) {
			// A finished flow will free a slot inside the state TTL, so a
			// short Retry-After is the right thing to promise.
			rateLimited(w, err.Error(), 30*time.Second)
			return
		}
		s.internal(w, r, "starting the single sign-on handshake", err)
		return
	}
	// Where to land afterwards, when the sign-in began somewhere other than
	// the front page -- an MCP client's consent screen, which is the one
	// place a person arrives already mid-task. Only this controller's own
	// consent page is accepted, so the parameter cannot be used to send a
	// freshly signed-in browser anywhere else.
	if back := r.URL.Query().Get("return_to"); consentReturn(back) {
		http.SetCookie(w, &http.Cookie{
			Name: oidcReturnCookie, Value: back, Path: oidcCookiePath, HttpOnly: true,
			Secure: s.cfg().CookieSecureValue(), SameSite: http.SameSiteLaxMode,
			MaxAge: int(auth.OIDCStateTTL / time.Second),
		})
	}
	http.SetCookie(w, &http.Cookie{
		Name:     oidcStateCookie,
		Value:    state,
		Path:     oidcCookiePath,
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		// Lax, because the provider brings the browser back with a top-level
		// GET, which is exactly the navigation Lax still sends cookies on.
		SameSite: http.SameSiteLaxMode,
		MaxAge:   int(auth.OIDCStateTTL / time.Second),
	})
	http.Redirect(w, r, authURL, http.StatusFound)
}

// clearOIDCStateCookie forgets the handshake, whichever way it ended.
func (s *Server) clearOIDCStateCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     oidcStateCookie,
		Value:    "",
		Path:     oidcCookiePath,
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteLaxMode,
		MaxAge:   -1,
		Expires:  time.Unix(0, 0),
	})
}

// handleOIDCCallback finishes the handshake and drops the browser back into the
// app.
//
// Failures redirect to the login page with a message rather than rendering an
// error document: whoever is looking at this is a person in a browser who was
// trying to sign in, and the login page is where they can try again.
func (s *Server) handleOIDCCallback(w http.ResponseWriter, r *http.Request) {
	sso := s.oidcProvider()
	if !sso.Enabled() {
		s.ssoUnavailable(w)
		return
	}
	q := r.URL.Query()
	if e := q.Get("error"); e != "" {
		desc := q.Get("error_description")
		if desc == "" {
			desc = e
		}
		s.clearOIDCStateCookie(w)
		s.redirectToLogin(w, r, "the identity provider refused the sign-in: "+desc)
		return
	}

	// The state has to be the one this browser was handed when it started.
	// Checked before the server-side state is spent, so a callback that
	// arrives in the wrong browser leaves the real one able to finish.
	if c, err := r.Cookie(oidcStateCookie); err != nil || c.Value == "" ||
		subtle.ConstantTimeCompare([]byte(c.Value), []byte(q.Get("state"))) != 1 {
		s.logger(r).Warn("a single sign-on callback arrived in a browser that did not start it")
		s.clearOIDCStateCookie(w)
		s.redirectToLogin(w, r, "this sign-in did not start in this browser, or took longer than "+
			auth.OIDCStateTTL.String()+"; start again from the login page")
		return
	}
	s.clearOIDCStateCookie(w)

	claims, err := sso.Complete(r.Context(), q.Get("state"), q.Get("code"))
	if err != nil {
		s.logger(r).Warn("a single sign-on callback could not be completed", "error", err)
		s.redirectToLogin(w, r, err.Error())
		return
	}

	u, err := sso.EnsureUser(r.Context(), s.ctrl.Store(), claims, sso.AllowSignup())
	if err != nil {
		s.logger(r).Warn("a single sign-on login matched no account", "subject", claims.Subject, "error", err)
		s.redirectToLogin(w, r, err.Error())
		return
	}
	if u.Disabled {
		s.redirectToLogin(w, r, auth.ErrAccountDisabled.Error())
		return
	}

	ip := ClientIP(r.Context())
	token, err := s.auth.NewSession(r.Context(), u, ip, r.UserAgent())
	if err != nil {
		s.internal(w, r, "starting a session after single sign-on", err)
		return
	}
	s.setSessionCookie(w, token)
	if err := s.ctrl.Store().TouchLogin(r.Context(), u.ID, s.auth.Now()); err != nil {
		s.logger(r).Warn("could not record a single sign-on login", "user", u.Username, "error", err)
	}
	s.auth.Auditor().Auth(r.Context(),
		&auth.Identity{Kind: auth.KindUser, ID: u.ID, Name: u.Username, Role: u.Role, IP: ip},
		"auth.login", map[string]any{"method": "oidc", "role": u.Role})

	landing := "/"
	if c, err := r.Cookie(oidcReturnCookie); err == nil && consentReturn(c.Value) {
		landing = c.Value
	}
	http.SetCookie(w, &http.Cookie{Name: oidcReturnCookie, Value: "", Path: oidcCookiePath, HttpOnly: true,
		Secure: s.cfg().CookieSecureValue(), SameSite: http.SameSiteLaxMode, MaxAge: -1, Expires: time.Unix(0, 0)})
	http.Redirect(w, r, landing, http.StatusFound)
}

// oidcReturnCookie remembers where a single sign-on that began on the MCP
// consent screen goes back to.
const oidcReturnCookie = "zoomies_oidc_return"

// consentReturn reports whether a return address is this controller's own
// consent page for one waiting request, and nothing else.
func consentReturn(v string) bool {
	u, err := url.Parse(v)
	if err != nil || u.Scheme != "" || u.Host != "" || u.Path != consentPath || u.Fragment != "" {
		return false
	}
	q := u.Query()
	return len(q) == 1 && store.LooksGenerated(q.Get("request")) && store.HasPrefix(q.Get("request"), store.PrefixOAuthRequest)
}

func (s *Server) ssoUnavailable(w http.ResponseWriter) {
	msg := "single sign-on is not configured on this controller; sign in with a username and password"
	if s.oidcFailure() != nil {
		msg = "single sign-on is configured but could not be set up: " + s.oidcFailure().Error()
	}
	writeError(w, http.StatusServiceUnavailable, errorEnvelope{Error: errorBody{
		Code: codeInternal, Message: msg,
	}})
}

// redirectToLogin sends a failed sign-in back to the login page with the reason
// in the query string, which is where the UI renders it.
func (s *Server) redirectToLogin(w http.ResponseWriter, r *http.Request, reason string) {
	http.Redirect(w, r, "/login?error="+urlQueryEscape(reason), http.StatusFound)
}

package api

import (
	"errors"
	"net/http"
	"net/url"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// Adding a destination from the page.
//
// `backup.remotes` in zoomies.yaml describes destinations too, and it stays --
// it is the one readable on a host whose database is gone. This is the other
// half: the destinations somebody adds, tests and rotates in the UI, stored as
// rows with their two secrets sealed under the instance key exactly as a
// provider's credential is.
//
// The secrets travel one way. They arrive in a body, they are sealed before
// anything else happens to them, and no response ever carries them back: the
// page is told whether one is set, which is the only thing it can act on.

// remoteInput is the body of a create or an update.
//
// Every field is a pointer so that a PATCH can carry the two an operator
// actually changed. The two secrets follow the convention the rest of the API
// uses for a credential: absent leaves what is stored, a value replaces it,
// and an explicit empty string clears it -- which is how a passphrase is
// removed from a destination that should send the plain archive.
type remoteInput struct {
	Name        *string `json:"name"`
	Endpoint    *string `json:"endpoint"`
	Region      *string `json:"region"`
	Bucket      *string `json:"bucket"`
	Prefix      *string `json:"prefix"`
	AccessKeyID *string `json:"access_key_id"`
	SecretKey   *string `json:"secret_access_key"`
	Passphrase  *string `json:"passphrase"`
	PathStyle   *bool   `json:"path_style"`
	Keep        *int    `json:"keep"`
	Enabled     *bool   `json:"enabled"`
}

// apply writes the input over a row and returns what is wrong with the result.
func (in *remoteInput) apply(row *store.BackupRemote, allowPrivate bool) []fieldError {
	if in.Name != nil {
		row.Name = strings.ToLower(strings.TrimSpace(*in.Name))
	}
	if in.Endpoint != nil {
		row.Endpoint = strings.TrimRight(strings.TrimSpace(*in.Endpoint), "/")
	}
	if in.Region != nil {
		row.Region = strings.TrimSpace(*in.Region)
	}
	if in.Bucket != nil {
		row.Bucket = strings.TrimSpace(*in.Bucket)
	}
	if in.Prefix != nil {
		row.Prefix = strings.Trim(strings.TrimSpace(*in.Prefix), "/")
	}
	if in.AccessKeyID != nil {
		row.AccessKeyID = strings.TrimSpace(*in.AccessKeyID)
	}
	if in.PathStyle != nil {
		style := *in.PathStyle
		row.PathStyle = &style
	}
	if in.Keep != nil {
		row.Keep = *in.Keep
	}
	if in.Enabled != nil {
		row.Enabled = *in.Enabled
	}
	return validateRemoteRow(row, allowPrivate)
}

// validateRemoteRow refuses a destination that could not work, in the words
// the validator uses about the same mistake in the configuration file.
func validateRemoteRow(row *store.BackupRemote, allowPrivate bool) []fieldError {
	var errs []fieldError
	if !config.ValidRemoteName(row.Name) {
		errs = append(errs, fieldError{"name",
			"use lower-case letters, digits and dashes, such as offsite or s3-frankfurt -- and not " +
				strings.Join(config.ReservedRemoteNames, " or ") + ", which the API already uses where the name goes"})
	}
	if strings.TrimSpace(row.Bucket) == "" {
		errs = append(errs, fieldError{"bucket",
			"name the bucket the archives go in. Zoomies never creates one: a destination that appeared by itself is one nobody has set the retention or access policy of"})
	}
	u, err := url.Parse(strings.TrimSpace(row.Endpoint))
	switch {
	case strings.TrimSpace(row.Endpoint) == "":
		errs = append(errs, fieldError{"endpoint",
			"give the service's URL, such as https://s3.eu-west-2.amazonaws.com or http://minio:9000"})
	case err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https"):
		errs = append(errs, fieldError{"endpoint",
			"that is not an HTTP URL. The scheme is what decides whether the connection is encrypted, so it has to be there"})
	default:
		if f := config.CheckOutboundURL("endpoint", row.Endpoint, allowPrivate); f != nil {
			errs = append(errs, fieldError{"endpoint", f.Title + ". " + f.Fix})
		}
	}
	if row.Keep < 0 {
		errs = append(errs, fieldError{"keep", "use 0 to keep every copy, or the number of copies this destination should hold"})
	}
	return errs
}

// handleCreateBackupRemote answers POST /api/v1/backups/remotes.
func (s *Server) handleCreateBackupRemote(w http.ResponseWriter, r *http.Request) {
	if s.key == nil {
		s.noEncryptionKey(w)
		return
	}
	var in remoteInput
	if !decode(w, r, &in) {
		return
	}
	row := &store.BackupRemote{Enabled: true}
	errs := in.apply(row, s.cfg().Security.AllowPrivateEgress)
	if in.SecretKey == nil || strings.TrimSpace(*in.SecretKey) == "" {
		errs = append(errs, fieldError{"secret_access_key",
			"a destination with no secret key would have every request to it refused"})
	}
	errs = append(errs, s.remoteNameErrors(r, row.Name, "")...)
	if len(errs) > 0 {
		unprocessable(w, "this backup remote cannot be created as described", errs)
		return
	}

	if err := s.ctrl.Store().CreateBackupRemote(r.Context(), row); err != nil {
		s.fail(w, r, "creating the backup remote", err)
		return
	}
	if !s.sealRemoteSecrets(w, r, row, &in) {
		return
	}
	// The row is the audit document: the secrets are sealed bytes behind
	// json:"-", so there is nothing here to blank first.
	s.auth.Auditor().Created(r.Context(), Identity(r.Context()), "backup_remote", row.ID, row)
	// A destination that has just been added is one the fleet has nothing in
	// yet, so the copies it is missing go now rather than within the hour.
	s.ctrl.NudgeBackupRemotes()
	writeJSON(w, http.StatusCreated, s.remoteStatus(r, row.Name))
}

// handleUpdateBackupRemote answers PATCH /api/v1/backups/remotes/{name}.
func (s *Server) handleUpdateBackupRemote(w http.ResponseWriter, r *http.Request) {
	row, ok := s.storedRemote(w, r)
	if !ok {
		return
	}
	var in remoteInput
	if !decode(w, r, &in) {
		return
	}
	if s.key == nil && (in.SecretKey != nil && strings.TrimSpace(*in.SecretKey) != "" ||
		in.Passphrase != nil && strings.TrimSpace(*in.Passphrase) != "") {
		s.noEncryptionKey(w)
		return
	}
	before := *row
	errs := in.apply(row, s.cfg().Security.AllowPrivateEgress)
	errs = append(errs, s.remoteNameErrors(r, row.Name, row.ID)...)
	if len(errs) > 0 {
		unprocessable(w, "this backup remote cannot be changed as described", errs)
		return
	}
	if err := s.ctrl.Store().UpdateBackupRemote(r.Context(), row); err != nil {
		s.fail(w, r, "saving the backup remote", err)
		return
	}
	if !s.sealRemoteSecrets(w, r, row, &in) {
		return
	}
	s.auth.Auditor().Updated(r.Context(), Identity(r.Context()), "backup_remote", row.ID, &before, row)
	s.ctrl.NudgeBackupRemotes()
	writeJSON(w, http.StatusOK, s.remoteStatus(r, row.Name))
}

// handleDeleteBackupRemote answers DELETE /api/v1/backups/remotes/{name}.
//
// What the bucket holds is left alone. Forgetting where the copies are is not
// the same as deciding they should not exist, and an operator who wants them
// gone deletes them from the listing first -- where each one is named.
func (s *Server) handleDeleteBackupRemote(w http.ResponseWriter, r *http.Request) {
	row, ok := s.storedRemote(w, r)
	if !ok {
		return
	}
	if err := s.ctrl.Store().DeleteBackupRemote(r.Context(), row.ID); err != nil {
		s.fail(w, r, "removing the backup remote", err)
		return
	}
	s.auth.Auditor().Deleted(r.Context(), Identity(r.Context()), "backup_remote", row.ID, row)
	noContent(w)
}

// handleCheckDraftRemote answers POST /api/v1/backups/remotes/check: try a
// destination that has not been saved.
//
// It exists so that a secret key is proved before it is stored rather than
// after, which is the difference between finding out now and finding out at
// three in the morning. A destination that refuses is a 200 with ok:false: the
// check ran, and what it found is the result.
func (s *Server) handleCheckDraftRemote(w http.ResponseWriter, r *http.Request) {
	// The same body a create takes, because the point is to test exactly what
	// is about to be stored -- including a secret key the database has never
	// seen.
	var in remoteInput
	if !decode(w, r, &in) {
		return
	}
	row := &store.BackupRemote{Enabled: true, Name: "draft"}
	if in.Name != nil && strings.TrimSpace(*in.Name) != "" {
		row.Name = strings.ToLower(strings.TrimSpace(*in.Name))
	}
	in.Name = nil
	if errs := in.apply(row, s.cfg().Security.AllowPrivateEgress); len(errs) > 0 {
		unprocessable(w, "this backup remote cannot be tested as described", errs)
		return
	}

	draft := config.BackupRemote{
		Name: row.Name, Endpoint: row.Endpoint, Region: row.Region, Bucket: row.Bucket,
		Prefix: row.Prefix, AccessKeyID: row.AccessKeyID, PathStyle: row.PathStyle,
	}
	switch {
	case in.SecretKey != nil && strings.TrimSpace(*in.SecretKey) != "":
		draft.SecretAccessKey = *in.SecretKey
	default:
		// Testing a saved destination after changing only its bucket should
		// not mean retyping the secret, so the stored one is used when the
		// body carries none.
		stored, err := s.ctrl.Store().GetBackupRemoteByName(r.Context(), row.Name)
		if err == nil && len(stored.SecretKeyEnc) > 0 && s.key != nil {
			if secret, err := s.key.OpenString(stored.SecretKeyEnc); err == nil {
				draft.SecretAccessKey = secret
			}
		}
	}

	out := remoteCheckResponse{Name: draft.Name, Where: draft.Where(), CheckedAt: s.ctrl.Now()}
	if err := s.ctrl.CheckBackupRemote(r.Context(), draft); err != nil {
		out.Error = err.Error()
	} else {
		out.OK = true
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.remote_check", "backup_remote", draft.Name, map[string]any{
		"ok": out.OK, "where": out.Where, "saved": false,
	})
	writeJSON(w, http.StatusOK, out)
}

// storedRemote resolves the row a route addresses, refusing the one thing that
// looks like a bug and is not: a destination the configuration file describes
// cannot be edited here, because the file is what that fleet reads.
func (s *Server) storedRemote(w http.ResponseWriter, r *http.Request) (*store.BackupRemote, bool) {
	name := chiURLParam(r, "name")
	row, err := s.ctrl.Store().GetBackupRemoteByName(r.Context(), name)
	if errors.Is(err, store.ErrNotFound) {
		for _, fromFile := range s.cfg().Backup.Remotes {
			if fromFile.Name == name {
				conflict(w, "the backup remote "+name+" is described in zoomies.yaml or the environment, so it is changed there rather than here")
				return nil, false
			}
		}
		notFound(w, "this controller has no backup remote by that name")
		return nil, false
	}
	if err != nil {
		s.internal(w, r, "reading the backup remote", err)
		return nil, false
	}
	return row, true
}

// remoteNameErrors refuses a name the file already uses or another row holds.
// The database's unique index is the real guard; this is the one that answers
// in words rather than as a conflict from a constraint.
func (s *Server) remoteNameErrors(r *http.Request, name, selfID string) []fieldError {
	for _, fromFile := range s.cfg().Backup.Remotes {
		if fromFile.Name == name {
			return []fieldError{{"name",
				"zoomies.yaml or the environment already describes a destination called " + name + ", and the file has the last word. Choose another name."}}
		}
	}
	existing, err := s.ctrl.Store().GetBackupRemoteByName(r.Context(), name)
	if err == nil && existing.ID != selfID {
		return []fieldError{{"name", "another backup remote is already called " + name}}
	}
	return nil
}

// sealRemoteSecrets writes the two secrets, sealed, when the body carried
// them. Absent leaves what is stored; an explicit empty string clears it.
func (s *Server) sealRemoteSecrets(w http.ResponseWriter, r *http.Request, row *store.BackupRemote, in *remoteInput) bool {
	if in.SecretKey == nil && in.Passphrase == nil {
		return true
	}
	secret, passphrase := row.SecretKeyEnc, row.PassphraseEnc
	seal := func(value string) ([]byte, bool) {
		if strings.TrimSpace(value) == "" {
			return nil, true
		}
		sealed, err := s.key.SealString(value)
		if err != nil {
			s.internal(w, r, "sealing the backup remote's secret", err)
			return nil, false
		}
		return sealed, true
	}
	if in.SecretKey != nil {
		var ok bool
		if secret, ok = seal(*in.SecretKey); !ok {
			return false
		}
	}
	if in.Passphrase != nil {
		var ok bool
		if passphrase, ok = seal(*in.Passphrase); !ok {
			return false
		}
	}
	if err := s.ctrl.Store().SetBackupRemoteSecrets(r.Context(), row.ID, secret, passphrase); err != nil {
		s.internal(w, r, "storing the backup remote's secret", err)
		return false
	}
	row.SecretKeyEnc, row.PassphraseEnc = secret, passphrase
	return true
}

// remoteStatus is how a destination reads back after it is written: the same
// view the Backups page lists, so a form submit and a page load agree.
func (s *Server) remoteStatus(r *http.Request, name string) controller.RemoteBackupStatus {
	for _, status := range s.ctrl.BackupRemotes(r.Context()) {
		if status.Name == name {
			return status
		}
	}
	// It was written a moment ago, so not finding it means the list and the
	// row disagree -- a bug, not a shape the page should have to handle. The
	// answer still says what it is rather than leaving the source blank.
	return controller.RemoteBackupStatus{Name: name, Source: controller.RemoteSourceDatabase}
}

package api

import (
	"errors"
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/controller"
)

// The offsite half of the backups surface.
//
// Everything here is a thin layer over internal/backup's remotes, which is the
// same code the controller's own pass and `zoomies backup --offsite` run: the
// page lists what a bucket holds, sends what it is missing, tests that it can
// be reached, pulls a copy back, and deletes one.
//
// What it deliberately does not have is "restore from the bucket". A restore
// swaps the database this fleet runs on, and the copy it swaps in should be
// one somebody has seen land and verified first -- so fetching puts the archive
// in the backup directory as an ordinary backup, and the existing staged
// restore does the rest. Two steps, both reversible until the last one.

// remoteCopiesResponse is what one destination holds.
type remoteCopiesResponse struct {
	Remote controller.RemoteBackupStatus `json:"remote"`
	Items  []backup.Copy                 `json:"items"`
	// Bytes is what the copies add up to, so the page can say what this
	// bucket is costing without adding a column up itself.
	Bytes int64 `json:"bytes"`
}

// remoteCheckResponse is the answer to "can this bucket be reached".
type remoteCheckResponse struct {
	Name      string    `json:"name"`
	Where     string    `json:"where"`
	OK        bool      `json:"ok"`
	CheckedAt time.Time `json:"checked_at"`
	// Error is the service's own refusal, worded by internal/backup so that a
	// wrong secret, a missing bucket and a drifted clock read differently.
	Error string `json:"error,omitempty"`
}

// shipResponse is what an offsite pass sent.
type shipResponse struct {
	Sent []backup.Copy `json:"sent"`
	// Error is what stopped one destination, when the others still went. The
	// pass is reported as it happened rather than as all or nothing: a typo in
	// the second bucket must not hide that the first one worked.
	Error string `json:"error,omitempty"`
}

// fetchRequest is the body of a fetch: a passphrase for an archive sealed with
// one this configuration no longer carries, which is what a rotation leaves
// behind in a bucket.
type fetchRequest struct {
	Passphrase string `json:"passphrase"`
}

// failRemote renders the refusals a remote makes.
func (s *Server) failRemote(w http.ResponseWriter, r *http.Request, doing string, err error) {
	switch {
	case errors.Is(err, backup.ErrNoRemote):
		notFound(w, "this controller has no backup remote by that name; they are configured under backup.remotes")
	case errors.Is(err, backup.ErrInvalidID):
		badRequestField(w, "id", "that is not a backup id; one looks like zoomies-20260916-120000")
	case errors.Is(err, controller.ErrShippingRunning):
		conflict(w, err.Error())
	default:
		s.internal(w, r, doing, err)
	}
}

// handleListRemoteCopies answers GET /api/v1/backups/remotes/{name}/copies.
//
// It is a live listing rather than something the controller remembers, because
// the question it answers is "is the offsite copy actually there?" and a
// cached yes is exactly the answer that is worth nothing.
func (s *Server) handleListRemoteCopies(w http.ResponseWriter, r *http.Request) {
	name := chiURLParam(r, "name")
	remote, err := s.ctrl.RemoteBackup(r.Context(), name)
	if err != nil {
		s.failRemote(w, r, "reading the backup remote", err)
		return
	}
	copies, err := remote.List(r.Context())
	if err != nil {
		// The bucket refusing is not this API failing: the message is the
		// service's own and the operator can act on it.
		unprocessable(w, "this backup remote could not be read", []fieldError{{"name", err.Error()}})
		return
	}
	out := remoteCopiesResponse{Items: copies}
	for _, c := range copies {
		out.Bytes += c.Bytes
	}
	s.ctrl.NoteRemoteListing(name, len(copies), out.Bytes)
	for _, status := range s.ctrl.BackupRemotes(r.Context()) {
		if status.Name == name {
			out.Remote = status
			break
		}
	}
	writeJSON(w, http.StatusOK, out)
}

// handleCheckRemote answers POST /api/v1/backups/remotes/{name}/check: one
// cheap listing, which is the whole of what has to work for a backup to reach
// the bucket.
//
// A POST because it goes out to the network on somebody else's account, and an
// answer of "no" is a 200 with ok:false rather than an error status: the check
// ran, and what it found is the result.
func (s *Server) handleCheckRemote(w http.ResponseWriter, r *http.Request) {
	name := chiURLParam(r, "name")
	remote, err := s.ctrl.RemoteBackup(r.Context(), name)
	if err != nil {
		s.failRemote(w, r, "reading the backup remote", err)
		return
	}
	out := remoteCheckResponse{Name: remote.Name(), Where: remote.Where(), CheckedAt: s.ctrl.Now()}
	if err := remote.Check(r.Context()); err != nil {
		out.Error = err.Error()
	} else {
		out.OK = true
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.remote_check", "backup_remote", name, map[string]any{
		"ok": out.OK, "where": out.Where,
	})
	writeJSON(w, http.StatusOK, out)
}

// handleShipBackups answers POST /api/v1/backups/offsite: send every remote
// what it is missing, now.
//
// It is the same pass the controller runs on its own, exposed because an
// operator who has just fixed a credential wants to know it worked without
// waiting an hour to find out.
func (s *Server) handleShipBackups(w http.ResponseWriter, r *http.Request) {
	sent, err := s.ctrl.ShipBackups(r.Context())
	if errors.Is(err, controller.ErrShippingRunning) {
		conflict(w, err.Error())
		return
	}
	out := shipResponse{Sent: sent}
	if out.Sent == nil {
		out.Sent = []backup.Copy{}
	}
	if err != nil {
		out.Error = err.Error()
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.offsite", "backup", "", map[string]any{
		"sent": len(out.Sent), "error": out.Error,
	})
	writeJSON(w, http.StatusOK, out)
}

// handlePruneBackups answers POST /api/v1/backups/prune: apply retention now,
// here and in every bucket.
//
// Retention is otherwise part of taking a backup, which leaves an operator who
// has just lowered backup.keep with nothing happening until the next one. The
// answer is what was deleted rather than a bare 204: this route removes copies
// of the whole fleet, and an operator is owed the list.
func (s *Server) handlePruneBackups(w http.ResponseWriter, r *http.Request) {
	report, err := s.ctrl.PruneBackups(r.Context())
	switch {
	case errors.Is(err, controller.ErrBackupRunning), errors.Is(err, controller.ErrShippingRunning):
		conflict(w, err.Error())
		return
	case err != nil:
		s.internal(w, r, "applying backup retention", err)
		return
	}
	removed := len(report.Removed)
	for _, remote := range report.Remotes {
		removed += len(remote.Removed)
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.prune", "backup", "", map[string]any{
		"keep": report.Keep, "removed": removed, "remotes": len(report.Remotes),
	})
	writeJSON(w, http.StatusOK, report)
}

// handleFetchRemoteCopy answers
// POST /api/v1/backups/remotes/{name}/copies/{id}/fetch: the archive comes
// down, is unpacked and verified exactly as an upload would be, and is then an
// ordinary backup in the directory.
func (s *Server) handleFetchRemoteCopy(w http.ResponseWriter, r *http.Request) {
	name, id := chiURLParam(r, "name"), chiURLParam(r, "id")
	remote, err := s.ctrl.RemoteBackup(r.Context(), name)
	if err != nil {
		s.failRemote(w, r, "reading the backup remote", err)
		return
	}
	var body fetchRequest
	if !decodeOptional(w, r, &body) {
		return
	}
	// A fetch writes a whole database over a link nobody promised anything
	// about; the request is not held to the API's ordinary write deadline.
	_ = http.NewResponseController(w).SetWriteDeadline(time.Time{})

	identity := Identity(r.Context())
	entry, err := remote.Fetch(r.Context(), s.ctrl.BackupDir(), id, backup.FetchOptions{
		Passphrase: body.Passphrase, TakenBy: identity.Name,
		MaxBytes: maxBackupUploadBytes, Now: s.ctrl.Now,
	})
	switch {
	case errors.Is(err, backup.ErrInvalidID):
		badRequestField(w, "id", "that is not a backup id; one looks like zoomies-20260916-120000")
		return
	case errors.Is(err, backup.ErrWrongPassphrase):
		unprocessable(w, "the archive did not open", []fieldError{{"passphrase", backup.ErrWrongPassphrase.Error()}})
		return
	case err != nil:
		unprocessable(w, "this copy could not be brought back", []fieldError{{"id", err.Error()}})
		return
	}
	s.auth.Auditor().Act(r.Context(), identity, "backup.remote_fetch", "backup", entry.ID, map[string]any{
		"remote": name, "where": remote.Where(), "bytes": entry.Bytes, "taken_at": entry.TakenAt,
	})
	writeJSON(w, http.StatusCreated, s.backupView(*entry, locationBackups))
}

// handleDeleteRemoteCopy answers
// DELETE /api/v1/backups/remotes/{name}/copies/{id}.
//
// Deleting the offsite copy is audited like deleting the local one, and for a
// stronger reason: it is the copy that exists because the local ones might
// not.
func (s *Server) handleDeleteRemoteCopy(w http.ResponseWriter, r *http.Request) {
	name, id := chiURLParam(r, "name"), chiURLParam(r, "id")
	remote, err := s.ctrl.RemoteBackup(r.Context(), name)
	if err != nil {
		s.failRemote(w, r, "reading the backup remote", err)
		return
	}
	if err := remote.Delete(r.Context(), id); err != nil {
		if errors.Is(err, backup.ErrInvalidID) {
			badRequestField(w, "id", "that is not a backup id; one looks like zoomies-20260916-120000")
			return
		}
		unprocessable(w, "this copy could not be removed", []fieldError{{"id", err.Error()}})
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.remote_delete", "backup", id, map[string]any{
		"remote": name, "where": remote.Where(),
	})
	noContent(w)
}

package api

import (
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// The backups surface.
//
// Everything here is a thin layer over internal/backup, which is the same
// code `zoomies backup` and `zoomies restore` run: the settings page takes,
// lists, verifies, downloads, uploads and deletes the copies in the backup
// directory, and stages a restore for the next start. It never restores under
// the running controller, because nothing can -- see backup.Stage.

// maxBackupUploadBytes bounds an uploaded archive. It is far above any
// database this controller has met and far below "fill the disk": an upload
// is unpacked beside the live database, on the volume the fleet runs from.
const maxBackupUploadBytes = 8 << 30

// backupView is one backup as the page renders it.
//
// The manifest's facts are lifted out flat rather than nested, because the
// table has a column for each and a client should not have to know the
// manifest's shape to draw one. The manifest itself is not carried: it holds
// the blanked configuration, which is a page of JSON per row.
type backupView struct {
	ID       string    `json:"id"`
	TakenAt  time.Time `json:"taken_at"`
	Source   string    `json:"source"`
	TakenBy  string    `json:"taken_by,omitempty"`
	Location string    `json:"location"`
	// Bytes is the database; TotalBytes is the directory, which differs when
	// the key is in it.
	Bytes      int64 `json:"bytes"`
	TotalBytes int64 `json:"total_bytes"`
	// Version is the build that wrote it, and SchemaLatest the newest
	// migration the copy had taken.
	Version          string `json:"version,omitempty"`
	SchemaLatest     string `json:"schema_latest,omitempty"`
	SchemaMigrations int    `json:"schema_migrations"`
	Integrity        string `json:"integrity,omitempty"`
	// Secrets is how many sealed credentials the key is needed for.
	Secrets int `json:"secrets"`
	// KeyFingerprint is the key that sealed it; KeyMatches says whether this
	// host holds that key, and is null when the backup does not say.
	KeyFingerprint string `json:"key_fingerprint,omitempty"`
	KeyMatches     *bool  `json:"key_matches"`
	KeyIncluded    bool   `json:"key_included"`
	// Restorable says every check a restore would make on this backup
	// passes from what the manifest says; RestoreProblem is the one that
	// does not. A backup with no manifest is restorable with a caveat.
	Restorable     bool   `json:"restorable"`
	RestoreProblem string `json:"restore_problem,omitempty"`
	// Problem is something wrong with the backup itself.
	Problem string `json:"problem,omitempty"`
}

// The two places a backup can be.
const (
	locationBackups      = "backups"
	locationPreMigration = "pre-migration"
)

// backupsResponse is the whole tab in one document.
type backupsResponse struct {
	Items     []backupView `json:"items"`
	Directory string       `json:"directory"`
	// DatabaseBytes is the live database's size, which is roughly what a
	// backup costs; DiskFreeBytes is the room beside it, when the platform
	// can say.
	DatabaseBytes int64  `json:"database_bytes"`
	DiskFreeBytes *int64 `json:"disk_free_bytes"`
	// KeyFingerprint is this host's key, for the row that says whether a
	// backup was sealed with it.
	KeyFingerprint string         `json:"key_fingerprint,omitempty"`
	Schedule       backupSchedule `json:"schedule"`
	// Remotes is every destination the copies are sent to, and what became
	// of each. Empty is the default and says so on the page: a fleet whose
	// backups never leave the host should be told that, not left to assume
	// otherwise from a tab full of tidy rows.
	Remotes []controller.RemoteBackupStatus `json:"remotes"`
	// Running says a backup is being taken right now.
	Running bool `json:"running"`
	// StagedRestore is the restore waiting for a restart, if any;
	// LastRestore is what became of the last one applied.
	StagedRestore *backup.Staged  `json:"staged_restore"`
	LastRestore   *backup.Outcome `json:"last_restore"`
	// Restarting says this process has been asked to stop and is on its way
	// down, so a page that receives this should start waiting for the next.
	Restarting bool `json:"restarting"`
}

// backupSchedule is the controller's own schedule, as the page shows it.
type backupSchedule struct {
	Enabled         bool       `json:"enabled"`
	Interval        string     `json:"interval"`
	Keep            int        `json:"keep"`
	NextDueAt       *time.Time `json:"next_due_at"`
	LastScheduledAt *time.Time `json:"last_scheduled_at"`
	LastScheduledID string     `json:"last_scheduled_id,omitempty"`
	LastError       string     `json:"last_error,omitempty"`
}

// restoreRequest is what staging a restore asks for.
type restoreRequest struct {
	RevokeAPITokens  bool `json:"revoke_api_tokens"`
	ResetAgentTokens bool `json:"reset_agent_tokens"`
}

// downloadRequest is the body of the encrypted download.
type downloadRequest struct {
	Passphrase string `json:"passphrase"`
}

// restartResponse answers the request that stops the controller.
type restartResponse struct {
	Restarting bool   `json:"restarting"`
	Message    string `json:"message"`
}

// minPassphrase is the shortest passphrase the encrypted download accepts.
// Eight characters of argon2id is not a strong secret, but a limit that
// refuses "1234" stops the one case that is no protection at all.
//
// It is the validator's number rather than a second one, because the same
// archive is sealed with the same cipher whether a browser asked for it or a
// backup remote is being written to, and two limits that disagree would make
// the page and the startup warning say different things about one passphrase.
const minPassphrase = config.MinBackupPassphrase

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

func (s *Server) backupView(e backup.Entry, location string) backupView {
	v := backupView{
		ID: e.ID, TakenAt: e.TakenAt, Source: e.Source, Location: location,
		Bytes: e.Bytes, TotalBytes: e.TotalBytes, KeyIncluded: e.KeyIncluded, Problem: e.Problem,
	}
	if m := e.Manifest; m != nil {
		v.TakenBy = m.TakenBy
		v.Version = m.Zoomies.Version
		v.SchemaLatest = m.LastMigration()
		v.SchemaMigrations = len(m.Database.Migrations)
		v.Integrity = m.Database.Integrity
		v.Secrets = len(m.Secrets)
		v.KeyFingerprint = m.Key.Fingerprint
		if m.Key.Fingerprint != "" {
			matches := s.key != nil && s.key.Fingerprint() == m.Key.Fingerprint
			v.KeyMatches = &matches
		}
	}
	v.Restorable, v.RestoreProblem = s.restorable(e)
	return v
}

// restorable answers from the manifest what backup.Check would answer from
// the file, so the list can grey out the rows a restore would refuse without
// opening every database in the directory.
func (s *Server) restorable(e backup.Entry) (bool, string) {
	if e.Problem != "" {
		return false, e.Problem
	}
	m := e.Manifest
	if m == nil {
		return true, "there is no manifest, so the encryption key and the release that wrote it cannot be checked before restoring; the database itself will be"
	}
	known := store.KnownMigrations()
	for _, name := range m.Database.Migrations {
		if !slices.Contains(known, name) {
			return false, fmt.Sprintf("written by a newer release: this build does not have the migration %s", name)
		}
	}
	if m.Key.Fingerprint != "" {
		if s.key == nil {
			return false, "this backup needs the encryption key " + m.Key.Fingerprint + ", and this controller has no key"
		}
		if s.key.Fingerprint() != m.Key.Fingerprint {
			return false, fmt.Sprintf("sealed with the encryption key %s, and this controller's key is %s; restoring would give a fleet that cannot authenticate to GitHub", m.Key.Fingerprint, s.key.Fingerprint())
		}
	}
	return true, ""
}

// findBackup resolves an id in the backup directory, then among the store's
// pre-migration copies. The backup directory wins a collision: it is where
// the operator's own copies are.
func (s *Server) findBackup(id string) (*backup.Entry, string, error) {
	if !backup.ValidID(id) {
		return nil, "", backup.ErrInvalidID
	}
	e, err := backup.Get(s.ctrl.BackupDir(), id)
	if err == nil {
		return e, locationBackups, nil
	}
	if !errors.Is(err, backup.ErrNotFound) {
		return nil, "", err
	}
	e, err = backup.Get(backup.PreMigrationDir(s.ctrl.DatabasePath()), id)
	if err != nil {
		return nil, "", err
	}
	return e, locationPreMigration, nil
}

// failBackup renders the package's own refusals: an id that is not one is a
// 400 rather than a 404, because it was never going to name anything.
func (s *Server) failBackup(w http.ResponseWriter, r *http.Request, doing string, err error) {
	switch {
	case errors.Is(err, backup.ErrInvalidID):
		badRequestField(w, "id", "that is not a backup id; one looks like zoomies-20260916-120000")
	case errors.Is(err, backup.ErrNotFound):
		notFound(w, "there is no backup with that id; it may have been removed since the page loaded")
	case errors.Is(err, controller.ErrBackupRunning):
		conflict(w, err.Error())
	default:
		s.internal(w, r, doing, err)
	}
}

// ---------------------------------------------------------------------------
// Listing and taking
// ---------------------------------------------------------------------------

// handleListBackups answers GET /api/v1/backups.
func (s *Server) handleListBackups(w http.ResponseWriter, r *http.Request) {
	dir := s.ctrl.BackupDir()
	dbPath := s.ctrl.DatabasePath()
	items := []backupView{}
	own, err := backup.List(dir)
	if err != nil {
		s.internal(w, r, "listing the backups", err)
		return
	}
	for _, e := range own {
		items = append(items, s.backupView(e, locationBackups))
	}
	pre, err := backup.List(backup.PreMigrationDir(dbPath))
	if err != nil {
		s.internal(w, r, "listing the pre-migration copies", err)
		return
	}
	for _, e := range pre {
		items = append(items, s.backupView(e, locationPreMigration))
	}
	slices.SortStableFunc(items, func(a, b backupView) int { return b.TakenAt.Compare(a.TakenAt) })

	out := backupsResponse{Items: items, Directory: dir, StagedRestore: nil, LastRestore: nil}
	if info, err := os.Stat(dbPath); err == nil {
		out.DatabaseBytes = info.Size()
	}
	// The directory may not exist until the first backup; its parent is on
	// the same filesystem, and is where the space would come from.
	probe := dir
	if _, err := os.Stat(probe); err != nil {
		probe = filepath.Dir(dir)
	}
	if free, ok := backup.DiskFree(probe); ok {
		out.DiskFreeBytes = &free
	}
	if s.key != nil {
		out.KeyFingerprint = s.key.Fingerprint()
	}
	status := s.ctrl.BackupStatus()
	out.Running = status.Running
	out.Remotes = s.ctrl.BackupRemotes(r.Context())
	out.Schedule = backupSchedule{
		Enabled:         status.Interval > 0,
		Interval:        config.Text(config.Setting{Kind: config.KindDuration}, status.Interval),
		Keep:            status.Keep,
		LastScheduledID: status.LastScheduledID,
		LastError:       status.LastError,
	}
	if !status.NextDueAt.IsZero() {
		at := status.NextDueAt
		out.Schedule.NextDueAt = &at
	}
	if !status.LastScheduledAt.IsZero() {
		at := status.LastScheduledAt
		out.Schedule.LastScheduledAt = &at
	}
	if staged, err := backup.LoadStaged(dbPath); err == nil {
		out.StagedRestore = staged
	} else {
		s.logger(r).Warn("could not read the staged restore", "error", err)
	}
	if last, err := backup.LastOutcome(dbPath); err == nil {
		out.LastRestore = last
	} else {
		s.logger(r).Warn("could not read the last restore's outcome", "error", err)
	}
	out.Restarting, _ = s.ctrl.Restarting()
	writeJSON(w, http.StatusOK, out)
}

// handleGetBackup answers GET /api/v1/backups/{id}.
func (s *Server) handleGetBackup(w http.ResponseWriter, r *http.Request) {
	e, location, err := s.findBackup(chiURLParam(r, "id"))
	if err != nil {
		s.failBackup(w, r, "reading the backup", err)
		return
	}
	writeJSON(w, http.StatusOK, s.backupView(*e, location))
}

// handleTakeBackup answers POST /api/v1/backups: a copy, now, on behalf of
// whoever pressed the button.
func (s *Server) handleTakeBackup(w http.ResponseWriter, r *http.Request) {
	id := Identity(r.Context())
	e, err := s.ctrl.TakeBackup(r.Context(), backup.SourceManual, id.Name)
	if err != nil {
		s.failBackup(w, r, "taking a backup", err)
		return
	}
	s.ctrl.NoteManualBackup()
	s.auth.Auditor().Act(r.Context(), id, "backup.take", "backup", e.ID, map[string]any{
		"bytes": e.Bytes, "dir": e.Dir,
	})
	writeJSON(w, http.StatusCreated, s.backupView(*e, locationBackups))
}

// handleDeleteBackup answers DELETE /api/v1/backups/{id}.
func (s *Server) handleDeleteBackup(w http.ResponseWriter, r *http.Request) {
	e, location, err := s.findBackup(chiURLParam(r, "id"))
	if err != nil {
		s.failBackup(w, r, "reading the backup", err)
		return
	}
	// A backup that is about to be restored must not be deleted from under
	// the restart that would apply it.
	if staged, _ := backup.LoadStaged(s.ctrl.DatabasePath()); staged != nil && staged.BackupID == e.ID {
		conflict(w, "this backup is staged to be restored at the next restart; cancel the restore first")
		return
	}
	if err := os.RemoveAll(e.Dir); err != nil {
		s.internal(w, r, "removing the backup", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.delete", "backup", e.ID, map[string]any{
		"taken_at": e.TakenAt, "source": e.Source, "location": location, "bytes": e.Bytes,
	})
	noContent(w)
}

// handleVerifyBackup answers POST /api/v1/backups/{id}/verify.
//
// A POST because it reads the whole file: on a large database it is seconds
// of work, and a GET that costs seconds is one a page will make by accident.
func (s *Server) handleVerifyBackup(w http.ResponseWriter, r *http.Request) {
	e, _, err := s.findBackup(chiURLParam(r, "id"))
	if err != nil {
		s.failBackup(w, r, "reading the backup", err)
		return
	}
	v, err := backup.Verify(r.Context(), filepath.Dir(e.Dir), e.ID)
	if err != nil {
		s.failBackup(w, r, "verifying the backup", err)
		return
	}
	writeJSON(w, http.StatusOK, v)
}

// ---------------------------------------------------------------------------
// Download and upload
// ---------------------------------------------------------------------------

// handleDownloadBackup answers GET /api/v1/backups/{id}/download: the backup
// as a gzipped tar, and POST with a passphrase: the same, encrypted.
//
// The download is audited, which few reads are, because it is the whole
// database leaving the machine.
func (s *Server) handleDownloadBackup(w http.ResponseWriter, r *http.Request) {
	e, _, err := s.findBackup(chiURLParam(r, "id"))
	if err != nil {
		s.failBackup(w, r, "reading the backup", err)
		return
	}
	passphrase := ""
	if r.Method == http.MethodPost {
		var body downloadRequest
		if !decode(w, r, &body) {
			return
		}
		if len(body.Passphrase) < minPassphrase {
			unprocessable(w, "the passphrase is too short", []fieldError{{"passphrase",
				fmt.Sprintf("use at least %d characters; the archive is only as private as this", minPassphrase)}})
			return
		}
		passphrase = body.Passphrase
	}

	name := backup.ArchiveName(e.ID, passphrase != "")
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", `attachment; filename="`+name+`"`)
	w.Header().Set("Cache-Control", "no-store")
	// A large backup over a slow link takes as long as it takes.
	_ = http.NewResponseController(w).SetWriteDeadline(time.Time{})
	w.WriteHeader(http.StatusOK)

	var out io.Writer = w
	if passphrase != "" {
		enc, err := backup.NewEncryptor(w, passphrase)
		if err != nil {
			s.logger(r).Warn("could not start the encrypted download", "backup", e.ID, "error", err)
			return
		}
		defer func() { _ = enc.Close() }()
		out = enc
	}
	if err := backup.WriteArchive(out, e); err != nil {
		// The headers are gone; the client gets a short file, and the log
		// gets the reason.
		s.logger(r).Warn("a backup download did not complete", "backup", e.ID, "error", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.download", "backup", e.ID, map[string]any{
		"encrypted": passphrase != "", "bytes": e.TotalBytes, "key_included": e.KeyIncluded,
	})
}

// handleUploadBackup answers POST /api/v1/backups/upload: a multipart form
// with the archive in `file` and, for an encrypted one, its `passphrase`.
//
// Multipart rather than a raw body, because the passphrase has to travel with
// the file and a header or a query string is where a passphrase ends up in a
// proxy log. The file part is spooled to disk before anything is decided, so
// the passphrase may come before or after it.
func (s *Server) handleUploadBackup(w http.ResponseWriter, r *http.Request) {
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "multipart/form-data" {
		badRequest(w, "send the backup as multipart/form-data: a `file` part holding the archive, and a `passphrase` part when it is encrypted")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxBackupUploadBytes)
	_ = http.NewResponseController(w).SetReadDeadline(time.Time{})
	mr, err := r.MultipartReader()
	if err != nil {
		badRequest(w, "the request is not a multipart form: "+err.Error())
		return
	}

	root := s.ctrl.BackupDir()
	if err := os.MkdirAll(root, 0o700); err != nil {
		s.internal(w, r, "creating the backup directory", err)
		return
	}
	spool, err := os.CreateTemp(root, ".incoming-*")
	if err != nil {
		s.internal(w, r, "spooling the upload", err)
		return
	}
	defer os.Remove(spool.Name())
	defer spool.Close()

	var passphrase, filename string
	var received bool
	for {
		part, err := mr.NextPart()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				payloadTooLarge(w, fmt.Sprintf("the upload is larger than the %d byte limit", maxErr.Limit))
				return
			}
			badRequest(w, "reading the upload: "+err.Error())
			return
		}
		switch part.FormName() {
		case "passphrase":
			raw, err := io.ReadAll(io.LimitReader(part, 4096))
			if err != nil {
				badRequest(w, "reading the passphrase: "+err.Error())
				return
			}
			passphrase = string(raw)
		case "file":
			if received {
				badRequest(w, "the form has more than one file part; send one archive per request")
				return
			}
			received = true
			filename = part.FileName()
			if _, err := io.Copy(spool, part); err != nil {
				var maxErr *http.MaxBytesError
				if errors.As(err, &maxErr) {
					payloadTooLarge(w, fmt.Sprintf("the upload is larger than the %d byte limit", maxErr.Limit))
					return
				}
				s.internal(w, r, "spooling the upload", err)
				return
			}
		default:
			// Ignored rather than refused: a form with an extra field is a
			// client that will be fixed, not an attack.
		}
		part.Close()
	}
	if !received {
		badRequest(w, "the form has no `file` part")
		return
	}
	if _, err := spool.Seek(0, io.SeekStart); err != nil {
		s.internal(w, r, "reading the spooled upload", err)
		return
	}

	var src io.Reader = spool
	encrypted, peek := backup.IsEncrypted(spool)
	src = peek
	switch {
	case encrypted && passphrase == "":
		unprocessable(w, "this archive is encrypted", []fieldError{{"passphrase", "it was downloaded with a passphrase; send the same one"}})
		return
	case encrypted:
		src, err = backup.NewDecryptor(peek, passphrase)
		if err != nil {
			s.internal(w, r, "opening the encrypted upload", err)
			return
		}
	case passphrase != "":
		// Not an error: an operator who typed a passphrase for a plain
		// archive has lost nothing. The upload proceeds without it.
	}

	entry, err := backup.Unpack(r.Context(), root, src, backup.UnpackOptions{
		Source: backup.SourceUploaded, TakenBy: Identity(r.Context()).Name, MaxBytes: maxBackupUploadBytes, Now: s.ctrl.Now,
	})
	if err != nil {
		if errors.Is(err, backup.ErrWrongPassphrase) {
			unprocessable(w, "the archive did not open", []fieldError{{"passphrase", backup.ErrWrongPassphrase.Error()}})
			return
		}
		unprocessable(w, "that file is not a Zoomies backup this controller can use", []fieldError{{"file", strings.TrimPrefix(err.Error(), "backup: ")}})
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.upload", "backup", entry.ID, map[string]any{
		"filename": filename, "encrypted": encrypted, "bytes": entry.Bytes, "taken_at": entry.TakenAt,
	})
	writeJSON(w, http.StatusCreated, s.backupView(*entry, locationBackups))
}

// ---------------------------------------------------------------------------
// Restoring
// ---------------------------------------------------------------------------

// handleStageRestore answers POST /api/v1/backups/{id}/restore.
//
// Nothing is restored here. The controller cannot swap the database it is
// running on, so the request is checked -- every check a restore makes -- and
// written down for the next controller to apply before it opens anything. The
// response is the staged restore; the restart that applies it is a separate,
// deliberate act.
func (s *Server) handleStageRestore(w http.ResponseWriter, r *http.Request) {
	e, _, err := s.findBackup(chiURLParam(r, "id"))
	if err != nil {
		s.failBackup(w, r, "reading the backup", err)
		return
	}
	var body restoreRequest
	if !decodeOptional(w, r, &body) {
		return
	}
	if existing, _ := backup.LoadStaged(s.ctrl.DatabasePath()); existing != nil && existing.BackupID != e.ID {
		conflict(w, fmt.Sprintf("%s is already staged to be restored; cancel that first", existing.BackupID))
		return
	}
	id := Identity(r.Context())
	staged, err := backup.Stage(r.Context(), s.cfg(), e, backup.Staged{
		RequestedBy: id.Name, RequestedAt: s.ctrl.Now(),
		RevokeAPITokens: body.RevokeAPITokens, ResetAgentTokens: body.ResetAgentTokens,
	})
	if err != nil {
		// Every refusal here is one the operator can act on: the wrong key,
		// a newer release, a copy that is not sound.
		unprocessable(w, "this backup cannot be restored", []fieldError{{"id", err.Error()}})
		return
	}
	s.auth.Auditor().Act(r.Context(), id, "backup.restore_staged", "backup", e.ID, map[string]any{
		"taken_at": staged.TakenAt, "revoke_api_tokens": staged.RevokeAPITokens, "reset_agent_tokens": staged.ResetAgentTokens,
	})
	writeJSON(w, http.StatusAccepted, staged)
}

// handleCancelRestore answers DELETE /api/v1/backups/restore.
func (s *Server) handleCancelRestore(w http.ResponseWriter, r *http.Request) {
	dbPath := s.ctrl.DatabasePath()
	staged, err := backup.LoadStaged(dbPath)
	if err != nil {
		s.internal(w, r, "reading the staged restore", err)
		return
	}
	if err := backup.CancelStaged(dbPath); err != nil {
		s.internal(w, r, "cancelling the staged restore", err)
		return
	}
	if staged != nil {
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.restore_cancelled", "backup", staged.BackupID, nil)
	}
	noContent(w)
}

// handleDismissRestoreOutcome answers DELETE /api/v1/backups/restore/outcome:
// the operator has read what became of the last restore.
func (s *Server) handleDismissRestoreOutcome(w http.ResponseWriter, r *http.Request) {
	if err := backup.ClearOutcome(s.ctrl.DatabasePath()); err != nil {
		s.internal(w, r, "dismissing the last restore's outcome", err)
		return
	}
	noContent(w)
}

// handleApplyRestore answers POST /api/v1/backups/restore/apply: stop this
// controller so that its service manager starts the next, which applies the
// staged restore before it opens the database.
//
// It refuses when nothing is staged, because a restart with nothing to apply
// is an outage somebody asked for by mistake.
func (s *Server) handleApplyRestore(w http.ResponseWriter, r *http.Request) {
	staged, err := backup.LoadStaged(s.ctrl.DatabasePath())
	if err != nil {
		s.internal(w, r, "reading the staged restore", err)
		return
	}
	if staged == nil {
		conflict(w, "no restore is staged; choose a backup and stage its restore first")
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "backup.restore_applied", "backup", staged.BackupID, map[string]any{
		"requested_by": staged.RequestedBy, "taken_at": staged.TakenAt,
	})
	s.ctrl.RequestRestart("restoring " + staged.BackupID + ", asked for by " + Identity(r.Context()).Name)
	writeJSON(w, http.StatusAccepted, restartResponse{
		Restarting: true,
		Message: "The controller is stopping. If its service manager starts it again, the restore is applied before the database is opened " +
			"and the fleet comes back fenced; if nothing starts it, start it by hand and the same happens.",
	})
}

package api

import (
	"cmp"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"runtime"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// bundleVersion is the shape's own number, carried in the document so that a
// reader given a bundle out of context knows what it is looking at. It moves
// when a section is removed or renamed, not when one is added: a reader that
// ignores fields it does not know keeps working across an addition.
const bundleVersion = 1

// The per-section caps. They are counts rather than bytes because a count is
// what a reader can reason about -- "the newest 500 runners" is a sentence --
// and because a section truncated at a row boundary is still valid JSON. The
// byte cap below is the backstop for the fleet that makes 500 rows enormous.
const (
	bundleMaxRunners       = 500
	bundleMaxJobs          = 300
	bundleMaxExplanations  = 50
	bundleMaxScalingEvents = 200
	bundleMaxMachines      = 200
	bundleMaxLogPointers   = 50

	// bundleMaxBytes is what an operator can paste into a support case
	// without a file-sharing service. A bundle over it sheds sections rather
	// than being refused: a short bundle answers some questions, and a 500
	// answers none.
	bundleMaxBytes = 8 << 20
)

// supportBundle is one document describing this instance, for a bug report.
//
// It is assembled from the same renderings the API already serves rather than
// from the store directly, which is the property that makes it trustworthy:
// every section is something the operator could have fetched themselves, so a
// field that is secret-free on its own route is secret-free here, and a view
// that gains a field gains it in both places. The configuration in particular
// comes from settingsConfig, which is built key by key -- a secret added to
// config.Config tomorrow cannot appear in a bundle by default.
//
// The one exception to "what the operator could have fetched" is a pool's
// environment: its values are the operator's to read on the pool's own route,
// but the bundle is a document made to be handed on, so it keeps the keys and
// drops the values.
//
// What it never carries is workflow log bodies. There is no redaction pass for
// them and there cannot be a reliable one -- a log holds whatever a workflow
// printed -- so the bundle carries runner ids and the download route instead,
// and an operator decides log by log what to attach.
type supportBundle struct {
	BundleVersion int                      `json:"bundle_version"`
	GeneratedAt   time.Time                `json:"generated_at"`
	Instance      bundleInstance           `json:"instance"`
	Config        map[string]any           `json:"config,omitempty"`
	Findings      []config.Finding         `json:"findings,omitempty"`
	Problems      *controller.ProblemsView `json:"problems,omitempty"`
	Stats         *controller.Stats        `json:"stats,omitempty"`
	Installations []installationResponse   `json:"installations,omitempty"`
	Pools         []poolResponse           `json:"pools,omitempty"`
	Hosts         []hostResponse           `json:"hosts,omitempty"`
	// Providers and Machines are the evidence a pending cleanup or an orphan
	// review needs, and they cost nothing: both sections are the renderings
	// the API already serves, so a machine stuck mid-create arrives in a bug
	// report with its operation handle and its provider's own words.
	Providers []providerResponse `json:"providers,omitempty"`
	Machines  []machineResponse  `json:"machines,omitempty"`
	Runners   []runnerResponse   `json:"runners,omitempty"`
	// Jobs is the work in flight rather than the history. A bundle is taken
	// because something is stuck, and finished jobs would be most of the bytes
	// while answering none of it; the history is a query away on the same
	// instance.
	Jobs          []jobResponse                `json:"jobs,omitempty"`
	Explanations  []*controller.JobExplanation `json:"explanations,omitempty"`
	ScalingEvents []*store.ScalingEvent        `json:"scaling_events,omitempty"`
	Logs          *bundleLogs                  `json:"logs,omitempty"`

	// Errors is why a section is missing. A bundle assembles section by
	// section and a failing one costs its own contents: a support case built
	// on nine sections and a named failure is worth more than a 500, and the
	// failure itself is often the bug being reported.
	Errors []bundleError `json:"errors"`
	// Truncated names each section that was capped, and why.
	Truncated []bundleTruncation `json:"truncated,omitempty"`
}

// bundleInstance is what this process is and how it is doing, which is the
// half of a bug report that is never in the fleet's own rows.
type bundleInstance struct {
	Version          string     `json:"version"`
	Commit           string     `json:"commit,omitempty"`
	BuildDate        string     `json:"build_date,omitempty"`
	Go               string     `json:"go"`
	OS               string     `json:"os"`
	Arch             string     `json:"arch"`
	CPUs             int        `json:"cpus"`
	Goroutines       int        `json:"goroutines"`
	HeapInUseBytes   uint64     `json:"heap_in_use_bytes"`
	ConfigPath       string     `json:"config_path,omitempty"`
	DatabasePath     string     `json:"database_path,omitempty"`
	SchemaApplied    int        `json:"schema_applied,omitempty"`
	SchemaLatest     string     `json:"schema_latest,omitempty"`
	EventSubscribers int        `json:"event_subscribers"`
	PollingOnly      bool       `json:"polling_only"`
	PollerEnabled    bool       `json:"poller_enabled"`
	PollerLastPollAt *time.Time `json:"poller_last_poll_at,omitempty"`
	// LoopPanics is the one fact here that is always a bug in Zoomies. A loop
	// that panicked was restarted and the fleet carried on, so nothing else in
	// a bundle would show it.
	LoopPanics []bundleLoopPanic `json:"loop_panics,omitempty"`
}

// bundleLoopPanic is one background loop's crash record.
type bundleLoopPanic struct {
	Loop  string    `json:"loop"`
	Count int       `json:"count"`
	Last  string    `json:"last"`
	At    time.Time `json:"at"`
}

// bundleLogs points at logs rather than carrying them.
type bundleLogs struct {
	Note    string             `json:"note"`
	Runners []bundleLogPointer `json:"runners"`
}

// bundleLogPointer is one runner whose log a support case is likely to want,
// with the route that fetches it.
type bundleLogPointer struct {
	RunnerID string            `json:"runner_id"`
	Name     string            `json:"name,omitempty"`
	State    store.RunnerState `json:"state"`
	PoolID   string            `json:"pool_id,omitempty"`
	Download string            `json:"download"`
}

type bundleError struct {
	Section string `json:"section"`
	Error   string `json:"error"`
}

type bundleTruncation struct {
	Section string `json:"section"`
	Kept    int    `json:"kept"`
	Reason  string `json:"reason"`
}

// handleDiagnosticsBundle answers GET /api/v1/diagnostics/bundle.
func (s *Server) handleDiagnosticsBundle(w http.ResponseWriter, r *http.Request) {
	b := s.supportBundle(r.Context())
	raw, err := marshalBundle(&b)
	if err != nil {
		s.internal(w, r, "rendering the support bundle", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "diagnostics.bundle", "instance", "", map[string]any{
		"bytes": len(raw), "sections_failed": len(b.Errors),
	})
	// no-store because a bundle is a snapshot of the whole instance and has no
	// business in a shared cache, and because it is stale the moment it is
	// taken.
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(raw)
}

// supportBundle assembles the document.
//
// Every section is gathered through gather, so that one failure is recorded
// and the rest of the bundle still arrives. That is the same rule the problems
// aggregator follows and for the same reason: the moment an operator most
// needs this is the moment a query is most likely to fail.
func (s *Server) supportBundle(ctx context.Context) supportBundle {
	b := supportBundle{
		BundleVersion: bundleVersion,
		GeneratedAt:   s.ctrl.Now(),
		Errors:        []bundleError{},
	}
	gather := func(section string, fn func() error) {
		if err := fn(); err != nil {
			b.Errors = append(b.Errors, bundleError{Section: section, Error: err.Error()})
		}
	}

	b.Instance = s.bundleInstance(ctx, gather)
	if !callerRoleCtx(ctx).AtLeast(store.RolePlatform) {
		// "Send me a bundle" is the platform's first support question, so the
		// fleet has to be able to answer it -- the route stays theirs rather
		// than moving behind the platform's. What they send is the fleet's
		// half: their pools, hosts, runners and jobs, and of the instance
		// only what identifies the build it all ran on. The machine the
		// process is on is not theirs to describe.
		b.Instance = bundleInstance{
			Version:   b.Instance.Version,
			Commit:    b.Instance.Commit,
			BuildDate: b.Instance.BuildDate,
			Go:        b.Instance.Go,
		}
	}

	gather("config", func() error {
		b.Config = s.settingsConfig(callerRoleCtx(ctx))
		b.Findings = s.cfg().Validate().ForUI()
		return nil
	})
	gather("problems", func() error {
		items, err := s.ctrl.Problems(ctx)
		if err != nil {
			return err
		}
		// The same audience split as the problems drawer: a failed backup
		// names the directory it could not write, and that directory is the
		// machine's, not the fleet's.
		view := controller.NewProblemsViewFor(items, callerRoleCtx(ctx).AtLeast(store.RolePlatform))
		b.Problems = &view
		return nil
	})
	gather("stats", func() error {
		stats, err := s.ctrl.Stats(ctx, defaultStatsWindow)
		if err != nil {
			return err
		}
		b.Stats = stats
		return nil
	})
	gather("installations", func() error {
		insts, err := s.ctrl.Store().ListInstallations(ctx)
		if err != nil {
			return err
		}
		counts, err := s.ctrl.PoolCountsByInstallation(ctx)
		if err != nil {
			return err
		}
		for _, i := range insts {
			b.Installations = append(b.Installations, controller.NewInstallationView(i, counts[i.ID]))
		}
		return nil
	})
	gather("pools", func() error {
		pools, err := s.ctrl.Store().ListPools(ctx)
		if err != nil {
			return err
		}
		view, err := s.ctrl.PoolRenderer(ctx)
		if err != nil {
			return err
		}
		for _, p := range pools {
			// Not poolFor: that is role-based, and an administrator who may read
			// the values on the pool's own route is not the reader of this file,
			// which is attached to an issue or sent to whoever runs the platform.
			b.Pools = append(b.Pools, view.View(p).WithoutEnvValues())
		}
		return nil
	})
	gather("hosts", func() error {
		hosts, err := s.ctrl.Store().ListHosts(ctx)
		if err != nil {
			return err
		}
		for _, h := range hosts {
			b.Hosts = append(b.Hosts, s.ctrl.HostView(h))
		}
		return nil
	})

	gather("providers", func() error {
		rows, err := s.ctrl.Store().ListProviders(ctx)
		if err != nil {
			return err
		}
		for _, row := range rows {
			machines, err := s.ctrl.Store().ListMachinesForProvider(ctx, row.ID)
			if err != nil {
				return err
			}
			b.Providers = append(b.Providers, s.ctrl.ProviderView(row, machines))
		}
		return nil
	})
	gather("machines", func() error {
		// Deleted machines are left out for the reason finished jobs are: a
		// fleet that has been renting for a month has far more history than
		// present, and a bundle is taken because something is stuck now.
		found, total, err := s.ctrl.Store().ListMachines(ctx, store.MachineFilter{}, store.Page{Limit: bundleMaxMachines})
		if err != nil {
			return err
		}
		view, err := s.ctrl.MachineRenderer(ctx)
		if err != nil {
			return err
		}
		for _, m := range found {
			b.Machines = append(b.Machines, view.View(m))
		}
		b.note(total > len(found), "machines", len(found), fmt.Sprintf("the fleet has %d; a bundle carries the newest %d", total, bundleMaxMachines))
		return nil
	})

	var runners []*store.Runner
	gather("runners", func() error {
		found, total, err := s.ctrl.Store().ListRunners(ctx, store.RunnerFilter{}, store.Page{Limit: bundleMaxRunners})
		if err != nil {
			return err
		}
		runners = found
		view, err := s.ctrl.RunnerRenderer(ctx, found)
		if err != nil {
			return err
		}
		for _, run := range found {
			b.Runners = append(b.Runners, view.View(run))
		}
		b.note(total > len(found), "runners", len(found), fmt.Sprintf("the fleet has %d; a bundle carries the newest %d", total, bundleMaxRunners))
		return nil
	})
	gather("logs", func() error {
		b.Logs = bundleLogPointers(runners)
		return nil
	})

	gather("jobs", func() error {
		return s.bundleJobs(ctx, &b)
	})
	gather("scaling_events", func() error {
		events, err := s.ctrl.Store().ListScalingEvents(ctx, "", bundleMaxScalingEvents)
		if err != nil {
			return err
		}
		b.ScalingEvents = events
		b.note(len(events) == bundleMaxScalingEvents, "scaling_events", len(events), "the newest decisions only")
		return nil
	})
	return b
}

// note records a cap that was reached, so a reader can tell a short section
// from a complete one. A section that fitted says nothing, because a bundle
// full of "not truncated" lines buries the one line that matters.
func (b *supportBundle) note(truncated bool, section string, kept int, reason string) {
	if truncated {
		b.Truncated = append(b.Truncated, bundleTruncation{Section: section, Kept: kept, Reason: reason})
	}
}

// bundleInstance describes the process. Its two store reads are gathered
// individually: a database that will not answer is exactly when the rest of
// this section -- the build, the goroutine count -- is worth having.
func (s *Server) bundleInstance(ctx context.Context, gather func(string, func() error)) bundleInstance {
	var mem runtime.MemStats
	runtime.ReadMemStats(&mem)
	out := bundleInstance{
		Version:          version.Version,
		Commit:           version.Commit,
		BuildDate:        version.Date,
		Go:               runtime.Version(),
		OS:               runtime.GOOS,
		Arch:             runtime.GOARCH,
		CPUs:             runtime.NumCPU(),
		Goroutines:       runtime.NumGoroutine(),
		HeapInUseBytes:   mem.HeapInuse,
		ConfigPath:       s.cfg().Path(),
		DatabasePath:     s.ctrl.Store().Path(),
		EventSubscribers: s.ctrl.Events().Subscribers(),
		PollingOnly:      s.ctrl.PollingOnly(),
		PollerEnabled:    s.ctrl.PollerEnabled(),
	}
	if last := s.ctrl.LastPollAt(); !last.IsZero() {
		out.PollerLastPollAt = &last
	}
	for name, p := range s.ctrl.LoopPanics() {
		out.LoopPanics = append(out.LoopPanics, bundleLoopPanic{Loop: name, Count: p.Count, Last: p.Last, At: p.At})
	}
	slices.SortFunc(out.LoopPanics, func(a, b bundleLoopPanic) int {
		return cmp.Compare(a.Loop, b.Loop)
	})
	gather("instance.schema", func() error {
		applied, err := s.ctrl.Store().AppliedMigrations(ctx)
		if err != nil {
			return err
		}
		out.SchemaApplied = len(applied)
		if n := len(applied); n > 0 {
			out.SchemaLatest = applied[n-1].Name
		}
		return nil
	})
	return out
}

// bundleJobs carries the work in flight and the controller's own answer for
// each of it -- the same answer the drawer and the CLI render, so a bundle
// cannot disagree with the page the operator was looking at when they took it.
func (s *Server) bundleJobs(ctx context.Context, b *supportBundle) error {
	filter := store.JobFilter{States: []store.JobState{store.JobWaiting, store.JobQueued, store.JobInProgress}}
	jobs, total, err := s.ctrl.Store().ListJobs(ctx, filter, store.Page{Limit: bundleMaxJobs})
	if err != nil {
		return err
	}
	pools, err := s.ctrl.Store().ListPools(ctx)
	if err != nil {
		return err
	}
	names := poolNames(pools)
	for _, j := range jobs {
		b.Jobs = append(b.Jobs, controller.NewJobView(j, names[j.PoolID]))
	}
	b.note(total > len(jobs), "jobs", len(jobs), fmt.Sprintf("%d jobs are unfinished; a bundle carries the newest %d", total, bundleMaxJobs))

	for _, j := range jobs {
		if len(b.Explanations) >= bundleMaxExplanations {
			b.note(true, "explanations", len(b.Explanations), "one per unfinished job, oldest first, up to the cap")
			break
		}
		ex, err := s.ctrl.ExplainJob(ctx, j.ID)
		if err != nil {
			// One job that cannot be explained is not the bundle's failure,
			// and the job itself is already in the section above.
			continue
		}
		b.Explanations = append(b.Explanations, ex)
	}
	return nil
}

// bundleLogPointers names the runners whose logs a support case is likely to
// want: the ones that failed, and the ones still trying to start. It is a list
// of routes rather than of bodies -- see the note it carries.
func bundleLogPointers(runners []*store.Runner) *bundleLogs {
	out := &bundleLogs{
		Note: "Workflow logs are never in a bundle: there is no redaction pass for them, and a log holds whatever a workflow printed. " +
			"Fetch the ones a support case needs from the routes below and attach them deliberately.",
		Runners: []bundleLogPointer{},
	}
	for _, r := range runners {
		switch r.State {
		case store.RunnerFailed, store.RunnerProvisioning, store.RunnerRegistering:
		default:
			continue
		}
		if len(out.Runners) >= bundleMaxLogPointers {
			break
		}
		out.Runners = append(out.Runners, bundleLogPointer{
			RunnerID: r.ID,
			Name:     r.Name,
			State:    r.State,
			PoolID:   r.PoolID,
			Download: "/api/v1/runners/" + r.ID + "/logs/download",
		})
	}
	return out
}

// shedOrder is what a bundle gives up when it is over the byte cap, weakest
// evidence first. Explanations are recomputable from the jobs beside them,
// scaling history is the least specific to a fault, and the fleet's own shape
// -- pools, hosts, configuration, problems -- is what a bundle is for and is
// never shed.
var shedOrder = []struct {
	section string
	drop    func(*supportBundle)
}{
	{"explanations", func(b *supportBundle) { b.Explanations = nil }},
	{"scaling_events", func(b *supportBundle) { b.ScalingEvents = nil }},
	{"jobs", func(b *supportBundle) { b.Jobs = nil }},
	{"runners", func(b *supportBundle) { b.Runners = nil }},
}

// marshalBundle renders the document, shedding sections until it is under the
// cap.
//
// The cap is checked on the rendered bytes rather than guessed from row counts
// because what makes a bundle huge is not usually the number of rows: it is one
// fleet's very long pool names, or a hundred scheduler reason strings. A count
// cap cannot see that and a byte cap can.
func marshalBundle(b *supportBundle) ([]byte, error) {
	raw, err := json.Marshal(b)
	if err != nil {
		return nil, err
	}
	for _, shed := range shedOrder {
		if len(raw) <= bundleMaxBytes {
			break
		}
		shed.drop(b)
		b.Truncated = append(b.Truncated, bundleTruncation{
			Section: shed.section,
			Reason:  fmt.Sprintf("the bundle was over its %d-byte cap, and this section is the most recomputable thing in it", bundleMaxBytes),
		})
		if raw, err = json.Marshal(b); err != nil {
			return nil, err
		}
	}
	return raw, nil
}

package api

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// hostResponse is the shape GET /hosts returns, rendered by the controller
// so the event stream's host.updated frames are the same JSON. See
// controller/views.go for why the renderer lives there.
type hostResponse = controller.HostView

// backendInfoResponse is one entry of hostResponse.backend_info.
type backendInfoResponse = controller.BackendInfoView

// handleListHosts answers GET /api/v1/hosts.
func (s *Server) handleListHosts(w http.ResponseWriter, r *http.Request) {
	hosts, err := s.ctrl.Store().ListHosts(r.Context())
	if err != nil {
		s.internal(w, r, "listing hosts", err)
		return
	}
	out := make([]hostResponse, 0, len(hosts))
	for _, h := range hosts {
		out = append(out, s.ctrl.HostView(h))
	}
	writeJSON(w, http.StatusOK, newList(out))
}

// handleListHostSamples answers GET /api/v1/hosts/samples: every host's
// minute samples, for the capacity map. It takes `since` or `window` exactly
// as /samples does, and `host_id` narrows it to one host.
func (s *Server) handleListHostSamples(w http.ResponseWriter, r *http.Request) {
	since, err := queryTime(r, "since")
	if err != nil {
		badRequestField(w, "since", err.Error())
		return
	}
	if since == nil {
		window, werr := queryDuration(r, "window", defaultStatsWindow)
		if werr != nil {
			badRequestField(w, "window", werr.Error())
			return
		}
		t := s.ctrl.Now().Add(-window)
		since = &t
	}
	samples, err := s.ctrl.HostSamples(r.Context(), *since, r.URL.Query().Get("host_id"))
	if err != nil {
		s.internal(w, r, "reading host samples", err)
		return
	}
	writeJSON(w, http.StatusOK, newList(samples))
}

// handleGetHost answers GET /api/v1/hosts/{id}.
func (s *Server) handleGetHost(w http.ResponseWriter, r *http.Request) {
	h, err := s.ctrl.Store().GetHost(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the host", err)
		return
	}
	writeJSON(w, http.StatusOK, s.ctrl.HostView(h))
}

type hostUpdateRequest struct {
	Capacity *int               `json:"capacity"`
	Labels   *map[string]string `json:"labels"`
	// The reserve: what this machine keeps for itself, in the units its own
	// figures are reported in. Each is optional and each is separate -- an
	// operator who holds back memory has said nothing about CPU.
	ReserveCPUs     *int   `json:"reserve_cpus"`
	ReserveMemoryMB *int64 `json:"reserve_memory_mb"`
	ReserveDiskMB   *int64 `json:"reserve_disk_mb"`
}

// handleUpdateHost changes a host's capacity, labels or reserve.
func (s *Server) handleUpdateHost(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	h, err := s.ctrl.Store().GetHost(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the host", err)
		return
	}

	var req hostUpdateRequest
	if !decode(w, r, &req) {
		return
	}
	var fields []fieldError
	if req.Capacity != nil {
		switch {
		case *req.Capacity < 0:
			fields = append(fields, fieldError{"capacity", "capacity cannot be negative; use 0 to stop this host taking new runners"})
		case *req.Capacity < h.ActiveRunners:
			// Allowed, and worth saying plainly rather than refusing: the
			// running jobs finish, and nothing new is placed until the host is
			// back under its new capacity.
			s.logger(r).Info("a host's capacity was lowered below the number of runners it is already running",
				"host", h.ID, "capacity", *req.Capacity, "active", h.ActiveRunners)
		}
	}
	if req.Labels != nil {
		for k := range *req.Labels {
			if strings.TrimSpace(k) == "" {
				fields = append(fields, fieldError{"labels", "a label needs a name"})
				break
			}
		}
	}
	// A reserve larger than the machine is refused rather than clamped: it
	// leaves nothing placeable, and an operator who typed megabytes where they
	// meant gigabytes should be told, not quietly obeyed. A reserve on a
	// figure the host has never reported is refused for the same reason --
	// there is nothing to hold back a share of, and the scheduler would ignore
	// it while the page showed it.
	if req.ReserveCPUs != nil {
		switch {
		case *req.ReserveCPUs < 0:
			fields = append(fields, fieldError{"reserve_cpus", "a reserve cannot be negative"})
		case h.CPUs <= 0 && *req.ReserveCPUs > 0:
			fields = append(fields, fieldError{"reserve_cpus", "this host has not reported how many CPUs it has, so there is nothing to hold back; upgrade its agent"})
		case h.CPUs > 0 && *req.ReserveCPUs >= h.CPUs:
			fields = append(fields, fieldError{"reserve_cpus", fmt.Sprintf("this host has %d CPUs; a reserve of %d would leave nothing to place on", h.CPUs, *req.ReserveCPUs)})
		}
	}
	if req.ReserveMemoryMB != nil {
		switch {
		case *req.ReserveMemoryMB < 0:
			fields = append(fields, fieldError{"reserve_memory_mb", "a reserve cannot be negative"})
		case h.MemoryMB <= 0 && *req.ReserveMemoryMB > 0:
			fields = append(fields, fieldError{"reserve_memory_mb", "this host has not reported how much memory it has, so there is nothing to hold back; upgrade its agent"})
		case h.MemoryMB > 0 && *req.ReserveMemoryMB >= h.MemoryMB:
			fields = append(fields, fieldError{"reserve_memory_mb", fmt.Sprintf("this host has %d MB of memory; a reserve of %d would leave nothing to place on", h.MemoryMB, *req.ReserveMemoryMB)})
		}
	}
	if req.ReserveDiskMB != nil {
		switch {
		case *req.ReserveDiskMB < 0:
			fields = append(fields, fieldError{"reserve_disk_mb", "a reserve cannot be negative"})
		case h.DiskTotalMB <= 0 && *req.ReserveDiskMB > 0:
			fields = append(fields, fieldError{"reserve_disk_mb", "this host has not reported its work directory's disk, so there is nothing to hold back; upgrade its agent"})
		case h.DiskTotalMB > 0 && *req.ReserveDiskMB >= h.DiskTotalMB:
			fields = append(fields, fieldError{"reserve_disk_mb", fmt.Sprintf("this host's work directory has %d MB of disk; a reserve of %d would leave nothing to place on", h.DiskTotalMB, *req.ReserveDiskMB)})
		}
	}
	if len(fields) > 0 {
		unprocessable(w, "this host cannot be changed as described", fields)
		return
	}

	// A host's settings and a pool's requirements are edited on different
	// pages, so neither form can show the other half. An edit that takes away
	// the last machine a pool could ever run on is refused here rather than
	// discovered an hour later as a job that never started; confirm=true is
	// the operator saying they meant it, which is right when the pool is on
	// its way out.
	if !queryBool(r, "confirm", false) {
		proposed := *h
		if req.Capacity != nil {
			proposed.Capacity = *req.Capacity
		}
		if req.ReserveCPUs != nil {
			proposed.ReserveCPUs = *req.ReserveCPUs
		}
		if req.ReserveMemoryMB != nil {
			proposed.ReserveMemoryMB = *req.ReserveMemoryMB
		}
		if req.ReserveDiskMB != nil {
			proposed.ReserveDiskMB = *req.ReserveDiskMB
		}
		if req.Labels != nil {
			proposed.Labels = store.StringMap(*req.Labels)
		}
		stranded, serr := s.ctrl.HostStrandings(r.Context(), &proposed)
		if serr != nil {
			s.internal(w, r, "checking which pools this change would leave with nowhere to run", serr)
			return
		}
		if len(stranded) > 0 {
			conflict(w, hostStrandingRefusal(stranded[0].Host, stranded))
			return
		}
	}

	before := *h
	changes := store.HostChanges{
		Capacity: req.Capacity, ReserveCPUs: req.ReserveCPUs,
		ReserveMemoryMB: req.ReserveMemoryMB, ReserveDiskMB: req.ReserveDiskMB,
	}
	if req.Labels != nil {
		labels := store.StringMap(*req.Labels)
		changes.Labels = &labels
	}
	if err := s.ctrl.Store().PatchHost(r.Context(), id, changes); err != nil {
		s.fail(w, r, "saving the host", err)
		return
	}
	h, err = s.ctrl.Store().GetHost(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the host back", err)
		return
	}

	// A change to the capacity or the reserve is the operator answering the
	// pressure that throttled the host -- fewer slots, or more of the machine
	// kept back -- so the rung it was on is lifted with it. Left standing, the
	// new figures would only take effect once the old episode had spent five
	// minutes calm, and the card would show a throttle nothing explains. A
	// label change says nothing about the machine and lifts nothing, and
	// neither does a request that repeats the figures the host already has:
	// the edit dialog sends every field it shows, and only a figure that
	// moved is an answer. When the
	// lift itself fails the patch still stands, so the answer is the saved
	// host and a log line, not a 500 that reads as "nothing was saved".
	cleared := false
	resized := before.Capacity != h.Capacity || before.ReserveCPUs != h.ReserveCPUs ||
		before.ReserveMemoryMB != h.ReserveMemoryMB || before.ReserveDiskMB != h.ReserveDiskMB
	if h.Throttle.Active() && resized {
		if lifted, err := s.ctrl.ClearHostThrottle(r.Context(), id); err != nil {
			s.logger(r).Warn("a host's capacity or reserve changed but its throttle could not be lifted; the next heartbeat decides it again",
				"host", id, "error", err)
		} else {
			h, cleared = lifted, true
		}
	}

	s.auditHostUpdate(r, id, &before, h, cleared)
	s.ctrl.PublishHost(h)
	// Capacity, labels and the reserve all decide where runners may be placed.
	s.ctrl.Nudge()
	writeJSON(w, http.StatusOK, s.ctrl.HostView(h))
}

// auditHostUpdate writes the PATCH's audit row: the fields that differ, as
// Auditor.Updated would, plus "throttle_cleared" when the change lifted one.
// The throttle column already appears in the diff, but a reader of the audit
// page should not have to know that {} against {level: 2} means "lifted".
func (s *Server) auditHostUpdate(r *http.Request, id string, before, after *store.Host, cleared bool) {
	b, af := auth.Diff(before, after)
	if cleared {
		detail, _ := af.(map[string]any)
		if detail == nil {
			detail = map[string]any{}
		}
		detail["throttle_cleared"] = true
		af = detail
	}
	if b == nil && af == nil {
		// Nothing changed, and Updated would have written nothing either.
		return
	}
	_ = s.auth.Auditor().Record(r.Context(), Identity(r.Context()), "host.update", "host", id, b, af)
}

// handleClearHostThrottle lifts a host's throttle by hand.
//
// It is for a host whose cause is known and fixed: the runaway job was
// cancelled, the daemon was restarted. Nothing pins the throttle the other
// way, so a host still under pressure is stepped back up by its next
// heartbeat, and the audit row says who lifted it early. A host on no rung is
// answered as it is, and nothing is written about it -- exactly as an
// uncordon of an uncordoned host is.
func (s *Server) handleClearHostThrottle(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	h, err := s.ctrl.Store().GetHost(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the host", err)
		return
	}
	if was := h.Throttle; was.Active() {
		effective := h.EffectiveCapacity()
		h, err = s.ctrl.ClearHostThrottle(r.Context(), id)
		if err != nil {
			s.fail(w, r, "lifting the host's throttle", err)
			return
		}
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "host.throttle_clear", "host", id, map[string]any{
			"name": h.Name, "level": was.Level, "reason": was.Reason, "since": was.Since,
			"effective_capacity": effective, "capacity": h.Capacity,
		})
	}
	writeJSON(w, http.StatusOK, s.ctrl.HostView(h))
}

type cordonRequest struct {
	Cordoned bool `json:"cordoned"`
}

// handleCordonHost cordons or uncordons a host.
//
// A cordoned host keeps everything it is already running: cordoning is how an
// operator drains a machine before maintenance without interrupting the jobs on
// it, and killing them would defeat the purpose.
func (s *Server) handleCordonHost(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	h, err := s.ctrl.Store().GetHost(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the host", err)
		return
	}

	var req cordonRequest
	if !decode(w, r, &req) {
		return
	}
	if h.Cordoned != req.Cordoned {
		if err := s.ctrl.Store().SetHostCordoned(r.Context(), id, req.Cordoned); err != nil {
			s.fail(w, r, "cordoning the host", err)
			return
		}
		h.Cordoned = req.Cordoned
		action := "host.uncordon"
		if req.Cordoned {
			action = "host.cordon"
		}
		s.auth.Auditor().Act(r.Context(), Identity(r.Context()), action, "host", id, map[string]any{
			"name": h.Name, "cordoned": req.Cordoned, "active_runners": h.ActiveRunners,
		})
		s.ctrl.PublishHost(h)
		s.ctrl.Nudge()
	}
	writeJSON(w, http.StatusOK, s.ctrl.HostView(h))
}

// handleDeleteHost removes a host.
//
// It refuses while the host still has live runners unless forced, because
// deleting the row cascades to those runners and their workloads would be left
// running on a machine Zoomies no longer knows about. It refuses a host that is
// a machine Zoomies rented for a second reason: the row is what says a VM
// exists and who is paying for it, and forgetting it here would leave the VM
// running with nothing tracking it.
func (s *Server) handleDeleteHost(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	force := queryBool(r, "force", false)

	h, err := s.ctrl.Store().GetHost(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the host", err)
		return
	}
	if !force {
		switch m, merr := s.ctrl.Store().GetMachineByHost(r.Context(), id); {
		case merr == nil && m != nil:
			rentedFrom := m.ProviderID
			if row, perr := s.ctrl.Store().GetProvider(r.Context(), m.ProviderID); perr == nil {
				rentedFrom = row.Name
			}
			conflict(w, fmt.Sprintf("host %s is a machine Zoomies created on %s. Delete the machine instead "+
				"(that removes the VM too), or repeat this with ?force=true to forget the host and the machine record and leave the VM running, untracked.",
				h.Name, rentedFrom))
			return
		case merr != nil && !errors.Is(merr, store.ErrNotFound):
			s.internal(w, r, "checking whether the host is a machine Zoomies created", merr)
			return
		}
	}
	live, err := s.ctrl.Store().ListRunnersForHost(r.Context(), id)
	if err != nil {
		s.internal(w, r, "listing the host's runners", err)
		return
	}
	alive := 0
	for _, run := range live {
		if !run.State.Terminal() {
			alive++
		}
	}
	if alive > 0 && !force {
		conflict(w, fmt.Sprintf("host %s is still running %d runner(s); cordon it and wait for them to finish, or repeat this with ?force=true to remove it and leave those workloads to be cleaned up by their agent", h.Name, alive))
		return
	}

	var forgotten *store.Machine
	if force {
		var ok bool
		if forgotten, ok = s.machineToForget(w, r, id); !ok {
			return
		}
	}

	machineID := ""
	if forgotten != nil {
		machineID = forgotten.ID
	}
	if err := s.ctrl.DeleteHostForgettingMachine(r.Context(), id, machineID); err != nil {
		s.fail(w, r, "deleting the host", err)
		return
	}
	if forgotten != nil {
		// After the commit, and on a context the client hanging up cannot
		// cancel: from here the audit row is the only record of the VM, so a
		// request that dies now must not take the resource identifier with it.
		s.auth.Auditor().Act(context.WithoutCancel(r.Context()), Identity(r.Context()), "machine.release", "machine", forgotten.ID, map[string]any{
			"name": forgotten.Name, "state": forgotten.State, "provider_id": forgotten.ProviderID,
			"resource_zone": forgotten.ResourceZone, "resource_id": forgotten.ResourceID,
			"address": forgotten.Address, "host_id": forgotten.HostID, "reason": "its host was force-deleted",
		})
	}
	s.auth.Auditor().Deleted(r.Context(), Identity(r.Context()), "host", id, h)
	s.ctrl.Nudge()
	noContent(w)
}

// machineToForget finds the machine a forced host delete has to forget so it
// stays to what the 409 promises -- the VM is left running -- and reports
// whether the delete may go on. It writes nothing: the row goes in the same
// transaction as the host, and the caller audits it once that has committed.
//
// machines.host_id is ON DELETE SET NULL, and the machine loop treats a ready
// machine with no host as one to release: drain, then destroy the VM, without
// waiting for the jobs the cascade just erased. So forgetting only the host
// would end in the destructive act the operator was told would not happen. A
// machine that is already deleting is left alone: the delete is under way, and
// dropping the row would abandon it half done with the VM still billed.
func (s *Server) machineToForget(w http.ResponseWriter, r *http.Request, hostID string) (*store.Machine, bool) {
	m, err := s.ctrl.Store().GetMachineByHost(r.Context(), hostID)
	if errors.Is(err, store.ErrNotFound) {
		return nil, true
	}
	if err != nil {
		s.internal(w, r, "checking whether the host is a machine Zoomies created", err)
		return nil, false
	}
	if m == nil || m.State == store.MachineDeleting {
		return nil, true
	}
	return m, true
}

// ---------------------------------------------------------------------------
// Join tokens
// ---------------------------------------------------------------------------

// joinTokenResponse never carries the secret. The prefix is enough to recognise
// a token in a list and to match a leaked string to a row.
type joinTokenResponse struct {
	ID        string            `json:"id"`
	Prefix    string            `json:"prefix"`
	CreatedBy string            `json:"created_by,omitempty"`
	Capacity  int               `json:"capacity"`
	Labels    map[string]string `json:"labels"`
	CreatedAt time.Time         `json:"created_at"`
	ExpiresAt time.Time         `json:"expires_at"`
	UsedAt    *time.Time        `json:"used_at"`
	UsedByID  string            `json:"used_by_id,omitempty"`
	Usable    bool              `json:"usable"`
}

// createJoinTokenResponse adds the things that exist exactly once: the
// plaintext token, the command to paste on the new host, and -- when the
// command could not be pinned to this controller's build -- what that will
// cost the operator.
type createJoinTokenResponse struct {
	joinTokenResponse
	Token             string `json:"token"`
	Command           string `json:"command"`
	JoinCommand       string `json:"join_command"`
	ControllerVersion string `json:"controller_version"`
	InstallTag        string `json:"install_tag,omitempty"`
	// VersionNote is empty when the command installs a matching agent.
	VersionNote string `json:"version_note,omitempty"`
}

func (s *Server) joinTokenResponse(t *store.JoinToken) joinTokenResponse {
	return joinTokenResponse{
		ID:        t.ID,
		Prefix:    t.Prefix,
		CreatedBy: t.CreatedBy,
		Capacity:  t.Capacity,
		Labels:    emptyMap(t.Labels),
		CreatedAt: t.CreatedAt,
		ExpiresAt: t.ExpiresAt,
		UsedAt:    t.UsedAt,
		UsedByID:  t.UsedByID,
		Usable:    t.Usable(s.ctrl.Now()),
	}
}

// handleListJoinTokens answers GET /api/v1/join-tokens.
func (s *Server) handleListJoinTokens(w http.ResponseWriter, r *http.Request) {
	tokens, err := s.ctrl.Store().ListJoinTokens(r.Context())
	if err != nil {
		s.internal(w, r, "listing join tokens", err)
		return
	}
	out := make([]joinTokenResponse, 0, len(tokens))
	for _, t := range tokens {
		out = append(out, s.joinTokenResponse(t))
	}
	writeJSON(w, http.StatusOK, newList(out))
}

type createJoinTokenRequest struct {
	TTL      string            `json:"ttl"`
	Capacity int               `json:"capacity"`
	Labels   map[string]string `json:"labels"`
	// ControllerURL is the address the new host should join on, when the
	// caller knows better than server.external_url does. The UI always does:
	// the browser reached this controller on some address, and a machine on
	// the same network will usually reach it there too.
	ControllerURL string `json:"controller_url"`
	Connection    string `json:"connection"`
}

// handleCreateJoinToken mints a single-use enrolment credential.
func (s *Server) handleCreateJoinToken(w http.ResponseWriter, r *http.Request) {
	// No capacity: the agent decides from the machine it measures, which is
	// the only figure in this exchange that has seen the machine. A constant
	// here pinned every host that did not name one to that constant, however
	// large it was -- and under automatic sizing the capacity is no longer
	// only a slot count, it is the divisor that gives each runner its CPU and
	// memory, so two slots on a thirty-two core box is half the machine per
	// runner and two jobs at a time.
	req := createJoinTokenRequest{TTL: "15m"}
	if !decodeOptional(w, r, &req) {
		return
	}

	var fields []fieldError
	ttl := 15 * time.Minute
	if raw := strings.TrimSpace(req.TTL); raw != "" {
		d, err := time.ParseDuration(raw)
		switch {
		case err != nil:
			fields = append(fields, fieldError{"ttl", fmt.Sprintf("%q is not a duration; write it like 15m, 1h or 24h", raw)})
		case d <= 0:
			fields = append(fields, fieldError{"ttl", "a join token has to be usable for some length of time; try 15m"})
		default:
			ttl = d
		}
	}
	if req.Capacity < 0 {
		fields = append(fields, fieldError{"capacity", "capacity cannot be negative; leave it at 0 to let the agent decide from the host's CPU count"})
	}
	if req.Connection != "" && req.Connection != "direct" && req.Connection != "tailcat" {
		fields = append(fields, fieldError{"connection", "choose direct or tailcat"})
	}
	controllerURL := strings.TrimRight(strings.TrimSpace(req.ControllerURL), "/")
	if controllerURL != "" {
		if msg := checkControllerURL(controllerURL); msg != "" {
			fields = append(fields, fieldError{"controller_url", msg})
		}
	}
	if len(fields) > 0 {
		unprocessable(w, "this join token could not be created", fields)
		return
	}
	if err := s.ctrl.AdmitJoinToken(r.Context()); err != nil {
		if !asLimit(w, err) {
			s.internal(w, r, "checking limits.join_tokens", err)
		}
		return
	}

	if req.Connection == "tailcat" {
		address, err := s.ensureTailcat(r.Context())
		if err != nil {
			unprocessable(w, err.Error(), []fieldError{{"connection", err.Error()}})
			return
		}
		controllerURL = "tailcat://" + address
	}
	id := Identity(r.Context())
	createdBy := ""
	if id != nil {
		createdBy = id.Name
	}
	token, plaintext, err := s.auth.CreateJoinToken(r.Context(), ttl, req.Labels, req.Capacity, createdBy)
	if err != nil {
		s.internal(w, r, "creating the join token", err)
		return
	}
	// The plaintext is deliberately not in the audit row: the row records that
	// a credential was minted, not the credential.
	s.auth.Auditor().Created(r.Context(), id, "join_token", token.ID, token)

	writeJSON(w, http.StatusCreated, createJoinTokenResponse{
		joinTokenResponse: s.joinTokenResponse(token),
		Token:             plaintext,
		Command:           s.joinCommand(plaintext, controllerURL),
		JoinCommand:       "zoomies agent join " + shellArgument(s.joinControllerURL(controllerURL)) + " --token " + shellArgument(plaintext),
		ControllerVersion: version.Short(),
		InstallTag:        version.Channel(version.Version),
		VersionNote:       joinVersionNote(),
	})
}

// checkControllerURL says what is wrong with an address a host is being told
// to join, or nothing. The bar is "an agent could dial it": an absolute
// http(s) URL with a host in it. Loopback is allowed on purpose -- an operator
// enrolling a second agent on the controller's own machine means it -- and
// the UI is what warns about it, since the UI knows which machine it is on.
func checkControllerURL(raw string) string {
	u, err := url.Parse(raw)
	switch {
	case err != nil:
		return fmt.Sprintf("%q is not a URL an agent could join; write it like https://zoomies.example.com", raw)
	case u.Scheme != "http" && u.Scheme != "https":
		return fmt.Sprintf("the controller address has to start with http:// or https://, not %q", u.Scheme+"://")
	case u.Host == "":
		return "the controller address needs a host name or IP address, like https://zoomies.example.com"
	case u.User != nil:
		return "the controller address must not carry a username or password; the join token is the credential"
	}
	return ""
}

// joinCommand renders the one-liner for the new host.
//
// The caller's address wins when it gave one. Otherwise the command names the
// controller's external URL, because that is the address the agent has to
// reach; when that is not configured either the command is still printed,
// with the placeholder in it, since an operator who has not set it yet needs
// to see what is missing rather than a blank field.
func (s *Server) joinControllerURL(controllerURL string) string {
	controller := controllerURL
	if controller == "" {
		controller = s.cfg().Server.ExternalURL
		// A loopback external URL is as unusable here as no URL at all, and
		// worse for being plausible: the default single-VM install makes it
		// http://localhost:8080, so the command told the new machine to join
		// itself, and the operator found out after a download, a system
		// write and a spent single-use token. The placeholder makes the gap
		// visible, and the UI fills it in.
		if controller == "" || s.cfg().ExternalURLIsLocal() {
			controller = "https://<this-controller>"
		}
	}
	return controller
}

func (s *Server) joinCommand(token, controllerURL string) string {
	controller := s.joinControllerURL(controllerURL)
	cmd := fmt.Sprintf("curl -fsSL https://zoomies.sh/install.sh | sh -s -- --mode agent --controller %s --join-token %s",
		shellArgument(controller), shellArgument(token))

	// Pin the agent to this controller's own published channel.
	//
	// Unpinned, the installer resolves "latest", which is the newest *published
	// release* -- not this build. A fleet whose controller was upgraded past the
	// newest release therefore enrolled every new host on an older agent, and
	// the host arrived reading "Different build" for good: re-running the
	// command changed nothing, because the version it asks for is the version
	// already there.
	//
	// It is worse than a cosmetic badge when the older agent predates something.
	// An agent that cannot yet measure its own machine reports no CPUs, memory
	// or disk, so the host shows "Size unknown" and a pool's resource limits
	// have nothing to fit against -- and no argument to the command could have
	// fixed it.
	if tag, ok := version.InstallTag(version.Version); ok {
		return cmd + " --version " + tag
	}

	// No pin, because there is nothing honest to pin to. Local and fork builds
	// have no repository asset; the command still works and the note says what
	// it cannot promise instead.
	return cmd
}

// shellArgument keeps a URL or credential one literal argument when the
// operator pastes the command into a POSIX shell.
func shellArgument(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

// joinVersionNote explains a join command that could not be pinned, or is empty
// when it was.
//
// The command above stays runnable either way, so this is the difference
// between an operator who knows their new host will read "Different build" and
// one who finds out afterwards and starts re-running the installer to fix it.
func joinVersionNote() string {
	if _, ok := version.InstallTag(version.Version); ok {
		return ""
	}
	return fmt.Sprintf("This controller is %s, which is a local or unpublished build, "+
		"so there is no matching agent to install. The host will get the newest release and the "+
		"fleet will show it as a different build until this controller runs a released version.",
		version.Version)
}

// handleGetJoinToken answers GET /api/v1/join-tokens/{id}.
//
// It is what the Add-a-host page polls while the operator is over on the new
// machine: the fleet stream deliberately carries nothing about credentials, so
// a token being redeemed is learnt by asking, and used_by_id is the host it
// became.
func (s *Server) handleGetJoinToken(w http.ResponseWriter, r *http.Request) {
	t, err := s.ctrl.Store().GetJoinToken(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the join token", err)
		return
	}
	writeJSON(w, http.StatusOK, s.joinTokenResponse(t))
}

// handleDeleteJoinToken revokes an unused join token.
func (s *Server) handleDeleteJoinToken(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	found, err := s.ctrl.Store().GetJoinToken(r.Context(), id)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			notFound(w, "there is no join token "+id+"; it may already have been used or revoked")
			return
		}
		s.internal(w, r, "reading the join token", err)
		return
	}
	if err := s.ctrl.Store().DeleteJoinToken(r.Context(), id); err != nil {
		s.fail(w, r, "revoking the join token", err)
		return
	}
	s.auth.Auditor().Deleted(r.Context(), Identity(r.Context()), "join_token", id, found)
	noContent(w)
}

package api

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// maxInstallationArchiveBytes bounds an import. An archive is one
// installation's history -- a year of sessions and whatever jobs retention
// kept -- so it can outgrow the user API's one-megabyte body limit by a long
// way, and is still nothing like a whole database.
const maxInstallationArchiveBytes = 512 << 20

type exportInstallationRequest struct {
	// Passphrase re-seals the App's private key and webhook secret so the
	// archive can be imported elsewhere without this instance's key. It is in
	// the body, not the query, because a query string is where a passphrase
	// ends up in a proxy log.
	Passphrase string `json:"passphrase,omitempty"`
}

// handleExportInstallation answers POST /api/v1/installations/{id}/export.
func (s *Server) handleExportInstallation(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	var req exportInstallationRequest
	if r.ContentLength != 0 && !decode(w, r, &req) {
		return
	}
	if req.Passphrase != "" && s.key == nil {
		s.noEncryptionKey(w)
		return
	}
	archive, err := s.ctrl.ExportInstallation(r.Context(), id, req.Passphrase)
	if err != nil {
		s.fail(w, r, "exporting the installation", err)
		return
	}
	rows := map[string]int{}
	for _, t := range archive.Tables {
		rows[t.Table] = len(t.Rows)
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "installation.export", "installation", id, map[string]any{
		"target": archive.Target, "rows": rows, "credentials": archive.Secrets != nil,
	})
	raw, err := json.Marshal(archive)
	if err != nil {
		s.internal(w, r, "rendering the archive", err)
		return
	}
	stamp := archive.ExportedAt.Format("20060102-150405")
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="zoomies-installation-%s-%s.json"`,
		safeFilePart(archive.Target), stamp))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(append(raw, '\n'))
}

// safeFilePart keeps a target name fit for a Content-Disposition filename.
func safeFilePart(s string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_', r == '.':
			return r
		}
		return '-'
	}, s)
}

type importInstallationRequest struct {
	Archive    *controller.InstallationArchive `json:"archive"`
	Passphrase string                          `json:"passphrase,omitempty"`
}

type importInstallationResponse struct {
	Installation controller.InstallationView `json:"installation"`
	Rows         map[string]int              `json:"rows"`
	Skipped      map[string]int              `json:"skipped"`
}

// handleImportInstallation answers POST /api/v1/installations/import.
func (s *Server) handleImportInstallation(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxInstallationArchiveBytes)
	// The server's ReadTimeout covers the body, so a big archive on a slow link
	// would be cut off midway and reported as invalid JSON. The size cap above
	// is the bound, as it is for a backup upload.
	_ = http.NewResponseController(w).SetReadDeadline(time.Time{})
	var req importInstallationRequest
	if !decode(w, r, &req) {
		return
	}
	if req.Archive == nil {
		unprocessable(w, "send the archive zoomies export wrote as `archive`", []fieldError{{"archive", "required"}})
		return
	}
	if msg := s.archiveEgressRefusal(req.Archive); msg != "" {
		unprocessable(w, "this archive cannot be imported", []fieldError{{"api_base_url", msg}})
		return
	}
	inst, done, err := s.ctrl.ImportInstallation(r.Context(), req.Archive, req.Passphrase)
	switch {
	case errors.Is(err, controller.ErrArchive), errors.Is(err, store.ErrArchiveShape):
		unprocessable(w, "this archive cannot be imported: "+strings.TrimPrefix(err.Error(), "installation archive: "), nil)
		return
	case err != nil:
		s.fail(w, r, "importing the installation", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "installation.import", "installation", inst.ID, map[string]any{
		"target": inst.Target, "rows": done.Rows, "skipped": done.Skipped,
		"exported_from": req.Archive.ExportedFrom, "credentials": req.Archive.Secrets != nil,
	})
	s.ctrl.Nudge()
	counts, cerr := s.ctrl.PoolCountsByInstallation(r.Context())
	if cerr != nil {
		s.internal(w, r, "reading the installation back", cerr)
		return
	}
	writeJSON(w, http.StatusCreated, importInstallationResponse{
		Installation: controller.NewInstallationView(inst, counts[inst.ID]),
		Rows:         done.Rows,
		Skipped:      done.Skipped,
	})
}

// archiveEgressRefusal says why an archive's installations row may not be
// imported, or "" when it may. The row's api_base_url is inserted as written
// and wins over github.api_base_url for everything the installation does, so
// an archive -- a file anyone can edit -- must meet the same outbound address
// guard as create and update, or the import is the way round it.
func (s *Server) archiveEgressRefusal(archive *controller.InstallationArchive) string {
	for _, t := range archive.Tables {
		if t.Table != "installations" {
			continue
		}
		col := -1
		for i, c := range t.Columns {
			if c == "api_base_url" {
				col = i
			}
		}
		if col < 0 {
			continue
		}
		for _, row := range t.Rows {
			if col >= len(row) || row[col].V == nil {
				continue
			}
			raw, ok := row[col].V.(string)
			if !ok {
				return "the archive's api_base_url must be a URL as text, such as https://ghes.example.com/api/v3; correct it in the file, or export the installation again"
			}
			if strings.TrimSpace(raw) == "" {
				continue
			}
			normalised, err := github.NormalizeAPIBaseURL(raw)
			if err != nil {
				return err.Error()
			}
			if msg := s.egressRefusal(normalised); msg != "" {
				return msg
			}
		}
	}
	return ""
}

package api

import (
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// defaultReportWindow is a month, which is the period the report exists for:
// an operator's own record of how each installation was served over one.
const defaultReportWindow = 30 * 24 * time.Hour

// installationReportResponse is GET /installations/{id}/report.
//
// It names no repository. The counts are per installation, and the route is
// gated on usage.read, which a token can hold without jobs.read -- the scope
// that reads repository names. An installation's target can itself be a
// repository, so it is only rendered to a caller who could read it anyway.
type installationReportResponse struct {
	Installation installationRef `json:"installation"`
	Window       string          `json:"window"`
	*store.InstallationReport
	// Unavailable says in words which figures do not cover the whole window,
	// and why, so a client does not have to derive it from the instants.
	Unavailable []string `json:"unavailable"`
}

type installationRef struct {
	ID         string `json:"id"`
	Target     string `json:"target,omitempty"`
	TargetType string `json:"target_type,omitempty"`
}

func (s *Server) handleInstallationReport(w http.ResponseWriter, r *http.Request) {
	window, err := queryDuration(r, "window", defaultReportWindow)
	if err != nil {
		badRequestField(w, "window", err.Error())
		return
	}
	if window > maxUsageRange {
		badRequestField(w, "window", "window cannot exceed 366 days (8784h)")
		return
	}
	inst, err := s.ctrl.Store().GetInstallation(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the installation", err)
		return
	}
	now := s.ctrl.Now()
	rep, err := s.ctrl.Store().InstallationReport(r.Context(), inst.ID, now.Add(-window), now)
	if err != nil {
		s.internal(w, r, "computing the installation report", err)
		return
	}
	ref := installationRef{ID: inst.ID}
	if targetVisible(Identity(r.Context()), inst) {
		ref.Target, ref.TargetType = inst.Target, string(inst.TargetType)
	}
	writeJSON(w, http.StatusOK, installationReportResponse{
		Installation: ref, Window: window.String(), InstallationReport: rep, Unavailable: reportGaps(rep),
	})
}

// targetVisible says whether a caller may be shown an installation's target.
// An organisation's name is what installations.read reads; a repository's is
// also what jobs.read reads, and a caller with only one of them is shown
// neither.
func targetVisible(id *auth.Identity, inst *store.Installation) bool {
	if id == nil || !auth.Allowed(id, auth.ActionInstallationsRead) {
		return false
	}
	return inst.TargetType != store.TargetRepo || auth.Allowed(id, auth.ActionJobsRead)
}

// reportGaps renders the parts of the window a report could not answer.
func reportGaps(rep *store.InstallationReport) []string {
	out := []string{}
	day := func(t time.Time) string { return t.UTC().Format("2 January 2006 15:04 MST") }
	if rep.CountsFrom.After(rep.From) {
		out = append(out, "Counts before "+day(rep.CountsFrom)+" are unavailable: the rows they are counted from "+
			"were pruned before the daily roll-up began keeping them.")
	}
	if rep.TimingsFrom.After(rep.From) {
		out = append(out, "Timings before "+day(rep.TimingsFrom)+" are unavailable: they are measured from runner "+
			"sessions, which retention.runner_sessions has pruned, and the daily roll-up keeps counts only.")
	}
	return out
}

