// jobFacetsResponse populates the filter menus.
type jobFacetsResponse struct {
	Repos       []string `json:"repos"`
	Workflows   []string `json:"workflows"`
	Conclusions []string `json:"conclusions"`
}

// handleJobFacets answers GET /api/v1/jobs/facets.
//
// The distinct values come from the database rather than from the page the UI
// happens to be showing, so the filter menu offers every repository that has
// ever run a job here, not only the fifty most recent.
func (s *Server) handleJobFacets(w http.ResponseWriter, r *http.Request) {
	out := jobFacetsResponse{}
	for _, f := range []struct {
		column string
		into   *[]string
	}{
		{"repo", &out.Repos},
		{"workflow", &out.Workflows},
		{"conclusion", &out.Conclusions},
	} {
		values, err := s.ctrl.Store().JobDistinct(r.Context(), f.column, 500)
		if err != nil {
			s.internal(w, r, "reading the distinct "+f.column+" values", err)
			return
		}
		*f.into = emptySlice(values)
	}
	writeJSON(w, http.StatusOK, out)
}

// handleJobExplanation answers GET /api/v1/jobs/{id}/explanation.
//
// It is its own endpoint rather than a field on the job, because the answer is
// computed from the last scheduler plan and the fleet around the job rather
// than from the row -- so it would be wrong on every cached copy of a job the
// event stream has already delivered.
func (s *Server) handleJobExplanation(w http.ResponseWriter, r *http.Request) {
	out, err := s.ctrl.ExplainJob(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "explaining the job", err)
		return
	}
	writeJSON(w, http.StatusOK, out)
}

func parseJobFilter(w http.ResponseWriter, r *http.Request) (store.JobFilter, bool) {
	filter := store.JobFilter{
		Repos:        queryList(r, "repo"),
		Branches:     queryList(r, "branch"),
		Provisioning: queryList(r, "provisioning"),
		Workflows:    queryList(r, "workflow"),
		PoolIDs:      queryList(r, "pool_id"),
		RunnerIDs:    queryList(r, "runner_id"),
		Conclusions:  queryList(r, "conclusion"),
		Labels:       queryList(r, "label"),
		Search:       r.URL.Query().Get("q"),

		ControllerVersions: queryList(r, "controller_version"),
		HostIDs:            queryList(r, "host_id"),
		// Not split on commas, unlike the lists around it: a matrix job's
		// name is "build (ubuntu-latest, 3.12)", and a filter that cut it in
		// two would match nothing while looking like it was working.
		JobNames: nonEmpty(r.URL.Query()["job_name"]),
	}
	var hostedOK bool
	if filter.Hosted, hostedOK = queryStrictBoolPtr(w, r, "hosted"); !hostedOK {
		return filter, false
	}
	for _, raw := range queryList(r, "run_id") {
		id, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || id <= 0 {
			badRequestField(w, "run_id", fmt.Sprintf("%q is not a workflow run ID; GitHub's are whole numbers, the run_id on a job", raw))
			return filter, false
		}
		filter.RunIDs = append(filter.RunIDs, id)
	}
	for _, raw := range queryList(r, "state") {
		st := store.JobState(raw)
		if !st.Valid() {
			badRequestField(w, "state", fmt.Sprintf("%q is not a job state; use waiting, queued, in_progress or completed", raw))
			return filter, false
		}
		filter.States = append(filter.States, st)
	}

	var err error
	if filter.Since, err = queryTime(r, "since"); err != nil {
		badRequestField(w, "since", err.Error())
		return filter, false
	}
	if filter.Until, err = queryTime(r, "until"); err != nil {
		badRequestField(w, "until", err.Error())
		return filter, false
	}
	if unmatched := queryBoolPtr(r, "unmatched"); unmatched != nil {
		filter.UnmatchedOnly = *unmatched
	}
	if managed := queryBoolPtr(r, "managed"); managed != nil {
		filter.ManagedOnly = *managed
	}
	if failed := queryBoolPtr(r, "failed"); failed != nil {
		filter.FailedOnly = *failed
	}
	if faulted := queryBoolPtr(r, "faulted"); faulted != nil {
		filter.FaultedOnly = *faulted
	}
	if workflowFailed := queryBoolPtr(r, "workflow_failed"); workflowFailed != nil {
		filter.WorkflowFailedOnly = *workflowFailed
	}
	// Kept as a pointer rather than flattened to a bool: absent means every
	// job, which is what a history wants, and `cancelling=false` is a
	// different question from not asking at all.
	filter.Cancelling = queryBoolPtr(r, "cancelling")
	if filter.FaultedOnly && filter.WorkflowFailedOnly {
		badRequestField(w, "faulted", "faulted and workflow_failed ask for opposite halves of the same list; send one")
		return filter, false
	}
	for _, raw := range r.URL.Query()["fault"] {
		// Refused rather than ignored. A category this build does not know
		// matches nothing, and a filter that silently returned everything
		// would read as a fleet in better shape than it is.
		kind := store.FaultKind(raw)
		if !kind.Valid() {
			badRequestField(w, "fault", fmt.Sprintf("%q is not a fault category; use one of %s", raw, faultKindList()))
			return filter, false
		}
		filter.FaultKinds = append(filter.FaultKinds, kind)
	}

	for _, v := range filter.Provisioning {
		switch v {
		case "ready", "expedited", "paused", "deleted":
		default:
			badRequestField(w, "provisioning", "use ready, expedited, paused or deleted")
			return filter, false
		}
	}
	if filter.Since != nil && filter.Until != nil && filter.Since.After(*filter.Until) {
		badRequestField(w, "since", "start must be before end")
		return filter, false
	}
	if strings.HasPrefix(r.URL.Path, "/api/v1/provisioning") {
		filter.States = []store.JobState{store.JobQueued}
		filter.ManagedOnly = true
	}
	return filter, true
}

// faultKindList names the categories for an error message, so a 400 tells the
// caller what to send instead of only that what they sent was wrong.
func faultKindList() string {
	kinds := store.FaultKinds()
	names := make([]string, len(kinds))
	for i, k := range kinds {
		names[i] = string(k)
	}
	return strings.Join(names, ", ")
}

// nonEmpty drops the blank values of a repeated parameter.
func nonEmpty(values []string) []string {
	var out []string
	for _, v := range values {
		if v = strings.TrimSpace(v); v != "" {
			out = append(out, v)
		}
	}
	return out
}

// queryStrictBoolPtr is queryBoolPtr for a parameter where a typo should be
// refused rather than read as absent: `hosted=flase` quietly returning every
// job would be taken for an answer about hosted jobs.
func queryStrictBoolPtr(w http.ResponseWriter, r *http.Request, name string) (*bool, bool) {
	raw := strings.TrimSpace(r.URL.Query().Get(name))
	if raw == "" {
		return nil, true
	}
	b, err := strconv.ParseBool(raw)
	if err != nil {
		badRequestField(w, name, fmt.Sprintf("%s must be true or false, not %q", name, raw))
		return nil, false
	}
	return &b, true
}

func queryStrictBool(w http.ResponseWriter, r *http.Request, name string, fallback bool) (bool, bool) {
	v, ok := queryStrictBoolPtr(w, r, name)
	if !ok {
		return false, false
	}
	if v == nil {
		return fallback, true
	}
	return *v, true
}

package api

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// machineResponse is the shape GET /machines returns, rendered by the
// controller so the event stream's machine.updated frames are the same JSON.
type machineResponse = controller.MachineView

// machineTimelineResponse is one phase a machine reached.
type machineTimelineResponse = controller.MachineTimelineEntry

// There is deliberately no POST /machines.
//
// A machine exists because demand asked for one: one creation path means one
// accounting path, and a machine made by hand would be a second source of
// supply that the reconciler -- which decides how many should exist from the
// demand it can see -- would then decide to delete. An operator who wants more
// machines raises the provider's ceiling, and an operator who wants one for
// something else creates it in their hypervisor, where Zoomies will leave it
// alone because it carries none of its marks.

// handleListMachines answers GET /api/v1/machines.
func (s *Server) handleListMachines(w http.ResponseWriter, r *http.Request) {
	filter := store.MachineFilter{
		ProviderIDs:    queryList(r, "provider"),
		PoolIDs:        queryList(r, "pool"),
		HostIDs:        queryList(r, "host"),
		Search:         strings.TrimSpace(r.URL.Query().Get("q")),
		IncludeDeleted: queryBool(r, "include_deleted", false),
	}
	for _, raw := range queryList(r, "state") {
		state := store.MachineState(raw)
		if !state.Valid() {
			badRequestField(w, "state", fmt.Sprintf("%q is not a machine state; use planned, creating, starting, "+
				"bootstrapping, enrolling, ready, draining, deleting, deleted, failed or quarantined", raw))
			return
		}
		filter.States = append(filter.States, state)
	}

	page := parsePage(r)
	machines, total, err := s.ctrl.Store().ListMachines(r.Context(), filter, page)
	if err != nil {
		s.internal(w, r, "listing machines", err)
		return
	}
	view, err := s.ctrl.MachineRenderer(r.Context())
	if err != nil {
		s.internal(w, r, "reading what the machines belong to", err)
		return
	}
	out := make([]machineResponse, 0, len(machines))
	for _, m := range machines {
		out = append(out, view.View(m))
	}
	writeJSON(w, http.StatusOK, newPage(out, total, page))
}

// handleGetMachine answers GET /api/v1/machines/{id}.
func (s *Server) handleGetMachine(w http.ResponseWriter, r *http.Request) {
	m, view, ok := s.machineFor(w, r)
	if !ok {
		return
	}
	writeJSON(w, http.StatusOK, view.View(m))
}

// machineFor reads one machine and the renderer its view needs, answering the
// client itself when either read fails.
func (s *Server) machineFor(w http.ResponseWriter, r *http.Request) (*store.Machine, *controller.MachineRenderer, bool) {
	m, err := s.ctrl.Store().GetMachine(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the machine", err)
		return nil, nil, false
	}
	view, err := s.ctrl.MachineRenderer(r.Context())
	if err != nil {
		s.internal(w, r, "reading what the machine belongs to", err)
		return nil, nil, false
	}
	return m, view, true
}

// cordonMachineHost stops the scheduler placing onto a machine that is on its
// way out, and reports whether the request may go on. A machine with no host
// has nothing to cordon.
func (s *Server) cordonMachineHost(w http.ResponseWriter, r *http.Request, m *store.Machine) bool {
	if m.HostID == "" {
		return true
	}
	if err := s.ctrl.Store().SetHostCordoned(r.Context(), m.HostID, true); err != nil {
		s.fail(w, r, "cordoning the machine's host", err)
		return false
	}
	if h, err := s.ctrl.Store().GetHost(r.Context(), m.HostID); err == nil {
		s.ctrl.PublishHost(h)
	}
	return true
}

// handleDrainMachine answers POST /api/v1/machines/{id}/drain.
//
// Draining is reversible right up until the delete starts: demand coming back
// takes a draining machine to ready again rather than paying for a new one.
// The host is cordoned in the same breath, because a machine on its way out
// that kept accepting runners would never empty.
func (s *Server) handleDrainMachine(w http.ResponseWriter, r *http.Request) {
	m, _, ok := s.machineFor(w, r)
	if !ok {
		return
	}
	// The transition is checked before the cordon: a refused drain (only a ready
	// machine can drain) must not leave the host of a failed or deleting machine
	// cordoned by a request that answered 409 and wrote no audit row.
	if !store.CanTransitionMachine(m.State, store.MachineDraining) {
		s.fail(w, r, "draining the machine", fmt.Errorf("%w: machine %s cannot go %s -> %s",
			store.ErrInvalidTransition, m.ID, m.State, store.MachineDraining))
		return
	}
	if !s.cordonMachineHost(w, r, m) {
		return
	}
	out, err := s.ctrl.Store().TransitionMachine(r.Context(), m.ID, store.MachineDraining,
		"an operator asked for this machine to be drained")
	if err != nil {
		s.fail(w, r, "draining the machine", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "machine.drain", "machine", m.ID, map[string]any{
		"name": m.Name, "was": m.State, "host_id": m.HostID,
	})
	s.publishMachine(r, out)
	writeJSON(w, http.StatusOK, s.machineView(r, out))
}

// handleDeleteMachine answers DELETE /api/v1/machines/{id}.
//
// It records the intent and lets the machine loop carry it out, because a
// delete is not finished when the provider returns: it is finished when an
// inspect can no longer find the resource. So this answers with the machine in
// deleting rather than with 204, and the page watches it reach deleted.
func (s *Server) handleDeleteMachine(w http.ResponseWriter, r *http.Request) {
	m, _, ok := s.machineFor(w, r)
	if !ok {
		return
	}
	force := queryBool(r, "force", false)

	// A quarantined machine is never deleted from here, forced or not. Its
	// ownership could not be proved, so the resource behind it may belong to
	// another fleet, and a delete would destroy somebody else's machine. The
	// escape hatch is release, which touches nothing.
	if m.State == store.MachineQuarantined {
		conflict(w, fmt.Sprintf("machine %s is quarantined: nothing has been able to prove the resource behind it is ours, "+
			"so deleting it could destroy a machine belonging to somebody else. Look at %s in the provider yourself. "+
			"If it is ours, remove it there; if it is not, POST /api/v1/machines/%s/release to forget this row, which touches no resource.",
			m.Name, resourceLabel(m), m.ID))
		return
	}
	if m.HostID != "" && !force {
		runners, err := s.ctrl.Store().ListRunnersForHost(r.Context(), m.HostID)
		if err != nil {
			s.internal(w, r, "listing the machine's runners", err)
			return
		}
		alive := 0
		for _, run := range runners {
			if !run.State.Terminal() {
				alive++
			}
		}
		if alive > 0 {
			conflict(w, fmt.Sprintf("machine %s is still running %s, and deleting it destroys the VM they are running on. "+
				"Drain it and call this again when they have finished, or repeat this with ?force=true to delete it now and lose that work.",
				m.Name, runnerCount(alive)))
			return
		}
	}

	// Cordoned on the way to deleting, as every other road there does
	// (beginDrain, quarantine, a vanished VM): the scheduler's snapshot carries
	// hosts and never machines, so without it the host stays placeable for the
	// whole delete and a runner placed in that window dies with the VM. The
	// forced path cordons too -- the host is going either way. It comes after
	// the refusals above so that a delete that says no changes nothing.
	if store.CanTransitionMachine(m.State, store.MachineDeleting) && !s.cordonMachineHost(w, r, m) {
		return
	}
	out, err := s.ctrl.Store().TransitionMachine(r.Context(), m.ID, store.MachineDeleting,
		"an operator asked for this machine to be deleted")
	if err != nil {
		s.fail(w, r, "deleting the machine", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "machine.delete", "machine", m.ID, map[string]any{
		"name": m.Name, "was": m.State, "forced": force,
		"resource_zone": m.ResourceZone, "resource_id": m.ResourceID,
	})
	s.publishMachine(r, out)
	writeJSON(w, http.StatusOK, s.machineView(r, out))
}

// releaseMachineRequest asks for the machine's name to be typed, which is the
// one guard on an act that cannot be undone.
type releaseMachineRequest struct {
	Name string `json:"name"`
}

// handleReleaseMachine answers POST /api/v1/machines/{id}/release: forget this
// row and touch nothing.
//
// It exists for the machine nobody can safely delete -- a quarantined one whose
// resource turned out to belong to somebody else, or a row for a resource that
// was removed in the hypervisor by hand. What it costs is exactly what it says:
// if the resource does still exist, it goes on running and stops being anything
// Zoomies knows about, so the audit row keeps the provider's own identifiers
// for it after the database has stopped holding them.
func (s *Server) handleReleaseMachine(w http.ResponseWriter, r *http.Request) {
	m, _, ok := s.machineFor(w, r)
	if !ok {
		return
	}
	var req releaseMachineRequest
	if !decode(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Name) != m.Name {
		unprocessable(w, fmt.Sprintf("releasing a machine forgets it without deleting anything, and it cannot be undone: "+
			"send the machine's name, %s, to confirm that is what you mean", m.Name),
			[]fieldError{{"name", fmt.Sprintf("type %s to confirm", m.Name)}})
		return
	}
	if err := s.ctrl.Store().ForgetMachine(r.Context(), m.ID); err != nil {
		s.fail(w, r, "releasing the machine", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "machine.release", "machine", m.ID, map[string]any{
		"name": m.Name, "state": m.State, "provider_id": m.ProviderID,
		"resource_zone": m.ResourceZone, "resource_id": m.ResourceID,
		"address": m.Address, "host_id": m.HostID,
	})
	s.ctrl.PublishMachineDeleted(m.ID)
	noContent(w)
}

// publishMachine announces a machine change and asks the machine loop to look
// again, which is what turns "deleting" into a delete rather than a state a row
// sits in until the next interval.
func (s *Server) publishMachine(r *http.Request, m *store.Machine) {
	s.ctrl.PublishMachine(r.Context(), m)
	s.ctrl.NudgeMachines()
}

// machineView renders one machine, falling back to what can be rendered
// without the lookups when they fail: a write that succeeded must not answer as
// though it had not.
func (s *Server) machineView(r *http.Request, m *store.Machine) machineResponse {
	view, err := s.ctrl.MachineRenderer(r.Context())
	if err != nil {
		s.logger(r).Warn("could not render a machine's provider, pool and host names", "machine", m.ID, "error", err)
		return controller.MachineView{ID: m.ID, ProviderID: m.ProviderID, Name: m.Name, State: m.State}
	}
	return view.View(m)
}

// resourceLabel names the resource behind a machine the way its provider does,
// so an operator can paste it into their own console.
func resourceLabel(m *store.Machine) string {
	switch {
	case m.ResourceZone != "" && m.ResourceID != "":
		return m.ResourceZone + "/" + m.ResourceID
	case m.ResourceID != "":
		return m.ResourceID
	}
	return m.Name
}

package api

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// OAuth for /mcp: the discovery documents, the four OAuth endpoints, and the
// REST routes the consent screen and the settings pages use. The decisions --
// what a redirect may be, whether a code is spent, what a role may be -- are
// internal/auth's; this file reads requests and writes the shapes the
// specifications promise.

// consentPath is the UI page an authorisation request is decided on.
const consentPath = "/oauth/consent"

// publicBase is the controller's public origin: the external URL when the
// operator set one, and otherwise the scheme and host this request arrived
// on. The validator raises mcp_oauth.enabled with a sentence about setting the
// external URL, because a Host header is the client's to choose.
func (s *Server) publicBase(r *http.Request) string {
	if ext := strings.TrimRight(strings.TrimSpace(s.cfg().Server.ExternalURL), "/"); ext != "" {
		if u, err := url.Parse(ext); err == nil && u.Host != "" {
			return strings.ToLower(u.Scheme) + "://" + strings.ToLower(u.Host)
		}
	}
	return s.requestScheme(r) + "://" + strings.ToLower(r.Host)
}

func (s *Server) oauthPolicy(r *http.Request) auth.OAuthPolicy {
	c := s.cfg()
	return auth.OAuthPolicy{
		Issuer:             s.publicBase(r),
		OpenRegistration:   c.Security.MCPOpenRegistration,
		AllowPrivateEgress: c.Security.AllowPrivateEgress,
	}
}

// mcpOAuth guards every OAuth route: with the setting off they are not here
// at all, which is what a client probing for them should find.
func (s *Server) mcpOAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if !s.cfg().MCPOAuthEnabled() {
			if isAPIPath(r.URL.Path) {
				notFound(w, "OAuth sign-in for MCP is off on this controller (security.mcp_oauth); use an API token on /mcp instead")
				return
			}
			http.NotFound(w, r)
			return
		}
		next(w, r)
	}
}

// resourceMetadataURL is where /mcp's 401 points a client.
func (s *Server) resourceMetadataURL(r *http.Request) string {
	return s.publicBase(r) + "/.well-known/oauth-protected-resource/mcp"
}

// mcpChallenge is the WWW-Authenticate header /mcp answers a missing or bad
// credential with. With OAuth on it is the one RFC 9728 describes, naming the
// metadata and the scopes, and it is what starts Claude's sign-in.
func (s *Server) mcpChallenge(r *http.Request, errCode string) string {
	if !s.cfg().MCPOAuthEnabled() {
		return `Bearer realm="zoomies"`
	}
	h := `Bearer resource_metadata="` + s.resourceMetadataURL(r) + `", scope="` + strings.Join(auth.MCPScopes, " ") + `"`
	if errCode != "" {
		h += `, error="` + errCode + `"`
	}
	return h
}

// metadataJSON writes a public discovery document. Anybody may read it --
// that is its purpose -- including a browser-based client on another origin.
func metadataJSON(w http.ResponseWriter, v any) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Cache-Control", "public, max-age=300")
	writeJSON(w, http.StatusOK, v)
}

// handleProtectedResource is RFC 9728 protected resource metadata for /mcp,
// served both at the root well-known address and at the one with /mcp
// appended, which a client tries first.
func (s *Server) handleProtectedResource(w http.ResponseWriter, r *http.Request) {
	p := s.oauthPolicy(r)
	metadataJSON(w, map[string]any{
		"resource":                 p.Resource(),
		"authorization_servers":    []string{p.Issuer},
		"scopes_supported":         auth.MCPScopes,
		"bearer_methods_supported": []string{"header"},
		"resource_name":            "Zoomies",
		"resource_documentation":   "https://zoomies.sh/connect-claude/",
	})
}

// handleAuthorizationServer is RFC 8414 authorisation server metadata.
//
// There is no OpenID Connect discovery document beside it. This server issues
// no ID tokens and publishes no signing keys, and a document at
// /.well-known/openid-configuration would tell a client it could expect both;
// the MCP specification asks for one discovery mechanism, and a client tries
// this one first.
func (s *Server) handleAuthorizationServer(w http.ResponseWriter, r *http.Request) {
	p := s.oauthPolicy(r)
	doc := map[string]any{
		"issuer":                                         p.Issuer,
		"authorization_endpoint":                         p.Issuer + "/oauth/authorize",
		"token_endpoint":                                 p.Issuer + "/oauth/token",
		"revocation_endpoint":                            p.Issuer + "/oauth/revoke",
		"response_types_supported":                       []string{"code"},
		"response_modes_supported":                       []string{"query"},
		"grant_types_supported":                          []string{"authorization_code", "refresh_token"},
		"code_challenge_methods_supported":               []string{"S256"},
		"token_endpoint_auth_methods_supported":          []string{"none", "client_secret_basic", "client_secret_post"},
		"revocation_endpoint_auth_methods_supported":     []string{"none", "client_secret_basic", "client_secret_post"},
		"scopes_supported":                               append(append([]string{}, auth.MCPScopes...), "offline_access"),
		"authorization_response_iss_parameter_supported": true,
		"client_id_metadata_document_supported":          p.OpenRegistration,
		"service_documentation":                          "https://zoomies.sh/connect-claude/",
	}
	if p.OpenRegistration {
		doc["registration_endpoint"] = p.Issuer + "/oauth/register"
	}
	metadataJSON(w, doc)
}

// oauthError writes an RFC 6749 error body. These endpoints speak OAuth's
// vocabulary rather than this API's envelope, because the client reading them
// is an OAuth library.
func oauthError(w http.ResponseWriter, e *auth.OAuthError, basic bool) {
	w.Header().Set("Cache-Control", "no-store")
	if e.Status == http.StatusUnauthorized && basic {
		w.Header().Set("WWW-Authenticate", `Basic realm="zoomies"`)
	}
	if e.Status == http.StatusTooManyRequests {
		w.Header().Set("Retry-After", "60")
	}
	writeJSON(w, e.Status, map[string]string{"error": e.Code, "error_description": e.Description})
}

func (s *Server) oauthFail(w http.ResponseWriter, r *http.Request, doing string, err error, basic bool) {
	var oe *auth.OAuthError
	if errors.As(err, &oe) {
		oauthError(w, oe, basic)
		return
	}
	// Nothing derived from the error is logged: these requests carry a client
	// secret and a code or refresh token, and an error that ever quoted one
	// would put a live credential in the log. The request ID, which the
	// request logger already carries, ties the 500 to the audit trail.
	s.logger(r).Error("an OAuth request failed", "doing", doing)
	oauthError(w, &auth.OAuthError{Code: "server_error", Status: http.StatusInternalServerError,
		Description: "something went wrong while " + doing + "; request " + RequestID(r.Context())}, basic)
}

// handleRegister is RFC 7591 dynamic client registration.
func (s *Server) handleRegister(w http.ResponseWriter, r *http.Request) {
	var in auth.ClientRegistration
	body, err := io.ReadAll(io.LimitReader(r.Body, 16<<10))
	if err != nil || json.Unmarshal(body, &in) != nil {
		oauthError(w, &auth.OAuthError{Code: "invalid_client_metadata", Status: http.StatusBadRequest,
			Description: "the registration request is not a JSON object"}, false)
		return
	}
	c, err := s.auth.RegisterClient(r.Context(), s.oauthPolicy(r), in, ClientIP(r.Context()))
	if err != nil {
		s.oauthFail(w, r, "registering a client", err, false)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	writeJSON(w, http.StatusCreated, map[string]any{
		"client_id":                  c.ClientID,
		"client_id_issued_at":        c.CreatedAt.Unix(),
		"client_name":                c.Name,
		"redirect_uris":              []string(c.RedirectURIs),
		"grant_types":                []string{"authorization_code", "refresh_token"},
		"response_types":             []string{"code"},
		"token_endpoint_auth_method": "none",
		"scope":                      strings.Join(auth.MCPScopes, " "),
	})
}

// handleAuthorize is the authorisation endpoint. It checks the request, keeps
// it, and sends the browser to the consent page -- which shows the sign-in
// form first when nobody is signed in, and comes back to the same address.
func (s *Server) handleAuthorize(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	p := s.oauthPolicy(r)
	req, err := s.auth.BeginAuthorization(r.Context(), p, auth.AuthorizeParams{
		ClientID:            q.Get("client_id"),
		RedirectURI:         q.Get("redirect_uri"),
		ResponseType:        q.Get("response_type"),
		CodeChallenge:       q.Get("code_challenge"),
		CodeChallengeMethod: q.Get("code_challenge_method"),
		State:               q.Get("state"),
		Scope:               q.Get("scope"),
		Resource:            q.Get("resource"),
	})
	var refusal *auth.AuthorizeRefusal
	switch {
	case errors.As(err, &refusal) && refusal.RedirectURI != "":
		http.Redirect(w, r, auth.ErrorRedirect(p, refusal.RedirectURI, refusal.State, refusal.Code, refusal.Description), http.StatusFound)
	case errors.As(err, &refusal):
		// The client or its redirect could not be trusted, so the person is
		// told here rather than sent anywhere. Only the code travels: the page
		// renders its own sentence for it, because text read from the address
		// is text anybody can write into a link that opens on this controller.
		// The specific reason goes to the log, for whoever the person asks --
		// at debug, like every other request line, and cut short, because it
		// quotes a client_id and redirect_uri anybody can make as long as a
		// URL, on an endpoint nobody has to sign in to reach.
		s.logger(r).Debug("refused an MCP sign-in on the consent page", "error", refusal.Code, "reason", truncateForLog(refusal.Description, 200))
		http.Redirect(w, r, consentPath+"?"+url.Values{"error": {refusal.Code}}.Encode(), http.StatusFound)
	case err != nil:
		s.internal(w, r, "starting an MCP sign-in", err)
	default:
		http.Redirect(w, r, consentPath+"?"+url.Values{"request": {req.ID}}.Encode(), http.StatusFound)
	}
}

// clientCredentials reads how a client identified itself: HTTP Basic with the
// form-encoded ID and secret RFC 6749 section 2.3.1 describes, or form fields.
// Both at once is refused, as the RFC asks.
func clientCredentials(r *http.Request) (auth.ClientCredentials, *auth.OAuthError) {
	cc := auth.ClientCredentials{ClientID: r.PostForm.Get("client_id"), Secret: r.PostForm.Get("client_secret")}
	h := r.Header.Get("Authorization")
	scheme, value, ok := strings.Cut(strings.TrimSpace(h), " ")
	if !ok || !strings.EqualFold(scheme, "basic") {
		return cc, nil
	}
	if cc.Secret != "" {
		return cc, &auth.OAuthError{Code: "invalid_request", Status: http.StatusBadRequest,
			Description: "send the client secret one way, not in both the Authorization header and the form"}
	}
	raw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(value))
	id, secret, found := strings.Cut(string(raw), ":")
	if err != nil || !found {
		return cc, &auth.OAuthError{Code: "invalid_client", Status: http.StatusUnauthorized, Description: "the Basic credentials are not client_id:client_secret"}
	}
	id, err1 := url.QueryUnescape(id)
	secret, err2 := url.QueryUnescape(secret)
	if err1 != nil || err2 != nil {
		return cc, &auth.OAuthError{Code: "invalid_client", Status: http.StatusUnauthorized, Description: "the Basic credentials are not form-encoded"}
	}
	if cc.ClientID != "" && cc.ClientID != id {
		return cc, &auth.OAuthError{Code: "invalid_request", Status: http.StatusBadRequest, Description: "client_id in the form is not the one in the Authorization header"}
	}
	return auth.ClientCredentials{ClientID: id, Secret: secret, Basic: true}, nil
}

func parseOAuthForm(w http.ResponseWriter, r *http.Request) bool {
	ct := r.Header.Get("Content-Type")
	if !strings.HasPrefix(strings.ToLower(strings.TrimSpace(ct)), "application/x-www-form-urlencoded") {
		oauthError(w, &auth.OAuthError{Code: "invalid_request", Status: http.StatusBadRequest,
			Description: "send the request as application/x-www-form-urlencoded, as RFC 6749 asks"}, false)
		return false
	}
	r.Body = http.MaxBytesReader(w, r.Body, 64<<10)
	if err := r.ParseForm(); err != nil {
		oauthError(w, &auth.OAuthError{Code: "invalid_request", Status: http.StatusBadRequest, Description: "the form could not be read"}, false)
		return false
	}
	return true
}

// handleToken is the token endpoint: a code or a refresh token in, a fresh
// access and refresh pair out.
func (s *Server) handleToken(w http.ResponseWriter, r *http.Request) {
	if !parseOAuthForm(w, r) {
		return
	}
	cc, cerr := clientCredentials(r)
	if cerr != nil {
		oauthError(w, cerr, cc.Basic)
		return
	}
	f := r.PostForm
	resp, err := s.auth.Token(r.Context(), s.oauthPolicy(r), cc, auth.TokenRequest{
		GrantType:    f.Get("grant_type"),
		Code:         f.Get("code"),
		RedirectURI:  f.Get("redirect_uri"),
		CodeVerifier: f.Get("code_verifier"),
		RefreshToken: f.Get("refresh_token"),
		Resource:     f.Get("resource"),
		Scope:        f.Get("scope"),
	}, ClientIP(r.Context()))
	if err != nil {
		s.oauthFail(w, r, "issuing a token", err, cc.Basic)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Pragma", "no-cache")
	writeJSON(w, http.StatusOK, resp)
}

// handleRevoke is RFC 7009 token revocation.
func (s *Server) handleRevoke(w http.ResponseWriter, r *http.Request) {
	if !parseOAuthForm(w, r) {
		return
	}
	cc, cerr := clientCredentials(r)
	if cerr != nil {
		oauthError(w, cerr, cc.Basic)
		return
	}
	token := r.PostForm.Get("token")
	if token == "" {
		oauthError(w, &auth.OAuthError{Code: "invalid_request", Status: http.StatusBadRequest, Description: "the request names no token"}, cc.Basic)
		return
	}
	if err := s.auth.RevokeToken(r.Context(), s.oauthPolicy(r), cc, token, ClientIP(r.Context())); err != nil {
		s.oauthFail(w, r, "revoking a token", err, cc.Basic)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(http.StatusOK)
}

