func (s *Server) handleDenyMCPRequest(w http.ResponseWriter, r *http.Request) {
	d, err := s.auth.DenyAuthorization(r.Context(), s.oauthPolicy(r), Identity(r.Context()), chiURLParam(r, "id"))
	if err != nil {
