)

func (s *Server) handleProvisioningSelection(w http.ResponseWriter, r *http.Request) {
	filter, ok := parseJobFilter(w, r)
	if !ok {
		return
	}
	ids, err := s.ctrl.Store().ProvisioningSelection(r.Context(), filter)
	if err != nil {
		if errors.Is(err, store.ErrProvisioningSelectionTooLarge) {
			badRequest(w, err.Error())
		} else {
			s.internal(w, r, "selecting provisioning items", err)
		}
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ids": ids})
}

func (s *Server) handleControlProvisioning(w http.ResponseWriter, r *http.Request) {
	var req struct {
		IDs    []string `json:"ids"`
		Action string   `json:"action"`
	}
	if !decode(w, r, &req) {
		return
	}
	switch req.Action {
	case "pause", "resume", "delete", "run_now":
	default:
		badRequestField(w, "action", "use pause, resume, delete or run_now")
		return
	}
	if len(req.IDs) == 0 || len(req.IDs) > store.MaxProvisioningSelection {
		badRequestField(w, "ids", "select between 1 and 5000 items")
		return
	}
	results, err := s.ctrl.ControlProvisioning(r.Context(), req.IDs, req.Action)
	if err != nil {
		s.internal(w, r, "updating provisioning", err)
		return
	}
	for _, result := range results {
		if result.OK {
			s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "provisioning."+req.Action, "job", result.ID, nil)
		}
	}
	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

type controlWorkflowRunProvisioningRequest struct {
	Repo   string `json:"repo"`
	RunID  int64  `json:"run_id"`
	Action string `json:"action"`
}

// handleControlWorkflowRunProvisioning answers POST /api/v1/workflow-runs/provisioning:
// the Workflows page's own run rows pausing, resuming or expediting every
// queued job of a run at once, rather than opening the run and pressing the
// same button on each job inside. Delete is deliberately not offered here: a
// removal is a decision about one job, taken on the Queue page where the
// Removed view can undo it.
func (s *Server) handleControlWorkflowRunProvisioning(w http.ResponseWriter, r *http.Request) {
	var req controlWorkflowRunProvisioningRequest
	if !decode(w, r, &req) {
		return
	}
	if req.Repo == "" {
		badRequestField(w, "repo", "repo is required")
		return
	}
	if req.RunID <= 0 {
		badRequestField(w, "run_id", "run_id must be a positive GitHub run ID")
		return
	}
	switch req.Action {
	case "pause", "resume", "run_now":
	default:
		badRequestField(w, "action", "use pause, resume or run_now; a job is removed from the queue one at a time, through /provisioning/bulk")
		return
	}
	results, err := s.ctrl.ControlWorkflowRunProvisioning(r.Context(), req.Repo, req.RunID, req.Action)
	if err != nil {
		switch {
		case errors.Is(err, controller.ErrRunHasNoQueuedJobs):
			conflict(w, err.Error()+"; every job of it has started or finished, or was removed from the queue and is restored from the Queue page's Removed view")
		default:
			s.fail(w, r, "updating the workflow run's provisioning", err)
		}
		return
	}
	target := fmt.Sprintf("%s#%d", req.Repo, req.RunID)
	for _, result := range results {
		if result.OK {
			s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "provisioning."+req.Action, "job", result.ID, map[string]any{
				"repo": req.Repo, "run_id": req.RunID, "workflow_run": target,
			})
		}
	}
	writeJSON(w, http.StatusOK, map[string]any{"results": results, "repo": req.Repo, "run_id": req.RunID})
}

package api

import (
	"net/http"

	"github.com/eyupio/zoomies/internal/controller"
)

// recoveryResponse is the fence's state.
//
// It is the response to lifting it as well as to reading it, so a client that
// lifted the fence knows what it now is rather than having to ask again.
type recoveryResponse struct {
	Fenced bool   `json:"fenced"`
	Reason string `json:"reason,omitempty"`
}

func newRecoveryResponse(f controller.Fence) recoveryResponse {
	return recoveryResponse{Fenced: f.Fenced, Reason: f.Reason}
}

// handleGetRecovery answers GET /api/v1/recovery.
func (s *Server) handleGetRecovery(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, newRecoveryResponse(s.ctrl.Fenced()))
}

// handleUnfence answers POST /api/v1/recovery/unfence.
//
// It is a person saying that a recovered fleet has been checked and may act on
// the world again, which is why it is audited under its own action rather than
// folded into the settings route: the audit log is where somebody later asks
// who decided that, and when.
func (s *Server) handleUnfence(w http.ResponseWriter, r *http.Request) {
	before := s.ctrl.Fenced()
	if !before.Fenced {
		// Not an error. Two operators recovering one fleet will both press it,
		// and the second must not be told something went wrong.
		writeJSON(w, http.StatusOK, newRecoveryResponse(before))
		return
	}
	if err := s.ctrl.Unfence(r.Context()); err != nil {
		s.internal(w, r, "lifting the recovery fence", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "recovery.unfence", "instance", "", map[string]any{
		"was_fenced_because": before.Reason,
	})
	writeJSON(w, http.StatusOK, newRecoveryResponse(s.ctrl.Fenced()))
}

package api

import (
	"fmt"
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/store"
)

// runnerResponse is the shape GET /runners returns, rendered by the controller
// so the event stream's runner.* frames are the same JSON. See
// controller/views.go for why the renderer lives there.
type runnerResponse = controller.RunnerView

// runnerDetailResponse adds what the detail page shows and a list would not:
// the host and pool in full, the state history, and whether logs can be had at
// all -- so the log pane can say why it is empty instead of just being empty.
type runnerDetailResponse struct {
	controller.RunnerView
	Host          *hostResponse   `json:"host,omitempty"`
	Pool          *poolResponse   `json:"pool,omitempty"`
	Timeline      []timelineEntry `json:"timeline"`
	LogsAvailable bool            `json:"logs_available"`
}

// timelineEntry is one step of a runner's life.
type timelineEntry struct {
	State      store.RunnerState `json:"state"`
	Stage      string            `json:"stage,omitempty"`
	At         time.Time         `json:"at"`
	DurationMS int64             `json:"duration_ms"`
	Message    string            `json:"message,omitempty"`
}

// handleListRunners answers GET /api/v1/runners.
func (s *Server) handleListRunners(w http.ResponseWriter, r *http.Request) {
	filter := store.RunnerFilter{
		PoolIDs:        queryList(r, "pool_id"),
		HostIDs:        queryList(r, "host_id"),
		Search:         r.URL.Query().Get("q"),
		IncludeRemoved: queryBool(r, "include_removed", false),
	}
	for _, raw := range queryList(r, "state") {
		st := store.RunnerState(raw)
		if !st.Valid() {
			badRequestField(w, "state", fmt.Sprintf("%q is not a runner state; use provisioning, registering, idle, busy, draining, removed or failed", raw))
			return
		}
		filter.States = append(filter.States, st)
	}

	p := parsePage(r)
	runners, total, err := s.ctrl.Store().ListRunners(r.Context(), filter, p)
	if err != nil {
		s.internal(w, r, "listing runners", err)
		return
	}
	view, err := s.ctrl.RunnerRenderer(r.Context(), runners)
	if err != nil {
		s.internal(w, r, "listing runners", err)
		return
	}
	out := make([]runnerResponse, 0, len(runners))
	for _, run := range runners {
		out = append(out, view.View(run))
	}
	writeJSON(w, http.StatusOK, newPage(out, total, p))
}

// handleGetRunner answers GET /api/v1/runners/{id}.
func (s *Server) handleGetRunner(w http.ResponseWriter, r *http.Request) {
	run, err := s.ctrl.Store().GetRunner(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the runner", err)
		return
	}
	view, err := s.ctrl.RunnerRenderer(r.Context(), []*store.Runner{run})
	if err != nil {
		s.internal(w, r, "reading the runner", err)
		return
	}
	detail := runnerDetailResponse{
		RunnerView: view.View(run),
		Timeline:   runnerTimeline(run, s.ctrl.Now()),
	}

	if host, herr := s.ctrl.Store().GetHost(r.Context(), run.HostID); herr == nil {
		h := s.ctrl.HostView(host)
		detail.Host = &h
		// Logs come from the runner's own agent, so a host that is not
		// checking in cannot produce them and a removed runner no longer has a
		// container to read.
		detail.LogsAvailable = host.Healthy(s.ctrl.Now()) && run.State != store.RunnerRemoved
	}
	if pool, perr := s.ctrl.Store().GetPool(r.Context(), run.PoolID); perr == nil {
		if pv, verr := s.ctrl.PoolRenderer(r.Context()); verr == nil {
			p := poolFor(r, pv.View(pool))
			detail.Pool = &p
		}
	}
	writeJSON(w, http.StatusOK, detail)
}

// handleRunnerTimeline answers GET /api/v1/runners/{id}/timeline.
func (s *Server) handleRunnerTimeline(w http.ResponseWriter, r *http.Request) {
	run, err := s.ctrl.Store().GetRunner(r.Context(), chiURLParam(r, "id"))
	if err != nil {
		s.fail(w, r, "reading the runner", err)
		return
	}
	writeJSON(w, http.StatusOK, newList(runnerTimeline(run, s.ctrl.Now())))
}

// runnerTimeline reconstructs a runner's life from the timestamps its row
// carries.
//
// There is no per-transition history table, deliberately: a busy fleet would
// write millions of rows to answer a question the four stamped timestamps
// already answer. What this cannot show is a runner that went idle, busy and
// idle again -- only the most recent of those is recorded -- so it is a summary
// of the runner's life rather than an audit trail of it, and the audit log is
// where the actions people took are kept.
func runnerTimeline(r *store.Runner, now time.Time) []timelineEntry {
	entries := []timelineEntry{{
		State:   store.RunnerProvisioning,
		At:      r.CreatedAt,
		Message: "the controller asked an agent to create this runner",
	}}
	if r.ImagePullDuration != nil && r.ContainerStartedAt != nil {
		at := r.ContainerStartedAt.Add(-*r.ImagePullDuration)
		if !at.Before(r.CreatedAt) {
			entries = append(entries, timelineEntry{State: store.RunnerProvisioning, Stage: "image_pulling", At: at, Message: "pulling the runner image"})
		}
	}
	if r.ContainerStartedAt != nil {
		entries = append(entries, timelineEntry{State: store.RunnerRegistering, Stage: "container_started", At: *r.ContainerStartedAt, Message: "the runner container started"})
	}
	if r.RegisteredAt != nil {
		entries = append(entries, timelineEntry{State: store.RunnerRegistering, Stage: "registered", At: *r.RegisteredAt, Message: "registered with GitHub"})
	}
	if r.StartedAt != nil {
		entries = append(entries, timelineEntry{
			State:   store.RunnerRegistering,
			At:      *r.StartedAt,
			Message: "the workload came up and registered with GitHub",
		})
	}
	if r.LastIdleAt != nil && (r.StartedAt == nil || r.LastIdleAt.After(*r.StartedAt)) {
		entries = append(entries, timelineEntry{
			State:   store.RunnerIdle,
			At:      *r.LastIdleAt,
			Message: "waiting for a job",
		})
	}
	if r.FinishedAt != nil {
		entries = append(entries, timelineEntry{
			State:   r.State,
			At:      *r.FinishedAt,
			Message: r.Message,
		})
	} else {
		entries = append(entries, timelineEntry{
			State:   r.State,
			At:      latest(r.CreatedAt, r.StartedAt, r.LastIdleAt),
			Message: r.Message,
		})
	}

	// Each entry lasts until the next one; the last one is still running,
	// unless the runner has finished, in which case it is over.
	for i := range entries {
		var until time.Time
		switch {
		case i+1 < len(entries):
			until = entries[i+1].At
		case r.FinishedAt != nil:
			until = *r.FinishedAt
		default:
			until = now
		}
		entries[i].DurationMS = millis(until.Sub(entries[i].At))
	}
	return entries
}

func latest(base time.Time, others ...*time.Time) time.Time {
	out := base
	for _, t := range others {
		if t != nil && t.After(out) {
			out = *t
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Acting on runners
// ---------------------------------------------------------------------------

// handleDrainRunner asks a runner to finish its current job and exit.
//
// It answers 202 rather than 200: the runner has been told, and it stops when
// its job does. A runner that is already terminal is a 409, because "drain a
// removed runner" is a request the fleet cannot honour and quietly succeeding
// would leave the operator believing something happened.
func (s *Server) handleDrainRunner(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	run, err := s.ctrl.DrainRunner(r.Context(), id, drainReason(r), queryBool(r, "confirm", false))
	if err != nil {
		s.fail(w, r, "draining the runner", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "runner.drain", "runner", id, map[string]any{
		"name": run.Name, "state": run.State, "pool_id": run.PoolID,
	})
	s.ctrl.Nudge()

	view, verr := s.ctrl.RunnerRenderer(r.Context(), []*store.Runner{run})
	if verr != nil {
		s.internal(w, r, "reading the runner back", verr)
		return
	}
	writeJSON(w, http.StatusAccepted, view.View(run))
}

// handleDeleteRunner removes a runner, draining first unless forced.
func (s *Server) handleDeleteRunner(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	force := queryBool(r, "force", false)
	run, err := s.ctrl.RemoveRunner(r.Context(), id, drainReason(r), force, queryBool(r, "confirm", false))
	if err != nil {
		s.fail(w, r, "removing the runner", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "runner.delete", "runner", id, map[string]any{
		"name": run.Name, "state": run.State, "pool_id": run.PoolID, "force": force,
	})
	s.ctrl.Nudge()
	w.WriteHeader(http.StatusAccepted)
}

// drainReason names who asked, so the runner's message and the audit row agree.
func drainReason(r *http.Request) string {
	id := Identity(r.Context())
	if id == nil || id.Name == "" {
		return "requested through the API"
	}
	return "requested by " + id.Name
}

type bulkRunnerRequest struct {
	Action string   `json:"action"`
	IDs    []string `json:"ids"`
	Force  bool     `json:"force"`
	// Confirm is the operator accepting that a runner in this batch which is
	// running a job will lose it. Without it a busy runner comes back as its own
	// failed row rather than failing the batch, which is how this endpoint
	// reports everything else.
	Confirm bool `json:"confirm"`
}

type bulkRunnerResult struct {
	ID    string `json:"id"`
	OK    bool   `json:"ok"`
	Error string `json:"error,omitempty"`
}

type bulkRunnerResponse struct {
	Results []bulkRunnerResult `json:"results"`
}

// handleBulkRunners drains or deletes several runners at once.
//
// It answers 200 with a result per ID rather than a single status: selecting
// forty runners and being told only that "something failed" is not an answer
// anyone can act on, and a partial failure here is normal -- one of the forty
// finished its job a second before the request arrived.
func (s *Server) handleBulkRunners(w http.ResponseWriter, r *http.Request) {
	var req bulkRunnerRequest
	if !decode(w, r, &req) {
		return
	}

	var fields []fieldError
	switch req.Action {
	case "drain", "delete":
	case "":
		fields = append(fields, fieldError{"action", "say what to do with these runners: drain or delete"})
	default:
		fields = append(fields, fieldError{"action", fmt.Sprintf("%q is not an action; use drain or delete", req.Action)})
	}
	switch {
	case len(req.IDs) == 0:
		fields = append(fields, fieldError{"ids", "no runners were selected"})
	case len(req.IDs) > 500:
		fields = append(fields, fieldError{"ids", fmt.Sprintf("%d runners is more than the 500 this endpoint accepts at once; do it in batches", len(req.IDs))})
	}
	if len(fields) > 0 {
		unprocessable(w, "this bulk action could not be carried out", fields)
		return
	}

	// Deleting is the stronger action, so a caller allowed only to drain must
	// not reach it through the bulk endpoint. The route gate checks the weaker
	// one; this is the other half of that.
	id := Identity(r.Context())
	if req.Action == "delete" && !auth.Allowed(id, auth.ActionRunnersDelete) {
		forbidden(w, auth.Explain(id, auth.ActionRunnersDelete))
		return
	}

	results := make([]bulkRunnerResult, 0, len(req.IDs))
	changed := 0
	for _, runnerID := range req.IDs {
		var err error
		var run *store.Runner
		if req.Action == "drain" {
			run, err = s.ctrl.DrainRunner(r.Context(), runnerID, drainReason(r), req.Confirm)
		} else {
			run, err = s.ctrl.RemoveRunner(r.Context(), runnerID, drainReason(r), req.Force, req.Confirm)
		}
		if err != nil {
			results = append(results, bulkRunnerResult{ID: runnerID, Error: err.Error()})
			continue
		}
		changed++
		results = append(results, bulkRunnerResult{ID: runnerID, OK: true})
		s.auth.Auditor().Act(r.Context(), id, "runner."+req.Action, "runner", runnerID, map[string]any{
			"name": run.Name, "state": run.State, "bulk": true, "force": req.Force,
		})
	}
	if changed > 0 {
		s.ctrl.Nudge()
	}
	writeJSON(w, http.StatusOK, bulkRunnerResponse{Results: results})
}

package api

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// The settings surface.
//
// Every configuration key except the three that get the database open lives in
// the database, so this is where an administrator changes the fleet rather than
// where they are told to go and edit a file on the controller's host. Two
// things follow from that, and both are the point:
//
// A change is kept. It used to be that a PATCH altered the running process and
// nothing else, so a setting that was also in zoomies.yaml quietly went back to
// the file's value at the next restart -- the API said so in as many words, and
// it was still a surprise every time. Now the value is written, and the file is
// a layer underneath it.
//
// A change that cannot be applied now is still accepted. Rebinding a listener
// under live connections is not something a process can do to itself, so
// server.bind is stored and reported in pending_restart instead of refused.
// Refusing it never stopped anybody wanting it changed; it only moved the work
// to a text editor and left no record that anyone had asked.
//
// What is refused is a change that would not survive: a key an environment
// variable is pinning would be written, overridden at the next start, and
// appear to have been forgotten. The refusal names the variable.

// ---------------------------------------------------------------------------
// The shapes
// ---------------------------------------------------------------------------

// settingView is one configuration key as the settings page sees it: what it
// is, what it is set to, where that value came from, and whether this
// administrator can change it here.
//
// It is generated from the registry in internal/config rather than written out
// by hand. The lists it replaces -- the fourteen keys the API would write, the
// forty-seven it would refuse, the nested map it rendered from, and the two
// constants the browser kept -- were four hand-maintained copies of one fact,
// and all four had drifted.
type settingView struct {
	Key     string   `json:"key"`
	Label   string   `json:"label"`
	Section string   `json:"section"`
	Kind    string   `json:"kind"`
	Choices []string `json:"choices,omitempty"`
	Summary string   `json:"summary"`

	// Value is what this controller is running. A secret's value is never
	// here; Configured says whether one is set, which is the useful fact.
	Value      any  `json:"value"`
	Secret     bool `json:"secret"`
	Configured bool `json:"configured"`
	// Default is what Zoomies would use if nothing said otherwise, so the UI
	// can offer "put it back" and show what that means.
	Default any `json:"default"`

	// Source is which layer won: default, file, database or environment.
	Source string `json:"source"`
	// Env is the variable that overrides this key, named so an operator can
	// find the one that is pinning it.
	Env string `json:"env"`
	// Stored says a value for this key is in the database.
	Stored bool `json:"stored"`

	// Editable says an administrator may change it here. Scope and Source are
	// between them the reason when it is false, and Reason says it in a
	// sentence.
	Editable bool   `json:"editable"`
	Scope    string `json:"scope"`
	Reason   string `json:"reason,omitempty"`

	// Live says a change is in force by the time the response is written.
	// False means it is stored and applies at the next restart.
	Live          bool   `json:"live"`
	RestartReason string `json:"restart_reason,omitempty"`
	// Pending says a stored value is waiting for that restart.
	Pending bool `json:"pending"`

	UpdatedAt *time.Time `json:"updated_at,omitempty"`
	UpdatedBy string     `json:"updated_by,omitempty"`
}

// settingsResponse is the whole settings page in one document.
type settingsResponse struct {
	// Config is the effective configuration as a nested object, every secret
	// absent. It is what `zoomies config print` shows and what the diagnostics
	// bundle carries, kept because a person reading a configuration wants it
	// shaped like the file rather than as a list of rows.
	Config   map[string]any   `json:"config"`
	Settings []settingView    `json:"settings"`
	Findings []config.Finding `json:"findings"`

	// PendingRestart names the settings stored since this process started that
	// it cannot apply to itself.
	PendingRestart []string `json:"pending_restart"`
	// PinnedByEnvironment names the settings an environment variable is
	// holding, which is why the page will not let them be changed.
	PinnedByEnvironment []string `json:"pinned_by_environment"`
	// RestartRequiredKeys is every setting whose change waits for a restart,
	// whether or not one is waiting now. The UI labels them before an
	// administrator edits one rather than after.
	RestartRequiredKeys []string `json:"restart_required_keys"`

	ConfigPath       string `json:"config_path,omitempty"`
	Version          string `json:"version"`
	DatabasePath     string `json:"database_path"`
	EventSubscribers int    `json:"event_subscribers"`
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

// dropAnsweredElsewhere removes the findings the configuration file cannot
// answer on its own.
//
// There is one: "backups never leave this host", which config.Validate raises
// from backup.remotes and cannot know about a destination an administrator
// added on the Backups page, because that is a database row. Telling somebody
// to do a thing they have already done is how a page teaches them to stop
// reading it.
func (s *Server) dropAnsweredElsewhere(r *http.Request, findings []config.Finding) []config.Finding {
	answered := false
	for _, remote := range s.ctrl.BackupRemotes(r.Context()) {
		if !remote.Disabled && !remote.Shadowed && remote.Problem == "" {
			answered = true
			break
		}
	}
	if !answered {
		return findings
	}
	out := findings[:0]
	for _, f := range findings {
		if f.Code != config.NoRemoteFinding {
			out = append(out, f)
		}
	}
	return out
}

// settingsConfig renders the effective configuration as a nested object.
//
// The registry-driven rendering lives in config.Redacted, shared with the
// support bundle and a backup's manifest; what is added here is the handful of
// values that are derived rather than configured, and are what an operator
// actually wants to see next to the settings they came from.
func (s *Server) settingsConfig(who store.Role) map[string]any {
	c := s.cfg()
	out := config.Redacted(c)

	// The nested object says the same thing the key-by-key list does, so it
	// has to answer the same way: an administrator who is not shown
	// backup.directory in the list must not find it here, or in the support
	// bundle that renders this same tree.
	if !who.AtLeast(store.RolePlatform) {
		for _, st := range config.Settings() {
			if platformsOwn(st) {
				deleteNested(out, st.Key)
			}
		}
	}

	// The encryption key's presence is the one thing here that is not read off
	// the configuration: it may have come from a file this process read at
	// startup rather than from a key any layer holds.
	setNested(out, "security.encryption_key_configured", s.key != nil)

	setNested(out, "github.webhook_url", c.WebhookURL())
	setNested(out, "github.polling_only", s.ctrl.PollingOnly())
	setNested(out, "oidc.redirect_url", s.oidcRedirectURL())
	return out
}

// setNested writes a dotted key into a tree of maps.
func setNested(into map[string]any, key string, value any) { config.SetNested(into, key, value) }

// deleteNested removes a dotted key from a tree of maps, and any section the
// removal leaves empty -- so a caller shown none of `backup.*` is not handed a
// bare `backup: {}` that says one exists and is being withheld.
func deleteNested(from map[string]any, key string) {
	parts := strings.Split(key, ".")
	node := from
	parents := make([]map[string]any, 0, len(parts))
	names := make([]string, 0, len(parts))
	for _, part := range parts[:len(parts)-1] {
		child, ok := node[part].(map[string]any)
		if !ok {
			return
		}
		parents = append(parents, node)
		names = append(names, part)
		node = child
	}
	delete(node, parts[len(parts)-1])
	for i := len(parents) - 1; i >= 0; i-- {
		child, _ := parents[i][names[i]].(map[string]any)
		if len(child) > 0 {
			return
		}
		delete(parents[i], names[i])
	}
}

func (s *Server) oidcRedirectURL() string {
	if s.oidcProvider().Enabled() {
		return s.oidcProvider().RedirectURL()
	}
	return s.cfg().OIDC.RedirectURL
}

// settingViews renders every key, in the order the documentation lists them.
func (s *Server) settingViews(rows []store.InstanceSetting, pending []string, who store.Role) []settingView {
	c := s.cfg()
	defaults := config.Default()
	stored := map[string]store.InstanceSetting{}
	for _, row := range rows {
		stored[row.Key] = row
	}

	out := make([]settingView, 0, len(config.Settings()))
	for _, st := range config.Settings() {
		// A fleet's administrator is not shown the platform's keys at all,
		// rather than shown them locked. A locked field still says what the
		// instance binds and where it ships its backups, and on an instance
		// one team operates for another that is the platform's business and
		// not the fleet's.
		if platformsOwn(st) && !who.AtLeast(store.RolePlatform) {
			continue
		}
		value, err := c.Value(st.Key)
		if err != nil {
			continue
		}
		row, isStored := stored[st.Key]
		source := string(c.Source(st.Key))

		v := settingView{
			Key:           st.Key,
			Label:         st.Label,
			Section:       st.Section(),
			Kind:          string(st.Kind),
			Choices:       st.Choices,
			Summary:       st.Summary,
			Secret:        st.Secret,
			Configured:    config.Text(st, value) != "",
			Source:        source,
			Env:           st.Env,
			Stored:        isStored,
			Scope:         string(st.Scope),
			Live:          st.Live,
			RestartReason: st.RestartReason,
			Pending:       slices.Contains(pending, st.Key),
		}
		if !st.Secret {
			v.Value = value
			if d, derr := defaults.Value(st.Key); derr == nil {
				v.Default = d
			}
		}
		if isStored {
			at := row.UpdatedAt
			v.UpdatedAt, v.UpdatedBy = &at, row.UpdatedBy
		}
		v.Editable, v.Reason = s.editable(st, c, who)
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool { return config.CompareKeys(out[i].Key, out[j].Key) < 0 })
	return out
}

// editable says whether this administrator may change a key here, and when they
// may not, why -- in a sentence written for the person reading it, because
// "not editable" with no reason is the thing that sends somebody to the source.
func (s *Server) editable(st config.Setting, c *config.Config, who store.Role) (bool, string) {
	if st.Platform() && !who.AtLeast(store.RolePlatform) {
		return false, "This belongs to whoever runs this controller rather than to the fleet: it changes what the process binds, trusts, stores or logs on its own machine. Ask them to change it."
	}
	switch st.Scope {
	case config.ScopeBootstrap:
		return false, fmt.Sprintf(
			"This is read before the database is open, so it cannot live in it. Set it in %s or as %s, and restart.",
			s.configFileName(), st.Env)
	case config.ScopeLocal:
		return false, fmt.Sprintf(
			"This belongs to a standalone agent's own host, not to the fleet. Set it there, in that agent's configuration or as %s.",
			st.Env)
	}
	if c.Source(st.Key) == config.SourceEnvironment {
		return false, fmt.Sprintf(
			"%s is setting this in the environment, and the environment is the last word. A change made here would be stored and then overridden at the next restart, so unset the variable first \u2014 or change it where it is set.",
			st.Env)
	}
	return true, ""
}

// callerRole is the asking identity's role, or the empty role when there is
// none. The empty role is at least nothing, so an unauthenticated caller that
// somehow reaches here is treated as the fleet rather than as the platform.
func callerRole(r *http.Request) store.Role { return callerRoleCtx(r.Context()) }

// isPlatform reports whether this caller runs the process rather than the
// fleet. It is the one question every audience filter asks.
func isPlatform(r *http.Request) bool { return callerRole(r).AtLeast(store.RolePlatform) }

// callerRoleCtx is callerRole for the handlers that carry a context rather
// than the request -- the support bundle assembles itself from several.
func callerRoleCtx(ctx context.Context) store.Role {
	if id := Identity(ctx); id != nil {
		return id.Role
	}
	return ""
}

// platformsOwn reports whether a setting describes the process's own machine,
// and so is shown to the platform alone. The bootstrap keys count: they are
// not platform-scoped, because they are not stored at all, but their values
// are the database file and the key file -- the two paths on the host that
// matter most -- and hiding database_path from an administrator while
// database.path sat in the same response hid nothing.
func platformsOwn(st config.Setting) bool {
	return st.Platform() || st.Scope == config.ScopeBootstrap
}

// platformOnly blanks a string that describes the process's own machine --
// where its configuration file is, where its database is -- for anybody but
// the platform. A fleet's administrator has no use for a path on somebody
// else's host, and on an operated instance it is not theirs to know.
func platformOnly(who store.Role, v string) string {
	if who.AtLeast(store.RolePlatform) {
		return v
	}
	return ""
}

// platformOnlyInt is platformOnly for a count. Zero rather than absent: the
// field is not optional in the schema, and "no subscribers" is the honest
// reading of a number the caller is not being told.
func platformOnlyInt(who store.Role, v int) int {
	if who.AtLeast(store.RolePlatform) {
		return v
	}
	return 0
}

// visibleKeys drops the platform's keys from a list of key names for anybody
// but the platform. The settings themselves are already filtered; a key that
// survived only in the pending-restart or restart-required list would name a
// setting the caller was never shown, which reads as a bug in the page.
func visibleKeys(keys []string, who store.Role) []string {
	if who.AtLeast(store.RolePlatform) {
		return keys
	}
	out := make([]string, 0, len(keys))
	for _, k := range keys {
		if st, ok := config.LookupSetting(k); ok && platformsOwn(st) {
			continue
		}
		out = append(out, k)
	}
	return out
}

func (s *Server) configFileName() string {
	if p := s.cfg().Path(); p != "" {
		return p
	}
	return "zoomies.yaml"
}

// restartRequiredKeys is every setting a change to which waits for a restart.
// A fresh slice each time: the old version returned one backing array to every
// response, which a caller that sorted it would have corrupted for all of them.
func restartRequiredKeys() []string {
	var out []string
	for _, st := range config.StoredSettings() {
		if !st.Live {
			out = append(out, st.Key)
		}
	}
	slices.Sort(out)
	return out
}

// ---------------------------------------------------------------------------
// GET
// ---------------------------------------------------------------------------

// handleGetSettings answers GET /api/v1/settings.
func (s *Server) handleGetSettings(w http.ResponseWriter, r *http.Request) {
	page, err := s.settingsPage(r)
	if err != nil {
		s.internal(w, r, "reading the stored settings", err)
		return
	}
	writeJSON(w, http.StatusOK, page)
}

// settingsPage renders the whole page. The import route returns it too, so
// that a client which just changed forty keys can repaint without asking.
func (s *Server) settingsPage(r *http.Request) (settingsResponse, error) {
	c := s.cfg()
	who := callerRole(r)
	rows, err := s.ctrl.Store().ListInstanceSettings(r.Context())
	if err != nil {
		return settingsResponse{}, err
	}
	// PendingRestart needs the sealed values to compare a stored credential
	// against the running one, so it reads the unblanked rows.
	sealed, err := s.ctrl.Store().InstanceSettings(r.Context())
	if err != nil {
		return settingsResponse{}, err
	}
	pending := config.PendingRestart(c, sealed, s.key)

	var pinned []string
	for _, st := range c.PinnedByEnvironment() {
		if platformsOwn(st) && !who.AtLeast(store.RolePlatform) {
			continue
		}
		pinned = append(pinned, st.Key)
	}

	// The findings about the rows themselves -- a stored value that will not
	// parse, keys a newer version left behind -- are recomputed here rather
	// than kept from startup. config.Validate cannot produce them: it works on
	// an in-memory snapshot and has never seen the rows. Printing them once at
	// startup and dropping them left the one page where each is actionable as
	// the one place it did not appear.
	stale := *c
	stale.SetSources(c.Sources())
	findings := append(config.ApplyStored(&stale, sealed, s.key).ForUI(), c.Validate().ForUI()...)
	findings = s.dropAnsweredElsewhere(r, findings)

	return settingsResponse{
		Config:              s.settingsConfig(who),
		Settings:            s.settingViews(rows, pending, who),
		Findings:            findings,
		PendingRestart:      emptySlice(visibleKeys(pending, who)),
		PinnedByEnvironment: emptySlice(pinned),
		RestartRequiredKeys: visibleKeys(restartRequiredKeys(), who),
		ConfigPath:          platformOnly(who, c.Path()),
		Version:             version.Short(),
		DatabasePath:        platformOnly(who, s.ctrl.Store().Path()),
		EventSubscribers:    platformOnlyInt(who, s.ctrl.Events().Subscribers()),
	}, nil
}

// ---------------------------------------------------------------------------
// PATCH
// ---------------------------------------------------------------------------

// change is one staged edit, checked but not yet written.
type change struct {
	setting config.Setting
	// unset asks for the stored row to be removed, so the key goes back to
	// whatever the configuration file or the built-in default says. A JSON
	// null means this, which reads the same way for every kind: "say nothing
	// about it".
	unset bool
	value any
	// before is what the setting was, for the audit trail.
	before any
}

// handleUpdateSettings changes the fleet's settings.
//
// Every key is checked before any is written, and the whole request is refused
// if one fails. A request is one change: applying the keys that parsed and
// answering 422 for the one that did not would leave an operator told their
// change was refused while half of it was in effect, with an audit row for
// neither half.
//
// The order of what follows matters. The candidate configuration is validated
// first, so a value that would stop the next startup is refused now rather than
// discovered at the next restart by an operator who can no longer reach this
// page. Then the rows are written, because a stored change that is not yet in
// force is recoverable and an applied change that was never stored is not.
// Then the live keys are pushed into the running snapshot.
func (s *Server) handleUpdateSettings(w http.ResponseWriter, r *http.Request) {
	var raw map[string]any
	if !decode(w, r, &raw) {
		return
	}
	flat := map[string]any{}
	flatten("", raw, flat)

	current := s.cfg()
	candidate, staged, fields := s.planSettings(current, flat, callerRole(r))
	if len(fields) > 0 {
		unprocessable(w, "these settings could not be changed", fields)
		return
	}
	if len(staged) == 0 {
		s.handleGetSettings(w, r)
		return
	}
	if fields := validatePlan(current, candidate, staged); len(fields) > 0 {
		unprocessable(w, "that would leave a controller that will not start", fields)
		return
	}
	if err := s.applyPlan(r.Context(), Identity(r.Context()), staged); err != nil {
		s.internal(w, r, "storing the settings", err)
		return
	}
	s.handleGetSettings(w, r)
}

// planSettings checks every key in flat against the running configuration and
// returns the candidate that results, the changes that would be made, and the
// refusals. It writes nothing. The import route plans the same way, which is
// how a preview of an import can be trusted to be what applying it would do.
func (s *Server) planSettings(current *config.Config, flat map[string]any, who store.Role) (*config.Config, []change, []fieldError) {
	// A scratch copy to try the whole request on. Validating the result is
	// what makes it safe to let a settings page write a listener address.
	candidate := *current
	candidate.SetSources(current.Sources())

	var fields []fieldError
	staged := make([]change, 0, len(flat))
	for _, key := range sortedKeys(flat) {
		value := flat[key]
		st, ok := config.LookupSetting(key)
		if !ok {
			fields = append(fields, fieldError{key, fmt.Sprintf("%q is not a setting this version has", key)})
			continue
		}
		if editable, reason := s.editable(st, current, who); !editable {
			fields = append(fields, fieldError{key, reason})
			continue
		}

		ch := change{setting: st}
		if value == nil && st.Kind != config.KindOptionalBool {
			ch.unset = true
			// Clearing a key means the layers underneath decide, and what they
			// say is only known once the row is gone -- so the candidate gets
			// the default, which is the floor of those layers and the only
			// value that is certainly no worse.
			def, _ := config.Default().Value(key)
			value = def
		}
		before, err := candidate.SetValue(key, value)
		if err != nil {
			var se *config.SettingError
			if errors.As(err, &se) {
				fields = append(fields, fieldError{key, se.Error()})
			} else {
				fields = append(fields, fieldError{key, err.Error()})
			}
			continue
		}
		// What gets stored and applied is what the configuration made of the
		// request, not the request itself. A list arrives from JSON as []any
		// and a duration as free text; reading the value back gives the typed,
		// normalised thing, so the row in the database and the value in the
		// running snapshot are the same value rendered the same way.
		parsed, err := candidate.Value(key)
		if err != nil {
			fields = append(fields, fieldError{key, err.Error()})
			continue
		}
		ch.before, ch.value = before, parsed
		staged = append(staged, ch)
	}
	return &candidate, staged, fields
}

// validatePlan asks whether the candidate would leave a controller that will
// not start, and returns the refusals as fields.
//
// Only the errors the request introduces count. An instance can already be
// running with one -- a deployment that disabled authentication and later
// gained an external URL is the common way -- and refusing every edit on that
// instance would lock the operator out of the settings page that is the one
// place they could fix it. So the validator is run twice and the difference is
// what is refused.
func validatePlan(current, candidate *config.Config, staged []change) []fieldError {
	candidate.Normalize()
	changed := map[string]bool{}
	for _, ch := range staged {
		changed[ch.setting.Key] = true
	}
	fields := egressRefusals(candidate, changed)
	introduced := newErrors(current, candidate)
	for _, f := range introduced {
		field := f.Setting
		if !changed[field] {
			// The error is about a setting this request did not touch, so it
			// belongs to the request rather than to a field: it is the
			// combination that is wrong.
			field = ""
		}
		fields = append(fields, fieldError{field, findingSentence(f)})
	}
	return fields
}

// egressRefusals refuses a write that points one of the settings the
// controller dials at this machine or a private network, unless the
// candidate allows it.
//
// The validator only warns about the same thing, because at startup the
// value came from whoever runs the process and an upgrade must not stop a
// working install. Here it is somebody with settings rights asking this
// controller to send requests somewhere on their say-so, which is the case
// the guard exists for -- so it is decided here, whatever the validator's
// severity. Turning single sign-on on is a write that starts dialling the
// issuer, so it counts as writing the issuer.
func egressRefusals(candidate *config.Config, changed map[string]bool) []fieldError {
	var fields []fieldError
	for _, o := range candidate.OutboundURLs() {
		if !changed[o.Setting] && (o.Setting != "oidc.issuer" || !changed["oidc.enabled"]) {
			continue
		}
		if f := config.CheckOutboundURL(o.Setting, o.Value, candidate.Security.AllowPrivateEgress); f != nil {
			// Blamed on the key the request changed, so an import preview
			// marks a row the operator can skip.
			field := o.Setting
			if !changed[field] {
				field = "oidc.enabled"
			}
			fields = append(fields, fieldError{field, findingSentence(*f)})
		}
	}
	return fields
}

// applyPlan stores the staged changes, pushes the live half into the running
// snapshot, and writes the audit row.
func (s *Server) applyPlan(ctx context.Context, id *auth.Identity, staged []change) error {
	if err := s.writeSettings(ctx, id.Name, staged); err != nil {
		return err
	}

	// Only the live half reaches the running snapshot. The rest is stored and
	// waiting, which is what pending_restart in the response says.
	applied, before := map[string]any{}, map[string]any{}
	var live []change
	for _, ch := range staged {
		if ch.setting.Live {
			live = append(live, ch)
		}
		b, a, recorded := auditedValues(ch)
		if recorded {
			before[ch.setting.Key], applied[ch.setting.Key] = b, a
		}
	}
	if len(live) > 0 {
		// One update for the whole request, so two keys sent together land in
		// the same snapshot and no reader sees one without the other.
		s.ctrl.UpdateConfig(func(c *config.Config) {
			for _, ch := range live {
				if _, err := c.SetValue(ch.setting.Key, ch.value); err != nil {
					continue // Already parsed against the candidate; cannot fail here.
				}
				if ch.unset {
					c.Note(ch.setting.Key, config.SourceDefault)
				} else {
					c.Note(ch.setting.Key, config.SourceDatabase)
				}
			}
			c.Normalize()
		})
	}

	s.auth.Auditor().Updated(ctx, id, "settings", "settings", before, applied)
	return nil
}

// The two markers a secret setting's audit row carries. redactedMarker is the
// word the audit trail already uses for a value it withheld; replacedMarker
// differs from it so that a change is still a change to the diff, which drops
// any key whose two sides are equal.
const (
	redactedMarker = "[redacted]"
	replacedMarker = "[replaced]"
)

// auditedValues is what the audit row records for one staged change, and
// whether it records anything.
//
// An audit row is kept for the life of the database and cannot be retracted,
// and its redaction goes by key name: "agent.registry_auth" matches none of
// its words, so the credential was written into the row whole, and the one it
// replaced with it. A secret setting records the direction of the change
// instead. It is keyed on the registry's Secret flag rather than a name, so a
// secret added later is covered without anyone remembering to.
func auditedValues(ch change) (before, after any, recorded bool) {
	if !ch.setting.Secret {
		if ch.unset {
			return ch.before, nil, true
		}
		return ch.before, ch.value, true
	}
	was := config.Text(ch.setting, ch.before)
	if !ch.unset && was == config.Text(ch.setting, ch.value) {
		// Saving what the controller already runs with. The markers differ, so
		// without this a re-save would be logged as a rotation.
		return nil, nil, false
	}
	// A clear removes a stored row that the running value may not show yet, so
	// it is always something that was there.
	if was != "" || ch.unset {
		before = redactedMarker
	}
	if !ch.unset {
		after = replacedMarker
	}
	return before, after, true
}

// writeSettings puts the whole batch in the database in one transaction, so a
// request that both sets a key and clears another cannot half-apply -- which
// would leave an audit row claiming both halves took.
func (s *Server) writeSettings(ctx context.Context, by string, staged []change) error {
	var rows []store.InstanceSetting
	var clear []string
	for _, ch := range staged {
		if ch.unset {
			clear = append(clear, ch.setting.Key)
			continue
		}
		row, err := config.EncodeStored(ch.setting, ch.value, s.key)
		if err != nil {
			return err
		}
		rows = append(rows, row)
	}
	return s.ctrl.Store().ApplyInstanceSettings(ctx, by, rows, clear)
}

// newErrors returns the validation errors the candidate has and the running
// configuration does not, matched by code and setting so that the same error
// moving from one setting to another still counts as new.
func newErrors(running, candidate *config.Config) config.Findings {
	had := map[string]bool{}
	for _, f := range running.Validate().Errors() {
		had[f.Code+"\x00"+f.Setting] = true
	}
	var out config.Findings
	for _, f := range candidate.Validate().Errors() {
		if !had[f.Code+"\x00"+f.Setting] {
			out = append(out, f)
		}
	}
	return out
}

// findingSentence puts a validator finding into one line an operator can act
// on: what is true, then what to do about it.
func findingSentence(f config.Finding) string {
	title := strings.TrimRight(f.Title, ".")
	if f.Fix == "" {
		return title + "."
	}
	return title + ". " + f.Fix
}

func sortedKeys(m map[string]any) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// flatten turns a nested settings object into dotted keys, so that a client may
// send either {"retention":{"jobs":"720h"}} or {"retention.jobs":"720h"} -- the
// UI's form produces one and a script written by hand produces the other.
//
// A key the registry knows is never descended into, so agent.labels -- the one
// setting whose value is itself a map -- arrives as one value rather than as a
// key per label.
func flatten(prefix string, in map[string]any, out map[string]any) {
	for k, v := range in {
		key := k
		if prefix != "" {
			key = prefix + "." + k
		}
		if _, known := config.LookupSetting(key); !known {
			if nested, ok := v.(map[string]any); ok && len(nested) > 0 {
				flatten(key, nested, out)
				continue
			}
		}
		out[key] = v
	}
}

package api

import (
	"encoding/json"
	"fmt"
	"net/http"
	"slices"
	"sort"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// Moving a configuration between instances, or keeping a record of one.
//
// An export is every setting somebody has set -- not the defaults, which are
// computed on the host that reads them, and never a secret's value -- shaped
// like zoomies.yaml, so the file an operator downloads is a file the next
// controller could be started with. An import is the same document read back,
// planned key by key through the same checks a PATCH goes through, and shown
// as a preview before anything is written: which keys would change, which are
// already so, and which this instance refuses and why.

// exportVersion is the export document's own shape number. It moves when a
// field is removed or renamed, not when one is added.
const exportVersion = 1

// settingsExport is the JSON form of an export. The YAML form is the
// `settings` tree alone, with these facts as a comment above it.
type settingsExport struct {
	ExportVersion int       `json:"export_version"`
	ExportedAt    time.Time `json:"exported_at"`
	// ExportedFrom names the instance, by the address it answers on, so a
	// file found in a directory a year later says where it came from.
	ExportedFrom string `json:"exported_from,omitempty"`
	Version      string `json:"version"`
	// Settings is the nested tree, shaped like the file.
	Settings map[string]any `json:"settings"`
	// SecretsConfigured names the credentials that were set on the source
	// and are not in this document. An import shows them as work to do by
	// hand, because a document that could carry them would be a credential.
	SecretsConfigured []string `json:"secrets_configured"`
}

// handleExportSettings answers GET /api/v1/settings/export.
func (s *Server) handleExportSettings(w http.ResponseWriter, r *http.Request) {
	format := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("format")))
	if format == "" {
		format = "json"
	}
	if format != "json" && format != "yaml" {
		badRequestField(w, "format", "the export is written as json or yaml")
		return
	}
	doc := s.exportSettings(callerRole(r))
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "settings.export", "settings", "settings", map[string]any{
		"format": format, "keys": countKeys(doc.Settings),
	})

	stamp := doc.ExportedAt.Format("20060102-150405")
	w.Header().Set("Cache-Control", "no-store")
	if format == "yaml" {
		body, err := yaml.Marshal(doc.Settings)
		if err != nil {
			s.internal(w, r, "rendering the export", err)
			return
		}
		header := fmt.Sprintf("# Zoomies settings, exported %s from %s (Zoomies %s).\n"+
			"# Every setting somebody has set on that instance; defaults are left out. No secret is in here:\n"+
			"# %s\n"+
			"# This file is the shape zoomies.yaml takes, and can be imported on the Settings page.\n",
			doc.ExportedAt.Format(time.RFC3339), orPhrase(doc.ExportedFrom, "an unnamed instance"), doc.Version,
			secretsLine(doc.SecretsConfigured))
		w.Header().Set("Content-Type", "application/yaml; charset=utf-8")
		w.Header().Set("Content-Disposition", `attachment; filename="zoomies-settings-`+stamp+`.yaml"`)
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(header))
		_, _ = w.Write(body)
		return
	}
	raw, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		s.internal(w, r, "rendering the export", err)
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="zoomies-settings-`+stamp+`.json"`)
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(append(raw, '\n'))
}

// exportSettings gathers every instance setting whose value somebody chose:
// stored here, set in the file, or pinned by the environment. Bootstrap and
// local settings are left out because they belong to a host rather than to a
// fleet, and a secret contributes its name to the list rather than its value.
// exportSettings renders what this caller may see, not everything the
// instance has. Rendering the lot would have made the audience split on
// GET /settings decorative: an administrator who could not read backup.directory
// on the page could read it out of the export one click away.
func (s *Server) exportSettings(who store.Role) settingsExport {
	c := s.cfg()
	doc := settingsExport{
		ExportVersion:     exportVersion,
		ExportedAt:        s.ctrl.Now(),
		ExportedFrom:      c.Server.ExternalURL,
		Version:           version.Short(),
		Settings:          map[string]any{},
		SecretsConfigured: []string{},
	}
	for _, st := range config.StoredSettings() {
		if st.Platform() && !who.AtLeast(store.RolePlatform) {
			continue
		}
		if c.Source(st.Key) == config.SourceDefault {
			continue
		}
		v, err := c.Value(st.Key)
		if err != nil {
			continue
		}
		if st.Secret {
			if config.Text(st, v) != "" {
				doc.SecretsConfigured = append(doc.SecretsConfigured, st.Key)
			}
			continue
		}
		config.SetNested(doc.Settings, st.Key, v)
	}
	return doc
}

func secretsLine(keys []string) string {
	if len(keys) == 0 {
		return "no secret was set on the source."
	}
	return "set these by hand after importing: " + strings.Join(keys, ", ") + "."
}

func orPhrase(s, fallback string) string {
	if strings.TrimSpace(s) == "" {
		return fallback
	}
	return s
}

func countKeys(tree map[string]any) int {
	flat := map[string]any{}
	flatten("", tree, flat)
	return len(flat)
}

// ---------------------------------------------------------------------------
// Import
// ---------------------------------------------------------------------------

// importRequest is what the page sends: the file's text, whether this is only
// a look, and the keys to leave out.
type importRequest struct {
	// Document is the export, or a zoomies.yaml, as text. YAML, of which JSON
	// is a subset, so either file works.
	Document string `json:"document"`
	// DryRun plans and reports without writing anything.
	DryRun bool `json:"dry_run"`
	// Skip names keys in the document to ignore -- the ones the preview
	// refused, or the ones the operator unticked.
	Skip []string `json:"skip"`
}

// importChange is one key's fate.
type importChange struct {
	Key     string `json:"key"`
	Label   string `json:"label,omitempty"`
	Section string `json:"section,omitempty"`
	// Current is the running value and Incoming the document's, both as the
	// settings page renders them; a secret's are never here.
	Current  any `json:"current"`
	Incoming any `json:"incoming"`
	// Action is what applying would do: change, unchanged, unset, or
	// refused. Live says a change is in force at once; false means it waits
	// for a restart.
	Action string `json:"action"`
	Live   bool   `json:"live"`
	Secret bool   `json:"secret"`
	// Reason says why it is refused, in a sentence.
	Reason string `json:"reason,omitempty"`
}

// The actions a planned key can have.
const (
	importChangeAction    = "change"
	importUnchangedAction = "unchanged"
	importUnsetAction     = "unset"
	importRefusedAction   = "refused"
)

// importResponse is the preview, or the result.
type importResponse struct {
	Applied bool           `json:"applied"`
	Changes []importChange `json:"changes"`
	Summary importSummary  `json:"summary"`
	// SecretsConfigured is carried through from an export document, so the
	// preview can say which credentials the operator has to set by hand.
	SecretsConfigured []string `json:"secrets_configured"`
	// Settings is the page after applying, so the client can repaint without
	// a second request. Absent on a dry run.
	Settings *settingsResponse `json:"settings,omitempty"`
}

type importSummary struct {
	Change    int `json:"change"`
	Unchanged int `json:"unchanged"`
	Unset     int `json:"unset"`
	Refused   int `json:"refused"`
	Skipped   int `json:"skipped"`
}

// handleImportSettings answers POST /api/v1/settings/import.
//
// A dry run plans and reports; a real run refuses the whole document if any
// key in it is refused, exactly as a PATCH does, so that an import is one
// change rather than the keys that happened to parse. The page sends the
// refused keys back in `skip` when the operator has decided to go on without
// them.
func (s *Server) handleImportSettings(w http.ResponseWriter, r *http.Request) {
	var req importRequest
	if !decode(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Document) == "" {
		unprocessable(w, "there is nothing to import", []fieldError{{"document", "paste or upload an export, or a zoomies.yaml"}})
		return
	}
	tree, secrets, err := parseImport(req.Document)
	if err != nil {
		unprocessable(w, "that is not a settings document", []fieldError{{"document", err.Error()}})
		return
	}
	flat := map[string]any{}
	flatten("", tree, flat)
	skipped := 0
	for _, key := range req.Skip {
		if _, ok := flat[key]; ok {
			delete(flat, key)
			skipped++
		}
	}

	current := s.cfg()
	candidate, staged, fields := s.planSettings(current, flat, callerRole(r))
	out := importResponse{Changes: []importChange{}, SecretsConfigured: emptySlice(secrets), Summary: importSummary{Skipped: skipped}}
	refused := map[string]string{}
	for _, f := range fields {
		refused[f.Field] = f.Message
	}
	for _, key := range sortedKeys(flat) {
		ch := importChange{Key: key}
		if st, ok := config.LookupSetting(key); ok {
			ch.Label, ch.Section, ch.Live, ch.Secret = st.Label, st.Section(), st.Live, st.Secret
			if !st.Secret {
				ch.Current, _ = current.Value(key)
			}
		}
		if reason, bad := refused[key]; bad {
			ch.Action, ch.Reason = importRefusedAction, reason
			out.Summary.Refused++
			out.Changes = append(out.Changes, ch)
			continue
		}
		idx := slices.IndexFunc(staged, func(c change) bool { return c.setting.Key == key })
		if idx < 0 {
			continue
		}
		planned := staged[idx]
		if !planned.setting.Secret {
			ch.Incoming = planned.value
		}
		switch {
		case planned.unset:
			ch.Action = importUnsetAction
			out.Summary.Unset++
		case config.Text(planned.setting, planned.before) == config.Text(planned.setting, planned.value):
			ch.Action = importUnchangedAction
			out.Summary.Unchanged++
			// Not staged: writing a row that changes nothing would still
			// stamp it as changed by this import.
			staged = slices.Delete(staged, idx, idx+1)
		default:
			ch.Action = importChangeAction
			out.Summary.Change++
		}
		out.Changes = append(out.Changes, ch)
	}
	sort.SliceStable(out.Changes, func(i, j int) bool { return config.CompareKeys(out.Changes[i].Key, out.Changes[j].Key) < 0 })

	if len(staged) > 0 {
		// The validator's verdict belongs in the preview too: an import that
		// would leave a controller that will not start is refused as a
		// whole, and the row it blames is marked so the operator can skip it.
		for _, f := range validatePlan(current, candidate, staged) {
			out.Summary.Refused++
			if f.Field == "" {
				out.Changes = append(out.Changes, importChange{Key: "", Action: importRefusedAction, Reason: f.Message})
				continue
			}
			for i := range out.Changes {
				if out.Changes[i].Key == f.Field {
					out.Changes[i].Action, out.Changes[i].Reason = importRefusedAction, f.Message
					out.Summary.Change--
				}
			}
			staged = slices.DeleteFunc(staged, func(c change) bool { return c.setting.Key == f.Field })
		}
	}

	if req.DryRun {
		writeJSON(w, http.StatusOK, out)
		return
	}
	if out.Summary.Refused > 0 {
		var fields []fieldError
		for _, ch := range out.Changes {
			if ch.Action == importRefusedAction {
				fields = append(fields, fieldError{ch.Key, ch.Reason})
			}
		}
		unprocessable(w, "some of the document was refused; skip those keys or fix the document", fields)
		return
	}
	if len(staged) > 0 {
		if err := s.applyPlan(r.Context(), Identity(r.Context()), staged); err != nil {
			s.internal(w, r, "storing the imported settings", err)
			return
		}
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "settings.import", "settings", "settings", map[string]any{
		"changed": out.Summary.Change, "unset": out.Summary.Unset, "unchanged": out.Summary.Unchanged, "skipped": skipped,
	})
	out.Applied = true
	page, err := s.settingsPage(r)
	if err != nil {
		s.internal(w, r, "reading the settings back", err)
		return
	}
	out.Settings = &page
	writeJSON(w, http.StatusOK, out)
}

// parseImport reads an export document or a zoomies.yaml and returns the
// settings tree, and the secrets an export said were configured.
//
// YAML is the parser, because JSON is YAML and a file an operator wrote by
// hand is more likely to be the former. An export is recognised by its
// version field; anything else is taken to be the tree itself.
func parseImport(text string) (map[string]any, []string, error) {
	var doc map[string]any
	if err := yaml.Unmarshal([]byte(text), &doc); err != nil {
		return nil, nil, fmt.Errorf("it does not parse as YAML or JSON: %w", err)
	}
	if doc == nil {
		return nil, nil, fmt.Errorf("it is empty")
	}
	if v, ok := doc["export_version"]; ok {
		n, isNum := v.(int)
		if !isNum || n > exportVersion {
			return nil, nil, fmt.Errorf("it is an export of version %v, and this build reads version %d", v, exportVersion)
		}
		tree, ok := doc["settings"].(map[string]any)
		if !ok {
			return nil, nil, fmt.Errorf("its settings are not an object")
		}
		var secrets []string
		if raw, ok := doc["secrets_configured"].([]any); ok {
			for _, item := range raw {
				if str, ok := item.(string); ok {
					secrets = append(secrets, str)
				}
			}
		}
		return tree, secrets, nil
	}
	return doc, nil, nil
}

package api

import (
	"fmt"
	"io/fs"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
)

// FleetStatus is the name-free projection GET /api/v1/status returns. It is
// the controller's type, aliased, for the reason every view is: one shape,
// defined once.
type FleetStatus = controller.FleetStatus

// statusAllowed answers the one question the three status routes share:
// may this request read the fleet's status at all? It writes the refusal
// itself, so a handler that gets false has nothing left to do.
//
// Off is a 404 rather than a 403 on every route, because a default install
// should look exactly as it did before this existed: a 403 would say there
// is something here to be refused.
func (s *Server) statusAllowed(w http.ResponseWriter, r *http.Request, api bool) bool {
	switch s.cfg().Status.Mode {
	case config.StatusPublic:
		return true
	case config.StatusAuthenticated:
		if info := infoFrom(r.Context()); info != nil && info.identity != nil {
			return true
		}
		if api {
			unauthorized(w, "the fleet status is only shown to people signed in to this controller; sign in, or ask an administrator to set status.mode to public")
			return false
		}
		// The page and the badge are fetched by a browser or an image proxy
		// that cannot sign in; a 401 page is all either could do with it.
		w.Header().Set("Cache-Control", "no-store")
		http.Error(w, "sign in to this controller to see the fleet status", http.StatusUnauthorized)
		return false
	default:
		if api {
			apiNotFound(w, r)
		} else {
			http.NotFound(w, r)
		}
		return false
	}
}

// handleStatus serves the projection.
func (s *Server) handleStatus(w http.ResponseWriter, r *http.Request) {
	if !s.statusAllowed(w, r, true) {
		return
	}
	st, err := s.ctrl.Status(r.Context())
	if err != nil {
		s.internal(w, r, "computing the fleet status", err)
		return
	}
	writeJSON(w, http.StatusOK, st)
}

// statusPlaceholder stands in for the status page in a binary built without
// the UI, so the route still answers what it would in a real build rather
// than a 404 that reads as "status.mode is off".
const statusPlaceholder = `<!doctype html><meta charset="utf-8"><title>Fleet status</title>` +
	`<p>` + placeholderMarker + ` into this binary. The status is at <a href="/api/v1/status">/api/v1/status</a>.</p>`

// handleStatusPage serves /status, the page's own Vite entry.
//
// It is its own document rather than a route of the app, so that a reader
// with no account never downloads the app shell, and so that nothing on it
// can open /api/v1/events: every frame on that stream is a resource view,
// and every resource view carries names.
func (s *Server) handleStatusPage(w http.ResponseWriter, r *http.Request) {
	if !s.statusAllowed(w, r, false) {
		return
	}
	page, err := fs.ReadFile(s.spa.files, "status.html")
	if err != nil {
		page = []byte(statusPlaceholder)
	}
	w.Header().Set("Cache-Control", "no-cache, must-revalidate")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write(page)
}

// badgeColours are the three states on the light theme's status tokens
// (--z-danger, --z-pending, --z-idle in web/src/lib/styles/tokens.css). A
// badge is an image fetched through somebody else's proxy, so it cannot read
// a stylesheet and cannot follow a theme; it carries the values itself.
var badgeColours = map[controller.FleetState]string{
	controller.FleetHealthy:  "#0f7a3d",
	controller.FleetDegraded: "#9a6100",
	controller.FleetBlocked:  "#bd2018",
}

// handleStatusBadge serves /status.svg, the state as a README badge on the
// docs/badge.svg pattern: self-contained, no font, no second request, text
// pinned to a width so it lays out the same wherever it is drawn.
func (s *Server) handleStatusBadge(w http.ResponseWriter, r *http.Request) {
	if !s.statusAllowed(w, r, false) {
		return
	}
	st, err := s.ctrl.Status(r.Context())
	if err != nil {
		s.internal(w, r, "computing the fleet status", err)
		return
	}
	w.Header().Set("Content-Type", "image/svg+xml")
	// Short enough that a README shows a blocked fleet within a minute, long
	// enough that an image proxy is not asking every time a page is viewed.
	// Only a public status may sit in a shared cache: one fetched by somebody
	// signed in would otherwise be handed by a proxy or CDN to the next
	// request for the same URL, signed in or not, without it ever reaching
	// statusAllowed.
	if s.cfg().Status.Mode == config.StatusPublic {
		w.Header().Set("Cache-Control", fmt.Sprintf("public, max-age=%d", int((30*time.Second).Seconds())))
	} else {
		w.Header().Set("Cache-Control", "private, no-store")
	}
	_, _ = w.Write([]byte(statusBadge(st.State)))
}

// statusBadge draws the badge. The state is one of three fixed words, so
// nothing from a row reaches the SVG and nothing needs escaping.
func statusBadge(state controller.FleetState) string {
	colour, ok := badgeColours[state]
	if !ok {
		colour = badgeColours[controller.FleetDegraded]
	}
	word := string(state)
	// Roughly Verdana 11's advance, which is what textLength is pinned to.
	right := 7*len(word) + 12
	const left = 44
	var b strings.Builder
	fmt.Fprintf(&b, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="20" role="img" aria-label="fleet: %s">`, left+right, word)
	fmt.Fprintf(&b, `<title>fleet: %s</title>`, word)
	fmt.Fprintf(&b, `<clipPath id="r"><rect width="%d" height="20" rx="3" fill="#fff"/></clipPath>`, left+right)
	fmt.Fprintf(&b, `<g clip-path="url(#r)"><rect width="%d" height="20" fill="#080808"/><rect x="%d" width="%d" height="20" fill="%s"/></g>`, left, left, right, colour)
	b.WriteString(`<g fill="#fff" font-family="Verdana,Geneva,DejaVu Sans,sans-serif" font-size="11" text-rendering="geometricPrecision">`)
	fmt.Fprintf(&b, `<text x="6" y="14" textLength="%d" lengthAdjust="spacingAndGlyphs">fleet</text>`, left-12)
	fmt.Fprintf(&b, `<text x="%d" y="14" textLength="%d" lengthAdjust="spacingAndGlyphs">%s</text>`, left+6, right-12, word)
	b.WriteString(`</g></svg>`)
	return b.String()
}

package api

import (
	"errors"
	"net/http"

	"github.com/eyupio/zoomies/internal/controller"
)

// handleToolchains is GET /toolchains: the latest reading of which toolchain
// versions each pool's jobs install, and whether a scan is running now.
func (s *Server) handleToolchains(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.ctrl.ToolchainScanResult())
}

// handleScanToolchains is POST /toolchains/scan. The scan runs in the
// background -- on a large organisation it is minutes of GitHub calls -- so
// this answers 202 at once and GET /toolchains says when it is done.
func (s *Server) handleScanToolchains(w http.ResponseWriter, r *http.Request) {
	if err := s.ctrl.StartToolchainScan(r.Context()); err != nil {
		if errors.Is(err, controller.ErrToolchainScanRunning) {
			conflict(w, "a toolchain scan is already running; GET /api/v1/toolchains says when it finishes")
			return
		}
		s.internal(w, r, "starting a toolchain scan", err)
		return
	}
	// It reads every workflow file the installations can see, which spends
	// the GitHub quota the scheduler shares -- worth a line in the audit log.
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "toolchains.scan", "toolchains", "", nil)
	writeJSON(w, http.StatusAccepted, s.ctrl.ToolchainScanResult())
}

package api

import (
	"errors"
	"net/http"
	"net/url"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// SignInCookie carries a sign-in that has passed the password and waits for
// its second step. It is scoped to the auth routes, lives as long as the
// pending sign-in does, and is Strict: nothing but this UI's own requests
// should ever send it.
const SignInCookie = "zoomies_sign_in"

const signInCookiePath = "/api/v1/auth"

// signInChallengeResponse is the 202 a correct password gets when the
// account has a second step still to take.
type signInChallengeResponse struct {
	TwoStep   string    `json:"two_step"`
	Username  string    `json:"username"`
	ExpiresAt time.Time `json:"expires_at"`
}

// twoStepSignInResponse is a finished second step: who is now signed in,
// and what the page should say about recovery codes.
type twoStepSignInResponse struct {
	Identity          identityResponse `json:"identity"`
	RecoveryCodeUsed  bool             `json:"recovery_code_used"`
	RecoveryCodesLeft *int             `json:"recovery_codes_left,omitempty"`
	RecoveryCodes     []string         `json:"recovery_codes,omitempty"`
}

type twoStepStatusResponse struct {
	Available         bool       `json:"available"`
	Enabled           bool       `json:"enabled"`
	EnabledAt         *time.Time `json:"enabled_at,omitempty"`
	RecoveryCodesLeft int        `json:"recovery_codes_left"`
	Required          bool       `json:"required"`
}

type twoStepSetupResponse struct {
	Secret string `json:"secret"`
	URI    string `json:"otpauth_uri"`
	QRSVG  string `json:"qr_svg"`
}

type twoStepCodeRequest struct {
	Code string `json:"code"`
}

type twoStepReauthRequest struct {
	Password string `json:"password"`
	Code     string `json:"code"`
}

type recoveryCodesResponse struct {
	RecoveryCodes []string `json:"recovery_codes"`
}

func (s *Server) setSignInCookie(w http.ResponseWriter, token string, expires time.Time) {
	http.SetCookie(w, &http.Cookie{
		Name:     SignInCookie,
		Value:    token,
		Path:     signInCookiePath,
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteStrictMode,
		MaxAge:   int(time.Until(expires).Round(time.Second) / time.Second),
	})
}

func (s *Server) clearSignInCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     SignInCookie,
		Value:    "",
		Path:     signInCookiePath,
		HttpOnly: true,
		Secure:   s.cfg().CookieSecureValue(),
		SameSite: http.SameSiteStrictMode,
		MaxAge:   -1,
		Expires:  time.Unix(0, 0),
	})
}

func signInChallenge(r *http.Request) string {
	if c, err := r.Cookie(SignInCookie); err == nil {
		return c.Value
	}
	return ""
}

// startSecondStep answers a correct password whose account has a second step
// to take: the challenge goes into a cookie the page cannot read, and the
// body says which step comes next.
func (s *Server) startSecondStep(w http.ResponseWriter, pending *auth.SecondStepRequired) {
	s.setSignInCookie(w, pending.Challenge, pending.ExpiresAt)
	writeJSON(w, http.StatusAccepted, signInChallengeResponse{
		TwoStep: pending.Purpose, Username: pending.User.Username, ExpiresAt: pending.ExpiresAt,
	})
}

// twoStepHost is the address the authenticator app files the entry under:
// the configured external address, or the one this request arrived on.
func (s *Server) twoStepHost(r *http.Request) string {
	if u, err := url.Parse(s.cfg().Server.ExternalURL); err == nil && u.Host != "" {
		return u.Host
	}
	return r.Host
}

// failSecondStep maps a refused second step onto a response. A code that is
// wrong is a 401 like a wrong password; a sign-in that has run out clears
// its cookie, because the page has to go back to the password.
func (s *Server) failSecondStep(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, auth.ErrRateLimited):
		ip := ClientIP(r.Context())
		rateLimited(w, err.Error(), s.auth.LoginRetryAfter(ip))
	case errors.Is(err, auth.ErrSignInExpired):
		s.clearSignInCookie(w)
		unauthorized(w, err.Error())
	case errors.Is(err, auth.ErrInvalidTwoStepCode):
		// Pointed at the code field, which is how the page tells "try the
		// next code" apart from "start again with the password".
		writeError(w, http.StatusUnauthorized, errorEnvelope{Error: errorBody{
			Code: codeUnauthorized, Message: err.Error(), Field: "code"}})
	case errors.Is(err, auth.ErrAccountDisabled):
		s.clearSignInCookie(w)
		unauthorized(w, err.Error())
	default:
		s.internal(w, r, "finishing the sign-in", err)
	}
}

// signedIn finishes a two-step sign-in the way handleLogin finishes a
// password-only one: the session cookie, the audit row, the identity.
func (s *Server) signedIn(w http.ResponseWriter, r *http.Request, in *auth.SignIn, how string) {
	s.clearSignInCookie(w)
	s.setSessionCookie(w, in.Session)
	u := in.User
	id := &auth.Identity{Kind: auth.KindUser, ID: u.ID, Name: u.Username, Role: u.Role, UserID: u.ID, IP: ClientIP(r.Context())}
	s.auth.Auditor().Auth(r.Context(), id, "auth.login", map[string]any{"role": u.Role, "two_step": how})
	out := twoStepSignInResponse{
		Identity:         newIdentityResponse(id, u.MustChangePassword),
		RecoveryCodeUsed: in.RecoveryCodeUsed,
		RecoveryCodes:    in.RecoveryCodes,
	}
	if in.RecoveryCodeUsed {
		left := in.RecoveryCodesLeft
		out.RecoveryCodesLeft = &left
	}
	writeJSON(w, http.StatusOK, out)
}

// handleTwoStepVerify answers POST /auth/two-step/verify: the code step of a
// sign-in.
func (s *Server) handleTwoStepVerify(w http.ResponseWriter, r *http.Request) {
	var req twoStepCodeRequest
	if !decode(w, r, &req) {
		return
	}
	in, err := s.auth.VerifySignIn(r.Context(), signInChallenge(r), req.Code, ClientIP(r.Context()), r.UserAgent())
	if err != nil {
		s.failSecondStep(w, r, err)
		return
	}
	how := "code"
	if in.RecoveryCodeUsed {
		how = "recovery_code"
	}
	s.signedIn(w, r, in, how)
}

// handleTwoStepEnrolStart answers POST /auth/two-step/enrol: the setup a
// sign-in has to finish because the instance requires two-step.
func (s *Server) handleTwoStepEnrolStart(w http.ResponseWriter, r *http.Request) {
	setup, err := s.auth.EnrolDuringSignIn(r.Context(), signInChallenge(r), s.twoStepHost(r), r.UserAgent())
	if err != nil {
		s.failSetup(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, setupResponse(setup))
}

// handleTwoStepEnrolConfirm answers POST /auth/two-step/enrol/confirm.
func (s *Server) handleTwoStepEnrolConfirm(w http.ResponseWriter, r *http.Request) {
	var req twoStepCodeRequest
	if !decode(w, r, &req) {
		return
	}
	in, err := s.auth.ConfirmDuringSignIn(r.Context(), signInChallenge(r), req.Code, ClientIP(r.Context()), r.UserAgent())
	if err != nil {
		s.failSecondStep(w, r, err)
		return
	}
	s.auth.Auditor().Act(r.Context(), &auth.Identity{Kind: auth.KindUser, ID: in.User.ID, Name: in.User.Username,
		Role: in.User.Role, UserID: in.User.ID, IP: ClientIP(r.Context())}, "user.two_step_enabled", "user", in.User.ID,
		map[string]any{"during_sign_in": true})
	s.signedIn(w, r, in, "enrolled")
}

func setupResponse(setup *auth.TwoStepSetup) twoStepSetupResponse {
	return twoStepSetupResponse{Secret: setup.Secret, URI: setup.URI, QRSVG: setup.QRSVG}
}

func (s *Server) failSetup(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, auth.ErrSignInExpired), errors.Is(err, auth.ErrAccountDisabled):
		s.failSecondStep(w, r, err)
	case errors.Is(err, auth.ErrRateLimited):
		rateLimited(w, err.Error(), s.auth.LoginRetryAfter(ClientIP(r.Context())))
	case errors.Is(err, auth.ErrTwoStepAlreadyOn):
		conflict(w, err.Error())
	case errors.Is(err, auth.ErrInvalidTwoStepCode):
		unprocessable(w, err.Error(), []fieldError{{"code", err.Error()}})
	case errors.Is(err, auth.ErrInvalidInput):
		unprocessable(w, err.Error(), nil)
	default:
		s.fail(w, r, "setting up two-step verification", err)
	}
}

// ownAccount is the account a self-service two-step route acts on: a person
// signed in with a session. A token is refused, because two-step guards the
// sign-in a token never makes.
func ownAccount(w http.ResponseWriter, r *http.Request) (*auth.Identity, bool) {
	id := Identity(r.Context())
	if id == nil || id.Kind != auth.KindUser || !store.HasPrefix(id.ID, store.PrefixUser) {
		forbidden(w, "two-step verification belongs to an account signing in with a password; "+
			"sign in to the UI to change it -- an API token is not asked for a code and cannot set one up")
		return nil, false
	}
	return id, true
}

// handleTwoStepStatus answers GET /auth/two-step.
func (s *Server) handleTwoStepStatus(w http.ResponseWriter, r *http.Request) {
	id, ok := ownAccount(w, r)
	if !ok {
		return
	}
	st, err := s.auth.TwoStepStatus(r.Context(), id.ID)
	if err != nil {
		s.fail(w, r, "reading two-step verification", err)
		return
	}
	writeJSON(w, http.StatusOK, twoStepStatusResponse{
		Available: st.Available, Enabled: st.Enabled, EnabledAt: st.EnabledAt,
		RecoveryCodesLeft: st.RecoveryCodesLeft, Required: st.Required,
	})
}

// handleTwoStepSetup answers POST /auth/two-step/setup: a new key, not yet
// in force.
func (s *Server) handleTwoStepSetup(w http.ResponseWriter, r *http.Request) {
	id, ok := ownAccount(w, r)
	if !ok {
		return
	}
	setup, err := s.auth.BeginTwoStep(r.Context(), id.ID, s.twoStepHost(r))
	if err != nil {
		s.failSetup(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, setupResponse(setup))
}

// handleTwoStepConfirm answers POST /auth/two-step/confirm: the first code,
// which turns two-step on and returns the recovery codes.
func (s *Server) handleTwoStepConfirm(w http.ResponseWriter, r *http.Request) {
	id, ok := ownAccount(w, r)
	if !ok {
		return
	}
	var req twoStepCodeRequest
	if !decode(w, r, &req) {
		return
	}
	keep := ""
	if c, err := r.Cookie(SessionCookie); err == nil {
		keep = c.Value
	}
	codes, err := s.auth.ConfirmTwoStep(r.Context(), id.ID, req.Code, keep, ClientIP(r.Context()))
	if err != nil {
		s.failSetup(w, r, err)
		return
	}
	s.auth.Auditor().Act(r.Context(), id, "user.two_step_enabled", "user", id.ID, nil)
	writeJSON(w, http.StatusOK, recoveryCodesResponse{RecoveryCodes: codes})
}

// failReauth maps a refused password-and-code proof onto field errors the
// dialog can put under the right box.
func (s *Server) failReauth(w http.ResponseWriter, r *http.Request, doing string, err error) {
	switch {
	case errors.Is(err, auth.ErrRateLimited):
		rateLimited(w, err.Error(), s.auth.LoginRetryAfter(ClientIP(r.Context())))
	case errors.Is(err, auth.ErrWrongPassword):
		unprocessable(w, err.Error(), []fieldError{{"password", err.Error()}})
	case errors.Is(err, auth.ErrInvalidTwoStepCode):
		unprocessable(w, err.Error(), []fieldError{{"code", err.Error()}})
	case errors.Is(err, auth.ErrInvalidInput):
		unprocessable(w, err.Error(), nil)
	default:
		s.fail(w, r, doing, err)
	}
}

// handleTwoStepDisable answers POST /auth/two-step/disable.
func (s *Server) handleTwoStepDisable(w http.ResponseWriter, r *http.Request) {
	id, ok := ownAccount(w, r)
	if !ok {
		return
	}
	var req twoStepReauthRequest
	if !decode(w, r, &req) {
		return
	}
	if err := s.auth.DisableTwoStep(r.Context(), id.ID, req.Password, req.Code, ClientIP(r.Context())); err != nil {
		s.failReauth(w, r, "turning two-step verification off", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), id, "user.two_step_disabled", "user", id.ID, nil)
	noContent(w)
}

// handleTwoStepRecoveryCodes answers POST /auth/two-step/recovery-codes.
func (s *Server) handleTwoStepRecoveryCodes(w http.ResponseWriter, r *http.Request) {
	id, ok := ownAccount(w, r)
	if !ok {
		return
	}
	var req twoStepReauthRequest
	if !decode(w, r, &req) {
		return
	}
	codes, err := s.auth.RegenerateRecoveryCodes(r.Context(), id.ID, req.Password, req.Code, ClientIP(r.Context()))
	if err != nil {
		s.failReauth(w, r, "issuing new recovery codes", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), id, "user.recovery_codes_regenerated", "user", id.ID, nil)
	writeJSON(w, http.StatusOK, recoveryCodesResponse{RecoveryCodes: codes})
}

// handleResetTwoStep answers DELETE /users/{id}/two-step: the
// administrator's answer to a lost phone. It is audited whether or not there
// was anything to remove, because an administrator taking the second factor
// off somebody's account is exactly what the audit log is for.
func (s *Server) handleResetTwoStep(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	target, err := s.ctrl.Store().GetUser(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the account", err)
		return
	}
	if err := auth.ManageWithin(Identity(r.Context()), target.Role); err != nil {
		forbidden(w, err.Error())
		return
	}
	removed, err := s.auth.ResetTwoStep(r.Context(), id)
	if err != nil {
		s.fail(w, r, "resetting two-step verification", err)
		return
	}
	s.auth.Auditor().Act(r.Context(), Identity(r.Context()), "user.two_step_reset", "user", id,
		map[string]any{"username": target.Username, "had_two_step": removed})
	noContent(w)
}

package api

import (
	"crypto/hmac"
	"crypto/sha1" //nolint:gosec // RFC 6238's algorithm, recomputed here independently of the auth package.
	"encoding/base32"
	"encoding/binary"
	"fmt"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// codeAt is an authenticator app: RFC 6238 written out a second time, so
// these tests do not lean on the implementation they are checking.
func codeAt(t *testing.T, secret string, at time.Time) string {
	t.Helper()
	key, err := base32.StdEncoding.WithPadding(base32.NoPadding).DecodeString(secret)
	if err != nil {
		t.Fatalf("decoding the secret: %v", err)
	}
	var counter [8]byte
	binary.BigEndian.PutUint64(counter[:], uint64(at.Unix()/30))
	mac := hmac.New(sha1.New, key)
	mac.Write(counter[:])
	sum := mac.Sum(nil)
	off := sum[len(sum)-1] & 0x0f
	return fmt.Sprintf("%06d", (binary.BigEndian.Uint32(sum[off:off+4])&0x7fffffff)%1_000_000)
}

// signInCookieOf picks the pending-sign-in cookie out of a response.
func signInCookieOf(res *response) *http.Cookie {
	for _, c := range (&http.Response{Header: res.header}).Cookies() {
		if c.Name == SignInCookie {
			return c
		}
	}
	return nil
}

func withSignIn(value string) map[string]string {
	return map[string]string{"Cookie": SignInCookie + "=" + value}
}

// enrolOverAPI turns two-step on for a signed-in account the way the account
// page does, and returns the key.
func enrolOverAPI(t *testing.T, h *harness, session string) (string, []string) {
	t.Helper()
	setup := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/setup", cookie: session})
	setup.mustStatus(t, http.StatusOK, "setup")
	var s struct {
		Secret string `json:"secret"`
		URI    string `json:"otpauth_uri"`
		QR     string `json:"qr_svg"`
	}
	setup.into(t, &s)
	if !strings.HasPrefix(s.URI, "otpauth://totp/Zoomies:") || !strings.Contains(s.URI, "zoomies.test") {
		t.Errorf("otpauth address = %q, want it to name the issuer and this instance", s.URI)
	}
	if !strings.HasPrefix(s.QR, "<svg") {
		t.Errorf("qr_svg is not an SVG document: %.40s", s.QR)
	}
	confirm := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/confirm", cookie: session,
		body: map[string]any{"code": codeAt(t, s.Secret, time.Now())}})
	confirm.mustStatus(t, http.StatusOK, "confirm")
	var codes struct {
		RecoveryCodes []string `json:"recovery_codes"`
	}
	confirm.into(t, &codes)
	return s.Secret, codes.RecoveryCodes
}

func TestTwoStepSignInOverTheAPI(t *testing.T) {
	h := newHarness(t)
	u, session := h.user("alice", store.RoleOperator)
	secret, codes := enrolOverAPI(t, h, session)
	if len(codes) != 10 {
		t.Fatalf("%d recovery codes, want 10", len(codes))
	}

	login := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}})
	login.mustStatus(t, http.StatusAccepted, "login with two-step on")
	if login.cookie != nil {
		t.Fatal("the password alone set a session cookie")
	}
	pending := signInCookieOf(login)
	if pending == nil || !pending.HttpOnly || pending.SameSite != http.SameSiteStrictMode || pending.Path != "/api/v1/auth" {
		t.Fatalf("pending sign-in cookie = %+v", pending)
	}
	if pending.MaxAge <= 0 || pending.MaxAge > 300 {
		t.Errorf("pending sign-in cookie lives %ds, want at most five minutes", pending.MaxAge)
	}
	if body := login.json(t); body["two_step"] != "verify" || body["username"] != "alice" {
		t.Errorf("202 body = %v", body)
	}

	// The pending cookie is not a session anywhere.
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", headers: withSignIn(pending.Value)}).
		mustStatus(t, http.StatusUnauthorized, "session with only the pending cookie")

	wrong := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/verify",
		headers: withSignIn(pending.Value), body: map[string]any{"code": "000000"}})
	wrong.mustStatus(t, http.StatusUnauthorized, "a wrong code")
	if !strings.Contains(string(wrong.body), `"field":"code"`) {
		t.Errorf("a wrong code is not pointed at the code field, so the page cannot tell it from an expired sign-in: %s", wrong.body)
	}

	// The confirming code used this step, so the phone's next one is the
	// one a person would type.
	next := codeAt(t, secret, time.Now().Add(30*time.Second))
	ok := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/verify",
		headers: withSignIn(pending.Value), body: map[string]any{"code": next}})
	ok.mustStatus(t, http.StatusOK, "the right code")
	if ok.cookie == nil || ok.cookie.Value == "" {
		t.Fatal("the code step set no session")
	}
	var in struct {
		Identity struct {
			ID string `json:"id"`
		} `json:"identity"`
		RecoveryCodeUsed bool `json:"recovery_code_used"`
	}
	ok.into(t, &in)
	if in.Identity.ID != u.ID || in.RecoveryCodeUsed {
		t.Errorf("sign-in = %+v", in)
	}
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: ok.cookie.Value}).
		mustStatus(t, http.StatusOK, "the new session")

	// The same code on a fresh sign-in is a replay.
	again := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}})
	again.mustStatus(t, http.StatusAccepted, "second login")
	replay := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/verify",
		headers: withSignIn(signInCookieOf(again).Value), body: map[string]any{"code": next}})
	replay.mustStatus(t, http.StatusUnauthorized, "a replayed code")

	// A recovery code stands in, once, and the answer says how many are left.
	rec := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/verify",
		headers: withSignIn(signInCookieOf(again).Value), body: map[string]any{"code": codes[0]}})
	rec.mustStatus(t, http.StatusOK, "a recovery code")
	if body := rec.json(t); body["recovery_code_used"] != true || body["recovery_codes_left"] != float64(9) {
		t.Errorf("recovery sign-in = %v", body)
	}

	// Signed in, the account page sees it on.
	status := h.do(request{method: http.MethodGet, path: "/api/v1/auth/two-step", cookie: ok.cookie.Value})
	status.mustStatus(t, http.StatusOK, "status")
	if body := status.json(t); body["enabled"] != true || body["recovery_codes_left"] != float64(9) || body["available"] != true {
		t.Errorf("status = %v", body)
	}
}

func TestAPendingSignInCannotBeFinishedWithoutItsCookie(t *testing.T) {
	h := newHarness(t)
	_, session := h.user("alice", store.RoleOperator)
	secret, _ := enrolOverAPI(t, h, session)
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}}).
		mustStatus(t, http.StatusAccepted, "login")

	for name, headers := range map[string]map[string]string{
		"no cookie":        nil,
		"a made-up cookie": withSignIn("not-a-real-challenge"),
	} {
		res := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/verify", headers: headers,
			body: map[string]any{"code": codeAt(t, secret, time.Now().Add(30*time.Second))}})
		if res.status != http.StatusUnauthorized || res.cookie != nil {
			t.Errorf("%s: status %d, session %v; want 401 and no session", name, res.status, res.cookie)
		}
	}
}

func TestTheSelfServiceRoutesRefuseATokenAndTakeThePasswordToTurnItOff(t *testing.T) {
	h := newHarness(t)
	_, session := h.user("alice", store.RoleOperator)
	secret, _ := enrolOverAPI(t, h, session)

	tok := h.token("ci", store.RoleAdmin)
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/two-step", token: tok}).
		mustStatus(t, http.StatusForbidden, "status with a token")

	bad := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/disable", cookie: session,
		body: map[string]any{"password": "wrong-password-entirely", "code": codeAt(t, secret, time.Now().Add(30*time.Second))}})
	bad.mustStatus(t, http.StatusUnprocessableEntity, "disable with the wrong password")
	if !strings.Contains(string(bad.body), `"password"`) {
		t.Errorf("the refusal does not point at the password field: %s", bad.body)
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/disable", cookie: session,
		body: map[string]any{"password": testPassword, "code": codeAt(t, secret, time.Now().Add(30*time.Second))}}).
		mustStatus(t, http.StatusNoContent, "disable")
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}}).
		mustStatus(t, http.StatusOK, "login with two-step off")
}

func TestAnAdministratorsTwoStepResetIsAudited(t *testing.T) {
	h := newHarness(t)
	target, session := h.user("alice", store.RoleOperator)
	enrolOverAPI(t, h, session)
	_, adminSession := h.user("root", store.RoleAdmin)

	list := h.do(request{method: http.MethodGet, path: "/api/v1/users", cookie: adminSession})
	list.mustStatus(t, http.StatusOK, "list users")
	if !strings.Contains(string(list.body), `"username":"alice"`) || !strings.Contains(string(list.body), `"two_step_enabled":true`) {
		t.Errorf("the users list does not show alice's two-step: %s", truncate(list.body))
	}

	// A viewer cannot.
	_, viewer := h.user("val", store.RoleViewer)
	h.do(request{method: http.MethodDelete, path: "/api/v1/users/" + target.ID + "/two-step", cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer's reset")

	h.do(request{method: http.MethodDelete, path: "/api/v1/users/" + target.ID + "/two-step", cookie: adminSession}).
		mustStatus(t, http.StatusNoContent, "reset")

	events, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{Actions: []string{"user.two_step_reset"}}, store.Page{})
	if err != nil {
		t.Fatal(err)
	}
	if len(events) != 1 || events[0].TargetID != target.ID || events[0].ActorName != "root" {
		t.Fatalf("audit rows = %+v, want one naming alice's account and the administrator", events)
	}
	if !strings.Contains(events[0].After, `"had_two_step":true`) {
		t.Errorf("the audit row does not say there was something to reset: %s", events[0].After)
	}
	// Her sessions ended, and her password alone signs her in again.
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: session}).
		mustStatus(t, http.StatusUnauthorized, "alice's old session")
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}}).
		mustStatus(t, http.StatusOK, "alice signs in after the reset")
}

func TestRequiringTwoStepSendsASignInToEnrolment(t *testing.T) {
	h := newHarness(t, func(c *config.Config) { c.Security.RequireTwoStep = true })
	h.user("alice", store.RoleOperator)

	login := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alice", "password": testPassword}})
	login.mustStatus(t, http.StatusAccepted, "login")
	if body := login.json(t); body["two_step"] != "enrol" {
		t.Fatalf("202 body = %v, want the enrol step", body)
	}
	pending := signInCookieOf(login).Value

	setup := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/enrol", headers: withSignIn(pending)})
	setup.mustStatus(t, http.StatusOK, "enrol")
	var s struct {
		Secret string `json:"secret"`
	}
	setup.into(t, &s)

	done := h.do(request{method: http.MethodPost, path: "/api/v1/auth/two-step/enrol/confirm", headers: withSignIn(pending),
		body: map[string]any{"code": codeAt(t, s.Secret, time.Now())}})
