		t.Fatalf("AppendJobEvent: %v", err)
	}
	_, cookie := h.user("viewer", store.RoleViewer)

	var timeline struct {
		Items []struct {
			Kind       string `json:"kind"`
			Source     string `json:"source"`
			Message    string `json:"message"`
			RunnerName string `json:"runner_name"`
			At         string `json:"at"`
		} `json:"items"`
	}
