// A refusal quotes values anybody can make as long as a URL; the log line
// that carries them must stay short whatever was sent.
func TestARefusalReasonIsCutShortForTheLog(t *testing.T) {
	long := strings.Repeat("é", 500)
	got := truncateForLog(long, 200)
	if len(got) > 203 || !strings.HasSuffix(got, "...") || !utf8.ValidString(got) {
		t.Fatalf("truncateForLog gave %d bytes (valid UTF-8: %v)", len(got), utf8.ValidString(got))
	}
	if truncateForLog("short", 200) != "short" {
		t.Fatal("a short reason should be left alone")
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// waitForLogTail is waitForStreamTask for a test that cares what backlog the
// agent was told to send, which is what makes a download of a huge log cheap.
func waitForLogTail(t *testing.T, h *harness, agentToken string) (streamID string, tail int) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=1", token: agentToken})
		if resp.status != http.StatusOK {
			t.Fatalf("agent task poll: %d %s", resp.status, resp.body)
		}
		var batch struct {
			Tasks []struct {
				Kind       string `json:"kind"`
				StreamID   string `json:"stream_id"`
				LogOptions struct {
					Tail int
				} `json:"log_options"`
			} `json:"tasks"`
		}
		resp.into(t, &batch)
		for _, task := range batch.Tasks {
			if task.Kind == "stream_logs" && task.StreamID != "" {
				return task.StreamID, task.LogOptions.Tail
			}
		}
	}
	t.Fatal("no stream_logs task was queued within the deadline")
	return "", 0
}

// A download used to be the whole log from its first byte. A caller that wants
// the end of a long build -- an MCP tool diagnosing a failure -- had to read
// everything and keep whatever fitted, which past a size limit is the wrong
// end. The route now takes tail, and the agent is told to send only that.
func TestDownloadingRunnerLogsPassesTheRequestedTailToTheAgent(t *testing.T) {
	for _, tc := range []struct {
		name  string
		query string
		want  int
	}{
		{"no tail is the whole log, as it always was", "", 0},
		{"a tail is the last lines only", "?tail=50", 50},
		{"a negative tail is the whole log rather than an error", "?tail=-3", 0},
		{"something that is not a number is the whole log", "?tail=lots", 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			pool := h.pool(inst, "linux-x64")
			hostID, agentToken := h.agentToken("vm-1")
			host, err := h.st.GetHost(h.ctx, hostID)
			if err != nil {
				t.Fatalf("GetHost: %v", err)
			}
			run := h.runner(pool, host, store.RunnerBusy)
			u, _ := h.user("viewer", store.RoleViewer)

			done := make(chan *response, 1)
			go func() {
				done <- h.do(request{method: http.MethodGet,
					path: "/api/v1/runners/" + run.ID + "/logs/download" + tc.query, cookie: h.session(u)})
			}()

			streamID, tail := waitForLogTail(t, h, agentToken)
			if tail != tc.want {
				t.Errorf("the agent was told to send tail=%d, want %d", tail, tc.want)
			}
			h.do(request{method: http.MethodPost, path: "/api/v1/agent/logs/" + streamID,
				token: agentToken, headers: map[string]string{"Content-Type": "application/octet-stream"},
				rawBody: "the last line\n"})
			if resp := <-done; resp.status != http.StatusOK {
				t.Fatalf("status = %d: %s", resp.status, resp.body)
			}
		})
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// waitForStreamTask polls as an agent would until the controller has queued
// the log relay this request caused, and returns its stream ID.
func waitForStreamTask(t *testing.T, h *harness, agentToken string) string {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/agent/tasks?wait=1", token: agentToken})
		if resp.status != http.StatusOK {
			t.Fatalf("agent task poll: %d %s", resp.status, resp.body)
		}
		var batch struct {
			Tasks []struct {
				Kind     string `json:"kind"`
				StreamID string `json:"stream_id"`
			} `json:"tasks"`
		}
		resp.into(t, &batch)
		for _, task := range batch.Tasks {
			if task.Kind == "stream_logs" && task.StreamID != "" {
				return task.StreamID
			}
		}
	}
	t.Fatal("no stream_logs task was queued within the deadline")
	return ""
}

// A download has to terminate. It is the same relay as the live tail, read
// until it goes quiet rather than followed -- a runner still producing output
// would otherwise stream forever into a file the browser never finishes.
func TestDownloadingRunnerLogsEndsWhenTheOutputDoes(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")

	hostID, agentToken := h.agentToken("vm-1")
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	run := h.runner(pool, host, store.RunnerBusy)
	u, _ := h.user("viewer", store.RoleViewer)

	done := make(chan *response, 1)
	go func() {
		done <- h.do(request{method: http.MethodGet,
			path: "/api/v1/runners/" + run.ID + "/logs/download", cookie: h.session(u)})
	}()

	streamID := waitForStreamTask(t, h, agentToken)
	const body = "the first line\nthe last line of the build\n"
	post := h.do(request{method: http.MethodPost, path: "/api/v1/agent/logs/" + streamID,
		token: agentToken, headers: map[string]string{"Content-Type": "application/octet-stream"},
		rawBody: body})
	if post.status != http.StatusNoContent && post.status != http.StatusOK {
		t.Fatalf("the agent's log POST answered %d: %s", post.status, post.body)
	}

	resp := <-done
	if resp.status != http.StatusOK {
		t.Fatalf("status = %d: %s", resp.status, resp.body)
	}
	if !strings.Contains(string(resp.body), "the last line of the build") {
		t.Fatalf("the download did not carry the output:\n%s", resp.body)
	}

	// It is a file, not a page: the browser must save it under a name that
	// says which runner it came from.
	if ct := resp.header.Get("Content-Type"); !strings.HasPrefix(ct, "text/plain") {
		t.Errorf("Content-Type = %q, want text/plain", ct)
	}
	cd := resp.header.Get("Content-Disposition")
	if !strings.HasPrefix(cd, "attachment;") || !strings.Contains(cd, ".log") {
		t.Errorf("Content-Disposition = %q, want an attachment named .log", cd)
	}
}

// A runner that never reached a host cannot produce output. That is a fact
// about the runner rather than a fault in the server, so it is a 409 carrying
// the controller's own sentence -- not a 500 with a request ID.
func TestDownloadingLogsForARunnerThatCannotProduceThem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	run := h.runner(pool, host, store.RunnerRemoved)
	u, _ := h.user("viewer", store.RoleViewer)

	resp := h.do(request{method: http.MethodGet,
		path: "/api/v1/runners/" + run.ID + "/logs/download", cookie: h.session(u)})
	if resp.status != http.StatusConflict {
		t.Fatalf("status = %d, want 409: %s", resp.status, resp.body)
	}
	if resp.errorMessage(t) == "" {
		t.Fatalf("the refusal said nothing an operator can act on:\n%s", resp.body)
	}

	missing := h.do(request{method: http.MethodGet,
		path: "/api/v1/runners/run_nope/logs/download", cookie: h.session(u)})
	if missing.status != http.StatusNotFound {
		t.Fatalf("status = %d, want 404: %s", missing.status, missing.body)
	}
}

// The download name goes into a Content-Disposition header and then into a
// filesystem, so it is reduced to characters that survive both -- a runner
// name with a slash or a quote in it must not be able to break either.
func TestLogFilenameSurvivesEveryFilesystemAndQuotingRule(t *testing.T) {
	for _, tc := range []struct{ in, want string }{
		{"zoomies-abc123", "zoomies-abc123.log"},
		{"zoomies_4vcpu.ubuntu-24.04", "zoomies_4vcpu.ubuntu-24.04.log"},
		{"../../etc/passwd", "..-..-etc-passwd.log"},
		{`a"quote`, "a-quote.log"},
		{"runner name", "runner-name.log"},
		// A name made entirely of characters that cannot survive would leave
		// nothing at all, and ".log" is not a filename.
		{"///", "---.log"},
		{"", "runner.log"},
	} {
		if got := logFilename(tc.in); got != tc.want {
			t.Errorf("logFilename(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

package api

import (
	"context"
	"hash/fnv"
	"net/http"
	"strconv"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// machineResourceID is the provider's own identifier for a test's machine,
// derived from its name because the store refuses two machines on one resource
// -- which is the constraint that stops two rows believing they own one VM.
func machineResourceID(name string) string {
	sum := fnv.New32a()
	_, _ = sum.Write([]byte(name))
	return strconv.Itoa(100 + int(sum.Sum32()%9000))
}

// machineOn is a machine that has reached a state and, when a host is given,
// enrolled onto it -- which is what makes it a machine with work on it.
func (h *harness) machineOn(p *store.Provider, name string, state store.MachineState, host *store.Host) *store.Machine {
	h.t.Helper()
	m := &store.Machine{
		ProviderID:   p.ID,
		Name:         name,
		State:        state,
		ResourceZone: "zone-a",
		ResourceID:   machineResourceID(name),
		Capacity:     p.MachineCapacity,
		Labels:       store.StringMap{},
	}
	if host != nil {
		m.HostID = host.ID
	}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		h.t.Fatalf("CreateMachine: %v", err)
	}
	return m
}

// A machine exists because demand asked for one. One creation path means one
// accounting path, so there is no route that makes one: a hand-made machine
// would be supply the reconciler would then decide to delete.
func TestThereIsNoWayToCreateAMachineByHand(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/machines", cookie: cookie,
		body: map[string]any{"provider_id": "prv_anything"}})
	if resp.status != http.StatusMethodNotAllowed {
		t.Fatalf("POST /machines answered %d, want 405: %s", resp.status, truncate(resp.body))
	}
}

// Deleting a machine destroys the VM its runners are running on, so the first
// call refuses and says what to do; the second, after a drain, is the short one.
func TestDeletingAMachineWithLiveRunnersIsRefusedUnlessForced(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)

	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-busy", store.MachineReady, host)
	h.runner(pool, host, store.RunnerBusy)

	refused := h.do(request{method: http.MethodDelete, path: "/api/v1/machines/" + m.ID, cookie: cookie})
	refused.mustStatus(t, http.StatusConflict, "delete a machine with a busy runner")
	msg := refused.errorMessage(t)
	if !strings.Contains(msg, "1 runner") {
		t.Errorf("the refusal does not say how many runners are on it: %q", msg)
	}
	if !strings.Contains(msg, "force=true") {
		t.Errorf("the refusal does not say how to insist: %q", msg)
	}

	forced := h.do(request{method: http.MethodDelete, path: "/api/v1/machines/" + m.ID + "?force=true", cookie: cookie})
	forced.mustStatus(t, http.StatusOK, "force-delete a machine")
	var out machineResponse
	forced.into(t, &out)
	if out.State != store.MachineDeleting {
		t.Errorf("the machine is %s rather than deleting; a delete is finished when the resource is gone, not when this returns", out.State)
	}
}

// A quarantined machine's resource may belong to somebody else, which is
// exactly what quarantine means. Deleting it -- forced or not -- would destroy
// another fleet's machine, so the refusal points at release instead.
func TestAQuarantinedMachineIsNeverDeletableAndTheRefusalPointsAtRelease(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-doubtful", store.MachineQuarantined, nil)

	for _, path := range []string{
		"/api/v1/machines/" + m.ID,
		"/api/v1/machines/" + m.ID + "?force=true",
	} {
		resp := h.do(request{method: http.MethodDelete, path: path, cookie: cookie})
		resp.mustStatus(t, http.StatusConflict, "delete a quarantined machine")
		msg := resp.errorMessage(t)
		if !strings.Contains(msg, "release") {
			t.Errorf("the refusal does not point at the escape hatch: %q", msg)
		}
		if !strings.Contains(msg, "zone-a/"+machineResourceID(m.Name)) {
			t.Errorf("the refusal does not name the resource to go and look at: %q", msg)
		}
	}
	row, err := h.st.GetMachine(h.ctx, m.ID)
	if err != nil {
		t.Fatalf("GetMachine: %v", err)
	}
	if row.State != store.MachineQuarantined {
		t.Errorf("the machine moved to %s despite the refusal", row.State)
	}
}

// Release forgets a row and touches nothing, which cannot be undone and cannot
// be checked afterwards -- so the machine's name has to be typed, and the audit
// row keeps the provider's identifiers the database is about to stop holding.
func TestReleasingAMachineNeedsItsNameAndThenForgetsIt(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-doubtful", store.MachineQuarantined, nil)

	wrong := h.do(request{method: http.MethodPost, path: "/api/v1/machines/" + m.ID + "/release", cookie: cookie,
		body: map[string]any{"name": "zoomies-mach-something-else"}})
	wrong.mustStatus(t, http.StatusUnprocessableEntity, "release with the wrong name")
	if msg := wrong.errorMessage(t); !strings.Contains(msg, m.Name) {
		t.Errorf("the refusal does not say what to type: %q", msg)
	}
	if _, err := h.st.GetMachine(h.ctx, m.ID); err != nil {
		t.Fatalf("the machine was forgotten despite the wrong name: %v", err)
	}

	ok := h.do(request{method: http.MethodPost, path: "/api/v1/machines/" + m.ID + "/release", cookie: cookie,
		body: map[string]any{"name": m.Name}})
	ok.mustStatus(t, http.StatusNoContent, "release a machine")
	if _, err := h.st.GetMachine(h.ctx, m.ID); err == nil {
		t.Fatal("the machine is still there after being released")
	}

	audit := h.do(request{method: http.MethodGet, path: "/api/v1/audit?limit=50", cookie: cookie})
	audit.mustStatus(t, http.StatusOK, "audit")
	body := string(audit.body)
	if !strings.Contains(body, "machine.release") {
		t.Error("releasing a machine was not audited")
	}
	if !strings.Contains(body, machineResourceID(m.Name)) {
		t.Error("the audit row does not keep the resource identifier, which is now the only record of it")
	}
}

// A draining machine keeps the work it has and accepts no more. Without the
// cordon the scheduler would go on placing runners onto a host whose VM is
// about to be destroyed, and it would never empty.
func TestDrainingAMachineCordonsItsHost(t *testing.T) {
	h := newHarness(t)
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-leaving", store.MachineReady, host)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/machines/" + m.ID + "/drain", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "drain a machine")
	var out machineResponse
	resp.into(t, &out)
	if out.State != store.MachineDraining {
		t.Errorf("the machine is %s rather than draining", out.State)
	}

	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !got.Cordoned {
		t.Error("the host was not cordoned, so the scheduler would keep placing runners on a machine that is leaving")
	}
}

// Every other road into a machine's deletion cordons its host first, because
// the scheduler's snapshot carries hosts and never machines: an idle machine
// with a queued job matching its pools stays placeable for the whole minutes-long
// delete, and a runner placed in that window dies with the VM.
func TestDeletingAMachineCordonsItsHost(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-idle", store.MachineReady, host)

	resp := h.do(request{method: http.MethodDelete, path: "/api/v1/machines/" + m.ID, cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "delete an idle machine")

	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !got.Cordoned {
		t.Error("the host of a machine being deleted was not cordoned, so the scheduler could place a runner on a VM that is about to be destroyed")
	}
}

// A refused delete must have no side effect: cordoning before the refusal would
// take a busy machine out of service by way of a request that said no.
func TestARefusedMachineDeleteLeavesItsHostUncordoned(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-busy", store.MachineReady, host)
	h.runner(pool, host, store.RunnerBusy)

	resp := h.do(request{method: http.MethodDelete, path: "/api/v1/machines/" + m.ID, cookie: cookie})
	resp.mustStatus(t, http.StatusConflict, "delete a machine with a busy runner")

	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Cordoned {
		t.Error("a refused delete cordoned the host")
	}
}

// A drain the state machine refuses -- only a ready machine can drain -- used to
// cordon the host first and then answer 409, so a request that reported an error
// still took a failed machine's enrolled host out of service, with no audit row.
func TestARefusedMachineDrainLeavesItsHostUncordoned(t *testing.T) {
	h := newHarness(t)
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-broken", store.MachineFailed, host)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/machines/" + m.ID + "/drain", cookie: cookie})
	resp.mustStatus(t, http.StatusConflict, "drain a failed machine")

	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Cordoned {
		t.Error("a refused drain cordoned the host")
	}
}

// A machine's host is not an ordinary host: the VM outlives the row, and an
// operator who deleted it here would go on paying for a machine nothing is
// tracking. The refusal says which act removes the VM as well.
func TestDeletingAHostThatIsAMachineSaysToDeleteTheMachineInstead(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	h.machineOn(prov, "zoomies-mach-serving", store.MachineReady, host)

	refused := h.do(request{method: http.MethodDelete, path: "/api/v1/hosts/" + host.ID, cookie: cookie})
	refused.mustStatus(t, http.StatusConflict, "delete a host that is a machine")
	msg := refused.errorMessage(t)
	for _, want := range []string{host.Name, prov.Name, "force=true"} {
		if !strings.Contains(msg, want) {
			t.Errorf("the refusal does not mention %q: %q", want, msg)
		}
	}

	// Forcing still works; what it does to the VM is the next test's business.
	forced := h.do(request{method: http.MethodDelete, path: "/api/v1/hosts/" + host.ID + "?force=true", cookie: cookie})
	forced.mustStatus(t, http.StatusNoContent, "force-delete a host that is a machine")
}

// The refusal above promises that ?force=true forgets the host and leaves the VM
// running. The machine row's host_id is ON DELETE SET NULL, and the machine loop
// reads a Ready machine with no host as one to release, so a bare host delete
// drained and destroyed the VM -- and any job still on it -- within two passes.
// Forcing has to forget the machine row as well, and audit it, because after
// that the audit row is the only record of the resource.
func TestForceDeletingAMachinesHostLeavesTheVMRunningAndForgetsTheRow(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-serving", store.MachineReady, host)

	forced := h.do(request{method: http.MethodDelete, path: "/api/v1/hosts/" + host.ID + "?force=true", cookie: cookie})
	forced.mustStatus(t, http.StatusNoContent, "force-delete a host that is a machine")

	if row, err := h.st.GetMachine(h.ctx, m.ID); err == nil {
		t.Fatalf("the machine is still recorded as %s, so the machine loop would release the VM the operator was promised would be left running", row.State)
	}

	audit := h.do(request{method: http.MethodGet, path: "/api/v1/audit?limit=50", cookie: cookie})
	audit.mustStatus(t, http.StatusOK, "audit")
	body := string(audit.body)
	if !strings.Contains(body, "machine.release") {
		t.Error("forgetting the machine was not audited")
	}
	if !strings.Contains(body, machineResourceID(m.Name)) {
		t.Error("the audit row does not keep the resource identifier, which is now the only record of it")
	}
}

// A machine already being deleted is the one case where forgetting the row would
// be the destructive act: the delete is under way and the VM is going anyway, so
// dropping the row would abandon a half-finished delete and leak the resource.
func TestForceDeletingTheHostOfAMachineThatIsAlreadyDeletingLeavesTheDeleteRunning(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("zoomies-mach-host")
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-leaving", store.MachineDeleting, host)

	forced := h.do(request{method: http.MethodDelete, path: "/api/v1/hosts/" + host.ID + "?force=true", cookie: cookie})
	forced.mustStatus(t, http.StatusNoContent, "force-delete the host of a deleting machine")

	row, err := h.st.GetMachine(h.ctx, m.ID)
	if err != nil {
		t.Fatalf("the deleting machine was forgotten, abandoning its delete: %v", err)
	}
	if row.State != store.MachineDeleting {
		t.Errorf("the machine is %s, want it left deleting", row.State)
	}
}

// An ordinary host is not a machine, and the check for one must not turn every
// host deletion into a refusal.
func TestDeletingAnOrdinaryHostIsUnaffectedByTheMachineCheck(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	host := h.host("a-machine-somebody-else-made")

	resp := h.do(request{method: http.MethodDelete, path: "/api/v1/hosts/" + host.ID, cookie: cookie})
	resp.mustStatus(t, http.StatusNoContent, "delete an ordinary host")
}

// The machines list is what the Hosts page's band and the provider page both
// read, so its filters have to narrow rather than merely decorate -- and a
// state nobody has heard of is the caller's mistake, named.
func TestTheMachinesListIsFilteredByProviderAndState(t *testing.T) {
	h := newHarness(t)
	viewer, _ := h.user("viewer", store.RoleViewer)
	cookie := h.session(viewer)
	first := h.provider("proxmox-lab")
	second := h.provider("proxmox-dr")
	h.machineOn(first, "zoomies-mach-one", store.MachineReady, nil)
	h.machineOn(first, "zoomies-mach-two", store.MachinePlanned, nil)
	h.machineOn(second, "zoomies-mach-three", store.MachineReady, nil)

	byProvider := h.do(request{method: http.MethodGet, path: "/api/v1/machines?provider=" + first.ID, cookie: cookie})
	byProvider.mustStatus(t, http.StatusOK, "machines by provider")
	var page struct {
		Items []machineResponse `json:"items"`
		Total int               `json:"total"`
	}
	byProvider.into(t, &page)
	if page.Total != 2 {
		t.Errorf("filtering by provider returned %d machines, want 2", page.Total)
	}
	for _, m := range page.Items {
		if m.ProviderID != first.ID {
			t.Errorf("machine %s belongs to %s", m.Name, m.ProviderID)
		}
		if m.ProviderName != first.Name {
			t.Errorf("machine %s does not carry its provider's name, so the grid would show an identifier", m.Name)
		}
	}

	byState := h.do(request{method: http.MethodGet, path: "/api/v1/machines?state=ready", cookie: cookie})
	byState.mustStatus(t, http.StatusOK, "machines by state")
	byState.into(t, &page)
	if page.Total != 2 {
		t.Errorf("filtering by state returned %d machines, want 2", page.Total)
	}

	bad := h.do(request{method: http.MethodGet, path: "/api/v1/machines?state=melted", cookie: cookie})
	bad.mustStatus(t, http.StatusBadRequest, "an unknown machine state")
	if msg := bad.errorMessage(t); !strings.Contains(msg, "quarantined") {
		t.Errorf("the refusal does not list the states there are: %q", msg)
	}
}

// The event stream is how a page follows a machine, and a frame carrying a
// store row rather than the view would repaint it without its provider's name,
// its timeline or whether it is safe to delete.
func TestAMachineFrameIsTheShapeTheRouteReturns(t *testing.T) {
	h := newHarness(t)
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)
	prov := h.provider("proxmox-lab")
	m := h.machineOn(prov, "zoomies-mach-watched", store.MachineReady, nil)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	frames, resp := h.openStream(t, ctx, "/api/v1/events", cookie, nil)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("event stream status %d", resp.StatusCode)
	}

	drained := h.do(request{method: http.MethodPost, path: "/api/v1/machines/" + m.ID + "/drain", cookie: cookie})
	drained.mustStatus(t, http.StatusOK, "drain a machine")

	frame := await(t, frames, "a machine frame", func(f sseFrame) bool {
		return f.event == "machine.updated"
	})
	for _, want := range []string{`"provider_name":"proxmox-lab"`, `"timeline"`, `"safe_to_delete"`} {
		if !strings.Contains(frame.data, want) {
			t.Errorf("the machine frame is not the GET shape; it is missing %s: %s", want, frame.data)
		}
	}
	if strings.Contains(frame.data, "owner_fingerprint") {
		t.Error("the frame carries the ownership fingerprint, which is the mark a delete is checked against")
	}
}

package api

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/go-chi/chi/v5"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/mcp"
	"github.com/eyupio/zoomies/internal/version"
)

// mcpToolActions is the action each MCP tool that changes the fleet needs. A
// token whose role reaches it is offered the tool; one whose role does not is
// not, and is told why if its agent asks anyway. The controller still decides
// each call on its own route -- this only keeps the list an agent chooses from
// honest.
var mcpToolActions = map[string]auth.Action{
	"rerun_job":    auth.ActionJobsRerun,
	"drain_runner": auth.ActionRunnersDrain,
}

// mcpResponseLimit bounds what one tool call reads back from a route. It is
// the stdio server's log limit: a runner's log is the only answer that is ever
// large, and the tool keeps only its tail.
const mcpResponseLimit = 32 << 20

// handleMCP is the fleet over MCP's Streamable HTTP transport, for an agent
// that can reach the controller but cannot, or would rather not, launch
// `zoomies mcp` beside itself -- a cloud session, a hosted agent.
//
// It adds no authority. The caller's bearer token is resolved exactly as the
// API resolves it, and every tool call is handed back to this server's own
// router as the documented route with that same token, so it passes through
// the same role check, scope check, audit trail and access log that
// `zoomies jobs list` does. A session cookie is not accepted: the endpoint is
// for agents, and refusing the cookie means a page the operator happens to
// visit cannot drive it, whatever the browser sends along.
func (s *Server) handleMCP(w http.ResponseWriter, r *http.Request) {
	// The specification asks a server to check Origin, so that a page
	// rebinding its own name to this address cannot reach a server that
	// trusts where a request came from. A bearer token already stops that;
	// this is the second lock the specification asks for, and an agent sends
	// no Origin at all.
	if origin := strings.TrimSpace(r.Header.Get("Origin")); origin != "" && !s.originAllowed(origin) && !s.sameOriginAsRequest(r, origin) {
		forbidden(w, "this MCP request came from "+origin+", which is not this controller's origin. "+
			"Add it to server.allowed_origins if that is deliberate.")
		return
	}
	id, err := s.authenticateMCP(r)
	if err != nil {
		// Before the challenge: on a 500 it would send the client off to start
		// a sign-in that cannot help.
		if errors.Is(err, auth.ErrAuthBackend) {
			s.internal(w, r, "checking your credentials", err)
			return
		}
		// The challenge is what tells an MCP client to ask for credentials
		// rather than give up. With OAuth on it names the metadata that starts
		// a browser sign-in; with it off, an API token is the only way in.
		errCode := ""
		if hasBearer(r) {
			errCode = "invalid_token"
		}
		w.Header().Set("WWW-Authenticate", s.mcpChallenge(r, errCode))
		msg := err.Error() + "; send an API token as Authorization: Bearer zoo_... -- " +
			"create one with `zoomies tokens create --role viewer` or on the API tokens settings page"
		if s.cfg().MCPOAuthEnabled() {
			msg = err.Error() + "; sign in through the client's OAuth flow, whose metadata is at " + s.resourceMetadataURL(r) +
				", or send an API token as Authorization: Bearer zoo_..."
		}
		unauthorized(w, msg)
		return
	}
	if info := infoFrom(r.Context()); info != nil {
		info.identity = id
		info.log = info.log.With("identity", id.String())
	}

	mcp.New(inProcessAPI{s: s, from: r, as: id}, mcp.Options{
		Offer: func(tool string) bool {
			a, ok := mcpToolActions[tool]
			return ok && auth.Allowed(id, a)
		},
		Refusal: func(tool string) string {
			if id.Kind == auth.KindConnection {
				return tool + " changes the fleet, and is not offered to this connection: " + auth.Explain(id, mcpToolActions[tool]) +
					". Disconnect and connect again choosing the operator role to be offered it."
			}
			return tool + " changes the fleet, and is not offered to this token: " + auth.Explain(id, mcpToolActions[tool])
		},
	}).ServeHTTP(w, r)
}

// authenticateMCP resolves /mcp's caller: an MCP access token when OAuth is
// on and the credential is one, and otherwise exactly as the API resolves a
// bearer token.
func (s *Server) authenticateMCP(r *http.Request) (*auth.Identity, error) {
	header := r.Header.Get("Authorization")
	if tok := auth.BearerToken(header); auth.IsMCPAccessToken(tok) && s.cfg().MCPOAuthEnabled() && !s.cfg().Security.DisableAuth {
		return s.auth.AuthenticateMCP(r.Context(), s.oauthPolicy(r), tok, ClientIP(r.Context()))
	}
	return s.auth.Authenticate(r.Context(), auth.AuthInput{Authorization: header, IP: ClientIP(r.Context())})
}

type contextCredentialCheck struct{}

func inProcessIdentity(r *http.Request) *auth.Identity {
	id, _ := r.Context().Value(ctxInProcess).(*auth.Identity)
	return id
}

// inProcessAPI is the REST API as the MCP tools see it from inside the
// controller: each call is a request to this server's own router, carrying the
// MCP request's credential and client address, so nothing about it differs
// from the same call made over the network except the network.
type inProcessAPI struct {
	s    *Server
	from *http.Request
	// as is the /mcp caller. An MCP connection's token is not forwarded: it
	// is accepted on /mcp alone, and the specification forbids passing it on,
	// so the route sees the connection's identity instead.
	as *auth.Identity
}

func (a inProcessAPI) Call(ctx context.Context, method, path string, q url.Values) ([]byte, error) {
	return a.do(ctx, method, path, q, "application/json")
}

func (a inProcessAPI) Stream(ctx context.Context, path, accept string) (io.ReadCloser, error) {
	// A log download ends when the relay goes quiet, so reading it whole is
	// what the stdio server's client does too; there is no connection here to
	// hold open for it.
	body, err := a.do(ctx, http.MethodGet, path, nil, accept)
	if err != nil {
		return nil, err
	}
	return io.NopCloser(bytes.NewReader(body)), nil
}

func (a inProcessAPI) do(ctx context.Context, method, path string, q url.Values, accept string) ([]byte, error) {
	target := "/api/v1" + path
	if len(q) > 0 {
		target += "?" + q.Encode()
	}
	// The tool's context descends from the /mcp request's, which carries the
	// router's own state for that request; left there, the router would take
	// this for the rest of that dispatch rather than a request of its own.
	ctx = context.WithValue(ctx, chi.RouteCtxKey, (*chi.Context)(nil))
	req, err := http.NewRequestWithContext(ctx, method, target, nil)
	if err != nil {
		return nil, err
	}
	// The address and the proxy headers go along so that the client address
	// the audit trail records is the agent's, resolved through the same
	// trusted proxies, rather than this process's own.
	req.RemoteAddr = a.from.RemoteAddr
	req.Host = a.from.Host
	req.TLS = a.from.TLS
	forward := []string{"Authorization", "Forwarded", "X-Forwarded-For", "X-Forwarded-Proto", "X-Forwarded-Host", "X-Real-IP"}
	if a.as != nil && a.as.Kind == auth.KindConnection {
		forward = forward[1:]
		req = req.WithContext(context.WithValue(req.Context(), ctxInProcess, a.as))
		req = req.WithContext(context.WithValue(req.Context(), contextCredentialCheck{}, func(ctx context.Context) (*auth.Identity, error) { return a.s.authenticateMCP(a.from.WithContext(ctx)) }))
	}
	for _, h := range forward {
		if v := a.from.Header.Values(h); len(v) > 0 {
			req.Header[h] = v
		}
	}
	req.Header.Set("Accept", accept)
	req.Header.Set("User-Agent", "zoomies-mcp/"+version.Version)

	rec := &bufferedResponse{header: http.Header{}, limit: mcpResponseLimit}
	a.s.handler.ServeHTTP(rec, req)
	if a.as != nil && a.as.Kind == auth.KindConnection && method != http.MethodGet {
		// The route audits what it did as the connection already; this row
		// says it was an MCP tool that asked, and how the route answered,
		// so a refused attempt is on the record too.
		a.s.auth.Auditor().Act(ctx, a.as, "mcp_connection.call", "mcp_connection", a.as.ID,
			map[string]any{"method": method, "path": target, "status": rec.status})
	}
	if rec.status >= 400 {
		return nil, refusalFrom(rec.status, rec.body.Bytes())
	}
	return rec.body.Bytes(), nil
}

// bufferedResponse collects a route's answer for a tool to read. It stops
// taking bytes at its limit, which ends a log download the way a closed
// connection would.
type bufferedResponse struct {
	header http.Header
	status int
	body   bytes.Buffer
	limit  int
}

var errResponseFull = errors.New("the answer is larger than an MCP tool reads")

func (b *bufferedResponse) Header() http.Header { return b.header }

func (b *bufferedResponse) WriteHeader(status int) {
	if b.status == 0 {
		b.status = status
	}
}

func (b *bufferedResponse) Write(p []byte) (int, error) {
	b.WriteHeader(http.StatusOK)
	room := b.limit - b.body.Len()
	if room <= 0 {
		return 0, errResponseFull
	}
	if len(p) > room {
		b.body.Write(p[:room])
		return room, errResponseFull
	}
	return b.body.Write(p)
}

// mcpRefusal is a route's refusal, carrying the controller's own sentence --
// which role is missing, which field is wrong -- to the agent intact.
type mcpRefusal struct {
	status  int
	message string
}

func (e *mcpRefusal) Error() string   { return e.message }
func (e *mcpRefusal) HTTPStatus() int { return e.status }

func refusalFrom(status int, body []byte) error {
	var envelope errorEnvelope
	msg := ""
	if json.Unmarshal(body, &envelope) == nil {
		msg = envelope.Error.Message
		if envelope.Error.Field != "" {
			msg += " (field " + envelope.Error.Field + ")"
		}
		if envelope.Error.Detail != "" {
			msg += ": " + envelope.Error.Detail
		}
	}
	if msg == "" {
		msg = http.StatusText(status)
	}
	return &mcpRefusal{status: status, message: msg}
}

package api

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The whole of OAuth for /mcp, against the real handlers: discovery, a client
// registering, a person signing in and approving it, the code exchanged with
// PKCE, the token used on /mcp, refreshed, replayed and revoked.

const (
	oauthBase     = "https://zoomies.test"
	oauthResource = oauthBase + "/mcp"
	claudeReturn  = "https://claude.ai/api/mcp/auth_callback"
	testVerifier  = "a-verifier-that-is-long-enough-to-be-accepted-by-rfc-7636-0123456789"
)

// oauthHarness is a controller reached over https, which is where OAuth for
// MCP turns itself on.
func oauthHarness(t *testing.T, opts ...func(*config.Config)) *harness {
	t.Helper()
	return newHarness(t, append([]func(*config.Config){func(c *config.Config) { c.Server.ExternalURL = oauthBase }}, opts...)...)
}

// form posts an application/x-www-form-urlencoded body, as an OAuth client
// does at the token and revocation endpoints.
func (h *harness) form(path string, v url.Values, headers map[string]string) *response {
	h.t.Helper()
	all := map[string]string{"Content-Type": "application/x-www-form-urlencoded"}
	for k, val := range headers {
		all[k] = val
	}
	return h.do(request{method: http.MethodPost, path: path, rawBody: v.Encode(), noOrigin: true, headers: all})
}

func (h *harness) registerClient(redirects ...string) string {
	h.t.Helper()
	return h.registerNamedClient("Claude", redirects...)
}

// registerNamedClient registers a client under a name of its own: the same
// name and redirects are the same client, and are handed the same ID.
func (h *harness) registerNamedClient(name string, redirects ...string) string {
	h.t.Helper()
	resp := h.do(request{method: http.MethodPost, path: "/oauth/register", noOrigin: true,
		body: map[string]any{"client_name": name, "redirect_uris": redirects, "token_endpoint_auth_method": "none"}})
	resp.mustStatus(h.t, http.StatusCreated, "registering a client")
	var out struct {
		ClientID string `json:"client_id"`
		Method   string `json:"token_endpoint_auth_method"`
	}
	resp.into(h.t, &out)
	if out.ClientID == "" || out.Method != "none" {
		h.t.Fatalf("registration must answer a public client ID, got %s", resp.body)
	}
	return out.ClientID
}

// authorize starts a sign-in the way Claude's browser tab does.
func (h *harness) authorize(clientID, redirect string, extra url.Values) *response {
	h.t.Helper()
	q := url.Values{
		"client_id": {clientID}, "redirect_uri": {redirect}, "response_type": {"code"},
		"code_challenge": {auth.PKCEChallenge(testVerifier)}, "code_challenge_method": {"S256"},
		"state": {"opaque-state"}, "scope": {"mcp:read mcp:operate"}, "resource": {oauthResource},
	}
	for k, v := range extra {
		q[k] = v
	}
	return h.do(request{method: http.MethodGet, path: "/oauth/authorize?" + q.Encode(), noOrigin: true})
}

// requestFrom reads the consent page's request ID out of the authorisation
// endpoint's redirect.
func requestFrom(t *testing.T, resp *response) string {
	t.Helper()
	resp.mustStatus(t, http.StatusFound, "the authorisation endpoint")
	loc, err := url.Parse(resp.header.Get("Location"))
	if err != nil || loc.Path != consentPath || loc.Query().Get("request") == "" {
		t.Fatalf("the authorisation endpoint must send the browser to the consent page, got %q", resp.header.Get("Location"))
	}
	return loc.Query().Get("request")
}

// approve decides a request as the signed-in person and returns the code.
func (h *harness) approve(cookie, requestID string, role store.Role) string {
	h.t.Helper()
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/auth/mcp-requests/" + requestID + "/approve", cookie: cookie,
		body: map[string]any{"role": role}})
	resp.mustStatus(h.t, http.StatusOK, "approving")
	var d mcpDecisionResponse
	resp.into(h.t, &d)
	back, err := url.Parse(d.RedirectTo)
	if err != nil {
		h.t.Fatal(err)
	}
	q := back.Query()
	if q.Get("state") != "opaque-state" || q.Get("iss") != oauthBase || q.Get("code") == "" {
		h.t.Fatalf("the redirect must carry the code, the state and the issuer, got %s", d.RedirectTo)
	}
	return q.Get("code")
}

type tokenPair struct {
	AccessToken  string `json:"access_token"`
	RefreshToken string `json:"refresh_token"`
	TokenType    string `json:"token_type"`
	ExpiresIn    int    `json:"expires_in"`
	Scope        string `json:"scope"`
}

func (h *harness) exchange(clientID, code string, extra url.Values, headers map[string]string) *response {
	h.t.Helper()
	v := url.Values{"grant_type": {"authorization_code"}, "code": {code}, "redirect_uri": {claudeReturn},
		"code_verifier": {testVerifier}, "resource": {oauthResource}}
	if clientID != "" {
		v.Set("client_id", clientID)
	}
	for k, val := range extra {
		v[k] = val
	}
	return h.form("/oauth/token", v, headers)
}

func pairFrom(t *testing.T, resp *response) tokenPair {
	t.Helper()
	resp.mustStatus(t, http.StatusOK, "the token endpoint")
	var p tokenPair
	resp.into(t, &p)
	if !strings.HasPrefix(p.AccessToken, auth.MCPAccessTokenPrefix) || !strings.HasPrefix(p.RefreshToken, auth.MCPRefreshTokenPrefix) ||
		p.TokenType != "Bearer" || p.ExpiresIn <= 0 {
		t.Fatalf("the token response is not a bearer pair: %s", resp.body)
	}
	if resp.header.Get("Cache-Control") != "no-store" {
		t.Errorf("a token response must not be cached, got Cache-Control %q", resp.header.Get("Cache-Control"))
	}
	return p
}

func oauthErrorCode(t *testing.T, resp *response) string {
	t.Helper()
	var e struct {
		Error string `json:"error"`
	}
	resp.into(t, &e)
	return e.Error
}

// connect runs the whole flow for a person and returns the pair.
func (h *harness) connect(cookie string, role store.Role) (string, tokenPair) {
	h.t.Helper()
	client := h.registerClient(claudeReturn)
	code := h.approve(cookie, requestFrom(h.t, h.authorize(client, claudeReturn, nil)), role)
	return client, pairFrom(h.t, h.exchange(client, code, nil, nil))
}

func (h *harness) auditActions() []string {
	h.t.Helper()
	rows, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{}, store.Page{Limit: 500})
	if err != nil {
		h.t.Fatal(err)
	}
	var out []string
	for _, r := range rows {
		out = append(out, r.Action)
	}
	return out
}

// A client that knows nothing but the URL finds everything else from the
// 401: the resource metadata it points at names the authorisation server,
// whose metadata names every endpoint and says PKCE is S256.
func TestMCPOAuthDiscoveryStartsFromTheUnauthorisedAnswer(t *testing.T) {
	h := oauthHarness(t)

	anon := h.mcpCall("", "tools/list", nil)
	anon.mustStatus(t, http.StatusUnauthorized, "no credential")
	want := `resource_metadata="` + oauthBase + `/.well-known/oauth-protected-resource/mcp"`
	if ch := anon.header.Get("WWW-Authenticate"); !strings.Contains(ch, want) || !strings.Contains(ch, `scope="mcp:read mcp:operate"`) {
		t.Errorf("the 401 must point at the resource metadata and name the scopes, got %q", ch)
	}

	for _, path := range []string{"/.well-known/oauth-protected-resource", "/.well-known/oauth-protected-resource/mcp"} {
		prm := h.do(request{method: http.MethodGet, path: path, noOrigin: true})
		prm.mustStatus(t, http.StatusOK, path)
		doc := prm.json(t)
		if doc["resource"] != oauthResource {
			t.Errorf("%s: resource must be the MCP endpoint exactly, got %v", path, doc["resource"])
		}
		if servers, _ := doc["authorization_servers"].([]any); len(servers) != 1 || servers[0] != oauthBase {
			t.Errorf("%s: the controller is its own authorisation server, got %v", path, doc["authorization_servers"])
		}
	}

	as := h.do(request{method: http.MethodGet, path: "/.well-known/oauth-authorization-server", noOrigin: true})
	as.mustStatus(t, http.StatusOK, "authorisation server metadata")
	var meta struct {
		Issuer        string   `json:"issuer"`
		Authorize     string   `json:"authorization_endpoint"`
		Token         string   `json:"token_endpoint"`
		Register      string   `json:"registration_endpoint"`
		Revoke        string   `json:"revocation_endpoint"`
		PKCE          []string `json:"code_challenge_methods_supported"`
		AuthMethods   []string `json:"token_endpoint_auth_methods_supported"`
		CIMD          bool     `json:"client_id_metadata_document_supported"`
		ISSParam      bool     `json:"authorization_response_iss_parameter_supported"`
		ResponseTypes []string `json:"response_types_supported"`
	}
	as.into(t, &meta)
	if meta.Issuer != oauthBase || meta.Authorize != oauthBase+"/oauth/authorize" || meta.Token != oauthBase+"/oauth/token" ||
		meta.Register != oauthBase+"/oauth/register" || meta.Revoke != oauthBase+"/oauth/revoke" {
		t.Errorf("the endpoints must all be on the issuer, got %+v", meta)
	}
	if !slices.Equal(meta.PKCE, []string{"S256"}) || !slices.Equal(meta.ResponseTypes, []string{"code"}) {
		t.Errorf("S256 PKCE and the code flow only, got %+v", meta)
	}
	// Claude uses a metadata document only when both of these are said.
	if !meta.CIMD || !slices.Contains(meta.AuthMethods, "none") || !meta.ISSParam {
		t.Errorf("metadata documents, public clients and the iss parameter must be advertised, got %+v", meta)
	}
	for _, m := range []string{"client_secret_basic", "client_secret_post"} {
		if !slices.Contains(meta.AuthMethods, m) {
			t.Errorf("%s must be advertised for an administrator's confidential client, got %v", m, meta.AuthMethods)
		}
	}
}

// The setting off, or the deployment on plain HTTP, and none of it is there:
// the 401 goes back to asking for an API token.
func TestMCPOAuthIsAbsentWhenOff(t *testing.T) {
	off := false
	for name, h := range map[string]*harness{
		"plain http by default": newHarness(t),
		"turned off":            oauthHarness(t, func(c *config.Config) { c.Security.MCPOAuth = &off }),
	} {
		t.Run(name, func(t *testing.T) {
			for _, path := range []string{"/.well-known/oauth-protected-resource", "/.well-known/oauth-authorization-server", "/oauth/authorize"} {
				if r := h.do(request{method: http.MethodGet, path: path, noOrigin: true}); r.status != http.StatusNotFound {
					t.Errorf("GET %s must be 404 with OAuth off, got %d", path, r.status)
				}
			}
			if r := h.do(request{method: http.MethodPost, path: "/oauth/register", noOrigin: true, body: map[string]any{}}); r.status != http.StatusNotFound {
				t.Errorf("registration must be 404 with OAuth off, got %d", r.status)
			}
			anon := h.mcpCall("", "tools/list", nil)
			if ch := anon.header.Get("WWW-Authenticate"); ch != `Bearer realm="zoomies"` {
				t.Errorf("with OAuth off the challenge must not point at metadata that is not there, got %q", ch)
			}
		})
	}
}

// Registration is a public client with PKCE; a redirect that is neither https
// nor loopback is refused; and one address cannot fill the clients table.
func TestMCPOAuthDynamicRegistration(t *testing.T) {
	h := oauthHarness(t)

	for _, tc := range []struct {
		name      string
		redirects []string
		want      int
		code      string
	}{
		{"claude.ai", []string{claudeReturn}, http.StatusCreated, ""},
		{"claude code's loopback", []string{"http://localhost/callback", "http://127.0.0.1/callback"}, http.StatusCreated, ""},
		{"plain http elsewhere", []string{"http://evil.example/callback"}, http.StatusBadRequest, "invalid_redirect_uri"},
		{"a custom scheme", []string{"claude://callback"}, http.StatusBadRequest, "invalid_redirect_uri"},
		{"a fragment", []string{"https://claude.ai/cb#x"}, http.StatusBadRequest, "invalid_redirect_uri"},
		{"none at all", nil, http.StatusBadRequest, "invalid_redirect_uri"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPost, path: "/oauth/register", noOrigin: true,
				body: map[string]any{"client_name": "Claude", "redirect_uris": tc.redirects}})
			resp.mustStatus(t, tc.want, tc.name)
			if tc.code != "" {
				if got := oauthErrorCode(t, resp); got != tc.code {
					t.Errorf("error %q, want %q", got, tc.code)
				}
			}
		})
	}
	if !slices.Contains(h.auditActions(), "mcp_client.register") {
		t.Errorf("a registration must be audited, got %v", h.auditActions())
	}

	// Each one new, because a client registering again as itself is handed
	// its registration back and never counted.
	limited := false
	for i := range 150 {
		r := h.do(request{method: http.MethodPost, path: "/oauth/register", noOrigin: true,
			body: map[string]any{"client_name": fmt.Sprintf("client %d", i), "redirect_uris": []string{claudeReturn}}})
		if r.status == http.StatusTooManyRequests {
			limited = true
			break
		}
	}
	if !limited {
		t.Error("registration must be rate limited per address")
	}
}

// The flow as Claude drives it, end to end, and what the person sees and
// can undo afterwards.
func TestMCPOAuthSignsAPersonInAndTheConnectionActsAsThem(t *testing.T) {
	h := oauthHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	idle := h.runner(pool, h.host("boogie"), store.RunnerIdle)
	u, cookie := h.user("olive", store.RoleOperator)

	client := h.registerClient(claudeReturn)
	reqID := requestFrom(t, h.authorize(client, claudeReturn, nil))

	// Nobody signed in: the consent page's data is not given out, and the
	// UI shows the sign-in form in place.
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/mcp-requests/" + reqID}).mustStatus(t, http.StatusUnauthorized, "no session")
	// An API token is not a person deciding.
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/mcp-requests/" + reqID, token: h.token("t", store.RoleAdmin)}).
		mustStatus(t, http.StatusUnprocessableEntity, "a token")

	view := h.do(request{method: http.MethodGet, path: "/api/v1/auth/mcp-requests/" + reqID, cookie: cookie})
	view.mustStatus(t, http.StatusOK, "the consent view")
	var consent mcpConsentResponse
	view.into(t, &consent)
	if consent.Client.Name != "Claude" || consent.RedirectHost != "claude.ai" || consent.LoopbackOnly ||
		!slices.Equal(consent.Roles, []store.Role{store.RoleViewer, store.RoleOperator}) || consent.SuggestedRole != store.RoleOperator {
		t.Errorf("the consent view must name the client, its redirect host and the roles on offer, got %+v", consent)
	}

	code := h.approve(cookie, reqID, store.RoleOperator)
	pair := pairFrom(t, h.exchange(client, code, nil, nil))
	if pair.Scope != "mcp:read mcp:operate" {
		t.Errorf("an operator connection carries both scopes, got %q", pair.Scope)
	}

	names := h.mcpToolNames(pair.AccessToken)
	if !slices.Contains(names, "drain_runner") || !slices.Contains(names, "get_job") {
		t.Errorf("an operator connection is offered the action tools, got %v", names)
	}
	if r := h.mcpTool(pair.AccessToken, "drain_runner", map[string]any{"runner_id": idle.ID}); r.IsError {
		t.Fatalf("draining through the connection failed: %s", resultText(r))
	}
	if after, _ := h.st.GetRunner(h.ctx, idle.ID); after.State != store.RunnerDraining {
		t.Errorf("the drain must have happened, runner is %s", after.State)
	}
	actions := h.auditActions()
	for _, want := range []string{"mcp_connection.grant", "mcp_connection.call"} {
		if !slices.Contains(actions, want) {
			t.Errorf("audit must record %s, got %v", want, actions)
		}
	}

	var mine list[mcpConnectionResponse]
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/mcp-connections", cookie: cookie}).into(t, &mine)
	if len(mine.Items) != 1 || mine.Items[0].UserID != u.ID || mine.Items[0].ClientName != "Claude" || mine.Items[0].Role != store.RoleOperator {
		t.Fatalf("the person must see their connection, got %+v", mine.Items)
	}

	// Somebody else cannot end it by its ID from their own account page.
	_, other := h.user("oscar", store.RoleOperator)
	h.do(request{method: http.MethodDelete, path: "/api/v1/auth/mcp-connections/" + mine.Items[0].ID, cookie: other}).
		mustStatus(t, http.StatusNotFound, "somebody else's connection")

	h.do(request{method: http.MethodDelete, path: "/api/v1/auth/mcp-connections/" + mine.Items[0].ID, cookie: cookie}).
		mustStatus(t, http.StatusNoContent, "disconnecting")
	h.mcpCall(pair.AccessToken, "tools/list", nil).mustStatus(t, http.StatusUnauthorized, "a disconnected token")
	if r := h.form("/oauth/token", url.Values{"grant_type": {"refresh_token"}, "refresh_token": {pair.RefreshToken}, "client_id": {client}}, nil); r.status != http.StatusBadRequest {
		t.Errorf("a disconnected connection's refresh token must be refused, got %d", r.status)
	}
	if !slices.Contains(h.auditActions(), "mcp_connection.revoke") {
		t.Error("disconnecting must be audited")
	}
}

// Every way an exchange can be wrong, each refused with the error code RFC
// 6749 names.
func TestMCPOAuthRefusesAWrongExchange(t *testing.T) {
	h := oauthHarness(t)
	_, cookie := h.user("olive", store.RoleOperator)
	client := h.registerClient(claudeReturn)
	other := h.registerNamedClient("Another client", claudeReturn)
	fresh := func() string {
		return h.approve(cookie, requestFrom(t, h.authorize(client, claudeReturn, nil)), store.RoleViewer)
	}

	for _, tc := range []struct {
		name  string
		code  func() string
		as    string
		extra url.Values
		want  string
	}{
		{"a wrong verifier", fresh, client, url.Values{"code_verifier": {"another-verifier-that-is-long-enough-to-pass-the-length-check-000"}}, "invalid_grant"},
		{"no verifier", fresh, client, url.Values{"code_verifier": {""}}, "invalid_request"},
		{"a different redirect", fresh, client, url.Values{"redirect_uri": {"https://claude.ai/elsewhere"}}, "invalid_grant"},
		{"a different resource", fresh, client, url.Values{"resource": {"https://elsewhere.test/mcp"}}, "invalid_target"},
		{"another client", fresh, other, nil, "invalid_grant"},
		{"a made-up code", func() string { return auth.MCPCodePrefix + "nothing" }, client, nil, "invalid_grant"},
		{"no grant type", fresh, client, url.Values{"grant_type": {""}}, "invalid_request"},
		{"client credentials", fresh, client, url.Values{"grant_type": {"client_credentials"}}, "unsupported_grant_type"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.exchange(tc.as, tc.code(), tc.extra, nil)
			if resp.status != http.StatusBadRequest {
				t.Fatalf("want 400, got %d: %s", resp.status, resp.body)
			}
			if got := oauthErrorCode(t, resp); got != tc.want {
				t.Errorf("error %q, want %q", got, tc.want)
			}
		})
	}

	// A code works once. The second presentation means somebody else has it,
	// so what the first one bought is revoked too.
	code := fresh()
	first := pairFrom(t, h.exchange(client, code, nil, nil))
	replay := h.exchange(client, code, nil, nil)
	if replay.status != http.StatusBadRequest || oauthErrorCode(t, replay) != "invalid_grant" {
		t.Fatalf("a reused code must be invalid_grant, got %d %s", replay.status, replay.body)
	}
	h.mcpCall(first.AccessToken, "tools/list", nil).mustStatus(t, http.StatusUnauthorized, "a token bought with a replayed code")
	if !slices.Contains(h.auditActions(), "mcp_connection.replay") {
		t.Error("a replayed code must be audited")
	}
	if r := h.form("/oauth/token", url.Values{"grant_type": {"authorization_code"}}, map[string]string{"Content-Type": "application/json"}); r.status != http.StatusBadRequest {
		t.Errorf("a token request that is not a form must be refused, got %d", r.status)
	}
}

// The authorisation endpoint never sends a person to a redirect the client did
// not register; everything else it refuses goes back to the client with the
// error, the state and the issuer.
func TestMCPOAuthAuthorizationRefusals(t *testing.T) {
	h := oauthHarness(t)
	client := h.registerClient(claudeReturn)

	for _, tc := range []struct {
		name     string
		clientID string
		redirect string
		extra    url.Values
		// here: the refusal is shown on the controller's own page.
		here bool
		want string
	}{
		{"an unregistered redirect", client, "https://evil.example/callback", nil, true, "invalid_request"},
		{"an unknown client", "oac_nosuchclient", claudeReturn, nil, true, "invalid_client"},
		{"no PKCE", client, claudeReturn, url.Values{"code_challenge": {""}}, false, "invalid_request"},
		{"plain PKCE", client, claudeReturn, url.Values{"code_challenge_method": {"plain"}}, false, "invalid_request"},
		{"another resource", client, claudeReturn, url.Values{"resource": {"https://elsewhere.test/mcp"}}, false, "invalid_target"},
		{"an unknown scope", client, claudeReturn, url.Values{"scope": {"admin"}}, false, "invalid_scope"},
		{"the implicit flow", client, claudeReturn, url.Values{"response_type": {"token"}}, false, "unsupported_response_type"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.authorize(tc.clientID, tc.redirect, tc.extra)
			resp.mustStatus(t, http.StatusFound, tc.name)
			loc, _ := url.Parse(resp.header.Get("Location"))
			if tc.here {
				if loc.Host != "" || loc.Path != consentPath || loc.Query().Get("error") != tc.want {
					t.Fatalf("must be shown on the controller's own page, got %s", loc)
				}
				if loc.Query().Has("error_description") {
					// Text in that address is rendered on this controller;
					// the page writes its own sentence from the code.
					t.Errorf("the consent page's address must carry the code alone, got %s", loc)
				}
				return
			}
			if !strings.HasPrefix(loc.String(), claudeReturn) {
				t.Fatalf("must go back to the client, got %s", loc)
			}
			q := loc.Query()
			if q.Get("error") != tc.want || q.Get("state") != "opaque-state" || q.Get("iss") != oauthBase {
				t.Errorf("want error %s with state and iss, got %s", tc.want, loc)
			}
		})
	}

	// A person who declines sends the client access_denied.
	_, cookie := h.user("olive", store.RoleViewer)
	reqID := requestFrom(t, h.authorize(client, claudeReturn, nil))
	deny := h.do(request{method: http.MethodPost, path: "/api/v1/auth/mcp-requests/" + reqID + "/deny", cookie: cookie})
	deny.mustStatus(t, http.StatusOK, "declining")
	var d mcpDecisionResponse
	deny.into(t, &d)
	if !strings.Contains(d.RedirectTo, "error=access_denied") {
		t.Errorf("declining must send access_denied, got %s", d.RedirectTo)
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/mcp-requests/" + reqID + "/approve", cookie: cookie}).
		mustStatus(t, http.StatusNotFound, "a request already answered")
}

// Rotation: each refresh spends the refresh token and hands out a new pair;
// presenting a spent one again revokes the whole family, the legitimate
// client's newest tokens included.
func TestMCPOAuthRefreshRotatesAndAReplayEndsTheConnection(t *testing.T) {
	h := oauthHarness(t)
	_, cookie := h.user("olive", store.RoleViewer)
	client, pair := h.connect(cookie, store.RoleViewer)

	refresh := func(tok string) *response {
		return h.form("/oauth/token", url.Values{"grant_type": {"refresh_token"}, "refresh_token": {tok}, "client_id": {client}, "resource": {oauthResource}}, nil)
	}
	second := pairFrom(t, refresh(pair.RefreshToken))
	if second.RefreshToken == pair.RefreshToken || second.AccessToken == pair.AccessToken {
		t.Fatal("a refresh must hand out a new pair")
	}
	if names := h.mcpToolNames(second.AccessToken); !slices.Contains(names, "get_job") {
		t.Errorf("the new access token must work, got %v", names)
	}
	if r := h.form("/oauth/token", url.Values{"grant_type": {"refresh_token"}, "refresh_token": {second.RefreshToken}, "client_id": {client}, "scope": {"mcp:operate"}}, nil); oauthErrorCode(t, r) != "invalid_scope" {
		t.Errorf("a refresh cannot widen a viewer connection, got %s", r.body)
	}

	replay := refresh(pair.RefreshToken)
	if replay.status != http.StatusBadRequest || oauthErrorCode(t, replay) != "invalid_grant" {
		t.Fatalf("a spent refresh token must be invalid_grant, got %d %s", replay.status, replay.body)
	}
	h.mcpCall(second.AccessToken, "tools/list", nil).mustStatus(t, http.StatusUnauthorized, "the family after a replay")
	if r := refresh(second.RefreshToken); r.status != http.StatusBadRequest {
		t.Errorf("the newest refresh token must go with the family, got %d", r.status)
	}
}

