	r := h.do(request{method: http.MethodPost, path: "/oauth/register", noOrigin: true, body: map[string]any{"redirect_uris": []string{claudeReturn}}})
	if r.status != http.StatusForbidden || !strings.Contains(string(r.body), "mcp_open_registration") {
		t.Errorf("registration must be refused naming the setting, got %d %s", r.status, r.body)
	}
	meta := h.do(request{method: http.MethodGet, path: "/.well-known/oauth-authorization-server", noOrigin: true}).json(t)
	if _, ok := meta["registration_endpoint"]; ok || meta["client_id_metadata_document_supported"] != false {
		t.Errorf("closed registration must not be advertised, got %v", meta)
	}
	if loc := h.authorize(early, claudeReturn, nil).header.Get("Location"); !strings.Contains(loc, "error=invalid_client") {
		t.Errorf("a self-registered client must be turned away, got %s", loc)
	}
	if loc := h.authorize("https://claude.ai/oauth/claude-code-client-metadata", "http://localhost:3118/callback", nil).header.Get("Location"); !strings.Contains(loc, "error=invalid_client") {
		t.Errorf("a metadata document must be turned away, got %s", loc)
	}

	_, admin := h.user("ada", store.RoleAdmin)
	var c mcpClientResponse
	h.do(request{method: http.MethodPost, path: "/api/v1/mcp-clients", cookie: admin, body: map[string]any{"name": "Claude"}}).into(t, &c)
	if c.Confidential || c.ClientSecret != "" {
		t.Errorf("a client created without confidential is public, got %+v", c)
	}
	pairFrom(t, h.exchange(c.ClientID, h.approve(admin, requestFrom(t, h.authorize(c.ClientID, claudeReturn, nil)), store.RoleViewer), nil, nil))
}

// The consent routes and connections list only ever describe; they never
// leak a code or a token into a JSON body a page could log.
func TestMCPOAuthConsentViewCarriesNoCredential(t *testing.T) {
	h := oauthHarness(t)
	_, cookie := h.user("olive", store.RoleViewer)
	client := h.registerClient("http://localhost/callback")
	reqID := requestFrom(t, h.authorize(client, "http://localhost:4242/callback", nil))
	body := h.do(request{method: http.MethodGet, path: "/api/v1/auth/mcp-requests/" + reqID, cookie: cookie})
	var v mcpConsentResponse
	body.into(t, &v)
	if !v.LoopbackOnly || v.RedirectHost != "localhost:4242" {
		t.Errorf("a loopback-only client must be flagged, got %+v", v)
	}
	raw, _ := json.Marshal(v)
	if strings.Contains(string(raw), auth.MCPCodePrefix) || strings.Contains(string(raw), "code_challenge") {
		t.Errorf("the consent view must not carry the challenge or a code: %s", raw)
	}
}

// Single sign-on that begins on the consent screen comes back to it, and the
// return address can name nothing else: it is read from a query string, so
// anything wider would be an open redirect on the sign-in path.
func TestSingleSignOnReturnsOnlyToTheConsentScreen(t *testing.T) {
	for addr, want := range map[string]bool{
		"/oauth/consent?request=oar_abcdefghijklm":                        true,
		"/oauth/consent?request=oar_abcdefghijklm&next=https://evil.test": false,
		"/oauth/consent?request=ses_abcdefghijklm":                        false,
		"https://evil.test/oauth/consent?request=oar_abcdefghijklm":       false,
		"//evil.test/oauth/consent?request=oar_abcdefghijklm":             false,
		"/settings?request=oar_abcdefghijklm":                             false,
		"/":                                                               false,
		"":                                                                false,
	} {
		if got := consentReturn(addr); got != want {
			t.Errorf("consentReturn(%q) = %v, want %v", addr, got, want)
		}
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/mcp"
	"github.com/eyupio/zoomies/internal/store"
)

// mcpCall posts one JSON-RPC request to /mcp the way an MCP client does.
func (h *harness) mcpCall(token, method string, params any) *response {
	h.t.Helper()
	return h.do(request{
		method: http.MethodPost, path: "/mcp", token: token, noOrigin: true,
		body:    map[string]any{"jsonrpc": "2.0", "id": 1, "method": method, "params": params},
		headers: map[string]string{"Accept": "application/json, text/event-stream"},
	})
}

type mcpReply struct {
	Result json.RawMessage `json:"result"`
	Error  *mcp.RPCError   `json:"error"`
}

func decodeMCP(t *testing.T, resp *response) mcpReply {
	t.Helper()
	if resp.status != http.StatusOK {
		t.Fatalf("MCP request answered %d: %s", resp.status, resp.body)
	}
	var r mcpReply
	if err := json.Unmarshal(resp.body, &r); err != nil {
		t.Fatalf("the answer was not JSON-RPC: %v\n%s", err, resp.body)
	}
	if r.Error != nil {
		t.Fatalf("protocol error %d: %s", r.Error.Code, r.Error.Message)
	}
	return r
}

func (h *harness) mcpTool(token, name string, args any) mcp.CallResult {
	h.t.Helper()
	var r mcp.CallResult
	if err := json.Unmarshal(decodeMCP(h.t, h.mcpCall(token, "tools/call", map[string]any{"name": name, "arguments": args})).Result, &r); err != nil {
		h.t.Fatal(err)
	}
	return r
}

func (h *harness) mcpToolNames(token string) []string {
	h.t.Helper()
	var list struct {
		Tools []struct {
			Name string `json:"name"`
		} `json:"tools"`
	}
	if err := json.Unmarshal(decodeMCP(h.t, h.mcpCall(token, "tools/list", nil)).Result, &list); err != nil {
		h.t.Fatal(err)
	}
	var names []string
	for _, tool := range list.Tools {
		names = append(names, tool.Name)
	}
	return names
}

func resultText(r mcp.CallResult) string {
	var b strings.Builder
	for _, c := range r.Content {
		b.WriteString(c.Text)
		b.WriteString("\n")
	}
	return b.String()
}

// The endpoint is for agents, which send a token. A session cookie is refused
// even though it would authenticate anywhere else, so that a page the operator
// visits cannot drive an agent's endpoint with the operator's own session.
func TestMCPOverHTTPTakesABearerTokenAndNothingElse(t *testing.T) {
	h := newHarness(t)

	anon := h.mcpCall("", "tools/list", nil)
	if anon.status != http.StatusUnauthorized {
		t.Fatalf("no credential must be 401, got %d: %s", anon.status, anon.body)
	}
	if !strings.HasPrefix(anon.header.Get("WWW-Authenticate"), "Bearer") {
		t.Errorf("a 401 must carry a Bearer challenge so the client knows to ask for a token, got %q", anon.header.Get("WWW-Authenticate"))
	}
	if !strings.Contains(string(anon.body), "tokens create") {
		t.Errorf("the refusal must say how to get a token: %s", anon.body)
	}

	admin, _ := h.user("alice", store.RoleAdmin)
	cookie := h.do(request{
		method: http.MethodPost, path: "/mcp", cookie: h.session(admin),
		body: map[string]any{"jsonrpc": "2.0", "id": 1, "method": "tools/list"},
	})
	if cookie.status != http.StatusUnauthorized {
		t.Errorf("a session cookie must not open the MCP endpoint, got %d", cookie.status)
	}

	if names := h.mcpToolNames(h.token("agent", store.RoleViewer)); !slices.Contains(names, "get_job") {
		t.Errorf("a viewer token must be offered the read-only tools, got %v", names)
	}
}

// The actions follow the token: a tool the role cannot use is not offered, so
// the model never plans around it, and asking anyway says which role is
// missing. Every action tool needs an entry, or a new one would be offered to
// nobody without anyone deciding that.
func TestMCPOverHTTPOffersActionsAsFarAsTheTokensRoleReaches(t *testing.T) {
	for _, tool := range mcp.ActionTools() {
		if _, ok := mcpToolActions[tool]; !ok {
			t.Errorf("MCP action tool %s has no entry in mcpToolActions", tool)
		}
	}

	h := newHarness(t)
	viewer := h.token("reader", store.RoleViewer)
	operator := h.token("actor", store.RoleOperator)

	names := h.mcpToolNames(viewer)
	for tool := range mcpToolActions {
		if slices.Contains(names, tool) {
			t.Errorf("%s must not be offered to a viewer token, got %v", tool, names)
		}
	}
	r := h.mcpTool(viewer, "drain_runner", map[string]any{"runner_id": "run_x"})
	if !r.IsError || !strings.Contains(resultText(r), "operator") {
		t.Errorf("asking for an action the role cannot use must name the role, got %s", resultText(r))
	}

	names = h.mcpToolNames(operator)
	for tool := range mcpToolActions {
		if !slices.Contains(names, tool) {
			t.Errorf("%s must be offered to an operator token, got %v", tool, names)
		}
	}
}

// A tool call is the route itself, with the caller's token: the record comes
// back as the API renders it, and a refusal the route makes -- a busy runner
// is not drained without a person confirming it -- reaches the agent intact.
func TestMCPOverHTTPCallsTheRoutesWithTheCallersToken(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	host := h.host("boogie")
	job := h.job(pool, store.JobQueued)
	idle := h.runner(pool, host, store.RunnerIdle)
	busy := h.runner(pool, host, store.RunnerBusy)
	operator := h.token("actor", store.RoleOperator)

	got := h.mcpTool(operator, "get_job", map[string]any{"job_id": job.ID})
	if got.IsError {
		t.Fatalf("get_job failed: %s", resultText(got))
	}
	var doc struct {
		Job struct {
			ID string `json:"id"`
		} `json:"job"`
		Explanation json.RawMessage `json:"explanation"`
	}
	if err := json.Unmarshal([]byte(got.Content[0].Text), &doc); err != nil || doc.Job.ID != job.ID || len(doc.Explanation) == 0 {
		t.Errorf("get_job must return the job and its explanation, got %s (%v)", got.Content[0].Text, err)
	}

	missing := h.mcpTool(operator, "get_job", map[string]any{"job_id": "job_nope"})
	if !missing.IsError || !strings.Contains(resultText(missing), "list_jobs") {
		t.Errorf("an unknown job must say where the IDs come from, got %s", resultText(missing))
	}

	if r := h.mcpTool(operator, "drain_runner", map[string]any{"runner_id": idle.ID}); r.IsError {
		t.Fatalf("draining an idle runner failed: %s", resultText(r))
	}
	if after, _ := h.st.GetRunner(h.ctx, idle.ID); after.State != store.RunnerDraining {
		t.Errorf("the drain must have happened, runner is %s", after.State)
	}

	r := h.mcpTool(operator, "drain_runner", map[string]any{"runner_id": busy.ID})
	if !r.IsError || !strings.Contains(resultText(r), "five minutes") {
		t.Errorf("a busy runner's drain must come back as the route's own refusal, got %s", resultText(r))
	}
	if after, _ := h.st.GetRunner(h.ctx, busy.ID); after.State != store.RunnerBusy {
		t.Errorf("a refused drain must leave the busy runner alone, it is %s", after.State)
	}
}

// What the transport itself answers, before any tool runs.
func TestMCPOverHTTPAnswersTheTransportsOwnCases(t *testing.T) {
	h := newHarness(t)
	viewer := h.token("reader", store.RoleViewer)

	var init struct {
		ProtocolVersion string `json:"protocolVersion"`
		Instructions    string `json:"instructions"`
	}
	if err := json.Unmarshal(decodeMCP(t, h.mcpCall(viewer, "initialize", map[string]any{"protocolVersion": "2025-06-18"})).Result, &init); err != nil {
		t.Fatal(err)
	}
	if init.ProtocolVersion != "2025-06-18" || !strings.Contains(init.Instructions, "untrusted") {
		t.Errorf("initialize must negotiate and carry the untrusted-data instructions: %+v", init)
	}

	note := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, noOrigin: true,
		body: map[string]any{"jsonrpc": "2.0", "method": "notifications/initialized"}})
	if note.status != http.StatusAccepted || len(note.body) != 0 {
		t.Errorf("a notification must be 202 with no body, got %d %q", note.status, note.body)
	}

	get := h.do(request{method: http.MethodGet, path: "/mcp", token: viewer, noOrigin: true})
	if get.status != http.StatusMethodNotAllowed || get.header.Get("Allow") != http.MethodPost {
		t.Errorf("a GET must be 405 naming POST, not the SPA, got %d %q", get.status, get.header.Get("Allow"))
	}

	old := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, noOrigin: true,
		body:    map[string]any{"jsonrpc": "2.0", "id": 1, "method": "ping"},
		headers: map[string]string{"MCP-Protocol-Version": "1999-01-01"}})
	if old.status != http.StatusBadRequest {
		t.Errorf("an unsupported MCP-Protocol-Version must be 400, got %d", old.status)
	}

	// The specification asks for the Origin check, against DNS rebinding.
	foreign := h.do(request{method: http.MethodPost, path: "/mcp", token: viewer, origin: "https://evil.example",
		body: map[string]any{"jsonrpc": "2.0", "id": 1, "method": "ping"}})
	if foreign.status != http.StatusForbidden {
		t.Errorf("a request from a foreign origin must be 403, got %d", foreign.status)
	}
	if cache := h.mcpCall(viewer, "ping", nil).header.Get("Cache-Control"); cache != "no-store" {
		t.Errorf("an MCP answer carries fleet data and must not be cached, got %q", cache)
	}
}

// A hundred jobs with their steps overflowed a client's output limit at about
// ten. Without them a full page of a hundred has to fit well inside 25k tokens;
// JSON runs at three bytes a token or worse, so 75 KB is the ceiling.
func TestMCPListJobsWithoutStepsFitsAHundredJobsInAModelsContext(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "linux")
	h.releaseJobs(pool, "v1.3.3", 100, 10_000, time.Now().Add(-2*time.Hour))
	viewer := h.token("reader", store.RoleViewer)

	const budget = 25_000 * 3
	summary := h.mcpTool(viewer, "list_jobs", map[string]any{"limit": 100})
	if summary.IsError {
		t.Fatalf("list_jobs failed: %s", resultText(summary))
	}
	text := resultText(summary)
	var page struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal([]byte(text), &page); err != nil || len(page.Items) != 100 {
		t.Fatalf("want 100 jobs, got %d (%v)", len(page.Items), err)
	}
	if _, has := page.Items[0]["steps"]; has {
		t.Errorf("steps must be off by default for MCP: %v", page.Items[0])
	}
	if len(text) > budget {
		t.Errorf("100 summaries are %d bytes, over the %d-byte proxy for 25k tokens", len(text), budget)
	}
	t.Logf("100 job summaries: %d bytes", len(text))

	full := resultText(h.mcpTool(viewer, "list_jobs", map[string]any{"limit": 10, "include_steps": true}))
	if !strings.Contains(full, `"steps":[{`) {
		t.Errorf("include_steps=true must bring the steps back")
	}
}

func TestMCPJobStatsIsOneCallPerReleaseAndTakesDays(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "linux")
	now := time.Now()
	h.releaseJobs(pool, "v1.2.0", 3, 20_000, now.Add(-10*24*time.Hour))
	h.releaseJobs(pool, "v1.3.0", 3, 30_000, now.Add(-2*24*time.Hour))
	viewer := h.token("reader", store.RoleViewer)

	res := h.mcpTool(viewer, "job_stats", map[string]any{"group_by": []string{"controller_version"}, "since": "30d"})
	if res.IsError {
		t.Fatalf("job_stats failed: %s", resultText(res))
	}
	var doc struct {
		Groups []struct {
			Keys map[string]string `json:"keys"`
		} `json:"groups"`
	}
	if err := json.Unmarshal([]byte(resultText(res)), &doc); err != nil || len(doc.Groups) != 2 {
		t.Fatalf("want a group per release, got %s (%v)", resultText(res), err)
	}
	for _, args := range []map[string]any{
		{"group_by": []string{"repo"}},
		{"since": "last tuesday"},
		{"unknown": true},
	} {
		if r := h.mcpTool(viewer, "job_stats", args); !r.IsError {
			t.Errorf("job_stats accepted %v", args)
		}
	}
}

package api

import (
	"fmt"
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	ciBefore = `name: CI

on: [push]

jobs:
  build:
    runs-on: ubuntu-latest      # the cheap one
    steps:
      - uses: actions/checkout@v4
  windows:
    runs-on: windows-latest
    steps:
      - run: build.ps1
  matrix:
    runs-on: ${{ matrix.os }}
    steps:
      - run: make test
`
	releaseBefore = "jobs:\n  ship:\n    runs-on: [ubuntu-22.04]\n"
)

// migrationHarness is a fleet with one Linux pool, two repositories with
// workflows and one without.
func migrationHarness(t *testing.T) (*harness, *store.Installation, string) {
	t.Helper()
	h := newHarness(t)
	inst := h.installation()

	pool := h.pool(inst, "zoomies-linux-x64")
	pool.Labels = store.StringSlice(store.BrandLabels([]string{"zoomies-linux-x64", "linux", "x64"}))
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", ciBefore)
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/release.yml", releaseBefore)
	h.gh.AddWorkflow("acme/api", ".github/workflows/ci.yml", ciBefore)
	h.gh.AddRepo("acme/site")

	_, cookie := h.user("migrator", store.RoleOperator)
	return h, inst, cookie
}

func TestMigrationPlanProposesAMappingAndADiff(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	// Every repository is reported, including the one with nothing to do:
	// "no workflows" is an answer, not an omission.
	if len(plan.Repositories) != 3 {
		t.Fatalf("repositories = %d, want all three", len(plan.Repositories))
	}

	// The server proposed the only pool for the Ubuntu labels, and nothing at
	// all for Windows, because no pool in this fleet runs it.
	if plan.Mapping["ubuntu-latest"] != "zoomies-linux-x64" {
		t.Errorf("mapping = %v, want ubuntu-latest on the Linux pool", plan.Mapping)
	}
	if plan.Mapping["ubuntu-22.04"] != "zoomies-linux-x64" {
		t.Errorf("mapping = %v, want ubuntu-22.04 on the Linux pool", plan.Mapping)
	}
	if _, ok := plan.Mapping["windows-latest"]; ok {
		t.Errorf("mapping = %v, want no proposal for windows-latest: nothing here runs Windows", plan.Mapping)
	}
	if !slices.Contains(plan.Unmapped, "windows-latest") {
		t.Errorf("unmapped = %v, want windows-latest named so the operator can decide", plan.Unmapped)
	}

	// Two repositories, three files, three Ubuntu jobs.
	if plan.Counts.Repos != 2 || plan.Counts.Workflows != 3 || plan.Counts.Jobs != 3 {
		t.Errorf("counts = %+v, want 2 repos / 3 workflows / 3 jobs", plan.Counts)
	}

	widgets := repoPlan(t, plan, "acme/widgets")
	ci := workflowPlan(t, widgets, ".github/workflows/ci.yml")
	if len(ci.Rewrites) != 1 || ci.Rewrites[0].Job != "build" {
		t.Fatalf("rewrites = %+v, want just the build job", ci.Rewrites)
	}
	if ci.Rewrites[0].To != "zoomies-linux-x64" {
		t.Errorf("to = %q, want the pool's label", ci.Rewrites[0].To)
	}
	// The Windows job and the matrix job are both left alone, each with a
	// reason a person can act on.
	if len(ci.Skips) != 2 {
		t.Fatalf("skips = %+v, want the windows and matrix jobs", ci.Skips)
	}
	if !strings.Contains(ci.Diff, "-    runs-on: ubuntu-latest      # the cheap one") ||
		!strings.Contains(ci.Diff, "+    runs-on: zoomies-linux-x64      # the cheap one") {
		t.Errorf("diff does not show the change with its comment intact:\n%s", ci.Diff)
	}

	if len(plan.Pools) != 1 || plan.Pools[0].RunsOn != "zoomies-linux-x64" {
		t.Errorf("pools = %+v, want the one pool with its runs-on value", plan.Pools)
	}
	// Nothing was written.
	if got, _ := h.gh.FileContent("acme/widgets", ".github/workflows/ci.yml"); got != ciBefore {
		t.Error("the plan endpoint modified a workflow")
	}
}

func TestMigrationPlanHonoursTheOperatorsMapping(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{
			"installation_id": inst.ID,
			"repos":           []string{"acme/widgets"},
			"mapping":         map[string]string{"UBUNTU-LATEST": "zoomies-big", "windows-latest": ""},
		}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)
	if len(plan.Repositories) != 1 {
		t.Fatalf("repositories = %d, want only the one asked for", len(plan.Repositories))
	}
	// The key is lowercased and the empty value is dropped, because that is
	// what the browser sends for a label the operator chose not to map.
	if plan.Mapping["ubuntu-latest"] != "zoomies-big" || len(plan.Mapping) != 1 {
		t.Fatalf("mapping = %v, want just the one the operator gave", plan.Mapping)
	}
	// ubuntu-22.04 is now unmapped, so release.yml is left alone.
	release := workflowPlan(t, repoPlan(t, plan, "acme/widgets"), ".github/workflows/release.yml")
	if release.Diff != "" || len(release.Rewrites) != 0 {
		t.Errorf("release.yml changed under a mapping that does not cover it: %+v", release)
	}
}

func TestMigrationPlanRefusesWithNoPool(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	_, cookie := h.user("migrator", store.RoleOperator)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "plan with no pool")
	if msg := resp.errorMessage(t); !strings.Contains(msg, "nowhere to migrate to") {
		t.Errorf("message = %q, want it to say there is no pool", msg)
	}
}

func TestMigrationOpensOnePullRequestPerRepository(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/pull-requests", cookie: cookie,
		body: map[string]any{
			"installation_id": inst.ID,
			"repos":           []string{"acme/widgets", "acme/api", "acme/site"},
			"mapping":         map[string]string{"ubuntu-latest": "zoomies-linux-x64", "ubuntu-22.04": "zoomies-linux-x64"},
		}})
	resp.mustStatus(t, http.StatusOK, "pull requests")

	var out migrationApplyResponse
	resp.into(t, &out)
	if out.Opened != 2 || out.Skipped != 1 || out.Failed != 0 {
		t.Fatalf("outcome = %+v, want two opened and the empty repository skipped", out)
	}

	widgets := result(t, out, "acme/widgets")
	if widgets.Status != "opened" || widgets.PullRequestURL == "" {
		t.Fatalf("acme/widgets = %+v", widgets)
	}
	if widgets.Workflows != 2 || widgets.Jobs != 2 {
		t.Errorf("acme/widgets changed %d files and %d jobs, want 2 and 2", widgets.Workflows, widgets.Jobs)
	}
	if !strings.HasPrefix(widgets.Branch, "zoomies/migrate-runners-") {
		t.Errorf("branch = %q, want a branded, dated branch", widgets.Branch)
	}

	site := result(t, out, "acme/site")
	if site.Status != "skipped" || !strings.Contains(site.Reason, "no .github/workflows") {
		t.Errorf("acme/site = %+v, want a skip that says why", site)
	}

	// The file on GitHub is the rewritten one, and only the runs-on changed.
	got, ok := h.gh.FileContent("acme/widgets", ".github/workflows/ci.yml")
	if !ok {
		t.Fatal("the workflow is gone")
	}
	if !strings.Contains(got, "runs-on: zoomies-linux-x64      # the cheap one") {
		t.Errorf("the committed file did not get the new label:\n%s", got)
	}
	if !strings.Contains(got, "runs-on: windows-latest") || !strings.Contains(got, "runs-on: ${{ matrix.os }}") {
		t.Errorf("the committed file lost a job it should not have touched:\n%s", got)
	}
	if !strings.Contains(got, "on: [push]") || !strings.Contains(got, "- uses: actions/checkout@v4") {
		t.Errorf("the committed file was reformatted:\n%s", got)
	}

	// The default branch is untouched; the work is on its own branch.
	branches := h.gh.Branches("acme/widgets")
	if len(branches) != 2 || !slices.Contains(branches, "main") {
		t.Errorf("branches = %v, want main and the migration branch", branches)
	}
