// An override that names nothing is refused rather than dropped. The operator
// picked that job, and quietly sending it to the consolidated pool instead is
// the kind of surprise this whole wizard is shaped to avoid.
func TestMigrationRefusesAMalformedOverride(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	cases := []struct {
		name     string
		override map[string]any
		wantWord string
	}{
		{"no job", map[string]any{"repo": "acme/widgets", "path": ".github/workflows/ci.yml", "to": "zoomies-big"}, "job"},
		{"no repository", map[string]any{"path": ".github/workflows/ci.yml", "job": "build", "to": "zoomies-big"}, "repo"},
		{"not a workflow file", map[string]any{"repo": "acme/widgets", "path": "Makefile", "job": "build", "to": "zoomies-big"}, "path"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
				body: map[string]any{
					"installation_id": inst.ID,
					"repos":           []string{"acme/widgets"},
					"overrides":       []map[string]any{c.override},
				}})
			resp.mustStatus(t, http.StatusUnprocessableEntity, c.name)
			if msg := resp.errorMessage(t); !strings.Contains(msg, "names one job") {
				t.Errorf("message = %q, want it to say what an override names", msg)
			}
		})
	}

	// The same job answered twice is a bug in whatever built the request, and
	// picking one of the two silently would hide it.
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{
			"installation_id": inst.ID,
			"repos":           []string{"acme/widgets"},
			"overrides": []map[string]any{
				{"repo": "acme/widgets", "path": ".github/workflows/ci.yml", "job": "build", "to": "zoomies-big"},
				{"repo": "acme/widgets", "path": ".github/workflows/ci.yml", "job": "build", "to": "zoomies-linux-x64"},
			},
		}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "the same job twice")
}

// ---------------------------------------------------------------------------

func repoPlan(t *testing.T, plan migrationPlanResponse, repo string) migrate.RepoPlan {
	t.Helper()
	for _, r := range plan.Repositories {
		if r.Repo == repo {
			return r
		}
	}
	t.Fatalf("%s is not in the plan", repo)
	return migrate.RepoPlan{}
}

func workflowPlan(t *testing.T, repo migrate.RepoPlan, path string) migrate.WorkflowPlan {
	t.Helper()
	for _, w := range repo.Workflows {
		if w.Path == path {
			return w
		}
	}
	t.Fatalf("%s is not in the plan for %s", path, repo.Repo)
	return migrate.WorkflowPlan{}
}

func result(t *testing.T, out migrationApplyResponse, repo string) migrationResult {
	t.Helper()
	for _, r := range out.Results {
		if r.Repo == repo {
			return r
		}
	}
	t.Fatalf("%s is not in the results", repo)
	return migrationResult{}
}

// An archived repository is read-only on GitHub, so a pull request against it
// is refused however many rewritable jobs it holds. The plan has to say so on
// the step where the operator chooses -- discovering it in the results, after
// they have walked the whole wizard, is the failure this test exists for.
func TestMigrationPlanMarksAnArchivedRepositoryRatherThanOfferingIt(t *testing.T) {
	h, inst, cookie := migrationHarness(t)
	h.gh.AddWorkflow("acme/legacy", ".github/workflows/ci.yml", ciBefore)
	h.gh.SetArchived("acme/legacy", true)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	legacy := repoPlan(t, plan, "acme/legacy")
	if !legacy.Archived {
		t.Error("acme/legacy is not marked archived, so the wizard would offer it")
	}
	if legacy.Changed() {
		t.Error("an archived repository is reported as one that would change")
	}
	// Its workflows are never read: nothing could be opened against it, and a
	// scan that read them anyway would spend GitHub quota on a greyed-out row.
	if len(legacy.Workflows) != 0 {
		t.Errorf("workflows = %+v, want an archived repository left unread", legacy.Workflows)
	}
	// The headline still counts the two repositories that can actually move.
	if plan.Counts.Repos != 2 || plan.Counts.Jobs != 3 {
		t.Errorf("counts = %+v, want the archived repository left out", plan.Counts)
	}
}

// A repository somebody has already migrated has nothing to do for the same
// reason a repository with no workflows has nothing to do, and they need
// telling apart: one is finished work, the other is work nobody has started.
func TestMigrationPlanSaysARepositoryIsAlreadyOnThisFleet(t *testing.T) {
	h, inst, cookie := migrationHarness(t)
	h.gh.AddWorkflow("acme/infra", ".github/workflows/ci.yml",
		"jobs:\n  build:\n    runs-on: zoomies-linux-x64\n")
	// Somebody else's self-hosted runners are not this fleet, and a repository
	// on them is still one an operator may want to migrate.
	h.gh.AddWorkflow("acme/elsewhere", ".github/workflows/ci.yml",
		"jobs:\n  build:\n    runs-on: [self-hosted, linux]\n")

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	infra := repoPlan(t, plan, "acme/infra")
	if !infra.OnZoomies {
		t.Error("acme/infra runs on this fleet's pool but is not reported as already migrated")
	}
	if infra.Changed() {
		t.Error("a repository already on this fleet would get a pull request")
	}

	if repoPlan(t, plan, "acme/elsewhere").OnZoomies {
		t.Error("a repository on somebody else's self-hosted runners was read as already on Zoomies")
	}
	// A repository with hosted jobs left is still work, whatever else it runs.
	if repoPlan(t, plan, "acme/widgets").OnZoomies {
		t.Error("acme/widgets is entirely on GitHub's runners")
	}
}

// The apply endpoint keeps its own guard. The wizard will not name an archived
// repository, but the endpoint is the API and something else might.
func TestMigrationSkipsAnArchivedRepositoryWithoutTouchingIt(t *testing.T) {
	h, inst, cookie := migrationHarness(t)
	h.gh.AddWorkflow("acme/legacy", ".github/workflows/ci.yml", ciBefore)
	h.gh.SetArchived("acme/legacy", true)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/pull-requests", cookie: cookie,
		body: map[string]any{
			"installation_id": inst.ID,
			"repos":           []string{"acme/widgets", "acme/legacy"},
			"mapping":         map[string]string{"ubuntu-latest": "zoomies-linux-x64", "ubuntu-22.04": "zoomies-linux-x64"},
		}})
	resp.mustStatus(t, http.StatusOK, "pull requests")

	var out migrationApplyResponse
	resp.into(t, &out)
	if out.Opened != 1 || out.Skipped != 1 || out.Failed != 0 {
		t.Fatalf("outcome = %+v, want the archived repository skipped and the other opened", out)
	}
	legacy := result(t, out, "acme/legacy")
	if legacy.Status != "skipped" || !strings.Contains(legacy.Reason, "archived") {
		t.Errorf("acme/legacy = %+v, want a skip that says it is archived", legacy)
	}
	// Skipped means untouched: no branch, and the workflow as it was.
	if branches := h.gh.Branches("acme/legacy"); len(branches) != 1 {
		t.Errorf("branches = %v, want only the default branch", branches)
	}
	if got, _ := h.gh.FileContent("acme/legacy", ".github/workflows/ci.yml"); got != ciBefore {
		t.Error("an archived repository's workflow was rewritten")
	}
}

// TestAnAppThatCannotReadContentsIsNotReportedAsEmptyRepositories is the
// regression test for a wizard that blamed the repositories for its own App.
//
// GitHub answers 404 for contents an App may not read, which is the same answer
// it gives for a repository that genuinely has no .github/workflows. Reading
// that as "no workflows" meant an App installed without the Contents permission
// showed the operator a full organisation in which nothing could be migrated
// and every row said the repository was empty -- while the one thing that would
// have explained it, the missing permission, stayed hidden because the panel
// that names it only appears when something failed to be read.
func TestAnAppThatCannotReadContentsIsNotReportedAsEmptyRepositories(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	// An App created before the migration wizard existed: it can list the
	// organisation's repositories, and see nothing inside them.
	h.gh.SetPermissions(map[string]string{"actions": "read", "metadata": "read"})

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	if len(plan.Repositories) == 0 {
		t.Fatal("no repositories were reported at all")
	}
	for _, repo := range plan.Repositories {
		if repo.Error == "" {
			t.Errorf("%s is reported as read successfully, but the App may not read any repository's contents",
				repo.Repo)
		}
	}

	// And the operator is told what to do about it, which is the whole point:
	// this panel is rendered from the repositories that could not be read, so
	// misfiling them as empty is what used to hide it.
	if len(plan.MissingPermissions) == 0 {
		t.Error("missing_permissions is empty, so nothing tells the operator the App cannot read contents")
	}
	if plan.PermissionHint == "" {
		t.Error("permission_hint is empty, so the operator is not told which permissions to grant")
	}
}

// TestAFullyPermittedAppStillReportsAGenuinelyEmptyRepository is the other
// half: "no workflows" has to keep meaning what it says when the App really can
// look.
func TestAFullyPermittedAppStillReportsAGenuinelyEmptyRepository(t *testing.T) {
	h, inst, cookie := migrationHarness(t)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/migrations/plan", cookie: cookie,
		body: map[string]any{"installation_id": inst.ID}})
	resp.mustStatus(t, http.StatusOK, "plan")

	var plan migrationPlanResponse
	resp.into(t, &plan)

	site := repoPlan(t, plan, "acme/site")
	if site.Error != "" {
		t.Errorf("acme/site error = %q, want none: the App can read it, and it simply has no workflows", site.Error)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// fakeIssuer serves just enough OpenID discovery for NewOIDC to build a
// provider. It never issues a token: these tests are about the half of the
// handshake this server owns.
func fakeIssuer(t *testing.T) *httptest.Server {
	t.Helper()
	mux := http.NewServeMux()
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                srv.URL,
			"authorization_endpoint":                srv.URL + "/authorize",
			"token_endpoint":                        srv.URL + "/token",
			"jwks_uri":                              srv.URL + "/jwks",
			"id_token_signing_alg_values_supported": []string{"RS256"},
		})
	})
	return srv
}

func oidcHarness(t *testing.T) *harness {
	t.Helper()
	issuer := fakeIssuer(t)
	return newHarness(t, func(c *config.Config) {
		c.OIDC = config.OIDC{Enabled: true, Issuer: issuer.URL, ClientID: "zoomies", ClientSecret: "secret"}
	})
}

// loginError is the reason a failed sign-in was sent back to the login page with.
func loginError(t *testing.T, res *response) string {
	t.Helper()
	if res.status != http.StatusFound {
		t.Fatalf("status = %d, want a redirect to the login page; body %s", res.status, res.body)
	}
	loc, err := url.Parse(res.header.Get("Location"))
	if err != nil || loc.Path != "/login" {
		t.Fatalf("Location = %q, want /login?error=...", res.header.Get("Location"))
	}
	return loc.Query().Get("error")
}

// The callback must only finish a handshake in the browser that started it.
// The server remembering the state proves the handshake began here; the cookie
// proves it began in this browser -- without it, an attacker could start their
// own sign-in, keep the callback URL, and have a victim load it, signing the
// victim in as the attacker.
func TestOIDCCallbackIsBoundToTheBrowserThatStartedIt(t *testing.T) {
	h := oidcHarness(t)
	if h.api.oidcFailure() != nil {
		t.Fatalf("single sign-on did not set up: %v", h.api.oidcFailure())
	}

	start := h.do(request{method: http.MethodGet, path: "/api/v1/auth/oidc/start"})
	if start.status != http.StatusFound {
		t.Fatalf("start: status = %d, want 302; body %s", start.status, start.body)
	}
	to, err := url.Parse(start.header.Get("Location"))
	if err != nil {
		t.Fatalf("start: Location %q: %v", start.header.Get("Location"), err)
	}
	state := to.Query().Get("state")
	if state == "" {
		t.Fatalf("start: no state in %s", to)
	}
	var cookie *http.Cookie
	for _, c := range (&http.Response{Header: start.header}).Cookies() {
		if c.Name == oidcStateCookie {
			cookie = c
		}
	}
	if cookie == nil || cookie.Value != state || !cookie.HttpOnly {
		t.Fatalf("start: state cookie = %+v, want an HttpOnly cookie carrying %q", cookie, state)
	}

	callback := "/api/v1/auth/oidc/callback?code=abc&state=" + url.QueryEscape(state)

	// No cookie: a link somebody else made.
	reason := loginError(t, h.do(request{method: http.MethodGet, path: callback}))
	if !strings.Contains(reason, "did not start in this browser") {
		t.Fatalf("without the cookie the callback was not refused; reason %q", reason)
	}

	// The wrong cookie: a browser mid-way through a different sign-in.
	reason = loginError(t, h.do(request{method: http.MethodGet, path: callback,
		headers: map[string]string{"Cookie": oidcStateCookie + "=someone-elses"}}))
	if !strings.Contains(reason, "did not start in this browser") {
		t.Fatalf("with another browser's cookie the callback was not refused; reason %q", reason)
	}

	// The right cookie: the check passes and the handshake proceeds to the
	// token exchange, which the fake issuer refuses. That failure, and not
	// the browser check, is what comes back -- so the refusals above did not
	// spend the state.
	reason = loginError(t, h.do(request{method: http.MethodGet, path: callback,
		headers: map[string]string{"Cookie": oidcStateCookie + "=" + state}}))
	if strings.Contains(reason, "did not start in this browser") || strings.Contains(reason, "already been used") {
		t.Fatalf("with its own cookie the browser was refused: %q", reason)
	}
}

// The single sign-on start endpoint is unauthenticated and mints a fresh
// entry in a bounded state cache on every call, so an attacker who can reach
// it can fill that cache in one burst and lock every real sign-in out with
// ErrTooManyPendingSignIns until the ten-minute TTL expires. The address is
// rate-limited on the login limiter for that reason -- both endpoints begin a
// sign-in -- and the refusal carries the Retry-After the browser can wait on.
func TestOIDCStartIsRateLimited(t *testing.T) {
	h := newHarness(t, func(c *config.Config) {
		issuer := fakeIssuer(t)
		c.OIDC = config.OIDC{Enabled: true, Issuer: issuer.URL, ClientID: "zoomies", ClientSecret: "secret"}
		c.Security.RateLimitLogins = 2
	})
	if h.api.oidcFailure() != nil {
		t.Fatalf("single sign-on did not set up: %v", h.api.oidcFailure())
	}
	for i := 0; i < 2; i++ {
		res := h.do(request{method: http.MethodGet, path: "/api/v1/auth/oidc/start"})
		if res.status != http.StatusFound {
			t.Fatalf("attempt %d: status = %d, want 302 while inside the limit", i+1, res.status)
		}
	}
	res := h.do(request{method: http.MethodGet, path: "/api/v1/auth/oidc/start"})
	if res.status != http.StatusTooManyRequests {
		t.Fatalf("status = %d, want 429 once the limit is spent; body %s", res.status, res.body)
	}
	if res.header.Get("Retry-After") == "" {
		t.Errorf("no Retry-After on the refusal: %v", res.header)
	}
}

// With single sign-on on, an administrator can make an account ahead of its
// owner's first sign-in, which links it by username. The CLI and the Users
// panel both offer this; the API has to actually allow it.
func TestCreateUserWithoutPasswordWhenSSOIsOn(t *testing.T) {
	h := oidcHarness(t)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	created := h.do(request{method: http.MethodPost, path: "/api/v1/users", cookie: cookie,
		body: map[string]any{"username": "alex", "role": "operator"}})
	created.mustStatus(t, http.StatusCreated, "create an SSO-only account")
	var alex userResponse
	created.into(t, &alex)
	if alex.MustChangePassword {
		t.Error("an account with no password has none to change")
	}

	// It cannot be signed in to with a password, and the refusal gives nothing
	// away: an account with no password has nothing that could prove it is
	// yours, so saying "this one uses SSO" would just enumerate the ones that
	// do. The reason is in the controller's log and the audit trail instead.
	login := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "alex", "password": testPassword}})
	login.mustStatus(t, http.StatusUnauthorized, "password login to an SSO-only account")
	unknown := h.do(request{method: http.MethodPost, path: "/api/v1/auth/login",
		body: map[string]any{"username": "nobody-at-all", "password": testPassword}})
	if login.errorMessage(t) != unknown.errorMessage(t) {
		t.Errorf("the refusals differ, which enumerates SSO accounts:\n sso:     %s\n unknown: %s",
			login.errorMessage(t), unknown.errorMessage(t))
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"slices"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// Anybody signed in manages their own API tokens -- the CLI and a script of
// their own are ordinary work -- and never at a role above their own. They see
// and revoke only theirs; an administrator still sees and revokes everybody's.
func TestAnyoneSignedInManagesTheirOwnTokensAndOnlyThose(t *testing.T) {
	h := newHarness(t)
	admin, adminCookie := h.user("admin", store.RoleAdmin)
	_, viewerCookie := h.user("vera", store.RoleViewer)
	_, otherCookie := h.user("otto", store.RoleOperator)

	mint := func(cookie, name, role string) createdTokenResponse {
		t.Helper()
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
			body: map[string]any{"name": name, "role": role, "expires_in": "720h"}})
		resp.mustStatus(t, http.StatusCreated, "minting "+name)
		var out createdTokenResponse
		resp.into(t, &out)
		return out
	}
	list := func(cookie string) []string {
		t.Helper()
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/tokens", cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "listing tokens")
		var out struct {
			Items []tokenResponse `json:"items"`
		}
		resp.into(t, &out)
		var names []string
		for _, tk := range out.Items {
			names = append(names, tk.Name)
		}
		slices.Sort(names)
		return names
	}

	vera := mint(viewerCookie, "vera-laptop", "viewer")
	otto := mint(otherCookie, "otto-script", "operator")
	adminTok := mint(adminCookie, "admin-ci", "admin")
	if adminTok.UserID != admin.ID {
		t.Errorf("a token must say whose it is: user_id %q, want %s", adminTok.UserID, admin.ID)
	}

	// Never above the caller's own role.
	above := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: viewerCookie,
		body: map[string]any{"name": "escalate", "role": "operator"}})
	above.mustStatus(t, http.StatusUnprocessableEntity, "a viewer minting an operator token")

	if got := list(viewerCookie); !slices.Equal(got, []string{"vera-laptop"}) {
		t.Errorf("a viewer sees %v, want only their own", got)
	}
	if got := list(adminCookie); !slices.Equal(got, []string{"admin-ci", "otto-script", "vera-laptop"}) {
		t.Errorf("an administrator sees %v, want everybody's", got)
	}

	// Somebody else's token is not there, to a caller who may only manage
	// their own -- a 404 rather than a 403, which would confirm it exists.
	h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + otto.ID, cookie: viewerCookie}).
		mustStatus(t, http.StatusNotFound, "a viewer revoking somebody else's token")
	h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + vera.ID, cookie: viewerCookie}).
		mustStatus(t, http.StatusNoContent, "a viewer revoking their own")
	h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + otto.ID, cookie: adminCookie}).
		mustStatus(t, http.StatusNoContent, "an administrator revoking somebody else's")

	// Purging reaches only the caller's own, unless they may manage everybody's.
	h.do(request{method: http.MethodPost, path: "/api/v1/tokens/purge", cookie: viewerCookie, body: map[string]any{"all": true}}).
		mustStatus(t, http.StatusForbidden, "a viewer purging everybody's")
	own := h.do(request{method: http.MethodPost, path: "/api/v1/tokens/purge", cookie: viewerCookie, body: map[string]any{}})
	own.mustStatus(t, http.StatusOK, "a viewer purging their own")
	var purged purgeTokensResponse
	own.into(t, &purged)
	if len(purged.Deleted) != 1 || purged.Deleted[0].ID != vera.ID {
		t.Errorf("a viewer's purge deleted %+v, want only their own revoked token", purged.Deleted)
	}
	if got := list(adminCookie); !slices.Contains(got, "otto-script") {
		t.Errorf("a viewer's purge must leave other people's spent tokens alone, left %v", got)
	}

	// Every step is on the record.
	actions := h.auditActions()
	for _, want := range []string{"token.create", "token.revoke", "token.delete"} {
		if !slices.Contains(actions, want) {
			t.Errorf("no %s audit row among %v", want, actions)
		}
	}
}

// Signing out everywhere else ends the other sessions and every MCP
// connection, and leaves this browser signed in.
func TestSigningOutOtherSessionsEndsThemAndMCPConnections(t *testing.T) {
	h := oauthHarness(t)
	u, here := h.user("olive", store.RoleOperator)
	elsewhere := h.session(u)
	_, pair := h.connect(here, store.RoleViewer)

	resp := h.do(request{method: http.MethodPost, path: "/api/v1/auth/logout-others", cookie: here})
	resp.mustStatus(t, http.StatusOK, "signing out other sessions")
	var out logoutOthersResponse
	resp.into(t, &out)
	if out.MCPConnectionsEnded != 1 {
		t.Errorf("mcp_connections_ended = %d, want 1", out.MCPConnectionsEnded)
	}
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: here}).
		mustStatus(t, http.StatusOK, "this browser after signing out the others")
	h.do(request{method: http.MethodGet, path: "/api/v1/auth/session", cookie: elsewhere}).
		mustStatus(t, http.StatusUnauthorized, "another browser after being signed out")
	if _, err := h.ctrl.Auth().AuthenticateMCP(h.ctx, auth.OAuthPolicy{Issuer: oauthBase, OpenRegistration: true}, pair.AccessToken, ""); err == nil {
		t.Error("the MCP access token must stop working")
	}
	for _, want := range []string{"auth.logout_others", "mcp_connection.revoke_all"} {
		if !slices.Contains(h.auditActions(), want) {
			t.Errorf("no %s audit row", want)
		}
	}

	// An API token has no sessions of its own to end.
	tok := h.token("script", store.RoleOperator)
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/logout-others", token: tok}).
		mustStatus(t, http.StatusForbidden, "an API token signing out other sessions")
}

// A password change ends the account's MCP connections as well as its other
// sessions, through the API as through the service.
func TestChangingThePasswordEndsMCPConnections(t *testing.T) {
	h := oauthHarness(t)
	_, cookie := h.user("olive", store.RoleOperator)
	_, pair := h.connect(cookie, store.RoleViewer)
	h.do(request{method: http.MethodPost, path: "/api/v1/auth/password", cookie: cookie,
		body: map[string]any{"old_password": testPassword, "new_password": "an entirely different passphrase"}}).
		mustStatus(t, http.StatusNoContent, "changing the password")
	if _, err := h.ctrl.Auth().AuthenticateMCP(h.ctx, auth.OAuthPolicy{Issuer: oauthBase, OpenRegistration: true}, pair.AccessToken, ""); err == nil {
		t.Error("the MCP access token must stop working after a password change")
	}
}

// The sign-in button says what the operator chose, or else the issuer's host.
func TestTheSignInButtonSaysWhatTheOperatorChose(t *testing.T) {
	for _, tc := range []struct {
		label, want string
	}{
		{"", "Sign in with "},
		{"  Sign in with Okta  ", "Sign in with Okta"},
	} {
		issuer := fakeIssuer(t)
		h := newHarness(t, func(c *config.Config) {
			c.OIDC = config.OIDC{Enabled: true, Issuer: issuer.URL, ClientID: "zoomies", ClientSecret: "secret", Label: tc.label}
		})
		var meta metaResponse
		h.do(request{method: http.MethodGet, path: "/api/v1/meta"}).into(t, &meta)
		if tc.label == "" {
