func TestTrustedProxyParsing(t *testing.T) {
	if _, err := parseTrustedProxies([]string{"10.0.0.0/8", "192.0.2.7", "::1"}); err != nil {
		t.Fatalf("parseTrustedProxies: %v", err)
	}
	_, err := parseTrustedProxies([]string{"the load balancer"})
	if err == nil {
		t.Fatal("a nonsense CIDR was accepted")
	}
	if !strings.Contains(err.Error(), "trusted_proxies") {
		t.Errorf("the error does not name the setting: %v", err)
	}
}

// The cloudflare token must expand to Cloudflare's published ranges, so a
// connection from any edge address is trusted without copying CIDRs about.
func TestTrustedProxyCloudflareTokenExpandsToThePublishedRanges(t *testing.T) {
	nets, err := parseTrustedProxies([]string{"cloudflare"})
	if err != nil {
		t.Fatalf("parseTrustedProxies: %v", err)
	}
	if len(nets) != len(config.CloudflareCIDRs) {
		t.Fatalf("expanded to %d networks, want the %d published ranges", len(nets), len(config.CloudflareCIDRs))
	}
	for _, addr := range []string{"104.16.0.1", "162.158.5.5", "2606:4700::1"} {
		ip := net.ParseIP(addr)
		if !slices.ContainsFunc(nets, func(n *net.IPNet) bool { return n.Contains(ip) }) {
			t.Errorf("Cloudflare edge address %s is not trusted by the token", addr)
		}
	}
	// And an address outside the ranges stays untrusted, or the token would
	// open the trust boundary wider than Cloudflare.
	if ip := net.ParseIP("192.0.2.7"); slices.ContainsFunc(nets, func(n *net.IPNet) bool { return n.Contains(ip) }) {
		t.Error("a non-Cloudflare address is trusted by the token")
	}
}

// freeAddr returns a loopback address nothing is listening on.
func freeAddr(t *testing.T) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("finding a free port: %v", err)
	}
	addr := ln.Addr().String()
	if err := ln.Close(); err != nil {
		t.Fatalf("closing the probe listener: %v", err)
	}
	return addr
}

func waitForServer(t *testing.T, url string) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		resp, err := http.Get(url)
		if err == nil {
			resp.Body.Close()
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatalf("the server never came up at %s", url)
}

func waitForTLS(t *testing.T, client *http.Client, url string) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	var last error
	for time.Now().Before(deadline) {
		resp, err := client.Get(url)
		if err == nil {
			resp.Body.Close()
			return
		}
		last = err
		time.Sleep(20 * time.Millisecond)
	}
	t.Fatalf("the TLS server never came up at %s: %v", url, last)
}

func containsString(in []string, want string) bool {
	for _, v := range in {
		if v == want {
			return true
		}
	}
	return false
}

// TestMountPathCollisionsAreRefused turns a configuration mistake into a
// message rather than a panic from the router.
func TestMountPathCollisionsAreRefused(t *testing.T) {
	cases := []struct {
		name  string
		apply func(*config.Config)
		says  string
	}{
		{"webhook over the API", func(c *config.Config) { c.GitHub.WebhookPath = "/api/v1/pools" }, "github.webhook_path"},
		{"webhook at the root", func(c *config.Config) { c.GitHub.WebhookPath = "/" }, "the UI"},
		{"metrics over health", func(c *config.Config) { c.Metrics.Path = "/healthz" }, "metrics.path"},
		{"metrics over the webhook", func(c *config.Config) { c.Metrics.Path = "/webhooks/github" }, "metrics.path"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cfg := config.Default()
			tc.apply(cfg)
			if err := checkMountPaths(cfg); err == nil {
				t.Fatal("the collision was accepted")
			} else if !strings.Contains(err.Error(), tc.says) {
				t.Errorf("the error does not name %q: %v", tc.says, err)
			}
		})
	}
	if err := checkMountPaths(config.Default()); err != nil {
		t.Fatalf("the default configuration was refused: %v", err)
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// settingsBody is the part of the settings page these tests read.
type settingsBody struct {
	Settings []struct {
		Key      string `json:"key"`
		Scope    string `json:"scope"`
		Editable bool   `json:"editable"`
		Reason   string `json:"reason"`
	} `json:"settings"`
	ConfigPath          string   `json:"config_path"`
	DatabasePath        string   `json:"database_path"`
	EventSubscribers    int      `json:"event_subscribers"`
	RestartRequiredKeys []string `json:"restart_required_keys"`
}

func settingsFor(t *testing.T, h *harness, role store.Role) settingsBody {
	t.Helper()
	u, _ := h.user(string(role)+"-caller", role)
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/settings", cookie: h.session(u)})
	if resp.status != http.StatusOK {
		t.Fatalf("GET /settings as %s = %d: %s", role, resp.status, resp.body)
	}
	var out settingsBody
	if err := json.Unmarshal(resp.body, &out); err != nil {
		t.Fatalf("decoding the settings page: %v", err)
	}
	return out
}

// An instance one team operates while another uses the fleet is the shape the
// platform role exists for. There, what the process binds, trusts, stores and
// logs on its own machine is not the fleet's business -- so an administrator
// is not shown those keys at all, rather than shown them locked. A locked
// field still says where the backups go.
func TestAFleetAdministratorIsNotShownThePlatformsSettings(t *testing.T) {
	h := newHarness(t)

	asAdmin := settingsFor(t, h, store.RoleAdmin)
	for _, s := range asAdmin.Settings {
		if s.Scope == "platform" {
			t.Errorf("an administrator was shown %q, which is the platform's", s.Key)
		}
	}
	// And the keys it does get are real ones, so a filter that returned
	// nothing at all would not pass this.
	var sawFleet bool
	for _, s := range asAdmin.Settings {
		if s.Key == "scheduler.interval" {
			sawFleet = true
		}
	}
	if !sawFleet {
		t.Error("an administrator was shown no scheduler keys; the fleet's own settings are theirs")
	}

	// The platform sees both halves: on a single-team instance this is what
	// an administrator saw before the role existed.
	asPlatform := settingsFor(t, h, store.RolePlatform)
	var platformKeys, fleetKeys int
	for _, s := range asPlatform.Settings {
		switch s.Scope {
		case "platform":
			platformKeys++
		case "instance":
			fleetKeys++
		}
	}
	if platformKeys == 0 || fleetKeys == 0 {
		t.Errorf("the platform saw %d platform and %d fleet keys; it should see both", platformKeys, fleetKeys)
	}
	if len(asPlatform.Settings) <= len(asAdmin.Settings) {
		t.Errorf("the platform saw %d settings and an administrator %d; the platform sees more",
			len(asPlatform.Settings), len(asAdmin.Settings))
	}
}

// The paths and the subscriber count describe the machine the process is on,
// which on an operated instance belongs to whoever runs it. A fleet's
// administrator has no use for a path on somebody else's host.
func TestAFleetAdministratorIsNotToldWhereTheProcessKeepsItsFiles(t *testing.T) {
	h := newHarness(t)

	asAdmin := settingsFor(t, h, store.RoleAdmin)
	if asAdmin.ConfigPath != "" {
		t.Errorf("an administrator was told the configuration file is at %q", asAdmin.ConfigPath)
	}
	if asAdmin.DatabasePath != "" {
		t.Errorf("an administrator was told the database is at %q", asAdmin.DatabasePath)
	}
	if asAdmin.EventSubscribers != 0 {
		t.Errorf("an administrator was told there are %d event subscribers", asAdmin.EventSubscribers)
	}

	// A key the caller was never shown must not survive in a list of key
	// names either: naming one there reads as a bug in the page.
	for _, k := range asAdmin.RestartRequiredKeys {
		if strings.HasPrefix(k, "server.") || strings.HasPrefix(k, "backup.") || strings.HasPrefix(k, "retention.") {
			t.Errorf("restart_required_keys named %q, a setting the caller was not shown", k)
		}
	}

	asPlatform := settingsFor(t, h, store.RolePlatform)
	if asPlatform.DatabasePath == "" {
		t.Error("the platform was not told where its own database is")
	}
}

// The bootstrap keys are not platform-scoped -- they are not stored anywhere
// a scope could apply to -- but their values are the database file and the
// key file. Blanking database_path while database.path carried the same
// string in the same response is the leak the browser-level audience test
// found, so this pins it where it is cheapest to run.
func TestAFleetAdministratorIsNotShownTheDatabaseOrKeyFile(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)

	for _, path := range []string{"/api/v1/settings", "/api/v1/diagnostics/bundle"} {
		resp := h.do(request{method: http.MethodGet, path: path, cookie: h.session(admin)})
		if resp.status != http.StatusOK {
			t.Fatalf("GET %s as admin = %d: %s", path, resp.status, resp.body)
		}
		for _, leak := range []string{"database.path", `"database":`, "encryption_key_file", h.ctrl.Store().Path()} {
			if leak != "" && strings.Contains(string(resp.body), leak) {
				t.Errorf("GET %s told an administrator %q", path, leak)
			}
		}
	}

	asPlatform := settingsFor(t, h, store.RolePlatform)
	var sawDatabase bool
	for _, s := range asPlatform.Settings {
		sawDatabase = sawDatabase || s.Key == "database.path"
	}
	if !sawDatabase {
		t.Error("the platform was not shown database.path; it is theirs to see")
	}
}

// The refusal is the half an operator acts on: a settings page that says
// "not editable" with no reason is what sends somebody to the source.
func TestAnAdministratorChangingAPlatformSettingIsToldWhoseItIs(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)

	resp := h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(admin),
		body: map[string]any{"server.bind": "0.0.0.0:9999"},
	})
	if resp.status != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d, want 422: %s", resp.status, resp.body)
	}
	if !strings.Contains(string(resp.body), "whoever runs this controller") {
		t.Errorf("the refusal does not say whose the setting is: %s", resp.body)
	}
	// And it did not take effect.
	if got := h.ctrl.Config().Server.Bind; got == "0.0.0.0:9999" {
		t.Errorf("the bind address was changed to %q by somebody who may not change it", got)
	}

	// The same change from the platform is ordinary work.
	plat, _ := h.user("operator-of-record", store.RolePlatform)
	ok := h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(plat),
		body: map[string]any{"server.bind": "127.0.0.1:9191"},
	})
	if ok.status != http.StatusOK {
		t.Fatalf("the platform could not change its own listener: %d %s", ok.status, ok.body)
	}
}

// The audience split on the page is only worth as much as the narrowest way
// out of it. An export is one click from the settings page and carries every
// key somebody has set, so an administrator who cannot read the instance's
// bind address on the page must not be able to read it out of the download.
func TestAnAdministratorsExportCarriesOnlyTheFleetsSettings(t *testing.T) {
	h := newHarness(t)

	// Something set at each scope, so neither half is absent by accident.
	plat, _ := h.user("operator-of-record", store.RolePlatform)
	set := h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(plat),
		body: map[string]any{"backup.directory": "/var/lib/zoomies/backups", "scheduler.interval": "12s"},
	})
	if set.status != http.StatusOK {
		t.Fatalf("seeding the settings: %d %s", set.status, set.body)
	}

	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/settings/export", cookie: h.session(admin)})
	if resp.status != http.StatusOK {
		t.Fatalf("export as admin = %d: %s", resp.status, resp.body)
	}
	body := string(resp.body)
	if strings.Contains(body, "/var/lib/zoomies/backups") {
		t.Errorf("an administrator's export carries the platform's backup directory:\n%s", body)
	}
	if !strings.Contains(body, "12s") {
		t.Errorf("an administrator's export lost the fleet's own scheduler interval:\n%s", body)
	}

	// The platform's own export is whole: it is the instance's configuration,
	// and it is what a restore is started from.
	whole := h.do(request{method: http.MethodGet, path: "/api/v1/settings/export", cookie: h.session(plat)})
	if whole.status != http.StatusOK {
		t.Fatalf("export as platform = %d: %s", whole.status, whole.body)
	}
	if !strings.Contains(string(whole.body), "/var/lib/zoomies/backups") {
		t.Error("the platform's export is missing its own backup directory")
	}
}

// The support bundle renders the same configuration tree the settings page
// does, so it answers the same way. A bundle is the third way out of the
// audience split, after the page and the export, and an operator collecting
// one for a bug report should not be the way an instance's bind address
// reaches whoever asked for it.
func TestAnAdministratorsSupportBundleLeavesOutThePlatformsConfiguration(t *testing.T) {
	h := newHarness(t)

	plat, _ := h.user("operator-of-record", store.RolePlatform)
	set := h.do(request{
		method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(plat),
		body: map[string]any{"backup.directory": "/var/lib/zoomies/backups"},
	})
	if set.status != http.StatusOK {
		t.Fatalf("seeding: %d %s", set.status, set.body)
	}

	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(admin)})
	if resp.status != http.StatusOK {
		t.Fatalf("bundle as admin = %d: %s", resp.status, resp.body)
	}
	if strings.Contains(string(resp.body), "/var/lib/zoomies/backups") {
		t.Error("an administrator's support bundle carries the platform's backup directory")
	}

	var doc struct {
		Instance struct {
			ConfigPath   string `json:"config_path"`
			DatabasePath string `json:"database_path"`
		} `json:"instance"`
	}
	if err := json.Unmarshal(resp.body, &doc); err != nil {
		t.Fatalf("decoding the bundle: %v", err)
	}
	if doc.Instance.DatabasePath != "" {
		t.Errorf("the bundle told an administrator the database is at %q", doc.Instance.DatabasePath)
	}

	// The platform's own bundle is the whole instance, which is what makes it
	// worth collecting.
	whole := h.do(request{method: http.MethodGet, path: "/api/v1/diagnostics/bundle", cookie: h.session(plat)})
	if !strings.Contains(string(whole.body), "/var/lib/zoomies/backups") {
		t.Error("the platform's own bundle is missing its backup directory")
	}
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// fieldRefusal returns the message a 422 carries for one field, or "".
func fieldRefusal(t *testing.T, body []byte, field string) string {
	t.Helper()
	var env struct {
		Errors []fieldError `json:"errors"`
	}
	if err := json.Unmarshal(body, &env); err != nil {
		t.Fatalf("decoding the refusal: %v\n%s", err, body)
	}
	for _, e := range env.Errors {
		if e.Field == field {
			return e.Message
		}
	}
	return ""
}

// The threat the guard exists for is somebody with settings rights, not the
// person who runs the process, aiming the controller at its own
// neighbourhood. So a write through the settings page is refused even though
// the same value in the file would only be warned about -- and the refusal
// names the key and the switch that would admit it.
func TestWritingAPrivateOutboundURLThroughTheSettingsIsRefused(t *testing.T) {
	for _, tc := range []struct {
		field string
		body  map[string]any
	}{
		{"github.api_base_url", map[string]any{"github.api_base_url": "https://10.0.0.9/api/v3"}},
		{"capacity_demand.destination_url", map[string]any{"capacity_demand.destination_url": "http://169.254.169.254/latest"}},
		{"agent.runner_download_url", map[string]any{"agent.runner_download_url": "http://127.0.0.1:8000/runner"}},
		{"oidc.issuer", map[string]any{"oidc.enabled": true, "oidc.issuer": "https://192.168.10.4/realms/fleet", "oidc.client_id": "zoomies"}},
	} {
		t.Run(tc.field, func(t *testing.T) {
			h := newHarness(t)
			admin, _ := h.user("admin", store.RolePlatform)
			resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(admin), body: tc.body})
			resp.mustStatus(t, http.StatusUnprocessableEntity, "write a private outbound URL")
			msg := fieldRefusal(t, resp.body, tc.field)
			if !strings.Contains(msg, tc.field) || !strings.Contains(msg, "security.allow_private_egress") {
				t.Errorf("the refusal does not name %s and the switch: %q\n%s", tc.field, msg, resp.body)
			}
		})
	}
}

// Turning single sign-on on starts dialling an issuer that is already
// stored, so it is refused as though the issuer had been written.
func TestTurningSingleSignOnOnWithAPrivateIssuerIsRefused(t *testing.T) {
	h := newHarness(t, func(c *config.Config) {
		c.OIDC.Issuer = "https://192.168.10.4/realms/fleet"
		c.OIDC.ClientID = "zoomies"
	})
	admin, _ := h.user("admin", store.RolePlatform)
	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(admin),
		body: map[string]any{"oidc.enabled": true}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "turn on single sign-on at a LAN issuer")
	if msg := fieldRefusal(t, resp.body, "oidc.enabled"); !strings.Contains(msg, "oidc.issuer") {
		t.Errorf("the refusal does not say it is the issuer: %q\n%s", msg, resp.body)
	}
}

// With the platform's switch on, the same write goes through.
func TestAllowingPrivateEgressAdmitsTheSettingsWrite(t *testing.T) {
	h := newHarness(t, allowPrivateEgress)
	admin, _ := h.user("admin", store.RolePlatform)
	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: h.session(admin),
		body: map[string]any{"github.api_base_url": "https://10.0.0.9/api/v3"}})
	resp.mustStatus(t, http.StatusOK, "write a LAN Enterprise Server once allowed")
	if got := h.ctrl.Config().GitHub.APIBaseURL; !strings.Contains(got, "10.0.0.9") {
		t.Errorf("github.api_base_url = %q after an admitted write", got)
	}
}

// An import is a write through the API too: its preview marks the row, and
// applying it is refused.
func TestAnImportNamingAPrivateOutboundURLIsRefused(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RolePlatform)
	cookie := h.session(admin)
	document := "github:\n  api_base_url: https://10.0.0.9/api/v3\n"

	preview := h.do(request{method: http.MethodPost, path: "/api/v1/settings/import", cookie: cookie,
		body: map[string]any{"document": document, "dry_run": true}})
	preview.mustStatus(t, http.StatusOK, "dry run")
	var out importResponse
	preview.into(t, &out)
	var row *importChange
	for i := range out.Changes {
		if out.Changes[i].Key == "github.api_base_url" {
			row = &out.Changes[i]
		}
	}
	if row == nil || row.Action != importRefusedAction || !strings.Contains(row.Reason, "security.allow_private_egress") {
		t.Fatalf("the preview does not refuse the row by the switch: %+v", row)
	}

	applied := h.do(request{method: http.MethodPost, path: "/api/v1/settings/import", cookie: cookie,
		body: map[string]any{"document": document}})
	applied.mustStatus(t, http.StatusUnprocessableEntity, "apply")
	if got := h.ctrl.Config().GitHub.APIBaseURL; strings.Contains(got, "10.0.0.9") {
		t.Errorf("a refused import changed github.api_base_url to %q", got)
	}
}

package api

import (
	"errors"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// Every setting this API accepts is one a running controller can change
// without a restart, and each has a shape. A round trip through all of them is
// what stops one being added to the vocabulary with no checking behind it.
func TestEverySettableKeyRoundTrips(t *testing.T) {
	h := newHarness(t)
	// Platform rather than admin: this list spans both audiences -- log.level
	// and the retention windows are the platform's, the scheduler keys the
	// fleet's -- and what it is checking is the round trip, not the gate.
	admin, _ := h.user("admin", store.RolePlatform)
	cookie := h.session(admin)

	settings := map[string]any{
		"log.level":                      "debug",
		"github.poll_interval":           "45s",
		"scheduler.interval":             "10s",
		"scheduler.scale_up_delay":       "0s",
		"scheduler.max_runner_lifetime":  "6h",
		"scheduler.provision_timeout":    "4m",
		"scheduler.max_creates_per_tick": 7,
		"retention.jobs":                 "720h",
		"retention.runners":              "168h",
		"retention.scaling_events":       "24h",
		"retention.samples":              "48h",
		"retention.webhooks":             "12h",
		"images.refresh_interval":        "30m",
		"updates.check_interval":         "24h",
	}

	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie, body: settings})
	if resp.status != http.StatusOK {
		t.Fatalf("status = %d: %s", resp.status, resp.body)
	}

	cfg := h.ctrl.Config()
	if cfg.Log.Level != "debug" {
		t.Errorf("log level = %q, want debug", cfg.Log.Level)
	}
	if cfg.GitHub.PollInterval.String() != "45s" {
		t.Errorf("poll interval = %s, want 45s", cfg.GitHub.PollInterval)
	}
	if cfg.Scheduler.MaxCreatesPerTick != 7 {
		t.Errorf("max creates per tick = %d, want 7", cfg.Scheduler.MaxCreatesPerTick)
	}
	if cfg.Scheduler.MaxRunnerLifetime.String() != "6h0m0s" {
		t.Errorf("max runner lifetime = %s, want 6h", cfg.Scheduler.MaxRunnerLifetime)
	}
	if cfg.Retention.Webhooks.String() != "12h0m0s" {
		t.Errorf("webhook retention = %s, want 12h", cfg.Retention.Webhooks)
	}
	if cfg.Updates.CheckInterval.String() != "24h0m0s" {
		t.Errorf("update check interval = %s, want 24h", cfg.Updates.CheckInterval)
	}
}

// A request is refused as a whole before any part of it has taken effect. A
// patch that half-applied would leave the controller in a state the operator
// never asked for and cannot see.
func TestASettingsPatchIsAllOrNothing(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(admin)
	before := h.ctrl.Config().Log.Level

	resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
		body: map[string]any{"log.level": "debug", "scheduler.interval": "not a duration"}})
	if resp.status != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d, want 422: %s", resp.status, resp.body)
	}
	if got := h.ctrl.Config().Log.Level; got != before {
		t.Fatalf("log level = %q after a refused patch, want %q untouched", got, before)
	}
}

// Each refusal names what is wrong with the value, because "invalid" leaves an
// operator guessing at which of the fourteen keys they got wrong and how.
func TestSettingsRefusalsSayWhatIsWrongWithTheValue(t *testing.T) {
	h := newHarness(t)
	// Platform: this exercises keys on both sides of the audience split,
	// and its subject is the behaviour, not who may reach it.
	admin, _ := h.user("admin", store.RolePlatform)
	cookie := h.session(admin)

	for _, tc := range []struct {
		name string
		body map[string]any
		want string
	}{
		{"an unknown key", map[string]any{"nonsense.key": "1s"}, "not a setting"},
		{"a log level that is not one", map[string]any{"log.level": "chatty"}, "is not a log level; use debug, info, warn or error"},
		{"a level that is not even a string", map[string]any{"log.level": 3}, "expected a string"},
		{"a duration that is not one", map[string]any{"retention.jobs": "a while"}, "is not a duration"},
		{"a negative duration", map[string]any{"retention.jobs": "-1h"}, "cannot be negative"},
		// A poll interval of one millisecond is a denial of service against
		// GitHub, not a configuration choice.
		{"a poll interval below the floor", map[string]any{"github.poll_interval": "1ms"}, "too short"},
		{"a negative cap", map[string]any{"scheduler.max_creates_per_tick": -1}, "cannot be negative"},
		{"a fractional cap", map[string]any{"scheduler.max_creates_per_tick": 1.5}, "whole number"},
		{"a cap that is not a number at all", map[string]any{"scheduler.max_creates_per_tick": true}, "whole number"},
		{"a cap written as words", map[string]any{"scheduler.max_creates_per_tick": "many"}, "whole number"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resp := h.do(request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie, body: tc.body})
			if resp.status != http.StatusUnprocessableEntity {
				t.Fatalf("status = %d, want 422: %s", resp.status, resp.body)
			}
			if !strings.Contains(string(resp.body), tc.want) {
				t.Fatalf("the refusal must say %q:\n%s", tc.want, resp.body)
			}
		})
	}
}

// A whole number sent as a string is what a script written by hand produces,
// and refusing it would be a distinction without a difference.
func TestASettingsCapMayBeWrittenAsAString(t *testing.T) {
