// TestSecretsAreNeverInAResponse is the one property no schema check can
// enforce, because a leaked secret would arrive in a field that does exist.
func TestSecretsAreNeverInAResponse(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	u, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(u)

	// Mint credentials whose plaintext we know, then look for it everywhere.
	tokenPlain := h.token("ci", store.RoleAdmin)
	joinResp := h.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: cookie,
		body: map[string]any{"ttl": "15m", "capacity": 2}})
	joinResp.mustStatus(t, http.StatusCreated, "create join token")
	var join createJoinTokenResponse
	joinResp.into(t, &join)
	if join.Token == "" {
		t.Fatal("the join token was not returned at creation, which is the one time it can be")
	}
	if !strings.Contains(join.Command, join.Token) {
		t.Error("the ready-to-paste command does not carry the token")
	}

	// A Proxmox API token, in the shape a hypervisor actually issues one, so a
	// hit is a leak rather than a coincidence.
	const proxmoxToken = "zoomies@pve!ci=9f1c0e2a-7b44-4d18-9f0a-nobody-may-ever-see"
	created := h.do(request{method: http.MethodPost, path: "/api/v1/providers", cookie: cookie,
		body: map[string]any{"kind": "fake", "name": "proxmox-lab", "endpoint": "https://pve.example.com:8006",
			"credential": proxmoxToken, "settings": map[string]string{"zone": "zone-a"}}})
	created.mustStatus(t, http.StatusCreated, "create provider")
	var prov struct {
		ID string `json:"id"`
	}
	created.into(t, &prov)

	secrets := []string{tokenPlain, join.Token, "PRIVATE KEY", "webhook-secret", testKey, proxmoxToken}
	paths := []string{
		"/api/v1/installations",
		"/api/v1/installations/" + inst.ID,
		// A provider's credential reaches a hypervisor, and the row it is
		// sealed in is read by every page that lists providers.
		"/api/v1/providers",
		"/api/v1/providers/" + prov.ID,
		"/api/v1/tokens",
		"/api/v1/join-tokens",
		"/api/v1/users",
		"/api/v1/settings",
		"/api/v1/audit",
		// The bundle is on this list because it is the others put together:
		// a document assembled from secret-free sections is only secret-free
		// while every section still is, and this is what notices when one
		// stops being.
		"/api/v1/diagnostics/bundle",
	}
	for _, path := range paths {
		resp := h.do(request{method: http.MethodGet, path: path, cookie: cookie})
		resp.mustStatus(t, http.StatusOK, path)
		for _, secret := range secrets {
			if secret != "" && strings.Contains(string(resp.body), secret) {
				t.Errorf("%s leaked a secret (%q...)", path, secret[:min(8, len(secret))])
			}
		}
		// Nor the hashes: they are as good as the credential for an attacker
		// who can replay them against the store's own lookup.
		for _, field := range []string{"token_hash", "password_hash", "private_key", "webhook_secret"} {
			if strings.Contains(string(resp.body), `"`+field+`"`) {
				t.Errorf("%s has a %s field", path, field)
			}
		}
	}
}

// TestSecretsAreNeverInAFailure is the other side of the coin from
// TestSecretsAreNeverInAResponse, which walks eight admin reads on the success
// path. A response that succeeded has been thought about; the ones that leak
// are the ones nobody was looking at.
//
// It covers what a refusal answers with, what the fleet's own resources carry,
// what goes out on the event stream, what /metrics exposes, the audit rows
// written when something fails, and the controller's own log -- which is read
// by more people than the API is, shipped to wherever logs are shipped, and
// outlives the request that produced it.
func TestSecretsAreNeverInAFailure(t *testing.T) {
	h := newHarness(t, allowPrivateEgress)
	admin, _ := h.user("root", store.RoleAdmin)
	cookie := h.session(admin)

	// Distinctive plaintexts, so that a hit is a leak and not a coincidence.
	const (
		appKey     = "-----BEGIN RSA PRIVATE KEY-----\nMIIEowIBAAKCAQEAtheAppKeyNobodyMayEverSee\n-----END RSA PRIVATE KEY-----"
		keyMarker  = "theAppKeyNobodyMayEverSee"
		hookSecret = "webhook-hmac-nobody-may-ever-see"
		password   = "the-operators-own-password-12345"
		// The credential a Proxmox API token is: it reaches a hypervisor, so
		// a leak of it is a leak of every machine on the cluster.
		proxmoxToken = "zoomies@pve!ci=9f1c0e2a-7b44-4d18-9f0a-nobody-may-ever-see"
	)

	created := h.do(request{method: http.MethodPost, path: "/api/v1/installations", cookie: cookie,
		body: map[string]any{
			"app_id": h.gh.AppID(), "installation_id": h.gh.InstallationID(),
			"target": "acme", "target_type": "org", "api_base_url": h.gh.URL(),
			"private_key": appKey, "webhook_secret": hookSecret,
		}})
	created.mustStatus(t, http.StatusCreated, "create installation")
	var inst struct {
		ID string `json:"id"`
	}
	created.into(t, &inst)

	madeProvider := h.do(request{method: http.MethodPost, path: "/api/v1/providers", cookie: cookie,
		body: map[string]any{"kind": "fake", "name": "proxmox-lab", "endpoint": "https://pve.example.com:8006",
			"credential": proxmoxToken, "settings": map[string]string{"zone": "zone-a"}}})
	madeProvider.mustStatus(t, http.StatusCreated, "create provider")
	var prov struct {
		ID string `json:"id"`
	}
	madeProvider.into(t, &prov)

	pool := h.pool(&store.Installation{ID: inst.ID}, "linux-x64")
	hostID, agentToken := h.agentToken("vm-1")
	host, err := h.st.GetHost(h.ctx, hostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	run := h.runner(pool, host, store.RunnerBusy)
	apiToken := h.token("ci", store.RoleAdmin)

	joinResp := h.do(request{method: http.MethodPost, path: "/api/v1/join-tokens", cookie: cookie,
		body: map[string]any{"ttl": "15m", "capacity": 2}})
	joinResp.mustStatus(t, http.StatusCreated, "create join token")
	var join createJoinTokenResponse
	joinResp.into(t, &join)

	// Spent here, so that the probe below is refused rather than quietly
	// enrolling a host and asserting nothing.
	spend := h.do(request{method: http.MethodPost, path: "/api/v1/agent/join",
		body: map[string]any{"protocol_version": 1, "join_token": join.Token, "name": "vm-spender",
			"capacity": 1, "os": "linux", "arch": "amd64", "version": "test"}})
	spend.mustStatus(t, http.StatusOK, "spending the join token")

	secrets := []struct {
		what  string
		value string
	}{
		{"the App private key", keyMarker},
		{"the installation's webhook secret", hookSecret},
		{"an operator's password", password},
		{"a host's agent token", agentToken},
		// The hash as well as the credential. A hash is as good as the token
		// to anyone who can replay it against the store's own lookup, and it
		// is the form that is actually on the row -- so it is what leaks when
		// a store row is rendered where a view belongs.
		{"a host's agent token hash", cryptox.HashToken(agentToken)},
		{"an API token", apiToken},
		{"a join token", join.Token},
		{"the instance encryption key", testKey},
		{"a provider's API token", proxmoxToken},
	}
	seen := func(t *testing.T, what string, body []byte) {
		t.Helper()
		for _, secret := range secrets {
			if secret.value != "" && strings.Contains(string(body), secret.value) {
				t.Errorf("%s carries %s", what, secret.what)
			}
		}
	}

	// --- What a refusal answers with. -----------------------------------
	t.Run("error bodies", func(t *testing.T) {
		// GitHub refusing everything, so the paths that talk to it fail.
		h.gh.SetError("/", http.StatusUnauthorized, "the App is not installed here")
		t.Cleanup(h.gh.ClearErrors)

		for _, probe := range []struct {
			what string
			req  request
			// reportsInBody marks the routes that answer 200 and describe the
			// failure in the payload rather than refusing outright. Verify is
			// one: "we asked GitHub and GitHub said no" is a successful check
			// with a bad answer, and the answer is where a quoted credential
			// would end up.
			reportsInBody bool
		}{
			// The key is in the request that is refused, which is the case
			// most likely to echo it back: a validator quoting what it was
			// given is an ordinary and helpful thing to write.
			{"a rejected installation carrying a key", request{method: http.MethodPost, path: "/api/v1/installations", cookie: cookie,
				body: map[string]any{"app_id": 0, "installation_id": 0, "target": "", "target_type": "",
					"private_key": appKey, "webhook_secret": hookSecret}}, false},
			{"a failed verify", request{method: http.MethodPost, path: "/api/v1/installations/" + inst.ID + "/verify", cookie: cookie}, true},
			// The credential is in the body that is refused, which is the case
			// most likely to echo it back: a validator quoting what it was
			// given is an ordinary and helpful thing to write.
			{"a rejected provider carrying a credential", request{method: http.MethodPost, path: "/api/v1/providers", cookie: cookie,
				body: map[string]any{"kind": "fake", "name": "", "credential": proxmoxToken, "settings": map[string]string{}}}, false},
			{"a wrong setup token", request{method: http.MethodPost, path: "/api/v1/auth/bootstrap",
				body: map[string]any{"username": "mallory", "password": password,
					"setup_token": h.setupToken() + "-wrong"}}, false},
			{"a wrong password", request{method: http.MethodPost, path: "/api/v1/auth/login",
				body: map[string]any{"username": "root", "password": password}}, false},
			{"a spent join token", request{method: http.MethodPost, path: "/api/v1/agent/join",
				body: map[string]any{"protocol_version": 1, "join_token": join.Token, "name": "vm-2",
					"capacity": 1, "os": "linux", "arch": "amd64", "version": "test"}}, false},
			{"an unrecognised agent token", request{method: http.MethodPost, path: "/api/v1/agent/heartbeat",
				token: agentToken + "-tampered", body: map[string]any{"protocol_version": 1}}, false},
			{"an unparseable settings patch", request{method: http.MethodPatch, path: "/api/v1/settings", cookie: cookie,
				rawBody: `{"scaling":{"max_runners":"` + appKey + `"}}`,
				headers: map[string]string{"Content-Type": "application/json"}}, false},
		} {
			resp := h.do(probe.req)
			switch {
			case probe.reportsInBody:
				if resp.status != http.StatusOK || !strings.Contains(string(resp.body), `"ok":false`) {
					t.Errorf("%s answered %d and did not report a failure, so this probe is not exercising one: %s",
						probe.what, resp.status, truncate(resp.body))
				}
			case resp.status < 400:
				t.Errorf("%s answered %d, so this probe is not exercising a failure path: %s",
					probe.what, resp.status, truncate(resp.body))
			}
			seen(t, probe.what+" ("+strconv.Itoa(resp.status)+")", resp.body)
		}
	})

	// --- What the fleet's own resources carry. ---------------------------
	t.Run("fleet resources", func(t *testing.T) {
		for _, path := range []string{
			"/api/v1/hosts", "/api/v1/hosts/" + hostID,
			"/api/v1/runners", "/api/v1/runners/" + run.ID,
			"/api/v1/pools", "/api/v1/pools/" + pool.ID,
			"/api/v1/jobs", "/api/v1/stats", "/api/v1/problems", "/api/v1/scaling-events",
			"/api/v1/providers", "/api/v1/providers/" + prov.ID, "/api/v1/machines",
		} {
			resp := h.do(request{method: http.MethodGet, path: path, cookie: cookie})
			resp.mustStatus(t, http.StatusOK, path)
			seen(t, path, resp.body)
		}
	})

	// --- What goes out on the event stream. ------------------------------
	t.Run("an event frame", func(t *testing.T) {
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		frames, resp := h.openStream(t, ctx, "/api/v1/events", cookie, nil)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("event stream status %d", resp.StatusCode)
		}

		// A host update is the frame most likely to carry a host's credential,
		// because the row it is rendered from holds the token hash.
		patched := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + hostID, cookie: cookie,
			body: map[string]any{"labels": map[string]string{"role": "rebuilt"}}})
		patched.mustStatus(t, http.StatusOK, "patch host")

		frame := await(t, frames, "a host frame", func(f sseFrame) bool {
			return strings.HasPrefix(f.event, "host.")
		})
		seen(t, "the "+frame.event+" frame", []byte(frame.data))
	})

	// --- What /metrics exposes. ------------------------------------------
	t.Run("metrics", func(t *testing.T) {
		resp := h.do(request{method: http.MethodGet, path: "/metrics", token: apiToken})
		resp.mustStatus(t, http.StatusOK, "metrics")
		seen(t, "/metrics", resp.body)
	})

	// --- The audit rows the failures above wrote. ------------------------
	t.Run("audit rows written on failure", func(t *testing.T) {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/audit?limit=200", cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "audit")
		seen(t, "the audit log", resp.body)
		// And it is not empty, or it would have nothing to leak: the failed
		// sign-in above is the row that has to be there.
		if !strings.Contains(string(resp.body), "auth.login_failed") {
			t.Errorf("no sign-in was audited, so this asserted nothing: %s", truncate(resp.body))
		}
	})

	// --- The controller's own log, across everything above. ---------------
	t.Run("the controller log", func(t *testing.T) {
		logged := h.logs.text()
		if logged == "" {
			t.Fatal("nothing was logged, so this asserted nothing")
		}
		seen(t, "the controller log", []byte(logged))
	})
}

// TestTokenIsShownExactlyOnce is the other half of that: the value exists in a
// response at creation and never again.
func TestTokenIsShownExactlyOnce(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("admin", store.RoleAdmin)
	cookie := h.session(u)

	created := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
		body: map[string]any{"name": "prometheus", "role": "viewer", "expires_in": "720h"}})
	created.mustStatus(t, http.StatusCreated, "create token")

	var token createdTokenResponse
	created.into(t, &token)
	if token.Token == "" {
		t.Fatal("the token value was not returned at creation")
	}
	if token.Prefix == "" || !strings.HasPrefix(token.Token, token.Prefix) {
		t.Errorf("the prefix does not identify the token: %q vs %q", token.Prefix, token.Token)
	}
	if token.ExpiresAt == nil {
		t.Error("expires_in was given but no expiry was recorded")
	}

	listed := h.do(request{method: http.MethodGet, path: "/api/v1/tokens", cookie: cookie})
	listed.mustStatus(t, http.StatusOK, "list tokens")
	if strings.Contains(string(listed.body), token.Token) {
		t.Fatal("the token list contains the token value")
	}

	// And it works, once.
	use := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: token.Token})
	use.mustStatus(t, http.StatusOK, "use the token")

	revoke := h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + token.ID, cookie: cookie})
	revoke.mustStatus(t, http.StatusNoContent, "revoke")
	after := h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: token.Token})
	after.mustStatus(t, http.StatusUnauthorized, "use a revoked token")
}

// A job's timeline is served straight from what the controller wrote, and with
// scheduler.auto_rerun on it writes a re-run the fleet decided on with the
// source "recovery". The published enum listed only the four an observer can
// be, so a strict client generated from the document would reject or mistype
// the timeline of exactly the jobs the fleet broke.
func TestTheJobTimelineSourceEnumNamesEverySourceTheControllerWrites(t *testing.T) {
	doc := loadSpec(t)
	components, _ := doc["components"].(map[string]any)
	schemas, _ := components["schemas"].(map[string]any)
	event, _ := schemas["JobEvent"].(map[string]any)
	props, _ := event["properties"].(map[string]any)
	source, _ := props["source"].(map[string]any)
	enum, _ := source["enum"].([]any)

	got := map[string]bool{}
	for _, v := range enum {
		if s, ok := v.(string); ok {
			got[s] = true
		}
	}
	for _, want := range []string{"webhook", "poller", "agent", "controller", "recovery"} {
		if !got[want] {
			t.Errorf("JobEvent.source does not list %q, which the controller writes to a job's timeline", want)
		}
	}
}

package api

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// heartbeatInterval is how often a live stream sends something.
//
// Twenty seconds is comfortably inside the idle timeout of every proxy and load
// balancer anyone puts in front of this, which is what keeps a quiet fleet's
// event stream from being closed under the operator every minute. The UI's
// watchdog is set from the same number.
const heartbeatInterval = 20 * time.Second

// sseWriter is one Server-Sent Events response.
//
// It exists so that the two streams -- fleet events and a runner's log tail --
// cannot disagree about framing, flushing or heartbeats, which is the usual way
// one of two SSE endpoints ends up subtly buffered.
type sseWriter struct {
	w  http.ResponseWriter
	rc *http.ResponseController
}

// startSSE writes the headers and returns the stream, or nil when the client
// cannot be streamed to.
func startSSE(w http.ResponseWriter, r *http.Request) *sseWriter {
	h := w.Header()
	h.Set("Content-Type", "text/event-stream; charset=utf-8")
	h.Set("Cache-Control", "no-cache, no-transform")
	h.Set("Connection", "keep-alive")
	// nginx buffers proxied responses by default, which turns a live stream
	// into one that arrives in lumps minutes late. This is the header that
	// turns that off, and it costs nothing when there is no nginx.
	h.Set("X-Accel-Buffering", "no")

	s := &sseWriter{w: w, rc: http.NewResponseController(w)}
	// A stream has no length and no deadline. The server's WriteTimeout is
	// already 0 for exactly this reason; clearing it here as well means a
	// caller that serves this handler from a listener of their own cannot cut
	// the stream off by setting one.
	_ = s.rc.SetWriteDeadline(time.Time{})

	w.WriteHeader(http.StatusOK)
	// The first flush is what makes the browser's EventSource fire onopen,
	// which the UI's connection indicator is driven by.
	s.flush()
	return s
}

// event writes one named event with its id and JSON payload. An empty id
// leaves the client's last id where it was, which is what a heartbeat or a
// log chunk wants.
func (s *sseWriter) event(kind string, id string, data []byte) error {
	var b strings.Builder
	if id != "" {
		b.WriteString("id: ")
		b.WriteString(id)
		b.WriteByte('\n')
	}
	if kind != "" {
		b.WriteString("event: ")
		b.WriteString(kind)
		b.WriteByte('\n')
	}
	if len(data) == 0 {
		data = []byte("{}")
	}
	// A payload containing a newline has to be split across data: lines or the
	// frame ends early and the client sees truncated JSON.
	for line := range strings.SplitSeq(string(data), "\n") {
		b.WriteString("data: ")
		b.WriteString(strings.TrimSuffix(line, "\r"))
		b.WriteByte('\n')
	}
	b.WriteByte('\n')
	if _, err := io.WriteString(s.w, b.String()); err != nil {
		return err
	}
	s.flush()
	return nil
}

// comment writes a heartbeat. A comment frame keeps the connection alive
// without the client having to know about a keep-alive event kind.
func (s *sseWriter) comment(text string) error {
	if _, err := fmt.Fprintf(s.w, ": %s\n\n", text); err != nil {
		return err
	}
	s.flush()
	return nil
}

// retry tells the browser how long to wait before reconnecting on its own.
func (s *sseWriter) retry(d time.Duration) error {
	if _, err := fmt.Fprintf(s.w, "retry: %d\n\n", d.Milliseconds()); err != nil {
		return err
	}
	s.flush()
	return nil
}

func (s *sseWriter) flush() { _ = s.rc.Flush() }

// ---------------------------------------------------------------------------
// GET /api/v1/events
// ---------------------------------------------------------------------------

// endIfRevoked re-resolves the credential this stream was opened with and, when
// it no longer stands, ends the stream with a frame saying so.
//
// A live stream is authorised once, at the moment it is opened, and then held
// for as long as the tab is. Without this, signing out, revoking the token,
// disabling the account or letting the session expire leaves the stream running
// -- the fleet's every movement still arriving at a browser whose credential
// the operator has just taken away, until something else happens to break the
// connection. Every other route re-checks on every request; a stream's
// heartbeat is the closest thing it has to one, so it re-checks there.
//
// The reason is deliberately the same whichever way the credential failed: an
// ended stream tells a client to stop and sign in again, and which of the four
// happened is not something the far end can do anything different about.
func (s *Server) endIfRevoked(stream *sseWriter, r *http.Request, action auth.Action) bool {
	id, err := s.resolveIdentity(r)
	if err == nil && auth.Allowed(id, action) {
		return false
	}
	// A failed read is not a revoked credential. Ending here would tell every
	// open tab to sign in again because the database blinked once; the stream
	// stays up and the next heartbeat asks again. A revocation is noticed a
	// beat late rather than missed, and the frames that carry anything
	// sensitive are still filtered per subscriber, failing closed, as they go
	// out.
	if errors.Is(err, auth.ErrAuthBackend) {
		s.logger(r).Warn("could not re-check a live stream's credential; keeping the stream open", "error", err)
		return false
	}
	_ = stream.event("end", "", []byte(`{"reason":"this stream's credential is no longer valid; sign in again"}`))
	return true
}

// handleEvents streams every change the operator would want to see.
//
// There is no polling anywhere in the UI, so this endpoint is the whole of the
// dashboard's liveness. It replays from Last-Event-ID on reconnect, which is
// what makes a dropped connection invisible rather than a hole in the history.
func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	bus := s.ctrl.Events()
	replay, sameEpoch := lastEventID(r, bus)
	opts := events.SubscribeOptions{
		Kinds:       parseKinds(r.URL.Query().Get("kinds")),
		TopicPrefix: strings.TrimSpace(r.URL.Query().Get("topic")),
		Replay:      replay,
		Incomplete:  replay > 0 && !sameEpoch,
	}

	ctx := r.Context()
	// The subscription is unsubscribed by cancelling the context it was made
	// with, which the bus watches and acts on. That is one owner of the
	// teardown rather than two: closing it here as well would mean this
	// handler and the bus's own watcher racing to do the same thing, and the
	// point of the cancel is that it happens on every exit from this function,
	// including a write failure to a browser that has already gone.
	subCtx, unsubscribe := context.WithCancel(ctx)
	defer unsubscribe()
	// Refused before the stream starts, while a status code can still be
	// sent. The browser's EventSource gives up on a non-200 rather than
	// retrying, which is what an instance with no room wants from it.
	limit := s.cfg().Limits.EventSubscribers
	sub, ok := bus.SubscribeWithin(subCtx, opts, limit)
	if !ok {
		limitReached(w, &controller.LimitError{
			Setting: "limits.event_subscribers", Limit: limit, What: "live-update streams",
			Free: "close a browser tab that is no longer needed",
		})
		return
	}

	stream := startSSE(w, r)
	_ = stream.retry(2 * time.Second)
	// An immediate heartbeat lets the client start its stall watchdog without
	// waiting twenty seconds to learn the stream works.
	if err := stream.comment("connected"); err != nil {
		return
	}
	if !sub.Complete {
		// The client asked to resume from an id the ring no longer reaches
		// back to, or from another run of this process. Saying so is what
		// lets it fetch afresh instead of quietly showing a fleet that has
		// moved on; the frame carries no id, so the client's own stays put.
		if err := stream.event(string(events.KindResync), "", []byte(`{"reason":"the events since your last id could not all be replayed; fetch the resources again"}`)); err != nil {
			return
		}
	}

	ticker := time.NewTicker(s.streamHeartbeat)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			// The browser navigated away, or the process is shutting down.
			return
		case ev, ok := <-sub.C:
			if !ok {
				// The bus dropped this subscriber for falling behind. Ending
				// the response makes the client reconnect with its last event
				// ID and catch up, which is better than silently going stale.
				return
			}
			data := ev.Data
			if ev.Kind == events.KindProblems {
				// The same two lists the REST route serves, chosen per
				// subscriber. Resolved per frame rather than once at
				// connect, for the reason the pool frames are: a viewer may
				// keep the stream open across a demotion.
				id, err := s.resolveIdentity(r)
				platform := err == nil && id != nil && id.Role.AtLeast(store.RolePlatform)
				filtered, ok := problemsFor(data, platform)
				if !ok && !platform {
					// Unfilterable, and this subscriber is not entitled to
					// the unfiltered list. Unlike the pool frames below,
					// passing it through would hand the fleet the whole of
					// the platform's list rather than leak one field, so the
					// frame is dropped instead. The drawer keeps what it had
					// until the next change, and GET /problems -- which
					// filters the same way -- repairs it on any reload.
					continue
				}
				data = filtered
			}
			if ev.Kind == events.KindAudit {
				// The same row GET /audit serves this caller, resolved per
				// frame for the reason the others are. A frame that will not
				// decode is dropped rather than passed through: the whole
				// document is exactly what the filter exists to withhold.
				var row store.AuditEvent
				if err := json.Unmarshal(data, &row); err != nil {
					continue
				}
				id, _ := s.resolveIdentity(r)
				filtered, err := json.Marshal(auditRowFor(row, id))
				if err != nil {
					continue
				}
				data = filtered
			}
			if ev.Kind == events.KindPoolCreated || ev.Kind == events.KindPoolUpdated {
				// A viewer may keep watching after a demotion, but must not
				// keep the environment access they opened this stream with.
				// Resolve each pool frame, including replay, and fail closed.
				id, err := s.resolveIdentity(r)
				if err != nil || !auth.Allowed(id, auth.ActionPoolsWrite) {
					data = withoutEnvValues(data)
				}
			}
			if err := stream.event(string(ev.Kind), bus.WireID(ev.ID), data); err != nil {
				return
			}
		case <-ticker.C:
			if s.endIfRevoked(stream, r, auth.ActionEventsRead) {
				return
			}
			if err := stream.comment("heartbeat"); err != nil {
				return
			}
			// The UI's watchdog is driven by heartbeat *events*, not comment
			// frames, so one is sent as well; it carries the server's clock,
			// which is what the top bar's "live" indicator shows.
			if err := stream.event(string(events.KindHeartbeat), "", heartbeatPayload(s)); err != nil {
				return
			}
		}
	}
}

func heartbeatPayload(s *Server) []byte {
	return []byte(`{"at":"` + s.ctrl.Now().Format(time.RFC3339) + `"}`)
}

// lastEventID reads where a reconnecting client left off, and whether that
// place is in this process's sequence at all.
//
// The header is what the browser's own EventSource retry sends. The query
// parameter is what the UI sends when it has given up and opened a fresh
// EventSource, which cannot carry the header; honouring both is what makes a
// reconnect seamless either way. A malformed id means "start from now" rather
// than an error: the alternative is a client that can never reconnect until it
// is reloaded by hand.
func lastEventID(r *http.Request, bus *events.Bus) (id uint64, sameEpoch bool) {
	raw := strings.TrimSpace(r.Header.Get("Last-Event-ID"))
	if raw == "" {
		raw = strings.TrimSpace(r.URL.Query().Get("last_event_id"))
	}
	if raw == "" {
		return 0, true
	}
	id, sameEpoch = bus.ParseWireID(raw)
	if id == 0 && !sameEpoch {
		return 0, true
	}
	return id, sameEpoch
}

func parseKinds(raw string) []events.Kind {
	var out []events.Kind
	for _, k := range strings.Split(raw, ",") {
		if k = strings.TrimSpace(k); k != "" {
			out = append(out, events.Kind(k))
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// GET /api/v1/runners/{id}/logs
// ---------------------------------------------------------------------------

// logChunkKind is the event name a log frame carries. It is not one of the
// fleet event kinds: this is a different stream with a payload of its own.
const logChunkKind = "log"

// handleRunnerLogs tails a runner's output.
//
// The controller never dials an agent, so this asks the controller to have the
// runner's agent open an outbound relay and then fans that out here. The two
// things this handler must get right are ending the stream when the runner's
// output ends, and unsubscribing on every exit -- a leaked subscription keeps a
// relay open on a host for a browser tab that closed hours ago.
func (s *Server) handleRunnerLogs(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	opts := backend.LogOptions{
		Follow: queryBool(r, "follow", true),
		Tail:   queryInt(r, "tail", 1000),
	}
	if opts.Tail < 0 {
		opts.Tail = 0
	}

	ctx := r.Context()
	ch, cancel, err := s.ctrl.OpenLogStream(ctx, id, opts)
	if err != nil {
		s.logStreamFailed(w, r, err)
		return
	}
	// Always, on every path out: this is what tells the agent to stop reading
	// the container's output once the last viewer has gone.
	defer cancel()

	stream := startSSE(w, r)
	_ = stream.retry(2 * time.Second)
	if err := stream.comment("attached to " + id); err != nil {
		return
	}

	ticker := time.NewTicker(s.streamHeartbeat)
	defer ticker.Stop()

	// carry is the incomplete tail of the last chunk: the first bytes of a
	// character whose rest is in the next one. The relay forwards whatever a
	// read returned, so a boundary can fall inside a character, and rendering
	// each half as its own JSON string would turn it into two U+FFFD.
	var carry []byte
	for {
		select {
		case <-ctx.Done():
			return
		case chunk, ok := <-ch:
			if !ok {
				// The runner's output finished -- for an ephemeral runner that
				// means the job is over. Say so and end the response, rather
				// than leaving the browser holding a connection that will never
				// carry another byte.
				if len(carry) > 0 {
					// Nothing more is coming to complete it, so it is what it
					// is: a truncated character, shown as one replacement.
					_ = stream.event(logChunkKind, "", jsonString(string(carry)))
				}
				_ = stream.event("end", "", []byte(`{"reason":"the runner's output ended"}`))
				return
			}
			data := chunk
			if len(carry) > 0 {
				data = append(append(make([]byte, 0, len(carry)+len(chunk)), carry...), chunk...)
			}
			whole, rest := splitIncompleteRune(data)
			carry = append(carry[:0], rest...)
			if len(whole) == 0 {
				continue
			}
			if err := stream.event(logChunkKind, "", jsonString(string(whole))); err != nil {
				return
			}
		case <-ticker.C:
			if s.endIfRevoked(stream, r, auth.ActionLogsRead) {
				return
			}
			if err := stream.comment("heartbeat"); err != nil {
				return
			}
		}
	}
}

// handleDownloadRunnerLogs returns a snapshot of a runner's output as a file.
//
// It is the same relay as the live tail, read until it goes quiet rather than
// followed: "download" has to terminate, and a runner that is still producing
// output would otherwise stream forever into a file the browser never finishes.
func (s *Server) handleDownloadRunnerLogs(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")
	run, err := s.ctrl.Store().GetRunner(r.Context(), id)
	if err != nil {
		s.fail(w, r, "reading the runner", err)
		return
	}

	// tail is what lets a caller who wants the end of a long build ask for
	// just that: without it the only way to the last lines was to read the
	// whole log and keep whatever fitted. Absent, or not a positive number, it
	// is the whole log, as a download always was.
	tail := max(queryInt(r, "tail", 0), 0)
	ch, cancel, err := s.ctrl.OpenLogStream(r.Context(), id, backend.LogOptions{Follow: false, Tail: tail})
	if err != nil {
		s.logStreamFailed(w, r, err)
		return
	}
	defer cancel()

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Content-Disposition", `attachment; filename="`+logFilename(run.Name)+`"`)
	w.WriteHeader(http.StatusOK)
	rc := http.NewResponseController(w)
	_ = rc.SetWriteDeadline(time.Time{})

	// A backlog arrives in a burst and then stops; this bounds the wait for the
	// first chunk and the gap between chunks, so a wedged agent cannot hold the
	// request open indefinitely.
	const firstChunkWait = 10 * time.Second
	const quietFor = 2 * time.Second

	timer := time.NewTimer(firstChunkWait)
	defer timer.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case chunk, ok := <-ch:
			if !ok {
				return
			}
			if _, err := w.Write(chunk); err != nil {
				return
			}
			_ = rc.Flush()
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
			timer.Reset(quietFor)
		case <-timer.C:
			return
		}
	}
}

// logStreamFailed answers a stream that could not be opened.
//
// A runner that has been removed, or that never reached a host, cannot produce
// output; that is a 409 with the controller's own sentence rather than a 500,
// because it is a fact about the runner and not a fault in the server.
func (s *Server) logStreamFailed(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, store.ErrNotFound) || errors.Is(err, controller.ErrStreamUnknown) {
		s.fail(w, r, "opening the log stream", err)
		return
	}
	conflict(w, err.Error())
}

// logFilename renders the Content-Disposition name, keeping it to characters
// that survive every filesystem and every quoting rule on the way.
func logFilename(runnerName string) string {
	safe := strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_', r == '.':
			return r
		default:
			return '-'
		}
	}, runnerName)
	if safe == "" {
		safe = "runner"
	}
	return safe + ".log"
}

// splitIncompleteRune cuts off a trailing sequence that is the start of a
// multi-byte character and cannot be finished yet, so a caller can hold it
// until the next read. At most three bytes are ever held back, and bytes that
// are simply invalid are not: they pass through, so a stream of garbage is
// never delayed waiting for a character that will not come.
func splitIncompleteRune(b []byte) (whole, rest []byte) {
	for i := len(b) - 1; i >= 0 && i >= len(b)-(utf8.UTFMax-1); i-- {
		if !utf8.RuneStart(b[i]) {
			continue
		}
		if !utf8.FullRune(b[i:]) {
			return b[:i], b[i:]
		}
		break
	}
	return b, nil
}

// jsonString renders a log chunk as a JSON string, which is what keeps a line
// containing a newline or a quote from breaking the frame.
func jsonString(s string) []byte {
	b, err := marshalJSON(s)
	if err != nil {
		return []byte(`""`)
	}
	return b
}

// problemsFor narrows an already-rendered problems frame to one audience,
// and reports whether it could. It works on the encoded bytes for the reason
// withoutEnvValues does: the frame is rendered once and fanned out, so
// filtering per connection is what one subscriber's presence costs rather
// than what every subscriber pays.
//
// ok is false when the payload is not a problems frame this version
// understands. The caller decides what that means, and the two audiences
// decide differently.
func problemsFor(data []byte, platform bool) ([]byte, bool) {
	var view struct {
		OK    bool                 `json:"ok"`
		Items []controller.Problem `json:"items"`
	}
	if err := json.Unmarshal(data, &view); err != nil {
		return data, false
	}
	out, err := json.Marshal(controller.NewProblemsViewFor(view.Items, platform))
	if err != nil {
		return data, false
	}
	return out, true
}

// withoutEnvValues blanks the env values in an already-rendered pool frame,
// keeping every key.
//
// It works on the encoded bytes because that is what the bus carries: a frame
// is rendered once and fanned out to every subscriber, so the alternative --
// rendering per connection -- would make one viewer's presence cost every
// other subscriber a re-render. Only a viewer's connection pays for this, and
// only on a pool frame.
//
// A payload that does not parse is passed through untouched rather than
// dropped: it cannot be a pool view, and swallowing frames would be a worse
// failure than the one this guards against.
func withoutEnvValues(data []byte) []byte {
	var frame map[string]json.RawMessage
	if err := json.Unmarshal(data, &frame); err != nil {
		return data
	}
	raw, ok := frame["env"]
	if !ok {
		return data
	}
	var env map[string]string
	if err := json.Unmarshal(raw, &env); err != nil || len(env) == 0 {
		return data
	}
	for k := range env {
		env[k] = ""
	}
	blanked, err := json.Marshal(env)
	if err != nil {
		return data
	}
	frame["env"] = blanked
	out, err := json.Marshal(frame)
	if err != nil {
		return data
	}
	return out
}

package api

import (
	"bufio"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// sseFrame is one parsed Server-Sent Event.
type sseFrame struct {
	id      string
	event   string
	data    string
	comment string
}

// openStream starts an SSE request and returns the frames as they arrive.
//
// The request carries its own context so the test can cancel it, which is how
// the "the handler returns when the client goes away" case is exercised.
func (h *harness) openStream(t *testing.T, ctx context.Context, path, cookie string, headers map[string]string) (<-chan sseFrame, *http.Response) {
	t.Helper()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, h.srv.URL+path, nil)
	if err != nil {
		t.Fatalf("building the stream request: %v", err)
	}
	if cookie != "" {
		req.AddCookie(&http.Cookie{Name: SessionCookie, Value: cookie})
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("opening the stream: %v", err)
	}

	frames := make(chan sseFrame, 64)
	go func() {
		defer close(frames)
		defer resp.Body.Close()
		sc := bufio.NewScanner(resp.Body)
		var f sseFrame
		for sc.Scan() {
			line := sc.Text()
			switch {
			case line == "":
				if f != (sseFrame{}) {
					frames <- f
					f = sseFrame{}
				}
			case strings.HasPrefix(line, ":"):
				frames <- sseFrame{comment: strings.TrimSpace(line[1:])}
			case strings.HasPrefix(line, "id: "):
				f.id = strings.TrimPrefix(line, "id: ")
			case strings.HasPrefix(line, "event: "):
				f.event = strings.TrimPrefix(line, "event: ")
			case strings.HasPrefix(line, "data: "):
				if f.data != "" {
					f.data += "\n"
				}
				f.data += strings.TrimPrefix(line, "data: ")
			}
		}
	}()
	return frames, resp
}

// await waits for a frame matching pred, or fails.
func await(t *testing.T, frames <-chan sseFrame, what string, pred func(sseFrame) bool) sseFrame {
	t.Helper()
	deadline := time.After(5 * time.Second)
	for {
		select {
		case f, ok := <-frames:
			if !ok {
				t.Fatalf("the stream closed before %s arrived", what)
			}
			if pred(f) {
				return f
			}
		case <-deadline:
			t.Fatalf("timed out waiting for %s", what)
		}
	}
}

// TestEventStreamDeliversPublishedEvents is the whole of the UI's liveness: an
// event published on the bus has to reach a browser holding this connection.
func TestEventStreamDeliversPublishedEvents(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	frames, resp := h.openStream(t, ctx, "/api/v1/events", h.session(u), nil)
	if ct := resp.Header.Get("Content-Type"); !strings.HasPrefix(ct, "text/event-stream") {
		t.Fatalf("Content-Type = %q, want text/event-stream", ct)
	}
	for _, want := range [][2]string{
		{"Cache-Control", "no-cache"},
		{"X-Accel-Buffering", "no"},
	} {
		if got := resp.Header.Get(want[0]); !strings.Contains(got, want[1]) {
			t.Errorf("%s = %q, want it to contain %q", want[0], got, want[1])
		}
	}

	// The connection is live before anything is published: the comment frame
	// arrives immediately so the browser fires onopen.
	await(t, frames, "the opening comment", func(f sseFrame) bool { return f.comment != "" })

	h.ctrl.Events().Publish(events.KindPoolCreated, "pool:pool_test", map[string]any{"id": "pool_test", "name": "linux-x64"})

	got := await(t, frames, "the pool.created event", func(f sseFrame) bool {
		return f.event == string(events.KindPoolCreated)
	})
	if got.id == "" {
		t.Error("the event carried no id, so a reconnecting client cannot resume")
	}
	var payload map[string]any
	if err := json.Unmarshal([]byte(got.data), &payload); err != nil {
		t.Fatalf("the event payload is not JSON: %v (%q)", err, got.data)
	}
	if payload["name"] != "linux-x64" {
		t.Errorf("payload = %v", payload)
	}
}

// TestEventStreamReplaysFromLastEventID covers reconnection, which is what
// makes a dropped connection invisible rather than a hole in the history.
func TestEventStreamReplaysFromLastEventID(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)
