import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

func withStatusMode(mode config.StatusMode) func(*config.Config) {
	return func(c *config.Config) { c.Status.Mode = mode }
}

// statusRoutes are the three ways the status is read, plus the built page's
// own file name, which the SPA would otherwise serve whatever the setting.
var statusRoutes = []string{"/api/v1/status", "/status", "/status.html", "/status.svg"}

// A default install serves nothing new: every status route is a 404, to
// anyone, signed in or not -- the same answer as a path that never existed,
// so turning the feature on is the only way anybody learns it is there.
func TestTheDefaultLeavesEveryStatusRouteA404(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	for _, path := range statusRoutes {
		for _, cookie := range []string{"", h.session(admin)} {
			resp := h.do(request{method: http.MethodGet, path: path, cookie: cookie})
			if resp.status != http.StatusNotFound {
				t.Errorf("GET %s (signed in: %v) = %d, want 404 while status.mode is off", path, cookie != "", resp.status)
			}
		}
	}
}

// Each mode lets in exactly who it says.
func TestTheStatusModeDecidesWhoMayRead(t *testing.T) {
	cases := []struct {
		mode      config.StatusMode
		anonymous int
		signedIn  int
	}{
		{config.StatusAuthenticated, http.StatusUnauthorized, http.StatusOK},
		{config.StatusPublic, http.StatusOK, http.StatusOK},
	}
	for _, tc := range cases {
		t.Run(string(tc.mode), func(t *testing.T) {
			h := newHarness(t, withStatusMode(tc.mode))
			viewer, _ := h.user("viewer", store.RoleViewer)
			for _, path := range statusRoutes {
				if got := h.do(request{method: http.MethodGet, path: path}).status; got != tc.anonymous {
					t.Errorf("anonymous GET %s = %d, want %d", path, got, tc.anonymous)
				}
				if got := h.do(request{method: http.MethodGet, path: path, cookie: h.session(viewer)}).status; got != tc.signedIn {
					t.Errorf("signed-in GET %s = %d, want %d", path, got, tc.signedIn)
				}
			}
		})
	}
}

// The API half of the fixture-name test: a fleet with distinctive names
// produces a body that carries none of them, in the shape the spec promises.
func TestTheStatusBodyNamesNothingInTheFleet(t *testing.T) {
	h := newHarness(t, withStatusMode(config.StatusPublic))
	inst := h.installation()
	pool := h.pool(inst, "wombatpool")
	host := h.host("platypushost")
	runner := h.runner(pool, host, store.RunnerBusy)
	job := h.job(pool, store.JobQueued)

	resp := h.do(request{method: http.MethodGet, path: "/api/v1/status"})
	resp.mustStatus(t, http.StatusOK, "the public status")
	for _, name := range []string{pool.Name, pool.ID, host.Name, host.ID, runner.Name, runner.ID, job.ID, job.Repo, inst.Target, inst.ID} {
		if strings.Contains(string(resp.body), name) {
			t.Errorf("the status body contains %q: %s", name, resp.body)
		}
	}

	var body map[string]json.RawMessage
	resp.into(t, &body)
	for _, key := range []string{"state", "since", "version", "queued", "running", "median_wait_minutes", "p95_wait_minutes", "reasons", "explanations"} {
		if _, ok := body[key]; !ok {
			t.Errorf("the body has no %q: %s", key, resp.body)
		}
	}
	var reasons []map[string]any
	if err := json.Unmarshal(body["reasons"], &reasons); err != nil {
		t.Fatal(err)
	}
	for _, r := range reasons {
		for k := range r {
			if k != "code" && k != "severity" && k != "since" {
				t.Errorf("a reason carries %q; it may carry code, severity and since and nothing else", k)
			}
		}
	}
}

// The badge is an image a README can embed: SVG, the state in words, and a
// colour from the status mapping rather than one of its own.
func TestTheBadgeIsTheStateAsAnImage(t *testing.T) {
	h := newHarness(t, withStatusMode(config.StatusPublic))
	resp := h.do(request{method: http.MethodGet, path: "/status.svg"})
	resp.mustStatus(t, http.StatusOK, "the badge")
	if ct := resp.header.Get("Content-Type"); ct != "image/svg+xml" {
		t.Fatalf("Content-Type = %q", ct)
	}
	svg := string(resp.body)
	if !strings.HasPrefix(svg, "<svg") || !strings.Contains(svg, "fleet: ") {
		t.Fatalf("not a status badge: %s", svg)
	}
	found := false
	for _, colour := range badgeColours {
		found = found || strings.Contains(svg, colour)
	}
	if !found {
		t.Errorf("the badge uses none of the three state colours: %s", svg)
	}
}

// A badge fetched by somebody signed in must never land in a shared cache: a
// proxy or CDN would hand it to the next request for the same URL, signed in
// or not, without that request ever reaching the mode check. Only a public
// status may be cached publicly.
func TestOnlyAPublicBadgeMayBeCachedByAProxy(t *testing.T) {
	for _, tc := range []struct {
		mode   config.StatusMode
		public bool
	}{
		{config.StatusPublic, true},
		{config.StatusAuthenticated, false},
	} {
		t.Run(string(tc.mode), func(t *testing.T) {
			h := newHarness(t, withStatusMode(tc.mode))
			viewer, _ := h.user("viewer", store.RoleViewer)
			resp := h.do(request{method: http.MethodGet, path: "/status.svg", cookie: h.session(viewer)})
			resp.mustStatus(t, http.StatusOK, "the badge")
			cc := resp.header.Get("Cache-Control")
			if got := strings.Contains(cc, "public"); got != tc.public {
				t.Errorf("Cache-Control = %q in %s mode; public caching allowed = %v, want %v", cc, tc.mode, got, tc.public)
			}
			if !tc.public && !strings.Contains(cc, "no-store") {
				t.Errorf("Cache-Control = %q; an authenticated badge must not be stored", cc)
			}
		})
	}
}

package api

import (
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/controller"
)

// The refusals that keep a host's settings and a pool's requirements from
// being edited into contradiction.
//
// Both are 409 rather than 422, for the reason ErrConfirmationRequired is:
// the request is well formed and it is the rest of the fleet that decides. An
// operator shrinking a host before they delete the pool that used it is right,
// so neither refusal is final -- each says what would be stranded, and each
// says how to mean it anyway.
//
// The sentence names the pool, the machine and the shortfall, because those
// three are the whole decision. "That would strand a pool" sends an operator
// to compare two forms on two pages by eye, which is the work this check
// exists to do for them.

const strandingConfirm = "send it again with confirm=true to save it anyway"

// hostStrandingRefusal answers a host edit that would leave pools homeless.
func hostStrandingRefusal(host string, stranded []controller.Stranding) string {
	if len(stranded) == 1 {
		s := stranded[0]
		return fmt.Sprintf("saving %s as described would leave pool %s with nowhere to run: %s, "+
			"and no other host in this fleet could run it. Lower what %s holds back, change what %s asks for, "+
			"or %s.", host, s.Pool, s.Reason, host, s.Pool, strandingConfirm)
	}
	parts := make([]string, 0, len(stranded))
	names := make([]string, 0, len(stranded))
	for _, s := range stranded {
		parts = append(parts, s.Pool+" ("+s.Reason+")")
		names = append(names, s.Pool)
	}
	return fmt.Sprintf("saving %s as described would leave %d pools with nowhere to run, and no other host in this "+
		"fleet could run them: %s. Lower what %s holds back, change what %s ask for, or %s.",
		host, len(stranded), strings.Join(parts, "; "), host, strings.Join(names, " and "), strandingConfirm)
}

// poolStrandingRefusal answers the same edit made from the pool's side. The
// host it names is one the pool fits on today, which is the machine the new
// figures have to be read against: a count of hosts is not something an
// operator can go and look at.
func poolStrandingRefusal(s controller.Stranding) string {
	return fmt.Sprintf("saving %s as described would leave it with nowhere to run: %s %s, and no other host in "+
		"this fleet could run it either. Ask for less, adjust %s to match, or %s.",
		s.Pool, s.Host, s.Reason, s.Host, strandingConfirm)
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// sizedHost is a host that has reported what it is, which is the only kind a
// fit can be judged against. The api harness's own host reports nothing --
// an agent too old to measure itself -- and every pool fits on one of those.
func sizedHost(t *testing.T, h *harness, name string, cpus int, memoryMB int64) *store.Host {
	t.Helper()
	host := h.host(name)
	host.CPUs, host.MemoryMB = cpus, memoryMB
	host.DiskTotalMB, host.DiskFreeMB = 500*1024, 400*1024
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	return host
}

// sizedPool is a pool whose runners ask for a definite share, so that raising
// a reserve can take the last machine it fits on away.
func sizedPool(t *testing.T, h *harness, inst *store.Installation, name string, cpus float64, memoryMB int64) *store.Pool {
	t.Helper()
	p := h.pool(inst, name)
	p.Resources = store.Resources{CPUs: cpus, MemoryMB: memoryMB}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	return p
}

// The mistake this refusal exists for: the Hosts page and the Pools page are
// two halves of one sentence, and holding back most of the machine on one of
// them is a pool whose jobs queue for ever on the other. Nothing was red
// before this check; the fleet simply stopped placing work.
func TestAReserveThatWouldLeaveAPoolNowhereToRunIsRefused(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	host := sizedHost(t, h, "vm-1", 16, 64*1024)
	pool := sizedPool(t, h, inst, "big", 4, 16*1024)
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	refused := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID, cookie: cookie,
		body: map[string]any{"reserve_memory_mb": 56 * 1024}})
	refused.mustStatus(t, http.StatusConflict, "a reserve that strands a pool")
	body := string(refused.body)
	for _, want := range []string{pool.Name, host.Name, "16 GB", "confirm=true"} {
		if !strings.Contains(body, want) {
			t.Errorf("the refusal does not mention %q, so an operator cannot act on it: %s", want, body)
		}
	}

	// And nothing was written: a refusal that half-saved would be worse than
	// no check at all.
	stored, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.ReserveMemoryMB != 0 {
		t.Fatalf("the refused reserve was written anyway: %+v", stored)
	}

	// Shrinking a host before the pool that used it is deleted is a real thing
	// to want, so the refusal is a question rather than a wall.
	confirmed := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + host.ID + "?confirm=true",
		cookie: cookie, body: map[string]any{"reserve_memory_mb": 56 * 1024}})
	confirmed.mustStatus(t, http.StatusOK, "the same reserve, confirmed")
	stored, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if stored.ReserveMemoryMB != 56*1024 {
		t.Fatalf("confirm=true did not save the reserve: %+v", stored)
	}
}

// The guard is narrow: a pool with somewhere else to go is not stranded, and
// an operator who could not adjust one host of several would stop using the
// page.
func TestAReserveIsSavedWhenAnotherHostCanStillRunThePool(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	first := sizedHost(t, h, "vm-1", 16, 64*1024)
	sizedHost(t, h, "vm-2", 16, 64*1024)
	sizedPool(t, h, inst, "big", 4, 16*1024)
	operator, _ := h.user("operator", store.RoleOperator)

	saved := h.do(request{method: http.MethodPatch, path: "/api/v1/hosts/" + first.ID,
		cookie: h.session(operator), body: map[string]any{"reserve_memory_mb": 56 * 1024}})
	saved.mustStatus(t, http.StatusOK, "a reserve that strands nothing")
}

// The other half of the same guard, typed on the pool's form instead. The
// wizard warns about this before a pool exists; the route has to refuse it for
// every other client, and for the quick edits that never open the wizard.
func TestAPoolEditThatNoHostCouldRunIsRefused(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	host := sizedHost(t, h, "vm-1", 16, 64*1024)
	pool := sizedPool(t, h, inst, "big", 4, 16*1024)
	operator, _ := h.user("operator", store.RoleOperator)
	cookie := h.session(operator)

	refused := h.do(request{method: http.MethodPatch, path: "/api/v1/pools/" + pool.ID, cookie: cookie,
		body: map[string]any{"resources": map[string]any{"cpus": 4, "memory_mb": 128 * 1024}}})
	refused.mustStatus(t, http.StatusConflict, "a pool no host could run")
	body := string(refused.body)
	for _, want := range []string{pool.Name, host.Name, "confirm=true"} {
		if !strings.Contains(body, want) {
			t.Errorf("the refusal does not mention %q: %s", want, body)
		}
	}

	stored, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatalf("GetPool: %v", err)
	}
	if stored.Resources.MemoryMB != 16*1024 {
		t.Fatalf("the refused change was written anyway: %+v", stored.Resources)
	}

	// A pool sized for machines that have not joined yet is legitimate, so the
	// refusal can be accepted.
	confirmed := h.do(request{method: http.MethodPatch, path: "/api/v1/pools/" + pool.ID + "?confirm=true",
		cookie: cookie, body: map[string]any{"resources": map[string]any{"cpus": 4, "memory_mb": 128 * 1024}}})
	confirmed.mustStatus(t, http.StatusOK, "the same change, confirmed")
}

// An edit to a pool that has somewhere to run and keeps it goes through
// untouched, whatever else it changes.
func TestAPoolEditThatKeepsAHostIsSaved(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	sizedHost(t, h, "vm-1", 16, 64*1024)
	pool := sizedPool(t, h, inst, "big", 4, 16*1024)
	operator, _ := h.user("operator", store.RoleOperator)

	saved := h.do(request{method: http.MethodPatch, path: "/api/v1/pools/" + pool.ID,
		cookie: h.session(operator), body: map[string]any{"max_runners": 8}})
	saved.mustStatus(t, http.StatusOK, "an edit that strands nothing")
}

package api

import (
	"context"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/tailscale/tailcat"
	"tailscale.com/tailcfg"
)

const tailcatIdentitySetting = "tailcat.identity.v1"

// tailcatCheckInterval is how often a wanted listener checks that its relay
// still answers. It is well inside the minute an operator should wait to be
// told the private hosts are cut off, and slow enough that a relay which is
// down is asked three times a minute rather than hammered.
const tailcatCheckInterval = 20 * time.Second

// tailcatHealthyInterval is how often a listener that is healthy on its sealed
// relay checks it. The public relays are documented as rate-limited, so a
// probe every twenty seconds from every controller is traffic nobody should
// generate while nothing is wrong; five minutes still notices an outage well
// before a host's heartbeats have been missed for long, and the moment it is
// noticed the loop drops back to tailcatCheckInterval.
const tailcatHealthyInterval = 5 * time.Minute

// relayProbeTimeout bounds one relay probe. A relay that takes longer than
// this to answer an HTTPS request is not one an agent can hold a session on.
const relayProbeTimeout = 5 * time.Second

type tailcatContextKey struct{}

// The listener exists only in memory. It cannot expose a port on the OS, route
// the home LAN, or give a tunnel peer access to the operator API.
type tunnelListener struct {
	connections chan net.Conn
	done        chan struct{}
	once        sync.Once
}

func (l *tunnelListener) Accept() (net.Conn, error) {
	select {
	case <-l.done:
		return nil, net.ErrClosed
	case c := <-l.connections:
		return c, nil
	}
}
func (l *tunnelListener) Close() error   { l.once.Do(func() { close(l.done) }); return nil }
func (l *tunnelListener) Addr() net.Addr { return &net.TCPAddr{IP: net.IPv4(127, 0, 0, 1), Port: 80} }
func (l *tunnelListener) offer(c net.Conn) {
	select {
	case <-l.done:
		_ = c.Close()
	case l.connections <- c:
	}
}

type privateConnections struct {
	mu       sync.Mutex
	closed   bool
	node     *tailcat.Server
	http     *http.Server
	listener *tunnelListener
	address  string

	// wanted is set once an identity exists, so the check loop knows a
	// listener that is not running is one that failed rather than one nobody
	// has asked for yet -- the latter must never dial a relay.
	wanted bool
	// sealed is the relay region the identity was sealed with, and region the
	// one the running node uses. They differ only while the sealed relay is
	// unreachable and the expansion found another that answers; the sealed one
	// stays the first choice, because it is the one every enrolled host's
	// address names.
	sealed *tailcfg.DERPRegion
	region *tailcfg.DERPRegion

	// expand and probe are the two network calls the listener makes on its
	// own behalf, replaceable so a test can hold a relay down without the
	// public relay map.
	expand func(context.Context) (*tailcfg.DERPRegion, error)
	probe  func(context.Context, *tailcfg.DERPRegion) error
}

// Only transport-observed facts mark hosts as Tailcat hosts. A JSON field or
// proxy header from an agent cannot grant it that badge.
func connectionKind(ctx context.Context) string {
	if ctx.Value(tailcatContextKey{}) == true {
		return "tailcat"
	}
	return "direct"
}

func (s *Server) privateAgentHandler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		allowed := r.URL.Path == agent.PathJoin || r.URL.Path == agent.PathHeartbeat ||
			r.URL.Path == agent.PathTasks || r.URL.Path == agent.PathResults || r.URL.Path == agent.PathReport ||
			strings.HasPrefix(r.URL.Path, agent.PathLogs+"/")
		if !allowed {
			http.NotFound(w, r)
			return
		}
		for _, key := range []string{"Forwarded", "X-Forwarded-For", "X-Real-IP", "CF-Connecting-IP", "X-Forwarded-Proto"} {
			r.Header.Del(key)
		}
		s.handler.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), tailcatContextKey{}, true)))
	})
}

// expandRelay picks a relay region afresh from the public relay map, bounded
// by a context because the upstream library would otherwise do the same
// discovery with a background one inside Start.
func expandRelay(ctx context.Context) (*tailcfg.DERPRegion, error) {
	ci := &tailcat.ConnInfo{RegionID: -1}
	resolveCtx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	if err := ci.Expand(resolveCtx, tailcat.ExpandForServer); err != nil {
		return nil, err
	}
	if len(ci.Region) == 0 {
		return nil, errors.New("the relay map named no region")
	}
	return ci.Region[0], nil
}

// probeRelay asks each of a region's relays for an HTTPS response.
//
// It exists because the node's own Start succeeds with a relay that does not
// answer -- it connects lazily, in the background -- so without asking, a
// controller whose relay has gone would report a healthy listener that no host
// can reach. Any HTTP answer counts: a relay that speaks HTTPS on its port is
// one the node's own connection can reach.
func probeRelay(ctx context.Context, region *tailcfg.DERPRegion) error {
	if region == nil {
		return errors.New("no relay region")
	}
	// The whole region shares one budget: the listener's lock is held while
	// it is asked, and an enrolment request waits behind it.
	ctx, cancel := context.WithTimeout(ctx, 2*relayProbeTimeout)
	defer cancel()
	var last error
	for _, n := range region.Nodes {
		if n.STUNOnly {
			continue
		}
		host := n.HostName
		if n.IPv4 != "" && n.IPv4 != "none" {
			host = n.IPv4
		}
		port := n.DERPPort
		if port == 0 {
			port = 443
		}
		serverName := n.CertName
		if serverName == "" {
			serverName = n.HostName
		}
		client := &http.Client{
			Timeout: relayProbeTimeout,
			Transport: &http.Transport{
				Proxy: http.ProxyFromEnvironment,
				// InsecureForTests is only ever set by a relay map built in a
				// test; the public map never carries it.
				TLSClientConfig: &tls.Config{ServerName: serverName, InsecureSkipVerify: n.InsecureForTests, MinVersion: tls.VersionTLS12},
			},
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://"+net.JoinHostPort(host, strconv.Itoa(port))+"/derp/probe", nil)
		if err != nil {
			last = err
			continue
		}
		resp, err := client.Do(req)
		client.CloseIdleConnections()
		if err != nil {
			last = fmt.Errorf("relay %s did not answer: %w", n.HostName, err)
			continue
		}
		_ = resp.Body.Close()
		return nil
	}
	if last == nil {
		last = errors.New("the relay region has no relay to connect to")
	}
	return last
}

func (p *privateConnections) expandFn() func(context.Context) (*tailcfg.DERPRegion, error) {
	if p.expand != nil {
		return p.expand
	}
	return expandRelay
}

func (p *privateConnections) probeFn() func(context.Context, *tailcfg.DERPRegion) error {
	if p.probe != nil {
		return p.probe
	}
	return probeRelay
}

// chooseRegion is the relay a sealed identity should run on: its own if that
// answers, otherwise whichever one a fresh expansion finds that does. The
// error is why neither would do, in which case the region returned is the
// sealed one -- the node still runs on it, because that is the relay the
// enrolled hosts will come back through when it recovers.
func (p *privateConnections) chooseRegion(ctx context.Context, sealed *tailcfg.DERPRegion) (*tailcfg.DERPRegion, error) {
	probe := p.probeFn()
	sealedErr := probe(ctx, sealed)
	if sealedErr == nil {
		return sealed, nil
	}
	alt, err := p.expandFn()(ctx)
	if err != nil {
		return sealed, fmt.Errorf("%v, and no other relay could be found: %v", sealedErr, err)
	}
	if err := probe(ctx, alt); err != nil {
		return sealed, fmt.Errorf("%v, and the nearest other relay did not answer either: %v", sealedErr, err)
	}
	return alt, nil
}

func sameRegion(a, b *tailcfg.DERPRegion) bool {
	if a == b {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	x, _ := json.Marshal(a)
	y, _ := json.Marshal(b)
	return string(x) == string(y)
}

// reportPrivateFault hands the listener's state to the controller, which owns
// the problems list, and logs the transitions -- once each way, rather than on
// every check, so an outage is two log lines and not three a minute.
func (s *Server) reportPrivateFault(err error) {
	was := s.ctrl.PrivateConnectionFault() != nil
	if err == nil {
		s.ctrl.SetPrivateConnectionFault(nil)
		if was {
			s.log.Info("the private connection's relay answers again")
		}
		return
	}
	s.ctrl.SetPrivateConnectionFault(&controller.PrivateConnectionFault{Since: s.ctrl.Now(), Reason: err.Error()})
	if !was {
		s.log.Warn("private hosts cannot reach this controller; retrying", "error", err)
	}
}

// ensureTailcat starts lazily when an operator asks for a private enrolment.
// The sealed identity lives in the normal database backup, so restarting the
// controller does not strand every lab that enrolled through it.
func (s *Server) ensureTailcat(ctx context.Context) (string, error) {
	p := &s.private
	p.mu.Lock()
	defer p.mu.Unlock()
	return s.ensureTailcatLocked(ctx)
}

func (s *Server) ensureTailcatLocked(ctx context.Context) (string, error) {
	p := &s.private
	if p.closed || !s.cfg().Server.TailcatEnabled || s.cfg().Security.DisableAuth {
		return "", errors.New("private connections are disabled; enable authentication and server.tailcat_enabled, then restart the controller")
	}
	if p.node != nil {
		return p.address, nil
	}
	if s.key == nil {
		return "", errors.New("private connections need the controller encryption key; check security.encryption_key_file")
	}
	stored, err := s.ctrl.Store().GetSetting(ctx, tailcatIdentitySetting)
	if err != nil {
		return "", errors.New("cannot read the private connection identity")
	}
	identity := tailcat.NewPrivateKey()
	if stored != "" {
		sealed, err := base64.StdEncoding.DecodeString(stored)
		if err != nil {
			return "", errors.New("cannot decode the private connection identity")
		}
		raw, err := s.key.Open(sealed)
		if err != nil {
			return "", errors.New("cannot decrypt the private connection identity; restore the matching encryption key")
		}
		if json.Unmarshal(raw, identity) != nil || identity.Private.IsZero() || identity.Public.PresharedKey.IsZero() {
			return "", errors.New("the saved private connection identity is incomplete")
		}
	}
	var region *tailcfg.DERPRegion
	var relayErr error
	if len(identity.Public.Region) == 0 {
		// A new identity: no host holds its address yet, so a relay that
		// cannot be found is a refused enrolment and nothing more.
		region, err = p.expandFn()(ctx)
		if err != nil {
			return "", errors.New("cannot reach a Tailcat relay; check outbound internet access and try again")
		}
		identity.Public.RegionID = 0
		identity.Public.Region = []*tailcfg.DERPRegion{region}
	} else {
		p.wanted = true
		p.sealed = identity.Public.Region[0]
		region, relayErr = p.chooseRegion(ctx, p.sealed)
	}
	if err := s.startNodeLocked(identity, region); err != nil {
		if stored == "" {
			return "", err
		}
		// The node would not start on the relay chosen above, so ask the
		// relay map afresh rather than retry the same one forever.
		alt, expandErr := p.expandFn()(ctx)
		if expandErr != nil || sameRegion(alt, region) || s.startNodeLocked(identity, alt) != nil {
			s.reportPrivateFault(err)
			return "", err
		}
		region, relayErr = alt, nil
	}
	if stored == "" {
		raw, err := json.Marshal(identity)
		if err == nil {
			var sealed []byte
			sealed, err = s.key.Seal(raw)
			if err == nil {
				err = s.ctrl.Store().SetSetting(ctx, tailcatIdentitySetting, base64.StdEncoding.EncodeToString(sealed), true)
			}
		}
		if err != nil {
			s.stopNodeLocked()
			return "", errors.New("cannot save the private connection identity")
		}
		p.wanted, p.sealed = true, region
	}
	s.reportPrivateFault(relayErr)
	return p.address, nil
}

// startNodeLocked starts a node for identity on region and serves the agent
// API through it. The address it records carries the region, so a node on a
// fallback relay hands out the address of that relay and not the sealed one.
func (s *Server) startNodeLocked(identity *tailcat.PrivateKey, region *tailcfg.DERPRegion) error {
	p := &s.private
	listener := &tunnelListener{connections: make(chan net.Conn), done: make(chan struct{})}
	node := &tailcat.Server{
		Key: identity.Private, PresharedKey: identity.Public.PresharedKey,
		Region: region, Logf: func(string, ...any) {},
		OnTCP: func(port uint16) func(net.Conn) {
			if port != 80 {
				return nil
			}
			return listener.offer
		},
	}
	if err := node.Start(); err != nil {
		_ = listener.Close()
		_ = node.Close()
		return errors.New("cannot start the private connection; check network-interface permissions and outbound internet access, then try again")
	}
	public := identity.Public
	public.RegionID = 0
	public.Region = []*tailcfg.DERPRegion{region}
	server := s.httpServer(context.Background())
	server.Handler = s.privateAgentHandler()
	p.node, p.listener, p.http, p.address, p.region = node, listener, server, string(public.Addr()), region
	go func() {
		if err := server.Serve(listener); err != nil && !errors.Is(err, http.ErrServerClosed) {
			s.log.Error("private connection listener stopped; restart the controller")
		}
	}()
	return nil
}

func (s *Server) stopNodeLocked() {
	p := &s.private
	if p.listener != nil {
		_ = p.listener.Close()
	}
	if p.http != nil {
		_ = p.http.Close()
	}
	if p.node != nil {
		_ = p.node.Close()
	}
	p.node, p.listener, p.http, p.address, p.region = nil, nil, nil, "", nil
}

// checkTailcat is one pass of the loop that keeps a wanted listener honest:
// it starts one that failed, says so while no relay answers, and moves the
// node back to the sealed relay -- or off it, when it is gone and another
// answers -- without a restart.
func (s *Server) checkTailcat(ctx context.Context) {
	p := &s.private
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed || !p.wanted {
		return
	}
	if p.node == nil {
		if _, err := s.ensureTailcatLocked(ctx); err != nil {
			s.reportPrivateFault(err)
		}
		return
	}
	region, err := p.chooseRegion(ctx, p.sealed)
	if err != nil || sameRegion(region, p.region) {
		s.reportPrivateFault(err)
		return
	}
	// A different relay answers than the one the node is on: the sealed one
	// has come back, or the one in use has gone and another has not.
	s.stopNodeLocked()
	if _, err := s.ensureTailcatLocked(ctx); err != nil {
		s.reportPrivateFault(err)
	}
}

// watchTailcat runs checkTailcat until ctx ends: every fast while there is a
// fault or the node is on a fallback relay, and every slow while it is healthy
// on the sealed one.
func (s *Server) watchTailcat(ctx context.Context, fast, slow time.Duration) {
	t := time.NewTimer(s.nextTailcatCheck(fast, slow))
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			s.checkTailcat(ctx)
			t.Reset(s.nextTailcatCheck(fast, slow))
		}
	}
}

// nextTailcatCheck is how long to wait before the next check.
func (s *Server) nextTailcatCheck(fast, slow time.Duration) time.Duration {
	p := &s.private
	p.mu.Lock()
	healthy := p.node != nil && sameRegion(p.region, p.sealed)
	p.mu.Unlock()
	if healthy && s.ctrl.PrivateConnectionFault() == nil {
		return slow
	}
	return fast
}

func (s *Server) closeTailcat() {
	p := &s.private
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return
	}
	p.closed = true
	s.stopNodeLocked()
}

// resumeTailcat brings back the listener of an identity that already exists,
// and starts the loop that keeps it honest until ctx ends.
//
// A listener that cannot start is the private hosts' problem, not the whole
// controller's: refusing to start would take the direct hosts, the UI and the
// webhooks down with it, and would need a restart to recover once the relay
// comes back. It is raised as tailcat.unavailable and retried instead, so the
// only error here is a database that cannot be read.
func (s *Server) resumeTailcat(ctx context.Context, fast, slow time.Duration) error {
	if !s.cfg().Server.TailcatEnabled || s.cfg().Security.DisableAuth {
		return nil
	}
	stored, err := s.ctrl.Store().GetSetting(ctx, tailcatIdentitySetting)
	if err != nil {
		return err
	}
	if stored != "" {
		s.private.mu.Lock()
		s.private.wanted = true
		s.private.mu.Unlock()
		if _, err := s.ensureTailcat(ctx); err != nil {
			s.reportPrivateFault(err)
		}
	}
	go s.watchTailcat(ctx, fast, slow)
	return nil
}

package api

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net"
	"strconv"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/controller"
	"github.com/tailscale/tailcat"
	"tailscale.com/tailcfg"
	"tailscale.com/tstest/integration"
)

// sealRelay stores an identity sealed with region, as a controller that had
// enrolled a private host before would have it.
func sealRelay(t *testing.T, h *harness, region *tailcfg.DERPRegion) {
	t.Helper()
	identity := tailcat.NewPrivateKey()
	identity.Public.Region = []*tailcfg.DERPRegion{region}
	raw, err := json.Marshal(identity)
	if err != nil {
		t.Fatal(err)
	}
	sealed, err := h.key.Seal(raw)
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetSetting(h.ctx, tailcatIdentitySetting, base64.StdEncoding.EncodeToString(sealed), true); err != nil {
		t.Fatal(err)
	}
}

// privateProblem is tailcat.unavailable from the problems list, or nil.
func privateProblem(t *testing.T, h *harness) *controller.Problem {
	t.Helper()
	problems, err := h.ctrl.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	for i := range problems {
		if problems[i].Code == "tailcat.unavailable" {
			return &problems[i]
		}
	}
	return nil
}

// relayDoor is a port that refuses connections until it is opened, and then
// forwards them to a real relay -- a relay that was unreachable and came back
// at the same address, which is what the sealed identity names.
type relayDoor struct {
	port   int
	target string
}

func newRelayDoor(t *testing.T, target string) *relayDoor {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := ln.Addr().(*net.TCPAddr).Port
	_ = ln.Close()
	return &relayDoor{port: port, target: target}
}

func (d *relayDoor) open(t *testing.T) {
	t.Helper()
	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(d.port)))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = ln.Close() })
	go func() {
		for {
			c, err := ln.Accept()
			if err != nil {
				return
			}
			go func() {
				defer c.Close()
				up, err := net.Dial("tcp", d.target)
				if err != nil {
					return
				}
				defer up.Close()
				go func() { _, _ = io.Copy(up, c) }()
				_, _ = io.Copy(c, up)
			}()
		}
	}()
}

// A controller whose sealed relay has gone used to say so only in a log line,
// and before that refused to start at all -- taking the direct hosts, the UI
// and the webhooks down with the private ones, and needing a restart to come
// back. It must start, say so in the problems list within a minute, and clear
// it by itself once the relay answers, with a private host able to join
// through it again without anybody restarting anything.
func TestAControllerWhoseSealedRelayIsDownSaysSoAndRecoversWithoutARestart(t *testing.T) {
	t.Setenv("IN_TS_TEST", "true")
	h := newHarness(t)
	dm := integration.RunDERPAndSTUN(t, func(string, ...any) {}, "127.0.0.1")
	live := dm.Regions[1]
	door := newRelayDoor(t, net.JoinHostPort("127.0.0.1", strconv.Itoa(live.Nodes[0].DERPPort)))
	sealed := live.Clone()
	sealed.Nodes[0].DERPPort = door.port
	sealRelay(t, h, sealed)
	// No relay map in a test: the expansion finds nothing else, as it would
	// for a controller whose whole egress to the relays is down.
	h.api.private.expand = func(context.Context) (*tailcfg.DERPRegion, error) {
		return nil, errors.New("the relay map is unreachable in this test")
	}
	ctx, cancel := context.WithCancel(h.ctx)
	defer cancel()
	t.Cleanup(h.api.closeTailcat)
	if err := h.api.resumeTailcat(ctx, 100*time.Millisecond, 100*time.Millisecond); err != nil {
		t.Fatalf("an unreachable relay stopped the controller starting: %v", err)
	}

	deadline := time.Now().Add(time.Minute)
	var p *controller.Problem
	for p == nil && time.Now().Before(deadline) {
		if p = privateProblem(t, h); p == nil {
			time.Sleep(50 * time.Millisecond)
		}
	}
	if p == nil {
		t.Fatal("a controller whose sealed relay is unreachable raised no tailcat.unavailable within a minute")
	}
	if p.Severity != config.SeverityWarning || p.Audience != controller.AudiencePlatform || p.Since == nil {
		t.Fatalf("tailcat.unavailable = %+v, want a platform warning that says since when", p)
	}

	door.open(t)
	deadline = time.Now().Add(time.Minute)
	for privateProblem(t, h) != nil {
		if time.Now().After(deadline) {
			t.Fatal("tailcat.unavailable did not clear within a minute of the relay answering")
		}
		time.Sleep(50 * time.Millisecond)
	}

	address, err := h.api.ensureTailcat(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	_, token, err := h.ctrl.Auth().CreateJoinToken(h.ctx, time.Minute, nil, 1, "test")
	if err != nil {
		t.Fatal(err)
	}
	tr, err := agent.NewHTTPTransport(agent.HTTPOptions{ControllerURL: "tailcat://" + address})
	if err != nil {
		t.Fatal(err)
	}
	defer tr.Close()
	jctx, jcancel := context.WithTimeout(h.ctx, time.Minute)
	defer jcancel()
	if _, err := tr.Join(jctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion, JoinToken: token, Name: "back-again", Capacity: 1, OS: "linux", Arch: "amd64"}); err != nil {
		t.Fatalf("a private host could not join through the relay once it answered, without a restart: %v", err)
	}
}

// The sealed relay is the first choice every time, because it is the one each
// enrolled host's address names; another is used only while it does not
// answer, so new enrolments are not refused for the length of an outage, and
// the node goes back to it as soon as it does.
func TestTheListenerPrefersItsSealedRelayAndFallsBackOnlyWhileItIsDown(t *testing.T) {
	t.Setenv("IN_TS_TEST", "true")
	h := newHarness(t)
	sealed := &tailcfg.DERPRegion{RegionID: 1, RegionCode: "sealed", Nodes: []*tailcfg.DERPNode{{Name: "1a", RegionID: 1, HostName: "sealed.invalid"}}}
	other := &tailcfg.DERPRegion{RegionID: 2, RegionCode: "other", Nodes: []*tailcfg.DERPNode{{Name: "2a", RegionID: 2, HostName: "other.invalid"}}}
	sealRelay(t, h, sealed)
	var mu sync.Mutex
	up := map[tailcfg.DERPRegionID]bool{2: true}
	h.api.private.probe = func(_ context.Context, r *tailcfg.DERPRegion) error {
		mu.Lock()
		defer mu.Unlock()
		if !up[r.RegionID] {
			return errors.New("relay " + r.RegionCode + " did not answer")
		}
		return nil
	}
	h.api.private.expand = func(context.Context) (*tailcfg.DERPRegion, error) { return other, nil }
	t.Cleanup(h.api.closeTailcat)
	ctx, cancel := context.WithCancel(h.ctx)
	defer cancel()
	if err := h.api.resumeTailcat(ctx, time.Hour, time.Hour); err != nil {
		t.Fatal(err)
	}
	regionOf := func() tailcfg.DERPRegionID {
		h.api.private.mu.Lock()
		defer h.api.private.mu.Unlock()
		if h.api.private.region == nil {
			return 0
		}
		return h.api.private.region.RegionID
	}
	if got := regionOf(); got != 2 {
		t.Fatalf("with the sealed relay down and another answering, the node runs on region %d, want the one that answers", got)
	}
	if p := privateProblem(t, h); p != nil {
		t.Fatalf("a listener serving through a relay that answers raised %q", p.Code)
	}

	mu.Lock()
	up[1] = true
	mu.Unlock()
	h.api.checkTailcat(h.ctx)
	if got := regionOf(); got != 1 {
		t.Fatalf("with the sealed relay back, the node stayed on region %d; the sealed relay is the first choice", got)
	}

	mu.Lock()
	up = map[tailcfg.DERPRegionID]bool{}
	mu.Unlock()
	h.api.checkTailcat(h.ctx)
	if got := regionOf(); got != 1 {
		t.Fatalf("with no relay answering, the node moved to region %d; it should stay on the sealed one", got)
	}
	if privateProblem(t, h) == nil {
		t.Fatal("no relay answers and tailcat.unavailable was not raised")
	}
}

// The public relays are rate-limited, so a listener that is healthy on its
// sealed relay must not probe it at the outage rate; one that has a fault must.
func TestAHealthyListenerProbesItsRelayAtTheSlowRate(t *testing.T) {
	t.Setenv("IN_TS_TEST", "true")
	h := newHarness(t)
	sealed := &tailcfg.DERPRegion{RegionID: 1, RegionCode: "sealed", Nodes: []*tailcfg.DERPNode{{Name: "1a", RegionID: 1, HostName: "sealed.invalid"}}}
	sealRelay(t, h, sealed)
	var mu sync.Mutex
	probes, up := 0, true
	h.api.private.probe = func(context.Context, *tailcfg.DERPRegion) error {
		mu.Lock()
		defer mu.Unlock()
		probes++
		if !up {
			return errors.New("relay did not answer")
		}
		return nil
	}
	h.api.private.expand = func(context.Context) (*tailcfg.DERPRegion, error) { return nil, errors.New("no relay map") }
	t.Cleanup(h.api.closeTailcat)
	ctx, cancel := context.WithCancel(h.ctx)
	defer cancel()
	if err := h.api.resumeTailcat(ctx, 10*time.Millisecond, time.Hour); err != nil {
		t.Fatal(err)
	}
	time.Sleep(300 * time.Millisecond)
	mu.Lock()
	healthy := probes
	up = false
	mu.Unlock()
	if healthy > 1 {
		t.Fatalf("a healthy listener probed its relay %d times in 300ms; it should wait the slow interval", healthy)
	}
	// A fault found some other way -- a failed enrolment -- must switch the
	// loop to the fast rate at its next check; here the slow timer is already
	// running, so drive one check by hand and then watch the fast rate take over.
	h.api.checkTailcat(h.ctx)
	go h.api.watchTailcat(ctx, 10*time.Millisecond, time.Hour)
	time.Sleep(300 * time.Millisecond)
	mu.Lock()
	defer mu.Unlock()
	if probes-healthy < 5 {
		t.Fatalf("a listener with a fault probed only %d times in 300ms; it should check at the fast rate", probes-healthy)
	}
}

