	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/store"
)

// A revoked token lingered in the list for ever, so a list kept tidy by
// revoking filled up with credentials nobody could use. Deleting removes them,
// but only once they are spent: a live token that vanished from the list would
// still work, with nothing left on the page to say so.
func TestDeletingATokenNeedsItToBeRevokedOrExpiredFirst(t *testing.T) {
	h := newHarness(t)
	_, cookie := h.user("root", store.RoleAdmin)
	id := mintToken(t, h, cookie, "ci-deploy", store.RoleViewer)
	purge := request{method: http.MethodDelete, path: "/api/v1/tokens/" + id + "?purge=true", cookie: cookie}

	cases := []struct {
		name   string
		before func()
		want   int
		inList bool
	}{
		{name: "an active token is refused", want: http.StatusConflict, inList: true},
		{name: "a revoked one is deleted", before: func() {
			h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + id, cookie: cookie}).
				mustStatus(t, http.StatusNoContent, "revoke")
		}, want: http.StatusNoContent},
		{name: "a second delete finds nothing", want: http.StatusNotFound},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if tc.before != nil {
				tc.before()
			}
			resp := h.do(purge)
			resp.mustStatus(t, tc.want, "delete")
			if tc.want == http.StatusConflict && !strings.Contains(resp.errorMessage(t), "revoke it first") {
				t.Errorf("a refused delete should say what to do instead: %q", resp.errorMessage(t))
			}
			var found bool
			for _, tok := range listTokens(t, h, cookie).Items {
				found = found || tok.ID == id
			}
			if found != tc.inList {
				t.Errorf("token in the list = %v, want %v", found, tc.inList)
			}
		})
	}
}

// The audit trail outlives the row: once a token is deleted, the revoke and
// delete rows are the only record that it existed, so they must name it by
// its prefix -- which an operator can match to a leaked string -- and never
// carry the secret.
func TestRevokingAndDeletingATokenAreAuditedByPrefix(t *testing.T) {
	h := newHarness(t)
	_, cookie := h.user("root", store.RoleAdmin)
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
		body: map[string]any{"name": "old-laptop", "role": "viewer"}})
	resp.mustStatus(t, http.StatusCreated, "mint")
	var minted struct{ ID, Prefix, Token string }
	resp.into(t, &minted)

	h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + minted.ID, cookie: cookie}).
		mustStatus(t, http.StatusNoContent, "revoke")
	h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + minted.ID + "?purge=true", cookie: cookie}).
		mustStatus(t, http.StatusNoContent, "delete")

	events, _, err := h.st.ListAudit(h.ctx, store.AuditFilter{TargetID: minted.ID}, store.Page{Limit: 50})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	seen := map[string]bool{}
	for _, e := range events {
		seen[e.Action] = true
		if strings.Contains(e.Before+e.After, minted.Token) {
			t.Errorf("%s carries the token's secret", e.Action)
		}
		if (e.Action == "token.revoke" || e.Action == "token.delete") && !strings.Contains(e.After, minted.Prefix) {
			t.Errorf("%s does not name the token's prefix %q: %s", e.Action, minted.Prefix, e.After)
		}
	}
	for _, want := range []string{"token.revoke", "token.delete"} {
		if !seen[want] {
			t.Errorf("no %s audit row survived the deletion", want)
		}
	}
}

// Purging is safe to press without reading the list: it takes only what is
// already spent, and only from the owners the caller asked for.
func TestPurgingTokensTakesOnlySpentOnesFromTheOwnersAskedFor(t *testing.T) {
	h := newHarness(t)
	me, cookie := h.user("root", store.RoleAdmin)
	other, _ := h.user("colleague", store.RoleAdmin)
	plat, _ := h.user("operator-of-record", store.RolePlatform)

	type seed struct {
		owner   *store.User
		revoked bool
		expired bool
	}
	seeds := map[string]seed{
		"mine-active":   {owner: me},
		"mine-revoked":  {owner: me, revoked: true},
		"mine-expired":  {owner: me, expired: true},
		"other-active":  {owner: other},
		"other-revoked": {owner: other, revoked: true},
		"plat-revoked":  {owner: plat, revoked: true},
	}
	mint := func(t *testing.T) map[string]string {
		ids := map[string]string{}
		for name, sd := range seeds {
			var exp *time.Time
			if sd.expired {
				exp = ptr(time.Now().Add(50 * time.Millisecond))
			}
			tok, _, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{
				Name: name, Role: store.RoleViewer, UserID: sd.owner.ID, OwnerRole: sd.owner.Role, ExpiresAt: exp,
			})
			if err != nil {
				t.Fatalf("minting %s: %v", name, err)
			}
			if sd.revoked {
				if err := h.ctrl.Auth().RevokeAPIToken(h.ctx, tok.ID); err != nil {
					t.Fatalf("revoking %s: %v", name, err)
				}
			}
			ids[name] = tok.ID
		}
		time.Sleep(80 * time.Millisecond)
		return ids
	}

	cases := []struct {
		name string
		body map[string]any
		gone []string
	}{
		{name: "by default, the caller's own", gone: []string{"mine-revoked", "mine-expired"}},
		{name: "one named account", body: map[string]any{"user_id": other.ID}, gone: []string{"other-revoked"}},
		// An administrator cannot see the platform's tokens, so cannot purge them.
		{name: "everything visible", body: map[string]any{"all": true}, gone: []string{"mine-revoked", "mine-expired", "other-revoked"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ids := mint(t)
			resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens/purge", cookie: cookie, body: tc.body})
			resp.mustStatus(t, http.StatusOK, "purge")
			var out struct {
				Deleted []struct{ ID string } `json:"deleted"`
			}
			resp.into(t, &out)
			deleted := map[string]bool{}
			for _, d := range out.Deleted {
				deleted[d.ID] = true
			}
			want := map[string]bool{}
			for _, n := range tc.gone {
				want[ids[n]] = true
			}
			for name, id := range ids {
				if deleted[id] != want[id] {
					t.Errorf("%s deleted = %v, want %v", name, deleted[id], want[id])
				}
			}
			all, err := h.st.ListAPITokens(h.ctx)
			if err != nil {
				t.Fatalf("ListAPITokens: %v", err)
			}
			for _, tok := range all {
				if want[tok.ID] {
					t.Errorf("%s is still in the store", tok.Name)
				}
			}
		})
	}
}

// Anybody may purge their own spent tokens; anybody else's is an
// administrator's to purge, and the refusal says so.
func TestPurgingEverybodysTokensNeedsAnAdministrator(t *testing.T) {
	h := newHarness(t)
	_, cookie := h.user("watcher", store.RoleOperator)
	other, _ := h.user("colleague", store.RoleOperator)
	for _, body := range []map[string]any{{"all": true}, {"user_id": other.ID}} {
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens/purge", cookie: cookie, body: body})
		resp.mustStatus(t, http.StatusForbidden, fmt.Sprint(body))
		if !strings.Contains(strings.ToLower(resp.errorMessage(t)), "admin") {
			t.Errorf("%v: the refusal does not name the role: %q", body, resp.errorMessage(t))
		}
	}
}

// Both at once used to read as "all", so a caller who meant one account's
// tokens purged every account's. Ambiguity is refused rather than guessed.
func TestPurgingTokensRefusesBothOneAccountAndAll(t *testing.T) {
	h := newHarness(t)
	me, cookie := h.user("root", store.RoleAdmin)
	other, _ := h.user("colleague", store.RoleAdmin)
	tok, _, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{Name: "spent", Role: store.RoleViewer, UserID: me.ID})
	if err != nil {
		t.Fatalf("CreateAPIToken: %v", err)
	}
	if err := h.ctrl.Auth().RevokeAPIToken(h.ctx, tok.ID); err != nil {
		t.Fatalf("RevokeAPIToken: %v", err)
	}
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens/purge", cookie: cookie,
		body: map[string]any{"user_id": other.ID, "all": true}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "purge with both")
	if !strings.Contains(resp.errorMessage(t), "user_id") {
		t.Errorf("the refusal does not say what to change: %q", resp.errorMessage(t))
	}
	all, err := h.st.ListAPITokens(h.ctx)
	if err != nil {
		t.Fatalf("ListAPITokens: %v", err)
	}
	if len(all) != 1 {
		t.Errorf("a refused purge deleted tokens: %d left, want 1", len(all))
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// A token narrowed to one resource used to be one request away from an
// unscoped admin token with no owner and no expiry: the minting route only
// asked for tokens.write, capped nothing at the caller, and attributed the
// result to nobody, so revoking the leaked token and disabling its owner left
// the minted one answering. Every step of that path is closed here.
func TestATokenCannotMintPastItself(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("admin", store.RoleAdmin)
	_, narrow, err := h.ctrl.Auth().CreateAPIToken(h.ctx, auth.NewToken{
		Name: "ci-only-tokens", Role: store.RoleAdmin, UserID: admin.ID, Scopes: []string{"tokens:*"},
	})
	if err != nil {
		t.Fatal(err)
	}

	// Unscoped, which would carry the whole admin role.
	wide := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", token: narrow,
		body: map[string]any{"name": "escaped", "role": "admin"}})
	wide.mustStatus(t, http.StatusUnprocessableEntity, "mint an unscoped token from a scoped one")
	if msg := wide.errorMessage(t); !strings.Contains(msg, "tokens:*") {
		t.Errorf("the refusal does not name the caller's limit: %q", msg)
	}

	// Scoped, but to a resource the caller cannot reach.
	beyond := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", token: narrow,
		body: map[string]any{"name": "escaped", "role": "admin", "scopes": []string{"pools:write"}}})
	beyond.mustStatus(t, http.StatusUnprocessableEntity, "mint a token reaching past the caller's scopes")
	if msg := beyond.errorMessage(t); !strings.Contains(msg, "pools:write") {
		t.Errorf("the refusal does not name the scope that reaches too far: %q", msg)
	}

	// Within its limit is fine, and the result belongs to the same account
	// as the token that made it.
	within := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", token: narrow,
		body: map[string]any{"name": "within", "role": "viewer", "scopes": []string{"tokens:read"}}})
	within.mustStatus(t, http.StatusCreated, "mint a token within the caller's scopes")
	var minted createdTokenResponse
	within.into(t, &minted)
	row, err := h.st.GetAPITokenByHash(h.ctx, cryptox.HashToken(minted.Token))
	if err != nil {
		t.Fatal(err)
	}
	if row.UserID != admin.ID {
		t.Fatalf("a token minted by %s's token is attributed to %q, want %s", admin.Username, row.UserID, admin.ID)
	}

	// So disabling the account ends the descendant too. Another administrator
	// exists first, because the last one cannot be disabled.
	h.user("other-admin", store.RoleAdmin)
	if err := h.ctrl.Auth().SetUserDisabled(h.ctx, admin.ID, true); err != nil {
		t.Fatal(err)
	}
	after := h.do(request{method: http.MethodGet, path: "/api/v1/tokens", token: minted.Token})
	after.mustStatus(t, http.StatusUnauthorized, "use a token whose owner's account was disabled")
}

// A role is capped the same way: an operator's session cannot hand out admin.
func TestAnOperatorCannotMintAnAdminToken(t *testing.T) {
	h := newHarness(t)
	_, cookie := h.user("ops", store.RoleOperator)
	// Anybody signed in may mint their own tokens, so the cap on the role is
	// the gate that matters here.
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
		body: map[string]any{"name": "escaped", "role": "admin"}})
	if resp.status == http.StatusCreated {
		t.Fatal("an operator minted an admin token")
	}
}

// A token nobody owns has nobody to attribute a descendant to, and a token
// with no owner is one that survives every account-level revocation. Such a
// token keeps working for everything else it was made for; it just cannot
// make more.
func TestAnOwnerlessTokenCannotMintTokens(t *testing.T) {
	h := newHarness(t)
	orphan := h.token("ownerless", store.RoleAdmin)
	resp := h.do(request{method: http.MethodPost, path: "/api/v1/tokens", token: orphan,
		body: map[string]any{"name": "descendant", "role": "viewer"}})
	resp.mustStatus(t, http.StatusUnprocessableEntity, "mint from a token with no owner")
	if msg := resp.errorMessage(t); !strings.Contains(msg, "no owner") {
		t.Errorf("the refusal does not say why: %q", msg)
	}
	// It still does its own job.
	h.do(request{method: http.MethodGet, path: "/api/v1/pools", token: orphan}).mustStatus(t, http.StatusOK, "use the ownerless token")
}

package api

import (
	"encoding/json"
	"net/http"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

type tokenList struct {
	Items []struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	} `json:"items"`
}

func mintToken(t *testing.T, h *harness, cookie, name string, role store.Role) string {
	t.Helper()
	resp := h.do(request{
		method: http.MethodPost, path: "/api/v1/tokens", cookie: cookie,
		body: map[string]any{"name": name, "role": string(role)},
	})
	if resp.status != http.StatusCreated {
		t.Fatalf("minting %q: %d %s", name, resp.status, resp.body)
	}
	var out struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(resp.body, &out); err != nil {
		t.Fatalf("decoding the new token: %v", err)
	}
	return out.ID
}

func listTokens(t *testing.T, h *harness, cookie string) tokenList {
	t.Helper()
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/tokens", cookie: cookie})
	if resp.status != http.StatusOK {
		t.Fatalf("listing tokens: %d %s", resp.status, resp.body)
	}
	var out tokenList
	if err := json.Unmarshal(resp.body, &out); err != nil {
		t.Fatalf("decoding the token list: %v", err)
	}
	return out
}

// A platform account operating an instance for another team needs automation
// against it -- a metrics scraper, a backup verifier -- and those credentials
// sat on the same page the fleet's administrators use, revocable by any of
// them. A fleet that can switch off the monitoring of a process it does not
// run can do so by accident.
func TestAPlatformsOwnTokensAreNotTheFleetsToSeeOrRevoke(t *testing.T) {
	h := newHarness(t)
	plat, _ := h.user("operator-of-record", store.RolePlatform)
	platCookie := h.session(plat)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	adminCookie := h.session(admin)

	scraper := mintToken(t, h, platCookie, "metrics-scraper", store.RoleViewer)
	fleets := mintToken(t, h, adminCookie, "deploy-bot", store.RoleOperator)

	// The fleet sees its own and not the platform's.
	asAdmin := listTokens(t, h, adminCookie)
	for _, tok := range asAdmin.Items {
		if tok.ID == scraper {
			t.Errorf("an administrator was shown the platform's %q", tok.Name)
		}
	}
	var sawOwn bool
	for _, tok := range asAdmin.Items {
		if tok.ID == fleets {
			sawOwn = true
		}
	}
	if !sawOwn {
		t.Error("an administrator cannot see the fleet's own token; the filter took too much")
	}

	// And cannot revoke what it cannot see. A 404 rather than a 403: refusing
	// would confirm the credential exists, which is the fact being withheld.
	resp := h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + scraper, cookie: adminCookie})
	if resp.status != http.StatusNotFound {
		t.Errorf("revoking the platform's token as an administrator = %d, want 404: %s", resp.status, resp.body)
	}

	// The platform sees both, and its own still works.
	asPlatform := listTokens(t, h, platCookie)
	var sawScraper, sawFleets bool
	for _, tok := range asPlatform.Items {
		switch tok.ID {
		case scraper:
			sawScraper = true
		case fleets:
			sawFleets = true
		}
	}
	if !sawScraper || !sawFleets {
		t.Errorf("the platform saw its own=%v and the fleet's=%v; it should see both", sawScraper, sawFleets)
	}
	if got := h.do(request{method: http.MethodDelete, path: "/api/v1/tokens/" + scraper, cookie: platCookie}); got.status != http.StatusNoContent {
		t.Errorf("the platform could not revoke its own token: %d %s", got.status, got.body)
	}
}

// A token minted before the column existed has no owner recorded. Guessing one
// from the token's role would hide the fleet's own automation from it, because
// migration 0045 promoted every administrator's token to the platform role for
// an unrelated reason -- to keep what it could already do.
func TestATokenFromBeforeTheColumnStaysVisible(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)

	legacy := &store.APIToken{
		Name: "nightly-backup", Role: store.RolePlatform, OwnerRole: "",
		TokenHash: "hash-legacy", Prefix: "zoo_legacy",
	}
	if err := h.st.CreateAPIToken(h.ctx, legacy); err != nil {
		t.Fatalf("seeding a token from before the column: %v", err)
	}

	var found bool
	for _, tok := range listTokens(t, h, h.session(admin)).Items {
		if tok.ID == legacy.ID {
			found = true
		}
	}
	if !found {
		t.Error("a token from before the column vanished from the administrator who could see it yesterday")
	}
}

// An audit row's `ip` says where a colleague was working from. That is a fact
// about a person rather than about the fleet, and an operator who can read
// that their administrator signed in from a hotel has learned something the
// audit log exists to record rather than to publish. Administrators keep it,
// because chasing a suspicious sign-in is why the column is there.
func TestTheAuditAddressIsForAdministrators(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	adminCookie := h.session(admin)

	// Something to audit, from a known address.
	mintToken(t, h, adminCookie, "audited-token", store.RoleViewer)

	read := func(cookie string) []struct {
		Action string `json:"action"`
		IP     string `json:"ip"`
	} {
		t.Helper()
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/audit", cookie: cookie})
		if resp.status != http.StatusOK {
			t.Fatalf("reading the audit log: %d %s", resp.status, resp.body)
		}
		var out struct {
			Items []struct {
				Action string `json:"action"`
				IP     string `json:"ip"`
			} `json:"items"`
		}
		if err := json.Unmarshal(resp.body, &out); err != nil {
			t.Fatalf("decoding the audit log: %v", err)
		}
		return out.Items
	}

	asAdmin := read(adminCookie)
	var adminSawAnAddress bool
	for _, e := range asAdmin {
		if e.IP != "" {
			adminSawAnAddress = true
		}
	}
	if !adminSawAnAddress {
		t.Fatal("no audit row carried an address for an administrator, so this proves nothing")
	}

	operator, _ := h.user("fleet-operator", store.RoleOperator)
	for _, e := range read(h.session(operator)) {
		if e.IP != "" {
			t.Errorf("an operator was shown the address %q on a %q row", e.IP, e.Action)
		}
	}
}

