// TestStructuredDataIsNotAllowedToRun covers a policy that has to stay
// truthful: JSON-LD is data the browser never executes, so hashing it into
// script-src would widen the policy to cover something that is not a script.
func TestStructuredDataIsNotAllowedToRun(t *testing.T) {
	page := []byte(`<script type="application/ld+json">{"@type":"WebApplication"}</script>` +
		`<script>console.log(1)</script>`)
	got := inlineScriptHashes(page)
	if len(got) != 1 {
		t.Fatalf("%d hashes for one executable script: %v", len(got), got)
	}
}

// TestAnUpgradedControllerStopsServing304ForIndex is the regression test for
// the bug that made a route fail to load after every upgrade.
//
// index.html is sent no-cache, so a browser revalidates it on every visit. It
// used to be given a Last-Modified taken from buildTime(), a constant, which
// meant an upgraded controller answered that revalidation 304 and the browser
// kept the previous build's page -- and with it the names of content-hashed
// chunks that are no longer in the binary. The shell booted anyway from its own
// immutable cached bundle, so what the operator saw was one route, the first
// one they had not already visited, failing with "That page could not be
// loaded" until they bypassed the cache by hand.
func TestAnUpgradedControllerStopsServing304ForIndex(t *testing.T) {
	before, err := newSPAHandler("https://zoomies.test", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}

	first := httptest.NewRecorder()
	before.ServeHTTP(first, httptest.NewRequest(http.MethodGet, "/", nil))
	if first.Code != http.StatusOK {
		t.Fatalf("first load = %d, want 200", first.Code)
	}
	etag := first.Header().Get("ETag")
	if etag == "" {
		t.Fatal("index.html was served with no ETag, so nothing but the clock can validate it")
	}
	// Sending one would re-open the hole: a browser holding the old page sends
	// only If-Modified-Since, and ServeContent honours it whenever a
	// modification time is set.
	if got := first.Header().Get("Last-Modified"); got != "" {
		t.Errorf("Last-Modified = %q, want it absent so If-Modified-Since cannot decide this", got)
	}

	// The operator upgrades. The page changes, because it names new chunks.
	after := *before
	after.index = []byte("<!doctype html><script type=module src=/assets/index.NEW.js></script>")
	sum := sha256.Sum256(after.index)
	after.indexETag = `"` + base64.RawURLEncoding.EncodeToString(sum[:16]) + `"`

	// A browser that cached before the fix has no ETag to send, only a date.
	stale := httptest.NewRequest(http.MethodGet, "/", nil)
	stale.Header.Set("If-Modified-Since", buildTime().UTC().Format(http.TimeFormat))
	staleResp := httptest.NewRecorder()
	after.ServeHTTP(staleResp, stale)
	if staleResp.Code != http.StatusOK {
		t.Errorf("a browser holding the old page got %d; it keeps the previous build's chunk URLs, which 404",
			staleResp.Code)
	}

	// And one that has the new validator is told, correctly, that the page it
	// is holding is no longer the page being served.
	revalidate := httptest.NewRequest(http.MethodGet, "/", nil)
	revalidate.Header.Set("If-None-Match", etag)
	revalidateResp := httptest.NewRecorder()
	after.ServeHTTP(revalidateResp, revalidate)
	if revalidateResp.Code != http.StatusOK {
		t.Errorf("revalidating a changed page = %d, want 200", revalidateResp.Code)
	}
}

// TestAnUnchangedIndexStillRevalidatesTo304 is the other half: the fix must not
// turn every visit into a full download of a page that has not changed.
func TestAnUnchangedIndexStillRevalidatesTo304(t *testing.T) {
	h, err := newSPAHandler("https://zoomies.test", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	first := httptest.NewRecorder()
	h.ServeHTTP(first, httptest.NewRequest(http.MethodGet, "/", nil))
	etag := first.Header().Get("ETag")

	again := httptest.NewRequest(http.MethodGet, "/", nil)
	again.Header.Set("If-None-Match", etag)
	againResp := httptest.NewRecorder()
	h.ServeHTTP(againResp, again)
	if againResp.Code != http.StatusNotModified {
		t.Errorf("revalidating an unchanged page = %d, want 304", againResp.Code)
	}
}

// TestTwoExternalURLsGetDifferentIndexValidators covers the reason the ETag is
// computed after the startup substitution rather than from the embedded file:
// the same binary serves a different page depending on what it was told its
// address is.
func TestTwoExternalURLsGetDifferentIndexValidators(t *testing.T) {
	one, err := newSPAHandler("https://one.example", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	two, err := newSPAHandler("https://two.example", false)
	if err != nil {
		t.Fatalf("newSPAHandler: %v", err)
	}
	// A build with no UI has no sharing tags to substitute into, so there is
	// nothing that could differ.
	if !one.built {
		t.Skip("the UI was not built; the placeholder page has no address in it")
	}
	if one.indexETag == two.indexETag {
		t.Error("two controllers on different addresses serve the same validator for different pages")
	}
}

package api

import (
	"net/http"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The Workflows page lists runs and opens each to its jobs, and both halves
// come from the same rows: a run's row sums the jobs GET /jobs?run_id= lists
// under it, so the two cannot disagree about how the run is getting on.
func TestWorkflowRunsAreListedAndOpenToTheirJobs(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	running := h.job(pool, store.JobInProgress) // run 1, queued a minute ago

	queued := time.Now().Add(-2 * time.Minute)
	started := queued.Add(time.Second)
	done := queued.Add(30 * time.Second)
	for _, j := range []*store.Job{
		{GitHubJobID: 201, JobName: "build", State: store.JobCompleted, Conclusion: "success"},
		{GitHubJobID: 202, JobName: "test", State: store.JobCompleted, Conclusion: "failure"},
	} {
		j.GitHubRunID, j.RunNumber, j.RunAttempt = 2, 42, 1
		j.Repo, j.Workflow, j.HeadBranch = "acme/widgets", "ci", "main"
		j.Labels = store.StringSlice{"self-hosted", "linux", "x64"}
		j.InstallationID, j.PoolID, j.Matched = pool.InstallationID, pool.ID, true
		j.QueuedAt, j.StartedAt, j.CompletedAt = queued, &started, &done
		j.HTMLURL = "https://github.com/acme/widgets/actions/runs/2/job/" + j.JobName
		if _, err := h.st.UpsertJob(h.ctx, j); err != nil {
			t.Fatalf("recording %s: %v", j.JobName, err)
		}
	}
	_, cookie := h.user("viewer", store.RoleViewer)

	type run struct {
		GitHubRunID int64  `json:"github_run_id"`
		RunNumber   int64  `json:"run_number"`
		State       string `json:"state"`
		Conclusion  string `json:"conclusion"`
		HTMLURL     string `json:"html_url"`
		Managed     bool   `json:"managed"`
		Jobs        struct {
			Total     int `json:"total"`
			Succeeded int `json:"succeeded"`
			Failed    int `json:"failed"`
		} `json:"jobs"`
		DurationMS int64 `json:"duration_ms"`
	}
	var page struct {
		Items []run `json:"items"`
		Total int   `json:"total"`
	}
	resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?sort=queued_at&order=asc", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "listing workflow runs")
	resp.into(t, &page)
	if page.Total != 2 || len(page.Items) != 2 {
		t.Fatalf("runs = %+v (total %d), want the two runs", page.Items, page.Total)
	}
	failed := page.Items[0]
	if failed.GitHubRunID != 2 || failed.RunNumber != 42 || failed.State != "completed" || failed.Conclusion != "failure" {
		t.Fatalf("first run = %+v, want run 2 (#42) completed as a failure", failed)
	}
	if failed.Jobs.Total != 2 || failed.Jobs.Succeeded != 1 || failed.Jobs.Failed != 1 || !failed.Managed {
		t.Fatalf("run 2 = %+v, want two jobs, one each way, on this fleet", failed)
	}
	if failed.HTMLURL != "https://github.com/acme/widgets/actions/runs/2" {
		t.Fatalf("run 2 links to %q, want the run's own page", failed.HTMLURL)
	}
	if failed.DurationMS != 29_000 {
		t.Fatalf("run 2 took %dms, want the 29s from first start to last finish", failed.DurationMS)
	}
	if got := page.Items[1]; got.GitHubRunID != running.GitHubRunID || got.State != "in_progress" || got.Conclusion != "" {
		t.Fatalf("second run = %+v, want run 1 still in progress", got)
	}

	// The status views name the run's own status.
	for _, tc := range []struct {
		query string
		want  int64
	}{
		{"failed=true", 2},
		{"state=in_progress", 1},
		{"conclusion=failure", 2},
	} {
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?" + tc.query, cookie: cookie})
		resp.mustStatus(t, http.StatusOK, "listing runs by "+tc.query)
		resp.into(t, &page)
		if page.Total != 1 || len(page.Items) != 1 || page.Items[0].GitHubRunID != tc.want {
			t.Errorf("%s: runs = %+v (total %d), want run %d alone", tc.query, page.Items, page.Total, tc.want)
		}
	}

	// Opening a run is the job listing narrowed to it.
	var jobs struct {
		Items []struct {
			GitHubRunID int64  `json:"github_run_id"`
			JobName     string `json:"job_name"`
		} `json:"items"`
		Total int `json:"total"`
	}
	resp = h.do(request{method: http.MethodGet, path: "/api/v1/jobs?repo=acme/widgets&run_id=2&sort=queued_at&order=asc", cookie: cookie})
	resp.mustStatus(t, http.StatusOK, "listing a run's jobs")
	resp.into(t, &jobs)
	if jobs.Total != 2 || len(jobs.Items) != 2 || jobs.Items[0].GitHubRunID != 2 || jobs.Items[1].GitHubRunID != 2 {
		t.Fatalf("jobs of run 2 = %+v (total %d), want its two", jobs.Items, jobs.Total)
	}

	// A run ID that is not one is refused rather than matching nothing.
	h.do(request{method: http.MethodGet, path: "/api/v1/jobs?run_id=latest", cookie: cookie}).
		mustStatus(t, http.StatusBadRequest, "a run ID that is not a number")
	h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?state=running", cookie: cookie}).
		mustStatus(t, http.StatusBadRequest, "a state GitHub does not have")
	h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs"}).
		mustStatus(t, http.StatusUnauthorized, "listing runs without signing in")
}

// The Workflows page offers Run now, Pause and Resume on a run's own row, so
// an operator who knows the run from a pull request can hold or hurry all of
// it without opening it and pressing the same button on each job inside. It
// is the Queue page's control over the run's queued jobs, and no more: what
// GitHub thinks of the run does not change, and a job an operator removed
// from the queue on purpose is not swept back in by a Run now on its run.
func TestAWorkflowRunsQueuedJobsAreControlledTogether(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux")
	queued := time.Now().Add(-time.Minute)
	for _, j := range []*store.Job{
		{GitHubJobID: 301, JobName: "build", State: store.JobQueued},
		{GitHubJobID: 302, JobName: "test", State: store.JobQueued},
		{GitHubJobID: 303, JobName: "lint", State: store.JobQueued},
		{GitHubJobID: 304, JobName: "package", State: store.JobCompleted, Conclusion: "success"},
	} {
		j.GitHubRunID, j.RunNumber, j.RunAttempt = 7, 77, 1
		j.Repo, j.Workflow, j.HeadBranch = "acme/widgets", "ci", "main"
		j.Labels = store.StringSlice{"self-hosted", "linux", "x64"}
		j.InstallationID, j.PoolID, j.Matched = pool.InstallationID, pool.ID, true
		j.QueuedAt = queued
		if j.State == store.JobCompleted {
			started, done := queued.Add(time.Second), queued.Add(30*time.Second)
			j.StartedAt, j.CompletedAt = &started, &done
		}
		if _, err := h.st.UpsertJob(h.ctx, j); err != nil {
			t.Fatalf("recording %s: %v", j.JobName, err)
		}
	}
	lint, err := h.st.GetJobByGitHubID(h.ctx, 303)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.st.ControlProvisioning(h.ctx, []string{lint.ID}, "delete"); err != nil {
		t.Fatal(err)
	}
	_, operator := h.user("operator", store.RoleOperator)
	_, viewer := h.user("viewer", store.RoleViewer)

	body := map[string]any{"repo": "acme/widgets", "run_id": 7, "action": "pause"}
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: viewer}).
		mustStatus(t, http.StatusForbidden, "a viewer pausing a run")
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", cookie: operator,
		body: map[string]any{"repo": "acme/widgets", "run_id": 7, "action": "delete"}}).
		mustStatus(t, http.StatusBadRequest, "removing a whole run from the queue")
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", cookie: operator,
		body: map[string]any{"repo": "acme/widgets", "run_id": 999, "action": "pause"}}).
		mustStatus(t, http.StatusNotFound, "a run this fleet has never heard of")

	before := len(h.gh.Requests())
	var out struct {
		Results []store.ProvisioningResult `json:"results"`
	}
	type run struct {
		Jobs store.RunJobCounts `json:"jobs"`
	}
	var page struct {
		Items []run `json:"items"`
	}
	counts := func(when string) store.RunJobCounts {
		t.Helper()
		resp := h.do(request{method: http.MethodGet, path: "/api/v1/workflow-runs?repo=acme/widgets&run_id=7", cookie: viewer})
		resp.mustStatus(t, http.StatusOK, "listing the run "+when)
		resp.into(t, &page)
		if len(page.Items) != 1 {
			t.Fatalf("%s: runs = %+v, want the one", when, page.Items)
		}
		return page.Items[0].Jobs
	}
	if got := counts("before anything"); got.Queued != 3 || got.Removed != 1 || got.Paused != 0 || got.Expedited != 0 {
		t.Fatalf("before anything: %+v, want three queued of which one removed", got)
	}

	for _, tc := range []struct {
		action                     string
		expedited, paused, removed int
	}{
		{"pause", 0, 2, 1},
		{"run_now", 2, 0, 1},
		{"resume", 0, 0, 1},
	} {
		body["action"] = tc.action
		resp := h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: operator})
		resp.mustStatus(t, http.StatusOK, tc.action)
		resp.into(t, &out)
		// The two queued jobs still in the queue, and never the removed one
		// or the one that finished.
		if len(out.Results) != 2 {
			t.Fatalf("%s: results = %+v, want the two queued jobs", tc.action, out.Results)
		}
		for _, r := range out.Results {
			if !r.OK || r.ID == lint.ID {
				t.Fatalf("%s: results = %+v", tc.action, out.Results)
			}
		}
		got := counts("after " + tc.action)
		if got.Queued != 3 || got.Expedited != tc.expedited || got.Paused != tc.paused || got.Removed != tc.removed {
			t.Fatalf("after %s: %+v, want expedited=%d paused=%d removed=%d", tc.action, got, tc.expedited, tc.paused, tc.removed)
		}
	}
	if len(h.gh.Requests()) != before {
		t.Fatal("a run's provisioning controls called GitHub")
	}

	// Once the removed job is all that is left queued, there is nothing for
	// the run's row to act on, and the answer says so rather than doing
	// nothing quietly.
	var ids []string
	for _, gh := range []int64{301, 302} {
		j, err := h.st.GetJobByGitHubID(h.ctx, gh)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, j.ID)
	}
	if _, err := h.st.ControlProvisioning(h.ctx, ids, "delete"); err != nil {
		t.Fatal(err)
	}
	h.do(request{method: http.MethodPost, path: "/api/v1/workflow-runs/provisioning", body: body, cookie: operator}).
		mustStatus(t, http.StatusConflict, "a run with nothing left in the queue")
}

package auth

import (
	"context"
	"fmt"
)

// ContextAccess adds the source-specific gate to the ordinary action policy.
// Admins still need membership to read source; configuring the feature is a
// separate authority. An unowned automation token has nobody's source access.
func (s *Service) ContextAccess(ctx context.Context, id *Identity, repositoryID string) (bool, error) {
	if !Allowed(id, ActionContextRead) || id.UserID == "" {
		return false, nil
	}
	switch id.Kind {
	case KindUser, KindToken:
		return s.store.AIContextUserAccess(ctx, repositoryID, id.UserID)
	case KindConnection:
		return s.store.AIContextConnectionAccess(ctx, repositoryID, id.ID, id.UserID)
	default:
		return false, nil
	}
}

// SetContextConnectionRepositories is a person's explicit source consent,
// independent of the role already approved for fleet tools. An agent must not
// be able to widen its own access by using the same token it wants to widen.
func (s *Service) SetContextConnectionRepositories(ctx context.Context, actor *Identity, grantID string, repositories []string) error {
	if actor == nil || actor.Kind != KindUser || actor.UserID == "" {
		return fmt.Errorf("%w: sign in as the connection's owner to choose its source repositories", ErrInvalidInput)
	}
	if err := s.store.ReplaceAIContextConnectionAccess(ctx, grantID, actor.UserID, repositories); err != nil {
		return err
	}
	s.audit.Act(ctx, actor, "mcp_connection.context", "mcp_connection", grantID, map[string]any{"repositories": len(repositories)})
	return nil
}

package auth

import (
	"testing"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/store"
)

func TestSourceAccessRequiresMembershipBeyondFleetRolesAndTokenScopes(t *testing.T) {
	s, st, _ := newService(t)
	u := addUser(t, st, "reader", store.RoleAdmin, nil)
	i := &store.Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: store.TargetOrg}
	if err := st.CreateInstallation(t.Context(), i); err != nil {
		t.Fatal(err)
	}
	r := &store.AIContextRepository{Key: aicontext.RepositoryKey{GitHubHost: "github.com", InstallationID: i.ID, RepositoryID: 1}, FullName: "acme/private", Config: aicontext.DefaultConfig("main")}
	if err := st.CreateAIContextRepository(t.Context(), r); err != nil {
		t.Fatal(err)
	}
	st.SetAIContextAvailable(t.Context(), r.ID, true)
	id := &Identity{Kind: KindUser, ID: u.ID, UserID: u.ID, Role: u.Role}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
		t.Fatal("admin implicitly gained source access")
	}
	if err := st.ReplaceAIContextMembers(t.Context(), r.ID, []string{u.ID}); err != nil {
		t.Fatal(err)
	}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || !allowed {
		t.Fatal("member refused")
	}
	for _, id := range []*Identity{nil, {Kind: KindToken, Role: store.RoleAdmin}, {Kind: KindToken, UserID: u.ID, Role: store.RoleAdmin, Scopes: []string{"jobs:read"}}, {Kind: KindConnection, ID: "old-connection", UserID: u.ID, Role: store.RoleViewer}, {Kind: KindAgent, UserID: u.ID, Role: store.RoleAdmin}} {
		if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
			t.Fatalf("source granted to %#v: %v", id, err)
		}
	}
	id = &Identity{Kind: KindToken, UserID: u.ID, Role: store.RoleViewer, Scopes: []string{"context:read"}}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || !allowed {
		t.Fatal("owned scoped token refused")
	}
	u.Disabled = true
	if err := st.UpdateUser(t.Context(), u); err != nil {
		t.Fatal(err)
	}
	if allowed, err := s.ContextAccess(t.Context(), id, r.ID); err != nil || allowed {
		t.Fatal("cached identity outlived disabled user")
	}
}

func TestAnAgentCannotGrantItselfSourceConsent(t *testing.T) {
	s, _, _ := newService(t)
	for _, actor := range []*Identity{nil, {Kind: KindToken, UserID: "owner", Role: store.RoleAdmin}, {Kind: KindConnection, UserID: "owner", Role: store.RoleOperator}} {
		if err := s.SetContextConnectionRepositories(t.Context(), actor, "grant", []string{"repository"}); err == nil {
			t.Fatal("agent widened its own consent")
		}
	}
}

package auth

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"reflect"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// Auditor writes the audit trail: one row per mutating action, with the actor,
// the target and a before/after picture whose secrets have been blanked.
type Auditor struct {
	store  *store.Store
	events *events.Bus
	logger *slog.Logger
}

// NewAuditor returns an auditor. bus may be nil, in which case rows are still
// written but the UI's audit page will only see them on its next fetch.
func NewAuditor(st *store.Store, bus *events.Bus, logger *slog.Logger) *Auditor {
	if logger == nil {
		logger = slog.Default()
	}
	return &Auditor{store: st, events: bus, logger: logger}
}

// maxAuditPayload caps a single before/after document. A pool with a very large
// environment map should not be able to turn the audit table into the biggest
// thing in the database.
const maxAuditPayload = 16 << 10

// Record writes one audit row and publishes it to the event bus.
//
// It returns an error for tests and for callers that genuinely want to know,
// but nothing in a request path should act on it: refusing an operator's change
// because the audit write failed would turn a logging problem into an outage,
// and the failure is already logged here. The convenience helpers below
// therefore discard it.
func (a *Auditor) Record(ctx context.Context, id *Identity, action, targetKind, targetID string, before, after any) error {
	ev := &store.AuditEvent{
		Action:     action,
		TargetKind: targetKind,
		TargetID:   targetID,
		Before:     a.encode(before),
		After:      a.encode(after),
		ActorKind:  KindSystem,
		ActorName:  "zoomies",
	}
	if id != nil {
		ev.ActorID, ev.ActorName, ev.ActorKind, ev.IP = id.ID, id.Name, id.Kind, id.IP
		if ev.ActorKind == "" {
			ev.ActorKind = KindSystem
		}
	}
	if err := a.store.AppendAudit(ctx, ev); err != nil {
		a.logger.Error("could not write audit entry", "action", action,
			"target_kind", targetKind, "target_id", targetID, "error", err)
		return err
	}
	if a.events != nil {
		a.events.Publish(events.KindAudit, "audit:"+targetKind, ev)
	}
	return nil
}

// Created records the creation of an object.
func (a *Auditor) Created(ctx context.Context, id *Identity, targetKind, targetID string, after any) {
	_ = a.Record(ctx, id, targetKind+".create", targetKind, targetID, nil, after)
}

// Updated records a change, keeping only the fields that actually differ so the
// audit page shows "max_runners 4 -> 8" rather than the whole object twice.
func (a *Auditor) Updated(ctx context.Context, id *Identity, targetKind, targetID string, before, after any) {
	b, af := Diff(before, after)
	if b == nil && af == nil {
		// Nothing changed. A row saying so is noise in the one log an operator
		// reads when something has gone wrong.
		return
	}
	_ = a.Record(ctx, id, targetKind+".update", targetKind, targetID, b, af)
}

// Deleted records a removal, keeping the object as it was.
func (a *Auditor) Deleted(ctx context.Context, id *Identity, targetKind, targetID string, before any) {
	_ = a.Record(ctx, id, targetKind+".delete", targetKind, targetID, before, nil)
}

// Act records an action that is not a create/update/delete -- draining a
// runner, cordoning a host, verifying an installation -- with whatever detail
// the caller wants preserved.
func (a *Auditor) Act(ctx context.Context, id *Identity, action, targetKind, targetID string, detail any) {
	_ = a.Record(ctx, id, action, targetKind, targetID, nil, detail)
}

// Auth records an authentication event: a login, a logout, a refused password.
// The identity may be partial -- a failed login knows the username and the
// address but not a user ID -- which is exactly what makes these rows useful.
func (a *Auditor) Auth(ctx context.Context, id *Identity, action string, detail any) {
	targetID := ""
	if id != nil {
		targetID = id.ID
	}
	_ = a.Record(ctx, id, action, "auth", targetID, nil, detail)
}

// encode renders a before/after document: redacted, JSON, and capped.
func (a *Auditor) encode(v any) string {
	if v == nil {
		return ""
	}
	b, err := json.Marshal(Redact(v))
	if err != nil {
		a.logger.Warn("could not render audit payload", "error", err)
		return ""
	}
	if len(b) > maxAuditPayload {
		// Truncating JSON in the middle would leave a document nothing can
		// parse, so say what happened instead of storing a broken one.
		a.logger.Warn("audit payload too large to store in full", "bytes", len(b))
		return fmt.Sprintf(`{"truncated":true,"bytes":%d}`, len(b))
	}
	return string(b)
}

// ---------------------------------------------------------------------------
// Redaction
// ---------------------------------------------------------------------------

// redactedMarker replaces a secret value. It matches what the logging package
// substitutes, so an operator sees the same word in both places.
const redactedMarker = "[redacted]"

// maxRedactDepth stops a cyclic structure from recursing forever. Nothing in
// the domain model is anywhere near this deep.
const maxRedactDepth = 12

// sensitiveTerms mark a field or map key as carrying a credential. They are
// matched as substrings of the name with punctuation removed, so "password"
// catches PasswordHash and new_password, and "secret" catches both
// client_secret and WebhookSecretEnc.
var sensitiveTerms = []string{
	"password", "token", "secret", "privatekey", "jitconfig",
	"encryptionkey", "clientsecret", "webhooksecret", "credential",
	"passphrase", "apikey",
}

// nameExceptions are suffixes that turn a would-be secret name back into a
// harmless one. A token's ID, its display name and its visible prefix are the
// things that make an audit row readable; blanking them would leave an entry
// that records that something happened to some token.
var nameExceptions = []string{
	"id", "ids", "name", "names", "prefix", "count", "at",
	"file", "path", "url", "type", "kind", "hint",
}

// Redact returns a copy of v -- as maps, slices and scalars -- with every value
// whose field or key name looks like a credential replaced by "[redacted]".
//
// It works on the shape a JSON document would have, not on the Go types, so the
// audit trail matches what the API shows. Fields tagged `json:"-"` are dropped
// entirely: in this codebase those are exactly the hashes and the sealed blobs,
// and they are absent from API responses for the same reason.
func Redact(v any) any { return redactValue(reflect.ValueOf(v), 0) }

var jsonMarshaler = reflect.TypeOf((*json.Marshaler)(nil)).Elem()

func redactValue(rv reflect.Value, depth int) any {
	if !rv.IsValid() {
		return nil
	}
	if depth > maxRedactDepth {
		return "[truncated]"
	}
	switch rv.Kind() {
	case reflect.Pointer, reflect.Interface:
		if rv.IsNil() {
			return nil
		}
		return redactValue(rv.Elem(), depth)
	}
	// A type that marshals itself -- time.Time, store.Duration -- is kept whole
	// so the audit entry shows "5m" and an RFC 3339 timestamp rather than a
	// nanosecond count. Containers are excluded: their contents still need
	// walking.
	if rv.Type().Implements(jsonMarshaler) && !isContainer(rv.Kind()) {
		if rv.CanInterface() {
			return rv.Interface()
		}
	}

	switch rv.Kind() {
	case reflect.Struct:
		return redactStruct(rv, depth)
	case reflect.Map:
		out := make(map[string]any, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			key := fmt.Sprint(iter.Key().Interface())
			if isSensitiveName(key) {
				out[key] = redactedValue(iter.Value())
				continue
			}
			out[key] = redactValue(iter.Value(), depth+1)
		}
		return out
	case reflect.Slice, reflect.Array:
		if rv.Kind() == reflect.Slice && rv.IsNil() {
			return nil
		}
		// A byte slice in this codebase is a sealed secret. Its length is
		// occasionally useful; its content never is.
		if rv.Type().Elem().Kind() == reflect.Uint8 {
			return fmt.Sprintf("[%d bytes]", rv.Len())
		}
		out := make([]any, rv.Len())
		for i := range rv.Len() {
			out[i] = redactValue(rv.Index(i), depth+1)
		}
		return out
	case reflect.Func, reflect.Chan, reflect.UnsafePointer:
		return nil
	default:
		if !rv.CanInterface() {
			return nil
		}
		return rv.Interface()
	}
}

func redactStruct(rv reflect.Value, depth int) map[string]any {
	t := rv.Type()
	out := make(map[string]any, t.NumField())
	for i := range t.NumField() {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		tag := f.Tag.Get("json")
		name, _, _ := strings.Cut(tag, ",")
		if name == "-" {
			continue
		}
		if f.Anonymous && name == "" {
			// An embedded struct is flattened, which is what encoding/json does.
			if inner, ok := redactValue(rv.Field(i), depth+1).(map[string]any); ok {
				for k, v := range inner {
					if _, taken := out[k]; !taken {
						out[k] = v
					}
				}
				continue
			}
		}
		if name == "" {
			name = f.Name
		}
		if isSensitiveName(name) || isSensitiveName(f.Name) {
			out[name] = redactedValue(rv.Field(i))
			continue
		}
		out[name] = redactValue(rv.Field(i), depth+1)
	}
	return out
}

// redactedValue blanks one value.
//
// An empty value stays empty: an audit entry that shows "password": "[redacted]"
// for an account that has no password would be a lie. A bool or a number is
// returned unchanged, because neither can carry a credential and blanking
// store.Setting.Secret -- a flag whose name matches -- would make the entry
// less readable rather than safer.
func redactedValue(rv reflect.Value) any {
	if !rv.IsValid() {
		return nil
	}
	switch rv.Kind() {
	case reflect.Bool,
		reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		if rv.CanInterface() {
			return rv.Interface()
		}
		return nil
	}
	if isEmptyValue(rv) {
		if rv.Kind() == reflect.String {
			return ""
		}
		return nil
	}
	return redactedMarker
}

func isEmptyValue(rv reflect.Value) bool {
	switch rv.Kind() {
	case reflect.Slice, reflect.Map, reflect.Array, reflect.String:
		return rv.Len() == 0
	case reflect.Pointer, reflect.Interface:
		return rv.IsNil()
	}
	return rv.IsZero()
}

func isContainer(k reflect.Kind) bool {
	return k == reflect.Map || k == reflect.Slice || k == reflect.Array
}

// isSensitiveName reports whether a field or key name means "this holds a
// credential".
func isSensitiveName(name string) bool {
	n := normalizeName(name)
	if n == "" {
		return false
	}
	matched := false
	for _, term := range sensitiveTerms {
		if strings.Contains(n, term) {
			matched = true
			break
		}
	}
	if !matched {
		return false
	}
	for _, ex := range nameExceptions {
		if n != ex && strings.HasSuffix(n, ex) {
			return false
		}
	}
	return true
}

// normalizeName lowercases a name and drops everything that is not a letter or
// a digit, so PasswordHash, password_hash and password-hash all compare equal.
func normalizeName(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// ---------------------------------------------------------------------------
// Diffing
// ---------------------------------------------------------------------------

// Diff returns the parts of before and after that differ, already redacted.
//
// An audit entry for "the operator raised max_runners" should say that and
// nothing else; printing two whole pool objects and leaving a human to spot the
// one changed number is how audit logs stop being read. Both results are nil
// when nothing changed.
func Diff(before, after any) (any, any) {
	b, a := Redact(before), Redact(after)
	bm, bok := b.(map[string]any)
	am, aok := a.(map[string]any)
	if !bok || !aok {
		if reflect.DeepEqual(b, a) {
			return nil, nil
		}
		return b, a
	}
	db, da := diffMaps(bm, am)
	var rb, ra any
	if len(db) > 0 {
		rb = db
	}
	if len(da) > 0 {
		ra = da
	}
	return rb, ra
}

func diffMaps(before, after map[string]any) (map[string]any, map[string]any) {
	db, da := map[string]any{}, map[string]any{}
	keys := make([]string, 0, len(before)+len(after))
	for k := range before {
		keys = append(keys, k)
	}
	for k := range after {
		if _, ok := before[k]; !ok {
			keys = append(keys, k)
		}
	}
	slices.Sort(keys)

	for _, k := range keys {
		bv, bok := before[k]
		av, aok := after[k]
		if bok && aok {
			bsub, bIsMap := bv.(map[string]any)
			asub, aIsMap := av.(map[string]any)
			if bIsMap && aIsMap {
				sb, sa := diffMaps(bsub, asub)
				if len(sb) > 0 {
					db[k] = sb
				}
				if len(sa) > 0 {
					da[k] = sa
				}
				continue
			}
			if reflect.DeepEqual(bv, av) {
				continue
			}
		}
		if bok {
			db[k] = bv
		}
		if aok {
			da[k] = av
		}
	}
	return db, da
}

package auth

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// secretful is a struct shaped like the ones the API actually audits: a couple
// of harmless fields, a secret at the top level, a secret one level down, and a
// map whose keys carry the secret names.
type secretful struct {
	Name     string            `json:"name"`
	TokenID  string            `json:"token_id"`
	Password string            `json:"password"`
	Count    int               `json:"count"`
	Nested   nested            `json:"nested"`
	Env      map[string]string `json:"env"`
	Peers    []nested          `json:"peers"`
	Hidden   string            `json:"-"`
}

type nested struct {
	Endpoint     string `json:"endpoint"`
	ClientSecret string `json:"client_secret"`
	PrivateKey   string `json:"private_key"`
	Empty        string `json:"webhook_secret"`
}

func TestRedactBlanksNestedSecrets(t *testing.T) {
	in := secretful{
		Name:     "acme",
		TokenID:  "tok_123",
		Password: "hunter2",
		Count:    3,
		Nested:   nested{Endpoint: "https://example.com", ClientSecret: "sh", PrivateKey: "-----BEGIN"},
		Env:      map[string]string{"HOME": "/home/runner", "GITHUB_TOKEN": "ghs_1", "region": "eu"},
		Peers:    []nested{{Endpoint: "https://b.example.com", ClientSecret: "shh"}},
		Hidden:   "never rendered",
	}

	out, ok := Redact(in).(map[string]any)
	if !ok {
		t.Fatalf("Redact returned %T; want a map", Redact(in))
	}

	if out["name"] != "acme" || out["count"] != 3 {
		t.Errorf("harmless fields were changed: %#v", out)
	}
	// An ID names a credential, it is not one; blanking it would leave an
	// audit entry that says something happened to some token.
	if out["token_id"] != "tok_123" {
		t.Errorf("token_id = %v; want it left alone", out["token_id"])
	}
	if out["password"] != redactedMarker {
		t.Errorf("password = %v; want it redacted", out["password"])
	}
	if _, present := out["Hidden"]; present {
		t.Error(`a json:"-" field reached the audit payload`)
	}

	nestedOut := out["nested"].(map[string]any)
	if nestedOut["endpoint"] != "https://example.com" {
		t.Errorf("nested endpoint = %v; want it left alone", nestedOut["endpoint"])
	}
	if nestedOut["client_secret"] != redactedMarker || nestedOut["private_key"] != redactedMarker {
		t.Errorf("nested secrets survived: %#v", nestedOut)
	}
	// An empty secret stays empty: "[redacted]" would claim a secret is set.
	if nestedOut["webhook_secret"] != "" {
		t.Errorf("empty secret = %v; want it left empty", nestedOut["webhook_secret"])
	}

	env := out["env"].(map[string]any)
	if env["HOME"] != "/home/runner" || env["region"] != "eu" {
		t.Errorf("harmless environment entries were changed: %#v", env)
	}
	if env["GITHUB_TOKEN"] != redactedMarker {
		t.Errorf("GITHUB_TOKEN = %v; want it redacted", env["GITHUB_TOKEN"])
	}

	peers := out["peers"].([]any)
	if len(peers) != 1 || peers[0].(map[string]any)["client_secret"] != redactedMarker {
		t.Errorf("secrets inside a slice survived: %#v", peers)
	}
}

func TestRedactHandlesDomainTypes(t *testing.T) {
	now := time.Date(2025, 3, 4, 10, 0, 0, 0, time.UTC)
	u := &store.User{
		ID: "usr_1", Username: "alice", Role: store.RoleAdmin,
		PasswordHash: "$argon2id$...", CreatedAt: now,
	}
	out := Redact(u).(map[string]any)
	if out["username"] != "alice" || out["role"] != store.RoleAdmin {
		t.Errorf("user fields were mangled: %#v", out)
	}
	if _, present := out["password_hash"]; present {
		t.Error("the password hash reached the audit payload")
	}
	if got, ok := out["created_at"].(time.Time); !ok || !got.Equal(now) {
		t.Errorf("created_at = %#v; want the time preserved so it renders as RFC 3339", out["created_at"])
	}

	// A sealed blob is reduced to its length: the ciphertext is of no use in an
	// audit entry and it is still key material.
	inst := &store.Installation{ID: "ins_1", Target: "acme", PrivateKeyEnc: []byte("ciphertext")}
	instOut := Redact(inst).(map[string]any)
	if instOut["target"] != "acme" {
		t.Errorf("target = %v", instOut["target"])
	}
	for k, v := range instOut {
		if s, ok := v.(string); ok && s == "ciphertext" {
			t.Errorf("field %q leaked sealed key material", k)
		}
	}

	// A Duration keeps its readable form rather than a nanosecond count.
	p := &store.Pool{Name: "linux", IdleTimeout: store.Duration(5 * time.Minute)}
	b, err := json.Marshal(Redact(p))
	if err != nil {
		t.Fatal(err)
	}
	if want := `"idle_timeout":"5m0s"`; !strings.Contains(string(b), want) {
		t.Errorf("marshalled pool = %s; want it to contain %s", b, want)
	}
}

func TestRedactKeepsFlagsAndSurvivesNil(t *testing.T) {
	// store.Setting.Secret is a flag whose name matches the sensitive list.
	// Blanking a bool makes the entry unreadable and protects nothing.
	out := Redact(store.Setting{Key: "oidc.client_secret", Value: "", Secret: true}).(map[string]any)
	if out["secret"] != true {
		t.Errorf("secret flag = %v; want true", out["secret"])
	}
	if Redact(nil) != nil {
		t.Error("Redact(nil) should be nil")
	}
	var p *secretful
	if Redact(p) != nil {
		t.Error("Redact of a nil pointer should be nil")
	}
}

func TestIsSensitiveName(t *testing.T) {
	sensitive := []string{"password", "PasswordHash", "new_password", "token", "TokenHash",
		"api_token", "client_secret", "WebhookSecretEnc", "private_key", "jit_config",
		"encryption_key", "GITHUB_TOKEN"}
	for _, n := range sensitive {
