	"golang.org/x/oauth2"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// OIDCCallbackPath is where the identity provider sends the browser back to.
// It has to match the redirect URI registered with the provider, so it is a
// constant rather than something an operator can drift out of sync.
const OIDCCallbackPath = "/api/v1/auth/oidc/callback"

// OIDCStateTTL is how long a login may sit half-finished at the identity
// provider before its state and nonce are forgotten.
const OIDCStateTTL = 10 * time.Minute

// maxPendingStates caps the state cache to bound its memory against a stream
// of unauthenticated calls to /auth/oidc/start. Real signins are a handful in
// flight at any moment on any real deployment; anything above this is a client
// that will not finish, and refusing new entries is what keeps the map from
// growing until the process runs out of memory.
const maxPendingStates = 1024

// ErrTooManyPendingSignIns reports that the state cache is at capacity, so a
// fresh sign-in cannot be remembered. It is returned from Start rather than
// from the cache itself so callers can shape the refusal.
var ErrTooManyPendingSignIns = errors.New("too many single sign-ins in flight; wait a moment and try again")

// ErrOIDCDiscovery marks a NewOIDC failure that is the identity provider's
// rather than the configuration's: it could not be reached, or did not answer
// with an OpenID configuration. It is the one kind worth trying again without
// anybody changing anything, and errors.Is tells the two apart.
var ErrOIDCDiscovery = errors.New("the identity provider's OpenID configuration could not be read")

// discoveryError keeps the sentence written for the operator as the message
// while answering errors.Is for both the cause and ErrOIDCDiscovery.
type discoveryError struct {
	msg   string
	cause error
}

func (e *discoveryError) Error() string   { return e.msg }
func (e *discoveryError) Unwrap() []error { return []error{e.cause, ErrOIDCDiscovery} }

// Claims is what a completed OIDC login tells us about the person, already
// mapped onto Zoomies' own vocabulary.
type Claims struct {
	// Subject is the provider's stable identifier for the person. It is what
	// accounts are linked by, because usernames and email addresses change.
	Subject string
	// Username is the account name inside Zoomies, from cfg.UsernameClaim.
	Username string
	Email    string
	// Name is the display name, if the provider sent one.
	Name string
	// Groups are the raw group values from cfg.GroupsClaim.
	Groups []string
	// Role is what those groups map to.
	Role store.Role
}

// OIDCProvider is optional single sign-on. A nil *OIDCProvider is a valid
// "SSO is switched off" value: every method tolerates it, so callers do not
// need a branch for the common case.
type OIDCProvider struct {
	cfg      config.OIDC
	oauth    oauth2.Config
	verifier *oidc.IDTokenVerifier
	states   *stateCache
	logger   *slog.Logger
}

// NewOIDC builds the provider, discovering the issuer's endpoints over the
// network. It returns (nil, nil) when SSO is disabled, so a caller can assign
// the result unconditionally.
//
// It is named NewOIDC rather than New because New is already this package's
// Service constructor.
func NewOIDC(ctx context.Context, cfg config.OIDC, externalURL string) (*OIDCProvider, error) {
	if !cfg.Enabled {
		return nil, nil
	}
	if strings.TrimSpace(cfg.Issuer) == "" {
		return nil, errors.New("oidc.enabled is on but oidc.issuer is empty; set it to your identity provider's issuer URL, e.g. https://login.example.com")
	}
	if cfg.ClientID == "" || cfg.ClientSecret == "" {
		return nil, errors.New("oidc.enabled is on but oidc.client_id or oidc.client_secret is empty; register Zoomies as an application with your identity provider and paste both here")
	}

	redirect := strings.TrimSpace(cfg.RedirectURL)
	if redirect == "" {
		if externalURL == "" {
			return nil, errors.New("oidc needs a redirect URL; set server.external_url so it can be derived, or set oidc.redirect_url explicitly")
		}
		redirect = strings.TrimRight(externalURL, "/") + OIDCCallbackPath
	}

	provider, err := oidc.NewProvider(ctx, strings.TrimRight(cfg.Issuer, "/"))
	if err != nil {
		return nil, &discoveryError{
			msg:   fmt.Sprintf("could not read the OpenID configuration from %s: %v; check oidc.issuer and that this host can reach it", cfg.Issuer, err),
			cause: err,
		}
	}

	scopes := cfg.Scopes
	if len(scopes) == 0 {
		scopes = []string{oidc.ScopeOpenID, "profile", "email"}
	}
	// Without the openid scope the provider returns no ID token at all, which
	// fails much later and much less clearly.
	if !containsFold(scopes, oidc.ScopeOpenID) {
		scopes = append([]string{oidc.ScopeOpenID}, scopes...)
	}

	return &OIDCProvider{
		cfg: cfg,
		oauth: oauth2.Config{
			ClientID:     cfg.ClientID,
			ClientSecret: cfg.ClientSecret,
			Endpoint:     provider.Endpoint(),
			RedirectURL:  redirect,
			Scopes:       scopes,
		},
		verifier: provider.Verifier(&oidc.Config{ClientID: cfg.ClientID}),
		states:   newStateCache(OIDCStateTTL, time.Now),
		logger:   slog.Default(),
	}, nil
}

// Enabled reports whether single sign-on is configured.
func (p *OIDCProvider) Enabled() bool { return p != nil }

// RedirectURL is where the provider sends the browser back to; the settings
// page shows it so an operator can paste it into the provider's console.
func (p *OIDCProvider) RedirectURL() string {
	if p == nil {
		return ""
	}
	return p.oauth.RedirectURL
}

// AllowSignup reports whether a successful login may create an account.
func (p *OIDCProvider) AllowSignup() bool { return p != nil && p.cfg.AllowSignup }

// Start begins a login: it mints a single-use state and nonce, remembers them,
// and returns the URL to redirect the browser to.
func (p *OIDCProvider) Start() (authURL, state string, err error) {
	if p == nil {
		return "", "", errors.New("single sign-on is not configured on this instance")
	}
	state = store.NewSecret(secretBytes)
	nonce := store.NewSecret(secretBytes)
	if err := p.states.put(state, nonce); err != nil {
		return "", "", err
	}
	return p.AuthCodeURL(state, nonce), state, nil
}

// AuthCodeURL renders the provider's authorisation URL for a state and nonce.
func (p *OIDCProvider) AuthCodeURL(state, nonce string) string {
	if p == nil {
		return ""
	}
	return p.oauth.AuthCodeURL(state, oidc.Nonce(nonce))
}

// Complete finishes a login begun by Start: it spends the state, exchanges the
// code and returns the claims. A state that is unknown, already spent or too
// old is refused -- that is what makes the flow single-use. It proves the
// handshake began on this controller, not that it began in this browser; the
// API layer adds that half by binding the state to a cookie set at Start.
func (p *OIDCProvider) Complete(ctx context.Context, state, code string) (*Claims, error) {
	if p == nil {
		return nil, errors.New("single sign-on is not configured on this instance")
	}
	nonce, ok := p.states.take(state)
	if !ok {
		return nil, errors.New("this sign-in link has already been used or has expired; start again from the login page")
	}
	return p.Exchange(ctx, code, nonce)
}

// Exchange swaps an authorisation code for an ID token, verifies it, and maps
// its claims onto a Zoomies identity. The nonce must be the one that was sent
// with the authorisation request.
func (p *OIDCProvider) Exchange(ctx context.Context, code, nonce string) (*Claims, error) {
	if p == nil {
		return nil, errors.New("single sign-on is not configured on this instance")
	}
	tok, err := p.oauth.Exchange(ctx, code)
	if err != nil {
		return nil, fmt.Errorf("the identity provider rejected the sign-in: %w", err)
	}
	raw, ok := tok.Extra("id_token").(string)
	if !ok || raw == "" {
		return nil, errors.New("the identity provider returned no ID token; check that Zoomies is asking for the openid scope and that the application is an OpenID Connect one")
	}
	idToken, err := p.verifier.Verify(ctx, raw)
	if err != nil {
		return nil, fmt.Errorf("the ID token did not verify: %w", err)
	}
	// A constant-time comparison is not strictly necessary for a value the
	// client already knows, but it costs nothing and keeps the habit.
	if subtle.ConstantTimeCompare([]byte(idToken.Nonce), []byte(nonce)) != 1 {
		return nil, errors.New("the ID token's nonce does not match the sign-in that started it; start again from the login page")
	}

	var raws map[string]any
	if err := idToken.Claims(&raws); err != nil {
		return nil, fmt.Errorf("could not read the ID token's claims: %w", err)
	}
	return p.claimsFrom(idToken.Subject, raws)
}

// claimsFrom maps a raw claim set onto Claims. It is separate from Exchange so
// the mapping can be tested without an identity provider.
func (p *OIDCProvider) claimsFrom(subject string, raw map[string]any) (*Claims, error) {
	usernameClaim := p.cfg.UsernameClaim
	if usernameClaim == "" {
		usernameClaim = "preferred_username"
	}
	groupsClaim := p.cfg.GroupsClaim
	if groupsClaim == "" {
		groupsClaim = "groups"
	}

	c := &Claims{
		Subject:  subject,
		Username: claimString(raw, usernameClaim),
		Email:    claimString(raw, "email"),
		Name:     claimString(raw, "name"),
		Groups:   claimStrings(raw, groupsClaim),
	}
	if c.Username == "" && claimBool(raw, "email_verified") {
		// Providers that do not send preferred_username almost always send an
		// email; falling back beats failing a login the operator cannot debug.
		// Only a verified one, though: an address the provider has not checked
		// is a value the person typed, and Zoomies matches accounts by username.
		c.Username = c.Email
	}
	if c.Username == "" {
		c.Username = subject
	}
	if c.Subject == "" {
		return nil, fmt.Errorf("the identity provider sent no subject claim, so this login cannot be linked to an account")
	}
	c.Role = p.RoleFor(c.Groups)
	return c, nil
}

// RoleFor maps the identity provider's groups onto a Zoomies role. The higher
// role wins wherever somebody is in two mapped groups, and anyone in no mapped
// group is a viewer -- so misconfiguring the group names produces read-only
// access rather than accidental admins.
func (p *OIDCProvider) RoleFor(groups []string) store.Role {
	if p == nil {
		return store.RoleViewer
	}
	for _, g := range groups {
		if containsFold(p.cfg.PlatformGroups, g) {
			return store.RolePlatform
		}
	}
	for _, g := range groups {
		if containsFold(p.cfg.AdminGroups, g) {
			return store.RoleAdmin
		}
	}
	for _, g := range groups {
		if containsFold(p.cfg.OperatorGroups, g) {
			return store.RoleOperator
		}
	}
	return store.RoleViewer
}

// mapsRoles reports whether the operator configured any group mapping at all.
// When they did not, EnsureUser leaves an existing account's role alone rather
// than demoting everyone to viewer on their next login.
func (p *OIDCProvider) mapsRoles() bool {
	return p != nil && (len(p.cfg.PlatformGroups) > 0 || len(p.cfg.AdminGroups) > 0 || len(p.cfg.OperatorGroups) > 0)
}

// EnsureUser resolves a set of verified claims to a local account.
//
// It links by subject first, because that is the only identifier a provider
// promises not to reuse. Failing that it adopts an existing account with the
// same username, but only one made for single sign-on -- one with no password
// -- unless oidc.link_by_username says otherwise: with a provider whose users
// can influence their own username claim, adopting any account by name would
// let a login as "admin" inherit the local admin's role. Only then, if
// allowSignup is on, does it create one.
func (p *OIDCProvider) EnsureUser(ctx context.Context, st *store.Store, claims *Claims, allowSignup bool) (*store.User, error) {
	if claims == nil || claims.Subject == "" {
		return nil, errors.New("no verified claims to sign in with")
	}
	username, err := normalizeUsername(claims.Username)
	if err != nil {
		return nil, fmt.Errorf("the identity provider's username claim is not usable: %w", err)
	}

	u, err := st.GetUserByOIDCSubject(ctx, claims.Subject)
	switch {
	case err == nil:
		return p.sync(ctx, st, u, claims, username)
	case !errors.Is(err, store.ErrNotFound):
		return nil, fmt.Errorf("looking up the linked account: %w", err)
	}

	u, err = st.GetUserByUsername(ctx, username)
	switch {
	case err == nil:
		if u.OIDCSubject != "" && u.OIDCSubject != claims.Subject {
			return nil, fmt.Errorf("the account %q is already linked to a different single sign-on identity; an administrator must unlink or rename it", username)
		}
		// Adopting an account by username is how an administrator pre-creates
		// somebody's account and how an instance moves from local passwords to
		// SSO. It is also how a matching username at the identity provider
		// could claim a local account -- so an account that has a password of
		// its own is only adopted when the operator has asked for exactly that.
		if u.PasswordHash != "" && !p.cfg.LinkByUsername {
			return nil, fmt.Errorf("an account named %q already exists and signs in with a password, so this single sign-on identity was not linked to it; "+
				"an administrator can set oidc.link_by_username for the migration, or create an SSO account under another name", username)
		}
		u.OIDCSubject = claims.Subject
		return p.sync(ctx, st, u, claims, username)
	case !errors.Is(err, store.ErrNotFound):
		return nil, fmt.Errorf("looking up the account: %w", err)
	}

	if !allowSignup {
		return nil, fmt.Errorf("no Zoomies account exists for %q; an administrator must create it first, or turn on oidc.allow_signup to create accounts on first sign-in", username)
	}
	role := claims.Role
	if !role.Valid() {
		role = store.RoleViewer
	}
	u = &store.User{
		Username:    username,
		Email:       claims.Email,
		DisplayName: claims.Name,
		Role:        role,
		OIDCSubject: claims.Subject,
	}
	if err := st.CreateUser(ctx, u); err != nil {
		return nil, fmt.Errorf("creating the account for %q: %w", username, err)
	}
	return u, nil
}

// sync updates a linked account from the provider's claims. The identity
// provider is authoritative for the profile, and for the role too when group
// mappings are configured.
func (p *OIDCProvider) sync(ctx context.Context, st *store.Store, u *store.User, claims *Claims, username string) (*store.User, error) {
	if u.Disabled {
		return nil, ErrAccountDisabled
	}
	before := *u
	u.OIDCSubject = claims.Subject
	u.Username = username
	if claims.Email != "" {
		u.Email = claims.Email
	}
	if claims.Name != "" {
		u.DisplayName = claims.Name
	}
	// The role follows the identity provider only when the operator actually
	// mapped groups to roles, and only when the mapping produced a real role;
	// otherwise an existing account keeps the role an administrator gave it.
	if p.mapsRoles() && claims.Role.Valid() {
		u.Role = claims.Role
	}
	if before == *u {
		return u, nil
	}
	if err := st.UpdateUser(ctx, u); err != nil {
		return nil, fmt.Errorf("updating the account for %q: %w", username, err)
	}
	return u, nil
}

// ---------------------------------------------------------------------------
// State and nonce cache
// ---------------------------------------------------------------------------

// stateCache remembers the state and nonce of logins that are in flight.
//
// It is deliberately in memory: a state lives for one redirect, and losing the
// lot on restart means everyone mid-login clicks the button again. Entries are
// single-use, so a replayed callback is refused.
type stateCache struct {
	mu      sync.Mutex
	ttl     time.Duration
	now     func() time.Time
	entries map[string]stateEntry
}

type stateEntry struct {
	nonce   string
	expires time.Time
}

func newStateCache(ttl time.Duration, clock func() time.Time) *stateCache {
	if clock == nil {
		clock = time.Now
	}
	return &stateCache{ttl: ttl, now: clock, entries: map[string]stateEntry{}}
}

func (c *stateCache) put(state, nonce string) error {
	now := c.now()
	c.mu.Lock()
	defer c.mu.Unlock()
	for k, e := range c.entries {
		if now.After(e.expires) {
			delete(c.entries, k)
		}
	}
	// The sweep above has already dropped every entry a legitimate caller was
	// going to lose. If the cache is still full, the ones left are all in flight
	// and refusing this one is what keeps a stream of unauthenticated Starts
	// from growing the map without bound.
	if len(c.entries) >= maxPendingStates {
		return ErrTooManyPendingSignIns
	}
	c.entries[state] = stateEntry{nonce: nonce, expires: now.Add(c.ttl)}
	return nil
}

// take returns the nonce for a state and forgets it, so a state can be spent
// exactly once.
func (c *stateCache) take(state string) (string, bool) {
	if state == "" {
		return "", false
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.entries[state]
	if !ok {
		return "", false
	}
	delete(c.entries, state)
	if c.now().After(e.expires) {
		return "", false
	}
	return e.nonce, true
}

// ---------------------------------------------------------------------------
// Claim helpers
// ---------------------------------------------------------------------------

// claimBool reads a boolean claim. Some providers send it as the string "true"
// rather than a JSON boolean, which is worth tolerating: the alternative is a
// login that fails for a reason nobody can see.
func claimBool(raw map[string]any, key string) bool {
	switch v := raw[key].(type) {
	case bool:
		return v
	case string:
		return strings.EqualFold(strings.TrimSpace(v), "true")
	}
	return false
}

func claimString(raw map[string]any, key string) string {
	if key == "" {
		return ""
	}
	switch v := raw[key].(type) {
	case string:
		return strings.TrimSpace(v)
	case fmt.Stringer:
		return strings.TrimSpace(v.String())
	}
	return ""
}

// claimStrings reads a claim that may be a list or, with some providers, a
// single string.
func claimStrings(raw map[string]any, key string) []string {
	switch v := raw[key].(type) {
	case []string:
		return v
	case string:
		if v == "" {
			return nil
		}
		return []string{v}
	case []any:
		out := make([]string, 0, len(v))
		for _, item := range v {
			if s, ok := item.(string); ok && s != "" {
				out = append(out, s)
			}
		}
		return out
	}
	return nil
}

func containsFold(list []string, want string) bool {
	for _, s := range list {
		if strings.EqualFold(strings.TrimSpace(s), strings.TrimSpace(want)) {
			return true
		}
	}
	return false
}

package auth

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// discovery serves just enough of an OpenID provider for oidc.NewProvider to
// finish its discovery request, so the constructor can be tested without a real
// identity provider or any network access.
func discovery(t *testing.T) *httptest.Server {
	t.Helper()
	mux := http.NewServeMux()
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                srv.URL,
			"authorization_endpoint":                srv.URL + "/authorize",
			"token_endpoint":                        srv.URL + "/token",
			"jwks_uri":                              srv.URL + "/jwks",
			"id_token_signing_alg_values_supported": []string{"RS256"},
		})
	})
	return srv
}

func TestNewOIDCDisabledIsNotAnError(t *testing.T) {
	p, err := NewOIDC(t.Context(), config.Default().OIDC, "https://zoomies.example.com")
	if p != nil || err != nil {
		t.Fatalf("NewOIDC with SSO off = %v, %v; want nil, nil", p, err)
	}
	// A nil provider must stay usable, so callers need no branch.
	if p.Enabled() || p.AllowSignup() || p.RedirectURL() != "" {
		t.Error("a nil provider claims to be configured")
	}
	if p.RoleFor([]string{"admins"}) != store.RoleViewer {
		t.Error("a nil provider should map every group to viewer")
	}
	if _, _, err := p.Start(); err == nil {
		t.Error("Start on a nil provider should say SSO is not configured")
	}
}

func TestNewOIDCRequiresItsSettings(t *testing.T) {
	cfg := config.Default().OIDC
	cfg.Enabled = true
	if _, err := NewOIDC(t.Context(), cfg, "https://zoomies.example.com"); err == nil ||
		!strings.Contains(err.Error(), "oidc.issuer") {
		t.Errorf("missing issuer = %v; want an error naming oidc.issuer", err)
	}

	cfg.Issuer = "https://login.example.com"
	if _, err := NewOIDC(t.Context(), cfg, "https://zoomies.example.com"); err == nil ||
		!strings.Contains(err.Error(), "oidc.client_id") {
		t.Errorf("missing client credentials = %v; want an error naming oidc.client_id", err)
	}

	cfg.ClientID, cfg.ClientSecret = "id", "shh"
	if _, err := NewOIDC(t.Context(), cfg, ""); err == nil ||
		!strings.Contains(err.Error(), "server.external_url") {
		t.Errorf("no way to build a redirect URL = %v; want an error naming external_url", err)
	}
}

func TestNewOIDCDerivesTheRedirectURL(t *testing.T) {
	srv := discovery(t)
	cfg := config.Default().OIDC
	cfg.Enabled, cfg.Issuer, cfg.ClientID, cfg.ClientSecret = true, srv.URL, "zoomies", "shh"

	p, err := NewOIDC(t.Context(), cfg, "https://zoomies.example.com/")
	if err != nil {
		t.Fatalf("NewOIDC: %v", err)
	}
	if want := "https://zoomies.example.com" + OIDCCallbackPath; p.RedirectURL() != want {
		t.Errorf("redirect URL = %q; want %q", p.RedirectURL(), want)
	}
	if !containsFold(p.oauth.Scopes, "openid") {
		t.Errorf("scopes = %v; want the openid scope to be present", p.oauth.Scopes)
	}

	url, state, err := p.Start()
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	for _, want := range []string{srv.URL + "/authorize", "client_id=zoomies", "state=" + state, "nonce="} {
		if !strings.Contains(url, want) {
			t.Errorf("authorisation URL %q is missing %q", url, want)
		}
	}

	// The state is single-use: a replayed callback is refused before any code
	// is exchanged.
	if _, err := p.Complete(t.Context(), "not-a-state", "code"); err == nil {
		t.Error("an unknown state was accepted")
	}
	if _, ok := p.states.take(state); !ok {
		t.Fatal("the state Start returned was not remembered")
	}
	if _, err := p.Complete(t.Context(), state, "code"); err == nil {
		t.Error("a spent state was accepted a second time")
	}
}

func TestStateCacheIsSingleUseAndExpires(t *testing.T) {
	c := newClock()
	cache := newStateCache(10*time.Minute, c.Now)

	cache.put("state-1", "nonce-1")
	if nonce, ok := cache.take("state-1"); !ok || nonce != "nonce-1" {
		t.Fatalf("take = %q, %v; want nonce-1, true", nonce, ok)
	}
	if _, ok := cache.take("state-1"); ok {
		t.Error("a state was spendable twice")
	}
	if _, ok := cache.take(""); ok {
		t.Error("an empty state was accepted")
	}

	cache.put("state-2", "nonce-2")
	c.Advance(11 * time.Minute)
	if _, ok := cache.take("state-2"); ok {
		t.Error("an expired state was accepted")
	}
	// Putting a new entry sweeps the expired ones.
	cache.put("state-3", "nonce-3")
	if len(cache.entries) != 1 {
		t.Errorf("cache holds %d entries; want only the live one", len(cache.entries))
	}
}

// A stream of unauthenticated calls to /auth/oidc/start would otherwise grow
// the state cache without bound; refusing new entries at the cap is what keeps
// one anonymous client from filling the process's memory with pending states
// that will never finish.
func TestStateCacheRefusesEntriesAtItsCap(t *testing.T) {
	c := newClock()
	cache := newStateCache(10*time.Minute, c.Now)
	for i := 0; i < maxPendingStates; i++ {
		if err := cache.put(fmt.Sprintf("state-%d", i), "nonce"); err != nil {
			t.Fatalf("put %d: %v", i, err)
		}
	}
	if err := cache.put("one-too-many", "nonce"); !errors.Is(err, ErrTooManyPendingSignIns) {
		t.Fatalf("put over the cap = %v; want ErrTooManyPendingSignIns", err)
	}
	// A completed flow frees the slot, so the next legitimate signin succeeds.
	if _, ok := cache.take("state-0"); !ok {
		t.Fatal("could not take a spent state back out")
	}
	if err := cache.put("after-take", "nonce"); err != nil {
		t.Fatalf("put after take: %v", err)
	}
}

func TestRoleForMapsGroups(t *testing.T) {
	p := &OIDCProvider{cfg: config.OIDC{
		PlatformGroups: []string{"Infra-Platform"},
		AdminGroups:    []string{"Platform-Admins"},
		OperatorGroups: []string{"ci-operators"},
	}}
	cases := []struct {
		groups []string
		want   store.Role
	}{
		{nil, store.RoleViewer},
		{[]string{"everyone"}, store.RoleViewer},
		{[]string{"ci-operators"}, store.RoleOperator},
		{[]string{"platform-admins"}, store.RoleAdmin},                 // case-insensitive
		{[]string{"ci-operators", "Platform-Admins"}, store.RoleAdmin}, // admin wins
		{[]string{"infra-platform"}, store.RolePlatform},               // case-insensitive
		// The higher role wins wherever somebody is in two mapped
		// groups. Checking admin first would hand whoever runs the
		// process the lesser of the two, and the mapping order is
		// configuration nobody should have to reason about.
		{[]string{"Platform-Admins", "Infra-Platform"}, store.RolePlatform},
		{[]string{"ci-operators", "Infra-Platform"}, store.RolePlatform},
	}
	for _, tc := range cases {
		if got := p.RoleFor(tc.groups); got != tc.want {
			t.Errorf("RoleFor(%v) = %q; want %q", tc.groups, got, tc.want)
		}
	}
}

func TestClaimsFrom(t *testing.T) {
	p := &OIDCProvider{cfg: config.OIDC{
		UsernameClaim: "preferred_username",
		GroupsClaim:   "groups",
		AdminGroups:   []string{"admins"},
	}}

	c, err := p.claimsFrom("sub-1", map[string]any{
		"preferred_username": "alice",
		"email":              "alice@example.com",
		"name":               "Alice Example",
		"groups":             []any{"admins", "everyone"},
	})
	if err != nil {
		t.Fatalf("claimsFrom: %v", err)
	}
	if c.Username != "alice" || c.Email != "alice@example.com" || c.Name != "Alice Example" {
		t.Errorf("claims = %+v", c)
	}
	if c.Role != store.RoleAdmin {
		t.Errorf("role = %q; want admin", c.Role)
	}

	// Providers that send no preferred_username fall back to a *verified* email
	// rather than failing a login nobody can debug.
	c, err = p.claimsFrom("sub-2", map[string]any{
		"email": "bob@example.com", "email_verified": true, "groups": "admins",
	})
	if err != nil {
		t.Fatalf("claimsFrom: %v", err)
	}
	if c.Username != "bob@example.com" {
		t.Errorf("username = %q; want the verified email as a fallback", c.Username)
	}
	if c.Role != store.RoleAdmin {
		t.Errorf("a groups claim sent as a single string was ignored: %+v", c)
	}

	// An unverified address is a value the person typed, and accounts are
	// matched by username -- so it must not become one. The subject does.
	c, err = p.claimsFrom("sub-3", map[string]any{"email": "root@example.com"})
	if err != nil {
		t.Fatalf("claimsFrom: %v", err)
	}
	if c.Username != "sub-3" {
		t.Errorf("username = %q; an unverified email must not be used as the username", c.Username)
	}
	// Providers that render the flag as a string still count as verified.
	c, err = p.claimsFrom("sub-4", map[string]any{"email": "carol@example.com", "email_verified": "true"})
	if err != nil {
		t.Fatalf("claimsFrom: %v", err)
	}
	if c.Username != "carol@example.com" {
		t.Errorf("username = %q; email_verified sent as a string should still count", c.Username)
	}

	if _, err := p.claimsFrom("", map[string]any{"email": "x@example.com"}); err == nil {
		t.Error("claims with no subject were accepted; there would be nothing to link the account by")
	}
}

func TestEnsureUser(t *testing.T) {
	p := &OIDCProvider{cfg: config.OIDC{AdminGroups: []string{"admins"}}}
	ctx := t.Context()

	newStore := func(t *testing.T) *store.Store {
		t.Helper()
		c := newClock()
		st, err := store.Open(ctx, store.Options{Path: ":memory:", Now: c.Now})
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { st.Close() })
		return st
	}

	t.Run("links by subject", func(t *testing.T) {
		st := newStore(t)
		want := addUser(t, st, "alice", store.RoleViewer, func(u *store.User) { u.OIDCSubject = "sub-1" })

		got, err := p.EnsureUser(ctx, st, &Claims{
			Subject: "sub-1", Username: "renamed-at-the-idp", Role: store.RoleAdmin,
		}, false)
		if err != nil {
			t.Fatalf("EnsureUser: %v", err)
		}
		if got.ID != want.ID {
			t.Fatalf("user = %s; want the account linked by subject (%s)", got.ID, want.ID)
		}
		if got.Role != store.RoleAdmin {
			t.Errorf("role = %q; want the identity provider's groups to be authoritative", got.Role)
		}
	})

	t.Run("adopts an existing username only when the account was made for SSO", func(t *testing.T) {
		st := newStore(t)
		want := addUser(t, st, "alice", store.RoleOperator, func(u *store.User) { u.PasswordHash = "" })

		got, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-9", Username: "Alice", Role: store.RoleViewer}, false)
		if err != nil {
			t.Fatalf("EnsureUser: %v", err)
		}
		if got.ID != want.ID || got.OIDCSubject != "sub-9" {
			t.Fatalf("user = %+v; want the existing account linked to sub-9", got)
		}
		stored, err := st.GetUser(ctx, want.ID)
		if err != nil {
			t.Fatal(err)
		}
		if stored.OIDCSubject != "sub-9" {
			t.Error("the link was not persisted")
		}
	})

	// With a provider whose users can influence their own username claim, a
	// sign-in as "admin" used to inherit the local admin's account and role.
	t.Run("refuses to take over a password account by name unless told to", func(t *testing.T) {
		st := newStore(t)
		local := addUser(t, st, "admin", store.RoleAdmin, nil)

		_, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-10", Username: "admin"}, true)
		if err == nil || !strings.Contains(err.Error(), "signs in with a password") || !strings.Contains(err.Error(), "link_by_username") {
			t.Fatalf("EnsureUser = %v; want a refusal that names the setting", err)
		}
		stored, _ := st.GetUser(ctx, local.ID)
		if stored.OIDCSubject != "" {
			t.Fatal("the password account was linked anyway")
		}

		linking := &OIDCProvider{cfg: config.OIDC{LinkByUsername: true}}
		got, err := linking.EnsureUser(ctx, st, &Claims{Subject: "sub-10", Username: "admin"}, false)
		if err != nil {
			t.Fatalf("EnsureUser with link_by_username: %v", err)
		}
		if got.ID != local.ID || got.OIDCSubject != "sub-10" || got.PasswordHash == "" {
			t.Fatalf("user = %+v; want the local account linked, password kept", got)
		}
	})

	t.Run("refuses a second identity for one username", func(t *testing.T) {
		st := newStore(t)
		addUser(t, st, "alice", store.RoleViewer, func(u *store.User) { u.OIDCSubject = "sub-1" })

		_, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-2", Username: "alice"}, true)
		if err == nil || !strings.Contains(err.Error(), "already linked") {
			t.Fatalf("EnsureUser = %v; want a refusal naming the existing link", err)
		}
	})

	t.Run("refuses to create when signup is off", func(t *testing.T) {
		st := newStore(t)
		_, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-3", Username: "carol"}, false)
		if err == nil {
			t.Fatal("an unknown user was provisioned with signup off")
		}
		if !strings.Contains(err.Error(), "create it first") || !strings.Contains(err.Error(), "allow_signup") {
			t.Errorf("error = %q; want it to tell the operator what to do", err)
		}
	})

	t.Run("creates when signup is on", func(t *testing.T) {
		st := newStore(t)
		u, err := p.EnsureUser(ctx, st, &Claims{
			Subject: "sub-4", Username: "dave", Email: "dave@example.com", Role: store.RoleOperator,
		}, true)
		if err != nil {
			t.Fatalf("EnsureUser: %v", err)
		}
		if u.PasswordHash != "" {
			t.Error("a provisioned account was given a password hash")
		}
		if u.Role != store.RoleOperator || u.Email != "dave@example.com" {
			t.Errorf("provisioned user = %+v", u)
		}
		// A second login finds the same account rather than making another.
		again, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-4", Username: "dave"}, true)
		if err != nil || again.ID != u.ID {
			t.Fatalf("second sign-in = %v, %v; want the same account", again, err)
		}
	})

	t.Run("refuses a disabled account", func(t *testing.T) {
		st := newStore(t)
		addUser(t, st, "eve", store.RoleViewer, func(u *store.User) {
			u.OIDCSubject, u.Disabled = "sub-5", true
		})
		if _, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-5", Username: "eve"}, true); !errors.Is(err, ErrAccountDisabled) {
			t.Fatalf("EnsureUser on a disabled account = %v; want ErrAccountDisabled", err)
		}
	})

	t.Run("leaves the role alone when no groups are mapped", func(t *testing.T) {
		st := newStore(t)
		unmapped := &OIDCProvider{cfg: config.OIDC{}}
		addUser(t, st, "frank", store.RoleAdmin, func(u *store.User) { u.OIDCSubject = "sub-6" })

		got, err := unmapped.EnsureUser(ctx, st, &Claims{
			Subject: "sub-6", Username: "frank", Role: store.RoleViewer,
		}, false)
		if err != nil {
			t.Fatalf("EnsureUser: %v", err)
		}
		if got.Role != store.RoleAdmin {
			t.Errorf("role = %q; an instance with no group mapping must not demote its admins on login", got.Role)
		}
	})

	t.Run("rejects an unusable username", func(t *testing.T) {
		st := newStore(t)
		if _, err := p.EnsureUser(ctx, st, &Claims{Subject: "sub-7", Username: "no spaces please"}, true); err == nil {
			t.Fatal("a username with spaces was accepted")
		}
		if _, err := p.EnsureUser(ctx, st, nil, true); err == nil {
			t.Fatal("nil claims were accepted")
		}
	})
}

// A provider that cannot be reached is worth trying again; a configuration
// that is missing a setting is not, because nothing will change until
// somebody changes it. The API's retry loop tells the two apart by this.
func TestAnUnreachableProviderIsADiscoveryFailureAndAMissingSettingIsNot(t *testing.T) {
	down := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "down for maintenance", http.StatusServiceUnavailable)
	}))
	t.Cleanup(down.Close)
	cfg := config.Default().OIDC
	cfg.Enabled, cfg.Issuer, cfg.ClientID, cfg.ClientSecret = true, down.URL, "zoomies", "shh"

	_, err := NewOIDC(t.Context(), cfg, "https://zoomies.example.com")
	if !errors.Is(err, ErrOIDCDiscovery) {
		t.Fatalf("an unreachable provider = %v; want ErrOIDCDiscovery", err)
	}
	if !strings.Contains(err.Error(), "oidc.issuer") {
		t.Errorf("the message must still say what to check: %v", err)
	}

	cfg.ClientSecret = ""
	if _, err := NewOIDC(t.Context(), cfg, "https://zoomies.example.com"); err == nil || errors.Is(err, ErrOIDCDiscovery) {
		t.Errorf("a missing client secret = %v; want a configuration error, not a discovery failure", err)
	}
}

package auth

import (
	"sync"
	"time"
)

// RateLimiter is a sliding-window counter keyed by client address.
//
// It keeps the timestamps of the attempts still inside the window rather than a
// per-minute bucket, so an attacker cannot get 2N attempts by straddling a
// bucket boundary.
//
// It is per-process and in-memory, which is fine: Zoomies is a single
// controller, and pushing every login attempt through SQLite would put a write
// -- serialised behind the single writer -- in front of the login path for no
// security gain. If this ever becomes more than one controller, this type is
// the piece that has to move to shared state.
type RateLimiter struct {
	mu     sync.Mutex
	limit  int
	window time.Duration
	now    func() time.Time
	hits   map[string][]time.Time
	// swept is when stale keys were last discarded, so a stream of one-shot
	// addresses cannot grow the map without bound.
	swept time.Time
}

// NewRateLimiter returns a limiter allowing limit attempts per key per window.
// A limit of zero or less disables limiting entirely, which is what setting
// security.rate_limit_logins to 0 means. clock may be nil for time.Now.
func NewRateLimiter(limit int, window time.Duration, clock func() time.Time) *RateLimiter {
	if clock == nil {
		clock = time.Now
	}
	if window <= 0 {
		window = time.Minute
	}
	return &RateLimiter{
		limit:  limit,
		window: window,
		now:    clock,
		hits:   map[string][]time.Time{},
	}
}

// Allow records an attempt for key and reports whether it is within the limit.
// A refused attempt is not recorded, so a client that keeps hammering does not
// extend its own lockout indefinitely -- it recovers one window after its last
// accepted attempt.
func (l *RateLimiter) Allow(key string) bool {
	if l == nil || l.limit <= 0 {
		return true
	}
	return l.AllowAt(key, l.now())
}

// AllowAt is Allow at an explicit time, which is how the tests move the window
// without sleeping.
func (l *RateLimiter) AllowAt(key string, now time.Time) bool {
	if l == nil || l.limit <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.sweep(now)

	hits := within(l.hits[key], now.Add(-l.window))
	if len(hits) >= l.limit {
		l.hits[key] = hits
		return false
	}
	l.hits[key] = append(hits, now)
	return true
}

// RetryAfter returns how long until key would be allowed again, or zero if it
// is allowed now. Handlers put it in a Retry-After header.
func (l *RateLimiter) RetryAfter(key string) time.Duration {
	if l == nil || l.limit <= 0 {
		return 0
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	hits := within(l.hits[key], now.Add(-l.window))
	l.hits[key] = hits
	if len(hits) < l.limit {
		return 0
	}
	// The oldest attempt in the window is the one that has to age out.
	if d := hits[0].Add(l.window).Sub(now); d > 0 {
		return d
	}
	return 0
}

// Reset forgets a key's attempts. Login calls it after a correct password, so
// one person's typos do not lock out the next person behind the same NAT.
func (l *RateLimiter) Reset(key string) {
	if l == nil {
		return
	}
	l.mu.Lock()
	delete(l.hits, key)
	l.mu.Unlock()
}

// Keys returns how many distinct keys are being tracked. It exists for the
// memory-growth test and for a debug endpoint.
func (l *RateLimiter) Keys() int {
	if l == nil {
		return 0
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	return len(l.hits)
}

// sweep drops keys with nothing left inside the window. It runs at most once
// per window, so the common path stays O(1) in the number of tracked keys.
func (l *RateLimiter) sweep(now time.Time) {
	if now.Sub(l.swept) < l.window {
		return
	}
	l.swept = now
	cut := now.Add(-l.window)
	for k, hits := range l.hits {
		if remaining := within(hits, cut); len(remaining) == 0 {
			delete(l.hits, k)
		} else {
			l.hits[k] = remaining
		}
	}
}

// within returns the timestamps at or after cut. The slice is ordered by
// construction, so this is a prefix drop rather than a filter.
func within(hits []time.Time, cut time.Time) []time.Time {
	for i, h := range hits {
		if h.After(cut) {
			return hits[i:]
		}
	}
	return nil
}

package auth

import (
	"testing"
	"time"
)

func TestRateLimiterAllowsThenBlocksThenRecovers(t *testing.T) {
	c := newClock()
	l := NewRateLimiter(3, time.Minute, c.Now)

	for i := range 3 {
		if !l.Allow("10.0.0.1") {
			t.Fatalf("attempt %d was refused; the limit is 3", i+1)
		}
	}
	if l.Allow("10.0.0.1") {
		t.Fatal("the fourth attempt inside the window was allowed")
	}
	if got := l.RetryAfter("10.0.0.1"); got != time.Minute {
		t.Errorf("RetryAfter = %v; want a full minute after three attempts at the same instant", got)
	}

	// Another address has its own budget.
	if !l.Allow("10.0.0.2") {
		t.Error("a different address was refused")
	}

	// The window slides rather than resetting on a boundary: after 61 seconds
	// the three attempts have aged out.
	c.Advance(61 * time.Second)
	for i := range 3 {
		if !l.Allow("10.0.0.1") {
			t.Fatalf("attempt %d after the window was refused", i+1)
		}
	}
	if l.Allow("10.0.0.1") {
		t.Error("the limit did not apply again after recovery")
	}
}

func TestRateLimiterSlidesRatherThanBuckets(t *testing.T) {
	c := newClock()
	l := NewRateLimiter(2, time.Minute, c.Now)

	if !l.Allow("ip") {
		t.Fatal("the first attempt was refused")
	}
	c.Advance(30 * time.Second)
	if !l.Allow("ip") {
		t.Fatal("the second attempt was refused")
	}
	if l.Allow("ip") {
		t.Fatal("a third attempt inside the window was allowed")
	}

	// 61 seconds after the first attempt, only that attempt has aged out, so
	// exactly one slot opens. A fixed per-minute bucket would have opened two.
	c.Advance(31 * time.Second)
	if !l.Allow("ip") {
		t.Error("the slot freed by the oldest attempt was not reused")
	}
	if l.Allow("ip") {
		t.Error("two slots opened; only one attempt had aged out")
	}
}

func TestRateLimiterRefusalDoesNotExtendTheLockout(t *testing.T) {
	c := newClock()
	l := NewRateLimiter(1, time.Minute, c.Now)

	if !l.Allow("ip") {
		t.Fatal("the first attempt was refused")
	}
	// Hammering while blocked must not keep pushing the window forward, or a
	// client with a retry loop could never recover.
	for range 5 {
		c.Advance(10 * time.Second)
		if l.Allow("ip") {
			t.Fatal("an attempt inside the window was allowed")
		}
	}
	c.Advance(11 * time.Second) // 61s since the accepted attempt
	if !l.Allow("ip") {
		t.Error("the client never recovered after its window elapsed")
	}
}

func TestRateLimiterZeroMeansUnlimited(t *testing.T) {
	l := NewRateLimiter(0, time.Minute, newClock().Now)
	for i := range 100 {
		if !l.Allow("ip") {
			t.Fatalf("attempt %d was refused by a disabled limiter", i+1)
		}
	}
	if got := l.RetryAfter("ip"); got != 0 {
		t.Errorf("RetryAfter on a disabled limiter = %v; want 0", got)
	}
	// A nil limiter is a disabled one, so callers need no branch.
	var nilLimiter *RateLimiter
	if !nilLimiter.Allow("ip") {
		t.Error("a nil limiter refused an attempt")
	}
	nilLimiter.Reset("ip")
}

func TestRateLimiterReset(t *testing.T) {
	c := newClock()
	l := NewRateLimiter(1, time.Minute, c.Now)
	if !l.Allow("ip") || l.Allow("ip") {
		t.Fatal("limiter did not block after one attempt")
	}
	l.Reset("ip")
	if !l.Allow("ip") {
		t.Error("Reset did not clear the address's attempts")
	}
}

func TestRateLimiterForgetsIdleKeys(t *testing.T) {
	c := newClock()
	l := NewRateLimiter(5, time.Minute, c.Now)
	for _, ip := range []string{"a", "b", "c"} {
		l.Allow(ip)
	}
	if got := l.Keys(); got != 3 {
		t.Fatalf("tracked keys = %d; want 3", got)
	}
	// A stream of one-shot addresses must not grow the map without bound.
	c.Advance(2 * time.Minute)
	l.Allow("d")
	if got := l.Keys(); got != 1 {
		t.Errorf("tracked keys after the sweep = %d; want only the live one", got)
	}
}

package auth

import (
	"fmt"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// Action names one thing the HTTP API lets an identity do.
//
// Every route in docs/api-surface.md maps onto exactly one action, and
// actionRoles below gives each action its minimum role. That table -- not a
// scattering of role checks in handlers -- is the authorisation policy, and a
// test walks the whole list, so a new endpoint cannot ship without somebody
// deciding who may call it.
//
// The string form is "<resource>.<verb>". The scope form an API token carries
// is "<resource>:<verb>", which Action.Scope renders.
type Action string

// Pool actions.
const (
	ActionPoolsRead   Action = "pools.read"
	ActionPoolsWrite  Action = "pools.write"
	ActionPoolsDelete Action = "pools.delete"
)

// Runner actions. Draining is separated from deleting because draining never
// interrupts a running job and deleting can.
const (
	ActionRunnersRead Action = "runners.read"
	// There is no runners.create: a runner is created by the scheduler, in
	// response to a queued job, and no route asks for one. A scope nothing
	// checks is a scope an operator can grant believing it does something.
	ActionRunnersDrain  Action = "runners.drain"
	ActionRunnersDelete Action = "runners.delete"
)

// Job actions. Cancellation is deliberately separate: GitHub cancels the
// whole workflow run, not only the job selected in Zoomies.
const (
	ActionProvisioningWrite Action = "provisioning.write"
	ActionJobsRead          Action = "jobs.read"
	ActionJobsCancel        Action = "jobs.cancel"
	ActionJobsRerun         Action = "jobs.rerun"
)
const ActionUsageRead Action = "usage.read"

// Host actions.
const (
	ActionHostsRead   Action = "hosts.read"
	ActionHostsWrite  Action = "hosts.write"
	ActionHostsCordon Action = "hosts.cordon"
	ActionHostsDelete Action = "hosts.delete"
)

// Installation actions. Verifying credentials is an operator action because it
// is a read-only probe; changing them is not.
const (
	ActionInstallationsRead   Action = "installations.read"
	ActionInstallationsWrite  Action = "installations.write"
	ActionInstallationsDelete Action = "installations.delete"
	ActionInstallationsVerify Action = "installations.verify"
	// ActionInstallationsExport takes an installation's whole history away,
	// and with a passphrase its private key too. It is admin, as changing the
	// key is, because the archive is the credential once it is sealed for
	// somewhere else.
	ActionInstallationsExport Action = "installations.export"
)

// Provider and machine actions. A provider's credential reaches a hypervisor,
// so configuring one is admin-class as an installation is; pausing is operator,
// because the person on call at three in the morning has to be able to press
// the kill switch without waiting for somebody with an admin account.
//
// Draining a machine is separated from deleting one for the reason runners are:
// a drain finishes the work that is on it, and a delete destroys a machine
// somebody is paying for.
const (
	ActionProvidersRead   Action = "providers.read"
	ActionProvidersWrite  Action = "providers.write"
	ActionProvidersDelete Action = "providers.delete"
	ActionProvidersPause  Action = "providers.pause"
	ActionMachinesRead    Action = "machines.read"
	ActionMachinesDrain   Action = "machines.drain"
	ActionMachinesDelete  Action = "machines.delete"
)

// Webhook actions cover the delivery log and the reachability test.
const (
	ActionWebhooksRead Action = "webhooks.read"
	ActionWebhooksTest Action = "webhooks.test"
)

// Audit actions.
const ActionAuditRead Action = "audit.read"

// Context is source data, not fleet metadata. These actions are only the
// coarse role/scope gate; ContextAccess also requires repository membership.
const (
	ActionContextRead      Action = "context.read"
	ActionContextConfigure Action = "context.configure"
	// ActionContextManage is only the coarse gate for installation owners. It
	// grants nothing by itself: every handler also checks that the caller owns
	// the installation (or holds context.configure).
	ActionContextManage Action = "context.manage"
)

// Migrations move a repository's workflows onto this fleet, which means
// opening pull requests in repositories Zoomies does not own. Reading a plan
// is an operator's job rather than a viewer's because it costs a burst of
// GitHub quota the scheduler shares; opening the pull requests is the same
// weight as changing a pool.
const (
	ActionMigrationsRead  Action = "migrations.read"
	ActionMigrationsWrite Action = "migrations.write"
)

// Account and credential actions.
const (
	ActionUsersRead   Action = "users.read"
	ActionUsersWrite  Action = "users.write"
	ActionTokensRead  Action = "tokens.read"
	ActionTokensWrite Action = "tokens.write"
	// ActionTokensOwn is creating, listing and revoking your own API tokens,
	// never at a role above your own. Everybody signed in has it: the CLI and
	// a script of one's own are ordinary work, and asking an administrator to
	// mint a credential for somebody else to hold was the worse habit.
	// tokens.read and tokens.write remain everybody's tokens.
	ActionTokensOwn  Action = "tokens.own"
	ActionJoinsRead  Action = "joins.read"
	ActionJoinsWrite Action = "joins.write"
	// The OAuth clients that may ask for an MCP connection, and every
	// person's connections. Administrator, as API tokens are: a client an
	// administrator creates is a way in that somebody else will use.
	ActionMCPClientsRead  Action = "mcp_clients.read"
	ActionMCPClientsWrite Action = "mcp_clients.write"
)

// Instance actions.
const (
	ActionSettingsRead  Action = "settings.read"
	ActionSettingsWrite Action = "settings.write"
	ActionMetricsRead   Action = "metrics.read"
	ActionEventsRead    Action = "events.read"
	ActionLogsRead      Action = "logs.read"
	ActionStatsRead     Action = "stats.read"
	// ActionDiagnosticsRead covers the support bundle, which is every other
	// read gathered into one document. It is admin rather than viewer because
	// the weakest role that covers all of it is the strongest role inside it:
	// the bundle carries the settings section, and settings.read is admin. A
	// viewer-readable bundle would hand out the one section this project has
	// always kept behind an admin.
	ActionDiagnosticsRead Action = "diagnostics.read"
	// ActionRecoveryWrite lifts the fence a restore sets. It is its own action
	// rather than settings.write because it is not a setting: it is a promise
	// that somebody has looked at a recovered fleet and decided it may act on
	// the world again, and it wants to be visible in an audit log under a name
	// that says so.
	ActionRecoveryWrite Action = "recovery.write"
	// The backups. Reading one is reading the whole database -- every
	// account's password hash and every sealed credential -- so backups.read
	// is admin like settings.read is, and a token scoped to it can download
	// the fleet. backups.restore is its own action rather than backups.write
	// because it is the one that replaces the fleet: a token that may take
	// copies should not be one that may put one back.
	ActionBackupsRead    Action = "backups.read"
	ActionBackupsWrite   Action = "backups.write"
	ActionBackupsRestore Action = "backups.restore"
)

// actionRoles is the authorisation policy in one table.
//
// The rule behind it, from docs/security.md: a viewer reads everything except
// secret values; an operator additionally acts on the fleet and manages pools;
// an admin additionally manages users, tokens, installations, join tokens and
// settings. Deleting a host is an admin action rather than an operator one
// because it removes a machine's whole history, not just a runner.
var actionRoles = map[Action]store.Role{
	ActionContextRead:      store.RoleViewer,
	ActionContextConfigure: store.RoleAdmin,
	ActionContextManage:    store.RoleViewer,

	ActionPoolsRead:   store.RoleViewer,
	ActionPoolsWrite:  store.RoleOperator,
	ActionPoolsDelete: store.RoleOperator,

	ActionRunnersRead:   store.RoleViewer,
	ActionRunnersDrain:  store.RoleOperator,
	ActionRunnersDelete: store.RoleOperator,

	ActionProvisioningWrite: store.RoleOperator,
	ActionJobsRead:          store.RoleViewer,
	ActionJobsCancel:        store.RoleOperator,
	// Operator rather than viewer: a re-run spends the organisation's GitHub
	// minutes and can have whatever side effects the workflow has, which is
	// the same bar cancelling one clears.
	ActionJobsRerun: store.RoleOperator,
	ActionUsageRead: store.RoleViewer,

	ActionHostsRead:   store.RoleViewer,
	ActionHostsWrite:  store.RoleOperator,
	ActionHostsCordon: store.RoleOperator,
	ActionHostsDelete: store.RoleAdmin,

	ActionInstallationsRead:   store.RoleViewer,
	ActionInstallationsWrite:  store.RoleAdmin,
	ActionInstallationsDelete: store.RoleAdmin,
	ActionInstallationsVerify: store.RoleOperator,
	ActionInstallationsExport: store.RoleAdmin,

	ActionWebhooksRead: store.RoleViewer,
	ActionWebhooksTest: store.RoleOperator,

	ActionProvidersRead:   store.RoleViewer,
	ActionProvidersWrite:  store.RoleAdmin,
	ActionProvidersDelete: store.RoleAdmin,
	ActionProvidersPause:  store.RoleOperator,
	ActionMachinesRead:    store.RoleViewer,
	ActionMachinesDrain:   store.RoleOperator,
	ActionMachinesDelete:  store.RoleAdmin,

	ActionAuditRead: store.RoleViewer,

	ActionMigrationsRead:  store.RoleOperator,
	ActionMigrationsWrite: store.RoleOperator,

	ActionUsersRead:   store.RoleAdmin,
	ActionUsersWrite:  store.RoleAdmin,
	ActionTokensRead:  store.RoleAdmin,
	ActionTokensWrite: store.RoleAdmin,
	ActionTokensOwn:   store.RoleViewer,
	ActionJoinsRead:   store.RoleAdmin,
	ActionJoinsWrite:  store.RoleAdmin,

	ActionMCPClientsRead:  store.RoleAdmin,
	ActionMCPClientsWrite: store.RoleAdmin,

	ActionSettingsRead:  store.RoleAdmin,
	ActionSettingsWrite: store.RoleAdmin,
	ActionMetricsRead:   store.RoleViewer,
	ActionEventsRead:    store.RoleViewer,
	ActionLogsRead:      store.RoleViewer,
	ActionStatsRead:     store.RoleViewer,

	ActionDiagnosticsRead: store.RoleAdmin,
	// The fence and the backups belong to whoever runs the process, not to
	// whoever runs the fleet. A backup is the whole database -- every
	// account's password hash and every sealed credential, under the key
	// this host holds -- and lifting the fence is a decision about whether
	// a restored instance may act on the world again. Neither is the
	// fleet's to take, and a fleet that wants its own data has the
	// per-installation export instead.
	ActionRecoveryWrite:  store.RolePlatform,
	ActionBackupsRead:    store.RolePlatform,
	ActionBackupsWrite:   store.RolePlatform,
	ActionBackupsRestore: store.RolePlatform,
}

// AllActions returns every action, sorted. The UI's token editor lists the
// scopes from here, so the list a human sees can never drift from the list the
// server enforces.
func AllActions() []Action {
	out := make([]Action, 0, len(actionRoles))
	for a := range actionRoles {
		out = append(out, a)
	}
	slices.Sort(out)
	return out
}

// Known reports whether a is an action this server enforces.
func (a Action) Known() bool { _, ok := actionRoles[a]; return ok }

// Resource is the noun an action acts on, e.g. "pools".
func (a Action) Resource() string { r, _, _ := strings.Cut(string(a), "."); return r }

// Verb is what the action does to its resource, e.g. "read".
func (a Action) Verb() string { _, v, _ := strings.Cut(string(a), "."); return v }

// Scope renders the action as the scope string an API token carries.
func (a Action) Scope() string { return a.Resource() + ":" + a.Verb() }

// MinRole returns the least privileged role that may perform a.
//
// An action that is not in the table returns admin, which keeps the display
// honest, but Allowed refuses unknown actions outright: failing closed matters
// more than being able to name the role.
func (a Action) MinRole() store.Role {
	if r, ok := actionRoles[a]; ok {
		return r
	}
	return store.RoleAdmin
}

// String makes Action printable in log lines and error messages.
func (a Action) String() string { return string(a) }

// Allowed reports whether id may perform a.
//
// Two gates apply. The role must reach the action's minimum, and -- when the
// identity carries a non-empty scope list -- one of its scopes must cover the
// action. An empty scope list means "whatever the role allows", which is what
// every user session and most tokens have.
func Allowed(id *Identity, a Action) bool {
	if id == nil {
		return false
	}
	want, known := actionRoles[a]
	if !known {
		return false
	}
	if !id.Role.AtLeast(want) {
		return false
	}
	if len(id.Scopes) == 0 {
		return true
	}
	if scopesAllow(id.Scopes, a) {
		return true
	}
	for _, wider := range impliedBy[a] {
		if scopesAllow(id.Scopes, wider) {
			return true
		}
	}
	return false
}

// impliedBy lists, for an action, the wider actions whose scope also grants
// it. A token scoped to everybody's tokens was minted to manage tokens, and
// refusing it its own would break every such token the day tokens.own arrived.
var impliedBy = map[Action][]Action{
	ActionTokensOwn: {ActionTokensRead, ActionTokensWrite},
}

// scopesAllow reports whether any scope in the list covers a.
//
// "*" covers everything, "pools:*" covers one resource, and any scope on a
// resource implies reading that resource -- a token that may drain runners but
// could not list them would be useless.
func scopesAllow(scopes []string, a Action) bool {
	want := a.Scope()
	for _, s := range scopes {
		s = strings.ToLower(strings.TrimSpace(s))
		switch s {
		case "", "-":
			continue
		case "*", "*:*":
			return true
		}
		if s == want {
			return true
		}
		res, verb, ok := strings.Cut(s, ":")
		if !ok || res != a.Resource() {
			continue
		}
		if verb == "*" || a.Verb() == "read" {
			return true
		}
	}
	return false
}

// ManageWithin refuses an account change that would reach past the caller's
// own role: granting a role the caller does not hold, or acting on an account
// that outranks it. Without it the platform role separated nothing -- an
// administrator could create a platform account, promote their own, or reset
// the platform's password and sign in as it. It is MintWithin's rule for
// accounts: authority is handed on, never made up.
func ManageWithin(by *Identity, roles ...store.Role) error {
	if by == nil {
		return Invalid("an account can only be changed by an authenticated caller")
	}
	for _, role := range roles {
		if !by.Role.AtLeast(role) {
			return Invalid("the %s role cannot grant or change a %s account; ask somebody with the %s role", by.Role, role, role)
		}
	}
	return nil
}

// MintWithin refuses a token that would carry more than the identity minting
// it. A token is a way to hand authority on, and handing on more than one
// holds is how a narrowly scoped credential that leaked turns into an
// unscoped one that never expires: the role may not exceed the caller's, and
// a caller narrowed by scopes may only mint a token narrowed at least as far.
//
// The check is made against the actions themselves rather than the scope
// strings, so "pools:*" covers "pools:write", any scope on a resource covers
// reading it, and a new action needs no change here.
func MintWithin(by *Identity, role store.Role, scopes []string) error {
	if by == nil {
		return Invalid("a token can only be minted by an authenticated caller")
	}
	if !by.Role.AtLeast(role) {
		return Invalid("a %s cannot mint a %s token; a token carries no more than the caller that made it", by.Role, role)
	}
	if len(by.Scopes) == 0 {
		return nil
	}
	if len(scopes) == 0 {
		return Invalid("this token is limited to %s, so the tokens it mints need scopes within that; an unscoped token would carry the whole role",
			strings.Join(by.Scopes, ", "))
	}
	var beyond []string
	for _, a := range AllActions() {
		if scopesAllow(scopes, a) && !scopesAllow(by.Scopes, a) {
			beyond = append(beyond, a.Scope())
		}
	}
	if len(beyond) > 0 {
		return Invalid("this token is limited to %s and cannot mint one that reaches %s",
			strings.Join(by.Scopes, ", "), strings.Join(beyond, ", "))
	}
	return nil
}

// ValidateScopes checks a token's requested scopes against the action list, so
// a typo is rejected at creation time rather than silently granting nothing.
func ValidateScopes(scopes []string) error {
	valid := map[string]bool{"*": true, "*:*": true}
	resources := map[string]bool{}
	for _, a := range AllActions() {
		valid[a.Scope()] = true
		resources[a.Resource()] = true
	}
	for r := range resources {
		valid[r+":*"] = true
	}
	var bad []string
	for _, s := range scopes {
		s = strings.ToLower(strings.TrimSpace(s))
		if s == "" {
			continue
		}
		if !valid[s] {
			bad = append(bad, s)
		}
	}
	if len(bad) == 0 {
		return nil
	}
	all := make([]string, 0, len(actionRoles))
	for _, a := range AllActions() {
		all = append(all, a.Scope())
	}
	return fmt.Errorf("unknown scope %s: valid scopes are %s, or <resource>:* , or *",
		strings.Join(bad, ", "), strings.Join(all, ", "))
}

// Explain returns the sentence a 403 should carry, or "" when the action is
// allowed. It names the role or scope that is missing, because "forbidden" on
// its own tells an operator nothing about what to change.
func Explain(id *Identity, a Action) string {
	if id == nil {
		return "this action needs you to be signed in"
	}
	want, known := actionRoles[a]
	if !known {
		return fmt.Sprintf("%q is not an action this server knows about", string(a))
	}
	if !id.Role.AtLeast(want) {
		return fmt.Sprintf("this action needs the %s role; your %s has %s",
			want, id.subject(), id.Role)
	}
	if len(id.Scopes) > 0 && !scopesAllow(id.Scopes, a) {
		return fmt.Sprintf("this action needs the %q scope; your %s is limited to %s",
			a.Scope(), id.subject(), strings.Join(id.Scopes, ", "))
	}
	return ""
}

package auth

import (
	"errors"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// readVerbs are the actions that only look at something. Everything else
// changes the fleet, an account or a credential.
var readVerbs = map[string]bool{"read": true}

// TestEveryActionHasARole is the test that catches a new endpoint being added
// without anybody deciding who may call it: an action that is not in the RBAC
// table fails here rather than silently denying every request in production.
func TestEveryActionHasARole(t *testing.T) {
	actions := AllActions()
	if len(actions) == 0 {
		t.Fatal("AllActions is empty")
	}
	seen := map[string]bool{}
	for _, a := range actions {
		if !a.Known() {
			t.Errorf("%s is not in the RBAC table", a)
			continue
		}
		if role := a.MinRole(); !role.Valid() {
			t.Errorf("%s maps to %q, which is not a role", a, role)
		}
		res, verb := a.Resource(), a.Verb()
		if res == "" || verb == "" {
			t.Errorf("%s is not shaped like <resource>.<verb>", a)
		}
		if want := res + ":" + verb; a.Scope() != want {
			t.Errorf("%s.Scope() = %q; want %q", a, a.Scope(), want)
		}
		if seen[string(a)] {
			t.Errorf("%s is listed twice", a)
		}
		seen[string(a)] = true
	}

	// The actions the API surface promises. Losing one of these means an
	// endpoint has no policy behind it.
	for _, required := range []Action{
		ActionPoolsRead, ActionPoolsWrite, ActionPoolsDelete,
		ActionRunnersRead, ActionRunnersDrain, ActionRunnersDelete,
		ActionJobsRead,
		ActionJobsCancel, ActionProvisioningWrite,
		ActionHostsRead, ActionHostsCordon, ActionHostsDelete,
		ActionInstallationsRead, ActionInstallationsWrite, ActionInstallationsDelete,
		ActionAuditRead,
		ActionUsersRead, ActionUsersWrite,
		ActionTokensRead, ActionTokensWrite,
		ActionSettingsRead, ActionSettingsWrite,
		ActionMetricsRead, ActionEventsRead, ActionLogsRead, ActionJoinsWrite,
		ActionDiagnosticsRead,
	} {
		if !required.Known() {
			t.Errorf("%s is missing from the RBAC table", required)
		}
	}
}

// ownCredentials are the write actions a viewer holds because they act on
// the viewer's own credentials and nothing of the fleet's: a token minted this
// way carries no more than the viewer does.
var ownCredentials = map[Action]bool{ActionTokensOwn: true}

// ownershipChecked are write actions a viewer holds only as the coarse gate:
// every handler behind them also requires the caller to own what they change
// (context.manage: an installation an administrator delegated), so the role
// alone reaches nothing. Adding to this list is a security decision; the route
// walk in internal/api shows which handlers carry the second check.
var ownershipChecked = map[Action]bool{ActionContextManage: true}

// TestRoleAuthority walks the full action list for every role. A viewer must
// not be able to perform any write action -- that single assertion is what
// stops a new mutating endpoint from being given away for free.
func TestRoleAuthority(t *testing.T) {
	roles := []store.Role{store.RoleViewer, store.RoleOperator, store.RoleAdmin, store.RolePlatform}
	for _, role := range roles {
		for _, a := range AllActions() {
			id := &Identity{Kind: KindUser, ID: "usr_1", Name: "test", Role: role}
			got := id.Can(a)
			want := role.AtLeast(a.MinRole())
			if got != want {
				t.Errorf("%s may do %s = %v; want %v (minimum role %s)", role, a, got, want, a.MinRole())
			}
			if role == store.RoleViewer && got && !readVerbs[a.Verb()] && !ownCredentials[a] && !ownershipChecked[a] {
				t.Errorf("a viewer may perform the write action %s; every mutating action needs operator or admin", a)
			}
			if !got && Explain(id, a) == "" {
				t.Errorf("%s is denied %s with no explanation", role, a)
			}
			if got && Explain(id, a) != "" {
				t.Errorf("%s is allowed %s but Explain returned %q", role, a, Explain(id, a))
			}
		}
	}
}

func TestSecretsStayWithAdmins(t *testing.T) {
	// Reading a user list, a token list, a join token or the settings can
	// expose credentials or their metadata, so none of them is a viewer read.
	// The bundle is on that list because it contains the settings section: a
	// document assembled from admin-only material does not become viewer
	// material by being assembled.
	for _, a := range []Action{ActionUsersRead, ActionTokensRead, ActionJoinsRead, ActionSettingsRead, ActionDiagnosticsRead} {
		if a.MinRole() != store.RoleAdmin {
			t.Errorf("%s needs %s; want admin", a, a.MinRole())
		}
	}
}

func TestUnknownActionIsDenied(t *testing.T) {
	admin := &Identity{Kind: KindUser, Role: store.RoleAdmin}
	if admin.Can("pools.nuke") {
		t.Error("an unknown action was allowed; authorisation must fail closed")
	}
	if msg := Explain(admin, "pools.nuke"); !strings.Contains(msg, "not an action") {
		t.Errorf("Explain for an unknown action = %q", msg)
	}
}

func TestNilIdentityIsDenied(t *testing.T) {
	var id *Identity
	if Allowed(id, ActionJobsRead) {
		t.Error("a nil identity was allowed to read jobs")
	}
	if msg := Explain(id, ActionJobsRead); !strings.Contains(msg, "signed in") {
		t.Errorf("Explain for a nil identity = %q", msg)
	}
}

func TestScopeNarrowing(t *testing.T) {
	cases := []struct {
		name   string
		scopes []string
		action Action
		want   bool
	}{
		{"empty scopes fall back to the role", nil, ActionPoolsDelete, true},
		{"exact match", []string{"pools:write"}, ActionPoolsWrite, true},
		{"other resource", []string{"pools:write"}, ActionRunnersDrain, false},
		{"other verb", []string{"pools:write"}, ActionPoolsDelete, false},
		{"acting implies reading", []string{"pools:write"}, ActionPoolsRead, true},
		{"reading does not imply acting", []string{"pools:read"}, ActionPoolsWrite, false},
		{"resource wildcard", []string{"runners:*"}, ActionRunnersDelete, true},
		{"resource wildcard is still one resource", []string{"runners:*"}, ActionPoolsWrite, false},
		{"global wildcard", []string{"*"}, ActionPoolsDelete, true},
		{"case and spacing are forgiven", []string{" Pools:Write "}, ActionPoolsWrite, true},
		{"several scopes", []string{"jobs:read", "runners:drain"}, ActionRunnersDrain, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			id := &Identity{Kind: KindToken, Name: "ci", Role: store.RoleOperator, Scopes: tc.scopes}
			if got := id.Can(tc.action); got != tc.want {
				t.Fatalf("Can(%s) with scopes %v = %v; want %v", tc.action, tc.scopes, got, tc.want)
			}
		})
	}
}

func TestScopesNeverWidenARole(t *testing.T) {
	// A viewer token asking for an admin scope is still a viewer.
	id := &Identity{Kind: KindToken, Name: "ci", Role: store.RoleViewer, Scopes: []string{"*"}}
	if id.Can(ActionUsersWrite) {
		t.Error("a wildcard scope let a viewer manage users; scopes narrow, they never widen")
	}
}

func TestExplainNamesWhatIsMissing(t *testing.T) {
	token := &Identity{Kind: KindToken, Name: "ci", Role: store.RoleViewer}
	msg := Explain(token, ActionPoolsWrite)
	if msg != "this action needs the operator role; your token has viewer" {
		t.Errorf("Explain = %q; want it to name the required role and the one held", msg)
	}

	scoped := &Identity{Kind: KindToken, Name: "ci", Role: store.RoleOperator, Scopes: []string{"jobs:read"}}
	msg = Explain(scoped, ActionPoolsWrite)
	if !strings.Contains(msg, `"pools:write"`) || !strings.Contains(msg, "jobs:read") {
		t.Errorf("Explain = %q; want it to name the missing scope and the ones held", msg)
	}

	user := &Identity{Kind: KindUser, Name: "alice", Role: store.RoleViewer}
	if msg := Explain(user, ActionUsersWrite); !strings.Contains(msg, "your account has viewer") {
		t.Errorf("Explain for a user = %q; want it to say 'account', not 'token'", msg)
	}
}

func TestValidateScopes(t *testing.T) {
	if err := ValidateScopes([]string{"pools:read", "runners:*", "*", ""}); err != nil {
		t.Errorf("ValidateScopes on valid input: %v", err)
	}
	err := ValidateScopes([]string{"pools:read", "pool:read"})
	if err == nil {
		t.Fatal("a misspelled scope was accepted")
	}
	if !strings.Contains(err.Error(), "pool:read") || !strings.Contains(err.Error(), "pools:read") {
		t.Errorf("the error should name the bad scope and list the valid ones: %v", err)
	}
}

func TestSystemAndAgentIdentities(t *testing.T) {
	if !SystemIdentity().Can(ActionRunnersDelete) {
		t.Error("the system identity cannot remove runners, which is half its job")
	}
	agent := AgentIdentity(&store.Host{ID: "host_1", Name: "builder"}, "10.0.0.5")
	if agent.Can(ActionPoolsWrite) {
		t.Error("an agent identity may edit pools; agents are not fleet operators")
	}
	if agent.Kind != KindAgent || agent.Name != "builder" {
		t.Errorf("agent identity = %+v", agent)
	}
}

// A scope no route checks is one an operator can grant believing it does
// something. runners.create was such a scope: runners are created by the
// scheduler when a job queues, and no endpoint has ever asked for it.
func TestEveryActionIsOneSomethingChecks(t *testing.T) {
	for action := range actionRoles {
		if strings.TrimSpace(string(action)) == "" {
			t.Error("an empty action is in the role table")
		}
		if action == "runners.create" {
			t.Error("runners.create is back; no route checks it, so granting it means nothing")
		}
	}
}

// A token hands authority on, so it must not hand on more than its maker has:
// a leaked token narrowed to one resource would otherwise be one request away
// from an unscoped one that never expires.
func TestATokenCannotMintMoreThanItsMakerHolds(t *testing.T) {
	tests := []struct {
		name   string
		by     *Identity
		role   store.Role
		scopes []string
		wantOK bool
	}{
		{"a user mints anything up to their role", &Identity{Kind: KindUser, Role: store.RoleAdmin}, store.RoleAdmin, nil, true},
		{"an operator cannot mint an admin", &Identity{Kind: KindUser, Role: store.RoleOperator}, store.RoleAdmin, nil, false},
		{"an operator can mint a viewer", &Identity{Kind: KindUser, Role: store.RoleOperator}, store.RoleViewer, nil, true},
		{"a scoped token cannot mint an unscoped one", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"tokens:*"}}, store.RoleAdmin, nil, false},
		{"a scoped token cannot reach past its scopes", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"tokens:*"}}, store.RoleAdmin, []string{"pools:write"}, false},
		{"a scoped token can mint within its scopes", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"pools:*"}}, store.RoleAdmin, []string{"pools:write"}, true},
		{"a resource scope covers reading it", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"pools:write"}}, store.RoleViewer, []string{"pools:read"}, true},
		{"a wildcard is only minted by a wildcard", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"pools:*"}}, store.RoleViewer, []string{"*"}, false},
		{"a wildcard covers everything", &Identity{Kind: KindToken, Role: store.RoleAdmin, Scopes: []string{"*"}}, store.RoleAdmin, []string{"hosts:write"}, true},
		{"nobody mints nothing", nil, store.RoleViewer, nil, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			err := MintWithin(tc.by, tc.role, tc.scopes)
			if tc.wantOK && err != nil {
				t.Fatalf("refused: %v", err)
			}
			if !tc.wantOK && err == nil {
				t.Fatal("allowed a token to carry more than its maker")
			}
			if err != nil && !errors.Is(err, ErrInvalidInput) {
				t.Fatalf("a refusal has to be something the API answers 422 to, got %v", err)
			}
		})
	}
}

// The fence and the backups moved above the fleet's administrator. A backup
// is the whole database under the key this host holds, and lifting the fence
// decides whether a restored instance acts on the world again; on an instance
// operated by one team for another, neither is the fleet's to take.
func TestTheFenceAndTheBackupsNeedThePlatformRole(t *testing.T) {
	moved := []Action{
		ActionRecoveryWrite,
		ActionBackupsRead, ActionBackupsWrite, ActionBackupsRestore,
	}
	admin := &Identity{Kind: KindUser, ID: "usr_a", Name: "alex", Role: store.RoleAdmin}
	platform := &Identity{Kind: KindUser, ID: "usr_p", Name: "pat", Role: store.RolePlatform}

	for _, a := range moved {
		if a.MinRole() != store.RolePlatform {
			t.Errorf("%s needs %s; want platform", a, a.MinRole())
		}
		if admin.Can(a) {
			t.Errorf("an administrator may still %s", a)
		}
		if !platform.Can(a) {
			t.Errorf("a platform account may not %s", a)
		}
		// A refusal an operator cannot act on is a support ticket.
		if msg := Explain(admin, a); !strings.Contains(msg, "platform") {
			t.Errorf("refusing %s to an admin says %q, which does not name the role they are missing", a, msg)
		}
	}
}

// Everything else an administrator could do, they still can. This is the
// guard against the change reaching further than the four actions above.
func TestNothingElseMovedOutOfReachOfAnAdministrator(t *testing.T) {
	moved := map[Action]bool{
		ActionRecoveryWrite: true,
		ActionBackupsRead:   true, ActionBackupsWrite: true, ActionBackupsRestore: true,
	}
	admin := &Identity{Kind: KindUser, ID: "usr_a", Name: "alex", Role: store.RoleAdmin}
	for _, a := range AllActions() {
		if moved[a] {
			continue
		}
		if !admin.Can(a) {
			t.Errorf("an administrator may no longer %s, and this change was not meant to touch it", a)
		}
	}
}

// With authentication off there is no second audience: whoever reaches the
// socket has the process. An instance started that way -- `make dev`, the
// browser suite, a loopback trial -- must not answer 403 on its own backups.
func TestWithAuthenticationOffEverythingIsReachable(t *testing.T) {
	dev := DevIdentity("127.0.0.1")
	for _, a := range AllActions() {
		if !dev.Can(a) {
			t.Errorf("with authentication disabled, %s is refused", a)
		}
	}
}

package auth

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha1" //nolint:gosec // RFC 6238's default, and the only one every authenticator app implements.
	"encoding/base32"
	"encoding/binary"
	"fmt"
	"net/url"
	"strings"
	"time"
)

// TOTP parameters. They are RFC 6238's defaults and they are fixed: every
// authenticator app implements exactly these, and the ones that accept
// others do not all say so when they silently ignore them.
const (
	totpPeriod = 30 * time.Second
	totpDigits = 6
	// totpSkew is how many steps either side of now a code is accepted for.
	// One step covers a phone clock thirty seconds adrift and a code typed
	// as it rolled over; more widens the window an overheard code is good in.
	totpSkew = 1
	// totpSecretBytes is 160 bits, the HMAC-SHA-1 block RFC 4226 recommends.
	totpSecretBytes = 20
)

var totpEncoding = base32.StdEncoding.WithPadding(base32.NoPadding)

// newTOTPSecret mints a random authenticator secret, base32 without padding,
// which is what an otpauth:// address and a person typing it by hand expect.
func newTOTPSecret() string {
	b := make([]byte, totpSecretBytes)
	if _, err := rand.Read(b); err != nil {
		panic("zoomies: entropy source unavailable: " + err.Error())
	}
	return totpEncoding.EncodeToString(b)
}

// totpStep is the RFC 6238 time step t falls in.
func totpStep(t time.Time) int64 { return t.Unix() / int64(totpPeriod/time.Second) }

// totpCode is the RFC 4226 HOTP value for a step: HMAC-SHA-1 of the counter,
// dynamically truncated to totpDigits decimal digits.
func totpCode(secret string, step int64) (string, error) {
	key, err := totpEncoding.DecodeString(strings.ToUpper(strings.TrimRight(secret, "=")))
	if err != nil {
		return "", fmt.Errorf("decoding the authenticator secret: %w", err)
	}
	var counter [8]byte
	binary.BigEndian.PutUint64(counter[:], uint64(step))
	mac := hmac.New(sha1.New, key)
	mac.Write(counter[:])
	sum := mac.Sum(nil)
	offset := sum[len(sum)-1] & 0x0f
	value := binary.BigEndian.Uint32(sum[offset:offset+4]) & 0x7fffffff
	return fmt.Sprintf("%0*d", totpDigits, value%1_000_000), nil
}

// matchTOTP returns the step a code is valid for within the skew window
// around now, or false. Every candidate is compared, in constant time, so the
// time taken does not say which step nearly matched.
func matchTOTP(secret, code string, now time.Time) (int64, bool) {
	code = normaliseCode(code)
	if len(code) != totpDigits {
		return 0, false
	}
	current := totpStep(now)
	var found int64
	ok := false
	for d := -totpSkew; d <= totpSkew; d++ {
		want, err := totpCode(secret, current+int64(d))
		if err != nil {
			return 0, false
		}
		if hmac.Equal([]byte(want), []byte(code)) && !ok {
			found, ok = current+int64(d), true
		}
	}
	return found, ok
}

// normaliseCode strips what people type around a code: spaces, the hyphen
// some apps show in the middle, and case, which matters for recovery codes.
func normaliseCode(code string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case r == ' ' || r == '-' || r == '\t':
			return -1
		case r >= 'A' && r <= 'Z':
			return r + ('a' - 'A')
		}
		return r
	}, strings.TrimSpace(code))
}

// totpURI is the otpauth:// address an authenticator app scans. The label
// names the instance as well as the account, so somebody with accounts on a
// staging and a production controller can tell the two entries apart.
func totpURI(secret, issuer, account string) string {
	label := url.PathEscape(issuer) + ":" + url.PathEscape(account)
	q := url.Values{}
	q.Set("secret", secret)
	q.Set("issuer", issuer)
	q.Set("algorithm", "SHA1")
	q.Set("digits", fmt.Sprint(totpDigits))
	q.Set("period", fmt.Sprint(int(totpPeriod/time.Second)))
	return "otpauth://totp/" + label + "?" + q.Encode()
}

// Recovery codes.
const (
	// RecoveryCodeCount is how many are issued at once.
	RecoveryCodeCount = 10
	// recoveryCodeChars gives each code about 49 bits: ten characters from
	// a 31-letter alphabet, shown as two groups of five. Guessing one is
	// bounded by the same sign-in limits as a password.
	recoveryCodeChars = 10
)

var recoveryAlphabet = []byte("abcdefghjkmnpqrstuvwxyz23456789")

// newRecoveryCodes mints a set of recovery codes, formatted for reading
// aloud or writing down: lowercase, no 0/o, 1/l/i confusion, and a hyphen in
// the middle that normaliseCode ignores.
func newRecoveryCodes() []string {
	out := make([]string, RecoveryCodeCount)
	for i := range out {
		b := make([]byte, recoveryCodeChars)
		raw := make([]byte, recoveryCodeChars)
		if _, err := rand.Read(raw); err != nil {
			panic("zoomies: entropy source unavailable: " + err.Error())
		}
		for j, r := range raw {
			// 256 is not a multiple of the alphabet's length, so reject
			// the tail rather than bias the first few letters.
			for int(r) >= 256-256%len(recoveryAlphabet) {
				var one [1]byte
				if _, err := rand.Read(one[:]); err != nil {
					panic("zoomies: entropy source unavailable: " + err.Error())
				}
				r = one[0]
			}
			b[j] = recoveryAlphabet[int(r)%len(recoveryAlphabet)]
		}
		out[i] = string(b[:5]) + "-" + string(b[5:])
	}
	return out
}

// looksLikeRecoveryCode tells the two kinds of second factor apart by shape,
// so one field on the sign-in page can take either.
func looksLikeRecoveryCode(code string) bool {
	return len(normaliseCode(code)) == recoveryCodeChars
}

package auth

import (
	"net/url"
	"strings"
	"testing"
	"time"
)

// rfcSecret is RFC 6238 appendix B's SHA-1 seed, "12345678901234567890",
// in base32.
const rfcSecret = "GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ"

// Appendix B's vectors, cut to six digits: the last six of each eight-digit
// value, which is what every authenticator app shows.
func TestTOTPMatchesTheRFC6238Vectors(t *testing.T) {
	for _, tc := range []struct {
		unix int64
		want string
	}{
		{59, "287082"},
		{1111111109, "081804"},
		{1111111111, "050471"},
		{1234567890, "005924"},
		{2000000000, "279037"},
		{20000000000, "353130"},
	} {
		got, err := totpCode(rfcSecret, totpStep(time.Unix(tc.unix, 0)))
		if err != nil {
			t.Fatal(err)
		}
		if got != tc.want {
			t.Errorf("code at %d = %s, want %s", tc.unix, got, tc.want)
		}
	}
}

func TestACodeIsAcceptedOneStepEitherSideAndNoFurther(t *testing.T) {
	now := time.Unix(1111111111, 0)
	step := totpStep(now)
	for _, tc := range []struct {
		offset int64
		want   bool
	}{
		{-2, false}, {-1, true}, {0, true}, {1, true}, {2, false},
	} {
		code, _ := totpCode(rfcSecret, step+tc.offset)
		got, ok := matchTOTP(rfcSecret, code, now)
		if ok != tc.want {
			t.Errorf("a code %d steps away: accepted = %v, want %v", tc.offset, ok, tc.want)
		}
		if ok && got != step+tc.offset {
			t.Errorf("a code %d steps away matched step %d, want %d", tc.offset, got, step+tc.offset)
		}
	}
}

func TestACodeIsReadTheWayPeopleTypeIt(t *testing.T) {
	now := time.Unix(1111111111, 0)
	for _, tc := range []struct {
		typed string
		want  bool
	}{
		{"050471", true},
		{" 050 471 ", true},
		{"050-471", true},
		{"50471", false},
		{"0504711", false},
		{"", false},
		{"abcdef", false},
	} {
		if _, ok := matchTOTP(rfcSecret, tc.typed, now); ok != tc.want {
			t.Errorf("matchTOTP(%q) = %v, want %v", tc.typed, ok, tc.want)
		}
	}
}

func TestANewSecretIsA160BitBase32Key(t *testing.T) {
	a, b := newTOTPSecret(), newTOTPSecret()
	if a == b {
		t.Fatal("two secrets were the same")
	}
	if len(a) != 32 || strings.ContainsAny(a, "=abcdefghijklmnopqrstuvwxyz01") {
		t.Fatalf("secret %q is not 32 characters of unpadded upper-case base32", a)
	}
	if _, err := totpCode(a, 1); err != nil {
		t.Fatalf("a minted secret does not decode: %v", err)
	}
}

// The label names the instance as well as the account, and every parameter
// is spelled out, because an app that assumes a default it does not state
// is an app that shows the wrong code.
func TestTheProvisioningAddressSaysEverythingAnAppNeeds(t *testing.T) {
	raw := totpURI(rfcSecret, "Zoomies", "ada (ci.example.com)")
	u, err := url.Parse(raw)
	if err != nil {
		t.Fatal(err)
	}
	if u.Scheme != "otpauth" || u.Host != "totp" || u.Path != "/Zoomies:ada (ci.example.com)" {
		t.Fatalf("address = %s", raw)
	}
	q := u.Query()
	for k, want := range map[string]string{"secret": rfcSecret, "issuer": "Zoomies", "algorithm": "SHA1", "digits": "6", "period": "30"} {
		if q.Get(k) != want {
			t.Errorf("%s = %q, want %q", k, q.Get(k), want)
		}
	}
}

func TestRecoveryCodesAreDistinctReadableAndRecognisedByShape(t *testing.T) {
	codes := newRecoveryCodes()
	if len(codes) != RecoveryCodeCount {
		t.Fatalf("%d codes, want %d", len(codes), RecoveryCodeCount)
	}
	seen := map[string]bool{}
	for _, c := range codes {
		if seen[c] {
			t.Fatalf("code %s issued twice", c)
		}
		seen[c] = true
		if len(c) != 11 || c[5] != '-' || strings.ContainsAny(c, "01ilo") {
			t.Errorf("code %q is not two groups of five unambiguous characters", c)
		}
		for _, typed := range []string{c, strings.ToUpper(c), strings.ReplaceAll(c, "-", " ")} {
			if !looksLikeRecoveryCode(typed) {
				t.Errorf("%q is not recognised as a recovery code", typed)
			}
		}
	}
	if looksLikeRecoveryCode("123456") {
		t.Error("an authenticator code was taken for a recovery code")
	}
}

package auth

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/qr"
	"github.com/eyupio/zoomies/internal/store"
)

// Two-step verification: an authenticator code after the password, for
// accounts that sign in with one.
//
// It is deliberately limited to local password accounts. An account that
// signs in through single sign-on gets its second factor, if it has one, from
// the identity provider, which is where a company's MFA policy already lives;
// asking again here would be a second prompt enforcing nothing new. API
// tokens are untouched too: a token is a long random secret that is already
// something you have, and automation has nobody to type a code.

// signInChallengeTTL is how long a sign-in may wait between the password and
// the code. Long enough to find a phone and open an app; short enough that a
// half-finished sign-in left on a shared machine is not a door left open.
const signInChallengeTTL = 5 * time.Minute

// maxChallengeFailures is how many wrong codes one pending sign-in takes
// before it is thrown away and the password has to be typed again. The rate
// limiters bound guessing overall; this stops one password proof buying an
// unbounded run at the code.
const maxChallengeFailures = 5

// twoStepIssuer is the name an authenticator app files the entry under.
const twoStepIssuer = "Zoomies"

var (
	// ErrInvalidTwoStepCode is a code that is wrong, outside the time window,
	// already used, or a recovery code that was already spent. One sentence
	// for all of them: which one it was is worth nothing to a guesser, and
	// the remedy -- the current code -- is the same.
	ErrInvalidTwoStepCode error = &refusal{kind: ErrInvalidInput,
		msg: "that code is not right, or has already been used; enter the current code from your authenticator app, or one of your recovery codes"}
	// ErrSignInExpired means the pending sign-in is gone: it took too long,
	// took too many wrong codes, or finished already.
	ErrSignInExpired = errors.New("this sign-in has expired; enter your username and password again")
	// ErrTwoStepUnavailable is an account that has no password to put a
	// second step after.
	ErrTwoStepUnavailable error = &refusal{kind: ErrInvalidInput,
		msg: "two-step verification is for accounts that sign in with a password; an account that uses single sign-on gets its second factor from the identity provider"}
	// ErrTwoStepAlreadyOn refuses starting enrolment over a working one.
	ErrTwoStepAlreadyOn error = &refusal{kind: store.ErrConflict,
		msg: "two-step verification is already on for this account; turn it off first to move it to a new device"}
	// ErrTwoStepNotOn refuses an action that needs it on.
	ErrTwoStepNotOn error = &refusal{kind: ErrInvalidInput,
		msg: "two-step verification is not on for this account"}
	// ErrTwoStepNotStarted is a confirmation with no enrolment to confirm.
	ErrTwoStepNotStarted error = &refusal{kind: ErrInvalidInput,
		msg: "no two-step setup is in progress for this account; start again to get a new key"}
	// ErrNoEncryptionKey means the service was built without the instance
	// key, so it has nowhere safe to keep a secret. It is the controller's
	// fault, not the caller's.
	ErrNoEncryptionKey = errors.New("two-step verification needs the instance encryption key, and this service was started without one")
)

// SecondStepRequired is what Login returns in place of a session when the
// password was right and the account has a second step still to take.
//
// It is an error on purpose. Every caller of Login that predates two-step --
// and any written later by somebody who has not read this -- treats it as a
// failed sign-in and mints nothing, so forgetting to handle it fails closed.
type SecondStepRequired struct {
	// Challenge is the plaintext token for the browser's challenge cookie.
	// Only its hash is stored.
	Challenge string
	// Purpose is store.ChallengeVerify or store.ChallengeEnrol.
	Purpose   string
	ExpiresAt time.Time
	User      *store.User
}

func (e *SecondStepRequired) Error() string {
	if e.Purpose == store.ChallengeEnrol {
		return "this instance requires two-step verification; set it up to finish signing in"
	}
	return "enter the code from your authenticator app to finish signing in"
}

// TwoStepStatus is one account's two-step state, as the account page shows it.
type TwoStepStatus struct {
	// Available is false for an account with no password: single sign-on.
	Available bool
	Enabled   bool
	EnabledAt *time.Time
	// RecoveryCodesLeft counts unspent recovery codes.
	RecoveryCodesLeft int
	// Required reports security.require_two_step.
	Required bool
}

// TwoStepSetup is what enrolment shows once: the key, the address an app
// scans, and that address drawn as a QR code.
type TwoStepSetup struct {
	Secret string
	URI    string
	QRSVG  string
}

// SignIn is a finished two-step sign-in.
type SignIn struct {
	User    *store.User
	Session string
	// RecoveryCodeUsed says a recovery code stood in for the app, which the
	// audit row records and the page warns about.
	RecoveryCodeUsed  bool
	RecoveryCodesLeft int
	// RecoveryCodes is set when the sign-in was an enrolment: the codes the
	// person has to write down before they go any further.
	RecoveryCodes []string
}

// WithKey gives the service the instance key it seals authenticator secrets
// with. Without it, two-step verification refuses to start.
func WithKey(k *cryptox.Key) Option {
	return func(s *Service) { s.key = k }
}

// RequireTwoStep reports whether every local account must use two-step.
func (s *Service) RequireTwoStep() bool { return s.cfg.RequireTwoStep }

// secondStep decides, after a correct password, whether the sign-in needs
// another step, and opens a challenge for it when it does.
func (s *Service) secondStep(ctx context.Context, u *store.User, ip, ua string) (*SecondStepRequired, error) {
	purpose := ""
	ts, err := s.store.GetTwoStep(ctx, u.ID)
	switch {
	case err == nil && ts.Enabled():
		purpose = store.ChallengeVerify
	case err != nil && !errors.Is(err, store.ErrNotFound):
		return nil, fmt.Errorf("reading two-step state: %w", err)
	case s.cfg.RequireTwoStep:
		purpose = store.ChallengeEnrol
	default:
		return nil, nil
	}
	token := store.NewSecret(32)
	c := &store.SignInChallenge{
		TokenHash: cryptox.HashToken(token),
		UserID:    u.ID,
		Purpose:   purpose,
		IP:        ip,
		UserAgent: truncate(ua, 512),
		ExpiresAt: s.Now().Add(signInChallengeTTL),
	}
	if err := s.store.CreateSignInChallenge(ctx, c); err != nil {
		return nil, fmt.Errorf("starting the second step: %w", err)
	}
	return &SecondStepRequired{Challenge: token, Purpose: purpose, ExpiresAt: c.ExpiresAt, User: u}, nil
}

// challenge resolves a pending sign-in and the account behind it, and
// refuses one that has expired, is for the other purpose, or is being
// finished from a different browser than the one that typed the password.
func (s *Service) challenge(ctx context.Context, token, purpose, ua string) (*store.SignInChallenge, *store.User, error) {
	if token == "" {
		return nil, nil, ErrSignInExpired
	}
	c, err := s.store.GetSignInChallenge(ctx, cryptox.HashToken(token))
	if errors.Is(err, store.ErrNotFound) {
		return nil, nil, ErrSignInExpired
	}
	if err != nil {
		return nil, nil, fmt.Errorf("reading the pending sign-in: %w", err)
	}
	if !s.Now().Before(c.ExpiresAt) {
		_ = s.store.DeleteSignInChallenge(ctx, c.TokenHash)
		return nil, nil, ErrSignInExpired
	}
	// The cookie is the binding; the user agent is a second, cheap one, so a
	// challenge cookie lifted into another browser is not enough on its own.
	if c.Purpose != purpose || c.UserAgent != truncate(ua, 512) {
		return nil, nil, ErrSignInExpired
	}
	u, err := s.store.GetUser(ctx, c.UserID)
	if errors.Is(err, store.ErrNotFound) {
		return nil, nil, ErrSignInExpired
	}
	if err != nil {
		return nil, nil, fmt.Errorf("reading the account: %w", err)
	}
	if u.Disabled {
		return nil, nil, ErrAccountDisabled
	}
	return c, u, nil
}

// allowAttempt charges one attempt at a second factor to the same limiters a
// password attempt is charged to, so a code is no cheaper to guess than the
// password in front of it.
func (s *Service) allowAttempt(ip, username string) bool {
	if ip != "" && !s.logins.Allow(ip) {
		s.logger.Warn("two-step rate limit hit", "ip", ip, "username", username)
		return false
	}
	if account := normalizeForLimiter(username); account != "" && !s.accountLogins.Allow(account) {
		s.logger.Warn("two-step rate limit hit for an account", "ip", ip, "username", username)
		return false
	}
	return true
}

// failChallenge counts a wrong code against the pending sign-in, and ends it
// once it has had its share.
// The refusal is audited here, because only here is the account known: the
// handler holds nothing but a cookie.
func (s *Service) failChallenge(ctx context.Context, c *store.SignInChallenge, u *store.User, ip string) error {
	s.audit.Auth(ctx, &Identity{Kind: KindUser, ID: u.ID, Name: u.Username, IP: ip}, "auth.two_step_failed",
		map[string]any{"username": u.Username, "step": c.Purpose})
	n, err := s.store.FailSignInChallenge(ctx, c.TokenHash)
	if err != nil && !errors.Is(err, store.ErrNotFound) {
		s.logger.Warn("could not count a wrong two-step code", "error", err)
	}
	if n >= maxChallengeFailures || errors.Is(err, store.ErrNotFound) {
		_ = s.store.DeleteSignInChallenge(ctx, c.TokenHash)
		return ErrSignInExpired
	}
	return ErrInvalidTwoStepCode
}

// finish mints the session a completed sign-in has earned, and forgives the
// attempts that led to it, exactly as a password-only sign-in does.
func (s *Service) finish(ctx context.Context, c *store.SignInChallenge, u *store.User, ip, ua string) (string, error) {
	if err := s.store.DeleteSignInChallenge(ctx, c.TokenHash); err != nil {
		return "", fmt.Errorf("closing the pending sign-in: %w", err)
	}
	token, err := s.NewSession(ctx, u, ip, ua)
	if err != nil {
		return "", err
	}
	now := s.Now()
	if err := s.store.TouchLogin(ctx, u.ID, now); err != nil {
		s.logger.Warn("could not record last login", "user", u.Username, "error", err)
	}
	u.LastLoginAt = &now
	s.logins.Reset(ip)
	s.accountLogins.Reset(normalizeForLimiter(u.Username))
	return token, nil
}

// VerifySignIn finishes a sign-in with a code from the authenticator app or
// a recovery code.
func (s *Service) VerifySignIn(ctx context.Context, challenge, code, ip, ua string) (*SignIn, error) {
	c, u, err := s.challenge(ctx, challenge, store.ChallengeVerify, ua)
	if err != nil {
		return nil, err
	}
	if !s.allowAttempt(ip, u.Username) {
		return nil, ErrRateLimited
	}
	usedRecovery, err := s.checkSecondFactor(ctx, u.ID, code)
	if errors.Is(err, ErrInvalidTwoStepCode) {
		return nil, s.failChallenge(ctx, c, u, ip)
	}
	if err != nil {
		return nil, err
	}
	token, err := s.finish(ctx, c, u, ip, ua)
	if err != nil {
		return nil, err
	}
	out := &SignIn{User: u, Session: token, RecoveryCodeUsed: usedRecovery}
	if usedRecovery {
		out.RecoveryCodesLeft, _ = s.store.RemainingRecoveryCodes(ctx, u.ID)
	}
	return out, nil
}

// checkSecondFactor accepts a current authenticator code, once, or an
// unspent recovery code, once. It reports which it was.
func (s *Service) checkSecondFactor(ctx context.Context, userID, code string) (recovery bool, err error) {
	ts, err := s.store.GetTwoStep(ctx, userID)
	if errors.Is(err, store.ErrNotFound) || (err == nil && !ts.Enabled()) {
		return false, ErrTwoStepNotOn
	}
	if err != nil {
		return false, fmt.Errorf("reading two-step state: %w", err)
	}
	if looksLikeRecoveryCode(code) {
		ok, err := s.store.UseRecoveryCode(ctx, userID, cryptox.HashToken(normaliseCode(code)))
		if err != nil {
			return false, fmt.Errorf("checking a recovery code: %w", err)
		}
		if !ok {
			return false, ErrInvalidTwoStepCode
		}
		return true, nil
	}
	secret, err := s.openSecret(ts.SecretEnc)
	if err != nil {
		return false, err
	}
	step, ok := matchTOTP(secret, code, s.Now())
	if !ok {
		return false, ErrInvalidTwoStepCode
	}
	// The replay guard: a code for a step at or before the last one
	// accepted is refused, even though it is arithmetically right.
	fresh, err := s.store.AcceptTwoStepStep(ctx, userID, step)
	if err != nil {
		return false, fmt.Errorf("recording the code: %w", err)
	}
	if !fresh {
		return false, ErrInvalidTwoStepCode
	}
	return false, nil
}

func (s *Service) sealSecret(secret string) ([]byte, error) {
	if s.key == nil {
		return nil, ErrNoEncryptionKey
	}
	return s.key.SealString(secret)
}

func (s *Service) openSecret(sealed []byte) (string, error) {
	if s.key == nil {
		return "", ErrNoEncryptionKey
	}
	secret, err := s.key.OpenString(sealed)
	if err != nil {
		return "", fmt.Errorf("opening the authenticator secret (was the encryption key changed?): %w", err)
	}
	return secret, nil
}

// TwoStepStatus reports an account's two-step state.
func (s *Service) TwoStepStatus(ctx context.Context, userID string) (*TwoStepStatus, error) {
	u, err := s.store.GetUser(ctx, userID)
	if err != nil {
		return nil, err
	}
	out := &TwoStepStatus{Available: u.PasswordHash != "", Required: s.cfg.RequireTwoStep}
	ts, err := s.store.GetTwoStep(ctx, userID)
	switch {
	case errors.Is(err, store.ErrNotFound):
		return out, nil
	case err != nil:
		return nil, err
	}
	out.Enabled, out.EnabledAt = ts.Enabled(), ts.EnabledAt
	if out.Enabled {
		if out.RecoveryCodesLeft, err = s.store.RemainingRecoveryCodes(ctx, userID); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// BeginTwoStep mints a new secret for an account and stores it, unconfirmed.
// host is the address the instance was reached on; the authenticator app
// lists the entry as the account and that address, so two instances do not
// produce two identical entries.
func (s *Service) BeginTwoStep(ctx context.Context, userID, host string) (*TwoStepSetup, error) {
	u, err := s.store.GetUser(ctx, userID)
	if err != nil {
		return nil, err
	}
	if u.PasswordHash == "" {
		return nil, ErrTwoStepUnavailable
	}
	secret := newTOTPSecret()
	sealed, err := s.sealSecret(secret)
	if err != nil {
		return nil, err
	}
	if err := s.store.BeginTwoStep(ctx, u.ID, sealed); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return nil, ErrTwoStepAlreadyOn
		}
		return nil, fmt.Errorf("storing the new secret: %w", err)
	}
	label := u.Username
	if host != "" {
		label += " (" + host + ")"
	}
	uri := totpURI(secret, twoStepIssuer, label)
	code, err := qr.Encode([]byte(uri))
	if err != nil {
		return nil, fmt.Errorf("drawing the QR code: %w", err)
	}
	// Dark on white in both themes: a scanner wants contrast, and a code
	// drawn light-on-dark does not scan in every app.
	return &TwoStepSetup{Secret: secret, URI: uri, QRSVG: code.SVG("#000000", "#ffffff")}, nil
}

// ConfirmTwoStep checks the first code from the new authenticator, turns
// two-step on, and returns the recovery codes -- the only time they exist in
// plaintext. Every other session for the account is ended: whoever holds one
// signed in with less than the account now asks for.
func (s *Service) ConfirmTwoStep(ctx context.Context, userID, code, keepSession, ip string) ([]string, error) {
	// Charged like every other code attempt. The secret being guessed is the
	// caller's own, so this guards less than a sign-in does, but a code that
	// is free to guess on one route is a limiter with a hole in it.
	u, err := s.store.GetUser(ctx, userID)
	if err != nil {
		return nil, err
	}
	if !s.allowAttempt(ip, u.Username) {
		return nil, ErrRateLimited
	}
	return s.confirmTwoStep(ctx, userID, code, keepSession)
}

// confirmTwoStep is ConfirmTwoStep for a caller that has already charged the
// attempt.
func (s *Service) confirmTwoStep(ctx context.Context, userID, code, keepSession string) ([]string, error) {
	ts, err := s.store.GetTwoStep(ctx, userID)
	if errors.Is(err, store.ErrNotFound) {
		return nil, ErrTwoStepNotStarted
	}
	if err != nil {
		return nil, err
	}
	if ts.Enabled() {
		return nil, ErrTwoStepAlreadyOn
	}
	secret, err := s.openSecret(ts.SecretEnc)
	if err != nil {
		return nil, err
	}
	step, ok := matchTOTP(secret, code, s.Now())
	if !ok {
		return nil, ErrInvalidTwoStepCode
	}
	codes := newRecoveryCodes()
	if err := s.store.ConfirmTwoStep(ctx, userID, step, hashCodes(codes)); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return nil, ErrTwoStepAlreadyOn
		}
		return nil, fmt.Errorf("turning two-step on: %w", err)
	}
	s.endOtherSessions(ctx, userID, keepSession)
	return codes, nil
}

// EnrolDuringSignIn is BeginTwoStep for somebody who is not signed in yet:
// the instance requires two-step, their password was right, and this is the
// setup they have to finish before they get a session.
func (s *Service) EnrolDuringSignIn(ctx context.Context, challenge, host, ua string) (*TwoStepSetup, error) {
	_, u, err := s.challenge(ctx, challenge, store.ChallengeEnrol, ua)
	if err != nil {
		return nil, err
	}
	return s.BeginTwoStep(ctx, u.ID, host)
}

// ConfirmDuringSignIn finishes an enrolment the sign-in required, and signs
// the person in.
func (s *Service) ConfirmDuringSignIn(ctx context.Context, challenge, code, ip, ua string) (*SignIn, error) {
	c, u, err := s.challenge(ctx, challenge, store.ChallengeEnrol, ua)
	if err != nil {
		return nil, err
	}
	if !s.allowAttempt(ip, u.Username) {
		return nil, ErrRateLimited
	}
	codes, err := s.confirmTwoStep(ctx, u.ID, code, "")
	if errors.Is(err, ErrInvalidTwoStepCode) {
		return nil, s.failChallenge(ctx, c, u, ip)
	}
	if err != nil {
		return nil, err
	}
	token, err := s.finish(ctx, c, u, ip, ua)
	if err != nil {
		return nil, err
	}
	return &SignIn{User: u, Session: token, RecoveryCodes: codes, RecoveryCodesLeft: len(codes)}, nil
}

// reauthenticate is the proof DisableTwoStep and RegenerateRecoveryCodes ask
// for: the password and a current code. A stolen session cookie is neither,
// so it cannot take the second factor off the account it stole.
func (s *Service) reauthenticate(ctx context.Context, userID, password, code, ip string) (*store.User, error) {
	u, err := s.store.GetUser(ctx, userID)
	if err != nil {
		return nil, err
	}
	if u.PasswordHash == "" {
		return nil, ErrTwoStepUnavailable
	}
	if !s.allowAttempt(ip, u.Username) {
		return nil, ErrRateLimited
	}
	if !cryptox.VerifyPassword(password, u.PasswordHash) {
		return nil, ErrWrongPassword
	}
	if _, err := s.checkSecondFactor(ctx, u.ID, code); err != nil {
		return nil, err
	}
	return u, nil
}

// DisableTwoStep turns two-step off for the caller's own account.
func (s *Service) DisableTwoStep(ctx context.Context, userID, password, code, ip string) error {
	if _, err := s.reauthenticate(ctx, userID, password, code, ip); err != nil {
		return err
	}
	if _, err := s.store.DeleteTwoStep(ctx, userID); err != nil {
		return fmt.Errorf("turning two-step off: %w", err)
	}
	return nil
}

// RegenerateRecoveryCodes replaces every recovery code the account has, and
// returns the new ones.
func (s *Service) RegenerateRecoveryCodes(ctx context.Context, userID, password, code, ip string) ([]string, error) {
	if _, err := s.reauthenticate(ctx, userID, password, code, ip); err != nil {
		return nil, err
	}
	codes := newRecoveryCodes()
	if err := s.store.ReplaceRecoveryCodes(ctx, userID, hashCodes(codes)); err != nil {
		return nil, fmt.Errorf("storing new recovery codes: %w", err)
	}
	return codes, nil
}

// ResetTwoStep is the administrator's reset, for somebody who has lost their
// authenticator and their recovery codes. It removes the secret and the
// codes and ends every session the account has, and it reports whether there
// was anything to remove. The caller audits it.
func (s *Service) ResetTwoStep(ctx context.Context, userID string) (bool, error) {
	if _, err := s.store.GetUser(ctx, userID); err != nil {
		return false, err
	}
	removed, err := s.store.DeleteTwoStep(ctx, userID)
	if err != nil {
		return false, fmt.Errorf("resetting two-step: %w", err)
	}
	if err := s.store.DeleteUserSessions(ctx, userID); err != nil {
		s.logger.Warn("could not end sessions after a two-step reset", "user_id", userID, "error", err)
	}
	return removed, nil
}

// endOtherSessions ends every session of an account but the one making the
// request, identified by its plaintext cookie.
func (s *Service) endOtherSessions(ctx context.Context, userID, keep string) {
	keepHash := ""
	if keep != "" {
		keepHash = cryptox.HashToken(keep)
	}
	if err := s.store.DeleteUserSessionsExcept(ctx, userID, keepHash); err != nil {
		s.logger.Warn("could not end other sessions after turning two-step on", "user_id", userID, "error", err)
	}
}

func hashCodes(codes []string) []string {
	out := make([]string, len(codes))
	for i, c := range codes {
		out[i] = cryptox.HashToken(normaliseCode(c))
	}
	return out
}

package auth

import (
	"errors"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

const testUA = "Mozilla/5.0 (test)"

// newTwoStepService is newService with the instance key two-step seals its
// secrets with, and the configuration in the test's hands.
func newTwoStepService(t *testing.T, mutate func(*config.Config)) (*Service, *store.Store, *clock) {
	t.Helper()
	cfg := config.Default()
	cfg.Security.RateLimitLogins = 0
	cfg.Security.SessionTTL = time.Hour
	if mutate != nil {
		mutate(cfg)
	}
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatal(err)
	}
	c := newClock()
	st, err := store.Open(t.Context(), store.Options{Path: ":memory:", Now: c.Now})
	if err != nil {
		t.Fatalf("opening store: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return New(st, cfg, events.New(), WithClock(c.Now), WithKey(key)), st, c
}

// currentCode is what the person's phone shows right now.
func currentCode(t *testing.T, secret string, c *clock) string {
	t.Helper()
	code, err := totpCode(secret, totpStep(c.Now()))
	if err != nil {
		t.Fatal(err)
	}
	return code
}

// enrol turns two-step on for u and returns the secret and recovery codes,
// then moves the clock on a step so the confirming code is not the next one.
func enrol(t *testing.T, s *Service, u *store.User, c *clock) (string, []string) {
	t.Helper()
	setup, err := s.BeginTwoStep(t.Context(), u.ID, "ci.example.com")
	if err != nil {
		t.Fatalf("BeginTwoStep: %v", err)
	}
	codes, err := s.ConfirmTwoStep(t.Context(), u.ID, currentCode(t, setup.Secret, c), "", "")
	if err != nil {
		t.Fatalf("ConfirmTwoStep: %v", err)
	}
	c.Advance(totpPeriod)
	return setup.Secret, codes
}

// signInPassword runs the first step and returns the pending sign-in.
func signInPassword(t *testing.T, s *Service, username string) *SecondStepRequired {
	t.Helper()
	_, token, err := s.Login(t.Context(), username, testPassword, "192.0.2.1", testUA)
	var pending *SecondStepRequired
	if !errors.As(err, &pending) {
		t.Fatalf("Login = token %q, %v; want a second step", token, err)
	}
	if token != "" {
		t.Fatal("a session was minted before the second step")
	}
	return pending
}

func TestAnAccountWithoutTwoStepSignsInExactlyAsBefore(t *testing.T) {
	s, st, _ := newTwoStepService(t, nil)
	addUser(t, st, "ada", store.RoleOperator, nil)
	// An enrolment started and abandoned asks nothing at sign-in.
	u, _ := st.GetUserByUsername(t.Context(), "ada")
	if _, err := s.BeginTwoStep(t.Context(), u.ID, "ada"); err != nil {
		t.Fatal(err)
	}
	_, token, err := s.Login(t.Context(), "ada", testPassword, "192.0.2.1", testUA)
	if err != nil || token == "" {
		t.Fatalf("Login = %q, %v; want a session", token, err)
	}
}

func TestTheCodeStepFinishesTheSignInAndCannotBeSkipped(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, _ := enrol(t, s, u, c)

	pending := signInPassword(t, s, "ada")
	if pending.Purpose != store.ChallengeVerify || pending.Challenge == "" {
		t.Fatalf("pending = %+v", pending)
	}
	if !pending.ExpiresAt.Equal(c.Now().Add(signInChallengeTTL)) {
		t.Errorf("the pending sign-in expires at %v, want five minutes from now", pending.ExpiresAt)
	}

	// The challenge is not a session: presented as a cookie, it is nobody.
	if _, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: pending.Challenge}); !errors.Is(err, ErrSessionExpired) {
		t.Fatalf("the challenge authenticated as a session: %v", err)
	}
	// Nor is it an enrolment, which would let somebody with only a password
	// replace the account's authenticator.
	if _, err := s.EnrolDuringSignIn(t.Context(), pending.Challenge, "ada", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("a verify challenge started an enrolment: %v", err)
	}
	// Nor can it be finished from another browser.
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "192.0.2.1", "curl/8"); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("a challenge was finished with another user agent: %v", err)
	}

	in, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "192.0.2.1", testUA)
	if err != nil {
		t.Fatalf("VerifySignIn: %v", err)
	}
	if in.Session == "" || in.User.ID != u.ID || in.RecoveryCodeUsed {
		t.Fatalf("sign-in = %+v", in)
	}
	if id, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: in.Session}); err != nil || id.ID != u.ID {
		t.Fatalf("the new session does not authenticate: %v", err)
	}
	// A finished challenge is spent.
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "192.0.2.1", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("a finished challenge was used again: %v", err)
	}
}

// A code seen once -- over a shoulder, or relayed by a phishing page -- is
// worth nothing the second time, even inside its thirty seconds.
func TestACodeIsRefusedTheSecondTime(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, _ := enrol(t, s, u, c)
	code := currentCode(t, secret, c)

	if _, err := s.VerifySignIn(t.Context(), signInPassword(t, s, "ada").Challenge, code, "", testUA); err != nil {
		t.Fatalf("first use: %v", err)
	}
	if _, err := s.VerifySignIn(t.Context(), signInPassword(t, s, "ada").Challenge, code, "", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Fatalf("second use = %v, want ErrInvalidTwoStepCode", err)
	}
	// And the confirming code of an enrolment counts as used.
	s2, st2, c2 := newTwoStepService(t, nil)
	u2 := addUser(t, st2, "grace", store.RoleOperator, nil)
	setup, _ := s2.BeginTwoStep(t.Context(), u2.ID, "grace")
	first := currentCode(t, setup.Secret, c2)
	if _, err := s2.ConfirmTwoStep(t.Context(), u2.ID, first, "", ""); err != nil {
		t.Fatal(err)
	}
	if _, err := s2.VerifySignIn(t.Context(), signInPassword(t, s2, "grace").Challenge, first, "", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Fatalf("the enrolment's code signed in = %v", err)
	}
}

func TestAPendingSignInExpiresAfterFiveMinutes(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, _ := enrol(t, s, u, c)
	pending := signInPassword(t, s, "ada")

	c.Advance(signInChallengeTTL)
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("an expired sign-in = %v, want ErrSignInExpired", err)
	}
}

func TestWrongCodesEndThePendingSignIn(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, _ := enrol(t, s, u, c)
	pending := signInPassword(t, s, "ada")

	for i := 1; i < maxChallengeFailures; i++ {
		if _, err := s.VerifySignIn(t.Context(), pending.Challenge, "000000", "", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
			t.Fatalf("wrong code %d = %v, want ErrInvalidTwoStepCode", i, err)
		}
	}
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, "000000", "", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("the last wrong code = %v, want the sign-in ended", err)
	}
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("the right code after the sign-in ended = %v", err)
	}
}

// A code is no cheaper to guess than the password in front of it: every
// attempt is charged to the same per-address counter, and a success is what
// clears it.
func TestCodeFailuresCountTowardTheSignInLimit(t *testing.T) {
	s, st, c := newTwoStepService(t, func(cfg *config.Config) { cfg.Security.RateLimitLogins = 3 })
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, _ := enrol(t, s, u, c)

	pending := signInPassword(t, s, "ada") // attempt 1
	for i := 0; i < 2; i++ {               // attempts 2 and 3
		if _, err := s.VerifySignIn(t.Context(), pending.Challenge, "000000", "192.0.2.1", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
			t.Fatalf("wrong code = %v", err)
		}
	}
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, currentCode(t, secret, c), "192.0.2.1", testUA); !errors.Is(err, ErrRateLimited) {
		t.Fatalf("a fourth attempt inside the minute = %v, want ErrRateLimited", err)
	}
	if _, _, err := s.Login(t.Context(), "ada", testPassword, "192.0.2.1", testUA); !errors.Is(err, ErrRateLimited) {
		t.Fatalf("the password after the codes = %v, want ErrRateLimited", err)
	}
}

func TestARecoveryCodeSignsInOnce(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	_, codes := enrol(t, s, u, c)
	if len(codes) != RecoveryCodeCount {
		t.Fatalf("%d recovery codes, want %d", len(codes), RecoveryCodeCount)
	}

	in, err := s.VerifySignIn(t.Context(), signInPassword(t, s, "ada").Challenge, codes[3], "", testUA)
	if err != nil {
		t.Fatalf("a recovery code: %v", err)
	}
	if !in.RecoveryCodeUsed || in.RecoveryCodesLeft != RecoveryCodeCount-1 {
		t.Fatalf("sign-in = used %v, left %d", in.RecoveryCodeUsed, in.RecoveryCodesLeft)
	}
	if _, err := s.VerifySignIn(t.Context(), signInPassword(t, s, "ada").Challenge, codes[3], "", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Fatalf("the same recovery code again = %v", err)
	}
	// Typed in capitals with a space instead of the hyphen, another one still works.
	typed := codes[4][:5] + " " + codes[4][6:]
	if _, err := s.VerifySignIn(t.Context(), signInPassword(t, s, "ada").Challenge, typed, "", testUA); err != nil {
		t.Fatalf("a recovery code typed loosely: %v", err)
	}
}

func TestRequiringTwoStepMakesAnAccountEnrolBeforeItGetsASession(t *testing.T) {
	s, st, c := newTwoStepService(t, func(cfg *config.Config) { cfg.Security.RequireTwoStep = true })
	u := addUser(t, st, "ada", store.RoleOperator, nil)

	pending := signInPassword(t, s, "ada")
	if pending.Purpose != store.ChallengeEnrol {
		t.Fatalf("purpose = %q, want enrol", pending.Purpose)
	}
	// An enrolment challenge cannot be finished with a code: there is no
	// authenticator yet, and the step is setting one up.
	if _, err := s.VerifySignIn(t.Context(), pending.Challenge, "000000", "", testUA); !errors.Is(err, ErrSignInExpired) {
		t.Fatalf("verify on an enrolment challenge = %v", err)
	}
	setup, err := s.EnrolDuringSignIn(t.Context(), pending.Challenge, "ada", testUA)
	if err != nil {
		t.Fatalf("EnrolDuringSignIn: %v", err)
	}
	if setup.Secret == "" || setup.QRSVG == "" {
		t.Fatalf("setup = %+v", setup)
	}
	if _, err := s.ConfirmDuringSignIn(t.Context(), pending.Challenge, "000000", "", testUA); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Fatalf("a wrong first code = %v", err)
	}
	in, err := s.ConfirmDuringSignIn(t.Context(), pending.Challenge, currentCode(t, setup.Secret, c), "", testUA)
	if err != nil {
		t.Fatalf("ConfirmDuringSignIn: %v", err)
	}
	if in.Session == "" || len(in.RecoveryCodes) != RecoveryCodeCount {
		t.Fatalf("sign-in = session %q, %d codes", in.Session, len(in.RecoveryCodes))
	}
	status, err := s.TwoStepStatus(t.Context(), u.ID)
	if err != nil || !status.Enabled || !status.Required {
		t.Fatalf("status = %+v, %v", status, err)
	}
	// The next sign-in asks for a code, not for enrolment.
	c.Advance(totpPeriod)
	if p := signInPassword(t, s, "ada"); p.Purpose != store.ChallengeVerify {
		t.Fatalf("the sign-in after enrolling asked to %s", p.Purpose)
	}
}

// Single sign-on accounts have no password to put a step after, and their
// second factor belongs to the identity provider: requiring two-step here
// must neither lock them out nor offer them an enrolment.
func TestSingleSignOnAccountsAreNotAskedForTwoStep(t *testing.T) {
	s, st, _ := newTwoStepService(t, func(cfg *config.Config) { cfg.Security.RequireTwoStep = true })
	u := addUser(t, st, "sso", store.RoleViewer, func(u *store.User) {
		u.PasswordHash = ""
		u.OIDCSubject = "sub-123"
	})
	status, err := s.TwoStepStatus(t.Context(), u.ID)
	if err != nil || status.Available || status.Enabled {
		t.Fatalf("status = %+v, %v; want unavailable", status, err)
	}
	if _, err := s.BeginTwoStep(t.Context(), u.ID, "sso"); !errors.Is(err, ErrTwoStepUnavailable) {
		t.Fatalf("BeginTwoStep for an SSO account = %v", err)
	}
	// The callback's path into a session is NewSession, which two-step does
	// not stand in front of.
	token, err := s.NewSession(t.Context(), u, "", testUA)
	if err != nil {
		t.Fatal(err)
	}
	if id, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: token}); err != nil || id.ID != u.ID {
		t.Fatalf("an SSO session does not authenticate with two-step required: %v", err)
	}
}

// Tokens are for automation, which has nobody to type a code; they are
// already a long random secret the caller holds.
func TestAPITokensAreNotAskedForACode(t *testing.T) {
	s, st, c := newTwoStepService(t, func(cfg *config.Config) { cfg.Security.RequireTwoStep = true })
	u := addUser(t, st, "ada", store.RoleAdmin, nil)
	enrol(t, s, u, c)
	_, plain, err := s.CreateAPIToken(t.Context(), NewToken{Name: "ci", Role: store.RoleViewer, UserID: u.ID, OwnerRole: store.RoleAdmin})
	if err != nil {
		t.Fatalf("CreateAPIToken: %v", err)
	}
	if _, err := s.Authenticate(t.Context(), AuthInput{Authorization: "Bearer " + plain}); err != nil {
		t.Fatalf("a token of an account with two-step on: %v", err)
	}
}

func TestTurningTwoStepOffTakesThePasswordAndACode(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	secret, codes := enrol(t, s, u, c)

	for _, tc := range []struct {
		name     string
		password string
		code     string
		want     error
	}{
		{"wrong password", "not the password at all", currentCode(t, secret, c), ErrWrongPassword},
		{"no code", testPassword, "", ErrInvalidTwoStepCode},
		{"wrong code", testPassword, "000000", ErrInvalidTwoStepCode},
	} {
		if err := s.DisableTwoStep(t.Context(), u.ID, tc.password, tc.code, ""); !errors.Is(err, tc.want) {
			t.Errorf("%s: DisableTwoStep = %v, want %v", tc.name, err, tc.want)
		}
	}
	if _, err := s.RegenerateRecoveryCodes(t.Context(), u.ID, testPassword, "000000", ""); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Errorf("RegenerateRecoveryCodes with a wrong code = %v", err)
	}
	fresh, err := s.RegenerateRecoveryCodes(t.Context(), u.ID, testPassword, currentCode(t, secret, c), "")
	if err != nil || len(fresh) != RecoveryCodeCount {
		t.Fatalf("RegenerateRecoveryCodes = %d codes, %v", len(fresh), err)
	}
	// The old set died with the new one's issue; a new one works to turn it off.
	if err := s.DisableTwoStep(t.Context(), u.ID, testPassword, codes[0], ""); !errors.Is(err, ErrInvalidTwoStepCode) {
		t.Errorf("an old recovery code = %v", err)
	}
	if err := s.DisableTwoStep(t.Context(), u.ID, testPassword, fresh[0], ""); err != nil {
		t.Fatalf("DisableTwoStep: %v", err)
	}
	if _, token, err := s.Login(t.Context(), "ada", testPassword, "", testUA); err != nil || token == "" {
		t.Fatalf("with two-step off, Login = %q, %v", token, err)
	}
}

func TestTurningTwoStepOnEndsEveryOtherSession(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	here, _ := s.NewSession(t.Context(), u, "", testUA)
	elsewhere, _ := s.NewSession(t.Context(), u, "", testUA)

	setup, err := s.BeginTwoStep(t.Context(), u.ID, "ada")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.ConfirmTwoStep(t.Context(), u.ID, currentCode(t, setup.Secret, c), here, ""); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: here}); err != nil {
		t.Errorf("the session that turned it on was ended: %v", err)
	}
	if _, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: elsewhere}); err == nil {
		t.Error("a session signed in with the password alone outlived turning two-step on")
	}
	if _, err := s.BeginTwoStep(t.Context(), u.ID, "ada"); !errors.Is(err, ErrTwoStepAlreadyOn) {
		t.Errorf("beginning again over a working enrolment = %v", err)
	}
}

func TestAnAdministratorsResetRemovesTheSecondFactorAndEndsSessions(t *testing.T) {
	s, st, c := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	enrol(t, s, u, c)
	session, _ := s.NewSession(t.Context(), u, "", testUA)

	removed, err := s.ResetTwoStep(t.Context(), u.ID)
	if err != nil || !removed {
		t.Fatalf("ResetTwoStep = %v, %v", removed, err)
	}
	if _, err := s.Authenticate(t.Context(), AuthInput{SessionCookie: session}); err == nil {
		t.Error("a session outlived the reset")
	}
	if _, token, err := s.Login(t.Context(), "ada", testPassword, "", testUA); err != nil || token == "" {
		t.Fatalf("after a reset, Login = %q, %v; want the password alone", token, err)
	}
	if removed, _ := s.ResetTwoStep(t.Context(), u.ID); removed {
		t.Error("a second reset said it removed something")
	}
	if _, err := s.ResetTwoStep(t.Context(), "usr_missing"); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("resetting a missing account = %v", err)
	}
}

// A service built without the instance key has nowhere safe to put a
// secret, and says so rather than storing one in the clear.
func TestTwoStepRefusesToStartWithoutTheInstanceKey(t *testing.T) {
	s, st, _ := newService(t)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	if _, err := s.BeginTwoStep(t.Context(), u.ID, "ada"); !errors.Is(err, ErrNoEncryptionKey) {
		t.Fatalf("BeginTwoStep without a key = %v", err)
	}
	if _, err := st.GetTwoStep(t.Context(), u.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("something was stored: %v", err)
	}
}

func TestTheSecretIsStoredSealed(t *testing.T) {
	s, st, _ := newTwoStepService(t, nil)
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	setup, err := s.BeginTwoStep(t.Context(), u.ID, "ada")
	if err != nil {
		t.Fatal(err)
	}
	ts, err := st.GetTwoStep(t.Context(), u.ID)
	if err != nil {
		t.Fatal(err)
	}
	if string(ts.SecretEnc) == setup.Secret || len(ts.SecretEnc) <= len(setup.Secret) {
		t.Fatal("the authenticator secret is in the database in the clear")
	}
}

// Confirming the setup from settings is a code attempt like any other: it is
// charged to the same limiters, so no route guesses codes for free.
func TestConfirmingSetupIsChargedToTheSignInLimit(t *testing.T) {
	s, st, _ := newTwoStepService(t, func(cfg *config.Config) { cfg.Security.RateLimitLogins = 3 })
	u := addUser(t, st, "ada", store.RoleOperator, nil)
	if _, err := s.BeginTwoStep(t.Context(), u.ID, "ci.example.com"); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		if _, err := s.ConfirmTwoStep(t.Context(), u.ID, "000000", "", "192.0.2.1"); !errors.Is(err, ErrInvalidTwoStepCode) {
			t.Fatalf("wrong code %d = %v", i+1, err)
		}
	}
	if _, err := s.ConfirmTwoStep(t.Context(), u.ID, "000000", "", "192.0.2.1"); !errors.Is(err, ErrRateLimited) {
		t.Fatalf("a fourth attempt inside the minute = %v, want ErrRateLimited", err)
	}
}

package backend

import (
	"context"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"
)

// These tests pin the agent to what docs/security.md ("What the agent owns on
// a host") promises a team before they run the enrolment command on their own
// machine. A prune that widens -- to images, to volumes, to a container
// somebody else started -- is a promise broken on a machine that is not ours,
// so each failure names the promise rather than the endpoint.

const agentOwnsPromise = `docs/security.md, "What the agent owns on a host"`

// The one daemon-wide thing the agent does is ask Docker to prune unused
// builder cache down to a target. Decision 25 keeps exactly that and nothing
// broader: no filter that reaches further, no second endpoint, and nothing at
// all when the target is zero, which is the shared-daemon advice.
func TestTheBuilderCachePruneAsksForNothingButUnusedCacheAboveTheTarget(t *testing.T) {
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/build/prune": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"SpaceReclaimed": 42})
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{})

	if _, err := b.PruneBuildCache(context.Background(), 0); err != nil {
		t.Fatal(err)
	}
	if len(f.seen) != 0 {
		t.Fatalf("a builder-cache target of 0 sent %d requests; 0 is the shared-daemon advice and must prune nothing (%s)", len(f.seen), agentOwnsPromise)
	}

	freed, err := b.PruneBuildCache(context.Background(), 5<<30)
	if err != nil {
		t.Fatal(err)
	}
	if freed != 42 {
		t.Errorf("freed = %d, want what the daemon reported", freed)
	}
	if len(f.seen) != 1 {
		t.Fatalf("the prune sent %d requests, want exactly one to /build/prune (%s)", len(f.seen), agentOwnsPromise)
	}
	r := f.seen[0]
	if r.Method != http.MethodPost || r.URL.Path != v+"/build/prune" {
		t.Fatalf("the prune sent %s %s; the builder cache is the only thing the agent prunes daemon-wide (%s)", r.Method, r.URL.Path, agentOwnsPromise)
	}
	q := r.URL.Query()
	keys := slices.Sorted(func(yield func(string) bool) {
		for k := range q {
			if !yield(k) {
				return
			}
		}
	})
	if !slices.Equal(keys, []string{"all", "keep-storage"}) {
		t.Errorf("the prune sent parameters %v; anything beyond the target reaches further than decision 25 allows (%s)", keys, agentOwnsPromise)
	}
	if q.Get("keep-storage") != "5368709120" {
		t.Errorf("keep-storage = %q, want the configured target in bytes", q.Get("keep-storage"))
	}
}

// Podman has no builder cache for the agent to prune, and the promise says so.
func TestPodmanPrunesNoBuilderCache(t *testing.T) {
	f := newFakeEngine(t, nil)
	b, err := NewPodman(DockerOptions{Host: "tcp://" + f.Listener.Addr().String(), Logger: quietLogger()})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := b.PruneBuildCache(context.Background(), 5<<30); err != nil {
		t.Fatal(err)
	}
	if len(f.seen) != 0 {
		t.Fatalf("a Podman backend sent %d requests to prune builder cache (%s)", len(f.seen), agentOwnsPromise)
	}
}

// The label is the whole boundary of which containers the agent touches: it
// lists, and therefore reaps, only what it labelled.
func TestTheAgentListsOnlyContainersCarryingItsLabel(t *testing.T) {
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/containers/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, []any{})
		},
	})
	if _, err := dockerBackendFor(t, f, DockerOptions{}).List(context.Background()); err != nil {
		t.Fatal(err)
	}
	r := f.request(http.MethodGet, v+"/containers/json")
	if r == nil {
		t.Fatal("List sent no container listing")
	}
	if !strings.Contains(r.URL.Query().Get("filters"), LabelManaged+"=true") {
		t.Fatalf("List filters = %q; without %s=true the agent would reap containers it did not start (%s)",
			r.URL.Query().Get("filters"), LabelManaged, agentOwnsPromise)
	}
}

// Nothing anywhere in the tree may ask a daemon to prune images, containers,
// volumes or networks, or delete an image or a volume. This reads the source
// rather than a fake daemon because the promise is about every code path,
// including one written next year that no fake here would think to exercise.
func TestNothingInTheTreePrunesImagesVolumesOrUnlabelledContainers(t *testing.T) {
	forbidden := []*regexp.Regexp{
		regexp.MustCompile(`"/(images|containers|volumes|networks)/prune"`),
		regexp.MustCompile(`MethodDelete,\s*"/(images|volumes)/`),
		regexp.MustCompile(`"DELETE",\s*"/(images|volumes)/`),
		regexp.MustCompile(`"(docker|podman)",\s*"(image|volume|system|container)",\s*"prune"`),
	}
	root := filepath.Join("..", "..")
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			case "node_modules", ".git", "web", "site", "dist":
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		body, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		for _, re := range forbidden {
			if m := re.Find(body); m != nil {
				t.Errorf("%s: %s -- the agent prunes only unused builder cache, and removes only containers it labelled (%s)", path, m, agentOwnsPromise)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
}

// Package backend defines how an agent materialises a runner on its host, and
// provides the implementations: Docker, Podman and a bare process.
//
// The interface is deliberately narrow -- create, inspect, log, remove -- so
// that a future cloud backend that boots a VM per job can satisfy it without
// the agent learning anything new.
package backend

import (
	"context"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// ErrNotFound is returned when a handle refers to a workload that no longer
// exists. Callers treat it as "already gone", not as a failure.
var ErrNotFound = errors.New("backend: workload not found")

// ErrUnavailable is returned when the backend's daemon cannot be reached.
var ErrUnavailable = errors.New("backend: not available on this host")

// Handle identifies one runner workload on a host. For containers it is the
// container ID; for the process backend it is the runner's work directory.
type Handle string

// CreateResult separates time spent fetching container images from the work
// needed to create and start the workload. ImagePullDuration is nil when a
// backend cannot observe an image pull (notably the process backend).
type CreateResult struct {
	DinDReadyDuration *time.Duration `json:"dind_ready_duration,omitempty"`
	Handle            Handle         `json:"handle"`
	Digest            string         `json:"digest,omitempty"`
	ImagePullDuration *time.Duration `json:"image_pull_duration,omitempty"`
	CreateDuration    time.Duration  `json:"create_duration"`
}

// Phase is the backend's view of a workload, which is coarser than the runner
// state machine: the backend knows whether the process is alive, not whether
// GitHub has given it a job.
type Phase string

const (
	// PhaseStarting means created but not yet running.
	PhaseStarting Phase = "starting"
	// PhaseRunning means the runner process is up.
	PhaseRunning Phase = "running"
	// PhaseExited means the runner process finished. For an ephemeral runner
	// this is the normal end of life after one job.
	PhaseExited Phase = "exited"
	// PhaseExitUnknown means the process is gone but its exit status was
	// not retained across an agent restart. It is neither success nor failure.
	PhaseExitUnknown Phase = "exit_unknown"
	// PhaseFailed means the workload died unexpectedly.
	PhaseFailed Phase = "failed"
	// PhaseGone means the workload no longer exists.
	PhaseGone Phase = "gone"
)

// Live reports whether the workload still exists and may yet do work. It is
// the question a caller asks before deciding a container is safe to delete,
// and starting counts: a workload created moments ago has not failed, it has
// not finished starting.
func (p Phase) Live() bool { return p == PhaseStarting || p == PhaseRunning }

// Status is a point-in-time report on one workload.
type Status struct {
	Handle    Handle    `json:"handle"`
	Phase     Phase     `json:"phase"`
	ExitCode  int       `json:"exit_code"`
	Message   string    `json:"message,omitempty"`
	StartedAt time.Time `json:"started_at,omitempty"`
	ExitedAt  time.Time `json:"exited_at,omitempty"`
	// OOMKilled is the daemon saying the kernel killed a process in the
	// workload for its memory limit. It can be true with any exit code: a
	// step killed under a runner that lived on exits the container cleanly.
	OOMKilled bool `json:"oom_killed,omitempty"`
}

// Stats is a best-effort resource sample. Backends that cannot measure a field
// leave it zero.
type CPUThrottling struct {
	Periods              uint64 `json:"periods"`
	ThrottledPeriods     uint64 `json:"throttled_periods"`
	ThrottledNanoseconds uint64 `json:"throttled_nanoseconds"`
}

type Stats struct {
	SampledAt     *time.Time     `json:"sampled_at,omitempty"`
	CPUThrottling *CPUThrottling `json:"cpu_throttling,omitempty"`

	CPUPercent  float64 `json:"cpu_percent"`
	MemoryBytes int64   `json:"memory_bytes"`
	MemoryLimit int64   `json:"memory_limit,omitempty"`
	// CPUAllocationFactor is filled by the agent. One is the creation quota;
	// above one is elastic CPU and below one is host-pressure throttling.
	CPUAllocationFactor float64 `json:"cpu_allocation_factor,omitempty"`
	// BusiestHalfPercent is, for a docker-in-docker pair, how much of its own
	// creation quota the busier of the two containers is using, in percent.
	// The pair's sum hides the case that matters: the daemon running a build
	// flat out on its half while the runner beside it idles reads as a pair
	// half busy. Zero for a single container, and from an agent that predates
	// it, which a controller reads as "judge the sum", as it always did.
	BusiestHalfPercent float64 `json:"busiest_half_percent,omitempty"`
}

// Info describes a backend's capabilities on this particular host. The agent
// reports it to the controller, and the installer prints it during setup.
type Info struct {
	Kind store.BackendKind `json:"kind"`
	// Available is false when the daemon could not be reached; Detail then
	// explains why in terms the operator can act on.
	Available bool   `json:"available"`
	Version   string `json:"version,omitempty"`
	// Rootless reports whether the daemon runs without root privileges, which
	// is the configuration Zoomies prefers.
	Rootless bool `json:"rootless"`
	// Endpoint is the socket or command actually in use.
	Endpoint string `json:"endpoint,omitempty"`
	Detail   string `json:"detail,omitempty"`
	// SupportsDinD reports whether a docker-in-docker sidecar can be created.
	SupportsDinD bool `json:"supports_dind"`
	// HostSocketPath is where the host daemon's socket lives, for pools that
	// have explicitly opted into host-socket mode.
	HostSocketPath string `json:"host_socket_path,omitempty"`
	// CPUs and MemoryMB are the machine the daemon is running on, as the
	// daemon sees it. They are the honest bound for what this host can run,
	// which the agent's own view is not: a containerised agent is held to its
	// cgroup, and the runners it starts through this daemon are siblings on the
	// host rather than children inside that cgroup. Zero where the daemon did
	// not say, which includes every backend that is not a container runtime.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	// Limits is whether the daemon can apply a CPU quota, a memory limit and
	// a pids limit. A daemon that cannot apply a quota refuses the container
	// outright rather than ignoring the request, so the controller reads this
	// before it gives a runner a default limit; Known is false from a backend
	// that has not asked, which the controller reads as "default nothing".
	Limits store.LimitSupport `json:"limits"`
	// SharedFolder says what is wrong with this host's shared folder, the
	// one runners' caches are bound from, and is empty when nothing is:
	// see SharedFolderProblem.
	SharedFolder string `json:"shared_folder,omitempty"`
}

// Credentials carry whatever the runner needs to attach itself to GitHub.
//
// JITConfig is the preferred form: a single base64 blob that registers an
// ephemeral runner and cannot be replayed. RegistrationToken is the fallback
// used by non-ephemeral pools, which must run config.sh.
type Credentials struct {
	// ExpiresAt is GitHub's token expiry, when supplied. Zero means unknown.
	ExpiresAt         time.Time `json:"expires_at,omitzero"`
	JITConfig         string    `json:"jit_config,omitempty"`
	RegistrationToken string    `json:"registration_token,omitempty"`
	// URL is the org or repo URL the runner registers against.
	URL string `json:"url,omitempty"`
	// RunnerGroup and Labels are only needed for the registration-token path;
	// a JIT config already encodes them.
	RunnerGroup string   `json:"runner_group,omitempty"`
	Labels      []string `json:"labels,omitempty"`
	// NoDefaultLabels passes --no-default-labels to config.sh. Like Labels it
	// only means anything on the registration-token path.
	NoDefaultLabels bool `json:"no_default_labels,omitempty"`
}

// Spec is everything a backend needs to create one runner.
type Spec struct {
	// StartBefore bounds queue wait using the controller's provision timeout.
	// An existing workload is adopted even after this deadline.
	StartBefore time.Time `json:"start_before,omitzero"`
	// Name is the runner name as GitHub will know it. It doubles as the
	// container name, so it must be unique on the host.
	Name string `json:"name"`
	// RunnerID is the Zoomies runner ID, attached as a label so that orphaned
	// workloads can be traced back after a controller restart.
	RunnerID string `json:"runner_id"`
	PoolID   string `json:"pool_id"`
	PoolName string `json:"pool_name"`

	Image string `json:"image"`
	// PullPolicy controls preparation of Image for this individual runner. An
	// empty value is accepted for tasks produced by older controllers and lets
	// the container backend use its configured compatibility default.
	PullPolicy  store.PullPolicy  `json:"pull_policy,omitempty"`
	Credentials Credentials       `json:"credentials"`
	Env         map[string]string `json:"env,omitempty"`
	Ephemeral   bool              `json:"ephemeral"`
	Resources   store.Resources   `json:"resources"`
	// ResourcesSource says where Resources came from: the pool's own limits,
	// or the host's default share of its machine (store.AllocationFromPool
	// and store.AllocationFromHost). A backend records it on the workload,
	// because the difference decides what a runner killed for exceeding its
	// memory limit should tell the operator to change. Empty from a
	// controller that predates it, which a backend reads as the pool's.
	ResourcesSource string            `json:"resources_source,omitempty"`
	Cache           store.CacheConfig `json:"cache"`
	Repository      string            `json:"repository,omitempty"`
	DockerMode      store.DockerMode  `json:"docker_mode"`
	// RunAsRoot keeps the container's default user instead of dropping to the
	// unprivileged "runner" account.
	RunAsRoot bool `json:"run_as_root"`
	// Network is an optional container network to attach to.
	Network string `json:"network,omitempty"`
	// WorkDir is the host directory this runner may use as scratch space.
	WorkDir string `json:"work_dir,omitempty"`
	// RunnerVersion pins the actions/runner release for the process backend,
	// which downloads it rather than getting it from an image.
	RunnerVersion string `json:"runner_version,omitempty"`
}

// Validate checks a spec before a backend acts on it.
func (s *Spec) Validate() error {
	if s.Name == "" {
		return errors.New("backend: spec.Name is required")
	}
	if s.Credentials.JITConfig == "" && s.Credentials.RegistrationToken == "" {
		return errors.New("backend: spec needs either a JIT config or a registration token")
	}
	if s.Credentials.RegistrationToken != "" && s.Credentials.URL == "" {
		return errors.New("backend: registration-token runners need a URL to register against")
	}
	if !s.DockerMode.Valid() {
		return fmt.Errorf("backend: %q is not a docker mode", s.DockerMode)
	}
	if s.PullPolicy != "" && !s.PullPolicy.Valid() {
		return fmt.Errorf("backend: %q is not a pool pull policy", s.PullPolicy)
	}
	if s.PullPolicy == store.PullPinnedOnly && !isDigestImageReference(s.Image) {
		return errors.New("backend: pinned-only requires an image digest")
	}
	return nil
}

func isDigestImageReference(ref string) bool {
	const marker = "@sha256:"
	i := strings.LastIndex(ref, marker)
	if i <= 0 || len(ref[i+len(marker):]) != 64 {
		return false
	}
	_, err := hex.DecodeString(ref[i+len(marker):])
	return err == nil
}

// LogOptions controls a log stream.
type LogOptions struct {
	// Follow keeps the stream open and appends new output.
	Follow bool
	// Tail limits the initial backlog; 0 means everything.
	Tail int
	// Since filters to output produced after this time.
	Since time.Time
	// Timestamps prefixes each line with an RFC3339 timestamp.
	Timestamps bool
}

// Backend creates and manages runner workloads on one host.
//
// Implementations must be safe for concurrent use: the agent runs several
// lifecycle operations at once.
type Backend interface {
	// Kind identifies the implementation.
	Kind() store.BackendKind
	// Probe reports what this backend can do on this host. It never returns an
	// error for "daemon is not installed"; that is Info.Available == false with
	// an explanatory Detail, because the agent should report it rather than
	// crash.
	Probe(ctx context.Context) Info
	// Create starts one runner and returns its handle. It must be idempotent
	// with respect to Spec.Name: recreating an existing name replaces it.
	Create(ctx context.Context, spec Spec) (Handle, error)
	// Status inspects one workload. It returns ErrNotFound if the workload is
	// gone.
	Status(ctx context.Context, h Handle) (Status, error)
	// Stats samples resource usage. A backend that cannot measure returns a
	// zero Stats and no error.
	Stats(ctx context.Context, h Handle) (Stats, error)
	// Logs streams a workload's output. The caller closes the reader.
	Logs(ctx context.Context, h Handle, opts LogOptions) (io.ReadCloser, error)
	// Stop asks the runner to finish its current job and exit, waiting at most
	// timeout before killing it. It is how a drain reaches the workload.
	Stop(ctx context.Context, h Handle, timeout time.Duration) error
	// Remove deletes the workload and its scratch space. Removing something
	// that is already gone is not an error.
	Remove(ctx context.Context, h Handle) error
	// List returns every workload this backend owns, including ones the agent
	// has forgotten about. The agent uses it to reap orphans after a restart.
	List(ctx context.Context) ([]Workload, error)
}

// TimedCreator is implemented by backends that expose creation timing. It is
// optional so third-party and older backends retain the explicit unavailable
// path rather than fabricating an image-pull duration.
type TimedCreator interface {
	CreateWithResult(context.Context, Spec) (CreateResult, error)
}

// ImagePrewarmer is implemented by container backends. It prepares an image
// without starting a runner and returns the immutable digest actually present.
type ImagePrewarmer interface {
	PrewarmImage(ctx context.Context, image string, policy store.PullPolicy) (string, error)
}

// Workload pairs a handle with the Zoomies identity recorded on it, so an agent
// restarting into a host full of containers can work out what it owns.
type Workload struct {
	Handle   Handle `json:"handle"`
	Name     string `json:"name"`
	RunnerID string `json:"runner_id"`
	PoolID   string `json:"pool_id"`
	Status   Status `json:"status"`
	// Sidecar marks a supporting container -- today only the docker-in-docker
	// daemon a pool can ask for -- rather than a runner. A backend only lists
	// one once the runner it served has gone, so it is always something to
	// clean up and never something to manage.
	//
	// It carries its runner's id, because that is the only thing that says
	// whose leftovers these are. Anything that finds a runner by id must
	// therefore skip it: binding a runner's slot to its sidecar would stop the
	// sidecar when the controller asked for the runner and leave the real
	// container running somebody's job unattended.
	Sidecar bool `json:"sidecar,omitempty"`
	// Resources are the limits the workload was created with, read back from
	// the labels the backend stamped on it. They are what a throttle scales
	// from, and they have to come from the workload rather than from the
	// agent's memory because the agent adopts what it finds after a restart
	// and remembers nothing about how it was made.
	Resources store.Resources `json:"resources,omitempty"`
}

// ResourceUpdater is implemented by a backend that can change a running
// workload's limits in place. It is how a throttle reaches a job that is
// already running: the one lever a host has left once every runner on it is
// busy, and one that slows a job rather than ending it.
//
// Only the CPU quota is expected to move. A backend may ignore any other
// field, and the container backends do: a memory limit lowered under a live
// process is refused by the daemon or kills the process, and neither is a
// throttle.
type ResourceUpdater interface {
	UpdateResources(ctx context.Context, h Handle, res store.Resources) error
}

// LabelPrefix namespaces the container labels Zoomies writes.
const LabelPrefix = "io.zoomies."

// Well-known labels applied to every workload a backend creates.
const (
	LabelManaged  = LabelPrefix + "managed"
	LabelRunnerID = LabelPrefix + "runner-id"
	LabelPoolID   = LabelPrefix + "pool-id"
	LabelPoolName = LabelPrefix + "pool-name"
	// Cache diagnostics identify the shared volume and the size limit enforced
	// against it between one runner and the next.
	LabelCacheVolume    = LabelPrefix + "cache-volume"
	LabelCacheSizeLimit = LabelPrefix + "cache-size-limit"
	LabelName           = LabelPrefix + "name"
	LabelCreated        = LabelPrefix + "created-at"
)

// Labels returns the label set to stamp on a workload built from spec.
func (s *Spec) Labels(now time.Time) map[string]string {
	return map[string]string{
		LabelManaged:  "true",
		LabelRunnerID: s.RunnerID,
		LabelPoolID:   s.PoolID,
		LabelPoolName: s.PoolName,
		LabelName:     s.Name,
		LabelCreated:  now.UTC().Format(time.RFC3339),
	}
}

// Registry holds the backends an agent has available.
type Registry struct {
	backends map[store.BackendKind]Backend
}

// NewRegistry builds a registry from a list of backends.
func NewRegistry(bs ...Backend) *Registry {
	r := &Registry{backends: make(map[store.BackendKind]Backend, len(bs))}
	for _, b := range bs {
		if b != nil {
			r.backends[b.Kind()] = b
		}
	}
	return r
}

// Get returns the backend for a kind.
func (r *Registry) Get(k store.BackendKind) (Backend, error) {
	b, ok := r.backends[k]
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrUnavailable, k)
	}
	return b, nil
}

// Kinds returns the registered backend kinds.
func (r *Registry) Kinds() []store.BackendKind {
	out := make([]store.BackendKind, 0, len(r.backends))
	for k := range r.backends {
		out = append(out, k)
	}
	return out
}

// Probe reports on every registered backend.
func (r *Registry) Probe(ctx context.Context) []Info {
	out := make([]Info, 0, len(r.backends))
	for _, b := range r.backends {
		out = append(out, b.Probe(ctx))
	}
	return out
}

// Available returns the kinds whose daemon actually answered.
func (r *Registry) Available(ctx context.Context) []string {
	var out []string
	for _, i := range r.Probe(ctx) {
		if i.Available {
			out = append(out, string(i.Kind))
		}
	}
	return out
}

