// BuildCachePruner is optional: process and Podman backends do not expose
// Docker's builder cache API. This never prunes containers, images or volumes.
type BuildCachePruner interface {
	PruneBuildCache(context.Context, int64) (int64, error)
}

func (b *DockerBackend) PruneBuildCache(ctx context.Context, keepBytes int64) (int64, error) {
	if b.Kind() != store.BackendDocker || keepBytes <= 0 {
		return 0, nil
	}
	var response struct{ SpaceReclaimed int64 }
	err := b.api.do(ctx, http.MethodPost, "/build/prune", url.Values{
		"all": {"true"}, "keep-storage": {strconv.FormatInt(keepBytes, 10)},
	}, nil, &response)
	if err != nil {
		return 0, fmt.Errorf("pruning unused Docker builder cache: %w", err)
	}
	return response.SpaceReclaimed, nil
}

// json-file is readable by the existing log API. Rotation bounds logs even
// when a cancelled runner or its sidecar is waiting for a cleanup retry.
func runnerLogConfig(fl flavor) *LogConfig {
	if fl.kind != store.BackendDocker {
		return nil
	}
	return &LogConfig{Type: "json-file", Config: map[string]string{"max-size": "10m", "max-file": "3"}}
}

package backend

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"io/fs"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// cacheSource derives an isolated daemon volume or host directory without
// placing unchecked pool/repository values into it.
func cacheSource(spec Spec) (string, error) {
	c := spec.Cache
	if !c.Enabled {
		return "", nil
	}
	safe, err := cacheIdentity(spec)
	if err != nil {
		return "", err
	}
	prefix := strings.TrimSpace(c.Source)
	if strings.Contains(prefix, "..") {
		return "", fmt.Errorf("backend: unsafe cache source %q: path traversal is not allowed", prefix)
	}
	if prefix == "" {
		prefix = "zoomies-cache"
	}
	if filepath.IsAbs(prefix) {
		return filepath.Join(prefix, safe), nil
	}
	if strings.ContainsAny(prefix, `/\\:`) {
		return "", fmt.Errorf("backend: unsafe cache volume prefix %q", prefix)
	}
	return prefix + "-" + safe, nil
}

// cacheIdentity is the one name a pool's caches are kept under: the pool, or
// the pool and its repository for a repository-scoped cache. The pool cache
// and the tool cache share it, so the two are always shared with the same
// runners.
func cacheIdentity(spec Spec) (string, error) {
	c := spec.Cache
	if !c.Scope.Valid() {
		return "", fmt.Errorf("backend: %q is not a cache scope", c.Scope)
	}
	repo := ""
	if c.Scope == store.CacheScopeRepository {
		repo = strings.ToLower(strings.TrimSpace(firstNonEmpty(c.Repository, spec.Repository)))
		parts := strings.Split(repo, "/")
		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
			return "", fmt.Errorf("backend: a repository-scoped cache needs a repository as owner/name, and this pool has %q; set the pool's cache repository", repo)
		}
	}
	// A hostname is a readable prefix, not an identity: punctuation and long
	// repository names must never collapse different trust scopes together.
	raw, _ := json.Marshal([]string{"v2", string(c.Scope), spec.PoolID, repo})
	sum := sha256.Sum256(raw)
	prefix := sanitizeHostname(spec.PoolID + "-" + repo)
	if len(prefix) > 24 {
		prefix = prefix[:24]
	}
	safe := fmt.Sprintf("v2-%s-%x", strings.TrimRight(prefix, "-"), sum[:16])

	return safe, nil
}

// toolCacheDir is the host folder a pool's tool cache is kept in, under the
// host's shared folder: "" when the pool keeps none or the host has no shared
// folder to keep it in.
func toolCacheDir(spec Spec, sharedDir string) (string, error) {
	if !spec.Cache.Enabled || !spec.Cache.Tools || sharedDir == "" {
		return "", nil
	}
	safe, err := cacheIdentity(spec)
	if err != nil {
		return "", err
	}
	// Create and fill resolve the image first. Its immutable identity also
	// separates architecture and ABI, including custom images with no OS labels.
	image := sha256.Sum256([]byte(spec.Image))
	return filepath.Join(sharedDir, "cache", "tools", safe, fmt.Sprintf("image-%x", image[:16])), nil
}

// ensureRunnerWritableDir creates a host folder a runner is going to write to
// through a bind mount, open to every user when it is new.
//
// The runner is not the agent: in the stock images it is uid 1001, in a
// pool's own image whatever that image says, and the agent may be root or
// the controller container's 65532. A folder the daemon creates for a bind is
// root's, and a folder the agent creates is the agent's, and either leaves the
// runner unable to write a byte to its own cache. So a folder this creates is
// made writable by all; its parents stay as they are, and they are what keep
// anyone who is not the runner out. A folder that already exists is left
// exactly as its owner made it.
func ensureRunnerWritableDir(dir string) error {
	if _, err := os.Stat(dir); err == nil {
		return nil
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return err
	}
	return os.Chmod(dir, 0o777)
}

// stockRunnerUID is the runner account of the stock images, and the one owner
// besides "everyone" a tool cache folder can be writable to.
const stockRunnerUID = 1001

// runnerCannotWrite says why the runner could not write to dir, or "" when
// it can: the folder is open to everyone, or belongs to the stock images'
// runner. A pool's own image may run as another account; one that does and
// finds a folder of 1001's is the operator's own arrangement.
func runnerCannotWrite(dir string) string {
	fi, err := os.Stat(dir)
	if err != nil {
		return "cannot be read (" + err.Error() + ")"
	}
	if fi.Mode().Perm()&0o002 != 0 {
		return ""
	}
	if uid, _, ok := fileOwner(fi); ok {
		if uid == stockRunnerUID && fi.Mode().Perm()&0o200 != 0 {
			return ""
		}
		return fmt.Sprintf("belongs to uid %d with mode %#o, which the runner (uid %d) cannot write to", uid, fi.Mode().Perm(), stockRunnerUID)
	}
	return ""
}

// cacheDirectory returns the host directory a cache lives in, and whether there
// is one at all. A named daemon volume has no path this agent can measure: its
// bytes are the daemon's business, on a filesystem the agent may not even
// share. That is the whole reason a size limit is only accepted alongside an
// absolute cache source.
func cacheDirectory(spec Spec) (string, bool) {
	source, err := cacheSource(spec)
	if err != nil || source == "" || !filepath.IsAbs(source) {
		return "", false
	}
	return source, true
}

// pruneCache brings a cache directory back under its configured limit by
// deleting whole top-level entries, least recently modified first.
//
// This runs before a runner starts rather than on a timer, because a job
// holding a file open while we delete the directory under it is the failure the
// timing designs out. Starting is only half of that, and the caller owns the
// other half: on a pool that runs more than one runner the cache is busy at
// every start but the first, so pruneCacheFor asks whether anything else is
// using this cache before calling here. It is a ceiling on how far over the
// limit a host can drift, not a quota -- a single job can still fill a disk
// between two runners -- so the limit belongs to a cache the operator is
// willing to lose, which is what this cache is.
func pruneCache(dir string, limit int64, log *slog.Logger) {
	pruneCacheContext(context.Background(), dir, limit, log)
}

func pruneCacheContext(ctx context.Context, dir string, limit int64, log *slog.Logger) {
	if limit <= 0 {
		return
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		// A cache that does not exist yet is not over its limit; anything else
		// is worth saying once, because it means the limit is not being kept.
		if !os.IsNotExist(err) {
			log.Warn("could not read the cache directory to enforce its size limit",
				"dir", dir, "error", err)
		}
		return
	}
	type entry struct {
		name  string
		size  int64
		mtime int64
	}
	items := make([]entry, 0, len(entries))
	var total int64
	for _, e := range entries {
		size, mtime := treeSizeContext(ctx, filepath.Join(dir, e.Name()))
		if ctx.Err() != nil {
			return
		}
		items = append(items, entry{name: e.Name(), size: size, mtime: mtime})
		total += size
	}
	if total <= limit {
		return
	}
	// Oldest first, so the entry a job is most likely to want next survives
	// longest. Ties break by name to keep the order stable across hosts.
	sort.Slice(items, func(i, j int) bool {
		if items[i].mtime == items[j].mtime {
			return items[i].name < items[j].name
		}
		return items[i].mtime < items[j].mtime
	})
	freed, removed := int64(0), 0
	for _, it := range items {
		if ctx.Err() != nil || total-freed <= limit {
			break
		}
		if err := os.RemoveAll(filepath.Join(dir, it.name)); err != nil {
			log.Warn("could not evict a cache entry", "dir", dir, "entry", it.name, "error", err)
			continue
		}
		freed += it.size
		removed++
	}
	log.Info("evicted cache entries to stay under the pool's cache size limit",
		"dir", dir, "limit_bytes", limit, "was_bytes", total, "freed_bytes", freed, "entries", removed)
}

// treeSizeContext sums the apparent size of a directory tree and reports the
// newest modification time in it, so that touching one file inside a cache
// entry keeps the whole entry warm. It stops early once ctx is done.
func treeSizeContext(ctx context.Context, path string) (size int64, newest int64) {
	_ = filepath.WalkDir(path, func(_ string, d fs.DirEntry, err error) error {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if err != nil {
			// An entry that vanished mid-walk simply contributes nothing.
			return nil
		}
		info, err := d.Info()
		if err != nil {
			return nil
		}
		if mod := info.ModTime().UnixMilli(); mod > newest {
			newest = mod
		}
		if !d.IsDir() {
			size += info.Size()
		}
		return nil
	})
	return size, newest
}

package backend

import (
	"context"
	"github.com/eyupio/zoomies/internal/store"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestRepositoryCacheNamesPreserveDistinctIdentities(t *testing.T) {
	seen := map[string]string{}
	for _, repo := range []string{"acme/a.b", "acme/a-b", "acme/" + strings.Repeat("a", 100) + "x", "acme/" + strings.Repeat("a", 100) + "y"} {
		s := Spec{PoolID: "pool_one", Repository: repo, Cache: store.CacheConfig{Enabled: true, Scope: store.CacheScopeRepository}}
		name, err := cacheSource(s)
		if err != nil {
			t.Fatal(err)
		}
		if old := seen[name]; old != "" {
			t.Fatalf("%s aliases %s", repo, old)
		}
		seen[name] = repo
	}
}
func TestToolCacheGenerationsFollowTheResolvedImage(t *testing.T) {
	s := Spec{PoolID: "pool_one", Image: "sha256:first", Cache: store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}}
	a, _ := toolCacheDir(s, t.TempDir())
	s.Image = "sha256:second"
	b, _ := toolCacheDir(s, filepath.Dir(filepath.Dir(filepath.Dir(filepath.Dir(a)))))
	if filepath.Base(a) == filepath.Base(b) {
		t.Fatal("different images reuse a tool generation")
	}
}
func TestCancelledCacheMaintenanceDoesNotEvict(t *testing.T) {
	dir := t.TempDir()
	p := filepath.Join(dir, "blob")
	if err := os.WriteFile(p, []byte("oversized"), 0600); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	pruneCacheContext(ctx, dir, 1, quietLogger())
	if _, err := os.Stat(p); err != nil {
		t.Fatal("cancelled prune removed cache")
	}
}

