func TestAPIClientLogs(t *testing.T) {
	var framed bytes.Buffer
	framed.Write(frame(1, "job started\n"))
	framed.Write(frame(2, "npm WARN\n"))

	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/containers/framed/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, ContainerInspect{ID: "framed", Config: &ContainerConfig{Tty: false}, State: &ContainerState{Running: true}})
		},
		"GET " + v + "/containers/framed/logs": func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write(framed.Bytes())
		},
		"GET " + v + "/containers/tty/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, ContainerInspect{ID: "tty", Config: &ContainerConfig{Tty: true}, State: &ContainerState{Running: true}})
		},
		"GET " + v + "/containers/tty/logs": func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write([]byte("raw output\n"))
		},
		"GET " + v + "/containers/legacy/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, ContainerInspect{ID: "legacy", Config: &ContainerConfig{Tty: false}, State: &ContainerState{Running: true}})
		},
		"GET " + v + "/containers/legacy/logs": func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/vnd.docker.raw-stream")
			_, _ = w.Write(framed.Bytes())
		},
	})
	c := f.client(t)
	ctx := context.Background()

	t.Run("framed output is demultiplexed", func(t *testing.T) {
		rc, err := c.ContainerLogs(ctx, "framed", LogQuery{Follow: true, Tail: 20, Since: time.Unix(1700000000, 0)})
		if err != nil {
			t.Fatalf("logs: %v", err)
		}
		defer rc.Close()
		got, err := io.ReadAll(rc)
		if err != nil {
			t.Fatalf("read: %v", err)
		}
		if string(got) != "job started\nnpm WARN\n" {
			t.Fatalf("got %q", got)
		}
		q := f.request(http.MethodGet, v+"/containers/framed/logs").Form
		for k, want := range map[string]string{"stdout": "1", "stderr": "1", "follow": "1", "tail": "20", "since": "1700000000"} {
			if q.Get(k) != want {
				t.Fatalf("%s = %q, want %q (query %v)", k, q.Get(k), want, q)
			}
		}
	})

	t.Run("tty output passes through", func(t *testing.T) {
		rc, err := c.ContainerLogs(ctx, "tty", LogQuery{})
		if err != nil {
			t.Fatalf("logs: %v", err)
		}
		defer rc.Close()
		got, _ := io.ReadAll(rc)
		if string(got) != "raw output\n" {
			t.Fatalf("got %q", got)
		}
	})

	// Every daemon before API 1.42 labels a framed stream "raw-stream", and so
	// does Podman's compatibility endpoint. Taking that at its word left the
	// 8-byte frame headers in the log an operator downloaded.
	t.Run("a raw-stream label does not override a container without a TTY", func(t *testing.T) {
		rc, err := c.ContainerLogs(ctx, "legacy", LogQuery{})
		if err != nil {
			t.Fatalf("logs: %v", err)
		}
		defer rc.Close()
		got, err := io.ReadAll(rc)
		if err != nil {
			t.Fatalf("read: %v", err)
		}
		if string(got) != "job started\nnpm WARN\n" {
			t.Fatalf("got %q, want the demultiplexed output", got)
		}
	})

	t.Run("logs for a container that is gone", func(t *testing.T) {
		_, err := c.ContainerLogs(ctx, "nope", LogQuery{})
		if !errors.Is(err, ErrNotFound) {
			t.Fatalf("got %v, want ErrNotFound", err)
		}
	})
}

func TestAPIClientImages(t *testing.T) {
	pulls := 0
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/images/runner:1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]string{"Id": "sha256:abc"})
		},
		"GET " + v + "/images/absent:1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "No such image: absent:1"})
		},
		"POST " + v + "/images/create": func(w http.ResponseWriter, r *http.Request) {
			pulls++
			w.WriteHeader(http.StatusOK)
			flusher, _ := w.(http.Flusher)
			// Progress arrives in pieces; the client must drain all of it.
			for i := range 3 {
				_, _ = w.Write([]byte(`{"status":"Downloading","progressDetail":{"current":` + string(rune('1'+i)) + `}}` + "\n"))
				if flusher != nil {
					flusher.Flush()
				}
			}
			if r.Form.Get("fromImage") == "broken" {
				_, _ = w.Write([]byte(`{"errorDetail":{"message":"manifest unknown"},"error":"manifest unknown"}` + "\n"))
			}
		},
	})
	c := f.client(t)
	ctx := context.Background()

	t.Run("present", func(t *testing.T) {
		ok, err := c.ImageInspect(ctx, "runner:1")
		if err != nil || !ok {
			t.Fatalf("got %v %v", ok, err)
		}
	})

	t.Run("absent is not an error", func(t *testing.T) {
		ok, err := c.ImageInspect(ctx, "absent:1")
		if err != nil || ok {
			t.Fatalf("got %v %v", ok, err)
		}
	})

	t.Run("pull drains the progress stream", func(t *testing.T) {
		if err := c.ImagePull(ctx, "ghcr.io/acme/runner:2", ""); err != nil {
			t.Fatalf("pull: %v", err)
		}
		q := f.request(http.MethodPost, v+"/images/create").Form
		if q.Get("fromImage") != "ghcr.io/acme/runner" || q.Get("tag") != "2" {
			t.Fatalf("pull query = %v", q)
		}
		if pulls != 1 {
			t.Fatalf("pulls = %d", pulls)
		}
	})

	t.Run("an error inside the stream fails the pull", func(t *testing.T) {
		err := c.ImagePull(ctx, "broken", "")
		if err == nil || !strings.Contains(err.Error(), "manifest unknown") {
			t.Fatalf("got %v", err)
		}
	})
}

func TestAPIClientNetworkEnsure(t *testing.T) {
	created := 0
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/networks/existing": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]string{"Name": "existing"})
		},
		"GET " + v + "/networks/fresh": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "network fresh not found"})
		},
		"GET " + v + "/networks/raced": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "network raced not found"})
		},
		"POST " + v + "/networks/create": func(w http.ResponseWriter, r *http.Request) {
			var body map[string]any
			_ = json.NewDecoder(r.Body).Decode(&body)
			if body["Name"] == "raced" {
				writeJSON(w, http.StatusConflict, map[string]string{"message": "network with name raced already exists"})
				return
			}
			created++
			writeJSON(w, http.StatusCreated, map[string]string{"Id": "net-1"})
		},
	})
	c := f.client(t)
	ctx := context.Background()

	if err := c.NetworkEnsure(ctx, "existing"); err != nil {
		t.Fatalf("existing: %v", err)
	}
	if created != 0 {
		t.Fatal("an existing network must not be recreated")
	}
	if err := c.NetworkEnsure(ctx, "fresh"); err != nil {
		t.Fatalf("fresh: %v", err)
	}
	if created != 1 {
		t.Fatalf("created = %d", created)
	}
	// Two agents on one host may create the same network at the same moment.
	if err := c.NetworkEnsure(ctx, "raced"); err != nil {
		t.Fatalf("a lost race must not fail: %v", err)
	}
}

// A throttle reaches a running job through the update endpoint, and it has to
// send only the quota: a body that also carried a zero memory limit would be
// read by the daemon as a request to remove the memory limit altogether.
func TestAPIClientContainerUpdateSendsOnlyTheCPUQuota(t *testing.T) {
	var body map[string]any
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/c/update": func(w http.ResponseWriter, r *http.Request) {
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				t.Errorf("decoding the update body: %v", err)
			}
			writeJSON(w, http.StatusOK, map[string]any{"Warnings": []string{}})
		},
	})
	c := f.client(t)
	if err := c.ContainerUpdate(context.Background(), "c", UpdateConfig{NanoCPUs: 1_500_000_000}); err != nil {
		t.Fatalf("update: %v", err)
	}
	if got := body["NanoCpus"]; got != float64(1_500_000_000) {
		t.Fatalf("NanoCpus = %v, want 1.5 CPUs in nanoseconds", got)
	}
	if _, ok := body["Memory"]; ok {
		t.Fatal("the update named a memory limit, which the daemon would apply")
	}
	if len(body) != 1 {
		t.Fatalf("the update body carries more than the quota: %v", body)
	}
}

func TestAPIClientStats(t *testing.T) {
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"GET " + v + "/containers/c/stats": func(w http.ResponseWriter, r *http.Request) {
			if r.Form.Get("stream") != "false" {
				t.Errorf("stats must not stream, query %v", r.Form)
			}
			_, _ = w.Write([]byte(`{
			  "cpu_stats":{"cpu_usage":{"total_usage":200000000},"system_cpu_usage":2000000000,"online_cpus":2},
			  "precpu_stats":{"cpu_usage":{"total_usage":100000000},"system_cpu_usage":1000000000},
			  "memory_stats":{"usage":600,"limit":1000,"stats":{"inactive_file":100}}
			}`))
		},
	})
	c := f.client(t)

	got, err := c.ContainerStats(context.Background(), "c")
	if err != nil {
		t.Fatalf("stats: %v", err)
	}
	// 0.1s of CPU over 1s of system time on 2 CPUs is 20%.
	if got.CPUPercent < 19.9 || got.CPUPercent > 20.1 {
		t.Fatalf("cpu = %v, want ~20", got.CPUPercent)
	}
	if got.MemoryBytes != 500 {
		t.Fatalf("memory = %d, want 500 (page cache excluded)", got.MemoryBytes)
	}
	if got.MemoryLimit != 1000 {
		t.Fatalf("limit = %d", got.MemoryLimit)
	}
}

func TestSplitImageRef(t *testing.T) {
	cases := []struct{ ref, name, tag string }{
		{"runner", "runner", "latest"},
		{"runner:2.1", "runner", "2.1"},
		{"ghcr.io/acme/runner:2.1", "ghcr.io/acme/runner", "2.1"},
		{"registry:5000/acme/runner", "registry:5000/acme/runner", "latest"},
		{"registry:5000/acme/runner:dev", "registry:5000/acme/runner", "dev"},
		{"runner@sha256:abc", "runner", "sha256:abc"},
	}
	for _, c := range cases {
		name, tag := splitImageRef(c.ref)
		if name != c.name || tag != c.tag {
			t.Errorf("%s -> (%q, %q), want (%q, %q)", c.ref, name, tag, c.name, c.tag)
		}
	}
}

func TestParseDockerTime(t *testing.T) {
	if got := parseDockerTime("0001-01-01T00:00:00Z"); !got.IsZero() {
		t.Fatalf("docker's never should be the zero time, got %v", got)
	}
	if got := parseDockerTime(""); !got.IsZero() {
		t.Fatalf("empty should be the zero time, got %v", got)
	}
	if got := parseDockerTime("nonsense"); !got.IsZero() {
		t.Fatalf("unparseable should be the zero time, got %v", got)
	}
	got := parseDockerTime("2026-01-02T03:04:05.123456789Z")
	if got.Year() != 2026 || got.Minute() != 4 {
		t.Fatalf("got %v", got)
	}
}

// The daemon answers a stop only once the container is down or its grace
// period is over, so a stop that gives a job minutes to finish holds the
// request open for minutes. The transport's response-header timeout used to
// cut it off at 90 seconds and report "the daemon may be busy or stalled",
// which failed the runner as unexplained while the daemon carried on and
// killed the container anyway. A stop is bounded by its own grace period.
func TestAStopOutlastsTheResponseHeaderTimeout(t *testing.T) {
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"POST " + v + "/containers/slow/stop": func(w http.ResponseWriter, r *http.Request) {
			time.Sleep(300 * time.Millisecond)
			w.WriteHeader(http.StatusNoContent)
		},
		"GET " + v + "/containers/slow/json": func(w http.ResponseWriter, r *http.Request) {
			time.Sleep(300 * time.Millisecond)
			writeJSON(w, 200, &ContainerInspect{ID: "slow"})
		},
	})
	c := f.client(t)
	c.http.Transport.(*http.Transport).ResponseHeaderTimeout = 50 * time.Millisecond
	if err := c.ContainerStop(context.Background(), "slow", 5*time.Second); err != nil {
		t.Fatalf("a stop answered after its grace period's work failed: %v", err)
	}
	// Every other call keeps the timeout: a daemon that does not answer an
	// inspect is one that is stalled.
	if _, err := c.ContainerInspect(context.Background(), "slow"); err == nil {
		t.Fatal("an ordinary call outlived the response-header timeout")
	}
}

func TestARemoveOutlastsTheResponseHeaderTimeout(t *testing.T) {
	// Docker answers a DELETE only when the removal is over, and a sidecar's
	// nested image store can take longer than the header timeout to delete.
	// Giving up then abandoned a removal the daemon went on to finish, and the
	// next attempt was refused as "already in progress".
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"DELETE " + v + "/containers/slow": func(w http.ResponseWriter, r *http.Request) {
			time.Sleep(300 * time.Millisecond)
			w.WriteHeader(http.StatusNoContent)
		},
	})
	c := f.client(t)
	c.http.Transport.(*http.Transport).ResponseHeaderTimeout = 50 * time.Millisecond
	if err := c.ContainerRemove(context.Background(), "slow", true); err != nil {
		t.Fatalf("a removal that took longer than the header timeout was abandoned: %v", err)
	}
}

func TestADeadlineBeforeTheRequestWasSentIsNotARemovalUnderWay(t *testing.T) {
	// A dial that timed out is a daemon that never heard of the removal, and
	// telling an operator it was still at it would send them to wait for
	// work nobody is doing. Only a request the daemon has is one it finishes.
	unreached := &url.Error{Op: "Delete", URL: "http://docker/containers/x", Err: &net.OpError{Op: "dial", Err: context.DeadlineExceeded}}
	if removalUnderWay(unreached, false) {
		t.Fatal("a DELETE that never reached the daemon was read as a removal under way")
	}
	if !removalUnderWay(unreached, true) {
		t.Fatal("a DELETE the daemon had when its deadline passed must read as a removal under way")
	}
}

func TestARemoveTellsARemovalUnderWayFromARefusal(t *testing.T) {
	for _, tc := range []struct {
		name       string
		status     int
		message    string
		inProgress bool
	}{
		{"docker's own words", http.StatusConflict, "removal of container runner-1-dind is already in progress", true},
		{"a conflict of another kind", http.StatusConflict, "sidecar is in use", false},
		{"a daemon error", http.StatusInternalServerError, "removal of container runner-1-dind is already in progress", false},
		{"gone", http.StatusNotFound, "no such container", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f := newFakeEngine(t, map[string]http.HandlerFunc{
				"DELETE " + v + "/containers/runner-1-dind": func(w http.ResponseWriter, r *http.Request) {
					writeJSON(w, tc.status, map[string]string{"message": tc.message})
				},
			})
			err := f.client(t).ContainerRemove(context.Background(), "runner-1-dind", true)
			if got := errors.Is(err, ErrRemovalInProgress); got != tc.inProgress {
				t.Fatalf("removal in progress = %v, want %v (%v)", got, tc.inProgress, err)
			}
			if tc.inProgress && !errors.Is(err, ErrDaemonBusy) {
				t.Fatalf("a removal in progress is a busy daemon, not a refusing one: %v", err)
			}
			// The operator still reads the daemon's own sentence.
			if !strings.Contains(err.Error(), tc.message) {
				t.Fatalf("the daemon's words were lost: %v", err)
			}
		})
	}
}

func TestARemoveWhoseDeadlinePassesIsARemovalUnderWay(t *testing.T) {
	// The daemon has the request, and does not stop because we did.
	release := make(chan struct{})
	t.Cleanup(func() { close(release) })
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"DELETE " + v + "/containers/slow": func(w http.ResponseWriter, r *http.Request) {
			select {
			case <-release:
			case <-r.Context().Done():
			}
		},
	})
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	err := f.client(t).ContainerRemove(ctx, "slow", true)
	if !errors.Is(err, ErrRemovalInProgress) || !errors.Is(err, ErrDaemonBusy) {
		t.Fatalf("a DELETE cut off by its deadline = %v, want a removal still in progress", err)
	}

	// A caller that gave up is not the daemon still working.
	cctx, ccancel := context.WithCancel(context.Background())
	go func() { time.Sleep(50 * time.Millisecond); ccancel() }()
	if err := f.client(t).ContainerRemove(cctx, "slow", true); errors.Is(err, ErrRemovalInProgress) {
		t.Fatalf("a cancelled DELETE was read as a removal under way: %v", err)
	}
}

package backend

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestRunnerRequiresDockerReadinessBeforeStartingItsListener(t *testing.T) {
	bash, err := exec.LookPath("bash")
	if err != nil {
		t.Skip("bash is not installed")
	}
	if _, err := exec.LookPath("timeout"); err != nil {
		t.Skip("coreutils timeout is not installed")
	}
	source, err := os.ReadFile("../../deploy/runner-entrypoint.sh")
	if err != nil {
		t.Fatal(err)
	}
	// The exit codes are part of the contract: the agent turns 69 and 78 into
	// a sentence on the Runners page, so a change here must change
	// entrypointExitHint with it.
	for _, tc := range []struct {
		name    string
		docker  string
		wait    string
		started bool
		exit    int
	}{
		{"ready", "exit 0", "30", true, 0},
		{"unavailable", "exit 1", "1", false, 69},
		{"hung probe", "exec sleep 30", "1", false, 69},
		{"invalid wait", "exit 0", "invalid", false, 78},
		{"zero wait", "exit 0", "0", false, 78},
		{"leading zero", "exit 0", "08", true, 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			write := func(name, body string) {
				t.Helper()
				if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o700); err != nil {
					t.Fatal(err)
				}
			}
			// Only relocate the fixed image work directory. Execute the actual
			// entrypoint logic, with a stub listener and no GitHub credentials.
			write("entrypoint.sh", strings.Replace(string(source), "cd /home/runner", "cd \"$TEST_RUNNER_HOME\"", 1))
			write("docker", "#!/usr/bin/env bash\n"+tc.docker+"\n")
			write("run.sh", "#!/usr/bin/env bash\ntouch listener-started\n")
			// The bound has to sit under the hung probe's thirty-second sleep,
			// or it proves nothing about the wait being bounded, and well above
			// the time the script takes when nothing is wrong. Five seconds was
			// under the second on a Windows runner, where starting bash and the
			// stub processes alone took nine, so a ready daemon failed as
			// "not bounded" on unrelated changes.
			ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, bash, filepath.Join(dir, "entrypoint.sh"))
			cmd.Env = append(os.Environ(), "PATH="+dir+string(os.PathListSeparator)+os.Getenv("PATH"),
				"TEST_RUNNER_HOME="+dir, "DOCKER_HOST=tcp://127.0.0.1:2375",
				"ZOOMIES_DOCKER_WAIT="+tc.wait, "ZOOMIES_JITCONFIG=test-only")
			out, err := cmd.CombinedOutput()
			if ctx.Err() != nil {
				t.Fatalf("readiness was not bounded: %s", out)
			}
			_, statErr := os.Stat(filepath.Join(dir, "listener-started"))
			if (statErr == nil) != tc.started || (err == nil) != tc.started {
				t.Fatalf("listener started=%v, exit=%v, want started=%v: %s", statErr == nil, err, tc.started, out)
			}
			if code := cmd.ProcessState.ExitCode(); code != tc.exit {
				t.Fatalf("exit code = %d, want %d: %s", code, tc.exit, out)
			}
		})
	}
}

