// A host behind a TLS-intercepting proxy hands its runners the proxy's CA.
// The runner needs the file where the entrypoint looks for it, and read-only,
// because the source is the host's file and a job must not write through it
// to what every later runner on the host trusts.
func TestARunnerIsGivenTheHostsExtraCAReadOnly(t *testing.T) {
	o := containerOptions{Now: time.Now(), ExtraCAFile: "/etc/acme/proxy-ca.pem"}
	spec := jitSpec()
	spec.Env = map[string]string{EnvExtraCAFile: "/somewhere/else"}
	cfg := buildRunnerConfig(spec, dockerFlavor(), o)

	if !slices.Contains(cfg.HostConfig.Binds, "/etc/acme/proxy-ca.pem:"+ExtraCAPath+":ro") {
		t.Fatalf("binds = %v, want the CA mounted read-only at %s", cfg.HostConfig.Binds, ExtraCAPath)
	}
	// A pool's env comes earlier, so the mount's path is the one that wins.
	if got := envMap(cfg.Env)[EnvExtraCAFile]; got != ExtraCAPath {
		t.Fatalf("%s = %q, want %q", EnvExtraCAFile, got, ExtraCAPath)
	}
}

func TestPodmanRelabelsTheExtraCAMount(t *testing.T) {
	o := containerOptions{Now: time.Now(), ExtraCAFile: "/etc/acme/proxy-ca.pem"}
	cfg := buildRunnerConfig(jitSpec(), podmanFlavor(), o)
	if !slices.Contains(cfg.HostConfig.Binds, "/etc/acme/proxy-ca.pem:"+ExtraCAPath+":ro,z") {
		t.Fatalf("binds = %v, want a read-only relabelled mount", cfg.HostConfig.Binds)
	}
}

// Nothing changes for a host that did not ask: the setting is new, and an
// upgrade must leave every existing runner's container exactly as it was.
func TestARunnerWithoutAnExtraCAGetsNoMountAndNoVariable(t *testing.T) {
	cfg := buildRunnerConfig(jitSpec(), dockerFlavor(), containerOptions{Now: time.Now()})
	for _, b := range cfg.HostConfig.Binds {
		if strings.Contains(b, ExtraCADir) {
			t.Fatalf("unexpected CA mount %q", b)
		}
	}
	if _, ok := envMap(cfg.Env)[EnvExtraCAFile]; ok {
		t.Fatalf("%s set with no extra CA configured", EnvExtraCAFile)
	}
	dind := buildDinDConfig(jitSpec(), dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage})
	if _, ok := envMap(dind.Env)["SSL_CERT_DIR"]; ok {
		t.Fatal("the sidecar's SSL_CERT_DIR was set with no extra CA configured")
	}
}

// The sidecar is what pulls a dind job's images, so it must trust the proxy
// too, and it must keep the image's own roots while it does.
func TestTheDockerSidecarTrustsTheExtraCAAlongsideItsOwnRoots(t *testing.T) {
	spec := jitSpec()
	spec.DockerMode = store.DockerDinD
	cfg := buildDinDConfig(spec, dockerFlavor(), containerOptions{Now: time.Now(), DinDImage: DefaultDinDImage, ExtraCAFile: "/etc/acme/proxy-ca.pem"})
	if !slices.Contains(cfg.HostConfig.Binds, "/etc/acme/proxy-ca.pem:"+ExtraCAPath+":ro") {
		t.Fatalf("binds = %v", cfg.HostConfig.Binds)
	}
	if got := envMap(cfg.Env)["SSL_CERT_DIR"]; got != "/etc/ssl/certs:"+ExtraCADir {
		t.Fatalf("SSL_CERT_DIR = %q", got)
	}
}

// The entrypoint is the other half: run the real script with stubbed trust
// store tools and check the CA reaches the store and the listener's
// environment before the listener starts.
func TestTheEntrypointTrustsTheExtraCABeforeStartingItsListener(t *testing.T) {
	bash, err := exec.LookPath("bash")
	if err != nil {
		t.Skip("bash is not installed")
	}
	source, err := os.ReadFile("../../deploy/runner-entrypoint.sh")
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name    string
		ca      bool // write the CA file the variable names
		setVar  bool
		exit    int
		trusted bool
	}{
		{"trusted", true, true, 0, true},
		{"unreadable", false, true, 78, false},
		{"not configured", false, false, 0, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			anchors := filepath.Join(dir, "anchors")
			if err := os.Mkdir(anchors, 0o700); err != nil {
				t.Fatal(err)
			}
			write := func(name, body string) {
				t.Helper()
				if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o700); err != nil {
					t.Fatal(err)
				}
			}
			script := strings.Replace(string(source), "cd /home/runner", "cd \"$TEST_RUNNER_HOME\"", 1)
			script = strings.Replace(script, "apt_anchors=/usr/local/share/ca-certificates", "apt_anchors=\"$TEST_RUNNER_HOME/anchors\"", 1)
			script = strings.Replace(script, "apt_bundle=/etc/ssl/certs/ca-certificates.crt", "apt_bundle=\"$TEST_RUNNER_HOME/bundle.crt\"", 1)
			write("entrypoint.sh", script)
			write("sudo", "#!/usr/bin/env bash\n[ \"$1\" = -n ] && shift\nexec \"$@\"\n")
			write("update-ca-certificates", "#!/usr/bin/env bash\ntouch \"$TEST_RUNNER_HOME/store-updated\"\n")
			write("run.sh", "#!/usr/bin/env bash\nenv > listener-env\n")
			ca := filepath.Join(dir, "proxy-ca.pem")
			if tc.ca {
				write("proxy-ca.pem", "-----BEGIN CERTIFICATE-----\n")
			}

			ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, bash, filepath.Join(dir, "entrypoint.sh"))
			cmd.Env = append(os.Environ(), "PATH="+dir+string(os.PathListSeparator)+os.Getenv("PATH"),
				"TEST_RUNNER_HOME="+dir, "ZOOMIES_JITCONFIG=test-only",
				// Empty counts as unset to the script; the machine running
				// the test may well have set these for its own proxy.
				"REQUESTS_CA_BUNDLE=", "SSL_CERT_FILE=", "NODE_EXTRA_CA_CERTS=")
			if tc.setVar {
				cmd.Env = append(cmd.Env, EnvExtraCAFile+"="+ca)
			}
			out, _ := cmd.CombinedOutput()
			if code := cmd.ProcessState.ExitCode(); code != tc.exit {
				t.Fatalf("exit code = %d, want %d: %s", code, tc.exit, out)
			}
			env, envErr := os.ReadFile(filepath.Join(dir, "listener-env"))
			if tc.exit != 0 {
				if envErr == nil {
					t.Fatalf("the listener started without its CA: %s", out)
				}
				return
			}
			_, copyErr := os.Stat(filepath.Join(anchors, "zoomies-extra-ca.crt"))
			_, storeErr := os.Stat(filepath.Join(dir, "store-updated"))
			if (copyErr == nil) != tc.trusted || (storeErr == nil) != tc.trusted {
				t.Fatalf("copied=%v store updated=%v, want %v: %s", copyErr == nil, storeErr == nil, tc.trusted, out)
			}
			for _, want := range []string{"NODE_EXTRA_CA_CERTS=" + ca, // The script joins with a slash whatever the platform, so
				// that is what it hands the listener -- filepath.Join would
				// write a backslash on Windows and expect something else.
				"REQUESTS_CA_BUNDLE=" + dir + "/bundle.crt"} {
				if strings.Contains(string(env), want+"\n") != tc.trusted {
					t.Fatalf("listener env has %q = %v, want %v", want, !tc.trusted, tc.trusted)
				}
			}
		})
	}
}

package backend

import (
	"errors"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// The categories a backend failure can be, as sentinels a caller matches with
// errors.Is. They are wrapped in at the point the answer is known -- inside the
// call that got the daemon's reply -- and never guessed at above it, because by
// the time an error has been reworded twice on its way to the controller the
// only evidence left is prose.
var (
	ErrContainerConflict = errors.New("backend: container name conflict could not be safely recovered")
	// ErrImageUnavailable is a runner image that could not be made ready: a tag
	// that is not there, a registry that refused the credential, a digest that
	// does not resolve. It is kept apart from ErrDaemon because the fix is in a
	// different place -- the pool's image, or the host's access to a registry,
	// rather than the daemon itself.
	ErrImageUnavailable = errors.New("backend: the runner image could not be made ready")
	// ErrDaemon is the container backend refusing the work or not answering.
	// This is the "cannot start the runner container" case, and on a fleet
	// where it is happening it is happening to every runner in the pool.
	ErrDaemon = errors.New("backend: the container backend would not do that")
	// ErrDaemonBusy is a daemon that is there and did not answer in time. It
	// is kept apart from ErrDaemon because the two send an operator to
	// different places: a socket that is not there is fixed on the host, and
	// a daemon that took too long to answer a create is a host carrying more
	// work than it can keep up with -- dockerd, containerd and the agent
	// answer in the gaps the runners' quotas leave, and on an oversubscribed
	// machine there are none. Told to check whether the daemon is running,
	// an operator finds it running and concludes the fleet is lying to them.
	ErrDaemonBusy = errors.New("backend: the container backend did not answer in time")
	// ErrRemovalInProgress is a removal the daemon has under way and has not
	// finished: a DELETE refused because another one is still being carried
	// out, or one whose caller's deadline passed while the daemon was working
	// on it. Neither is a removal that failed -- Docker finishes a removal it
	// has started whether or not anyone is still waiting for it -- and the
	// agent tells the two apart so that a slow removal is waited out rather
	// than reported as something left behind. It always travels with
	// ErrDaemonBusy, so its fault is the busy one.
	ErrRemovalInProgress = errors.New("backend: the container backend is still removing this container")
)

// noSpace is the daemon's own words for a full disk, and the only evidence
// there is for it: Docker reports it as an ordinary 500 with this in the
// message. Matching here rather than in the controller is the point -- this is
// the package holding the daemon's reply, and a controller matching on prose
// would be matching on a sentence three layers of wrapping had already
// rewritten.
const noSpace = "no space left on device"

// imageErr and daemonErr attach a category to an error without adding a word
// to what it says. The sentence an operator reads stays the daemon's own --
// "manifest unknown", "permission denied" -- and the category rides alongside
// it for the code. Wrapping the sentinel into the message instead would give
// every one of these two prefixes and say nothing new in the second.
func imageErr(err error) error  { return tagged{err: err, kind: ErrImageUnavailable} }
func daemonErr(err error) error { return tagged{err: err, kind: ErrDaemon} }
func busyErr(err error) error   { return tagged{err: err, kind: ErrDaemonBusy} }

// removingErr is busyErr with the one thing a caller can do about it attached:
// wait, because the daemon is still doing the work.
func removingErr(err error) error {
	return tagged{err: busyErr(err), kind: ErrRemovalInProgress}
}

type tagged struct{ err, kind error }

func (t tagged) Error() string   { return t.err.Error() }
func (t tagged) Unwrap() []error { return []error{t.err, t.kind} }

// Fault categorises a backend error for the fleet's failure taxonomy.
//
// An error it cannot place is FaultBackend rather than the unclassified kind:
// everything that reaches here came from the backend, so "the container
// backend would not do that" is true even when nothing narrower is. The
// unclassified kind is for a runner that stopped for reasons nobody observed,
// which is a different admission.
func Fault(err error) store.FaultKind {
	switch {
	case err == nil:
		return ""
	case strings.Contains(strings.ToLower(err.Error()), noSpace):
		return store.FaultOutOfDisk
	case errors.Is(err, ErrContainerConflict):
		return store.FaultContainerConflict
	case errors.Is(err, ErrImageUnavailable):
		return store.FaultImage
	case errors.Is(err, ErrDaemonBusy):
		return store.FaultBackendBusy
	}
	return store.FaultBackend
}

package backend

import (
	"context"
	"errors"
	"fmt"
	"net"
	"strings"
	"syscall"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// timeoutError is what net/http hands back when the daemon accepted the
// connection and never answered: the shape the real failure arrives in.
type timeoutError struct{}

func (timeoutError) Error() string   { return "net/http: timeout awaiting response headers" }
func (timeoutError) Timeout() bool   { return true }
func (timeoutError) Temporary() bool { return true }

var _ net.Error = timeoutError{}

// A daemon that did not answer in time is not a daemon that is missing, and
// the fleet has to say which. An operator sent to "check whether the daemon is
// running" finds it running, finds the socket where the agent said it was, and
// learns to stop reading the fix line -- while the machine that is actually
// oversubscribed goes on failing every create.
func TestADaemonThatTimesOutIsNotADaemonThatIsMissing(t *testing.T) {
	c := &APIClient{host: "unix:///var/run/docker.sock"}

	stalled := c.unavailable(timeoutError{})
	if got := Fault(stalled); got != store.FaultBackendBusy {
		t.Fatalf("a timeout classified as %q, want %q", got, store.FaultBackendBusy)
	}
	// It stays an unavailable backend for everything that already matched on
	// that: the category rides alongside the sentinel rather than replacing it.
	if !errors.Is(stalled, ErrUnavailable) {
		t.Error("a timeout stopped being ErrUnavailable, which every caller that retries matches on")
	}
	if !errors.Is(stalled, ErrDaemonBusy) {
		t.Error("a timeout is not tagged ErrDaemonBusy")
	}
	// And the sentence is still the daemon's own, with nothing added: the tag
	// is for the code.
	if want := "did not answer in time"; !strings.Contains(stalled.Error(), want) {
		t.Errorf("the message lost %q: %s", want, stalled)
	}

	// The failures that really are a backend to go and fix stay where they
	// were, or the new category would swallow the old one.
	for name, err := range map[string]error{
		"no socket":         c.unavailable(fmt.Errorf("dial: %w", syscall.ENOENT)),
		"nothing listening": c.unavailable(fmt.Errorf("dial: %w", syscall.ECONNREFUSED)),
		"permission denied": c.unavailable(fmt.Errorf("dial: %w", syscall.EACCES)),
	} {
		if got := Fault(err); got != store.FaultBackend {
			t.Errorf("%s classified as %q, want %q", name, got, store.FaultBackend)
		}
	}

	// A cancelled request is the controller or the operator giving up, not the
	// host being overloaded, so it must not read as either.
	if got := Fault(c.unavailable(context.Canceled)); got != store.FaultBackend {
		t.Errorf("a cancelled request classified as %q, want %q", got, store.FaultBackend)
	}

	// A full disk still wins: the daemon answered, and what it said is the
	// only evidence there is for it.
	full := busyErr(errors.New("no space left on device"))
	if got := Fault(full); got != store.FaultOutOfDisk {
		t.Errorf("a full disk classified as %q, want %q", got, store.FaultOutOfDisk)
	}
}

//go:build ignore

// Command gen_runner_digests writes runner_digests.go from the digests GitHub
// publishes for an actions/runner release.
//
// The process backend refuses to install a runner archive it cannot verify,
// so the release Zoomies pins by default has to ship with its digests. Every
// actions/runner release lists them in its notes, between HTML comments of the
// form <!-- BEGIN SHA linux-x64 --> ... <!-- END SHA linux-x64 -->, and this
// command copies the ones for the platforms the process backend supports into
// Go source. The version bump workflow runs it so the table cannot lag the
// version.
//
// Run it from the repository root, with the version DefaultRunnerVersion pins:
//
//	go run internal/backend/gen_runner_digests.go 2.337.0
//
// -body reads a saved copy of the release notes instead of asking GitHub,
// for a host without access to api.github.com.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"sort"
	"strings"
)

const target = "internal/backend/runner_digests.go"

// platforms are the archives runnerAsset in process.go can name.
var platforms = []string{"linux-x64", "linux-arm64", "linux-arm", "osx-x64", "osx-arm64", "win-x64", "win-arm64"}

// assetExt is the archive format each platform is published in; runnerAsset
// makes the same choice.
func assetExt(platform string) string {
	if strings.HasPrefix(platform, "win-") {
		return ".zip"
	}
	return ".tar.gz"
}

var shaBlock = regexp.MustCompile(`<!-- BEGIN SHA ([A-Za-z0-9-]+) -->\s*([0-9a-fA-F]{64})\s*<!-- END SHA `)

func main() {
	bodyFile := flag.String("body", "", "a file holding the release notes, instead of fetching them")
	flag.Parse()
	if flag.NArg() != 1 {
		fmt.Fprintln(os.Stderr, "usage: go run internal/backend/gen_runner_digests.go [-body notes.md] <version>")
		os.Exit(2)
	}
	version := strings.TrimPrefix(flag.Arg(0), "v")

	var body string
	var err error
	if *bodyFile != "" {
		body, err = readFile(*bodyFile)
	} else {
		body, err = fetchReleaseBody(version)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	found := map[string]string{}
	for _, m := range shaBlock.FindAllStringSubmatch(body, -1) {
		found[m[1]] = strings.ToLower(m[2])
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by gen_runner_digests.go; DO NOT EDIT.\n//\n")
	fmt.Fprintf(&b, "// Regenerate after bumping DefaultRunnerVersion:\n//\n")
	fmt.Fprintf(&b, "//\tgo run internal/backend/gen_runner_digests.go %s\n\n", version)
	fmt.Fprintf(&b, "package backend\n\n")
	fmt.Fprintf(&b, "// knownRunnerSHA256 holds the SHA-256 of every actions/runner archive the\n")
	fmt.Fprintf(&b, "// process backend can install for DefaultRunnerVersion, keyed\n")
	fmt.Fprintf(&b, "// \"<version>/<asset file name>\". The values are the ones GitHub publishes in\n")
	fmt.Fprintf(&b, "// the release notes, so a download that does not match them is refused rather\n")
	fmt.Fprintf(&b, "// than executed.\n")
	fmt.Fprintf(&b, "var knownRunnerSHA256 = map[string]string{\n")
	keys := make([]string, 0, len(platforms))
	width := 0
	for _, p := range platforms {
		if _, ok := found[p]; !ok {
			fmt.Fprintf(os.Stderr, "the release notes for %s carry no SHA-256 for %s\n", version, p)
			os.Exit(1)
		}
		k := fmt.Sprintf("%s/actions-runner-%s-%s%s", version, p, version, assetExt(p))
		keys = append(keys, k)
		width = max(width, len(k))
	}
	sort.Strings(keys)
	for _, k := range keys {
		platform := strings.TrimPrefix(k, version+"/actions-runner-")
		platform = platform[:strings.LastIndex(platform, "-"+version+".")]
		fmt.Fprintf(&b, "\t%-*s %q,\n", width+3, fmt.Sprintf("%q:", k), found[platform])
	}
	fmt.Fprintf(&b, "}\n")

	if err := os.WriteFile(target, []byte(b.String()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("wrote %s for actions/runner %s (%d archives)\n", target, version, len(keys))
}

func readFile(path string) (string, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// fetchReleaseBody asks GitHub for the release notes. GITHUB_TOKEN, when set,
// lifts the anonymous rate limit, which matters in a workflow.
func fetchReleaseBody(version string) (string, error) {
	req, err := http.NewRequest(http.MethodGet, "https://api.github.com/repos/actions/runner/releases/tags/v"+version, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	if tok := os.Getenv("GITHUB_TOKEN"); tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("fetching the v%s release: %s", version, resp.Status)
	}
	var release struct {
		Body string `json:"body"`
	}
	if err := json.NewDecoder(io.LimitReader(resp.Body, 4<<20)).Decode(&release); err != nil {
		return "", err
	}
	return release.Body, nil
}

package backend

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path"
	"strconv"
	"strings"
)

// A containerised agent hands the host's daemon host paths: a runner's cache
// is bound from the shared folder by the path the agent sees it at, and the
// daemon resolves that path on the host. That is only the same folder when
// the agent's container mounts it from the host at that very path. When it
// does not -- a Compose file from before the shared folder existed -- the
// folder the agent creates is inside its own data volume, the daemon creates
// an empty one on the host owned by root, and a runner handed it as its tool
// cache cannot write to it: every setup action that downloads fails.
//
// So a containerised agent checks, and leaves the tool cache off with a
// reason rather than hand out a folder the daemon cannot see.

// containerMarkers are the files a container runtime leaves at the root of a
// container: Docker's and Podman's.
var containerMarkers = []string{"/.dockerenv", "/run/.containerenv"}

// runningInContainer is InContainer, a variable so a test can describe a
// container from a machine that is not one.
var runningInContainer = InContainer

// InContainer reports whether this process runs inside a container.
func InContainer() bool {
	for _, m := range containerMarkers {
		if _, err := os.Stat(m); err == nil {
			return true
		}
	}
	return false
}

// IsMountPoint reports whether dir is itself a mount point in this process's
// mount namespace -- a bind from the host, not a folder inside another mount.
// It is false where /proc cannot say, which is every system but Linux.
func IsMountPoint(dir string) bool {
	f, err := os.Open("/proc/self/mountinfo")
	if err != nil {
		return false
	}
	defer f.Close()
	return mountPoints(f)[path.Clean(dir)]
}

// mountPoints reads /proc/self/mountinfo: the fifth field of each line is
// the mount point, with spaces and the like written as octal escapes.
func mountPoints(r io.Reader) map[string]bool {
	out := map[string]bool{}
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) < 5 {
			continue
		}
		out[path.Clean(unescapeMount(f[4]))] = true
	}
	return out
}

func unescapeMount(s string) string {
	if !strings.Contains(s, `\`) {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+3 < len(s) {
			if n, err := strconv.ParseUint(s[i+1:i+4], 8, 8); err == nil {
				b.WriteByte(byte(n))
				i += 3
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// SharedFolderProblem says why the shared folder at dir cannot be handed to
// the host's daemon, or "" when it can: this process is in a container and the
// folder is not mounted into it from the host at its own path.
func SharedFolderProblem(dir string, inContainer bool, isMount func(string) bool) string {
	if !inContainer || isMount(dir) {
		return ""
	}
	return fmt.Sprintf("the shared folder %s is not mounted into this container from the host, so the host's daemon cannot see what is in it; pools' tool caches are off here until it is. "+
		"Add `- %s:%s` to the zoomies service's volumes (or `--volume %s:%s` to its docker run), or run `zoomies upgrade --yes` on the host, which adds it", dir, dir, dir, dir, dir)
}

package backend

import (
	"errors"
	"strings"
	"testing"
)

func TestMountPointsReadsTheFifthFieldOfMountinfo(t *testing.T) {
	info := strings.Join([]string{
		`36 35 98:0 /mnt1 / rw,noatime master:1 - ext3 /dev/root rw,errors=continue`,
		`812 790 0:52 /volumes/zoomies-data/_data /var/lib/zoomies rw,relatime - ext4 /dev/vda rw`,
		`813 812 0:52 /srv/shared /var/lib/zoomies/shared rw,relatime - ext4 /dev/vda rw`,
		`900 790 0:60 / /mnt/with\040space rw - tmpfs tmpfs rw`,
	}, "\n")
	got := mountPoints(strings.NewReader(info))
	for _, want := range []string{"/", "/var/lib/zoomies", "/var/lib/zoomies/shared", "/mnt/with space"} {
		if !got[want] {
			t.Errorf("%s is not a mount point in %v", want, got)
		}
	}
	if got["/var/lib/zoomies/work"] {
		t.Error("a folder inside a mount was read as a mount of its own")
	}
}

// Outside a container the folder is the host's by definition; inside one it
// is only the host's when it is mounted from there.
func TestSharedFolderProblemOnlyInAContainerThatDoesNotMountIt(t *testing.T) {
	mounted := func(string) bool { return true }
	unmounted := func(string) bool { return false }
	if p := SharedFolderProblem("/var/lib/zoomies/shared", false, unmounted); p != "" {
		t.Errorf("outside a container: %q", p)
	}
	if p := SharedFolderProblem("/var/lib/zoomies/shared", true, mounted); p != "" {
		t.Errorf("mounted in a container: %q", p)
	}
	p := SharedFolderProblem("/var/lib/zoomies/shared", true, unmounted)
	for _, want := range []string{"not mounted into this container", "- /var/lib/zoomies/shared:/var/lib/zoomies/shared", "zoomies upgrade --yes"} {
		if !strings.Contains(p, want) {
			t.Errorf("problem %q does not say %q", p, want)
		}
	}
}

// An older Compose file can lack the socket mount altogether. Inside a
// container that is not a daemon to install -- the advice outside one -- but a
// mount to add, and the detail the Hosts page shows says which.
func TestAMissingSocketInAContainerIsAMissingMount(t *testing.T) {
	requirePOSIX(t)
	was := runningInContainer
	runningInContainer = func() bool { return true }
	t.Cleanup(func() { runningInContainer = was })
	sock := t.TempDir() + "/docker.sock"
	b, err := NewDocker(DockerOptions{Host: "unix://" + sock, Logger: quietLogger()})
	if err != nil {
		t.Fatal(err)
	}
	detail := b.unreachableDetail(errors.New("dial unix: no such file"))
	for _, want := range []string{"inside this container", "- " + sock + ":" + sock, "zoomies upgrade --yes"} {
		if !strings.Contains(detail, want) {
			t.Errorf("detail %q does not say %q", detail, want)
		}
	}
}

//go:build !unix

package backend

import "io/fs"

// fileOwner has no answer off unix, where a folder has no owning uid for a
// Linux runner to be refused by.
func fileOwner(fs.FileInfo) (uid, gid int, ok bool) { return 0, 0, false }

//go:build unix

package backend

import (
	"io/fs"
	"syscall"
)

// fileOwner reads a file's uid and gid.
func fileOwner(fi fs.FileInfo) (uid, gid int, ok bool) {
	st, ok := fi.Sys().(*syscall.Stat_t)
	if !ok {
		return 0, 0, false
	}
	return int(st.Uid), int(st.Gid), true
}

package backend

// Why a socket that exists cannot be opened.
//
// "permission denied on /var/run/docker.sock; add your user to the docker group
// (sudo usermod -aG docker $USER, then log in again)" is true often enough to be
// dangerous. $USER is the operator's login shell, not the account the agent runs
// under, and an agent started by systemd as a service user is the normal case --
// so the copied command adds the wrong person to the group and the pool stays
// stuck. Worse, the commonest state after somebody has already run usermod is a
// process that predates the change: the membership is real, the running agent
// does not hold it, and no amount of repeating the same command helps.
//
// So the denial is diagnosed against four facts the agent can read for itself:
// who it is, whether it is in a container, what owns the socket, and which
// groups the process actually holds as opposed to which ones the user database
// lists.
//
// The container case is the one that makes the group advice actively wrong. An
// agent in the published image runs as a user that exists only inside that
// image, so `usermod -aG 987 nonroot` on the host answers "user does not exist"
// and there is nothing the operator can do to make it work. A container is
// given a group when it is created, not afterwards.

import (
	"fmt"
	"io/fs"
	"os"
	"os/user"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

// agentIdentity is the agent's view of itself, injected so that every branch of
// the diagnosis can be tested on a machine with one user and no docker group.
type agentIdentity struct {
	uid int
	// gid is the primary group, which is what separates "the groups this
	// process was given" from the one it would have anyway.
	gid      int
	username string
	// processGroups are the groups this process holds. A group added with
	// usermod does not appear here until the process is restarted, and that gap
	// is the difference between "join the group" and "restart the agent".
	processGroups []int
	// userGroups are the groups the user database says the account belongs to.
	userGroups []int
	// groupName resolves a gid to a name, returning "" when it cannot.
	groupName func(gid int) string
	// stat reports the mode and owning gid of a path. ok is false when the path
	// cannot be examined at all, which is itself common here: a socket inside a
	// directory the agent may not traverse.
	stat func(path string) (mode fs.FileMode, gid int, ok bool)
	// unit is the systemd unit the agent runs under, so the restart hint names
	// a command that exists on this host. Empty means no systemd, or no unit
	// this agent could recognise, and the hint stays generic.
	unit string
	// containerized reports that this agent is itself in a container, which
	// changes the fix completely: its account is the image's, not the host's,
	// and the group has to be granted when the container is created.
	containerized bool
	// envDockerGID is DOCKER_GID from the environment, if the deployment put
	// it there. The compose files do: it is the value group_add was given, so
	// when it is present the advice can say which line to change rather than
	// which file to look in.
	envDockerGID string
}

func realIdentity() agentIdentity {
	id := agentIdentity{
		uid:          os.Geteuid(),
		gid:          os.Getegid(),
		envDockerGID: strings.TrimSpace(os.Getenv("DOCKER_GID")),
		groupName: func(gid int) string {
			g, err := user.LookupGroupId(strconv.Itoa(gid))
			if err != nil || g == nil {
				return ""
			}
			return g.Name
		},
		stat:          statOwner,
		unit:          agentUnit(),
		containerized: inContainer(),
	}
	// The effective gid is not guaranteed to appear in the supplementary list,
	// so it is added explicitly: a socket owned by the agent's own primary group
	// is usable, and must not be reported as a group it needs to join.
	id.processGroups = append(id.processGroups, os.Getegid())
	if groups, err := os.Getgroups(); err == nil {
		id.processGroups = append(id.processGroups, groups...)
	}
	if u, err := user.Current(); err == nil && u != nil {
		id.username = u.Username
		if ids, err := u.GroupIds(); err == nil {
			for _, s := range ids {
				if n, err := strconv.Atoi(s); err == nil {
					id.userGroups = append(id.userGroups, n)
				}
			}
		}
	}
	return id
}

// deniedDetail explains a permission denial on one socket, in a sentence whose
// commands can be pasted without editing.
//
// path is the socket itself; it may be unreadable, in which case the advice
// falls back to what is still knowable -- who the agent is, and where a rootless
// daemon would put a socket it could use.
func deniedDetail(id agentIdentity, path string) string {
	who := id.who()
	mode, gid, ok := fs.FileMode(0), 0, false
	if id.stat != nil {
		mode, gid, ok = id.stat(path)
	}
	// The group is named where the system can name it and numbered where it
	// cannot; usermod takes either, so the command works both ways.
	group := ""
	if ok {
		group = strconv.Itoa(gid)
		if id.groupName != nil {
			if name := id.groupName(gid); name != "" {
				group = name
			}
		}
	}
	perm := fmt.Sprintf("%04o", mode.Perm())

	switch {
	case ok && id.containerized && !id.holdsGroup(gid):
		// Nothing an operator does on the host to a user that only exists in
		// the image will help. The container needs the host gid at creation.
		return id.containerDenied(path, gid, perm)

	case !ok && id.containerized:
		// The socket cannot even be examined from in here, which usually means
		// it was never mounted.
		return fmt.Sprintf("permission denied on %s: this agent runs in a container as %s and cannot open that socket. "+
			"Mount the host's socket into the container and give the container the group that owns it -- "+
			"`stat -c '%%g' %s` on the host says which gid; with docker compose put DOCKER_GID=<gid> in .env (the compose file's group_add reads it) "+
			"and run `docker compose up -d`, with docker run recreate the container with --group-add <gid>.",
			path, id.name(), path)

	case ok && id.holdsGroup(gid):
		// The agent is in the group and was still refused, so the group is not
		// what is in the way: the mode, or a directory above the socket.
		return fmt.Sprintf("permission denied on %s: %s and already holds group %s, "+
			"so the denial is the socket's own mode (%s) or a directory above it. "+
			"Check `ls -l %s`, or %s",
			path, who, group, perm, path, id.rootlessAlternative())

	case ok && slices.Contains(id.userGroups, gid):
		// usermod has already been run; the process simply predates it.
		return fmt.Sprintf("permission denied on %s: %s is in the %s group that owns the socket, "+
			"but this agent process started before it was added and does not hold the group yet. %s",
			path, id.name(), group, id.restart())

	case ok:
		return fmt.Sprintf("permission denied on %s: %s, and the socket is group-owned by %s (mode %s). "+
			"Run `sudo usermod -aG %s %s` and %s, or %s",
			path, who, group, perm, group, id.name(), id.restartClause(), id.rootlessAlternative())

	case id.uid == 0:
		// Root was refused, which no group can explain.
		return fmt.Sprintf("permission denied on %s even though the agent is running as root, "+
			"which usually means SELinux or AppArmor is blocking it; check `dmesg` or `ausearch -m avc` on this host",
			path)

	default:
		// The socket could not be examined -- typically a directory above it
		// that this agent may not traverse -- so name the usual cause and the
		// escape hatch rather than inventing a group.
		return fmt.Sprintf("permission denied on %s: %s. "+
			"Add that user to the docker group (`sudo usermod -aG docker %s`) and %s, or %s",
			path, who, id.name(), id.restartClause(), id.rootlessAlternative())
	}
}

// containerDenied is the advice for a container that was not given the group
// owning the socket, written as the two steps a compose operator actually has
// to take.
//
// The earlier version of this sentence offered `group_add: ["987"]` as a
// copyable snippet, and the UI dutifully gave it a copy button -- so it was
// pasted into a shell, which answered "command not found", and the container
// was recreated with the same wrong group as before. The compose file already
// has group_add; what it reads is DOCKER_GID in .env, and that line is the
// only thing to change. Naming the group the container currently holds is
// what makes the mismatch obvious at a glance: "holds 999, socket is 987".
//
// Nothing here is a `docker compose down`: `up -d` recreates a container whose
// configuration changed, and the destructive variant, `down -v`, is what an
// operator reaches for when told to "recreate" -- and it deletes the volume
// with the database in it.
func (id agentIdentity) containerDenied(path string, gid int, perm string) string {
	socketGID := strconv.Itoa(gid)
	var b strings.Builder
	fmt.Fprintf(&b, "permission denied on %s: this agent runs in a container as %s, and the host socket mounted into it is group-owned by %s (mode %s)",
		path, id.name(), socketGID, perm)

	if gid == 0 {
		// The only gid that would reach this socket is root's, and the two
		// numbered steps below would put the container in it. That is not a
		// fix Zoomies will suggest; the socket needs a group of its own.
		b.WriteString(", which is root's group: the only DOCKER_GID that would open it is 0, and a container in the root group is not something to run jobs from. ")
		fmt.Fprintf(&b, "Give the socket a group of its own on the host -- `sudo groupadd docker`, then restart the daemon so it takes the group, "+
			"and put that group's gid (`stat -c '%%g' %s`) in DOCKER_GID -- or run a rootless daemon and point ZOOMIES_DOCKER_HOST at its socket.", path)
		return b.String()
	}

	switch extra := id.extraGroups(); {
	case len(extra) == 1:
		fmt.Fprintf(&b, ", but the container holds group %d, not %s", extra[0], socketGID)
	case len(extra) > 1:
		fmt.Fprintf(&b, ", but the container holds groups %s, not %s", joinInts(extra), socketGID)
	default:
		b.WriteString(", and the container was given no extra group at all")
	}
	if id.envDockerGID != "" {
		if slices.Contains(id.extraGroups(), atoiOr(id.envDockerGID, -1)) {
			fmt.Fprintf(&b, " -- DOCKER_GID=%s in its environment is where that came from", id.envDockerGID)
		} else {
			fmt.Fprintf(&b, " (its environment says DOCKER_GID=%s, but no group_add carried that into the container)", id.envDockerGID)
		}
	}
	b.WriteString(". A usermod on the host cannot help: that account exists only inside the image, and a container is given its groups when it is created. ")

	b.WriteString("With docker compose, in the directory that holds docker-compose.yml: ")
	if id.envDockerGID != "" && id.envDockerGID != socketGID {
		fmt.Fprintf(&b, "1. change the DOCKER_GID line in .env from %s to `DOCKER_GID=%s`", id.envDockerGID, socketGID)
	} else {
		fmt.Fprintf(&b, "1. put `DOCKER_GID=%s` in .env, which is the value the compose file's group_add reads", socketGID)
	}
	fmt.Fprintf(&b, " (`stat -c '%%g' %s` on the host confirms the gid); ", path)
	b.WriteString("2. run `docker compose up -d`, which recreates the container with that group -- there is no need to bring it down first, and down -v would delete the volume with the database in it. ")
	fmt.Fprintf(&b, "With docker run, recreate the container with `--group-add %s`.", socketGID)
	return b.String()
}

// extraGroups are the groups the process holds beyond its primary one: for a
// container, exactly what group_add or --group-add gave it.
func (id agentIdentity) extraGroups() []int {
	var out []int
	for _, g := range id.processGroups {
		if g != id.gid && !slices.Contains(out, g) {
			out = append(out, g)
		}
	}
	slices.Sort(out)
	return out
}

func joinInts(ns []int) string {
	parts := make([]string, len(ns))
	for i, n := range ns {
		parts[i] = strconv.Itoa(n)
	}
	return strings.Join(parts, ", ")
}

func atoiOr(s string, fallback int) int {
	n, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil {
		return fallback
	}
	return n
}

// who names the account the agent runs as, which is the fact an operator most
// often gets wrong: it is a service user far more often than their own login.
func (id agentIdentity) who() string {
	return fmt.Sprintf("the agent runs as %s (uid %d)", id.name(), id.uid)
}

// name is the agent's username, falling back to the uid when the user database
// has nothing to say about it -- a container with no /etc/passwd entry, say.
func (id agentIdentity) name() string {
	if id.username != "" {
		return id.username
	}
	return "uid " + strconv.Itoa(id.uid)
}

func (id agentIdentity) holdsGroup(gid int) bool {
	return slices.Contains(id.processGroups, gid)
}

// agentUnit names the systemd unit this agent is most likely running under: its
// own on a dedicated host, the controller's where the agent is embedded. A host
// with neither unit file gets no command, because a command that does not exist
// is worse than none.
func agentUnit() string {
	if !HasSystemd() {
		return ""
	}
	for _, unit := range []string{"zoomies-agent", "zoomies"} {
		if _, err := os.Stat(filepath.Join("/etc/systemd/system", unit+".service")); err == nil {
			return unit
		}
	}
	return ""
}

// restart is the whole instruction, for the case where restarting is the only
// thing left to do.
func (id agentIdentity) restart() string {
	if id.unit != "" {
		return fmt.Sprintf("Restart it with `sudo systemctl restart %s` and it will pick the group up.", id.unit)
	}
	return "Restart the agent process and it will pick the group up."
}

// restartClause is the same instruction as a fragment, for the case where it
// follows a usermod in one sentence.
func (id agentIdentity) restartClause() string {
	if id.unit != "" {
		return fmt.Sprintf("restart the agent (`sudo systemctl restart %s`)", id.unit)
	}
	return "restart the agent"
}

// rootlessAlternative points at the other way out of a socket the agent may not
// use: a per-user daemon, which is the arrangement Zoomies prefers anyway.
func (id agentIdentity) rootlessAlternative() string {
	return fmt.Sprintf("run a rootless daemon and set agent.docker_host to %s",
		filepath.Join("/run/user", strconv.Itoa(id.uid), "docker.sock"))
}

// inContainer reports whether this agent is itself running in a container.
//
// Docker writes /.dockerenv and Podman /run/.containerenv; the cgroup line is
// the fallback for runtimes that write neither, and for a container started
// with an unusual entrypoint. A false negative only costs the sharper wording,
// so none of these checks needs to be certain.
func inContainer() bool {
	for _, marker := range []string{"/.dockerenv", "/run/.containerenv"} {
		if _, err := os.Stat(marker); err == nil {
			return true
		}
	}
	cgroup, err := os.ReadFile("/proc/self/cgroup")
	if err != nil {
		return false
	}
	for _, needle := range []string{"docker", "containerd", "libpod", "kubepods"} {
		if strings.Contains(string(cgroup), needle) {
			return true
		}
	}
	return false
}

