//go:build unix

package backend

import (
	"io/fs"
	"os"
	"syscall"
)

// statOwner reports a path's mode and owning gid.
//
// os.Stat follows the symlink /var/run/docker.sock usually is, which is what we
// want: the mode that matters belongs to the socket the connection lands on.
func statOwner(path string) (fs.FileMode, int, bool) {
	fi, err := os.Stat(path)
	if err != nil {
		return 0, 0, false
	}
	st, ok := fi.Sys().(*syscall.Stat_t)
	if !ok {
		return fi.Mode(), 0, false
	}
	return fi.Mode(), int(st.Gid), true
}

package backend

// The Podman backend.
//
// Podman's API socket speaks the Docker Engine API, so the whole of docker.go
// applies unchanged and this file is the list of differences:
//
//   - the socket is found in a different place (DetectPodmanHost),
//   - rootless is the normal configuration rather than the hardened one, so an
//     unavailable-because-root Podman is worth commenting on rather than
//     celebrating,
//   - docker-in-docker is not supported: a privileged nested dockerd inside a
//     rootless Podman container does not work, and telling an operator that up
//     front is kinder than letting the sidecar crash-loop,
//   - bind mounts get an SELinux relabel suffix, because Podman's usual home is
//     a Fedora or RHEL host with SELinux enforcing, where an unlabelled mount
//     is silently unreadable inside the container.
//
// It embeds *DockerBackend rather than copying it, so a fix to the container
// lifecycle lands in both backends at once.

import (
	"context"
	"fmt"

	"github.com/eyupio/zoomies/internal/store"
)

// PodmanBackend runs runners as containers on a Podman service.
type PodmanBackend struct {
	*DockerBackend
}

func podmanFlavor() flavor {
	f := dockerFlavor()
	f.kind = store.BackendPodman
	f.displayName = "Podman"
	f.supportsDinD = false
	// :z relabels the host path so an SELinux-enforcing host lets the container
	// read it. It is shared rather than private (:Z) because the cache is
	// mounted into one runner after another. It applies to the directories
	// Zoomies creates -- the work and cache binds -- and never to the host
	// socket, which is the system's file to label.
	f.mountSuffix = ":z"
	// The usual cause of an unreachable Podman socket is that podman.socket has
	// never been enabled -- rootless Podman does not start it on install the
	// way Docker's own daemon starts itself.
	f.startHint = "systemctl --user enable --now podman.socket"
	return f
}

var _ Backend = (*PodmanBackend)(nil)

// NewPodman builds a Podman backend. An empty Host autodetects, preferring the
// per-user socket at $XDG_RUNTIME_DIR/podman/podman.sock.
//
// As with NewDocker, this does not contact the service: Probe reports on it.
func NewPodman(opts DockerOptions) (*PodmanBackend, error) {
	d, err := newContainerBackend(opts, podmanFlavor(), DetectPodmanHost, "unix:///run/podman/podman.sock")
	if err != nil {
		return nil, err
	}
	return &PodmanBackend{DockerBackend: d}, nil
}

// Kind identifies the implementation.
func (b *PodmanBackend) Kind() store.BackendKind { return store.BackendPodman }

// Probe reports on the Podman service. The Docker probe already names Podman
// and its own start command via the flavor's displayName and startHint, so
// there is nothing to add here beyond correcting Kind and SupportsDinD.
func (b *PodmanBackend) Probe(ctx context.Context) Info {
	info := b.DockerBackend.Probe(ctx)
	info.Kind = store.BackendPodman
	info.SupportsDinD = false
	return info
}

// Create goes through CreateWithResult, so both entry points give the same
// answer.
func (b *PodmanBackend) Create(ctx context.Context, spec Spec) (Handle, error) {
	r, err := b.CreateWithResult(ctx, spec)
	return r.Handle, err
}

// CreateWithResult refuses docker-in-docker and otherwise defers to the Docker
// path. The refusal lives here, not only in Create, because the agent calls this
// one for any backend that reports timings: the terse check further down would
// otherwise be the only text an operator ever saw, with no remedy in it.
func (b *PodmanBackend) CreateWithResult(ctx context.Context, spec Spec) (CreateResult, error) {
	if spec.DockerMode == store.DockerDinD {
		return CreateResult{}, fmt.Errorf("backend: pool %q asks for docker-in-docker, which the podman backend does not support; either move the pool to the docker backend, or drop docker_mode to none and let jobs use podman's own nested container support inside the runner image", spec.PoolName)
	}
	return b.DockerBackend.CreateWithResult(ctx, spec)
}

package backend

import (
	"context"
	"net/http"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func TestPodmanKindAndDefaults(t *testing.T) {
	b, err := NewPodman(DockerOptions{Logger: quietLogger()})
	if err != nil {
		t.Fatalf("NewPodman: %v", err)
	}
	if b.Kind() != store.BackendPodman {
		t.Fatalf("kind = %q", b.Kind())
	}
	// Autodetection must land on a Podman socket, not Docker's.
	if !strings.Contains(b.api.Endpoint(), "podman") {
		t.Fatalf("endpoint = %q, want a podman socket", b.api.Endpoint())
	}
}

func TestPodmanRefusesDinD(t *testing.T) {
	b, err := NewPodman(DockerOptions{Host: "unix:///run/podman/podman.sock", Logger: quietLogger()})
	if err != nil {
		t.Fatalf("NewPodman: %v", err)
	}
	spec := jitSpec()
	spec.DockerMode = store.DockerDinD

	// The agent calls CreateWithResult, so it has to give the same answer as
	// Create: a test of Create alone passed while production showed the terse
	// message with no remedy in it.
	entryPoints := map[string]func() error{
		"Create": func() error {
			_, err := b.Create(context.Background(), spec)
			return err
		},
		"CreateWithResult": func() error {
			_, err := b.CreateWithResult(context.Background(), spec)
			return err
		},
	}
	for name, create := range entryPoints {
		t.Run(name, func(t *testing.T) {
			err := create()
			if err == nil {
				t.Fatal("podman accepted docker-in-docker")
			}
			// The operator needs both alternatives, not just a refusal.
			if !strings.Contains(err.Error(), "docker backend") || !strings.Contains(err.Error(), "nested") {
				t.Fatalf("unhelpful message: %v", err)
			}
		})
	}
}

func TestPodmanFlavorDiffersFromDocker(t *testing.T) {
	p, d := podmanFlavor(), dockerFlavor()
	if p.supportsDinD {
		t.Fatal("podman must not claim docker-in-docker support")
	}
	if d.mountSuffix != "" {
		t.Fatalf("docker needs no mount suffix, got %q", d.mountSuffix)
	}
	if p.mountSuffix != ":z" {
		t.Fatalf("podman mount suffix = %q, want :z for SELinux relabelling", p.mountSuffix)
	}

	spec := jitSpec()
	spec.DockerMode = store.DockerHostSocket
	cfg := buildRunnerConfig(spec, p, containerOptions{
		Now: time.Now(), HostSocket: "/run/user/1000/podman/podman.sock",
	})
	want := "/run/user/1000/podman/podman.sock:/var/run/docker.sock"
	if !slices.Contains(cfg.HostConfig.Binds, want) {
		t.Fatalf("binds = %v, want %q", cfg.HostConfig.Binds, want)
	}
	// The rest of the container contract is shared with Docker on purpose.
	if cfg.User != "runner" || !slices.Contains(cfg.HostConfig.CapDrop, "ALL") {
		t.Fatalf("podman lost the shared security defaults: %+v", cfg.HostConfig)
	}
}

func TestPodmanProbe(t *testing.T) {
	t.Run("unavailable explains the socket unit", func(t *testing.T) {
		// On a host, that is. Inside a container a missing socket is a
		// missing mount and says so instead -- see
		// TestAMissingSocketInAContainerIsAMissingMount -- and CI's own jobs
		// run in containers: left to the machine it ran on, this failed on
		// exactly the runners Zoomies provides.
		was := runningInContainer
		runningInContainer = func() bool { return false }
		t.Cleanup(func() { runningInContainer = was })
		b, err := NewPodman(DockerOptions{Host: "unix:///nonexistent/zoomies/podman.sock", Logger: quietLogger()})
		if err != nil {
			t.Fatalf("NewPodman: %v", err)
		}
		info := b.Probe(context.Background())
		if info.Available {
			t.Fatal("a missing socket must not report as available")
		}
		if info.Kind != store.BackendPodman {
			t.Fatalf("kind = %q", info.Kind)
		}
		if !strings.Contains(info.Detail, "podman.socket") {
			t.Fatalf("detail must mention the socket unit: %q", info.Detail)
		}
	})

	t.Run("available never claims dind", func(t *testing.T) {
		f := newFakeEngine(t, map[string]http.HandlerFunc{
			"GET " + v + "/_ping":   func(w http.ResponseWriter, r *http.Request) { _, _ = w.Write([]byte("OK")) },
			"GET " + v + "/version": func(w http.ResponseWriter, r *http.Request) { writeJSON(w, 200, VersionInfo{Version: "5.2.0"}) },
			"GET " + v + "/info": func(w http.ResponseWriter, r *http.Request) {
				writeJSON(w, 200, SystemInfo{ServerVersion: "5.2.0", Rootless: true})
			},
		})
		b, err := NewPodman(DockerOptions{Host: "tcp://" + f.Listener.Addr().String(), Logger: quietLogger()})
		if err != nil {
			t.Fatalf("NewPodman: %v", err)
		}
		info := b.Probe(context.Background())
		if !info.Available || info.Version != "5.2.0" || !info.Rootless {
			t.Fatalf("info = %+v", info)
		}
		if info.SupportsDinD {
			t.Fatal("podman must never report docker-in-docker support")
		}
	})
}

package backend

// The bare-process backend: the actions/runner binary, run directly on the
// host, with no container and no systemd unit.
//
// It exists for the two cases containers cannot serve -- a macOS host, and a
// build that needs hardware the daemon will not hand to a container -- and it
// makes a trade the operator must understand: a job on this backend runs as the
// agent's user, on the agent's filesystem, with the agent's network. Isolation
// comes from the ephemeral lifecycle and nothing else.
//
// Each runner gets its own directory under <WorkDir>/runners, laid out the way
// the runner expects, so two runners on one host never share credentials or a
// work folder.

import (
	"archive/tar"
	"archive/zip"
	"compress/gzip"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log/slog"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// Layout of <WorkDir>.
const (
	toolsDirName   = "_tools"
	runnersDirName = "runners"

	runnerLogFile  = "runner.log"
	runnerPIDFile  = "runner.pid"
	runnerExitFile = "runner.exit"
	runnerMetaFile = "runner.json"
	runnerWorkDir  = "_work"
)

// listenerPath is the binary run.sh (run.cmd on Windows) eventually execs.
// Zoomies runs it directly: the script is a wrapper that spawns the listener
// as a child, so a SIGINT sent to the wrapper does not reliably reach the
// process that has to act on it, and the pid we record would not be the pid we
// need. The suffix, like configScript, is the platform's: see process_unix.go
// and process_windows.go.
var listenerPath = "bin/Runner.Listener" + exeSuffix

// DefaultRunnerVersion is used when neither the pool nor the agent pins one.
//
// It is the same release deploy/Dockerfile.runner and the Makefile pin, and
// the digests in runner_digests.go are its digests: bump all of them together
// (.github/workflows/runner-version.yml does), or the process backend will
// refuse to install the version it defaults to.
const DefaultRunnerVersion = "2.337.0"

// defaultRunnerDownloadURL is where actions/runner releases live.
const defaultRunnerDownloadURL = "https://github.com/actions/runner/releases/download"

// configureTimeout bounds config.sh, which talks to GitHub and can hang.
const configureTimeout = 3 * time.Minute

// tailPoll is how often a followed log file is re-read. See followReader.
const tailPoll = 250 * time.Millisecond

// ProcessOptions configures the process backend.
type ProcessOptions struct {
	// WorkDir is the root of the layout above. It must be writable.
	WorkDir string
	// RunnerVersion is the actions/runner release used when a pool does not pin
	// one. Empty means DefaultRunnerVersion.
	RunnerVersion string
	// RunnerSHA256 is the expected digest of the runner archive for
	// RunnerVersion on this host's OS and architecture. Setting it is how an
	// operator gets a verified download for a version Zoomies does not ship a
	// digest for.
	RunnerSHA256 string
	// AllowUnverifiedDownload permits installing a runner archive whose digest
	// Zoomies cannot check. It is off by default: the alternative is executing
	// whatever the network handed us.
	AllowUnverifiedDownload bool
	// DownloadBaseURL overrides where releases are fetched from, for hosts that
	// mirror them internally.
	DownloadBaseURL string
	HTTPClient      *http.Client
	Logger          *slog.Logger
}

// ProcessBackend runs runners as ordinary processes on the host.
type ProcessBackend struct {
	root            string
	version         string
	sha256          string
	allowUnverified bool
	baseURL         string
	http            *http.Client
	log             *slog.Logger

	// mu guards running, which holds the children this agent started so that
	// exactly one goroutine waits on each of them.
	mu sync.Mutex
	// running maps a runner's directory to the child there and to a channel
	// closed once the goroutine reaping it has finished writing. Removal waits
	// on that: the reaper records the exit code in the very directory the
	// remove is deleting, and the two used to race.
	running map[string]*child
	// installing serialises release downloads so two concurrent creates do not
	// fetch the same archive twice.
	installing sync.Mutex
}

var _ Backend = (*ProcessBackend)(nil)

// NewProcess builds a process backend rooted at opts.WorkDir.
func NewProcess(opts ProcessOptions) (*ProcessBackend, error) {
	root := strings.TrimSpace(opts.WorkDir)
	if root == "" {
		return nil, errors.New("backend: the process backend needs agent.work_dir set to a writable directory")
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return nil, fmt.Errorf("backend: resolving the work directory %s: %w", root, err)
	}

	log := opts.Logger
	if log == nil {
		log = slog.Default()
	}
	version := strings.TrimPrefix(strings.TrimSpace(opts.RunnerVersion), "v")
	if version == "" {
		version = DefaultRunnerVersion
	}
	client := opts.HTTPClient
	if client == nil {
		client = &http.Client{Timeout: 30 * time.Minute}
	}
	base := strings.TrimSuffix(strings.TrimSpace(opts.DownloadBaseURL), "/")
	if base == "" {
		base = defaultRunnerDownloadURL
	}

	return &ProcessBackend{
		root:            abs,
		version:         version,
		sha256:          strings.ToLower(strings.TrimSpace(opts.RunnerSHA256)),
		allowUnverified: opts.AllowUnverifiedDownload,
		baseURL:         base,
		http:            client,
		log:             log.With("backend", string(store.BackendProcess)),
		running:         make(map[string]*child),
	}, nil
}

// Kind identifies the implementation.
func (b *ProcessBackend) Kind() store.BackendKind { return store.BackendProcess }

// Probe reports whether this host can actually run the runner binary.
//
// "Available" here means more than "the code compiled": the runner is a .NET
// application, and on Linux it refuses to start without ICU. That single
// missing library is the most common cause of a runner that dies seconds after
// launch with a stack trace nobody reads, so it is checked here and named.
func (b *ProcessBackend) Probe(ctx context.Context) Info {
	info := Info{
		Kind:     store.BackendProcess,
		Version:  b.version,
		Endpoint: b.root,
		Rootless: os.Geteuid() != 0,
	}

	if _, err := runnerAsset(runtime.GOOS, runtime.GOARCH, b.version); err != nil {
		info.Detail = err.Error()
		return info
	}
	if err := b.checkWritable(); err != nil {
		info.Detail = err.Error()
		return info
	}
	if !HasShell() {
		info.Detail = noShellDetail
		return info
	}
	if err := checkICU(); err != nil {
		info.Detail = err.Error()
		return info
	}

	info.Available = true
	info.Detail = fmt.Sprintf("actions/runner %s on %s/%s, work directory %s", b.version, runtime.GOOS, runtime.GOARCH, b.root)
	if !info.Rootless {
		info.Detail += "; the agent is running as root, so every job runs as root on this host"
	}
	return info
}

func (b *ProcessBackend) checkWritable() error {
	if err := os.MkdirAll(b.root, 0o750); err != nil {
		return fmt.Errorf("work directory %s cannot be created: %v; point agent.work_dir somewhere this user can write", b.root, err)
	}
	f, err := os.CreateTemp(b.root, ".zoomies-write-check-*")
	if err != nil {
		return fmt.Errorf("work directory %s is not writable by this user: %v; fix its ownership or point agent.work_dir elsewhere", b.root, err)
	}
	name := f.Name()
	_ = f.Close()
	_ = os.Remove(name)
	return nil
}

// checkICU looks for the ICU libraries the runner's .NET runtime needs.
func checkICU() error {
	if runtime.GOOS != "linux" {
		return nil
	}
	if os.Getenv("DOTNET_SYSTEM_GLOBALIZATION_INVARIANT") == "1" {
		return nil
	}
	globs := []string{
		"/usr/lib/libicuuc.so*",
		"/usr/lib64/libicuuc.so*",
		"/usr/lib/*/libicuuc.so*",
		"/lib/*/libicuuc.so*",
		"/usr/local/lib/libicuuc.so*",
		"/usr/local/lib/*/libicuuc.so*",
	}
	for _, g := range globs {
		if m, err := filepath.Glob(g); err == nil && len(m) > 0 {
			return nil
		}
	}
	return errors.New("libicu is not installed, and the actions/runner will exit at startup without it: install it (apt-get install -y libicu-dev, dnf install -y libicu) or set DOTNET_SYSTEM_GLOBALIZATION_INVARIANT=1 in the agent's environment")
}

// Create lays out one runner directory, registers it and starts it.
func (b *ProcessBackend) Create(ctx context.Context, spec Spec) (Handle, error) {
	r, err := b.CreateWithResult(ctx, spec)
	return r.Handle, err
}

func (b *ProcessBackend) CreateWithResult(ctx context.Context, spec Spec) (CreateResult, error) {
	started := time.Now()
	if err := spec.Validate(); err != nil {
		return CreateResult{}, err
	}
	if spec.DockerMode == store.DockerDinD {
		return CreateResult{}, fmt.Errorf("backend: pool %q asks for docker-in-docker, which the process backend cannot provide; move the pool to the docker backend", spec.PoolName)
	}

	version := strings.TrimPrefix(strings.TrimSpace(spec.RunnerVersion), "v")
	if version == "" {
		version = b.version
	}
	tools, err := b.ensureRelease(ctx, version)
	if err != nil {
		return CreateResult{}, err
	}

	dir := b.runnerDir(spec.Name)
	if err := b.wipe(ctx, dir); err != nil {
		return CreateResult{}, err
	}
	if err := os.MkdirAll(filepath.Join(dir, runnerWorkDir), 0o750); err != nil {
		return CreateResult{}, fmt.Errorf("backend: creating the runner directory %s: %w", dir, err)
	}
	// Each runner needs its own copy of the tree, because the runner keeps its
	// credentials and its state next to the binary. Files are hard-linked where
	// the filesystem allows it, so the copy costs inodes rather than gigabytes.
	if err := cloneTree(tools, dir); err != nil {
		_ = os.RemoveAll(dir)
		return CreateResult{}, fmt.Errorf("backend: laying out the runner in %s: %w", dir, err)
	}

	env := b.childEnv(spec, dir)
	args := []string{"run"}
	if jit := spec.Credentials.JITConfig; jit != "" {
		// In the environment rather than on the command line. The runner reads
		// ACTIONS_RUNNER_INPUT_<ARG> as a fallback for every --arg, which is
		// how the container backends already hand it over, and it is the
		// difference between a credential in /proc/<pid>/cmdline, which every
		// local user can read, and one in /proc/<pid>/environ, which only this
		// account and root can. Short-lived and single-use is a reason to
		// worry less, not a reason to publish it.
		env = append(env, EnvUpstreamJITConfig+"="+jit)
	} else if err := b.configure(ctx, dir, spec, env); err != nil {
		_ = os.RemoveAll(dir)
		return CreateResult{}, err
	}

	if err := b.start(dir, args, env, spec, version); err != nil {
		_ = os.RemoveAll(dir)
		return CreateResult{}, err
	}
	b.log.Info("runner process started", "runner", spec.Name, "pool", spec.PoolName, "dir", dir, "runner_version", version)
	return CreateResult{Handle: Handle(dir), CreateDuration: time.Since(started)}, nil
}

// configure runs config.sh for the registration-token path, which is how a
// non-ephemeral pool joins a runner to GitHub.
func (b *ProcessBackend) configure(ctx context.Context, dir string, spec Spec, env []string) error {
	script := filepath.Join(dir, configScript)
	if _, err := os.Stat(script); err != nil {
		return fmt.Errorf("backend: %s is missing from the runner release in %s; delete %s and let Zoomies download it again", configScript, dir, dir)
	}

	args := []string{
		"--unattended", "--replace", "--disableupdate",
		"--url", spec.Credentials.URL,
		"--name", spec.Name,
		"--work", runnerWorkDir,
	}
	if labels := strings.Join(spec.Credentials.Labels, ","); labels != "" {
		args = append(args, "--labels", labels)
	}
	if spec.Credentials.RunnerGroup != "" {
		args = append(args, "--runnergroup", spec.Credentials.RunnerGroup)
	}
	if spec.Credentials.NoDefaultLabels {
		args = append(args, "--no-default-labels")
	}
	if spec.Ephemeral {
		args = append(args, "--ephemeral")
	}

	ctx, cancel := context.WithTimeout(ctx, configureTimeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, script, args...)
	cmd.Dir = dir
	// Only config.sh gets the token, on a copy of env: the listener started
	// afterwards runs for hours and has no use for a credential that can
	// register more runners. It is in the environment rather than the command
	// line for the reason the JIT config is -- argv is readable by every local
	// account, environ only by this one and root.
	cmd.Env = append(slices.Clone(env), EnvUpstreamRegistrationToken+"="+spec.Credentials.RegistrationToken)
	out, err := cmd.CombinedOutput()
	// The output is appended to the runner's own log so that a failed
	// registration is visible in the same place as everything else.
	appendLog(filepath.Join(dir, runnerLogFile), out)
	if err != nil {
		return fmt.Errorf("backend: registering runner %s with GitHub failed: %w; the last output was: %s", spec.Name, err, lastLine(out))
	}
	return nil
}

// start launches the listener detached and records enough on disk for a future
// agent process to find it again.
func (b *ProcessBackend) start(dir string, args, env []string, spec Spec, version string) error {
	bin := filepath.Join(dir, listenerPath)
	if _, err := os.Stat(bin); err != nil {
		return fmt.Errorf("backend: the runner binary %s is missing: %w", bin, err)
	}

	logFile, err := os.OpenFile(filepath.Join(dir, runnerLogFile), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o640)
	if err != nil {
		return fmt.Errorf("backend: opening the runner log in %s: %w", dir, err)
	}

	// The command deliberately does not carry a context: the runner must outlive
	// the create call, and the agent's own shutdown must not kill a job.
	cmd := exec.Command(bin, args...)
	cmd.Dir = dir
	cmd.Env = env
	cmd.Stdout = logFile
	cmd.Stderr = logFile
	detachRunner(cmd)
	if err := cmd.Start(); err != nil {
		_ = logFile.Close()
		return fmt.Errorf("backend: starting the runner in %s: %w", dir, err)
	}
	adoptRunner(cmd)

	now := time.Now().UTC()
	meta := processMeta{
		Name:      spec.Name,
		RunnerID:  spec.RunnerID,
		PoolID:    spec.PoolID,
		PoolName:  spec.PoolName,
		Version:   version,
		Ephemeral: spec.Ephemeral,
		PID:       cmd.Process.Pid,
		CreatedAt: now,
		StartedAt: now,
	}
	meta.ProcessIdentity, err = processIdentity(meta.PID)
	if err != nil {
		abandon(cmd, logFile)
		return fmt.Errorf("recording native process identity: %w", err)
	}
	if err := writeMeta(dir, meta); err != nil {
		abandon(cmd, logFile)
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, runnerPIDFile), []byte(strconv.Itoa(cmd.Process.Pid)), 0o640); err != nil {
		abandon(cmd, logFile)
		return fmt.Errorf("backend: writing the pid file in %s: %w", dir, err)
	}

	b.mu.Lock()
	reaped := make(chan struct{})
	b.running[dir] = &child{cmd: cmd, reaped: reaped}
	b.mu.Unlock()

	go func() {
		defer close(reaped)
		err := cmd.Wait()
		_ = logFile.Close()
		code := 0
		var ee *exec.ExitError
		switch {
		case err == nil:
		case errors.As(err, &ee):
			code = ee.ExitCode()
		default:
			code = -1
		}
		writeExit(dir, code)
		releaseRunner(meta.PID)
		b.mu.Lock()
		delete(b.running, dir)
		b.mu.Unlock()
		b.log.Info("runner process exited", "runner", meta.Name, "dir", dir, "exit_code", code)
	}()
	return nil
}

// child is a runner process and the signal that everything written on its
// behalf has been written.
type child struct {
	cmd    *exec.Cmd
	reaped chan struct{}
}

// reapGrace is how long a removal waits for the exit record to be written
// before deleting the directory anyway. It is a bound on a handover that takes
// microseconds, not an expectation.
const reapGrace = 5 * time.Second

// abandon kills a child we have decided not to keep and reaps it, so that a
// half-failed create leaves no zombie behind.
func abandon(cmd *exec.Cmd, log *os.File) {
	_ = cmd.Process.Kill()
	_ = cmd.Wait()
	_ = log.Close()
}

// childEnv builds the runner's environment. It is assembled rather than
// inherited so that a job cannot read whatever happened to be in the agent's
// environment, which on a controller host includes its database path and its
// GitHub credentials.
func (b *ProcessBackend) childEnv(spec Spec, dir string) []string {
	env := []string{
		"HOME=" + dir,
		"PATH=" + firstNonEmpty(os.Getenv("PATH"), "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"),
		EnvRunnerName + "=" + spec.Name,
		EnvEphemeral + "=" + boolString(spec.Ephemeral),
		// The runner refuses to start as root unless told that is intended, and
		// an agent running as a system service often is root.
		"RUNNER_ALLOW_RUNASROOT=1",
	}
	env = append(env, platformChildEnv(dir)...)
	for _, k := range []string{"LANG", "LC_ALL", "TZ", "DOTNET_SYSTEM_GLOBALIZATION_INVARIANT"} {
		if v, ok := os.LookupEnv(k); ok {
			env = append(env, k+"="+v)
		}
	}
	env = append(env, inheritedProxyEnv(os.LookupEnv, spec.Env)...)

	keys := make([]string, 0, len(spec.Env))
	for k := range spec.Env {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		env = append(env, k+"="+spec.Env[k])
	}
	return env
}

// Status reads the recorded pid and exit file.
func (b *ProcessBackend) Status(ctx context.Context, h Handle) (Status, error) {
	dir := string(h)
	meta, err := readMeta(dir)
	if err != nil {
		return Status{}, err
	}

	st := Status{Handle: h, StartedAt: meta.StartedAt}
	if ex, ok := readExit(dir); ok {
		st.ExitedAt = ex.ExitedAt
		st.ExitCode = ex.Code
		if ex.Code == 0 {
			st.Phase = PhaseExited
		} else {
			st.Phase = PhaseFailed
			st.Message = fmt.Sprintf("runner exited with code %d; see %s", ex.Code, filepath.Join(dir, runnerLogFile))
		}
		return st, nil
	}

	pid := readPID(dir)
	reused := false
	if pid > 0 && processAlive(pid) {
		switch err := verifyProcessIdentity(meta, pid); {
		case errors.Is(err, errProcessReused):
			reused = true
		case err != nil:
			return Status{}, err
		}
	}
	switch {
	case pid <= 0:
		st.Phase = PhaseStarting
	case reused:
		// The PID now belongs to something else, so the runner it was recorded
		// for is gone. Reporting that as an error instead froze List, and with
		// it every process runner on the host, behind one stale directory.
		st.Phase = PhaseExitUnknown
		st.ExitCode = -1
		st.Message = fmt.Sprintf("runner process %d is gone (its PID now belongs to another process) and recorded no exit code; see %s", pid, filepath.Join(dir, runnerLogFile))
	case processAlive(pid):
		st.Phase = PhaseRunning
	default:
		b.mu.Lock()
		_, owned := b.running[dir]
		b.mu.Unlock()
		if owned {
			// Our waiter is still recording the exit. Do not turn that tiny
			// handover into an unknown outcome and lose a real non-zero code.
			st.Phase = PhaseRunning
			return st, nil
		}
		// No exit file and no process: the agent was restarted while the runner
		// died, so nobody recorded the code.
		st.Phase = PhaseExitUnknown
		st.ExitCode = -1
		st.Message = fmt.Sprintf("runner process %d is gone and recorded no exit code; see %s", pid, filepath.Join(dir, runnerLogFile))
	}
	return st, nil
}

// Stats samples the runner's memory on Linux, where /proc makes it free. CPU is
// left at zero: sampling it properly means holding state between calls, and the
// host's own tooling already does that better.
func (b *ProcessBackend) Stats(ctx context.Context, h Handle) (Stats, error) {
	pid := readPID(string(h))
	if pid <= 0 || runtime.GOOS != "linux" {
		return Stats{}, nil
	}
	data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "statm"))
	if err != nil {
		return Stats{}, nil
	}
	fields := strings.Fields(string(data))
	if len(fields) < 2 {
		return Stats{}, nil
	}
	rss, err := strconv.ParseInt(fields[1], 10, 64)
	if err != nil {
		return Stats{}, nil
	}
	return Stats{MemoryBytes: rss * int64(os.Getpagesize())}, nil
}

// Logs streams the runner's log file.
//
// Following is done by polling rather than with inotify because inotify is
// Linux-only and this backend's whole reason to exist is the hosts that are not
// Linux containers. A quarter-second poll on one small file is cheaper than a
// dependency that does not build on macOS.
//
// Since and Timestamps are ignored here: unlike a container's log stream, this
// is the runner's own file, and the runner already timestamps every line.
func (b *ProcessBackend) Logs(ctx context.Context, h Handle, opts LogOptions) (io.ReadCloser, error) {
	dir := string(h)
	if _, err := os.Stat(dir); err != nil {
		return nil, fmt.Errorf("%w: no runner directory at %s", ErrNotFound, dir)
	}
	path := filepath.Join(dir, runnerLogFile)
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			// The runner has not written anything yet, which is not an error.
			if f, err = os.OpenFile(path, os.O_CREATE|os.O_RDONLY, 0o640); err != nil {
				return nil, fmt.Errorf("backend: opening %s: %w", path, err)
			}
		} else {
			return nil, fmt.Errorf("backend: opening %s: %w", path, err)
		}
	}

	if opts.Tail > 0 {
		if err := seekToLastLines(f, opts.Tail); err != nil {
			_ = f.Close()
			return nil, err
		}
	}
	if !opts.Follow {
		return f, nil
	}
	return &followReader{
		ctx:  ctx,
		f:    f,
		poll: tailPoll,
		// Following stops once the runner has exited and its log is drained;
		// otherwise a viewer on a finished runner would hang forever.
		finished: func() bool { _, done := readExit(dir); return done },
	}, nil
}

// Stop sends SIGINT, which the runner treats as "finish this job and exit",
// then escalates.
func (b *ProcessBackend) Stop(ctx context.Context, h Handle, timeout time.Duration) error {
	dir := string(h)
	pid := readPID(dir)
	if pid <= 0 || !processAlive(pid) {
		return nil
	}
	meta, err := readMeta(dir)
	if err != nil {
		return err
	}
	if err := verifyProcessIdentity(meta, pid); errors.Is(err, errProcessReused) {
		return nil
	} else if err != nil {
		return err
	}
	if timeout <= 0 {
		timeout = defaultStopTimeout
	}

	proc, err := os.FindProcess(pid)
	if err != nil {
		return nil
	}
	if runtime.GOOS == "windows" {
		// There is no interrupt to send: a service has no console to raise
		// Ctrl-C on, so a drain is a kill here. The runner's ephemeral
		// registration is single-use and the reaper removes it either way.
		return b.kill(ctx, proc, dir)
	}
	// The whole group, not the listener alone: the job runs in a worker the
	// listener spawned, and it is the worker that has to be told to stop.
	if err := signalRunner(proc, syscall.SIGINT); err != nil && !errors.Is(err, os.ErrProcessDone) {
		b.log.Warn("could not interrupt the runner; killing it", "dir", dir, "pid", pid, "error", err)
		return b.kill(ctx, proc, dir)
	}
	if waitFor(ctx, func() bool { return !processAlive(pid) }, timeout, 200*time.Millisecond) {
		return nil
	}

	b.log.Warn("runner did not exit after SIGINT; killing it", "dir", dir, "pid", pid, "timeout", timeout)
	return b.kill(ctx, proc, dir)
}

// killGrace is how long to wait for a killed runner to actually be gone.
//
// SIGKILL cannot be refused, so this is not a negotiation; it is the time the
// kernel takes to tear a process tree down, which on a loaded machine is not
// zero.
const killGrace = 5 * time.Second

func (b *ProcessBackend) kill(ctx context.Context, proc *os.Process, dir string) error {
	if !processAlive(proc.Pid) {
		return nil
	}
	{
		meta, err := readMeta(dir)
		if err != nil {
			return err
		}
		if err := verifyProcessIdentity(meta, proc.Pid); errors.Is(err, errProcessReused) {
			return nil
		} else if err != nil {
			return err
		}
	}
	if err := signalRunner(proc, syscall.SIGKILL); err != nil && !errors.Is(err, os.ErrProcessDone) {
		// The group could not be signalled; the leader alone is better than
		// nothing, and is all Windows can do anyway.
		if err := proc.Kill(); err != nil && !errors.Is(err, os.ErrProcessDone) {
			return fmt.Errorf("backend: killing the runner process %d in %s: %w", proc.Pid, dir, err)
		}
	}
	// SIGKILL is delivered, not applied. Returning here says the runner has
	// stopped when it is still running, and the caller's next move is usually
	// to delete the directory it is running in -- which fails, or worse
	// half-succeeds, while the process still has files open there. The SIGINT
	// path above already waits; this one has to as well.
	if !waitFor(ctx, func() bool { return !processAlive(proc.Pid) }, killGrace, 20*time.Millisecond) {
		b.log.Warn("a killed runner is still there", "dir", dir, "pid", proc.Pid, "waited", killGrace)
	}
	return nil
}

// Remove kills the runner and deletes its directory. Removing what is already
// gone is success.
func (b *ProcessBackend) Remove(ctx context.Context, h Handle) error {
	return b.wipe(ctx, string(h))
}

func (b *ProcessBackend) wipe(ctx context.Context, dir string) error {
	if _, err := os.Stat(dir); errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if pid := readPID(dir); pid > 0 && processAlive(pid) {
		if err := b.Stop(ctx, Handle(dir), 10*time.Second); err != nil {
			return fmt.Errorf("refusing to remove a runner whose process could not be stopped: %w", err)
		}
	}
	// The process being gone is not the end of the writing. The goroutine
	// reaping it records the exit code in this very directory, and it gets
	// there a moment after the process it was waiting on disappears -- which
	// is a moment this function is already spending inside RemoveAll. The walk
	// deletes what it found, the exit record lands behind it, and the rmdir
	// meets a directory that is not empty. So the removal waits for the
	// reaper, and there is nobody left writing here when it starts.
	b.mu.Lock()
	c := b.running[dir]
	delete(b.running, dir)
	b.mu.Unlock()
	if c != nil && !waitFor(ctx, func() bool {
		select {
		case <-c.reaped:
			return true
		default:
			return false
		}
	}, reapGrace, 10*time.Millisecond) {
		b.log.Warn("a runner's exit was still being recorded when its directory was removed",
			"dir", dir, "waited", reapGrace)
	}

	if err := removeAllRetry(ctx, dir, removeGrace, os.RemoveAll); err != nil {
		return fmt.Errorf("backend: removing the runner directory %s: %w", dir, err)
	}
	return nil
}

// removeAllRetry removes a tree, trying again for up to grace after a failure.
//
// The retry exists for Windows, where a file another process still holds open
// cannot be deleted and a runner's handles can outlive its termination by a
// moment. On POSIX grace is zero and this is one RemoveAll. The backoff starts
// short, because the usual wait is milliseconds, and caps at two seconds so
// the whole grace is spent looking rather than sleeping.
func removeAllRetry(ctx context.Context, dir string, grace time.Duration, remove func(string) error) error {
	deadline := time.Now().Add(grace)
	wait := 100 * time.Millisecond
	for {
		err := remove(dir)
		if err == nil || grace <= 0 || !time.Now().Before(deadline) {
			return err
		}
		select {
		case <-ctx.Done():
			return err
		case <-time.After(wait):
		}
		wait = min(wait*2, 2*time.Second)
	}
}

// abandonedGrace is how long a runner directory carrying no usable metadata
// has to sit untouched before List will call it abandoned.
//
// Create makes the directory and clones the tools tree into it before it
// writes the metadata, so a directory without metadata is either one being
// made right now or one whose agent died in that window. The two are told
// apart by whether anything is still writing: the clone touches the directory
// with every file it lays down, so a modification time this old means nobody
// is. Generous on purpose -- the cost of waiting is disk, and the cost of
// being wrong is deleting a runner while it is being built.
const abandonedGrace = 15 * time.Minute

// List walks the runners directory, so an agent that restarted still finds the
// runners it started before.
//
// A directory whose metadata cannot be read is reported as a workload that is
// gone rather than skipped. Skipping it was a leak: nothing else walks this
// tree, so a directory the reaper never hears about is a copy of the runner
// tools -- hundreds of megabytes -- left on the host until somebody notices
// the disk. Reported, it becomes an orphan like any other, and the agent
// removes it under the same grace and the same "only after a successful poll"
// rule as a container nothing claims.
func (b *ProcessBackend) List(ctx context.Context) ([]Workload, error) {
	root := filepath.Join(b.root, runnersDirName)
	entries, err := os.ReadDir(root)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("backend: listing runner directories in %s: %w", root, err)
	}

	var out []Workload
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		dir := filepath.Join(root, e.Name())
		meta, err := readMeta(dir)
		if err != nil {
			if w, ok := abandonedDir(dir, e); ok {
				out = append(out, w)
			}
			continue
		}
		st, err := b.Status(ctx, Handle(dir))
		if err != nil {
			return nil, fmt.Errorf("inspecting native runner %s: %w", meta.RunnerID, err)
		}
		out = append(out, Workload{
			Handle:   Handle(dir),
			Name:     meta.Name,
			RunnerID: meta.RunnerID,
			PoolID:   meta.PoolID,
			Status:   st,
		})
	}
	return out, nil
}

// abandonedDir reports a runner directory that has no usable metadata and has
// not been written to for abandonedGrace.
//
// It carries no runner ID because there is nothing to read one from, which is
// exactly right: the agent's orphan path removes the workload and reports
// nothing, so no row moves on the strength of a directory nobody can identify.
func abandonedDir(dir string, e os.DirEntry) (Workload, bool) {
	info, err := e.Info()
	if err != nil || time.Since(info.ModTime()) < abandonedGrace {
		return Workload{}, false
	}
	return Workload{
		Handle: Handle(dir),
		Name:   e.Name(),
		Status: Status{Handle: Handle(dir), Phase: PhaseGone},
	}, true
}

func (b *ProcessBackend) runnerDir(name string) string {
	return filepath.Join(b.root, runnersDirName, containerName(name))
}

// ---------------------------------------------------------------------------
// Runner release management
// ---------------------------------------------------------------------------

// ensureRelease returns the directory holding an extracted runner release,
// downloading it once per version.
func (b *ProcessBackend) ensureRelease(ctx context.Context, version string) (string, error) {
	dir := filepath.Join(b.root, toolsDirName, version)
	if _, err := os.Stat(filepath.Join(dir, listenerPath)); err == nil {
		return dir, nil
	}

	b.installing.Lock()
	defer b.installing.Unlock()
	// Another create may have installed it while we waited for the lock.
	if _, err := os.Stat(filepath.Join(dir, listenerPath)); err == nil {
		return dir, nil
	}

	asset, err := runnerAsset(runtime.GOOS, runtime.GOARCH, version)
	if err != nil {
		return "", err
	}
	url := fmt.Sprintf("%s/v%s/%s", b.baseURL, version, asset)

	if err := os.MkdirAll(filepath.Join(b.root, toolsDirName), 0o750); err != nil {
		return "", fmt.Errorf("backend: creating the tools directory: %w", err)
	}
	archive, err := b.download(ctx, url, asset)
	if err != nil {
		return "", err
	}
	defer os.Remove(archive)

	if err := b.verify(archive, version, asset); err != nil {
		return "", err
	}

	tmp := dir + ".incoming"
	_ = os.RemoveAll(tmp)
	extract := extractTarGz
	if strings.HasSuffix(asset, ".zip") {
		extract = extractZip
	}
	if err := extract(archive, tmp); err != nil {
		_ = os.RemoveAll(tmp)
		return "", fmt.Errorf("backend: unpacking %s: %w", asset, err)
	}
	if err := os.Rename(tmp, dir); err != nil {
		_ = os.RemoveAll(tmp)
		return "", fmt.Errorf("backend: installing the runner release into %s: %w", dir, err)
	}
	b.log.Info("installed actions/runner release", "version", version, "dir", dir)
	return dir, nil
}

func (b *ProcessBackend) download(ctx context.Context, url, asset string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return "", fmt.Errorf("backend: building the download request for %s: %w", url, err)
	}
	resp, err := b.http.Do(req)
	if err != nil {
		return "", fmt.Errorf("backend: downloading %s: %w; this host needs outbound access to the runner release, or set agent.runner_download_url to an internal mirror", url, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("backend: downloading %s: %s; check that the pinned runner version exists", url, resp.Status)
	}

	f, err := os.CreateTemp(filepath.Join(b.root, toolsDirName), ".download-*-"+asset)
	if err != nil {
		return "", fmt.Errorf("backend: creating a temporary file for %s: %w", asset, err)
	}
	if _, err := io.Copy(f, resp.Body); err != nil {
		_ = f.Close()
		_ = os.Remove(f.Name())
		return "", fmt.Errorf("backend: downloading %s: %w", url, err)
	}
	if err := f.Close(); err != nil {
		_ = os.Remove(f.Name())
		return "", fmt.Errorf("backend: writing %s: %w", asset, err)
	}
	return f.Name(), nil
}

// verify checks the archive against a digest we know, and refuses to install an
// unverified one unless the operator has said that is acceptable.
func (b *ProcessBackend) verify(path, version, asset string) error {
	want := b.sha256
	if want == "" {
		want = knownRunnerSHA256[version+"/"+asset]
	}
	if want == "" {
		if !b.allowUnverified {
			return fmt.Errorf("backend: no SHA-256 is known for %s, so Zoomies will not install it; publish the digest with agent.runner_sha256 (it is in the actions/runner release notes) or set agent.allow_unverified_runner_download to accept the risk", asset)
		}
		b.log.Warn("INSTALLING AN UNVERIFIED RUNNER RELEASE: no SHA-256 was available to check this download against, and it will be executed on this host",
			"asset", asset, "version", version)
		return nil
	}

	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("backend: reading %s to verify it: %w", asset, err)
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return fmt.Errorf("backend: hashing %s: %w", asset, err)
	}
	got := hex.EncodeToString(h.Sum(nil))
	if !strings.EqualFold(got, want) {
		return fmt.Errorf("backend: %s does not match its expected SHA-256 (got %s, want %s); the download was corrupted or tampered with -- it has not been installed", asset, got, want)
	}
	return nil
}

// runnerAsset names the release archive for a host, or explains why there is
// not one.
func runnerAsset(goos, goarch, version string) (string, error) {
	var osPart string
	switch goos {
	case "linux":
		osPart = "linux"
	case "darwin":
		osPart = "osx"
	case "windows":
		osPart = "win"
	default:
		return "", fmt.Errorf("backend: Zoomies has no runner for %s; run this agent on a Linux, macOS or Windows host", goos)
	}

	var archPart string
	switch goarch {
	case "amd64":
		archPart = "x64"
	case "arm64":
		archPart = "arm64"
	case "arm":
		archPart = "arm"
	default:
		return "", fmt.Errorf("backend: the process backend does not support %s/%s; actions/runner ships for x64, arm64 and arm", goos, goarch)
	}
	if osPart != "linux" && archPart == "arm" {
		return "", fmt.Errorf("backend: actions/runner does not ship a 32-bit %s build", goos)
	}
	// Windows releases are zips, and everything else a gzipped tarball; the
	// extension is what ensureRelease picks its unpacker by.
	ext := ".tar.gz"
	if osPart == "win" {
		ext = ".zip"
	}
	return fmt.Sprintf("actions-runner-%s-%s-%s%s", osPart, archPart, version, ext), nil
}

// extractZip unpacks a Windows runner release with the same refusals as
// extractTarGz: nothing outside the destination, nothing through a symlink,
// and no symlink entries at all, since a runner release has none and a zip
// that carries one is not the file it claims to be.
func extractZip(archive, dest string) error {
	zr, err := zip.OpenReader(archive)
	if err != nil {
		return err
	}
	defer zr.Close()

	if err := os.MkdirAll(dest, 0o750); err != nil {
		return err
	}
	for _, f := range zr.File {
		// Zip names are slash-separated whatever made them. An absolute name
		// or one with a drive letter is refused outright rather than joined,
		// because filepath.Join would keep the volume and safeJoin sees only
		// the text after it.
		name := filepath.FromSlash(f.Name)
		if filepath.IsAbs(name) || filepath.VolumeName(name) != "" || strings.HasPrefix(name, string(os.PathSeparator)) {
			return fmt.Errorf("archive entry %q is an absolute path", f.Name)
		}
		target, err := safeJoin(dest, name)
		if err != nil {
			return err
		}
		if err := noSymlinkParents(dest, target); err != nil {
			return err
		}
		mode := f.Mode()
		if mode&fs.ModeSymlink != 0 {
			return fmt.Errorf("archive entry %q is a symlink, which a runner release never carries", f.Name)
		}
		if f.FileInfo().IsDir() {
			if err := os.MkdirAll(target, 0o750); err != nil {
				return err
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o750); err != nil {
			return err
		}
		// A zip written on Windows records no POSIX mode at all, and a file
		// created with none could not be read back even to hash it.
		perm := mode.Perm()
		if perm == 0 {
			perm = 0o644
		}
		in, err := f.Open()
		if err != nil {
			return err
		}
		out, err := os.OpenFile(target, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, perm)
		if err != nil {
			_ = in.Close()
			return err
		}
		_, copyErr := io.Copy(out, in)
		_ = in.Close()
		if closeErr := out.Close(); copyErr == nil {
			copyErr = closeErr
		}
		if copyErr != nil {
			return copyErr
		}
	}
	return nil
}

// extractTarGz unpacks an archive, refusing entries that would write outside
// the destination -- a tarball is remote input, however trusted its origin.
func extractTarGz(archive, dest string) error {
	f, err := os.Open(archive)
	if err != nil {
		return err
	}
	defer f.Close()
	gz, err := gzip.NewReader(f)
	if err != nil {
		return err
	}
	defer gz.Close()

	if err := os.MkdirAll(dest, 0o750); err != nil {
		return err
	}
	tr := tar.NewReader(gz)
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		target, err := safeJoin(dest, hdr.Name)
		if err != nil {
			return err
		}
		// A symlink extracted earlier must not become a path component now:
		// "lib -> /etc" followed by "lib/cron.d/x" is the second half of the
		// classic escape, and safeJoin sees only the text of the name.
		if err := noSymlinkParents(dest, target); err != nil {
			return err
		}

		switch hdr.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0o750); err != nil {
				return err
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(target), 0o750); err != nil {
				return err
			}
			out, err := os.OpenFile(target, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, fs.FileMode(hdr.Mode).Perm())
			if err != nil {
				return err
			}
			if _, err := io.Copy(out, tr); err != nil {
				_ = out.Close()
				return err
			}
			if err := out.Close(); err != nil {
				return err
			}
		case tar.TypeSymlink:
			// filepath.Join cleans "/etc" to "etc" under the entry's directory,
			// which is why an absolute target used to pass the check below;
			// it is refused outright, since nothing in a runner release links
			// to an absolute path.
			if filepath.IsAbs(hdr.Linkname) || strings.HasPrefix(hdr.Linkname, `\`) {
				return fmt.Errorf("archive entry %q links to the absolute path %q", hdr.Name, hdr.Linkname)
			}
			if _, err := safeJoin(dest, filepath.Join(filepath.Dir(hdr.Name), hdr.Linkname)); err != nil {
				return fmt.Errorf("archive entry %q links outside the archive", hdr.Name)
			}
			if err := os.MkdirAll(filepath.Dir(target), 0o750); err != nil {
				return err
			}
			_ = os.Remove(target)
			if err := os.Symlink(hdr.Linkname, target); err != nil {
				return err
			}
		}
	}
}

// noSymlinkParents refuses to write through a symlink: every directory between
// root and target that already exists must be a real directory. The archive is
// extracted into a fresh directory, so the only way one of them is a symlink is
// that an earlier entry of the same archive made it so.
func noSymlinkParents(root, target string) error {
	rel, err := filepath.Rel(root, filepath.Dir(target))
	if err != nil {
		return err
	}
	dir := root
	for _, part := range strings.Split(rel, string(os.PathSeparator)) {
		if part == "." || part == "" {
			continue
		}
		dir = filepath.Join(dir, part)
		info, err := os.Lstat(dir)
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("archive entry %q would be written through the symlink %q", target, dir)
		}
	}
	return nil
}

// safeJoin resolves name under root, rejecting anything that escapes it. A
// tarball is remote input even when it comes from a trusted release, and an
// entry called ../../etc/cron.d/anything is the classic way that stops being
// true.
func safeJoin(root, name string) (string, error) {
	target := filepath.Join(root, name)
	if target != root && !strings.HasPrefix(target, root+string(os.PathSeparator)) {
		return "", fmt.Errorf("archive entry %q would write outside %s", name, root)
	}
	return target, nil
}

// cloneTree copies a directory tree, hard-linking regular files where the
// filesystem allows it. The runner never writes to its own program files, so
// sharing inodes between runners is safe and turns a 400MB copy per runner into
// a handful of directory entries.
func cloneTree(src, dst string) error {
	return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(src, path)
		if err != nil {
			return err
		}
		target := filepath.Join(dst, rel)
		switch {
		case d.IsDir():
			info, err := d.Info()
			if err != nil {
				return err
			}
			return os.MkdirAll(target, info.Mode().Perm()|0o700)
		case d.Type()&fs.ModeSymlink != 0:
			link, err := os.Readlink(path)
			if err != nil {
				return err
			}
			_ = os.Remove(target)
			return os.Symlink(link, target)
		default:
			if err := os.Link(path, target); err == nil {
				return nil
			}
			return copyFile(path, target)
		}
	})
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	info, err := in.Stat()
	if err != nil {
		return err
	}
	out, err := os.OpenFile(dst, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, info.Mode().Perm())
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		_ = out.Close()
		return err
	}
	return out.Close()
}

// ---------------------------------------------------------------------------
// On-disk records
// ---------------------------------------------------------------------------

// processMeta is what a restarted agent needs to recognise a directory as one
// of its runners.
type processMeta struct {
	Name            string    `json:"name"`
	RunnerID        string    `json:"runner_id"`
	PoolID          string    `json:"pool_id"`
	PoolName        string    `json:"pool_name"`
	Version         string    `json:"runner_version"`
	Ephemeral       bool      `json:"ephemeral"`
	PID             int       `json:"pid"`
	ProcessIdentity string    `json:"process_identity,omitempty"`
	CreatedAt       time.Time `json:"created_at"`
	StartedAt       time.Time `json:"started_at"`
}

func writeMeta(dir string, m processMeta) error {
	b, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("backend: encoding runner metadata: %w", err)
	}
	tmp, err := os.CreateTemp(dir, "metadata-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if err = tmp.Chmod(0640); err != nil {
		tmp.Close()
		return err
	}
	if _, err = tmp.Write(b); err != nil {
		tmp.Close()
		return err
	}
	if err = tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err = tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmp.Name(), filepath.Join(dir, runnerMetaFile)); err != nil {
		return fmt.Errorf("backend: writing runner metadata in %s: %w", dir, err)
	}
	return nil
}

func readMeta(dir string) (processMeta, error) {
	var m processMeta
	b, err := os.ReadFile(filepath.Join(dir, runnerMetaFile))
	if errors.Is(err, fs.ErrNotExist) {
		return m, fmt.Errorf("%w: no runner in %s", ErrNotFound, dir)
	}
	if err != nil {
		return m, fmt.Errorf("backend: reading runner metadata in %s: %w", dir, err)
	}
	if err := json.Unmarshal(b, &m); err != nil {
		return m, fmt.Errorf("backend: runner metadata in %s is corrupt: %w", dir, err)
	}
	return m, nil
}

// exitRecord is written once the runner's process has been reaped.
type exitRecord struct {
	Code     int       `json:"exit_code"`
	ExitedAt time.Time `json:"exited_at"`
}

func writeExit(dir string, code int) {
	b, err := json.Marshal(exitRecord{Code: code, ExitedAt: time.Now().UTC()})
	if err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(dir, runnerExitFile), b, 0o640)
}

func readExit(dir string) (exitRecord, bool) {
	var r exitRecord
	b, err := os.ReadFile(filepath.Join(dir, runnerExitFile))
	if err != nil || json.Unmarshal(b, &r) != nil {
		return r, false
	}
	return r, true
}

func readPID(dir string) int {
	b, err := os.ReadFile(filepath.Join(dir, runnerPIDFile))
	if err != nil {
		return 0
	}
	pid, err := strconv.Atoi(strings.TrimSpace(string(b)))
	if err != nil {
		return 0
	}
	return pid
}

// waitFor polls until done returns true, the context ends or the deadline
// passes. It is how "stop, then kill" is implemented without a busy loop.
func waitFor(ctx context.Context, done func() bool, timeout, interval time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for {
		if done() {
			return true
		}
		if !time.Now().Before(deadline) {
			return false
		}
		select {
		case <-ctx.Done():
			return done()
		case <-time.After(interval):
		}
	}
}

func appendLog(path string, data []byte) {
	if len(data) == 0 {
		return
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o640)
	if err != nil {
		return
	}
	defer f.Close()
	_, _ = f.Write(data)
}

func lastLine(out []byte) string {
	lines := strings.Split(strings.TrimSpace(string(out)), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if l := strings.TrimSpace(lines[i]); l != "" {
			return l
		}
	}
	return "(no output)"
}

// ---------------------------------------------------------------------------
// Log tailing
// ---------------------------------------------------------------------------

// followReader turns a log file into a stream that keeps producing as the
// runner writes.
type followReader struct {
	ctx      context.Context
	f        *os.File
	poll     time.Duration
	finished func() bool
	// drained records that the runner had already exited when we last hit the
	// end of the file, so one more read confirms there is nothing left.
	drained bool
}

func (t *followReader) Read(p []byte) (int, error) {
	for {
		n, err := t.f.Read(p)
		if n > 0 {
			t.drained = false
			return n, nil
		}
		if err != nil && !errors.Is(err, io.EOF) {
			return 0, err
		}
		// Copy-truncate keeps the same inode and inherited runner descriptor.
		if pos, e := t.f.Seek(0, io.SeekCurrent); e == nil {
			if st, e := t.f.Stat(); e == nil && st.Size() < pos {
				if _, e = t.f.Seek(0, io.SeekStart); e != nil {
					return 0, e
				}
				continue
			}
		}
		if t.finished != nil && t.finished() {
			if t.drained {
				return 0, io.EOF
			}
			// One more pass, because the runner may have written its last lines
			// between our read and its exit.
			t.drained = true
			continue
		}
		select {
		case <-t.ctx.Done():
			return 0, io.EOF
		case <-time.After(t.poll):
		}
	}
}

// Close releases the file.
func (t *followReader) Close() error { return t.f.Close() }

// seekToLastLines positions f at the start of its last n lines, reading
// backwards in blocks so that a large log is not loaded to show its tail.
func seekToLastLines(f *os.File, n int) error {
	const block = 8 << 10
	info, err := f.Stat()
	if err != nil {
		return fmt.Errorf("backend: reading the size of %s: %w", f.Name(), err)
	}

	size := info.Size()
	var (
		found int
		off   = size
		buf   = make([]byte, block)
	)
	for off > 0 {
		read := int64(block)
		if off < read {
			read = off
		}
		off -= read
		if _, err := f.ReadAt(buf[:read], off); err != nil && !errors.Is(err, io.EOF) {
			return fmt.Errorf("backend: reading %s: %w", f.Name(), err)
		}
		chunk := buf[:read]
		for i := len(chunk) - 1; i >= 0; i-- {
			if chunk[i] != '\n' {
				continue
			}
			// The final newline ends the last line rather than starting one.
			if off+int64(i) == size-1 {
				continue
			}
			found++
			if found >= n {
				_, err := f.Seek(off+int64(i)+1, io.SeekStart)
				return err
			}
		}
	}
	_, err = f.Seek(0, io.SeekStart)
	return err
}

// errProcessReused marks the one identity failure that is proof rather than
// doubt: the PID is alive and its birth identity differs from the recorded one,
// so the runner we recorded is gone. Callers treat it as "nothing of ours to
// signal"; every other verification failure stays an unverified identity and
// fails closed.
var errProcessReused = errors.New("PID was reused")

// An existing PID alone is never authority to signal a process after restart.
// Legacy metadata remains visible for operator recovery, but cannot kill a PID
// whose birth identity was never recorded.
func verifyProcessIdentity(meta processMeta, pid int) error {
	if meta.PID != pid || meta.ProcessIdentity == "" {
		return fmt.Errorf("%w: native runner process identity is unverified; inspect the runner before cleanup", ErrUnavailable)
	}
	identity, err := processIdentity(pid)
	if err != nil {
		return fmt.Errorf("%w: reading native process identity: %v", ErrUnavailable, err)
	}
	if identity != meta.ProcessIdentity {
		return fmt.Errorf("%w: native runner %w; refusing to signal or adopt it", ErrUnavailable, errProcessReused)
	}
	return nil
}

package backend

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

type tarEntry struct {
	name, link, body string
	typeflag         byte
}

func writeTarGz(t *testing.T, entries []tarEntry) string {
	t.Helper()
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	for _, e := range entries {
		h := &tar.Header{Name: e.name, Mode: 0o755, Typeflag: e.typeflag, Linkname: e.link, Size: int64(len(e.body))}
		if err := tw.WriteHeader(h); err != nil {
			t.Fatal(err)
		}
		if _, err := tw.Write([]byte(e.body)); err != nil {
			t.Fatal(err)
		}
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	src := filepath.Join(t.TempDir(), "runner.tar.gz")
	if err := os.WriteFile(src, buf.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
	return src
}

// safeJoin cleaned "/etc" to "etc" under the entry's directory, so a symlink
// to an absolute path passed the check, and a later regular entry beneath the
// link then followed it out of the destination. The digest check on every
// archive was the only thing standing in the way, and an operator may now
// choose to download a release Zoomies has no digest for.
func TestExtractTarGzRefusesSymlinkEscapes(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlinks in archives are a Unix concern here")
	}
	cases := []struct {
		name    string
		entries []tarEntry
		want    string
	}{
		{"an absolute link target", []tarEntry{
			{name: "lib", link: "/etc", typeflag: tar.TypeSymlink},
		}, "absolute path"},
		{"a link out of the archive", []tarEntry{
			{name: "lib", link: "../../outside", typeflag: tar.TypeSymlink},
		}, "links outside"},
		{"a file written through an earlier link", []tarEntry{
			{name: "real", typeflag: tar.TypeDir},
			{name: "lib", link: "real", typeflag: tar.TypeSymlink},
			{name: "lib/cron.d/x", body: "* * * * * root evil\n", typeflag: tar.TypeReg},
		}, "through the symlink"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dest := filepath.Join(t.TempDir(), "tools")
			err := extractTarGz(writeTarGz(t, tc.entries), dest)
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("extract = %v, want a refusal mentioning %q", err, tc.want)
			}
		})
	}

	// A relative link inside the archive, the shape a runner release actually
	// carries, still extracts.
	dest := filepath.Join(t.TempDir(), "tools")
	src := writeTarGz(t, []tarEntry{
		{name: "bin/real.sh", body: "#!/bin/sh\n", typeflag: tar.TypeReg},
		{name: "bin/alias.sh", link: "real.sh", typeflag: tar.TypeSymlink},
	})
	if err := extractTarGz(src, dest); err != nil {
		t.Fatalf("a relative link inside the archive was refused: %v", err)
	}
	if target, err := os.Readlink(filepath.Join(dest, "bin/alias.sh")); err != nil || target != "real.sh" {
		t.Fatalf("alias.sh -> %q, %v", target, err)
	}
}

package backend

import (
	"context"
	"errors"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"
)

// The runner never writes to its own program files, so sharing inodes between
// runners is safe -- and it is what turns a 400MB copy per runner into a
// handful of directory entries.
func TestCloneTreeSharesInodesWhereItCan(t *testing.T) {
	requirePOSIX(t)
	src, dst := t.TempDir(), filepath.Join(t.TempDir(), "clone")

	if err := os.MkdirAll(filepath.Join(src, "bin"), 0o750); err != nil {
		t.Fatal(err)
	}
	prog := filepath.Join(src, "bin", "Runner.Listener")
	if err := os.WriteFile(prog, []byte("#!/bin/sh\nexit 0\n"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink("Runner.Listener", filepath.Join(src, "bin", "run.sh")); err != nil {
		t.Fatal(err)
	}

	if err := cloneTree(src, dst); err != nil {
		t.Fatalf("cloneTree: %v", err)
	}

	cloned := filepath.Join(dst, "bin", "Runner.Listener")
	body, err := os.ReadFile(cloned)
	if err != nil {
		t.Fatalf("reading the clone: %v", err)
	}
	if !strings.Contains(string(body), "exit 0") {
		t.Fatalf("the clone does not carry the file's contents: %q", body)
	}
	// The executable bit has to survive, or the runner cannot be started.
	info, err := os.Stat(cloned)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm()&0o100 == 0 {
		t.Fatalf("mode = %v, want the executable bit kept", info.Mode())
	}
	// A hard link is the point: same inode, so the copy costs a directory
	// entry rather than the file.
	if !sameFile(t, prog, cloned) {
		t.Error("the cloned program file is a copy rather than a link")
	}

	link, err := os.Readlink(filepath.Join(dst, "bin", "run.sh"))
	if err != nil {
		t.Fatalf("the symlink did not survive the clone: %v", err)
	}
	if link != "Runner.Listener" {
		t.Fatalf("symlink target = %q, want it copied as-is", link)
	}

	// Cloning over an existing tree replaces the symlink rather than failing on
	// it, which is what makes a retried create work.
	if err := cloneTree(src, dst); err != nil {
		t.Fatalf("cloneTree over an existing tree: %v", err)
	}
}

// copyFile is the fallback for a filesystem that will not link -- a separate
// mount, or one with no hard links at all -- so it has to produce the same
// file, mode included.
func TestCopyFileKeepsContentsAndMode(t *testing.T) {
	requirePOSIX(t)
	dir := t.TempDir()
	src := filepath.Join(dir, "prog")
	if err := os.WriteFile(src, []byte("the program"), 0o755); err != nil {
		t.Fatal(err)
	}

	dst := filepath.Join(dir, "copy")
	if err := copyFile(src, dst); err != nil {
		t.Fatalf("copyFile: %v", err)
	}
	body, err := os.ReadFile(dst)
	if err != nil {
		t.Fatal(err)
	}
	if string(body) != "the program" {
		t.Fatalf("copy = %q", body)
	}
	info, err := os.Stat(dst)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm() != 0o755 {
		t.Fatalf("mode = %v, want 0755", info.Mode().Perm())
	}

	// A source that is not there is reported rather than producing an empty
	// file that would look like a runner with no program in it.
	if err := copyFile(filepath.Join(dir, "absent"), filepath.Join(dir, "out")); err == nil {
		t.Error("copying a file that does not exist succeeded")
	}
	// So is a destination that cannot be written.
	if err := copyFile(src, filepath.Join(dir, "no-such-dir", "out")); err == nil {
		t.Error("copying into a directory that does not exist succeeded")
	}
}

// A restarted agent recognises its runners by what it wrote beside them, so
// the metadata has to round-trip -- and a directory with none is ErrNotFound
// rather than a zero-valued runner the agent would then act on.
func TestRunnerMetadataRoundTrips(t *testing.T) {
	dir := t.TempDir()
	created := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	want := processMeta{
		Name: "zoomies-abc", RunnerID: "run_1", PoolID: "pool_1", PoolName: "hosted",
		Version: "2.320.0", Ephemeral: true, PID: 4242, CreatedAt: created, StartedAt: created,
	}
	if err := writeMeta(dir, want); err != nil {
		t.Fatalf("writeMeta: %v", err)
	}
	got, err := readMeta(dir)
	if err != nil {
		t.Fatalf("readMeta: %v", err)
	}
	if got.Name != want.Name || got.RunnerID != want.RunnerID || got.PID != want.PID || !got.Ephemeral {
		t.Fatalf("metadata round-tripped wrong: %+v", got)
	}
	if !got.CreatedAt.Equal(created) {
		t.Fatalf("created_at = %v, want %v", got.CreatedAt, created)
	}

	if _, err := readMeta(t.TempDir()); !errors.Is(err, ErrNotFound) {
		t.Fatalf("readMeta on an empty directory = %v, want ErrNotFound", err)
	}

	// Writing into a directory that is not there is an error naming the
	// directory, because the alternative is a runner the agent forgets.
	if err := writeMeta(filepath.Join(dir, "absent"), want); err == nil {
		t.Error("metadata was written into a directory that does not exist")
	}
}

// Asking for the log of a runner that has not written one yet is not an error:
// a viewer who opens the page the instant a runner starts should see an empty
// file filling up, not a failure.
func TestLogsOfARunnerThatHasWrittenNothingYet(t *testing.T) {
	requireUnix(t)
	b, root := newStubProcessBackend(t)
	dir := filepath.Join(root, "runners", "zoomies-quiet")
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatal(err)
	}

	rc, err := b.Logs(context.Background(), Handle(dir), LogOptions{})
	if err != nil {
		t.Fatalf("Logs: %v", err)
	}
	defer rc.Close()
	body, err := io.ReadAll(rc)
	if err != nil {
		t.Fatalf("reading the log: %v", err)
	}
	if len(body) != 0 {
		t.Fatalf("a runner that has written nothing produced %q", body)
	}

	// A directory that was never a runner is a different thing, and says so.
	if _, err := b.Logs(context.Background(), Handle(filepath.Join(root, "nowhere")), LogOptions{}); err == nil {
		t.Error("logs were offered for a runner directory that does not exist")
	} else if !errors.Is(err, ErrNotFound) {
		t.Errorf("error = %v, want ErrNotFound", err)
	}
}

// Tailing hands back the last few lines rather than the whole file, which is
// what makes a page open quickly on a runner that has been going for an hour.
func TestLogsTailReturnsOnlyTheLastLines(t *testing.T) {
	requireUnix(t)
	b, root := newStubProcessBackend(t)
	dir := filepath.Join(root, "runners", "zoomies-chatty")
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	var lines strings.Builder
	for i := range 100 {
		lines.WriteString("line ")
		lines.WriteString(string(rune('0' + i%10)))
		lines.WriteString("\n")
	}
	lines.WriteString("the last line\n")
	if err := os.WriteFile(filepath.Join(dir, runnerLogFile), []byte(lines.String()), 0o640); err != nil {
		t.Fatal(err)
	}

	rc, err := b.Logs(context.Background(), Handle(dir), LogOptions{Tail: 3})
	if err != nil {
		t.Fatalf("Logs: %v", err)
	}
	defer rc.Close()
	body, err := io.ReadAll(rc)
	if err != nil {
		t.Fatalf("reading the log: %v", err)
	}
	if !strings.Contains(string(body), "the last line") {
		t.Fatalf("the tail did not reach the end of the file:\n%s", body)
	}
	if got := strings.Count(string(body), "\n"); got > 4 {
		t.Fatalf("the tail returned %d lines, want about 3", got)
	}
}

// Sampling memory is free on Linux and nowhere else, so everywhere else it
// reports nothing rather than guessing -- and a handle that is not a running
// runner reports nothing rather than failing the heartbeat that asked.
func TestStatsSaysNothingRatherThanGuessing(t *testing.T) {
	b, root := newStubProcessBackend(t)

	got, err := b.Stats(context.Background(), Handle(filepath.Join(root, "runners", "nowhere")))
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	if got.MemoryBytes != 0 || got.CPUPercent != 0 {
		t.Fatalf("Stats for a runner that is not there = %+v, want nothing", got)
	}

	// CPU is left at zero even on Linux: sampling it properly means holding
	// state between calls, and the host's own tooling does that better.
	if runtime.GOOS == "linux" && got.CPUPercent != 0 {
		t.Fatalf("CPU = %v, want zero", got.CPUPercent)
	}
}

func sameFile(t *testing.T, a, b string) bool {
	t.Helper()
	ai, err := os.Stat(a)
	if err != nil {
		t.Fatal(err)
	}
	bi, err := os.Stat(b)
	if err != nil {
		t.Fatal(err)
	}
	return os.SameFile(ai, bi)
}

