// The runner image verifies its download against digests written into the
// Dockerfile, and the process backend against the generated table. They are
// the same release, so they had better be the same numbers; the bump workflow
// copies them from the table, and this is what catches a hand edit of one.
func TestTheRunnerImagePinsTheSameDigestsAsTheProcessBackend(t *testing.T) {
	dockerfile, err := os.ReadFile(filepath.Join("..", "..", "deploy", "Dockerfile.runner"))
	if err != nil {
		t.Fatalf("reading the runner Dockerfile: %v", err)
	}
	for arch, arg := range map[string]string{"x64": "RUNNER_SHA256_X64", "arm64": "RUNNER_SHA256_ARM64"} {
		want := knownRunnerSHA256[DefaultRunnerVersion+"/actions-runner-linux-"+arch+"-"+DefaultRunnerVersion+".tar.gz"]
		if want == "" {
			t.Fatalf("the digest table has no linux-%s entry for %s", arch, DefaultRunnerVersion)
		}
		if !strings.Contains(string(dockerfile), "ARG "+arg+"="+want) {
			t.Fatalf("deploy/Dockerfile.runner does not pin %s to the table's digest %s for %s", arg, want, DefaultRunnerVersion)
		}
	}
	if !strings.Contains(string(dockerfile), "ARG RUNNER_VERSION="+DefaultRunnerVersion) {
		t.Fatalf("deploy/Dockerfile.runner pins a different runner version from DefaultRunnerVersion %s", DefaultRunnerVersion)
	}
}

// The JIT config is a credential. On the command line it is in
// /proc/<pid>/cmdline, which every account on the host can read; the runner
// takes it from the environment just as happily, and the container backends
// already hand it over that way.
func TestProcessKeepsTheJITConfigOffTheCommandLine(t *testing.T) {
	requireUnix(t)
	b, _ := newStubProcessBackend(t)
	ctx := context.Background()

	spec := processSpec()
	h, err := b.Create(ctx, spec)
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	t.Cleanup(func() { _ = b.Remove(context.Background(), h) })

	dir := string(h)
	waitForLog(t, dir, "listener started", 5*time.Second)

	args, err := os.ReadFile(filepath.Join(dir, "listener-args.txt"))
	if err != nil {
		t.Fatalf("reading the listener's arguments: %v", err)
	}
	if got := strings.TrimSpace(string(args)); got != "run" {
		t.Fatalf("listener arguments = %q, want just \"run\"", got)
	}
	if strings.Contains(string(args), spec.Credentials.JITConfig) {
		t.Fatal("the JIT config is on the command line, where ps can read it")
	}

	jit, err := os.ReadFile(filepath.Join(dir, "listener-jitconfig.txt"))
	if err != nil {
		t.Fatalf("reading the listener's environment: %v", err)
	}
	if string(jit) != spec.Credentials.JITConfig {
		t.Fatalf("%s = %q, want the JIT config", EnvUpstreamJITConfig, jit)
	}
}

// stubDeaf ignores the interrupt Stop sends first, so that stopping it has to
// go through the kill, which is the path this file's other tests never take.
//
// Ignoring a signal is installed the same way as handling one, so the order
// here matters for the same reason it does in stubListener: announce after the
// trap, or a SIGINT that lands in between kills the shell and the kill path
// this test exists for is never reached.
const stubDeaf = `#!/bin/sh
trap '' INT
echo "listener started with $1"
i=0
while [ $i -lt 120 ]; do
  sleep 1
  i=$((i + 1))
done
`

// SIGKILL is delivered, not applied: the process is still there, with its files
// still open, for as long as the kernel takes to tear it down. Stop used to
// return the moment the signal was sent, and what the caller does next is
// delete the directory the runner is running in -- so a create replacing a
// runner could fail on a directory that would not stay empty, and a remove
// could half-succeed against a process still writing into it.
func TestStoppingARunnerThatIgnoresTheInterruptWaitsForItToDie(t *testing.T) {
	requireUnix(t)
	root := t.TempDir()
	installStubRunner(t, root, stubVersion, stubDeaf, stubConfigOK)
	b, err := NewProcess(ProcessOptions{WorkDir: root, RunnerVersion: stubVersion, Logger: quietLogger()})
	if err != nil {
		t.Fatalf("NewProcess: %v", err)
	}
	ctx := context.Background()

	h, err := b.Create(ctx, processSpec())
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	waitForPhase(t, b, h, PhaseRunning, 5*time.Second)
	waitForLog(t, string(h), "listener started", 5*time.Second)
	pid := readPID(string(h))
	if pid <= 0 || !processAlive(pid) {
		t.Fatalf("the runner is not running to begin with, pid = %d", pid)
	}

	// A short interrupt timeout, so the kill is reached quickly. The runner
	// ignores the interrupt, so this is the only thing that ends it.
	if err := b.Stop(ctx, h, 300*time.Millisecond); err != nil {
		t.Fatalf("stop: %v", err)
	}

	if processAlive(pid) {
		t.Fatal("Stop returned while the runner it killed was still running")
	}
	// And the directory it was running in can now be removed, which is what
	// the caller does next.
	if err := b.Remove(ctx, h); err != nil {
		t.Fatalf("removing a runner that has just been killed: %v", err)
	}
}

// The process being gone is not the end of the writing: the goroutine reaping
// it records the exit code in the runner's own directory, and it gets there a
// moment after the process disappears -- a moment the removal is already
// spending inside RemoveAll. The walk deletes what it found, the exit record
// lands behind it, and the rmdir meets a directory that is not empty. CI found
// this as "directory not empty" from a create replacing an existing runner,
// which is a fleet failing to start a runner rather than a test being unlucky.
//
// Staged rather than raced: a reaper that never finishes, so that whether the
// removal waits for one is the only thing being measured. Waiting for a real
// exit to be recorded takes microseconds, and a test that hopes to land inside
// those is a test that passes whatever the code does.
func TestRemovingARunnerWaitsForItsExitToBeRecorded(t *testing.T) {
	requireUnix(t)
	b, _ := newStubProcessBackend(t)

	dir := b.runnerDir("zoomies-host-a1b2")
	if err := os.MkdirAll(filepath.Join(dir, runnerWorkDir), 0o750); err != nil {
		t.Fatal(err)
	}
	b.mu.Lock()
	b.running[dir] = &child{reaped: make(chan struct{})}
	b.mu.Unlock()

	// The context is what ends the wait, since this reaper never will. Without
	// a wait at all the removal returns in microseconds.
	ctx, cancel := context.WithTimeout(context.Background(), 250*time.Millisecond)
	defer cancel()
	started := time.Now()
	if err := b.Remove(ctx, Handle(dir)); err != nil {
		t.Fatalf("remove: %v", err)
	}
	if waited := time.Since(started); waited < 200*time.Millisecond {
		t.Fatalf("Remove returned after %s, so it deleted the directory while the exit was still being recorded into it", waited)
	}
	// And it still removes the directory: a reaper that will not finish is a
	// reason to wait, not a reason to leave a runner on the host for ever.
	if _, err := os.Stat(dir); !os.IsNotExist(err) {
		t.Fatalf("the runner directory is still there: %v", err)
	}
}

// The same sequence the CI failure came from, run enough times that the window
// between the process exiting and its exit record landing is hit rather than
// hoped past.
func TestReplacingARunnerRepeatedlyNeverTripsOverItsOwnExitRecord(t *testing.T) {
	requireUnix(t)
	b, _ := newStubProcessBackend(t)
	ctx := context.Background()

	for i := range 12 {
		h, err := b.Create(ctx, processSpec())
		if err != nil {
			t.Fatalf("create %d: %v", i, err)
		}
		waitForPhase(t, b, h, PhaseRunning, 5*time.Second)
		waitForLog(t, string(h), "listener started", 5*time.Second)
	}
	if err := b.Remove(ctx, Handle(b.runnerDir(processSpec().Name))); err != nil {
		t.Fatalf("remove: %v", err)
	}
}

// TestProcessChildEnvironmentIsBuiltNotInherited is the process backend's
// side of the isolation the container backends get from the container. A
// job's steps run as ordinary processes on the agent's machine, so anything
// left in the agent's environment would be readable by every workflow the
// fleet runs -- and on a single-VM install the agent is inside the controller,
// whose environment holds the database path, the encryption key and the GitHub
// App's private key.
//
// The parent is poisoned with the things that would actually be there.
func TestProcessChildEnvironmentIsBuiltNotInherited(t *testing.T) {
	b := &ProcessBackend{}

	poison := map[string]string{
		"ZOOMIES_ENCRYPTION_KEY":        "3d5f0a1b-the-key-that-decrypts-every-installation",
		"ZOOMIES_GITHUB_PRIVATE_KEY":    "-----BEGIN RSA PRIVATE KEY-----\nMIIEow...\n",
		"ZOOMIES_GITHUB_WEBHOOK_SECRET": "the-webhook-hmac-secret",
		"ZOOMIES_DATABASE":              "/var/lib/zoomies/zoomies.db",
		"ZOOMIES_AGENT_TOKEN":           "zag_this_hosts_own_credential",
		"GITHUB_TOKEN":                  "ghp_a_token_the_operator_exported",
		"AWS_SECRET_ACCESS_KEY":         "an-unrelated-secret-that-happened-to-be-there",
		"SSH_AUTH_SOCK":                 "/tmp/ssh-agent.sock",
	}
	for k, v := range poison {
		t.Setenv(k, v)
	}
	// The agent's own home must not become the runner's: the runner writes its
	// credentials and state next to it.
	t.Setenv("HOME", "/root")

	dir := t.TempDir()
	spec := Spec{Name: "zoomies-runner-1", Ephemeral: true, Env: map[string]string{
		"RUNNER_ALLOW_RUNASROOT": "1",
		"ZOOMIES_POOL":           "linux-x64",
	}}
	env := b.childEnv(spec, dir)

	got := map[string]string{}
	for _, kv := range env {
		k, v, ok := strings.Cut(kv, "=")
		if !ok {
			t.Fatalf("childEnv produced %q, which is not a KEY=VALUE pair", kv)
		}
		got[k] = v
	}

	for k, v := range poison {
		if _, present := got[k]; present {
			t.Errorf("the runner's environment carries %s from the agent's", k)
		}
		// Not merely absent under that name: absent as a value, so a rename
		// or a well-meaning "pass the proxy settings through" that widened
		// the allowlist would still be caught.
		for _, kv := range env {
			if strings.Contains(kv, v) {
				t.Errorf("%s's value reached the runner as %q", k, kv)
			}
		}
	}

	if got["HOME"] != dir {
		t.Errorf("HOME = %q, want the runner's own directory %q", got["HOME"], dir)
	}
	if got["ZOOMIES_POOL"] != "linux-x64" {
		t.Errorf("the controller's own spec.Env did not reach the runner: %v", got)
	}
}

// TestProcessChildEnvironmentPassesTheAllowlistThrough is the other half: the
// allowlist exists because a runner behind a corporate proxy or in a non-UTC
// timezone needs those settings, and dropping them would make the backend
// unusable rather than safe. Both halves have to be asserted, or "return nil"
// would pass the test above.
func TestProcessChildEnvironmentPassesTheAllowlistThrough(t *testing.T) {
	b := &ProcessBackend{}

	allowed := map[string]string{
		"LANG":                                  "en_GB.UTF-8",
		"LC_ALL":                                "en_GB.UTF-8",
		"TZ":                                    "Europe/London",
		"HTTP_PROXY":                            "http://proxy.example.com:3128",
		"HTTPS_PROXY":                           "http://proxy.example.com:3128",
		"NO_PROXY":                              "localhost,10.0.0.0/8",
		"http_proxy":                            "http://proxy.example.com:3128",
		"https_proxy":                           "http://proxy.example.com:3128",
		"no_proxy":                              "localhost,10.0.0.0/8",
		"DOTNET_SYSTEM_GLOBALIZATION_INVARIANT": "1",
	}
	for k, v := range allowed {
		t.Setenv(k, v)
	}
	t.Setenv("PATH", "/opt/toolcache/bin:/usr/bin")

	env := b.childEnv(Spec{Name: "zoomies-runner-1"}, t.TempDir())
	got := map[string]string{}
	for _, kv := range env {
		k, v, _ := strings.Cut(kv, "=")
		got[k] = v
	}

	for k, want := range allowed {
		if got[k] != want {
			t.Errorf("%s = %q, want %q -- a runner needs the agent's proxy and locale settings", k, got[k], want)
		}
	}
	if got["PATH"] != "/opt/toolcache/bin:/usr/bin" {
		t.Errorf("PATH = %q, want the agent's -- it is how the runner finds its toolchain", got["PATH"])
	}

	// A variable on the allowlist that the agent does not have is left unset
	// rather than set empty: an empty TZ is not the same as no TZ, and the
	// runner's own defaulting is better than a blank.
	t.Setenv("TZ", "Europe/London") // registers the cleanup that restores it
	os.Unsetenv("TZ")
	withoutTZ := map[string]string{}
	for _, kv := range b.childEnv(Spec{Name: "zoomies-runner-1"}, t.TempDir()) {
		k, v, _ := strings.Cut(kv, "=")
		withoutTZ[k] = v
	}
	if v, present := withoutTZ["TZ"]; present {
		t.Errorf("TZ = %q was invented for a runner whose agent has no TZ set", v)
	}

	// And PATH is the one variable with a fallback, because a runner with no
	// PATH finds no tools at all -- not even the ones it downloaded.
	t.Setenv("PATH", "")
	for _, kv := range b.childEnv(Spec{Name: "zoomies-runner-1"}, t.TempDir()) {
		if kv == "PATH=" {
			t.Error("an empty PATH was passed through instead of the fallback")
		}
	}
}

// TestAnAbandonedRunnerDirectoryIsListedSoItCanBeReaped closes a leak with
// nothing else watching it.
//
// Create makes the runner's directory and clones the tools tree into it --
// hundreds of megabytes -- before it writes the metadata. An agent killed in
// that window leaves the tree behind, and List used to skip a directory whose
// metadata would not read. Nothing else walks this tree, so the copy stayed on
// the host until somebody went looking for the disk.
func TestAnAbandonedRunnerDirectoryIsListedSoItCanBeReaped(t *testing.T) {
	b, workDir := newStubProcessBackend(t)
	root := filepath.Join(workDir, runnersDirName)

	// The shape Create leaves behind when it dies between MkdirAll and
	// writeMeta: a directory, some of the tree, and no runner.json.
	dir := filepath.Join(root, "zoomies-abandoned")
	if err := os.MkdirAll(filepath.Join(dir, "bin"), 0o750); err != nil {
		t.Fatalf("staging the abandoned directory: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "bin", "Runner.Listener"), []byte("stub"), 0o750); err != nil {
		t.Fatalf("staging the tools copy: %v", err)
	}

	// Still being written: nothing may touch it yet.
	fresh, err := b.List(context.Background())
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	for _, w := range fresh {
		if string(w.Handle) == dir {
			t.Fatal("a directory written moments ago was reported as abandoned; " +
				"a create in progress would be removed out from under itself")
		}
	}

	// Nothing has written to it for longer than a create could take.
	old := time.Now().Add(-abandonedGrace - time.Minute)
	if err := os.Chtimes(dir, old, old); err != nil {
		t.Fatalf("ageing the directory: %v", err)
	}

	listed, err := b.List(context.Background())
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	var found *Workload
	for i, w := range listed {
		if string(w.Handle) == dir {
			found = &listed[i]
		}
	}
	if found == nil {
		t.Fatal("an abandoned runner directory was not listed, so nothing will ever remove it")
	}
	if found.Status.Phase != PhaseGone {
		t.Errorf("phase = %q, want %q: there is no process here to be anything else",
			found.Status.Phase, PhaseGone)
	}
	// No runner ID, because there is nothing to read one from. The agent's
	// orphan path removes the workload and reports nothing, so no row moves on
	// the strength of a directory nobody can identify.
	if found.RunnerID != "" {
		t.Errorf("runner = %q, want none: the metadata is what carries it and it is unreadable", found.RunnerID)
	}

	// And it can actually be removed, which is the whole point of listing it.
	if err := b.Remove(context.Background(), found.Handle); err != nil {
		t.Fatalf("Remove: %v", err)
	}
	if _, err := os.Stat(dir); !errors.Is(err, fs.ErrNotExist) {
		t.Fatalf("the directory is still there after Remove: %v", err)
	}
}

//go:build !windows

package backend

import (
	"errors"
	"os"
	"os/exec"
	"syscall"
	"time"
)

// The parts of the process backend that differ by operating system. Each has a
// twin in process_windows.go, and the two files together are the whole of what
// "the process backend runs on Windows" cost: everything above them is the same
// lifecycle, the same layout on disk, and the same records in it.
const (
	// exeSuffix is what a runner binary's name ends in here, which is nothing.
	exeSuffix = ""
	// configScript is the registration script a non-ephemeral pool runs.
	configScript = "config.sh"
	// removeGrace is how long a directory removal keeps trying after it first
	// fails. POSIX unlinks a file whose process is still running, so a
	// removal here either works or names a real problem, and there is nothing
	// to wait for.
	removeGrace = 0 * time.Second
)

// noShellDetail is why the process backend is unavailable on a host with no
// shell, in the words the Hosts page shows.
const noShellDetail = "no shell is installed (sh is not in PATH), so nothing actions/runner starts could run here; " +
	"the published Zoomies image is built without one on purpose -- from a container, use the docker or podman backend, " +
	"and use the process backend only on a host with a shell, tar and libicu"

// HasShell reports whether this host has a shell, which the runner's config.sh
// and every `run:` step need.
//
// It is checked before ICU because it decides what kind of host this is. The
// published Zoomies image is distroless -- no shell at all, on purpose -- so an
// agent running in it can never use this backend, and telling that operator to
// apt-get install libicu, into an image with no apt, sends them the wrong way.
func HasShell() bool {
	_, err := exec.LookPath("sh")
	return err == nil
}

// detachRunner starts the runner as the leader of a process group of its own.
//
// Two things follow. A signal meant for the runner reaches its whole worker
// tree -- Runner.Listener spawns Runner.Worker per job, and interrupting the
// listener alone orphaned the worker with the job still running. And a signal
// meant for the agent does not reach the runner: a terminal's Ctrl-C, or a
// service manager stopping the unit, stays with the agent's own group.
func detachRunner(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
}

// adoptRunner is called once the runner has started. The process group above
// is all the grouping a POSIX host needs, so there is nothing to add.
func adoptRunner(*exec.Cmd) {}

// releaseRunner is called once the runner has been reaped. Nothing was held
// for it here.
func releaseRunner(int) {}

// signalRunner delivers sig to the runner's process group. A group that is
// already gone answers os.ErrProcessDone, so callers treat it as the other
// "already exited" answers.
func signalRunner(proc *os.Process, sig syscall.Signal) error {
	err := syscall.Kill(-proc.Pid, sig)
	if errors.Is(err, syscall.ESRCH) {
		return os.ErrProcessDone
	}
	return err
}

// processAlive reports whether a pid is still running. Signal 0 performs the
// permission and existence checks without delivering anything.
func processAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	proc, err := os.FindProcess(pid)
	if err != nil {
		return false
	}
	return proc.Signal(syscall.Signal(0)) == nil
}

// platformChildEnv is what a runner's environment needs beyond the portable
// part childEnv builds. A POSIX runner needs nothing more than HOME and PATH.
func platformChildEnv(string) []string { return nil }

//go:build windows

package backend

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"sync"
	"syscall"
	"time"

	"golang.org/x/sys/windows"
)

// The Windows half of the process backend. It exists so that a Windows host
// can join a fleet and run actions/runner's win-x64 build as a process, which
// is the shape decision 26 in the roadmap chose: no Windows containers, and so
// no ephemeral container -- a job gets a fresh work directory and a single-use
// registration on a machine that keeps its state, exactly what the process
// backend already means on Linux. The docs say so where the guarantee is
// claimed.
//
// Nothing in this file has been run on a Windows host by this repository's
// tests yet; the support matrix records it as built and unit-tested, and the
// beta is where it earns the next column.
const (
	// exeSuffix is what a runner binary's name ends in: bin/Runner.Listener
	// is bin/Runner.Listener.exe in the win-x64 archive.
	exeSuffix = ".exe"
	// configScript is the registration script a non-ephemeral pool runs.
	configScript = "config.cmd"
	// removeGrace is how long a directory removal keeps trying after it first
	// fails. Windows refuses to delete a file another process holds open, and
	// a runner that has just been terminated can leave a handle on its own
	// log or its work tree for a moment after the process is gone. One
	// RemoveAll would turn that moment into runners.cleanup_failed; a retry
	// with backoff turns it into a removal that converges.
	removeGrace = 30 * time.Second
)

// noShellDetail is why the process backend is unavailable on a Windows host
// with no command interpreter, which is a host so unusual it is worth naming.
const noShellDetail = "cmd.exe is not on PATH, so nothing actions/runner starts could run here; " +
	"the process backend on Windows needs the command interpreter and PowerShell that every Windows installation ships, " +
	"so check the service's PATH and the ComSpec variable"

// HasShell reports whether this host has a command interpreter, which the
// runner's config.cmd and every `run:` step need.
func HasShell() bool {
	_, err := exec.LookPath("cmd")
	return err == nil
}

// jobs tracks the job object each runner this agent started was put in, by
// pid. A job object is Windows' answer to a process group: terminating it
// terminates every process that was ever assigned to it, including the
// Runner.Worker the listener spawns per job and whatever msbuild that worker
// started, so killing a runner does not leave its children behind on a
// machine whose state persists.
var jobs = struct {
	sync.Mutex
	byPID map[int]windows.Handle
}{byPID: map[int]windows.Handle{}}

// detachRunner starts the runner in a console process group of its own, so a
// Ctrl-C at the agent's console does not reach it. The job object is added
// after the start, because a process is assigned to a job by handle and the
// handle does not exist before then.
func detachRunner(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{CreationFlags: windows.CREATE_NEW_PROCESS_GROUP}
}

// adoptRunner puts a started runner into a job object of its own.
//
// The job deliberately has no kill-on-close limit: when the agent exits, its
// handle closes and the job object simply stops being tracked, so an agent
// restart leaves the runner running exactly as it does on Linux. What the job
// is for is the other direction -- a runner this agent decides to kill takes
// its whole tree with it.
//
// Every failure here is swallowed. A runner that could not be put in a job is
// still a runner; killing it later falls back to taskkill, which walks the
// tree by parentage instead, and a start that succeeded must not be reported
// as a failure over an accounting detail.
func adoptRunner(cmd *exec.Cmd) {
	if cmd.Process == nil {
		return
	}
	job, err := windows.CreateJobObject(nil, nil)
	if err != nil {
		return
	}
	proc, err := windows.OpenProcess(windows.PROCESS_SET_QUOTA|windows.PROCESS_TERMINATE, false, uint32(cmd.Process.Pid))
	if err != nil {
		_ = windows.CloseHandle(job)
		return
	}
	defer windows.CloseHandle(proc)
	if err := windows.AssignProcessToJobObject(job, proc); err != nil {
		_ = windows.CloseHandle(job)
		return
	}
	jobs.Lock()
	jobs.byPID[cmd.Process.Pid] = job
	jobs.Unlock()
}

// releaseRunner closes the job handle of a runner that has been reaped.
func releaseRunner(pid int) {
	jobs.Lock()
	defer jobs.Unlock()
	if job, ok := jobs.byPID[pid]; ok {
		_ = windows.CloseHandle(job)
		delete(jobs.byPID, pid)
	}
}

// signalRunner can only kill on Windows. There is no interrupt to deliver to
// a process that has no console of ours to receive it on -- a service has no
// console at all -- so a drain is a kill here, and the docs say so.
//
// A runner this agent started is killed through its job object, tree and all.
// One adopted after an agent restart has no job handle here, so taskkill /T
// walks its tree by parent pid instead; that misses a child whose parent has
// already exited, which is the honest limit of the adopted case.
func signalRunner(proc *os.Process, sig syscall.Signal) error {
	if sig != syscall.SIGKILL {
		return syscall.EWINDOWS
	}
	jobs.Lock()
	job, ok := jobs.byPID[proc.Pid]
	jobs.Unlock()
	if ok {
		if err := windows.TerminateJobObject(job, 137); err == nil {
			return nil
		}
	}
	killCtx, cancel := context.WithTimeout(context.Background(), killGrace)
	defer cancel()
	out, err := exec.CommandContext(killCtx, "taskkill", "/T", "/F", "/PID", strconv.Itoa(proc.Pid)).CombinedOutput()
	if err != nil {
		if !processAlive(proc.Pid) {
			return os.ErrProcessDone
		}
		return fmt.Errorf("taskkill: %w: %s", err, lastLine(out))
	}
	return nil
}

// stillActive is the exit code GetExitCodeProcess reports for a process that
// has not exited (STATUS_PENDING).
const stillActive = 259

// processAlive reports whether a pid is still running. Opening the process
// for limited query is the least privilege that answers the question, and a
// pid nothing answers for is a process that is gone.
func processAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid))
	if err != nil {
		return false
	}
	defer windows.CloseHandle(h)
	var code uint32
	if err := windows.GetExitCodeProcess(h, &code); err != nil {
		return false
	}
	return code == stillActive
}

// platformChildEnv is what a Windows runner needs beyond HOME and PATH. The
// .NET runtime refuses to start without SystemRoot, cmd.exe wants ComSpec and
// PATHEXT, and the runner's own home is USERPROFILE rather than HOME. These
// are passed through from the agent rather than invented, and the list is an
// allowlist for the same reason childEnv's is: a job must not inherit
// whatever else happened to be in the service's environment.
func platformChildEnv(dir string) []string {
	env := []string{"USERPROFILE=" + dir}
	for _, k := range []string{
		"SystemRoot", "SystemDrive", "windir", "ComSpec", "PATHEXT",
		"TEMP", "TMP", "ProgramData", "ProgramFiles", "ProgramFiles(x86)", "ProgramW6432",
		"ALLUSERSPROFILE", "LOCALAPPDATA", "APPDATA", "PSModulePath",
		"NUMBER_OF_PROCESSORS", "PROCESSOR_ARCHITECTURE", "USERNAME", "USERDOMAIN",
	} {
		if v, ok := os.LookupEnv(k); ok {
			env = append(env, k+"="+v)
		}
	}
	return env
}

package backend

// proxyEnvKeys are the proxy variables a runner inherits from the agent that
// starts it. Both spellings are carried because tools disagree about which one
// they read: curl honours only the lowercase http_proxy, Go and most package
// managers read either, and a runner behind a proxy that half its tools ignore
// fails in ways that look like flaky networking rather than configuration.
var proxyEnvKeys = []string{"HTTP_PROXY", "HTTPS_PROXY", "NO_PROXY", "http_proxy", "https_proxy", "no_proxy"}

// inheritedProxyEnv returns the agent's proxy variables as KEY=value pairs, in
// a stable order, leaving out any the pool sets itself.
//
// A host that can only reach GitHub through a proxy has its agent configured
// with one already -- the agent could not long-poll the controller or pull an
// image otherwise -- so a runner that did not inherit it would fail on its
// first checkout. The pool's own value wins, including an empty one, which is
// how a pool opts its runners out of a proxy the host needs.
func inheritedProxyEnv(lookup func(string) (string, bool), pool map[string]string) []string {
	var env []string
	for _, k := range proxyEnvKeys {
		if _, set := pool[k]; set {
			continue
		}
		if v, ok := lookup(k); ok {
			env = append(env, k+"="+v)
		}
	}
	return env
}

package backend

import (
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"
)

func proxyLookup(vars map[string]string) func(string) (string, bool) {
	return func(k string) (string, bool) {
		v, ok := vars[k]
		return v, ok
	}
}

// A host behind a proxy configures its agent with one; a runner that did not
// inherit it would fail its first checkout with nothing pointing at why.
func TestContainerRunnersInheritTheAgentsProxy(t *testing.T) {
	spec := jitSpec()
	agent := map[string]string{
		"HTTPS_PROXY": "http://proxy.corp:3128",
		"no_proxy":    ".corp",
		"UNRELATED":   "must not leak",
	}
	o := containerOptions{Now: time.Now(), ProxyEnv: inheritedProxyEnv(proxyLookup(agent), spec.Env)}
	env := buildRunnerConfig(spec, dockerFlavor(), o).Env
	for _, want := range []string{"HTTPS_PROXY=http://proxy.corp:3128", "no_proxy=.corp"} {
		if !slices.Contains(env, want) {
			t.Errorf("runner env is missing %q: %v", want, env)
		}
	}
	for _, e := range env {
		if e == "UNRELATED=must not leak" {
			t.Errorf("runner inherited a variable that is not a proxy setting: %v", env)
		}
	}
}

// The pool is the more specific statement, and an empty value is how a pool
// says its runners must go direct although the host needs a proxy.
func TestAPoolsOwnProxyWinsOverTheAgents(t *testing.T) {
	spec := jitSpec()
	spec.Env = map[string]string{"HTTPS_PROXY": "", "HTTP_PROXY": "http://pool:8080"}
	agent := map[string]string{"HTTPS_PROXY": "http://agent:3128", "HTTP_PROXY": "http://agent:3128", "NO_PROXY": "localhost"}
	o := containerOptions{Now: time.Now(), ProxyEnv: inheritedProxyEnv(proxyLookup(agent), spec.Env)}

	for name, env := range map[string][]string{
		"runner":  buildRunnerConfig(spec, dockerFlavor(), o).Env,
		"sidecar": buildDinDConfig(spec, dockerFlavor(), o).Env,
	} {
		for _, e := range env {
			if e == "HTTPS_PROXY=http://agent:3128" || e == "HTTP_PROXY=http://agent:3128" {
				t.Errorf("%s: the agent's proxy overrode the pool's: %v", name, env)
			}
		}
		for _, want := range []string{"HTTPS_PROXY=", "HTTP_PROXY=http://pool:8080", "NO_PROXY=localhost"} {
			if !slices.Contains(env, want) {
				t.Errorf("%s env is missing %q: %v", name, want, env)
			}
		}
	}
}

// The docker-in-docker daemon pulls the images a job's builds name, so it needs
// the proxy too -- but none of the job's other variables.
func TestTheDockerSidecarGetsTheProxyAndNothingElseFromThePool(t *testing.T) {
	spec := jitSpec()
	o := containerOptions{Now: time.Now(), ProxyEnv: inheritedProxyEnv(proxyLookup(map[string]string{"http_proxy": "http://p:1"}), spec.Env)}
	env := buildDinDConfig(spec, dockerFlavor(), o).Env
	if !slices.Contains(env, "http_proxy=http://p:1") || !slices.Contains(env, "DOCKER_TLS_CERTDIR=") {
		t.Fatalf("sidecar env = %v, want the proxy and DOCKER_TLS_CERTDIR", env)
	}
	for _, e := range env {
		if e == "ZULU=last" || e == "ALPHA=first" {
			t.Errorf("sidecar received a pool variable meant for the job: %v", env)
		}
	}
}

func TestNoProxyInheritedWhenTheAgentHasNone(t *testing.T) {
	if got := inheritedProxyEnv(proxyLookup(nil), nil); len(got) != 0 {
		t.Fatalf("inheritedProxyEnv = %v, want nothing", got)
	}
}

// A runner behind a proxy is handed these variables, and the stock image gives
// it passwordless sudo because real workflows `sudo apt-get install`. sudo's
// default env_reset dropped every one of them, so the install timed out on a
// host whose runners could otherwise reach the internet. The image's sudoers
// entry keeps them; this holds it to the list the agent actually passes on.
func TestTheRunnerImageKeepsTheProxyThroughSudo(t *testing.T) {
	dockerfile := readFile(t, filepath.Join("..", "..", "deploy", "Dockerfile.runner"))
	var keep string
	for _, line := range strings.Split(dockerfile, "\n") {
		if _, rest, ok := strings.Cut(line, "Defaults:runner env_keep += \""); ok {
			keep, _, _ = strings.Cut(rest, "\"")
			break
		}
	}
	if keep == "" {
		t.Fatal("deploy/Dockerfile.runner has no Defaults:runner env_keep line, so sudo drops the runner's proxy")
	}
	kept := strings.Fields(keep)
	for _, k := range proxyEnvKeys {
		if !slices.Contains(kept, k) {
			t.Errorf("deploy/Dockerfile.runner's env_keep does not carry %s, which the agent passes to every runner", k)
		}
	}
}

package backend

import "strings"

// DockerHubRegistry is the registry an image reference with no registry part
// resolves to. It is named as docker.io rather than the index host the daemon
// actually dials, because that is what an operator allowing egress, or
// logging in, writes.
const DockerHubRegistry = "docker.io"

// RegistryHost is the registry an image reference is pulled from, by the
// daemon's own rule: the first path component is a registry only when it
// looks like a host -- it has a dot or a port, or is localhost -- and
// otherwise the image is on Docker Hub. "ubuntu", "library/ubuntu" and
// "eyupio/runner" are all docker.io; "ghcr.io/eyupio/runner" is ghcr.io and
// "registry.internal:5000/runner" keeps its port, because the port is part of
// what a firewall rule has to allow.
//
// It is what turns "the image would not pull" into "this host cannot reach
// ghcr.io", which is the sentence an operator can act on.
func RegistryHost(image string) string {
	image = strings.TrimSpace(image)
	if image == "" {
		return ""
	}
	first, _, found := strings.Cut(image, "/")
	if !found {
		return DockerHubRegistry
	}
	if strings.ContainsAny(first, ".:") || first == "localhost" {
		first = strings.ToLower(first)
		// Docker Hub's own hostnames are the same registry as a bare name.
		if first == "index.docker.io" || first == "registry-1.docker.io" {
			return DockerHubRegistry
		}
		return first
	}
	return DockerHubRegistry
}

package backend

import "testing"

// The registry is the thing a blocked egress rule or a missing login is
// about, so naming the wrong one sends an operator to fix a firewall for a
// host that was never the problem.
func TestRegistryHostNamesWhereAnImageIsPulledFrom(t *testing.T) {
	for _, tc := range []struct{ image, want string }{
		{"ubuntu", "docker.io"},
		{"ubuntu:24.04", "docker.io"},
		{"library/ubuntu", "docker.io"},
		{"eyupio/runner:latest", "docker.io"},
		{"docker.io/library/ubuntu", "docker.io"},
		{"index.docker.io/eyupio/runner", "docker.io"},
		{"ghcr.io/eyupio/zoomies-runner:ubuntu-24.04", "ghcr.io"},
		{"GHCR.IO/eyupio/runner", "ghcr.io"},
		{"ghcr.io/eyupio/runner@sha256:0123abcd", "ghcr.io"},
		{"registry.internal:5000/runner", "registry.internal:5000"},
		{"10.0.0.4:5000/team/runner:1", "10.0.0.4:5000"},
		{"localhost/runner", "localhost"},
		{"localhost:5000/runner", "localhost:5000"},
		{"", ""},
		{"  ", ""},
	} {
		if got := RegistryHost(tc.image); got != tc.want {
			t.Errorf("RegistryHost(%q) = %q, want %q", tc.image, got, tc.want)
		}
	}
}

package backend

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"path"
	"strings"
)

// ContainerReplacement retains the full deployment configuration, not just the
// subset the runner backend uses. Dropping an unknown host option while
// upgrading an agent would silently change the operator's isolation or mounts.
type ContainerReplacement struct {
	ID      string
	Name    string
	Image   string
	Running bool
	body    map[string]json.RawMessage
}

// PrepareReplacement reads without changing anything. The returned request
// keeps credentials, mounts, ports and runtime options from the old container.
func (c *APIClient) PrepareReplacement(ctx context.Context, id, image string) (*ContainerReplacement, error) {
	var old struct {
		ID         string `json:"Id"`
		Name       string
		Config     map[string]json.RawMessage
		HostConfig map[string]json.RawMessage
		State      ContainerState
		Mounts     []struct {
			Type, Name, Source, Destination, Mode string
			RW                                    bool
		}
		NetworkSettings struct {
			Networks map[string]map[string]json.RawMessage
		}
	}
	if err := c.do(ctx, http.MethodGet, "/containers/"+url.PathEscape(id)+"/json", nil, nil, &old); err != nil {
		return nil, err
	}
	if old.ID == "" || old.Config == nil || old.HostConfig == nil {
		return nil, fmt.Errorf("docker api: container %s has no complete configuration", id)
	}
	if string(old.HostConfig["AutoRemove"]) == "true" {
		return nil, fmt.Errorf("docker api: %s uses automatic removal; recreate it manually so its data can be preserved", id)
	}
	var previousImage string
	_ = json.Unmarshal(old.Config["Image"], &previousImage)
	old.Config["Image"], _ = json.Marshal(image)

	// Image-declared anonymous volumes must be attached by their existing name;
	// otherwise Docker allocates empty ones when the replacement is created.
	var binds []string
	_ = json.Unmarshal(old.HostConfig["Binds"], &binds)
	var explicit []struct{ Target string }
	_ = json.Unmarshal(old.HostConfig["Mounts"], &explicit)
	for _, mount := range old.Mounts {
		if mount.Type != "volume" {
			continue
		}
		found := false
		for _, bind := range binds {
			parts := strings.Split(bind, ":")
			if len(parts) > 1 && parts[1] == mount.Destination {
				found = true
			}
		}
		for _, m := range explicit {
			if m.Target == mount.Destination {
				found = true
			}
		}
		if !found {
			mode := "rw"
			if !mount.RW {
				mode = "ro"
			}
			binds = append(binds, mount.Name+":"+mount.Destination+":"+mode)
		}
	}
	old.HostConfig["Binds"], _ = json.Marshal(binds)
	old.Config["HostConfig"], _ = json.Marshal(old.HostConfig)
	endpoints := map[string]map[string]json.RawMessage{}
	for name, settings := range old.NetworkSettings.Networks {
		endpoint := map[string]json.RawMessage{}
		// Runtime-assigned addresses and endpoint IDs are output, not requests.
		for _, key := range []string{"IPAMConfig", "Links", "DriverOpts", "GwPriority"} {
			if value, ok := settings[key]; ok {
				endpoint[key] = value
			}
		}
		var aliases []string
		_ = json.Unmarshal(settings["Aliases"], &aliases)
		kept := []string{}
		for _, alias := range aliases {
			if alias != old.ID && alias != old.ID[:min(12, len(old.ID))] {
				kept = append(kept, alias)
			}
		}
		endpoint["Aliases"], _ = json.Marshal(kept)
		endpoints[name] = endpoint
	}
	old.Config["NetworkingConfig"], _ = json.Marshal(map[string]any{"EndpointsConfig": endpoints})
	return &ContainerReplacement{ID: old.ID, Name: strings.TrimPrefix(old.Name, "/"), Image: previousImage, Running: old.State.Running, body: old.Config}, nil
}

// CreateReplacement creates a stopped container. Its predecessor can remain
// available under a backup name until the new process has successfully started.
func (c *APIClient) CreateReplacement(ctx context.Context, replacement *ContainerReplacement) (string, error) {
	var result struct {
		ID string `json:"Id"`
	}
	if err := c.do(ctx, http.MethodPost, "/containers/create", url.Values{"name": {replacement.Name}}, replacement.body, &result); err != nil {
		return "", err
	}
	return result.ID, nil
}

func (c *APIClient) ContainerRename(ctx context.Context, id, name string) error {
	return c.do(ctx, http.MethodPost, "/containers/"+url.PathEscape(id)+"/rename", url.Values{"name": {name}}, nil, nil)
}

// RemoveContainerKeepingVolumes is for a deployment replacement, whose data
// must survive even when it was put in an anonymous volume.
func (c *APIClient) RemoveContainerKeepingVolumes(ctx context.Context, id string, force bool) error {
	q := url.Values{"v": {"0"}}
	if force {
		q.Set("force", "1")
	}
	return c.do(ctx, http.MethodDelete, "/containers/"+url.PathEscape(id), q, nil, nil)
}

// HasBind reports whether the replacement already mounts something at target,
// by a bind or an explicit mount.
func (r *ContainerReplacement) HasBind(target string) bool {
	for _, t := range r.bindTargets() {
		if t == target {
			return true
		}
	}
	return false
}

// HasBindAbove reports whether the replacement binds a host folder at its own
// path that target is inside, so target is the same folder on both sides and
// a mount of it would add nothing. A volume or a bind to another path does not
// count: inside the container it hides the host's folder rather than showing it.
func (r *ContainerReplacement) HasBindAbove(target string) bool {
	target = path.Clean(target)
	for _, dir := range r.samePathBinds() {
		if dir != "/" && strings.HasPrefix(target, dir+"/") {
			return true
		}
	}
	return false
}

func (r *ContainerReplacement) hostConfig() map[string]json.RawMessage {
	var host map[string]json.RawMessage
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		return nil
	}
	return host
}

func (r *ContainerReplacement) bindTargets() []string {
	host := r.hostConfig()
	var out []string
	var binds []string
	_ = json.Unmarshal(host["Binds"], &binds)
	for _, b := range binds {
		if parts := strings.Split(b, ":"); len(parts) > 1 {
			out = append(out, parts[1])
		}
	}
	var mounts []struct{ Target string }
	_ = json.Unmarshal(host["Mounts"], &mounts)
	for _, m := range mounts {
		out = append(out, m.Target)
	}
	return out
}

func (r *ContainerReplacement) samePathBinds() []string {
	host := r.hostConfig()
	var out []string
	var binds []string
	_ = json.Unmarshal(host["Binds"], &binds)
	for _, b := range binds {
		if parts := strings.Split(b, ":"); len(parts) > 1 && parts[0] == parts[1] && path.IsAbs(parts[0]) {
			out = append(out, path.Clean(parts[0]))
		}
	}
	var mounts []struct{ Type, Source, Target string }
	_ = json.Unmarshal(host["Mounts"], &mounts)
	for _, m := range mounts {
		if m.Type == "bind" && m.Source == m.Target && path.IsAbs(m.Source) {
			out = append(out, path.Clean(m.Source))
		}
	}
	return out
}

// AddBind adds one bind to the replacement, which is how an upgrade gives a
// container a mount its predecessor was created without. Everything else the
// predecessor was created with is kept as it was.
func (r *ContainerReplacement) AddBind(bind string) error {
	var host map[string]json.RawMessage
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		return fmt.Errorf("docker api: the replacement has no host configuration to add %s to: %w", bind, err)
	}
	var binds []string
	_ = json.Unmarshal(host["Binds"], &binds)
	binds = append(binds, bind)
	var err error
	if host["Binds"], err = json.Marshal(binds); err != nil {
		return err
	}
	r.body["HostConfig"], err = json.Marshal(host)
	return err
}

// HasGroup reports whether the replacement already adds group.
func (r *ContainerReplacement) HasGroup(group string) bool {
	var host map[string]json.RawMessage
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		return false
	}
	var groups []string
	_ = json.Unmarshal(host["GroupAdd"], &groups)
	for _, g := range groups {
		if g == group {
			return true
		}
	}
	return false
}

// AddGroup adds a supplementary group to the replacement: the one that owns
// the runtime's socket, for a container created before it was given one.
func (r *ContainerReplacement) AddGroup(group string) error {
	var host map[string]json.RawMessage
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		return fmt.Errorf("docker api: the replacement has no host configuration to add group %s to: %w", group, err)
	}
	var groups []string
	_ = json.Unmarshal(host["GroupAdd"], &groups)
	groups = append(groups, group)
	var err error
	if host["GroupAdd"], err = json.Marshal(groups); err != nil {
		return err
	}
	r.body["HostConfig"], err = json.Marshal(host)
	return err
}

// Env is the environment the replacement will be created with: its
// predecessor's, as `docker inspect` shows it.
func (r *ContainerReplacement) Env() []string {
	var env []string
	_ = json.Unmarshal(r.body["Env"], &env)
	return env
}

// RemoveEnv drops the named variables from the replacement's environment,
// which is how an upgrade stops a container pinning a setting its database
// now holds. Everything else the predecessor was created with is kept.
func (r *ContainerReplacement) RemoveEnv(names map[string]bool) error {
	kept := []string{}
	for _, kv := range r.Env() {
		name, _, _ := strings.Cut(kv, "=")
		if !names[name] {
			kept = append(kept, kv)
		}
	}
	var err error
	r.body["Env"], err = json.Marshal(kept)
	return err
}

package backend

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"
)

func TestContainerReplacementKeepsCredentialsPortsVolumesAndIsolation(t *testing.T) {
	var created map[string]any
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasSuffix(r.URL.Path, "/json") {
			_, _ = w.Write([]byte(`{"Id":"0123456789abcdef","Name":"/zoomies","Config":{"Image":"agent:old","Env":["TOKEN=keep-this"],"User":"65532","Healthcheck":{"Test":["NONE"]}},"HostConfig":{"AutoRemove":false,"Binds":["/socket:/socket"],"PortBindings":{"8080/tcp":[{"HostIp":"127.0.0.1","HostPort":"8081"}]},"SecurityOpt":["no-new-privileges:true"],"CustomFutureOption":true},"Mounts":[{"Type":"volume","Name":"existing-data","Destination":"/var/lib/zoomies","RW":true}],"State":{"Running":true},"NetworkSettings":{"Networks":{"zoomies":{"Aliases":["zoomies","0123456789ab"],"IPAddress":"172.18.0.4","EndpointID":"old-endpoint","IPAMConfig":null}}}}`))
			return
		}
		if strings.HasSuffix(r.URL.Path, "/create") {
			if r.URL.Query().Get("name") != "zoomies" {
				t.Error("wrong name")
			}
			if err := json.NewDecoder(r.Body).Decode(&created); err != nil {
				t.Error(err)
			}
			w.WriteHeader(http.StatusCreated)
			_, _ = w.Write([]byte(`{"Id":"new"}`))
			return
		}
		if r.Method == http.MethodDelete {
			if r.URL.Query().Get("v") != "0" {
				t.Error("removed data volumes")
			}
			w.WriteHeader(http.StatusNoContent)
			return
		}
		t.Errorf("unexpected request %s", r.URL)
		w.WriteHeader(500)
	}))
	defer server.Close()
	client, err := NewAPIClient(server.URL)
	if err != nil {
		t.Fatal(err)
	}
	snapshot, err := client.PrepareReplacement(context.Background(), "zoomies", "agent:new")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := client.CreateReplacement(context.Background(), snapshot); err != nil {
		t.Fatal(err)
	}
	if created["Image"] != "agent:new" || created["User"] != "65532" || !reflect.DeepEqual(created["Env"], []any{"TOKEN=keep-this"}) {
		t.Fatalf("lost configuration: %v", created)
	}
	host := created["HostConfig"].(map[string]any)
	if host["CustomFutureOption"] != true || host["PortBindings"] == nil || host["SecurityOpt"] == nil {
		t.Fatalf("lost runtime options: %v", host)
	}
	if !reflect.DeepEqual(host["Binds"], []any{"/socket:/socket", "existing-data:/var/lib/zoomies:rw"}) {
		t.Fatalf("lost data volume: %v", host)
	}
	endpoints := created["NetworkingConfig"].(map[string]any)["EndpointsConfig"].(map[string]any)
	network := endpoints["zoomies"].(map[string]any)
	if network["IPAddress"] != nil || network["EndpointID"] != nil || !reflect.DeepEqual(network["Aliases"], []any{"zoomies"}) {
		t.Fatalf("copied runtime network identity: %v", network)
	}
	if err := client.RemoveContainerKeepingVolumes(context.Background(), snapshot.ID, false); err != nil {
		t.Fatal(err)
	}
}

func TestAnAutomaticallyRemovedContainerIsRefusedBeforeAnUpgradeCanStopIt(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			t.Fatal("preflight mutated a container")
		}
		_, _ = w.Write([]byte(`{"Id":"old","Config":{"Image":"old"},"HostConfig":{"AutoRemove":true}}`))
	}))
	defer server.Close()
	client, _ := NewAPIClient(server.URL)
	if _, err := client.PrepareReplacement(context.Background(), "old", "new"); err == nil {
		t.Fatal("accepted a container that would destroy the rollback copy when stopped")
	}
}

// An upgrade adds the shared folder to a container that was created before
// there was one. The bind is added beside what the container already had;
// losing an operator's own mount on the way would be the worse outcome.
func TestAReplacementGainsABindAndKeepsItsOthers(t *testing.T) {
	r := &ContainerReplacement{body: map[string]json.RawMessage{
		"HostConfig": json.RawMessage(`{"Binds":["/socket:/socket:ro"],"Mounts":[{"Type":"bind","Source":"/data","Target":"/mnt/data"}],"CustomFutureOption":true}`),
	}}
	for target, want := range map[string]bool{"/socket": true, "/mnt/data": true, "/var/lib/zoomies/shared": false} {
		if got := r.HasBind(target); got != want {
			t.Errorf("HasBind(%s) = %v, want %v", target, got, want)
		}
	}
	if err := r.AddBind("/var/lib/zoomies/shared:/var/lib/zoomies/shared"); err != nil {
		t.Fatal(err)
	}
	if !r.HasBind("/var/lib/zoomies/shared") {
		t.Error("the added bind is not there")
	}
	var host map[string]any
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(host["Binds"], []any{"/socket:/socket:ro", "/var/lib/zoomies/shared:/var/lib/zoomies/shared"}) {
		t.Errorf("binds = %v", host["Binds"])
	}
	if host["CustomFutureOption"] != true || host["Mounts"] == nil {
		t.Errorf("lost host options: %v", host)
	}
}

// The group that owns the runtime's socket is how the image's account reaches
// it; a container created without it is given it, and keeps its other groups.
func TestAReplacementGainsAGroupAndKeepsItsOthers(t *testing.T) {
	r := &ContainerReplacement{body: map[string]json.RawMessage{
		"HostConfig": json.RawMessage(`{"GroupAdd":["100"],"CustomFutureOption":true}`),
	}}
	if !r.HasGroup("100") || r.HasGroup("998") {
		t.Fatal("HasGroup misread the existing groups")
	}
	if err := r.AddGroup("998"); err != nil {
		t.Fatal(err)
	}
	var host map[string]any
	if err := json.Unmarshal(r.body["HostConfig"], &host); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(host["GroupAdd"], []any{"100", "998"}) || host["CustomFutureOption"] != true {
		t.Errorf("host config = %v", host)
	}
}

// A pool's cache folder needs no mount of its own when the container already
// sees it through a host folder bound at its own path -- and only then: a
// volume, or a bind to another path, hides the host's folder instead.
func TestAFolderIsSeenOnlyThroughASamePathBindAboveIt(t *testing.T) {
	r := &ContainerReplacement{body: map[string]json.RawMessage{
		"HostConfig": json.RawMessage(`{"Binds":["zoomies-data:/var/lib/zoomies","/srv/mounted:/srv/mounted","/opt/x:/elsewhere"],"Mounts":[{"Type":"bind","Source":"/data","Target":"/data"},{"Type":"volume","Source":"v","Target":"/vol"}]}`),
	}}
	for target, want := range map[string]bool{
		"/srv/mounted/cache":   true,
		"/data/cache":          true,
		"/srv/mounted":         false, // the folder itself is HasBind's question
		"/var/lib/zoomies/c":   false, // under a named volume
		"/elsewhere/cache":     false, // under a bind from another host path
		"/vol/cache":           false,
		"/srv/mounted-other/x": false,
	} {
		if got := r.HasBindAbove(target); got != want {
			t.Errorf("HasBindAbove(%s) = %v, want %v", target, got, want)
		}
	}
}

