func cleanupRunner(t *testing.T, shared string) ContainerInspect {
	t.Helper()
	farm := toolFarmDir(shared, "runner-501")
	if err := os.MkdirAll(filepath.Join(farm, "go/1.27.1/x64/api"), 0755); err != nil {
		t.Fatal(err)
	}
	return ContainerInspect{ID: "runner-id", Image: "sha256:immutable", Config: &ContainerConfig{
		Image:  "runner:moving-tag",
		Labels: map[string]string{LabelManaged: "true", LabelRole: roleRunner, LabelName: "runner-501", LabelToolFarm: farm},
	}}
}

// Inject the unlinkat failure so this regression also runs in root CI jobs.
// The fake daemon models the helper clearing container-owned descendants.
func TestToolCleanupRecoversPermissionFailure(t *testing.T) {
	// Recovery uses a POSIX bind mount and shell. A Windows drive-letter
	// path contains the ':' separator that this mount's safety check rejects.
	requirePOSIX(t)
	for _, scenario := range []string{"success", "auto-removed", "auto-removing", "still auto-removing", "exit failure", "wait failure", "start failure", "cancelled", "still denied", "stale helper", "foreign helper"} {
		t.Run(scenario, func(t *testing.T) {
			shared := t.TempDir()
			runner := cleanupRunner(t, shared)
			farm := runner.Config.Labels[LabelToolFarm]
			var created ContainerCreateRequest
			var deleted []string
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			f := newFakeEngine(t, map[string]http.HandlerFunc{
				"GET " + v + "/containers/{id}/json": func(w http.ResponseWriter, r *http.Request) {
					if scenario == "stale helper" || scenario == "foreign helper" {
						labels := map[string]string{LabelRole: roleToolCleanup, LabelToolFarm: farm}
						if scenario == "foreign helper" {
							labels[LabelRole] = roleRunner
						}
						writeJSON(w, 200, ContainerInspect{ID: "stale", Config: &ContainerConfig{Labels: labels}})
						return
					}
					w.WriteHeader(404)
				},
				"POST " + v + "/containers/create": func(w http.ResponseWriter, r *http.Request) {
					if r.URL.Query().Get("name") != toolCleanupName(runner) {
						t.Error("helper name is not stable for retry")
					}
					if err := json.NewDecoder(r.Body).Decode(&created); err != nil {
						t.Error(err)
					}
					writeJSON(w, 201, map[string]string{"Id": "helper"})
				},
				"POST " + v + "/containers/helper/start": func(w http.ResponseWriter, r *http.Request) {
					if scenario == "start failure" {
						w.WriteHeader(500)
						return
					}
					if scenario == "cancelled" {
						cancel()
					}
					w.WriteHeader(204)
				},
				"POST " + v + "/containers/helper/wait": func(w http.ResponseWriter, r *http.Request) {
					if scenario == "wait failure" {
						w.WriteHeader(500)
						return
					}
					if scenario == "auto-removed" {
						w.WriteHeader(404)
						return
					}
					code := 0
					if scenario == "exit failure" {
						code = 1
					}
					writeJSON(w, 200, map[string]int{"StatusCode": code})
				},
				"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
					deleted = append(deleted, r.PathValue("id"))
					// The helper is AutoRemove: once it exits the daemon is
					// already removing it, and a DELETE that arrives first is
					// told so rather than doing it.
					if scenario == "still auto-removing" && r.PathValue("id") == "helper" {
						writeJSON(w, http.StatusConflict, map[string]string{"message": "removal of container helper is already in progress"})
						return
					}
					if scenario == "auto-removing" && r.PathValue("id") == "helper" {
						if len(deleted) == 1 {
							writeJSON(w, http.StatusConflict, map[string]string{"message": "removal of container helper is already in progress"})
							return
						}
						w.WriteHeader(404)
						return
					}
					w.WriteHeader(204)
				},
			})
			b := dockerBackendFor(t, f, DockerOptions{SharedDir: shared})
			b.removalWait = 200 * time.Millisecond
			calls := 0
			err := b.removeRunnerToolFarm(ctx, runner, func(path string) error {
				calls++
				if path != farm {
					t.Fatalf("cleanup touched %s", path)
				}
				if calls == 1 || scenario == "still denied" {
					return &os.PathError{Op: "unlinkat", Path: filepath.Join(farm, "go/1.27.1/x64/api/go1.txt"), Err: os.ErrPermission}
				}
				return os.RemoveAll(path)
			})
			wantSuccess := scenario == "success" || scenario == "auto-removed" || scenario == "auto-removing" || scenario == "still auto-removing" || scenario == "stale helper"
			if (err == nil) != wantSuccess {
				t.Fatalf("cleanup = %v", err)
			}
			if scenario == "foreign helper" {
				if len(deleted) != 0 || created.Image != "" {
					t.Fatal("foreign helper was touched")
				}
				return
			}
			if !slices.Contains(deleted, "helper") {
				t.Fatal("helper was not removed, including after cancellation")
			}
			if scenario == "stale helper" && (len(deleted) != 2 || deleted[0] != "stale") {
				t.Fatalf("stale helper not removed first: %v", deleted)
			}
			if created.Image != runner.Image || created.User != "0:0" || created.WorkingDir != "/" {
				t.Fatalf("unsafe helper identity: %+v", created)
			}
			hc := created.HostConfig
			if !slices.Equal(hc.Binds, []string{farm + ":/cleanup"}) || hc.NetworkMode != "none" || hc.Privileged || !hc.ReadonlyRootfs {
				t.Fatalf("helper has excessive access: %+v", hc)
			}
			if !slices.Equal(hc.CapDrop, []string{"ALL"}) || !slices.Equal(hc.CapAdd, []string{"DAC_OVERRIDE", "FOWNER"}) || !slices.Equal(hc.SecurityOpt, []string{"no-new-privileges"}) {
				t.Fatalf("capabilities = %+v", hc)
			}
			if !hc.AutoRemove || hc.Memory == 0 || hc.NanoCPUs == 0 || hc.PidsLimit == nil {
				t.Fatal("helper is not bounded and automatically removed")
			}
			if len(created.Env) != 0 || created.Labels[LabelManaged] != "" {
				t.Fatal("helper inherited runner credentials or reconciliation labels")
			}
			if wantSuccess && calls != 2 {
				t.Fatal("helper success was not verified on the host")
			}
		})
	}
}

func TestToolCleanupDoesNotEscalateOtherErrors(t *testing.T) {
	for _, localErr := range []error{nil, errors.New("read-only filesystem")} {
		b := &DockerBackend{}
		runner := ContainerInspect{Config: &ContainerConfig{Labels: map[string]string{LabelToolFarm: "/farm"}}}
		if got := b.removeRunnerToolFarm(context.Background(), runner, func(string) error { return localErr }); got != localErr {
			t.Fatalf("got %v, want original error %v", got, localErr)
		}
	}
}

func TestToolCleanupRejectsUntrustedPaths(t *testing.T) {
	for _, scenario := range []string{"kept cache", "other runner", "relative", "symlink farm", "symlink parent", "unmanaged", "missing image"} {
		t.Run(scenario, func(t *testing.T) {
			shared := t.TempDir()
			runner := cleanupRunner(t, shared)
			farm := runner.Config.Labels[LabelToolFarm]
			switch scenario {
			case "kept cache":
				runner.Config.Labels[LabelToolFarm] = filepath.Join(shared, "cache", "tools")
			case "other runner":
				runner.Config.Labels[LabelToolFarm] = toolFarmDir(shared, "other")
			case "relative":
				runner.Config.Labels[LabelToolFarm] = "relative"
			case "unmanaged":
				delete(runner.Config.Labels, LabelManaged)
			case "missing image":
				runner.Image = ""
			case "symlink farm", "symlink parent":
				path := farm
				if scenario == "symlink parent" {
					path = filepath.Dir(farm)
				}
				if err := os.RemoveAll(path); err != nil {
					t.Fatal(err)
				}
				if err := os.Symlink(t.TempDir(), path); err != nil {
					t.Skip(err)
				}
			}
			b := &DockerBackend{sharedDir: shared}
			if err := b.validateToolCleanup(runner); err == nil {
				t.Fatal("unsafe recovery accepted")
			}
		})
	}
}

func TestToolCleanupScriptPreservesSymlinkTargetsAndRemovesDotfiles(t *testing.T) {
	requirePOSIX(t)
	farm, kept := t.TempDir(), t.TempDir()
	for _, name := range []string{"go/1.27.1/x64/api/go1.txt", ".hidden/tool", "..hidden/tool", "--option/tool", "space and ' quote/tool"} {
		path := filepath.Join(farm, name)
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte("temporary"), 0644); err != nil {
			t.Fatal(err)
		}
	}
	marker := filepath.Join(kept, "do-not-delete")
	if err := os.WriteFile(marker, []byte("kept"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(kept, filepath.Join(farm, "shared-version")); err != nil {
		t.Fatal(err)
	}
	// Substitute a quoted positional parameter, never interpolate a host path
	// into the script. Production always uses the fixed /cleanup mountpoint.
	script := strings.ReplaceAll(toolCleanupScript, "/cleanup", `"$1"`)
	if out, err := exec.Command("/bin/sh", "-c", script, "cleanup-test", farm).CombinedOutput(); err != nil {
		t.Fatalf("%v: %s", err, out)
	}
	entries, err := os.ReadDir(farm)
	if err != nil || len(entries) != 0 {
		t.Fatalf("farm not empty: %v, %v", entries, err)
	}
	if data, err := os.ReadFile(marker); err != nil || string(data) != "kept" {
		t.Fatal("kept cache was touched")
	}
}

package backend

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// RunnerToolCacheSharedMount is where a pool's kept tool cache is mounted in a
// runner, read-only. The runner's AGENT_TOOLSDIRECTORY is a folder of its own
// at RunnerToolCacheMount, which links to every complete version in here.
//
// The kept cache used to be mounted writable, and that was a race: when two
// runners asked for a version it lacked, actions/tool-cache in each deleted
// the folder, copied the files in and wrote the .complete marker, with no
// lock between them. One run of this repository's own CI left a marker beside
// half a Go, and every job after it trusted the marker and failed. Read-only
// also means a job can no longer replace the toolchain the next job runs. The
// fill container is now the only thing that writes to the kept cache; a
// version it has not put there is downloaded into the runner's own folder and
// thrown away with the runner.
const RunnerToolCacheSharedMount = "/opt/zoomies-tools-shared"

// LabelToolFarm records the host folder holding a runner's own tool cache, so
// removing the runner removes it too.
const LabelToolFarm = LabelPrefix + "toolfarm"

// toolFarmDir is the host folder a runner's own tool cache is made in: beside
// the kept caches, in the shared folder the daemon can already bind from.
func toolFarmDir(sharedDir, runner string) string {
	return filepath.Join(sharedDir, "cache", "tool-runs", containerName(runner))
}

// buildToolFarm makes farm a tool cache the runner can write to, holding a
// link to each version in shared whose install finished. A version is
// tool/version/arch plus a tool/version/arch.complete marker; one without its
// marker is a fill still under way, or one that failed, and is left out
// rather than handed to a job half-written. The links point at the read-only
// mount, which is where they resolve inside the runner.
func buildToolFarm(shared, farm string) error {
	if err := os.RemoveAll(farm); err != nil {
		return err
	}
	// The parent is the agent's, like the shared folder above it: only each
	// runner's own folder is opened up.
	if err := os.MkdirAll(filepath.Dir(farm), 0o750); err != nil {
		return err
	}
	if err := mkdirOpen(farm); err != nil {
		return err
	}
	markers, err := filepath.Glob(filepath.Join(shared, "*", "*", "*.complete"))
	if err != nil {
		return err
	}
	for _, marker := range markers {
		rel, err := filepath.Rel(shared, strings.TrimSuffix(marker, ".complete"))
		if err != nil {
			return err
		}
		if fi, err := os.Stat(filepath.Join(shared, rel)); err != nil || !fi.IsDir() {
			continue
		}
		parts := strings.Split(rel, string(filepath.Separator))
		if err := mkdirOpen(filepath.Join(farm, parts[0])); err != nil {
			return err
		}
		if err := mkdirOpen(filepath.Join(farm, parts[0], parts[1])); err != nil {
			return err
		}
		link := filepath.Join(farm, rel)
		if err := os.Symlink(RunnerToolCacheSharedMount+"/"+filepath.ToSlash(rel), link); err != nil {
			return err
		}
		if err := os.WriteFile(link+".complete", nil, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// mkdirOpen creates a folder the runner can add to, whatever its uid: the same
// reasoning as ensureRunnerWritableDir, for a folder that is only ever ours.
func mkdirOpen(dir string) error {
	if err := os.Mkdir(dir, 0o750); err != nil && !errors.Is(err, fs.ErrExist) {
		return err
	}
	if err := os.Chmod(dir, 0o777); err != nil {
		return fmt.Errorf("opening %s to the runner: %w", dir, err)
	}
	return nil
}

package backend

import (
	"os"
	"path/filepath"
	"testing"
)

// Two runners filling the same writable tool cache left a .complete marker
// beside half a Go, and every later job trusted it. A runner now sees only
// versions whose install finished, as links into the read-only kept cache,
// and has a folder of its own to download anything else into.
func TestARunnersToolCacheLinksOnlyFinishedVersions(t *testing.T) {
	requirePOSIX(t)
	shared := t.TempDir()
	for _, p := range []string{"go/1.27.1/x64", "node/22.23.3/x64"} {
		if err := os.MkdirAll(filepath.Join(shared, p), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	if err := os.WriteFile(filepath.Join(shared, "go/1.27.1/x64.complete"), nil, 0o644); err != nil {
		t.Fatal(err)
	}
	farm := toolFarmDir(t.TempDir(), "run-one")
	if err := os.MkdirAll(filepath.Join(farm, "stale"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := buildToolFarm(shared, farm); err != nil {
		t.Fatalf("buildToolFarm: %v", err)
	}

	target, err := os.Readlink(filepath.Join(farm, "go/1.27.1/x64"))
	if err != nil {
		t.Fatalf("finished Go is not linked: %v", err)
	}
	if want := RunnerToolCacheSharedMount + "/go/1.27.1/x64"; target != want {
		t.Errorf("link = %q, want %q: where the kept cache is mounted in the runner", target, want)
	}
	if _, err := os.Stat(filepath.Join(farm, "go/1.27.1/x64.complete")); err != nil {
		t.Errorf("finished Go has no marker, so setup-go would download it again: %v", err)
	}
	if _, err := os.Lstat(filepath.Join(farm, "node")); !os.IsNotExist(err) {
		t.Errorf("an unfinished Node was handed to the runner: %v", err)
	}
	if _, err := os.Stat(filepath.Join(farm, "stale")); !os.IsNotExist(err) {
		t.Errorf("a previous runner's leftovers survived: %v", err)
	}
	for _, d := range []string{farm, filepath.Join(farm, "go"), filepath.Join(farm, "go/1.27.1")} {
		if fi, _ := os.Stat(d); fi.Mode().Perm() != 0o777 {
			t.Errorf("%s mode = %v, want writable by the runner, whatever its uid", d, fi.Mode().Perm())
		}
	}
}

package backend

import (
	"bufio"
	"context"
	_ "embed"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
	"time"
)

// A pool that keeps a tool cache starts it empty: the first job to ask for
// Python 3.12 downloads it, and so does every job on every other host until
// one of them has. Filling it is the same download done once per host, ahead
// of the jobs, for the versions the toolchain scan found the pool's workflows
// asking for.
//
// The fill runs inside the pool's own image rather than in the agent, which
// is a static binary in a distroless image with nothing to unpack a toolchain
// with. The image is also the only thing that knows which build is the right
// one: setup-python's archives are per Ubuntu release, and a toolchain built
// for another C library is a cache entry that fails in the job that finds it.

//go:embed toolfill.sh
var toolFillScript string

// ToolRequest is one toolchain version to put in a pool's tool cache, as a
// workflow asked for it: "python" "3.12", "node" "lts/*", "java" "21"
// "temurin".
type ToolRequest struct {
	Tool         string `json:"tool"`
	Version      string `json:"version"`
	Distribution string `json:"distribution,omitempty"`
}

// ToolFill is what became of one ToolRequest.
type ToolFill struct {
	Tool    string `json:"tool"`
	Request string `json:"request"`
	// Outcome is installed, present (it was already there), skipped (this
	// request is not one a fill can serve, with the reason) or failed.
	Outcome string `json:"outcome"`
	// Version is the release the request resolved to, for installed and
	// present; Reason says why for skipped and failed.
	Version string `json:"version,omitempty"`
	Reason  string `json:"reason,omitempty"`
}

// The outcomes a fill reports.
const (
	ToolInstalled = "installed"
	ToolPresent   = "present"
	ToolSkipped   = "skipped"
	ToolFailed    = "failed"
)

// ToolCacheFiller is implemented by a backend that can fill a pool's kept tool
// cache. spec carries what the pool's runners would: its ID, image, pull
// policy, env and cache, from which the backend finds the same folder the
// runners are given.
type ToolCacheFiller interface {
	FillToolCache(ctx context.Context, spec Spec, tools []ToolRequest) ([]ToolFill, error)
}

const (
	roleToolFill = "toolcache-fill"
	// A fill is a background download and must not take a running job's
	// share of the host to do it.
	toolFillCPUs     = 1
	toolFillMemoryMB = 2048
)

// FillToolCache runs the fill in a short-lived container of the pool's image,
// with the pool's tool cache mounted where its runners have it.
func (b *DockerBackend) FillToolCache(ctx context.Context, spec Spec, tools []ToolRequest) ([]ToolFill, error) {
	if len(tools) == 0 {
		return nil, nil
	}
	if dir, err := toolCacheDir(spec, b.sharedDir); err != nil || dir == "" {
		if err != nil {
			return nil, err
		}
		return nil, errors.New("backend: this pool keeps no tool cache on this host")
	}
	ref, _, _, _, err := b.prepareImage(ctx, spec.Image, spec.PullPolicy)
	if err != nil {
		return nil, err
	}
	spec.Image = ref
	dir, err := toolCacheDir(spec, b.sharedDir)
	if err != nil {
		return nil, err
	}
	if dir == "" {
		return nil, errors.New("backend: this pool keeps no tool cache on this host; it needs the pool cache and its tool cache turned on, and a shared folder the agent could create")
	}
	if err := ensureRunnerWritableDir(dir); err != nil {
		return nil, fmt.Errorf("backend: creating the tool cache folder %s: %w", dir, err)
	}

	cfg := buildToolFillConfig(spec, b.fl, dir, b.extraCA, inheritedProxyEnv(os.LookupEnv, spec.Env), tools)
	// The reference prepareImage resolved, which is the digest a pinned pool
	// names rather than whatever its tag points at now.
	cfg.Image = ref
	if network := firstNonEmpty(strings.TrimSpace(spec.Network), b.network); network != "" {
		if err := b.ensureNetwork(ctx, network); err != nil {
			return nil, err
		}
		cfg.HostConfig.NetworkMode = network
	}
	name := "zoomies-toolfill-" + sanitizeHostname(cfg.Labels[LabelPoolID])
	if id, err := cacheIdentity(spec); err == nil && id != "" {
		name = "zoomies-toolfill-" + id
	}

	// Removed before and after, under a bounded context of its own: a fill
	// that was cancelled half way leaves a container of this name, and one
	// left behind is what would make the next fill's create fail.
	cleanup := func() {
		rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		if err := b.removeContainer(rctx, name); err != nil && !errors.Is(err, ErrNotFound) {
			b.log.Warn("could not remove the tool cache fill container", "container", name, "error", err)
		}
	}
	cleanup()
	id, err := b.api.ContainerCreate(ctx, name, cfg)
	if err != nil {
		return nil, fmt.Errorf("backend: creating the tool cache fill container: %w", err)
	}
	defer cleanup()
	if err := b.api.ContainerStart(ctx, id); err != nil {
		return nil, fmt.Errorf("backend: starting the tool cache fill container: %w", err)
	}
	code, waitErr := b.api.ContainerWait(ctx, id)

	// The logs are read even when the wait failed: every request that
	// finished before a deadline is in them, and is in the cache.
	lctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
	defer cancel()
	var fills []ToolFill
	var tail []string
	if rc, err := b.api.ContainerLogs(lctx, id, LogQuery{Stdout: true, Stderr: true}); err == nil {
		fills, tail = parseToolFills(rc)
		_ = rc.Close()
	}
	switch {
	case waitErr != nil:
		return fills, fmt.Errorf("backend: the tool cache fill did not finish: %w", waitErr)
	case code != 0:
		return fills, fmt.Errorf("backend: the tool cache fill exited with status %d: %s", code, strings.Join(tail, " / "))
	}
	return fills, nil
}

// buildToolFillConfig is the fill container: the pool's image, as the image's
// runner user, with the tool cache and nothing else of the host's mounted.
//
// It carries no io.zoomies.managed label, so the agent's reconciliation never
// counts it as a runner or reaps it as an orphan; its fixed name is how a
// leftover one is found instead.
func buildToolFillConfig(spec Spec, fl flavor, dir, extraCA string, proxyEnv []string, tools []ToolRequest) ContainerCreateRequest {
	var requests strings.Builder
	for _, t := range tools {
		fmt.Fprintf(&requests, "%s %s %s\n", t.Tool, t.Version, t.Distribution)
	}
	env := []string{EnvToolsDirectory + "=" + RunnerToolCacheMount}
	env = append(env, proxyEnv...)
	// The pool's own proxy, where it sets one: the fill fetches from the same
	// hosts the pool's jobs would, through the same way out.
	for _, k := range proxyEnvKeys {
		if v, ok := spec.Env[k]; ok {
			env = append(env, k+"="+v)
		}
	}
	env = append(env, "ZOOMIES_TOOL_REQUESTS="+requests.String())

	cfg := ContainerCreateRequest{
		Image: spec.Image,
		// bash -c runs the script from memory, so the image needs nothing of
		// Zoomies' in it; "toolfill" is $0, which names it in any error bash
		// prints.
		Entrypoint: []string{"/bin/bash", "-c", toolFillScript, "toolfill"},
		Env:        env,
		Labels: map[string]string{
			LabelRole:   roleToolFill,
			LabelPoolID: spec.PoolID,
		},
		HostConfig: &HostConfig{
			LogConfig:     runnerLogConfig(fl),
			RestartPolicy: RestartPolicy{Name: "no"},
			CapDrop:       append([]string(nil), fl.capDrop...),
			NanoCPUs:      nanoCPUs(toolFillCPUs),
			Memory:        toolFillMemoryMB * 1024 * 1024,
			MemorySwap:    toolFillMemoryMB * 1024 * 1024,
			Binds:         []string{dir + ":" + RunnerToolCacheMount + fl.mountSuffix},
		},
	}
	// As the runner user whatever the pool says about root: what the fill
	// writes, the runners read and a later job may update, and a folder of
	// root's would be one they cannot.
	cfg.User = fl.runnerUser
	if extraCA != "" {
		cfg.HostConfig.Binds = append(cfg.HostConfig.Binds, extraCABind(fl, extraCA))
		cfg.Env = append(cfg.Env, EnvExtraCAFile+"="+ExtraCAPath)
	}
	return cfg
}

// parseToolFills reads the script's "zoomies-fill <outcome> <tool> <request>
// <version-or-reason>" lines, and keeps the last few other lines for an error
// message.
func parseToolFills(r io.Reader) ([]ToolFill, []string) {
	var fills []ToolFill
	var tail []string
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		rest, ok := strings.CutPrefix(line, "zoomies-fill ")
		if !ok {
			if line != "" {
				tail = append(tail, line)
				if len(tail) > 5 {
					tail = tail[1:]
				}
			}
			continue
		}
		f := strings.SplitN(rest, " ", 4)
		if len(f) < 3 {
			continue
		}
		fill := ToolFill{Outcome: f[0], Tool: f[1], Request: f[2]}
		detail := ""
		if len(f) == 4 {
			detail = f[3]
		}
		switch fill.Outcome {
		case ToolInstalled, ToolPresent:
			fill.Version = detail
		case ToolSkipped, ToolFailed:
			fill.Reason = detail
		default:
			continue
		}
		fills = append(fills, fill)
	}
	return fills, tail
}

package backend

import (
	"context"
	"encoding/json"
	"net/http"
	"os"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func toolFillSpec() Spec {
	return Spec{
		PoolID:     "pool_1",
		PoolName:   "linux-x64",
		Image:      "ghcr.io/eyupio/zoomies-runner:v1",
		PullPolicy: store.PullIfNotPresent,
		Cache:      store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool},
		Env:        map[string]string{"HTTPS_PROXY": "http://proxy.pool:3128", "SECRET_TOKEN": "not-for-the-fill"},
		RunAsRoot:  true,
	}
}

// The fill writes what the runners read, so it runs as the image's runner
// user even for a pool whose jobs run as root -- a cache of root's files is
// one a later job cannot update. It sees the tool cache and nothing else of
// the host's, and carries no managed label, so the agent's reconciliation
// never mistakes it for a runner and reaps it mid-download.
func TestTheFillContainerIsTheRunnerUserWithOnlyTheToolCache(t *testing.T) {
	tools := []ToolRequest{{Tool: "python", Version: "3.12"}, {Tool: "java", Version: "21", Distribution: "temurin"}}
	cfg := buildToolFillConfig(toolFillSpec(), dockerFlavor(), "/var/lib/zoomies/shared/cache/tools/pool-1", "", nil, tools)

	if cfg.User != "runner" {
		t.Errorf("user = %q, want the runner user", cfg.User)
	}
	if _, managed := cfg.Labels[LabelManaged]; managed {
		t.Error("the fill carries the managed label, so reconciliation would treat it as a runner")
	}
	if !slices.Equal(cfg.HostConfig.Binds, []string{"/var/lib/zoomies/shared/cache/tools/pool-1:" + RunnerToolCacheMount}) {
		t.Errorf("binds = %v, want only the tool cache", cfg.HostConfig.Binds)
	}
	env := envMap(cfg.Env)
	if env[EnvToolsDirectory] != RunnerToolCacheMount {
		t.Errorf("%s = %q", EnvToolsDirectory, env[EnvToolsDirectory])
	}
	if env["ZOOMIES_TOOL_REQUESTS"] != "python 3.12 \njava 21 temurin\n" {
		t.Errorf("requests = %q", env["ZOOMIES_TOOL_REQUESTS"])
	}
	// The pool's proxy is its way out; the rest of its env is its jobs'.
	if env["HTTPS_PROXY"] != "http://proxy.pool:3128" {
		t.Errorf("the pool's proxy was not passed on: %v", env)
	}
	if _, ok := env["SECRET_TOKEN"]; ok {
		t.Error("a pool variable that is not a proxy reached the fill")
	}
	if cfg.HostConfig.NanoCPUs == 0 || cfg.HostConfig.Memory == 0 {
		t.Error("the fill has no resource limit, so it can take a running job's share of the host")
	}
	if len(cfg.Entrypoint) < 3 || cfg.Entrypoint[0] != "/bin/bash" || cfg.Entrypoint[2] != toolFillScript {
		t.Errorf("entrypoint = %.60q, want the embedded script run by bash", cfg.Entrypoint)
	}
}

func TestTheFillTrustsTheHostsExtraCA(t *testing.T) {
	cfg := buildToolFillConfig(toolFillSpec(), dockerFlavor(), "/tools", "/etc/acme/proxy-ca.pem", nil, []ToolRequest{{Tool: "node", Version: "22"}})
	if !slices.Contains(cfg.HostConfig.Binds, "/etc/acme/proxy-ca.pem:"+ExtraCAPath+":ro") {
		t.Errorf("binds = %v, want the CA mounted read-only", cfg.HostConfig.Binds)
	}
	if envMap(cfg.Env)[EnvExtraCAFile] != ExtraCAPath {
		t.Errorf("%s is not set, so the script cannot find the CA", EnvExtraCAFile)
	}
}

func TestParseToolFillsReadsEachOutcome(t *testing.T) {
	out := strings.Join([]string{
		"Collecting pip",
		"zoomies-fill installed python 3.12 3.12.7",
		"zoomies-fill present node 22 22.11.0",
		"zoomies-fill skipped dotnet 8.0 setup-dotnet installs into its own folder, not the tool cache",
		"zoomies-fill failed go 1.27 could not download go1.27.1.linux-amd64.tar.gz",
		"zoomies-fill nonsense line",
		"curl: (6) Could not resolve host",
	}, "\n")
	fills, tail := parseToolFills(strings.NewReader(out))
	want := []ToolFill{
		{Tool: "python", Request: "3.12", Outcome: ToolInstalled, Version: "3.12.7"},
		{Tool: "node", Request: "22", Outcome: ToolPresent, Version: "22.11.0"},
		{Tool: "dotnet", Request: "8.0", Outcome: ToolSkipped, Reason: "setup-dotnet installs into its own folder, not the tool cache"},
		{Tool: "go", Request: "1.27", Outcome: ToolFailed, Reason: "could not download go1.27.1.linux-amd64.tar.gz"},
	}
	if !slices.Equal(fills, want) {
		t.Errorf("fills = %+v\nwant %+v", fills, want)
	}
	if !slices.Equal(tail, []string{"Collecting pip", "curl: (6) Could not resolve host"}) {
		t.Errorf("tail = %q", tail)
	}
}

func TestFillToolCacheRunsTheFillInThePoolsToolCache(t *testing.T) {
	shared := t.TempDir()
	var created ContainerCreateRequest
	var removed []string
	f := newFakeEngine(t, map[string]http.HandlerFunc{
		"DELETE " + v + "/containers/{id}": func(w http.ResponseWriter, r *http.Request) {
			removed = append(removed, r.PathValue("id"))
			writeJSON(w, http.StatusNotFound, map[string]string{"message": "no such container"})
		},
		"GET " + v + "/images/{ref...}": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Id": "sha256:cached", "RepoDigests": []string{"ghcr.io/eyupio/zoomies-runner@sha256:abc"}})
		},
		"POST " + v + "/containers/create": func(w http.ResponseWriter, r *http.Request) {
			_ = json.NewDecoder(r.Body).Decode(&created)
			writeJSON(w, http.StatusCreated, map[string]any{"Id": "fill1"})
		},
		"POST " + v + "/containers/fill1/start": func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(http.StatusNoContent)
		},
		"POST " + v + "/containers/fill1/wait": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"StatusCode": 0})
		},
		"GET " + v + "/containers/fill1/json": func(w http.ResponseWriter, r *http.Request) {
			writeJSON(w, http.StatusOK, map[string]any{"Id": "fill1", "Config": map[string]any{"Tty": false}})
		},
		"GET " + v + "/containers/fill1/logs": func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/vnd.docker.multiplexed-stream")
			_, _ = w.Write(frame(1, "zoomies-fill installed node 22 22.11.0\n"))
			_, _ = w.Write(frame(1, "zoomies-fill skipped java 17 only the temurin distribution is filled, and this asks for zulu\n"))
		},
	})
	b := dockerBackendFor(t, f, DockerOptions{SharedDir: shared})

	ctx, cancel := context.WithTimeout(context.Background(), 10e9)
	defer cancel()
	fills, err := b.FillToolCache(ctx, toolFillSpec(), []ToolRequest{{Tool: "node", Version: "22"}, {Tool: "java", Version: "17", Distribution: "zulu"}})
	if err != nil {
		t.Fatalf("FillToolCache: %v", err)
	}
	if len(fills) != 2 || fills[0].Version != "22.11.0" || fills[1].Outcome != ToolSkipped {
		t.Errorf("fills = %+v", fills)
	}
	// The folder a runner of this pool is bound, created before the daemon is
	// asked to bind it, or the daemon makes it root's.
	resolved := toolFillSpec()
	resolved.Image = created.Image
	dir, _ := toolCacheDir(resolved, shared)
	if fi, err := os.Stat(dir); err != nil || !fi.IsDir() {
		t.Fatalf("the tool cache folder was not created: %v", err)
	}
	if !slices.Contains(created.HostConfig.Binds, dir+":"+RunnerToolCacheMount) {
		t.Errorf("binds = %v, want %s", created.HostConfig.Binds, dir)
	}
	// Removed before, in case a cancelled fill left one, and after.
	if len(removed) != 2 || removed[0] != "zoomies-toolfill-v2-pool-1-75ea1320805b60dd113424f239f9236f" {
		t.Errorf("removed = %v", removed)
	}
}

