package backup

// DiskFree has no portable answer away from the platforms Zoomies measures
// disks on; the page simply does not show a figure.
func DiskFree(string) (int64, bool) { return 0, false }

//go:build linux || darwin

package backup

import (
	"math"
	"syscall"
)

// DiskFree reports the bytes available on the filesystem holding path, and
// whether the question could be answered. It is what the settings page shows
// next to the backup directory, because "is there room for another copy" is
// the question an operator has just before there is not.
//
// The same two platforms internal/agent's disk measurement names, for the same
// reason: syscall.Statfs is not everywhere `unix` is.
func DiskFree(path string) (int64, bool) {
	var st syscall.Statfs_t
	if err := syscall.Statfs(path, &st); err != nil {
		return 0, false
	}
	bsize := int64(st.Bsize)
	if bsize <= 0 || uint64(st.Bavail) > math.MaxInt64/uint64(bsize) {
		return 0, false
	}
	return int64(st.Bavail) * bsize, true
}

package backup

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// FakeS3 is a fake object store, in the spirit of internal/github's fake
// GitHub and for the same reason: the tests of everything that ships a backup
// -- this package's, the controller's loop, the API's handlers -- should
// exercise the real client against a real socket rather than a stub of
// themselves.
//
// It is enough of the protocol to be useful and strict about the parts that
// matter: every request must be signed, dated and must state its payload, and
// a PUT whose body is not the digest it declared is refused. A client that
// quietly stopped signing would fail here rather than in somebody's bucket.
//
// It lives in a non-test file because packages above this one need it, and it
// is path style because that is what a bare host with no wildcard DNS in front
// of it can be.
type FakeS3 struct {
	server *httptest.Server
	mu     sync.Mutex
	// objects is the bucket, keyed by object key.
	objects map[string][]byte
	stored  map[string]time.Time
	// bucket is the one bucket that exists; anything else is NoSuchBucket.
	bucket string
	// fail, when set, is answered to every request: the way a remote that is
	// down is simulated.
	fail *fakeS3Failure
	// puts counts successful writes, so a test can say the catch-up sent two.
	puts int
}

type fakeS3Failure struct {
	status  int
	code    string
	message string
}

// NewFakeS3 starts a fake object store holding one bucket. The caller must
// Close it.
func NewFakeS3(bucket string) *FakeS3 {
	f := &FakeS3{objects: map[string][]byte{}, stored: map[string]time.Time{}, bucket: bucket}
	f.server = httptest.NewServer(http.HandlerFunc(f.handle))
	return f
}

// Close stops the fake.
func (f *FakeS3) Close() { f.server.Close() }

// Endpoint is what a remote's configuration points at.
func (f *FakeS3) Endpoint() string { return f.server.URL }

// Bucket is the one bucket it holds.
func (f *FakeS3) Bucket() string { return f.bucket }

// BreakWith makes every request from now on fail with this S3 error, which is
// how a remote that is down, refusing a signature or missing its bucket is
// arranged.
func (f *FakeS3) BreakWith(status int, code, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.fail = &fakeS3Failure{status: status, code: code, message: message}
}

// Mend puts it back.
func (f *FakeS3) Mend() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.fail = nil
}

// Keys is every object key it holds, sorted.
func (f *FakeS3) Keys() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]string, 0, len(f.objects))
	for k := range f.objects {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Count is how many objects it holds.
func (f *FakeS3) Count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.objects)
}

// Puts is how many successful writes it has taken, so a test can say that a
// catch-up sent two backups rather than one.
func (f *FakeS3) Puts() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.puts
}

func (f *FakeS3) handle(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	failure := f.fail
	f.mu.Unlock()
	if failure != nil {
		f.refuse(w, failure.status, failure.code, failure.message)
		return
	}

	// Every request is signed, dated and states its payload. A client that
	// stopped doing any of the three would be refused by a real service, so it
	// is refused here.
	if !strings.HasPrefix(r.Header.Get("Authorization"), "AWS4-HMAC-SHA256 Credential=") {
		f.refuse(w, http.StatusForbidden, "AccessDenied", "the request is not signed")
		return
	}
	if r.Header.Get("X-Amz-Date") == "" {
		f.refuse(w, http.StatusForbidden, "AccessDenied", "the request has no date")
		return
	}
	declared := r.Header.Get("X-Amz-Content-Sha256")
	if declared == "" {
		f.refuse(w, http.StatusForbidden, "AccessDenied", "the request does not state its payload")
		return
	}

	// The fake is path style, which is what a bare host with no wildcard DNS
	// in front of it can be.
	trimmed := strings.TrimPrefix(r.URL.Path, "/")
	bucket, key, _ := strings.Cut(trimmed, "/")
	if bucket != f.bucket {
		f.refuse(w, http.StatusNotFound, "NoSuchBucket", "no such bucket")
		return
	}

	switch r.Method {
	case http.MethodGet:
		if key == "" {
			f.listObjects(w, r)
			return
		}
		f.mu.Lock()
		body, ok := f.objects[key]
		f.mu.Unlock()
		if !ok {
			f.refuse(w, http.StatusNotFound, "NoSuchKey", "no such key")
			return
		}
		w.Header().Set("Content-Length", strconv.Itoa(len(body)))
		_, _ = w.Write(body)
	case http.MethodPut:
		body, err := io.ReadAll(r.Body)
		if err != nil {
			f.refuse(w, http.StatusBadRequest, "IncompleteBody", err.Error())
			return
		}
		sum := sha256.Sum256(body)
		if hex.EncodeToString(sum[:]) != declared {
			f.refuse(w, http.StatusBadRequest, "XAmzContentSHA256Mismatch",
				"the body is not what the request said it would be")
			return
		}
		f.mu.Lock()
		f.objects[key] = body
		f.stored[key] = time.Now().UTC()
		f.puts++
		f.mu.Unlock()
		w.Header().Set("ETag", `"`+hex.EncodeToString(sum[:])+`"`)
		w.WriteHeader(http.StatusOK)
	case http.MethodDelete:
		f.mu.Lock()
		delete(f.objects, key)
		delete(f.stored, key)
		f.mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	default:
		f.refuse(w, http.StatusMethodNotAllowed, "MethodNotAllowed", r.Method)
	}
}

// listObjects answers ListObjectsV2, one key at a time when a max-keys is
// given, so the client's continuation handling is exercised rather than
// assumed.
func (f *FakeS3) listObjects(w http.ResponseWriter, r *http.Request) {
	if r.URL.Query().Get("list-type") != "2" {
		f.refuse(w, http.StatusBadRequest, "InvalidArgument", "only ListObjectsV2 is implemented")
		return
	}
	prefix := r.URL.Query().Get("prefix")
	after := r.URL.Query().Get("continuation-token")
	page := 1
	if v := r.URL.Query().Get("max-keys"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			page = n
		}
	}

	f.mu.Lock()
	keys := make([]string, 0, len(f.objects))
	for k := range f.objects {
		if strings.HasPrefix(k, prefix) && k > after {
			keys = append(keys, k)
		}
	}
	sort.Strings(keys)
	var body strings.Builder
	body.WriteString(`<?xml version="1.0" encoding="UTF-8"?><ListBucketResult>`)
	truncated := len(keys) > page
	shown := keys
	if truncated {
		shown = keys[:page]
	}
	for _, k := range shown {
		sum := sha256.Sum256(f.objects[k])
		fmt.Fprintf(&body, `<Contents><Key>%s</Key><Size>%d</Size><LastModified>%s</LastModified><ETag>"%s"</ETag></Contents>`,
			xmlEscape(k), len(f.objects[k]), f.stored[k].Format(time.RFC3339), hex.EncodeToString(sum[:]))
	}
	f.mu.Unlock()

	fmt.Fprintf(&body, `<IsTruncated>%t</IsTruncated>`, truncated)
	if truncated {
		fmt.Fprintf(&body, `<NextContinuationToken>%s</NextContinuationToken>`, xmlEscape(shown[len(shown)-1]))
	}
	body.WriteString(`</ListBucketResult>`)
	w.Header().Set("Content-Type", "application/xml")
	_, _ = io.WriteString(w, body.String())
}

func (f *FakeS3) refuse(w http.ResponseWriter, status int, code, message string) {
	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(status)
	fmt.Fprintf(w, `<?xml version="1.0" encoding="UTF-8"?><Error><Code>%s</Code><Message>%s</Message></Error>`,
		xmlEscape(code), xmlEscape(message))
}

// Put writes an object directly, for the test that needs a bucket to already
// hold something -- somebody else's backups, most usefully.
func (f *FakeS3) Put(key string, body []byte) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.objects[key] = body
	f.stored[key] = time.Now().UTC()
}

func xmlEscape(s string) string {
	var b strings.Builder
	_ = xml.EscapeText(&b, []byte(s))
	return b.String()
}

package backup

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"testing"
)

// tarOf builds a gzipped tar of the given members, for the archives Unpack
// must refuse.
func tarOf(t *testing.T, members map[string][]byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	for name, body := range members {
		if err := tw.WriteHeader(&tar.Header{Name: name, Mode: 0o600, Size: int64(len(body))}); err != nil {
			t.Fatal(err)
		}
		if _, err := tw.Write(body); err != nil {
			t.Fatal(err)
		}
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

package backup

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path"
	"path/filepath"
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

// A backup that leaves the machine.
//
// A copy beside the database is a backup against a mistake: a bad migration, a
// deletion somebody regrets, an upgrade that went sideways. It is not a backup
// against the disk, the machine or the datacentre, and a directory of tidy
// copies on the volume that just died is the worst kind of backup because
// everyone believed in it.
//
// So a remote is one S3-compatible bucket, and what goes into it is exactly
// the file the Backups tab downloads: the same gzipped tar of the manifest,
// the database and -- only when the backup was taken with it -- the key,
// optionally sealed with the same argon2id and AES-256-GCM. One archive
// format, whether it was downloaded by a browser, copied by hand or put there
// by the fleet, so a copy pulled out of a bucket three years from now opens
// with `zoomies restore` and nothing else.

// ErrNoRemote is a remote named by something that does not have one.
var ErrNoRemote = errors.New("backup: no such backup remote")

// Remote is one configured destination, ready to be used.
type Remote struct {
	cfg config.BackupRemote
	s3  *s3Client
}

// NewRemote builds a client for one configured remote.
func NewRemote(cfg config.BackupRemote, httpClient *http.Client) (*Remote, error) {
	client, err := newS3Client(cfg.Endpoint, cfg.Region, cfg.Bucket, cfg.AccessKeyID, cfg.SecretAccessKey, cfg.PathStyle, httpClient)
	if err != nil {
		return nil, fmt.Errorf("the backup remote %s: %w", cfg.Name, err)
	}
	return &Remote{cfg: cfg, s3: client}, nil
}

// Name is what this destination is called.
func (r *Remote) Name() string { return r.cfg.Name }

// Where is the bucket and prefix, for a log line or a row on the page.
func (r *Remote) Where() string { return r.cfg.Where() }

// Endpoint is the service it talks to.
func (r *Remote) Endpoint() string { return r.cfg.Endpoint }

// Encrypted says the archive is sealed before it leaves this host.
func (r *Remote) Encrypted() bool { return r.cfg.Encrypted() }

// Keep is how many copies this remote holds; 0 keeps every one.
func (r *Remote) Keep() int { return r.cfg.Keep }

// Key is where a backup with this id lands in the bucket.
func (r *Remote) Key(id string) string {
	name := ArchiveName(id, r.Encrypted())
	if r.cfg.Prefix == "" {
		return name
	}
	return r.cfg.Prefix + "/" + name
}

// Copy is one backup as a bucket holds it: an archive, not a directory.
type Copy struct {
	// Remote is the destination's name, so a list gathered from several says
	// which came from where.
	Remote string `json:"remote"`
	// ID is the backup's own id, read back out of the key, so a copy in a
	// bucket and the copy on disk it came from have one name.
	ID string `json:"id"`
	// Key is the object's full key, which is what an operator needs to find
	// it with any other tool.
	Key string `json:"key"`
	// Bytes is the archive's size, which is the compressed database rather
	// than the database.
	Bytes int64 `json:"bytes"`
	// StoredAt is when the object was written, from the service. It is not
	// when the backup was taken -- an old backup uploaded today is stored
	// today -- and the id carries the other.
	StoredAt time.Time `json:"stored_at"`
	// TakenAt is read from the id, which is the only thing about the backup a
	// listing can know without downloading it.
	TakenAt time.Time `json:"taken_at"`
	// Encrypted says the archive is sealed and needs the remote's passphrase.
	Encrypted bool `json:"encrypted"`
}

// Check asks the bucket one cheap question -- list one key under the prefix --
// which is the whole of what has to work for a backup to reach it: the
// endpoint resolves, TLS agrees, the signature is accepted, the bucket exists,
// and the policy allows reading it.
//
// It is what the settings page's "test this remote" runs, so that a mistyped
// secret is found when it is typed rather than at three in the morning.
func (r *Remote) Check(ctx context.Context) error {
	_, err := r.s3.list(ctx, r.cfg.Prefix, 1)
	return err
}

// List is every backup this remote holds, newest first.
//
// It holds an object only if it sits directly in this remote's own directory,
// which is exactly where Key writes it. A bucket's prefix match is a string
// match, so "prod" also finds "prod-eu/..." and "zoomies" finds
// "zoomies/prod/..."; an empty prefix finds the whole bucket. Retention runs on
// this list, so accepting those would have one fleet delete another's offsite
// backups.
//
// Anything else in the directory that is not named like an archive this
// package writes is ignored rather than reported: an operator's bucket is
// allowed to hold other things, and a listing that complained about them would
// be a listing nobody reads.
func (r *Remote) List(ctx context.Context) ([]Copy, error) {
	dir := r.dir()
	listPrefix := r.cfg.Prefix
	if dir != "." {
		listPrefix = dir + "/"
	}
	objects, err := r.s3.list(ctx, listPrefix, 0)
	if err != nil {
		return nil, err
	}
	out := []Copy{}
	for _, o := range objects {
		if path.Dir(o.Key) != dir {
			continue
		}
		id, encrypted, ok := idFromKey(o.Key)
		if !ok {
			continue
		}
		out = append(out, Copy{
			Remote: r.cfg.Name, ID: id, Key: o.Key, Bytes: o.Size,
			StoredAt: o.LastModified, TakenAt: takenFromName(id), Encrypted: encrypted,
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID > out[j].ID })
	return out, nil
}

// dir is the directory Key puts this remote's archives in, in the form
// path.Dir reports for an object key: "." for the bucket's root.
func (r *Remote) dir() string {
	if dir := strings.Trim(r.cfg.Prefix, "/"); dir != "" {
		return dir
	}
	return "."
}

// idFromKey reads a backup's id back out of an object key, and says whether
// the archive is encrypted. It looks at the name alone; List is what checks
// that the key's directory is this remote's own.
func idFromKey(key string) (id string, encrypted bool, ok bool) {
	name := path.Base(key)
	if strings.HasSuffix(name, EncryptedExt) {
		encrypted = true
		name = strings.TrimSuffix(name, EncryptedExt)
	}
	name, found := strings.CutSuffix(name, ".tar.gz")
	if !found || !ValidID(name) {
		return "", false, false
	}
	return name, encrypted, true
}

// Upload copies one backup into the bucket and returns what landed there.
//
// The archive is written to a file beside the backup first rather than
// streamed straight out. A signed PUT names the length and the digest of what
// it is sending, which is what lets the service refuse a transfer that arrived
// altered instead of storing it and saying nothing -- and neither is knowable
// until the last byte of a gzip stream has been produced. The spool costs one
// compressed copy of the database, briefly, on the volume the backup is
// already on.
func (r *Remote) Upload(ctx context.Context, entry *Entry) (*Copy, error) {
	spool, err := os.CreateTemp(filepath.Dir(entry.Dir), ".offsite-*")
	if err != nil {
		return nil, fmt.Errorf("backup: spooling %s for %s: %w", entry.ID, r.cfg.Name, err)
	}
	defer func() {
		spool.Close()
		_ = os.Remove(spool.Name())
	}()

	digest := sha256.New()
	var out io.Writer = io.MultiWriter(spool, digest)
	if r.Encrypted() {
		enc, err := NewEncryptor(out, r.cfg.Passphrase)
		if err != nil {
			return nil, err
		}
		if err := WriteArchive(enc, entry); err != nil {
			return nil, err
		}
		// Close writes the final chunk. Without it the file is a truncated
		// archive that will not open, which is the one failure a backup must
		// not be able to have.
		if err := enc.Close(); err != nil {
			return nil, err
		}
	} else if err := WriteArchive(out, entry); err != nil {
		return nil, err
	}

	size, err := spool.Seek(0, io.SeekEnd)
	if err != nil {
		return nil, err
	}
	if _, err := spool.Seek(0, io.SeekStart); err != nil {
		return nil, err
	}

	key := r.Key(entry.ID)
	if err := r.s3.put(ctx, key, spool, size, hex.EncodeToString(digest.Sum(nil))); err != nil {
		return nil, err
	}
	return &Copy{
		Remote: r.cfg.Name, ID: entry.ID, Key: key, Bytes: size,
		StoredAt: time.Now().UTC(), TakenAt: entry.TakenAt, Encrypted: r.Encrypted(),
	}, nil
}

// FetchOptions says who is pulling a copy back and how the archive opens.
type FetchOptions struct {
	// Passphrase overrides the remote's own, for an archive sealed with a
	// passphrase this configuration no longer carries -- which is what a
	// rotation leaves behind in a bucket.
	Passphrase string
	// TakenBy is recorded in the manifest of the copy that lands on disk.
	TakenBy string
	// MaxBytes bounds the unpacked database. Zero is unbounded.
	MaxBytes int64
	// Now is the clock; nil uses the wall clock.
	Now func() time.Time
}

// Fetch pulls one copy out of the bucket and unpacks it into root, where it is
// an ordinary backup: listed, verifiable, and restorable by the same staging
// the Backups tab does everything else through.
//
// It is deliberately two steps rather than "restore from the bucket". A
// restore swaps the database this fleet runs on, and the file it swaps in
// should be one somebody has seen land, verified, and chosen -- not one that
// arrived and was applied in the same request.
func (r *Remote) Fetch(ctx context.Context, root, id string, opts FetchOptions) (*Entry, error) {
	if !ValidID(id) {
		return nil, fmt.Errorf("%w: %q", ErrInvalidID, id)
	}
	body, _, err := r.s3.get(ctx, r.Key(id))
	if err != nil {
		return nil, err
	}
	defer body.Close()

	passphrase := opts.Passphrase
	if strings.TrimSpace(passphrase) == "" {
		passphrase = r.cfg.Passphrase
	}
	var src io.Reader = body
	encrypted, peek := IsEncrypted(body)
	src = peek
	switch {
	case encrypted && strings.TrimSpace(passphrase) == "":
		return nil, errors.New("backup: this copy is encrypted and the remote has no passphrase configured; give the one it was sealed with")
	case encrypted:
		src, err = NewDecryptor(peek, passphrase)
		if err != nil {
			return nil, err
		}
	}

	entry, err := Unpack(ctx, root, src, UnpackOptions{
		Source: SourceFetched, TakenBy: opts.TakenBy, MaxBytes: opts.MaxBytes, Now: opts.Now,
	})
	if err != nil {
		return nil, err
	}
	return entry, nil
}

// Delete removes one copy from the bucket.
func (r *Remote) Delete(ctx context.Context, id string) error {
	if !ValidID(id) {
		return fmt.Errorf("%w: %q", ErrInvalidID, id)
	}
	return r.s3.remove(ctx, r.Key(id))
}

// Prune deletes all but the newest keep copies and returns the ids it removed.
// Zero keeps every one, exactly as backup.keep does on disk.
//
// It only ever removes an object whose key is one this package writes, under
// this remote's own prefix: a bucket shared with somebody else's backups is
// the normal case, and retention that guessed would eventually delete the
// wrong thing.
func (r *Remote) Prune(ctx context.Context, keep int) ([]string, error) {
	if keep <= 0 {
		return nil, nil
	}
	copies, err := r.List(ctx)
	if err != nil {
		return nil, err
	}
	if len(copies) <= keep {
		return nil, nil
	}
	var removed []string
	for _, c := range copies[keep:] {
		if err := r.s3.remove(ctx, c.Key); err != nil {
			return removed, err
		}
		removed = append(removed, c.ID)
	}
	return removed, nil
}

// Missing is the backups in entries that this remote does not already hold,
// newest first and no more than the remote keeps.
//
// It is what makes a remote catch up by itself. A bucket that was unreachable
// for two nights is two backups behind, and the next pass sends both rather
// than only the one it happens to have been asked about -- while a remote
// keeping three copies is never sent the fourth-oldest backup only to delete
// it again a second later.
func Missing(entries []Entry, held []Copy, keep int) []Entry {
	have := map[string]bool{}
	for _, c := range held {
		have[c.ID] = true
	}
	var ours []Entry
	for _, e := range entries {
		// A backup with no database, or one this fleet did not take, is not
		// something to put in somebody's bucket by itself.
		if e.Problem != "" || e.Source == SourcePreMigration {
			continue
		}
		ours = append(ours, e)
	}
	if keep > 0 && len(ours) > keep {
		ours = ours[:keep]
	}
	out := []Entry{}
	for _, e := range ours {
		if !have[e.ID] {
			out = append(out, e)
		}
	}
	// Oldest first, so an interrupted catch-up leaves the bucket holding a
	// contiguous run rather than a gap.
	slices.Reverse(out)
	return out
}

package backup

import (
	"context"
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// Where a backup destination comes from, and which one wins.
//
// There are two places a destination can be described, and both are right for
// the case they exist for. `backup.remotes` in zoomies.yaml is readable on a
// host whose database is gone, which is the day an offsite copy is for; a row
// in the database is editable, testable and rotatable from the Backups page
// without a file to open or a controller to restart.
//
// A name in both is the file's. That is the rule the rest of the configuration
// follows -- the file and the environment have the last word -- and it is the
// safe way round: an administrator who cannot reach the page can still correct
// a destination by editing the file, and the row being shadowed is reported as
// shadowed rather than silently ignored.
//
// The merge lives here rather than in the controller because three callers
// need the same answer: the controller's pass, the API, and `zoomies restore
// --from-remote` on a host where no controller is running. A second copy of
// this rule would eventually disagree with the first, and the disagreement
// would be about where a fleet's backups are.

// The two places a destination is described, as the API names them.
const (
	OriginFile     = "file"
	OriginDatabase = "database"
)

// RemoteLister is the half of the store this needs: a fleet that cannot read
// its rows still has the file's destinations, and says so.
type RemoteLister interface {
	ListBackupRemotes(ctx context.Context) ([]*store.BackupRemote, error)
}

// ResolvedRemote is one destination ready to be used, and what a page needs to
// know about where it came from.
type ResolvedRemote struct {
	// Remote is the destination itself, secrets in hand.
	Remote config.BackupRemote
	// Origin is OriginFile or OriginDatabase.
	Origin string
	// ID is the database row's id, empty for a file's destination. It is what
	// an audit entry names, because a name can be edited and an id cannot.
	ID string
	// Shadowed is a stored destination the file overrides by name. It is kept
	// in the list so a page can say so: a row that quietly does nothing is the
	// failure this design exists to avoid.
	Shadowed bool
	// Problem is why a stored destination cannot be used at all -- almost
	// always that this controller's key does not open its secrets, which is
	// what a database restored onto a host with the wrong key looks like.
	Problem string
}

// Usable reports whether a copy would actually be sent here.
func (r ResolvedRemote) Usable() bool {
	return !r.Shadowed && r.Problem == "" && r.Remote.Enabled()
}

// ResolveRemotes is every destination a fleet has: the file's first, then the
// stored ones in the order the database lists them.
//
// A stored destination whose secrets the key does not open is returned with
// its Problem set and disabled rather than dropped. Trying it every hour would
// have the service refuse it, which reads as the bucket's fault rather than
// this host's; dropping it would make a destination an operator can see in the
// database vanish from the page with no explanation.
func ResolveRemotes(ctx context.Context, cfg *config.Config, rows RemoteLister, key *cryptox.Key) ([]ResolvedRemote, error) {
	out := make([]ResolvedRemote, 0, len(cfg.Backup.Remotes))
	named := map[string]bool{}
	for _, r := range cfg.Backup.Remotes {
		named[r.Name] = true
		out = append(out, ResolvedRemote{Remote: r, Origin: OriginFile})
	}
	if rows == nil {
		return out, nil
	}

	stored, err := rows.ListBackupRemotes(ctx)
	if err != nil {
		return out, err
	}
	for _, row := range stored {
		resolved := ResolvedRemote{
			Origin: OriginDatabase, ID: row.ID, Shadowed: named[row.Name],
			Remote: config.BackupRemote{
				Name: row.Name, Endpoint: row.Endpoint, Region: row.Region,
				Bucket: row.Bucket, Prefix: row.Prefix, AccessKeyID: row.AccessKeyID,
				PathStyle: row.PathStyle, Keep: row.Keep, Disabled: !row.Enabled,
			},
		}
		if err := openRemoteSecrets(row, key, &resolved.Remote); err != nil {
			resolved.Problem = err.Error()
			resolved.Remote.Disabled = true
		}
		out = append(out, resolved)
	}
	return out, nil
}

// FindResolvedRemote is one destination by the name every surface addresses it
// with, or ErrNoRemote.
func FindResolvedRemote(ctx context.Context, cfg *config.Config, rows RemoteLister, key *cryptox.Key, name string) (ResolvedRemote, error) {
	name = strings.TrimSpace(name)
	resolved, err := ResolveRemotes(ctx, cfg, rows, key)
	if err != nil {
		return ResolvedRemote{}, err
	}
	for _, r := range resolved {
		if r.Remote.Name != name || r.Shadowed {
			continue
		}
		switch {
		case r.Problem != "":
			return ResolvedRemote{}, fmt.Errorf("the backup remote %s cannot be used: %s", name, r.Problem)
		case !r.Remote.Enabled():
			return ResolvedRemote{}, fmt.Errorf("the backup remote %s is switched off or incomplete", name)
		}
		return r, nil
	}
	return ResolvedRemote{}, fmt.Errorf("%w: %q", ErrNoRemote, name)
}

// openRemoteSecrets unseals a stored destination's secret key and passphrase.
func openRemoteSecrets(row *store.BackupRemote, key *cryptox.Key, into *config.BackupRemote) error {
	if len(row.SecretKeyEnc) == 0 && len(row.PassphraseEnc) == 0 {
		return nil
	}
	if key == nil {
		return fmt.Errorf("this controller holds no encryption key, so the secret key stored for %s cannot be opened", row.Name)
	}
	if len(row.SecretKeyEnc) > 0 {
		secret, err := key.OpenString(row.SecretKeyEnc)
		if err != nil {
			return fmt.Errorf("the secret key stored for %s does not open with this instance's encryption key (%s): %w",
				row.Name, key.Fingerprint(), err)
		}
		into.SecretAccessKey = secret
	}
	if len(row.PassphraseEnc) > 0 {
		passphrase, err := key.OpenString(row.PassphraseEnc)
		if err != nil {
			return fmt.Errorf("the passphrase stored for %s does not open with this instance's encryption key (%s): %w",
				row.Name, key.Fingerprint(), err)
		}
		into.Passphrase = passphrase
	}
	return nil
}

package backup

import (
	"context"
	"errors"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// fakeStore is an object store that lasts as long as the test.
func fakeStore(t *testing.T) *FakeS3 {
	t.Helper()
	f := NewFakeS3("backups")
	t.Cleanup(f.Close)
	return f
}

// remoteFor is a configured remote pointed at the fake, with whatever the test
// wants changed about it.
func remoteFor(t *testing.T, f *FakeS3, adjust func(*config.BackupRemote)) *Remote {
	t.Helper()
	cfg := config.BackupRemote{
		Name: "offsite", Endpoint: f.Endpoint(), Bucket: f.Bucket(), Prefix: "fleet",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
	}
	if adjust != nil {
		adjust(&cfg)
	}
	remote, err := NewRemote(cfg, nil)
	if err != nil {
		t.Fatalf("NewRemote: %v", err)
	}
	return remote
}

// takeOne is one backup on disk, which is what every remote operation is about.
func takeOne(t *testing.T, at time.Time) (*config.Config, *Entry) {
	t.Helper()
	cfg, st, _ := host(t)
	entry, err := Take(context.Background(), st, TakeOptions{
		Config: cfg, Source: SourceScheduled, TakenBy: "the schedule",
		Now: func() time.Time { return at },
	})
	if err != nil {
		t.Fatalf("Take: %v", err)
	}
	return cfg, entry
}

// The whole point, end to end: a backup taken here is in the bucket, comes
// back out of it, and is an ordinary backup when it does -- because a copy
// nobody has ever restored is a copy nobody knows about.
func TestUploadingABackupAndFetchingItBackGivesTheSameBackup(t *testing.T) {
	f := fakeStore(t)
	remote := remoteFor(t, f, nil)
	_, entry := takeOne(t, time.Date(2026, 3, 1, 2, 0, 0, 0, time.UTC))

	copied, err := remote.Upload(context.Background(), entry)
	if err != nil {
		t.Fatalf("Upload: %v", err)
	}
	if copied.Key != "fleet/"+entry.ID+".tar.gz" {
		t.Errorf("stored at %q, which is not the prefix and name a restore would look for", copied.Key)
	}
	if copied.Bytes <= 0 {
		t.Errorf("the copy reports %d bytes", copied.Bytes)
	}

	held, err := remote.List(context.Background())
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(held) != 1 || held[0].ID != entry.ID {
		t.Fatalf("the bucket lists %+v, wanted the one backup %s", held, entry.ID)
	}
	if held[0].TakenAt.IsZero() {
		t.Error("a listing should be able to say when a backup was taken from its id alone")
	}

	// Somewhere else entirely, as a second fleet's directory would be.
	root := filepath.Join(t.TempDir(), "restored")
	fetched, err := remote.Fetch(context.Background(), root, entry.ID, FetchOptions{TakenBy: "alice"})
	if err != nil {
		t.Fatalf("Fetch: %v", err)
	}
	if fetched.ID != entry.ID {
		t.Errorf("fetched %s, wanted %s", fetched.ID, entry.ID)
	}
	if fetched.Source != SourceFetched {
		t.Errorf("the fetched copy says it came from %q; it came out of a bucket", fetched.Source)
	}
	if fetched.Manifest == nil || fetched.Manifest.Database.SHA256 != entry.Manifest.Database.SHA256 {
		t.Fatal("the fetched database is not the one that was uploaded")
	}

	v, err := Verify(context.Background(), root, fetched.ID)
	if err != nil {
		t.Fatalf("Verify: %v", err)
	}
	if !v.OK {
		t.Errorf("the copy that came back does not verify: %v", v.Problems)
	}
}

// A remote with a passphrase must put an encrypted file in the bucket, not a
// database with a different name: the file is on somebody else's disk, and
// whoever holds the bucket is not the person who is allowed to read the fleet.
func TestAnEncryptedRemoteUploadsSomethingThatDoesNotOpenWithoutThePassphrase(t *testing.T) {
	f := fakeStore(t)
	remote := remoteFor(t, f, func(r *config.BackupRemote) { r.Passphrase = "a long passphrase" })
	_, entry := takeOne(t, time.Date(2026, 3, 1, 2, 0, 0, 0, time.UTC))

	copied, err := remote.Upload(context.Background(), entry)
	if err != nil {
		t.Fatalf("Upload: %v", err)
	}
	if !strings.HasSuffix(copied.Key, ".tar.gz"+EncryptedExt) {
		t.Errorf("an encrypted copy is stored at %q, which does not say it is encrypted", copied.Key)
	}

	// The same remote, minus the passphrase, is what somebody holding the
	// bucket has: the bytes and nothing else.
	blind := remoteFor(t, f, func(r *config.BackupRemote) {
		r.Passphrase = ""
	})
	// Its key has no .enc, so it does not even find the object -- and asked
	// for the encrypted one, it cannot open it.
	if _, err := blind.Fetch(context.Background(), t.TempDir(), entry.ID, FetchOptions{}); err == nil {
		t.Error("an unencrypted remote fetched an encrypted copy")
	}
	if _, err := remote.Fetch(context.Background(), t.TempDir(), entry.ID, FetchOptions{Passphrase: "the wrong one"}); err == nil {
		t.Error("the wrong passphrase opened the archive")
	}

	root := t.TempDir()
	fetched, err := remote.Fetch(context.Background(), root, entry.ID, FetchOptions{})
	if err != nil {
		t.Fatalf("Fetch with the remote's own passphrase: %v", err)
	}
	if fetched.Manifest == nil || fetched.Manifest.Database.SHA256 != entry.Manifest.Database.SHA256 {
		t.Error("what came back is not what went in")
	}
}

// Retention on the remote keeps the newest and nothing else, and it only ever
// removes keys this package writes -- a bucket is usually shared.
func TestRemoteRetentionKeepsTheNewestAndLeavesStrangersAlone(t *testing.T) {
	f := fakeStore(t)
	remote := remoteFor(t, f, nil)
	f.Put("fleet/somebody-elses-backup.tar.gz", []byte("not ours"))

	cfg, st, _ := host(t)
	var ids []string
	for i := range 4 {
		at := time.Date(2026, 3, 1, 2, i, 0, 0, time.UTC)
		entry, err := Take(context.Background(), st, TakeOptions{Config: cfg, Source: SourceScheduled, Now: func() time.Time { return at }})
		if err != nil {
			t.Fatalf("Take: %v", err)
		}
		if _, err := remote.Upload(context.Background(), entry); err != nil {
			t.Fatalf("Upload: %v", err)
		}
		ids = append(ids, entry.ID)
	}

	removed, err := remote.Prune(context.Background(), 2)
	if err != nil {
		t.Fatalf("Prune: %v", err)
	}
	if len(removed) != 2 {
		t.Fatalf("removed %v, wanted the two oldest", removed)
	}
	held, err := remote.List(context.Background())
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(held) != 2 || held[0].ID != ids[3] || held[1].ID != ids[2] {
		t.Errorf("the bucket holds %+v, wanted the newest two", held)
	}
	for _, key := range f.Keys() {
		if key == "fleet/somebody-elses-backup.tar.gz" {
			return
		}
	}
	t.Error("retention deleted an object this package did not write")
}

// A remote that was unreachable for two nights is two backups behind, and the
// next pass has to send both. Missing is what decides that, and it is a pure
// function so the rule is testable without a bucket.
func TestMissingSendsTheBacklogButNeverMoreThanTheRemoteKeeps(t *testing.T) {
	entries := []Entry{
		{ID: "zoomies-20260304-020000", Source: SourceScheduled},
		{ID: "zoomies-20260303-020000", Source: SourceScheduled},
		{ID: "zoomies-20260302-020000", Source: SourceScheduled},
		{ID: "zoomies-20260301-020000", Source: SourceScheduled},
	}
	held := []Copy{{ID: "zoomies-20260301-020000"}}

	missing := Missing(entries, held, 0)
	if len(missing) != 3 {
		t.Fatalf("with no ceiling, %d of the backlog would be sent; wanted 3", len(missing))
	}
	if missing[0].ID != "zoomies-20260302-020000" {
		t.Errorf("the backlog starts at %s; it is sent oldest first, so an interrupted catch-up leaves the bucket holding a contiguous run rather than a gap", missing[0].ID)
	}

	// A remote keeping two is never sent the third-oldest only to delete it.
	missing = Missing(entries, held, 2)
	if len(missing) != 2 || missing[0].ID != "zoomies-20260303-020000" {
		t.Errorf("with keep=2 the backlog is %+v; wanted only the newest two", missing)
	}

	// The store's pre-migration copies have no manifest and are the fleet's
	// own scaffolding, not its backups.
	pre := append([]Entry{{ID: "zoomies-20260305-020000", Source: SourcePreMigration}}, entries...)
	for _, e := range Missing(pre, nil, 0) {
		if e.Source == SourcePreMigration {
			t.Error("a pre-migration copy was queued for a bucket")
		}
	}

	// A backup whose database has gone is not something to upload.
	broken := []Entry{{ID: "zoomies-20260306-020000", Source: SourceScheduled, Problem: "the database is missing"}}
	if got := Missing(broken, nil, 0); len(got) != 0 {
		t.Errorf("a broken backup was queued for a bucket: %+v", got)
	}
}

// What a remote refuses has to arrive as a sentence an operator can act on:
// the fix for a wrong secret and the fix for a missing bucket are different
// jobs, and "403" is neither.
func TestARefusedRequestSaysWhatToDoAboutIt(t *testing.T) {
	f := fakeStore(t)
	remote := remoteFor(t, f, nil)

	for _, tc := range []struct {
		name   string
		status int
		code   string
		want   string
	}{
		{"a bucket that is not there", 404, "NoSuchBucket", "never creates one"},
		{"a secret that is wrong", 403, "SignatureDoesNotMatch", "secret access key is wrong"},
		{"a policy that says no", 403, "AccessDenied", "s3:PutObject"},
		{"a clock that has drifted", 403, "RequestTimeTooSkewed", "clock"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f.BreakWith(tc.status, tc.code, "refused")
			defer f.Mend()
			err := remote.Check(context.Background())
			if err == nil {
				t.Fatal("the check passed against a service that refused it")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("the error reads %q, which does not tell the operator about %q", err, tc.want)
			}
		})
	}
}

// A remote holds one fleet's copies under a prefix; a bucket shared with
// another fleet must not make one appear in the other's list.
func TestAListingIsScopedToTheRemotesOwnPrefix(t *testing.T) {
	f := fakeStore(t)
	ours := remoteFor(t, f, func(r *config.BackupRemote) { r.Prefix = "prod" })
	theirs := remoteFor(t, f, func(r *config.BackupRemote) { r.Name = "other"; r.Prefix = "staging" })

	cfg, st, _ := host(t)
	entry, err := Take(context.Background(), st, TakeOptions{Config: cfg, Source: SourceScheduled})
	if err != nil {
		t.Fatalf("Take: %v", err)
	}
	if _, err := theirs.Upload(context.Background(), entry); err != nil {
		t.Fatalf("Upload: %v", err)
	}

	held, err := ours.List(context.Background())
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(held) != 0 {
		t.Errorf("the prod remote lists %+v, which is staging's", held)
	}
}

// A raw string prefix is not a directory: "prod" also matches "prod-eu/...",
// "zoomies" matches "zoomies/prod/...", and an empty prefix matches the whole
// bucket. Retention that listed by string prefix would delete another fleet's
// offsite backups without a word, which is the one failure it must not have.
func TestAListingNeverReachesIntoASiblingOrNestedPrefix(t *testing.T) {
	for _, tc := range []struct{ ours, theirs string }{
		{"prod", "prod-eu"},
		{"zoomies", "zoomies/prod"},
		{"", "staging"},
	} {
		t.Run(tc.ours+" against "+tc.theirs, func(t *testing.T) {
			f := fakeStore(t)
			ours := remoteFor(t, f, func(r *config.BackupRemote) { r.Prefix = tc.ours })
			theirs := remoteFor(t, f, func(r *config.BackupRemote) { r.Name = "other"; r.Prefix = tc.theirs })
			ctx := context.Background()

			base := time.Date(2026, 1, 1, 2, 0, 0, 0, time.UTC)
			// Theirs are older than ours, so a listing that merged the two would
			// hand them to retention first.
			for i := 0; i < 2; i++ {
				_, entry := takeOne(t, base.Add(time.Duration(i)*time.Hour))
				if _, err := theirs.Upload(ctx, entry); err != nil {
					t.Fatalf("Upload: %v", err)
				}
			}
			_, entry := takeOne(t, base.Add(48*time.Hour))
			if _, err := ours.Upload(ctx, entry); err != nil {
				t.Fatalf("Upload: %v", err)
			}

			held, err := ours.List(ctx)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if len(held) != 1 || held[0].ID != entry.ID {
				t.Fatalf("the %q remote lists %+v, which is not just its own copy", tc.ours, held)
			}

			removed, err := ours.Prune(ctx, 1)
			if err != nil {
				t.Fatalf("Prune: %v", err)
			}
			if len(removed) != 0 {
				t.Errorf("pruning the %q remote removed %v, which are %q's", tc.ours, removed, tc.theirs)
			}
			kept, err := theirs.List(ctx)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if len(kept) != 2 {
				t.Errorf("the %q remote holds %d copies after the other's retention pass, wanted 2", tc.theirs, len(kept))
			}
		})
	}
}

// The endpoint decides the request style, because the alternative is a setting
// that silently disagrees with the endpoint: a bucket in the hostname needs
// DNS nobody arranges for a MinIO on a private network.
func TestPathStyleIsChosenByTheEndpointUnlessItIsSaid(t *testing.T) {
	yes, no := true, false
	for _, tc := range []struct {
		endpoint  string
		pathStyle *bool
		want      string
	}{
		{"https://s3.eu-west-2.amazonaws.com", nil, "https://backups.s3.eu-west-2.amazonaws.com/k"},
		{"http://minio:9000", nil, "http://minio:9000/backups/k"},
		{"https://s3.eu-west-2.amazonaws.com", &yes, "https://s3.eu-west-2.amazonaws.com/backups/k"},
		{"http://minio:9000", &no, "http://backups.minio:9000/k"},
	} {
		client, err := newS3Client(tc.endpoint, "", "backups", "id", "secret", tc.pathStyle, nil)
		if err != nil {
			t.Fatalf("newS3Client(%s): %v", tc.endpoint, err)
		}
		if got := client.url("k").String(); got != tc.want {
			t.Errorf("%s addresses a key as %s, wanted %s", tc.endpoint, got, tc.want)
		}
	}
}

// The signature is the one part of this with an external definition, so it is
// checked against the example AWS documents it with rather than against
// itself.
func TestTheCanonicalRequestIsEncodedTheWayTheSignatureDefinesIt(t *testing.T) {
	if got := uriEncode("a b/c~d.e", false); got != "a%20b/c~d.e" {
		t.Errorf("a path encodes as %q; a space is %%20, a tilde and a dot are themselves, and a slash stays", got)
	}
	if got := uriEncode("a b/c", true); got != "a%20b%2Fc" {
		t.Errorf("a query value encodes as %q; outside a path a slash is encoded too", got)
	}
	if emptyPayloadSHA256 != "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855" {
		t.Error("the empty payload digest is not the digest of no bytes, so every unsigned-body request would be refused")
	}
}

// The merge rule has to hold for every caller -- the controller's pass, the
// API and `zoomies restore --from-remote` on a host with no controller -- so
// it is tested where it lives rather than three times over.
func TestTheFileWinsAndAStoredSecretThatWillNotOpenIsReported(t *testing.T) {
	f := fakeStore(t)
	cfg := config.Default()
	cfg.Backup.Remotes = []config.BackupRemote{{
		Name: "offsite", Endpoint: f.Endpoint(), Bucket: f.Bucket(),
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "from-the-file",
	}}
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	sealed, err := key.SealString("from-the-database")
	if err != nil {
		t.Fatalf("SealString: %v", err)
	}
	stranger, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	strange, err := stranger.SealString("somebody else's")
	if err != nil {
		t.Fatalf("SealString: %v", err)
	}

	rows := fakeRemotes{
		{ID: "bkr_1", Name: "offsite", Endpoint: "https://elsewhere.example.com", Bucket: "other",
			AccessKeyID: "a", SecretKeyEnc: sealed, Enabled: true},
		{ID: "bkr_2", Name: "second", Endpoint: "https://s3.example.com", Bucket: "second",
			AccessKeyID: "b", SecretKeyEnc: sealed, Enabled: true},
		{ID: "bkr_3", Name: "strange", Endpoint: "https://s3.example.com", Bucket: "third",
			AccessKeyID: "c", SecretKeyEnc: strange, Enabled: true},
	}

	resolved, err := ResolveRemotes(context.Background(), cfg, rows, key)
	if err != nil {
		t.Fatalf("ResolveRemotes: %v", err)
	}
	if len(resolved) != 4 {
		t.Fatalf("resolved %d destinations, wanted the file's and all three rows", len(resolved))
	}
	if resolved[0].Origin != OriginFile || resolved[0].Remote.SecretAccessKey != "from-the-file" {
		t.Errorf("the file's destination reads %+v", resolved[0])
	}
	if !resolved[1].Shadowed || resolved[1].Usable() {
		t.Errorf("the stored destination of the same name is %+v; the file has the last word", resolved[1])
	}
	if resolved[2].Remote.SecretAccessKey != "from-the-database" || !resolved[2].Usable() {
		t.Errorf("a stored destination with its own name reads %+v", resolved[2])
	}
	if resolved[3].Problem == "" || resolved[3].Usable() {
		t.Errorf("a stored destination sealed with another key reads %+v; it must not be tried", resolved[3])
	}

	// And the lookup every route uses agrees with the list.
	found, err := FindResolvedRemote(context.Background(), cfg, rows, key, "offsite")
	if err != nil || found.Origin != OriginFile {
		t.Errorf("looking up offsite gave %+v, %v", found, err)
	}
	if _, err := FindResolvedRemote(context.Background(), cfg, rows, key, "strange"); err == nil {
		t.Error("a destination whose secret will not open was handed out")
	}
	if _, err := FindResolvedRemote(context.Background(), cfg, rows, key, "nowhere"); !errors.Is(err, ErrNoRemote) {
		t.Errorf("an unknown name gave %v", err)
	}

	// A fleet with no database at all still has the file's destinations,
	// which is the case `zoomies restore --from-remote` exists for.
	resolved, err = ResolveRemotes(context.Background(), cfg, nil, key)
	if err != nil || len(resolved) != 1 || resolved[0].Origin != OriginFile {
		t.Errorf("with no database the fleet resolved %+v, %v", resolved, err)
	}
}

// fakeRemotes is a stored-destination list without a database behind it.
type fakeRemotes []store.BackupRemote

func (f fakeRemotes) ListBackupRemotes(context.Context) ([]*store.BackupRemote, error) {
	out := make([]*store.BackupRemote, len(f))
	for i := range f {
		row := f[i]
		out[i] = &row
	}
	return out, nil
}

package backup

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// A restore is the one operation here that touches the live database, and
// every refusal in it is one an operator would otherwise discover after the
// controller was running on the restored data, which is the worst moment: the
// fleet is live, the original may already be gone, and the symptom -- a
// decryption error, a schema nobody understands -- says nothing about the
// restore that caused it. So the checks run before anything is moved, and the
// same checks run whether the restore was asked for on the command line or
// staged from the settings page.

// ErrControllerRunning is a restore attempted under a live controller.
var ErrControllerRunning = errors.New("backup: a controller is running on this database")

// RestoreOptions is what a restore may be asked to do beyond putting the file
// back.
type RestoreOptions struct {
	// Replace allows a database already at database.path to be moved aside.
	// Without it, an existing database is refused.
	Replace bool
	// RevokeAPITokens and ResetAgentTokens go further than the defaults,
	// because each has a cost only the operator can weigh: revoking API
	// tokens breaks whatever automation holds them, and resetting agent
	// tokens means walking every host.
	RevokeAPITokens  bool
	ResetAgentTokens bool
	// Now is the clock; nil uses the wall clock.
	Now func() time.Time
}

// RestoreReport is what a restore did, in the order it did it, written for
// the person who asked for it.
type RestoreReport struct {
	Source string `json:"source"`
	// MovedAside is where the database that was there went, if there was one.
	MovedAside string `json:"moved_aside,omitempty"`
	// MovedLogs names a write-ahead log that had outlived its database and
	// was kept rather than replayed.
	MovedLogs []string `json:"moved_logs,omitempty"`
	// KeyChecked says the manifest's fingerprint was compared with this
	// host's key, and matched.
	KeyChecked bool `json:"key_checked"`
	// ManifestProblem says why the manifest could not be checked, when it
	// could not. The database itself was still verified.
	ManifestProblem string `json:"manifest_problem,omitempty"`
	// Invalidated is what the restore took away, one line each.
	Invalidated []string `json:"invalidated"`
	// Fenced is the reason recorded on the fence.
	Fenced string `json:"fenced"`
}

// Check runs every pre-flight a restore makes and moves nothing: is the copy
// sound, can this build read it, and is the key on this host the one that
// sealed it. It returns the manifest, which may be nil when the backup has
// none, and the reason the manifest could not be read when that is so.
func Check(ctx context.Context, cfg *config.Config, dir string) (*Manifest, string, error) {
	dbPath := filepath.Join(dir, DBName)
	if _, err := os.Stat(dbPath); err != nil {
		return nil, "", fmt.Errorf("%s does not look like a Zoomies backup: %w", dir, err)
	}
	m, merr := ReadManifest(dir)
	problem := ""
	if merr != nil {
		problem = merr.Error()
		m = nil
	}
	// Checked in the order an operator would want to be stopped: is this
	// file sound, can this binary read it, and is the key on this host the
	// one that opens it?
	if err := checkCopy(ctx, dbPath); err != nil {
		return m, problem, err
	}
	if m != nil {
		if err := checkKey(cfg, m); err != nil {
			return m, problem, err
		}
	}
	return m, problem, nil
}

// checkCopy opens the backup's database and asks it two questions: is it
// sound, and can this binary read it?
//
// The second is the one that catches a rollback. The store refuses a ledger
// naming migrations this build does not have, so restoring a backup from a
// newer release onto an older binary stops here with the names, rather than
// after the controller has been started on it.
func checkCopy(ctx context.Context, path string) error {
	st, err := store.Open(ctx, store.Options{Path: path, ReadOnly: true})
	if err != nil {
		if errors.Is(err, store.ErrSchemaNewer) {
			return fmt.Errorf("this backup was written by a newer release than %s: %w", version.Short(), err)
		}
		return fmt.Errorf("opening the backup's database: %w", err)
	}
	defer func() { _ = st.Close() }()
	return st.IntegrityCheck(ctx)
}

// checkKey compares the key this host is configured with against the one that
// sealed the backup.
//
// A mismatch is refused rather than warned about. The alternative is a
// controller that starts, reports itself healthy, and fails inside its first
// GitHub call -- and by then the original database may be gone.
func checkKey(cfg *config.Config, m *Manifest) error {
	if m.Key.Fingerprint == "" {
		return nil
	}
	key, err := ConfiguredKey(cfg)
	if err != nil {
		return fmt.Errorf("this backup needs the encryption key whose fingerprint is %s, and this host has none: %w "+
			"(put it where security.encryption_key_file points, or pass it in ZOOMIES_ENCRYPTION_KEY)", m.Key.Fingerprint, err)
	}
	if got := key.Fingerprint(); got != m.Key.Fingerprint {
		return fmt.Errorf("the encryption key on this host (%s) is not the one that sealed this backup (%s). "+
			"Restoring anyway would produce a fleet that starts and cannot authenticate to GitHub; "+
			"put the right key in place first", got, m.Key.Fingerprint)
	}
	return nil
}

// ConfiguredKey resolves the key this host is configured with, without
// generating one: a restore is never a first run.
func ConfiguredKey(cfg *config.Config) (*cryptox.Key, error) {
	if raw := strings.TrimSpace(cfg.Security.EncryptionKey); raw != "" {
		return cryptox.ParseKey(raw)
	}
	if path := strings.TrimSpace(cfg.Security.EncryptionKeyFile); path != "" {
		return cryptox.LoadKeyFile(path)
	}
	return nil, cryptox.ErrNoKey
}

// Restore puts the backup at dir in place at cfg.Database.Path.
//
// The caller holds the database lock, or is certain nothing else does: Lock
// is the same lock a controller takes before it opens the database, and
// holding it for the whole swap both proves none is running now and stops one
// starting halfway through. Renaming a file does not reach a process that
// already has it open, so a restore under a live controller loses whatever
// the fleet did while the file was being replaced, silently.
//
// It restores the database and nothing else. The encryption key, the
// configuration and the service unit are the operator's to put back, because
// each of them is a decision about this host rather than a copy of the data.
func Restore(ctx context.Context, cfg *config.Config, dir string, opts RestoreOptions) (*RestoreReport, error) {
	now := opts.Now
	if now == nil {
		now = time.Now
	}
	m, problem, err := Check(ctx, cfg, dir)
	if err != nil {
		return nil, err
	}
	report := &RestoreReport{Source: dir, ManifestProblem: problem, KeyChecked: m != nil && m.Key.Fingerprint != "", Invalidated: []string{}}

	live := cfg.Database.Path
	backupDB := filepath.Join(dir, DBName)
	if err := os.MkdirAll(filepath.Dir(live), 0o750); err != nil {
		return nil, fmt.Errorf("creating %s: %w", filepath.Dir(live), err)
	}

	// Restoring a backup over itself would move the source aside and then
	// copy from a path that is no longer there, so it is refused while both
	// still exist. It is an easy mistake to make: the argument is a
	// directory, and pointing it at the state directory reads as "restore
	// what is here".
	if same, err := sameFile(backupDB, live); err != nil {
		return nil, err
	} else if same {
		return nil, fmt.Errorf("%s is the database being restored to, not a backup of it. "+
			"Point restore at a directory `zoomies backup` wrote", backupDB)
	}

	stamp := now().UTC().Format("20060102-150405")
	switch _, err := os.Stat(live); {
	case err == nil:
		if !opts.Replace {
			return nil, fmt.Errorf("%s already exists, and restoring over it would lose whatever is in it. "+
				"Pass --replace to overwrite it; a copy of it is taken first, beside it", live)
		}
		kept, err := setAsideLiveDatabase(live, stamp)
		if err != nil {
			return nil, err
		}
		report.MovedAside = kept

	case errors.Is(err, os.ErrNotExist):
		// The database is gone; its write-ahead log may not be. That pair is
		// exactly what a corrupt-database recovery leaves behind, and it is
		// the state a restore is most often run in.
		//
		// SQLite replays a log it finds beside a database, whatever database
		// wrote it. A restored database opened on top of somebody else's log
		// comes back "database disk image is malformed", and the replay
		// consumes and unlinks the log doing it: the committed transactions
		// that only existed in that log are gone, destroyed by a command that
		// then reported failure. So the log is moved aside rather than
		// removed. It is the last copy of whatever those transactions were,
		// and an operator who came here to recover data should not lose more
		// of it to the recovery.
		if !hasOrphanedLogs(live) {
			break
		}
		if !opts.Replace {
			return nil, fmt.Errorf("%s is gone but its write-ahead log is still there, and SQLite would replay "+
				"that log into whatever is restored, corrupting it and destroying the log in the process. "+
				"Pass --replace to move the log aside first; it is kept, not deleted, beside the database", live)
		}
		kept, err := setAsideOrphanedLogs(live, stamp)
		if err != nil {
			return nil, err
		}
		report.MovedLogs = kept

	default:
		return nil, fmt.Errorf("checking %s: %w", live, err)
	}

	if err := copyFile(backupDB, live); err != nil {
		return nil, err
	}
	if err := invalidate(ctx, live, dir, m, opts, report); err != nil {
		return nil, restoreUnfinished(err, live, report)
	}
	return report, nil
}

// restoreUnfinished says what state a restore that failed after the copy left
// behind. The copy has replaced the database by then, so "the restore failed"
// on its own reads as "nothing changed" -- and the controller would then start
// on the restored database believing it was the old one. Nothing is rolled
// back: the fence is what makes the restored copy safe to leave in place, and
// undoing a file swap on the strength of a failing disk is a second way to
// lose the database.
func restoreUnfinished(err error, live string, report *RestoreReport) error {
	var before string
	switch {
	case report.MovedAside != "":
		before = "The database that was there before is kept at " + report.MovedAside + "."
	case len(report.MovedLogs) > 0:
		before = "The write-ahead log that was left behind is kept at " + strings.Join(report.MovedLogs, ", ") + "."
	default:
		before = "There was no database there before."
	}
	if report.Fenced != "" {
		return fmt.Errorf("the backup was copied into place but the restore did not finish: %w. "+
			"The restored database is now in place at %s and its recovery fence is up, so this fleet will not act on "+
			"rented machines until an administrator lifts it, but some of the credentials a restore ends may still be live. %s "+
			"Put right what the error names and run the restore again", err, live, before)
	}
	return fmt.Errorf("the backup was copied into place but the restore did not finish: %w. "+
		"The restored database is now in place at %s and its recovery fence could not be set, so do not start a controller on it. %s "+
		"Put right what the error names and run the restore again, or move the kept database back", err, live, before)
}

// invalidate does the part that is not copying a file: it fences the fleet, and
// takes away the credentials the backup froze.
//
// The fence is written first. It is the one step whose absence is dangerous --
// a restored copy that has not been fenced may delete rented machines created
// after the backup -- so a failure part-way through leaves the fleet fenced
// rather than half-invalidated and free to act.
func invalidate(ctx context.Context, live, src string, m *Manifest, opts RestoreOptions, report *RestoreReport) error {
	st, err := store.Open(ctx, store.Options{Path: live})
	if err != nil {
		return fmt.Errorf("opening the restored database: %w", err)
	}
	defer func() { _ = st.Close() }()

	reason := "restored from " + src
	if m != nil && !m.TakenAt.IsZero() {
		reason = fmt.Sprintf("restored from %s, a backup taken %s", src, m.TakenAt.Format(time.RFC3339))
	}
	if err := st.SetRecoveryFence(ctx, true, reason); err != nil {
		return err
	}
	report.Fenced = reason

	sessions, err := st.DeleteAllSessions(ctx)
	if err != nil {
		return err
	}
	report.Invalidated = append(report.Invalidated, fmt.Sprintf("Ended %s: a cookie from the day of the backup would otherwise still be signed in.", countOf(int(sessions), "session")))

	joins, err := st.DeleteUnusedJoinTokens(ctx)
	if err != nil {
		return err
	}
	report.Invalidated = append(report.Invalidated, fmt.Sprintf("Removed %s that had never been redeemed; the redeemed ones are history and were kept.", countOf(int(joins), "join token")))

	machines, err := st.MarkMachinesUnverified(ctx)
	if err != nil {
		return err
	}
	report.Invalidated = append(report.Invalidated, fmt.Sprintf("Marked %s as unverified: this copy proves it still owns a rented machine before it may delete one.", countOf(int(machines), "machine")))

	if opts.RevokeAPITokens {
		n, err := st.RevokeAllAPITokens(ctx)
		if err != nil {
			return err
		}
		report.Invalidated = append(report.Invalidated, fmt.Sprintf("Revoked %s. Anything automated that held one needs a new one.", countOf(int(n), "API token")))
	} else {
		report.Invalidated = append(report.Invalidated, "Left the API tokens working. If this backup may have been read by anyone else, revoke them.")
	}
	if opts.ResetAgentTokens {
		n, err := st.ResetAgentTokens(ctx)
		if err != nil {
			return err
		}
		report.Invalidated = append(report.Invalidated, fmt.Sprintf("Forgot the agent credential on %s; each will exit with the command to join again.", countOf(int(n), "host")))
	}

	// The audit row is written to the restored database, which is where
	// anyone asking "why is this fleet fenced?" will look.
	return st.AppendAudit(ctx, &store.AuditEvent{
		ActorKind: "system", ActorName: "zoomies restore",
		Action: "instance.restore", TargetKind: "instance",
		After: reason,
	})
}

// hasOrphanedLogs reports whether a write-ahead log or shared-memory file is
// sitting beside a database that is not there.
func hasOrphanedLogs(live string) bool {
	for _, ext := range []string{"-wal", "-shm"} {
		if _, err := os.Stat(live + ext); err == nil {
			return true
		}
	}
	return false
}

// setAsideOrphanedLogs moves that pair out of the way, under the same name the
// database itself would have been kept under. Renamed and never removed: the
// log may hold committed transactions that exist nowhere else.
func setAsideOrphanedLogs(live, stamp string) ([]string, error) {
	kept := live + ".before-restore-" + stamp
	var moved []string
	for _, ext := range []string{"-wal", "-shm"} {
		if err := os.Rename(live+ext, kept+ext); err != nil {
			if errors.Is(err, os.ErrNotExist) {
				continue
			}
			return nil, fmt.Errorf("moving %s aside: %w", live+ext, err)
		}
		moved = append(moved, kept+ext)
	}
	return moved, nil
}

// setAsideLiveDatabase moves the database that is already there out of the way
// and returns where it went.
//
// It is a raw file move of all three files rather than a store backup, and it
// has to be: the live database may be the newer one -- an operator restoring
// an old copy after a bad upgrade -- and the store refuses to open a database
// whose ledger it does not know. A pre-restore copy that only worked when it
// was not needed would be worse than none.
func setAsideLiveDatabase(live, stamp string) (string, error) {
	kept := live + ".before-restore-" + stamp
	if err := os.Rename(live, kept); err != nil {
		return "", fmt.Errorf("moving %s aside: %w", live, err)
	}
	// The write-ahead log and shared-memory file are part of that database.
	// Leaving them beside the restored copy would be worse than losing them:
	// SQLite would replay another database's log into this one.
	for _, ext := range []string{"-wal", "-shm"} {
		if err := os.Rename(live+ext, kept+ext); err != nil && !errors.Is(err, os.ErrNotExist) {
			return "", fmt.Errorf("moving %s aside: %w", live+ext, err)
		}
	}
	return kept, nil
}

// sameFile reports whether two paths are the same file on disk. A path that is
// not there is not the same file as anything.
func sameFile(a, b string) (bool, error) {
	fa, err := os.Stat(a)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("checking %s: %w", a, err)
	}
	fb, err := os.Stat(b)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("checking %s: %w", b, err)
	}
	return os.SameFile(fa, fb), nil
}

// copyFile writes src to dest at owner-only permissions, refusing to leave a
// half-written database behind.
func copyFile(src, dest string) error {
	if err := os.MkdirAll(filepath.Dir(dest), 0o750); err != nil {
		return fmt.Errorf("creating %s: %w", filepath.Dir(dest), err)
	}
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.OpenFile(dest, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return fmt.Errorf("writing %s: %w", dest, err)
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		_ = os.Remove(dest)
		return fmt.Errorf("writing %s: %w", dest, err)
	}
	if err := out.Close(); err != nil {
		_ = os.Remove(dest)
		return fmt.Errorf("writing %s: %w", dest, err)
	}
	return nil
}

// countOf renders "1 backup" and "3 backups".
func countOf(n int, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	return fmt.Sprintf("%d %ss", n, noun)
}

// ---------------------------------------------------------------------------
// A staged restore
// ---------------------------------------------------------------------------

// A controller cannot restore under itself: the database is open, every loop
// holds the store, and a file swapped under a process that has it open is a
// process reading a file nobody else can see. So a restore asked for while the
// controller is running is staged -- checked, then written down beside the
// database -- and applied by the next controller to start, before it opens
// anything. The settings page asks for the restart; a service manager brings
// the process back; the restore happens in the gap.

// The two files beside the database that carry a staged restore and what
// became of the last one.
const (
	stagedName  = "restore-staged.json"
	outcomeName = "restore-outcome.json"
)

// Staged is a restore that has been checked and is waiting for a restart.
type Staged struct {
	// BackupID and Dir name the backup; the id is for people and the
	// directory is what the restore opens.
	BackupID string `json:"backup_id"`
	Dir      string `json:"dir"`
	// TakenAt is when the backup was taken, for the page that shows what is
	// about to be put back.
	TakenAt time.Time `json:"taken_at,omitempty"`
	// RequestedAt and RequestedBy say who asked, and when.
	RequestedAt time.Time `json:"requested_at"`
	RequestedBy string    `json:"requested_by,omitempty"`
	// The options the operator chose.
	RevokeAPITokens  bool `json:"revoke_api_tokens"`
	ResetAgentTokens bool `json:"reset_agent_tokens"`
}

// Outcome is what the last staged restore did, kept so that the settings page
// can say so after the restart rather than leaving the operator to infer it
// from the fence.
type Outcome struct {
	BackupID    string    `json:"backup_id"`
	AttemptedAt time.Time `json:"attempted_at"`
	OK          bool      `json:"ok"`
	// Error is why it did not happen, and the sentence the page shows. When
	// the failure came after the copy, it says which database is in place and
	// whether it is fenced.
	Error  string         `json:"error,omitempty"`
	Report *RestoreReport `json:"report,omitempty"`
}

func stagedPath(dbPath string) string  { return filepath.Join(filepath.Dir(dbPath), stagedName) }
func outcomePath(dbPath string) string { return filepath.Join(filepath.Dir(dbPath), outcomeName) }

// Stage checks a backup as a restore would and, when every check passes,
// records it as the restore to apply at the next start.
//
// The checks are run now rather than at the restart, because now is when the
// operator is looking: a refusal at startup lands in a log they may not be
// reading, and the fleet then starts on the old database with nothing on the
// page to say the restore did not happen.
func Stage(ctx context.Context, cfg *config.Config, entry *Entry, s Staged) (*Staged, error) {
	m, _, err := Check(ctx, cfg, entry.Dir)
	if err != nil {
		return nil, err
	}
	s.BackupID = entry.ID
	s.Dir = entry.Dir
	s.TakenAt = entry.TakenAt
	if m != nil && !m.TakenAt.IsZero() {
		s.TakenAt = m.TakenAt
	}
	if s.RequestedAt.IsZero() {
		s.RequestedAt = time.Now().UTC()
	}
	raw, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(filepath.Dir(cfg.Database.Path), 0o750); err != nil {
		return nil, err
	}
	if err := os.WriteFile(stagedPath(cfg.Database.Path), append(raw, '\n'), 0o600); err != nil {
		return nil, fmt.Errorf("backup: recording the staged restore: %w", err)
	}
	return &s, nil
}

// LoadStaged returns the staged restore, or nil when none is waiting.
func LoadStaged(dbPath string) (*Staged, error) {
	raw, err := os.ReadFile(stagedPath(dbPath))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("backup: reading the staged restore: %w", err)
	}
	var s Staged
	if err := json.Unmarshal(raw, &s); err != nil {
		return nil, fmt.Errorf("backup: %s is not a staged restore: %w", stagedPath(dbPath), err)
	}
	return &s, nil
}

// CancelStaged forgets a staged restore. Cancelling when none is staged is
// not an error: the operator asked for there to be none, and there is none.
func CancelStaged(dbPath string) error {
	err := os.Remove(stagedPath(dbPath))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("backup: cancelling the staged restore: %w", err)
	}
	return nil
}

// LastOutcome returns what became of the last staged restore, or nil when
// there has never been one.
func LastOutcome(dbPath string) (*Outcome, error) {
	raw, err := os.ReadFile(outcomePath(dbPath))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("backup: reading the last restore's outcome: %w", err)
	}
	var o Outcome
	if err := json.Unmarshal(raw, &o); err != nil {
		return nil, fmt.Errorf("backup: %s is not a restore outcome: %w", outcomePath(dbPath), err)
	}
	return &o, nil
}

// ClearOutcome forgets the last outcome, which is how the page dismisses it.
func ClearOutcome(dbPath string) error {
	err := os.Remove(outcomePath(dbPath))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("backup: clearing the last restore's outcome: %w", err)
	}
	return nil
}

// ApplyStaged performs the staged restore, if there is one, and records what
// happened. It returns the outcome, or nil when nothing was staged.
//
// The caller holds the database lock and has not opened the store: this runs
// in the gap between one controller stopping and the next opening the file.
//
// The staged file is removed whatever happens. A restore that failed is not
// retried at every start -- the failure is recorded for the page to show. A
// restore that was refused before anything moved leaves the controller on the
// database it had; one that failed after the copy has already replaced it, and
// the recorded error says so and whether the fence is up. Either way the
// operator can still reach the page through what starts.
func ApplyStaged(ctx context.Context, cfg *config.Config, now func() time.Time) (*Outcome, error) {
	if now == nil {
		now = time.Now
	}
	s, err := LoadStaged(cfg.Database.Path)
	if err != nil {
		return nil, err
	}
	if s == nil {
		return nil, nil
	}
	_ = CancelStaged(cfg.Database.Path)

	out := &Outcome{BackupID: s.BackupID, AttemptedAt: now().UTC()}
	report, err := Restore(ctx, cfg, s.Dir, RestoreOptions{
		Replace:          true,
		RevokeAPITokens:  s.RevokeAPITokens,
		ResetAgentTokens: s.ResetAgentTokens,
		Now:              now,
	})
	if err != nil {
		out.Error = err.Error()
	} else {
		out.OK = true
		out.Report = report
	}
	raw, merr := json.MarshalIndent(out, "", "  ")
	if merr == nil {
		if werr := os.WriteFile(outcomePath(cfg.Database.Path), append(raw, '\n'), 0o600); werr != nil {
			return out, fmt.Errorf("backup: recording the restore's outcome: %w", werr)
		}
	}
	return out, nil
}

package backup

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"time"
)

// An S3 client, in four verbs.
//
// There is no SDK behind this for the reason there is no Docker SDK behind
// internal/backend: putting an object, getting it, listing a prefix and
// deleting a key is four signed requests, and the signature is forty lines of
// HMAC. The dependency that implements the other two hundred calls brings a
// transitive tree, a release cadence and a vulnerability surface with it, all
// so that a controller can write one file a night.
//
// It speaks to anything that implements the S3 API -- AWS, MinIO, Ceph,
// Backblaze B2, Cloudflare R2, Garage -- because signature version 4 and
// ListObjectsV2 are what they all agree on.

// s3Client is one bucket at one endpoint, with the credentials that open it.
type s3Client struct {
	endpoint  *url.URL
	bucket    string
	region    string
	accessKey string
	secretKey string
	// pathStyle puts the bucket in the path rather than the hostname. Every
	// self-hosted implementation needs it; AWS's own endpoints do not.
	pathStyle bool
	http      *http.Client
	// now is the clock the signature is dated with, injected so a test can
	// pin one.
	now func() time.Time
}

// defaultS3Region is what a request is signed for when the operator named no
// region. It is not a guess about where the data is: an implementation with no
// regions of its own ignores it, and AWS accepts it as the signing region for
// a bucket it will redirect us to if it is wrong.
const defaultS3Region = "us-east-1"

// s3Timeouts bound the parts of a request that are not the transfer. The
// transfer itself is bounded by the caller's context and nothing else: a
// backup over a slow link takes as long as it takes, and a client timeout that
// killed it at five minutes would fail every night at the same size.
var s3Transport = &http.Transport{
	Proxy: http.ProxyFromEnvironment,
	DialContext: (&net.Dialer{
		Timeout:   15 * time.Second,
		KeepAlive: 30 * time.Second,
	}).DialContext,
	TLSHandshakeTimeout:   15 * time.Second,
	ResponseHeaderTimeout: 60 * time.Second,
	MaxIdleConnsPerHost:   2,
}

// newS3Client builds a client for one remote, or says what is missing.
func newS3Client(endpoint, region, bucket, accessKey, secretKey string, pathStyle *bool, httpClient *http.Client) (*s3Client, error) {
	u, err := url.Parse(strings.TrimSpace(endpoint))
	if err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") {
		return nil, fmt.Errorf("backup: %q is not an S3 endpoint URL; write one like https://s3.eu-west-2.amazonaws.com or http://minio:9000", endpoint)
	}
	if strings.TrimSpace(bucket) == "" {
		return nil, errors.New("backup: the remote names no bucket")
	}
	if strings.TrimSpace(accessKey) == "" || strings.TrimSpace(secretKey) == "" {
		return nil, errors.New("backup: the remote has no access key and secret key, so every request to it would be refused")
	}
	if region = strings.TrimSpace(region); region == "" {
		region = defaultS3Region
	}
	if httpClient == nil {
		httpClient = &http.Client{Transport: s3Transport}
	}
	style := !isAWSEndpoint(u.Hostname())
	if pathStyle != nil {
		style = *pathStyle
	}
	return &s3Client{
		endpoint: u, bucket: strings.TrimSpace(bucket), region: region,
		accessKey: strings.TrimSpace(accessKey), secretKey: strings.TrimSpace(secretKey),
		pathStyle: style, http: httpClient, now: time.Now,
	}, nil
}

// isAWSEndpoint says whether the host is one of AWS's own, which is the only
// case where virtual-hosted style is the safe default: a bucket name in the
// hostname needs DNS to resolve it, and nothing self-hosted arranges that.
func isAWSEndpoint(host string) bool {
	host = strings.ToLower(host)
	return host == "amazonaws.com" || strings.HasSuffix(host, ".amazonaws.com")
}

// url builds the request URL for a key, in whichever style this endpoint uses.
func (c *s3Client) url(key string) *url.URL {
	u := *c.endpoint
	if c.pathStyle {
		u.Path = "/" + c.bucket
		if key != "" {
			u.Path += "/" + key
		}
		return &u
	}
	u.Host = c.bucket + "." + u.Host
	u.Path = "/" + key
	return &u
}

// s3Object is one key in the bucket, as a listing reports it.
type s3Object struct {
	Key          string
	Size         int64
	LastModified time.Time
	ETag         string
}

// listResult is ListObjectsV2's answer. Only the fields that are read are
// named: an S3 implementation may send more, and encoding/xml ignores what it
// does not know about.
type listResult struct {
	XMLName               xml.Name `xml:"ListBucketResult"`
	IsTruncated           bool     `xml:"IsTruncated"`
	NextContinuationToken string   `xml:"NextContinuationToken"`
	Contents              []struct {
		Key          string    `xml:"Key"`
		Size         int64     `xml:"Size"`
		LastModified time.Time `xml:"LastModified"`
		ETag         string    `xml:"ETag"`
	} `xml:"Contents"`
}

// list returns every key under prefix, following the continuation tokens so a
// bucket with more than a page of backups in it is fully seen.
func (c *s3Client) list(ctx context.Context, prefix string, limit int) ([]s3Object, error) {
	var out []s3Object
	token := ""
	for {
		q := url.Values{}
		q.Set("list-type", "2")
		if prefix != "" {
			q.Set("prefix", prefix)
		}
		if limit > 0 {
			q.Set("max-keys", strconv.Itoa(limit))
		}
		if token != "" {
			q.Set("continuation-token", token)
		}
		u := c.url("")
		u.RawQuery = q.Encode()

		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
		if err != nil {
			return nil, err
		}
		resp, err := c.do(req, emptyPayloadSHA256, 0)
		if err != nil {
			return nil, err
		}
		body, err := io.ReadAll(io.LimitReader(resp.Body, 8<<20))
		resp.Body.Close()
		if err != nil {
			return nil, fmt.Errorf("backup: reading the listing of %s: %w", c.bucket, err)
		}
		var parsed listResult
		if err := xml.Unmarshal(body, &parsed); err != nil {
			return nil, fmt.Errorf("backup: %s answered a listing this is not: %w", c.endpoint.Host, err)
		}
		for _, item := range parsed.Contents {
			out = append(out, s3Object{
				Key: item.Key, Size: item.Size, LastModified: item.LastModified,
				ETag: strings.Trim(item.ETag, `"`),
			})
		}
		if limit > 0 && len(out) >= limit {
			return out[:limit], nil
		}
		if !parsed.IsTruncated || parsed.NextContinuationToken == "" {
			return out, nil
		}
		token = parsed.NextContinuationToken
	}
}

// put writes one object. The body has to be a reader whose length is known and
// whose contents have already been hashed, because a single signed PUT names
// both: it is what lets the service refuse a transfer that arrived altered
// rather than storing it and telling nobody.
func (c *s3Client) put(ctx context.Context, key string, body io.Reader, size int64, payloadSHA256 string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, c.url(key).String(), body)
	if err != nil {
		return err
	}
	req.ContentLength = size
	req.Header.Set("Content-Type", "application/octet-stream")
	resp, err := c.do(req, payloadSHA256, size)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))
	return nil
}

// get opens one object for reading. The caller closes it.
func (c *s3Client) get(ctx context.Context, key string) (io.ReadCloser, int64, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.url(key).String(), nil)
	if err != nil {
		return nil, 0, err
	}
	resp, err := c.do(req, emptyPayloadSHA256, 0)
	if err != nil {
		return nil, 0, err
	}
	return resp.Body, resp.ContentLength, nil
}

// remove deletes one object. S3 answers 204 for a key that was never there,
// and so does this: a delete is a statement about the end state.
func (c *s3Client) remove(ctx context.Context, key string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodDelete, c.url(key).String(), nil)
	if err != nil {
		return err
	}
	resp, err := c.do(req, emptyPayloadSHA256, 0)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))
	return nil
}

// do signs a request, sends it, and turns a refusal into a sentence.
func (c *s3Client) do(req *http.Request, payloadSHA256 string, size int64) (*http.Response, error) {
	if err := c.sign(req, payloadSHA256, size); err != nil {
		return nil, err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return nil, fmt.Errorf("backup: %s %s: %w", req.Method, redactedURL(req.URL), err)
	}
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return resp, nil
	}
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	resp.Body.Close()
	return nil, s3Error(req, resp.StatusCode, body)
}

// s3ErrorBody is the document every S3 implementation answers a refusal with.
type s3ErrorBody struct {
	Code    string `xml:"Code"`
	Message string `xml:"Message"`
}

// s3Error turns a status code and an XML body into something an operator can
// act on. The codes named here are the ones that have a fix somebody can
// perform; the rest are reported as the service worded them, because an
// implementation Zoomies has never seen still knows what went wrong.
func s3Error(req *http.Request, status int, body []byte) error {
	var parsed s3ErrorBody
	_ = xml.Unmarshal(body, &parsed)
	where := redactedURL(req.URL)

	switch parsed.Code {
	case "NoSuchBucket":
		return fmt.Errorf("backup: the bucket does not exist at %s. Zoomies never creates one: a backup destination that appeared by itself is one nobody has set the retention or access policy of", where)
	case "AccessDenied":
		return fmt.Errorf("backup: %s refused the request as %s. The credentials work but the policy does not allow it -- a backup remote needs s3:PutObject, s3:GetObject, s3:DeleteObject and s3:ListBucket on the bucket and its prefix", where, req.Method)
	case "InvalidAccessKeyId":
		return fmt.Errorf("backup: %s does not know this access key id", where)
	case "SignatureDoesNotMatch":
		return fmt.Errorf("backup: %s rejected the signature. The secret access key is wrong, or the region the requests are signed for is not the bucket's", where)
	case "RequestTimeTooSkewed":
		return fmt.Errorf("backup: %s refused the request because this host's clock is too far from its own. Fix the clock; nothing signed here will be accepted until it agrees", where)
	case "NoSuchKey":
		return fmt.Errorf("backup: %s holds no such object", where)
	case "PermanentRedirect", "AuthorizationHeaderMalformed":
		return fmt.Errorf("backup: %s says this bucket belongs to another region (%s). Set the remote's region to the bucket's own", where, strings.TrimSpace(parsed.Message))
	}
	switch {
	case status == http.StatusNotFound:
		return fmt.Errorf("backup: %s answered 404; the bucket or the object is not there", where)
	case status == http.StatusForbidden:
		return fmt.Errorf("backup: %s answered 403; the credentials were refused or the policy does not allow %s", where, req.Method)
	case parsed.Message != "":
		return fmt.Errorf("backup: %s answered %d: %s (%s)", where, status, strings.TrimSpace(parsed.Message), parsed.Code)
	default:
		return fmt.Errorf("backup: %s answered %d", where, status)
	}
}

// redactedURL is a URL fit for a log line and an error message: the bucket and
// the key, without the query, because a listing's continuation token is long
// and a presigned parameter would be a credential.
func redactedURL(u *url.URL) string {
	return u.Scheme + "://" + u.Host + u.EscapedPath()
}

// emptyPayloadSHA256 is the digest of no bytes at all, which every request
// without a body is signed with.
const emptyPayloadSHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"

// sign adds the signature version 4 headers.
//
// The three headers it sets are all part of what is signed: the host, so a
// signature for one endpoint cannot be replayed against another; the date, so
// it expires; and the payload digest, so a body altered in flight fails to
// verify rather than being stored.
func (c *s3Client) sign(req *http.Request, payloadSHA256 string, size int64) error {
	now := c.now().UTC()
	amzDate := now.Format("20060102T150405Z")
	dateStamp := now.Format("20060102")

	req.Header.Set("Host", req.URL.Host)
	req.Header.Set("X-Amz-Date", amzDate)
	req.Header.Set("X-Amz-Content-Sha256", payloadSHA256)
	if size > 0 {
		req.Header.Set("Content-Length", strconv.FormatInt(size, 10))
	}

	signed, canonicalHeaders := canonicalHeaders(req)
	canonicalRequest := strings.Join([]string{
		req.Method,
		canonicalPath(req.URL),
		canonicalQuery(req.URL),
		canonicalHeaders,
		signed,
		payloadSHA256,
	}, "\n")

	scope := strings.Join([]string{dateStamp, c.region, "s3", "aws4_request"}, "/")
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		scope,
		hex.EncodeToString(sha256Of(canonicalRequest)),
	}, "\n")

	key := hmacSHA256([]byte("AWS4"+c.secretKey), dateStamp)
	key = hmacSHA256(key, c.region)
	key = hmacSHA256(key, "s3")
	key = hmacSHA256(key, "aws4_request")
	signature := hex.EncodeToString(hmacSHA256(key, stringToSign))

	req.Header.Set("Authorization", fmt.Sprintf(
		"AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		c.accessKey, scope, signed, signature))
	return nil
}

// canonicalHeaders is the signed header block and the list of names in it.
// Only the three headers that are always present are signed: every extra
// header signed is one a proxy can break by rewriting it.
func canonicalHeaders(req *http.Request) (signed, block string) {
	names := []string{"host", "x-amz-content-sha256", "x-amz-date"}
	sort.Strings(names)
	var b strings.Builder
	for _, name := range names {
		value := req.Header.Get(name)
		if name == "host" {
			value = req.URL.Host
		}
		b.WriteString(name)
		b.WriteString(":")
		b.WriteString(strings.TrimSpace(value))
		b.WriteString("\n")
	}
	return strings.Join(names, ";"), b.String()
}

// canonicalPath encodes the path the way the signature expects: every segment
// percent-encoded, the separators left alone, and an empty path spelled "/".
func canonicalPath(u *url.URL) string {
	path := u.Path
	if path == "" {
		return "/"
	}
	parts := strings.Split(path, "/")
	for i, p := range parts {
		parts[i] = uriEncode(p, false)
	}
	return strings.Join(parts, "/")
}

// canonicalQuery is the query sorted by name and encoded the same way. Go's
// own Encode is close but not identical -- it escapes a space as "+", which
// the signature counts as a different byte.
func canonicalQuery(u *url.URL) string {
	values := u.Query()
	names := make([]string, 0, len(values))
	for name := range values {
		names = append(names, name)
	}
	sort.Strings(names)
	var pairs []string
	for _, name := range names {
		vs := values[name]
		sort.Strings(vs)
		for _, v := range vs {
			pairs = append(pairs, uriEncode(name, true)+"="+uriEncode(v, true))
		}
	}
	return strings.Join(pairs, "&")
}

// uriEncode is the encoding the signature is defined in terms of: everything
// but the unreserved characters is percent-encoded in upper-case hex, and a
// slash is encoded only outside a path.
func uriEncode(s string, encodeSlash bool) string {
	var b strings.Builder
	for _, r := range []byte(s) {
		switch {
		case (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9'),
			r == '-', r == '_', r == '.', r == '~':
			b.WriteByte(r)
		case r == '/' && !encodeSlash:
			b.WriteByte(r)
		default:
			fmt.Fprintf(&b, "%%%02X", r)
		}
	}
	return b.String()
}

func hmacSHA256(key []byte, data string) []byte {
	h := hmac.New(sha256.New, key)
	h.Write([]byte(data))
	return h.Sum(nil)
}

func sha256Of(s string) []byte {
	sum := sha256.Sum256([]byte(s))
	return sum[:]
}

package config

import (
	"strings"
	"testing"
	"time"
)

// A compose deployment describes the bucket in the file and keeps the secret
// in the environment, which is the whole reason the environment half exists.
// Matching by name rather than by position is what makes that work when the
// file lists more than one destination.
func TestTheEnvironmentFillsInTheRemoteTheFileAlreadyDescribes(t *testing.T) {
	c := Default()
	c.Backup.Remotes = []BackupRemote{
		{Name: "minio", Endpoint: "http://minio:9000", Bucket: "first"},
		{Name: "offsite", Endpoint: "https://s3.eu-west-2.amazonaws.com", Bucket: "second"},
	}
	t.Setenv("ZOOMIES_BACKUP_REMOTE_NAME", "offsite")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_SECRET_ACCESS_KEY", "the secret")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_PASSPHRASE", "a long passphrase")

	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	c.normalize()

	if got := c.Backup.Remotes[0].SecretAccessKey; got != "" {
		t.Errorf("the first remote gained %q; the variables named the second by name", got)
	}
	second := c.Backup.Remotes[1]
	if second.SecretAccessKey != "the secret" || !second.Encrypted() {
		t.Errorf("the named remote reads %+v", second)
	}
	if second.Bucket != "second" {
		t.Errorf("bucket = %q; the environment set no bucket and must not have cleared one", second.Bucket)
	}
}

// And a deployment with no file at all describes the whole destination in the
// environment, which is what a container without a mounted configuration has.
func TestARemoteCanBeDescribedEntirelyInTheEnvironment(t *testing.T) {
	c := Default()
	t.Setenv("ZOOMIES_BACKUP_REMOTE_ENDPOINT", "http://minio:9000")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_BUCKET", "backups")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_ACCESS_KEY_ID", "zoomies")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_SECRET_ACCESS_KEY", "secret")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_KEEP", "30")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_2_ENDPOINT", "https://s3.eu-west-2.amazonaws.com")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_2_BUCKET", "acme")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_2_ACCESS_KEY_ID", "AKIA")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_2_SECRET_ACCESS_KEY", "secret")

	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	c.normalize()

	if len(c.Backup.Remotes) != 2 {
		t.Fatalf("the environment described %d remotes, wanted 2", len(c.Backup.Remotes))
	}
	// Named for them, because the name is what the page, the log and the API
	// address a destination by and nobody supplied one.
	if c.Backup.Remotes[0].Name != "offsite" || c.Backup.Remotes[1].Name != "offsite-2" {
		t.Errorf("unnamed remotes are called %q and %q", c.Backup.Remotes[0].Name, c.Backup.Remotes[1].Name)
	}
	if c.Backup.Remotes[0].Keep != 30 {
		t.Errorf("keep = %d, wanted the 30 the environment asked for", c.Backup.Remotes[0].Keep)
	}
	if enabled := c.EnabledBackupRemotes(); len(enabled) != 2 {
		t.Errorf("%d of the two remotes would be used", len(enabled))
	}
	if c.Source("backup.remotes") != SourceEnvironment {
		t.Error("a remote set from the environment does not say where it came from")
	}
}

// A number the environment cannot parse is refused by name rather than
// silently ignored: a remote with no retention is a bucket that grows forever,
// and a typo that reads as "keep everything" is one nobody notices.
func TestABadRemoteEnvironmentValueIsRefusedByName(t *testing.T) {
	c := Default()
	t.Setenv("ZOOMIES_BACKUP_REMOTE_ENDPOINT", "http://minio:9000")
	t.Setenv("ZOOMIES_BACKUP_REMOTE_KEEP", "lots")

	err := c.applyEnv()
	if err == nil {
		t.Fatal("a keep of \"lots\" was accepted")
	}
	if !strings.Contains(err.Error(), "ZOOMIES_BACKUP_REMOTE_KEEP") {
		t.Errorf("the error reads %q, which does not name the variable the operator wrote", err)
	}
}

// The two findings that are not errors are the point of the validator here: a
// bucket that can be read by whoever owns it, and credentials crossing a
// network in the clear, are both things a fleet may choose and neither is
// allowed to be silent.
func TestAnOffsiteBackupSaysWhatItIsGivingAway(t *testing.T) {
	base := func() *Config {
		c := Default()
		c.Backup.Interval = 24 * time.Hour
		c.Backup.Remotes = []BackupRemote{{
			Name: "offsite", Endpoint: "https://s3.eu-west-2.amazonaws.com", Bucket: "acme",
			AccessKeyID: "AKIA", SecretAccessKey: "secret",
		}}
		c.normalize()
		return c
	}

	c := base()
	if !hasCode(c.Validate(), "backup.remote_plaintext") {
		t.Error("a remote with no passphrase is sent the whole fleet in the clear and nothing says so")
	}
	if hasCode(c.Validate(), NoRemoteFinding) {
		t.Error("a fleet with a remote is told it has none")
	}

	// And the fleet that has none is told, under the code the settings API
	// drops once a destination stored in the database has answered it. The
	// constant and the finding are spelled separately, so this is what holds
	// them together.
	bare := Default()
	bare.Backup.Interval = 24 * time.Hour
	if !hasCode(bare.Validate(), NoRemoteFinding) {
		t.Error("a fleet taking backups that never leave the host is not told")
	}

	c = base()
	c.Backup.Remotes[0].Passphrase = "a long random passphrase"
	if f := c.Validate(); hasCode(f, "backup.remote_plaintext") || hasCode(f, "backup.remote_passphrase_short") {
		t.Error("a remote with a real passphrase is still being warned about")
	}

	c = base()
	c.Backup.Remotes[0].Passphrase = "short"
	if !hasCode(c.Validate(), "backup.remote_passphrase_short") {
		t.Error("a five-character passphrase passed without comment")
	}

	c = base()
	c.Backup.Remotes[0].Endpoint = "http://s3.example.com"
	if !hasCode(c.Validate(), "backup.remote_insecure") {
		t.Error("a remote reached over plain HTTP passed without comment")
	}
	// Loopback is the developer's MinIO and is not a warning: the credentials
	// never leave the host.
	c = base()
	c.Backup.Remotes[0].Endpoint = "http://127.0.0.1:9000"
	if hasCode(c.Validate(), "backup.remote_insecure") {
		t.Error("a remote on loopback was warned about as if it crossed a network")
	}
}

// A half-written remote is the dangerous case: it looks configured, it copies
// nothing, and the fleet believes it has an offsite backup it has never had.
func TestAHalfWrittenRemoteIsAnErrorRatherThanSilence(t *testing.T) {
	for _, tc := range []struct {
		name   string
		remote BackupRemote
		code   string
	}{
		{"no bucket", BackupRemote{Name: "offsite", Endpoint: "https://s3.example.com"}, "backup.remote_incomplete"},
		{"no endpoint", BackupRemote{Name: "offsite", Bucket: "acme"}, "backup.remote_incomplete"},
		{
			"no credentials",
			BackupRemote{Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "acme"},
			"backup.remote_credentials",
		},
		{
			"an endpoint that is not a URL",
			BackupRemote{Name: "offsite", Endpoint: "s3.example.com", Bucket: "acme", AccessKeyID: "a", SecretAccessKey: "b"},
			"backup.remote_endpoint",
		},
		{
			"a name that is not a name",
			BackupRemote{Name: "Off Site!", Endpoint: "https://s3.example.com", Bucket: "acme", AccessKeyID: "a", SecretAccessKey: "b"},
			"backup.remote_name",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := Default()
			c.Backup.Remotes = []BackupRemote{tc.remote}
			// Deliberately not normalised for the name case: normalize
			// lower-cases and trims, and the validator is what refuses what is
			// left.
			if !hasCode(c.Validate(), tc.code) {
				t.Errorf("%+v raised no %s", tc.remote, tc.code)
			}
		})
	}

	// Two destinations with one name: one of them would be unaddressable.
	c := Default()
	c.Backup.Remotes = []BackupRemote{
		{Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "a", AccessKeyID: "a", SecretAccessKey: "b"},
		{Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "b", AccessKeyID: "a", SecretAccessKey: "b"},
	}
	if !hasCode(c.Validate(), "backup.remote_duplicate") {
		t.Error("two remotes sharing a name passed without comment")
	}

	// A remote switched off is not a remote to complain about: that is what
	// disabled is for.
	c = Default()
	c.Backup.Remotes = []BackupRemote{{Name: "offsite", Disabled: true}}
	c.normalize()
	for _, f := range c.Validate() {
		if strings.HasPrefix(f.Code, "backup.remote_") {
			t.Errorf("a disabled remote raised %s", f.Code)
		}
	}
}

// Nothing in a remote reaches a manifest, a settings export or a diagnostics
// bundle, and that is a property of the registry rather than of a list of
// fields somebody has to remember to blank.
func TestARemotesCredentialsAreNotInTheRedactedConfiguration(t *testing.T) {
	c := Default()
	c.Backup.Remotes = []BackupRemote{{
		Name: "offsite", Endpoint: "https://s3.example.com", Bucket: "acme",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "the secret", Passphrase: "the passphrase",
	}}
	blob := Redacted(c)
	if backupSection, ok := blob["backup"].(map[string]any); ok {
		if _, leaked := backupSection["remotes"]; leaked {
			t.Fatal("the backup remotes are in the redacted configuration, which is what a manifest carries")
		}
	}
}

package config

import "testing"

// Half a bootstrap is a provisioner waiting on an instance that will never
// become usable, so it stops startup with a message saying what is missing.
func TestHalfABootstrapStopsStartup(t *testing.T) {
	cases := []struct {
		name string
		b    Bootstrap
		want bool
	}{
		{"nothing set", Bootstrap{}, false},
		{"a password", Bootstrap{Admin: "ops", PasswordFile: "/run/secrets/pw"}, false},
		{"a token", Bootstrap{Admin: "ops", TokenFile: "/run/secrets/tok"}, false},
		{"no username", Bootstrap{PasswordFile: "/run/secrets/pw"}, true},
		{"no credential", Bootstrap{Admin: "ops"}, true},
		{"both credentials", Bootstrap{Admin: "ops", PasswordFile: "/a", TokenFile: "/b"}, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := Default()
			c.Bootstrap = tc.b
			var got bool
			for _, f := range c.Validate().Errors() {
				if f.Code == "bootstrap.incomplete" {
					got = true
				}
			}
			if got != tc.want {
				t.Fatalf("bootstrap.incomplete raised = %v; want %v", got, tc.want)
			}
		})
	}
}

// The variables are read from the environment and nowhere else.
func TestTheBootstrapVariablesAreReadFromTheEnvironment(t *testing.T) {
	t.Setenv("ZOOMIES_BOOTSTRAP_ADMIN", " ops ")
	t.Setenv("ZOOMIES_BOOTSTRAP_TOKEN_FILE", "/run/secrets/tok")
	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if c.Bootstrap.Admin != "ops" || c.Bootstrap.TokenFile != "/run/secrets/tok" || c.Bootstrap.PasswordFile != "" {
		t.Fatalf("read %+v", c.Bootstrap)
	}
}

package config

import "testing"

// Finished runner containers are disposable execution state. The agent still
// waits for the controller to acknowledge their terminal report, so zero means
// removal on the next reconcile pass rather than removal before the result is
// safe. A non-zero default makes disk consumption grow with job throughput.
func TestFinishedRunnerWorkloadsAreNotRetainedByDefault(t *testing.T) {
	if got := Default().Agent.FinishedRetention; got != 0 {
		t.Fatalf("FinishedRetention = %s, want 0 so each completed job releases its container disk", got)
	}
}

func TestDockerBuildCacheBudgetDefaultsAndValidation(t *testing.T) {
	c := Default()
	if c.Agent.DockerBuildCacheMB != 0 {
		t.Fatalf("cache target = %d", c.Agent.DockerBuildCacheMB)
	}
	for _, value := range []int{-1, 1048577} {
		c.Agent.DockerBuildCacheMB = value
		if !hasCode(c.Validate(), "agent.docker_build_cache_mb") {
			t.Fatalf("invalid cache budget %d accepted", value)
		}
	}
	c.Agent.DockerBuildCacheMB = 0
	if hasCode(c.Validate(), "agent.docker_build_cache_mb") {
		t.Fatal("disabled cleanup rejected")
	}
}

package config

import "strings"

// TrustedProxyCloudflare is the whole word an operator writes in
// server.trusted_proxies when Cloudflare is in front. It expands to
// Cloudflare's published edge ranges, so the configuration says what it
// means and nobody has to copy two dozen CIDRs by hand -- or keep them
// current by hand.
const TrustedProxyCloudflare = "cloudflare"

// CloudflareCIDRs are Cloudflare's published edge ranges, as listed at
// https://www.cloudflare.com/ips/ on 2026-09-05. They are embedded rather
// than fetched at startup: a trust boundary must not depend on a third-party
// fetch succeeding, and a stale list fails safe -- a connection from a range
// this binary does not know is treated as an ordinary client, and its
// forwarded headers are ignored.
var CloudflareCIDRs = []string{
	"173.245.48.0/20",
	"103.21.244.0/22",
	"103.22.200.0/22",
	"103.31.4.0/22",
	"141.101.64.0/18",
	"108.162.192.0/18",
	"190.93.240.0/20",
	"188.114.96.0/20",
	"197.234.240.0/22",
	"198.41.128.0/17",
	"162.158.0.0/15",
	"104.16.0.0/13",
	"104.24.0.0/14",
	"172.64.0.0/13",
	"131.0.72.0/22",
	"2400:cb00::/32",
	"2606:4700::/32",
	"2803:f800::/32",
	"2405:b500::/32",
	"2405:8100::/32",
	"2a06:98c0::/29",
	"2c0f:f248::/32",
}

// ExpandTrustedProxies replaces the cloudflare token with Cloudflare's
// published ranges and passes everything else through untouched.
func ExpandTrustedProxies(in []string) []string {
	out := make([]string, 0, len(in))
	for _, raw := range in {
		if strings.TrimSpace(raw) == TrustedProxyCloudflare {
			out = append(out, CloudflareCIDRs...)
			continue
		}
		out = append(out, raw)
	}
	return out
}

// Package config loads and validates zoomies.yaml plus its ZOOMIES_* env
// overrides.
//
// Validation has two outputs. Errors stop the process with a message that says
// what to change. Warnings do not stop anything, but every one of them names a
// setting that weakens the default security posture; they are logged at startup
// and surfaced in the UI's problems drawer, so a dangerous toggle is never
// silently in effect.
package config

import (
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/eyupio/zoomies/internal/machine"
	"github.com/eyupio/zoomies/internal/naming"
)

// Config is the complete on-disk configuration.
type Config struct {
	Server         Server         `yaml:"server"`
	Database       Database       `yaml:"database"`
	Security       Security       `yaml:"security"`
	GitHub         GitHub         `yaml:"github"`
	Agent          Agent          `yaml:"agent"`
	Runners        Runners        `yaml:"runners"`
	Scheduler      Scheduler      `yaml:"scheduler"`
	Log            Log            `yaml:"log"`
	OIDC           OIDC           `yaml:"oidc"`
	Metrics        Metrics        `yaml:"metrics"`
	Status         Status         `yaml:"status"`
	Retention      Retention      `yaml:"retention"`
	Limits         Limits         `yaml:"limits"`
	Images         Images         `yaml:"images"`
	Updates        Updates        `yaml:"updates"`
	CapacityDemand CapacityDemand `yaml:"capacity_demand"`
	Provider       Provider       `yaml:"provider"`
	UI             UI             `yaml:"ui"`
	Backup         Backup         `yaml:"backup"`

	// Bootstrap is the first identity an unattended install asks for. It is
	// read from the environment only -- see Bootstrap.
	Bootstrap Bootstrap `yaml:"-"`

	// path records where this config was read from, for error messages.
	path string `yaml:"-"`
	// keyInFile records that the encryption key was written in that file, as
	// opposed to arriving from the environment after the file was read. The
	// warning about a key in the config file has to look at where the key came
	// from, not at whether one is present.
	keyInFile bool `yaml:"-"`
	// sources records which layer set each key -- see sources.go. It is what
	// the settings page reads to say whether a value came from the file, the
	// database or the environment, and therefore whether changing it here will
	// survive a restart.
	sources map[string]Source `yaml:"-"`
}

// Bootstrap names the first identity a controller creates for itself when
// its database has no accounts, so an instance a compose file or a Terraform
// module brought up is usable with nobody at a browser and nobody reading the
// setup token out of the log -- a compose file has nobody watching.
//
// It is environment only: never a key in zoomies.yaml nor a row in the
// settings table. It is a one-shot instruction rather than a setting -- it
// acts once, on an empty database, and is ignored ever after -- so storing it
// would keep a value that means nothing in a place that implies it does. The
// secrets are named by path rather than carried in the variables, because a
// process's environment is readable by more things than a 0600 file is:
// `docker inspect`, /proc, a crash report.
type Bootstrap struct {
	// Admin is the username of the first account.
	Admin string
	// PasswordFile holds that account's password.
	PasswordFile string
	// TokenFile holds an API token the provisioner generated. The controller
	// registers it as a platform token for the account and prints nothing:
	// the secret is chosen by whoever already holds it, so there is no second
	// copy to scrape out of a log.
	TokenFile string
}

// Requested reports whether any of the bootstrap variables is set.
func (b Bootstrap) Requested() bool {
	return b.Admin != "" || b.PasswordFile != "" || b.TokenFile != ""
}

// Variables names the bootstrap variables that are set, for a message that
// has to tell an operator which ones to remove.
func (b Bootstrap) Variables() []string {
	var out []string
	if b.Admin != "" {
		out = append(out, "ZOOMIES_BOOTSTRAP_ADMIN")
	}
	if b.PasswordFile != "" {
		out = append(out, "ZOOMIES_BOOTSTRAP_PASSWORD_FILE")
	}
	if b.TokenFile != "" {
		out = append(out, "ZOOMIES_BOOTSTRAP_TOKEN_FILE")
	}
	return out
}

// Images controls how the fleet keeps the images its pools run up to date.
type Images struct {
	// RefreshInterval is how often every pool's image is prewarmed again on
	// the hosts that can run it. Prewarming otherwise happens only when a pool
	// is created, edited or prewarmed by hand, so a pool that names a moving
	// tag -- which the default ghcr.io/eyupio/zoomies-runner:latest is -- keeps
	// running whatever its hosts first pulled, however many times the tag has
	// moved since.
	//
	// The work is idempotent and off every job's critical path: it costs a
	// registry round trip per pool per host, and a pull only when the tag has
	// actually moved. Zero switches it off, which is what an air-gapped fleet
	// or one that pins every pool to a digest wants.
	RefreshInterval time.Duration `yaml:"refresh_interval"`
}

// UI holds what the web UI opens with. Nothing here changes what the fleet
// does; it changes what an operator sees first. Every one of these is a
// starting point the page itself lets an operator move away from, and the
// page remembers the move in that browser -- so what is set here is what
// somebody who has never chosen sees, on every screen they open it on.
type UI struct {
	CapacityMap CapacityMap `yaml:"capacity_map"`
	// QueueWarningThreshold is how many jobs have to be queued before the
	// queue tiles on the Overview, Jobs and Pools pages turn to their warning
	// colour. Unlike the capacity map's layouts, there is no per-browser
	// override to fall back to: this is the one answer every operator sees,
	// so a fleet whose queue habitually sits at a dozen jobs can say so rather
	// than living with an amber tile that never turns off.
	QueueWarningThreshold int `yaml:"queue_warning_threshold"`
}

// CapacityMap is how the host capacity map first draws itself on each of the
// two pages that carry it. The two are separate on purpose: the Overview is
// glanced at, where every host on one chart answers "which machine is busy",
// and the Hosts page is where one machine gets looked into, where a chart per
// host answers "what has it been doing" -- and a fleet may want each page to
// open on its own answer.
type CapacityMap struct {
	// OverviewLayout is the layout the Overview's map opens with: overlay,
	// every host on one chart, or split, a chart for each.
	OverviewLayout string `yaml:"overview_layout"`
	// HostsLayout is the same choice for the Hosts page.
	HostsLayout string `yaml:"hosts_layout"`
}

// The capacity map's layouts, as the settings and the UI name them.
const (
	CapacityLayoutOverlay = "overlay"
	CapacityLayoutSplit   = "split"
)

// CapacityLayouts lists the layouts the map can open in, in the order the
// settings page offers them.
var CapacityLayouts = []string{CapacityLayoutOverlay, CapacityLayoutSplit}

// Updates controls whether this controller asks github.com which release of
// Zoomies is current, so that being out of date is something the UI says rather
// than something an operator finds out later.
type Updates struct {
	// CheckInterval is how often that question is asked. Zero switches the
	// check off, and with it the one request Zoomies makes to github.com that
	// is not about your fleet -- which is what an air-gapped deployment, or one
	// pointed at GitHub Enterprise Server with no route to github.com, wants.
	//
	// Nothing is ever downloaded or installed by this: the controller does not
	// update itself, it only says that a newer release exists.
	CheckInterval time.Duration `yaml:"check_interval"`
}

// Backup is the controller's own copies of its database: where they go, how
// often one is taken, how many are kept, and which object stores each one is
// copied to afterwards.
//
// The copies are the same layout `zoomies backup` writes and `zoomies restore`
// reads, so a scheduled copy is restorable by exactly the command that restores
// one taken by hand. A copy beside the database is a backup against a mistake
// and not against the disk, which is what Remotes is for: the same archive the
// Backups tab downloads, put in somebody else's bucket by the fleet rather than
// by a cron line nobody has checked since they wrote it.
type Backup struct {
	// Directory is where backups are kept. Empty is a `backups` directory
	// beside the database, which on a container deployment is the mounted
	// volume -- the one place a copy survives the container being recreated.
	// A relative path is relative to the database's directory, not to
	// wherever the process was started from.
	Directory string `yaml:"directory"`
	// Interval is how often the controller takes a copy of its own accord.
	// Zero switches scheduled copies off; the settings page and the command
	// line still take one on demand.
	Interval time.Duration `yaml:"interval"`
	// Keep is how many of the controller's own copies are kept; the oldest
	// beyond it are deleted after each new one. Zero keeps every one. Copies
	// an operator uploaded are never counted and never deleted by this.
	Keep int `yaml:"keep"`
	// Remotes are the S3-compatible buckets every new backup is copied to.
	// Empty is the old behaviour and still the default: nothing leaves the
	// host unless somebody says where it goes.
	//
	// They live in the file rather than in the database, unlike a provider's
	// credentials, because of the day they are for. A fleet whose database is
	// gone has no stored settings to read, and `zoomies restore --from` has to
	// be able to find the copy and open the bucket with nothing but
	// zoomies.yaml in front of it. Keep the file mode 0600 and prefer
	// ZOOMIES_BACKUP_REMOTE_SECRET_ACCESS_KEY for the secret.
	Remotes []BackupRemote `yaml:"remotes"`
}

// BackupRemote is one S3-compatible destination: a bucket somebody else's disk
// is responsible for, and what it takes to write to it.
//
// Any implementation of the S3 API does -- AWS, MinIO, Ceph, Backblaze B2,
// Cloudflare R2, Garage -- because the client is the same few signed requests
// against all of them. There is no SDK behind it, for the reason there is no
// Docker SDK behind internal/backend: four verbs of one protocol is less code
// than the dependency that implements two hundred.
type BackupRemote struct {
	// Name is what the Backups tab, the log and the problems drawer call this
	// destination. Empty is "offsite" for the first and "offsite-2" for the
	// next, and two remotes may not share one.
	Name string `yaml:"name"`
	// Endpoint is the service's URL: https://s3.eu-west-2.amazonaws.com,
	// https://<account>.r2.cloudflarestorage.com, http://minio:9000. The
	// scheme decides whether the connection is encrypted -- there is no
	// separate "use TLS" switch to disagree with it.
	Endpoint string `yaml:"endpoint"`
	// Region is what the request is signed for. Empty is us-east-1, which is
	// what every S3 implementation that has no regions of its own accepts.
	Region string `yaml:"region"`
	// Bucket is the bucket. Zoomies never creates it: a backup destination
	// that appears because the controller made it is a destination nobody has
	// checked the retention, versioning or access policy of.
	Bucket string `yaml:"bucket"`
	// Prefix is the key prefix inside it, so one bucket can hold several
	// fleets. "zoomies/prod" puts a backup at zoomies/prod/zoomies-....tar.gz.
	Prefix string `yaml:"prefix"`
	// AccessKeyID and SecretAccessKey are the credentials the requests are
	// signed with. The secret is a secret: it belongs in the environment, or
	// in a file only the controller reads.
	AccessKeyID     string `yaml:"access_key_id"`
	SecretAccessKey string `yaml:"secret_access_key"`
	// Passphrase encrypts the archive before it is uploaded, with the same
	// argon2id and AES-256-GCM the Backups tab's encrypted download uses.
	//
	// Empty uploads the plain archive, and the validator says what that costs:
	// a backup is the whole fleet, and in a bucket it is the whole fleet on
	// somebody else's disk. Nothing on the controller can recover a lost
	// passphrase -- the archive opens with it and with nothing else.
	Passphrase string `yaml:"passphrase"`
	// PathStyle puts the bucket in the path (http://minio:9000/bucket/key)
	// rather than in the hostname. Unset chooses: virtual-hosted style for
	// AWS's own endpoints, path style for everything else, which is what
	// MinIO, Ceph and a bare IP address need.
	PathStyle *bool `yaml:"path_style"`
	// Keep is how many copies this remote holds; the oldest beyond it are
	// deleted after each upload. Zero keeps every one, exactly as backup.keep
	// does, and is the default: object storage is cheap and the operator who
	// wants an offsite copy usually wants the long tail of them.
	Keep int `yaml:"keep"`
	// Disabled stops uploads to this remote without removing what it holds or
	// making its configuration something an operator has to reconstruct.
	Disabled bool `yaml:"disabled"`
}

// Enabled reports whether this remote is configured enough to be used.
func (r BackupRemote) Enabled() bool {
	return !r.Disabled && strings.TrimSpace(r.Endpoint) != "" && strings.TrimSpace(r.Bucket) != ""
}

// Encrypted reports whether the archive is sealed before it leaves the host.
func (r BackupRemote) Encrypted() bool { return strings.TrimSpace(r.Passphrase) != "" }

// Where reports the bucket and prefix as one phrase, for a log line or a row
// on the Backups tab.
func (r BackupRemote) Where() string {
	where := r.Bucket
	if p := strings.Trim(strings.TrimSpace(r.Prefix), "/"); p != "" {
		where += "/" + p
	}
	return where
}

// EnabledBackupRemotes is the remotes a copy is actually sent to, named and in
// the order the file lists them.
func (c *Config) EnabledBackupRemotes() []BackupRemote {
	var out []BackupRemote
	for _, r := range c.Backup.Remotes {
		if r.Enabled() {
			out = append(out, r)
		}
	}
	return out
}

// CapacityDemand publishes signed requests for host capacity to an external
// provisioner. An empty DestinationURL disables the integration.
type CapacityDemand struct {
	DestinationURL string        `yaml:"destination_url"`
	SigningSecret  string        `yaml:"signing_secret"`
	Cooldown       time.Duration `yaml:"cooldown"`
	Timeout        time.Duration `yaml:"timeout"`
	Pools          []string      `yaml:"pools"`
}

// Provider bounds what the infrastructure providers may do. The providers
// themselves -- their endpoints, credentials and the machine each one offers --
// are rows in the database, edited from the UI and sealed at rest; a credential
// in a configuration file is a credential in a backup, a diagnostics bundle and
// a screenshot.
//
// What lives here is the part an operator wants to set once and have a restart
// honour: whether machines may be rented at all, the ceilings nothing may
// exceed, and how long each step of a machine's life is given before somebody
// is asked about it.
type Provider struct {
	// Enabled decides whether the machine loop runs at all. Off by default:
	// renting a machine spends money, and nothing in this system should start
	// doing that because a release added the ability to.
	Enabled bool `yaml:"enabled"`
	// Paused is the kill switch in the file, for an operator who wants a
	// restart to come back held. It blocks new machines only -- draining,
	// deleting, recovering and verifying ownership all continue, because a
	// switch that also stopped those would strand running VMs nobody is
	// watching. The same switch exists per provider as a row, which is what the
	// Hosts page presses.
	Paused bool `yaml:"paused"`
	// Interval is how often the machine loop runs. It is separate from the
	// scheduler's because it is a slower thing: a clone takes minutes, and the
	// pass that watches one has nothing to gain from a ten-second tick.
	Interval time.Duration `yaml:"interval"`
	// SweepInterval is how often each provider is asked for everything it
	// believes it is running, which is how an orphaned VM and a resource that
	// vanished underneath us are both found. It is paced rather than per pass
	// because it is one API call per provider and the answer changes slowly.
	SweepInterval time.Duration `yaml:"sweep_interval"`
	// MaxMachines is the fleet-wide ceiling across every provider.
	//
	// Zero rents nothing, exactly as a pool's max_runners of zero runs nothing:
	// a maximum of none is none. It is the default, so a fleet that turns
	// providers on has to say in the same breath how many machines it is
	// willing to pay for, and the validator says so when it has not. The
	// alternative -- zero meaning "unbounded" -- puts the one number that
	// decides the size of an invoice behind a value somebody can leave unset.
	MaxMachines int `yaml:"max_machines"`
	// MaxCreatesInFlight caps how many machines may be being built at once
	// across the fleet, so a burst of queued jobs cannot ask a hypervisor for
	// fifty clones in one pass.
	MaxCreatesInFlight int `yaml:"max_creates_in_flight"`
	// ScaleUpDelay is how long a pool's demand must stand before a machine is
	// bought for it. It defaults to zero, unlike the scheduler's: that one damps
	// runner churn, and a runner costs seconds, whereas a machine that takes
	// four minutes to arrive has already spent the delay by being slow.
	ScaleUpDelay time.Duration `yaml:"scale_up_delay"`
	// CallTimeout bounds one API request to a provider.
	CallTimeout time.Duration `yaml:"call_timeout"`
	// CreateTimeout bounds the whole asynchronous creation of a machine, not
	// the request that starts it.
	CreateTimeout time.Duration `yaml:"create_timeout"`
	// BootstrapTimeout bounds installing the agent inside a machine that is up.
	BootstrapTimeout time.Duration `yaml:"bootstrap_timeout"`
	// EnrolTimeout is how long a bootstrapped machine has to appear as a host.
	// It has to outlast a heartbeat timeout, or a machine that joined and went
	// briefly quiet would be given up on.
	EnrolTimeout time.Duration `yaml:"enrol_timeout"`
	// DeleteTimeout bounds an asynchronous deletion.
	DeleteTimeout time.Duration `yaml:"delete_timeout"`
	// AmbiguityTimeout is how long an operation whose outcome is unknown is
	// reconciled by looking before a person is asked instead. It must outlast
	// CreateTimeout: a create that is merely slow is not an unknown outcome.
	AmbiguityTimeout time.Duration `yaml:"ambiguity_timeout"`
	// IdleTimeout is how long a machine's host must have had no runner on it
	// before the machine is drained.
	IdleTimeout time.Duration `yaml:"idle_timeout"`
	// ScaleDownCooldown is how long that idleness must hold continuously before
	// anything is deleted, so a quiet minute between two bursts does not
	// destroy the machines the second burst is about to want.
	ScaleDownCooldown time.Duration `yaml:"scale_down_cooldown"`
	// DeleteGrace is how long a machine whose host has gone silent is left
	// alone before it is treated as lost. It has to outlast the controller's
	// own "this host is lost" judgement, or a network blip would destroy a
	// machine that is in the middle of a job.
	DeleteGrace time.Duration `yaml:"delete_grace"`
}

// Server controls the HTTP listener.
type Server struct {
	// TailcatEnabled permits private agent connections, started on first enrolment.
	TailcatEnabled bool `yaml:"tailcat_enabled"`
	// Bind defaults to 127.0.0.1:8080. Binding to 0.0.0.0 without TLS is a
	// warning, not an error, because a reverse proxy in front is legitimate.
	Bind string `yaml:"bind"`
	// ExternalURL is how GitHub and browsers reach this controller. It is
	// required once webhooks are in play, since it forms the webhook URL.
	ExternalURL string `yaml:"external_url"`
	TLS         TLS    `yaml:"tls"`
	// TrustedProxies lists CIDRs whose X-Forwarded-For header is believed.
	// Empty means client IPs come from the socket, which is the safe default.
	// The word "cloudflare" expands to Cloudflare's published ranges.
	TrustedProxies []string      `yaml:"trusted_proxies"`
	ReadTimeout    time.Duration `yaml:"read_timeout"`
	WriteTimeout   time.Duration `yaml:"write_timeout"`
	IdleTimeout    time.Duration `yaml:"idle_timeout"`
	// AllowedOrigins restricts browser origins for state-changing requests.
	// Empty means same-origin only, which is what the embedded UI needs.
	AllowedOrigins []string `yaml:"allowed_origins"`
	// AllowIndexing invites search engines into the UI. Off by default: a
	// controller is somebody's infrastructure rather than somebody's website,
	// so robots.txt declines crawling until an operator says otherwise.
	AllowIndexing bool `yaml:"allow_indexing"`
}

// TLSMode selects how the listener terminates TLS.
type TLSMode string

const (
	// TLSOff serves plain HTTP. Correct behind a reverse proxy; a warning
	// otherwise.
	TLSOff TLSMode = "off"
	// TLSSelfSigned generates and persists a self-signed certificate.
	TLSSelfSigned TLSMode = "self-signed"
	// TLSFiles uses an operator-provided certificate and key.
	TLSFiles TLSMode = "files"
)

// TLS configures transport security for the controller listener.
type TLS struct {
	Mode     TLSMode `yaml:"mode"`
	CertFile string  `yaml:"cert_file"`
	KeyFile  string  `yaml:"key_file"`
	// Hosts are the names baked into a generated self-signed certificate.
	Hosts []string `yaml:"hosts"`
}

// Database points at the SQLite file.
type Database struct {
	Path string `yaml:"path"`
}

// Security holds instance-wide security settings.
type Security struct {
	// EncryptionKey is a base64 or hex 32-byte key. Prefer EncryptionKeyFile
	// or the ZOOMIES_ENCRYPTION_KEY environment variable; a key written into
	// zoomies.yaml is a key in your configuration management system.
	EncryptionKey     string `yaml:"encryption_key"`
	EncryptionKeyFile string `yaml:"encryption_key_file"`
	// SessionTTL is how long a browser login lasts.
	SessionTTL time.Duration `yaml:"session_ttl"`
	// CookieSecure forces the Secure attribute on session cookies. It is
	// derived from the external URL when unset.
	CookieSecure *bool `yaml:"cookie_secure"`
	// DisableAuth removes all authentication. It exists for local development
	// only and is refused wherever the controller looks reachable -- see
	// LikelyReachable, which counts an external URL or a trusted proxy as
	// reachable even on a loopback bind.
	DisableAuth bool `yaml:"disable_auth"`
	// RateLimitLogins caps password attempts per source address per minute.
	RateLimitLogins int `yaml:"rate_limit_logins"`
	// DockerInDockerExpected stops a pool that gives its jobs a private daemon
	// raising pool.dangerous for the privileged sidecar that daemon runs in.
	//
	// A warning an operator cannot act on is a warning they stop reading, and
	// with it the ones they could. A fleet whose whole purpose is building
	// container images has made that choice once, deliberately, and repeating
	// it for every such pool on every pass buries the settings that are still
	// worth a second look. It silences that one sentence and nothing else: the
	// host socket still warns, because it hands a job root on the host, and so
	// do persistent runners.
	DockerInDockerExpected bool `yaml:"docker_in_docker_expected"`
	// AllowPrivateEgress lets the settings that make this process dial a URL
	// -- the OIDC issuer, the GitHub API, the capacity-demand destination,
	// the runner download mirror, a backup remote, a provider -- name this
	// machine, its link-local network or a private range. See
	// CheckOutboundURL. It is off because those addresses are the platform's
	// own neighbourhood, and on a single-team instance whose identity
	// provider or Enterprise Server is on the LAN it is the one key to set.
	AllowPrivateEgress bool `yaml:"allow_private_egress"`
	// RequireTwoStep makes every account that signs in with a password set
	// up two-step verification at its next sign-in. Accounts that sign in
	// through single sign-on are not asked -- their identity provider owns
	// their second factor -- and API tokens are not affected.
	RequireTwoStep bool `yaml:"require_two_step"`
	// MCPOAuth lets an MCP client -- Claude, added as a connector by URL --
	// sign a person in through the browser and receive a token for /mcp
	// alone, with this controller as its own authorisation server. Unset
	// follows the deployment: on when authentication is on and the controller
	// is reached over https, which is the only way such a client can reach it
	// safely. See MCPOAuthEnabled.
	MCPOAuth *bool `yaml:"mcp_oauth"`
	// MCPOpenRegistration lets an MCP client register itself -- through
	// dynamic client registration or a client ID metadata document -- rather
	// than only use a client an administrator created. A client that
	// registers itself still cannot do anything until a person signs in and
	// approves it, which is why it is on by default.
	MCPOpenRegistration bool `yaml:"mcp_open_registration"`
}

// GitHub configures the GitHub integration.
type GitHub struct {
	// APIBaseURL is https://api.github.com for github.com, or
	// https://ghes.example.com/api/v3 for GitHub Enterprise Server.
	APIBaseURL    string `yaml:"api_base_url"`
	UploadBaseURL string `yaml:"upload_base_url"`
	WebhookPath   string `yaml:"webhook_path"`
	// PollInterval drives the fallback poller that lists queued jobs when
	// webhooks cannot reach this controller.
	PollInterval time.Duration `yaml:"poll_interval"`
	// PollFallback enables that poller. It is on by default: a controller that
	// silently stops scaling because a webhook was misconfigured is worse than
	// a few extra API calls.
	PollFallback bool `yaml:"poll_fallback"`
	// AllowWorkflowCancellation lets operators ask GitHub to cancel the whole
	// workflow run that owns a Zoomies job. It is on by default; operators who
	// want a read-only Actions grant can explicitly disable it.
	AllowWorkflowCancellation bool `yaml:"allow_workflow_cancellation"`
	// ToolchainScanInterval is how often every workflow every installation
	// can see is read for the toolchains its jobs install; 0 scans only when
	// asked. Off by default, because a scan reads every workflow file in
	// every repository -- thousands of calls on a large organisation, from
	// the quota the scheduler needs to find queued jobs.
	ToolchainScanInterval time.Duration `yaml:"toolchain_scan_interval"`
	// RunnerImage is the default container image for new pools.
	RunnerImage string `yaml:"runner_image"`
	// RunnerVersion pins the actions/runner release; empty tracks the image.
	RunnerVersion string `yaml:"runner_version"`
}

// Agent configures the runner-executing half of the system.
type Agent struct {
	// Embedded runs an agent inside the controller process, so the single-VM
	// case needs exactly one process.
	Embedded bool   `yaml:"embedded"`
	Name     string `yaml:"name"`
	Capacity int    `yaml:"capacity"`
	Backend  string `yaml:"backend"`
	// DockerHost is a docker/podman socket URL. Empty means autodetect, which
	// prefers a rootless socket over the root one.
	DockerHost string            `yaml:"docker_host"`
	WorkDir    string            `yaml:"work_dir"`
	Labels     map[string]string `yaml:"labels"`
	// ControllerURL and JoinToken are used by `zoomies agent` in standalone
	// mode; they are ignored by the embedded agent.
	ControllerURL string `yaml:"controller_url"`
	JoinToken     string `yaml:"join_token"`
	AgentToken    string `yaml:"agent_token"`
	// CAFile pins the controller's certificate for a standalone agent.
	CAFile string `yaml:"ca_file"`
	// ClientCertFile and ClientKeyFile enable mTLS to the controller.
	ClientCertFile string `yaml:"client_cert_file"`
	ClientKeyFile  string `yaml:"client_key_file"`
	// InsecureSkipVerify disables controller certificate verification.
	InsecureSkipVerify bool `yaml:"insecure_skip_verify"`
	// AllowInsecureHTTP permits an http:// controller URL that is not on
	// loopback. Off by default: the agent token and the runner registration
	// credentials in every create task would otherwise cross the network in
	// the clear.
	AllowInsecureHTTP bool          `yaml:"allow_insecure_http"`
	HeartbeatInterval time.Duration `yaml:"heartbeat_interval"`
	// Network is an optional pre-existing container network to attach runners to.
	Network string `yaml:"network"`
	// RunnerSHA256 is the expected digest of the actions/runner archive the
	// process backend downloads for this host's OS and architecture. Zoomies
	// ships the digests for the release it pins; an operator who pins another
	// release with github.runner_version supplies its digest here, from the
	// actions/runner release notes, and gets a verified download.
	RunnerSHA256 string `yaml:"runner_sha256"`
	// AllowUnverifiedRunnerDownload lets the process backend install a runner
	// archive whose digest it cannot check. Off by default and warned about:
	// the alternative is executing whatever the network handed over.
	AllowUnverifiedRunnerDownload bool `yaml:"allow_unverified_runner_download"`
	// RegistryAuth is a base64 X-Registry-Auth value the container backends
	// send when they pull. Without it a pool on a private registry cannot use
	// pull_policy: pinned-only at all, because the pull it needs is the one
	// the registry refuses. Best supplied as ZOOMIES_REGISTRY_AUTH rather than
	// written into zoomies.yaml: it is a credential.
	RegistryAuth string `yaml:"registry_auth"`
	// RunnerDownloadURL replaces github.com/actions/runner/releases/download as
	// the place the process backend fetches archives from, for hosts that
	// mirror releases internally. The path below it is the same.
	RunnerDownloadURL string `yaml:"runner_download_url"`
	// ExtraCAFile is a PEM bundle on this host that container runners, and
	// their Docker sidecars, add to what they trust. It is a host setting and
	// not a pool one because a TLS-intercepting proxy is a property of the
	// network the host sits on: every job there needs it, whichever pool it
	// came from. The process backend ignores it -- a bare runner already uses
	// the host's own trust store.
	ExtraCAFile string `yaml:"extra_ca_file"`
	// FinishedRetention is how long a finished runner's workload -- the exited
	// container with its output, its sidecar and scratch directory, or the
	// process backend's runner directory -- stays on the host after the
	// controller has been told how the runner ended, before the agent deletes
	// it. It is the window an operator has to read a finished runner's log.
	// Zero deletes on the next pass. Unlike retention.runners, which keeps the
	// row, this is disk on the host: a busy host keeps one finished
	// container per job for this long.
	FinishedRetention time.Duration `yaml:"finished_retention"`
	// PrewarmTimeout bounds background work separately from foreground starts.
	PrewarmTimeout time.Duration `yaml:"prewarm_timeout"`
	PrewarmJitter  time.Duration `yaml:"prewarm_jitter"`
	// BootstrapCPUGrace preserves normal quotas before host-pressure reductions.
	BootstrapCPUGrace time.Duration `yaml:"bootstrap_cpu_grace"`
	// DockerBuildCacheMB is the target for unused Docker builder cache. Zero
	// disables automatic cache pruning on shared or externally managed daemons.
	DockerBuildCacheMB int `yaml:"docker_build_cache_mb"`
}

// Scheduler tunes the scaling loop.
type Scheduler struct {
	// PlacementMode keeps readiness-based host selection opt-in until measured.
	PlacementMode string `yaml:"placement_mode"`
	// HistorySizing is off, shadow or on: whether a runner is placed on a host
	// with room for, and sized to, what the jobs waiting on its pool are known
	// to need from their recent runs. Shadow, the default, works it out and
	// records where it would have differed without changing placement.
	HistorySizing string `yaml:"history_sizing"`
	// Interval is how often the reconcile loop runs even without an event.
	Interval time.Duration `yaml:"interval"`
	// ScaleUpDelay makes the scheduler wait before reacting to a queued job,
	// which damps churn when jobs arrive in bursts. Zero reacts immediately.
	ScaleUpDelay time.Duration `yaml:"scale_up_delay"`
	// MaxRunnerLifetime drains a runner that has lived this long, the next
	// time it is not busy. It bounds how long a persistent runner's state and
	// credentials live; it never ends a job, so it is no answer to a hung
	// one -- that is what a workflow's timeout-minutes is for.
	MaxRunnerLifetime time.Duration `yaml:"max_runner_lifetime"`
	// ProvisionTimeout fails a runner that never finishes registering. It is
	// the last of three bounds on a runner's start and the only one that gives
	// up, so it has to outlast the other two: the agent's own create budget,
	// which covers a cold image pull, and the wait a Docker pool's runner does
	// for its daemon before it registers at all. Set inside those, it condemns
	// runners the rest of the system is patiently still making.
	ProvisionTimeout time.Duration `yaml:"provision_timeout"`
	// DrainTimeout fails a runner that has been draining this long with no job
	// left on it, so a stop lost to a controller restart stops holding a host
	// slot for ever. A runner still finishing a job is never touched by it.
	DrainTimeout time.Duration `yaml:"drain_timeout"`
	// MaxCreatesPerTick caps how many runners may be created in one pass, so a
	// thundering herd of queued jobs cannot exhaust a host in one go.
	MaxCreatesPerTick int `yaml:"max_creates_per_tick"`
	// RegistrationConcurrency bounds outstanding credential requests per installation.
	RegistrationConcurrency int `yaml:"registration_concurrency"`
	// DefaultRunnerLimits gives a runner whose pool sets no CPU or memory
	// limit one slot's share of its host's machine as a real cgroup limit --
	// the same share the scheduler already charges it. Off, such a runner is
	// given no limit at all, and a host's worth of them can each take every
	// core, which is the overload this setting exists to prevent.
	DefaultRunnerLimits bool `yaml:"default_runner_limits"`
	// AutoRerun asks GitHub to run a job again when this fleet is what broke
	// it -- a runner that died under it, not a test that failed. It is off by
	// default and deliberately so: GitHub minutes are the operator's to spend,
	// and a job that got as far as running may have had side effects its
	// author knows about and this does not.
	AutoRerun bool `yaml:"auto_rerun"`
	// AutoRerunLimit is how many times one workflow run may be re-run
	// automatically. It is what stops a fault the fleet is causing every time
	// from re-running the same job for ever, and it is counted from GitHub's
	// own run attempt rather than from anything we store: the bound therefore
	// survives a controller restart, and a re-run an operator asked for by
	// hand counts against it like any other.
	AutoRerunLimit int `yaml:"auto_rerun_limit"`
	// HostThrottling lets the controller throttle a host whose measurements
	// say it is overwhelmed: fewer slots, and a lower CPU quota on the runners
	// already on it, stepped back up after a stretch of calm. Off, the
	// pressure holds still refuse new starts while the pressure is acute, and
	// nothing outlasts them.
	HostThrottling bool `yaml:"host_throttling"`
}

// Log configures structured logging.
type Log struct {
	Level  string `yaml:"level"`  // debug | info | warn | error
	Format string `yaml:"format"` // json | text
}

// OIDC configures optional single sign-on.
type OIDC struct {
	Enabled      bool     `yaml:"enabled"`
	Issuer       string   `yaml:"issuer"`
	ClientID     string   `yaml:"client_id"`
	ClientSecret string   `yaml:"client_secret"`
	RedirectURL  string   `yaml:"redirect_url"`
	Scopes       []string `yaml:"scopes"`
	// UsernameClaim and GroupsClaim map token claims onto Zoomies identities.
	UsernameClaim string `yaml:"username_claim"`
	GroupsClaim   string `yaml:"groups_claim"`
	// AdminGroups and OperatorGroups map IdP groups onto Zoomies roles. A user
	// in no mapped group gets the viewer role.
	AdminGroups    []string `yaml:"admin_groups"`
	OperatorGroups []string `yaml:"operator_groups"`
	// PlatformGroups maps onto the role above administrator. It is listed
	// first when a login is mapped, so somebody in both a platform group
	// and an admin group gets the higher of the two rather than whichever
	// the code happened to check first.
	PlatformGroups []string `yaml:"platform_groups"`
	// AllowSignup provisions an account on first successful login.
	AllowSignup bool `yaml:"allow_signup"`
	// LinkByUsername lets a first single sign-on login take over an existing
	// local account that has a password and the same username. Off, the
	// username alone links only to an account created for SSO -- one with no
	// password -- because with an identity provider whose users can influence
	// their own username claim, a sign-in as "admin" would otherwise inherit
	// the local admin's role. Turn it on for the one migration where that is
	// the intention, then turn it off again.
	LinkByUsername bool `yaml:"link_by_username"`
	// Label is the words on the sign-in button. Empty derives them from the
	// issuer's host, which is what an operator recognises without being told.
	Label string `yaml:"label"`
	// HidePasswordLogin takes the password form off the sign-in page while
	// single sign-on is working, so people are not invited to keep a second
	// credential alive. It is never a lock: an administrator can still sign in
	// with a password from /login?password, the break-glass door for the day
	// the identity provider is the thing that is broken.
	HidePasswordLogin bool `yaml:"hide_password_login"`
}

// Metrics configures the Prometheus endpoint.
type Metrics struct {
	Enabled bool   `yaml:"enabled"`
	Path    string `yaml:"path"`
	// Public exposes /metrics without authentication. Off by default because
	// job and repository names are visible in the label set.
	Public bool `yaml:"public"`
}

// StatusMode says who may read the fleet's status projection: the
// name-free, banded summary at /api/v1/status, the page at /status and the
// badge at /status.svg.
type StatusMode string

const (
	// StatusOff serves none of the three. It is the default, because a new
	// capability starts disabled and this one's cost is disclosure.
	StatusOff StatusMode = "off"
	// StatusAuthenticated serves them to anyone signed in, whatever their
	// role.
	StatusAuthenticated StatusMode = "authenticated"
	// StatusPublic serves them to anyone who can reach the listener, which is
	// the point for a developer with no account whose job has queued, and is
	// warned about for the same reason.
	StatusPublic StatusMode = "public"
)

// Status configures the fleet's status projection.
type Status struct {
	Mode StatusMode `yaml:"mode"`
}

// Runners is what every runner this fleet creates is started with, whichever
// pool and host it lands on. A pool's own env is layered over it, so the fleet
// says what is usual and a pool says what is different.
//
// It is a section of its own rather than part of Agent because it is not about
// the agent at all: the controller writes these into the runner's environment
// when it builds the create task, and a standalone agent on another host never
// reads them.
type Runners struct {
	// DockerWait is how long a runner on a pool that provides Docker waits
	// for that daemon before refusing to take a job. It reaches the runner
	// image as ZOOMIES_DOCKER_WAIT, in whole seconds. Zero leaves the image's
	// own default in place.
	DockerWait time.Duration `yaml:"docker_wait"`
	// Env is extra environment for every runner. It is visible to every job
	// that runs, so it is the place for a proxy or a mirror and not for a
	// credential: a pool's env, or a GitHub secret, is where those belong.
	Env map[string]string `yaml:"env"`
	// DefaultCPUs and DefaultMemoryMB are where a pool's size sliders open
	// when somebody chooses a fixed size. They are not what a pool with no
	// size becomes: such a pool is given one slot's share of whichever host
	// each runner lands on, charged against that host and applied as a real
	// cgroup limit, which is the sizing most fleets want and what a new pool
	// does.
	//
	// The distinction matters because the two behave differently as a fleet
	// grows. A share follows the machine, so one pool is sized correctly on
	// every host it reaches; a figure typed here is the same everywhere, so it
	// fits the host it was chosen for and strands the machine on the ones that
	// joined later.
	//
	// They are a fleet's answer rather than a constant because the right
	// answer is the shape of the machines and the jobs: two cores and four
	// gigabytes suits most, and a fleet of small boxes or of compilers is
	// entitled to say otherwise once rather than on every pool it creates.
	// Zero or less is not "no limit" -- it is nothing having been said, and
	// DefaultRunnerSize answers with the built-in figures.
	DefaultCPUs     float64 `yaml:"default_cpus"`
	DefaultMemoryMB int64   `yaml:"default_memory_mb"`
	// MinimumCPUs and MinimumMemoryMB are the fleet's minimum: the least a
	// runner may be given when no host has room for its standard size -- the
	// figures above for a fixed pool, a whole slot's share of the host for an
	// automatic one. Unlike the standard figures they are not an opening
	// value: every pool whose own minimum is zero follows them live
	// (controller.EffectiveMinimum), so changing them moves those pools with
	// no row rewritten. Zero is none, which is what every fleet was before
	// they existed, so an upgrade changes nothing.
	MinimumCPUs     float64 `yaml:"minimum_cpus"`
	MinimumMemoryMB int64   `yaml:"minimum_memory_mb"`
}

// The size a runner gets where nothing else says: two cores and four
// gigabytes. It is what a pool created today opens on, and it is deliberately
// modest -- a figure an operator raises for the pool that needs it is better
// than one that fits three runners on a machine that has room for eight.
const (
	DefaultRunnerCPUs     = 2
	DefaultRunnerMemoryMB = 4096
)

// EffectiveDockerWait is how long a Docker pool's runner actually waits for its
// daemon, which is not the same as what this setting says: zero does not mean
// no wait, it means the runner image chooses, and the image waits two minutes.
// Anything reasoning about how long a runner may take to start has to read the
// wait that happens rather than the one that was configured.
func (r Runners) EffectiveDockerWait() time.Duration {
	if r.DockerWait > 0 {
		return r.DockerWait
	}
	return ImageDockerWait
}

// DefaultRunnerSize is the per-runner CPU and memory a pool gets when it names
// none, with the built-in figures standing in for a setting nobody has given a
// usable value.
func (r Runners) DefaultRunnerSize() (cpus float64, memoryMB int64) {
	cpus, memoryMB = r.DefaultCPUs, r.DefaultMemoryMB
	if cpus <= 0 {
		cpus = DefaultRunnerCPUs
	}
	if memoryMB <= 0 {
		memoryMB = DefaultRunnerMemoryMB
	}
	return cpus, memoryMB
}

// Limits are fleet-wide ceilings on what callers of the API and agents can
// make the controller hold. Each is zero by default, meaning unlimited.
//
// They exist for an instance several teams use, where one team's script
// minting join tokens in a loop, or a browser left open in forty tabs, spends
// memory and database rows every other team shares. A limit refuses the
// request that would cross it, with a message naming the setting, rather than
// letting the process find out by running out of something.
type Limits struct {
	// Hosts caps enrolled hosts. A host that joins again under its own name
	// replaces its row and is not counted twice.
	Hosts int `yaml:"hosts"`
	// Pools caps pools.
	Pools int `yaml:"pools"`
	// Runners caps live runners across every pool. The scheduler stops
	// creating at the ceiling and says so in each pool's scaling reason.
	Runners int `yaml:"runners"`
	// JoinTokens caps join tokens that are still outstanding: neither used
	// nor expired.
	JoinTokens int `yaml:"join_tokens"`
	// EventSubscribers caps open live-update streams.
	EventSubscribers int `yaml:"event_subscribers"`
	// JobStatsWindow is the longest span GET /api/v1/jobs/stats will
	// aggregate in one request. The statistics are computed from the job
	// rows on demand, so the bound is what keeps a single request from
	// scanning a database that has kept a year of history. Unlike the
	// ceilings above, zero is not unlimited: it reads as the 90-day default.
	JobStatsWindow time.Duration `yaml:"job_stats_window"`
}

// DefaultJobStatsWindow is the job statistics' window when none is set.
const DefaultJobStatsWindow = 90 * 24 * time.Hour

// JobStatsSpan is JobStatsWindow with the default applied.
func (l Limits) JobStatsSpan() time.Duration {
	if l.JobStatsWindow <= 0 {
		return DefaultJobStatsWindow
	}
	return l.JobStatsWindow
}

// Retention bounds how much history the database keeps.
//
// Audit rows are deliberately absent: an audit trail a process can quietly
// delete is not one, and the store offers no way to prune them.
type Retention struct {
	Jobs    time.Duration `yaml:"jobs"`
	Runners time.Duration `yaml:"runners"`
	// RunnerSessions is how long the usage ledger keeps a gone runner's
	// session. It is separate from Runners, and far longer, because the row
	// is what an operator debugs with for a week and the session is what they
	// reconcile a year's cloud bill against.
	RunnerSessions time.Duration `yaml:"runner_sessions"`
	// ScalingEvents is how long scaling decisions are kept. It used to be
	// called audit, and a file that still says so is honoured -- see Audit.
	ScalingEvents time.Duration `yaml:"scaling_events"`
	// Audit is the old name for ScalingEvents. It never bounded audit rows,
	// which are not pruned, so the name promised a deletion that never
	// happened and hid one that did. A value here still sets ScalingEvents,
	// with an info finding asking for the rename.
	Audit    time.Duration `yaml:"audit"`
	Samples  time.Duration `yaml:"samples"`
	Webhooks time.Duration `yaml:"webhooks"`
	// Machines is how long a deleted machine's row is kept. The row outlives
	// the VM on purpose: it is the only record of what was rented, when, and
	// what it cost, and an operator reconciling a hypervisor bill against the
	// fleet is reading exactly this.
	Machines time.Duration `yaml:"machines"`
}

// Path returns the file this config was loaded from, or "" for defaults.
func (c *Config) Path() string { return c.path }

// Default returns a configuration that is safe to run as-is: loopback only,
// ephemeral Docker runners, no Docker socket exposed to jobs, auth on.
func Default() *Config {
	return &Config{
		Server: Server{
			TailcatEnabled: true,
			Bind:           "127.0.0.1:8080",
			TLS:            TLS{Mode: TLSOff},
			ReadTimeout:    30 * time.Second,
			WriteTimeout:   0, // 0: SSE streams and log tails must not be cut off
			IdleTimeout:    120 * time.Second,
		},
		Database: Database{Path: defaultStatePath("zoomies.db")},
		Security: Security{
			EncryptionKeyFile: defaultConfigPath("encryption.key"),
			SessionTTL:        7 * 24 * time.Hour,
			RateLimitLogins:   10,
			// Registration only ever creates a client that has to be approved
			// by somebody signing in, so being open costs a row, not access.
			MCPOpenRegistration: true,
		},
		GitHub: GitHub{
			APIBaseURL:                "https://api.github.com",
			WebhookPath:               "/webhooks/github",
			PollInterval:              30 * time.Second,
			PollFallback:              true,
			AllowWorkflowCancellation: true,
			RunnerImage:               DefaultRunnerImage,
		},
		Agent: Agent{
			Embedded:          true,
			Capacity:          defaultCapacity(),
			Backend:           "docker",
			WorkDir:           defaultStatePath("work"),
			HeartbeatInterval: 30 * time.Second,
			// The controller already retains runner history and the agent waits for
			// its terminal report to be acknowledged before removal. Keeping an
			// exited container as well makes every job consume host disk for no
			// default benefit; operators who debug from container logs can opt in.
			FinishedRetention:  0,
			BootstrapCPUGrace:  2 * time.Minute,
			PrewarmTimeout:     5 * time.Minute,
			PrewarmJitter:      30 * time.Second,
			DockerBuildCacheMB: 0,
		},
		Scheduler: Scheduler{
			Interval:          10 * time.Second,
			ScaleUpDelay:      0,
			MaxRunnerLifetime: 6 * time.Hour,
			// Longer than the agent's own create budget and the runner image's
			// Docker wait together, because those two are what a runner's start
			// actually costs on a cold host: fifteen minutes for a pull on a
			// slow link, then two for the daemon. Five minutes -- what this was
			// before the runners section existed to say the second number --
			// failed runners that were still coming up and had the pool replace
			// them, which put a second pull of the same image on the same link.
			// The genuinely broken create does not wait for this: the agent
			// reports the failure and the row fails on the report. This is the
			// backstop for the create that is never reported at all.
			ProvisionTimeout:        20 * time.Minute,
			DrainTimeout:            15 * time.Minute,
			MaxCreatesPerTick:       10,
			DefaultRunnerLimits:     true,
			RegistrationConcurrency: 1,
			PlacementMode:           "headroom",
			HistorySizing:           "shadow",
			HostThrottling:          true,
			AutoRerunLimit:          1,
		},
		Log:     Log{Level: "info", Format: "json"},
		Metrics: Metrics{Enabled: true, Path: "/metrics"},
		Status:  Status{Mode: StatusOff},
		OIDC: OIDC{
			Scopes:        []string{"openid", "profile", "email"},
			UsernameClaim: "preferred_username",
			GroupsClaim:   "groups",
		},
		Limits: Limits{JobStatsWindow: DefaultJobStatsWindow},
		Retention: Retention{
			Jobs:           30 * 24 * time.Hour,
			Runners:        7 * 24 * time.Hour,
			RunnerSessions: 365 * 24 * time.Hour,
			ScalingEvents:  365 * 24 * time.Hour,
			Samples:        7 * 24 * time.Hour,
			Webhooks:       7 * 24 * time.Hour,
			Machines:       7 * 24 * time.Hour,
		},
		// Hourly is soon enough that a host picks up a rebuilt image the same
		// working day, and rare enough that the registry never notices.
		Images: Images{RefreshInterval: time.Hour},
		// Two minutes matches the runner image's own default: dockerd in a
		// fresh sidecar on a host that is also extracting images takes longer
		// than the thirty seconds the first version allowed.
		Runners: Runners{
			DockerWait:      3 * time.Minute,
			DefaultCPUs:     DefaultRunnerCPUs,
			DefaultMemoryMB: DefaultRunnerMemoryMB,
		},
		// Daily: releases are not frequent, and a controller that asks once a
		// day still tells you within a working day of one being published.
		Updates: Updates{CheckInterval: 24 * time.Hour},
		// Nightly, keeping a week. The database holds configuration and
		// history rather than anything a workflow depends on minute to
		// minute, so a day is the right grain; seven copies bounds the disk
		// on a fleet whose database is large, and covers the week it takes
		// to notice a mistake made on Monday.
		Backup:         Backup{Interval: 24 * time.Hour, Keep: 7},
		CapacityDemand: CapacityDemand{Cooldown: 10 * time.Minute, Timeout: 10 * time.Second},
		// Off, with no ceiling and every step generously bounded. The numbers
		// are what a hypervisor actually takes: a full clone of a small Linux
		// template is minutes rather than seconds, and a guest that has to
		// finish cloud-init before its agent starts is minutes again. A
		// deployment that turns this on sets max_machines in the same edit,
		// which is what the validator's warning is for.
		Provider: Provider{
			Interval:           30 * time.Second,
			SweepInterval:      10 * time.Minute,
			MaxCreatesInFlight: 2,
			CallTimeout:        30 * time.Second,
			CreateTimeout:      20 * time.Minute,
			BootstrapTimeout:   10 * time.Minute,
			EnrolTimeout:       15 * time.Minute,
			DeleteTimeout:      15 * time.Minute,
			AmbiguityTimeout:   30 * time.Minute,
			IdleTimeout:        15 * time.Minute,
			ScaleDownCooldown:  15 * time.Minute,
			DeleteGrace:        10 * time.Minute,
		},
		// Every host on one chart, on both pages: it is the layout that reads
		// a small fleet at a glance, and a fleet large enough to want the
		// other one is a fleet whose administrator has been to the settings.
		UI: UI{
			CapacityMap: CapacityMap{
				OverviewLayout: CapacityLayoutOverlay,
				HostsLayout:    CapacityLayoutOverlay,
			},
			// One: a queue with anything at all waiting is worth an operator's
			// glance, which is the behaviour this setting replaces.
			QueueWarningThreshold: 1,
		},
	}
}

// DefaultRunnerImage is the image a pool uses when it names neither an image
// nor an operating system. It is the default variant of the catalogue in
// internal/naming, built from deploy/Dockerfile.runner; a pool that does name
// an operating system gets that variant instead.
var DefaultRunnerImage = naming.DefaultRunnerImage()

// DefaultRunnerDockerImage is DefaultRunnerImage plus a Docker client: the
// same file's runner-docker target, published under the same tags. It is what
// a pool whose docker_mode gives its jobs a daemon actually runs, whichever of
// the two the pool names; see RunnerImageFor.
var DefaultRunnerDockerImage = stockRunnerDockerRepository + ":" + naming.RunnerImageTag

// The two repositories RunnerImageFor translates between.
const (
	stockRunnerRepository       = "ghcr.io/eyupio/zoomies-runner"
	stockRunnerDockerRepository = "ghcr.io/eyupio/zoomies-runner-docker"
)

// ResolvePoolRunnerImage keeps automatic images on the build's channel, including
// their Docker CLI variants: the pool's own image where it has one, the variant
// its platform names, or the instance default, and then the Docker swap.
func ResolvePoolRunnerImage(poolImage, os, version, instanceDefault string, daemon bool) string {
	return RunnerImageFor(naming.ResolveRunnerImage(poolImage, os, version, instanceDefault), daemon)
}

// RunnerImageFor returns the image a pool's runners are created from, given
// the image the pool names and whether its docker_mode gives jobs a daemon.
//
// A docker_mode gives a job a daemon and nothing else; the client has to come
// from the image, and the stock runner image carries none, on purpose, because
// most pools never build an image. Leaving the operator to remember that -- to
// set the mode *and* swap the image for its Docker variant -- was the mistake
// everybody made: the daemon came up, the job reached its first docker step,
// and it failed with "Unable to locate executable file: docker", which names
// the missing binary and not the reason.
//
// So the swap is made here, once, whenever daemon is true, and only where the
// variant is known to exist: the stock repository, no digest, under a tag this
// build's own catalogue accounts for -- see naming.PublishedRunnerTag. One step
// of one workflow publishes both images, so such a tag exists for both or for
// neither, which a pinned pool's tag from some other build does not promise.
//
// Everything else is left exactly as it was given. A digest names one exact
// image and cannot be moved to another. A commit pin may name a run whose
// second build never finished. An image of the operator's own is theirs to
// equip, and so is a mirror of the stock image under another registry: whether
// the mirror carries the variant is not something this code can know. A pool
// that asks for a daemon while on one of those is told so -- the pool's page
// and the problems drawer carry pool.docker_client_missing -- rather than left
// to find out one failed job at a time.
//
// The swap is never reversed. A pool that stops asking for a daemon keeps the
// client, which costs it pull time and nothing else, and may be using it
// against a DOCKER_HOST of its own.
func RunnerImageFor(image string, daemon bool) string {
	if !daemon {
		return image
	}
	repo, tag, digest := naming.SplitImage(image)
	if repo != stockRunnerRepository || digest != "" || !naming.PublishedRunnerTag(tag) {
		return image
	}
	return stockRunnerDockerRepository + tag
}

// MissingDockerClient answers, for the image a pool actually runs, whether
// Zoomies knows it carries no Docker client -- and if so, which reference to
// pin instead: the same tag or digest position on the variant's repository, so
// the operator is given something to paste rather than a repository to search.
//
// "Knows" is the whole of it. An image nobody here published may carry a client
// or may not, and warning about every one of them would teach an operator to
// ignore the warning that matters. Only the stock runner image is certain, and
// only a reference RunnerImageFor could not move gets this far.
func MissingDockerClient(image string) (pin string, missing bool) {
	repo, tag, digest := naming.SplitImage(image)
	if repo != stockRunnerRepository {
		return "", false
	}
	return stockRunnerDockerRepository + tag + digest, true
}

func defaultCapacity() int {
	// One runner per two cores is a defensible starting point: a job usually
	// wants more than one core, and the host still has room to breathe.
	if n := runtime.NumCPU() / 2; n > 0 {
		return n
	}
	return 1
}

// StateDir is where the controller keeps its database and runner work areas.
func StateDir() string {
	if v := os.Getenv("ZOOMIES_STATE_DIR"); v != "" {
		return v
	}
	if dir := windowsDir(); dir != "" {
		return dir
	}
	if runtime.GOOS == "darwin" {
		if home, err := os.UserHomeDir(); err == nil {
			return filepath.Join(home, "Library", "Application Support", "zoomies")
		}
	}
	if os.Geteuid() == 0 {
		return "/var/lib/zoomies"
	}
	if dir, err := os.UserConfigDir(); err == nil {
		return filepath.Join(dir, "zoomies")
	}
	return ".zoomies"
}

// SharedDir is the folder Zoomies keeps data on the host in that runners, and
// anything else outside this process, have to reach: /var/lib/zoomies/shared
// on a Linux host where Zoomies runs as root, and the shared folder under the
// state directory everywhere else.
//
// It is not a setting, because a Compose deployment fixes it: the controller's
// container mounts the host's /var/lib/zoomies/shared at the same path, so the
// path the controller hands the host's Docker daemon for a runner's mount
// means the same folder on both sides. A setting that could move it inside
// the container without moving the mount would point every runner at a
// folder the daemon cannot see.
func SharedDir() string { return filepath.Join(StateDir(), "shared") }

// SharedLayout is every folder this release keeps under SharedDir, one per
// purpose. Each is created when an agent starts, so a later release adds a
// purpose by adding a line here and nothing else: the shared folder itself is
// writable by Zoomies for exactly that reason.
var SharedLayout = []string{
	// cache/pools is where a pool cache with an absolute source lives,
	// when the operator points it here.
	"cache/pools",
	// cache/tools holds each pool's tool cache: the Python, Node.js, Go and
	// Java the setup-* actions unpack, kept between runners.
	"cache/tools",
}

// EnsureSharedDir creates SharedDir and every folder in SharedLayout that is
// missing, and reports the first it could not. It changes nothing that
// already exists.
func EnsureSharedDir() error {
	for _, sub := range append([]string{""}, SharedLayout...) {
		dir := filepath.Join(SharedDir(), filepath.FromSlash(sub))
		if err := os.MkdirAll(dir, 0o750); err != nil {
			return fmt.Errorf("creating %s: %w", dir, err)
		}
	}
	return nil
}

// ConfigDir is where zoomies.yaml and the encryption key live.
func ConfigDir() string {
	if v := os.Getenv("ZOOMIES_CONFIG_DIR"); v != "" {
		return v
	}
	if dir := windowsDir(); dir != "" {
		return dir
	}
	if runtime.GOOS == "darwin" {
		if home, err := os.UserHomeDir(); err == nil {
			return filepath.Join(home, "Library", "Application Support", "zoomies")
		}
	}
	if os.Geteuid() == 0 {
		return "/etc/zoomies"
	}
	if dir, err := os.UserConfigDir(); err == nil {
		return filepath.Join(dir, "zoomies")
	}
	return ".zoomies"
}

// windowsDir is the one directory Zoomies uses on Windows, for configuration
// and state alike: %ProgramData%\zoomies. A per-user directory would put the
// agent's credentials under whichever account ran `zoomies agent join`, and
// the service runs as LocalSystem, whose profile is not a place an operator
// looks. Empty everywhere but Windows.
func windowsDir() string {
	if runtime.GOOS != "windows" {
		return ""
	}
	base := os.Getenv("ProgramData")
	if base == "" {
		base = `C:\ProgramData`
	}
	return filepath.Join(base, "zoomies")
}

func defaultStatePath(name string) string  { return filepath.Join(StateDir(), name) }
func defaultConfigPath(name string) string { return filepath.Join(ConfigDir(), name) }

// DefaultConfigFile is the path Load uses when none is given.
func DefaultConfigFile() string { return filepath.Join(ConfigDir(), "zoomies.yaml") }

// Load reads a config file, applies environment overrides and fills defaults.
// A missing file is not an error when path is empty: an operator running
// `zoomies controller` with only environment variables gets working defaults.
func Load(path string) (*Config, error) {
	cfg := Default()
	if err := cfg.readFile(path); err != nil {
		return nil, err
	}
	if err := cfg.applyEnv(); err != nil {
		return nil, err
	}
	cfg.normalize()
	return cfg, nil
}

// readFile decodes a config file over c. An empty path is the default file,
// which may be missing; a path named explicitly may not.
func (c *Config) readFile(path string) error {
	cfg := c
	explicit := path != ""
	if path == "" {
		path = DefaultConfigFile()
	}

	b, err := os.ReadFile(path)
	switch {
	case err == nil:
		// A strict decoder turns a typo like "extenal_url" into an error that
		// names the line, instead of a setting that silently does nothing.
		dec := yaml.NewDecoder(strings.NewReader(string(b)))
		dec.KnownFields(true)
		// An empty file is an empty configuration, not a parse error.
		if err := dec.Decode(cfg); err != nil && !errors.Is(err, io.EOF) {
			return fmt.Errorf("%s: %w", path, err)
		}
		cfg.path = path
		cfg.keyInFile = cfg.Security.EncryptionKey != ""
		for _, key := range keysIn(b) {
			cfg.note(key, SourceFile)
		}
	case os.IsNotExist(err) && !explicit:
		// Defaults plus environment.
	default:
		return fmt.Errorf("reading %s: %w", path, err)
	}
	return nil
}

// LoadOrDefault is Load, but a config file that fails to parse is fatal while a
// missing one is not. It is what the daemon entry points call.
func LoadOrDefault(path string) (*Config, error) { return Load(path) }

// Save writes the configuration to path with 0640 permissions.
//
// It writes what an operator actually chose, not the whole struct. The two
// keys that get the database open go in whatever they are set to -- the file
// is the only place they can live -- and so does everything a standalone agent
// needs to reach its controller. Beyond that, only a value that differs from
// the built-in default is written.
//
// This used to marshal every field, which put all eighty-nine settings in the
// file of every fresh install. That was merely noisy while the file was the
// only source of configuration; now that the database is the one an operator
// edits, it would be worse than noisy -- a key spelled in the file is a key the
// file is in charge of, so a generated file listing all of them would hand the
// whole configuration back to a text editor on the controller's host on the day
// it was installed.
//
// It also stops writing the defaults *as* defaults. agent.capacity comes from
// this machine's core count and database.path from this machine's state
// directory, so a file that spells them freezes one host's answers, and a
// second host given a copy of that file inherits them.
func (c *Config) Save(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return err
	}
	b, err := yaml.Marshal(c.sparse())
	if err != nil {
		return err
	}
	header := "# zoomies.yaml -- the settings this host needs before it can read the rest.\n" +
		"#\n" +
		"# Everything else lives in the database named below and is changed on the\n" +
		"# settings page. A key written here is still honoured -- it is the layer\n" +
		"# underneath the database -- and a ZOOMIES_* environment variable still\n" +
		"# overrides both. See https://github.com/eyupio/zoomies/blob/main/docs/configuration.md\n\n"
	return os.WriteFile(path, append([]byte(header), b...), 0o640)
}

// sparse renders the configuration as the nested tree Save writes: the keys
// that have to be in a file, plus anything that is not the default.
func (c *Config) sparse() map[string]any {
	defaults := Default()
	out := map[string]any{}
	for _, s := range Settings() {
		value, err := c.Value(s.Key)
		if err != nil {
			continue
		}
		text := Text(s, value)
		// A bootstrap key is always written: the file is the only place it can
		// live, so leaving it out because it happens to equal the default would
		// mean the next start had to guess. Everything else, including the
		// agent transport keys, is written only when it differs -- an agent
		// setting at its default is a setting nobody has chosen.
		//
		// agent.work_dir is the one exception to "only when it differs": its
		// default is derived from the euid of whatever process asks for it, and
		// `zoomies agent join` always runs as root while the service it installs
		// almost always runs as an unprivileged one. A join that happens to
		// compute the same path root would default to must still pin it, or the
		// service recomputes a different default under its own uid, finds no
		// credentials at the path it guessed, and fails to start -- while the
		// controller, which saw the join succeed, still shows the host as added.
		if s.Scope != ScopeBootstrap && s.Key != "agent.work_dir" {
			if def, derr := defaults.Value(s.Key); derr == nil && Text(s, def) == text {
				continue
			}
		} else if text == "" {
			continue
		}
		putPath(out, s.Key, yamlValue(s, value))
	}
	return out
}

// yamlValue renders a value the way the strict decoder reads it back: a
// duration as the text an operator writes, and everything else as itself.
func yamlValue(s Setting, value any) any {
	if s.Kind == KindDuration {
		return Text(s, value)
	}
	return value
}

// putPath writes a dotted key into a tree of maps.
func putPath(into map[string]any, key string, value any) {
	parts := strings.Split(key, ".")
	for _, part := range parts[:len(parts)-1] {
		child, ok := into[part].(map[string]any)
		if !ok {
			child = map[string]any{}
			into[part] = child
		}
		into = child
	}
	into[parts[len(parts)-1]] = value
}

// normalize fills in values that depend on other values.
func (c *Config) normalize() {
	// The old name for the scaling-history window still sets it. Only a
	// positive value carries over: zero is what an unset key reads as, and
	// treating it as "keep everything" would turn every file that never
	// mentioned the key into one that switched pruning off.
	//
	// It does not carry over a value the fleet has stored. normalize runs last,
	// after the database layer, so without this an administrator who set the
	// scaling-history window on the settings page would get a 200, an audit
	// row, a stored value -- and a controller quietly running the number in a
	// years-old file. The finding asking for the rename is still raised, which
	// is what eventually removes the file's key altogether.
	if c.Retention.Audit > 0 && c.Source("retention.scaling_events") != SourceDatabase {
		c.Retention.ScalingEvents = c.Retention.Audit
	}
	c.normalizeBackupRemotes()
	c.Log.Level = strings.ToLower(strings.TrimSpace(c.Log.Level))
	if c.Log.Level == "warning" {
		// slog's name for the level is warn; the file may say either.
		c.Log.Level = "warn"
	}
	c.Log.Format = strings.ToLower(strings.TrimSpace(c.Log.Format))
	c.Agent.Backend = strings.ToLower(strings.TrimSpace(c.Agent.Backend))
	// The environment override was always lowercased; the file is now too, so
	// "Self-Signed" in zoomies.yaml is the same mode as self-signed.
	c.Server.TLS.Mode = TLSMode(strings.ToLower(strings.TrimSpace(string(c.Server.TLS.Mode))))
	c.Status.Mode = StatusMode(strings.ToLower(strings.TrimSpace(string(c.Status.Mode))))
	if c.Status.Mode == "" {
		c.Status.Mode = StatusOff
	}
	if c.Server.TLS.Mode == "" {
		c.Server.TLS.Mode = TLSOff
	}
	if !strings.HasPrefix(c.GitHub.WebhookPath, "/") {
		c.GitHub.WebhookPath = "/" + c.GitHub.WebhookPath
	}
	if !strings.HasPrefix(c.Metrics.Path, "/") {
		c.Metrics.Path = "/" + c.Metrics.Path
	}
	c.Server.ExternalURL = strings.TrimRight(c.Server.ExternalURL, "/")
	c.Agent.ControllerURL = strings.TrimRight(c.Agent.ControllerURL, "/")
	// A bare Enterprise Server hostname is accepted, as the docs promise: it
	// gains its scheme and /api/v3 here rather than failing validation for the
	// lack of them. github.com in any spelling is left as the default reads.
	if s := strings.TrimSpace(c.GitHub.APIBaseURL); s != "" && !strings.Contains(s, "api.github.com") && s != "https://github.com" {
		if n, err := NormalizeGitHubAPIBaseURL(s); err == nil {
			c.GitHub.APIBaseURL = strings.TrimRight(n, "/")
		}
	}
	c.CapacityDemand.DestinationURL = strings.TrimSpace(c.CapacityDemand.DestinationURL)
	if c.Agent.Name == "" {
		// A host named for what it is -- "zoomies-16vcpu-32gb-ubuntu-2404-
		// build01" -- answers at a glance the questions a bare hostname makes
		// an operator open three pages to answer.
		c.Agent.Name = machine.DefaultHostName()
	}
	if c.Security.CookieSecure == nil {
		secure := strings.HasPrefix(c.Server.ExternalURL, "https://") || c.Server.TLS.Mode != TLSOff
		c.Security.CookieSecure = &secure
	}
}

// NormalizeGitHubAPIBaseURL turns whatever an operator wrote for a GitHub API
// base into the form the client needs: github.com in any spelling becomes
// https://api.github.com/, a GHE.com tenant becomes its api. host, and an
// Enterprise Server host gains https:// and /api/v3 when it lacks them. The
// result always ends in a slash.
func NormalizeGitHubAPIBaseURL(raw string) (string, error) {
	s := strings.TrimSpace(raw)
	if s == "" || s == "https://github.com" || s == "https://api.github.com" {
		return "https://api.github.com/", nil
	}
	if !strings.Contains(s, "://") {
		s = "https://" + s
	}
	s = strings.TrimRight(s, "/")
	if tenant, ok := gheComTenant(s); ok {
		return tenant, nil
	}
	if !strings.HasSuffix(s, "/api/v3") && !strings.HasSuffix(s, "/api/uploads") &&
		!strings.Contains(s, "api.github.com") {
		s += "/api/v3"
	}
	return s + "/", nil
}

// gheComSuffix is the domain GitHub Enterprise Cloud with data residency
// serves every tenant from.
const gheComSuffix = ".ghe.com"

// gheComTenant recognises a GHE.com tenant and returns its API base.
//
// GHE.com is laid out like github.com rather than like Enterprise Server: the
// REST API is its own host, api.<tenant>.ghe.com, at the root. Treated as an
// Enterprise Server it gained /api/v3, and every request -- the App's token,
// every JIT config -- came back 404, which reads as a wrong App ID rather than
// a wrong URL. So the tenant's web address, the api. host, and either with a
// stray /api/v3 all arrive at the one base that works. Any other host under
// the domain -- uploads.<tenant>.ghe.com for upload_base_url -- keeps its name
// and loses only the path.
func gheComTenant(s string) (string, bool) {
	u, err := url.Parse(s)
	if err != nil || u.Host == "" {
		return "", false
	}
	host := strings.ToLower(u.Hostname())
	labels, ok := strings.CutSuffix(host, gheComSuffix)
	if !ok || labels == "" {
		return "", false
	}
	if !strings.Contains(labels, ".") {
		host = "api." + host
	}
	if port := u.Port(); port != "" {
		host += ":" + port
	}
	return "https://" + host + "/", true
}

// IsGHECom reports whether an API base URL belongs to a GHE.com tenant.
func IsGHECom(apiBaseURL string) bool {
	u, err := url.Parse(strings.TrimSpace(apiBaseURL))
	if err != nil {
		return false
	}
	return strings.HasSuffix(strings.ToLower(u.Hostname()), gheComSuffix)
}

// WebhookURL returns the URL GitHub should deliver to, or "" if the external
// URL is not configured.
func (c *Config) WebhookURL() string {
	if c.Server.ExternalURL == "" {
		return ""
	}
	return c.Server.ExternalURL + c.GitHub.WebhookPath
}

// CookieSecureValue resolves the tri-state cookie flag.
func (c *Config) CookieSecureValue() bool {
	return c.Security.CookieSecure != nil && *c.Security.CookieSecure
}

// MCPOAuthEnabled reports whether /mcp offers OAuth sign-in to MCP clients.
//
// An explicit setting wins, except that there is nothing to sign in to with
// authentication off. Unset, it is on only when the controller says it is
// reached over https -- an https external URL, or TLS on its own listener --
// because the authorisation code and the tokens it is exchanged for would
// otherwise cross the network readable, and because Claude will not use an
// authorisation server that is not on https anyway.
func (c *Config) MCPOAuthEnabled() bool {
	if c.Security.DisableAuth {
		return false
	}
	if c.Security.MCPOAuth != nil {
		// Switched on where it cannot be served safely, it is refused at
		// startup (mcp_oauth.no_external_url) and off until then.
		return *c.Security.MCPOAuth && !c.mcpOAuthWithoutAddress()
	}
	// Unset, it turns itself on only where it would be allowed to be turned
	// on: an instance that listens publicly with its own certificate and no
	// external URL kept working through the upgrade that made the explicit
	// setting an error there, rather than refusing to start over a default.
	if c.BindsPublicly() && strings.TrimSpace(c.Server.ExternalURL) == "" {
		return false
	}
	return c.ReachedOverHTTPS()
}

// ReachedOverHTTPS reports whether the address this controller is reached at
// is an https one: its external URL when that is set, otherwise its own
// listener's TLS mode.
func (c *Config) ReachedOverHTTPS() bool {
	if ext := strings.TrimSpace(c.Server.ExternalURL); ext != "" {
		u, err := url.Parse(ext)
		return err == nil && strings.EqualFold(u.Scheme, "https") && u.Host != ""
	}
	return c.Server.TLS.Mode != "" && c.Server.TLS.Mode != TLSOff
}

// LikelyReachable reports whether anything other than this machine can reach
// the controller.
//
// It is deliberately broader than BindsPublicly. A loopback bind is only
// private when nothing forwards to it, and the deployment this project
// recommends -- loopback plus a reverse proxy -- is precisely the case where
// the bind address says "private" and the truth is "the internet". An external
// URL or a configured trusted proxy is the operator telling us, in the
// configuration itself, that something in front does forward to this listener.
func (c *Config) LikelyReachable() bool {
	return c.BindsPublicly() ||
		strings.TrimSpace(c.Server.ExternalURL) != "" ||
		len(c.Server.TrustedProxies) > 0
}

// BindsPublicly reports whether the listener accepts connections from off-host.
func (c *Config) BindsPublicly() bool {
	host, _, err := net.SplitHostPort(c.Server.Bind)
	if err != nil {
		host = c.Server.Bind
	}
	switch host {
	case "", "0.0.0.0", "::", "[::]", "*":
		return true
	}
	// Any other name is assumed to resolve off-host, except the ones that
	// never can.
	return !loopbackHost(host)
}

// loopbackHost reports whether a host name or address can only ever be this
// machine: a loopback IP, localhost, or a name under .localhost, which RFC 6761
// reserves for exactly that. It is the one answer to the question the bind
// address, the external URL, the allowed origins and the OIDC issuer all ask,
// so that "localhost" cannot count as local in one of them and public in
// another, as it once did between external_url and bind.
// LoopbackHost reports whether a hostname names only this machine.
//
// It is exported because the same question is asked about a backup
// destination's endpoint, which the controller warns about and this package
// cannot see: a bucket on loopback is a developer's MinIO, and one anywhere
// else over plain HTTP is credentials on somebody's network.
func LoopbackHost(host string) bool { return loopbackHost(host) }

func loopbackHost(host string) bool {
	host = strings.ToLower(strings.Trim(host, "[]"))
	if host == "localhost" || strings.HasSuffix(host, ".localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// ExternalURLValid reports whether the external URL parses as an absolute URL.
func (c *Config) ExternalURLValid() bool {
	if c.Server.ExternalURL == "" {
		return false
	}
	u, err := url.Parse(c.Server.ExternalURL)
	return err == nil && u.Scheme != "" && u.Host != ""
}

// ExternalURLIsLocal reports whether the address this controller believes it is
// reached at is one only this machine can reach.
//
// It is the question behind three separate failures, so there is one answer to
// it: GitHub cannot deliver a webhook to loopback, and a webhook URL is fixed
// when the App is created; a join command naming loopback tells the new host to
// join itself; and a "check reachability" probe made from the controller only
// proves the controller can reach itself. A loopback external URL is a
// perfectly good default for a fleet reached through an SSH tunnel -- it is not
// a misconfiguration, which is why this is a question and not a warning.
func (c *Config) ExternalURLIsLocal() bool {
	if c.Server.ExternalURL == "" {
		return false
	}
	u, err := url.Parse(c.Server.ExternalURL)
	if err != nil || u.Host == "" {
		return false
	}
	return loopbackHost(u.Hostname())
}

// applyEnv overlays this process's ZOOMIES_* environment variables.
func (c *Config) applyEnv() error { return c.applyEnvFrom(os.LookupEnv) }

// applyEnvFrom overlays the ZOOMIES_* variables of an environment, which is
// this process's for everything but a caller working out another process's
// configuration -- see Effective.
func (c *Config) applyEnvFrom(lookup func(string) (string, bool)) error {
	getenv := func(k string) string { v, _ := lookup(k); return v }
	var errs []string
	for _, s := range Settings() {
		raw, ok := lookup(s.Env)
		if !ok {
			continue
		}
		if _, err := c.SetValueString(s.Key, raw); err != nil {
			// The variable is what the operator wrote, so the variable is what
			// the message names -- not the dotted key they would have to work
			// back to.
			var se *SettingError
			if errors.As(err, &se) {
				errs = append(errs, fmt.Sprintf("%s: %s", s.Env, se.Reason))
			} else {
				errs = append(errs, fmt.Sprintf("%s: %s", s.Env, err))
			}
			continue
		}
		c.note(s.Key, SourceEnvironment)
	}

	// retention.audit has no registry row -- it is the old spelling of
	// retention.scaling_events rather than a setting of its own -- but a
	// deployment still setting the variable is honoured, and normalize says so.
	if v, ok := lookup("ZOOMIES_RETENTION_AUDIT"); ok {
		d, err := time.ParseDuration(strings.TrimSpace(v))
		if err != nil {
			errs = append(errs, fmt.Sprintf("ZOOMIES_RETENTION_AUDIT=%q is not a duration (try 30s, 5m, 2h)", v))
		} else {
			c.Retention.Audit = d
		}
	}

	// The backup remotes have no registry rows -- they are a list of
	// destinations carrying credentials rather than a setting the page edits --
	// so their environment is read here. A container deployment keeps the
	// bucket in the file and the secret key in the environment, which is the
	// whole reason this exists.
	if err := c.applyRemoteEnv(lookup); err != nil {
		errs = append(errs, err.Error())
	}

	// The bootstrap identity has no registry row either: it is an instruction
	// to an empty database, not a setting -- see Bootstrap.
	c.Bootstrap = Bootstrap{
		Admin:        strings.TrimSpace(getenv("ZOOMIES_BOOTSTRAP_ADMIN")),
		PasswordFile: strings.TrimSpace(getenv("ZOOMIES_BOOTSTRAP_PASSWORD_FILE")),
		TokenFile:    strings.TrimSpace(getenv("ZOOMIES_BOOTSTRAP_TOKEN_FILE")),
	}

	// Docker's own variable is honoured only when Zoomies' is not set. The
	// compose file hands the whole .env to the container, and an operator
	// whose daemon is rootless or remote keeps DOCKER_HOST in that file for
	// docker and compose themselves; read second, it would silently override
	// the socket the compose file names explicitly.
	if _, explicit := lookup("ZOOMIES_DOCKER_HOST"); !explicit {
		if v, ok := lookup("DOCKER_HOST"); ok {
			c.Agent.DockerHost = v
			c.note("agent.docker_host", SourceEnvironment)
		}
	}

	if len(errs) > 0 {
		return fmt.Errorf("invalid environment configuration:\n  - %s", strings.Join(errs, "\n  - "))
	}
	return nil
}

// backupRemoteEnvPrefixes are the spellings one remote's environment may take:
// ZOOMIES_BACKUP_REMOTE_BUCKET for the first, ZOOMIES_BACKUP_REMOTE_2_BUCKET
// for the second. The unnumbered form is the first remote, because a fleet
// with one offsite bucket should not have to count.
const backupRemoteEnvMax = 9

// applyRemoteEnv overlays ZOOMIES_BACKUP_REMOTE_* onto backup.remotes.
//
// A variable that names a remote the file already has fills that one in; one
// that names a remote past the end of the list appends it. So a compose file
// can hand over only the secret key of a bucket zoomies.yaml describes, or
// describe the whole destination with no file at all.
func (c *Config) applyRemoteEnv(lookup func(string) (string, bool)) error {
	var errs []string
	touched := false
	for i := 1; i <= backupRemoteEnvMax; i++ {
		prefixes := []string{fmt.Sprintf("ZOOMIES_BACKUP_REMOTE_%d_", i)}
		if i == 1 {
			prefixes = append(prefixes, "ZOOMIES_BACKUP_REMOTE_")
		}
		// Each field remembers which variable it came from, so an error names
		// the one the operator actually wrote rather than the other spelling
		// of it.
		type envField struct{ variable, value string }
		fields := map[string]envField{}
		for _, prefix := range prefixes {
			for _, name := range []string{
				"NAME", "ENDPOINT", "REGION", "BUCKET", "PREFIX",
				"ACCESS_KEY_ID", "SECRET_ACCESS_KEY", "PASSPHRASE",
				"PATH_STYLE", "KEEP", "DISABLED",
			} {
				if v, ok := lookup(prefix + name); ok {
					// The numbered spelling is read first and wins, so a file
					// that sets both is not ambiguous about which it meant.
					if _, already := fields[name]; !already {
						fields[name] = envField{variable: prefix + name, value: v}
					}
				}
			}
		}
		if len(fields) == 0 {
			continue
		}

		// A name that matches a remote the file already describes overlays
		// that one wherever it sits in the list, which is what an operator
		// who wrote the variables by name expects.
		idx := i - 1
		if name := strings.TrimSpace(fields["NAME"].value); name != "" {
			for n, existing := range c.Backup.Remotes {
				if strings.EqualFold(strings.TrimSpace(existing.Name), name) {
					idx = n
					break
				}
			}
		}
		for len(c.Backup.Remotes) <= idx {
			c.Backup.Remotes = append(c.Backup.Remotes, BackupRemote{})
		}
		r := &c.Backup.Remotes[idx]
		for name, field := range fields {
			raw := field.value
			switch name {
			case "NAME":
				r.Name = raw
			case "ENDPOINT":
				r.Endpoint = raw
			case "REGION":
				r.Region = raw
			case "BUCKET":
				r.Bucket = raw
			case "PREFIX":
				r.Prefix = raw
			case "ACCESS_KEY_ID":
				r.AccessKeyID = raw
			case "SECRET_ACCESS_KEY":
				r.SecretAccessKey = raw
			case "PASSPHRASE":
				r.Passphrase = raw
			case "PATH_STYLE":
				b, err := strconv.ParseBool(strings.TrimSpace(raw))
				if err != nil {
					errs = append(errs, fmt.Sprintf("%s=%q is not true or false", field.variable, raw))
					continue
				}
				r.PathStyle = &b
			case "KEEP":
				n, err := strconv.Atoi(strings.TrimSpace(raw))
				if err != nil || n < 0 {
					errs = append(errs, fmt.Sprintf("%s=%q is not a number of copies to keep", field.variable, raw))
					continue
				}
				r.Keep = n
			case "DISABLED":
				b, err := strconv.ParseBool(strings.TrimSpace(raw))
				if err != nil {
					errs = append(errs, fmt.Sprintf("%s=%q is not true or false", field.variable, raw))
					continue
				}
				r.Disabled = b
			}
		}
		touched = true
	}
	if touched {
		c.note("backup.remotes", SourceEnvironment)
	}
	if len(errs) > 0 {
		return errors.New(strings.Join(errs, "\n  - "))
	}
	return nil
}

// normalizeBackupRemotes tidies what the file and the environment left, and
// names the ones nobody named: the name is what the log, the problems drawer
// and the API route all address a destination by, so every remote has to have
// one whether or not an operator thought of it.
func (c *Config) normalizeBackupRemotes() {
	for i := range c.Backup.Remotes {
		r := &c.Backup.Remotes[i]
		r.Name = strings.ToLower(strings.TrimSpace(r.Name))
		if r.Name == "" {
			r.Name = "offsite"
			if i > 0 {
				r.Name = fmt.Sprintf("offsite-%d", i+1)
			}
		}
		r.Endpoint = strings.TrimRight(strings.TrimSpace(r.Endpoint), "/")
		r.Region = strings.TrimSpace(r.Region)
		r.Bucket = strings.TrimSpace(r.Bucket)
		r.Prefix = strings.Trim(strings.TrimSpace(r.Prefix), "/")
		r.AccessKeyID = strings.TrimSpace(r.AccessKeyID)
		r.SecretAccessKey = strings.TrimSpace(r.SecretAccessKey)
		if r.Keep < 0 {
			r.Keep = 0
		}
	}
}

// splitList and parseKV read the comma-separated text a list or label setting
// is stored as, from the database, from ZOOMIES_* and from `config set`.
//
// A backslash escapes the next character only when that is a comma or another
// backslash, so a value with a comma in it (NO_PROXY, an LDAP group name)
// survives the round trip through Text, while text written before escaping
// existed -- which held neither pair -- reads exactly as it always did.
func splitList(v string) []string {
	var out []string
	for _, p := range splitUnescaped(v) {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, unescapeList(p))
		}
	}
	return out
}

func parseKV(v string) (map[string]string, error) {
	out := map[string]string{}
	for _, p := range splitUnescaped(v) {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		k, val, ok := strings.Cut(p, "=")
		if !ok {
			return nil, fmt.Errorf("%q is not key=value", unescapeList(p))
		}
		out[unescapeList(strings.TrimSpace(k))] = unescapeList(strings.TrimSpace(val))
	}
	return out, nil
}

// splitUnescaped cuts on commas that are not escaped and leaves the escapes in
// place, because a label still has to be cut at its first `=` before they go.
func splitUnescaped(v string) []string {
	var out []string
	start := 0
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case '\\':
			if i+1 < len(v) && (v[i+1] == ',' || v[i+1] == '\\') {
				i++
			}
		case ',':
			out = append(out, v[start:i])
			start = i + 1
		}
	}
	return append(out, v[start:])
}

func unescapeList(v string) string {
	if !strings.Contains(v, `\`) {
		return v
	}
	var b strings.Builder
	for i := 0; i < len(v); i++ {
		if v[i] == '\\' && i+1 < len(v) && (v[i+1] == ',' || v[i+1] == '\\') {
			i++
		}
		b.WriteByte(v[i])
	}
	return b.String()
}

// escapeList is unescapeList's inverse, for Text.
func escapeList(v string) string {
	return strings.NewReplacer(`\`, `\\`, ",", `\,`).Replace(v)
}

// Normalize fills in the values that are derived from other values. It is
// exported for the settings API, which builds a candidate configuration by
// assigning into a copy and has to derive the rest of it before asking the
// validator whether the result would start.
func (c *Config) Normalize() { c.normalize() }

// readFile and decodeYAML are Load's two halves, separated so the seed importer
// can read the same file the same strict way without also applying the
// environment over it -- which is exactly what it must not do.
func readFile(path string) ([]byte, error) { return os.ReadFile(path) }

func decodeYAML(doc []byte, into *Config) error {
	dec := yaml.NewDecoder(strings.NewReader(string(doc)))
	dec.KnownFields(true)
	if err := dec.Decode(into); err != nil && !errors.Is(err, io.EOF) {
		return err
	}
	return nil
}

package config

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// Load derives security.cookie_secure from the file and the environment alone,
// because the database is not open yet. A controller whose external URL is kept
// in the database (the Settings page, or a config import) then rebuilt over the
// stored rows with the flag already decided, so its session cookies went out
// without Secure even though it was served over https -- and on a loopback bind
// behind a TLS proxy nothing warned about it.
func TestTheSecureCookieFlagIsDerivedFromTheStoredExternalURL(t *testing.T) {
	isolateEnvironment(t)
	key := testKey(t)
	https := []store.InstanceSetting{{Key: "server.external_url", Value: "https://zoomies.example.com"}}

	dir := t.TempDir()
	pinnedOff := filepath.Join(dir, "off.yaml")
	if err := os.WriteFile(pinnedOff, []byte("security:\n  cookie_secure: false\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	for _, tc := range []struct {
		name string
		file string
		env  string
		want bool
	}{
		{"nothing says, so the stored https URL decides", "", "", true},
		{"the file says false, and an operator's choice stands", pinnedOff, "", false},
		{"the environment says false, and an operator's choice stands", "", "false", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if tc.env != "" {
				t.Setenv("ZOOMIES_COOKIE_SECURE", tc.env)
			}
			cfg, err := Load(tc.file)
			if err != nil {
				t.Fatalf("Load: %v", err)
			}
			if _, err := cfg.Rebuild(https, key); err != nil {
				t.Fatalf("Rebuild: %v", err)
			}
			if got := cfg.CookieSecureValue(); got != tc.want {
				t.Errorf("CookieSecureValue() = %v, want %v", got, tc.want)
			}
		})
	}
}

package config

import (
	"encoding/base64"
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// The database layer: stored rows applied onto a configuration, and a
// configuration's values encoded back into rows.
//
// This is the layer between the file and the environment, and the one an
// administrator changes from the UI. It is applied after the store is open and
// the encryption key is loaded, which is the earliest moment a sealed value can
// be read -- and which is why the three keys that get the store open and the
// key loaded cannot themselves live here.

// ApplyStored writes stored settings onto cfg and records that they came from
// the database.
//
// A row that this build cannot use does not stop startup. A downgrade is the
// ordinary way to meet one -- an operator who set something in a newer version
// and rolled back -- and refusing to boot over a setting the older binary never
// had would turn "the new feature is not available" into "the controller is
// down". Each one becomes a finding instead, so the row is still named and
// still recoverable, and the fleet keeps running on the value underneath.
//
// It never mutates a slice or map the previous snapshot shares: every list and
// label set is rebuilt, which is what makes this safe to call inside a
// config.Live update.
func ApplyStored(cfg *Config, rows []store.InstanceSetting, key *cryptox.Key) Findings {
	var findings Findings
	var unknown, unreadable []string

	for _, row := range rows {
		s, ok := LookupSetting(row.Key)
		if !ok || !s.Stored() {
			unknown = append(unknown, row.Key)
			continue
		}

		raw := row.Value
		if s.Secret {
			opened, err := openSecret(key, row.Value)
			if err != nil {
				unreadable = append(unreadable, row.Key)
				continue
			}
			raw = opened
		}

		if _, err := cfg.SetValueString(row.Key, raw); err != nil {
			var se *SettingError
			reason := err.Error()
			if errors.As(err, &se) {
				reason = se.Reason
			}
			findings = append(findings, Finding{
				Code:     "settings.stored_invalid",
				Severity: SeverityWarning,
				Setting:  row.Key,
				Title:    fmt.Sprintf("The stored value for %s cannot be used", row.Key),
				Detail: fmt.Sprintf("It %s, so this controller is running the value underneath it instead \u2014 "+
					"whichever of the configuration file and the built-in default applies.", reason),
				Fix: fmt.Sprintf("Set %s again on the settings page, or clear it with `zoomies config unset %s`.", row.Key, row.Key),
			})
			continue
		}
		cfg.note(row.Key, SourceDatabase)
	}

	if len(unknown) > 0 {
		sort.Strings(unknown)
		findings = append(findings, Finding{
			Code:     "settings.stored_unknown",
			Severity: SeverityInfo,
			Title:    fmt.Sprintf("%s stored that this version does not have", countOf(len(unknown), "One setting is", "settings are")),
			Detail: "They are kept untouched, so a controller upgraded again picks them up where it left off: " +
				strings.Join(unknown, ", ") + ".",
			Fix: "Nothing, unless they were meant for this version \u2014 in which case check the spelling on the settings page.",
		})
	}
	if len(unreadable) > 0 {
		sort.Strings(unreadable)
		findings = append(findings, Finding{
			Code:     "settings.stored_unreadable",
			Severity: SeverityError,
			Title: fmt.Sprintf("%s sealed with a key this controller does not have",
				countOf(len(unreadable), "A stored credential is", "stored credentials are")),
			Detail: "The key this controller loaded does not open " + strings.Join(unreadable, ", ") + ". " +
				"Starting anyway would run the fleet with credentials silently missing.",
			Fix: "Restore the encryption key these were sealed with, or clear them with `zoomies config unset " + unreadable[0] + "` and set them again.",
		})
	}
	return findings
}

// EncodeStored turns a setting's value into the row that holds it, sealing it
// when the setting is a credential.
func EncodeStored(s Setting, value any, key *cryptox.Key) (store.InstanceSetting, error) {
	text := Text(s, value)
	if !s.Secret {
		return store.InstanceSetting{Key: s.Key, Value: text}, nil
	}
	if key == nil {
		return store.InstanceSetting{}, &SettingError{s.Key,
			"is a credential and there is no encryption key to seal it with; set security.encryption_key_file and restart"}
	}
	sealed, err := key.SealString(text)
	if err != nil {
		return store.InstanceSetting{}, &SettingError{s.Key, "could not be sealed: " + err.Error()}
	}
	return store.InstanceSetting{
		Key:    s.Key,
		Value:  base64.StdEncoding.EncodeToString(sealed),
		Secret: true,
	}, nil
}

// openSecret reverses EncodeStored's sealing. The base64 and the seal are two
// separate failures with the same answer -- this row was written by an instance
// holding a different key -- so they are reported as one.
func openSecret(key *cryptox.Key, value string) (string, error) {
	if strings.TrimSpace(value) == "" {
		return "", nil
	}
	if key == nil {
		return "", errors.New("no encryption key")
	}
	sealed, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		return "", err
	}
	return key.OpenString(sealed)
}

// Rebuild re-layers a running configuration over the fleet's stored settings.
//
// Order is the whole of it: the file is already in cfg, the database goes on
// top of it, and the environment goes on top of the database. The environment
// is last deliberately. It is the way back in when a stored setting has locked
// an operator out of the interface that would let them fix it -- a bind address
// nothing can reach, an external URL that breaks the login redirect -- and a
// deployment that ships its configuration as environment variables, which is
// every containerised one, keeps working across the upgrade that introduced
// this table.
//
// The cost of that choice is that a value an administrator types can be
// invisibly overridden, so it is not left invisible: Config.Source says where
// each value came from, PinnedByEnvironment lists the ones the environment is
// holding, and the settings page refuses to pretend it can change them.
//
// normalize runs last, as it does after Load, so derived values are derived
// from the values that actually won.
//
// One derived value has to be forgotten first. Load derived the secure-cookie
// flag before the database was open, from the file and the environment alone,
// and normalize only derives a flag that is unset -- so a stored https external
// URL never reached it, and a controller served over https issued cookies
// without Secure. A flag no layer chose is noted at no source, so it is safe to
// clear; one the file, the environment or a row chose keeps its source and its
// value.
func (c *Config) Rebuild(rows []store.InstanceSetting, key *cryptox.Key) (Findings, error) {
	if c.Source("security.cookie_secure") == SourceDefault {
		c.Security.CookieSecure = nil
	}
	findings := ApplyStored(c, rows, key)
	if err := c.applyEnv(); err != nil {
		return findings, err
	}
	c.normalize()
	return findings, nil
}

// Effective is the configuration a deployment runs with, worked out the way
// its controller works it out at start -- the file, then the database, then
// the environment -- for a caller that is not that controller: the installer,
// upgrading it, which has to know whether the deployment runs runners before
// it can say which mounts it needs.
//
// The database is the answer to that, as it is to every setting; asking the
// deployment's .env instead would miss everything set on the settings page.
// env is the deployment's own environment, never this process's, which is the
// upgrade's and says nothing about the service. file is empty for a container
// deployment, which keeps no zoomies.yaml.
func Effective(file string, rows []store.InstanceSetting, key *cryptox.Key, env map[string]string) (*Config, Findings, error) {
	cfg := Default()
	if file != "" {
		if err := cfg.readFile(file); err != nil {
			return nil, nil, err
		}
	}
	findings := ApplyStored(cfg, rows, key)
	lookup := func(k string) (string, bool) { v, ok := env[k]; return v, ok }
	if err := cfg.applyEnvFrom(lookup); err != nil {
		return nil, findings, err
	}
	cfg.normalize()
	return cfg, findings, nil
}

// PendingRestart lists the settings whose stored value is not what this process
// is running, because it was stored after this process started and needs a
// restart to take effect.
//
// It is the honest half of letting an administrator change a setting that
// cannot be applied live. The alternative the product used to offer was to
// refuse the edit and say "edit the file and restart", which left the operator
// to do by hand the one thing a settings page exists to do -- and left no
// record that anybody had wanted the change.
//
// A setting the environment is pinning is never pending. Its stored value will
// lose to the variable at the next start exactly as it loses now, so calling it
// "waiting for a restart" would promise a change that is never coming.
func PendingRestart(running *Config, rows []store.InstanceSetting, key *cryptox.Key) []string {
	// A copy with every layer re-applied is what the next start will look
	// like. Anything that differs from the running configuration is waiting.
	next := *running
	next.sources = running.copySources()
	if _, err := next.Rebuild(rows, key); err != nil {
		// The environment cannot have become unparseable since this process
		// read it, so there is nothing useful to say and nothing to report.
		return nil
	}

	var out []string
	for _, s := range StoredSettings() {
		if s.Live || running.Source(s.Key) == SourceEnvironment {
			continue
		}
		if !sameValue(running, &next, s.Key) {
			out = append(out, s.Key)
		}
	}
	sort.Slice(out, func(i, j int) bool { return CompareKeys(out[i], out[j]) < 0 })
	return out
}

// sameValue compares two configurations at one key, through the same text a
// row would store, so "30s" and "30s" match however each was arrived at.
func sameValue(a, b *Config, key string) bool {
	s, ok := LookupSetting(key)
	if !ok {
		return true
	}
	av, aerr := a.Value(key)
	bv, berr := b.Value(key)
	if aerr != nil || berr != nil {
		return aerr != nil && berr != nil
	}
	return Text(s, av) == Text(s, bv)
}

// countOf reads as a sentence opening rather than as a number and a noun:
// "One setting stored that this version does not have", "Three settings
// stored...". A finding's title is prose, and "1 setting" in front of a verb is
// not.
func countOf(n int, one, many string) string {
	if n == 1 {
		return one
	}
	return fmt.Sprintf("%d %s", n, many)
}

// SeedKey is the row that records the one-time import of a configuration file
// into the database. It lives in the store's own settings table rather than in
// instance_settings, because it is a fact the product keeps about itself and
// not a setting anybody may change.
const SeedKey = "config.file_imported"

// SeedFromFile returns the rows that carry a configuration file's settings into
// the database, so an instance upgraded into this design keeps running exactly
// as it did and gains a settings page that works.
//
// Only what the file actually spells is taken. A key it never mentioned is left
// alone, because the defaults are computed on the host that reads them -- the
// database path from the state directory, the agent's capacity from the number
// of cores, its name from the machine -- and freezing one host's answers into
// rows would quietly make every later host inherit them.
//
// A key the environment is pinning is taken too. The value stored is the one
// the file gave, not the one the environment is currently winning with: the
// import is a copy of the file, and writing the environment's value would turn
// a temporary override into a permanent setting the moment somebody unset the
// variable.
func SeedFromFile(cfg *Config, key *cryptox.Key) ([]store.InstanceSetting, error) {
	fromFile := &Config{path: cfg.path}
	if cfg.path == "" {
		return nil, nil
	}
	doc, err := readFile(cfg.path)
	if err != nil {
		return nil, err
	}
	if err := decodeYAML(doc, fromFile); err != nil {
		return nil, err
	}

	var rows []store.InstanceSetting
	for _, spelled := range keysIn(doc) {
		s, ok := LookupSetting(spelled)
		if !ok || !s.Stored() {
			continue
		}
		value, err := fromFile.Value(spelled)
		if err != nil {
			continue
		}
		row, err := EncodeStored(s, value, key)
		if err != nil {
			// A credential with no key to seal it stays in the file, where it
			// still works. Refusing the whole import over one of them would
			// leave an upgraded instance with no settings at all.
			continue
		}
		rows = append(rows, row)
	}
	sort.Slice(rows, func(i, j int) bool { return CompareKeys(rows[i].Key, rows[j].Key) < 0 })
	return rows, nil
}

// SeedFinding says what the import did, so an operator who upgraded finds out
// from the startup output rather than from a settings page that has quietly
// changed hands.
func SeedFinding(path string, n int) Finding {
	return Finding{
		Code:     "settings.imported_from_file",
		Severity: SeverityInfo,
		Title:    fmt.Sprintf("%s moved into this fleet's database", countOf(n, "One setting from "+path+" has", "settings from "+path+" have")),
		Detail: "Settings now live in the database, so they can be changed on the settings page and kept. " +
			"The file is still read as the layer underneath them, so nothing has changed about what this controller is running.",
		Fix: "Nothing. The file can stay as it is; a value changed on the settings page takes precedence over it from now on.",
	}
}

// SettingForEnv is the stored setting a ZOOMIES_* variable sets, if it sets
// one. Bootstrap and local settings are not returned: they cannot live in the
// database, so a variable naming one is not a setting to move there.
func SettingForEnv(name string) (Setting, bool) {
	for _, s := range registry {
		if s.Env == name && s.Stored() {
			return s, true
		}
	}
	return Setting{}, false
}

// EnvImport is one variable ImportEnvironment turned into a row.
type EnvImport struct {
	Env     string
	Setting Setting
	// Text is the value as the settings page shows it; empty for a secret.
	Text string
}

// ImportEnvironment turns the ZOOMIES_* variables a deployment was started
// with into the rows that hold the same settings in its database.
//
// It is how a container deployment's settings leave its .env. Every variable
// is parsed as the controller would parse it, and one that does not parse
// stops the whole import: storing the rest would leave the deployment half in
// the database and half in its environment, with the half that failed the
// one nobody notices. Variables that are not stored settings -- the
// encryption key, the database path, Compose's own -- are returned in left,
// so a caller can say they stay where they are.
func ImportEnvironment(vars map[string]string, key *cryptox.Key) (rows []store.InstanceSetting, imported []EnvImport, left []string, err error) {
	names := make([]string, 0, len(vars))
	for name := range vars {
		names = append(names, name)
	}
	sort.Strings(names)

	var problems []string
	for _, name := range names {
		s, ok := SettingForEnv(name)
		if !ok {
			if strings.HasPrefix(name, "ZOOMIES_") {
				left = append(left, name)
			}
			continue
		}
		candidate := Default()
		if _, err := candidate.SetValueString(s.Key, vars[name]); err != nil {
			var se *SettingError
			if errors.As(err, &se) {
				problems = append(problems, fmt.Sprintf("%s: %s", name, se.Reason))
			} else {
				problems = append(problems, fmt.Sprintf("%s: %s", name, err))
			}
			continue
		}
		value, err := candidate.Value(s.Key)
		if err != nil {
			problems = append(problems, fmt.Sprintf("%s: %s", name, err))
			continue
		}
		row, err := EncodeStored(s, value, key)
		if err != nil {
			problems = append(problems, fmt.Sprintf("%s: %s", name, err))
			continue
		}
		rows = append(rows, row)
		text := ""
		if !s.Secret {
			text = Text(s, value)
		}
		imported = append(imported, EnvImport{Env: name, Setting: s, Text: text})
	}
	if len(problems) > 0 {
		return nil, nil, left, fmt.Errorf("nothing was stored, because these would not be what the controller runs with:\n  - %s",
			strings.Join(problems, "\n  - "))
	}
	sort.Slice(rows, func(i, j int) bool { return CompareKeys(rows[i].Key, rows[j].Key) < 0 })
	return rows, imported, left, nil
}

package config

import (
	"os"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// isolateEnvironment removes every ZOOMIES_* variable for the duration of a
// test, so a test about the layers is not also a test of whatever the machine
// running it happens to export.
//
// This repository builds itself on its own runners, and those set
// ZOOMIES_DOCKER_HOST and ZOOMIES_RUNNER_VERSION -- so a test asserting which
// settings the environment is holding passed on every laptop and failed in the
// one place it had to pass.
func isolateEnvironment(t *testing.T) {
	t.Helper()
	for _, entry := range os.Environ() {
		key, _, _ := strings.Cut(entry, "=")
		if !strings.HasPrefix(key, "ZOOMIES_") && key != "DOCKER_HOST" {
			continue
		}
		was := os.Getenv(key)
		if err := os.Unsetenv(key); err != nil {
			t.Fatalf("unsetting %s: %v", key, err)
		}
		t.Cleanup(func() { _ = os.Setenv(key, was) })
	}
}

func testKey(t *testing.T) *cryptox.Key {
	t.Helper()
	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	return key
}

// The four layers stack in one order, and the order is the whole design.
//
// The environment is last on purpose: it is the way back in when a stored
// setting has locked somebody out of the page that would fix it, and it is what
// keeps every containerised deployment working across the change that
// introduced the database. The cost is that a value an administrator typed can
// be invisibly overridden, which is why the layer each value came from is
// recorded rather than left to be worked out.
func TestTheEnvironmentBeatsTheDatabaseAndTheDatabaseBeatsTheFile(t *testing.T) {
	isolateEnvironment(t)
	key := testKey(t)
	cfg := Default()
	cfg.Scheduler.Interval = 11
	cfg.note("scheduler.interval", SourceFile)
	cfg.Server.Bind = "10.0.0.1:8080"
	cfg.note("server.bind", SourceFile)

	t.Setenv("ZOOMIES_BIND", "127.0.0.1:7000")
	rows := []store.InstanceSetting{
		{Key: "scheduler.interval", Value: "22s"},
		{Key: "server.bind", Value: "0.0.0.0:9090"},
	}
	if _, err := cfg.Rebuild(rows, key); err != nil {
		t.Fatalf("Rebuild: %v", err)
	}

	if got := cfg.Scheduler.Interval.String(); got != "22s" {
		t.Errorf("the database should beat the file: scheduler.interval = %s", got)
	}
	if cfg.Source("scheduler.interval") != SourceDatabase {
		t.Errorf("scheduler.interval came from %s", cfg.Source("scheduler.interval"))
	}
	if cfg.Server.Bind != "127.0.0.1:7000" {
		t.Errorf("the environment should beat the database: server.bind = %s", cfg.Server.Bind)
	}
	if cfg.Source("server.bind") != SourceEnvironment {
		t.Errorf("server.bind came from %s", cfg.Source("server.bind"))
	}

	pinned := cfg.PinnedByEnvironment()
	if len(pinned) != 1 || pinned[0].Key != "server.bind" {
		t.Errorf("PinnedByEnvironment = %v, want just server.bind", pinned)
	}
}

// A stored row this build cannot use does not stop the controller.
//
// A downgrade is the ordinary way to meet one -- somebody set a value in a
// newer version and rolled back -- and refusing to boot over a setting the
// older binary never had turns "that feature is not available" into "the
// controller is down". The row is named in a finding instead, and the layer
// underneath it decides.
func TestAStoredValueThisBuildCannotUseLeavesTheLayerBeneathIt(t *testing.T) {
	key := testKey(t)
	cfg := Default()
	want := cfg.Retention.Jobs

	findings := ApplyStored(cfg, []store.InstanceSetting{
		{Key: "retention.jobs", Value: "forever"},
		{Key: "a.setting.from.the.future", Value: "1"},
	}, key)

	if cfg.Retention.Jobs != want {
		t.Errorf("retention.jobs = %s, want the default %s left in place", cfg.Retention.Jobs, want)
	}
	codes := map[string]bool{}
	for _, f := range findings {
		codes[f.Code] = true
	}
	if !codes["settings.stored_invalid"] || !codes["settings.stored_unknown"] {
		t.Errorf("findings = %v, want both an invalid and an unknown row reported", codes)
	}
	// Neither stops startup: an unusable row is a thing to fix, not a reason to
	// take the fleet down.
	if err := findings.Err(); err != nil {
		t.Errorf("a bad stored row refused to start: %v", err)
	}
}

// A credential is sealed on the way in and opened on the way out, so a copy of
// the database taken without the key holds nothing usable.
func TestACredentialIsSealedInTheDatabase(t *testing.T) {
	key := testKey(t)
	s, ok := LookupSetting("capacity_demand.signing_secret")
	if !ok {
		t.Fatal("no capacity_demand.signing_secret")
	}

	row, err := EncodeStored(s, "hunter2", key)
	if err != nil {
		t.Fatalf("EncodeStored: %v", err)
	}
	if !row.Secret {
		t.Error("the row is not marked as holding a secret")
	}
	if strings.Contains(row.Value, "hunter2") {
		t.Errorf("the secret is in the row in the clear: %q", row.Value)
	}

	cfg := Default()
	if f := ApplyStored(cfg, []store.InstanceSetting{row}, key); len(f) > 0 {
		t.Fatalf("opening a sealed row produced findings: %v", f)
	}
	if cfg.CapacityDemand.SigningSecret != "hunter2" {
		t.Errorf("the secret did not come back: %q", cfg.CapacityDemand.SigningSecret)
	}

	// And a different key does not quietly produce an instance running without
	// the credential it thinks it has.
	other := testKey(t)
	findings := ApplyStored(Default(), []store.InstanceSetting{row}, other)
	if findings.Err() == nil {
		t.Error("a credential sealed with another key did not stop startup")
	}
}

// A setting the running process cannot apply is reported as waiting rather than
// pretended about. A setting the environment is pinning never waits, because
// its stored value is not coming into force at the next start either.
func TestOnlyASettingThatWillActuallyChangeIsPending(t *testing.T) {
	isolateEnvironment(t)
	key := testKey(t)
	running := Default()
	t.Setenv("ZOOMIES_AGENT_CAPACITY", "4")
	if _, err := running.Rebuild(nil, key); err != nil {
		t.Fatalf("Rebuild: %v", err)
	}

	rows := []store.InstanceSetting{
		{Key: "server.bind", Value: "0.0.0.0:9090"}, // waits for a restart
		{Key: "agent.capacity", Value: "8"},         // pinned by the environment
		{Key: "scheduler.interval", Value: "30s"},   // live, so never pending
	}
	pending := PendingRestart(running, rows, key)
	if len(pending) != 1 || pending[0] != "server.bind" {
		t.Errorf("PendingRestart = %v, want just server.bind", pending)
	}
}

// The importer takes what the file spells and nothing else.
//
// A key the file never mentioned is left alone because the defaults are worked
// out on the host that reads them -- the database path from its state
// directory, the agent's capacity from its cores -- so a row claiming to be
// "the default" would freeze one machine's answers for every machine after it.
func TestTheImporterTakesOnlyWhatTheFileSpells(t *testing.T) {
	isolateEnvironment(t)
	dir := t.TempDir()
	path := dir + "/zoomies.yaml"
	if err := writeFileForTest(path, `
server:
  external_url: https://ci.example.com
scheduler:
  interval: 25s
agent:
  labels:
    tier: build
`); err != nil {
		t.Fatal(err)
	}

	cfg, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	rows, err := SeedFromFile(cfg, testKey(t))
	if err != nil {
		t.Fatalf("SeedFromFile: %v", err)
	}

	got := map[string]string{}
	for _, row := range rows {
		got[row.Key] = row.Value
	}
	want := map[string]string{
		"server.external_url": "https://ci.example.com",
		"scheduler.interval":  "25s",
		"agent.labels":        "tier=build",
	}
	if len(got) != len(want) {
		t.Errorf("imported %d settings, want %d: %v", len(got), len(want), got)
	}
	for key, value := range want {
		if got[key] != value {
			t.Errorf("%s imported as %q, want %q", key, got[key], value)
		}
	}
	// The bootstrap keys stay in the file, where they have to be.
	if _, taken := got["database.path"]; taken {
		t.Error("database.path was imported into the database it names")
	}
}

// The file a fresh install writes says only what that host needs before it can
// read the rest. It used to marshal all eighty-nine settings, which -- now that
// a key spelled in the file is a key the file is in charge of -- would hand the
// whole configuration back to a text editor on the day it was installed.
func TestTheWrittenFileSaysOnlyWhatItHasTo(t *testing.T) {
	path := t.TempDir() + "/zoomies.yaml"
	cfg := Default()
	cfg.Server.ExternalURL = "https://ci.example.com"
	if err := cfg.Save(path); err != nil {
		t.Fatalf("Save: %v", err)
	}

	doc, err := readFile(path)
	if err != nil {
		t.Fatal(err)
	}
	keys := keysIn(doc)
	for _, want := range []string{"database.path", "security.encryption_key_file", "server.external_url"} {
		if !contains(keys, want) {
			t.Errorf("the written file does not spell %s: %v", want, keys)
		}
	}
	for _, unwanted := range []string{"scheduler.interval", "retention.jobs", "agent.capacity", "log.level"} {
		if contains(keys, unwanted) {
			t.Errorf("the written file pins %s, which nobody chose", unwanted)
		}
	}

	// And it still parses, which is the only hard constraint on its shape.
	back, err := Load(path)
	if err != nil {
		t.Fatalf("the written file does not load: %v", err)
	}
	if back.Server.ExternalURL != "https://ci.example.com" {
		t.Errorf("the round trip lost the external URL: %q", back.Server.ExternalURL)
	}
}

// agent.work_dir's default is derived from the euid of whatever process asks
// for it: `zoomies agent join` always runs as root, and root's default happens
// to be the same path the join chose here. That must not be reason enough to
// drop it from the file -- the service the join installs almost always runs
// as an unprivileged user, whose own default for the same key is a different
// path, and a value missing from the file is recomputed from that default
// rather than left alone.
func TestAgentWorkDirIsWrittenEvenWhenItMatchesTheFreshDefault(t *testing.T) {
	path := t.TempDir() + "/zoomies.yaml"
	cfg := Default()
	cfg.Agent.Embedded = false
	cfg.Agent.WorkDir = Default().Agent.WorkDir // exactly what sparse() compares against
	if err := cfg.Save(path); err != nil {
		t.Fatalf("Save: %v", err)
	}

	doc, err := readFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !contains(keysIn(doc), "agent.work_dir") {
		t.Fatalf("the written file does not spell agent.work_dir, though nothing else names it: %v", keysIn(doc))
	}

	// A load that computes a different default for the key -- standing in for
	// the unprivileged service user -- must still recover the pinned value.
	back, err := Load(path)
	if err != nil {
		t.Fatalf("the written file does not load: %v", err)
	}
	if back.Agent.WorkDir != cfg.Agent.WorkDir {
		t.Errorf("agent.work_dir round-tripped as %q, want %q", back.Agent.WorkDir, cfg.Agent.WorkDir)
	}
}

func contains(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

// writeFileForTest writes a configuration file, so a test can say what an
// operator's file holds rather than build one field by field.
func writeFileForTest(path, body string) error {
	return os.WriteFile(path, []byte(strings.TrimLeft(body, "\n")), 0o600)
}

// The old name for the scaling-history window still works, and no longer eats a
// value somebody typed on the settings page.
//
// normalize runs last, after the database layer, so the legacy carry-over used
// to overwrite a stored value unconditionally: the administrator got a 200, an
// audit row and a stored setting, and the controller quietly ran the number in
// a years-old file. A key in the file still beats the built-in default, which
// is what honouring it at all means.
func TestTheLegacyRetentionKeyDoesNotEatAStoredValue(t *testing.T) {
	isolateEnvironment(t)
	key := testKey(t)

	fromFileOnly := Default()
	fromFileOnly.Retention.Audit = 48 * time.Hour
	if _, err := fromFileOnly.Rebuild(nil, key); err != nil {
		t.Fatalf("Rebuild: %v", err)
	}
	if fromFileOnly.Retention.ScalingEvents != 48*time.Hour {
		t.Errorf("the legacy key stopped working: %s", fromFileOnly.Retention.ScalingEvents)
	}

	stored := Default()
	stored.Retention.Audit = 48 * time.Hour
	if _, err := stored.Rebuild([]store.InstanceSetting{
		{Key: "retention.scaling_events", Value: "72h"},
	}, key); err != nil {
		t.Fatalf("Rebuild: %v", err)
	}
	if stored.Retention.ScalingEvents != 72*time.Hour {
		t.Errorf("a stored value was eaten by the legacy key: %s", stored.Retention.ScalingEvents)
	}
	// And the finding asking for the rename is still raised, because the file's
	// key is still there and still wants removing.
	var asked bool
	for _, f := range stored.Validate() {
		if f.Code == "retention.audit_renamed" {
			asked = true
		}
	}
	if !asked {
		t.Error("nothing asked the operator to remove the old key")
	}
}

package config

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The installer upgrading a deployment has to know what that deployment runs,
// and the settings page writes to its database -- so an answer read from the
// file or the .env alone is wrong the moment an operator has used the page.
// The layers stack as the controller stacks them, and the environment
// consulted is the deployment's, never the process asking.
func TestEffectiveLayersTheDatabaseOverTheFileAndTheDeploymentsEnvironmentOverBoth(t *testing.T) {
	file := filepath.Join(t.TempDir(), "zoomies.yaml")
	if err := os.WriteFile(file, []byte("agent:\n  embedded: true\n  capacity: 3\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	rows := []store.InstanceSetting{{Key: "agent.embedded", Value: "false"}, {Key: "agent.capacity", Value: "6"}}

	cfg, _, err := Effective(file, rows, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Agent.Embedded || cfg.Agent.Capacity != 6 {
		t.Errorf("embedded=%v capacity=%d, want the database's false and 6 over the file", cfg.Agent.Embedded, cfg.Agent.Capacity)
	}

	cfg, _, err = Effective(file, rows, nil, map[string]string{"ZOOMIES_AGENT_CAPACITY": "8"})
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Agent.Capacity != 8 || cfg.Agent.Embedded {
		t.Errorf("capacity=%d embedded=%v, want the deployment's environment to win for what it sets and nothing else", cfg.Agent.Capacity, cfg.Agent.Embedded)
	}

	// The upgrade's own environment is not the service's.
	t.Setenv("ZOOMIES_AGENT_EMBEDDED", "true")
	cfg, _, err = Effective("", rows, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Agent.Embedded {
		t.Error("Effective read the calling process's environment as the deployment's")
	}
}

package config

import (
	"fmt"
	"net/netip"
	"net/url"
	"strings"
)

// AllowPrivateEgressSetting is the key that lets the addresses below be dialled,
// named once because every refusal has to quote it.
const AllowPrivateEgressSetting = "security.allow_private_egress"

// The ranges an outbound URL may not name. Go's netip answers loopback,
// link-local and RFC 1918 / ULA itself; these are the neighbours it has no
// predicate for, and each is somewhere a request from this process lands on
// infrastructure nobody meant to hand to a form field.
var (
	thisNetwork  = netip.MustParsePrefix("0.0.0.0/8")      // "this host on this network": Linux dials 0.0.0.0 as loopback
	sharedCGNAT  = netip.MustParsePrefix("100.64.0.0/10")  // carrier-grade NAT, and the range overlay networks hand out
	benchmarking = netip.MustParsePrefix("198.18.0.0/15")  // reserved for benchmarking, used as a private range in practice
	reservedV4   = netip.MustParsePrefix("240.0.0.0/4")    // reserved, including the limited broadcast address
	v4Compatible = netip.MustParsePrefix("::/96")          // deprecated IPv4-compatible IPv6, :: and ::1 among them
	siteLocal    = netip.MustParsePrefix("fec0::/10")      // deprecated site-local, still routed privately by some stacks
	nat64        = netip.MustParsePrefix("64:ff9b::/96")   // well-known NAT64: the last 32 bits are the IPv4 destination
	nat64Local   = netip.MustParsePrefix("64:ff9b:1::/48") // local-use NAT64, same embedding
	sixToFour    = netip.MustParsePrefix("2002::/16")      // 6to4: bits 16-48 are the IPv4 destination
)

// loopbackNames are host names that resolve to this machine on any system
// that has an /etc/hosts, or that a cloud resolves to its metadata service.
// They are refused as names because the check below never resolves anything.
var loopbackNames = map[string]string{
	"localhost":                "this machine",
	"localhost.localdomain":    "this machine",
	"ip6-localhost":            "this machine",
	"ip6-loopback":             "this machine",
	"metadata.google.internal": "the cloud metadata service",
}

// CheckOutboundURL refuses a URL this process would dial on an operator's
// behalf when it names this machine, its link-local neighbourhood or a private
// network, and returns nil when it does not or when allowPrivate is set.
//
// It exists because a setting that holds a URL is a setting that makes the
// controller send a request wherever it points. An administrator who may set
// oidc.issuer may otherwise point it at 169.254.169.254 and read the cloud
// credentials of the machine the controller runs on out of the error message,
// or at a service on the LAN that trusts anything from inside it. Those are
// the platform's resources, not the fleet's, which is why the switch that
// permits them is platform-scoped.
//
// The check reads the address it is given and resolves nothing. A validator
// cannot resolve DNS honestly: the answer at startup need not be the answer at
// the next request, and a name the operator does not control can be pointed at
// 10.0.0.1 afterwards. So an IP literal and the handful of names that can only
// be local are refused, and any other host name is admitted on trust.
// docs/security.md says so rather than letting this read as a network policy.
//
// setting names the key being checked, so the finding points at the value to
// change as well as at the switch that would allow it. The finding is an
// error, which is what a write through the API refuses with; the validator
// lowers it to a warning, because a value in the file is the process owner's
// and an upgrade must not stop an install that works.
func CheckOutboundURL(setting, raw string, allowPrivate bool) *Finding {
	if allowPrivate {
		return nil
	}
	host, ok := outboundHost(raw)
	if !ok {
		// Not a URL at all is a different mistake, and each caller already
		// has its own finding for it.
		return nil
	}
	what := privateTarget(host)
	if what == "" {
		return nil
	}
	return &Finding{
		Code:     "egress.private_target",
		Severity: SeverityError,
		Setting:  setting,
		Title:    fmt.Sprintf("%s points at %s, which is %s", setting, host, what),
		Detail: "this controller would send a request there on a configuration's say-so. An address on this machine, its " +
			"link-local network or a private range reaches services that trust whatever is inside the network -- the " +
			"cloud metadata service, an admin port bound to loopback, the LAN -- and none of them are the fleet's to reach.",
		Fix: fmt.Sprintf("use the service's public address; or, if it really does live on a network you own (an identity "+
			"provider or Enterprise Server on the LAN, a hypervisor beside this host), set %s to true.", AllowPrivateEgressSetting),
	}
}

// outboundHost pulls the host out of what an operator typed, normalised the
// way a dialler will read it. A bare host:port gets a scheme first, because
// url.Parse would otherwise read "10.0.0.5:8006" as a scheme and a path and
// the check would see no host at all -- and the Proxmox driver accepts
// exactly that spelling.
func outboundHost(raw string) (string, bool) {
	s := strings.TrimSpace(raw)
	if s == "" {
		return "", false
	}
	if !strings.Contains(s, "://") {
		s = "https://" + strings.TrimPrefix(s, "//")
	}
	u, err := url.Parse(s)
	if err != nil {
		return "", false
	}
	host := strings.ToLower(u.Hostname())
	// A trailing dot is the fully qualified spelling of the same name, and
	// "localhost." resolves exactly where "localhost" does.
	host = strings.TrimSuffix(host, ".")
	if host == "" {
		return "", false
	}
	return host, true
}

// privateTarget says what host is when it is somewhere an outbound request
// must not go, and "" when it is a public address or a host name this check
// cannot see through.
func privateTarget(host string) string {
	if what, ok := loopbackNames[host]; ok {
		return what
	}
	if strings.HasSuffix(host, ".localhost") {
		// RFC 6761 reserves the whole of .localhost for this machine.
		return "this machine"
	}
	addr, err := netip.ParseAddr(host)
	if err != nil {
		if numericHost(host) {
			// 2130706433, 0x7f000001 and 127.1 are all 127.0.0.1 to a URL
			// parser that follows the WHATWG rules and to C's inet_aton, and
			// netip reads none of them. Nothing public is written like this,
			// so an address this check cannot read is refused rather than
			// waved through as though it were a name.
			return "an IP address written in a form this check does not read"
		}
		return ""
	}
	return addressTarget(addr.WithZone(""))
}

// PrivateAddress says what an address is when it is somewhere an outbound
// request must not go, and "" when it is public. It is the same judgement
// CheckOutboundURL makes of a literal, offered for the dialler's side: code
// that resolves a name and checks the address it is about to connect to
// must not keep a second, shorter list of ranges that drifts from this one.
func PrivateAddress(addr netip.Addr) string {
	return addressTarget(addr.WithZone(""))
}

// addressTarget classifies one IP address.
func addressTarget(addr netip.Addr) string {
	// ::ffff:10.0.0.1 is 10.0.0.1 on the wire; judge the address it carries.
	addr = addr.Unmap()
	switch {
	case addr.IsUnspecified() || (addr.Is4() && thisNetwork.Contains(addr)):
		return "the unspecified address, which reaches this machine"
	case addr.IsLoopback():
		return "a loopback address on this machine"
	case addr.IsLinkLocalUnicast():
		if addr == netip.AddrFrom4([4]byte{169, 254, 169, 254}) {
			return "the cloud metadata service's link-local address"
		}
		return "a link-local address"
	case addr.IsPrivate():
		return "a private-network address"
	case addr.Is4() && sharedCGNAT.Contains(addr):
		return "a carrier-grade NAT (100.64.0.0/10) address"
	case addr.Is4() && benchmarking.Contains(addr):
		return "an address in the reserved benchmarking range"
	case addr.Is4() && reservedV4.Contains(addr):
		return "a reserved or broadcast address"
	case addr.IsMulticast():
		return "a multicast address, which is not one host"
	case addr.Is6() && v4Compatible.Contains(addr):
		return "a deprecated IPv4-compatible address"
	case addr.Is6() && siteLocal.Contains(addr):
		return "a site-local address"
	case addr.Is6() && (nat64.Contains(addr) || nat64Local.Contains(addr)):
		b := addr.As16()
		if what := addressTarget(netip.AddrFrom4([4]byte{b[12], b[13], b[14], b[15]})); what != "" {
			return what + " behind a NAT64 prefix"
		}
	case addr.Is6() && sixToFour.Contains(addr):
		b := addr.As16()
		if what := addressTarget(netip.AddrFrom4([4]byte{b[2], b[3], b[4], b[5]})); what != "" {
			return what + " inside a 6to4 address"
		}
	}
	return ""
}

// numericHost reports whether a host that did not parse as an address is
// nonetheless one: its last label is a number, decimal, octal or 0x-hex. A
// DNS name's top-level label is never numeric, which is the rule the WHATWG
// URL standard uses to decide a host is IPv4.
func numericHost(host string) bool {
	last := host[strings.LastIndexByte(host, '.')+1:]
	if last == "" {
		return false
	}
	digits := last
	if strings.HasPrefix(last, "0x") {
		digits = last[2:]
		for _, r := range digits {
			if !strings.ContainsRune("0123456789abcdef", r) {
				return false
			}
		}
		return true
	}
	for _, r := range digits {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// OutboundURL is one setting whose value this process dials.
type OutboundURL struct {
	Setting string
	Value   string
}

// OutboundURLs lists the settings the controller sends requests to, so the
// validator and the API's settings write ask about the same ones. An issuer
// is listed only while single sign-on is on, because nothing dials it
// otherwise and a draft value should not be refused or warned about.
func (c *Config) OutboundURLs() []OutboundURL {
	out := []OutboundURL{
		{"github.api_base_url", c.GitHub.APIBaseURL},
		{"capacity_demand.destination_url", c.CapacityDemand.DestinationURL},
		{"agent.runner_download_url", c.Agent.RunnerDownloadURL},
	}
	if c.OIDC.Enabled {
		out = append(out, OutboundURL{"oidc.issuer", c.OIDC.Issuer})
	}
	return out
}

package config

import (
	"strings"
	"testing"
)

// A wrong list here is a hole: every address below is somewhere a request
// from the controller reaches this machine or a network behind it, and each
// is written the way someone probing for one would write it.
func TestAnOutboundURLNamingThisMachineOrAPrivateNetworkIsRefused(t *testing.T) {
	for _, raw := range []string{
		// Loopback, both families, and the names that can only be local.
		"http://127.0.0.1:8080", "https://127.8.9.10", "http://[::1]:9000",
		"http://localhost", "https://LOCALHOST:443", "http://localhost.", "http://idp.localhost",
		"http://localhost.localdomain", "http://ip6-localhost",
		// Unspecified, which Linux dials as loopback.
		"http://0.0.0.0:8080", "http://0.1.2.3", "http://[::]:80",
		// Link-local, and the metadata service by address and by name.
		"http://169.254.169.254/latest/meta-data/", "http://169.254.1.1", "http://[fe80::1]",
		"http://[fe80::1%25eth0]:8080", "http://metadata.google.internal",
		// RFC 1918, CGNAT and ULA (fd00:ec2::254 is a cloud metadata address).
		"https://10.0.0.1", "https://172.16.0.1", "https://172.31.255.255", "https://192.168.1.20:8006",
		"https://100.64.0.1", "https://100.127.255.254", "https://[fc00::1]", "https://[fd00:ec2::254]",
		// IPv4 inside IPv6: mapped, compatible, NAT64 and 6to4.
		"http://[::ffff:10.0.0.1]", "http://[::ffff:127.0.0.1]", "http://[::ffff:169.254.169.254]",
		"http://[::ffff:100.64.0.1]", "http://[::ffff:0.1.2.3]",
		"http://[::127.0.0.1]", "http://[64:ff9b::a00:1]", "http://[2002:a00:1::]",
		// Deprecated site-local, reserved, broadcast and multicast.
		"http://[fec0::1]", "http://240.0.0.1", "http://255.255.255.255", "http://224.0.0.1", "http://[ff02::1]",
		"http://198.18.0.1",
		// Addresses in spellings netip does not read but other parsers do.
		"http://2130706433", "http://0x7f000001", "http://127.1", "http://0177.0.0.1",
		// A bare host and port, which the Proxmox driver accepts, and a
		// user-info prefix that does not change where the request goes.
		"10.0.0.5:8006", "https://public.example.com@10.0.0.1/",
	} {
		f := CheckOutboundURL("oidc.issuer", raw, false)
		if f == nil {
			t.Errorf("%s was admitted", raw)
			continue
		}
		if f.Code != "egress.private_target" || f.Severity != SeverityError || f.Setting != "oidc.issuer" {
			t.Errorf("%s: got %s/%s on %q, want an egress.private_target error on oidc.issuer", raw, f.Code, f.Severity, f.Setting)
		}
		if !strings.Contains(f.Fix, "security.allow_private_egress") {
			t.Errorf("%s: the fix does not name the setting that would allow it: %q", raw, f.Fix)
		}
	}
}

// The guard is worth nothing if it refuses the ordinary case, so the public
// internet -- including addresses that sit just outside each private range --
// and host names it cannot see through are admitted.
func TestAnOutboundURLOnThePublicInternetIsAdmitted(t *testing.T) {
	for _, raw := range []string{
		"https://api.github.com", "https://ghes.example.com/api/v3", "https://login.example.org/realms/x",
		"https://8.8.8.8", "https://172.15.255.255", "https://172.32.0.1", "https://100.63.255.255",
		"https://100.128.0.1", "https://169.253.255.255", "https://11.0.0.1", "https://[2001:db8::1]",
		"https://[2606:4700::1111]", "https://[::ffff:8.8.8.8]", "https://[64:ff9b::808:808]",
		"https://[2002:808:808::]",
		// A name is not resolved, so one that merely contains a number is a
		// name: the check reads, it does not guess.
		"https://10.example.com", "https://s3.eu-west-2.amazonaws.com", "https://host-127-0-0-1.example",
		// Nothing to check: each caller has its own finding for these.
		"", "   ",
	} {
		if f := CheckOutboundURL("oidc.issuer", raw, false); f != nil {
			t.Errorf("%q was refused: %s", raw, f.Title)
		}
	}
}

// On a single-team instance whose identity provider is on the LAN, the one
// key is the whole answer.
func TestAllowingPrivateEgressAdmitsEveryPrivateAddress(t *testing.T) {
	for _, raw := range []string{"https://10.0.0.1", "http://127.0.0.1:5556", "http://169.254.169.254"} {
		if f := CheckOutboundURL("oidc.issuer", raw, true); f != nil {
			t.Errorf("%s was refused with the setting on: %s", raw, f.Title)
		}
	}
}

// An install that has talked to a LAN identity provider since before the
// guard existed must still start after an upgrade: the file is the process
// owner's, so the validator warns, naming the setting and the key, and never
// errs. The refusal belongs to writes through the API.
func TestAPrivateRangeIssuerInTheFileWarnsAndNeverStopsStartup(t *testing.T) {
	c := Default()
	c.OIDC.Enabled = true
	c.OIDC.Issuer = "https://192.168.10.4/realms/fleet"
	c.OIDC.ClientID = "zoomies"
	c.Server.ExternalURL = "https://zoomies.example.com"

	fs := c.Validate()
	if errs := fs.Errors(); len(errs) != 0 {
		t.Fatalf("a LAN issuer stopped startup: %v", errs)
	}
	f := findingFor(fs, "egress.private_target")
	if f == nil {
		t.Fatal("a private-range issuer was not warned about")
	}
	if f.Severity != SeverityWarning || f.Setting != "oidc.issuer" || !strings.Contains(f.Title, "192.168.10.4") {
		t.Errorf("the warning does not name the issuer: %+v", *f)
	}
	if !strings.Contains(f.Fix, "security.allow_private_egress") {
		t.Errorf("the warning does not name the setting that quiets it: %q", f.Fix)
	}

	c.Security.AllowPrivateEgress = true
	if f := findingFor(c.Validate(), "egress.private_target"); f != nil {
		t.Errorf("the setting did not admit the issuer: %s", f.Title)
	}
}

// The switch removes the only guard between an administrator's typed URL and
// this machine's neighbourhood, so a controller running with it on must say
// so where an operator looks -- and stay quiet with it off, or the warning
// means nothing. It never stops startup: a LAN install that needs it is the
// expected case, and the finding is there to make the choice visible.
func TestAllowingPrivateEgressIsNamedByAWarningAndNeverStopsStartup(t *testing.T) {
	c := Default()
	if f := findingFor(c.Validate(), "egress.private_allowed"); f != nil {
		t.Fatalf("the default configuration raised %s", f.Code)
	}

	c.Security.AllowPrivateEgress = true
	fs := c.Validate()
	if errs := fs.Errors(); len(errs) != 0 {
		t.Fatalf("the switch stopped startup: %v", errs)
	}
	f := findingFor(fs, "egress.private_allowed")
	if f == nil {
		t.Fatal("turning the switch on raised no finding")
	}
	if f.Severity != SeverityWarning || f.Setting != AllowPrivateEgressSetting {
		t.Errorf("the finding is not a warning on %s: %+v", AllowPrivateEgressSetting, *f)
	}
	if !strings.Contains(f.Detail, "169.254.169.254") || f.Fix == "" {
		t.Errorf("the finding does not say what is accepted or what to do: %+v", *f)
	}
}

// Each of the settings the controller dials is checked, as a warning, and an
// issuer that is switched off is not: nothing dials it.
func TestEveryOutboundSettingIsCheckedByTheValidator(t *testing.T) {
	for _, tc := range []struct {
		setting string
		set     func(c *Config)
	}{
		{"github.api_base_url", func(c *Config) { c.GitHub.APIBaseURL = "http://10.1.2.3/api/v3" }},
		{"capacity_demand.destination_url", func(c *Config) { c.CapacityDemand.DestinationURL = "http://169.254.169.254/" }},
		{"agent.runner_download_url", func(c *Config) { c.Agent.RunnerDownloadURL = "http://[::1]:8000/runner" }},
		{"oidc.issuer", func(c *Config) { c.OIDC.Enabled = true; c.OIDC.Issuer = "http://localhost:5556" }},
		{"backup.remotes", func(c *Config) {
			c.Backup.Remotes = []BackupRemote{{Name: "minio", Endpoint: "http://127.0.0.1:9000", Bucket: "b"}}
		}},
	} {
		t.Run(tc.setting, func(t *testing.T) {
			c := Default()
			tc.set(c)
			f := findingFor(c.Validate(), "egress.private_target")
			if f == nil || f.Setting != tc.setting || f.Severity != SeverityWarning {
				t.Fatalf("got %+v, want an egress.private_target warning on %s", f, tc.setting)
			}
		})
	}

	c := Default()
	c.OIDC.Issuer = "http://localhost:5556"
	if f := findingFor(c.Validate(), "egress.private_target"); f != nil {
		t.Errorf("an issuer nothing dials was warned about: %s", f.Title)
	}
}

// A backup remote is one entry in a list, so its refusal has to say which.
func TestAPrivateBackupRemoteIsNamedInItsRefusal(t *testing.T) {
	c := Default()
	c.Backup.Remotes = []BackupRemote{{Name: "minio", Endpoint: "http://192.168.1.9:9000", Bucket: "b"}}
	f := findingFor(c.Validate(), "egress.private_target")
	if f == nil || !strings.Contains(f.Title, "minio") || !strings.Contains(f.Title, "192.168.1.9") {
		t.Fatalf("the refusal does not name the remote and its address: %+v", f)
	}
}

// Platform-scoped, like everything that changes what the process dials from
// its own machine, and reachable from the environment like every key.
func TestAllowPrivateEgressIsAPlatformSettingWithAnEnvironmentOverride(t *testing.T) {
	s, ok := LookupSetting(AllowPrivateEgressSetting)
	if !ok {
		t.Fatalf("%s is not in the registry", AllowPrivateEgressSetting)
	}
	if s.Scope != ScopePlatform || s.Env != "ZOOMIES_ALLOW_PRIVATE_EGRESS" {
		t.Errorf("got scope %s and env %s", s.Scope, s.Env)
	}
	t.Setenv("ZOOMIES_ALLOW_PRIVATE_EGRESS", "true")
	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatal(err)
	}
	if !c.Security.AllowPrivateEgress {
		t.Error("the environment override did not set it")
	}
}

func findingFor(fs Findings, code string) *Finding {
	for i := range fs {
		if fs[i].Code == code {
			return &fs[i]
		}
	}
	return nil
}

package config

import (
	"os"
	"testing"
)

// The compose file hands the whole .env to the container, and an operator with
// a rootless or remote daemon keeps DOCKER_HOST in that file for docker and
// compose themselves. Read after ZOOMIES_DOCKER_HOST, it silently replaced the
// socket the compose file names explicitly.
func TestZoomiesDockerHostWinsOverDockersOwnVariable(t *testing.T) {
	t.Setenv("ZOOMIES_DOCKER_HOST", "unix:///var/run/docker.sock")
	t.Setenv("DOCKER_HOST", "unix:///run/user/1000/docker.sock")

	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if c.Agent.DockerHost != "unix:///var/run/docker.sock" {
		t.Fatalf("docker host = %q, want the explicit ZOOMIES_DOCKER_HOST", c.Agent.DockerHost)
	}
}

// Without Zoomies' own variable, Docker's is still honoured: it is what a
// developer's shell already has set.
func TestDockerHostIsHonouredWhenZoomiesDockerHostIsUnset(t *testing.T) {
	t.Setenv("ZOOMIES_DOCKER_HOST", "")
	// t.Setenv cannot unset, so clear it the long way round.
	t.Setenv("DOCKER_HOST", "unix:///run/user/1000/docker.sock")
	unsetenv(t, "ZOOMIES_DOCKER_HOST")

	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if c.Agent.DockerHost != "unix:///run/user/1000/docker.sock" {
		t.Fatalf("docker host = %q, want DOCKER_HOST", c.Agent.DockerHost)
	}
}

// unsetenv removes a variable for the rest of the test, restoring whatever was
// there before -- t.Setenv can only set.
func unsetenv(t *testing.T, key string) {
	t.Helper()
	if was, ok := os.LookupEnv(key); ok {
		t.Cleanup(func() { _ = os.Setenv(key, was) })
	}
	if err := os.Unsetenv(key); err != nil {
		t.Fatalf("unsetting %s: %v", key, err)
	}
}

// A private registry needs a credential, and the backends have always had a
// field for one with no way to fill it: a pool on a private registry could not
// use pinned-only at all, because the pull it needs was the one the registry
// refused.
func TestTheRegistryCredentialCanBeSuppliedByTheEnvironment(t *testing.T) {
	t.Setenv("ZOOMIES_REGISTRY_AUTH", "eyJ1c2VybmFtZSI6ImJvdCJ9")
	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatalf("applyEnv: %v", err)
	}
	if c.Agent.RegistryAuth != "eyJ1c2VybmFtZSI6ImJvdCJ9" {
		t.Fatalf("agent.registry_auth = %q, want the value from the environment", c.Agent.RegistryAuth)
	}
}

package config

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func writeTestCA(t *testing.T) string {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	tmpl := &x509.Certificate{
		SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "Acme proxy CA"},
		NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour),
		IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign,
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		t.Fatal(err)
	}
	p := filepath.Join(t.TempDir(), "proxy-ca.pem")
	if err := os.WriteFile(p, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), 0o600); err != nil {
		t.Fatal(err)
	}
	return p
}

// The file is mounted into every runner. A bad one has to stop the agent at
// startup, with the setting named, rather than fail every create or leave
// every job failing TLS behind the proxy it was meant to get them through.
func TestAnExtraCAFileMustBeAnAbsolutePathToAPEMCertificate(t *testing.T) {
	dir := t.TempDir()
	notPEM := filepath.Join(dir, "ca.der")
	if err := os.WriteFile(notPEM, []byte{0x30, 0x82, 0x01}, 0o600); err != nil {
		t.Fatal(err)
	}
	garbled := filepath.Join(dir, "garbled.pem")
	if err := os.WriteFile(garbled, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: []byte("nope")}), 0o600); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name, path string
	}{
		{"relative", "proxy-ca.pem"},
		{"missing", filepath.Join(dir, "absent.pem")},
		{"not PEM", notPEM},
		{"unparseable certificate", garbled},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := Default()
			c.Agent.Embedded = true
			c.Agent.ExtraCAFile = tc.path
			fs := c.Validate()
			if !hasCode(fs.Errors(), "agent.extra_ca_invalid") {
				t.Fatalf("agent.extra_ca_file %q was accepted: %+v", tc.path, fs)
			}
			if hasCode(fs, "agent.extra_ca") {
				t.Fatal("a refused CA was also reported as trusted")
			}
		})
	}
}

// Trusting another CA widens what every job trusts. That is the point, and
// not a risk to warn about, but it is surprising enough to say once.
func TestAGoodExtraCAIsReportedAsInformationOnly(t *testing.T) {
	c := Default()
	c.Agent.Embedded = true
	if fs := c.Validate(); hasCode(fs, "agent.extra_ca") || hasCode(fs, "agent.extra_ca_invalid") {
		t.Fatal("an unset agent.extra_ca_file drew a finding")
	}
	c.Agent.ExtraCAFile = writeTestCA(t)
	fs := c.Validate()
	if hasCode(fs, "agent.extra_ca_invalid") {
		t.Fatalf("a good CA was refused: %+v", fs)
	}
	for _, f := range fs {
		if f.Code == "agent.extra_ca" && f.Severity == SeverityInfo {
			return
		}
	}
	t.Fatalf("no agent.extra_ca info finding: %+v", fs)
}

func TestTheExtraCAFileHasAnEnvironmentOverride(t *testing.T) {
	t.Setenv("ZOOMIES_AGENT_EXTRA_CA_FILE", "/etc/acme/proxy-ca.pem")
	c := Default()
	if err := c.applyEnv(); err != nil {
		t.Fatal(err)
	}
	if c.Agent.ExtraCAFile != "/etc/acme/proxy-ca.pem" {
		t.Fatalf("agent.extra_ca_file = %q", c.Agent.ExtraCAFile)
	}
}

