// Opening the log viewer on a runner whose container is not there yet -- or
// whose backend would not answer -- comes back as a failed stream_logs task.
// That says nothing about the runner, and must not fail it: the next reconcile
// would otherwise tear down a container that may be mid-job.
func TestFailedLogTaskLeavesTheRunnerAlone(t *testing.T) {
	for _, tc := range []struct {
		name string
		kind agent.TaskKind // what the agent puts in its result; "" is an older agent
	}{
		{"agent names the kind", agent.TaskStreamLogs},
		{"older agent, controller's record decides", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, store.RunnerProvisioning)

			h.c.enqueue(host.ID, agent.Task{Kind: agent.TaskStreamLogs, RunnerID: r.ID, StreamID: "log_1"})
			batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
			if err != nil {
				t.Fatalf("PollTasks: %v", err)
			}
			err = h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
				TaskID:   batch.Tasks[0].ID,
				Kind:     tc.kind,
				RunnerID: r.ID,
				OK:       false,
				Error:    "no workload for runner " + r.ID + " on this host, so its logs are gone",
			})
			if err != nil {
				t.Fatalf("ReportResult: %v", err)
			}

			after, err := h.st.GetRunner(h.ctx, r.ID)
			if err != nil {
				t.Fatalf("GetRunner: %v", err)
			}
			if after.State != store.RunnerProvisioning {
				t.Fatalf("state = %q after a failed log task, want it left at %q", after.State, store.RunnerProvisioning)
			}
		})
	}
}

// Capacity belongs to the operator once a host has joined: the Hosts API lets
// them set it to 0 to stop placement, and a heartbeat must not put the agent's
// configured number back.
func TestHeartbeatLeavesCapacityToTheOperator(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()

	resp, err := tr.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "vm-1",
		Capacity:        4,
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true}},
	})
	if err != nil {
		t.Fatalf("Join: %v", err)
	}
	tr.SetCredentials(resp.HostID, resp.AgentToken)

	host, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	host.Capacity = 0
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Capacity: 4}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	after, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if after.Capacity != 0 {
		t.Fatalf("capacity = %d after a heartbeat, want the operator's 0 kept", after.Capacity)
	}
	if after.LastHeartbeat.IsZero() {
		t.Fatalf("last heartbeat was not recorded")
	}
}

// A compose deployment joined under whatever hostname Docker gave its first
// container, before the compose file set one, and kept that random name for
// life: the identity is the persisted credential, so the row is renamed rather
// than joined again. Unless something else already has the name.
func TestAdoptingEmbeddedCredentialsRenamesTheHostToItsConfiguredName(t *testing.T) {
	h := newHarness(t)
	host := h.host("7096d9a9b798")

	h.c.renameEmbeddedHost(h.ctx, host, "zoomies")
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Name != "zoomies" {
		t.Fatalf("name = %q, want the configured one", got.Name)
	}

	// Two hosts called zoomies would be worse than one called by its
	// container ID, so a name that is taken stays where it is.
	other := h.host("build-box")
	h.c.renameEmbeddedHost(h.ctx, other, "zoomies")
	if got, _ := h.st.GetHost(h.ctx, other.ID); got.Name != "build-box" {
		t.Fatalf("name = %q; a taken name must not be duplicated", got.Name)
	}
}

// A host that has been silent past the grace is presumed gone, and the runners
// recorded on it with it: until they are failed they count as capacity, so a
// pool pinned at its maximum by a dead host would create nothing for ever
// while looking healthy. The job a busy one was running is the fleet's
// failure, and is marked as such.
func TestRunnersOnAHostSilentPastTheGraceAreFailedAndTheirJobMarkedLost(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	busy := h.runnerRow(pool, host, store.RunnerRegistering)
	mustReportRunning(t, h, host.ID, busy.ID)
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 7007, Labels: []string{"linux-x64"}, RunnerName: busy.Name})

	host.LastHeartbeat = time.Now().Add(-hostLostAfter - time.Minute)
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	h.c.checkHostHealth(h.ctx)

	for _, id := range []string{idle.ID, busy.ID} {
		after, err := h.st.GetRunner(h.ctx, id)
		if err != nil {
			t.Fatalf("GetRunner: %v", err)
		}
		if after.State != store.RunnerFailed {
			t.Fatalf("runner %s is %q after its host went silent, want %q", id, after.State, store.RunnerFailed)
		}
		if !strings.Contains(after.Message, "vm-1") || !strings.Contains(after.Message, "heartbeat") {
			t.Fatalf("message %q does not say which host went quiet", after.Message)
		}
	}
	job, err := h.st.GetJobByGitHubID(h.ctx, 7007)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if job.RunnerFault == "" {
		t.Fatal("the job the busy runner was running was not marked as lost by the fleet")
	}
}

// Unhealthy is not gone. An agent restarting, a daemon being upgraded or a
// network blip all outlast the health timeout, and a host in that state keeps
// its runners until the longer grace has passed.
func TestAHostThatIsMerelyLateKeepsItsRunners(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	r := h.runnerRow(pool, host, store.RunnerIdle)

	host.LastHeartbeat = time.Now().Add(-2 * store.HeartbeatTimeout)
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	h.c.checkHostHealth(h.ctx)

	after, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if after.State != store.RunnerIdle {
		t.Fatalf("runner is %q on a host that is late but not lost, want %q", after.State, store.RunnerIdle)
	}
}

// A stop the host never confirms would leave the runner draining for ever,
// counted against its pool's maximum and holding a slot on its host. Once the
// task has been given up on, the runner is too.
func TestAStopTheHostNeverConfirmedFailsTheRunner(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.c.DrainRunner(h.ctx, r.ID, "operator asked", false); err != nil {
		t.Fatalf("DrainRunner: %v", err)
	}
	if !h.hasTaskOfKind(host.ID, agent.TaskStopRunner) {
		t.Fatal("draining did not queue a stop task")
	}

	q := h.c.queues.get(host.ID)
	now := time.Now()
	for attempt := 1; attempt <= maxTaskAttempts; attempt++ {
		if got := q.take(10, now); len(got) != 1 {
			t.Fatalf("attempt %d: took %d tasks, want the stop", attempt, len(got))
		}
		now = now.Add(stopLease + time.Minute)
		h.c.sweepTasks(h.ctx, now)
	}

	after, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if after.State != store.RunnerFailed {
		t.Fatalf("runner is %q after its stop was given up on, want %q", after.State, store.RunnerFailed)
	}
	if !strings.Contains(after.Message, "never confirmed") {
		t.Fatalf("message %q does not say the stop was never confirmed", after.Message)
	}
}

// joinedHost joins a host reporting the given disk figures and returns the
// transport, already carrying its credentials, with the host's ID.
func joinedHost(t *testing.T, h *harness, totalMB, freeMB int64) (agent.Transport, string) {
	t.Helper()
	tr := h.c.EmbeddedTransport()
	resp, err := tr.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "vm-1",
		Capacity:        4,
		DiskTotalMB:     totalMB,
		DiskFreeMB:      freeMB,
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true}},
	})
	if err != nil {
		t.Fatalf("Join: %v", err)
	}
	tr.SetCredentials(resp.HostID, resp.AgentToken)
	return tr, resp.HostID
}

func hostDisk(t *testing.T, h *harness, id string) (totalMB, freeMB int64) {
	t.Helper()
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	return host.DiskTotalMB, host.DiskFreeMB
}

// A host's disk is what decides whether a runner's checkout and its caches
// have anywhere to go, and until now the agent measured none of it.
func TestAHostReportsTheDiskItsRunnersWillUse(t *testing.T) {
	h := newHarness(t)
	_, id := joinedHost(t, h, 500_000, 200_000)

	total, free := hostDisk(t, h, id)
	if total != 500_000 || free != 200_000 {
		t.Fatalf("disk = %d total, %d free; want what the agent reported", total, free)
	}
}

// Free space is the one figure an agent reports that moves on its own: a job
// unpacking a cache changes it, and so does the job next door. A heartbeat
// arrives every thirty seconds per host, so recording every difference turns a
// fleet's heartbeats into one row write per host per beat for a number that is
// never exactly the same twice.
func TestASmallChangeInFreeDiskIsNotWorthAWrite(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	// One percent down, which is what a job starting looks like.
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		DiskTotalMB:     500_000,
		DiskFreeMB:      198_000,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	if _, free := hostDisk(t, h, id); free != 200_000 {
		t.Fatalf("free = %d; a drift this small must not rewrite the row", free)
	}
}

// Far enough is another matter: a host filling up is exactly what an operator
// needs to see, and what placement will need to read.
func TestADiskThatHasReallyMovedIsRecorded(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		DiskTotalMB:     500_000,
		DiskFreeMB:      40_000,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	if _, free := hostDisk(t, h, id); free != 40_000 {
		t.Fatalf("free = %d, want the 40000 the agent reported", free)
	}
}

// An agent too old to measure disk, or one on a platform with no portable way
// to ask, sends nothing. Nothing must not overwrite something: a zero read as
// a full disk would take a host out of service on an upgrade, which is the
// opposite of what reporting more about a host is for.
func TestAnAgentThatCannotMeasureDiskDoesNotEraseWhatIsKnown(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	// The beat carries a new version, so the row is rewritten for a reason
	// that has nothing to do with the disk. Without a beat that writes at all,
	// this would pass on the tolerance alone and say nothing about whether a
	// silent agent's zero can reach the row.
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Version:         "0.3-beta",
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	after, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if after.Version != "0.3-beta" {
		t.Fatalf("version = %q; the beat has to have rewritten the row for this to mean anything", after.Version)
	}

	total, free := hostDisk(t, h, id)
	if total != 500_000 || free != 200_000 {
		t.Fatalf("disk = %d total, %d free; a silent agent erased what was known", total, free)
	}
}

// The first measurement always lands, however small the number, because going
// from "not measured" to a figure is the difference between a host that can be
// placed on by disk and one that cannot.
func TestTheFirstDiskMeasurementIsAlwaysRecorded(t *testing.T) {
	h := newHarness(t)
	// The total is already known, so only the free figure is new. Letting the
	// total change too would carry the write on its own and say nothing about
	// how a first free-space measurement is treated.
	tr, id := joinedHost(t, h, 500_000, 0)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		DiskTotalMB:     500_000,
		DiskFreeMB:      10,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	if _, free := hostDisk(t, h, id); free != 10 {
		t.Fatalf("free = %d; a first measurement is smaller than any tolerance and must still land", free)
	}
}

// The tolerance itself, branch by branch. The heartbeat tests above prove the
// wiring; this proves the rule, including the two cases whose only effect is a
// row write that does not happen -- which nothing outside this package can see.
func TestWhenFreeDiskIsWorthAWrite(t *testing.T) {
	tests := []struct {
		name     string
		was, now int64
		measured bool
		want     bool
	}{
		{"a first measurement, however small", 0, 10, true, true},
		{"an agent that cannot measure says nothing", 200_000, 0, false, false},
		{"neither figure known", 0, 0, false, false},
		{"a job starting, on a large disk", 200_000, 198_000, true, false},
		{"a disk filling up", 200_000, 40_000, true, true},
		{"freed by a cache eviction", 40_000, 200_000, true, true},
		{"a small disk, drifting under the floor", 1_000, 900, true, false},
		{"a small disk, past the floor", 1_000, 700, true, true},
		// The pair that cannot share an encoding. A host with nothing left is
		// the one state where being out of date does real harm, and it reads
		// as the same zero an agent too old to look sends.
		{"a disk that has actually filled up", 200_000, 0, true, true},
		{"a full disk that is still full", 0, 0, true, false},
		{"the first space freed on a full disk", 0, 5_000, true, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := diskFreeMoved(tc.was, tc.now, tc.measured); got != tc.want {
				t.Fatalf("diskFreeMoved(%d, %d, measured=%v) = %v, want %v",
					tc.was, tc.now, tc.measured, got, tc.want)
			}
		})
	}
}

// The state an operator most needs to see, end to end: an agent reporting a
// disk with nothing left on it, which reads as the same zero that an agent too
// old to measure sends. Getting these two the same way round leaves a full host
// describing itself with the last comfortable figure it ever reported.
func TestAFullDiskIsRecordedRatherThanReadAsSilence(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		DiskTotalMB:     500_000,
		DiskFreeMB:      0,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	total, free := hostDisk(t, h, id)
	if free != 0 {
		t.Fatalf("free = %d MB on a host that reported none left", free)
	}
	if total != 500_000 {
		t.Fatalf("total = %d MB; the size is what says the reading happened", total)
	}
}

// The reserve is the operator's, like capacity. An agent reports what it sees
// and never writes this, or a host could talk its way out of the room its
// operator held back for it.
func TestAHeartbeatNeverWritesTheOperatorsReserve(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	if err := h.st.SetHostReserve(h.ctx, id, 2, 4096, 50_000); err != nil {
		t.Fatalf("SetHostReserve: %v", err)
	}

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		DiskTotalMB:     500_000,
		DiskFreeMB:      40_000,
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	after, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if after.ReserveCPUs != 2 || after.ReserveMemoryMB != 4096 || after.ReserveDiskMB != 50_000 {
		t.Fatalf("reserve = %d cpus, %d MB, %d MB disk; a heartbeat overwrote the operator's",
			after.ReserveCPUs, after.ReserveMemoryMB, after.ReserveDiskMB)
	}
	// And the observation it carried did land, so this is not passing because
	// the whole write was skipped.
	if _, free := hostDisk(t, h, id); free != 40_000 {
		t.Fatalf("free = %d; the heartbeat's own observation was lost", free)
	}
}

// A re-join is the agent's doing -- a rebuilt machine reclaiming its row, or an
// embedded agent whose credentials no longer match -- and it replaces the row
// wholesale. Letting the reserve drop there would be the agent writing it after
// all, by the back door and silently: the row keeps its id, its cordon and its
// labels, so nothing looks wrong until the controller places into the space the
// operator held back.
func TestARejoinKeepsTheOperatorsReserve(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)
	_ = tr

	if err := h.st.SetHostReserve(h.ctx, id, 2, 4096, 50_000); err != nil {
		t.Fatalf("SetHostReserve: %v", err)
	}
	before, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	before.Cordoned = true
	if err := h.st.UpdateHost(h.ctx, before); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}

	// The same machine, joining again under its own name with a fresh token.
	again := h.c.EmbeddedTransport()
	resp, err := again.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "vm-1",
		Capacity:        4,
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true}},
	})
	if err != nil {
		t.Fatalf("re-Join: %v", err)
	}

	after, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if after.ReserveCPUs != 2 || after.ReserveMemoryMB != 4096 || after.ReserveDiskMB != 50_000 {
		t.Fatalf("reserve = %d cpus, %d MB, %d MB disk after a re-join; the operator's must survive it",
			after.ReserveCPUs, after.ReserveMemoryMB, after.ReserveDiskMB)
	}
	// The cordon is carried across for the same reason and is the proof that
	// this row really was replaced rather than left alone.
	if !after.Cordoned {
		t.Fatal("the cordon did not survive the re-join either, so this is not testing what it claims")
	}
}

// stringsIn returns every string in a marshalled JSON document, keys included,
// so a secret is found wherever it was put and whatever escaping it picked up
// on the way.
func stringsIn(t *testing.T, doc []byte) []string {
	t.Helper()
	var v any
	if err := json.Unmarshal(doc, &v); err != nil {
		t.Fatalf("unmarshalling to walk it: %v", err)
	}
	var out []string
	var walk func(any)
	walk = func(n any) {
		switch n := n.(type) {
		case string:
			out = append(out, n)
		case []any:
			for _, e := range n {
				walk(e)
			}
		case map[string]any:
			for k, e := range n {
				out = append(out, k)
				walk(e)
			}
		}
	}
	walk(v)
	return out
}

func truncateValue(s string) string {
	if len(s) > 120 {
		return s[:120] + "..."
	}
	return s
}

// A controller holding more polls than it wants to asks the agents it answers
// to come back less often. The pressure it is shedding is the fleet's size
// rather than its workload -- an idle host still costs a held connection --
// so nothing else about the fleet says it is happening.
func TestATaskPollFindingNothingIsAskedToWaitWhenTheControllerIsHoldingTooMany(t *testing.T) {
	h := newHarness(t)
	h.c.pollsInFlight.Store(pollShedThreshold * 2)

	batch, err := h.c.PollTasks(h.ctx, "host_quiet", 10*time.Millisecond)
	if err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if batch.Backoff <= 0 {
		t.Fatalf("batch = %+v, want a backoff: %d polls are in flight and the threshold is %d",
			batch, h.c.pollsInFlight.Load(), pollShedThreshold)
	}
}

// Work is never delayed to shed load. The long poll exists so that a task
// reaches its host in the instant it is queued, and a controller that held a
// created runner back for fifteen seconds because it was busy would be slower
// exactly when the fleet needed it to be quick.
func TestABatchWithWorkInItIsNeverAskedToWait(t *testing.T) {
	h := newHarness(t)
	h.c.pollsInFlight.Store(pollShedThreshold * 10)
	h.c.enqueue("host_busy", agent.Task{Kind: agent.TaskRemoveRunner, RunnerID: "run_1"})

	batch, err := h.c.PollTasks(h.ctx, "host_busy", 10*time.Millisecond)
	if err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if len(batch.Tasks) != 1 {
		t.Fatalf("batch = %+v, want the queued task", batch)
	}
	if batch.Backoff != 0 {
		t.Fatalf("batch carries a %s backoff with work in it", batch.Backoff)
	}
}

// A quiet fleet is asked for nothing at all, so the mechanism costs a single
// deployment nothing.
func TestShedForAsksAFleetUnderTheThresholdForNothing(t *testing.T) {
	for _, inFlight := range []int64{0, 1, pollShedThreshold} {
		if got := shedFor(inFlight); got != 0 {
			t.Errorf("shedFor(%d) = %s, want no wait at all", inFlight, got)
		}
	}
}

// The wait rises with the excess rather than switching on: a step would move
// the whole fleet between two duty cycles at once and oscillate around the
// threshold. It is capped, because a fleet twice the size it should be is
// still a fleet that has to start runners.
func TestTheShedWaitRisesWithTheExcessAndIsCapped(t *testing.T) {
	small, large := shedFor(pollShedThreshold+8), shedFor(pollShedThreshold+64)
	if small <= 0 || large <= small {
		t.Fatalf("waits of %s then %s: a bigger excess should ask for a longer wait", small, large)
	}
	if got := shedFor(pollShedThreshold * 100); got != maxPollShed {
		t.Fatalf("shedFor(a hundred times over) = %s, want the %s cap", got, maxPollShed)
	}
}

// TestAHeartbeatDoesNotUndoAnOperatorsCordon covers the window between reading
// a host row and writing it back.
//
// The heartbeat reads the host at the top of the request and, when anything the
// agent reports has moved, wrote the whole row back. An operator who cordoned
// the machine in the interval had their change overwritten with the pre-edit
// value -- no error, nothing in the log, and the UI still showing it cordoned
// because the cordon handler had already published its own view. The scheduler
// reads the row, so the next pass puts runners on the machine somebody is about
// to power off.
//
// The store already draws this line for the reserves, whose comment says a host
// must not be able to talk its way out of the room its operator held back for
// it. A cordon is the same thing said more loudly.
func TestAHeartbeatDoesNotUndoAnOperatorsCordon(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()

	resp, err := tr.Join(h.ctx, agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Name:            "builder-1",
		Capacity:        4,
		OS:              "linux",
		Arch:            "amd64",
		Backends:        []backend.Info{{Kind: store.BackendDocker, Available: true, Version: "27.1.1"}},
	})
	if err != nil {
		t.Fatalf("Join: %v", err)
	}
	tr.SetCredentials(resp.HostID, resp.AgentToken)

	// The operator cordons the host for maintenance, and renames it.
	if err := h.st.SetHostCordoned(h.ctx, resp.HostID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}

	// A heartbeat arrives carrying something new, so the row is written. The
	// agent's copy of the host still says uncordoned.
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        4,
		Version:         "1.2.3",
		CPUs:            16,
		MemoryMB:        32768,
		Backends: []backend.Info{{
			Kind: store.BackendDocker, Available: true, Version: "27.2.0",
		}},
	}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}

	host, err := h.st.GetHost(h.ctx, resp.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !host.Cordoned {
		t.Error("the heartbeat uncordoned a host its operator had just cordoned")
	}
	// And what the agent legitimately reports still lands, or the narrower
	// write has thrown away the point of the heartbeat.
	if host.Version != "1.2.3" || host.CPUs != 16 || host.MemoryMB != 32768 {
		t.Errorf("host = version %q cpus %d memory %d, want the values the agent reported",
			host.Version, host.CPUs, host.MemoryMB)
	}
	if info, ok := host.BackendInfo.Find(store.BackendDocker); !ok || info.Version != "27.2.0" {
		t.Errorf("backend info = %+v, want the version the agent reported", host.BackendInfo)
	}
}

// A host that changes its name on upgrade must still be one host.
//
// The name is not stable: it is derived from what the machine is, so an agent
// that has learnt to measure its own CPUs and memory computes a different one
// from an agent that had not. The reclaim was keyed on the name alone, so
// upgrading such a host enrolled it a second time -- a new row with the correct
// figures, beside the old row still being kept alive by the process that had
// not been restarted yet. The operator saw one machine as two, one of them
// reporting nothing, and neither of them wrong exactly.
//
// The id the agent already keeps in its credentials file is what settles it.
// The token is still the proof; the id only says which row the proof is about.
func TestAnUpgradedAgentThatRenamesItselfReclaimsItsOwnRow(t *testing.T) {
	h := newHarness(t)

	// As it was: the bare hostname, which is what an older agent sent.
	first, err := h.c.Join(h.ctx, joinRequest("Ollama1", h.joinToken(t, nil, 0)), "10.0.0.9")
	if err != nil {
		t.Fatalf("first join: %v", err)
	}

	// As it is after the upgrade: the same machine, describing itself.
	renamed := joinRequest("zoomies-4vcpu-8gb-debian-12-ollama1", h.joinToken(t, nil, 0))
	renamed.PreviousToken = first.AgentToken
	renamed.PreviousHostID = first.HostID
	second, err := h.c.Join(h.ctx, renamed, "10.0.0.9")
	if err != nil {
		t.Fatalf("re-join under a new name: %v", err)
	}
	if second.HostID != first.HostID {
		t.Errorf("host ID = %s, want %s: the machine was enrolled a second time instead of reclaiming its row",
			second.HostID, first.HostID)
	}

	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	var named int
	for _, host := range hosts {
		if host.ID == first.HostID {
			named++
			if host.Name != "zoomies-4vcpu-8gb-debian-12-ollama1" {
				t.Errorf("the reclaimed row kept the old name %q, so the Hosts page still says what the machine was", host.Name)
			}
		}
	}
	if named != 1 {
		t.Fatalf("found %d rows for the reclaimed host, want 1", named)
	}
	if len(hosts) != 1 {
		names := make([]string, 0, len(hosts))
		for _, host := range hosts {
			names = append(names, host.Name)
		}
		t.Errorf("one machine left %d host rows: %s", len(hosts), strings.Join(names, ", "))
	}

	// The id is a claim, not a credential. Naming somebody else's row without
	// their token still gets nowhere.
	_, _, other := h.fleet()
	thief := joinRequest("anything-at-all", h.joinToken(t, nil, 0))
	thief.PreviousHostID = other.ID
	if _, err := h.c.Join(h.ctx, thief, "10.0.0.66"); err == nil {
		t.Error("a join claimed another host's row by naming its id, with no token to prove it")
	}
}

package controller

import (
	"context"
	"fmt"
	"net/url"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// AIContextDiscovery describes candidates only; discovery never grants source
// access, enables a repository or changes the GitHub App's permissions.
type AIContextDiscovery struct {
	Repositories            []github.Repository `json:"repositories"`
	CanReadContents         bool                `json:"can_read_contents"`
	MissingSetupPermissions []string            `json:"missing_setup_permissions"`
	DefaultExclusions       []string            `json:"default_exclusions"`
	DefaultKeepSnapshots    int                 `json:"default_keep_snapshots"`
	Capped                  bool                `json:"capped"`
	// ZoomiesUploadAvailable says whether this controller can take
	// Zoomies-only uploads at all: GitHub's runners need an https address.
	ZoomiesUploadAvailable bool `json:"zoomies_upload_available"`
}

func (c *Controller) DiscoverAIContext(ctx context.Context, installationID string) (*AIContextDiscovery, error) {
	client, err := c.ClientFor(ctx, installationID)
	if err != nil {
		return nil, err
	}
	// The fleet's Verify operation may create/adopt a runner group. Discovery
	// probes the client directly so opening the wizard cannot mutate a fleet.
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, err
	}
	repos, err := client.ListRepositories(ctx, 0)
	if err != nil {
		return nil, err
	}
	// ListRepositories has a hard ceiling. Conservatively report that ceiling
	// even when an installation happens to have exactly this many repositories.
	defaults := aicontext.DefaultConfig("main")
	out := &AIContextDiscovery{DefaultExclusions: defaults.Exclude, DefaultKeepSnapshots: defaults.KeepSnapshots, Repositories: repos, CanReadContents: info.CanReadContents(), MissingSetupPermissions: info.MissingForMigration(), Capped: len(repos) >= github.RepositoryDiscoveryLimit, ZoomiesUploadAvailable: aicontext.UploadURLFor(c.cfg().Server.ExternalURL) != ""}
	if out.Repositories == nil {
		out.Repositories = []github.Repository{}
	}
	if out.MissingSetupPermissions == nil {
		out.MissingSetupPermissions = []string{}
	}
	sort.Slice(out.Repositories, func(i, j int) bool { return out.Repositories[i].FullName < out.Repositories[j].FullName })
	return out, nil
}

// AIContextDraftRequest selects a discovered identity, never a caller-supplied
// host or name. Those fields must come from the installation's own metadata.
type AIContextDraftRequest struct {
	InstallationID string `json:"installation_id"`
	RepositoryID   int64  `json:"repository_id"`
}

func (c *Controller) CreateAIContextDraft(ctx context.Context, req AIContextDraftRequest) (*store.AIContextRepository, error) {
	if req.InstallationID == "" || req.RepositoryID <= 0 {
		return nil, fmt.Errorf("%w: choose a known installation and repository", auth.ErrInvalidInput)
	}
	discovery, err := c.DiscoverAIContext(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	if !discovery.CanReadContents {
		return nil, fmt.Errorf("%w: grant the GitHub App Contents read permission before preparing this repository", auth.ErrInvalidInput)
	}
	var selected *github.Repository
	for i := range discovery.Repositories {
		if discovery.Repositories[i].ID == req.RepositoryID {
			selected = &discovery.Repositories[i]
			break
		}
	}
	if selected == nil {
		return nil, fmt.Errorf("%w: this repository is not in the installation's discovered selection", auth.ErrInvalidInput)
	}
	if selected.Archived {
		return nil, fmt.Errorf("%w: choose an active repository; archived repositories cannot receive setup pull requests", auth.ErrInvalidInput)
	}
	cfg := aicontext.DefaultConfig(selected.DefaultBranch)
	if err := cfg.Validate(); err != nil {
		return nil, fmt.Errorf("%w: %s", auth.ErrInvalidInput, err)
	}
	inst, err := c.st.GetInstallation(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	host, err := aiContextGitHubHost(inst.APIBaseURL)
	if err != nil {
		return nil, err
	}
	draft := &store.AIContextRepository{Key: aicontext.RepositoryKey{GitHubHost: host, InstallationID: inst.ID, RepositoryID: selected.ID}, FullName: selected.FullName, Config: cfg}
	if err := c.st.CreateAIContextRepository(ctx, draft); err != nil {
		return nil, err
	}
	return draft, nil
}

func aiContextGitHubHost(baseURL string) (string, error) {
	if baseURL == "" {
		return "github.com", nil
	}
	u, err := url.Parse(baseURL)
	if err != nil || u.Host == "" || u.User != nil {
		return "", fmt.Errorf("%w: correct the installation's GitHub API URL", auth.ErrInvalidInput)
	}
	host := strings.ToLower(u.Host)
	if host == "api.github.com" {
		host = "github.com"
	}
	return host, nil
}

func (c *Controller) FindAIContextDraft(ctx context.Context, installationID string, repositoryID int64) (*store.AIContextRepository, error) {
	inst, err := c.st.GetInstallation(ctx, installationID)
	if err != nil {
		return nil, err
	}
	host, err := aiContextGitHubHost(inst.APIBaseURL)
	if err != nil {
		return nil, err
	}
	if repositoryID <= 0 {
		return nil, fmt.Errorf("%w: choose a known repository ID", auth.ErrInvalidInput)
	}
	return c.st.FindAIContextRepository(ctx, aicontext.RepositoryKey{GitHubHost: host, InstallationID: installationID, RepositoryID: repositoryID})
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

var errAIContextAwaitingMerge = errors.New("merge the reviewed setup PR before generating context")

var errAIContextAwaitingUpload = errors.New("the workflow has not uploaded context for the current commit yet")

// Context verification has its own bounded loop so a repository pack cannot
// hold the fleet's scheduling lock. Polling also recovers missed push events.
func (c *Controller) aiContextLoop(ctx context.Context) {
	timer := time.NewTimer(15 * time.Second)
	defer timer.Stop()
	offset := 0
	for {
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
			ids, err := c.st.ListAIContextVerificationCandidates(ctx, 20, offset)
			if err == nil {
				for _, id := range ids {
					checkCtx, cancel := context.WithTimeout(ctx, 45*time.Second)
					_ = c.RefreshAIContext(checkCtx, id)
					cancel()
					if ctx.Err() != nil {
						return
					}
				}
				offset += len(ids)
				if len(ids) < 20 {
					offset = 0
				}
			}
			timer.Reset(5 * time.Minute)
		}
	}
}
func (c *Controller) trustedAIContext(ctx context.Context, r *store.AIContextRepository) (github.ContextIngestionClient, *github.ContextSetupSource, error) {
	if r.Config.Disabled {
		return nil, nil, fmt.Errorf("AI Context has been removed; reinstall it to resume source access")
	}
	setup, err := c.st.GetAIContextSetup(ctx, r.ID)
	if err != nil {
		return nil, nil, err
	}
	if setup.State != "awaiting_merge" || setup.PRNumber < 1 {
		return nil, nil, errAIContextAwaitingMerge
	}
	client, err := c.ClientFor(ctx, r.Key.InstallationID)
	if err != nil {
		return nil, nil, err
	}
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, nil, err
	}
	if !info.CanReadContents() {
		return nil, nil, fmt.Errorf("restore GitHub Contents read permission")
	}
	ingestion, ok := client.(github.ContextIngestionClient)
	if !ok {
		return nil, nil, fmt.Errorf("this client cannot verify generated context")
	}
	merged, err := ingestion.ContextSetupMerged(ctx, r.FullName, setup.PRNumber, r.Config.SourceBranch)
	if err != nil {
		return nil, nil, err
	}
	if !merged {
		return nil, nil, errAIContextAwaitingMerge
	}
	sourceClient, ok := client.(github.ContextSetupClient)
	if !ok {
		return nil, nil, fmt.Errorf("this client cannot verify managed context files")
	}
	source, err := sourceClient.ReadContextSetup(ctx, r.FullName, r.Config.SourceBranch)
	if err != nil {
		return nil, nil, err
	}
	if source.Repository.ID != r.Key.RepositoryID || source.Repository.FullName != r.FullName || source.Repository.Archived || source.Repository.DefaultBranch != r.Config.SourceBranch {
		return nil, nil, fmt.Errorf("repository identity or trusted branch changed")
	}
	desired, err := aicontext.PlanManagedSetup(r.Key, r.FullName, r.Config, nil)
	if err != nil {
		return nil, nil, err
	}
	files := map[string]string{}
	for _, file := range source.Files {
		files[file.Path] = file.Content
	}
	for _, file := range desired {
		switch file.Path {
		case aicontext.ConfigPath, aicontext.WorkflowPath, aicontext.GeneratorPackagePath, aicontext.GeneratorLockPath:
			if files[file.Path] != file.Content {
				if file.Path == aicontext.WorkflowPath {
					legacy, legacyErr := aicontext.LegacySetupWorkflow(r.Key, r.Config)
					if legacyErr == nil && files[file.Path] == legacy {
						continue
					}
				}
				return nil, nil, fmt.Errorf("managed workflow or configuration changed; review a repair before ingestion")
			}
		}
	}
	return ingestion, source, nil
}
func (c *Controller) RefreshAIContext(ctx context.Context, id string) error {
	_, _, err := c.verifyAIContext(ctx, id)
	return err
}

// verifyAIContext runs the live access, setup and publication checks. For
// repository-only output it returns the verified snapshot in memory and records
// freshness without storing a byte of source; for Both the snapshot lives in the
// database and the returned one is nil.
func (c *Controller) verifyAIContext(ctx context.Context, id string) (*aicontext.Snapshot, string, error) {
	select {
	case c.aiContextChecks <- struct{}{}:
		defer func() { <-c.aiContextChecks }()
	case <-ctx.Done():
		return nil, "", ctx.Err()
	}

	r, err := c.st.GetAIContextRepository(ctx, id)
	if err != nil {
		return nil, "", err
	}
	// Close the access gate on every failed verification, including transient
	// network failures. Source never falls back to an unverified retained pack.
	client, source, err := c.trustedAIContext(ctx, r)
	if err != nil {
		state, reason := "unavailable", "Repository setup or GitHub access could not be verified."
		if errors.Is(err, errAIContextAwaitingMerge) {
			state, reason = "awaiting_merge", "Merge the reviewed setup PR before generating context."
		}
		_ = c.failAIContextCheck(ctx, id, state, "", reason)
		return nil, "", err
	}
	if r.Config.Destination == aicontext.Zoomies {
		// Nothing to fetch: the workflow uploads, and the upload is verified
		// when it arrives. A check only confirms the stored snapshot is still
		// the current commit's, with everything above still true.
		hash, _ := r.Config.Hash()
		if f, _ := c.st.GetAIContextFreshness(ctx, id); f != nil && f.PublishedCommit == source.Commit && f.Digest != "" {
			if _, err := c.st.GetAIContextSnapshot(ctx, id, f.Digest); err == nil {
				if err = c.st.ConfirmAIContextSnapshot(ctx, id, r.Revision, f.Digest, source.Commit, hash); err == nil {
					return nil, f.Digest, nil
				}
			}
		}
		_ = c.failAIContextCheck(ctx, id, "stale", source.Commit, "Waiting for the workflow to upload context for the current commit. The previous snapshot is retained.")
		return nil, "", errAIContextAwaitingUpload
	}
	transient := r.Config.Destination == aicontext.Repository
	hash, _ := r.Config.Hash()
	if !transient {
		freshness, _ := c.st.GetAIContextFreshness(ctx, id)
		if freshness != nil && freshness.PublishedCommit == source.Commit && freshness.Digest != "" {
			if _, err := c.st.GetAIContextSnapshot(ctx, id, freshness.Digest); err == nil {
				if err = c.st.ConfirmAIContextSnapshot(ctx, id, r.Revision, freshness.Digest, source.Commit, hash); err == nil {
					return nil, freshness.Digest, nil
				}
			}
		}
	}
	publication, err := client.ReadContextPublication(ctx, r.FullName, r.Config.SourceBranch)
	var digest string
	if err == nil {
		err = publication.Snapshot.Match(r.Key, r.Config.SourceBranch, source.Commit, hash)
		if err == nil {
			err = r.Config.CheckSourceFiles(publication.Snapshot.Files)
		}
		if err == nil && publication.Snapshot.Manifest.Generator != "repomix@1.18.1" {
			err = fmt.Errorf("context generator identity does not match its managed workflow")
		}
	}
	if err == nil {
		if transient {
			var body []byte
			if body, err = json.Marshal(publication.Snapshot); err == nil {
				digest = aicontext.Hash(body)
				err = c.st.ConfirmAIContextTransient(ctx, id, r.Revision, source.Commit, digest, hash)
			}
		} else {
			err = c.st.PublishAIContextSnapshot(ctx, id, r.Revision, publication.Snapshot)
		}
	}
	if err != nil {
		reason := "Current generation could not be verified. The previous snapshot is retained."
		if transient {
			reason = "Current generation could not be verified. Repository-only output keeps no copy."
		}
		_ = c.failAIContextCheck(ctx, id, "stale", source.Commit, reason)
		return nil, "", err
	}
	if transient {
		return publication.Snapshot, digest, nil
	}
	return nil, digest, nil
}

// VerifiedAIContextSnapshot repeats live access and workflow checks before
// returning source. Background polling alone is not an access gate.
func (c *Controller) VerifiedAIContextSnapshot(ctx context.Context, id string) (*aicontext.Snapshot, *store.AIContextFreshness, error) {
	transient, _, err := c.verifyAIContext(ctx, id)
	if err != nil {
		return nil, nil, err
	}
	f, err := c.st.GetAIContextFreshness(ctx, id)
	if err != nil {
		return nil, nil, err
	}
	if transient != nil {
		return transient, f, nil
	}
	snapshot, err := c.st.GetAIContextSnapshot(ctx, id, f.Digest)
	return snapshot, f, err
}

func (c *Controller) failAIContextCheck(ctx context.Context, id, state, desired, reason string) error {
	cleanup, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	return c.st.FailAIContextCheck(cleanup, id, state, desired, reason)
}

package controller

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

type AIContextMaintenanceRequest struct {
	Mode     string            `json:"mode"`
	Revision int64             `json:"revision"`
	Config   *aicontext.Config `json:"config,omitempty"`
	PlanHash string            `json:"plan_hash,omitempty"`
}

func (c *Controller) PreviewAIContextMaintenance(ctx context.Context, id string, req AIContextMaintenanceRequest) (*AIContextSetupPreview, error) {
	if req.Mode != "reinstall" && req.Mode != "amend" && req.Mode != "remove" {
		return nil, fmt.Errorf("%w: choose reinstall, amend or remove", auth.ErrInvalidInput)
	}
	r, err := c.st.GetAIContextRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	saved, err := c.st.GetAIContextSetup(ctx, id)
	if err != nil {
		return nil, err
	}
	var previous AIContextSetupPreview
	if err = json.Unmarshal([]byte(saved.PlanJSON), &previous); err != nil {
		return nil, err
	}
	// A lost publication response resumes the persisted operation, never a new one.
	if req.PlanHash != "" && req.PlanHash == saved.PlanHash && req.Mode == previous.Mode {
		previous.Setup = saved
		return &previous, nil
	}
	if req.Revision != r.Revision || saved.PRNumber == 0 {
		return nil, fmt.Errorf("%w: resume the existing proposal before maintenance", store.ErrConflict)
	}
	client, source, err := c.contextSetupClient(ctx, r)
	if err != nil {
		return nil, err
	}
	statusClient, ok := client.(github.ContextSetupStatusClient)
	if !ok {
		return nil, fmt.Errorf("%w: GitHub cannot verify the previous proposal", auth.ErrInvalidInput)
	}
	status, err := statusClient.ContextSetupStatus(ctx, r.FullName, saved.PRNumber, r.Config.SourceBranch)
	if err != nil {
		return nil, err
	}
	if status != "merged" && status != "closed" {
		return nil, fmt.Errorf("%w: merge or close the existing setup PR before maintenance", store.ErrConflict)
	}
	config := r.Config
	if req.Mode == "amend" {
		if req.Config == nil {
			return nil, fmt.Errorf("%w: provide amended settings", auth.ErrInvalidInput)
		}
		config = *req.Config
	}
	if config.SourceBranch != r.Config.SourceBranch {
		return nil, fmt.Errorf("%w: keep the verified source branch", auth.ErrInvalidInput)
	}
	config.ReadmeBadge = nil
	// The upload address follows the controller, never the request: a
	// reinstall after server.external_url changed re-aims the workflow too.
	config.UploadURL = ""
	if config.Destination == aicontext.Zoomies {
		config.UploadURL = aicontext.UploadURLFor(c.cfg().Server.ExternalURL)
	}
	config.SetupGeneration = r.Config.SetupGeneration + 1
	config.Disabled = req.Mode == "remove"
	if err = config.Validate(); err != nil {
		return nil, fmt.Errorf("%w: %s", auth.ErrInvalidInput, err)
	}
	files, err := aicontext.PlanMaintenance(r.Key, r.FullName, r.Config, config, source.Files, previous.Files, req.Mode == "remove")
	if err != nil {
		return nil, fmt.Errorf("%w: %s", auth.ErrInvalidInput, err)
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("%w: no managed files remain to remove", auth.ErrInvalidInput)
	}
	plan := &AIContextSetupPreview{Mode: req.Mode, Config: &config, PreviousHash: saved.PlanHash, Revision: r.Revision, BaseCommit: source.Commit, Files: files}
	payload, _ := json.Marshal(struct {
		Key  aicontext.RepositoryKey
		Plan *AIContextSetupPreview
	}{r.Key, plan})
	plan.PlanHash = aicontext.Hash(payload)
	plan.Branch = fmt.Sprintf("zoomies-ai-context-%s-%d-%s", req.Mode, r.Key.RepositoryID, plan.PlanHash[:16])
	if payload, _ = json.Marshal(plan); len(payload) > 4<<20 {
		return nil, fmt.Errorf("%w: maintenance preview exceeds size limit", auth.ErrInvalidInput)
	}
	return plan, nil
}

func (c *Controller) ApplyAIContextMaintenance(ctx context.Context, id string, req AIContextMaintenanceRequest) (*AIContextSetupPreview, error) {
	if len(req.PlanHash) != 64 {
		return nil, auth.ErrInvalidInput
	}
	plan, err := c.PreviewAIContextMaintenance(ctx, id, req)
	if err != nil {
		return nil, err
	}
	if plan.PlanHash != req.PlanHash {
		return nil, store.ErrConflict
	}
	if plan.Setup != nil && plan.Setup.State == "awaiting_merge" {
		return plan, nil
	}
	r, err := c.st.GetAIContextRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	client, source, err := c.contextSetupClient(ctx, r)
	if err != nil {
		return nil, err
	}
	operation := &store.AIContextSetup{RepositoryID: id, PlanHash: plan.PlanHash}
	if plan.Setup != nil {
		operation.Revision = plan.Revision
		operation.PlanJSON = plan.Setup.PlanJSON
		err = c.st.ClaimAIContextSetup(ctx, operation)
	} else {
		if source.Commit != plan.BaseCommit {
			return nil, store.ErrConflict
		}
		plan.Revision++
		payload, _ := json.Marshal(plan)
		operation.Revision = plan.Revision
		operation.PlanJSON = string(payload)
		err = c.st.ClaimAIContextMaintenance(ctx, operation, plan.PreviousHash, *plan.Config)
	}
	if err != nil {
		return nil, err
	}
	return c.publishAIContextPlan(ctx, r, client, plan, operation)
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

type AIContextSetupPreview struct {
	Mode         string                  `json:"mode,omitempty"`
	Config       *aicontext.Config       `json:"config,omitempty"`
	PreviousHash string                  `json:"previous_hash,omitempty"`
	Revision     int64                   `json:"revision"`
	BaseCommit   string                  `json:"base_commit"`
	Branch       string                  `json:"branch"`
	PlanHash     string                  `json:"plan_hash"`
	Files        []aicontext.SetupChange `json:"files"`
	Setup        *store.AIContextSetup   `json:"setup,omitempty"`
}

type AIContextSetupApproval struct {
	Revision int64  `json:"revision"`
	PlanHash string `json:"plan_hash"`
}

func (c *Controller) contextSetupClient(ctx context.Context, r *store.AIContextRepository) (github.ContextSetupClient, *github.ContextSetupSource, error) {
	client, err := c.ClientFor(ctx, r.Key.InstallationID)
	if err != nil {
		return nil, nil, err
	}
	info, err := client.Probe(ctx)
	if err != nil {
		return nil, nil, err
	}
	if !info.CanReadContents() {
		_ = c.st.SetAIContextAvailable(ctx, r.ID, false)
		return nil, nil, fmt.Errorf("%w: grant Contents read permission to inspect repository setup", auth.ErrInvalidInput)
	}
	if missing := info.MissingForMigration(); len(missing) > 0 {
		return nil, nil, fmt.Errorf("%w: setup PRs need Contents write, Workflows write and Pull requests write; accept these permissions on the installation", auth.ErrInvalidInput)
	}
	setupClient, ok := client.(github.ContextSetupClient)
	if !ok {
		return nil, nil, fmt.Errorf("%w: this GitHub client does not support managed context setup", auth.ErrInvalidInput)
	}
	source, err := setupClient.ReadContextSetup(ctx, r.FullName, r.Config.SourceBranch)
	if err != nil {
		return nil, nil, err
	}
	if source.Repository.ID != r.Key.RepositoryID || source.Repository.FullName != r.FullName || source.Repository.Archived || source.Repository.DefaultBranch != r.Config.SourceBranch {
		return nil, nil, fmt.Errorf("%w: repository identity, default branch or archived state changed; review its setup", auth.ErrInvalidInput)
	}
	return setupClient, source, nil
}

func (c *Controller) PreviewAIContextSetup(ctx context.Context, id string) (*AIContextSetupPreview, error) {
	r, err := c.st.GetAIContextRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	_, source, err := c.contextSetupClient(ctx, r)
	if err != nil {
		if errors.Is(err, github.ErrSetupConflict) {
			return nil, fmt.Errorf("%w: %s", store.ErrConflict, err)
		}
		return nil, err
	}
	saved, err := c.st.GetAIContextSetup(ctx, id)
	if err == nil {
		var plan AIContextSetupPreview
		if err := json.Unmarshal([]byte(saved.PlanJSON), &plan); err != nil {
			return nil, err
		}
		plan.Setup = saved
		return &plan, nil
	}
	if !errors.Is(err, store.ErrNotFound) {
		return nil, err
	}
	files, err := aicontext.PlanManagedSetup(r.Key, r.FullName, r.Config, source.Files)
	if err != nil {
		return nil, fmt.Errorf("%w: %s", auth.ErrInvalidInput, err)
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("%w: managed files already match; setup repair/reconciliation is required before another PR", auth.ErrInvalidInput)
	}
	plan := &AIContextSetupPreview{Revision: r.Revision, BaseCommit: source.Commit, Files: files}
	hashInputs, _ := json.Marshal(struct {
		Repository aicontext.RepositoryKey
		Name       string
		Revision   int64
		BaseCommit string
		Files      []aicontext.SetupChange
	}{r.Key, r.FullName, r.Revision, source.Commit, files})
	plan.PlanHash = aicontext.Hash(hashInputs)
	plan.Branch = fmt.Sprintf("zoomies-ai-context-setup-%d-%s", r.Key.RepositoryID, plan.PlanHash[:16])
	if encoded, _ := json.Marshal(plan); len(encoded) > 4<<20 {
		return nil, fmt.Errorf("%w: combined setup preview exceeds its size limit; shorten large README or instruction files before setup", auth.ErrInvalidInput)
	}
	return plan, nil
}

func (c *Controller) CreateAIContextSetupPR(ctx context.Context, id string, approval AIContextSetupApproval) (*AIContextSetupPreview, error) {
	plan, err := c.PreviewAIContextSetup(ctx, id)
	if err != nil {
		return nil, err
	}
	if approval.Revision != plan.Revision || approval.PlanHash != plan.PlanHash {
		return nil, store.ErrConflict
	}
	if plan.Setup != nil && plan.Setup.State == "awaiting_merge" {
		return plan, nil
	}
	r, err := c.st.GetAIContextRepository(ctx, id)
	if err != nil {
		return nil, err
	}
	client, source, err := c.contextSetupClient(ctx, r)
	if err != nil {
		return nil, err
	}
	if plan.Setup == nil && source.Commit != plan.BaseCommit {
		return nil, fmt.Errorf("%w: source branch changed after review; no repository writes were made", store.ErrConflict)
	}
	payload, _ := json.Marshal(plan)
	operation := &store.AIContextSetup{RepositoryID: id, Revision: plan.Revision, PlanHash: plan.PlanHash, PlanJSON: string(payload)}
	if err := c.st.ClaimAIContextSetup(ctx, operation); err != nil {
		return nil, err
	}
	return c.publishAIContextPlan(ctx, r, client, plan, operation)
}

func (c *Controller) publishAIContextPlan(ctx context.Context, r *store.AIContextRepository, client github.ContextSetupClient, plan *AIContextSetupPreview, operation *store.AIContextSetup) (*AIContextSetupPreview, error) {
	// An HTTP disconnect must not strand an otherwise finished PR. The
	// bounded operation is persisted first, and safe to reconcile after crash.
	detached, cancel := context.WithTimeout(context.WithoutCancel(ctx), 4*time.Minute)
	defer cancel()
	defer func() {
		cleanup, cancel := context.WithTimeout(context.WithoutCancel(ctx), 10*time.Second)
		defer cancel()
		_ = c.st.ReleaseAIContextSetup(cleanup, r.ID, operation.LeaseToken)
	}()
	pr, err := client.OpenContextSetup(detached, github.ContextSetupRequest{Action: plan.Mode, Repo: r.FullName, Base: r.Config.SourceBranch, BaseCommit: plan.BaseCommit, Head: plan.Branch, PlanHash: plan.PlanHash, Files: plan.Files})
	if err != nil {
		if errors.Is(err, github.ErrSetupConflict) {
			return nil, fmt.Errorf("%w: %s", store.ErrConflict, err)
		}
		return nil, err
	}
	if err := c.st.CompleteAIContextSetup(detached, r.ID, operation.LeaseToken, pr.Number, pr.HTMLURL); err != nil {
		return nil, err
	}
	plan.Setup, err = c.st.GetAIContextSetup(detached, r.ID)
	return plan, err
}

package controller

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/aicontext"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// ErrAIContextUploadRefused is a valid Actions token that does not entitle
// this upload: the wrong workflow, branch, event or commit. The wrapped text
// says which, for the workflow log; it never carries source.
var ErrAIContextUploadRefused = errors.New("this upload is not from the repository's managed workflow on its trusted branch")

// ErrAIContextUploadSuperseded is an upload for a commit that is no longer the
// head of the trusted branch, or a token that has already been used. Either
// way a later run is the one that counts.
var ErrAIContextUploadSuperseded = errors.New("this upload has been superseded")

var commitSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)

// SetActionsIssuer points upload verification at another OIDC issuer. Tests
// use it with github.NewFakeActionsIssuer; production keeps GitHub's.
func (c *Controller) SetActionsIssuer(issuer string) {
	c.actionsTokens = github.NewActionsTokenVerifier(issuer)
}

// CheckAIContextUploadToken verifies an upload's token alone, so the API can
// refuse a stranger before reading a body of up to 32 MiB. The full check runs
// again in IngestAIContextUpload; the keys are cached, so that costs nothing.
func (c *Controller) CheckAIContextUploadToken(ctx context.Context, rawToken, audience string) error {
	_, err := c.actionsTokens.Verify(ctx, rawToken, audience)
	return err
}

// IngestAIContextUpload admits a Zoomies-only snapshot. The token proves which
// repository, branch, commit and workflow file ran; everything the Both mode
// checks on a generated branch is then checked here too, against GitHub.
// Nothing about the request body is trusted until all of that holds.
func (c *Controller) IngestAIContextUpload(ctx context.Context, rawToken, audience string, body []byte) (*store.AIContextRepository, error) {
	claims, err := c.actionsTokens.Verify(ctx, rawToken, audience)
	if err != nil {
		return nil, err
	}
	numericID, err := strconv.ParseInt(claims.RepositoryID, 10, 64)
	if err != nil || numericID <= 0 {
		return nil, fmt.Errorf("%w: the token names no repository", ErrAIContextUploadRefused)
	}
	r, err := c.st.FindAIContextUploadTarget(ctx, "github.com", numericID)
	if err != nil {
		return nil, err
	}
	// The configuration fixes the audience. A token minted for this address
	// still has to belong to a repository whose reviewed workflow names it.
	if r.Config.UploadURL != audience {
		return nil, fmt.Errorf("%w: the repository's configuration names another upload address", ErrAIContextUploadRefused)
	}
	branch := r.Config.SourceBranch
	trustedRef := "refs/heads/" + branch
	workflow := "/.github/workflows/zoomies-ai-context.yml@" + trustedRef
	switch {
	case claims.Ref != trustedRef:
		return nil, fmt.Errorf("%w: it ran on %q, not the trusted branch %q", ErrAIContextUploadRefused, claims.Ref, branch)
	case claims.EventName != "push" && claims.EventName != "workflow_dispatch":
		return nil, fmt.Errorf("%w: it was started by %q; only a push or a manual run of the trusted branch may upload", ErrAIContextUploadRefused, claims.EventName)
	// Repository names are case-insensitive on GitHub; the ref after them is not.
	case !strings.HasSuffix(claims.JobWorkflowRef, workflow) ||
		!strings.EqualFold(strings.TrimSuffix(claims.JobWorkflowRef, workflow), r.FullName):
		return nil, fmt.Errorf("%w: it came from %q, not the managed workflow", ErrAIContextUploadRefused, claims.JobWorkflowRef)
	case !commitSHA.MatchString(claims.SHA):
		return nil, fmt.Errorf("%w: the token names no commit", ErrAIContextUploadRefused)
	}
	if err := c.st.ClaimAIContextUploadToken(ctx, claims.ID, r.ID, claims.Expiry); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return nil, fmt.Errorf("%w: this token has already been used", ErrAIContextUploadSuperseded)
		}
		return nil, err
	}
	snapshot, err := aicontext.Decode(bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("%w: the snapshot is not valid: %v", ErrAIContextUploadRefused, err)
	}
	if snapshot.Manifest.SourceCommit != claims.SHA {
		return nil, fmt.Errorf("%w: the snapshot is for another commit than the run that sent it", ErrAIContextUploadRefused)
	}

	select {
	case c.aiContextChecks <- struct{}{}:
		defer func() { <-c.aiContextChecks }()
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	client, source, err := c.trustedAIContext(ctx, r)
	if err != nil {
		_ = c.failAIContextCheck(ctx, r.ID, "unavailable", claims.SHA, "Repository setup or GitHub access could not be verified.")
		return nil, err
	}
	if source.Commit != claims.SHA {
		return nil, fmt.Errorf("%w: the trusted branch has moved on to a newer commit", ErrAIContextUploadSuperseded)
	}
	hash, _ := r.Config.Hash()
	err = snapshot.Match(r.Key, branch, source.Commit, hash)
	if err == nil {
		err = r.Config.CheckSourceFiles(snapshot.Files)
	}
	if err == nil && snapshot.Manifest.Generator != "repomix@1.18.1" {
		err = fmt.Errorf("context generator identity does not match its managed workflow")
	}
	if err == nil {
		err = client.VerifyContextSnapshot(ctx, r.FullName, branch, source.Commit, snapshot)
	}
	if err == nil {
		err = c.st.PublishAIContextSnapshot(ctx, r.ID, r.Revision, snapshot)
	}
	if err != nil {
		_ = c.failAIContextCheck(ctx, r.ID, "stale", source.Commit, "The uploaded context could not be verified. The previous snapshot is retained.")
		return nil, fmt.Errorf("%w: %v", ErrAIContextUploadRefused, err)
	}
	return c.st.GetAIContextRepository(ctx, r.ID)
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// measuredHost seeds a host whose agent has measured the machine and whose
// daemon has said it can apply every limit: the host a default allocation is
// computed for.
func (h *harness) measuredHost(name string, cpus int, memoryMB int64, capacity int, limits store.LimitSupport) *store.Host {
	h.t.Helper()
	host := &store.Host{
		Name:     name,
		Capacity: capacity,
		Backends: store.StringSlice{"docker"},
		BackendInfo: store.HostBackends{
			{Kind: store.BackendDocker, Available: true, Version: "27.1.1", Limits: limits},
		},
		Labels:        store.StringMap{},
		OS:            "linux",
		Arch:          "amd64",
		CPUs:          cpus,
		MemoryMB:      memoryMB,
		DiskTotalMB:   500 * 1024,
		DiskFreeMB:    400 * 1024,
		LastHeartbeat: h.c.Now(),
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		h.t.Fatalf("CreateHost: %v", err)
	}
	return host
}

var enforcesEverything = store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}

// A pool that sets no limits used to start runners with no limits at all, so
// eight of them on one host could each take every core. Now such a runner is
// given one slot's share of the host it lands on, the row says where the
// figure came from, and the task the agent receives carries the same share --
// the row and the container must never disagree about what a runner was
// given, because the row is what an operator reads after an OOM kill.
func TestAPoolWithNoLimitsGetsOneSlotsShareOfItsHost(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// Eight cores less the half-core floor is 7.5, and four slots of that is
	// 1.875, floored to the hundredth the pool form takes. Memory is the
	// machine less its reserve -- a twentieth of 16 GB, which is above the
	// flat floor -- in four.
	host := h.measuredHost("measured", 8, 16384, 4, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocatedCPUs != 1.87 || r.AllocatedMemoryMB != 3891 || r.AllocationSource != store.AllocationFromHost {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want 1.87, 3891 from %q",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource, store.AllocationFromHost)
	}
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec == nil {
		t.Fatal("the create task carries no spec")
	}
	if task.Spec.Resources.CPUs != 1.87 || task.Spec.Resources.MemoryMB != 3891 || task.Spec.ResourcesSource != store.AllocationFromHost {
		t.Fatalf("task spec = %+v from %q; the agent would apply something other than what the row records",
			task.Spec.Resources, task.Spec.ResourcesSource)
	}
	view := h.c.runnerView(h.ctx, r)
	if view.AllocatedCPUs != 1.87 || view.AllocatedMemoryMB != 3891 || view.AllocationSource != store.AllocationFromHost {
		t.Fatalf("runner view = %v CPUs, %d MB from %q; the Runners page cannot say what the runner was given",
			view.AllocatedCPUs, view.AllocatedMemoryMB, view.AllocationSource)
	}
}

// With defaults switched off the fleet behaves exactly as it did before they
// existed: a pool's own limits are the whole answer, and a pool with none
// starts an unlimited runner whose row says nothing about an allocation.
func TestDefaultLimitsOffLeavesARunnerUnlimited(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = false })
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	host := h.measuredHost("measured", 8, 16384, 4, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocatedCPUs != 0 || r.AllocatedMemoryMB != 0 || r.AllocationSource != "" {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want none with defaults off",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource)
	}
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec.Resources != (store.Resources{}) || task.Spec.ResourcesSource != "" {
		t.Fatalf("task spec = %+v from %q; want no limits with defaults off", task.Spec.Resources, task.Spec.ResourcesSource)
	}
	// And the host counts it among the runners nothing binds, which is the
	// count the CPU hold reads before it means anything.
	got, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.UnlimitedRunners != 1 || h.c.HostView(got).UnlimitedRunners != 1 {
		t.Fatalf("unlimited runners = %d (view %d), want 1", got.UnlimitedRunners, h.c.HostView(got).UnlimitedRunners)
	}
}

// A pool's own limits win over the default, and the row says they are the
// pool's: an operator who set memory_mb and sees an OOM kill should be sent
// to the pool, not to the host's capacity.
func TestAPoolsOwnLimitsAreRecordedAsThePools(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.measuredHost("measured", 8, 16384, 4, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	r := h.onlyRunner()
	if r.AllocatedCPUs != 2 || r.AllocatedMemoryMB != 4096 || r.AllocationSource != store.AllocationFromPool {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want the pool's 2 and 4096 from %q",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource, store.AllocationFromPool)
	}
}

// A pool with a minimum runs on a host a little short of its standard size,
// and the runner, the task and the view all say what it was actually given.
// The row is the one place the reduced size is written down: its host is
// charged from it, and an operator reading a slow job needs it.
func TestARunnerOnAShortHostIsGivenWhatItCanSpareAndSaysSo(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 32 * 1024, MinCPUs: 1, MinMemoryMB: 8 * 1024}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// 16 GB less its reserve is well short of 32 GB and well above 8.
	host := h.measuredHost("short", 8, 16384, 1, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocationSource != store.AllocationReduced {
		t.Fatalf("allocation source = %q, want %q", r.AllocationSource, store.AllocationReduced)
	}
	if r.AllocatedCPUs != 2 {
		t.Errorf("CPU = %v, want the standard 2: the host has room for it", r.AllocatedCPUs)
	}
	if r.AllocatedMemoryMB >= 32*1024 || r.AllocatedMemoryMB < 8*1024 {
		t.Errorf("memory = %d MB, want between the 8 GB minimum and the 32 GB standard", r.AllocatedMemoryMB)
	}
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec == nil || task.Spec.Resources.MemoryMB != r.AllocatedMemoryMB {
		t.Fatalf("task spec = %+v; the agent would apply something other than what the row records", task.Spec)
	}
	if task.Spec.Resources.MinCPUs != 0 || task.Spec.Resources.MinMemoryMB != 0 {
		t.Errorf("task spec carries the pool's minimum %+v; the agent is told a size, not a policy", task.Spec.Resources)
	}
}

// The report that found this: an automatic pool, a host with a free slot and
// most of a slot's worth idle, and no runner, because the pool only ever asked
// for a whole share. With a minimum it runs there, and the row, the task and
// the host's charge all carry what it was actually given.
func TestAnAutomaticPoolWithAMinimumRunsOnWhatIsLeftOfAHost(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	// 8 cores and 16 GB over two slots; a fixed pool's runner takes 5 cores
	// and 10 GB of it first, which is more than a slot's share.
	host := h.measuredHost("shared", 8, 16384, 2, enforcesEverything)
	big := h.pool(inst, "big", "big")
	big.MinRunners = 1
	big.Resources = store.Resources{CPUs: 5, MemoryMB: 10 * 1024}
	if err := h.st.UpdatePool(h.ctx, big); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	auto := h.pool(inst, "auto", "auto")
	auto.MinRunners = 1
	auto.Resources = store.Resources{MinCPUs: 1, MinMemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, auto); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	runners, _, err := h.st.ListRunners(h.ctx, store.RunnerFilter{PoolIDs: []string{auto.ID}}, store.Page{})
	if err != nil {
		t.Fatalf("ListRunners: %v", err)
	}
	if len(runners) != 1 {
		t.Fatalf("the automatic pool has %d runners, want 1 on the host's free slot", len(runners))
	}
	r := runners[0]
	if r.AllocationSource != store.AllocationReduced {
		t.Fatalf("allocation source = %q, want %q", r.AllocationSource, store.AllocationReduced)
	}
	if r.AllocatedMemoryMB < 2048 || r.AllocatedMemoryMB >= 8*1024 {
		t.Errorf("memory = %d MB, want at least the 2 GB minimum and less than a whole 8 GB share", r.AllocatedMemoryMB)
	}
	var task *agent.Task
	for _, tk := range h.tasksFor(host.ID) {
		if tk.Kind == agent.TaskCreateRunner && tk.RunnerID == r.ID {
			task = &tk
		}
	}
	if task == nil || task.Spec == nil || task.Spec.Resources.MemoryMB != r.AllocatedMemoryMB || task.Spec.Resources.CPUs != r.AllocatedCPUs {
		t.Fatalf("task = %+v; the agent would apply something other than what the row records", task)
	}
}

// A fleet minimum above a host's slot share is what a runner of a pool that
// follows it is given, row and task alike: the minimum is the least a runner
// may have, and a thinner share is raised to it rather than handed out. The
// fleet figure is not copied into the pool to get there -- the pool keeps
// following the setting.
func TestAFleetMinimumAboveTheShareIsWhatTheRunnerIsGiven(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Runners.MinimumMemoryMB = 6144 })
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 1
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// The same machine as TestAPoolWithNoLimitsGetsOneSlotsShareOfItsHost: a
	// share of 3891 MB, under the 6 GB the fleet says a runner may not go
	// below.
	host := h.measuredHost("measured", 8, 16384, 4, enforcesEverything)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	r := h.onlyRunner()
	if r.AllocatedMemoryMB != 6144 || r.AllocatedCPUs != 1.87 || r.AllocationSource != store.AllocationFromHost {
		t.Fatalf("row allocation = %v CPUs, %d MB from %q; want the 1.87 CPU share and the 6144 MB minimum from %q",
			r.AllocatedCPUs, r.AllocatedMemoryMB, r.AllocationSource, store.AllocationFromHost)
	}
	task := h.taskOfKind(host.ID, agent.TaskCreateRunner)
	if task.Spec == nil || task.Spec.Resources.MemoryMB != 6144 {
		t.Fatalf("task spec = %+v; the agent would apply something other than the row's 6144 MB", task.Spec)
	}
	stored, err := h.st.GetPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatalf("GetPool: %v", err)
	}
	if stored.Resources.MinMemoryMB != 0 {
		t.Errorf("the pool's own minimum is %d MB, want 0: it follows the fleet", stored.Resources.MinMemoryMB)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The housekeeping cadences. They share one goroutine and one ticker: none of
// this work is urgent, and three timers would be three things to reason about
// at shutdown instead of one.
const (
	housekeepingTick = 30 * time.Second
	pruneInterval    = time.Hour
)

// backgroundLoop runs the periodic work: the fleet sampler behind the
// Overview's sparklines, retention pruning, credential expiry, the image
// refresh that keeps a moving tag current on the hosts, the release check
// behind the update notice, and the sweep that re-offers tasks whose agent
// never answered.
func (c *Controller) backgroundLoop(ctx context.Context) {
	ticker := time.NewTicker(housekeepingTick)
	defer ticker.Stop()

	var last housekeeping
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		c.housekeep(ctx, &last)
	}
}

// housekeeping remembers when each of the slower jobs last ran, so that one
// ticker can pace work that wants a minute, an hour and a day apart.
type housekeeping struct {
	sample, prune, imageRefresh, updateCheck, toolchainScan time.Time
}

// housekeep is one pass of the background loop, pulled out of the ticker so
// that a test can run a pass without waiting for one.
func (c *Controller) housekeep(ctx context.Context, last *housekeeping) {
	now := c.Now()
	c.sweepTasks(ctx, now)
	c.checkHostHealth(ctx)
	c.settleThrottles(ctx, now)
	c.expireStaleQueuedJobs(ctx, now)
	// A host going quiet is a problem and a capacity change, and neither
	// waits for the next reconcile pass to be told about.
	c.publishDerived(ctx)

	// The minute is the unit: the store keys a sample on it and the chart
	// draws a point per minute, so the sampler has to land in every one.
	// Firing "once sixty seconds have passed" from a thirty-second ticker
	// looked the same and was not: a tick that arrived a few milliseconds
	// short of the minute skipped, the next one wrote, and the rows fell
	// ninety seconds apart -- every third minute on the chart an empty slot.
	// Firing when the minute has changed puts a row in each, whatever the
	// ticker's jitter, and the store's upsert makes a second pass in the same
	// minute harmless.
	if now.Truncate(time.Minute).After(last.sample.Truncate(time.Minute)) {
		last.sample = now
		if err := c.sample(ctx); err != nil {
			c.log.Warn("could not record a fleet sample", "error", err)
		}
	}
	if now.Sub(last.prune) >= pruneInterval {
		last.prune = now
		c.prune(ctx)
	}
	// The zero time is deliberately allowed to fire on the first tick: a
	// controller that has just come back up has no idea what moved while it
	// was down, and the pass is idempotent.
	if d := c.cfg().Images.RefreshInterval; d > 0 && now.Sub(last.imageRefresh) >= d {
		last.imageRefresh = now
		c.refreshPoolImages(ctx)
	}
	if d := c.cfg().Updates.CheckInterval; d > 0 && now.Sub(last.updateCheck) >= d {
		last.updateCheck = now
		c.checkForRelease(ctx)
	}
	// In the background, on the loop's own context so shutdown stops it: a
	// scan takes minutes on a large organisation, and this pass must not.
	// One already running -- started by hand -- is the answer, and this tick
	// is not retried.
	if d := c.cfg().GitHub.ToolchainScanInterval; d > 0 && now.Sub(last.toolchainScan) >= d {
		last.toolchainScan = now
		if err := c.startToolchainScan(ctx, false); err != nil && !errors.Is(err, ErrToolchainScanRunning) {
			c.log.Warn("could not start the scheduled toolchain scan", "error", err)
		}
	}
}

// refreshPoolImages prewarms every pool's image again on the hosts that can run
// it, so that a pool naming a moving tag picks up a rebuilt image without
// anyone touching the pool.
//
// Prewarming is otherwise only triggered by a pool being created, edited or
// prewarmed by hand, which means a moving image -- :dev on each main build or
// :latest on each full release -- would reach a host once and never again.
//
// Nothing here can affect scheduling: PrewarmPool records its outcome per host
// and queues an idempotent task, and a host that cannot reach the registry
// fails that task alone. The runners it is already running are untouched, and
// so is the image any of them was created from; a container keeps the image it
// started with until it is replaced.
func (c *Controller) refreshPoolImages(ctx context.Context) {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools to refresh their images", "error", err)
		return
	}
	var refreshed, hosts int
	for _, p := range pools {
		n, err := c.PrewarmPool(ctx, p)
		switch {
		case errors.Is(err, ErrPrewarmUnsupported):
			// A process-backend pool has no image to pull; its runners fetch
			// the actions/runner archive themselves.
			continue
		case err != nil:
			c.log.Warn("could not refresh a pool's image", "pool", p.ID, "error", err)
			continue
		}
		if n > 0 {
			refreshed++
			hosts += n
		}
	}
	if refreshed > 0 {
		c.log.Debug("queued an image refresh", "pools", refreshed, "hosts", hosts)
	}
}

// sweepTasks re-offers tasks whose lease expired without a result.
//
// Delivery is at-least-once and every task is idempotent, so a redelivery
// costs the agent a no-op. The alternative -- assuming one delivery is enough
// -- means a runner that was never created and nothing to say why.
func (c *Controller) sweepTasks(ctx context.Context, now time.Time) {
	for hostID, q := range c.queues.all() {
		requeued, dropped := q.sweep(now)
		if requeued > 0 {
			c.log.Warn("re-queued tasks a host never reported on",
				"host", hostID, "tasks", requeued)
		}
		if len(dropped) == 0 {
			continue
		}
		c.log.Error("gave up redelivering tasks to a host",
			"host", hostID, "tasks", len(dropped), "attempts", maxTaskAttempts)
		for _, task := range dropped {
			if task.Kind == agent.TaskRemoveRunner {
				if r, err := c.st.GetRunner(ctx, task.RunnerID); err == nil {
					c.noteCleanupFailure(ctx, r, task.Kind, "host did not confirm removal; cleanup will be retried")
				}
				continue
			}
			// A dropped create is noticed by the runner's provision timeout,
			// which says so on the Runners page. A dropped stop is noticed by
			// nothing: the runner would sit in draining for ever, counted
			// against its pool's maximum and holding a slot on its host, so
			// it is failed here and the next pass frees the slot.
			if task.Kind != agent.TaskStopRunner {
				continue
			}
			reason := fmt.Sprintf("the host never confirmed stopping this runner after %d deliveries; it is presumed gone", maxTaskAttempts)
			if err := c.failRunnerID(ctx, task.RunnerID, reason, store.FaultRunnerExited); err != nil &&
				!errors.Is(err, store.ErrNotFound) && !errors.Is(err, store.ErrInvalidTransition) {
				c.log.Warn("could not fail a runner whose stop was never confirmed", "runner", task.RunnerID, "error", err)
			}
		}
	}
}

// sample writes one point for the Overview's sparklines. RecordSample keys on
// the minute, so a restart mid-minute overwrites rather than double-counts.
func (c *Controller) sample(ctx context.Context) error {
	counts, err := c.st.CountRunnersByPool(ctx)
	if err != nil {
		return err
	}
	var s store.FleetSample
	s.At = c.Now()
	for _, pc := range counts {
		s.IdleRunners += pc.Idle
		s.BusyRunners += pc.Busy
		s.TotalRunners += pc.Live()
	}
	stats, err := c.st.StatsSince(ctx, c.Now().Add(-time.Hour), false)
	if err != nil {
		return err
	}
	s.QueuedJobs, s.RunningJobs = stats.Queued, stats.Running
	// The fleet's own figures are recorded alongside, so the Overview's
	// sparkline can follow its "other runners" toggle rather than making the
	// line disagree with the tile above it.
	fleet, err := c.st.StatsSince(ctx, c.Now().Add(-time.Hour), true)
	if err != nil {
		return err
	}
	s.FleetQueuedJobs, s.FleetRunningJobs = fleet.Queued, fleet.Running
	if err := c.st.RecordSample(ctx, s); err != nil {
		return err
	}
	return c.sampleHosts(ctx, s.At)
}

// sampleHosts writes the same minute for every host: its slots, what its
// agent last measured, and what the scheduler has promised away on it. It is
// what lets the Hosts page say whether "CPU 93%" is a spike or the whole
// afternoon, which a card with one number cannot.
//
// A measurement older than HostUsageMaxAge is left out rather than carried
// forward. A host that stopped reporting would otherwise draw a flat line at
// its last reading, and a flat line is exactly what a healthy, quiet machine
// draws too.
func (c *Controller) sampleHosts(ctx context.Context, now time.Time) error {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return err
	}
	samples := make([]store.HostSample, 0, len(hosts))
	for _, h := range hosts {
		samples = append(samples, c.hostSample(h, now))
	}
	return c.st.RecordHostSamples(ctx, samples)
}

// hostSample is one host as one row of history, from the same figures the
// host's view is rendered from, so the newest point of the chart and the card
// beside it never disagree.
func (c *Controller) hostSample(h *store.Host, now time.Time) store.HostSample {
	alloc := h.Allocatable()
	s := store.HostSample{
		HostID:              h.ID,
		At:                  now,
		Capacity:            h.EffectiveCapacity(),
		ActiveRunners:       h.ActiveRunners,
		CPUs:                int64(h.CPUs),
		MemoryMB:            h.MemoryMB,
		AllocatableCPUs:     alloc.CPUs,
		AllocatableMemoryMB: alloc.MemoryMB,
		DiskTotalMB:         h.DiskTotalMB,
		DiskFreeMB:          h.DiskFreeMB,
	}
	if h.Usage.Fresh(now) {
		s.CPUPercent = h.Usage.CPUPercent
		s.LoadAverage1 = h.Usage.LoadAverage1
		s.MemoryAvailableMB = h.Usage.MemoryAvailableMB
	}
	if res, ok := c.reservedOn(h.ID); ok {
		cpus, mem := res.CPUs, res.MemoryMB
		s.ReservedCPUs = &cpus
		s.ReservedMemoryMB = &mem
	}
	return s
}

// prune enforces the retention windows and expires credentials.
//
// Every deletion is logged at debug with a count, because "where did my job
// history go?" should be answerable from the log rather than from reading this
// function.
func (c *Controller) prune(ctx context.Context) {
	now := c.Now()
	r := c.cfg().Retention

	// The roll-up goes first: it is computed from the sessions, and the
	// sessions prune below refuses to delete any it has not absorbed, so a
	// pass that ran them the other way round would only prune less. Running it
	// with every retention off costs one small transaction a pass and means
	// switching a retention on later loses nothing.
	if n, err := c.st.RollUpUsage(ctx, now); err != nil {
		c.log.Warn("could not roll up usage", "error", err)
	} else if n > 0 {
		c.log.Debug("rolled up usage", "days", n)
	}
	// The installation report's counts are rolled up the same way, before
	// the job and session rows they are counted from can go. A job still
	// unfinished when the jobs prune would take it no longer holds its day
	// open: it is counted as what it was, because it is about to be deleted.
	var settled time.Time
	if r.Jobs > 0 {
		settled = now.Add(-r.Jobs)
	}
	if n, err := c.st.RollUpInstallations(ctx, now, settled); err != nil {
		c.log.Warn("could not roll up the installation report", "error", err)
	} else if n > 0 {
		c.log.Debug("rolled up the installation report", "days", n)
	}
	// Neither the jobs nor the sessions a day is counted from are pruned
	// before that day is in the roll-up. A failed roll-up above therefore
	// prunes less this pass, never loses a count.
	counted, countedErr := c.st.InstallationRollupUntil(ctx)
	if countedErr != nil {
		c.log.Warn("could not read the installation roll-up", "error", countedErr)
	}
	heldBack := func(fn func(context.Context, time.Time) (int64, error)) func(context.Context, time.Time) (int64, error) {
		return func(ctx context.Context, before time.Time) (int64, error) {
			if countedErr != nil {
				return 0, nil
			}
			if counted.Before(before) {
				before = counted
			}
			return fn(ctx, before)
		}
	}

	type job struct {
		what   string
		window time.Duration
		fn     func(context.Context, time.Time) (int64, error)
	}
	for _, j := range []job{
		{"jobs", r.Jobs, heldBack(c.st.PruneJobs)},
		{"runners", r.Runners, func(ctx context.Context, before time.Time) (int64, error) {
			// Each pruned row is announced, or the Runners page keeps showing
			// runners that no longer exist until it is reloaded.
			ids, err := c.st.PruneRunners(ctx, before)
			c.publishRunnersDeleted(ids)
			return int64(len(ids)), err
		}},
		{"runner sessions", r.RunnerSessions, heldBack(c.st.PruneRunnerSessions)},
		{"fleet samples", r.Samples, c.st.PruneSamples},
		{"host samples", r.Samples, c.st.PruneHostSamples},
		{"webhook deliveries", r.Webhooks, c.st.PruneDeliveries},
		// The audit rows themselves have no prune: an audit trail a process can
		// quietly delete is not one, so store deliberately offers no way.
		{"scaling events", r.ScalingEvents, c.st.PruneScalingEvents},
		// Only the machines that cannot be about anything live: a failed
		// machine still naming a resource is never pruned, however old, because
		// the row is the only record that something was rented and may still be
		// running. PruneMachines enforces that; this announces what went.
		{"machines", r.Machines, func(ctx context.Context, before time.Time) (int64, error) {
			n, ids, err := c.st.PruneMachines(ctx, before)
			c.publishMachinesDeleted(ids)
			return n, err
		}},
		{"usage capacity", r.Jobs, c.st.PruneUsageCapacity},
	} {
		// A zero or negative window means "keep everything", which is what an
		// operator who cleared the setting meant.
		if j.window <= 0 {
			continue
		}
		n, err := j.fn(ctx, now.Add(-j.window))
		if err != nil {
			c.log.Warn("could not prune history", "what", j.what, "error", err)
			continue
		}
		if n > 0 {
			c.log.Debug("pruned history", "what", j.what, "rows", n, "older_than", j.window)
		}
	}

	if n, err := c.st.PruneSessions(ctx, now); err != nil {
		c.log.Warn("could not prune expired sessions", "error", err)
	} else if n > 0 {
		c.log.Debug("pruned expired sessions", "rows", n)
	}
	if n, err := c.st.PruneOAuth(ctx, now); err != nil {
		c.log.Warn("could not prune expired MCP sign-ins", "error", err)
	} else if n > 0 {
		c.log.Debug("pruned expired MCP sign-ins", "rows", n)
	}
	if n, err := c.st.PruneJoinTokens(ctx, now); err != nil {
		c.log.Warn("could not prune expired join tokens", "error", err)
	} else if n > 0 {
		c.log.Debug("pruned expired join tokens", "rows", n)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
)

// The controller's own backups.
//
// A fleet whose only backup is the one an operator remembers to take is a
// fleet with no backup, so the controller takes one itself on the interval
// backup.interval sets, into the directory backup.directory names, and keeps
// backup.keep of them. It is the same copy `zoomies backup` writes and the
// settings page takes on demand: one layout, one manifest, one restore.
//
// A backup beside the database is a backup against a mistake and not against
// the disk, which is why a backup here is an event rather than a file. The
// whole of the event is: take the copy, apply retention to the directory, and
// reconcile every destination backup.remotes names. Whichever of the three
// asked for it gets all of it, because "the copy left the machine" is not
// something an operator should have to press a second button for and then
// remember to.

const (
	// backupTick is how often the loop asks whether a backup is due. A minute
	// is fine-grained enough that "every 24h" means what it says and coarse
	// enough that an idle controller does not read its backup directory a
	// thousand times an hour.
	backupTick = time.Minute
	// backupRetry is how long a failed scheduled backup waits before trying
	// again. Disk that is full at noon is usually still full at 12:01, and a
	// warning that re-fires every minute is a warning that gets muted.
	backupRetry = 15 * time.Minute
)

// backupState is what the loop knows about its own last attempt, kept in
// memory: the backups themselves are the durable record, and the problems
// drawer only needs to know whether the most recent attempt worked.
type backupState struct {
	mu sync.Mutex
	// running is held while a backup is in progress, whoever asked for it,
	// so that the scheduler and the settings page cannot take two at once.
	running bool
	// lastAttemptAt and lastError describe the last scheduled attempt. A
	// backup an operator takes by hand clears the error: the thing that was
	// failing has just worked.
	lastAttemptAt time.Time
	lastError     string
	lastID        string

	// shipping is held while an offsite pass is running, whoever asked for
	// it, and remotes is what became of each destination, keyed by its name.
	// They share this mutex because they are read together: the Backups tab
	// asks one question and gets the schedule and every bucket in one answer.
	shipping bool
	remotes  map[string]*remoteState
	// ship is the nudge a finished backup gives the loop, so a copy reaches
	// the bucket in the minute it was taken rather than at the next sweep.
	// Capacity 1: it is a flag, not a queue.
	ship chan struct{}
}

// BackupStatus is the state of scheduled backups, for the settings page and
// the problems drawer.
type BackupStatus struct {
	// Directory is where backups are kept, resolved.
	Directory string `json:"directory"`
	// Interval is backup.interval; zero means scheduled backups are off.
	Interval time.Duration `json:"-"`
	// Keep is backup.keep.
	Keep int `json:"keep"`
	// Running says a backup is being taken right now.
	Running bool `json:"running"`
	// LastScheduledAt is when the loop last tried, LastScheduledID what it
	// wrote, and LastError why it did not.
	LastScheduledAt time.Time `json:"-"`
	LastScheduledID string    `json:"last_scheduled_id,omitempty"`
	LastError       string    `json:"last_error,omitempty"`
	// NextDueAt is when the next scheduled backup is expected, from the
	// newest backup in the directory and the interval. Zero when off.
	NextDueAt time.Time `json:"-"`
}

// BackupDir is where this controller keeps its backups.
func (c *Controller) BackupDir() string { return backup.Dir(c.cfg()) }

// TakeBackup takes a backup now, on behalf of whoever asked, and applies
// retention afterwards.
//
// One at a time. The store serialises the copy itself, but two callers racing
// for the same second would race for the same directory name too, and a
// backup and a prune interleaved could delete the copy being taken.
func (c *Controller) TakeBackup(ctx context.Context, source, by string) (*backup.Entry, error) {
	if !c.beginBackup() {
		return nil, ErrBackupRunning
	}
	defer c.endBackup()

	cfg := c.cfg()
	entry, err := backup.Take(ctx, c.st, backup.TakeOptions{
		Config: cfg, Source: source, TakenBy: by, Now: c.clock,
	})
	if err != nil {
		return nil, err
	}
	// Retention runs after a backup the controller took, whatever asked for
	// it: a backup taken from the page is the same kind of copy as one the
	// schedule took, and the ceiling is the ceiling. Uploads are never
	// counted or removed, which Prune itself guarantees.
	if removed, err := backup.Prune(backup.Dir(cfg), cfg.Backup.Keep); err != nil {
		c.log.Warn("could not remove old backups", "dir", backup.Dir(cfg), "error", err)
	} else if len(removed) > 0 {
		c.log.Info("removed old backups", "removed", len(removed), "keep", cfg.Backup.Keep)
	}
	c.log.Info("took a backup", "id", entry.ID, "source", source, "bytes", entry.Bytes, "dir", entry.Dir)
	// The copy exists; getting it off the machine is the backup loop's next
	// pass rather than this caller's wait. An operator pressing the button
	// should not hold a browser open for the length of an upload, and the
	// schedule should not skip a night because a bucket was slow.
	c.nudgeRemotes()
	return entry, nil
}

// BackupPruning is what applying retention removed, here and in each bucket.
//
// It is reported per destination rather than as a total because the numbers
// disagree on purpose: this host keeps backup.keep copies and each remote
// keeps its own, so "three here, thirty offsite" is a correct fleet and a
// single count would read like a fault.
type BackupPruning struct {
	// Keep is backup.keep as the pass read it. Zero keeps every copy, and
	// nothing is removed from this host at all.
	Keep int `json:"keep"`
	// Removed is what was deleted from the backup directory. Copies somebody
	// uploaded or pulled back out of a bucket are never in it: Prune itself
	// guarantees that, because a copy that arrived here is not one this fleet
	// took and retention has no claim on it.
	Removed []string `json:"removed"`
	// Error is why the directory could not be pruned, in the words the
	// filesystem used.
	Error string `json:"error,omitempty"`
	// Remotes is the same pass over each destination.
	Remotes []RemotePruning `json:"remotes"`
}

// RemotePruning is what retention removed from one destination.
type RemotePruning struct {
	Name string `json:"name"`
	// Keep is this destination's own retention; zero keeps every copy.
	Keep    int      `json:"keep"`
	Removed []string `json:"removed"`
	// Error is the service's own refusal, so a bucket that would not answer
	// reads differently from one that had nothing to remove.
	Error string `json:"error,omitempty"`
}

// PruneBackups applies retention now, to this host's directory and to every
// destination, and reports what went.
//
// Retention otherwise runs as part of a backup, which is the right moment for
// it and the wrong one for an operator who has just lowered backup.keep from
// thirty to seven: nothing at all happens until the next backup, and on a
// fleet with the schedule off that is never. So this exists, it is deliberate,
// and it says what it deleted rather than reporting a tidy success.
//
// Whatever cannot be pruned is recorded against the thing that refused and the
// pass carries on: one bucket with a wrong credential must not leave the
// others full.
func (c *Controller) PruneBackups(ctx context.Context) (BackupPruning, error) {
	cfg := c.cfg()
	out := BackupPruning{Keep: cfg.Backup.Keep, Removed: []string{}, Remotes: []RemotePruning{}}

	// The directory is pruned under the lock a backup takes, for the reason
	// TakeBackup holds it: a prune interleaved with a copy being written
	// could count a directory that is not finished yet.
	if !c.beginBackup() {
		return out, ErrBackupRunning
	}
	removed, err := backup.Prune(backup.Dir(cfg), cfg.Backup.Keep)
	c.endBackup()
	out.Removed = append(out.Removed, removed...)
	if err != nil {
		out.Error = err.Error()
		c.log.Warn("could not remove old backups", "dir", backup.Dir(cfg), "error", err)
	} else if len(removed) > 0 {
		c.log.Info("removed old backups", "removed", len(removed), "keep", cfg.Backup.Keep)
	}

	// And then the buckets, under the offsite pass's own lock: a prune that
	// ran beside an upload could delete the copy being sent.
	configured := c.usableBackupRemotes(ctx)
	if len(configured) == 0 {
		return out, nil
	}
	if !c.beginShipping() {
		return out, ErrShippingRunning
	}
	defer c.endShipping()
	for _, entry := range configured {
		item := RemotePruning{Name: entry.Remote.Name, Keep: entry.Remote.Keep, Removed: []string{}}
		remote, err := backup.NewRemote(entry.Remote, c.backupHTTP)
		if err != nil {
			item.Error = err.Error()
			out.Remotes = append(out.Remotes, item)
			continue
		}
		gone, err := remote.Prune(ctx, remote.Keep())
		item.Removed = append(item.Removed, gone...)
		if err != nil {
			item.Error = err.Error()
			c.noteRemoteFailure(entry.Remote.Name, err, c.Now)
		} else if len(gone) > 0 {
			c.log.Info("removed old copies from a backup remote",
				"remote", entry.Remote.Name, "removed", len(gone), "keep", remote.Keep())
			// What the page says this bucket holds was counted before the
			// prune. Read it once more so the figure the operator is shown
			// after pressing the button is the one they just changed.
			if held, err := remote.List(ctx); err == nil {
				var bytes int64
				for _, one := range held {
					bytes += one.Bytes
				}
				c.NoteRemoteListing(entry.Remote.Name, len(held), bytes)
			}
		}
		out.Remotes = append(out.Remotes, item)
	}
	return out, nil
}

// ErrBackupRunning is a second backup asked for while one is being taken.
var ErrBackupRunning = errors.New("controller: a backup is already being taken; wait for it to finish")

func (c *Controller) beginBackup() bool {
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	if c.backups.running {
		return false
	}
	c.backups.running = true
	return true
}

func (c *Controller) endBackup() {
	c.backups.mu.Lock()
	c.backups.running = false
	c.backups.mu.Unlock()
}

// BackupStatus reports the schedule and its last outcome.
func (c *Controller) BackupStatus() BackupStatus {
	cfg := c.cfg()
	c.backups.mu.Lock()
	out := BackupStatus{
		Directory:       backup.Dir(cfg),
		Interval:        cfg.Backup.Interval,
		Keep:            cfg.Backup.Keep,
		Running:         c.backups.running,
		LastScheduledAt: c.backups.lastAttemptAt,
		LastScheduledID: c.backups.lastID,
		LastError:       c.backups.lastError,
	}
	c.backups.mu.Unlock()
	if out.Interval > 0 {
		out.NextDueAt = c.nextBackupDue(cfg)
		if out.NextDueAt.IsZero() {
			out.NextDueAt = c.Now()
		}
	}
	return out
}

// nextBackupDue is when the schedule next wants a backup: the newest copy the
// fleet took of itself, plus the interval. A backup somebody uploaded or
// pulled back out of a bucket does not count -- it is a copy that arrived
// here, not evidence this fleet has been backing itself up. The zero time
// means there is no such copy, so one is due now.
func (c *Controller) nextBackupDue(cfg *config.Config) time.Time {
	entries, err := backup.List(backup.Dir(cfg))
	if err != nil {
		return time.Time{}
	}
	for _, e := range entries {
		if e.Source == backup.SourceUploaded || e.Source == backup.SourceFetched || e.Problem != "" {
			continue
		}
		return e.TakenAt.Add(cfg.Backup.Interval)
	}
	return time.Time{}
}

// backupLoop takes the scheduled backups.
//
// It is its own loop rather than a housekeeping step: VACUUM INTO on a large
// database takes as long as it takes, and the housekeeping pass has a host
// health check in it that should not wait for a copy to finish.
func (c *Controller) backupLoop(ctx context.Context) {
	ticker := time.NewTicker(backupTick)
	defer ticker.Stop()
	for {
		nudged := false
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		case <-c.backups.ship:
			nudged = true
		}
		c.backupPass(ctx, nudged)
	}
}

// backupPass is one turn of the loop, pulled out so a test can run one without
// waiting for a tick.
func (c *Controller) backupPass(ctx context.Context, nudged bool) {
	if !nudged {
		c.scheduledBackup(ctx)
		// A backup taken in this pass left its own nudge behind. Take it here
		// rather than at some later tick: a scheduled backup is a backup event
		// like any other, and the copies leave with it.
		nudged = c.tookNudge()
	}
	// And then the copies that leave the machine. A nudge means a backup has
	// just been taken and there is something to send; a tick means checking
	// whether a remote that was unreachable has come back.
	if nudged || c.remotesDue(ctx, c.Now()) {
		c.shipScheduled(ctx)
	}
}

// tookNudge reports whether a nudge was waiting, and takes it.
func (c *Controller) tookNudge() bool {
	select {
	case <-c.backups.ship:
		return true
	default:
		return false
	}
}

// shipScheduled is the loop's offsite pass. Its failures are already recorded
// against each remote, where the page and the problems drawer read them, so
// nothing is logged twice here.
//
// Whether there is anywhere to send a copy is ShipBackups' question rather
// than this one's, and that is the point: the pass used to ask the
// configuration file, which cannot see a destination an operator added on the
// Backups page. A fleet whose only destination was a stored one took its
// backups every night and never sent one, while the page showed a healthy
// bucket and a button that worked when pressed -- the worst way for this to
// fail, because everything an operator could see said it was working.
func (c *Controller) shipScheduled(ctx context.Context) {
	_, err := c.ShipBackups(ctx)
	if errors.Is(err, ErrShippingRunning) {
		// Somebody pressed "copy offsite now" while this pass was being
		// asked for. Put the nudge back rather than dropping it: the reason
		// it exists is a backup that has just been taken, and a pass already
		// half-way through its own listing may not carry it.
		c.nudgeRemotes()
		return
	}
	if err != nil {
		c.log.Debug("the offsite copies did not all go", "error", err)
	}
}

// scheduledBackup is one pass of the loop, pulled out so a test can run one
// without waiting for a tick.
func (c *Controller) scheduledBackup(ctx context.Context) {
	cfg := c.cfg()
	if cfg.Backup.Interval <= 0 {
		return
	}
	now := c.Now()
	c.backups.mu.Lock()
	backingOff := c.backups.lastError != "" && now.Sub(c.backups.lastAttemptAt) < backupRetry
	c.backups.mu.Unlock()
	if backingOff {
		return
	}
	if due := c.nextBackupDue(cfg); !due.IsZero() && due.After(now) {
		return
	}

	entry, err := c.TakeBackup(ctx, backup.SourceScheduled, "the schedule")
	if errors.Is(err, ErrBackupRunning) {
		// Somebody is taking one by hand. That will satisfy the schedule.
		return
	}
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	c.backups.lastAttemptAt = now
	if err != nil {
		c.backups.lastError = err.Error()
		c.log.Warn("the scheduled backup failed", "error", err, "retry_in", backupRetry)
		return
	}
	c.backups.lastError = ""
	c.backups.lastID = entry.ID
}

// NoteManualBackup clears a scheduled failure: what was failing has just
// worked, and a warning about it would be stale.
func (c *Controller) NoteManualBackup() {
	c.backups.mu.Lock()
	c.backups.lastError = ""
	c.backups.mu.Unlock()
}

// backupProblems is what the drawer says about backups: a schedule that is
// failing, a restore that is waiting for a restart, and a restore that did not
// happen.
func (c *Controller) backupProblems(ctx context.Context) []Problem {
	var out []Problem
	status := c.BackupStatus()
	if status.LastError != "" {
		at := status.LastScheduledAt
		out = append(out, Problem{
			Code:     "backup.failed",
			Severity: config.SeverityWarning,
			Setting:  "backup.directory",
			Title:    "the scheduled backup is failing",
			Detail:   fmt.Sprintf("the last attempt, at %s, failed: %s. The controller tries again every %s.", at.Format(time.RFC3339), status.LastError, backupRetry),
			Fix:      "check that " + status.Directory + " exists, is writable by the controller, and has room for a copy of the database; or take one from the Backups tab and read the error there.",
			Since:    &at,
		})
	}
	dbPath := c.DatabasePath()
	if staged, err := backup.LoadStaged(dbPath); err == nil && staged != nil {
		at := staged.RequestedAt
		by := staged.RequestedBy
		if by == "" {
			by = "an administrator"
		}
		out = append(out, Problem{
			Code:     "backup.restore_staged",
			Severity: config.SeverityWarning,
			Title:    "a restore is waiting for the controller to restart",
			Detail: fmt.Sprintf("%s asked for %s to be restored. Nothing has changed yet: the database is swapped when the controller next starts, and until then the fleet runs on the database it has.", by, staged.BackupID) +
				" The restored fleet will come back fenced.",
			Fix:   "restart the controller from the Backups tab to apply it, or cancel it there.",
			Since: &at,
		})
	}
	out = append(out, c.remoteProblems(ctx)...)
	if outcome, err := backup.LastOutcome(dbPath); err == nil && outcome != nil && !outcome.OK {
		at := outcome.AttemptedAt
		out = append(out, Problem{
			Code:     "backup.restore_failed",
			Severity: config.SeverityError,
			Title:    "the last restore did not finish",
			Detail:   fmt.Sprintf("restoring %s at %s failed: %s", outcome.BackupID, at.Format(time.RFC3339), outcome.Error),
			Fix:      "read the reason, put right what it names, and stage the restore again from the Backups tab. Dismiss this from the same tab once it is understood.",
			Since:    &at,
		})
	}
	return out
}

// DatabasePath is the database the staged-restore files sit beside. It is the
// configured path rather than the store's own, because the store a test opens
// is in memory and has nowhere for a file to sit; in production the two are
// the same file.
func (c *Controller) DatabasePath() string { return c.cfg().Database.Path }

// ---------------------------------------------------------------------------
// Restarting
// ---------------------------------------------------------------------------

// RequestRestart asks the process to stop so that its service manager starts
// it again. It is how a staged restore is applied from the settings page: the
// restore has to happen with the database closed, and the only process that
// can close this controller's database is this controller, by exiting.
//
// It is a request, not a promise: whether the process comes back is up to
// whatever started it, which is why the page that presses it says what to do
// if nothing does.
func (c *Controller) RequestRestart(reason string) {
	c.restartOnce.Do(func() {
		c.restartReason = reason
		c.log.Warn("a restart was requested; the controller will stop and expects its service manager to start it again", "reason", reason)
		close(c.restart)
	})
}

// RestartRequested is closed once RequestRestart has been called.
func (c *Controller) RestartRequested() <-chan struct{} { return c.restart }

// Restarting reports whether a restart has been asked for, and why.
func (c *Controller) Restarting() (bool, string) {
	select {
	case <-c.restart:
		return true, c.restartReason
	default:
		return false, ""
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
)

// Getting the copies off the machine.
//
// The scheduled backup is a backup against a mistake. This is the other half:
// every copy the fleet takes is put in an S3-compatible bucket somebody else's
// disk is responsible for, because a directory of tidy copies on the volume
// that just died is the worst kind of backup -- everyone believed in it.
//
// The pass is written as "make the bucket hold what the directory holds"
// rather than "upload the backup that was just taken", and that is the whole
// design. A remote that was unreachable for two nights is two backups behind;
// a pass that only ever sent the newest would leave the gap there forever and
// nothing would say so. So every pass lists the remote, works out what is
// missing, sends it oldest first, and applies the remote's own retention
// afterwards.

const (
	// remoteSweep is how often the remotes are reconciled when nothing has
	// happened. Uploads are driven by taking a backup; this is the safety net
	// that catches up after an outage nobody watched, and it is slow because
	// listing a bucket is a request that costs money in some of them.
	remoteSweep = time.Hour
	// remoteRetry is how long a failed remote waits before it is tried again.
	// A bucket that refused the signature at noon refuses it at 12:01, and a
	// warning that re-fires every minute is a warning that gets muted.
	remoteRetry = 15 * time.Minute
	// remoteUploadTimeout bounds one pass over one remote: listing it,
	// sending what it is missing, and pruning it. It is generous because the
	// thing being sent is a whole database over a link nobody promised
	// anything about, and bounded because a transfer that has stalled must
	// not hold the pass open until the process restarts.
	remoteUploadTimeout = 6 * time.Hour
)

// The two places a destination is described, named here as the API serves
// them. They are internal/backup's, aliased so a handler reading this file
// does not have to go looking for where the merge lives.
const (
	RemoteSourceFile     = backup.OriginFile
	RemoteSourceDatabase = backup.OriginDatabase
)

// backupRemotes is every destination this fleet has: the file's and the
// stored ones, merged by internal/backup so the CLI and the controller agree
// about which wins.
func (c *Controller) backupRemotes(ctx context.Context) []backup.ResolvedRemote {
	resolved, _ := c.resolveBackupRemotes(ctx)
	return resolved
}

// resolveBackupRemotes is backupRemotes that also says whether it saw the whole
// configuration. It is false when the database would not answer, in which case
// only the file's destinations came back -- and a caller deciding what has
// left the configuration must not read that as every stored one having left.
func (c *Controller) resolveBackupRemotes(ctx context.Context) ([]backup.ResolvedRemote, bool) {
	resolved, err := backup.ResolveRemotes(ctx, c.cfg(), c.st, c.key)
	if err != nil {
		// The file's destinations are still returned, which is the half that
		// works when the database will not answer.
		c.log.Warn("could not read the stored backup remotes", "error", err)
	}
	return resolved, err == nil
}

// usableRemotes is the destinations a pass actually sends to.
func usableRemotes(resolved []backup.ResolvedRemote) []backup.ResolvedRemote {
	var out []backup.ResolvedRemote
	for _, r := range resolved {
		if r.Usable() {
			out = append(out, r)
		}
	}
	return out
}

// usableBackupRemotes is the destinations a pass actually sends to.
func (c *Controller) usableBackupRemotes(ctx context.Context) []backup.ResolvedRemote {
	return usableRemotes(c.backupRemotes(ctx))
}

// forgetGoneRemotes drops the state of a destination that is no longer in the
// configuration at all. Nothing ships to it, so its last attempt is never
// refreshed, and left in place it ages past the sweep and keeps the loop
// reconciling -- and listing every bucket that remains -- on every tick.
//
// Only a name that is gone goes. A switched-off, shadowed or unreadable
// destination is still on the page, and the page shows what its last listing
// found. And it does nothing unless the whole configuration was read: a
// database that briefly would not answer must not blank every stored remote.
func (c *Controller) forgetGoneRemotes(resolved []backup.ResolvedRemote, complete bool) {
	if !complete {
		return
	}
	named := make(map[string]bool, len(resolved))
	for _, r := range resolved {
		named[r.Remote.Name] = true
	}
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	for name, st := range c.backups.remotes {
		if !named[name] && !st.uploading {
			delete(c.backups.remotes, name)
		}
	}
}

// remoteState is what the controller knows about one destination. The bucket
// is the durable record; this is only what the page and the problems drawer
// need to say whether the last attempt worked.
type remoteState struct {
	uploading     bool
	lastAttemptAt time.Time
	lastUploadAt  time.Time
	lastUploadID  string
	lastError     string
	// held and heldBytes are what the last listing found, so the page can say
	// "7 copies, 412 MB" without a request of its own.
	held      int
	heldBytes int64
	listedAt  time.Time
}

// RemoteBackupStatus is one destination as the Backups tab and the problems
// drawer see it.
type RemoteBackupStatus struct {
	// Name is what this destination is called, and what the API addresses it
	// by.
	Name string `json:"name"`
	// Where is the bucket and prefix, and Endpoint the service, so an
	// operator can tell two buckets apart without opening the configuration.
	Where    string `json:"where"`
	Endpoint string `json:"endpoint"`
	// Encrypted says the archive is sealed before it leaves this host.
	Encrypted bool `json:"encrypted"`
	// Keep is this remote's own retention; 0 keeps every copy.
	Keep int `json:"keep"`
	// Disabled is a remote that is configured and switched off, which is
	// shown rather than hidden: a destination nobody can see is one nobody
	// notices has stopped.
	Disabled bool `json:"disabled"`
	// Source says where this destination is described -- "file" for
	// zoomies.yaml and the environment, "database" for one added on the page.
	// The page needs it to know what it may edit, and an operator needs it to
	// know where to go and change something.
	Source string `json:"source"`
	// ID is the stored destination's row id, empty for one the file
	// describes. Region, Bucket, Prefix and AccessKeyID are the rest of the
	// form, so the page can open an editor without a second request.
	ID          string `json:"id,omitempty"`
	Region      string `json:"region,omitempty"`
	Bucket      string `json:"bucket,omitempty"`
	Prefix      string `json:"prefix,omitempty"`
	AccessKeyID string `json:"access_key_id,omitempty"`
	// PathStyle is the tri-state: null asks for the style to be chosen from
	// the endpoint.
	PathStyle *bool `json:"path_style"`
	// Shadowed is a stored destination the file overrides by name. Nothing is
	// sent to it, and the page says why rather than leaving a row that
	// quietly does nothing.
	Shadowed bool `json:"shadowed"`
	// Problem is why this destination cannot be used at all -- almost always
	// that this controller's key does not open its stored secrets.
	Problem string `json:"problem,omitempty"`
	// HasSecretKey says a secret key is held for this destination. The secret
	// itself is never served: whether there is one is the only part of it a
	// page can act on.
	HasSecretKey bool `json:"has_secret_key"`
	// Uploading says something is being sent right now.
	Uploading bool `json:"uploading"`
	// Copies and Bytes are what the last listing found, and ListedAt when.
	Copies   int        `json:"copies"`
	Bytes    int64      `json:"bytes"`
	ListedAt *time.Time `json:"listed_at"`
	// LastUploadAt and LastUploadID are the last copy that reached it.
	LastUploadAt *time.Time `json:"last_upload_at"`
	LastUploadID string     `json:"last_upload_id,omitempty"`
	// LastError is why the last attempt did not work, in the words the
	// service used.
	LastError string `json:"last_error,omitempty"`
}

// remoteStates is the per-destination state, keyed by name, behind the backup
// state's own mutex: a name that leaves the configuration takes its state with
// it at the next pass.
func (c *Controller) remoteState(name string) *remoteState {
	if c.backups.remotes == nil {
		c.backups.remotes = map[string]*remoteState{}
	}
	st, ok := c.backups.remotes[name]
	if !ok {
		st = &remoteState{}
		c.backups.remotes[name] = st
	}
	return st
}

// BackupRemotes reports every destination this fleet has and what became of
// it: the file's first, then the stored ones.
func (c *Controller) BackupRemotes(ctx context.Context) []RemoteBackupStatus {
	resolved := c.backupRemotes(ctx)
	out := []RemoteBackupStatus{}
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	for _, entry := range resolved {
		r := entry.Remote
		status := RemoteBackupStatus{
			Name: r.Name, Where: r.Where(), Endpoint: r.Endpoint,
			Encrypted: r.Encrypted(), Keep: r.Keep, Disabled: !r.Enabled(),
			Source: entry.Origin, ID: entry.ID, Shadowed: entry.Shadowed, Problem: entry.Problem,
			Region: r.Region, Bucket: r.Bucket, Prefix: r.Prefix,
			AccessKeyID: r.AccessKeyID, PathStyle: r.PathStyle,
			HasSecretKey: strings.TrimSpace(r.SecretAccessKey) != "",
		}
		if st, ok := c.backups.remotes[r.Name]; ok && !entry.Shadowed {
			status.Uploading = st.uploading
			status.Copies = st.held
			status.Bytes = st.heldBytes
			status.LastUploadID = st.lastUploadID
			status.LastError = st.lastError
			if !st.listedAt.IsZero() {
				at := st.listedAt
				status.ListedAt = &at
			}
			if !st.lastUploadAt.IsZero() {
				at := st.lastUploadAt
				status.LastUploadAt = &at
			}
		}
		out = append(out, status)
	}
	return out
}

// RemoteBackup resolves one destination by name, for the handlers that list,
// fetch from or delete a copy in it.
func (c *Controller) RemoteBackup(ctx context.Context, name string) (*backup.Remote, error) {
	resolved, err := backup.FindResolvedRemote(ctx, c.cfg(), c.st, c.key, name)
	if err != nil {
		return nil, err
	}
	return backup.NewRemote(resolved.Remote, c.backupHTTP)
}

// CheckBackupRemote tests a destination that has not been saved yet, which is
// what makes the page's "test" button worth pressing before the credential is
// stored rather than after.
func (c *Controller) CheckBackupRemote(ctx context.Context, cfg config.BackupRemote) error {
	remote, err := backup.NewRemote(cfg, c.backupHTTP)
	if err != nil {
		return err
	}
	return remote.Check(ctx)
}

// NoteRemoteListing records what a listing found, so that a page which has
// just read a remote leaves the count behind for the page that has not.
func (c *Controller) NoteRemoteListing(name string, copies int, bytes int64) {
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	st := c.remoteState(name)
	st.held = copies
	st.heldBytes = bytes
	st.listedAt = c.Now()
}

// nudgeRemotes asks the backup loop to reconcile the remotes now. Capacity 1,
// like every other nudge in here: it is a flag saying there is something to
// send, not a queue of things to send.
func (c *Controller) nudgeRemotes() {
	select {
	case c.backups.ship <- struct{}{}:
	default:
	}
}

// NudgeBackupRemotes asks the backup loop to reconcile the destinations now.
// It is what a destination added or corrected on the page presses: waiting an
// hour to find out whether it works is the opposite of what an operator who
// has just typed a credential wants.
func (c *Controller) NudgeBackupRemotes() { c.nudgeRemotes() }

// ShipBackups makes every enabled remote hold what the backup directory holds,
// and returns what it sent.
//
// It is safe to call from anywhere: one pass at a time across the whole
// controller, so the loop's catch-up and an operator pressing "copy offsite
// now" cannot upload the same archive twice.
func (c *Controller) ShipBackups(ctx context.Context) ([]backup.Copy, error) {
	cfg := c.cfg()
	resolved, complete := c.resolveBackupRemotes(ctx)
	// Before the early return, so that deleting the last destination clears
	// its state too.
	c.forgetGoneRemotes(resolved, complete)
	configured := usableRemotes(resolved)
	if len(configured) == 0 {
		return nil, nil
	}
	if !c.beginShipping() {
		return nil, ErrShippingRunning
	}
	defer c.endShipping()

	entries, err := backup.List(backup.Dir(cfg))
	if err != nil {
		return nil, err
	}

	var (
		sent  []backup.Copy
		errs  []error
		clock = c.Now
	)
	for _, entry := range configured {
		cfgRemote := entry.Remote
		// Each destination is built on its own so that one with a typo in its
		// endpoint is recorded against its own name, where the page and the
		// problems drawer show it, and the copies still leave for the others.
		remote, err := backup.NewRemote(cfgRemote, c.backupHTTP)
		if err != nil {
			c.noteRemoteFailure(cfgRemote.Name, err, clock)
			errs = append(errs, err)
			continue
		}
		copies, err := c.shipOne(ctx, remote, entries, clock)
		sent = append(sent, copies...)
		if err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", remote.Name(), err))
		}
	}
	return sent, errors.Join(errs...)
}

// noteRemoteFailure records a destination that could not even be built.
func (c *Controller) noteRemoteFailure(name string, err error, clock func() time.Time) {
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	st := c.remoteState(name)
	st.uploading = false
	st.lastAttemptAt = clock()
	st.lastError = err.Error()
}

// shipOne reconciles one destination and records what happened to it.
func (c *Controller) shipOne(ctx context.Context, remote *backup.Remote, entries []backup.Entry, clock func() time.Time) ([]backup.Copy, error) {
	name := remote.Name()
	c.backups.mu.Lock()
	st := c.remoteState(name)
	st.uploading = true
	st.lastAttemptAt = clock()
	c.backups.mu.Unlock()

	finish := func(err error, sent []backup.Copy, held []backup.Copy) {
		c.backups.mu.Lock()
		defer c.backups.mu.Unlock()
		st := c.remoteState(name)
		st.uploading = false
		if err != nil {
			st.lastError = err.Error()
			return
		}
		st.lastError = ""
		if n := len(sent); n > 0 {
			st.lastUploadAt = clock()
			st.lastUploadID = sent[n-1].ID
		}
		st.held = len(held)
		st.heldBytes = 0
		for _, item := range held {
			st.heldBytes += item.Bytes
		}
		st.listedAt = clock()
	}

	ctx, cancel := context.WithTimeout(ctx, remoteUploadTimeout)
	defer cancel()

	held, err := remote.List(ctx)
	if err != nil {
		finish(err, nil, nil)
		return nil, err
	}
	var sent []backup.Copy
	for _, entry := range backup.Missing(entries, held, remote.Keep()) {
		copied, err := remote.Upload(ctx, &entry)
		if err != nil {
			finish(err, sent, held)
			c.log.Warn("a backup could not be copied offsite",
				"remote", name, "backup", entry.ID, "where", remote.Where(), "error", err)
			return sent, err
		}
		sent = append(sent, *copied)
		held = append([]backup.Copy{*copied}, held...)
		c.log.Info("copied a backup offsite",
			"remote", name, "backup", entry.ID, "where", remote.Where(),
			"bytes", copied.Bytes, "encrypted", copied.Encrypted)
	}
	if removed, err := remote.Prune(ctx, remote.Keep()); err != nil {
		finish(err, sent, held)
		return sent, err
	} else if len(removed) > 0 {
		c.log.Info("removed old copies from a backup remote",
			"remote", name, "removed", len(removed), "keep", remote.Keep())
		kept := held[:0]
		for _, item := range held {
			if !slices.Contains(removed, item.ID) {
				kept = append(kept, item)
			}
		}
		held = kept
	}
	finish(nil, sent, held)
	return sent, nil
}

// ErrShippingRunning is a second offsite pass asked for while one is running.
var ErrShippingRunning = errors.New("controller: the backups are already being copied offsite; wait for that to finish")

func (c *Controller) beginShipping() bool {
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	if c.backups.shipping {
		return false
	}
	c.backups.shipping = true
	return true
}

func (c *Controller) endShipping() {
	c.backups.mu.Lock()
	c.backups.shipping = false
	c.backups.mu.Unlock()
}

// remotesDue says whether the loop should reconcile the remotes on this tick:
// when something asked it to, when a remote is behind after a failure and the
// retry is up, and once a sweep however quiet things have been.
//
// Only a destination a pass would send to can be due. The others are never
// attempted, so their attempt time cannot advance, and counting them would
// keep the loop listing every bucket that does work on every tick.
func (c *Controller) remotesDue(ctx context.Context, now time.Time) bool {
	resolved, complete := c.resolveBackupRemotes(ctx)
	c.forgetGoneRemotes(resolved, complete)
	usable := map[string]bool{}
	for _, r := range usableRemotes(resolved) {
		usable[r.Remote.Name] = true
	}
	c.backups.mu.Lock()
	defer c.backups.mu.Unlock()
	if len(c.backups.remotes) == 0 {
		return true
	}
	for name, st := range c.backups.remotes {
		if st.uploading || !usable[name] {
			continue
		}
		wait := remoteSweep
		if st.lastError != "" {
			wait = remoteRetry
		}
		if st.lastAttemptAt.IsZero() || now.Sub(st.lastAttemptAt) >= wait {
			return true
		}
	}
	return false
}

// remoteProblems is what the drawer says about the copies that leave the
// machine.
//
// A remote that is failing is a warning rather than an error for the same
// reason a failing local backup is: the fleet is still running jobs. It is
// never silent, though, because the whole value of an offsite copy is that
// somebody would notice its absence before the day it is needed.
func (c *Controller) remoteProblems(ctx context.Context) []Problem {
	var out []Problem
	statuses := c.BackupRemotes(ctx)
	// "backups never leave this host" is not raised here. It is an info
	// finding, and Problems deliberately drops those from the drawer so that
	// a list which is never clear does not stop being read -- so the
	// validator keeps it, where the startup output and the Configuration page
	// show it, and the Backups page says the same thing in its own words
	// beside the button that fixes it.
	for _, status := range statuses {
		// A stored destination the file shadows, or one whose secrets will
		// not open, is a problem about this fleet's configuration rather than
		// about a bucket, and each says so in its own words.
		if status.Shadowed {
			out = append(out, Problem{
				Code:     "backup.remote_shadowed",
				Severity: config.SeverityWarning,
				Setting:  "backup.remotes",
				Title:    "the stored backup remote " + status.Name + " is being ignored",
				Detail: "zoomies.yaml or the environment describes a destination with the same name, and the file has the " +
					"last word. Nothing is sent to the stored one, and its settings are not the ones in use.",
				Fix: "rename one of them, or delete the stored destination and keep describing it in the file.",
			})
			continue
		}
		if status.Problem != "" {
			out = append(out, Problem{
				Code:     "backup.remote_unreadable",
				Severity: config.SeverityError,
				Setting:  "backup.remotes",
				Title:    "the backup remote " + status.Name + " cannot be used",
				Detail:   status.Problem,
				Fix: "this is what a database restored onto a host with a different encryption key looks like. Put the key " +
					"this fleet was sealed with back, or open the destination on the Backups tab and enter its secret key again.",
			})
			continue
		}
		// The same two things the startup validator says about a destination
		// in the file, said here about one in the database -- which the
		// validator cannot see. A fleet should not learn that its offsite
		// copies are readable by whoever owns the bucket from where it chose
		// to describe the destination.
		if status.Source == RemoteSourceDatabase && !status.Disabled {
			if !status.Encrypted {
				out = append(out, Problem{
					Code:     "backup.remote_plaintext",
					Severity: config.SeverityWarning,
					Setting:  "backup.remotes",
					Title:    "the backup remote " + status.Name + " is sent the backup unencrypted",
					Detail: "a backup is the whole fleet: every repository and job it has seen, every account, and the sealed " +
						"GitHub App credentials. In " + status.Where + " it is a file anyone who can read the bucket can open.",
					Fix: "set a passphrase on the destination from the Backups tab — the archive is then sealed with argon2id and " +
						"AES-256-GCM before it leaves this host — and keep it wherever you keep the encryption key. Nothing here can recover it.",
				})
			}
			if u, err := url.Parse(status.Endpoint); err == nil && u.Scheme == "http" && !config.LoopbackHost(u.Hostname()) {
				out = append(out, Problem{
					Code:     "backup.remote_insecure",
					Severity: config.SeverityWarning,
					Setting:  "backup.remotes",
					Title:    "the backup remote " + status.Name + " is reached over plain HTTP",
					Detail: "the access key, the signature and the backup itself cross the network in the clear, so anyone on the " +
						"path can both read the fleet and write to the bucket afterwards.",
					Fix: "use https:// unless the endpoint is on this host or a network you own end to end.",
				})
			}
		}
		if status.LastError == "" {
			continue
		}
		at := c.Now()
		c.backups.mu.Lock()
		if st, ok := c.backups.remotes[status.Name]; ok && !st.lastAttemptAt.IsZero() {
			at = st.lastAttemptAt
		}
		c.backups.mu.Unlock()
		detail := fmt.Sprintf("the last attempt, at %s, failed: %s. The controller tries again every %s.",
			at.Format(time.RFC3339), status.LastError, remoteRetry)
		if status.LastUploadID != "" && status.LastUploadAt != nil {
			detail += fmt.Sprintf(" The newest copy it holds is %s, from %s.", status.LastUploadID, status.LastUploadAt.Format(time.RFC3339))
		} else {
			detail += " Nothing has ever reached it."
		}
		out = append(out, Problem{
			Code:     "backup.remote_failed",
			Severity: config.SeverityWarning,
			Setting:  "backup.remotes",
			Title:    "backups are not reaching " + status.Name,
			Detail:   detail,
			Fix:      "read the error: it names the bucket, the credential or the clock. The Backups tab tests the remote on demand, and the copies on this host are unaffected — they are simply all there is.",
			Since:    &at,
		})
	}
	return out
}

package controller

import (
	"errors"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/store"
)

// offsite points the harness's fleet at a fake object store and returns it.
func offsite(h *harness, adjust func(*config.BackupRemote)) *backup.FakeS3 {
	h.t.Helper()
	fake := backup.NewFakeS3("backups")
	h.t.Cleanup(fake.Close)
	remote := config.BackupRemote{
		Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(), Prefix: "fleet",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
	}
	if adjust != nil {
		adjust(&remote)
	}
	h.c.UpdateConfig(func(c *config.Config) {
		c.Backup.Interval = time.Hour
		c.Backup.Remotes = []config.BackupRemote{remote}
	})
	return fake
}

// The copy the schedule takes has to reach the bucket, because a backup on the
// disk that just died is not a backup.
func TestAScheduledBackupIsCopiedToTheRemote(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)

	h.c.scheduledBackup(h.ctx)
	entries, err := backup.List(filepath.Join(h.onDisk(), backup.DefaultDirName))
	if err != nil || len(entries) != 1 {
		t.Fatalf("the schedule took %d backups, %v", len(entries), err)
	}
	// The loop nudges rather than uploading inside TakeBackup, so that an
	// operator pressing the button is not holding a browser open for the
	// length of a transfer. The pass is what sends it.
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}

	keys := fake.Keys()
	if len(keys) != 1 || keys[0] != "fleet/"+entries[0].ID+".tar.gz" {
		t.Fatalf("the bucket holds %v, wanted the backup that was just taken", keys)
	}
	status := h.c.BackupRemotes(h.ctx)
	if len(status) != 1 {
		t.Fatalf("the page would show %d remotes", len(status))
	}
	if status[0].LastError != "" || status[0].LastUploadID != entries[0].ID || status[0].Copies != 1 {
		t.Errorf("the remote reports %+v after a successful copy", status[0])
	}

	// And a second pass sends nothing: the bucket already holds it, and a
	// remote that re-uploaded every backup every hour would cost money for
	// nothing.
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the second pass: %v", err)
	}
	if fake.Puts() != 1 {
		t.Errorf("the bucket was written to %d times for one backup", fake.Puts())
	}
}

// A remote that was unreachable while two backups were taken is two behind,
// and the pass that finds it working again has to send both. A fleet whose
// offsite copy silently skips the nights the bucket was down has a gap nobody
// knows about.
func TestARemoteThatWasDownIsCaughtUpWithEveryBackupItMissed(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)
	fake.BreakWith(403, "AccessDenied", "the policy says no")

	root := filepath.Join(h.onDisk(), backup.DefaultDirName)
	for range 2 {
		h.c.scheduledBackup(h.ctx)
		if _, err := h.c.ShipBackups(h.ctx); err == nil {
			t.Fatal("the pass reported success against a bucket that refused it")
		}
		h.offset.Add(int64(2 * time.Hour))
		// The backup's name carries the clock's second, so two must not land
		// inside one.
		time.Sleep(1100 * time.Millisecond)
	}

	entries, err := backup.List(root)
	if err != nil || len(entries) != 2 {
		t.Fatalf("the schedule took %d backups while the bucket was down, %v", len(entries), err)
	}
	// The failure is on the page and in the drawer, not only in a log line.
	if status := h.c.BackupRemotes(h.ctx); status[0].LastError == "" {
		t.Error("a remote that is refusing every request reports no error")
	}
	codes := []string{}
	for _, p := range h.c.remoteProblems(h.ctx) {
		codes = append(codes, p.Code)
	}
	if len(codes) != 1 || codes[0] != "backup.remote_failed" {
		t.Errorf("the problems drawer says %v about a failing remote", codes)
	}

	fake.Mend()
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the pass after the bucket came back: %v", err)
	}
	if got := fake.Count(); got != 2 {
		t.Errorf("the bucket holds %d copies; the catch-up was meant to send both backups it missed", got)
	}
	if status := h.c.BackupRemotes(h.ctx); status[0].LastError != "" {
		t.Errorf("the remote still reports %q after a pass that worked", status[0].LastError)
	}
}

// A remote's own retention is its own: a fleet may keep a week on the disk and
// a year in the bucket, which is most of why the bucket is there.
func TestTheRemoteKeepsItsOwnNumberOfCopies(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, func(r *config.BackupRemote) { r.Keep = 1 })

	for range 2 {
		h.c.scheduledBackup(h.ctx)
		if _, err := h.c.ShipBackups(h.ctx); err != nil {
			t.Fatalf("ShipBackups: %v", err)
		}
		h.offset.Add(int64(2 * time.Hour))
		time.Sleep(1100 * time.Millisecond)
	}

	if got := fake.Count(); got != 1 {
		t.Fatalf("the bucket holds %d copies with keep: 1", got)
	}
	entries, err := backup.List(filepath.Join(h.onDisk(), backup.DefaultDirName))
	if err != nil || len(entries) != 2 {
		t.Fatalf("the local directory holds %d backups, %v -- the remote's ceiling is not the fleet's", len(entries), err)
	}
}

// Nothing leaves the host unless somebody says where it goes. The default
// configuration has no remotes, and a pass over none must be a pass that does
// nothing rather than an error somebody has to read.
func TestAFleetWithNoRemoteShipsNothingAndSaysSo(t *testing.T) {
	h := newHarness(t)
	sent, err := h.c.ShipBackups(h.ctx)
	if err != nil || len(sent) != 0 {
		t.Errorf("a fleet with no remotes shipped %d copies, %v", len(sent), err)
	}
	if remotes := h.c.BackupRemotes(h.ctx); len(remotes) != 0 {
		t.Errorf("the page would show %d remotes on a fleet with none", len(remotes))
	}
	// Nothing in the drawer, either: "these copies never leave the host" is
	// the validator's info finding, which the drawer drops on purpose, and
	// the Backups page says it in its own words beside the button that fixes
	// it.
	if problems := h.c.remoteProblems(h.ctx); len(problems) != 0 {
		t.Errorf("a fleet with no remotes raised %+v", problems)
	}
}

// A copy pulled back out of a bucket must survive local retention. It is here
// because the local copies are gone or suspect, and deleting it on the next
// pass because the directory is one over its ceiling would be the cruellest
// possible moment to enforce one.
func TestACopyFetchedBackIsNeverRemovedByRetention(t *testing.T) {
	h := newHarness(t)
	offsite(h, nil)
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })

	h.c.scheduledBackup(h.ctx)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}
	root := filepath.Join(h.onDisk(), backup.DefaultDirName)
	entries, err := backup.List(root)
	if err != nil || len(entries) != 1 {
		t.Fatalf("setting up: %d backups, %v", len(entries), err)
	}
	id := entries[0].ID
	if err := backup.Delete(root, id); err != nil {
		t.Fatalf("Delete: %v", err)
	}

	remote, err := h.c.RemoteBackup(h.ctx, "offsite")
	if err != nil {
		t.Fatalf("RemoteBackup: %v", err)
	}
	if _, err := remote.Fetch(h.ctx, root, id, backup.FetchOptions{TakenBy: "alice", Now: h.c.Now}); err != nil {
		t.Fatalf("Fetch: %v", err)
	}

	// A new scheduled backup, and retention behind it, must leave the fetched
	// copy alone even though keep is 1.
	h.offset.Add(int64(2 * time.Hour))
	time.Sleep(1100 * time.Millisecond)
	h.c.scheduledBackup(h.ctx)

	entries, err = backup.List(root)
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	found := false
	for _, e := range entries {
		if e.ID == id {
			found = true
			if e.Source != backup.SourceFetched {
				t.Errorf("the fetched copy says it came from %q", e.Source)
			}
		}
	}
	if !found {
		t.Error("retention removed the copy that was brought back from offsite")
	}
}

// A stored destination whose secrets this controller's key does not open is
// the shape a database restored onto the wrong host takes. It must not be
// tried every hour and refused by the service -- which reads as the bucket's
// fault -- and it must not be silent either.
func TestAStoredDestinationThisKeyCannotOpenIsReportedRatherThanTried(t *testing.T) {
	h := newHarness(t)
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)

	row := &store.BackupRemote{
		Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(),
		AccessKeyID: "AKIAEXAMPLE", Enabled: true,
	}
	if err := h.st.CreateBackupRemote(h.ctx, row); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	// Sealed with somebody else's key, which is exactly what a restored
	// database carries when the key file was left behind.
	other, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	sealed, err := other.SealString("secret")
	if err != nil {
		t.Fatalf("SealString: %v", err)
	}
	if err := h.st.SetBackupRemoteSecrets(h.ctx, row.ID, sealed, nil); err != nil {
		t.Fatalf("SetBackupRemoteSecrets: %v", err)
	}

	statuses := h.c.BackupRemotes(h.ctx)
	if len(statuses) != 1 || statuses[0].Problem == "" {
		t.Fatalf("the page shows %+v; it should carry the reason", statuses)
	}
	codes := []string{}
	for _, p := range h.c.remoteProblems(h.ctx) {
		codes = append(codes, p.Code)
	}
	if !slices.Contains(codes, "backup.remote_unreadable") {
		t.Errorf("the problems drawer says %v about a destination whose secrets will not open", codes)
	}

	h.c.scheduledBackup(h.ctx)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}
	if fake.Puts() != 0 {
		t.Error("a destination whose secret will not open was used anyway")
	}
}

// A stored destination the file names too is ignored, and says so. The file
// wins because it is the copy a host that has lost its database can read.
func TestTheFileWinsOverAStoredDestinationOfTheSameName(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)

	row := &store.BackupRemote{
		Name: "offsite", Endpoint: "https://elsewhere.example.com", Bucket: "other",
		AccessKeyID: "AKIAEXAMPLE", Enabled: true,
	}
	if err := h.st.CreateBackupRemote(h.ctx, row); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}

	statuses := h.c.BackupRemotes(h.ctx)
	if len(statuses) != 2 {
		t.Fatalf("the page shows %d destinations; the shadowed one is listed rather than hidden", len(statuses))
	}
	if statuses[0].Source != RemoteSourceFile || !statuses[1].Shadowed {
		t.Fatalf("the page shows %+v", statuses)
	}

	// And the copies go to the file's bucket, not the row's.
	h.c.scheduledBackup(h.ctx)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}
	if fake.Count() != 1 {
		t.Errorf("the file's bucket holds %d copies", fake.Count())
	}
}

// A destination added on the page gets the same two warnings as one in the
// file. Where a fleet chose to describe its offsite copies must not decide
// whether it is told they are readable by whoever owns the bucket.
func TestAStoredDestinationIsWarnedAboutLikeAFileOne(t *testing.T) {
	h := newHarness(t)
	row := &store.BackupRemote{
		Name: "offsite", Endpoint: "http://s3.example.com", Bucket: "acme",
		AccessKeyID: "AKIAEXAMPLE", Enabled: true,
	}
	if err := h.st.CreateBackupRemote(h.ctx, row); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}

	codes := map[string]bool{}
	for _, p := range h.c.remoteProblems(h.ctx) {
		codes[p.Code] = true
	}
	if !codes["backup.remote_plaintext"] {
		t.Error("a stored destination with no passphrase was not warned about")
	}
	if !codes["backup.remote_insecure"] {
		t.Error("a stored destination reached over plain HTTP was not warned about")
	}

	// Loopback is a developer's MinIO: the credentials never cross a network,
	// so that one is not a warning.
	row.Endpoint = "http://127.0.0.1:9000"
	if err := h.st.UpdateBackupRemote(h.ctx, row); err != nil {
		t.Fatalf("UpdateBackupRemote: %v", err)
	}
	for _, p := range h.c.remoteProblems(h.ctx) {
		if p.Code == "backup.remote_insecure" {
			t.Error("a destination on loopback was warned about as if it crossed a network")
		}
	}
}

// The copy leaves the machine because a backup was taken, not because
// somebody pressed a button afterwards.
//
// The loop takes the backup and the backup nudges the loop, so the nudge lands
// in a channel the pass it came from has already read. It used to sit there
// until a later tick happened to pick it up, and a fleet whose remotes were
// reconciled five minutes ago would sit on the night's backup for as long as
// that took. This runs one pass with the remote freshly reconciled -- so
// nothing but the nudge can start an upload -- and expects the bucket to hold
// what the pass took.
func TestABackupTakenByThePassIsShippedByTheSamePass(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)

	// Reconcile once, so remotesDue is false for the next hour and the only
	// thing that can ship in the pass below is the backup it takes.
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the first pass: %v", err)
	}
	if h.c.remotesDue(h.ctx, h.c.Now()) {
		t.Fatal("setting up: the remote is still due, so this proves nothing")
	}

	h.c.backupPass(h.ctx, false)

	entries, err := backup.List(filepath.Join(h.onDisk(), backup.DefaultDirName))
	if err != nil || len(entries) != 1 {
		t.Fatalf("the pass took %d backups, %v", len(entries), err)
	}
	keys := fake.Keys()
	if len(keys) != 1 || keys[0] != "fleet/"+entries[0].ID+".tar.gz" {
		t.Fatalf("the bucket holds %v after the pass that took %s", keys, entries[0].ID)
	}
}

// twoOffsite is two destinations on one fake bucket, the shape whose second
// half an operator later deletes or switches off.
func twoOffsite(h *harness, adjustSpare func(*config.BackupRemote)) {
	h.t.Helper()
	fake := offsite(h, nil)
	spare := config.BackupRemote{
		Name: "spare", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(), Prefix: "spare",
		AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
	}
	if adjustSpare != nil {
		adjustSpare(&spare)
	}
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Remotes = append(c.Backup.Remotes, spare) })
}

// remoteStateNames is the destinations the controller is holding state for.
func remoteStateNames(h *harness) []string {
	h.c.backups.mu.Lock()
	defer h.c.backups.mu.Unlock()
	var names []string
	for name := range h.c.backups.remotes {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// A remote that has left the configuration must take its state with it. Its
// last attempt is never refreshed again -- nothing ships to it -- so once it is
// an hour old the loop reconciles on every tick, and each of those passes
// lists every bucket that is left, which is a request that costs money in
// some of them and is what the hourly sweep exists to avoid.
func TestARemovedRemoteDoesNotKeepTheLoopListingEveryBucket(t *testing.T) {
	h := newHarness(t)
	twoOffsite(h, nil)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the first pass: %v", err)
	}
	if names := remoteStateNames(h); !slices.Equal(names, []string{"offsite", "spare"}) {
		t.Fatalf("setting up: state is held for %v", names)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Remotes = c.Backup.Remotes[:1] })
	h.advance(50 * time.Minute)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the pass after the removal: %v", err)
	}
	if names := remoteStateNames(h); !slices.Equal(names, []string{"offsite"}) {
		t.Errorf("state is still held for %v after spare left the configuration", names)
	}

	// The survivor was reconciled twenty minutes ago; only what was left of
	// the removed one is more than an hour old.
	h.advance(20 * time.Minute)
	if h.c.remotesDue(h.ctx, h.c.Now()) {
		t.Error("the loop is due on every tick because of a remote that no longer exists")
	}
}

// A switched-off remote is still on the page, and the page shows what a
// listing last found there, so its state stays -- but a listing has no
// attempt time, and that must not be read as a remote nobody has tried.
func TestAListedDisabledRemoteKeepsItsCountsWithoutMakingTheLoopDue(t *testing.T) {
	h := newHarness(t)
	twoOffsite(h, func(r *config.BackupRemote) { r.Disabled = true })
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the first pass: %v", err)
	}

	h.c.NoteRemoteListing("spare", 3, 4096)
	if h.c.remotesDue(h.ctx, h.c.Now()) {
		t.Error("listing a switched-off remote made the loop reconcile on every tick")
	}

	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the second pass: %v", err)
	}
	for _, status := range h.c.BackupRemotes(h.ctx) {
		if status.Name == "spare" && status.Copies != 3 {
			t.Errorf("the page shows %d copies for the switched-off remote, wanted the 3 its listing found", status.Copies)
		}
	}
}

// The stored half of the configuration comes from the database. A read that
// fails leaves only the file's remotes to compare against, and every stored
// remote's state would look abandoned; wiping it would blank the page and the
// problems drawer for an outage that has nothing to do with them.
func TestAFailedStoreReadDoesNotWipeTheStateOfStoredRemotes(t *testing.T) {
	h := newHarness(t)
	offsite(h, nil)
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the first pass: %v", err)
	}
	h.c.NoteRemoteListing("stored", 2, 1024)

	if err := h.st.Close(); err != nil {
		t.Fatalf("closing the store: %v", err)
	}
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("the pass with the store down: %v", err)
	}
	if names := remoteStateNames(h); !slices.Equal(names, []string{"offsite", "stored"}) {
		t.Errorf("state is held for %v after a pass that could not read the stored remotes", names)
	}
}

// A nudge that arrives while somebody is pressing "copy offsite now" is a
// backup that has just been taken. Dropping it would leave that copy waiting
// for the hourly sweep, so the pass that cannot run puts it back.
func TestANudgeRefusedByAPassAlreadyRunningIsKept(t *testing.T) {
	h := newHarness(t)
	offsite(h, nil)

	if !h.c.beginShipping() {
		t.Fatal("setting up: shipping was already held")
	}
	h.c.nudgeRemotes()
	h.c.shipScheduled(h.ctx)
	h.c.endShipping()

	if !h.c.tookNudge() {
		t.Error("the nudge was dropped, so the backup it stood for waits for the hourly sweep")
	}
}

// Retention runs when a backup is taken, which is the wrong moment for an
// operator who has just lowered the number kept: with backup.interval off,
// nothing happens ever. This is that button, and it has to reach the buckets
// too -- both numbers are set on the same page.
func TestRetentionCanBeAppliedWithoutTakingABackup(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, func(r *config.BackupRemote) { r.Keep = 1 })
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 0 })

	for range 3 {
		h.c.scheduledBackup(h.ctx)
		h.offset.Add(int64(2 * time.Hour))
		// The name carries the clock's second, so two backups must not land
		// in the same one.
		time.Sleep(1100 * time.Millisecond)
	}
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}
	root := filepath.Join(h.onDisk(), backup.DefaultDirName)
	before, err := backup.List(root)
	if err != nil || len(before) != 3 {
		t.Fatalf("setting up: %d backups, %v", len(before), err)
	}
	// keep: 1 on the remote means the pass above already pruned it; what is
	// under test is the local half and that the bucket is not disturbed.
	if got := fake.Count(); got != 1 {
		t.Fatalf("setting up: the bucket holds %d copies", got)
	}

	// The ceiling is lowered, and nothing has happened yet: that is the whole
	// complaint this route answers.
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })
	if entries, _ := backup.List(root); len(entries) != 3 {
		t.Fatalf("lowering backup.keep removed %d backups by itself", 3-len(entries))
	}

	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if report.Keep != 1 || len(report.Removed) != 2 {
		t.Errorf("the report says keep %d, removed %v", report.Keep, report.Removed)
	}
	after, err := backup.List(root)
	if err != nil || len(after) != 1 {
		t.Fatalf("after pruning: %d backups, %v", len(after), err)
	}
	if after[0].ID != before[0].ID {
		t.Errorf("retention kept %s; the newest was %s", after[0].ID, before[0].ID)
	}
	if len(report.Remotes) != 1 || report.Remotes[0].Name != "offsite" || report.Remotes[0].Error != "" {
		t.Errorf("the report's remotes read %+v", report.Remotes)
	}
	if got := fake.Count(); got != 1 {
		t.Errorf("the bucket holds %d copies after a prune that should have left it alone", got)
	}
}

// The other half of the same button: a destination holding more than it is
// meant to is pruned without a backup being taken either.
func TestRetentionOnDemandReachesTheBuckets(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 0 })

	for range 3 {
		h.c.scheduledBackup(h.ctx)
		h.offset.Add(int64(2 * time.Hour))
		time.Sleep(1100 * time.Millisecond)
	}
	if _, err := h.c.ShipBackups(h.ctx); err != nil {
		t.Fatalf("ShipBackups: %v", err)
	}
	if got := fake.Count(); got != 3 {
		t.Fatalf("setting up: the bucket holds %d copies", got)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Remotes[0].Keep = 1 })
	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if len(report.Remotes) != 1 || len(report.Remotes[0].Removed) != 2 {
		t.Fatalf("the report's remotes read %+v", report.Remotes)
	}
	if got := fake.Count(); got != 1 {
		t.Errorf("the bucket holds %d copies after keep was lowered to 1", got)
	}
	// And the page's own figure is the one the operator just changed, rather
	// than the count from before the prune.
	status := h.c.BackupRemotes(h.ctx)
	if len(status) != 1 || status[0].Copies != 1 {
		t.Errorf("the page would say the bucket holds %+v", status)
	}
	// The local directory keeps every copy: the two ceilings are separate,
	// and a fleet with three here and one offsite is a correct fleet.
	if entries, _ := backup.List(filepath.Join(h.onDisk(), backup.DefaultDirName)); len(entries) != 3 {
		t.Errorf("pruning the bucket removed local backups too: %d left", len(entries))
	}
}

// Retention deletes copies, and two other things in this controller also move
// them: a backup being written, and an offsite pass sending one. Pruning
// beside either could count a directory that is not finished or delete the
// archive being uploaded, so it refuses and says which one to wait for.
func TestRetentionOnDemandWaitsForABackupAndForAnOffsitePass(t *testing.T) {
	h := newHarness(t)
	offsite(h, nil)

	if !h.c.beginBackup() {
		t.Fatal("setting up: a backup was already being taken")
	}
	_, err := h.c.PruneBackups(h.ctx)
	h.c.endBackup()
	if !errors.Is(err, ErrBackupRunning) {
		t.Errorf("pruning beside a backup returned %v", err)
	}

	if !h.c.beginShipping() {
		t.Fatal("setting up: a pass was already running")
	}
	report, err := h.c.PruneBackups(h.ctx)
	h.c.endShipping()
	if !errors.Is(err, ErrShippingRunning) {
		t.Errorf("pruning beside an offsite pass returned %v", err)
	}
	// The local half still ran: it is done before the buckets are touched,
	// and it is the half that has nothing to do with them.
	if report.Keep != h.c.cfg().Backup.Keep {
		t.Errorf("the report says keep %d", report.Keep)
	}
}

// A bucket that refuses is recorded against its own name, and the copies on
// this host are pruned anyway. A fleet whose retention stopped at the first
// wrong credential would keep every copy it has and never say why.
func TestRetentionOnDemandRecordsABucketThatRefuses(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, func(r *config.BackupRemote) { r.Keep = 1 })
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 0 })

	for range 2 {
		h.c.scheduledBackup(h.ctx)
		h.offset.Add(int64(2 * time.Hour))
		time.Sleep(1100 * time.Millisecond)
	}
	fake.BreakWith(403, "AccessDenied", "the policy says no")

	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })
	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if len(report.Removed) != 1 {
		t.Errorf("the local half removed %v while the bucket was refusing", report.Removed)
	}
	if len(report.Remotes) != 1 || report.Remotes[0].Error == "" {
		t.Fatalf("the report says %+v about a bucket that refused", report.Remotes)
	}
	// internal/backup words the refusal rather than passing the service's
	// code through, so a policy that is too narrow reads as the permissions
	// it is missing rather than as "AccessDenied".
	if !strings.Contains(report.Remotes[0].Error, "s3:ListBucket") {
		t.Errorf("the refusal reads %q, which does not say what the credential needs", report.Remotes[0].Error)
	}
	// And the page carries it, so the drawer has something to raise.
	if status := h.c.BackupRemotes(h.ctx); len(status) != 1 || status[0].LastError == "" {
		t.Errorf("the page would say %+v about the destination that refused", status)
	}
}

// The default fleet has no destinations at all, and pruning it is the local
// half alone rather than an error somebody has to read.
func TestRetentionOnDemandOnAFleetWithNoDestinations(t *testing.T) {
	h := newHarness(t)
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Interval = time.Hour })

	for range 2 {
		h.c.scheduledBackup(h.ctx)
		h.offset.Add(int64(2 * time.Hour))
		time.Sleep(1100 * time.Millisecond)
	}
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })

	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if len(report.Removed) != 1 || report.Error != "" {
		t.Errorf("the report reads %+v", report)
	}
	if len(report.Remotes) != 0 {
		t.Errorf("a fleet with no destinations reported %+v", report.Remotes)
	}
}

// A backup directory that cannot be read is the report's own error rather
// than a pass that claims to have removed nothing.
func TestRetentionOnDemandSaysWhyTheDirectoryRefused(t *testing.T) {
	h := newHarness(t)
	root := filepath.Join(h.onDisk(), backup.DefaultDirName)
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Interval = time.Hour })
	h.c.scheduledBackup(h.ctx)
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })

	// A file where the directory should be: List cannot read it, and the
	// operator is told that rather than "nothing to remove".
	if err := os.RemoveAll(root); err != nil {
		t.Fatalf("clearing the directory: %v", err)
	}
	if err := os.WriteFile(root, []byte("not a directory"), 0o600); err != nil {
		t.Fatalf("writing the file in its place: %v", err)
	}

	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if report.Error == "" {
		t.Error("a directory that could not be read reported no error")
	}
	if len(report.Removed) != 0 {
		t.Errorf("it also claims to have removed %v", report.Removed)
	}
}

// A destination this controller cannot even build a client for -- an endpoint
// that is not a URL, which the startup validator would have caught but a
// stored row edited by hand would not -- is recorded against its own name.
// The others are still pruned: one malformed row must not stop retention.
func TestRetentionOnDemandRecordsADestinationItCannotBuild(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)
	h.c.UpdateConfig(func(c *config.Config) {
		c.Backup.Keep = 0
		c.Backup.Remotes = append(c.Backup.Remotes, config.BackupRemote{
			Name: "broken", Endpoint: "://not-a-url", Bucket: fake.Bucket(),
			AccessKeyID: "AKIAEXAMPLE", SecretAccessKey: "secret",
		})
	})

	for range 2 {
		h.c.scheduledBackup(h.ctx)
		h.offset.Add(int64(2 * time.Hour))
		time.Sleep(1100 * time.Millisecond)
	}
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Keep = 1 })

	report, err := h.c.PruneBackups(h.ctx)
	if err != nil {
		t.Fatalf("PruneBackups: %v", err)
	}
	if len(report.Removed) != 1 {
		t.Errorf("the local half removed %v", report.Removed)
	}
	var broken *RemotePruning
	for i, r := range report.Remotes {
		if r.Name == "broken" {
			broken = &report.Remotes[i]
		}
	}
	if broken == nil || broken.Error == "" {
		t.Fatalf("the report says %+v about a destination that cannot be built", report.Remotes)
	}
	if len(report.Remotes) != 2 {
		t.Errorf("the working destination was dropped from the pass: %+v", report.Remotes)
	}
}

// The loop's quiet pass: nothing is due, nothing has been asked for, and
// there is nowhere for a copy to go. It has to be a pass that does nothing
// rather than one that takes a backup or reaches for a bucket.
func TestAQuietPassTakesNothingAndSendsNothing(t *testing.T) {
	h := newHarness(t)
	root := filepath.Join(h.onDisk(), backup.DefaultDirName)
	// The schedule off, which is what backup.interval 0 means, and no
	// destinations -- the default fleet.
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Interval = 0 })

	h.c.backupPass(h.ctx, false)

	if entries, err := backup.List(root); err == nil && len(entries) != 0 {
		t.Errorf("a pass with the schedule off took %d backups", len(entries))
	}
	if remotes := h.c.BackupRemotes(h.ctx); len(remotes) != 0 {
		t.Errorf("a fleet with no destinations reported %+v", remotes)
	}
}

// And the noisy one: a pass whose bucket refuses leaves the failure on the
// destination rather than raising it out of the loop, which has nobody to
// tell. The page and the drawer are where it is read.
func TestAScheduledPassRecordsABucketThatRefuses(t *testing.T) {
	h := newHarness(t)
	fake := offsite(h, nil)
	fake.BreakWith(500, "InternalError", "the service is having a moment")

	h.c.scheduledBackup(h.ctx)
	h.c.shipScheduled(h.ctx)

	status := h.c.BackupRemotes(h.ctx)
	if len(status) != 1 || status[0].LastError == "" {
		t.Errorf("the page would say %+v about a destination that refused every request", status)
	}
}

// A destination added on the Backups page has to be shipped to by the
// schedule, exactly like one in zoomies.yaml.
//
// The loop's own pass used to ask the configuration file whether there was
// anywhere to send a copy, and a destination an operator typed into the page
// is a database row the file knows nothing about. So the schedule took its
// backups every night, the page showed a healthy destination with a button
// that worked when pressed, and nothing ever left the machine on its own --
// the worst shape this can fail in, because everything visible said it was
// working.
func TestTheScheduleShipsToADestinationAddedOnThePage(t *testing.T) {
	h := newHarness(t)
	fake := backup.NewFakeS3("backups")
	t.Cleanup(fake.Close)

	row := &store.BackupRemote{
		Name: "offsite", Endpoint: fake.Endpoint(), Bucket: fake.Bucket(), Prefix: "fleet",
		AccessKeyID: "AKIAEXAMPLE", Enabled: true,
	}
	if err := h.st.CreateBackupRemote(h.ctx, row); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	sealed, err := h.key.SealString("secret")
	if err != nil {
		t.Fatalf("SealString: %v", err)
	}
	if err := h.st.SetBackupRemoteSecrets(h.ctx, row.ID, sealed, nil); err != nil {
		t.Fatalf("SetBackupRemoteSecrets: %v", err)
	}
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Interval = time.Hour })

	// One whole turn of the loop: the schedule takes the copy, and the same
	// pass sends it. Nothing here presses a button.
	h.c.backupPass(h.ctx, false)

	entries, err := backup.List(filepath.Join(h.onDisk(), backup.DefaultDirName))
	if err != nil || len(entries) != 1 {
		t.Fatalf("the pass took %d backups, %v", len(entries), err)
	}
	keys := fake.Keys()
	if len(keys) != 1 || keys[0] != "fleet/"+entries[0].ID+".tar.gz" {
		t.Fatalf("the bucket holds %v after the pass that took %s", keys, entries[0].ID)
	}
	if status := h.c.BackupRemotes(h.ctx); len(status) != 1 || status[0].LastUploadID != entries[0].ID {
		t.Errorf("the page reports %+v after the schedule copied a backup offsite", status)
	}
}

package controller

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/backup"
	"github.com/eyupio/zoomies/internal/config"
)

// onDisk is the directory the harness's configuration puts the database in,
// which is where the backup directory is derived from. The harness's own store
// is in memory, and VACUUM INTO copies that fine; the configured path is what
// the loop and the staged-restore files go by.
func (h *harness) onDisk() string {
	h.t.Helper()
	return filepath.Dir(h.cfg.Database.Path)
}

// A fleet whose only backup is the one somebody remembers to take has no
// backup. The loop takes one when none is recent, leaves the schedule alone
// while one is, and keeps to backup.keep.
func TestTheScheduleTakesABackupWhenOneIsDueAndKeepsToTheCeiling(t *testing.T) {
	h := newHarness(t)
	dir := h.onDisk()
	h.c.UpdateConfig(func(c *config.Config) {
		c.Backup.Interval = time.Hour
		c.Backup.Keep = 2
	})
	root := filepath.Join(dir, backup.DefaultDirName)

	h.c.scheduledBackup(h.ctx)
	entries, err := backup.List(root)
	if err != nil || len(entries) != 1 {
		t.Fatalf("after the first pass: %d backups, %v", len(entries), err)
	}
	if entries[0].Source != backup.SourceScheduled {
		t.Errorf("source = %q, want scheduled", entries[0].Source)
	}
	status := h.c.BackupStatus()
	if status.LastError != "" || status.LastScheduledID != entries[0].ID || status.NextDueAt.Before(entries[0].TakenAt.Add(time.Hour)) {
		t.Errorf("status = %+v", status)
	}

	// Not due again yet: nothing new.
	h.c.scheduledBackup(h.ctx)
	if entries, _ := backup.List(root); len(entries) != 1 {
		t.Fatalf("a second pass inside the interval took another backup: %d", len(entries))
	}

	// Time passes; the newest is stale, so another is taken -- and a third
	// removes the oldest.
	for range 2 {
		h.offset.Add(int64(2 * time.Hour))
		// The name carries the clock's second, so two passes must not land
		// in the same one.
		time.Sleep(1100 * time.Millisecond)
		h.c.scheduledBackup(h.ctx)
	}
	entries, _ = backup.List(root)
	if len(entries) != 2 {
		t.Fatalf("keep 2 left %d backups", len(entries))
	}
	if problems := h.c.backupProblems(h.ctx); len(problems) != 0 {
		t.Errorf("a working schedule raised %+v", problems)
	}
}

// A schedule that cannot write is a fleet with no backup and a page that says
// so: the failure is a problem, it is retried later rather than every minute,
// and a backup that then succeeds clears it.
func TestAFailingScheduleIsAProblemAndBacksOff(t *testing.T) {
	h := newHarness(t)
	dir := h.onDisk()
	h.c.UpdateConfig(func(c *config.Config) { c.Backup.Interval = time.Hour })
	// A file where the directory should be.
	if err := os.WriteFile(filepath.Join(dir, backup.DefaultDirName), []byte("in the way"), 0o600); err != nil {
		t.Fatal(err)
	}

	h.c.scheduledBackup(h.ctx)
	status := h.c.BackupStatus()
	if status.LastError == "" {
		t.Fatal("the failure was not recorded")
	}
	var found bool
	for _, p := range h.c.backupProblems(h.ctx) {
		if p.Code == "backup.failed" && p.Fix != "" {
			found = true
		}
	}
	if !found {
		t.Errorf("no backup.failed problem: %+v", h.c.backupProblems(h.ctx))
	}

	// Cleared out of the way, but inside the retry window: no attempt.
	if err := os.Remove(filepath.Join(dir, backup.DefaultDirName)); err != nil {
		t.Fatal(err)
	}
	h.c.scheduledBackup(h.ctx)
	if entries, _ := backup.List(filepath.Join(dir, backup.DefaultDirName)); len(entries) != 0 {
		t.Fatal("the loop retried inside its back-off")
	}
	h.offset.Add(int64(backupRetry + time.Minute))
	h.c.scheduledBackup(h.ctx)
	if status := h.c.BackupStatus(); status.LastError != "" || status.LastScheduledID == "" {
		t.Errorf("a backup that worked did not clear the failure: %+v", status)
	}
}

// Two backups at once would race for one directory name and a prune could
// delete the copy being taken. The second caller is refused, not queued.
func TestOnlyOneBackupIsTakenAtATime(t *testing.T) {
	h := newHarness(t)
	h.onDisk()
	if !h.c.beginBackup() {
		t.Fatal("could not begin")
	}
	if _, err := h.c.TakeBackup(context.Background(), backup.SourceManual, "alice"); err != ErrBackupRunning {
		t.Errorf("a second backup was not refused: %v", err)
	}
	h.c.endBackup()
	if _, err := h.c.TakeBackup(context.Background(), backup.SourceManual, "alice"); err != nil {
		t.Errorf("after the first finished: %v", err)
	}
}

// A restart is asked for once and answered once; asking again is not an
// error, and the reason given first is the one kept.
func TestARestartIsRequestedOnce(t *testing.T) {
	h := newHarness(t)
	if on, _ := h.c.Restarting(); on {
		t.Fatal("restarting before anybody asked")
	}
	h.c.RequestRestart("to apply a restore")
	h.c.RequestRestart("again")
	select {
	case <-h.c.RestartRequested():
	default:
		t.Fatal("the channel is not closed")
	}
	if on, why := h.c.Restarting(); !on || why != "to apply a restore" {
		t.Errorf("Restarting = %v, %q", on, why)
	}
}

// The staged restore and the failed restore both belong in the drawer: one is
// a fleet about to change hands, the other a change that did not happen.
func TestAStagedAndAFailedRestoreAreProblems(t *testing.T) {
	h := newHarness(t)
	h.onDisk()
	entry, err := h.c.TakeBackup(h.ctx, backup.SourceManual, "alice")
	if err != nil {
		t.Fatalf("TakeBackup: %v", err)
	}
	if _, err := backup.Stage(h.ctx, h.cfg, entry, backup.Staged{RequestedBy: "alice"}); err != nil {
		t.Fatalf("Stage: %v", err)
	}
	codes := map[string]bool{}
	for _, p := range h.c.backupProblems(h.ctx) {
		codes[p.Code] = true
	}
	if !codes["backup.restore_staged"] {
		t.Errorf("a staged restore is not on the list: %v", codes)
	}

	// The next start applies it. Here the database does not exist yet, which
	// a restore handles; a backup sealed with another key does not.
	if err := os.WriteFile(filepath.Join(entry.Dir, backup.ManifestName), []byte(`{"key":{"fingerprint":"not-this-one"}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	outcome, err := backup.ApplyStaged(h.ctx, h.cfg, nil)
	if err != nil || outcome == nil || outcome.OK {
		t.Fatalf("ApplyStaged = %+v, %v; want a recorded failure", outcome, err)
	}
	codes = map[string]bool{}
	for _, p := range h.c.backupProblems(h.ctx) {
		codes[p.Code] = true
	}
	if codes["backup.restore_staged"] || !codes["backup.restore_failed"] {
		t.Errorf("after a failed restore: %v", codes)
	}
	if err := backup.ClearOutcome(h.cfg.Database.Path); err != nil {
		t.Fatal(err)
	}
	if problems := h.c.backupProblems(h.ctx); len(problems) != 0 {
		t.Errorf("dismissed and still listed: %+v", problems)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"os"
	"runtime"
	"strings"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
)

// BootstrapFromEnvironment creates the first identity ZOOMIES_BOOTSTRAP_*
// describes, if the database has no accounts yet.
//
// It runs once, at start, beside the setup token. On an empty database it is
// what makes an instance a compose file or a Terraform module brought up
// usable with no human step: nobody is there to read the setup token out of
// the log. Once any account exists the variables are ignored -- they must
// never be a way to add a platform account to an instance somebody has
// already claimed -- and bootstrap.ignored names them, because variables that
// silently do nothing are a credential sitting in a file for no reason.
//
// A malformed request is an error that stops startup: a provisioner waiting
// on /readyz for bootstrap_required to go false would otherwise wait for ever.
func (c *Controller) BootstrapFromEnvironment(ctx context.Context) error {
	b := c.cfg().Bootstrap
	if !b.Requested() {
		return nil
	}
	svc := c.Auth()
	need, err := svc.NeedsBootstrap(ctx)
	if err != nil {
		return err
	}
	if !need {
		c.ignoreBootstrap(b)
		return nil
	}

	in := auth.Unattended{Username: b.Admin}
	if b.TokenFile != "" {
		if in.Token, err = readSecretFile("ZOOMIES_BOOTSTRAP_TOKEN_FILE", b.TokenFile); err != nil {
			return err
		}
	} else {
		if in.Password, err = readSecretFile("ZOOMIES_BOOTSTRAP_PASSWORD_FILE", b.PasswordFile); err != nil {
			return err
		}
	}
	u, tok, err := svc.CreateUnattendedIdentity(ctx, in)
	if errors.Is(err, auth.ErrAlreadyBootstrapped) {
		// Somebody used the setup token between the check above and here.
		c.ignoreBootstrap(b)
		return nil
	}
	if err != nil {
		return fmt.Errorf("creating the first account from ZOOMIES_BOOTSTRAP_ADMIN: %w", err)
	}
	if tok != nil {
		c.log.Info("created the first account from the environment, with the API token the bootstrap file holds",
			"username", u.Username, "role", u.Role, "token_id", tok.ID)
	} else {
		c.log.Info("created the first account from the environment", "username", u.Username, "role", u.Role)
	}
	return nil
}

func (c *Controller) ignoreBootstrap(b config.Bootstrap) {
	vars := b.Variables()
	c.bootstrapIgnored.Store(&vars)
	c.log.Warn("ignoring the bootstrap variables: this instance already has an account",
		"variables", strings.Join(vars, ", "))
}

// bootstrapProblems is the warning that the bootstrap variables did nothing.
func (c *Controller) bootstrapProblems() []Problem {
	p := c.bootstrapIgnored.Load()
	if p == nil || len(*p) == 0 {
		return nil
	}
	names := strings.Join(*p, ", ")
	return []Problem{{
		Code:     "bootstrap.ignored",
		Severity: config.SeverityWarning,
		Title:    names + " set on an instance that already has accounts",
		Detail: "they only ever create the first account on an empty database, so this start ignored them. " +
			"The file they point at is a credential kept for nothing.",
		Fix: "remove " + names + " from the controller's environment, and delete the file they name.",
	}}
}

// readSecretFile reads a bootstrap credential, refusing a file that group or
// other can read -- the rule cryptox.LoadKeyFile applies to the encryption
// key, for the same reason: a platform credential readable by every account
// on the host is not one only the provisioner holds. Windows is skipped for
// the reason LoadKeyFile gives: its mode bits say nothing about its ACL.
func readSecretFile(variable, path string) (string, error) {
	info, err := os.Stat(path)
	if err != nil {
		return "", fmt.Errorf("%s: %w", variable, err)
	}
	if mode := info.Mode().Perm(); runtime.GOOS != "windows" && mode&0o077 != 0 {
		return "", fmt.Errorf("%s: %s is mode %04o; it must not be readable by group or other (chmod 600 %s)",
			variable, path, mode, path)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("%s: %w", variable, err)
	}
	v := strings.TrimRight(string(b), "\r\n")
	if v == "" {
		return "", fmt.Errorf("%s: %s is empty", variable, path)
	}
	return v, nil
}

package controller

import (
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

func writeSecret(t *testing.T, value string, mode os.FileMode) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "secret")
	if err := os.WriteFile(path, []byte(value+"\n"), mode); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatalf("chmod %s: %v", path, err)
	}
	return path
}

func (h *harness) bootstrapWith(b config.Bootstrap) {
	h.c.UpdateConfig(func(c *config.Config) { c.Bootstrap = b })
}

func (h *harness) problemsByCode() map[string]Problem {
	h.t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		h.t.Fatalf("Problems: %v", err)
	}
	out := map[string]Problem{}
	for _, p := range ps {
		out[p.Code] = p
	}
	return out
}

// A compose file or a Terraform module has nobody watching, so on an empty
// database the environment's account is the one that makes the instance
// usable, and it is the platform one.
func TestTheEnvironmentCreatesTheFirstPlatformAccountOnAnEmptyDatabase(t *testing.T) {
	h := newHarness(t)
	h.bootstrapWith(config.Bootstrap{
		Admin:        "ops",
		PasswordFile: writeSecret(t, "correct-horse-battery-staple", 0o600),
	})

	if err := h.c.BootstrapFromEnvironment(h.ctx); err != nil {
		t.Fatalf("BootstrapFromEnvironment: %v", err)
	}
	u, err := h.st.GetUserByUsername(h.ctx, "ops")
	if err != nil {
		t.Fatalf("the account was not created: %v", err)
	}
	if u.Role != store.RolePlatform {
		t.Fatalf("the account is %s; want platform", u.Role)
	}
	if _, ok := h.problemsByCode()["bootstrap.ignored"]; ok {
		t.Fatal("variables that did their job must not be reported as ignored")
	}
}

// Variables that silently do nothing are a credential sitting in a file for no
// reason, so a start that ignores them says which ones to remove.
func TestTheBootstrapVariablesAreIgnoredAndNamedOnceAnAccountExists(t *testing.T) {
	h := newHarness(t)
	if err := h.st.CreateUser(h.ctx, &store.User{Username: "someone", Role: store.RoleAdmin}); err != nil {
		t.Fatalf("CreateUser: %v", err)
	}
	h.bootstrapWith(config.Bootstrap{
		Admin:     "ops",
		TokenFile: writeSecret(t, strings.Repeat("t", 40), 0o600),
	})

	if err := h.c.BootstrapFromEnvironment(h.ctx); err != nil {
		t.Fatalf("BootstrapFromEnvironment: %v", err)
	}
	if n, _ := h.st.CountUsers(h.ctx); n != 1 {
		t.Fatalf("there are %d accounts; the environment must not add one to a claimed instance", n)
	}
	p, ok := h.problemsByCode()["bootstrap.ignored"]
	if !ok {
		t.Fatal("no bootstrap.ignored problem")
	}
	if p.Severity != config.SeverityWarning {
		t.Errorf("bootstrap.ignored is %s; want a warning", p.Severity)
	}
	for _, v := range []string{"ZOOMIES_BOOTSTRAP_ADMIN", "ZOOMIES_BOOTSTRAP_TOKEN_FILE"} {
		if !strings.Contains(p.Title+p.Fix, v) {
			t.Errorf("the problem does not name %s: %q / %q", v, p.Title, p.Fix)
		}
	}
	if strings.Contains(p.Title+p.Fix, "PASSWORD_FILE") {
		t.Errorf("the problem names a variable that is not set: %q", p.Title)
	}
}

// The rule the encryption key file follows: a platform credential readable by
// every account on the host is not one only the provisioner holds.
func TestABootstrapFileOthersCanReadIsRefused(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("mode bits say nothing about access on Windows")
	}
	h := newHarness(t)
	h.bootstrapWith(config.Bootstrap{
		Admin:        "ops",
		PasswordFile: writeSecret(t, "correct-horse-battery-staple", 0o644),
	})

	err := h.c.BootstrapFromEnvironment(h.ctx)
	if err == nil || !strings.Contains(err.Error(), "chmod 600") {
		t.Fatalf("got %v; want a refusal that says how to fix the mode", err)
	}
	if n, _ := h.st.CountUsers(h.ctx); n != 0 {
		t.Fatal("a refused file still created an account")
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func TestTerminalJobWithoutStartDeliveryRemovesItsEphemeralRunner(t *testing.T) {
	for _, conclusion := range []string{"cancelled", "failure", "success"} {
		t.Run(conclusion, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, store.RunnerRegistering)
			h.deliverJob(jobEvent{Action: "completed", JobID: 8010, Name: "build", Workflow: "CI",
				Labels: pool.Labels, Conclusion: conclusion, RunnerName: r.Name})
			got := h.runnerByID(t, r.ID)
			if got.State != store.RunnerRemoved || !h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
				t.Fatalf("completion without in_progress left runner %s without removal", got.State)
			}
			if got.JobsHandled != 1 {
				t.Fatalf("jobs handled = %d", got.JobsHandled)
			}
		})
	}
}

func TestCancelledDrainingRunnerIsRemovedAndPersistentDrainIsPreserved(t *testing.T) {
	for _, ephemeral := range []bool{true, false} {
		t.Run(map[bool]string{true: "ephemeral", false: "persistent"}[ephemeral], func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			pool.Ephemeral = ephemeral
			if err := h.st.UpdatePool(h.ctx, pool); err != nil {
				t.Fatal(err)
			}
			_, runner := startJobOnRunner(t, h, host.ID, 8020, pool.Labels)
			if _, err := h.st.TransitionRunner(h.ctx, runner.ID, store.RunnerDraining, "operator drain"); err != nil {
				t.Fatal(err)
			}
			h.deliverJob(jobEvent{Action: "completed", JobID: 8020, Name: "build", Workflow: "CI", Conclusion: "cancelled", RunnerName: runner.Name})
			got := h.runnerByID(t, runner.ID)
			want := store.RunnerDraining
			if ephemeral {
				want = store.RunnerRemoved
			}
			if got.State != want || got.CurrentJobID != "" || got.JobsHandled != 1 {
				t.Fatalf("runner after cancellation: %+v", got)
			}
		})
	}
}

func TestHostRemovalFailureRetriesUntilConfirmed(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	_, runner := startJobOnRunner(t, h, host.ID, 8021, []string{"self-hosted", "linux", "x64", "demo"})
	h.deliverJob(jobEvent{Action: "completed", JobID: 8021, Name: "build", Workflow: "CI", Conclusion: "cancelled", RunnerName: runner.Name})
	h.c.queues = newTaskQueues()
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: "failed-remove", Kind: agent.TaskRemoveRunner, RunnerID: runner.ID, Error: "daemon unavailable"}); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	if !h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
		t.Fatal("failed removal was abandoned")
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: "removed", Kind: agent.TaskRemoveRunner, RunnerID: runner.ID, OK: true, State: store.RunnerRemoved}); err != nil {
