func TestZoomiesRunCancellationStopsWorkBeforeGitHubCompletionEvents(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	pool.Ephemeral = false
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	r := h.runnerRow(pool, host, store.RunnerIdle)
	const runID = 8060
	h.deliverJob(jobEvent{Action: "queued", JobID: 8061, RunID: runID, Name: "build", Workflow: "CI", Labels: pool.Labels})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 8061, RunID: runID, Name: "build", Workflow: "CI", Labels: pool.Labels, RunnerName: r.Name})
	h.deliverJob(jobEvent{Action: "queued", JobID: 8062, RunID: runID, Name: "deploy", Workflow: "CI", Labels: pool.Labels})

	job, err := h.st.GetJobByGitHubID(h.ctx, 8061)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := h.c.CancelJobWorkflow(h.ctx, job.ID, false); err != nil {
		t.Fatal(err)
	}

	// GitHub has accepted the run-scoped request but has not sent completion
	// events. Job states therefore remain authoritative, while local work is
	// already stopped and queued demand cannot create replacement capacity.
	stillRunning, _ := h.st.GetJobByGitHubID(h.ctx, 8061)
	queued, _ := h.st.GetJobByGitHubID(h.ctx, 8062)
	if stillRunning.State != store.JobInProgress {
		t.Fatalf("local cancellation invented terminal state %q before GitHub", stillRunning.State)
	}
	if queued.State != store.JobQueued || queued.Provisioning != "paused" {
		t.Fatalf("queued sibling was not suppressed while awaiting GitHub: %+v", queued)
	}
	if !h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
		t.Fatal("accepted run cancellation did not immediately queue removal of its executing runner")
	}
	h.c.lifecycleCalls.Wait()
	if got := h.runnerByID(t, r.ID); got.State != store.RunnerRemoved {
		t.Fatalf("executing runner after accepted run cancellation = %s", got.State)
	}
}

package controller

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

const (
	capacityDemandEvent = "capacity_demand"
	scaleDownEvent      = "scale_down_opportunity"

	// capacityDemandSchemaVersion is what a receiver checks before it reads
	// the rest. Adding a field never raises it; a change a receiver written
	// for the current shape would misread does.
	capacityDemandSchemaVersion = 1
)

// CapacityDemandEvent is the stable wire contract consumed by provisioners.
// RequiredRunnerSlots is positive for demand and negative for removable idle
// capacity. It is a reading, not an increment: the pool should have
// CurrentCapacity+RequiredRunnerSlots slots, and a receiver that adds
// RequiredRunnerSlots to whatever it already asked for adds the same shortfall
// again on every re-delivery, because each attempt after the cooldown carries
// a fresh EventID for what may be the same unmet demand.
type CapacityDemandEvent struct {
	SchemaVersion         int               `json:"schema_version"`
	EventID               string            `json:"event_id"`
	Type                  string            `json:"type"`
	Timestamp             time.Time         `json:"timestamp"`
	PoolID                string            `json:"pool_id"`
	HostSelector          store.StringMap   `json:"host_selector"`
	Backend               store.BackendKind `json:"backend"`
	RequiredRunnerSlots   int               `json:"required_runner_slots"`
	CurrentCapacity       int               `json:"current_capacity"`
	QueuedJobCount        int               `json:"queued_job_count"`
	OldestQueueAgeSeconds int64             `json:"oldest_queue_age_seconds"`
}

func (c *Controller) publishCapacitySignals(ctx context.Context, snap scheduler.Snapshot, plan scheduler.Plan) {
	if c.cfg().CapacityDemand.DestinationURL == "" {
		return
	}
	pools := make(map[string]*store.Pool, len(snap.Pools))
	for _, p := range snap.Pools {
		pools[p.ID] = p
	}
	// Computed once for every pool in this pass rather than once per pool in
	// the loop below: oldestPoolQueue used to re-walk every job against every
	// pool for each pool it was asked about, which made this whole function
	// quadratic in the pool count on top of its jobs. oldestQueueAges walks
	// the jobs once, calling scheduler.BestPool exactly once per job.
	oldestQueue := oldestQueueAges(snap.Pools, snap.Jobs, snap.Now)
	for _, pp := range plan.Pools {
		p := pools[pp.PoolID]
		if p == nil || !c.capacityPoolAllowed(p) {
			continue
		}
		capacity := eligibleCapacity(p, snap.Hosts, snap.Now)
		oldest := queueAgeSeconds(oldestQueue[p.ID])
		// Both blockages are demand, and the second one is the one a receiver
		// exists for: a pool whose jobs have nowhere to go at all is asking to
		// be scaled from zero, and until this said so the only shortfall
		// Zoomies ever announced was one a finished job would have cleared by
		// itself. A pool blocked for a reason a machine cannot fix -- the wrong
		// platform, a selector nothing matches -- still reaches the receiver,
		// which is correct: the event says what is missing, and deciding
		// whether it can supply it has always been the receiver's half.
		if (pp.BlockedAtCapacity || pp.BlockedNoEligibleHost) && pp.QueuedMatched > 0 {
			slots := max(pp.Desired-pp.Current, 1)
			c.deliverCapacityEvent(ctx, p, capacity, pp.QueuedMatched, oldest, slots, capacityDemandEvent, false)
		} else {
			_ = c.st.DeleteCapacityDemandObservation(ctx, p.ID, capacityDemandEvent)
		}

		// A host provisioner can remove only capacity which is both unused and
		// above this pool's desired runner count. The observation must remain
		// continuously true for one cooldown before it is announced.
		excess := capacity - pp.Desired
		if pp.QueuedMatched == 0 && excess > 0 {
			c.deliverCapacityEvent(ctx, p, capacity, 0, 0, -excess, scaleDownEvent, true)
		} else {
			_ = c.st.DeleteCapacityDemandObservation(ctx, p.ID, scaleDownEvent)
		}
	}
}

func (c *Controller) capacityPoolAllowed(p *store.Pool) bool {
	a := c.cfg().CapacityDemand.Pools
	return len(a) == 0 || slices.Contains(a, p.ID) || slices.Contains(a, p.Name)
}

// eligibleCapacity is the slots the pool can be placed into right now, which
// is a throttled host's effective capacity rather than its configured one: a
// provisioner told the fleet has eight slots while the throttle leaves it four
// would never be asked for the capacity the queue is actually short of.
func eligibleCapacity(p *store.Pool, hosts []*store.Host, now time.Time) int {
	n := 0
	for _, h := range hosts {
		if scheduler.HostCanRun(h, p, now) {
			n += h.EffectiveCapacity()
		}
	}
	return n
}

// oldestQueueAges maps every pool to the age of its oldest queued job, by
// asking scheduler.BestPool which pool claims each job exactly once. A pool
// with no queued job of its own is simply absent, which queueAgeSeconds reads
// the same way oldestPoolQueue's zero-valued accumulator used to.
func oldestQueueAges(pools []*store.Pool, jobs []*store.Job, now time.Time) map[string]time.Duration {
	oldest := make(map[string]time.Duration, len(pools))
	for _, j := range jobs {
		p := scheduler.BestPool(pools, j)
		if p == nil {
			continue
		}
		if a := now.Sub(j.QueuedAt); a > oldest[p.ID] {
			oldest[p.ID] = a
		}
	}
	return oldest
}

// queueAgeSeconds turns a queue age into the whole seconds the wire event
// carries, treating a negative reading (a job queued in the future, as a
// clock skew or a test fixture might produce) the same as no wait at all.
func queueAgeSeconds(d time.Duration) int64 {
	if d < 0 {
		return 0
	}
	return int64(d / time.Second)
}

func (c *Controller) deliverCapacityEvent(ctx context.Context, p *store.Pool, capacity, queued int, oldest int64, slots int, eventType string, sustained bool) {
	now := c.Now()
	previous, err := c.st.GetCapacityDemandDelivery(ctx, p.ID, eventType)
	if err == nil {
		// Attempt time, rather than only success time, is the durable circuit
		// breaker which prevents an unavailable receiver (and controller
		// restarts) from turning every reconciliation tick into a request storm.
		if previous.AttemptedAt != nil && now.Sub(*previous.AttemptedAt) < c.cfg().CapacityDemand.Cooldown {
			return
		}
		if sustained && previous.AttemptedAt == nil && now.Sub(previous.ObservedSince) < c.cfg().CapacityDemand.Cooldown {
			return
		}
	} else if err == store.ErrNotFound {
		if sustained {
			_ = c.st.PutCapacityDemandDelivery(ctx, &store.CapacityDemandDelivery{PoolID: p.ID, EventType: eventType, EventID: store.NewSecret(12), Payload: "", ObservedSince: now})
			return
		}
	} else {
		c.log.Error("could not read capacity-demand delivery state", "error", err)
		return
	}

	e := CapacityDemandEvent{SchemaVersion: capacityDemandSchemaVersion, EventID: store.NewSecret(12), Type: eventType, Timestamp: now, PoolID: p.ID, HostSelector: p.HostSelector, Backend: p.Backend, RequiredRunnerSlots: slots, CurrentCapacity: capacity, QueuedJobCount: queued, OldestQueueAgeSeconds: oldest}
	body, _ := json.Marshal(e)
	d := &store.CapacityDemandDelivery{PoolID: p.ID, EventType: eventType, EventID: e.EventID, Payload: string(body), ObservedSince: now, AttemptedAt: &now}
	// The attempt is recorded before the request is made, not after: it is
	// the circuit breaker the cooldown check above reads, and the next pass
	// may well arrive before the receiver has answered.
	if err := c.st.PutCapacityDemandDelivery(ctx, d); err != nil {
		c.log.Error("could not persist capacity-demand delivery", "error", err)
		return
	}

	// The request itself leaves the reconcile pass. This function runs under
	// the reconcile lock, and a receiver that accepts the connection and never
	// answers held every pass for three attempts of the timeout, per pool, per
	// event type -- tens of seconds in which nothing scaled. The delivery gets
	// a context of its own, bounded by the attempts it may make, so a pass
	// ending or the controller stopping does not cut a request off half-way.
	timeout := c.cfg().CapacityDemand.Timeout
	c.deliveries.Add(1)
	go func() {
		defer c.deliveries.Done()
		dctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 3*timeout+time.Second)
		defer cancel()
		c.finishCapacityDelivery(dctx, p, e, body, d)
	}()
}

// finishCapacityDelivery makes the request and records how it went.
func (c *Controller) finishCapacityDelivery(ctx context.Context, p *store.Pool, e CapacityDemandEvent, body []byte, d *store.CapacityDemandDelivery) {
	status, attempts, sendErr := c.postCapacityEvent(ctx, body, e)
	d.StatusCode = status
	d.Attempts = attempts
	if sendErr != nil {
		d.LastError = sendErr.Error()
	} else {
		delivered := c.Now()
		d.DeliveredAt = &delivered
	}
	if err := c.st.PutCapacityDemandDelivery(ctx, d); err != nil {
		c.log.Error("could not persist capacity-demand delivery", "error", err)
	}
	action := "capacity_demand.delivered"
	if sendErr != nil {
		action = "capacity_demand.failed"
	}
	c.authsvc.Auditor().Act(ctx, auth.SystemIdentity(), action, "pool", p.ID, map[string]any{"event_id": e.EventID, "type": d.EventType, "status_code": status, "attempts": attempts, "error": d.LastError})
}

func (c *Controller) postCapacityEvent(ctx context.Context, body []byte, e CapacityDemandEvent) (int, int, error) {
	mac := hmac.New(sha256.New, []byte(c.cfg().CapacityDemand.SigningSecret))
	mac.Write(body)
	signature := "sha256=" + hex.EncodeToString(mac.Sum(nil))
	var last error
	status := 0
	for attempt := 1; attempt <= 3; attempt++ {
		reqCtx, cancel := context.WithTimeout(ctx, c.cfg().CapacityDemand.Timeout)
		req, err := http.NewRequestWithContext(reqCtx, http.MethodPost, c.cfg().CapacityDemand.DestinationURL, bytes.NewReader(body))
		if err == nil {
			req.Header.Set("Content-Type", "application/json")
			req.Header.Set("X-Zoomies-Event-ID", e.EventID)
			req.Header.Set("X-Zoomies-Timestamp", e.Timestamp.Format(time.RFC3339Nano))
			req.Header.Set("X-Zoomies-Signature-256", signature)
			var resp *http.Response
			resp, err = c.httpClient.Do(req)
			if resp != nil {
				status = resp.StatusCode
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
				if status >= 200 && status < 300 {
					cancel()
					return status, attempt, nil
				}
				err = fmt.Errorf("receiver returned HTTP %d", status)
			}
		}
		cancel()
		last = err
		if ctx.Err() != nil {
			return status, attempt, ctx.Err()
		}
		if attempt < 3 {
			timer := time.NewTimer(time.Duration(1<<(attempt-1)) * 100 * time.Millisecond)
			select {
			case <-ctx.Done():
				timer.Stop()
				return status, attempt, ctx.Err()
			case <-timer.C:
			}
		}
	}
	return status, 3, last
}

package controller

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

func TestCapacityDemandSignatureCooldownAndDuplicateTicks(t *testing.T) {
	h := newHarness(t)
	var mu sync.Mutex
	var bodies [][]byte
	var signatures []string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
		bodies = append(bodies, body)
		signatures = append(signatures, r.Header.Get("X-Zoomies-Signature-256"))
		mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "receiver-secret"
	h.cfg.CapacityDemand.Cooldown = time.Hour
	h.cfg.CapacityDemand.Timeout = time.Second
	p := &store.Pool{ID: "pool-cap", Backend: store.BackendDocker, HostSelector: store.StringMap{"zone": "a"}}

	h.c.deliverCapacityEvent(h.ctx, p, 4, 2, 90, 2, capacityDemandEvent, false)
	h.c.deliveries.Wait()
	h.c.deliverCapacityEvent(h.ctx, p, 4, 2, 90, 2, capacityDemandEvent, false)
	h.c.deliveries.Wait()
	mu.Lock()
	defer mu.Unlock()
	if len(bodies) != 1 {
		t.Fatalf("requests = %d, want one deduplicated request", len(bodies))
	}
	mac := hmac.New(sha256.New, []byte("receiver-secret"))
	mac.Write(bodies[0])
	want := "sha256=" + hex.EncodeToString(mac.Sum(nil))
	if !hmac.Equal([]byte(signatures[0]), []byte(want)) {
		t.Fatalf("signature = %q, want %q", signatures[0], want)
	}
	// The receiver page tells its reader to check the schema version first and
	// to read current_capacity + required_runner_slots as the capacity the pool
	// should have, so those three fields are the contract this test holds.
	var got CapacityDemandEvent
	if err := json.Unmarshal(bodies[0], &got); err != nil {
		t.Fatalf("payload %s: %v", bodies[0], err)
	}
	if got.SchemaVersion != 1 || got.EventID == "" || got.Type != capacityDemandEvent {
		t.Fatalf("payload = %+v, want schema_version 1, an event id and type %q", got, capacityDemandEvent)
	}
	if got.CurrentCapacity+got.RequiredRunnerSlots != 6 {
		t.Fatalf("current_capacity %d + required_runner_slots %d = %d, want the 6 slots the pool should have", got.CurrentCapacity, got.RequiredRunnerSlots, got.CurrentCapacity+got.RequiredRunnerSlots)
	}
}

func TestCapacityDemandFailureAndRecovery(t *testing.T) {
	h := newHarness(t)
	now := time.Date(2026, 9, 5, 12, 0, 0, 0, time.UTC)
	h.c.clock = func() time.Time { return now }
	var mu sync.Mutex
	failing := true
	requests := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		mu.Lock()
		defer mu.Unlock()
		requests++
		if failing {
			http.Error(w, "not now", http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "secret"
	h.cfg.CapacityDemand.Cooldown = time.Hour
	h.cfg.CapacityDemand.Timeout = time.Second
	p := &store.Pool{ID: "pool-recovery", Backend: store.BackendDocker}

	h.c.deliverCapacityEvent(h.ctx, p, 1, 1, 30, 1, capacityDemandEvent, false)
	h.c.deliveries.Wait()
	d, err := h.st.GetCapacityDemandDelivery(h.ctx, p.ID, capacityDemandEvent)
	if err != nil || d.DeliveredAt != nil || d.Attempts != 3 || d.LastError == "" {
		t.Fatalf("failed delivery = %+v, %v", d, err)
	}
	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, problem := range problems {
		found = found || (problem.Code == "capacity_demand.delivery_failed" && problem.TargetID == p.ID)
	}
	if !found {
		t.Fatal("latest failed delivery was not surfaced in Problems")
	}

	mu.Lock()
	failing = false
	mu.Unlock()
	// A failed burst is also cooled down, preventing every reconciliation tick
	// (or a restart) from becoming a new delivery storm.
	h.c.deliverCapacityEvent(h.ctx, p, 1, 1, 30, 1, capacityDemandEvent, false)
	h.c.deliveries.Wait()
	mu.Lock()
	if requests != 3 {
		t.Fatalf("requests during cooldown = %d, want 3", requests)
	}
	mu.Unlock()
	now = now.Add(time.Hour)
	h.c.deliverCapacityEvent(h.ctx, p, 1, 1, 30, 1, capacityDemandEvent, false)
	h.c.deliveries.Wait()
	d, err = h.st.GetCapacityDemandDelivery(h.ctx, p.ID, capacityDemandEvent)
	if err != nil || d.DeliveredAt == nil || d.LastError != "" {
		t.Fatalf("recovered delivery = %+v, %v", d, err)
	}
	mu.Lock()
	defer mu.Unlock()
	if requests != 4 {
		t.Fatalf("requests = %d, want three bounded retries then one recovery", requests)
	}
}

func TestScaleDownRequiresSustainedExcessCapacity(t *testing.T) {
	h := newHarness(t)
	now := time.Date(2026, 9, 5, 12, 0, 0, 0, time.UTC)
	h.c.clock = func() time.Time { return now }
	requests := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { requests++; w.WriteHeader(204) }))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "secret"
	h.cfg.CapacityDemand.Cooldown = time.Minute
	h.cfg.CapacityDemand.Timeout = time.Second
	p := &store.Pool{ID: "pool-down", Backend: store.BackendDocker}

	h.c.deliverCapacityEvent(h.ctx, p, 8, 0, 0, -4, scaleDownEvent, true)
	h.c.deliveries.Wait()
	if requests != 0 {
		t.Fatal("scale-down emitted before sustained cooldown")
	}
	now = now.Add(time.Minute)
	h.c.deliverCapacityEvent(h.ctx, p, 8, 0, 0, -4, scaleDownEvent, true)
	h.c.deliveries.Wait()
	if requests != 1 {
		t.Fatalf("requests = %d, want one sustained scale-down opportunity", requests)
	}
}

// The request to the receiver used to run inside the reconcile pass, under
// its lock, so a receiver that accepted the connection and never answered
// held scaling for three attempts of the timeout. The pass now records the
// attempt and moves on; the request finishes on its own.
func TestASlowCapacityReceiverDoesNotHoldTheReconcilePass(t *testing.T) {
	h := newHarness(t)
	release := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		<-release
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "secret"
	h.cfg.CapacityDemand.Cooldown = time.Hour
	h.cfg.CapacityDemand.Timeout = 10 * time.Second
	p := &store.Pool{ID: "pool-slow", Backend: store.BackendDocker}

	started := time.Now()
	h.c.deliverCapacityEvent(h.ctx, p, 1, 1, 30, 1, capacityDemandEvent, false)
	if took := time.Since(started); took > time.Second {
		t.Fatalf("deliverCapacityEvent took %s with the receiver hanging; the pass must not wait on it", took)
	}
	// The attempt is already on record, which is what stops the next pass
	// from sending a second request while this one is still in the air.
	d, err := h.st.GetCapacityDemandDelivery(h.ctx, p.ID, capacityDemandEvent)
	if err != nil || d.AttemptedAt == nil || d.DeliveredAt != nil {
		t.Fatalf("delivery before the receiver answered = %+v, %v; want the attempt recorded and no outcome yet", d, err)
	}
	h.c.deliverCapacityEvent(h.ctx, p, 1, 1, 30, 1, capacityDemandEvent, false)

	close(release)
	h.c.deliveries.Wait()
	d, err = h.st.GetCapacityDemandDelivery(h.ctx, p.ID, capacityDemandEvent)
	if err != nil || d.DeliveredAt == nil || d.Attempts != 1 {
		t.Fatalf("delivery after the receiver answered = %+v, %v; want one delivered attempt", d, err)
	}
}

// The one shortfall Zoomies never used to announce.
//
// A receiver exists to add hosts, and the case it most needs to hear about is
// the pool with queued work and no host that could run it at all -- scaling
// from zero. The publisher only ever fired on BlockedAtCapacity, which means
// "every host is busy", so a fleet with nothing to be busy said nothing.
func TestTheCapacityDemandEventFiresWhenNoHostCanEverRunThePool(t *testing.T) {
	h := newHarness(t)
	var mu sync.Mutex
	var bodies [][]byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
		bodies = append(bodies, body)
		mu.Unlock()
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "secret"
	h.cfg.CapacityDemand.Cooldown = time.Hour
	h.cfg.CapacityDemand.Timeout = time.Second

	p := &store.Pool{ID: "pool_zero", Name: "linux-x64", Backend: store.BackendDocker}
	snap := scheduler.Snapshot{Now: time.Now(), Pools: []*store.Pool{p}}
	plan := scheduler.Plan{Pools: []scheduler.PoolPlan{{
		PoolID:                p.ID,
		PoolName:              p.Name,
		Current:               0,
		Desired:               3,
		QueuedMatched:         3,
		BlockedNoEligibleHost: true,
	}}}

	h.c.publishCapacitySignals(h.ctx, snap, plan)
	h.c.deliveries.Wait()

	mu.Lock()
	defer mu.Unlock()
	if len(bodies) != 1 {
		t.Fatalf("requests = %d, want one demand event for a pool with nowhere to run", len(bodies))
	}
	var got CapacityDemandEvent
	if err := json.Unmarshal(bodies[0], &got); err != nil {
		t.Fatalf("payload %s: %v", bodies[0], err)
	}
	if got.Type != capacityDemandEvent {
		t.Fatalf("type = %q, want %q", got.Type, capacityDemandEvent)
	}
	// The event is a reading: an empty fleet has no capacity, and the three
	// slots it is missing are the three the pool should have.
	if got.CurrentCapacity != 0 || got.CurrentCapacity+got.RequiredRunnerSlots != 3 {
		t.Fatalf("current_capacity %d + required_runner_slots %d, want 0 + 3",
			got.CurrentCapacity, got.RequiredRunnerSlots)
	}
}

// And a pool that is blocked for neither reason still says nothing, so a
// receiver is not woken by a fleet that is merely waiting out a scale-up delay.
func TestNoCapacityDemandWithoutABlockage(t *testing.T) {
	h := newHarness(t)
	requests := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		requests++
		w.WriteHeader(http.StatusNoContent)
	}))
	defer srv.Close()
	h.cfg.CapacityDemand.DestinationURL = srv.URL
	h.cfg.CapacityDemand.SigningSecret = "secret"
	h.cfg.CapacityDemand.Cooldown = time.Hour
	h.cfg.CapacityDemand.Timeout = time.Second

	p := &store.Pool{ID: "pool_quiet", Name: "linux-x64", Backend: store.BackendDocker}
	h.c.publishCapacitySignals(h.ctx,
		scheduler.Snapshot{Now: time.Now(), Pools: []*store.Pool{p}},
		scheduler.Plan{Pools: []scheduler.PoolPlan{{PoolID: p.ID, PoolName: p.Name, Desired: 1, QueuedMatched: 1}}})
	h.c.deliveries.Wait()

	if requests != 0 {
		t.Fatalf("requests = %d, want none for a pool nothing is blocking", requests)
	}
}

package controller

import (
	"fmt"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The host and GitHub finish independently. One side succeeding must not
// erase the other side's failure, including when both failed first.
func TestHostCleanupDoesNotHideARegistrationThatStillExists(t *testing.T) {
	for _, hostFailsFirst := range []bool{false, true} {
		name := "registration failure only"
		if hostFailsFirst {
			name = "both sides failed"
		}
		t.Run(name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, store.RunnerIdle)
			if err := h.st.SetRunnerGitHubID(h.ctx, r.ID, 4242); err != nil {
				t.Fatal(err)
			}
			h.gh.SetError("/actions/runners/4242", 403, "Resource not accessible by integration")
			if _, err := h.c.removeRunner(h.ctx, h.runnerByID(t, r.ID), "scaling down", pool); err != nil {
				t.Fatal(err)
			}
			if hostFailsFirst {
				if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
					TaskID: "remove_failed", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
					OK: false, Error: "container is in use",
				}); err != nil {
					t.Fatal(err)
				}
			}
			if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
				TaskID: "remove_succeeded", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
				OK: true, State: store.RunnerRemoved,
			}); err != nil {
				t.Fatal(err)
			}
			got := h.runnerByID(t, r.ID)
			if !strings.Contains(got.CleanupError, "registration") || got.CleanupFailedAt == nil {
				t.Fatalf("host success hid the registration failure: error=%q failed_at=%v", got.CleanupError, got.CleanupFailedAt)
			}
			if got.CleanedUpAt != nil {
				t.Fatal("cleanup was marked complete while GitHub still refuses deletion")
			}
			if !contains(h.problemCodes(), "runners.cleanup_failed") {
				t.Fatal("the unfinished registration cleanup disappeared from Problems")
			}
			h.gh.ClearErrors()
			h.c.deleteRegistration(h.ctx, got, pool)
			got = h.runnerByID(t, r.ID)
			if got.CleanupError != "" || got.CleanupFailedAt != nil {
				t.Fatalf("successful registration retry did not clear its own failure: %q", got.CleanupError)
			}
		})
	}
}

func TestRegistrationReapingDoesNotHideAFailedHostRemoval(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRemoved)
	h.gh.AddRunner(r.Name, pool.Labels)
	if err := h.st.RecordRegistrationCleanupFailure(h.ctx, r.ID, "registration deletion refused"); err != nil {
		t.Fatal(err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "remove_failed", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: false, Error: "container is in use",
	}); err != nil {
		t.Fatal(err)
	}
	h.c.reap(h.ctx)
	if len(h.gh.Runners()) != 0 {
		t.Fatal("the reaper did not delete the registration")
	}
	got := h.runnerByID(t, r.ID)
	if !strings.Contains(got.CleanupError, "container is in use") || strings.Contains(got.CleanupError, "registration") {
		t.Fatalf("the reaper must clear only its own error: %q", got.CleanupError)
	}
	if got.CleanedUpAt != nil || !contains(h.problemCodes(), "runners.cleanup_failed") {
		t.Fatal("the reaper hid the host's unfinished cleanup")
	}
}

// A remove that fails on a runner the fleet has already finished with used to
// vanish.
//
// The result arrives for a terminal row, the state machine refuses to move a
// removed runner to failed -- correctly, it cannot -- and before this the
// refusal was logged at debug and that was the end of it. Meanwhile the
// container is still on the host, holding its writable layer and, on a
// docker-in-docker pool, a privileged sidecar. Nobody was told.
func TestARemoveThatFailsOnATerminalRunnerIsRecorded(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "task_1", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: false, Error: "the daemon refused: container is in use",
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	got := h.runnerByID(t, r.ID)
	if got.CleanupError == "" {
		t.Fatal("the failed remove left no record on the row; the container is on the host and nobody is told")
	}
	if !strings.Contains(got.CleanupError, "container is in use") {
		t.Errorf("cleanup_error = %q, want it to carry what the agent said", got.CleanupError)
	}
	if got.CleanupAttempts != 1 {
		t.Errorf("cleanup_attempts = %d, want 1", got.CleanupAttempts)
	}
	if got.CleanupFailedAt == nil {
		t.Error("cleanup_failed_at is unset, so the problem has no age")
	}
	// The row must not be dragged back through the state machine: its slot is
	// free and the scheduler has moved on.
	if got.State != store.RunnerRemoved {
		t.Errorf("state = %q, want it to stay removed: recording a tidying problem must not change capacity", got.State)
	}
}

// And it must be somewhere an operator looks, not only in a column.
func TestARunnerThatWillNotCleanUpRaisesAProblem(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}
	if contains(h.problemCodes(), "runners.cleanup_failed") {
		t.Fatalf("problems = %v; a runner that cleaned up fine is not a problem", h.problemCodes())
	}

	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "task_1", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: false, Error: "the daemon refused",
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if !contains(h.problemCodes(), "runners.cleanup_failed") {
		t.Fatalf("problems = %v, want runners.cleanup_failed", h.problemCodes())
	}
}

// A retry that works clears the complaint, and closes the runner's life.
// Otherwise the problems panel would keep naming a runner that is long gone,
// and an operator would learn to ignore it.
func TestACleanupThatEventuallyWorksClearsTheRecord(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerDraining, "draining"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}
	if err := h.st.RecordCleanupFailure(h.ctx, r.ID, "remove_runner failed: the daemon refused"); err != nil {
		t.Fatalf("RecordCleanupFailure: %v", err)
	}

	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "task_2", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: true, State: store.RunnerRemoved,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	before := h.runnerByID(t, r.ID)
	if before.HostRemovedAt == nil {
		t.Fatal("host cleanup was not durable before ACK")
	}
	// Remote registration deletion now runs after ingestion has acknowledged.
	h.c.enrichOnce(h.ctx)

	got := h.runnerByID(t, r.ID)
	if got.CleanupError != "" {
		t.Errorf("cleanup_error = %q, want it cleared once the removal worked", got.CleanupError)
	}
	if got.CleanedUpAt == nil {
		t.Error("cleaned_up_at is unset; the cleanup interval never closed")
	}
	// The count survives. How many tries it took is the difference between a
	// blip and a host worth looking at.
	if got.CleanupAttempts != 1 {
		t.Errorf("cleanup_attempts = %d, want the history kept", got.CleanupAttempts)
	}
	if contains(h.problemCodes(), "runners.cleanup_failed") {
		t.Fatalf("problems = %v; the problem should clear with the record", h.problemCodes())
	}
}

// A log task that fails says nothing about cleanup: the container is where it
// was, doing what it was doing. Recording it would send an operator looking for
// litter that is not there.
//
// The runner is terminal on purpose. That is the case where the guard is
// load-bearing -- on a live runner the failure would be an ordinary transition
// to failed and never reach the cleanup record at all.
func TestAFailedLogTaskIsNotACleanupFailure(t *testing.T) {
