func TestCleanupSnapshotNeverSettlesALiveRunner(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)
	h.c.reap(h.ctx)
	if h.runnerByID(t, r.ID).RegistrationDeletedAt != nil {
		t.Fatal("empty snapshot settled a live runner")
	}
}

func TestCleanupIdleListingCanRaceWithBusyDelete(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRemoved)
	h.gh.AddRunner(r.Name, pool.Labels)
	h.gh.SetMethodError(http.MethodDelete, "/actions/runners/", http.StatusUnprocessableEntity, "Bad request - Runner is currently running a job and cannot be deleted")
	h.c.reap(h.ctx)
	got := h.runnerByID(t, r.ID)
	if got.CleanupAttempts != 0 || !strings.Contains(got.CleanupError, "deferred") || got.RegistrationDeletedAt != nil {
		t.Fatalf("busy race not deferred: %+v", got)
	}
	h.gh.ClearErrors()
	h.c.reap(h.ctx)
	if h.runnerByID(t, r.ID).RegistrationDeletedAt == nil {
		t.Fatal("idle retry never recovered")
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// ManagedRunnerGroupName is the organisation runner group Zoomies provisions
// and uses for pools that do not explicitly choose another one.
const ManagedRunnerGroupName = "zoomies"

// probeInterval is how often every installation's credentials are re-checked.
// It is minutes rather than seconds because the failure it catches -- a
// revoked App, a rotated key, a permission removed by an org admin -- happens
// on human timescales, and each probe costs three API calls.
const probeInterval = 5 * time.Minute

// clientCache holds one github.Client per installation.
//
// The cache key includes the installation's updated_at, so editing an
// installation (a new private key, a different target) invalidates its client
// without anyone having to remember to do it.
type clientCache struct {
	c *Controller

	mu      sync.Mutex
	entries map[string]*clientEntry
}

type clientEntry struct {
	client    github.Client
	updatedAt time.Time
	// groups maps runner group names to their GitHub policy for this
	// installation. It is filled lazily because the lookup costs an API call.
	groups map[string]github.RunnerGroup
}

func newClientCache(c *Controller) *clientCache {
	return &clientCache{c: c, entries: map[string]*clientEntry{}}
}

// ClientFor returns a GitHub client for one installation, identified by its
// Zoomies installation ID ("ins_...").
func (c *Controller) ClientFor(ctx context.Context, installationID string) (github.Client, error) {
	inst, err := c.st.GetInstallation(ctx, installationID)
	if err != nil {
		return nil, err
	}
	return c.clients.get(ctx, inst)
}

// ClientForRepo returns the client for whichever installation covers a
// repository, preferring a repo-scoped installation over the owning org.
func (c *Controller) ClientForRepo(ctx context.Context, repoFullName string) (github.Client, error) {
	inst, err := c.st.FindInstallationByTarget(ctx, repoFullName)
	if err != nil {
		return nil, err
	}
	return c.clients.get(ctx, inst)
}

// get returns a cached client, building one if the installation is new to the
// cache or has been edited since it was cached.
func (cc *clientCache) get(ctx context.Context, inst *store.Installation) (github.Client, error) {
	if inst == nil {
		return nil, errors.New("controller: no installation given")
	}
	// The demo fixtures have no GitHub App behind them, so every real client
	// path would fail on the placeholder key they carry. The check lives here
	// rather than at one call site because it was at one call site: `ClientFor`
	// had it and `ProbeInstallation` did not, so pressing Verify on the demo
	// installation answered "the stored private key is not a PEM-encoded RSA
	// key" -- on the one page a new operator is most likely to press it.
	if IsDemoID(inst.ID) {
		return newDemoClient(inst), nil
	}
	cc.mu.Lock()
	if e, ok := cc.entries[inst.ID]; ok && e.updatedAt.Equal(inst.UpdatedAt) {
		cc.mu.Unlock()
		return e.client, nil
	}
	cc.mu.Unlock()

	pem, err := cc.c.key.Open(inst.PrivateKeyEnc)
	if err != nil {
		// A key mismatch is a real operational situation -- an operator
		// restored a database without its encryption key -- so the message has
		// to say that, and say which installation cannot be used.
		return nil, fmt.Errorf("installation %s (%s): the stored GitHub App private key cannot be decrypted: %w; "+
			"either restore the encryption key this data was written with, or upload the App's .pem again on the Installations page",
			inst.ID, inst.Target, err)
	}
	if len(pem) == 0 {
		return nil, fmt.Errorf("installation %s (%s) has no GitHub App private key stored; upload the App's .pem file on the Installations page",
			inst.ID, inst.Target)
	}

	client, err := cc.c.factory.For(ctx, inst, pem)
	if err != nil {
		return nil, err
	}

	cc.mu.Lock()
	cc.entries[inst.ID] = &clientEntry{client: client, updatedAt: inst.UpdatedAt}
	cc.mu.Unlock()
	return client, nil
}

// forget drops an installation's cached client, used when it is deleted.
func (cc *clientCache) forget(id string) {
	cc.mu.Lock()
	defer cc.mu.Unlock()
	delete(cc.entries, id)
}

// Forget drops the cached client for an installation. The API calls it after
// deleting or re-keying one, so the next call rebuilds from the stored row.
func (c *Controller) Forget(installationID string) {
	c.clients.forget(installationID)
	// Its rate-limit hold goes with it. The hold is read only when the
	// installation comes round on a sweep, so a stale entry changes nothing --
	// but an installation that is gone should leave nothing behind, and one
	// re-added under the same identifier would inherit a stand-down it never
	// earned.
	c.githubMu.Lock()
	delete(c.githubPaused, installationID)
	c.githubMu.Unlock()
}

// runnerGroupID resolves a runner group name to the ID the JIT config API
// wants. An empty or unknown name falls back to 0, which the github package
// turns into the Default group every target has.
//
// The second return value is why the fallback happened, empty when it did not.
// Falling back is not a detail: Default is usually wider than a named group,
// so a pool that asked to be fenced into one and quietly landed in Default may
// run jobs it was not meant for. Conversely, a group that blocks public
// repositories makes an online runner ineligible for their jobs. The caller
// turns both conditions into standing warnings.
func (cc *clientCache) runnerGroupID(ctx context.Context, inst *store.Installation, client github.Client, name string) (int64, string, bool) {
	name = strings.TrimSpace(name)
	wantsDefault := name == "" || strings.EqualFold(name, "default")
	lookup := strings.ToLower(name)
	if wantsDefault {
		lookup = "default"
	}

	if inst.TargetType == store.TargetRepo {
		if wantsDefault {
			return 0, "", false
		}
		cc.c.log.Warn("a repository target has no runner groups; using the default group",
			"installation", inst.ID, "target", inst.Target, "group", name)
		return 0, "runner groups belong to an organisation, and " + inst.Target + " is a repository", false
	}

	cc.mu.Lock()
	e := cc.entries[inst.ID]
	if e != nil && e.groups != nil {
		if group, ok := e.groups[lookup]; ok {
			cc.mu.Unlock()
			return group.ID, "", group.PublicRepositoryAccessKnown && !group.AllowsPublicRepositories
		}
	}
	cc.mu.Unlock()

	// A name that resolved to nothing is deliberately not cached, so that the
	// next create asks again. It costs one call per runner on a pool that is
	// misconfigured, and it is what lets the warning clear by itself the
	// moment an operator creates the group GitHub was missing.
	groups, err := client.ListRunnerGroups(ctx)
	if errors.Is(err, github.ErrRateLimited) {
		cc.c.holdRateLimited(inst.ID, err, cc.c.Now(), "resolving runner groups")
	}
	if err != nil {
		// A pool naming a group Zoomies cannot list still deserves a runner;
		// GitHub will place it in Default and the operator sees the warning.
		cc.c.log.Warn("could not list runner groups; falling back to the default group",
			"installation", inst.ID, "group", name, "error", err)
		if wantsDefault {
			return 0, "", false
		}
		return 0, "GitHub would not say which runner groups exist on " + inst.Target, false
	}

	var found github.RunnerGroup
	m := make(map[string]github.RunnerGroup, len(groups))
	for _, g := range groups {
		key := strings.ToLower(g.Name)
		m[key] = g
		if key == lookup || (wantsDefault && g.Default) {
			found = g
		}
	}
	cc.mu.Lock()
	if e := cc.entries[inst.ID]; e != nil {
		e.groups = m
	}
	cc.mu.Unlock()

	if found.ID == 0 {
		if wantsDefault {
			return 0, "", false
		}
		cc.c.log.Warn("the pool names a runner group that does not exist on the target; using the default group",
			"installation", inst.ID, "target", inst.Target, "group", name)
		return 0, "the group " + name + " does not exist on " + inst.Target, false
	}
	return found.ID, "", found.PublicRepositoryAccessKnown && !found.AllowsPublicRepositories
}

// probeLoop re-checks every installation's credentials on an interval, so a
// revoked App or a rotated key shows up on the Installations page instead of
// as runners that quietly stop being created.
func (c *Controller) probeLoop(ctx context.Context) {
	// Probe once shortly after startup rather than immediately: it costs API
	// calls, and an operator restarting the controller does not need them in
	// the first second.
	timer := time.NewTimer(5 * time.Second)
	defer timer.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
			c.probeInstallations(ctx)
			timer.Reset(probeInterval)
		}
	}
}

// probeInstallations checks every installation and records the result.
func (c *Controller) probeInstallations(ctx context.Context) {
	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		c.log.Error("could not list installations to check their credentials", "error", err)
		return
	}
	for _, inst := range insts {
		if ctx.Err() != nil {
			return
		}
		if IsDemoID(inst.ID) {
			continue
		}
		// Every other background path stands down from an installation GitHub
		// has rate-limited; the probe spends the same quota (runners, groups,
		// repositories), so it waits too.
		if c.githubHeld(inst.ID, c.Now()) {
			c.log.Debug("not checking installation credentials while it is rate limited",
				"installation", inst.ID, "target", inst.Target)
			continue
		}
		if _, err := c.ProbeInstallation(ctx, inst.ID); err != nil {
			c.log.Warn("installation credentials are not usable",
				"installation", inst.ID, "target", inst.Target, "error", err)
		}
	}
}

// refreshRunnerGroupProblems makes group eligibility visible even when a
// controller upgrade finds an already-full pool and therefore has no reason
// to mint another runner. Without this probe-only path, the warning would not
// appear until the next scale-up -- exactly when an ineligible group can leave
// every existing runner idle forever.
func (c *Controller) refreshRunnerGroupProblems(ctx context.Context, inst *store.Installation, client github.Client) {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not inspect pool runner groups", "installation", inst.ID, "error", err)
		return
	}
	for _, pool := range pools {
		if pool.InstallationID != inst.ID {
			continue
		}
		_, unresolved, publicBlocked := c.clients.runnerGroupID(ctx, inst, client, pool.RunnerGroup)
		c.noteRunnerGroup(pool, pool.RunnerGroup, unresolved, publicBlocked)
	}
}

// ensureManagedRunnerGroup creates the organisation-wide group Zoomies owns,
// or reuses a compatible one left by an earlier setup attempt. It deliberately
// does not rewrite a same-named group with a different policy: that group may
// belong to an administrator, and widening it to public repositories is a
// security decision setup must never make silently.
func (c *Controller) ensureManagedRunnerGroup(ctx context.Context, inst *store.Installation, client github.Client) (*github.RunnerGroup, error) {
	if inst.TargetType != store.TargetOrg || IsDemoID(inst.ID) {
		return nil, nil
	}
	groups, err := client.ListRunnerGroups(ctx)
	if err != nil {
		return nil, fmt.Errorf("list runner groups before provisioning %s: %w", ManagedRunnerGroupName, err)
	}
	for i := range groups {
		g := &groups[i]
		if !strings.EqualFold(g.Name, ManagedRunnerGroupName) {
			continue
		}
		if g.Visibility != "all" || !g.PublicRepositoryAccessKnown || !g.AllowsPublicRepositories || g.RestrictedToWorkflows {
			return nil, fmt.Errorf("runner group %s already exists but is not the organisation-wide group Zoomies needs; configure it with visibility all, Allow public repositories enabled, and no workflow restriction, or rename it so Zoomies can create its own", g.Name)
		}
		return g, nil
	}

	g, err := client.CreateRunnerGroup(ctx, github.RunnerGroupCreate{
		Name: ManagedRunnerGroupName, Visibility: "all", AllowsPublicRepositories: true,
	})
	if err != nil {
		return nil, fmt.Errorf("provision runner group %s: %w", ManagedRunnerGroupName, err)
	}
	// ListRunnerGroups is cached for JIT creation. Drop only that snapshot so
	// the new group is resolvable immediately without rebuilding credentials.
	c.clients.mu.Lock()
	if e := c.clients.entries[inst.ID]; e != nil {
		e.groups = nil
	}
	c.clients.mu.Unlock()
	c.log.Info("created the managed GitHub runner group", "installation", inst.ID,
		"target", inst.Target, "group", g.Name)
	return g, nil
}

// adoptManagedRunnerGroup moves only pools that still use GitHub's implicit
// Default group. Explicit group choices are administrator policy and stay
// untouched. Existing non-busy runners were registered in Default, so recycle
// them; the scheduler replaces them in the managed group on its next pass.
func (c *Controller) adoptManagedRunnerGroup(ctx context.Context, inst *store.Installation, group *github.RunnerGroup) error {
	if group == nil {
		return nil
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return err
	}
	changed := false
	for _, pool := range pools {
		if pool.InstallationID != inst.ID || strings.TrimSpace(pool.RunnerGroup) != "" {
			continue
		}
		runners, err := c.st.ListRunnersForPool(ctx, pool.ID)
		if err != nil {
			return err
		}
		pool.RunnerGroup = group.Name
		if err := c.st.UpdatePool(ctx, pool); err != nil {
			return err
		}
		c.PublishPool(ctx, events.KindPoolUpdated, pool)
		for _, runner := range runners {
			if runner.State != store.RunnerIdle && runner.State != store.RunnerRegistering {
				continue
			}
			if err := c.drainRunnerID(ctx, runner.ID,
				"pool moved from GitHub Default to the managed "+group.Name+" runner group", pool); err != nil {
				c.log.Warn("could not recycle a runner after assigning its pool to the managed group",
					"pool", pool.Name, "runner", runner.ID, "error", err)
			}
		}
		changed = true
	}
	if changed {
		c.Nudge()
	}
	return nil
}

// ProbeInstallation verifies one installation's credentials end to end and
// records the outcome, publishing it so the UI updates.
//
// It returns the App information on success and the operator-facing error on
// failure; the error is also stored, because "why is nothing scaling?" is
// answered on the Installations page.
func (c *Controller) ProbeInstallation(ctx context.Context, installationID string) (*github.AppInfo, error) {
	inst, err := c.st.GetInstallation(ctx, installationID)
	if err != nil {
		return nil, err
	}

	var info *github.AppInfo
	client, err := c.clients.get(ctx, inst)
	if err == nil {
		info, err = client.Probe(ctx)
		if err == nil {
			var group *github.RunnerGroup
			group, err = c.ensureManagedRunnerGroup(ctx, inst, client)
			if err == nil {
				err = c.adoptManagedRunnerGroup(ctx, inst, group)
			}
			if err == nil {
				c.refreshRunnerGroupProblems(ctx, inst, client)
			}
		}
	}
	c.observeGitHub(inst.ID, err)

	if errors.Is(err, github.ErrRateLimited) {
		// A quota refusal says nothing about the credentials and refills on
		// its own, so it is neither recorded as the installation's health --
		// that raised "not usable, check your private key" -- nor published:
		// the row and the event stream must keep agreeing. The caller still
		// gets the reason, so a manual Verify can say why it has no answer.
		c.holdRateLimited(inst.ID, err, c.Now(), "checking credentials")
		return nil, err
	}

	msg := ""
	if err != nil {
		msg = err.Error()
	} else if info != nil {
		// A working credential with a missing permission is not an error yet,
		// but it will become one the first time a runner is created, so it is
		// recorded now rather than discovered later.
		if missing := info.MissingRequirements(inst.TargetType); len(missing) > 0 {
			msg = "the App is installed but " + strings.Join(missing, "; ")
		}
	}

	if serr := c.st.SetInstallationHealth(ctx, inst.ID, msg); serr != nil {
		c.log.Error("could not record installation health", "installation", inst.ID, "error", serr)
	}
	// The probe is the only place the App's slug is learned for an installation
	// that was added by hand, and every link to the App on GitHub is built from
	// it -- including the settings page where its avatar is uploaded, which is
	// the one setup step a manifest cannot do.
	if info != nil && info.Slug != "" && info.Slug != inst.AppSlug {
		if serr := c.st.SetInstallationAppSlug(ctx, inst.ID, info.Slug); serr != nil {
			c.log.Error("could not record the App's slug", "installation", inst.ID, "error", serr)
		} else {
			inst.AppSlug = info.Slug
		}
	}
	inst.LastError = msg
	now := c.Now()
	inst.LastCheckedAt = &now
	c.publishInstallation(ctx, inst)

	if err != nil {
		return nil, err
	}
	if msg != "" {
		return info, errors.New(msg)
	}
	return info, nil
}

// observeGitHub records one GitHub API outcome for the metrics endpoint.
func (c *Controller) observeGitHub(installationID string, err error) {
	result := "ok"
	switch {
	case err == nil:
	case errors.Is(err, github.ErrRateLimited):
		result = "rate_limited"
	case errors.Is(err, github.ErrForbidden):
		result = "forbidden"
	case errors.Is(err, github.ErrNotFound):
		result = "not_found"
	default:
		result = "error"
	}
	c.metrics.githubRequests.WithLabelValues(installationID, result).Inc()
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/version"
)

// The protocol was checked at join and nowhere else, so an agent that joined
// before a bump kept polling and receiving tasks it could not understand. The
// answer is exclusion rather than refusal: refusing the heartbeat would send
// every agent in the fleet into its re-join path at the same moment, which is
// the outage the upgrade was meant to avoid.
func TestAnAgentThatFallsOutOfProtocolIsExcludedRatherThanRefused(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	// The bump, from the fleet's point of view: the same agent, now speaking a
	// version this controller does not.
	resp, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion + 1})
	if err != nil {
		t.Fatalf("the heartbeat was refused, which would restart every agent at once: %v", err)
	}
	if !resp.Incompatible {
		t.Error("the response does not tell the agent it is incompatible")
	}
	if !resp.Cordoned {
		t.Error("the response does not stop the agent asking for work; an agent that ignores the new field would keep asking")
	}
	// Both numbers, because an operator has to know which side to upgrade.
	for _, want := range []string{"protocol version", "Upgrade this agent"} {
		if !strings.Contains(resp.IncompatibleReason, want) {
			t.Errorf("the reason does not mention %q: %q", want, resp.IncompatibleReason)
		}
	}

	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if !host.Incompatible || host.ProtocolVersion != agent.ProtocolVersion+1 {
		t.Fatalf("the host row does not record the mismatch: %+v", host)
	}
	// Excluded from placement exactly as a cordon excludes it.
	if scheduler.HostAvailable(host, h.c.Now()) {
		t.Error("an incompatible host is still available for placement")
	}

	// And it comes back on its own when the agent is upgraded, without a
	// re-join: the fleet heals host by host as binaries are replaced.
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	host, err = h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if host.Incompatible {
		t.Error("an upgraded agent is still marked incompatible")
	}
	if !scheduler.HostAvailable(host, h.c.Now()) {
		t.Error("an upgraded agent's host did not become available again")
	}
}

// An agent old enough not to send a version is the one case this cannot judge.
// Guessing would empty a fleet the moment its controller learnt to ask.
func TestAnAgentThatSendsNoProtocolIsNotJudged(t *testing.T) {
	h := newHarness(t)
	tr, id := joinedHost(t, h, 500_000, 200_000)

	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if host.Incompatible {
		t.Error("a host that reported no protocol was marked incompatible")
	}
	if !scheduler.HostAvailable(host, h.c.Now()) {
		t.Error("a host that reported no protocol was excluded from placement")
	}
}

// A pool that cannot place because every host runs an old agent has to say so.
// It is the blockage an operator is least likely to guess: nothing is broken,
// the hosts are up and heartbeating, and the fleet has simply stopped placing.
func TestAPoolBlockedByOldAgentsSaysWhichVersionToFix(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	host.Incompatible = true
	host.ProtocolVersion = agent.ProtocolVersion + 1
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if runners := h.runners(); len(runners) != 0 {
		t.Fatalf("a runner was placed on an incompatible host: %d", len(runners))
	}

	plan, _ := h.c.getLastPlan()
	if plan == nil {
		t.Fatal("no plan")
	}
	var blocked, fix string
	for _, pp := range plan.Pools {
		if pp.PoolID == pool.ID {
			blocked, fix = pp.Blocked, pp.BlockedFix
		}
	}
	if !strings.Contains(blocked, "cannot talk to") {
		t.Errorf("the reason does not name the incompatible agents: %q", blocked)
	}
	if !strings.Contains(fix, "upgrade the agent") {
		t.Errorf("the fix does not say to upgrade the agent: %q", fix)
	}
}

// An agent one release behind does not ignore a task kind it has never heard
// of -- it reports the task failed. The controller used to treat any kind it
// could not name as lifecycle work and mark a perfectly healthy runner failed
// for it, which is the opposite of what a skewed fleet needs.
func TestAFailureOnAnUnknownTaskKindLeavesTheRunnerAlone(t *testing.T) {
	for _, tc := range []struct {
		kind agent.TaskKind
		want bool
	}{
		{agent.TaskCreateRunner, true},
		{agent.TaskStopRunner, true},
		{agent.TaskRemoveRunner, true},
		{agent.TaskStreamLogs, false},
		{agent.TaskCancelLogs, false},
		{agent.TaskPrewarmImage, false},
		{agent.TaskKind("something_a_later_release_added"), false},
	} {
		if got := lifecycleTask(tc.kind); got != tc.want {
			t.Errorf("lifecycleTask(%q) = %v, want %v", tc.kind, got, tc.want)
		}
	}
}

// A fleet part-way through an upgrade is supposed to look like this for a
// while, so it is a warning: an error for every host between two releases
// would train an operator to ignore the list. What it protects against is the
// fleet that stays this way.
func TestHostsOnAnotherReleaseAreNamedWithTheDirection(t *testing.T) {
	// A test binary's version is "dev", which is deliberately unorderable, so
	// every comparison would answer "differs" and the direction -- the thing
	// worth testing -- would never be exercised.
	asRelease(t, "v1.2.0")
	h := newHarness(t)
	behind := h.host("vm-behind")
	behind.Version = "v0.0.1"
	if err := h.st.UpdateHost(h.ctx, behind); err != nil {
		t.Fatal(err)
	}
	ahead := h.host("vm-ahead")
	ahead.Version = "v99.0.0"
	if err := h.st.UpdateHost(h.ctx, ahead); err != nil {
		t.Fatal(err)
	}

	all, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var p Problem
	for _, item := range all {
		if item.Code == "host.version_behind" {
			p = item
		}
	}
	if p.Code == "" {
		t.Fatalf("version skew is not on the problems list: %v", h.problemCodes())
	}
	if p.Severity != config.SeverityWarning {
		t.Errorf("severity = %s; a fleet mid-upgrade is not an error", p.Severity)
	}
	// Both hosts, and which way round each one is: an operator sent to upgrade
	// the agent on a host that is ahead would be told to make it worse.
	for _, want := range []string{"vm-behind", "vm-ahead", "ahead of this controller"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("the detail does not mention %q: %q", want, p.Detail)
		}
	}
	if !strings.Contains(p.Fix, "upgrade this controller") {
		t.Errorf("the fix does not say to upgrade the controller for a host that is ahead: %q", p.Fix)
	}
}

// An incompatible host has a louder problem of its own. Two entries about one
// machine is how a list stops being read.
func TestAnIncompatibleHostIsNotAlsoReportedAsSkew(t *testing.T) {
	h := newHarness(t)
	host := h.host("vm-1")
	host.Version = "v0.0.1"
	host.Incompatible = true
	host.ProtocolVersion = agent.ProtocolVersion + 1
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	if contains(h.problemCodes(), "host.version_behind") {
		t.Error("an incompatible host is reported twice, once for the protocol and once for the release")
	}
}

// The badge and the agent's own warning come from one comparison, so they
// cannot disagree. They used to: the agent compared the version with its
// commit while the host row stores the bare version, so two builds of one tag
// warned in the log and matched on the page.
func TestTheHostViewReportsTheSameSkewTheAgentWouldWarnAbout(t *testing.T) {
	asRelease(t, "v1.2.0")
	h := newHarness(t)
	host := h.host("vm-1")

	host.Version = version.Version
	if got := h.c.HostView(host).VersionSkew; got != "" {
		t.Errorf("a host on this build reports skew %q", got)
	}
	host.Version = "v0.0.1"
	if got := h.c.HostView(host).VersionSkew; got != string(version.SkewBehind) {
		t.Errorf("skew = %q, want behind", got)
	}
}

// asRelease pretends this build is a tagged release for the duration of one
// test, so the ordering the comparison exists for can be exercised at all.
func asRelease(t *testing.T, v string) {
	t.Helper()
	was := version.Version
	version.Version = v
	t.Cleanup(func() { version.Version = was })
}

package controller

import (
	"context"
	"fmt"
	"maps"
	"slices"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A host's settings and a pool's requirements are two halves of one sentence,
// and they are edited on different pages by people who cannot see the other
// half. Raising a host's memory reserve is arithmetic on the Hosts page and a
// pool with nowhere to run on the Pools page; asking a pool for two more cores
// is one number on a form and a fleet that has none. Either way the fleet
// stays green, the scheduler keeps deciding correctly, and the only symptom is
// a job that queues for an hour.
//
// So both edits are checked against the other half before they are saved, and
// an edit that takes away the last host a pool could ever run on is refused
// until the operator says they meant it. The check is deliberately narrow: it
// asks only whether a pool that has somewhere to run would stop having one.
// A pool that is already stranded is not made worse by the next edit, and a
// pool that keeps one home is not the operator's problem today.

// Stranding is one pool an edit would leave with no host in the fleet that
// could ever run it, and the refusal that is the nearest miss -- a host that
// could run it before the edit and could not after, with that host's own
// account of why. The name is the operator's way in: a code is something to
// group by, and the machine that stopped fitting is the one to go and look at.
type Stranding struct {
	PoolID string `json:"pool_id"`
	Pool   string `json:"pool"`
	// Host is the machine whose refusal Reason quotes: the host being edited,
	// or, for a pool edit, one that used to have room for it.
	Host string `json:"host"`
	// Code is which of the placement rules it now fails, in the same
	// vocabulary HostFit's exclusions use: selector, backend, platform, size.
	Code   string `json:"code"`
	Reason string `json:"reason"`
}

// HostStrandings reports the pools that could run somewhere in this fleet
// today and would have nowhere to run if this host were saved as proposed.
//
// Proposed is the host as it would be after the edit, id and all; every other
// host is read as it stands. Health is not consulted on either side: a host
// waiting for its agent to check in is still where a pool lives, and refusing
// an edit because some other machine happened to be rebooting would be a rule
// nobody could predict.
func (c *Controller) HostStrandings(ctx context.Context, proposed *store.Host) ([]Stranding, error) {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return nil, err
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return nil, err
	}
	pools = c.sizingPools(pools)
	after := make([]*store.Host, 0, len(hosts))
	for _, h := range hosts {
		if h.ID == proposed.ID {
			after = append(after, proposed)
			continue
		}
		after = append(after, h)
	}
	var out []Stranding
	for _, p := range pools {
		// A disabled pool creates no runners, so nothing is waiting on it and
		// there is nothing to refuse an edit over. It is checked again on its
		// own account when it is enabled.
		if !p.Enabled {
			continue
		}
		if !anyHostCouldRun(hosts, p) || anyHostCouldRun(after, p) {
			continue
		}
		code, reason := HostRefusal(proposed, p)
		out = append(out, Stranding{PoolID: p.ID, Pool: p.Name, Host: hostLabel(proposed), Code: code, Reason: reason})
	}
	return out, nil
}

// PoolStranding is the same question asked from the other side: whether this
// pool, saved as proposed, would still have a host it could run on.
//
// It returns at most one entry, because there is only one pool in question.
// The host it names is one that has room for the pool as it stands, which is
// the machine the new figures should be read against -- an operator who has
// just typed 16 GB needs to see the 12 GB host it no longer fits, not a count.
func (c *Controller) PoolStranding(ctx context.Context, current, proposed *store.Pool) ([]Stranding, error) {
	if !proposed.Enabled {
		return nil, nil
	}
	fleet := c.cfg().Runners
	current, proposed = sizingPool(current, fleet), sizingPool(proposed, fleet)
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return nil, err
	}
	if anyHostCouldRun(hosts, proposed) {
		return nil, nil
	}
	// Only an edit that takes the last host away is refused. A pool that had
	// none to begin with is being edited by an operator who has already been
	// shown pool.no_matching_hosts, and stopping them changing anything else
	// about it would be a trap rather than a guard.
	var home *store.Host
	for _, h := range hosts {
		if scheduler.HostCouldRun(h, current) {
			home = h
			break
		}
	}
	if home == nil {
		return nil, nil
	}
	code, reason := HostRefusal(home, proposed)
	return []Stranding{{PoolID: proposed.ID, Pool: proposed.Name, Host: hostLabel(home), Code: code, Reason: reason}}, nil
}

// hostLabel is the host as an operator would name it in a sentence. A host
// that has not yet reported a name is still being talked about, and its id is
// what the Hosts page would show for it.
func hostLabel(h *store.Host) string {
	if h.Name != "" {
		return h.Name
	}
	return h.ID
}

func anyHostCouldRun(hosts []*store.Host, p *store.Pool) bool {
	for _, h := range hosts {
		if scheduler.HostCouldRun(h, p) {
			return true
		}
	}
	return false
}

// HostRefusal says which of the rules that are configuration -- rather than
// weather -- this host fails for this pool, and why, in the operator's terms.
// It is empty when the host could run the pool.
//
// The order is the scheduler's own, so the reason given is the first rule the
// host actually failed, and the sentences are written about "it" with the
// host's name left out, so a caller can put the name where its layout wants
// it. HostFit renders its exclusions from here, and so does every refusal an
// edit produces: the count before a pool exists and the refusal that stops one
// being stranded are the same fact, and they are said in the same words.
func HostRefusal(h *store.Host, p *store.Pool) (code, reason string) {
	switch {
	case !scheduler.HostSelects(h, p):
		return ExcludedSelector, selectorReason(h, p)
	case !scheduler.HostOffers(h, p):
		return ExcludedBackend, backendReason(h, p)
	case !scheduler.HostIsPlatform(h, p):
		return ExcludedPlatform, platformReason(h, p)
	}
	if short := scheduler.HostShortfall(h, p); short != "" {
		return ExcludedSize, short
	}
	return "", ""
}

// selectorReason names the one key that did not answer, and what it answered
// instead. The pair is the whole fix: a host missing the label is labelled, a
// host carrying the wrong value is corrected, and "it does not match the host
// selector" sends an operator to compare two lists by eye.
func selectorReason(h *store.Host, p *store.Pool) string {
	for _, k := range slices.Sorted(maps.Keys(p.HostSelector)) {
		want := p.HostSelector[k]
		got := h.SelectorValue(k)
		if got == want {
			continue
		}
		if got == "" {
			return fmt.Sprintf("it has no %s label, and this pool's host selector asks for %s=%s", k, k, want)
		}
		return fmt.Sprintf("its %s is %s, and this pool's host selector asks for %s", k, got, want)
	}
	return "it does not match this pool's host selector"
}

// backendReason adds the agent's own probe when it has one. The backend's name
// alone sends an operator looking in the wrong place: the usual cause is a
// socket that is not readable or a daemon that is not running, and the probe
// says which.
func backendReason(h *store.Host, p *store.Pool) string {
	reason := "its agent does not offer the " + string(p.Backend) + " backend"
	if info, ok := h.BackendInfo.Find(p.Backend); ok && !info.Available && info.Detail != "" {
		reason += " -- it reports: " + info.Detail
	}
	return reason
}

