// A loop that panicked used to stay dead while /readyz went on answering 200:
// one bad snapshot in the scheduler and every job queued for good, with
// nothing on the problems drawer to say why. The loop is restarted and the
// crash is reported.
func TestAPanickingLoopIsRestartedAndReported(t *testing.T) {
	h := newHarness(t)
	h.c.loopRestartDelay = time.Millisecond
	var runs atomic.Int32
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	h.c.spawn("flaky", ctx, func(ctx context.Context) {
		if runs.Add(1) < 3 {
			panic("a nil pointer where a pool should be")
		}
		<-ctx.Done()
	})

	eventually(t, 5*time.Second, "the loop to be restarted twice", func() bool {
		return runs.Load() >= 3
	})
	panics := h.c.LoopPanics()
	if panics["flaky"].Count != 2 || !strings.Contains(panics["flaky"].Last, "nil pointer") {
		t.Fatalf("recorded panics = %+v, want two with the last message", panics["flaky"])
	}
	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var found *Problem
	for i := range problems {
		if problems[i].Code == "controller.loop_panicked" {
			found = &problems[i]
		}
	}
	if found == nil {
		t.Fatalf("problems = %v, want the crashed loop reported", codesOf(problems))
	}
	if found.Severity != config.SeverityError || !strings.Contains(found.Title, "flaky") || !strings.Contains(found.Title, "2 times") {
		t.Fatalf("problem = %+v, want an error naming the loop and the count", found)
	}

	cancel()
	done := make(chan struct{})
	go func() { h.c.wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("the restarted loop did not stop with its context")
	}
}

func codesOf(problems []Problem) []string {
	out := make([]string, 0, len(problems))
	for _, p := range problems {
		out = append(out, p.Code)
	}
	return out
}

// Verifying the demo installation must not report a broken key.
//
// The demo fixtures carry a placeholder credential, so every real client path
// fails on them -- and the shortcut that answers from the demo client lived at
// one call site. `ClientFor` had it and `ProbeInstallation` did not, so an
// operator pressing Verify on the seeded installation, which is the one a new
// fleet has, was told "the stored private key is not a PEM-encoded RSA key".
func TestVerifyingTheDemoInstallationAnswersFromTheFixture(t *testing.T) {
	h := newHarness(t)
	inst := &store.Installation{
		ID: demoInstallationID, AppID: 123456, InstallationID: 654321,
		Target: "acme", TargetType: store.TargetOrg, AppSlug: "zoomies-demo",
		PrivateKeyEnc: []byte("not a key"), WebhookSecretEnc: []byte("not a secret"),
	}
	if err := h.st.CreateInstallation(h.ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	info, err := h.c.ProbeInstallation(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("probing the demo installation: %v", err)
	}
	if info == nil || info.Slug != "zoomies-demo" {
		t.Fatalf("probe returned %+v, want the demo fixture's App", info)
	}
	if missing := info.MissingRequirements(store.TargetOrg); len(missing) > 0 {
		t.Errorf("the demo fixture reports missing permissions %v; the page it is seeded for would show a fault that is not there", missing)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// demoClient stands in for GitHub on the seeded demo installation.
//
// The fixtures exist so that a demo instance, a screenshot and the UI test
// suite have a fleet to show. There is no GitHub App behind them, so every
// call that would leave the process has to be answered here instead. Without
// this the Installations page 500s on the rate limit, the poller logs a
// credential failure every thirty seconds, and the whole demo reads as broken
// software rather than as a working fleet.
//
// Reads answer plausibly. Writes refuse, and say why: a demo fixture cannot
// mint a real runner credential, and pretending otherwise would leave runners
// stuck in provisioning with no explanation.
type demoClient struct {
	target string
}

// ErrDemoFixture is returned by the demo installation for anything that would
// have to reach GitHub to be true.
var ErrDemoFixture = errors.New("this is a seeded demo installation with no GitHub App behind it")

func newDemoClient(inst *store.Installation) github.Client {
	return &demoClient{target: inst.Target}
}

func (d *demoClient) Target() (string, store.TargetType) { return d.target, store.TargetOrg }

func (d *demoClient) Probe(context.Context) (*github.AppInfo, error) {
	return &github.AppInfo{
		ID:    123456,
		Slug:  "zoomies-demo",
		Name:  "Zoomies (demo)",
		Owner: d.target,
		Permissions: map[string]string{
			"organization_self_hosted_runners": "write",
			"actions":                          "read",
			"metadata":                         "read",
			// Read-only source access, so AI Context's wizard can be shown
			// preparing a draft. Setup writes still refuse, as every write does.
			"contents": "read",
		},
		Events: []string{"workflow_job"},
		// The demo fixture is a fleet with nothing wrong, and an installation
		// on "selected" would read as one of the two setup mistakes the verify
		// dialog exists to name.
		RepositorySelection: "all",
	}, nil
}

func (d *demoClient) CreateJITConfig(context.Context, github.JITRequest) (*github.JITConfig, error) {
	return nil, fmt.Errorf("%w, so it cannot register a runner; create a real installation to run jobs", ErrDemoFixture)
}

func (d *demoClient) CreateRegistrationToken(context.Context) (*github.RegistrationToken, error) {
	return nil, fmt.Errorf("%w, so it cannot mint a registration token", ErrDemoFixture)
}

func (d *demoClient) CreateRemoveToken(context.Context) (*github.RegistrationToken, error) {
	return nil, fmt.Errorf("%w, so it cannot mint a removal token", ErrDemoFixture)
}

// ListRunners returns nothing, so the registration reaper has nothing to reap.
func (d *demoClient) ListRunners(context.Context) ([]github.Runner, error) { return nil, nil }

// DeleteRunner succeeds: the desired end state -- no such registration -- is
// already true.
func (d *demoClient) DeleteRunner(context.Context, int64) error { return nil }

func (d *demoClient) ListRunnerGroups(context.Context) ([]github.RunnerGroup, error) {
	return []github.RunnerGroup{{ID: 1, Name: "Default"}}, nil
}

func (d *demoClient) CreateRunnerGroup(context.Context, github.RunnerGroupCreate) (*github.RunnerGroup, error) {
	return nil, errors.New("the demo installation cannot create runner groups")
}

// ListQueuedJobs returns nothing. The demo's queued jobs are already in the
// database; inventing more on every poll would make the fixture drift.
func (d *demoClient) ListQueuedJobs(context.Context) ([]github.QueuedJob, error) { return nil, nil }

func (d *demoClient) RateLimit(context.Context) (*github.RateLimit, error) {
	return &github.RateLimit{
		Limit:     5000,
		Remaining: 4873,
		ResetAt:   time.Now().Add(41 * time.Minute).UTC(),
	}, nil
}

func (d *demoClient) WebURL() string { return "https://github.com/" + d.target }

// The migration surface. Reads answer with the fixture's repositories so the
// wizard has something to render in a demo; the write refuses, because a
// fixture has no App behind it and a pull request that silently went nowhere
// would be worse than a refusal that says why.

func (d *demoClient) ListRepositories(context.Context, int) ([]github.Repository, error) {
	names := append(append([]string{}, demoRepos...), demoQuietRepos...)
	names = append(append(names, demoMigratedRepos...), demoArchivedRepos...)
	out := make([]github.Repository, 0, len(names))
	for i, name := range names {
		out = append(out, github.Repository{
			// Stable numeric IDs, as GitHub gives: AI Context keys a
			// repository by its ID so a rename cannot move its source grants.
			ID:            int64(900001 + i),
			FullName:      name,
			DefaultBranch: "main",
			Private:       true,
			Archived:      slices.Contains(demoArchivedRepos, name),
			HTMLURL:       "https://github.com/" + name,
		})
	}
	return out, nil
}

// ListWorkflows gives the fixture the answers a real organisation gives: a
// repository with one workflow, a repository with several -- so the wizard's
// per-file choice has something to choose between -- a repository with no
// workflows at all, which is what the "hide repositories with nothing to move"
// filter exists for, and one that has already been migrated, which has nothing
// to move for the opposite reason.
func (d *demoClient) ListWorkflows(_ context.Context, repo string) ([]github.WorkflowFile, error) {
	for _, quiet := range demoQuietRepos {
		if repo == quiet {
			return nil, fmt.Errorf("%s: %w", repo, github.ErrNoWorkflows)
		}
	}
	sha := "demo" + strings.ReplaceAll(repo, "/", "")
	if slices.Contains(demoMigratedRepos, repo) {
		return []github.WorkflowFile{{
			Path:    ".github/workflows/ci.yml",
			SHA:     sha,
			Content: demoMigratedWorkflow,
		}}, nil
	}
	out := []github.WorkflowFile{{
		Path:    ".github/workflows/ci.yml",
		SHA:     sha,
		Content: demoWorkflow,
	}}
	if repo == demoRepos[0] {
		out = append(out, github.WorkflowFile{
			Path:    ".github/workflows/release.yml",
			SHA:     sha + "release",
			Content: demoReleaseWorkflow,
		})
	}
	return out, nil
}

// ReadReadme answers as a repository with no README does. The demo cannot open
// a pull request, so nothing would be written into one anyway.
func (d *demoClient) ReadReadme(_ context.Context, repo string) (*github.Readme, error) {
	return nil, fmt.Errorf("%s: %w", repo, github.ErrNoReadme)
}

func (d *demoClient) OpenPullRequest(context.Context, github.PullRequestRequest) (*github.PullRequest, error) {
	return nil, fmt.Errorf("%w, so it cannot open a pull request; connect a real installation to migrate a repository", ErrDemoFixture)
}

// demoMigratedWorkflow is a repository somebody has already moved. It reads as
// "nothing to do" in exactly the same way as a repository nobody has touched,
// which is why the wizard has to tell the two apart by name.
const demoMigratedWorkflow = `name: CI

on: [push]

jobs:
  build:
    runs-on: zoomies-demo-linux-x64
    steps:
      - uses: actions/checkout@v4
      - run: make build
`

// demoReleaseWorkflow is the fixture's second workflow file in one repository:
// a release is exactly the workflow an operator might want to leave on GitHub's
// runners while the rest of the repository moves.
const demoReleaseWorkflow = `name: Release

on:
  push:
    tags: ["v*"]

jobs:
  publish:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: make release
`

// demoWorkflow is a workflow with one job the wizard can migrate and one it
// must refuse to touch, so a demo shows both halves of the review step.
const demoWorkflow = `name: CI

on: [push]

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: make build
  matrix:
    strategy:
      matrix:
        os: [ubuntu-latest, macos-14]
    runs-on: ${{ matrix.os }}
    steps:
      - run: make test
`

func (d *demoClient) GetWorkflowJob(context.Context, string, int64) (*github.WorkflowJobEvent, error) {
	return nil, ErrDemoFixture
}

func (d *demoClient) GetWorkflowRun(context.Context, string, int64) (*github.WorkflowRunState, error) {
	return nil, ErrDemoFixture
}

func (d *demoClient) RerunWorkflowJob(context.Context, string, int64) error {
	return nil
}

func (d *demoClient) RerunFailedWorkflowJobs(context.Context, string, int64) error {
	return ErrDemoFixture
}

func (d *demoClient) CancelWorkflowRun(context.Context, string, int64, bool) error {
	return ErrDemoFixture
}

package controller

import (
	"context"
	"errors"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

func demoFixtureClient() github.Client {
	return newDemoClient(&store.Installation{Target: "acme", TargetType: store.TargetOrg})
}

// Every call that would have to reach GitHub to be true refuses, and says so
// in a sentence an operator can act on. A demo that answered these would leave
// runners stuck in provisioning with nothing to explain why.
func TestEveryCallThatWouldNeedARealAppRefusesAndSaysWhy(t *testing.T) {
	ctx := context.Background()
	c := demoFixtureClient()

	cases := []struct {
		what string
		call func() error
	}{
		{"a just-in-time configuration", func() error {
			_, err := c.CreateJITConfig(ctx, github.JITRequest{Name: "demo-runner"})
			return err
		}},
		{"a registration token", func() error {
			_, err := c.CreateRegistrationToken(ctx)
			return err
		}},
		{"a removal token", func() error {
			_, err := c.CreateRemoveToken(ctx)
			return err
		}},
		{"a pull request", func() error {
			_, err := c.OpenPullRequest(ctx, github.PullRequestRequest{Repo: "acme/api"})
			return err
		}},
		{"one job's detail", func() error {
			_, err := c.GetWorkflowJob(ctx, "acme/api", 1)
			return err
		}},
		{"cancelling a run", func() error { return c.CancelWorkflowRun(ctx, "acme/api", 1, false) }},
	}
	for _, tc := range cases {
		t.Run(tc.what, func(t *testing.T) {
			err := tc.call()
			if err == nil {
				t.Fatalf("asking the demo fixture for %s succeeded", tc.what)
			}
			if !errors.Is(err, ErrDemoFixture) {
				t.Errorf("error = %v, want it to match ErrDemoFixture so a caller can tell a fixture from an outage", err)
			}
		})
	}
}

// The reads answer plausibly instead of erroring, because a demo whose
// Installations page 500s reads as broken software rather than as a fleet.
func TestTheReadsADemoPageMakesAllAnswer(t *testing.T) {
	ctx := context.Background()
	c := demoFixtureClient()

	app, err := c.Probe(ctx)
	if err != nil {
		t.Fatalf("Probe: %v", err)
	}
	if app.Owner != "acme" || app.Permissions["organization_self_hosted_runners"] != "write" {
		t.Errorf("app = %+v, want the fixture's own organisation with the permission a fleet needs", app)
	}
	// "selected" is one of the two setup mistakes the verify dialog names, and
	// the fixture is a fleet with nothing wrong.
	if app.RepositorySelection != "all" {
		t.Errorf("repository selection = %q, want a fixture that reads as correctly installed", app.RepositorySelection)
	}

	limit, err := c.RateLimit(ctx)
	if err != nil {
		t.Fatalf("RateLimit: %v", err)
	}
	if limit.Remaining <= 0 || limit.Remaining > limit.Limit || limit.ResetAt.IsZero() {
		t.Errorf("rate limit = %+v, want quota left and a reset in the future", limit)
	}

	groups, err := c.ListRunnerGroups(ctx)
	if err != nil {
		t.Fatalf("ListRunnerGroups: %v", err)
	}
	if len(groups) == 0 {
		t.Error("the fixture offers no runner group, so a pool cannot name one")
	}

	// The two lists are deliberately empty: the demo's runners and queued jobs
	// are rows in the database already, and inventing more on every poll would
	// have the fixture drift under the screenshots taken of it.
	if runners, err := c.ListRunners(ctx); err != nil || len(runners) != 0 {
		t.Errorf("ListRunners = %v, %v; want nothing for the reaper to reap", runners, err)
	}
	if jobs, err := c.ListQueuedJobs(ctx); err != nil || len(jobs) != 0 {
		t.Errorf("ListQueuedJobs = %v, %v; want the fixture's own rows left alone", jobs, err)
	}

	// Removing a registration that was never there is the end state the
	// caller wanted, so it is not an error.
	if err := c.DeleteRunner(ctx, 42); err != nil {
		t.Errorf("DeleteRunner: %v, want deleting a registration nobody made to succeed", err)
	}

	target, kind := c.Target()
	if target != "acme" || kind != store.TargetOrg {
		t.Errorf("Target() = %q, %q; want the installation's own organisation", target, kind)
	}
	if c.WebURL() != "https://github.com/acme" {
		t.Errorf("WebURL() = %q, want a link to the organisation", c.WebURL())
	}
}

// The migration wizard's demo needs one of each kind of repository, because
// each is a different thing for it to say: something to move, nothing to move,
// already moved, and one it must refuse to open a pull request against.
func TestTheFixtureOffersEveryKindOfRepositoryTheWizardHasToExplain(t *testing.T) {
	ctx := context.Background()
	c := demoFixtureClient()

	repos, err := c.ListRepositories(ctx, 0)
	if err != nil {
		t.Fatalf("ListRepositories: %v", err)
	}
	byName := map[string]github.Repository{}
	for _, r := range repos {
		byName[r.FullName] = r
	}
	for _, want := range slices.Concat(demoRepos, demoQuietRepos, demoMigratedRepos, demoArchivedRepos) {
		r, ok := byName[want]
		if !ok {
			t.Fatalf("%s is a fixture repository but is not listed", want)
		}
		if r.DefaultBranch == "" || r.HTMLURL == "" {
			t.Errorf("%s = %+v, want a branch to open against and a link to follow", want, r)
		}
	}
	for _, archived := range demoArchivedRepos {
		if !byName[archived].Archived {
			t.Errorf("%s is the fixture's archived repository and must say so, or the wizard offers to migrate it", archived)
		}
	}

	// A repository with no workflows is its own answer, not an empty list:
	// the wizard's "hide repositories with nothing to move" filter is what it
	// exists for.
	for _, quiet := range demoQuietRepos {
		if _, err := c.ListWorkflows(ctx, quiet); !errors.Is(err, github.ErrNoWorkflows) {
			t.Errorf("ListWorkflows(%q) = %v, want ErrNoWorkflows", quiet, err)
		}
	}

	// One repository carries a second workflow, so the wizard's per-file
	// choice has something to choose between.
	files, err := c.ListWorkflows(ctx, demoRepos[0])
	if err != nil {
		t.Fatalf("ListWorkflows(%q): %v", demoRepos[0], err)
	}
	if len(files) < 2 {
		t.Errorf("%s has %d workflow files, want more than one to choose between", demoRepos[0], len(files))
	}
	seen := map[string]bool{}
	for _, f := range files {
		if f.SHA == "" {
			t.Errorf("%s has no SHA, so a migration could not be written back safely", f.Path)
		}
		if seen[f.Path] {
			t.Errorf("%s is listed twice", f.Path)
		}
		seen[f.Path] = true
	}
}

// The fixture's two kinds of workflow have to read differently to the code
// that plans a migration: one has a job to move, the other is already done.
func TestTheFixtureHasAWorkflowToMigrateAndOneAlreadyMigrated(t *testing.T) {
	ctx := context.Background()
	c := demoFixtureClient()

	files, err := c.ListWorkflows(ctx, demoRepos[0])
	if err != nil {
		t.Fatalf("ListWorkflows: %v", err)
	}
	if !strings.Contains(files[0].Content, "ubuntu-latest") {
		t.Errorf("%s has nothing on GitHub's runners, so the wizard has nothing to offer", files[0].Path)
	}

	for _, done := range demoMigratedRepos {
		files, err := c.ListWorkflows(ctx, done)
		if err != nil {
			t.Fatalf("ListWorkflows(%q): %v", done, err)
		}
		for _, f := range files {
			if strings.Contains(f.Content, "runs-on: ubuntu-latest") {
				t.Errorf("%s still runs a job on GitHub's runners, so it does not read as migrated", done)
			}
		}
	}
}

// The migration planner is the reader these fixtures are written for, so the
// one that is meant to have work finds work, and one job it must leave alone.
func TestThePlannerSeesBothHalvesOfTheFixtureWorkflow(t *testing.T) {
	ctx := context.Background()
	c := demoFixtureClient()

	files, err := c.ListWorkflows(ctx, demoRepos[0])
	if err != nil {
		t.Fatalf("ListWorkflows: %v", err)
	}
	workflows := make([]migrate.Workflow, 0, len(files))
	for _, f := range files {
		workflows = append(workflows, migrate.Workflow{Path: f.Path, SHA: f.SHA, Content: f.Content})
	}

	plan := migrate.PlanRepo(demoRepos[0], "main", workflows,
		migrate.Mapping{Labels: map[string]string{"ubuntu-latest": "zoomies-demo-linux-x64"}})
	if !plan.Changed() {
		t.Fatal("the fixture's repository gives the wizard nothing to migrate")
	}

	var rewrites, skips int
	for _, w := range plan.Workflows {
		rewrites += len(w.Rewrites)
		skips += len(w.Skips)
	}
	if rewrites == 0 || skips == 0 {
		t.Errorf("plan has %d rewrites and %d skips; the fixture exists to show both a job that moves and one the wizard must refuse to touch",
			rewrites, skips)
	}

	// A repository somebody has already moved reads as "nothing to do", which
	// is the other thing the wizard has to be able to say.
	for _, done := range demoMigratedRepos {
		files, err := c.ListWorkflows(ctx, done)
		if err != nil {
			t.Fatalf("ListWorkflows(%q): %v", done, err)
		}
		migrated := make([]migrate.Workflow, 0, len(files))
		for _, f := range files {
			migrated = append(migrated, migrate.Workflow{Path: f.Path, SHA: f.SHA, Content: f.Content})
		}
		if migrate.PlanRepo(done, "main", migrated,
			migrate.Mapping{Labels: map[string]string{"ubuntu-latest": "zoomies-demo-linux-x64"}}).Changed() {
			t.Errorf("%s is the fixture's already-migrated repository and still has something to change", done)
		}
	}
}

package controller

import (
	"bytes"
	"context"
	"encoding/json"
	"time"

	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// statsEventWindow is the window a `stats` frame summarises. It is the
// window GET /stats defaults to and the one the Overview asks for, so a frame
// arriving over the stream carries the same numbers a fetch would -- a
// different window here would make the tiles jump on every event.
const statsEventWindow = time.Hour

// publishDerived sends what is computed rather than stored: the Overview's
// statistics, the problems list, and any host whose card has moved.
//
// Nothing writes a row when a job ages out of the wait percentiles or a host
// stops sending heartbeats, so nothing in the store can announce those. They
// are worked out here after every reconcile pass and every housekeeping tick,
// and published only when the JSON actually differs from what was last sent.
// Without this the Overview's four numbers and the problems bell were the
// only parts of the product that stayed as they were until the browser was
// reloaded.
//
// It costs a handful of SQLite queries per pass, so it is skipped when nobody
// is connected to the stream: a controller nobody is watching should not do
// the watchers' work.
func (c *Controller) publishDerived(ctx context.Context) {
	if c.bus == nil || c.bus.Subscribers() == 0 || ctx.Err() != nil {
		return
	}

	c.derivedMu.Lock()
	defer c.derivedMu.Unlock()

	if stats, err := c.Stats(ctx, statsEventWindow); err != nil {
		c.log.Warn("could not compute fleet statistics for the event stream", "error", err)
	} else if raw, changed := c.derivedChanged(&c.lastStats, stats); changed {
		c.bus.Publish(events.KindStats, "", json.RawMessage(raw))
	}

	if problems, err := c.SharedProblems(ctx); err != nil {
		c.log.Warn("could not gather the current problems for the event stream", "error", err)
	} else if raw, changed := c.derivedChanged(&c.lastProblems, NewProblemsView(problems)); changed {
		c.bus.Publish(events.KindProblems, "", json.RawMessage(raw))
	}

	c.publishHostChanges(ctx)
	c.publishMachineChanges(ctx)
}

// publishMachineChanges announces every machine whose rendered view has moved
// since it was last sent. Called with derivedMu held.
//
// It exists for the same reason publishHostChanges does, and for one more. A
// machine spends most of its life waiting -- for a clone, for a guest to boot,
// for an agent to join -- and what moves on the page while it waits is elapsed
// time and the counts around it, neither of which writes a row. Without this
// the one screen an operator watches while a machine is being built would be
// the one screen that did not move.
//
// Machines are in the tens, like hosts, so diffing the rendered view is cheap;
// this is deliberately not how the runners are done.
func (c *Controller) publishMachineChanges(ctx context.Context) {
	if !c.cfg().Provider.Enabled {
		return
	}
	view, err := c.MachineRenderer(ctx)
	if err != nil {
		c.log.Warn("could not read the providers for the event stream", "error", err)
		return
	}
	machines, _, err := c.st.ListMachines(ctx, store.MachineFilter{}, store.Page{Limit: 500})
	if err != nil {
		c.log.Warn("could not read the machines for the event stream", "error", err)
		return
	}
	if c.lastMachines == nil {
		c.lastMachines = make(map[string][]byte, len(machines))
	}
	live := make(map[string]struct{}, len(machines))
	for _, m := range machines {
		live[m.ID] = struct{}{}
		last := c.lastMachines[m.ID]
		raw, changed := c.derivedChanged(&last, view.View(m))
		if !changed {
			continue
		}
		c.lastMachines[m.ID] = last
		c.bus.Publish(events.KindMachineUpdated, "machine:"+m.ID, json.RawMessage(raw))
	}
	for id := range c.lastMachines {
		if _, ok := live[id]; !ok {
			delete(c.lastMachines, id)
		}
	}
}

// publishHostChanges announces every host whose rendered view has moved since
// it was last sent. Called with derivedMu held.
//
// The two numbers an operator actually reads off the Hosts page are the two
// nothing announces. `active_runners` is counted from the runners table when a
// host is read, so a runner starting moves the "4 of 6 slots in use" bar with
// no host row written and nothing to publish; and the heartbeat behind "last
// heartbeat 12s ago" is a bare UPDATE of one column that no publisher watches.
// Both sat still until the browser reconciled, which is why the page felt dead
// while the fleet moved underneath it -- the operator was looking at the one
// screen in the product that was not live.
//
// Diffing the rendered view is what stops that becoming a frame per host per
// pass: a host nobody has touched marshals to the same bytes and says nothing,
// and a host that is merely alive says something once per heartbeat rather
// than once per pass. The cost is bounded by how many hosts a fleet has, which
// is tens -- this is deliberately not how the runners are done, because there
// are thousands of those and the same idea would be too expensive.
func (c *Controller) publishHostChanges(ctx context.Context) {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		c.log.Warn("could not read the hosts for the event stream", "error", err)
		return
	}
	if c.lastHosts == nil {
		c.lastHosts = make(map[string][]byte, len(hosts))
	}
	live := make(map[string]struct{}, len(hosts))
	for _, h := range hosts {
		live[h.ID] = struct{}{}
		last := c.lastHosts[h.ID]
		raw, changed := c.derivedChanged(&last, c.HostView(h))
		if !changed {
			continue
		}
		c.lastHosts[h.ID] = last
		c.bus.Publish(events.KindHostUpdated, "host:"+h.ID, json.RawMessage(raw))
	}
	// A host that has gone announced itself on the way out. Forgetting it here
	// only keeps the map from growing for the life of the process.
	for id := range c.lastHosts {
		if _, ok := live[id]; !ok {
			delete(c.lastHosts, id)
		}
	}
}

// derivedChanged marshals v, records it as the last published form, and says
// whether it differs from the one before. Comparing the bytes rather than the
// values means a new field is compared the day it is added.
func (c *Controller) derivedChanged(last *[]byte, v any) ([]byte, bool) {
	raw, err := json.Marshal(v)
	if err != nil {
		c.log.Error("could not marshal a payload for the event stream", "error", err)
		return nil, false
	}
	if bytes.Equal(raw, *last) {
		return raw, false
	}
	*last = raw
	return raw, true
}

package controller

import (
	"context"
	"encoding/json"
	"slices"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// listen subscribes to the bus the way the SSE endpoint does, for the kinds a
// test cares about.
func (h *harness) listen(kinds ...events.Kind) *events.Subscription {
	h.t.Helper()
	ctx, cancel := context.WithCancel(h.ctx)
	h.t.Cleanup(cancel)
	return h.c.Events().Subscribe(ctx, events.SubscribeOptions{Kinds: kinds})
}

// nextOfKind returns the next event of a kind, skipping the others, or fails.
func nextOfKind(t *testing.T, sub *events.Subscription, kind events.Kind) map[string]any {
	t.Helper()
	deadline := time.After(2 * time.Second)
	for {
		select {
		case e, ok := <-sub.C:
			if !ok {
				t.Fatalf("the subscription closed before a %s event arrived", kind)
			}
			if e.Kind != kind {
				continue
			}
			var out map[string]any
			if err := json.Unmarshal(e.Data, &out); err != nil {
				t.Fatalf("%s payload is not a JSON object: %v (%s)", kind, err, e.Data)
			}
			return out
		case <-deadline:
			t.Fatalf("no %s event arrived", kind)
		}
	}
}

// nothingFor asserts the subscription stays quiet for a moment. The bus hands
// events to a subscriber synchronously, so a pass that published something
// has done so before it returns and a short wait is not a race.
func nothingFor(t *testing.T, sub *events.Subscription) {
	t.Helper()
	select {
	case e := <-sub.C:
		t.Fatalf("an event arrived when nothing had changed: %s %s", e.Kind, e.Data)
	case <-time.After(100 * time.Millisecond):
	}
}

// The Overview's numbers and the problems bell are computed, not stored, so no
// row change can announce them. A reconcile pass has to, and it has to keep
// quiet when nothing moved -- a frame every ten seconds saying the same thing
// is noise the browser would repaint for.
func TestAReconcilePassTellsTheOverviewWhatChanged(t *testing.T) {
	h := newHarness(t)
	inst, _, _ := h.fleet()
	sub := h.listen(events.KindStats, events.KindProblems)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	stats := nextOfKind(t, sub, events.KindStats)
	if got := stats["queued_jobs"]; got != float64(0) {
		t.Errorf("first stats frame queued_jobs = %v, want 0", got)
	}
	// A fleet that has never received a webhook has one thing to say, and the
	// frame carries the list in the shape GET /problems returns.
	problems := nextOfKind(t, sub, events.KindProblems)
	if problems["ok"] != false || len(itemsOf(problems)) != 1 {
		t.Errorf("first problems frame = %v, want the one warning a fleet without a webhook has", problems)
	}

	// Nothing changed, so nothing is said.
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("second Reconcile: %v", err)
	}
	nothingFor(t, sub)

	// A job arriving changes the queue depth; the next pass says so.
	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile with a job: %v", err)
	}
	stats = nextOfKind(t, sub, events.KindStats)
	if got := stats["queued_jobs"]; got != float64(1) {
		t.Errorf("stats frame after a job queued: queued_jobs = %v, want 1", got)
	}
	// That delivery was the first webhook, so the warning about not having one
	// is gone, and the bell has to be told that too.
	problems = nextOfKind(t, sub, events.KindProblems)
	if problems["ok"] != true {
		t.Errorf("problems frame after the first webhook = %v, want ok", problems)
	}

	// A dangerous setting is a problem the moment it exists, and the frame
	// carries the whole list in the shape GET /problems returns.
	h.st.CreatePool(h.ctx, &store.Pool{
		Name: "root", InstallationID: inst.ID, Labels: []string{"root"},
		Backend: store.BackendDocker, Image: "img", MaxRunners: 1,
		IdleTimeout: store.Duration(time.Minute), Ephemeral: true,
		DockerMode: store.DockerNone, RunAsRoot: true, Enabled: true,
	})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile with a dangerous pool: %v", err)
	}
	problems = nextOfKind(t, sub, events.KindProblems)
	if problems["ok"] != false {
		t.Fatalf("problems frame after a dangerous pool = %v, want ok=false", problems)
	}
	items := itemsOf(problems)
	found := false
	for _, raw := range items {
		if item, _ := raw.(map[string]any); item["code"] == "pool.dangerous" {
			found = true
		}
	}
	if !found {
		t.Errorf("problems frame does not name the dangerous pool: %v", items)
	}
}

func itemsOf(problems map[string]any) []any {
	items, _ := problems["items"].([]any)
	return items
}

// A controller nobody is watching should not do the watchers' work: with no
// stream open, a pass computes neither payload and publishes nothing.
func TestNothingIsComputedForNobody(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	before := h.c.Events().LastID()
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if got := h.c.Events().LastID(); got != before {
		t.Errorf("a pass with no subscribers published %d event(s)", got-before)
	}
	if h.c.lastStats != nil || h.c.lastProblems != nil || h.c.lastHosts != nil {
		t.Error("a pass with no subscribers still computed the derived payloads")
	}
}

// The two numbers an operator reads off the Hosts page are the two nothing
// writes a row for: the slots in use are counted from the runners table when a
// host is read, and the heartbeat is one column no publisher watches. Starting
// a runner therefore moved the bar on the card with nothing to announce it,
// and the page sat still while the fleet moved under it.
func TestAPassAnnouncesTheSlotsAHostHasFilled(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	sub := h.listen(events.KindHostUpdated)

	// The first pass introduces the host, because nothing has been sent yet.
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	first := nextOfKind(t, sub, events.KindHostUpdated)
	if first["active_runners"] != float64(0) {
		t.Fatalf("first host frame active_runners = %v, want 0", first["active_runners"])
	}

	// A queued job puts a runner on that host. The runner's own frame says the
	// runner exists; only the host's says the machine has one fewer slot.
	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile with a job: %v", err)
	}
	got := nextOfKind(t, sub, events.KindHostUpdated)
	if got["active_runners"] != float64(1) {
		t.Errorf("host frame after a runner started: active_runners = %v, want 1", got["active_runners"])
	}
	if got["free"] != float64(host.Capacity-1) {
		t.Errorf("host frame free = %v, want %d", got["free"], host.Capacity-1)
	}
}

// A frame every ten seconds saying what the last one said is noise the browser
// repaints for, and there is one of these per host.
func TestAPassSaysNothingAboutAHostThatHasNotMoved(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	sub := h.listen(events.KindHostUpdated)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	nextOfKind(t, sub, events.KindHostUpdated)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("second Reconcile: %v", err)
	}
	nothingFor(t, sub)
}

// An operator's change is announced the moment it is made. The pass that comes
// along a few seconds later must not say it again: every publisher records what
// it sent, and the diff is against that record rather than against the last
// pass.
func TestAChangeAlreadyAnnouncedIsNotAnnouncedAgain(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	sub := h.listen(events.KindHostUpdated)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	nextOfKind(t, sub, events.KindHostUpdated)

	// Exactly what the API handler does when somebody cordons a host: read it,
	// write the change, then announce the row it read.
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}
	cordoned, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	h.c.PublishHost(cordoned)
	if got := nextOfKind(t, sub, events.KindHostUpdated); got["cordoned"] != true {
		t.Fatalf("host frame after cordoning = %v, want cordoned", got)
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile after cordoning: %v", err)
	}
	nothingFor(t, sub)
}

// A host that has gone is not something the pass should keep a record of, or
// the map grows for the life of the process on a fleet that churns machines.
func TestADeletedHostIsForgotten(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	sub := h.listen(events.KindHostUpdated, events.KindHostDeleted)

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	nextOfKind(t, sub, events.KindHostUpdated)

	if err := h.c.DeleteHost(h.ctx, host.ID); err != nil {
		t.Fatalf("DeleteHost: %v", err)
	}
	nextOfKind(t, sub, events.KindHostDeleted)

	h.c.derivedMu.Lock()
	_, remembered := h.c.lastHosts[host.ID]
	h.c.derivedMu.Unlock()
	if remembered {
		t.Error("a deleted host is still remembered as something to diff against")
	}
}

// The runner grid shows pool and host names, and the fleet cache takes each
// runner event as the row to show. An event carrying only the ids would blank
// those two columns until the next full fetch.
func TestRunnerEventsNameThePoolAndTheHost(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	sub := h.listen(events.KindRunnerCreated)

	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	got := nextOfKind(t, sub, events.KindRunnerCreated)
	if got["pool_name"] != pool.Name || got["host_name"] != host.Name {
		t.Errorf("runner.created names pool %v and host %v, want %s and %s",
			got["pool_name"], got["host_name"], pool.Name, host.Name)
	}
	if _, ok := got["labels"].([]any); !ok {
		t.Errorf("runner.created labels = %v, want a list", got["labels"])
	}
}

// The one thing a host event exists to say is whether the agent is still
// there, and that is worked out from the heartbeat rather than stored. A frame
// without it repainted a silent host as healthy.
func TestHostEventsCarryTheHealthTheCardShows(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	sub := h.listen(events.KindHostUpdated)

	h.c.PublishHost(host)
	got := nextOfKind(t, sub, events.KindHostUpdated)
	if got["healthy"] != true {
		t.Errorf("host.updated healthy = %v, want true for a host that just heartbeat", got["healthy"])
	}
	if got["free"] != float64(host.Capacity) {
		t.Errorf("host.updated free = %v, want %d", got["free"], host.Capacity)
	}
	if _, ok := got["backend_info"].([]any); !ok {
		t.Errorf("host.updated backend_info = %v, want a list", got["backend_info"])
	}
}

// A runner row that goes with its pool, host or installation, or is pruned, used
// to go without a frame, so the Runners page kept showing runners that no
// longer existed until it was reloaded. Each is announced now, before the thing
// that took it.
func TestRunnerRowsThatVanishAreAnnounced(t *testing.T) {
	h := newHarness(t)
	inst, pool, host := h.fleet()
	var ids []string
	for _, name := range []string{"one", "two"} {
		r := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: name, State: store.RunnerIdle}
		if err := h.st.CreateRunner(h.ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		ids = append(ids, r.ID)
	}
	sub := h.listen(events.KindRunnerDeleted, events.KindPoolDeleted, events.KindInstallationDeleted)

	if err := h.c.DeletePool(h.ctx, pool.ID); err != nil {
		t.Fatalf("DeletePool: %v", err)
	}
	var got []string
	for range ids {
		got = append(got, nextOfKind(t, sub, events.KindRunnerDeleted)["id"].(string))
	}
	slices.Sort(got)
	slices.Sort(ids)
	if !slices.Equal(got, ids) {
		t.Fatalf("runner.deleted for %v, want %v", got, ids)
	}
	if gone := nextOfKind(t, sub, events.KindPoolDeleted); gone["id"] != pool.ID {
		t.Fatalf("pool.deleted = %v, want %s after its runners", gone, pool.ID)
	}

	// The installation route goes through its pools.
	other := h.pool(inst, "other")
	r := &store.Runner{PoolID: other.ID, HostID: host.ID, Name: "three", State: store.RunnerFailed}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	if err := h.c.DeleteInstallation(h.ctx, inst.ID); err != nil {
		t.Fatalf("DeleteInstallation: %v", err)
	}
	if e := nextOfKind(t, sub, events.KindRunnerDeleted); e["id"] != r.ID {
		t.Fatalf("runner.deleted = %v, want %s", e, r.ID)
	}
	if e := nextOfKind(t, sub, events.KindPoolDeleted); e["id"] != other.ID {
		t.Fatalf("pool.deleted = %v, want %s", e, other.ID)
	}
	if e := nextOfKind(t, sub, events.KindInstallationDeleted); e["id"] != inst.ID {
		t.Fatalf("installation.deleted = %v, want %s", e, inst.ID)
	}
}

// Deleting a pool takes its queued demand with it too, and the Jobs and Queue
// pages learn about that job.updated frame the same way they learn about
// everything else -- no refresh needed to see it drop off the pool it just
// lost.
func TestDeletingAPoolAnnouncesTheQueuedJobsItTakesWithIt(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 900, Repo: "acme/widgets", State: store.JobQueued,
		Matched: true, PoolID: pool.ID, QueuedAt: time.Now(),
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	sub := h.listen(events.KindJobUpdated, events.KindPoolDeleted)

	if err := h.c.DeletePool(h.ctx, pool.ID); err != nil {
		t.Fatalf("DeletePool: %v", err)
	}
	got := nextOfKind(t, sub, events.KindJobUpdated)
	if got["id"] != job.ID {
		t.Fatalf("job.updated = %v, want id %s", got, job.ID)
	}
	if pid, present := got["pool_id"]; present && pid != "" {
		t.Fatalf("job.updated for a job whose pool was deleted = %v, want no pool_id", got)
	}
	if got["matched"] != false {
		t.Fatalf("job.updated matched = %v, want false", got["matched"])
	}
	if got["provisioning"] != store.ProvisioningDeleted {
		t.Fatalf("job.updated provisioning = %v, want %q", got["provisioning"], store.ProvisioningDeleted)
	}
	if gone := nextOfKind(t, sub, events.KindPoolDeleted); gone["id"] != pool.ID {
		t.Fatalf("pool.deleted = %v, want %s after its queued jobs", gone, pool.ID)
	}
}

// The prune is the quiet one: hourly, and a row it deletes is one the page
// may well be showing under "include removed".
func TestPrunedRunnersAreAnnounced(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	old := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: "old", State: store.RunnerRemoved}
	if err := h.st.CreateRunner(h.ctx, old); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	finished := time.Now().Add(-48 * time.Hour)
	old.FinishedAt = &finished
	if err := h.st.UpdateRunner(h.ctx, old); err != nil {
		t.Fatalf("UpdateRunner: %v", err)
	}
	h.c.UpdateConfig(func(c *config.Config) { c.Retention.Runners = 24 * time.Hour })

	sub := h.listen(events.KindRunnerDeleted)
	h.c.prune(h.ctx)
	if e := nextOfKind(t, sub, events.KindRunnerDeleted); e["id"] != old.ID {
		t.Fatalf("runner.deleted = %v, want the pruned runner %s", e, old.ID)
	}
}

// A machine spends most of its life waiting -- for a clone, for a guest to
// boot, for an agent to join -- and what moves on the page while it waits is
// elapsed time and the counts around it, neither of which writes a row. The
// pass's diff is what repaints it; without that, the one screen an operator
// watches while a machine is being built would be the one screen that did not
// move.
func TestAMachineWhoseViewMovedIsRepublishedWithoutAnyoneAskingFor(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	h.machinePass(t)
	m := h.onlyMachine(t)

	sub := h.listen(events.KindMachineUpdated)
	// The first pass with somebody watching sends what it has -- the machine
	// moved while nobody was subscribed -- and the second says nothing, because
	// a frame per machine per pass would cost every open tab a repaint of a row
	// it already has.
	h.c.publishDerived(h.ctx)
	nextOfKind(t, sub, events.KindMachineUpdated)
	h.c.publishDerived(h.ctx)
	nothingFor(t, sub)

	// A column written by something that does not publish -- here the sweep's
	// own ownership stamp -- still reaches the page.
	if err := h.st.SetMachineOwnershipError(h.ctx, m.ID, "the resource says it belongs to another machine"); err != nil {
		t.Fatalf("SetMachineOwnershipError: %v", err)
	}
	h.c.publishDerived(h.ctx)
	frame := nextOfKind(t, sub, events.KindMachineUpdated)
	if frame["id"] != m.ID {
		t.Fatalf("the frame is about %v, want machine %s", frame["id"], m.ID)
	}
	if frame["provider_name"] != row.Name {
		t.Fatalf("the frame names provider %v, want %s: it has to be the shape the API returns",
			frame["provider_name"], row.Name)
	}
}

package controller

import (
	"math"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// elasticPool switches a pool's CPU burst mode and saves it.
func (h *harness) elasticPool(p *store.Pool, mode store.CPUBurstMode) {
	h.t.Helper()
	p.CPUBurst = store.CPUBurstPolicy{Mode: mode}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		h.t.Fatal(err)
	}
}

// sharedRunner seeds a runner launched with a host share of cpus.
func (h *harness) sharedRunner(p *store.Pool, host *store.Host, state store.RunnerState, cpus float64) *store.Runner {
	h.t.Helper()
	r := h.runnerRow(p, host, state)
	r.AllocatedCPUs = cpus
	r.AllocationSource = store.AllocationFromHost
	if err := h.st.UpdateRunner(h.ctx, r); err != nil {
		h.t.Fatal(err)
	}
	return r
}

// calm gives a host a fresh, quiet CPU reading.
func calm(host *store.Host, now time.Time) {
	cpu := 20.0
	host.Usage = store.HostUsage{CPUPercent: &cpu, SampledAt: now}
}

// busyReport is a fresh sample of a runner using cpus cores.
func busyReport(r *store.Runner, cpus float64, now time.Time) agent.RunnerReport {
	at := now
	return agent.RunnerReport{RunnerID: r.ID, Stats: backend.Stats{SampledAt: &at, CPUPercent: cpus * 100}}
}

func targetOf(directives []agent.ElasticCPUDirective, id string) float64 {
	for _, d := range directives {
		if d.RunnerID == id {
			return d.TargetCPUs
		}
	}
	return 0
}

// The runner page and the runners table repaint a runner only from a
// runner.updated frame. A boost is written with the heartbeat's sample and
// nothing else, so without a frame of its own "Squirrel spotted" appeared on a
// reload and never while anyone was watching.
func TestABoostIsAnnouncedToTheLiveUI(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.elasticPool(pool, store.CPUBurstAutomatic)
	runner := h.sharedRunner(pool, host, store.RunnerBusy, 3.87)
	sub := h.listen(events.KindRunnerUpdated)

	now := h.c.Now()
	boosted := busyReport(runner, 7, now)
	boosted.Stats.CPUAllocationFactor = 2
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{Runners: []agent.RunnerReport{boosted}}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	frame := nextOfKind(t, sub, events.KindRunnerUpdated)
	cpu, _ := frame["cpu_resource"].(map[string]any)
	if frame["id"] != runner.ID || cpu == nil || cpu["state"] != "maximum_zoomies" || cpu["factor"] != float64(2) {
		t.Fatalf("runner.updated = %v, want the runner's GET shape with a doubled cpu_resource", frame)
	}

	// The same factor again changes nothing a person can see.
	if _, err := h.c.Heartbeat(h.ctx, host.ID, agent.HeartbeatRequest{Runners: []agent.RunnerReport{boosted}}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
	nothingFor(t, sub)
}

// An observe runner is never boosted, so a share the applied plan handed it
// was CPU nobody used and nobody else was lent. Beside an automatic runner on
// the same host it halved the automatic runner's boost for nothing.
func TestAnObservingRunnerReservesNoCPUFromAnAutomaticOne(t *testing.T) {
	h := newHarness(t)
	inst, auto, host := h.fleet()
	h.elasticPool(auto, store.CPUBurstAutomatic)
	watch := h.pool(inst, "watching", "watching")
	h.elasticPool(watch, store.CPUBurstObserve)
	a := h.sharedRunner(auto, host, store.RunnerBusy, 3.87)
	o := h.sharedRunner(watch, host, store.RunnerBusy, 3.87)
	now := h.c.Now()
	calm(host, now)

	got := h.c.elasticCPUTargets(h.ctx, host, agent.HeartbeatRequest{
		Features: []string{agent.FeatureElasticCPU},
		Runners:  []agent.RunnerReport{busyReport(a, 3.87, now), busyReport(o, 3.87, now)},
	}, now)
	alloc := host.Allocatable().CPUs
	if len(got) != 1 || math.Abs(targetOf(got, a.ID)-(alloc-3.87)) > 0.011 {
		t.Fatalf("directives = %+v, want the automatic runner lent all %.2f CPUs the observing one's guarantee leaves", got, alloc-3.87)
	}
	// Observe mode still answers its question: what the boost would have been.
	labels := map[string]string{"pool": watch.Name, "mode": string(store.CPUBurstObserve), "outcome": "burst"}
	if n, _ := gatherValue(t, h.c, "zoomies_elastic_cpu_decisions_total", labels); n != 1 {
		t.Errorf("observe burst decisions = %v, want 1", n)
	}
}

// Warm runners are what owners noticed most: sixteen CPUs, four slots, one
// busy job and three idle runners lent nothing, because each idle guarantee
// was charged in full. Only one of them can be handed a job before the next
// plan, so only one is held back -- and the moment one turns busy, the next
// plan gives everyone their guarantee again.
func TestIdleWarmRunnersLeaveABusyOneRoomToBoost(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.elasticPool(pool, store.CPUBurstAutomatic)
	busy := h.sharedRunner(pool, host, store.RunnerBusy, 3.87)
	var idle []*store.Runner
	for range 3 {
		idle = append(idle, h.sharedRunner(pool, host, store.RunnerIdle, 3.87))
	}
	now := h.c.Now()
	calm(host, now)
	alloc := host.Allocatable().CPUs
	beat := func() []agent.ElasticCPUDirective {
		return h.c.elasticCPUTargets(h.ctx, host, agent.HeartbeatRequest{
			Features: []string{agent.FeatureElasticCPU},
			Runners:  []agent.RunnerReport{busyReport(busy, 3.87, now)},
		}, now)
	}

	if got := targetOf(beat(), busy.ID); math.Abs(got-(alloc-3.87)) > 0.011 {
		t.Fatalf("busy runner beside three idle ones was lent %.2f CPUs, want %.2f: one idle guarantee held back, not three", got, alloc-3.87)
	}

	idle[0].State = store.RunnerBusy
	if err := h.st.UpdateRunner(h.ctx, idle[0]); err != nil {
		t.Fatal(err)
	}
	target := targetOf(beat(), busy.ID)
	if target == 0 {
		target = 3.87
	}
	// Two busy guarantees, the boost, and the one idle guarantee still held.
	if total := target + 3.87 + 3.87; total > alloc+0.001 {
		t.Fatalf("after an idle runner took a job the plan promised %.2f CPUs of %.2f; its guarantee was not reclaimed", total, alloc)
	}
}

// A Docker Desktop or VM daemon is smaller than the machine the agent
// measured, and refuses a quota above its own cores outright. A boost past it
// was no boost at all, and a warning on every heartbeat.
func TestABoostNeverAsksTheDaemonForMoreCoresThanItHas(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.elasticPool(pool, store.CPUBurstAutomatic)
	host.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true, CPUs: 4}}
	runner := h.sharedRunner(pool, host, store.RunnerBusy, 2)
	now := h.c.Now()
	calm(host, now)

	got := h.c.elasticCPUTargets(h.ctx, host, agent.HeartbeatRequest{
		Features: []string{agent.FeatureElasticCPU},
		Runners:  []agent.RunnerReport{busyReport(runner, 2, now)},
	}, now)
	if target := targetOf(got, runner.ID); target != 4 {
		t.Fatalf("target = %v on a daemon with 4 CPUs, want 4", target)
	}
}

// A runner already on its way up for a queued job is charged its guarantee in
// the ledger, and is where that job will land. Holding back a second share for
// the same job shrank every boost by one share during every start.
func TestAStartingRunnerIsNotHeldBackTwiceForItsJob(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.elasticPool(pool, store.CPUBurstAutomatic)
	busy := h.sharedRunner(pool, host, store.RunnerBusy, 3.87)
	now := h.c.Now()
	calm(host, now)
	lent := func() float64 {
		t.Helper()
		return targetOf(h.c.elasticCPUTargets(h.ctx, host, agent.HeartbeatRequest{
			Features: []string{agent.FeatureElasticCPU},
			Runners:  []agent.RunnerReport{busyReport(busy, 3.87, now)},
		}, now), busy.ID)
	}

	h.sharedRunner(pool, host, store.RunnerProvisioning, 3.87)
	before := lent()
	h.queuedJob(t, pool, pool.Labels)
	if got := lent(); got != before {
		t.Fatalf("a job with a runner already starting for it cut the boost from %.2f to %.2f CPUs", before, got)
	}
	h.queuedJob(t, pool, pool.Labels)
	if got := lent(); got >= before {
		t.Fatalf("a second queued job, with no runner starting for it, left the boost at %.2f CPUs; its room must be held", got)
	}
}

// A docker-in-docker build runs in the daemon, which saturates its own half
// of the slot while the pair together reads about half busy. Judged on the
// sum alone, the build waited most of its run before it was lent anything.
func TestADinDPairDemandsCPUWhenItsBusierHalfIsSaturated(t *testing.T) {
	now := time.Now()
	r := &store.Runner{}
	pair := backend.Stats{SampledAt: &now, CPUPercent: 210, BusiestHalfPercent: 98}
	if !elasticCPUDemanding(r, pair, 4, now) {
		t.Fatal("a pair whose daemon is using 98% of its half was not demanding")
	}
	pair.BusiestHalfPercent = 55
	if elasticCPUDemanding(r, pair, 4, now) {
		t.Fatal("a pair using about half of each half was demanding")
	}
}

// A host at full CPU because its runners are using what they were lent must
// not trip the sustained-CPU hold, so the heartbeat records how much of it
// was lent, from the runners' own samples.
func TestTheHeartbeatRecordsHowMuchOfTheHostWasLentCPU(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.elasticPool(pool, store.CPUBurstAutomatic)
	runner := h.sharedRunner(pool, host, store.RunnerBusy, 4)
	now := h.c.Now()
	report := busyReport(runner, 8, now)
	report.Stats.CPUAllocationFactor = 2

	if got := h.c.lentCPUPercent(h.ctx, host, []agent.RunnerReport{report}, now); got != 25 {
		t.Fatalf("lent = %v%%, want 25%%: 4 of the host's 16 CPUs are lent and in use", got)
	}
	report.Stats.CPUAllocationFactor = 1
	if got := h.c.lentCPUPercent(h.ctx, host, []agent.RunnerReport{report}, now); got != 0 {
		t.Fatalf("lent = %v%% with no boost standing, want 0", got)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"math"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// elasticDemandPercent is the share of its guarantee a runner must be using
// to be lent CPU. Whether it keeps a loan once lent is scheduler.DecideLoan's
// question, judged against the loan rather than the guarantee.
const elasticDemandPercent = 80.0

// elasticSaturatedPercent is how much of its own quota the busier half of a
// docker-in-docker pair must be using to count as pressing against its limit.
const elasticSaturatedPercent = scheduler.LoanSaturatedShare * 100

// elasticCPUTargets makes one host-wide decision from one coherent heartbeat.
// Every busy or starting runner is charged its guarantee before any spare CPU
// is lent, the idle runners one guarantee between them, and one compatible
// queued start is protected so a fast job cannot starve the next job out of
// the machine.
//
// Charging idle runners only one guarantee lets a busy runner borrow what warm
// capacity is not using, at the cost of a bounded oversubscription: if a
// second idle runner is handed a job, it may compete with a boost until the
// next heartbeat, whose plan charges it in full. The agent replaces its whole
// set of boosts from every plan, so the lent CPU is back within one heartbeat
// interval and a quota update, and a runner is never below its own quota.
func (c *Controller) elasticCPUTargets(ctx context.Context, h *store.Host, req agent.HeartbeatRequest, now time.Time) []agent.ElasticCPUDirective {
	if !c.mayAct() {
		return nil
	}
	// Nothing measured is no decision at all: there is nothing to judge the
	// host by, so nothing is recorded as if there were.
	if h == nil || !h.Usage.Fresh(now) || h.Usage.CPUPercent == nil {
		return nil
	}
	alloc := h.Allocatable()
	if !alloc.CPUsKnown || alloc.CPUs <= 0 {
		return nil
	}

	runners, err := c.st.ListRunnersForHost(ctx, h.ID)
	if err != nil {
		c.log.Warn("could not plan elastic CPU for a host", "host", h.ID, "error", err)
		return nil
	}
	// A runner between jobs, or gone, starts its next loan from nothing: an
	// idle runner's next job is a different job.
	busy := make(map[string]bool, len(runners))
	for _, r := range runners {
		if r != nil && r.State == store.RunnerBusy {
			busy[r.ID] = true
		}
	}
	c.sweepLoans(h.ID, busy)
	// This runs on every heartbeat of every host, so it stops as soon as there
	// is nothing to decide: before the fleet-wide pool read when the host runs
	// nothing, and before any plan or record when nothing here is elastic.
	if !slices.ContainsFunc(runners, func(r *store.Runner) bool { return r != nil && r.State.Live() }) {
		return nil
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools while planning elastic CPU", "host", h.ID, "error", err)
		return nil
	}
	pools = c.sizingPools(pools)
	poolByID := make(map[string]*store.Pool, len(pools))
	for _, p := range pools {
		poolByID[p.ID] = p
	}
	reports := make(map[string]agent.RunnerReport, len(req.Runners))
	for _, rep := range req.Runners {
		reports[rep.RunnerID] = rep
	}

	supported := slices.Contains(req.Features, agent.FeatureElasticCPU)

	// Two ledgers of the same runners. applied is the plan the agent is sent:
	// only a runner that will actually be boosted -- an automatic pool on an
	// agent that can move a quota -- may take part in its water-fill. An
	// observe runner, or one on an agent too old to boost it, is held at its
	// guarantee there, because a share the plan hands it is a share nobody
	// uses and nobody else is lent. hypothetical lets every observing runner
	// compete, and answers only the question observe mode asks: what would a
	// boost have been?
	applied := make([]scheduler.ElasticCPUWorkload, 0, len(runners))
	hypothetical := make([]scheduler.ElasticCPUWorkload, 0, len(runners))
	poolByRunner := make(map[string]*store.Pool, len(runners))
	starting := make(map[string]int)
	lent := 0.0
	loanCodes := make(map[string]scheduler.LoanCode)
	for _, r := range runners {
		if r == nil || !r.State.Live() {
			continue
		}
		p := poolByID[r.PoolID]
		if p == nil {
			continue
		}
		if r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering {
			starting[p.ID]++
		}
		base := elasticBase(p, h, r)
		poolByRunner[r.ID] = p
		if rep, ok := reports[r.ID]; ok {
			lent += lentInUse(rep.Stats, base, now)
		}
		eligible := p.Automatic() && p.CPUBurst.Observes() && (p.Backend == store.BackendDocker || p.Backend == store.BackendPodman) && r.State == store.RunnerBusy && r.AllocatedCPUs > 0
		w := scheduler.ElasticCPUWorkload{ID: r.ID, BaseCPUs: base, MaxCPUs: base, Idle: r.State == store.RunnerIdle}
		a := w
		if eligible && base > 0 {
			w.MaxCPUs = elasticCeiling(p, h, alloc.CPUs)
			if rep, ok := reports[r.ID]; ok {
				w.Demanding = elasticCPUDemanding(r, rep.Stats, base, now)
				if p.CPUBurst.Enforces() && supported {
					// Only a runner that can really be lent CPU has a loan to
					// waste; an observing one keeps the plain demand test.
					d := c.decideLoan(r, p, base, rep.Stats, w.Demanding, now)
					w.Demanding = d.Lend
					loanCodes[r.ID] = d.Code
				}
			}
			if p.CPUBurst.Enforces() && supported {
				a = w
			}
		}
		hypothetical = append(hypothetical, w)
		applied = append(applied, a)
	}

	elastic, demanding := false, false
	for _, w := range hypothetical {
		if p := poolByRunner[w.ID]; p != nil && p.CPUBurst.Observes() && w.BaseCPUs > 0 && w.MaxCPUs > w.BaseCPUs {
			elastic = true
			demanding = demanding || w.Demanding
		}
	}
	if !elastic {
		return nil
	}

	if elasticHostBusy(h, lent) {
		// A host too busy to lend is still a decision, and it is recorded as
		// one. Observe mode exists so an operator can read how often a boost
		// would happen before switching one on; a busy heartbeat that left no
		// trace would count only the calm ones, and overstate the answer.
		for _, w := range hypothetical {
			p := poolByRunner[w.ID]
			if p == nil || !p.CPUBurst.Observes() || w.BaseCPUs <= 0 || w.MaxCPUs <= w.BaseCPUs {
				continue
			}
			c.metrics.elasticCPUDecisions.WithLabelValues(p.Name, string(p.CPUBurst.Mode), "host_busy").Inc()
			c.metrics.elasticCPUFactor.WithLabelValues(p.Name, string(p.CPUBurst.Mode)).Observe(1)
		}
		return nil
	}

	// The start reserve only shapes a plan that lends something. With no
	// runner demanding, every one stays at its guarantee whatever the reserve
	// is, so the fleet-wide read of queued jobs it needs is skipped.
	reserve := 0.0
	if demanding {
		reserve = c.elasticStartReserve(ctx, h, poolByID, starting)
	}
	targets := scheduler.ElasticCPUPlan(alloc.CPUs, reserve, applied)
	would := targets
	if !slices.Equal(applied, hypothetical) {
		would = scheduler.ElasticCPUPlan(alloc.CPUs, reserve, hypothetical)
	}
	directives := make([]agent.ElasticCPUDirective, 0, len(hypothetical))
	for _, w := range hypothetical {
		p := poolByRunner[w.ID]
		if p == nil || !p.CPUBurst.Observes() || w.BaseCPUs <= 0 || w.MaxCPUs <= w.BaseCPUs {
			continue
		}
		enforced := p.CPUBurst.Enforces() && supported
		target := would[w.ID]
		if enforced {
			target = targets[w.ID]
		}
		outcome := "base"
		if target > w.BaseCPUs+0.01 {
			outcome = "burst"
		}
		switch loanCodes[w.ID] {
		case scheduler.LoanReclaimed:
			outcome = "reclaimed"
		case scheduler.LoanBackingOff:
			outcome = "backing_off"
		}
		if p.CPUBurst.Enforces() && !supported {
			outcome = "unsupported_agent"
		}
		c.metrics.elasticCPUDecisions.WithLabelValues(p.Name, string(p.CPUBurst.Mode), outcome).Inc()
		c.metrics.elasticCPUFactor.WithLabelValues(p.Name, string(p.CPUBurst.Mode)).Observe(target / w.BaseCPUs)
		if !enforced || target <= w.BaseCPUs+0.01 {
			continue
		}
		directives = append(directives, agent.ElasticCPUDirective{
			RunnerID: w.ID, CPUFactor: target / w.BaseCPUs, BaseCPUs: w.BaseCPUs,
			TargetCPUs: target, Reason: "squirrel_spotted",
		})
	}
	return directives
}

// elasticBase is the guarantee a runner is lent CPU on top of.
func elasticBase(p *store.Pool, h *store.Host, r *store.Runner) float64 {
	if p.Automatic() && r.AllocatedCPUs > 0 {
		// An automatic runner keeps the host share it was actually launched
		// with. Recomputing it after a host-capacity edit would corrupt both
		// the committed ledger and any factor sent to the agent.
		return r.AllocatedCPUs
	}
	return scheduler.Reserve(p, h).CPUs
}

// elasticCeiling is the most one runner of p may be lent up to on h: the
// pool's own ceiling, the host's allocatable CPU, and the daemon's core count,
// whichever is least. The last is the one easily forgotten: a Docker Desktop
// or VM daemon is smaller than the machine the agent measured, and refuses a
// quota above its own cores outright ("range of CPUs is from 0.01 to N"), so a
// boost past it would be no boost at all and a warning on every heartbeat.
func elasticCeiling(p *store.Pool, h *store.Host, allocatable float64) float64 {
	ceiling := p.CPUBurst.MaxCPUs
	if ceiling <= 0 || ceiling > allocatable {
		ceiling = allocatable
	}
	if info, ok := h.BackendInfo.Find(p.Backend); ok && info.CPUs > 0 {
		ceiling = min(ceiling, float64(info.CPUs))
	}
	return ceiling
}

// lentCPUPercent is the share of the host, in percent, that its runners were
// using out of CPU lent to them in this heartbeat. The host's admission hold
// and throttle are judged without it (see store.ObserveHostUsage).
//
// It reads the fleet only when some runner reports a boost, which is the only
// time the answer can be anything but zero.
func (c *Controller) lentCPUPercent(ctx context.Context, h *store.Host, reports []agent.RunnerReport, now time.Time) float64 {
	if h == nil || h.CPUs <= 0 || !slices.ContainsFunc(reports, func(rep agent.RunnerReport) bool { return rep.Stats.CPUAllocationFactor > 1 }) {
		return 0
	}
	runners, err := c.st.ListRunnersForHost(ctx, h.ID)
	if err != nil {
		return 0
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return 0
	}
	pools = c.sizingPools(pools)
	poolByID := make(map[string]*store.Pool, len(pools))
	for _, p := range pools {
		poolByID[p.ID] = p
	}
	byID := make(map[string]*store.Runner, len(runners))
	for _, r := range runners {
		if r != nil {
			byID[r.ID] = r
		}
	}
	lent := 0.0
	for _, rep := range reports {
		r := byID[rep.RunnerID]
		if r == nil || !r.State.Live() {
			continue
		}
		if p := poolByID[r.PoolID]; p != nil {
			lent += lentInUse(rep.Stats, elasticBase(p, h, r), now)
		}
	}
	return lent / float64(h.CPUs) * 100
}

// elasticHostBusy reports whether the host is too busy to lend CPU: throttled,
// high on CPU or load, or at its memory reserve.
//
// lent is the CPU this plan has already lent and the runners are using, and
// the CPU test is made without it. A boost is lent from the host's spare CPU,
// so a boost being used is a host whose CPU goes up -- and judged on the raw
// figure, a boost that did its job pushed the host over the line, the next
// heartbeat withdrew it, the host fell quiet, and the one after lent it again.
// Every other heartbeat, for as long as the job ran: a CPU-bound runner lent
// twice its guarantee averaged half as much again, and paid a quota change
// each time. What the line is for is CPU the plan did not account for --
// outside work, a runner with no limit, the daemon -- and that is what is
// left once the lent CPU in use is taken out.
//
// The same is why the sustained-CPU hold is not consulted here: it is decided
// on the raw figure, and a host held only because of what it was lent is the
// same flap a heartbeat later.
func elasticHostBusy(h *store.Host, lent float64) bool {
	cpu := *h.Usage.CPUPercent
	if h.CPUs > 0 {
		cpu = max(cpu-lent/float64(h.CPUs)*100, 0)
	}
	return h.Throttle.Active() || cpu >= 85 ||
		h.Usage.LoadAverage1 != nil && h.CPUs > 0 && *h.Usage.LoadAverage1 >= 2*float64(h.CPUs) ||
		h.Usage.MemoryAvailableMB != nil && *h.Usage.MemoryAvailableMB <= h.MemoryReserve()
}

// lentInUse is how much CPU a runner is using beyond its guarantee because it
// was lent it: its use above base, and never more than the boost it was given.
// A runner at or below its creation quota contributes nothing, so a runner
// with no limit that is using more than its share is left counted as the load
// it is, not written off as ours.
func lentInUse(st backend.Stats, base float64, now time.Time) float64 {
	if base <= 0 || st.CPUAllocationFactor <= 1 || st.SampledAt == nil || st.SampledAt.After(now) || now.Sub(*st.SampledAt) > store.HostUsageMaxAge {
		return 0
	}
	used := st.CPUPercent / 100
	return min(max(used-base, 0), (st.CPUAllocationFactor-1)*base)
}

func elasticCPUDemanding(r *store.Runner, current backend.Stats, base float64, now time.Time) bool {
	if current.SampledAt == nil || current.SampledAt.After(now) || now.Sub(*current.SampledAt) > store.HostUsageMaxAge {
		return false
	}
	if current.CPUPercent >= base*elasticDemandPercent {
		return true
	}
	// A docker-in-docker pair is judged by its busier half as well. The build
	// runs in the daemon, which saturates its own half of the slot while the
	// pair together reads barely half busy -- judged on the sum alone, a
	// build waited most of its run before it was lent anything.
	if current.BusiestHalfPercent >= elasticDemandPercent {
		return true
	}
	return throttlingRose(r, current)
}

// throttlingRose reports whether the cgroup's throttling counters moved since
// the runner's previous sample: the kernel saying, in its own terms, that the
// runner wanted more CPU than its quota allowed.
func throttlingRose(r *store.Runner, current backend.Stats) bool {
	var previous backend.Stats
	if len(r.ResourceSample) == 0 || json.Unmarshal(r.ResourceSample, &previous) != nil {
		return false
	}
	if previous.CPUThrottling == nil || current.CPUThrottling == nil {
		return false
	}
	return current.CPUThrottling.ThrottledPeriods > previous.CPUThrottling.ThrottledPeriods ||
		current.CPUThrottling.ThrottledNanoseconds > previous.CPUThrottling.ThrottledNanoseconds
}

// decideLoan asks the scheduler whether a busy runner of an automatic pool
// keeps, loses or may be given a loan, and remembers the answer for the next
// heartbeat. The memory lives in this process only: a restarted controller
// forgets a backoff, which costs at most one wasted loan per runner, and
// keeps the store free of a row written on every heartbeat.
func (c *Controller) decideLoan(r *store.Runner, p *store.Pool, base float64, st backend.Stats, demanding bool, now time.Time) scheduler.LoanDecision {
	if st.SampledAt == nil || st.SampledAt.After(now) || now.Sub(*st.SampledAt) > store.HostUsageMaxAge {
		// Nothing current to judge by: no loan, and nothing learned.
		return scheduler.LoanDecision{Code: scheduler.LoanNotDemanding, Reason: "not lent: no current sample"}
	}
	factor := st.CPUAllocationFactor
	if factor <= 0 {
		factor = 1
	}
	in := scheduler.LoanInput{
		Now: now, SampledAt: *st.SampledAt,
		BaseCPUs: base, LimitCPUs: base * factor, UsedCPUs: st.CPUPercent / 100,
		Saturated: throttlingRose(r, st) || st.BusiestHalfPercent >= elasticSaturatedPercent,
		Demanding: demanding,
	}
	if p.DockerMode == store.DockerDinD && r.AllocationSource == store.AllocationFromHost && st.BusiestHalfPercent > 0 {
		// The pair's loan is given to its busier half alone, so that half is
		// what is judged. A host-sized pair splits its slot evenly (see
		// store.Resources.SplitWithDaemon), and BusiestHalfPercent is that
		// half's use of its own share. An agent too old to report it leaves
		// the pair judged on its sum, as it always was.
		half, _ := store.Resources{CPUs: base}.SplitWithDaemon()
		in.HolderBaseCPUs = half.CPUs
		in.HolderUsedCPUs = st.BusiestHalfPercent / 100 * half.CPUs
	}
	c.loansMu.Lock()
	defer c.loansMu.Unlock()
	if c.loans == nil {
		c.loans = make(map[string]loanEntry)
	}
	in.Memory = c.loans[r.ID].memory
	d := scheduler.DecideLoan(in)
	c.loans[r.ID] = loanEntry{host: r.HostID, memory: d.Memory}
	if d.Code == scheduler.LoanReclaimed || d.Code == scheduler.LoanBackoffOverride {
		c.log.Info("elastic CPU loan changed", "pool", p.Name, "runner", r.ID, "decision", string(d.Code), "reason", d.Reason)
	}
	return d
}

// loanEntry is one runner's loan memory and the host it runs on, which is
// what lets a host's plan sweep entries for runners it no longer lists.
type loanEntry struct {
	host   string
	memory scheduler.LoanMemory
}

// sweepLoans drops the loan memory of every runner of host that is not busy
// in this plan. A runner that went straight from busy to gone -- every
// ephemeral runner, once its job ends -- is never seen idle, and may no
// longer be listed at all; keyed only by what the listing returned, its entry
// would outlive it for as long as the controller ran.
func (c *Controller) sweepLoans(host string, busy map[string]bool) {
	c.loansMu.Lock()
	defer c.loansMu.Unlock()
	for id, e := range c.loans {
		if e.host == host && !busy[id] {
			delete(c.loans, id)
		}
	}
}

// elasticStartReserve is the one share held back for a compatible queued job.
//
// starting counts this host's runners of each pool that are already on their
// way up. Each of those is charged its guarantee in the plan's ledger, and is
// the runner a queued job of its pool is about to land on; holding a second
// share back for the same job shrank every boost by one share during every
// start. Only a pool with more jobs queued than runners starting for it here
// still needs room kept.
func (c *Controller) elasticStartReserve(ctx context.Context, h *store.Host, pools map[string]*store.Pool, starting map[string]int) float64 {
	if intent := c.placement.Load(); intent != nil && intent.Version == c.placementVersion.Load() && c.Now().Sub(intent.At) >= 0 && c.Now().Sub(intent.At) < 30*time.Second {
		reserve := 0.0
		for id, n := range intent.Starts[h.ID] {
			if p := pools[id]; p != nil && n > starting[id] && scheduler.HostCouldRun(h, p) {
				reserve = math.Max(reserve, scheduler.Reserve(p, h).CPUs)
			}
		}
		return reserve
	}

	queued, err := c.st.ListQueuedJobs(ctx)
	if err != nil {
		return 0
	}
	waiting := make(map[string]int)
	for _, job := range queued {
		waiting[job.PoolID]++
	}
	reserve := 0.0
	for id, n := range waiting {
		p := pools[id]
		if p == nil || n <= starting[id] || !scheduler.HostCouldRun(h, p) {
			continue
		}
		reserve = math.Max(reserve, scheduler.Reserve(p, h).CPUs)
	}
	return reserve
}

