)

// A heartbeat for a host this controller has never seen must carry
// agent.ErrHostGone. The HTTP transport derives that sentinel from a 404, but
// the embedded agent has no status code to derive it from, so if the controller
// does not wrap it the in-process agent retries a host that will never exist
// again instead of stopping and telling the operator to re-join.
func TestHeartbeatForUnknownHostIsErrHostGone(t *testing.T) {
	h := newHarness(t)

	_, err := h.c.Heartbeat(context.Background(), "host_doesnotexist", agent.HeartbeatRequest{
		ProtocolVersion: agent.ProtocolVersion,
		Capacity:        1,
	})
	if err == nil {
		t.Fatal("heartbeat for an unknown host succeeded; it must fail")
	}
	if !errors.Is(err, agent.ErrHostGone) {
		t.Fatalf("error = %v, want it to wrap agent.ErrHostGone so the embedded agent stops rather than retrying", err)
	}
}

package controller

import (
	"context"
	"errors"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
	"sync"
	"time"
)

// Bounded workers keep optional remote lookups out of webhook and heartbeat
// acknowledgements. Durable leases also cover controller restarts and 429s.
func (c *Controller) enrichmentLoop(ctx context.Context) {
	tick := time.NewTicker(time.Second)
	defer tick.Stop()
	for {
		c.enrichOnce(ctx)
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
		}
	}
}
func (c *Controller) enrichOnce(ctx context.Context) {
	if !c.mayAct() {
		return
	}
	items, err := c.st.ClaimEnrichment(ctx, 4)
	if err != nil {
		c.log.Warn("could not claim GitHub enrichment", "error", err)
		return
	}
	var wg sync.WaitGroup
	for _, item := range items {
		wg.Add(1)
		go func(v store.Enrichment) {
			defer wg.Done()
			cctx, cancel := context.WithTimeout(ctx, 5*time.Second)
			defer cancel()
			err := c.enrich(cctx, v)
			if err != nil {
				c.log.Debug("GitHub enrichment will retry", "kind", v.Kind, "target", v.Target, "error", err)
			}
			if e := c.st.FinishEnrichment(ctx, v, err == nil); e != nil {
				c.log.Warn("could not acknowledge enrichment", "error", e)
			}
		}(item)
	}
	wg.Wait()
}
func (c *Controller) enrich(ctx context.Context, v store.Enrichment) error {
	if !c.mayAct() {
		return errors.New("controller authority is paused")
	}
	switch v.Kind {
	case "registration":
		r, err := c.st.GetRunner(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if r.RegistrationDeletedAt != nil {
			return nil
		}
		c.deleteRegistration(ctx, r, nil)
		r, err = c.st.GetRunner(ctx, v.Target)
		if err != nil {
			return err
		}
		if r.RegistrationDeletedAt == nil {
			return errors.New("registration cleanup not yet confirmed")
		}
		return nil
	case "ready":
		r, err := c.st.GetRunner(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if r.State != store.RunnerRegistering {
			return nil
		}
		if !c.runnerOnline(ctx, r, make(map[string][]github.Runner)) {
			return errors.New("runner not yet confirmed online")
		}
		return c.applyRunnerState(ctx, r, store.RunnerIdle, "GitHub confirmed the runner online", "")
	case "job":
		j, err := c.st.GetJob(ctx, v.Target)
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		if err != nil {
			return err
		}
		if j.InstallationID == "" || j.GitHubRunID == 0 {
			return nil
		}
		cancelled := j.State == store.JobCompleted && j.Conclusion == "cancelled"
		if j.RunNumber != 0 && !cancelled {
			return nil
		}
		if c.githubHeld(j.InstallationID, c.Now()) {
			return errors.New("GitHub rate limit hold")
		}
		client, err := c.ClientFor(ctx, j.InstallationID)
		if err != nil {
			return err
		}
		run, err := client.GetWorkflowRun(ctx, j.Repo, j.GitHubRunID)
		c.observeGitHub(j.InstallationID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(j.InstallationID, err, c.Now(), "enriching workflow")
			}
			return err
		}
		if run.RunNumber > 0 {
			if err := c.st.SetRunNumberForRun(ctx, j.Repo, j.GitHubRunID, run.RunNumber); err != nil {
				return err
			}
			j.RunNumber = run.RunNumber
			c.publishJob(ctx, j)
		}
		if cancelled && run.Cancelled() {
			if !c.mayAct() {
				return errors.New("controller authority is paused")
			}
			return c.cancelWorkflowRunLocally(ctx, j.Repo, j.GitHubRunID, true)
		}
	}
	return nil
}

package controller

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// JobExplanation is the answer to "why is this job not running?", computed
// once, on the side that knows.
//
// The browser used to work this out for itself from the pool's live counts, and
// the CLI could only say "unmatched": two answers to one question, neither of
// which could see the scheduler's own reason for refusing to place a runner.
// This is that reason plus the four facts around it -- the last plan, the
// pool's warnings, the runner's stamps and its host's heartbeat -- so the
// drawer, the CLI and the support bundle read from one place and cannot
// disagree.
type JobExplanation struct {
	JobID string         `json:"job_id"`
	State store.JobState `json:"state"`
	// Summary is the sentence. It is always set, including for a job that is
	// running or finished: "nothing is wrong" is an answer to the question, and
	// a caller that has to special-case an empty string will print nothing on
	// the one page an operator opened to be told something.
	Summary string `json:"summary"`
	// Detail is what the summary leaves out, in the scheduler's own words
	// where it has any.
	Detail string `json:"detail,omitempty"`
	// Fix is what to do. Empty means there is nothing to do, which is the
	// normal case and is different from not knowing.
	Fix string `json:"fix,omitempty"`
	// Waiting is whether the job is still waiting on something. Blocked is
	// whether waiting will not on its own end it: a fleet that is merely busy
	// clears, and a pool nothing can place never will.
	Waiting bool `json:"waiting"`
	Blocked bool `json:"blocked"`
	// PoolID, RunnerID and HostID are what the explanation is about, so a
	// caller can link to them rather than parse them back out of the prose.
	PoolID     string    `json:"pool_id,omitempty"`
	RunnerID   string    `json:"runner_id,omitempty"`
	HostID     string    `json:"host_id,omitempty"`
	ComputedAt time.Time `json:"computed_at"`
}

// ExplainJob works out why a job is where it is.
//
// It reads rather than decides: the scheduler has already said why it could not
// place a runner, and repeating that decision here would give an operator two
// answers that drift apart. What this adds is the surrounding facts, which the
// plan does not carry -- whose runner it is, and whether that runner's host is
// still alive.
func (c *Controller) ExplainJob(ctx context.Context, jobID string) (*JobExplanation, error) {
	job, err := c.st.GetJob(ctx, jobID)
	if err != nil {
		return nil, err
	}
	out := &JobExplanation{
		JobID:      job.ID,
		State:      job.State,
		PoolID:     job.PoolID,
		RunnerID:   job.RunnerID,
		ComputedAt: c.Now(),
	}

	switch job.State {
	case store.JobCompleted:
		c.explainCompleted(job, out)
		return out, nil
	case store.JobInProgress:
		// Ahead of the running explanation, which would otherwise name a
		// runner this fleet took away when the cancellation landed.
		if job.Cancelling() {
			explainCancelling(job, out)
			return out, nil
		}
		c.explainRunning(ctx, job, out)
		return out, nil
	case store.JobWaiting:
		// Not this fleet's wait at all, and saying so is the point: a job
		// sitting still reads as a slow fleet until somebody says otherwise.
		out.Waiting = true
		out.Summary = "GitHub is holding this job for a deployment review."
		out.Detail = "Nothing here can start it until somebody approves it. The wait for a runner begins when they do, so the queue wait below has not started."
		out.Fix = "approve the deployment on GitHub, or leave it -- nothing in this fleet is wrong."
		return out, nil
	}

	out.Waiting = true
	c.explainQueued(ctx, job, out)
	return out, nil
}

func (c *Controller) explainCompleted(job *store.Job, out *JobExplanation) {
	defer explainOOM(job, out)
	switch {
	case job.FleetFailed():
		out.Summary = "The runner this job was on stopped before the job finished."
		out.Detail = job.RunnerFault
		// The category's own remedy where there is one. It is the difference
		// between being told the fleet broke the job and being told what to go
		// and change, and the second is why anybody opened this page.
		out.Fix = job.FaultKind.Fix()
		if out.Fix == "" {
			out.Fix = "this is the fleet's failure rather than the workflow's: the runner's page has what it said as it went."
		}
	case store.IsFailedConclusion(job.Conclusion):
		out.Summary = "This job ran and " + job.Conclusion + "."
		out.Detail = "The fleet did its part: a conclusion is the workflow's own outcome."
	default:
		out.Summary = "This job ran and " + job.Conclusion + "."
	}
}

// explainOOM adds an out-of-memory kill to a finished job's explanation. A
// step killed with exit 137 can leave a runner that finishes the job, and
// GitHub then reports a failed step like any test failure; the kill is the
// part the workflow's author cannot see, so it is said whatever else was.
func explainOOM(job *store.Job, out *JobExplanation) {
	if !job.OOMKilled {
		return
	}
	peak := ""
	if job.PeakMemoryMB > 0 {
		peak = fmt.Sprintf(", having used up to %s", formatJobMB(job.PeakMemoryMB))
	}
	where := ""
	if job.HostID != "" {
		where = " on host " + job.HostID
	}
	sentence := fmt.Sprintf("The kernel killed this job's runner, or one of its steps, for its memory limit%s%s.", where, peak)
	// The kill is the summary: it is the one fact about this job the
	// conclusion GitHub recorded cannot tell anybody.
	out.Summary = sentence
	out.Fix = store.FaultOutOfMemory.Fix() + " With scheduler.history_sizing set to on, the next run of this job is placed on a host with room for what it needed."
}

// formatJobMB says a memory figure the way the rest of the explanation does.
func formatJobMB(mb int64) string {
	if mb >= 1024 {
		return fmt.Sprintf("%.1f GB", float64(mb)/1024)
	}
	return fmt.Sprintf("%d MB", mb)
}

func (c *Controller) explainRunning(ctx context.Context, job *store.Job, out *JobExplanation) {
	// A runner that died under a job is recorded the moment the fleet sees it,
	// which is often minutes before GitHub closes the job. Until it does, this
	// is the function that answers -- and it used to answer "this job is
	// running on zoomies-x", about a runner the fleet had already written off.
	if job.FleetFailed() {
		out.Blocked = true
		out.Summary = "The runner this job was on has stopped, and GitHub has not noticed yet."
		out.Detail = job.RunnerFault + ". GitHub will report the job failed once the runner's absence is noticed, and it will look like any other failure."
		out.Fix = job.FaultKind.Fix()
		if out.Fix == "" {
			out.Fix = "this is the fleet's failure rather than the workflow's: the runner's page has what it said as it went."
		}
		return
	}
	out.Summary = "This job is running."
	if job.RunnerName != "" {
		out.Summary = "This job is running on " + job.RunnerName + "."
	}
	// A runner whose host has gone quiet is the case worth catching here: the
	// job looks healthy and nothing is watching it.
	if job.RunnerID == "" {
		return
	}
	runner, err := c.st.GetRunner(ctx, job.RunnerID)
	if err != nil {
		return
	}
	out.HostID = runner.HostID
	host, err := c.st.GetHost(ctx, runner.HostID)
	if err != nil || host.Healthy(c.Now()) {
		return
	}
	out.Blocked = true
	out.Summary = "This job is on a runner whose host has gone quiet."
	out.Detail = fmt.Sprintf("%s last checked in %s ago, and a host silent for %s is presumed gone -- the job will be marked as lost by the fleet.",
		host.Name, formatAge(c.Now().Sub(host.LastHeartbeat)), store.HeartbeatTimeout)
	out.Fix = "check that the zoomies agent is running on that host and can reach this controller."
}

// explainCancelling covers the window between GitHub accepting a cancellation
// and GitHub reporting the job over, which can be minutes. The fleet has
// already stopped: there is nothing for an operator to do but wait, and the
// one thing they must not be told is that the job is still queued or running.
func explainCancelling(job *store.Job, out *JobExplanation) {
	out.Blocked = true
	out.Summary = "This job's workflow run was cancelled."
	out.Detail = "GitHub accepted the cancellation; this fleet stopped its queued demand and any runner working on it at that moment. " +
		"GitHub reports the conclusion in its own time, and until it does the job is recorded as neither waiting nor running."
	out.Fix = "nothing here: the conclusion arrives with GitHub's completion event. Re-run the workflow on GitHub if the work is still wanted."
}

// explainQueued is the case the endpoint exists for.
func (c *Controller) explainQueued(ctx context.Context, job *store.Job, out *JobExplanation) {
	// Before the provisioning branch: a cancelled run pauses its queued jobs,
	// so an operator who cancelled one would otherwise be told their own
	// cancellation was a pause, and offered a Resume that would undo it.
	if job.Cancelling() {
		explainCancelling(job, out)
		return
	}
	if job.Provisioning != "" {
		out.Blocked = true
		out.Summary = "Provisioning is paused for this item."
		if job.Provisioning == "deleted" {
			out.Summary = "This item was deleted from the provisioning queue."
		}
		out.Detail = "It contributes no new runner demand. Existing runners and the pool's warm capacity can still pick up the GitHub job."
		out.Fix = "Resume the item in Queue to restore its provisioning demand."
		return
	}
	plan, planAt := c.getLastPlan()

	// Nothing claims it. The scheduler records why when the reason is not the
	// obvious one, and the obvious one still needs saying.
	if !job.Matched {
		out.Blocked = true
		out.Summary = "No pool in this fleet claims this job."
		out.Detail = fmt.Sprintf("It asks for [%s], and no enabled pool advertises those labels for the installation covering %s.",
			joinLabels(job.Labels), job.Repo)
		if plan != nil {
			for _, u := range plan.Unmatched {
				if u.Job != nil && u.Job.ID == job.ID && u.Reason != "" {
					out.Detail = u.Reason
					break
				}
			}
		}
		out.Fix = "create or enable a pool advertising those labels, or change the workflow's runs-on. If another runner provider takes these jobs, nothing needs doing."
		return
	}

	pool, err := c.st.GetPool(ctx, job.PoolID)
	if err != nil {
		out.Summary = "A pool claimed this job, and that pool is no longer here."
		out.Fix = "the job will be re-matched on the next pass; if it is not, its labels no longer name a pool."
		return
	}
	out.Summary = "A runner is on its way for this job."
	out.Detail = "It is claimed by " + pool.Name + "."

	// The scheduler's own sentence for this pool, which is the one thing the
	// browser could never work out for itself: whether a runner can be placed
	// at all is a question about hosts, not about counts.
	if plan != nil {
		for _, pp := range plan.Pools {
			if pp.PoolID != pool.ID {
				continue
			}
			if pp.Blocked != "" {
				out.Blocked = true
				out.Summary = "The scheduler wants a runner for this job and cannot place one."
				out.Detail = pp.Blocked
				out.Fix = pp.BlockedFix
				if out.Fix == "" {
					out.Fix = "add a host, raise a host's capacity, uncordon one, or relax the pool's host selector."
				}
				return
			}
			// A pool whose runners keep dying before they register is the case
			// that read as a pool that was merely slow. It has to be said
			// before the counts below, because those describe a fleet working:
			// "a runner is starting for this job" is true of a pool on its
			// twentieth failed attempt, and saying it to somebody watching a
			// queue that has not moved in an hour is worse than saying
			// nothing.
			if pp.Failing != "" {
				out.Blocked = true
				out.Summary = pool.Name + " keeps failing to start a runner for this job."
				out.Detail = pp.Failing
				out.Fix = startFailureFix(pp.FailingFault)
				return
			}
			// What the jobs waiting are known to need, and what that did to
			// where the runner goes -- or, in shadow, what it would have.
			if pp.History != "" {
				out.Detail += " Job history: " + pp.History + "."
			}
			if pp.HistoryUnfit != "" {
				out.Detail += " " + capitalise(pp.HistoryUnfit) + "."
			}
			break
		}
	}

	counts, err := c.st.CountRunnersByPool(ctx)
	if err != nil {
		// The counts are the nicety; the claim above is the answer.
		return
	}
	pc := counts[pool.ID]
	switch {
	case pc.Idle > 0:
		out.Summary = fmt.Sprintf("%s idle in %s, so GitHub should hand this job over any moment.",
			runnersAre(pc.Idle), pool.Name)
		out.Detail = "Which runner takes it is GitHub's choice, not this fleet's."
	case pc.Provisioning+pc.Registering > 0:
		out.Summary = fmt.Sprintf("%s starting for %s.", runnersAre(pc.Provisioning+pc.Registering), pool.Name)
		out.Detail = "The job goes to the first one GitHub sees."
	case pool.MaxRunners > 0 && pc.Live() >= pool.MaxRunners:
		out.Waiting = true
		out.Summary = fmt.Sprintf("%s is at its ceiling of %s, all busy.", pool.Name, plural(pool.MaxRunners, "runner"))
		out.Detail = "The job waits for one of them to finish."
		out.Fix = "raise this pool's max_runners if the fleet has room for more."
	default:
		out.Summary = "No runner is free for this job yet, and none is starting."
		out.Detail = "The scheduler decides on its next pass."
		if !planAt.IsZero() {
			out.Detail = fmt.Sprintf("The scheduler last decided %s ago and will decide again on its next pass.",
				formatAge(c.Now().Sub(planAt)))
		}
	}
}

// runnersAre agrees the verb with the count, which the general plural helper
// cannot: it pluralises the noun it is given, and "1 runner is" pluralises to
// "2 runner iss".
func runnersAre(n int) string {
	if n == 1 {
		return "1 runner is"
	}
	return fmt.Sprintf("%d runners are", n)
}

func joinLabels(labels store.StringSlice) string {
	if len(labels) == 0 {
		return "no labels"
	}
	return strings.Join(labels, ", ")
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// seedRunner puts one runner of a pool on a host, in a state.
func (h *harness) seedRunner(t *testing.T, pool *store.Pool, host *store.Host, state store.RunnerState) *store.Runner {
	t.Helper()
	r := &store.Runner{
		PoolID: pool.ID, HostID: host.ID,
		Name:      "zoomies-" + pool.Name + "-" + store.NewSecret(4),
		State:     store.RunnerProvisioning,
		Ephemeral: true, Labels: pool.Labels,
	}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	for _, to := range []store.RunnerState{store.RunnerRegistering, store.RunnerIdle, store.RunnerBusy} {
		out, err := h.st.TransitionRunner(h.ctx, r.ID, to, "")
		if err != nil {
			t.Fatalf("TransitionRunner(%s): %v", to, err)
		}
		r = out
		if to == state {
			break
		}
	}
	return r
}

// queuedJob puts one queued job in the store, claimed or not.
func (h *harness) queuedJob(t *testing.T, pool *store.Pool, labels []string) *store.Job {
	t.Helper()
	j := &store.Job{
		GitHubJobID: time.Now().UnixNano(),
		Repo:        "acme/widgets",
		Workflow:    "CI",
		JobName:     "build",
		Labels:      store.NormalizeLabels(labels),
		State:       store.JobQueued,
		QueuedAt:    h.c.Now().Add(-2 * time.Minute),
	}
	if pool != nil {
		j.PoolID, j.Matched = pool.ID, true
	}
	saved, err := h.st.UpsertJob(h.ctx, j)
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	return saved
}

// The question this endpoint exists for has four answers that need different
// advice, and the difference between them is what an operator does next. A
// fleet that is merely busy clears itself; a pool nothing can place never will;
// a job GitHub is holding is not this fleet's at all; and a job no pool claims
// will not run here however long anybody waits.
func TestTheExplanationTellsWaitingApartFromBlocked(t *testing.T) {
	t.Run("a job nothing claims is blocked, not waiting for capacity", func(t *testing.T) {
		h := newHarness(t)
		h.fleet()
		job := h.queuedJob(t, nil, []string{"self-hosted", "cuda12"})

		got, err := h.c.ExplainJob(h.ctx, job.ID)
		if err != nil {
			t.Fatalf("ExplainJob: %v", err)
		}
		if !got.Blocked {
			t.Error("a job no pool claims was not reported as blocked; waiting will never start it")
		}
		if !strings.Contains(got.Summary, "No pool") {
			t.Errorf("summary = %q, want it to say nothing claims the job", got.Summary)
		}
		if !strings.Contains(got.Detail, "cuda12") {
			t.Errorf("the detail does not name the labels that went unanswered: %q", got.Detail)
		}
		if got.Fix == "" {
			t.Error("a blocked job with no fix leaves the operator nowhere to go")
		}
	})

	t.Run("a held job is GitHub's wait, and says so", func(t *testing.T) {
		h := newHarness(t)
		h.fleet()
		// Held from the moment it was first seen, which is how GitHub reports
		// one: the jobs upsert refuses to move a job backwards, so a job
		// cannot be queued and then become held.
		job, err := h.st.UpsertJob(h.ctx, &store.Job{
			GitHubJobID: 9911, Repo: "acme/widgets", Workflow: "Deploy", JobName: "deploy",
			Labels: store.NormalizeLabels([]string{"self-hosted", "linux"}),
			State:  store.JobWaiting, QueuedAt: h.c.Now().Add(-10 * time.Minute),
		})
		if err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}

		got, err := h.c.ExplainJob(h.ctx, job.ID)
		if err != nil {
			t.Fatalf("ExplainJob: %v", err)
		}
		if !got.Waiting {
			t.Error("a held job is waiting on something")
		}
		if got.Blocked {
			t.Error("a held job was called blocked; an approval will start it and nothing here is wrong")
		}
		if !strings.Contains(got.Summary, "deployment review") {
			t.Errorf("summary = %q, want it to name the review", got.Summary)
		}
	})

	t.Run("the scheduler's own words are what a blocked pool says", func(t *testing.T) {
		h := newHarness(t)
		_, pool, _ := h.fleet()
		job := h.queuedJob(t, pool, []string{"self-hosted", "linux"})

		// The plan is the only place that knows a runner cannot be placed:
		// it is a question about hosts, and no count on the pool answers it.
		h.c.mu.Lock()
		h.c.lastPlan = &scheduler.Plan{Pools: []scheduler.PoolPlan{{
			PoolID:     pool.ID,
			PoolName:   pool.Name,
			Blocked:    "no host can take a new docker runner (2 not matching the pool's host selector)",
			BlockedFix: "add a host, uncordon one, or relax the pool's host selector",
		}}}
		h.c.lastPlanAt = h.c.Now()
		h.c.mu.Unlock()

		got, err := h.c.ExplainJob(h.ctx, job.ID)
		if err != nil {
			t.Fatalf("ExplainJob: %v", err)
		}
		if !got.Blocked {
			t.Fatal("a pool the scheduler cannot place was not reported as blocked")
		}
		if !strings.Contains(got.Detail, "not matching the pool's host selector") {
			t.Errorf("the detail is not the scheduler's own sentence: %q", got.Detail)
		}
		if !strings.Contains(got.Fix, "host selector") {
			t.Errorf("the fix is not the scheduler's own: %q", got.Fix)
		}
	})

	t.Run("a job with an idle runner waiting for it is neither", func(t *testing.T) {
		h := newHarness(t)
		_, pool, host := h.fleet()
		h.seedRunner(t, pool, host, store.RunnerIdle)
		job := h.queuedJob(t, pool, []string{"self-hosted", "linux"})

		got, err := h.c.ExplainJob(h.ctx, job.ID)
		if err != nil {
			t.Fatalf("ExplainJob: %v", err)
		}
		if got.Blocked {
			t.Error("a job with an idle runner ready for it was called blocked")
		}
		if !strings.Contains(got.Summary, "idle") {
			t.Errorf("summary = %q, want it to say a runner is idle and waiting", got.Summary)
		}
	})
}

// A job that is running is not usually interesting -- except when the host
// under it has gone quiet, which looks exactly like a healthy long job and is
// the case an operator most wants found for them.
func TestTheExplanationCatchesARunningJobOnASilentHost(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	runner := h.seedRunner(t, pool, host, store.RunnerBusy)

	job := h.queuedJob(t, pool, []string{"self-hosted", "linux"})
	started := h.c.Now().Add(-time.Minute)
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: job.GitHubJobID, State: store.JobInProgress, Repo: job.Repo,
		RunnerID: runner.ID, RunnerName: runner.Name, StartedAt: &started,
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	// While the host is heartbeating there is nothing to say beyond where it is.
	got, err := h.c.ExplainJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if got.Blocked || !strings.Contains(got.Summary, "running") {
		t.Fatalf("a healthy running job reported %+v", got)
	}

	// Once it has gone quiet the job is in trouble and nothing else says so.
	h.advance(store.HeartbeatTimeout + time.Minute)
	got, err = h.c.ExplainJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if !got.Blocked {
		t.Error("a job on a host that has gone quiet was not flagged")
	}
	if !strings.Contains(got.Summary, "gone quiet") {
		t.Errorf("summary = %q, want it to name the silent host", got.Summary)
	}
	if got.HostID != host.ID {
		t.Errorf("host_id = %q, want the host the operator has to go and look at", got.HostID)
	}
}

package controller

import (
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// faultTotals reads the split counter back through the registry, the way a
// scrape would, keyed by domain and category.
func (h *harness) faultTotals() map[string]float64 {
	h.t.Helper()
	families, err := h.c.metrics.reg.Gather()
	if err != nil {
		h.t.Fatalf("Gather: %v", err)
	}
	out := map[string]float64{}
	for _, mf := range families {
		name := mf.GetName()
		if name != "zoomies_job_failures_total" && name != "zoomies_runner_start_failures_total" {
			continue
		}
		for _, m := range mf.GetMetric() {
			key := name
			for _, l := range m.GetLabel() {
				if l.GetName() == "domain" || l.GetName() == "fault" {
					key += "|" + l.GetValue()
				}
			}
			out[key] += m.GetCounter().GetValue()
		}
	}
	return out
}

// The category is the whole point: "the runner died" is a bad afternoon, and
// "the runner died because it ran out of memory" is a number somebody can
// raise. The exit code is the evidence and only the agent has it, so the
// classification has to survive the trip.
func TestAnExitCodeReachesTheJobAsACategoryAndAFix(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9101, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerFailed, ExitCode: 137,
		Message:    "runner exited with code 137: the container was killed for exceeding its memory limit",
		Fault:      store.FaultOutOfMemory,
		ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	after, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if after.FaultKind != store.FaultOutOfMemory {
		t.Fatalf("fault kind = %q, want out_of_memory: the agent said so and nothing above it should have second-guessed it", after.FaultKind)
	}
	if after.FaultDomain() != store.FaultDomainFleet {
		t.Fatalf("fault domain = %q, want fleet", after.FaultDomain())
	}
	// The runner row carries it too, because the runner's page is where
	// somebody goes next and it must not have to ask the job.
	failed := h.runnerByID(t, r.ID)
	if failed.FaultKind != store.FaultOutOfMemory {
		t.Fatalf("the runner row's fault kind = %q, want out_of_memory", failed.FaultKind)
	}

	// The explanation offers the category's own remedy rather than the generic
	// "go and look", which is the difference between being told the fleet
	// broke the job and being told what to change.
	why, err := h.c.ExplainJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if !strings.Contains(why.Fix, "memory limit") {
		t.Fatalf("explanation fix = %q, want the memory limit named", why.Fix)
	}

	totals := h.faultTotals()
	if got := totals["zoomies_job_failures_total|fleet|out_of_memory"]; got != 1 {
		t.Fatalf("fleet/out_of_memory failures = %v, want 1 (all: %v)", got, totals)
	}
}

// An agent older than the category field sends none. The controller must read
// that as "we could not narrow it" rather than as "nothing is wrong": the
// second would hand the failure back to a workflow that did nothing.
func TestAFaultWithNoCategoryIsUnclassifiedRatherThanAbsent(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9102, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerFailed, ExitCode: 1,
		Message: "runner exited with code 1", ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}
	after, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if after.FaultKind != store.FaultRunnerExited {
		t.Fatalf("fault kind = %q, want runner_exited for a report that carried none", after.FaultKind)
	}
	if after.FaultDomain() != store.FaultDomainFleet {
		t.Fatalf("fault domain = %q, want fleet: an uncategorised fault is still ours", after.FaultDomain())
	}
}

// A job GitHub failed with nothing wrong on this side belongs to the workflow,
// and the fleet must say so plainly. This is the half that used to be
// indistinguishable from the half above.
func TestAWorkflowFailureIsNotCountedAgainstTheFleet(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9103, labels)
	h.deliverJob(jobEvent{Action: "completed", JobID: 9103, Name: "test", Workflow: "CI",
		Labels: labels, RunnerName: r.Name, Conclusion: "failure"})

	after, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if !after.Failed() {
		t.Fatal("the job did not count as failed")
	}
	if after.FaultDomain() != store.FaultDomainWorkflow {
		t.Fatalf("fault domain = %q, want workflow", after.FaultDomain())
	}
	if after.FleetFailed() {
		t.Fatal("a test failure was recorded as the fleet's")
	}

	stats, err := h.c.Stats(h.ctx, time.Hour)
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	if stats.Failed != 1 || stats.FleetFailed != 0 {
		t.Fatalf("failed = %d, of them ours = %d; want 1 and 0", stats.Failed, stats.FleetFailed)
	}

	// And the two filters are genuinely opposite halves of one list.
	ours, n, err := h.st.ListJobs(h.ctx, store.JobFilter{FaultedOnly: true}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if n != 0 {
		t.Fatalf("faulted jobs = %d (%+v), want none", n, ours)
	}
	theirs, n, err := h.st.ListJobs(h.ctx, store.JobFilter{WorkflowFailedOnly: true}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if n != 1 || theirs[0].ID != job.ID {
		t.Fatalf("workflow failures = %d (%+v), want the one job", n, theirs)
	}
}

// failPoolRunner plays a pool that cannot start a container: a runner is
// placed, the create fails on the host, and it never registers. The second
// reconcile is what makes the scheduler see it, which is where the pool's own
// "my runners keep failing" sentence comes from.
func failPoolRunner(t *testing.T, h *harness, kind store.FaultKind, message string) *store.Runner {
	t.Helper()
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	var starting *store.Runner
	for _, r := range h.runners() {
		if r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering {
			starting = r
			break
		}
	}
	if starting == nil {
		t.Fatal("the scheduler placed no runner to fail")
	}
	if err := h.c.failRunnerID(h.ctx, starting.ID, message, kind); err != nil {
		t.Fatalf("failRunnerID: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile after the failure: %v", err)
	}
	return h.runnerByID(t, starting.ID)
}

// The failure that reached nothing. A runner that dies before it registers has
// no job to be recorded on, so from the Jobs page a pool whose containers will
// not start looked exactly like a pool that was merely busy -- and the
// operator watching a queue that never moved had nowhere to find out which.
func TestAFailedRunnerStartReachesTheJobsWaitingForIt(t *testing.T) {
	h := newHarness(t)
	_, _, _ = h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	h.deliverJob(jobEvent{Action: "queued", JobID: 9201, Name: "test", Workflow: "CI", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9201)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}

	failed := failPoolRunner(t, h, store.FaultImage,
		"the docker backend could not create runner zoomies-x: pulling ghcr.io/acme/runner:v9: manifest unknown")
	if failed.FaultKind != store.FaultImage {
		t.Fatalf("the failed runner's category = %q, want image", failed.FaultKind)
	}

	// The job is told, and deliberately not failed: it is still queued, the
	// next runner may well run it, and concluding a job GitHub still has open
	// would be the fleet inventing an outcome.
	again, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if again.State != store.JobQueued || again.Failed() {
		t.Fatalf("the job was moved by a failed runner start: state %q, failed %v", again.State, again.Failed())
	}
	events := h.timeline(job.ID)
	last := events[len(events)-1]
	if last.Kind != store.JobEventRunnerStartFailed {
		t.Fatalf("last timeline entry = %v, want runner_start_failed", kindsOfEvents(events))
	}
	if !strings.Contains(last.Message, "manifest unknown") {
		t.Fatalf("the entry dropped the backend's own words: %q", last.Message)
	}

	// A pool stuck in a start loop tries again every pass. One entry per job
	// per run of failures: a timeline is opened to avoid reading a log file,
	// not to read one. The report is replayed directly because the scheduler
	// has, correctly, stopped placing runners for this pool -- which is the
	// state the guard has to survive.
	before := *failed
	before.State = store.RunnerProvisioning
	h.c.noteRunnerStartFailure(h.ctx, &before, failed)
	if got := h.timeline(job.ID); len(got) != len(events) {
		t.Fatalf("a second failed start added another entry: %v", kindsOfEvents(got))
	}
}

// Two failed starts is a pool that will not recover on its own, and everything
// that looks at the fleet has to say so: the problems drawer with the category's
// own remedy, and the job's own page instead of the cheerful "a runner is on
// its way" that was equally true of a pool that had stopped being able to
// produce one.
func TestAPoolThatCannotStartARunnerSaysSoEverywhere(t *testing.T) {
	h := newHarness(t)
	_, _, _ = h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	h.deliverJob(jobEvent{Action: "queued", JobID: 9202, Name: "test", Workflow: "CI", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9202)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}

	failPoolRunner(t, h, store.FaultBackend,
		"the docker backend would not answer: dial unix /var/run/docker.sock: no such file")

	// The problems drawer, with the category's own remedy rather than the list
	// of three possibilities it used to offer every pool. Being handed three
	// when the fleet already knows which one it is is how an operator learns
	// not to read the fix line.
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var failing *Problem
	for i := range ps {
		if ps[i].Code == "pool.runners_failing" {
			failing = &ps[i]
		}
	}
	if failing == nil {
		t.Fatalf("problems = %v, want pool.runners_failing", h.problemCodes())
	}
	if !strings.Contains(failing.Fix, "container backend") {
		t.Fatalf("the problem's fix = %q, want the backend category's own remedy", failing.Fix)
	}

	// And the job's own page.
	why, err := h.c.ExplainJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if !why.Blocked || !strings.Contains(why.Summary, "failing to start") {
		t.Fatalf("explanation = %+v, want a blocked job whose pool cannot start a runner", why)
	}
	if !strings.Contains(why.Fix, "container backend") {
		t.Fatalf("explanation fix = %q, want the backend category's own remedy", why.Fix)
	}

	// None of this reaches a job count, which is the blind spot the runner
	// counter exists to cover: the job is still queued and nothing is failed.
	stats, err := h.c.Stats(h.ctx, time.Hour)
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	if stats.Failed != 0 {
		t.Fatalf("failed jobs = %d, want 0: the job is still queued", stats.Failed)
	}
	if stats.RunnerStartFaults[store.FaultBackend] != 1 {
		t.Fatalf("runner start faults = %v, want one under backend", stats.RunnerStartFaults)
	}
}

// The one thing Zoomies can do about a failure it caused. It is offered on the
// strength of the category and allowed on the strength of the failure, which
// are deliberately different questions: an operator who has looked at a failure
// and decided to run it again is entitled to, and a button that refused on a
// judgement Zoomies made about blame is a button people route around.
func TestRerunAsksGitHubOnlyForAJobThatFailed(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9301, labels)

	// A job still running has nothing to run again.
	if _, err := h.c.RerunJobWorkflow(h.ctx, job.ID); !errors.Is(err, ErrJobNotFinished) {
		t.Fatalf("re-running a running job = %v, want ErrJobNotFinished", err)
	}
	if n := h.gh.Reruns() + h.gh.JobReruns(); n != 0 {
		t.Fatalf("GitHub was asked %d times about a job that had not finished", n)
	}

	// A job that succeeded is the other refusal, and a different sentence:
	// GitHub only reruns the failed jobs of a run.
	h.deliverJob(jobEvent{Action: "completed", JobID: 9301, RunID: 4301, Name: "test", Workflow: "CI",
		Labels: labels, RunnerName: r.Name, Conclusion: "success"})
	if _, err := h.c.RerunJobWorkflow(h.ctx, job.ID); !errors.Is(err, ErrJobDidNotFail) {
		t.Fatalf("re-running a successful job = %v, want ErrJobDidNotFail", err)
	}
	if n := h.gh.Reruns() + h.gh.JobReruns(); n != 0 {
		t.Fatalf("GitHub was asked %d times about a job that succeeded", n)
	}

	// A workflow's own failure: allowed, because whose fault it was is not
	// this call's question.
	h.deliverJob(jobEvent{Action: "queued", JobID: 9302, RunID: 4302, Name: "test", Workflow: "CI", Labels: labels})
	h.deliverJob(jobEvent{Action: "completed", JobID: 9302, RunID: 4302, Name: "test", Workflow: "CI",
		Labels: labels, Conclusion: "failure", Steps: failingSteps()})
	theirs, err := h.st.GetJobByGitHubID(h.ctx, 9302)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if _, err := h.c.RerunJobWorkflow(h.ctx, theirs.ID); err != nil {
		t.Fatalf("RerunJobWorkflow on a workflow failure: %v", err)
	}
	// Job-level, because this job has a GitHub job ID: the operator asked
	// about one job and gets that job, not every failure sharing its run.
	if n := h.gh.JobReruns(); n != 1 {
		t.Fatalf("GitHub was asked for %d job re-runs, want one", n)
	}
	if n := h.gh.Reruns(); n != 0 {
		t.Fatalf("the run-level re-run was used %d times for a job that has its own ID; that re-runs every failure in the run", n)
	}

	// Nothing local is written beyond the record that somebody asked: the
	// re-run arrives as new deliveries with a higher run attempt, and an
	// outcome invented here would be the fleet answering for GitHub.
	after, err := h.st.GetJob(h.ctx, theirs.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if after.Conclusion != "failure" || after.State != store.JobCompleted {
		t.Fatalf("the re-run changed the local row: %q/%q", after.State, after.Conclusion)
	}
	events := h.timeline(theirs.ID)
	last := events[len(events)-1]
	if last.Kind != store.JobEventRerunRequested {
		t.Fatalf("last timeline entry = %v, want rerun_requested", kindsOfEvents(events))
	}
	// The blast radius is still said out loud, it is just smaller now: the
	// job, and whatever declares it in `needs`. An operator reading the
	// timeline should not have to go to GitHub to find out what else ran.
	if !strings.Contains(last.Message, "any job that needs it") {
		t.Fatalf("the entry does not say what else goes with it: %q", last.Message)
	}
}

// A job whose GitHub job ID this fleet never recorded -- an old row, or one
// whose workflow_job delivery never arrived -- still gets its button. GitHub's
// job-level re-run needs that ID, so the wider run-level call is the fallback,
// and the timeline says so rather than leaving an operator to discover from
// the billing page that three other jobs ran again.
func TestRerunFallsBackToTheRunWhenAJobHasNoGitHubID(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	_ = host

	// Written straight to the store with no GitHub job ID, which is the state
	// this path exists for: a row from before the fleet recorded one, or a job
	// whose workflow_job delivery never arrived.
	inst, err := h.st.ListInstallations(h.ctx)
	if err != nil || len(inst) == 0 {
		t.Fatalf("the harness has no installation to attribute the job to: %v", err)
	}
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 0, GitHubRunID: 4401, Repo: "acme/widgets", InstallationID: inst[0].ID,
		JobName: "test", Workflow: "CI", Labels: labels,
		State: store.JobCompleted, Conclusion: "failure",
	})
	if err != nil {
		t.Fatalf("seeding a job with no GitHub job ID: %v", err)
	}

	if _, err := h.c.RerunJobWorkflow(h.ctx, job.ID); err != nil {
		t.Fatalf("RerunJobWorkflow: %v", err)
	}
	if n := h.gh.Reruns(); n != 1 {
		t.Errorf("the run-level re-run was used %d times, want once: it is the only one that works without a job ID", n)
	}
	if n := h.gh.JobReruns(); n != 0 {
		t.Errorf("a job-level re-run was attempted %d times with no job ID to name", n)
	}

	events := h.timeline(job.ID)
	last := events[len(events)-1]
	if !strings.Contains(last.Message, "failed jobs") {
		t.Errorf("the entry does not say the whole run's failures went with it: %q", last.Message)
	}
}

// Auto-recovery is the same call the button makes, decided by a setting rather
// than by a person. What matters is that it is narrow: the fleet's own
// failures, bounded by GitHub's attempt number, and nothing at all while the
// setting is off -- which is the default, because each one of these spends
// somebody's GitHub minutes.
func TestAJobTheFleetBrokeIsReRunOnlyWhenTheSettingSaysSo(t *testing.T) {
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	for _, tc := range []struct {
		name       string
		on         bool
		limit      int
		attempt    int
		fleetFault bool
		want       int
	}{
		{"off by default", false, 1, 1, true, 0},
		{"on, first attempt, the fleet's fault", true, 1, 1, true, 1},
		{"on, but the workflow's own failure", true, 1, 1, false, 0},
		{"on, but this run has had its re-run", true, 1, 2, true, 0},
		{"a higher limit lets a second attempt through", true, 2, 2, true, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, _, host := h.fleet()
			h.c.live.Update(func(c *config.Config) {
				c.Scheduler.AutoRerun, c.Scheduler.AutoRerunLimit = tc.on, tc.limit
			})

			job, r := startJobOnRunner(t, h, host.ID, 9501, labels)
			if tc.fleetFault {
				// The order the fleet actually sees it in: the runner goes
				// first, GitHub reports the job over afterwards.
				before, err := h.st.GetRunner(h.ctx, r.ID)
				if err != nil {
					t.Fatalf("GetRunner: %v", err)
				}
				h.c.noteRunnerLost(h.ctx, before, sourceAgent,
					"runner exited with code 137: the container was killed for exceeding its memory limit",
					store.FaultOutOfMemory)
			}
			h.deliverJob(jobEvent{Action: "completed", JobID: 9501, RunID: 4501, Name: "test", Workflow: "CI",
				Labels: labels, RunnerName: r.Name, Conclusion: "failure", RunAttempt: tc.attempt,
				Steps: failingSteps()})

			if n := h.gh.JobReruns(); n != tc.want {
				t.Fatalf("GitHub was asked to re-run %d times, want %d", n, tc.want)
			}
			if tc.want == 0 {
				return
			}
			// The timeline says the fleet asked, not an operator: somebody
			// reading it must not go looking for the colleague who pressed a
			// button nobody pressed.
			events := h.timeline(job.ID)
			last := events[len(events)-1]
			if last.Kind != store.JobEventRerunRequested || last.Source != sourceRecovery {
				t.Fatalf("last entry = %s via %s, want a re-run via recovery", last.Kind, last.Source)
			}
			if !strings.Contains(last.Message, "scheduler.auto_rerun") {
				t.Errorf("the entry does not name the setting that did it: %q", last.Message)
			}
		})
	}
}

// A duplicate delivery must not buy a second re-run. GitHub delivers at least
// once, and a completion that arrives twice for a job already completed is not
// a state change -- so it never reaches the re-run. This pins that, because
// the cost of getting it wrong is a bill rather than a wrong pixel.
func TestARepeatedCompletionDoesNotReRunTwice(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	h.c.live.Update(func(c *config.Config) {
		c.Scheduler.AutoRerun, c.Scheduler.AutoRerunLimit = true, 3
	})

	_, r := startJobOnRunner(t, h, host.ID, 9601, labels)
	before, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	h.c.noteRunnerLost(h.ctx, before, sourceAgent, "the runner stopped", store.FaultRunnerExited)

	done := jobEvent{Action: "completed", JobID: 9601, RunID: 4601, Name: "test", Workflow: "CI",
		Labels: labels, RunnerName: r.Name, Conclusion: "failure", RunAttempt: 1, Steps: failingSteps()}
	h.deliverJob(done)
	h.deliverJob(done)
	h.deliverJob(done)

	if n := h.gh.JobReruns(); n != 1 {
		t.Fatalf("GitHub was asked to re-run %d times for three deliveries of one completion, want once", n)
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// fence puts the harness's fleet behind the fence, the way a restore does.
func (h *harness) fence(reason string) {
	h.t.Helper()
	if err := h.st.SetRecoveryFence(h.ctx, true, reason); err != nil {
		h.t.Fatalf("SetRecoveryFence: %v", err)
	}
	if err := h.c.LoadFence(h.ctx); err != nil {
		h.t.Fatalf("LoadFence: %v", err)
	}
}

// The fence's whole value is the difference between deciding and doing. A
// controller that stopped deciding would leave an operator recovering a fleet
// with nothing to look at, and no way to tell "the scheduler wants nothing"
// from "the scheduler is not allowed to want anything".
func TestAFencedFleetStillDecidesAndCreatesNothing(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})

	h.fence("restored from a backup taken on Tuesday")
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	runners, _, err := h.st.ListRunners(h.ctx, store.RunnerFilter{}, store.Page{Limit: 50})
	if err != nil {
		t.Fatal(err)
	}
	if len(runners) != 0 {
		t.Fatalf("a fenced fleet created %d runners", len(runners))
	}

	// And the plan is there, saying what it would have done.
	plan, at := h.c.getLastPlan()
	if plan == nil || at.IsZero() {
		t.Fatal("a fenced pass recorded no plan, so the Overview has nothing to show")
	}
	var wanted int
	for _, pp := range plan.Pools {
		for _, a := range pp.Actions {
			if a.Kind == scheduler.ActionCreate {
				wanted++
			}
		}
	}
	if wanted == 0 {
		t.Error("the fenced pass decided to do nothing at all; the plan is meant to be what it would do")
	}

	// Lifting it does the work that was waiting.
	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatalf("Unfence: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile after lifting: %v", err)
	}
	runners, _, err = h.st.ListRunners(h.ctx, store.RunnerFilter{}, store.Page{Limit: 50})
	if err != nil {
		t.Fatal(err)
	}
	if len(runners) == 0 {
		t.Error("lifting the fence did not let the fleet act")
	}
}

// A fenced controller looks exactly like a healthy one with nothing to do, so
// the drawer is the only thing that says otherwise. It is the highest
// consequence entry the drawer can carry, because everything else on it is
// something that went wrong and this is something somebody chose.
func TestTheFenceIsOnTheProblemsList(t *testing.T) {
	h := newHarness(t)
	h.fence("restored from /var/backups/zoomies/zoomies-20260908-181718")

	var p Problem
	all, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, item := range all {
		if item.Code == "recovery.fenced" {
			p = item
		}
	}
	if p.Code == "" {
		t.Fatalf("the fence is not on the problems list: %v", h.problemCodes())
	}
	if p.Severity != config.SeverityError {
		t.Errorf("severity = %s; a fleet doing nothing is not a warning", p.Severity)
	}
	// The reason travels with it, because "fenced" without "why" sends an
	// operator looking for a fault that is not there.
	if !strings.Contains(p.Detail, "zoomies-20260908-181718") {
		t.Errorf("the detail does not say why it is fenced: %q", p.Detail)
	}
	// The fix names the checks rather than only the route: an operator who
	// lifts the fence without making them has spent the fence for nothing.
	for _, want := range []string{"external URL", "agents", "runners", "/api/v1/recovery/unfence"} {
		if !strings.Contains(p.Fix, want) {
			t.Errorf("the fix does not mention %q: %q", want, p.Fix)
		}
	}

	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatalf("Unfence: %v", err)
	}
	if contains(h.problemCodes(), "recovery.fenced") {
		t.Error("the fence is still on the list after being lifted")
	}
}

// A write that failed must leave a fenced controller rather than one that
// believes it is free: the fence is the safe side of its own question.
func TestUnfenceKeepsTheFenceWhenItCannotWriteIt(t *testing.T) {
	h := newHarness(t)
	h.fence("restored")
	if err := h.st.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if err := h.c.Unfence(h.ctx); err == nil {
		t.Fatal("Unfence reported success with no database to write to")
	}
	if !h.c.Fenced().Fenced {
		t.Error("the controller believes it is unfenced after a write that failed")
	}
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The validator judges an operator's deadlines against constants of its own,
// because config sits below the store and the agent and cannot import either.
// Every one of those restatements is a number that can drift away from the
// thing it describes without anything failing, so this is what holds them.
//
// The pair that matters most is the two silences. A host is unhealthy after
// ninety seconds, which only stops new runners being placed on it, and lost
// after five minutes, which fails the runners already there. A deadline judged
// against the wrong one of those is not off by a little: provider.delete_grace
// measured against the ninety seconds accepted a grace that destroys a machine
// while the fleet still believes a job is running on it.
func TestTheValidatorAgreesWithWhatItIsJudgingAgainst(t *testing.T) {
	for _, c := range []struct {
		what        string
		restated    any
		source      any
		consequence string
	}{
		{"config.HostUnhealthyAfter", config.HostUnhealthyAfter, store.HeartbeatTimeout,
			"the heartbeat warning would name the wrong silence"},
		{"config.RunnersLostAfter", config.RunnersLostAfter, hostLostAfter,
			"provider.delete_grace and provider.idle_timeout would be judged against a silence that frees nothing"},
		{"config.RunnerCreateBudget", config.RunnerCreateBudget, agent.CreateTimeout,
			"the provision timeout would be judged against a create budget the agent does not keep"},
	} {
		if c.restated != c.source {
			t.Errorf("%s = %s but its source is %s; %s", c.what, c.restated, c.source, c.consequence)
		}
	}
}

package controller

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

const testWebhookSecret = "s3cret-for-tests"

// fakeFactory hands out clients backed by github.NewFake. The private key is
// checked but not used, which is what lets a test seal a dummy key and still
// exercise the unseal-then-build path the real factory takes.
type fakeFactory struct {
	gh  *github.FakeGitHub
	err error
}

func (f *fakeFactory) For(_ context.Context, inst *store.Installation, privateKeyPEM []byte) (github.Client, error) {
	if f.err != nil {
		return nil, f.err
	}
	if len(privateKeyPEM) == 0 {
		return nil, errors.New("fake factory: no private key")
	}
	return f.gh.Client(inst.Target, inst.TargetType), nil
}

// harness is a controller wired to an in-memory store and a fake GitHub.
type harness struct {
	t       *testing.T
	c       *Controller
	st      *store.Store
	gh      *github.FakeGitHub
	factory *fakeFactory
	key     *cryptox.Key
	cfg     *config.Config
	ctx     context.Context
	// fake is the provider every machine test drives, and providers the
	// registry the controller builds it from. One fake, shared by the
	// controller and the test, so that a test can ask what was actually asked
	// of the provider rather than inferring it from the rows.
	fake      provider.Fake
	providers *provider.Registry
	// offset is added to the wall clock the controller reads, in nanoseconds.
	// It is zero unless a test calls advance, so time still passes normally
	// for everything that does not ask; a lease that has to expire is the one
	// thing a test cannot wait out honestly.
	offset *atomic.Int64
}

// advance moves the controller's clock forward without moving the test's.
func (h *harness) advance(d time.Duration) { h.offset.Add(int64(d)) }

// testConfig is a configuration that validates without a single warning, so a
// test asserting "Problems is empty" is asserting about the fleet rather than
// about the defaults.
func testConfig(t *testing.T) *config.Config {
	t.Helper()
	cfg := config.Default()
	cfg.Server.Bind = "127.0.0.1:8080"
	cfg.Server.ExternalURL = "https://zoomies.test"
	cfg.Database.Path = filepath.Join(t.TempDir(), "zoomies.db")
	cfg.Security.EncryptionKey = "0000000000000000000000000000000000000000000="
	// No embedded agent: it would otherwise warn about running as root, which
	// CI often is, and this is a controller test either way.
	cfg.Agent.Embedded = false
	cfg.Agent.Backend = "process"
	cfg.Agent.WorkDir = filepath.Join(t.TempDir(), "work")
	return cfg
}

func newHarness(t *testing.T) *harness {
	t.Helper()
	ctx := context.Background()

	st, err := store.Open(ctx, store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { st.Close() })

	gh := github.NewFake()
	t.Cleanup(gh.Close)

	key, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}

	cfg := testConfig(t)
	bus := events.New()
	factory := &fakeFactory{gh: gh}
	offset := new(atomic.Int64)

	fake := provider.NewFake()
	providers, err := provider.NewRegistry(&sharedFakeFactory{fake: fake})
	if err != nil {
		t.Fatalf("provider.NewRegistry: %v", err)
	}

	c, err := New(Options{
		Store:  st,
		Config: cfg,
		Key:    key,
		Auth:   auth.New(st, cfg, bus),
		Events: bus,
		GitHub: factory,
		// Background update checks must not depend on public GitHub in tests.
		HTTPClient: &http.Client{Transport: harnessTransport{}},
		Providers:  providers,
		Logger:     slog.New(slog.DiscardHandler),
		Clock:      func() time.Time { return time.Now().Add(time.Duration(offset.Load())) },
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	return &harness{t: t, c: c, st: st, gh: gh, factory: factory, key: key, cfg: cfg, ctx: ctx,
		offset: offset, fake: fake, providers: providers}
}

// sharedFakeFactory hands out one fake rather than building a new one per
// call, which is what lets a test ask the provider what it was asked to do.
// provider.NewFakeFactory deliberately builds a fresh fake each time, which is
// right for the registry's own tests and useless here.
type sharedFakeFactory struct{ fake provider.Fake }

func (f *sharedFakeFactory) Kind() store.ProviderKind                    { return store.ProviderFake }
func (f *sharedFakeFactory) Describe() provider.Capabilities             { return f.fake.Capabilities() }
func (f *sharedFakeFactory) Settings() []provider.SettingSpec            { return nil }
func (f *sharedFakeFactory) Validate(map[string]string) []config.Finding { return nil }
func (f *sharedFakeFactory) New(context.Context, provider.Config) (provider.Provider, error) {
	return f.fake, nil
}

// installation seeds a GitHub App installation on the "acme" organisation with
// a sealed webhook secret.
func (h *harness) installation() *store.Installation {
	h.t.Helper()
	return h.installationOn("acme", store.TargetOrg)
}

// installationOn seeds an installation on a named target, so that a test can
// have two of them and prove work does not cross between them. One fake GitHub
// backs both: its client is built per target, which is the distinction that
// matters here.
func (h *harness) installationOn(target string, kind store.TargetType) *store.Installation {
	h.t.Helper()
	pem, err := h.key.SealString("-----BEGIN RSA PRIVATE KEY-----\ntest\n-----END RSA PRIVATE KEY-----")
	if err != nil {
		h.t.Fatalf("sealing key: %v", err)
	}
	secret, err := h.key.SealString(testWebhookSecret)
	if err != nil {
		h.t.Fatalf("sealing secret: %v", err)
	}
	inst := &store.Installation{
		AppID:            h.gh.AppID(),
		InstallationID:   h.gh.InstallationID(),
		Target:           target,
		TargetType:       kind,
		APIBaseURL:       h.gh.URL(),
		PrivateKeyEnc:    pem,
		WebhookSecretEnc: secret,
	}
	if err := h.st.CreateInstallation(h.ctx, inst); err != nil {
		h.t.Fatalf("CreateInstallation: %v", err)
	}
	return inst
}

// pool seeds an enabled ephemeral docker pool.
func (h *harness) pool(inst *store.Installation, name string, labels ...string) *store.Pool {
	h.t.Helper()
	if len(labels) == 0 {
		labels = []string{"self-hosted", "linux", "x64", "demo"}
	}
	p := &store.Pool{
		Name:           name,
		InstallationID: inst.ID,
		Labels:         labels,
		Backend:        store.BackendDocker,
		Image:          "ghcr.io/eyupio/zoomies-runner:test",
		MinRunners:     0,
		MaxRunners:     4,
		IdleTimeout:    store.Duration(5 * time.Minute),
		Ephemeral:      true,
		DockerMode:     store.DockerNone,
		Enabled:        true,
	}
	if err := h.st.CreatePool(h.ctx, p); err != nil {
		h.t.Fatalf("CreatePool: %v", err)
	}
	return p
}

// host seeds a healthy docker host with room for four runners.
func (h *harness) host(name string) *store.Host {
	h.t.Helper()
	host := &store.Host{
		Name:     name,
		Capacity: 4,
		Backends: store.StringSlice{"docker"},
		Labels:   store.StringMap{},
		OS:       "linux",
		Arch:     "amd64",
		// A machine large enough that nothing here is refused for want of
		// room: these tests are about everything except fit, and a fleet whose
		// hosts report nothing is a fleet of agents too old to measure
		// themselves -- which raises a note of its own and is not what any of
		// them mean to describe.
		CPUs:          16,
		MemoryMB:      64 * 1024,
		DiskTotalMB:   500 * 1024,
		DiskFreeMB:    400 * 1024,
		LastHeartbeat: time.Now(),
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		h.t.Fatalf("CreateHost: %v", err)
	}
	return host
}

// fleet is the common setup: one installation, one pool, one host.
func (h *harness) fleet() (*store.Installation, *store.Pool, *store.Host) {
	inst := h.installation()
	return inst, h.pool(inst, "linux-x64"), h.host("vm-1")
}

// ---------------------------------------------------------------------------
// Webhook helpers
// ---------------------------------------------------------------------------

type jobEvent struct {
	Action     string
	JobID      int64
	RunID      int64
	Repo       string
	Name       string
	Workflow   string
	Labels     []string
	RunnerName string
	Conclusion string
	QueuedAt   time.Time
	// RunAttempt is GitHub's attempt number for the job's run. Zero is sent
	// as the first attempt, which is what a delivery for a run nobody has
	// re-run carries.
	RunAttempt int
	// Steps, when set, are rendered as GitHub's steps array.
	Steps []map[string]any
}

// failingSteps renders the steps of a job that failed on its second step, which
// is the shape a completed delivery with a failure has.
func failingSteps() []map[string]any {
	return []map[string]any{
		{"number": 1, "name": "Checkout", "status": "completed", "conclusion": "success"},
		{"number": 2, "name": "Run tests", "status": "completed", "conclusion": "failure"},
		{"number": 3, "name": "Upload", "status": "completed", "conclusion": "skipped"},
	}
}

func (e jobEvent) body() []byte {
	if e.Repo == "" {
		e.Repo = "acme/widgets"
	}
	if e.QueuedAt.IsZero() {
		e.QueuedAt = time.Now().Add(-time.Minute)
	}
	status := e.Action
	if status == "waiting" {
		status = "queued"
	}
	job := map[string]any{
		"id":            e.JobID,
		"run_id":        e.RunID,
		"name":          e.Name,
		"workflow_name": e.Workflow,
		"labels":        e.Labels,
		"status":        status,
		"runner_name":   e.RunnerName,
		"created_at":    e.QueuedAt.Format(time.RFC3339),
		"html_url":      "https://github.com/" + e.Repo + "/actions/runs/1",
		"run_attempt":   max(e.RunAttempt, 1),
	}
	if e.Action == "in_progress" || e.Action == "completed" {
		job["started_at"] = e.QueuedAt.Add(30 * time.Second).Format(time.RFC3339)
	}
	if e.Action == "completed" {
		job["completed_at"] = e.QueuedAt.Add(2 * time.Minute).Format(time.RFC3339)
		job["conclusion"] = e.Conclusion
	}
	if e.Steps != nil {
		job["steps"] = e.Steps
	}
	b, _ := json.Marshal(map[string]any{
		"action":       e.Action,
		"workflow_job": job,
		"repository":   map[string]any{"full_name": e.Repo},
		"installation": map[string]any{"id": 42},
	})
	return b
}

// sign produces the HMAC header GitHub sends.
func sign(secret string, body []byte) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(body)
	return "sha256=" + hex.EncodeToString(mac.Sum(nil))
}

// deliver posts one webhook and returns the recorded response.
func (h *harness) deliver(event string, body []byte, secret string) *httptest.ResponseRecorder {
	h.t.Helper()
	req := httptest.NewRequest(http.MethodPost, "/webhooks/github", bytes.NewReader(body))
	req.Header.Set(github.EventTypeHeader, event)
	req.Header.Set(github.DeliveryIDHeader, "delivery-"+store.NewSecret(4))
	if secret != "" {
		req.Header.Set(github.SignatureHeader, sign(secret, body))
	}
	rec := httptest.NewRecorder()
	h.c.HandleWebhook(rec, req)
	return rec
}

// deliverJob posts a signed workflow_job delivery.
func (h *harness) deliverJob(e jobEvent) *httptest.ResponseRecorder {
	h.t.Helper()
	rec := h.deliver("workflow_job", e.body(), testWebhookSecret)
	h.c.enrichOnce(h.ctx)
	return rec
}

