// tasksFor returns the tasks queued for a host without consuming them.
func (h *harness) tasksFor(hostID string) []agent.Task {
	q := h.c.queues.get(hostID)
	q.mu.Lock()
	defer q.mu.Unlock()
	out := make([]agent.Task, 0, len(q.pending))
	for _, lt := range q.pending {
		out = append(out, lt.task)
	}
	return out
}

// taskOfKind returns the first queued task of a kind, or fails.
func (h *harness) taskOfKind(hostID string, kind agent.TaskKind) agent.Task {
	h.t.Helper()
	for _, t := range h.tasksFor(hostID) {
		if t.Kind == kind {
			return t
		}
	}
	h.t.Fatalf("no %s task queued for host %s (queued: %v)", kind, hostID, kindsOf(h.tasksFor(hostID)))
	return agent.Task{}
}

func (h *harness) hasTaskOfKind(hostID string, kind agent.TaskKind) bool {
	for _, t := range h.tasksFor(hostID) {
		if t.Kind == kind {
			return true
		}
	}
	return false
}

func kindsOf(tasks []agent.Task) []agent.TaskKind {
	out := make([]agent.TaskKind, 0, len(tasks))
	for _, t := range tasks {
		out = append(out, t.Kind)
	}
	return out
}

// runners returns every runner row, terminal ones included.
func (h *harness) runners() []*store.Runner {
	h.t.Helper()
	rs, _, err := h.st.ListRunners(h.ctx, store.RunnerFilter{IncludeRemoved: true}, store.Page{Limit: 500})
	if err != nil {
		h.t.Fatalf("ListRunners: %v", err)
	}
	return rs
}

// onlyRunner asserts there is exactly one runner and returns it.
// restart builds a fresh controller over the same store, which is what a
// process restart actually is: every row survives and every in-memory
// structure -- the task queue above all -- does not.
func (h *harness) restart() *Controller {
	h.t.Helper()
	bus := events.New()
	c, err := New(Options{
		Store:     h.st,
		Config:    h.cfg,
		Key:       h.key,
		Auth:      auth.New(h.st, h.cfg, bus),
		Events:    bus,
		GitHub:    h.factory,
		Providers: h.providers,
		Logger:    slog.New(slog.DiscardHandler),
		Clock:     func() time.Time { return time.Now().Add(time.Duration(h.offset.Load())) },
	})
	if err != nil {
		h.t.Fatalf("restarting the controller: %v", err)
	}
	return c
}

// runnerByID re-reads one runner, for a test that has to see a column change.
func (h *harness) runnerByID(t *testing.T, id string) *store.Runner {
	t.Helper()
	r, err := h.st.GetRunner(h.ctx, id)
	if err != nil {
		t.Fatalf("GetRunner %s: %v", id, err)
	}
	return r
}

func (h *harness) onlyRunner() *store.Runner {
	h.t.Helper()
	rs := h.runners()
	if len(rs) != 1 {
		h.t.Fatalf("expected exactly one runner, got %d", len(rs))
	}
	return rs[0]
}

// deliveries returns the recorded webhook deliveries.
func (h *harness) deliveries() []*store.WebhookDelivery {
	h.t.Helper()
	ds, err := h.st.ListDeliveries(h.ctx, "", 100)
	if err != nil {
		h.t.Fatalf("ListDeliveries: %v", err)
	}
	return ds
}

// problemCodes returns the codes Problems reports, for set assertions.
func (h *harness) problemCodes() []string {
	h.t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		h.t.Fatalf("Problems: %v", err)
	}
	out := make([]string, 0, len(ps))
	for _, p := range ps {
		out = append(out, p.Code)
	}
	return out
}

// drain reads a channel until it closes or the deadline passes.
func drain(t *testing.T, ch <-chan []byte, timeout time.Duration) []byte {
	t.Helper()
	var buf bytes.Buffer
	deadline := time.After(timeout)
	for {
		select {
		case b, ok := <-ch:
			if !ok {
				return buf.Bytes()
			}
			buf.Write(b)
		case <-deadline:
			return buf.Bytes()
		}
	}
}

// eventually polls cond until it holds or the deadline passes.
func eventually(t *testing.T, timeout time.Duration, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(2 * time.Millisecond)
	}
	t.Fatalf("timed out waiting for %s", what)
}

// byteReader yields one byte per Read, which is how a test produces many small
// chunks without a real network.
type byteReader struct {
	data []byte
	pos  int
}

func (r *byteReader) Read(p []byte) (int, error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	p[0] = r.data[r.pos]
	r.pos++
	return 1, nil
}

// newGetRequest builds a GET to the webhook path, for the method check.
func newGetRequest() *http.Request {
	return httptest.NewRequest(http.MethodGet, "/webhooks/github", nil)
}

func recorder() *httptest.ResponseRecorder { return httptest.NewRecorder() }

// mustReport plays the part of an agent asserting a runner state.
func mustReport(t *testing.T, h *harness, hostID, runnerID string, state store.RunnerState) {
	t.Helper()
	err := h.c.ReportRunners(h.ctx, hostID, []agent.RunnerReport{{
		RunnerID: runnerID, State: state, ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners(%s): %v", state, err)
	}
}

// mustReportRunning plays the part of an agent whose workload is up but which
// deliberately asserts no runner state, because whether GitHub has given the
// runner a job is not the agent's call.
func mustReportRunning(t *testing.T, h *harness, hostID, runnerID string) {
	t.Helper()
	err := h.c.ReportRunners(h.ctx, hostID, []agent.RunnerReport{{
		RunnerID: runnerID, Phase: backend.PhaseRunning,
		Handle: backend.Handle("container-" + runnerID), ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners(running): %v", err)
	}
}

// problem returns the one problem with a code, failing the test when the list
// does not carry it. Tests that assert on an entry's words need the entry, not
// only that its code is present.
func (h *harness) problem(t *testing.T, code string) Problem {
	t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range ps {
		if p.Code == code {
			return p
		}
	}
	t.Fatalf("no %s problem in %v", code, h.problemCodes())
	return Problem{}
}

// The controller's GitHub API client is already fake. Its independent public
// release checker uses this client, so intercept those two URLs as well.
type harnessTransport struct{}

func (harnessTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	if r.URL.String() == latestReleaseURL || r.URL.String() == mainCommitURL {
		return jsonResponse(http.StatusNotFound, `{}`), nil
	}
	return http.DefaultTransport.RoundTrip(r)
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/agent"
)

// Called under reconcileMu. A removal is not complete until the host says it
// is: recording a terminal job, restarting, or exhausting a lease is not proof.
func (c *Controller) recoverHostCleanup(ctx context.Context) error {
	if !c.mayAct() {
		return nil
	}
	const batch = 100
	runners, err := c.st.PendingHostCleanup(ctx, c.cleanupCursor, batch)
	if err != nil {
		return err
	}
	for _, r := range runners {
		c.enqueueLifecycle(ctx, r.HostID, agent.Task{
			Kind: agent.TaskRemoveRunner, RunnerID: r.ID, Backend: c.backendKind(ctx, r, nil),
		})
		c.cleanupCursor = r.ID
	}
	if len(runners) < batch {
		c.cleanupCursor = ""
	}
	return nil
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// A host given more slots than its machine has cores, or than its memory has
// 2 GB slots, is the shape the owner's report described: eight runners each
// promised a share under a core, and a daemon that stops answering. The
// warning names the machine, the capacity and the share each runner gets, and
// the fix names the largest capacity that would fit.
func TestAnOverprovisionedHostIsNamedWithTheCapacityThatFits(t *testing.T) {
	h := newHarness(t)
	// Four cores less the half-core floor is 3.5, so three slots fit; the
	// memory would take seven. Eight slots is more than either.
	host := h.measuredHost("crowded", 4, 16384, 8, enforcesEverything)

	p := h.problem(t, "host.overprovisioned")
	if p.Severity != config.SeverityWarning || p.TargetKind != "host" || p.TargetID != host.ID {
		t.Fatalf("problem = %+v; want a warning pointing at the host", p)
	}
	for _, want := range []string{"crowded", "capacity 8", "3.5 allocatable CPUs", "4 CPUs", "default share is 0.43 CPUs", "1945 MB"} {
		if !strings.Contains(p.Detail, want) {
			t.Errorf("detail %q does not say %q", p.Detail, want)
		}
	}
	if !strings.Contains(p.Fix, "capacity to 3") || !strings.Contains(p.Fix, host.ID) {
		t.Errorf("fix %q does not name the capacity that fits and where to set it", p.Fix)
	}
	if strings.Contains(p.Fix, "too small") {
		t.Errorf("fix %q calls a machine that fits three runners too small", p.Fix)
	}

	// With defaults off the runners are not merely small: nothing limits
	// them at all, which is the shape that stops Docker answering, and the
	// detail has to say so rather than quote a share nobody is given.
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = false })
	p = h.problem(t, "host.overprovisioned")
	if !strings.Contains(p.Detail, "nothing limits its runners") || strings.Contains(p.Detail, "default share") {
		t.Errorf("with defaults off the detail is %q", p.Detail)
	}
}

// When even one runner would not fit -- under a core, or under 2 GB, after
// the reserve -- lowering the capacity is not the whole answer, and the fix
// says the machine is too small rather than pretending a capacity of one is.
// The named capacity still never goes below one: zero is a cordon, and the
// operator has a cordon.
func TestAHostTooSmallForOneRunnerIsToldSo(t *testing.T) {
	h := newHarness(t)
	// One core less the half-core floor leaves half a core, and 2 GB less
	// the 512 MB floor leaves 1536 MB: neither is a runner's worth.
	h.measuredHost("tiny", 1, 2048, 2, enforcesEverything)

	p := h.problem(t, "host.overprovisioned")
	if !strings.Contains(p.Fix, "too small") || !strings.Contains(p.Fix, "capacity to 1") {
		t.Errorf("fix %q should say the machine is too small and still name capacity 1", p.Fix)
	}
}

// The warning is about hosts that do not fit, and only those: a host whose
// slots fit its cores and its memory raises nothing, a cordoned host is
// somebody's problem already, and the demo fleet is sized so that none of
// its hosts trips it.
func TestAHostWhoseSlotsFitRaisesNoOverprovisioningWarning(t *testing.T) {
	h := newHarness(t)
	h.host("roomy")
	h.measuredHost("exact", 4, 8192, 3, enforcesEverything)
	crowded := h.measuredHost("crowded-but-cordoned", 4, 16384, 8, enforcesEverything)
	if err := h.st.SetHostCordoned(h.ctx, crowded.ID, true); err != nil {
		t.Fatal(err)
	}
	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; every uncordoned host here fits", codes)
	}

	demo := newHarness(t)
	if err := demo.c.SeedDemo(demo.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	for _, code := range []string{"host.overprovisioned", "host.limits_unverified", "host.limits_unenforceable", "host.resources_unknown"} {
		if contains(demo.problemCodes(), code) {
			t.Errorf("the demo fleet raises %s; it exists to look like a fleet with nothing wrong", code)
		}
	}
}

// A daemon that has said it cannot apply a CPU quota refuses a runner that
// asks for one, so a pool with an explicit limit fails every create there
// and the default is withheld. The fix is the cgroup delegation a rootless
// daemon needs, spelled out.
func TestADaemonThatCannotApplyLimitsIsAWarningWithTheDelegationFix(t *testing.T) {
	h := newHarness(t)
	host := h.measuredHost("userns", 8, 16384, 4, store.LimitSupport{Known: true, CPU: false, Memory: true, Pids: true})
	// The probe says rootless, which picks the drop-in fix.
	host.BackendInfo[0].Rootless = true
	if err := h.st.SetHostReported(h.ctx, host); err != nil {
		t.Fatal(err)
	}

	p := h.problem(t, "host.limits_unenforceable")
	if p.Severity != config.SeverityWarning || p.TargetID != host.ID {
		t.Fatalf("problem = %+v", p)
	}
	if !strings.Contains(p.Detail, "rootless docker daemon on userns") || !strings.Contains(p.Detail, "CPU quota") || strings.Contains(p.Detail, "memory limit") {
		t.Errorf("detail %q should name the daemon and the one limit it cannot apply", p.Detail)
	}
	if !strings.Contains(p.Fix, "Delegate=cpu cpuset io memory pids") {
		t.Errorf("fix %q does not name the systemd delegation", p.Fix)
	}
	if contains(h.problemCodes(), "host.limits_unverified") {
		t.Error("a daemon that answered the probe is also reported as not having answered")
	}
}

// An agent too old to ask its daemon about limits is read as "default
// nothing", which is what every host did before defaults existed. That is
// worth a note while defaults are on, because it is the one reason a pool
// with no limits is still running unlimited there; with defaults off nothing
// is different about the host and there is nothing to say.
func TestAnUnverifiedProbeIsANoteOnlyWhileDefaultsAreOn(t *testing.T) {
	h := newHarness(t)
	h.measuredHost("old-probe", 8, 16384, 4, store.LimitSupport{})

	p := h.problem(t, "host.limits_unverified")
	if p.Severity != config.SeverityInfo || !strings.Contains(p.Detail, "old-probe") || !strings.Contains(p.Detail, "no default") {
		t.Fatalf("problem = %+v", p)
	}
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = false })
	if contains(h.problemCodes(), "host.limits_unverified") {
		t.Error("with defaults off an unverified probe changes nothing and should say nothing")
	}
}

// A host with room to spare in every dimension and a daemon that can apply
// everything is the host the resource model was written for, and it raises
// none of the model's problems: the drawer is for the three things wrong
// among the twenty that are right.
func TestAFullyInQuotaHostRaisesNoResourceProblem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 4
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	h.measuredHost("well-sized", 16, 65536, 4, enforcesEverything)
	// Registration admission may defer demand to the next pass. Fill the
	// host before checking its resource accounting, without depending on
	// how quickly the fake GitHub answers detached credential requests.
	for range pool.MinRunners {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
		if len(h.runners()) == pool.MinRunners {
			break
		}
	}
	if got := len(h.runners()); got != 4 {
		t.Fatalf("created %d runners, want the host full at 4", got)
	}
	for _, code := range h.problemCodes() {
		if strings.HasPrefix(code, "host.") {
			t.Errorf("a full, in-quota host raised %s", code)
		}
	}
}

// A docker-in-docker slot is two containers whatever the pool typed, and the
// machine has to be sized for both either way.
//
// This is the host from the report that started the work: twelve slots' worth
// of cores on paper, every one of them a pair in practice, a Hosts page reading
// half committed, and a daemon that stopped answering creates. A pool that
// typed its own figures was always charged for the sidecar a second time; a
// pool sized by its host used to be let off the count entirely, on the theory
// that the pair splitting one slot between them made a slot worth one runner
// like everybody else's -- but stability over performance means each half of
// that split still has to be a runner's worth, not half of one, so an
// automatic pool now makes a slot a pair too. See scheduler.ShareFloor for the
// other half of that: a slot too thin for the split is refused outright rather
// than merely counted here.
func TestADockerInDockerPoolMakesEachSlotAPairInTheOverprovisioningCount(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	// Eight cores less the floor is 7.5, so six plain runners fit and this
	// host raises nothing at all.
	h.measuredHost("builders", 8, 32768, 6, enforcesEverything)
	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; six plain slots fit this machine", codes)
	}

	p := h.pool(inst, "dind-builders")
	p.DockerMode = store.DockerDinD
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	// Sized by its host: the pair still splits one slot between them, but
	// stability over performance means each half of that slot has to clear a
	// runner's own comfortable floor, and six slots of 7.5 allocatable cores
	// does not.
	auto := h.problem(t, "host.overprovisioned")
	for _, want := range []string{"dind-builders", "docker in docker", "two containers", "without limits of its own"} {
		if !strings.Contains(auto.Detail, want) {
			t.Errorf("detail %q does not mention %q", auto.Detail, want)
		}
	}
	if strings.Contains(auto.Detail, "each given what the pool asked for") {
		t.Errorf("detail %q describes a typed charge for a pool that set none", auto.Detail)
	}
	// 7.5 cores in pairs is three, and 31.5 GB in pairs of 2 GB slots is
	// seven: the cores run out first, as they did on the real host, and the
	// same figure applies whether or not the pool typed its own limits --
	// the fix is the same slot count either way.
	if !strings.Contains(auto.Fix, "capacity to 3") {
		t.Errorf("fix %q does not name the capacity the pairs fit in", auto.Fix)
	}

	p.Resources = store.Resources{CPUs: 1, MemoryMB: 2048}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	got := h.problem(t, "host.overprovisioned")
	for _, want := range []string{"dind-builders", "docker in docker", "two containers", "each given what the pool asked for"} {
		if !strings.Contains(got.Detail, want) {
			t.Errorf("detail %q does not mention %q", got.Detail, want)
		}
	}
	if !strings.Contains(got.Fix, "capacity to 3") {
		t.Errorf("fix %q does not name the capacity the pairs fit in", got.Fix)
	}
}

// The count follows the pools, not the host alone: a dind pool that cannot
// place here says nothing about how big a slot on this host is. A pool for
// another platform is the case an operator hits first -- one arm64 dind pool
// should not re-size every amd64 host in the fleet.
func TestAPoolThatCannotPlaceHereDoesNotMakeItsSlotsPairs(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.measuredHost("builders", 8, 32768, 6, enforcesEverything)

	p := h.pool(inst, "dind-arm")
	p.DockerMode = store.DockerDinD
	p.HostSelector = store.StringMap{"arch": "arm64"}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	if codes := h.problemCodes(); contains(codes, "host.overprovisioned") {
		t.Fatalf("problems = %v; the dind pool cannot place on an amd64 host", codes)
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// An operator can see what a host is and what is left on it; without this they
// could not see what the fleet has already promised away, which is the number
// that explains a host with free slots taking nothing.
//
// It is the scheduler's own sum rather than a second one computed for the page:
// a figure on screen that disagreed with the one the pass placed against would
// be worse than no figure, because it would be believed.
func TestTheHostViewCarriesWhatTheFleetHasPromisedAway(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.Resources = store.Resources{CPUs: 2, MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	host := h.host("vm-1")
	h.runnerRow(pool, host, store.RunnerIdle)
	h.runnerRow(pool, host, store.RunnerBusy)
	// A failed runner is not charged for, exactly as it does not hold a slot.
	failed := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, failed.ID, store.RunnerFailed, "failed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	// Before a pass has run there is no answer, and saying zero would read as
	// an idle machine rather than as a question nobody has asked yet.
	if view := h.c.HostView(host); view.ReservedKnown {
		t.Error("a controller that has decided nothing reported a reservation anyway")
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	view := h.c.HostView(host)
	if !view.ReservedKnown {
		t.Fatal("a pass has run and the host still reports no reservation")
	}
	if view.ReservedCPUs != 4 || view.ReservedMemoryMB != 8192 {
		t.Errorf("reserved = %v CPUs / %d MB, want the two live runners' 4 and 8192 (the failed one is not charged)",
			view.ReservedCPUs, view.ReservedMemoryMB)
	}
	if !view.ResourcesKnown {
		t.Error("a host that reported its machine says its resources are unknown")
	}
	// The memory reserve scales with the machine, so a 64 GB host holds back a
	// twentieth rather than the flat floor a small one does.
	if want := int64(64*1024) - (&store.Host{MemoryMB: 64 * 1024}).MemoryReserve(); view.AllocatableMemoryMB != want {
		t.Errorf("allocatable memory = %d, want the machine less its reserve, %d", view.AllocatableMemoryMB, want)
	}
}

// A host whose agent predates the resource fields is placed by slots alone,
// which is what keeps an upgrade from emptying a fleet -- and the page has to
// say so, because a card with every figure missing reads as broken rather than
// as old.
//
// How loudly it says so depends on what the fleet does with a measurement.
// With default limits on, an unmeasured host is the one host whose runners
// get no default -- their share of a machine nobody has measured cannot be
// computed -- so a pool with no limits of its own runs unlimited there, and
// that is a warning. With defaults off nothing is different about the host and
// it stays a note.
func TestAHostThatHasNotMeasuredItselfSaysSo(t *testing.T) {
	h := newHarness(t)
	silent := &store.Host{Name: "old-agent", Capacity: 2, Backends: store.StringSlice{"docker"},
		Labels: store.StringMap{}, OS: "linux", Arch: "amd64", LastHeartbeat: h.c.Now()}
	if err := h.st.CreateHost(h.ctx, silent); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}

	if h.c.HostView(silent).ResourcesKnown {
		t.Error("a host that has reported nothing claims its resources are known")
	}
	for _, tc := range []struct {
		defaults bool
		want     string
		because  string
	}{
		{true, "warning", "its runners are given no default limit, so a pool without limits runs unlimited there"},
		{false, "info", "nothing is wrong with an old agent, it is just unmeasured"},
	} {
		h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.DefaultRunnerLimits = tc.defaults })
		p := h.problem(t, "host.resources_unknown")
		if !strings.Contains(p.Detail, "old-agent") {
			t.Errorf("the note does not name the host: %q", p.Detail)
		}
		if string(p.Severity) != tc.want {
			t.Errorf("defaults=%v: severity = %q, want %s: %s", tc.defaults, p.Severity, tc.want, tc.because)
		}
		if tc.defaults && !strings.Contains(p.Detail, "no default") {
			t.Errorf("with defaults on the detail does not say the runners get none: %q", p.Detail)
		}
	}
}

// A pool's resources become cgroup limits on the container backends and
// nothing at all on the process backend. The reservation still holds the room,
// so the fleet does not oversubscribe -- but the room is bookkeeping, and
// saying so is the difference between a limit and a wish.
func TestAProcessPoolWithLimitsIsWarnedAbout(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "on-metal")
	pool.Backend = store.BackendProcess
	pool.Resources = store.Resources{MemoryMB: 4096}
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	if !contains(h.problemCodes(), "pool.resources_unenforced") {
		t.Fatalf("problems = %v, want pool.resources_unenforced", h.problemCodes())
	}

	// The same pool on a backend that enforces them raises nothing: the
	// warning is about the backend, not about setting limits.
	pool.Backend = store.BackendDocker
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if contains(h.problemCodes(), "pool.resources_unenforced") {
		t.Errorf("problems = %v; a docker pool enforces its limits and needs no warning", h.problemCodes())
	}
}

// The UI tells two problems apart by code, target and setting, and dismisses
// or snoozes by that identity. Two process pools with limits used to raise two
// problems that shared all three (with no target at all), so muting one pool's
// warning muted the other's and neither got an "Open the pool" link.
func TestTwoProcessPoolsWithLimitsAreTwoProblemsWithTheirOwnTargets(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	want := map[string]string{}
	for _, name := range []string{"on-metal", "on-metal-too"} {
		pool := h.pool(inst, name)
		pool.Backend = store.BackendProcess
		pool.Resources = store.Resources{MemoryMB: 4096}
		if err := h.st.UpdatePool(h.ctx, pool); err != nil {
			t.Fatalf("UpdatePool: %v", err)
		}
		want[pool.ID] = name
	}

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	seen := map[string]bool{}
	for _, p := range ps {
		if p.Code != "pool.resources_unenforced" {
			continue
		}
		name, ok := want[p.TargetID]
		if !ok || p.TargetKind != "pool" {
			t.Errorf("problem targets %s %q, want one of the pools %v", p.TargetKind, p.TargetID, want)
			continue
		}
		if seen[p.TargetID] {
			t.Errorf("two problems target pool %s", p.TargetID)
		}
		seen[p.TargetID] = true
		if !strings.Contains(p.Title, name) {
			t.Errorf("title %q does not name pool %s, so the drawer cannot tell its rows apart", p.Title, name)
		}
	}
	if len(seen) != len(want) {
		t.Errorf("problems cover pools %v, want %v", seen, want)
	}
}

// A host whose docker and podman daemons both have something wrong raises one
// problem per backend for the same host. The UI keys a drawer row by code,
// target and title, so the titles have to differ or the two rows collide.
func TestAHostWithTwoAffectedBackendsRaisesProblemsWithDistinctTitles(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	for _, kind := range []store.BackendKind{store.BackendDocker, store.BackendPodman} {
		p := h.pool(inst, "cached-"+string(kind))
		p.Backend = kind
		p.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
		if err := h.st.UpdatePool(h.ctx, p); err != nil {
			t.Fatalf("UpdatePool: %v", err)
		}
	}
	limits := store.LimitSupport{Known: true, CPU: false, Memory: true, Pids: true}
	host := h.measuredHost("both", 16, 65536, 4, limits)
	host.Backends = store.StringSlice{"docker", "podman"}
	host.BackendInfo = store.HostBackends{
		{Kind: store.BackendDocker, Available: true, SharedFolder: "the shared folder is not mounted", Limits: limits},
		{Kind: store.BackendPodman, Available: true, SharedFolder: "the shared folder is not mounted", Limits: limits},
	}
	if err := h.st.SetHostReported(h.ctx, host); err != nil {
		t.Fatal(err)
	}

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, code := range []string{"host.limits_unenforceable", "host.shared_folder_unmounted"} {
		titles := map[string]bool{}
		n := 0
		for _, p := range ps {
			if p.Code == code {
				n++
				titles[p.Title] = true
			}
		}
		if n != 2 || len(titles) != 2 {
			t.Errorf("%s: %d problems with %d distinct titles, want two of each", code, n, len(titles))
		}
	}
}

