)

func TestHeartbeatUsageReachesPlacementViewsAndMetrics(t *testing.T) {
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()
	joined, err := tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "shared-host", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true}}})
	if err != nil {
		t.Fatal(err)
	}
	tr.SetCredentials(joined.HostID, joined.AgentToken)
	cpu, memory := 99.0, int64(8192)
	beat := func() *store.Host {
		t.Helper()
		if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{Usage: &store.HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &memory}}); err != nil {
			t.Fatal(err)
		}
		host, err := h.st.GetHost(h.ctx, joined.HostID)
		if err != nil {
			t.Fatal(err)
		}
		return host
	}
	if host := beat(); !scheduler.HostAvailable(host, h.c.Now()) {
		t.Fatal("one spike held the host")
	}
	h.advance(31 * time.Second)
	host := beat()
	view := h.c.HostView(host)
	if !host.Healthy(h.c.Now()) || scheduler.HostAvailable(host, h.c.Now()) || !view.UsageFresh || !strings.Contains(view.AdmissionReason, "CPU") {
		t.Fatalf("connected and pressure-held were conflated: %+v", view)
	}
	for name, want := range map[string]float64{
		"zoomies_host_cpu_usage_percent":      99,
		"zoomies_host_memory_available_bytes": 8192 * (1 << 20),
		"zoomies_host_admission_held":         1,
		"zoomies_host_usage_fresh":            1,
	} {
		if got, ok := gatherValue(t, h.c, name, map[string]string{"host": host.ID}); !ok || got != want {
			t.Fatalf("%s = %v (%v), want %v", name, got, ok, want)
		}
	}
	// An older peer omits usage. It must not restamp the old reading as fresh.
	h.advance(store.HostUsageMaxAge)
	if _, err := tr.Heartbeat(h.ctx, agent.HeartbeatRequest{}); err != nil {
		t.Fatal(err)
	}
	host, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if h.c.HostView(host).UsageFresh {
		t.Fatal("heartbeat freshened an omitted usage sample")
	}
	if _, ok := gatherValue(t, h.c, "zoomies_host_cpu_usage_percent", map[string]string{"host": host.ID}); ok {
		t.Fatal("stale CPU still exported as current")
	}
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	cpu = 20
	host = beat()
	if host.Usage.CPUHeld || !host.Cordoned || scheduler.HostAvailable(host, h.c.Now()) {
		t.Fatal("CPU recovery undid the operator's cordon")
	}
}

package controller

import (
	"context"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// HostFit is what the pool wizard asks before a pool exists: how many hosts
// could run it as configured, and, when none can, the first host's own account
// of why and the backends those hosts do offer.
//
// Zero is worth saying out loud before a pool is created: a pool whose
// selector matches nothing looks completely healthy and never starts a runner.
// The explanation matters as much as the count, because the usual cause is not
// a missing machine but a daemon the agent on an existing one could not reach,
// and the backends those same hosts do offer are the other way out.
type HostFit struct {
	Count  int
	Detail string
	// Alternatives are the backends offered by the hosts that match this pool
	// in every way except its backend, in the order a pool would move to them.
	// The wizard turns them into the second half of its warning, in the same
	// words the scheduler uses once the pool is real.
	Alternatives []string
	// PlatformMismatch counts the hosts that fit in every other way but are
	// not the machine the pool asked for. It is called out separately because
	// it is the one mismatch no backend change can fix: the answer is a
	// different host, or a different platform on the pool.
	PlatformMismatch int
	// Selected is how many hosts the pool's host selector reaches at all,
	// whatever became of them afterwards. It is the number the wizard's
	// placement step shows while a selector is being typed, and Count is the
	// number its review step shows -- so when the two differ, something
	// happened between them that an operator has to be told about.
	Selected int
	// Excluded is that difference, host by host: everything the selector
	// reaches and the fleet cannot run, with the reason in the operator's
	// terms. It is what turns "2 hosts match" followed by "1 host can run
	// this pool" from a contradiction into an explanation.
	Excluded []HostExclusion
	// Reduced are hosts that can run the pool, counted in Count, where its
	// runners get less than they would on a larger machine: the pool's
	// minimum is doing its job there. It is information for the wizard to
	// show as such -- a host listed here is not a problem with the pool.
	Reduced []HostExclusion
}

// HostExclusion is one host a pool's selector reaches that could not run it,
// and why. The reason is a sentence about the host with the host's name left
// out, so a caller can put the name where its own layout wants it.
type HostExclusion struct {
	Host string `json:"host"`
	// Code is which of the placement rules turned this host down, for a caller
	// that wants to group or colour them: unavailable, backend, platform, size.
	Code   string `json:"code"`
	Reason string `json:"reason"`
}

// The reasons a host cannot run the pool. HostFit never returns the first of
// them -- a host the selector does not reach is not counted as excluded there,
// because the pool never asked for it -- but an edit that takes a label off a
// host is exactly that rule being failed, and it needs a name for the same
// reasons the others have one.
const (
	ExcludedSelector    = "selector"
	ExcludedUnavailable = "unavailable"
	ExcludedBackend     = "backend"
	ExcludedPlatform    = "platform"
	ExcludedSize        = "size"
	// ReducedSize is not an exclusion: it marks a host in HostFit.Reduced.
	ReducedSize = "reduced"
)

// HostFit counts the hosts that could run a pool, using the scheduler's own
// placement rule so the wizard can never disagree with the fleet.
func (c *Controller) HostFit(ctx context.Context, p *store.Pool) (HostFit, error) {
	p = sizingPool(p, c.cfg().Runners)
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return HostFit{}, err
	}
	now := c.Now()
	fit := HostFit{}
	offered := map[string]int{}
	for _, h := range hosts {
		if !scheduler.HostSelects(h, p) {
			continue
		}
		fit.Selected++
		exclude := func(code, reason string) {
			fit.Excluded = append(fit.Excluded, HostExclusion{Host: h.Name, Code: code, Reason: reason})
		}
		// A host that is there and not taking work is still an answer to
		// "where did my other host go", so it is excluded with a reason rather
		// than passed over. The order below is the scheduler's own, so the
		// reason given is the first rule the host actually failed.
		if !scheduler.HostAvailable(h, now) {
			exclude(ExcludedUnavailable, unavailableReason(h, now))
			continue
		}
		for _, kind := range h.Backends {
			if kind != string(p.Backend) {
				offered[kind]++
			}
		}
		// The remaining rules are the ones an edit can break too, so their
		// sentences are HostRefusal's and are written once. A host that could
		// never hold one runner of this pool cannot run it, and saying so
		// before the pool exists is the whole point of the wizard's count.
		code, reason := HostRefusal(h, p)
		switch code {
		case ExcludedBackend:
			if info, ok := h.BackendInfo.Find(p.Backend); ok && !info.Available && info.Detail != "" && fit.Detail == "" {
				fit.Detail = h.Name + " reports: " + info.Detail
			}
		case ExcludedPlatform:
			fit.PlatformMismatch++
		case ExcludedSize:
			if fit.Detail == "" {
				fit.Detail = h.Name + " cannot run it: " + reason + "."
			}
		}
		if code != "" {
			exclude(code, reason)
			continue
		}
		fit.Count++
		if note := scheduler.HostReduction(h, p); note != "" {
			fit.Reduced = append(fit.Reduced, HostExclusion{Host: h.Name, Code: ReducedSize, Reason: note})
		}
	}
	for _, kind := range []store.BackendKind{store.BackendDocker, store.BackendPodman, store.BackendProcess} {
		if offered[string(kind)] > 0 {
			fit.Alternatives = append(fit.Alternatives, string(kind))
		}
	}
	return fit, nil
}

// unavailableReason says which of the ways a host takes no new runner it is
// in. They read alike on a Hosts page and are different jobs: wait for an
// agent, uncordon a machine, wait out a pressure hold or a throttle, upgrade a
// release. The order is the scheduler's own, so the reason given is the first
// rule the host actually failed; the incompatible agent is last because it
// used to be the default answer for every host that failed for a reason this
// function had no case for, and a held host was told to upgrade its agent.
func unavailableReason(h *store.Host, now time.Time) string {
	switch {
	case !h.Healthy(now):
		return "it is not heartbeating, so nothing is placed there until its agent checks in again"
	case h.Cordoned:
		return "it is cordoned, so it takes no new runners until it is uncordoned"
	case h.Incompatible:
		return "its agent speaks a protocol this controller does not, so it takes no new runners until it is upgraded"
	case scheduler.HostAdmissionReason(h, now) != "":
		return "it is under pressure: " + scheduler.HostAdmissionReason(h, now)
	case h.Throttle.Active() && h.ActiveRunners >= h.EffectiveCapacity():
		return fmt.Sprintf("it is throttled to %d of its %d slots after sustained pressure and every one of them is in use; the throttle lifts one step after %s of calm, or an operator can clear it once the cause is fixed",
			h.EffectiveCapacity(), h.Capacity, scheduler.FormatDuration(scheduler.ThrottleRecovery))
	default:
		return "it takes no new runners right now"
	}
}

// platformReason names both machines, because the fix is a different host or a
// different pool and an operator cannot choose between them without the pair.
func platformReason(h *store.Host, p *store.Pool) string {
	has := h.Platform().Describe()
	if has == "" {
		has = "an unreported platform"
	}
	return "it is running " + has + ", and this pool asks for " + p.Platform.Describe()
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The whole point of the refresh: a pool is created once and then nothing
// touches it again, so without this pass the image its hosts pulled on the
// first job is the image they keep, however many times the tag has moved.
func TestRefreshPoolImagesPrewarmsEveryPoolAgain(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	h.c.refreshPoolImages(h.ctx)

	task := h.taskOfKind(host.ID, agent.TaskPrewarmImage)
	if task.PoolID != pool.ID {
		t.Fatalf("prewarm task pool = %q, want %q", task.PoolID, pool.ID)
	}
	if task.Image != pool.Image {
		t.Fatalf("prewarm image = %q, want %q", task.Image, pool.Image)
	}
}

// A process-backend pool has no image to pull -- its runners fetch the
// actions/runner archive themselves -- so PrewarmPool refuses it. The refusal
// is expected and must not be logged as a failure or stop the pools after it
// from being refreshed.
func TestRefreshPoolImagesSkipsProcessPoolsAndKeepsGoing(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	proc := h.pool(inst, "bare-metal")
	proc.Backend = store.BackendProcess
	if err := h.st.UpdatePool(h.ctx, proc); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	container := h.pool(inst, "linux-x64")
	host := h.host("vm-1")

	h.c.refreshPoolImages(h.ctx)

	var seen []string
	for _, task := range h.tasksFor(host.ID) {
		if task.Kind == agent.TaskPrewarmImage {
			seen = append(seen, task.PoolID)
		}
	}
	if len(seen) != 1 || seen[0] != container.ID {
		t.Fatalf("prewarmed pools = %v, want only the container pool %q", seen, container.ID)
	}
}

// Refreshing is not a scheduling decision and must never look like one: it
// queues its own idempotent task kind and creates no runners.
func TestRefreshPoolImagesCreatesNoRunners(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	h.c.refreshPoolImages(h.ctx)

	if got := h.runners(); len(got) != 0 {
		t.Fatalf("runners = %d, want 0: the refresh must not scale the fleet", len(got))
	}
}

package controller

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// maxIncidentError bounds what an agent's error may put on the host row and
// the Hosts page. The agent bounds it too; an agent is not trusted to.
const maxIncidentError = 500

// maxRuntimeRetry is the longest retry an agent's report is believed about.
// The agent's own ceiling is a minute plus jitter; anything past this is an
// agent reporting nonsense, and a retry time an hour out would read as a host
// nobody needs to look at.
const maxRuntimeRetry = 5 * time.Minute

// noteRuntime folds the heartbeat's runtime report into the host row.
//
// It writes only when the report says something new -- a first failure, a
// further one, a different kind, or a recovery -- so a host sitting in a
// cooldown for a minute costs one write rather than one per beat, and the
// times on the row are when the controller learnt each thing rather than
// when it last happened to be told again.
//
// A beat with no report clears it. That is a healthy runtime from this
// release, and from an agent too old to send one it is the only thing the
// controller has ever known about that host's runtime.
func (c *Controller) noteRuntime(ctx context.Context, h *store.Host, rep *agent.RuntimeReport, now time.Time) {
	was := h.Incidents.Runtime
	if rep == nil || rep.Failures <= 0 {
		if was == nil {
			return
		}
		if err := c.st.SetHostRuntimeIncident(ctx, h.ID, nil); err != nil {
			c.log.Warn("could not clear a host's runtime incident", "host", h.ID, "error", err)
			return
		}
		h.Incidents.Runtime = nil
		c.log.Info("a host's container runtime has recovered", "host", h.ID, "name", h.Name,
			"after_failures", was.Failures, "since", was.Since)
		c.publishHost(h)
		return
	}
	kind := rep.Kind
	if kind != agent.RuntimeTimeout {
		kind = agent.RuntimeUnavailable
	}
	failures := min(rep.Failures, 99)
	if was != nil && was.Failures == failures && was.Kind == kind {
		return
	}
	inc := &store.RuntimeIncident{
		Failures:   failures,
		Kind:       kind,
		Error:      truncateIncident(rep.Error),
		RetryAt:    now.Add(min(max(rep.RetryIn, 0), maxRuntimeRetry)),
		Since:      now,
		ObservedAt: now,
	}
	added := failures
	if was != nil {
		inc.Since = was.Since
		added = max(failures-was.Failures, 0)
	}
	if err := c.st.SetHostRuntimeIncident(ctx, h.ID, inc); err != nil {
		c.log.Warn("could not record a host's runtime incident", "host", h.ID, "error", err)
		return
	}
	h.Incidents.Runtime = inc
	if added > 0 {
		c.metrics.runtimeFailures.WithLabelValues(kind).Add(float64(added))
	}
	c.log.Warn("a host's container runtime failed; its agent is holding new starts before one recovery attempt",
		"host", h.ID, "name", h.Name, "consecutive_failures", failures, "kind", kind,
		"retry_at", inc.RetryAt, "error", inc.Error)
	c.publishHost(h)
}

// noteImagePull records a start or prewarm that failed because its image
// could not be made ready, or clears the record when the same pool's image is
// made ready on the same host.
//
// It is recorded from the task results the agent already sends, because the
// failed runner itself is cleaned up within minutes; before this, a host
// whose egress blocked a registry showed nothing but runners that never
// registered.
func (c *Controller) noteImagePull(ctx context.Context, hostID, poolID, image, source string, ok bool, fault store.FaultKind, message string) {
	if hostID == "" || poolID == "" {
		return
	}
	if !ok && fault != store.FaultImage {
		return
	}
	h, err := c.st.GetHost(ctx, hostID)
	if err != nil {
		return
	}
	was := h.Incidents.ImagePull
	now := c.Now()
	if ok {
		// Only the pool that failed clears it: another pool's image being
		// fine says nothing about a registry this one cannot reach.
		if was == nil || was.PoolID != poolID {
			return
		}
		if err := c.st.SetHostImagePullIncident(ctx, hostID, nil); err != nil {
			c.log.Warn("could not clear a host's image pull incident", "host", hostID, "error", err)
			return
		}
		h.Incidents.ImagePull = nil
		c.log.Info("a pool's image is pulling on this host again", "host", hostID, "pool", poolID, "registry", was.Registry)
		c.publishHost(h)
		return
	}
	pool := poolID
	if p, err := c.st.GetPool(ctx, poolID); err == nil {
		pool = p.Name
		if image == "" {
			image = p.Image
		}
	}
	inc := &store.ImagePullIncident{
		PoolID:     poolID,
		Pool:       pool,
		Image:      image,
		Registry:   backend.RegistryHost(image),
		Source:     source,
		Error:      truncateIncident(message),
		Since:      now,
		ObservedAt: now,
	}
	if was != nil && was.PoolID == poolID && was.Image == image {
		inc.Since = was.Since
	}
	if err := c.st.SetHostImagePullIncident(ctx, hostID, inc); err != nil {
		c.log.Warn("could not record a host's image pull incident", "host", hostID, "error", err)
		return
	}
	h.Incidents.ImagePull = inc
	c.metrics.imagePullFailures.WithLabelValues(c.poolLabel(poolID), source).Inc()
	c.log.Warn("a host could not pull a pool's image", "host", hostID, "name", h.Name,
		"pool", pool, "image", image, "registry", inc.Registry, "source", source, "error", inc.Error)
	c.publishHost(h)
}

func truncateIncident(s string) string {
	r := []rune(strings.TrimSpace(s))
	if len(r) <= maxIncidentError {
		return string(r)
	}
	return string(r[:maxIncidentError]) + "..."
}

// ordinalFailure is "third failure", the way the card says it. The agent
// counts no higher than five, so five is "at least the fifth".
func ordinalFailure(n int) string {
	words := []string{"first", "second", "third", "fourth"}
	switch {
	case n >= 1 && n <= len(words):
		return words[n-1] + " failure"
	case n == 5:
		return "fifth failure or later"
	default:
		return fmt.Sprintf("failure %d", n)
	}
}

// runtimeReason is the incident as the host card's sentence, without its
// times: the card renders the retry and the age against the viewer's clock,
// so the sentence stays true while the page is open.
func runtimeReason(inc *store.RuntimeIncident) string {
	if inc == nil {
		return ""
	}
	what := "the container runtime could not be reached"
	if inc.Kind == agent.RuntimeTimeout {
		what = "the container runtime did not answer in time"
	}
	return fmt.Sprintf("Runtime recovering: %s in a row, %s. New starts here are held until one recovery attempt; running jobs continue.",
		ordinalFailure(inc.Failures), what)
}

// runtimeFix is the fix the agent itself would give, by kind: a daemon that
// is not there is started on the host, and one that is there but slow is
// relieved of load.
func runtimeFix(hostName string, inc *store.RuntimeIncident) string {
	if inc.Kind == agent.RuntimeTimeout {
		return fmt.Sprintf("the runtime on %s is running but not answering in time: check its load and its disk "+
			"(`docker info`, `df -h /var/lib/docker`), and lower the host's capacity if it carries more than the machine can. "+
			"The agent retries by itself, and this clears on the next start that succeeds.", hostName)
	}
	return fmt.Sprintf("start the container runtime on %s, or give the agent's user access to its socket -- the error names "+
		"the socket and how to start it (for Docker, `sudo systemctl start docker`). "+
		"The agent retries by itself, and this clears on the next start that succeeds.", hostName)
}

func incidentTime(t time.Time) string { return t.UTC().Format("15:04:05 UTC") }

// hostIncidentProblems names each host whose runtime is recovering and each
// host that could not pull a pool's image, from what is stored on the host
// row -- so a controller that restarts in the middle of either still says so.
//
// The times in them are absolute rather than "in 40 s": the list is sent only
// when it changes, and a sentence counting down would be wrong by the time it
// was read. The card counts down against the viewer's own clock instead.
func (c *Controller) hostIncidentProblems(ctx context.Context, out *[]Problem) error {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return fmt.Errorf("listing hosts: %w", err)
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return fmt.Errorf("listing pools: %w", err)
	}
	live := make(map[string]bool, len(pools))
	for _, p := range pools {
		live[p.ID] = true
	}
	for _, h := range hosts {
		if inc := h.Incidents.Runtime; inc != nil {
			since := inc.Since
			detail := fmt.Sprintf("%s's agent reported its %s in a row at %s and holds new starts until one recovery attempt at %s. "+
				"Running jobs continue.", h.Name, ordinalFailure(inc.Failures), incidentTime(inc.ObservedAt), incidentTime(inc.RetryAt))
			if inc.Error != "" {
				detail += " The last error: " + inc.Error
			}
			*out = append(*out, Problem{
				Code:     "host.runtime_recovering",
				Severity: config.SeverityWarning,
				Title:    fmt.Sprintf("the container runtime on %s is recovering after its %s", h.Name, ordinalFailure(inc.Failures)),
				Detail:   detail,
				Fix:      runtimeFix(h.Name, inc),
				// Since is when the controller first heard of it; the
				// detail carries when it last heard anything new.
				TargetKind: "host", TargetID: h.ID, Since: &since,
			})
		}
		if inc := h.Incidents.ImagePull; inc != nil && live[inc.PoolID] {
			since := inc.Since
			what := "a runner start"
			if inc.Source == "prewarm" {
				what = "a prewarm"
			}
			detail := fmt.Sprintf("%s of %s for pool %s failed on %s at %s because the image could not be made ready. "+
				"Every runner that pool places on this host fails the same way until it can.",
				what, inc.Image, inc.Pool, h.Name, incidentTime(inc.ObservedAt))
			if inc.Error != "" {
				detail += " The error: " + inc.Error
			}
			*out = append(*out, Problem{
				Code:     "host.image_pull_failed",
				Severity: config.SeverityWarning,
				Title:    fmt.Sprintf("%s cannot pull pool %s's image from %s", h.Name, inc.Pool, inc.Registry),
				Detail:   detail,
				Fix: fmt.Sprintf("check that %s can reach %s -- its egress rules, proxy and DNS -- and is logged in to it if the image "+
					"is private (`docker pull %s` on the host gives the daemon's own answer), and that the pool's image and tag exist. "+
					"This clears on the next start or prewarm of %s that succeeds on this host.", h.Name, inc.Registry, inc.Image, inc.Pool),
				TargetKind: "host", TargetID: h.ID, Since: &since,
			})
		}
	}
	return nil
}

package controller

import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func (h *harness) reread(t *testing.T, id string) *store.Host {
	t.Helper()
	host, err := h.st.GetHost(h.ctx, id)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	return host
}

func (h *harness) beat(t *testing.T, id string, rt *agent.RuntimeReport) {
	t.Helper()
	if _, err := h.c.Heartbeat(h.ctx, id, agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Runtime: rt}); err != nil {
		t.Fatalf("Heartbeat: %v", err)
	}
}

func hasCode(codes []string, code string) bool {
	for _, c := range codes {
		if c == code {
			return true
		}
	}
	return false
}

// A runtime that keeps falling over used to be a log line on the host, and
// the Hosts page showed a healthy machine that was oddly slow to start
// runners. One beat is enough to put it on the card and in the drawer, with
// when the recovery attempt is due, and a controller restart does not lose it.
func TestAHeartbeatCarryingARuntimeCooldownIsShownUntilASuccessClearsIt(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()

	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 3, Kind: agent.RuntimeUnavailable,
		Error: "backend: not available on this host: no socket at /var/run/docker.sock", RetryIn: 40 * time.Second})
	beatAt := h.c.Now()

	view := h.c.HostView(h.reread(t, host.ID))
	inc := view.RuntimeRecovering
	if inc == nil {
		t.Fatal("the host view does not carry the runtime cooldown")
	}
	if inc.Failures != 3 || inc.Kind != agent.RuntimeUnavailable {
		t.Fatalf("recorded %+v, want three unavailable failures", inc)
	}
	// The retry is on the controller's clock, forty seconds from the beat.
	if d := inc.RetryAt.Sub(beatAt); d < 39*time.Second || d > 41*time.Second {
		t.Fatalf("retry at %s is %s after the beat, want about 40s", inc.RetryAt, d)
	}
	if inc.ObservedAt.IsZero() || inc.Since.IsZero() {
		t.Fatalf("the incident carries no age: %+v", inc)
	}
	if !strings.Contains(view.RuntimeReason, "third failure") {
		t.Fatalf("the card's sentence does not say which failure this is: %q", view.RuntimeReason)
	}
	p := h.problem(t, "host.runtime_recovering")
	if p.TargetID != host.ID || p.Since == nil || !strings.Contains(p.Detail, incidentTime(inc.RetryAt)) ||
		!strings.Contains(p.Fix, "systemctl start docker") || p.Audience != AudienceFleet {
		t.Fatalf("the drawer entry does not name the host, its age, the retry time and the fix: %+v", p)
	}
	if got, ok := gatherValue(t, h.c, "zoomies_host_runtime_recovering", map[string]string{"host": host.ID}); !ok || got != 1 {
		t.Fatalf("zoomies_host_runtime_recovering = %v (%v), want 1", got, ok)
	}
	if got, ok := gatherValue(t, h.c, "zoomies_host_runtime_failures_total", map[string]string{"kind": "unavailable"}); !ok || got != 3 {
		t.Fatalf("zoomies_host_runtime_failures_total = %v (%v), want 3", got, ok)
	}

	// The same report again is not news: the row keeps when it was learnt.
	h.advance(10 * time.Second)
	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 3, Kind: agent.RuntimeUnavailable, RetryIn: 30 * time.Second})
	if again := h.reread(t, host.ID).Incidents.Runtime; again == nil || !again.ObservedAt.Equal(inc.ObservedAt) {
		t.Fatalf("a beat with nothing new rewrote the incident: %+v", again)
	}

	// The controller restarts: the row is all that is left, and it is enough.
	h.c = h.restart()
	if !hasCode(h.problemCodes(), "host.runtime_recovering") {
		t.Fatal("a controller restart lost the runtime cooldown")
	}

	// A further failure moves it on and keeps when the episode began.
	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 4, Kind: agent.RuntimeUnavailable, RetryIn: time.Minute})
	next := h.reread(t, host.ID).Incidents.Runtime
	if next == nil || next.Failures != 4 || !next.Since.Equal(inc.Since) {
		t.Fatalf("a fourth failure was recorded as %+v", next)
	}
	// And a different kind of failure is news even at the same count.
	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 4, Kind: agent.RuntimeTimeout, RetryIn: time.Minute})
	if next := h.reread(t, host.ID).Incidents.Runtime; next == nil || next.Kind != agent.RuntimeTimeout {
		t.Fatalf("a slow daemon after an absent one was recorded as %+v", next)
	}
	if fix := h.problem(t, "host.runtime_recovering").Fix; !strings.Contains(fix, "not answering in time") {
		t.Fatalf("a slow daemon was given the fix for a missing one: %q", fix)
	}

	// The next beat without a report is the runtime working again.
	h.beat(t, host.ID, nil)
	if got := h.reread(t, host.ID); got.Incidents.Runtime != nil || h.c.HostView(got).RuntimeRecovering != nil {
		t.Fatalf("a recovered runtime is still shown: %+v", got.Incidents.Runtime)
	}
	if hasCode(h.problemCodes(), "host.runtime_recovering") {
		t.Fatal("a recovered runtime is still in the drawer")
	}
}

// An agent is not trusted with the retry time any more than with its clock: a
// report of an hour's wait would read as a host nobody need look at.
func TestARuntimeReportIsBoundedBeforeItIsStored(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 1, Kind: "gremlins", RetryIn: 10 * time.Hour,
		Error: strings.Repeat("x", 10*maxIncidentError)})
	inc := h.reread(t, host.ID).Incidents.Runtime
	if inc == nil {
		t.Fatal("the report was dropped")
	}
	if inc.Kind != agent.RuntimeUnavailable {
		t.Errorf("an unknown kind was stored as %q", inc.Kind)
	}
	if d := inc.RetryAt.Sub(inc.ObservedAt); d > maxRuntimeRetry {
		t.Errorf("a retry %s out was believed", d)
	}
	if n := len([]rune(inc.Error)); n > maxIncidentError+3 {
		t.Errorf("a %d-rune error was stored", n)
	}
}

// An image that will not pull used to reach the controller only as a failed
// runner, cleaned up within minutes; a host whose egress blocked the registry
// showed nothing but runners that never registered. One failed start is
// enough to name the registry and the pool.
func TestAStartThatCannotPullItsImageNamesTheRegistryAndThePool(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: "zoomies-pull-1",
		State: store.RunnerProvisioning, Ephemeral: true, Labels: pool.Labels}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "t1", Kind: agent.TaskCreateRunner, RunnerID: r.ID, OK: false, Fault: store.FaultImage,
		Error: "backend: pulling ghcr.io/eyupio/zoomies-runner:test: dial tcp: i/o timeout",
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	view := h.c.HostView(h.reread(t, host.ID))
	inc := view.ImagePullFailed
	if inc == nil || inc.Registry != "ghcr.io" || inc.Pool != pool.Name || inc.Source != "start" || inc.ObservedAt.IsZero() {
		t.Fatalf("the host view carries %+v, want ghcr.io and pool %s from a start", inc, pool.Name)
	}
	p := h.problem(t, "host.image_pull_failed")
	if !strings.Contains(p.Title, "ghcr.io") || !strings.Contains(p.Title, pool.Name) || p.TargetID != host.ID || p.Since == nil {
		t.Fatalf("the drawer entry does not name the registry, the pool and the host: %+v", p)
	}
	if got, ok := gatherValue(t, h.c, "zoomies_image_pull_failures_total", map[string]string{"pool": pool.Name, "kind": "start"}); !ok || got != 1 {
		t.Fatalf("zoomies_image_pull_failures_total = %v (%v), want 1", got, ok)
	}

	h.c = h.restart()
	if !hasCode(h.problemCodes(), "host.image_pull_failed") {
		t.Fatal("a controller restart lost the image pull failure")
	}

	// A prewarm of the same pool that succeeds is the image pulling again.
	if n, err := h.c.PrewarmPool(h.ctx, pool); err != nil || n != 1 {
		t.Fatalf("PrewarmPool = %d, %v", n, err)
	}
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks = %+v, %v", batch, err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: batch.Tasks[0].ID, Kind: agent.TaskPrewarmImage, OK: true}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if got := h.reread(t, host.ID).Incidents.ImagePull; got != nil {
		t.Fatalf("a successful prewarm did not clear the incident: %+v", got)
	}
}

// Only an image fault is an image fault. A start the daemon refused for any
// other reason is a different sentence with a different fix, and naming a
// registry for it would send an operator to a firewall that is not the cause.
func TestOnlyAnImageFaultIsRecordedAsAnImagePullFailure(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	if n, err := h.c.PrewarmPool(h.ctx, pool); err != nil || n != 1 {
		t.Fatalf("PrewarmPool = %d, %v", n, err)
	}
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks = %+v, %v", batch, err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: batch.Tasks[0].ID, Kind: agent.TaskPrewarmImage,
		OK: false, Fault: store.FaultBackend, Error: "the daemon said no"}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if got := h.reread(t, host.ID).Incidents.ImagePull; got != nil {
		t.Fatalf("a backend fault was recorded as an image pull failure: %+v", got)
	}
}

// The event stream renders the same view the API does, so the new fields have
// to be there under the names the UI reads.
func TestTheHostViewCarriesIncidentsUnderTheirAPINames(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	h.beat(t, host.ID, &agent.RuntimeReport{Failures: 1, Kind: agent.RuntimeTimeout, RetryIn: 5 * time.Second})
	raw, err := json.Marshal(h.c.HostView(h.reread(t, host.ID)))
	if err != nil {
		t.Fatal(err)
	}
	var got map[string]any
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatal(err)
	}
	rr, ok := got["runtime_recovering"].(map[string]any)
	if !ok {
		t.Fatalf("no runtime_recovering in %s", raw)
	}
	for _, key := range []string{"failures", "kind", "retry_at", "since", "observed_at"} {
		if _, ok := rr[key]; !ok {
			t.Errorf("runtime_recovering has no %s: %v", key, rr)
		}
	}
	if s, _ := got["runtime_reason"].(string); !strings.Contains(s, "first failure") {
		t.Errorf("runtime_reason = %q", s)
	}
	if _, ok := got["image_pull_failed"]; ok {
		t.Errorf("a host with no pull failure carries image_pull_failed: %s", raw)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// InstallationArchiveKind names the document, so an import can tell an
// installation archive from a settings export or anything else somebody
// points it at before it reads a single row.
const InstallationArchiveKind = "zoomies-installation"

// installationArchiveVersion is bumped when the document changes shape in a
// way an older reader would misread. The rows carry their own column names,
// so a column added to a table is not such a change.
const installationArchiveVersion = 1

// InstallationArchive is everything about one installation, as one document.
type InstallationArchive struct {
	Kind           string    `json:"kind"`
	ArchiveVersion int       `json:"archive_version"`
	ExportedAt     time.Time `json:"exported_at"`
	ExportedFrom   string    `json:"exported_from,omitempty"`
	Version        string    `json:"version"`
	InstallationID string    `json:"installation_id"`
	Target         string    `json:"target"`
	// Secrets is the installation's private key and webhook secret, sealed
	// under the passphrase the export was given. It is absent when none was:
	// the archive is then the installation's history without the means to
	// act as it, and an import asks for the key to be entered by hand.
	Secrets *ArchiveSecrets      `json:"secrets,omitempty"`
	Tables  []store.ArchiveTable `json:"tables"`
}

// ArchiveSecrets are passphrase-sealed values (cryptox.SealWithPassphrase),
// base64 in JSON.
type ArchiveSecrets struct {
	PrivateKey    []byte `json:"private_key,omitempty"`
	WebhookSecret []byte `json:"webhook_secret,omitempty"`
}

// ErrArchive is an archive or passphrase the operator can do something about:
// the wrong file, a missing or wrong passphrase, or no instance key to seal
// the secrets under once they are open.
var ErrArchive = errors.New("installation archive")

// secretColumns are the installation columns sealed under this instance's
// key. They never leave in that form: ciphertext under a key the destination
// does not have is noise at best, and at worst a copy of a credential that
// outlives the purge meant to remove it.
var secretColumns = map[string]bool{"private_key_enc": true, "webhook_secret_enc": true}

// ExportInstallation assembles one installation's archive. With a passphrase
// its secrets are opened with the instance key and sealed again under the
// passphrase; without one they are left out.
func (c *Controller) ExportInstallation(ctx context.Context, id, passphrase string) (*InstallationArchive, error) {
	inst, err := c.st.GetInstallation(ctx, id)
	if err != nil {
		return nil, err
	}
	tables, err := c.st.ExportInstallation(ctx, id)
	if err != nil {
		return nil, err
	}
	for i := range tables {
		if tables[i].Table != "installations" {
			continue
		}
		for col, name := range tables[i].Columns {
			if !secretColumns[name] {
				continue
			}
			for _, row := range tables[i].Rows {
				row[col] = store.ArchiveValue{}
			}
		}
	}
	out := &InstallationArchive{
		Kind:           InstallationArchiveKind,
		ArchiveVersion: installationArchiveVersion,
		ExportedAt:     c.Now(),
		ExportedFrom:   c.cfg().Server.ExternalURL,
		Version:        version.Short(),
		InstallationID: inst.ID,
		Target:         inst.Target,
		Tables:         tables,
	}
	if strings.TrimSpace(passphrase) == "" {
		return out, nil
	}
	secrets := &ArchiveSecrets{}
	for _, s := range []struct {
		sealed []byte
		what   string
		into   *[]byte
	}{
		{inst.PrivateKeyEnc, "the App's private key", &secrets.PrivateKey},
		{inst.WebhookSecretEnc, "the webhook secret", &secrets.WebhookSecret},
	} {
		plain, err := c.unsealString(s.sealed, s.what)
		if err != nil {
			return nil, err
		}
		if plain == "" {
			continue
		}
		if *s.into, err = cryptox.SealWithPassphrase(passphrase, []byte(plain)); err != nil {
			return nil, fmt.Errorf("sealing %s under the passphrase: %w", s.what, err)
		}
	}
	out.Secrets = secrets
	return out, nil
}

// ImportInstallation writes an archive onto this instance. The secrets are
// opened with the passphrase and sealed under this instance's key before the
// row is written, so nothing on disk here is readable with the passphrase
// alone.
func (c *Controller) ImportInstallation(ctx context.Context, a *InstallationArchive, passphrase string) (*store.Installation, *store.ImportedInstallation, error) {
	if a == nil || a.Kind != InstallationArchiveKind {
		return nil, nil, fmt.Errorf("%w: this is not an installation archive; make one with zoomies export --installation", ErrArchive)
	}
	if a.ArchiveVersion > installationArchiveVersion {
		return nil, nil, fmt.Errorf("%w: it was written by Zoomies %s in a newer format; upgrade this instance first", ErrArchive, a.Version)
	}
	sealed := map[string][]byte{}
	if a.Secrets != nil {
		if strings.TrimSpace(passphrase) == "" {
			return nil, nil, fmt.Errorf("%w: it carries the App's credentials sealed under a passphrase; give the one it was exported with", ErrArchive)
		}
		if c.key == nil {
			return nil, nil, fmt.Errorf("%w: this instance has no encryption key to keep the App's credentials under; set security.encryption_key first", ErrArchive)
		}
		for col, v := range map[string][]byte{"private_key_enc": a.Secrets.PrivateKey, "webhook_secret_enc": a.Secrets.WebhookSecret} {
			if len(v) == 0 {
				continue
			}
			plain, err := cryptox.OpenWithPassphrase(passphrase, v)
			if err != nil {
				return nil, nil, fmt.Errorf("%w: the passphrase does not open the App's credentials, or the archive has been altered", ErrArchive)
			}
			if sealed[col], err = c.key.Seal(plain); err != nil {
				return nil, nil, err
			}
		}
	}
	for i := range a.Tables {
		if a.Tables[i].Table != "installations" {
			continue
		}
		for col, name := range a.Tables[i].Columns {
			if !secretColumns[name] {
				continue
			}
			for _, row := range a.Tables[i].Rows {
				if col < len(row) {
					// Whatever the file says is replaced: a secret column is
					// only ever what this instance sealed itself.
					row[col] = store.ArchiveValue{V: sealed[name]}
				}
			}
		}
	}
	done, err := c.st.ImportInstallation(ctx, a.Tables)
	if err != nil {
		return nil, nil, err
	}
	inst, err := c.st.GetInstallation(ctx, done.InstallationID)
	if err != nil {
		return nil, nil, err
	}
	c.publishInstallation(ctx, inst)
	if pools, err := c.st.ListPools(ctx); err == nil {
		for _, p := range pools {
			if p.InstallationID == inst.ID {
				c.PublishPool(ctx, events.KindPoolCreated, p)
			}
		}
	}
	return inst, done, nil
}

package controller

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// Two installations whose pools advertise exactly the same labels is the shape
// that used to cross-allocate: nothing about a job said which GitHub target it
// belonged to, so the label rule picked between the pools on their names and
// the runner was minted in whichever organisation won. These tests are the
// three paths a job can arrive by, each proving the job lands on its own
// installation's pool and that nothing was created in the other target.

// twoInstallations seeds two organisations, each with a pool advertising the
// same labels, and one host big enough for either.
func twoInstallations(h *harness) (acme, globex *store.Pool) {
	h.t.Helper()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	// The names are chosen so that "acme-pool" sorts first: the old tie-break
	// was the pool name, so a test whose expected pool sorts first would pass
	// on the broken code as well.
	a := h.installationOn("acme", store.TargetOrg)
	g := h.installationOn("globex", store.TargetOrg)
	h.host("vm-1")
	return h.pool(a, "acme-pool", labels...), h.pool(g, "globex-pool", labels...)
}

// jitTargets is the organisation of every runner registration minted against
// GitHub so far, which is what says where a runner was actually created.
func jitTargets(h *harness) []string {
	h.t.Helper()
	var out []string
	for _, r := range h.gh.Requests() {
		path, ok := strings.CutPrefix(r, "POST /orgs/")
		if !ok {
			continue
		}
		if org, rest, found := strings.Cut(path, "/"); found && strings.Contains(rest, "generate-jitconfig") {
			out = append(out, org)
		}
	}
	return out
}

func TestAWebhookJobIsClaimedByThePoolOnItsOwnInstallation(t *testing.T) {
	h := newHarness(t)
	_, globex := twoInstallations(h)

	rec := h.deliverJob(jobEvent{
		Action: "queued", JobID: 7001, Repo: "globex/thing",
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("status = %d, want %d (%s)", rec.Code, http.StatusAccepted, rec.Body.String())
	}

	job, err := h.st.GetJobByGitHubID(h.ctx, 7001)
	if err != nil {
		t.Fatalf("the delivery recorded no job: %v", err)
	}
	if job.InstallationID != globex.InstallationID {
		t.Fatalf("job installation = %q, want globex's %q", job.InstallationID, globex.InstallationID)
	}
	if job.PoolID != globex.ID || !job.Matched {
		t.Fatalf("job = %+v, want it claimed by %s", job, globex.Name)
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	runners := h.runners()
	if len(runners) != 1 || runners[0].PoolID != globex.ID {
		t.Fatalf("runners = %+v, want one in %s", runners, globex.Name)
	}
	for _, org := range jitTargets(h) {
		if org != "globex" {
			t.Fatalf("a runner was registered in %q for a job in globex/thing", org)
		}
	}
}

func TestAPolledJobIsClaimedByThePoolOnTheInstallationItCameFrom(t *testing.T) {
	h := newHarness(t)
	// Repository-target installations, so each one polls only its own
	// repository and the two queues cannot be confused for one another.
	acme := h.installationOn("acme/widgets", store.TargetRepo)
	globex := h.installationOn("globex/thing", store.TargetRepo)
	h.host("vm-1")
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	acmePool := h.pool(acme, "acme-pool", labels...)
	globexPool := h.pool(globex, "globex-pool", labels...)

	acmeJob := h.gh.AddQueuedJob("acme/widgets", "CI", "build", labels)
	globexJob := h.gh.AddQueuedJob("globex/thing", "CI", "build", labels)

	h.c.pollOnce(h.ctx)

	for _, tc := range []struct {
		name string
		id   int64
		pool *store.Pool
	}{
		{"acme", acmeJob.ID, acmePool},
		{"globex", globexJob.ID, globexPool},
	} {
		job, err := h.st.GetJobByGitHubID(h.ctx, tc.id)
		if err != nil {
			t.Fatalf("%s: the poller recorded no job: %v", tc.name, err)
		}
		if job.InstallationID != tc.pool.InstallationID {
			t.Errorf("%s: job installation = %q, want %q", tc.name, job.InstallationID, tc.pool.InstallationID)
		}
		if job.PoolID != tc.pool.ID || !job.Matched {
			t.Errorf("%s: job = %+v, want it claimed by %s", tc.name, job, tc.pool.Name)
		}
	}
}

func TestTheSchedulerNeverPlacesAJobOnAnotherInstallationsPool(t *testing.T) {
	h := newHarness(t)
	acmePool, globexPool := twoInstallations(h)

	// A queued job in globex, written straight to the store: this is the
	// scheduler's own path, with no ingest in the way.
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 7002, Repo: "globex/thing", Workflow: "CI", JobName: "build",
		Labels: store.StringSlice{"self-hosted", "linux", "x64", "demo"},
		State:  store.JobQueued, InstallationID: globexPool.InstallationID,
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	for _, r := range h.runners() {
		if r.PoolID == acmePool.ID {
			t.Fatalf("a runner was created in %s for a job in globex", acmePool.Name)
		}
	}
	if got := len(h.runners()); got != 1 {
		t.Fatalf("created %d runners, want 1 in %s", got, globexPool.Name)
	}
}

// A job whose repository no installation covers is recorded and left unclaimed
// rather than rejected: Zoomies cannot mint a runner for a target it holds no
// credentials for, and a delivery it drops is a job that disappears.
func TestAJobNoInstallationCoversIsRecordedAndUnclaimed(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()

	rec := h.deliverJob(jobEvent{
		Action: "queued", JobID: 7003, Repo: "other-org/thing",
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	})
	if rec.Code != http.StatusAccepted {
		t.Fatalf("status = %d, want %d (%s)", rec.Code, http.StatusAccepted, rec.Body.String())
	}
	job, err := h.st.GetJobByGitHubID(h.ctx, 7003)
	if err != nil {
		t.Fatalf("the delivery recorded no job: %v", err)
	}
	if job.InstallationID != "" {
		t.Errorf("job installation = %q, want none: no installation covers other-org", job.InstallationID)
	}
	if job.Matched || job.PoolID == pool.ID {
		t.Errorf("job = %+v, want it unclaimed: %s cannot run work in another target", job, pool.Name)
	}
}

// The Jobs page shows an unclaimed job the same way whatever refused it, so
// the problems drawer is where the difference has to be said: "no pool
// advertises those labels" and "a pool advertises exactly those labels, in
// another GitHub target" need opposite fixes.
func TestTheProblemsDrawerNamesThePoolOnTheOtherInstallation(t *testing.T) {
	h := newHarness(t)
	acme, globex := twoInstallations(h)

	// Globex's pool is the only one whose labels fit, and it is the wrong
	// target for this job.
	if _, _, err := h.st.DeletePool(h.ctx, acme.ID); err != nil {
		t.Fatalf("DeletePool: %v", err)
	}
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 7004, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
		Labels: store.StringSlice{"self-hosted", "linux", "x64", "demo"},
		State:  store.JobQueued, InstallationID: acme.InstallationID,
		QueuedAt: time.Now().Add(-unmatchedGrace - time.Minute),
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var found *Problem
	for i, p := range ps {
		if p.Code == "jobs.unmatched" {
			found = &ps[i]
		}
	}
	if found == nil {
		t.Fatalf("problems = %v, want the unmatched-job warning", h.problemCodes())
	}
	if !strings.Contains(found.Detail, globex.Name) || !strings.Contains(found.Detail, "installation globex") {
		t.Errorf("detail = %q, want it to name %s and the installation it belongs to", found.Detail, globex.Name)
	}
	if strings.Contains(found.Fix, "runs-on") {
		t.Errorf("fix = %q, want it to point at the installation rather than the workflow", found.Fix)
	}
}

// An organisation installation and a repository one can both cover the same
// repository. Only one of them owns a job in it, and both ingest paths have to
// agree on which: if the poller kept the installation it polled while the
// webhook path resolved the repository, the job's installation would change
// with every delivery and its pool with it.
func TestBothIngestPathsAgreeOnTheInstallationThatOwnsAJob(t *testing.T) {
	h := newHarness(t)
	org := h.installationOn("acme", store.TargetOrg)
	repo := h.installationOn("acme/widgets", store.TargetRepo)
	h.host("vm-1")
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	h.pool(org, "acme-pool", labels...)
	repoPool := h.pool(repo, "widgets-pool", labels...)

	// Ingested as the organisation's installation, which is what a poll of it
	// returns; the repository's installation is the one that owns the job.
	// Ingest is driven directly rather than through pollOnce, because pollOnce
	// polls both installations and the second would paper over the first.
	polled := h.gh.AddQueuedJob("acme/widgets", "CI", "build", labels)
	if _, err := h.c.ingestQueuedJobs(h.ctx, org, []github.QueuedJob{{
		ID: polled.ID, RunID: polled.RunID, Repo: "acme/widgets",
		WorkflowName: "CI", JobName: "build", Labels: labels,
	}}); err != nil {
		t.Fatalf("ingestQueuedJobs: %v", err)
	}

	job, err := h.st.GetJobByGitHubID(h.ctx, polled.ID)
	if err != nil {
		t.Fatalf("the poller recorded no job: %v", err)
	}
	if job.InstallationID != repo.ID {
		t.Fatalf("polled job installation = %q, want the repository's %q", job.InstallationID, repo.ID)
	}
	if job.PoolID != repoPool.ID {
		t.Fatalf("polled job pool = %q, want %s", job.PoolID, repoPool.Name)
	}

	// And the webhook path, on a job in the same repository, says the same.
	h.deliverJob(jobEvent{
		Action: "queued", JobID: 7005, Repo: "acme/widgets", Labels: labels,
	})
	delivered, err := h.st.GetJobByGitHubID(h.ctx, 7005)
	if err != nil {
		t.Fatalf("the delivery recorded no job: %v", err)
	}
	if delivered.InstallationID != job.InstallationID {
		t.Fatalf("the two paths disagree: webhook says %q, poller said %q",
			delivered.InstallationID, job.InstallationID)
	}
}

// The timeline is read by the same operator the problems drawer is, so an
// unclaimed job must not be told two different stories about why.
func TestTheTimelineSaysWhenNoInstallationCoversTheRepository(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	h.deliverJob(jobEvent{
		Action: "queued", JobID: 7006, Repo: "other-org/thing",
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	})
	job, err := h.st.GetJobByGitHubID(h.ctx, 7006)
	if err != nil {
		t.Fatalf("the delivery recorded no job: %v", err)
	}
	events, err := h.st.ListJobEvents(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ListJobEvents: %v", err)
	}
	var said string
	for _, e := range events {
		if e.Kind == store.JobEventUnmatched {
			said = e.Message
		}
	}
	if !strings.Contains(said, "no GitHub App installation here covers other-org/thing") {
		t.Fatalf("the unmatched entry says %q, want it to name the uncovered repository", said)
	}
}

// twoPolledInstallations seeds two repository-target installations, so each
// polls only its own repository and the two queues cannot be confused.
func twoPolledInstallations(h *harness) (acme, globex *store.Installation) {
	h.t.Helper()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	a := h.installationOn("acme/widgets", store.TargetRepo)
	g := h.installationOn("globex/thing", store.TargetRepo)
	h.host("vm-1")
	h.pool(a, "acme-pool", labels...)
	h.pool(g, "globex-pool", labels...)
	h.gh.AddQueuedJob("acme/widgets", "CI", "build", labels)
	h.gh.AddQueuedJob("globex/thing", "CI", "build", labels)
	return a, g
}

// polledRepos is the repositories this sweep asked GitHub about, which is what
// says which installations were actually polled.
func polledRepos(h *harness, since int) map[string]bool {
	h.t.Helper()
	out := map[string]bool{}
	for _, r := range h.gh.Requests()[since:] {
		for _, repo := range []string{"acme/widgets", "globex/thing"} {
			if strings.Contains(r, "/repos/"+repo+"/") {
				out[repo] = true
			}
		}
	}
	return out
}

// GitHub's quota is per installation. A sweep that abandoned the rest of the
// fleet on the first rate-limited installation would let one organisation out
// of quota stop every other one from scaling -- and the poller is the fallback
// that exists precisely for the installation whose webhooks are not arriving.
func TestARateLimitedInstallationDoesNotStopTheOthersBeingPolled(t *testing.T) {
	h := newHarness(t)
	acme, globex := twoPolledInstallations(h)
	// A secondary rate limit, which GitHub reports as a 429 on the call it
	// refuses. The primary form is a 403 plus an exhausted quota in the
	// response headers, and those headers are what go-github caches per
	// client -- setting them on the fake would rate-limit every installation
	// at once and prove nothing about isolation.
	h.gh.SetError("/repos/acme/widgets/", 429, "You have exceeded a secondary rate limit")

	before := len(h.gh.Requests())
	h.c.pollOnce(h.ctx)

	if !h.c.githubHeld(acme.ID, time.Now()) {
		t.Error("the rate-limited installation was not stood down")
	}
	if h.c.githubHeld(globex.ID, time.Now()) {
		t.Error("the installation GitHub did not rate-limit was stood down with it")
	}
	if asked := polledRepos(h, before); !asked["globex/thing"] {
		t.Errorf("globex was never polled: %v", asked)
	}

	// And the next sweep skips the held installation while still polling the
	// other, rather than the hold covering the whole fleet.
	before = len(h.gh.Requests())
	h.c.pollOnce(h.ctx)
	asked := polledRepos(h, before)
	if asked["acme/widgets"] {
		t.Error("the held installation was polled again inside its backoff")
	}
	if !asked["globex/thing"] {
		t.Errorf("the other installation stopped being polled: %v", asked)
	}
}

// Standing down because webhooks are arriving is what makes the poller cheap
// enough to leave on. Asked fleet-wide, one organisation's working deliveries
// would silence the poller for an organisation whose webhooks reach nobody --
// which is the exact failure the poller is the safety net for.
func TestAFreshInstallationDoesNotSilenceThePollerForASilentOne(t *testing.T) {
	h := newHarness(t)
	_, _ = twoPolledInstallations(h)

	if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
		DeliveryID: "recent", Event: "workflow_job", Repo: "acme/widgets",
		Status: "accepted", ReceivedAt: time.Now(),
	}); err != nil {
		t.Fatalf("RecordDelivery: %v", err)
	}

	before := len(h.gh.Requests())
	h.c.pollOnce(h.ctx)

	asked := polledRepos(h, before)
	if asked["acme/widgets"] {
		t.Error("an installation whose webhooks are arriving was polled anyway")
	}
	if !asked["globex/thing"] {
		t.Errorf("the installation no webhook has ever arrived for was not polled: %v", asked)
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The constants that govern reconciliation live in four packages, and each
// was chosen against one in another: the host-lost reclaim against the
// heartbeat timeout, the heartbeat timeout against the interval the controller
// hands the agent, every task lease against the time the agent gives itself to
// do that task. Until now nothing but a comment held those pairs together, so
// a change to one side did not have to say what it did to the other. These
// tests are the section of the same name in docs/architecture.md, made to
// fail.

// A host passes through two judgements as it goes quiet, and they have to come
// in this order: late (one missed heartbeat is nothing), then unhealthy (the
// scheduler stops placing runners on it), then lost (the runners already on
// it are failed so a pool can replace them). Unhealthy before late would fail
// healthy hosts on every hiccup; lost before unhealthy would destroy runners
// on a host the scheduler was still placing new ones on.
func TestAHostIsLateThenUnhealthyThenLostInThatOrder(t *testing.T) {
	interval := config.Default().Agent.HeartbeatInterval
	if interval <= 0 {
		t.Fatalf("the default heartbeat interval is %s; the ladder needs a positive one", interval)
	}
	// Three missed heartbeats, not one: a single late POST is a busy host or
	// a slow link, and marking it unhealthy would bounce placement on and off.
	if store.HeartbeatTimeout < 3*interval {
		t.Fatalf("store.HeartbeatTimeout is %s, less than three default heartbeat intervals of %s; one slow heartbeat would make a host unhealthy", store.HeartbeatTimeout, interval)
	}
	if hostLostAfter <= store.HeartbeatTimeout {
		t.Fatalf("hostLostAfter is %s, not later than store.HeartbeatTimeout at %s; runners would be failed on a host the scheduler had not yet stopped using", hostLostAfter, store.HeartbeatTimeout)
	}
}

// A task's lease is how long the controller waits before offering the task to
// the host again. If it were shorter than the work, a create still pulling its
// image would be redelivered while the first attempt was running, and the
// agent's adopt-before-create is a backstop for a lost result, not a licence
// to race it. So each lease exceeds the longest the agent will spend on that
// kind of task, with room for the result to travel.
func TestEveryTaskLeaseOutlastsTheWorkItCovers(t *testing.T) {
	cases := []struct {
		kind  agent.TaskKind
		lease time.Duration
		work  time.Duration
	}{
		{agent.TaskCreateRunner, createLease, agent.CreateTimeout},
		// The controller hands the agent DefaultStopTimeout on every stop
		// (reconcile.go), and the agent adds StopMargin to it.
		{agent.TaskStopRunner, stopLease, agent.DefaultStopTimeout + agent.StopMargin},
		{agent.TaskRemoveRunner, removeLease, agent.RemoveTimeout},
	}
	for _, c := range cases {
		if got := requeueAfter(c.kind); got != c.lease {
			t.Errorf("%s: requeueAfter gives %s, want the %s lease this test pins", c.kind, got, c.lease)
		}
		if c.lease <= c.work {
			t.Errorf("%s: the lease is %s and the agent may spend %s on the task; the controller would redeliver it while the first attempt was still running", c.kind, c.lease, c.work)
		}
	}
}

// A machine's life is a chain of deadlines, and each one has to outlast the
// thing it bounds. Set the wrong way round they do not merely misbehave: an
// ambiguity timeout shorter than a create quarantines machines that are simply
// still being built, and a delete grace shorter than the silence that loses a
// host destroys a machine in the middle of a job.
func TestEveryMachineDeadlineOutlastsTheWorkItCovers(t *testing.T) {
	p := config.Default().Provider
	cases := []struct {
		shorter, longer string
		short, long     time.Duration
		because         string
	}{
		{"provider.call_timeout", "provider.create_timeout", p.CallTimeout, p.CreateTimeout,
			"one request has to fit inside the whole asynchronous create it starts"},
		{"provider.create_timeout", "provider.ambiguity_timeout", p.CreateTimeout, p.AmbiguityTimeout,
			"a create that is merely slow would otherwise be treated as one nobody can account for"},
		{"the heartbeat timeout", "provider.enrol_timeout", store.HeartbeatTimeout, p.EnrolTimeout,
			"a machine that joined and went briefly quiet would otherwise be given up on"},
		{"hostLostAfter plus a housekeeping tick", "provider.delete_grace",
			hostLostAfter + housekeepingTick, p.DeleteGrace,
			"a network blip would otherwise destroy a machine that is in the middle of a job"},
		{"hostLostAfter", "provider.idle_timeout", hostLostAfter, p.IdleTimeout,
			"a machine whose host had merely gone quiet would otherwise be drained as idle"},
		{"provider.enrol_timeout", "a machine join token's life",
			p.EnrolTimeout, p.EnrolTimeout + machineTokenGrace,
			"the credential has to outlast the window the machine is given to use it"},
	}
	for _, c := range cases {
		if c.long <= c.short {
			t.Errorf("%s is %s and %s is %s: %s", c.longer, c.long, c.shorter, c.short, c.because)
		}
	}
}

// A runner's start is bounded in three places, and the three have to agree.
// The agent gives itself a budget for the create because a cold image pull is
// minutes; the controller holds the task that long again before re-offering it;
// the scheduler fails the row once it has been starting too long. The scheduler
// is the only one of the three that gives up, so it has to be the most patient
// of them -- and it did not used to be. With a five-minute provision timeout
// against a fifteen-minute create budget, a cold host had its runners condemned
// while the agent was still pulling, and the pool replaced each one, which put a
// second pull of the same image on the link that was slow to begin with.
func TestARunnerIsGivenLongEnoughToStartByEveryHalfThatBoundsIt(t *testing.T) {
	cfg := config.Default()
	// What a start actually costs: the agent's create, then the wait the runner
	// image does for its Docker daemon before it registers.
	start := agent.CreateTimeout + cfg.Runners.EffectiveDockerWait()
	if cfg.Scheduler.ProvisionTimeout <= start {
		t.Errorf("scheduler.provision_timeout is %s and a runner may legitimately take %s to start (agent.CreateTimeout %s plus a %s Docker wait); runners still coming up would be failed and replaced",
			cfg.Scheduler.ProvisionTimeout, start, agent.CreateTimeout, cfg.Runners.EffectiveDockerWait())
	}
	// The lease is how long the controller waits before offering the create to
	// the host again. A runner failed while its create is still leased is one
	// nothing will retry and nothing will finish.
	if createLease < cfg.Scheduler.ProvisionTimeout {
		t.Errorf("the create lease is %s and scheduler.provision_timeout is %s; a runner would be failed with its create neither redelivered nor abandoned",
			createLease, cfg.Scheduler.ProvisionTimeout)
	}
	// The fleet says a runner is not progressing at half the timeout, and that
	// has to land after the Docker wait rather than during it: a runner doing
	// exactly what it was configured to do must not be reported as stuck.
	if half := cfg.Scheduler.ProvisionTimeout / 2; half <= cfg.Runners.EffectiveDockerWait() {
		t.Errorf("runners are reported as not progressing after %s, within the %s a Docker pool's runner is configured to wait for its daemon; a healthy runner would be raised as a problem",
			half, cfg.Runners.EffectiveDockerWait())
	}
}

// The throttle ladder's four constants were each chosen against one in
// another package, and a change to any of them has to say what it does to
// the other side.
func TestTheThrottleLadderIsPacedAgainstTheMeasurementsItClimbsOn(t *testing.T) {
	// A step down waits for a stretch of calm, and calm is only ever judged
	// from a fresh sample. If the recovery were shorter than a sample's life,
	// one calm reading could take a host down a rung before a second reading
	// had a chance to disagree, and a host under pressure that lulled for a
	// moment would bounce between rungs.
	if scheduler.ThrottleRecovery <= store.HostUsageMaxAge {
		t.Fatalf("scheduler.ThrottleRecovery is %s, not longer than store.HostUsageMaxAge at %s; a single calm sample could step a host down", scheduler.ThrottleRecovery, store.HostUsageMaxAge)
	}
	// A rung may not be climbed faster than the CPU hold that feeds the
	// ladder can trip: the hold needs CPUHoldWindow of saturation, and a step
	// shorter than that would let the ladder climb on measurements the hold
	// had not yet judged sustained.
	if scheduler.ThrottleStep < store.CPUHoldWindow {
		t.Fatalf("scheduler.ThrottleStep is %s, shorter than the %s CPU hold that feeds it; the ladder would climb on pressure the hold had not called sustained", scheduler.ThrottleStep, store.CPUHoldWindow)
	}
	// A host that stops measuring is lifted after StaleThrottleReset, and a
	// host that stops heartbeating is given up on after hostLostAfter. The
	// reset has to be the later of the two: a host whose runners were just
	// reclaimed as lost is a host that is about to come back, and it should
	// come back on no rung -- but a host lifted before it was lost would have
	// its full capacity handed back while it was merely late.
	if scheduler.StaleThrottleReset <= hostLostAfter {
		t.Fatalf("scheduler.StaleThrottleReset is %s, not later than hostLostAfter at %s; a late host would be handed its slots back before it was even given up on", scheduler.StaleThrottleReset, hostLostAfter)
	}
	// Half speed doubles a job's time, which the timeout-minutes most
	// workflows set survives; a quarter turns "slow" into "timed out", and a
	// throttle that made jobs fail would be doing the thing it exists to
	// prevent. The top rung takes slots and nothing else.
	if store.MinCPUFactor < 0.5 {
		t.Fatalf("store.MinCPUFactor is %v, below the half speed a running job is promised; a throttled job would time out rather than finish late", store.MinCPUFactor)
	}
}

