func TestMissedCompletionIsRecoveredDespiteFreshWebhooks(t *testing.T) {
	for _, conclusion := range []string{"cancelled", "success", "failure"} {
		t.Run(conclusion, func(t *testing.T) {
			h := newHarness(t)
			inst, _, _ := h.fleet()
			q := h.gh.AddQueuedJob("acme/widgets", "CI", "Images", []string{"self-hosted", "linux", "x64", "demo"})
			h.c.pollOnce(h.ctx)
			h.gh.CompleteJob(q.ID, conclusion)
			h.advance(3 * time.Minute)
			if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
				DeliveryID: "unrelated", Event: "workflow_job", Repo: "acme/widgets", InstallationID: inst.ID,
				Status: "accepted", ReceivedAt: h.c.Now(),
			}); err != nil {
				t.Fatal(err)
			}
			h.c.pollOnce(h.ctx)
			job, err := h.st.GetJobByGitHubID(h.ctx, q.ID)
			if err != nil {
				t.Fatal(err)
			}
			if job.State != store.JobCompleted || job.Conclusion != conclusion {
				t.Fatalf("job = %+v", job)
			}
			events := h.timeline(job.ID)
			last := events[len(events)-1]
			if last.Kind != store.JobEventCompleted || last.Source != sourcePoller {
				t.Fatalf("event = %+v", last)
			}
			h.c.pollOnce(h.ctx)
			if got := len(h.timeline(job.ID)); got != len(events) {
				t.Fatalf("duplicate completion: %d events", got)
			}
			queued, err := h.st.ListQueuedJobs(h.ctx)
			if err != nil || len(queued) != 0 {
				t.Fatalf("cancelled job still creates demand: %+v, %v", queued, err)
			}
		})
	}
}

func TestJobRecoveryDoesNotInventCancellationOnGitHubFailure(t *testing.T) {
	for _, status := range []int{http.StatusNotFound, http.StatusForbidden, http.StatusInternalServerError} {
		h := newHarness(t)
		h.fleet()
		q := h.gh.AddQueuedJob("acme/widgets", "CI", "Images", []string{"self-hosted", "linux", "x64", "demo"})
		h.c.pollOnce(h.ctx)
		h.advance(3 * time.Minute)
		h.gh.SetError("/actions/jobs/", status, "lookup failed")
		h.c.pollOnce(h.ctx)
		job, err := h.st.GetJobByGitHubID(h.ctx, q.ID)
		if err != nil {
			t.Fatal(err)
		}
		if job.State != store.JobQueued {
			t.Fatalf("HTTP %d changed job to %s", status, job.State)
		}
	}
}

func TestRunningContainerNeedsAnOnlineGitHubRunner(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRegistering)
	report := []agent.RunnerReport{{RunnerID: r.ID, Phase: backend.PhaseRunning}}
	if err := h.c.ReportRunners(h.ctx, host.ID, report); err != nil {
		t.Fatal(err)
	}
	got, _ := h.st.GetRunner(h.ctx, r.ID)
	if got.State != store.RunnerRegistering {
		t.Fatalf("unregistered container became %s", got.State)
	}
	h.gh.AddRunner(r.Name, pool.Labels)
	if err := h.c.ReportRunners(h.ctx, host.ID, report); err != nil {
		t.Fatal(err)
	}
	h.c.enrichOnce(h.ctx)
	got, _ = h.st.GetRunner(h.ctx, r.ID)
	if got.State != store.RunnerIdle || got.GitHubRunnerID == 0 {
		t.Fatalf("online runner = %+v", got)
	}
}

func TestJobRecoveryRotatesThroughBoundedPages(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	for i := 0; i < 13; i++ {
		q := h.gh.AddQueuedJob("acme/widgets", "CI", "Images", []string{"self-hosted", "linux", "x64", "demo"})
		h.c.pollOnce(h.ctx)
		_ = q
	}
	h.advance(3 * time.Minute)
	for pass := 0; pass < 2; pass++ {
		before := len(h.gh.Requests())
		h.c.reconcileKnownJobs(h.ctx, h.c.Now())
		n := 0
		for _, req := range h.gh.Requests()[before:] {
			if strings.Contains(req, "/actions/jobs/") {
				n++
			}
		}
		want := 10
		if pass == 1 {
			want = 3
		}
		if n != want {
			t.Fatalf("pass %d made %d checks, want %d", pass, n, want)
		}
	}
}

// Turning the fallback poller off used to turn off the only check that notices
// a completion whose webhook never arrived, leaving the job in progress for
// ever: counted against its repository's scale-up limit, and holding its
// runner's host back from cleanup. The job-recovery loop owns that check
// whatever github.poll_fallback says, so it must still find the completion
// with the poller off -- and the housekeeping pass must not run it a second
// time, because two callers double every GitHub call and race on the shared
// rotation offset.
func TestAMissedCompletionIsStillRecoveredWithThePollerOff(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	q := h.gh.AddQueuedJob("acme/widgets", "CI", "Images", []string{"self-hosted", "linux", "x64", "demo"})
	h.c.pollOnce(h.ctx)
	h.gh.CompleteJob(q.ID, "success")
	h.advance(3 * time.Minute)

	// The pass is run whole, as the loop runs it, with the two jobs that would
	// leave the fake switched off: the image refresh and the release check
	// both have nowhere to go here.
	h.cfg.GitHub.PollFallback = false
	h.cfg.Images.RefreshInterval = 0
	h.cfg.Updates.CheckInterval = 0
	h.c.housekeep(h.ctx, &housekeeping{})
	job, err := h.st.GetJobByGitHubID(h.ctx, q.ID)
	if err != nil {
		t.Fatal(err)
	}
	if job.State == store.JobCompleted {
		t.Fatal("the housekeeping loop checked known jobs, which the job-recovery loop already does and would double every GitHub call")
	}

	h.c.reconcileKnownJobs(h.ctx, h.c.Now())
	job, err = h.st.GetJobByGitHubID(h.ctx, q.ID)
	if err != nil {
		t.Fatal(err)
	}
	if job.State != store.JobCompleted || job.Conclusion != "success" {
		t.Fatalf("job = %+v, want it completed by the job-recovery sweep", job)
	}
}

package controller

import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// The failure this was built for, end to end: a heavy job runs on a small
// host, the agent's samples record what it used, a step is killed for memory
// and the runner finishes the job anyway. The job has to come out of it with
// its peaks, marked as the fleet's failure, explained as a memory kill, and
// listed as a problem on the host -- because GitHub will call it a failed
// step like any other.
func TestAJobKilledForMemoryIsRecordedExplainedAndReported(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.seedRunner(t, pool, host, store.RunnerBusy)
	started := h.c.Now().Add(-time.Hour)
	job, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 4242, Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)",
		Labels: pool.Labels, State: store.JobInProgress, PoolID: pool.ID, Matched: true,
		RunnerID: r.ID, RunnerName: r.Name, QueuedAt: started, StartedAt: &started, HostID: host.ID,
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	at := h.c.Now()
	for _, s := range []backend.Stats{
		{SampledAt: &at, CPUPercent: 390, MemoryBytes: 2900 << 20},
		{SampledAt: &at, CPUPercent: 120, MemoryBytes: 1200 << 20},
	} {
		if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{RunnerID: r.ID, Stats: s}}); err != nil {
			t.Fatalf("ReportRunners: %v", err)
		}
	}

	done := h.c.Now()
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 4242, State: store.JobCompleted, Conclusion: "failure",
		Repo: job.Repo, StartedAt: &started, CompletedAt: &done}); err != nil {
		t.Fatalf("completing the job: %v", err)
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerRemoved, Fault: store.FaultOutOfMemory,
		Message: "runner exited after its job, but the kernel killed a process in it for its memory limit",
	}}); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	got, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.OOMKilled || got.FaultKind != store.FaultOutOfMemory || got.PeakMemoryMB != 2900 || got.PeakCPUs != 3.9 {
		t.Fatalf("job = oom %t, fault %q, peaks %v CPU %d MB", got.OOMKilled, got.FaultKind, got.PeakCPUs, got.PeakMemoryMB)
	}

	// The view is the API's shape, and the UI and the MCP tools read these
	// three fields from it.
	raw, err := json.Marshal(NewJobView(got, pool.Name))
	if err != nil {
		t.Fatal(err)
	}
	for _, field := range []string{`"peak_cpus":3.9`, `"peak_memory_mb":2900`, `"oom_killed":true`} {
		if !strings.Contains(string(raw), field) {
			t.Errorf("the job view has no %s: %s", field, raw)
		}
	}

	events, err := h.st.ListJobEvents(h.ctx, job.ID)
	if err != nil {
		t.Fatal(err)
	}
	kills := 0
	for _, e := range events {
		if e.Kind == store.JobEventOOMKilled {
			kills++
		}
	}
	if kills != 1 {
		t.Fatalf("timeline has %d memory kills, want 1", kills)
	}

	ex, err := h.c.ExplainJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("ExplainJob: %v", err)
	}
	if !strings.Contains(ex.Summary, "for its memory limit") || !strings.Contains(ex.Summary, "2.8 GB") {
		t.Errorf("the explanation does not lead with the kill: %q", ex.Summary)
	}

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, p := range problems {
		if p.Code == "jobs.oom_killed" {
			found = true
			if !strings.Contains(p.Title, host.ID) {
				t.Errorf("the problem does not name the host: %q", p.Title)
			}
		}
	}
	if !found {
		t.Error("no jobs.oom_killed problem was raised")
	}
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// stampJobVersions records which build handled a job, once each, so that jobs
// can be compared across releases.
//
// It runs from recordJobChange, which every path that changes a job passes
// through, rather than from the webhook handler alone: the poller, the
// recovery sweep and the agent's own reports all move jobs, and a stamp that
// only one of them wrote would leave whichever saw the job first unlabelled.
//
// The controller's pair is stamped once something here has a claim on the job
// -- a pool matched it or a runner took it -- and never for a job nothing
// here touched, so a hosted job stays "unknown" instead of being credited to
// a release that never saw it. The host's pair waits for the runner, and is
// read from the host row as its last heartbeat left it. The store writes each
// column only while it is NULL, so calling this on every change is safe; the
// checks here only keep it from writing when there is nothing to add.
//
// j is updated in place, because the callers publish it next and the event
// frame is the job's GET shape.
func (c *Controller) stampJobVersions(ctx context.Context, j *store.Job, runner *store.Runner) {
	if j == nil || IsDemoID(j.InstallationID) {
		return
	}
	claimed := j.Matched || j.RunnerID != ""
	var v store.JobVersions
	if claimed && j.ControllerVersion == "" {
		v.ControllerVersion, v.ControllerChannel = version.Version, version.Channel(version.Version)
	}
	if j.RunnerID != "" && (j.HostID == "" || j.AgentVersion == "") {
		if runner == nil || runner.ID != j.RunnerID {
			if r, err := c.st.GetRunner(ctx, j.RunnerID); err == nil {
				runner = r
			} else {
				runner = nil
			}
		}
		if runner != nil && runner.HostID != "" {
			v.HostID = runner.HostID
			if h, err := c.st.GetHost(ctx, runner.HostID); err == nil {
				v.AgentVersion = h.Version
			}
		}
	}
	if v == (store.JobVersions{}) {
		return
	}
	stamped, err := c.st.StampJobVersions(ctx, j.ID, v)
	if err != nil {
		// Not worth failing the delivery over: the job is recorded, and the
		// next change to it tries again.
		c.log.Warn("could not stamp a job with its release", "job", j.ID, "error", err)
		return
	}
	j.ControllerVersion, j.ControllerChannel = stamped.ControllerVersion, stamped.ControllerChannel
	j.AgentVersion, j.HostID = stamped.AgentVersion, stamped.HostID
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// A job is stamped where the fleet first has a claim on it -- the controller's
// build when a pool matches it, the host and its agent when a runner takes it --
// and an upgrade half way through must not move it to another release.
func TestAJobIsStampedAtClaimAndAtPickupAndNeverAgain(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	host.Version = "v1.3.1"
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatal(err)
	}
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 9301, Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9301)
	if err != nil {
		t.Fatal(err)
	}
	if job.ControllerVersion != version.Version || job.ControllerChannel != version.Channel(version.Version) {
		t.Fatalf("claimed job carries %q/%q, want this build's %q", job.ControllerVersion, job.ControllerChannel, version.Version)
	}
	if job.HostID != "" || job.AgentVersion != "" {
		t.Fatalf("a job with no runner yet has a host: %+v", job)
	}

	// The controller is upgraded while the job runs.
	defer func(v string) { version.Version = v }(version.Version)
	version.Version = "v9.9.9"

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.advance(5 * time.Second)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatal(err)
	}
	r := h.onlyRunner()
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9301, RunnerName: r.Name, Labels: labels})
	h.deliverJob(jobEvent{Action: "completed", JobID: 9301, RunnerName: r.Name, Labels: labels, Conclusion: "success"})

	got, err := h.st.GetJobByGitHubID(h.ctx, 9301)
	if err != nil {
		t.Fatal(err)
	}
	if got.HostID != host.ID || got.AgentVersion != "v1.3.1" {
		t.Errorf("picked-up job is on %q at agent %q, want %q at v1.3.1", got.HostID, got.AgentVersion, host.ID)
	}
	if got.ControllerVersion == "v9.9.9" || got.ControllerVersion != job.ControllerVersion {
		t.Errorf("the controller's release moved from %q to %q on later deliveries", job.ControllerVersion, got.ControllerVersion)
	}
	if got.State != store.JobCompleted {
		t.Errorf("state = %s", got.State)
	}
}

// Hosted work belongs to somebody else's runners, so crediting it to a release
// of this controller would put numbers it never produced into that release.
func TestAJobNoPoolClaimsIsNotStamped(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9302, Labels: []string{"ubuntu-latest"}})
	job, err := h.st.GetJobByGitHubID(h.ctx, 9302)
	if err != nil {
		t.Fatal(err)
	}
	if job.ControllerVersion != "" || job.HostID != "" {
		t.Fatalf("an unclaimed hosted job was stamped: %+v", job)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

var (
	ErrWorkflowCancellationDisabled = errors.New("workflow cancellation is disabled")
	ErrJobAlreadyCompleted          = errors.New("the job has already completed")
	// ErrJobNotFinished and ErrJobDidNotFail are the two ways a re-run is
	// refused for the job's own sake rather than for a missing permission, and
	// they are separate because the advice differs: one is "wait", the other is
	// "you are looking at the wrong job".
	ErrJobNotFinished = errors.New("the job has not finished")
	ErrJobDidNotFail  = errors.New("the job did not fail")
)

// CancelJobWorkflow asks GitHub to cancel the workflow run containing jobID.
// GitHub remains authoritative for terminal job states, but once its
// run-scoped API accepts the request Zoomies immediately suppresses queued
// demand and tears down runners executing jobs from that run. Waiting for a
// completed webhook would let an arbitrary current step keep running.
//
// It exists beside CancelWorkflowRun because the Jobs page and JobDrawer
// already have a job in hand, not a run; it resolves the job to its run and
// delegates. The job's own already-completed check stays here rather than
// moving to the run-scoped method, so asking to cancel through a job that has
// itself finished is still refused even when a sibling job has not.
func (c *Controller) CancelJobWorkflow(ctx context.Context, jobID string, force bool) (*store.Job, error) {
	j, err := c.st.GetJob(ctx, jobID)
	if err != nil {
		return nil, err
	}
	if j.State == store.JobCompleted {
		return nil, ErrJobAlreadyCompleted
	}
	if j.InstallationID == "" || j.Repo == "" || j.GitHubRunID <= 0 {
		return nil, fmt.Errorf("job %s has no GitHub installation and workflow run to cancel", j.ID)
	}
	if _, err := c.CancelWorkflowRun(ctx, j.Repo, j.GitHubRunID, force); err != nil {
		return nil, err
	}
	return c.st.GetJob(ctx, j.ID)
}

// CancelWorkflowRun asks GitHub to cancel repo's workflow run runID, without
// needing one of its jobs' IDs. It is what the Workflows page's own run rows
// call directly, since a run there is only ever repo + GitHub's run ID -- see
// store.WorkflowRun for why it has no ID of its own.
//
// Every job of the run still in hand gets the timeline entry an operator's
// request produces, not only whichever job happened to be used to reach the
// run: nothing about the run names one job over another as the one this was
// "really" about.
func (c *Controller) CancelWorkflowRun(ctx context.Context, repo string, runID int64, force bool) ([]*store.Job, error) {
	if !c.cfg().GitHub.AllowWorkflowCancellation {
		return nil, ErrWorkflowCancellationDisabled
	}
	jobs, err := c.st.ListJobsForRun(ctx, repo, runID)
	if err != nil {
		return nil, err
	}
	if len(jobs) == 0 {
		return nil, store.ErrNotFound
	}
	var installationID string
	var live []*store.Job
	for _, j := range jobs {
		if j.InstallationID != "" {
			installationID = j.InstallationID
		}
		if j.State != store.JobCompleted {
			live = append(live, j)
		}
	}
	if len(live) == 0 {
		return nil, ErrJobAlreadyCompleted
	}
	if installationID == "" {
		return nil, fmt.Errorf("workflow run %d in %s has no GitHub installation to cancel", runID, repo)
	}
	client, err := c.ClientFor(ctx, installationID)
	if err != nil {
		return nil, err
	}
	if err := client.CancelWorkflowRun(ctx, repo, runID, force); err != nil {
		return nil, err
	}
	mode := "cancellation"
	if force {
		mode = "force cancellation"
	}
	message := fmt.Sprintf("an operator requested %s of GitHub workflow run %d; local queued work and runners were stopped immediately, while GitHub's completion events remain authoritative for the result", mode, runID)
	for _, j := range live {
		if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
			JobID: j.ID, Kind: store.JobEventCancelRequested, Source: sourceController,
			Message: message, At: c.Now(),
		}); err != nil {
			return nil, err
		}
	}
	if err := c.cancelWorkflowRunLocally(ctx, repo, runID, false); err != nil {
		// GitHub has already accepted the cancellation. Returning an error would
		// encourage an operator to repeat a request that succeeded; the webhook
		// and poller still provide the durable convergence path.
		c.log.Warn("GitHub accepted a workflow cancellation but local work could not all be stopped yet",
			"repo", repo, "run", runID, "error", err)
	}
	out := make([]*store.Job, 0, len(jobs))
	for _, j := range jobs {
		updated, getErr := c.st.GetJob(ctx, j.ID)
		if getErr != nil {
			continue
		}
		out = append(out, updated)
		c.publishJob(ctx, updated)
	}
	return out, nil
}

// cancelWorkflowRunLocally aligns every locally known job in a run with a
// run-scoped cancellation. Before GitHub confirms the terminal run state it
// pauses queued demand without inventing job conclusions. Once confirmed it
// also closes every remaining local job as cancelled.
func (c *Controller) cancelWorkflowRunLocally(ctx context.Context, repo string, runID int64, confirmed bool) error {
	jobs, err := c.st.ListJobsForRun(ctx, repo, runID)
	if err != nil {
		return fmt.Errorf("listing jobs in cancelled workflow run: %w", err)
	}
	now := c.Now()
	var queued, live []string
	var errs []error
	for _, j := range jobs {
		wasActive := j.State != store.JobCompleted
		if !confirmed && j.State == store.JobQueued {
			queued = append(queued, j.ID)
		}
		// Every job the run still owns, queued or running. Pausing the queued
		// half stops it asking for runners, but neither half stops being
		// reported as work in hand until the row says the cancellation was
		// asked for -- GitHub's completion delivery is what ends them, and it
		// is not always prompt.
		if !confirmed && wasActive {
			live = append(live, j.ID)
		}
		if confirmed && wasActive {
			update := *j
			update.State = store.JobCompleted
			update.Conclusion = "cancelled"
			update.CompletedAt = &now
			saved, change, applyErr := c.st.ApplyJob(ctx, &update)
			if applyErr != nil {
				errs = append(errs, fmt.Errorf("cancelling job %s with its workflow run: %w", j.ID, applyErr))
			} else {
				c.recordJobChange(ctx, saved, change, sourceController, nil)
				if change.StateChanged {
					c.observeJobCompletion(saved)
				}
				c.publishJob(ctx, saved)
			}
		}

		// Only a job that was still running when the run-wide cancellation
		// arrived owns live work. Completed siblings may have had their runner
		// reused by another run and must never be torn down here.
		if j.State == store.JobInProgress && j.RunnerID != "" {
			if err := c.stopCancelledJobRunner(ctx, j); err != nil {
				errs = append(errs, err)
			}
		}
	}
	if len(queued) > 0 {
		if _, err := c.st.ControlProvisioning(ctx, queued, "pause"); err != nil {
			errs = append(errs, fmt.Errorf("suppressing queued jobs in cancelled workflow run: %w", err))
		}
	}
	// Stamped after the pause, so one publish carries both: the frame is the
	// job's GET shape and the UI drops it straight into its cache, so sending
	// it twice would paint the job as merely paused for a moment first.
	if len(live) > 0 {
		stamped, err := c.st.MarkCancelRequested(ctx, live, now)
		if err != nil {
			errs = append(errs, fmt.Errorf("recording the cancellation against the run's jobs: %w", err))
		} else if len(stamped) > 0 {
			c.log.Info("a cancelled workflow run's jobs are waiting on GitHub to confirm",
				"repo", repo, "run", runID, "jobs", len(stamped))
		}
	}
	// `live` is every job `queued` holds and the running ones besides, so one
	// pass over it announces both changes once each.
	for _, id := range live {
		if j, getErr := c.st.GetJob(ctx, id); getErr == nil {
			c.publishJob(ctx, j)
		}
	}
	c.Nudge()
	return errors.Join(errs...)
}

// stopCancelledJobRunner detaches the job before forcing removal. That avoids
// recording a fleet fault: GitHub cancelled this work; the runner did not fail
// underneath it.
func (c *Controller) stopCancelledJobRunner(ctx context.Context, j *store.Job) error {
	r, err := c.st.GetRunner(ctx, j.RunnerID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		return err
	}
	if r.CurrentJobID != j.ID {
		return nil
	}
	finished, changed, err := c.st.CompleteRunnerJob(ctx, r.ID, j.ID,
		fmt.Sprintf("workflow run %d was cancelled", j.GitHubRunID))
	if err != nil {
		return fmt.Errorf("releasing runner %s from cancelled workflow run: %w", r.ID, err)
	}
	if changed {
		c.publishRunner(ctx, events.KindRunnerUpdated, finished)
	}
	if finished.State == store.RunnerRemoved {
		c.enqueueLifecycle(ctx, finished.HostID, agent.Task{
			Kind: agent.TaskRemoveRunner, RunnerID: finished.ID,
			Backend: c.backendKind(ctx, finished, nil),
		})
		return nil
	}
	return c.removeRunnerID(ctx, finished.ID,
		fmt.Sprintf("GitHub workflow run %d was cancelled", j.GitHubRunID), nil)
}

// RerunJobWorkflow asks GitHub to run the failed jobs of this job's run again.
//
// This is what Zoomies can actually do about a failure it caused. A job the
// fleet broke did not fail on its merits -- nothing about the workflow has
// changed, and the ordinary remedy is to run it again -- but until now an
// operator had to notice the fault, work out that it was the fleet's, find the
// run on GitHub and press the button there.
//
// Three things it deliberately does not do:
//
// It does not re-run by itself. GitHub minutes are the operator's to spend, a
// fleet that re-runs its own failures can loop on a fault it is causing every
// time, and a job that failed may have had side effects the person who wrote
// it knows about and this does not.
//
// It does not restrict itself to fleet faults. The check is that the job
// failed, not whose fault it was: an operator who has looked at a failure and
// decided to run it again is entitled to, and a button that refused on a
// judgement Zoomies made about blame would be a button people learn to route
// around. What the fault category does is decide where the button is offered.
//
// And it does not touch the local row. The re-run arrives as new deliveries
// with a higher run attempt, through the same webhook path as everything else;
// writing an outcome here would be the fleet inventing one.
func (c *Controller) RerunJobWorkflow(ctx context.Context, jobID string) (*store.Job, error) {
	j, err := c.st.GetJob(ctx, jobID)
	if err != nil {
		return nil, err
	}
	if j.State != store.JobCompleted {
		return nil, ErrJobNotFinished
	}
	if !j.Failed() {
		return nil, ErrJobDidNotFail
	}
	if j.InstallationID == "" || j.Repo == "" || j.GitHubRunID <= 0 {
		return nil, fmt.Errorf("job %s has no GitHub installation and workflow run to re-run", j.ID)
	}
	if err := c.askGitHubToRerun(ctx, j, rerunByOperator); err != nil {
		return nil, err
	}
	return j, nil
}

// Who asked for a re-run. It is the metric's label and the difference between
// the two sentences a timeline entry can carry, and the two are deliberately
// not interchangeable: one is a person who looked at the failure and decided,
// the other is a setting somebody turned on weeks ago.
const (
	rerunByOperator = "operator"
	rerunByFault    = "fleet_fault"
)

// askGitHubToRerun makes the call, writes the timeline entry and counts the
// metric. It is shared by the button and by the automatic path so the two
// cannot drift into asking GitHub for different things.
func (c *Controller) askGitHubToRerun(ctx context.Context, j *store.Job, trigger string) error {
	client, err := c.ClientFor(ctx, j.InstallationID)
	if err != nil {
		return err
	}
	who := "an operator"
	source := sourceController
	if trigger == rerunByFault {
		who = "this fleet"
		source = sourceRecovery
	}
	// One job where we can, the whole run's failures only where we cannot.
	// GitHub's job-level re-run takes the job and whatever names it in
	// `needs`; the run-level one takes every failure in the run, which for
	// somebody who asked about one job is three other teams' jobs running
	// again on their account.
	var message string
	if j.GitHubJobID > 0 {
		if err := client.RerunWorkflowJob(ctx, j.Repo, j.GitHubJobID); err != nil {
			return err
		}
		message = fmt.Sprintf("%s asked GitHub to run job %d again; GitHub runs it together with any job that needs it, and they arrive as a new run attempt", who, j.GitHubJobID)
	} else {
		// A job recorded before this fleet kept GitHub's job ID, or one whose
		// workflow_job delivery never arrived. The wider call is still better
		// than refusing the button.
		if err := client.RerunFailedWorkflowJobs(ctx, j.Repo, j.GitHubRunID); err != nil {
			return err
		}
		message = fmt.Sprintf("%s asked GitHub to run the failed jobs of workflow run %d again, because this job has no GitHub job ID recorded; GitHub reruns them together, and they arrive as a new run attempt", who, j.GitHubRunID)
	}
	switch {
	case trigger == rerunByFault:
		message += fmt.Sprintf(", because a runner stopped under it and scheduler.auto_rerun is on. This is attempt %d of the %d this run may be given", c.runAttempt(j)+1, c.cfg().Scheduler.AutoRerunLimit+1)
	case j.FleetFailed():
		message += ". This job's failure was the fleet's rather than the workflow's"
	}
	if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
		JobID: j.ID, Kind: store.JobEventRerunRequested, Source: source,
		Message: message, At: c.Now(),
	}); err != nil {
		return err
	}
	c.metrics.jobReruns.WithLabelValues(c.poolLabel(j.PoolID), trigger).Inc()
	c.log.Info("asked GitHub to re-run a run's failed jobs",
		"job", j.ID, "repo", j.Repo, "run", j.GitHubRunID, "fault", j.FaultKind, "trigger", trigger)
	c.publishJob(ctx, j)
	return nil
}

// A job's timeline is the answer to "what happened to my job?", told in the
// order it happened and in sentences an operator can read without knowing how
// Zoomies works. The jobs row holds the current truth; the timeline holds how
// it got there, and it is the only place a fault on the fleet's side -- a runner
// that died under a job -- is written down next to the job it cost.
//
// Entries are written from what the store says changed, never from what a
// delivery said. GitHub delivers at least once and out of order, so "a queued
// delivery arrived" is not the same fact as "the job was queued".

// Where a timeline entry came from.
const (
	sourceWebhook    = "webhook"
	sourcePoller     = "poller"
	sourceAgent      = "agent"
	sourceController = "controller"
	// A re-run the fleet decided on rather than a person. It is its own source
	// so a timeline reads "via recovery" and nobody has to work out which
	// operator pressed a button that was never pressed.
	sourceRecovery = "recovery"
)

// recordJobChange writes the timeline entries a job change earned.
//
// runner is this fleet's row for the runner the delivery named, when there is
// one; a job that started on a runner Zoomies did not start is recorded as such,
// because "it ran somewhere else" is the whole explanation of why the fleet's
// numbers do not include it.
func (c *Controller) recordJobChange(ctx context.Context, j *store.Job, change store.JobChange, source string, runner *store.Runner) {
	if j == nil {
		return
	}
	c.stampJobVersions(ctx, j, runner)
	c.observeScheduling(ctx, j, change, runner)
	at := c.Now()
	add := func(kind store.JobEventKind, message string) {
		e := &store.JobEvent{JobID: j.ID, Kind: kind, Source: source, Message: message, At: at}
		if runner != nil && (kind == store.JobEventStarted || kind == store.JobEventCompleted) {
			e.RunnerID, e.RunnerName = runner.ID, runner.Name
		} else if kind == store.JobEventStarted || kind == store.JobEventCompleted {
			e.RunnerID, e.RunnerName = j.RunnerID, j.RunnerName
		}
		if err := c.st.AppendJobEvent(ctx, e); err != nil {
			c.log.Warn("could not record a job timeline entry", "job", j.ID, "kind", kind, "error", err)
		}
	}

	if change.Created && j.State == store.JobWaiting {
		// Held by GitHub for a deployment review. The time it spends here is
		// GitHub's, not the queue's, so the first line says so rather than
		// calling the job queued; the claim line waits for the approval,
		// which is when it becomes true.
		add(store.JobEventWaiting, fmt.Sprintf("GitHub announced %s in %s, asking for [%s], and is holding it for a deployment review; nothing here can start it until it is approved",
			jobTitle(j), j.Repo, strings.Join(j.Labels, ", ")))
	} else if change.Created {
		add(store.JobEventQueued, fmt.Sprintf("GitHub queued %s in %s, asking for [%s]",
			jobTitle(j), j.Repo, strings.Join(j.Labels, ", ")))
		// Whether a pool answers the labels matters while the job is waiting.
		// A job first seen already running was answered by whatever runs it,
		// and the "started" line below says who that was.
		if j.State == store.JobQueued {
			add(c.claimKind(j), c.claimMessage(ctx, j))
		}
	} else if change.StateChanged && change.PreviousState == store.JobWaiting && j.State == store.JobQueued {
		// The approval arrives as an ordinary queued delivery. This is when
		// the queue wait starts, and when whether a pool claims it matters.
		add(store.JobEventApproved, "GitHub approved it, and it is queued for a runner from now")
		add(c.claimKind(j), c.claimMessage(ctx, j))
	} else if change.Claimed && j.State == store.JobQueued {
		add(store.JobEventClaimed, c.claimMessage(ctx, j))
	}

	if !change.StateChanged && !change.Created {
		return
	}
	// A job whose first delivery is already in progress or complete skipped
	// straight past "queued" here: the controller was down, or the webhook
	// never arrived. Each state it reached still gets its line.
	if j.State == store.JobInProgress || (j.State == store.JobCompleted && j.StartedAt != nil &&
		(change.Created || change.PreviousState == store.JobQueued)) {
		add(store.JobEventStarted, c.startMessage(ctx, j, runner))
	}
	if j.State == store.JobCompleted {
		add(store.JobEventCompleted, completionMessage(j))
		c.autoRerunFleetFailure(ctx, j)
	}
}

// runAttempt is GitHub's attempt number for this job's run, reading an
// unrecorded one as the first. A job from before the column existed, or one
// whose delivery carried no attempt, is on its first attempt as far as anyone
// can tell, and treating it as a later one would refuse the re-run that is the
// whole point.
func (c *Controller) runAttempt(j *store.Job) int {
	if j.RunAttempt < 1 {
		return 1
	}
	return j.RunAttempt
}

// autoRerunFleetFailure sends a job back to GitHub when this fleet is what
// broke it.
//
// A runner that dies under a job fails it in a way indistinguishable, on
// GitHub, from a test failure -- and the ordinary remedy for a job that did
// not fail on its merits is to run it again. Until this, somebody had to
// notice, work out that the fault was the fleet's, and press the button.
//
// It is off by default and narrow when on:
//
// Only the fleet's own failures. `FleetFailed` is the same predicate the Jobs
// page splits on, so what is re-run automatically is exactly what the fleet
// has already confessed to. A test that failed is never touched: re-running
// somebody's red build for them would be the fleet overruling their result.
//
// Only while GitHub's attempt number is under the limit. That is what stops a
// fault the fleet causes every time -- a host out of disk, an image that will
// not pull -- from re-running the same job until somebody notices the bill.
// The count comes from GitHub rather than from us, so a controller restart
// does not reset it and a re-run an operator asked for by hand counts too.
//
// Only once per completion. Deliveries are at-least-once, and a second
// "completed" for a job already completed does not change its state, so it
// does not reach here: the caller only runs this branch on a change.
//
// A failure to ask is logged and dropped. The button is still there, the job
// is still failed, and a fleet that cannot reach GitHub has a louder problem
// than this one already on the drawer.
func (c *Controller) autoRerunFleetFailure(ctx context.Context, j *store.Job) {
	cfg := c.cfg()
	if !cfg.Scheduler.AutoRerun || !j.FleetFailed() || !j.Failed() {
		return
	}
	if j.InstallationID == "" || j.Repo == "" || j.GitHubRunID <= 0 {
		return
	}
	if attempt := c.runAttempt(j); attempt > cfg.Scheduler.AutoRerunLimit {
		c.log.Info("not re-running a job the fleet broke: this run has had its automatic re-runs",
			"job", j.ID, "run", j.GitHubRunID, "attempt", attempt, "limit", cfg.Scheduler.AutoRerunLimit)
		return
	}
	if err := c.askGitHubToRerun(ctx, j, rerunByFault); err != nil {
		c.log.Warn("could not re-run a job the fleet broke",
			"job", j.ID, "run", j.GitHubRunID, "error", err)
	}
}

// claimKind is "claimed" or "unmatched", the two answers to "will anything
// here run it?".
func (c *Controller) claimKind(j *store.Job) store.JobEventKind {
	if j.Matched {
		return store.JobEventClaimed
	}
	return store.JobEventUnmatched
}

func (c *Controller) claimMessage(ctx context.Context, j *store.Job) string {
	if !j.Matched {
		// A job this fleet holds no credential for is refused for a reason its
		// labels cannot explain, and the timeline is read by the same person
		// the problems drawer is; telling them to check their runs-on here
		// while the drawer says the App is not installed would be worse than
		// saying nothing.
		if j.InstallationID == "" {
			return "no GitHub App installation here covers " + j.Repo +
				", so no pool can claim it whatever its labels say"
		}
		return "no enabled pool claims these labels, so nothing in this fleet will start it"
	}
	name := j.PoolID
	if p, err := c.st.GetPool(ctx, j.PoolID); err == nil {
		name = p.Name
	}
	return fmt.Sprintf("pool %s claims it; the scheduler will start a runner if none is free", name)
}

func (c *Controller) startMessage(ctx context.Context, j *store.Job, runner *store.Runner) string {
	if runner == nil && j.RunnerID != "" {
		if r, err := c.st.GetRunner(ctx, j.RunnerID); err == nil {
			runner = r
		}
	}
	switch {
	case runner != nil:
		host := runner.HostID
		if h, err := c.st.GetHost(ctx, runner.HostID); err == nil {
			host = h.Name
		}
		return fmt.Sprintf("started on runner %s, on host %s, after %s in the queue",
			runner.Name, host, roundDuration(j.QueueWait()))
	case j.RunnerName != "":
		return fmt.Sprintf("started on %s, a runner this fleet does not manage, after %s in the queue",
			j.RunnerName, roundDuration(j.QueueWait()))
	}
	return fmt.Sprintf("started after %s in the queue", roundDuration(j.QueueWait()))
}

// completionMessage is the one line a finished job is summarised by: what
// GitHub concluded, and where it went wrong when it did.
func completionMessage(j *store.Job) string {
	took := roundDuration(j.Duration())
	switch j.Conclusion {
	case "success":
		return fmt.Sprintf("succeeded after %s", took)
	case "cancelled":
		if step := j.FailedStep(); step != nil {
			return fmt.Sprintf("cancelled after %s, during step %d, %s", took, step.Number, step.Name)
		}
		return fmt.Sprintf("cancelled after %s", took)
	case "skipped":
		return "skipped: a condition on the job was false"
	case "":
		return fmt.Sprintf("finished after %s", took)
	}
	verb := "failed"
	if j.Conclusion != "failure" {
		verb = strings.ReplaceAll(j.Conclusion, "_", " ")
	}
	if step := j.FailedStep(); step != nil {
		return fmt.Sprintf("%s at step %d, %s, after %s", verb, step.Number, step.Name, took)
	}
	if j.RunnerFault != "" {
		return fmt.Sprintf("%s after %s; the runner had stopped under it", verb, took)
	}
	return fmt.Sprintf("%s after %s", verb, took)
}

// noteOOMKilled marks the job a runner ran last as killed for memory, writes
// its timeline entry and publishes it. It is idempotent for the reason
// noteRunnerLost is: the same exit reaches here from a report and again from
// a task result, and only the call that marked the job writes the entry.
func (c *Controller) noteOOMKilled(ctx context.Context, r *store.Runner, message string) {
	if message == "" {
		message = "the kernel killed a process in it for its memory limit"
	}
	sentence := fmt.Sprintf("runner %s was killed for memory on host %s: %s", r.Name, r.HostID, message)
	j, marked, err := c.st.MarkJobOOMKilled(ctx, r.ID, sentence)
	if err != nil {
		c.log.Warn("could not record an out-of-memory kill on its job", "runner", r.ID, "error", err)
		return
	}
	if j == nil || !marked {
		return
	}
	if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
		JobID: j.ID, Kind: store.JobEventOOMKilled, Source: sourceAgent,
		Message: sentence, RunnerID: r.ID, RunnerName: r.Name, At: c.Now(),
	}); err != nil {
		c.log.Warn("could not record a job timeline entry", "job", j.ID, "kind", store.JobEventOOMKilled, "error", err)
	}
	c.publishJob(ctx, j)
}

// noteRunnerLost records that a runner stopped while it was still executing a
// job. GitHub will report the job as failed in its own time, indistinguishable
// from a test failure; this is what tells the operator the fleet did it.
//
// before is the runner as it was before the transition, because the store
// clears CurrentJobID when a runner goes terminal and the job's identity would
// otherwise be gone by the time anyone asked. source says who saw it go: the
// agent, when the container died on its own; the controller, when an operator
// removed a busy runner with force or the reconcile loop gave up on it.
//
// fault is the category, decided by whoever saw the runner stop: the agent
// from an exit code or the daemon's own reply, the controller from its own
// decision to give up on a host. It is a parameter rather than something read
// back out of message, because the evidence is gone by the time the sentence
// is written.
//
// It is idempotent. The same exit can reach here more than once -- a runner
// report and then the task result that carries it -- and only the report that
// records the fault writes the timeline entry and counts the metric.
func (c *Controller) noteRunnerLost(ctx context.Context, before *store.Runner, source, message string, fault store.FaultKind) {
	if before == nil || before.CurrentJobID == "" {
		return
	}
	j, err := c.st.GetJob(ctx, before.CurrentJobID)
	if err != nil {
		return
	}
	if j.State == store.JobCompleted {
		// GitHub already closed the job; the runner exiting afterwards is the
		// normal end of an ephemeral runner's life, whatever its exit code.
		return
	}
	if message == "" {
		message = "the runner stopped without saying why"
	}
	sentence := fmt.Sprintf("runner %s stopped while this job was running: %s", before.Name, message)
	updated, recorded, err := c.st.SetJobRunnerFault(ctx, j.ID, sentence, fault)
	if err != nil {
		c.log.Warn("could not record a lost runner on its job", "job", j.ID, "runner", before.ID, "error", err)
		return
	}
	if !recorded {
		return
	}
	if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
		JobID: j.ID, Kind: store.JobEventRunnerLost, Source: source,
		Message:  sentence + "; GitHub will report the job failed once the runner's absence is noticed",
		RunnerID: before.ID, RunnerName: before.Name, At: c.Now(),
	}); err != nil {
		c.log.Warn("could not record a job timeline entry", "job", j.ID, "kind", store.JobEventRunnerLost, "error", err)
	}
	c.metrics.jobsRunnerLost.WithLabelValues(c.poolLabel(before.PoolID)).Inc()
	c.metrics.jobFailures.WithLabelValues(c.poolLabel(before.PoolID), store.FaultDomainFleet, string(updated.FaultKind)).Inc()
	c.log.Warn("a runner stopped while running a job",
		"job", j.ID, "runner", before.ID, "name", before.Name, "fault", updated.FaultKind, "message", message)
	c.publishJob(ctx, updated)
}

// startFailureFanout caps how many waiting jobs one failed start is written
// onto. A pool that cannot start a container fails every attempt, and a fleet
// with three hundred jobs queued against it would otherwise spend a reconcile
// pass writing three hundred timeline rows that all say the same sentence.
// The problems panel carries the scale; the timeline carries the news.
const startFailureFanout = 20

// noteRunnerStartFailure tells the jobs waiting on a pool that a runner meant
// for work like theirs died before it could take any.
//
// This is the failure that reached nothing before. A runner that fails while
// executing a job has a job to be recorded on; a runner that fails on the way
// up has none -- it was created for a pool, not for a job -- so from the Jobs
// page a pool whose containers will not start was indistinguishable from a
// pool that was merely busy, and the operator watching a queue that never
// moved had nowhere to find out which.
//
// It deliberately does not fail the jobs. They are still queued, the next
// runner may well run them, and Zoomies concluding a job GitHub still has open
// would be the fleet inventing an outcome. What it writes is a note.
func (c *Controller) noteRunnerStartFailure(ctx context.Context, before, failed *store.Runner) {
	if failed == nil || failed.PoolID == "" {
		return
	}
	// A runner that had a job is the other case entirely, and noteRunnerLost
	// has already recorded it on the job it was running.
	if before != nil && before.CurrentJobID != "" {
		return
	}
	// Registering counts as never having started: the container may exist, but
	// nothing has ever handed it a job and nothing now will.
	if before != nil && before.State != store.RunnerProvisioning && before.State != store.RunnerRegistering {
		return
	}
	queued, err := c.st.ListQueuedJobs(ctx)
	if err != nil {
		c.log.Warn("could not list queued jobs to note a failed runner start", "runner", failed.ID, "error", err)
		return
	}
	written := 0
	for _, j := range queued {
		if written >= startFailureFanout {
			break
		}
		if j.PoolID != failed.PoolID {
			continue
		}
		// One entry per job per run of failures. A pool stuck in a start loop
		// tries again every pass, and a timeline is opened to avoid reading a
		// log file rather than to read one.
		last, err := c.st.LastJobEventKind(ctx, j.ID)
		if err != nil {
			c.log.Warn("could not read a job's last timeline entry", "job", j.ID, "error", err)
			continue
		}
		if last == store.JobEventRunnerStartFailed {
			continue
		}
		if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
			JobID: j.ID, Kind: store.JobEventRunnerStartFailed, Source: sourceController,
			Message: fmt.Sprintf("a runner this pool started for work like this one never took a job: %s. "+
				"This job is still queued and the next runner may run it", failed.Message),
			RunnerID: failed.ID, RunnerName: failed.Name, At: c.Now(),
		}); err != nil {
			c.log.Warn("could not record a job timeline entry", "job", j.ID, "kind", store.JobEventRunnerStartFailed, "error", err)
			continue
		}
		written++
	}
	c.metrics.runnerStartFailures.WithLabelValues(c.poolLabel(failed.PoolID), string(failed.FaultKind)).Inc()
}

// JobEvents returns a job's timeline, oldest first.
func (c *Controller) JobEvents(ctx context.Context, jobID string) ([]*store.JobEvent, error) {
	if _, err := c.st.GetJob(ctx, jobID); err != nil {
		return nil, err
	}
	return c.st.ListJobEvents(ctx, jobID)
}

func jobTitle(j *store.Job) string {
	switch {
	case j.Workflow != "" && j.JobName != "":
		return j.Workflow + " / " + j.JobName
	case j.JobName != "":
		return j.JobName
	case j.Workflow != "":
		return j.Workflow
	}
	return fmt.Sprintf("job %d", j.GitHubJobID)
}

// roundDuration renders a duration the way a person would say it: "42s",
// "3m 10s", "1h 05m". Sub-second precision is noise in a sentence.
func roundDuration(d time.Duration) string {
	if d <= 0 {
		return "no time"
	}
	d = d.Round(time.Second)
	switch {
	case d < time.Minute:
		return fmt.Sprintf("%ds", int(d.Seconds()))
	case d < time.Hour:
		return fmt.Sprintf("%dm %02ds", int(d.Minutes()), int(d.Seconds())%60)
	}
	return fmt.Sprintf("%dh %02dm", int(d.Hours()), int(d.Minutes())%60)
}

// staleQueuedAfter is how long a job may sit queued before the controller
// stops believing GitHub still has it. GitHub itself cancels a job that no
// runner has picked up within a day, and it is the completed delivery for a
// job like that -- or one whose repository was deleted, or whose run was
// cancelled while the poller was rate-limited -- that goes missing.
const staleQueuedAfter = 24 * time.Hour

// expireStaleQueuedJobs retires queued jobs older than staleQueuedAfter.
//
// A queued row is scheduler demand for as long as it exists: it keeps a pool's
// desired count up, so a runner is created for it, idles out, and is created
// again, for ever. Nothing else reconciles a row GitHub no longer lists, so
// this marks it completed with the conclusion GitHub uses for the same thing,
// "stale", and the timeline says why.
func (c *Controller) expireStaleQueuedJobs(ctx context.Context, now time.Time) {
	// Asked for by age rather than filtered here, because this is the one
	// sweep that wants the jobs an operator removed from the queue as well:
	// the removal stopped them counting as demand, and this is what stops them
	// sitting in the Queue's removed view for ever.
	queued, err := c.st.ListStaleQueuedJobs(ctx, now.Add(-staleQueuedAfter))
	if err != nil {
		c.log.Warn("could not list queued jobs to retire stale ones", "error", err)
		return
	}
	retired := 0
	for _, j := range queued {
		age := now.Sub(j.QueuedAt)
		done := now
		saved, change, err := c.st.ApplyJob(ctx, &store.Job{
			GitHubJobID: j.GitHubJobID, State: store.JobCompleted, Conclusion: "stale", CompletedAt: &done,
		})
		if err != nil {
			c.log.Warn("could not retire a stale queued job", "job", j.ID, "error", err)
			continue
		}
		if !change.StateChanged {
			continue
		}
		message := fmt.Sprintf("queued for %s with no word from GitHub that it started; GitHub gives up on a job after a day, so this one is presumed cancelled or lost and is no longer counted as demand",
			age.Truncate(time.Minute))
		if err := c.st.AppendJobEvent(ctx, &store.JobEvent{
			JobID: saved.ID, Kind: store.JobEventCompleted, Source: sourceController, Message: message, At: now,
		}); err != nil {
			c.log.Warn("could not record a job timeline entry", "job", saved.ID, "kind", store.JobEventCompleted, "error", err)
		}
		c.log.Warn("retired a queued job GitHub never started", "job", saved.ID, "repo", saved.Repo, "queued_for", age.Truncate(time.Minute))
		c.publishJob(ctx, saved)
		retired++
	}
	if retired > 0 {
		// Demand has dropped, and a runner created for the retired job may
		// now be surplus.
		c.Nudge()
	}
}

package controller

import (
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func kindsOfEvents(events []*store.JobEvent) []store.JobEventKind {
	out := make([]store.JobEventKind, 0, len(events))
	for _, e := range events {
		out = append(out, e.Kind)
	}
	return out
}

// runnerLostTotal reads the lost-runner counter back through the registry, the
// way a scrape would, so the test needs nothing the production code does not.
func (h *harness) runnerLostTotal() float64 {
	h.t.Helper()
	families, err := h.c.metrics.reg.Gather()
	if err != nil {
		h.t.Fatalf("Gather: %v", err)
	}
	total := 0.0
	for _, mf := range families {
		if mf.GetName() != "zoomies_jobs_runner_lost_total" {
			continue
		}
		for _, m := range mf.GetMetric() {
			total += m.GetCounter().GetValue()
		}
	}
	return total
}

func (h *harness) timeline(jobID string) []*store.JobEvent {
	h.t.Helper()
	events, err := h.c.JobEvents(h.ctx, jobID)
	if err != nil {
		h.t.Fatalf("JobEvents: %v", err)
	}
	return events
}

// The timeline is the answer to "what happened to my job?", and it has to stay
// honest under GitHub's delivery guarantees: at least once, and out of order. A
// redelivery must not add a line, and a completed job must say where it failed
// in the words of the step that failed.
func TestJobDeliveriesWriteTheTimelineOnceEach(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 7007)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed}) {
		t.Fatalf("after queued: %v, want queued then claimed", got)
	}
	if !strings.Contains(events[0].Message, "CI / test") || !strings.Contains(events[0].Message, "acme/widgets") {
		t.Fatalf("queued entry does not name the job: %q", events[0].Message)
	}
	if !strings.Contains(events[1].Message, pool.Name) || events[1].Source != sourceWebhook {
		t.Fatalf("claimed entry = %+v, want the pool named and the webhook as source", events[1])
	}

	// GitHub sends the same delivery again.
	h.deliverJob(jobEvent{Action: "queued", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels})
	if got := h.timeline(job.ID); len(got) != 2 {
		t.Fatalf("a redelivered queued added a timeline entry: %v", kindsOfEvents(got))
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	r := h.onlyRunner()
	mustReport(t, h, host.ID, r.ID, store.RunnerRegistering)
	mustReportRunning(t, h, host.ID, r.ID)

	h.deliverJob(jobEvent{Action: "in_progress", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels, RunnerName: r.Name})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed, store.JobEventStarted}) {
		t.Fatalf("after in_progress: %v", got)
	}
	started := events[2]
	if !strings.Contains(started.Message, r.Name) || !strings.Contains(started.Message, host.Name) || started.RunnerID != r.ID {
		t.Fatalf("started entry = %+v, want the runner and its host named", started)
	}

	h.deliverJob(jobEvent{Action: "completed", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure", Steps: failingSteps()})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); len(got) != 4 || got[3] != store.JobEventCompleted {
		t.Fatalf("after completed: %v", got)
	}
	if want := "failed at step 2, Run tests"; !strings.Contains(events[3].Message, want) {
		t.Fatalf("completed entry = %q, want it to say %q", events[3].Message, want)
	}

	// And the row itself carries what the drawer shows.
	job, _ = h.st.GetJobByGitHubID(h.ctx, 7007)
	if step := job.FailedStep(); step == nil || step.Name != "Run tests" {
		t.Fatalf("FailedStep = %+v", step)
	}
	view := h.c.jobView(h.ctx, job)
	if view.FailedStep == nil || view.FailedStep.Number != 2 || len(view.Steps) != 3 {
		t.Fatalf("job view = %+v, want the failed step named and every step carried", view)
	}

	// A duplicate completed delivery is the commonest redelivery of all.
	h.deliverJob(jobEvent{Action: "completed", JobID: 7007, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure", Steps: failingSteps()})
	if got := h.timeline(job.ID); len(got) != 4 {
		t.Fatalf("a redelivered completed added a timeline entry: %v", kindsOfEvents(got))
	}
}

// An unmatched job says so on its timeline, and says when that changed: the
// operator who creates the missing pool should see the job claimed without
// having to work out which delivery did it.
func TestAnUnmatchedJobIsClaimedWhenAPoolAppears(t *testing.T) {
	h := newHarness(t)
	inst, _, _ := h.fleet()
	labels := []string{"self-hosted", "linux", "gpu"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 8008, Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 8008)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventUnmatched}) {
		t.Fatalf("timeline = %v, want queued then unmatched", got)
	}
	if !strings.Contains(events[1].Message, "no enabled pool") {
		t.Fatalf("unmatched entry does not explain itself: %q", events[1].Message)
	}

	gpu := h.pool(inst, "gpu", labels...)
	// GitHub redelivers, or the poller re-lists the queue; either way the
	// same payload arrives again and this time a pool answers it.
	h.deliverJob(jobEvent{Action: "queued", JobID: 8008, Labels: labels})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventQueued, store.JobEventUnmatched, store.JobEventClaimed}) {
		t.Fatalf("timeline = %v, want a claimed entry added", got)
	}
	if !strings.Contains(events[2].Message, gpu.Name) {
		t.Fatalf("claimed entry = %q, want the new pool named", events[2].Message)
	}
}

// startJobOnRunner takes a job from queued to running on a runner this fleet
// started, the way the real sequence does.
func startJobOnRunner(t *testing.T, h *harness, hostID string, jobID int64, labels []string) (*store.Job, *store.Runner) {
	t.Helper()
	h.deliverJob(jobEvent{Action: "queued", JobID: jobID, Name: "test", Workflow: "CI", Labels: labels})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	r := h.onlyRunner()
	mustReport(t, h, hostID, r.ID, store.RunnerRegistering)
	mustReportRunning(t, h, hostID, r.ID)
	h.deliverJob(jobEvent{Action: "in_progress", JobID: jobID, Name: "test", Workflow: "CI", Labels: labels, RunnerName: r.Name})
	job, err := h.st.GetJobByGitHubID(h.ctx, jobID)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if job.RunnerID != r.ID {
		t.Fatalf("the job was not linked to runner %s", r.ID)
	}
	return job, r
}

// A runner that dies under a job produces a failure GitHub cannot tell from a
// test failure. The job has to say the fleet did it: on the row, on the
// timeline, in the problems drawer, and in the failed filter -- before GitHub
// has even noticed.
func TestARunnerFailingUnderItsJobIsRecordedOnTheJob(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 9009, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerFailed, ExitCode: 137,
		Message:    "runner exited with code 137: the container was killed for exceeding its memory limit",
		ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	after, err := h.st.GetJob(h.ctx, job.ID)
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if after.State != store.JobInProgress {
		t.Fatalf("job state = %q; GitHub has not said the job is over, so Zoomies must not", after.State)
	}
	if !strings.Contains(after.RunnerFault, r.Name) || !strings.Contains(after.RunnerFault, "code 137") {
		t.Fatalf("runner fault = %q, want the runner named and the agent's message kept", after.RunnerFault)
	}

	events := h.timeline(job.ID)
	last := events[len(events)-1]
	if last.Kind != store.JobEventRunnerLost || last.Source != sourceAgent || last.RunnerID != r.ID {
		t.Fatalf("last timeline entry = %+v, want runner_lost from the agent", last)
	}

	// The agent reports the same exit again -- a runner report and then the
	// task result that carries it both arrive -- and the failed runner is
	// terminal, so the second report is dropped by the state machine. The
	// job must still carry exactly one line and one count for it.
	before := h.runnerLostTotal()
	if before != 1 {
		t.Fatalf("zoomies_jobs_runner_lost_total = %v after one lost runner, want 1", before)
	}
	h.c.noteRunnerLost(h.ctx, r, sourceAgent, "runner exited with code 137: reported again", store.FaultOutOfMemory)
	if got := h.timeline(job.ID); len(got) != len(events) {
		t.Fatalf("a repeated report added a timeline entry: %v", kindsOfEvents(got))
	}
	if after := h.runnerLostTotal(); after != before {
		t.Fatalf("a repeated report counted the runner as lost again: %v -> %v", before, after)
	}
	if again, _ := h.st.GetJob(h.ctx, job.ID); !strings.Contains(again.RunnerFault, "memory limit") {
		t.Fatalf("a repeated report replaced the first fault: %q", again.RunnerFault)
	}

	if codes := h.problemCodes(); !slices.Contains(codes, "jobs.runner_lost") {
		t.Fatalf("problems = %v, want jobs.runner_lost", codes)
	}
	failed, total, err := h.st.ListJobs(h.ctx, store.JobFilter{FailedOnly: true}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if total != 1 || failed[0].ID != job.ID {
		t.Fatalf("failed jobs = %+v, want the orphaned job before GitHub reports it", failed)
	}

	// GitHub catches up, and the completed entry says the fleet's part in it.
	h.deliverJob(jobEvent{Action: "completed", JobID: 9009, Name: "test", Workflow: "CI", Labels: labels,
		RunnerName: r.Name, Conclusion: "failure"})
	events = h.timeline(job.ID)
	done := events[len(events)-1]
	if done.Kind != store.JobEventCompleted || !strings.Contains(done.Message, "the runner had stopped under it") {
		t.Fatalf("completed entry = %+v", done)
	}
	if after, _ = h.st.GetJob(h.ctx, job.ID); after.RunnerFault == "" {
		t.Fatal("the completed delivery erased the fault")
	}
}

// An ephemeral runner exits after every job, and GitHub's completed delivery
// races the agent noticing. A clean exit is never a fault, whichever arrives
// first -- or every finished job would be reported as a runner lost.
func TestACleanExitUnderAJobIsNotAFault(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 1010, labels)

	err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{{
		RunnerID: r.ID, State: store.RunnerRemoved, Message: "ephemeral runner exited cleanly after its job", ObservedAt: time.Now(),
	}})
	if err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}
	after, _ := h.st.GetJob(h.ctx, job.ID)
	if after.RunnerFault != "" {
		t.Fatalf("a clean exit was recorded as a fault: %q", after.RunnerFault)
	}
	for _, e := range h.timeline(job.ID) {
		if e.Kind == store.JobEventRunnerLost {
			t.Fatalf("a clean exit wrote a runner_lost entry: %+v", e)
		}
	}
	if codes := h.problemCodes(); slices.Contains(codes, "jobs.runner_lost") {
		t.Fatalf("problems = %v; a clean exit is not a lost runner", codes)
	}
}

// Force-removing a busy runner is the operator's decision, and the job it was
// running is the one that pays for it. The job's timeline should say so rather
// than leaving GitHub's "failure" to be blamed on the tests.
func TestForceRemovingABusyRunnerIsRecordedOnItsJob(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}
	job, r := startJobOnRunner(t, h, host.ID, 1111, labels)

	if _, err := h.c.RemoveRunner(h.ctx, r.ID, "removed by an operator", true, false); err != nil {
		t.Fatalf("RemoveRunner: %v", err)
	}
	after, _ := h.st.GetJob(h.ctx, job.ID)
	if !strings.Contains(after.RunnerFault, "removed by an operator") {
		t.Fatalf("runner fault = %q, want the operator's reason", after.RunnerFault)
	}
	// The agent did not see this one go; the controller did it, and the
	// timeline says so rather than blaming the host.
	events := h.timeline(job.ID)
	if last := events[len(events)-1]; last.Kind != store.JobEventRunnerLost || last.Source != sourceController {
		t.Fatalf("last timeline entry = %+v, want runner_lost from the controller", last)
	}

	// Without force the runner drains, the job keeps running, and nothing is
	// written against it.
	h2 := newHarness(t)
	_, _, host2 := h2.fleet()
	job2, r2 := startJobOnRunner(t, h2, host2.ID, 1212, labels)
	if _, err := h2.c.RemoveRunner(h2.ctx, r2.ID, "removed by an operator", false, true); err != nil {
		t.Fatalf("RemoveRunner without force: %v", err)
	}
	if after2, _ := h2.st.GetJob(h2.ctx, job2.ID); after2.RunnerFault != "" {
		t.Fatalf("a drain was recorded as a fault: %q", after2.RunnerFault)
	}
}

func TestCompletionMessagesReadAsSentences(t *testing.T) {
	started := time.Date(2026, 1, 1, 10, 0, 0, 0, time.UTC)
	done := started.Add(3*time.Minute + 10*time.Second)
	base := store.Job{State: store.JobCompleted, StartedAt: &started, CompletedAt: &done}
	cases := []struct {
		name string
		mod  func(j *store.Job)
		want string
	}{
		{"success", func(j *store.Job) { j.Conclusion = "success" }, "succeeded after 3m 10s"},
		{"failure without steps", func(j *store.Job) { j.Conclusion = "failure" }, "failed after 3m 10s"},
		{"failure at a step", func(j *store.Job) {
			j.Conclusion = "failure"
			j.Steps = store.JobSteps{{Number: 1, Name: "Checkout", Conclusion: "success"}, {Number: 2, Name: "Run tests", Conclusion: "failure"}}
		}, "failed at step 2, Run tests, after 3m 10s"},
		{"timed out", func(j *store.Job) { j.Conclusion = "timed_out" }, "timed out after 3m 10s"},
		{"cancelled", func(j *store.Job) { j.Conclusion = "cancelled" }, "cancelled after 3m 10s"},
		{"runner lost", func(j *store.Job) { j.Conclusion = "failure"; j.RunnerFault = "x" }, "the runner had stopped under it"},
	}
	for _, tc := range cases {
		j := base
		tc.mod(&j)
		if got := completionMessage(&j); !strings.Contains(got, tc.want) {
			t.Errorf("%s: %q does not contain %q", tc.name, got, tc.want)
		}
	}
	if got := roundDuration(90 * time.Minute); got != "1h 30m" {
		t.Errorf("roundDuration(90m) = %q", got)
	}
}

// A job GitHub holds for a deployment review spends that time on GitHub, not
// in the queue. The timeline says so, and the approval is the moment the queue
// wait and the claim start, so a redelivered approval must not repeat either.
func TestAHeldJobsTimelineSaysWhoItWasWaitingFor(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "waiting", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	job, err := h.st.GetJobByGitHubID(h.ctx, 8201)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	events := h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventWaiting}) {
		t.Fatalf("after waiting: %v, want one waiting entry and no queued one", got)
	}
	if !strings.Contains(events[0].Message, "deployment review") || !strings.Contains(events[0].Message, "Release / deploy") {
		t.Fatalf("waiting entry does not say who is holding the job: %q", events[0].Message)
	}

	h.deliverJob(jobEvent{Action: "queued", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	events = h.timeline(job.ID)
	if got := kindsOfEvents(events); !slices.Equal(got, []store.JobEventKind{store.JobEventWaiting, store.JobEventApproved, store.JobEventClaimed}) {
		t.Fatalf("after approval: %v, want waiting, approved, then the claim", got)
	}
	if !strings.Contains(events[1].Message, "approved") || !strings.Contains(events[2].Message, pool.Name) {
		t.Fatalf("approval entries = %q, %q; want the approval said and the pool named", events[1].Message, events[2].Message)
	}

	// GitHub sends the approval again.
	h.deliverJob(jobEvent{Action: "queued", JobID: 8201, Name: "deploy", Workflow: "Release", Labels: labels})
	if got := h.timeline(job.ID); len(got) != 3 {
		t.Fatalf("a redelivered approval added a timeline entry: %v", kindsOfEvents(got))
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// lostRunnerOnAJob builds the situation the late-report path exists for: a
// runner executing a job, whose host went quiet long enough that the
// controller gave up and failed it as lost.
//
// It goes through failRunnerID rather than writing the row, because the point
// of the fixture is the state the reclaim actually leaves behind -- including
// the cleared current_job_id, which is why the job has to be found from the
// other end.
func lostRunnerOnAJob(t *testing.T, h *harness) (*store.Runner, *store.Job) {
	t.Helper()
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)

	h.deliverJob(jobEvent{Action: "queued", JobID: 8801, Name: "build", Workflow: "CI",
		Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 8801, Name: "build", Workflow: "CI",
		Labels: []string{"self-hosted", "linux", "x64", "demo"}, RunnerName: r.Name})

	job, err := h.st.GetJobByGitHubID(h.ctx, 8801)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if job.RunnerID != r.ID {
		t.Fatalf("job.RunnerID = %q, want the runner %q; the fixture needs the job linked", job.RunnerID, r.ID)
	}
	if err := h.st.AssignRunnerJob(h.ctx, r.ID, job.ID); err != nil {
		t.Fatalf("AssignRunnerJob: %v", err)
	}
	if err := h.c.failRunnerID(h.ctx, r.ID, "host went quiet", store.FaultHostLost); err != nil {
		t.Fatalf("failRunnerID: %v", err)
	}
	lost, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if lost.State != store.RunnerFailed {
		t.Fatalf("state = %q, want failed", lost.State)
	}
	_ = host
	return lost, job
}

func liveReport(r *store.Runner) []agent.RunnerReport {
	return []agent.RunnerReport{{RunnerID: r.ID, Phase: backend.PhaseRunning, ObservedAt: time.Now()}}
}

// "Lost" is a guess made from silence. A network partition, a long agent
// restart or a paused VM all end with the host back and the container exactly
// where it was, still executing its job -- and before this the report was
// dropped as an illegal transition, so the row stayed failed, the agent kept
// the workload because the controller never disowned it, and the container ran
// for ever on a host nobody was accounting for.
//
// The row is not resurrected: the fleet has already told an operator, and this
// job's timeline, that the runner was gone. What it must do is stop lying in
// the message and leave the job alone to finish.
func TestARunnerThatComesBackStillWorkingKeepsItsJob(t *testing.T) {
	h := newHarness(t)
	r, job := lostRunnerOnAJob(t, h)

	if err := h.c.ReportRunners(h.ctx, r.HostID, liveReport(r)); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	after, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if after.State != store.RunnerFailed {
		t.Fatalf("state = %q, want it to stay failed: a terminal row is what the timeline already reported", after.State)
	}
	if after.Message == r.Message {
		t.Fatalf("message = %q, unchanged; an operator reading the row is still told it is gone", after.Message)
	}
	if h.hasTaskOfKind(r.HostID, agent.TaskRemoveRunner) {
		t.Fatal("a remove task was queued while the job was still running; that fails a job for tidiness")
	}

	var returned int
	for _, e := range h.timeline(job.ID) {
		if e.Kind == store.JobEventRunnerReturned {
			returned++
		}
	}
	if returned != 1 {
		t.Fatalf("runner_returned entries = %d, want exactly 1", returned)
	}
}

// A host reports every runner on every heartbeat, so the timeline entry needs
// a guard: without one, a job that takes ten minutes to finish collects one
// identical line per heartbeat and the timeline becomes unreadable.
func TestARunnerThatKeepsReportingWritesOneReturnedEntry(t *testing.T) {
	h := newHarness(t)
	r, job := lostRunnerOnAJob(t, h)

	for range 5 {
		if err := h.c.ReportRunners(h.ctx, r.HostID, liveReport(r)); err != nil {
			t.Fatalf("ReportRunners: %v", err)
		}
	}

	var returned int
	for _, e := range h.timeline(job.ID) {
		if e.Kind == store.JobEventRunnerReturned {
			returned++
		}
	}
	if returned != 1 {
		t.Fatalf("runner_returned entries = %d after five heartbeats, want exactly 1", returned)
	}
}

// The other half. Once the job is over, the container is genuinely litter: the
// row is terminal, the slot has already been given to a replacement, and
// nothing else in the system will ever remove it -- the agent keeps it tracked
// precisely because the controller still has a row for it.
func TestARunnerThatComesBackWithNoJobLeftIsRemoved(t *testing.T) {
	h := newHarness(t)
	r, _ := lostRunnerOnAJob(t, h)

	h.deliverJob(jobEvent{Action: "completed", JobID: 8801, Name: "build", Workflow: "CI",
		Labels: []string{"self-hosted", "linux", "x64", "demo"}, RunnerName: r.Name, Conclusion: "success"})

	if err := h.c.ReportRunners(h.ctx, r.HostID, liveReport(r)); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}

	after, err := h.st.GetRunner(h.ctx, r.ID)
	if err != nil {
		t.Fatalf("GetRunner: %v", err)
	}
	if after.State != store.RunnerRemoved {
		t.Fatalf("state = %q, want removed once nothing is running on it", after.State)
	}
	if !h.hasTaskOfKind(r.HostID, agent.TaskRemoveRunner) {
		t.Fatal("no remove task was queued; the container would run on the host for ever")
	}
}

// A removed row is already the answer: the heartbeat names it as unknown, the
// agent releases it and the reconciler collects the workload. Reaching the
// late-report path for one would enqueue a second removal for a runner whose
// removal is already in flight.
func TestAReportForAnAlreadyRemovedRunnerQueuesNothing(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	if err := h.c.ReportRunners(h.ctx, host.ID, liveReport(r)); err != nil {
		t.Fatalf("ReportRunners: %v", err)
	}
	if h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
		t.Fatal("a remove task was queued for an already-removed runner")
	}
}

// A duplicated credential -- a cloned VM, or a state directory copied to
// another machine -- gives two agents one host id. From the controller's side
// they are indistinguishable: both hold a valid token and both report real
// work. What they cannot hide is handing the session back and forth.
//
// It is reported and not refused, by decision: both are running jobs, and
// picking one to reject would end the other's work on a coin toss.
func TestTwoAgentsOnOneHostAreReportedButNotRefused(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()

	h.c.NoteAgentSession(h.ctx, host.ID, "ses_one")
	h.c.NoteAgentSession(h.ctx, host.ID, "ses_two")
	if contains(h.problemCodes(), "host.duplicate_agent") {
		t.Fatalf("problems = %v; one change of session is an ordinary restart", h.problemCodes())
	}

	h.c.NoteAgentSession(h.ctx, host.ID, "ses_one")
	if !contains(h.problemCodes(), "host.duplicate_agent") {
		t.Fatalf("problems = %v, want host.duplicate_agent once the sessions swap back", h.problemCodes())
	}
}

// The problem ages out on its own. An operator who has stopped the second
// agent should not have to clear anything by hand, and a host that was
// duplicated last month is not a fault today.
func TestADuplicateAgentStopsBeingReportedOnceItIsGone(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()

	h.c.NoteAgentSession(h.ctx, host.ID, "ses_one")
	h.c.NoteAgentSession(h.ctx, host.ID, "ses_two")
	h.c.NoteAgentSession(h.ctx, host.ID, "ses_one")
	if !contains(h.problemCodes(), "host.duplicate_agent") {
		t.Fatalf("problems = %v, want the duplicate reported first", h.problemCodes())
	}

	h.advance(duplicateAgentWindow + time.Minute)
	if contains(h.problemCodes(), "host.duplicate_agent") {
		t.Fatalf("problems = %v; the duplicate should age out once the sessions stop swapping", h.problemCodes())
	}
}

package controller

import (
	"context"
	"errors"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

const (
	// LeaseTTL is how long a controller's claim on the database stands without
	// being renewed. It is comfortably longer than the renewal interval, so a
	// slow disk or a paused process does not lose a lease it still holds, and
	// short enough that a controller killed rather than stopped does not keep
	// a fleet waiting for long.
	LeaseTTL = 90 * time.Second
	// leaseRenew is how often the holder stamps the row. Three renewals fit
	// inside the TTL, which is the same ratio the host heartbeat uses.
	leaseRenew = 30 * time.Second
)

// leaseLoop keeps this controller's claim on the database current, and notices
// when it no longer has one.
//
// Losing the lease is not recoverable by retrying: another controller is now
// running against the same database, and both are scheduling. This says so,
// loudly and permanently, rather than trying to take it back -- a lease this
// process fights another for would flap between them, and two controllers each
// convinced they are the only one is exactly the state the lease exists to
// prevent.
func (c *Controller) leaseLoop(ctx context.Context) {
	t := time.NewTicker(leaseRenew)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
		}
		renewedAt := c.Now()
		held, err := c.st.RenewControllerLease(ctx, c.lease.Holder)
		switch {
		case ctx.Err() != nil:
			return
		case errors.Is(err, store.ErrConflict), errors.Is(err, store.ErrNotFound):
			if c.leaseLost.Load() == nil {
				c.log.Error("another controller has taken this database's lease; two controllers are now running against it",
					"holder", holderName(held), "ours", c.lease.Holder)
			}
			if held == nil {
				// The row was deleted rather than taken. Somebody else's
				// clean shutdown, or a hand-edited database; either way this
				// controller can no longer prove it is the only one.
				held = &store.ControllerLease{Holder: "nobody"}
			}
			c.leaseLost.Store(held)
		case err == nil:
			at := renewedAt
			c.leaseRenewed.Store(&at)
		case err != nil:
			// A transient write failure is not a lost lease, and the TTL is
			// three renewals wide precisely so one of these costs nothing.
			c.log.Warn("could not renew the controller lease", "error", err)
		}
	}
}

func holderName(l *store.ControllerLease) string {
	if l == nil {
		return "nobody"
	}
	return l.Describe()
}

// mayAct is checked at admission and again at dispatch: a plan prepared before
// a restore fence or lost lease must not become authority to mutate a host.
func (c *Controller) mayAct() bool {
	if c.Fenced().Fenced || c.leaseLost.Load() != nil {
		return false
	}
	if c.lease == nil {
		return true
	}
	renewed := c.lease.RenewedAt
	if at := c.leaseRenewed.Load(); at != nil {
		renewed = *at
	}
	return !renewed.IsZero() && c.Now().Before(renewed.Add(LeaseTTL))
}

package controller

import (
	"context"
	"errors"
	"fmt"
)

// ErrLimitReached marks a refusal because one of the limits.* ceilings has
// been reached. The API answers it with a 409 and the stable code
// limit_reached, since the request is well formed and would succeed on an
// instance with room: it is the state of the fleet that refuses it, not the
// request.
var ErrLimitReached = errors.New("limit reached")

// LimitError is ErrLimitReached with the setting that refused, so the message
// an operator reads names the key they would change -- or the one they would
// ask whoever runs the instance to change, since every limit is platform-scoped.
type LimitError struct {
	Setting string
	Limit   int
	What    string
	// Free says how to make room without changing the setting. Empty is
	// "remove one first", which is right for everything stored.
	Free string
}

func (e *LimitError) Error() string {
	free := e.Free
	if free == "" {
		free = "remove one first"
	}
	return fmt.Sprintf("this instance already holds %d %s, the most %s allows; %s, or ask whoever runs this instance to raise %s",
		e.Limit, e.What, e.Setting, free, e.Setting)
}

func (e *LimitError) Unwrap() error { return ErrLimitReached }

// admit refuses when a ceiling is set and adding n more would cross it. n is
// one for everything created a request at a time; the pools import is the
// caller that creates several at once, and checking them one at a time would
// let the whole batch through against a count that has not moved yet.
func admit(setting, what string, limit, n int, count func() (int, error)) error {
	if limit <= 0 || n <= 0 {
		return nil
	}
	held, err := count()
	if err != nil {
		return fmt.Errorf("counting %s for %s: %w", what, setting, err)
	}
	if held+n > limit {
		le := &LimitError{Setting: setting, Limit: limit, What: what}
		if n > 1 {
			// "Already holds" is only true of the ceiling, not of this
			// instance, when the batch is what crosses it.
			le.Free = fmt.Sprintf("this request adds %d more, so leave some out or remove one first", n)
		}
		return le
	}
	return nil
}

// AdmitPool says whether one more pool fits under limits.pools.
func (c *Controller) AdmitPool(ctx context.Context) error { return c.AdmitPools(ctx, 1) }

// AdmitPools says whether n more pools fit under limits.pools together.
func (c *Controller) AdmitPools(ctx context.Context, n int) error {
	return admit("limits.pools", "pools", c.cfg().Limits.Pools, n, func() (int, error) {
		return c.st.CountPools(ctx)
	})
}

// AdmitJoinToken says whether one more outstanding join token fits under
// limits.join_tokens.
func (c *Controller) AdmitJoinToken(ctx context.Context) error {
	return admit("limits.join_tokens", "outstanding join tokens", c.cfg().Limits.JoinTokens, 1, func() (int, error) {
		return c.st.CountOutstandingJoinTokens(ctx)
	})
}

// admitHost says whether one more host fits under limits.hosts.
func (c *Controller) admitHost(ctx context.Context) error {
	return admit("limits.hosts", "hosts", c.cfg().Limits.Hosts, 1, func() (int, error) {
		return c.st.CountHosts(ctx)
	})
}

package controller

import (
	"errors"
	"testing"
)

// limits.runners is decided in the scheduler, but it only protects anything
// if the reconcile loop hands it over: a pool's minimum above the ceiling must
// still leave the fleet at the ceiling.
func TestReconcileCreatesNoRunnerBeyondLimitsRunners(t *testing.T) {
	h := newHarness(t)
	h.cfg.Limits.Runners = 2
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	pool.MinRunners = 4
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.host("one")
	h.host("two")

	// Enough passes to reach the pool minimum of four, since registration is
	// admitted a runner at a time: without the ceiling this ends at four.
	for range 5 {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatalf("Reconcile: %v", err)
		}
		h.c.lifecycleCalls.Wait()
	}
	if n := len(h.runners()); n != 2 {
		t.Fatalf("runners = %d, want 2: limits.runners did not hold", n)
	}
}

func TestTheStoredLimitsRefuseAtTheirCeiling(t *testing.T) {
	h := newHarness(t)
	h.cfg.Limits.Pools = 1
	h.cfg.Limits.Hosts = 1
	inst := h.installation()

	if err := h.c.AdmitPool(h.ctx); err != nil {
		t.Fatalf("an empty instance refused a pool: %v", err)
	}
	h.pool(inst, "only")
	var le *LimitError
	if err := h.c.AdmitPool(h.ctx); !errors.As(err, &le) || le.Setting != "limits.pools" || !errors.Is(err, ErrLimitReached) {
		t.Fatalf("AdmitPool at the ceiling = %v, want a limits.pools LimitError", err)
	}

	if err := h.c.admitHost(h.ctx); err != nil {
		t.Fatalf("an empty instance refused a host: %v", err)
	}
	h.host("only")
	if err := h.c.admitHost(h.ctx); !errors.As(err, &le) || le.Setting != "limits.hosts" {
		t.Fatalf("admitHost at the ceiling = %v, want a limits.hosts LimitError", err)
	}

	h.cfg.Limits.Pools = 0
	if err := h.c.AdmitPool(h.ctx); err != nil {
		t.Fatalf("a ceiling of 0 refused a pool: %v", err)
	}
}

// The pools import creates several pools in one request, so the ceiling is on
// the total it would leave, not on whether there is room for one more.
func TestAdmitPoolsRefusesABatchThatWouldCrossTheCeiling(t *testing.T) {
	h := newHarness(t)
	h.cfg.Limits.Pools = 3
	inst := h.installation()
	h.pool(inst, "first")

	if err := h.c.AdmitPools(h.ctx, 2); err != nil {
		t.Fatalf("two more pools with room for two: %v", err)
	}
	var le *LimitError
	if err := h.c.AdmitPools(h.ctx, 3); !errors.As(err, &le) || le.Setting != "limits.pools" {
		t.Fatalf("three more pools with room for two = %v, want a limits.pools LimitError", err)
	}
	if err := h.c.AdmitPools(h.ctx, 0); err != nil {
		t.Fatalf("no new pools was refused: %v", err)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// Tunables for the relay. A browser tab that has been backgrounded stops
// reading its SSE connection, and a runner compiling something noisy produces
// megabytes a minute; the queue depth bounds how much of that is held for a
// reader who may never come back.
const (
	logSubscriberQueue = 512
	logReadChunk       = 32 << 10
	// logStreamBytesPerSecond and logStreamBurst are one stream's byte budget.
	// The subscriber queue bounds what is held for a slow reader; this bounds
	// what one agent can push through the relay at all, which is otherwise as
	// fast as it can write and is copied once per viewer. A megabyte a second
	// is more than any runner's output a person can read, and the burst
	// covers the backlog a stream opened with --tail sends at once.
	logStreamBytesPerSecond = 1 << 20
	logStreamBurst          = 8 << 20
)

// ErrStreamUnknown is returned when an agent posts a log stream nobody is
// waiting for, which happens whenever the last viewer closed the tab between
// the task being issued and the agent acting on it.
var ErrStreamUnknown = errors.New("controller: no log stream is open with that ID")

// logRelay fans a runner's output out to everyone watching it.
//
// The direction is inverted compared with what one would expect, because the
// controller never dials an agent: a viewer asks the controller, the
// controller queues a stream_logs task, and the agent opens an outbound
// chunked POST that lands in AcceptLogStream.
type logRelay struct {
	c *Controller

	mu       sync.Mutex
	streams  map[string]*logStream // by stream ID
	byRunner map[string]string     // runner ID -> stream ID
}

type logStream struct {
	id       string
	runnerID string
	hostID   string

	mu     sync.Mutex
	subs   map[int]chan []byte
	nextID int
	closed bool

	// budget is the stream's remaining byte allowance and budgetAt when it
	// was last topped up. Only AcceptLogStream touches them, from the one
	// goroutine reading the agent's POST, so they need no lock.
	budget   float64
	budgetAt time.Time
}

// spend reports whether n bytes fit in the stream's budget at now, and takes
// them if they do. A chunk that does not fit is dropped whole rather than cut:
// half a line is worse than a gap.
func (s *logStream) spend(n int, now time.Time) bool {
	if s.budgetAt.IsZero() {
		s.budget = logStreamBurst
	} else if d := now.Sub(s.budgetAt); d > 0 {
		s.budget = min(logStreamBurst, s.budget+d.Seconds()*logStreamBytesPerSecond)
	}
	s.budgetAt = now
	if float64(n) > s.budget {
		return false
	}
	s.budget -= float64(n)
	return true
}

func newLogRelay(c *Controller) *logRelay {
	return &logRelay{c: c, streams: map[string]*logStream{}, byRunner: map[string]string{}}
}

// OpenLogStream subscribes to a runner's output and returns the channel the
// API's SSE handler reads, plus the function that unsubscribes.
//
// The channel is closed when the stream ends, so a handler can range over it.
// Bytes are dropped rather than queued without limit when a reader falls
// behind: a wedged browser tab must not hold a runner's output in memory.
func (c *Controller) OpenLogStream(ctx context.Context, runnerID string, opts backend.LogOptions) (<-chan []byte, func(), error) {
	r, err := c.st.GetRunner(ctx, runnerID)
	if err != nil {
		return nil, nil, err
	}
	if r.HostID == "" {
		return nil, nil, fmt.Errorf("runner %s is not on a host, so it has no logs to stream", runnerID)
	}
	if r.State == store.RunnerRemoved {
		// The container is gone and so is its output; saying so beats an empty
		// stream that looks like a runner producing nothing.
		return nil, nil, fmt.Errorf("runner %s has been removed; an ephemeral runner's output only exists while its container does", runnerID)
	}
	// host_id references hosts(id) ON DELETE CASCADE, so a runner row cannot
	// outlive its host: this is a real query failure, not a deletion race.
	h, err := c.st.GetHost(ctx, r.HostID)
	if err != nil {
		return nil, nil, err
	}
	if !h.Healthy(c.Now()) {
		// Nothing would ever answer this stream: no agent is going to poll for
		// the task it enqueues. Refusing here, rather than opening one that
		// waits forever, is what keeps a repeatedly reopened stream from
		// piling up queued tasks for a host that is never coming back.
		return nil, nil, fmt.Errorf("runner %s's host has not been heard from recently, so it cannot stream logs right now", runnerID)
	}
	return c.relay.subscribe(r, opts)
}

// subscribe attaches a viewer, starting the stream if this is the first one.
func (lr *logRelay) subscribe(r *store.Runner, opts backend.LogOptions) (<-chan []byte, func(), error) {
	lr.mu.Lock()
	var s *logStream
	var streamID string
	fresh := true
	if opts.Follow {
		if curID, ok := lr.byRunner[r.ID]; ok {
			s = lr.streams[curID]
			if s != nil && !s.isClosed() {
				streamID = curID
				fresh = false
			}
		}
	}
	if fresh {
		streamID = "log_" + store.NewSecret(8)
		s = &logStream{id: streamID, runnerID: r.ID, hostID: r.HostID, subs: map[int]chan []byte{}}
		lr.streams[streamID] = s
		if opts.Follow {
			lr.byRunner[r.ID] = streamID
		}
	}
	lr.mu.Unlock()

	ch, subID, err := s.add()
	if err != nil {
		return nil, nil, err
	}

	if fresh {
		lr.c.enqueue(r.HostID, agent.Task{
			Kind:       agent.TaskStreamLogs,
			RunnerID:   r.ID,
			StreamID:   streamID,
			LogOptions: &opts,
		})
		lr.c.log.Debug("opened a log relay", "runner", r.ID, "stream", streamID, "host", r.HostID)
	}

	var once sync.Once
	cancel := func() { once.Do(func() { lr.unsubscribe(s, subID) }) }
	return ch, cancel, nil
}

// unsubscribe drops one viewer and tears the stream down when it was the last.
func (lr *logRelay) unsubscribe(s *logStream, subID int) {
	last := s.remove(subID)
	if !last {
		return
	}
	lr.mu.Lock()
	if lr.streams[s.id] == s {
		delete(lr.streams, s.id)
	}
	if lr.byRunner[s.runnerID] == s.id {
		delete(lr.byRunner, s.runnerID)
	}
	lr.mu.Unlock()

	// Nobody is watching, so tell the agent to stop reading the container's
	// output and close its outbound POST.
	lr.c.enqueue(s.hostID, agent.Task{
		Kind:     agent.TaskCancelLogs,
		RunnerID: s.runnerID,
		StreamID: s.id,
	})
	s.close()
	lr.c.log.Debug("closed a log relay; the last viewer went away", "runner", s.runnerID, "stream", s.id)
}

// fail ends a stream whose relay the agent could not open, after handing every
// viewer the agent's explanation as output.
//
// Without it the viewer waits on a stream no POST will ever feed, and a second
// Follow viewer attaches to the same dead stream rather than queuing a task of
// its own. No cancel task is queued: the agent never opened anything to close.
// The explanation travels as a log chunk because that is the one channel the
// API layer already renders, so the api/controller boundary stays as it is.
func (lr *logRelay) fail(streamID, reason string) {
	lr.mu.Lock()
	s := lr.streams[streamID]
	if s != nil {
		delete(lr.streams, streamID)
		if lr.byRunner[s.runnerID] == streamID {
			delete(lr.byRunner, s.runnerID)
		}
	}
	lr.mu.Unlock()
	if s == nil {
		return
	}
	if reason != "" {
		s.send([]byte("zoomies: could not open this runner's log stream: " + reason + "\n"))
	}
	s.close()
	lr.c.log.Debug("closed a log relay the agent could not open", "runner", s.runnerID, "stream", streamID, "reason", reason)
}

// AcceptLogStream consumes the agent's outbound chunked POST and fans it out.
// It returns when the agent closes the body or the stream is torn down.
//
// hostID is the host the request authenticated as, and it must be the host the
// stream was opened for: whatever arrives here is shown to operators as that
// runner's output, so a stream another agent could write into would let one
// host put words in another's mouth. Every other agent endpoint checks the same
// thing against the runner's host; this one checks it against the stream's.
func (c *Controller) AcceptLogStream(hostID, streamID string, r io.Reader) error {
	c.relay.mu.Lock()
	s := c.relay.streams[streamID]
	c.relay.mu.Unlock()
	if s == nil {
		return fmt.Errorf("%w: %s", ErrStreamUnknown, streamID)
	}
	if s.hostID != hostID {
		c.log.Warn("a host tried to write into another host's log stream",
			"host", hostID, "stream", streamID, "owner", s.hostID)
		// Deliberately the same answer a closed stream gets: an agent probing
		// for streams it does not own learns nothing from the difference.
		return fmt.Errorf("%w: %s", ErrStreamUnknown, streamID)
	}

	// Clean up registration on any exit path (error, viewer cancellation, EOF)
	// so closed streams are never leaked in relay maps.
	defer func() {
		c.relay.mu.Lock()
		if c.relay.streams[streamID] == s {
			delete(c.relay.streams, streamID)
		}
		if c.relay.byRunner[s.runnerID] == streamID {
			delete(c.relay.byRunner, s.runnerID)
		}
		c.relay.mu.Unlock()
		s.close()
	}()

	buf := make([]byte, logReadChunk)
	for {
		n, err := r.Read(buf)
		if n > 0 && !s.spend(n, c.Now()) {
			// Over budget: the bytes are read and dropped, never waited on.
			// Blocking would hold the agent's POST open and push the backlog
			// back into the agent's memory, which is the same wedge the
			// subscriber queue exists to avoid, one hop earlier.
			c.metrics.logRelayDropped.Add(float64(n))
			n = 0
			if s.isClosed() {
				// Nobody is left to drop it for; send would have said so.
				return nil
			}
		}
		if n > 0 {
			// The buffer is reused, so each subscriber gets its own copy.
			chunk := make([]byte, n)
			copy(chunk, buf[:n])
			if !s.send(chunk) {
				// The last viewer left mid-stream; the cancel task is already
				// queued, and returning ends the agent's POST.
				return nil
			}
		}
		if err != nil {
			if !errors.Is(err, io.EOF) {
				// The agent's connection dropped mid-stream -- the job ended
				// and the container with it, or the network went. The output
				// up to here was delivered, the viewer sees the stream end,
				// and nothing needs a 500 in the log every time a job
				// finishes under a watcher.
				c.log.Debug("a log stream ended before its EOF", "stream", streamID, "runner", s.runnerID, "error", err)
			}
			break
		}
	}
	return nil
}

// streamIDFor returns the stream currently open for a runner, or "".
func (lr *logRelay) streamIDFor(runnerID string) string {
	lr.mu.Lock()
	defer lr.mu.Unlock()
	return lr.byRunner[runnerID]
}

// closeAll ends every stream, used at shutdown so no SSE response is left open.
func (lr *logRelay) closeAll() {
	lr.mu.Lock()
	streams := make([]*logStream, 0, len(lr.streams))
	for _, s := range lr.streams {
		streams = append(streams, s)
	}
	lr.streams = map[string]*logStream{}
	lr.byRunner = map[string]string{}
	lr.mu.Unlock()
	for _, s := range streams {
		s.close()
	}
}

// add registers a viewer.
func (s *logStream) add() (chan []byte, int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil, 0, ErrStreamUnknown
	}
	s.nextID++
	ch := make(chan []byte, logSubscriberQueue)
	s.subs[s.nextID] = ch
	return ch, s.nextID, nil
}

// remove drops a viewer and reports whether it was the last one.
func (s *logStream) remove(id int) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	ch, ok := s.subs[id]
	if !ok {
		return false
	}
	delete(s.subs, id)
	close(ch)
	return len(s.subs) == 0
}

// send fans one chunk out, dropping for subscribers that are not keeping up.
// It reports whether anybody is still listening.
func (s *logStream) send(chunk []byte) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed || len(s.subs) == 0 {
		return false
	}
	for _, ch := range s.subs {
		select {
		case ch <- chunk:
		default:
			// Dropped rather than blocked. A slow reader loses lines; every
			// other viewer, and the agent writing into the relay, do not stall.
		}
	}
	return true
}

// close ends the stream for everyone still attached.
func (s *logStream) close() {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return
	}
	s.closed = true
	for id, ch := range s.subs {
		delete(s.subs, id)
		close(ch)
	}
}

// isClosed reports whether the stream has already ended.
func (s *logStream) isClosed() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closed
}

package controller

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// The controller never dials an agent, so a log tail is a task out and a
// chunked POST back. This is that round trip.
func TestLogRelayDeliversToASubscriber(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	ch, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true, Tail: 100})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	defer cancel()

	task := h.taskOfKind(host.ID, agent.TaskStreamLogs)
	if task.RunnerID != r.ID || task.StreamID == "" {
		t.Fatalf("stream task = %+v, want one for runner %s with a stream ID", task, r.ID)
	}
	if task.LogOptions == nil || !task.LogOptions.Follow || task.LogOptions.Tail != 100 {
		t.Fatalf("log options = %+v, want the ones the viewer asked for", task.LogOptions)
	}

	done := make(chan []byte, 1)
	go func() { done <- drain(t, ch, 2*time.Second) }()

	if err := h.c.AcceptLogStream(host.ID, task.StreamID, strings.NewReader("run 1/3\nrun 2/3\nrun 3/3\n")); err != nil {
		t.Fatalf("AcceptLogStream: %v", err)
	}

	got := <-done
	if !bytes.Contains(got, []byte("run 2/3")) {
		t.Fatalf("subscriber received %q, want the runner's output", got)
	}
}

// Two viewers of the same runner share one stream, so opening a second tab
// does not make the agent read the container's output twice.
func TestSecondViewerSharesTheStream(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	_, cancel1, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("first OpenLogStream: %v", err)
	}
	defer cancel1()
	ch2, cancel2, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("second OpenLogStream: %v", err)
	}
	defer cancel2()

	var streams int
	for _, task := range h.tasksFor(host.ID) {
		if task.Kind == agent.TaskStreamLogs {
			streams++
		}
	}
	if streams != 1 {
		t.Fatalf("queued %d stream tasks for two viewers, want 1", streams)
	}

	streamID := h.c.relay.streamIDFor(r.ID)
	go func() { _ = h.c.AcceptLogStream(host.ID, streamID, strings.NewReader("shared output\n")) }()
	if got := drain(t, ch2, 2*time.Second); !bytes.Contains(got, []byte("shared output")) {
		t.Fatalf("the second viewer received %q", got)
	}
}

// When the last viewer goes away the agent is told to stop reading, otherwise
// a closed browser tab would keep a container's output flowing forever.
func TestLastViewerLeavingCancelsTheStream(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	ch, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	streamID := h.c.relay.streamIDFor(r.ID)
	cancel()

	if !h.hasTaskOfKind(host.ID, agent.TaskCancelLogs) {
		t.Fatal("no cancel task was queued when the last viewer left")
	}
	if _, open := <-ch; open {
		t.Fatal("the subscriber's channel is still open after it unsubscribed")
	}
	if err := h.c.AcceptLogStream(host.ID, streamID, strings.NewReader("late")); !errors.Is(err, ErrStreamUnknown) {
		t.Fatalf("AcceptLogStream after cancel = %v, want ErrStreamUnknown", err)
	}
}

// A browser that has stopped reading must lose lines rather than hold up the
// agent writing into the relay.
func TestLogRelayDropsRatherThanBlocks(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	// Subscribe and deliberately never read.
	_, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	defer cancel()
	streamID := h.taskOfKind(host.ID, agent.TaskStreamLogs).StreamID

	// One byte per Read, so this is several times the subscriber's queue depth
	// in separate chunks.
	payload := bytes.Repeat([]byte("x"), logSubscriberQueue*3)
	done := make(chan error, 1)
	go func() { done <- h.c.AcceptLogStream(host.ID, streamID, &byteReader{data: payload}) }()

	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("AcceptLogStream: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("AcceptLogStream blocked on a subscriber that stopped reading")
	}
}

// Logs for a runner whose container is gone are not an empty stream: the API
// gets an error it can turn into an explanation.
func TestLogStreamForARemovedRunnerIsRefused(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "gone"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	if _, _, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{}); err == nil {
		t.Fatal("OpenLogStream succeeded for a removed runner")
	} else if !strings.Contains(err.Error(), "ephemeral") {
		t.Fatalf("error = %v, want one explaining that the container is gone", err)
	}
}

// Opening a stream for a runner on a host that has not heartbeated recently
// would queue a task nobody will ever poll for: no agent is coming back to
// read it. Refusing here, rather than opening a stream that waits forever, is
// what stops a repeatedly reopened tab from piling up queued tasks for a host
// that is never coming back.
func TestLogStreamForAnUnhealthyHostIsRefused(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)
	host.LastHeartbeat = time.Now().Add(-store.HeartbeatTimeout - time.Minute)
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}

	if _, _, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{}); err == nil {
		t.Fatal("OpenLogStream succeeded for a host with no recent heartbeat")
	} else if !strings.Contains(err.Error(), "not been heard from") {
		t.Fatalf("error = %v, want one explaining the host is unreachable", err)
	}
	if h.hasTaskOfKind(host.ID, agent.TaskStreamLogs) {
		t.Fatal("a stream task was queued for a host nothing will ever poll")
	}
}

// Whatever arrives on a log relay is shown to operators as that runner's
// output. Every other agent endpoint checks the reporting host owns what it is
// reporting on; this one has to check the same thing against the stream, or one
// host in the fleet can put words in another's mouth.
func TestLogRelayRefusesAnotherHostsStream(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)
	intruder := h.host("vm-intruder")

	ch, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	defer cancel()
	streamID := h.taskOfKind(host.ID, agent.TaskStreamLogs).StreamID

	err = h.c.AcceptLogStream(intruder.ID, streamID, strings.NewReader("you have been pwned\n"))
	if !errors.Is(err, ErrStreamUnknown) {
		t.Fatalf("another host writing into the stream = %v; want ErrStreamUnknown", err)
	}
	// And the answer is the same one a stream that never existed gets, so
	// probing for streams you do not own tells you nothing. The two messages
	// name their own stream id, so they are not compared for equality; what
	// must match is the sentinel, and what must not appear in either is any
	// hint that this particular id belongs to somebody.
	never := h.c.AcceptLogStream(intruder.ID, "log_nosuchstream", strings.NewReader("x"))
	if !errors.Is(never, ErrStreamUnknown) {
		t.Fatalf("a stream that never existed = %v; want the same ErrStreamUnknown", never)
	}
	for _, telltale := range []string{host.ID, host.Name, r.ID, "owner", "another", "belongs", "forbidden"} {
		if strings.Contains(err.Error(), telltale) {
			t.Fatalf("the refusal names %q, which tells an intruder the stream is real: %v", telltale, err)
		}
	}

	// Nothing the intruder sent reached the viewer.
	select {
	case chunk, ok := <-ch:
		if ok {
			t.Fatalf("the viewer received %q from a host that does not own the runner", chunk)
		}
		t.Fatal("the stream was closed by a refused write")
	default:
	}

	// The owning host is unaffected.
	go func() { _ = h.c.AcceptLogStream(host.ID, streamID, strings.NewReader("real output\n")) }()
	if got := drain(t, ch, 2*time.Second); !bytes.Contains(got, []byte("real output")) {
		t.Fatalf("the owning host's output did not arrive: %q", got)
	}
}

// cutReader hands out its data and then fails the way a dropped connection
// does, rather than ending with a clean EOF.
type cutReader struct {
	data []byte
	done bool
}

func (r *cutReader) Read(p []byte) (int, error) {
	if r.done {
		return 0, errors.New("read tcp: connection reset by peer")
	}
	r.done = true
	return copy(p, r.data), nil
}

// A job that finishes under a watcher ends the agent's chunked POST without a
// clean EOF -- the container is gone, and the connection with it. That is how
// every watched job ends, and it used to be logged as an error and answered
// with a 500 each time.
func TestALogStreamCutMidJobEndsQuietly(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerBusy)

	lines, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
	if err != nil {
		t.Fatalf("OpenLogStream: %v", err)
	}
	defer cancel()
	streamID := h.taskOfKind(host.ID, agent.TaskStreamLogs).StreamID

	if err := h.c.AcceptLogStream(host.ID, streamID, &cutReader{data: []byte("last line\n")}); err != nil {
		t.Fatalf("AcceptLogStream = %v, want the stream to end quietly", err)
	}
	select {
	case chunk := <-lines:
		if string(chunk) != "last line\n" {
			t.Fatalf("delivered %q before the cut, want the last line", chunk)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("the output before the cut was not delivered")
	}
}

// A viewer that opens a runner whose container is not there is told why,
// straight away. Before this the failed task was only logged, so the browser
// waited on a relay no agent would ever feed, and a second tab attached to the
// same dead stream instead of asking for a fresh one.
func TestAFailedLogTaskEndsTheRelayWithTheAgentsReason(t *testing.T) {
	for _, tc := range []struct {
		name string
		kind agent.TaskKind // what the agent puts in its result; "" is an older agent
	}{
		{"agent names the kind", agent.TaskStreamLogs},
		{"older agent, controller's record decides", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, store.RunnerFailed)

			ch, cancel, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
			if err != nil {
				t.Fatalf("OpenLogStream: %v", err)
			}
			defer cancel()

			batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
			if err != nil {
				t.Fatalf("PollTasks: %v", err)
			}
			const reason = "no workload for runner on this host, so its logs are gone"
			if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
				TaskID:   batch.Tasks[0].ID,
				Kind:     tc.kind,
				RunnerID: r.ID,
				OK:       false,
				Error:    reason,
			}); err != nil {
				t.Fatalf("ReportResult: %v", err)
			}

			got := drain(t, ch, 2*time.Second)
			if !bytes.Contains(got, []byte(reason)) {
				t.Fatalf("viewer received %q, want the agent's reason %q", got, reason)
			}
			if id := h.c.relay.streamIDFor(r.ID); id != "" {
				t.Fatalf("the dead stream %s is still registered for the runner", id)
			}

			// A second tab must get a relay of its own, and the agent a task
			// to open it.
			_, cancel2, err := h.c.OpenLogStream(h.ctx, r.ID, backend.LogOptions{Follow: true})
			if err != nil {
				t.Fatalf("second OpenLogStream: %v", err)
			}
			defer cancel2()
			if task := h.taskOfKind(host.ID, agent.TaskStreamLogs); task.StreamID == "" {
				t.Fatal("no fresh stream_logs task was queued for the second viewer")
			}
		})
	}
}

package controller

import (
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// DecideMachines is the machine-side twin of scheduler.Decide: it reads a
// snapshot of the fleet and answers how many machines each provider should be
// renting. It is pure -- no clock read, no database, no provider call, no
// randomness -- and it mutates nothing it was handed, so the whole of what a
// fleet decides to spend money on is reproducible in a table test and
// explainable in the sentence each decision carries.
//
// It lives here rather than in internal/scheduler because the scheduler is
// about placing runners on hosts that already exist, and this is about whether
// a host should exist at all: it reads provider and machine rows the scheduler
// knows nothing about, and it must not teach that package about either.
//
// What it does not do is form a second opinion. Which hosts could run a pool is
// scheduler.HostCanRun's answer and which pool claims a queued job is
// scheduler.BestPool's, because a copy of either rule would drift from the one
// that actually places the work, and a fleet that bought machines by one rule
// and refused to use them by another would pay for hosts that never run a job.
//
// The four ways it refuses to count the same capacity twice are stated where
// each one happens: the synthetic host, the shared slot ledger, ready machines,
// and the single claim on a queued job.

// MachineLimits are the fleet-wide bounds, gathered from configuration by the
// caller so that nothing in this file reads configuration for itself.
//
// A maximum of zero is zero, for the fleet exactly as for a pool's max_runners:
// the one number that decides the size of an invoice is not allowed to mean
// "unbounded" because somebody left it unset.
type MachineLimits struct {
	// MaxMachines is how many machines the whole fleet may own at once, across
	// every provider, and MaxCreatesInFlight how many it may be building.
	MaxMachines        int
	MaxCreatesInFlight int
	// IdleTimeout answers for a provider whose row names none of its own, so a
	// provider nobody thought about is not the one machine that never leaves.
	IdleTimeout time.Duration
	// ScaleDownCooldown is how long idleness has to keep being true before a
	// machine is given up, on top of the idle timeout that started it.
	ScaleDownCooldown time.Duration
	// DeleteGrace is how long a machine's host has to have been silent before
	// that silence is believed. Without it a blip releases a machine, because a
	// quiet host is ruled out for every pool and the test that would have said
	// "the fleet still wants this" is skipped rather than failed.
	DeleteGrace time.Duration
}

// MachineSnapshot is everything the decision reads. It is a value rather than a
// set of accessors for the reason scheduler.Snapshot is: a test can place a
// machine exactly one second either side of a timeout, and nothing in the
// calculation can reach past it for a fact nobody wrote down.
type MachineSnapshot struct {
	// Now is the decision time, a field rather than a clock read.
	Now time.Time
	// Plan is the caller's own scheduler.Decide over these same rows. Its pool
	// plans are where demand comes from: Desired, Current and the two blockage
	// flags are the scheduler's reading of the queue, and re-deriving them here
	// would be the copied rule this file exists not to have.
	Plan      scheduler.Plan
	Pools     []*store.Pool
	Hosts     []*store.Host
	Runners   map[string][]*store.Runner
	Jobs      []*store.Job
	Machines  []*store.Machine
	Providers []*store.Provider
	Limits    MachineLimits
}

// MachinePlan is what one pass should do, per provider.
type MachinePlan struct {
	Providers []ProviderPlan `json:"providers"`
}

// ProviderPlan is the decision for one provider, with the sentence that
// justified it in the scheduler's voice -- an operator reading "buy 1 machine
// on proxmox-lab: pool linux-x64 is 2 runner slots short with 3 jobs queued,
// and no host in the fleet can run it" needs nothing else explained.
type ProviderPlan struct {
	ProviderID string `json:"provider_id"`
	// Wanted is how many machines this provider should have, and Have how many
	// it already has: one that owns a resource, or one on the way to owning
	// one. Both are readings, not increments -- a pass that has already bought
	// what the queue asked for wants the same number again, not one more.
	Wanted int `json:"wanted"`
	Have   int `json:"have"`
	// Create is this pass's purchase, after every ceiling has been applied.
	Create int `json:"create"`
	// Drain is the machines that have stopped earning their keep, newest
	// created first so that the one with the least warmed cache goes first.
	Drain  []string `json:"drain,omitempty"`
	Reason string   `json:"reason,omitempty"`
	// Blocked says why Create is below what the queue asked for, and
	// BlockedFix what to change. They are separate because the problems drawer
	// shows the two differently.
	Blocked    string `json:"blocked,omitempty"`
	BlockedFix string `json:"blocked_fix,omitempty"`
}

// poolDemand is one pool's unmet demand, charged to one provider.
type poolDemand struct {
	pool string
	// slots is what is still missing after everything the fleet already has,
	// or is already buying, has been subtracted from it.
	slots  int
	queued int
	// nowhere distinguishes a pool no host can run from one whose hosts are
	// merely full, because they read as completely different faults and only
	// the first is one a machine is the answer to.
	nowhere bool
}

// DecideMachines turns a snapshot into the machines each provider should buy
// and release. See the file comment for what it promises.
func DecideMachines(s MachineSnapshot) MachinePlan {
	providers := sortedProviders(s.Providers)
	if len(providers) == 0 {
		return MachinePlan{}
	}
	pools := sortedPoolsForMachines(s.Pools)
	hosts := sortedHostsForMachines(s.Hosts)
	machines := sortedMachines(s.Machines)

	planned := make(map[string]scheduler.PoolPlan, len(s.Plan.Pools))
	for _, pp := range s.Plan.Pools {
		planned[pp.PoolID] = pp
	}
	byProvider := make(map[string]*store.Provider, len(providers))
	synth := make(map[string]*store.Host, len(providers))
	for _, p := range providers {
		byProvider[p.ID] = p
		synth[p.ID] = providerSynthHost(p, s.Now)
	}
	queued := queuedByPool(pools, s.Jobs)

	// The counts every ceiling is measured against. Owns() is the money
	// question -- a failed machine whose VM was created still costs -- and
	// Pending() is the in-flight one.
	owned, pending, have := map[string]int{}, map[string]int{}, map[string]int{}
	// credit is the shared ledger's second half: what each machine that is
	// still on its way may be counted for, at most once in total however many
	// pools its shape happens to match.
	//
	// Ready machines are deliberately absent. A ready machine is already a host
	// row, already in the scheduler's Current and already in the free slots
	// subtracted below; counting it here as well IS the double count, and a
	// fleet that did it would buy a second machine for demand the first one had
	// already met.
	credit := map[string]int{}
	fleetOwned, fleetPending := 0, 0
	for _, m := range machines {
		p := byProvider[m.ProviderID]
		if p == nil {
			continue
		}
		if m.Owns() {
			owned[p.ID]++
			fleetOwned++
		}
		if m.State.Pending() {
			pending[p.ID]++
			fleetPending++
			credit[m.ID] = machineSlots(m, p)
		}
		if m.Owns() || m.State.Pending() {
			have[p.ID]++
		}
	}

	// free is the ledger's first half: slots a real host has and nothing has
	// claimed yet. It is decremented as pools take from it, so a slot that
	// satisfied linux-x64 is not also available to linux-x64-large -- the same
	// mechanic as hostSet.place mutating its own free counts.
	free := make(map[string]int, len(hosts))
	for _, h := range hosts {
		free[h.ID] = h.Free()
	}

	demand := map[string][]poolDemand{}
	for _, pool := range pools {
		pp, ok := planned[pool.ID]
		// Only a pool the scheduler says is blocked is demand a machine can
		// answer. A pool merely waiting on this tick's create budget clears
		// itself next pass, and buying a machine for it would pay for a queue
		// that was already moving.
		if !ok || (!pp.BlockedAtCapacity && !pp.BlockedNoEligibleHost) {
			continue
		}
		short := pp.Desired - pp.Current
		if short <= 0 {
			continue
		}
		for _, h := range hosts {
			if short <= 0 {
				break
			}
			if free[h.ID] <= 0 || !scheduler.HostCanRun(h, pool, s.Now) {
				continue
			}
			// A free slot on a host that could run this pool is capacity the
			// fleet already has: the finishing job that releases it costs
			// nothing, and a machine bought against it is paid for twice.
			take := min(free[h.ID], short)
			free[h.ID] -= take
			short -= take
		}
		for _, m := range machines {
			if short <= 0 {
				break
			}
			p := byProvider[m.ProviderID]
			if p == nil || credit[m.ID] <= 0 || !scheduler.HostCanRun(synth[p.ID], pool, s.Now) {
				continue
			}
			take := min(credit[m.ID], short)
			credit[m.ID] -= take
			short -= take
		}
		if short <= 0 {
			continue
		}
		p := providerFor(providers, synth, pool, owned, s.Now)
		if p == nil {
			// No provider's machines would be allowed to run this pool, so its
			// blockage is not one money can fix. BlockedNoEligibleHost is a
			// hint that a machine might help, never an instruction to buy one.
			continue
		}
		demand[p.ID] = append(demand[p.ID], poolDemand{
			pool:    pool.Name,
			slots:   short,
			queued:  queued[pool.ID],
			nowhere: pp.BlockedNoEligibleHost,
		})
	}

	drains := drainable(s, byProvider, pools, planned, hosts, machines)

	fleetRoom := s.Limits.MaxMachines - fleetOwned
	fleetCreateRoom := s.Limits.MaxCreatesInFlight - fleetPending
	out := MachinePlan{Providers: make([]ProviderPlan, 0, len(providers))}
	for _, p := range providers {
		plan := ProviderPlan{ProviderID: p.ID, Have: have[p.ID], Drain: drains[p.ID]}
		ds := demand[p.ID]
		slots := 0
		for _, d := range ds {
			slots += d.slots
		}
		want := ceilDiv(slots, providerSlots(p))
		plan.Wanted = plan.Have + want

		create, because, fix := want, "", ""
		// Each ceiling in turn, and the sentence kept is whichever one actually
		// binds: an operator told to raise a limit that was not the one holding
		// them back has been sent to the wrong screen.
		bite := func(room int, what, how string) {
			if room < create {
				create = max(room, 0)
				because, fix = what, how
			}
		}
		what, how := providerMachineCeiling(p, owned[p.ID])
		bite(p.MaxMachines-owned[p.ID], what, how)
		// The fleet's two counts are what it owns and is building plus what
		// this pass has already granted to the providers before this one, so
		// the second provider of a pass is told the truth about what is left
		// rather than what there was before anything was bought.
		what, how = fleetMachineCeiling(s.Limits, s.Limits.MaxMachines-fleetRoom)
		bite(fleetRoom, what, how)
		what, how = providerCreateCeiling(p, pending[p.ID])
		bite(p.MaxCreatesInFlight-pending[p.ID], what, how)
		what, how = fleetCreateCeiling(s.Limits, s.Limits.MaxCreatesInFlight-fleetCreateRoom)
		bite(fleetCreateRoom, what, how)

		plan.Create = create
		fleetRoom -= create
		fleetCreateRoom -= create
		if create > 0 {
			plan.Reason = fmt.Sprintf("buy %s on %s: %s", plural(create, "machine"), p.Name, demandReason(ds))
		}
		if create < want {
			plan.Blocked = fmt.Sprintf("%s not bought: %s", plural(want-create, "machine"), because)
			plan.BlockedFix = fix
		}
		out.Providers = append(out.Providers, plan)
	}
	return out
}

// providerSynthHost is the host this provider's next machine would be, so that
// "could this provider serve that pool" is asked of scheduler.HostCanRun -- the
// predicate that will decide where the runner actually goes -- rather than of a
// second copy of the matching rule that would drift from it.
//
// It is a value nobody keeps: it exists for the length of one decision, and
// writing it to the database would put a host in the fleet that does not exist.
func providerSynthHost(p *store.Provider, now time.Time) *store.Host {
	pf := p.MachinePlatform.Normalized()
	return &store.Host{
		ID:       "synthetic-" + p.ID,
		Name:     p.Name,
		Capacity: providerSlots(p),
		Backends: store.StringSlice{string(p.MachineBackend)},
		Labels:   p.MachineLabels,
		// The kernel is what an agent on such a machine would report about
		// itself, and it is what a host selector asking for os=linux is
		// answered with; the distribution is what a pool's platform is matched
		// against. Filling only one of the two would make this machine fail a
		// test the real one would pass.
		OS:        naming.Kernel(pf.OS),
		Distro:    pf.OS,
		OSVersion: pf.OSVersion,
		Arch:      pf.Arch,
		CPUs:      int(p.MachineCPUs),
		MemoryMB:  p.MachineMemoryMB,
		// A machine that has not been built has all of its disk free, and the
		// host reserve then applies to it exactly as it would to the real one,
		// so a provider offering a machine too small for a pool is refused here
		// rather than after it has been paid for.
		DiskTotalMB: p.MachineDiskMB,
		DiskFreeMB:  p.MachineDiskMB,
		// It has never missed a heartbeat either: without the snapshot's own
		// clock here, HostCanRun's health test would rule out every provider
		// and the fleet would never buy anything.
		LastHeartbeat: now,
	}
}

// providerFor picks which provider a pool's unmet demand is charged to.
//
// Exactly one, deterministically. Charging every provider whose machines could
// run the pool would buy the same shortfall from each of them, and the ledger
// above exists precisely so that a slot is paid for once. Order is the
// providers' own -- name, then id -- and a provider with no room left under its
// own ceiling is passed over, so a half-configured row that may own nothing
// cannot starve a configured one. When none has room the first eligible
// provider still takes the demand, because a refusal an operator can read is
// worth more than silence.
func providerFor(providers []*store.Provider, synth map[string]*store.Host, pool *store.Pool, owned map[string]int, now time.Time) *store.Provider {
	var first *store.Provider
	for _, p := range providers {
		if !scheduler.HostCanRun(synth[p.ID], pool, now) {
			continue
		}
		if first == nil {
			first = p
		}
		if p.MaxMachines-owned[p.ID] > 0 {
			return p
		}
	}
	return first
}

// drainable is the scale-down half: the machines that may be given up, keyed by
// provider.
//
// A machine qualifies when it is ready, its host is running nothing, it has
// been idle for the provider's idle timeout plus one scale-down cooldown, and
// removing its slots would not reopen a shortfall for any pool it serves. The
// two durations are added rather than checked separately because they say
// different things about the same observation: the idle timeout is when a
// machine stopped being useful, and the cooldown is how long that has to keep
// being true before the fleet pays the price of building it again -- a quiet
// minute between two bursts must not destroy what the second burst wants.
func drainable(s MachineSnapshot, byProvider map[string]*store.Provider, pools []*store.Pool, planned map[string]scheduler.PoolPlan, hosts []*store.Host, machines []*store.Machine) map[string][]string {
	byHost := make(map[string]*store.Host, len(hosts))
	for _, h := range hosts {
		byHost[h.ID] = h
	}
	live := map[string]int{}
	for _, rs := range s.Runners {
		for _, r := range rs {
			if r != nil && r.State.Live() {
				live[r.HostID]++
			}
		}
	}
	// slack is how many slots each pool could lose and still have room for
	// every runner it is aiming at. It is a ledger too: a drain granted here
	// spends the slack of every pool that host served, so two machines are
	// never both released against the same spare capacity.
	//
	// The slots counted are the ones a throttle leaves, not the ones the
	// operator configured. A throttled host keeps the runners placed before
	// the throttle and will re-place fewer when they finish, so counting the
	// slots it has just given back would release a machine to cover work
	// nothing can place -- and the fleet would buy the same machine again on
	// the next burst, having paid twice for one clone. Every site below reads
	// the same figure, or the ledger stops balancing and two machines could be
	// released against one host's spare slots.
	slack := make(map[string]int, len(pools))
	for _, pool := range pools {
		capacity := 0
		for _, h := range hosts {
			if scheduler.HostCanRun(h, pool, s.Now) {
				capacity += h.EffectiveCapacity()
			}
		}
		slack[pool.ID] = capacity - planned[pool.ID].Desired
	}

	// Newest first, tie-broken by id: the youngest machine has the least
	// warmed cache to throw away, and the order is the same on every pass, so
	// two passes over one snapshot never disagree about which machine goes.
	candidates := slices.Clone(machines)
	slices.SortStableFunc(candidates, func(a, b *store.Machine) int {
		if c := b.CreatedAt.Compare(a.CreatedAt); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})

	out := map[string][]string{}
	for _, m := range candidates {
		p := byProvider[m.ProviderID]
		host := byHost[m.HostID]
		if p == nil || host == nil || m.State != store.MachineReady || live[host.ID] > 0 {
			continue
		}
		if m.IdleSince == nil || s.Now.Sub(*m.IdleSince) < idleTimeout(p, s.Limits)+s.Limits.ScaleDownCooldown {
			continue
		}
		// A host that has gone quiet is ruled out for every pool below, so the
		// spare-capacity test is not failed by a machine the fleet still wants
		// -- it is never reached, and a network blip releases the machine.
		// provider.delete_grace is how long the silence has to last before it
		// is treated as the machine being gone. It is longer than the
		// host-lost judgement, so by then the runners that were on it have
		// already been failed and the emptiness is real rather than reported.
		if !host.Healthy(s.Now) && s.Now.Sub(host.LastHeartbeat) < s.Limits.DeleteGrace {
			continue
		}
		served := make([]*store.Pool, 0, len(pools))
		spare := true
		for _, pool := range pools {
			if !scheduler.HostCanRun(host, pool, s.Now) {
				continue
			}
			pp := planned[pool.ID]
			if slack[pool.ID] < host.EffectiveCapacity() || pp.Desired > pp.Current {
				spare = false
				break
			}
			served = append(served, pool)
		}
		if !spare {
			continue
		}
		for _, pool := range served {
			slack[pool.ID] -= host.EffectiveCapacity()
		}
		out[p.ID] = append(out[p.ID], m.ID)
	}
	return out
}

// queuedByPool counts the queued jobs each pool has claimed, so a purchase can
// be justified by the work an operator can see waiting.
//
// The claim is scheduler.BestPool's, which gives a job to exactly one pool. A
// job counted for both of two pools that advertise its labels would be a job
// two machines were bought for.
func queuedByPool(pools []*store.Pool, jobs []*store.Job) map[string]int {
	out := make(map[string]int, len(pools))
	for _, j := range jobs {
		if j == nil || j.State != store.JobQueued || j.Provisioning != "" {
			continue
		}
		if p := scheduler.BestPool(pools, j); p != nil {
			out[p.ID]++
		}
	}
	return out
}

// providerSlots is how many runners one machine of this provider offers. A row
// that says nothing still offers one, because demand divided by zero slots
// would buy nothing for ever and never say why.
func providerSlots(p *store.Provider) int { return max(p.MachineCapacity, 1) }

// machineSlots is what one machine on its way may be counted for: what it was
// planned with, or its provider's shape when the row does not say. The row
// wins, because a provider whose shape was edited after a machine was planned
// is not evidence about the machine already being built.
func machineSlots(m *store.Machine, p *store.Provider) int {
	if m.Capacity > 0 {
		return m.Capacity
	}
	return providerSlots(p)
}

// idleTimeout is the provider's own, or the fleet's when its row names none.
func idleTimeout(p *store.Provider, l MachineLimits) time.Duration {
	if d := time.Duration(p.IdleTimeout); d > 0 {
		return d
	}
	return l.IdleTimeout
}

func ceilDiv(a, b int) int {
	if a <= 0 || b <= 0 {
		return 0
	}
	return (a + b - 1) / b
}

// ---------------------------------------------------------------------------
// The sentences
// ---------------------------------------------------------------------------

// demandReason says what the machines are for, naming the pools an operator
// would go and look at and what is waiting in them.
func demandReason(ds []poolDemand) string {
	slots, queued, nowhere := 0, 0, 0
	names := make([]string, 0, len(ds))
	for _, d := range ds {
		slots += d.slots
		queued += d.queued
		if d.nowhere {
			nowhere++
		}
		names = append(names, d.pool)
	}
	what := fmt.Sprintf("%s is %s short", poolList(names), plural(slots, "runner slot"))
	if len(names) > 1 {
		what = fmt.Sprintf("%s are %s short between them", poolList(names), plural(slots, "runner slot"))
	}
	if queued > 0 {
		what += " with " + plural(queued, "job") + " queued"
	}
	switch {
	case nowhere == len(ds):
		return what + ", and no host in the fleet can run " + them(len(ds))
	case nowhere == 0:
		return what + ", and every host that can run " + them(len(ds)) + " is full"
	}
	return what + ", and the fleet has nowhere to put " + them(len(ds))
}

// The four ceilings, each in the words of the setting that has to change. A
// maximum of none is none, so each one says that outright rather than reporting
// a room of zero that an operator would read as a coincidence.
func providerMachineCeiling(p *store.Provider, owned int) (string, string) {
	switch {
	case p.MaxMachines <= 0:
		return fmt.Sprintf("%s may own no machines at all", p.Name),
			"set this provider's maximum machines to the number of machines you are willing to pay for"
	case owned == 0:
		return fmt.Sprintf("%s may own only %s", p.Name, plural(p.MaxMachines, "machine")),
			"raise this provider's maximum machines"
	}
	return fmt.Sprintf("%s owns %s and its maximum is %d", p.Name, plural(owned, "machine"), p.MaxMachines),
		"raise this provider's maximum machines, or wait for one of its machines to be released"
}

func fleetMachineCeiling(l MachineLimits, owned int) (string, string) {
	switch {
	case l.MaxMachines <= 0:
		return "provider.max_machines is 0, so this fleet rents nothing",
			"set provider.max_machines to the number of machines this fleet may pay for"
	case owned == 0:
		return fmt.Sprintf("provider.max_machines allows only %s across the fleet", plural(l.MaxMachines, "machine")),
			"raise provider.max_machines"
	}
	return fmt.Sprintf("the fleet owns %s and provider.max_machines is %d", plural(owned, "machine"), l.MaxMachines),
		"raise provider.max_machines, or wait for a machine to be released"
}

func providerCreateCeiling(p *store.Provider, building int) (string, string) {
	switch {
	case p.MaxCreatesInFlight <= 0:
		return fmt.Sprintf("%s may build no machine at a time", p.Name),
			"raise this provider's maximum creates in flight above 0"
	case building == 0:
		return fmt.Sprintf("%s may build only %s at a time", p.Name, plural(p.MaxCreatesInFlight, "machine")),
			"raise this provider's maximum creates in flight"
	}
	return fmt.Sprintf("%s is already building %s and may build %d at a time", p.Name, plural(building, "machine"), p.MaxCreatesInFlight),
		"raise this provider's maximum creates in flight, or wait for one to finish"
}

func fleetCreateCeiling(l MachineLimits, building int) (string, string) {
	switch {
	case l.MaxCreatesInFlight <= 0:
		return "provider.max_creates_in_flight is 0, so nothing may be built",
			"set provider.max_creates_in_flight to the number of machines that may be built at once"
	case building == 0:
		return fmt.Sprintf("provider.max_creates_in_flight allows only %s at a time", plural(l.MaxCreatesInFlight, "machine")),
			"raise provider.max_creates_in_flight"
	}
	return fmt.Sprintf("the fleet is already building %s and provider.max_creates_in_flight is %d", plural(building, "machine"), l.MaxCreatesInFlight),
		"raise provider.max_creates_in_flight, or wait for one to finish"
}

func poolList(names []string) string {
	switch len(names) {
	case 0:
		return "no pool"
	case 1:
		return "pool " + names[0]
	case 2:
		return "pools " + names[0] + " and " + names[1]
	}
	return "pools " + strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
}

func them(n int) string {
	if n == 1 {
		return "it"
	}
	return "them"
}

// ---------------------------------------------------------------------------
// Deterministic ordering
//
// Every walk over a snapshot's rows is ordered, and every slice is copied
// before it is sorted: a decision function that reordered its caller's slices
// would be mutating the input it promises not to touch, and one that walked a
// map would answer differently on identical input.
// ---------------------------------------------------------------------------

func sortedProviders(in []*store.Provider) []*store.Provider {
	out := withoutNil(in)
	slices.SortStableFunc(out, func(a, b *store.Provider) int {
		if c := strings.Compare(a.Name, b.Name); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

// sortedPoolsForMachines orders pools the way the scheduler does, so that the
// fleet takes from its shared ledger in the same order it places runners.
func sortedPoolsForMachines(in []*store.Pool) []*store.Pool {
	out := withoutNil(in)
	slices.SortStableFunc(out, func(a, b *store.Pool) int {
		if c := strings.Compare(a.Name, b.Name); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

func sortedHostsForMachines(in []*store.Host) []*store.Host {
	out := withoutNil(in)
	slices.SortStableFunc(out, func(a, b *store.Host) int { return strings.Compare(a.ID, b.ID) })
	return out
}

func sortedMachines(in []*store.Machine) []*store.Machine {
	out := withoutNil(in)
	slices.SortStableFunc(out, func(a, b *store.Machine) int {
		if c := a.CreatedAt.Compare(b.CreatedAt); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

func withoutNil[T any](in []*T) []*T {
	out := make([]*T, 0, len(in))
	for _, v := range in {
		if v != nil {
			out = append(out, v)
		}
	}
	return out
}

package controller

import (
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// machineNow is the one instant every test in this file decides at. The
// calculation reads no clock, so a fixed time is all that is needed to place a
// machine exactly one second either side of a timeout.
var machineNow = time.Date(2026, 3, 2, 9, 0, 0, 0, time.UTC)

func demandPool(name string, labels ...string) *store.Pool {
	return &store.Pool{
		ID: "pool_" + name, Name: name, Enabled: true,
		InstallationID: "inst_1", Backend: store.BackendDocker,
		Labels: labels, MaxRunners: 100,
	}
}

func demandProvider(name string) *store.Provider {
	return &store.Provider{
		ID: "prv_" + name, Name: name, Kind: store.ProviderFake, Enabled: true,
		MachineBackend: store.BackendDocker, MachineCapacity: 2,
		MaxMachines: 10, MaxCreatesInFlight: 10,
		IdleTimeout: store.Duration(15 * time.Minute),
	}
}

func demandHost(id string, capacity, active int) *store.Host {
	return &store.Host{
		ID: id, Name: id, Capacity: capacity, ActiveRunners: active,
		Backends: store.StringSlice{string(store.BackendDocker)}, LastHeartbeat: machineNow,
	}
}

// demandMachine is a machine of p in one state. A machine that has got as far
// as owning a resource carries one, because Owns() -- not the state -- is what
// every ceiling is counted over.
func demandMachine(id string, p *store.Provider, state store.MachineState, age time.Duration) *store.Machine {
	m := &store.Machine{
		ID: id, ProviderID: p.ID, Name: id, State: state,
		CreatedAt: machineNow.Add(-age),
	}
	if state != store.MachinePlanned {
		m.ResourceID, m.ResourceZone = "vm-"+id, "node-1"
	}
	return m
}

// demandPoolPlan is the scheduler's reading of one pool, which is where demand
// comes from. blocked is "nowhere" for a pool no host can run, "capacity" for
// one whose hosts are all full, and "" for a pool that is not blocked at all.
func demandPoolPlan(p *store.Pool, current, desired, queued int, blocked string) scheduler.PoolPlan {
	return scheduler.PoolPlan{
		PoolID: p.ID, PoolName: p.Name, Current: current, Desired: desired, QueuedMatched: queued,
		BlockedAtCapacity:     blocked == "capacity",
		BlockedNoEligibleHost: blocked == "nowhere",
	}
}

// demandJobs are queued jobs any pool in this file claims: the labels are the
// ones nearly every workflow is written with, so a job's pool is decided by
// scheduler.BestPool rather than by the test.
func demandJobs(n int) []*store.Job {
	out := make([]*store.Job, 0, n)
	for i := range n {
		out = append(out, &store.Job{
			ID: "job_" + string(rune('a'+i)), Repo: "acme/widgets", State: store.JobQueued,
			InstallationID: "inst_1", Labels: store.StringSlice{"self-hosted", "linux", "x64"},
			QueuedAt: machineNow.Add(-5 * time.Minute),
		})
	}
	return out
}

func demandLimits() MachineLimits {
	return MachineLimits{
		MaxMachines: 10, MaxCreatesInFlight: 10,
		IdleTimeout: 15 * time.Minute, ScaleDownCooldown: 10 * time.Minute,
	}
}

// planFor is the one provider's decision, so a test says what it means rather
// than indexing a slice.
func planFor(t *testing.T, plan MachinePlan, providerID string) ProviderPlan {
	t.Helper()
	for _, pp := range plan.Providers {
		if pp.ProviderID == providerID {
			return pp
		}
	}
	t.Fatalf("no plan for provider %s in %+v", providerID, plan.Providers)
	return ProviderPlan{}
}

// Two pools short one runner each are two slots, and a machine offering two
// slots answers both. Rounding each pool up to its own machine would buy two
// machines for work one of them can do, which is the bill an operator notices.
func TestTwoPoolsWantingTheSameMachineShapeBuyOne(t *testing.T) {
	p := demandProvider("lab")
	alpha, beta := demandPool("alpha"), demandPool("beta")
	s := MachineSnapshot{
		Now:       machineNow,
		Pools:     []*store.Pool{alpha, beta},
		Providers: []*store.Provider{p},
		Limits:    demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{
			demandPoolPlan(alpha, 0, 1, 1, "nowhere"),
			demandPoolPlan(beta, 0, 1, 1, "nowhere"),
		}},
	}

	got := planFor(t, DecideMachines(s), p.ID)
	if got.Create != 1 || got.Wanted != 1 || got.Have != 0 {
		t.Fatalf("create/wanted/have = %d/%d/%d, want 1/1/0", got.Create, got.Wanted, got.Have)
	}
	want := "buy 1 machine on lab: pools alpha and beta are 2 runner slots short between them, and no host in the fleet can run them"
	if got.Reason != want {
		t.Fatalf("reason = %q, want %q", got.Reason, want)
	}
}

// A machine already on its way is capacity, and it is capacity once. Crediting
// it to every pool its labels match would satisfy three pools with one machine
// on paper and leave two of them queueing for ever.
func TestOverlappingPoolsNeverCreditOneMachineTwice(t *testing.T) {
	p := demandProvider("lab")
	alpha, beta := demandPool("alpha"), demandPool("beta")
	onTheWay := demandMachine("mach_1", p, store.MachinePlanned, time.Minute)
	s := MachineSnapshot{
		Now:       machineNow,
		Pools:     []*store.Pool{alpha, beta},
		Providers: []*store.Provider{p},
		Machines:  []*store.Machine{onTheWay},
		Limits:    demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{
			demandPoolPlan(alpha, 0, 2, 2, "nowhere"),
			demandPoolPlan(beta, 0, 2, 2, "nowhere"),
		}},
	}

	got := planFor(t, DecideMachines(s), p.ID)
	// The machine covers alpha entirely; beta is still two slots short, which
	// is one more machine and not two.
	if got.Create != 1 {
		t.Fatalf("create = %d, want 1: the pending machine answers one pool, not both", got.Create)
	}
	if got.Have != 1 || got.Wanted != 2 {
		t.Fatalf("have/wanted = %d/%d, want 1/2", got.Have, got.Wanted)
	}
	if !strings.Contains(got.Reason, "pool beta is 2 runner slots short") {
		t.Fatalf("reason = %q, want it to name the pool the machine could not cover", got.Reason)
	}
}

// A ready machine is already a host row, already counted in the scheduler's
// Current and already in the free slots this calculation subtracts. Counting
// its capacity here as well is the double count, and a fleet that did it would
// refuse to buy the machine the queue is actually waiting for.
func TestReadyMachinesAreNotCountedTwice(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	host := demandHost("host_1", 2, 2) // full: both slots are running jobs
	ready := demandMachine("mach_1", p, store.MachineReady, time.Hour)
	ready.HostID = host.ID
	s := MachineSnapshot{
		Now:       machineNow,
		Pools:     []*store.Pool{pool},
		Hosts:     []*store.Host{host},
		Providers: []*store.Provider{p},
		Machines:  []*store.Machine{ready},
		Limits:    demandLimits(),
		Plan:      scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 2, 4, 2, "capacity")}},
	}

	got := planFor(t, DecideMachines(s), p.ID)
	if got.Create != 1 {
		t.Fatalf("create = %d, want 1: a ready machine's slots are the host's, and they are busy", got.Create)
	}
	if got.Have != 1 || got.Wanted != 2 {
		t.Fatalf("have/wanted = %d/%d, want 1/2", got.Have, got.Wanted)
	}
}

// BlockedNoEligibleHost is a hint that a machine might help, never an
// instruction to buy one: a pool blocked because nothing matches its selector
// is not served by a provider whose machines would not match it either, and
// buying one would spend money and leave the queue exactly where it was.
func TestNoMachineIsBoughtForAPoolItsShapeCouldNotServe(t *testing.T) {
	for _, tc := range []struct {
		name       string
		pool       func(*store.Pool)
		provider   func(*store.Provider)
		wantCreate int
	}{
		{name: "nothing in the way", pool: func(*store.Pool) {}, provider: func(*store.Provider) {}, wantCreate: 1},
		{
			name:     "the backend the pool needs",
			pool:     func(p *store.Pool) { p.Backend = store.BackendPodman },
			provider: func(*store.Provider) {},
		},
		{
			name:     "a host selector the machine does not answer",
			pool:     func(p *store.Pool) { p.HostSelector = store.StringMap{"zone": "b"} },
			provider: func(p *store.Provider) { p.MachineLabels = store.StringMap{"zone": "a"} },
		},
		{
			name:     "the platform the pool asked for",
			pool:     func(p *store.Pool) { p.Platform = store.Platform{OS: "windows"} },
			provider: func(p *store.Provider) { p.MachinePlatform = store.Platform{OS: "ubuntu", OSVersion: "24.04"} },
		},
		{
			name:     "a machine too small for the pool's limits",
			pool:     func(p *store.Pool) { p.Resources = store.Resources{CPUs: 8} },
			provider: func(p *store.Provider) { p.MachineCPUs = 4 },
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := demandProvider("lab")
			tc.provider(p)
			pool := demandPool("alpha")
			tc.pool(pool)
			s := MachineSnapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
				Limits: demandLimits(),
				Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 2, 2, "nowhere")}},
			}

			got := planFor(t, DecideMachines(s), p.ID)
			if got.Create != tc.wantCreate {
				t.Fatalf("create = %d, want %d", got.Create, tc.wantCreate)
			}
			if tc.wantCreate == 0 && (got.Reason != "" || got.Blocked != "") {
				t.Fatalf("reason %q / blocked %q, want both empty: this is not a shortfall money can fix", got.Reason, got.Blocked)
			}
		})
	}
}

// Scale from zero is the whole point of a provider: a fleet with no host at all
// emits no capacity signal a finished job could ever clear, so the number of
// machines bought has to come out of the queue itself -- and be exactly enough
// for it, rounded up to whole machines.
func TestScaleFromZeroBuysExactlyTheMachinesTheQueueNeeds(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("linux-x64", "linux", "x64")
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
		Jobs: demandJobs(5), Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 5, 5, "nowhere")}},
	}

	got := planFor(t, DecideMachines(s), p.ID)
	if got.Create != 3 || got.Wanted != 3 || got.Have != 0 {
		t.Fatalf("create/wanted/have = %d/%d/%d, want 3/3/0 for 5 slots on 2-slot machines", got.Create, got.Wanted, got.Have)
	}
	want := "buy 3 machines on lab: pool linux-x64 is 5 runner slots short with 5 jobs queued, and no host in the fleet can run it"
	if got.Reason != want {
		t.Fatalf("reason = %q, want %q", got.Reason, want)
	}
}

// The number of machines a provider should have is a reading, not an
// increment. A pass that added its answer to what the last pass asked for would
// buy the same shortfall again every time it ran, which is how a queue of five
// jobs ends up costing fifty machines.
func TestAMachineTargetIsAReadingNotAnIncrement(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("linux-x64", "linux", "x64")
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
		Jobs: demandJobs(5), Limits: demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 5, 5, "nowhere")}},
	}
	first := planFor(t, DecideMachines(s), p.ID)
	if first.Create != 3 {
		t.Fatalf("first pass create = %d, want 3", first.Create)
	}

	// The pass acted: three machines are on their way and nothing else moved.
	for _, id := range []string{"mach_1", "mach_2", "mach_3"} {
		s.Machines = append(s.Machines, demandMachine(id, p, store.MachinePlanned, time.Minute))
	}
	for range 2 {
		got := planFor(t, DecideMachines(s), p.ID)
		if got.Create != 0 {
			t.Fatalf("create = %d, want 0: the machines already on their way are the answer", got.Create)
		}
		if got.Wanted != 3 || got.Have != 3 {
			t.Fatalf("wanted/have = %d/%d, want 3/3", got.Wanted, got.Have)
		}
	}
}

// The same snapshot always yields the same plan, whatever order its rows
// arrived in. A decision that moved with a map walk or a database's ordering
// would buy a machine on one pass and release it on the next.
func TestDecideMachinesIsDeterministic(t *testing.T) {
	build := func(reversed bool) MachineSnapshot {
		lab, spare := demandProvider("lab"), demandProvider("spare")
		spare.MaxMachines = 0 // may own nothing, so demand walks past it
		alpha, beta := demandPool("alpha"), demandPool("beta")
		host := demandHost("host_1", 2, 2)
		ready := demandMachine("mach_ready", lab, store.MachineReady, 3*time.Hour)
		ready.HostID = host.ID
		ready.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
		planned := demandMachine("mach_planned", lab, store.MachinePlanned, time.Minute)
		s := MachineSnapshot{
			Now:       machineNow,
			Pools:     []*store.Pool{alpha, beta},
			Hosts:     []*store.Host{host},
			Providers: []*store.Provider{lab, spare},
			Machines:  []*store.Machine{ready, planned},
			Jobs:      demandJobs(3),
			Limits:    demandLimits(),
			Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{
				demandPoolPlan(alpha, 2, 6, 3, "capacity"),
				demandPoolPlan(beta, 0, 2, 2, "nowhere"),
			}},
		}
		if reversed {
			reverse(s.Pools)
			reverse(s.Providers)
			reverse(s.Machines)
			reverse(s.Plan.Pools)
		}
		return s
	}

	want := DecideMachines(build(false))
	for i := range 5 {
		if got := DecideMachines(build(i%2 == 1)); !reflect.DeepEqual(got, want) {
			t.Fatalf("pass %d = %+v, want %+v", i, got.Providers, want.Providers)
		}
	}
}

// The calculation is handed the controller's own live rows, so anything it
// wrote through them -- or any slice it sorted in place -- would be a change to
// the fleet's state made by a function that only claims to decide.
func TestDecideMachinesDoesNotMutateItsInput(t *testing.T) {
	lab := demandProvider("lab")
	// Every slice is handed over in an order the calculation has to sort, so an
	// in-place sort shows up as a changed snapshot rather than as nothing.
	alpha, beta := demandPool("alpha"), demandPool("beta")
	host := demandHost("host_2", 2, 0)
	ready := demandMachine("mach_ready", lab, store.MachineReady, 3*time.Hour)
	ready.HostID = host.ID
	ready.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
	planned := demandMachine("mach_planned", lab, store.MachinePlanned, time.Minute)
	s := MachineSnapshot{
		Now:       machineNow,
		Pools:     []*store.Pool{beta, alpha},
		Hosts:     []*store.Host{host},
		Providers: []*store.Provider{lab},
		Machines:  []*store.Machine{planned, ready},
		Runners:   map[string][]*store.Runner{alpha.ID: {}},
		Jobs:      demandJobs(2),
		Limits:    demandLimits(),
		Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{
			demandPoolPlan(alpha, 0, 3, 2, "nowhere"),
			demandPoolPlan(beta, 0, 0, 0, ""),
		}},
	}
	before := cloneSnapshot(s)

	DecideMachines(s)

	if !reflect.DeepEqual(s, before) {
		t.Fatalf("the snapshot changed:\n got %+v\nwant %+v", s, before)
	}
}

// Idleness has to be sustained before it is acted on. A machine released
// between two bursts is one the second burst pays to build again -- minutes of
// queueing for a hypervisor clone -- so the idle timeout says when a machine
// stopped being useful and the cooldown is how long that has to keep being
// true.
func TestScaleDownNeedsTheObservationToHoldForOneCooldown(t *testing.T) {
	for _, tc := range []struct {
		name      string
		idleFor   time.Duration
		idleNever bool
		busy      bool
		wantDrain bool
	}{
		{name: "never idle", idleNever: true},
		{name: "idle, but not yet for the idle timeout", idleFor: 5 * time.Minute},
		{name: "past the idle timeout, still inside the cooldown", idleFor: 20 * time.Minute},
		{name: "idle past the timeout and the cooldown", idleFor: 30 * time.Minute, wantDrain: true},
		{name: "idle long enough, but a runner landed on it", idleFor: 30 * time.Minute, busy: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := demandProvider("lab")
			pool := demandPool("alpha")
			host := demandHost("host_1", 2, 0)
			m := demandMachine("mach_1", p, store.MachineReady, 4*time.Hour)
			m.HostID = host.ID
			if !tc.idleNever {
				m.IdleSince = ptrTime(machineNow.Add(-tc.idleFor))
			}
			runners := map[string][]*store.Runner{}
			if tc.busy {
				host.ActiveRunners = 1
				runners[pool.ID] = []*store.Runner{{ID: "run_1", PoolID: pool.ID, HostID: host.ID, State: store.RunnerBusy}}
			}
			s := MachineSnapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host},
				Providers: []*store.Provider{p}, Machines: []*store.Machine{m}, Runners: runners,
				Limits: demandLimits(),
				Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 0, 0, "")}},
			}

			got := planFor(t, DecideMachines(s), p.ID)
			if drained := len(got.Drain) == 1; drained != tc.wantDrain {
				t.Fatalf("drain = %v, want drained = %v", got.Drain, tc.wantDrain)
			}
		})
	}
}

// A machine whose slots a pool is still waiting for is not idle capacity,
// however long nothing has run on it: releasing it would reopen the shortfall
// the next pass then buys a machine to close.
func TestADrainIsRefusedWhileAPoolItServesIsStillShort(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	host := demandHost("host_1", 2, 0)
	m := demandMachine("mach_1", p, store.MachineReady, 4*time.Hour)
	m.HostID = host.ID
	m.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host},
		Providers: []*store.Provider{p}, Machines: []*store.Machine{m},
		Limits: demandLimits(),
		Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 1, 3, 2, "capacity")}},
	}

	if got := planFor(t, DecideMachines(s), p.ID); len(got.Drain) != 0 {
		t.Fatalf("drain = %v, want nothing released while the pool is still short", got.Drain)
	}
}

// Newest first, so the machine with the least warmed cache is the one thrown
// away, and the order is fixed so two passes over one snapshot never disagree
// about which machine goes.
func TestTheNewestIdleMachineIsDrainedFirst(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	older, newer := demandHost("host_old", 2, 0), demandHost("host_new", 2, 0)
	first := demandMachine("mach_older", p, store.MachineReady, 6*time.Hour)
	first.HostID, first.IdleSince = older.ID, ptrTime(machineNow.Add(-2*time.Hour))
	second := demandMachine("mach_newer", p, store.MachineReady, time.Hour)
	second.HostID, second.IdleSince = newer.ID, ptrTime(machineNow.Add(-2*time.Hour))
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{older, newer},
		Providers: []*store.Provider{p}, Machines: []*store.Machine{first, second},
		Limits: demandLimits(),
		Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 0, 0, "")}},
	}

	got := planFor(t, DecideMachines(s), p.ID)
	if want := []string{"mach_newer", "mach_older"}; !reflect.DeepEqual(got.Drain, want) {
		t.Fatalf("drain = %v, want %v", got.Drain, want)
	}
}

// A maximum of none is none, for a provider and for the fleet alike -- the same
// rule a pool's max_runners of zero obeys. Zero meaning "unlimited" would put
// the number that decides the size of an invoice behind a value somebody can
// leave unset.
func TestACeilingOfNoMachinesBuysNothing(t *testing.T) {
	for _, tc := range []struct {
		name     string
		limits   func(*MachineLimits)
		provider func(*store.Provider)
		want     string
		wantFix  string
	}{
		{
			name:     "the provider may own none",
			limits:   func(*MachineLimits) {},
			provider: func(p *store.Provider) { p.MaxMachines = 0 },
			want:     "3 machines not bought: lab may own no machines at all",
			wantFix:  "set this provider's maximum machines to the number of machines you are willing to pay for",
		},
		{
			name:     "the fleet may own none",
			limits:   func(l *MachineLimits) { l.MaxMachines = 0 },
			provider: func(*store.Provider) {},
			want:     "3 machines not bought: provider.max_machines is 0, so this fleet rents nothing",
			wantFix:  "set provider.max_machines to the number of machines this fleet may pay for",
		},
		{
			name:     "the provider may build none",
			limits:   func(*MachineLimits) {},
			provider: func(p *store.Provider) { p.MaxCreatesInFlight = 0 },
			want:     "3 machines not bought: lab may build no machine at a time",
			wantFix:  "raise this provider's maximum creates in flight above 0",
		},
		{
			name:     "the fleet may build none",
			limits:   func(l *MachineLimits) { l.MaxCreatesInFlight = 0 },
			provider: func(*store.Provider) {},
			want:     "3 machines not bought: provider.max_creates_in_flight is 0, so nothing may be built",
			wantFix:  "set provider.max_creates_in_flight to the number of machines that may be built at once",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := demandProvider("lab")
			tc.provider(p)
			limits := demandLimits()
			tc.limits(&limits)
			pool := demandPool("linux-x64", "linux", "x64")
			s := MachineSnapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
				Jobs: demandJobs(5), Limits: limits,
				Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 5, 5, "nowhere")}},
			}

			got := planFor(t, DecideMachines(s), p.ID)
			if got.Create != 0 || got.Reason != "" {
				t.Fatalf("create %d reason %q, want nothing bought", got.Create, got.Reason)
			}
			if got.Blocked != tc.want || got.BlockedFix != tc.wantFix {
				t.Fatalf("blocked %q / fix %q,\nwant %q / %q", got.Blocked, got.BlockedFix, tc.want, tc.wantFix)
			}
		})
	}
}

// An operator sent to raise the limit that was not the one holding them back
// has been sent to the wrong screen, so the sentence names whichever ceiling
// actually bound -- and the ones that did not bite say nothing.
func TestTheCeilingThatBindsIsTheOneNamed(t *testing.T) {
	for _, tc := range []struct {
		name       string
		limits     func(*MachineLimits)
		provider   func(*store.Provider)
		owned      int
		wantCreate int
		wantBlock  string
	}{
		{
			name:       "the provider is nearly full",
			limits:     func(*MachineLimits) {},
			provider:   func(p *store.Provider) { p.MaxMachines = 3 },
			owned:      2,
			wantCreate: 1,
			wantBlock:  "2 machines not bought: lab owns 2 machines and its maximum is 3",
		},
		{
			name:       "the fleet's ceiling is the lower one",
			limits:     func(l *MachineLimits) { l.MaxMachines = 2 },
			provider:   func(*store.Provider) {},
			wantCreate: 2,
			wantBlock:  "1 machine not bought: provider.max_machines allows only 2 machines across the fleet",
		},
		{
			name:       "the provider may only build one at a time",
			limits:     func(*MachineLimits) {},
			provider:   func(p *store.Provider) { p.MaxCreatesInFlight = 1 },
			wantCreate: 1,
			wantBlock:  "2 machines not bought: lab may build only 1 machine at a time",
		},
		{
			name:       "nothing binds",
			limits:     func(*MachineLimits) {},
			provider:   func(*store.Provider) {},
			wantCreate: 3,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := demandProvider("lab")
			tc.provider(p)
			limits := demandLimits()
			tc.limits(&limits)
			pool := demandPool("linux-x64", "linux", "x64")
			s := MachineSnapshot{
				Now: machineNow, Pools: []*store.Pool{pool}, Providers: []*store.Provider{p},
				Jobs: demandJobs(5), Limits: limits,
				Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 5, 5, "nowhere")}},
			}
			// Machines that already own a resource are what a maximum counts.
			for i := range tc.owned {
				s.Machines = append(s.Machines, demandMachine("mach_own_"+string(rune('a'+i)), p, store.MachineFailed, time.Hour))
			}

			got := planFor(t, DecideMachines(s), p.ID)
			if got.Create != tc.wantCreate {
				t.Fatalf("create = %d, want %d", got.Create, tc.wantCreate)
			}
			if got.Blocked != tc.wantBlock {
				t.Fatalf("blocked = %q, want %q", got.Blocked, tc.wantBlock)
			}
			if tc.wantBlock != "" && got.BlockedFix == "" {
				t.Fatal("blocked with no fix: a refusal an operator cannot act on")
			}
		})
	}
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func ptrTime(t time.Time) *time.Time { return &t }

func reverse[T any](in []T) {
	for i, j := 0, len(in)-1; i < j; i, j = i+1, j-1 {
		in[i], in[j] = in[j], in[i]
	}
}

// cloneSnapshot copies a snapshot deeply enough that reflect.DeepEqual against
// it catches both a field written through a pointer and a slice sorted in
// place.
func cloneSnapshot(s MachineSnapshot) MachineSnapshot {
	out := s
	out.Pools = clonePointers(s.Pools)
	out.Hosts = clonePointers(s.Hosts)
	out.Machines = clonePointers(s.Machines)
	out.Providers = clonePointers(s.Providers)
	out.Jobs = clonePointers(s.Jobs)
	out.Plan.Pools = append([]scheduler.PoolPlan(nil), s.Plan.Pools...)
	if s.Runners != nil {
		out.Runners = make(map[string][]*store.Runner, len(s.Runners))
		for k, v := range s.Runners {
			out.Runners[k] = clonePointers(v)
		}
	}
	return out
}

func clonePointers[T any](in []*T) []*T {
	if in == nil {
		return nil
	}
	out := make([]*T, len(in))
	for i, v := range in {
		if v != nil {
			c := *v
			out[i] = &c
		}
	}
	return out
}

// A blip is not a machine that has gone away.
//
// A silent host is ruled out for every pool, so the test that would have said
// "the fleet still wants this machine" is skipped rather than failed, and an
// idle machine becomes releasable the moment its host stops answering. That
// turns a network partition into a delete: the VM is up, doing nothing wrong,
// and would answer again in five minutes. provider.delete_grace is how long the
// silence has to last before it is believed, and it is deliberately longer than
// the host-lost judgement so that by the time it expires the runners that were
// on the host have already been failed and the emptiness is real.
func TestAMachineIsNotReleasedWhileItsHostsSilenceIsStillShorterThanTheGrace(t *testing.T) {
	limits := demandLimits()
	limits.DeleteGrace = 10 * time.Minute

	build := func(silentFor time.Duration) MachineSnapshot {
		p := demandProvider("lab")
		pool := demandPool("alpha")
		host := demandHost("host_1", 2, 0)
		host.LastHeartbeat = machineNow.Add(-silentFor)
		m := demandMachine("mach_1", p, store.MachineReady, 4*time.Hour)
		m.HostID = host.ID
		m.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
		return MachineSnapshot{
			Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host},
			Providers: []*store.Provider{p}, Machines: []*store.Machine{m},
			Limits: limits,
			Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 0, 0, "")}},
		}
	}

	// Quiet for two minutes: past the health timeout, nowhere near the grace.
	if got := planFor(t, DecideMachines(build(2*time.Minute)), "prv_lab"); len(got.Drain) != 0 {
		t.Errorf("a machine was released after two minutes of silence: %v", got.Drain)
	}
	// Quiet for fifteen: the silence has outlasted the grace and is believed.
	if got := planFor(t, DecideMachines(build(15*time.Minute)), "prv_lab"); len(got.Drain) != 1 {
		t.Errorf("a machine silent past its grace was kept: drain = %v", got.Drain)
	}
	// And a machine whose host is answering is unaffected by any of it.
	if got := planFor(t, DecideMachines(build(0)), "prv_lab"); len(got.Drain) != 1 {
		t.Errorf("a healthy idle machine was kept: drain = %v", got.Drain)
	}
}

// An unset grace leaves the decision exactly as it was, which is how the
// validator already treats it.
func TestAnUnsetDeleteGraceChangesNothing(t *testing.T) {
	p := demandProvider("lab")
	pool := demandPool("alpha")
	host := demandHost("host_1", 2, 0)
	host.LastHeartbeat = machineNow.Add(-2 * time.Minute)
	m := demandMachine("mach_1", p, store.MachineReady, 4*time.Hour)
	m.HostID = host.ID
	m.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
	s := MachineSnapshot{
		Now: machineNow, Pools: []*store.Pool{pool}, Hosts: []*store.Host{host},
		Providers: []*store.Provider{p}, Machines: []*store.Machine{m},
		Limits: demandLimits(),
		Plan:   scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 0, 0, 0, "")}},
	}
	if got := planFor(t, DecideMachines(s), p.ID); len(got.Drain) != 1 {
		t.Errorf("an unset grace withheld a release: drain = %v", got.Drain)
	}
}

// A throttled host has already given back slots it will not re-place, and a
// machine must not be released to cover work those slots can no longer do.
//
// The throttle takes capacity from future placements and leaves the runners
// already on the host alone, so a throttled host sits over its effective
// capacity until they finish. Counting the operator's configured number there
// says the fleet has room it does not have: the machine goes, the next burst
// queues, the pool reports itself at capacity because the throttle-taken slots
// count as full, and the fleet buys the same machine again -- two clones paid
// for, and the queue latency of the second.
func TestAMachineIsKeptWhileAThrottleHasTakenTheSlotsThatWouldReplaceIt(t *testing.T) {
	// The operator's own host, full and throttled a rung: four configured
	// slots, three once the throttle has had its share, and four runners on it
	// that the throttle does not evict.
	build := func(level int) MachineSnapshot {
		p := demandProvider("lab")
		pool := demandPool("alpha")
		busy := demandHost("host_busy", 4, 4)
		busy.Throttle = store.HostThrottle{Level: level}
		rented := demandHost("host_rented", 2, 0)
		m := demandMachine("mach_1", p, store.MachineReady, 4*time.Hour)
		m.HostID = rented.ID
		m.IdleSince = ptrTime(machineNow.Add(-2 * time.Hour))
		return MachineSnapshot{
			Now: machineNow, Pools: []*store.Pool{pool},
			Hosts:     []*store.Host{busy, rented},
			Providers: []*store.Provider{p}, Machines: []*store.Machine{m},
			Limits: demandLimits(),
			// The pool is satisfied only because the busy host's four runners
			// are still going.
			Plan: scheduler.Plan{Pools: []scheduler.PoolPlan{demandPoolPlan(pool, 4, 4, 4, "")}},
		}
	}

	// Unthrottled the fleet really does have the slack, so the machine goes.
	if got := planFor(t, DecideMachines(build(0)), "prv_lab"); len(got.Drain) != 1 {
		t.Errorf("an idle machine beside an unthrottled fleet was kept: drain = %v", got.Drain)
	}
	// Throttled one rung, the busy host will re-place only three of its four,
	// so the fleet is short and the machine is what covers it.
	if got := planFor(t, DecideMachines(build(1)), "prv_lab"); len(got.Drain) != 0 {
		t.Errorf("a machine was released against slots a throttle had already taken: drain = %v", got.Drain)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// What goes inside a guest, and what deliberately does not.
//
// A machine receives exactly one credential: a single-use, minutes-long join
// token scoped to this machine's own name. Its only power is to create one host
// row with labels an operator chose. It cannot read the provider's API,
// enumerate machines or delete anything -- and if it is copied out of the guest
// it enrols nothing, because the store refuses it under any other name inside
// the transaction that would spend it.
//
// The provider's own credential never comes near this. It is sealed in the
// provider row under the instance key, unsealed only for the life of one
// client, and there is no code path that could copy it into a payload:
// provider.Bootstrap has files and argv arrays and no field a credential could
// go in. A test plants a recognisable token in the provider row and scans every
// byte of every payload for it.
//
// Nothing here builds a shell command line. The transport writes bytes and runs
// an argv array, which removes the entire quoting and injection class that the
// human join command's shell round-trip test exists to police.

const (
	// machineEnvPath is where the agent's unit reads its environment from --
	// the path and the key names internal/installer already writes, so a
	// template prepared with the ordinary agent install needs nothing special.
	machineEnvPath = "/etc/zoomies/zoomies.env"
	// machineEnvMode is 0600 because the file holds a join token. Some
	// transports cannot set a mode when they write a file, which is why the
	// chmod below is a command rather than an assumption.
	machineEnvMode = 0o600
	// machineWorkDir is where a runner's checkout and caches land inside the
	// guest.
	machineWorkDir = "/var/lib/zoomies/work"
	// machineCAPath is where a provider-supplied controller CA is written, for
	// a controller behind a certificate the guest's trust store has never seen.
	machineCAPath = "/etc/zoomies/controller-ca.pem"
	// machineTokenGrace is added to the enrolment timeout when the token is
	// minted. The credential must outlast the window the machine is given to
	// use it, or a machine that booted slowly is refused by its own token --
	// and it must not outlast it by much, because nobody is watching it.
	machineTokenGrace = 5 * time.Minute
)

// stepBootstrapping puts the enrolment payload inside the guest.
//
// A bootstrap may have to be run again -- a payload that was written and never
// acknowledged is indistinguishable from one that was lost -- so the first
// question it asks is whether this machine's credential has already been
// spent. A redeemed token is proof the guest got the payload, whatever became
// of the acknowledgement, and re-running would then be writing over an agent
// that is already joining.
func (c *Controller) stepBootstrapping(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	if m.OpHandle != "" {
		status, err := pr.p.Operation(ctx, provider.OperationRef{Kind: provider.OpBootstrap, Handle: m.OpHandle})
		switch {
		case errors.Is(err, provider.ErrNotFound):
		case err != nil:
			return err
		case !status.Done:
			return errMachineWaiting
		case !status.OK:
			// The guest's own words, on the bootstrap column rather than the
			// provider one: two systems complained, and an operator reading
			// one error has to know which half to go and look at.
			detail := status.Detail
			if detail == "" {
				detail = "the agent install did not report why it failed"
			}
			if err := c.st.RecordMachineFailure(ctx, m.ID, store.MachineErrorBootstrap, detail,
				c.Now().Add(c.machineBackoff(m.Attempts+1))); err != nil {
				c.log.Warn("could not record a bootstrap failure", "machine", m.ID, "error", err)
			}
			return &provider.Error{Kind: provider.FailureRefused, Op: "bootstrap", Ref: m.Name, Message: detail}
		default:
			c.transitionMachine(ctx, env, m, store.MachineEnrolling,
				"the agent is installed and is joining this controller")
			return nil
		}
	}

	// A token this machine minted that has already been spent means the agent
	// inside the guest has what it needs, whatever became of the payload we
	// wrote: the write is what could be lost, and the redemption is proof it
	// was not.
	if spent, err := c.machineTokenSpent(ctx, m); err != nil {
		c.log.Warn("could not read a machine's join token", "machine", m.ID, "error", err)
	} else if spent {
		c.transitionMachine(ctx, env, m, store.MachineEnrolling,
			"the agent has its credential and is joining this controller")
		return nil
	}

	boot, ok := pr.p.(provider.Bootstrapper)
	if !ok {
		// The payload travelled with the create, so there is nothing to push.
		// The machine is waiting on the agent inside it, which the enrolment
		// timeout bounds.
		c.transitionMachine(ctx, env, m, store.MachineEnrolling,
			"the enrolment payload went with this machine; waiting for its agent to join")
		return nil
	}
	if held := c.mutationsHeld(); held != "" {
		return fmt.Errorf("%w: %s", errMachineHeld, held)
	}
	payload, err := c.machineBootstrap(ctx, env, pr.row, m)
	if err != nil {
		return err
	}
	op, err := boot.Bootstrap(ctx, machineRef(m), payload)
	if err != nil {
		return c.noteAmbiguity(ctx, m, err)
	}
	if op.Zero() {
		c.transitionMachine(ctx, env, m, store.MachineEnrolling,
			"the agent is installed and is joining this controller")
		return nil
	}
	if err := c.st.SetMachineOperationHandle(ctx, m.ID, m.OpID, op.Handle); err != nil {
		c.log.Warn("could not record a bootstrap's handle", "machine", m.ID, "error", err)
	}
	return errMachineWaiting
}

// machineBootstrap mints this machine's credential if it has none and renders
// the payload that carries it.
func (c *Controller) machineBootstrap(ctx context.Context, env *machineEnv, row *store.Provider, m *store.Machine) (provider.Bootstrap, error) {
	token, err := c.machineJoinToken(ctx, env, row, m)
	if err != nil {
		return provider.Bootstrap{}, err
	}
	return bootstrapPayload(m, row, token, env.cfg), nil
}

// machineJoinToken returns the plaintext of this machine's join token, minting
// one when it has none this pass can use.
//
// A token already minted cannot be re-read -- only its hash is stored -- so a
// machine whose payload was written and lost gets a fresh one, and the one it
// replaces is revoked rather than left to expire. Either would be safe, since
// both are single-use and scoped to the same single name; revoking is what
// keeps "one machine, one live credential" true rather than merely harmless.
func (c *Controller) machineJoinToken(ctx context.Context, env *machineEnv, row *store.Provider, m *store.Machine) (string, error) {
	if m.JoinTokenID != "" {
		spent, err := c.machineTokenSpent(ctx, m)
		switch {
		case err != nil:
			return "", err
		case spent:
			// Already redeemed: the agent has what it needs and the machine is
			// waiting to be linked, not to be bootstrapped again.
			return "", fmt.Errorf("%w: machine %s has already spent its join token", errMachineWaiting, m.ID)
		}
		// Unspent, and its plaintext cannot be read back -- only the hash is
		// kept. Re-minting is the only way to write the payload again, and the
		// one it replaces is revoked here rather than left to expire: two live
		// credentials for one machine is one more than the design allows
		// itself, even where both are scoped to the same single name.
		if err := c.st.RevokeUnusedJoinToken(ctx, m.JoinTokenID); err != nil && !errors.Is(err, store.ErrNotFound) {
			return "", fmt.Errorf("revoking machine %s's previous join token: %w", m.ID, err)
		}
	}
	ttl := env.cfg.Provider.EnrolTimeout + machineTokenGrace
	tok, plaintext, err := c.authsvc.CreateScopedJoinToken(ctx, auth.JoinScope{
		TTL:      ttl,
		Labels:   row.MachineLabels,
		Capacity: row.MachineCapacity,
		// The two scope fields. The name is the machine's own, which is what
		// the store checks the claim against.
		MachineID:    m.ID,
		ExpectedName: m.Name,
		CreatedBy:    "machine " + m.ID,
	})
	if err != nil {
		return "", fmt.Errorf("minting machine %s's join token: %w", m.ID, err)
	}
	if err := c.st.SetMachineJoinToken(ctx, m.ID, tok.ID); err != nil {
		// Do not leave an untracked credential valid after a failed link.
		cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
		defer cancel()
		if revokeErr := c.st.DeleteJoinToken(cleanupCtx, tok.ID); revokeErr != nil {
			return "", errors.Join(err, revokeErr)
		}
		return "", fmt.Errorf("recording machine %s's join token: %w", m.ID, err)
	}
	m.JoinTokenID = tok.ID
	return plaintext, nil
}

// machineTokenSpent reports whether the credential this machine was given has
// been redeemed, which is the only proof that the payload reached the guest.
func (c *Controller) machineTokenSpent(ctx context.Context, m *store.Machine) (bool, error) {
	if m.JoinTokenID == "" {
		return false, nil
	}
	tok, err := c.st.GetJoinToken(ctx, m.JoinTokenID)
	if errors.Is(err, store.ErrNotFound) {
		// Pruned or revoked: not proof of anything, and a fresh one is minted.
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return tok.UsedAt != nil, nil
}

// bootstrapPayload renders what goes into the guest. It is pure so that the
// file an operator would find on a machine is something a test can assert on
// byte for byte, rather than something that only exists after a create.
//
// ZOOMIES_AGENT_NAME is pinned to the machine's own name, and that is not
// cosmetic. machine.DefaultHostName derives a name from the hardware and the
// hostname, so identical clones of one template compute the SAME name -- and
// the second one's join is refused with "a host named %q is already enrolled
// here". Every machine a provider builds is a clone of one template, so this is
// the failure every fleet would hit on its second machine.
func bootstrapPayload(m *store.Machine, row *store.Provider, token string, cfg *config.Config) provider.Bootstrap {
	var b strings.Builder
	b.WriteString("# Zoomies -- written by the controller when this machine was created.\n")
	b.WriteString("# It carries one credential: a single-use join token for this machine alone.\n")
	set := func(key, value string) {
		if value == "" {
			return
		}
		b.WriteString(key + "=" + value + "\n")
	}
	set("ZOOMIES_CONTROLLER_URL", controllerURLFor(row, cfg))
	set("ZOOMIES_JOIN_TOKEN", token)
	set("ZOOMIES_AGENT_NAME", m.Name)
	if capacity := row.MachineCapacity; capacity > 0 {
		set("ZOOMIES_AGENT_CAPACITY", strconv.Itoa(capacity))
	}
	set("ZOOMIES_AGENT_BACKEND", string(row.MachineBackend))
	set("ZOOMIES_AGENT_LABELS", machineLabelsFor(row.MachineLabels))
	set("ZOOMIES_WORK_DIR", machineWorkDir)

	files := []provider.File{{Path: machineEnvPath, Mode: machineEnvMode, Content: []byte(b.String())}}
	if row.CAPEM != "" {
		// Only when the provider supplies one: a guest told to trust a file
		// that is not there refuses to start, which is worse than a guest that
		// uses its own trust store.
		files = append(files, provider.File{Path: machineCAPath, Mode: 0o644, Content: []byte(row.CAPEM)})
		files[0].Content = append(files[0].Content, []byte("ZOOMIES_AGENT_CA_FILE="+machineCAPath+"\n")...)
	}

	return provider.Bootstrap{
		Files: files,
		Commands: [][]string{
			// The chmod is required rather than tidy: a transport that writes
			// a file has no way to say what mode it should have, and this file
			// holds a credential.
			{"/bin/chmod", "0600", machineEnvPath},
			// enable --now, so that the unit the template ships disabled comes
			// up here and comes up again after a reboot. A template that
			// shipped it enabled would have every clone try to join before it
			// had an environment file to join with.
			{"/bin/systemctl", "enable", "--now", "zoomies-agent"},
		},
	}
}

// controllerURLFor is how the guest reaches this controller: the provider's own
// answer where it has one -- a machine on a private network usually cannot use
// the URL a browser does -- and the fleet's external URL otherwise.
func controllerURLFor(row *store.Provider, cfg *config.Config) string {
	if u := strings.TrimSpace(row.Settings["controller_url"]); u != "" {
		return strings.TrimRight(u, "/")
	}
	return strings.TrimRight(cfg.Server.ExternalURL, "/")
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/installer"
)

// The controller writes a clone's enrolment to one path and the unit
// `zoomies agent install` leaves in the template reads another only if the two
// packages drift, which is a fleet of machines that boot and never join.
func TestTheEnrolmentFileIsWhereTheTemplatesUnitReadsIt(t *testing.T) {
	if machineEnvPath != installer.MachineEnvPath {
		t.Fatalf("controller writes %s, the template's unit reads %s", machineEnvPath, installer.MachineEnvPath)
	}
}

package controller

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// The guest gets exactly one credential, and this is the test that says so.
//
// A provider credential can read the whole hypervisor: enumerate machines,
// destroy them, and read every other guest's configuration. It is sealed in the
// provider row and unsealed only for the life of one client, and nothing copies
// it into a payload -- provider.Bootstrap has files and argv arrays and no
// field one could go in. This scans every byte that reached a guest for it,
// because a type can be changed and a test cannot be argued with.
func TestABootstrapPayloadCarriesNoProviderCredential(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	const secret = "PVEAPIToken=zoomies@pve!ci=9f1c0a3e-recognisable-2b7d"
	sealed, err := h.key.SealString(secret)
	if err != nil {
		t.Fatalf("sealing the provider credential: %v", err)
	}
	if err := h.st.SetProviderCredentials(h.ctx, row.ID, sealed); err != nil {
		t.Fatalf("SetProviderCredentials: %v", err)
	}

	h.machinePass(t)
	m := h.onlyMachine(t)
	h.drive(t, m.ID, store.MachineEnrolling, 6)

	payloads := h.fake.Bootstraps()
	if len(payloads) == 0 {
		t.Fatal("nothing reached the guest at all, so this test proves nothing")
	}
	for _, b := range payloads {
		for _, f := range b.Files {
			if bytes.Contains(f.Content, []byte(secret)) {
				t.Fatalf("the provider's credential was written into %s", f.Path)
			}
		}
		for _, argv := range b.Commands {
			for _, arg := range argv {
				if strings.Contains(arg, secret) {
					t.Fatalf("the provider's credential was passed as an argument: %q", arg)
				}
			}
		}
	}
}

// The name the guest enrols under must be pinned, and this is the reason.
// machine.DefaultHostName derives a name from the hardware and the hostname, so
// two clones of one template compute the same one -- and every machine a
// provider builds is a clone of one template. Without the pin the second
// machine's join is refused with "a host named %q is already enrolled here",
// and the fleet stops growing at one.
func TestTheEnrolmentFilePinsTheMachineName(t *testing.T) {
	m := &store.Machine{ID: "mach_abc", Name: "zoomies-mach-abc", Capacity: 2}
	row := &store.Provider{
		Name: "lab", MachineCapacity: 4, MachineBackend: store.BackendDocker,
		MachineLabels: store.StringMap{"tier": "untrusted", "site": "dc1"},
	}
	cfg := config.Default()
	cfg.Server.ExternalURL = "https://zoomies.test/"

	payload := bootstrapPayload(m, row, "zoojoin_abc_secret", cfg)
	env := envOf(t, payload)

	for _, want := range []struct{ key, value string }{
		{"ZOOMIES_AGENT_NAME", m.Name},
		{"ZOOMIES_JOIN_TOKEN", "zoojoin_abc_secret"},
		{"ZOOMIES_CONTROLLER_URL", "https://zoomies.test"},
		{"ZOOMIES_AGENT_CAPACITY", "4"},
		{"ZOOMIES_AGENT_BACKEND", "docker"},
		{"ZOOMIES_AGENT_LABELS", "site=dc1,tier=untrusted"},
		{"ZOOMIES_WORK_DIR", machineWorkDir},
	} {
		if got := env[want.key]; got != want.value {
			t.Errorf("%s is %q, want %q", want.key, got, want.value)
		}
	}
}

// The environment file is chmodded because the transport that writes it has no
// way to say what mode it should have, and the file holds a credential. The
// unit is enabled rather than started so that a reboot brings the agent back.
func TestTheEnrolmentFileIsChmoddedBecauseAFileWriteHasNoMode(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.machinePass(t)
	m := h.onlyMachine(t)
	h.drive(t, m.ID, store.MachineEnrolling, 6)

	payload := h.fake.Bootstraps()[0]
	var wrote bool
	for _, f := range payload.Files {
		if f.Path == machineEnvPath {
			wrote = true
			if f.Mode != machineEnvMode {
				t.Errorf("the enrolment file asks for mode %#o, want %#o", f.Mode, machineEnvMode)
			}
		}
	}
	if !wrote {
		t.Fatalf("nothing was written to %s", machineEnvPath)
	}
	want := [][]string{
		{"/bin/chmod", "0600", machineEnvPath},
		{"/bin/systemctl", "enable", "--now", "zoomies-agent"},
	}
	if len(payload.Commands) != len(want) {
		t.Fatalf("the payload runs %d commands, want %d: %v", len(payload.Commands), len(want), payload.Commands)
	}
	for i, argv := range payload.Commands {
		if strings.Join(argv, " ") != strings.Join(want[i], " ") {
			t.Errorf("command %d is %v, want %v", i, argv, want[i])
		}
	}
}

// Nothing in this path builds a shell command line. A payload that is never
// pasted into a shell has no quoting to get wrong and no injection class to
// police, which is the whole reason the transport takes an argv array.
func TestTheBootstrapNeverBuildsAShellCommandLine(t *testing.T) {
	m := &store.Machine{ID: "mach_x", Name: "zoomies-mach-x; rm -rf /"}
	row := &store.Provider{Name: "lab", MachineCapacity: 1,
		MachineLabels: store.StringMap{"note": "a value with spaces and a $VARIABLE"}}
	payload := bootstrapPayload(m, row, "zoojoin_x_`whoami`", config.Default())

	for _, argv := range payload.Commands {
		if len(argv) < 2 {
			t.Fatalf("a command with no arguments is a shell line waiting to happen: %v", argv)
		}
		if !strings.HasPrefix(argv[0], "/") {
			t.Errorf("command %v does not name an absolute executable, so it would be resolved through a PATH we do not control", argv)
		}
		for _, shell := range []string{"sh", "bash", "-c"} {
			for _, arg := range argv {
				if arg == shell {
					t.Errorf("the payload runs a shell: %v", argv)
				}
			}
		}
	}
}

// A token minted for one machine may not enrol another, and the check runs
// inside the transaction that spends it: a credential that leaks out of a guest
// is not stopped by a check that happens afterwards.
func TestAJoinTokenMintedForOneMachineCannotEnrolAnother(t *testing.T) {
	h := newHarness(t)
	_, plaintext, err := h.c.Auth().CreateScopedJoinToken(h.ctx, auth.JoinScope{
		TTL: time.Minute, Capacity: 2, MachineID: "mach_abc", ExpectedName: "zoomies-mach-abc",
		CreatedBy: "machine mach_abc",
	})
	if err != nil {
		t.Fatalf("CreateScopedJoinToken: %v", err)
	}

	if _, err := h.c.Join(h.ctx, joinRequest("somebody-elses-laptop", plaintext), "203.0.113.9"); err == nil {
		t.Fatal("a machine's join token enrolled a host it was not minted for")
	} else if !errors.Is(err, auth.ErrInvalidInput) {
		t.Fatalf("the refusal is %v, want one the agent's operator can act on", err)
	}

	// And the token is still there to be spent by the machine it belongs to,
	// because a refused claim must not burn the credential.
	if _, err := h.c.Join(h.ctx, joinRequest("zoomies-mach-abc", plaintext), "203.0.113.9"); err != nil {
		t.Fatalf("the machine the token was minted for could not use it: %v", err)
	}
}

// A token an operator pastes is theirs to look after, and they pick the name
// themselves. The human path must not gain a scope check it cannot satisfy.
func TestAnOperatorsJoinTokenStillEnrolsWhateverTheyName(t *testing.T) {
	h := newHarness(t)
	token := h.joinToken(t, map[string]string{"tier": "trusted"}, 4)

	if _, err := h.c.Join(h.ctx, joinRequest("builder-07", token), "203.0.113.9"); err != nil {
		t.Fatalf("an unscoped join token refused a name the operator chose: %v", err)
	}
}

// The token is minted once and recorded on the machine, so a pass that comes
// back to a machine already waiting on its agent does not mint a second
// credential for it.
func TestAMachineMintsOneCredentialAndRecordsIt(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.machinePass(t)
	m := h.onlyMachine(t)
	m = h.drive(t, m.ID, store.MachineEnrolling, 6)

	if m.JoinTokenID == "" {
		t.Fatal("a machine reached enrolling with no record of the credential it was given")
	}
	tok, err := h.st.GetJoinToken(h.ctx, m.JoinTokenID)
	if err != nil {
		t.Fatalf("GetJoinToken: %v", err)
	}
	if tok.MachineID != m.ID || tok.ExpectedName != m.Name {
		t.Fatalf("the token is scoped to machine %q named %q, want %q named %q",
			tok.MachineID, tok.ExpectedName, m.ID, m.Name)
	}
	// Short-lived: a credential nobody is watching must not last an hour.
	if life := tok.ExpiresAt.Sub(tok.CreatedAt); life > h.cfg.Provider.EnrolTimeout+machineTokenGrace+time.Second {
		t.Fatalf("the machine's token lasts %s, want the enrolment window plus a grace", life)
	}
	if life := tok.ExpiresAt.Sub(tok.CreatedAt); life <= h.cfg.Provider.EnrolTimeout {
		t.Fatalf("the machine's token lasts %s, which is less than the %s it is given to enrol in",
			life, h.cfg.Provider.EnrolTimeout)
	}

	// A second pass over a machine already waiting mints nothing.
	before := tok.ID
	h.machinePass(t)
	if got := h.machineByID(t, m.ID); got.JoinTokenID != before {
		t.Fatal("a second pass minted a second credential for a machine that already had one")
	}
}

// A host that joined with a machine's token is linked to it, and that link is
// the only thing that makes deleting the host this controller's business.
func TestTheHostAMachineEnrolledAsIsLinkedToIt(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.machinePass(t)
	m := h.drive(t, h.onlyMachine(t).ID, store.MachineEnrolling, 6)

	h.joinAsMachine(t, m)
	got := h.machineByID(t, m.ID)
	if got.HostID == "" {
		t.Fatal("a machine whose token was redeemed is not linked to the host that redeemed it")
	}
	linked, err := h.st.GetMachineByHost(h.ctx, got.HostID)
	if err != nil {
		t.Fatalf("GetMachineByHost: %v", err)
	}
	if linked.ID != m.ID {
		t.Fatalf("host %s is linked to machine %s, want %s", got.HostID, linked.ID, m.ID)
	}
}

// envOf reads the environment file out of a payload, so that a test asserts on
// the keys the agent will actually read rather than on a blob of bytes.
func envOf(t *testing.T, b provider.Bootstrap) map[string]string {
	t.Helper()
	out := map[string]string{}
	for _, f := range b.Files {
		if f.Path != machineEnvPath {
			continue
		}
		for line := range strings.SplitSeq(string(f.Content), "\n") {
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			key, value, ok := strings.Cut(line, "=")
			if !ok {
				t.Fatalf("the enrolment file has a line that is not an assignment: %q", line)
			}
			out[key] = value
		}
	}
	if len(out) == 0 {
		t.Fatal("the payload wrote no environment file")
	}
	return out
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// Recovery is not a startup path. It runs before demand on every pass, so a
// controller that has just come back is simply having the pass where nothing
// was in memory: the rows say what was being done, the provider says what
// actually happened, and the difference between the two is resolved by asking
// rather than by acting. A separate "recover once at start" path would be code
// that runs on the rarest occasion and is therefore never right.
//
// What this file does is the half of recovery that asks nothing of a provider:
// reservations that expired, phases that have run out of time, and the paced
// ownership sweep. The half that needs a provider call is the step function's,
// because a machine whose create was lost is resolved by exactly the same
// Inspect whether the controller restarted or merely blinked.

// recoverMachineOperations walks the machines with unfinished work and settles
// what can be settled from the rows alone.
//
// A keyset cursor over a bounded batch, recoverHostCleanup's shape: a machine
// stuck behind an unreachable node must not starve the rest, and a fleet with a
// month of history must not read it every thirty seconds.
func (c *Controller) recoverMachineOperations(ctx context.Context, env *machineEnv) {
	rows, err := c.st.PendingMachineWork(ctx, c.machines.cursor, machineSweepBatch)
	if err != nil {
		c.log.Warn("could not read the machines with unfinished work", "error", err)
		return
	}
	for _, m := range rows {
		c.machines.cursor = m.ID
		if live := env.machine(m.ID); live != nil {
			// The pass's own copy is the one every later step reads, so the
			// recovery works on that rather than on a second row that would
			// then disagree with it.
			m = live
		}
		c.recoverMachine(ctx, env, m)
	}
	if len(rows) < machineSweepBatch {
		c.machines.cursor = ""
	}
}

// recoverMachine settles one machine's overdue phase.
//
// Every judgement here is made against a stamp on the row rather than against
// anything held in memory, which is what makes a restart indistinguishable from
// a slow pass.
func (c *Controller) recoverMachine(ctx context.Context, env *machineEnv, m *store.Machine) {
	cfg := env.cfg.Provider
	now := env.now
	switch m.State {
	case store.MachinePlanned:
		// A reservation that never became a create. Nothing was issued -- the
		// identity is written before the call and this row has none -- so
		// failing it costs nothing and frees the ceiling it was holding.
		if m.ResourceID == "" && m.ReservationExpiresAt != nil && now.After(*m.ReservationExpiresAt) {
			c.transitionMachine(ctx, env, m, store.MachineFailed,
				"the create for this machine was never issued, so the reservation was released")
		}
	case store.MachineCreating:
		// provider.create_timeout bounds the whole creation, but only a
		// resource the provider cannot find was ever timed (the ambiguity
		// timeout). A create whose task is lost or whose resource stays locked
		// waited for ever, holding a create slot and a ceiling slot while the
		// VM was billed. An unheard outcome stays the ambiguity path's: that
		// one quarantines rather than fails, and asks a person to look.
		if !m.OpOutcomeUnknown && overdue(m.CreateStartedAt, nil, now, cfg.CreateTimeout) {
			c.failMachine(ctx, env, m, store.MachineErrorProvider, fmt.Sprintf(
				"the provider has not finished creating this machine inside %s. The resource may exist and is "+
					"still being paid for: check the provider's console",
				roundDuration(cfg.CreateTimeout)))
		}
	case store.MachineStarting:
		if !m.OpOutcomeUnknown && overdue(m.CreatedOKAt, nil, now, cfg.CreateTimeout) {
			c.failMachine(ctx, env, m, store.MachineErrorProvider, fmt.Sprintf(
				"the machine was created but did not start inside %s. The resource exists and is still being "+
					"paid for: check the provider's console",
				roundDuration(cfg.CreateTimeout)))
		}
	case store.MachineBootstrapping:
		if overdue(m.StartedAt, m.CreatedOKAt, now, cfg.BootstrapTimeout) {
			c.failMachine(ctx, env, m, store.MachineErrorBootstrap, fmt.Sprintf(
				"the agent was not installed inside %s. The machine is running and is still being paid for: "+
					"check that the template has the zoomies agent installed and the guest agent answering",
				roundDuration(cfg.BootstrapTimeout)))
		}
	case store.MachineEnrolling:
		if overdue(m.BootstrappedAt, m.StartedAt, now, cfg.EnrolTimeout) {
			c.failMachine(ctx, env, m, store.MachineErrorBootstrap, fmt.Sprintf(
				"the agent was installed but no host joined within %s. The machine is running and is still being "+
					"paid for: check that it can reach this controller's external URL",
				roundDuration(cfg.EnrolTimeout)))
		}
	case store.MachineDeleting:
		// A delete that has not confirmed is a machine somebody may still be
		// paying for, so it is never quietly forgotten: past the timeout a
		// person is asked rather than the row being stamped on a guess.
		if overdue(m.DeleteStartedAt, nil, now, cfg.DeleteTimeout) && m.ResourceID != "" {
			_ = c.quarantineMachine(ctx, env, m, fmt.Sprintf(
				"this machine's delete was issued %s ago and %s has not confirmed the resource is gone. "+
					"Nothing further has been attempted: check the provider's console, then either release this "+
					"row -- which forgets the resource without touching it -- or delete the resource by hand",
				roundDuration(now.Sub(deref(m.DeleteStartedAt, now))), providerLabelFor(env.rows, m.ProviderID)))
		}
	}
}

// failMachine records which half complained and gives up on the lifecycle,
// leaving the row and whatever resource is behind it exactly where they are.
func (c *Controller) failMachine(ctx context.Context, env *machineEnv, m *store.Machine, src store.MachineErrorSource, detail string) {
	next := c.Now().Add(machineRetryMax)
	if err := c.st.RecordMachineFailure(ctx, m.ID, src, detail, next); err != nil {
		c.log.Warn("could not record why a machine was given up on", "machine", m.ID, "error", err)
	}
	c.transitionMachine(ctx, env, m, store.MachineFailed, detail)
}

// overdue reports whether the phase that began at from (or at fallback, for a
// provider whose create skipped a phase) has run past d.
//
// A phase with no stamp at all is never overdue: a missing timestamp is a
// question, and answering it with "give up" would fail machines for a column
// nobody wrote.
func overdue(from, fallback *time.Time, now time.Time, d time.Duration) bool {
	if d <= 0 {
		return false
	}
	at := from
	if at == nil {
		at = fallback
	}
	if at == nil {
		return false
	}
	return now.Sub(*at) > d
}

func deref(t *time.Time, or time.Time) time.Time {
	if t == nil {
		return or
	}
	return *t
}

// ---------------------------------------------------------------------------
// The ownership sweep
// ---------------------------------------------------------------------------

// sweepProviders asks each provider, at most every sweep interval, for
// everything it believes it is running, and compares that against the rows.
//
// It is paced rather than run every pass because it is one call per provider
// and the answer changes slowly. What it is for is the two things no machine's
// own step can see: a resource that went away outside Zoomies, and a resource
// wearing this fleet's marks that no row accounts for.
func (c *Controller) sweepProviders(ctx context.Context, env *machineEnv) {
	interval := env.cfg.Provider.SweepInterval
	if interval <= 0 {
		interval = 10 * time.Minute
	}
	for _, row := range env.rows {
		if row.LastSweepAt != nil && env.now.Sub(*row.LastSweepAt) < interval {
			continue
		}
		pr, err := c.providerFor(ctx, row)
		if err != nil {
			c.noteProviderTrouble(row.ID, err, "", env.now)
			continue
		}
		if c.machines.sweeps == nil {
			c.machines.sweeps = map[string]bool{}
		}
		if c.machines.sweeps[row.ID] || len(c.machines.sweeps) >= 4 || env.now.Before(c.machines.sweepRetry[row.ID]) {
			continue
		}
		c.machines.sweeps[row.ID] = true
		// Freeze evidence before the pass can advance any machine rows.
		inventory := *env
		inventory.list = make([]*store.Machine, len(env.list))
		for i, m := range env.list {
			copy := *m
			inventory.list[i] = &copy
		}
		c.machines.calls.Add(1)
		go func() {
			defer c.machines.calls.Done()
			defer func() { c.machines.mu.Lock(); delete(c.machines.sweeps, pr.row.ID); c.machines.mu.Unlock() }()
			c.sweepProvider(ctx, &inventory, pr)
		}()
	}
}

// sweepProvider is one provider's six-way comparison.
//
// The rule for what it may act on is deliberately narrow, because this code is
// one call away from destroying somebody else's machine:
//
//   - a resource wearing our marks with a row is verified, and nothing more;
//   - a resource wearing our name grammar with no row at all is an UNTRACKED
//     resource: reported, listed on the orphan page, and never deleted;
//   - a resource whose marks name another machine is a quarantine, not a
//     delete;
//   - a row whose resource is absent is confirmed gone only when the row was
//     already being deleted, and otherwise says so and drains the host.
//
// Anything live and unexplained is left alone. That is reap's rule about GitHub
// registrations, applied where the mistake costs a running machine.
// sweepTimeout is one provider's sweep budget.
//
// A call apiece, because a sweep is a listing plus a read per candidate rather
// than the two requests stepTimeout budgets for -- Proxmox reads one
// configuration per guest in the range to find its marks. Never longer than the
// interval that paces it: a sweep still running when the next one is due has
// already failed at being paced. Derived from provider.call_timeout, which on
// this path was otherwise never consulted at all.
func (c *Controller) sweepTimeout(env *machineEnv, pr *machineProvider) time.Duration {
	d := env.cfg.Provider.CallTimeout
	if d <= 0 {
		d = 30 * time.Second
	}
	if ask := pr.p.Capabilities().Deadlines.Call; ask > d {
		d = ask
	}
	rows := 0
	for _, m := range env.list {
		if m.ProviderID == pr.row.ID {
			rows++
		}
	}
	// Two spare, so a provider with no rows yet still has room for the listing
	// and for the orphan it is about to find.
	budget := d * time.Duration(rows+2)
	if ceiling := env.cfg.Provider.SweepInterval; ceiling > 0 && budget > ceiling {
		budget = ceiling
	}
	return budget
}

func (c *Controller) sweepProvider(ctx context.Context, env *machineEnv, pr *machineProvider) {
	owner := provider.Owner{ControllerID: c.controllerID(), ProviderID: pr.row.ID}
	// Bounded, because this call is made from inside the pass and everything
	// after it -- every reservation, every drain and every delete -- waits on
	// it. A sweep cut short is retried by the next pass with nothing stamped
	// and nothing acted on, which is much the cheaper of the two failures.
	// Only the call: the store writes below must not inherit a deadline a slow
	// List has already spent.
	listCtx, cancel := context.WithTimeout(ctx, c.sweepTimeout(env, pr))
	seen, err := pr.p.List(listCtx, owner)
	cancel()
	if err != nil {
		c.noteProviderTrouble(pr.row.ID, err, "", env.now)
		c.machines.mu.Lock()
		if c.machines.sweepRetry == nil {
			c.machines.sweepRetry = map[string]time.Time{}
		}
		c.machines.sweepRetry[pr.row.ID] = c.Now().Add(30 * time.Second)
		c.machines.mu.Unlock()
		c.log.Warn("could not list a provider's resources", "provider", pr.row.Name, "error", err)
		return
	}
	// The remote listing must not hold the machine pass lock. Apply it to a
	// fresh local snapshot, since creates and operator actions continued meanwhile.
	c.machines.mu.Lock()
	defer c.machines.mu.Unlock()
	if !c.mayAct() {
		return
	}
	rows, readErr := c.st.ListProviders(ctx)
	if readErr != nil {
		return
	}
	fresh, readErr := c.machineSnapshot(ctx, rows)
	if readErr != nil {
		return
	}
	current := fresh.provider(pr.row.ID)
	if current == nil || !current.UpdatedAt.Equal(pr.row.UpdatedAt) {
		return
	}
	baseline := make(map[string]*store.Machine, len(env.list))
	for _, m := range env.list {
		baseline[m.ID] = m
	}
	unchanged := func(m *store.Machine) bool {
		old := baseline[m.ID]
		return old != nil && old.State == m.State && old.ResourceID == m.ResourceID &&
			old.ResourceZone == m.ResourceZone && old.UpdatedAt.Equal(m.UpdatedAt)
	}
	env = fresh
	// Recorded even when the sweep found nothing: the interval is paced by
	// this stamp, and a sweep that found nothing still happened.
	if err := c.st.SetProviderSwept(ctx, pr.row.ID, env.now); err != nil {
		c.log.Warn("could not record a provider's sweep", "provider", pr.row.ID, "error", err)
	}

	byResource := map[string]*store.Machine{}
	for _, m := range env.list {
		if m.ProviderID == pr.row.ID && m.ResourceID != "" {
			byResource[m.ResourceZone+"/"+m.ResourceID] = m
		}
	}

	var orphans []string
	found := map[string]bool{}
	for _, got := range seen {
		key := got.Ref.Zone + "/" + got.Ref.ID
		m := byResource[key]
		if m == nil && got.Ref.ID == "" {
			m = byResource[got.Ref.Zone+"/"+got.Ref.Name]
			key = got.Ref.Zone + "/" + got.Ref.Name
		}
		if m == nil {
			// No row at all. If it wears our naming grammar it is ours and
			// something lost track of it; if it wears somebody else's marks it
			// is another fleet's. Neither is ever deleted from here.
			if store.IsMachineName(got.Ref.Name) {
				orphans = append(orphans, got.Ref.Name)
			}
			continue
		}
		found[key] = true
		if !unchanged(m) {
			continue
		}
		if why := c.ownershipComplaint(m, got); why != "" {
			if m.State != store.MachineQuarantined {
				_ = c.quarantineMachine(ctx, env, m, why)
			}
			continue
		}
		if err := c.st.SetMachineOwnershipVerified(ctx, m.ID, env.now); err != nil {
			c.log.Warn("could not record a machine's ownership", "machine", m.ID, "error", err)
		}
	}
	slices.Sort(orphans)
	c.noteOrphans(pr.row.ID, orphans)

	for key, m := range byResource {
		if found[key] || !unchanged(m) {
			continue
		}
		c.sweepAbsent(ctx, env, pr, m)
	}
}

// sweepAbsent decides what a resource's absence means for the row that names
// it.
//
// Absence is only ever acted on for a machine that was already on its way out.
// For one the fleet believes is working it is reported and its host drained,
// because a machine that vanished under us has taken whatever it was running
// with it -- and there is nothing left to delete.
func (c *Controller) sweepAbsent(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) {
	switch m.State {
	case store.MachineDeleting, store.MachineFailed:
		if _, err := c.st.ConfirmMachineDeleted(ctx, m.ID, env.now); err != nil {
			c.log.Warn("could not confirm a machine's resource is gone", "machine", m.ID, "error", err)
			return
		}
		c.transitionMachine(ctx, env, m, store.MachineDeleted,
			fmt.Sprintf("%s no longer has this machine's resource", pr.row.Name))
		if m.HostID != "" {
			if err := c.DeleteHost(ctx, m.HostID); err != nil && !errors.Is(err, store.ErrNotFound) {
				c.log.Warn("a machine's resource is gone but its host row could not be removed",
					"machine", m.ID, "host", m.HostID, "error", err)
			}
		}
	case store.MachineCreating, store.MachinePlanned:
		// The create's own ambiguity path owns this: a machine that is being
		// built and cannot be seen yet is not a machine that has gone.
	case store.MachineQuarantined, store.MachineDeleted:
	default:
		// ready, enrolling, starting, bootstrapping, draining: the resource
		// went away outside Zoomies.
		detail := fmt.Sprintf("%s no longer has this machine's resource, so it was destroyed outside Zoomies. "+
			"There is nothing left to delete; anything it was running has been lost", pr.row.Name)
		if m.HostID != "" {
			if err := c.st.SetHostCordoned(ctx, m.HostID, true); err != nil {
				c.log.Warn("could not cordon a vanished machine's host", "machine", m.ID, "error", err)
			}
		}
		c.failMachine(ctx, env, m, store.MachineErrorProvider, detail)
		c.log.Warn("a machine's resource vanished outside Zoomies", "machine", m.ID,
			"name", m.Name, "provider", pr.row.Name)
	}
}

// ---------------------------------------------------------------------------
// Enrolment, which is an observation of our own rows
// ---------------------------------------------------------------------------

// stepEnrolling links a machine to the host that redeemed its token.
//
// The link is the only thing that grants this controller deletion authority
// over a host, and the only writer of it is a token this machine minted. There
// is deliberately no route, verb or label that attaches a machine to a host an
// operator already had: a host that could be labelled into deletion authority
// is a host anyone with the operator role can have destroyed.
func (c *Controller) stepEnrolling(ctx context.Context, env *machineEnv, m *store.Machine) {
	if m.HostID != "" {
		c.transitionMachine(ctx, env, m, store.MachineReady, "the agent joined and this machine is serving runners")
		return
	}
	if m.JoinTokenID == "" {
		// Nothing was minted, so nothing can have joined. Back to bootstrapping
		// is not a transition the state machine allows, so this waits for the
		// enrolment timeout to say so in words.
		return
	}
	tok, err := c.st.GetJoinToken(ctx, m.JoinTokenID)
	if err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("could not read a machine's join token", "machine", m.ID, "error", err)
		}
		return
	}
	if tok.UsedAt == nil || tok.UsedByID == "" {
		return
	}
	if tok.MachineID != "" && tok.MachineID != m.ID {
		_ = c.quarantineMachine(ctx, env, m, fmt.Sprintf(
			"this machine's join token was spent by machine %s rather than by this one. Nothing has been deleted: "+
				"a credential that enrolled something else is a copied guest, and which machine owns host %s has to be "+
				"decided by a person", tok.MachineID, tok.UsedByID))
		return
	}
	if err := c.st.LinkMachineHost(ctx, m.ID, tok.UsedByID, tok.ID, env.now); err != nil {
		if errors.Is(err, store.ErrConflict) {
			_ = c.quarantineMachine(ctx, env, m, fmt.Sprintf(
				"this machine's token enrolled host %s, which another machine already claims. Nothing has been "+
					"deleted; a person has to decide which machine that host belongs to", tok.UsedByID))
			return
		}
		c.log.Warn("could not link a machine to the host it enrolled as", "machine", m.ID, "error", err)
		return
	}
	m.HostID = tok.UsedByID
	c.transitionMachine(ctx, env, m, store.MachineReady, "the agent joined and this machine is serving runners")
	c.log.Info("a machine became a host", "machine", m.ID, "name", m.Name, "host", m.HostID)
	// A new host changes where runners can be placed, and the scheduling pass
	// is the half that places them.
	c.Nudge()
}

package controller

import (
	"github.com/eyupio/zoomies/internal/config"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// A timeout says nothing about whether the work happened. Treating one as a
// failure is how a fleet ends up with two machines and one row -- and the row
// names only one of them, so the other is never drained, never deleted and
// never anything but a line on the bill.
func TestATimeoutIsNotEvidenceThatCreationFailed(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetAmbiguousAfterWork("create")

	h.machinePass(t)
	m := h.onlyMachine(t)
	if !m.OpOutcomeUnknown {
		t.Fatal("a create whose answer was never heard was not recorded as unknown; the next pass would retry it")
	}

	// The connection comes back. Every pass from here resolves by asking.
	h.fake.ClearFailures()
	for range 3 {
		h.pastBackoff(t, m.ID)
		h.machinePass(t)
	}
	if got := h.callsTo("create"); got != 1 {
		t.Fatalf("the provider was asked to create %d times after one ambiguous answer, want once", got)
	}
	if got := len(h.fake.Machines()); got != 1 {
		t.Fatalf("the provider holds %d machines after one ambiguous create, want 1", got)
	}
	if got := h.machineByID(t, m.ID); got.OwnershipVerifiedAt == nil {
		t.Fatal("the machine was never adopted: an ambiguous create is resolved by finding what was made")
	}
	h.assertOneResourcePerMachine(t)
}

// An ambiguous answer with nothing behind it is the same answer as one with a
// machine behind it. The difference is only knowable by looking, and looking
// twice before reusing the identity is what stops a provider that is slow to
// admit a resource exists from being asked for a second one.
func TestAnAmbiguousCreateIsResolvedByLookingNotByCreating(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetAmbiguousBeforeWork("create")

	h.machinePass(t)
	m := h.onlyMachine(t)
	h.fake.ClearFailures()

	// The first look finds nothing and creates nothing.
	h.pastBackoff(t, m.ID)
	h.machinePass(t)
	if got := h.callsTo("create"); got != 1 {
		t.Fatalf("the provider was asked to create %d times after one look, want the first one only", got)
	}

	// The second, a call timeout later, reuses the identity rather than
	// allocating a new one.
	h.pastBackoff(t, m.ID)
	h.machinePass(t)
	if got := h.callsTo("allocate"); got != 1 {
		t.Fatalf("a second identity was allocated (%d allocates); a retry of one machine reuses the identity it already has", got)
	}
	h.assertOneResourcePerMachine(t)
}

// Past the ambiguity timeout the honest answer is that nobody knows, and the
// honest action is to ask a person. Retrying for ever would leave a machine
// that may exist being paid for, with nothing on any page to say so.
func TestAnUnresolvedAmbiguityIsQuarantinedRatherThanRetried(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetAmbiguousBeforeWork("create")

	h.machinePass(t)
	m := h.onlyMachine(t)
	h.fake.ClearFailures()
	h.advance(h.cfg.Provider.AmbiguityTimeout + time.Minute)

	h.machinePass(t)
	got := h.machineByID(t, m.ID)
	if got.State != store.MachineQuarantined {
		t.Fatalf("an ambiguity nobody could resolve left the machine %s, want quarantined", got.State)
	}
	if !slices.Contains(h.problemCodes(), "provider.ownership_unverified") {
		t.Fatalf("a quarantined machine raised %v, want provider.ownership_unverified", h.problemCodes())
	}
}

// provider.create_timeout is documented as bounding the whole asynchronous
// creation of a machine, and the ambiguity timeout only covers a resource the
// provider cannot find. A create whose task never finishes -- a PVE task lost
// with its node, a stale clone lock -- was therefore waited on for ever, and
// because a machine that is still creating counts against the in-flight create
// limit, one such machine stopped the provider buying anything.
func TestAMachineStuckCreatingIsFailedAtTheCreateTimeoutAndFreesItsSlot(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetAsync("create", 1<<30)

	h.machinePass(t)
	m := h.onlyMachine(t)
	if m.State != store.MachineCreating {
		t.Fatalf("machine is %s after the first pass, want creating", m.State)
	}

	// Inside the timeout it is simply a slow create, and is left alone.
	h.advance(h.cfg.Provider.CreateTimeout / 2)
	h.machinePass(t)
	if got := h.machineByID(t, m.ID); got.State != store.MachineCreating {
		t.Fatalf("a create inside its timeout was %s, want it left creating", got.State)
	}

	h.advance(h.cfg.Provider.CreateTimeout)
	h.machinePass(t)
	got := h.machineByID(t, m.ID)
	if got.State != store.MachineFailed {
		t.Fatalf("a create that ran past provider.create_timeout is %s, want failed", got.State)
	}
	if got.State.Pending() {
		t.Fatal("a failed machine still counts against the in-flight create limit")
	}
	if !strings.Contains(got.Message, "still being paid for") {
		t.Fatalf("the failure does not say the resource may still be billed: %q", got.Message)
	}
	if h.callsTo("delete") != 0 {
		t.Fatal("giving up on a create deleted a resource that may be somebody's work")
	}
	if !slices.Contains(h.problemCodes(), "provider.machine_failed") {
		t.Fatalf("a failed machine raised %v, want provider.machine_failed", h.problemCodes())
	}
}

// The starting phase is bounded by the same setting, counted from when the
// resource was created, for a provider that cannot be powered on by us.
func TestAMachineStuckStartingIsFailedAtTheCreateTimeout(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	if err := h.st.SetMachineResource(h.ctx, m.ID, "zone-a", "9001", "ours", h.c.controllerID()); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	for _, to := range []store.MachineState{store.MachineCreating, store.MachineStarting} {
		if _, err := h.st.TransitionMachine(h.ctx, m.ID, to, ""); err != nil {
			t.Fatalf("TransitionMachine to %s: %v", to, err)
		}
	}

	h.advance(h.cfg.Provider.CreateTimeout + time.Minute)
	h.machinePass(t)
	if got := h.machineByID(t, m.ID); got.State != store.MachineFailed {
		t.Fatalf("a machine starting for longer than provider.create_timeout is %s, want failed", got.State)
	}
}

// A machine wearing our naming and somebody else's ownership marks is another
// fleet's. Deleting it would destroy a machine that is running somebody's work,
// so it is quarantined and left exactly where it is.
func TestAVMWearingOurNameWithAnotherOwnerIsQuarantinedNotDeleted(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	// A machine of another fleet's, wearing the naming this one mints: a
	// recycled identifier, which is the realistic accident.
	m := &store.Machine{ProviderID: row.ID, State: store.MachineCreating}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	h.fake.PlantForeign(m.Name)
	theirs := h.fake.Machines()[0]
	if err := h.st.SetMachineResource(h.ctx, m.ID, theirs.Ref.Zone, theirs.Ref.ID,
		"ours", h.c.controllerID()); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}

	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineQuarantined {
		t.Fatalf("a resource owned by another fleet left our machine %s, want quarantined", got.State)
	}
	if got.OwnershipError == "" {
		t.Fatal("a quarantined machine says nothing about what disagreed; the whole entry is for a person to read")
	}
	if h.callsTo("delete") != 0 {
		t.Fatal("a resource this fleet could not prove it owns was deleted")
	}
}

// A resource wearing this fleet's naming with no row at all is reported and
// never removed. One left over from a database that was lost is the operator's
// to remove; one still doing work belongs to something else, and a sweep cannot
// tell the two apart.
func TestAnUntrackedResourceIsReportedAndNeverDeleted(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	name := store.NewMachineName("mach_orphaned")
	h.fake.PlantOrphan(name, provider.Owner{ControllerID: h.c.controllerID(), ProviderID: row.ID})

	h.machinePass(t)

	orphans := h.c.ProviderOrphans()[row.ID]
	if !slices.Contains(orphans, name) {
		t.Fatalf("the sweep reported orphans %v, want %s among them", orphans, name)
	}
	if !slices.Contains(h.problemCodes(), "provider.orphan_found") {
		t.Fatalf("an untracked resource raised %v, want provider.orphan_found", h.problemCodes())
	}
	if h.callsTo("delete") != 0 {
		t.Fatal("an untracked resource was deleted; it may be somebody else's and it may be running")
	}
	for _, got := range h.fake.Machines() {
		if got.Ref.Name == name {
			return
		}
	}
	t.Fatal("the untracked resource is gone from the provider, and nothing here should have removed it")
}

// A resource that went away outside Zoomies is not a delete that worked: there
// is nothing left to delete, whatever was running on it has been lost, and the
// fleet has to say so rather than quietly recording a tidy removal.
func TestAMachineThatVanishedOutsideZoomiesSaysSo(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)

	h.fake.Vanish(m.ResourceID)
	h.advance(h.cfg.Provider.SweepInterval + time.Minute)
	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineFailed {
		t.Fatalf("a machine destroyed outside Zoomies is %s, want failed", got.State)
	}
	if got.DeletedAt != nil {
		t.Fatal("a machine nobody deleted was recorded as deleted; that stamp is what frees the budget and it has to mean a delete")
	}
	if !slices.Contains(h.problemCodes(), "provider.machine_failed") {
		t.Fatalf("a vanished machine raised %v, want provider.machine_failed", h.problemCodes())
	}
}

// A sweep's answer goes stale. A delete needs a fresh look, in the pass that
// deletes, because an observation from ten minutes ago is a statement about a
// machine that may have been rebuilt since.
func TestADeleteAlwaysInspectsAfresh(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)

	before := h.callsTo("inspect")
	h.beginDrainFor(t, m)
	h.drive(t, m.ID, store.MachineDeleted, 8)

	if h.callsTo("inspect") <= before {
		t.Fatal("a machine was deleted without a fresh inspect; a sweep's answer is not evidence for a delete")
	}
	// And the view says the same thing to an operator: a machine whose last
	// confirmation has gone stale is not offered a delete button.
	stale := &store.Machine{ID: "mach_x", ResourceID: "143",
		OwnershipVerifiedAt: ptrTime(h.c.Now().Add(-2 * observationMaxAge))}
	if ok, why := machineSafeToDelete(stale, h.c.Now()); ok {
		t.Fatalf("a machine last verified %s ago was offered as safe to delete (%q)", 2*observationMaxAge, why)
	}
}

// A reservation that never became a create is released rather than left
// holding a place in the ceiling for ever. Nothing was created -- the identity
// is written before the call and this row has none -- so nothing is at risk.
func TestAReservationThatNeverBecameACreateIsReleased(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	expires := h.c.Now().Add(-time.Minute)
	m := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned, ReservationExpiresAt: &expires}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}

	h.machinePass(t)
	got := h.machineByID(t, m.ID)
	if got.State != store.MachineFailed {
		t.Fatalf("an expired reservation is %s, want failed so it stops holding a place in the ceiling", got.State)
	}
}

// A repeated observation changes nothing. Deliveries and sweeps are
// at-least-once, so a pass that saw the same thing twice must write the same
// row twice rather than moving the machine on twice.
func TestARepeatedProviderObservationChangesNothing(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)

	before := h.machineByID(t, m.ID)
	for range 3 {
		h.advance(h.cfg.Provider.SweepInterval + time.Minute)
		h.machinePass(t)
	}
	after := h.machineByID(t, m.ID)
	if after.State != before.State {
		t.Fatalf("three sweeps over an unchanged machine moved it from %s to %s", before.State, after.State)
	}
	if !after.ReadyAt.Equal(*before.ReadyAt) {
		t.Fatal("a repeated observation rewrote when the machine became ready; the timeline is first-write-wins")
	}
	h.assertOneResourcePerMachine(t)
}

// A host an operator enrolled by hand never becomes a machine this controller
// may destroy. Deletion authority is the existence of a machine row this
// controller wrote before the resource existed, and there is no route that
// attaches one to a host somebody already had.
func TestAnImportedHostNeverAcquiresDeletionAuthority(t *testing.T) {
	h := newHarness(t)
	h.enableProviders(t)
	host := h.host("imported-1")

	if _, err := h.st.GetMachineByHost(h.ctx, host.ID); err == nil {
		t.Fatal("a host nobody rented has a machine row, which is the only thing that grants a delete")
	}
	// Labelling it cannot change that: labels are the operator's and are
	// writable through the API.
	host.Labels = store.StringMap{"zoomies.machine": "mach_pretend"}
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	if _, err := h.st.GetMachineByHost(h.ctx, host.ID); err == nil {
		t.Fatal("a label gave a host a machine row; a host that can be labelled into deletion authority can be destroyed by anyone with the operator role")
	}
}

// A credential that enrolled somebody else is a copied guest.
//
// The machine minted a token for itself, and a different machine spent it. That
// can only happen if the guest was cloned after it was given its credential, and
// the answer is emphatically not to take the host: two machines now claim it,
// and which one owns it is a question for a person. The alternative -- linking
// it anyway -- would hand this machine deletion authority over a host that
// belongs to another.
func TestATokenSpentBySomebodyElseQuarantinesTheMachineRatherThanTakingTheHost(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	m := &store.Machine{ProviderID: row.ID, State: store.MachineEnrolling}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	// The token belongs to another machine and was legitimately redeemed by the
	// host it names. What is wrong is this row pointing at it -- a restored
	// database, or a row edited by hand -- and the scope check cannot catch
	// that, because the redemption itself was correct.
	tok, _, err := h.c.Auth().CreateScopedJoinToken(h.ctx, auth.JoinScope{
		TTL: time.Hour, Capacity: 1, MachineID: "mach_somebodyelse", ExpectedName: "zoomies-mach-stranger",
	})
	if err != nil {
		t.Fatalf("CreateScopedJoinToken: %v", err)
	}
	host := h.host("zoomies-mach-stranger")
	if _, err := h.st.RedeemJoinToken(h.ctx, tok.TokenHash, store.JoinClaim{HostID: host.ID, Name: host.Name}, h.c.Now()); err != nil {
		t.Fatalf("RedeemJoinToken: %v", err)
	}
	if err := h.st.SetMachineJoinToken(h.ctx, m.ID, tok.ID); err != nil {
		t.Fatalf("SetMachineJoinToken: %v", err)
	}

	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineQuarantined {
		t.Fatalf("state = %s, want quarantined: a token spent by another machine is a copied guest", got.State)
	}
	if got.HostID != "" {
		t.Fatalf("the machine took host %s, which another machine's token enrolled", got.HostID)
	}
	if got.OwnershipError == "" {
		t.Fatal("the quarantine says nothing about what disagreed, and the entry exists for a person to read")
	}
}

// A machine that has minted a credential and not yet had it spent is simply
// waiting. It is neither ready nor broken, and a pass that moved it either way
// would be guessing.
func TestAMachineWhoseCredentialIsUnspentIsStillWaiting(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	m := &store.Machine{ProviderID: row.ID, State: store.MachineEnrolling}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	tok, _, err := h.c.Auth().CreateScopedJoinToken(h.ctx, auth.JoinScope{
		TTL: time.Hour, Capacity: 1, MachineID: m.ID, ExpectedName: m.Name,
	})
	if err != nil {
		t.Fatalf("CreateScopedJoinToken: %v", err)
	}
	if err := h.st.SetMachineJoinToken(h.ctx, m.ID, tok.ID); err != nil {
		t.Fatalf("SetMachineJoinToken: %v", err)
	}

	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineEnrolling {
		t.Fatalf("state = %s, want it still enrolling: nothing has happened yet", got.State)
	}
	if got.HostID != "" {
		t.Fatal("a machine whose token nobody redeemed was linked to a host anyway")
	}
}

// A machine in enrolling with no credential at all waits for its timeout to say
// so, rather than being walked backwards. Nothing returns to bootstrapping: the
// state machine has no such edge, because a machine that may already have been
// handed a credential must not be handed a second one.
func TestAMachineWithNoCredentialIsNotWalkedBackwards(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	m := &store.Machine{ProviderID: row.ID, State: store.MachineEnrolling}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}

	h.machinePass(t)

	if got := h.machineByID(t, m.ID); got.State != store.MachineEnrolling {
		t.Fatalf("state = %s, want it left alone until its enrolment timeout speaks", got.State)
	}
}

// A resource that went away underneath a working machine is not a deletion this
// fleet can tidy up: there is nothing left to delete, and whatever the host was
// running is gone. Its host is cordoned so no more work is placed on something
// that no longer exists, and the machine is failed with the provider's name in
// the sentence rather than silently removed.
func TestAMachineDestroyedOutsideZoomiesCordonsItsHostAndSaysSo(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	m := &store.Machine{ProviderID: row.ID, State: store.MachineReady}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	host := h.host(m.Name)
	if err := h.st.SetMachineResource(h.ctx, m.ID, "zone-a", "9001", "ours", h.c.controllerID()); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	if err := h.st.LinkMachineHost(h.ctx, m.ID, host.ID, "", h.c.Now()); err != nil {
		t.Fatalf("LinkMachineHost: %v", err)
	}
	// The provider has never heard of it: somebody removed it by hand.
	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineFailed {
		t.Fatalf("state = %s, want failed: the resource is gone and there is nothing to delete", got.State)
	}
	if got.ProviderError == "" {
		t.Fatal("a machine that vanished says nothing about it; the message is the only record")
	}
	gotHost, err := h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !gotHost.Cordoned {
		t.Fatal("the host of a machine that no longer exists is still taking work")
	}
}

// A provider that answers its listing slowly cannot hold up the fleet.
//
// The sweep runs inside the pass, before demand, so everything behind it waits:
// every reservation, every drain and every delete. Proxmox reads one
// configuration per guest to find its marks, so a cluster whose API has wedged
// stalls once per candidate rather than once -- which is how a sweep nobody
// bounded blocks a pass for many minutes and leaves a drained machine powered
// on and billed. A sweep cut short costs nothing: the next pass retries it with
// nothing stamped and nothing acted on.
func TestASlowSweepIsCutShortRatherThanHoldingUpThePass(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	// The interval is the ceiling on the budget, so it is the cheap way to
	// make this test's bound small; the provider's own asking price would
	// otherwise set it.
	h.c.UpdateConfig(func(c *config.Config) {
		c.Provider.CallTimeout = 20 * time.Millisecond
		c.Provider.SweepInterval = 200 * time.Millisecond
	})
	h.cfg = h.c.Config()
	h.fake.SetDelay("list", 30*time.Second)

	done := make(chan struct{})
	go func() {
		defer close(done)
		h.machinePass(t)
	}()
	select {
	case <-done:
	case <-time.After(20 * time.Second):
		t.Fatal("a pass was still waiting on a provider's listing; the sweep is not bounded")
	}

	// The sweep did not finish, so it is not recorded as having happened: the
	// interval is paced by that stamp, and a sweep cut short has to be tried
	// again rather than counted.
	fresh, err := h.st.GetProvider(h.ctx, row.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if fresh.LastSweepAt != nil {
		t.Errorf("a sweep that timed out was recorded as done at %v", fresh.LastSweepAt)
	}
}

// The budget is a call apiece, because a sweep is a listing plus a read per
// candidate -- and never longer than the interval that paces it, since a sweep
// still running when the next is due has already failed at being paced.
func TestTheSweepBudgetGrowsWithTheMachinesItHasToReadAndStopsAtTheInterval(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	h.c.UpdateConfig(func(c *config.Config) {
		c.Provider.CallTimeout = time.Second
		c.Provider.SweepInterval = time.Hour
	})
	h.cfg = h.c.Config()
	pr, err := h.c.providerFor(h.ctx, row)
	if err != nil {
		t.Fatalf("building the provider: %v", err)
	}
	// A provider may ask for longer than the operator's timeout and never for
	// less supervision, so the per-call figure is whichever is larger. Read it
	// rather than assumed, so this test says the rule instead of a number.
	call := h.c.Config().Provider.CallTimeout
	if ask := pr.p.Capabilities().Deadlines.Call; ask > call {
		call = ask
	}

	env := &machineEnv{cfg: h.c.Config()}
	if got := h.c.sweepTimeout(env, pr); got != 2*call {
		t.Errorf("with no machines the budget is %s, want %s: room for the listing and one orphan", got, 2*call)
	}
	for range 4 {
		env.list = append(env.list, &store.Machine{ProviderID: row.ID})
	}
	// Another provider's machines are not this sweep's to read.
	env.list = append(env.list, &store.Machine{ProviderID: "prv_elsewhere"})
	if got := h.c.sweepTimeout(env, pr); got != 6*call {
		t.Errorf("with four machines the budget is %s, want %s: a call apiece plus two", got, 6*call)
	}

	env.cfg.Provider.SweepInterval = call / 2
	if got := h.c.sweepTimeout(env, pr); got != call/2 {
		t.Errorf("the budget is %s, want it capped at the interval that paces it", got)
	}
}

// A quarantined machine's host stops taking work.
//
// The scheduler's snapshot carries hosts and never machines, so it cannot work
// this out for itself: without the cordon a machine can be recorded as one the
// fleet cannot prove it owns while its host goes on accepting runners. Whoever
// the resource really belongs to may power it off at any moment, and every
// runner placed after the quarantine is a job lost.
//
// Driven through quarantineMachine rather than through a sweep because the
// store will not let a test repoint a machine that already has a resource --
// "a machine has one resource for its whole life" -- and a ready machine, which
// is the only kind with a host, always has one.
func TestQuarantiningAMachineStopsItsHostTakingNewWork(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)
	if m.HostID == "" {
		t.Fatal("a ready machine has no host; the fixture is not what this test needs")
	}
	host, err := h.st.GetHost(h.ctx, m.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.Cordoned {
		t.Fatal("the host was already cordoned before the quarantine")
	}

	if err := h.c.quarantineMachine(h.ctx, &machineEnv{now: h.c.Now()}, m,
		"that resource's ownership record says another machine"); err != nil {
		t.Fatalf("quarantineMachine: %v", err)
	}

	if got := h.machineByID(t, m.ID); got.State != store.MachineQuarantined {
		t.Fatalf("the machine is %s, want quarantined", got.State)
	}
	fresh, err := h.st.GetHost(h.ctx, m.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if !fresh.Cordoned {
		t.Error("a quarantined machine's host is still taking new runners")
	}
	if h.callsTo("delete") != 0 {
		t.Error("a resource this fleet could not prove it owns was deleted")
	}
}

// And a quarantine raised before there is a host cordons nothing, because there
// is nothing to cordon -- every pre-enrolment quarantine is in that position.
func TestQuarantiningAMachineWithNoHostYetCordonsNothing(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := &store.Machine{ProviderID: row.ID, State: store.MachineCreating}
	if err := h.st.CreateMachine(h.ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	h.fake.PlantForeign(m.Name)
	theirs := h.fake.Machines()[0]
	if err := h.st.SetMachineResource(h.ctx, m.ID, theirs.Ref.Zone, theirs.Ref.ID,
		"ours", h.c.controllerID()); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}

	h.machinePass(t)

	if got := h.machineByID(t, m.ID); got.State != store.MachineQuarantined {
		t.Fatalf("the machine is %s, want quarantined", got.State)
	}
	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	for _, host := range hosts {
		if host.Cordoned {
			t.Errorf("host %s was cordoned by a quarantine that had no host of its own", host.ID)
		}
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The machine loop is the half of the fleet that spends money.
//
// Everything here follows one rule, and it is worth stating before any of the
// code: every arrow between two machine states is an OBSERVATION, never an
// intent. A create whose answer never arrived is resolved by asking the
// provider about the identity the row already carries, never by creating a
// second machine; a delete is complete when an inspect cannot find the
// resource, never when the delete call returned 200. A controller that guessed
// in either direction would leave somebody paying for a machine nothing in the
// fleet knows about, which is the failure this whole design is arranged around.
//
// The loop is its own spawn rather than a step of Reconcile. reconcileMu is
// held for a whole scheduling pass and a clone takes minutes, so a machine step
// inside it would stop the fleet placing runners for as long as a hypervisor
// felt like taking -- the argument that already moved capacity-demand delivery
// out of the pass.

const (
	// machineFirstPass is how long after start the first machine pass runs.
	// Late enough that agents have had a chance to say they are back -- a pass
	// that ran the instant the process came up would see an empty fleet and
	// buy machines for work the hosts it has were about to take.
	machineFirstPass = 15 * time.Second
	// machineRetryBase and machineRetryMax bound one machine's own backoff.
	machineRetryBase = 20 * time.Second
	machineRetryMax  = 15 * time.Minute
	// machineMaxAttempts is how many times a step is tried before the machine
	// is failed and left visible. Failing it is not tidying up: the row stays,
	// with its reason, because the resource behind it may still exist.
	machineMaxAttempts = 5
	// observationMaxAge is how old an observation may be and still be evidence
	// for a delete. A minute: long enough that a sweep and a delete in the same
	// pass agree, short enough that nothing acts on what was true at breakfast.
	observationMaxAge = 60 * time.Second
	// machineSweepBatch bounds one recovery pass, so a machine stuck behind an
	// unreachable node cannot starve the rest.
	machineSweepBatch = 100
	// machineClaimMargin is how much longer a claim lasts than the call it
	// covers, so that a claim never expires underneath the request it is there
	// to make exclusive.
	machineClaimMargin = 30 * time.Second
	// breakerThreshold is how many machines may fail before ready in a row
	// before the provider is stood down. Three is enough to tell a bad template
	// from an unlucky one, and few enough that the fourth is not paid for.
	breakerThreshold = 3
	breakerBase      = time.Minute
	breakerMax       = 15 * time.Minute
)

// machineRuntime is everything the machine loop owns.
type machineRuntime struct {
	// mu makes a machine pass mutually exclusive with itself, exactly as
	// reconcileMu does for the scheduling pass. It is a separate mutex because
	// the two passes have nothing to say to each other and a machine step must
	// never be able to hold up a scheduling one.
	mu                 sync.Mutex
	sweeps             map[string]bool
	sweepRetry         map[string]time.Time
	operationCount     int
	providerOperations map[string]int
	// calls tracks the provider calls a pass issued, which outlive the pass:
	// Stop waits on it beside deliveries, because exiting under a create
	// leaves a machine whose outcome nobody recorded.
	calls  sync.WaitGroup
	nudges chan struct{}
	// cursor is the recovery sweep's keyset position, owned by the pass that
	// mu serialises.
	cursor string

	cacheMu sync.Mutex
	cache   map[string]*builtProvider

	// noteMu guards what the problems drawer reads about each provider: the
	// last failure and the untracked resources the last sweep found. Both are
	// in memory, like blocked and runnerGroups, because both are re-learnt by
	// the next pass -- and neither is a fact about the fleet worth a row.
	noteMu  sync.Mutex
	trouble map[string]providerTrouble
	orphans map[string][]string
}

// providerTrouble is the last failure a provider gave us, kept for the
// sentence the problems drawer shows.
type providerTrouble struct {
	Kind    provider.FailureKind
	Detail  string
	Remedy  string
	At      time.Time
	Machine string
}

// builtProvider is one configuration row's live client, cached until the row
// changes. updated_at is the whole cache key beyond the id: an operator who
// rotates a credential expects the next pass to use it, and nothing else in
// the row moves without moving that column.
type builtProvider struct {
	p         provider.Provider
	updatedAt time.Time
	// tunnel is the private connection the client dials through, or nil for
	// a provider reached directly. It is closed when the row it was built
	// for changes, because the new row may point somewhere else.
	tunnel *privateDialer
}

func newMachineRuntime() *machineRuntime {
	return &machineRuntime{
		nudges:  make(chan struct{}, 1),
		cache:   map[string]*builtProvider{},
		trouble: map[string]providerTrouble{},
		orphans: map[string][]string{},
	}
}

// NudgeMachines wakes the machine loop immediately. Like Nudge it never blocks
// and never queues: the channel holds one token, so a burst of changes costs
// one pass.
func (c *Controller) NudgeMachines() {
	select {
	case c.machines.nudges <- struct{}{}:
	default:
	}
}

// machineLoop runs a pass on the configured interval, on every nudge, and
// whenever the settings change.
func (c *Controller) machineLoop(ctx context.Context) {
	timer := time.NewTimer(machineFirstPass)
	defer timer.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
		case <-c.machines.nudges:
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
		case <-c.machineSettingsChanged:
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
		}
		if err := c.ReconcileMachines(ctx); err != nil && ctx.Err() == nil {
			// Logged rather than propagated: a transient database or provider
			// error must not stop the loop, and the machines it did not reach
			// this pass are reached by the next one.
			c.log.Error("a machine pass failed", "error", err)
		}
		timer.Reset(c.machineInterval())
	}
}

// machineInterval is how often machines are reconciled, with a floor so that a
// misconfigured zero does not spin the loop.
func (c *Controller) machineInterval() time.Duration {
	if d := c.cfg().Provider.Interval; d > 0 {
		return d
	}
	return 30 * time.Second
}

// ReconcileMachines runs exactly one machine pass. It is exported so that
// tests and the API can force a pass and know it has finished, which a nudge
// deliberately cannot promise.
//
// The order is the design. Recovery runs before demand on every pass, so a
// restart is simply the pass where nothing was in memory and there is no
// separate startup path to get wrong. Ownership is swept before anything is
// decided, so a resource that vanished under us is known about before the
// fleet works out whether to buy another. And nothing is created until every
// machine already on the way has been counted.
func (c *Controller) ReconcileMachines(ctx context.Context) error {
	c.machines.mu.Lock()
	defer c.machines.mu.Unlock()

	// Provider and runner mutations share the same authority boundary.
	if !c.mayAct() {
		return nil
	}
	// Off is off, whoever asked. The loop is not started when providers are
	// switched off, and a pass forced by a test or an API call must refuse for
	// the same reason: renting a machine spends money, and nothing should
	// start doing that because a release added the ability to.
	if !c.cfg().Provider.Enabled {
		return nil
	}

	rows, err := c.st.ListProviders(ctx)
	if err != nil {
		return fmt.Errorf("listing providers: %w", err)
	}
	// The demo fixture's provider has no hypervisor behind it, and its address
	// is a name that does not resolve. Left in, an instance seeded for a demo
	// and then switched on would spend every pass dialling it, fill the
	// problems drawer with a provider nobody configured, and count its two
	// fictional machines against the fleet's ceiling -- the same reason the
	// credential prober and the registration reaper skip the fixtures they
	// would otherwise reach out on behalf of.
	//
	// Filtered here rather than at each step so that recovery, the sweep, the
	// plan and the machine loop all agree about which providers exist: a
	// fixture that were visible to one of them and not the others is worse
	// than one visible to all.
	providers := rows[:0:0]
	for _, p := range rows {
		if !IsDemoID(p.ID) {
			providers = append(providers, p)
		}
	}
	if len(providers) == 0 {
		return nil
	}

	env, err := c.machineSnapshot(ctx, providers)
	if err != nil {
		return err
	}

	c.recoverMachineOperations(ctx, env)
	c.sweepProviders(ctx, env)
	c.applyMachinePlan(ctx, env, DecideMachines(env.demand()))
	c.stepMachines(ctx, env)
	c.publishDerived(ctx)
	return nil
}

// machineEnv is one pass's view of the world, gathered once.
type machineEnv struct {
	now    time.Time
	holder string
	cfg    *config.Config
	// snap and plan are the scheduler's own snapshot and decision over the
	// same rows. The machine demand calculation reads them rather than forming
	// a second opinion about which pool wants what.
	snap  scheduler.Snapshot
	plan  scheduler.Plan
	rows  []*store.Provider
	byID  map[string]*store.Provider
	list  []*store.Machine
	hosts map[string]*store.Host
	// live is how many runners each host is actually running, which is what
	// says whether a machine may be drained and whether a drain has finished.
	live map[string]int
}

func (e *machineEnv) provider(id string) *store.Provider { return e.byID[id] }

// demand renders the snapshot the pure calculation reads.
func (e *machineEnv) demand() MachineSnapshot {
	return MachineSnapshot{
		Now:       e.now,
		Plan:      e.plan,
		Pools:     e.snap.Pools,
		Hosts:     e.snap.Hosts,
		Runners:   e.snap.Runners,
		Jobs:      e.snap.Jobs,
		Machines:  e.list,
		Providers: e.rows,
		Limits: MachineLimits{
			MaxMachines:        e.cfg.Provider.MaxMachines,
			MaxCreatesInFlight: e.cfg.Provider.MaxCreatesInFlight,
			IdleTimeout:        e.cfg.Provider.IdleTimeout,
			ScaleDownCooldown:  e.cfg.Provider.ScaleDownCooldown,
			DeleteGrace:        e.cfg.Provider.DeleteGrace,
		},
	}
}

// machineSnapshot reads everything one pass decides on.
func (c *Controller) machineSnapshot(ctx context.Context, providers []*store.Provider) (*machineEnv, error) {
	snap, err := c.snapshot(ctx)
	if err != nil {
		return nil, err
	}
	cfg := c.cfg()
	// A machine takes minutes to arrive, so it starts before the delay that
	// exists to damp runner churn has expired: the delay has already been paid
	// by the hypervisor being slow.
	snap.Policy.ScaleUpDelay = cfg.Provider.ScaleUpDelay

	env := &machineEnv{
		now:    c.Now(),
		holder: c.controllerID(),
		cfg:    cfg,
		snap:   snap,
		plan:   scheduler.Decide(snap),
		rows:   providers,
		byID:   make(map[string]*store.Provider, len(providers)),
		hosts:  make(map[string]*store.Host, len(snap.Hosts)),
		live:   map[string]int{},
	}
	for _, p := range providers {
		env.byID[p.ID] = p
		ms, err := c.st.ListMachinesForProvider(ctx, p.ID)
		if err != nil {
			return nil, fmt.Errorf("listing machines for provider %s: %w", p.Name, err)
		}
		env.list = append(env.list, ms...)
	}
	for _, h := range snap.Hosts {
		env.hosts[h.ID] = h
	}
	for _, rs := range snap.Runners {
		for _, r := range rs {
			if r != nil && r.State.Live() {
				env.live[r.HostID]++
			}
		}
	}
	return env, nil
}

// controllerID is what this controller stamps on the resources it creates and
// claims operations under. The lease holder where there is one, because that is
// the identity another controller would see; a fixed local name otherwise, for
// the embedded and test controllers that hold no lease.
func (c *Controller) controllerID() string {
	if c.lease != nil && c.lease.Holder != "" {
		return c.lease.Holder
	}
	return "ctl_local"
}

// ---------------------------------------------------------------------------
// The guards -- the kill switch, in three layers
// ---------------------------------------------------------------------------

// mutationsHeld says why no provider may be changed at all right now, or ""
// when one may.
//
// Only the recovery fence answers here, and it is deliberately stricter than
// the operator's kill switch: it blocks deletes as well as creates. A fenced
// database may be a RESTORED COPY, so its machine rows may describe resources
// a different, live controller owns -- and deleting somebody else's running
// machine on the strength of a restored row is the worst thing this system
// could do. Inspecting, listing, polling an operation and recording what was
// seen all continue, because none of them changes anything.
func (c *Controller) mutationsHeld() string {
	if f := c.Fenced(); f.Fenced {
		return "this fleet is fenced for recovery, so nothing is created or deleted at any provider: " +
			"a restored database's machines may belong to a controller that is still running"
	}
	return ""
}

// provisioningHeld says why no new machine may be created right now, or "" when
// one may.
//
// Drains, deletes, recovery and sweeps never consult it: draining and removing
// a machine ask the provider for nothing new, so a held provider still scales
// down -- holdWhileRateLimited's asymmetry, for the same reason. A kill switch
// that also stopped those would strand running machines nobody is watching.
func (c *Controller) provisioningHeld(p *store.Provider, now time.Time) string {
	if held := c.mutationsHeld(); held != "" {
		return held
	}
	if c.cfg().Provider.Paused {
		return "provider.paused is set, so no new machine is created anywhere; " +
			"draining, deleting and recovery continue"
	}
	if p == nil {
		return ""
	}
	switch {
	case p.Paused:
		reason := p.PausedReason
		if reason == "" {
			reason = "an operator paused it"
		}
		return fmt.Sprintf("%s is paused: %s", p.Name, reason)
	case !p.Enabled:
		return fmt.Sprintf("%s is disabled, so it is offered no new demand", p.Name)
	case p.PausedUntil != nil && now.Before(*p.PausedUntil):
		return fmt.Sprintf("%s is standing down after %s in a row; trying again in %s",
			p.Name, plural(p.ConsecutiveFailures, "failure"), roundDuration(p.PausedUntil.Sub(now)))
	}
	return ""
}

// ---------------------------------------------------------------------------
// Building providers
// ---------------------------------------------------------------------------

// machineProvider is one configuration row and the client built from it.
type machineProvider struct {
	row *store.Provider
	p   provider.Provider
}

// providerFor builds the client for one row, cached until the row changes.
//
// The credential is unsealed here and handed to the factory for the life of
// the client it builds. It is never written anywhere else and has no field in
// anything that reaches a guest: the type MachineSpec has nowhere to put one.
func (c *Controller) providerFor(ctx context.Context, row *store.Provider) (*machineProvider, error) {
	c.machines.cacheMu.Lock()
	if got, ok := c.machines.cache[row.ID]; ok && got.updatedAt.Equal(row.UpdatedAt) {
		c.machines.cacheMu.Unlock()
		return &machineProvider{row: row, p: got.p}, nil
	}
	c.machines.cacheMu.Unlock()

	credential, err := c.unsealString(row.CredentialsEnc, "provider "+row.Name+"'s credential")
	if err != nil {
		return nil, err
	}
	var address string
	if len(row.TailcatAddressEnc) > 0 {
		if !c.cfg().Server.TailcatEnabled {
			return nil, errPrivateConnectionsDisabled(row)
		}
		address, err = c.unsealString(row.TailcatAddressEnc, "provider "+row.Name+"'s private connection address")
		if err != nil {
			return nil, err
		}
	}
	p, tunnel, err := c.buildProvider(ctx, row, credential, address)
	if err != nil {
		return nil, err
	}
	c.machines.cacheMu.Lock()
	if old, ok := c.machines.cache[row.ID]; ok && old.tunnel != nil {
		old.tunnel.Close()
	}
	c.machines.cache[row.ID] = &builtProvider{p: p, updatedAt: row.UpdatedAt, tunnel: tunnel}
	c.machines.cacheMu.Unlock()
	return &machineProvider{row: row, p: p}, nil
}

// errPrivateConnectionsDisabled is the refusal for a row that is reached
// through a gateway on a controller with the tunnel switched off.
func errPrivateConnectionsDisabled(row *store.Provider) error {
	return errors.New("provider " + row.Name + " is reached over a private connection, and private connections are disabled; set server.tailcat_enabled to true and restart the controller, or switch the provider to a direct connection")
}

// buildProvider makes one client from a row and its already-unsealed secrets,
// and owns nothing afterwards: the caller caches the tunnel or closes it. It
// is separate from providerFor so that a draft the wizard has not saved --
// which has no row to unseal from and nothing to cache under -- can be built
// the same way and asked what its credential can see.
func (c *Controller) buildProvider(ctx context.Context, row *store.Provider, credential, address string) (provider.Provider, *privateDialer, error) {
	cfg, tunnel, err := c.providerConfig(row, credential, address)
	if err != nil {
		return nil, nil, err
	}
	p, err := c.providers.New(ctx, row.Kind, cfg)
	if err != nil {
		if tunnel != nil {
			tunnel.Close()
		}
		return nil, nil, err
	}
	return p, tunnel, nil
}

// providerConfig is what a factory is handed for one row, with the private
// connection opened when the row has one. The caller owns the tunnel.
func (c *Controller) providerConfig(row *store.Provider, credential, address string) (provider.Config, *privateDialer, error) {
	cfg := provider.Config{
		ProviderID: row.ID,
		Owner:      provider.Owner{ControllerID: c.controllerID(), ProviderID: row.ID},
		Endpoint:   row.Endpoint,
		Settings:   row.Settings,
		Credential: credential,
		CAPEM:      row.CAPEM,
		Insecure:   row.InsecureSkipVerify,
		Deadlines:  c.providerDeadlines(),
		// Only an injected client is handed on. The default one this
		// controller keeps for its own requests knows nothing about the
		// row's certificate settings or its private connection, and a
		// provider given a ready-made client uses it as it is.
		HTTPClient: c.providerHTTP,
		Logger:     c.log.With("provider", row.Name),
	}
	var tunnel *privateDialer
	if address != "" {
		var err error
		tunnel, err = newPrivateDialer(address)
		if err != nil {
			return provider.Config{}, nil, errors.New("provider " + row.Name + ": " + err.Error())
		}
		cfg.DialContext = tunnel.DialContext
	}
	return cfg, tunnel, nil
}

// closeProviderTunnels releases every private connection the cache holds. It
// runs when the controller stops; a row that is deleted while running keeps
// its client until the controller restarts, which costs an idle userspace
// network stack and nothing else.
func (c *Controller) closeProviderTunnels() {
	c.machines.cacheMu.Lock()
	defer c.machines.cacheMu.Unlock()
	for id, built := range c.machines.cache {
		if built.tunnel != nil {
			built.tunnel.Close()
		}
		delete(c.machines.cache, id)
	}
}

// providerDeadlines is the operator's half of the budget. A provider may ask
// for longer than these and never for less supervision.
func (c *Controller) providerDeadlines() provider.Deadlines {
	cfg := c.cfg().Provider
	return provider.Deadlines{
		Call:      cfg.CallTimeout,
		Allocate:  cfg.CallTimeout,
		Create:    cfg.CreateTimeout,
		Bootstrap: cfg.BootstrapTimeout,
		Delete:    cfg.DeleteTimeout,
	}
}

// stepTimeout is how long one step's requests get. It is not how long the work
// takes: a create is asynchronous, and the deadline that bounds the whole clone
// is provider.create_timeout, checked against the row rather than against a
// context. Two call timeouts, because the longest step makes two requests.
func (c *Controller) stepTimeout(pr *machineProvider) time.Duration {
	d := c.cfg().Provider.CallTimeout
	if d <= 0 {
		d = 30 * time.Second
	}
	if ask := pr.p.Capabilities().Deadlines.Call; ask > d {
		d = ask
	}
	return 2 * d
}

// ---------------------------------------------------------------------------
// Applying the plan
// ---------------------------------------------------------------------------

// applyMachinePlan writes this pass's reservations and starts this pass's
// drains. A failure on one provider never abandons the rest.
func (c *Controller) applyMachinePlan(ctx context.Context, env *machineEnv, plan MachinePlan) {
	for _, pp := range plan.Providers {
		row := env.provider(pp.ProviderID)
		if row == nil {
			continue
		}
		if pp.Create > 0 {
			// A machine already draining is cheaper than a new one, and the
			// drain is reversible right up until the delete starts: demand
			// that came back before then takes its machine back rather than
			// paying to build another.
			pp.Create -= c.reviveDraining(ctx, env, row, pp)
		}
		if pp.Create > 0 {
			if held := c.provisioningHeld(row, env.now); held != "" {
				c.log.Debug("machines were wanted and nothing may be bought", "provider", row.Name,
					"wanted", pp.Create, "held", held)
			} else {
				c.reserveMachines(ctx, env, row, pp)
			}
		}
		for _, id := range pp.Drain {
			c.beginDrain(ctx, env, id)
		}
	}
}

// reserveMachines writes the planned rows for one provider's purchase.
//
// The row is written before the credential is minted and before the provider
// is called, so that a failure has somewhere to be recorded -- the createRunner
// ordering, for the same reason. Deleting the row instead would leave a
// provider silently one machine short with nothing to explain it and, worse
// here, a machine nobody has a record of.
func (c *Controller) reserveMachines(ctx context.Context, env *machineEnv, row *store.Provider, pp ProviderPlan) {
	expires := env.now.Add(c.cfg().Provider.CreateTimeout)
	for range pp.Create {
		m := &store.Machine{
			ProviderID:           row.ID,
			State:                store.MachinePlanned,
			Message:              pp.Reason,
			Capacity:             row.MachineCapacity,
			Labels:               row.MachineLabels,
			ReservationExpiresAt: &expires,
		}
		if err := c.st.CreateMachine(ctx, m); err != nil {
			c.log.Error("could not reserve a machine", "provider", row.Name, "error", err)
			return
		}
		env.list = append(env.list, m)
		c.publishMachine(ctx, m)
		c.log.Info("a machine was reserved", "machine", m.ID, "name", m.Name,
			"provider", row.Name, "reason", pp.Reason)
	}
}

// reviveDraining takes back as many of this provider's draining machines as the
// pass wants to buy, and returns how many it took.
//
// It is the other half of a drain being an intent rather than an act: nothing
// has been deleted yet, the host is cordoned and its runners have finished, so
// uncordoning costs nothing and saves the minutes a clone takes. A machine
// whose delete has started is past this -- a delete that was issued cannot be
// un-issued.
func (c *Controller) reviveDraining(ctx context.Context, env *machineEnv, row *store.Provider, pp ProviderPlan) int {
	taken := 0
	for _, m := range env.list {
		if taken >= pp.Create {
			break
		}
		if m.ProviderID != row.ID || m.State != store.MachineDraining {
			continue
		}
		if slices.Contains(pp.Drain, m.ID) {
			// This pass wants it gone, so taking it back would be the same
			// pass disagreeing with itself.
			continue
		}
		if m.HostID != "" {
			if err := c.st.SetHostCordoned(ctx, m.HostID, false); err != nil {
				c.log.Warn("could not uncordon a machine coming back into service",
					"machine", m.ID, "host", m.HostID, "error", err)
				continue
			}
			if h, err := c.st.GetHost(ctx, m.HostID); err == nil {
				c.publishHost(h)
			}
		}
		c.transitionMachine(ctx, env, m, store.MachineReady,
			"work came back for this machine's pools before it was released")
		taken++
	}
	return taken
}

// beginDrain cordons a machine's host and moves the machine to draining, which
// is reversible right up until the delete starts.
func (c *Controller) beginDrain(ctx context.Context, env *machineEnv, id string) {
	m := env.machine(id)
	if m == nil || m.State != store.MachineReady {
		return
	}
	if m.HostID != "" {
		if err := c.st.SetHostCordoned(ctx, m.HostID, true); err != nil {
			c.log.Warn("could not cordon a draining machine's host", "machine", id, "host", m.HostID, "error", err)
			return
		}
		if h, err := c.st.GetHost(ctx, m.HostID); err == nil {
			c.publishHost(h)
		}
	}
	c.transitionMachine(ctx, env, m, store.MachineDraining,
		"this machine's pools have had no queued work for long enough that it is no longer worth paying for")
}

func (e *machineEnv) machine(id string) *store.Machine {
	for _, m := range e.list {
		if m.ID == id {
			return m
		}
	}
	return nil
}

// transitionMachine moves a machine and publishes the result, keeping the
// pass's own copy of the row in step so that a later step in the same pass is
// not deciding from a state that has already moved.
func (c *Controller) transitionMachine(ctx context.Context, env *machineEnv, m *store.Machine, to store.MachineState, message string) {
	out, err := c.st.TransitionMachine(ctx, m.ID, to, message)
	if err != nil {
		// Two passes racing over one machine is normal rather than an error,
		// and so is a machine an operator moved underneath this pass.
		if errors.Is(err, store.ErrInvalidTransition) || errors.Is(err, store.ErrNotFound) {
			c.log.Debug("a machine could not be moved", "machine", m.ID, "to", to, "error", err)
			return
		}
		c.log.Error("could not move a machine", "machine", m.ID, "to", to, "error", err)
		return
	}
	*m = *out
	c.publishMachine(ctx, m)
}

// ---------------------------------------------------------------------------
// Stepping
// ---------------------------------------------------------------------------

// stepMachines advances every machine by at most one step, so a pass is
// bounded and a restart never finds a half-applied multi-step sequence.
//
// The steps that talk to a provider run in their own goroutine on a detached,
// bounded context: a hypervisor that accepts a connection and never answers
// must hold up one machine rather than the pass, and the answer must still be
// recorded if the process is asked to stop while the request is out. Stop waits
// for them.
func (c *Controller) stepMachines(ctx context.Context, env *machineEnv) {
	for _, m := range env.list {
		row := env.provider(m.ProviderID)
		if row == nil {
			continue
		}
		switch m.State {
		case store.MachineDeleted, store.MachineQuarantined, store.MachineFailed:
			// A quarantined machine moves when a person moves it, and never
			// otherwise. A failed one keeps whatever resource it has until a
			// sweep or an operator says what to do with it.
			continue
		}
		if m.NextAttemptAt != nil && env.now.Before(*m.NextAttemptAt) {
			continue
		}

		// The states that are answered by looking at our own rows need no
		// provider call, no claim and no goroutine.
		switch m.State {
		case store.MachineEnrolling:
			c.stepEnrolling(ctx, env, m)
			continue
		case store.MachineReady:
			c.stepReady(ctx, env, m)
			continue
		case store.MachineDraining:
			c.stepDraining(ctx, env, m)
			continue
		}

		pr, err := c.providerFor(ctx, row)
		if err != nil {
			c.noteProviderTrouble(row.ID, err, m.ID, env.now)
			continue
		}
		kind := machineOperationFor(m.State)
		if kind == store.MachineOpNone {
			continue
		}
		if c.machines.operationCount >= 8 || c.machines.providerOperations[row.ID] >= 4 {
			continue
		}
		claimed, ok := c.claimMachineStep(ctx, env, m, kind)
		if !ok {
			continue
		}
		*m = *claimed

		timeout := c.stepTimeout(pr)

		if c.machines.providerOperations == nil {
			c.machines.providerOperations = map[string]int{}
		}
		c.machines.operationCount++
		c.machines.providerOperations[row.ID]++
		c.machines.calls.Add(1)
		go func(m *store.Machine) {
			defer c.machines.calls.Done()
			defer func() {
				c.machines.mu.Lock()
				c.machines.operationCount--
				c.machines.providerOperations[m.ProviderID]--
				c.machines.mu.Unlock()
			}()
			cctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), timeout)
			defer cancel()
			c.runMachineStep(cctx, env, pr, m)
		}(claimed)
	}
}

// claimMachineStep takes this machine's next step, or carries on with the
// operation it is already in the middle of.
//
// An operation outlives the pass that issued it: a create is asynchronous, its
// handle lives in the same columns as the claim, and giving the claim back
// would take the handle with it -- so a pass that has issued one keeps the
// claim and the next pass polls what it finds. The claim's timeout is the
// PHASE's budget rather than one request's, which is what makes an operation
// whose controller died takeable exactly when it has run out of time.
//
// A live claim left by another holder is continued rather than refused. This
// controller holds the database lease, so another holder is a previous life of
// this fleet rather than a rival -- and the first thing a continuation does is
// ask the provider what happened, which is safe whoever asked last.
func (c *Controller) claimMachineStep(ctx context.Context, env *machineEnv, m *store.Machine, kind store.MachineOpKind) (*store.Machine, bool) {
	if m.OpID != "" && m.OpDeadlineAt != nil && env.now.Before(*m.OpDeadlineAt) {
		if m.OpKind != kind {
			// The operation in flight is not the one this state calls for.
			// Leaving it to finish is the only safe answer: its handle is the
			// only record of what was issued.
			return nil, false
		}
		return m, true
	}
	claimed, err := c.st.ClaimMachineOperation(ctx, m.ID, store.MachineOperation{
		Kind: kind, Holder: env.holder, Timeout: c.operationBudget(kind),
	}, env.now)
	if err != nil {
		if !errors.Is(err, store.ErrMachineBusy) {
			c.log.Warn("could not claim a machine's next step", "machine", m.ID, "error", err)
		}
		return nil, false
	}
	return claimed, true
}

// operationBudget is how long a phase has before its claim is takeable. It is
// the phase's own timeout, not one request's: a claim shorter than the work
// would let a second pass start issuing while the first was still under way.
func (c *Controller) operationBudget(kind store.MachineOpKind) time.Duration {
	cfg := c.cfg().Provider
	var d time.Duration
	switch kind {
	case store.MachineOpBootstrap:
		d = cfg.BootstrapTimeout
	case store.MachineOpDelete:
		d = cfg.DeleteTimeout
	default:
		// Create, start and stop all live inside the budget for building a
		// machine, because that is what they are steps of.
		d = cfg.CreateTimeout
	}
	if d <= 0 {
		d = 20 * time.Minute
	}
	return d + machineClaimMargin
}

// machineOperationFor is the one operation a machine in this state can be
// doing. It is the claim's kind, so that a machine stuck mid-step says which
// step it is stuck in.
func machineOperationFor(s store.MachineState) store.MachineOpKind {
	switch s {
	case store.MachinePlanned, store.MachineCreating:
		return store.MachineOpCreate
	case store.MachineStarting:
		return store.MachineOpStart
	case store.MachineBootstrapping:
		return store.MachineOpBootstrap
	case store.MachineDeleting:
		return store.MachineOpDelete
	}
	return store.MachineOpNone
}

// runMachineStep makes one machine's provider call and records what it learnt.
func (c *Controller) runMachineStep(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) {
	opID := m.OpID
	started := time.Now()

	var err error
	if !c.mayAct() {
		c.recordMachineFailure(ctx, env, pr, m, opID, errMachineHeld)
		return
	}
	switch m.State {
	case store.MachinePlanned:
		err = c.stepPlanned(ctx, env, pr, m)
	case store.MachineCreating:
		err = c.stepCreating(ctx, env, pr, m)
	case store.MachineStarting:
		err = c.stepStarting(ctx, env, pr, m)
	case store.MachineBootstrapping:
		err = c.stepBootstrapping(ctx, env, pr, m)
	case store.MachineDeleting:
		err = c.stepDeleting(ctx, env, pr, m)
	}
	c.metrics.providerOperations.WithLabelValues(string(m.OpKind), operationOutcome(err)).Inc()
	c.metrics.providerOperationSeconds.WithLabelValues(string(m.OpKind)).Observe(time.Since(started).Seconds())

	switch {
	case errors.Is(err, errMachineHeld):
		// A guard refused after the claim was taken. Released rather than
		// failed: nothing about the machine went wrong, and counting it would
		// walk the backoff up towards giving up on a machine nobody has tried.
		c.finishMachineOperation(ctx, m, opID, store.MachineOpReleased, "", nil)
	case errors.Is(err, errMachineWaiting):
		// Nothing is written at all. The operation is still in flight, and the
		// claim is what carries its handle from this pass to the next.
	case errors.Is(err, errMachineUnknownOutcome):
		// Deliberately not finished. The operation is not over -- nobody knows
		// whether it happened -- and the claim expiring on its own is what lets
		// the next pass ASK rather than act. Finishing here would clear the one
		// flag that says the answer was never heard.
	case err != nil:
		c.recordMachineFailure(ctx, env, pr, m, opID, err)
	default:
		c.finishMachineOperation(ctx, m, opID, store.MachineOpSucceeded, "", nil)
		c.noteProviderSuccess(ctx, pr.row.ID)
	}
}

// The three outcomes that are not failures, as sentinels so that each step can
// simply return one.
var (
	// errMachineHeld is a guard that refused after the claim was taken.
	errMachineHeld = errors.New("this machine may not be changed right now")
	// errMachineWaiting is an operation that has not finished yet, which is
	// the normal answer to most polls.
	errMachineWaiting = errors.New("this machine's operation has not finished")
	// errMachineUnknownOutcome is the one that matters: the request went out
	// and we never heard. It is never retried, only looked into.
	errMachineUnknownOutcome = errors.New("this machine's operation ended without an answer")
)

// operationOutcome is the metric label for how a call went. The categories are
// the ones an operator would separate: it worked, it was refused for capacity,
// we could not reach the provider, it refused, or we never found out.
func operationOutcome(err error) string {
	switch {
	case err == nil, errors.Is(err, errMachineWaiting), errors.Is(err, errMachineHeld):
		return "ok"
	case errors.Is(err, errMachineUnknownOutcome):
		return "ambiguous"
	}
	switch provider.KindOf(err) {
	case provider.FailureQuota:
		return "quota"
	case provider.FailureUnreachable:
		return "unreachable"
	}
	return "refused"
}

func (c *Controller) finishMachineOperation(ctx context.Context, m *store.Machine, opID string, out store.MachineOpOutcome, message string, next *time.Time) {
	if err := c.st.FinishMachineOperation(ctx, m.ID, opID, out, message, next); err != nil {
		c.log.Warn("could not record a machine operation's outcome", "machine", m.ID, "error", err)
	}
	c.publishMachineByID(ctx, m.ID)
}

// publishMachineByID re-reads a machine and publishes it, for the changes that
// are column writes rather than transitions.
func (c *Controller) publishMachineByID(ctx context.Context, id string) {
	m, err := c.st.GetMachine(ctx, id)
	if err != nil {
		return
	}
	c.publishMachine(ctx, m)
}

// recordMachineFailure settles one failed step: the provider's own sentence on
// the row, the backoff, and the provider's breaker.
//
// A failure nothing but a person can fix -- a wrong credential, a missing
// privilege, a setting -- goes straight to failed with the provider's words.
// There is nothing to wait for, and retrying it five times only delays the
// moment somebody reads the reason.
func (c *Controller) recordMachineFailure(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine, opID string, err error) {
	kind := provider.KindOf(err)
	detail := err.Error()
	now := c.Now()

	terminal := !provider.Retryable(err) || m.Attempts+1 >= machineMaxAttempts
	next := now.Add(c.machineBackoff(m.Attempts + 1))
	if at, ok := provider.RetryAfter(err, now); ok {
		// The provider named a time, and its own rate limiter knows better
		// than our backoff. A time already in the past is no answer, which
		// RetryAfter has already refused.
		next = at
	}
	c.finishMachineOperation(ctx, m, opID, store.MachineOpFailed, detail, &next)
	c.noteProviderTrouble(pr.row.ID, err, m.ID, now)
	c.noteProviderFailure(ctx, pr.row.ID, m)

	if terminal {
		c.transitionMachine(ctx, env, m, store.MachineFailed, detail)
		c.log.Warn("a machine was given up on", "machine", m.ID, "name", m.Name,
			"provider", pr.row.Name, "kind", kind, "error", detail)
		return
	}
	c.log.Warn("a machine's step failed and will be tried again", "machine", m.ID,
		"provider", pr.row.Name, "kind", kind, "attempts", m.Attempts+1, "next", next, "error", detail)
}

// machineBackoff is how long to wait before attempt n+1.
//
// Jittered down by up to a quarter, and the number is drawn here rather than
// in the decision function for the same reason poolJitter is: a decision has to
// be reproducible from the snapshot that produced it, and one that reached for
// rand inside could not be put in front of a test.
func (c *Controller) machineBackoff(attempts int) time.Duration {
	if attempts < 1 {
		attempts = 1
	}
	wait := machineRetryBase
	for range attempts - 1 {
		wait *= 2
		if wait >= machineRetryMax {
			wait = machineRetryMax
			break
		}
	}
	return wait - time.Duration(rand.Float64()*float64(wait)/4)
}

// ---------------------------------------------------------------------------
// The steps
// ---------------------------------------------------------------------------

// stepPlanned takes a machine from a reservation to a machine being built.
//
// The ordering is everything: the identity is allocated, written to the row,
// and only then is anything created. A create whose answer is lost is therefore
// answered by asking about an identity we already hold, rather than by creating
// a second machine.
func (c *Controller) stepPlanned(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	if held := c.provisioningHeld(pr.row, c.Now()); held != "" {
		return fmt.Errorf("%w: %s", errMachineHeld, held)
	}
	owner := c.machineOwner(pr.row, m)
	spec, err := c.machineSpec(ctx, env, pr, m, owner)
	if err != nil {
		return err
	}
	ref, err := pr.p.Allocate(ctx, spec)
	if err != nil {
		return err
	}
	if ref.ID == "" && ref.Name == "" {
		return fmt.Errorf("%s allocated nothing to identify a machine by; a provider must return an id, a name, or both", pr.row.Name)
	}
	if ref.Name == "" {
		ref.Name = m.Name
	}
	// The identity, before anything exists to lose. SetMachineResource refuses
	// to move one already set, so a pass that lost a race leaves the first
	// identity standing rather than pointing the row away from a live machine.
	id := ref.ID
	if id == "" {
		id = ref.Name
	}
	if err := c.st.SetMachineResource(ctx, m.ID, ref.Zone, id, owner.Fingerprint, owner.ControllerID); err != nil {
		return err
	}
	c.transitionMachine(ctx, env, m, store.MachineCreating,
		fmt.Sprintf("building %s at %s", ref.Name, pr.row.Name))

	op, err := pr.p.Create(ctx, ref, spec)
	if err != nil {
		return c.noteAmbiguity(ctx, m, err)
	}
	if op.Zero() {
		// A synchronous provider: there is nothing to follow, and the next
		// pass asks what exists.
		return nil
	}
	if err := c.st.SetMachineOperationHandle(ctx, m.ID, m.OpID, op.Handle); err != nil {
		c.log.Warn("could not record a create's handle", "machine", m.ID, "error", err)
	}
	return errMachineWaiting
}

// noteAmbiguity records a call whose outcome was never heard, and turns
// anything else straight back into a failure.
//
// It leaves the claim in place: the operation is not finished, nobody knows
// whether it happened, and the one thing that must not follow is a retry that
// treats silence as failure and creates a second machine.
func (c *Controller) noteAmbiguity(ctx context.Context, m *store.Machine, err error) error {
	if provider.KindOf(err) != provider.FailureAmbiguous {
		return err
	}
	if mErr := c.st.MarkMachineOutcomeUnknown(ctx, m.ID, m.OpID, err.Error()); mErr != nil {
		c.log.Warn("could not record that an operation's outcome is unknown", "machine", m.ID, "error", mErr)
	}
	c.publishMachineByID(ctx, m.ID)
	c.log.Warn("a machine operation ended without an answer; it will be resolved by looking, never by trying again",
		"machine", m.ID, "operation", m.OpKind, "error", err)
	return fmt.Errorf("%w: %s", errMachineUnknownOutcome, err)
}

// stepCreating follows a create to its end, or works out what became of one
// whose answer was never heard.
func (c *Controller) stepCreating(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	if m.OpHandle != "" && !m.OpOutcomeUnknown {
		status, err := pr.p.Operation(ctx, provider.OperationRef{Kind: provider.OpCreate, Handle: m.OpHandle})
		switch {
		case errors.Is(err, provider.ErrNotFound):
			// The provider has forgotten the task -- a restart at its end, or
			// a task log that has rolled over. What became of the machine is
			// still a question for Inspect.
		case err != nil:
			return err
		case !status.Done:
			return errMachineWaiting
		case !status.OK:
			return &provider.Error{Kind: provider.FailureRefused, Op: "create", Ref: m.Name,
				Message: status.Detail, Remedy: "the provider's own task log carries the rest of it"}
		}
	}
	return c.resolveByInspection(ctx, env, pr, m)
}

// resolveByInspection is the whole of ambiguity recovery: ask what exists, and
// let the answer decide.
//
// It never creates on a guess. A machine that cannot be found is looked for
// twice, a call timeout apart, before the identity is reused -- and past the
// ambiguity timeout it is quarantined rather than retried, because at that
// point the honest answer is that nobody knows and a person should look.
func (c *Controller) resolveByInspection(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	ref := machineRef(m)
	got, err := pr.p.Inspect(ctx, ref)
	switch {
	case err == nil:
	case errors.Is(err, provider.ErrNotFound):
		return c.resolveMissing(ctx, env, pr, m)
	default:
		return err
	}

	if why := c.ownershipComplaint(m, got); why != "" {
		return c.quarantineMachine(ctx, env, m, why)
	}
	if got.Locked != "" {
		// Something else holds the resource. A reason to wait, not a failure,
		// and never a reason to create a second machine.
		return errMachineWaiting
	}
	if err := c.st.SetMachineOwnershipVerified(ctx, m.ID, c.Now()); err != nil {
		c.log.Warn("could not record a machine's ownership", "machine", m.ID, "error", err)
	}
	c.recordMachineAddress(ctx, m, got)

	switch got.Phase {
	case provider.PhaseRunning:
		c.transitionMachine(ctx, env, m, store.MachineBootstrapping, "the machine is running; installing the agent")
	case provider.PhaseStopped:
		c.transitionMachine(ctx, env, m, store.MachineStarting, "the machine exists and is being started")
	case provider.PhaseCreating:
		return errMachineWaiting
	default:
		// PhaseUnknown and PhaseDeleting both mean we cannot say what this is,
		// and what we cannot recognise we leave alone.
		return errMachineWaiting
	}
	return nil
}

// resolveMissing decides what to do about an identity the provider cannot find.
func (c *Controller) resolveMissing(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	cfg := c.cfg().Provider
	since := m.CreatedAt
	if m.CreateStartedAt != nil {
		since = *m.CreateStartedAt
	}
	if c.Now().Sub(since) > cfg.AmbiguityTimeout {
		return c.quarantineMachine(ctx, env, m, fmt.Sprintf(
			"this machine's create was issued %s ago and %s still cannot find %s. Nothing has been created or deleted: "+
				"look in the provider's console, then either release this row or delete the resource by hand",
			roundDuration(c.Now().Sub(since)), pr.row.Name, m.ResourceID))
	}
	if m.Attempts == 0 {
		// Looked for once. A provider that has just accepted a create often
		// cannot answer about it yet, so one absence is not evidence that
		// nothing was created.
		return &provider.Error{Kind: provider.FailureNotFound, Op: "inspect", Ref: m.Name,
			Message: fmt.Sprintf("%s cannot find %s yet; looking again before anything is created", pr.row.Name, m.ResourceID),
			Remedy:  "nothing to do: the machine is looked for once more before its identity is reused"}
	}
	// Twice, a call timeout apart. The identity is reused rather than a new one
	// allocated: that is what makes this a retry of one machine rather than the
	// purchase of a second.
	if held := c.provisioningHeld(pr.row, c.Now()); held != "" {
		return fmt.Errorf("%w: %s", errMachineHeld, held)
	}
	owner := c.machineOwner(pr.row, m)
	spec, err := c.machineSpec(ctx, env, pr, m, owner)
	if err != nil {
		return err
	}
	op, err := pr.p.Create(ctx, machineRef(m), spec)
	if err != nil {
		return c.noteAmbiguity(ctx, m, err)
	}
	if op.Zero() {
		return nil
	}
	if err := c.st.SetMachineOperationHandle(ctx, m.ID, m.OpID, op.Handle); err != nil {
		c.log.Warn("could not record a create's handle", "machine", m.ID, "error", err)
	}
	return errMachineWaiting
}

// stepStarting powers a machine on and waits for it to be running.
func (c *Controller) stepStarting(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	if m.OpHandle != "" {
		status, err := pr.p.Operation(ctx, provider.OperationRef{Kind: provider.OpStart, Handle: m.OpHandle})
		switch {
		case errors.Is(err, provider.ErrNotFound):
		case err != nil:
			return err
		case !status.Done:
			return errMachineWaiting
		}
	}
	got, err := pr.p.Inspect(ctx, machineRef(m))
	if err != nil {
		return err
	}
	if why := c.ownershipComplaint(m, got); why != "" {
		return c.quarantineMachine(ctx, env, m, why)
	}
	c.recordMachineAddress(ctx, m, got)
	if got.Phase == provider.PhaseRunning {
		c.transitionMachine(ctx, env, m, store.MachineBootstrapping, "the machine is running; installing the agent")
		return nil
	}
	power, ok := pr.p.(provider.PowerController)
	if !ok || got.Phase != provider.PhaseStopped {
		return errMachineWaiting
	}
	if held := c.mutationsHeld(); held != "" {
		return fmt.Errorf("%w: %s", errMachineHeld, held)
	}
	op, err := power.Start(ctx, machineRef(m))
	if err != nil {
		return c.noteAmbiguity(ctx, m, err)
	}
	if !op.Zero() {
		if err := c.st.SetMachineOperationHandle(ctx, m.ID, m.OpID, op.Handle); err != nil {
			c.log.Warn("could not record a start's handle", "machine", m.ID, "error", err)
		}
	}
	return errMachineWaiting
}

// stepReady is an observation and nothing else: a ready machine is a host, and
// the host's own lifecycle is the fleet's.
//
// What it writes is when the machine last had nothing to do, which is the clock
// scale-down counts from. It is stamped once and cleared the moment a runner
// lands, so a machine that has been idle all afternoon does not look like one
// that went idle a moment ago.
func (c *Controller) stepReady(ctx context.Context, env *machineEnv, m *store.Machine) {
	if m.HostID == "" {
		// The host row has gone -- deleted by an operator, or lost with a
		// restore. The machine is still rented, so it is drained and deleted
		// rather than forgotten.
		c.transitionMachine(ctx, env, m, store.MachineDraining,
			"the host this machine enrolled as no longer exists, so the machine is being released")
		return
	}
	host := env.hosts[m.HostID]
	if host == nil {
		c.transitionMachine(ctx, env, m, store.MachineDraining,
			"the host this machine enrolled as no longer exists, so the machine is being released")
		return
	}
	switch {
	case env.live[host.ID] > 0:
		if m.IdleSince != nil {
			if err := c.st.SetMachineIdleSince(ctx, m.ID, nil); err != nil {
				c.log.Warn("could not clear a machine's idle time", "machine", m.ID, "error", err)
			}
			m.IdleSince = nil
			c.publishMachine(ctx, m)
		}
	case m.IdleSince == nil:
		at := env.now
		if err := c.st.SetMachineIdleSince(ctx, m.ID, &at); err != nil {
			c.log.Warn("could not record a machine's idle time", "machine", m.ID, "error", err)
			return
		}
		m.IdleSince = &at
		c.publishMachine(ctx, m)
	}
}

// stepDraining waits for a machine's runners to finish, and lets demand take it
// back until the moment the delete starts.
func (c *Controller) stepDraining(ctx context.Context, env *machineEnv, m *store.Machine) {
	if m.HostID != "" && env.live[m.HostID] > 0 {
		return
	}
	c.transitionMachine(ctx, env, m, store.MachineDeleting,
		"the machine is empty and is being released")
}

// stepDeleting removes a machine, and is not finished until the provider says
// the resource is gone.
//
// A removal is not complete until the provider says the resource is gone. A 200
// from the delete call is not that; an Inspect that answers ErrNotFound is.
// recoverHostCleanup's header comment is the same sentence about a host.
func (c *Controller) stepDeleting(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine) error {
	if m.ResourceID == "" {
		// Nothing was ever created, so there is nothing to confirm gone.
		return c.confirmDeleted(ctx, env, m)
	}
	// Has the delete already issued finished? Its handle is the only record of
	// it, and polling before looking is what stops a delete being issued twice
	// while the first one is still running.
	issued := false
	if m.OpHandle != "" {
		status, err := pr.p.Operation(ctx, provider.OperationRef{Kind: provider.OpDelete, Handle: m.OpHandle})
		switch {
		case errors.Is(err, provider.ErrNotFound):
			// The provider has forgotten the task. What became of the resource
			// is still Inspect's to answer.
			issued = true
		case err != nil:
			return err
		case !status.Done:
			return errMachineWaiting
		default:
			issued = true
		}
	}

	got, err := pr.p.Inspect(ctx, machineRef(m))
	switch {
	case errors.Is(err, provider.ErrNotFound):
		return c.confirmDeleted(ctx, env, m)
	case err != nil:
		return err
	}
	if why := c.ownershipComplaint(m, got); why != "" {
		return c.quarantineMachine(ctx, env, m, why)
	}
	if err := c.st.SetMachineOwnershipVerified(ctx, m.ID, c.Now()); err != nil {
		c.log.Warn("could not record a machine's ownership", "machine", m.ID, "error", err)
	}
	if issued {
		// The delete finished and the resource is still there, so it did not
		// work. The claim goes back rather than being held against a task that
		// has already ended: the next attempt needs a handle of its own, and
		// the delete timeout is what says when to stop asking.
		return nil
	}
	if !got.Phase.AuthorisesDelete() {
		// PhaseUnknown above all: what we cannot recognise we leave alone,
		// which costs a stuck machine and saves somebody else's.
		return errMachineWaiting
	}
	if held := c.mutationsHeld(); held != "" {
		return fmt.Errorf("%w: %s", errMachineHeld, held)
	}
	if got.Locked != "" {
		return errMachineWaiting
	}
	op, err := pr.p.Delete(ctx, machineRef(m))
	if err != nil {
		return c.noteAmbiguity(ctx, m, err)
	}
	if !op.Zero() {
		if err := c.st.SetMachineOperationHandle(ctx, m.ID, m.OpID, op.Handle); err != nil {
			c.log.Warn("could not record a delete's handle", "machine", m.ID, "error", err)
		}
	}
	// Not done: the next pass inspects, and only an inspect that cannot find
	// the resource records the deletion.
	return errMachineWaiting
}

// confirmDeleted stamps the confirmation exactly once, and takes the host row
// with it.
func (c *Controller) confirmDeleted(ctx context.Context, env *machineEnv, m *store.Machine) error {
	stamped, err := c.st.ConfirmMachineDeleted(ctx, m.ID, c.Now())
	if err != nil {
		return err
	}
	c.transitionMachine(ctx, env, m, store.MachineDeleted, "the provider confirms this machine's resource is gone")
	if stamped && m.HostID != "" {
		if err := c.DeleteHost(ctx, m.HostID); err != nil && !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("a machine's resource is gone but its host row could not be removed",
				"machine", m.ID, "host", m.HostID, "error", err)
		}
	}
	if stamped {
		c.log.Info("a machine was released", "machine", m.ID, "name", m.Name)
	}
	return nil
}

// quarantineMachine stops a machine being acted on at all, with a sentence
// written for the person who now has to look.
func (c *Controller) quarantineMachine(ctx context.Context, env *machineEnv, m *store.Machine, why string) error {
	if err := c.st.SetMachineOwnershipError(ctx, m.ID, why); err != nil {
		c.log.Warn("could not record why a machine was quarantined", "machine", m.ID, "error", err)
	}
	// Nothing automatic will move this machine again, so its host has to stop
	// taking work. The scheduler cannot work this out for itself: its snapshot
	// carries hosts and never machines, so a quarantined machine's host stays
	// as placeable as any other, and the fleet would keep starting runners on a
	// resource it has just recorded it cannot prove it owns. Whoever the
	// resource does belong to may power it off at any moment, and every runner
	// placed after that is work lost.
	//
	// Cordoned rather than drained, so the runners already on it finish, and so
	// an operator who decides the machine was ours after all has one switch to
	// undo. A cordon that could not be written is logged and never stops the
	// quarantine: the row saying nothing may touch this machine is the more
	// important of the two.
	if m.HostID != "" {
		if err := c.st.SetHostCordoned(ctx, m.HostID, true); err != nil {
			c.log.Warn("could not cordon a quarantined machine's host",
				"machine", m.ID, "host", m.HostID, "error", err)
		} else if h, err := c.st.GetHost(ctx, m.HostID); err == nil {
			c.publishHost(h)
		}
	}
	c.transitionMachine(ctx, env, m, store.MachineQuarantined, why)
	c.log.Error("a machine was quarantined and nothing will act on it until a person does",
		"machine", m.ID, "name", m.Name, "reason", why)
	return nil
}

// ownershipComplaint reports which of the ownership facts disagreed, or "" when
// they all hold.
//
// The marks are not authenticated -- anybody with audit rights on the
// infrastructure can read and forge them -- so this is tamper-evidence rather
// than a credential. Its job is to tell "the machine I created at this
// identifier" apart from "a machine somebody else created at the same
// identifier after mine was destroyed", which is the accident that actually
// happens.
func (c *Controller) ownershipComplaint(m *store.Machine, got provider.Machine) string {
	want := provider.Owner{
		ControllerID: m.OwnerControllerID,
		ProviderID:   m.ProviderID,
		MachineID:    m.ID,
		Fingerprint:  m.OwnerFingerprint,
	}
	switch {
	case got.Ref.Name != "" && got.Ref.Name != m.Name:
		// Checked before the marks, because a name is the one identity an
		// unmarked resource still carries. Our guest destroyed out of band and
		// its identifier reused by another tool is the accident this exists to
		// catch -- and it arrives wearing no marks, so an unmarked-is-ours rule
		// that ran first would authorise a delete on the strength of our own
		// row. That is how a fleet destroys somebody else's machine.
		return fmt.Sprintf("machine %s names %s on %s, but that resource is called %q rather than %q. "+
			"Nothing has been deleted", m.ID, m.ResourceID, m.ResourceZone, got.Ref.Name, m.Name)
	case got.Owner.Zero():
		// An unmarked resource is not evidence of a second fleet: a provider
		// that cannot write marks leaves every resource like this, and the
		// store is then the only record of who made it. Safe only because the
		// name has already been agreed above.
		return ""
	case got.Owner.MachineID != "" && got.Owner.MachineID != m.ID:
		return fmt.Sprintf("machine %s names %s on %s, but that resource's ownership record says machine %s. "+
			"Nothing has been deleted. Check the provider's console, then either release this row -- which forgets "+
			"the resource without touching it -- or delete the resource by hand",
			m.ID, m.ResourceID, m.ResourceZone, got.Owner.MachineID)
	case !got.Owner.Matches(want):
		return fmt.Sprintf("machine %s names %s on %s, but that resource was created by another controller. "+
			"Nothing has been deleted. Check the provider's console before releasing this row",
			m.ID, m.ResourceID, m.ResourceZone)
	}
	return ""
}

// machineRef is the durable identity the row carries, in the provider's terms.
func machineRef(m *store.Machine) provider.MachineRef {
	ref := provider.MachineRef{Zone: m.ResourceZone, ID: m.ResourceID, Name: m.Name}
	if ref.ID == ref.Name {
		// A provider whose identity is only knowable after creation has its
		// name recorded as its identifier; handing that back as a native id
		// would ask it to look up something it does not have.
		ref.ID = ""
	}
	return ref
}

// machineOwner is the marks this controller stamps on a machine's resource.
func (c *Controller) machineOwner(row *store.Provider, m *store.Machine) provider.Owner {
	fingerprint := m.OwnerFingerprint
	if fingerprint == "" {
		fingerprint = store.NewSecret(12)
	}
	controller := m.OwnerControllerID
	if controller == "" {
		controller = c.controllerID()
	}
	return provider.Owner{
		ControllerID: controller,
		ProviderID:   row.ID,
		MachineID:    m.ID,
		Fingerprint:  fingerprint,
		CreatedAt:    m.CreatedAt,
	}
}

// machineSpec is what to build, including the enrolment payload when the
// provider carries it in the machine's creation metadata rather than pushing it
// into a running guest.
func (c *Controller) machineSpec(ctx context.Context, env *machineEnv, pr *machineProvider, m *store.Machine, owner provider.Owner) (provider.MachineSpec, error) {
	spec := provider.MachineSpec{
		Name:  m.Name,
		Owner: owner,
		Shape: provider.Shape{
			CPUs:      pr.row.MachineCPUs,
			MemoryMB:  pr.row.MachineMemoryMB,
			DiskMB:    pr.row.MachineDiskMB,
			Platform:  pr.row.MachinePlatform,
			Placement: pr.row.Settings,
		},
	}
	if pr.p.Capabilities().Bootstrap != provider.BootstrapMetadata {
		return spec, nil
	}
	// A provider that cannot reach into a running guest gets the payload with
	// the create, which means it is readable by anyone who can read the
	// machine's metadata. The credential in it is a single-use, minutes-long,
	// name-scoped join token and nothing else, which is exactly why that is
	// tolerable.
	payload, err := c.machineBootstrap(ctx, env, pr.row, m)
	if err != nil {
		return spec, err
	}
	spec.Bootstrap = payload
	return spec, nil
}

// recordMachineAddress keeps the address the provider reports, which is what an
// operator needs when a machine boots and never joins.
func (c *Controller) recordMachineAddress(ctx context.Context, m *store.Machine, got provider.Machine) {
	if got.Address == "" || got.Address == m.Address {
		return
	}
	if err := c.st.SetMachineAddress(ctx, m.ID, got.Address); err != nil {
		c.log.Debug("could not record a machine's address", "machine", m.ID, "error", err)
		return
	}
	m.Address = got.Address
}

// ---------------------------------------------------------------------------
// The breaker, and what the problems drawer reads
// ---------------------------------------------------------------------------

// noteProviderFailure counts a machine that failed before it was ever ready,
// and stands the provider down once enough have in a row.
//
// This is what stops a bad template burning fifty machines: three failures is
// enough to tell an unlucky create from a broken one, and the window widens so
// that a provider which is simply down is not hammered while it recovers.
func (c *Controller) noteProviderFailure(ctx context.Context, providerID string, m *store.Machine) {
	if m.ReadyAt != nil {
		// A machine that worked once and failed later says nothing about the
		// provider's ability to build one.
		return
	}
	// Read afresh rather than counting on the pass's copy. Two machines of one
	// provider are stepped at the same time, and the pass's row is shared
	// between them: incrementing it in place would have the second failure
	// overwrite the first as often as it followed it.
	row, err := c.st.GetProvider(ctx, providerID)
	if err != nil {
		c.log.Warn("could not read a provider to record its failure", "provider", providerID, "error", err)
		return
	}
	failures := row.ConsecutiveFailures + 1
	var until *time.Time
	if failures >= breakerThreshold {
		wait := breakerBase << min(failures-breakerThreshold, 4)
		if wait > breakerMax {
			wait = breakerMax
		}
		at := c.Now().Add(wait)
		until = &at
		c.log.Warn("a provider was stood down after failing to build machines",
			"provider", row.Name, "failures", failures, "until", at)
	}
	if err := c.st.SetProviderBreaker(ctx, row.ID, failures, until); err != nil {
		c.log.Warn("could not record a provider's failures", "provider", row.ID, "error", err)
		return
	}
	row.ConsecutiveFailures, row.PausedUntil = failures, until
	c.publishProvider(ctx, row)
}

// noteProviderSuccess clears the breaker. One machine that worked is the whole
// of the evidence needed: the breaker exists to stop a run of failures, not to
// punish a provider for having had one.
func (c *Controller) noteProviderSuccess(ctx context.Context, providerID string) {
	c.clearProviderTrouble(providerID)
	row, err := c.st.GetProvider(ctx, providerID)
	if err != nil || (row.ConsecutiveFailures == 0 && row.PausedUntil == nil) {
		return
	}
	if err := c.st.SetProviderBreaker(ctx, row.ID, 0, nil); err != nil {
		c.log.Warn("could not clear a provider's failures", "provider", row.ID, "error", err)
		return
	}
	row.ConsecutiveFailures, row.PausedUntil = 0, nil
	c.publishProvider(ctx, row)
}

// noteProviderTrouble remembers the last failure a provider gave us, for the
// sentence the problems drawer shows. It is in memory, like the pools' blocked
// reasons, because the next pass re-learns it and it is a fact about now.
func (c *Controller) noteProviderTrouble(providerID string, err error, machineID string, now time.Time) {
	if err == nil {
		return
	}
	t := providerTrouble{Kind: provider.KindOf(err), Detail: err.Error(), At: now, Machine: machineID}
	var pe *provider.Error
	if errors.As(err, &pe) {
		t.Remedy = pe.Remedy
		if pe.Message != "" {
			t.Detail = pe.Message
		}
	}
	c.machines.noteMu.Lock()
	c.machines.trouble[providerID] = t
	c.machines.noteMu.Unlock()
}

func (c *Controller) clearProviderTrouble(providerID string) {
	c.machines.noteMu.Lock()
	delete(c.machines.trouble, providerID)
	c.machines.noteMu.Unlock()
}

func (c *Controller) providerTroubles() map[string]providerTrouble {
	c.machines.noteMu.Lock()
	defer c.machines.noteMu.Unlock()
	out := make(map[string]providerTrouble, len(c.machines.trouble))
	for k, v := range c.machines.trouble {
		out[k] = v
	}
	return out
}

// noteOrphans records the untracked resources one sweep found, which the orphan
// page lists and nothing ever deletes.
func (c *Controller) noteOrphans(providerID string, names []string) {
	c.machines.noteMu.Lock()
	defer c.machines.noteMu.Unlock()
	if len(names) == 0 {
		delete(c.machines.orphans, providerID)
		return
	}
	c.machines.orphans[providerID] = names
}

// ProviderOrphans is the untracked resources the last sweep found, by provider.
func (c *Controller) ProviderOrphans() map[string][]string {
	c.machines.noteMu.Lock()
	defer c.machines.noteMu.Unlock()
	out := make(map[string][]string, len(c.machines.orphans))
	for k, v := range c.machines.orphans {
		out[k] = append([]string(nil), v...)
	}
	return out
}

// unservableProviders names the providers whose machines no pool could ever
// place a runner on: money for nothing, and the one provider fault that looks
// like nothing being wrong at all.
func unservableProviders(providers []*store.Provider, pools []*store.Pool, now time.Time) []string {
	var out []string
	for _, p := range providers {
		if !p.Enabled {
			continue
		}
		synth := providerSynthHost(p, now)
		served := false
		for _, pool := range pools {
			if pool.Enabled && scheduler.HostCanRun(synth, pool, now) {
				served = true
				break
			}
		}
		if !served {
			out = append(out, p.ID)
		}
	}
	return out
}

// providerLabelFor names a provider in a metric or a sentence, falling back to
// the id when the row has gone.
func providerLabelFor(providers []*store.Provider, id string) string {
	for _, p := range providers {
		if p.ID == id {
			return p.Name
		}
	}
	return id
}

// machineLabelsFor renders a machine's labels the way the agent's environment
// file wants them.
func machineLabelsFor(labels store.StringMap) string {
	if len(labels) == 0 {
		return ""
	}
	keys := make([]string, 0, len(labels))
	for k := range labels {
		keys = append(keys, k)
	}
	// Sorted, so that two renderings of one machine's labels are the same
	// bytes: an environment file that reshuffled itself would look like a
	// change every time it was written.
	slices.Sort(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, k+"="+labels[k])
	}
	return strings.Join(parts, ",")
}

package controller

import (
	"slices"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The kill switch has three layers, and what separates them is what each one
// is allowed to stop. These tests are the table in the design, made to fail.

// The operator's switch stops the fleet buying and nothing else. A switch that
// also stopped draining and deleting would strand running machines nobody is
// watching -- which is the opposite of what somebody reaching for a kill switch
// wants.
func TestAPausedProviderCreatesNothingAndStillDrainsAndDeletes(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	ready := h.readyMachine(t, row)
	h.pauseProvider(t, row, "the hypervisor is being patched")
	h.queueWork(t)

	before := len(h.machines())
	h.machinePass(t)
	if got := len(h.machines()); got != before {
		t.Fatalf("a paused provider bought %d more machines", got-before)
	}

	h.beginDrainFor(t, ready)
	m := h.drive(t, ready.ID, store.MachineDeleted, 8)
	if m.DeletedAt == nil {
		t.Fatal("a paused provider would not release a machine; a kill switch that strands machines is not one")
	}
}

// The pause is a row rather than a live setting, because a kill switch a
// restart lifts is not a kill switch.
func TestThePauseSurvivesARestart(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	h.pauseProvider(t, row, "we are over budget this month")

	h.c = h.restart()
	got, err := h.st.GetProvider(h.ctx, row.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if held := h.c.provisioningHeld(got, h.c.Now()); held == "" {
		t.Fatal("a restart lifted the pause")
	}
	h.machinePass(t)
	if len(h.machines()) != 0 {
		t.Fatal("a restarted controller bought a machine from a paused provider")
	}
	if !slices.Contains(h.problemCodes(), "provider.provisioning_paused") {
		t.Fatalf("a paused provider raised %v, want provider.provisioning_paused", h.problemCodes())
	}
}

// Pressing the kill switch changes no setting a connection check would verify,
// so it must not tell the operator the provider "has not been checked since its
// settings changed". That warning turns the public status page degraded, and it
// would clear only after a check they had no reason to run.
func TestPausingACheckedProviderDoesNotClaimItsSettingsChanged(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	if err := h.st.SetProviderChecked(h.ctx, row.ID, time.Now(), ""); err != nil {
		t.Fatalf("SetProviderChecked: %v", err)
	}
	if slices.Contains(h.problemCodes(), "provider.template_unverified") {
		t.Fatalf("a freshly checked provider raised template_unverified: %v", h.problemCodes())
	}

	// updated_at has millisecond resolution; without the gap a pause in the
	// same millisecond as the check would pass for the wrong reason.
	time.Sleep(5 * time.Millisecond)
	h.pauseProvider(t, row, "the hypervisor is being patched")
	if slices.Contains(h.problemCodes(), "provider.template_unverified") {
		t.Fatalf("pausing raised template_unverified: %v", h.problemCodes())
	}

	time.Sleep(5 * time.Millisecond)
	if err := h.st.SetProviderPaused(h.ctx, row.ID, false, ""); err != nil {
		t.Fatalf("SetProviderPaused: %v", err)
	}
	if slices.Contains(h.problemCodes(), "provider.template_unverified") {
		t.Fatalf("resuming raised template_unverified: %v", h.problemCodes())
	}
}

// The same switch in the configuration file, for an operator who wants a
// restart to come back held.
func TestTheConfiguredPauseHoldsEveryProvider(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.c.UpdateConfig(func(c *config.Config) { c.Provider.Paused = true })

	h.machinePass(t)
	if got := len(h.machines()); got != 0 {
		t.Fatalf("provider.paused bought %d machines", got)
	}
}

// The fence is stricter than the kill switch on purpose, and the difference is
// the delete. A fenced database may be a restored copy, so its machine rows may
// describe resources a different, live controller owns -- and destroying
// somebody else's running machine on the strength of a restored row is the
// worst thing this system could do.
func TestAFencedFleetTouchesNoProviderMutationAtAll(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	ready := h.readyMachine(t, row)
	h.beginDrainFor(t, ready)
	h.queueWork(t)

	deletes, creates := h.callsTo("delete"), h.callsTo("create")
	h.fence("restored from a backup taken on Tuesday")
	for range 3 {
		h.machinePass(t)
	}

	if got := h.callsTo("create"); got != creates {
		t.Fatalf("a fenced fleet made %d creates", got-creates)
	}
	if got := h.callsTo("delete"); got != deletes {
		t.Fatalf("a fenced fleet made %d deletes; a restored row may describe another controller's machine", got-deletes)
	}
	// Looking is still allowed, and is the whole reason a fenced fleet is
	// worth running at all: an operator has to be able to see what it would do.
	if h.callsTo("list")+h.callsTo("inspect") == 0 {
		t.Fatal("a fenced fleet stopped observing as well as acting, so nothing can be reviewed before the fence is lifted")
	}
}

// Lifting the fence does not hand the deletes straight back. Every machine has
// to prove its ownership afresh first, because the rows that survived the
// restore are exactly the rows whose resources may belong to somebody else.
func TestLiftingTheFenceMakesEveryMachineProveItselfAgain(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)
	if got := h.machineByID(t, m.ID); got.OwnershipVerifiedAt == nil {
		t.Fatal("a machine that was built and enrolled has no ownership proof to take away")
	}

	h.fence("restored from a backup")
	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatalf("Unfence: %v", err)
	}
	if got := h.machineByID(t, m.ID); got.OwnershipVerifiedAt != nil {
		t.Fatal("lifting the fence left yesterday's ownership proof standing, so a delete could act on it")
	}
	if ok, _ := machineSafeToDelete(h.machineByID(t, m.ID), h.c.Now()); ok {
		t.Fatal("a machine with no fresh proof is offered as safe to delete")
	}
}

// Two controllers each cloning a machine is the expensive failure this design
// exists for. Nothing else in this codebase stops on lease loss, because
// nothing else spends money.
func TestALeaseLostControllerCreatesNothing(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.c.leaseLost.Store(&store.ControllerLease{Holder: "ctl_theother", Host: "elsewhere"})

	h.machinePass(t)
	if got := len(h.machines()); got != 0 {
		t.Fatalf("a controller that has lost the database lease bought %d machines", got)
	}
	if h.callsTo("create") != 0 {
		t.Fatal("a controller that has lost the lease called a provider; two controllers cloning is two invoices")
	}
}

// A provider that has been switched off keeps everything it has and is offered
// nothing new. The distinction matters because the machines it owns are still
// real: disabling a provider must not be a way to lose track of them.
func TestADisabledProviderKeepsItsMachinesAndBuysNoMore(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)

	row.Enabled = false
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}
	h.queueWork(t)
	h.machinePass(t)

	if got := h.machineByID(t, m.ID); got.State != store.MachineReady {
		t.Fatalf("disabling a provider left its ready machine %s; the machine is still rented and still real", got.State)
	}
	if got := len(h.machines()); got != 1 {
		t.Fatalf("a disabled provider bought %d machines", got-1)
	}
}

// The machine loop is not started at all unless providers are switched on.
// Renting machines spends money, and nothing should start doing that because a
// release added the ability to.
func TestNothingIsRentedUntilProvidersAreSwitchedOn(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "linux-x64")
	h.providerRow(t, "lab")
	h.queueWork(t)

	h.machinePass(t)
	if got := len(h.machines()); got != 0 {
		t.Fatalf("providers are off and %d machines were bought", got)
	}
	if got := h.callsTo("allocate"); got != 0 {
		t.Fatal("providers are off and one was called anyway")
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// A restart is the pass where nothing was in memory, and these are the
// instants it can happen at.
//
// The table is the acceptance criterion "controller restart at every operation
// boundary" written out: one row per boundary, each one carrying the machine to
// that exact instant, restarting the controller there, and letting the new one
// carry on. Every row ends on the same two assertions -- one resource per
// machine, and exactly one create per machine at the provider -- because the
// failure every boundary could produce is the same failure: two machines, one
// row, one of them invisible and both of them on the bill.
func TestAMachineSurvivesARestartAtEveryOperationBoundary(t *testing.T) {
	cases := []struct {
		name string
		// reach carries the machine to the boundary and returns its id.
		reach func(t *testing.T, h *harness) string
		// want is where the machine should end up once a fresh controller has
		// had a few passes at it.
		want store.MachineState
	}{{
		// Nothing was created: the identity is written before the call, and
		// this row has none. Retrying costs nothing.
		name: "after the reservation, before anything was allocated",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.fake.SetFailureOnce("allocate", provider.FailureUnreachable, "dial tcp: connection refused")
			h.machinePass(t)
			return h.onlyMachine(t).ID
		},
		want: store.MachineCreating,
	}, {
		// The identity is persisted and the create went out. A new controller
		// holds nothing but the row and has to ask what happened.
		name: "after the create was issued",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.machinePass(t)
			return h.onlyMachine(t).ID
		},
		want: store.MachineBootstrapping,
	}, {
		// The request went out and the answer never came back. This is the one
		// the whole design turns on: retrying it buys a second machine.
		//
		// It stays creating, and that is the right answer: the machine exists,
		// the fleet has adopted it, and it moves on when the provider says it
		// is running. What must not happen is a second create, which is what
		// the shared assertion below is for.
		name: "after a create whose answer was never heard",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.fake.SetAmbiguousAfterWork("create")
			h.machinePass(t)
			h.fake.ClearFailures()
			return h.onlyMachine(t).ID
		},
		want: store.MachineCreating,
	}, {
		// The clone is still running. The handle is the only record of it, and
		// it is on the row rather than in the pass that issued it.
		name: "while the create is still running",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.fake.SetAsync("create", 2)
			h.machinePass(t)
			return h.onlyMachine(t).ID
		},
		want: store.MachineBootstrapping,
	}, {
		name: "after the machine came up and before the agent was installed",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.machinePass(t)
			id := h.onlyMachine(t).ID
			h.drive(t, id, store.MachineBootstrapping, 4)
			return id
		},
		want: store.MachineEnrolling,
	}, {
		// The token was minted and the payload was written. A new controller
		// must not mint a second machine for a guest that is already joining.
		name: "after the agent was installed and before it joined",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.machinePass(t)
			id := h.onlyMachine(t).ID
			h.drive(t, id, store.MachineEnrolling, 6)
			return id
		},
		want: store.MachineEnrolling,
	}, {
		// The agent joined and the link was never written. The token names the
		// machine and the host, so the link is recoverable from the rows alone.
		name: "after the agent joined and before the link was written",
		reach: func(t *testing.T, h *harness) string {
			h.machineFleet(t)
			h.machinePass(t)
			id := h.onlyMachine(t).ID
			m := h.drive(t, id, store.MachineEnrolling, 6)
			h.joinAsMachine(t, m)
			return id
		},
		want: store.MachineReady,
	}, {
		// A delete that was issued cannot be un-issued, and a restart in the
		// middle of one must finish it rather than start again elsewhere.
		name: "after a delete was issued",
		reach: func(t *testing.T, h *harness) string {
			_, row := h.machineFleet(t)
			m := h.readyMachine(t, row)
			h.beginDrainFor(t, m)
			h.machinePass(t)
			return m.ID
		},
		want: store.MachineDeleted,
	}}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			id := tc.reach(t, h)

			// The restart itself: a fresh controller over the same store, with
			// the same provider still holding whatever it was holding.
			h.c = h.restart()

			for range 8 {
				if h.machineByID(t, id).State == tc.want {
					break
				}
				h.pastBackoff(t, id)
				h.machinePass(t)
			}
			m := h.machineByID(t, id)
			if m.State != tc.want {
				t.Fatalf("after the restart the machine is %s, want %s (message: %s, provider error: %s)",
					m.State, tc.want, m.Message, m.ProviderError)
			}
			h.assertOneResourcePerMachine(t)
		})
	}
}

// A create that succeeded after the fleet gave up must not put a machine back
// into service. The row is failed and the resource is reported, because a
// resource that exists and is not being watched is worse than one that is
// simply gone.
func TestALateCreateSuccessDoesNotResurrectAMachineTheFleetGaveUpOn(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetFailure("create", provider.FailureConfig, "the template id in this provider's settings does not exist")

	h.machinePass(t)
	m := h.onlyMachine(t)
	if m.State != store.MachineFailed {
		t.Fatalf("a create refused for a reason only a person can fix left the machine %s, want failed", m.State)
	}

	// The provider comes good, and the resource turns up anyway.
	h.fake.ClearFailures()
	h.fake.PlantOrphan(m.Name, provider.Owner{
		ControllerID: m.OwnerControllerID, ProviderID: m.ProviderID,
		MachineID: m.ID, Fingerprint: m.OwnerFingerprint,
	})
	h.advance(time.Minute)
	h.machinePass(t)

	if got := h.machineByID(t, m.ID); got.State == store.MachineReady {
		t.Fatal("a machine the fleet gave up on came back into service on its own")
	}
}

// A machine that failed for a reason nothing but a person can change is failed
// at once rather than retried five times. There is nothing to wait for, and the
// only thing four more attempts buy is four more minutes before somebody reads
// the reason.
func TestAFailureOnlyAPersonCanFixIsNotRetried(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetFailure("allocate", provider.FailurePermission,
		"the API token is missing VM.Allocate on /vms")

	h.machinePass(t)
	m := h.onlyMachine(t)
	if m.State != store.MachineFailed {
		t.Fatalf("a refused privilege left the machine %s, want failed", m.State)
	}
	if got := h.callsTo("allocate"); got != 1 {
		t.Fatalf("the provider was asked %d times for something it will never allow, want once", got)
	}
}

package controller

import (
	"context"
	"errors"
	"net"
	"strconv"
	"sync"
	"time"

	"github.com/tailscale/tailcat"
)

// privateDialer opens connections to a provider through a `zoomies gateway`
// rather than the network: a hypervisor on a home network has no address this
// controller can route to, and the gateway's Tailcat address is what stands
// in for one. It is the provider-side counterpart of the agent's private
// transport, with the direction reversed -- the controller is the one dialling.
//
// The address is a capability, kept sealed on the provider row and never put
// in an error: what a message names is the provider, and what an operator
// checks is whether the gateway beside the hypervisor is running.
type privateDialer struct {
	client *tailcat.Client
	once   sync.Once
}

// newPrivateDialer validates the address without touching the network. A
// malformed one is refused here, when the row is being built, rather than
// discovered at the first clone.
func newPrivateDialer(address string) (*privateDialer, error) {
	info, err := tailcat.ParseAddr(tailcat.Addr(address))
	if err != nil || info.PresharedKey.IsZero() {
		return nil, errors.New("the private connection address is not a complete Tailcat address; copy it again from the gateway's output")
	}
	client := tailcat.NewClient(tailcat.Addr(address))
	// Upstream diagnostics can quote the address. Only our own messages,
	// which never do, reach the log.
	client.Logf = func(string, ...any) {}
	return &privateDialer{client: client}, nil
}

// DialContext is what a provider's HTTP transport calls. The port is the one
// from the endpoint the operator typed, so the gateway forwards to the same
// service whether or not the host part means anything from here.
func (d *privateDialer) DialContext(ctx context.Context, _, address string) (net.Conn, error) {
	_, portText, err := net.SplitHostPort(address)
	if err != nil {
		return nil, errors.New("private connection: the endpoint has no port; write it as https://pve.example.com:8006")
	}
	port, err := strconv.ParseUint(portText, 10, 16)
	if err != nil {
		return nil, errors.New("private connection: the endpoint's port is not a number")
	}
	dialCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	conn, err := d.client.DialTCPPort(dialCtx, uint16(port))
	if err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		return nil, errors.New("private connection: cannot reach the gateway; check that `zoomies gateway` is running beside the provider and that both sides have outbound internet access")
	}
	return conn, nil
}

// Close releases the userspace network stack. Idempotent, because the cache
// drops a client both when its row changes and when the controller stops.
func (d *privateDialer) Close() {
	d.once.Do(func() { _ = d.client.Close() })
}

package controller

import (
	"context"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/tailscale/tailcat"
)

// capturingFactory keeps the last Config it was asked to build from, which is
// how a test sees what the controller hands a provider without a hypervisor.
type capturingFactory struct {
	sharedFakeFactory
	last provider.Config
}

func (f *capturingFactory) New(_ context.Context, cfg provider.Config) (provider.Provider, error) {
	f.last = cfg
	return f.fake, nil
}

func privateAddress(t *testing.T) string {
	t.Helper()
	identity := tailcat.NewPrivateKey()
	identity.Public.RegionID = 1
	return string(identity.Public.Addr())
}

// A provider on a home network is reached through its gateway, so the client
// built for it has to be given the tunnel to dial through -- and not the
// controller's own HTTP client, which would take the row's certificate
// settings and its private connection out of the picture together.
func TestAProviderWithAPrivateConnectionIsBuiltWithTheTunnelToDialThrough(t *testing.T) {
	h := newHarness(t)
	factory := &capturingFactory{sharedFakeFactory: sharedFakeFactory{fake: h.fake}}
	registry, err := provider.NewRegistry(factory)
	if err != nil {
		t.Fatal(err)
	}
	h.c.providers = registry
	_, row := h.machineFleet(t)

	pr, err := h.c.providerFor(h.ctx, row)
	if err != nil {
		t.Fatalf("direct provider: %v", err)
	}
	if factory.last.DialContext != nil || factory.last.HTTPClient != nil {
		t.Fatal("a direct provider was given a tunnel, or a ready-made client that ignores the row's certificate settings")
	}
	if h.c.ProviderView(row, nil).Connection != "direct" {
		t.Fatal("the view does not say the provider is reached directly")
	}

	sealed, err := h.key.SealString(privateAddress(t))
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetProviderTailcatAddress(h.ctx, row.ID, sealed); err != nil {
		t.Fatal(err)
	}
	row, err = h.st.GetProvider(h.ctx, row.ID)
	if err != nil {
		t.Fatal(err)
	}
	if h.c.ProviderView(row, nil).Connection != "tailcat" {
		t.Fatal("the view does not say the provider is reached privately")
	}
	again, err := h.c.providerFor(h.ctx, row)
	if err != nil {
		t.Fatalf("private provider: %v", err)
	}
	if again == pr {
		t.Fatal("the row changed and the cached client was reused")
	}
	if factory.last.DialContext == nil {
		t.Fatal("a private provider was built without the tunnel to dial through")
	}
	if factory.last.HTTPClient != nil {
		t.Fatal("a ready-made client would bypass the tunnel")
	}
	// An endpoint with no port cannot say which service the gateway should
	// forward to, and the message says so rather than naming the address.
	if _, err := factory.last.DialContext(h.ctx, "tcp", "pve.lan"); err == nil || !strings.Contains(err.Error(), "8006") {
		t.Fatalf("dialling without a port: %v", err)
	}
	h.c.closeProviderTunnels()
}

func TestAPrivateProviderIsRefusedWhenPrivateConnectionsAreOffOrTheAddressIsNotOne(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	garbage, err := h.key.SealString("not-an-address")
	if err != nil {
		t.Fatal(err)
	}
	if err := h.st.SetProviderTailcatAddress(h.ctx, row.ID, garbage); err != nil {
		t.Fatal(err)
	}
	row, _ = h.st.GetProvider(h.ctx, row.ID)
	if _, err := h.c.providerFor(h.ctx, row); err == nil || !strings.Contains(err.Error(), "Tailcat address") || strings.Contains(err.Error(), "not-an-address") {
		t.Fatalf("a malformed address was accepted, or quoted: %v", err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Server.TailcatEnabled = false })
	if _, err := h.c.providerFor(h.ctx, row); err == nil || !strings.Contains(err.Error(), "server.tailcat_enabled") {
		t.Fatalf("private connections off, got: %v", err)
	}
}

package controller

import (
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// ---------------------------------------------------------------------------
// The machine harness
// ---------------------------------------------------------------------------

// machineFleet is the setup every test in these files starts from: providers
// switched on with a ceiling, one provider row that can serve the pool, one
// pool and one queued job. There is deliberately no host: a fleet with nowhere
// to put a runner is the whole reason a machine gets bought.
func (h *harness) machineFleet(t *testing.T) (*store.Pool, *store.Provider) {
	t.Helper()
	h.enableProviders(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	row := h.providerRow(t, "lab")
	h.queueWork(t)
	return pool, row
}

// queueWork puts one job in the queue the way GitHub does, so that the pool's
// demand is the scheduler's own reading rather than something a test asserted.
func (h *harness) queueWork(t *testing.T) {
	t.Helper()
	h.deliverJob(jobEvent{Action: "queued", JobID: time.Now().UnixNano(),
		Labels: []string{"self-hosted", "linux", "x64", "demo"}})
}

// enableProviders turns the machine loop's configuration on with a ceiling, so
// that a test is exercising the fleet rather than the validator's refusal to
// rent anything without one.
func (h *harness) enableProviders(t *testing.T) {
	t.Helper()
	h.c.UpdateConfig(func(c *config.Config) {
		c.Provider.Enabled = true
		c.Provider.MaxMachines = 10
		c.Provider.MaxCreatesInFlight = 10
	})
	h.cfg = h.c.Config()
}

// providerRow writes a provider that offers two docker slots per machine.
func (h *harness) providerRow(t *testing.T, name string) *store.Provider {
	t.Helper()
	p := &store.Provider{
		Kind:               store.ProviderFake,
		Name:               name,
		Endpoint:           "https://" + name + ".test",
		Settings:           store.StringMap{"zone": "zone-a"},
		MachineLabels:      store.StringMap{},
		MachineCapacity:    2,
		MachineBackend:     store.BackendDocker,
		MaxMachines:        5,
		MaxCreatesInFlight: 5,
		IdleTimeout:        store.Duration(15 * time.Minute),
		Enabled:            true,
	}
	if err := h.st.CreateProvider(h.ctx, p); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}
	return p
}

// machinePass runs one machine pass and waits for the provider calls it
// issued, which outlive it. Without the wait a test would be asserting on a
// pass that has claimed the work and not yet done it.
func (h *harness) machinePass(t *testing.T) {
	t.Helper()
	if err := h.c.ReconcileMachines(h.ctx); err != nil {
		t.Fatalf("ReconcileMachines: %v", err)
	}
	h.c.machines.calls.Wait()
}

// machines returns every machine row, oldest first.
func (h *harness) machines() []*store.Machine {
	h.t.Helper()
	ms, _, err := h.st.ListMachines(h.ctx, store.MachineFilter{IncludeDeleted: true}, store.Page{Limit: 100})
	if err != nil {
		h.t.Fatalf("ListMachines: %v", err)
	}
	slices.SortFunc(ms, func(a, b *store.Machine) int { return strings.Compare(a.ID, b.ID) })
	return ms
}

// onlyMachine asserts there is exactly one machine and returns it fresh.
func (h *harness) onlyMachine(t *testing.T) *store.Machine {
	t.Helper()
	ms := h.machines()
	if len(ms) != 1 {
		t.Fatalf("expected exactly one machine, got %d", len(ms))
	}
	return ms[0]
}

// machineByID re-reads one machine, for a test that has to see a column move.
func (h *harness) machineByID(t *testing.T, id string) *store.Machine {
	t.Helper()
	m, err := h.st.GetMachine(h.ctx, id)
	if err != nil {
		t.Fatalf("GetMachine %s: %v", id, err)
	}
	return m
}

// drive runs passes until the machine reaches a state, or gives up saying
// where it actually got to. It is a helper rather than a loop in each test
// because the number of passes a lifecycle takes is an implementation detail --
// what a test means is "let this run".
func (h *harness) drive(t *testing.T, id string, want store.MachineState, passes int) *store.Machine {
	t.Helper()
	var m *store.Machine
	for range passes {
		m = h.machineByID(t, id)
		if m.State == want {
			return m
		}
		// A machine waiting out a backoff is waiting for a clock, and a test
		// has one it can move.
		h.pastBackoff(t, id)
		h.machinePass(t)
	}
	m = h.machineByID(t, id)
	if m.State != want {
		t.Fatalf("machine %s reached %s after %d passes, want %s (message: %s, provider error: %s)",
			id, m.State, passes, want, m.Message, m.ProviderError)
	}
	return m
}

// pastBackoff moves the controller's clock past whatever a machine is waiting
// out, which is the honest way for a test to reach the next attempt: the wait
// is real, and a test that wrote the columns itself would be asserting on its
// own arithmetic rather than on the fleet's.
func (h *harness) pastBackoff(t *testing.T, id string) {
	t.Helper()
	m := h.machineByID(t, id)
	now := h.c.Now()
	if m.NextAttemptAt != nil && m.NextAttemptAt.After(now) {
		h.advance(m.NextAttemptAt.Sub(now) + time.Second)
	}
}

// callsTo counts how many times an operation was made against the fake.
func (h *harness) callsTo(op string) int {
	n := 0
	for _, call := range h.fake.Calls() {
		if call == op || strings.HasPrefix(call, op+" ") {
			n++
		}
	}
	return n
}

// assertOneResourcePerMachine is the invariant every restart test ends on: no
// two live rows share an identity, no two share a name, and the provider was
// asked to create each machine exactly once.
//
// It is assertOneLiveRowPerName's twin, and it is the assertion that catches
// the failure this whole design exists to prevent: one row, two machines, one
// of them invisible and both of them on the bill.
func (h *harness) assertOneResourcePerMachine(t *testing.T) {
	t.Helper()
	seenResource := map[string]string{}
	seenName := map[string]string{}
	for _, m := range h.machines() {
		if m.DeletedAt != nil {
			continue
		}
		if m.ResourceID != "" {
			key := m.ProviderID + "/" + m.ResourceZone + "/" + m.ResourceID
			if was, dup := seenResource[key]; dup {
				t.Errorf("machines %s and %s both name resource %s", was, m.ID, key)
			}
			seenResource[key] = m.ID
		}
		if was, dup := seenName[m.Name]; dup {
			t.Errorf("machines %s and %s are both called %s", was, m.ID, m.Name)
		}
		seenName[m.Name] = m.ID
	}
	// A create ISSUED twice for one identity is not in itself the bug -- a
	// create whose answer was lost and whose resource could not be found twice
	// is deliberately re-issued with the same identity, which is a retry of one
	// machine rather than the purchase of a second. The bug is a second
	// machine, so that is what is counted: the provider must not be holding
	// more machines than the fleet has rows naming one.
	if got := len(h.fake.Machines()); got > len(seenResource) {
		t.Errorf("the provider holds %d machines and the fleet has %d rows naming one; a resource with no row is a machine nobody is watching",
			got, len(seenResource))
	}
}

// ---------------------------------------------------------------------------
// The lifecycle
// ---------------------------------------------------------------------------

// The whole point of the feature, in one test: a pool with work and nowhere to
// put it ends with a machine that has become a host. Every state in between is
// reached by observing the provider rather than by assuming the last call
// worked.
func TestAQueueWithNowhereToRunBuysAMachineAndEnrolsIt(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)

	h.machinePass(t)
	m := h.onlyMachine(t)
	if m.State != store.MachineCreating {
		t.Fatalf("after one pass the machine is %s, want creating: %s", m.State, m.Message)
	}
	if m.ResourceID == "" {
		t.Fatal("the machine has no resource identity; it must be written before anything is created")
	}
	if m.ProviderID != row.ID {
		t.Fatalf("the machine belongs to %s, want %s", m.ProviderID, row.ID)
	}

	m = h.drive(t, m.ID, store.MachineEnrolling, 8)
	if m.JoinTokenID == "" {
		t.Fatal("the machine reached enrolling with no join token; nothing could ever join with it")
	}
	if got := len(h.fake.Bootstraps()); got != 1 {
		t.Fatalf("the guest was bootstrapped %d times, want once", got)
	}

	// The agent inside the guest joins with what it was given.
	h.joinAsMachine(t, m)
	h.machinePass(t)

	m = h.machineByID(t, m.ID)
	if m.State != store.MachineReady {
		t.Fatalf("the machine is %s after its agent joined, want ready: %s", m.State, m.Message)
	}
	if m.HostID == "" {
		t.Fatal("a ready machine with no host: the link is the only thing that grants deletion authority")
	}
	h.assertOneResourcePerMachine(t)
}

// joinAsMachine enrols an agent the way the guest would, with the token that
// machine's payload carried.
func (h *harness) joinAsMachine(t *testing.T, m *store.Machine) {
	t.Helper()
	token := h.tokenFromBootstrap(t, m)
	resp, err := h.c.Join(h.ctx, joinRequest(m.Name, token), "203.0.113.9")
	if err != nil {
		t.Fatalf("joining as machine %s: %v", m.Name, err)
	}
	if resp.HostID == "" {
		t.Fatal("the join returned no host id")
	}
}

// tokenFromBootstrap digs the join token out of the payload the controller
// pushed into the guest, which is the only place the plaintext ever exists.
func (h *harness) tokenFromBootstrap(t *testing.T, m *store.Machine) string {
	t.Helper()
	for _, b := range h.fake.Bootstraps() {
		for _, f := range b.Files {
			if f.Path != machineEnvPath {
				continue
			}
			for line := range strings.SplitSeq(string(f.Content), "\n") {
				name, value, ok := strings.Cut(line, "=")
				if ok && name == "ZOOMIES_AGENT_NAME" && value != m.Name {
					break
				}
				if ok && name == "ZOOMIES_JOIN_TOKEN" {
					return value
				}
			}
		}
	}
	t.Fatalf("no join token was written into machine %s's guest", m.Name)
	return ""
}

// A machine is bought once for a shortfall, not once per pass. A reservation
// that did not count as capacity would have every pass buy the queue again,
// and the fleet would notice on the invoice rather than on the page.
func TestASecondPassBuysNothingWhileTheFirstMachineIsStillComing(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)

	for range 3 {
		h.machinePass(t)
	}
	if got := len(h.machines()); got != 1 {
		t.Fatalf("three passes bought %d machines for one shortfall, want 1", got)
	}
	h.assertOneResourcePerMachine(t)
}

// A create that takes minutes is the normal case, not the exception. The pass
// that finds one already under way must poll it, never start another.
func TestASlowCreateDoesNotStartASecondOne(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetAsync("create", 5)

	for range 5 {
		h.machinePass(t)
	}
	if got := h.callsTo("create"); got != 1 {
		t.Fatalf("the provider was asked to create %d times while one create was still running, want 1", got)
	}
	m := h.onlyMachine(t)
	if m.State != store.MachineCreating {
		t.Fatalf("the machine is %s while its create is still running, want creating", m.State)
	}
	h.assertOneResourcePerMachine(t)
}

// The machine loop must never be able to hold up the scheduling pass. A
// hypervisor that accepts a connection and answers in four minutes would
// otherwise stop every pool placing runners for four minutes, which is the
// argument that moved capacity-demand delivery out of the pass as well.
func TestASlowProviderDoesNotHoldTheReconcilePass(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.fake.SetDelay("allocate", 2*time.Second)

	done := make(chan struct{})
	go func() {
		defer close(done)
		_ = h.c.ReconcileMachines(h.ctx)
	}()
	defer func() {
		<-done
		h.c.machines.calls.Wait()
	}()

	started := time.Now()
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if took := time.Since(started); took > time.Second {
		t.Fatalf("a scheduling pass took %s while a provider call was in flight; the machine loop is holding reconcileMu", took)
	}
}

// Two passes running at once must not be able to exceed the create budget
// between them. The claim is in the database rather than in memory precisely so
// that the answer does not depend on which goroutine read first.
func TestConcurrentMachinePassesNeverExceedTheCreateLimit(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	row.MaxCreatesInFlight = 1
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}

	done := make(chan struct{}, 2)
	for range 2 {
		go func() {
			defer func() { done <- struct{}{} }()
			_ = h.c.ReconcileMachines(h.ctx)
		}()
	}
	<-done
	<-done
	h.c.machines.calls.Wait()

	if got := len(h.machines()); got > 1 {
		t.Fatalf("two concurrent passes bought %d machines against a limit of one in flight", got)
	}
	h.assertOneResourcePerMachine(t)
}

// A provider that is full says so and stands down, and -- the half that matters
// -- keeps draining and deleting while it does. A kill switch that also stopped
// those would strand running machines nobody is watching.
func TestAProviderOutOfCapacitySaysSoAndStandsDown(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	h.fake.SetFailure("create", provider.FailureQuota, "no capacity for another machine: 12 of 12 in use")

	h.machinePass(t)
	m := h.onlyMachine(t)
	if m.ProviderError == "" {
		t.Fatal("a refused create recorded nothing on the machine")
	}
	if !slices.Contains(h.problemCodes(), "provider.quota_exhausted") {
		t.Fatalf("a provider that is full raised %v, want provider.quota_exhausted", h.problemCodes())
	}
	// Jobs are queued, so this is an outage rather than a note.
	if got := h.problem(t, "provider.quota_exhausted").Severity; got != config.SeverityError {
		t.Fatalf("with jobs queued the entry is %s, want error", got)
	}

	// And the drain half still runs: a machine that is already ready is
	// released even while the provider refuses new ones.
	h.fake.ClearFailures()
	ready := h.readyMachine(t, row)
	h.pauseProvider(t, row, "full")
	h.beginDrainFor(t, ready)
	h.machinePass(t)
	if got := h.machineByID(t, ready.ID); got.State != store.MachineDeleting && got.State != store.MachineDeleted {
		t.Fatalf("a draining machine on a paused provider is %s; drains and deletes must never be held", got.State)
	}
}

// A bootstrap that fails says what the guest said, on the guest's own column.
// Two systems complain about a machine -- the hypervisor and the thing inside
// it -- and an operator reading one error has to know which half to go to.
func TestABootstrapThatFailsSaysWhatTheGuestSaid(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	h.machinePass(t)
	m := h.onlyMachine(t)
	m = h.drive(t, m.ID, store.MachineBootstrapping, 6)

	h.fake.SetFailure("bootstrap", provider.FailureRefused, "dpkg: zoomies-agent is not installed in this template")
	h.machinePass(t)

	m = h.machineByID(t, m.ID)
	if !strings.Contains(m.ProviderError+m.BootstrapError, "not installed in this template") {
		t.Fatalf("the guest's own words did not reach the machine row: provider=%q bootstrap=%q",
			m.ProviderError, m.BootstrapError)
	}
	if m.State == store.MachineDeleted {
		t.Fatal("a machine whose bootstrap failed was removed; the resource is still running and still being paid for")
	}
}

// Three machines that never reach ready stand the provider down. This is what
// stops a bad template burning fifty machines while nobody is looking.
func TestThreeFailedBootstrapsStandTheProviderDown(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	h.fake.SetFailure("allocate", provider.FailureUnreachable, "dial tcp: connection refused")

	for range breakerThreshold {
		h.machinePass(t)
		for _, m := range h.machines() {
			h.pastBackoff(t, m.ID)
		}
	}
	got, err := h.st.GetProvider(h.ctx, row.ID)
	if err != nil {
		t.Fatalf("GetProvider: %v", err)
	}
	if got.ConsecutiveFailures < breakerThreshold {
		t.Fatalf("the provider recorded %d failures in a row, want at least %d", got.ConsecutiveFailures, breakerThreshold)
	}
	if got.PausedUntil == nil {
		t.Fatal("three failures in a row did not stand the provider down; a bad template would burn machines until somebody noticed")
	}
	// A second before the stand-down expires, nothing may be bought from it.
	if held := h.c.provisioningHeld(got, got.PausedUntil.Add(-time.Second)); held == "" {
		t.Fatal("a stood-down provider is not held, so the next pass buys another machine")
	}
}

// A delete is finished when the provider cannot find the resource, and not
// before. A 200 from a delete call is not evidence: a fleet that took it as one
// would stop counting a machine that is still running and still being billed.
func TestADeleteIsNotCompleteUntilAnInspectCannotFindIt(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)
	h.beginDrainFor(t, m)

	m = h.drive(t, m.ID, store.MachineDeleted, 8)
	if m.DeletedAt == nil {
		t.Fatal("a deleted machine has no confirmation stamp; only an inspect that could not find the resource writes one")
	}
	if h.callsTo("inspect") == 0 {
		t.Fatal("the machine was recorded deleted without the provider being asked whether it was gone")
	}
	for _, got := range h.fake.Machines() {
		if got.Ref.Name == m.Name {
			t.Fatalf("machine %s is recorded deleted and the provider still holds it", m.Name)
		}
	}
}

// readyMachine drives one machine all the way to ready, so that the tests about
// the second half of a machine's life do not each repeat the first half.
func (h *harness) readyMachine(t *testing.T, row *store.Provider) *store.Machine {
	t.Helper()
	h.machinePass(t)
	var m *store.Machine
	for _, got := range h.machines() {
		if got.ProviderID == row.ID && got.State != store.MachineDeleted {
			m = got
		}
	}
	if m == nil {
		t.Fatal("no machine was bought")
	}
	m = h.drive(t, m.ID, store.MachineEnrolling, 8)
	h.joinAsMachine(t, m)
	h.machinePass(t)
	return h.drive(t, m.ID, store.MachineReady, 3)
}

// beginDrainFor starts a drain the way a scale-down decision would.
func (h *harness) beginDrainFor(t *testing.T, m *store.Machine) {
	t.Helper()
	if _, err := h.st.TransitionMachine(h.ctx, m.ID, store.MachineDraining, "the test asked for it"); err != nil {
		t.Fatalf("TransitionMachine(draining): %v", err)
	}
}

// pauseProvider presses the operator's kill switch.
func (h *harness) pauseProvider(t *testing.T, row *store.Provider, reason string) {
	t.Helper()
	if err := h.st.SetProviderPaused(h.ctx, row.ID, true, reason); err != nil {
		t.Fatalf("SetProviderPaused: %v", err)
	}
}

// A machine with runners on it is not released, however idle the fleet thinks
// it is. The drain waits for the work, which is the difference between scaling
// down and killing somebody's build.
func TestADrainWaitsForTheRunnersOnTheMachine(t *testing.T) {
	h := newHarness(t)
	pool, row := h.machineFleet(t)
	m := h.readyMachine(t, row)

	host, err := h.st.GetHost(h.ctx, m.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	h.seedRunner(t, pool, host, store.RunnerBusy)
	h.beginDrainFor(t, m)

	h.machinePass(t)
	if got := h.machineByID(t, m.ID); got.State != store.MachineDraining {
		t.Fatalf("a machine running a job is %s, want draining until the job finishes", got.State)
	}
	if h.callsTo("delete") != 0 {
		t.Fatal("a machine still running a job was deleted")
	}
}

// A provider kind this build has no driver for is refused with a sentence
// naming it, rather than being discovered inside the first create.
func TestAProviderThisBuildCannotMakeSaysSoRatherThanFailingLater(t *testing.T) {
	h := newHarness(t)
	h.enableProviders(t)
	row := &store.Provider{
		Kind: store.ProviderProxmox, Name: "pve", Endpoint: "https://pve.test:8006",
		MachineCapacity: 2, MachineBackend: store.BackendDocker,
		MaxMachines: 1, MaxCreatesInFlight: 1, Enabled: true,
	}
	if err := h.st.CreateProvider(h.ctx, row); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}

	h.machinePass(t)
	if !slices.Contains(h.problemCodes(), "provider.contract_unsupported") {
		t.Fatalf("a provider this build cannot make raised %v, want provider.contract_unsupported", h.problemCodes())
	}
}

// A provider whose machines no pool could ever use is money for nothing, and it
// is the one provider fault that looks exactly like nothing being wrong.
func TestAProviderNoPoolCouldUseSaysSo(t *testing.T) {
	h := newHarness(t)
	h.enableProviders(t)
	inst := h.installation()
	h.pool(inst, "linux-x64")
	row := h.providerRow(t, "lab")
	row.MachineBackend = store.BackendProcess
	row.MachineLabels = store.StringMap{"class": "gpu"}
	if err := h.st.UpdateProvider(h.ctx, row); err != nil {
		t.Fatalf("UpdateProvider: %v", err)
	}

	h.machinePass(t)
	if !slices.Contains(h.problemCodes(), "provider.unservable") {
		t.Fatalf("an unservable provider raised %v, want provider.unservable", h.problemCodes())
	}
}

// Every machine frame carries the resource's GET shape, because the UI drops it
// straight into its cache. A store row would repaint the machine with no
// provider name, no host name and no timeline.
func TestAMachineFrameCarriesTheShapeTheAPIReturns(t *testing.T) {
	h := newHarness(t)
	h.machineFleet(t)
	sub := h.listen(events.KindMachineUpdated)

	h.machinePass(t)
	frame := nextOfKind(t, sub, events.KindMachineUpdated)
	for _, field := range []string{"id", "provider_id", "provider_name", "name", "state", "timeline", "safe_to_delete"} {
		if _, ok := frame[field]; !ok {
			t.Errorf("a machine.updated frame has no %q; it is not the shape GET /machines/{id} returns", field)
		}
	}
	if _, leaked := frame["owner_fingerprint"]; leaked {
		t.Error("a machine frame carries the ownership fingerprint, which is the mark a delete is checked against")
	}
}

// A drain is an intent, not an act. Work that comes back before the delete
// starts takes the machine back: nothing has been deleted, its host is merely
// cordoned, and uncordoning costs nothing where building another costs minutes.
func TestWorkComingBackTakesADrainingMachineBack(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)
	h.beginDrainFor(t, m)
	// A drain cordons the host first, which is what puts the pool back to
	// having nowhere to run: without that the fleet is not short of anything
	// and there is nothing for the machine to come back for.
	if err := h.st.SetHostCordoned(h.ctx, m.HostID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}

	h.queueWork(t)
	h.machinePass(t)

	got := h.machineByID(t, m.ID)
	if got.State != store.MachineReady {
		t.Fatalf("a draining machine with work back for its pools is %s, want ready", got.State)
	}
	if len(h.machines()) != 1 {
		t.Fatalf("the fleet bought %d machines rather than taking back the one it was releasing", len(h.machines()))
	}
	host, err := h.st.GetHost(h.ctx, got.HostID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if host.Cordoned {
		t.Fatal("the machine came back into service with its host still cordoned, so nothing can be placed on it")
	}
}

// A delete that has not confirmed is a resource somebody may still be paying
// for, so it is said out loud rather than assumed. Silence here is how a fleet
// stops counting a machine that is still running.
func TestADeleteThatHasNotConfirmedIsReported(t *testing.T) {
	h := newHarness(t)
	_, row := h.machineFleet(t)
	m := h.readyMachine(t, row)
	h.beginDrainFor(t, m)
	h.fake.SetFailure("delete", provider.FailureUnreachable, "dial tcp: i/o timeout")

	h.machinePass(t)
	if got := h.machineByID(t, m.ID); got.State != store.MachineDeleting {
		t.Fatalf("a machine whose delete could not be issued is %s, want deleting", got.State)
	}
	h.advance(h.cfg.Provider.DeleteTimeout + time.Minute)

	if !slices.Contains(h.problemCodes(), "provider.delete_pending") {
		t.Fatalf("a delete that has not confirmed raised %v, want provider.delete_pending", h.problemCodes())
	}
}

// The demo fixture's provider is never acted on, however the fleet is
// configured.
//
// The fixture is a Proxmox cluster at an address that does not resolve, so an
// instance seeded for a demo and then switched on would spend every pass
// dialling it: a provider nobody configured in the problems drawer, DNS
// failures in the log, and two fictional machines counted against the fleet's
// ceiling. It is the same reason the credential prober and the registration
// reaper skip the fixtures they would otherwise reach out on behalf of, and it
// is worth a test because the thing that would break it -- a second place that
// lists providers -- looks harmless.
func TestTheDemoProvidersFixtureIsNeverRentedFrom(t *testing.T) {
	h := newHarness(t)
	h.enableProviders(t)
	inst := h.installation()
	h.pool(inst, "linux-x64")

	demo := &store.Provider{
		ID:                 "prv_demofixture",
		Kind:               store.ProviderFake,
		Name:               "demo-pve",
		Endpoint:           "https://pve.acme.example:8006",
		Settings:           store.StringMap{"zone": "zone-a"},
		MachineLabels:      store.StringMap{},
		MachineCapacity:    2,
		MachineBackend:     store.BackendDocker,
		MaxMachines:        5,
		MaxCreatesInFlight: 5,
		IdleTimeout:        store.Duration(15 * time.Minute),
		Enabled:            true,
	}
	if err := h.st.CreateProvider(h.ctx, demo); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}
	h.queueWork(t)

	for range 3 {
		h.machinePass(t)
	}

	if got := h.callsTo("allocate"); got != 0 {
		t.Errorf("the demo provider was asked to allocate %d times", got)
	}
	if got := h.callsTo("create"); got != 0 {
		t.Errorf("the demo provider was asked to create %d times", got)
	}
	if ms := h.machines(); len(ms) != 0 {
		for _, m := range ms {
			t.Errorf("a machine was planned against the demo fixture: %s on %s, %s", m.ID, m.ProviderID, m.State)
		}
	}

	// And a real provider beside it is rented from as usual, so the skip is a
	// skip rather than the machine loop having stopped.
	lab := h.providerRow(t, "lab")
	h.machinePass(t)
	ms := h.machines()
	if len(ms) != 1 {
		t.Fatalf("expected the real provider to get one machine, got %d", len(ms))
	}
	if ms[0].ProviderID != lab.ID {
		t.Errorf("the machine was rented from %s, want the real provider %s", ms[0].ProviderID, lab.ID)
	}
}

// A resource is not ours because our row points at its identifier.
//
// The name is the primary ownership mark -- provider.MachineRef says so, and it
// is the one thing a cluster-wide sweep can filter on without reading every
// resource's config -- so it has to be agreed before anything else is, and
// especially before the rule that an unmarked resource is nobody's evidence of
// a second fleet. An identifier is recycled; a name is not.
func TestOwnershipIsRefusedOnTheNameBeforeItIsExcusedOnMissingMarks(t *testing.T) {
	h := newHarness(t)
	mine := &store.Machine{
		ID: "mach_mine", ProviderID: "prv_lab", Name: "zoomies-mach-mine",
		ResourceZone: "zone-a", ResourceID: "150",
		OwnerControllerID: h.c.controllerID(), OwnerFingerprint: "ours",
	}
	ref := func(name string) provider.MachineRef {
		return provider.MachineRef{Zone: "zone-a", ID: "150", Name: name}
	}
	ours := provider.Owner{
		ControllerID: h.c.controllerID(), ProviderID: "prv_lab",
		MachineID: "mach_mine", Fingerprint: "ours",
	}

	for _, tc := range []struct {
		name     string
		got      provider.Machine
		complain bool
	}{
		{
			// The accident this exists to catch: our guest destroyed in the
			// console, its identifier reused by another tool. It carries no
			// marks, because whoever made it never heard of us.
			name:     "unmarked, and called something else",
			got:      provider.Machine{Ref: ref("db-primary")},
			complain: true,
		},
		{
			// A provider that cannot write marks leaves every resource like
			// this, and the store is then the only record of who made it.
			name: "unmarked, but called what we called ours",
			got:  provider.Machine{Ref: ref("zoomies-mach-mine")},
		},
		{
			// Between the create and the name being written there is nothing
			// to compare, and a machine still being built must not be
			// quarantined for it.
			name: "unmarked, and not yet named",
			got:  provider.Machine{Ref: ref("")},
		},
		{
			name: "ours, and agreed on every fact",
			got:  provider.Machine{Ref: ref("zoomies-mach-mine"), Owner: ours},
		},
		{
			// Marked or not, a disagreeing name is a disagreeing name.
			name:     "marked as ours, but called something else",
			got:      provider.Machine{Ref: ref("db-primary"), Owner: ours},
			complain: true,
		},
		{
			name: "marked for another machine",
			got: provider.Machine{Ref: ref("zoomies-mach-mine"), Owner: provider.Owner{
				ControllerID: h.c.controllerID(), ProviderID: "prv_lab",
				MachineID: "mach_theirs", Fingerprint: "ours",
			}},
			complain: true,
		},
		{
			name: "marked by another controller",
			got: provider.Machine{Ref: ref("zoomies-mach-mine"), Owner: provider.Owner{
				ControllerID: "ctl_somebodyelse", ProviderID: "prv_lab",
				MachineID: "mach_mine", Fingerprint: "theirs",
			}},
			complain: true,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := h.c.ownershipComplaint(mine, tc.got)
			switch {
			case tc.complain && got == "":
				t.Errorf("%s was accepted as ours; a delete on it would have been authorised", tc.name)
			case !tc.complain && got != "":
				t.Errorf("%s was refused: %s", tc.name, got)
			}
			if tc.complain && got != "" && !strings.Contains(got, "Nothing has been deleted") {
				t.Errorf("a refusal does not say nothing was deleted, which is the sentence a person needs: %s", got)
			}
		})
	}
}

package controller

import (
	"context"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/collectors"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// collectTimeout bounds the database work one scrape may do. Prometheus
// scrapes on a schedule and does not wait patiently; a slow query must fail
// the scrape rather than pile requests up.
const collectTimeout = 5 * time.Second

// metrics holds the collectors the API serves at /metrics.
//
// The counters and histograms are updated where the events happen. The gauges
// are not stored at all: they are read from the database at scrape time by
// fleetCollector, so they cannot drift from the fleet the way a cached counter
// would after a restart.
type metrics struct {
	reg *prometheus.Registry

	jobsTotal                                                                                    *prometheus.CounterVec
	jobsRunnerLost                                                                               *prometheus.CounterVec
	jobReruns                                                                                    *prometheus.CounterVec
	jobFailures                                                                                  *prometheus.CounterVec
	runnerStartFailures                                                                          *prometheus.CounterVec
	queueWait                                                                                    prometheus.Histogram
	jobDuration                                                                                  prometheus.Histogram
	startupWait, dindReady                                                                       *prometheus.HistogramVec
	queuedToCreate, createToContainer, containerToRegistered, registeredToReady, queuedToStarted *prometheus.HistogramVec
	scalingEvents                                                                                *prometheus.CounterVec
	registrationsDeferred                                                                        *prometheus.CounterVec
	webhookDeliveries                                                                            *prometheus.CounterVec
	githubRequests                                                                               *prometheus.CounterVec
	reconcileDuration                                                                            prometheus.Histogram
	storeWriteWait                                                                               prometheus.Histogram
	storeWriteHeld                                                                               prometheus.Histogram
	reconcileErrors                                                                              prometheus.Counter
	cleanups                                                                                     *prometheus.CounterVec
	schedulingLatency, cleanupDuration                                                           *prometheus.HistogramVec
	pollsShed                                                                                    prometheus.Counter
	agentLimited                                                                                 *prometheus.CounterVec
	logRelayDropped                                                                              prometheus.Counter
	buildInfo                                                                                    *prometheus.GaugeVec
	providerOperations                                                                           *prometheus.CounterVec
	providerOperationSeconds                                                                     *prometheus.HistogramVec
	runtimeFailures                                                                              *prometheus.CounterVec
	imagePullFailures                                                                            *prometheus.CounterVec
	imagePrewarms                                                                                *prometheus.CounterVec
	imagePrewarmDuration                                                                         *prometheus.HistogramVec
	elasticCPUDecisions                                                                          *prometheus.CounterVec
	elasticCPUFactor                                                                             *prometheus.HistogramVec
}

// UnmatchedPool is the `pool` label for work no pool here claims.
//
// A literal rather than an empty string, because Prometheus has no notion of an
// absent label value and a blank one is indistinguishable from a bug. A real
// pool named `unmatched` would merge with it; that is a price worth naming in
// the docs rather than designing around.
const UnmatchedPool = "unmatched"

// poolLabel is the `pool` label value for a pool id, and it is the only place
// that decides what one looks like.
//
// Names, not ids. Every other pool-labelled metric uses the name, and
// zoomies_jobs_total used the id -- so a PromQL query joining a pool's job
// count against its runner count on `pool` silently matched nothing, which is
// the worst kind of wrong for a dashboard.
func (c *Controller) poolLabel(id string) string {
	if id == "" {
		return UnmatchedPool
	}
	if p, err := c.st.GetPool(context.Background(), id); err == nil && p.Name != "" {
		return p.Name
	}
	// A pool deleted between the job finishing and this call still has to be
	// counted somewhere, and its id is the only name left.
	return id
}

func newMetrics(c *Controller) *metrics {
	m := &metrics{
		reg: prometheus.NewRegistry(),
		jobsTotal: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_jobs_total",
			Help: "Workflow jobs Zoomies has seen complete, by pool and conclusion.",
		}, []string{"pool", "conclusion"}),
		// A runner the scheduler had already chosen a host for, and did not
		// create, because the installation was at its credential-minting
		// limit. It counts work deferred rather than work failed: the demand
		// stands and a later pass takes it. Without it the limit is invisible
		// -- the pool reports jobs waiting, an operator adds hosts, and the
		// hosts do not help, because hosts were never what ran out.
		registrationsDeferred: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_registrations_deferred_total",
			Help: "Runner creations held back by scheduler.registration_concurrency, by installation. Demand is retained and retried on a later pass.",
		}, []string{"installation"}),
		jobsRunnerLost: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_jobs_runner_lost_total",
			Help: "Jobs whose runner stopped before GitHub reported the job over, by pool. These are the fleet's failures rather than the workflows'.",
		}, []string{"pool"}),
		// Who asked, not whether it worked: a re-run this fleet decided on is
		// spending somebody's GitHub minutes, and an operator turning the
		// setting on wants to see how often it fires before they trust it.
		jobReruns: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_job_reruns_total",
			Help: "Re-runs Zoomies has asked GitHub for, by pool and who asked. trigger is operator for the button on a job and fleet_fault for scheduler.auto_rerun.",
		}, []string{"pool", "trigger"}),
		// The same failures as jobs_runner_lost, split by category, and kept
		// beside it rather than replacing it: an operator whose alert fires on
		// the old series should not have it disappear under them on an
		// upgrade. Sum this one by pool and the two agree.
		jobFailures: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_job_failures_total",
			Help: "Job failures by whose they are and why. domain is fleet or workflow; fault is the category, and is empty for a workflow's own failure. Alert on the fleet domain -- a rise there is this deployment, not somebody's tests.",
		}, []string{"pool", "domain", "fault"}),
		// Runner starts that failed, which reach no job at all: the job they
		// were meant for stays queued. A pool climbing here with a queue that
		// never moves is the fleet failing without a single failed job to show
		// for it, which is the blind spot this exists to cover.
		runnerStartFailures: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_runner_start_failures_total",
			Help: "Runners that failed before they could take a job, by pool and category.",
		}, []string{"pool", "fault"}),
		queueWait: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name: "zoomies_job_queue_wait_seconds",
			Help: "How long jobs waited between being queued and a runner picking them up.",
			// From "a runner was already idle" to "somebody should look at
			// this": one second to an hour.
			Buckets: []float64{1, 5, 10, 30, 60, 120, 300, 600, 1800, 3600},
		}),
		jobDuration: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name:    "zoomies_job_duration_seconds",
			Help:    "How long jobs took to run once they started.",
			Buckets: []float64{10, 30, 60, 300, 600, 1800, 3600, 7200, 21600},
		}),
		queuedToCreate:        startupHistogram("zoomies_runner_queued_to_create_seconds", "Time from a queued job to runner creation."),
		schedulingLatency:     startupHistogram("zoomies_runner_eligible_to_create_task_seconds", "Time from observed job eligibility to its runner's first create task delivery. Excludes prewarmed runners and unobserved timestamps."),
		cleanupDuration:       startupHistogram("zoomies_runner_cleanup_duration_seconds", "Time from runner finish to confirmed host and GitHub removal, including retention. Excludes missing confirmations."),
		startupWait:           startupHistogram("zoomies_runner_startup_queue_seconds", "Time waiting for the host startup admission slot."),
		dindReady:             startupHistogram("zoomies_runner_dind_ready_seconds", "Time creating and awaiting a healthy Docker sidecar, excluding its image pull."),
		createToContainer:     startupHistogram("zoomies_runner_create_to_container_started_seconds", "Time from runner creation to its container starting."),
		containerToRegistered: startupHistogram("zoomies_runner_container_started_to_registered_seconds", "Time from container start to GitHub registration."),
		registeredToReady:     startupHistogram("zoomies_runner_registered_to_ready_seconds", "Time from registration to the runner becoming idle or busy."),
		queuedToStarted:       startupHistogram("zoomies_runner_queued_to_job_started_seconds", "Total time from queueing to job start."),
		scalingEvents: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_scaling_events_total",
			Help: "Scheduler decisions that changed a pool's size, by direction.",
		}, []string{"pool", "direction"}),
		webhookDeliveries: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_webhook_deliveries_total",
			Help: "Inbound webhook deliveries by outcome; a rising rejected count means a secret mismatch or a prober.",
		}, []string{"status"}),
		githubRequests: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_github_api_requests_total",
			Help: "GitHub API calls by installation and outcome.",
		}, []string{"installation", "result"}),
		// The single database writer is the design, and the queue behind it is
		// where a busy instance slows down first: every heartbeat, webhook,
		// scheduling pass and API write waits its turn there. The two halves
		// are kept apart because they point at different fixes -- a long wait
		// says too much is writing, a long hold says one write is too slow --
		// and the buckets reach the ten seconds SQLite's busy timeout allows,
		// which is also how long GitHub waits for a webhook to be answered.
		storeWriteWait: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name:    "zoomies_store_write_wait_seconds",
			Help:    "How long a database write waited for the single writer before it could start.",
			Buckets: []float64{.0005, .001, .005, .01, .05, .1, .5, 1, 2.5, 5, 10},
		}),
		storeWriteHeld: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name:    "zoomies_store_write_held_seconds",
			Help:    "How long a database write then held the single writer, every other write waiting behind it.",
			Buckets: []float64{.0005, .001, .005, .01, .05, .1, .5, 1, 2.5, 5, 10},
		}),
		reconcileDuration: prometheus.NewHistogram(prometheus.HistogramOpts{
			Name:    "zoomies_reconcile_duration_seconds",
			Help:    "How long one reconcile pass took, including the GitHub calls it made.",
			Buckets: []float64{.01, .05, .1, .25, .5, 1, 2.5, 5, 10, 30},
		}),
		// A pass that failed observes no duration, so the histogram's count is
		// the number of passes that *worked* and this is the rest. Without it a
		// controller whose every pass fails looks like one that is simply not
		// busy: the duration series goes quiet either way.
		reconcileErrors: prometheus.NewCounter(prometheus.CounterOpts{
			Name: "zoomies_reconcile_errors_total",
			Help: "Reconcile passes that failed. The loop carries on, so a rising count is a fleet deciding nothing while looking idle.",
		}),
		// Taking a runner away is the half of the lifecycle that leaves
		// something behind when it goes wrong, and it goes wrong on the host
		// rather than in the fleet -- so it is invisible in every other series
		// here, which count what the fleet decided rather than what the host
		// managed.
		cleanups: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_runner_cleanups_total",
			Help: "Attempts to take a runner off its host, by outcome: succeeded, or failed and recorded on the row.",
		}, []string{"outcome"}),
		// A shed poll is the only sign the controller is holding more agent
		// connections than it wants to: the fleet keeps working, each host
		// just hears about its tasks a little later, so nothing else here
		// moves.
		pollsShed: prometheus.NewCounter(prometheus.CounterOpts{
			Name: "zoomies_agent_polls_shed_total",
			Help: "Task polls answered with a backoff because the controller was holding too many at once.",
		}),
		// One series per limit rather than per host: a host id is unbounded
		// cardinality, and the log line that goes with each refusal names it.
		agentLimited: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_agent_requests_limited_total",
			Help: "Agent requests refused or cut short by a per-host limit, by which limit.",
		}, []string{"limit"}),
		logRelayDropped: prometheus.NewCounter(prometheus.CounterOpts{
			Name: "zoomies_log_relay_dropped_bytes_total",
			Help: "Relayed runner output dropped because a stream went over its byte budget.",
		}),
		buildInfo: prometheus.NewGaugeVec(prometheus.GaugeOpts{
			Name: "zoomies_build_info",
			Help: "Always 1; the version and commit are in the labels.",
		}, []string{"version", "commit"}),
		// An ambiguous outcome is its own label value rather than a failure,
		// because it is the one that means something different: a create that
		// failed costs nothing and a create whose answer was lost may already
		// be a machine somebody is paying for.
		providerOperations: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_provider_operations_total",
			Help: "Provider operations by kind and outcome: ok, ambiguous, quota, unreachable or refused.",
		}, []string{"kind", "outcome"}),
		providerOperationSeconds: prometheus.NewHistogramVec(prometheus.HistogramOpts{
			Name: "zoomies_provider_operation_seconds",
			Help: "How long one provider request took. It measures the request, not the clone it starts.",
			// From "a cached answer" to "this hypervisor has stopped
			// answering": a tenth of a second to five minutes.
			Buckets: []float64{.1, .5, 1, 2.5, 5, 10, 30, 60, 120, 300},
		}, []string{"kind"}),
		runtimeFailures: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_host_runtime_failures_total",
			Help: "Container-runtime failures agents reported, each one opening or extending a cooldown on new starts, by kind: unavailable or timeout.",
		}, []string{"kind"}),
		imagePullFailures: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_image_pull_failures_total",
			Help: "Runner starts and prewarms that failed because the pool's image could not be made ready on the host, by pool and kind: start or prewarm.",
		}, []string{"pool", "kind"}),
		imagePrewarms: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_image_prewarms_total",
			Help: "Background image preparations by pool, backend and outcome: prepared, cache_hit, failed or unknown for a successful older agent.",
		}, []string{"pool", "backend", "outcome"}),
		imagePrewarmDuration: prometheus.NewHistogramVec(prometheus.HistogramOpts{
			Name:    "zoomies_image_prewarm_duration_seconds",
			Help:    "Time an agent spent satisfying background image preparation, including local metadata cache hits.",
			Buckets: []float64{.001, .01, .1, .5, 1, 2.5, 5, 10, 30, 60, 120, 300, 600, 900},
		}, []string{"pool", "backend", "outcome"}),
		elasticCPUDecisions: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "zoomies_elastic_cpu_decisions_total",
			Help: "Elastic CPU decisions by pool, policy mode and outcome. Observe mode records the same plan without changing quotas.",
		}, []string{"pool", "mode", "outcome"}),
		elasticCPUFactor: prometheus.NewHistogramVec(prometheus.HistogramOpts{
			Name:    "zoomies_elastic_cpu_target_factor",
			Help:    "Planned CPU target divided by the runner's guaranteed CPU, by pool and policy mode.",
			Buckets: []float64{1, 1.25, 1.5, 2, 3, 4, 6, 8},
		}, []string{"pool", "mode"}),
	}
	m.buildInfo.WithLabelValues(version.Version, version.Commit).Set(1)

	m.reg.MustRegister(
		m.jobsTotal, m.jobsRunnerLost, m.jobReruns, m.jobFailures, m.runnerStartFailures, m.queueWait, m.jobDuration, m.scalingEvents,
		m.registrationsDeferred,
		m.webhookDeliveries, m.githubRequests, m.reconcileDuration, m.storeWriteWait, m.storeWriteHeld, m.reconcileErrors, m.cleanups, m.pollsShed, m.agentLimited, m.logRelayDropped, m.buildInfo,
		m.providerOperations, m.providerOperationSeconds,
		m.imagePrewarms, m.imagePrewarmDuration, m.runtimeFailures, m.imagePullFailures,
		m.elasticCPUDecisions, m.elasticCPUFactor,
		m.startupWait, m.dindReady, m.queuedToCreate, m.createToContainer, m.containerToRegistered, m.registeredToReady, m.queuedToStarted,
		m.schedulingLatency, m.cleanupDuration,
		&fleetCollector{c: c},
		collectors.NewGoCollector(),
		collectors.NewProcessCollector(collectors.ProcessCollectorOpts{}),
	)
	return m
}

func startupHistogram(name, help string) *prometheus.HistogramVec {
	return prometheus.NewHistogramVec(prometheus.HistogramOpts{Name: name, Help: help,
		Buckets: []float64{.1, .5, 1, 2.5, 5, 10, 30, 60, 120, 300, 600, 1800}}, []string{"pool", "backend"})
}

func observeDuration(h *prometheus.HistogramVec, pool, backend string, from, to time.Time) bool {
	if from.IsZero() || to.IsZero() || to.Before(from) {
		return false
	}
	h.WithLabelValues(pool, backend).Observe(to.Sub(from).Seconds())
	return true
}

// Registry returns the Prometheus registry the API serves at the configured
// metrics path.
func (c *Controller) Registry() *prometheus.Registry { return c.metrics.reg }

// Metric descriptors for the fleet gauges. They are package-level because a
// collector must return the same descriptors on every Describe call.
var (
	descRunners = prometheus.NewDesc("zoomies_runners",
		"Runners by pool and state.", []string{"pool", "state"}, nil)
	descJobsQueued = prometheus.NewDesc("zoomies_jobs_queued",
		"Jobs waiting for a runner, by the pool that claimed them.", []string{"pool"}, nil)
	descHosts = prometheus.NewDesc("zoomies_hosts",
		"Agent hosts by state.", []string{"state"}, nil)
	descHostCapacity = prometheus.NewDesc("zoomies_host_capacity",
		"Total configured runner slots across healthy, uncordoned hosts.", nil, nil)
	// Configured and effective are kept apart rather than one replacing the
	// other: the gap between them is the throttle, and an operator alerting
	// on "the fleet shrank" needs to tell a host somebody resized from a host
	// the controller stepped down.
	descHostEffectiveCapacity = prometheus.NewDesc("zoomies_host_effective_capacity",
		"Runner slots across healthy, uncordoned hosts as their throttles leave them; equals zoomies_host_capacity while no host is throttled.", nil, nil)
	descHostCapacityUsed = prometheus.NewDesc("zoomies_host_capacity_used",
		"Runner slots currently occupied on healthy, uncordoned hosts: the same hosts zoomies_host_capacity counts, so the ratio of the two is utilisation.", nil, nil)
	// Slots say how many runners a fleet will take; these say whether the
	// machines can carry them. A fleet with slots free and no memory left is
	// the case the slot gauges cannot describe, and it is the one an operator
	// is looking for when the queue is not draining.
	descAllocatableCPUs = prometheus.NewDesc("zoomies_host_allocatable_cpus",
		"CPUs across healthy, uncordoned hosts, less each host's reserve.", nil, nil)
	descAllocatableMemory = prometheus.NewDesc("zoomies_host_allocatable_memory_bytes",
		"Memory across healthy, uncordoned hosts, less each host's reserve.", nil, nil)
	descReservedCPUs = prometheus.NewDesc("zoomies_host_reserved_cpus",
		"CPUs the live runners on those hosts have promised away, as of the last scheduling pass.", nil, nil)
	descReservedMemory = prometheus.NewDesc("zoomies_host_reserved_memory_bytes",
		"Memory the live runners on those hosts have promised away, as of the last scheduling pass.", nil, nil)
	// The backlog's depth and its age answer different questions: ten jobs
	// queued for four seconds is a fleet working, and one job queued for forty
	// minutes is a fleet that has stopped, and `zoomies_jobs_queued` cannot
	// tell them apart. This is the one an alert should use.
	descQueueAge = prometheus.NewDesc("zoomies_job_queue_age_seconds",
		"How long the oldest job still waiting has been waiting, by pool. Zero when nothing is waiting.",
		[]string{"pool"}, nil)
	// Rate-limit backoff is per installation and always has been, so this
	// carries the installation rather than being the fleet-wide flag the plan
	// described. A fleet with two installations, one of them held, is a fleet
	// half working -- and the fleet-wide version could not say which half.
	descGitHubPaused = prometheus.NewDesc("zoomies_github_paused",
		"1 while an installation is inside its GitHub rate-limit backoff and every background sweep is standing down from it, 0 otherwise.",
		[]string{"installation"}, nil)
	descHostCPUUsage = prometheus.NewDesc("zoomies_host_cpu_usage_percent",
		"Recent whole-host CPU occupied, including I/O wait. Absent when stale or unmeasured.", []string{"host"}, nil)
	descHostMemoryAvailable = prometheus.NewDesc("zoomies_host_memory_available_bytes",
		"Recent whole-host memory available, including reclaimable cache. Absent when stale or unmeasured.", []string{"host"}, nil)
	descHostAdmissionHeld = prometheus.NewDesc("zoomies_host_admission_held",
		"1 while measured host pressure holds new starts, 0 otherwise. Does not describe operator cordons.", []string{"host"}, nil)
	descHostUsageFresh = prometheus.NewDesc("zoomies_host_usage_fresh",
		"1 when a host usage measurement is recent enough for placement, 0 otherwise.", []string{"host"}, nil)
	// The machines a fleet is renting, by provider and state. Read at scrape
	// time like every other fleet gauge, so it cannot drift from the rows the
	// way a counter kept in memory would across a restart -- and a restart is
	// exactly when somebody is looking at it.
	descProviderMachines = prometheus.NewDesc("zoomies_provider_machines",
		"Machines by provider and state.", []string{"provider", "state"}, nil)
	// Quarantined machines are separated from the state series because they
	// are the one state nothing will move on its own: the number is a queue of
	// work for a person, and an alert on it is an alert on somebody being
	// needed rather than on the fleet's shape.
	descProviderQuarantined = prometheus.NewDesc("zoomies_provider_machines_quarantined",
		"Machines whose ownership could not be proved, which nothing will act on until a person does.", nil, nil)
	descHostLoadAverage = prometheus.NewDesc("zoomies_host_load_average_1m",
		"Recent whole-host one-minute load average. Absent when stale or unmeasured.", []string{"host"}, nil)
	descHostRuntimeRecovering = prometheus.NewDesc("zoomies_host_runtime_recovering",
		"1 while a host's agent reports its container runtime is in a recovery cooldown, 0 otherwise.", []string{"host"}, nil)
	descHostThrottleLevel = prometheus.NewDesc("zoomies_host_throttle_level",
		"The throttle rung a host is on after sustained pressure, 0 to 3; 0 while it is not throttled.", []string{"host"}, nil)
)

// fleetCollector reads the fleet's shape from the database on each scrape.
type fleetCollector struct{ c *Controller }

func (f *fleetCollector) Describe(ch chan<- *prometheus.Desc) {
	ch <- descRunners
	ch <- descJobsQueued
	ch <- descHosts
	ch <- descHostCapacity
	ch <- descHostCapacityUsed
	ch <- descQueueAge
	ch <- descGitHubPaused
	ch <- descAllocatableCPUs
	ch <- descAllocatableMemory
	ch <- descReservedCPUs
	ch <- descReservedMemory
	ch <- descHostCPUUsage
	ch <- descHostMemoryAvailable
	ch <- descHostAdmissionHeld
	ch <- descHostUsageFresh
	ch <- descProviderMachines
	ch <- descProviderQuarantined
	ch <- descHostLoadAverage
	ch <- descHostThrottleLevel
	ch <- descHostRuntimeRecovering
	ch <- descHostEffectiveCapacity
}

func (f *fleetCollector) Collect(ch chan<- prometheus.Metric) {
	ctx, cancel := context.WithTimeout(context.Background(), collectTimeout)
	defer cancel()

	pools, err := f.c.st.ListPools(ctx)
	if err != nil {
		f.c.log.Warn("could not read pools for the metrics endpoint", "error", err)
		return
	}
	counts, err := f.c.st.CountRunnersByPool(ctx)
	if err != nil {
		f.c.log.Warn("could not count runners for the metrics endpoint", "error", err)
		return
	}
	queued, err := f.c.st.ListQueuedJobs(ctx)
	if err != nil {
		f.c.log.Warn("could not read queued jobs for the metrics endpoint", "error", err)
		return
	}
	hosts, err := f.c.st.ListHosts(ctx)
	if err != nil {
		f.c.log.Warn("could not read hosts for the metrics endpoint", "error", err)
		return
	}

	installations, err := f.c.st.ListInstallations(ctx)
	if err != nil {
		f.c.log.Warn("could not read installations for the metrics endpoint", "error", err)
		return
	}

	now := f.c.Now()
	queuedByPool := map[string]int{}
	// The oldest wait per pool, from the moment GitHub queued the job: that is
	// the wait somebody is actually sitting through, and it is the same clock
	// `zoomies_job_queue_wait_seconds` measures once the job finally starts.
	oldestByPool := map[string]float64{}
	for _, j := range queued {
		queuedByPool[j.PoolID]++
		if j.QueuedAt.IsZero() {
			continue
		}
		if age := now.Sub(j.QueuedAt).Seconds(); age > oldestByPool[j.PoolID] {
			oldestByPool[j.PoolID] = age
		}
	}

	gauge := func(d *prometheus.Desc, v float64, labels ...string) {
		ch <- prometheus.MustNewConstMetric(d, prometheus.GaugeValue, v, labels...)
	}

	for _, p := range pools {
		pc := counts[p.ID]
		// Every state is emitted, including the zeroes: a series that vanishes
		// when a pool empties makes rate() and alerting rules unreliable.
		for state, n := range map[store.RunnerState]int{
			store.RunnerProvisioning: pc.Provisioning,
			store.RunnerRegistering:  pc.Registering,
			store.RunnerIdle:         pc.Idle,
			store.RunnerBusy:         pc.Busy,
			store.RunnerDraining:     pc.Draining,
			store.RunnerFailed:       pc.Failed,
		} {
			gauge(descRunners, float64(n), p.Name, string(state))
		}
		gauge(descJobsQueued, float64(queuedByPool[p.ID]), p.Name)
		gauge(descQueueAge, oldestByPool[p.ID], p.Name)
	}
	// Jobs no pool claimed still have to be visible somewhere.
	gauge(descJobsQueued, float64(queuedByPool[""]), UnmatchedPool)
	gauge(descQueueAge, oldestByPool[""], UnmatchedPool)

	// Every installation reports, held or not: a series that only exists while
	// something is wrong cannot be alerted on with a threshold, and an operator
	// reading the endpoint by hand learns nothing from an absent line.
	held := f.c.heldInstallations(now)
	for _, inst := range installations {
		v := 0.0
		if _, ok := held[inst.ID]; ok {
			v = 1
		}
		gauge(descGitHubPaused, v, inst.ID)
	}

	var healthy, unhealthy, cordoned, capacity, effective, used int
	for _, h := range hosts {
		fresh, held := 0.0, 0.0
		if h.Usage.Fresh(now) {
			fresh = 1
			if v := h.Usage.CPUPercent; v != nil {
				gauge(descHostCPUUsage, *v, h.ID)
			}
			if v := h.Usage.MemoryAvailableMB; v != nil {
				gauge(descHostMemoryAvailable, float64(*v)*(1<<20), h.ID)
			}
			if v := h.Usage.LoadAverage1; v != nil {
				gauge(descHostLoadAverage, *v, h.ID)
			}
		}
		if scheduler.HostAdmissionReason(h, now) != "" {
			held = 1
		}
		gauge(descHostUsageFresh, fresh, h.ID)
		gauge(descHostAdmissionHeld, held, h.ID)
		// Every host reports a level, throttled or not, for the same reason
		// the paused gauge does: a series that only exists while something
		// is wrong cannot be alerted on with a threshold.
		gauge(descHostThrottleLevel, float64(h.Throttle.Level), h.ID)
		recovering := 0.0
		if h.Incidents.Runtime != nil {
			recovering = 1
		}
		gauge(descHostRuntimeRecovering, recovering, h.ID)
		switch {
		case !h.Healthy(now):
			unhealthy++
		case h.Cordoned:
			cordoned++
		default:
			healthy++
		}
		if h.Healthy(now) && !h.Cordoned {
			capacity += h.Capacity
			effective += h.EffectiveCapacity()
			// The same hosts as the capacity it is divided by; see Stats.
			used += h.ActiveRunners
		}
	}
	// Only the hosts that can actually take work, which is the same set
	// descHostCapacity counts: a cordoned host's memory is not the fleet's to
	// place into, and counting it would say the fleet has room it will not use.
	var allocCPUs, reservedCPUs float64
	var allocMemory, reservedMemory int64
	for _, h := range hosts {
		if !h.Healthy(now) || h.Cordoned {
			continue
		}
		a := h.Allocatable()
		allocCPUs += a.CPUs
		allocMemory += a.MemoryMB
		if r, ok := f.c.reservedOn(h.ID); ok {
			reservedCPUs += r.CPUs
			reservedMemory += r.MemoryMB
		}
	}
	const mb = 1 << 20
	gauge(descAllocatableCPUs, allocCPUs)
	gauge(descAllocatableMemory, float64(allocMemory)*mb)
	gauge(descReservedCPUs, reservedCPUs)
	gauge(descReservedMemory, float64(reservedMemory)*mb)

	f.collectMachines(ctx, gauge)

	gauge(descHosts, float64(healthy), "healthy")
	gauge(descHosts, float64(unhealthy), "unhealthy")
	gauge(descHosts, float64(cordoned), "cordoned")
	gauge(descHostCapacity, float64(capacity))
	gauge(descHostEffectiveCapacity, float64(effective))
	gauge(descHostCapacityUsed, float64(used))
}

// collectMachines reports what each provider is renting.
//
// Every state of every configured provider is emitted, zeroes included, for the
// reason the runner gauges are: a series that vanishes when a provider empties
// makes an alerting rule unreliable, and "no machines" is exactly what somebody
// paging on a stuck fleet needs to be able to see.
func (f *fleetCollector) collectMachines(ctx context.Context, gauge func(*prometheus.Desc, float64, ...string)) {
	providers, err := f.c.st.ListProviders(ctx)
	if err != nil {
		f.c.log.Warn("could not read providers for the metrics endpoint", "error", err)
		return
	}
	if len(providers) == 0 {
		return
	}
	quarantined := 0
	for _, p := range providers {
		machines, err := f.c.st.ListMachinesForProvider(ctx, p.ID)
		if err != nil {
			f.c.log.Warn("could not read a provider's machines for the metrics endpoint",
				"provider", p.ID, "error", err)
			continue
		}
		counts := map[store.MachineState]int{}
		for _, m := range machines {
			counts[m.State]++
			if m.State == store.MachineQuarantined {
				quarantined++
			}
		}
		for _, state := range []store.MachineState{
			store.MachinePlanned, store.MachineCreating, store.MachineStarting,
			store.MachineBootstrapping, store.MachineEnrolling, store.MachineReady,
			store.MachineDraining, store.MachineDeleting, store.MachineFailed,
			store.MachineQuarantined,
		} {
			gauge(descProviderMachines, float64(counts[state]), p.Name, string(state))
		}
	}
	gauge(descProviderQuarantined, float64(quarantined))
}

package controller

import (
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"

	"github.com/eyupio/zoomies/internal/agent"

	"github.com/prometheus/client_golang/prometheus/testutil"

	"github.com/eyupio/zoomies/internal/store"
)

// Every pool-labelled metric names the pool the same way.
//
// `zoomies_jobs_total` used the pool id while every other pool-labelled series
// used the name, so a PromQL query joining a pool's job count against its
// runner count on `pool` matched nothing at all -- silently, which is the worst
// way for a dashboard to be wrong. One helper decides what a pool label is now,
// and this holds it to names.
func TestPoolLabelsAreNamesEverywhere(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "zoomies-linux-x64")

	if got := h.c.poolLabel(pool.ID); got != pool.Name {
		t.Errorf("poolLabel(%q) = %q, want the pool's name %q", pool.ID, got, pool.Name)
	}

	// Work no pool claims is counted under one agreed literal rather than an
	// empty label, which Prometheus cannot tell from a bug.
	if got := h.c.poolLabel(""); got != UnmatchedPool {
		t.Errorf("poolLabel(\"\") = %q, want %q", got, UnmatchedPool)
	}

	// A pool deleted between the job finishing and the metric being written
	// still has to be counted somewhere, and its id is the only name left.
	if got := h.c.poolLabel("pool_goneaway"); got != "pool_goneaway" {
		t.Errorf("poolLabel of a missing pool = %q, want the id back", got)
	}
}

// The completion counter carries the pool's name, not its id.
func TestJobCompletionIsCountedUnderThePoolName(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "zoomies-linux-x64")

	h.c.observeJobCompletion(&store.Job{PoolID: pool.ID, Conclusion: "success"})

	if got := testutil.ToFloat64(h.c.metrics.jobsTotal.WithLabelValues(pool.Name, "success")); got != 1 {
		t.Errorf("zoomies_jobs_total{pool=%q} = %v, want 1", pool.Name, got)
	}
	if got := testutil.ToFloat64(h.c.metrics.jobsTotal.WithLabelValues(pool.ID, "success")); got != 0 {
		t.Errorf("zoomies_jobs_total is still counted under the pool id %q", pool.ID)
	}

	// And a job no pool claimed lands under the agreed literal.
	h.c.observeJobCompletion(&store.Job{Conclusion: "failure"})
	if got := testutil.ToFloat64(h.c.metrics.jobsTotal.WithLabelValues(UnmatchedPool, "failure")); got != 1 {
		t.Errorf("an unclaimed job was not counted under %q", UnmatchedPool)
	}
}

// gatherValue reads one sample from the controller's own registry, by metric
// name and label values, so a test asks the endpoint's question rather than
// the collector's.
func gatherValue(t *testing.T, c *Controller, name string, labels map[string]string) (float64, bool) {
	t.Helper()
	families, err := c.Registry().Gather()
	if err != nil {
		t.Fatalf("gathering metrics: %v", err)
	}
	for _, f := range families {
		if f.GetName() != name {
			continue
		}
	metric:
		for _, m := range f.GetMetric() {
			for k, want := range labels {
				found := false
				for _, l := range m.GetLabel() {
					if l.GetName() == k && l.GetValue() == want {
						found = true
					}
				}
				if !found {
					continue metric
				}
			}
			switch {
			case m.Gauge != nil:
				return m.GetGauge().GetValue(), true
			case m.Counter != nil:
				return m.GetCounter().GetValue(), true
			}
		}
	}
	return 0, false
}

func gatherHistogram(t *testing.T, c *Controller, name string, labels map[string]string) (uint64, float64, bool) {
	t.Helper()
	families, err := c.Registry().Gather()
	if err != nil {
		t.Fatalf("gathering metrics: %v", err)
	}
	for _, family := range families {
		if family.GetName() != name {
			continue
		}
	metric:
		for _, metric := range family.GetMetric() {
			for key, want := range labels {
				found := false
				for _, label := range metric.GetLabel() {
					if label.GetName() == key && label.GetValue() == want {
						found = true
					}
				}
				if !found {
					continue metric
				}
			}
			if metric.Histogram != nil {
				return metric.GetHistogram().GetSampleCount(), metric.GetHistogram().GetSampleSum(), true
			}
		}
	}
	return 0, 0, false
}

func TestImagePrewarmReportsCacheEfficiencyAndDuration(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	if n, err := h.c.PrewarmPool(h.ctx, pool); err != nil || n != 1 {
		t.Fatalf("PrewarmPool = %d, %v; want one host", n, err)
	}
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks = %+v, %v; want the prewarm task", batch, err)
	}
	cached := true
	duration := 7 * time.Millisecond
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: batch.Tasks[0].ID, Kind: agent.TaskPrewarmImage, OK: true,
		PrewarmCached: &cached, PrewarmDuration: &duration,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	labels := map[string]string{"pool": pool.Name, "backend": string(pool.Backend), "outcome": "cache_hit"}
	if got, ok := gatherValue(t, h.c, "zoomies_image_prewarms_total", labels); !ok || got != 1 {
		t.Errorf("cache-hit prewarms = %v (present=%v), want 1", got, ok)
	}
	count, sum, ok := gatherHistogram(t, h.c, "zoomies_image_prewarm_duration_seconds", labels)
	if !ok || count != 1 || sum < duration.Seconds() || sum > duration.Seconds()+0.001 {
		t.Errorf("prewarm duration = count %d, sum %v (present=%v), want one %v observation", count, sum, ok, duration.Seconds())
	}
}

// The backlog's depth and its age are different questions, and only the second
// one distinguishes a fleet that is working from a fleet that has stopped: ten
// jobs queued for four seconds and one job queued for forty minutes are the
// same number in `zoomies_jobs_queued`.
func TestTheQueueAgeGaugeIsTheOldestWaitInThePool(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "zoomies-linux-x64")

	// Two waiting jobs. The gauge is about the one that has waited longest,
	// which is the one somebody is complaining about.
	waiting := func(ago time.Duration) {
		t.Helper()
		if _, err := h.st.UpsertJob(h.ctx, &store.Job{
			GitHubJobID: time.Now().UnixNano(),
			Repo:        "acme/widgets",
			Workflow:    "CI",
			JobName:     "build",
			Labels:      store.NormalizeLabels(pool.Labels),
			State:       store.JobQueued,
			PoolID:      pool.ID,
			Matched:     true,
			QueuedAt:    h.c.Now().Add(-ago),
		}); err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}
	}
	waiting(20 * time.Minute)
	waiting(time.Minute)

	got, ok := gatherValue(t, h.c, "zoomies_job_queue_age_seconds", map[string]string{"pool": pool.Name})
	if !ok {
		t.Fatal("zoomies_job_queue_age_seconds was not reported for the pool")
	}
	// The harness runs on a real clock, so the assertion is that this is the
	// twenty-minute wait and not the one-minute one, not that it is 1200.0.
	if want := (20 * time.Minute).Seconds(); got < want || got > want+30 {
		t.Errorf("queue age = %v, want the oldest wait, about %v", got, want)
	}
}

// A pool with nothing waiting reports zero rather than nothing at all: a series
// that disappears when the fleet is idle cannot carry an alert, because the
// rule stops matching exactly when it would otherwise fire.
func TestAnEmptyQueueReportsZeroRatherThanNothing(t *testing.T) {
	h := newHarness(t)
	pool := h.pool(h.installation(), "zoomies-linux-x64")

	got, ok := gatherValue(t, h.c, "zoomies_job_queue_age_seconds", map[string]string{"pool": pool.Name})
	if !ok {
		t.Fatal("an idle pool reported no queue age at all")
	}
	if got != 0 {
		t.Errorf("queue age on an idle pool = %v, want 0", got)
	}
}

// Rate-limit backoff is per installation, so the gauge is too: a fleet with two
// installations, one of them held, is a fleet half working, and the fleet-wide
// flag the plan described could not say which half.
func TestTheGitHubPauseGaugeNamesTheInstallationItIsHolding(t *testing.T) {
	h := newHarness(t)
	held := h.installationOn("acme", store.TargetOrg)
	free := h.installationOn("globex", store.TargetOrg)

	h.c.holdGitHub(held.ID, h.c.Now().Add(10*time.Minute))

	if got, ok := gatherValue(t, h.c, "zoomies_github_paused", map[string]string{"installation": held.ID}); !ok || got != 1 {
		t.Errorf("the held installation reported %v (present=%v), want 1", got, ok)
	}
	if got, ok := gatherValue(t, h.c, "zoomies_github_paused", map[string]string{"installation": free.ID}); !ok || got != 0 {
		t.Errorf("the installation that is not held reported %v (present=%v), want 0", got, ok)
	}
}

// A pass that fails observes no duration, so without this the difference
// between a controller deciding nothing and a controller with nothing to decide
// is invisible: the duration series goes quiet either way.
func TestAFailedReconcilePassIsCounted(t *testing.T) {
	h := newHarness(t)
	// A closed store fails the snapshot, which is the first thing a pass does.
	if err := h.st.Close(); err != nil {
		t.Fatalf("closing the store: %v", err)
	}

	h.c.reconcileNow(h.ctx)

	if got, _ := gatherValue(t, h.c, "zoomies_reconcile_errors_total", nil); got != 1 {
		t.Errorf("zoomies_reconcile_errors_total = %v after a failed pass, want 1", got)
	}
}

// Labels are the one thing about a metric that cannot be fixed later: a
// repository or workflow name here multiplies every series by the number of
// repositories in the organisation, and a scraper that has ingested them keeps
// them for its retention window whatever the next release does. The allowed set
// is small and deliberate, and this holds the whole registry to it rather than
// one family at a time -- the older test covered the startup histograms alone,
// and every series added since was on trust.
//
// It reads the registry's *descriptors* rather than a scrape. Written the
// obvious way -- gather, then look at the labels on what came back -- it passed
// with a `repository` label added to a counter, because a vector with no
// observations yet reports nothing at all, and a bad label would only be caught
// on the day something happened to increment it.
func TestNoMetricDeclaresAnUnboundedLabel(t *testing.T) {
	h := newHarness(t)

	allowed := map[string]bool{
		"pool": true, "state": true, "conclusion": true, "direction": true,
		"status": true, "installation": true, "result": true, "backend": true,
		"outcome": true, "version": true, "commit": true,
		// Elastic CPU mode is the closed off/observe/automatic policy set.
		"mode": true,
		// Registered hosts are operator-managed fleet entities like pools;
		// ephemeral runner/container IDs remain excluded.
		"host": true,
		// A provider is a configuration row somebody wrote, like a pool, and
		// there are a handful of them. "kind" is the five operations the
		// provider contract defines, which is a closed set in the source --
		// neither grows with the fleet's work, which is what this test is
		// about; a machine id would, and is deliberately absent.
		"provider": true, "kind": true,
		// "domain" is two values and "fault" is the closed set in
		// store.FaultKinds. Both are constants in the source rather than
		// anything the fleet's work produces, which is the distinction this
		// test draws: a job id would multiply every series by the day's work,
		// and nine categories do not.
		"domain": true, "fault": true,
		// "trigger" is the two ways a re-run is asked for -- the button and
		// the setting -- and both are constants in the source. What it must
		// never become is who asked, which would grow with the people.
		"trigger": true,
		// "limit" is the three per-host agent limits -- rate, poll and
		// runners -- constants in the source. The host that met one is in the
		// log line instead, because refusals are exactly where an unbounded
		// label would do its damage.
		"limit": true,
	}

	descs := make(chan *prometheus.Desc, 256)
	go func() {
		h.c.Registry().Describe(descs)
		close(descs)
	}()

	labels := regexp.MustCompile(`variableLabels: \{([^}]*)\}`)
	name := regexp.MustCompile(`fqName: "([^"]*)"`)
	var checked int
	for d := range descs {
		s := d.String()
		m := name.FindStringSubmatch(s)
		if m == nil {
			t.Fatalf("could not read a metric name out of %s", s)
		}
		// The Go runtime and process collectors are the library's, and their
		// label names are not ours to police.
		if strings.HasPrefix(m[1], "go_") || strings.HasPrefix(m[1], "process_") {
			continue
		}
		checked++
		v := labels.FindStringSubmatch(s)
		if v == nil || v[1] == "" {
			continue
		}
		for _, l := range strings.Split(v[1], ",") {
			if l = strings.TrimSpace(l); l != "" && !allowed[l] {
				t.Errorf("%s declares the label %q, which is not in the bounded set: a label whose values grow with the fleet's work multiplies every series by it",
					m[1], l)
			}
		}
	}
	if checked == 0 {
		t.Fatal("no Zoomies metric descriptors were collected; the test is looking in the wrong place")
	}
}

// Cleanup is the half of a runner's life that fails on the host rather than in
// the fleet, so it is invisible in every other series here: those count what
// the fleet decided, and this counts what the host managed. The row already
// carries the failure and the problems drawer already names it; neither is a
// rate, and "one host has been failing to remove containers all week" is a rate
// question.
func TestCleanupOutcomesAreCounted(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	// The row is finished with, which is the case the record exists for: the
	// slot is already free, so a failed remove leaves a container on the host
	// and no state to move.
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "task_1", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: false, Error: "the daemon refused: container is in use",
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if got, _ := gatherValue(t, h.c, "zoomies_runner_cleanups_total", map[string]string{"outcome": "failed"}); got != 1 {
		t.Errorf("failed cleanups = %v after one refusal, want 1", got)
	}

	// And the retry that works is counted as the success it is, rather than
	// leaving the failure standing alone as though the runner were still there.
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: "task_2", Kind: agent.TaskRemoveRunner, RunnerID: r.ID,
		OK: true, State: store.RunnerRemoved,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	if got, _ := gatherValue(t, h.c, "zoomies_runner_cleanups_total", map[string]string{"outcome": "succeeded"}); got != 1 {
		t.Errorf("successful cleanups = %v after the retry worked, want 1", got)
	}
}

// A runner's startup timings are read off the row the store handed back, not
// off whatever the caller was holding.
//
// The create result is what stamps container_started_at, and it is also what
// races GitHub's in_progress delivery -- which is how a job start came to be
// dropped in the first place. The webhook handler's copy of the runner is
// several writes old by the time the start is applied, so taking the container
// time from it would lose the container-to-registered timing for exactly the
// runners whose startup was slow enough to race.
func TestRunnerStartupTimingsAreReadOffTheRowTheStoreReturned(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")

	started := time.Now().Add(-30 * time.Second)
	registered := started.Add(20 * time.Second)
	row := &store.Runner{
		PoolID:             pool.ID,
		State:              store.RunnerBusy,
		ContainerStartedAt: &started,
		RegisteredAt:       &registered,
	}

	if n := testutil.CollectAndCount(h.c.metrics.containerToRegistered); n != 0 {
		t.Fatalf("the container timing already has %d series before anything was observed", n)
	}
	h.c.observeRunnerReady(h.ctx, row)
	if n := testutil.CollectAndCount(h.c.metrics.containerToRegistered); n != 1 {
		t.Errorf("container-to-registered has %d series, want 1: the timing was taken from a copy that did not have it", n)
	}
	if n := testutil.CollectAndCount(h.c.metrics.registeredToReady); n != 1 {
		t.Errorf("registered-to-ready has %d series, want 1", n)
	}
}

// A controller's writes reach its histograms. The store measures, but it is
// the controller that owns the registry, and a histogram registered and never
// observed would scrape as a writer that is never used -- the one reading
// that says everything is fine.
func TestTheWritersQueueIsOnTheScrape(t *testing.T) {
	h := newHarness(t)
	beforeWait, _, _ := gatherHistogram(t, h.c, "zoomies_store_write_wait_seconds", nil)
	beforeHeld, _, _ := gatherHistogram(t, h.c, "zoomies_store_write_held_seconds", nil)

	h.fleet() // installs, pools and a host: writes, all through the one writer

	wait, _, ok := gatherHistogram(t, h.c, "zoomies_store_write_wait_seconds", nil)
	if !ok || wait <= beforeWait {
		t.Errorf("zoomies_store_write_wait_seconds counted %d writes after the fleet was seeded, and %d before; the writer's queue never reached the scrape", wait, beforeWait)
	}
	held, _, ok := gatherHistogram(t, h.c, "zoomies_store_write_held_seconds", nil)
	if !ok || held <= beforeHeld {
		t.Errorf("zoomies_store_write_held_seconds counted %d writes after the fleet was seeded, and %d before; every write has a hold as well as a wait", held, beforeHeld)
	}
}

// Queued-to-create is how long a job waited before the fleet started a runner
// for it -- the first figure anyone reads when the queue feels slow. Nothing
// tested it, so this pins it before the read that feeds it moves: one
// observation per runner created, measured from the job the pool was serving.
func TestEveryRunnerCreatedForAWaitingJobRecordsHowLongItWaited(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64")
	// Two runners wanted outright, so the pass creates whatever the demand
	// arithmetic makes of the jobs; the metric reads the job the pool is
	// serving either way.
	pool.MinRunners = 2
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.measuredHost("measured", 8, 16384, 4, enforcesEverything)
	h.queuedJob(t, pool, pool.Labels) // queued two minutes ago

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	created := 0
	rs, err := h.st.ListRunnersForPool(h.ctx, pool.ID)
	if err != nil {
		t.Fatal(err)
	}
	for _, r := range rs {
		if r.State.Live() || r.State == store.RunnerFailed {
			created++
		}
	}
	if created == 0 {
		t.Fatal("the pass created no runner; the fixture is not exercising a create")
	}
	n, sum, ok := gatherHistogram(t, h.c, "zoomies_runner_queued_to_create_seconds", map[string]string{"pool": pool.Name})
	if !ok || int(n) != created {
		t.Fatalf("queued-to-create has %d observation(s) for %d runner(s) created; want one per runner", n, created)
	}
	if mean := sum / float64(n); mean < 100 || mean > 200 {
		t.Errorf("queued-to-create averaged %.0fs; the jobs were queued two minutes before the pass", mean)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

// The migration service: what moving a repository's workflows onto this fleet
// would change, and then doing it.
//
// It is two halves of one thing, deliberately shaped like /pools/validate and
// /pools: a plan is computed and shown, and only a second, explicit call
// writes anything. Nothing about a migration should ever be a surprise -- it
// opens pull requests in other people's repositories -- so planning creates
// nothing at all, and applying takes the plan's own inputs back rather than a
// token that could stand for a plan the operator never saw.
//
// Neither half stores anything. A migration is a thing an operator does once
// per repository; a table of half-finished migrations would be a schema to
// maintain, a thing to garbage-collect, and another place for a stale plan to
// hide.
//
// This lives in the controller rather than the API because it is fleet logic
// -- which pools a job could go to, what a repository's workflows say, what
// GitHub is asked to do about it -- and the API has no opinions about the
// fleet. The handlers decode a request, call here, and render the answer.

// Both halves fan out into GitHub's API on a quota the scheduler shares, so
// each bounds what one request will do.
const (
	// MaxPlanRepos is the most repositories one plan will read workflows from.
	// The wizard scans in pages; an operator with more repositories than this
	// migrates them in batches, which is how anyone would want to review them
	// anyway.
	MaxPlanRepos = 50
	// MaxApplyRepos is the most pull requests one call will open. It is lower
	// than the plan's limit on purpose: fifty pull requests landing at once in
	// somebody's review queue is not a migration, it is an incident.
	MaxApplyRepos = 25
	// planConcurrency is how many repositories are read at once. GitHub's
	// secondary rate limits punish bursts, and a scan is not urgent.
	planConcurrency = 4
)

var (
	// ErrNoMigrationPool means the installation has no enabled pool, so there
	// is nowhere to send a job and nothing to plan.
	ErrNoMigrationPool = errors.New("there is nowhere to migrate to: this installation has no enabled pool")
	// ErrNothingMapped means the apply request maps no hosted label to a pool
	// and points no single job at one either, so no workflow would change.
	ErrNothingMapped = errors.New("nothing would change: no hosted label is mapped to a pool, and no job is pointed at one by name")
	// ErrNotAWorkflow means the apply request named a file GitHub would never
	// run, which would be a pull request that quietly changed nothing.
	ErrNotAWorkflow = errors.New("only files directly under .github/workflows can be migrated")
	// ErrBadOverride means an override named something other than one job in
	// one workflow file in one repository, so there is no single place for it
	// to apply to.
	ErrBadOverride = errors.New("an override names one job in one workflow file in one repository")
)

// ---------------------------------------------------------------------------
// Requests
// ---------------------------------------------------------------------------

// MigrationPlanRequest asks what a migration would change.
type MigrationPlanRequest struct {
	InstallationID string `json:"installation_id"`
	// Repos limits the plan to these repositories. Empty means every
	// repository the installation can see, up to the limit.
	Repos []string `json:"repos"`
	// Mapping is hosted label -> the runs-on value that replaces it. Empty asks
	// the server to propose one from the pools that exist.
	Mapping map[string]string `json:"mapping"`
	// Overrides are the exceptions to Mapping, each naming one job in one file
	// in one repository. Empty is the common case: most fleets want one answer
	// per hosted-runner label everywhere.
	Overrides []migrate.Override `json:"overrides"`
	// Cursor asks for the page of repositories after this one. It is the full
	// name of the last repository the previous page returned, because the
	// listing is sorted by name: a name is stable when the App gains or loses
	// a repository between two pages, and an offset is not.
	Cursor string `json:"cursor"`
}

// MigrationApplyRequest opens the pull requests a plan described.
type MigrationApplyRequest struct {
	InstallationID string            `json:"installation_id"`
	Repos          []string          `json:"repos"`
	Mapping        map[string]string `json:"mapping"`
	// Overrides are the exceptions to Mapping. They sit alongside Workflows
	// rather than inside it: Workflows says which files move at all, and an
	// override says where one job in one of them lands.
	Overrides []migrate.Override `json:"overrides"`
	// Workflows narrows a repository to the workflow files named here, keyed by
	// repository. A repository absent from the map gets every file the mapping
	// would change, which is what a client that does not know about the field
	// asks for. It exists because a repository with a dozen workflow files is
	// rarely one where all dozen should move at once.
	Workflows map[string][]string `json:"workflows"`
	// Title, Body and CommitMessage override the defaults. They are here
	// because the pull request lands in somebody else's repository, and an
	// organisation with a pull-request template or a commit convention should
	// not have to accept ours.
	Title         string `json:"title"`
	Body          string `json:"body"`
	CommitMessage string `json:"commit_message"`
	// Badge says whether each pull request also adds the "CI has the
	// Zoomies" badge to the repository's README. It is a pointer because
	// the default is yes: a client that does not know the field asks for the
	// badge, and only an explicit false leaves the README alone. The badge is
	// how the people who read a README find out what runs its CI, and a
	// checkbox is a fair price for a line in somebody else's front page.
	Badge *bool `json:"badge"`
}

// WantsBadge reports whether the request asks for the badge, which it does
// unless it said not to.
func (r MigrationApplyRequest) WantsBadge() bool {
	return r.Badge == nil || *r.Badge
}

// ---------------------------------------------------------------------------
// Results
// ---------------------------------------------------------------------------

// MigrationPoolOption is one pool the wizard can map a hosted label to.
type MigrationPoolOption struct {
	ID     string   `json:"id"`
	Name   string   `json:"name"`
	Labels []string `json:"labels"`
	// RunsOn is what a workflow writes to reach this pool: the value the
	// mapping should hold.
	RunsOn  string `json:"runs_on"`
	Enabled bool   `json:"enabled"`
}

// MigrationPlan is the whole review step.
type MigrationPlan struct {
	InstallationID string `json:"installation_id"`
	Target         string `json:"target"`
	// Repositories is every repository looked at, whether or not it changed.
	// A repository with nothing to do is information: it means its workflows
	// are already somewhere deliberate.
	Repositories []migrate.RepoPlan `json:"repositories"`
	// HostedLabels is every hosted-runner label found across them -- GitHub's
	// own and the vendors' -- which is what the mapping step lists.
	HostedLabels []string `json:"hosted_labels"`
	// Mapping is what was applied -- the request's, or the proposal the server
	// made from the pools that exist.
	Mapping map[string]string `json:"mapping"`
	// Overrides is what was applied on top of it, echoed back so that a plan
	// describes itself: every `to` under Repositories came either from Mapping
	// or from one of these.
	Overrides []migrate.Override `json:"overrides"`
	// Unmapped are the hosted labels no pool was proposed for. They are the
	// operator's decision, and the reason a plan can be empty.
	Unmapped []string `json:"unmapped"`
	// Pools is what the mapping step chooses between.
	Pools  []MigrationPoolOption `json:"pools"`
	Counts migrate.Counts        `json:"counts"`
	// Truncated says there are more repositories after this page. It is kept
	// alongside NextCursor because it is what a client reads to know the
	// listing is incomplete, whether or not it can page.
	Truncated bool `json:"truncated"`
	// NextCursor is what to send as Cursor to read the next page. Empty means
	// this was the last one.
	NextCursor string `json:"next_cursor,omitempty"`
	// TotalRepos is how many repositories the installation can see, so a wizard
	// showing a page can say what fraction of the whole it is.
	TotalRepos int `json:"total_repos"`
	// MissingPermissions is what the App still needs before the apply step can
	// work. It is reported here, in the step before, because discovering it
	// halfway through opening pull requests leaves half of them open.
	MissingPermissions []string `json:"missing_permissions"`
	// PermissionHint is the sentence that fixes MissingPermissions.
	PermissionHint string `json:"permission_hint,omitempty"`
	// SettingsURL is where to go and fix it.
	SettingsURL string `json:"settings_url,omitempty"`
}

// MigrationResult is what happened to one repository.
type MigrationResult struct {
	Repo string `json:"repo"`
	// Status is "opened", "skipped" or "failed".
	Status string `json:"status"`
	// PullRequestURL and PullRequestNumber are set when Status is "opened".
	PullRequestURL    string `json:"pull_request_url,omitempty"`
	PullRequestNumber int    `json:"pull_request_number,omitempty"`
	Branch            string `json:"branch,omitempty"`
	// Workflows is how many files the pull request changed.
	Workflows int `json:"workflows"`
	// Jobs is how many runs-on lines it rewrote.
	Jobs int `json:"jobs"`
	// Reason explains a skip or a failure.
	Reason string `json:"reason,omitempty"`
	// Badge says what became of the README badge on a pull request that was
	// opened: "added", "present" when the README already carried it,
	// "no_readme" when there was nowhere Markdown to put it, "unread" when
	// GitHub would not hand the README over, and "off" when the request
	// asked for none. BadgeReason says which of the no_readme and unread
	// cases it was. A badge that could not be added never stops the
	// migration: the runs-on lines are the work, and the badge is the thanks.
	Badge       string `json:"badge,omitempty"`
	BadgeReason string `json:"badge_reason,omitempty"`
}

// The values MigrationResult.Badge takes.
const (
	BadgeAdded    = "added"
	BadgePresent  = "present"
	BadgeNoReadme = "no_readme"
	BadgeUnread   = "unread"
	BadgeOff      = "off"
)

// MigrationOutcome is what applying a migration did.
type MigrationOutcome struct {
	Results []MigrationResult `json:"results"`
	Opened  int               `json:"opened"`
	Skipped int               `json:"skipped"`
	Failed  int               `json:"failed"`
	// Branch is the branch every pull request was opened from, for the audit
	// row; each result carries its own for the wire.
	Branch string `json:"-"`
}

// ---------------------------------------------------------------------------
// Plan
// ---------------------------------------------------------------------------

// PlanMigration works out what a migration would change. It creates nothing.
//
// It answers store.ErrNotFound for an installation that does not exist,
// ErrNoMigrationPool for one with nowhere to migrate to, and GitHub's own
// errors when the App cannot see or read the repositories.
func (c *Controller) PlanMigration(ctx context.Context, req MigrationPlanRequest) (*MigrationPlan, error) {
	inst, client, err := c.migrationClient(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	pools, err := c.migrationPools(ctx, inst.ID)
	if err != nil {
		return nil, fmt.Errorf("listing the pools this installation could migrate to: %w", err)
	}
	if len(pools) == 0 {
		return nil, ErrNoMigrationPool
	}
	overrides, err := normaliseOverrides(req.Overrides)
	if err != nil {
		return nil, err
	}

	repos, next, total, err := migrationRepos(ctx, client, req.Repos, req.Cursor, MaxPlanRepos)
	if err != nil {
		return nil, err
	}

	// Two passes. The first reads every repository and works out which hosted
	// labels are in play; the second applies a mapping to them. They are
	// separate because the mapping the server proposes depends on what the
	// first pass found, and reading each repository twice would double the
	// cost of the most expensive call Zoomies makes.
	sources := readWorkflows(ctx, client, repos)

	// Asking GitHub what this installation may do costs one call, and it is
	// asked before the plans are built rather than after because the answer
	// changes what "no workflows" means. GitHub returns 404 for contents an App
	// may not read, exactly as it does for a repository that has no
	// .github/workflows, so without this an App that was never granted Contents
	// reports every repository in the organisation as having nothing to
	// migrate -- and the operator is told a fact about their repositories
	// instead of about their App.
	var appInfo *github.AppInfo
	if info, err := client.Probe(ctx); err == nil {
		appInfo = info
	}
	blind := appInfo != nil && !appInfo.CanReadContents()

	hosted := hostedLabelsAcross(sources)
	mapping := normaliseMapping(req.Mapping)
	if len(mapping) == 0 {
		mapping = migrate.Suggest(pools, hosted)
	}
	m := migrate.Mapping{Labels: mapping, Overrides: overrides}

	// The labels that mean "this fleet", so a repository somebody already
	// migrated is reported as finished rather than as having nothing in it.
	fleet := migrate.FleetLabels(pools)

	plans := make([]migrate.RepoPlan, 0, len(sources))
	for _, src := range sources {
		failed := src.err
		// An archived repository was never read, and is greyed out for its own
		// reason; every other empty-looking one is only empty as far as an App
		// that cannot see inside it can tell.
		if failed == "" && blind && len(src.workflows) == 0 && !src.repo.Archived {
			failed = "the App may not read this repository's contents, so its workflows were never looked at"
		}
		if failed != "" {
			plans = append(plans, migrate.RepoPlan{
				Repo:          src.repo.FullName,
				DefaultBranch: src.repo.DefaultBranch,
				Error:         failed,
				Archived:      src.repo.Archived,
			})
			continue
		}
		plan := migrate.PlanRepo(src.repo.FullName, src.repo.DefaultBranch, src.workflows, m)
		plan.Archived = src.repo.Archived
		for _, wf := range src.workflows {
			if migrate.UsesAnyLabel(wf.Content, fleet) {
				plan.OnZoomies = true
				break
			}
		}
		plans = append(plans, plan)
	}

	var unmapped []string
	for _, l := range hosted {
		if _, ok := mapping[l]; !ok {
			unmapped = append(unmapped, l)
		}
	}

	out := &MigrationPlan{
		InstallationID:     inst.ID,
		Target:             inst.Target,
		Repositories:       plans,
		HostedLabels:       hosted,
		Mapping:            mapping,
		Overrides:          emptySlice(overrides),
		Unmapped:           emptySlice(unmapped),
		Pools:              poolOptions(pools),
		Counts:             migrate.Count(plans),
		Truncated:          next != "",
		NextCursor:         next,
		TotalRepos:         total,
		MissingPermissions: []string{},
	}
	// What the probe above found, turned into something the operator can act
	// on: "403 halfway through" becomes a sentence in the step before.
	if appInfo != nil {
		if missing := appInfo.MissingForMigration(); len(missing) > 0 {
			out.MissingPermissions = missing
			out.PermissionHint = github.MigrationPermissionHint
			settingsOrg := ""
			if inst.TargetType == store.TargetOrg {
				settingsOrg = inst.Target
			}
			out.SettingsURL = github.SettingsURL(inst.APIBaseURL, appInfo.Slug, settingsOrg)
		}
	}
	return out, nil
}

// ---------------------------------------------------------------------------
// Apply
// ---------------------------------------------------------------------------

// ApplyMigration opens the pull requests a plan described, one repository at a
// time.
//
// It re-reads and re-plans rather than trusting a plan the browser sends back.
// The workflows may have changed since the review step, and the alternative --
// committing content the browser supplied -- would make this a way to write
// arbitrary files into any repository the App can reach. The caller has
// already bounded req.Repos to MaxApplyRepos; an empty mapping is
// ErrNothingMapped.
func (c *Controller) ApplyMigration(ctx context.Context, req MigrationApplyRequest) (*MigrationOutcome, error) {
	mapping := normaliseMapping(req.Mapping)
	overrides, err := normaliseOverrides(req.Overrides)
	if err != nil {
		return nil, err
	}
	// An operator who mapped no label at all but pointed three jobs at a pool
	// by hand has asked for something real, so the question is "would anything
	// move", not "is there a mapping".
	if len(mapping) == 0 && !anyOverrideWrites(overrides) {
		return nil, ErrNothingMapped
	}
	m := migrate.Mapping{Labels: mapping, Overrides: overrides}
	only, err := workflowSelection(req.Workflows)
	if err != nil {
		return nil, err
	}
	_, client, err := c.migrationClient(ctx, req.InstallationID)
	if err != nil {
		return nil, err
	}
	repos, _, _, err := migrationRepos(ctx, client, req.Repos, "", MaxApplyRepos)
	if err != nil {
		return nil, err
	}

	branch := github.BranchName(c.Now())
	title := firstNonEmpty(strings.TrimSpace(req.Title), "Run CI on Zoomies runners")
	commit := firstNonEmpty(strings.TrimSpace(req.CommitMessage), title)

	out := &MigrationOutcome{Results: make([]MigrationResult, 0, len(repos)), Branch: branch}
	// One repository at a time. Opening pull requests is a write against a
	// shared quota, and a burst of them is exactly what GitHub's secondary
	// rate limits exist to stop.
	for _, repo := range repos {
		if err := ctx.Err(); err != nil {
			break
		}
		out.Results = append(out.Results, migrateRepo(ctx, client, repo, m, only[strings.ToLower(repo.FullName)], branch, title, req.Body, commit, req.WantsBadge()))
	}
	for _, res := range out.Results {
		switch res.Status {
		case "opened":
			out.Opened++
		case "failed":
			out.Failed++
		default:
			out.Skipped++
		}
	}
	return out, nil
}

// migrateRepo plans and opens the pull request for one repository.
//
// only, when not nil, is the set of workflow paths the operator chose in this
// repository; every other file is left where it is.
func migrateRepo(ctx context.Context, client github.Client, repo github.Repository,
	m migrate.Mapping, only map[string]bool, branch, title, body, commit string, badge bool) MigrationResult {

	res := MigrationResult{Repo: repo.FullName, Status: "skipped"}
	if repo.Archived {
		res.Reason = "the repository is archived, so it accepts no pull requests"
		return res
	}

	workflows, err := client.ListWorkflows(ctx, repo.FullName)
	if err != nil {
		if errors.Is(err, github.ErrNoWorkflows) {
			res.Reason = "the repository has no .github/workflows"
			return res
		}
		res.Status, res.Reason = "failed", err.Error()
		return res
	}

	plan := migrate.PlanRepo(repo.FullName, repo.DefaultBranch, asMigrateWorkflows(workflows), m)
	if only != nil {
		plan = selectWorkflows(plan, only)
	}
	var files []github.FileChange
	for _, wf := range plan.Workflows {
		if !wf.Changed() {
			continue
		}
		files = append(files, github.FileChange{Path: wf.Path, Content: wf.After, SHA: wf.SHA})
		res.Workflows++
		res.Jobs += len(wf.Rewrites)
	}
	if len(files) == 0 {
		res.Reason = "no job in this repository is on a mapped GitHub-hosted label"
		if only != nil {
			res.Reason = "no job in the workflow files you chose here is on a mapped GitHub-hosted label"
		}
		return res
	}

	// The badge rides along only once there is a pull request to ride: a
	// repository with nothing to move gets no pull request, and a badge is
	// not a reason to open one.
	res.Badge = BadgeOff
	if badge {
		readme, change := badgeChange(ctx, client, repo.FullName)
		res.Badge, res.BadgeReason = readme.Badge, readme.BadgeReason
		if change != nil {
			files = append(files, *change)
		}
	}

	pr, err := client.OpenPullRequest(ctx, github.PullRequestRequest{
		Repo:          repo.FullName,
		Base:          repo.DefaultBranch,
		Head:          branch,
		Title:         title,
		Body:          firstNonEmpty(body, pullRequestBody(plan, res.Badge == BadgeAdded)),
		CommitMessage: commit,
		Files:         files,
	})
	if err != nil {
		// Nothing was opened, so nothing was added: a badge reported on a
		// failed row would be a line that exists nowhere.
		res.Status, res.Reason = "failed", err.Error()
		res.Badge, res.BadgeReason = "", ""
		return res
	}
	res.Status = "opened"
	res.PullRequestURL, res.PullRequestNumber, res.Branch = pr.HTMLURL, pr.Number, pr.Branch
	return res
}

// badgeChange reads a repository's README and works out what adding the
// badge to it would be: the file change to commit, when there is one, and
// the outcome to report either way.
//
// Nothing here fails the migration. A README that cannot be read, or is not
// Markdown, or is missing altogether, is reported and the pull request goes
// ahead without the badge, because an operator who asked for their CI moved
// should get their CI moved.
func badgeChange(ctx context.Context, client github.Client, repo string) (MigrationResult, *github.FileChange) {
	readme, err := client.ReadReadme(ctx, repo)
	switch {
	case errors.Is(err, github.ErrNoReadme):
		return MigrationResult{Badge: BadgeNoReadme, BadgeReason: "the repository has no README"}, nil
	case err != nil:
		return MigrationResult{Badge: BadgeUnread, BadgeReason: err.Error()}, nil
	case !migrate.IsMarkdownReadme(readme.Path):
		return MigrationResult{Badge: BadgeNoReadme, BadgeReason: readme.Path + " is not Markdown, and the badge is a line of Markdown"}, nil
	}
	after, changed := migrate.AddBadge(readme.Content)
	if !changed {
		return MigrationResult{Badge: BadgePresent}, nil
	}
	return MigrationResult{Badge: BadgeAdded}, &github.FileChange{Path: readme.Path, Content: after, SHA: readme.SHA}
}

// pullRequestBody is what somebody reviewing the change reads first.
//
// It says what moved and what did not, because the skips are the part a
// reviewer has to act on: a job left on `${{ matrix.os }}` is still running on
// GitHub's runners after this merges, and nobody should have to work that out
// from the diff. When the badge is in the diff too it says so, and says how to
// take it out, because a line in somebody's README is theirs to decline.
func pullRequestBody(plan migrate.RepoPlan, badge bool) string {
	var b strings.Builder
	b.WriteString("Moves this repository's CI onto self-hosted runners managed by [Zoomies](https://zoomies.sh).\n\n")

	changed := 0
	for _, wf := range plan.Workflows {
		if !wf.Changed() {
			continue
		}
		changed++
		fmt.Fprintf(&b, "### `%s`\n\n", wf.Path)
		for _, rw := range wf.Rewrites {
			if rw.Job != "" {
				fmt.Fprintf(&b, "- `%s`: `%s` → `%s`\n", rw.Job, rw.From, rw.To)
			} else {
				fmt.Fprintf(&b, "- line %d: `%s` → `%s`\n", rw.Line, rw.From, rw.To)
			}
		}
		b.WriteString("\n")
	}

	var skips []migrate.Skip
	for _, wf := range plan.Workflows {
		skips = append(skips, wf.Skips...)
	}
	if len(skips) > 0 {
		b.WriteString("### Left alone\n\n")
		for _, sk := range skips {
			where := sk.Job
			if where == "" {
				where = fmt.Sprintf("line %d", sk.Line)
			}
			fmt.Fprintf(&b, "- `%s` (`%s`): %s\n", where, sk.Value, sk.Reason)
		}
		b.WriteString("\nThose jobs still run on GitHub's runners.\n")
	}
	if badge {
		b.WriteString("\n### The badge\n\n")
		b.WriteString("The README gains one line, so the front page says where CI runs:\n\n")
		b.WriteString(migrate.BadgeMarkdown + "\n\n")
		b.WriteString("It is a badge like any other. Drop that line from this pull request if the README is better without it; nothing else depends on it.\n")
	}
	return b.String()
}

// ---------------------------------------------------------------------------
// Shared plumbing
// ---------------------------------------------------------------------------

// migrationClient resolves the installation and its GitHub client.
func (c *Controller) migrationClient(ctx context.Context, id string) (*store.Installation, github.Client, error) {
	inst, err := c.st.GetInstallation(ctx, strings.TrimSpace(id))
	if err != nil {
		return nil, nil, err
	}
	client, err := c.ClientFor(ctx, inst.ID)
	if err != nil {
		return nil, nil, fmt.Errorf("authenticating as the GitHub App: %w", err)
	}
	return inst, client, nil
}

// migrationPools returns the enabled pools belonging to an installation, which
// are the only places a job could actually be sent.
func (c *Controller) migrationPools(ctx context.Context, installationID string) ([]*store.Pool, error) {
	all, err := c.st.ListPools(ctx)
	if err != nil {
		return nil, err
	}
	var out []*store.Pool
	for _, p := range all {
		if p.InstallationID == installationID && p.Enabled {
			out = append(out, p)
		}
	}
	return out, nil
}

func poolOptions(pools []*store.Pool) []MigrationPoolOption {
	out := make([]MigrationPoolOption, 0, len(pools))
	for _, p := range pools {
		out = append(out, MigrationPoolOption{
			ID:      p.ID,
			Name:    p.Name,
			Labels:  emptySlice(p.Labels),
			RunsOn:  store.RunsOn(p.Labels),
			Enabled: p.Enabled,
		})
	}
	return out
}

// migrationRepos resolves the repositories a request names, or one page of
// what the installation can see when it names none.
//
// It returns the page, the cursor for the page after it -- empty when there is
// none -- and how many repositories the installation can see in total, so the
// wizard can say which slice of an organisation is on screen and go and get
// the next one. Paging rather than one big scan is deliberate: reading every
// workflow file in a thousand repositories is the most expensive thing Zoomies
// asks GitHub for, and it spends the quota the scheduler shares.
func migrationRepos(ctx context.Context, client github.Client, named []string, cursor string, limit int) ([]github.Repository, string, int, error) {
	all, err := client.ListRepositories(ctx, 0)
	if err != nil {
		return nil, "", 0, err
	}
	byName := make(map[string]github.Repository, len(all))
	for _, r := range all {
		byName[strings.ToLower(r.FullName)] = r
	}

	if len(named) > 0 {
		out := make([]github.Repository, 0, len(named))
		for _, want := range named {
			want = strings.TrimSpace(want)
			if want == "" {
				continue
			}
			repo, ok := byName[strings.ToLower(want)]
			if !ok {
				// A repository the App cannot see is named, not silently
				// dropped: the operator picked it, and it disappearing from the
				// results with no explanation is worse than a failure.
				return nil, "", 0, fmt.Errorf("%w: this installation cannot see %s; check the App is installed on it", github.ErrNotFound, want)
			}
			out = append(out, repo)
		}
		return out, "", len(out), nil
	}

	// Sorted by the lowercased name, because that is the order the cursor
	// below is compared in. GitHub's names are mixed case, and ordering by raw
	// bytes puts every capitalised name before every lowercase one -- so the
	// search for the cursor would run over an order it does not share, and the
	// repositories between the two orders would appear on no page at all. A
	// repository the wizard never lists is one nobody can migrate.
	sort.Slice(all, func(i, j int) bool {
		return strings.ToLower(all[i].FullName) < strings.ToLower(all[j].FullName)
	})
	total := len(all)

	// The cursor is a name rather than an offset, so a repository added or
	// removed between two pages shifts nothing: the next page is whatever
	// sorts after the last name the operator has already seen.
	if after := strings.ToLower(strings.TrimSpace(cursor)); after != "" {
		i := sort.Search(len(all), func(i int) bool { return strings.ToLower(all[i].FullName) > after })
		all = all[i:]
	}
	if len(all) > limit {
		return all[:limit], all[limit-1].FullName, total, nil
	}
	return all, "", total, nil
}

// workflowSelection turns the apply request's per-repository workflow paths
// into a lookup, refusing anything that is not a file GitHub would run.
//
// A path that is not a workflow is a client bug, and accepting it silently
// would mean a repository whose pull request quietly changes nothing.
func workflowSelection(in map[string][]string) (map[string]map[string]bool, error) {
	if len(in) == 0 {
		return nil, nil
	}
	out := make(map[string]map[string]bool, len(in))
	for repo, paths := range in {
		repo = strings.ToLower(strings.TrimSpace(repo))
		if repo == "" {
			continue
		}
		set := make(map[string]bool, len(paths))
		for _, p := range paths {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			if !migrate.IsWorkflowPath(p) {
				return nil, fmt.Errorf("%w: %q is not one", ErrNotAWorkflow, p)
			}
			set[p] = true
		}
		if len(set) == 0 {
			return nil, fmt.Errorf("%w: %s named none, so leave it out to migrate every file the mapping covers", ErrNotAWorkflow, repo)
		}
		out[repo] = set
	}
	if len(out) == 0 {
		return nil, nil
	}
	return out, nil
}

// selectWorkflows keeps only the files the operator chose, so the pull request
// body still reports the jobs left behind in the files it did touch.
func selectWorkflows(plan migrate.RepoPlan, only map[string]bool) migrate.RepoPlan {
	out := plan
	out.Workflows = make([]migrate.WorkflowPlan, 0, len(plan.Workflows))
	for _, wf := range plan.Workflows {
		if only[wf.Path] {
			out.Workflows = append(out.Workflows, wf)
		}
	}
	return out
}

// workflowSource is one repository's workflows, or why they could not be read.
type workflowSource struct {
	repo      github.Repository
	workflows []migrate.Workflow
	err       string
}

// readWorkflows reads every repository's workflows, a few at a time.
//
// One repository failing is recorded against that repository rather than
// failing the scan: in an organisation of any size there is always one the App
// was removed from, and one with a .github/workflows that is a file rather
// than a directory.
//
// An archived repository is not read at all. Nothing could be opened against
// it whatever its workflows say, and a scan of an organisation that has been
// tidying up for years would otherwise spend most of its GitHub quota on
// repositories the wizard is about to grey out.
func readWorkflows(ctx context.Context, client github.Client, repos []github.Repository) []workflowSource {
	out := make([]workflowSource, len(repos))
	sem := make(chan struct{}, planConcurrency)
	var wg sync.WaitGroup

	for i, repo := range repos {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()

			out[i] = workflowSource{repo: repo}
			if repo.Archived {
				return
			}
			if ctx.Err() != nil {
				out[i].err = "the request was cancelled before this repository was read"
				return
			}
			files, err := client.ListWorkflows(ctx, repo.FullName)
			switch {
			case errors.Is(err, github.ErrNoWorkflows):
				// Not an error: most repositories have no workflows.
			case err != nil:
				out[i].err = err.Error()
			default:
				out[i].workflows = asMigrateWorkflows(files)
			}
		}()
	}
	wg.Wait()
	return out
}

func asMigrateWorkflows(files []github.WorkflowFile) []migrate.Workflow {
	out := make([]migrate.Workflow, 0, len(files))
	for _, f := range files {
		if !migrate.IsWorkflowPath(f.Path) {
			continue
		}
		out = append(out, migrate.Workflow{Path: f.Path, SHA: f.SHA, Content: f.Content})
	}
	return out
}

// hostedLabelsAcross collects every GitHub-hosted label the scan found, sorted
// so the mapping step is in the same order every time it is opened.
func hostedLabelsAcross(sources []workflowSource) []string {
	seen := map[string]bool{}
	var out []string
	for _, src := range sources {
		for _, wf := range src.workflows {
			for _, l := range migrate.HostedLabelsIn(wf.Content) {
				if !seen[l] {
					seen[l] = true
					out = append(out, l)
				}
			}
		}
	}
	sort.Strings(out)
	return out
}

// normaliseOverrides trims the overrides a request carries and refuses the ones
// that name nothing.
//
// A malformed override is refused rather than dropped. The operator picked that
// job on the review screen, and a migration that quietly ignored the exception
// they asked for -- sending the job to the consolidated pool instead -- is the
// kind of surprise every other decision in this file is shaped to avoid.
func normaliseOverrides(in []migrate.Override) ([]migrate.Override, error) {
	out := make([]migrate.Override, 0, len(in))
	seen := make(map[string]bool, len(in))
	for i, o := range in {
		o = migrate.Override{
			Repo: strings.TrimSpace(o.Repo),
			Path: strings.TrimSpace(o.Path),
			Job:  strings.TrimSpace(o.Job),
			To:   strings.TrimSpace(o.To),
		}
		switch {
		case o.Repo == "":
			return nil, fmt.Errorf("%w, and override %d names no repository", ErrBadOverride, i+1)
		case o.Job == "":
			// Not every runs-on can be attributed to a job, and one that cannot
			// has no name that survives the file being read again at apply time.
			return nil, fmt.Errorf("%w, and override %d names no job; a runs-on the plan could not attribute to one cannot be overridden", ErrBadOverride, i+1)
		case !migrate.IsWorkflowPath(o.Path):
			return nil, fmt.Errorf("%w, and override %d names %q, which is not a workflow file GitHub runs", ErrBadOverride, i+1, o.Path)
		}
		key := strings.ToLower(o.Repo) + "\x00" + o.Path + "\x00" + o.Job
		if seen[key] {
			// Two answers for one job is not a preference, it is a bug in
			// whatever built the request, and picking one of them silently
			// would hide it.
			return nil, fmt.Errorf("%w, and %s in %s is overridden twice", ErrBadOverride, o.Job, o.Path)
		}
		seen[key] = true
		out = append(out, o)
	}
	return out, nil
}

// anyOverrideWrites reports whether any override would actually move a job. One
// that says "stay where you are" is a decision, but it is not a reason to open
// a pull request.
func anyOverrideWrites(in []migrate.Override) bool {
	for _, o := range in {
		if o.To != "" {
			return true
		}
	}
	return false
}

// normaliseMapping lowercases the keys and drops the entries the browser sends
// for a label the operator chose not to map, which arrive as empty strings.
func normaliseMapping(in map[string]string) map[string]string {
	out := make(map[string]string, len(in))
	for k, v := range in {
		k, v = strings.ToLower(strings.TrimSpace(k)), strings.TrimSpace(v)
		if k == "" || v == "" {
			continue
		}
		out[k] = v
	}
	return out
}

package controller

import (
	"fmt"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/migrate"
	"github.com/eyupio/zoomies/internal/store"
)

// Paging through an organisation has to reach every repository in it, whatever
// case its name is written in.
//
// The cursor is a repository name, and it is compared in lowercase so that the
// one the browser sends back matches whatever GitHub returned. That only works
// if the listing is ordered the same way: sorted by raw bytes, every
// capitalised name sorts before every lowercase one, the binary search for the
// cursor runs over an order it does not share, and the repositories caught
// between the two are returned on no page at all. They are not merely
// misordered -- they are unreachable, and a repository the wizard never lists
// is one nobody can migrate.
func TestMigrationPagingReachesEveryRepositoryWhateverItsCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	// Names GitHub would really return: some capitalised, some not, mixed
	// together so that no single ordering happens to work by luck.
	var want []string
	for i := 0; i < 12; i++ {
		name := fmt.Sprintf("acme/repo%02d", i)
		if i%2 == 0 {
			name = fmt.Sprintf("acme/Repo%02d", i)
		}
		h.gh.AddRepo(name)
		want = append(want, strings.ToLower(name))
	}

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	// A page size that does not divide the fleet evenly, so the last page is a
	// partial one and the cursor is exercised more than once.
	const perPage = 5
	seen := map[string]int{}
	cursor := ""
	for page := 0; ; page++ {
		if page > len(want) {
			t.Fatalf("paging did not terminate after %d pages", page)
		}
		repos, next, total, err := migrationRepos(h.ctx, client, nil, cursor, perPage)
		if err != nil {
			t.Fatalf("migrationRepos(cursor=%q): %v", cursor, err)
		}
		if total != len(want) {
			t.Errorf("total = %d on page %d, want %d: the wizard reports which slice of the organisation is on screen", total, page, len(want))
		}
		for _, r := range repos {
			seen[strings.ToLower(r.FullName)]++
		}
		if next == "" {
			break
		}
		cursor = next
	}

	for _, name := range want {
		switch seen[name] {
		case 1:
		case 0:
			t.Errorf("%s appeared on no page, so it can never be migrated", name)
		default:
			t.Errorf("%s appeared on %d pages, so the wizard offers it twice", name, seen[name])
		}
	}
}

// The cursor is matched without regard to case, so a client that lowercases the
// name it was handed still gets the page after it rather than a repeat of the
// one it has.
func TestMigrationPagingAcceptsACursorInAnyCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	for _, name := range []string{"acme/Alpha", "acme/Bravo", "acme/Charlie", "acme/Delta"} {
		h.gh.AddRepo(name)
	}

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	first, next, _, err := migrationRepos(h.ctx, client, nil, "", 2)
	if err != nil {
		t.Fatalf("first page: %v", err)
	}
	if next == "" {
		t.Fatalf("first page of four repositories at two a page says it is the whole organisation")
	}

	for _, cursor := range []string{next, strings.ToLower(next), strings.ToUpper(next)} {
		rest, _, _, err := migrationRepos(h.ctx, client, nil, cursor, 2)
		if err != nil {
			t.Fatalf("second page (cursor %q): %v", cursor, err)
		}
		for _, r := range rest {
			for _, had := range first {
				if strings.EqualFold(r.FullName, had.FullName) {
					t.Errorf("cursor %q returned %s again, which the operator has already seen", cursor, r.FullName)
				}
			}
		}
	}
}

// A repository the operator named by hand is matched without regard to case:
// GitHub resolves a repository URL that way, and an operator who typed the name
// into the wizard should not be told their own repository does not exist.
func TestMigrationReposMatchesANamedRepositoryWhateverItsCase(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.gh.AddRepo("acme/Widgets")

	client, err := h.c.ClientFor(h.ctx, inst.ID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	for _, named := range []string{"acme/Widgets", "acme/widgets", "ACME/WIDGETS"} {
		repos, next, total, err := migrationRepos(h.ctx, client, []string{named}, "", MaxPlanRepos)
		if err != nil {
			t.Fatalf("migrationRepos(%q): %v", named, err)
		}
		if len(repos) != 1 || !strings.EqualFold(repos[0].FullName, "acme/Widgets") {
			t.Fatalf("migrationRepos(%q) = %v, want the one repository", named, repos)
		}
		// A named request is not a page of a listing: there is nothing after it.
		if next != "" || total != 1 {
			t.Errorf("migrationRepos(%q) = cursor %q total %d, want no cursor and a total of 1", named, next, total)
		}
	}
}

// A pool that belongs to another installation is not somewhere this one's jobs
// could be sent, so it is not offered as a migration target. Getting this wrong
// would point one organisation's workflows at another's runners.
func TestMigrationPoolsAreScopedToTheirInstallation(t *testing.T) {
	h := newHarness(t)
	mine := h.installation()
	theirs := h.installationOn("globex", store.TargetOrg)

	wanted := h.pool(mine, "mine-linux")
	h.pool(theirs, "theirs-linux")

	disabled := h.pool(mine, "mine-windows")
	disabled.Enabled = false
	if err := h.st.UpdatePool(h.ctx, disabled); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}

	pools, err := h.c.migrationPools(h.ctx, mine.ID)
	if err != nil {
		t.Fatalf("migrationPools: %v", err)
	}
	if len(pools) != 1 || pools[0].ID != wanted.ID {
		var got []string
		for _, p := range pools {
			got = append(got, p.Name)
		}
		t.Fatalf("migrationPools = %v, want only the enabled pool of this installation (%s)", got, wanted.Name)
	}
}

// The badge is on by default and rides in the same pull request as the
// runs-on change, in the README GitHub renders, at the end of the row of
// badges that is already there.
func TestApplyMigrationAddsTheBadgeByDefault(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs:\n  build:\n    runs-on: ubuntu-latest\n")
	h.gh.AddFile("acme/widgets", "README.md", "# Widgets\n\n[![CI](https://x/ci.svg)](https://x)\n\nProse.\n")

	out, err := h.c.ApplyMigration(h.ctx, MigrationApplyRequest{
		InstallationID: inst.ID,
		Repos:          []string{"acme/widgets"},
		Mapping:        map[string]string{"ubuntu-latest": "zoomies-linux-x64"},
	})
	if err != nil {
		t.Fatalf("ApplyMigration: %v", err)
	}
	if len(out.Results) != 1 || out.Results[0].Status != "opened" {
		t.Fatalf("results = %+v", out.Results)
	}
	res := out.Results[0]
	if res.Badge != BadgeAdded || res.BadgeReason != "" {
		t.Errorf("badge = %q (%q), want %q", res.Badge, res.BadgeReason, BadgeAdded)
	}
	// The pull request changed one workflow file; the README is not counted
	// as one, because "files" on the results screen means workflow files.
	if res.Workflows != 1 || res.Jobs != 1 {
		t.Errorf("workflows=%d jobs=%d, want 1 and 1", res.Workflows, res.Jobs)
	}
	got, _ := h.gh.FileContent("acme/widgets", "README.md")
	want := "# Widgets\n\n[![CI](https://x/ci.svg)](https://x)\n" + migrate.BadgeMarkdown + "\n\nProse.\n"
	if got != want {
		t.Errorf("README on GitHub:\n%s\nwant:\n%s", got, want)
	}
	if wf, _ := h.gh.FileContent("acme/widgets", ".github/workflows/ci.yml"); !strings.Contains(wf, "zoomies-linux-x64") {
		t.Errorf("the workflow was not rewritten alongside the badge: %q", wf)
	}
	if body := h.gh.PullRequestBody("acme/widgets", 1); !strings.Contains(body, migrate.BadgeMarkdown) {
		t.Errorf("the pull request body does not say the badge is in it:\n%s", body)
	}
}

// The README is somebody else's front page, so one word from the operator
// leaves it alone -- and a README that is missing, not Markdown, or already
// badged is reported rather than either failing the migration or being
// written into anyway.
func TestApplyMigrationBadgeIsDeclinedAndReported(t *testing.T) {
	no := false
	cases := map[string]struct {
		readme  string // "" for no README
		path    string
		badge   *bool
		want    string
		touched bool
	}{
		"declined":         {readme: "# W\n", path: "README.md", badge: &no, want: BadgeOff},
		"no readme":        {want: BadgeNoReadme},
		"not markdown":     {readme: "Widgets\n=======\n", path: "README.rst", want: BadgeNoReadme},
		"already there":    {readme: "# W\n\n" + migrate.BadgeMarkdown + "\n", path: "README.md", want: BadgePresent},
		"explicitly asked": {readme: "# W\n", path: "README.md", badge: ptr(true), want: BadgeAdded, touched: true},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			h := newHarness(t)
			inst := h.installation()
			h.pool(inst, "linux-x64", "zoomies-linux-x64")
			h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs:\n  build:\n    runs-on: ubuntu-latest\n")
			if tc.path != "" {
				h.gh.AddFile("acme/widgets", tc.path, tc.readme)
			}
			out, err := h.c.ApplyMigration(h.ctx, MigrationApplyRequest{
				InstallationID: inst.ID,
				Repos:          []string{"acme/widgets"},
				Mapping:        map[string]string{"ubuntu-latest": "zoomies-linux-x64"},
				Badge:          tc.badge,
			})
			if err != nil {
				t.Fatalf("ApplyMigration: %v", err)
			}
			res := out.Results[0]
			if res.Status != "opened" {
				t.Fatalf("the migration itself must go ahead whatever the badge does: %+v", res)
			}
			if res.Badge != tc.want {
				t.Errorf("badge = %q (%q), want %q", res.Badge, res.BadgeReason, tc.want)
			}
			if tc.want == BadgeNoReadme && res.BadgeReason == "" {
				t.Error("no_readme carries no reason, so the results screen cannot say which kind of nowhere")
			}
			if tc.path != "" {
				got, _ := h.gh.FileContent("acme/widgets", tc.path)
				if touched := got != tc.readme; touched != tc.touched {
					t.Errorf("README changed = %v, want %v:\n%s", touched, tc.touched, got)
				}
			}
			if body := h.gh.PullRequestBody("acme/widgets", 1); strings.Contains(body, "### The badge") != tc.touched {
				t.Errorf("the body mentions the badge = %v, want %v", !tc.touched, tc.touched)
			}
		})
	}
}

func ptr[T any](v T) *T { return &v }

package controller

import (
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// EffectiveMinimum is the minimum size a pool's runners are actually held to:
// the pool's own figure on a field where it set one, and otherwise the fleet's
// runners.minimum_cpus / runners.minimum_memory_mb.
//
// The fleet figure is read live rather than copied into the pool when it is
// created, so changing it moves every pool that never said otherwise on the
// next pass -- and saving a pool never freezes today's value into it. A fleet
// minimum at or above a pool's typed standard size means nothing for that pool
// (the same rule the wizard's opening value follows), and is ignored there. On
// an automatic field it applies as-is: below a host's slot share it is how far
// a runner may be reduced, and above it the scheduler gives each runner the
// minimum (scheduler.MinimumSlot).
func EffectiveMinimum(r store.Resources, fleet config.Runners) (cpus float64, memoryMB int64) {
	cpus, memoryMB = r.MinCPUs, r.MinMemoryMB
	if cpus <= 0 && fleet.MinimumCPUs > 0 && (r.CPUs <= 0 || fleet.MinimumCPUs < r.CPUs) {
		cpus = fleet.MinimumCPUs
	}
	if memoryMB <= 0 && fleet.MinimumMemoryMB > 0 && (r.MemoryMB <= 0 || fleet.MinimumMemoryMB < r.MemoryMB) {
		memoryMB = fleet.MinimumMemoryMB
	}
	return cpus, memoryMB
}

// sizingPool returns p as the fleet sizes it: a copy with the inherited
// minimum filled in, or p itself when nothing is inherited. It is for the
// callers that decide or report on a runner's size -- scheduling, room, fit,
// problems -- and never for one that stores, exports or renders the pool's own
// settings: a copy written back would turn "the fleet's figure" into a figure
// of the pool's own, and the fleet setting would stop moving it.
func sizingPool(p *store.Pool, fleet config.Runners) *store.Pool {
	if p == nil {
		return nil
	}
	cpus, memoryMB := EffectiveMinimum(p.Resources, fleet)
	if cpus == p.Resources.MinCPUs && memoryMB == p.Resources.MinMemoryMB {
		return p
	}
	cp := *p
	cp.Resources.MinCPUs, cp.Resources.MinMemoryMB = cpus, memoryMB
	return &cp
}

// sizingPools is sizingPool over a listing, against the settings in force now.
func (c *Controller) sizingPools(pools []*store.Pool) []*store.Pool {
	fleet := c.cfg().Runners
	out := make([]*store.Pool, len(pools))
	for i, p := range pools {
		out[i] = sizingPool(p, fleet)
	}
	return out
}

