import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// host.overprovisioned judges a slot against a core and 2 GB because that is
// what a runner nobody sized needs to do real work. A pool whose operator set
// a minimum below that has been sized: its runners are accepted at the
// minimum, and a host whose slots each cover it is a host the pool runs on as
// configured. Calling it too small -- the report this test exists for -- sends
// the operator to lower a capacity the fleet is using. The warning stays
// wherever any pool that reaches the host has no such minimum, because that
// pool's runners still get a slot too thin to work in.
func TestAHostWhoseSlotsCoverEveryPoolsMinimumIsNotOverprovisioned(t *testing.T) {
	small := store.Resources{CPUs: 1, MemoryMB: 2048, MinCPUs: 0.5, MinMemoryMB: 1024}
	tests := []struct {
		name  string
		pools []store.Resources
		warn  bool
	}{
		{"with no pool the default judgement stands", nil, true},
		{"a pool with a minimum the slots cover raises nothing", []store.Resources{small}, false},
		{"a pool without a minimum beside it keeps the warning", []store.Resources{small, {CPUs: 1, MemoryMB: 2048}}, true},
		{"a minimum above the slot share keeps the warning", []store.Resources{{CPUs: 1, MemoryMB: 2048, MinMemoryMB: 1536}}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			// Two cores less the reserve and 4 GB less the reserve: one slot
			// at a core and 2 GB, three at half a core and 1 GB.
			h.measuredHost("small", 2, 4096, 3, enforcesEverything)
			inst := h.installation()
			for i, r := range tc.pools {
				p := h.pool(inst, "pool-"+string(rune('a'+i)))
				p.Resources = r
				if err := h.st.UpdatePool(h.ctx, p); err != nil {
					t.Fatal(err)
				}
			}
			got := contains(h.problemCodes(), "host.overprovisioned")
			if got != tc.warn {
				t.Errorf("host.overprovisioned raised = %v, want %v", got, tc.warn)
			}
			if tc.warn && len(tc.pools) > 0 {
				p := h.problem(t, "host.overprovisioned")
				if strings.Contains(p.Fix, "capacity to 3") {
					t.Errorf("fix %q names the capacity the host already has", p.Fix)
				}
			}
		})
	}
}

package controller

import (
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"time"
)

type placementIntent struct {
	At      time.Time
	Version uint64
	Starts  map[string]map[string]int
}

// Publish immutable admission intent. Boosts can reserve the selected hosts
// rather than every host compatible with the same queued job. Unknown or stale
// intent still uses the conservative queue-based fallback.
func (c *Controller) rememberPlacement(s scheduler.Snapshot, p scheduler.Plan, version uint64) {
	v := &placementIntent{At: s.Now, Version: version, Starts: map[string]map[string]int{}}
	add := func(host, pool string) {
		if v.Starts[host] == nil {
			v.Starts[host] = map[string]int{}
		}
		v.Starts[host][pool]++
	}
	for pool, rs := range s.Runners {
		for _, r := range rs {
			if r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering {
				add(r.HostID, pool)
			}
		}
	}
	for _, pp := range p.Pools {
		for _, a := range pp.Actions {
			if a.Kind == scheduler.ActionCreate {
				add(a.HostID, pp.PoolID)
			}
		}
	}
	c.placement.Store(v)
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// rateLimitBackoff is how long to stand down from an installation when GitHub
// says it is out of quota and does not say when that ends. Polling and reaping
// are background paths; spending the last of an installation's quota on them
// would take the webhook path's own API calls -- minting JIT configs -- down
// with it.
const rateLimitBackoff = 15 * time.Minute

const (
	// rateLimitSlack is added to a reset GitHub named. Resuming on the exact
	// second races its own accounting and buys another refusal, which costs
	// the call and starts the wait again.
	rateLimitSlack = 5 * time.Second

	// maxRateLimitBackoff caps a stand-down however far away the reset says it
	// is. GitHub's primary window is an hour, so anything beyond that is a
	// clock out of step or a proxy inventing a header -- and taking an
	// installation out of service for a day on either would be a far worse
	// failure than one more refused call.
	maxRateLimitBackoff = time.Hour
)

// rateLimitHold is when an installation refused for quota may be used again.
//
// GitHub sends the answer on the response, so the fixed backoff is only what
// to do when it did not: waiting a flat fifteen minutes for a quota that came
// back in two wastes the difference on every sweep, and for one that comes
// back in fifty spends the rest of the window discovering that again.
func rateLimitHold(err error, now time.Time) time.Time {
	until, ok := github.RetryAfterRateLimit(err, now)
	if !ok {
		return now.Add(rateLimitBackoff)
	}
	until = until.Add(rateLimitSlack)
	if capped := now.Add(maxRateLimitBackoff); until.After(capped) {
		return capped
	}
	return until
}

// pollLoop is the webhook fallback.
//
// A controller behind NAT, or one whose webhook secret was mistyped, would
// otherwise stop scaling silently, and a fleet that has quietly stopped
// scaling looks exactly like a quiet fleet.
func (c *Controller) pollLoop(ctx context.Context) {
	if !c.cfg().GitHub.PollFallback {
		c.log.Info("the fallback poller is off; scaling depends entirely on webhooks reaching this controller")
		return
	}
	interval := c.pollInterval()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			// The poller exists to find work this fleet should run. A fenced
			// fleet is not going to run any, and sweeping would spend the
			// installation's GitHub quota to learn something it cannot act on.
			if !c.Fenced().Fenced {
				c.discoverJobs(ctx)
				c.polls.Add(1)
			}
		case <-c.pollSettingsChanged:
			// github.poll_interval is a runtime setting. The timer was built
			// from the old value, so it is rebuilt here rather than left to
			// fire once more on the old interval.
		}
		if d := c.pollInterval(); d != interval {
			interval = d
			ticker.Reset(d)
		}
	}
}

func (c *Controller) pollInterval() time.Duration {
	if d := c.cfg().GitHub.PollInterval; d > 0 {
		return d
	}
	return 30 * time.Second
}

// pollOnce lists unfinished jobs for every installation and records what it
// finds.
//
// Queue discovery skips installations with recent webhooks. Known unfinished
// jobs are checked separately in bounded pages so a missing completion cannot
// be hidden by unrelated deliveries.
func (c *Controller) pollOnce(ctx context.Context) {
	c.reconcileKnownJobs(ctx, c.Now())
	c.discoverJobs(ctx)
}

func (c *Controller) discoverJobs(ctx context.Context) {
	now := c.Now()

	// Accepted deliveries only: one that was rejected recorded a job for
	// nobody, and a run of them is the mistyped-secret case this poller is
	// the safety net for.
	//
	// The fleet-wide answer is only used to say whether a webhook has ever
	// arrived, which the Overview reports about the deployment rather than
	// about any one installation. What to poll is decided per installation
	// below.
	last, err := c.st.LastAcceptedDeliveryAt(ctx)
	if err != nil {
		c.log.Error("could not tell when the last webhook arrived", "error", err)
		return
	}
	c.pollingOnly.Store(last.IsZero())

	fresh, err := c.st.InstallationsFreshSince(ctx, now.Add(-2*c.pollInterval()))
	if err != nil {
		c.log.Error("could not tell which installations webhooks are arriving for", "error", err)
		return
	}

	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		c.log.Error("could not list installations to poll", "error", err)
		return
	}

	found, changed := 0, 0
	for _, inst := range insts {
		if ctx.Err() != nil {
			return
		}
		if IsDemoID(inst.ID) {
			// The demo fixtures are already in the database; there is nothing
			// to poll for, and trying would log a credential failure on every
			// tick of a demo instance.
			continue
		}
		if c.githubHeld(inst.ID, now) {
			continue
		}
		// Skip discovery for this installation when its deliveries are fresh.
		// Known job reconciliation above remains independent of that signal.
		if fresh[inst.ID] {
			continue
		}
		client, err := c.clients.get(ctx, inst)
		if err != nil {
			c.log.Warn("skipping an installation while polling", "installation", inst.ID, "error", err)
			continue
		}
		jobs, err := client.ListQueuedJobs(ctx)
		c.observeGitHub(inst.ID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				// Hold this installation only. Its quota is its own, and the
				// sweep abandoning the rest would let one organisation out of
				// quota stop every other one from scaling.
				until := rateLimitHold(err, now)
				c.holdGitHub(inst.ID, until)
				c.log.Warn("GitHub rate-limited the fallback poller for an installation; standing down for it",
					"installation", inst.ID, "until", until.UTC().Format(time.RFC3339), "error", err)
				continue
			}
			c.log.Warn("could not poll for queued jobs", "installation", inst.ID, "error", err)
			continue
		}
		found += len(jobs)
		n, err := c.ingestQueuedJobs(ctx, inst, jobs)
		if err != nil {
			c.log.Error("could not record polled jobs", "installation", inst.ID, "error", err)
			continue
		}
		changed += n
	}

	if found > 0 {
		c.log.Debug("polled GitHub for queued jobs", "found", found, "new_or_changed", changed)
	}
	if changed > 0 {
		c.Nudge()
	}

	// Stamped here, at the end, rather than in the loop that calls this: what
	// an operator wants to know is when the poller last got all the way round,
	// and a sweep that returned early because it could not read its own
	// database did not. The early returns above deliberately leave the stamp
	// where it was, so the interval keeps growing and poller.stale fires.
	c.lastPollAt.Store(c.Now().UnixNano())
}

// ingestQueuedJobs folds polled jobs into the same rows the webhook path
// writes, so both paths feed one scheduler and one history.
//
// A job is attributed to the installation covering its repository, resolved
// the same way the webhook path resolves it, rather than to the installation
// this poll happened to come from. The two are usually the same and are not
// always: an organisation installation and a repository one can both cover a
// repository, and if each path picked its own answer the job's installation
// would flip with every delivery. The polled installation is the fallback,
// because it did report the job.
//
// The count returned is of jobs left waiting, which is what the caller wakes
// the scheduler for. A job found already running is handed to
// ingestStartedJob, which wakes it itself.
func (c *Controller) ingestQueuedJobs(ctx context.Context, polled *store.Installation, jobs []github.QueuedJob) (int, error) {
	if len(jobs) == 0 {
		return 0, nil
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return 0, fmt.Errorf("listing pools to match polled jobs: %w", err)
	}

	changed := 0
	for _, q := range jobs {
		if store.JobState(q.Status) == store.JobInProgress {
			c.ingestStartedJob(ctx, q)
			continue
		}
		job := &store.Job{
			GitHubJobID:    q.ID,
			GitHubRunID:    q.RunID,
			RunNumber:      q.RunNumber,
			Repo:           q.Repo,
			Workflow:       q.WorkflowName,
			JobName:        q.JobName,
			Labels:         store.NormalizeLabels(q.Labels),
			State:          store.JobQueued,
			InstallationID: c.owningInstallation(ctx, q.Repo, polled),
			RunnerName:     q.RunnerName,
			HTMLURL:        q.HTMLURL,
			QueuedAt:       q.QueuedAt,
		}
		if job.QueuedAt.IsZero() {
			job.QueuedAt = c.Now()
		}
		if p := scheduler.BestPool(pools, job); p != nil {
			job.PoolID = p.ID
			job.Matched = true
		}
		saved, change, err := c.st.ApplyJob(ctx, job)
		if err != nil {
			c.log.Warn("could not record a polled job", "github_job_id", q.ID, "error", err)
			continue
		}
		c.recordJobChange(ctx, saved, change, sourcePoller, nil)
		if saved.State == store.JobQueued {
			changed++
		}
		c.publishJob(ctx, saved)
	}
	return changed, nil
}

// ingestStartedJob records a job a sweep found running on one of this fleet's
// runners before anything here had recorded it as started.
//
// Without webhooks that is the ordinary case, not a rare one: an idle runner
// takes a job within a second or two of GitHub queuing it, far inside the
// sweep interval, so the job is never seen queued at all. Nothing else moves a
// runner to busy, and reconcileKnownJobs only rechecks rows that exist, so the
// runner stayed idle on paper for the whole build and stood in for the next
// queued job, which then waited for a runner the pool had room to start.
//
// It goes through applyWorkflowJob because that is what a delivered
// in_progress would have gone through: one owner for the job row, the runner
// link and the busy transition, with the store refusing to move either
// backwards. Two cases are left where they were. A job this controller already
// has as started or finished belongs to reconcileKnownJobs, and applying it
// again on every sweep would cost a write and a scheduling pass per running
// job for nothing. A job running somewhere else occupies nothing here, and a
// row for it would never be reconciled to a completion.
func (c *Controller) ingestStartedJob(ctx context.Context, q github.QueuedJob) {
	if q.RunnerName == "" {
		return
	}
	known, err := c.st.GetJobByGitHubID(ctx, q.ID)
	switch {
	case err == nil:
		if known.State == store.JobInProgress || known.State == store.JobCompleted {
			return
		}
	case !errors.Is(err, store.ErrNotFound):
		c.log.Warn("could not look up a polled running job", "github_job_id", q.ID, "error", err)
		return
	}
	if _, err := c.st.GetRunnerByName(ctx, q.RunnerName); err != nil {
		if !errors.Is(err, store.ErrNotFound) {
			c.log.Warn("could not look up the runner of a polled running job",
				"github_job_id", q.ID, "runner", q.RunnerName, "error", err)
		}
		return
	}
	started := &github.WorkflowJobEvent{
		Action:       string(store.JobInProgress),
		JobID:        q.ID,
		RunID:        q.RunID,
		Repo:         q.Repo,
		WorkflowName: q.WorkflowName,
		JobName:      q.JobName,
		Labels:       q.Labels,
		RunnerName:   q.RunnerName,
		Status:       q.Status,
		QueuedAt:     q.QueuedAt,
		HTMLURL:      q.HTMLURL,
	}
	if q.StartedAt != nil {
		started.StartedAt = *q.StartedAt
	}
	if err := c.applyWorkflowJob(ctx, started, sourcePoller); err != nil {
		c.log.Warn("could not record a polled running job", "github_job_id", q.ID, "error", err)
	}
}

// holdRateLimited stands every background sweep down from one installation for
// as long as GitHub asked, and says so once.
func (c *Controller) holdRateLimited(id string, err error, now time.Time, doing string) {
	until := rateLimitHold(err, now)
	c.holdGitHub(id, until)
	c.log.Warn("GitHub rate-limited this installation; standing down from it",
		"installation", id, "while", doing, "until", until.UTC().Format(time.RFC3339), "error", err)
}

// githubHeld reports whether an installation is inside its rate-limit backoff,
// clearing the hold once it has expired so the map does not grow with the
// installations that have long since recovered.
func (c *Controller) githubHeld(id string, now time.Time) bool {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	until, ok := c.githubPaused[id]
	if !ok {
		return false
	}
	if !now.Before(until) {
		delete(c.githubPaused, id)
		return false
	}
	return true
}

// heldInstallations lists the installations currently inside a rate-limit
// backoff, with the moment each may be used again.
//
// Expired holds are dropped here as they are in githubHeld, so a caller that
// only reads never leaves the map growing with installations that recovered
// hours ago.
func (c *Controller) heldInstallations(now time.Time) map[string]time.Time {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	held := make(map[string]time.Time, len(c.githubPaused))
	for id, until := range c.githubPaused {
		if !now.Before(until) {
			delete(c.githubPaused, id)
			continue
		}
		held[id] = until
	}
	return held
}

// holdGitHub stands the poller down for one installation until a moment.
func (c *Controller) holdGitHub(id string, until time.Time) {
	c.githubMu.Lock()
	defer c.githubMu.Unlock()
	if c.githubPaused == nil {
		c.githubPaused = map[string]time.Time{}
	}
	c.githubPaused[id] = until
}

// owningInstallation is the installation covering a repository, with a
// fallback for the caller that already knows one. A lookup failure is not
// worth abandoning an ingest over: the poller's own installation is a worse
// answer than the repository's and a much better one than none.
func (c *Controller) owningInstallation(ctx context.Context, repo string, fallback *store.Installation) string {
	if owner, err := c.st.FindInstallationByTarget(ctx, repo); err == nil {
		return owner.ID
	} else if !errors.Is(err, store.ErrNotFound) {
		c.log.Warn("could not resolve the installation covering a polled repository",
			"repo", repo, "error", err)
	}
	return installationID(fallback)
}

// A healthy stream of unrelated webhooks does not prove every completion was
// delivered. Check a rotating, bounded page of older unfinished jobs even when
// queue discovery stands down. A 404 or API failure is not a cancellation.
func (c *Controller) reconcileKnownJobs(ctx context.Context, now time.Time) {
	const batch = 10
	cutoff := now.Add(-2 * time.Minute)
	offset := int(c.jobPollOffset.Load())
	jobs, total, err := c.st.ListJobs(ctx, store.JobFilter{
		States: []store.JobState{store.JobQueued, store.JobInProgress}, Until: &cutoff, ManagedOnly: true,
	}, store.Page{Limit: batch, Offset: offset})
	if err != nil {
		c.log.Warn("could not list jobs to reconcile", "error", err)
		return
	}
	next := offset + len(jobs)
	if next >= total {
		next = 0
	}
	c.jobPollOffset.Store(int64(next))
	for _, j := range jobs {
		if ctx.Err() != nil {
			return
		}
		if j.InstallationID == "" || IsDemoID(j.InstallationID) || c.githubHeld(j.InstallationID, now) {
			continue
		}
		inst, err := c.st.GetInstallation(ctx, j.InstallationID)
		if err != nil {
			continue
		}
		client, err := c.clients.get(ctx, inst)
		if err != nil {
			continue
		}
		checkCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		remote, err := client.GetWorkflowJob(checkCtx, j.Repo, j.GitHubJobID)
		cancel()
		c.observeGitHub(inst.ID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(inst.ID, err, now, "reconciling jobs")
			}
			c.log.Warn("could not reconcile workflow job", "job", j.ID, "error", err)
			continue
		}
		if remote.State() != store.JobCompleted && remote.State() != store.JobInProgress {
			continue
		}
		if err := c.applyWorkflowJob(ctx, remote, sourcePoller); err != nil {
			c.log.Warn("could not update reconciled workflow job", "job", j.ID, "error", err)
		}
	}
}

// jobRecoveryLoop is the single owner of checking known unfinished jobs against
// GitHub, and it runs whether or not the fallback poller is on.
//
// That check is not about discovering queued work; it is the only thing that
// notices a completion whose webhook never arrived, and an in-progress job
// nothing ever completes counts against its repository's scale-up limit for
// ever and keeps its runner's host from being cleaned up. Nothing else may
// call it on a timer: a second caller doubles every GitHub call and races on
// the rotation offset. A fleet that has lost its lease is left alone for the
// same reason the poller leaves it, since it cannot act on what it would learn.
func (c *Controller) jobRecoveryLoop(ctx context.Context) {
	interval := c.pollInterval()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		if c.mayAct() {
			c.reconcileKnownJobs(ctx, c.Now())
			c.recoveries.Add(1)
		}
		if !c.awaitRecoveryTick(ctx, ticker, &interval) {
			return
		}
	}
}

// awaitRecoveryTick blocks until the next sweep is due and reports false when
// the context ended first.
//
// A settings change wakes it too, since this loop spends the most installation
// quota of any and an operator who raises github.poll_interval to relieve a
// rate limit needs it retuned now, not at the next restart. Any setting wakes
// it, so it retunes and keeps waiting rather than sweeping: a change to
// something unrelated must not cost ten GitHub calls.
func (c *Controller) awaitRecoveryTick(ctx context.Context, ticker *time.Ticker, interval *time.Duration) bool {
	for {
		select {
		case <-ctx.Done():
			return false
		case <-ticker.C:
			return true
		case <-c.recoverySettingsChanged:
			if d := c.pollInterval(); d != *interval {
				*interval = d
				ticker.Reset(d)
			}
		}
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

var demoLabels = []string{"self-hosted", "linux", "x64", "demo"}

// startedBetweenSweeps is the race the poller loses by construction: GitHub
// queues a job and an idle runner takes it before any sweep has looked, so the
// first thing this controller can see is a job already in progress.
func (h *harness) startedBetweenSweeps(name string, runner *store.Runner) github.QueuedJob {
	h.t.Helper()
	q := h.gh.AddQueuedJob("acme/widgets", "CI", name, demoLabels)
	h.gh.StartJob(q.ID, runner.Name)
	return q
}

func (h *harness) polledJob(id int64) *store.Job {
	h.t.Helper()
	job, err := h.st.GetJobByGitHubID(h.ctx, id)
	if err != nil {
		h.t.Fatalf("the sweep did not record job %d: %v", id, err)
	}
	return job
}

// A polling-only fleet never sees a job queued when an idle runner takes it
// inside the sweep interval. The runner under it has to go busy all the same,
// or it stands in for the next queued job for the whole build and a pool with
// a free slot leaves that job waiting.
func TestASweepThatFirstSeesAJobRunningTakesItsRunnerBusy(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	running := h.startedBetweenSweeps("build", idle)
	waiting := h.gh.AddQueuedJob("acme/widgets", "CI", "test", demoLabels)

	before := len(h.gh.Requests())
	h.c.pollOnce(h.ctx)

	job := h.polledJob(running.ID)
	if job.State != store.JobInProgress || job.RunnerID != idle.ID || job.StartedAt == nil {
		t.Fatalf("job = %+v, want it in progress on %s with its start recorded", job, idle.ID)
	}
	if job.PoolID != pool.ID || !job.Matched {
		t.Fatalf("job = %+v, want it claimed by %s like any other job of the pool", job, pool.ID)
	}
	runner := h.runnerByID(t, idle.ID)
	if runner.State != store.RunnerBusy || runner.CurrentJobID != job.ID {
		t.Fatalf("runner = %s on job %q, want it busy on %s", runner.State, runner.CurrentJobID, job.ID)
	}
	events := h.timeline(job.ID)
	if last := events[len(events)-1]; last.Kind != store.JobEventStarted || last.Source != sourcePoller || last.RunnerID != idle.ID {
		t.Fatalf("last timeline entry = %+v, want the start, from the poller, on %s", last, idle.ID)
	}
	// It was on the page the sweep had already paid for.
	for _, req := range h.gh.Requests()[before:] {
		if strings.Contains(req, "/actions/jobs/") {
			t.Fatalf("recording a running job cost a lookup of its own: %s", req)
		}
	}

	// And the job still waiting gets a runner of its own, which is the whole
	// point: one busy and one wanted is two, and one is all there is.
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if got := len(h.runners()); got != 2 {
		t.Fatalf("the fleet has %d runners for one running job and one waiting (%d), want 2", got, waiting.ID)
	}
}

// A sweep sees a running job on every pass until it finishes. Only the first
// may say so: a start restamped every thirty seconds would fill the timeline,
// and a write and a scheduling pass per running job is a cost with no end.
func TestASweepRecordsARunningJobOnce(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	running := h.startedBetweenSweeps("build", idle)

	h.c.pollOnce(h.ctx)
	job := h.polledJob(running.ID)
	events := len(h.timeline(job.ID))
	started := *job.StartedAt
	message := h.runnerByID(t, idle.ID).Message

	h.advance(time.Minute)
	h.c.pollOnce(h.ctx)

	job = h.polledJob(running.ID)
	if got := len(h.timeline(job.ID)); got != events {
		t.Fatalf("a second sweep wrote %d more timeline entries", got-events)
	}
	if !job.StartedAt.Equal(started) {
		t.Fatalf("a second sweep moved the start from %v to %v", started, *job.StartedAt)
	}
	runner := h.runnerByID(t, idle.ID)
	if runner.State != store.RunnerBusy || runner.CurrentJobID != job.ID || runner.Message != message {
		t.Fatalf("runner = %s on job %q (%q), want it left busy on %s", runner.State, runner.CurrentJobID, runner.Message, job.ID)
	}
}

// A listing is a snapshot, and one taken before a job finished can be applied
// after the completion was. It must not bring the job back, and it must not
// take a runner busy on work that is over.
func TestAStaleRunningSnapshotDoesNotReopenAFinishedJob(t *testing.T) {
	h := newHarness(t)
	inst, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	running := h.startedBetweenSweeps("build", idle)
	h.c.pollOnce(h.ctx)

	h.gh.CompleteJob(running.ID, "success")
	h.advance(3 * time.Minute)
	h.c.pollOnce(h.ctx)
	job := h.polledJob(running.ID)
	if job.State != store.JobCompleted {
		t.Fatalf("job = %s, want the known-job check to have completed it", job.State)
	}
	after := h.runnerByID(t, idle.ID)
	events := len(h.timeline(job.ID))

	stale := running
	stale.Status = string(store.JobInProgress)
	stale.RunnerName = idle.Name
	if _, err := h.c.ingestQueuedJobs(h.ctx, inst, []github.QueuedJob{stale}); err != nil {
		t.Fatalf("ingestQueuedJobs: %v", err)
	}

	if got := h.polledJob(running.ID); got.State != store.JobCompleted || got.Conclusion != "success" {
		t.Fatalf("a stale snapshot moved the job back to %s (%q)", got.State, got.Conclusion)
	}
	if got := len(h.timeline(job.ID)); got != events {
		t.Fatalf("a stale snapshot wrote %d timeline entries", got-events)
	}
	if got := h.runnerByID(t, idle.ID); got.State != after.State || got.CurrentJobID != after.CurrentJobID {
		t.Fatalf("a stale snapshot moved the runner from %s to %s", after.State, got.State)
	}
}

// A runner is on one job. A snapshot naming it for a second -- a name reused,
// a listing out of step -- must not take it off the job it has.
func TestASweepDoesNotMoveABusyRunnerToAnotherJob(t *testing.T) {
	h := newHarness(t)
	inst, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	first := h.startedBetweenSweeps("build", idle)
	h.c.pollOnce(h.ctx)
	held := h.polledJob(first.ID)

	second := h.gh.AddQueuedJob("acme/widgets", "CI", "test", demoLabels)
	second.Status = string(store.JobInProgress)
	second.RunnerName = idle.Name
	if _, err := h.c.ingestQueuedJobs(h.ctx, inst, []github.QueuedJob{second}); err != nil {
		t.Fatalf("ingestQueuedJobs: %v", err)
	}

	if got := h.runnerByID(t, idle.ID); got.State != store.RunnerBusy || got.CurrentJobID != held.ID {
		t.Fatalf("runner = %s on job %q, want it still busy on %s", got.State, got.CurrentJobID, held.ID)
	}
}

// Most running jobs in an installed repository are on somebody else's runners.
// They occupy nothing here, and a row for one would sit in progress for ever:
// nothing reconciles a job this fleet has no hand in.
func TestASweepLeavesAJobRunningElsewhereAlone(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	elsewhere := h.gh.AddQueuedJob("acme/widgets", "CI", "build", []string{"ubuntu-latest"})
	h.gh.StartJob(elsewhere.ID, "GitHub Actions 7")

	h.c.pollOnce(h.ctx)

	if job, err := h.st.GetJobByGitHubID(h.ctx, elsewhere.ID); err == nil {
		t.Fatalf("the sweep recorded a job running on a runner that is not this fleet's: %+v", job)
	}
}

// The other half of the same race: the sweep did see the job queued, and a
// runner took it before the next one. The known-job check gets there too, but
// not until the job is two minutes old and its turn comes round, and until
// then the runner is idle on paper and free to be stopped as one.
func TestASweepStartsAKnownQueuedJobWithoutWaitingForRecovery(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	q := h.gh.AddQueuedJob("acme/widgets", "CI", "build", demoLabels)
	h.c.pollOnce(h.ctx)
	if job := h.polledJob(q.ID); job.State != store.JobQueued {
		t.Fatalf("job = %s, want it queued before anything took it", job.State)
	}

	h.gh.StartJob(q.ID, idle.Name)
	h.c.pollOnce(h.ctx)

	job := h.polledJob(q.ID)
	if job.State != store.JobInProgress || job.RunnerID != idle.ID {
		t.Fatalf("job = %s on %q, want it in progress on %s", job.State, job.RunnerID, idle.ID)
	}
	if got := h.runnerByID(t, idle.ID); got.State != store.RunnerBusy || got.CurrentJobID != job.ID {
		t.Fatalf("runner = %s on job %q, want it busy on %s", got.State, got.CurrentJobID, job.ID)
	}
	queued, err := h.st.ListQueuedJobs(h.ctx)
	if err != nil || len(queued) != 0 {
		t.Fatalf("a started job still creates demand: %+v, %v", queued, err)
	}
}

// A job the sweep found running has to end the way any other does. Its run
// leaves the listing when it finishes, so the completion can only come from
// the known-job check -- which finds the row because the runner link makes it
// this fleet's -- and that has to release the runner and remove its workload.
func TestAJobFoundRunningIsCompletedAndItsRunnerReleased(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	idle := h.runnerRow(pool, host, store.RunnerIdle)
	running := h.startedBetweenSweeps("build", idle)
	h.c.pollOnce(h.ctx)

	h.gh.CompleteJob(running.ID, "success")
	h.advance(3 * time.Minute)
	h.c.pollOnce(h.ctx)

	job := h.polledJob(running.ID)
	if job.State != store.JobCompleted || job.Conclusion != "success" {
		t.Fatalf("job = %s (%q), want it completed", job.State, job.Conclusion)
	}
	runner := h.runnerByID(t, idle.ID)
	if runner.State == store.RunnerBusy || runner.State == store.RunnerIdle {
		t.Fatalf("runner = %s, want an ephemeral runner finished with its one job", runner.State)
	}
	if !h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
		t.Fatal("nothing was asked to remove the finished runner's workload")
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// The poller is what stops a misconfigured webhook from silently ending the
// fleet's scaling. It feeds the same rows the webhook path writes.
func TestPollerDiscoversQueuedJobs(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	queued := h.gh.AddQueuedJob("acme/widgets", "CI", "build", []string{"self-hosted", "linux", "x64", "demo"})

	h.c.pollOnce(h.ctx)

	job, err := h.st.GetJobByGitHubID(h.ctx, queued.ID)
	if err != nil {
		t.Fatalf("the poller did not record the queued job: %v", err)
	}
	if job.State != store.JobQueued || job.PoolID != pool.ID || !job.Matched {
		t.Fatalf("job = %+v, want it queued and matched to %s", job, pool.ID)
	}
	if !h.c.PollingOnly() {
		t.Fatal("no webhook has ever arrived, so the controller is polling-only and should say so")
	}

	// And the pass that follows creates a runner for it, exactly as the
	// webhook path would.
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if got := len(h.runners()); got != 1 {
		t.Fatalf("created %d runners for the polled job, want 1", got)
	}
}

// When webhooks are working the poller must cost nothing at all -- one local
// query and no GitHub calls -- which is what makes leaving it on by default
// defensible.
func TestPollerStandsDownWhenWebhooksAreRecent(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.gh.AddQueuedJob("acme/widgets", "CI", "build", []string{"self-hosted", "linux", "x64", "demo"})

	// The repository is what credits the delivery to an installation, and a
	// real workflow_job delivery always carries one.
	if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
		DeliveryID: "recent", Event: "workflow_job", Repo: "acme/widgets",
		Status: "accepted", ReceivedAt: time.Now(),
	}); err != nil {
		t.Fatalf("RecordDelivery: %v", err)
	}
	before := len(h.gh.Requests())

	h.c.pollOnce(h.ctx)

	if after := len(h.gh.Requests()); after != before {
		t.Fatalf("the poller made %d GitHub calls despite a webhook arriving seconds ago", after-before)
	}
	if h.c.PollingOnly() {
		t.Fatal("a delivery has arrived, so the controller is not polling-only")
	}
}

// A rejected delivery -- a mistyped webhook secret, say -- records a job for
// nobody. The poller must not take it as proof that webhooks work, or a fleet
// with the wrong secret never starts a runner and never says why.
func TestPollerKeepsGoingWhenDeliveriesAreRejected(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.gh.AddQueuedJob("acme/widgets", "CI", "build", []string{"self-hosted", "linux", "x64", "demo"})

	if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
		DeliveryID: "bad-secret", Event: "workflow_job", Status: "rejected", ReceivedAt: time.Now(),
	}); err != nil {
		t.Fatalf("RecordDelivery: %v", err)
	}
	before := len(h.gh.Requests())

	h.c.pollOnce(h.ctx)

	if after := len(h.gh.Requests()); after == before {
		t.Fatal("the poller stood down on a delivery whose signature did not verify")
	}
	if !h.c.PollingOnly() {
		t.Fatal("no delivery has verified, so the controller is still polling-only")
	}
}

// A rate-limited installation must make the poller stand down rather than
// spend the quota the webhook path's own calls need.
func TestPollerBacksOffWhenRateLimited(t *testing.T) {
	h := newHarness(t)
	inst, _, _ := h.fleet()
	reset := time.Now().Add(time.Hour)
	h.gh.SetRateLimit(5000, 0, reset)
	h.gh.SetError("/installation/repositories", 403, "API rate limit exceeded")

	h.c.pollOnce(h.ctx)

	if !h.c.githubHeld(inst.ID, time.Now()) {
		t.Fatal("the poller did not back off after GitHub reported a rate limit")
	}

	before := len(h.gh.Requests())
	h.c.pollOnce(h.ctx)
	if after := len(h.gh.Requests()); after != before {
		t.Fatalf("the poller made %d more calls while backed off", after-before)
	}
}

// A flat fifteen minutes is either most of a window wasted or most of a window
// spent rediscovering the same refusal. GitHub says when the quota returns, so
// the fixed wait is only what to do when it did not.
func TestAStandDownLastsAsLongAsGitHubAsked(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	reset := now.Add(2 * time.Minute)

	got := rateLimitHold(&github.RateLimitedError{ResetAt: reset}, now)

	// A little past the reset: resuming on the exact second races GitHub's own
	// accounting and buys another refusal.
	if !got.After(reset) {
		t.Fatalf("hold = %v; it must clear the reset at %v", got, reset)
	}
	if got.Sub(reset) > time.Minute {
		t.Fatalf("hold = %v, which is far past the reset at %v", got, reset)
	}
	if got.Sub(now) >= rateLimitBackoff {
		t.Fatalf("hold of %s is no better than the flat %s it replaces", got.Sub(now), rateLimitBackoff)
	}
}

// GitHub does not always say -- an older enterprise server, a proxy that drops
// the headers -- and the fixed wait is what that case still gets.
func TestAStandDownFallsBackToTheFixedWaitWhenGitHubSaysNothing(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)

	got := rateLimitHold(&github.RateLimitedError{}, now)

	if !got.Equal(now.Add(rateLimitBackoff)) {
		t.Fatalf("hold = %v, want the fixed %s", got, rateLimitBackoff)
	}
}

// A reset days away is a clock out of step or a proxy inventing a header.
// Believing it would take an installation out of service until somebody
// noticed, which is a worse failure than one more refused call.
func TestAnAbsurdResetDoesNotParkAnInstallationForEver(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)

	got := rateLimitHold(&github.RateLimitedError{ResetAt: now.Add(72 * time.Hour)}, now)

	if got.Sub(now) > maxRateLimitBackoff {
		t.Fatalf("hold of %s exceeds the %s cap", got.Sub(now), maxRateLimitBackoff)
	}
}

// The stamp is the only evidence that the safety net is still sweeping, so the
// thing to pin is that a sweep writes it -- the failure being designed out is a
// stamp nothing ever moves, which reads as a poller that stopped the moment the
// controller started and would make poller.stale permanent.
func TestACompletedSweepStampsWhenItFinished(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	if !h.c.LastPollAt().IsZero() {
		t.Fatal("a controller that has not swept reported a last poll")
	}

	before := h.c.Now()
	h.c.pollOnce(h.ctx)
	first := h.c.LastPollAt()
	if first.Before(before) {
		t.Fatalf("a completed sweep did not stamp: LastPollAt = %v, sweep started %v", first, before)
	}

	// And it moves with each sweep, or the second one is invisible.
	h.advance(time.Minute)
	h.c.pollOnce(h.ctx)
	if !h.c.LastPollAt().After(first) {
		t.Errorf("a second sweep left the stamp at %v", first)
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

func poolDur(d time.Duration) *store.Duration {
	v := store.Duration(d)
	return &v
}

func warned(problems []Problem, code string) *Problem {
	for i := range problems {
		if problems[i].Code == code {
			return &problems[i]
		}
	}
	return nil
}

// A pool that overrides its provision timeout can re-create, for itself, the
// ladder inversion the fleet's own defaults are held out of.
//
// The fleet's three budgets are kept in order by an invariant test and by the
// validator, and neither of those reaches a pool: a pool may now set the
// provision timeout, the Docker wait, or one without the other. A pool whose
// timeout lands inside the start its own settings ask for condemns runners
// that are still coming up, and the replacement pulls the same image over the
// link that was slow to begin with -- the same outage as the fleet-wide one,
// on the pool that overrode it.
func TestAPoolCannotQuietlyCondemnItsOwnStartingRunners(t *testing.T) {
	cfg := config.Default()

	base := func() *store.Pool {
		return &store.Pool{
			ID: "pool_x", Name: "zoomies-slow", Enabled: true,
			Backend: store.BackendDocker, DockerMode: store.DockerDinD,
		}
	}

	// Following the fleet says nothing: the fleet's own figures are in order,
	// and a warning on every correct pool is one an operator stops reading.
	if w := warned(PoolWarnings(base(), nil, cfg), "pool.provision_timeout_short"); w != nil {
		t.Fatalf("a pool that overrides nothing warned about the fleet's own order: %s", w.Title)
	}

	// A timeout inside the create budget plus this pool's Docker wait does.
	p := base()
	p.RunnerSettings.ProvisionTimeout = poolDur(5 * time.Minute)
	w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short")
	if w == nil {
		t.Fatal("a 5m provision timeout on a pool whose runners wait 2m for Docker after a 15m create budget raised nothing")
	}
	if w.Fix == "" || w.TargetID != p.ID {
		t.Errorf("the warning does not say what to do or which pool it is about: %+v", w)
	}

	// Raised above what a start actually costs, it goes quiet again.
	p.RunnerSettings.ProvisionTimeout = poolDur(30 * time.Minute)
	if w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short"); w != nil {
		t.Errorf("a 30m timeout still warned: %s", w.Title)
	}

	// Zero is "never give up", which cannot condemn anything.
	p.RunnerSettings.ProvisionTimeout = poolDur(0)
	if w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short"); w != nil {
		t.Errorf("a pool that asked for no timeout at all warned: %s", w.Title)
	}
}

// The wait counts only where the pool actually does it. A pool with no daemon
// waits for none, so its start costs the create budget alone -- and a timeout
// that clears that is right, whatever a Docker pool would have needed.
func TestOnlyAPoolWithADaemonIsChargedTheDockerWait(t *testing.T) {
	cfg := config.Default()
	p := &store.Pool{
		ID: "pool_y", Name: "zoomies-plain", Enabled: true,
		Backend: store.BackendDocker, DockerMode: store.DockerNone,
		RunnerSettings: store.RunnerSettings{ProvisionTimeout: poolDur(16 * time.Minute)},
	}
	if w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short"); w != nil {
		t.Errorf("a pool with no daemon was charged a wait it never does: %s", w.Title)
	}

	// The same 16 minutes on a pool that does wait is inside its own start.
	p.DockerMode = store.DockerDinD
	if w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short"); w == nil {
		t.Error("a pool that waits 2m for Docker after a 15m create budget was not warned about a 16m timeout")
	}
}

// A pool's own Docker wait is what its start is measured against, because it
// is what its runners actually do.
func TestAPoolsOwnDockerWaitIsWhatItsStartIsMeasuredAgainst(t *testing.T) {
	cfg := config.Default()
	p := &store.Pool{
		ID: "pool_z", Name: "zoomies-patient", Enabled: true,
		Backend: store.BackendDocker, DockerMode: store.DockerDinD,
		RunnerSettings: store.RunnerSettings{
			ProvisionTimeout: poolDur(20 * time.Minute),
			DockerWait:       poolDur(10 * time.Minute),
		},
	}
	// 15m of create budget plus this pool's own 10m wait is 25m, so 20m is inside it.
	w := warned(PoolWarnings(p, nil, cfg), "pool.provision_timeout_short")
	if w == nil {
		t.Fatal("a pool that waits 10m for Docker was measured against the fleet's 2m")
	}
	if got := PoolEffectiveDockerWait(p, cfg); got != 10*time.Minute {
		t.Errorf("effective docker wait = %s, want the pool's 10m", got)
	}

	// An override of zero hands the wait to the image, which waits two minutes
	// -- not to no wait at all, which is what a bare zero would read as.
	p.RunnerSettings.DockerWait = poolDur(0)
	if got := PoolEffectiveDockerWait(p, cfg); got != config.ImageDockerWait {
		t.Errorf("effective docker wait = %s, want the image's own %s", got, config.ImageDockerWait)
	}
}

// A pool's fixed size can strand the machine its hosts have above their slot
// count, and the info says so with the edit that would take it back.
//
// It is the state a fixed size drifts into as a fleet acquires unequal
// machines: the figure chosen for the first host fits four runners on the
// 64-core one that joined later, and nothing on any page says the pool is why.
// An automatic pool cannot be in that state at all -- dividing a machine by
// its slot count is what fills every slot -- so the info is only ever about a
// size somebody typed.
func TestAFixedSizeSaysWhatItLeavesUnused(t *testing.T) {
	fixed := &store.Pool{
		ID: "pool_fixed", Name: "zoomies-small", Enabled: true,
		Backend:   store.BackendDocker,
		Resources: store.Resources{CPUs: 2, MemoryMB: 4096},
	}
	// Four slots on a machine with room for sixteen runners of this size.
	room := PoolRoom{Hosts: []PoolHostRoom{{
		HostID: "host_1", Host: "big-1",
		Slots: 4, Fits: 16, Room: 4, LimitedBy: "slots",
		CPUs: 32, MemoryMB: 65536, CPUsKnown: true, MemoryKnown: true,
	}}}

	w := warned(PoolRoomWarnings(fixed, room), "pool.size_strands_hosts")
	if w == nil {
		t.Fatal("a 2 CPU pool on a host with room for sixteen of them said nothing")
	}
	if !strings.Contains(w.Detail, "big-1") {
		t.Errorf("the info does not name the host: %s", w.Detail)
	}
	if !strings.Contains(w.Fix, "one slot's share") {
		t.Errorf("the info does not offer the automatic size as the fix: %s", w.Fix)
	}

	// The same fleet, sized by its host, is not stranding anything: the share
	// is the machine divided by the slots, so every slot is usable.
	automatic := &store.Pool{
		ID: "pool_auto", Name: "zoomies-auto", Enabled: true, Backend: store.BackendDocker,
	}
	autoRoom := PoolRoom{Hosts: []PoolHostRoom{{
		HostID: "host_1", Host: "big-1",
		Slots: 4, Fits: 4, Room: 4,
		CPUs: 32, MemoryMB: 65536, CPUsKnown: true, MemoryKnown: true,
	}}}
	if w := warned(PoolRoomWarnings(automatic, autoRoom), "pool.size_strands_hosts"); w != nil {
		t.Errorf("an automatic pool was told its size strands capacity: %s", w.Title)
	}

	// Nor is a fixed pool whose hosts it fills. A note an operator sees on
	// every correct pool is one they stop reading.
	tight := PoolRoom{Hosts: []PoolHostRoom{{
		HostID: "host_2", Host: "right-1",
		Slots: 4, Fits: 4, Room: 4,
		CPUs: 8, MemoryMB: 16384, CPUsKnown: true, MemoryKnown: true,
	}}}
	if w := warned(PoolRoomWarnings(fixed, tight), "pool.size_strands_hosts"); w != nil {
		t.Errorf("a fixed pool that fills its hosts was told otherwise: %s", w.Title)
	}

	// A host that has measured nothing is placed by slots alone and has no
	// share to compare against, so it is never counted as stranded.
	unmeasured := PoolRoom{Hosts: []PoolHostRoom{{
		HostID: "host_3", Host: "old-1", Slots: 4, Fits: 99, Room: 4,
	}}}
	if w := warned(PoolRoomWarnings(fixed, unmeasured), "pool.size_strands_hosts"); w != nil {
		t.Errorf("a host that has measured nothing was counted as stranded: %s", w.Detail)
	}
}

// A pool that overrides neither half says nothing, even when the fleet's own
// figures are in a bad order.
//
// That case is the fleet's finding -- scheduler.provision_timeout_short, which
// names the setting to change -- and repeating it once per pool would bury the
// one sentence that matters under a row for every pool in the fleet, all of
// them pointing at the same fix.
func TestAPoolFollowingTheFleetLeavesTheLadderToTheFleet(t *testing.T) {
	cfg := config.Default()
	// A fleet whose own timeout is inside what a start costs. The validator
	// already says so about the setting.
	cfg.Scheduler.ProvisionTimeout = 5 * time.Minute

	following := &store.Pool{
		ID: "pool_follow", Name: "zoomies-follows", Enabled: true,
		Backend: store.BackendDocker, DockerMode: store.DockerDinD,
	}
	if w := warned(PoolWarnings(following, nil, cfg), "pool.provision_timeout_short"); w != nil {
		t.Errorf("a pool that overrides nothing repeated the fleet's own finding: %s", w.Title)
	}

	// A pool that overrode the Docker wait alone is its own case: the fleet's
	// timeout may have been fine against the fleet's wait and is not against
	// this pool's.
	longWait := &store.Pool{
		ID: "pool_wait", Name: "zoomies-patient", Enabled: true,
		Backend: store.BackendDocker, DockerMode: store.DockerDinD,
		RunnerSettings: store.RunnerSettings{DockerWait: poolDur(30 * time.Minute)},
	}
	if w := warned(PoolWarnings(longWait, nil, cfg), "pool.provision_timeout_short"); w == nil {
		t.Error("a pool that waits 30m for Docker under a 5m timeout said nothing")
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// A repository cache under an organisation installation is only as private
// as the pool's labels, because GitHub can hand an organisation-registered
// runner any repository's job that asks for them. That is a fact about the
// installation, which the pool cannot see in itself, so the warning has to
// come from the pairing -- and must not fire where the installation already
// confines the runner to one repository.
func TestPoolWarningsSayWhenARepositoryCacheIsOnlyAsPrivateAsItsLabels(t *testing.T) {
	cache := store.CacheConfig{Enabled: true, Scope: store.CacheScopeRepository, Repository: "acme/widgets"}
	org := &store.Installation{Target: "acme", TargetType: store.TargetOrg}
	repo := &store.Installation{Target: "acme/widgets", TargetType: store.TargetRepo}

	cases := []struct {
		name string
		pool store.Pool
		inst *store.Installation
		want bool
	}{
		{"repository cache under an organisation", store.Pool{Name: "widgets", Cache: cache}, org, true},
		{"the same cache under a repository installation", store.Pool{Name: "widgets", Cache: cache}, repo, false},
		{"pool scope is a different choice, documented as such", store.Pool{Name: "shared", Cache: store.CacheConfig{Enabled: true, Scope: store.CacheScopePool}}, org, false},
		{"a disabled cache", store.Pool{Name: "plain", Cache: store.CacheConfig{Scope: store.CacheScopeRepository, Repository: "acme/widgets"}}, org, false},
		{"an unknown installation, which validation reports itself", store.Pool{Name: "orphan", Cache: cache}, nil, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var found *Problem
			for _, w := range PoolWarnings(&tc.pool, tc.inst, config.Default()) {
				if w.Code == "pool.cache_shared" {
					w := w
					found = &w
				}
			}
			if (found != nil) != tc.want {
				t.Fatalf("warned = %v, want %v; warnings: %+v", found != nil, tc.want, PoolWarnings(&tc.pool, tc.inst, config.Default()))
			}
			if found == nil {
				return
			}
			// The sentence has to carry the mechanism, the repository at
			// stake and the one thing the operator can do about it.
			for _, want := range []string{"acme/widgets", "labels"} {
				if !strings.Contains(found.Title+found.Detail+found.Fix, want) {
					t.Errorf("the warning does not mention %q: %+v", want, *found)
				}
			}
			if found.Fix == "" || found.TargetID != tc.pool.ID {
				t.Errorf("the warning needs a fix and a target: %+v", *found)
			}
		})
	}
}

// A daemon with no client is not a slower pool: it is a pool where every job
// that touches Docker dies at its first step, with an error naming a missing
// binary and not the reason. The swap moves a pool off the client-less image
// wherever the variant is known to exist, so what reaches this warning is what
// it could not move -- and an operator who pinned that image has to be told,
// because nothing else they can see says why the jobs are failing.
func TestPoolWarningsSayWhenAPoolHasADaemonAndNoClient(t *testing.T) {
	const digest = "@sha256:8c2f1a9e5b3d4c6a7e8f0b1d2c3a4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f"
	cases := []struct {
		name string
		pool store.Pool
		want string // the reference the fix should name, or "" for no warning
	}{
		{"a digest of the stock image", store.Pool{Name: "builders", DockerMode: store.DockerDinD,
			Image: "ghcr.io/eyupio/zoomies-runner" + digest},
			"ghcr.io/eyupio/zoomies-runner-docker" + digest},
		{"a commit pin from another build", store.Pool{Name: "builders", DockerMode: store.DockerDinD,
			Image: "ghcr.io/eyupio/zoomies-runner:sha-b966fb6"},
			"ghcr.io/eyupio/zoomies-runner-docker:sha-b966fb6"},
		{"the host socket needs a client just as much", store.Pool{Name: "builders", DockerMode: store.DockerHostSocket,
			Image: "ghcr.io/eyupio/zoomies-runner:sha-b966fb6"},
			"ghcr.io/eyupio/zoomies-runner-docker:sha-b966fb6"},
		// Everything the swap handles, which is the common case and must stay
		// quiet: a warning that fires on a working pool is a warning nobody
		// reads on the pool where it matters.
		{"a tag the swap moves", store.Pool{Name: "builders", DockerMode: store.DockerDinD,
			Image: "ghcr.io/eyupio/zoomies-runner:latest"}, ""},
		{"a pool that names no image at all", store.Pool{Name: "builders", DockerMode: store.DockerDinD}, ""},
		{"a pool that names an operating system", store.Pool{Name: "builders", DockerMode: store.DockerDinD,
			Platform: store.Platform{OS: "debian", OSVersion: "12"}}, ""},
		{"an image of the operator's own, which may carry one", store.Pool{Name: "builders", DockerMode: store.DockerDinD,
			Image: "registry.example.com/ci/runner:latest"}, ""},
		{"no daemon, nothing to reach", store.Pool{Name: "plain", DockerMode: store.DockerNone,
			Image: "ghcr.io/eyupio/zoomies-runner:sha-b966fb6"}, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var found *Problem
			for _, w := range PoolWarnings(&tc.pool, nil, config.Default()) {
				if w.Code == "pool.docker_client_missing" {
					w := w
					found = &w
				}
			}
			if (found == nil) != (tc.want == "") {
				t.Fatalf("warned = %v, want %v", found != nil, tc.want != "")
			}
			if found == nil {
				return
			}
			if found.Severity != config.SeverityError {
				t.Errorf("severity = %q; every Docker job on this pool fails, which is work not happening", found.Severity)
			}
			// The operator needs the reference to paste, not a repository to
			// go and search for, and the error the jobs are dying with so the
			// two can be connected.
			for _, want := range []string{tc.want, "Unable to locate executable file: docker", tc.pool.Name} {
				if !strings.Contains(found.Title+found.Detail+found.Fix, want) {
					t.Errorf("the warning does not mention %q: %+v", want, *found)
				}
			}
		})
	}
}

// A pool that named no image is running the fleet's default, and no edit to the
// pool corrects a default that cannot be swapped -- so the sentence has to name
// the setting that can be. Telling that operator to "clear the pool's image"
// would be advice they have already taken.
func TestTheDockerClientFixNamesWhicheverSettingCanBeChanged(t *testing.T) {
	const digest = "@sha256:8c2f1a9e5b3d4c6a7e8f0b1d2c3a4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f"
	cfg := config.Default()
	cfg.GitHub.RunnerImage = "ghcr.io/eyupio/zoomies-runner" + digest

	following := store.Pool{Name: "builders", DockerMode: store.DockerDinD}
	own := store.Pool{Name: "builders", DockerMode: store.DockerDinD,
		Image: "ghcr.io/eyupio/zoomies-runner" + digest}

	fix := func(p store.Pool, c *config.Config) string {
		w, ok := dockerClientWarning(&p, c)
		if !ok {
			t.Fatalf("no warning for %+v", p)
		}
		return w.Fix
	}
	if got := fix(following, cfg); !strings.Contains(got, "github.runner_image") {
		t.Errorf("a pool on the fleet's default is told: %q", got)
	}
	if got := fix(own, config.Default()); !strings.Contains(got, "image of pool builders") {
		t.Errorf("a pool with an image of its own is told: %q", got)
	}
}

// A fleet that exists to build container images decides about the privileged
// sidecar once. Repeating it for every such pool on every pass is what teaches
// an operator to skim the problems list, and the list is only worth having
// while it is read -- so the fleet may ask not to be told that one again, and
// only that one.
func TestAFleetCanSayDockerInDockerIsExpected(t *testing.T) {
	quiet := config.Default()
	quiet.Security.DockerInDockerExpected = true

	dangers := func(p store.Pool, cfg *config.Config) []string {
		var out []string
		for _, w := range PoolWarnings(&p, nil, cfg) {
			if w.Code == "pool.dangerous" {
				out = append(out, w.Title)
			}
		}
		return out
	}
	dind := store.Pool{Name: "builders", DockerMode: store.DockerDinD, Ephemeral: true}
	if got := dangers(dind, config.Default()); len(got) != 1 {
		t.Fatalf("a dind pool warns %v by default, want the one sentence", got)
	}
	if got := dangers(dind, quiet); len(got) != 0 {
		t.Errorf("a dind pool still warns once the fleet said it knows: %v", got)
	}

	// What the setting must not silence: the socket hands any job on the pool
	// root on the host, and that is a different decision from wanting Docker.
	socket := store.Pool{Name: "builders", DockerMode: store.DockerHostSocket, Ephemeral: true}
	if got := dangers(socket, quiet); len(got) != 1 {
		t.Errorf("the host socket warns %v, want it said whatever the fleet asked about dind", got)
	}
	persistent := store.Pool{Name: "builders", DockerMode: store.DockerDinD}
	if got := dangers(persistent, quiet); len(got) != 1 {
		t.Errorf("persistent runners warn %v, want the sentence that is not about Docker kept", got)
	}
}

func TestAutomaticPoolWarningsIncludeFleetStartupRecommendations(t *testing.T) {
	cfg := config.Default()
	cfg.Agent.Embedded = true
	cfg.Scheduler.DefaultRunnerLimits = false
	cfg.Scheduler.HostThrottling = false
	cfg.Agent.BootstrapCPUGrace = 0
	cfg.Runners.DockerWait = time.Minute
	cfg.Scheduler.ProvisionTimeout = time.Minute
	p := &store.Pool{Backend: store.BackendDocker, DockerMode: store.DockerDinD}
	wanted := map[string]bool{"scheduler.default_runner_limits": false, "scheduler.host_throttling": false, "agent.bootstrap_cpu_grace": false, "runners.docker_wait": false, "scheduler.provision_timeout": false}
	for _, w := range PoolWarnings(p, nil, cfg) {
		if _, ok := wanted[w.Setting]; ok {
			wanted[w.Setting] = true
		}
	}
	for key, found := range wanted {
		if !found {
			t.Errorf("automatic pool did not explain %s", key)
		}
	}
	p.Resources = store.Resources{CPUs: 2, MemoryMB: 4096}
	for _, w := range PoolWarnings(p, nil, cfg) {
		if w.Code == "scheduler.default_runner_limits_off" {
			t.Fatal("fixed pool received auto sizing remedy")
		}
	}
}

package controller

import (
	"context"
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// How much machine a pool asks for, against the machines it may land on.
//
// HostFit next door answers "could this pool run anywhere at all", which is a
// yes or a no. This answers the question underneath the two settings an
// operator actually gets wrong: how big one runner is, and how many of them
// there may be. A pool of eight-core runners on three four-core boxes is
// valid, matches its hosts and starts nothing; a pool whose maximum is forty
// on a fleet with room for eleven is valid, healthy, and queues twenty-nine
// jobs behind runners that will never be created. Neither is visible anywhere
// a pool is edited unless something counts it.
//
// It is counted on an empty fleet on purpose: what is running right now
// changes with every job, and a size and a cap chosen against this minute's
// occupancy would be re-chosen the next. The question is what the machines can
// hold, which is a property of the machines.

// PoolHostRoom is one host's answer, in the terms the machine was set up in.
type PoolHostRoom struct {
	HostID string `json:"host_id"`
	Host   string `json:"host"`
	// Slots is the host's runner capacity, less any throttle in force.
	Slots int `json:"slots"`
	// Fits is how many runners of this pool the machine has room for,
	// ignoring the slot count -- so a host whose slots outrun its machine can
	// be told from one sized to match.
	Fits int `json:"fits"`
	// Room is what the pool can actually expect here: the smaller of the two.
	Room int `json:"room"`
	// LimitedBy is what ran out first: slots, cpu, memory or disk. It is empty
	// on a host that has measured nothing, where only its slots bind.
	LimitedBy string `json:"limited_by,omitempty"`
	// ChargeCPUs and ChargeMemoryMB are what one runner of this pool costs
	// here, which is not always what the pool says: a docker-in-docker runner
	// is charged for its sidecar too.
	ChargeCPUs     float64 `json:"charge_cpus"`
	ChargeMemoryMB int64   `json:"charge_memory_mb"`
	// The machine less its reserve, which is what the charge is taken from.
	// Zero with the matching known flag false means the agent has not said.
	CPUs        float64 `json:"cpus"`
	MemoryMB    int64   `json:"memory_mb"`
	DiskMB      int64   `json:"disk_mb"`
	CPUsKnown   bool    `json:"cpus_known"`
	MemoryKnown bool    `json:"memory_known"`
	DiskKnown   bool    `json:"disk_known"`
	// ElasticCPU is whether this host's agent can move a live runner's CPU
	// quota. An elastic pool is honoured only where it is true; a runner of
	// one placed elsewhere is held at its share, and nothing but this says so
	// while the pool is still being edited.
	ElasticCPU bool `json:"elastic_cpu"`
}

// Overcommitted reports whether this host promises more slots than the machine
// can back at this pool's size -- the state where the fleet's own capacity
// figures say there is room and every create for that room is refused.
func (r PoolHostRoom) Overcommitted() bool { return r.Slots > r.Fits }

// PoolRoom is the fleet's answer, and the per-host detail behind it.
type PoolRoom struct {
	// Runners is how many runners of this pool the matching hosts could hold
	// between them. It is the number a maximum is worth comparing against.
	Runners int `json:"runners"`
	// Slots is what those hosts' capacities add up to, whatever the size.
	Slots int            `json:"slots"`
	Hosts []PoolHostRoom `json:"hosts"`
	// SmallestDiskMB is the least free disk on any matching host, which is
	// what a cache size limit has to live inside. Known is false when no
	// matching host has measured its disk.
	SmallestDiskMB   int64  `json:"smallest_disk_mb"`
	SmallestDiskHost string `json:"smallest_disk_host,omitempty"`
	DiskKnown        bool   `json:"disk_known"`
}

// Overcommitted is every host promising more slots than it can back.
func (r PoolRoom) Overcommitted() []PoolHostRoom {
	var out []PoolHostRoom
	for _, h := range r.Hosts {
		if h.Overcommitted() {
			out = append(out, h)
		}
	}
	return out
}

// PoolRoom counts the room a pool has across the hosts that can run it.
//
// Only the hosts that could run it at all are counted: a host turned down for
// its backend or its platform has no room for this pool whatever its size, and
// HostFit already says so in its own words. Counting it here would put machine
// the pool can never reach into the number an operator sets a maximum from.
func (c *Controller) PoolRoom(ctx context.Context, p *store.Pool) (PoolRoom, error) {
	p = sizingPool(p, c.cfg().Runners)
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return PoolRoom{}, err
	}
	now := c.Now()
	out := PoolRoom{Hosts: []PoolHostRoom{}}
	for _, h := range hosts {
		if !scheduler.HostSelects(h, p) || !scheduler.HostAvailable(h, now) {
			continue
		}
		if code, _ := HostRefusal(h, p); code != "" && code != ExcludedSize {
			continue
		}
		entry := poolHostRoom(h, p)
		alloc := h.Allocatable()
		out.Hosts = append(out.Hosts, entry)
		out.Runners += entry.Room
		out.Slots += entry.Slots
		if alloc.DiskKnown && (!out.DiskKnown || alloc.DiskMB < out.SmallestDiskMB) {
			out.SmallestDiskMB, out.SmallestDiskHost, out.DiskKnown = alloc.DiskMB, h.Name, true
		}
	}
	return out, nil
}

// poolHostRoom is one host's line in PoolRoom.
//
// The charge is what a runner there is really given. On a machine too small
// for the pool's standard size that is the reduced size the pass places --
// all the host can spare, never below the minimum -- and quoting the standard
// there would tell an operator the pool is charged a size no runner on that
// host is ever created at.
func poolHostRoom(h *store.Host, p *store.Pool) PoolHostRoom {
	room := scheduler.HostRoomFor(h, p)
	alloc := h.Allocatable()
	charge := scheduler.Reserve(p, h)
	whole := scheduler.Reservation{CPUs: alloc.CPUs, MemoryMB: alloc.MemoryMB, DiskMB: alloc.DiskMB}
	if reduced, _, ok := scheduler.ReducedSize(p, h, whole, alloc); ok {
		charge = reduced
	}
	return PoolHostRoom{
		HostID:         h.ID,
		Host:           h.Name,
		Slots:          room.Slots,
		Fits:           room.Fits,
		Room:           room.Room,
		LimitedBy:      room.LimitedBy,
		ChargeCPUs:     charge.CPUs,
		ChargeMemoryMB: charge.MemoryMB,
		CPUs:           alloc.CPUs,
		MemoryMB:       alloc.MemoryMB,
		DiskMB:         alloc.DiskMB,
		CPUsKnown:      alloc.CPUsKnown,
		MemoryKnown:    alloc.MemoryKnown,
		DiskKnown:      alloc.DiskKnown,
		ElasticCPU:     h.Supports(agent.FeatureElasticCPU),
	}
}

// PoolRoomWarnings is what the room says about the pool's own figures.
//
// All three are the same class of failure: a pool that is valid, matches its
// hosts, shows green on every page, and cannot do what its settings promise.
// Nothing else catches them, because each is a disagreement between two
// settings that are correct on their own -- a maximum and a fleet, a host's
// slots and a runner's size, a cache limit and a disk.
func PoolRoomWarnings(p *store.Pool, room PoolRoom) []Problem {
	var out []Problem
	if len(room.Hosts) == 0 {
		// A pool no host can run is already said in the fleet's own words,
		// and saying it again as arithmetic helps nobody.
		return out
	}

	if p.MaxRunners > room.Runners {
		out = append(out, Problem{
			Code:     "pool.max_above_room",
			Severity: config.SeverityWarning,
			Title: fmt.Sprintf("pool %s: its maximum is %d runners and its hosts have room for %d",
				p.Name, p.MaxRunners, room.Runners),
			Detail: fmt.Sprintf("one runner of this pool is charged %s CPU and %s, and the %s it can land on %s room for %s at that size. "+
				"The maximum is a backstop rather than a target, so this is not wrong -- but %s above the room are runners the scheduler will never create, "+
				"and the jobs that ask for them wait with nothing on any page saying why.",
				scheduler.FormatCPUs(chargeCPUs(room)), formatRoomMB(chargeMemoryMB(room)),
				plural(len(room.Hosts), "host"), verb(len(room.Hosts)), plural(room.Runners, "runner"),
				plural(p.MaxRunners-room.Runners, "runner")),
			Fix:        fmt.Sprintf("lower the maximum to %d, ask for less per runner, or give the pool more hosts.", room.Runners),
			TargetKind: "pool",
			TargetID:   p.ID,
		})
	}

	if over := room.Overcommitted(); len(over) > 0 {
		names := make([]string, 0, len(over))
		for _, h := range over {
			names = append(names, fmt.Sprintf("%s (%d slots, room for %d)", h.Host, h.Slots, h.Fits))
		}
		out = append(out, Problem{
			Code:     "pool.host_overcommitted",
			Severity: config.SeverityWarning,
			Title: fmt.Sprintf("pool %s: %s promises more slots than it can back at this size",
				p.Name, plural(len(over), "host")),
			Detail: "the slots above what the machine has room for read as free capacity on every page that counts them, " +
				"and every create for one of them is refused for want of CPU or memory: " + strings.Join(names, ", ") + ".",
			Fix: "adjust those hosts to the slots their machines can back, give this pool's runners less, " +
				"or clear its CPU and memory so each runner is given one slot's share of whatever host it lands on -- " +
				"which is the one size that cannot outrun a slot.",
			TargetKind: "pool",
			TargetID:   p.ID,
		})
	}

	if w, ok := strandedByFixedSize(p, room); ok {
		out = append(out, w)
	}

	if w, ok := heldByOldAgents(p, room); ok {
		out = append(out, w)
	}

	if p.Cache.Enabled && p.Cache.SizeLimit > 0 && room.DiskKnown {
		limitMB := p.Cache.SizeLimit / (1024 * 1024)
		if limitMB > room.SmallestDiskMB {
			out = append(out, Problem{
				Code:     "pool.cache_above_disk",
				Severity: config.SeverityWarning,
				Title: fmt.Sprintf("pool %s: its cache may grow to %s and %s has %s free",
					p.Name, formatRoomMB(limitMB), room.SmallestDiskHost, formatRoomMB(room.SmallestDiskMB)),
				Detail: "the cache is evicted down to its limit between one runner and the next, so a limit above the free space is not a limit at all: " +
					"the disk fills first, and a host at or below its disk reserve takes no runner of any pool.",
				Fix:        fmt.Sprintf("keep the limit inside what the smallest host can spare -- %s or less -- or free space there.", formatRoomMB(room.SmallestDiskMB)),
				TargetKind: "pool",
				TargetID:   p.ID,
			})
		}
	}
	return out
}

// strandedByFixedSize names the capacity a pool's fixed size is leaving on the
// floor, and the one edit that would take it back.
//
// A pool sized by its host gets one slot's share of each machine, so every
// host fills every slot it has: that is what dividing the machine by the slot
// count means. A fixed size can only match that on the hosts that happen to be
// the size it was chosen for -- and a fleet acquires unequal machines as a
// matter of course, one 8-core box and then a 64-core one. The 8-core figure
// then fits four runners on a machine with room for thirty-one, and nothing on
// any page says the pool is the reason.
//
// It is not the same as pool.host_overcommitted, which is about a host
// promising slots its machine cannot back; this is about a pool not using
// slots its hosts can. Both can be true at once, on different hosts.
//
// Only real stranding counts. A host is stranded when its machine could hold
// more runners of this pool than its slot count allows -- Fits above Slots --
// because that is the state where the size is not what binds, and the
// automatic share would have used every slot instead.
func strandedByFixedSize(p *store.Pool, room PoolRoom) (Problem, bool) {
	if p.Automatic() {
		return Problem{}, false
	}
	var names []string
	stranded := 0
	for _, h := range room.Hosts {
		// Slots above Fits is the overcommitted case, which has its own
		// problem and its own fix. This is the other direction: machine left
		// over that the slot count forbids using.
		if !h.CPUsKnown && !h.MemoryKnown {
			continue
		}
		if h.Fits <= h.Slots {
			continue
		}
		stranded += h.Fits - h.Slots
		names = append(names, fmt.Sprintf("%s (%d slots, room for %d at this size)", h.Host, h.Slots, h.Fits))
	}
	if stranded == 0 {
		return Problem{}, false
	}
	return Problem{
		Code:     "pool.size_strands_hosts",
		Severity: config.SeverityInfo,
		Title: fmt.Sprintf("pool %s: its fixed size is smaller than its hosts' share",
			p.Name),
		Detail: fmt.Sprintf("this pool asks for %s CPU and %s on every host, and %s could each hold more runners of it than their slot count allows: %s. "+
			"The slot count is what binds, so the machine above it goes unused -- %s worth across the fleet.",
			scheduler.FormatCPUs(p.Resources.CPUs), formatRoomMB(p.Resources.MemoryMB),
			plural(len(names), "host"), strings.Join(names, ", "), plural(stranded, "runner")),
		Fix:        "raise those hosts' capacity to the runners they can hold, or clear this pool's CPU and memory so each runner is given one slot's share of the host it lands on -- which fills every slot on every machine, whatever size it is.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// heldByOldAgents names the hosts on which an elastic pool is not elastic.
//
// Lending CPU means moving a live runner's cgroup quota, and the agent is the
// only thing on the host that can. An agent too old to advertise that it can
// is sent no directive and the runner stays at its guaranteed share -- which
// is a correct, safe outcome, and an invisible one: the pool says automatic,
// the runner says nothing was lent, and the metric that counts the decision as
// unsupported_agent is not a page anybody edits a pool from. This is the
// warning in the place the pool is saved, with the hosts named, because the
// only thing the controller cannot do about it is upgrade the agent itself:
// agents connect outbound, and a binary is replaced on the host.
//
// Observe mode raises nothing. It measures and never moves a quota, so the
// agent's part is never asked of it.
func heldByOldAgents(p *store.Pool, room PoolRoom) (Problem, bool) {
	if !p.CPUBurst.Enforces() {
		return Problem{}, false
	}
	var names []string
	for _, h := range room.Hosts {
		if !h.ElasticCPU {
			names = append(names, h.Host)
		}
	}
	if len(names) == 0 {
		return Problem{}, false
	}
	runs := "run"
	if len(names) == 1 {
		runs = "runs"
	}
	return Problem{
		Code:     "pool.elastic_cpu_unsupported",
		Severity: config.SeverityWarning,
		Title: fmt.Sprintf("pool %s: %d of its %s %s an agent that cannot lend CPU",
			p.Name, len(names), plural(len(room.Hosts), "host"), runs),
		Detail: "elastic CPU moves a live runner's quota through the agent on its host, and these agents are too old to say they can: " +
			strings.Join(names, ", ") + ". A runner placed there is held at its guaranteed share, exactly as with elastic CPU off, " +
			"and nothing on the pool says which of its runners that happened to.",
		Fix: "upgrade the agent on those hosts -- the command is on each host's card under Hosts -- " +
			"or keep this pool on observe, which needs nothing of the agent, until they are.",
		TargetKind: "pool",
		TargetID:   p.ID,
	}, true
}

// verb keeps "the host it can land on has" from reading as "hosts ... has".
func verb(n int) string {
	if n == 1 {
		return "has"
	}
	return "have"
}

// The charge is the same on every host that reports its machine, and differs
// only where a host's own share is standing in for a figure the pool did not
// give -- which, now that every pool has a size, is a pool made before it was
// mandatory. The first host that can run it is the one quoted.
func chargeCPUs(room PoolRoom) float64 {
	if len(room.Hosts) == 0 {
		return 0
	}
	return room.Hosts[0].ChargeCPUs
}

func chargeMemoryMB(room PoolRoom) int64 {
	if len(room.Hosts) == 0 {
		return 0
	}
	return room.Hosts[0].ChargeMemoryMB
}

// formatRoomMB writes a size the way the scheduler's own explanations do.
func formatRoomMB(mb int64) string {
	if mb >= 1024 && mb%1024 == 0 {
		return fmt.Sprintf("%d GB", mb/1024)
	}
	if mb >= 1024 {
		return fmt.Sprintf("%.1f GB", float64(mb)/1024)
	}
	return fmt.Sprintf("%d MB", mb)
}

package controller

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A host smaller than a pool's standard size but above its minimum is a host
// the pool runs on, and its line in the room says so at the size a runner
// there is really given. Quoting the standard charged, or no room at all, is
// how an operator was told a host the fleet was using was too small for it.
func TestPoolRoomCountsAHostThatFitsOnlyAtTheMinimum(t *testing.T) {
	tests := []struct {
		name        string
		memoryMB    int64
		capacity    int
		maxRunners  int
		wantFits    int
		wantCharged func(allocMB int64) int64
		wantWarn    bool
	}{
		{name: "a host below the standard holds one runner given all its memory",
			memoryMB: 8 * 1024, capacity: 1, maxRunners: 1, wantFits: 1,
			wantCharged: func(a int64) int64 { return a }},
		{name: "a host with room for one standard and one reduced runner is not over-committed at two slots",
			memoryMB: 14 * 1024, capacity: 2, maxRunners: 2, wantFits: 2,
			wantCharged: func(int64) int64 { return 8 * 1024 }},
		{name: "a maximum above what the minimum can place is still warned about",
			memoryMB: 8 * 1024, capacity: 4, maxRunners: 4, wantFits: 1,
			wantCharged: func(a int64) int64 { return a }, wantWarn: true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := &store.Host{ID: "host_a", Name: "small-1", Capacity: tc.capacity,
				CPUs: 32, MemoryMB: tc.memoryMB, Backends: []string{"docker"}}
			alloc := h.Allocatable().MemoryMB
			p := &store.Pool{ID: "pool_m", Name: "standard", Enabled: true, Backend: store.BackendDocker,
				MaxRunners: tc.maxRunners,
				Resources:  store.Resources{CPUs: 2, MemoryMB: 8 * 1024, MinMemoryMB: 4 * 1024}}

			entry := poolHostRoom(h, p)
			if entry.Fits != tc.wantFits {
				t.Errorf("fits = %d, want %d", entry.Fits, tc.wantFits)
			}
			if want := tc.wantCharged(alloc); entry.ChargeMemoryMB != want {
				t.Errorf("charged %d MB, want %d MB", entry.ChargeMemoryMB, want)
			}

			room := PoolRoom{Runners: entry.Room, Slots: entry.Slots, Hosts: []PoolHostRoom{entry}}
			ws := PoolRoomWarnings(p, room)
			if got := warned(ws, "pool.max_above_room") != nil; got != tc.wantWarn {
				t.Errorf("pool.max_above_room raised = %v, want %v", got, tc.wantWarn)
			}
			if w := warned(ws, "pool.host_overcommitted"); w != nil && !tc.wantWarn {
				t.Errorf("a host the pool fills at its minimum was called over-committed: %s", w.Detail)
			}
		})
	}
}

package controller

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// An elastic pool is elastic only where its host's agent can move a live
// quota. The pool cannot tell from its own settings which of its hosts can, so
// the room -- the one count made from the hosts it will actually land on --
// says so, and the review step names them rather than letting a runner there
// sit at its share while the pool reads automatic.
func TestAnElasticPoolNamesTheHostsWhoseAgentsCannotLendCPU(t *testing.T) {
	elastic := &store.Pool{
		ID: "pool_e", Name: "zoomies-elastic", Enabled: true,
		Backend:  store.BackendDocker,
		CPUBurst: store.CPUBurstPolicy{Mode: store.CPUBurstAutomatic},
	}
	room := PoolRoom{Runners: 6, Slots: 6, Hosts: []PoolHostRoom{
		{HostID: "host_1", Host: "new-1", Slots: 4, Fits: 4, Room: 4, ElasticCPU: true},
		{HostID: "host_2", Host: "old-1", Slots: 2, Fits: 2, Room: 2},
	}}

	w := warned(PoolRoomWarnings(elastic, room), "pool.elastic_cpu_unsupported")
	if w == nil {
		t.Fatal("an automatic pool with a host that cannot lend CPU said nothing")
	}
	if !strings.Contains(w.Title, "1 of its 2 hosts runs") {
		t.Errorf("title = %q, want the count of hosts held at their share", w.Title)
	}
	if !strings.Contains(w.Detail, "old-1") || strings.Contains(w.Detail, "new-1") {
		t.Errorf("detail = %q, want the old agent named and the new one not", w.Detail)
	}
	if !strings.Contains(w.Fix, "upgrade the agent") {
		t.Errorf("fix = %q, want the one thing that changes the answer", w.Fix)
	}

	// Observe measures and never moves a quota, so it asks nothing of the
	// agent and the warning would be about a change nothing makes.
	elastic.CPUBurst.Mode = store.CPUBurstObserve
	if w := warned(PoolRoomWarnings(elastic, room), "pool.elastic_cpu_unsupported"); w != nil {
		t.Errorf("an observe pool was warned about an agent it never asks anything of: %s", w.Title)
	}

	// And a fleet whose every agent can lend CPU says nothing either: a warning
	// an operator sees on every correct pool is one they stop reading.
	elastic.CPUBurst.Mode = store.CPUBurstAutomatic
	room.Hosts[1].ElasticCPU = true
	if w := warned(PoolRoomWarnings(elastic, room), "pool.elastic_cpu_unsupported"); w != nil {
		t.Errorf("a fleet of capable agents was warned anyway: %s", w.Title)
	}
}

package controller

import (
	"context"
	"time"

	"github.com/eyupio/zoomies/internal/config"
)

// PrivateConnectionFault is why the private-connection listener cannot be
// reached by the hosts that enrolled through it, and since when.
//
// The listener belongs to the API server, which owns the socket-shaped half of
// the process; the controller only keeps the fact, because the problems list is
// built here and a listener that fails with nothing but a log line is the
// failure this exists to design out.
type PrivateConnectionFault struct {
	Since  time.Time
	Reason string
}

// SetPrivateConnectionFault records the private-connection listener's state:
// a fault while no relay answers, nil once one does. It is safe to call from
// any goroutine.
func (c *Controller) SetPrivateConnectionFault(f *PrivateConnectionFault) {
	if f == nil {
		c.privateFault.Store(nil)
		return
	}
	// Keep the first moment it went wrong: a retry that fails again is the
	// same outage, not a new one, and "since" should say how long hosts have
	// been cut off rather than when somebody last looked.
	if prev := c.privateFault.Load(); prev != nil {
		f = &PrivateConnectionFault{Since: prev.Since, Reason: f.Reason}
	}
	c.privateFault.Store(f)
}

// PrivateConnectionFault is the listener's current fault, or nil.
func (c *Controller) PrivateConnectionFault() *PrivateConnectionFault {
	return c.privateFault.Load()
}

// privateConnectionProblems says the private connection is down.
//
// It is a warning rather than an error because nothing about the direct half of
// the fleet depends on it, and a host that enrolled privately keeps its jobs
// running through an interruption; what stops is its heartbeats and its next
// task, which host.unhealthy reports on its own. This entry is the cause those
// symptoms otherwise leave an operator to guess.
func (c *Controller) privateConnectionProblems(_ context.Context, out *[]Problem) error {
	f := c.privateFault.Load()
	if f == nil {
		return nil
	}
	since := f.Since
	*out = append(*out, Problem{
		Code:     "tailcat.unavailable",
		Severity: config.SeverityWarning,
		Title:    "private hosts cannot reach this controller",
		Detail: "the private-connection listener has no Tailcat relay it can reach, so hosts enrolled with a " +
			"private connection cannot heartbeat or take work. " +
			"The last attempt said: " + f.Reason,
		Fix: "check that this controller has outbound HTTPS to Tailcat's relays — a firewall, proxy or DNS change is " +
			"the usual cause. The controller keeps retrying, trying the relay its identity was sealed with first, " +
			"and this clears on its own once one answers; no restart is needed.",
		Since: &since,
	})
	return nil
}

package controller

import (
	"testing"
	"time"
)

// A relay that stays down is retried every twenty seconds, and each retry
// reports again. "Since" has to stay at the first failure, or the entry would
// say the private hosts were cut off moments ago however long it had been.
func TestAPrivateConnectionFaultKeepsWhenItStartedAcrossRetries(t *testing.T) {
	h := newHarness(t)
	first := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)
	h.c.SetPrivateConnectionFault(&PrivateConnectionFault{Since: first, Reason: "relay did not answer"})
	h.c.SetPrivateConnectionFault(&PrivateConnectionFault{Since: first.Add(time.Minute), Reason: "still no answer"})

	var got *Problem
	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	for i := range problems {
		if problems[i].Code == "tailcat.unavailable" {
			got = &problems[i]
		}
	}
	if got == nil {
		t.Fatal("a recorded private-connection fault raised no tailcat.unavailable")
	}
	if got.Since == nil || !got.Since.Equal(first) {
		t.Errorf("since = %v, want the first failure %v", got.Since, first)
	}
	if got.Audience != AudiencePlatform {
		t.Errorf("audience = %q; the listener is the process's, so the platform's", got.Audience)
	}

	h.c.SetPrivateConnectionFault(nil)
	problems, _ = h.c.Problems(h.ctx)
	for _, p := range problems {
		if p.Code == "tailcat.unavailable" {
			t.Fatal("tailcat.unavailable stayed after the relay answered")
		}
	}
}

