	if contains(h.problemCodes(), "pool.no_capacity") {
		t.Fatalf("problems = %v, want the blocked pool gone once a host can run it", h.problemCodes())
	}
}

// A fleet that is simply full is the system working: the jobs are waiting for a
// runner to finish, not for an operator. It is still worth saying, but it is
// not an outage.
func TestAFullFleetIsAWarningRatherThanAnOutage(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	p := h.pool(inst, "linux-x64")
	host := h.host("vm-1")
	host.Capacity = 1
	if err := h.st.UpdateHost(h.ctx, host); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	// The one slot is taken, and a second job is queued behind it.
	h.runnerRow(p, host, store.RunnerBusy)
	h.deliverJob(jobEvent{Action: "queued", JobID: 4244, Labels: p.Labels})

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	found := false
	for _, pr := range ps {
		if pr.Code != "pool.no_capacity" {
			continue
		}
		found = true
		if pr.Severity != config.SeverityWarning {
			t.Errorf("severity = %q, want a warning: the fleet is busy, not broken", pr.Severity)
		}
		if !strings.Contains(pr.Detail, "at capacity") {
			t.Errorf("detail = %q, want it to say the fleet is full", pr.Detail)
		}
	}
	if !found {
		t.Fatalf("problems = %v, want the pool waiting on capacity", h.problemCodes())
	}
}

// The installation's webhooks cover every job in its repositories, most of
// which this fleet never touches. A job on GitHub's own runners is theirs to
// run however long it queues, and a job no pool here claims may be another
// provider's, about to start there; neither is a problem for this fleet, and
// the dev instance once showed fifty of them as jobs that would never run.
func TestAHostedOrFreshUnmatchedJobIsNotAProblem(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	h.deliverJob(jobEvent{
		Action: "queued", JobID: 910,
		Labels:   []string{"ubuntu-latest"},
		QueuedAt: time.Now().Add(-time.Hour),
	})
	h.deliverJob(jobEvent{
		Action: "queued", JobID: 911,
		Labels:   []string{"blacksmith-4vcpu-ubuntu-2404"},
		QueuedAt: time.Now().Add(-time.Hour),
	})
	h.deliverJob(jobEvent{
		Action: "queued", JobID: 912,
		Labels: []string{"self-hosted", "arc-runner-set"},
		// Fresh: another provider's scale-up delay has not run out.
	})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	if contains(h.problemCodes(), "jobs.unmatched") {
		t.Fatalf("problems = %v; hosted and freshly queued jobs are not this fleet's", h.problemCodes())
	}

	// The view says which jobs are hosted, so the UI can badge them rather
	// than warn about them.
	hosted, err := h.st.GetJobByGitHubID(h.ctx, 910)
	if err != nil {
		t.Fatal(err)
	}
	if v := NewJobView(hosted, ""); !v.Hosted || v.Matched {
		t.Fatalf("view = %+v, want hosted and unmatched", v)
	}
	own, err := h.st.GetJobByGitHubID(h.ctx, 912)
	if err != nil {
		t.Fatal(err)
	}
	if v := NewJobView(own, ""); v.Hosted {
		t.Fatalf("a self-hosted label counted as hosted: %+v", v)
	}
}

// A cordoned host used to be blamed for every queued job in the fleet, pools it
// never offered included, which sent an operator to uncordon a machine that
// would have changed nothing.
func TestACordonedHostIsOnlyBlamedForWorkItCouldRun(t *testing.T) {
	h := newHarness(t)
	inst, _, host := h.fleet()
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}
	// A pool this host never offered: it runs bare processes, and the host's
	// agent speaks Docker.
	bare := h.pool(inst, "bare", "self-hosted", "bare")
	bare.Backend = store.BackendProcess
	if err := h.st.UpdatePool(h.ctx, bare); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.deliverJob(jobEvent{Action: "queued", JobID: 3, Labels: []string{"self-hosted", "bare"}})
	if contains(h.problemCodes(), "host.cordoned_with_work") {
		t.Fatalf("problems = %v; the queued job is for a backend this host does not offer", h.problemCodes())
	}

	h.deliverJob(jobEvent{Action: "queued", JobID: 4, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if !contains(h.problemCodes(), "host.cordoned_with_work") {
		t.Fatalf("problems = %v, want the cordoned-host warning for a job it could run", h.problemCodes())
	}
}

// Platform is a promise about the machine, separate from a host selector: an
// arm64 pool with no selector is not excluded by the label match, but the
// scheduler will never place it on an amd64 host. Blaming the cordon for that
// queue sends an operator to uncordon a machine that would change nothing.
func TestACordonedHostIsNotBlamedForWorkOfAnotherPlatform(t *testing.T) {
	h := newHarness(t)
	inst, _, host := h.fleet()
	if err := h.st.SetHostCordoned(h.ctx, host.ID, true); err != nil {
		t.Fatalf("SetHostCordoned: %v", err)
	}
	arm := h.pool(inst, "arm", "self-hosted", "arm64")
	arm.Platform = store.Platform{Arch: "arm64"}
	if err := h.st.UpdatePool(h.ctx, arm); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	h.deliverJob(jobEvent{Action: "queued", JobID: 5, Labels: []string{"self-hosted", "arm64"}})
	if contains(h.problemCodes(), "host.cordoned_with_work") {
		t.Fatalf("problems = %v; the queued job is for an architecture this host is not", h.problemCodes())
	}
}

// The failed-runner count came from a page of at most a hundred rows, so a
// fleet having a bad day was told it had a hundred failures however many it had.
func TestTheFailedRunnerCountIsNotAPage(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	const failed = 120
	for i := 0; i < failed; i++ {
		r := h.runnerRow(pool, host, store.RunnerProvisioning)
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerFailed, "the image could not be pulled"); err != nil {
			t.Fatalf("TransitionRunner: %v", err)
		}
	}
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range ps {
		if p.Code == "runners.failed" {
			if want := "120 runners in the failed state"; p.Title != want {
				t.Fatalf("title = %q, want %q", p.Title, want)
			}
			return
		}
	}
	t.Fatalf("problems = %v, want runners.failed", ps)
}

// findProblem returns the problem with a code, or fails saying what was there.
func findProblem(t *testing.T, h *harness, code string) Problem {
	t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range ps {
		if p.Code == code {
			return p
		}
	}
	t.Fatalf("problems = %v, want %s", codesOf(ps), code)
	return Problem{}
}

// stuck is a moment past the threshold that reports a runner as not
// progressing -- half the provision timeout -- and before the timeout itself
// would fail it, which is the window these problems exist to fill. It is
// derived rather than written down: the threshold follows a setting, and a test
// that pinned the minutes would have to be edited every time that setting moved
// rather than failing only when the behaviour did.
func (h *harness) stuck(from time.Time) time.Time {
	return from.Add(h.cfg.Scheduler.ProvisionTimeout * 3 / 4)
}

// A runner that is still starting up normally must not raise anything. This is
// the expensive half of the behaviour to get wrong: a warning that appears
// every time a pool creates a runner is a warning nobody reads by the end of
// the week.
func TestARunnerThatIsStillComingUpIsNotAProblem(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.runnerRow(pool, host, store.RunnerRegistering)

	if got := h.problemCodes(); contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v, want nothing about a runner that was created a moment ago", got)
	}
}

// The distinction this problem exists to make: a container that started and a
// runner that has not registered is the runner process failing to reach GitHub,
// and the fix says to read that runner's own logs.
func TestARunnerWhoseContainerStartedButNeverRegisteredNamesItsOwnLogs(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	started := time.Now()
	r := h.runnerRow(pool, host, store.RunnerRegistering)
	if err := h.st.SetRunnerStartup(h.ctx, r.ID, nil, &started); err != nil {
		t.Fatalf("SetRunnerStartup: %v", err)
	}
	// Past half the provision timeout, but not yet past the timeout itself:
	// the whole point is to say something while there is still time to look.
	h.c.clock = func() time.Time { return h.stuck(started) }

	p := findProblem(t, h, "runners.not_progressing")
	if !strings.Contains(p.Fix, "has not registered") || !strings.Contains(p.Fix, "github.com") {
		t.Fatalf("fix = %q, want the runner-side causes", p.Fix)
	}
	if !strings.Contains(p.Detail, r.Name) {
		t.Fatalf("detail = %q, want the runner named", p.Detail)
	}
	if p.TargetID != r.ID || p.TargetKind != "runner" {
		t.Fatalf("target = %s/%s, want the runner itself", p.TargetKind, p.TargetID)
	}
}

// The other shape, and the reason one code is not enough on its own: nothing
// has reported a workload at all, which is a problem on the host rather than
// inside the runner.
func TestARunnerWithNoContainerYetPointsAtTheHost(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)

	h.c.clock = func() time.Time { return h.stuck(r.CreatedAt) }

	p := findProblem(t, h, "runners.not_progressing")
	if !strings.Contains(p.Fix, "agent log") || !strings.Contains(p.Fix, "image") {
		t.Fatalf("fix = %q, want the host-side causes", p.Fix)
	}
	if !strings.Contains(p.Detail, host.Name) {
		t.Fatalf("detail = %q, want the host named when they are all on one", p.Detail)
	}
}

// The threshold is half the provision timeout rather than a number of its own,
// so an operator who allows longer for a slow image pull is not then told their
// runners are stuck while they are still within the time they allowed.
func TestTheStuckThresholdFollowsTheProvisionTimeout(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRegistering)
	h.c.clock = func() time.Time { return r.CreatedAt.Add(6 * time.Minute) }

	h.cfg.Scheduler.ProvisionTimeout = 10 * time.Minute
	if got := h.problemCodes(); !contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v, want a ten-minute timeout to have raised it by six", got)
	}

	h.cfg.Scheduler.ProvisionTimeout = time.Hour
	if got := h.problemCodes(); contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v, want silence six minutes into an hour's allowance", got)
	}

	// Off means off: a fleet that has switched the timeout off has said that
	// runners may take as long as they take.
	h.cfg.Scheduler.ProvisionTimeout = 0
	h.c.clock = func() time.Time { return r.CreatedAt.Add(24 * time.Hour) }
	if got := h.problemCodes(); contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v, want nothing when provision_timeout is off", got)
	}
}

// The detail names one runner and the fix tells you what to do about it, so on
// a mixed fleet the two must describe the same runner. They used to be chosen
// separately -- the example was the oldest, the fix was whichever shape there
// were more of -- so an even split named a runner with no container and then
// told the operator to go and read that container's logs.
func TestTheFixDescribesTheRunnerTheDetailNames(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	// Oldest first and still waiting for a container, then a younger one whose
	// container started: one of each, so no bucket is the larger.
	waiting := h.runnerRow(pool, host, store.RunnerProvisioning)
	started := h.runnerRow(pool, host, store.RunnerRegistering)
	// The younger one's clock starts a second after the older one's, not at
	// the wall clock: the two rows are written within a millisecond of each
	// other, and a container stamped with the same millisecond as the other
	// runner's creation is not younger by anyone's clock.
	at := waiting.CreatedAt.Add(time.Second)
	if err := h.st.SetRunnerStartup(h.ctx, started.ID, nil, &at); err != nil {
		t.Fatalf("SetRunnerStartup: %v", err)
	}
	h.c.clock = func() time.Time { return h.stuck(waiting.CreatedAt) }

	p := findProblem(t, h, "runners.not_progressing")
	if !strings.Contains(p.Detail, waiting.Name) {
		t.Fatalf("detail = %q, want the oldest runner %s", p.Detail, waiting.Name)
	}
	if !strings.Contains(p.Fix, "agent log") {
		t.Fatalf("fix = %q, want the host-side fix that matches a runner with no container", p.Fix)
	}
	if !strings.Contains(p.Detail, "1 runner waiting for a container") {
		t.Fatalf("detail = %q, want both counts named", p.Detail)
	}
}

// Runners created in one scheduler pass share a millisecond, and the problem
// used to pick whichever the store returned first, so the same fleet could be
// described two ways on two passes. A tie names the runner with no container,
// whichever order the rows come back in.
func TestAStuckTieNamesTheRunnerWithNoContainer(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	started := h.runnerRow(pool, host, store.RunnerRegistering)
	waiting := h.runnerRow(pool, host, store.RunnerProvisioning)
	// The container came up at the exact moment the other runner was created.
	at := waiting.CreatedAt
	if err := h.st.SetRunnerStartup(h.ctx, started.ID, nil, &at); err != nil {
		t.Fatalf("SetRunnerStartup: %v", err)
	}
	h.c.clock = func() time.Time { return h.stuck(waiting.CreatedAt) }

	for i := 0; i < 5; i++ {
		p := findProblem(t, h, "runners.not_progressing")
		if !strings.Contains(p.Detail, waiting.Name) {
			t.Fatalf("pass %d: detail = %q, want the runner with no container, %s", i, p.Detail, waiting.Name)
		}
		if !strings.Contains(p.Fix, "agent log") {
			t.Fatalf("pass %d: fix = %q, want the host-side fix", i, p.Fix)
		}
	}
}

// The drawer is read at the moment something is wrong, so the one thing it
// must never do is come back empty because it could not look. It used to
// return a 500 for any single failing query, and a drawer that will not load
// is indistinguishable from a fleet with nothing wrong.
//
// A cancelled context fails every store query at once, which is the strongest
// version of the case: the sections that need the database are all lost, the
// ones that do not are still there, and the list says out loud that it is
// incomplete.
func TestProblemsSurvivesASectionItCannotGather(t *testing.T) {
	h := newHarness(t)
	h.cfg.Security.DisableAuth = true

	ctx, cancel := context.WithCancel(h.ctx)
	cancel()

	got, err := h.c.Problems(ctx)
	if err != nil {
		t.Fatalf("Problems returned an error rather than what it could gather: %v", err)
	}
	codes := make([]string, 0, len(got))
	for _, p := range got {
		codes = append(codes, p.Code)
	}
	// What does not need the database is still reported.
	if !slices.Contains(codes, "auth.disabled") {
		t.Errorf("a configuration warning was lost with the database sections: %v", codes)
	}
	// And the operator is told the list is short, rather than being left to
	// read it as a clean fleet.
	i := slices.Index(codes, "controller.problems_partial")
	if i < 0 {
		t.Fatalf("an incomplete list did not say so: %v", codes)
	}
	if got[i].Severity != config.SeverityError {
		t.Errorf("the incomplete-list entry is %q; a list that cannot be trusted is an error", got[i].Severity)
	}
	// Naming the sections is what makes it actionable rather than alarming.
	for _, section := range []string{"hosts", "jobs", "runners"} {
		if !strings.Contains(got[i].Detail, section) {
			t.Errorf("the detail does not name the %s section: %q", section, got[i].Detail)
		}
	}
}

// The fallback poller is the safety net for a fleet whose webhooks have stopped
// arriving, and both of its failure modes are silent by construction: a sweep
// that has stopped happening looks exactly like a sweep with nothing to find.
// Until now both were visible only in the log, and nobody reads the log of a
// fleet that appears to be fine.
func TestTheProblemsListSaysWhenThePollerHasStoppedSweeping(t *testing.T) {
	h := newHarness(t)
	h.cfg.GitHub.PollFallback = true
	h.cfg.GitHub.PollInterval = 30 * time.Second

	// A poller that has never swept says nothing: a controller that started
	// ten seconds ago is not a controller with a broken poller.
	if contains(h.problemCodes(), "poller.stale") {
		t.Fatalf("a controller that has not polled yet reported a stale poller: %v", h.problemCodes())
	}

	h.c.lastPollAt.Store(h.c.Now().UnixNano())
	if contains(h.problemCodes(), "poller.stale") {
		t.Fatalf("a poller that has just swept was called stale: %v", h.problemCodes())
	}

	// One missed tick is a slow query, not a fault, so the grace is more than
	// one interval and the entry must not fire inside it.
	h.advance(45 * time.Second)
	if contains(h.problemCodes(), "poller.stale") {
		t.Errorf("one missed tick was reported as a stopped poller: %v", h.problemCodes())
	}

	h.advance(2 * time.Minute)
	got := h.problem(t, "poller.stale")
	if got.Severity != config.SeverityWarning {
		t.Errorf("severity = %q, want a warning", got.Severity)
	}
	if !strings.Contains(got.Detail, "webhook") {
		t.Errorf("the detail does not say what is lost while it is stopped: %q", got.Detail)
	}

	// Off is a choice the configuration validator already names, and saying it
	// twice would be the drawer disagreeing with itself.
	h.cfg.GitHub.PollFallback = false
	if contains(h.problemCodes(), "poller.stale") {
		t.Errorf("a deliberately disabled poller was reported as broken: %v", h.problemCodes())
	}
}

// GitHub's quota is per installation, so a hold on one is not a fleet-wide
// fault -- and an operator told "the poller is paused" would go looking for
// one. ZF-101 made the hold per installation; this is the entry catching up
// with it.
func TestARateLimitedInstallationIsNamedRatherThanTheWholePoller(t *testing.T) {
	h := newHarness(t)
	h.cfg.GitHub.PollFallback = true
	inst := h.installation()

	until := h.c.Now().Add(20 * time.Minute)
	h.c.holdGitHub(inst.ID, until)

	got := h.problem(t, "poller.paused")
	if got.TargetKind != "installation" || got.TargetID != inst.ID {
		t.Errorf("the entry does not point at the installation being held: %+v", got)
	}
	// The organisation, not the opaque identifier: an operator recognises one
	// of those.
	if !strings.Contains(got.Title, "acme") {
		t.Errorf("the title does not name the installation an operator would recognise: %q", got.Title)
	}
	if !strings.Contains(got.Detail, until.UTC().Format(time.RFC3339)) {
		t.Errorf("the detail does not say when it clears: %q", got.Detail)
	}

	// It clears itself, and the entry has to go with it or an operator is left
	// chasing a hold that expired an hour ago.
	h.advance(21 * time.Minute)
	if contains(h.problemCodes(), "poller.paused") {
		t.Errorf("an expired hold was still reported: %v", h.problemCodes())
	}
}

// A key that does not open its own database is what a restore that brought the
// database back and left the key behind looks like once the instance is
// running: every installation fails at once, and the fix is a file rather than
// anything on GitHub. Reporting it as installation.unhealthy would send the
// operator to check permissions on an App that is perfectly fine.
func TestAKeyThatCannotOpenItsOwnDatabaseSaysSo(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	// The database as a restore without its key leaves it: the sealed bytes
	// are real and this instance's key is not the one that sealed them.
	other, err := cryptox.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	sealed, err := other.SealString("-----BEGIN RSA PRIVATE KEY-----\nother\n-----END RSA PRIVATE KEY-----")
	if err != nil {
		t.Fatalf("sealing: %v", err)
	}
	inst.PrivateKeyEnc = sealed
	if err := h.st.UpdateInstallation(h.ctx, inst); err != nil {
		t.Fatalf("UpdateInstallation: %v", err)
	}

	codes := h.problemCodes()
	if !contains(codes, "crypto.key_mismatch") {
		t.Fatalf("problems = %v, want crypto.key_mismatch", codes)
	}
	all, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var p Problem
	for _, item := range all {
		if item.Code == "crypto.key_mismatch" {
			p = item
		}
	}
	// The organisation is in it because an operator with several needs to know
	// whether this is all of them, which is what distinguishes a lost key from
	// one App being revoked.
	if !strings.Contains(p.Detail, "acme") {
		t.Errorf("the detail does not name the installation: %q", p.Detail)
	}
	if !strings.Contains(p.Fix, "encryption key") {
		t.Errorf("the fix does not name the key to put back: %q", p.Fix)
	}
	if p.Severity != config.SeverityError {
		t.Errorf("severity = %s; nothing can reach GitHub, so this is an error", p.Severity)
	}
}

// Advice about upgrading an agent has to be advice an operator can follow.
//
// Both of these problems used to build their Fix from version.Version without
// asking what that version was. On a controller built from main -- which is
// what the :dev and :main images are -- it is main-sha-abc1234, and no
// release asset carries it, so "upgrade the agent on those hosts to
// main-sha-abc1234" sent the operator to a 404 and they came back to find the
// fleet exactly as it was. That is the fleet these problems fire on, too: a
// build from main cannot be ordered against a release, so every host on one
// lands in the differs bucket.
//
// CLAUDE.md puts the bar at "findings say what to change", and
// RemedyText.svelte hangs a copy button on every backticked run of text, so a
// command belongs in backticks or the operator retypes it.
func TestAgentUpgradeAdviceIsSomethingAnOperatorCanDo(t *testing.T) {
	was := version.Version
	t.Cleanup(func() { version.Version = was })

	t.Run("a released controller names the command", func(t *testing.T) {
		version.Version = "1.0.0"
		fix := agentUpgradeFix("Then the figures appear.")
		if !strings.Contains(fix, "--version v1.0.0") {
			t.Errorf("the advice does not name the version to install: %q", fix)
		}
		if strings.Count(fix, "`") < 2 {
			t.Errorf("the advice carries no backticked command, so the UI renders no copy button: %q", fix)
		}
		if !strings.Contains(fix, "Then the figures appear.") {
			t.Errorf("the advice dropped what follows the upgrade: %q", fix)
		}
	})

	for _, stamped := range []string{"main-sha-117bc18", "dev"} {
		t.Run("an unreleased controller says there is nothing to install: "+stamped, func(t *testing.T) {
			version.Version = stamped
			fix := agentUpgradeFix("Then the figures appear.")
			if strings.Contains(fix, "--version") {
				t.Errorf("a controller stamped %q told the operator to install a version that does not exist: %q",
					stamped, fix)
			}
			if !strings.Contains(fix, stamped) {
				t.Errorf("the advice does not say which build this controller is: %q", fix)
			}
		})
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// This file is the operator's half of the provider feature: the four questions
// a person asks that the reconciler never does -- what can this build rent
// from, are these answers sensible, does this credential actually work, and
// what is out there that no row accounts for.
//
// It lives here rather than in internal/api because every one of them needs a
// built provider, and building one needs the registry, the instance key and the
// operator's deadlines. The API is transport: it renders what these return and
// has no opinion about the fleet, which is why each of them answers in a view
// type rather than in provider's own vocabulary.

// ErrProviderKindUnknown is a provider row, or a draft, naming a kind this
// build has no driver for. It is a conflict rather than a validation failure
// for a stored row -- the row was legal when it was written -- and the message
// names the kind so an operator knows which build they need.
var ErrProviderKindUnknown = errors.New("this build has no driver for that provider kind")

// ErrDiscoveryUnsupported is a provider whose driver cannot list what a
// credential can see. The guided form asks the operator to type identifiers
// instead, so this is reported rather than hidden.
var ErrDiscoveryUnsupported = errors.New("this provider cannot list what its credential can see")

// ---------------------------------------------------------------------------
// The kinds this build ships
// ---------------------------------------------------------------------------

// ProviderKindView is one provider driver this build carries, with the
// questions its configuration form has to ask. The form, the CLI and
// docs/providers.md all render this one description, so a setting cannot
// appear in one of them and be missing from the others.
type ProviderKindView struct {
	Kind  store.ProviderKind `json:"kind"`
	Label string             `json:"label"`
	// Bootstrap says how the enrolment payload reaches a guest, which is the
	// one capability an operator has to care about before they buy anything:
	// "metadata" means the payload is readable by anyone who can read the
	// machine's metadata.
	Bootstrap        string `json:"bootstrap"`
	CanStartStop     bool   `json:"can_start_stop"`
	CanDiscover      bool   `json:"can_discover"`
	CanMarkOwnership bool   `json:"can_mark_ownership"`
	AsyncOperations  bool   `json:"async_operations"`
	CostUnit         string `json:"cost_unit,omitempty"`
	EndpointExample  string `json:"endpoint_example,omitempty"`
	// Where the three answers every kind is asked for are found, in the
	// provider's own console's terms.
	EndpointSource   string `json:"endpoint_source,omitempty"`
	CredentialSource string `json:"credential_source,omitempty"`
	CASource         string `json:"ca_source,omitempty"`
	// Guide is what has to exist before this kind can rent anything, in the
	// order it is done, so the wizard can say it before its first question.
	Guide    []ProviderGuideStepView `json:"guide"`
	Settings []ProviderSettingView   `json:"settings"`
}

// ProviderGuideStepView is one thing to do before a provider of a kind works.
type ProviderGuideStepView struct {
	Title   string `json:"title"`
	Detail  string `json:"detail,omitempty"`
	Command string `json:"command,omitempty"`
}

// ProviderSettingView is one answer a provider needs.
type ProviderSettingView struct {
	Key      string `json:"key"`
	Label    string `json:"label"`
	Kind     string `json:"kind"`
	Required bool   `json:"required"`
	Advanced bool   `json:"advanced"`
	Help     string `json:"help,omitempty"`
	// Consequence says what choosing this costs, in the voice the pool form
	// already uses. A list of identifiers with no consequences is a list
	// somebody guesses at.
	Consequence string `json:"consequence,omitempty"`
	Discovers   string `json:"discovers,omitempty"`
	Default     string `json:"default,omitempty"`
	// Source says where to find the answer when discovery cannot offer it.
	Source string `json:"source,omitempty"`
}

// ProviderKinds is every driver this build can speak, in the registry's stable
// order.
func (c *Controller) ProviderKinds() []ProviderKindView {
	kinds := c.providers.Kinds()
	out := make([]ProviderKindView, 0, len(kinds))
	for _, k := range kinds {
		f, err := c.providers.Get(k)
		if err != nil {
			continue
		}
		caps := f.Describe()
		v := ProviderKindView{
			Kind:             k,
			Label:            caps.Label,
			Bootstrap:        string(caps.Bootstrap),
			CanStartStop:     caps.CanStartStop,
			CanDiscover:      caps.CanDiscover,
			CanMarkOwnership: caps.CanMarkOwnership,
			AsyncOperations:  caps.AsyncOperations,
			CostUnit:         caps.CostUnit,
			EndpointExample:  caps.EndpointExample,
			EndpointSource:   caps.EndpointSource,
			CredentialSource: caps.CredentialSource,
			CASource:         caps.CASource,
			Guide:            make([]ProviderGuideStepView, 0, len(caps.Guide)),
			Settings:         make([]ProviderSettingView, 0, len(f.Settings())),
		}
		for _, step := range caps.Guide {
			v.Guide = append(v.Guide, ProviderGuideStepView{Title: step.Title, Detail: step.Detail, Command: step.Command})
		}
		for _, spec := range f.Settings() {
			v.Settings = append(v.Settings, ProviderSettingView{
				Key:         spec.Key,
				Label:       spec.Label,
				Kind:        string(spec.Kind),
				Required:    spec.Required,
				Advanced:    spec.Advanced,
				Help:        spec.Help,
				Consequence: spec.Consequence,
				Discovers:   spec.Discovers,
				Default:     spec.Default,
				Source:      spec.Source,
			})
		}
		out = append(out, v)
	}
	return out
}

// ProvidersAvailable reports whether this deployment can rent machines at all:
// a driver to rent from, and an operator who has turned the machine loop on.
// The page that would otherwise offer to buy machines nothing would ever create
// asks this first.
func (c *Controller) ProvidersAvailable() bool {
	return len(c.providers.Kinds()) > 0 && c.cfg().Provider.Enabled
}

// ValidateProviderSettings runs a driver's own offline check over a draft's
// answers. It dials nothing and needs no credential, which is what lets the
// wizard run it as somebody types; CheckProvider is the call that talks to the
// hypervisor.
func (c *Controller) ValidateProviderSettings(kind store.ProviderKind, settings map[string]string) ([]config.Finding, error) {
	f, err := c.providers.Get(kind)
	if err != nil {
		return nil, fmt.Errorf("%w: %s", ErrProviderKindUnknown, kind)
	}
	return f.Validate(settings), nil
}

// ---------------------------------------------------------------------------
// The live preflight
// ---------------------------------------------------------------------------

// ProviderCheckView is a preflight result: whether the hypervisor answered,
// what it said it is, and everything an operator has to fix before a machine
// will ever be created. The findings are config.Finding so that "what is wrong
// with this provider" reads exactly like "what is wrong with this
// configuration", in the wizard, in the problems drawer and in the CLI.
type ProviderCheckView struct {
	ProviderID string           `json:"provider_id"`
	OK         bool             `json:"ok"`
	Reachable  bool             `json:"reachable"`
	Version    string           `json:"version,omitempty"`
	Findings   []config.Finding `json:"findings"`
	CheckedAt  time.Time        `json:"checked_at"`
}

// CheckProvider asks a provider what it would refuse, changing nothing.
//
// The result is recorded on the row as well as returned, because the page, the
// problems drawer and the reconciler's own "this template has not been verified
// since the configuration changed" warning all read it from there -- a check an
// operator ran in a terminal should quiet the warning the UI is showing.
func (c *Controller) CheckProvider(ctx context.Context, row *store.Provider) (ProviderCheckView, error) {
	pr, err := c.providerFor(ctx, row)
	if err != nil {
		return ProviderCheckView{}, providerBuildError(row, err)
	}
	callCtx, cancel := context.WithTimeout(ctx, c.stepTimeout(pr))
	defer cancel()
	report := pr.p.Preflight(callCtx)

	now := c.Now()
	out := ProviderCheckView{
		ProviderID: row.ID,
		OK:         report.OK(),
		Reachable:  report.Reachable,
		Version:    report.Version,
		Findings:   report.Findings,
		CheckedAt:  now,
	}
	if out.Findings == nil {
		out.Findings = []config.Finding{}
	}
	// The recorded error is the worst thing the check found, in one sentence,
	// because that is what a card has room for; the findings are the whole of
	// it and are returned to the caller who asked.
	if err := c.st.SetProviderChecked(ctx, row.ID, now, checkComplaint(report)); err != nil {
		c.log.Warn("could not record a provider check", "provider", row.ID, "error", err)
	}
	if fresh, err := c.st.GetProvider(ctx, row.ID); err == nil {
		c.PublishProvider(ctx, fresh)
	}
	return out, nil
}

// checkComplaint is the one sentence a preflight leaves on the row. A provider
// that could not be reached has one problem rather than eleven, so that is what
// it says; otherwise it is the first error, and warnings alone leave the row
// clean because they never stopped anything.
func checkComplaint(r provider.Report) string {
	if !r.Reachable {
		return "could not be reached"
	}
	for _, f := range r.Findings {
		if f.Severity == config.SeverityError {
			return f.Title
		}
	}
	return ""
}

// ---------------------------------------------------------------------------
// Discovery
// ---------------------------------------------------------------------------

// ProviderDiscoveryView is what a credential can actually see. A provider with
// no such concept leaves a list empty rather than inventing one.
type ProviderDiscoveryView struct {
	Nodes     []ProviderChoiceView `json:"nodes"`
	Storages  []ProviderChoiceView `json:"storages"`
	Bridges   []ProviderChoiceView `json:"bridges"`
	Templates []ProviderChoiceView `json:"templates"`
	// Unavailable is why the lists are empty when the provider could not be
	// asked: the address did not answer, the credential was refused. A draft
	// in a wizard is expected to be wrong at first, and a sentence beside the
	// form is what corrects it; the form asks for identifiers meanwhile.
	Unavailable string `json:"unavailable,omitempty"`
}

// ProviderChoiceView is one option in a guided form.
type ProviderChoiceView struct {
	Value       string `json:"value"`
	Label       string `json:"label,omitempty"`
	Consequence string `json:"consequence,omitempty"`
}

// DiscoverProvider asks a provider what this credential can see, so the form
// offers a menu rather than asking somebody to go and look an identifier up.
func (c *Controller) DiscoverProvider(ctx context.Context, row *store.Provider) (ProviderDiscoveryView, error) {
	pr, err := c.providerFor(ctx, row)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	return c.discover(ctx, pr)
}

// DiscoverDraft asks a provider that has not been saved what its credential
// can see, so the wizard can offer the nodes, storages, bridges and templates
// as a menu before there is a row to save them on.
//
// The secrets arrive in plaintext because there is no row to unseal them
// from, and they go nowhere: the client is built for this one call and
// dropped, and a private connection opened for it is closed with it. Nothing
// is cached, because a draft has no identity to cache under and its
// credential may be about to be corrected.
func (c *Controller) DiscoverDraft(ctx context.Context, row *store.Provider, credential, address string) (ProviderDiscoveryView, error) {
	if address != "" && !c.cfg().Server.TailcatEnabled {
		return ProviderDiscoveryView{}, errPrivateConnectionsDisabled(row)
	}
	f, err := c.providers.Get(row.Kind)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	if dd, ok := f.(provider.DraftDiscoverer); ok {
		// The address and the credential are enough: the placement answers
		// a built provider would insist on are the ones the menu is for.
		cfg, tunnel, err := c.providerConfig(row, credential, address)
		if err != nil {
			return ProviderDiscoveryView{}, err
		}
		if tunnel != nil {
			defer tunnel.Close()
		}
		callCtx, cancel := context.WithTimeout(ctx, c.providerDeadlines().Call)
		defer cancel()
		got, err := dd.DiscoverDraft(callCtx, cfg)
		if err != nil {
			return ProviderDiscoveryView{}, err
		}
		return discoveryView(got), nil
	}
	p, tunnel, err := c.buildProvider(ctx, row, credential, address)
	if err != nil {
		return ProviderDiscoveryView{}, providerBuildError(row, err)
	}
	if tunnel != nil {
		defer tunnel.Close()
	}
	return c.discover(ctx, &machineProvider{row: row, p: p})
}

func (c *Controller) discover(ctx context.Context, pr *machineProvider) (ProviderDiscoveryView, error) {
	row := pr.row
	d, ok := pr.p.(provider.Discoverer)
	if !ok {
		return ProviderDiscoveryView{}, fmt.Errorf("%w: %s is a %s provider", ErrDiscoveryUnsupported, row.Name, row.Kind)
	}
	callCtx, cancel := context.WithTimeout(ctx, c.stepTimeout(pr))
	defer cancel()
	got, err := d.Discover(callCtx)
	if err != nil {
		return ProviderDiscoveryView{}, err
	}
	return discoveryView(got), nil
}

func discoveryView(got provider.Discovery) ProviderDiscoveryView {
	return ProviderDiscoveryView{
		Nodes:     choiceViews(got.Nodes),
		Storages:  choiceViews(got.Storages),
		Bridges:   choiceViews(got.Bridges),
		Templates: choiceViews(got.Templates),
	}
}

func choiceViews(in []provider.Choice) []ProviderChoiceView {
	out := make([]ProviderChoiceView, 0, len(in))
	for _, c := range in {
		out = append(out, ProviderChoiceView{Value: c.Value, Label: c.Label, Consequence: c.Consequence})
	}
	return out
}

// providerBuildError explains a provider that could not be built at all, which
// is a different failure from one that answered badly: the credential would not
// unseal, or this build has no driver for the row's kind.
func providerBuildError(row *store.Provider, err error) error {
	if errors.Is(err, provider.ErrUnsupported) {
		return fmt.Errorf("%w: %s is a %s provider", ErrProviderKindUnknown, row.Name, row.Kind)
	}
	return err
}

// ---------------------------------------------------------------------------
// The orphan review
// ---------------------------------------------------------------------------

// OrphanReportView is the review page in one answer: the three ways a row and a
// resource can fail to agree. Nothing here is ever acted on automatically --
// each section is a list of things for a person to look at, and the only
// destructive act on the page asks for a name to be typed.
type OrphanReportView struct {
	ProviderID   string     `json:"provider_id"`
	ProviderName string     `json:"provider_name"`
	LastSweepAt  *time.Time `json:"last_sweep_at,omitempty"`
	// Untracked is a resource wearing this fleet's naming grammar that no row
	// accounts for. It is never deleted from here: the row is the only record
	// of what was rented, and a resource with no row may be another fleet's.
	Untracked []OrphanView `json:"untracked"`
	// NoResource is a row that believes it holds nothing, which is a row an
	// operator can release without anything being lost.
	NoResource []MachineView `json:"no_resource"`
	// Unverified is a machine whose ownership nothing has confirmed, including
	// every quarantined one. Until a person decides, nothing will touch them.
	Unverified []MachineView `json:"unverified"`
}

// OrphanView is one untracked resource, as the last sweep saw it.
type OrphanView struct {
	Name string `json:"name"`
	// Note is what an operator should do about it, which for an untracked
	// resource is always "look at it yourself": Zoomies will not delete a
	// machine it has no record of creating.
	Note string `json:"note"`
}

// OrphanReport gathers a provider's three disagreements. The untracked half
// comes from the last ownership sweep rather than from a call made now, because
// the page is read far more often than the hypervisor should be asked -- the
// sweep's own timestamp is returned so a stale answer says so.
func (c *Controller) OrphanReport(ctx context.Context, row *store.Provider) (OrphanReportView, error) {
	machines, err := c.st.ListMachinesForProvider(ctx, row.ID)
	if err != nil {
		return OrphanReportView{}, fmt.Errorf("listing the provider's machines: %w", err)
	}
	renderer, err := c.MachineRenderer(ctx)
	if err != nil {
		return OrphanReportView{}, err
	}
	out := OrphanReportView{
		ProviderID:   row.ID,
		ProviderName: row.Name,
		LastSweepAt:  row.LastSweepAt,
		Untracked:    []OrphanView{},
		NoResource:   []MachineView{},
		Unverified:   []MachineView{},
	}
	names := c.ProviderOrphans()[row.ID]
	slices.Sort(names)
	for _, name := range names {
		out.Untracked = append(out.Untracked, OrphanView{
			Name: name,
			Note: "this resource wears the naming Zoomies gives its machines but no row accounts for it. " +
				"Zoomies will never delete it; look at it in " + row.Name + " and remove it there if it is yours and idle.",
		})
	}
	for _, m := range machines {
		switch {
		case m.State == store.MachineDeleted:
			// History. The resource is confirmed gone and the row goes with
			// the next prune.
		case !m.Owns():
			out.NoResource = append(out.NoResource, renderer.View(m))
		case m.State == store.MachineQuarantined || m.OwnershipError != "" || m.OwnershipVerifiedAt == nil:
			out.Unverified = append(out.Unverified, renderer.View(m))
		}
	}
	return out, nil
}

package controller

import (
	"context"
	"errors"

	"github.com/eyupio/zoomies/internal/store"
)

func (c *Controller) ControlProvisioning(ctx context.Context, ids []string, action string) ([]store.ProvisioningResult, error) {
	// Serialize with snapshot AND apply, so an old plan cannot create runners
	// after a pause has been acknowledged. Already-issued tasks are unaffected.
	c.reconcileMu.Lock()
	defer c.reconcileMu.Unlock()
	results, err := c.st.ControlProvisioning(ctx, ids, action)
	if err != nil {
		return nil, err
	}
	for _, result := range results {
		if result.OK {
			if j, err := c.st.GetJob(ctx, result.ID); err == nil {
				c.publishJob(ctx, j)
			}
		}
	}
	c.Nudge()
	return results, nil
}

// ErrRunHasNoQueuedJobs is a run-level provisioning action on a run none of
// whose jobs is waiting for a runner here: every job has started or finished,
// or the ones still queued were removed from the queue and are restored from
// the Queue page rather than swept back in with their siblings.
var ErrRunHasNoQueuedJobs = errors.New("no job of this workflow run is queued for this fleet")

// runProvisioningStates is what a run-level action reaches: the run's queued
// jobs in every provisioning state but removed. See RunJobCounts.Controllable.
var runProvisioningStates = []string{"ready", "expedited", store.ProvisioningPaused}

// ControlWorkflowRunProvisioning is ControlProvisioning for every queued job
// of one run: what the Workflows page's run rows call, since a run has no ID
// of its own to select by, only repo + GitHub's run ID.
//
// store.ErrNotFound for a run this fleet has never heard of, and
// ErrRunHasNoQueuedJobs when it knows the run but nothing in it is waiting
// for a runner here -- the two are different answers for an operator, and a
// 200 with no results would read as a button that did nothing.
func (c *Controller) ControlWorkflowRunProvisioning(ctx context.Context, repo string, runID int64, action string) ([]store.ProvisioningResult, error) {
	jobs, err := c.st.ListJobsForRun(ctx, repo, runID)
	if err != nil {
		return nil, err
	}
	if len(jobs) == 0 {
		return nil, store.ErrNotFound
	}
	ids, err := c.st.ProvisioningSelection(ctx, store.JobFilter{
		Repos:        []string{repo},
		RunIDs:       []int64{runID},
		Provisioning: runProvisioningStates,
	})
	if err != nil {
		return nil, err
	}
	if len(ids) == 0 {
		return nil, ErrRunHasNoQueuedJobs
	}
	return c.ControlProvisioning(ctx, ids, action)
}

package controller

import (
	"errors"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/store"
)

// The prune loop is the only caller of five delete queries, and its shape
// carries two rules that live nowhere else: a zero window means keep
// everything, and a pruned runner is announced so the Runners page stops
// showing rows that no longer exist. Neither was tested, and both fail
// silently: history that quietly disappears looks like history nobody wrote,
// and a stale page looks like a page nobody reloaded.
func TestPruningHonoursEachWindowAndKeepsEverythingWhenOneIsZero(t *testing.T) {
	h := newHarness(t)
	_, pool, _ := h.fleet()
	now := h.c.Now()

	seed := func() {
		t.Helper()
		if err := h.st.AppendScalingEvent(h.ctx, &store.ScalingEvent{
			PoolID: pool.ID, PoolName: pool.Name, To: 1, Reason: "old",
			CreatedAt: now.Add(-48 * time.Hour),
		}); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
		if err := h.st.RecordSample(h.ctx, store.FleetSample{At: now.Add(-48 * time.Hour), TotalRunners: 1}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
		if err := h.st.RecordDelivery(h.ctx, &store.WebhookDelivery{
			DeliveryID: "old", Event: "workflow_job", Status: "accepted",
			ReceivedAt: now.Add(-48 * time.Hour),
		}); err != nil {
			t.Fatalf("RecordDelivery: %v", err)
		}
	}

	// A cleared window means "keep everything", which is what an operator who
	// emptied the setting meant -- not "delete everything older than now".
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{}
	})
	seed()
	h.c.prune(h.ctx)

	events, err := h.st.ListScalingEvents(h.ctx, "", 10)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	samples, err := h.st.ListSamples(h.ctx, now.Add(-72*time.Hour))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	deliveries, err := h.st.ListDeliveries(h.ctx, "", 10)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(events) != 1 || len(samples) != 1 || len(deliveries) != 1 {
		t.Fatalf("a zero window deleted history: %d scaling events, %d samples, %d deliveries left, want 1 of each",
			len(events), len(samples), len(deliveries))
	}

	// And a window that is set takes exactly what is older than it.
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{
			ScalingEvents: 24 * time.Hour, Samples: 24 * time.Hour, Webhooks: 24 * time.Hour,
			Jobs: 24 * time.Hour, Runners: 24 * time.Hour,
		}
	})
	h.c.prune(h.ctx)

	if events, err = h.st.ListScalingEvents(h.ctx, "", 10); err != nil || len(events) != 0 {
		t.Errorf("scaling events after the prune = %d (err %v), want none: they follow the scaling-events window", len(events), err)
	}
	if samples, err = h.st.ListSamples(h.ctx, now.Add(-72*time.Hour)); err != nil || len(samples) != 0 {
		t.Errorf("samples after the prune = %d (err %v), want none", len(samples), err)
	}
	if deliveries, err = h.st.ListDeliveries(h.ctx, "", 10); err != nil || len(deliveries) != 0 {
		t.Errorf("deliveries after the prune = %d (err %v), want none", len(deliveries), err)
	}
}

// Every pruned runner is announced. The delete happens in the database, which
// tells nobody, so without this the Runners page keeps showing runners that
// were deleted an hour ago until somebody reloads it.
func TestAPrunedRunnerIsAnnounced(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}

	sub := h.listen(events.KindRunnerDeleted)

	// An hour of retention and an hour on the clock: the row is old enough to
	// go without the test having to wait for it.
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{Runners: time.Hour}
	})
	h.advance(2 * time.Hour)
	h.c.prune(h.ctx)

	select {
	case <-sub.C:
	case <-time.After(2 * time.Second):
		t.Fatal("the pruned runner was never announced; every open Runners page still shows it")
	}
}

// A prune that takes thousands of rows must not take every open tab with it.
//
// A subscriber's queue is 256 deep and the bus drops a subscriber that falls
// behind. The hourly prune deletes everything past the retention window in one
// pass, and announcing each row filled that queue several times over: every
// tab was cut off, showed itself as disconnected, reconnected and refetched six
// endpoints. The storm was the announcement rather than the deletion, so the
// announcement is bounded.
func TestABulkPruneAnnouncesOnceRatherThanDroppingEverySubscriber(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()

	for i := range announceEach + 5 {
		r := h.runnerRow(pool, host, store.RunnerIdle)
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "removed"); err != nil {
			t.Fatalf("TransitionRunner %d: %v", i, err)
		}
	}

	sub := h.listen(events.KindRunnerDeleted, events.KindResync)
	h.c.UpdateConfig(func(c *config.Config) {
		c.Retention = config.Retention{Runners: time.Hour}
	})
	h.advance(2 * time.Hour)
	h.c.prune(h.ctx)

	// One frame, and it is the one that means "fetch the resources again".
	select {
	case ev := <-sub.C:
		if ev.Kind != events.KindResync {
			t.Fatalf("the first frame was %q; a row-by-row announcement of a bulk prune fills every subscriber's queue and cuts it off", ev.Kind)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("a bulk prune announced nothing at all, so every open page keeps showing rows that are gone")
	}
	select {
	case ev := <-sub.C:
		t.Fatalf("a second frame (%q) followed the resync; one is the whole point", ev.Kind)
	case <-time.After(200 * time.Millisecond):
	}
}

// A machine's row outlives its resource on purpose: it is the only record of
// what was rented, when, and what it cost, and an operator reconciling a
// hypervisor bill against the fleet is reading exactly that. What retention
// takes is the confirmed-gone rows, and never one that still names a resource.
func TestPruningKeepsEveryMachineThatMayStillHaveAResource(t *testing.T) {
	h := newHarness(t)
	row := h.providerRow(t, "lab")
	now := h.c.Now()

	gone := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned}
	if err := h.st.CreateMachine(h.ctx, gone); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	if err := h.st.SetMachineResource(h.ctx, gone.ID, "zone-a", "143", "fp", "ctl_test"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	if _, err := h.st.ConfirmMachineDeleted(h.ctx, gone.ID, now.Add(-48*time.Hour)); err != nil {
		t.Fatalf("ConfirmMachineDeleted: %v", err)
	}
	for _, to := range []store.MachineState{store.MachineFailed, store.MachineDeleted} {
		if _, err := h.st.TransitionMachine(h.ctx, gone.ID, to, ""); err != nil {
			t.Fatalf("TransitionMachine(%s): %v", to, err)
		}
	}

	// Failed, old, and still naming a resource: the one row a prune must never
	// take, because deleting it is how a fleet loses a machine it is paying for.
	kept := &store.Machine{ProviderID: row.ID, State: store.MachinePlanned}
	if err := h.st.CreateMachine(h.ctx, kept); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	if err := h.st.SetMachineResource(h.ctx, kept.ID, "zone-a", "144", "fp", "ctl_test"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	if _, err := h.st.TransitionMachine(h.ctx, kept.ID, store.MachineFailed, "the guest never joined"); err != nil {
		t.Fatalf("TransitionMachine: %v", err)
	}

	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Machines: 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, err := h.st.GetMachine(h.ctx, gone.ID); !errors.Is(err, store.ErrNotFound) {
		t.Errorf("a machine confirmed gone 48 hours ago survived a 24-hour window: %v", err)
	}
	if _, err := h.st.GetMachine(h.ctx, kept.ID); err != nil {
		t.Errorf("a failed machine that still names a resource was pruned: %v", err)
	}
}

// The prune pass is what rolls usage up. Without it the roll-up never moves,
// the report falls back to rows a week's retention has already taken, and last
// month's runner-hours quietly disappear.
func TestPruningRollsUsageUpSoARunnerOutlivesItsRow(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := &store.Runner{PoolID: pool.ID, HostID: host.ID, Name: "rolled-up"}
	if err := h.st.CreateRunner(h.ctx, r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	for _, to := range []store.RunnerState{store.RunnerRegistering, store.RunnerRemoved} {
		if _, err := h.st.TransitionRunner(h.ctx, r.ID, to, ""); err != nil {
			t.Fatalf("TransitionRunner(%s): %v", to, err)
		}
	}
	for _, side := range []bool{true, false} {
		if _, err := h.st.ConfirmRunnerCleanup(h.ctx, r.ID, side); err != nil {
			t.Fatalf("ConfirmRunnerCleanup: %v", err)
		}
	}

	h.advance(10 * 24 * time.Hour)
	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Runners: 7 * 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, err := h.st.GetRunner(h.ctx, r.ID); !errors.Is(err, store.ErrNotFound) {
		t.Fatalf("a runner ten days gone survived a seven-day window: %v", err)
	}
	_, until, ok, err := h.st.UsageRollupRange(h.ctx)
	if err != nil || !ok || until.Before(h.c.Now().Add(-24*time.Hour)) {
		t.Fatalf("the prune did not roll usage up to today: until %v, ok %v, %v", until, ok, err)
	}
}

// A job the jobs retention takes is counted in the installation report's
// roll-up by the same pass, so a month's report still has it. The pass that
// could prune it before counting it -- a roll-up that failed, or one that has
// not reached its day -- prunes nothing instead.
func TestPruningCountsAJobForTheInstallationReportBeforeDeletingIt(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	queued := h.c.Now()
	done := queued.Add(time.Minute)
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{GitHubJobID: 77, Repo: "acme/app", State: store.JobCompleted,
		Matched: true, InstallationID: inst.ID, PoolID: pool.ID, QueuedAt: queued, StartedAt: &done,
		CompletedAt: &done, RunnerName: "GitHub Actions 1"}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	h.advance(10 * 24 * time.Hour)
	h.c.UpdateConfig(func(c *config.Config) { c.Retention = config.Retention{Jobs: 7 * 24 * time.Hour} })
	h.c.prune(h.ctx)

	if _, n, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 10}); err != nil || n != 0 {
		t.Fatalf("%d jobs left after a seven-day window, %v; want the ten-day-old one pruned", n, err)
	}
	rep, err := h.st.InstallationReport(h.ctx, inst.ID, queued, h.c.Now())
	if err != nil {
		t.Fatalf("InstallationReport: %v", err)
	}
	if rep.Counts.Observed != 1 || rep.Counts.RanElsewhere != 1 {
		t.Fatalf("after the prune the report counts %+v; want the pruned job, from the roll-up", rep.Counts)
	}
}

package controller

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/events"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// reapInterval is how often Zoomies' view of the fleet is compared against the
// runners GitHub thinks exist. It is slow because it costs one API call per
// installation and the situation it fixes -- an orphaned registration -- is
// untidy rather than urgent.
const reapInterval = 10 * time.Minute

// lifecycleCallTimeout bounds a detached create or remove's GitHub work: a
// credential mint is one call, a registration delete is up to two (a lookup
// by name, then the delete), each already bounded by the client's own
// per-request timeout. This is the outer net for the pair of them together,
// matching the same defence-in-depth the machine loop gives a provider call.
const lifecycleCallTimeout = 2 * time.Minute

// reconcileLoop runs a pass on the configured interval and immediately on
// every nudge, with only one pass in flight at a time.
func (c *Controller) reconcileLoop(ctx context.Context) {
	interval := c.schedulerInterval()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	// One pass at startup so a controller that was down while jobs queued
	// starts creating runners without waiting out the interval.
	c.reconcileNow(ctx)

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			c.reconcileNow(ctx)
		case <-c.nudges:
			// Every nudge that arrived while the previous pass ran has already
			// collapsed into the single token we just took, so this is one
			// pass for the whole burst.
			c.reconcileNow(ctx)
		}
		// The interval is a runtime setting, and UpdateConfig nudges this
		// loop, so a change is in force from the pass after it was accepted.
		if d := c.schedulerInterval(); d != interval {
			interval = d
			ticker.Reset(d)
		}
	}
}

// reconcileNow runs one pass and logs a failure rather than propagating it: a
// transient database or GitHub error must not stop the loop.
func (c *Controller) reconcileNow(ctx context.Context) {
	if err := c.Reconcile(ctx); err != nil && ctx.Err() == nil {
		c.metrics.reconcileErrors.Inc()
		c.log.Error("reconcile pass failed; the next pass will try again", "error", err)
	}
}

// Reconcile runs exactly one scheduling pass: snapshot the fleet, decide, and
// apply. It is exported so that tests and the API can force a pass and know it
// has finished, which Nudge deliberately cannot promise.
func (c *Controller) Reconcile(ctx context.Context) error {
	c.reconcileMu.Lock()
	defer c.reconcileMu.Unlock()

	started := time.Now()
	// What the previous pass held back at the minting limit is spent: this
	// pass either gets those creations through or holds them back again, and
	// the problems list should describe now rather than then.
	c.resetDeferredMints()
	if err := c.recoverHostCleanup(ctx); err != nil {
		return fmt.Errorf("recovering unfinished host cleanup: %w", err)
	}
	placementVersion := c.placementVersion.Load()
	snap, err := c.snapshot(ctx)
	if err != nil {
		return err
	}
	plan := scheduler.Decide(snap)
	if c.cfg().Scheduler.PlacementMode == "shadow" {
		candidate := snap
		candidate.PreferReadiness = true
		alternative := scheduler.Decide(candidate)
		c.log.Debug("compared host placement policies", "current", plan.Pools, "readiness", alternative.Pools)
	}
	for _, pp := range plan.Pools {
		if pp.History != "" {
			c.log.Debug("job history placement", "pool", pp.PoolName, "mode", snap.HistorySizing, "decision", pp.History)
		}
	}
	c.rememberPlacement(snap, plan, placementVersion)
	c.setLastPlan(plan)
	c.setReserved(snap)
	c.apply(ctx, snap, plan)
	c.publishCapacitySignals(ctx, snap, plan)
	// The pass may have changed what the queue and the fleet look like, and
	// time alone changes the wait percentiles; this is the moment the Overview
	// learns either way.
	c.publishDerived(ctx)
	c.passes.Add(1)
	c.metrics.reconcileDuration.Observe(time.Since(started).Seconds())
	return nil
}

// snapshot gathers everything the scheduler needs in one place. The scheduler
// reads no clock and no database, so this is the only point at which a
// decision is coupled to the state of the world.
func (c *Controller) snapshot(ctx context.Context) (scheduler.Snapshot, error) {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("listing pools: %w", err)
	}
	// The scheduler sizes a pool by its minimum, so it is handed the minimum
	// in force -- the fleet's where the pool set none -- rather than the row.
	pools = c.sizingPools(pools)
	runners, err := c.st.SchedulingRunners(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("listing scheduling runners: %w", err)
	}
	jobs, err := c.st.ListQueuedJobs(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("listing queued jobs: %w", err)
	}
	activeByRepository, queuedByRepository, err := c.st.RepositoryJobCounts(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("counting jobs by repository: %w", err)
	}
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("listing hosts: %w", err)
	}
	installations, err := c.st.ListInstallations(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("listing installations: %w", err)
	}
	lastProvisioned, err := c.st.LastProvisioned(ctx)
	if err != nil {
		return scheduler.Snapshot{}, fmt.Errorf("reading provisioning order: %w", err)
	}
	now := c.Now()
	readiness := make(map[string]map[string]time.Duration)
	if c.cfg().Scheduler.PlacementMode == "readiness" || c.cfg().Scheduler.PlacementMode == "shadow" {
		if estimates, err := c.st.StartupEstimates(ctx, now.Add(-24*time.Hour)); err == nil {
			images := map[string]string{}
			for _, p := range pools {
				images[p.ID] = c.RunnerImage(p)
			}
			for _, e := range estimates {
				if images[e.PoolID] != e.Image {
					continue
				}
				if readiness[e.PoolID] == nil {
					readiness[e.PoolID] = map[string]time.Duration{}
				}
				readiness[e.PoolID][e.HostID] = time.Duration(e.Milliseconds) * time.Millisecond
			}
		}
	}
	mode := c.cfg().Scheduler.HistorySizing
	var history map[store.JobUsageKey][]store.JobPeak
	if mode == scheduler.HistoryShadow || mode == scheduler.HistoryOn {
		// Read for every distinct queued job, whichever pool ends up running
		// it: the store answers per pool and the scheduler picks the pool's.
		// A failed read costs this pass its history and nothing else -- the
		// fleet places as it did before history existed.
		var keys []store.JobUsageKey
		for _, j := range jobs {
			if j.State == store.JobQueued {
				keys = append(keys, store.JobUsageKey{Repo: j.Repo, Workflow: j.Workflow, JobName: j.JobName})
			}
		}
		if h, err := c.st.JobUsageHistory(ctx, keys); err == nil {
			history = h
		} else {
			c.log.Warn("could not read job history; placing without it this pass", "error", err)
		}
	}
	return scheduler.Snapshot{
		JobHistory: history, HistorySizing: mode,
		Readiness: readiness, PreferReadiness: c.cfg().Scheduler.PlacementMode == "readiness",
		LastProvisioned:    lastProvisioned,
		Now:                now,
		HeldInstallations:  c.heldInstallations(now),
		Pools:              pools,
		Runners:            runners,
		Jobs:               jobs,
		ActiveByRepository: activeByRepository,
		QueuedByRepository: queuedByRepository,
		Hosts:              hosts,
		Installations:      installations,
		Policy:             c.policy(),
		Jitter:             poolJitter(pools),
	}, nil
}

// poolJitter draws one number per pool for the scheduler to spread its
// start-failure backoff with.
//
// It is drawn here because the scheduler has no random source, for the same
// reason it has no clock: a plan has to be reproducible from the snapshot that
// produced it, and a decision that reached for rand inside could not be put in
// front of a test or explained to an operator afterwards.
func poolJitter(pools []*store.Pool) map[string]float64 {
	out := make(map[string]float64, len(pools))
	for _, p := range pools {
		out[p.ID] = rand.Float64()
	}
	return out
}

// apply executes a plan pool by pool and records what actually happened.
//
// A failure on one action never abandons the rest: one pool being unable to
// reach GitHub must not stop another pool from draining an idle runner.
func (c *Controller) apply(ctx context.Context, snap scheduler.Snapshot, plan scheduler.Plan) {
	// A fenced fleet has decided and does nothing about it. The plan is still
	// computed and published above, which is the point: an operator recovering
	// from a backup can see exactly what this controller would do the moment
	// they lift the fence, and can tell "nothing to do" from "not allowed to".
	if !c.mayAct() {
		return
	}
	pools := make(map[string]*store.Pool, len(snap.Pools))
	for _, p := range snap.Pools {
		pools[p.ID] = p
	}
	// The host a create lands on decides what the runner is given: its
	// default limits are one slot's share of that machine, and the snapshot
	// is the one view of the host the decision was made against.
	hosts := make(map[string]*store.Host, len(snap.Hosts))
	for _, h := range snap.Hosts {
		hosts[h.ID] = h
	}

	// When each pool's first waiting job was queued, for the queued-to-create
	// metric. The snapshot already holds the queued jobs, in the order the
	// store returns them; reading them again for every runner created -- inside
	// reconcileMu, where every other pool's scheduling waits -- was a full list
	// query per create for a figure the pass already had.
	queuedSince := make(map[string]time.Time, len(plan.Pools))
	for _, j := range snap.Jobs {
		if _, seen := queuedSince[j.PoolID]; j.PoolID != "" && !seen {
			queuedSince[j.PoolID] = j.QueuedAt
		}
	}

	type changes struct{ created, drained int }
	counts := make(map[string]*changes, len(plan.Pools))
	for _, a := range plan.Actions {
		if ctx.Err() != nil {
			return
		}
		pool := pools[a.PoolID]
		if pool == nil {
			continue
		}
		n := counts[a.PoolID]
		if n == nil {
			n = &changes{}
			counts[a.PoolID] = n
		}
		switch a.Kind {
		case scheduler.ActionCreate:
			if IsDemoID(pool.InstallationID) {
				// The demo installation has no GitHub behind it, and its
				// client refuses every credential, so a create here can only
				// end as a failed row -- and five of them inside ten minutes
				// put the pool on a start backoff that reads "keeps failing
				// to start" on every queued job in the fixture. The runners
				// a demo shows are the ones the seed wrote; the rest of its
				// demand is left standing rather than manufactured into
				// failures a fleet with nothing wrong with it never had.
				continue
			}
			if err := c.createRunner(ctx, pool, hosts[a.HostID], a, queuedSince[pool.ID]); err != nil {
				if !errors.Is(err, errRegistrationDeferred) {
					c.log.Error("could not create a runner", "pool", pool.Name, "host", a.HostID, "reason", a.Reason, "error", err)
				}
				continue
			}
			n.created++
		case scheduler.ActionDrain:
			if err := c.drainRunnerID(ctx, a.RunnerID, a.Reason, pool); err != nil {
				c.logRunnerAction("drain", a, err)
				continue
			}
			n.drained++
		case scheduler.ActionRemove:
			if err := c.removeRunnerID(ctx, a.RunnerID, a.Reason, pool); err != nil {
				c.logRunnerAction("remove", a, err)
			}
		case scheduler.ActionFail:
			if err := c.failRunner(ctx, a.RunnerID, a.Reason, store.FaultRunnerExited, true); err != nil {
				c.logRunnerAction("fail", a, err)
			}
		}
	}
	for _, pp := range plan.Pools {
		if pools[pp.PoolID] == nil {
			continue
		}
		if n := counts[pp.PoolID]; n != nil {
			c.recordScaling(ctx, pp, n.created, n.drained)
		}
		c.noteBlocked(pp)
		if err := c.st.RecordUsageCapacity(ctx, pp.PoolID, c.Now(), pp.BlockedAtCapacity); err != nil {
			c.log.Error("could not record usage capacity", "pool", pp.PoolID, "error", err)
		}
	}
}

// logRunnerAction reports a failed action, quietly when the runner has simply
// gone: two passes racing over the same dead runner is normal, not an error.
func (c *Controller) logRunnerAction(what string, a scheduler.Action, err error) {
	if errors.Is(err, store.ErrNotFound) || errors.Is(err, store.ErrInvalidTransition) {
		c.log.Debug("skipped a runner action that no longer applies",
			"action", what, "runner", a.RunnerID, "error", err)
		return
	}
	c.log.Error("could not apply a runner action",
		"action", what, "runner", a.RunnerID, "pool", a.PoolName, "reason", a.Reason, "error", err)
}

// recordScaling writes the scaling row the UI's history shows, but only when
// the pool's size actually moved. A "cannot scale" reason is real and gets
// logged, yet writing it as a scaling event every ten seconds would bury the
// decisions that did something.
func (c *Controller) recordScaling(ctx context.Context, pp scheduler.PoolPlan, created, drained int) {
	to := pp.Current + created - drained
	if pp.Reason == "" || to == pp.Current {
		return
	}
	e := &store.ScalingEvent{
		PoolID:   pp.PoolID,
		PoolName: pp.PoolName,
		From:     pp.Current,
		To:       to,
		Reason:   pp.Reason,
	}
	if err := c.st.AppendScalingEvent(ctx, e); err != nil {
		c.log.Error("could not record a scaling event", "pool", pp.PoolName, "error", err)
		return
	}
	c.metrics.scalingEvents.WithLabelValues(pp.PoolName, e.Direction()).Inc()
	c.publish(events.KindScaling, "pool:"+pp.PoolID, e)
	c.log.Info("scaled a pool", "pool", pp.PoolName, "from", e.From, "to", e.To, "reason", pp.Reason)
}

// ---------------------------------------------------------------------------
// Create
// ---------------------------------------------------------------------------

// createRunner materialises one ActionCreate: a row, a GitHub credential and a
// task for the chosen host's agent.
//
// The row is written before the credential is minted so that a failure has
// somewhere to be recorded. A runner that never got a JIT config is marked
// failed with GitHub's own error as its message, which is what the operator
// sees on the Runners page -- the alternative, deleting the row, leaves a pool
// that silently sits one runner short with nothing to explain it.
//
// host is the machine the action chose, from the snapshot the plan was made
// against, and it may be nil for a host that vanished between snapshot and
// apply: the runner is then created with the pool's own limits and nothing
// else, exactly as every runner was before defaults existed. The limits are
// decided here and written on the row before the create task carries them,
// so the Runners page can say what a runner was given and where the figure
// came from -- an OOM kill on a defaulted limit points at the host's capacity,
// not at a pool field nobody set.
// queuedSince is when the pool's first waiting job was queued, or zero when it
// has none.
func (c *Controller) createRunner(ctx context.Context, pool *store.Pool, host *store.Host, a scheduler.Action, queuedSince time.Time) error {
	if !c.mayAct() {
		return nil
	}
	inst, err := c.st.GetInstallation(ctx, pool.InstallationID)
	if err != nil {
		return fmt.Errorf("pool %s points at installation %s, which is not there; edit the pool to choose an installation: %w",
			pool.Name, pool.InstallationID, err)
	}

	if !c.admitCredentialMint(inst.ID) {
		return errRegistrationDeferred
	}
	detached := false
	defer func() {
		if !detached {
			c.releaseCredentialMint(inst.ID)
		}
	}()
	// Sized as the pass sized it, so a minimum the pool follows from the
	// fleet raises a thin share exactly as one of its own would; the pool
	// itself is not written.
	cfg := c.cfg()
	resources, source := scheduler.Allocation(sizingPool(pool, cfg.Runners), host, cfg.Scheduler.DefaultRunnerLimits)
	if a.Size != nil {
		// No host had room for the pool's standard size, and the pass placed
		// this one smaller, at or above the pool's minimum. The row carries
		// what it was given, because that is what its host is charged for it
		// and what an operator reading a slow job needs to know.
		resources.CPUs, resources.MemoryMB = a.Size.CPUs, a.Size.MemoryMB
		source = store.AllocationReduced
		if a.SizedFromHistory {
			// Larger than the share, not smaller: the jobs waiting are known
			// to need more than a slot of this host.
			source = store.AllocationHistory
		}
	}
	resources.MinCPUs, resources.MinMemoryMB = 0, 0
	name := github.RunnerName(pool)
	r := &store.Runner{
		PoolID:            pool.ID,
		HostID:            a.HostID,
		Name:              name,
		State:             store.RunnerProvisioning,
		Ephemeral:         pool.Ephemeral,
		Labels:            pool.Labels,
		Image:             c.RunnerImage(pool),
		RunnerVersion:     c.runnerVersion(pool),
		Message:           a.Reason,
		AllocatedCPUs:     resources.CPUs,
		AllocatedMemoryMB: resources.MemoryMB,
		AllocationSource:  source,
		SizedForCPUs:      buildSizedCPUs(pool, host, resources.CPUs),
	}
	if err := c.st.CreateRunner(ctx, r); err != nil {
		return fmt.Errorf("creating the runner row for %s: %w", name, err)
	}
	if !queuedSince.IsZero() {
		observeDuration(c.metrics.queuedToCreate, pool.Name, string(pool.Backend), queuedSince, r.CreatedAt)
	}
	c.publishRunner(ctx, events.KindRunnerCreated, r)

	// Minting a credential is a GitHub round trip. It is detached here, the
	// same way the machine loop detaches a provider call from its own pass
	// lock: reconcileMu must not span it, or a pool's scale-up holds every
	// other pool and installation's scheduling for as long as GitHub takes to
	// answer. The row already exists and carries RunnerProvisioning, so the
	// next snapshot counts it towards the pool's current size either way.
	c.lifecycleCalls.Add(1)
	detached = true
	go func() {
		defer c.lifecycleCalls.Done()
		// Release admission before signalling completion to lifecycle waiters.
		defer c.releaseCredentialMint(inst.ID)
		cctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), lifecycleCallTimeout)
		defer cancel()
		c.finishCreateRunner(cctx, inst, pool, r, a, name, resources, source)
	}()
	c.log.Info("creating a runner",
		"pool", pool.Name, "runner", r.ID, "name", name, "host", a.HostID, "reason", a.Reason)
	return nil
}

// finishCreateRunner mints the GitHub credential a newly-created runner row
// needs and either enqueues its create task or marks it failed, whichever
// GitHub answers. It runs apart from the pass that wrote the row -- see
// createRunner -- so its own errors end here rather than back in apply().
func (c *Controller) finishCreateRunner(ctx context.Context, inst *store.Installation, pool *store.Pool, r *store.Runner, a scheduler.Action, name string, resources store.Resources, source string) {
	creds, ghID, err := c.mintCredentials(ctx, inst, pool, name)
	if err != nil {
		msg := fmt.Sprintf("GitHub would not register %s: %v", name, err)
		if failed, ferr := c.st.FailRunner(ctx, r.ID, msg, store.FaultRegistration); ferr == nil {
			c.publishRunner(ctx, events.KindRunnerUpdated, failed)
			if !errors.Is(err, github.ErrRateLimited) {
				c.noteRunnerStartFailure(ctx, r, failed)
			}
		} else {
			c.log.Error("could not mark a runner failed after its registration failed",
				"runner", r.ID, "error", ferr)
		}
		c.log.Error("could not create a runner",
			"pool", pool.Name, "host", a.HostID, "reason", a.Reason, "error", err)
		return
	}
	if ghID != 0 {
		if err := c.st.SetRunnerGitHubID(ctx, r.ID, ghID); err != nil {
			c.log.Error("could not record the GitHub runner ID", "runner", r.ID, "error", err)
		}
		r.GitHubRunnerID = ghID
	}

	spec := backend.Spec{
		Name:        name,
		RunnerID:    r.ID,
		PoolID:      pool.ID,
		PoolName:    pool.Name,
		Image:       r.Image,
		PullPolicy:  pool.PullPolicy,
		Credentials: creds,
		Env:         withBuildSizing(runnerEnv(c.cfg().Runners, pool), r.SizedForCPUs),
		Ephemeral:   pool.Ephemeral,
		// What the row records, not the pool's field: a pool that sets no
		// limit gets one slot's share of the host, and the agent applies
		// whatever this says without knowing the difference.
		Resources:       resources,
		ResourcesSource: source,
		Cache:           pool.Cache,
		// An organisation installation's target is the organisation, which is
		// no repository at all; a pool under one names its cache's repository
		// itself, and that is the identity the runner should carry.
		Repository:    firstNonEmpty(strings.TrimSpace(pool.Cache.Repository), inst.Target),
		DockerMode:    pool.DockerMode,
		RunAsRoot:     pool.RunAsRoot,
		Network:       c.cfg().Agent.Network,
		RunnerVersion: r.RunnerVersion,
	}
	if timeout := c.policy().For(pool).ProvisionTimeout; timeout > 0 {
		spec.StartBefore = r.CreatedAt.Add(timeout)
	}

	// Credential minting is deliberately detached from the reconcile pass. In
	// that gap GitHub may cancel the queued job and the next pass may drain the
	// now-surplus provisioning row. Re-read under the reconcile lock before
	// publishing the create task: otherwise the late JIT response can enqueue a
	// create after the stop, bringing up exactly the runner cancellation meant
	// to avoid.
	//
	// Hold the lock only across the local read and enqueue, never across the
	// GitHub calls above or the cleanup below. This leaves the slow-call promise
	// of createRunner intact while making the final state check indivisible from
	// the scheduler pass that can drain it.
	c.reconcileMu.Lock()
	current, currentErr := c.st.GetRunner(ctx, r.ID)
	if currentErr == nil && current.State == store.RunnerProvisioning {
		c.enqueueLifecycle(ctx, a.HostID, agent.Task{
			Kind:     agent.TaskCreateRunner,
			RunnerID: r.ID,
			Spec:     &spec,
			Backend:  pool.Backend,
		})
		c.reconcileMu.Unlock()
		return
	}
	c.reconcileMu.Unlock()

	if currentErr != nil {
		// A JIT configuration may already have registered the runner even though
		// its row disappeared. Use the copy carrying that registration ID so the
		// remote side is not leaked.
		c.deleteRegistration(ctx, r, pool)
		c.log.Warn("discarded a runner credential because its row disappeared before creation",
			"runner", r.ID, "error", currentErr)
		return
	}

	switch current.State {
	case store.RunnerDraining:
		// The host removal is idempotent even when the earlier stop already found
		// nothing. removeRunner also deletes the newly-minted registration and
		// leaves durable cleanup intent if either side is temporarily unavailable.
		if _, err := c.removeRunner(ctx, current,
			"queued demand disappeared before this runner finished starting", pool); err != nil {
			c.log.Warn("could not finish cancelling a runner whose credential arrived late",
				"runner", current.ID, "state", current.State, "error", err)
		}
	case store.RunnerFailed:
		// A failed start must remain failed long enough to be visible in the
		// pool diagnostics and failure counters. The create task was never
		// published, so only the registration minted by this late response needs
		// cleanup; transitioning the row to removed here would erase the fault.
		c.deleteRegistration(ctx, current, pool)
	case store.RunnerRemoved:
		c.enqueueLifecycle(ctx, current.HostID, agent.Task{
			Kind: agent.TaskRemoveRunner, RunnerID: current.ID, Backend: pool.Backend,
		})
		c.deleteRegistration(ctx, current, pool)
	default:
		// A create task has already advanced this runner. Do not enqueue a second
		// one; GitHub's in-progress event remains authoritative if it is busy.
		c.log.Debug("runner moved on before its detached credential mint finished; skipped duplicate create",
			"runner", current.ID, "state", current.State)
	}
}

// mintCredentials asks GitHub for whatever this pool's runners register with.
//
// Ephemeral pools get a JIT configuration: it registers exactly one runner,
// cannot be replayed, and expires quickly, which is what makes it safe to hand
// to a container through its environment. Non-ephemeral pools have to run
// config.sh, so they get a registration token instead.
func (c *Controller) mintCredentials(ctx context.Context, inst *store.Installation, pool *store.Pool, name string) (creds backend.Credentials, id int64, err error) {
	if c.githubHeld(inst.ID, c.Now()) {
		return backend.Credentials{}, 0, errRegistrationHeld
	}
	defer func() {
		if errors.Is(err, github.ErrRateLimited) && err != errRegistrationHeld {
			c.holdRateLimited(inst.ID, err, c.Now(), "registering a runner")
		}
	}()
	client, err := c.clients.get(ctx, inst)
	if err != nil {
		return backend.Credentials{}, 0, err
	}

	if pool.Ephemeral {
		group, unresolved, publicBlocked := c.clients.runnerGroupID(ctx, inst, client, pool.RunnerGroup)
		c.noteRunnerGroup(pool, pool.RunnerGroup, unresolved, publicBlocked)
		if c.githubHeld(inst.ID, c.Now()) {
			return backend.Credentials{}, 0, errRegistrationHeld
		}
		jit, err := client.CreateJITConfig(ctx, github.JITRequest{
			Name:          name,
			Labels:        pool.Labels,
			RunnerGroupID: group,
		})
		c.observeGitHub(inst.ID, err)
		if err != nil {
			return backend.Credentials{}, 0, err
		}
		return backend.Credentials{JITConfig: jit.Encoded}, jit.RunnerID, nil
	}

	tok, err := client.CreateRegistrationToken(ctx)
	c.observeGitHub(inst.ID, err)
	if err != nil {
		return backend.Credentials{}, 0, err
	}
	return backend.Credentials{
		RegistrationToken: tok.Token,
		ExpiresAt:         tok.ExpiresAt,
		URL:               client.WebURL(),
		RunnerGroup:       pool.RunnerGroup,
		Labels:            pool.Labels,
		NoDefaultLabels:   pool.NoDefaultLabels,
	}, 0, nil
}

// RunnerImage returns the image a pool's runners use.
//
// Three answers in order. A pool that names an image gets it, unchanged: an
// operator who has built their own is not second-guessed. Otherwise the pool's
// platform picks the variant, so a pool called zoomies-4vcpu-debian-12 boots
// the Debian 12 image without anyone keeping the two in step by hand. A pool
// that names neither falls back to the instance default.
//
// Whichever it lands on, a pool that gives its jobs a daemon then runs that
// image's Docker variant. The API already writes the swap into the pool when
// it is saved; it is made again here because this is the one place that sees
// the other two answers, and because what runs should be decided where the
// runner is made rather than trusted to every path that ever wrote a pool row.
func (c *Controller) RunnerImage(p *store.Pool) string {
	return config.ResolvePoolRunnerImage(p.Image, p.Platform.OS, p.Platform.OSVersion,
		c.cfg().GitHub.RunnerImage, p.DockerMode.GivesDaemon())
}

func (c *Controller) runnerVersion(p *store.Pool) string {
	if strings.TrimSpace(p.RunnerVersion) != "" {
		return p.RunnerVersion
	}
	return c.cfg().GitHub.RunnerVersion
}

// ---------------------------------------------------------------------------
// Drain, remove, fail
// ---------------------------------------------------------------------------

// ErrConfirmationRequired is an operator asking to drain a runner that is
// running a job, without having said they accept losing it.
//
// A drain is not the gentle option it reads as. The stop task carries
// agent.DefaultStopTimeout, so the runner gets five minutes and is then killed;
// a twenty-minute job drained at minute one dies at minute six and GitHub marks
// it failed. That is the behaviour -- an operator draining a host for
// maintenance needs the machine to actually empty -- but it must not be
// something they get by accident, so the paths an operator reaches ask first.
//
// The scheduler is deliberately not subject to this. It reaches a drain through
// the unexported drainRunnerID, and never proposes one for a busy runner in the
// first place; automatic scale-down must not be waiting on anybody to confirm.
var ErrConfirmationRequired = errors.New("this runner is running a job, and draining it will end that job")

// DrainRunner asks a runner to finish its current job and exit.
//
// confirmed is the operator saying they accept that a job in flight will be
// ended: see ErrConfirmationRequired. It is ignored for a runner that is not
// busy, because there is nothing to lose.
func (c *Controller) DrainRunner(ctx context.Context, runnerID, reason string, confirmed bool) (*store.Runner, error) {
	r, err := c.st.GetRunner(ctx, runnerID)
	if err != nil {
		return nil, err
	}
	if r.State.Terminal() {
		return nil, fmt.Errorf("%w: runner %s is already %s", store.ErrInvalidTransition, runnerID, r.State)
	}
	if r.State == store.RunnerBusy && !confirmed {
		return nil, fmt.Errorf("%w: runner %s has five minutes to finish and is then stopped", ErrConfirmationRequired, r.Name)
	}
	if reason == "" {
		reason = "drained by an operator"
	}
	return c.drainRunner(ctx, r, reason, nil, false)
}

// RemoveRunner tears a runner down now and deletes its GitHub registration.
// Without force it drains instead, which still ends a running job after the
// stop timeout -- so the unforced path asks for the same acknowledgement a
// direct drain does.
func (c *Controller) RemoveRunner(ctx context.Context, runnerID, reason string, force, confirmed bool) (*store.Runner, error) {
	r, err := c.st.GetRunner(ctx, runnerID)
	if err != nil {
		return nil, err
	}
	if reason == "" {
		reason = "removed by an operator"
	}
	if !force && r.State == store.RunnerBusy {
		if !confirmed {
			return nil, fmt.Errorf("%w: runner %s has five minutes to finish and is then stopped", ErrConfirmationRequired, r.Name)
		}
		return c.drainRunner(ctx, r, reason+" (draining first so the running job finishes)", nil, false)
	}
	if r.State == store.RunnerRemoved {
		return r, nil
	}
	return c.removeRunner(ctx, r, reason, nil)
}

func (c *Controller) drainRunnerID(ctx context.Context, id, reason string, pool *store.Pool) error {
	r, err := c.st.GetRunner(ctx, id)
	if err != nil {
		return err
	}
	_, err = c.drainRunner(ctx, r, reason, pool, true)
	return err
}

// drainRunner moves a runner to draining and asks its host to stop it.
//
// unlessBusy is for the scheduler's own drains, which were decided for a runner
// that was not running a job. The row is checked in the same write as the
// transition, so one that has taken a job since is refused with
// store.ErrInvalidTransition instead of having its job stopped. An operator's
// drain passes false: draining a busy runner is what they asked for, behind
// the confirmation DrainRunner has already taken.
func (c *Controller) drainRunner(ctx context.Context, r *store.Runner, reason string, pool *store.Pool, unlessBusy bool) (*store.Runner, error) {
	if !c.mayAct() {
		return nil, errors.New("controller authority is paused; retry after recovery or lease renewal")
	}
	transition := c.st.TransitionRunner
	if unlessBusy {
		transition = c.st.TransitionRunnerUnlessBusy
	}
	updated, err := transition(ctx, r.ID, store.RunnerDraining, reason)
	if err != nil {
		return nil, err
	}
	c.publishRunner(ctx, events.KindRunnerUpdated, updated)
	c.enqueueLifecycle(ctx, r.HostID, agent.Task{
		Kind:        agent.TaskStopRunner,
		RunnerID:    r.ID,
		Backend:     c.backendKind(ctx, r, pool),
		StopTimeout: agent.DefaultStopTimeout,
	})
	c.log.Info("draining a runner", "runner", r.ID, "name", r.Name, "reason", reason)
	return updated, nil
}

// removeRunnerID is the scheduler's own path to a removal, reached only from
// apply() under reconcileMu. Deleting the GitHub registration is detached the
// same way minting a credential is in createRunner: the task goes out and this
// returns at once, so a bulk drain does not hold every other pool and
// installation's scheduling for as long as GitHub takes to answer each one in
// turn.
//
// claimRemoval is what makes that safe. The row does not read as
// RunnerRemoved until the detached call finishes -- see finishRemoveRunner --
// so without it the next pass would see the same not-yet-removed runner and
// redecide the identical ActionRemove before the first attempt had finished,
// dispatching a second registration delete alongside the first.
func (c *Controller) removeRunnerID(ctx context.Context, id, reason string, pool *store.Pool) error {
	r, err := c.st.GetRunner(ctx, id)
	if err != nil {
		return err
	}
	if !c.claimRemoval(r.ID) {
		return nil
	}
	c.enqueueLifecycle(ctx, r.HostID, agent.Task{
		Kind:     agent.TaskRemoveRunner,
		RunnerID: r.ID,
		Backend:  c.backendKind(ctx, r, pool),
	})
	c.lifecycleCalls.Add(1)
	go func() {
		defer c.lifecycleCalls.Done()
		defer c.releaseRemoval(r.ID)
		cctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), lifecycleCallTimeout)
		defer cancel()
		if _, err := c.finishRemoveRunner(cctx, r, reason, pool); err != nil {
			c.logRunnerAction("remove", scheduler.Action{RunnerID: id, Reason: reason}, err)
		}
	}()
	return nil
}

// claimRemoval reports whether this runner's removal may proceed, claiming it
// for the caller if so. A runner already claimed keeps whatever pass claimed
// it first.
func (c *Controller) claimRemoval(runnerID string) bool {
	c.removingMu.Lock()
	defer c.removingMu.Unlock()
	if _, ok := c.removing[runnerID]; ok {
		return false
	}
	c.removing[runnerID] = struct{}{}
	return true
}

func (c *Controller) releaseRemoval(runnerID string) {
	c.removingMu.Lock()
	delete(c.removing, runnerID)
	c.removingMu.Unlock()
}

// removeRunner tears the workload down, deletes the GitHub registration and
// marks the row removed, in that order, synchronously -- used by the two
// paths that answer a caller with the result: the operator-facing
// RemoveRunner, and a host reporting a runner it was told to give up as lost.
func (c *Controller) removeRunner(ctx context.Context, r *store.Runner, reason string, pool *store.Pool) (*store.Runner, error) {
	if !c.mayAct() {
		return nil, errors.New("controller authority is paused; retry after recovery or lease renewal")
	}
	c.enqueueLifecycle(ctx, r.HostID, agent.Task{
		Kind:     agent.TaskRemoveRunner,
		RunnerID: r.ID,
		Backend:  c.backendKind(ctx, r, pool),
	})
	return c.finishRemoveRunner(ctx, r, reason, pool)
}

// finishRemoveRunner deletes a runner's GitHub registration and marks its row
// removed, in that order: the registration goes first so that a crash in
// between leaves a row we can still find the registration from.
func (c *Controller) finishRemoveRunner(ctx context.Context, r *store.Runner, reason string, pool *store.Pool) (*store.Runner, error) {
	c.deleteRegistration(ctx, r, pool)

	updated, err := c.st.TransitionRunner(ctx, r.ID, store.RunnerRemoved, reason)
	if err != nil {
		return nil, err
	}
	c.publishRunner(ctx, events.KindRunnerUpdated, updated)
	c.log.Info("removed a runner", "runner", r.ID, "name", r.Name, "reason", reason)
	if r.State == store.RunnerBusy {
		// Only a forced removal reaches here with a job still running, and
		// that job is about to fail on GitHub for a reason only this fleet
		// knows.
		// An operator chose this. It is the fleet's failure in the sense that
		// the workflow did nothing wrong, and the one kind that needs no
		// fixing -- so it is worth telling apart from the runner that died on
		// its own, which is a fleet with a problem.
		c.noteRunnerLost(ctx, r, sourceController, reason, store.FaultRemoved)
	}
	return updated, nil
}

// failRunnerID marks a runner failed and says what category the failure
// belongs to, so the row, the job under it and the fleet's counts all agree
// about whose fault it was. Callers that genuinely cannot narrow it pass
// store.FaultRunnerExited, which reads as "go and look" rather than as a
// diagnosis nobody made.
func (c *Controller) failRunnerID(ctx context.Context, id, reason string, fault store.FaultKind) error {
	return c.failRunner(ctx, id, reason, fault, false)
}

// failRunner is failRunnerID with the scheduler's condition available: a
// failure planned against a snapshot is refused, with store.ErrInvalidTransition,
// for a runner that has since taken a job, since failing it would end that job.
// The host-lost and agent-exit paths fail busy runners on purpose and pass false.
func (c *Controller) failRunner(ctx context.Context, id, reason string, fault store.FaultKind, unlessBusy bool) error {
	before, err := c.st.GetRunner(ctx, id)
	if err != nil {
		return err
	}
	fail := c.st.FailRunner
	if unlessBusy {
		fail = c.st.FailRunnerUnlessBusy
	}
	updated, err := fail(ctx, id, reason, fault)
	if err != nil {
		return err
	}
	c.publishRunner(ctx, events.KindRunnerUpdated, updated)
	c.log.Warn("a runner failed", "runner", updated.ID, "name", updated.Name, "reason", reason, "fault", updated.FaultKind)
	c.noteRunnerLost(ctx, before, sourceController, reason, updated.FaultKind)
	c.noteRunnerStartFailure(ctx, before, updated)
	return nil
}

// deleteRegistration removes a runner's registration from GitHub. Failures are
// logged rather than returned: the reaper will find it again, and a GitHub
// outage must not stop Zoomies from freeing the host's capacity.
//
// A JIT-registered runner carries the ID GitHub minted for it. One registered
// with a registration token -- a non-ephemeral pool -- has none until GitHub
// is asked, so it is looked up by name; the alternative was the container's
// own config.sh remove on exit, with a registration token that expires after
// an hour and had usually expired, leaving exactly the ghost that comment
// promised to prevent.
func (c *Controller) deleteRegistration(ctx context.Context, r *store.Runner, pool *store.Pool) {
	if !c.mayAct() {
		return
	}
	if r.GitHubRunnerID == 0 && !store.IsRunnerName(r.Name) {
		c.confirmCleanup(ctx, r.ID, false)
		return
	}
	if pool == nil {
		p, err := c.st.GetPool(ctx, r.PoolID)
		if err != nil {
			return
		}
		pool = p
	}
	if IsDemoID(pool.InstallationID) {
		// Demo fixtures have no GitHub behind them; there is nothing to delete.
		c.confirmCleanup(ctx, r.ID, false)
		return
	}
	inst, err := c.st.GetInstallation(ctx, pool.InstallationID)
	if err != nil {
		return
	}
	if c.githubHeld(inst.ID, c.Now()) {
		return
	}
	client, err := c.clients.get(ctx, inst)
	if err != nil {
		c.log.Warn("could not delete a GitHub runner registration", "runner", r.ID, "error", err)
		return
	}
	id := r.GitHubRunnerID
	if id == 0 {
		remote, err := client.ListRunners(ctx)
		c.observeGitHub(inst.ID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(inst.ID, err, c.Now(), "finding a runner registration")
			}
			c.log.Warn("could not list GitHub runners to find a registration to delete", "runner", r.ID, "name", r.Name, "error", err)
			return
		}
		for _, gr := range remote {
			if gr.Name == r.Name {
				if gr.Busy {
					c.deferBusyRegistration(ctx, r)
					return
				}
				id = gr.ID
				break
			}
		}
		if id == 0 {
			// Never registered, or already gone: either way there is nothing
			// to delete, and nothing worth a warning.
			c.confirmCleanup(ctx, r.ID, false)
			return
		}
	}
	err = client.DeleteRunner(ctx, id)
	c.observeGitHub(inst.ID, err)
	if errors.Is(err, github.ErrRunnerBusy) {
		c.deferBusyRegistration(ctx, r)
		return
	}
	if errors.Is(err, github.ErrRateLimited) {
		c.holdRateLimited(inst.ID, err, c.Now(), "deleting a runner registration")
	}
	if err != nil {
		reason := fmt.Sprintf("the GitHub runner registration could not be deleted: %v", err)
		// Recorded on the row, not only logged. A registration Zoomies could
		// not delete is a ghost on somebody's organisation, and a log line and
		// a counter are not something an operator finds before the runner list
		// is full of them. The reap will try again; until it succeeds, the row
		// says so and runners.cleanup_failed names it.
		if rerr := c.st.RecordRegistrationCleanupFailure(ctx, r.ID, reason); rerr != nil {
			c.log.Warn("could not record a failed registration delete", "runner", r.ID, "error", rerr)
		}
		c.log.Warn("could not delete a GitHub runner registration",
			"runner", r.ID, "github_runner_id", id, "error", err)
		return
	}
	c.confirmCleanup(ctx, r.ID, false)
}

// backendKind names the backend a task should run on. It comes from the pool,
// with the host's default as a fallback for a runner whose pool has gone.
func (c *Controller) backendKind(ctx context.Context, r *store.Runner, pool *store.Pool) store.BackendKind {
	if pool != nil {
		return pool.Backend
	}
	if p, err := c.st.GetPool(ctx, r.PoolID); err == nil {
		return p.Backend
	}
	return ""
}

// ---------------------------------------------------------------------------
// Reaping orphaned GitHub registrations
// ---------------------------------------------------------------------------

// reapLoop periodically reconciles Zoomies' view against GitHub's.
func (c *Controller) reapLoop(ctx context.Context) {
	timer := time.NewTimer(time.Minute)
	defer timer.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
			// Not while fenced. Reaping deletes GitHub registrations, and a
			// restored database's idea of which runners are gone is as old as
			// the backup -- so the one thing it must not do is act on it.
			if !c.Fenced().Fenced {
				c.reap(ctx)
			}
			timer.Reset(reapInterval)
		}
	}
}

// reap deletes GitHub registrations for runners Zoomies considers gone.
//
// An orphaned registration is not harmless: it sits in the organisation's
// runner list forever, and a workflow targeting its labels can be assigned to
// a runner that no longer exists, where the job waits until it times out.
//
// The rule for what may be deleted is deliberately narrow, because this code
// is one API call away from deleting somebody else's runners:
//
//   - the name must carry the "zoomies-" prefix that store.NewRunnerName mints,
//     so a runner another tool registered is never a candidate;
//   - and either Zoomies has a row for it in a terminal state (we know it is
//     dead), or Zoomies has no row at all and GitHub reports it offline (the
//     row was lost, and an offline registration can do no work anyway).
//
// A registration Zoomies has a live row for, or one that is online but
// unknown, is left alone: those are cases where deleting would interrupt work.
func (c *Controller) reap(ctx context.Context) {
	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		c.log.Error("could not list installations to reap runner registrations", "error", err)
		return
	}
	now := c.Now()
	for _, inst := range insts {
		if ctx.Err() != nil {
			return
		}
		// An installation already refusing for quota is not asked again until
		// the hold runs out. The reap shares that hold with the poller: both
		// spend the same quota, so a stand-down either of them earned is one
		// the other would otherwise spend a refused call rediscovering.
		if c.githubHeld(inst.ID, now) {
			continue
		}
		client, err := c.clients.get(ctx, inst)
		if err != nil {
			continue
		}
		remote, err := client.ListRunners(ctx)
		c.observeGitHub(inst.ID, err)
		if err != nil {
			if errors.Is(err, github.ErrRateLimited) {
				c.holdRateLimited(inst.ID, err, now, "listing runners")
				continue
			}
			c.log.Warn("could not list GitHub runners while reaping", "installation", inst.ID, "error", err)
			continue
		}
		// A successful, fully paginated listing is also positive evidence
		// for registrations GitHub removed itself while cleanup was pending.
		presentNames := make(map[string]bool, len(remote))
		presentIDs := make(map[int64]bool, len(remote))
		for _, gr := range remote {
			presentNames[gr.Name] = true
			presentIDs[gr.ID] = true
		}
		pending, perr := c.st.RunnersPendingRegistrationCleanup(ctx, inst.ID)
		if perr != nil {
			c.log.Warn("could not load pending registration cleanup", "installation", inst.ID, "error", perr)
			continue
		}
		for _, row := range pending {
			if !presentNames[row.Name] && (row.GitHubRunnerID == 0 || !presentIDs[row.GitHubRunnerID]) {
				c.confirmCleanup(ctx, row.ID, false)
			}
		}
		// A fleet's runners share a handful of pools, so the pool each row
		// names is read once per pass rather than once per registration.
		// Only a successful read is remembered: a failed one is retried for
		// the next registration, exactly as before.
		pools := map[string]*store.Pool{}
		for _, gr := range remote {
			if !store.IsRunnerName(gr.Name) {
				continue
			}
			row, rerr := c.st.GetRunnerByName(ctx, gr.Name)
			if rerr == nil {
				pool, ok := pools[row.PoolID]
				var err error
				if !ok {
					pool, err = c.st.GetPool(ctx, row.PoolID)
					if err == nil {
						pools[row.PoolID] = pool
					}
				}
				if err != nil || pool.InstallationID != inst.ID || (row.GitHubRunnerID != 0 && row.GitHubRunnerID != gr.ID) {
					continue
				}
			}
			if gr.Busy {
				if rerr == nil && row.State.Terminal() {
					c.deferBusyRegistration(ctx, row)
				}
				continue
			}
			switch {
			case rerr == nil && row.State.Terminal():
				// We know this one is dead.
			case errors.Is(rerr, store.ErrNotFound) && strings.EqualFold(gr.Status, "offline"):
				// Our row is gone and the runner cannot pick up work.
			default:
				continue
			}
			err := client.DeleteRunner(ctx, gr.ID)
			c.observeGitHub(inst.ID, err)
			if errors.Is(err, github.ErrRateLimited) {
				// Stop on this installation rather than working down the rest
				// of its list. Every one of them would be refused the same
				// way, and each refusal is another call against a quota that
				// is already gone -- which is how a reap turns one exhausted
				// window into two.
				c.holdRateLimited(inst.ID, err, now, "deleting an orphaned registration")
				break
			}
			if errors.Is(err, github.ErrRunnerBusy) {
				if row != nil {
					c.deferBusyRegistration(ctx, row)
				}
				continue
			}
			if err != nil {
				// Recorded on the row when there is one, the same as the
				// first attempt: without this the panel freezes on whatever
				// the original failure said while the reap loop keeps
				// quietly retrying (or not) behind it.
				if row != nil {
					reason := fmt.Sprintf("the GitHub runner registration could not be deleted: %v", err)
					if rerr := c.st.RecordRegistrationCleanupFailure(ctx, row.ID, reason); rerr != nil {
						c.log.Warn("could not record a failed registration delete", "runner", row.ID, "error", rerr)
					}
				}
				c.log.Warn("could not delete an orphaned runner registration",
					"installation", inst.ID, "runner_name", gr.Name, "error", err)
				continue
			}
			c.log.Info("deleted an orphaned GitHub runner registration",
				"installation", inst.ID, "target", inst.Target, "runner_name", gr.Name)
			// The reap is the retry for a delete that failed earlier, so it is
			// also what clears the row's complaint about it.
			if row, rerr := c.st.GetRunnerByName(ctx, gr.Name); rerr == nil {
				c.confirmCleanup(ctx, row.ID, false)
			}
		}
	}
}

// GitHub's busy flag is authoritative for deletion even when our row is terminal.
// Do not cancel a workflow or count waiting as another failed delete.
func (c *Controller) deferBusyRegistration(ctx context.Context, r *store.Runner) {
	reason := fmt.Sprintf("GitHub still reports %s as running a job; cleanup is deferred until GitHub reports it idle or absent", r.Name)
	if err := c.st.DeferRegistrationCleanup(ctx, r.ID, reason); err != nil {
		c.log.Warn("could not record deferred registration cleanup", "runner", r.ID, "error", err)
		return
	}
	c.publishRunnerByID(ctx, r.ID)
}

