func TestRegistrationAdmissionIsBoundedAndInstallationScoped(t *testing.T) {
	h := newHarness(t)
	if !h.c.admitCredentialMint("one") || h.c.admitCredentialMint("one") {
		t.Fatal("default must admit exactly one mint")
	}
	if !h.c.admitCredentialMint("two") {
		t.Fatal("unrelated installation was blocked")
	}
	h.c.releaseCredentialMint("one")
	h.c.holdGitHub("one", h.c.Now().Add(time.Minute))
	if h.c.admitCredentialMint("one") {
		t.Fatal("held installation admitted")
	}
	h.advance(2 * time.Minute)
	if !h.c.admitCredentialMint("one") {
		t.Fatal("expired hold did not recover")
	}
	h.c.releaseCredentialMint("one")
	h.c.releaseCredentialMint("two")
	if len(h.c.credentialMints) != 0 {
		t.Fatal("admission bookkeeping leaked")
	}
}

func TestRegistrationRateLimitCreatesSharedHold(t *testing.T) {
	for _, ephemeral := range []bool{true, false} {
		h := newHarness(t)
		inst, pool, _ := h.fleet()
		pool.Ephemeral = ephemeral
		reset := h.c.Now().Add(10 * time.Minute)
		h.gh.SetRateLimit(5000, 0, reset)
		pattern := "registration-token"
		if ephemeral {
			pattern = "generate-jitconfig"
		}
		h.gh.SetError(pattern, http.StatusForbidden, "rate limit exceeded")
		_, _, err := h.c.mintCredentials(h.ctx, inst, pool, "limited")
		if !errors.Is(err, github.ErrRateLimited) {
			t.Fatalf("mint error: %v", err)
		}
		if !h.c.githubHeld(inst.ID, h.c.Now()) {
			t.Fatal("registration did not hold installation")
		}
		before := h.c.heldInstallations(h.c.Now())[inst.ID]
		if before.Before(reset.Truncate(time.Second)) {
			t.Fatal("hold ignored GitHub reset")
		}
		h.gh.ClearErrors()
		_, _, err = h.c.mintCredentials(h.ctx, inst, pool, "still-held")
		if !errors.Is(err, github.ErrRateLimited) {
			t.Fatalf("held mint error: %v", err)
		}
		if after := h.c.heldInstallations(h.c.Now())[inst.ID]; !after.Equal(before) {
			t.Fatal("skipped call extended hold")
		}
	}
}

func TestRegistrationGroupLookupRateLimitPreventsMint(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	h.gh.SetRateLimit(5000, 0, h.c.Now().Add(time.Minute))
	h.gh.SetError("runner-groups", http.StatusForbidden, "rate limit exceeded")
	_, _, err := h.c.mintCredentials(h.ctx, inst, pool, "group-limited")
	if !errors.Is(err, github.ErrRateLimited) || !h.c.githubHeld(inst.ID, h.c.Now()) {
		t.Fatalf("group quota not held: %v", err)
	}
	if len(h.gh.Runners()) != 0 {
		t.Fatal("minted after group lookup rate limit")
	}
}

// A full admission budget defers demand without losing it or allocating rows.
func TestRegistrationDeferredDemandResumesOnLaterPass(t *testing.T) {
	h := newHarness(t)
	inst, pool, _ := h.fleet()
	pool.MinRunners = 2
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("could not occupy admission")
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	if len(h.runners()) != 0 {
		t.Fatal("deferred demand allocated provisioning rows")
	}
	h.c.releaseCredentialMint(inst.ID)
	for range pool.MinRunners {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
	}
	if got := len(h.runners()); got != pool.MinRunners {
		t.Fatalf("created %d runners, want %d", got, pool.MinRunners)
	}
	h.c.githubMu.Lock()
	defer h.c.githubMu.Unlock()
	if len(h.c.credentialMints) != 0 {
		t.Fatal("completed lifecycle retained admission")
	}
}

func TestRegistrationAdmissionPreservesPoolFairness(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	a, b := h.pool(inst, "a"), h.pool(inst, "b")
	h.host("host")
	for _, p := range []*store.Pool{a, b} {
		p.MinRunners = 2
		if err := h.st.UpdatePool(h.ctx, p); err != nil {
			t.Fatal(err)
		}
	}
	h.gh.SetDelay("", "generate-jitconfig", 500*time.Millisecond)
	for pass := 0; pass < 2; pass++ {
		if err := h.c.Reconcile(h.ctx); err != nil {
			t.Fatal(err)
		}
		h.c.lifecycleCalls.Wait()
	}
	counts := map[string]int{}
	for _, r := range h.runners() {
		counts[r.PoolID]++
	}
	if counts[a.ID] != 1 || counts[b.ID] != 1 {
		t.Fatalf("admission starved a pool: %v", counts)
	}
}

func TestCreateTaskCarriesProvisionDeadlineAndTokenExpiry(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	pool.Ephemeral = false
	pool.MinRunners = 1
	timeout := store.Duration(17 * time.Minute)
	pool.RunnerSettings.ProvisionTimeout = &timeout
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatal(err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.c.lifecycleCalls.Wait()
	tasks := h.tasksFor(host.ID)
	for _, task := range tasks {
		if task.Spec == nil || task.Spec.Credentials.RegistrationToken == "" {
			continue
		}
		runners := h.runners()
		if len(runners) != 1 {
			t.Fatalf("runners: %d", len(runners))
		}
		if !task.Spec.StartBefore.Truncate(time.Millisecond).Equal(runners[0].CreatedAt.Add(time.Duration(timeout))) {
			t.Fatalf("deadline %s, created %s, timeout %s", task.Spec.StartBefore, runners[0].CreatedAt, timeout)
		}
		if task.Spec.Credentials.ExpiresAt.IsZero() {
			t.Fatal("GitHub token expiry was discarded")
		}
		return
	}
	t.Fatal("no credential-bearing create task")
}

package controller

import (
	"strings"
	"testing"
	"time"
)

// scheduler.registration_concurrency is the one limit in this fleet that used
// to bind without saying so. The pool reports jobs waiting and nowhere to run
// them, an operator reads that, looks at the idle hosts and adds more -- and
// the new hosts do not help, because hosts were never what ran out.
func TestAHeldBackRegistrationSaysSoRatherThanJustNotHappening(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	// One in flight, which is the default limit, so the next is held.
	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("the first mint was refused, so nothing below is testing the limit")
	}
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a second mint was admitted at a limit of one")
	}

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	var found *Problem
	for i := range problems {
		if problems[i].Code == "scheduler.registration_throttled" {
			found = &problems[i]
		}
	}
	if found == nil {
		var codes []string
		for _, p := range problems {
			codes = append(codes, p.Code)
		}
		t.Fatalf("nothing said the registration was held back; the list was %s", strings.Join(codes, ", "))
	}

	// The entry has to name the setting, or an operator reading it still does
	// not know which number to change.
	if found.Setting != "scheduler.registration_concurrency" {
		t.Errorf("the entry names setting %q", found.Setting)
	}
	if found.TargetID != inst.ID {
		t.Errorf("the entry targets %q, not the installation it is about", found.TargetID)
	}
	// And it has to say the thing that stops somebody buying hosts.
	if !strings.Contains(found.Detail, "hosts are not what ran out") {
		t.Errorf("the entry does not say adding hosts will not help: %q", found.Detail)
	}
	if found.Since == nil {
		t.Error("the entry does not say since when, so nobody can tell a blip from a standing condition")
	}
}

// A throttle that is no longer binding must stop being reported, or it becomes
// one more line an operator learns to scroll past.
func TestTheHeldBackRegistrationClearsWhenItStops(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	if !h.c.admitCredentialMint(inst.ID) {
		t.Fatal("the first mint was refused")
	}
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a second mint was admitted at a limit of one")
	}
	h.c.releaseCredentialMint(inst.ID)

	// A pass that defers nothing forgets it.
	h.c.resetDeferredMints()
	h.c.resetDeferredMints()

	problems, err := h.c.Problems(h.ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range problems {
		if p.Code == "scheduler.registration_throttled" {
			t.Errorf("the fleet is no longer holding registrations back and still says it is: %q", p.Title)
		}
	}
}

// GitHub's own rate-limit hold is a different thing with a different fix, and
// counting it here would send an operator to raise a limit that is not the one
// refusing them.
func TestAGitHubRateLimitHoldIsNotCountedAsOurThrottle(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()

	h.c.holdGitHub(inst.ID, h.c.Now().Add(time.Hour))
	if h.c.admitCredentialMint(inst.ID) {
		t.Fatal("a mint was admitted while the installation was held by GitHub")
	}

	held, _ := h.c.deferredMintsNow()
	if n := held[inst.ID]; n != 0 {
		t.Errorf("a GitHub rate-limit hold was counted as %d of our own deferrals", n)
	}
}

package controller

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

// The restart boundary table.
//
// A controller restart drops the task queue, by design: every task is derived
// from state the database already holds, so persisting the queue would add a
// second source of truth that could disagree with the runners table. The price
// is that a result arriving after the restart answers a task the new
// controller has never heard of, and it must still be applied -- the agent did
// the work, and the row is the only place that fact can land.
//
// Each row here puts a runner at one boundary with a task in flight, restarts
// the controller over the same store, replays the agent's result, and asserts
// the fleet converges: the state the result implies, and never two live rows
// for one runner name. Duplicate live rows are the failure this guards
// against, because a name is a GitHub registration, and two of them means one
// runner executing jobs that the fleet is accounting for twice.
func TestALateResultAfterARestartLeavesOneLiveRowPerRunner(t *testing.T) {
	cases := []struct {
		name string
		// state the runner is in when the controller goes down.
		state store.RunnerState
		// kind of the task the agent is still working on.
		kind agent.TaskKind
		// inflight polls the task, so it is in flight rather than queued.
		inflight bool
		// result the agent reports once the controller is back.
		ok        bool
		reports   store.RunnerState
		wantState store.RunnerState
	}{
		{
			name:  "create enqueued but never collected",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner,
			ok: true, reports: store.RunnerRegistering, wantState: store.RunnerRegistering,
		},
		{
			name:  "create acknowledged and in flight",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner, inflight: true,
			ok: true, reports: store.RunnerRegistering, wantState: store.RunnerRegistering,
		},
		{
			name:  "create failed on the host",
			state: store.RunnerProvisioning, kind: agent.TaskCreateRunner, inflight: true,
			ok: false, wantState: store.RunnerFailed,
		},
		{
			name:  "registering when the controller went down",
			state: store.RunnerRegistering, kind: agent.TaskCreateRunner, inflight: true,
			ok: true, reports: store.RunnerIdle, wantState: store.RunnerIdle,
		},
		{
			name:  "busy with a stop in flight",
			state: store.RunnerBusy, kind: agent.TaskStopRunner, inflight: true,
			ok: true, reports: store.RunnerDraining, wantState: store.RunnerDraining,
		},
		{
			name:  "draining with a stop in flight",
			state: store.RunnerDraining, kind: agent.TaskStopRunner, inflight: true,
			ok: true, reports: store.RunnerRemoved, wantState: store.RunnerRemoved,
		},
		{
			name:  "remove in flight",
			state: store.RunnerDraining, kind: agent.TaskRemoveRunner, inflight: true,
			ok: true, reports: store.RunnerRemoved, wantState: store.RunnerRemoved,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			_, pool, host := h.fleet()
			r := h.runnerRow(pool, host, tc.state)

			task := agent.Task{ID: "task_boundary", Kind: tc.kind, RunnerID: r.ID, Backend: pool.Backend}
			h.c.enqueueLifecycle(h.ctx, host.ID, task)
			if tc.inflight {
				if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
					t.Fatalf("PollTasks: %v", err)
				}
			}

			// The restart. The rows are all that crosses it.
			c := h.restart()

			// The agent finishes the work it was already doing and reports a
			// result for a task this controller has never issued. Kind is
			// carried on the result precisely so it can still be understood.
			err := c.ReportResult(h.ctx, host.ID, agent.TaskResult{
				TaskID: task.ID, Kind: tc.kind, RunnerID: r.ID,
				OK: tc.ok, State: tc.reports, Error: errorFor(tc.ok),
			})
			if err != nil {
				t.Fatalf("ReportResult after the restart: %v", err)
			}

			got := h.runnerByID(t, r.ID)
			if got.State != tc.wantState {
				t.Errorf("state = %q, want %q: the agent's work was lost across the restart", got.State, tc.wantState)
			}
			assertOneLiveRowPerName(t, h)
		})
	}
}

func errorFor(ok bool) string {
	if ok {
		return ""
	}
	return "the workload could not be created"
}

// assertOneLiveRowPerName is the invariant the table exists for. A runner name
// is a GitHub registration, so two live rows sharing one would have the fleet
// account twice for a single runner -- and place work against capacity that
// does not exist.
func assertOneLiveRowPerName(t *testing.T, h *harness) {
	t.Helper()
	live := map[string]string{}
	for _, r := range h.runners() {
		if !r.State.Live() {
			continue
		}
		if other, dup := live[r.Name]; dup {
			t.Fatalf("runners %s and %s are both live as %q", other, r.ID, r.Name)
		}
		live[r.Name] = r.ID
	}
}

// The other half of the boundary: a result that arrives after the fleet has
// already given up on the runner. The five-minute host-lost reclaim is shorter
// than the twenty-minute create lease, so a create in flight on a host that
// goes quiet is failed before its lease has even expired -- and the agent,
// which never heard any of that, reports success when it comes back.
//
// The terminal row stands. It is what the operator and the job's timeline were
// told, and a success arriving afterwards does not make it untrue that this
// fleet stopped counting on the runner.
func TestALateSuccessDoesNotResurrectARunnerTheFleetGaveUpOn(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)

	task := agent.Task{ID: "task_late", Kind: agent.TaskCreateRunner, RunnerID: r.ID, Backend: pool.Backend}
	h.c.enqueueLifecycle(h.ctx, host.ID, task)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	if err := h.c.failRunnerID(h.ctx, r.ID, "host went quiet for longer than hostLostAfter", store.FaultHostLost); err != nil {
		t.Fatalf("failRunnerID: %v", err)
	}

	c := h.restart()
	if err := c.ReportResult(h.ctx, host.ID, agent.TaskResult{
		TaskID: task.ID, Kind: agent.TaskCreateRunner, RunnerID: r.ID,
		OK: true, State: store.RunnerRegistering,
	}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}

	got := h.runnerByID(t, r.ID)
	if got.State != store.RunnerFailed {
		t.Fatalf("state = %q, want it to stay failed; the fleet had already told an operator this runner was gone", got.State)
	}
	assertOneLiveRowPerName(t, h)
}

package controller

import (
	"net/http"
	"slices"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// A pool names a runner group to keep its runners away from work that is not
// meant for them. When that group cannot be resolved the runners register in
// GitHub's Default group, which every repository the installation covers can
// reach -- so the pool is running its jobs somewhere wider than its operator
// asked for. That was a log line and nothing else.

// runnerGroupWarning returns the pool.runner_group_unresolved entry, or nil.
func runnerGroupWarning(h *harness, poolID string) *Problem {
	h.t.Helper()
	ps, err := h.c.Problems(h.ctx)
	if err != nil {
		h.t.Fatalf("Problems: %v", err)
	}
	for i, p := range ps {
		if p.Code == "pool.runner_group_unresolved" && p.TargetID == poolID {
			return &ps[i]
		}
	}
	return nil
}

// groupPool is a fleet whose pool asks for a named runner group and has a job
// waiting, so that a reconcile pass actually mints a runner for it.
func groupPool(h *harness, group string) *store.Pool {
	h.t.Helper()
	inst, pool, _ := h.fleet()
	pool.RunnerGroup = group
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		h.t.Fatalf("UpdatePool: %v", err)
	}
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 9001, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
		Labels: store.StringSlice{"self-hosted", "linux", "x64", "demo"},
		State:  store.JobQueued, InstallationID: inst.ID,
	}); err != nil {
		h.t.Fatalf("UpsertJob: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		h.t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()
	return pool
}

func TestAPoolNamingAGroupTheTargetDoesNotHaveSaysSoInsteadOfUsingDefaultQuietly(t *testing.T) {
	h := newHarness(t)
	h.gh.AddRunnerGroup("builders")
	pool := groupPool(h, "gpu")

	if got := len(h.runners()); got != 1 {
		t.Fatalf("created %d runners, want 1: the pool still gets its runner", got)
	}
	w := runnerGroupWarning(h, pool.ID)
	if w == nil {
		t.Fatal("a pool whose runner group does not exist raised no warning")
	}
	if !strings.Contains(w.Detail, "gpu") || !strings.Contains(w.Detail, "Default") {
		t.Errorf("detail = %q, want it to name the group asked for and the one used", w.Detail)
	}
	if w.Title == "" || w.Fix == "" {
		t.Errorf("warning = %+v, want a title and a fix as well as a detail", w)
	}
}

func TestAPoolWhoseRunnerGroupsCannotBeListedSaysThatRatherThanNaminTheGroup(t *testing.T) {
	h := newHarness(t)
	h.gh.SetError("/actions/runner-groups", http.StatusForbidden, "Resource not accessible by integration")
	pool := groupPool(h, "gpu")

	w := runnerGroupWarning(h, pool.ID)
	if w == nil {
		t.Fatal("a pool whose groups could not be listed raised no warning")
	}
	// The two cases need different fixes, so they must not read the same: this
	// one is a permission, not a missing group.
	if !strings.Contains(w.Detail, "would not say") {
		t.Errorf("detail = %q, want it to say GitHub would not answer rather than that the group is missing", w.Detail)
	}
}

// Runner groups belong to an organisation. A pool on a repository target that
// names one is misconfigured in the opposite direction: nothing to create, the
// group has to come off the pool.
func TestAPoolOnARepositoryTargetIsToldRunnerGroupsAreAnOrganisationThing(t *testing.T) {
	h := newHarness(t)
	inst := h.installationOn("acme/widgets", store.TargetRepo)
	h.host("vm-1")
	pool := h.pool(inst, "linux-x64")
	pool.RunnerGroup = "gpu"
	if err := h.st.UpdatePool(h.ctx, pool); err != nil {
		t.Fatalf("UpdatePool: %v", err)
	}
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 9002, Repo: "acme/widgets", Workflow: "CI", JobName: "build",
		Labels: store.StringSlice{"self-hosted", "linux", "x64", "demo"},
		State:  store.JobQueued, InstallationID: inst.ID,
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	// The warning is noted while the runner's credential is minted, which
	// runs detached from the pass; reading problems before it finishes read
	// them before the warning existed, and failed whenever it lost the race.
	h.c.lifecycleCalls.Wait()

	w := runnerGroupWarning(h, pool.ID)
	if w == nil {
		t.Fatal("a repository-target pool naming a runner group raised no warning")
	}
	if !strings.Contains(w.Detail, "organisation") {
		t.Errorf("detail = %q, want it to say runner groups belong to an organisation", w.Detail)
	}
}

// The warning has to go away by itself, or an operator who fixes it is left
// looking at a drawer that still says they have not.
func TestTheRunnerGroupWarningClearsOnceTheGroupExists(t *testing.T) {
	h := newHarness(t)
	pool := groupPool(h, "gpu")
	if runnerGroupWarning(h, pool.ID) == nil {
		t.Fatal("the warning was never raised, so clearing it proves nothing")
	}

	// The operator creates the group, and the fleet makes its next runner.
	h.gh.AddRunnerGroup("gpu")
	if _, err := h.st.UpsertJob(h.ctx, &store.Job{
		GitHubJobID: 9003, Repo: "acme/widgets", Workflow: "CI", JobName: "build2",
		Labels: store.StringSlice{"self-hosted", "linux", "x64", "demo"},
		State:  store.JobQueued, InstallationID: pool.InstallationID,
	}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	// Registration -- where the group is resolved and the warning cleared --
	// runs on its own goroutine after the pass. Asking before it finishes
	// read whichever it happened to be, and failed about one run in three.
	h.c.lifecycleCalls.Wait()
	if w := runnerGroupWarning(h, pool.ID); w != nil {
		t.Fatalf("the warning survived the group being created: %+v", w)
	}
}

// A pool that names no group, or names Default, is not misconfigured and must
// not be warned about -- the drawer is only read while it stays short.
func TestAPoolWithNoRunnerGroupIsNotWarnedAbout(t *testing.T) {
	h := newHarness(t)
	for _, group := range []string{"", "Default", "default"} {
		t.Run("group "+group, func(t *testing.T) {
			h := newHarness(t)
			pool := groupPool(h, group)
			if w := runnerGroupWarning(h, pool.ID); w != nil {
