// seedSamples writes an hour of per-minute fleet history.
//
// Without it the Overview's sparklines have a single point until the instance
// has been up for a while, so the one thing that makes that page worth leaving
// open -- the shape of the last hour -- is exactly what a demo or a screenshot
// cannot show. The shape is deliberate rather than noise: a quiet start, a
// burst of queued work that the fleet scales into, and a wind-down, which is
// what a real morning looks like.
func (c *Controller) seedSamples(ctx context.Context, now time.Time, rng *rand.Rand) error {
	const minutes = 60
	start := now.Add(-minutes * time.Minute).Truncate(time.Minute)

	for i := 0; i <= minutes; i++ {
		at := start.Add(time.Duration(i) * time.Minute)

		// Keep the burst near the end of the fixture hour. The browser suite shares
		// a live controller for long enough that an early burst aged out of its
		// one-hour view before the mobile project reached it.
		var queued, running, total int
		switch {
		case i < 40:
			queued = jitter(rng, 0, 1)
			running = jitter(rng, 1, 2)
			total = 2 + running
		case i < 52:
			// Nothing idle through the burst, and that is the point: the queue
			// is deep precisely because every runner is taken. A demo whose
			// busiest ten minutes still showed four free runners would say the
			// scheduler had simply not bothered.
			queued = jitter(rng, 4, 9)
			running = jitter(rng, 2, 4)
			total = running
		case i < 58:
			// The scheduler has caught up: the queue drains as runners appear.
			queued = jitter(rng, 1, 4)
			running = jitter(rng, 4, 7)
			total = 2 + running + queued/2
		default:
			queued = jitter(rng, 0, 2)
			running = jitter(rng, 2, 4)
			total = 3 + running
		}
		busy := running
		if busy > total {
			busy = total
		}
		idle := total - busy
		if idle < 0 {
			idle = 0
		}

		if err := c.st.RecordSample(ctx, store.FleetSample{
			At:          at,
			QueuedJobs:  queued,
			RunningJobs: running,
			// Every job the demo seeds belongs to one of its own pools, so the
			// fleet's own figures are the same figures. Leaving them at zero
			// would give the Overview a flat sparkline in its default view and
			// make the demo look broken.
			FleetQueuedJobs:  queued,
			FleetRunningJobs: running,
			IdleRunners:      idle,
			BusyRunners:      busy,
			TotalRunners:     total,
		}); err != nil {
			return fmt.Errorf("seeding the fleet sample for %s: %w", at.Format(time.RFC3339), err)
		}
	}
	return nil
}

// jitter returns a value in [lo, hi]. The fixtures use a seeded source, so the
// shape is the same on every run and a screenshot taken today matches one taken
// last week.
// demoHostUsage is what a demo host measured at `at`: a working day drawn
// as a curve rather than a random walk, so the capacity map shows the shape
// an operator recognises -- quiet overnight, climbing from nine, a lunchtime
// dip, an afternoon peak -- and each host sits on its own band of it. The
// third host is the cordoned one and idles. Deterministic, so two controllers
// seeded in the same minute draw the same chart.
func demoHostUsage(cpus int, memoryMB int64, host int, at, now time.Time) store.HostUsage {
	local := at.In(time.Local)
	hour := float64(local.Hour()) + float64(local.Minute())/60
	// The day's shape, 0..1.
	var day float64
	switch {
	case hour < 7:
		day = 0.08
	case hour < 9:
		day = 0.08 + (hour-7)/2*0.5
	case hour < 12.5:
		day = 0.58 + (hour-9)/3.5*0.3
	case hour < 13.5:
		day = 0.55
	case hour < 17:
		day = 0.6 + (hour-13.5)/3.5*0.35
	case hour < 20:
		day = 0.95 - (hour-17)/3*0.7
	default:
		day = 0.25 - (hour-20)/4*0.17
	}
	// Ten-minute texture on top, so the line reads as a measurement and not
	// a drawing; the phase differs per host so their peaks do not coincide.
	minute := float64(at.Unix()/60) + float64(host*7)
	texture := 0.06*math.Sin(minute/10*2*math.Pi/6) + 0.04*math.Sin(minute/3.3)
	band := []float64{0.9, 0.7, 0.2}[host%3]
	cpu := math.Max(1, math.Min(92, 100*(day*band+texture+0.05)))
	// The most recent point is the one the card shows, and the throttle
	// ladder reads it too: the first builder is under real pressure at the
	// afternoon peak and nowhere else.
	load := cpu / 100 * float64(cpus) * 1.15
	memUsed := 0.25 + 0.55*day*band + texture/2
	available := int64(float64(memoryMB) * (1 - memUsed))
	if available < 256 {
		available = 256
	}
	return store.HostUsage{
		CPUPercent:        &cpu,
		LoadAverage1:      &load,
		MemoryAvailableMB: &available,
		SampledAt:         now,
	}
}

// seedHostSamples writes a day of per-minute history for every demo host, so
// the Hosts page's capacity map has a past to draw on a controller that was
// started a moment ago. The runner counts follow the same curve as the
// measurements: a host is busy because its slots are.
func (c *Controller) seedHostSamples(ctx context.Context, now time.Time, hosts []*store.Host, runners []*store.Runner) error {
	const minutes = 24 * 60
	// The closing hour carries the runners the fixture actually has, so the
	// chart's history meets its live edge instead of stepping to it: the
	// newest point is drawn from the fleet, and a line that jumps there
	// reads as a fault in the chart rather than a fact about the host.
	live := map[string]int{}
	for _, r := range runners {
		if !r.State.Terminal() {
			live[r.HostID]++
		}
	}
	start := now.Add(-minutes * time.Minute).Truncate(time.Minute)
	samples := make([]store.HostSample, 0, (minutes+1)*len(hosts))
	for i, h := range hosts {
		alloc := h.Allocatable()
		for m := 0; m <= minutes; m++ {
			at := start.Add(time.Duration(m) * time.Minute)
			usage := demoHostUsage(h.CPUs, h.MemoryMB, i, at, at)
			busy := int(math.Round(*usage.CPUPercent / 100 * float64(h.Capacity)))
			if h.Cordoned {
				busy = 0
			}
			// Over the last hour the curve's count gives way to the fixture's
			// real one, so the line arrives at the live edge rather than
			// stepping to it.
			if left := minutes - m; left <= 60 {
				t := math.Min(1, float64(60-left)/45)
				busy = int(math.Round(float64(busy) + (float64(live[h.ID])-float64(busy))*t))
			}
			reservedCPUs := float64(busy) * 2
			reservedMem := int64(busy) * 4096
			samples = append(samples, store.HostSample{
				HostID:              h.ID,
				At:                  at,
				Capacity:            h.Capacity,
				ActiveRunners:       busy,
				CPUPercent:          usage.CPUPercent,
				LoadAverage1:        usage.LoadAverage1,
				CPUs:                int64(h.CPUs),
				MemoryMB:            h.MemoryMB,
				MemoryAvailableMB:   usage.MemoryAvailableMB,
				AllocatableCPUs:     alloc.CPUs,
				AllocatableMemoryMB: alloc.MemoryMB,
				ReservedCPUs:        &reservedCPUs,
				ReservedMemoryMB:    &reservedMem,
				DiskTotalMB:         h.DiskTotalMB,
				// Disk fills slowly through the day: the caches a runner
				// leaves behind, which is what the second builder is short of.
				DiskFreeMB: h.DiskFreeMB + int64(minutes-m)*8,
			})
		}
	}
	if err := c.st.RecordHostSamples(ctx, samples); err != nil {
		return fmt.Errorf("seeding host samples: %w", err)
	}
	return nil
}

func jitter(rng *rand.Rand, lo, hi int) int {
	if hi <= lo {
		return lo
	}
	return lo + rng.IntN(hi-lo+1)
}

package controller

import (
	"context"
	"errors"
	"testing"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

func TestIsDemoID(t *testing.T) {
	for _, tc := range []struct {
		id   string
		want bool
	}{
		{"ins_demoacme", true},
		{"pool_demolinux", true},
		{"host_demo1", true},
		{"run_demo09", true},
		{"pool_k3f9qz2mx7ab", false},
		{"ins_democracy", true}, // readable, and not the shape NewID makes
		{"job_demostuckheldjob", true},
		// A real identifier whose random part happens to begin "demo". One row
		// in a million does, and it used to be skipped by the prober, the
		// poller and the reap, and never reclaimed if it was a host.
		{"ins_demoq2mx7abk3", false},
		{"host_demozzzzzzzzz", false},
		{"nounderscore", false},
		{"", false},
	} {
		if got := IsDemoID(tc.id); got != tc.want {
			t.Errorf("IsDemoID(%q) = %v, want %v", tc.id, got, tc.want)
		}
	}
}

// Every identifier the seed writes has to be one IsDemoID recognises, and the
// rule it recognises them by is the shape, so no fixture may be exactly the
// shape NewID produces. This is the test that stops a future fixture named
// with thirteen readable letters from becoming a real row overnight.
func TestEveryDemoFixtureIsRecognisedAsOne(t *testing.T) {
	h := newHarness(t)
	t.Setenv(StuckSeedEnvVar, "1")
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("seedStuck: %v", err)
	}
	var ids []string
	insts, _ := h.st.ListInstallations(h.ctx)
	for _, i := range insts {
		ids = append(ids, i.ID)
	}
	pools, _ := h.st.ListPools(h.ctx)
	for _, p := range pools {
		ids = append(ids, p.ID)
	}
	hosts, _ := h.st.ListHosts(h.ctx)
	for _, hh := range hosts {
		ids = append(ids, hh.ID)
	}
	for _, r := range h.runners() {
		ids = append(ids, r.ID)
	}
	jobs, _, _ := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 500})
	for _, j := range jobs {
		ids = append(ids, j.ID)
	}
	if len(ids) < 60 {
		t.Fatalf("collected only %d fixture identifiers; the seed is not what this test thinks it is", len(ids))
	}
	for _, id := range ids {
		if !IsDemoID(id) {
			t.Errorf("fixture %q is not recognised as demo data", id)
		}
		if store.LooksGenerated(id) {
			t.Errorf("fixture %q has the shape of a real identifier; a fixture must never be mistakable for one", id)
		}
	}
}

// The demo fixtures have no GitHub behind them. If the credential prober were
// allowed to check them, every demo instance and every UI test run would open
// on a problems drawer led by "this installation is not usable" -- a failure
// that says nothing about the operator's fleet and hides the ones that do.
func TestDemoInstallationIsNotProbed(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()

	if err := h.c.SeedDemo(ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	h.c.probeInstallations(ctx)

	inst, err := h.st.GetInstallation(ctx, demoInstallationID)
	if err != nil {
		t.Fatalf("GetInstallation: %v", err)
	}
	if inst.LastError != "" {
		t.Errorf("the demo installation was probed and recorded %q; it must be skipped", inst.LastError)
	}

	problems, err := h.c.Problems(ctx)
	if err != nil {
		t.Fatalf("Problems: %v", err)
	}
	for _, p := range problems {
		if p.Code == "installation.unhealthy" {
			t.Errorf("the demo fleet reports %q: %s", p.Code, p.Title)
		}
	}
}

// The demo installation must answer every read the UI makes without reaching
// GitHub. Before this, the Installations page 500'd on the rate limit and the
// poller logged a credential failure every thirty seconds, which makes a demo
// instance read as broken software rather than as a working fleet.
func TestDemoInstallationAnswersReadsWithoutGitHub(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	if err := h.c.SeedDemo(ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	client, err := h.c.ClientFor(ctx, demoInstallationID)
	if err != nil {
		t.Fatalf("ClientFor: %v", err)
	}

	if _, err := client.Probe(ctx); err != nil {
		t.Errorf("Probe: %v", err)
	}
	rl, err := client.RateLimit(ctx)
	if err != nil {
		t.Fatalf("RateLimit: %v", err)
	}
	if rl.Remaining <= 0 || rl.Remaining > rl.Limit {
		t.Errorf("rate limit = %d/%d, want a plausible pair", rl.Remaining, rl.Limit)
	}
	if _, err := client.ListRunners(ctx); err != nil {
		t.Errorf("ListRunners: %v", err)
	}
	if _, err := client.ListRunnerGroups(ctx); err != nil {
		t.Errorf("ListRunnerGroups: %v", err)
	}
	if _, err := client.ListQueuedJobs(ctx); err != nil {
		t.Errorf("ListQueuedJobs: %v", err)
	}
	if err := client.DeleteRunner(ctx, 42); err != nil {
		t.Errorf("DeleteRunner on a registration that never existed should succeed: %v", err)
	}

	// Writes must refuse, and say why. Silently pretending to mint a runner
	// credential would leave runners stuck in provisioning with no explanation.
	if _, err := client.CreateJITConfig(ctx, github.JITRequest{Name: "x"}); err == nil {
		t.Error("CreateJITConfig succeeded on a demo fixture; it must refuse")
	} else if !errors.Is(err, ErrDemoFixture) {
		t.Errorf("CreateJITConfig error = %v, want it to wrap ErrDemoFixture", err)
	}
}

package controller

import (
	"context"
	"fmt"
	"os"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// StuckSeedEnvVar names the environment variable that adds the diagnostics
// fixture on top of the demo fleet.
//
// It is separate from ZOOMIES_SEED_DEMO on purpose, and it is the opposite of
// what a demo wants. The demo deliberately keeps its two starting runners young
// (see freshenDemoRunners) so an instance left open never reports a fault in a
// fleet that has no agent to have one. Every diagnostic this project has for a
// fleet in trouble -- the problems drawer, the stuck-runner shapes, the blocked
// pool, the held job -- is therefore unreachable from the demo, which is why
// they went untested until this existed.
//
// Nothing here is for an operator. It exists so a test can open the pages an
// operator opens on their worst day.
const StuckSeedEnvVar = "ZOOMIES_SEED_STUCK"

// The diagnostics fixture's own identifiers. They begin "demo" after the
// prefix, so IsDemoID covers them and every guard that keeps a fixture out of a
// real fleet applies to them unchanged.
const (
	stuckPoolID    = "pool_demostuckblocked"
	stuckPoolName  = "zoomies-demo-stuck-blocked"
	stuckHeldJobID = "job_demostuckheldjob"
	// StuckThrottledHostName is the fixture's throttled host, named here so
	// a browser test can find its card.
	StuckThrottledHostName = "demo-throttled-1"
	stuckThrottledHostID   = demoHostPrefix + "stuckthrottled"
)

// stuckSeedRequested reports whether the diagnostics fixture was asked for.
func stuckSeedRequested() bool {
	v, ok := os.LookupEnv(StuckSeedEnvVar)
	if !ok {
		return false
	}
	b, err := strconv.ParseBool(v)
	return err == nil && b
}

// SeedStuck ages the demo's starting runners into the two stuck shapes and adds
// the two fixtures the demo has no room for: a pool nothing can place, and a
// job GitHub is holding.
//
// It runs after SeedDemo and depends on it, because a fleet in trouble is only
// legible against one that is working: the point of the problems drawer is that
// it names the three things wrong among the twenty that are right.
func (c *Controller) SeedStuck(ctx context.Context) error {
	now := c.Now()

	// The demo's two starting runners are the two shapes exactly: one with no
	// container yet, one whose container came up and never registered. They are
	// already the right shape and only ever the wrong age, so this back-dates
	// them rather than writing more rows -- a fixture that duplicated them
	// would drift from the demo's the first time either was edited.
	starting, _, err := c.st.ListRunners(ctx, store.RunnerFilter{
		States: []store.RunnerState{store.RunnerProvisioning, store.RunnerRegistering},
	}, store.Page{Limit: 100})
	if err != nil {
		return fmt.Errorf("listing the runners to age: %w", err)
	}
	// Three quarters of the provision timeout: past half, which is when
	// runners.not_progressing starts saying so, and short of the whole, which
	// is when the reconcile loop gives up and fails the runner. Ageing them to
	// the full timeout produced a fixture with one stuck runner rather than
	// two, because the next pass failed the one with no container -- which is
	// the correct behaviour and the wrong fixture.
	stuckSince := now.Add(-c.cfg().Scheduler.ProvisionTimeout * 3 / 4)
	aged := 0
	for _, r := range starting {
		if !IsDemoID(r.ID) {
			continue
		}
		if r.ContainerStartedAt != nil {
			err = c.st.SetRunnerStartup(ctx, r.ID, r.ImagePullDuration, &stuckSince)
		} else {
			err = c.st.SetRunnerCreatedAt(ctx, r.ID, stuckSince)
		}
		if err != nil {
			return fmt.Errorf("ageing runner %s into a stuck one: %w", r.ID, err)
		}
		aged++
	}
	if aged == 0 {
		return fmt.Errorf("no demo runner was starting up, so there is nothing to make stuck; is %s set too?", SeedEnvVar)
	}

	if err := c.seedBlockedPool(ctx); err != nil {
		return err
	}
	if err := c.seedHeldJob(ctx, now); err != nil {
		return err
	}
	if err := c.seedThrottledHost(ctx, now); err != nil {
		return err
	}
	c.log.Info("seeded the diagnostics fixture", "env", StuckSeedEnvVar, "stuck_runners", aged)
	return nil
}

// seedBlockedPool writes a pool no host can take, so the scheduler's own
// sentence for that -- and the pool warning the drawer renders from it -- has
// something to say.
//
// The selector is what makes it unplaceable, rather than a disabled pool or a
// ceiling of zero: those are choices an operator made, and the page says so
// differently. A selector nothing answers is the misconfiguration, and it is
// the one the reason string exists to explain.
func (c *Controller) seedBlockedPool(ctx context.Context) error {
	if _, err := c.st.GetPool(ctx, stuckPoolID); err == nil {
		return nil
	}
	p := &store.Pool{
		ID:             stuckPoolID,
		Name:           stuckPoolName,
		InstallationID: demoInstallationID,
		Labels:         store.StringSlice(store.BrandLabels([]string{"linux", "x64", stuckPoolName})),
		Backend:        store.BackendDocker,
		MinRunners:     1,
		MaxRunners:     2,
		IdleTimeout:    store.Duration(5 * time.Minute),
		Ephemeral:      true,
		DockerMode:     store.DockerNone,
		// No host answers this, and none is meant to.
		HostSelector: store.StringMap{"zone": "nowhere"},
		Enabled:      true,
	}
	if err := c.st.CreatePool(ctx, p); err != nil {
		return fmt.Errorf("seeding the blocked pool: %w", err)
	}
	return nil
}

// seedHeldJob writes a job GitHub is holding for a deployment review.
//
// It is the one job state the demo has never carried, and the one that reads
// as a fleet fault when it is not: every panel that explains a wait keys on
// `queued`, so a held job used to sit in the drawer with nothing said about it.
func (c *Controller) seedHeldJob(ctx context.Context, now time.Time) error {
	held := &store.Job{
		ID:             stuckHeldJobID,
		GitHubJobID:    80099,
		GitHubRunID:    40099,
		RunNumber:      399,
		Repo:           demoRepos[0],
		Workflow:       "Deploy",
		JobName:        "deploy-production",
		Labels:         store.StringSlice(store.BrandLabels([]string{"linux", "x64", "zoomies-demo-linux-x64"})),
		InstallationID: demoInstallationID,
		State:          store.JobWaiting,
		QueuedAt:       now.Add(-18 * time.Minute),
		HTMLURL:        fmt.Sprintf("https://github.com/%s/actions/runs/%d", demoRepos[0], 40099),
		HeadBranch:     "main",
		HeadSHA:        fmt.Sprintf("%040x", 0xDEC1DE),
		RunAttempt:     1,
	}
	saved, change, err := c.st.ApplyJob(ctx, held)
	if err != nil {
		return fmt.Errorf("seeding the held job: %w", err)
	}
	return c.seedJobTimeline(ctx, saved, change)
}

// seedThrottledHost writes a host the controller has stepped down after
// sustained pressure, with a live runner on it that was given one slot's
// share of the machine, so the host card's throttle notice, the runner
// detail's allocation and the problems drawer's host.throttled entry all
// have something to render.
//
// It is throttled for its load average rather than for a CPU hold, because
// that is the signal the ladder was added for: a machine whose CPU pinned at
// 100% and stopped saying anything, while the runnable queue kept growing.
// The measurements are the shape of that machine -- CPU at 60% because the
// throttle has already halved every runner's quota, load still at thirty on
// eight cores because the work is still there -- and the demo heartbeat keeps
// the sample fresh so the card can keep explaining itself. Housekeeping leaves
// the demo's hosts alone, so the rung does not climb or lift on its own.
func (c *Controller) seedThrottledHost(ctx context.Context, now time.Time) error {
	if _, err := c.st.GetHost(ctx, stuckThrottledHostID); err == nil {
		return nil
	}
	cpu, load, memory := 60.0, 30.0, int64(4096)
	since := now.Add(-7 * time.Minute)
	changed := now.Add(-3 * time.Minute)
	h := &store.Host{
		ID:       stuckThrottledHostID,
		Name:     StuckThrottledHostName,
		Address:  "10.0.0.14",
		Capacity: 4,
		Backends: store.StringSlice{"docker"},
		BackendInfo: store.HostBackends{
			{Kind: store.BackendDocker, Available: true, Version: "27.1.1",
				Rootless: true, Endpoint: "unix:///run/user/1000/docker.sock", SupportsDinD: true,
				Limits: store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}},
		},
		Labels:      store.StringMap{"arch": "amd64", "zone": "demo"},
		OS:          "linux",
		Distro:      "ubuntu",
		OSVersion:   "24.04",
		Arch:        "amd64",
		CPUs:        8,
		MemoryMB:    16384,
		DiskTotalMB: 524_288,
		DiskFreeMB:  301_989,
		Usage: store.HostUsage{
			CPUPercent:        &cpu,
			LoadAverage1:      &load,
			MemoryAvailableMB: &memory,
			SampledAt:         now,
		},
		Throttle: store.HostThrottle{
			Level:     2,
			Since:     &since,
			ChangedAt: &changed,
			Reason:    "the 1-minute load average is 30.0, at least twice the host's 8 CPUs",
		},
		Version:         version.Version,
		ProtocolVersion: agent.ProtocolVersion,
		LastHeartbeat:   now,
	}
	if err := c.st.CreateHost(ctx, h); err != nil {
		return fmt.Errorf("seeding the throttled host: %w", err)
	}
	// One of the demo's busy runners moves here and is given the share a
	// four-slot host of this size hands out: (8 - 0.5) / 4 CPUs, floored to
	// the hundredth, and (16384 - 512) / 4 MB. Moved rather than written
	// afresh so the fixture's runner count stays what the demo's tests pin.
	runners, _, err := c.st.ListRunners(ctx, store.RunnerFilter{
		States: []store.RunnerState{store.RunnerBusy},
	}, store.Page{Limit: 100})
	if err != nil {
		return fmt.Errorf("listing the runners to place on the throttled host: %w", err)
	}
	slices.SortFunc(runners, func(a, b *store.Runner) int { return strings.Compare(a.ID, b.ID) })
	for _, r := range runners {
		if !IsDemoID(r.ID) {
			continue
		}
		r.HostID = h.ID
		r.AllocatedCPUs = 1.87
		r.AllocatedMemoryMB = 3968
		r.AllocationSource = store.AllocationFromHost
		if err := c.st.UpdateRunner(ctx, r); err != nil {
			return fmt.Errorf("placing runner %s on the throttled host: %w", r.ID, err)
		}
		return nil
	}
	return fmt.Errorf("no demo runner was busy, so none can be placed on the throttled host; is %s set too?", SeedEnvVar)
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The diagnostics fixture carries one throttled host with a runner on it that
// was given the host's default share, so the host card's throttle notice, the
// runner detail's allocation and the drawer's host.throttled entry can all be
// looked at -- and it has to stay that way for as long as the instance is
// open, or a screenshot taken a minute after start shows a different fleet.
func TestSeedStuckAddsAThrottledHostThatStaysThrottled(t *testing.T) {
	h := newHarness(t)
	t.Setenv(StuckSeedEnvVar, "1")
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("SeedStuck: %v", err)
	}
	host, err := h.st.GetHostByName(h.ctx, StuckThrottledHostName)
	if err != nil {
		t.Fatalf("the fixture's throttled host is missing: %v", err)
	}
	if host.Throttle.Level != 2 || host.EffectiveCapacity() != 2 || !host.Usage.Fresh(h.c.Now()) {
		t.Fatalf("host = throttle %+v, effective %d, fresh %v; want rung 2 of 4 with a fresh sample", host.Throttle, host.EffectiveCapacity(), host.Usage.Fresh(h.c.Now()))
	}
	view := h.c.HostView(host)
	if !strings.Contains(view.ThrottleReason, "30.0") || view.Throttle == nil || view.EffectiveCapacity != 2 {
		t.Fatalf("view = reason %q, throttle %+v, effective %d", view.ThrottleReason, view.Throttle, view.EffectiveCapacity)
	}
	if !contains(h.problemCodes(), "host.throttled") {
		t.Fatalf("problems = %v, want host.throttled", h.problemCodes())
	}
	var placed *store.Runner
	for _, r := range h.runners() {
		if r.HostID == host.ID {
			placed = r
		}
	}
	if placed == nil || placed.State != store.RunnerBusy || placed.AllocationSource != store.AllocationFromHost ||
		placed.AllocatedCPUs != 1.87 || placed.AllocatedMemoryMB != 3968 {
		t.Fatalf("runner on the throttled host = %+v; want a busy one allocated the host's share", placed)
	}
	if got := len(h.runners()); got != 12 {
		t.Fatalf("the fixture has %d runners, want the demo's 12: the runner was to be moved, not added", got)
	}

	// Seeding again is a no-op.
	if err := h.c.SeedStuck(h.ctx); err != nil {
		t.Fatalf("second SeedStuck: %v", err)
	}
	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(hosts) != 4 {
		t.Fatalf("seeded %d hosts, want the demo's 3 and the throttled one", len(hosts))
	}

	// Long enough for the sample to have gone stale and the reset to be due:
	// the demo beat keeps the sample fresh and housekeeping leaves the
	// fixture's rung alone, so the card keeps explaining itself.
	future := time.Now().Add(scheduler.StaleThrottleReset * 2)
	h.c.clock = func() time.Time { return future }
	h.c.beatDemoHosts(h.ctx)
	h.c.settleThrottles(h.ctx, future)
	host, err = h.st.GetHost(h.ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Level != 2 || !host.Usage.Fresh(future) || !host.Healthy(future) {
		t.Fatalf("after housekeeping: throttle %+v, fresh %v, healthy %v; the fixture did not hold", host.Throttle, host.Usage.Fresh(future), host.Healthy(future))
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The fixture has to survive the loop that reads it.
//
// A pool holding more runners than its queue justifies has the ones that have
// not finished starting drained on the very first pass -- "queued demand
// disappeared before this runner finished starting" -- so a demo seeded with a
// runner in provisioning and one in registering showed neither a second later.
// That is both states missing from the grid and from the screenshots, and it
// leaves the diagnostics fixture, which ages exactly those two into stuck
// runners, with nothing to age.
func TestSeedDemoKeepsItsStartingRunnersThroughAReconcilePass(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	starting := map[string]store.RunnerState{}
	for _, r := range h.runners() {
		if r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering {
			starting[r.ID] = r.State
		}
	}
	if len(starting) != 2 {
		t.Fatalf("the fixture starts %d runners, want the two states the UI has to show", len(starting))
	}

	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}

	for _, r := range h.runners() {
		want, ok := starting[r.ID]
		if !ok {
			continue
		}
		if r.State != want {
			t.Fatalf("runner %s was %s before the pass and is %s after it (%q); the fixture does not add up to the scheduler",
				r.ID, want, r.State, r.Message)
		}
	}
}

// The Playwright suite and a demo instance both need a fleet with something in
// it. This is that fixture, and it has to be the same fixture every time.
func TestSeedDemoBuildsAFleet(t *testing.T) {
	h := newHarness(t)

	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	pools, err := h.st.ListPools(h.ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(pools) != 2 {
		t.Fatalf("seeded %d pools, want 2", len(pools))
	}

	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	if len(hosts) != 3 {
		t.Fatalf("seeded %d hosts, want 3", len(hosts))
	}

	runners := h.runners()
	if len(runners) != 12 {
		t.Fatalf("seeded %d runners, want 12", len(runners))
	}
	states := map[store.RunnerState]int{}
	for _, r := range runners {
		states[r.State]++
	}
	for _, want := range []store.RunnerState{
		store.RunnerProvisioning, store.RunnerRegistering, store.RunnerIdle,
		store.RunnerBusy, store.RunnerDraining, store.RunnerFailed, store.RunnerRemoved,
	} {
		if states[want] == 0 {
			t.Fatalf("no seeded runner is %q; the UI has nothing to render for that state", want)
		}
	}

	jobs, total, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{Limit: 100})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	// Fifty of a morning's history, the two on a vendor's runners, and the
	// backlog that explains the runners this fleet has not finished starting.
	if total != 55 {
		t.Fatalf("seeded %d jobs, want 55", total)
	}
	var completed, queued, running, unmatched, elsewhere int
	for _, j := range jobs {
		switch j.State {
		case store.JobCompleted:
			completed++
		case store.JobQueued:
			queued++
		case store.JobInProgress:
			running++
		}
		if !j.Matched {
			unmatched++
		}
		// A job on a vendor's runner: no pool claimed it and no runner here
		// ran it. The Overview's panels are built to tell these apart, so the
		// fixture has to contain some -- one finished, one still running, and
		// one still queued, which is the one the default view used to show.
		if store.HostedJob(j.Labels) {
			elsewhere++
		}
	}
	if completed == 0 || queued == 0 || running == 0 {
		t.Fatalf("job mix = %d completed, %d queued, %d running; the Overview needs all three",
			completed, queued, running)
	}
	if unmatched == 0 {
		t.Fatal("no seeded job is unmatched, so the problems drawer has nothing to show")
	}
	if elsewhere != 3 {
		t.Fatalf("%d jobs belong to somebody else's runners, want 3 (one finished, one running, one queued)", elsewhere)
	}

	// The Overview's history and the audit page both need rows.
	evs, err := h.st.ListScalingEvents(h.ctx, "", 50)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	if len(evs) == 0 {
		t.Fatal("no scaling history was seeded")
	}
	audit, auditTotal, err := h.st.ListAudit(h.ctx, store.AuditFilter{}, store.Page{Limit: 50})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	if auditTotal == 0 || len(audit) == 0 {
		t.Fatal("no audit rows were seeded")
	}

	// The shared browser controller lives for the whole suite. Keep the burst
	// close enough to the fixture's present that its one-hour view still has a
	// queued-with-nothing-idle spell when the mobile project reaches it.
	samples, err := h.st.ListSamples(h.ctx, h.c.Now().Add(-30*time.Minute))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	starved := 0
	for _, sample := range samples {
		if sample.FleetQueuedJobs > 0 && sample.IdleRunners == 0 {
			starved++
		}
	}
	if starved == 0 {
		t.Fatal("the recent demo history has no queued work with nothing idle")
	}

	// Stats has to work over the fixture, since that is what the Overview does.
	if _, err := h.c.Stats(h.ctx, 24*time.Hour); err != nil {
		t.Fatalf("Stats over the fixture: %v", err)
	}
}

// Seeding twice must not double the fixture: the Playwright suite restarts the
// binary and would otherwise accumulate a fleet.
func TestSeedDemoIsIdempotent(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("first SeedDemo: %v", err)
	}
	before := len(h.runners())

	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("second SeedDemo: %v", err)
	}
	if got := len(h.runners()); got != before {
		t.Fatalf("runners went from %d to %d on a second seed", before, got)
	}
}

// Fixtures appearing in somebody's real fleet would be indistinguishable from
// a compromise, so an instance that is already in use is refused.
func TestSeedDemoRefusesARealFleet(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "production-linux")

	err := h.c.SeedDemo(h.ctx)
	if err == nil {
		t.Fatal("SeedDemo seeded an instance that already had a real pool")
	}
	if !strings.Contains(err.Error(), "production-linux") || !strings.Contains(err.Error(), SeedEnvVar) {
		t.Fatalf("error = %q, want it to name the pool and how to turn seeding off", err)
	}
	if got := len(h.runners()); got != 0 {
		t.Fatalf("the refused seed still wrote %d runners", got)
	}
}

// The Jobs page's drawer, its failed filter and the problems drawer's "runner
// lost" entry all need a fixture behind them, and the timeline needs one job
// whose story it can tell in full.
func TestSeedDemoGivesJobsStepsATimelineAndOneLostRunner(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	failed, total, err := h.st.ListJobs(h.ctx, store.JobFilter{FailedOnly: true}, store.Page{Limit: 100})
	if err != nil {
		t.Fatalf("ListJobs: %v", err)
	}
	if total == 0 {
		t.Fatal("the seed has no failed job for the failed filter to find")
	}
	var lost *store.Job
	for _, j := range failed {
		if j.Conclusion == "failure" && j.FailedStep() == nil {
			t.Errorf("failed job %s names no failed step", j.ID)
		}
		if j.RunnerFault != "" {
			lost = j
		}
	}
	if lost == nil {
		t.Fatal("no seeded job lost its runner, so the runner_lost badge has no fixture")
	}

	events, err := h.c.JobEvents(h.ctx, lost.ID)
	if err != nil {
		t.Fatalf("JobEvents: %v", err)
	}
	kinds := kindsOfEvents(events)
	for _, want := range []store.JobEventKind{store.JobEventQueued, store.JobEventClaimed, store.JobEventStarted, store.JobEventRunnerLost, store.JobEventCompleted} {
		found := false
		for _, k := range kinds {
			found = found || k == want
		}
		if !found {
			t.Errorf("the lost-runner job's timeline %v lacks %s", kinds, want)
		}
	}
	for i := 1; i < len(events); i++ {
		if events[i].At.Before(events[i-1].At) {
			t.Errorf("timeline out of order at %d: %v after %v", i, events[i].At, events[i-1].At)
		}
	}

	running, _, err := h.st.ListJobs(h.ctx, store.JobFilter{States: []store.JobState{store.JobInProgress}}, store.Page{})
	if err != nil {
		t.Fatalf("ListJobs running: %v", err)
	}
	for _, j := range running {
		if len(j.Steps) == 0 || j.FailedStep() != nil {
			t.Errorf("running job %s has steps %+v, want some in flight and none failed", j.ID, j.Steps)
		}
	}
}

// A pool was the only thing the guard looked at. A production controller that
// has an installation, a host and an administrator but no pool yet -- the
// state every fresh install passes through -- got a fixture fleet if its
// compose file kept ZOOMIES_SEED_DEMO from a trial run.
func TestSeedDemoRefusesAnInstanceWithRealStateButNoPool(t *testing.T) {
	cases := []struct {
		name string
		set  func(h *harness)
		want string
	}{
		{"an installation", func(h *harness) { h.installation() }, "installation"},
		{"a host", func(h *harness) { h.host("build-1") }, `host "build-1"`},
		{"an account", func(h *harness) {
			if err := h.st.CreateUser(h.ctx, &store.User{Username: "root", Role: store.RoleAdmin}); err != nil {
				h.t.Fatalf("CreateUser: %v", err)
			}
		}, "1 account"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			tc.set(h)
			err := h.c.SeedDemo(h.ctx)
			if err == nil {
				t.Fatalf("SeedDemo seeded an instance that already had %s", tc.name)
			}
			if !strings.Contains(err.Error(), tc.want) || !strings.Contains(err.Error(), SeedEnvVar) {
				t.Fatalf("error = %q, want it to name %s and how to turn seeding off", err, tc.want)
			}
			pools, err := h.st.ListPools(h.ctx)
			if err != nil || len(pools) != 0 {
				t.Fatalf("the refused seed still wrote %d pools (%v)", len(pools), err)
			}
		})
	}
}

// And the demo's own fixtures are not "real state": a seeded instance is
// still recognised as seeded on its next start.
func TestSeedDemoStillRecognisesItsOwnFixtures(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("first SeedDemo: %v", err)
	}
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("second SeedDemo refused its own fixtures: %v", err)
	}
}

// The demo fleet has to stay alive for as long as somebody is looking at it.
//
// A seeded host has no agent behind it, so its heartbeat is written once. Ninety
// seconds later store.HeartbeatTimeout has passed, every demo host is unhealthy
// and every demo pool reports that it has nowhere to run -- the fleet goes dark
// while the page is open. It also made the Playwright suite's answers depend on
// how long the suite had been running.
func TestDemoHostsKeepBeating(t *testing.T) {
	h := newHarness(t)

	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	// Far enough past the timeout that nothing is healthy any more.
	future := time.Now().Add(store.HeartbeatTimeout * 3)
	h.c.clock = func() time.Time { return future }

	hosts, err := h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	for _, host := range hosts {
		if host.Healthy(future) {
			t.Fatalf("host %s was still healthy before the beat; the fixture proves nothing", host.ID)
		}
	}

	h.c.beatDemoHosts(h.ctx)

	hosts, err = h.st.ListHosts(h.ctx)
	if err != nil {
		t.Fatalf("ListHosts: %v", err)
	}
	if len(hosts) == 0 {
		t.Fatal("no hosts to check")
	}
	for _, host := range hosts {
		if !host.Healthy(future) {
			t.Errorf("demo host %s is unhealthy after a beat", host.ID)
		}
	}
}

// And it never touches a host it did not create: an operator who set
// ZOOMIES_SEED_DEMO on an instance that has since grown a real agent must not
// have that agent's silence covered up.
func TestDemoHeartbeatLeavesRealHostsAlone(t *testing.T) {
	h := newHarness(t)

	real := &store.Host{
		ID:            "hst_realone",
		Name:          "a-real-host",
		Capacity:      2,
		LastHeartbeat: time.Now().Add(-store.HeartbeatTimeout * 2),
	}
	if err := h.st.CreateHost(h.ctx, real); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}

	h.c.beatDemoHosts(h.ctx)

	got, err := h.st.GetHost(h.ctx, real.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Healthy(time.Now()) {
		t.Fatal("a real host was marked alive by the demo heartbeat")
	}
}

// The demo fleet holds one runner in provisioning and one in registering so
// both states appear in the grid. On a real fleet those states last seconds, so
// left alone the fixture ages into a fleet reporting runners that are stuck --
// on every screenshot, and in the back half of a Playwright run but not the
// front half, which is the worst kind of failure to chase.
func TestTheDemoFleetDoesNotAgeIntoAFleetWithAProblem(t *testing.T) {
	h := newHarness(t)
	if err := h.c.SeedDemo(h.ctx); err != nil {
		t.Fatalf("SeedDemo: %v", err)
	}

	// An hour into an instance somebody left open on a second monitor.
	future := time.Now().Add(time.Hour)
	h.c.clock = func() time.Time { return future }

	if got := h.problemCodes(); !contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v; an hour-old fixture should be stuck before the beat, or this test proves nothing", got)
	}

	h.c.freshenDemoRunners(h.ctx)

	if got := h.problemCodes(); contains(got, "runners.not_progressing") {
		t.Fatalf("problems = %v, want the demo's starting runners to read as freshly started", got)
	}
	// The states themselves survive: freshening a clock must not quietly
	// finish the runners the fixture exists to show.
	states := map[store.RunnerState]int{}
	for _, r := range h.runners() {
		states[r.State]++
	}
	if states[store.RunnerProvisioning] != 1 || states[store.RunnerRegistering] != 1 {
		t.Fatalf("states = %v, want one provisioning and one registering runner still there", states)
	}
}

// And it never touches a runner it did not seed: a real runner that is genuinely
// stuck must not have its clock wound back by an instance someone set
// ZOOMIES_SEED_DEMO on.
func TestDemoRefreshLeavesRealRunnersAlone(t *testing.T) {
