func TestLostLeaseStopsRunnerCreation(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 1, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	h.c.leaseLost.Store(&store.ControllerLease{Holder: "rival"})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.c.lifecycleCalls.Wait()
	if len(h.runners()) != 0 {
		t.Fatal("created runner without authority")
	}
}
func TestRecoveryFenceStopsCleanupDispatch(t *testing.T) {
	h := newHarness(t)
	_, p, host := h.fleet()
	r := h.runnerRow(p, host, store.RunnerFailed)
	if err := h.st.RecordCleanupFailure(h.ctx, r.ID, "host unreachable"); err != nil {
		t.Fatal(err)
	}
	h.fence("restored")
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	if h.hasTaskOfKind(host.ID, agent.TaskRemoveRunner) {
		t.Fatal("fenced controller dispatched removal")
	}
}
func TestRecoveryFenceWithholdsPreviouslyQueuedTasks(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	h.c.enqueue(host.ID, agent.Task{Kind: agent.TaskRemoveRunner, RunnerID: "run_unknown"})
	h.fence("restored")
	b, err := h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(b.Tasks) != 0 {
		t.Fatalf("fenced poll=%v %v", b, err)
	}
	if err := h.c.Unfence(h.ctx); err != nil {
		t.Fatal(err)
	}
	b, err = h.c.PollTasks(h.ctx, host.ID, time.Millisecond)
	if err != nil || len(b.Tasks) != 1 {
		t.Fatalf("intent was lost: %v %v", b, err)
	}
}
func TestDuplicateCompletionCountsOnce(t *testing.T) {
	h := newHarness(t)
	_, p, _ := h.fleet()
	e := jobEvent{Action: "completed", JobID: 1, Conclusion: "success", Labels: []string{"self-hosted", "linux", "x64", "demo"}}
	h.deliverJob(e)
	h.deliverJob(e)
	if got := testutil.ToFloat64(h.c.metrics.jobsTotal.WithLabelValues(p.Name, "success")); got != 1 {
		t.Fatalf("completion count=%v", got)
	}
}
func TestExpiredAuthorityCannotAdmitWork(t *testing.T) {
	h := newHarness(t)
	h.c.lease = &store.ControllerLease{Holder: "ours", RenewedAt: h.c.Now().Add(-LeaseTTL)}
	if h.c.mayAct() {
		t.Fatal("expired lease admitted work")
	}
	at := h.c.Now()
	h.c.leaseRenewed.Store(&at)
	if !h.c.mayAct() {
		t.Fatal("renewed lease not honoured")
	}
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"
)

func TestObserveDurationRejectsMissingOutOfOrderAndNegativeTimestamps(t *testing.T) {
	h := startupHistogram("test_startup_seconds", "test")
	now := time.Unix(100, 0)
	if observeDuration(h, "linux", "docker", time.Time{}, now) {
		t.Fatal("accepted a missing timestamp")
	}
	if observeDuration(h, "linux", "docker", now, now.Add(-time.Second)) {
		t.Fatal("accepted an out-of-order negative duration")
	}
	if !observeDuration(h, "linux", "docker", now, now.Add(250*time.Millisecond)) {
		t.Fatal("rejected a valid duration")
	}
	r := prometheus.NewRegistry()
	r.MustRegister(h)
	families, err := r.Gather()
	if err != nil {
		t.Fatal(err)
	}
	if len(families) != 1 || len(families[0].Metric) != 1 {
		t.Fatalf("unexpected metric families: %+v", families)
	}
	m := families[0].Metric[0].GetHistogram()
	if m.GetSampleCount() != 1 || m.GetSampleSum() != .25 {
		t.Fatalf("count/sum = %d/%g", m.GetSampleCount(), m.GetSampleSum())
	}
	labels := families[0].Metric[0].Label
	if len(labels) != 2 || labels[0].GetName() != "backend" || labels[1].GetName() != "pool" {
		t.Fatalf("labels = %+v", labels)
	}
}

func TestStartupMetricsHaveOnlyBoundedDimensionLabels(t *testing.T) {
	h := startupHistogram("test_labels_seconds", "test")
	d := make(chan *prometheus.Desc, 1)
	h.Describe(d)
	desc := (<-d).String()
	for _, forbidden := range []string{"repository", "job", "runner_id", "image", "digest"} {
		if strings.Contains(desc, forbidden) {
			t.Fatalf("descriptor contains forbidden label %q: %s", forbidden, desc)
		}
	}
	if !strings.Contains(desc, "pool") || !strings.Contains(desc, "backend") {
		t.Fatalf("descriptor lacks bounded labels: %s", desc)
	}
}

func TestPercentileDurations(t *testing.T) {
	values := []int64{950, 10, 500, 100, 50}
	if got := percentile(values, .5); got != 100 {
		t.Fatalf("p50 = %d, want 100", got)
	}
	if got := percentile(values, .95); got != 950 {
		t.Fatalf("p95 = %d, want 950", got)
	}
	if got := percentile(nil, .95); got != 0 {
		t.Fatalf("missing percentile = %d, want 0", got)
	}
}

package controller

import (
	"context"
	"fmt"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// defaultStatsWindow is the period this summarises when the caller does not ask
// for one.
//
// It is statsEventWindow, and has to be: the same numbers arrive by fetch and
// by `stats` frame, and while these disagreed -- a day for the fetch, an hour
// for the frame -- an Overview showed a day of completed jobs and a day's wait
// percentiles for the second or two before its first frame arrived, then
// silently replaced them with an hour's. Nobody watching could tell which
// window they were looking at, and the documented default said an hour
// throughout.
const defaultStatsWindow = statsEventWindow

// Stats is the Overview payload: what the queue is doing, what the fleet is
// doing, and how long jobs are waiting.
type Stats struct {
	// Window is the period the completed counts and the wait percentiles
	// cover. Completed is Succeeded + Failed + Cancelled + Unknown; a rate
	// computed from Completed and Failed alone would count a job GitHub
	// stopped reporting as a success, which is why the split is here.
	Window      string `json:"window"`
	QueuedJobs  int    `json:"queued_jobs"`
	RunningJobs int    `json:"running_jobs"`
	Completed   int    `json:"completed"`
	Succeeded   int    `json:"succeeded"`
	Failed      int    `json:"failed"`
	// FleetFailed is how many of Failed this deployment caused rather than the
	// workflows: a runner that never started, or one that stopped under the
	// job. It is a subset rather than a fifth outcome -- GitHub's answer for
	// such a job is still "failure", and a split that did not add up would be
	// a worse lie than no split.
	//
	// It is the number the taxonomy exists for. "Eleven failures this hour" is
	// a question; "eleven, nine of them ours" is an answer, and it sends a
	// different person to a different page.
	FleetFailed int `json:"fleet_failed"`
	// Faults counts those failures by category, so the Overview can say which
	// of the fleet's problems this is rather than only that it has one. Absent
	// categories are absent rather than zero.
	Faults map[store.FaultKind]int `json:"faults,omitempty"`
	// RunnerStartFaults counts the runners that failed before taking a job,
	// also by category. These are in no job count anywhere, because the jobs
	// they were meant for are still queued -- which is exactly why a fleet
	// that cannot start a container reads as a fleet that is merely busy.
	RunnerStartFaults map[store.FaultKind]int `json:"runner_start_faults,omitempty"`
	Cancelled         int                     `json:"cancelled"`
	Unknown           int                     `json:"unknown"`
	MedianWaitMS      int64                   `json:"median_wait_ms"`
	P95WaitMS         int64                   `json:"p95_wait_ms"`
	P50StartupMS      int64                   `json:"p50_startup_ms"`
	P95StartupMS      int64                   `json:"p95_startup_ms"`
	P50RegistrationMS int64                   `json:"p50_registration_ms"`
	P95RegistrationMS int64                   `json:"p95_registration_ms"`

	// Fleet is every job figure above, narrowed to the jobs this fleet has a
	// hand in. Both are carried in one payload rather than chosen by a query
	// parameter because the same numbers arrive over the event stream, which
	// is one frame for every viewer: a per-request scope would be correct
	// until the next frame overwrote it, a second or two later.
	Fleet ScopedJobStats `json:"fleet"`

	Runners RunnerStats `json:"runners"`
	Hosts   HostStats   `json:"hosts"`
	Pools   []PoolStats `json:"pools"`
}

// ScopedJobStats is the job half of Stats over one scope.
//
// GitHub reports every job in an installed repository, and on an organisation
// that also uses hosted runners most of them are somebody else's. A queue depth
// that counts those answers "why is my fleet slow?" with a number nobody here
// can act on, and a median wait computed from them is somebody else's queue.
type ScopedJobStats struct {
	QueuedJobs  int `json:"queued_jobs"`
	RunningJobs int `json:"running_jobs"`
	Completed   int `json:"completed"`
	Succeeded   int `json:"succeeded"`
	Failed      int `json:"failed"`
	// FleetFailed is the part of Failed this fleet caused. See Stats.
	FleetFailed  int   `json:"fleet_failed"`
	Cancelled    int   `json:"cancelled"`
	Unknown      int   `json:"unknown"`
	MedianWaitMS int64 `json:"median_wait_ms"`
	P95WaitMS    int64 `json:"p95_wait_ms"`
}

// RunnerStats counts the fleet by runner state.
type RunnerStats struct {
	Provisioning int `json:"provisioning"`
	Registering  int `json:"registering"`
	Idle         int `json:"idle"`
	Busy         int `json:"busy"`
	Draining     int `json:"draining"`
	Failed       int `json:"failed"`
	Total        int `json:"total"`
}

// HostStats summarises the agents and the room they have left.
type HostStats struct {
	Total    int `json:"total"`
	Healthy  int `json:"healthy"`
	Cordoned int `json:"cordoned"`
	Capacity int `json:"capacity"`
	Used     int `json:"used"`
}

// PoolStats is one row of the Overview's per-pool utilisation.
type PoolStats struct {
	PoolID   string `json:"pool_id"`
	PoolName string `json:"pool_name"`
	Min      int    `json:"min"`
	Max      int    `json:"max"`
	Live     int    `json:"live"`
	Busy     int    `json:"busy"`
	Idle     int    `json:"idle"`
	// Queued is the number of queued jobs this pool has claimed.
	Queued      int     `json:"queued"`
	Utilisation float64 `json:"utilisation"`
}

// Stats builds the Overview payload over a rolling window.
func (c *Controller) Stats(ctx context.Context, window time.Duration) (*Stats, error) {
	if window <= 0 {
		window = defaultStatsWindow
	}
	since := c.Now().Add(-window)

	js, err := c.st.StatsSince(ctx, since, false)
	if err != nil {
		return nil, fmt.Errorf("computing job statistics: %w", err)
	}
	fleet, err := c.st.StatsSince(ctx, since, true)
	if err != nil {
		return nil, fmt.Errorf("computing this fleet's job statistics: %w", err)
	}
	out := &Stats{
		Fleet: ScopedJobStats{
			QueuedJobs:   fleet.Queued,
			RunningJobs:  fleet.Running,
			Completed:    fleet.CompletedLast,
			Succeeded:    fleet.Succeeded,
			Failed:       fleet.Failed,
			FleetFailed:  fleet.FleetFailed,
			Cancelled:    fleet.Cancelled,
			Unknown:      fleet.Unknown,
			MedianWaitMS: fleet.MedianWaitMS,
			P95WaitMS:    fleet.P95WaitMS,
		},
		Window:       window.String(),
		QueuedJobs:   js.Queued,
		RunningJobs:  js.Running,
		Completed:    js.CompletedLast,
		Succeeded:    js.Succeeded,
		Failed:       js.Failed,
		FleetFailed:  js.FleetFailed,
		Cancelled:    js.Cancelled,
		Unknown:      js.Unknown,
		MedianWaitMS: js.MedianWaitMS,
		P95WaitMS:    js.P95WaitMS,
	}

	// The two category breakdowns behind the split. A window with no fleet
	// failures in it produces no map at all, which is the shape the Overview
	// wants: nothing to draw rather than nine zeroes to draw nothing with.
	if out.FleetFailed > 0 {
		faults, err := c.st.JobFaultCountsSince(ctx, since, false)
		if err != nil {
			return nil, fmt.Errorf("counting job failures by category: %w", err)
		}
		out.Faults = faults
	}
	startFaults, err := c.st.RunnerFaultCountsSince(ctx, since)
	if err != nil {
		return nil, fmt.Errorf("counting runner failures by category: %w", err)
	}
	if len(startFaults) > 0 {
		out.RunnerStartFaults = startFaults
	}

	counts, err := c.st.CountRunnersByPool(ctx)
	if err != nil {
		return nil, fmt.Errorf("counting runners: %w", err)
	}
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing pools: %w", err)
	}
	queued, err := c.st.ListQueuedJobs(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing queued jobs: %w", err)
	}
	queuedByPool := map[string]int{}
	for _, j := range queued {
		queuedByPool[j.PoolID]++
	}
	// The samples come from a query over the window rather than a page of
	// runner rows: the page was capped at 500, so the percentiles described
	// the newest few hundred starts and called it a day.
	startup, registration, err := c.st.StartupSamples(ctx, since)
	if err != nil {
		return nil, fmt.Errorf("sampling runner start-up times: %w", err)
	}
	out.P50StartupMS, out.P95StartupMS = percentile(startup, .50), percentile(startup, .95)
	out.P50RegistrationMS, out.P95RegistrationMS = percentile(registration, .50), percentile(registration, .95)

	out.Pools = make([]PoolStats, 0, len(pools))
	for _, p := range pools {
		pc := counts[p.ID]
		out.Runners.Provisioning += pc.Provisioning
		out.Runners.Registering += pc.Registering
		out.Runners.Idle += pc.Idle
		out.Runners.Busy += pc.Busy
		out.Runners.Draining += pc.Draining
		out.Runners.Failed += pc.Failed
		out.Pools = append(out.Pools, PoolStats{
			PoolID:      p.ID,
			PoolName:    p.Name,
			Min:         p.MinRunners,
			Max:         p.MaxRunners,
			Live:        pc.Live(),
			Busy:        pc.Busy,
			Idle:        pc.Idle,
			Queued:      queuedByPool[p.ID],
			Utilisation: pc.Utilisation(),
		})
	}
	out.Runners.Total = out.Runners.Provisioning + out.Runners.Registering + out.Runners.Idle +
		out.Runners.Busy + out.Runners.Draining + out.Runners.Failed

	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing hosts: %w", err)
	}
	now := c.Now()
	for _, h := range hosts {
		out.Hosts.Total++
		if h.Healthy(now) {
			out.Hosts.Healthy++
		}
		if h.Cordoned {
			out.Hosts.Cordoned++
		}
		// An unhealthy host's capacity is not capacity anyone can use, so it
		// is left out rather than flattering the total. A throttled host's
		// slots are counted as the throttle leaves them, for the same reason:
		// the Overview's "capacity" is what the fleet will take right now.
		// Used is counted over the same hosts: a runner still finishing on a
		// cordoned host occupies a slot capacity does not offer, and
		// counting it made "used of capacity" read as full, or over full,
		// while the healthy hosts beside it sat free. Runners.Total still
		// counts every live runner.
		if h.Healthy(now) && !h.Cordoned {
			out.Hosts.Capacity += h.EffectiveCapacity()
			out.Hosts.Used += h.ActiveRunners
		}
	}
	return out, nil
}

func percentile(values []int64, q float64) int64 {
	if len(values) == 0 {
		return 0
	}
	slices.Sort(values)
	i := int(float64(len(values)-1)*q + .5)
	return values[i]
}

// Samples returns the Overview's sparkline points since a cutoff.
func (c *Controller) Samples(ctx context.Context, since time.Time) ([]store.FleetSample, error) {
	return c.st.ListSamples(ctx, since)
}

// HostSamples returns every host's minute samples since a cutoff, for the
// Hosts page's capacity map. An empty hostID means every host.
func (c *Controller) HostSamples(ctx context.Context, since time.Time, hostID string) ([]store.HostSample, error) {
	return c.st.ListHostSamples(ctx, since, hostID)
}

package controller

import (
	"testing"
)

// A fetch and a frame must summarise the same period.
//
// They did not: the fetch defaulted to a day and the frame to an hour, so an
// Overview showed a day's completed counts and wait percentiles for the second
// or two before its first frame landed and then silently swapped them for an
// hour's. The spec said an hour the whole time.
func TestAFetchAndAFrameSummariseTheSameWindow(t *testing.T) {
	h := newHarness(t)

	fetched, err := h.c.Stats(h.ctx, 0)
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	framed, err := h.c.Stats(h.ctx, statsEventWindow)
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	if fetched.Window != framed.Window {
		t.Errorf("a fetch covers %s and a frame covers %s; the tiles change under the operator when the first frame arrives",
			fetched.Window, framed.Window)
	}
}

package controller

import (
	"context"
	"fmt"
	"math"
	"slices"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/version"
)

// FleetState is the one word the status projection leads with.
type FleetState string

const (
	// FleetHealthy is a fleet with nothing on its own list above info.
	FleetHealthy FleetState = "healthy"
	// FleetDegraded is a fleet whose worst problem is a warning: jobs still
	// run, slower or with less room than they should have.
	FleetDegraded FleetState = "degraded"
	// FleetBlocked is a fleet whose worst problem is an error: something the
	// fleet is asked to do is not happening, and waiting will not fix it.
	FleetBlocked FleetState = "blocked"
)

// Band is a count said roughly. The status projection is read by people with
// no account, and "eleven jobs queued" tells them nothing "many" does not
// while telling a stranger exactly how big the fleet is.
type Band string

const (
	BandNone     Band = "none"
	BandFew      Band = "few"
	BandMany     Band = "many"
	BandBackedUp Band = "backed_up"
)

// fewUpTo is the largest count still called "few": a handful, the size of
// one push's matrix on a small fleet.
const fewUpTo = 5

// FleetStatus is what GET /api/v1/status returns: a projection, not a view.
//
// It is the one payload in the API that is deliberately not a resource's GET
// shape, because every resource view carries names -- a pool's, a host's, a
// repository's -- and this is for the developer with no account whose job
// has queued. So it is built the other way round: it carries no string that
// came from a row. Its reasons are codes, its counts are bands, its waits are
// whole minutes, and the only prose in it is the fixed public sentence for
// each code. Proving that is a test that searches a body for every name a
// fixture fleet has, which is a check rather than a promise renewed every
// time somebody edits a sentence.
type FleetStatus struct {
	State FleetState `json:"state"`
	// Since is when this process first saw the fleet in this state.
	Since   time.Time `json:"since"`
	Version string    `json:"version"`
	// Queued and Running are the fleet's own jobs, banded.
	Queued  Band `json:"queued"`
	Running Band `json:"running"`
	// The queue wait over the last hour, rounded to the minute.
	MedianWaitMinutes int `json:"median_wait_minutes"`
	P95WaitMinutes    int `json:"p95_wait_minutes"`
	// Reasons are the fleet's current problems, one per code, worst first.
	Reasons []StatusReason `json:"reasons"`
	// Explanations is the public sentence for each code in Reasons. It is
	// beside the reasons rather than in them so that a reason stays three
	// fields and nothing else.
	Explanations map[string]string `json:"explanations"`
}

// StatusReason is one code on the fleet's list: which, how bad, and since
// when. Nothing else -- the operator's title and detail name the pool or host
// they are about, and that is exactly what this must not carry.
type StatusReason struct {
	Code     string          `json:"code"`
	Severity config.Severity `json:"severity"`
	Since    *time.Time      `json:"since,omitempty"`
}

// ProjectStatus builds the name-free status from the operator's problems list
// and the Overview's numbers. It is pure so that the disclosure boundary can
// be tested without a fleet.
//
// Only the fleet's half of the problems split is read, the half a signed-in
// fleet operator without the platform role is shown, so a platform finding --
// the backup remote, the lease, the controller's own release -- cannot reach
// it even by a mistake in the sentences below.
func ProjectStatus(problems []Problem, stats *Stats) FleetStatus {
	out := FleetStatus{
		State:        FleetHealthy,
		Queued:       BandNone,
		Running:      BandNone,
		Reasons:      []StatusReason{},
		Explanations: map[string]string{},
	}
	byCode := map[string]int{}
	for _, p := range problems {
		audience := p.Audience
		if audience == "" {
			audience = audienceFor(p.Code)
		}
		if !audience.For(false) {
			continue
		}
		if p.Severity != config.SeverityError && p.Severity != config.SeverityWarning {
			continue
		}
		// One reason per code: three pools with no capacity is one reason a
		// job waits, and a count of them would be a count of pools.
		if i, ok := byCode[p.Code]; ok {
			r := &out.Reasons[i]
			if severityRank(p.Severity) < severityRank(r.Severity) {
				r.Severity = p.Severity
			}
			if p.Since != nil && (r.Since == nil || p.Since.Before(*r.Since)) {
				since := *p.Since
				r.Since = &since
			}
			continue
		}
		r := StatusReason{Code: p.Code, Severity: p.Severity}
		if p.Since != nil {
			since := *p.Since
			r.Since = &since
		}
		byCode[p.Code] = len(out.Reasons)
		out.Reasons = append(out.Reasons, r)
	}
	slices.SortStableFunc(out.Reasons, func(a, b StatusReason) int {
		if r := severityRank(a.Severity) - severityRank(b.Severity); r != 0 {
			return r
		}
		if a.Code < b.Code {
			return -1
		}
		if a.Code > b.Code {
			return 1
		}
		return 0
	})
	for _, r := range out.Reasons {
		switch {
		case r.Severity == config.SeverityError:
			out.State = FleetBlocked
		case out.State == FleetHealthy:
			out.State = FleetDegraded
		}
		out.Explanations[r.Code] = PublicSentence(r.Code)
	}

	if stats != nil {
		out.Queued = queueBand(stats.Fleet.QueuedJobs, stats.Hosts.Capacity)
		out.Running = countBand(stats.Fleet.RunningJobs)
		out.MedianWaitMinutes = wholeMinutes(stats.Fleet.MedianWaitMS)
		out.P95WaitMinutes = wholeMinutes(stats.Fleet.P95WaitMS)
	}
	return out
}

// countBand says a count roughly.
func countBand(n int) Band {
	switch {
	case n <= 0:
		return BandNone
	case n <= fewUpTo:
		return BandFew
	default:
		return BandMany
	}
}

// queueBand is countBand with one more word: a queue longer than every slot
// the fleet has is backed up, which is the thing a developer waiting on it
// most needs to know and the one a bare "many" hides.
func queueBand(queued, capacity int) Band {
	b := countBand(queued)
	if b == BandMany && queued > capacity {
		return BandBackedUp
	}
	return b
}

func wholeMinutes(ms int64) int {
	if ms <= 0 {
		return 0
	}
	return int(math.Round(float64(ms) / float64(time.Minute/time.Millisecond)))
}

// Status is the projection for the running fleet, with Since kept across
// calls so it means "since the state last changed" rather than "since you
// asked".
func (c *Controller) Status(ctx context.Context) (*FleetStatus, error) {
	problems, err := c.Problems(ctx)
	if err != nil {
		return nil, fmt.Errorf("gathering the fleet's problems: %w", err)
	}
	stats, err := c.Stats(ctx, defaultStatsWindow)
	if err != nil {
		return nil, fmt.Errorf("gathering the fleet's numbers: %w", err)
	}
	out := ProjectStatus(problems, stats)
	out.Version = version.Version

	c.statusMu.Lock()
	if c.statusSince.IsZero() || c.statusState != out.State {
		c.statusState = out.State
		c.statusSince = c.Now().UTC().Truncate(time.Second)
	}
	out.Since = c.statusSince
	c.statusMu.Unlock()
	return &out, nil
}

// PublicSentence is what the status page says about a code, for a reader who
// cannot act on the fleet and wants to know whether to wait.
func PublicSentence(code string) string {
	if s, ok := publicSentences[code]; ok {
		return s
	}
	// Unreachable for any code the fleet's list can carry --
	// TestEveryFleetCodeHasAPublicSentence sees to that -- but a build between
	// a new code and its sentence says something true rather than nothing.
	return "The fleet has a problem its operators have been told about."
}

