// The task queue is in memory by design: every task is derived from state the
// database already holds, so persisting the queue would add a second source of
// truth that could disagree with the runners table.
//
// What a restart must not lose is the time. Without a stamp on the row, a
// provisioning runner whose create was issued twenty minutes ago and one whose
// create went out a second ago are the same row, and the operator reading the
// page -- or a controller that has just come back -- has no way to tell how
// long this runner has actually been waiting on its host.
func TestIssuingARunnersTaskIsRecordedOnItsRow(t *testing.T) {
	h := newHarness(t)
	_, _, host := h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9101, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatalf("Reconcile: %v", err)
	}
	h.c.lifecycleCalls.Wait()

	r := h.onlyRunner()
	if r.TaskIssuedAt == nil {
		t.Fatal("task_issued_at is unset after the create was queued; the row cannot say when its host was asked")
	}
	first := *r.TaskIssuedAt

	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks: %v, %d tasks", err, len(batch.Tasks))
	}
	after := h.onlyRunner()
	if after.TaskIssuedAt == nil || after.TaskIssuedAt.Before(first) {
		t.Fatalf("task_issued_at = %v after the poll, want it at or after the enqueue stamp %v", after.TaskIssuedAt, first)
	}
}

// The redelivery half. A create whose lease expires is offered again, and the
// second offer is the one that matters: counting the provision timeout from
// the first would fail a runner whose host only just received the work.
func TestRedeliveringATaskMovesTheRunnersIssueStampForward(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)

	task := agent.Task{Kind: agent.TaskCreateRunner, RunnerID: r.ID, Backend: pool.Backend}
	if !h.c.enqueueLifecycle(h.ctx, host.ID, task) {
		t.Fatal("the task was not queued")
	}
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}
	issued := h.runnerByID(t, r.ID).TaskIssuedAt
	if issued == nil {
		t.Fatal("task_issued_at is unset after the first delivery")
	}

	// Wind the clock past the create lease and sweep, which is what puts the
	// task back on the queue for a second attempt.
	h.advance(createLease + time.Minute)
	if requeued, _ := h.c.queues.get(host.ID).sweep(h.c.Now()); requeued != 1 {
		t.Fatalf("sweep re-queued %d tasks, want 1", requeued)
	}
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatalf("PollTasks: %v", err)
	}

	again := h.runnerByID(t, r.ID).TaskIssuedAt
	if again == nil {
		t.Fatal("task_issued_at is unset after the redelivery")
	}
	if !again.After(*issued) {
		t.Fatalf("task_issued_at = %v after redelivery, want it later than the first issue %v; "+
			"the provision timeout would be counted from an attempt the host never received", again, issued)
	}
}

// A log relay says nothing about whether a runner is progressing -- the
// container is where it was, doing what it was doing -- so it must not move a
// clock that decides whether the runner is written off.
func TestALogTaskDoesNotTouchTheRunnersIssueStamp(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)

	h.c.enqueueLifecycle(h.ctx, host.ID, agent.Task{
		Kind: agent.TaskStreamLogs, RunnerID: r.ID, StreamID: "stream_x",
	})
	if got := h.runnerByID(t, r.ID).TaskIssuedAt; got != nil {
		t.Fatalf("task_issued_at = %v after a log task, want it untouched", got)
	}
}

func TestFirstCreateDeliverySurvivesRetriesAndRemoval(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerProvisioning)
	h.c.enqueueLifecycle(h.ctx, host.ID, agent.Task{Kind: agent.TaskCreateRunner, RunnerID: r.ID})
	if h.runnerByID(t, r.ID).CreateTaskIssuedAt != nil {
		t.Fatal("enqueue was counted as delivery to the host")
	}
	h.advance(5 * time.Second)
	batch, err := h.c.PollTasks(h.ctx, host.ID, time.Second)
	if err != nil || len(batch.Tasks) != 1 {
		t.Fatalf("PollTasks: %v, batch: %+v", err, batch)
	}
	first := h.runnerByID(t, r.ID).CreateTaskIssuedAt
	if first == nil || !first.Equal(batch.Tasks[0].IssuedAt.Truncate(time.Millisecond)) {
		t.Fatalf("first delivery = %v, want %v", first, batch.Tasks[0].IssuedAt)
	}
	for _, kind := range []agent.TaskKind{agent.TaskCreateRunner, agent.TaskStopRunner, agent.TaskRemoveRunner} {
		h.advance(time.Minute)
		issued := h.c.Now()
		h.c.stampIssued(h.ctx, []agent.Task{{Kind: kind, RunnerID: r.ID, IssuedAt: issued}})
		got := h.runnerByID(t, r.ID)
		if got.CreateTaskIssuedAt == nil || !got.CreateTaskIssuedAt.Equal(*first) {
			t.Fatalf("%s overwrote the first create delivery: %v", kind, got.CreateTaskIssuedAt)
		}
		if got.TaskIssuedAt == nil || !got.TaskIssuedAt.Equal(issued.Truncate(time.Millisecond)) {
			t.Fatal("the retry clock must still advance independently")
		}
	}
}

package controller

import (
	"context"
	"errors"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// The throttle is decided in the scheduler (NextThrottle, pure) and applied
// here, from two places: every heartbeat, which is where a fresh measurement
// arrives, and the housekeeping pass, which is what lifts a throttle whose
// host has stopped sending measurements at all. Both go through settleThrottle
// so that a step is persisted, logged, audited and published in exactly one
// way -- a rung the Hosts page showed and the audit trail did not would be a
// decision nobody could account for afterwards.

// settleThrottle runs the ladder for one host as it stands now and records
// whatever moved. It reports whether the rung changed.
//
// h is updated in place, so a caller that goes on to render or answer with
// the host sees the rung it is actually on. A change that moves no rung -- a
// calm streak starting -- is persisted and published but neither logged nor
// audited: the streak is bookkeeping for the next step down, and a log line
// per heartbeat about a host that is merely recovering would bury the lines
// about the ones that are not.
func (c *Controller) settleThrottle(ctx context.Context, h *store.Host, now time.Time) bool {
	next := scheduler.NextThrottle(h, now)
	if sameThrottle(next, h.Throttle) {
		return false
	}
	if err := c.st.SetHostThrottle(ctx, h.ID, next, h.Throttle.Level); err != nil {
		if errors.Is(err, store.ErrThrottleMoved) {
			// Somebody else decided first: a heartbeat racing the
			// housekeeping tick, or an operator's clear. Their decision
			// stands, and the next sample decides from it.
			c.log.Debug("a host's throttle was decided elsewhere first", "host", h.ID)
			return false
		}
		c.log.Warn("could not record a host's throttle; the next heartbeat will decide again", "host", h.ID, "error", err)
		return false
	}
	was := h.Throttle
	h.Throttle = next
	if next.Level == was.Level {
		c.publishHost(h)
		return false
	}
	c.recordThrottleStep(ctx, h, was, next, true)
	return true
}

// recordThrottleStep is the log line, the audit row, the event and the nudge
// for a rung that moved in either direction. audit is false for an operator's
// clear, whose caller writes the row itself under the operator's own name:
// a lift the ladder decided and a lift somebody asked for are two different
// facts, and an audit trail with both attributed to the system could not
// tell an operator which of their colleagues cleared a throttle early.
func (c *Controller) recordThrottleStep(ctx context.Context, h *store.Host, was, next store.HostThrottle, audit bool) {
	action := "host.throttle"
	switch {
	case next.Level > was.Level:
		c.log.Info("throttled a host after sustained pressure",
			"host", h.ID, "name", h.Name, "level", next.Level, "was", was.Level,
			"effective_capacity", h.EffectiveCapacity(), "capacity", h.Capacity,
			"cpu_factor", next.CPUFactor(), "reason", next.Reason)
	case next.Active():
		action = "host.throttle_lift"
		c.log.Info("lifted a host's throttle one step after a stretch of calm",
			"host", h.ID, "name", h.Name, "level", next.Level, "was", was.Level,
			"effective_capacity", h.EffectiveCapacity(), "capacity", h.Capacity)
	default:
		action = "host.throttle_lift"
		c.log.Info("lifted a host's throttle",
			"host", h.ID, "name", h.Name, "was", was.Level, "capacity", h.Capacity)
	}
	if audit {
		c.authsvc.Auditor().Act(ctx, auth.SystemIdentity(), action, "host", h.ID, map[string]any{
			"level":              next.Level,
			"reason":             firstNonEmpty(next.Reason, was.Reason),
			"effective_capacity": h.EffectiveCapacity(),
		})
	}
	// The slots the host offers just changed, and both the Hosts page and the
	// next pass have to know: a lift is room a queued job may be waiting for.
	c.publishHost(h)
	c.Nudge()
}

// settleThrottles is the housekeeping half: every host on a rung is run
// through the ladder, so that a host whose agent stopped sending measurements
// -- downgraded, or gone -- is lifted after StaleThrottleReset rather than
// staying throttled for as long as nobody heartbeats. A host with no throttle
// needs nothing here; the heartbeat that could put it on a rung runs the
// ladder itself.
//
// Throttling switched off at runtime is also settled here, by lifting every
// throttle that stands: the heartbeat path stops deciding when the setting is
// off, and a rung nothing will ever step down from again is a cordon nobody
// applied.
func (c *Controller) settleThrottles(ctx context.Context, now time.Time) {
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		c.log.Warn("could not list hosts to settle their throttles", "error", err)
		return
	}
	enabled := c.cfg().Scheduler.HostThrottling
	for _, h := range hosts {
		if !h.Throttle.Active() {
			continue
		}
		// The demo fleet's hosts are left alone, as they are everywhere else
		// in housekeeping: its throttled host is a fixture, on a rung so the
		// UI can be looked at with one, and it would otherwise lift itself
		// the moment its seeded measurement went stale.
		if IsDemoID(h.ID) {
			continue
		}
		if !enabled {
			c.log.Info("lifting a host's throttle because scheduler.host_throttling is off", "host", h.ID, "name", h.Name)
			if _, err := c.clearThrottle(ctx, h, true); err != nil {
				c.log.Warn("could not lift a host's throttle", "host", h.ID, "error", err)
			}
			continue
		}
		// A host with a fresh sample is being decided by its heartbeats, and
		// housekeeping has nothing to add but a second decider racing the
		// first. This pass is for the host that has stopped sending samples.
		if h.Usage.Fresh(now) {
			continue
		}
		c.settleThrottle(ctx, h, now)
	}
}

// ClearHostThrottle lifts a host's throttle by hand, whatever rung it is on.
//
// It is the operator's way out once the cause is fixed -- a pool given the
// limits it lacked, a capacity lowered to what the machine can carry --
// without waiting out the recovery the ladder would otherwise ask for. The
// caller audits, because it knows who asked; this writes nothing to the audit
// trail itself. It logs the lift, publishes the host and nudges a pass, since
// the slots it gives back are room a queued job may be waiting on. A host
// that is not throttled is returned unchanged.
//
// Nothing pins a throttle the other way: if the pressure is still there, the
// next heartbeat puts the host back on the first rung, which is the honest
// answer to a clear that was premature.
func (c *Controller) ClearHostThrottle(ctx context.Context, id string) (*store.Host, error) {
	h, err := c.st.GetHost(ctx, id)
	if err != nil {
		return nil, err
	}
	return c.clearThrottle(ctx, h, false)
}

func (c *Controller) clearThrottle(ctx context.Context, h *store.Host, audit bool) (*store.Host, error) {
	if !h.Throttle.Active() {
		return h, nil
	}
	if err := c.st.SetHostThrottle(ctx, h.ID, store.HostThrottle{}, h.Throttle.Level); err != nil {
		if errors.Is(err, store.ErrThrottleMoved) {
			// The rung moved between the read and the clear. Read it again
			// and clear from where it is now: a clear is an instruction
			// about the host, not about the rung it happened to be on.
			fresh, rerr := c.st.GetHost(ctx, h.ID)
			if rerr != nil {
				return nil, rerr
			}
			return c.clearThrottle(ctx, fresh, audit)
		}
		return nil, err
	}
	was := h.Throttle
	h.Throttle = store.HostThrottle{}
	c.recordThrottleStep(ctx, h, was, h.Throttle, audit)
	return h, nil
}

// throttleDirective is what a heartbeat answers about the host's rung. It is
// always sent, level 0 and factor 1 included: an agent that was told to run
// its runners at half their quota has to be told when to stop, and "no field"
// from a controller too old to send one already means "no throttle".
func throttleDirective(h *store.Host) *agent.ThrottleDirective {
	return &agent.ThrottleDirective{Level: h.Throttle.Level, CPUFactor: h.Throttle.CPUFactor()}
}

// sameThrottle reports whether two rungs are the same row: the ladder returns
// a fresh value on every call, and only a value that differs is worth a write.
func sameThrottle(a, b store.HostThrottle) bool {
	return a.Level == b.Level && a.Reason == b.Reason &&
		sameInstant(a.Since, b.Since) && sameInstant(a.ChangedAt, b.ChangedAt) && sameInstant(a.CalmSince, b.CalmSince)
}

func sameInstant(a, b *time.Time) bool {
	if a == nil || b == nil {
		return a == b
	}
	return a.Equal(*b)
}

package controller

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// throttleFixture is a joined host and the means to heartbeat it with a
// measurement, which is the only way a throttle is ever decided.
type throttleFixture struct {
	h      *harness
	tr     agent.Transport
	hostID string
	cpu    float64
	load   float64
	memory int64
}

func newThrottleFixture(t *testing.T) *throttleFixture {
	t.Helper()
	h := newHarness(t)
	tr := h.c.EmbeddedTransport()
	joined, err := tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "pressed", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true, Limits: enforcesEverything}}})
	if err != nil {
		t.Fatal(err)
	}
	tr.SetCredentials(joined.HostID, joined.AgentToken)
	// Calm to begin with: CPU well under the bar, one runnable task per two
	// cores, half the memory free.
	return &throttleFixture{h: h, tr: tr, hostID: joined.HostID, cpu: 30, load: 4, memory: 8192}
}

// beat sends the fixture's current measurement and returns the answer and
// the host as the store now has it.
func (f *throttleFixture) beat(t *testing.T) (*agent.HeartbeatResponse, *store.Host) {
	t.Helper()
	cpu, load, memory := f.cpu, f.load, f.memory
	resp, err := f.tr.Heartbeat(f.h.ctx, agent.HeartbeatRequest{Usage: &store.HostUsage{
		CPUPercent: &cpu, LoadAverage1: &load, MemoryAvailableMB: &memory}})
	if err != nil {
		t.Fatal(err)
	}
	host, err := f.h.st.GetHost(f.h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	return resp, host
}

func (f *throttleFixture) audits(t *testing.T, action string) int {
	t.Helper()
	rows, _, err := f.h.st.ListAudit(f.h.ctx, store.AuditFilter{Actions: []string{action}, TargetID: f.hostID}, store.Page{Limit: 50})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	return len(rows)
}

// A host whose load average has run past twice its cores is a host being
// pushed harder than it can go, and the pressure holds alone would only
// bounce it in and out of admission. The ladder takes a quarter of its slots
// and tells its agent to run the jobs at three quarters of their quota, and
// every surface an operator reads -- the row, the view, the problems drawer,
// the audit trail, the metrics -- says the same thing about it.
func TestASustainedLoadAverageThrottlesAHost(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	resp, host := f.beat(t)

	if resp.Throttle == nil || resp.Throttle.Level != 1 || resp.Throttle.CPUFactor != 0.75 {
		t.Fatalf("heartbeat answered %+v, want the agent told about rung 1 at three quarters", resp.Throttle)
	}
	if host.Throttle.Level != 1 || host.EffectiveCapacity() != 3 || host.Throttle.Since == nil {
		t.Fatalf("host row = %+v with effective capacity %d, want rung 1 of 4 slots leaving 3", host.Throttle, host.EffectiveCapacity())
	}
	view := h.c.HostView(host)
	if view.Throttle == nil || view.Throttle.Level != 1 || view.EffectiveCapacity != 3 || view.Free != 3 ||
		!strings.Contains(view.ThrottleReason, "load average is 20.0") {
		t.Fatalf("host view = throttle %+v, effective %d, free %d, reason %q", view.Throttle, view.EffectiveCapacity, view.Free, view.ThrottleReason)
	}
	p := h.problem(t, "host.throttled")
	if p.Severity != config.SeverityWarning || !strings.Contains(p.Detail, "pressed") || !strings.Contains(p.Detail, "3 of 4 slots") {
		t.Fatalf("host.throttled = %+v; it has to name the host and what it was stepped down to", p)
	}
	if f.audits(t, "host.throttle") != 1 {
		t.Fatalf("host.throttle audit rows = %d, want 1", f.audits(t, "host.throttle"))
	}
	for name, want := range map[string]float64{
		"zoomies_host_throttle_level":     1,
		"zoomies_host_load_average_1m":    20,
		"zoomies_host_effective_capacity": 3,
		"zoomies_host_capacity":           4,
	} {
		labels := map[string]string{}
		if strings.HasSuffix(name, "_level") || strings.HasSuffix(name, "_1m") {
			labels["host"] = host.ID
		}
		if got, ok := gatherValue(t, h.c, name, labels); !ok || got != want {
			t.Errorf("%s = %v (%v), want %v", name, got, ok, want)
		}
	}
	stats, err := h.c.Stats(h.ctx, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if stats.Hosts.Capacity != 3 {
		t.Errorf("Stats.Hosts.Capacity = %d, want the 3 slots the throttle leaves rather than the 4 configured", stats.Hosts.Capacity)
	}
	pool := h.pool(h.installation(), "linux-x64")
	if got := eligibleCapacity(pool, []*store.Host{host}, h.c.Now()); got != 3 {
		t.Errorf("capacity-demand eligible capacity = %d, want 3; a provisioner told 4 would never be asked for the slot the queue is short of", got)
	}

	// The next rung waits for ThrottleStep, because a quota lowered on a
	// live container takes a while to show in a load average that itself
	// averages over a minute.
	if resp, _ := f.beat(t); resp.Throttle.Level != 1 {
		t.Fatalf("a second overwhelmed beat inside ThrottleStep moved the rung to %d", resp.Throttle.Level)
	}
	h.advance(scheduler.ThrottleStep)
	resp, host = f.beat(t)
	if resp.Throttle.Level != 2 || resp.Throttle.CPUFactor != 0.5 || host.EffectiveCapacity() != 2 {
		t.Fatalf("after ThrottleStep: %+v, effective %d; want rung 2 at half quota leaving 2 slots", resp.Throttle, host.EffectiveCapacity())
	}
}

// A throttle comes off one rung at a time, and only after a stretch of calm
// long enough to mean something: a host that recovered for a minute and was
// pushed straight back over would otherwise oscillate with the ladder. The
// step down is audited as a lift, so the trail reads as a pair.
func TestAThrottleLiftsOneStepAfterCalm(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	f.beat(t)
	h.advance(scheduler.ThrottleStep)
	if _, host := f.beat(t); host.Throttle.Level != 2 {
		t.Fatalf("setup: level %d, want 2", host.Throttle.Level)
	}

	f.load = 2
	_, host := f.beat(t)
	if host.Throttle.Level != 2 || host.Throttle.CalmSince == nil {
		t.Fatalf("one calm beat: %+v; want the rung kept and the calm streak started", host.Throttle)
	}
	h.advance(scheduler.ThrottleRecovery / 2)
	if _, host := f.beat(t); host.Throttle.Level != 2 {
		t.Fatalf("half a recovery of calm already stepped the host down to %d", host.Throttle.Level)
	}
	h.advance(scheduler.ThrottleRecovery / 2)
	resp, host := f.beat(t)
	if host.Throttle.Level != 1 || resp.Throttle.Level != 1 || resp.Throttle.CPUFactor != 0.75 {
		t.Fatalf("after ThrottleRecovery of calm: row %+v, answer %+v; want rung 1", host.Throttle, resp.Throttle)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1", f.audits(t, "host.throttle_lift"))
	}
	h.advance(scheduler.ThrottleRecovery)
	resp, host = f.beat(t)
	if host.Throttle.Active() || resp.Throttle.Level != 0 || resp.Throttle.CPUFactor != 1 {
		t.Fatalf("after a second recovery: row %+v, answer %+v; want no throttle and the agent told to restore every quota", host.Throttle, resp.Throttle)
	}
	if h.c.HostView(host).Throttle != nil || contains(h.problemCodes(), "host.throttled") {
		t.Fatal("a lifted throttle is still on the view or in the problems drawer")
	}
}

// An operator who has fixed the cause -- a pool given limits, a capacity
// lowered -- should not have to wait out the recovery. The clear lifts every
// rung at once, publishes the host, and writes no audit row of its own: the
// API records who asked, and a system row beside it would say the ladder
// decided something a person did.
func TestAnOperatorCanClearAThrottle(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	f.beat(t)
	h.advance(scheduler.ThrottleStep)
	f.beat(t)

	// Drain the nudge the heartbeats left, so the one below is the clear's.
	select {
	case <-h.c.nudges:
	default:
	}
	host, err := h.c.ClearHostThrottle(h.ctx, f.hostID)
	if err != nil {
		t.Fatalf("ClearHostThrottle: %v", err)
	}
	if host.Throttle.Active() || host.EffectiveCapacity() != 4 {
		t.Fatalf("cleared host = %+v with effective capacity %d", host.Throttle, host.EffectiveCapacity())
	}
	stored, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if stored.Throttle.Active() {
		t.Fatal("the clear was not persisted")
	}
	if f.audits(t, "host.throttle_lift") != 0 || f.audits(t, "host.throttle_clear") != 0 {
		t.Fatal("ClearHostThrottle wrote an audit row; that is the caller's, under the operator's name")
	}
	if len(h.c.nudges) != 1 {
		t.Fatal("the clear did not nudge a pass; the slots it gave back would wait for the interval")
	}

	// Nothing pins it: the pressure is still there, so the next beat puts
	// the host straight back on the first rung.
	if resp, _ := f.beat(t); resp.Throttle.Level != 1 {
		t.Fatalf("after a premature clear the next beat answered %+v, want rung 1 again", resp.Throttle)
	}
	// And an unthrottled host is returned unchanged rather than refused.
	if _, err := h.c.ClearHostThrottle(h.ctx, f.hostID); err != nil {
		t.Fatalf("clearing again: %v", err)
	}
}

// A host whose agent stopped sending measurements -- downgraded to a build
// without them, or gone -- must not stay throttled for as long as nobody
// heartbeats. Housekeeping runs the ladder for it, and the ladder lifts a
// throttle its measurements have been stale on for StaleThrottleReset.
func TestHousekeepingLiftsAThrottleWhoseHostStoppedMeasuring(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	if _, host := f.beat(t); host.Throttle.Level != 1 {
		t.Fatalf("setup: %+v", host.Throttle)
	}

	h.advance(scheduler.StaleThrottleReset - time.Second)
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if !host.Throttle.Active() {
		t.Fatal("a stale sample lifted the throttle before StaleThrottleReset; a host that merely missed a few beats would be handed its slots back")
	}
	h.advance(2 * time.Second)
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err = h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("after StaleThrottleReset the host is still on rung %d", host.Throttle.Level)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1 for the stale reset", f.audits(t, "host.throttle_lift"))
	}
}

// scheduler.host_throttling off means no host is ever put on a rung, and a
// host already on one when the setting is turned off is lifted rather than
// left there for ever with nothing to step it down.
func TestThrottlingOffDecidesNothingAndLiftsWhatStands(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	h.c.UpdateConfig(func(cfg *config.Config) { cfg.Scheduler.HostThrottling = false })
	f.load = 20
	resp, host := f.beat(t)
	if host.Throttle.Active() || resp.Throttle == nil || resp.Throttle.Level != 0 || resp.Throttle.CPUFactor != 1 {
		t.Fatalf("with throttling off: row %+v, answer %+v; want no rung and the agent still told so", host.Throttle, resp.Throttle)
	}

	// A rung left over from before the setting was turned off.
	now := h.c.Now()
	if err := h.st.SetHostThrottle(h.ctx, f.hostID, store.HostThrottle{Level: 2, Since: &now, ChangedAt: &now, Reason: "earlier"}, 0); err != nil {
		t.Fatal(err)
	}
	h.c.settleThrottles(h.ctx, h.c.Now())
	host, err := h.st.GetHost(h.ctx, f.hostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("housekeeping left a host on rung %d with throttling off", host.Throttle.Level)
	}
	if f.audits(t, "host.throttle_lift") != 1 {
		t.Fatalf("host.throttle_lift audit rows = %d, want 1", f.audits(t, "host.throttle_lift"))
	}
}

// A host that joins again starts on no rung: the throttle was decided from
// measurements of a machine that has just been rebuilt or restarted. If the
// pressure is still there its first heartbeats put it straight back.
func TestARejoiningHostStartsOnNoRung(t *testing.T) {
	f := newThrottleFixture(t)
	h := f.h
	f.load = 20
	if _, host := f.beat(t); !host.Throttle.Active() {
		t.Fatal("setup: not throttled")
	}
	joined, err := f.tr.Join(h.ctx, agent.JoinRequest{ProtocolVersion: agent.ProtocolVersion,
		Name: "pressed", Capacity: 4, CPUs: 8, MemoryMB: 16384,
		Backends: []backend.Info{{Kind: store.BackendDocker, Available: true, Limits: enforcesEverything}}})
	if err != nil {
		t.Fatal(err)
	}
	host, err := h.st.GetHost(h.ctx, joined.HostID)
	if err != nil {
		t.Fatal(err)
	}
	if host.Throttle.Active() {
		t.Fatalf("a re-joined host is still on rung %d", host.Throttle.Level)
	}
}

// The reason a host takes no new runner used to fall through to "upgrade its
// agent" for every case the sentence had no words for, so a host held for
// pressure or throttled to its last slot was told to upgrade. Each is its own
// job and gets its own sentence.
func TestUnavailableReasonNamesAHoldAndAThrottle(t *testing.T) {
	now := time.Now()
	fresh := now.Add(-time.Second)
	held := &store.Host{Name: "held", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		Usage: store.HostUsage{SampledAt: fresh, CPUHeld: true}}
	throttled := &store.Host{Name: "throttled", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		ActiveRunners: 2, Throttle: store.HostThrottle{Level: 2}}
	roomy := &store.Host{Name: "roomy", Capacity: 4, CPUs: 8, MemoryMB: 16384, LastHeartbeat: now,
		ActiveRunners: 1, Throttle: store.HostThrottle{Level: 2}}
	old := &store.Host{Name: "old", Capacity: 4, LastHeartbeat: now, Incompatible: true}
	for _, tc := range []struct {
		host *store.Host
		want string
	}{
		{held, "under pressure"},
		{throttled, "throttled to 2 of its 4 slots"},
		{old, "protocol"},
		// A throttled host with a slot free is not unavailable at all; the
		// sentence for it is the last resort, never the upgrade advice.
		{roomy, "takes no new runners right now"},
	} {
		if got := unavailableReason(tc.host, now); !strings.Contains(got, tc.want) {
			t.Errorf("%s: reason %q does not say %q", tc.host.Name, got, tc.want)
		}
	}
	if !roomy.Available(now) {
		t.Error("a throttled host with a slot left under its effective capacity should still be available")
	}
	if throttled.Available(now) {
		t.Error("a throttled host at its effective capacity should not be available")
	}
}

package controller

import (
	"context"

	"github.com/eyupio/zoomies/internal/store"
)

func (c *Controller) confirmCleanup(ctx context.Context, id string, host bool) error {
	completed, err := c.st.ConfirmRunnerCleanup(ctx, id, host)
	if err != nil {
		c.log.Warn("could not record confirmed cleanup", "runner", id, "host_confirmation", host, "error", err)
		return err
	}
	r, err := c.st.GetRunner(ctx, id)
	if err != nil {
		return err
	}
	if completed && r.FinishedAt != nil && r.CleanedUpAt != nil {
		if p, err := c.st.GetPool(ctx, r.PoolID); err == nil && !IsDemoID(p.InstallationID) {
			observeDuration(c.metrics.cleanupDuration, p.Name, string(p.Backend), *r.FinishedAt, *r.CleanedUpAt)
		}
	}
	c.publishRunnerByID(ctx, id)
	return nil
}

// Observe the job's actual runner once the association is known, not the
// first queued job found when any runner in its pool was created. Prewarmed
// runners and jobs whose eligibility was never observed have no sample.
func (c *Controller) observeScheduling(ctx context.Context, j *store.Job, change store.JobChange, r *store.Runner) {
	firstStart := (j.State == store.JobInProgress || j.State == store.JobCompleted) &&
		(change.RunnerLinked || ((change.Created || change.StateChanged) &&
			change.PreviousState != store.JobInProgress && change.PreviousState != store.JobCompleted))
	if !firstStart || j.EligibleAt == nil || j.RunnerID == "" || IsDemoID(j.InstallationID) {
		return
	}
	if r == nil {
		var err error
		r, err = c.st.GetRunner(ctx, j.RunnerID)
		if err != nil {
			return
		}
	}
	if r.CreateTaskIssuedAt == nil {
		return
	}
	if p, err := c.st.GetPool(ctx, r.PoolID); err == nil && p.InstallationID == j.InstallationID {
		observeDuration(c.metrics.schedulingLatency, p.Name, string(p.Backend), *j.EligibleAt, *r.CreateTaskIssuedAt)
	}
}

package controller

import (
	"context"
	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	dto "github.com/prometheus/client_model/go"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/store"
)

func timingSample(t *testing.T, h *prometheus.HistogramVec, pool, backend string) (uint64, float64) {
	t.Helper()
	var m dto.Metric
	if err := h.WithLabelValues(pool, backend).(prometheus.Metric).Write(&m); err != nil {
		t.Fatal(err)
	}
	return m.GetHistogram().GetSampleCount(), m.GetHistogram().GetSampleSum()
}

func TestSchedulingTimingUsesTheJobsActualRunnerOnce(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	h.deliverJob(jobEvent{Action: "queued", JobID: 9201, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	if err := h.c.Reconcile(h.ctx); err != nil {
		t.Fatal(err)
	}
	h.advance(5 * time.Second)
	if _, err := h.c.PollTasks(h.ctx, host.ID, time.Second); err != nil {
		t.Fatal(err)
	}
	r := h.onlyRunner()
	first := *r.CreateTaskIssuedAt
	h.advance(time.Minute)
	h.c.stampIssued(h.ctx, []agent.Task{{Kind: agent.TaskCreateRunner, RunnerID: r.ID, IssuedAt: h.c.Now()}})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9201, RunnerName: r.Name, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	h.deliverJob(jobEvent{Action: "in_progress", JobID: 9201, RunnerName: r.Name, Labels: []string{"self-hosted", "linux", "x64", "demo"}})
	jobs, _, err := h.st.ListJobs(h.ctx, store.JobFilter{}, store.Page{})
	if err != nil || len(jobs) != 1 || jobs[0].EligibleAt == nil {
		t.Fatalf("job eligibility: %+v, %v", jobs, err)
	}
	count, sum := timingSample(t, h.c.metrics.schedulingLatency, pool.Name, string(pool.Backend))
	if count != 1 || sum != first.Sub(*jobs[0].EligibleAt).Seconds() {
		t.Fatalf("scheduling histogram = %d samples, %v seconds; want one first-delivery interval", count, sum)
	}
}

func TestCleanupMetricWaitsForBothSidesAndDoesNotCountRetries(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerIdle)
	if _, err := h.st.TransitionRunner(h.ctx, r.ID, store.RunnerRemoved, "finished"); err != nil {
		t.Fatal(err)
	}
	h.c.confirmCleanup(h.ctx, r.ID, false)
	if count, _ := timingSample(t, h.c.metrics.cleanupDuration, pool.Name, string(pool.Backend)); count != 0 {
		t.Fatal("registration removal alone produced a cleanup timing")
	}
	h.advance(2 * time.Minute)
	h.c.confirmCleanup(h.ctx, r.ID, true)
	h.c.confirmCleanup(h.ctx, r.ID, true)
	h.c.confirmCleanup(h.ctx, r.ID, false)
	count, sum := timingSample(t, h.c.metrics.cleanupDuration, pool.Name, string(pool.Backend))
	finished := h.runnerByID(t, r.ID)
	want := finished.CleanedUpAt.Sub(*finished.FinishedAt).Seconds()
	if count != 1 || sum != want {
		t.Fatalf("cleanup histogram = %d samples, %v seconds; want one confirmed interval of %v seconds", count, sum, want)
	}
}

func TestCleanupReportsAreNotAcknowledgedWhenTheStoreCannotBeRead(t *testing.T) {
	h := newHarness(t)
	_, pool, host := h.fleet()
	r := h.runnerRow(pool, host, store.RunnerRemoved)
	report := agent.RunnerReport{RunnerID: r.ID, State: store.RunnerRemoved, HostRemoved: true}
	ctx, cancel := context.WithCancel(h.ctx)
	cancel()
	if err := h.c.ReportRunners(ctx, host.ID, []agent.RunnerReport{report}); err == nil {
		t.Fatal("a failed database read acknowledged the cleanup receipt")
	}
	if err := h.c.ReportRunners(h.ctx, host.ID, []agent.RunnerReport{report}); err != nil {
		t.Fatal(err)
	}
	if h.runnerByID(t, r.ID).HostRemovedAt == nil {
		t.Fatal("the retried receipt was not stored")
	}
}

package controller

import (
	"context"
	"errors"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/toolscan"
)

// A toolchain scan reads every workflow every installation can see and says,
// per pool, which setup-python, setup-node, setup-go, setup-java and
// setup-dotnet versions its jobs will ask for. It is what lets a pool's cache
// be filled with those versions before the jobs arrive, rather than each
// ephemeral runner downloading them again.
//
// The result lives in memory. It is a reading of GitHub that the next scan
// replaces, not fleet state: nothing schedules from it, and a controller that
// restarts without it has lost a cache hint, not a record. Keeping it out of
// the store also keeps a scan -- the most GitHub-expensive thing the
// controller does on its own initiative -- from contending with the one
// writer.

// ToolchainDemand is one toolchain version a pool's jobs ask for.
type ToolchainDemand struct {
	Tool         string `json:"tool"`
	Version      string `json:"version,omitempty"`
	Distribution string `json:"distribution,omitempty"`
	// Unresolved says why the version is not known from the workflows; see
	// toolscan.Requirement.
	Unresolved string `json:"unresolved,omitempty"`
	// Jobs is how many workflow jobs ask for it, counting each matrix
	// combination once, and Repositories which repositories they are in.
	Jobs         int      `json:"jobs"`
	Repositories []string `json:"repositories"`
}

// ToolchainScanInstallation is how the scan went for one installation.
type ToolchainScanInstallation struct {
	InstallationID string `json:"installation_id"`
	Target         string `json:"target"`
	Repositories   int    `json:"repositories"`
	Workflows      int    `json:"workflows"`
	// Error is why this installation was not read, or only partly: GitHub
	// refusing it, a rate-limit hold, or an App without the Contents
	// permission, whose every repository would otherwise look empty.
	Error string `json:"error,omitempty"`
	// Unreadable lists repositories GitHub would not give up workflows for,
	// with the reason.
	Unreadable map[string]string `json:"unreadable,omitempty"`
}

// ToolchainScan is the latest scan.
type ToolchainScan struct {
	Running    bool       `json:"running"`
	StartedAt  *time.Time `json:"started_at,omitempty"`
	FinishedAt *time.Time `json:"finished_at,omitempty"`
	// Pools maps a pool ID to what its jobs ask for.
	Pools map[string][]ToolchainDemand `json:"pools"`
	// Unmatched is what jobs ask for that no pool would run: jobs on
	// GitHub-hosted labels, on labels no pool carries, or on labels an
	// expression chooses.
	Unmatched     []ToolchainDemand           `json:"unmatched"`
	Installations []ToolchainScanInstallation `json:"installations"`
	// Fills maps a pool ID to its tool cache's latest fill on each host,
	// for the pools that keep one; see toolfill.go.
	Fills map[string][]ToolCacheFill `json:"fills"`
}

// scannedRequirement is one requirement and the repository it was found in.
type scannedRequirement struct {
	installationID string
	repo           string
	req            toolscan.Requirement
}

// toolchainScans holds the latest scan and whether one is running.
type toolchainScans struct {
	mu      sync.Mutex
	running bool
	latest  ToolchainScan
	// fills is pool ID to host ID to that host's latest fill.
	fills map[string]map[string]ToolCacheFill
}

// ErrToolchainScanRunning is returned when a scan is asked for while one is
// already under way; the running one's result is the answer.
var ErrToolchainScanRunning = errors.New("a toolchain scan is already running")

// ToolchainScanResult returns the latest scan, and whether one is running.
func (c *Controller) ToolchainScanResult() ToolchainScan {
	c.toolchains.mu.Lock()
	defer c.toolchains.mu.Unlock()
	out := c.toolchains.latest
	out.Running = c.toolchains.running
	if out.Pools == nil {
		out.Pools = map[string][]ToolchainDemand{}
	}
	if out.Unmatched == nil {
		out.Unmatched = []ToolchainDemand{}
	}
	if out.Installations == nil {
		out.Installations = []ToolchainScanInstallation{}
	}
	out.Fills = c.toolFillsByPool()
	return out
}

// StartToolchainScan begins a scan in the background and returns at once. A
// scan reads every workflow file in every repository, which on a large
// organisation is minutes of GitHub calls: far longer than a request should
// hold a connection open, so the scan is detached from the request.
func (c *Controller) StartToolchainScan(ctx context.Context) error {
	return c.startToolchainScan(ctx, true)
}

// startToolchainScan runs a scan in the background, on ctx or detached from it.
func (c *Controller) startToolchainScan(ctx context.Context, detach bool) error {
	c.toolchains.mu.Lock()
	if c.toolchains.running {
		c.toolchains.mu.Unlock()
		return ErrToolchainScanRunning
	}
	c.toolchains.running = true
	c.toolchains.mu.Unlock()

	if detach {
		ctx = context.WithoutCancel(ctx)
	}
	go func() {
		scan := c.scanToolchains(ctx)
		c.toolchains.mu.Lock()
		c.toolchains.latest = scan
		c.toolchains.running = false
		c.toolchains.mu.Unlock()
		// What the scan found is what the pools' caches are filled with,
		// so every scan -- scheduled or asked for -- is followed by a fill.
		c.fillToolCaches(ctx, scan)
	}()
	return nil
}

// scanToolchains is one scan, start to finish.
func (c *Controller) scanToolchains(ctx context.Context) ToolchainScan {
	started := c.Now()
	scan := ToolchainScan{StartedAt: &started}

	var found []scannedRequirement
	insts, err := c.st.ListInstallations(ctx)
	if err != nil {
		c.log.Warn("could not list installations to scan their workflows", "error", err)
	}
	for _, inst := range insts {
		if ctx.Err() != nil {
			break
		}
		if IsDemoID(inst.ID) {
			continue
		}
		report, reqs := c.scanInstallation(ctx, inst)
		scan.Installations = append(scan.Installations, report)
		found = append(found, reqs...)
	}

	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools to match scanned workflows against", "error", err)
	}
	scan.Pools, scan.Unmatched = aggregateToolchains(pools, found)
	finished := c.Now()
	scan.FinishedAt = &finished
	c.log.Info("scanned workflows for the toolchains they install",
		"installations", len(scan.Installations), "pools", len(scan.Pools),
		"took", finished.Sub(started).Round(time.Second))
	return scan
}

// scanInstallation reads one installation's workflows.
func (c *Controller) scanInstallation(ctx context.Context, inst *store.Installation) (ToolchainScanInstallation, []scannedRequirement) {
	report := ToolchainScanInstallation{InstallationID: inst.ID, Target: inst.Target}
	now := c.Now()
	if c.githubHeld(inst.ID, now) {
		report.Error = "GitHub is rate-limiting this installation; it will be read on the next scan"
		return report, nil
	}
	client, err := c.clients.get(ctx, inst)
	if err != nil {
		report.Error = err.Error()
		return report, nil
	}
	// The same question the migration wizard asks first, for the same
	// reason: GitHub answers an App without Contents with a 404, exactly as
	// it answers a repository with no workflows, so without asking every
	// repository would read as needing nothing.
	if info, err := client.Probe(ctx); err == nil && !info.CanReadContents() {
		report.Error = "the GitHub App cannot read repository contents, so no workflow can be read; grant it Contents: read on the installation"
		return report, nil
	}
	repos, err := client.ListRepositories(ctx, 0)
	c.observeGitHub(inst.ID, err)
	if err != nil {
		c.holdRateLimited(inst.ID, err, now, "scanning workflows for toolchains")
		report.Error = err.Error()
		return report, nil
	}
	report.Repositories = len(repos)

	var out []scannedRequirement
	for _, src := range readWorkflows(ctx, client, repos) {
		if src.err != "" {
			if report.Unreadable == nil {
				report.Unreadable = map[string]string{}
			}
			report.Unreadable[src.repo.FullName] = src.err
			continue
		}
		for _, wf := range src.workflows {
			report.Workflows++
			reqs, err := toolscan.Scan(wf.Path, wf.Content)
			if err != nil {
				// A workflow GitHub itself would refuse to run asks for
				// nothing; it is not worth failing the repository over.
				continue
			}
			for _, r := range reqs {
				out = append(out, scannedRequirement{installationID: inst.ID, repo: src.repo.FullName, req: r})
			}
		}
	}
	return report, out
}

// aggregateToolchains decides which pool would run each job and totals what
// each pool's jobs ask for. It is the scan without GitHub, which is what makes
// it testable.
//
// A job goes to the pool the scheduler would give it -- scheduler.BestPool, on
// the same labels and installation a queued job would carry -- so the answer
// here and the pool a real job lands on cannot disagree.
func aggregateToolchains(pools []*store.Pool, found []scannedRequirement) (map[string][]ToolchainDemand, []ToolchainDemand) {
	type key struct{ pool, tool, version, distribution, unresolved string }
	type tally struct {
		jobs  map[string]bool
		repos map[string]bool
	}
	tallies := map[key]*tally{}
	for _, f := range found {
		pool := ""
		if f.req.Labels != nil {
			job := &store.Job{Repo: f.repo, Labels: store.StringSlice(f.req.Labels), InstallationID: f.installationID}
			if p := scheduler.BestPool(pools, job); p != nil {
				pool = p.ID
			}
		}
		k := key{pool, string(f.req.Tool), f.req.Version, f.req.Distribution, f.req.Unresolved}
		t := tallies[k]
		if t == nil {
			t = &tally{jobs: map[string]bool{}, repos: map[string]bool{}}
			tallies[k] = t
		}
		// A job is its repository, file, key and labels: the same job with
		// two matrix combinations asking for one version counts once per
		// combination's labels, which is how many runners it takes.
		t.jobs[f.repo+"\x00"+f.req.Workflow+"\x00"+f.req.Job+"\x00"+strings.Join(f.req.Labels, ",")] = true
		t.repos[f.repo] = true
	}

	byPool := map[string][]ToolchainDemand{}
	var unmatched []ToolchainDemand
	for k, t := range tallies {
		repos := make([]string, 0, len(t.repos))
		for r := range t.repos {
			repos = append(repos, r)
		}
		sort.Strings(repos)
		d := ToolchainDemand{Tool: k.tool, Version: k.version, Distribution: k.distribution,
			Unresolved: k.unresolved, Jobs: len(t.jobs), Repositories: repos}
		if k.pool == "" {
			unmatched = append(unmatched, d)
		} else {
			byPool[k.pool] = append(byPool[k.pool], d)
		}
	}
	for id := range byPool {
		sortDemand(byPool[id])
	}
	sortDemand(unmatched)
	return byPool, unmatched
}

// sortDemand orders by tool, then the most-asked-for first, then version, so
// the list reads as "what matters most for each toolchain".
func sortDemand(ds []ToolchainDemand) {
	sort.Slice(ds, func(i, j int) bool {
		a, b := ds[i], ds[j]
		if a.Tool != b.Tool {
			return a.Tool < b.Tool
		}
		if a.Jobs != b.Jobs {
			return a.Jobs > b.Jobs
		}
		if a.Version != b.Version {
			return a.Version < b.Version
		}
		return a.Unresolved < b.Unresolved
	})
}

package controller

import (
	"errors"
	"reflect"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/toolscan"
)

// demandBrief renders what a pool's jobs ask for as "tool version xN" lines,
// which is what these tests compare.
func demandBrief(ds []ToolchainDemand) []string {
	var out []string
	for _, d := range ds {
		v := d.Version
		if d.Unresolved != "" {
			v = "? " + d.Unresolved
		}
		out = append(out, d.Tool+" "+v+" x"+strconv.Itoa(d.Jobs))
	}
	return out
}

// The pool a scanned job is counted against has to be the one the scheduler
// would give that job when it is queued -- otherwise the pool's cache is
// filled for jobs another pool runs.
func TestAggregateToolchainsGivesEachJobThePoolTheSchedulerWould(t *testing.T) {
	x64 := &store.Pool{ID: "pool_x64", Name: "x64", InstallationID: "ins_1", Enabled: true, Labels: []string{"linux", "x64"}}
	arm := &store.Pool{ID: "pool_arm", Name: "arm", InstallationID: "ins_1", Enabled: true, Labels: []string{"linux", "arm64"}}
	req := func(repo, job string, labels []string, tool toolscan.Tool, version string) scannedRequirement {
		return scannedRequirement{installationID: "ins_1", repo: repo,
			req: toolscan.Requirement{Workflow: ".github/workflows/ci.yml", Job: job, Labels: labels, Tool: tool, Version: version}}
	}
	found := []scannedRequirement{
		req("acme/a", "test", []string{"linux", "x64"}, toolscan.Python, "3.12"),
		req("acme/b", "test", []string{"linux", "x64"}, toolscan.Python, "3.12"),
		req("acme/b", "lint", []string{"linux", "x64"}, toolscan.Node, "22"),
		req("acme/a", "arm", []string{"linux", "arm64"}, toolscan.Go, "1.27"),
		req("acme/a", "hosted", []string{"ubuntu-latest"}, toolscan.Python, "3.13"),
		req("acme/a", "dynamic", nil, toolscan.Python, "3.11"),
	}
	pools, unmatched := aggregateToolchains([]*store.Pool{x64, arm}, found)

	if got, want := demandBrief(pools["pool_x64"]), []string{"node 22 x1", "python 3.12 x2"}; !reflect.DeepEqual(got, want) {
		t.Errorf("x64 pool: got %q, want %q", got, want)
	}
	if got := pools["pool_x64"][1].Repositories; !reflect.DeepEqual(got, []string{"acme/a", "acme/b"}) {
		t.Errorf("x64 python repositories = %q", got)
	}
	if got, want := demandBrief(pools["pool_arm"]), []string{"go 1.27 x1"}; !reflect.DeepEqual(got, want) {
		t.Errorf("arm pool: got %q, want %q", got, want)
	}
	// A hosted label no pool carries, and labels an expression chooses, are
	// not guessed onto a pool.
	if got, want := demandBrief(unmatched), []string{"python 3.11 x1", "python 3.13 x1"}; !reflect.DeepEqual(got, want) {
		t.Errorf("unmatched: got %q, want %q", got, want)
	}
}

func TestToolchainScanReadsTheWorkflowsOfEveryRepository(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", `
jobs:
  test:
    runs-on: zoomies-linux-x64
    strategy:
      matrix:
        python: ["3.12", "3.13"]
    steps:
      - uses: actions/setup-python@v6
        with:
          python-version: ${{ matrix.python }}
  hosted:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: "24"
`)
	h.gh.AddWorkflow("acme/gadgets", ".github/workflows/build.yml", `
jobs:
  build:
    runs-on: zoomies-linux-x64
    steps:
      - uses: actions/setup-go@v6
        with:
          go-version-file: go.mod
`)

	scan := h.c.scanToolchains(h.ctx)

	want := []string{"go ? read from go.mod in the repository x1", "python 3.12 x1", "python 3.13 x1"}
	if got := demandBrief(scan.Pools[pool.ID]); !reflect.DeepEqual(got, want) {
		t.Errorf("pool demand: got %q, want %q", got, want)
	}
	if got := demandBrief(scan.Unmatched); !reflect.DeepEqual(got, []string{"node 24 x1"}) {
		t.Errorf("unmatched: got %q", got)
	}
	if len(scan.Installations) != 1 || scan.Installations[0].Workflows != 2 || scan.Installations[0].Error != "" {
		t.Errorf("installation report = %+v", scan.Installations)
	}
	if scan.StartedAt == nil || scan.FinishedAt == nil {
		t.Error("a finished scan says when it ran")
	}
}

// GitHub answers an App without Contents exactly as it answers a repository
// with no workflows. Without asking first, the scan would report an
// organisation that needs nothing, when the truth is that it could not look.
func TestToolchainScanSaysWhenTheAppCannotReadWorkflows(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", "jobs: {}\n")
	h.gh.SetPermissions(map[string]string{"metadata": "read", "organization_self_hosted_runners": "write"})

	scan := h.c.scanToolchains(h.ctx)

	if len(scan.Installations) != 1 || scan.Installations[0].Error == "" {
		t.Fatalf("installation report = %+v, want an error naming the missing permission", scan.Installations)
	}
	if len(scan.Pools) != 0 {
		t.Errorf("pools = %+v, want nothing from an installation that was not read", scan.Pools)
	}
}

// A scan is minutes of GitHub calls on a large organisation; a second one
// started beside it would spend the same quota twice for the same answer.
func TestOnlyOneToolchainScanRunsAtATime(t *testing.T) {
	h := newHarness(t)
	h.c.toolchains.mu.Lock()
	h.c.toolchains.running = true
	h.c.toolchains.mu.Unlock()

	if err := h.c.StartToolchainScan(h.ctx); !errors.Is(err, ErrToolchainScanRunning) {
		t.Fatalf("StartToolchainScan = %v, want ErrToolchainScanRunning", err)
	}
	if !h.c.ToolchainScanResult().Running {
		t.Error("the result does not say a scan is running")
	}
}

// With an interval set, the background loop scans on its own; left at 0 it
// never spends the quota a scan costs unless somebody asks.
func TestHousekeepingScansToolchainsOnlyWhenAnIntervalIsSet(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	pool := h.pool(inst, "linux-x64", "zoomies-linux-x64")
	h.gh.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", `
jobs:
  test:
    runs-on: zoomies-linux-x64
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: "24"
`)

	h.c.live.Update(func(c *config.Config) { c.GitHub.ToolchainScanInterval = 0 })
	h.c.housekeep(h.ctx, &housekeeping{})
	if r := h.c.ToolchainScanResult(); r.Running || r.StartedAt != nil {
		t.Fatalf("a scan ran with the interval at 0: %+v", r)
	}

	h.c.live.Update(func(c *config.Config) { c.GitHub.ToolchainScanInterval = 24 * time.Hour })
	h.c.housekeep(h.ctx, &housekeeping{})
	deadline := time.Now().Add(10 * time.Second)
	for {
		r := h.c.ToolchainScanResult()
		if !r.Running && r.FinishedAt != nil {
			if got := demandBrief(r.Pools[pool.ID]); !reflect.DeepEqual(got, []string{"node 24 x1"}) {
				t.Fatalf("scheduled scan found %q", got)
			}
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("the scheduled scan did not finish")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

package controller

import (
	"context"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
)

// A finished toolchain scan is turned into work: every pool that keeps a tool
// cache is sent the versions its jobs ask for, to each host that could run
// it, and each host's agent fills its copy of that cache ahead of the jobs.
//
// Which fills ran, and how each went, lives beside the scan in memory, for
// the same reason the scan does: it describes a cache the next fill brings
// up to date, and losing it on a restart loses a report, not a record.

// maxToolFillRequests caps what one pool is sent. A pool whose jobs ask for
// forty versions between them wants the ones most of them ask for, not an
// hour of downloads on every host for the long tail.
const maxToolFillRequests = 12

// ToolCacheFill is one pool's fill on one host.
type ToolCacheFill struct {
	HostID   string `json:"host_id"`
	HostName string `json:"host_name"`
	// State is pending while the agent works, then succeeded or failed. A
	// fill that succeeded may still have skipped or failed requests; Tools
	// says which.
	State      string             `json:"state"`
	Requested  int                `json:"requested"`
	Tools      []backend.ToolFill `json:"tools"`
	Error      string             `json:"error,omitempty"`
	QueuedAt   time.Time          `json:"queued_at"`
	FinishedAt *time.Time         `json:"finished_at,omitempty"`
}

// fillToolCaches sends every pool that keeps a tool cache the versions scan
// found its jobs asking for, and returns how many fills it queued.
func (c *Controller) fillToolCaches(ctx context.Context, scan ToolchainScan) int {
	pools, err := c.st.ListPools(ctx)
	if err != nil {
		c.log.Warn("could not list pools to fill their tool caches", "error", err)
		return 0
	}
	hosts, err := c.st.ListHosts(ctx)
	if err != nil {
		c.log.Warn("could not list hosts to fill tool caches on", "error", err)
		return 0
	}
	now := c.Now()
	queued := 0
	for _, p := range pools {
		if !p.Enabled || !p.Cache.Enabled || !p.Cache.Tools || p.Backend == store.BackendProcess {
			continue
		}
		tools := toolRequests(scan.Pools[p.ID])
		if len(tools) == 0 {
			continue
		}
		spec, err := c.toolFillSpec(ctx, p)
		if err != nil {
			c.log.Warn("could not describe a pool to fill its tool cache", "pool", p.Name, "error", err)
			continue
		}
		for _, h := range hosts {
			// An older agent refuses the task outright; asking it would
			// only put a failure on every host that has not upgraded.
			if !scheduler.HostCanRun(h, p, now) || !h.Supports(agent.FeatureToolCacheFill) {
				continue
			}
			task := agent.Task{Kind: agent.TaskFillToolCache, PoolID: p.ID, Backend: p.Backend,
				Spec: &spec, Tools: tools, IssuedAt: now}
			if !c.enqueue(h.ID, task) {
				continue
			}
			queued++
			c.noteToolFill(p.ID, ToolCacheFill{HostID: h.ID, HostName: h.Name, State: "pending",
				Requested: len(tools), Tools: []backend.ToolFill{}, QueuedAt: now})
		}
	}
	if queued > 0 {
		c.log.Info("asked hosts to fill their pools' tool caches", "fills", queued)
	}
	return queued
}

// toolFillSpec is what a fill needs of the pool: the parts of a runner's spec
// that decide its image, its way out to the internet and which tool cache it
// is given. It has to name the same folder a runner of the pool is bound, or
// the fill warms a cache no job reads.
func (c *Controller) toolFillSpec(ctx context.Context, p *store.Pool) (backend.Spec, error) {
	target := ""
	if p.InstallationID != "" {
		inst, err := c.st.GetInstallation(ctx, p.InstallationID)
		if err != nil {
			return backend.Spec{}, err
		}
		target = inst.Target
	}
	return backend.Spec{
		PoolID:     p.ID,
		PoolName:   p.Name,
		Image:      c.RunnerImage(p),
		PullPolicy: p.PullPolicy,
		Env:        runnerEnv(c.cfg().Runners, p),
		Cache:      p.Cache,
		Repository: firstNonEmpty(strings.TrimSpace(p.Cache.Repository), target),
		Network:    c.cfg().Agent.Network,
	}, nil
}

// toolRequests is what a fill can act on, most-asked-for first: a version the
// workflows state, of a toolchain the tool cache holds. A version only a run
// knows -- read from a file, passed as an input -- has nothing to fill yet.
func toolRequests(demand []ToolchainDemand) []backend.ToolRequest {
	var ds []ToolchainDemand
	for _, d := range demand {
		if d.Unresolved != "" || d.Version == "" || strings.ContainsAny(d.Version, " \t\n") {
			continue
		}
		switch d.Tool {
		case "python", "node", "go", "java":
			ds = append(ds, d)
		}
	}
	sort.SliceStable(ds, func(i, j int) bool { return ds[i].Jobs > ds[j].Jobs })
	if len(ds) > maxToolFillRequests {
		ds = ds[:maxToolFillRequests]
	}
	out := make([]backend.ToolRequest, 0, len(ds))
	for _, d := range ds {
		out = append(out, backend.ToolRequest{Tool: d.Tool, Version: d.Version, Distribution: d.Distribution})
	}
	return out
}

// noteToolFill records a fill's latest state for its pool and host.
func (c *Controller) noteToolFill(poolID string, f ToolCacheFill) {
	c.toolchains.mu.Lock()
	defer c.toolchains.mu.Unlock()
	if c.toolchains.fills == nil {
		c.toolchains.fills = map[string]map[string]ToolCacheFill{}
	}
	if c.toolchains.fills[poolID] == nil {
		c.toolchains.fills[poolID] = map[string]ToolCacheFill{}
	}
	c.toolchains.fills[poolID][f.HostID] = f
}

// recordToolFill is an agent's answer to a fill.
func (c *Controller) recordToolFill(hostID string, task agent.Task, res agent.TaskResult) {
	c.toolchains.mu.Lock()
	f, ok := c.toolchains.fills[task.PoolID][hostID]
	c.toolchains.mu.Unlock()
	if !ok {
		f = ToolCacheFill{HostID: hostID, Requested: len(task.Tools), QueuedAt: task.IssuedAt}
		if h, err := c.st.GetHost(context.Background(), hostID); err == nil {
			f.HostName = h.Name
		}
	}
	f.State = "succeeded"
	if !res.OK {
		f.State = "failed"
	}
	f.Error = res.Error
	f.Tools = res.ToolFills
	if f.Tools == nil {
		f.Tools = []backend.ToolFill{}
	}
	done := res.CompletedAt
	if done.IsZero() {
		done = c.Now()
	}
	f.FinishedAt = &done
	c.noteToolFill(task.PoolID, f)
	if !res.OK {
		c.log.Warn("a host could not fill a pool's tool cache", "host", hostID, "pool", task.PoolID, "error", res.Error)
	}
}

// toolFillsByPool is the fills as the API shows them: per pool, by host name.
// The caller holds c.toolchains.mu.
func (c *Controller) toolFillsByPool() map[string][]ToolCacheFill {
	out := make(map[string][]ToolCacheFill, len(c.toolchains.fills))
	for pool, byHost := range c.toolchains.fills {
		list := make([]ToolCacheFill, 0, len(byHost))
		for _, f := range byHost {
			list = append(list, f)
		}
		sort.Slice(list, func(i, j int) bool {
			if list[i].HostName != list[j].HostName {
				return list[i].HostName < list[j].HostName
			}
			return list[i].HostID < list[j].HostID
		})
		out[pool] = list
	}
	return out
}

package controller

import (
	"reflect"
	"strconv"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/store"
)

// hostWith seeds a healthy docker host whose agent advertises features.
func (h *harness) hostWith(name string, features ...string) *store.Host {
	h.t.Helper()
	host := &store.Host{
		Name: name, Capacity: 4, Backends: store.StringSlice{"docker"}, Labels: store.StringMap{},
		OS: "linux", Arch: "amd64", CPUs: 16, MemoryMB: 64 * 1024, DiskTotalMB: 500 * 1024, DiskFreeMB: 400 * 1024,
		LastHeartbeat: time.Now(), Features: store.StringSlice(features),
	}
	if err := h.st.CreateHost(h.ctx, host); err != nil {
		h.t.Fatalf("CreateHost: %v", err)
	}
	return host
}

func (h *harness) keepToolCache(p *store.Pool) {
	h.t.Helper()
	p.Cache = store.CacheConfig{Enabled: true, Tools: true, Scope: store.CacheScopePool}
	if err := h.st.UpdatePool(h.ctx, p); err != nil {
		h.t.Fatalf("UpdatePool: %v", err)
	}
}

// A scan is what a pool's jobs ask for; a fill is that put in the cache the
// pool's runners are given. Only a pool that keeps a tool cache has one to
// fill, and only an agent that understands the task is sent it -- an older
// one refuses the kind, which would read as a fill failing on every host
// that has not upgraded yet.
func TestAScanFillsThePoolsThatKeepAToolCacheOnHostsThatCanRunThem(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	kept := h.pool(inst, "kept", "zoomies-kept")
	h.keepToolCache(kept)
	plain := h.pool(inst, "plain", "zoomies-plain")
	current := h.hostWith("current", agent.FeatureToolCacheFill)
	older := h.hostWith("older")

	demand := []ToolchainDemand{{Tool: "python", Version: "3.12", Jobs: 3}, {Tool: "node", Version: "22", Jobs: 5}}
	scan := ToolchainScan{Pools: map[string][]ToolchainDemand{kept.ID: demand, plain.ID: demand}}
	if n := h.c.fillToolCaches(h.ctx, scan); n != 1 {
		t.Fatalf("fillToolCaches queued %d fills, want 1", n)
	}
	if h.hasTaskOfKind(older.ID, agent.TaskFillToolCache) {
		t.Error("a fill was sent to an agent that does not advertise it")
	}
	task := h.taskOfKind(current.ID, agent.TaskFillToolCache)
	if task.PoolID != kept.ID || task.Spec == nil || task.Spec.PoolID != kept.ID || !task.Spec.Cache.Tools {
		t.Fatalf("task = %+v, want the kept pool's cache", task)
	}
	if task.Spec.Image != h.c.RunnerImage(kept) {
		t.Errorf("image = %q, want the one the pool's runners use", task.Spec.Image)
	}
	want := []backend.ToolRequest{{Tool: "node", Version: "22"}, {Tool: "python", Version: "3.12"}}
	if !reflect.DeepEqual(task.Tools, want) {
		t.Errorf("tools = %+v, want the most-asked-for first: %+v", task.Tools, want)
	}

	fills := h.c.ToolchainScanResult().Fills[kept.ID]
	if len(fills) != 1 || fills[0].State != "pending" || fills[0].HostName != "current" || fills[0].Requested != 2 {
		t.Fatalf("fills = %+v, want one pending fill on current", fills)
	}

	// A second scan while that fill is still downloading leaves it be.
	if n := h.c.fillToolCaches(h.ctx, scan); n != 0 {
		t.Errorf("a second scan queued %d more fills behind the running one", n)
	}

	batch, err := h.c.PollTasks(h.ctx, current.ID, 0)
	if err != nil || len(batch.Tasks) == 0 {
		t.Fatalf("PollTasks = %v, %v", batch, err)
	}
	result := []backend.ToolFill{
		{Tool: "node", Request: "22", Outcome: backend.ToolInstalled, Version: "22.11.0"},
		{Tool: "python", Request: "3.12", Outcome: backend.ToolFailed, Reason: "could not download it"},
	}
	if err := h.c.ReportResult(h.ctx, current.ID, agent.TaskResult{TaskID: task.ID, Kind: task.Kind, OK: true, ToolFills: result, CompletedAt: h.c.Now()}); err != nil {
		t.Fatalf("ReportResult: %v", err)
	}
	fills = h.c.ToolchainScanResult().Fills[kept.ID]
	if len(fills) != 1 || fills[0].State != "succeeded" || fills[0].FinishedAt == nil || !reflect.DeepEqual(fills[0].Tools, result) {
		t.Fatalf("fills after the report = %+v", fills)
	}
}

func TestAFailedFillSaysWhy(t *testing.T) {
	h := newHarness(t)
	inst := h.installation()
	p := h.pool(inst, "kept", "zoomies-kept")
	h.keepToolCache(p)
	host := h.hostWith("current", agent.FeatureToolCacheFill)
	h.c.fillToolCaches(h.ctx, ToolchainScan{Pools: map[string][]ToolchainDemand{p.ID: {{Tool: "go", Version: "1.27", Jobs: 1}}}})
	task := h.taskOfKind(host.ID, agent.TaskFillToolCache)
	if _, err := h.c.PollTasks(h.ctx, host.ID, 0); err != nil {
		t.Fatal(err)
	}
	if err := h.c.ReportResult(h.ctx, host.ID, agent.TaskResult{TaskID: task.ID, Kind: task.Kind, OK: false, Error: "backend: pulling the image: denied"}); err != nil {
		t.Fatal(err)
	}
	f := h.c.ToolchainScanResult().Fills[p.ID]
	if len(f) != 1 || f[0].State != "failed" || f[0].Error != "backend: pulling the image: denied" {
		t.Fatalf("fills = %+v", f)
	}
	// A fill is not a runner, so its failure fails none.
	if len(h.runners()) != 0 {
		t.Errorf("runners = %v, want none", h.runners())
	}
}

// A fill acts only on what it can put in a tool cache, and on the versions
// most jobs ask for when there are more than it is worth fetching on every
// host.
func TestToolRequestsKeepWhatAFillCanActOnMostAskedFirst(t *testing.T) {
	demand := []ToolchainDemand{
		{Tool: "go", Unresolved: "read from go.mod in the repository", Jobs: 50},
		{Tool: "dotnet", Version: "8.0", Jobs: 40},
		{Tool: "java", Version: "21", Distribution: "temurin", Jobs: 2},
		{Tool: "python", Version: "3.12", Jobs: 9},
	}
	got := toolRequests(demand)
	want := []backend.ToolRequest{{Tool: "python", Version: "3.12"}, {Tool: "java", Version: "21", Distribution: "temurin"}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("toolRequests = %+v, want %+v", got, want)
	}

	var many []ToolchainDemand
	for i := range 20 {
		many = append(many, ToolchainDemand{Tool: "node", Version: strconv.Itoa(10 + i), Jobs: i})
	}
	got = toolRequests(many)
	if len(got) != maxToolFillRequests || got[0].Version != "29" {
		t.Errorf("toolRequests over the cap = %d, first %+v; want %d starting with the most-asked-for", len(got), got[0], maxToolFillRequests)
	}
}

package controller

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/version"
)

// The release check asks github.com which release of Zoomies is current, so an
// operator learns that their controller is behind from the UI rather than from
// a changelog they were not reading.
//
// It is deliberately the only thing in Zoomies that talks to github.com
// regardless of github.api_base_url: the releases of this software live there
// whichever GitHub a fleet is pointed at. An Enterprise Server deployment with
// no route to github.com should switch it off, and updates.check_interval: 0
// says so plainly.
const (
	// latestReleaseURL is the API redirect GitHub maintains for the newest
	// release that is neither a draft nor a prerelease.
	latestReleaseURL = "https://api.github.com/repos/eyupio/zoomies/releases/latest"
	mainCommitURL    = "https://api.github.com/repos/eyupio/zoomies/commits/main"
	// updateCheckTimeout bounds the request. Nothing waits on this, so it can
	// afford to be patient, but not to hold a housekeeping pass open.
	updateCheckTimeout = 15 * time.Second
)

// releaseState is what the last successful check learned.
type releaseState struct {
	// Tag is the release's tag, e.g. "v0.2-beta".
	Tag string
	// URL is its release page, so the UI can link to the notes.
	URL string
	// At is when this was learned, so a stale answer can be recognised.
	At time.Time
}

// developmentState is what the last successful main-branch check learned.
type developmentState struct {
	SHA string
	URL string
	At  time.Time
}

// developmentCommit returns the commit stamped into a published main build.
func developmentCommit(v string) (string, bool) {
	const prefix = "main-sha-"
	sha := strings.TrimPrefix(strings.TrimSpace(v), prefix)
	if sha == v || len(sha) < 7 {
		return "", false
	}
	for _, r := range sha {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return "", false
		}
	}
	return sha, true
}

// releaseVersion reports the release this binary was built from, and whether it
// was built from one at all.
//
// This is the whole honesty of the feature. A controller running :dev or
// :main is stamped main-sha-abc1234 and is usually *ahead* of the newest
// release, so telling it that a release is available would be telling it to
// downgrade. Only a build that came from a release tag has anything to compare.
//
// The join command needs the same answer -- an agent is installed from a
// release asset, so a controller that is not a release cannot pin a host to
// itself -- so the rule lives in internal/version and this is its name here.
func releaseVersion(v string) (string, bool) { return version.Release(v) }

// checkForRelease asks GitHub for the current release and records it.
//
// A failure is logged at debug and otherwise ignored: a controller that cannot
// reach github.com is not a controller with a problem, and the previous answer
// stays until a later pass replaces it.
func (c *Controller) checkForRelease(ctx context.Context) {
	ctx, cancel := context.WithTimeout(ctx, updateCheckTimeout)
	defer cancel()
	if _, ok := developmentCommit(version.Version); ok {
		c.checkForMain(ctx)
		return
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, latestReleaseURL, nil)
	if err != nil {
		c.log.Debug("could not build the release check request", "error", err)
		return
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", version.UserAgent())

	resp, err := c.httpClient.Do(req)
	if err != nil {
		c.log.Debug("could not ask GitHub which release is current", "error", err)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		// 404 is what a repository with no published release answers, and it is
		// not a failure: there is simply nothing to compare against yet.
		c.log.Debug("the release check was refused", "status", resp.StatusCode)
		return
	}

	var body struct {
		TagName string `json:"tag_name"`
		HTMLURL string `json:"html_url"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		c.log.Debug("could not read the release check answer", "error", err)
		return
	}
	if strings.TrimSpace(body.TagName) == "" {
		return
	}

	c.mu.Lock()
	c.release = &releaseState{Tag: body.TagName, URL: body.HTMLURL, At: c.Now()}
	c.mu.Unlock()
}

// checkForMain gives a moving dev build a source of truth. The registry tag
// can remain perfectly reachable while CI has failed to advance it, so asking
// the branch rather than the tag is what detects that failure mode.
func (c *Controller) checkForMain(ctx context.Context) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, mainCommitURL, nil)
	if err != nil {
		c.log.Debug("could not build the main branch check request", "error", err)
		return
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", version.UserAgent())
	resp, err := c.httpClient.Do(req)
	if err != nil {
		c.log.Debug("could not ask GitHub which commit is on main", "error", err)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		c.log.Debug("the main branch check was refused", "status", resp.StatusCode)
		return
	}
	var body struct {
		SHA     string `json:"sha"`
		HTMLURL string `json:"html_url"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		c.log.Debug("could not read the main branch check answer", "error", err)
		return
	}
	if strings.TrimSpace(body.SHA) == "" {
		return
	}
	c.mu.Lock()
	c.development = &developmentState{SHA: body.SHA, URL: body.HTMLURL, At: c.Now()}
	c.mu.Unlock()
}

// latestRelease returns what the last check learned, or nil.
func (c *Controller) latestRelease() *releaseState {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.release
}

func (c *Controller) latestDevelopment() *developmentState {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.development
}

package controller

import (
	"bytes"
	"io"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/version"
)

// roundTripFunc answers every request with one canned response, which is enough
// for a checker that only ever asks GitHub one question.
type roundTripFunc func(*http.Request) *http.Response

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r), nil }

func jsonResponse(status int, body string) *http.Response {
	return &http.Response{
		StatusCode: status,
		Body:       io.NopCloser(bytes.NewBufferString(body)),
		Header:     http.Header{"Content-Type": []string{"application/json"}},
	}
}

// withVersion stamps a version for the duration of one test, because the whole
// question this feature answers is "what was this binary built from".
func withVersion(t *testing.T, v string) {
	t.Helper()
	prev := version.Version
	version.Version = v
	t.Cleanup(func() { version.Version = prev })
}

// The distinction the honesty of this feature rests on: a controller built from
// main is stamped with a commit and is normally *ahead* of the newest release,
// so it has nothing to compare and must say nothing.
func TestReleaseVersionAcceptsOnlyABuildFromARelease(t *testing.T) {
	for _, tc := range []struct {
		in   string
		want string
		ok   bool
	}{
		{"0.2-beta", "0.2-beta", true},
		{"v0.2-beta", "0.2-beta", true},
		{"1.4.0", "1.4.0", true},
		{"v1.4.0", "1.4.0", true},
		// What ci.yml stamps on an image built from main.
		{"main-sha-abc1234", "", false},
		// What the Makefile's git describe gives once commits land on a tag.
		{"v0.2-beta-5-gabc1234", "", false},
		{"v0.2-beta-5-gabc1234-dirty", "", false},
		{"dev", "", false},
		{"", "", false},
	} {
		got, ok := releaseVersion(tc.in)
		if got != tc.want || ok != tc.ok {
			t.Errorf("releaseVersion(%q) = %q, %v; want %q, %v", tc.in, got, ok, tc.want, tc.ok)
		}
	}
}

func TestDevelopmentCommitAcceptsOnlyPublishedMainBuilds(t *testing.T) {
	for _, tc := range []struct {
		in   string
		want string
		ok   bool
	}{
		{"main-sha-abc1234", "abc1234", true},
		{"main-sha-0123456789abcdef", "0123456789abcdef", true},
		{"main-sha-short", "", false},
		{"dev", "", false},
		{"1.0.0", "", false},
	} {
		got, ok := developmentCommit(tc.in)
		if got != tc.want || ok != tc.ok {
			t.Errorf("developmentCommit(%q) = %q, %v; want %q, %v", tc.in, got, ok, tc.want, tc.ok)
		}
	}
}

func TestUpdateProblemSaysNothingWithoutAReleaseToCompare(t *testing.T) {
	h := newHarness(t)

	t.Run("before the first check has answered", func(t *testing.T) {
		withVersion(t, "0.1-alpha")
		if got := h.c.updateProblems(); len(got) != 0 {
			t.Fatalf("problems = %v, want none", got)
		}
	})

	h.c.mu.Lock()
	h.c.release = &releaseState{Tag: "v0.2-beta", URL: "https://example.invalid/r", At: time.Now()}
	h.c.mu.Unlock()

	t.Run("a build from main is ahead, not behind", func(t *testing.T) {
		withVersion(t, "main-sha-abc1234")
		if got := h.c.updateProblems(); len(got) != 0 {
			t.Fatalf("problems = %v, want none: a main build has nothing to compare", got)
		}
	})

	t.Run("already on the current release", func(t *testing.T) {
		withVersion(t, "0.2-beta")
		if got := h.c.updateProblems(); len(got) != 0 {
			t.Fatalf("problems = %v, want none", got)
		}
	})
}

func TestUpdateProblemNamesBothVersions(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "0.1-alpha")
	h.c.mu.Lock()
	h.c.release = &releaseState{Tag: "v0.2-beta", URL: "https://example.invalid/r", At: time.Now()}
	h.c.mu.Unlock()

	got := h.c.updateProblems()
	if len(got) != 1 {
		t.Fatalf("problems = %v, want one", got)
	}
	p := got[0]
	if p.Code != "controller.update_available" {
		t.Fatalf("code = %q", p.Code)
	}
	// Both versions have to appear: the operator decides, and cannot without
	// knowing what they are on as well as what is current.
	if !strings.Contains(p.Title, "v0.2-beta") || !strings.Contains(p.Title, "0.1-alpha") {
		t.Fatalf("title = %q, want both versions named", p.Title)
	}
	if !strings.Contains(p.Fix, "https://example.invalid/r") {
		t.Fatalf("fix = %q, want the release notes linked", p.Fix)
	}
}

func TestDevelopmentUpdateProblemNamesRunningAndMainCommits(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "main-sha-abc1234")
	h.c.mu.Lock()
	h.c.development = &developmentState{SHA: "def5678901234567", URL: "https://example.invalid/commit/def5678", At: time.Now()}
	h.c.mu.Unlock()

	got := h.c.updateProblems()
	if len(got) != 1 {
		t.Fatalf("problems = %v, want one", got)
	}
	p := got[0]
	if p.Code != "controller.development_update_available" || !strings.Contains(p.Title, "abc1234") || !strings.Contains(p.Title, "def5678") {
		t.Fatalf("problem = %+v, want both development commits", p)
	}
	if !strings.Contains(p.Detail, "actually published") || !strings.Contains(p.Fix, "zoomies upgrade") {
		t.Fatalf("problem does not explain the stale channel: %+v", p)
	}

	h.c.mu.Lock()
	h.c.development.SHA = "abc1234fffffffffffffffffffffffff"
	h.c.mu.Unlock()
	if got := h.c.updateProblems(); len(got) != 0 {
		t.Fatalf("matching development build reported as stale: %v", got)
	}
}

// Switching the check off has to switch the notice off too, or an air-gapped
// fleet keeps being told about a release it deliberately stopped asking for.
func TestUpdateProblemIsSilentWhenTheCheckIsOff(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "0.1-alpha")
	h.c.mu.Lock()
	h.c.release = &releaseState{Tag: "v0.2-beta", At: time.Now()}
	h.c.mu.Unlock()

	h.c.live.Update(func(c *config.Config) { c.Updates.CheckInterval = 0 })

	if got := h.c.updateProblems(); len(got) != 0 {
		t.Fatalf("problems = %v, want none", got)
	}
}

func TestCheckForReleaseRecordsWhatGitHubSaid(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "0.1-alpha")
	h.c.httpClient = &http.Client{Transport: roundTripFunc(func(r *http.Request) *http.Response {
		if r.URL.String() != latestReleaseURL {
			t.Errorf("asked %s, want %s", r.URL, latestReleaseURL)
		}
		return jsonResponse(http.StatusOK, `{"tag_name":"v0.2-beta","html_url":"https://example.invalid/r"}`)
	})}

	h.c.checkForRelease(h.ctx)

	got := h.c.latestRelease()
	if got == nil || got.Tag != "v0.2-beta" || got.URL != "https://example.invalid/r" {
		t.Fatalf("release = %+v", got)
	}
}

func TestDevelopmentBuildChecksMainInsteadOfTheLatestRelease(t *testing.T) {
	h := newHarness(t)
	withVersion(t, "main-sha-abc1234")
	h.c.httpClient = &http.Client{Transport: roundTripFunc(func(r *http.Request) *http.Response {
		if r.URL.String() != mainCommitURL {
			t.Errorf("asked %s, want %s", r.URL, mainCommitURL)
		}
		return jsonResponse(http.StatusOK, `{"sha":"def5678901234567","html_url":"https://example.invalid/commit/def5678"}`)
	})}

	h.c.checkForRelease(h.ctx)

	got := h.c.latestDevelopment()
	if got == nil || got.SHA != "def5678901234567" || got.URL != "https://example.invalid/commit/def5678" {
		t.Fatalf("development = %+v", got)
	}
	if got := h.c.latestRelease(); got != nil {
		t.Fatalf("release = %+v, want no release comparison for a main build", got)
	}
}

// A repository with no published release answers 404, and a controller that
// cannot reach GitHub answers nothing. Neither is a problem with the fleet, and
// neither may be mistaken for an answer.
func TestCheckForReleaseKeepsQuietWhenThereIsNoAnswer(t *testing.T) {
	for _, tc := range []struct {
		name   string
		status int
		body   string
	}{
		{"no release published", http.StatusNotFound, `{"message":"Not Found"}`},
		{"rate limited", http.StatusForbidden, `{"message":"API rate limit exceeded"}`},
		{"an answer with no tag", http.StatusOK, `{}`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t)
			h.c.httpClient = &http.Client{Transport: roundTripFunc(func(*http.Request) *http.Response {
				return jsonResponse(tc.status, tc.body)
			})}
			h.c.checkForRelease(h.ctx)
			if got := h.c.latestRelease(); got != nil {
				t.Fatalf("release = %+v, want nothing recorded", got)
			}
		})
	}
}

package controller

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/scheduler"
	"github.com/eyupio/zoomies/internal/store"
	"github.com/eyupio/zoomies/internal/version"
)

// The views are the resources as the API documents them: a host with its
// health worked out, a runner with its pool and host named, a pool with its
// counts, a job with its waits measured.
//
// They live here rather than in internal/api because two transports render
// them. The REST handlers do, and so does the event stream -- and the stream
// is fed from this package, at the moment a row changes. When the two rendered
// different shapes, a `host.updated` frame carried a store row with no
// `healthy` field, so the one event that exists to say "this agent has gone
// quiet" repainted the host as healthy. One renderer, used by both, is what
// stops the cache the UI keeps from being wrong the moment an event lands.
// controller.Stats and controller.Problem already worked this way; these
// follow them.

// ---------------------------------------------------------------------------
// Hosts
// ---------------------------------------------------------------------------

// BackendInfoView describes one backend a host offers.
type BackendInfoView struct {
	Kind      store.BackendKind `json:"kind"`
	Available bool              `json:"available"`
	Version   string            `json:"version,omitempty"`
	Rootless  bool              `json:"rootless"`
	Endpoint  string            `json:"endpoint,omitempty"`
	Detail    string            `json:"detail,omitempty"`
	DinD      bool              `json:"supports_dind"`
	// Limits is what the daemon said it can enforce, which is what the
	// controller defaults a runner's limits from and what
	// host.limits_unenforceable reasons about; the API carries it so a
	// reader of the problem can see the fact behind it.
	Limits store.LimitSupport `json:"limits"`
	// SharedFolder is what is wrong with the host's shared folder, as the
	// agent said; see host.shared_folder_unmounted.
	SharedFolder string `json:"shared_folder,omitempty"`
}

// HostView is one agent host and the room it has left.
type HostView struct {
	Usage           *store.HostUsage `json:"usage,omitempty"`
	UsageFresh      bool             `json:"usage_fresh"`
	AdmissionReason string           `json:"admission_reason,omitempty"`
	// Throttle is the rung the controller has stepped this host down to after
	// sustained pressure, absent when it is on none, and ThrottleReason is the
	// same thing as the sentence the host card shows: what it took, why, what
	// it is doing to the jobs already running, and how it ends. Both are the
	// controller's alone; a heartbeat carries the measurements and never the
	// decision.
	Throttle       *store.HostThrottle `json:"throttle,omitempty"`
	ThrottleReason string              `json:"throttle_reason"`
	// RuntimeRecovering is the container-runtime cooldown the agent last
	// reported, absent when there is none, and RuntimeReason the card's
	// sentence for it. The times are carried rather than written into the
	// sentence, so the card can count down to the retry and say how old the
	// report is against the viewer's own clock.
	RuntimeRecovering *store.RuntimeIncident `json:"runtime_recovering,omitempty"`
	RuntimeReason     string                 `json:"runtime_reason,omitempty"`
	// ImagePullFailed is the last start or prewarm here that could not make
	// its pool's image ready, naming the registry, absent when there is none.
	ImagePullFailed *store.ImagePullIncident `json:"image_pull_failed,omitempty"`
	// EffectiveCapacity is the slots the host takes right now: Capacity
	// stepped down by the throttle, and Capacity itself when there is none.
	// Free is measured against it, so a throttled host's card does not
	// promise slots the next pass will refuse.
	EffectiveCapacity int `json:"effective_capacity"`
	// UnlimitedRunners is how many of the live runners here were created
	// with no CPU quota -- a pool with none and defaults off, a process pool,
	// a daemon that cannot apply one, or a row from before allocations were
	// recorded. They are the runners a CPU hold can mean something about.
	UnlimitedRunners int               `json:"unlimited_runners,omitempty"`
	Connection       string            `json:"connection"`
	ID               string            `json:"id"`
	Name             string            `json:"name"`
	Address          string            `json:"address,omitempty"`
	Embedded         bool              `json:"embedded"`
	Capacity         int               `json:"capacity"`
	ActiveRunners    int               `json:"active_runners"`
	Free             int               `json:"free"`
	Backends         []string          `json:"backends"`
	BackendInfo      []BackendInfoView `json:"backend_info"`
	Labels           map[string]string `json:"labels"`
	OS               string            `json:"os,omitempty"`
	Distro           string            `json:"distro,omitempty"`
	OSVersion        string            `json:"os_version,omitempty"`
	Arch             string            `json:"arch,omitempty"`
	// CPUs and MemoryMB are how much machine this host is, as its agent
	// reported it: the daemon's view of the machine where that is larger than
	// the agent's own share, because a container runner runs beside the agent
	// rather than inside its cgroup.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	// DiskTotalMB and DiskFreeMB are the filesystem holding the agent's work
	// directory, which is where a runner's checkout and its caches land -- so
	// it is the disk that decides whether a job has anywhere to go, and the
	// answer to "the host has slots free, why did nothing start?".
	//
	// Free is what a runner may write to rather than what is unused; the two
	// differ by the reserve the filesystem keeps for root, and a runner is not
	// root. Zero on both is "not measured" -- an agent too old to report it,
	// or a platform with no portable way to ask -- and is not a full disk.
	DiskTotalMB int64 `json:"disk_total_mb,omitempty"`
	DiskFreeMB  int64 `json:"disk_free_mb,omitempty"`
	// ReserveCPUs, ReserveMemoryMB and ReserveDiskMB are what the operator has
	// held back from placement, for the machine's own sake rather than for any
	// pool's. They are the operator's alone: a heartbeat never writes them,
	// exactly as it never writes capacity.
	ReserveCPUs     int   `json:"reserve_cpus,omitempty"`
	ReserveMemoryMB int64 `json:"reserve_memory_mb,omitempty"`
	ReserveDiskMB   int64 `json:"reserve_disk_mb,omitempty"`
	// AllocatableCPUs, AllocatableMemoryMB and AllocatableDiskMB are the
	// machine less its reserve: what the scheduler may actually place onto,
	// which is the figure a "how full is this host" question is asked against.
	// The floors under the reserve -- half a core or 5% of the CPUs, 512 MB
	// of memory and 2 GB of disk -- are applied here too, so what is shown is
	// what is used. The CPU floor is what keeps the daemon, the agent and the
	// kernel a core the runners' quotas can never take.
	AllocatableCPUs     float64 `json:"allocatable_cpus,omitempty"`
	AllocatableMemoryMB int64   `json:"allocatable_memory_mb,omitempty"`
	AllocatableDiskMB   int64   `json:"allocatable_disk_mb,omitempty"`
	// ReservedCPUs and ReservedMemoryMB are what the runners already on this
	// host have promised away, as of the last scheduling pass and from the
	// snapshot that pass decided on. Disk is deliberately absent: free disk is
	// a measurement of the filesystem as it is now, so what those runners have
	// written is in DiskFreeMB already, and adding their reservations would
	// charge the same bytes twice.
	//
	// ReservedKnown is false until a pass has run, because zero would read as
	// an idle machine rather than as an unanswered question.
	ReservedCPUs     float64 `json:"reserved_cpus,omitempty"`
	ReservedMemoryMB int64   `json:"reserved_memory_mb,omitempty"`
	ReservedKnown    bool    `json:"reserved_known"`
	// ResourcesKnown is whether this host has reported what machine it is at
	// all. An agent too old to say is placed by slots alone, which is what
	// keeps an upgrade from emptying a fleet -- and the page has to say so,
	// because a host showing no figures looks broken rather than old.
	ResourcesKnown bool `json:"resources_known"`
	// Platform is what this host is in the terms a pool asks in, and
	// PlatformLabel is the same thing as a sentence: "Ubuntu 24.04, arm64".
	Platform      store.Platform `json:"platform"`
	PlatformLabel string         `json:"platform_label,omitempty"`
	// CanonicalName is the name this machine would be given today. It is shown
	// beside a host called something that says nothing, so an operator can see
	// what renaming it would buy them.
	CanonicalName  string `json:"canonical_name,omitempty"`
	Version        string `json:"version,omitempty"`
	VersionChannel string `json:"version_channel,omitempty"`
	// Features is what the agent advertises it can do, and ElasticCPU the one
	// answer a pool cares about: whether a runner placed here can be lent CPU
	// at all. Rendered as a flag rather than left for the browser to find in
	// the list, so the card and the pool wizard cannot disagree about which
	// feature name means what.
	Features   []string `json:"features"`
	ElasticCPU bool     `json:"elastic_cpu"`
	Cordoned   bool     `json:"cordoned"`
	// ProtocolVersion is the agent protocol this host reported, and
	// Incompatible whether this controller can work with it. An incompatible
	// host is excluded from placement exactly as a cordoned one is, so the
	// Hosts page has to say which of the two it is: nothing is broken, the
	// host is up and heartbeating, and it has quietly stopped taking work.
	ProtocolVersion    int    `json:"protocol_version,omitempty"`
	Incompatible       bool   `json:"incompatible"`
	IncompatibleReason string `json:"incompatible_reason,omitempty"`
	// VersionSkew is how this host's release stands to the controller's:
	// "behind", "ahead", "differs", or absent when they match. It is computed
	// here rather than in the browser because the controller is the side that
	// knows its own version, and because the agent's own warning comes from
	// the same comparison -- the two used to disagree for two builds of one
	// tag, and a badge that contradicts a log line is worse than neither.
	VersionSkew    string    `json:"version_skew,omitempty"`
	UpgradeCommand string    `json:"upgrade_command,omitempty"`
	UpgradeVersion string    `json:"upgrade_version,omitempty"`
	UpgradeNote    string    `json:"upgrade_note,omitempty"`
	Healthy        bool      `json:"healthy"`
	LastHeartbeat  time.Time `json:"last_heartbeat"`
	CreatedAt      time.Time `json:"created_at"`
}

// HostView renders a host as the API returns it.
//
// backend_info is the agent's own probe, which includes the backends it could
// not use and the sentence explaining why: that sentence is the whole answer to
// "this host is connected, so why is nothing running on it?". A host that
// joined an older controller has no probe stored, so its available kinds are
// rendered as the bare list they are, and nothing is invented about the
// backends it never reported on.
func (c *Controller) HostView(h *store.Host) HostView {
	out := HostView{
		ID:                 h.ID,
		Name:               h.Name,
		Address:            h.Address,
		Embedded:           h.Embedded,
		Connection:         h.Connection,
		Capacity:           h.Capacity,
		ActiveRunners:      h.ActiveRunners,
		Free:               h.Free(),
		EffectiveCapacity:  h.EffectiveCapacity(),
		UnlimitedRunners:   h.UnlimitedRunners,
		ThrottleReason:     scheduler.ThrottleReason(h),
		Backends:           emptySlice(h.Backends),
		Labels:             emptyMap(h.Labels),
		OS:                 h.OS,
		Distro:             h.Distro,
		OSVersion:          h.OSVersion,
		Arch:               h.Arch,
		CPUs:               h.CPUs,
		MemoryMB:           h.MemoryMB,
		UsageFresh:         h.Usage.Fresh(c.Now()),
		AdmissionReason:    scheduler.HostAdmissionReason(h, c.Now()),
		DiskTotalMB:        h.DiskTotalMB,
		DiskFreeMB:         h.DiskFreeMB,
		ReserveCPUs:        h.ReserveCPUs,
		ReserveMemoryMB:    h.ReserveMemoryMB,
		ReserveDiskMB:      h.ReserveDiskMB,
		Platform:           h.Platform(),
		PlatformLabel:      h.Platform().Describe(),
		CanonicalName:      h.CanonicalName(),
		Version:            h.Version,
		VersionChannel:     version.Channel(h.Version),
		Features:           emptySlice(h.Features),
		ElasticCPU:         h.Supports(agent.FeatureElasticCPU),
		Cordoned:           h.Cordoned,
		ProtocolVersion:    h.ProtocolVersion,
		Incompatible:       h.Incompatible,
		IncompatibleReason: incompatibleReason(h),
		VersionSkew:        string(version.CompareBuilds(h.Version, version.Version)),
		Healthy:            h.Healthy(c.Now()),
		LastHeartbeat:      h.LastHeartbeat,
		CreatedAt:          h.CreatedAt,
	}
	out.UpgradeCommand, out.UpgradeVersion, out.UpgradeNote = hostUpgrade(h, version.Version)
	if !h.Usage.SampledAt.IsZero() {
		usage := h.Usage
		out.Usage = &usage
	}
	if h.Throttle.Active() {
		throttle := h.Throttle
		out.Throttle = &throttle
	}
	if inc := h.Incidents.Runtime; inc != nil {
		runtime := *inc
		out.RuntimeRecovering = &runtime
		out.RuntimeReason = runtimeReason(inc)
	}
	if inc := h.Incidents.ImagePull; inc != nil {
		pull := *inc
		out.ImagePullFailed = &pull
	}
	alloc := h.Allocatable()
	out.AllocatableCPUs = alloc.CPUs
	out.AllocatableMemoryMB = alloc.MemoryMB
	out.AllocatableDiskMB = alloc.DiskMB
	out.ResourcesKnown = alloc.CPUsKnown || alloc.MemoryKnown || alloc.DiskKnown
	if res, ok := c.reservedOn(h.ID); ok {
		out.ReservedCPUs = res.CPUs
		out.ReservedMemoryMB = res.MemoryMB
		out.ReservedKnown = true
	}
	if len(h.BackendInfo) > 0 {
		out.BackendInfo = make([]BackendInfoView, 0, len(h.BackendInfo))
		for _, b := range h.BackendInfo {
			out.BackendInfo = append(out.BackendInfo, BackendInfoView{
				Kind:         b.Kind,
				Available:    b.Available,
				Version:      b.Version,
				Rootless:     b.Rootless,
				Endpoint:     b.Endpoint,
				Detail:       b.Detail,
				DinD:         b.SupportsDinD,
				Limits:       b.Limits,
				SharedFolder: b.SharedFolder,
			})
		}
		return out
	}
	out.BackendInfo = make([]BackendInfoView, 0, len(h.Backends))
	for _, kind := range h.Backends {
		out.BackendInfo = append(out.BackendInfo, BackendInfoView{
			Kind:      store.BackendKind(kind),
			Available: true,
		})
	}
	return out
}

