		t.Fatalf("status = %d, want %d", rec.Code, http.StatusUnauthorized)
	}
}

// TestARejectedDeliveryIsNotProofThatWebhooksWork covers the diagnostic that
// tells an operator nothing is scaling.
//
// The webhook endpoint is public and unauthenticated by necessity, so anybody
// can put a row in the delivery table. Gating the warning on "a delivery
// arrived" rather than "a delivery verified" meant one probe from a passing
// scanner took the message off the screen for the whole retention window --
// including its error-severity form, which is the only thing that says no
// queued job will ever be noticed.
func TestARejectedDeliveryIsNotProofThatWebhooksWork(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	problemPresent := func() bool {
		t.Helper()
		ps, err := h.c.Problems(h.ctx)
		if err != nil {
			t.Fatalf("Problems: %v", err)
		}
		for _, p := range ps {
			if p.Code == "webhook.never_received" {
				return true
			}
		}
		return false
	}

	if !problemPresent() {
		t.Fatal("a fleet that has never had a webhook does not report webhook.never_received")
	}

	// A stranger probes the endpoint. It is rejected, and recorded.
	rec := h.deliver("workflow_job", jobEvent{Action: "queued", JobID: 7007}.body(), "not-the-secret")
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("probe status = %d, want %d", rec.Code, http.StatusUnauthorized)
	}
	if ds := h.deliveries(); len(ds) != 1 || ds[0].Status != "rejected" {
		t.Fatalf("deliveries = %+v, want one rejected", ds)
	}

	if !problemPresent() {
		t.Error("a rejected delivery silenced webhook.never_received: an unauthenticated stranger can hide the fact that nothing is scaling")
	}

	// A delivery that actually verifies is what clears it.
	if rec := h.deliverJob(jobEvent{
		Action: "queued", JobID: 7008,
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	}); rec.Code != http.StatusAccepted {
		t.Fatalf("accepted delivery status = %d, want %d (%s)", rec.Code, http.StatusAccepted, rec.Body.String())
	}
	if problemPresent() {
		t.Error("webhook.never_received survived a delivery that verified")
	}
}

// Nothing an unverified delivery says about itself is written down whole.
//
// The envelope is parsed before the signature is checked, because the
// repository is what chooses the secret to check it with. So the repository
// name, the action and both headers arrive from an unauthenticated request and
// are then kept: a database row, a line in the log, and a frame on the event
// stream every watching browser holds in memory. Unbounded, that is five
// megabytes of "repository.full_name" per request from anyone who can reach the
// endpoint, with no credential of any kind.
func TestAnUnverifiedDeliveryCannotWriteDownWhateverItLikes(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	huge := strings.Repeat("A", 2<<20)
	body := []byte(`{"action":"` + huge + `","repository":{"full_name":"` + huge + `"}}`)

	req := httptest.NewRequest(http.MethodPost, "/webhooks/github", bytes.NewReader(body))
	req.Header.Set(github.EventTypeHeader, "workflow_job")
	req.Header.Set(github.DeliveryIDHeader, huge)
	rec := httptest.NewRecorder()
	h.c.HandleWebhook(rec, req)

	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusUnauthorized)
	}
	ds := h.deliveries()
	if len(ds) != 1 {
		t.Fatalf("recorded %d deliveries, want 1", len(ds))
	}
	d := ds[0]
	for _, f := range []struct {
		name  string
		value string
		max   int
	}{
		{"repo", d.Repo, maxDeliveryRepo},
		{"delivery id", d.DeliveryID, maxDeliveryID},
		{"event", d.Event, maxDeliveryEvent},
	} {
		// The clamp says what it cut, so the allowance is the limit plus that
		// note rather than the limit exactly.
		if len(f.value) > f.max+64 {
			t.Errorf("the recorded %s is %d bytes; an unverified delivery chose that", f.name, len(f.value))
		}
	}
	// The reason a delivery was rejected quotes the repository back, so it has
	// to be bounded too or the clamp is undone by the error beside it.
	if len(d.Error) > 4096 {
		t.Errorf("the recorded rejection reason is %d bytes", len(d.Error))
	}
}

// A stream of unverifiable deliveries from one address is bounded in what it
// writes down, without any of it reaching a delivery that verifies.
func TestAFloodOfProbesStopsBeingWrittenDown(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	body := jobEvent{Action: "queued", JobID: 4004}.body()
	for i := 0; i < 200; i++ {
		if rec := h.deliver("workflow_job", body, "the-wrong-secret"); rec.Code != http.StatusUnauthorized {
			t.Fatalf("probe %d: status = %d, want %d; the refusal itself must not change", i, rec.Code, http.StatusUnauthorized)
		}
	}
	// Counted straight out of the store, at the largest page it will serve.
	// The harness helper pages at 100, which would hide exactly the failure
	// this test is for -- and ListDeliveries silently falls back to 50 for any
	// limit above 500, so asking for more than it allows hides it just as well.
	ds, err := h.st.ListDeliveries(h.ctx, "", 500)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(ds) == 0 {
		t.Fatal("no probe was recorded at all; a burst is worth knowing about")
	}
	if len(ds) > 100 {
		t.Errorf("recorded %d of 200 probes, so one address can still fill the database", len(ds))
	}

	// And the fleet still works: a real delivery is never touched by this.
	if rec := h.deliverJob(jobEvent{
		Action: "queued", JobID: 4005,
		Labels: []string{"self-hosted", "linux", "x64", "demo"},
	}); rec.Code != http.StatusOK && rec.Code != http.StatusAccepted {
		t.Fatalf("a signed delivery after the flood = %d; GitHub must never be throttled here", rec.Code)
	}
	if _, err := h.st.GetJobByGitHubID(h.ctx, 4005); err != nil {
		t.Errorf("the signed delivery did not create its job: %v", err)
	}
}

// A delivery with no signature header cannot verify, so it is refused before
// its body is read. Reading, parsing and checking a body against every
// installation's secret is the expensive part of the endpoint, and the
// endpoint is public: a probe used to get all of that for free, and a large
// unsigned body was answered as too large rather than as unsigned, which told
// the prober something and cost the controller the whole body cap to say it.
func TestAnUnsignedDeliveryIsRefusedBeforeItsBodyIsRead(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	body := make([]byte, maxWebhookBody+1)
	rec := h.deliver("workflow_job", body, "")
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("status = %d, want %d: an unsigned delivery is unsigned before it is too large", rec.Code, http.StatusUnauthorized)
	}
	ds := h.deliveries()
	if len(ds) != 1 || ds[0].Status != "rejected" {
		t.Fatalf("deliveries = %+v, want one rejected", ds)
	}
	if !strings.Contains(ds[0].Error, github.SignatureHeader) {
		t.Fatalf("the record does not name the missing header: %q", ds[0].Error)
	}
	if ds[0].Repo != "" {
		t.Fatalf("the body was parsed for a delivery that could never verify: repo = %q", ds[0].Repo)
	}
}

// A signed delivery larger than the cap is refused as too large, and one of
// the size GitHub really sends is not. The cap is what one request on the
// public endpoint costs before its signature can be checked, so it is kept to
// a megabyte -- and a cap set below a real workflow_job would stop the fleet
// hearing about work, which is the failure on the other side of this line.
func TestADeliveryOverTheBodyCapIsRefusedAndARealOneIsNot(t *testing.T) {
	h := newHarness(t)
	h.fleet()

	if maxWebhookBody > 1<<20 {
		t.Fatalf("the webhook body cap is %d bytes; a workflow_job is tens of kilobytes, and a megabyte is already twenty times that", maxWebhookBody)
	}

	over := make([]byte, maxWebhookBody+1)
	if rec := h.deliver("workflow_job", over, testWebhookSecret); rec.Code != http.StatusRequestEntityTooLarge {
		t.Fatalf("a %d-byte signed delivery: status = %d, want %d", len(over), rec.Code, http.StatusRequestEntityTooLarge)
	}

	// A real delivery padded well past what GitHub sends: the steps array of a
	// long job is the part that grows, and it is still nowhere near the cap.
	steps := make([]map[string]any, 500)
	for i := range steps {
		steps[i] = map[string]any{"number": i + 1, "name": fmt.Sprintf("Step %d of a very long job with a descriptive name", i+1), "status": "completed", "conclusion": "success"}
	}
	long := jobEvent{Action: "completed", JobID: 1001, RunID: 77, Labels: []string{"self-hosted", "linux"}, Conclusion: "success", Steps: steps}
	if n := len(long.body()); n > maxWebhookBody/4 {
		t.Fatalf("the fixture is %d bytes; it is meant to be a long job, well inside the cap", n)
	}
	if rec := h.deliverJob(long); rec.Code == http.StatusRequestEntityTooLarge || rec.Code >= 500 {
		t.Fatalf("a real workflow_job delivery for a 500-step job: status = %d; it must be accepted, not refused as too large", rec.Code)
	}
}

// A run's number was saved only on the job that looked it up: a sibling that
// found it already recorded used it for one delivery and never wrote it down,
// so the Runners page showed "#1114" beside one job of a run and nothing
// beside the rest. Every job of the run now carries it.
func TestEveryJobOfARunKeepsTheRunsNumber(t *testing.T) {
	h := newHarness(t)
	h.fleet()
	labels := []string{"self-hosted", "linux", "x64", "demo"}

	h.deliverJob(jobEvent{Action: "queued", JobID: 7101, RunID: 7100, Name: "lint", Workflow: "CI", Labels: labels})
	first, err := h.st.GetJobByGitHubID(h.ctx, 7101)
	if err != nil {
		t.Fatal(err)
	}
	// What the one lookup of GitHub for the run's number records.
	if err := h.st.SetRunNumberForRun(h.ctx, first.Repo, 7100, 1114); err != nil {
		t.Fatal(err)
	}

	h.deliverJob(jobEvent{Action: "queued", JobID: 7102, RunID: 7100, Name: "test", Workflow: "CI", Labels: labels})
	second, err := h.st.GetJobByGitHubID(h.ctx, 7102)
	if err != nil {
		t.Fatal(err)
	}
	if second.RunNumber != 1114 {
		t.Fatalf("second job's stored run number = %d, want 1114 from its sibling", second.RunNumber)
	}
}

// Package cryptox holds the two cryptographic primitives Zoomies needs:
// authenticated encryption for secrets at rest, and password hashing.
//
// There is deliberately no key-management ceremony here. The instance key comes
// from the environment or a file with 0600 permissions, and every secret column
// in the database is sealed with it. Losing the key means re-entering the
// GitHub App private key -- which is recoverable -- rather than losing the
// fleet's state.
package cryptox

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"golang.org/x/crypto/argon2"
)

// KeyLen is the required instance key length in bytes.
const KeyLen = 32

// ErrNoKey is returned when a seal or open is attempted without a key.
var ErrNoKey = errors.New("cryptox: no encryption key configured")

// ErrBadKey is returned when a configured key is the wrong length or encoding.
var ErrBadKey = errors.New("cryptox: encryption key must be 32 bytes, base64 or hex encoded")

// Key is an instance encryption key.
type Key struct {
	aead cipher.AEAD
	raw  []byte
}

// NewKey wraps 32 raw bytes.
func NewKey(raw []byte) (*Key, error) {
	if len(raw) != KeyLen {
		return nil, ErrBadKey
	}
	block, err := aes.NewCipher(raw)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	dup := make([]byte, len(raw))
	copy(dup, raw)
	return &Key{aead: aead, raw: dup}, nil
}

// GenerateKey returns a fresh random instance key.
func GenerateKey() (*Key, error) {
	raw := make([]byte, KeyLen)
	if _, err := rand.Read(raw); err != nil {
		return nil, err
	}
	return NewKey(raw)
}

// ParseKey accepts a base64 (standard or raw URL) or hex encoded 32-byte key.
// Surrounding whitespace is tolerated because keys get pasted into terminals.
func ParseKey(s string) (*Key, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, ErrNoKey
	}
	for _, dec := range []func(string) ([]byte, error){
		base64.StdEncoding.DecodeString,
		base64.RawStdEncoding.DecodeString,
		base64.URLEncoding.DecodeString,
		base64.RawURLEncoding.DecodeString,
		hex.DecodeString,
	} {
		if raw, err := dec(s); err == nil && len(raw) == KeyLen {
			return NewKey(raw)
		}
	}
	return nil, ErrBadKey
}

// LoadKeyFile reads a key from a file, refusing world- or group-readable files.
//
// The refusal reads POSIX mode bits, and Windows has none: Go reports every
// writable file there as 0666 whatever its ACL says, so the check would refuse
// every key on the one platform where the bits mean nothing. Access there is
// the directory's ACL, which the installer restricts; the check is skipped
// rather than made to lie.
func LoadKeyFile(path string) (*Key, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("cryptox: reading key file %s: %w", path, err)
	}
	if mode := info.Mode().Perm(); runtime.GOOS != "windows" && mode&0o077 != 0 {
		return nil, fmt.Errorf("cryptox: key file %s is mode %04o; it must not be readable by group or other (chmod 600 %s)",
			path, mode, path)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("cryptox: reading key file %s: %w", path, err)
	}
	return ParseKey(string(b))
}

// WriteKeyFile writes a key to disk with 0600 permissions, creating parents.
func WriteKeyFile(path string, k *Key) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(k.Encode()+"\n"), 0o600)
}

// Fingerprint identifies a key without disclosing it.
//
// It is the SHA-256 of the key material, truncated to twelve hex characters --
// enough for a person to compare two at a glance, and far short of what would
// help anybody who had one. What it is for is a backup manifest: an operator
// restoring on a new machine needs to know whether the key file they have is
// the one that sealed the database in front of them, and the alternative to a
// fingerprint is finding out when the first GitHub call fails.
//
// It hashes the raw key rather than anything the key produced, so two
// instances configured with the same key agree on it, which is the point.
func (k *Key) Fingerprint() string {
	if k == nil {
		return ""
	}
	sum := sha256.Sum256(k.raw)
	return hex.EncodeToString(sum[:])[:12]
}

// Encode renders the key as standard base64, the form the installer prints and
// zoomies.yaml stores.
func (k *Key) Encode() string { return base64.StdEncoding.EncodeToString(k.raw) }

// Seal encrypts plaintext, returning nonce||ciphertext. Nil input seals to nil
// so that an absent secret round-trips as absent rather than as empty bytes.
func (k *Key) Seal(plaintext []byte) ([]byte, error) {
	if k == nil {
		return nil, ErrNoKey
	}
	if plaintext == nil {
		return nil, nil
	}
	nonce := make([]byte, k.aead.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	return k.aead.Seal(nonce, nonce, plaintext, nil), nil
}

// SealString is Seal for text secrets.
func (k *Key) SealString(s string) ([]byte, error) {
	if s == "" {
		return nil, nil
	}
	return k.Seal([]byte(s))
}

// Open decrypts a value produced by Seal.
func (k *Key) Open(sealed []byte) ([]byte, error) {
	if k == nil {
		return nil, ErrNoKey
	}
	if len(sealed) == 0 {
		return nil, nil
	}
	ns := k.aead.NonceSize()
	if len(sealed) < ns+k.aead.Overhead() {
		return nil, errors.New("cryptox: ciphertext is too short to be valid")
	}
	out, err := k.aead.Open(nil, sealed[:ns], sealed[ns:], nil)
	if err != nil {
		return nil, errors.New("cryptox: could not decrypt; the encryption key does not match the one this data was written with")
	}
	return out, nil
}

// OpenString is Open for text secrets.
func (k *Key) OpenString(sealed []byte) (string, error) {
	b, err := k.Open(sealed)
	return string(b), err
}

// ---------------------------------------------------------------------------
// Sealing under a passphrase
// ---------------------------------------------------------------------------

// passphraseMagic starts every value SealWithPassphrase writes, so a value
// sealed with the instance key -- or anything else -- is refused as the wrong
// kind rather than reported as a wrong passphrase.
const passphraseMagic = "zoomies-pass-v1:"

// The KDF costs are the backup encryptor's: a passphrase-sealed value is opened
// once, by a person moving an installation, so the time is spent where a
// guessed passphrase costs the guesser most.
const (
	passArgonTime   = 3
	passArgonMemory = 64 * 1024 // KiB
	passArgonLanes  = 4
)

// ErrWrongPassphrase is a passphrase-sealed value that did not open. A wrong
// passphrase and an altered value are the same failure by construction.
var ErrWrongPassphrase = errors.New("cryptox: the passphrase does not open this value, or the value has been altered")

// SealWithPassphrase encrypts plaintext under a key derived from passphrase
// with argon2id and a fresh salt, and returns magic||salt||nonce||ciphertext.
//
// This exists so a secret can leave the instance without the instance key:
// that key seals every secret column, and handing it over to move one
// installation would hand over every other one with it.
func SealWithPassphrase(passphrase string, plaintext []byte) ([]byte, error) {
	if strings.TrimSpace(passphrase) == "" {
		return nil, errors.New("cryptox: a passphrase is needed to seal")
	}
	salt := make([]byte, argonSaltLen)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	k, err := passphraseKey(passphrase, salt)
	if err != nil {
		return nil, err
	}
	sealed, err := k.Seal(plaintext)
	if err != nil {
		return nil, err
	}
	out := append([]byte(passphraseMagic), salt...)
	return append(out, sealed...), nil
}

// OpenWithPassphrase reverses SealWithPassphrase.
func OpenWithPassphrase(passphrase string, sealed []byte) ([]byte, error) {
	if !strings.HasPrefix(string(sealed), passphraseMagic) || len(sealed) < len(passphraseMagic)+argonSaltLen {
		return nil, errors.New("cryptox: this value was not sealed with a passphrase")
	}
	rest := sealed[len(passphraseMagic):]
	k, err := passphraseKey(passphrase, rest[:argonSaltLen])
	if err != nil {
		return nil, err
	}
	out, err := k.Open(rest[argonSaltLen:])
	if err != nil {
		return nil, ErrWrongPassphrase
	}
	return out, nil
}

func passphraseKey(passphrase string, salt []byte) (*Key, error) {
	return NewKey(argon2.IDKey([]byte(passphrase), salt, passArgonTime, passArgonMemory, passArgonLanes, KeyLen))
}

// ---------------------------------------------------------------------------
// Password hashing
// ---------------------------------------------------------------------------

// argon2id parameters. These target roughly 100 ms on a modest VM, which is the
// right order of magnitude for an interactive login on the kind of host this
// controller runs on.
const (
	argonTime    = 2
	argonMemory  = 64 * 1024 // KiB
	argonThreads = 4
	argonKeyLen  = 32
	argonSaltLen = 16
)

// HashPassword returns a PHC-formatted argon2id hash.
func HashPassword(password string) (string, error) {
	if password == "" {
		return "", errors.New("cryptox: password must not be empty")
	}
	salt := make([]byte, argonSaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", err
	}
	sum := argon2.IDKey([]byte(password), salt, argonTime, argonMemory, argonThreads, argonKeyLen)
	return fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version, argonMemory, argonTime, argonThreads,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(sum)), nil
}

// VerifyPassword reports whether password matches a PHC-formatted hash. It
// always runs the full KDF so that a wrong password and an unknown user take
// the same time.
func VerifyPassword(password, encoded string) bool {
	parts := strings.Split(encoded, "$")
	if len(parts) != 6 || parts[1] != "argon2id" {
		return false
	}
	var version int
	if _, err := fmt.Sscanf(parts[2], "v=%d", &version); err != nil || version != argon2.Version {
		return false
	}
	var memory uint32
	var time uint32
	var threads uint8
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &memory, &time, &threads); err != nil {
		return false
	}
	// argon2 panics rather than erring on a zero round count or lane count, so
	// a hash column that has been corrupted -- by a hand-edited row, a partial
	// restore, a database from some other tool -- would take down whatever is
	// verifying rather than refusing the password. A hash nothing could have
	// produced is simply not a match.
	if time == 0 || threads == 0 {
		return false
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[4])
	if err != nil {
		return false
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[5])
	if err != nil {
		return false
	}
	got := argon2.IDKey([]byte(password), salt, time, memory, threads, uint32(len(want)))
	return subtle.ConstantTimeCompare(got, want) == 1
}

// DummyVerify burns the same CPU as VerifyPassword. Login handlers call it when
// the username does not exist, so that response timing does not enumerate users.
func DummyVerify(password string) {
	argon2.IDKey([]byte(password), make([]byte, argonSaltLen),
		argonTime, argonMemory, argonThreads, argonKeyLen)
}

// ---------------------------------------------------------------------------
// Token hashing
// ---------------------------------------------------------------------------

// HashToken returns the hex SHA-256 of a bearer token. Tokens carry full
// entropy from the start, so a fast hash is sufficient and keeps API
// authentication off the argon2 path.
func HashToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

// ConstantTimeEqual compares two strings without leaking their contents through
// timing.
func ConstantTimeEqual(a, b string) bool {
	return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

package cryptox

import (
	"bytes"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func testKey(t *testing.T) *Key {
	t.Helper()
	k, err := GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	return k
}

// A key is pasted into a terminal from wherever it was written down, so every
// encoding the installer or a person is likely to produce has to parse, and
// anything that is not 32 bytes has to be refused rather than silently used.
func TestParseKeyAcceptsEveryEncodingTheInstallerMightProduce(t *testing.T) {
	raw := bytes.Repeat([]byte{0xAB}, KeyLen)
	cases := map[string]string{
		"standard base64": base64.StdEncoding.EncodeToString(raw),
		"raw base64":      base64.RawStdEncoding.EncodeToString(raw),
		"url base64":      base64.URLEncoding.EncodeToString(raw),
		"raw url base64":  base64.RawURLEncoding.EncodeToString(raw),
		"hex":             hex.EncodeToString(raw),
		"with whitespace": "  " + hex.EncodeToString(raw) + "\n",
	}
	for name, encoded := range cases {
		t.Run(name, func(t *testing.T) {
			k, err := ParseKey(encoded)
			if err != nil {
				t.Fatalf("ParseKey: %v", err)
			}
			if !bytes.Equal(k.raw, raw) {
				t.Fatal("the parsed key is not the bytes that were encoded")
			}
		})
	}

	for name, bad := range map[string]string{
		"too short":          base64.StdEncoding.EncodeToString(raw[:16]),
		"too long":           hex.EncodeToString(append(raw, 0x01)),
		"not encoded":        "definitely not a key",
		"empty is not a key": "",
	} {
		t.Run(name, func(t *testing.T) {
			_, err := ParseKey(bad)
			switch {
			case bad == "" && !errors.Is(err, ErrNoKey):
				t.Fatalf("an empty key = %v, want ErrNoKey", err)
			case bad != "" && !errors.Is(err, ErrBadKey):
				t.Fatalf("%q = %v, want ErrBadKey", bad, err)
			}
		})
	}
	if _, err := NewKey(raw[:31]); !errors.Is(err, ErrBadKey) {
		t.Fatalf("NewKey with 31 bytes = %v, want ErrBadKey", err)
	}
}

func TestEncodeRoundTripsThroughParse(t *testing.T) {
	k := testKey(t)
	again, err := ParseKey(k.Encode())
	if err != nil {
		t.Fatalf("ParseKey(Encode): %v", err)
	}
	if !bytes.Equal(k.raw, again.raw) {
		t.Fatal("Encode then ParseKey changed the key")
	}
}

// Seal and Open are what stand between a database backup and the GitHub App
// private key inside it.
func TestSealAndOpen(t *testing.T) {
	k := testKey(t)
	plain := []byte("-----BEGIN RSA PRIVATE KEY-----\nnot really\n")

	sealed, err := k.Seal(plain)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}
	if bytes.Contains(sealed, []byte("not really")) {
		t.Fatal("the sealed value contains the plaintext")
	}
	got, err := k.Open(sealed)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	if !bytes.Equal(got, plain) {
		t.Fatalf("Open = %q, want the plaintext back", got)
	}

	t.Run("every seal uses a fresh nonce", func(t *testing.T) {
		again, err := k.Seal(plain)
		if err != nil {
			t.Fatal(err)
		}
		if bytes.Equal(sealed, again) {
			t.Fatal("two seals of the same plaintext were identical; the nonce is being reused")
		}
	})

	t.Run("a tampered byte is refused", func(t *testing.T) {
		for _, i := range []int{0, len(sealed) / 2, len(sealed) - 1} {
			bad := bytes.Clone(sealed)
			bad[i] ^= 0x01
			if _, err := k.Open(bad); err == nil {
				t.Fatalf("Open accepted a value with byte %d flipped", i)
			}
		}
	})

	t.Run("the wrong key is refused, in words an operator can act on", func(t *testing.T) {
		other := testKey(t)
		_, err := other.Open(sealed)
		if err == nil || !strings.Contains(err.Error(), "encryption key does not match") {
			t.Fatalf("Open with the wrong key = %v", err)
		}
	})

	t.Run("a truncated value is refused without panicking", func(t *testing.T) {
		if _, err := k.Open(sealed[:5]); err == nil {
			t.Fatal("Open accepted a value shorter than a nonce and a tag")
		}
	})

	t.Run("an absent secret stays absent", func(t *testing.T) {
		if s, err := k.Seal(nil); err != nil || s != nil {
			t.Fatalf("Seal(nil) = %v, %v; want nil, nil", s, err)
		}
		if s, err := k.SealString(""); err != nil || s != nil {
			t.Fatalf("SealString(\"\") = %v, %v; want nil, nil", s, err)
		}
		if p, err := k.Open(nil); err != nil || p != nil {
			t.Fatalf("Open(nil) = %v, %v; want nil, nil", p, err)
		}
		if p, err := k.OpenString(nil); err != nil || p != "" {
			t.Fatalf("OpenString(nil) = %q, %v; want empty", p, err)
		}
	})

	t.Run("a nil key refuses rather than panics", func(t *testing.T) {
		var none *Key
		if _, err := none.Seal(plain); !errors.Is(err, ErrNoKey) {
			t.Fatalf("Seal on a nil key = %v, want ErrNoKey", err)
		}
		if _, err := none.Open(sealed); !errors.Is(err, ErrNoKey) {
			t.Fatalf("Open on a nil key = %v, want ErrNoKey", err)
		}
	})
}

// The key file is the one secret on disk that unlocks every other; a file the
// group or the world can read is refused, and the file this package writes is
// one it would accept.
func TestKeyFilePermissions(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("file modes do not carry the same meaning on Windows")
	}
	dir := t.TempDir()
	k := testKey(t)

	path := filepath.Join(dir, "nested", "key")
	if err := WriteKeyFile(path, k); err != nil {
		t.Fatalf("WriteKeyFile: %v", err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if mode := info.Mode().Perm(); mode != 0o600 {
		t.Fatalf("the written key file is mode %04o, want 0600", mode)
	}
	loaded, err := LoadKeyFile(path)
	if err != nil {
		t.Fatalf("LoadKeyFile: %v", err)
	}
	if !bytes.Equal(loaded.raw, k.raw) {
		t.Fatal("the loaded key is not the one written")
	}

	if err := os.Chmod(path, 0o644); err != nil {
		t.Fatal(err)
	}
	_, err = LoadKeyFile(path)
	if err == nil || !strings.Contains(err.Error(), "chmod 600") {
		t.Fatalf("a world-readable key file was loaded: %v", err)
	}

	if _, err := LoadKeyFile(filepath.Join(dir, "missing")); err == nil {
		t.Fatal("a missing key file was loaded")
	}
}

// Passwords are hashed with argon2id in PHC form, so a hash is verifiable
// without any parameter stored beside it and a wrong password never matches.
func TestPasswordHashing(t *testing.T) {
	hash, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatalf("HashPassword: %v", err)
	}
	if !strings.HasPrefix(hash, "$argon2id$v=19$") {
		t.Fatalf("hash = %q, want PHC argon2id", hash)
	}
	if !VerifyPassword("correct horse battery staple", hash) {
		t.Fatal("the right password does not verify")
	}
	if VerifyPassword("correct horse battery stapler", hash) {
		t.Fatal("a wrong password verified")
	}
	if VerifyPassword("correct horse battery staple", "$argon2id$v=19$garbage") {
		t.Fatal("a malformed hash verified")
	}
	if VerifyPassword("anything", "") {
		t.Fatal("an empty hash verified")
	}
	if _, err := HashPassword(""); err == nil {
		t.Fatal("an empty password was hashed")
	}

	again, _ := HashPassword("correct horse battery staple")
	if again == hash {
		t.Fatal("two hashes of the same password were identical; the salt is being reused")
	}
}

// A hash column that has been corrupted must refuse the password, not take
// the process with it.
//
// argon2 panics on a zero round count or lane count rather than returning an
// error, and the parameters come from the stored string -- so a hand-edited
// row, a partial restore or a database written by something else turned every
// sign-in attempt against that account into a panic. The API's recovery
// middleware turns that into a 500; `zoomies users passwd` has no such net
// and simply dies.
func TestVerifyPasswordRefusesAHashWithImpossibleParameters(t *testing.T) {
	const salt = "c29tZXNhbHRzb21lc2E"
	const sum = "c29tZWhhc2hzb21laGFzaHNvbWVoYXNoc29tZQ"
	for _, params := range []string{
		"m=65536,t=0,p=4",
		"m=65536,t=2,p=0",
		"m=0,t=0,p=0",
	} {
		hash := "$argon2id$v=19$" + params + "$" + salt + "$" + sum
		if VerifyPassword("correct horse battery staple", hash) {
			t.Fatalf("a hash with %s verified", params)
		}
	}
}

// Tokens carry full entropy, so their hash is a plain SHA-256 that has to be
// the same every time the same token is presented.
func TestTokenHashing(t *testing.T) {
	a, b := HashToken("zt_abc"), HashToken("zt_abc")
	if a != b || len(a) != 64 {
		t.Fatalf("HashToken is not a stable hex SHA-256: %q, %q", a, b)
	}
	if HashToken("zt_abd") == a {
		t.Fatal("two different tokens hashed the same")
	}
	if !ConstantTimeEqual(a, b) || ConstantTimeEqual(a, "") {
		t.Fatal("ConstantTimeEqual gave the wrong answer")
	}
}

// A fingerprint exists so an operator restoring on a new machine can tell
// whether the key file in their hand is the one that sealed the database in
// front of them. What it must never be is a shortcut to the key itself.
func TestFingerprintIdentifiesAKeyWithoutDisclosingIt(t *testing.T) {
	a, err := GenerateKey()
	if err != nil {
		t.Fatal(err)
	}
	b, err := GenerateKey()
	if err != nil {
		t.Fatal(err)
	}

	first := a.Fingerprint()
	if first == "" {
		t.Fatal("a key has no fingerprint, so a manifest has nothing to record")
	}
	if again := a.Fingerprint(); again != first {
		t.Errorf("the same key fingerprints differently twice (%q then %q); comparing two would prove nothing", first, again)
	}
	if a.Fingerprint() == b.Fingerprint() {
		t.Error("two different keys share a fingerprint, so the check would pass on the wrong key")
	}
	// The same key material anywhere gives the same answer: two instances
	// configured alike have to agree, which is the whole point.
	same, err := ParseKey(a.Encode())
	if err != nil {
		t.Fatal(err)
	}
	if same.Fingerprint() != a.Fingerprint() {
		t.Error("a key parsed back from its own encoding fingerprints differently")
	}

	// It is a hash, not an excerpt. A fingerprint that contained key material
	// would put a piece of the key in every backup manifest.
	if strings.Contains(a.Encode(), a.Fingerprint()) || strings.Contains(hex.EncodeToString(a.raw), a.Fingerprint()) {
		t.Error("the fingerprint appears inside the key itself")
	}
}

package cryptox

import (
	"bytes"
	"encoding/base64"
	"encoding/hex"
	"testing"
)

func FuzzParseKey(f *testing.F) {
	raw := bytes.Repeat([]byte{0x42}, KeyLen)
	for _, s := range []string{"", "invalid", hex.EncodeToString(raw), base64.StdEncoding.EncodeToString(raw), base64.RawURLEncoding.EncodeToString(raw)} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, encoded string) {
		key, err := ParseKey(encoded)
		if err != nil {
			return
		}
		if key == nil || len(key.raw) != KeyLen {
			t.Fatal("accepted an invalid key")
		}
		roundTrip, err := ParseKey(key.Encode())
		if err != nil || !bytes.Equal(key.raw, roundTrip.raw) {
			t.Fatal("key encoding did not round-trip")
		}
	})
}

func FuzzSealOpen(f *testing.F) {
	f.Add([]byte("secret"))
	f.Add([]byte{})
	f.Add([]byte{0, 255, 0})
	f.Fuzz(func(t *testing.T, plaintext []byte) {
		key, err := NewKey(bytes.Repeat([]byte{0x42}, KeyLen))
		if err != nil {
			t.Fatal(err)
		}
		sealed, err := key.Seal(plaintext)
		if err != nil {
			t.Fatal(err)
		}
		opened, err := key.Open(sealed)
		if err != nil || !bytes.Equal(opened, plaintext) {
			t.Fatal("encryption did not round-trip")
		}
		if len(sealed) > 0 {
			sealed[len(sealed)-1] ^= 1
			if _, err := key.Open(sealed); err == nil {
				t.Fatal("accepted tampered ciphertext")
			}
		}
		// Arbitrary ciphertext, including truncated nonces, must not panic.
		_, _ = key.Open(plaintext)
	})
}

package cryptox

import (
	"errors"
	"testing"
)

// A secret sealed for another instance has to open with the passphrase alone,
// and with nothing else: not a wrong passphrase, not an altered copy.
func TestAPassphraseSealedValueOpensWithThePassphraseAndNothingElse(t *testing.T) {
	sealed, err := SealWithPassphrase("correct horse", []byte("-----BEGIN RSA PRIVATE KEY-----"))
	if err != nil {
		t.Fatalf("SealWithPassphrase: %v", err)
	}
	got, err := OpenWithPassphrase("correct horse", sealed)
	if err != nil || string(got) != "-----BEGIN RSA PRIVATE KEY-----" {
		t.Fatalf("OpenWithPassphrase = %q, %v", got, err)
	}
	if _, err := OpenWithPassphrase("battery staple", sealed); !errors.Is(err, ErrWrongPassphrase) {
		t.Errorf("a wrong passphrase gave %v, want ErrWrongPassphrase", err)
	}
	tampered := append([]byte(nil), sealed...)
	tampered[len(tampered)-1] ^= 1
	if _, err := OpenWithPassphrase("correct horse", tampered); !errors.Is(err, ErrWrongPassphrase) {
		t.Errorf("an altered value gave %v, want ErrWrongPassphrase", err)
	}
	again, _ := SealWithPassphrase("correct horse", []byte("-----BEGIN RSA PRIVATE KEY-----"))
	if string(again) == string(sealed) {
		t.Error("two seals of one value came out the same; the salt or nonce is not fresh")
	}
}

// A value the instance key sealed is the wrong kind of thing, and saying so is
// more use to the person holding it than "wrong passphrase".
func TestAnInstanceSealedValueIsRefusedAsTheWrongKind(t *testing.T) {
	k, err := GenerateKey()
	if err != nil {
		t.Fatal(err)
	}
	instance, _ := k.Seal([]byte("x"))
	if _, err := OpenWithPassphrase("correct horse", instance); err == nil || errors.Is(err, ErrWrongPassphrase) {
		t.Errorf("an instance-sealed value gave %v, want a refusal naming the wrong kind", err)
	}
	if _, err := SealWithPassphrase("  ", []byte("x")); err == nil {
		t.Error("a blank passphrase sealed a value")
	}
}

