func TestCIDogfoodsZoomiesWithRecoveryForEveryJob(t *testing.T) {
	files := workflowFiles(t)
	selector := `((github.event_name == 'workflow_dispatch' && inputs.runner == 'github') || (github.event_name == 'pull_request' && github.event.pull_request.head.repo.fork)) && 'ubuntu-latest' || 'zoomies-linux-x64'`
	runsOn := regexp.MustCompile(`(?m)^    runs-on: (.+)$`)
	for _, name := range []string{"ci.yml", "govulncheck.yml"} {
		body := files[name]
		for _, want := range []string{"default: zoomies", "options: [zoomies, github]"} {
			if !strings.Contains(body, want) {
				t.Errorf("%s lacks %s", name, want)
			}
		}
		matches := runsOn.FindAllStringSubmatch(body, -1)
		if len(matches) == 0 {
			t.Fatalf("%s has no job runners", name)
		}
		// Match exceptions by job ID: a count alone lets the wrong job stop
		// dogfooding while still satisfying the test. Both exist to run on a
		// platform the Zoomies pool has no host for, which is the whole point
		// of each -- everything else, including playwright and installer,
		// dogfoods the pool because the runner image gives its user
		// passwordless sudo (see deploy/Dockerfile.runner).
		exceptions := map[string]string{}
		found := map[string]bool{}
		if name == "ci.yml" {
			exceptions["arm64"] = "ubuntu-24.04-arm"
			exceptions["drill"] = "ubuntu-latest"
			exceptions["windows"] = "windows-latest"
		}
		jobs := regexp.MustCompile(`(?m)^  ([a-zA-Z0-9_-]+):\n`).FindAllStringSubmatchIndex(body, -1)
		for i, job := range jobs {
			end := len(body)
			if i+1 < len(jobs) {
				end = jobs[i+1][0]
			}
			id := body[job[2]:job[3]]
			runner := runsOn.FindStringSubmatch(body[job[1]:end])
			if len(runner) == 0 {
				continue
			}
			if want, allowed := exceptions[id]; allowed {
				found[id] = true
				if runner[1] != want {
					t.Errorf("%s job %s must run on the GitHub-hosted %s, got %s", name, id, want, runner[1])
				}
			} else if !strings.Contains(runner[1], selector) {
				t.Errorf("%s job %s lacks fork protection and manual recovery: %s", name, id, runner[1])
			}
		}
		for id := range exceptions {
			if !found[id] {
				t.Errorf("%s is missing expected GitHub-hosted job %s", name, id)
			}
		}
	}
	ci := files["ci.yml"]
	if strings.Contains(ci, "useblacksmith/") {
		t.Error("CI still depends on Blacksmith-specific builders")
	}
	if !strings.Contains(ci, "if: ${{ !cancelled() && (github.event_name == 'pull_request'") {
		t.Error("Images must respect cancellation while allowing skipped PR publishing dependencies")
	}
}

func TestContainerBuildsStampTheirRunnerChannel(t *testing.T) {
	workflows := workflowFiles(t)
	for _, tc := range []struct {
		file, stamp string
		count       int
	}{
		{"ci.yml", "RUNNER_IMAGE_TAG=dev", 2},
		{"release.yml", "RUNNER_IMAGE_TAG=${{ needs.setup.outputs.tag }}", 4},
	} {
		if got := strings.Count(workflows[tc.file], tc.stamp); got != tc.count {
			t.Errorf("%s: found %d runner tag stamps, want %d controller/agent build paths", tc.file, got, tc.count)
		}
	}
	dockerfile, err := os.ReadFile("../../deploy/Dockerfile")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(dockerfile), "-X github.com/eyupio/zoomies/internal/naming.RunnerImageTag=${RUNNER_IMAGE_TAG}") {
		t.Error("container build does not pass its runner tag to the binary")
	}
}

// Every binary `make dist` builds is a binary the dev channel publishes.
//
// The publish names its files rather than globbing them, because a glob
// cannot tell a missing build from a platform nobody asked for: the job that
// found dist/ short of a binary published the rest and called it a release.
// Naming them buys that check and costs this one -- a platform added to the
// Makefile and not to the workflow would be built on every push to main and
// published nowhere, which nothing else would say.
func TestTheDevChannelPublishesEveryBinaryDistBuilds(t *testing.T) {
	makefile, err := os.ReadFile("../../Makefile")
	if err != nil {
		t.Fatalf("reading the Makefile: %v", err)
	}
	platforms := regexp.MustCompile(`for platform in ([^;]+); do`).FindSubmatch(makefile)
	if platforms == nil {
		t.Fatal("the dist target no longer lists its platforms in a loop this test can read")
	}
	ci := workflowFiles(t)["ci.yml"]
	for _, platform := range strings.Fields(string(platforms[1])) {
		os_, arch, ok := strings.Cut(platform, "/")
		if !ok {
			t.Errorf("%q is not an os/arch", platform)
			continue
		}
		name := "dist/zoomies_" + os_ + "_" + arch
		if os_ == "windows" {
			name += ".exe"
		}
		if !strings.Contains(ci, name) {
			t.Errorf("make dist builds %s and the dev release does not publish it", name)
		}
	}
}

// Scorecard's publishing service verifies the workflow that produced a result
// before it accepts one, and one of its rules is that the job ran on a
// GitHub-hosted Ubuntu runner. The move of CI onto the fleet took this job with
// it, and every push to main afterwards failed the same way: the publish was
// refused with "invalid runner label", no SARIF was written, and the
// code-scanning upload found nothing to upload. It is the one workflow that
// cannot dogfood, so this is the one runs-on that must not follow the others.
func TestScorecardPublishesFromAGitHubHostedRunner(t *testing.T) {
	body := workflowFiles(t)["scorecard.yml"]
	if body == "" {
		t.Fatal("scorecard.yml is missing")
	}
	if !strings.Contains(body, "publish_results: true") {
		t.Fatal("scorecard.yml no longer publishes its results; the README badge and the public score come from that publish")
	}
	if !strings.Contains(body, "    runs-on: ubuntu-latest\n") {
		t.Error("scorecard.yml's analysis job does not run on ubuntu-latest; the publishing service refuses every other runner label (https://github.com/ossf/scorecard-action#workflow-restrictions), and without the publish no SARIF is written for the upload step")
	}
	if strings.Contains(body, "runs-on: zoomies-linux-x64") {
		t.Error("scorecard.yml's job runs on the fleet's label; this workflow is scored by a service that only accepts results from GitHub's runners")
	}
}

// A release tag that does not begin with a lower-case v has to fail out loud.
// The setup job once ran only for tags matching `v*`, so `V1.1.0` matched
// nothing: every job was skipped, the run was green, and the release was
// published with no assets. Skipping is reserved for the rolling dev
// prerelease by name; everything else reaches the case statement that refuses
// it with an error annotation.
func TestTheReleaseWorkflowRefusesAMalformedTagOutLoud(t *testing.T) {
	body := workflowFiles(t)["release.yml"]
	if body == "" {
		t.Fatal("release.yml is missing")
	}
	if strings.Contains(body, "startsWith(github.event.release.tag_name, 'v')") {
		t.Error("release.yml skips the run for a tag that does not begin with v, which is how V1.1.0 was published with no assets and nobody was told")
	}
	if !strings.Contains(body, "github.event.release.tag_name != 'dev'") {
		t.Error("release.yml no longer skips the rolling dev prerelease by name, so publishing dev would try to turn a moving channel into a release")
	}
	if !strings.Contains(body, `*) echo "::error::$TAG is not a release tag; they begin with a lower-case v" && exit 1 ;;`) {
		t.Error("release.yml does not refuse a tag that fails the v* check with an error, so a malformed tag would be built or silently skipped")
	}
}

// The watchdog exists for the day the fleet cannot publish its own fix, so
// each property here is one whose loss would bring that day back.
//
// It runs on GitHub's machines, because a watchdog on the fleet is starved by
// the fault it is watching for. It recovers with runner=github, the one path
// that needs nothing from the fleet. It starts the recovery run before it
// cancels anything: the recovery run queues behind the stuck one, so the stuck
// one has to go -- but cancelling main's only publisher with no replacement in
// place is the failure the whole arrangement guards against. And it cancels
// push runs only, never a dispatched one, which is somebody's recovery.
func TestTheDevWatchdogRecoversMainWithoutTheFleet(t *testing.T) {
	body := workflowFiles(t)["dev-watchdog.yml"]
	if body == "" {
		t.Fatal("dev-watchdog.yml is missing; nothing notices when main's CI is starved and :dev goes stale")
	}
	if !strings.Contains(body, "    runs-on: ubuntu-latest\n") || strings.Contains(body, "zoomies-linux-x64\n") {
		t.Error("the watchdog does not run on ubuntu-latest; on the fleet it is starved by the very fault it watches for")
	}
	if !strings.Contains(body, "-f runner=github") {
		t.Error("the watchdog's recovery does not dispatch CI with runner=github; any other runner waits on the fleet")
	}
	if !strings.Contains(body, "event=push") {
		t.Error("the watchdog's cancellation is not limited to push runs; it could cancel a recovery run, its own included")
	}
	dispatch := strings.Index(body, "gh workflow run ci.yml")
	cancel := strings.Index(body, "/cancel\"")
	if dispatch < 0 || cancel < 0 || dispatch > cancel {
		t.Error("the watchdog does not start its recovery run before it cancels; cancelling main's publisher first can leave :dev with nothing to publish it")
	}
	if !strings.Contains(body, "\npermissions: {}\n") {
		t.Error("the watchdog grants permissions at the top; its jobs ask for what they need themselves")
	}
	// This repository's scheduled runs start five to six and a half hours
	// late, longer than the limit the watchdog enforces. Main's CI being
	// requested is what has to start it.
	if !strings.Contains(body, "  workflow_run:\n    workflows: [CI]\n    types: [requested]\n    branches: [main]\n") {
		t.Error("the watchdog is not started by main's CI being requested; on a schedule alone it arrives hours after the limit it enforces")
	}
	if !strings.Contains(body, "github.event.workflow_run.event == 'push'") {
		t.Error("the watchdog waits on dispatched CI runs too; a recovery run, its own included, would be watched and recovered in turn")
	}
	// Wait is skipped for a CI run that was not a push as well as for a tick,
	// so Watch deciding by "Wait was skipped" ran at once for every such run.
	if strings.Contains(body, "needs.wait.result == 'skipped'") || !strings.Contains(body, "github.event_name != 'workflow_run' || needs.wait.outputs.act == 'true'") {
		t.Error("Watch decides whether to run from Wait being skipped; a CI run that was not a push skips Wait too, and Watch must not act on it")
	}
	// The wait holds its job for up to the limit. A workflow-wide group would
	// queue every tick and every newer commit behind it; the group that stops
	// two recoveries starting at once belongs on the job that starts them.
	if strings.Contains(body, "\nconcurrency:") {
		t.Error("the watchdog has a workflow-wide concurrency group; a Wait holding it for hours queues the newest commit's watchdog behind a stale one")
	}
	// GitHub delays or drops scheduled runs when it is busiest, and it names
	// the top of the hour as that moment. The first tick, due at 18:00, never
	// ran.
	cron := regexp.MustCompile(`cron: "([^ "]+) `).FindStringSubmatch(body)
	if cron == nil {
		t.Fatal("the watchdog has no schedule")
	}
	for _, minute := range strings.Split(cron[1], ",") {
		if minute == "0" || minute == "30" || strings.HasPrefix(minute, "*") {
			t.Errorf("the watchdog's schedule fires at minute %q; GitHub delays or drops scheduled runs at the top of the hour, so pick minutes clear of :00 and :30", minute)
		}
	}
}

// Package events is the in-process publish/subscribe bus that makes the UI
// live.
//
// Every state change the operator would want to see -- a runner changing state,
// a scaling decision, a job starting -- is published here, and the API's
// Server-Sent Events endpoint fans it out to browsers. There is no polling
// anywhere in the UI.
package events

import (
	"context"
	"encoding/json"
	"log/slog"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Kind names an event type. The UI switches on these to decide what to update,
// so they are part of the API's contract.
type Kind string

const (
	KindRunnerCreated Kind = "runner.created"
	KindRunnerUpdated Kind = "runner.updated"
	KindRunnerDeleted Kind = "runner.deleted"
	KindPoolCreated   Kind = "pool.created"
	KindPoolUpdated   Kind = "pool.updated"
	KindPoolDeleted   Kind = "pool.deleted"
	KindJobUpdated    Kind = "job.updated"
	KindHostUpdated   Kind = "host.updated"
	KindHostDeleted   Kind = "host.deleted"
	KindScaling       Kind = "scaling"
	KindInstallation  Kind = "installation.updated"
	// KindInstallationDeleted is sent when an installation is removed; the
	// pools that depended on it go with it, each with its own pool.deleted.
	KindInstallationDeleted Kind = "installation.deleted"
	// The provider and machine kinds carry the same JSON their GET routes
	// return, as every other resource frame does. A machine is deleted from
	// the page only when its row goes -- the row outlives the resource on
	// purpose -- so machine.deleted is the prune's frame rather than the
	// hypervisor's.
	KindProviderUpdated Kind = "provider.updated"
	KindProviderDeleted Kind = "provider.deleted"
	KindMachineUpdated  Kind = "machine.updated"
	KindMachineDeleted  Kind = "machine.deleted"
	KindProblems        Kind = "problems.updated"
	KindStats           Kind = "stats"
	KindAudit           Kind = "audit"
	KindWebhook         Kind = "webhook.delivery"
	// KindHeartbeat is an empty keep-alive so that proxies do not close an
	// idle SSE connection.
	KindHeartbeat Kind = "heartbeat"
	// KindResync tells a client that what it holds may be stale and it should
	// fetch the resources afresh: the events between its last ID and now could
	// not all be replayed -- the ring had moved on, or the controller
	// restarted and the IDs began again -- or too much was deleted at once to
	// announce row by row. It is never in the ring, because it is true of the
	// connections it was sent to and of no connection made afterwards; the
	// SSE handler writes its own directly, and the controller sends one with
	// Bus.PublishTransient.
	KindResync Kind = "resync"
)

// Event is one published change.
type Event struct {
	// ID is a monotonic sequence number, sent as the SSE event id so a
	// reconnecting client can say where it left off.
	ID   uint64 `json:"id"`
	Kind Kind   `json:"kind"`
	// Topic narrows the event, e.g. "runner:run_abc" or "pool:pool_xyz".
	// Subscribers may filter on it.
	Topic string `json:"topic,omitempty"`
	// Data is the payload, already marshalled by the publisher.
	Data json.RawMessage `json:"data,omitempty"`
	At   time.Time       `json:"at"`
}

// Bus fans events out to subscribers.
//
// A slow subscriber is cut off rather than allowed to block the publisher: an
// operator whose browser tab is wedged must not stop the fleet from scaling.
// Cut off, not thinned: its feed ends, the SSE handler closes the response,
// and the browser reconnects with its last event ID and catches up from the
// ring. Dropping single events would leave that tab quietly showing a fleet
// that no longer exists, with no polling to ever put it right.
type Bus struct {
	mu     sync.RWMutex
	subs   map[int]*subscriber
	nextID int
	seq    atomic.Uint64

	// epoch names this process's run. Event IDs restart at one with every
	// controller start, so a client's Last-Event-ID from before a restart is
	// a number from a different sequence -- usually one this process has not
	// reached yet, which replayed nothing and said nothing. The epoch travels
	// with the ID on the wire so a client that comes back with the wrong one
	// is told to resynchronise instead.
	epoch string

	// buffer is the per-subscriber queue depth. It is deliberately larger
	// than ringCap: a subscriber is handed the whole replay before it has
	// read a byte, so a queue only as deep as the ring is full at the moment
	// it is created, and the next publish -- one already waiting on this same
	// lock, on a fleet busy enough to have filled the ring -- would drop it.
	// The tab reconnects, replays a full ring again and is dropped again.
	buffer int
	// ring keeps recent events so a client that reconnects within a few
	// seconds does not miss anything.
	ring    []Event
	ringCap int
}

type subscriber struct {
	id     int
	ch     chan Event
	filter func(Event) bool
}

// New returns a bus with sensible queue depths.
func New() *Bus {
	return &Bus{
		subs:    map[int]*subscriber{},
		epoch:   strconv.FormatInt(time.Now().UnixNano(), 36),
		buffer:  512,
		ringCap: 256,
	}
}

// Epoch identifies this process's run of the sequence; see Bus.epoch.
func (b *Bus) Epoch() string { return b.epoch }

// WireID renders an event ID for the wire: the epoch, a dot, the sequence
// number. ParseWireID reads it back.
func (b *Bus) WireID(id uint64) string {
	return b.epoch + "." + strconv.FormatUint(id, 10)
}

// ParseWireID reads a Last-Event-ID the client sent back. It returns the
// sequence number to replay from and whether that number belongs to this
// process's sequence at all; a bare number, from a client that predates the
// epoch, is taken as this epoch's so an upgrade does not resync every tab for
// nothing.
func (b *Bus) ParseWireID(raw string) (id uint64, sameEpoch bool) {
	raw = strings.TrimSpace(raw)
	epoch, seq, dotted := strings.Cut(raw, ".")
	if !dotted {
		seq, epoch = raw, b.epoch
	}
	n, err := strconv.ParseUint(seq, 10, 64)
	if err != nil {
		return 0, false
	}
	return n, epoch == b.epoch
}

// Publish marshals v and delivers it to every matching subscriber. Marshalling
// failures are logged rather than returned, because a publisher in the middle
// of a reconcile has nothing useful to do with the error.
func (b *Bus) Publish(kind Kind, topic string, v any) {
	if e, ok := frame(kind, topic, v); ok {
		b.publish(e, true)
	}
}

// PublishTransient is Publish for a frame that must reach the subscribers who
// are here now and must never be replayed to one that arrives later.
//
// KindResync is the whole of it: it says "what you hold may be stale, fetch
// the resources again", which is true of the tab it was sent to and says
// nothing about a tab that connects afterwards -- that one is already fetching
// everything. Replaying it would send a client that has just loaded the fleet
// straight back to load it again.
func (b *Bus) PublishTransient(kind Kind, topic string, v any) {
	if e, ok := frame(kind, topic, v); ok {
		b.publish(e, false)
	}
}

// frame renders a payload into an unnumbered event, or reports that it could
// not be. The number is publish's to draw, under the lock.
func frame(kind Kind, topic string, v any) (Event, bool) {
	var raw json.RawMessage
	if v != nil {
		enc, err := json.Marshal(v)
		if err != nil {
			slog.Error("events: could not marshal payload", "kind", kind, "error", err)
			return Event{}, false
		}
		raw = enc
	}
	return Event{Kind: kind, Topic: topic, Data: raw, At: time.Now().UTC()}, true
}

// publish numbers the event, appends it to the ring and hands it to every
// subscriber.
//
// The number is drawn here, under the lock, rather than by the caller. Drawing
// it first and taking the lock afterwards let two publishers -- the reconcile
// loop and an API handler, say -- enter the ring in the opposite order to their
// numbers, and the wire with them. A browser handed 6 before 5 reconnects with
// 6 as its last id and never sees 5 again, while Subscribe still reports the
// replay complete because the ring's oldest id is no longer its lowest. There
// is no polling to put that right, so the tab quietly shows a fleet that has
// moved on.
//
// The sends happen under the lock on purpose. Close closes a subscriber's
// channel under that same lock, and a send on a closed channel panics even
// from a select with a default case -- so sending from a snapshot taken
// before releasing the lock let a browser tab closing at the wrong instant
// panic whichever loop was publishing, and the reconcile loop does not come
// back from that. Every send here is non-blocking, so holding the lock costs
// the other publishers microseconds.
// It still draws a number when it is not kept: the number is what a client
// comes back with, and a frame delivered without one would have the client
// resume from before it and be sent the events it has already seen.
func (b *Bus) publish(e Event, keep bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	e.ID = b.seq.Add(1)
	if keep && b.ringCap > 0 {
		b.ring = append(b.ring, e)
		if len(b.ring) > b.ringCap {
			b.ring = b.ring[len(b.ring)-b.ringCap:]
		}
	}

	for _, s := range b.subs {
		if s.filter != nil && !s.filter(e) {
			continue
		}
		select {
		case s.ch <- e:
		default:
			// The subscriber is not keeping up. Ending its feed here, under
			// the same lock Close takes and after removing it from the map,
			// is what stops Close from closing the channel a second time.
			// What it has already been handed stays in the channel for it to
			// drain; only then does it see the end and reconnect.
			slog.Warn("events: subscriber is behind; ending its feed so the client resynchronises",
				"subscriber", s.id, "buffer", b.buffer)
			delete(b.subs, s.id)
			close(s.ch)
		}
	}
}

// Subscription is a live event feed.
type Subscription struct {
	C   <-chan Event
	bus *Bus
	id  int
	// Complete reports whether the subscriber has everything it asked for: a
	// subscription that asked for no replay, or one whose Replay the ring
	// still reached back to. When it is false the client missed events it
	// will never be sent, and the SSE handler tells it so with a resync
	// frame before anything else.
	Complete bool
	// done is closed by Close, so the goroutine Subscribe starts to watch the
	// context ends with the subscription. Without it a subscription closed by
	// hand under a context that never ends -- the SSE handler closes its own
	// before the request's context is cancelled -- left one goroutine waiting
	// per connection for the life of the process.
	done chan struct{}
	// once makes Close idempotent AND race-free. Both matter: Subscribe spawns
	// a goroutine that closes the subscription when the context ends, so an
	// explicit Close from the handler and that goroutine routinely run at the
	// same time. An earlier version cleared s.bus at the end of Close, which
	// was an unsynchronised write to a field the other caller was reading.
	once sync.Once
}

// Close unsubscribes. It is safe to call more than once and from more than one
// goroutine at a time.
func (s *Subscription) Close() {
	if s == nil || s.bus == nil {
		return
	}
	s.once.Do(func() {
		s.bus.mu.Lock()
		if sub, ok := s.bus.subs[s.id]; ok {
			delete(s.bus.subs, s.id)
			close(sub.ch)
		}
		s.bus.mu.Unlock()
		if s.done != nil {
			close(s.done)
		}
	})
}

// SubscribeOptions narrows a subscription.
type SubscribeOptions struct {
	// Kinds, when non-empty, limits delivery to these event kinds.
	Kinds []Kind
	// TopicPrefix, when non-empty, limits delivery to matching topics.
	TopicPrefix string
	// Replay delivers buffered events with an ID greater than this before any
	// new ones, so a reconnecting client can catch up.
	Replay uint64
	// Incomplete says the caller already knows the client missed events --
	// its Last-Event-ID was from another run of the process -- so the
	// subscription is marked incomplete whatever the ring holds.
	Incomplete bool
}

// Subscribe returns a feed. The caller must Close it.
func (b *Bus) Subscribe(ctx context.Context, opts SubscribeOptions) *Subscription {
	s, _ := b.SubscribeWithin(ctx, opts, 0)
	return s
}

// SubscribeWithin is Subscribe with a ceiling on how many feeds may be open,
// reporting false and subscribing nothing when limit are already open. Zero
// is no ceiling.
//
// The count and the subscription are taken under the one lock, so a burst of
// streams opened together cannot all see room for one and all take it.
func (b *Bus) SubscribeWithin(ctx context.Context, opts SubscribeOptions, limit int) (*Subscription, bool) {
	kinds := map[Kind]bool{}
	for _, k := range opts.Kinds {
		kinds[k] = true
	}
	filter := func(e Event) bool {
		if len(kinds) > 0 && !kinds[e.Kind] {
			return false
		}
		if opts.TopicPrefix != "" && !strings.HasPrefix(e.Topic, opts.TopicPrefix) {
			return false
		}
		return true
	}

	b.mu.Lock()
	if limit > 0 && len(b.subs) >= limit {
		b.mu.Unlock()
		return nil, false
	}
	ch := make(chan Event, b.buffer)
	b.nextID++
	sub := &subscriber{id: b.nextID, ch: ch, filter: filter}
	b.subs[sub.id] = sub
	// Replay under the same lock so an event cannot slip between the replay
	// and the subscription taking effect.
	complete := true
	if opts.Replay > 0 {
		// The ring covers the gap when the event after Replay is still in
		// it, or when nothing has been published since. A Replay beyond the
		// sequence is from another run of the process and covers nothing.
		last := b.seq.Load()
		switch {
		case opts.Replay > last:
			complete = false
		case opts.Replay == last:
		case len(b.ring) == 0 || b.ring[0].ID > opts.Replay+1:
			complete = false
		}
		for _, e := range b.ring {
			if e.ID > opts.Replay && filter(e) {
				select {
				case ch <- e:
				default:
					// The queue is deeper than the ring, so this is not
					// reachable -- but a replay that silently dropped a frame
					// while still calling itself complete is the one outcome
					// this whole path exists to prevent, so say so instead.
					complete = false
				}
			}
		}
	}
	if opts.Incomplete {
		complete = false
	}
	b.mu.Unlock()

	s := &Subscription{C: ch, bus: b, id: sub.id, Complete: complete, done: make(chan struct{})}
	if ctx != nil {
		go func() {
			select {
			case <-ctx.Done():
				s.Close()
			case <-s.done:
			}
		}()
	}
	return s, true
}

// Subscribers returns the current subscriber count, which the UI shows on the
// Settings page as a sanity check that live updates are wired up.
func (b *Bus) Subscribers() int {
	b.mu.RLock()
	defer b.mu.RUnlock()
	return len(b.subs)
}

// LastID returns the most recently issued event ID.
func (b *Bus) LastID() uint64 { return b.seq.Load() }

package events

import (
	"context"
	"encoding/json"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"
)

func TestPublishReachesSubscribers(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	b.Publish(KindRunnerUpdated, "runner:run_1", map[string]string{"state": "idle"})

	select {
	case e := <-sub.C:
		if e.Kind != KindRunnerUpdated {
			t.Errorf("kind = %s, want %s", e.Kind, KindRunnerUpdated)
		}
		if e.Topic != "runner:run_1" {
			t.Errorf("topic = %q", e.Topic)
		}
		var got map[string]string
		if err := json.Unmarshal(e.Data, &got); err != nil {
			t.Fatalf("payload: %v", err)
		}
		if got["state"] != "idle" {
			t.Errorf("payload = %v", got)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("no event arrived")
	}
}

func TestSubscribeFiltersByKindAndTopic(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{
		Kinds:       []Kind{KindRunnerUpdated},
		TopicPrefix: "runner:",
	})
	defer sub.Close()

	b.Publish(KindPoolUpdated, "pool:p1", nil)     // wrong kind
	b.Publish(KindRunnerUpdated, "host:h1", nil)   // wrong topic
	b.Publish(KindRunnerUpdated, "runner:r1", nil) // both right

	select {
	case e := <-sub.C:
		if e.Topic != "runner:r1" {
			t.Fatalf("got %s/%s; the filter let the wrong event through", e.Kind, e.Topic)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("the matching event never arrived")
	}
}

func TestReplayDeliversMissedEvents(t *testing.T) {
	b := New()
	b.Publish(KindScaling, "", map[string]int{"n": 1})
	after := b.LastID()
	b.Publish(KindScaling, "", map[string]int{"n": 2})

	// A client reconnecting with Last-Event-ID should be given what it missed.
	sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: after})
	defer sub.Close()

	select {
	case e := <-sub.C:
		if e.ID != after+1 {
			t.Errorf("replayed event ID = %d, want %d", e.ID, after+1)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("nothing was replayed")
	}
}

func TestSlowSubscriberIsCutOffNotBlocking(t *testing.T) {
	b := New()
	b.buffer = 2
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	// A wedged browser tab must not be able to stop the fleet from scaling, so
	// publishing past a full queue never blocks.
	done := make(chan struct{})
	go func() {
		for i := 0; i < 500; i++ {
			b.Publish(KindHeartbeat, "", nil)
		}
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Publish blocked on a subscriber that was not reading")
	}

	// And the subscriber that fell behind is told so, by its feed ending. A
	// stream quietly thinned by dropped events would leave its dashboard wrong
	// until somebody reloaded it; an ended stream makes the browser reconnect
	// and replay. It keeps what it had already been handed.
	received := 0
	for range sub.C {
		received++
	}
	if received != b.buffer {
		t.Fatalf("received %d buffered events before the feed ended, want %d", received, b.buffer)
	}
	if n := b.Subscribers(); n != 0 {
		t.Fatalf("%d subscribers remain after the slow one was cut off, want 0", n)
	}
}

// Subscribe spawns a goroutine that closes the subscription when the context
// ends, so an explicit Close and that goroutine routinely race. Run this with
// -race: it is the regression test for an unsynchronised write in Close.
func TestCloseIsSafeConcurrentlyAndRepeatedly(t *testing.T) {
	b := New()
	for i := 0; i < 50; i++ {
		ctx, cancel := context.WithCancel(context.Background())
		sub := b.Subscribe(ctx, SubscribeOptions{})

		var wg sync.WaitGroup
		wg.Add(3)
		go func() { defer wg.Done(); cancel() }()
		go func() { defer wg.Done(); sub.Close() }()
		go func() { defer wg.Done(); sub.Close() }()
		wg.Wait()
		cancel()
	}
	// Give the context watchers a moment, then assert nothing leaked.
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && b.Subscribers() != 0 {
		time.Sleep(10 * time.Millisecond)
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("%d subscriptions leaked", n)
	}
}

func TestContextCancellationUnsubscribes(t *testing.T) {
	b := New()
	ctx, cancel := context.WithCancel(context.Background())
	b.Subscribe(ctx, SubscribeOptions{})
	if b.Subscribers() != 1 {
		t.Fatalf("subscribers = %d, want 1", b.Subscribers())
	}
	cancel()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && b.Subscribers() != 0 {
		time.Sleep(10 * time.Millisecond)
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("subscribers = %d after cancellation, want 0", n)
	}
}

// A subscriber closing while a publish is in flight is the everyday case: a
// browser tab closes and its SSE handler's context ends while the reconcile
// loop is announcing a state change. Sending on the closed channel panics,
// and the loop that was publishing does not come back from a panic.
func TestPublishRacesClose(t *testing.T) {
	b := New()
	for i := 0; i < 2000; i++ {
		sub := b.Subscribe(context.Background(), SubscribeOptions{})
		var wg sync.WaitGroup
		wg.Add(2)
		go func() {
			defer wg.Done()
			b.Publish(KindRunnerUpdated, "runner:r1", map[string]string{"id": "r1"})
		}()
		go func() {
			defer wg.Done()
			sub.Close()
		}()
		wg.Wait()
	}
	if n := b.Subscribers(); n != 0 {
		t.Errorf("%d subscriptions leaked", n)
	}
}

// Replay used to be silent about what it could not do: a client whose last id
// predated the ring, or whose id came from before a restart, was handed
// nothing and told nothing. Subscribe now says whether the gap was covered.
func TestReplayReportsWhetherItCoveredTheGap(t *testing.T) {
	b := New()
	b.ringCap = 3
	for i := range 6 {
		b.Publish(KindScaling, "", map[string]int{"n": i})
	}
	last := b.LastID()

	cases := []struct {
		name     string
		replay   uint64
		complete bool
	}{
		{"a fresh subscription asks for nothing and misses nothing", 0, true},
		{"the id just before the ring's oldest is covered", last - 3, true},
		{"an id the ring no longer reaches back to is not", 1, false},
		{"the latest id, with nothing since, is covered", last, true},
		{"an id from another run of the process is not", last + 40, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: tc.replay})
			defer sub.Close()
			if sub.Complete != tc.complete {
				t.Fatalf("Complete = %v, want %v", sub.Complete, tc.complete)
			}
		})
	}

	t.Run("a caller that knows better can mark it incomplete", func(t *testing.T) {
		sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: last, Incomplete: true})
		defer sub.Close()
		if sub.Complete {
			t.Fatal("Incomplete was ignored")
		}
	})
}

// IDs restart at one with every process, so an id alone cannot say which
// sequence it came from. On the wire it carries the run's epoch.
func TestWireIDsCarryTheEpoch(t *testing.T) {
	b := New()
	wire := b.WireID(42)
	if !strings.HasPrefix(wire, b.Epoch()+".") || !strings.HasSuffix(wire, ".42") {
		t.Fatalf("WireID(42) = %q, want <epoch>.42", wire)
	}
	if id, same := b.ParseWireID(wire); id != 42 || !same {
		t.Fatalf("ParseWireID(%q) = %d, %v; want 42 in this epoch", wire, id, same)
	}
	if id, same := b.ParseWireID("otherrun.42"); id != 42 || same {
		t.Fatalf("an id from another epoch parsed as %d, %v; want 42 and not this epoch", id, same)
	}
	// A bare number is what a client that predates the epoch sends; it is
	// taken as this epoch's so an upgrade does not resync every tab.
	if id, same := b.ParseWireID("42"); id != 42 || !same {
		t.Fatalf("a bare id parsed as %d, %v", id, same)
	}
	if id, same := b.ParseWireID("not-an-id"); id != 0 || same {
		t.Fatalf("garbage parsed as %d, %v", id, same)
	}
	other := New()
	if other.Epoch() == b.Epoch() {
		t.Fatal("two buses share an epoch; a restart would look like the same run")
	}
}

// Subscribe starts a goroutine to close the subscription when its context
// ends. The SSE handler closes its subscription itself, before the request's
// context is cancelled, and a long-lived caller may pass a context that is
// never cancelled at all; either way that goroutine used to wait for ever, one
// per subscription for the life of the process.
func TestClosingASubscriptionEndsItsContextWatcher(t *testing.T) {
	b := New()
	before := runtime.NumGoroutine()
	for i := 0; i < 50; i++ {
		b.Subscribe(context.Background(), SubscribeOptions{}).Close()
	}
	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before+5 && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	if n := runtime.NumGoroutine(); n > before+5 {
		t.Fatalf("%d goroutines after closing 50 subscriptions, %d before them", n, before)
	}
}

// The ring and the wire have to agree with the sequence.
//
// Every event carries the number a reconnecting client comes back with, and
// the SSE handler replays everything above it. So an event that reaches the
// ring after one numbered above it is an event that client will never be sent
// -- and Subscribe, which reads the ring's first entry as the oldest number it
// holds, would still call the replay complete and send no resync. The number
// used to be drawn before the lock, which is exactly the window two publishers
// need to swap places.
func TestConcurrentPublishesKeepTheRingInSequence(t *testing.T) {
	b := New()
	const writers, each = 8, 64

	var wg sync.WaitGroup
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < each; i++ {
				b.Publish(KindStats, "", map[string]int{"n": i})
			}
		}()
	}
	wg.Wait()

	b.mu.RLock()
	ring := append([]Event(nil), b.ring...)
	b.mu.RUnlock()

	if len(ring) == 0 {
		t.Fatal("nothing reached the ring")
	}
	for i := 1; i < len(ring); i++ {
		if ring[i].ID <= ring[i-1].ID {
			t.Fatalf("ring entry %d has id %d, after id %d: a client resuming from the higher one never sees the lower",
				i, ring[i].ID, ring[i-1].ID)
		}
	}
	if got, want := ring[len(ring)-1].ID, uint64(writers*each); got != want {
		t.Fatalf("the last event is %d, want %d", got, want)
	}
}

// A tab reconnecting to a busy fleet must not be cut off by its own replay.
//
// The replay is delivered before the subscriber has read anything, so a queue
// only as deep as the ring is full the instant the subscription exists. The
// next publish then finds no room and ends the feed -- and the tab reconnects
// to a ring that is still full and is ended again, on the fleet that most
// needs watching.
func TestAFullReplayLeavesRoomForTheNextEvent(t *testing.T) {
	b := New()
	// One more than the ring holds, so a replay from the first id reaches
	// back to the oldest entry still in it and carries every one of them.
	for i := 0; i <= b.ringCap; i++ {
		b.Publish(KindStats, "", map[string]int{"n": i})
	}

	sub := b.Subscribe(context.Background(), SubscribeOptions{Replay: 1})
	defer sub.Close()
	if !sub.Complete {
		t.Fatal("a replay reaching back to the oldest event in the ring reported itself incomplete")
	}

	b.Publish(KindStats, "", map[string]int{"n": -1})
	for i := 0; i < b.ringCap; i++ {
		if _, ok := <-sub.C; !ok {
			t.Fatalf("the feed ended after %d replayed events; the subscriber was dropped by its own replay", i)
		}
	}
	if _, ok := <-sub.C; !ok {
		t.Fatal("the feed ended before the event published after the replay")
	}
}

// A resync is about the connections it was sent to and about no other.
//
// It means "what you hold may be stale, fetch the resources again", which is
// never true of a client that connects afterwards -- that one is already
// fetching everything. Kept in the ring, the prune's resync would meet each
// new tab on its first reconnect and send it straight back to load a fleet it
// had only just loaded.
func TestATransientEventReachesSubscribersWithoutEnteringTheRing(t *testing.T) {
	b := New()
	sub := b.Subscribe(context.Background(), SubscribeOptions{})
	defer sub.Close()

	b.PublishTransient(KindResync, "", map[string]string{"reason": "everything went"})

	select {
	case ev := <-sub.C:
		if ev.Kind != KindResync {
			t.Fatalf("the subscriber got %q, want a resync", ev.Kind)
		}
		if ev.ID == 0 {
			t.Fatal("a transient event carried no id, so a client resuming from it would be sent what it has already seen")
		}
	case <-time.After(time.Second):
		t.Fatal("the subscriber never got the transient event")
	}

	b.mu.RLock()
	ring := append([]Event(nil), b.ring...)
	b.mu.RUnlock()
	for _, e := range ring {
		if e.Kind == KindResync {
			t.Fatal("the resync is in the ring; a client reconnecting later would be told to refetch for nothing")
		}
	}

	// The number it drew still belongs to the sequence, so an ordinary event
	// published after it follows on.
	b.Publish(KindStats, "", map[string]int{"n": 1})
	later := b.Subscribe(context.Background(), SubscribeOptions{Replay: 1})
	defer later.Close()
	if !later.Complete {
		t.Fatal("a replay across the transient event reported itself incomplete")
	}
}

package events

import (
	"context"
	"testing"
)

// limits.event_subscribers is enforced here rather than by counting first and
// subscribing after, so that the ceiling holds for streams opened together.
// Closing one has to give its place back, or a browser that reconnects would
// find the instance permanently full of its own dead streams.
func TestSubscribeWithinRefusesAtTheCeilingAndFreesAPlaceOnClose(t *testing.T) {
	b := New()
	ctx := context.Background()

	first, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2)
	if !ok {
		t.Fatal("the first subscription was refused under a ceiling of 2")
	}
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); !ok {
		t.Fatal("the second subscription was refused under a ceiling of 2")
	}
	if s, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); ok || s != nil {
		t.Fatalf("a third subscription was admitted under a ceiling of 2 (%d open)", b.Subscribers())
	}
	if n := b.Subscribers(); n != 2 {
		t.Fatalf("a refused subscription was still counted: %d open", n)
	}

	first.Close()
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 2); !ok {
		t.Fatal("closing a subscription did not free its place")
	}
	if _, ok := b.SubscribeWithin(ctx, SubscribeOptions{}, 0); !ok {
		t.Fatal("a ceiling of 0 refused a subscription; 0 is unlimited")
	}
}

// Package gateway publishes one private service -- a hypervisor's API on a
// home network, typically -- to a controller over Tailcat.
//
// It is the provider-side half of what internal/agent's private transport is
// for hosts, with the direction reversed. A host connects outbound to the
// controller, so the controller listens inside the tunnel. A provider is
// something the controller connects to, so the gateway listens instead: it
// runs beside the hypervisor, on any machine that can reach its API, and
// forwards every TCP connection that arrives through the tunnel to that one
// address. The controller keeps the gateway's address sealed beside the
// provider's credential and dials through it.
//
// The gateway exposes exactly the target and nothing else. There is no port
// on the operating system, no route to the LAN and no way to ask it for a
// second destination: a client that holds the address can open connections to
// the target, which is why the address is treated as a credential everywhere
// it is handled. TLS is not terminated here -- the controller still verifies
// the hypervisor's certificate end to end, so the gateway learns nothing about
// the API token that passes through it.
package gateway

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/tailscale/tailcat"
	"tailscale.com/tailcfg"
)

// StateFile is the identity, kept in the state directory. Losing it changes
// the address, and every provider row pointing at this gateway with it.
const StateFile = "gateway.json"

// dialTimeout bounds one forwarded connection's dial of the target. The
// controller has its own budget for the request; this is only so that a target
// that has gone away frees the tunnel's side promptly.
const dialTimeout = 10 * time.Second

// relayTimeout bounds relay discovery at startup, which the upstream library
// otherwise does with a background context.
const relayTimeout = 20 * time.Second

// Options is what a gateway needs.
type Options struct {
	// Target is the host:port every forwarded connection goes to, as the
	// machine running the gateway reaches it: "192.168.1.10:8006".
	Target string
	// StateDir is where the identity is kept. The address printed at startup
	// is derived from it, so a gateway restarted from the same directory
	// keeps its address.
	StateDir string
	// Region, when set, is the relay to use instead of discovering one. Tests
	// point it at a local relay; production leaves it nil.
	Region *tailcfg.DERPRegion
	Logger *slog.Logger
}

// Gateway is one running tunnel end.
type Gateway struct {
	node    *tailcat.Server
	address string
	target  string
	log     *slog.Logger
	closed  chan struct{}
	once    sync.Once
	active  sync.WaitGroup
}

// StatePath is where a gateway in the given directory keeps its identity.
func StatePath(dir string) string { return filepath.Join(dir, StateFile) }

// ParseTarget checks a target the way Start will use it, so a command can
// refuse a bad one before touching the network or the state directory.
func ParseTarget(raw string) (string, error) {
	target := strings.TrimSpace(raw)
	if target == "" {
		return "", errors.New("gateway: no target; give the address the hypervisor's API answers on, as this machine reaches it, e.g. --target 192.168.1.10:8006")
	}
	if strings.Contains(target, "://") {
		return "", fmt.Errorf("gateway: the target is a host and port, not a URL: write %q without the scheme and path", target)
	}
	host, port, err := net.SplitHostPort(target)
	if err != nil || host == "" || port == "" {
		return "", fmt.Errorf("gateway: %q is not host:port; a Proxmox API is usually on port 8006, e.g. 192.168.1.10:8006", target)
	}
	return net.JoinHostPort(host, port), nil
}

// Start loads or creates the identity, joins the relay and begins forwarding.
//
// The address it returns is a capability: whoever holds it can open
// connections to the target. It goes to the operator once, to paste into the
// provider's form, and nowhere else -- not into the log, which is why the
// upstream library's own logging is discarded.
func Start(ctx context.Context, opts Options) (*Gateway, error) {
	target, err := ParseTarget(opts.Target)
	if err != nil {
		return nil, err
	}
	log := opts.Logger
	if log == nil {
		log = slog.Default()
	}
	log = log.With("component", "gateway")
	if opts.StateDir == "" {
		return nil, errors.New("gateway: no state directory; the identity that keeps the address stable across restarts has to live somewhere")
	}

	identity, fresh, err := loadIdentity(StatePath(opts.StateDir))
	if err != nil {
		return nil, err
	}
	if opts.Region != nil {
		identity.Public.Region = []*tailcfg.DERPRegion{opts.Region}
	}
	if len(identity.Public.Region) == 0 {
		// Resolve the relay with a bounded context before Start, which
		// otherwise performs discovery with a background context inside the
		// upstream library. The region is saved with the identity so that
		// the address, which embeds it, is the same after a restart.
		identity.Public.RegionID = -1
		resolveCtx, cancel := context.WithTimeout(ctx, relayTimeout)
		defer cancel()
		if err := identity.Public.Expand(resolveCtx, tailcat.ExpandForServer); err != nil {
			return nil, errors.New("gateway: cannot reach a Tailcat relay; check this machine's outbound internet access and try again")
		}
		fresh = true
	}

	g := &Gateway{target: target, log: log, closed: make(chan struct{})}
	g.node = &tailcat.Server{
		Key:          identity.Private,
		PresharedKey: identity.Public.PresharedKey,
		Region:       identity.Public.Region[0],
		Logf:         func(string, ...any) {},
		// Every port forwards to the one target. Refusing all but one would
		// only add a way for the endpoint an operator typed on the controller
		// and the target they typed here to disagree, with a reset and no
		// message as the symptom; there is one destination either way.
		OnTCP: func(uint16) func(net.Conn) { return g.forward },
	}
	if err := g.node.Start(); err != nil {
		return nil, errors.New("gateway: cannot start the private connection; check network-interface permissions and outbound internet access, then try again")
	}
	if fresh {
		if err := saveIdentity(StatePath(opts.StateDir), identity); err != nil {
			_ = g.node.Close()
			return nil, err
		}
	}
	g.address = string(identity.Public.Addr())
	return g, nil
}

// Address is the capability a controller needs to reach the target.
func (g *Gateway) Address() string { return g.address }

// Target is what forwarded connections go to.
func (g *Gateway) Target() string { return g.target }

// Close stops accepting connections and cuts the ones in flight. A controller
// mid-request sees a closed connection and retries on its own schedule, as it
// does for any hypervisor that went away.
func (g *Gateway) Close() error {
	g.once.Do(func() {
		close(g.closed)
		_ = g.node.Close()
	})
	g.active.Wait()
	return nil
}

// forward carries one tunnelled connection to the target and back.
func (g *Gateway) forward(tunnel net.Conn) {
	g.active.Add(1)
	defer g.active.Done()
	defer tunnel.Close()
	select {
	case <-g.closed:
		return
	default:
	}
	ctx, cancel := context.WithTimeout(context.Background(), dialTimeout)
	defer cancel()
	local, err := (&net.Dialer{}).DialContext(ctx, "tcp", g.target)
	if err != nil {
		// The one failure worth a log line: the tunnel is up and the thing
		// behind it is not, which is what an operator staring at "provider
		// unreachable" on the controller needs to hear from this side.
		g.log.Warn("cannot reach the target behind the gateway; the controller will see the provider as unreachable",
			"target", g.target, "error", err.Error())
		return
	}
	defer local.Close()
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(local, tunnel); closeWrite(local); done <- struct{}{} }()
	go func() { _, _ = io.Copy(tunnel, local); closeWrite(tunnel); done <- struct{}{} }()
	select {
	case <-done:
	case <-g.closed:
		return
	}
	select {
	case <-done:
	case <-g.closed:
	}
}

func closeWrite(c net.Conn) {
	if cw, ok := c.(interface{ CloseWrite() error }); ok {
		_ = cw.CloseWrite()
		return
	}
	_ = c.Close()
}

// loadIdentity reads the saved identity, or makes a new one when there is
// none. fresh says the caller has to save it.
//
// A world-readable identity file is refused rather than used, as the agent's
// credentials file is: it is the address, and the address is the capability.
func loadIdentity(path string) (identity *tailcat.PrivateKey, fresh bool, err error) {
	info, err := os.Stat(path)
	if errors.Is(err, os.ErrNotExist) {
		return tailcat.NewPrivateKey(), true, nil
	}
	if err != nil {
		return nil, false, fmt.Errorf("gateway: reading the identity at %s: %w", path, err)
	}
	if info.Mode().Perm()&0o077 != 0 {
		return nil, false, fmt.Errorf("gateway: the identity at %s is readable by other users, and it is the address a controller uses to reach the target; run chmod 600 on it", path)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, false, fmt.Errorf("gateway: reading the identity at %s: %w", path, err)
	}
	identity = &tailcat.PrivateKey{}
	if json.Unmarshal(raw, identity) != nil || identity.Private.IsZero() || identity.Public.PresharedKey.IsZero() {
		return nil, false, fmt.Errorf("gateway: the identity at %s is incomplete; move it aside to start with a new address, then update the provider on the controller with it", path)
	}
	return identity, false, nil
}

// saveIdentity writes the identity with mode 0600, atomically, so a crash
// between two writes cannot leave a half-written address behind.
func saveIdentity(path string, identity *tailcat.PrivateKey) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("gateway: creating the state directory %s: %w", dir, err)
	}
	raw, err := json.MarshalIndent(identity, "", "  ")
	if err != nil {
		return fmt.Errorf("gateway: encoding the identity: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".gateway-*.json")
	if err != nil {
		return fmt.Errorf("gateway: creating a temporary file in %s: %w", dir, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) // no-op once the rename has succeeded
	if err := tmp.Chmod(0o600); err != nil {
		tmp.Close()
		return fmt.Errorf("gateway: setting permissions on %s: %w", tmpName, err)
	}
	if _, err := tmp.Write(append(raw, '\n')); err != nil {
		tmp.Close()
		return fmt.Errorf("gateway: writing %s: %w", tmpName, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("gateway: closing %s: %w", tmpName, err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("gateway: moving the identity into place at %s: %w", path, err)
	}
	return nil
}

