func TestTargetsAreHostAndPortAndNothingElse(t *testing.T) {
	for _, bad := range []string{"", "https://pve:8006", "pve", ":8006", "pve:"} {
		if _, err := ParseTarget(bad); err == nil {
			t.Errorf("%q was accepted", bad)
		}
	}
	got, err := ParseTarget(" 192.168.1.10:8006 ")
	if err != nil || got != "192.168.1.10:8006" {
		t.Fatalf("ParseTarget = %q, %v", got, err)
	}
}

// The identity is the address, and the address is a capability to open
// connections to the target, so it is kept the way the agent keeps its token.
func TestIdentityIsPrivateAndRefusedWhenItIsNot(t *testing.T) {
	dir := t.TempDir()
	path := StatePath(dir)
	identity := tailcat.NewPrivateKey()
	if err := saveIdentity(path, identity); err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm() != 0o600 {
		t.Fatalf("identity saved with mode %o", info.Mode().Perm())
	}
	loaded, fresh, err := loadIdentity(path)
	if err != nil || fresh {
		t.Fatalf("loadIdentity = fresh %v, %v", fresh, err)
	}
	if !loaded.Private.Equal(identity.Private) || !loaded.Public.PresharedKey.Equal(identity.Public.PresharedKey) {
		t.Fatal("the identity did not survive a round trip")
	}
	if err := os.Chmod(path, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadIdentity(path); err == nil || !strings.Contains(err.Error(), "chmod 600") {
		t.Fatalf("a world-readable identity was used: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "broken.json"), []byte("{}"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, _, err := loadIdentity(filepath.Join(dir, "broken.json")); err == nil {
		t.Fatal("an empty identity was used")
	}
	if _, fresh, err := loadIdentity(filepath.Join(dir, "absent.json")); err != nil || !fresh {
		t.Fatalf("a missing identity is a fresh start: fresh %v, %v", fresh, err)
	}
}

// A local DERP relay exercises the real data path: a TLS server that only the
// gateway can reach, a client that holds nothing but the address, and the
// hypervisor's certificate verified end to end through the tunnel.
func TestGatewayForwardsTheTunnelToItsTargetAndKeepsItsAddressAcrossRestarts(t *testing.T) {
	t.Setenv("IN_TS_TEST", "true")
	dm := integration.RunDERPAndSTUN(t, func(string, ...any) {}, "127.0.0.1")
	target := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.WriteString(w, "hello from "+r.Host)
	}))
	defer target.Close()
	dir := t.TempDir()
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()

	g, err := Start(ctx, Options{Target: target.Listener.Addr().String(), StateDir: dir, Region: dm.Regions[1]})
	if err != nil {
		t.Fatal(err)
	}
	address := g.Address()
	if !strings.HasPrefix(address, "tc") {
		t.Fatalf("address %q is not a Tailcat address", address)
	}

	client := tailcat.NewClient(tailcat.Addr(address))
	client.Logf = func(string, ...any) {}
	defer client.Close()
	pool := target.Client().Transport.(*http.Transport).TLSClientConfig.RootCAs
	httpClient := &http.Client{Transport: &http.Transport{
		TLSClientConfig: &tls.Config{RootCAs: pool},
		DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return client.DialTCPPort(ctx, 8006)
		},
	}}
	// example.com is the name httptest's certificate is issued for, and it
	// does not resolve to the target: only the tunnel gets there.
	res, err := httpClient.Get("https://example.com:8006/version")
	if err != nil {
		t.Fatalf("through the gateway: %v", err)
	}
	body, _ := io.ReadAll(res.Body)
	res.Body.Close()
	if string(body) != "hello from example.com:8006" {
		t.Fatalf("got %q", body)
	}

	// The same directory is the same address, which is what lets a provider
	// row outlive a reboot of the machine the gateway runs on.
	if err := g.Close(); err != nil {
		t.Fatal(err)
	}
	again, err := Start(ctx, Options{Target: target.Listener.Addr().String(), StateDir: dir})
	if err != nil {
		t.Fatal(err)
	}
	defer again.Close()
	if again.Address() != address {
		t.Fatal("restarting the gateway changed its address")
	}
}

package github

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/coreos/go-oidc/v3/oidc"
)

// ActionsIssuer is the issuer of GitHub.com's Actions OIDC tokens. A token from
// any other issuer is not a statement GitHub made about a workflow run.
const ActionsIssuer = "https://token.actions.githubusercontent.com"

// ActionsClaims are the parts of an Actions OIDC token Zoomies decides on. Each
// is something GitHub asserts about the run, not something the workflow chose:
// a step can ask for a token but cannot change what it says.
type ActionsClaims struct {
	ID                string
	Expiry            time.Time
	Repository        string `json:"repository"`
	RepositoryID      string `json:"repository_id"`
	RepositoryOwnerID string `json:"repository_owner_id"`
	Ref               string `json:"ref"`
	SHA               string `json:"sha"`
	EventName         string `json:"event_name"`
	JobWorkflowRef    string `json:"job_workflow_ref"`
	RunID             string `json:"run_id"`
	RunAttempt        string `json:"run_attempt"`
}

// ActionsTokenVerifier checks an Actions OIDC token's signature against the
// issuer's published keys, and its issuer, audience and expiry.
type ActionsTokenVerifier struct {
	issuer string
	once   sync.Once
	keys   oidc.KeySet
}

// NewActionsTokenVerifier verifies tokens from issuer; production passes
// ActionsIssuer, and tests a local one. The keys are fetched on first use and
// cached by go-oidc, which refetches when it sees a key it does not know --
// GitHub rotates them.
func NewActionsTokenVerifier(issuer string) *ActionsTokenVerifier {
	return &ActionsTokenVerifier{issuer: strings.TrimRight(issuer, "/")}
}

// ErrActionsToken is returned for any token that is not a valid, current
// Actions token for this audience. The cause is wrapped for the log only.
var ErrActionsToken = errors.New("the upload's GitHub Actions OIDC token is not valid for this controller")

// Verify returns the claims of a token minted for audience. The audience is
// the controller's own upload address, so a token minted for one Zoomies is
// useless against another.
func (v *ActionsTokenVerifier) Verify(ctx context.Context, raw, audience string) (*ActionsClaims, error) {
	v.once.Do(func() {
		// Its own context: the key set outlives the request that created it.
		v.keys = oidc.NewRemoteKeySet(context.WithoutCancel(ctx), v.issuer+"/.well-known/jwks")
	})
	verifier := oidc.NewVerifier(v.issuer, v.keys, &oidc.Config{ClientID: audience, SupportedSigningAlgs: []string{oidc.RS256}})
	token, err := verifier.Verify(ctx, raw)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrActionsToken, err)
	}
	var claims ActionsClaims
	if err := token.Claims(&claims); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrActionsToken, err)
	}
	var id struct {
		JTI string `json:"jti"`
	}
	if err := token.Claims(&id); err != nil || id.JTI == "" || len(id.JTI) > 200 {
		return nil, fmt.Errorf("%w: it carries no token ID, so it could be replayed", ErrActionsToken)
	}
	claims.ID, claims.Expiry = id.JTI, token.Expiry
	return &claims, nil
}

package github

import (
	"errors"
	"testing"
	"time"
)

func TestActionsTokensAreBoundToTheirIssuerAudienceAndLifetime(t *testing.T) {
	issuer := NewFakeActionsIssuer(t)
	verifier := NewActionsTokenVerifier(issuer.URL)
	const audience = "https://zoomies.example.com/api/v1/ai-context/uploads"

	claims, err := verifier.Verify(t.Context(), issuer.Sign(t, map[string]any{"aud": audience, "repository_id": "42", "sha": "abc", "jti": "one"}), audience)
	if err != nil {
		t.Fatal(err)
	}
	if claims.RepositoryID != "42" || claims.SHA != "abc" || claims.ID != "one" {
		t.Fatalf("claims %+v", claims)
	}

	for name, token := range map[string]string{
		"another controller's audience": issuer.Sign(t, map[string]any{"aud": "https://elsewhere.example.com/api/v1/ai-context/uploads"}),
		"expired":                       issuer.Sign(t, map[string]any{"aud": audience, "exp": time.Now().Add(-time.Minute).Unix()}),
		"another issuer":                issuer.Sign(t, map[string]any{"aud": audience, "iss": "https://token.actions.example.com"}),
		"no token ID":                   issuer.Sign(t, map[string]any{"aud": audience, "jti": ""}),
	} {
		if _, err := verifier.Verify(t.Context(), token, audience); !errors.Is(err, ErrActionsToken) {
			t.Errorf("%s: accepted (%v)", name, err)
		}
	}

	forged := NewFakeActionsIssuer(t)
	token := forged.Sign(t, map[string]any{"aud": audience, "iss": issuer.URL})
	if _, err := verifier.Verify(t.Context(), token, audience); !errors.Is(err, ErrActionsToken) {
		t.Errorf("a token signed with someone else's key was accepted: %v", err)
	}
}

