// One sweep of a hundred-repository organisation used to cost two run listings
// per repository before a single job was looked at -- every thirty seconds, in
// exactly the failure the poller exists for -- which spent the installation's
// hourly quota in about ten minutes. The sweep now has a request budget, and
// spends it on the repositories pushed to most recently.
func TestPollStaysWithinItsRequestBudgetAndLooksAtBusyRepositoriesFirst(t *testing.T) {
	f := newFake(t)
	// Forty quiet repositories the installation can see, added before any job
	// is queued so they are the least recently pushed.
	for i := range 40 {
		f.AddRepo(fmt.Sprintf("acme/quiet-%02d", i))
	}
	f.AddQueuedJob("acme/busy-a", "CI", "build", []string{"linux"})
	f.AddQueuedJob("acme/busy-b", "CI", "build", []string{"linux"})

	jobs, err := f.Client("acme", store.TargetOrg).ListQueuedJobs(context.Background())
	if err != nil {
		t.Fatalf("ListQueuedJobs: %v", err)
	}
	if len(jobs) != 2 {
		t.Fatalf("got %d jobs, want the two in the busy repositories: %+v", len(jobs), jobs)
	}
	requests := f.Requests()
	if len(requests) > maxPollRequests {
		t.Fatalf("the sweep made %d requests, over its budget of %d", len(requests), maxPollRequests)
	}
	// The repository listing comes first; the run listings that follow start
	// with the repositories that were pushed to.
	var order []string
	for _, r := range requests {
		if strings.Contains(r, "/actions/runs") && !strings.Contains(r, "/jobs") {
			order = append(order, r)
		}
	}
	if len(order) < 2 || !strings.Contains(order[0], "acme/busy-") || !strings.Contains(order[1], "acme/busy-") {
		t.Fatalf("run listings did not start with the busy repositories: %v", order[:min(4, len(order))])
	}
}

// pagedRunServer serves one queued run of acme/widgets whose jobs come in pages
// of pollPerPage, the way GitHub serves a large matrix. The fake does not page,
// so this drives appClient against its own handler. jobPages bounds the listing;
// a negative value never ends it. It returns the client and a counter of every
// request made.
func pagedRunServer(t *testing.T, jobPages int) (*appClient, *atomic.Int32) {
	t.Helper()
	var requests atomic.Int32
	var srv *httptest.Server
	srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests.Add(1)
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.URL.Path == "/repos/acme/widgets/actions/runs":
			if r.URL.Query().Get("status") != "queued" {
				_, _ = w.Write([]byte(`{"total_count":0,"workflow_runs":[]}`))
				return
			}
			_, _ = w.Write([]byte(`{"total_count":1,"workflow_runs":[{"id":1,"run_number":7,"name":"CI","created_at":"2024-05-01T10:00:00Z"}]}`))
		case r.URL.Path == "/repos/acme/widgets/actions/runs/1/jobs":
			page := 1
			if p := r.URL.Query().Get("page"); p != "" {
				page, _ = strconv.Atoi(p)
			}
			if jobPages < 0 || page < jobPages {
				w.Header().Set("Link", fmt.Sprintf(`<%s%s?page=%d&per_page=%d>; rel="next"`, srv.URL, r.URL.Path, page+1, pollPerPage))
			}
			var jobs []string
			for i := range pollPerPage {
				id := (page-1)*pollPerPage + i + 1
				jobs = append(jobs, fmt.Sprintf(`{"id":%d,"status":"queued","name":"build-%d","labels":["self-hosted"],"created_at":"2024-05-01T10:00:00Z"}`, id, id))
			}
			_, _ = fmt.Fprintf(w, `{"total_count":0,"jobs":[%s]}`, strings.Join(jobs, ","))
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(srv.Close)
	c, err := newGitHubClient(srv.Client(), srv.URL+"/", srv.URL+"/")
	if err != nil {
		t.Fatal(err)
	}
	return newAppClient(c, c, "acme/widgets", store.TargetRepo, 1, "https://github.com"), &requests
}

// GitHub allows a matrix of 256 jobs in one run, and completed jobs stay in the
// listing, so the tail beyond the first page is never seen by a poller that
// reads only that page -- not even once the head has finished. The poller is
// the safety net for a missed delivery, and a missed delivery is exactly when
// the tail of a large matrix would otherwise never get a runner.
func TestThePollerReadsEveryPageOfALargeRunsJobs(t *testing.T) {
	c, requests := pagedRunServer(t, 3)

	jobs, err := c.ListQueuedJobs(context.Background())
	if err != nil {
		t.Fatalf("ListQueuedJobs: %v", err)
	}
	if want := 3 * pollPerPage; len(jobs) != want {
		t.Fatalf("found %d jobs, want all %d across three pages", len(jobs), want)
	}
	// Two run listings (queued, in progress) and one request per job page.
	if n := requests.Load(); n != 5 {
		t.Fatalf("the sweep made %d requests, want 5", n)
	}
}

// Paging must not undo the request budget that keeps one sweep from spending
// the installation's hourly quota: a run that never stops paging is cut off
// and the jobs already found are still returned.
func TestPagingThroughARunsJobsStaysWithinTheSweepsRequestBudget(t *testing.T) {
	c, requests := pagedRunServer(t, -1)

	jobs, err := c.ListQueuedJobs(context.Background())
	if err != nil {
		t.Fatalf("ListQueuedJobs: %v", err)
	}
	if len(jobs) < 2*pollPerPage {
		t.Fatalf("found %d jobs; the pages read before the budget ran out should still count", len(jobs))
	}
	if n := int(requests.Load()); n > maxPollRequests {
		t.Fatalf("the sweep made %d requests, over its budget of %d", n, maxPollRequests)
	}
}

// A rate limit that lands on the installation token refresh is the one a real
// fleet meets first: every background sweep mints a token before it does
// anything else, so the quota usually runs out there rather than on the call
// the sweep was making. ghinstallation refreshes the token inside the
// transport, so its refusal arrives as its own error with no go-github
// response attached -- and until this was classified, the controller's
// per-installation stand-down never engaged for it.
func TestARateLimitedTokenRefreshIsStillARateLimit(t *testing.T) {
	reset := time.Now().Add(12 * time.Minute).Truncate(time.Second)
	err := classify(nil, fmt.Errorf("listing the queued jobs: %w", tokenRefusal(t, http.StatusForbidden, "0", reset)))

	if !errors.Is(err, ErrRateLimited) {
		t.Fatalf("classify(a refused token refresh with no quota left) = %v, want a rate limit", err)
	}
	var rl *RateLimitedError
	if !errors.As(err, &rl) || !rl.ResetAt.Equal(reset.UTC()) {
		t.Fatalf("the rate limit says it resets at %v, want %v: the caller waits exactly as long as GitHub asked",
			rl.ResetAt, reset.UTC())
	}
}

// And the refusal that is not about quota must not be read as one. A 403 for a
// permission the App has not been granted comes back with its quota intact,
// and standing the installation down for fifteen minutes over it would be a
// wait that fixes nothing.
func TestARefusedTokenRefreshWithQuotaLeftIsNotARateLimit(t *testing.T) {
	err := classify(nil, tokenRefusal(t, http.StatusForbidden, "4999", time.Now()))
	if errors.Is(err, ErrRateLimited) {
		t.Fatalf("classify(a 403 with quota to spare) = %v, want it left alone", err)
	}
}

// tokenRefusal is what ghinstallation hands back when GitHub refuses to mint
// an installation token.
func tokenRefusal(t *testing.T, status int, remaining string, reset time.Time) error {
	t.Helper()
	resp := &http.Response{StatusCode: status, Header: http.Header{}}
	resp.Header.Set("X-RateLimit-Limit", "5000")
	resp.Header.Set("X-RateLimit-Remaining", remaining)
	resp.Header.Set("X-RateLimit-Reset", strconv.FormatInt(reset.Unix(), 10))
	return &ghinstallation.HTTPError{
		Message:  fmt.Sprintf("received non 2xx response status %d when fetching the access token", status),
		Response: resp,
	}
}

package github

import (
	"errors"
	"net/http"
	"net/url"
	"strings"
	"testing"

	gh "github.com/google/go-github/v88/github"
)

// GitHub's 401, 403, 404 and 429 all became sentences an operator can act on;
// a 422 -- a runner name already taken, a label GitHub will not accept -- fell
// through as go-github's raw "422 Validation Failed", which is what a runner
// row then showed as the reason it never started.
func TestAValidationFailureSaysWhatGitHubObjectedTo(t *testing.T) {
	cases := []struct {
		name string
		errs []gh.Error
		msg  string
		want string
	}{
		{
			name: "a message per field",
			errs: []gh.Error{{Resource: "Runner", Field: "name", Code: "already_exists", Message: "A runner with this name already exists"}},
			msg:  "Validation Failed",
			want: "A runner with this name already exists",
		},
		{
			name: "a code where there is no message",
			errs: []gh.Error{{Resource: "Runner", Field: "labels", Code: "invalid"}},
			msg:  "Validation Failed",
			want: "Runner labels invalid",
		},
		{
			name: "nothing but the message",
			msg:  "Validation Failed",
			want: "Validation Failed",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := classify(nil, validationError(tc.msg, tc.errs))
			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("classify = %v, want it to match ErrInvalid", err)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("classify = %q, want it to carry %q", err, tc.want)
			}
		})
	}
}

// The statuses that already had answers keep them: a 422 must not swallow the
// ones a caller branches on.
func TestClassifyKeepsTheOtherStatusesApart(t *testing.T) {
	for status, want := range map[int]error{
		http.StatusNotFound:            ErrNotFound,
		http.StatusForbidden:           ErrForbidden,
		http.StatusTooManyRequests:     ErrRateLimited,
		http.StatusUnprocessableEntity: ErrInvalid,
	} {
		err := classify(nil, &gh.ErrorResponse{Response: response(status), Message: "nope"})
		if !errors.Is(err, want) {
			t.Errorf("classify(%d) = %v, want %v", status, err, want)
		}
	}
}

func validationError(message string, errs []gh.Error) *gh.ErrorResponse {
	return &gh.ErrorResponse{
		Response: response(http.StatusUnprocessableEntity),
		Message:  message,
		Errors:   errs,
	}
}

func response(status int) *http.Response {
	return &http.Response{
		StatusCode: status,
		Request:    &http.Request{Method: http.MethodPost, URL: &url.URL{Scheme: "https", Host: "api.github.com", Path: "/repos/acme/widgets/actions/runners"}},
	}
}

// Package github wraps everything Zoomies needs from the GitHub API: App
// authentication, minting runner credentials, listing runners and queued jobs,
// and validating inbound webhooks.
//
// Zoomies never asks an operator for a personal access token. It authenticates
// as a GitHub App and mints short-lived registration credentials itself, so
// there is no long-lived token sitting in a dotfile next to a runner.
package github

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// ErrNotFound is returned when GitHub reports a 404 for something Zoomies
// expected to exist.
var ErrNotFound = errors.New("github: not found")

// ErrRateLimited is returned when the installation has exhausted its quota.
// The caller backs off rather than hammering.
var ErrRateLimited = errors.New("github: rate limited")

// RateLimitedError is a refusal that says when to come back.
//
// GitHub sends the answer on every rate-limited response -- a reset instant on
// the primary limit, a retry-after duration on the secondary one -- and it used
// to be formatted straight into the message and lost, leaving every caller to
// guess a fixed wait. Guessing long wastes quota that came back minutes ago;
// guessing short spends the next window on refusals. So the number is carried.
//
// It wraps ErrRateLimited, so the callers that only ask "was this a rate limit"
// keep working through errors.Is and only the ones that want the time reach for
// errors.As.
type RateLimitedError struct {
	// ResetAt is when the quota refills, zero when GitHub did not say.
	ResetAt time.Time
	// RetryAfter is the secondary limit's answer, which is a duration rather
	// than an instant. Zero when unset.
	RetryAfter time.Duration
	Detail     string
}

func (e *RateLimitedError) Error() string {
	switch {
	case !e.ResetAt.IsZero():
		return fmt.Sprintf("%s: quota exhausted until %s%s",
			ErrRateLimited, e.ResetAt.UTC().Format(time.RFC3339), e.Detail)
	case e.RetryAfter > 0:
		return fmt.Sprintf("%s: secondary rate limit, retry after %s%s",
			ErrRateLimited, e.RetryAfter, e.Detail)
	}
	return ErrRateLimited.Error() + e.Detail
}

func (e *RateLimitedError) Unwrap() error { return ErrRateLimited }

// RetryAt is when a caller may try this installation again, given the time it
// is asking at, and whether GitHub said anything at all.
//
// A reset already in the past is no answer -- clocks drift, and a response can
// sit in a queue -- so it is reported as unknown and the caller keeps its own
// default rather than resuming into the same refusal.
func (e *RateLimitedError) RetryAt(now time.Time) (time.Time, bool) {
	if e == nil {
		return time.Time{}, false
	}
	if e.RetryAfter > 0 {
		return now.Add(e.RetryAfter), true
	}
	if !e.ResetAt.IsZero() && e.ResetAt.After(now) {
		return e.ResetAt, true
	}
	return time.Time{}, false
}

// RetryAfterRateLimit reports when err says an installation may be used again.
//
// It answers false for anything that is not a rate limit and for a rate limit
// GitHub said nothing useful about, which is the same thing to a caller: fall
// back to your own wait.
func RetryAfterRateLimit(err error, now time.Time) (time.Time, bool) {
	var rl *RateLimitedError
	if !errors.As(err, &rl) {
		return time.Time{}, false
	}
	return rl.RetryAt(now)
}

// ErrForbidden is returned for a 403 that is not a rate limit, usually meaning
// the App installation is missing a permission.
var ErrForbidden = errors.New("github: forbidden")

// ErrInvalid is GitHub refusing a request as invalid rather than unauthorised:
// a runner name already taken, a label it will not accept. The detail carries
// the field-by-field reason, which is the part worth reading -- the message on
// a 422 is always "Validation Failed".
var ErrInvalid = errors.New("github: refused as invalid")

// ErrRunnerBusy is DeleteRunner refused because GitHub still considers the
// runner to be running a job. It wraps ErrInvalid -- the same 422 GitHub uses
// for every other "refused as invalid" case -- so a caller that only checks
// for ErrInvalid still catches it, and one that wants to tell this apart from
// a genuinely bad request (a stale ID, a name GitHub never had) can.
//
// This is usually not the operator's problem: GitHub's own bookkeeping can lag
// a few seconds behind the workflow_job "completed" webhook that told Zoomies
// the runner was free, and the delete loses that race. Deleting again once
// GitHub reports the runner idle succeeds without anyone doing anything.
var ErrRunnerBusy = errors.New("github: runner is still running a job")

// JITRequest asks GitHub for a just-in-time runner configuration.
type JITRequest struct {
	// Name must be unique within the target. GitHub rejects reuse.
	Name string
	// Labels are the custom labels this runner advertises, without the
	// implicit self-hosted/os/arch set.
	Labels []string
	// RunnerGroupID is 1 (Default) unless the pool names a group.
	RunnerGroupID int64
	// WorkFolder defaults to "_work".
	WorkFolder string
}

// JITConfig is the base64 blob handed to `actions-runner --jitconfig`. It
// registers an ephemeral runner exactly once and expires quickly, which is what
// makes it safe to pass through an environment variable.
type JITConfig struct {
	// Encoded is the base64 configuration.
	Encoded string
	// RunnerID is the ID GitHub assigned, so Zoomies can delete the
	// registration later if the runner never comes up.
	RunnerID int64
	// Name echoes the requested name.
	Name string
}

// RegistrationToken is the older credential, used by non-ephemeral pools that
// must run config.sh. It is valid for one hour.
type RegistrationToken struct {
	Token     string
	ExpiresAt time.Time
}

// Runner is a runner as GitHub sees it, used to reconcile Zoomies' view with
// reality and to clean up registrations Zoomies has lost track of.
type Runner struct {
	ID     int64
	Name   string
	OS     string
	Status string // online | offline
	Busy   bool
	Labels []string
	// Ephemeral is reported by GitHub for JIT-configured runners.
	Ephemeral bool
}

// QueuedJob is a job the fallback poller found unfinished: waiting for a
// runner, or already running on one. It carries only what the scheduler needs
// to match it to a pool and, once it has started, to its runner.
type QueuedJob struct {
	ID    int64
	RunID int64
	// RunNumber is GitHub's own sequential number for the workflow run --
	// free from the same run listing this job was found in, unlike the
	// webhook path, which has to ask for it separately.
	RunNumber    int64
	Repo         string
	WorkflowName string
	JobName      string
	Labels       []string
	QueuedAt     time.Time
	HTMLURL      string
	// RunnerName is set once GitHub has assigned the job.
	RunnerName  string
	Status      string
	Conclusion  string
	StartedAt   *time.Time
	CompletedAt *time.Time
}

// WorkflowRunState is GitHub's authoritative lifecycle for one workflow run.
// Status becomes "completed" before Conclusion is meaningful.
type WorkflowRunState struct {
	Status     string
	Conclusion string
	// RunNumber is the "#1009" GitHub's Actions UI shows next to the workflow
	// name. workflow_job deliveries never carry it, which is what this lookup
	// is for.
	RunNumber int64
}

// Cancelled reports whether GitHub has finished the whole run as cancelled.
// A cancelled workflow job by itself is deliberately not enough evidence.
func (s WorkflowRunState) Cancelled() bool {
	return s.Status == string(store.JobCompleted) && s.Conclusion == "cancelled"
}

// RunnerGroup is a runner group in the target org.
type RunnerGroup struct {
	ID         int64
	Name       string
	Default    bool
	Visibility string
	// PublicRepositoryAccessKnown distinguishes an older GitHub Enterprise
	// response that omitted the setting from a group that explicitly disables
	// it. Treating both as false would raise a warning nobody could act on.
	PublicRepositoryAccessKnown bool
	AllowsPublicRepositories    bool
	RestrictedToWorkflows       bool
}

// RunnerGroupCreate is the policy for a new organisation runner group.
type RunnerGroupCreate struct {
	Name                     string
	Visibility               string
	AllowsPublicRepositories bool
}

// AppInfo describes the authenticated GitHub App.
type AppInfo struct {
	ID    int64
	Slug  string
	Name  string
	Owner string
	// Permissions is what the App was granted, so setup can tell the operator
	// exactly which permission is missing rather than "403".
	Permissions map[string]string
	Events      []string
	// RepositorySelection is GitHub's own word for how much of the target this
	// installation covers: "all" or "selected". It is the difference between a
	// pool that will see every repository somebody pushes to and one that
	// silently sees none of them -- the second commonest setup mistake after a
	// missing permission, and the one nothing in Zoomies could previously say
	// anything about.
	RepositorySelection string
}

// RateLimit reports the installation's remaining API quota, which the UI shows
// on the Installations page.
type RateLimit struct {
	Limit     int
	Remaining int
	ResetAt   time.Time
}

// Client is the GitHub surface Zoomies uses, scoped to one installation.
//
// It is an interface so that tests can run the whole controller against a fake
// GitHub without a network, and so that GHES differences stay behind one seam.
type Client interface {
	// Target returns the org or repo this client acts on.
	Target() (name string, kind store.TargetType)
	// Probe verifies the credentials and permissions, returning an error whose
	// message names the missing permission where GitHub tells us.
	Probe(ctx context.Context) (*AppInfo, error)
	// CreateJITConfig mints an ephemeral runner registration.
	CreateJITConfig(ctx context.Context, req JITRequest) (*JITConfig, error)
	// CreateRegistrationToken mints a one-hour token for config.sh.
	CreateRegistrationToken(ctx context.Context) (*RegistrationToken, error)
	// CreateRemoveToken mints a token for deregistering a runner from the host.
	CreateRemoveToken(ctx context.Context) (*RegistrationToken, error)
	// ListRunners returns every self-hosted runner registered on the target.
	ListRunners(ctx context.Context) ([]Runner, error)
	// DeleteRunner removes a registration. Deleting one that is already gone
	// returns nil, because the desired end state has been reached.
	DeleteRunner(ctx context.Context, id int64) error
	// ListRunnerGroups returns the target's runner groups.
	ListRunnerGroups(ctx context.Context) ([]RunnerGroup, error)
	// CreateRunnerGroup creates an organisation runner group. Repository
	// targets reject it because GitHub only supports groups at organisation
	// scope.
	CreateRunnerGroup(ctx context.Context, req RunnerGroupCreate) (*RunnerGroup, error)
	// ListQueuedJobs is the webhook fallback: it walks recent workflow runs and
	// returns the jobs still waiting for a runner and the ones running on one.
	// Status tells the two apart.
	ListQueuedJobs(ctx context.Context) ([]QueuedJob, error)
	// GetWorkflowJob reconciles a known job even after its run has completed.
	GetWorkflowJob(ctx context.Context, repo string, id int64) (*WorkflowJobEvent, error)
	// GetWorkflowRun reads the run-level status used to distinguish one
	// cancelled job from cancellation of the entire workflow run.
	GetWorkflowRun(ctx context.Context, repo string, runID int64) (*WorkflowRunState, error)
	// CancelWorkflowRun asks GitHub to cancel the entire run containing a job.
	// Force bypasses conditions that may otherwise keep a run cancelling.
	CancelWorkflowRun(ctx context.Context, repo string, runID int64, force bool) error
	// RerunWorkflowJob asks GitHub to run one job again, together with any
	// job that declares it in `needs`. It is the narrower of the two and the
	// one to reach for: a job re-run on its own account should not drag the
	// rest of the run's failures with it.
	RerunWorkflowJob(ctx context.Context, repo string, jobID int64) error
	// RerunFailedWorkflowJobs asks GitHub to run a run's failed jobs again.
	// Like cancellation it is run-level: GitHub reruns the failed jobs of a
	// run together, so a caller must be clear about what else goes with it.
	// It is the fallback for a job whose GitHub job ID this fleet never saw.
	RerunFailedWorkflowJobs(ctx context.Context, repo string, runID int64) error
	// RateLimit reports remaining quota.
	RateLimit(ctx context.Context) (*RateLimit, error)
	// WebURL returns the browser URL for the target.
	WebURL() string

	// The migration surface. These are the only calls Zoomies makes that
	// write anything to a repository, and they are used by one feature: the
	// wizard that moves a repository's workflows onto this fleet. They need
	// permissions the rest of Zoomies does not have and does not ask for, so
	// every one of them can fail with ErrForbidden on a perfectly healthy
	// installation; callers must say so rather than reporting a broken App.

	// ListRepositories returns the repositories this installation can see.
	ListRepositories(ctx context.Context, limit int) ([]Repository, error)
	// ListWorkflows returns the workflow files at the top of a repository's
	// .github/workflows, with their contents.
	ListWorkflows(ctx context.Context, repo string) ([]WorkflowFile, error)
	// ReadReadme returns the README GitHub renders on the repository's front
	// page, or ErrNoReadme when there is none. It is where the badge goes.
	ReadReadme(ctx context.Context, repo string) (*Readme, error)
	// OpenPullRequest commits a set of files to a new branch and opens a pull
	// request for it.
	OpenPullRequest(ctx context.Context, req PullRequestRequest) (*PullRequest, error)
}

// Repository is one repository an installation can see.
type Repository struct {
	ID            int64  `json:"id"`
	FullName      string `json:"full_name"`
	DefaultBranch string `json:"default_branch"`
	Private       bool   `json:"private"`
	Archived      bool   `json:"archived"`
	HTMLURL       string `json:"html_url"`
}

// WorkflowFile is one file under .github/workflows as it exists on the
// repository's default branch.
type WorkflowFile struct {
	// Path is repository-relative.
	Path string
	// SHA is the blob SHA. GitHub requires it to update the file, and it is
	// what makes an update fail rather than clobber somebody's change.
	SHA string
	// Content is the decoded file.
	Content string
}

// FileChange is one file a pull request writes.
type FileChange struct {
	Path    string
	Content string
	// SHA is the blob SHA the change was computed against.
	SHA string
}

// PullRequestRequest describes the pull request to open.
type PullRequestRequest struct {
	// Repo is "owner/name".
	Repo string
	// Base is the branch to open against. Empty means the default branch.
	Base string
	// Head is the branch to create. It must not already exist.
	Head          string
	Title         string
	Body          string
	CommitMessage string
	Files         []FileChange
}

// PullRequest is what opening one produced.
type PullRequest struct {
	Number  int    `json:"number"`
	HTMLURL string `json:"html_url"`
	Branch  string `json:"branch"`
}

// Factory builds a Client for an installation. The controller holds one
// factory and caches clients per installation.
type Factory interface {
	For(ctx context.Context, inst *store.Installation, privateKeyPEM []byte) (Client, error)
}

// RunnerName mints the name one runner of this pool registers under:
// "zoomies-4vcpu-ubuntu-2404-biscuit-a3f9qz2m".
//
// This is the one name Zoomies puts in somebody else's account, so GitHub's
// constraints on it are worth stating where the registration is made. The name
// must be unique within the target -- two runners answering to one name is one
// registration being taken over, not two runners -- which is what the random
// token at the end is for, and why nothing may truncate it away. GitHub also
// shows it in three places a reader arrives at knowing nothing: the runner list,
// the job header, and the "Set up job" step of every log. That is what the shape
// in the middle answers, and store.NewRunnerName explains why it is worth the
// characters.
//
// The 64-character limit GitHub enforces is internal/naming's MaxNameLength, so
// a name is trimmed to fit here rather than refused by the API at registration.
func RunnerName(pool *store.Pool) string { return store.NewRunnerName(pool) }

// SplitTarget parses "owner" or "owner/repo" into its parts.
func SplitTarget(target string) (owner, repo string, kind store.TargetType) {
	if o, r, ok := strings.Cut(target, "/"); ok && r != "" {
		return o, r, store.TargetRepo
	}
	return target, "", store.TargetOrg
}

// NormalizeAPIBaseURL turns the forms operators actually type into the form
// go-github expects: an absolute URL ending in a slash, with /api/v3 appended
// for a bare GHES hostname.
func NormalizeAPIBaseURL(raw string) (string, error) {
	// The rule lives in config so that zoomies.yaml is normalised by the same
	// code as an installation row: the docs promise a bare GHES hostname works
	// in both places, and two copies of the rule had already let the config
	// side refuse what this side accepted.
	return config.NormalizeGitHubAPIBaseURL(raw)
}

// IsEnterprise reports whether an API base URL points at GitHub Enterprise
// Server rather than github.com.
func IsEnterprise(apiBaseURL string) bool {
	return apiBaseURL != "" && !strings.Contains(apiBaseURL, "api.github.com")
}

// WebURLForAPI derives the browser-facing base URL from an API base URL, which
// is what the UI links to.
//
// It is also the URL a runner registers against, so a GHE.com tenant has to
// lose its api. prefix here: config.sh pointed at api.<tenant>.ghe.com/<org>
// fails to register, and the App-creation page there does not exist.
func WebURLForAPI(apiBaseURL string) string {
	if !IsEnterprise(apiBaseURL) {
		return "https://github.com"
	}
	s := strings.TrimSuffix(strings.TrimRight(apiBaseURL, "/"), "/api/v3")
	if config.IsGHECom(s) {
		s = strings.Replace(s, "://api.", "://", 1)
	}
	return s
}

// errorf wraps a GitHub failure with the operation that produced it.
func errorf(op string, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("github: %s: %w", op, err)
}

package github

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The reset GitHub sends is the difference between waiting exactly as long as
// the quota needs and guessing a flat fifteen minutes -- which is either most
// of a window wasted or most of a window spent on refusals. It used to be
// formatted into the message and lost, so this checks it survives as a number.
func TestARateLimitCarriesWhenToComeBack(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	reset := now.Add(9 * time.Minute)

	err := error(&RateLimitedError{ResetAt: reset})
	if !errors.Is(err, ErrRateLimited) {
		t.Fatal("callers that only ask whether it was a rate limit must still get yes")
	}
	at, ok := RetryAfterRateLimit(err, now)
	if !ok || !at.Equal(reset) {
		t.Fatalf("RetryAfterRateLimit = %v, %v; want %v, true", at, ok, reset)
	}
	if !strings.Contains(err.Error(), reset.Format(time.RFC3339)) {
		t.Fatalf("the message still has to name the time for an operator: %q", err)
	}
}

// GitHub's secondary limit answers with a duration rather than an instant.
func TestASecondaryRateLimitCarriesItsRetryAfter(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	err := error(&RateLimitedError{RetryAfter: 90 * time.Second})

	at, ok := RetryAfterRateLimit(err, now)
	if !ok || !at.Equal(now.Add(90*time.Second)) {
		t.Fatalf("RetryAfterRateLimit = %v, %v", at, ok)
	}
}

// A reset already behind us is no answer at all: clocks drift and a response
// can sit in a queue, and resuming on it would buy another refusal. The caller
// is told nothing rather than told to go now.
func TestARateLimitResetInThePastIsNotAnAnswer(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	err := error(&RateLimitedError{ResetAt: now.Add(-time.Minute)})

	if at, ok := RetryAfterRateLimit(err, now); ok {
		t.Fatalf("a reset in the past was offered as a resume time: %v", at)
	}
}

// Anything that is not a rate limit must not be mistaken for one.
func TestOtherFailuresCarryNoResumeTime(t *testing.T) {
	now := time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)
	for _, err := range []error{ErrForbidden, ErrNotFound, errors.New("boom"), nil} {
		if _, ok := RetryAfterRateLimit(err, now); ok {
			t.Fatalf("%v was read as a rate limit", err)
		}
	}
}

// The end of the same story, through a real client against a real response:
// what GitHub sends has to arrive as a number a caller can wait on. The tests
// above build the error by hand and would go on passing if classify stopped
// producing it.
func TestAGitHubRefusalForQuotaArrivesWithItsResetTime(t *testing.T) {
	f := newFake(t)
	reset := time.Now().Add(11 * time.Minute).Truncate(time.Second)
	f.SetRateLimit(5000, 0, reset)
	f.SetError("/actions/runners", http.StatusForbidden, "API rate limit exceeded")

	_, err := f.Client("acme", store.TargetOrg).ListRunners(context.Background())
	if !errors.Is(err, ErrRateLimited) {
		t.Fatalf("got %v, want a rate limit", err)
	}
	at, ok := RetryAfterRateLimit(err, time.Now())
	if !ok {
		t.Fatalf("the refusal carried no time to come back at: %v", err)
	}
	if !at.Equal(reset.UTC()) {
		t.Fatalf("resume at %v, want the reset GitHub sent, %v", at, reset.UTC())
	}
}

package github

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// FakeGitHub is an in-memory stand-in for the GitHub REST API.
//
// It lives in the production package rather than a _test.go file on purpose:
// the controller, scheduler and API tests all need a GitHub to run the whole
// system against, and a second, subtly different fake in each of them would be
// worse than one honest fake here. "Honest" means it enforces the rules that
// actually bite -- runner names must be unique, a deleted runner is gone, a
// job only appears in a run's job list -- so a test that passes against it has
// some claim to passing against GitHub.
//
// It serves both the github.com layout (/app) and the GitHub Enterprise Server
// layout (/api/v3/app), so the same fake exercises both code paths.
//
// Pagination is not implemented: every list returns one page. Tests that need
// to exercise paging should drive appClient against their own handler.
type FakeGitHub struct {
	srv *httptest.Server

	mu             sync.Mutex
	appID          int64
	installationID int64
	appSlug        string
	appName        string
	appOwner       string
	permissions    map[string]string
	// repositorySelection is GitHub's "all" or "selected".
	repositorySelection string
	events              []string

	nextRunnerID int64
	runners      []*Runner

	// jobReruns counts job-level re-run requests, kept apart from reruns so a
	// test can say which endpoint the controller chose.
	jobReruns int
	// reruns counts re-run requests, which nothing else records: the fake
	// answers and forgets, and a test asserting that Zoomies asked GitHub
	// exactly once needs somewhere to look.
	reruns int

	nextJobID     int64
	nextRunID     int64
	nextRunNumber int64
	jobs          []*fakeJob
	repos         []string
	// contents holds what the migration surface reads and writes: files,
	// branches and pull requests, per repository. It fills in lazily, so a
	// test that never migrates anything pays nothing for it.
	contents map[string]*fakeRepo

	groups []RunnerGroup

	rateLimit RateLimit

	failures []fakeFailure
	delays   []fakeDelay
	requests []string
}

// fakeJob is one queued/running/finished job. Every job gets its own workflow
// run, which is the common shape and keeps the run listing meaningful.
type fakeJob struct {
	QueuedJob
	runStatus string
}

// fakeFailure makes matching requests fail, so tests can exercise the error
// paths without a network.
type fakeFailure struct {
	// method narrows the failure to one HTTP verb. Empty matches any.
	method  string
	pattern string
	status  int
	message string
}

// fakeDelay holds a matching request open before it is served, so a test can
// exercise a GitHub call that takes real wall-clock time -- a controller
// detaching that call from a lock it must not hold is not proven by one that
// answers before anybody could tell the difference.
type fakeDelay struct {
	method  string
	pattern string
	d       time.Duration
}

// NewFake starts a fake GitHub and returns it. The caller must Close it.
func NewFake() *FakeGitHub {
	f := &FakeGitHub{
		appID:               12345,
		installationID:      42,
		appSlug:             "zoomies-fake",
		appName:             "Zoomies Fake",
		appOwner:            "acme",
		repositorySelection: "all",
		// What an App created with the migration option is granted, which is what
		// the manifest in manifest.go asks for when it is asked to. The three
		// migration permissions belong here because this fake serves repository
		// contents: an App described as
		// unable to read them, while the fake hands them over anyway, is a
		// fixture no real installation can be in, and it hid the wizard
		// reporting an App's missing Contents permission as "these
		// repositories have no workflows". A test that wants a narrower App
		// says so with SetPermissions.
		permissions: map[string]string{
			"actions":                          "write",
			"metadata":                         "read",
			"administration":                   "write",
			"organization_self_hosted_runners": "write",
			"contents":                         "write",
			"pull_requests":                    "write",
			"workflows":                        "write",
		},
		events:        []string{"workflow_job"},
		nextRunnerID:  1,
		nextJobID:     1000,
		nextRunID:     5000,
		nextRunNumber: 1,
		groups: []RunnerGroup{{
			ID: 1, Name: "Default", Default: true,
			PublicRepositoryAccessKnown: true, AllowsPublicRepositories: true,
		}},
		rateLimit: RateLimit{Limit: 5000, Remaining: 4999, ResetAt: time.Now().Add(time.Hour).UTC()},
	}
	f.srv = httptest.NewServer(f.handler())
	return f
}

// Server exposes the underlying test server, for tests that need its URL or
// its TLS-aware http.Client.
func (f *FakeGitHub) Server() *httptest.Server { return f.srv }

// URL is the API base URL to hand to an installation.
func (f *FakeGitHub) URL() string { return f.srv.URL }

// Close shuts the server down.
func (f *FakeGitHub) Close() { f.srv.Close() }

// AppID is the App ID the fake claims to be.
func (f *FakeGitHub) AppID() int64 { return f.appID }

// InstallationID is the installation ID the fake serves.
func (f *FakeGitHub) InstallationID() int64 { return f.installationID }

// Client returns a Client wired to this fake for the given target. It is the
// quickest way for a test to get a working github.Client.
func (f *FakeGitHub) Client(target string, kind store.TargetType) Client {
	base := f.srv.URL + "/"
	c, err := newGitHubClient(f.srv.Client(), base, base)
	if err != nil {
		// The URL comes from httptest, so this cannot happen; failing loudly
		// beats handing back a client that talks to the real GitHub.
		panic("github: fake: " + err.Error())
	}
	return newAppClient(c, c, target, kind, f.installationID, "https://github.com")
}

// SetRepositorySelection sets GitHub's "all" or "selected", so a test can
// describe an App installed on a handful of repositories rather than on
// everything.
func (f *FakeGitHub) SetRepositorySelection(selection string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repositorySelection = selection
}

// SetPermissions replaces what the App reports being granted, so tests can
// exercise the "missing permission" reporting.
func (f *FakeGitHub) SetPermissions(p map[string]string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.permissions = p
}

// SetEvents replaces the App's event subscriptions.
func (f *FakeGitHub) SetEvents(events ...string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.events = events
}

// AddRepo makes "owner/name" visible to the installation. AddQueuedJob does
// this for you; call it directly for a repository with no jobs.
func (f *FakeGitHub) AddRepo(fullName string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(fullName)
}

func (f *FakeGitHub) addRepoLocked(fullName string) {
	if fullName == "" || slices.Contains(f.repos, fullName) {
		return
	}
	f.repos = append(f.repos, fullName)
	f.repoLocked(fullName).id = int64(len(f.repos))
}

// AddRunnerGroup registers a runner group and returns it.
func (f *FakeGitHub) AddRunnerGroup(name string) RunnerGroup {
	f.mu.Lock()
	defer f.mu.Unlock()
	g := RunnerGroup{ID: int64(len(f.groups) + 1), Name: name,
		Visibility:                  "all",
		PublicRepositoryAccessKnown: true, AllowsPublicRepositories: true}
	f.groups = append(f.groups, g)
	return g
}

// SetRunnerGroupPublicAccess changes the public-repository policy GitHub
// reports for a group. It exists for controller tests of the otherwise easy
// to miss state where a runner is online but no public-repository job is
// eligible to use it.
func (f *FakeGitHub) SetRunnerGroupPublicAccess(name string, allowed bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for i := range f.groups {
		if strings.EqualFold(f.groups[i].Name, name) {
			f.groups[i].PublicRepositoryAccessKnown = true
			f.groups[i].AllowsPublicRepositories = allowed
			return
		}
	}
}

// AddRunner registers a runner that Zoomies did not create, which is how a
// test simulates a registration the controller has lost track of.
func (f *FakeGitHub) AddRunner(name string, labels []string) Runner {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.addRunnerLocked(name, labels, false)
	return *r
}

func (f *FakeGitHub) addRunnerLocked(name string, labels []string, ephemeral bool) *Runner {
	r := &Runner{
		ID:        f.nextRunnerID,
		Name:      name,
		OS:        "linux",
		Status:    "online",
		Labels:    append([]string{"self-hosted"}, labels...),
		Ephemeral: ephemeral,
	}
	f.nextRunnerID++
	f.runners = append(f.runners, r)
	return r
}

// SetRunnerBusy marks a registered runner busy or idle, the same field
// GitHub's own runner list carries. Tests use it to reproduce the race where
// GitHub still considers a runner busy after its completion webhook already
// fired: deleting it is refused the way GitHub refuses it for real.
func (f *FakeGitHub) SetRunnerBusy(name string, busy bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if i := slices.IndexFunc(f.runners, func(r *Runner) bool { return r.Name == name }); i >= 0 {
		f.runners[i].Busy = busy
	}
}

// Runners returns a snapshot of the registered runners.
func (f *FakeGitHub) Runners() []Runner {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]Runner, 0, len(f.runners))
	for _, r := range f.runners {
		out = append(out, *r)
	}
	return out
}

// AddQueuedJob queues a job on repo ("owner/name") and returns it as the API
// will report it. The repository becomes visible to the installation.
func (f *FakeGitHub) AddQueuedJob(repo, workflow, jobName string, labels []string) QueuedJob {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	// A queued job usually follows a push; the poller sorts on it.
	f.repoLocked(repo).pushedAt = time.Now().UTC()
	j := &fakeJob{
		QueuedJob: QueuedJob{
			ID:           f.nextJobID,
			RunID:        f.nextRunID,
			RunNumber:    f.nextRunNumber,
			Repo:         repo,
			WorkflowName: workflow,
			JobName:      jobName,
			Labels:       slices.Clone(labels),
			QueuedAt:     time.Now().UTC(),
			HTMLURL:      fmt.Sprintf("https://github.com/%s/actions/runs/%d/job/%d", repo, f.nextRunID, f.nextJobID),
			Status:       string(store.JobQueued),
		},
		runStatus: string(store.JobQueued),
	}
	f.nextJobID++
	f.nextRunID++
	f.nextRunNumber++
	f.jobs = append(f.jobs, j)
	return j.QueuedJob
}

// StartJob marks a queued job as picked up by runnerName.
func (f *FakeGitHub) StartJob(jobID int64, runnerName string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if j := f.findJobLocked(jobID); j != nil {
		now := time.Now().UTC()
		j.Status = string(store.JobInProgress)
		j.runStatus = string(store.JobInProgress)
		j.RunnerName = runnerName
		j.StartedAt = &now
	}
}

// CompleteJob finishes a job with the given conclusion ("success",
// "failure", "cancelled", ...).
func (f *FakeGitHub) CompleteJob(jobID int64, conclusion string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if j := f.findJobLocked(jobID); j != nil {
		now := time.Now().UTC()
		if j.StartedAt == nil {
			j.StartedAt = &now
		}
		j.Status = string(store.JobCompleted)
		j.runStatus = string(store.JobCompleted)
		j.Conclusion = conclusion
		j.CompletedAt = &now
	}
}

// SetWorkflowRunState changes the run record independently of its jobs. That
// distinction lets controller tests prove that one cancelled stage does not
// fan cancellation out to the rest of the workflow.
func (f *FakeGitHub) SetWorkflowRunState(runID int64, status, conclusion string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, j := range f.jobs {
		if j.RunID == runID {
			j.runStatus = status
			if conclusion != "" {
				j.Conclusion = conclusion
			}
		}
	}
}

func (f *FakeGitHub) findJobLocked(id int64) *fakeJob {
	for _, j := range f.jobs {
		if j.ID == id {
			return j
		}
	}
	return nil
}

// SetError makes every request whose path contains pattern fail with status
// and message. An empty pattern matches every request. Calls accumulate; use
// ClearErrors to reset.
//
// A 403 carrying the rate-limit headers (see SetRateLimit) is how a test
// produces ErrRateLimited, because that is how GitHub signals it.
func (f *FakeGitHub) SetError(pattern string, status int, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = append(f.failures, fakeFailure{pattern: pattern, status: status, message: message})
}

// SetMethodError is SetError narrowed to one HTTP method.
//
// Several verbs share a path: an orphan sweep lists an installation's runners
// and then deletes them at the same one, so a test about a refused delete
// cannot afford to refuse the listing that finds them too.
func (f *FakeGitHub) SetMethodError(method, pattern string, status int, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = append(f.failures, fakeFailure{
		method: method, pattern: pattern, status: status, message: message,
	})
}

// SetDelay holds every request matching method (empty for any) and pattern
// open for d before it is served, so a test can drive a GitHub call that
// takes real wall-clock time.
func (f *FakeGitHub) SetDelay(method, pattern string, d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.delays = append(f.delays, fakeDelay{method: method, pattern: pattern, d: d})
}

// ClearErrors removes every failure injected with SetError.
func (f *FakeGitHub) ClearErrors() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures = nil
}

// SetRateLimit sets the quota reported by /rate_limit and by the rate-limit
// headers on every response.
func (f *FakeGitHub) SetRateLimit(limit, remaining int, reset time.Time) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.rateLimit = RateLimit{Limit: limit, Remaining: remaining, ResetAt: reset.UTC()}
}

// Requests returns every request the fake has served, as "GET /path". Tests
// use it to assert that a poll stayed within its call budget.
func (f *FakeGitHub) Requests() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.requests)
}

// ---------------------------------------------------------------------------
// HTTP surface
// ---------------------------------------------------------------------------

func (f *FakeGitHub) handler() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /app", f.getApp)
	mux.HandleFunc("GET /app/installations/{id}", f.getInstallation)
	mux.HandleFunc("POST /app/installations/{id}/access_tokens", f.createInstallationToken)
	mux.HandleFunc("GET /installation/repositories", f.listInstallationRepos)
	mux.HandleFunc("GET /rate_limit", f.getRateLimit)

	mux.HandleFunc("POST /orgs/{org}/actions/runners/generate-jitconfig", f.generateJITConfig)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/generate-jitconfig", f.generateJITConfig)
	mux.HandleFunc("POST /orgs/{org}/actions/runners/registration-token", f.createToken)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/registration-token", f.createToken)
	mux.HandleFunc("POST /orgs/{org}/actions/runners/remove-token", f.createToken)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runners/remove-token", f.createToken)
	mux.HandleFunc("GET /orgs/{org}/actions/runners", f.listRunners)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runners", f.listRunners)
	mux.HandleFunc("DELETE /orgs/{org}/actions/runners/{id}", f.deleteRunner)
	mux.HandleFunc("DELETE /repos/{owner}/{repo}/actions/runners/{id}", f.deleteRunner)
	mux.HandleFunc("GET /orgs/{org}/actions/runner-groups", f.listRunnerGroups)
	mux.HandleFunc("POST /orgs/{org}/actions/runner-groups", f.createRunnerGroup)

	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/jobs/{job}", f.getWorkflowJob)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs", f.listWorkflowRuns)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs/{run}", f.getWorkflowRun)
	mux.HandleFunc("GET /repos/{owner}/{repo}/actions/runs/{run}/jobs", f.listWorkflowJobs)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/cancel", f.cancelWorkflowRun)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/force-cancel", f.cancelWorkflowRun)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/runs/{run}/rerun-failed-jobs", f.rerunFailedJobs)
	mux.HandleFunc("POST /repos/{owner}/{repo}/actions/jobs/{job}/rerun", f.rerunJob)

	f.registerMigrationRoutes(mux)

	return f.middleware(mux)
}

func (f *FakeGitHub) cancelWorkflowRun(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusAccepted)
}

// rerunFailedJobs answers a re-run request. It needs the same Actions write
// permission a cancel does, and it answers 201 as GitHub does, so a test can
// tell the two status paths apart.
func (f *FakeGitHub) rerunFailedJobs(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.reruns++
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusCreated)
}

// rerunJob answers a job-level re-run. It is a separate counter from the
// run-level one, because which of the two a caller reached for is the whole
// difference between re-running one job and re-running every failure in its
// run, and a test that could not tell them apart could not hold that.
func (f *FakeGitHub) rerunJob(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	level := f.permissions["actions"]
	f.jobReruns++
	f.mu.Unlock()
	if level != "write" {
		writeError(w, http.StatusForbidden, "Resource not accessible by integration")
		return
	}
	w.WriteHeader(http.StatusCreated)
}

// JobReruns is how many job-level re-run requests the fake has been sent.
func (f *FakeGitHub) JobReruns() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.jobReruns
}

// Reruns is how many re-run requests the fake has been sent, so a test can
// assert that asking twice asked GitHub twice -- or, where the controller
// refuses, that it asked nothing at all.
func (f *FakeGitHub) Reruns() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.reruns
}

// middleware records the request, strips the GitHub Enterprise Server /api/v3
// prefix so one set of routes serves both layouts, stamps the rate-limit
// headers GitHub always sends, and applies any injected failure.
func (f *FakeGitHub) middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// The raw path is what gets recorded, so a test can tell a GHES-shaped
		// call from a github.com-shaped one.
		raw := r.URL.Path
		path := raw
		if rest, ok := strings.CutPrefix(path, "/api/v3"); ok && strings.HasPrefix(rest, "/") {
			r = r.Clone(r.Context())
			r.URL.Path = rest
			path = rest
		}

		f.mu.Lock()
		f.requests = append(f.requests, r.Method+" "+raw)
		rate := f.rateLimit
		var hit *fakeFailure
		for i := range f.failures {
			if f.failures[i].method != "" && f.failures[i].method != r.Method {
				continue
			}
			if f.failures[i].pattern == "" || strings.Contains(path, f.failures[i].pattern) {
				hit = &f.failures[i]
				break
			}
		}
		var wait time.Duration
		for i := range f.delays {
			if f.delays[i].method != "" && f.delays[i].method != r.Method {
				continue
			}
			if f.delays[i].pattern == "" || strings.Contains(path, f.delays[i].pattern) {
				wait = f.delays[i].d
				break
			}
		}
		f.mu.Unlock()

		if wait > 0 {
			select {
			case <-time.After(wait):
			case <-r.Context().Done():
				return
			}
		}

		h := w.Header()
		h.Set("Content-Type", "application/json; charset=utf-8")
		h.Set("X-Ratelimit-Limit", strconv.Itoa(rate.Limit))
		h.Set("X-Ratelimit-Remaining", strconv.Itoa(rate.Remaining))
		h.Set("X-Ratelimit-Reset", strconv.FormatInt(rate.ResetAt.Unix(), 10))

		if hit != nil {
			writeError(w, hit.status, hit.message)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func writeError(w http.ResponseWriter, status int, message string) {
	if message == "" {
		message = http.StatusText(status)
	}
	writeJSON(w, status, map[string]any{
		"message":           message,
		"documentation_url": "https://docs.github.com/rest",
	})
}

// target reconstructs the target a request addresses, so one handler can serve
// both halves of each org/repo endpoint pair.
func target(r *http.Request) (full string, kind store.TargetType) {
	if org := r.PathValue("org"); org != "" {
		return org, store.TargetOrg
	}
	return r.PathValue("owner") + "/" + r.PathValue("repo"), store.TargetRepo
}

func (f *FakeGitHub) getApp(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	writeJSON(w, http.StatusOK, map[string]any{
		"id":          f.appID,
		"slug":        f.appSlug,
		"name":        f.appName,
		"owner":       map[string]any{"login": f.appOwner},
		"permissions": f.permissions,
		"events":      f.events,
	})
}

func (f *FakeGitHub) getInstallation(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	if id != f.installationID {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"id":          f.installationID,
		"app_id":      f.appID,
		"app_slug":    f.appSlug,
		"account":     map[string]any{"login": f.appOwner},
		"target_type": "Organization",
		"permissions": f.permissions,
		"events":      f.events,
		// How much of the target the installation covers. GitHub sends it on
		// every installation, and it is what tells "the App can see everything
		// you push to" from "the App was installed on three repositories and
		// yours is not one of them".
		"repository_selection": f.repositorySelection,
	})
}

func (f *FakeGitHub) createInstallationToken(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	if id != f.installationID {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{
		"token":       "ghs_fake_installation_token",
		"expires_at":  time.Now().Add(time.Hour).UTC().Format(time.RFC3339),
		"permissions": f.permissions,
	})
}

func (f *FakeGitHub) listInstallationRepos(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	repos := make([]map[string]any, 0, len(f.repos))
	for _, full := range f.repos {
		owner, name, _ := SplitTarget(full)
		repos = append(repos, map[string]any{
			"id":        f.repoLocked(full).id,
			"full_name": full,
			"name":      name,
			"owner":     map[string]any{"login": owner},
			// The migration scan reads the default branch from here: a pull
			// request has to be opened against one, and guessing "main" is how
			// a migration fails silently on a repository still using "master".
			"default_branch": f.repoLocked(full).defaultBranch,
			"private":        true,
			"archived":       f.repoLocked(full).archived,
			"html_url":       "https://github.com/" + full,
			"pushed_at":      f.repoLocked(full).pushedAt.UTC().Format(time.RFC3339),
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(repos), "repositories": repos})
}

func (f *FakeGitHub) getRateLimit(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	core := map[string]any{
		"limit":     f.rateLimit.Limit,
		"remaining": f.rateLimit.Remaining,
		"used":      f.rateLimit.Limit - f.rateLimit.Remaining,
		"reset":     f.rateLimit.ResetAt.Unix(),
	}
	writeJSON(w, http.StatusOK, map[string]any{"resources": map[string]any{"core": core}})
}

func (f *FakeGitHub) generateJITConfig(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name          string   `json:"name"`
		RunnerGroupID int64    `json:"runner_group_id"`
		WorkFolder    string   `json:"work_folder"`
		Labels        []string `json:"labels"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "Problems parsing JSON")
		return
	}
	if req.Name == "" || len(req.Labels) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed: name and labels are required")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	// GitHub refuses to reuse a runner name within a target; a fake that
	// allowed it would hide the bug where a pool mints colliding names.
	for _, existing := range f.runners {
		if existing.Name == req.Name {
			writeError(w, http.StatusConflict,
				fmt.Sprintf("A runner with the name %q already exists.", req.Name))
			return
		}
	}
	if !slices.ContainsFunc(f.groups, func(g RunnerGroup) bool { return g.ID == req.RunnerGroupID }) {
		writeError(w, http.StatusNotFound, "Runner group not found")
		return
	}

	runner := f.addRunnerLocked(req.Name, req.Labels, true)
	blob, _ := json.Marshal(map[string]any{
		"name":        req.Name,
		"labels":      req.Labels,
		"work_folder": req.WorkFolder,
		"runner_id":   runner.ID,
	})
	writeJSON(w, http.StatusCreated, map[string]any{
		"runner":             runnerJSON(runner),
		"encoded_jit_config": base64.StdEncoding.EncodeToString(blob),
	})
}

func (f *FakeGitHub) createToken(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusCreated, map[string]any{
		"token":      "AABF3JGZDX3P5PMEXLND6TS6FCWO6",
		"expires_at": time.Now().Add(time.Hour).UTC().Format(time.RFC3339),
	})
}

func (f *FakeGitHub) listRunners(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]map[string]any, 0, len(f.runners))
	for _, r := range f.runners {
		out = append(out, runnerJSON(r))
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(out), "runners": out})
}

func runnerJSON(r *Runner) map[string]any {
	labels := make([]map[string]any, 0, len(r.Labels))
	for i, l := range r.Labels {
		labels = append(labels, map[string]any{"id": i + 1, "name": l, "type": "custom"})
	}
	return map[string]any{
		"id":        r.ID,
		"name":      r.Name,
		"os":        r.OS,
		"status":    r.Status,
		"busy":      r.Busy,
		"ephemeral": r.Ephemeral,
		"labels":    labels,
	}
}

func (f *FakeGitHub) deleteRunner(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.ParseInt(r.PathValue("id"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	i := slices.IndexFunc(f.runners, func(x *Runner) bool { return x.ID == id })
	if i < 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	if f.runners[i].Busy {
		// The refusal real GitHub sends for this, reproduced verbatim: it is
		// the plain message field, with no per-field errors array, which is
		// why classify() reads it straight off er.Message.
		writeError(w, http.StatusUnprocessableEntity, fmt.Sprintf(
			"Bad request - Runner %s is currently running a job and cannot be deleted.", f.runners[i].Name))
		return
	}
	f.runners = slices.Delete(f.runners, i, i+1)
	w.WriteHeader(http.StatusNoContent)
}

func (f *FakeGitHub) listRunnerGroups(w http.ResponseWriter, _ *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]map[string]any, 0, len(f.groups))
	for _, g := range f.groups {
		out = append(out, map[string]any{
			"id": g.ID, "name": g.Name, "default": g.Default,
			"visibility":                 g.Visibility,
			"allows_public_repositories": g.AllowsPublicRepositories,
			"restricted_to_workflows":    g.RestrictedToWorkflows,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(out), "runner_groups": out})
}

func (f *FakeGitHub) createRunnerGroup(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name                     string `json:"name"`
		Visibility               string `json:"visibility"`
		AllowsPublicRepositories bool   `json:"allows_public_repositories"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || strings.TrimSpace(req.Name) == "" {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if slices.ContainsFunc(f.groups, func(g RunnerGroup) bool { return strings.EqualFold(g.Name, req.Name) }) {
		writeError(w, http.StatusUnprocessableEntity, "Validation Failed")
		return
	}
	g := RunnerGroup{
		ID: int64(len(f.groups) + 1), Name: strings.TrimSpace(req.Name), Visibility: req.Visibility,
		PublicRepositoryAccessKnown: true, AllowsPublicRepositories: req.AllowsPublicRepositories,
	}
	f.groups = append(f.groups, g)
	writeJSON(w, http.StatusCreated, map[string]any{
		"id": g.ID, "name": g.Name, "default": false, "visibility": g.Visibility,
		"allows_public_repositories": g.AllowsPublicRepositories,
		"restricted_to_workflows":    false,
	})
}

func (f *FakeGitHub) listWorkflowRuns(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	want := r.URL.Query().Get("status")

	f.mu.Lock()
	defer f.mu.Unlock()
	runs := make([]map[string]any, 0)
	for _, j := range f.jobs {
		if j.Repo != full {
			continue
		}
		if want != "" && j.runStatus != want {
			continue
		}
		runs = append(runs, map[string]any{
			"id":         j.RunID,
			"run_number": j.RunNumber,
			"name":       j.WorkflowName,
			"status":     j.runStatus,
			"created_at": j.QueuedAt.Format(time.RFC3339),
			"html_url":   j.HTMLURL,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(runs), "workflow_runs": runs})
}

func (f *FakeGitHub) getWorkflowRun(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	runID, _ := strconv.ParseInt(r.PathValue("run"), 10, 64)

	f.mu.Lock()
	defer f.mu.Unlock()
	for _, j := range f.jobs {
		if j.Repo == full && j.RunID == runID {
			writeJSON(w, http.StatusOK, map[string]any{
				"id": runID, "status": j.runStatus, "conclusion": j.Conclusion,
				"name": j.WorkflowName, "html_url": j.HTMLURL, "run_number": j.RunNumber,
			})
			return
		}
	}
	writeError(w, http.StatusNotFound, "Not Found")
}

func (f *FakeGitHub) listWorkflowJobs(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	runID, _ := strconv.ParseInt(r.PathValue("run"), 10, 64)

	f.mu.Lock()
	defer f.mu.Unlock()
	jobs := make([]map[string]any, 0)
	for _, j := range f.jobs {
		if j.Repo != full || j.RunID != runID {
			continue
		}
		job := map[string]any{
			"id":            j.ID,
			"run_id":        j.RunID,
			"name":          j.JobName,
			"workflow_name": j.WorkflowName,
			"status":        j.Status,
			"labels":        j.Labels,
			"created_at":    j.QueuedAt.Format(time.RFC3339),
			"html_url":      j.HTMLURL,
			"runner_name":   j.RunnerName,
		}
		if j.Conclusion != "" {
			job["conclusion"] = j.Conclusion
		}
		if j.StartedAt != nil {
			job["started_at"] = j.StartedAt.Format(time.RFC3339)
		}
		if j.CompletedAt != nil {
			job["completed_at"] = j.CompletedAt.Format(time.RFC3339)
		}
		jobs = append(jobs, job)
	}
	if len(jobs) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"total_count": len(jobs), "jobs": jobs})
}

func (f *FakeGitHub) getWorkflowJob(w http.ResponseWriter, r *http.Request) {
	full, _ := target(r)
	id, _ := strconv.ParseInt(r.PathValue("job"), 10, 64)
	f.mu.Lock()
	defer f.mu.Unlock()
	j := f.findJobLocked(id)
	if j == nil || j.Repo != full {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"id": j.ID, "run_id": j.RunID, "name": j.JobName, "workflow_name": j.WorkflowName,
		"status": j.Status, "conclusion": j.Conclusion, "labels": j.Labels, "runner_name": j.RunnerName,
		"created_at": j.QueuedAt, "started_at": j.StartedAt, "completed_at": j.CompletedAt, "html_url": j.HTMLURL,
	})
}

package github

import (
	"crypto"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"math/big"
	"net/http"
	"net/http/httptest"
	"time"
)

// fakeT is the part of *testing.T the fake issuer uses, so this production
// package does not import testing.
type fakeT interface {
	Helper()
	Fatal(args ...any)
	Cleanup(func())
}

// FakeActionsIssuer stands in for token.actions.githubusercontent.com: it
// publishes a key set and signs tokens with the matching private key, so the
// verifier is exercised end to end without the network.
type FakeActionsIssuer struct {
	URL string
	key *rsa.PrivateKey
}

func NewFakeActionsIssuer(t fakeT) *FakeActionsIssuer {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/.well-known/jwks" {
			http.NotFound(w, r)
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"keys": []map[string]string{{
			"kty": "RSA", "alg": "RS256", "use": "sig", "kid": "test",
			"n": base64.RawURLEncoding.EncodeToString(key.N.Bytes()),
			"e": base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.E)).Bytes()),
		}}})
	}))
	t.Cleanup(srv.Close)
	return &FakeActionsIssuer{URL: srv.URL, key: key}
}

// Sign mints a token with the given claims, defaulting the registered ones.
func (f *FakeActionsIssuer) Sign(t fakeT, claims map[string]any) string {
	t.Helper()
	now := time.Now()
	all := map[string]any{"iss": f.URL, "iat": now.Unix(), "nbf": now.Unix(), "exp": now.Add(5 * time.Minute).Unix(), "jti": "jti-" + now.Format(time.RFC3339Nano)}
	for k, v := range claims {
		all[k] = v
	}
	header, _ := json.Marshal(map[string]string{"alg": "RS256", "typ": "JWT", "kid": "test"})
	body, _ := json.Marshal(all)
	signing := base64.RawURLEncoding.EncodeToString(header) + "." + base64.RawURLEncoding.EncodeToString(body)
	digest := sha256.Sum256([]byte(signing))
	sig, err := rsa.SignPKCS1v15(rand.Reader, f.key, crypto.SHA256, digest[:])
	if err != nil {
		t.Fatal(err)
	}
	return signing + "." + base64.RawURLEncoding.EncodeToString(sig)
}

package github

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"sort"
	"strconv"
	"strings"

	gh "github.com/google/go-github/v88/github"
)

// Git objects are immutable in the fake, too. Reads pinned to yesterday's
// commit must not see files somebody added to the default branch today.
type fakeContextGit struct {
	Trees                map[string]*gh.Tree
	Commits              map[string]*gh.Commit
	Blobs                map[string]string
	Modes                map[string]string
	Pulls                []*gh.PullRequest
	LoseNextPullResponse bool
}

func (r *fakeRepo) contextGit() *fakeContextGit {
	if r.git == nil {
		r.git = &fakeContextGit{Trees: map[string]*gh.Tree{}, Commits: map[string]*gh.Commit{}, Blobs: map[string]string{}, Modes: map[string]string{}}
	}
	return r.git
}

func (g *fakeContextGit) treeOf(files map[string]*gh.TreeEntry) *gh.Tree {
	groups := map[string]map[string]*gh.TreeEntry{}
	entries := []*gh.TreeEntry{}
	for p, e := range files {
		first, rest, nested := strings.Cut(p, "/")
		if !nested {
			copy := *e
			copy.Path = gh.Ptr(p)
			entries = append(entries, &copy)
			continue
		}
		if groups[first] == nil {
			groups[first] = map[string]*gh.TreeEntry{}
		}
		groups[first][rest] = e
	}
	for p, children := range groups {
		tree := g.treeOf(children)
		entries = append(entries, &gh.TreeEntry{Path: gh.Ptr(p), Type: gh.Ptr("tree"), Mode: gh.Ptr("040000"), SHA: tree.SHA})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].GetPath() < entries[j].GetPath() })
	encoded, _ := json.Marshal(entries)
	sha := blobSHA(string(encoded))
	tree := &gh.Tree{SHA: gh.Ptr(sha), Entries: entries}
	g.Trees[sha] = tree
	return tree
}

func (g *fakeContextGit) flatten(sha string, prefix string, out map[string]*gh.TreeEntry) {
	tree := g.Trees[sha]
	if tree == nil {
		return
	}
	for _, e := range tree.Entries {
		p := prefix + e.GetPath()
		if e.GetType() == "tree" {
			g.flatten(e.GetSHA(), p+"/", out)
		} else {
			copy := *e
			copy.Path = gh.Ptr(p)
			out[p] = &copy
		}
	}
}

func (r *fakeRepo) pinContextSource() {
	g := r.contextGit()
	files := map[string]*gh.TreeEntry{}
	for p, c := range r.files {
		sha := blobSHA(c)
		g.Blobs[sha] = c
		mode := g.Modes[p]
		if mode == "" {
			mode = "100644"
		}
		files[p] = &gh.TreeEntry{Path: gh.Ptr(p), Mode: gh.Ptr(mode), Type: gh.Ptr("blob"), SHA: gh.Ptr(sha), Size: gh.Ptr(len(c))}
	}
	tree := g.treeOf(files)
	sha := blobSHA("source:" + tree.GetSHA())
	g.Commits[sha] = &gh.Commit{SHA: gh.Ptr(sha), Tree: tree, Message: gh.Ptr("Source commit")}
	r.branches[r.defaultBranch] = sha
}

func (f *FakeGitHub) SetFileMode(repo, path, mode string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repoLocked(repo).contextGit().Modes[path] = mode
}

func (f *FakeGitHub) registerContextGitRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/commits/{sha}", f.contextGitRead)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/trees/{sha}", f.contextGitRead)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/blobs/{sha}", f.contextGitRead)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/trees", f.contextCreateTree)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/commits", f.contextCreateCommit)
	mux.HandleFunc("GET /repos/{owner}/{repo}/pulls", f.contextListPulls)
	mux.HandleFunc("GET /repos/{owner}/{repo}/pulls/{number}", f.contextGetPull)
}

func (f *FakeGitHub) contextGitRead(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if !f.canReadContentsLocked() {
		writeError(w, 404, "Not Found")
		return
	}
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	sha := r.PathValue("sha")
	switch {
	case strings.Contains(r.URL.Path, "/git/commits/"):
		if obj := g.Commits[sha]; obj != nil {
			writeJSON(w, 200, obj)
			return
		}
	case strings.Contains(r.URL.Path, "/git/trees/"):
		if obj := g.Trees[sha]; obj != nil {
			if r.URL.Query().Get("recursive") != "" {
				files := map[string]*gh.TreeEntry{}
				g.flatten(sha, "", files)
				flat := &gh.Tree{SHA: obj.SHA}
				for _, e := range files {
					flat.Entries = append(flat.Entries, e)
				}
				sort.Slice(flat.Entries, func(i, j int) bool { return flat.Entries[i].GetPath() < flat.Entries[j].GetPath() })
				writeJSON(w, 200, flat)
				return
			}
			writeJSON(w, 200, obj)
			return
		}
	case strings.Contains(r.URL.Path, "/git/blobs/"):
		if content, ok := g.Blobs[sha]; ok {
			writeJSON(w, 200, map[string]any{"sha": sha, "encoding": "base64", "size": len(content), "content": base64.StdEncoding.EncodeToString([]byte(content))})
			return
		}
	}
	writeError(w, 404, "Not Found")
}

func (f *FakeGitHub) contextCreateTree(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Base    string          `json:"base_tree"`
		Entries []*gh.TreeEntry `json:"tree"`
	}
	if json.NewDecoder(r.Body).Decode(&in) != nil {
		writeError(w, 400, "invalid body")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	if repo.archived || f.permissions["contents"] != "write" {
		writeError(w, 403, "Missing Contents write")
		return
	}
	files := map[string]*gh.TreeEntry{}
	g.flatten(in.Base, "", files)
	for _, e := range in.Entries {
		if strings.HasPrefix(e.GetPath(), ".github/workflows/") && f.permissions["workflows"] != "write" {
			writeError(w, 403, "Missing Workflows write")
			return
		}
		if e.Content == nil && e.SHA == nil {
			delete(files, e.GetPath())
			continue
		}
		if e.Content != nil {
			sha := blobSHA(e.GetContent())
			g.Blobs[sha] = e.GetContent()
			e.SHA = gh.Ptr(sha)
			e.Size = gh.Ptr(len(e.GetContent()))
			e.Content = nil
		}
		files[e.GetPath()] = e
	}
	writeJSON(w, 201, g.treeOf(files))
}

func (f *FakeGitHub) contextCreateCommit(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Message string   `json:"message"`
		Tree    string   `json:"tree"`
		Parents []string `json:"parents"`
	}
	if json.NewDecoder(r.Body).Decode(&in) != nil {
		writeError(w, 400, "invalid body")
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	repo := f.repoLocked(fullName(r))
	g := repo.contextGit()
	if repo.archived || f.permissions["contents"] != "write" {
		writeError(w, 403, "Missing Contents write")
		return
	}
	if g.Trees[in.Tree] == nil {
		writeError(w, 422, "unknown tree")
		return
	}
	encoded, _ := json.Marshal(in)
	sha := blobSHA(string(encoded))
	obj := &gh.Commit{SHA: gh.Ptr(sha), Message: gh.Ptr(in.Message), Tree: g.Trees[in.Tree]}
	for _, p := range in.Parents {
		obj.Parents = append(obj.Parents, &gh.Commit{SHA: gh.Ptr(p)})
	}
	g.Commits[sha] = obj
	writeJSON(w, 201, obj)
}

func (f *FakeGitHub) contextListPulls(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	var out []*gh.PullRequest
	for _, pr := range f.repoLocked(fullName(r)).contextGit().Pulls {
		_, head, _ := strings.Cut(r.URL.Query().Get("head"), ":")
		if pr.GetHead().GetRef() == head && pr.GetBase().GetRef() == r.URL.Query().Get("base") {
			out = append(out, pr)
		}
	}
	if out == nil {
		out = []*gh.PullRequest{}
	}
	writeJSON(w, 200, out)
}

func (f *FakeGitHub) LoseNextContextPullResponse(repo string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.repoLocked(repo).contextGit().LoseNextPullResponse = true
}

func (f *FakeGitHub) contextGetPull(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	number, _ := strconv.Atoi(r.PathValue("number"))
	for _, pr := range f.repoLocked(fullName(r)).contextGit().Pulls {
		if pr.GetNumber() == number {
			writeJSON(w, 200, pr)
			return
		}
	}
	writeError(w, 404, "Not Found")
}

// MergeContextPull models the reviewed setup becoming trusted branch content.
func (f *FakeGitHub) MergeContextPull(repo string, number int) bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.repoLocked(repo)
	g := r.contextGit()
	for _, pr := range g.Pulls {
		if pr.GetNumber() != number {
			continue
		}
		commit := g.Commits[r.branches[pr.GetHead().GetRef()]]
		if commit == nil {
			return false
		}
		files := map[string]*gh.TreeEntry{}
		g.flatten(commit.GetTree().GetSHA(), "", files)
		r.files = map[string]string{}
		for p, e := range files {
			r.files[p] = g.Blobs[e.GetSHA()]
			g.Modes[p] = e.GetMode()
		}
		r.pinContextSource()
		pr.Merged = gh.Ptr(true)
		pr.State = gh.Ptr("closed")
		pr.MergeCommitSHA = gh.Ptr(r.branches[r.defaultBranch])
		return true
	}
	return false
}

// SetContextBranch publishes complete immutable objects without touching source.
func (f *FakeGitHub) SetContextBranch(repo, branch string, contents map[string]string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	r := f.repoLocked(repo)
	g := r.contextGit()
	files := map[string]*gh.TreeEntry{}
	for p, c := range contents {
		sha := blobSHA(c)
		g.Blobs[sha] = c
		files[p] = &gh.TreeEntry{Path: gh.Ptr(p), Type: gh.Ptr("blob"), Mode: gh.Ptr("100644"), SHA: gh.Ptr(sha), Size: gh.Ptr(len(c))}
	}
	tree := g.treeOf(files)
	sha := blobSHA("publication:" + tree.GetSHA())
	g.Commits[sha] = &gh.Commit{SHA: gh.Ptr(sha), Tree: tree}
	r.branches[branch] = sha
}

package github

import (
	"crypto/sha1"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"maps"
	"net/http"
	"slices"
	"sort"
	"strings"
	"time"

	gh "github.com/google/go-github/v88/github"
)

// The fake's half of the migration surface: repository contents, refs and pull
// requests.
//
// It enforces the rules that actually bite when a migration goes wrong. A
// branch that already exists is a 422, not a silent overwrite. A file committed
// with a stale blob SHA is a 409, which is what stops the wizard from
// clobbering a change somebody pushed while the review screen was open. A
// repository with no .github/workflows is a 404 on the directory, which is the
// common case in a large organisation and must not read as a broken App.

// fakeRepo is one repository's contents, as far as the migration cares.
type fakeRepo struct {
	git *fakeContextGit
	// pushedAt is what the poller sorts repositories by; a queued job bumps it.
	pushedAt      time.Time
	defaultBranch string
	id            int64
	// archived makes the repository read-only, as GitHub does: every write
	// answers 403. It is here so a test can prove the migration never gets
	// that far rather than only that it survives the refusal.
	archived bool
	// files maps a repository-relative path to its contents.
	files map[string]string
	// branches maps a branch name to the commit it points at.
	branches map[string]string
	// pulls counts the pull requests opened, which is where the next number
	// comes from.
	pulls int
	// pullBodies keeps each pull request's body by number, so a test can read
	// what a reviewer would read.
	pullBodies map[int]string
}

// AddWorkflow puts a workflow file in a repository, creating the repository if
// this is the first thing in it.
func (f *FakeGitHub) AddWorkflow(repo, path, content string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	r := f.repoLocked(repo)
	r.files[path] = content
}

// AddFile puts any file in a repository, creating the repository if this is
// the first thing in it. It is AddWorkflow under a name that does not lie
// about a README.
func (f *FakeGitHub) AddFile(repo, path, content string) {
	f.AddWorkflow(repo, path, content)
}

// SetDefaultBranch names a repository's default branch. It is "main" until
// something says otherwise.
func (f *FakeGitHub) SetDefaultBranch(repo, branch string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	r := f.repoLocked(repo)
	head := r.branches[r.defaultBranch]
	r.defaultBranch = branch
	r.branches = map[string]string{branch: head}
}

// SetArchived archives or unarchives a repository, creating it if this is the
// first thing said about it.
func (f *FakeGitHub) SetArchived(repo string, archived bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.addRepoLocked(repo)
	f.repoLocked(repo).archived = archived
}

// FileContent returns what a repository's file holds now, which is how a test
// checks what a migration actually committed.
func (f *FakeGitHub) FileContent(repo, path string) (string, bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return "", false
	}
	content, ok := r.files[path]
	return content, ok
}

// PullRequestBody returns the body a pull request was opened with, or "" for
// one that was never opened.
func (f *FakeGitHub) PullRequestBody(repo string, number int) string {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return ""
	}
	return r.pullBodies[number]
}

// Branches returns a repository's branch names, sorted.
func (f *FakeGitHub) Branches(repo string) []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.contents[repo]
	if !ok {
		return nil
	}
	out := slices.Collect(maps.Keys(r.branches))
	sort.Strings(out)
	return out
}

// repoLocked returns the repository's contents, creating them on first use.
// The caller holds f.mu.
func (f *FakeGitHub) repoLocked(repo string) *fakeRepo {
	if f.contents == nil {
		f.contents = map[string]*fakeRepo{}
	}
	r, ok := f.contents[repo]
	if !ok {
		r = &fakeRepo{
			defaultBranch: "main",
			files:         map[string]string{},
			branches:      map[string]string{"main": blobSHA("commit:" + repo)},
		}
		f.contents[repo] = r
	}
	return r
}

// blobSHA uses Git's object identity so source verification exercises real hashes.
func blobSHA(content string) string {
	sum := sha1.Sum([]byte(fmt.Sprintf("blob %d\x00%s", len(content), content)))
	return hex.EncodeToString(sum[:])
}

func (f *FakeGitHub) registerMigrationRoutes(mux *http.ServeMux) {
	f.registerContextGitRoutes(mux)
	mux.HandleFunc("GET /repos/{owner}/{repo}", f.getRepo)
	mux.HandleFunc("GET /repos/{owner}/{repo}/contents/{path...}", f.getContents)
	mux.HandleFunc("PUT /repos/{owner}/{repo}/contents/{path...}", f.putContents)
	mux.HandleFunc("GET /repos/{owner}/{repo}/readme", f.getReadme)
	mux.HandleFunc("GET /repos/{owner}/{repo}/git/ref/{ref...}", f.getRef)
	mux.HandleFunc("POST /repos/{owner}/{repo}/git/refs", f.createRef)
	mux.HandleFunc("DELETE /repos/{owner}/{repo}/git/refs/{ref...}", f.deleteRef)
	mux.HandleFunc("POST /repos/{owner}/{repo}/pulls", f.createPull)
}

func fullName(r *http.Request) string {
	return r.PathValue("owner") + "/" + r.PathValue("repo")
}

func (f *FakeGitHub) getRepo(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	owner, name, _ := SplitTarget(full)
	writeJSON(w, http.StatusOK, map[string]any{
		"id":             repo.id,
		"full_name":      full,
		"name":           name,
		"owner":          map[string]any{"login": owner},
		"default_branch": repo.defaultBranch,
		"private":        true,
		"archived":       repo.archived,
		"html_url":       "https://github.com/" + full,
	})
}

func (f *FakeGitHub) getContents(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	path := strings.Trim(r.PathValue("path"), "/")

	f.mu.Lock()
	defer f.mu.Unlock()
	// GitHub does not distinguish "you may not see this" from "it is not
	// there": an App without the Contents permission gets a 404, the same
	// answer as a repository with no .github/workflows. Answering 403 here
	// would make the fake kinder than GitHub is, and hide the confusion that
	// causes.
	if !slices.Contains(f.repos, full) || !f.canReadContentsLocked() {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)

	if content, ok := repo.files[path]; ok {
		writeJSON(w, http.StatusOK, contentEntry(path, content))
		return
	}

	// A directory: everything one level below the prefix.
	prefix := path + "/"
	var entries []map[string]any
	for p, content := range repo.files {
		rest, ok := strings.CutPrefix(p, prefix)
		if !ok || strings.Contains(rest, "/") {
			continue
		}
		entries = append(entries, contentEntry(p, content))
	}
	if len(entries) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i]["path"].(string) < entries[j]["path"].(string)
	})
	writeJSON(w, http.StatusOK, entries)
}

// getReadme answers as GitHub does: the file at the repository root whose
// name is README in any case and with any extension, and a 404 when there is
// none. Which of several wins is GitHub's own preference order, so a test can
// prove the badge goes in the file people actually see.
func (f *FakeGitHub) getReadme(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) || !f.canReadContentsLocked() {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	var names []string
	for p := range repo.files {
		if strings.Contains(p, "/") {
			continue
		}
		if base := strings.ToLower(p); base == "readme" || strings.HasPrefix(base, "readme.") {
			names = append(names, p)
		}
	}
	if len(names) == 0 {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	sort.Slice(names, func(i, j int) bool {
		return readmeRank(names[i]) < readmeRank(names[j]) || (readmeRank(names[i]) == readmeRank(names[j]) && names[i] < names[j])
	})
	writeJSON(w, http.StatusOK, contentEntry(names[0], repo.files[names[0]]))
}

// readmeRank orders README candidates the way GitHub prefers them: a Markdown
// one before any other markup, and markup before plain text.
func readmeRank(name string) int {
	switch strings.ToLower(name[strings.LastIndex(name, ".")+1:]) {
	case "md", "markdown":
		return 0
	case "rst", "adoc", "org", "textile":
		return 1
	}
	return 2
}

func contentEntry(path, content string) map[string]any {
	return map[string]any{
		"type":     "file",
		"name":     path[strings.LastIndex(path, "/")+1:],
		"path":     path,
		"sha":      blobSHA(content),
		"size":     len(content),
		"encoding": "base64",
		"content":  base64.StdEncoding.EncodeToString([]byte(content)),
	}
}

func (f *FakeGitHub) putContents(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	path := strings.Trim(r.PathValue("path"), "/")

	var body struct {
		Message string `json:"message"`
		Content string `json:"content"`
		SHA     string `json:"sha"`
		Branch  string `json:"branch"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}
	decoded, err := base64.StdEncoding.DecodeString(body.Content)
	if err != nil {
		writeError(w, http.StatusBadRequest, "content is not base64")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if body.Branch != "" {
		if _, ok := repo.branches[body.Branch]; !ok {
			writeError(w, http.StatusNotFound, "Branch "+body.Branch+" not found")
			return
		}
	}
	if body.Message == "" {
		writeError(w, http.StatusUnprocessableEntity, "message is required")
		return
	}
	existing, exists := repo.files[path]
	switch {
	case exists && body.SHA == "":
		writeError(w, http.StatusUnprocessableEntity, path+" exists; a sha is required to update it")
		return
	case exists && body.SHA != blobSHA(existing):
		// The real failure this guards: somebody pushed to the file between the
		// wizard reading it and the operator approving the migration.
		writeError(w, http.StatusConflict, path+" has changed since it was read")
		return
	}
	repo.files[path] = string(decoded)
	writeJSON(w, http.StatusOK, map[string]any{
		"content": contentEntry(path, string(decoded)),
		"commit":  map[string]any{"sha": blobSHA(body.Message + string(decoded))},
	})
}

func (f *FakeGitHub) getRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	ref := strings.Trim(r.PathValue("ref"), "/")
	branch := strings.TrimPrefix(ref, "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if branch == repo.defaultBranch {
		repo.pinContextSource()
	}
	sha, ok := repo.branches[branch]
	if !ok {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"ref":    "refs/heads/" + branch,
		"object": map[string]any{"sha": sha, "type": "commit"},
	})
}

func (f *FakeGitHub) createRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	var body struct {
		Ref string `json:"ref"`
		SHA string `json:"sha"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}
	branch := strings.TrimPrefix(strings.TrimPrefix(body.Ref, "refs/"), "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if branch == "" || body.SHA == "" {
		writeError(w, http.StatusUnprocessableEntity, "ref and sha are required")
		return
	}
	if _, exists := repo.branches[branch]; exists {
		writeError(w, http.StatusUnprocessableEntity, "Reference already exists")
		return
	}
	repo.branches[branch] = body.SHA
	writeJSON(w, http.StatusCreated, map[string]any{
		"ref":    "refs/heads/" + branch,
		"object": map[string]any{"sha": body.SHA, "type": "commit"},
	})
}

// deleteRef removes a branch. Like GitHub it refuses the default branch, and it
// does not close or forget pull requests: the real API closes a pull request
// whose head branch is deleted, which is why the migration only cleans up a
// branch it knows has none.
func (f *FakeGitHub) deleteRef(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	branch := strings.TrimPrefix(strings.Trim(r.PathValue("ref"), "/"), "heads/")

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	if _, ok := repo.branches[branch]; !ok {
		writeError(w, http.StatusUnprocessableEntity, "Reference does not exist")
		return
	}
	if branch == repo.defaultBranch {
		writeError(w, http.StatusUnprocessableEntity, "Cannot delete the default branch")
		return
	}
	delete(repo.branches, branch)
	w.WriteHeader(http.StatusNoContent)
}

func (f *FakeGitHub) createPull(w http.ResponseWriter, r *http.Request) {
	full := fullName(r)
	var body struct {
		Title string `json:"title"`
		Body  string `json:"body"`
		Head  string `json:"head"`
		Base  string `json:"base"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid body")
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if !slices.Contains(f.repos, full) {
		writeError(w, http.StatusNotFound, "Not Found")
		return
	}
	repo := f.repoLocked(full)
	if repo.archived {
		writeError(w, http.StatusForbidden, "Repository was archived so is read-only.")
		return
	}
	for _, branch := range []string{body.Head, body.Base} {
		if _, ok := repo.branches[branch]; !ok {
			writeError(w, http.StatusUnprocessableEntity, "Branch "+branch+" not found")
			return
		}
	}
	if strings.TrimSpace(body.Title) == "" {
		writeError(w, http.StatusUnprocessableEntity, "title is required")
		return
	}
	repo.pulls++
	number := repo.pulls
	if repo.pullBodies == nil {
		repo.pullBodies = map[int]string{}
	}
	repo.pullBodies[number] = body.Body
	repo.contextGit().Pulls = append(repo.contextGit().Pulls, &gh.PullRequest{Number: gh.Ptr(number), Title: gh.Ptr(body.Title), Body: gh.Ptr(body.Body), State: gh.Ptr("open"), Head: &gh.PullRequestBranch{Ref: gh.Ptr(body.Head)}, Base: &gh.PullRequestBranch{Ref: gh.Ptr(body.Base)}, HTMLURL: gh.Ptr(fmt.Sprintf("https://github.com/%s/pull/%d", full, number))})
	if repo.contextGit().LoseNextPullResponse {
		repo.contextGit().LoseNextPullResponse = false
		writeError(w, http.StatusBadGateway, "Response lost after opening pull request")
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{
		"number":   number,
		"title":    body.Title,
		"body":     body.Body,
		"head":     map[string]any{"ref": body.Head},
		"base":     map[string]any{"ref": body.Base},
		"html_url": fmt.Sprintf("https://github.com/%s/pull/%d", full, number),
	})
}

// canReadContentsLocked reports whether the App this fake describes was granted
// the Contents permission. The caller holds f.mu.
func (f *FakeGitHub) canReadContentsLocked() bool {
	switch f.permissions["contents"] {
	case "read", "write":
		return true
	}
	return false
}

package github

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// maxAppNameLength is GitHub's limit on a GitHub App name. Hitting it during
// the manifest POST produces an unhelpful 422, so the check happens here.
const maxAppNameLength = 34

// ManifestOptions describes the App the installer asks GitHub to create.
type ManifestOptions struct {
	// Name is the App's display name, unique across all of GitHub.
	Name string
	// URL is the App's homepage, shown on its GitHub page.
	URL string
	// WebhookURL is where GitHub delivers workflow_job events.
	WebhookURL string
	// Organization is the org the App is created under. Empty creates it on
	// the operator's own account, which is the right choice for repo targets.
	Organization string
	// SetupURL is permanent App configuration: GitHub sends the operator here
	// after every future install or reconfiguration of the App -- adding a
	// repository to the installation, most commonly, years later. It has to be
	// an address that still answers then.
	SetupURL string
	// RedirectURL is where GitHub returns during *this* handshake, carrying
	// ?code=. Empty means "the same as SetupURL", which is right when the
	// handshake is driven from the controller's own web UI.
	//
	// They are separate because the installer is not: it catches the callback
	// on a temporary loopback listener that is gone minutes later, and writing
	// that ephemeral port into setup_url left every App `zoomies init` ever
	// created sending its operator to a refused connection.
	RedirectURL string
	// Public allows the App to be installed on accounts other than the one
	// that created it. Zoomies defaults it off: a fleet controller's App has
	// no business being installable by strangers.
	Public bool
	// AllowWorkflowCancellation raises Actions from read to write so Zoomies
	// can cancel workflow runs. It is opt-in because write is not needed to run
	// the fleet.
	AllowWorkflowCancellation bool
	// Migration adds the three repository permissions the migration wizard needs
	// to rewrite a runs-on line and open a pull request for it: contents,
	// pull_requests and workflows, all at write. It is opt-in because nothing
	// else in Zoomies writes to a repository, so an App that carries them by
	// default hands every installation write access to code and to CI workflows
	// for a feature most of them will never use.
	Migration bool
}

// manifest is the wire format of GitHub's App manifest.
type manifest struct {
	Name               string            `json:"name"`
	URL                string            `json:"url"`
	HookAttributes     hookAttributes    `json:"hook_attributes"`
	RedirectURL        string            `json:"redirect_url,omitempty"`
	SetupURL           string            `json:"setup_url,omitempty"`
	SetupOnUpdate      bool              `json:"setup_on_update"`
	Description        string            `json:"description,omitempty"`
	Public             bool              `json:"public"`
	DefaultEvents      []string          `json:"default_events"`
	DefaultPermissions map[string]string `json:"default_permissions"`
}

// hookAttributes carries the webhook configuration. GitHub's manifest schema
// permits exactly url and active here: sending a "secret" key makes GitHub
// reject the whole manifest with `"secret" is not a permitted key`. The secret
// is GitHub's to generate, and it comes back from the conversion in
// ManifestCredentials.WebhookSecret.
type hookAttributes struct {
	URL    string `json:"url"`
	Active bool   `json:"active"`
}

// Manifest renders the JSON an operator's browser POSTs to GitHub to create
// the App.
//
// The permission set is deliberately minimal, because an App that manages a
// fleet's runners is a high-value credential: it asks for the runner
// administration permission for the kind of target it will manage, read access
// to Actions so it can see queued jobs, and nothing else. The three the
// migration wizard needs to rewrite a runs-on line and open a pull request for
// it are added only when the operator has said they want the wizard.
// Metadata read is mandatory for every App.
//
// Every key here is one GitHub's manifest schema permits; it rejects anything
// else outright, so nothing speculative belongs in this struct.
func Manifest(o ManifestOptions) ([]byte, error) {
	name := strings.TrimSpace(o.Name)
	switch {
	case name == "":
		return nil, fmt.Errorf("github: app manifest: a name is required; pick something that "+
			"identifies this controller, such as %q", "zoomies-acme")
	case len(name) > maxAppNameLength:
		return nil, fmt.Errorf("github: app manifest: the name %q is %d characters; GitHub allows "+
			"at most %d", name, len(name), maxAppNameLength)
	}
	if strings.TrimSpace(o.URL) == "" {
		return nil, fmt.Errorf("github: app manifest: a homepage url is required; set " +
			"server.external_url in zoomies.yaml")
	}
	if strings.TrimSpace(o.WebhookURL) == "" {
		return nil, fmt.Errorf("github: app manifest: a webhook url is required; set " +
			"server.external_url in zoomies.yaml so GitHub can reach this controller")
	}

	redirect := o.RedirectURL
	if redirect == "" {
		redirect = o.SetupURL
	}

	m := manifest{
		Name: name,
		URL:  o.URL,
		// No secret is sent: GitHub generates one for a manifest-created App
		// and returns it through the conversion, which Zoomies then seals.
		HookAttributes: hookAttributes{URL: o.WebhookURL, Active: true},
		RedirectURL:    redirect,
		SetupURL:       o.SetupURL,
		Description:    "Self-hosted runner fleet managed by Zoomies.",
		Public:         o.Public,
		// workflow_job is the only event Zoomies acts on. Subscribing to more
		// would mean parsing payloads it has no use for.
		DefaultEvents:      []string{"workflow_job"},
		DefaultPermissions: manifestPermissions(o.Organization != "", o.AllowWorkflowCancellation, o.Migration),
	}
	b, err := json.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("github: app manifest: %w", err)
	}
	return b, nil
}

// manifestPermissions returns the least privilege that works for the target
// kind. An org App manages runners through the organisation permission and
// never needs repository administration; a repo App is the other way round.
//
// The three migration permissions are asked for only when the operator has said
// they want the wizard. Nothing else in Zoomies writes to a repository, and
// "can change code and CI workflows in every repository it is installed on" is
// the sentence that ends a security review, so an App that carried them by
// default made every installation pay for a feature most never use.
//
// The cost of the choice is real, and it is why this is a question on the
// consent screen rather than a silent default either way. Adding a permission
// to an App that already exists is not a setting an operator can just flip:
// GitHub holds the change until the account's owner accepts it on the
// installation, and until they do the migration wizard cannot even *read* a
// workflow. So the question is asked where saying yes costs a click, and the
// wizard names exactly what is missing, and where to add it, when the answer
// was no (MissingForMigration).
func manifestPermissions(org, allowWorkflowCancellation, migration bool) map[string]string {
	actions := "read"
	if allowWorkflowCancellation {
		actions = "write"
	}
	p := map[string]string{
		"actions":  actions,
		"metadata": "read",
	}
	if migration {
		// The migration wizard's three: read a repository's workflows, commit
		// the rewritten file to a branch, and open the pull request. GitHub
		// requires "workflows" specifically for a change under
		// .github/workflows, and grants nothing else with it.
		p["contents"] = "write"
		p["pull_requests"] = "write"
		p["workflows"] = "write"
	}
	if org {
		p["organization_self_hosted_runners"] = "write"
	} else {
		p["administration"] = "write"
	}
	return p
}

// ManifestURL returns the page the manifest form posts to. GitHub has a
// separate endpoint for creating an App under an organisation, and posting the
// org manifest to the user endpoint silently creates a personal App instead.
func ManifestURL(apiBaseURL, org string) string {
	web := WebURLForAPI(apiBaseURL)
	if org = strings.TrimSpace(org); org != "" {
		return web + "/organizations/" + org + "/settings/apps/new"
	}
	return web + "/settings/apps/new"
}

// ManifestCredentials is everything GitHub hands back once the operator has
// created the App. Every field except HTMLURL is a secret or identifies one.
type ManifestCredentials struct {
	AppID int64
	Slug  string
	Name  string
	// PEM is the App's private key. It is shown once and must be sealed
	// immediately.
	PEM string
	// WebhookSecret is the secret GitHub generated for the App's webhook. It
	// is the only copy: the manifest cannot ask for a particular one, and
	// GitHub does not show it again.
	WebhookSecret string
	ClientID      string
	ClientSecret  string
	HTMLURL       string
}

// manifestConversion is the wire format of the conversion response.
type manifestConversion struct {
	ID            int64  `json:"id"`
	Slug          string `json:"slug"`
	Name          string `json:"name"`
	PEM           string `json:"pem"`
	WebhookSecret string `json:"webhook_secret"`
	ClientID      string `json:"client_id"`
	ClientSecret  string `json:"client_secret"`
	HTMLURL       string `json:"html_url"`
	Message       string `json:"message"`
}

// ExchangeManifestCode trades the temporary code GitHub redirected back with
// for the App's real credentials.
//
// The code is valid for one hour and exactly one exchange, so a failure here
// means starting the manifest flow again rather than retrying.
func ExchangeManifestCode(ctx context.Context, apiBaseURL, code string) (*ManifestCredentials, error) {
	if strings.TrimSpace(code) == "" {
		return nil, fmt.Errorf("github: exchange manifest code: no code was returned by GitHub; " +
			"start the App creation again from the setup page")
	}
	base, err := NormalizeAPIBaseURL(apiBaseURL)
	if err != nil {
		return nil, fmt.Errorf("github: exchange manifest code: unusable api base url %q: %w", apiBaseURL, err)
	}
	// The code is escaped so a crafted one cannot rewrite the path or add a query
	// on the host it is sent to.
	endpoint := base + "app-manifests/" + url.PathEscape(code) + "/conversions"

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("github: exchange manifest code: %w", err)
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("X-GitHub-Api-Version", "2022-11-28")

	client := &http.Client{Timeout: defaultHTTPTimeout}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("github: exchange manifest code: cannot reach %s: %w", base, err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("github: exchange manifest code: reading response: %w", err)
	}
	var out manifestConversion
	// A non-JSON body here usually means a proxy answered instead of GitHub,
	// so the decode error is reported only when the status was otherwise fine.
	decodeErr := json.Unmarshal(bytes.TrimSpace(body), &out)

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		msg := out.Message
		if msg == "" {
			msg = strings.TrimSpace(string(body))
		}
		if resp.StatusCode == http.StatusNotFound {
			return nil, fmt.Errorf("%w: the manifest code has already been used or has expired "+
				"(codes last one hour): start the App creation again", ErrNotFound)
		}
		return nil, fmt.Errorf("github: exchange manifest code: GitHub returned %s: %s", resp.Status, msg)
	}
	if decodeErr != nil {
		return nil, fmt.Errorf("github: exchange manifest code: %s did not return JSON, which "+
			"usually means a proxy answered instead of GitHub: %w", endpoint, decodeErr)
	}
	if out.ID == 0 || out.PEM == "" {
		return nil, fmt.Errorf("github: exchange manifest code: GitHub returned no app id or " +
			"private key; start the App creation again")
	}
	return &ManifestCredentials{
		AppID:         out.ID,
		Slug:          out.Slug,
		Name:          out.Name,
		PEM:           out.PEM,
		WebhookSecret: out.WebhookSecret,
		ClientID:      out.ClientID,
		ClientSecret:  out.ClientSecret,
		HTMLURL:       out.HTMLURL,
	}, nil
}

// InstallURL returns the page that installs an App on an account, given the
// html_url the manifest conversion returned.
func InstallURL(htmlURL string) string {
	h := strings.TrimRight(strings.TrimSpace(htmlURL), "/")
	if h == "" {
		return ""
	}
	return h + "/installations/new"
}

// SettingsURL returns the App's own settings page, which is the only place its
// logo can be set.
//
// The App manifest schema has no field for an avatar -- GitHub takes it as an
// upload and nothing else -- so an App created by Zoomies arrives with the grey
// default, and every "Set up job" line in the organisation's logs is signed by
// an anonymous App. Pointing the operator at the page and handing them the
// mark is as close to automatic as GitHub allows.
//
// An App owned by an organisation has its settings under that organisation;
// one owned by a user has them under the user's own settings, and GitHub
// answers the wrong URL with a 404 rather than a redirect.
func SettingsURL(apiBaseURL, slug, org string) string {
	slug = strings.Trim(strings.TrimSpace(slug), "/")
	if slug == "" {
		return ""
	}
	web := strings.TrimRight(WebURLForAPI(apiBaseURL), "/")
	if org = strings.Trim(strings.TrimSpace(org), "/"); org != "" {
		return web + "/organizations/" + org + "/settings/apps/" + slug
	}
	return web + "/settings/apps/" + slug
}

package github

import (
	"context"
	"encoding/json"
	"errors"
	"maps"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"testing"
)

func decodeManifest(t *testing.T, o ManifestOptions) map[string]any {
	t.Helper()
	b, err := Manifest(o)
	if err != nil {
		t.Fatalf("Manifest: %v", err)
	}
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("manifest is not JSON: %v", err)
	}
	return m
}

func permissions(t *testing.T, m map[string]any) map[string]string {
	t.Helper()
	raw, ok := m["default_permissions"].(map[string]any)
	if !ok {
		t.Fatalf("default_permissions missing from %v", m)
	}
	out := make(map[string]string, len(raw))
	for k, v := range raw {
		s, ok := v.(string)
		if !ok {
			t.Fatalf("permission %q is %T, want string", k, v)
		}
		out[k] = s
	}
	return out
}

func TestManifestOrgShape(t *testing.T) {
	m := decodeManifest(t, ManifestOptions{
		Name:         "zoomies-acme",
		URL:          "https://zoomies.example.com",
		WebhookURL:   "https://zoomies.example.com/webhooks/github",
		Organization: "acme",
		SetupURL:     "https://zoomies.example.com/setup/github",
	})

	if m["name"] != "zoomies-acme" || m["url"] != "https://zoomies.example.com" {
		t.Fatalf("identity fields wrong: %v", m)
	}
	if m["public"] != false {
		t.Fatalf("public = %v, want false: a fleet controller's App must not be installable by strangers", m["public"])
	}

	hook, ok := m["hook_attributes"].(map[string]any)
	if !ok {
		t.Fatalf("hook_attributes missing: %v", m)
	}
	if hook["url"] != "https://zoomies.example.com/webhooks/github" || hook["active"] != true {
		t.Fatalf("hook_attributes = %v", hook)
	}

	events, _ := m["default_events"].([]any)
	if len(events) != 1 || events[0] != "workflow_job" {
		t.Fatalf("default_events = %v, want exactly [workflow_job]", events)
	}

	// Runner administration, the read access that lets it see queued jobs, and
	// the metadata read GitHub makes mandatory: nothing that can write code.
	want := map[string]string{
		"organization_self_hosted_runners": "write",
		"actions":                          "read",
		"metadata":                         "read",
	}
	if got := permissions(t, m); !maps.Equal(got, want) {
		t.Fatalf("permissions = %v, want %v", got, want)
	}

	// Both hops of the flow land back on the installer page: one with ?code=,
	// the other with ?installation_id=.
	if m["redirect_url"] != "https://zoomies.example.com/setup/github" ||
		m["setup_url"] != "https://zoomies.example.com/setup/github" {
		t.Fatalf("setup urls = %v / %v", m["redirect_url"], m["setup_url"])
	}
}

func TestManifestRequestsActionsWriteOnlyWhenCancellationEnabled(t *testing.T) {
	m := decodeManifest(t, ManifestOptions{
