const ciWorkflow = "jobs:\n  build:\n    runs-on: ubuntu-latest\n"

func migrationFake(t *testing.T) (*FakeGitHub, Client) {
	t.Helper()
	f := NewFake()
	t.Cleanup(f.Close)
	f.AddWorkflow("acme/widgets", ".github/workflows/ci.yml", ciWorkflow)
	f.AddWorkflow("acme/widgets", ".github/workflows/release.yaml", "jobs:\n  ship:\n    runs-on: ubuntu-22.04\n")
	// Not a workflow GitHub runs, and not one to open a pull request about.
	f.AddWorkflow("acme/widgets", ".github/workflows/nested/old.yml", ciWorkflow)
	f.AddWorkflow("acme/widgets", ".github/workflows/README.md", "notes")
	f.AddRepo("acme/site")
	return f, f.Client("acme", store.TargetOrg)
}

func TestListRepositoriesForAnOrg(t *testing.T) {
	f, c := migrationFake(t)
	f.SetDefaultBranch("acme/site", "master")

	repos, err := c.ListRepositories(context.Background(), 0)
	if err != nil {
		t.Fatalf("ListRepositories: %v", err)
	}
	if len(repos) != 2 {
		t.Fatalf("repos = %+v, want both", repos)
	}
	byName := map[string]Repository{}
	for _, r := range repos {
		byName[r.FullName] = r
	}
	if got := byName["acme/widgets"].DefaultBranch; got != "main" {
		t.Errorf("acme/widgets default branch = %q, want main", got)
	}
	// A repository that never renamed its default branch is the case a
	// migration silently breaks on if the branch is guessed.
	if got := byName["acme/site"].DefaultBranch; got != "master" {
		t.Errorf("acme/site default branch = %q, want master", got)
	}
}

func TestListRepositoriesForARepoInstallation(t *testing.T) {
	f, _ := migrationFake(t)
	c := f.Client("acme/widgets", store.TargetRepo)

	repos, err := c.ListRepositories(context.Background(), 0)
	if err != nil {
		t.Fatalf("ListRepositories: %v", err)
	}
	if len(repos) != 1 || repos[0].FullName != "acme/widgets" || repos[0].ID <= 0 {
		t.Fatalf("repos = %+v, want just the installation's own repository", repos)
	}
}

func TestListWorkflows(t *testing.T) {
	_, c := migrationFake(t)

	got, err := c.ListWorkflows(context.Background(), "acme/widgets")
	if err != nil {
		t.Fatalf("ListWorkflows: %v", err)
	}
	var paths []string
	for _, w := range got {
		paths = append(paths, w.Path)
	}
	want := ".github/workflows/ci.yml,.github/workflows/release.yaml"
	if strings.Join(paths, ",") != want {
		t.Fatalf("paths = %v, want %q: only the yaml files at the top of the directory", paths, want)
	}
	if got[0].Content != ciWorkflow {
		t.Errorf("content = %q, want the file as it is on the default branch", got[0].Content)
	}
	if got[0].SHA == "" {
		t.Error("no blob sha, so an update could not be made safe against a concurrent push")
	}
}

// Most repositories in a large organisation have no workflows at all. That is
// an ordinary answer, not a broken installation, and it has its own error so a
// caller can tell the two apart.
func TestListWorkflowsWithoutAny(t *testing.T) {
	_, c := migrationFake(t)
	_, err := c.ListWorkflows(context.Background(), "acme/site")
	if !errors.Is(err, ErrNoWorkflows) {
		t.Fatalf("err = %v, want ErrNoWorkflows", err)
	}
}

func TestOpenPullRequest(t *testing.T) {
	f, c := migrationFake(t)
	before, _ := f.FileContent("acme/widgets", ".github/workflows/ci.yml")
	after := strings.Replace(before, "ubuntu-latest", "zoomies-linux-x64", 1)

	branch := BranchName(time.Date(2026, 3, 1, 9, 30, 0, 0, time.UTC))
	pr, err := c.OpenPullRequest(context.Background(), PullRequestRequest{
		Repo:          "acme/widgets",
		Head:          branch,
		Title:         "Move CI onto Zoomies runners",
		Body:          "One job moved.",
		CommitMessage: "Move CI onto Zoomies runners",
		Files: []FileChange{{
			Path:    ".github/workflows/ci.yml",
			Content: after,
			SHA:     blobSHA(before),
		}},
	})
	if err != nil {
		t.Fatalf("OpenPullRequest: %v", err)
	}
	if pr.Number != 1 || !strings.HasSuffix(pr.HTMLURL, "/acme/widgets/pull/1") {
		t.Errorf("pull request = %+v", pr)
	}
	if pr.Branch != branch {
		t.Errorf("branch = %q, want %q", pr.Branch, branch)
	}
	if got, _ := f.FileContent("acme/widgets", ".github/workflows/ci.yml"); got != after {
		t.Errorf("the file on GitHub is %q, want the rewritten one", got)
	}
	// The default branch is left alone; the change lives on its own branch.
	if branches := f.Branches("acme/widgets"); len(branches) != 2 {
		t.Errorf("branches = %v, want main plus the migration branch", branches)
	}
}

// The wizard reads a file, the operator thinks about it, and somebody pushes to
// the file in between. Committing anyway would silently revert their change.
func TestOpenPullRequestRefusesAStaleFile(t *testing.T) {
	_, c := migrationFake(t)
	_, err := c.OpenPullRequest(context.Background(), PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-stale",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{
			Path:    ".github/workflows/ci.yml",
			Content: "jobs: {}\n",
			SHA:     blobSHA("something else entirely"),
		}},
	})
	if err == nil {
		t.Fatal("a commit against a stale sha was accepted")
	}
	if !strings.Contains(err.Error(), "has changed since it was read") {
		t.Fatalf("err = %v, want it to say the file moved under us", err)
	}
}

// A failed attempt used to leave a zoomies/migrate-runners-<timestamp> branch on
// the customer's repository with no pull request to close, and the next attempt
// a second one, because the name is never reused. A repository that failed is
// meant to be left as it was.
func TestAFailedMigrationLeavesNoBranchBehind(t *testing.T) {
	stale := PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-failing",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{Path: ".github/workflows/ci.yml", Content: "jobs: {}\n", SHA: blobSHA("something else entirely")}},
	}
	for _, tc := range []struct {
		name    string
		arrange func(f *FakeGitHub)
		req     PullRequestRequest
	}{
		{"a commit that is refused", func(*FakeGitHub) {}, stale},
		{"a later file that is refused after an earlier one committed", func(*FakeGitHub) {}, PullRequestRequest{
			Repo:  "acme/widgets",
			Head:  "zoomies/migrate-runners-second-file",
			Title: "Move CI onto Zoomies runners",
			Files: []FileChange{
				{Path: ".github/workflows/new.yml", Content: "jobs: {}\n"},
				{Path: ".github/workflows/ci.yml", Content: "jobs: {}\n", SHA: blobSHA("something else entirely")},
			},
		}},
		{"a pull request GitHub refuses to open", func(f *FakeGitHub) {
			f.SetMethodError(http.MethodPost, "/pulls", http.StatusUnprocessableEntity, "Validation Failed")
		}, PullRequestRequest{
			Repo:  "acme/widgets",
			Head:  "zoomies/migrate-runners-refused",
			Title: "Move CI onto Zoomies runners",
			Files: []FileChange{{Path: ".github/workflows/new.yml", Content: "jobs: {}\n"}},
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f, c := migrationFake(t)
			tc.arrange(f)
			if _, err := c.OpenPullRequest(context.Background(), tc.req); err == nil {
				t.Fatal("the migration succeeded, so there is nothing to clean up")
			}
			if branches := f.Branches("acme/widgets"); len(branches) != 1 || branches[0] != "main" {
				t.Fatalf("branches = %v, want only main: the failed attempt left its branch behind", branches)
			}
		})
	}
}

// If the request to open the pull request is cut off, or GitHub answers with a
// server error, the pull request may exist anyway. Deleting its head branch
// would close it, so an ambiguous failure keeps the branch and says so.
func TestAnAmbiguousPullRequestFailureKeepsTheBranchAndSaysSo(t *testing.T) {
	f, c := migrationFake(t)
	f.SetMethodError(http.MethodPost, "/pulls", http.StatusBadGateway, "Bad Gateway")

	_, err := c.OpenPullRequest(context.Background(), PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-ambiguous",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{Path: ".github/workflows/new.yml", Content: "jobs: {}\n"}},
	})
	if err == nil {
		t.Fatal("the migration succeeded")
	}
	if !slices.Contains(f.Branches("acme/widgets"), "zoomies/migrate-runners-ambiguous") {
		t.Fatal("the branch was deleted although the pull request may have been opened from it")
	}
	if !strings.Contains(err.Error(), "migrate-runners-ambiguous was kept") {
		t.Fatalf("err = %v, want it to name the branch that was kept", err)
	}
}

// Cleanup is best effort, and an operator who is not told the branch is still
// there has no way to know to remove it.
func TestAMigrationThatCannotRemoveItsBranchSaysWhereItIs(t *testing.T) {
	f, c := migrationFake(t)
	f.SetMethodError(http.MethodDelete, "/git/refs/", http.StatusInternalServerError, "boom")

	_, err := c.OpenPullRequest(context.Background(), PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-stuck",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{Path: ".github/workflows/ci.yml", Content: "jobs: {}\n", SHA: blobSHA("something else entirely")}},
	})
	if err == nil || !strings.Contains(err.Error(), "has changed since it was read") {
		t.Fatalf("err = %v, want the original failure to come first", err)
	}
	if !strings.Contains(err.Error(), "migrate-runners-stuck could not be removed") {
		t.Fatalf("err = %v, want it to name the branch left behind", err)
	}
}

func TestOpenPullRequestRefusesAnExistingBranch(t *testing.T) {
	f, c := migrationFake(t)
	req := PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-once",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{Path: ".github/workflows/new.yml", Content: "jobs: {}\n"}},
	}
	if _, err := c.OpenPullRequest(context.Background(), req); err != nil {
		t.Fatalf("the first attempt failed: %v", err)
	}
	// Reusing the branch would rewrite a pull request somebody may already be
	// reviewing, so it has to fail rather than force.
	if _, err := c.OpenPullRequest(context.Background(), req); err == nil {
		t.Fatal("the same branch was created twice")
	}
	// The refusal came before this call created anything, so its cleanup must
	// not reach the first attempt's branch, which has a pull request.
	if !slices.Contains(f.Branches("acme/widgets"), req.Head) {
		t.Fatal("a refused second attempt deleted the branch the first one opened its pull request from")
	}
}

// A 403 here is almost always the three permissions the App was never given,
// and the generic runner-permission hint would send the operator to a settings
// page that is already correct.
func TestOpenPullRequestExplainsAForbidden(t *testing.T) {
	f, c := migrationFake(t)
	f.SetError("/git/refs", http.StatusForbidden, "Resource not accessible by integration")

	_, err := c.OpenPullRequest(context.Background(), PullRequestRequest{
		Repo:  "acme/widgets",
		Head:  "zoomies/migrate-runners-denied",
		Title: "Move CI onto Zoomies runners",
		Files: []FileChange{{Path: ".github/workflows/new.yml", Content: "jobs: {}\n"}},
	})
	if err == nil {
		t.Fatal("expected a failure")
	}
	if !errors.Is(err, ErrForbidden) {
		t.Errorf("err = %v, want it to wrap ErrForbidden", err)
	}
	for _, want := range []string{"Contents", "Pull requests", "Workflows"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("err = %v, want it to name the %q permission", err, want)
		}
	}
}

// A scan is the first thing an operator runs, and a 403 there used to be
// decorated with the runner permissions -- which are set correctly, so the
// operator checks them, finds nothing wrong, and concludes Zoomies is broken.
// Reading needs the same three permissions writing does, and says so.
func TestListWorkflowsExplainsAForbidden(t *testing.T) {
	f, c := migrationFake(t)
	f.SetError("/contents/", http.StatusForbidden, "Resource not accessible by integration")

	_, err := c.ListWorkflows(context.Background(), "acme/widgets")
	if err == nil {
		t.Fatal("expected a failure")
	}
	if !errors.Is(err, ErrForbidden) {
		t.Errorf("err = %v, want it to wrap ErrForbidden", err)
	}
	for _, want := range []string{"Contents", "Pull requests", "Workflows"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("err = %v, want it to name the %q permission", err, want)
		}
	}
	if strings.Contains(err.Error(), "Self-hosted runners") {
		t.Errorf("err = %v, sends the operator to the runner permissions, which are not the problem", err)
	}
}

// The migration permissions are opt-in at creation, because adding one
// afterwards is held by GitHub until the account's owner accepts it -- and
// until they do the wizard cannot read a workflow at all. So the question is
// asked where saying yes costs a click, and the two answers have to mean what
// they say: an App made with the option can run the wizard the day it is
// installed, and one made without it says plainly which three permissions it
// lacks rather than failing halfway through opening pull requests.
func TestManifestGrantsWhatTheMigrationNeedsWhenAskedTo(t *testing.T) {
	granted := func(t *testing.T, o ManifestOptions) *AppInfo {
		t.Helper()
		b, err := Manifest(o)
		if err != nil {
			t.Fatalf("Manifest: %v", err)
		}
		var m struct {
			Permissions map[string]string `json:"default_permissions"`
		}
		if err := json.Unmarshal(b, &m); err != nil {
			t.Fatalf("decode manifest: %v", err)
		}
		return &AppInfo{Permissions: m.Permissions}
	}
	for _, org := range []string{"", "acme"} {
		base := ManifestOptions{
			Name: "zoomies", URL: "https://z.example", WebhookURL: "https://z.example/w",
			Organization: org,
		}

		base.Migration = true
		if missing := granted(t, base).MissingForMigration(); len(missing) != 0 {
			t.Errorf("an App created for migration (org=%q) still cannot migrate: %v", org, missing)
		}

		base.Migration = false
		if missing := granted(t, base).MissingForMigration(); len(missing) != len(MigrationPermissions) {
			t.Errorf("an App created without migration (org=%q) reports %v missing, want all %d named",
				org, missing, len(MigrationPermissions))
		}
	}
}

func TestMissingForMigration(t *testing.T) {
	full := &AppInfo{Permissions: map[string]string{
		"contents": "write", "pull_requests": "write", "workflows": "write",
	}}
	if got := full.MissingForMigration(); len(got) != 0 {
		t.Fatalf("MissingForMigration = %v, want none", got)
	}

	partial := &AppInfo{Permissions: map[string]string{"contents": "read"}}
	got := partial.MissingForMigration()
	if len(got) != 3 {
		t.Fatalf("MissingForMigration = %v, want all three named", got)
	}
	if !strings.Contains(got[0], "only read") {
		t.Errorf("%q does not say what the permission currently is", got[0])
	}
	if !strings.Contains(got[1], "not granted") {
		t.Errorf("%q does not say the permission is absent", got[1])
	}
}

func TestBranchNameIsUniquePerRun(t *testing.T) {
	at := time.Date(2026, 3, 1, 9, 30, 0, 0, time.UTC)
	if got := BranchName(at); got != "zoomies/migrate-runners-20260301-093000" {
		t.Fatalf("BranchName = %q", got)
	}
	if BranchName(at) == BranchName(at.Add(time.Second)) {
		t.Error("two runs a second apart would collide on the same branch")
	}
}

// GitHub decides which file is a repository's README, so the fake answers the
// way GitHub does: any case, any extension, Markdown first.
func TestReadReadmeFindsTheFileGitHubRenders(t *testing.T) {
	f, c := migrationFake(t)
	f.AddFile("acme/widgets", "readme.markdown", "# Widgets\n")
	f.AddFile("acme/widgets", "README.txt", "widgets")
	f.AddFile("acme/widgets", "docs/README.md", "not the front page")

	got, err := c.ReadReadme(context.Background(), "acme/widgets")
	if err != nil {
		t.Fatalf("ReadReadme: %v", err)
	}
	if got.Path != "readme.markdown" || got.Content != "# Widgets\n" || got.SHA != blobSHA("# Widgets\n") {
		t.Errorf("readme = %+v", got)
	}
}

// A repository without a README is the normal case for a badge to have
// nowhere to go, and it must read as that rather than as a broken App.
func TestReadReadmeWithoutOne(t *testing.T) {
	_, c := migrationFake(t)
	_, err := c.ReadReadme(context.Background(), "acme/site")
	if !errors.Is(err, ErrNoReadme) {
		t.Errorf("err = %v, want ErrNoReadme", err)
	}
}

func TestRepositoryIdentitySurvivesDefaultBranchChanges(t *testing.T) {
	f, c := migrationFake(t)
	before, err := c.ListRepositories(context.Background(), 0)
	if err != nil {
		t.Fatal(err)
	}
	f.SetDefaultBranch("acme/widgets", "trunk")
	after, err := c.ListRepositories(context.Background(), 0)
	if err != nil {
		t.Fatal(err)
	}
	ids := map[string]int64{}
	for _, repo := range before {
		ids[repo.FullName] = repo.ID
	}
	for _, repo := range after {
		if repo.ID <= 0 || repo.ID != ids[repo.FullName] {
			t.Fatalf("unstable repository identity: %+v", repo)
		}
	}
}

package github

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	gh "github.com/google/go-github/v88/github"

	"github.com/eyupio/zoomies/internal/store"
)

// Headers GitHub sets on every delivery. They are re-exported here so the API
// package does not need its own opinion about their spelling.
const (
	// SignatureHeader carries the HMAC-SHA256 of the body.
	SignatureHeader = gh.SHA256SignatureHeader
	// EventTypeHeader carries the event name, e.g. "workflow_job".
	EventTypeHeader = gh.EventTypeHeader
	// DeliveryIDHeader carries the delivery UUID, which is what an operator
	// quotes when comparing Zoomies' log with GitHub's redelivery page.
	DeliveryIDHeader = gh.DeliveryIDHeader
)

// ErrNoSecret is returned when Zoomies holds no webhook secret to verify a
// delivery against. It is a configuration fault, not an attack, and the API
// answers it differently from a bad signature.
var ErrNoSecret = errors.New("github: no webhook secret configured")

// ErrInvalidSignature is returned when a delivery is unsigned or its signature
// does not match. The API answers these with 401 and does not process the body.
var ErrInvalidSignature = errors.New("github: webhook signature invalid")

// ErrNotWorkflowJob is returned when a payload is not a workflow_job event.
var ErrNotWorkflowJob = errors.New("github: not a workflow_job payload")

// ValidateSignature checks the HMAC GitHub attached to a delivery.
//
// It refuses to pass an unsigned delivery under any circumstances: an endpoint
// that accepts unsigned webhooks lets anyone on the internet make Zoomies
// start runners.
func ValidateSignature(payload []byte, header, secret string) error {
	if secret == "" {
		return fmt.Errorf("%w: Zoomies has no webhook secret for this installation, so it cannot "+
			"tell a real delivery from a forged one: set one on the Installations page and copy the "+
			"same value into the App's webhook settings", ErrNoSecret)
	}
	if strings.TrimSpace(header) == "" {
		return fmt.Errorf("%w: the delivery carried no %s header, which means no webhook secret is "+
			"configured on the GitHub side: open the App's settings, set the webhook secret to the "+
			"value Zoomies holds, and redeliver", ErrInvalidSignature, SignatureHeader)
	}
	if err := gh.ValidateSignature(header, payload, []byte(secret)); err != nil {
		return fmt.Errorf("%w: the webhook secret on the GitHub App does not match the one Zoomies "+
			"holds for this installation, or the body was modified in transit", ErrInvalidSignature)
	}
	return nil
}

// ParseEventType normalises the X-GitHub-Event header. GitHub sends it
// lowercase, but proxies have been known to rewrite header values.
func ParseEventType(header string) string {
	return strings.ToLower(strings.TrimSpace(header))
}

// IsPing reports whether an event is GitHub's "does this endpoint exist"
// probe, which is sent once when a webhook is configured and carries no job.
func IsPing(event string) bool { return ParseEventType(event) == "ping" }

// WorkflowJobEvent is the part of a workflow_job delivery Zoomies acts on.
//
// It is a hand-written struct rather than go-github's event type because this
// payload is the load-bearing input of the whole scheduler: naming exactly the
// fields that matter keeps it obvious what a change to GitHub's payload would
// break.
type WorkflowJobEvent struct {
	// Action is "queued", "in_progress", "completed" or "waiting".
	Action string
	// InstallationID routes the delivery to one of Zoomies' installations.
	InstallationID int64

	JobID        int64
	RunID        int64
	Repo         string // "acme/widgets"
	WorkflowName string
	JobName      string
	// Labels are the workflow's runs-on values, including implicit ones.
	Labels     []string
	RunnerID   int64
	RunnerName string
	Status     string
	Conclusion string

	// QueuedAt is the job's created_at, i.e. when GitHub started looking for a
	// runner.
	QueuedAt    time.Time
	StartedAt   time.Time
	CompletedAt time.Time
	HTMLURL     string

	// HeadBranch, HeadSHA and RunAttempt say what the job ran for.
	HeadBranch string
	HeadSHA    string
	RunAttempt int
	// Steps are the job's steps as this delivery reports them. On a completed
	// delivery every step carries its conclusion, which is what lets a failed
	// job say where it failed.
	Steps []store.JobStep
}

// workflowJobPayload mirrors the wire format. Timestamps are pointers because
// GitHub sends null for the ones that have not happened yet.
type workflowJobPayload struct {
	Action      string `json:"action"`
	WorkflowJob struct {
		ID           int64      `json:"id"`
		RunID        int64      `json:"run_id"`
		WorkflowName string     `json:"workflow_name"`
		Name         string     `json:"name"`
		Labels       []string   `json:"labels"`
		RunnerID     int64      `json:"runner_id"`
		RunnerName   string     `json:"runner_name"`
		Status       string     `json:"status"`
		Conclusion   string     `json:"conclusion"`
		CreatedAt    *time.Time `json:"created_at"`
		StartedAt    *time.Time `json:"started_at"`
		CompletedAt  *time.Time `json:"completed_at"`
		HTMLURL      string     `json:"html_url"`
		HeadBranch   string     `json:"head_branch"`
		HeadSHA      string     `json:"head_sha"`
		RunAttempt   int        `json:"run_attempt"`
		Steps        []struct {
			Number      int        `json:"number"`
			Name        string     `json:"name"`
			Status      string     `json:"status"`
			Conclusion  string     `json:"conclusion"`
			StartedAt   *time.Time `json:"started_at"`
			CompletedAt *time.Time `json:"completed_at"`
		} `json:"steps"`
	} `json:"workflow_job"`
	Repository struct {
		FullName string `json:"full_name"`
	} `json:"repository"`
	Installation struct {
		ID int64 `json:"id"`
	} `json:"installation"`
}

// ParseWorkflowJob decodes a workflow_job delivery.
func ParseWorkflowJob(payload []byte) (*WorkflowJobEvent, error) {
	var p workflowJobPayload
	if err := json.Unmarshal(payload, &p); err != nil {
		return nil, fmt.Errorf("github: parse workflow_job: %w", err)
	}
	if p.WorkflowJob.ID == 0 {
		return nil, fmt.Errorf("%w: the body has no workflow_job.id; check that the App is "+
			"subscribed to the \"workflow_job\" event and not to \"workflow_run\"", ErrNotWorkflowJob)
	}
	e := &WorkflowJobEvent{
		Action:         strings.ToLower(strings.TrimSpace(p.Action)),
		InstallationID: p.Installation.ID,
		JobID:          p.WorkflowJob.ID,
		RunID:          p.WorkflowJob.RunID,
		Repo:           p.Repository.FullName,
		WorkflowName:   p.WorkflowJob.WorkflowName,
		JobName:        p.WorkflowJob.Name,
		Labels:         p.WorkflowJob.Labels,
		RunnerID:       p.WorkflowJob.RunnerID,
		RunnerName:     p.WorkflowJob.RunnerName,
		Status:         strings.ToLower(strings.TrimSpace(p.WorkflowJob.Status)),
		Conclusion:     strings.ToLower(strings.TrimSpace(p.WorkflowJob.Conclusion)),
		HTMLURL:        p.WorkflowJob.HTMLURL,
		HeadBranch:     p.WorkflowJob.HeadBranch,
		HeadSHA:        p.WorkflowJob.HeadSHA,
		RunAttempt:     p.WorkflowJob.RunAttempt,
	}
	for _, st := range p.WorkflowJob.Steps {
		step := store.JobStep{
			Number:     st.Number,
			Name:       st.Name,
			Status:     strings.ToLower(strings.TrimSpace(st.Status)),
			Conclusion: strings.ToLower(strings.TrimSpace(st.Conclusion)),
		}
		if st.StartedAt != nil {
			t := st.StartedAt.UTC()
			step.StartedAt = &t
		}
		if st.CompletedAt != nil {
			t := st.CompletedAt.UTC()
			step.CompletedAt = &t
		}
		e.Steps = append(e.Steps, step)
	}
	if t := p.WorkflowJob.CreatedAt; t != nil {
		e.QueuedAt = t.UTC()
	}
	if t := p.WorkflowJob.StartedAt; t != nil {
		e.StartedAt = t.UTC()
	}
	if t := p.WorkflowJob.CompletedAt; t != nil {
		e.CompletedAt = t.UTC()
	}
	return e, nil
}

// State maps the delivery's action onto the job state machine.
//
// "waiting" means the job is held for a deployment review, which can take
// hours or days, and GitHub sends a real "queued" delivery once it is approved.
// It is its own state, ahead of queued in the lifecycle so the approval moves
// the job forward, and one the scheduler does not count: recording it as
// queued started a runner that idled out and was started again on the next
// pass, for as long as the review took.
func (e *WorkflowJobEvent) State() store.JobState {
	switch e.Action {
	case "waiting":
		return store.JobWaiting
	case "queued":
		return store.JobQueued
	case "in_progress":
		return store.JobInProgress
	case "completed":
		return store.JobCompleted
	}
	// Some GHES versions send actions Zoomies has not seen; the job's own
	// status field is then the better source.
	if s := store.JobState(e.Status); s.Valid() {
		return s
	}
	return store.JobQueued
}

// ToJob maps the event onto the row the store keeps, stamping the timestamps
// that this transition is the first evidence of.
//
// The returned Job has no ID: Store.UpsertJob keys on GitHubJobID and mints one
// for a job it has not seen before.
func (e *WorkflowJobEvent) ToJob() *store.Job {
	state := e.State()
	j := &store.Job{
		GitHubJobID: e.JobID,
		GitHubRunID: e.RunID,
		Repo:        e.Repo,
		Workflow:    e.WorkflowName,
		JobName:     e.JobName,
		Labels:      store.NormalizeLabels(e.Labels),
		State:       state,
		RunnerName:  e.RunnerName,
		HTMLURL:     e.HTMLURL,
		QueuedAt:    e.QueuedAt,
		HeadBranch:  e.HeadBranch,
		HeadSHA:     e.HeadSHA,
		RunAttempt:  e.RunAttempt,
		Steps:       e.Steps,
	}
	if j.QueuedAt.IsZero() {
		// A delivery without created_at still has to sort somewhere in the
		// queue-wait histogram; now is the closest honest answer.
		j.QueuedAt = time.Now().UTC()
	}
	// GitHub stamps started_at on a queued job too (equal to created_at), so
	// trusting it while queued would report a zero queue wait for every job. A
	// job held for a deployment review is the same: StartedAt is write-once in
	// the store, so a stamp taken while waiting would count the whole review as
	// run time and outlive the real one.
	if state != store.JobQueued && state != store.JobWaiting && !e.StartedAt.IsZero() {
		t := e.StartedAt
		j.StartedAt = &t
	}
	if state == store.JobCompleted {
		t := e.CompletedAt
		if t.IsZero() {
			t = time.Now().UTC()
		}
		j.CompletedAt = &t
		j.Conclusion = e.Conclusion
	}
	return j
}

package github

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

const testSecret = "s3cr3t-webhook"

func sign(t *testing.T, payload []byte, secret string) string {
	t.Helper()
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(payload)
	return "sha256=" + hex.EncodeToString(mac.Sum(nil))
}

func TestValidateSignature(t *testing.T) {
	payload := []byte(`{"action":"queued"}`)
	good := sign(t, payload, testSecret)

	t.Run("valid", func(t *testing.T) {
		if err := ValidateSignature(payload, good, testSecret); err != nil {
			t.Fatalf("valid signature rejected: %v", err)
		}
	})

	t.Run("wrong secret", func(t *testing.T) {
		err := ValidateSignature(payload, sign(t, payload, "other"), testSecret)
		if !errors.Is(err, ErrInvalidSignature) {
			t.Fatalf("got %v, want ErrInvalidSignature", err)
		}
	})

	t.Run("missing header", func(t *testing.T) {
		err := ValidateSignature(payload, "  ", testSecret)
		if !errors.Is(err, ErrInvalidSignature) {
			t.Fatalf("got %v, want ErrInvalidSignature", err)
		}
		// The operator needs to be sent to the GitHub side, not ours.
		if !strings.Contains(err.Error(), "GitHub side") || !strings.Contains(err.Error(), SignatureHeader) {
			t.Fatalf("unhelpful message for a missing signature: %v", err)
		}
	})

	t.Run("tampered body", func(t *testing.T) {
		err := ValidateSignature([]byte(`{"action":"completed"}`), good, testSecret)
		if !errors.Is(err, ErrInvalidSignature) {
			t.Fatalf("got %v, want ErrInvalidSignature", err)
		}
	})

	t.Run("no secret configured", func(t *testing.T) {
		err := ValidateSignature(payload, good, "")
		if !errors.Is(err, ErrNoSecret) {
			t.Fatalf("got %v, want ErrNoSecret", err)
		}
	})
}

func TestParseEventType(t *testing.T) {
	if got := ParseEventType("  Workflow_Job "); got != "workflow_job" {
		t.Fatalf("ParseEventType = %q", got)
	}
	if !IsPing("Ping") {
		t.Fatal("IsPing did not recognise a ping")
	}
	if IsPing("workflow_job") {
		t.Fatal("IsPing matched a workflow_job")
	}
}

// jobPayload renders a workflow_job delivery for one action.
func jobPayload(action, status, conclusion string, started, completed bool) []byte {
	body := `{
	  "action": "` + action + `",
	  "installation": {"id": 42},
	  "repository": {"full_name": "acme/widgets"},
	  "workflow_job": {
	    "id": 998877,
	    "run_id": 5544,
	    "workflow_name": "CI",
	    "name": "build (linux)",
	    "labels": ["self-hosted", "Linux", "gpu"],
	    "runner_id": 7,
	    "runner_name": "zoomies-linux-abcd",
	    "status": "` + status + `",
	    "conclusion": ` + jsonOrNull(conclusion) + `,
	    "created_at": "2024-05-01T10:00:00Z",
	    "started_at": ` + timeOrNull("2024-05-01T10:00:30Z", started) + `,
	    "completed_at": ` + timeOrNull("2024-05-01T10:05:00Z", completed) + `,
	    "html_url": "https://github.com/acme/widgets/actions/runs/5544/job/998877",
	    "head_branch": "main",
	    "head_sha": "0123456789abcdef0123456789abcdef01234567",
	    "run_attempt": 2,
	    "steps": [
	      {"number": 1, "name": "Set up job", "status": "completed", "conclusion": "success",
	       "started_at": "2024-05-01T10:00:30Z", "completed_at": "2024-05-01T10:00:35Z"},
	      {"number": 2, "name": "Run tests", "status": "` + stepStatus(completed) + `", "conclusion": ` + jsonOrNull(stepConclusion(conclusion, completed)) + `,
	       "started_at": "2024-05-01T10:00:35Z", "completed_at": ` + timeOrNull("2024-05-01T10:04:50Z", completed) + `},
	      {"number": 3, "name": "Upload", "status": "` + stepStatus(completed) + `", "conclusion": ` + jsonOrNull(skippedIf(completed)) + `}
	    ]
	  }
	}`
	return []byte(body)
}

// stepStatus, stepConclusion and skippedIf render the steps the way GitHub
// does: all of them "completed" with a conclusion once the job is over, and
// mid-flight before that.
func stepStatus(completed bool) string {
	if completed {
		return "completed"
	}
	return "in_progress"
}

func stepConclusion(conclusion string, completed bool) string {
	if !completed {
		return ""
	}
	return conclusion
}

func skippedIf(completed bool) string {
	if completed {
		return "skipped"
	}
	return ""
}

func jsonOrNull(s string) string {
	if s == "" {
		return "null"
	}
	return `"` + s + `"`
}

func timeOrNull(s string, present bool) string {
	if !present {
		return "null"
	}
	return `"` + s + `"`
}

func TestParseWorkflowJobQueued(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("queued", "queued", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if e.Action != "queued" || e.JobID != 998877 || e.RunID != 5544 {
		t.Fatalf("unexpected event: %+v", e)
	}
	if e.Repo != "acme/widgets" || e.WorkflowName != "CI" || e.JobName != "build (linux)" {
		t.Fatalf("unexpected identity: %+v", e)
	}
	if e.InstallationID != 42 || e.RunnerID != 7 || e.RunnerName != "zoomies-linux-abcd" {
		t.Fatalf("unexpected routing fields: %+v", e)
	}
	if !slices.Equal(e.Labels, []string{"self-hosted", "Linux", "gpu"}) {
		t.Fatalf("labels = %v", e.Labels)
	}
	if e.HTMLURL == "" || !e.CompletedAt.IsZero() {
		t.Fatalf("unexpected timestamps: %+v", e)
	}

	j := e.ToJob()
	if j.State != store.JobQueued {
		t.Fatalf("state = %q", j.State)
	}
	if j.ID != "" {
		t.Fatalf("ToJob minted an ID (%q); the store owns that", j.ID)
	}
	// GitHub stamps started_at on queued jobs too; trusting it would report a
	// zero queue wait for every job.
	if j.StartedAt != nil {
		t.Fatalf("queued job has StartedAt = %v", *j.StartedAt)
	}
	if !j.QueuedAt.Equal(time.Date(2024, 5, 1, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("queued_at = %v", j.QueuedAt)
	}
	if !slices.Equal(j.Labels, []string{"gpu", "linux", "self-hosted"}) {
		t.Fatalf("labels not normalised: %v", j.Labels)
	}
	if j.Conclusion != "" {
		t.Fatalf("queued job has a conclusion: %q", j.Conclusion)
	}
}

func TestParseWorkflowJobInProgress(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("in_progress", "in_progress", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	j := e.ToJob()
	if j.State != store.JobInProgress {
		t.Fatalf("state = %q", j.State)
	}
	if j.StartedAt == nil || !j.StartedAt.Equal(time.Date(2024, 5, 1, 10, 0, 30, 0, time.UTC)) {
		t.Fatalf("started_at = %v", j.StartedAt)
	}
	if j.CompletedAt != nil {
		t.Fatalf("running job has CompletedAt = %v", *j.CompletedAt)
	}
	if j.RunnerName != "zoomies-linux-abcd" {
		t.Fatalf("runner name lost: %q", j.RunnerName)
	}
	if got := j.QueueWait(); got != 30*time.Second {
		t.Fatalf("queue wait = %v, want 30s", got)
	}
}

func TestParseWorkflowJobCompleted(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "success", true, true))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	j := e.ToJob()
	if j.State != store.JobCompleted {
		t.Fatalf("state = %q", j.State)
	}
	if j.Conclusion != "success" {
		t.Fatalf("conclusion = %q", j.Conclusion)
	}
	if j.CompletedAt == nil || !j.CompletedAt.Equal(time.Date(2024, 5, 1, 10, 5, 0, 0, time.UTC)) {
		t.Fatalf("completed_at = %v", j.CompletedAt)
	}
	if got := j.Duration(); got != 4*time.Minute+30*time.Second {
		t.Fatalf("duration = %v", got)
	}
}

// The steps are what let a failed job say where it failed without the operator
// leaving for GitHub, and the branch and attempt are what make "CI failed" mean
// something.
func TestParseWorkflowJobCarriesTheStepsAndTheRunContext(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "failure", true, true))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if e.HeadBranch != "main" || e.HeadSHA != "0123456789abcdef0123456789abcdef01234567" || e.RunAttempt != 2 {
		t.Fatalf("run context = %q %q %d", e.HeadBranch, e.HeadSHA, e.RunAttempt)
	}
	if len(e.Steps) != 3 {
		t.Fatalf("steps = %+v, want 3", e.Steps)
	}
	j := e.ToJob()
	if j.HeadBranch != "main" || j.RunAttempt != 2 || len(j.Steps) != 3 {
		t.Fatalf("ToJob dropped the run context or the steps: %+v", j)
	}
	step := j.FailedStep()
	if step == nil || step.Number != 2 || step.Name != "Run tests" || step.Conclusion != "failure" {
		t.Fatalf("FailedStep = %+v, want step 2 'Run tests' failed", step)
	}
	if step.StartedAt == nil || step.CompletedAt == nil || step.CompletedAt.Sub(*step.StartedAt) != 4*time.Minute+15*time.Second {
		t.Fatalf("failed step timestamps = %v .. %v", step.StartedAt, step.CompletedAt)
	}
	// The step after the failure was skipped as a consequence, and must not be
	// the one reported.
	if j.Steps[2].Conclusion != "skipped" {
		t.Fatalf("step 3 conclusion = %q, want skipped", j.Steps[2].Conclusion)
	}

	// A job still running has steps too, but none of them has failed yet.
	running, err := ParseWorkflowJob(jobPayload("in_progress", "in_progress", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob in_progress: %v", err)
	}
	if rj := running.ToJob(); rj.FailedStep() != nil || len(rj.Steps) != 3 || rj.Steps[1].Status != "in_progress" {
		t.Fatalf("running job steps = %+v", rj.Steps)
	}
	// And a success has no failed step to name.
	ok, _ := ParseWorkflowJob(jobPayload("completed", "completed", "success", true, true))
	if ok.ToJob().FailedStep() != nil {
		t.Fatal("a successful job named a failed step")
	}
}

func TestParseWorkflowJobWaitingIsItsOwnState(t *testing.T) {
	// A job held for a deployment review is not demand: recorded as queued it
	// had the scheduler starting a runner nobody could use for as long as the
	// review took. It is "waiting", which sits before queued in the lifecycle
	// so that the approval's queued delivery still moves it forward.
	e, err := ParseWorkflowJob(jobPayload("waiting", "waiting", "", false, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if got := e.ToJob().State; got != store.JobWaiting {
		t.Fatalf("state = %q, want %q", got, store.JobWaiting)
	}
}

// GitHub stamps started_at on any job that has not started, and the store keeps
// StartedAt write-once. Trusting it on a held job would pin the start to the
// moment the job was created: the hours of review would then count as run time,
// the queue wait after approval would come out negative and be dropped, and the
// real started_at on the in_progress delivery could never replace it.
func TestAWaitingJobKeepsNoStartedAtFromItsDelivery(t *testing.T) {
	e, err := ParseWorkflowJob(jobPayload("waiting", "waiting", "", true, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	if e.StartedAt.IsZero() {
		t.Fatal("the payload carries no started_at, so this test proves nothing")
	}
	if j := e.ToJob(); j.StartedAt != nil {
		t.Fatalf("a waiting job has StartedAt = %v", *j.StartedAt)
	}
}

func TestParseWorkflowJobCompletedWithoutTimestamp(t *testing.T) {
	before := time.Now().UTC()
	e, err := ParseWorkflowJob(jobPayload("completed", "completed", "cancelled", false, false))
	if err != nil {
		t.Fatalf("ParseWorkflowJob: %v", err)
	}
	j := e.ToJob()
	if j.CompletedAt == nil || j.CompletedAt.Before(before) {
		t.Fatalf("completed_at should be stamped now, got %v", j.CompletedAt)
	}
}

func TestParseWorkflowJobRejectsOtherEvents(t *testing.T) {
	_, err := ParseWorkflowJob([]byte(`{"action":"completed","workflow_run":{"id":1}}`))
	if !errors.Is(err, ErrNotWorkflowJob) {
		t.Fatalf("got %v, want ErrNotWorkflowJob", err)
	}
	if _, err := ParseWorkflowJob([]byte(`not json`)); err == nil {
		t.Fatal("malformed JSON accepted")
	}
}

func TestToJobStampsQueuedAtWhenMissing(t *testing.T) {
	e := &WorkflowJobEvent{Action: "queued", JobID: 1}
	j := e.ToJob()
	if j.QueuedAt.IsZero() {
		t.Fatal("QueuedAt left zero; the queue-wait histogram cannot sort it")
	}
}

package installer

import (
	"bytes"
	"context"
	"log/slog"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/auth"
	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// An answer file is an unattended install, and the account it makes is the
// platform one: the audit log has to say the system made it and that an
// answer file said to, or the first row of every such instance's history is
// an account nobody can account for.
func TestTheAnswerFileAdministratorIsAudited(t *testing.T) {
	ctx := context.Background()
	st, err := store.Open(ctx, store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	i := &Installer{out: &bytes.Buffer{}, ui: newUI(&bytes.Buffer{}), log: slog.New(slog.DiscardHandler)}
	p := Plan{AdminUser: "ada", adminPassword: "correct-horse-battery"}
	if err := i.stepAdmin(ctx, st, config.Default(), p); err != nil {
		t.Fatalf("stepAdmin: %v", err)
	}

	rows, _, err := st.ListAudit(ctx, store.AuditFilter{Actions: []string{"auth.bootstrap"}}, store.Page{Limit: 10})
	if err != nil {
		t.Fatalf("ListAudit: %v", err)
	}
	if len(rows) != 1 {
		t.Fatalf("got %d auth.bootstrap rows; want exactly one", len(rows))
	}
	if rows[0].ActorKind != auth.KindSystem || !strings.Contains(rows[0].After, auth.BootstrapAnswerFile) {
		t.Fatalf("the row is by %s and says %s; want the system and the answer file", rows[0].ActorKind, rows[0].After)
	}
}

package installer

import (
	"fmt"
	"io"
	"os"
	"strings"

	"gopkg.in/yaml.v3"
)

// Answers is the answer file: one YAML key for every question `zoomies init`
// would otherwise ask.
//
// It exists so that a fleet can be rebuilt by configuration management without
// anyone sitting in front of it. Every field maps to exactly one prompt, and
// the non-interactive path uses the same decision code as the interactive one,
// so an answer file cannot drift away from what the prompts do.
type Answers struct {
	// Mode is single, controller or agent.
	Mode string `yaml:"mode"`
	// Deployment is native, compose or docker: how this host runs Zoomies,
	// which is a separate question from what it runs.
	Deployment string `yaml:"deployment"`
	// DeploymentDir is where a compose or docker deployment writes its
	// docker-compose.yml and its environment file.
	DeploymentDir string `yaml:"deployment_dir"`
	// Image is the container image those deployments run.
	Image string `yaml:"image"`
	// ServiceUser is the unprivileged account the service runs as.
	ServiceUser string `yaml:"service_user"`
	ConfigDir   string `yaml:"config_dir"`
	StateDir    string `yaml:"state_dir"`

	// Backend is docker, podman or process.
	Backend string `yaml:"backend"`
	// DockerHost overrides socket autodetection.
	DockerHost string `yaml:"docker_host"`
	// Capacity is the most runners this host may hold at once.
	Capacity int `yaml:"capacity"`

	Bind           string      `yaml:"bind"`
	TLS            AnswersTLS  `yaml:"tls"`
	TrustedProxies []string    `yaml:"trusted_proxies"`
	ExternalURL    string      `yaml:"external_url"`
	GitHub         AnswersApp  `yaml:"github"`
	Admin          AnswersUser `yaml:"admin"`
	Pool           AnswersPool `yaml:"pool"`
	Service        AnswersSvc  `yaml:"service"`
	Agent          AnswersJoin `yaml:"agent"`

	// path records where this file came from, so errors can name it.
	path string `yaml:"-"`
}

// AnswersTLS mirrors the bind-and-TLS question.
type AnswersTLS struct {
	// Mode is "off", "files" or "self-signed". Quote it: an unquoted off is a
	// boolean in YAML, not a word.
	Mode     string   `yaml:"mode"`
	CertFile string   `yaml:"cert_file"`
	KeyFile  string   `yaml:"key_file"`
	Hosts    []string `yaml:"hosts"`
}

// AnswersApp mirrors the GitHub App questions. A non-interactive run cannot
// drive a browser, so it takes credentials that already exist instead.
type AnswersApp struct {
	APIBaseURL string `yaml:"api_base_url"`
	// Target is an organisation login, or "owner/repo" for a single repository.
	Target string `yaml:"target"`
	// TargetType is org or repo. It is derived from Target when empty.
	TargetType     string `yaml:"target_type"`
	AppID          int64  `yaml:"app_id"`
	InstallationID int64  `yaml:"installation_id"`
	// PrivateKeyFile is the .pem GitHub gave you when the App was created.
	PrivateKeyFile string `yaml:"private_key_file"`
	// WebhookSecret is the secret configured on the App's webhook. Without it
	// Zoomies cannot verify deliveries and will reject every one.
	WebhookSecret string `yaml:"webhook_secret"`
	// WebhookSecretFile keeps the secret out of the answer file, which is the
	// better habit when that file lives in a repository.
	WebhookSecretFile string `yaml:"webhook_secret_file"`
	// Skip records a deliberate decision to connect GitHub later in the UI.
	Skip bool `yaml:"skip"`
}

// AnswersUser is the first administrator.
type AnswersUser struct {
	Username string `yaml:"username"`
	// Password is here for completeness; PasswordFile is the one to use when
	// the answer file is stored anywhere shared.
	Password     string `yaml:"password"`
	PasswordFile string `yaml:"password_file"`
}

// AnswersPool mirrors the first-pool question a single-host install asks.
//
// Every field is optional: an answer file that says nothing about pools gets
// the same pool the prompt would have offered, which is the one this host can
// actually run.
type AnswersPool struct {
	// Skip finishes setup with no pool. The Pools page is then empty and
	// nothing runs until one is created.
	Skip bool `yaml:"skip"`
	// Name overrides the suggested pool name, which is derived from this
	// host's OS, architecture and backend. It is branded on the way in, so a
	// name written here without the "zoomies-" prefix is given one.
	Name string `yaml:"name"`
	// Labels are what a workflow's runs-on has to ask for. Empty means the
	// pool answers to its own name.
	Labels []string `yaml:"labels"`
	// MaxRunners caps how many runners the pool may start at once. It cannot
	// usefully exceed the host's capacity, which is where the default comes
	// from.
	MaxRunners int `yaml:"max_runners"`
}

// AnswersSvc mirrors the service question.
type AnswersSvc struct {
	// Manager is systemd, launchd, compose or none.
	Manager string `yaml:"manager"`
	// Enable and Start are pointers so that "false" can be told apart from
	// "not mentioned", which is what lets a partial answer file work.
	Enable *bool `yaml:"enable"`
	Start  *bool `yaml:"start"`
}

// AnswersJoin mirrors `zoomies agent join`.
type AnswersJoin struct {
	ControllerURL string            `yaml:"controller_url"`
	JoinToken     string            `yaml:"join_token"`
	JoinTokenFile string            `yaml:"join_token_file"`
	Name          string            `yaml:"name"`
	Labels        map[string]string `yaml:"labels"`
	CAFile        string            `yaml:"ca_file"`
}

// Load reads an answer file. Unknown keys are an error, not a shrug: a typo in
// an unattended install would otherwise leave a setting silently at its
// default and be found weeks later.
func Load(path string) (*Answers, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("installer: reading the answer file %s: %w (write one with `zoomies init --print-answers > %s`)", path, err, path)
	}
	var a Answers
	dec := yaml.NewDecoder(strings.NewReader(string(b)))
	dec.KnownFields(true)
	if err := dec.Decode(&a); err != nil && err != io.EOF {
		return nil, fmt.Errorf("installer: %s is not a valid answer file: %w", path, err)
	}
	a.path = path
	a.normalize()
	return &a, nil
}

// Path returns the file these answers were read from, for error messages.
func (a *Answers) Path() string {
	if a == nil {
		return ""
	}
	return a.path
}

func (a *Answers) normalize() {
	a.Mode = strings.ToLower(strings.TrimSpace(a.Mode))
	a.Deployment = strings.ToLower(strings.TrimSpace(a.Deployment))
	a.Backend = strings.ToLower(strings.TrimSpace(a.Backend))
	a.TLS.Mode = strings.ToLower(strings.TrimSpace(a.TLS.Mode))
	a.Service.Manager = strings.ToLower(strings.TrimSpace(a.Service.Manager))
	a.GitHub.TargetType = strings.ToLower(strings.TrimSpace(a.GitHub.TargetType))
	a.GitHub.Target = strings.TrimSpace(a.GitHub.Target)
	a.ExternalURL = strings.TrimRight(strings.TrimSpace(a.ExternalURL), "/")
	a.Agent.ControllerURL = strings.TrimRight(strings.TrimSpace(a.Agent.ControllerURL), "/")
	a.Admin.Username = strings.TrimSpace(a.Admin.Username)
	// "false" is what a YAML 1.1 parser makes of an unquoted "off", and an
	// operator who wrote that meant the TLS mode.
	if a.TLS.Mode == "false" {
		a.TLS.Mode = "off"
	}
}

// MissingAnswer names one answer a non-interactive run cannot invent, and says
// what it is for. Silently defaulting any of these would produce a controller
// that starts and then does not work.
type MissingAnswer struct {
	Key string
	Why string
}

func (m MissingAnswer) String() string { return m.Key + " -- " + m.Why }

// Missing lists the answers this file still needs for a given mode. A nil
// Answers is treated as an empty one, which is what a run with no answer file
// at all should report.
func (a *Answers) Missing(mode Mode) []MissingAnswer {
	if a == nil {
		a = &Answers{}
	}
	var out []MissingAnswer
	need := func(ok bool, key, why string) {
		if !ok {
			out = append(out, MissingAnswer{Key: key, Why: why})
		}
	}

	if mode == ModeAgent {
		need(a.Agent.ControllerURL != "", "agent.controller_url",
			"the controller this host joins, e.g. https://zoomies.example.com")
		need(a.Agent.JoinToken != "" || a.Agent.JoinTokenFile != "", "agent.join_token",
			"a join token from the UI under Hosts, or `zoomies hosts join-token create`")
		return out
	}

	need(a.ExternalURL != "", "external_url",
		"the URL GitHub and your browser reach this controller on; it forms the webhook URL")
	// A container's database lives in a volume the installer never opens, so
	// its first administrator is created in the browser rather than here.
	if !Deployment(a.Deployment).Containerised() {
		need(a.Admin.Username != "", "admin.username",
			"the first administrator's login name")
		need(a.Admin.Password != "" || a.Admin.PasswordFile != "", "admin.password",
			"the first administrator's password, or admin.password_file to keep it out of this file")
	}

	if !a.GitHub.Skip {
		need(a.GitHub.Target != "", "github.target",
			"the organisation, or owner/repo, whose runners this fleet manages")
		need(a.GitHub.AppID != 0, "github.app_id",
			"the GitHub App's ID; unattended setup cannot drive the browser handshake, so create the App first and paste its numbers here")
		need(a.GitHub.InstallationID != 0, "github.installation_id",
			"the installation ID from the App's installation page URL")
		need(a.GitHub.PrivateKeyFile != "", "github.private_key_file",
			"the path to the App's .pem private key, which Zoomies seals with the instance encryption key")
		need(a.GitHub.WebhookSecret != "" || a.GitHub.WebhookSecretFile != "", "github.webhook_secret",
			"the App's webhook secret; without it every delivery fails signature validation")
	}
	if a.TLS.Mode == "files" {
		need(a.TLS.CertFile != "", "tls.cert_file", "the certificate to serve")
		need(a.TLS.KeyFile != "", "tls.key_file", "the certificate's private key")
	}
	return out
}

// Validate returns an error naming every missing key, or nil.
func (a *Answers) Validate(mode Mode) error {
	missing := a.Missing(mode)
	if len(missing) == 0 {
		return nil
	}
	var b strings.Builder
	where := a.Path()
	if where == "" {
		where = "this run"
	}
	fmt.Fprintf(&b, "installer: %s cannot continue without these answers (%s):\n", where, mode)
	for _, m := range missing {
		fmt.Fprintf(&b, "  - %s: %s\n", m.Key, m.Why)
	}
	b.WriteString("write them with `zoomies init --print-answers > answers.yaml`, fill it in, and pass --answers answers.yaml")
	return fmt.Errorf("%s", b.String())
}

// AdminPassword resolves the administrator's password, preferring the file so
// that the secret need never be written into the answer file itself.
func (a *Answers) AdminPassword() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.Admin.PasswordFile != "" {
		b, err := os.ReadFile(a.Admin.PasswordFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading admin.password_file %s: %w", a.Admin.PasswordFile, err)
		}
		return strings.TrimRight(string(b), "\r\n"), nil
	}
	return a.Admin.Password, nil
}

// WebhookSecret resolves the App's webhook secret from the file or the inline
// value.
func (a *Answers) WebhookSecret() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.GitHub.WebhookSecretFile != "" {
		b, err := os.ReadFile(a.GitHub.WebhookSecretFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading github.webhook_secret_file %s: %w", a.GitHub.WebhookSecretFile, err)
		}
		return strings.TrimSpace(string(b)), nil
	}
	return a.GitHub.WebhookSecret, nil
}

// PrivateKey reads the GitHub App's private key. The PEM is returned rather
// than kept, so the caller can seal it and let it go out of scope.
func (a *Answers) PrivateKey() (string, error) {
	if a == nil || a.GitHub.PrivateKeyFile == "" {
		return "", nil
	}
	b, err := os.ReadFile(a.GitHub.PrivateKeyFile)
	if err != nil {
		return "", fmt.Errorf("installer: reading github.private_key_file %s: %w (it is the .pem GitHub offered once, when the App was created)", a.GitHub.PrivateKeyFile, err)
	}
	if !strings.Contains(string(b), "PRIVATE KEY") {
		return "", fmt.Errorf("installer: %s does not look like a PEM private key; download a new one from the App's settings page", a.GitHub.PrivateKeyFile)
	}
	return string(b), nil
}

// JoinToken resolves the join token for `zoomies agent join`.
func (a *Answers) JoinToken() (string, error) {
	if a == nil {
		return "", nil
	}
	if a.Agent.JoinTokenFile != "" {
		b, err := os.ReadFile(a.Agent.JoinTokenFile)
		if err != nil {
			return "", fmt.Errorf("installer: reading agent.join_token_file %s: %w", a.Agent.JoinTokenFile, err)
		}
		return strings.TrimSpace(string(b)), nil
	}
	return strings.TrimSpace(a.Agent.JoinToken), nil
}

// exampleAnswers is what `zoomies init --print-answers` emits. It is a
// commented template rather than a dump of defaults, because the person
// filling it in is deciding, not reviewing.
const exampleAnswers = `# zoomies answer file
#
#   zoomies init --non-interactive --answers answers.yaml
#
# Every key here is one question the interactive installer would ask. Anything
# left out keeps the detected or default value, except the keys marked
# REQUIRED: an unattended run refuses to guess those rather than build a
# controller that starts and then does not work.

# single     -- controller with an embedded agent, one process on one VM
# controller -- controller only; runner hosts join it separately
# agent      -- this host only runs runners
mode: single

# How this host runs Zoomies. Orthogonal to mode: any of them can be
# containerised.
#
# native   -- the binary under systemd or launchd. Leanest, starts fastest,
#             and needs no container runtime for the controller itself.
# compose  -- a docker-compose.yml and a fully populated .env, brought up with
#             "docker compose up -d". Easiest to upgrade and to move.
# docker   -- a single container from an env file. Fewest files, but you own
#             the run command.
#
# Omitted, it takes compose when this host has a compose command and native
# otherwise. A compose or docker deployment creates its first administrator in
# the browser, so admin.username and admin.password below are then unused.
deployment: compose
# Where docker-compose.yml and the .env are written. Defaults to config_dir.
# deployment_dir: /etc/zoomies
# The image those deployments run. Pin a release tag to choose when to upgrade.
# image: ghcr.io/eyupio/zoomies:latest

# The unprivileged account the service runs as. Created when init runs as root.
service_user: zoomies
# config_dir: /etc/zoomies
# state_dir: /var/lib/zoomies

# docker | podman | process
# Rootless docker or podman is strongly preferred: a container escape from a
# job then lands on an unprivileged account rather than on root. The process
# backend gives jobs no isolation at all -- they run directly on this host.
backend: docker
# docker_host: unix:///run/user/1000/docker.sock
# The most runners this host may hold at once.
capacity: 4

# Where the controller listens. Loopback is the safe default; reach it through
# a reverse proxy or an SSH tunnel. Use 0.0.0.0:8080 only with a proxy in front
# or with TLS configured below.
bind: 127.0.0.1:8080

tls:
  # "off" (quote it -- an unquoted off is a boolean in YAML), "files" or
  # "self-signed". GitHub will not deliver webhooks to a self-signed
  # certificate, so use "files" or terminate TLS in a proxy.
  mode: "off"
  # cert_file: /etc/zoomies/tls/fullchain.pem
  # key_file: /etc/zoomies/tls/privkey.pem
  # hosts: [zoomies.example.com]

# CIDRs whose X-Forwarded-For header is believed. Set this when a proxy
# terminates TLS, or every audit entry records the proxy's address. The word
# cloudflare stands for Cloudflare's published ranges.
# trusted_proxies: [10.0.0.0/8]

# REQUIRED. How GitHub and your browser reach this controller. Webhook
# deliveries go to $external_url/webhooks/github.
external_url: https://zoomies.example.com

github:
  # https://api.github.com, or https://ghes.example.com/api/v3 for Enterprise.
  api_base_url: https://api.github.com
  # REQUIRED unless skip is true. An organisation login, or "owner/repo".
  target: acme
  # org | repo. Derived from target when omitted.
  target_type: org
  # REQUIRED unless skip is true. An unattended run cannot drive the browser
  # handshake that creates the App, so create it first -- interactively, once --
  # and paste its numbers here.
  app_id: 0
  installation_id: 0
  private_key_file: /etc/zoomies/github-app.private-key.pem
  # Prefer the file: an answer file often ends up in a repository.
  # webhook_secret_file: /etc/zoomies/webhook.secret
  webhook_secret: ""
  # Set skip to true to finish setup now and connect GitHub later in the UI.
  skip: false

admin:
  # REQUIRED. The first administrator.
  username: admin
  # REQUIRED (or password_file). At least 12 characters.
  password: ""
  # password_file: /run/secrets/zoomies-admin-password

# The first pool, created on a single-host install once GitHub is connected.
# Without one the fleet has a host and nothing to place on it, so every key
# here is optional and the defaults come from what this host actually is.
pool:
  # Set skip to true to finish setup with no pool and create one yourself.
  skip: false
  # Defaults to this host's OS and architecture, e.g. zoomies-linux-x64 (and
  # zoomies-linux-x64-host for the process backend, which gives jobs no
  # container). A name given without the zoomies- prefix is stored with one.
  # name: zoomies-linux-x64
  # What a workflow's runs-on has to ask for. Defaults to the pool's name.
  # labels: [linux-x64]
  # Defaults to capacity above. Always set a maximum somewhere: it is the only
  # backstop against a runaway workflow.
  # max_runners: 4

# Only for deployment: native.
service:
  # systemd | launchd | compose | none. Detected when omitted.
  manager: systemd
  enable: true
  start: true

# Only for mode: agent.
agent:
  # REQUIRED for mode: agent.
  controller_url: https://zoomies.example.com
  # REQUIRED for mode: agent. Mint one with:
  #   zoomies hosts join-token create --ttl 15m
  join_token: ""
  # join_token_file: /run/secrets/zoomies-join-token
  # name: build-box-3
  # labels: {zone: eu-west-1a}
  # ca_file: /etc/zoomies/controller-ca.pem
`

// WriteExample emits a commented answer-file template, which is what
// `zoomies init --print-answers` prints.
func WriteExample(w io.Writer) error {
	if _, err := io.WriteString(w, exampleAnswers); err != nil {
		return fmt.Errorf("installer: writing the answer template: %w", err)
	}
	return nil
}

package installer

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeFile(t *testing.T, dir, name, body string) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing %s: %v", path, err)
	}
	return path
}

func TestLoadAnswers(t *testing.T) {
	dir := t.TempDir()
	path := writeFile(t, dir, "answers.yaml", `
mode: controller
backend: podman
capacity: 6
bind: 0.0.0.0:8443
tls:
  mode: files
  cert_file: /etc/zoomies/tls/cert.pem
  key_file: /etc/zoomies/tls/key.pem
trusted_proxies: [10.0.0.0/8]
external_url: https://zoomies.example.com/
github:
  target: acme
  app_id: 42
  installation_id: 99
  private_key_file: /etc/zoomies/app.pem
  webhook_secret: shhh
admin:
  username: ada
  password: correct-horse-battery
service:
  manager: systemd
  start: false
`)

	a, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if a.Mode != "controller" || a.Backend != "podman" || a.Capacity != 6 {
		t.Fatalf("basic fields not decoded: %+v", a)
	}
	if a.ExternalURL != "https://zoomies.example.com" {
		t.Fatalf("external URL not normalised: %q", a.ExternalURL)
	}
	if a.TLS.Mode != "files" || a.TLS.CertFile == "" {
		t.Fatalf("tls block not decoded: %+v", a.TLS)
	}
	if a.Service.Start == nil || *a.Service.Start {
		t.Fatalf("service.start should decode as an explicit false, got %v", a.Service.Start)
	}
	if a.Service.Enable != nil {
		t.Fatalf("service.enable was not in the file, so it must stay nil rather than default to false")
	}
	if got := a.Path(); got != path {
		t.Fatalf("Path() = %q, want %q", got, path)
	}
}

