// containsSuffix reports whether any entry ends with want, which is how a
// volume list is checked without pinning the order.
func containsSuffix(list []string, want string) bool {
	for _, v := range list {
		if strings.HasSuffix(v, want) {
			return true
		}
	}
	return false
}

// `zoomies healthcheck` exists to be a container's HEALTHCHECK, and the
// compose files use it. The image declared none, so a `docker run`
// deployment -- the third of the three the installer offers -- had no health
// state at all: a wedged controller kept a running container and nothing said
// otherwise.
func TestTheImageDeclaresTheHealthcheckADockerRunInherits(t *testing.T) {
	body, err := os.ReadFile(filepath.Join("..", "..", "deploy", "Dockerfile"))
	if err != nil {
		t.Fatalf("reading deploy/Dockerfile: %v", err)
	}
	text := string(body)
	i := strings.Index(text, "HEALTHCHECK")
	if i < 0 {
		t.Fatal("the controller image declares no HEALTHCHECK")
	}
	instruction := text[i:]
	if j := strings.Index(instruction, "\nENTRYPOINT"); j >= 0 {
		instruction = instruction[:j]
	}
	// Exec form, or a distroless image cannot run it at all.
	if !strings.Contains(instruction, `CMD ["/usr/local/bin/zoomies", "healthcheck"`) {
		t.Fatalf("the HEALTHCHECK is not the exec form of `zoomies healthcheck`:\n%s", instruction)
	}
	if want := fmt.Sprintf("http://127.0.0.1:%d", ContainerPort); !strings.Contains(instruction, want) {
		t.Errorf("the HEALTHCHECK does not probe %s:\n%s", want, instruction)
	}
}

// The agent image is derived from the controller image rather than asked
// about, and the three references it must refuse are each a reference that
// would look plausible and pull nothing.
func TestAgentImageForFollowsTheControllerImage(t *testing.T) {
	const digest = "@sha256:8c2f1a9e5b3d4c6a7e8f0b1d2c3a4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f"
	for _, tc := range []struct {
		name       string
		controller string
		want       string
		ok         bool
	}{
		{"a release tag is the whole point", "ghcr.io/eyupio/zoomies:v1.2.3", "ghcr.io/eyupio/zoomies-agent:v1.2.3", true},
		{"the tip of main", "ghcr.io/eyupio/zoomies:dev", "ghcr.io/eyupio/zoomies-agent:dev", true},
		{"the newest release", "ghcr.io/eyupio/zoomies:latest", "ghcr.io/eyupio/zoomies-agent:latest", true},
		{"a commit tag", "ghcr.io/eyupio/zoomies:sha-b966fb6", "ghcr.io/eyupio/zoomies-agent:sha-b966fb6", true},
		{"no tag at all", "ghcr.io/eyupio/zoomies", "ghcr.io/eyupio/zoomies-agent", true},

		// A digest names one set of bytes and there is no arithmetic that
		// turns the controller's into the agent's. Carrying it across would
		// name an image that does not exist.
		{"a digest cannot be translated", "ghcr.io/eyupio/zoomies" + digest, "", false},
		{"a tag and a digest", "ghcr.io/eyupio/zoomies:v1.2.3" + digest, "", false},

		// Whether somebody else's registry carries an -agent counterpart is
		// not knowable from the name.
		{"a mirror", "registry.example.com/mirror/zoomies:v1.2.3", "", false},
		{"a mirror on a port", "registry.example.com:5000/zoomies:v1.2.3", "", false},
		{"an operator's own build", "zoomies:local", "", false},

		// The repository is compared whole. A prefix test would rewrite the
		// runner image, which is a different image entirely.
		{"a repository that merely starts the same way", "ghcr.io/eyupio/zoomies-runner:latest", "", false},
		{"the agent image itself is not doubled", "ghcr.io/eyupio/zoomies-agent:v1.2.3", "", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, ok := AgentImageFor(tc.controller)
			if ok != tc.ok {
				t.Fatalf("AgentImageFor(%q) derived = %v, want %v", tc.controller, ok, tc.ok)
			}
			if got != tc.want {
				t.Errorf("AgentImageFor(%q) = %q, want %q", tc.controller, got, tc.want)
			}
		})
	}
}

// containerise is the one place a plan's image is settled, so it is the one
// place the agent image has to appear.
func TestContainerisingARunnerHostGivesItTheAgentImage(t *testing.T) {
	got := containerise(Plan{Deployment: DeploymentCompose, Mode: ModeAgent, Bind: "127.0.0.1:8080", Image: "ghcr.io/eyupio/zoomies:v1.2.3"})
	if want := "ghcr.io/eyupio/zoomies-agent:v1.2.3"; got.Image != want {
		t.Errorf("image = %q, want %q", got.Image, want)
	}

	// A controller keeps the controller image, which is the half that would
	// break loudly if the swap were made on mode rather than for it.
	ctl := containerise(Plan{Deployment: DeploymentCompose, Mode: ModeSingle, Bind: "127.0.0.1:8080", Image: "ghcr.io/eyupio/zoomies:v1.2.3"})
	if want := "ghcr.io/eyupio/zoomies:v1.2.3"; ctl.Image != want {
		t.Errorf("controller image = %q, want %q", ctl.Image, want)
	}

	// A pin is a pin. An operator who named a digest gets the bytes they named,
	// and the compose file's command override is what makes it an agent.
	const digest = "@sha256:8c2f1a9e5b3d4c6a7e8f0b1d2c3a4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f"
	pinned := containerise(Plan{Deployment: DeploymentCompose, Mode: ModeAgent, Bind: "127.0.0.1:8080", Image: "ghcr.io/eyupio/zoomies" + digest})
	if want := "ghcr.io/eyupio/zoomies" + digest; pinned.Image != want {
		t.Errorf("pinned image = %q, want %q", pinned.Image, want)
	}
}

// The default image names this build, because :latest names nothing useful.
//
// Every release this project has made carries a hyphen, which is how it says
// the release is not finished, and the release workflow leaves :latest alone
// for one. main stopped publishing it when :dev took over. So an installer
// defaulting to :latest would write a compose file pulling a controller older
// than the installer that wrote it -- and, once the agent image is derived from
// it, a runner host pulling a tag that has never been published at all.
func TestTheDefaultImageFollowsThisBuild(t *testing.T) {
	for _, tc := range []struct{ name, version, want string }{
		// The release workflow stamps the version with the leading v stripped,
		// because a binary reports 1.2.3; the image tag is the git tag, which
		// keeps it. Getting that backwards names a tag no registry has.
		{"a release", "1.2.3", "ghcr.io/eyupio/zoomies:v1.2.3"},
		{"a release candidate", "1.0.0-RC1", "ghcr.io/eyupio/zoomies:v1.0.0-RC1"},
		{"a release that kept its v", "v0.2-beta", "ghcr.io/eyupio/zoomies:v0.2-beta"},

		// Anything that is not a release gets the tag main publishes.
		{"a build from main", "main-sha-b966fb6", "ghcr.io/eyupio/zoomies:dev"},
		{"an unstamped build", "dev", "ghcr.io/eyupio/zoomies:dev"},
		{"a describe from a working tree", "v1.2.3-14-gb966fb6", "ghcr.io/eyupio/zoomies:dev"},
		{"nothing at all", "", "ghcr.io/eyupio/zoomies:dev"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := defaultImageFor(tc.version); got != tc.want {
				t.Errorf("defaultImageFor(%q) = %q, want %q", tc.version, got, tc.want)
			}
		})
	}

	// And the pair composes: a runner host on a release gets the agent image of
	// that release, which is the whole reason the default stopped being a
	// constant.
	agent, ok := AgentImageFor(defaultImageFor("1.0.0-RC1"))
	if !ok || agent != "ghcr.io/eyupio/zoomies-agent:v1.0.0-RC1" {
		t.Errorf("a runner host on a release candidate gets %q (derived %v), want ghcr.io/eyupio/zoomies-agent:v1.0.0-RC1", agent, ok)
	}
	if agent, ok := AgentImageFor(defaultImageFor("main-sha-b966fb6")); !ok || agent != "ghcr.io/eyupio/zoomies-agent:dev" {
		t.Errorf("a runner host on a main build gets %q (derived %v), want ghcr.io/eyupio/zoomies-agent:dev", agent, ok)
	}
}

// ---------------------------------------------------------------------------
// What the operator is handed
// ---------------------------------------------------------------------------
//
// These four are the strings a containerised install prints, polls or pastes.
// None of them had a test, and each is the kind of thing that is wrong in
// exactly one deployment shape -- the shape whose operator then has a health
// check that never passes, or a logs command that names nothing.

// The health check must follow the scheme the controller was configured to
// serve. Polling http:// against a controller serving TLS is a health check
// that never passes and an install that reports failure after succeeding.
func TestContainerHealthURLFollowsTheSchemeTheControllerServes(t *testing.T) {
	for _, tc := range []struct {
		mode config.TLSMode
		want string
	}{
		{config.TLSOff, "http://127.0.0.1:8443/healthz"},
		{config.TLSSelfSigned, "https://127.0.0.1:8443/healthz"},
		{config.TLSFiles, "https://127.0.0.1:8443/healthz"},
	} {
		p := Plan{TLSMode: tc.mode, PublishedPort: 8443}
		if got := containerHealthURL(p); got != tc.want {
			t.Errorf("containerHealthURL(%q) = %q, want %q", tc.mode, got, tc.want)
		}
	}
}

// The two container deployments read different environment files, and the
// names are not interchangeable: compose finds `.env` beside the file on its
// own, while `docker run --env-file` is handed a name that has to be the one
// that was written.
func TestEnvFileForNamesTheFileTheDeploymentActuallyReads(t *testing.T) {
	if got := EnvFileFor(DeploymentCompose); got != EnvFileName {
		t.Errorf("EnvFileFor(compose) = %q, want %q", got, EnvFileName)
	}
	if got := EnvFileFor(DeploymentDocker); got != DockerEnvFileName {
		t.Errorf("EnvFileFor(docker) = %q, want %q", got, DockerEnvFileName)
	}
	// A native install has no container to hand a file to; the compose name is
	// the harmless answer, and the point is that it is never the docker one.
	if got := EnvFileFor(DeploymentNative); got == DockerEnvFileName {
		t.Errorf("EnvFileFor(native) = %q, which belongs to the single-container deployment", got)
	}
}

// DockerCommandLine renders an argv as something the operator can paste, so
// the `docker` at the front is part of it.
func TestDockerCommandLineIsPastable(t *testing.T) {
	got := DockerCommandLine([]string{"run", "-d", "--name", ContainerName})
	if want := "docker run -d --name zoomies"; got != want {
		t.Errorf("DockerCommandLine = %q, want %q", got, want)
	}
}

// The logs command has to name the thing that actually holds the logs: the
// compose project through its own file, or the container by name.
func TestLogsCommandNamesWhicheverHoldsTheLogs(t *testing.T) {
	i := &Installer{}

	dir := t.TempDir()
	compose := i.logsCommand(Plan{
		Deployment:     DeploymentCompose,
		DeployDir:      dir,
		ComposeCommand: []string{"docker", "compose"},
	})
	if !strings.Contains(compose, filepath.Join(dir, ComposeFileName)) {
		t.Errorf("compose logs command %q does not name the compose file, so it only works from one directory", compose)
	}
	for _, want := range []string{"docker compose", "logs", "-f"} {
		if !strings.Contains(compose, want) {
			t.Errorf("compose logs command %q is missing %q", compose, want)
		}
	}

	if got, want := i.logsCommand(Plan{Deployment: DeploymentDocker}), "docker logs -f "+ContainerName; got != want {
		t.Errorf("docker logs command = %q, want %q", got, want)
	}
}

package installer

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Deployment is how Zoomies is run on this host, which is a separate question
// from Mode.
//
// Mode says what this host is -- a controller, an agent, or both in one
// process. Deployment says what supervises it. The two are orthogonal: an
// agent can be a binary under systemd or a container, and a single-host
// controller can be either as well. Keeping them apart is what stops the
// installer growing a matrix of nine special cases.
type Deployment string

const (
	// DeploymentNative runs the binary directly, supervised by systemd or
	// launchd. It is the leanest option and the only one that needs no
	// container runtime for the controller itself.
	DeploymentNative Deployment = "native"
	// DeploymentCompose writes a docker-compose.yml and a fully populated
	// .env, then brings them up. It is the easiest to upgrade and to move to
	// another host, because the whole deployment is two files.
	DeploymentCompose Deployment = "compose"
	// DeploymentDocker runs a single container from an env file. Fewest files,
	// but the operator owns the run command from then on.
	DeploymentDocker Deployment = "docker"
)

// ParseDeployment validates a --deployment value, naming the alternatives when
// it is not one of them. An empty string means "ask", the same as ParseMode.
func ParseDeployment(s string) (Deployment, error) {
	switch Deployment(strings.ToLower(strings.TrimSpace(s))) {
	case DeploymentNative:
		return DeploymentNative, nil
	case DeploymentCompose:
		return DeploymentCompose, nil
	case DeploymentDocker:
		return DeploymentDocker, nil
	case "":
		return "", nil
	default:
		return "", fmt.Errorf("installer: %q is not a deployment; use native (the binary under systemd or launchd), "+
			"compose (a docker-compose.yml and a .env) or docker (a single container)", s)
	}
}

// Containerised reports whether this deployment runs Zoomies inside a
// container, which is the difference that decides where its database lives and
// which questions setup still has to ask.
func (d Deployment) Containerised() bool {
	return d == DeploymentCompose || d == DeploymentDocker
}

// DeploymentOption is one deployment the prompt offers: what the operator
// gets, and what it costs them.
type DeploymentOption struct {
	Deployment  Deployment
	Label       string
	Description string
	// Default marks the one chosen when the operator just presses Enter.
	Default bool
}

// DeploymentOptions returns the deployments this host can actually carry out,
// best-understood first.
//
// Only workable choices are offered: compose needs a compose command that
// answered, docker needs a socket this user can talk to, and native always
// works because a binary and a supervisor are always available -- even if the
// supervisor turns out to be the operator.
func DeploymentOptions(d Detection) []DeploymentOption {
	def := DefaultDeployment(d)
	// The containerised options change the shape of the rest of setup, not
	// only where the process lives: the database is in a volume this installer
	// cannot open, so the administrator, the GitHub App and the first pool are
	// all done in the browser afterwards. Saying so here is the difference
	// between choosing that and discovering it.
	const deferred = " The administrator, the GitHub App and the first pool are then set up in the browser, not here."
	out := []DeploymentOption{{
		Deployment: DeploymentNative,
		Label:      "Native -- " + nativeSupervisor(d),
		Description: "Leanest, starts fastest, and needs no container runtime for the controller itself. " +
			"Setup finishes everything here, including your first pool.",
	}}
	if d.Compose.Available {
		out = append(out, DeploymentOption{
			Deployment: DeploymentCompose,
			Label:      "Compose -- docker-compose.yml and .env in " + d.ConfigDir,
			Description: "Writes both, then brings them up with `" + d.Compose.String() +
				" up -d`. Easiest to upgrade and to move to another host." + deferred,
		})
	}
	if d.Docker.Available {
		out = append(out, DeploymentOption{
			Deployment:  DeploymentDocker,
			Label:       "Docker -- a single container",
			Description: "Fewest files: an env file and one container. You manage the run command yourself." + deferred,
		})
	}
	for n := range out {
		if out[n].Deployment == def {
			out[n].Default = true
			out[n].Label += " (default)"
		}
	}
	return out
}

// nativeSupervisor describes what would keep a native install running, so that
// the option does not promise a systemd unit on a host with no systemd.
func nativeSupervisor(d Detection) string {
	switch {
	case d.HasSystemd:
		return "the binary under systemd"
	case d.HasLaunchd:
		return "the binary under launchd"
	default:
		return "the binary, started by you"
	}
}

// DefaultDeployment is what the operator gets by pressing Enter, and what a
// non-interactive run takes when the answer file is silent.
//
// Compose wins whenever a compose command exists: an operator who has gone to
// the trouble of installing Compose almost certainly wants their services in
// it, and a compose deployment is the one that upgrades and moves cleanly.
func DefaultDeployment(d Detection) Deployment {
	if d.Compose.Available {
		return DeploymentCompose
	}
	return DeploymentNative
}

// DeploymentAvailable reports whether this host can carry out a deployment,
// which is what turns a --deployment flag into an error the operator can fix
// rather than a failure half-way through setup.
func DeploymentAvailable(d Detection, want Deployment) bool {
	switch want {
	case DeploymentCompose:
		return d.Compose.Available
	case DeploymentDocker:
		return d.Docker.Available
	default:
		return true
	}
}

// UnavailableDeployment explains why a deployment cannot be used here and what
// to do about it. It returns an empty string when the deployment is fine.
func UnavailableDeployment(d Detection, want Deployment) string {
	if DeploymentAvailable(d, want) {
		return ""
	}
	switch want {
	case DeploymentCompose:
		detail := "no compose command answered on this host"
		if d.Compose.Detail != "" {
			detail = d.Compose.Detail
		}
		return "installer: --deployment compose was asked for, but " + detail +
			". Install the Compose plugin (`docker compose version` must work), or use --deployment native."
	case DeploymentDocker:
		detail := "no Docker socket answered here"
		if d.Docker.Detail != "" {
			detail = firstLine(d.Docker.Detail)
		}
		return "installer: --deployment docker was asked for, but " + detail +
			". Fix that, or use --deployment native."
	default:
		return ""
	}
}

// ---------------------------------------------------------------------------
// The record
// ---------------------------------------------------------------------------

// deploymentRecordFile is the name of the record inside the config directory.
const deploymentRecordFile = "deployment.json"

// DeploymentRecord is what `zoomies init` leaves behind so that
// `zoomies uninstall` can take the same deployment down again.
//
// Without it, uninstall would have to guess: it would stop a systemd unit that
// was never installed and leave a container running that the operator believes
// is gone. Everything needed to tear the deployment down is written here, in
// the words it was created with -- including which compose command was used,
// because a host can have either.
type DeploymentRecord struct {
	Deployment Deployment `json:"deployment"`
	// Directory holds docker-compose.yml and the env file.
	Directory string `json:"directory"`
	// ComposeCommand is the argv prefix, e.g. ["docker","compose"].
	ComposeCommand []string `json:"compose_command,omitempty"`
	// Container, Image, Volume and Network name what a docker deployment
	// created, so that removing it does not depend on this code's defaults
	// still being what they were on the day it was installed.
	Container string `json:"container,omitempty"`
	Image     string `json:"image,omitempty"`
	Volume    string `json:"volume,omitempty"`
	Network   string `json:"network,omitempty"`
	EnvFile   string `json:"env_file,omitempty"`
	Mode      Mode   `json:"mode,omitempty"`
	CreatedAt string `json:"created_at,omitempty"`
}

// ComposeFile is the compose file this record's deployment was brought up
// with.
func (r DeploymentRecord) ComposeFile() string {
	if r.Directory == "" {
		return ""
	}
	return filepath.Join(r.Directory, ComposeFileName)
}

// WriteDeploymentRecord saves the record beside the configuration. It is
// written atomically at 0640 so that an interrupted install never leaves
// uninstall reading half a JSON document.
func WriteDeploymentRecord(configDir string, r DeploymentRecord) (string, error) {
	if r.CreatedAt == "" {
		r.CreatedAt = time.Now().UTC().Format(time.RFC3339)
	}
	b, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return "", fmt.Errorf("installer: recording the deployment: %w", err)
	}
	path := filepath.Join(configDir, deploymentRecordFile)
	if err := writeFileAtomic(path, append(b, '\n'), 0o640); err != nil {
		return "", fmt.Errorf("installer: writing %s: %w", path, err)
	}
	return path, nil
}

// ReadDeploymentRecord reads the record back. A missing or unreadable record
// is not an error: it means this host was installed natively, or by a version
// of Zoomies that predates the record, and the caller falls back to looking
// for a unit file.
func ReadDeploymentRecord(configDir string) (DeploymentRecord, bool) {
	b, err := os.ReadFile(filepath.Join(configDir, deploymentRecordFile))
	if err != nil {
		return DeploymentRecord{}, false
	}
	var r DeploymentRecord
	if err := json.Unmarshal(b, &r); err != nil {
		return DeploymentRecord{}, false
	}
	if r.Deployment == "" {
		return DeploymentRecord{}, false
	}
	return r, true
}

// DeploymentRecordPath is where the record for a config directory lives, which
// uninstall needs so it can remove it along with everything else.
func DeploymentRecordPath(configDir string) string {
	return filepath.Join(configDir, deploymentRecordFile)
}

package installer

import (
	"bytes"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// hostWith builds the detection the deployment question actually reads, so
// that "what does this host offer" can be asked without a host.
func hostWith(compose, docker bool) Detection {
	d := Detection{ConfigDir: "/etc/zoomies", HasSystemd: true}
	if compose {
		d.Compose = ComposeInfo{Command: []string{"docker", "compose"}, Available: true}
		d.HasCompose = true
	} else {
		d.Compose = ComposeInfo{Detail: "neither `docker compose` nor `docker-compose` answered here"}
	}
	if docker {
		d.Docker = RuntimeInfo{Kind: store.BackendDocker, Available: true, Installed: true,
			Endpoint: "unix:///var/run/docker.sock"}
	} else {
		d.Docker = RuntimeInfo{Kind: store.BackendDocker, Detail: "the Docker socket is not reachable"}
	}
	return d
}

func deploymentsOffered(d Detection) []Deployment {
	var out []Deployment
	for _, o := range DeploymentOptions(d) {
		out = append(out, o.Deployment)
	}
	return out
}

func TestDeploymentOptionsOfferOnlyWhatTheHostCanDo(t *testing.T) {
	cases := []struct {
		name            string
		compose, docker bool
		want            []Deployment
		wantDefault     Deployment
	}{
		{"a host with compose and docker", true, true,
			[]Deployment{DeploymentNative, DeploymentCompose, DeploymentDocker}, DeploymentCompose},
		{"docker without the compose plugin", false, true,
			[]Deployment{DeploymentNative, DeploymentDocker}, DeploymentNative},
		{"no container runtime at all", false, false,
			[]Deployment{DeploymentNative}, DeploymentNative},
		{"compose answering but the socket refusing us", true, false,
			[]Deployment{DeploymentNative, DeploymentCompose}, DeploymentCompose},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			det := hostWith(tc.compose, tc.docker)
			got := deploymentsOffered(det)
			if len(got) != len(tc.want) {
				t.Fatalf("offered %v, want %v", got, tc.want)
			}
			for n := range got {
				if got[n] != tc.want[n] {
					t.Fatalf("offered %v, want %v", got, tc.want)
				}
			}
			if def := DefaultDeployment(det); def != tc.wantDefault {
				t.Errorf("default = %q, want %q", def, tc.wantDefault)
			}

			// Every option must say what choosing it costs, and exactly one
			// must be marked as the default.
			defaults := 0
			for _, o := range DeploymentOptions(det) {
				if o.Description == "" {
					t.Errorf("%s is offered with no consequence stated", o.Deployment)
				}
				if o.Default {
					defaults++
					if o.Deployment != tc.wantDefault {
						t.Errorf("%s is marked default, want %s", o.Deployment, tc.wantDefault)
					}
					if !strings.Contains(o.Label, "(default)") {
						t.Errorf("the default must say so in its label, got %q", o.Label)
					}
				}
			}
			if defaults != 1 {
				t.Errorf("exactly one option is the default, got %d", defaults)
			}
		})
	}
}

func TestNativeOptionNamesTheSupervisorThisHostHas(t *testing.T) {
	systemd := DeploymentOptions(hostWith(false, false))[0]
	if !strings.Contains(systemd.Label, "systemd") {
		t.Errorf("a systemd host should be told about systemd, got %q", systemd.Label)
	}

	bare := hostWith(false, false)
	bare.HasSystemd = false
	if label := DeploymentOptions(bare)[0].Label; strings.Contains(label, "systemd") {
		t.Errorf("a host with no systemd must not be promised a unit, got %q", label)
	}
}

func TestDeploymentAvailabilityExplainsItself(t *testing.T) {
	det := hostWith(false, false)
	for _, want := range []Deployment{DeploymentCompose, DeploymentDocker} {
		if DeploymentAvailable(det, want) {
			t.Errorf("%s is not available on this host", want)
		}
		why := UnavailableDeployment(det, want)
		if why == "" {
			t.Fatalf("%s must be refused with a reason", want)
		}
		if !strings.Contains(why, "--deployment native") {
			t.Errorf("the refusal must offer a way forward, got %q", why)
		}
	}
	if !DeploymentAvailable(det, DeploymentNative) {
		t.Error("native always works; it is the one that needs nothing installed")
	}
	if why := UnavailableDeployment(det, DeploymentNative); why != "" {
		t.Errorf("native needs no excuse, got %q", why)
	}
}

func TestDefaultDeploymentReasonIsSpecific(t *testing.T) {
	with := defaultDeploymentReason(hostWith(true, true))
	if !strings.Contains(with, "docker compose") {
		t.Errorf("the reason should name the command that answered, got %q", with)
	}
	without := defaultDeploymentReason(hostWith(false, false))
	if !strings.Contains(without, "no compose command") {
		t.Errorf("the reason should say why native won, got %q", without)
	}
}

func TestDeploymentRecordRoundTrip(t *testing.T) {
	dir := t.TempDir()
	want := DeploymentRecord{
		Deployment:     DeploymentCompose,
		Directory:      dir,
		ComposeCommand: []string{"docker-compose"},
		Container:      "zoomies",
		Image:          "ghcr.io/eyupio/zoomies:v1.2.3",
		Volume:         "zoomies-data",
		Network:        "zoomies",
		EnvFile:        filepath.Join(dir, ".env"),
		Mode:           ModeSingle,
	}

	path, err := WriteDeploymentRecord(dir, want)
	if err != nil {
		t.Fatalf("WriteDeploymentRecord: %v", err)
	}
	if path != DeploymentRecordPath(dir) {
		t.Fatalf("record written to %q, want %q", path, DeploymentRecordPath(dir))
	}

	got, ok := ReadDeploymentRecord(dir)
	if !ok {
		t.Fatal("the record just written was not read back")
	}
	if got.Deployment != want.Deployment || got.Directory != want.Directory ||
		strings.Join(got.ComposeCommand, " ") != "docker-compose" || got.Volume != want.Volume {
		t.Fatalf("record round-tripped as %+v", got)
	}
	if got.CreatedAt == "" {
		t.Error("the record should say when it was written")
	}
	if got.ComposeFile() != filepath.Join(dir, ComposeFileName) {
		t.Errorf("compose file = %q", got.ComposeFile())
	}
}

func TestReadDeploymentRecordIsQuietWhenThereIsNone(t *testing.T) {
	dir := t.TempDir()
	if _, ok := ReadDeploymentRecord(dir); ok {
		t.Fatal("an empty directory records no deployment")
	}
	// A native install, or one from a version that predates the record, must
	// not be mistaken for a container.
	writeFile(t, dir, deploymentRecordFile, "{ this is not json")
	if _, ok := ReadDeploymentRecord(dir); ok {
		t.Fatal("an unreadable record must be treated as no record, not as a container")
	}
	writeFile(t, dir, deploymentRecordFile, `{"directory":"/etc/zoomies"}`)
	if _, ok := ReadDeploymentRecord(dir); ok {
		t.Fatal("a record naming no deployment says nothing about how this host runs")
	}
}

func TestUninstallItemsIncludeAContainerDeployment(t *testing.T) {
	opts := uninstallOpts(t)
	env := writeFile(t, opts.ConfigDir, ".env", "ZOOMIES_ENCRYPTION_KEY=abc\n")
	if _, err := WriteDeploymentRecord(opts.ConfigDir, DeploymentRecord{
		Deployment:     DeploymentCompose,
		Directory:      opts.ConfigDir,
		ComposeCommand: []string{"docker", "compose"},
		Volume:         "zoomies-data",
		EnvFile:        env,
	}); err != nil {
		t.Fatal(err)
	}

	byWhat := map[string]RemovalItem{}
	for _, it := range UninstallItems(opts) {
		byWhat[it.What] = it
	}
	for _, what := range []string{"compose project", "environment file", "data volume", "deployment record"} {
		if _, ok := byWhat[what]; !ok {
			t.Errorf("%s is not listed, so an operator would be told Zoomies is gone while it is still running", what)
		}
	}
	if note := byWhat["data volume"].Note; !strings.Contains(note, "database") {
		t.Errorf("the volume's note must say it is the database, got %q", note)
	}
	if note := byWhat["environment file"].Note; !strings.Contains(note, "encryption key") {
		t.Errorf("the env file's note must say what is in it, got %q", note)
	}

	// A docker deployment is named by its container, because there is no file
	// to point at.
	if err := os.Remove(DeploymentRecordPath(opts.ConfigDir)); err != nil {
		t.Fatal(err)
	}
	if _, err := WriteDeploymentRecord(opts.ConfigDir, DeploymentRecord{
		Deployment: DeploymentDocker, Directory: opts.ConfigDir, Container: "zoomies",
	}); err != nil {
		t.Fatal(err)
	}
	found := false
	for _, it := range UninstallItems(opts) {
		if it.What == "container" && it.Path == "zoomies" {
			found = true
		}
	}
	if !found {
		t.Error("a docker deployment must be listed by the container it left running")
	}
}

// newTestInstaller builds an installer with a known host and no terminal, so
// that the unattended path can be exercised without one.
func newTestInstaller(t *testing.T, det Detection, opts Options) (*Installer, *bytes.Buffer) {
	t.Helper()
	out := &bytes.Buffer{}
	opts.Out = out
	opts.In = strings.NewReader("")
	opts.NonInteractive = true
	opts.Logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	i, err := New(opts)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	i.det = det
	return i, out
}

func TestResolveDeploymentTakesTheDefaultUnattendedAndSaysSo(t *testing.T) {
	det := hostWith(true, true)
	i, out := newTestInstaller(t, det, Options{})

	got, err := i.resolveDeployment(t.Context(), Plan{Deployment: DefaultDeployment(det)})
	if err != nil {
		t.Fatalf("resolveDeployment: %v", err)
	}
	if got.Deployment != DeploymentCompose {
		t.Fatalf("deployment = %q, want compose", got.Deployment)
	}
	// An operator reading the log later must be able to see what was chosen
	// for them, and why.
	body := out.String()
	for _, want := range []string{"compose", "docker compose", "--deployment"} {
		if !strings.Contains(body, want) {
			t.Errorf("the output must mention %q:\n%s", want, body)
		}
	}
}

func TestResolveDeploymentRefusesOneThisHostCannotDo(t *testing.T) {
	i, _ := newTestInstaller(t, hostWith(false, false), Options{Deployment: DeploymentCompose})

	_, err := i.resolveDeployment(t.Context(), Plan{})
	if err == nil {
		t.Fatal("a compose deployment on a host with no compose must be refused, not attempted")
	}
	if !strings.Contains(err.Error(), "compose") {
		t.Errorf("the error must name what is missing, got %q", err)
	}
}

func TestPlanMissingSkipsTheAdministratorForAContainer(t *testing.T) {
	p := testPlan(t)
	p.AdminUser, p.adminPassword = "", ""
	if len(p.Missing()) == 0 {
