package installer

import (
	"context"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// deploymentSettings is the configuration the deployment being upgraded runs
// with: its file, its database and its environment, layered as its controller
// layers them at start (config.Effective).
//
// The database is the point. Settings are kept there -- the settings page
// writes nowhere else -- so whether this host runs runners, on which backend
// and through which socket is a question for the deployment's database, and a
// file or .env read on its own answers it wrongly the moment an operator has
// used the page. The upgrade reads it read-only, which is safe beside the
// running controller for the same reason a backup is.
//
// read is false when the database could not be read, and why says what
// stood in the way; cfg is then what the file and environment say over the
// defaults, and the caller must treat anything the database could have
// changed as unknown rather than as that.
type deploymentSettings struct {
	cfg  *config.Config
	read bool
	why  string
	// cacheDirs are the host folders pools keep a size-limited cache in. The
	// agent keeps that limit by measuring the folder itself, so a container
	// deployment has to mount each one at its own path.
	cacheDirs []cacheDir
}

// cacheDir is one host folder pool caches live under, and the pools using it.
type cacheDir struct {
	path  string
	pools []string
}

// settings reads the deployment's configuration. It never fails the upgrade:
// the answer is used to decide what to offer, and an upgrade that cannot read
// it offers what a host that runs runners needs rather than nothing.
func (p *upgradePlan) settings(ctx context.Context) deploymentSettings {
	env := map[string]string{}
	file := ""
	var dbPath string
	switch p.record.Deployment {
	case DeploymentCompose, DeploymentDocker:
		// The container's environment is its .env; that is the layer the
		// controller in it reads last. DOCKER_GID and the like in there are
		// Compose's own, and config ignores what is not a setting.
		if p.record.EnvFile != "" {
			if parsed, err := ParseEnvFile(p.record.EnvFile); err == nil {
				env = parsed
			}
		}
		path, err := p.volumeDatabase(ctx)
		if err != nil {
			return p.unreadSettings(file, env, err.Error())
		}
		dbPath = path
	default:
		if candidate := filepath.Join(p.opts.ConfigDir, "zoomies.yaml"); exists(candidate) {
			file = candidate
		}
		base, _, err := config.Effective(file, nil, nil, nil)
		if err != nil {
			return p.unreadSettings("", env, err.Error())
		}
		dbPath = base.Database.Path
	}
	if !exists(dbPath) {
		// No database yet: nothing has been set on the settings page, so the
		// file and environment are the whole answer.
		cfg, _, err := config.Effective(file, nil, nil, env)
		if err != nil {
			return p.unreadSettings("", env, err.Error())
		}
		return deploymentSettings{cfg: cfg, read: true}
	}
	st, err := store.Open(ctx, store.Options{Path: dbPath, ReadOnly: true})
	if err != nil {
		return p.unreadSettings(file, env, fmt.Sprintf("opening %s: %v", dbPath, err))
	}
	defer func() { _ = st.Close() }()
	rows, err := st.InstanceSettings(ctx)
	if err != nil {
		return p.unreadSettings(file, env, fmt.Sprintf("reading the settings in %s: %v", dbPath, err))
	}
	// No key: nothing this reads is a secret, and a sealed row it cannot open
	// is a finding, not a failure.
	cfg, _, err := config.Effective(file, rows, nil, env)
	if err != nil {
		return p.unreadSettings(file, env, err.Error())
	}
	// A pool that cannot be listed costs only the cache mounts: the settings
	// above still decide everything else.
	pools, _ := st.ListPools(ctx)
	return deploymentSettings{cfg: cfg, read: true, cacheDirs: sizeLimitedCacheDirs(pools)}
}

// sizeLimitedCacheDirs is every absolute host folder a pool keeps a
// size-limited cache in, once each, in a stable order. A cache with no limit
// is left out: the host's daemon mounts it into runners on its own, and only
// enforcing a limit needs the agent to see inside it.
func sizeLimitedCacheDirs(pools []*store.Pool) []cacheDir {
	byPath := map[string]*cacheDir{}
	var order []string
	for _, pool := range pools {
		c := pool.Cache
		// A cache source is a path on the Linux host the runners run on,
		// whatever machine this upgrade happens to run from.
		source := strings.TrimSpace(c.Source)
		if !c.Enabled || c.SizeLimit <= 0 || !path.IsAbs(source) || strings.Contains(source, "..") {
			continue
		}
		dir := path.Clean(source)
		if byPath[dir] == nil {
			byPath[dir] = &cacheDir{path: dir}
			order = append(order, dir)
		}
		byPath[dir].pools = append(byPath[dir].pools, pool.Name)
	}
	sort.Strings(order)
	out := make([]cacheDir, 0, len(order))
	for _, dir := range order {
		out = append(out, *byPath[dir])
	}
	return out
}

func (p *upgradePlan) unreadSettings(file string, env map[string]string, why string) deploymentSettings {
	cfg, _, err := config.Effective(file, nil, nil, env)
	if err != nil {
		cfg = config.Default()
	}
	return deploymentSettings{cfg: cfg, why: why}
}

// volumeDatabase is the host path of the database in a container
// deployment's data volume. The running container is asked where its state
// directory is mounted from, rather than the volume by name: Compose prefixes
// a volume's name with its project unless the file names it, so the name the
// record holds is not always the name the daemon knows.
func (p *upgradePlan) volumeDatabase(ctx context.Context) (string, error) {
	container := containerOr(p.record)
	format := `{{range .Mounts}}{{if eq .Destination "` + ContainerStateDir + `"}}{{.Source}}{{end}}{{end}}`
	out, err := p.docker(ctx, "inspect", "--type", "container", "--format", format, container)
	if err != nil {
		return "", fmt.Errorf("asking the %s container where its data is: %w", container, err)
	}
	dir := strings.TrimSpace(out)
	if dir == "" {
		return "", fmt.Errorf("the %s container mounts nothing at %s", container, ContainerStateDir)
	}
	if _, err := os.Stat(dir); err != nil {
		// Docker Desktop keeps volumes inside its own VM, where this host
		// cannot open them.
		return "", fmt.Errorf("its data is at %s, which this host cannot open: %w", dir, err)
	}
	return filepath.Join(dir, filepath.Base(ContainerDBPath)), nil
}

// runsRunners is whether this host creates runners itself: an agent always
// does, a controller when its embedded agent is on. Unknown -- the database
// could not be read -- counts as yes, because a folder or a mount offered to a
// controller that does not need it costs a question, and one not offered to a
// controller that does breaks its runners' tool cache.
func (s deploymentSettings) runsRunners(mode Mode) bool {
	if mode == ModeAgent {
		return true
	}
	if !s.read {
		return true
	}
	return s.cfg.Agent.Embedded
}

package installer

import (
	"context"
	"fmt"
	"net"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/machine"
	"github.com/eyupio/zoomies/internal/naming"
	"github.com/eyupio/zoomies/internal/store"
)

// InitSystem names the supervisor this host uses, which decides whether the
// installer can offer to write a unit file or has to print a compose file
// instead.
type InitSystem string

const (
	// InitSystemd is the common case on Debian, Ubuntu and Fedora.
	InitSystemd InitSystem = "systemd"
	// InitLaunchd is macOS, where Zoomies is a development controller.
	InitLaunchd InitSystem = "launchd"
	// InitOpenRC is Alpine. Zoomies does not write OpenRC scripts in v1, so it
	// prints a compose file and says why.
	InitOpenRC InitSystem = "openrc"
	// InitNone covers containers and anything unrecognised.
	InitNone InitSystem = "none"
)

// RuntimeInfo is what one container runtime looks like from here, including
// whether this particular user could actually use it. The distinction matters:
// a Docker socket that exists but rejects us is a completely different problem
// from one that is not there, and it has a different remedy.
type RuntimeInfo struct {
	Kind store.BackendKind
	// Available means the daemon answered a version request.
	Available bool
	// Rootless means a container escape lands on an unprivileged account
	// rather than on root, which is why it is preferred everywhere.
	Rootless bool
	Endpoint string
	Version  string
	// Detail explains an unavailable runtime in words the operator can act on.
	Detail string
	// Installed means the CLI is on PATH even though the socket is not
	// reachable, which is the "start the service" case rather than the
	// "install it" case.
	Installed bool
	// Limits is whether the daemon can apply a CPU quota, a memory limit and
	// a pids limit, carried over from the probe so that setup can delegate the
	// cgroup controllers a rootless daemon is missing before it ever refuses a
	// runner, rather than waiting for host.limits_unenforceable at runtime.
	Limits store.LimitSupport
}

// ComposeInfo is the Docker Compose command this host can run.
//
// Compose v2 is a subcommand of docker; v1 was a separate docker-compose
// binary. Both are still in the field, so whichever answered is carried around
// as an argv prefix rather than re-derived at each call site -- which is how a
// host with only v1 ends up being told to run a v2 command it does not have.
type ComposeInfo struct {
	// Command is the argv prefix, e.g. ["docker","compose"].
	Command []string
	// Available means the command answered a version request. install.sh's
	// finding is trusted here without re-running it: the script asked this
	// same host moments ago.
	Available bool
	// Detail explains an absent compose in words the operator can act on.
	Detail string
}

// String renders the command the way an operator would type it.
func (c ComposeInfo) String() string { return strings.Join(c.Command, " ") }

// ParseComposeCommand turns install.sh's --detected-compose value into an argv
// prefix.
func ParseComposeCommand(s string) []string { return strings.Fields(s) }

// detectCompose settles which compose command this host has.
//
// install.sh already ran both probes before any privilege change, so its
// answer wins. The probing here is for `zoomies init` run on its own, and it
// asks in the same order the script does: the v2 plugin first, because a host
// with both should use the one that is still maintained.
func detectCompose(ctx context.Context, hint string) ComposeInfo {
	if cmd := ParseComposeCommand(hint); len(cmd) > 0 {
		return ComposeInfo{Command: cmd, Available: true}
	}
	ctx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()

	if lookPath("docker") != "" {
		if _, err := runCommand(ctx, "docker", "compose", "version"); err == nil {
			return ComposeInfo{Command: []string{"docker", "compose"}, Available: true}
		}
	}
	if lookPath("docker-compose") != "" {
		if _, err := runCommand(ctx, "docker-compose", "--version"); err == nil {
			return ComposeInfo{Command: []string{"docker-compose"}, Available: true}
		}
	}
	return ComposeInfo{Detail: "neither `docker compose` nor `docker-compose` answered here"}
}

// PortStatus records whether the installer could bind a port, so that the bind
// prompt can offer another one instead of failing at first start.
type PortStatus struct {
	Port int
	Free bool
	// Detail carries the bind error, which distinguishes "in use" from
	// "permission denied" on a privileged port.
	Detail string
}

// ExistingInstall lists the parts of a previous installation found on this
// host. Every field is either an existing path or empty, so the caller can
// print exactly what is there without stat-ing anything again.
type ExistingInstall struct {
	ConfigFile    string
	KeyFile       string
	Database      string
	Unit          string
	AgentUnit     string
	AgentState    string
	Binary        string
	BinaryVersion string
}

// Present reports whether anything of a previous install survives. It is the
// signal that `zoomies init` should offer an upgrade rather than a fresh
// install.
func (e ExistingInstall) Present() bool {
	return e.ConfigFile != "" || e.KeyFile != "" || e.Database != "" ||
		e.Unit != "" || e.AgentUnit != "" || e.AgentState != ""
}

// HasState reports whether an existing install holds data that would be
// destroyed by starting again: the encryption key and the database. Those two
// are the ones that need a typed confirmation rather than a yes/no.
func (e ExistingInstall) HasState() bool { return e.KeyFile != "" || e.Database != "" }

// Items lists what was found, one line each, for the confirmation screen.
func (e ExistingInstall) Items() []string {
	var out []string
	add := func(label, path string) {
		if path != "" {
			out = append(out, fmt.Sprintf("%-16s %s", label, path))
		}
	}
	add("config", e.ConfigFile)
	add("encryption key", e.KeyFile)
	add("database", e.Database)
	add("service", e.Unit)
	add("agent service", e.AgentUnit)
	add("agent creds", e.AgentState)
	if e.Binary != "" {
		v := e.BinaryVersion
		if v == "" {
			v = "unknown version"
		}
		out = append(out, fmt.Sprintf("%-16s %s (%s)", "binary", e.Binary, v))
	}
	return out
}

// Detection is everything the installer knows about this host before it asks
// the operator anything. Run prints it once, at the top, because half of
// setting up a fleet controller is finding out what the machine already has.
type Detection struct {
	OS     string
	Arch   string
	Distro string
	// OSVersion is the distribution's release, e.g. "24.04". With Distro it is
	// what a pool's platform is matched against, and what picks the runner
	// image variant this host can actually run.
	OSVersion string
	// CPUs and MemoryMB are how much machine this is. They size the first
	// pool's suggestion and name the host.
	CPUs     int
	MemoryMB int64
	Init     InitSystem
	Hostname string

	// User, UID and GID describe who is running the installer, which decides
	// whether a service user can be created at all.
	User string
	UID  int
	GID  int
	Root bool

	Docker RuntimeInfo
	Podman RuntimeInfo

	// HasSystemd, HasLaunchd and HasCompose say which supervisors this host
	// can actually run, so the installer never shells out to a binary that is
	// not there.
	HasSystemd bool
	HasLaunchd bool
	HasCompose bool
	// HasSCM is the Windows service manager, present on every Windows host
	// and nowhere else.
	HasSCM bool

	// Compose is the Docker Compose command this host has, which decides
	// whether a compose deployment can be offered at all.
	Compose ComposeInfo

	// Ports records the bind check for the ports setup would like to use.
	Ports []PortStatus

	Existing ExistingInstall

	// ConfigDir and StateDir are where this run will put things.
	ConfigDir string
	StateDir  string

	// Interactive is false when there is no terminal to prompt on, which
	// forces the non-interactive path.
	Interactive bool

	// BinaryPath is the zoomies binary the service unit will point at.
	BinaryPath string
}

// defaultPorts are the ports setup checks: the default listener and the
// privileged HTTPS port an operator may want instead.
var defaultPorts = []int{8080, 443}

// Detect works out everything install.sh could not tell us, and everything
// needed when `zoomies init` is run directly rather than through the script.
//
// Flags from install.sh always win over local probing: the script ran before
// any privilege change and its answers describe the same host, so re-deriving
// them here could only disagree confusingly.
func Detect(ctx context.Context, opts Options) Detection {
	// install.sh has already looked at /etc/os-release; machine.Detect reads
	// the same file plus the size of the machine, and knows about cgroups, so
	// an installer running inside a container does not report the host's cores.
	facts := machine.Detect()
	d := Detection{
		OS:          firstNonEmpty(opts.DetectedOS, runtime.GOOS),
		Arch:        firstNonEmpty(opts.DetectedArch, runtime.GOARCH),
		Distro:      firstNonEmpty(opts.DetectedDistro, facts.Distro, readDistroID()),
		OSVersion:   facts.OSVersion,
		CPUs:        facts.CPUs,
		MemoryMB:    facts.MemoryMB,
		Hostname:    hostname(),
		UID:         os.Geteuid(),
		GID:         os.Getegid(),
		ConfigDir:   opts.configDir(),
		StateDir:    opts.stateDir(),
		Interactive: opts.interactive(),
		BinaryPath:  opts.binaryPath(),
	}
	d.Root = d.UID == 0
	d.User = currentUserName(d.UID)

	if opts.DetectedInit != "" {
		d.Init = InitSystem(opts.DetectedInit)
	} else {
		d.Init = detectInit()
	}
	d.HasSystemd = d.Init == InitSystemd && lookPath("systemctl") != ""
	d.HasLaunchd = d.Init == InitLaunchd && lookPath("launchctl") != ""
	d.HasSCM = d.OS == "windows" && lookPath("sc.exe") != ""
	d.Compose = detectCompose(ctx, opts.DetectedCompose)
	d.HasCompose = d.Compose.Available

	d.Docker = probeRuntime(ctx, store.BackendDocker, socketHintFor(opts, store.BackendDocker))
	d.Podman = probeRuntime(ctx, store.BackendPodman, socketHintFor(opts, store.BackendPodman))
	// install.sh worked out rootlessness from the socket's path before any
	// privilege change. A daemon that does not advertise it in /info -- some
	// Podman builds do not -- would otherwise be treated as a root one and
	// warned about for no reason.
	if opts.DetectedRootless {
		markRootless(&d.Docker, opts)
		markRootless(&d.Podman, opts)
	}

	for _, p := range defaultPorts {
		d.Ports = append(d.Ports, checkPort(p))
	}
	d.Existing = ExistingInstallAt(d.ConfigDir, d.StateDir, d.BinaryPath)
	return d
}

// markRootless applies install.sh's finding to the runtime it described, and
// only when the probe landed on the same socket the script was talking about.
func markRootless(r *RuntimeInfo, opts Options) {
	if !r.Available || r.Rootless {
		return
	}
	hint := socketHintFor(opts, r.Kind)
	if hint != "" && hint == r.Endpoint {
		r.Rootless = true
	}
}

// socketHintFor returns the socket install.sh found, but only for the runtime
// it belongs to; handing a Podman socket to the Docker probe would report a
// Docker daemon that is not there.
func socketHintFor(opts Options, kind store.BackendKind) string {
	if opts.DetectedSocket == "" {
		return ""
	}
	if !strings.HasPrefix(opts.DetectedRuntime, string(kind)) {
		return ""
	}
	if strings.Contains(opts.DetectedSocket, "://") {
		return opts.DetectedSocket
	}
	return "unix://" + opts.DetectedSocket
}

// probeRuntime asks one runtime what it can do here. A missing daemon is not
// an error: the installer has to be able to report it and carry on offering
// the other backends.
func probeRuntime(ctx context.Context, kind store.BackendKind, hint string) RuntimeInfo {
	out := RuntimeInfo{Kind: kind}
	cli := "docker"
	if kind == store.BackendPodman {
		cli = "podman"
	}
	out.Installed = lookPath(cli) != ""

	var (
		b   backend.Backend
		err error
	)
	opts := backend.DockerOptions{Host: hint}
	if kind == store.BackendPodman {
		b, err = backend.NewPodman(opts)
	} else {
		b, err = backend.NewDocker(opts)
	}
	if err != nil {
		out.Detail = err.Error()
		return out
	}

	ctx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()
	info := b.Probe(ctx)
	out.Available = info.Available
	out.Rootless = info.Rootless
	out.Endpoint = info.Endpoint
	out.Version = info.Version
	out.Detail = info.Detail
	out.Limits = info.Limits
	if !out.Available && out.Detail == "" && out.Endpoint != "" {
		if err := backend.CanUseDockerSocket(out.Endpoint); err != nil {
			out.Detail = err.Error()
		}
	}
	return out
}

// probeTimeout bounds each runtime probe. A daemon that has not answered in
// five seconds is not one the operator wants to wait on during setup.
const probeTimeout = 5 * time.Second

// detectInit works out the supervisor without help from install.sh, which is
// the path taken when `zoomies init` is run on its own.
func detectInit() InitSystem {
	if runtime.GOOS == "darwin" {
		if lookPath("launchctl") != "" {
			return InitLaunchd
		}
		return InitNone
	}
	if backend.HasSystemd() {
		return InitSystemd
	}
	if _, err := os.Stat("/sbin/openrc-run"); err == nil {
		return InitOpenRC
	}
	return InitNone
}

// ExistingInstallAt reports which pieces of a previous installation are on
// disk. It takes its directories as arguments so that it can be tested against
// a temporary directory rather than against the real /etc.
func ExistingInstallAt(configDir, stateDir, binary string) ExistingInstall {
	var e ExistingInstall
	if p := filepath.Join(configDir, "zoomies.yaml"); exists(p) {
		e.ConfigFile = p
	}
	if p := filepath.Join(configDir, "encryption.key"); exists(p) {
		e.KeyFile = p
	}
	if p := filepath.Join(stateDir, "zoomies.db"); exists(p) {
		e.Database = p
	}
	if p := filepath.Join(stateDir, "work", "agent.json"); exists(p) {
		e.AgentState = p
	}
	if p := SystemdUnitPath(UnitController); exists(p) {
		e.Unit = p
	}
	if p := SystemdUnitPath(UnitAgent); exists(p) {
		e.AgentUnit = p
	}
	if binary != "" && exists(binary) {
		e.Binary = binary
		e.BinaryVersion = binaryVersion(binary)
	}
	return e
}

// binaryVersion asks an installed binary what it is. It is best effort: an
// unreadable or foreign binary simply has no version to report.
func binaryVersion(path string) string {
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, path, "version", "--short").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// checkPort reports whether the installer could bind a port on all interfaces.
// Binding is the only honest test: a port can be free in /proc and still be
// refused by a container's network namespace or by a privileged-port rule.
func checkPort(port int) PortStatus {
	s := PortStatus{Port: port}
	ln, err := net.Listen("tcp", net.JoinHostPort("", strconv.Itoa(port)))
	if err != nil {
		s.Detail = err.Error()
		return s
	}
	_ = ln.Close()
	s.Free = true
	return s
}

// PortFree reports whether a TCP port can be bound on host. An empty host
// means every interface, which is the stricter check of the two.
func PortFree(host string, port int) bool {
	ln, err := net.Listen("tcp", net.JoinHostPort(host, strconv.Itoa(port)))
	if err != nil {
		return false
	}
	_ = ln.Close()
	return true
}

// BindFree reports whether a "host:port" bind address is available, returning
// the parse error for an address that is not one.
func BindFree(bind string) (bool, error) {
	host, portStr, err := net.SplitHostPort(bind)
	if err != nil {
		return false, fmt.Errorf("%q is not a host:port address: %w", bind, err)
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		return false, fmt.Errorf("%q does not end in a port number: %w", bind, err)
	}
	return PortFree(host, port), nil
}

// NextFreePort suggests a port near the one the operator wanted, so a busy
// 8080 becomes an offer of 8081 rather than a dead end.
func NextFreePort(host string, from int, tries int) (int, bool) {
	for p := from; p < from+tries && p < 65536; p++ {
		if PortFree(host, p) {
			return p, true
		}
	}
	return 0, false
}

// Lines renders the detection as the block Run prints at the start. The shape
// deliberately matches install.sh's own "Looking around" output, so the two
// halves of one install read as one program.
// Fields is Lines without the padding: the same key/value pairs, for a caller
// that owns the column itself. `ui.field` is that caller, and it is not faint
// -- which the host report ought not to be either, given install.sh has just
// printed the same facts at full weight.
func (d Detection) Fields() []Field {
	out := make([]Field, 0, 12)
	for _, line := range d.Lines() {
		key := strings.TrimSpace(line[:min(12, len(line))])
		value := ""
		if len(line) > 12 {
			value = line[12:]
		}
		out = append(out, Field{Key: key, Value: value})
	}
	return out
}

// Field is one key/value row of the host report.
type Field struct {
	Key   string
	Value string
}

func (d Detection) Lines() []string {
	out := []string{
		fmt.Sprintf("%-12s%s/%s (%s)", "os", d.OS, d.Arch, d.describeDistro()),
		fmt.Sprintf("%-12s%s", "size", d.describeSize()),
		fmt.Sprintf("%-12s%s", "init", d.Init),
		fmt.Sprintf("%-12s%s (uid %d)%s", "user", d.User, d.UID, map[bool]string{true: " -- root", false: ""}[d.Root]),
		fmt.Sprintf("%-12s%s", "config", d.ConfigDir),
		fmt.Sprintf("%-12s%s", "state", d.StateDir),
	}
	out = append(out, runtimeLine(d.Docker), runtimeLine(d.Podman))
	if d.Compose.Available {
		out = append(out, fmt.Sprintf("%-12s%s", "compose", d.Compose))
	}
	for _, p := range d.Ports {
		if !p.Free {
			out = append(out, fmt.Sprintf("%-12sport %d is not available: %s", "ports", p.Port, p.Detail))
		}
	}
	if !d.Interactive {
		out = append(out, fmt.Sprintf("%-12sno terminal attached; answers must come from the answer file or flags", "prompts"))
	}
	if d.Existing.Present() {
		out = append(out, fmt.Sprintf("%-12sa previous installation is present", "existing"))
	}
	return out
}

// describeDistro is the distribution and its release, which together are what
// decides which runner image this host can run.
func (d Detection) describeDistro() string {
	if d.OSVersion == "" {
		return d.Distro
	}
	return d.Distro + " " + d.OSVersion
}

// describeSize is how much machine this is, in the words the host's name uses.
func (d Detection) describeSize() string {
	if d.CPUs <= 0 {
		return "unknown"
	}
	out := fmt.Sprintf("%d vCPU", d.CPUs)
	if d.MemoryMB > 0 {
		out += fmt.Sprintf(", %d GB", d.MemoryMB/1024)
	}
	return out
}

// HostName is the canonical name this machine would join under: what it is,
// then which one it is. `zoomies agent join --name` overrides it.
func (d Detection) HostName() string {
	spec := naming.Spec{
		CPUs:     float64(d.CPUs),
		MemoryGB: int(d.MemoryMB / 1024),
		OS:       firstNonEmpty(d.Distro, d.OS),
		Version:  d.OSVersion,
		Arch:     d.Arch,
		Suffix:   d.Hostname,
	}
	if spec.Empty() {
		return naming.Slug(d.Hostname)
	}
	return spec.String()
}

func runtimeLine(r RuntimeInfo) string {
	label := string(r.Kind)
	switch {
	case r.Available && r.Rootless:
		return fmt.Sprintf("%-12srootless, %s -- %s", label, r.Version, r.Endpoint)
	case r.Available:
		return fmt.Sprintf("%-12sroot, %s -- %s", label, r.Version, r.Endpoint)
	case r.Installed:
		return fmt.Sprintf("%-12sinstalled but its socket is not reachable: %s", label, firstLine(r.Detail))
	default:
		return fmt.Sprintf("%-12snot installed", label)
	}
}

// CanUseSocket reports whether this user can talk to a runtime's socket, and
// why not when it cannot. The installer uses it to decide whether the service
// user needs to be added to a group.
func CanUseSocket(endpoint string) error { return backend.CanUseDockerSocket(endpoint) }

// dockerGroupGID returns the numeric gid of the docker group, or 0 when the
// host has no such group. A root Docker socket is usually reachable only for
// members of that group, and the systemd unit has to name it.
func dockerGroupGID() int {
	g, err := user.LookupGroup("docker")
	if err != nil {
		return 0
	}
	gid, err := strconv.Atoi(g.Gid)
	if err != nil {
		return 0
	}
	return gid
}

func exists(p string) bool {
	if p == "" {
		return false
	}
	_, err := os.Stat(p)
	return err == nil
}

func lookPath(bin string) string {
	p, err := exec.LookPath(bin)
	if err != nil {
		return ""
	}
	return p
}

func hostname() string {
	h, err := os.Hostname()
	if err != nil || h == "" {
		return "localhost"
	}
	return h
}

func currentUserName(uid int) string {
	if u, err := user.Current(); err == nil && u.Username != "" {
		return u.Username
	}
	if u, err := user.LookupId(strconv.Itoa(uid)); err == nil {
		return u.Username
	}
	return "uid " + strconv.Itoa(uid)
}

// readDistroID reads ID= from /etc/os-release, the same field install.sh uses,
// so that a directly-run `zoomies init` reports the distro the same way.
func readDistroID() string {
	if runtime.GOOS == "darwin" {
		return "macos"
	}
	b, err := os.ReadFile("/etc/os-release")
	if err != nil {
		return "unknown"
	}
	for _, line := range strings.Split(string(b), "\n") {
		if v, ok := strings.CutPrefix(strings.TrimSpace(line), "ID="); ok {
			return strings.Trim(strings.TrimSpace(v), `"`)
		}
	}
	return "unknown"
}

func firstNonEmpty(vals ...string) string {
	for _, v := range vals {
		if strings.TrimSpace(v) != "" {
			return strings.TrimSpace(v)
		}
	}
	return ""
}

func firstLine(s string) string {
	s = strings.TrimSpace(s)
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

// userExists reports whether a local account of this name is present, which is
// how uninstall avoids running userdel for an account that is already gone.
func userExists(name string) bool {
	_, err := user.Lookup(name)
	return err == nil
}

package installer

import (
	"net"
	"os"
	"os/user"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"testing"
)

// A port the installer would bind is checked by binding it, because a port
// free in /proc can still be refused by a container's network namespace. The
// honest test is the one the operator's host will perform.
//
// The port here is held on every interface, which is the scope checkPort uses:
// Windows lets a wildcard bind succeed over one held on the loopback address
// alone, so a test that held only 127.0.0.1 would be asking a question with
// two different answers depending on the platform.
func TestAPortInUseIsReportedWithTheReasonItCouldNotBeTaken(t *testing.T) {
	ln, err := net.Listen("tcp", ":0")
	if err != nil {
		t.Fatalf("taking a port: %v", err)
	}
	defer func() { _ = ln.Close() }()
	port := ln.Addr().(*net.TCPAddr).Port

	busy := checkPort(port)
	if busy.Port != port {
		t.Errorf("port = %d, want the one that was asked about", busy.Port)
	}
	if busy.Free {
		t.Fatalf("port %d is held by this test and was reported free", port)
	}
	if strings.TrimSpace(busy.Detail) == "" {
		t.Error("a port that could not be bound was reported with nothing to say why")
	}
	if PortFree("", port) {
		t.Errorf("PortFree said %d was free on every interface while this test held it", port)
	}

	// And once it is given up, both answers change.
	if err := ln.Close(); err != nil {
		t.Fatalf("giving the port back: %v", err)
	}
	if free := checkPort(port); !free.Free || free.Detail != "" {
		t.Errorf("checkPort after the listener closed = %+v, want free and nothing to explain", free)
	}
	if !PortFree("127.0.0.1", port) {
		t.Errorf("PortFree said %d was taken after the listener closed", port)
	}
}

// The host is described well enough to fill a plan: a name for the runner
// pool, an OS and architecture for the image, and the directories the rest of
// setup writes to.
//
// The installed binary is named rather than left to default. Detect asks an
// installed binary its version by running it, and the default is this
// process -- so a test that left it out ran the test binary again, as a child,
// with every test in the package inside it. On Windows the still-running copy
// then held its own file open and `go test` could not clean up after itself.
func TestDetectDescribesTheHostThePlanNeeds(t *testing.T) {
	cfg, state := t.TempDir(), t.TempDir()
	binary := filepath.Join(t.TempDir(), "zoomies")
	d := Detect(t.Context(), Options{
		NonInteractive: true, ConfigDir: cfg, StateDir: state, InstalledBinary: binary,
	})

	if d.OS != runtime.GOOS || d.Arch != runtime.GOARCH {
		t.Errorf("detected %s/%s, want this host's own %s/%s", d.OS, d.Arch, runtime.GOOS, runtime.GOARCH)
	}
	if d.Hostname == "" {
		t.Error("no hostname; the first pool's runners are named after it")
	}
	if d.User == "" {
		t.Error("no user; the installer decides whether it can create a service account from it")
	}
	if d.ConfigDir != cfg || d.StateDir != state {
		t.Errorf("directories = %q and %q, want the ones the caller gave", d.ConfigDir, d.StateDir)
	}
	if d.UID != os.Geteuid() || d.Root != (os.Geteuid() == 0) {
		t.Errorf("uid = %d, root = %v; want this process's own identity", d.UID, d.Root)
	}
	if d.Interactive {
		t.Error("a run told not to prompt was detected as interactive")
	}
	if len(d.Ports) == 0 {
		t.Error("no port was checked, so the summary cannot warn about one already in use")
	}
	if d.BinaryPath != binary {
		t.Errorf("binary path = %q, want the one install.sh named, %q", d.BinaryPath, binary)
	}
}

// install.sh probed this host moments ago, before any privilege change, so
// what it found is trusted over anything re-derived here.
func TestTheScriptsFindingsWinOverLocalProbing(t *testing.T) {
	d := Detect(t.Context(), Options{
		NonInteractive:  true,
		ConfigDir:       t.TempDir(),
		StateDir:        t.TempDir(),
		InstalledBinary: filepath.Join(t.TempDir(), "zoomies"),
		DetectedDistro:  "alpine",
		DetectedInit:    string(InitOpenRC),
	})
	if d.Distro != "alpine" {
		t.Errorf("distro = %q, want the script's own answer", d.Distro)
	}
	if d.Init != InitOpenRC {
		t.Errorf("init = %q, want the script's own answer", d.Init)
	}
	// An init system nobody supervises with is not claimed as one that is.
	if d.HasSystemd || d.HasLaunchd {
		t.Errorf("host reports systemd=%v launchd=%v under OpenRC", d.HasSystemd, d.HasLaunchd)
	}
}

// The account questions are asked of the host, because uninstall runs userdel
// only for an account that is really there, and the summary names the user as
// `ls -l` would.
func TestTheLocalAccountQuestionsAreAnsweredByTheHost(t *testing.T) {
	me, err := user.Current()
	if err != nil {
		t.Skipf("this host has no current user to ask about: %v", err)
	}
	if !userExists(me.Username) {
		t.Errorf("userExists(%q) = false for the account running this test", me.Username)
	}
	if userExists("zoomies-no-such-account-9f3a") {
		t.Error("an account that does not exist was reported present, so uninstall would run userdel for nothing")
	}

	uid, err := strconv.Atoi(me.Uid)
	if err != nil {
		t.Skipf("uid %q is not a number on this platform", me.Uid)
	}
	if got := currentUserName(uid); got != me.Username {
		t.Errorf("currentUserName(%d) = %q, want %q", uid, got, me.Username)
	}
	// A uid with no account still reads as something an operator can match up
	// with what they see on disk.
	if got := ownerName(1 << 30); got != strconv.Itoa(1<<30) {
		t.Errorf("ownerName for an unknown uid = %q, want the number itself", got)
	}
}

// The distro is what a pool's platform is matched against, so it always says
// something -- "unknown" is a worse answer than a name, and an empty one
// would match nothing at all.
func TestTheDistroIsAlwaysAnswered(t *testing.T) {
	if got := readDistroID(); strings.TrimSpace(got) == "" {
		t.Error("readDistroID returned nothing; a pool's platform would match no image")
	}
	if runtime.GOOS == "darwin" && readDistroID() != "macos" {
		t.Errorf("readDistroID() = %q on darwin, want macos", readDistroID())
	}
}

// The name a host is known by never comes back empty: it goes into the first
// pool's runner names, and "-runner-1" would be a puzzle in the UI.
func TestTheHostnameFallsBackRatherThanBeingEmpty(t *testing.T) {
	if hostname() == "" {
		t.Error("hostname() = \"\", want a fallback")
	}
}

package installer

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestExistingInstallAtFindsNothingInAnEmptyDirectory(t *testing.T) {
	e := ExistingInstallAt(t.TempDir(), t.TempDir(), "")
	if e.Present() {
		t.Fatalf("nothing is installed here, got %+v", e)
	}
	if e.HasState() {
		t.Fatal("no key and no database means no state")
	}
	if len(e.Items()) != 0 {
		t.Fatalf("nothing to list, got %v", e.Items())
	}
}

func TestExistingInstallAtFindsEachPiece(t *testing.T) {
	cfgDir, stateDir := t.TempDir(), t.TempDir()
	writeFile(t, cfgDir, "zoomies.yaml", "server:\n  bind: 127.0.0.1:8080\n")
	writeFile(t, cfgDir, "encryption.key", "not a real key\n")
	writeFile(t, stateDir, "zoomies.db", "")
	if err := os.MkdirAll(filepath.Join(stateDir, "work"), 0o750); err != nil {
		t.Fatal(err)
	}
	writeFile(t, filepath.Join(stateDir, "work"), "agent.json", "{}")

	e := ExistingInstallAt(cfgDir, stateDir, "")
	if !e.Present() || !e.HasState() {
		t.Fatalf("want a present install with state, got %+v", e)
	}
	if e.ConfigFile == "" || e.KeyFile == "" || e.Database == "" || e.AgentState == "" {
		t.Fatalf("a piece was missed: %+v", e)
	}

	items := strings.Join(e.Items(), "\n")
	for _, want := range []string{"config", "encryption key", "database", "agent creds"} {
		if !strings.Contains(items, want) {
			t.Errorf("the summary should name %q:\n%s", want, items)
		}
	}
}

func TestExistingInstallStateIsWhatNeedsAConfirmation(t *testing.T) {
	cfgDir, stateDir := t.TempDir(), t.TempDir()
	writeFile(t, cfgDir, "zoomies.yaml", "")

	e := ExistingInstallAt(cfgDir, stateDir, "")
	if !e.Present() {
		t.Fatal("a config file is an existing install")
	}
	// Only the key and the database are irreplaceable, and only they trigger
	// the typed confirmation.
	if e.HasState() {
		t.Fatalf("a config file alone is not state: %+v", e)
	}
}

func TestExistingInstallReportsTheBinary(t *testing.T) {
	dir := t.TempDir()
	binary := writeFile(t, dir, "zoomies", "#!/bin/sh\nexit 1\n")
	e := ExistingInstallAt(t.TempDir(), t.TempDir(), binary)
	if e.Binary != binary {
		t.Fatalf("binary = %q, want %q", e.Binary, binary)
	}
	if !strings.Contains(strings.Join(e.Items(), "\n"), "binary") {
		t.Fatalf("the summary should name the binary: %v", e.Items())
	}
}

func TestDetectionLinesDescribeTheHost(t *testing.T) {
	d := Detection{
		OS: "linux", Arch: "amd64", Distro: "ubuntu", Init: InitSystemd,
		User: "root", UID: 0, Root: true,
		ConfigDir: "/etc/zoomies", StateDir: "/var/lib/zoomies",
		Docker: RuntimeInfo{Kind: "docker", Available: true, Rootless: true, Version: "27.1.1", Endpoint: "unix:///run/user/1000/docker.sock"},
		Podman: RuntimeInfo{Kind: "podman", Installed: true, Detail: "no socket at /run/podman/podman.sock"},
		Ports:  []PortStatus{{Port: 8080, Free: false, Detail: "address already in use"}},
	}
	lines := strings.Join(d.Lines(), "\n")

	for _, want := range []string{
		"linux/amd64 (ubuntu)",
		"systemd",
		"root",
		"rootless, 27.1.1 -- unix:///run/user/1000/docker.sock",
		"installed but its socket is not reachable",
		"port 8080 is not available",
		"no terminal attached",
	} {
		if !strings.Contains(lines, want) {
			t.Errorf("detection summary is missing %q:\n%s", want, lines)
		}
	}
}

func TestSocketHintOnlyGoesToItsOwnRuntime(t *testing.T) {
	opts := Options{DetectedRuntime: "docker", DetectedSocket: "/run/user/1000/docker.sock"}
	if got := socketHintFor(opts, "docker"); got != "unix:///run/user/1000/docker.sock" {
		t.Fatalf("docker hint = %q", got)
	}
	// Handing a Docker socket to the Podman probe would report a Podman daemon
	// that is not there.
	if got := socketHintFor(opts, "podman"); got != "" {
		t.Fatalf("podman hint = %q, want empty", got)
	}

	unavailable := Options{DetectedRuntime: "docker-unavailable", DetectedSocket: ""}
	if got := socketHintFor(unavailable, "docker"); got != "" {
		t.Fatalf("no socket means no hint, got %q", got)
	}
}

func TestFirstNonEmptyPrefersTheScriptsAnswer(t *testing.T) {
	if got := firstNonEmpty("", "  ", "fedora"); got != "fedora" {
		t.Fatalf("firstNonEmpty = %q", got)
	}
	if got := firstNonEmpty(" alpine ", "debian"); got != "alpine" {
		t.Fatalf("firstNonEmpty = %q", got)
	}
}

// ---------------------------------------------------------------------------
// What the detection step shows and names
// ---------------------------------------------------------------------------

// Fields is the inverse of the `%-12s` padding Lines writes, and the two are
// coupled by nothing but that number: Fields splits at column 12 whatever
// Lines put there. A key one character too long would quietly take its own
// last letters into the value and show the operator a mangled summary, so the
// round trip is the thing worth pinning.
func TestDetectionFieldsSplitEveryLineItRenders(t *testing.T) {
	d := Detection{
		OS: "linux", Arch: "amd64", Distro: "ubuntu", OSVersion: "24.04",
		CPUs: 8, MemoryMB: 16384,
		Init: InitSystemd, Hostname: "build-box",
		User: "ada", UID: 1000, GID: 1000,
		Docker:      RuntimeInfo{Kind: store.BackendDocker, Available: true, Version: "27.1", Endpoint: "unix:///var/run/docker.sock"},
		Podman:      RuntimeInfo{Kind: store.BackendPodman},
		Compose:     ComposeInfo{Command: []string{"docker", "compose"}, Available: true},
		Ports:       []PortStatus{{Port: 8080, Free: false, Detail: "something else is listening"}},
		ConfigDir:   "/etc/zoomies",
		StateDir:    "/var/lib/zoomies",
		Interactive: false,
	}

	lines, fields := d.Lines(), d.Fields()
	if len(lines) != len(fields) {
		t.Fatalf("%d lines but %d fields", len(lines), len(fields))
	}
	for i, f := range fields {
		if f.Key == "" {
			t.Errorf("line %d (%q) split into an empty key", i, lines[i])
		}
		if strings.Contains(f.Key, " ") {
			t.Errorf("line %d split inside a value: key %q", i, f.Key)
		}
		if got := fmt.Sprintf("%-12s%s", f.Key, f.Value); got != lines[i] {
			t.Errorf("line %d does not round trip:\n got %q\nwant %q", i, got, lines[i])
		}
	}

	// The summary is what an operator reads before answering anything, so the
	// facts that change their answers have to be in it.
	joined := strings.Join(lines, "\n")
	for _, want := range []string{"ubuntu", "24.04", "systemd", "ada", "/etc/zoomies", "8080"} {
		if !strings.Contains(joined, want) {
			t.Errorf("the detection summary never mentions %q:\n%s", want, joined)
		}
	}
}

// A host is named after its shape, with the machine's own hostname as the
// discriminator. The hostname is whatever somebody typed into a DHCP lease, so
// it goes through the slug on the way in: a host name ends up on a runner and
// has to be a label, not a sentence with spaces and capitals in it.
func TestDetectionHostNameDescribesTheMachineAndSlugsItsHostname(t *testing.T) {
	shaped := Detection{CPUs: 8, MemoryMB: 16384, Distro: "ubuntu", OSVersion: "24.04", Arch: "amd64", Hostname: "ci-1"}
	name := shaped.HostName()
	for _, want := range []string{"8vcpu", "16gb", "ubuntu"} {
		if !strings.Contains(name, want) {
			t.Errorf("HostName() = %q, which does not carry the machine's %s", name, want)
		}
	}

	// Nothing measurable about the machine, so the name is the hostname --
	// still slugged, and still carrying the prefix every Zoomies name has.
	bare := Detection{Hostname: "Build Box 01"}
	got := bare.HostName()
	if strings.ContainsAny(got, " ") || strings.ToLower(got) != got {
		t.Errorf("HostName() = %q, which is not a usable label", got)
	}
	if !strings.HasSuffix(got, "build-box-01") {
		t.Errorf("HostName() = %q, want the slugged hostname at the end of it", got)
	}
}

// install.sh hands its own compose finding across as a string, and it is the
// answer that wins: the script asked this host moments ago. Parsing it has to
// survive the spacing a shell variable arrives with.
func TestParseComposeCommandTakesTheScriptsAnswer(t *testing.T) {
	for _, tc := range []struct {
		in   string
		want []string
	}{
		{"docker compose", []string{"docker", "compose"}},
		{"  docker-compose  ", []string{"docker-compose"}},
		{"", nil},
		{"   ", nil},
	} {
		got := ParseComposeCommand(tc.in)
		if len(got) != len(tc.want) {
			t.Errorf("ParseComposeCommand(%q) = %v, want %v", tc.in, got, tc.want)
			continue
		}
		for i := range got {
			if got[i] != tc.want[i] {
				t.Errorf("ParseComposeCommand(%q) = %v, want %v", tc.in, got, tc.want)
				break
			}
		}
	}

	// String is how the command is shown back, so it has to be what would be
	// typed rather than Go's rendering of a slice.
	if got := (ComposeInfo{Command: []string{"docker", "compose"}}).String(); got != "docker compose" {
		t.Errorf("ComposeInfo.String() = %q, want %q", got, "docker compose")
	}
}

package installer

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/machine"
)

// EnvFileName is the environment file a compose deployment reads. Compose
// picks it up automatically from the directory the project is brought up in,
// which is why it is not named after Zoomies.
const EnvFileName = ".env"

// DockerEnvFileName is the environment file a single-container deployment
// reads. It is named rather than hidden because nothing picks it up
// automatically: `docker run --env-file` has to be pointed at it, and an
// operator reading their own shell history should be able to tell what it is.
const DockerEnvFileName = "zoomies.env"

// EnvSpec is every value a generated environment file carries.
//
// It is a plain struct with no behaviour so that RenderEnv can be a pure
// function from it to a string: the file the operator ends up with is then
// something a test can assert on directly, character for character, rather
// than something that only exists after an install has touched a host.
type EnvSpec struct {
	// Deployment and Mode decide which variables belong in the file at all: a
	// controller needs a listener, an agent needs a controller to talk to.
	Deployment Deployment
	Mode       Mode

	// ExternalURL is how GitHub and browsers reach this controller.
	ExternalURL string
	// EncryptionKey is base64, 32 bytes. It is the reason the file is 0600.
	EncryptionKey string

	// Bind is the address inside the container. PublishAddr and PublishedPort
	// are the host side of the same listener.
	Bind          string
	PublishAddr   string
	PublishedPort int

	TLSMode        config.TLSMode
	TLSCertFile    string
	TLSKeyFile     string
	TrustedProxies []string

	// Embedded, Backend, DockerHost and Capacity describe the agent half.
	Embedded   bool
	Backend    string
	DockerHost string
	Capacity   int
	// Network is the container network runner containers are attached to:
	// the one the deployment declares. Left unset, the agent would put them
	// on the daemon's default bridge, whatever the compose file's comment
	// promises.
	Network string

	WorkDir string
	DBPath  string
	// StateDir is where the container keeps anything it generates, which is
	// the volume's mount point.
	StateDir string

	LogFormat string
	LogLevel  string
	// PollFallback is the queued-job poller. It is a pointer only so that
	// "not set" can take the safe default of true rather than of false.
	PollFallback *bool
	// AllowWorkflowCancellation controls GitHub Actions write access and the
	// operator cancellation action. It is a pointer so unset inherits true.
	AllowWorkflowCancellation *bool
	// GitHubAPIBaseURL is https://api.github.com, or a GHES API root.
	GitHubAPIBaseURL string

	// Image and DockerGID are read by compose and by docker run, not by
	// Zoomies itself.
	Image     string
	DockerGID int

	// ControllerURL and JoinToken are how a containerised agent reaches a
	// controller and earns a lasting credential from it.
	//
	// A join token rather than an agent token, which is what this used to
	// carry: nothing reads an agent token back out of the configuration. The
	// daemon takes its credentials from the state file a join wrote, and the
	// one fallback when that file is absent is a join token -- so an agent
	// handed only ZOOMIES_AGENT_TOKEN refuses to start, saying it has no
	// credentials and no join token to get some. A container given a join
	// token joins itself on first start and writes the state file into its
	// volume, where every later start finds it.
	ControllerURL string
	JoinToken     string
	// AgentName is what this host calls itself. A container has to be told:
	// the name is derived from the machine and the hostname, and a container's
	// hostname is whatever the deployment set it to -- the same for every host
	// running the same file, which is how two machines of the same shape end
	// up computing one name and the second one's join is refused.
	AgentName string
}

// defaults fills in the values a caller may reasonably leave empty, so that
// RenderEnv is total: every field it prints has a sensible value, and the
// operator never opens the file to find a blank where a decision should be.
func (s EnvSpec) defaults() EnvSpec {
	if s.Deployment == "" {
		s.Deployment = DeploymentCompose
	}
	if s.Mode == "" {
		s.Mode = ModeSingle
	}
	if s.Image == "" {
		s.Image = DefaultImage()
	}
	if s.Mode == ModeAgent {
		// A dedicated agent is not an embedded one, whatever the plan carried.
		// The two are the mutually exclusive halves of how an agent exists --
		// inside a controller, or against one -- and the zoomies.yaml a native
		// join writes says so outright. An environment file that said otherwise
		// would be the only place they disagreed.
		s.Embedded = false
		// The image follows suit: the tag is the deployment's, the repository
		// is the agent's.
		if img, ok := AgentImageFor(s.Image); ok {
			s.Image = img
		}
	}
	if s.Bind == "" {
		s.Bind = "0.0.0.0:" + strconv.Itoa(ContainerPort)
	}
	if s.PublishAddr == "" {
		s.PublishAddr = "127.0.0.1"
	}
	if s.PublishedPort == 0 {
		s.PublishedPort = ContainerPort
	}
	if s.TLSMode == "" {
		s.TLSMode = config.TLSOff
	}
	if s.Backend == "" {
		s.Backend = "docker"
	}
	if s.Capacity <= 0 {
		// No detection here: this fills in an env file that is being written
		// without one, so the process's own view of the machine is the only
		// figure there is. Every path that has measured the host passes what
		// it measured, and this one is the fallback it always was.
		s.Capacity = defaultCapacity(Detection{})
	}
	if s.WorkDir == "" {
		s.WorkDir = ContainerWorkDir
	}
	if s.DBPath == "" {
		s.DBPath = ContainerDBPath
	}
	if s.StateDir == "" {
		s.StateDir = ContainerStateDir
	}
	if s.LogFormat == "" {
		s.LogFormat = "json"
	}
	if s.LogLevel == "" {
		s.LogLevel = "info"
	}
	if s.GitHubAPIBaseURL == "" {
		s.GitHubAPIBaseURL = "https://api.github.com"
	}
	if s.PollFallback == nil {
		on := true
		s.PollFallback = &on
	}
	if s.AllowWorkflowCancellation == nil {
		on := true
		s.AllowWorkflowCancellation = &on
	}
	return s
}

// Config renders the configuration the container will actually run with.
//
// A container deployment writes no zoomies.yaml: its configuration is the
// environment file and, for a controller, the settings stored in its database
// before it first starts (SettingsEnv). This is both of them together, which
// is what lets a test put a generated deployment through config.Validate and
// assert that each one produces a controller that starts, and produces
// exactly the warnings that deployment deserves.
func (s EnvSpec) Config() *config.Config {
	s = s.defaults()
	cfg := config.Default()
	cfg.Server.Bind = s.Bind
	cfg.Server.ExternalURL = strings.TrimRight(s.ExternalURL, "/")
	cfg.Server.TLS.Mode = s.TLSMode
	cfg.Server.TLS.CertFile = s.TLSCertFile
	cfg.Server.TLS.KeyFile = s.TLSKeyFile
	cfg.Server.TrustedProxies = s.TrustedProxies

	cfg.Database.Path = s.DBPath
	// The key is in the environment, not in a file the container can read, so
	// the key file setting is cleared rather than left pointing at a path that
	// does not exist inside the image.
	cfg.Security.EncryptionKey = s.EncryptionKey
	cfg.Security.EncryptionKeyFile = ""

	cfg.GitHub.APIBaseURL = s.GitHubAPIBaseURL
	cfg.GitHub.PollFallback = *s.PollFallback
	cfg.GitHub.AllowWorkflowCancellation = *s.AllowWorkflowCancellation

	cfg.Agent.Embedded = s.Embedded
	cfg.Agent.Capacity = s.Capacity
	cfg.Agent.Backend = s.Backend
	cfg.Agent.DockerHost = s.DockerHost
	cfg.Agent.WorkDir = s.WorkDir
	cfg.Agent.ControllerURL = s.ControllerURL
	cfg.Agent.JoinToken = s.JoinToken
	cfg.Agent.Name = s.AgentName
	if cfg.Agent.Name == "" {
		cfg.Agent.Name = machine.DefaultHostName()
	}

	cfg.Log.Format = s.LogFormat
	cfg.Log.Level = s.LogLevel

	secure := s.TLSMode != config.TLSOff || strings.HasPrefix(cfg.Server.ExternalURL, "https://")
	cfg.Security.CookieSecure = &secure
	return cfg
}

// required lists the values this file would otherwise be written with a blank
// for.
//
// A blank is a placeholder, and a placeholder is the thing this generator
// exists to abolish: an operator who has to go and fill something in has been
// handed a half-finished install and told it is done. Refusing here means the
// failure lands during setup, where it can be fixed, rather than at first
// start.
//
// settingsOnly is SettingsEnv's check: the encryption key is not one of the
// settings, and the installer stores them before WriteEnv has generated it.
func (s EnvSpec) required(settingsOnly bool) []string {
	var missing []string
	if s.Mode == ModeAgent {
		if s.ControllerURL == "" {
			missing = append(missing, "ZOOMIES_CONTROLLER_URL (the controller this host joined)")
		}
		if s.JoinToken == "" {
			missing = append(missing, "ZOOMIES_JOIN_TOKEN (the token this host joins with on its first start)")
		}
		return missing
	}
	if s.ExternalURL == "" {
		missing = append(missing, "ZOOMIES_EXTERNAL_URL (the URL GitHub and your browser use)")
	}
	if s.EncryptionKey == "" && !settingsOnly {
		missing = append(missing, "ZOOMIES_ENCRYPTION_KEY (32 bytes, base64; WriteEnv generates one when there is none to keep)")
	}
	if s.TLSMode == config.TLSFiles && (s.TLSCertFile == "" || s.TLSKeyFile == "") {
		missing = append(missing, "ZOOMIES_TLS_CERT_FILE and ZOOMIES_TLS_KEY_FILE (tls mode is \"files\")")
	}
	return missing
}

// RenderEnv renders an environment file from a spec.
//
// Two rules govern what comes out. Nothing is left as a placeholder: every
// value was answered during setup, so an operator never has to open this file
// to make it work. And every variable carries a line saying what it is for,
// because the person who reads this file next is usually reading it six months
// later, at speed, without the documentation open.
//
// It is a pure function so that the file can be asserted on in a test rather
// than only observed after an install.
func RenderEnv(spec EnvSpec) (string, error) {
	body, _, err := renderEnv(spec, false)
	return body, err
}

// SettingsEnv is the other half of RenderEnv for a controller: the settings it
// keeps in its database, as the lines `zoomies config import-env` stores. An
// agent keeps none -- it has no database -- so its half is empty.
func SettingsEnv(spec EnvSpec) (string, error) {
	_, vars, err := renderEnv(spec, true)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	for _, v := range vars {
		quoted, err := quoteEnvValue(v.key, v.value)
		if err != nil {
			return "", err
		}
		b.WriteString(v.key + "=" + quoted + "\n")
	}
	return b.String(), nil
}

func renderEnv(spec EnvSpec, settingsOnly bool) (string, []envVar, error) {
	s := spec.defaults()
	if missing := s.required(settingsOnly); len(missing) > 0 {
		return "", nil, fmt.Errorf("installer: the environment file would be written with nothing in:\n  - %s",
			strings.Join(missing, "\n  - "))
	}
	w := &envWriter{database: s.Mode != ModeAgent}

	w.header(s)

	if s.Mode == ModeAgent {
		w.section("Joining a controller")
		w.set("ZOOMIES_CONTROLLER_URL", s.ControllerURL,
			"The controller this host takes work from. It is the URL `zoomies agent join` was pointed at.")
		w.set("ZOOMIES_JOIN_TOKEN", s.JoinToken,
			"Single-use, and spent the first time this host starts: it is exchanged for a lasting credential written into the state volume, which every later start reads instead. Mint another under Hosts -> Add a host if the volume is ever lost.")
		w.set("ZOOMIES_AGENT_NAME", s.AgentName,
			"What this host calls itself on the Hosts page. It is set explicitly because a container's hostname is the same on every machine running this file, and two hosts that compute one name are one host as far as the controller is concerned.")
	} else {
		w.section("The controller")
		w.set("ZOOMIES_EXTERNAL_URL", s.ExternalURL,
			"How GitHub and your browser reach this controller. Webhook deliveries go to this URL plus /webhooks/github, and the https here is what marks the session cookie Secure.")
		w.set("ZOOMIES_ENCRYPTION_KEY", s.EncryptionKey,
			"32 random bytes, base64. Everything secret in the database is sealed with it. Back it up separately from the database: without it the stored GitHub App private key and webhook secrets cannot be decrypted.")
		w.set("ZOOMIES_BIND", s.Bind,
			"Where the controller listens inside the container. The published port below is what actually controls exposure.")
		w.set("ZOOMIES_TLS_MODE", string(s.TLSMode), tlsModeComment(s.TLSMode))
		if s.TLSMode == config.TLSFiles {
			w.set("ZOOMIES_TLS_CERT_FILE", s.TLSCertFile,
				"The full chain to serve, PEM encoded. It is mounted into the container at this same path.")
			w.set("ZOOMIES_TLS_KEY_FILE", s.TLSKeyFile,
				"The certificate's private key, mounted read-only at this same path.")
		}
		w.set("ZOOMIES_TRUSTED_PROXIES", strings.Join(s.TrustedProxies, ","),
			"Comma-separated CIDRs whose X-Forwarded-For header is believed. Empty takes client addresses from the socket, which is safe but records your proxy's address in every audit entry and every login rate-limit decision.")
		w.set("ZOOMIES_GITHUB_API_BASE_URL", s.GitHubAPIBaseURL,
			"https://api.github.com, or https://ghes.example.com/api/v3 for GitHub Enterprise Server.")
		w.set("ZOOMIES_POLL_FALLBACK", strconv.FormatBool(*s.PollFallback),
			"The queued-job poller. Leave it on: it is what keeps jobs being picked up when a webhook delivery is lost or misconfigured.")
		w.set("ZOOMIES_ALLOW_WORKFLOW_CANCELLATION", strconv.FormatBool(*s.AllowWorkflowCancellation),
			"Allow operators to cancel whole workflow runs from Zoomies. Disable it to keep the GitHub App Actions permission read-only.")
	}

	w.section("The agent")
	w.set("ZOOMIES_AGENT_EMBEDDED", strconv.FormatBool(s.Embedded),
		"Whether this process runs runners itself. false makes it a controller only, and runner hosts join it with `zoomies agent join`.")
	w.set("ZOOMIES_AGENT_BACKEND", s.Backend,
		"docker, podman or process. The process backend runs workflow steps directly on this host with no container isolation.")
	w.set("ZOOMIES_DOCKER_HOST", s.DockerHost,
		"The socket runner containers are created on. This is Zoomies' own access to the runtime -- it is NOT pool.docker_mode=host-socket, which would hand the socket to your jobs.")
	w.set("ZOOMIES_AGENT_CAPACITY", strconv.Itoa(s.Capacity),
		"The most runners this host may hold at once. A pool's max_runners can be lower than this, never higher.")
	w.set("ZOOMIES_AGENT_NETWORK", s.Network,
		"The container network runner containers are attached to -- the one this deployment declares -- so they stay off the daemon's default bridge.")
	w.set("ZOOMIES_WORK_DIR", s.WorkDir,
		"Scratch space for runner work directories. It is inside the volume, so it survives the container being replaced.")

	w.section("Storage and logs")
	w.set("ZOOMIES_STATE_DIR", s.StateDir,
		"Where anything generated at run time goes -- a self-signed certificate, above all. It points into the volume so that replacing the container does not change the certificate underneath your agents.")
	w.set("ZOOMIES_DB_PATH", s.DBPath,
		"The SQLite database: pools, runners, job history, the audit log and the sealed GitHub credentials. It lives in the named volume.")
	w.set("ZOOMIES_LOG_FORMAT", s.LogFormat,
		"json or text. json is what a log shipper wants; text is what a person reading `docker logs` wants.")
	w.set("ZOOMIES_LOG_LEVEL", s.LogLevel,
		"debug, info, warn or error. debug logs repository and workflow names in full; secrets are redacted at every level.")

	w.section("Read by " + composeOrDocker(s.Deployment) + ", not by Zoomies")
	w.set("ZOOMIES_IMAGE", s.Image,
		"The image to run. Pin a release tag instead of latest if you would rather choose when to upgrade.")
	w.set("ZOOMIES_PUBLISHED_ADDR", s.PublishAddr,
		"The address on this host the container is published on. 127.0.0.1 means only this machine and whatever proxies from it can reach Zoomies.")
	w.set("ZOOMIES_PUBLISHED_PORT", strconv.Itoa(s.PublishedPort),
		"The port on this host that maps to the container's listener.")
	w.set("DOCKER_GID", dockerGIDValue(s.DockerGID), dockerGIDComment(s.DockerGID))

	body, err := w.result()
	return body, w.settings, err
}

// composeOrDocker names whichever tool reads the deployment-only variables, so
// the section heading is true for the file it is actually in.
func composeOrDocker(d Deployment) string {
	if d == DeploymentDocker {
		return "docker run"
	}
	return "docker compose"
}

func tlsModeComment(mode config.TLSMode) string {
	switch mode {
	case config.TLSFiles:
		return "off, self-signed or files. This container terminates TLS itself with the certificate below."
	case config.TLSSelfSigned:
		return "off, self-signed or files. A generated certificate: browsers will warn, and GitHub will refuse to deliver webhooks to it."
	default:
		return "off, self-signed or files. \"off\" is right when something in front of this host terminates TLS; Zoomies warns about the plaintext listener at startup, and that warning is expected here."
	}
}

func dockerGIDValue(gid int) string {
	if gid <= 0 {
		return ""
	}
	return strconv.Itoa(gid)
}

func dockerGIDComment(gid int) string {
	if gid <= 0 {
		return "The gid that owns the container socket. It could not be read on this host, so the container is given no extra group; if the embedded agent cannot reach the socket, set this to the gid that owns it (ls -l on the socket says which)."
	}
	return "The gid that owns the container socket, read from the socket itself on this host -- which is not always the group called docker. The image runs as uid 65532, which must be in this group to use the socket."
}

// envWriter builds the file. It collects the first error rather than returning
// one per line, so that a refusal names the variable that caused it and
// nothing is written at all.
type envWriter struct {
	b   strings.Builder
	err error
	// database sends every setting that lives in the database to settings
	// instead of the file: a controller keeps its settings there, and a
	// variable in this file would pin each one over the settings page.
	database bool
	settings []envVar
	// pending is a section heading not yet written, because a section whose
	// every variable went to the database has nothing under it.
	pending string
	// keys guards against a variable being written twice, which would leave
	// the second value silently winning.
	keys map[string]bool
}

func (w *envWriter) header(s EnvSpec) {
	fmt.Fprintf(&w.b, `# Zoomies -- environment for the %s deployment.
#
# Written by `+"`zoomies init`"+`. Every value here was answered during setup:
# there is nothing left to fill in.
#
# This file is mode 0600 because ZOOMIES_ENCRYPTION_KEY below is what every
# stored secret is sealed with. Do not commit it, and back that key up
# somewhere that is not the same backup as the database.
#
`, s.Deployment)
	if w.database {
		w.b.WriteString(`# This controller's settings live in its database, not here: change them on
# the settings page, or with ` + "`zoomies config set`" + ` while it is stopped. What is
# left in this file is what has to be known before the database can be opened,
# and what ` + composeOrDocker(s.Deployment) + ` reads itself. A ZOOMIES_* setting added here would
# override the database, and the settings page would show it as locked.
`)
		return
	}
	w.b.WriteString("# Any of these can also be set in the environment, which wins over this file.\n")
}

func (w *envWriter) section(title string) {
	w.pending = title
}

// envVar is one variable and its value.
type envVar struct{ key, value string }

// set writes one variable with the comment that says what it is for. A
// variable without a comment is a bug, not a style choice, so it is refused.
func (w *envWriter) set(key, value, comment string) {
	if w.err != nil {
		return
	}
	if strings.TrimSpace(comment) == "" {
		w.err = fmt.Errorf("installer: %s would be written without a comment saying what it is for", key)
		return
	}
	if w.keys == nil {
		w.keys = map[string]bool{}
	}
	if w.keys[key] {
		w.err = fmt.Errorf("installer: %s would be written twice, and the second value would silently win", key)
		return
	}
	w.keys[key] = true

	quoted, err := quoteEnvValue(key, value)
	if err != nil {
		w.err = err
		return
	}
	if _, stored := config.SettingForEnv(key); w.database && stored {
		w.settings = append(w.settings, envVar{key, value})
		return
	}
	if w.pending != "" {
		fmt.Fprintf(&w.b, "\n# --- %s %s\n", w.pending, strings.Repeat("-", max(3, 68-len(w.pending))))
		w.pending = ""
	}
	w.b.WriteString("\n")
	for _, line := range wrapComment(comment, 74) {
		w.b.WriteString("# " + line + "\n")
	}
	w.b.WriteString(key + "=" + quoted + "\n")
}

func (w *envWriter) result() (string, error) {
	if w.err != nil {
		return "", w.err
	}
	return w.b.String(), nil
}

// quoteEnvValue renders a value so that both `docker compose` and
// `docker run --env-file` read back exactly what was meant.
//
// Quoting is kept to the minimum on purpose. Compose strips quotes; docker
// run's --env-file does not, and would hand the container a value with the
// quote marks still on it. None of the values Zoomies writes -- URLs, paths,
// numbers, a base64 key, a comma-separated CIDR list -- needs quoting, so a
// value that does is unusual enough to be worth seeing quoted in the file.
//
// A newline is refused outright rather than written: an environment file is
// line-oriented, so a value containing one would end the assignment early and
// silently drop every variable after it.
func quoteEnvValue(key, value string) (string, error) {
	if strings.ContainsAny(value, "\r\n") {
		return "", fmt.Errorf("installer: the value for %s contains a line break, which would truncate the environment file "+
			"and leave every variable after it unset; remove the line break", key)
	}
	if value == "" {
		return "", nil
	}
	if !strings.ContainsAny(value, " \t\"'$#\\`") && value == strings.TrimSpace(value) {
		return value, nil
	}
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, "$", `\$`, "`", "\\`")
	return `"` + r.Replace(value) + `"`, nil
}

// wrapComment breaks a comment onto lines that fit an eighty-column terminal,
// because a comment that needs horizontal scrolling is one nobody reads.
func wrapComment(s string, width int) []string {
	words := strings.Fields(s)
	if len(words) == 0 {
		return nil
	}
	var lines []string
	line := words[0]
	for _, word := range words[1:] {
		if len(line)+1+len(word) > width {
			lines = append(lines, line)
			line = word
			continue
		}
		line += " " + word
	}
	return append(lines, line)
}

// ---------------------------------------------------------------------------
// Reading and writing
// ---------------------------------------------------------------------------

// ParseEnvFile reads an environment file back into a map.
//
// It exists for one job above all: finding the encryption key an earlier run
// wrote, so that a re-run keeps it. It is deliberately forgiving about
// everything else, because the file it reads may well have been edited by
// hand since it was generated.
func ParseEnvFile(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	out, err := ParseEnv(f)
	if err != nil {
		return nil, fmt.Errorf("installer: reading %s: %w", path, err)
	}
	return out, nil
}

// ParseEnv is ParseEnvFile over a stream: what `zoomies config import-env`
// reads a deployment's variables from, when the upgrade hands them over on
// standard input rather than as arguments any process on the host could read.
func ParseEnv(r io.Reader) (map[string]string, error) {
	out := map[string]string{}
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		out[strings.TrimSpace(key)] = unquoteEnvValue(strings.TrimSpace(value))
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// unquoteEnvValue undoes quoteEnvValue, and leaves anything it does not
// recognise exactly as it found it.
func unquoteEnvValue(v string) string {
	if len(v) >= 2 && v[0] == '\'' && v[len(v)-1] == '\'' {
		return v[1 : len(v)-1]
	}
	if len(v) >= 2 && v[0] == '"' && v[len(v)-1] == '"' {
		inner := v[1 : len(v)-1]
		return strings.NewReplacer(`\\`, `\`, `\"`, `"`, `\$`, "$", "\\`", "`").Replace(inner)
	}
	return v
}

// EnvResult reports what WriteEnv did, so the installer can tell the operator
// rather than making them work it out from the directory listing.
type EnvResult struct {
	Path string
	// Backup is where a previous file was copied to, empty when there was
	// none.
	Backup string
	// ReusedKey means an existing encryption key was kept, which is what makes
	// a re-run an upgrade instead of a reinstall that cannot read its own
	// database.
	ReusedKey bool
}

// WriteEnv writes the environment file for a spec, and is safe to run again
// over an installation that already exists.
//
// Three things make it safe. An existing ZOOMIES_ENCRYPTION_KEY is read back
// and kept: minting a new key on an upgrade would leave every stored secret
// undecryptable, which is the worst thing this installer could do to somebody.
// The previous file is copied to .env.bak.<timestamp> before anything is
// overwritten, so an operator's hand edits are recoverable. And the write
// itself goes through a temporary file and a rename, so an interrupted install
// never leaves a half-written file that compose would then read.
func WriteEnv(path string, spec EnvSpec) (EnvResult, error) {
	res := EnvResult{Path: path}

	prior, err := ParseEnvFile(path)
	switch {
	case err == nil:
	case errors.Is(err, os.ErrNotExist):
		prior = nil
	default:
		// An unreadable existing file must stop the run. Carrying on would
		// generate a fresh key and orphan the database this one belongs to.
		return res, fmt.Errorf("installer: %s exists but cannot be read, and overwriting it could orphan the database it belongs to: %w", path, err)
	}

	if existing := strings.TrimSpace(prior["ZOOMIES_ENCRYPTION_KEY"]); existing != "" {
		spec.EncryptionKey = existing
		res.ReusedKey = true
	}
	if spec.EncryptionKey == "" {
		key, err := cryptox.GenerateKey()
		if err != nil {
			return res, fmt.Errorf("installer: generating an encryption key: %w", err)
		}
		spec.EncryptionKey = key.Encode()
	}

	// Render before touching anything: a value this file cannot represent must
	// stop the run while the old file is still exactly as it was.
	body, err := RenderEnv(spec)
	if err != nil {
		return res, err
	}

	if prior != nil {
		backup := path + ".bak." + time.Now().UTC().Format("20060102-150405")
		if err := copyFile(path, backup, 0o600); err != nil {
			return res, fmt.Errorf("installer: keeping a copy of the previous %s: %w", filepath.Base(path), err)
		}
		res.Backup = backup
	}
	// 0600: this file holds the key every stored secret is sealed with.
	if err := writeFileAtomic(path, []byte(body), 0o600); err != nil {
		return res, fmt.Errorf("installer: writing %s: %w", path, err)
	}
	return res, nil
}

// copyFile duplicates a file rather than renaming it, so that at no point does
// the deployment have no environment file at all.
func copyFile(src, dst string, mode os.FileMode) error {
	b, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	return writeFileAtomic(dst, b, mode)
}

