// The last screen of a join has to say what this host became.
//
// It used to say the host name, the log command and "it should be on the Hosts
// page within a heartbeat" -- nothing about which build the agent is, which
// build the controller is, or what the machine measured. All three are answered
// by running the install again with different arguments, and none was visible
// until somebody opened the Hosts page and read a badge, which is how a host
// sat on 0.2-beta reporting no size at all for as long as nobody looked.
func TestReportedSizeSaysWhatTheAgentMeasuredOrThatItCouldNot(t *testing.T) {
	for _, tc := range []struct {
		name string
		in   agent.Reported
		want []string
		not  []string
	}{
		{
			name: "a machine it measured",
			in:   agent.Reported{CPUs: 12, MemoryMB: 31 * 1024, DiskTotalMB: 108 * 1024, DiskFreeMB: 15 * 1024},
			want: []string{"12 vCPU", "31 GB", "15 GB free of 108"},
		},
		{
			// An agent from before the machine package existed sends nothing,
			// and an empty field would read as "nothing to say" when what it
			// means is "this host cannot say".
			name: "an agent too old to measure",
			in:   agent.Reported{},
			want: []string{"not reported"},
			not:  []string{"0 vCPU"},
		},
		{
			name: "cpus but no disk",
			in:   agent.Reported{CPUs: 4, MemoryMB: 8 * 1024},
			want: []string{"4 vCPU", "8 GB"},
			not:  []string{"free of"},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := reportedSize(tc.in)
			for _, w := range tc.want {
				if !strings.Contains(got, w) {
					t.Errorf("reportedSize(%+v) = %q, want it to carry %q", tc.in, got, w)
				}
			}
			for _, n := range tc.not {
				if strings.Contains(got, n) {
					t.Errorf("reportedSize(%+v) = %q, should not carry %q", tc.in, got, n)
				}
			}
		})
	}
}

package installer

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"gopkg.in/yaml.v3"
)

// An upgrade replaces the binary or the image, and a release sometimes needs
// more of the host than the one that was installed: a folder, a mount, a file
// the installer used to write and somebody has since removed. Left to the next
// `zoomies init`, that is a deployment that upgrades cleanly and then quietly
// lacks what the new release expects -- a pool's tool cache that is never
// kept, with nothing to say why.
//
// So an upgrade looks for what this release expects and the deployment does
// not have, says what it would add, and adds it only with the operator's say:
// --yes, or an answer at the terminal. With neither -- a scheduled run, a
// pipeline -- it changes nothing beyond what it always changed, and says what
// is missing and the command that adds it. Nothing on the host changes
// without approval.

// layoutChange is one thing this release expects that the deployment lacks.
type layoutChange struct {
	// what is said to the operator: what would be added, and where.
	what string
	// required marks a change the upgrade cannot go on without. Only a
	// missing Compose file is: there is nothing to bring the new image up
	// with.
	required bool
	apply    func(ctx context.Context) error
}

// layoutChanges is everything this deployment lacks, for what it runs: the
// shared folder and the socket only where it runs runners, the certificate
// only where it serves TLS from files. What it runs is read from its own
// settings -- see deploymentSettings.
func (p *upgradePlan) layoutChanges(ctx context.Context) ([]layoutChange, error) {
	s := p.settings(ctx)
	if !s.read {
		fmt.Fprintf(p.opts.Out, "Could not read this deployment's settings from its database (%s), so the upgrade offers what a host that runs runners needs.\n", s.why)
	}
	switch p.record.Deployment {
	case DeploymentCompose:
		return p.composeLayoutChanges(s)
	case DeploymentDocker:
		return p.dockerLayoutChanges(s), nil
	default:
		return p.nativeLayoutChanges(s), nil
	}
}

// socketGroup is the group that owns the runtime's socket, 0 when it cannot
// be read.
func (p *upgradePlan) socketGroup(path string) int {
	if p.opts.socketGroup != nil {
		return p.opts.socketGroup(path)
	}
	fi, err := os.Stat(path)
	if err != nil {
		return 0
	}
	if _, g, ok := fileOwner(fi); ok && g > 0 {
		return g
	}
	return 0
}

// wantMount is one mount this release gives a container of this deployment.
type wantMount struct {
	// target is the path inside the container; alt is another spelling of
	// it an older Compose file may use, such as ${ZOOMIES_TLS_CERT_FILE}.
	target, alt string
	// bind is what is added: source:target[:mode].
	bind string
	why  string
	// covered marks a mount that any mount of a folder above it already
	// provides: a pool's cache under a folder the operator mounted is seen.
	covered bool
}

// isUnder reports whether p is dir or inside it. Both are paths inside a
// Linux container or on its host, so they are compared with forward slashes
// whatever this upgrade runs on.
func isUnder(p, dir string) bool {
	dir = path.Clean(dir)
	p = path.Clean(p)
	return p == dir || (dir != "/" && strings.HasPrefix(p, dir+"/"))
}

// wantedMounts is every mount the installer would give this deployment
// today, and the group that owns the runtime's socket, 0 when none is needed
// or it could not be read. It is the same decision ComposeFileSpecFor and
// DockerRunSpecFor take at install, taken from the running deployment's
// settings instead of a plan, which is what lets an upgrade find the mounts an
// older release never wrote.
func (p *upgradePlan) wantedMounts(s deploymentSettings) ([]wantMount, int) {
	var out []wantMount
	runs := s.runsRunners(p.record.Mode)
	if runs {
		out = append(out, wantMount{target: SharedHostDir, bind: SharedHostDir + ":" + SharedHostDir,
			why: "the shared folder, where pools keep their tool caches"})
	}
	gid := 0
	if sock := runtimeSocket(s.cfg); runs && s.cfg.Agent.Backend != "process" && sock != "" {
		out = append(out, wantMount{target: sock, bind: sock + ":" + sock,
			why: "the runtime's socket, which the agent creates runner containers on"})
		gid = p.socketGroup(sock)
	}
	if runs {
		// A size-limited pool cache outside the shared folder: the host's
		// daemon mounts it into runners without help, so the cache works --
		// but the agent in this container cannot see the folder, finds
		// nothing to measure, and the limit is never kept. Mounting it at its
		// own path is what makes the limit real.
		for _, dir := range s.cacheDirs {
			if isUnder(dir.path, SharedHostDir) {
				continue
			}
			out = append(out, wantMount{target: dir.path, bind: dir.path + ":" + dir.path, covered: true,
				why: fmt.Sprintf("the cache folder of pool %s, whose size limit the agent keeps by measuring it", strings.Join(dir.pools, ", "))})
		}
	}
	tls := s.cfg.Server.TLS
	if p.record.Mode != ModeAgent && tls.Mode == config.TLSFiles && tls.CertFile != "" && tls.KeyFile != "" {
		out = append(out,
			wantMount{target: tls.CertFile, alt: "${ZOOMIES_TLS_CERT_FILE}", bind: tls.CertFile + ":" + tls.CertFile + ":ro",
				why: "the TLS certificate the controller serves"},
			wantMount{target: tls.KeyFile, alt: "${ZOOMIES_TLS_KEY_FILE}", bind: tls.KeyFile + ":" + tls.KeyFile + ":ro",
				why: "the TLS certificate's key"})
	}
	return out, gid
}

func (p *upgradePlan) composeLayoutChanges(s deploymentSettings) ([]layoutChange, error) {
	var out []layoutChange
	path := p.record.ComposeFile()
	want, gid := p.wantedMounts(s)
	runs := s.runsRunners(p.record.Mode)
	body, err := os.ReadFile(path)
	switch {
	case os.IsNotExist(err):
		spec := composeSpecFor(p.record, s, gid)
		out = append(out, layoutChange{
			what:     "write " + path + " again from this deployment's record and settings; it is missing, and the upgraded container is brought up with it",
			required: true,
			apply: func(context.Context) error {
				rendered, err := RenderComposeFile(spec)
				if err != nil {
					return err
				}
				return writeFileAtomic(path, []byte(rendered), 0o640)
			},
		})
	case err != nil:
		return nil, fmt.Errorf("installer: reading %s: %w", path, err)
	default:
		have, err := composeServiceMounts(body)
		if err != nil {
			return nil, fmt.Errorf("installer: %s is not a Compose file this release can read: %w", path, err)
		}
		var missing []wantMount
		for _, m := range want {
			if !have.mounts(m) {
				missing = append(missing, m)
			}
		}
		group := ""
		if gid > 0 && !have.groups[strconv.Itoa(gid)] && !have.groups["${DOCKER_GID}"] {
			group = strconv.Itoa(gid)
		}
		if len(missing) > 0 || group != "" {
			var items []string
			for _, m := range missing {
				items = append(items, fmt.Sprintf("mount %s (%s)", m.target, m.why))
			}
			if group != "" {
				items = append(items, fmt.Sprintf("add group %s, which owns the runtime's socket, so the image's account can use it", group))
			}
			out = append(out, layoutChange{
				what: fmt.Sprintf("in %s, which an older release wrote: %s; the file is backed up first", path, strings.Join(items, "; ")),
				apply: func(context.Context) error {
					return editComposeFile(path, missing, group)
				},
			})
		}
	}
	if runs {
		out = append(out, p.sharedFolderChanges(SharedHostDir, ImageUID, ImageUID)...)
	}
	return out, nil
}

func (p *upgradePlan) dockerLayoutChanges(s deploymentSettings) []layoutChange {
	var out []layoutChange
	want, gid := p.wantedMounts(s)
	if p.replacement != nil {
		for _, m := range want {
			if p.replacement.HasBind(m.target) || (m.covered && p.replacement.HasBindAbove(m.target)) {
				continue
			}
			bind := m.bind
			out = append(out, layoutChange{
				what: fmt.Sprintf("mount %s in the replacement container (%s)", m.target, m.why),
				apply: func(context.Context) error {
					return p.replacement.AddBind(bind)
				},
			})
		}
		if group := strconv.Itoa(gid); gid > 0 && !p.replacement.HasGroup(group) {
			out = append(out, layoutChange{
				what: fmt.Sprintf("add group %s to the replacement container, which owns the runtime's socket", group),
				apply: func(context.Context) error {
					return p.replacement.AddGroup(group)
				},
			})
		}
	}
	if s.runsRunners(p.record.Mode) {
		out = append(out, p.sharedFolderChanges(SharedHostDir, ImageUID, ImageUID)...)
	}
	return out
}

// nativeLayoutChanges gives the shared folder to whoever owns the state
// directory beside it, which is the account the service runs as.
func (p *upgradePlan) nativeLayoutChanges(s deploymentSettings) []layoutChange {
	if !s.runsRunners(p.record.Mode) {
		return nil
	}
	dir := config.SharedDir()
	uid, gid := -1, -1
	if fi, err := os.Stat(filepath.Dir(dir)); err == nil {
		if u, g, ok := fileOwner(fi); ok {
			uid, gid = u, g
		}
	}
	return p.sharedFolderChanges(dir, uid, gid)
}

// sharedTarget is where the shared folder is and who has to own it.
type sharedTarget struct {
	dir      string
	uid, gid int
}

// sharedFolderChanges is the shared folder and its layout, where any of it is
// missing or the folder belongs to an account that cannot add to it.
func (p *upgradePlan) sharedFolderChanges(dir string, uid, gid int) []layoutChange {
	if s := p.opts.shared; s != nil {
		dir, uid, gid = s.dir, s.uid, s.gid
	}
	problems := SharedDirProblems(dir, uid)
	if len(problems) == 0 {
		return nil
	}
	owner := ""
	if uid >= 0 {
		owner = fmt.Sprintf(", owned by uid %d so Zoomies can add to it", uid)
	}
	return []layoutChange{{
		what: fmt.Sprintf("create %s and the folders in it (%s)%s", dir, strings.Join(problems, "; "), owner),
		apply: func(context.Context) error {
			if _, err := PrepareSharedDir(dir, uid, gid); err != nil {
				return err
			}
			// A folder that is there but belongs to somebody else is given
			// back; PrepareSharedDir leaves an existing one as it is.
			if uid >= 0 {
				if err := os.Lchown(dir, uid, gid); err != nil {
					return fmt.Errorf("installer: giving %s to uid %d: %w", dir, uid, err)
				}
			}
			return nil
		},
	}}
}

// composeSpecFor rebuilds the Compose file's spec from the deployment's record
// and settings, which is everything the installer rendered it from.
func composeSpecFor(rec DeploymentRecord, s deploymentSettings, gid int) ComposeFileSpec {
	mode := rec.Mode
	if mode == "" {
		mode = ModeSingle
	}
	runs := s.runsRunners(mode)
	socket := runtimeSocket(s.cfg)
	mountSocket := runs && s.cfg.Agent.Backend != "process" && socket != ""
	spec := ComposeFileSpec{
		Mode:          mode,
		ContainerPort: ContainerPort,
		Publish:       mode != ModeAgent,
		MountSocket:   mountSocket,
		SocketPath:    socket,
		GroupAdd:      mountSocket && gid > 0,
		Healthcheck:   mode != ModeAgent,
		MountShared:   runs,
		Container:     rec.Container,
		Volume:        rec.Volume,
		Network:       rec.Network,
	}
	if tls := s.cfg.Server.TLS; mode != ModeAgent && tls.Mode == config.TLSFiles {
		spec.TLSCertFile, spec.TLSKeyFile = tls.CertFile, tls.KeyFile
	}
	return spec
}

// runtimeSocket is the socket the deployment's agent creates runners on. An
// empty agent.docker_host is detection, which in a container finds Docker's
// standard socket, the one the installer mounts; Podman's is the user's own
// and is only known when it is set.
func runtimeSocket(cfg *config.Config) string {
	if cfg.Agent.DockerHost == "" && (cfg.Agent.Backend == "" || cfg.Agent.Backend == "docker") {
		return "/var/run/docker.sock"
	}
	return socketPath(cfg.Agent.DockerHost)
}

// serviceMounts is what the zoomies service of a Compose file mounts, by
// target, and the groups it adds.
type serviceMounts struct {
	targets map[string]bool
	groups  map[string]bool
	// samePath are host folders bound at their own path. Only those make a
	// folder inside them the same folder on both sides: a named volume at
	// /var/lib/zoomies hides the host's /var/lib/zoomies/anything.
	samePath map[string]bool
}

func (h serviceMounts) mounts(m wantMount) bool {
	if h.targets[m.target] || (m.alt != "" && h.targets[m.alt]) {
		return true
	}
	if m.covered {
		for dir := range h.samePath {
			if isUnder(m.target, dir) {
				return true
			}
		}
	}
	return false
}

// composeServiceMounts reads the zoomies service's volumes, in either of
// Compose's syntaxes, and its group_add.
func composeServiceMounts(body []byte) (serviceMounts, error) {
	var doc struct {
		Services map[string]struct {
			Volumes  []yaml.Node `yaml:"volumes"`
			GroupAdd []string    `yaml:"group_add"`
		} `yaml:"services"`
	}
	out := serviceMounts{targets: map[string]bool{}, groups: map[string]bool{}, samePath: map[string]bool{}}
	if err := yaml.Unmarshal(body, &doc); err != nil {
		return out, err
	}
	svc, ok := doc.Services["zoomies"]
	if !ok {
		return out, fmt.Errorf("it has no zoomies service")
	}
	for _, v := range svc.Volumes {
		switch v.Kind {
		case yaml.ScalarNode:
			if target, ok := shortMountTarget(v.Value); ok {
				out.targets[target] = true
				if source, _, _ := strings.Cut(v.Value, ":"); source == target && path.IsAbs(source) {
					out.samePath[path.Clean(source)] = true
				}
			}
		case yaml.MappingNode:
			var long struct {
				Type   string `yaml:"type"`
				Source string `yaml:"source"`
				Target string `yaml:"target"`
			}
			if err := v.Decode(&long); err == nil && long.Target != "" {
				out.targets[long.Target] = true
				if long.Type == "bind" && long.Source == long.Target && path.IsAbs(long.Source) {
					out.samePath[path.Clean(long.Source)] = true
				}
			}
		}
	}
	for _, g := range svc.GroupAdd {
		out.groups[strings.TrimSpace(g)] = true
	}
	return out, nil
}

// shortMountTarget is the target of a "source:target[:mode]" volume. A
// ${VARIABLE} source or target is kept as written, which is how a file this
// release wrote names the TLS files.
func shortMountTarget(v string) (string, bool) {
	var parts []string
	depth := 0
	start := 0
	for i, r := range v {
		switch {
		case r == '{':
			depth++
		case r == '}':
			depth--
		case r == ':' && depth == 0:
			parts = append(parts, v[start:i])
			start = i + 1
		}
	}
	parts = append(parts, v[start:])
	if len(parts) < 2 {
		return "", false
	}
	return parts[1], true
}

// editComposeFile adds mounts and a group to the zoomies service, keeping a
// copy of the file as it was. It edits the file rather than writing it again
// from the template: an operator's own additions -- another service, a label,
// a resource limit -- are theirs, and an upgrade that silently dropped them
// would be a worse problem than the one it solved.
func editComposeFile(path string, mounts []wantMount, group string) error {
	body, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	edited, err := addComposeMounts(body, mounts, group)
	if err != nil {
		return err
	}
	backup := fmt.Sprintf("%s.bak.%s", path, time.Now().UTC().Format("20060102T150405Z"))
	if err := os.WriteFile(backup, body, 0o640); err != nil {
		return fmt.Errorf("installer: backing up %s: %w", path, err)
	}
	return writeFileAtomic(path, edited, 0o640)
}

// addComposeMounts is the edit itself, on the parsed document, so that
// comments and every other key survive it.
func addComposeMounts(body []byte, mounts []wantMount, group string) ([]byte, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(body, &root); err != nil {
		return nil, err
	}
	if len(root.Content) == 0 {
		return nil, fmt.Errorf("the Compose file is empty")
	}
	services := mappingValue(root.Content[0], "services")
	svc := mappingValue(services, "zoomies")
	if svc == nil || svc.Kind != yaml.MappingNode {
		return nil, fmt.Errorf("the Compose file has no zoomies service to add to")
	}
	if len(mounts) > 0 {
		volumes := sequenceUnder(svc, "volumes")
		if volumes == nil {
			return nil, fmt.Errorf("the zoomies service's volumes are not a list")
		}
		for _, m := range mounts {
			volumes.Content = append(volumes.Content, &yaml.Node{
				Kind: yaml.ScalarNode, Value: m.bind,
				HeadComment: "Added by zoomies upgrade: " + m.why + ".",
			})
		}
	}
	if group != "" {
		groups := sequenceUnder(svc, "group_add")
		if groups == nil {
			return nil, fmt.Errorf("the zoomies service's group_add is not a list")
		}
		groups.Content = append(groups.Content, &yaml.Node{
			Kind: yaml.ScalarNode, Value: group, Style: yaml.DoubleQuotedStyle,
			HeadComment: "Added by zoomies upgrade: the group that owns the runtime's socket.",
		})
	}
	var out bytes.Buffer
	enc := yaml.NewEncoder(&out)
	enc.SetIndent(2)
	if err := enc.Encode(&root); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// sequenceUnder is the list under key in a mapping, created empty when the
// key is missing, or nil when the key holds something other than a list.
func sequenceUnder(m *yaml.Node, key string) *yaml.Node {
	v := mappingValue(m, key)
	if v == nil {
		m.Content = append(m.Content,
			&yaml.Node{Kind: yaml.ScalarNode, Value: key},
			&yaml.Node{Kind: yaml.SequenceNode})
		return m.Content[len(m.Content)-1]
	}
	if v.Kind != yaml.SequenceNode {
		return nil
	}
	return v
}

// mappingValue is the value under key in a mapping node, or nil.
func mappingValue(m *yaml.Node, key string) *yaml.Node {
	if m == nil || m.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(m.Content); i += 2 {
		if m.Content[i].Value == key {
			return m.Content[i+1]
		}
	}
	return nil
}

package installer

import (
	"bytes"
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// controllerFixture is a Compose controller deployment whose data volume holds
// a database with the given settings, and whose Compose file an older release
// wrote: no shared folder, no socket, no group.
func controllerFixture(t *testing.T, settings map[string]string) (UpgradeOptions, DeploymentRecord, string) {
	t.Helper()
	opts, rec := upgradeFixture(t, DeploymentCompose)
	rec.Mode = ModeController
	opts.Mode = ModeController
	if _, err := WriteDeploymentRecord(opts.ConfigDir, rec); err != nil {
		t.Fatal(err)
	}
	volume := filepath.Join(t.TempDir(), "volume")
	if err := os.MkdirAll(volume, 0o700); err != nil {
		t.Fatal(err)
	}
	st, err := store.Open(context.Background(), store.Options{Path: filepath.Join(volume, "zoomies.db")})
	if err != nil {
		t.Fatal(err)
	}
	var rows []store.InstanceSetting
	for k, v := range settings {
		rows = append(rows, store.InstanceSetting{Key: k, Value: v})
	}
	if len(rows) > 0 {
		if err := st.PutInstanceSettings(context.Background(), "test", rows); err != nil {
			t.Fatal(err)
		}
	}
	_ = st.Close()

	old := "services:\n  zoomies:\n    image: ${ZOOMIES_IMAGE}\n    volumes:\n      - zoomies-data:/var/lib/zoomies\n    # an operator's own note\n    labels:\n      team: platform\n"
	if err := os.WriteFile(rec.ComposeFile(), []byte(old), 0o640); err != nil {
		t.Fatal(err)
	}
	opts.shared.dir = filepath.Join(t.TempDir(), "shared")
	return opts, rec, volume
}

// fakeVolume answers the question where the container's data is mounted
// from with the fixture's volume, and everything else as a healthy host
// would.
func fakeVolume(opts *UpgradeOptions, volume string, inspectErr error) {
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		switch {
		case strings.Contains(line, "inspect --type container --format"):
			return volume, inspectErr
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
}

// Whether a controller runs runners is a setting, and settings are kept in the
// database -- the settings page writes nowhere else. So the upgrade asks the
// deployment's database, and a controller whose embedded agent was turned off
// there is not offered a runner host's folder and mounts.
func TestTheDatabaseDecidesWhatAControllerIsOffered(t *testing.T) {
	for _, tc := range []struct {
		name     string
		settings map[string]string
		offered  bool
	}{
		{"embedded agent turned off on the settings page", map[string]string{"agent.embedded": "false"}, false},
		{"embedded agent turned on", map[string]string{"agent.embedded": "true"}, true},
		{"never set, so the default: on", nil, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			opts, _, volume := controllerFixture(t, tc.settings)
			fakeVolume(&opts, volume, nil)
			opts.socketGroup = func(string) int { return 998 }
			var out bytes.Buffer
			opts.Out, opts.Check = &out, true
			if err := Upgrade(context.Background(), opts); err != nil {
				t.Fatal(err)
			}
			got := strings.Contains(out.String(), "mount "+SharedHostDir)
			if got != tc.offered {
				t.Errorf("shared folder offered = %v, want %v:\n%s", got, tc.offered, out.String())
			}
			if strings.Contains(out.String(), "Could not read") {
				t.Errorf("the database was there to read:\n%s", out.String())
			}
		})
	}
}

// An older Compose file can lack more than the shared folder: the socket and
// its group were once optional too. Every mount this release would write for
// the host is offered, in one edit with one backup.
func TestAnOldComposeFileIsGivenEveryMountItLacks(t *testing.T) {
	opts, rec, volume := controllerFixture(t, map[string]string{"agent.embedded": "true"})
	fakeVolume(&opts, volume, nil)
	opts.socketGroup = func(string) int { return 998 }
	var out bytes.Buffer
	opts.Out, opts.AssumeYes = &out, true
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	body, err := os.ReadFile(rec.ComposeFile())
	if err != nil {
		t.Fatal(err)
	}
	have, err := composeServiceMounts(body)
	if err != nil {
		t.Fatal(err)
	}
	for _, target := range []string{SharedHostDir, "/var/run/docker.sock", "/var/lib/zoomies"} {
		if !have.targets[target] {
			t.Errorf("%s is not mounted after the upgrade:\n%s", target, body)
		}
	}
	if !have.groups["998"] {
		t.Errorf("the socket's group was not added:\n%s", body)
	}
	for _, keep := range []string{"an operator's own note", "team: platform", "${ZOOMIES_IMAGE}"} {
		if !strings.Contains(string(body), keep) {
			t.Errorf("the edit lost %q:\n%s", keep, body)
		}
	}
	if backups, _ := filepath.Glob(rec.ComposeFile() + ".bak.*"); len(backups) != 1 {
		t.Errorf("backups = %v, want one", backups)
	}
}

// Docker Desktop keeps volumes in its own VM, and a volume can be anywhere a
// daemon puts it. When the database cannot be read the upgrade says so and
// offers what a host that runs runners needs: a question too many costs a
// controller nothing, a mount too few breaks a runner host's tool cache.
func TestAnUnreadableDatabaseOffersWhatARunnerHostNeeds(t *testing.T) {
	opts, _, _ := controllerFixture(t, map[string]string{"agent.embedded": "false"})
	fakeVolume(&opts, "", errors.New("no such volume"))
	opts.socketGroup = func(string) int { return 0 }
	var out bytes.Buffer
	opts.Out, opts.Check = &out, true
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "Could not read this deployment's settings") || !strings.Contains(out.String(), "mount "+SharedHostDir) {
		t.Errorf("output:\n%s", out.String())
	}
}

// A pool cache with a size limit is kept under it by the agent, which has to
// see the folder to measure it. Under Compose a host folder outside the shared
// folder is mounted into runners by the host's daemon but not into the
// controller's own container -- the cache works, and the limit quietly never
// does. The upgrade mounts each such folder at its own path, and leaves alone
// the ones the container can already see.
func TestAnUpgradeMountsTheCacheFoldersWhoseSizeLimitTheAgentKeeps(t *testing.T) {
	opts, rec, volume := controllerFixture(t, map[string]string{"agent.embedded": "true"})
	st, err := store.Open(context.Background(), store.Options{Path: filepath.Join(volume, "zoomies.db")})
	if err != nil {
		t.Fatal(err)
	}
	inst := &store.Installation{AppID: 1, InstallationID: 1, Target: "acme", TargetType: store.TargetOrg}
	if err := st.CreateInstallation(context.Background(), inst); err != nil {
		t.Fatal(err)
	}
	for _, pool := range []struct {
		name, source string
		limit        int64
	}{
		{"limited", "/srv/zoomies-cache", 10 << 30},
		{"limited-too", "/srv/zoomies-cache/", 5 << 30},           // the same folder, spelt differently
		{"unlimited", "/srv/unlimited-cache", 0},                  // no limit: nothing to measure
		{"shared", SharedHostDir + "/cache/pools", 10 << 30},      // already mounted
		{"under-a-volume", "/var/lib/zoomies/elsewhere", 1 << 30}, // a named volume at /var/lib/zoomies hides the host's folder
		{"under-a-bind", "/srv/mounted/cache", 1 << 30},           // under a folder bound at its own path
		{"volume", "zoomies-cache", 0},
	} {
		p := &store.Pool{Name: pool.name, InstallationID: inst.ID, Backend: "docker", DockerMode: "none", Labels: store.StringSlice{pool.name},
			Cache: store.CacheConfig{Enabled: true, Scope: store.CacheScopePool, Source: pool.source, SizeLimit: pool.limit}}
		if err := st.CreatePool(context.Background(), p); err != nil {
			t.Fatalf("pool %s: %v", pool.name, err)
		}
	}
	_ = st.Close()

	compose, err := os.ReadFile(rec.ComposeFile())
	if err != nil {
		t.Fatal(err)
	}
	compose = []byte(strings.Replace(string(compose), "      - zoomies-data:/var/lib/zoomies\n", "      - zoomies-data:/var/lib/zoomies\n      - /srv/mounted:/srv/mounted\n", 1))
	if err := os.WriteFile(rec.ComposeFile(), compose, 0o640); err != nil {
		t.Fatal(err)
	}
	fakeVolume(&opts, volume, nil)
	opts.socketGroup = func(string) int { return 998 }
	var out bytes.Buffer
	opts.Out, opts.AssumeYes = &out, true
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "pool zoomies-limited, zoomies-limited-too") {
		t.Errorf("the upgrade did not say which pools the cache mount is for:\n%s", out.String())
	}
	body, err := os.ReadFile(rec.ComposeFile())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Count(string(body), "/srv/zoomies-cache:/srv/zoomies-cache") != 1 {
		t.Errorf("the size-limited cache folder is not mounted exactly once:\n%s", body)
	}
	if !strings.Contains(string(body), "/var/lib/zoomies/elsewhere:/var/lib/zoomies/elsewhere") {
		t.Errorf("a folder hidden by the data volume was not mounted:\n%s", body)
	}
	for _, absent := range []string{"/srv/unlimited-cache", "/cache/pools:", "/srv/mounted/cache"} {
		if strings.Contains(string(body), absent) {
			t.Errorf("%s was mounted, but the container can already see it or it has no limit:\n%s", absent, body)
		}
	}
}

package installer

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// mountsShared reports whether a Compose file's zoomies service mounts the
// shared folder.
func mountsShared(body []byte) (bool, error) {
	m, err := composeServiceMounts(body)
	return m.targets[SharedHostDir], err
}

var sharedWant = wantMount{target: SharedHostDir, bind: SharedHostDir + ":" + SharedHostDir, why: "the shared folder"}

func addShared(body []byte) ([]byte, error) {
	return addComposeMounts(body, []wantMount{sharedWant}, "")
}

// fakeDeploymentCommands answers the commands a compose upgrade runs as a
// healthy host would, and records them.
func fakeDeploymentCommands(opts *UpgradeOptions, calls *[]string) {
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		*calls = append(*calls, line)
		switch {
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
}

// withoutSharedMount rewrites the fixture's Compose file as a release before
// the shared folder wrote it, and empties the shared folder.
func withoutSharedMount(t *testing.T, opts *UpgradeOptions, rec DeploymentRecord) string {
	t.Helper()
	body, err := os.ReadFile(rec.ComposeFile())
	if err != nil {
		t.Fatal(err)
	}
	var kept []string
	for _, line := range strings.Split(string(body), "\n") {
		if !strings.Contains(line, SharedHostDir) {
			kept = append(kept, line)
		}
	}
	old := strings.Join(kept, "\n") + "\n# an operator's own note, kept by any edit\n"
	if err := os.WriteFile(rec.ComposeFile(), []byte(old), 0o640); err != nil {
		t.Fatal(err)
	}
	if mounted, err := mountsShared([]byte(old)); err != nil || mounted {
		t.Fatalf("the older file still mounts the shared folder (%v, %v):\n%s", mounted, err, old)
	}
	opts.shared.dir = filepath.Join(t.TempDir(), "shared")
	return old
}

func TestComposeMountsSharedReadsBothVolumeSyntaxes(t *testing.T) {
	for _, tc := range []struct {
		name string
		body string
		want bool
	}{
		{"short", "services:\n  zoomies:\n    volumes:\n      - /var/lib/zoomies/shared:/var/lib/zoomies/shared\n", true},
		{"short with a mode", "services:\n  zoomies:\n    volumes:\n      - /var/lib/zoomies/shared:/var/lib/zoomies/shared:rw\n", true},
		{"long", "services:\n  zoomies:\n    volumes:\n      - type: bind\n        source: /srv/shared\n        target: /var/lib/zoomies/shared\n", true},
		{"elsewhere", "services:\n  zoomies:\n    volumes:\n      - /var/lib/zoomies/shared:/shared\n", false},
		{"absent", "services:\n  zoomies:\n    image: zoomies\n", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := mountsShared([]byte(tc.body))
			if err != nil || got != tc.want {
				t.Fatalf("composeMountsShared = %v, %v; want %v", got, err, tc.want)
			}
		})
	}
	if _, err := mountsShared([]byte("services:\n  other: {}\n")); err == nil {
		t.Error("a file with no zoomies service was read as one without the mount")
	}
}

// The Compose file is the operator's as much as the installer's. Adding the
// mount by writing the file again from the template would drop a service or a
// label they added; the edit has to leave everything else where it was.
func TestAddingTheSharedMountKeepsTheRestOfTheComposeFile(t *testing.T) {
	body := `# written by zoomies init
services:
  zoomies:
    image: ${ZOOMIES_IMAGE}
    labels:
      team: platform # who to ask
    volumes:
      - zoomies-data:/var/lib/zoomies
  sidecar:
    image: example/sidecar
volumes:
  zoomies-data: {}
`
	edited, err := addShared([]byte(body))
	if err != nil {
		t.Fatal(err)
	}
	if mounted, err := mountsShared(edited); err != nil || !mounted {
		t.Fatalf("the edited file does not mount the shared folder (%v):\n%s", err, edited)
	}
	for _, keep := range []string{"# written by zoomies init", "team: platform # who to ask", "zoomies-data:/var/lib/zoomies", "example/sidecar", "${ZOOMIES_IMAGE}", "Added by zoomies upgrade"} {
		if !strings.Contains(string(edited), keep) {
			t.Errorf("the edit lost %q:\n%s", keep, edited)
		}
	}

	// A service with no volumes at all gets the list as well as the entry.
	edited, err = addShared([]byte("services:\n  zoomies:\n    image: zoomies\n"))
	if err != nil {
		t.Fatal(err)
	}
	if mounted, _ := mountsShared(edited); !mounted {
		t.Fatalf("no volumes list was added:\n%s", edited)
	}
}

// Nothing on the host changes without the operator's say, and each way of
// giving or withholding it lands where it should.
func TestAnUpgradeAddsTheSharedMountOnlyWithApproval(t *testing.T) {
	for _, tc := range []struct {
		name    string
		yes     bool
		tty     bool
		answer  string
		applied bool
		says    string
	}{
		{name: "--yes", yes: true, applied: true, says: "Added"},
		{name: "enter at the terminal", tty: true, answer: "\n", applied: true, says: "Add them now?"},
		{name: "yes at the terminal", tty: true, answer: "yes\n", applied: true, says: "Add them now?"},
		{name: "no at the terminal", tty: true, answer: "n\n", says: "zoomies upgrade --yes"},
		{name: "nobody at the terminal", tty: true, answer: "", says: "zoomies upgrade --yes"},
		{name: "unattended", says: "zoomies upgrade --yes"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			opts, rec := upgradeFixture(t, DeploymentCompose)
			old := withoutSharedMount(t, &opts, rec)
			var out bytes.Buffer
			var calls []string
			opts.Out = &out
			opts.AssumeYes = tc.yes
			opts.Interactive = tc.tty
			opts.In = strings.NewReader(tc.answer)
			fakeDeploymentCommands(&opts, &calls)

			// Declining is not a failure: the upgrade goes on, as it
			// always did, without what it offered.
			if err := Upgrade(context.Background(), opts); err != nil {
				t.Fatal(err)
			}
			if !strings.Contains(out.String(), SharedHostDir) || !strings.Contains(out.String(), tc.says) {
				t.Errorf("output does not say %q about %s:\n%s", tc.says, SharedHostDir, out.String())
			}
			now, _ := os.ReadFile(rec.ComposeFile())
			backups, _ := filepath.Glob(rec.ComposeFile() + ".bak.*")
			_, folderErr := os.Stat(filepath.Join(opts.shared.dir, "cache", "tools"))
			if !tc.applied {
				if string(now) != old || len(backups) != 0 || folderErr == nil {
					t.Fatalf("changed the host without approval: backups %v, folder %v, file:\n%s", backups, folderErr, now)
				}
				return
			}
			if mounted, _ := mountsShared(now); !mounted {
				t.Errorf("the Compose file was not given the mount:\n%s", now)
			}
			if !strings.Contains(string(now), "an operator's own note") {
				t.Error("the edit dropped the operator's comment")
			}
			if len(backups) != 1 {
				t.Fatalf("backups = %v, want the file as it was kept once", backups)
			}
			if kept, _ := os.ReadFile(backups[0]); string(kept) != old {
				t.Error("the backup is not the file as it was")
			}
			if folderErr != nil {
				t.Errorf("the shared folder's layout was not created: %v", folderErr)
			}
			if !strings.Contains(strings.Join(calls, "\n"), " up ") {
				t.Error("the upgrade did not go on after adding the mount")
			}
		})
	}
}

// A deleted docker-compose.yml leaves nothing to bring the new image up with,
// so an upgrade that cannot write it again stops before it pulls anything --
// and one that may, writes it from what the deployment recorded.
func TestAMissingComposeFileIsWrittenAgainOrStopsTheUpgrade(t *testing.T) {
	for _, yes := range []bool{false, true} {
		t.Run(map[bool]string{false: "unattended", true: "--yes"}[yes], func(t *testing.T) {
			opts, rec := upgradeFixture(t, DeploymentCompose)
			if err := os.Remove(rec.ComposeFile()); err != nil {
				t.Fatal(err)
			}
			var calls []string
			var out bytes.Buffer
			opts.Out = &out
			opts.AssumeYes = yes
			fakeDeploymentCommands(&opts, &calls)

			err := Upgrade(context.Background(), opts)
			if !yes {
				if err == nil || !strings.Contains(err.Error(), "zoomies upgrade --yes") {
					t.Fatalf("err = %v, want one naming zoomies upgrade --yes", err)
				}
				for _, c := range calls {
					// Reading where the data is changes nothing.
					if !strings.Contains(c, " inspect ") {
						t.Fatalf("a stopped upgrade ran %v", calls)
					}
				}
				if _, err := os.Stat(rec.ComposeFile()); !os.IsNotExist(err) {
					t.Error("the file was written without approval")
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			body, err := os.ReadFile(rec.ComposeFile())
			if err != nil {
				t.Fatal(err)
			}
			if mounted, _ := mountsShared(body); !mounted {
				t.Errorf("the file written again does not mount the shared folder:\n%s", body)
			}
		})
	}
}

// install.sh checks before it replaces the binary, so an unattended upgrade
// that is bound to stop for a missing Compose file has to stop at the check,
// with the old binary still in place.
func TestAnUnattendedCheckRefusesWhatTheRealRunCouldNotFinish(t *testing.T) {
	opts, rec := upgradeFixture(t, DeploymentCompose)
	if err := os.Remove(rec.ComposeFile()); err != nil {
		t.Fatal(err)
	}
	var calls []string
	fakeDeploymentCommands(&opts, &calls)
	opts.Check = true
	opts.NonInteractive = true
	if err := Upgrade(context.Background(), opts); err == nil || !strings.Contains(err.Error(), "zoomies upgrade --yes") {
		t.Fatalf("unattended check = %v, want a refusal naming zoomies upgrade --yes", err)
	}
	opts.AssumeYes = true
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatalf("a check with --yes refused: %v", err)
	}
	if _, err := os.Stat(rec.ComposeFile()); !os.IsNotExist(err) {
		t.Error("a check wrote the Compose file")
	}
}

// --check is what install.sh runs before it replaces the binary. It says what
// the upgrade will offer and changes none of it.
func TestAnUpgradeCheckReportsWhatIsMissingAndChangesNothing(t *testing.T) {
	opts, rec := upgradeFixture(t, DeploymentCompose)
	old := withoutSharedMount(t, &opts, rec)
	var calls []string
	var out bytes.Buffer
	opts.Out = &out
	opts.Check = true
	opts.AssumeYes = true
	fakeDeploymentCommands(&opts, &calls)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "will offer") || !strings.Contains(out.String(), SharedHostDir) {
		t.Errorf("the check did not say what it would offer:\n%s", out.String())
	}
	if now, _ := os.ReadFile(rec.ComposeFile()); string(now) != old {
		t.Error("the check edited the Compose file")
	}
	if _, err := os.Stat(opts.shared.dir); !os.IsNotExist(err) {
		t.Error("the check created the shared folder")
	}
}

func TestANativeUpgradeCreatesTheSharedFolderWithApproval(t *testing.T) {
	requirePOSIX(t)
	shared := filepath.Join(t.TempDir(), "shared")
	opts := UpgradeOptions{ConfigDir: t.TempDir(), Mode: ModeAgent, BinaryPath: "/custom/bin/zoomies", AssumeYes: true,
