	if _, err := storeInstallation(ctx, st, nil, installationInput{Target: "acme"}); err == nil {
		t.Fatal("without a key the private key cannot be sealed, and that must be an error")
	}
}

// The manifest the installer sends is the security boundary of the whole
// integration, so it is checked here rather than trusted.
func TestManifestAsksForTheLeastItCan(t *testing.T) {
	raw, err := github.Manifest(github.ManifestOptions{
		Name:         "zoomies-acme",
		URL:          "https://zoomies.example.com",
		WebhookURL:   "https://zoomies.example.com/webhooks/github",
		Organization: "acme",
		SetupURL:     "http://127.0.0.1:4321/callback",
	})
	if err != nil {
		t.Fatalf("Manifest: %v", err)
	}
	var m struct {
		DefaultEvents      []string          `json:"default_events"`
		DefaultPermissions map[string]string `json:"default_permissions"`
		Public             bool              `json:"public"`
	}
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if len(m.DefaultEvents) != 1 || m.DefaultEvents[0] != "workflow_job" {
		t.Errorf("events = %v, want only workflow_job", m.DefaultEvents)
	}
	if m.Public {
		t.Error("a fleet controller's App has no business being installable by strangers")
	}
	if m.DefaultPermissions["organization_self_hosted_runners"] != "write" {
		t.Errorf("an org App needs the runner permission: %v", m.DefaultPermissions)
	}
}

// TestTheAppSetupURLOutlivesTheHandshake pins the split between the two
// addresses GitHub is given.
//
// setup_url is permanent App configuration: GitHub sends the operator there
// after every future install or reconfiguration -- adding a repository to the
// installation, most often, long after setup finished. It used to be the
// installer's temporary callback listener, so every App `zoomies init` created
// pointed its operator at a loopback port that stopped existing minutes later.
func TestTheAppSetupURLOutlivesTheHandshake(t *testing.T) {
	srv, err := newCallbackServer()
	if err != nil {
		t.Fatalf("newCallbackServer: %v", err)
	}
	defer srv.Close()

	raw, err := github.Manifest(github.ManifestOptions{
		Name:        "zoomies-acme",
		URL:         "https://zoomies.example.com",
		WebhookURL:  "https://zoomies.example.com/webhooks/github",
		SetupURL:    "https://zoomies.example.com/settings/github/setup",
		RedirectURL: srv.CallbackURL(),
	})
	if err != nil {
		t.Fatalf("Manifest: %v", err)
	}

	var got struct {
		RedirectURL string `json:"redirect_url"`
		SetupURL    string `json:"setup_url"`
	}
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatalf("unmarshalling the manifest: %v", err)
	}
	if got.SetupURL != "https://zoomies.example.com/settings/github/setup" {
		t.Errorf("setup_url = %q, want the controller's own durable route", got.SetupURL)
	}
	if strings.Contains(got.SetupURL, "127.0.0.1") || strings.Contains(got.SetupURL, "localhost") {
		t.Errorf("setup_url must never be a loopback address, got %q", got.SetupURL)
	}
	if got.RedirectURL != srv.CallbackURL() {
		t.Errorf("redirect_url = %q, want this handshake's listener %q", got.RedirectURL, srv.CallbackURL())
	}
}

// A code with no state at all must be refused, not waved through.
//
// The guard used to run only when a state was present, so omitting it skipped
// the check rather than failing it. That matters more than it looks: this
// listener is on loopback, which keeps the network out but not the browser --
// any page the operator has open can navigate to a guessed port on 127.0.0.1,
// and it does not need to read the reply for the code to land. Exchanged, a
// code yields the App's client secret, private key and webhook secret, so an
// operator finishing setup could be handed somebody else's App, and nothing
// about the run would look wrong.
func TestCallbackServerRefusesACodeWithNoState(t *testing.T) {
	c, srv := newTestCallbackServer(t)

	resp, err := srv.Client().Get(srv.URL + "/callback?code=attacker-code")
	if err != nil {
		t.Fatalf("callback: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400: a code with no state was accepted", resp.StatusCode)
	}

	// Nothing may reach the waiter, or the exchange happens anyway.
	select {
	case res := <-c.results:
		t.Fatalf("the code reached the installer: %+v", res)
	default:
	}
	select {
	case <-c.stateErrs:
	default:
		t.Error("the refusal was not reported, so the operator would see a timeout instead")
	}
}

// A name that resolves to 127.0.0.1 reaches this listener however loopback it
// is bound, and the address check cannot see the difference. The Host header
// can: a rebound name arrives under its own name, not under the address the
// installer told the operator to open.
func TestCallbackServerRefusesAReboundHost(t *testing.T) {
	_, srv := newTestCallbackServer(t)

	req, err := http.NewRequest(http.MethodGet, srv.URL+"/callback?installation_id=987654", nil)
	if err != nil {
		t.Fatalf("request: %v", err)
	}
	req.Host = "setup.attacker.example"

	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatalf("callback: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400: a rebound host was served", resp.StatusCode)
	}
}

// Stopping the handshake has to stop the reader, even though the install
// carries on.
//
// The paste reader takes the same stdin every later prompt takes. Started on
// the install's own context it kept scanning for the whole run, so the operator
// typing their administrator password was typing into a terminal with two
// readers on it -- and on the `curl | sh` path that password is the first thing
// they type after the handshake.
func TestThePasteReaderStopsWhenTheHandshakeDoesNotWhenTheInstallDoes(t *testing.T) {
	install, cancelInstall := context.WithCancel(context.Background())
	defer cancelInstall()

	i := &Installer{in: strings.NewReader("pasted-code\nthe-operators-password\n")}
	paste, stopPaste := i.pasteReader(install)

	if got := <-paste; got != "pasted-code" {
		t.Fatalf("first line = %q, want the pasted code", got)
	}

	// The handshake is over. The install is not.
	stopPaste()
	if install.Err() != nil {
		t.Fatalf("stopping the handshake cancelled the whole install: %v", install.Err())
	}

	// The reader must be finished with stdin: the channel closes and the line
	// after the paste is never taken.
	select {
	case line, open := <-paste:
		if open {
			t.Fatalf("the reader took %q after the handshake ended; that is the operator's next answer", line)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("the reader is still on stdin after the handshake ended")
	}
}

package installer

import (
	"context"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/charmbracelet/huh"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// unattendedInstaller is the installer these tests want: no terminal, no
// host detection worth speaking of, and nowhere for its output to go.
func unattendedInstaller(t *testing.T, opts Options) *Installer {
	t.Helper()
	i, _ := newTestInstaller(t, Detection{OS: "linux", Arch: "amd64"}, opts)
	return i
}

// An operator who says where the configuration and state go is obeyed. The
// overrides exist so a test -- and an operator packaging Zoomies somewhere
// unusual -- never writes to the platform default by accident.
func TestExplicitDirectoriesWinOverThePlatformDefaults(t *testing.T) {
	opts := Options{ConfigDir: t.TempDir(), StateDir: t.TempDir()}
	if got := opts.configDir(); got != opts.ConfigDir {
		t.Errorf("configDir() = %q, want the override %q", got, opts.ConfigDir)
	}
	if got := opts.stateDir(); got != opts.StateDir {
		t.Errorf("stateDir() = %q, want the override %q", got, opts.StateDir)
	}

	// With no override the platform's own answer is used, whatever it is on
	// the host running this test.
	bare := Options{}
	if got, want := bare.configDir(), config.ConfigDir(); got != want {
		t.Errorf("configDir() = %q, want the platform default %q", got, want)
	}
	if got, want := bare.stateDir(), config.StateDir(); got != want {
		t.Errorf("stateDir() = %q, want the platform default %q", got, want)
	}
}

// The unit file names a binary, so the path has to be one that still exists
// after the installer exits -- never the temporary copy install.sh ran.
func TestTheInstalledBinaryPathIsTakenFromTheScriptWhenItSaysSo(t *testing.T) {
	opts := Options{InstalledBinary: "/opt/zoomies/bin/zoomies"}
	if got := opts.binaryPath(); got != opts.InstalledBinary {
		t.Errorf("binaryPath() = %q, want %q", got, opts.InstalledBinary)
	}

	// Without one it falls back to this process, resolved through any
	// symlink: a unit pointing at /usr/local/bin/zoomies -> ../releases/x
	// would otherwise break the next time that link moved.
	got := (Options{}).binaryPath()
	if got == "" || !filepath.IsAbs(got) {
		t.Fatalf("binaryPath() = %q, want an absolute path to fall back on", got)
	}
	if resolved, err := filepath.EvalSymlinks(got); err == nil && resolved != got {
		t.Errorf("binaryPath() = %q, want the symlink resolved to %q", got, resolved)
	}
}

// A run with nobody watching must not prompt, whatever the terminal says.
func TestANonInteractiveRunNeverPrompts(t *testing.T) {
	if (Options{NonInteractive: true}).interactive() {
		t.Error("a run told not to prompt reported itself interactive")
	}
	if isTerminal(nil) {
		t.Error("a missing file was called a terminal")
	}
	// A file that is not a character device is not a terminal, on any
	// platform: install.sh reconnects /dev/tty when the script was piped into
	// sh, so a false here really does mean nobody is watching.
	dir, err := os.Open(t.TempDir())
	if err != nil {
		t.Fatalf("opening a directory: %v", err)
	}
	defer func() { _ = dir.Close() }()
	if isTerminal(dir) {
		t.Error("a directory was called a terminal")
	}
}

// What is being installed is settled without asking when the answer is
// already there, and the order matters: install.sh's --mode is the operator
// typing at the shell, so it wins over a file they wrote weeks ago.
func TestTheModeComesFromTheFlagThenTheAnswerFileThenTheDefault(t *testing.T) {
	answers := filepath.Join(t.TempDir(), "answers.yaml")
	if err := os.WriteFile(answers, []byte("mode: controller\n"), 0o600); err != nil {
		t.Fatalf("writing answers: %v", err)
	}

	cases := []struct {
		name string
		opts Options
		want Mode
	}{
		{"the flag wins", Options{Mode: ModeAgent, AnswersFile: answers}, ModeAgent},
		{"then the answer file", Options{AnswersFile: answers}, ModeController},
		{"and a run with nothing to go on installs the usual single host", Options{}, ModeSingle},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := unattendedInstaller(t, tc.opts).resolveMode(context.Background())
			if err != nil {
				t.Fatalf("resolveMode: %v", err)
			}
			if got != tc.want {
				t.Errorf("resolveMode() = %q, want %q", got, tc.want)
			}
		})
	}
}

// A typo in the answer file stops the run with the word that was not
// understood, rather than installing something the operator did not ask for.
func TestAnUnknownModeInTheAnswerFileIsRefusedByName(t *testing.T) {
	answers := filepath.Join(t.TempDir(), "answers.yaml")
	if err := os.WriteFile(answers, []byte("mode: controler\n"), 0o600); err != nil {
		t.Fatalf("writing answers: %v", err)
	}
	_, err := unattendedInstaller(t, Options{AnswersFile: answers}).resolveMode(context.Background())
	if err == nil {
		t.Fatal("a misspelled mode was accepted")
	}
	if !strings.Contains(err.Error(), "controler") {
		t.Errorf("error = %q, want it to name the word it could not read", err)
	}
}

// Every listener the plan can hold is one the operator was offered. A choice
// missing from the menu is a setting reachable only from an answer file, and
// an option whose apply does something else is a lie told at the prompt.
func TestEveryListenerChoiceIsOfferedAndDoesWhatItsRowSays(t *testing.T) {
	opts := listenOptions()
	for _, c := range []ListenChoice{ListenLoopback, ListenTLSFiles, ListenSelfSigned, ListenProxy, ListenCloudflare} {
		if !slices.ContainsFunc(opts, func(o listenOption) bool { return o.Choice == c }) {
			t.Errorf("%q is a listener the plan can hold but the operator is never offered", c)
		}
	}

	for _, o := range opts {
		t.Run(string(o.Choice), func(t *testing.T) {
			if strings.TrimSpace(o.Label) == "" || strings.TrimSpace(o.Description) == "" {
				t.Fatalf("%q is offered with nothing to read: label %q, description %q", o.Choice, o.Label, o.Description)
			}
			p := Plan{}
			o.Choice.apply(&p, 8443, "build-01")
			if p.Listen != o.Choice {
				t.Errorf("applying %q left the plan on %q", o.Choice, p.Listen)
			}
			if !strings.HasSuffix(p.Bind, ":8443") {
				t.Errorf("bind = %q, want the port the operator chose", p.Bind)
			}
			loopback := strings.HasPrefix(p.Bind, "127.0.0.1:")
			if (o.Choice == ListenLoopback) != loopback {
				t.Errorf("bind = %q for %q; only the loopback choice keeps it off every other interface", p.Bind, o.Choice)
			}
			// The two choices that terminate TLS here are the two that say so.
			wantTLS := o.Choice == ListenTLSFiles || o.Choice == ListenSelfSigned
			if gotTLS := p.TLSMode != config.TLSOff; gotTLS != wantTLS {
				t.Errorf("TLS mode = %q for %q, want TLS terminated here = %v", p.TLSMode, o.Choice, wantTLS)
			}
		})
	}
}

// Cloudflare's edge ranges are trusted for the operator who picks it, because
// a proxy nobody trusts records its own address in every audit entry.
func TestPickingCloudflareTrustsItsEdgeRanges(t *testing.T) {
	p := Plan{}
	ListenCloudflare.apply(&p, 8080, "build-01")
	if !slices.Contains(p.TrustedProxies, config.TrustedProxyCloudflare) {
		t.Errorf("trusted proxies = %v, want %q among them", p.TrustedProxies, config.TrustedProxyCloudflare)
	}

	// And picking the generic proxy does not: those ranges belong to somebody
	// else's network, and trusting them there would let a client spoof its
	// own address.
	plain := Plan{}
	ListenProxy.apply(&plain, 8080, "build-01")
	if slices.Contains(plain.TrustedProxies, config.TrustedProxyCloudflare) {
		t.Errorf("trusted proxies = %v for a plain reverse proxy, want Cloudflare's ranges left out", plain.TrustedProxies)
	}
}

// A self-signed certificate is issued for this host's name, so the operator
// is not asked for something the installer already knows.
func TestASelfSignedCertificateCoversTheHostnameItWasGiven(t *testing.T) {
	p := Plan{}
	ListenSelfSigned.apply(&p, 8080, "build-01")
	if !slices.Contains(p.TLSHosts, "build-01") {
		t.Errorf("TLS hosts = %v, want the host's own name", p.TLSHosts)
	}

	// A plan that already names its hosts keeps them: the operator's list is
	// more specific than the hostname this process happens to see.
	named := Plan{TLSHosts: []string{"ci.example.com"}}
	ListenSelfSigned.apply(&named, 8080, "build-01")
	if !slices.Equal(named.TLSHosts, []string{"ci.example.com"}) {
		t.Errorf("TLS hosts = %v, want the operator's own list kept", named.TLSHosts)
	}
}

// What an installation targets is read from the name when nobody said: a
// slash is a repository, and anything else is an organisation.
func TestATargetWithASlashIsARepository(t *testing.T) {
	cases := []struct {
		target, declared string
		want             store.TargetType
	}{
		{"acme", "", store.TargetOrg},
		{"acme/api", "", store.TargetRepo},
		// A declared type is the operator's answer and is not second-guessed,
		// even when the shape of the name suggests otherwise.
		{"acme/api", string(store.TargetOrg), store.TargetOrg},
		{"acme", string(store.TargetRepo), store.TargetRepo},
		{"acme/api", "nonsense", store.TargetRepo},
	}
	for _, tc := range cases {
		if got := targetTypeFor(tc.target, tc.declared); got != tc.want {
			t.Errorf("targetTypeFor(%q, %q) = %q, want %q", tc.target, tc.declared, got, tc.want)
		}
	}
}

// The ledger is what an aborted run prints instead of claiming nothing
// happened, so a caller must not be able to edit history by holding onto it.
func TestTheLedgerOfWhatWasWrittenIsACopy(t *testing.T) {
	i := unattendedInstaller(t, Options{})
	i.wrote("wrote /etc/zoomies/zoomies.yaml")
	i.wrote("created the service user")

	got := i.Written()
	if len(got) != 2 || got[0] != "wrote /etc/zoomies/zoomies.yaml" {
		t.Fatalf("Written() = %v, want both entries oldest first", got)
	}
	got[0] = "did something else entirely"
	if i.Written()[0] == "did something else entirely" {
		t.Error("a caller rewrote the installer's record of what it did to the host")
	}
}

// The step headings count themselves ("-> 3/9"), so the total has to match
// what the run is actually going to do.
func TestTheStepCountGrowsWithTheWorkThePlanAsksFor(t *testing.T) {
	base := Plan{Mode: ModeController}
	single := Plan{Mode: ModeSingle}
	starting := Plan{Mode: ModeSingle, StartService: true}

	if nativeStepCount(single) != nativeStepCount(base)+1 {
		t.Errorf("a single host creates a first pool, so it is one step longer than a controller: %d and %d",
			nativeStepCount(single), nativeStepCount(base))
	}
	if nativeStepCount(starting) != nativeStepCount(single)+1 {
		t.Errorf("starting the service adds the health check: %d and %d",
			nativeStepCount(starting), nativeStepCount(single))
	}
}

// A select row is one line, so a consequence written as a paragraph is cut at
// its first sentence rather than wrapped across the menu.
func TestASelectRowKeepsOnlyTheFirstSentence(t *testing.T) {
	cases := []struct{ in, want string }{
		{"Binds every interface. Browsers will warn.", "Binds every interface."},
		{"One sentence only", "One sentence only"},
		{"", ""},
		// A trailing full stop is the end of the line, not a boundary to cut
		// an empty tail off.
		{"Ends here.", "Ends here."},
	}
	for _, tc := range cases {
		if got := firstSentence(tc.in); got != tc.want {
			t.Errorf("firstSentence(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

// The backend rows name the socket they found, and say nothing at all when
// there is none -- "docker at " would be worse than "docker".
func TestTheSocketIsNamedOnlyWhenThereIsOne(t *testing.T) {
	if got := socketSuffix("/run/docker.sock"); got != " at /run/docker.sock" {
		t.Errorf("socketSuffix = %q, want the socket named", got)
	}
	if got := socketSuffix(""); got != "" {
		t.Errorf("socketSuffix = %q, want nothing to follow the backend's name", got)
	}
}

// A non-interactive run gets the same sentence the prompt would have shown,
// so an unattended install explains the deployment it picked.
func TestTheDeploymentConsequenceIsTheOneFromTheMenu(t *testing.T) {
	det := hostWith(true, true)
	for _, o := range DeploymentOptions(det) {
		if got := deploymentConsequence(det, o.Deployment); got != o.Description {
			t.Errorf("deploymentConsequence(%q) = %q, want the menu's own description %q", o.Deployment, got, o.Description)
		}
	}

	// A deployment this host cannot offer still gets a sentence rather than
	// an empty line.
	if got := deploymentConsequence(hostWith(false, false), Deployment("nonsense")); strings.TrimSpace(got) == "" {
		t.Error("a deployment with no row of its own was described with nothing at all")
	}
}

// A path the operator typed is checked while they are still at the prompt.
func TestAPathIsCheckedBeforeTheRunGoesAnyFurther(t *testing.T) {
	dir := t.TempDir()
	cert := filepath.Join(dir, "cert.pem")
	if err := os.WriteFile(cert, []byte("not really a certificate"), 0o600); err != nil {
		t.Fatalf("writing a certificate: %v", err)
	}
	if err := fileMustExist("  " + cert + "  "); err != nil {
		t.Errorf("fileMustExist(%q) = %v, want the surrounding spaces trimmed and the file found", cert, err)
	}
	if err := fileMustExist(""); err == nil {
		t.Error("an empty path was accepted")
	}
	missing := filepath.Join(dir, "nowhere.pem")
	err := fileMustExist(missing)
	if err == nil {
		t.Fatal("a path that is not there was accepted")
	}
	if !strings.Contains(err.Error(), missing) {
		t.Errorf("error = %q, want it to name the path it could not read", err)
	}
}

// An answer that is not on the menu cannot be preselected: the form would
// show the first row while the plan held something else.
func TestAnAnswerIsOnlyKeptWhenItIsOneOfTheChoices(t *testing.T) {
	var opts []huh.Option[string]
	for _, o := range DeploymentOptions(hostWith(true, true)) {
		opts = append(opts, huh.NewOption(o.Label+" -- "+o.Description, string(o.Deployment)))
	}
	if len(opts) == 0 {
		t.Fatal("no deployment options were offered at all")
	}
	if !containsOption(opts, opts[0].Value) {
		t.Errorf("the first option %q was not found among the choices", opts[0].Value)
	}
	if containsOption(opts, "something-else") {
		t.Error("a value nobody offered was reported as one of the choices")
	}
}

package installer

import (
	"bytes"
	"context"
	"slices"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// poolFixture is a non-interactive installer writing into a scratch database,
// which is all stepFirstPool needs: it asks nothing when not interactive.
func poolFixture(t *testing.T) (*Installer, *store.Store, *config.Config, Plan) {
	t.Helper()
	st, err := store.Open(context.Background(), store.Options{Path: ":memory:"})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	i := &Installer{
		out: &bytes.Buffer{},
		ui:  newUI(&bytes.Buffer{}),
		det: Detection{OS: "linux", Arch: "amd64", Hostname: "runner-1"},
	}
	p := Plan{Mode: ModeSingle, Backend: store.BackendDocker, Capacity: 4}
	return i, st, config.Default(), p
}

// installedInstallation records the App the pool will belong to, because a
// pool with no installation is not a pool the API would accept either.
func installedInstallation(t *testing.T, st *store.Store) *store.Installation {
	t.Helper()
	inst := &store.Installation{
		AppID: 1, InstallationID: 2, Target: "acme", TargetType: store.TargetOrg,
		APIBaseURL: "https://api.github.com",
	}
	if err := st.CreateInstallation(context.Background(), inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}
	return inst
}

func TestFirstPoolMakesTheInstallHostUsable(t *testing.T) {
	ctx := context.Background()
	i, st, cfg, p := poolFixture(t)
	inst := installedInstallation(t, st)

	if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
		t.Fatalf("stepFirstPool: %v", err)
	}

	pools, err := st.ListPools(ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(pools) != 1 {
		t.Fatalf("got %d pools, want exactly one", len(pools))
	}
	got := pools[0]
	if got.Name != "zoomies-linux-x64" {
		t.Errorf("pool name = %q, want the branded label a workflow's runs-on can ask for", got.Name)
	}
	if !slices.Equal([]string(got.Labels), []string{"zoomies", "zoomies-linux-x64"}) {
		t.Errorf("labels = %v, want the brand and this host's branded label", got.Labels)
	}
	if got.InstallationID != inst.ID {
		t.Errorf("installation = %q, want %q", got.InstallationID, inst.ID)
	}
	if got.Backend != store.BackendDocker {
		t.Errorf("backend = %q, want the one setup chose for this host", got.Backend)
	}
	if got.MaxRunners != 4 {
		t.Errorf("max_runners = %d, want the host's capacity", got.MaxRunners)
	}
	if !got.Ephemeral {
		t.Error("the pool must be ephemeral: one job per runner is what keeps workflows out of each other")
	}
	if !got.Enabled {
		t.Error("a pool created by setup that is not enabled runs nothing, which is the bug this step exists to fix")
	}
	// No image, like the pool the wizard's simple path writes. Writing the
	// fleet's default into the row would pin this pool to the build it was
	// installed with, and a pool on a tag an older build handed out is one
	// nothing can move onto the Docker variant the day its jobs need a client.
	if got.Image != "" {
		t.Errorf("image = %q, want none so the pool follows the fleet's default", got.Image)
	}
	// The summary reads this to say "you are ready" rather than printing a
	// command for a pool that now exists.
	if p.PoolName != "zoomies-linux-x64" {
		t.Errorf("plan.PoolName = %q, want the pool that was created", p.PoolName)
	}
}

// Re-running `zoomies init` on a live fleet must not add a second pool beside
// the ones an operator has since shaped by hand.
func TestFirstPoolLeavesAnExistingFleetAlone(t *testing.T) {
	ctx := context.Background()
	i, st, cfg, p := poolFixture(t)
	inst := installedInstallation(t, st)

	existing := &store.Pool{
		Name: "zoomies-big-builders", InstallationID: inst.ID,
		Labels: store.StringSlice{"big-builders"}, Backend: store.BackendDocker,
		DockerMode: store.DockerNone, MaxRunners: 20, Enabled: true,
	}
	if err := st.CreatePool(ctx, existing); err != nil {
		t.Fatalf("CreatePool: %v", err)
	}

	if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
		t.Fatalf("stepFirstPool: %v", err)
	}
	pools, err := st.ListPools(ctx)
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(pools) != 1 || pools[0].Name != "zoomies-big-builders" {
		t.Fatalf("existing fleet was modified: %+v", pools)
	}
	if p.PoolName != "" {
		t.Errorf("plan.PoolName = %q, want empty when no pool was created", p.PoolName)
	}
}

// A pool belongs to an installation, so there is nothing to create until
// GitHub is connected. Setup says so rather than failing.
func TestFirstPoolWaitsForGitHub(t *testing.T) {
	ctx := context.Background()

	t.Run("github skipped", func(t *testing.T) {
		i, st, cfg, p := poolFixture(t)
		p.GitHub.Skip = true
		if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
			t.Fatalf("stepFirstPool: %v", err)
		}
		assertNoPools(t, st)
	})

	t.Run("no installation recorded", func(t *testing.T) {
		i, st, cfg, p := poolFixture(t)
		if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
			t.Fatalf("stepFirstPool: %v", err)
		}
		assertNoPools(t, st)
	})
}

// Only the single-host mode puts an agent on this machine; the other two have
// no runners here to describe.
func TestFirstPoolOnlyOnASingleHostInstall(t *testing.T) {
	ctx := context.Background()
	for _, mode := range []Mode{ModeController, ModeAgent} {
		t.Run(string(mode), func(t *testing.T) {
			i, st, cfg, p := poolFixture(t)
			installedInstallation(t, st)
			p.Mode = mode
			if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
				t.Fatalf("stepFirstPool: %v", err)
			}
			assertNoPools(t, st)
		})
	}
}

func TestFirstPoolHonoursTheAnswerFile(t *testing.T) {
	ctx := context.Background()

	t.Run("skip", func(t *testing.T) {
		i, st, cfg, p := poolFixture(t)
		installedInstallation(t, st)
		i.answers = &Answers{Pool: AnswersPool{Skip: true}}
		if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
			t.Fatalf("stepFirstPool: %v", err)
		}
		assertNoPools(t, st)
	})

	t.Run("overrides", func(t *testing.T) {
		i, st, cfg, p := poolFixture(t)
		installedInstallation(t, st)
		i.answers = &Answers{Pool: AnswersPool{Name: "gpu", MaxRunners: 2}}
		if err := i.stepFirstPool(ctx, st, cfg, &p); err != nil {
			t.Fatalf("stepFirstPool: %v", err)
		}
		pools, err := st.ListPools(ctx)
		if err != nil {
			t.Fatalf("ListPools: %v", err)
		}
		if len(pools) != 1 {
			t.Fatalf("got %d pools, want one", len(pools))
		}
		// The answer file said "gpu"; every pool name carries the brand, so
		// what it gets is the branded form of it.
		if pools[0].Name != "zoomies-gpu" || pools[0].MaxRunners != 2 {
			t.Fatalf("pool = %+v, want the answer file's name, branded, and its cap", pools[0])
		}
		// A renamed pool that was given no labels answers to a branded form
		// of its new name, not the architecture label it would have had.
		if !slices.Equal([]string(pools[0].Labels), []string{"zoomies", "zoomies-gpu"}) {
			t.Fatalf("labels = %v, want [zoomies zoomies-gpu] to follow the rename", pools[0].Labels)
		}
	})
}

func assertNoPools(t *testing.T, st *store.Store) {
	t.Helper()
	pools, err := st.ListPools(context.Background())
	if err != nil {
		t.Fatalf("ListPools: %v", err)
	}
	if len(pools) != 0 {
		t.Fatalf("got %d pools, want none", len(pools))
	}
}

package installer

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"runtime"

	"github.com/eyupio/zoomies/internal/agent"
	"github.com/eyupio/zoomies/internal/config"
)

// The environment file a provider writes into a machine it rents. It is the
// whole of a machine's enrolment -- the controller, a single-use join token,
// the name it must take -- and the unit PrepareAgent writes reads it, which is
// how a template with no credential in it becomes a host that has one.
//
// The controller writes the same path (internal/controller/machineenrol.go),
// and a test in each package pins the two to one string.
const MachineEnvPath = "/etc/zoomies/zoomies.env"

// PrepareOptions describe an agent install that joins nothing.
type PrepareOptions struct {
	ConfigDir  string
	StateDir   string
	BinaryPath string
	// ServiceUser is the account the agent service runs as.
	ServiceUser string
	// Service selects the supervisor; empty detects one.
	Service ServiceKind
	Out     io.Writer
	Logger  *slog.Logger

	// newManager is the test seam: the real one writes under /etc.
	newManager func(kind ServiceKind, unit string) (ServiceManager, error)
}

func (o PrepareOptions) configDir() string {
	if o.ConfigDir != "" {
		return o.ConfigDir
	}
	return config.ConfigDir()
}

func (o PrepareOptions) stateDir() string {
	if o.StateDir != "" {
		return o.StateDir
	}
	return config.StateDir()
}

// PrepareAgent installs the agent service on a machine that is about to become
// a template, and enrols it with nothing.
//
// A provider clones the template and then writes one file into each clone,
// MachineEnvPath, carrying that machine's own credential; the unit written
// here reads that file and is left disabled so that a clone tries to join only
// once the controller has told it what to join as. Everything else -- the
// service account, the directories, a configuration with the agent switched
// on -- is what `zoomies agent join` would have done, minus the join.
//
// It refuses a machine that has already joined something. agent.json is one
// host's identity, and a template containing one clones that identity into
// every machine made from it, which shows up as work vanishing rather than as
// an error. The docs say to delete it; this says so at the moment it matters.
func PrepareAgent(ctx context.Context, opts PrepareOptions) error {
	if opts.Out == nil {
		opts.Out = os.Stdout
	}
	if opts.Logger == nil {
		opts.Logger = slog.Default()
	}
	if opts.newManager == nil {
		opts.newManager = NewServiceManager
	}
	u := newUI(opts.Out)

	det := Detect(ctx, Options{ConfigDir: opts.ConfigDir, StateDir: opts.StateDir, InstalledBinary: opts.BinaryPath, NonInteractive: true})
	workDir := filepath.Join(opts.stateDir(), "work")
	configFile := filepath.Join(opts.configDir(), "zoomies.yaml")

	if statePath := agent.StatePath(workDir); exists(statePath) {
		return fmt.Errorf("installer: %s holds a host's identity, and a template that carries one clones it into every machine made from it; "+
			"delete that file (and remove the host on the controller if it is still listed there), then run this again", statePath)
	}

	serviceUser, serviceGroup := opts.ServiceUser, opts.ServiceUser
	if serviceUser == "" {
		serviceUser, serviceGroup = defaultServiceUser(det)
	}

	u.step("Service user and directories")
	if det.Root && det.OS != "darwin" {
		created, err := ensureServiceUser(ctx, serviceUser, serviceGroup, opts.stateDir())
		if err != nil {
			return err
		}
		if created {
			u.ok("created the system user " + serviceUser)
		}
	}
	if err := prepareDirs(ctx, runtime.GOOS, runCommand, opts.configDir(), opts.stateDir(), workDir); err != nil {
		return err
	}
	u.ok(opts.configDir() + " and " + opts.stateDir() + " are ready")

	// A configuration with nothing in it but "this is an agent". The controller,
	// the name and the capacity arrive in the environment file, per machine.
	u.step("Configuration")
	cfg := config.Default()
	cfg.Agent.Embedded = false
	cfg.Agent.WorkDir = workDir
	if err := cfg.Save(configFile); err != nil {
		return fmt.Errorf("installer: writing %s: %w", configFile, err)
	}
	u.ok("wrote " + configFile)
	if det.Root && det.OS != "darwin" {
		if uid, gid, err := lookupUser(serviceUser, serviceGroup); err == nil {
			for _, p := range []string{opts.configDir(), opts.stateDir(), workDir, configFile} {
				_ = os.Chown(p, uid, gid)
			}
		}
	}

	u.step("Service")
	kind := opts.Service
	if kind == "" {
		kind = DetectServiceKind(det)
	}
	if kind != ServiceSystemd {
		// The provider's bootstrap runs `systemctl enable --now zoomies-agent`
		// inside the guest, so a template without systemd is a template whose
		// machines never join. Saying so here is cheaper than a fleet of
		// machines that boot and sit there.
		return errors.New("installer: a machine that a provider clones needs systemd, because the controller enrols a clone by enabling zoomies-agent.service inside it; " +
			"prepare the template on a systemd-based Linux image (Ubuntu 24.04 is what has been qualified)")
	}
	mgr, err := opts.newManager(kind, UnitAgent)
	if err != nil {
		return err
	}
	spec := ServiceSpec{
		Unit:       UnitAgent,
		ExecPath:   det.BinaryPath,
		ConfigFile: configFile,
		User:       serviceUser,
		Group:      serviceGroup,
		StateDir:   opts.stateDir(),
		ConfigDir:  opts.configDir(),
		EnvFile:    MachineEnvPath,
		// Every qualified machine runs Docker, and a unit that raced the
		// daemon would fail its first probe for no good reason. The line is
		// harmless on a template that ships something else.
		WantsDocker: true,
		RuntimeName: "docker",
	}
	if group, ok := dockerSocketGroup(); ok {
		spec.SupplementaryGroups = []string{group}
	}
	path, err := mgr.Install(ctx, spec)
	if err != nil {
		return err
	}
	// Installed and deliberately not enabled: `enable --now` is the
	// controller's line, run once the environment file is in place.
	if err := mgr.Disable(ctx); err != nil {
		return fmt.Errorf("installer: leaving the agent service disabled: %w", err)
	}
	u.ok("installed " + path + ", disabled")
	u.note("it reads " + MachineEnvPath + ", which the controller writes into each clone; nothing here joins anything")

	u.blank()
	u.step("Done")
	u.note("shut this machine down and convert it to a template; a provider clones it from here")
	return nil
}

// dockerSocketGroup names the group that owns the root Docker socket, when
// there is one, so the unit can join it and reach the daemon without being
// root. A rootless socket, or no Docker at all, needs no line.
func dockerSocketGroup() (string, bool) {
	facts, ok := statSocket("unix:///var/run/docker.sock")
	if !ok || facts.gid == 0 {
		return "", false
	}
	return socketGroupName(facts.gid), true
}

package installer

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// fakeManager records what PrepareAgent asks of the service manager, because
// the real one writes under /etc and the point of the test is what was asked.
type fakeManager struct {
	spec    ServiceSpec
	enabled bool
	started bool
	calls   []string
}

func (m *fakeManager) Kind() ServiceKind { return ServiceSystemd }
func (m *fakeManager) Install(_ context.Context, spec ServiceSpec) (string, error) {
	m.spec = spec
	m.calls = append(m.calls, "install")
	return "/etc/systemd/system/zoomies-agent.service", nil
}
func (m *fakeManager) Enable(context.Context) error {
	m.enabled = true
	m.calls = append(m.calls, "enable")
	return nil
}
func (m *fakeManager) Start(context.Context) error {
	m.started = true
	m.calls = append(m.calls, "start")
	return nil
}
func (m *fakeManager) Stop(context.Context) error { m.calls = append(m.calls, "stop"); return nil }
func (m *fakeManager) Disable(context.Context) error {
	m.calls = append(m.calls, "disable")
	return nil
}
func (m *fakeManager) Remove(context.Context) error { m.calls = append(m.calls, "remove"); return nil }
func (m *fakeManager) Status(context.Context) (string, error) {
	return "inactive", nil
}
func (m *fakeManager) Logs(context.Context, int) (string, error) { return "", nil }
func (m *fakeManager) LogCommand() string                        { return "journalctl -u zoomies-agent" }

func prepareOptions(t *testing.T, mgr *fakeManager) (PrepareOptions, *bytes.Buffer) {
	t.Helper()
	root := t.TempDir()
	var out bytes.Buffer
	return PrepareOptions{
		ConfigDir:  filepath.Join(root, "etc"),
		StateDir:   filepath.Join(root, "lib"),
		BinaryPath: "/usr/local/bin/zoomies",
		// An account that exists, so no system user is created on the machine
		// running the tests.
		ServiceUser: currentUserName(os.Getuid()),
		Service:     ServiceSystemd,
		Out:         &out,
		newManager: func(ServiceKind, string) (ServiceManager, error) {
			return mgr, nil
		},
	}, &out
}

// The template's unit is what makes a clone enrollable: it reads the file the
// controller writes into each machine and stays disabled until the controller
// enables it, so a template that shipped it enabled would have every clone try
// to join before it had anything to join with.
func TestPreparingAnAgentInstallsAUnitThatReadsTheEnrolmentFileAndStaysDisabled(t *testing.T) {
	mgr := &fakeManager{}
	opts, out := prepareOptions(t, mgr)
	if err := PrepareAgent(context.Background(), opts); err != nil {
		t.Fatalf("PrepareAgent: %v\n%s", err, out)
	}
	if mgr.spec.EnvFile != MachineEnvPath {
		t.Errorf("EnvFile = %q, want %q", mgr.spec.EnvFile, MachineEnvPath)
	}
	if mgr.spec.Unit != UnitAgent {
		t.Errorf("unit = %q, want the agent's", mgr.spec.Unit)
	}
	if mgr.enabled || mgr.started {
		t.Errorf("the unit was enabled or started; the controller does that inside each clone (calls: %v)", mgr.calls)
	}
	if strings.Join(mgr.calls, " ") != "install disable" {
		t.Errorf("calls = %v, want install then disable", mgr.calls)
	}
	// The unit needs a configuration file to point at, and the one written
	// says this is an agent and nothing else: the controller, the name and the
	// capacity arrive per machine in the environment file.
	cfg, err := os.ReadFile(filepath.Join(opts.ConfigDir, "zoomies.yaml"))
	if err != nil {
		t.Fatalf("no configuration was written: %v", err)
	}
	if !strings.Contains(string(cfg), "embedded: false") {
		t.Errorf("the configuration does not switch the embedded agent off:\n%s", cfg)
	}
	if strings.Contains(string(cfg), "join_token") || strings.Contains(string(cfg), "zoojoin_") {
		t.Errorf("a credential landed in the configuration:\n%s", cfg)
	}
	if !strings.Contains(out.String(), "convert it to a template") {
		t.Errorf("the output does not say what to do next:\n%s", out)
	}
}

// A machine that has already joined holds one host's identity, and a template
// made from it clones that identity into every machine. Refusing here is the
// only moment the mistake is cheap.
func TestPreparingAnAgentRefusesAMachineThatHasAlreadyJoined(t *testing.T) {
	mgr := &fakeManager{}
	opts, _ := prepareOptions(t, mgr)
	work := filepath.Join(opts.StateDir, "work")
	if err := os.MkdirAll(work, 0o750); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(work, "agent.json"), []byte(`{"host_id":"hst_x"}`), 0o600); err != nil {
		t.Fatal(err)
	}
	err := PrepareAgent(context.Background(), opts)
	if err == nil {
		t.Fatal("a machine holding agent.json was accepted as a template")
	}
	if !strings.Contains(err.Error(), "agent.json") || !strings.Contains(err.Error(), "delete that file") {
		t.Errorf("the error does not name the file and the fix: %v", err)
	}
	if len(mgr.calls) != 0 {
		t.Errorf("the service manager was touched before the refusal: %v", mgr.calls)
	}
}

// The bootstrap enrols a clone with `systemctl enable --now`, so a template
// without systemd is a fleet of machines that boot and never join.
func TestPreparingAnAgentNeedsSystemd(t *testing.T) {
	mgr := &fakeManager{}
	opts, _ := prepareOptions(t, mgr)
	opts.Service = ServiceNone
	err := PrepareAgent(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "systemd") {
		t.Fatalf("err = %v, want a refusal naming systemd", err)
	}
}

func TestRenderSystemdUnitReadsAnEnvironmentFileOnlyWhenAsked(t *testing.T) {
	spec := ServiceSpec{
		Unit:       UnitAgent,
		ExecPath:   "/usr/local/bin/zoomies",
		ConfigFile: "/etc/zoomies/zoomies.yaml",
		User:       "zoomies",
		Group:      "zoomies",
		StateDir:   "/var/lib/zoomies",
		ConfigDir:  "/etc/zoomies",
	}
	out, err := RenderSystemdUnit(spec)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out, "EnvironmentFile") {
		t.Errorf("a joined host's unit names an environment file nobody asked for:\n%s", out)
	}
	spec.EnvFile = MachineEnvPath
	out, err = RenderSystemdUnit(spec)
	if err != nil {
		t.Fatal(err)
	}
	// The dash is load-bearing: the file is written by the controller after
	// the clone boots, and a unit that failed for want of it could never be
	// the unit that reads it.
	if !strings.Contains(out, "EnvironmentFile=-"+MachineEnvPath+"\n") {
		t.Errorf("the environment file is not read, or is not optional:\n%s", out)
	}
	if strings.Contains(out, "{{") {
		t.Errorf("unrendered template directive left in the unit:\n%s", out)
	}
}

package installer

import (
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

func reviewValue(t *testing.T, lines []ReviewLine, key string) string {
	t.Helper()
	for _, l := range lines {
		if l.Key == key {
			return l.Value
		}
	}
	t.Fatalf("the review screen has no %q line: %+v", key, lines)
	return ""
}

func hasReviewKey(lines []ReviewLine, key string) bool {
	for _, l := range lines {
		if l.Key == key {
			return true
		}
	}
	return false
}

// An installer that writes to /etc and /var/lib without saying what it is
// about to do is the reason people ctrl-c at the last question. Every setting
// that changes the host has to be on the screen the operator approves.
func TestReviewNamesEverythingThatChangesTheHost(t *testing.T) {
	p := Plan{
		Mode: ModeSingle, Deployment: DeploymentNative, Service: ServiceSystemd,
		ServiceUser: "zoomies", ServiceGroup: "zoomies",
		Embedded: true, Backend: store.BackendDocker, DockerHost: "unix:///var/run/docker.sock",
		Capacity: 4, Bind: "127.0.0.1:8080", TLSMode: config.TLSOff,
		ExternalURL: "http://localhost:8080", AdminUser: "admin",
		GitHub: GitHubPlan{Target: "acme", TargetType: store.TargetOrg},
	}

	lines := p.Review()

	if got := reviewValue(t, lines, "this host"); !strings.Contains(got, "embedded agent") {
		t.Errorf("this host = %q, want it to say the agent is embedded", got)
	}
	if got := reviewValue(t, lines, "run as"); !strings.Contains(got, "systemd") {
		t.Errorf("run as = %q, want the service manager named", got)
	}
	if got := reviewValue(t, lines, "account"); got != "zoomies:zoomies" {
		t.Errorf("account = %q", got)
	}
	// The socket is on the screen because which daemon a runner reaches is the
	// difference between a container escape landing on root and landing on an
	// unprivileged account.
	if got := reviewValue(t, lines, "backend"); !strings.Contains(got, "/var/run/docker.sock") {
		t.Errorf("backend = %q, want the socket named", got)
	}
	if got := reviewValue(t, lines, "capacity"); got != "4 runners at once" {
		t.Errorf("capacity = %q", got)
	}
	if got := reviewValue(t, lines, "listener"); !strings.Contains(got, "127.0.0.1:8080") {
		t.Errorf("listener = %q", got)
	}
	if got := reviewValue(t, lines, "github"); !strings.Contains(got, "acme (org)") {
		t.Errorf("github = %q", got)
	}
	if got := reviewValue(t, lines, "admin"); got != "admin" {
		t.Errorf("admin = %q", got)
	}
	// A native deployment builds nothing, so there is no image to show.
	if hasReviewKey(lines, "image") {
		t.Error("a native deployment was offered an image line")
	}
}

// A rootless daemon is the safe answer and the screen has to say which one was
// found, because "docker" alone does not distinguish them.
func TestReviewMarksARootlessDaemon(t *testing.T) {
	p := Plan{
		Mode: ModeSingle, Deployment: DeploymentNative, Embedded: true,
		Backend: store.BackendDocker, DockerHost: "unix:///run/user/1000/docker.sock",
		Rootless: true, Capacity: 1, TLSMode: config.TLSOff,
	}

	if got := reviewValue(t, p.Review(), "backend"); !strings.Contains(got, "rootless") {
		t.Errorf("backend = %q, want it marked rootless", got)
	}
	// One runner is not "1 runners".
	if got := reviewValue(t, p.Review(), "capacity"); got != "1 runner at once" {
		t.Errorf("capacity = %q", got)
	}
}

// A containerised deployment makes its administrator in the browser and shows
// the image instead of an account, because there is no account on this host to
// show and the image is the single line saying which build it becomes.
func TestReviewOfAContainerShowsTheImageAndNoAccount(t *testing.T) {
	p := Plan{
		Mode: ModeSingle, Deployment: DeploymentCompose, DeployDir: "/opt/zoomies",
		Image: "ghcr.io/eyupio/zoomies:1.0.0", Bind: "0.0.0.0:8080",
		PublishAddr: "0.0.0.0", PublishedPort: 443, TLSMode: config.TLSOff,
		ExternalURL: "https://zoomies.example.com",
	}

	lines := p.Review()

	if got := reviewValue(t, lines, "image"); got != "ghcr.io/eyupio/zoomies:1.0.0" {
		t.Errorf("image = %q", got)
	}
	if hasReviewKey(lines, "account") {
		t.Error("a containerised deployment was offered a service account")
	}
	if got := reviewValue(t, lines, "admin"); !strings.Contains(got, "browser") {
		t.Errorf("admin = %q, want it created in the browser", got)
	}
	// A published port is two addresses, and the operator needs both: the one
	// they will reach and the one inside the container.
	if got := reviewValue(t, lines, "listener"); !strings.Contains(got, "0.0.0.0:443") || !strings.Contains(got, "0.0.0.0:8080") {
		t.Errorf("listener = %q, want both sides of the publish", got)
	}
	if got := reviewValue(t, lines, "run as"); !strings.Contains(got, "/opt/zoomies") {
		t.Errorf("run as = %q, want the project directory", got)
	}
}

// Skipping GitHub is a decision, not an omission, and it has to read as one on
// the screen where the operator is deciding.
func TestReviewSaysWhenGitHubIsBeingLeftForLater(t *testing.T) {
	skipped := Plan{Mode: ModeSingle, Deployment: DeploymentNative, TLSMode: config.TLSOff,
		GitHub: GitHubPlan{Skip: true}}
	if got := reviewValue(t, skipped.Review(), "github"); !strings.Contains(got, "later") {
		t.Errorf("github = %q, want it to say later", got)
	}

	fresh := Plan{Mode: ModeSingle, Deployment: DeploymentNative, TLSMode: config.TLSOff}
	if got := reviewValue(t, fresh.Review(), "github"); !strings.Contains(got, "browser") {
		t.Errorf("github = %q, want the browser handshake", got)
	}
}

// Every mode gets a sentence of its own, because "controller" and "controller
// with an embedded agent" are different machines and the difference is the
// whole reason a fleet has more than one host.
func TestReviewDescribesEachMode(t *testing.T) {
	for mode, want := range map[Mode]string{
		ModeSingle:     "embedded agent",
		ModeController: "join it separately",
		ModeAgent:      "a runner host",
	} {
		p := Plan{Mode: mode, Deployment: DeploymentNative, TLSMode: config.TLSOff}
		if got := reviewValue(t, p.Review(), "this host"); !strings.Contains(got, want) {
			t.Errorf("%s: this host = %q, want it to mention %q", mode, got, want)
		}
	}
}

// A native install with no service manager has nothing to restart it, which is
// a real choice with a real cost -- so the screen says so rather than leaving
// the "run as" line reading like any other.
func TestReviewSaysWhenNothingWillRestartIt(t *testing.T) {
	p := Plan{Mode: ModeSingle, Deployment: DeploymentNative, Service: ServiceNone, TLSMode: config.TLSOff}

	if got := reviewValue(t, p.Review(), "run as"); !strings.Contains(got, "no service manager") {
		t.Errorf("run as = %q, want the absence of a supervisor named", got)
	}
}

// An operator who can see exactly which files are involved can decide in a
// second; one who cannot has to take the installer's word for it.
func TestWritesNamesTheFilesEachDeploymentTouches(t *testing.T) {
	native := Plan{
		Deployment: DeploymentNative, Service: ServiceSystemd,
		ConfigFile: "/etc/zoomies/zoomies.yaml", KeyFile: "/etc/zoomies/key",
		DBPath: "/var/lib/zoomies/zoomies.db",
	}
	got := native.Writes()
	for _, want := range []string{"/etc/zoomies/zoomies.yaml", "/var/lib/zoomies/zoomies.db"} {
		if !containsSubstring(got, want) {
			t.Errorf("Writes() = %v, want it to name %q", got, want)
		}
	}
	// The key's mode is part of the promise: 0600 is what stops anything that
	// can read the config from decrypting every stored secret.
	if !containsSubstring(got, "0600") {
		t.Errorf("Writes() = %v, want the key's mode shown", got)
	}
	if !containsSubstring(got, SystemdUnitPath(UnitController)) {
		t.Errorf("Writes() = %v, want the unit file named", got)
	}

	// With no service manager there is no unit to write.
	bare := native
	bare.Service = ServiceNone
	if containsSubstring(bare.Writes(), ".service") {
		t.Errorf("a serviceless install claimed it would write a unit: %v", bare.Writes())
	}

	// A containerised deployment writes into its project directory and nowhere
	// else on the host; the database lives in a volume.
	compose := Plan{Deployment: DeploymentCompose, DeployDir: "/opt/zoomies", StateDir: "/var/lib/zoomies"}
	got = compose.Writes()
	if len(got) != 3 {
		t.Fatalf("Writes() = %v, want three paths", got)
	}
	if got[0] != filepath.Join("/opt/zoomies", "docker-compose.yml") || got[1] != filepath.Join("/opt/zoomies", ".env") {
		t.Errorf("Writes() = %v, want the compose project's two files first", got)
	}
	if !strings.Contains(got[2], "volume") {
		t.Errorf("the database line = %q, want it to say the volume", got[2])
	}
}

// "Did a previous run finish?" is asked read-only, because a read-write open
// would migrate the database as a side effect of the question -- and a
// database that cannot be opened is not evidence of anything either way.
func TestFinishedIsFalseUntilThereIsAnAdministrator(t *testing.T) {
	ctx := t.Context()
	dir := t.TempDir()

	if finished(ctx, "") {
		t.Error("an empty path was reported as a finished install")
	}
	if finished(ctx, filepath.Join(dir, "absent.db")) {
		t.Error("a database that does not exist was reported as a finished install")
	}

	// A file that is not a database answers false rather than failing the run.
	junk := writeFile(t, dir, "junk.db", "not a database")
	if finished(ctx, junk) {
		t.Error("an unreadable database was reported as a finished install")
	}

	// A real database with no users is an abandoned run: the remaining steps
	// are all safe to repeat.
	path := filepath.Join(dir, "zoomies.db")
	st, err := store.Open(ctx, store.Options{Path: path})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if finished(ctx, path) {
		t.Error("a database with no administrator was reported as finished")
	}

	st, err = store.Open(ctx, store.Options{Path: path})
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	if err := st.CreateUser(ctx, &store.User{Username: "admin", Role: store.RoleAdmin}); err != nil {
		t.Fatalf("CreateUser: %v", err)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if !finished(ctx, path) {
		t.Error("a database with an administrator was not reported as finished")
	}
}

func containsSubstring(haystack []string, needle string) bool {
	for _, s := range haystack {
		if strings.Contains(s, needle) {
			return true
		}
	}
	return false
}

package installer

import (
	"bytes"
	"context"
	"embed"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"text/template"
	"time"
)

// templateFS holds the unit files, the launchd plist and the compose file.
//
// They are embedded rather than read from disk because the installer must work
// from a single downloaded binary on a host that has never seen this
// repository, and they are the only copy: deploy/ used to carry a static pair
// of units beside them, which drifted -- no SupplementaryGroups, no
// conditional CAP_NET_BIND_SERVICE, no `systemctl edit` guidance -- and which
// nothing installed, documented or tested.
//
//go:embed templates/*.tmpl
var templateFS embed.FS

var unitTemplates = template.Must(template.New("").Funcs(template.FuncMap{
	"join": strings.Join,
}).ParseFS(templateFS, "templates/*.tmpl"))

// ServiceKind names the supervisor an installation will be managed by.
type ServiceKind string

const (
	// ServiceSystemd installs a unit under /etc/systemd/system.
	ServiceSystemd ServiceKind = "systemd"
	// ServiceLaunchd installs a plist, which is how macOS keeps a development
	// controller running.
	ServiceLaunchd ServiceKind = "launchd"
	// ServiceCompose is what detection reports for a host that has neither but
	// does have a compose command. It installs nothing: a native install
	// supervised by a container would keep its state in two places, so setup
	// refuses the pair and says to run again with --deployment compose, which
	// makes the whole deployment containerised rather than half of it.
	ServiceCompose ServiceKind = "compose"
	// ServiceNone leaves the operator to run the binary themselves.
	ServiceNone ServiceKind = "none"
	// ServiceWindows is declared in service_scm.go beside the manager that
	// drives it.
)

// serviceStopTimeout outlasts the agent's admitted work and the controller's
// shutdown. Keep container upgrades and installed units on the same budget.
const serviceStopTimeout = 20 * time.Minute

// Unit names the two services Zoomies installs.
const (
	// UnitController is the controller, with or without an embedded agent.
	UnitController = "zoomies"
	// UnitAgent is a standalone agent on a runner host.
	UnitAgent = "zoomies-agent"
)

// ServiceSpec is everything the unit templates need. It is a plain struct so
// that rendering can be tested without a service manager, an init system or
// root.
type ServiceSpec struct {
	// Unit is UnitController or UnitAgent.
	Unit string
	// Description is the one-line summary systemd and launchd show.
	Description string
	// ExecPath is the zoomies binary the service runs.
	ExecPath string
	// Command is the subcommand: "controller" or "agent".
	Command    string
	ConfigFile string
	User       string
	Group      string
	StateDir   string
	ConfigDir  string
	// SupplementaryGroups are extra groups the service joins, which is how a
	// root Docker socket becomes usable without running as root.
	SupplementaryGroups []string
	// RuntimeName names the runtime those groups exist for, so the unit's
	// comment says why the line is there.
	RuntimeName string
	// Bind is the listen address, used only to decide whether the service
	// needs CAP_NET_BIND_SERVICE.
	Bind string
	// StopTimeout bounds a graceful stop while admitted lifecycle tasks finish.
	// Running CI jobs are left alone, including by the embedded agent.
	StopTimeout time.Duration
	// WantsDocker orders the unit after the Docker daemon.
	WantsDocker bool
	// Home and Path are launchd's environment, which is otherwise empty.
	Home string
	Path string
	// LogFile is where launchd sends stdout and stderr, since macOS has no
	// journal.
	LogFile string
	// EnvFile is an environment file the unit reads before it starts, and is
	// allowed not to exist. A machine a provider clones is enrolled by having
	// this file written into it, so the unit in the template has to name it
	// before the file is there.
	EnvFile string
}

// Label is the launchd job label, which doubles as the plist's file name.
func (s ServiceSpec) Label() string {
	if s.Unit == UnitAgent {
		return "sh.zoomies.agent"
	}
	return "sh.zoomies.controller"
}

// StandardDirs reports whether the state and config directories are the ones
// systemd's StateDirectory= and ConfigurationDirectory= would create. When an
// operator has chosen their own, those directives would point elsewhere, so
// they are left out and ReadWritePaths does the work instead.
func (s ServiceSpec) StandardDirs() bool {
	return s.StateDir == "/var/lib/zoomies" && s.ConfigDir == "/etc/zoomies"
}

// NeedsNetBind reports whether the listener wants a privileged port, which is
// the only reason this service is ever given a capability.
func (s ServiceSpec) NeedsNetBind() bool {
	_, port, err := splitBind(s.Bind)
	return err == nil && port > 0 && port < 1024
}

// defaults fills the fields a caller may reasonably leave empty, and returns an
// error for the ones it may not.
func (s *ServiceSpec) defaults() error {
	if s.Unit == "" {
		s.Unit = UnitController
	}
	if s.Command == "" {
		if s.Unit == UnitAgent {
			s.Command = "agent"
		} else {
			s.Command = "controller"
		}
	}
	if s.Description == "" {
		if s.Unit == UnitAgent {
			s.Description = "Zoomies runner agent"
		} else {
			s.Description = "Zoomies GitHub Actions runner fleet controller"
		}
	}
	if s.StopTimeout == 0 {
		s.StopTimeout = serviceStopTimeout
	}
	if s.ExecPath == "" {
		return errors.New("installer: the service needs the path of the zoomies binary; pass --installed-binary or install it to /usr/local/bin/zoomies")
	}
	if s.ConfigFile == "" {
		return errors.New("installer: the service needs a config file path; it is what `zoomies " + s.Command + " --config` will read")
	}
	if s.User == "" {
		return errors.New("installer: the service needs a user to run as; on Linux that is the dedicated \"zoomies\" account, on macOS your own")
	}
	if s.Group == "" {
		s.Group = s.User
	}
	if s.StateDir == "" {
		return errors.New("installer: the service needs a state directory, for example /var/lib/zoomies")
	}
	if s.LogFile == "" {
		s.LogFile = filepath.Join(s.StateDir, s.Unit+".log")
	}
	if s.Home == "" {
		s.Home = s.StateDir
	}
	return nil
}

// RenderSystemdUnit renders the unit file for a spec.
func RenderSystemdUnit(spec ServiceSpec) (string, error) {
	if err := spec.defaults(); err != nil {
		return "", err
	}
	name := "zoomies.service.tmpl"
	if spec.Unit == UnitAgent {
		name = "zoomies-agent.service.tmpl"
	}
	return render(name, systemdView{ServiceSpec: spec,
		StandardDirs: spec.StandardDirs(),
		NeedsNetBind: spec.NeedsNetBind(),
		StopTimeout:  formatSeconds(spec.StopTimeout),
	})
}

// systemdView adapts a spec for the template, so that the template contains no
// logic beyond choosing between two lines.
type systemdView struct {
	ServiceSpec
	StandardDirs bool
	NeedsNetBind bool
	StopTimeout  string
}

// RenderLaunchdPlist renders the macOS job description for a spec.
func RenderLaunchdPlist(spec ServiceSpec) (string, error) {
	if err := spec.defaults(); err != nil {
		return "", err
	}
	return render("launchd.plist.tmpl", launchdView{ServiceSpec: spec, Label: spec.Label()})
}

type launchdView struct {
	ServiceSpec
	Label string
}

func render(name string, data any) (string, error) {
	var b bytes.Buffer
	if err := unitTemplates.ExecuteTemplate(&b, name, data); err != nil {
		return "", fmt.Errorf("installer: rendering %s: %w", name, err)
	}
	return b.String(), nil
}

// formatSeconds renders a duration the way systemd writes them, which keeps
// the generated unit readable next to the hand-written one in deploy/.
func formatSeconds(d time.Duration) string {
	return strconv.Itoa(int(d.Seconds())) + "s"
}

// SystemdUnitPath is where a unit of this name lives.
func SystemdUnitPath(unit string) string {
	return filepath.Join("/etc/systemd/system", unit+".service")
}

// LaunchdPlistPath is where a launchd job of this name lives. A root install
// is a daemon that starts at boot; a user install is an agent that starts at
// login, which is what a development controller on a laptop wants.
func LaunchdPlistPath(label string, root bool) string {
	if root {
		return filepath.Join("/Library/LaunchDaemons", label+".plist")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		home = "."
	}
	return filepath.Join(home, "Library", "LaunchAgents", label+".plist")
}

// ReadUnitIdentity recovers the account and groups an existing systemd unit
// runs as.
//
// An upgrade rewrites the unit, and rewriting it with this installer's
// defaults would quietly move a controller onto a different account -- and
// away from the files that account owns. Whatever is already there wins.
func ReadUnitIdentity(path string) (userName, group string, groups []string) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", "", nil
	}
	for _, line := range strings.Split(string(b), "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "User="):
			userName = strings.TrimSpace(strings.TrimPrefix(line, "User="))
		case strings.HasPrefix(line, "Group="):
			group = strings.TrimSpace(strings.TrimPrefix(line, "Group="))
		case strings.HasPrefix(line, "SupplementaryGroups="):
			groups = strings.Fields(strings.TrimPrefix(line, "SupplementaryGroups="))
		}
	}
	return userName, group, groups
}

// ServiceManager installs and controls a service through whichever supervisor
// this host actually runs.
//
// Every method is allowed to fail with an explanation rather than a status
// code: setup has to be able to tell an operator what to do next, and "exit
// status 1" is not that.
type ServiceManager interface {
	// Kind names the supervisor.
	Kind() ServiceKind
	// Install writes the unit and returns the path it wrote.
	Install(ctx context.Context, spec ServiceSpec) (string, error)
	// Enable makes the service start at boot.
	Enable(ctx context.Context) error
	// Start starts it now.
	Start(ctx context.Context) error
	// Stop stops it, and is not an error when it was not running.
	Stop(ctx context.Context) error
	// Disable undoes Enable, and is not an error when it was not enabled.
	Disable(ctx context.Context) error
	// Remove deletes the unit file.
	Remove(ctx context.Context) error
	// Status returns one line describing the service's current state.
	Status(ctx context.Context) (string, error)
	// Logs returns the last n lines, for the failure path of a health check.
	Logs(ctx context.Context, n int) (string, error)
	// LogCommand is the command the operator should run to see more, printed
	// alongside those lines.
	LogCommand() string
}

// DetectServiceKind chooses the supervisor for this host. It only ever returns
// one that is actually present: shelling out to systemctl on Alpine is how
// installers produce their most confusing errors.
func DetectServiceKind(d Detection) ServiceKind {
	switch {
	case d.HasSCM:
		return ServiceWindows
	case d.HasSystemd:
		return ServiceSystemd
	case d.HasLaunchd:
		return ServiceLaunchd
	case d.Docker.Available || d.HasCompose:
		return ServiceCompose
	default:
		return ServiceNone
	}
}

// commandRunner runs an external command. It is a field on the managers so
// that tests can watch what would have been run without running it.
type commandRunner func(ctx context.Context, name string, args ...string) (string, error)

// inputRunner is a commandRunner that also hands the command its standard
// input: how a secret reaches a one-off container without appearing in an
// argument list any process on the host can read.
type inputRunner func(ctx context.Context, input, name string, args ...string) (string, error)

func runCommandInput(ctx context.Context, input, name string, args ...string) (string, error) {
	path, err := exec.LookPath(name)
	if err != nil {
		return "", fmt.Errorf("installer: %s is not on PATH, so this step cannot run here: %w", name, err)
	}
	cmd := exec.CommandContext(ctx, path, args...)
	cmd.Stdin = strings.NewReader(input)
	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out
	err = cmd.Run()
	text := strings.TrimSpace(out.String())
	if err != nil {
		if text != "" {
			return text, fmt.Errorf("installer: %s %s failed: %w: %s", name, strings.Join(args, " "), err, text)
		}
		return text, fmt.Errorf("installer: %s %s failed: %w", name, strings.Join(args, " "), err)
	}
	return text, nil
}

func runCommand(ctx context.Context, name string, args ...string) (string, error) {
	path, err := exec.LookPath(name)
	if err != nil {
		return "", fmt.Errorf("installer: %s is not on PATH, so this step cannot run here: %w", name, err)
	}
	cmd := exec.CommandContext(ctx, path, args...)
	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out
	err = cmd.Run()
	text := strings.TrimSpace(out.String())
	if err != nil {
		if text != "" {
			return text, fmt.Errorf("installer: %s %s failed: %w: %s", name, strings.Join(args, " "), err, text)
		}
		return text, fmt.Errorf("installer: %s %s failed: %w", name, strings.Join(args, " "), err)
	}
	return text, nil
}

// NewServiceManager returns the manager for a kind, refusing one whose tooling
// is not installed rather than failing later in the middle of setup.
func NewServiceManager(kind ServiceKind, unit string) (ServiceManager, error) {
	if unit == "" {
		unit = UnitController
	}
	switch kind {
	case ServiceSystemd:
		if lookPath("systemctl") == "" {
			return nil, errors.New("installer: systemd was selected but systemctl is not on PATH; re-run with --service none and start `zoomies controller` yourself, or install systemd")
		}
		return &systemdManager{unit: unit, run: runCommand}, nil
	case ServiceLaunchd:
		if lookPath("launchctl") == "" {
			return nil, errors.New("installer: launchd was selected but launchctl is not on PATH; this is not macOS")
		}
		return &launchdManager{unit: unit, root: os.Geteuid() == 0, run: runCommand}, nil
	case ServiceWindows:
		if lookPath("sc.exe") == "" {
			return nil, errors.New("installer: the Windows service manager was selected but sc.exe is not on PATH; this is not Windows")
		}
		return &windowsManager{unit: unit, run: runCommand}, nil
	case ServiceCompose, ServiceNone:
		return nil, fmt.Errorf("installer: %q installs no service; the installer prints what to run instead", kind)
	default:
		return nil, fmt.Errorf("installer: %q is not a service manager; use systemd, launchd, windows, compose or none", kind)
	}
}

// systemdManager drives systemctl for one unit.
type systemdManager struct {
	unit string
	run  commandRunner
	// path is remembered by Install so Remove needs no second guess.
	path string
}

func (m *systemdManager) Kind() ServiceKind { return ServiceSystemd }

func (m *systemdManager) unitName() string { return m.unit + ".service" }

// Install writes the unit and reloads systemd so the new file is seen.
func (m *systemdManager) Install(ctx context.Context, spec ServiceSpec) (string, error) {
	spec.Unit = m.unit
	body, err := RenderSystemdUnit(spec)
	if err != nil {
		return "", err
	}
	path := SystemdUnitPath(m.unit)
	if err := writeFileAtomic(path, []byte(body), 0o644); err != nil {
		return "", fmt.Errorf("installer: writing %s: %w (this step needs root; re-run with sudo)", path, err)
	}
	m.path = path
	if _, err := m.run(ctx, "systemctl", "daemon-reload"); err != nil {
		return path, err
	}
	return path, nil
}

func (m *systemdManager) Enable(ctx context.Context) error {
	_, err := m.run(ctx, "systemctl", "enable", m.unitName())
	return err
}

func (m *systemdManager) Start(ctx context.Context) error {
	_, err := m.run(ctx, "systemctl", "start", m.unitName())
	return err
}

// Stop is quiet about a unit that is not loaded, because uninstall has to be
// safe to re-run.
func (m *systemdManager) Stop(ctx context.Context) error {
	if !m.loaded(ctx) {
		return nil
	}
	_, err := m.run(ctx, "systemctl", "stop", m.unitName())
	return err
}

func (m *systemdManager) Disable(ctx context.Context) error {
	if !m.loaded(ctx) {
		return nil
	}
	_, err := m.run(ctx, "systemctl", "disable", m.unitName())
	return err
}

func (m *systemdManager) Remove(ctx context.Context) error {
	path := m.path
	if path == "" {
		path = SystemdUnitPath(m.unit)
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("installer: removing %s: %w", path, err)
	}
	_, _ = m.run(ctx, "systemctl", "daemon-reload")
	_, _ = m.run(ctx, "systemctl", "reset-failed", m.unitName())
	return nil
}

func (m *systemdManager) Status(ctx context.Context) (string, error) {
	out, err := m.run(ctx, "systemctl", "is-active", m.unitName())
	if out == "" && err != nil {
		return "", err
	}
	// is-active exits non-zero for anything but "active", and the word it
	// prints is more useful than the exit code.
	return out, nil
}

func (m *systemdManager) Logs(ctx context.Context, n int) (string, error) {
	if lookPath("journalctl") == "" {
		return "", errors.New("installer: journalctl is not on PATH, so the service's logs cannot be shown here; try `systemctl status " + m.unitName() + "`")
	}
	out, err := m.run(ctx, "journalctl", "-u", m.unitName(), "-n", strconv.Itoa(n), "--no-pager")
	if err != nil && out == "" {
		return "", err
	}
	return out, nil
}

func (m *systemdManager) LogCommand() string {
	return "journalctl -u " + m.unitName() + " -f"
}

func (m *systemdManager) loaded(ctx context.Context) bool {
	out, _ := m.run(ctx, "systemctl", "list-unit-files", m.unitName())
	return strings.Contains(out, m.unitName())
}

// launchdManager drives launchctl for one job.
type launchdManager struct {
	unit string
	root bool
	run  commandRunner
	path string
	log  string
}

func (m *launchdManager) Kind() ServiceKind { return ServiceLaunchd }

func (m *launchdManager) label() string {
	if m.unit == UnitAgent {
		return "sh.zoomies.agent"
	}
	return "sh.zoomies.controller"
}

func (m *launchdManager) domain() string {
	if m.root {
		return "system"
	}
	return "gui/" + strconv.Itoa(os.Getuid())
}

func (m *launchdManager) Install(ctx context.Context, spec ServiceSpec) (string, error) {
	spec.Unit = m.unit
	body, err := RenderLaunchdPlist(spec)
	if err != nil {
		return "", err
	}
	path := LaunchdPlistPath(m.label(), m.root)
	if err := writeFileAtomic(path, []byte(body), 0o644); err != nil {
		return "", fmt.Errorf("installer: writing %s: %w", path, err)
	}
	m.path = path
	m.log = spec.LogFile
	// A job already loaded from an older plist would keep running the old
	// command, so the load is always preceded by an unload.
	_, _ = m.run(ctx, "launchctl", "bootout", m.domain()+"/"+m.label())
	return path, nil
}

// Enable is a no-op beyond bootstrapping: RunAtLoad in the plist is what makes
// a launchd job come back, and bootstrapping is what Start does.
func (m *launchdManager) Enable(ctx context.Context) error {
	_, err := m.run(ctx, "launchctl", "enable", m.domain()+"/"+m.label())
	return err
}

func (m *launchdManager) Start(ctx context.Context) error {
	path := m.path
	if path == "" {
		path = LaunchdPlistPath(m.label(), m.root)
	}
	if _, err := m.run(ctx, "launchctl", "bootstrap", m.domain(), path); err != nil {
		return err
	}
	_, err := m.run(ctx, "launchctl", "kickstart", m.domain()+"/"+m.label())
	return err
}

func (m *launchdManager) Stop(ctx context.Context) error {
	_, _ = m.run(ctx, "launchctl", "bootout", m.domain()+"/"+m.label())
	return nil
}

func (m *launchdManager) Disable(ctx context.Context) error {
	_, _ = m.run(ctx, "launchctl", "disable", m.domain()+"/"+m.label())
	return nil
}

func (m *launchdManager) Remove(ctx context.Context) error {
	path := m.path
	if path == "" {
		path = LaunchdPlistPath(m.label(), m.root)
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("installer: removing %s: %w", path, err)
	}
	return nil
}

func (m *launchdManager) Status(ctx context.Context) (string, error) {
	out, err := m.run(ctx, "launchctl", "print", m.domain()+"/"+m.label())
	if err != nil {
		return "not loaded", nil
	}
	for _, line := range strings.Split(out, "\n") {
		if s := strings.TrimSpace(line); strings.HasPrefix(s, "state = ") {
			return strings.TrimPrefix(s, "state = "), nil
		}
	}
	return "loaded", nil
}

// Logs tails the file the plist points at, because macOS has no journal and
// `log show` cannot be filtered usefully by job label.
func (m *launchdManager) Logs(_ context.Context, n int) (string, error) {
	path := m.log
	if path == "" {
		path = filepath.Join("/var/log", m.unit+".log")
	}
	return tailFile(path, n)
}

func (m *launchdManager) LogCommand() string {
	path := m.log
	if path == "" {
		path = filepath.Join("/var/log", m.unit+".log")
	}
	return "tail -f " + path
}

// tailFile returns the last n lines of a file, which is all the failure path
// of a health check needs.
func tailFile(path string, n int) (string, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("installer: reading %s: %w", path, err)
	}
	lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
	if len(lines) > n {
		lines = lines[len(lines)-n:]
	}
	return strings.Join(lines, "\n"), nil
}

// writeFileAtomic writes through a temporary file and a rename, so that a
// crash halfway through never leaves a half-written unit that systemd would
// then refuse to parse.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".*")
	if err != nil {
		return err
	}
	name := tmp.Name()
	defer os.Remove(name)
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(mode); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(name, path)
}

package installer

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
)

// The Windows service manager. It has no build tag because nothing in it is
// Windows-specific to compile: it renders a command line and drives sc.exe,
// and both are things a test on any platform can watch through the fake
// command runner. The only Windows-only code the agent needs to run as a
// service is in cmd/zoomies, where the service control dispatcher lives.

// ServiceWindows registers the agent with the Windows service manager, which
// is how a Windows host keeps an agent running across logins and reboots the
// way systemd does on Linux.
const ServiceWindows ServiceKind = "windows"

// WindowsServiceName is the name the service is registered under. It is the
// unit name, so `sc.exe query zoomies-agent` and `systemctl status
// zoomies-agent` are the same question on either platform.
func WindowsServiceName(unit string) string {
	if unit == "" {
		return UnitController
	}
	return unit
}

// WindowsServiceCommand renders the command line the service manager runs.
//
// sc.exe takes the whole line as one argument and the service manager splits
// it again by the usual CommandLineToArgv rules, so every path is quoted
// whether or not it contains a space: C:\Program Files is the common case,
// and a line that only works for paths without spaces is a line that fails on
// the default install location.
//
// The log file is on the command line because a Windows service has no
// stderr anyone can read and no journal to send it to; --log-file is the
// agent's own answer to that.
func WindowsServiceCommand(spec ServiceSpec) (string, error) {
	if err := spec.defaults(); err != nil {
		return "", err
	}
	parts := []string{quoteWindowsArg(spec.ExecPath), spec.Command, "--config", quoteWindowsArg(spec.ConfigFile)}
	if spec.LogFile != "" {
		parts = append(parts, "--log-file", quoteWindowsArg(spec.LogFile))
	}
	return strings.Join(parts, " "), nil
}

// quoteWindowsArg wraps an argument in double quotes, escaping any it already
// carries, which is the CommandLineToArgv convention.
func quoteWindowsArg(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `\"`) + `"`
}

// windowsManager drives sc.exe for one service.
type windowsManager struct {
	unit string
	run  commandRunner
	// log is the file the service was installed with, remembered so Logs and
	// LogCommand can point at it.
	log string
}

func (m *windowsManager) Kind() ServiceKind { return ServiceWindows }

func (m *windowsManager) name() string { return WindowsServiceName(m.unit) }

// Install registers the service, replacing one that already exists so that a
// re-join with a different configuration path takes effect rather than
// leaving the old command line registered.
//
// The `key= value` spelling with the space after the equals sign is sc.exe's
// own: the key and the value are separate arguments to it, and writing them
// as one is the classic way an sc.exe invocation silently does nothing.
func (m *windowsManager) Install(ctx context.Context, spec ServiceSpec) (string, error) {
	spec.Unit = m.unit
	if err := spec.defaults(); err != nil {
		return "", err
	}
	cmd, err := WindowsServiceCommand(spec)
	if err != nil {
		return "", err
	}
	m.log = spec.LogFile
	if m.exists(ctx) {
		_, _ = m.run(ctx, "sc.exe", "stop", m.name())
		if _, err := m.run(ctx, "sc.exe", "delete", m.name()); err != nil {
			return "", err
		}
	}
	if _, err := m.run(ctx, "sc.exe", "create", m.name(),
		"binPath=", cmd,
		"start=", "auto",
		"DisplayName=", spec.Description,
	); err != nil {
		return "", fmt.Errorf("%w (this step needs an elevated prompt; run it as Administrator)", err)
	}
	// Failure actions are what Restart=always is on Linux: an agent that
	// crashes comes back, with a pause so a crash loop is not a busy loop.
	_, _ = m.run(ctx, "sc.exe", "failure", m.name(), "reset=", "86400", "actions=", "restart/5000/restart/5000/restart/30000")
	_, _ = m.run(ctx, "sc.exe", "description", m.name(), spec.Description)
	return m.name(), nil
}

func (m *windowsManager) Enable(ctx context.Context) error {
	_, err := m.run(ctx, "sc.exe", "config", m.name(), "start=", "auto")
	return err
}

func (m *windowsManager) Start(ctx context.Context) error {
	_, err := m.run(ctx, "sc.exe", "start", m.name())
	return err
}

// Stop is quiet about a service that is not registered or already stopped,
// because uninstall has to be safe to re-run.
func (m *windowsManager) Stop(ctx context.Context) error {
	if !m.exists(ctx) {
		return nil
	}
	out, err := m.run(ctx, "sc.exe", "stop", m.name())
	if err != nil && strings.Contains(out, "1062") {
		// ERROR_SERVICE_NOT_ACTIVE: stopping what is stopped is success.
		return nil
	}
	return err
}

func (m *windowsManager) Disable(ctx context.Context) error {
	if !m.exists(ctx) {
		return nil
	}
	_, err := m.run(ctx, "sc.exe", "config", m.name(), "start=", "disabled")
	return err
}

func (m *windowsManager) Remove(ctx context.Context) error {
	if !m.exists(ctx) {
		return nil
	}
	_, err := m.run(ctx, "sc.exe", "delete", m.name())
	return err
}

// Status reads the STATE line of `sc.exe query`, which is the word an
// operator would read themselves: RUNNING, STOPPED, START_PENDING.
func (m *windowsManager) Status(ctx context.Context) (string, error) {
	out, err := m.run(ctx, "sc.exe", "query", m.name())
	if err != nil {
		return "not installed", nil
	}
	for _, line := range strings.Split(out, "\n") {
		s := strings.TrimSpace(line)
		if !strings.HasPrefix(s, "STATE") {
			continue
		}
		fields := strings.Fields(s)
		return strings.ToLower(fields[len(fields)-1]), nil
	}
	return "installed", nil
}

// Logs tails the file the service writes, because a Windows service has no
// journal and the event log is not where a Go agent's structured lines go.
func (m *windowsManager) Logs(_ context.Context, n int) (string, error) {
	if m.log == "" {
		return "", errors.New("installer: the service was installed without a log file, so there is nothing to show; look at its --log-file argument in `sc.exe qc " + m.name() + "`")
	}
	return tailFile(m.log, n)
}

func (m *windowsManager) LogCommand() string {
	if m.log == "" {
		return "sc.exe qc " + m.name()
	}
	return "Get-Content -Wait " + quoteWindowsArg(m.log)
}

func (m *windowsManager) exists(ctx context.Context) bool {
	_, err := m.run(ctx, "sc.exe", "query", m.name())
	return err == nil
}

// prepareDirs creates the installer's directories and, on Windows, replaces
// each one's inherited ACL with one that only SYSTEM and Administrators can
// read.
//
// %ProgramData% is readable by every local user by default, and the agent's
// credentials live under it. On POSIX the 0600 on the credentials file is
// what keeps another account out; on Windows that mode is ignored and the
// directory's ACL is the only thing that does the same job. The platform and
// the runner are arguments so the icacls invocation is checked on every
// platform, not only the one it runs on.
func prepareDirs(ctx context.Context, goos string, run commandRunner, dirs ...string) error {
	for _, dir := range dirs {
		if err := os.MkdirAll(dir, 0o750); err != nil {
			return fmt.Errorf("installer: creating %s: %w", dir, err)
		}
		if err := restrictDir(ctx, goos, dir, run); err != nil {
			return fmt.Errorf("installer: restricting %s to administrators: %w (run this from an elevated prompt)", dir, err)
		}
	}
	return nil
}

// restrictDir is the ACL half of prepareDirs.
func restrictDir(ctx context.Context, goos, dir string, run commandRunner) error {
	if goos != "windows" {
		return nil
	}
	_, err := run(ctx, "icacls", dir, "/inheritance:r",
		"/grant:r", "SYSTEM:(OI)(CI)F", "/grant:r", "Administrators:(OI)(CI)F")
	return err
}

// windowsServiceInstalled reports whether the agent service is registered on
// this host, for uninstall, which has no unit file to look for.
func windowsServiceInstalled(ctx context.Context, unit string) bool {
	if lookPath("sc.exe") == "" {
		return false
	}
	_, err := runCommand(ctx, "sc.exe", "query", WindowsServiceName(unit))
	return err == nil
}

