package installer

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/eyupio/zoomies/internal/config"
)

// SharedHostDir is the shared folder of a container deployment: the host path
// the controller's container mounts at the same path, so a folder the embedded
// agent hands the host's daemon for a runner's mount is the same folder on
// both sides. It is config.SharedDir as the container sees it, which is why
// the container's state directory has to stay /var/lib/zoomies.
const SharedHostDir = ContainerStateDir + "/shared"

// sharedFolders is the shared folder and every folder this release keeps in
// it, parents first.
func sharedFolders(dir string) []string {
	out := []string{dir}
	for _, sub := range config.SharedLayout {
		out = append(out, filepath.Join(dir, filepath.FromSlash(sub)))
	}
	return out
}

// PrepareSharedDir creates the shared folder and its layout, owned by uid (the
// account Zoomies runs as there) where this process may say so, and returns
// the folders it created.
//
// The owner is the point. The folder is where later releases add folders of
// their own, at start, without an installer run -- so the account that runs
// Zoomies has to be able to write to it, not only read it. A folder that is
// already there is left as it is: an operator who put it on another disk or
// gave it another owner meant to.
func PrepareSharedDir(dir string, uid, gid int) ([]string, error) {
	var created []string
	for _, d := range sharedFolders(dir) {
		if _, err := os.Stat(d); err == nil {
			continue
		}
		if err := os.MkdirAll(d, 0o750); err != nil {
			return created, fmt.Errorf("installer: creating %s: %w", d, err)
		}
		if err := os.Chmod(d, 0o750); err != nil {
			return created, fmt.Errorf("installer: setting permissions on %s: %w", d, err)
		}
		if uid >= 0 {
			if err := os.Lchown(d, uid, gid); err != nil && !errors.Is(err, os.ErrPermission) {
				return created, fmt.Errorf("installer: giving %s to uid %d: %w", d, uid, err)
			}
		}
		created = append(created, d)
	}
	return created, nil
}

// SharedDirProblems says what is wrong with the shared folder for an account
// that has to write to it: each folder of the layout that is missing, and the
// shared folder itself when that account does not own it. Empty is ready.
func SharedDirProblems(dir string, uid int) []string {
	var out []string
	for _, d := range sharedFolders(dir) {
		fi, err := os.Stat(d)
		if err != nil {
			out = append(out, d+" is missing")
			continue
		}
		if d != dir || uid < 0 {
			continue
		}
		if owner, _, ok := fileOwner(fi); ok && owner != uid {
			out = append(out, fmt.Sprintf("%s is owned by uid %d, not uid %d, so Zoomies cannot add folders to it", d, owner, uid))
		}
	}
	return out
}

package installer

import (
	"os"
	"path"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"gopkg.in/yaml.v3"
)

// The container deployment mounts the shared folder at the path it has on the
// host. At any other path, the folder the embedded agent hands the host's
// daemon for a runner's tool cache would be one the daemon cannot see.
func TestTheComposeFileMountsTheSharedFolderAtItsOwnPath(t *testing.T) {
	body, err := RenderComposeFile(ComposeFileSpecFor(containerPlan(t)))
	if err != nil {
		t.Fatalf("RenderComposeFile: %v", err)
	}
	var doc struct {
		Services map[string]struct {
			Volumes []string `yaml:"volumes"`
		} `yaml:"services"`
	}
	if err := yaml.Unmarshal([]byte(body), &doc); err != nil {
		t.Fatalf("parsing: %v", err)
	}
	want := SharedHostDir + ":" + SharedHostDir
	for name, svc := range doc.Services {
		found := false
		for _, v := range svc.Volumes {
			if v == want {
				found = true
			}
		}
		if !found {
			t.Errorf("service %s does not mount %q: %v", name, want, svc.Volumes)
		}
	}
	// A path inside the container, so slash-separated whichever OS runs the
	// installer's tests.
	if SharedHostDir != path.Join(ContainerStateDir, "shared") {
		t.Errorf("SharedHostDir = %s, but the container's own shared folder is %s/shared", SharedHostDir, ContainerStateDir)
	}
}

// The layout is created parents first and reported, and a second run creates
// nothing: an upgrade that finds the folder already there changes nothing.
func TestPrepareSharedDirCreatesTheLayoutOnce(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "shared")
	created, err := PrepareSharedDir(dir, -1, -1)
	if err != nil {
		t.Fatalf("PrepareSharedDir: %v", err)
	}
	if len(created) != len(config.SharedLayout)+1 {
		t.Errorf("created %v, want the folder and every folder of the layout", created)
	}
	for _, sub := range config.SharedLayout {
		if fi, err := os.Stat(filepath.Join(dir, filepath.FromSlash(sub))); err != nil || !fi.IsDir() {
			t.Errorf("%s was not created: %v", sub, err)
		}
	}
	if again, _ := PrepareSharedDir(dir, -1, -1); len(again) != 0 {
		t.Errorf("a second run created %v", again)
	}
	if problems := SharedDirProblems(dir, -1); len(problems) != 0 {
		t.Errorf("problems = %v, want none", problems)
	}
}

// What is missing is named folder by folder, so an upgrade can say exactly
// what it would add.
func TestSharedDirProblemsNamesWhatIsMissing(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "shared")
	if err := os.Mkdir(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	problems := SharedDirProblems(dir, -1)
	if len(problems) != len(config.SharedLayout) {
		t.Fatalf("problems = %v, want one per folder of the layout", problems)
	}
	for _, p := range problems {
		if !strings.HasSuffix(p, " is missing") {
			t.Errorf("problem %q does not say what is missing", p)
		}
	}
	// The owner is checked only for an account that has to write.
	if uid := os.Getuid(); uid >= 0 {
		if got := SharedDirProblems(dir, uid+1); len(got) != len(config.SharedLayout)+1 {
			t.Errorf("problems for another uid = %v, want the owner named as well", got)
		}
	}
}

// A controller whose runners all run on other hosts keeps no caches, so it is
// given neither the folder nor the mount -- nor the question at upgrade.
func TestAControllerWithoutRunnersIsNotGivenTheSharedFolder(t *testing.T) {
	p := containerPlan(t)
	p.Mode, p.Embedded = ModeController, false
	body, err := RenderComposeFile(ComposeFileSpecFor(p))
	if err != nil {
		t.Fatalf("RenderComposeFile: %v", err)
	}
	if strings.Contains(body, SharedHostDir+":"+SharedHostDir) {
		t.Errorf("a controller that runs no runners mounts the shared folder:\n%s", body)
	}
}

package installer

// Whether the account the service will run as can actually open the container
// socket, decided before the service is started rather than discovered by an
// operator reading a stalled pool an hour later.
//
// The old rule was "if a group called docker exists, add the service user to
// it". It is right on a stock Docker install and wrong everywhere else: a
// Podman API socket, a distribution that names the group something else, a
// socket that was chgrp'd, or a mode with no group bits at all. In each of
// those the installer reported success and the fleet came up with a host that
// could run nothing. The socket itself knows who may open it, so it is asked.

import (
	"fmt"
	"io/fs"
	"os"
	"os/user"
	"strconv"
	"strings"
)

// socketFacts is what the filesystem says about a runtime socket.
type socketFacts struct {
	uid  int
	gid  int
	mode fs.FileMode
}

// statSocket reads the owner and mode of a socket path, following the symlink
// /var/run/docker.sock usually is.
func statSocket(path string) (socketFacts, bool) {
	p := SocketPathOf(path)
	if p == "" {
		return socketFacts{}, false
	}
	fi, err := os.Stat(p)
	if err != nil {
		return socketFacts{}, false
	}
	uid, gid, ok := fileOwner(fi)
	if !ok {
		return socketFacts{}, false
	}
	return socketFacts{uid: uid, gid: gid, mode: fi.Mode()}, true
}

// SocketPathOf turns an endpoint into a filesystem path, or "" when there is
// none to have: a TCP daemon has no mode and no group, and nothing here applies
// to it.
func SocketPathOf(endpoint string) string {
	e := strings.TrimSpace(endpoint)
	switch {
	case e == "":
		return ""
	case strings.HasPrefix(e, "tcp://"), strings.HasPrefix(e, "http://"), strings.HasPrefix(e, "https://"):
		return ""
	}
	return strings.TrimPrefix(e, "unix://")
}

// account is the identity the service will have: its uid, and every group the
// user database gives it.
type account struct {
	uid    int
	groups []int
}

// lookupAccount reads an account from the user database. It is deliberately not
// the running process's identity: the installer is usually root, and root can
// open anything, so asking about root would answer the wrong question.
func lookupAccount(name string) (account, error) {
	u, err := user.Lookup(name)
	if err != nil {
		return account{}, err
	}
	uid, err := strconv.Atoi(u.Uid)
	if err != nil {
		return account{}, fmt.Errorf("installer: %s has a non-numeric uid %q", name, u.Uid)
	}
	acct := account{uid: uid}
	ids, err := u.GroupIds()
	if err != nil {
		return account{}, err
	}
	for _, id := range ids {
		if gid, err := strconv.Atoi(id); err == nil {
			acct.groups = append(acct.groups, gid)
		}
	}
	return acct, nil
}

// canOpen reports whether an account may read and write a socket, by the same
// rule the kernel uses: owner, then group, then other, first match wins.
//
// Root is exempt, which is a fact rather than a recommendation: an installer
// that runs the service as root would pass this check and still be the thing
// the security model asks operators not to do.
func canOpen(s socketFacts, a account) bool {
	if a.uid == 0 {
		return true
	}
	const readWrite = 0o6
	var bits fs.FileMode
	switch {
	case a.uid == s.uid:
		bits = (s.mode.Perm() >> 6) & 0o7
	case containsInt(a.groups, s.gid):
		bits = (s.mode.Perm() >> 3) & 0o7
	default:
		bits = s.mode.Perm() & 0o7
	}
	return bits&readWrite == readWrite
}

// joinable reports whether adding the account to the socket's owning group
// would be enough. A mode of 0600 says no group membership can help, and
// telling somebody to run usermod anyway is how an install ends in a host that
// can run nothing.
func joinable(s socketFacts, a account) bool {
	if containsInt(a.groups, s.gid) {
		return false
	}
	const readWrite = 0o6
	return (s.mode.Perm()>>3)&readWrite == readWrite
}

// socketGroupName names the group that owns a socket, falling back to the gid,
// which usermod and `--group-add` both accept.
func socketGroupName(gid int) string {
	if g, err := user.LookupGroupId(strconv.Itoa(gid)); err == nil && g != nil && g.Name != "" {
		return g.Name
	}
	return strconv.Itoa(gid)
}

// SocketGroupGID returns the group that owns the socket this host will use, or
// the docker group when the socket cannot be examined -- a container deployment
// on a host where the installer cannot see the socket still has to write some
// gid into `--group-add`, and the docker group is the best guess available.
func SocketGroupGID(endpoint string) int {
	if s, ok := statSocket(endpoint); ok {
		return s.gid
	}
	return dockerGroupGID()
}

func containsInt(haystack []int, needle int) bool {
	for _, v := range haystack {
		if v == needle {
			return true
		}
	}
	return false
}

