package installer

import "io/fs"

// fileOwner has no answer off unix, where a socket has no owning group and
// none of the group handling around it applies.
func fileOwner(fs.FileInfo) (uid, gid int, ok bool) { return 0, 0, false }

package installer

import (
	"bytes"
	"context"
	"fmt"
	"io/fs"
	"net"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func sock(mode fs.FileMode, uid, gid int) socketFacts {
	return socketFacts{uid: uid, gid: gid, mode: fs.ModeSocket | mode}
}

func TestCanOpenFollowsTheKernelsRule(t *testing.T) {
	cases := []struct {
		name string
		s    socketFacts
		a    account
		want bool
	}{
		{"owner may", sock(0o600, 1001, 999), account{uid: 1001}, true},
		{"group member may", sock(0o660, 0, 999), account{uid: 1001, groups: []int{999}}, true},
		{"non-member may not", sock(0o660, 0, 999), account{uid: 1001, groups: []int{1001}}, false},
		// The rule is first match wins, not most permissive: an owner with no
		// owner bits is refused even when the group would have let them in.
		{"owner bits win over group bits", sock(0o060, 1001, 999), account{uid: 1001, groups: []int{999}}, false},
		{"world-writable socket", sock(0o666, 0, 0), account{uid: 1001}, true},
		{"root is exempt", sock(0o600, 0, 0), account{uid: 0}, true},
		// Read without write is not enough to drive a daemon.
		{"read-only group", sock(0o640, 0, 999), account{uid: 1001, groups: []int{999}}, false},
	}
	for _, c := range cases {
		if got := canOpen(c.s, c.a); got != c.want {
			t.Errorf("%s: canOpen = %v, want %v", c.name, got, c.want)
		}
	}
}

func TestJoinableOnlyWhenTheGroupWouldHelp(t *testing.T) {
	// The case the installer exists to catch: a mode with no group bits, where
	// usermod would succeed and change nothing.
	if joinable(sock(0o600, 0, 999), account{uid: 1001}) {
		t.Error("a socket with no group permissions is not fixed by joining its group")
	}
	if !joinable(sock(0o660, 0, 999), account{uid: 1001}) {
		t.Error("a group-writable socket is exactly what joining the group fixes")
	}
	// Already a member: whatever is wrong, it is not the membership.
	if joinable(sock(0o660, 0, 999), account{uid: 1001, groups: []int{999}}) {
		t.Error("an account already in the group has nothing to join")
	}
}

func TestSocketPathOfIgnoresEndpointsWithNoFile(t *testing.T) {
	cases := map[string]string{
		"unix:///var/run/docker.sock": "/var/run/docker.sock",
		"/var/run/docker.sock":        "/var/run/docker.sock",
		"tcp://10.0.0.5:2375":         "",
		"https://docker.example:2376": "",
		"":                            "",
		"  ":                          "",
	}
	for in, want := range cases {
		if got := SocketPathOf(in); got != want {
			t.Errorf("SocketPathOf(%q) = %q, want %q", in, got, want)
		}
	}
}

// The group to join comes from the socket, not from the name "docker": a Podman
// API socket, or a distribution that names the group something else, gave the
// old code the wrong gid and an install that looked like it had worked.
func TestSocketGroupGIDFallsBackWhenThereIsNoSocket(t *testing.T) {
	if got := SocketGroupGID("tcp://10.0.0.5:2375"); got != dockerGroupGID() {
		t.Errorf("SocketGroupGID = %d, want the docker group %d for an endpoint with no file", got, dockerGroupGID())
	}
}

// ensureSocketAccess reports rather than guesses. These drive the two branches
// that need no root and no second account on the machine: a socket that is not
// there yet, and an account that does not exist.
func TestEnsureSocketAccessOnAHostWithNoSocketYet(t *testing.T) {
	out := &bytes.Buffer{}
	i := &Installer{ui: newUI(out)}
	p := &Plan{Backend: store.BackendDocker, DockerHost: "unix://" + filepath.Join(t.TempDir(), "absent.sock"), ServiceUser: "zoomies"}

	i.ensureSocketAccess(context.Background(), p)

	if !strings.Contains(out.String(), "re-probes") {
		t.Errorf("a daemon that is not up yet is not a failure: %s", out)
	}
}

// socketsHaveOwners reports whether this build can say who owns a file, which
// is the question both tests below are really asking.
//
// Listening on a unix socket is not the platform test it looks like: Windows
// has had AF_UNIX for years, so the listen succeeds there and then fileOwner --
// which has no answer off unix by design -- leaves the socket with no owning
// group and no gid to name. A test guarded only by the listen therefore passes
// or fails by the runner it lands on, not by the code, which is how this one
// went green on one Windows image and red on the next.
func socketsHaveOwners(t *testing.T) bool {
	t.Helper()
	fi, err := os.Stat(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	_, _, ok := fileOwner(fi)
	return ok
}

func TestEnsureSocketAccessNamesTheCommandForAnAccountThatDoesNotExistYet(t *testing.T) {
	if !socketsHaveOwners(t) {
		t.Skip("this platform has no owning group for a socket, so there is no group to name")
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "docker.sock")
	l, err := net.Listen("unix", path)
	if err != nil {
		t.Skipf("unix sockets unavailable here: %v", err)
	}
	defer l.Close()

	out := &bytes.Buffer{}
	i := &Installer{ui: newUI(out)}
	p := &Plan{Backend: store.BackendDocker, DockerHost: "unix://" + path, ServiceUser: "no-such-account-here"}

	i.ensureSocketAccess(context.Background(), p)

	if !strings.Contains(out.String(), "usermod -aG") || !strings.Contains(out.String(), "no-such-account-here") {
		t.Errorf("want the command the operator will need, got: %s", out)
	}
	if p.DockerGID == 0 && os.Geteuid() != 0 {
		t.Errorf("the socket's own group must be recorded for the unit to name: %+v", p)
	}
}

// The process backend runs no containers, so nothing here applies to it.
func TestEnsureSocketAccessSkipsTheProcessBackend(t *testing.T) {
	out := &bytes.Buffer{}
	i := &Installer{ui: newUI(out)}
	i.ensureSocketAccess(context.Background(), &Plan{
		Backend: store.BackendProcess, DockerHost: "unix:///var/run/docker.sock", ServiceUser: "zoomies",
	})
	if out.Len() != 0 {
		t.Errorf("a process-backend install has no socket to talk about: %s", out)
	}
}

// The container deployment has no usermod to fall back on: a wrong DOCKER_GID
// is a container that comes up healthy and can run nothing, so the verdict is
// reached before the thing is started.
func TestJudgeContainerSocket(t *testing.T) {
	cases := []struct {
		name string
		s    socketFacts
		gid  int
		want containerSocketVerdict
	}{
		{"the gid that owns it", sock(0o660, 0, 987), 987, socketUsable},
		{"a gid that does not", sock(0o660, 0, 987), 986, socketWrongGID},
		{"no gid added at all", sock(0o660, 0, 987), 0, socketWrongGID},
		{"a mode with no group bits", sock(0o600, 0, 987), 987, socketNoGroupBits},
		{"group root, which is never added", sock(0o660, 0, 0), 0, socketRootGroup},
		{"a world-writable socket needs no group", sock(0o666, 0, 0), 0, socketUsable},
		// The image's own uid owning the socket is the rootless case.
		{"owned by the image's account", sock(0o600, ImageUID, 0), 0, socketUsable},
	}
	for _, c := range cases {
		if got := judgeContainerSocket(c.s, c.gid); got != c.want {
			t.Errorf("%s: verdict = %d, want %d", c.name, got, c.want)
		}
	}
}

// And the printing says the one thing an operator has to change.
func TestCheckContainerSocketAccessNamesTheGidToSet(t *testing.T) {
	if !socketsHaveOwners(t) {
		t.Skip("this platform has no owning group for a socket, so there is no gid to name")
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "docker.sock")
	l, err := net.Listen("unix", path)
	if err != nil {
		t.Skipf("unix sockets unavailable here: %v", err)
	}
	defer l.Close()
	if err := os.Chmod(path, 0o660); err != nil {
		t.Fatal(err)
	}
	facts, ok := statSocket(path)
	if !ok {
		t.Fatal("the socket must be readable by this test")
	}
	if facts.gid == 0 {
		// Running as root: the socket belongs to group root, which is the one
		// case that is deliberately never answered with a gid.
		t.Skip("this socket belongs to group root, covered by TestJudgeContainerSocket")
	}

	out := &bytes.Buffer{}
	i := &Installer{ui: newUI(out)}
	i.checkContainerSocketAccess(Plan{
		Deployment: DeploymentCompose, Mode: ModeSingle, Backend: store.BackendDocker,
		DockerHost: "unix://" + path, DockerGID: facts.gid + 1, Embedded: true,
	})

	if !strings.Contains(out.String(), fmt.Sprintf("DOCKER_GID=%d", facts.gid)) {
		t.Errorf("want the gid that actually owns the socket, got: %s", out)
	}
}

// A socket that is not there yet is not a failure: the agent re-probes.
func TestCheckContainerSocketAccessOnAHostWithNoSocket(t *testing.T) {
	out := &bytes.Buffer{}
	i := &Installer{ui: newUI(out)}
	i.checkContainerSocketAccess(Plan{
		Deployment: DeploymentCompose, Mode: ModeSingle, Backend: store.BackendDocker,
		DockerHost: "unix://" + filepath.Join(t.TempDir(), "absent.sock"), Embedded: true,
	})
	if !strings.Contains(out.String(), "re-probes") {
		t.Errorf("want the daemon-not-up-yet note, got: %s", out)
	}
}

//go:build unix

package installer

import (
	"io/fs"
	"syscall"
)

// fileOwner reads a file's uid and gid.
func fileOwner(fi fs.FileInfo) (uid, gid int, ok bool) {
	st, ok := fi.Sys().(*syscall.Stat_t)
	if !ok {
		return 0, 0, false
	}
	return int(st.Uid), int(st.Gid), true
}

# Zoomies, deployed with Docker Compose.
#
# Written by `zoomies init`. Every value this reads is in the .env file beside
# it, already filled in -- there is nothing to edit here before it will run.
{{- if ne .Command "agent" }}
# The controller's settings are in its database, and change on its settings
# page; this file and .env only start it:
{{- end }}
#
#     docker compose up -d
#
{{if eq .Command "agent" -}}
# The .env holds this host's agent token, so it is mode 0600 and belongs in
# neither a repository nor a backup that anyone can read. This file has no
# secrets in it and is safe to keep under version control.
{{- else -}}
# The .env holds the instance encryption key, so it is mode 0600 and belongs in
# neither a repository nor a backup that anyone can read. This file has no
# secrets in it and is safe to keep under version control.
{{- end}}

name: zoomies

services:
  zoomies:
    image: ${ZOOMIES_IMAGE}
    restart: unless-stopped
    # Finish admitted runner creation before replacing the service.
    stop_grace_period: 20m
    container_name: {{.Container}}
    # The last segment of the name the embedded agent registers this host
    # under, which is otherwise derived from what the machine is:
    # zoomies-8vcpu-32gb-ubuntu-2404-<this>. Without the line that segment is
    # the container's random twelve-hex-digit ID, which then follows the host
    # into every scheduler reason and problem message. A dedicated agent does
    # not rely on it -- it is told its whole name outright, because this line
    # reads the same on every machine running this file.
    hostname: {{.Container}}
    command: ["{{.Command}}"]
    environment:
{{- if eq .Command "agent" }}
      # The controller this host takes work from, and the token it joins with
      # the first time it starts. The join writes a lasting credential into the
      # state volume, so the token is spent once and every later start reads
      # the volume instead.
      ZOOMIES_CONTROLLER_URL: ${ZOOMIES_CONTROLLER_URL:?set this in .env}
      ZOOMIES_JOIN_TOKEN: ${ZOOMIES_JOIN_TOKEN:?set this in .env}
      # Set explicitly because this container's hostname is the same on every
      # machine that runs this file, and the name is derived from it.
      ZOOMIES_AGENT_NAME: ${ZOOMIES_AGENT_NAME:?set this in .env}

      # An agent has no database, so its settings are these.
      ZOOMIES_AGENT_BACKEND: ${ZOOMIES_AGENT_BACKEND}
      ZOOMIES_DOCKER_HOST: ${ZOOMIES_DOCKER_HOST}
      ZOOMIES_AGENT_CAPACITY: ${ZOOMIES_AGENT_CAPACITY}
      # The network runner containers are attached to: the one declared at the
      # bottom of this file. Without it they land on the daemon's default
      # bridge.
      ZOOMIES_AGENT_NETWORK: ${ZOOMIES_AGENT_NETWORK}
      ZOOMIES_WORK_DIR: ${ZOOMIES_WORK_DIR}
      ZOOMIES_LOG_FORMAT: ${ZOOMIES_LOG_FORMAT}
      ZOOMIES_LOG_LEVEL: ${ZOOMIES_LOG_LEVEL}
{{- else }}
      # 32 bytes, base64. Everything secret in the database is sealed with it.
      # Back it up: without it the stored GitHub App key cannot be decrypted.
      ZOOMIES_ENCRYPTION_KEY: ${ZOOMIES_ENCRYPTION_KEY:?set this in .env}
      # Every other setting -- the external URL, TLS, the embedded agent --
      # lives in the database, where the settings page changes it. One named
      # here would override it there, and the page would show it as locked.
{{- end }}

      # Generated run-time data -- a self-signed certificate above all -- goes
      # into the volume, so replacing the container does not change it.
      ZOOMIES_STATE_DIR: ${ZOOMIES_STATE_DIR}
      ZOOMIES_DB_PATH: ${ZOOMIES_DB_PATH}
{{- if .GroupAdd }}

      # The gid group_add below is given, echoed in so that if it is ever
      # wrong the Hosts page can name the line in .env to change.
      DOCKER_GID: ${DOCKER_GID}
{{- end }}
{{- if .Publish }}
    ports:
      # Published as ${ZOOMIES_PUBLISHED_ADDR}:${ZOOMIES_PUBLISHED_PORT}. On
      # 127.0.0.1 only this host and whatever proxies from it can connect; open
      # it wider only once something in front terminates TLS, or put the origin
      # behind a firewall that allows only your proxy's ranges.
      - "${ZOOMIES_PUBLISHED_ADDR}:${ZOOMIES_PUBLISHED_PORT}:{{.ContainerPort}}"
{{- end }}
    volumes:
      - {{.Volume}}:/var/lib/zoomies
{{- if .MountShared }}
      # The shared folder: runners' caches, one folder per purpose, and the
      # place later releases add folders of their own. It is mounted at the
      # path it has on this host, so a folder the controller hands this host's
      # daemon for a runner's mount is the same folder on both sides. Owned by
      # uid 65532, the image's account, so Zoomies can add to it as it runs.
      - {{.SharedDir}}:{{.SharedDir}}
{{- end }}
{{- if .MountSocket }}
      # The embedded agent needs this socket to create runner containers. This
      # is Zoomies' own access to the runtime -- it is NOT the same thing as
      # pool.docker_mode=host-socket, which would hand the socket to your jobs.
      - {{.SocketPath}}:{{.SocketPath}}
{{- end }}
{{- if .TLSCertFile }}
      # The certificate and key are mounted at the same paths they have on this
      # host, which is why the TLS settings can name them directly.
      - {{.TLSCertFile}}:{{.TLSCertFile}}:ro
      - {{.TLSKeyFile}}:{{.TLSKeyFile}}:ro
{{- end }}
{{- if .GroupAdd }}
    # The image runs as uid 65532; that user must be able to use the socket.
    # On most hosts that means adding the docker group's gid here.
    group_add:
      - "${DOCKER_GID}"
{{- end }}
    networks: [zoomies]
{{- if .Healthcheck }}
    healthcheck:
      test: ["CMD", "/usr/local/bin/zoomies", "healthcheck", "--url", "http://127.0.0.1:{{.ContainerPort}}"]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 20s
{{- end }}

volumes:
  {{.Volume}}:

networks:
  # Runner containers are attached to this network by the embedded agent, which
  # keeps them off the host network and off the default bridge.
  zoomies:
    name: {{.Network}}

package installer

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/cryptox"
	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// UninstallOptions configures `zoomies uninstall`.
type UninstallOptions struct {
	ConfigDir string
	StateDir  string
	// BinaryPath is removed last, so that a failure part-way through still
	// leaves a binary that can finish the job.
	BinaryPath string
	// ServiceUser is the account to remove. Empty means "zoomies" when running
	// as root, and nothing otherwise.
	ServiceUser string

	// Yes skips the confirmation. It does not skip the summary: an operator
	// running this from a script still gets a record of what went.
	Yes bool
	// NonInteractive forbids prompting, which means Yes must be set for
	// anything to be removed.
	NonInteractive bool
	// Deregister decides the GitHub cleanup without asking. Nil asks.
	Deregister *bool
	// RemoveVolume decides whether a containerised deployment's data volume
	// goes with it. Nil asks, and a run that cannot ask keeps the volume: the
	// volume is the database, and an uninstaller that deletes one nobody
	// mentioned is not one anybody runs twice.
	RemoveVolume *bool
	// KeepConfig leaves zoomies.yaml in place, for an operator who edited it
	// and wants to keep their work.
	KeepConfig bool

	Out    io.Writer
	In     io.Reader
	Logger *slog.Logger
}

func (o UninstallOptions) configDir() string {
	if o.ConfigDir != "" {
		return o.ConfigDir
	}
	return config.ConfigDir()
}

func (o UninstallOptions) stateDir() string {
	if o.StateDir != "" {
		return o.StateDir
	}
	return config.StateDir()
}

// sameDir reports whether two paths are the same directory.
//
// It asks the filesystem rather than comparing strings, so a symlink, a
// trailing slash or a relative path cannot make one directory look like two --
// which here would mean deleting a configuration the operator asked to keep.
// String comparison is the fallback for a path that cannot be stat'd, where
// being wrong costs nothing that is not already missing.
func sameDir(a, b string) bool {
	fa, err := os.Stat(a)
	if err != nil {
		return filepath.Clean(a) == filepath.Clean(b)
	}
	fb, err := os.Stat(b)
	if err != nil {
		return filepath.Clean(a) == filepath.Clean(b)
	}
	return os.SameFile(fa, fb)
}

// RemovalItem is one thing uninstall is about to do, listed before it does any
// of it. An uninstaller that surprises you is not one you run twice.
type RemovalItem struct {
	What string
	Path string
	// Present is false for something already gone, which is normal on a
	// re-run and is printed as "already gone" rather than hidden.
	Present bool
	// Note explains anything unobvious about this item.
	Note string
}

// UninstallItems lists what would be removed from these directories. It takes
// its paths as arguments so that it can be tested against a temporary
// directory rather than against the real /etc.
func UninstallItems(opts UninstallOptions) []RemovalItem {
	cfgDir, stateDir := opts.configDir(), opts.stateDir()
	var items []RemovalItem

	// A containerised deployment is listed first because it is the part an
	// operator would otherwise not see going: a compose project left running
	// keeps creating runners long after the files are gone.
	if rec, ok := ReadDeploymentRecord(cfgDir); ok {
		items = append(items, deploymentItems(rec, opts)...)
	}

	items = append(items, []RemovalItem{
		{What: "service", Path: SystemdUnitPath(UnitController), Present: exists(SystemdUnitPath(UnitController)),
			Note: "stopped and disabled first"},
		{What: "agent service", Path: SystemdUnitPath(UnitAgent), Present: exists(SystemdUnitPath(UnitAgent))},
		{What: "database", Path: filepath.Join(stateDir, "zoomies.db"), Present: exists(filepath.Join(stateDir, "zoomies.db")),
			Note: "pools, runners, job history and the audit log"},
		{What: "state directory", Path: stateDir, Present: exists(stateDir)},
		{What: "encryption key", Path: filepath.Join(cfgDir, "encryption.key"), Present: exists(filepath.Join(cfgDir, "encryption.key")),
			Note: "the GitHub App private key and webhook secrets cannot be decrypted without it"},
	}...)
	cfgFile := filepath.Join(cfgDir, "zoomies.yaml")
	if opts.KeepConfig {
		items = append(items, RemovalItem{What: "configuration", Path: cfgFile, Present: exists(cfgFile),
			Note: "kept, because you asked"})
	} else {
		items = append(items, RemovalItem{What: "configuration", Path: cfgFile, Present: exists(cfgFile)})
	}
	if opts.BinaryPath != "" {
		items = append(items, RemovalItem{What: "binary", Path: opts.BinaryPath, Present: exists(opts.BinaryPath),
			Note: "removed last"})
	}
	return items
}

// deploymentItems lists what a containerised deployment leaves on this host,
// in the words the operator will recognise from setup.
func deploymentItems(rec DeploymentRecord, opts UninstallOptions) []RemovalItem {
	what := "compose project"
	if rec.Deployment == DeploymentDocker {
		what = "container"
	}
	target := rec.ComposeFile()
	note := "brought down with `" + strings.Join(rec.ComposeCommand, " ") + " down`"
	if rec.Deployment == DeploymentDocker {
		target = containerOr(rec)
		note = "stopped and removed"
	}
	items := []RemovalItem{
		{What: what, Path: target, Present: true, Note: note},
	}
	if rec.Image != "" {
		items = append(items, RemovalItem{What: "container image", Path: rec.Image, Present: true,
			Note: "removed after the container"})
	}
	if rec.EnvFile != "" {
		// The volume question is asked after this list is printed, so the note
		// has to be true whichever way it is answered.
		envNote := "it holds the encryption key, so it is kept unless the data volume is deleted too"
		if opts.RemoveVolume != nil && *opts.RemoveVolume {
			envNote = "it holds the encryption key; removed with the data volume it seals"
		}
		items = append(items, RemovalItem{What: "environment file", Path: rec.EnvFile, Present: exists(rec.EnvFile), Note: envNote})
	}
	volumeNote := "the database; kept unless you say otherwise"
	if opts.RemoveVolume != nil && *opts.RemoveVolume {
		volumeNote = "the database -- removing it destroys every pool, runner, job and audit row"
	}
	items = append(items, RemovalItem{What: "data volume", Path: volumeOr(rec), Present: true, Note: volumeNote})
	items = append(items, RemovalItem{What: "deployment record", Path: DeploymentRecordPath(opts.configDir()),
		Present: exists(DeploymentRecordPath(opts.configDir()))})
	return items
}

// Uninstall removes Zoomies from this host.
//
// The order is the point. Runners are deregistered from GitHub first, while
// the credentials to do it still exist: after the database is gone those
// registrations become orphans that somebody has to delete by hand, one at a
// time, in a web UI. Everything else is removed in an order that leaves a
// half-finished run recoverable, and every step tolerates having been done
// already, so this is safe to run twice.
func Uninstall(ctx context.Context, opts UninstallOptions) error {
	if opts.Out == nil {
		opts.Out = os.Stdout
	}
	if opts.In == nil {
		opts.In = os.Stdin
	}
	if opts.Logger == nil {
		opts.Logger = slog.Default()
	}
	u := newUI(opts.Out)
	log := opts.Logger.With("component", "installer.uninstall")

	items := UninstallItems(opts)
	u.step("This will remove Zoomies from this host")
	anything := false
	for _, it := range items {
		if !it.Present {
			u.note(fmt.Sprintf("%-16s %s -- already gone", it.What, it.Path))
			continue
		}
		anything = true
		line := fmt.Sprintf("%-16s %s", it.What, it.Path)
		if it.Note != "" {
			line += "  (" + it.Note + ")"
		}
		u.note(line)
	}
	if !anything {
		u.ok("nothing to remove; Zoomies is not installed here.")
		return nil
	}
	u.blank()

	if !opts.Yes {
		if opts.NonInteractive {
			return errors.New("installer: refusing to remove anything without confirmation; re-run with --yes")
		}
		ok, err := askYesNo(opts.In, opts.Out, "Remove all of this? Type yes to confirm: ")
		if err != nil {
			return err
		}
		if !ok {
			return errors.New("installer: nothing was removed")
		}
	}

	var done []string
	var left []string
	record := func(format string, a ...any) {
		line := fmt.Sprintf(format, a...)
		done = append(done, line)
		u.ok(line)
	}
	keep := func(format string, a ...any) {
		line := fmt.Sprintf(format, a...)
		left = append(left, line)
		u.note("left in place: " + line)
	}

	// --- Stop the service first, so nothing creates new runners while we are
	// deregistering the old ones. -----------------------------------------
	if windowsServiceInstalled(ctx, UnitAgent) {
		if mgr, err := NewServiceManager(ServiceWindows, UnitAgent); err == nil {
			if err := mgr.Stop(ctx); err != nil {
				u.warn("could not stop " + UnitAgent + ": " + err.Error())
			}
			if err := mgr.Remove(ctx); err != nil {
				u.warn("could not remove the " + UnitAgent + " service: " + err.Error())
			} else {
				record("stopped and removed the %s service", UnitAgent)
			}
		}
	}
	for _, unit := range []string{UnitController, UnitAgent} {
		if !exists(SystemdUnitPath(unit)) {
			continue
		}
		mgr, err := NewServiceManager(ServiceSystemd, unit)
		if err != nil {
			u.warn(err.Error())
			continue
		}
		if err := mgr.Stop(ctx); err != nil {
			u.warn("could not stop " + unit + ": " + err.Error())
		}
		if err := mgr.Disable(ctx); err != nil {
			u.warn("could not disable " + unit + ": " + err.Error())
		}
		record("stopped and disabled %s", unit)
	}

	// --- Bring a containerised deployment down, for the same reason: a
	// running container would carry on creating runners while we deregister
	// the ones it has already made. -----------------------------------------
	volumeKept := false
	if rec, ok := ReadDeploymentRecord(opts.configDir()); ok {
		removeVolume, err := wantsVolumeRemoved(opts, u, rec)
		if err != nil {
			return err
		}
		volumeKept = !removeVolume
		tearDownDeployment(ctx, rec, removeVolume, u, record)
	}

	// --- Deregister runners from GitHub, before the credentials go. -------
	if err := maybeDeregister(ctx, opts, u, log, record); err != nil {
		// A GitHub failure must not strand the operator with a half-removed
		// install; it is reported and the removal continues.
		u.warn("could not deregister runners: " + err.Error())
		u.note("delete any leftover self-hosted runners by hand under your organisation's Actions settings.")
	}

	// --- Unit files -------------------------------------------------------
	for _, unit := range []string{UnitController, UnitAgent} {
		path := SystemdUnitPath(unit)
		if !exists(path) {
			continue
		}
		mgr, err := NewServiceManager(ServiceSystemd, unit)
		if err == nil {
			if err := mgr.Remove(ctx); err != nil {
				u.warn(err.Error())
				continue
			}
		} else if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
			u.warn("could not remove " + path + ": " + err.Error())
			continue
		}
		record("removed %s", path)
	}
	for _, label := range []string{"sh.zoomies.controller", "sh.zoomies.agent"} {
		for _, root := range []bool{true, false} {
			path := LaunchdPlistPath(label, root)
			if !exists(path) {
				continue
			}
			if err := os.Remove(path); err != nil {
				u.warn("could not remove " + path + ": " + err.Error())
				continue
			}
			record("removed %s", path)
		}
	}

	// --- State ------------------------------------------------------------
	stateDir := opts.stateDir()
	cfgDir := opts.configDir()

	// These two are the same directory on macOS, and on Linux for anyone but
	// root -- config.StateDir and config.ConfigDir both answer
	// ~/Library/Application Support/zoomies, or os.UserConfigDir()/zoomies,
	// and only a root install separates /var/lib/zoomies from /etc/zoomies.
	//
	// So RemoveAll here took the configuration with the database on most
	// installations: the zoomies.yaml --keep-config had just promised to keep,
	// the encryption key, and whatever else the operator had put in there. The
	// careful handling below -- keep the file, remove the directory only when
	// it is empty, name what is left -- ran afterwards on a directory that was
	// already gone, found nothing, and said nothing. The report claimed the
	// state directory had been removed and left the rest unmentioned.
	//
	// When they are one directory the state is removed by name instead, and
	// the configuration below is left to be dealt with on its own terms.
	if exists(stateDir) {
		if sameDir(stateDir, cfgDir) {
			for _, name := range []string{"zoomies.db", "zoomies.db-wal", "zoomies.db-shm", "work"} {
				path := filepath.Join(stateDir, name)
				if !exists(path) {
					continue
				}
				if err := os.RemoveAll(path); err != nil {
					u.warn("could not remove " + path + ": " + err.Error())
					continue
				}
				record("removed %s", path)
			}
		} else if err := os.RemoveAll(stateDir); err != nil {
			u.warn("could not remove " + stateDir + ": " + err.Error())
		} else {
			record("removed %s, including the database", stateDir)
		}
	}

	// --- Configuration ----------------------------------------------------
	cfgFile := filepath.Join(cfgDir, "zoomies.yaml")
	if opts.KeepConfig && exists(cfgFile) {
		keep("%s", cfgFile)
	} else if exists(cfgFile) {
		if err := os.Remove(cfgFile); err != nil {
			u.warn("could not remove " + cfgFile + ": " + err.Error())
		} else {
			record("removed %s", cfgFile)
		}
	}
	if rec, ok := ReadDeploymentRecord(cfgDir); ok {
		paths := []string{rec.ComposeFile(), DeploymentRecordPath(cfgDir)}
		// The environment file is the only copy of the encryption key that
		// seals the data volume. A volume that is kept is unreadable without
		// it -- a later install would mint a new key, and every stored GitHub
		// App private key and webhook secret would fail to decrypt -- so the
		// key stays exactly as long as the volume does, and is named so the
		// operator knows a secret is still on this host.
		//
		// The backups this installer made hold the key too, so they follow the
		// file they are copies of, in either direction: leaving one behind
		// when the volume goes would undo the care taken to remove the key at
		// all.
		var keyFiles []string
		if rec.EnvFile != "" {
			backups, _ := filepath.Glob(rec.EnvFile + ".bak.*")
			keyFiles = append([]string{rec.EnvFile}, backups...)
		}
		if volumeKept {
			for _, path := range keyFiles {
				if exists(path) {
					keep("%s, which holds the encryption key for the %s volume that was kept; "+
						"a later install reuses it, so keep it safe, and delete it once the volume is gone", path, volumeOr(rec))
				}
			}
		} else {
			paths = append(paths, keyFiles...)
		}
		for _, path := range paths {
			if path == "" || !exists(path) {
				continue
			}
			if err := os.Remove(path); err != nil {
				u.warn("could not remove " + path + ": " + err.Error())
				continue
			}
			record("removed %s", path)
		}
	}
	keyFile := filepath.Join(cfgDir, "encryption.key")
	if exists(keyFile) {
		if err := os.Remove(keyFile); err != nil {
			u.warn("could not remove " + keyFile + ": " + err.Error())
		} else {
			record("removed %s", keyFile)
		}
	}
	// Anything else in the config directory belongs to the operator --
	// certificates they put there, a backup this installer made -- so the
	// directory is removed only when it is empty, and what is left is named.
	if exists(cfgDir) {
		if remaining, err := os.ReadDir(cfgDir); err == nil {
			if len(remaining) == 0 {
				if err := os.Remove(cfgDir); err == nil {
					record("removed %s", cfgDir)
				}
			} else {
				names := make([]string, 0, len(remaining))
				for _, e := range remaining {
					names = append(names, e.Name())
				}
				sort.Strings(names)
				keep("%s, which still holds %s", cfgDir, strings.Join(names, ", "))
			}
		}
	}

	// --- The service account ---------------------------------------------
	if name := serviceUserToRemove(opts); name != "" {
		if err := removeServiceUser(ctx, name); err != nil {
			u.warn("could not remove the " + name + " user: " + err.Error())
		} else {
			record("removed the %s system user", name)
		}
	}

	// --- The binary, last -------------------------------------------------
	if opts.BinaryPath != "" && exists(opts.BinaryPath) {
		if err := os.Remove(opts.BinaryPath); err != nil {
			u.warn("could not remove " + opts.BinaryPath + ": " + err.Error())
			u.note("remove it by hand: sudo rm " + opts.BinaryPath)
		} else {
			record("removed %s", opts.BinaryPath)
		}
	}

	u.blank()
	u.step("Done")
	for _, line := range done {
		u.note(line)
	}
	for _, line := range left {
		u.note("left: " + line)
	}
	if len(left) == 0 {
		u.note("nothing was left behind.")
	}
	return nil
}

// wantsVolumeRemoved settles whether the data volume goes too.
//
// It is a separate question from the rest of uninstall because it is the one
// irreversible answer: the volume is the database, and nothing about the
// container being gone implies the operator wanted their job history, pools
// and audit log gone with it. Silence keeps it.
func wantsVolumeRemoved(opts UninstallOptions, u *ui, rec DeploymentRecord) (bool, error) {
	if opts.RemoveVolume != nil {
		return *opts.RemoveVolume, nil
	}
	if opts.NonInteractive || opts.Yes {
		u.note("keeping the " + volumeOr(rec) + " volume, which is the database; pass --volumes to delete it too.")
		return false, nil
	}
	u.blank()
	u.step("Delete the " + volumeOr(rec) + " volume as well?")
	u.note("that volume is the database: pools, runners, job history and the audit log. Deleting it")
	u.note("cannot be undone, and keeping it lets a later install pick up exactly where this left off:")
	u.note("the environment file that holds its encryption key is kept with it, and goes only if the volume does.")
	return askYesNo(opts.In, opts.Out, "Delete the volume? [y/N]: ")
}

// maybeDeregister offers, and then performs, the GitHub cleanup. It is offered
// first and done first because the credentials that make it possible are about
// to be deleted.
func maybeDeregister(ctx context.Context, opts UninstallOptions, u *ui, log *slog.Logger, record func(string, ...any)) error {
	dbPath := filepath.Join(opts.stateDir(), "zoomies.db")
	keyPath := filepath.Join(opts.configDir(), "encryption.key")
	if !exists(dbPath) || !exists(keyPath) {
		return nil
	}

	want := true
	switch {
	case opts.Deregister != nil:
		want = *opts.Deregister
	case opts.NonInteractive || opts.Yes:
		// Deregistering is the helpful default: leaving orphaned registrations
		// behind creates manual work for somebody later.
		want = true
	default:
		u.blank()
		u.step("Deregister this fleet's runners from GitHub first?")
		u.note("after the database is removed, the credentials are gone and every registration GitHub still")
		u.note("holds becomes an orphan that has to be deleted by hand in the Actions settings.")
		ok, err := askYesNo(opts.In, opts.Out, "Deregister them now? [Y/n]: ")
		if err != nil {
			return err
		}
		want = ok
	}
	if !want {
		u.note("leaving the GitHub registrations alone; delete them under your organisation's Actions settings.")
		return nil
	}

	key, err := cryptox.LoadKeyFile(keyPath)
	if err != nil {
		return err
	}
	// Read-only: an uninstall reads this database to find the registrations
	// GitHub still holds, and has no business migrating the schema of a
	// deployment on its way out.
	st, err := store.Open(ctx, store.Options{Path: dbPath, ReadOnly: true})
	if err != nil {
		return fmt.Errorf("opening %s: %w", dbPath, err)
	}
	defer st.Close()

	installations, err := st.ListInstallations(ctx)
	if err != nil {
		return err
	}
	local, err := allRunners(ctx, st)
	if err != nil {
		return err
	}
	factory := github.NewAppFactory(nil)
	removed := 0
	for _, inst := range installations {
		pem, err := key.OpenString(inst.PrivateKeyEnc)
		if err != nil {
			u.warn(fmt.Sprintf("cannot decrypt the private key for %s: %s", inst.Target, err))
			continue
		}
		client, err := factory.For(ctx, inst, []byte(pem))
		if err != nil {
			u.warn(fmt.Sprintf("cannot authenticate for %s: %s", inst.Target, err))
			continue
		}
		runners, err := client.ListRunners(ctx)
		if err != nil {
			u.warn(fmt.Sprintf("cannot list runners for %s: %s", inst.Target, err))
			continue
		}
		for _, r := range fleetRunners(runners, local) {
			if err := client.DeleteRunner(ctx, r.ID); err != nil {
				u.warn(fmt.Sprintf("could not deregister %s: %s", r.Name, err))
				continue
			}
			log.Info("deregistered runner", "name", r.Name, "target", inst.Target)
			removed++
		}
	}
	if removed > 0 {
		record("deregistered %d runner(s) from GitHub", removed)
	} else {
		u.note("no runners of this fleet were still registered with GitHub.")
	}
	return nil
}

// allRunners reads every runner row this database has, removed ones included:
// a registration GitHub still holds for a runner this fleet has already
// removed is exactly the orphan the uninstall is here to clean up.
func allRunners(ctx context.Context, st *store.Store) ([]*store.Runner, error) {
	var out []*store.Runner
	for offset := 0; ; {
		page, _, err := st.ListRunners(ctx, store.RunnerFilter{IncludeRemoved: true}, store.Page{Limit: 500, Offset: offset})
		if err != nil {
			return nil, fmt.Errorf("listing this fleet's runners: %w", err)
		}
		out = append(out, page...)
		if len(page) < 500 {
			return out, nil
		}
		offset += len(page)
	}
}

// fleetRunners returns the registrations that are this fleet's to delete: the
// ones whose GitHub ID or name the local database has a row for.
//
// Runner names carry no instance identity -- a second controller on the same
// organisation names its runners the same way -- so the "zoomies-" prefix
// alone had uninstalling a staging controller delete a production
// controller's idle runners. A registration the database has never heard of
// is left alone, whatever it is called.
func fleetRunners(remote []github.Runner, local []*store.Runner) []github.Runner {
	ids := make(map[int64]bool, len(local))
	names := make(map[string]bool, len(local))
	for _, r := range local {
		if r.GitHubRunnerID != 0 {
			ids[r.GitHubRunnerID] = true
		}
		names[r.Name] = true
	}
	var out []github.Runner
	for _, r := range remote {
		if ids[r.ID] || names[r.Name] {
			out = append(out, r)
		}
	}
	return out
}

// serviceUserToRemove decides whether there is an account to remove.
//
// Three conditions have to hold, and each one exists to stop a different way of
// deleting the wrong account: it must be the dedicated account this installer
// creates, this must be a root install in the system directories (a per-user
// install never created an account, and a run pointed at some other directory
// is not the one that owns /etc/zoomies), and the account must still exist.
func serviceUserToRemove(opts UninstallOptions) string {
	name := opts.ServiceUser
	if name == "" {
		name = "zoomies"
	}
	if name != "zoomies" {
		return ""
	}
	if os.Geteuid() != 0 {
		return ""
	}
	if opts.configDir() != "/etc/zoomies" || opts.stateDir() != "/var/lib/zoomies" {
		return ""
	}
	if !userExists(name) {
		return ""
	}
	return name
}

func removeServiceUser(ctx context.Context, name string) error {
	switch {
	case lookPath("userdel") != "":
		_, err := runCommand(ctx, "userdel", name)
		return err
	case lookPath("deluser") != "":
		_, err := runCommand(ctx, "deluser", name)
		return err
	default:
		return fmt.Errorf("no userdel or deluser on this host; remove the %s account by hand", name)
	}
}

// askYesNo reads a plain confirmation. It deliberately does not use the TUI:
// uninstall often runs over a pipe, in a script, or on a host where the
// terminal is barely a terminal.
func askYesNo(in io.Reader, out io.Writer, prompt string) (bool, error) {
	fmt.Fprint(out, prompt)
	sc := bufio.NewScanner(in)
	if !sc.Scan() {
		if err := sc.Err(); err != nil {
			return false, fmt.Errorf("installer: reading your answer: %w", err)
		}
		return false, nil
	}
	answer := strings.ToLower(strings.TrimSpace(sc.Text()))
	switch answer {
	case "y", "yes":
		return true, nil
	case "":
		// An empty line takes the prompt's default, which every prompt here
		// writes out in full rather than relying on capitalisation.
		return strings.Contains(prompt, "[Y/n]"), nil
	default:
		return false, nil
	}
}

