// Runner names carry no instance identity, so the "zoomies-" prefix used to
// be the whole test of ownership: uninstalling a staging controller deleted a
// production controller's idle runners on the same organisation.
func TestUninstallDeregistersOnlyTheRunnersThisDatabaseKnows(t *testing.T) {
	remote := []github.Runner{
		{ID: 1, Name: "zoomies-ours-by-id"},
		{ID: 2, Name: "zoomies-ours-by-name"},
		{ID: 3, Name: "zoomies-someone-elses-controller"},
		{ID: 4, Name: "hand-registered"},
	}
	local := []*store.Runner{
		{Name: "zoomies-renamed-on-github", GitHubRunnerID: 1},
		{Name: "zoomies-ours-by-name"},
	}
	got := fleetRunners(remote, local)
	ids := make([]int64, 0, len(got))
	for _, r := range got {
		ids = append(ids, r.ID)
	}
	if !slices.Equal(ids, []int64{1, 2}) {
		t.Fatalf("would deregister %v, want only the two this database has rows for", ids)
	}
}

// On most installations the config directory and the state directory are one
// directory, and --keep-config has to survive that.
//
// config.StateDir and config.ConfigDir both answer ~/Library/Application
// Support/zoomies on macOS, and os.UserConfigDir()/zoomies for a non-root
// Linux install; only a root install separates /var/lib/zoomies from
// /etc/zoomies. Uninstall used RemoveAll on the state directory, so on every
// one of those it deleted the configuration too -- the zoomies.yaml just
// promised to be kept, the encryption key, and anything else in there -- and
// then reported only that the state directory had gone.
//
// The encryption key is the part that does not come back. It is the only copy,
// and without it the stored App private keys and webhook secrets in any backup
// the operator still holds cannot be decrypted.
//
// Every other test here gives ConfigDir and StateDir separate temporary
// directories, which is exactly why none of them could see this.
func TestUninstallWithOneSharedDirectoryKeepsTheConfigItPromisedToKeep(t *testing.T) {
	shared := t.TempDir()
	opts := UninstallOptions{
		ConfigDir:      shared,
		StateDir:       shared,
		Out:            &bytes.Buffer{},
		In:             strings.NewReader(""),
		Yes:            true,
		NonInteractive: true,
		KeepConfig:     true,
	}
	var out bytes.Buffer
	opts.Out = &out

	writeFile(t, shared, "zoomies.yaml", "server: {}\n")
	writeFile(t, shared, "encryption.key", "the only copy")
	writeFile(t, shared, "zoomies.db", "")
	// Something of the operator's own, which uninstall has never claimed.
	writeFile(t, shared, "fullchain.pem", "a certificate they put here")

	if err := Uninstall(context.Background(), opts); err != nil {
		t.Fatalf("Uninstall: %v", err)
	}

	if !exists(filepath.Join(shared, "zoomies.yaml")) {
		t.Errorf("--keep-config was given and zoomies.yaml was deleted anyway:\n%s", out.String())
	}
	if !exists(filepath.Join(shared, "fullchain.pem")) {
		t.Errorf("a file that was never ours was deleted:\n%s", out.String())
	}
	// The database is still the thing being uninstalled.
	if exists(filepath.Join(shared, "zoomies.db")) {
		t.Errorf("the database survived, so nothing was uninstalled:\n%s", out.String())
	}
	// The key goes: it is not configuration, and leaving it behind is the
	// thing removing it at all is meant to prevent.
	if exists(filepath.Join(shared, "encryption.key")) {
		t.Errorf("the encryption key was left behind:\n%s", out.String())
	}
	// And the report has to name what survived, or the operator does not know
	// there is anything still to clean up.
	if report := out.String(); !strings.Contains(report, "fullchain.pem") {
		t.Errorf("the report did not name what was left behind:\n%s", report)
	}
}

// ---------------------------------------------------------------------------
// The one irreversible answer
// ---------------------------------------------------------------------------

// The volume is the database -- pools, runners, job history, the audit log --
// and deleting it cannot be undone. Every path into the question defaults to
// keeping it, and the one that would surprise somebody most is `--yes`: on
// nearly every other tool that means "yes to everything", and here it must
// still not mean "and delete my data".
func TestUninstallKeepsTheVolumeUnlessItIsAskedPlainly(t *testing.T) {
	yes, no := true, false

	for _, tc := range []struct {
		name  string
		opts  UninstallOptions
		input string
		want  bool
	}{
		{name: "the flag says so", opts: UninstallOptions{RemoveVolume: &yes}, want: true},
		{name: "the flag says not to", opts: UninstallOptions{RemoveVolume: &no}, want: false},
		{name: "--yes is not consent to lose the database", opts: UninstallOptions{Yes: true}, want: false},
		{name: "nobody is there to ask", opts: UninstallOptions{NonInteractive: true}, want: false},
		{name: "asked, and answered yes", input: "y\n", want: true},
		{name: "asked, and answered no", input: "n\n", want: false},
		{name: "asked, and just pressed return", input: "\n", want: false},
		{name: "asked, and the input ended", input: "", want: false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			out := &bytes.Buffer{}
			opts := tc.opts
			opts.Out = out
			opts.In = strings.NewReader(tc.input)

			got, err := wantsVolumeRemoved(opts, newUI(out), DeploymentRecord{})
			if err != nil {
				t.Fatalf("wantsVolumeRemoved: %v", err)
			}
			if got != tc.want {
				t.Errorf("wantsVolumeRemoved = %v, want %v", got, tc.want)
			}
		})
	}
}

// When the question is skipped because nobody is there to answer it, the
// operator is told the volume was kept and how to ask for it to go. A silent
// skip leaves somebody believing they uninstalled everything.
func TestUninstallSaysItKeptTheVolumeWhenItCouldNotAsk(t *testing.T) {
	out := &bytes.Buffer{}
	opts := UninstallOptions{NonInteractive: true, Out: out, In: strings.NewReader("")}

	if _, err := wantsVolumeRemoved(opts, newUI(out), DeploymentRecord{Volume: "zoomies-data"}); err != nil {
		t.Fatalf("wantsVolumeRemoved: %v", err)
	}
	said := out.String()
	if !strings.Contains(said, "zoomies-data") {
		t.Errorf("the note does not name the volume that was kept:\n%s", said)
	}
	if !strings.Contains(said, "--volumes") {
		t.Errorf("the note does not say how to delete it either:\n%s", said)
	}
}

// The prompt has to say what is about to be lost. "Delete the volume?" on its
// own is a question an operator answers wrongly once.
func TestUninstallVolumePromptNamesWhatIsInIt(t *testing.T) {
	out := &bytes.Buffer{}
	opts := UninstallOptions{Out: out, In: strings.NewReader("n\n")}

	if _, err := wantsVolumeRemoved(opts, newUI(out), DeploymentRecord{}); err != nil {
		t.Fatalf("wantsVolumeRemoved: %v", err)
	}
	asked := out.String()
	for _, want := range []string{"database", "cannot be undone"} {
		if !strings.Contains(asked, want) {
			t.Errorf("the prompt never says %q:\n%s", want, asked)
		}
	}
	// The default is spelled out rather than left to capitalisation alone.
	if !strings.Contains(asked, "[y/N]") {
		t.Errorf("the prompt does not show that keeping the volume is the default:\n%s", asked)
	}
}

// For a container deployment the environment file is the only copy of the
// encryption key, and the data volume is sealed with it. Uninstall keeps the
// volume unless it is asked plainly, so it must keep the key that opens it:
// otherwise "keeping it lets a later install pick up exactly where this left
// off" is false, and the operator finds out when every stored GitHub App key
// and webhook secret fails to decrypt.
func TestUninstallKeepsTheKeyForAVolumeItKeeps(t *testing.T) {
	yes, no := true, false

	for _, tc := range []struct {
		name         string
		removeVolume *bool
		keyKept      bool
	}{
		{name: "the volume is kept when nobody says otherwise", removeVolume: nil, keyKept: true},
		{name: "the volume is kept when the flag says not to delete it", removeVolume: &no, keyKept: true},
		{name: "the key goes with the volume it sealed", removeVolume: &yes, keyKept: false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			opts := uninstallOpts(t)
			opts.Yes = true
			opts.NonInteractive = true
			opts.RemoveVolume = tc.removeVolume
			var out bytes.Buffer
			opts.Out = &out

			deployDir := t.TempDir()
			envFile := writeFile(t, deployDir, ".env", "ZOOMIES_ENCRYPTION_KEY=the-only-copy\n")
			backup := writeFile(t, deployDir, ".env.bak.20260101-000000", "ZOOMIES_ENCRYPTION_KEY=the-only-copy\n")
			compose := writeFile(t, deployDir, ComposeFileName, "services: {}\n")
			// Names nothing on this machine can have, so the docker calls
			// uninstall makes are refused rather than acted on.
			rec := DeploymentRecord{
				Deployment: DeploymentDocker,
				Directory:  deployDir,
				Container:  "zoomies-uninstall-test-none",
				Volume:     "zoomies-uninstall-test-none",
				EnvFile:    envFile,
			}
			if _, err := WriteDeploymentRecord(opts.ConfigDir, rec); err != nil {
				t.Fatal(err)
			}

			if err := Uninstall(context.Background(), opts); err != nil {
				t.Fatalf("Uninstall: %v", err)
			}

			for _, path := range []string{envFile, backup} {
				if got := exists(path); got != tc.keyKept {
					t.Errorf("%s exists = %v, want %v\n%s", path, got, tc.keyKept, out.String())
				}
			}
			// Nothing else needs to survive: the compose file is regenerated
			// and the record describes a deployment that is gone.
			if exists(compose) || exists(DeploymentRecordPath(opts.ConfigDir)) {
				t.Errorf("the compose file and the deployment record should still be removed\n%s", out.String())
			}
			if tc.keyKept {
				if report := out.String(); !strings.Contains(report, "encryption key") || !strings.Contains(report, envFile) {
					t.Errorf("the report should say the environment file was left, and why:\n%s", report)
				}
			}
		})
	}
}

// The plan is printed before the volume question is asked, so what it says
// about the key has to be true for both answers.
func TestDeploymentItemsSayTheKeyStaysWithAKeptVolume(t *testing.T) {
	yes := true
	rec := DeploymentRecord{Deployment: DeploymentDocker, EnvFile: "/etc/zoomies/.env"}

	for _, tc := range []struct {
		name   string
		remove *bool
		want   string
	}{
		{"undecided", nil, "kept unless the data volume is deleted"},
		{"the volume is going", &yes, "removed with the data volume"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			opts := uninstallOpts(t)
			opts.RemoveVolume = tc.remove
			for _, item := range deploymentItems(rec, opts) {
				if item.What == "environment file" {
					if !strings.Contains(item.Note, "encryption key") || !strings.Contains(item.Note, tc.want) {
						t.Fatalf("note = %q, want it to mention the key and %q", item.Note, tc.want)
					}
					return
				}
			}
			t.Fatal("the environment file is not in the plan")
		})
	}
}

package installer

import (
	"context"
	"encoding/json"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/backend"
	"github.com/eyupio/zoomies/internal/config"
)

// UpgradeOptions selects an existing deployment. Upgrade never enrols a host,
// generates credentials, or rewrites its configuration from installer defaults.
type UpgradeOptions struct {
	ConfigDir  string
	BinaryPath string
	DockerHost string
	Runtime    string
	Image      string
	Mode       Mode
	Check      bool
	Out        io.Writer
	// In is where an answer to "add them now?" is read from, and Interactive
	// says somebody is there to give one. AssumeYes is --yes: approval given
	// in advance. With neither, what this release expects and the deployment
	// lacks is reported and left alone. NonInteractive says nobody will be
	// there on the real run either, which lets --check refuse an upgrade that
	// could only stop half way.
	In             io.Reader
	Interactive    bool
	NonInteractive bool
	AssumeYes      bool
	run            commandRunner
	runInput       inputRunner
	// shared stands in for the host's shared folder and the account it
	// belongs to, so a test does not reach for /var/lib/zoomies.
	shared *sharedTarget
	// socketGroup stands in for reading the group that owns the runtime's
	// socket, which is the test host's own otherwise.
	socketGroup func(path string) int
	// serveTimeout, servePoll and progressEvery shorten the wait for the
	// controller to answer, which is minutes long outside a test.
	serveTimeout, servePoll, progressEvery time.Duration
}

type upgradePlan struct {
	opts        UpgradeOptions
	record      DeploymentRecord
	image       string
	unit        string
	launchd     bool
	client      *backend.APIClient
	replacement *backend.ContainerReplacement
	// move is the settings the operator agreed to take out of the
	// container's environment and into its database; see envsettings.go.
	move []movedSetting
}

// Upgrade applies the binary already downloaded by install.sh to the running
// deployment, and refreshes its stock runner images without removing workloads.
func Upgrade(ctx context.Context, opts UpgradeOptions) error {
	if opts.Runtime != "" && opts.Runtime != "docker" && opts.Runtime != "podman" {
		return fmt.Errorf("installer: --runtime must be docker or podman")
	}
	if opts.ConfigDir == "" {
		opts.ConfigDir = config.ConfigDir()
	}
	if opts.Out == nil {
		opts.Out = io.Discard
	}
	if opts.run == nil {
		opts.run = runCommand
	}
	if opts.runInput == nil {
		opts.runInput = runCommandInput
	}
	if opts.BinaryPath == "" {
		opts.BinaryPath, _ = os.Executable()
	}
	opts.BinaryPath = upgradeBinaryPath(opts.BinaryPath)
	if !opts.Check {
		lockPath := filepath.Join(opts.ConfigDir, "upgrade.lock")
		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if err != nil {
			return fmt.Errorf("installer: cannot reserve this deployment for upgrade: %w; if an earlier upgrade was interrupted, remove %s only after checking it has stopped", err, lockPath)
		}
		_ = lock.Close()
		defer os.Remove(lockPath)
	}
	p, err := prepareUpgrade(ctx, opts)
	if err != nil {
		return err
	}
	// Before anything is pulled or restarted, so that what is added -- a
	// mount above all -- is there when the upgraded service starts.
	if err := p.settleLayout(ctx); err != nil {
		return err
	}
	p.settleSettings(ctx)
	if opts.Check {
		fmt.Fprintln(opts.Out, "The existing deployment can be upgraded without running setup again.")
		return nil
	}
	beforeImage := p.localImageID(ctx)
	// The tag can have been pulled already -- by an earlier `docker pull`, a
	// check, or an upgrade whose restart failed -- while the service still
	// runs something older. Comparing the tag alone then says nothing changed
	// on an upgrade that moved the service and migrated its database.
	beforeRunning := p.runningImageID(ctx)
	serving := p.serveCheck(ctx)
	fmt.Fprintln(opts.Out, "Keeping this host's configuration, credentials, identity and data.")
	if err := p.pullRunnerImages(ctx); err != nil {
		return err
	}
	switch p.record.Deployment {
	case DeploymentCompose:
		err = p.upgradeCompose(ctx)
	case DeploymentDocker:
		err = p.upgradeDocker(ctx)
	default:
		fmt.Fprintln(opts.Out, "Restarting "+p.unit+" with the installed binary. Reporting resumes after the restart.")
		if p.launchd {
			_, err = opts.run(ctx, "launchctl", "kickstart", "-k", p.unit)
		} else {
			_, err = opts.run(ctx, "systemctl", "restart", p.unit)
			if err == nil {
				_, err = opts.run(ctx, "systemctl", "is-active", "--quiet", p.unit)
			}
		}
	}
	if err != nil {
		return fmt.Errorf("installer: the upgrade did not finish: %w", err)
	}
	if err := p.waitServing(ctx, serving); err != nil {
		return fmt.Errorf("installer: %w", err)
	}
	if p.record.Deployment.Containerised() {
		afterImage := p.localImageID(ctx)
		reportImage(opts.Out, p.image, beforeImage, afterImage, beforeRunning, p.runningImageID(ctx))
	}
	fmt.Fprintln(opts.Out, "Upgrade complete. Check the Hosts page for the agent's next heartbeat.")
	return nil
}

// settleLayout says what this release expects that the deployment lacks, and
// adds it when the operator approves: --yes, or an answer at the terminal.
// Unattended, it adds nothing and says how to; see layout.go.
func (p *upgradePlan) settleLayout(ctx context.Context) error {
	changes, err := p.layoutChanges(ctx)
	if err != nil || len(changes) == 0 {
		return err
	}
	out := p.opts.Out
	fmt.Fprintln(out, "This release expects what this deployment does not have yet:")
	required := ""
	for _, c := range changes {
		fmt.Fprintln(out, "  - "+c.what)
		if c.required && required == "" {
			required = c.what
		}
	}
	refuse := func() error {
		return fmt.Errorf("installer: the upgrade cannot go on without this: %s; run `zoomies upgrade --yes` to add it, or `zoomies init` to set the deployment up again", required)
	}
	approved := false
	switch {
	case p.opts.Check:
		// install.sh replaces the binary between the check and the real
		// run, so a run that is bound to stop has to stop here, while the
		// old binary is still the installed one.
		if required != "" && p.opts.NonInteractive && !p.opts.AssumeYes {
			return refuse()
		}
		fmt.Fprintln(out, "The upgrade will offer to add them, and adds nothing without your approval.")
		return nil
	case p.opts.AssumeYes:
		approved = true
	case p.opts.Interactive && p.opts.In != nil:
		approved = askApproval(p.opts.In, out, "Add them now? [Y/n] ")
	}
	if !approved {
		if required != "" {
			return refuse()
		}
		fmt.Fprintln(out, "Left as they are: nothing on this host changes without approval, and the upgrade goes on without them.")
		fmt.Fprintln(out, "To add them, run: zoomies upgrade --yes  (as root, as the upgrade itself is)")
		return nil
	}
	for _, c := range changes {
		if err := c.apply(ctx); err != nil {
			return fmt.Errorf("installer: could not %s: %w", c.what, err)
		}
	}
	fmt.Fprintf(out, "Added %d change(s) this release expects.\n", len(changes))
	return nil
}

// askApproval reads one answer. An empty line is yes, as the [Y/n] says; an
// input that ends before anything is typed is no, because nobody said yes.
func askApproval(in io.Reader, out io.Writer, question string) bool {
	fmt.Fprint(out, question)
	var line strings.Builder
	buf := make([]byte, 1)
	for {
		n, err := in.Read(buf)
		if n == 1 {
			if buf[0] == '\n' {
				break
			}
			line.WriteByte(buf[0])
		}
		if err != nil {
			if line.Len() == 0 {
				fmt.Fprintln(out)
				return false
			}
			break
		}
	}
	switch strings.ToLower(strings.TrimSpace(line.String())) {
	case "", "y", "yes":
		return true
	}
	return false
}

func (p *upgradePlan) localImageID(ctx context.Context) string {
	if !p.record.Deployment.Containerised() || p.image == "" {
		return ""
	}
	out, err := p.docker(ctx, "image", "inspect", "--format", "{{.Id}}", p.image)
	if err != nil {
		return ""
	}
	return strings.TrimSpace(out)
}

// runningImageID is the image the service's container was created from, which
// is what an upgrade actually changes; the tag is only what it will be
// created from next.
func (p *upgradePlan) runningImageID(ctx context.Context) string {
	if !p.record.Deployment.Containerised() {
		return ""
	}
	out, err := p.docker(ctx, "inspect", "--format", "{{.Image}}", containerOr(p.record))
	if err != nil {
		return ""
	}
	return strings.TrimSpace(out)
}

// reportImage says what the upgrade did to the image the service runs, and
// separately whether the channel it follows moved, because those differ
// whenever the tag was pulled before the service was recreated from it.
func reportImage(out io.Writer, image, tagBefore, tagAfter, runBefore, runAfter string) {
	moved := runBefore != "" && runAfter != "" && runBefore != runAfter
	switch {
	case moved && tagBefore != "" && tagAfter == tagBefore:
		fmt.Fprintf(out, "The service moved from %s to %s. %s already resolved to %s on this host before this upgrade, so nothing new was downloaded.\n", shortImageID(runBefore), shortImageID(runAfter), image, shortImageID(tagAfter))
	case moved:
		fmt.Fprintf(out, "Image channel advanced: the service moved from %s to %s, which %s now resolves to.\n", shortImageID(runBefore), shortImageID(runAfter), image)
	case tagBefore != "" && tagAfter == tagBefore:
		fmt.Fprintf(out, "Image channel did not advance: %s still resolves to %s. The service was recreated from the same published image.\n", image, shortImageID(tagAfter))
	case tagAfter != "" && tagBefore != "":
		fmt.Fprintf(out, "Image channel advanced: %s now resolves to %s (was %s).\n", image, shortImageID(tagAfter), shortImageID(tagBefore))
	case tagAfter != "":
		fmt.Fprintf(out, "Pulled %s at %s.\n", image, shortImageID(tagAfter))
	default:
		fmt.Fprintf(out, "Recreated the service from %s. Confirm its reported build; moving tags advance only after a successful publish.\n", image)
	}
}

func shortImageID(id string) string {
	id = strings.TrimSpace(strings.TrimPrefix(id, "sha256:"))
	if len(id) > 12 {
		id = id[:12]
	}
	return id
}

func prepareUpgrade(ctx context.Context, opts UpgradeOptions) (*upgradePlan, error) {
	p := &upgradePlan{opts: opts}
	data, err := os.ReadFile(DeploymentRecordPath(opts.ConfigDir))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("installer: read the existing deployment: %w", err)
	}
	if err == nil {
		if err := json.Unmarshal(data, &p.record); err != nil {
			return nil, fmt.Errorf("installer: the deployment record is invalid; restore it before upgrading: %w", err)
		}
		if p.record.Deployment != DeploymentNative && !p.record.Deployment.Containerised() {
			return nil, fmt.Errorf("installer: unknown deployment %q; no service was changed", p.record.Deployment)
		}
	}
	if opts.Mode != "" && p.record.Mode != "" && opts.Mode != p.record.Mode {
		return nil, fmt.Errorf("installer: this is a %s deployment, not %s; run the command on the intended host", p.record.Mode, opts.Mode)
	}
	if !p.record.Deployment.Containerised() {
		if err := p.prepareNative(ctx); err != nil {
			return nil, err
		}
		return p, nil
	}
	if p.record.Directory == "" || p.record.EnvFile == "" {
		return nil, fmt.Errorf("installer: the deployment record has no directory or environment file; restore it before upgrading")
	}
	if _, err := os.ReadFile(p.record.EnvFile); err != nil {
		return nil, fmt.Errorf("installer: read the existing environment: %w", err)
	}
	p.image, err = upgradeImage(p.record, opts.Image)
	if err != nil {
		return nil, err
	}
	if p.record.Deployment == DeploymentCompose {
		// A missing Compose file is one the upgrade offers to write again
		// (see layout.go), and a file it writes uses ZOOMIES_IMAGE by
		// construction; there is nothing to ask Compose about yet.
		if _, err := os.Stat(p.record.ComposeFile()); os.IsNotExist(err) {
			return p, nil
		}
		// Do not claim an upgrade if the operator has replaced the image
		// variable with a fixed reference in the compose file.
		images, err := p.compose(ctx, "config", "--images")
		if err != nil {
			return nil, err
		}
		found := false
		for _, image := range strings.Fields(images) {
			if image == p.image {
				found = true
			}
		}
		if !found {
			return nil, fmt.Errorf("installer: %s does not use ZOOMIES_IMAGE; restore that image setting before upgrading", p.record.ComposeFile())
		}
		return p, nil
	}
	endpoint := opts.DockerHost
	if endpoint == "" {
		endpoint = os.Getenv("DOCKER_HOST")
	}
	if endpoint == "" {
		endpoint = "unix:///var/run/docker.sock"
	}
	p.client, err = backend.NewAPIClient(endpoint)
	if err != nil {
		return nil, err
	}
	p.replacement, err = p.client.PrepareReplacement(ctx, containerOr(p.record), p.image)
	if err != nil {
		return nil, err
	}
	if opts.Image == "" && p.replacement.Image != p.record.Image {
		return nil, fmt.Errorf("installer: the running container uses a different image from its deployment record; pass --image with the intended replacement")
	}
	backup := p.replacement.Name + "-before-upgrade"
	if _, err := p.client.ContainerInspect(ctx, backup); backend.StatusCode(err) != 404 {
		return nil, fmt.Errorf("installer: cannot reserve backup container %s; inspect or remove an earlier upgrade backup before retrying", backup)
	}
	return p, nil
}

func upgradeImage(rec DeploymentRecord, override string) (string, error) {
	if override != "" {
		if strings.HasPrefix(override, "-") || strings.ContainsAny(override, " \t\r\n") {
			return "", fmt.Errorf("installer: --image must be one image reference")
		}
		return override, nil
	}
	base := strings.Split(strings.Split(rec.Image, "@")[0], ":")[0]
	if base != stockControllerRepository && base != stockAgentRepository {
		return "", fmt.Errorf("installer: %s is a custom image; pass --image with the image to upgrade to", rec.Image)
	}
	image := DefaultImage()
	if rec.Mode == ModeAgent || base == stockAgentRepository {
		image, _ = AgentImageFor(image)
	}
	return image, nil
}

func (p *upgradePlan) prepareNative(ctx context.Context) error {
	units := []string{UnitAgent, UnitController}
	if p.opts.Mode == ModeAgent {
		units = []string{UnitAgent}
	} else if p.opts.Mode != "" {
		units = []string{UnitController}
	}
	for _, unit := range units {
		if runtime.GOOS == "darwin" {
			label := (ServiceSpec{Unit: unit}).Label()
			path := LaunchdPlistPath(label, os.Geteuid() == 0)
			data, err := os.ReadFile(path)
			if errors.Is(err, os.ErrNotExist) {
				continue
			}
			if err != nil {
				return err
			}
			binary, err := launchdBinary(data)
			if err != nil || filepath.Clean(binary) != p.opts.BinaryPath {
				return fmt.Errorf("installer: %s does not run %s; pass --prefix for its ProgramArguments executable", label, p.opts.BinaryPath)
			}
			domain := fmt.Sprintf("gui/%d/", os.Geteuid())
			if os.Geteuid() == 0 {
				domain = "system/"
			}
			if p.unit != "" {
				return fmt.Errorf("installer: more than one native service exists; choose --mode agent or --mode controller")
			}
			p.unit, p.launchd = domain+label, true
			continue
		}
		state, err := p.opts.run(ctx, "systemctl", "show", "--property=LoadState", "--value", unit)
		if err != nil || strings.TrimSpace(state) != "loaded" {
			continue
		}
		if p.unit != "" {
			return fmt.Errorf("installer: more than one native service exists; choose --mode agent or --mode controller")
		}
		execStart, err := p.opts.run(ctx, "systemctl", "show", "--property=ExecStart", "--value", unit)
		if err != nil {
			return err
		}
		if !strings.Contains(execStart, "path="+p.opts.BinaryPath+" ;") && !strings.Contains(execStart, "path="+p.opts.BinaryPath+";") {
			return fmt.Errorf("installer: %s does not run %s; pass --prefix for the directory its ExecStart uses", unit, p.opts.BinaryPath)
		}
		p.unit = unit
	}
	if p.unit == "" {
		return fmt.Errorf("installer: no existing Zoomies deployment was found; run on the installed host, or pass --config-dir for its deployment record")
	}
	return nil
}

func (p *upgradePlan) docker(ctx context.Context, args ...string) (string, error) {
	name, argv := p.dockerArgv(args...)
	return p.opts.run(ctx, name, argv...)
}

func (p *upgradePlan) dockerArgv(args ...string) (string, []string) {
	if p.opts.Runtime == "podman" {
		if p.opts.DockerHost != "" {
			args = append([]string{"--remote", "--url", p.opts.DockerHost}, args...)
		}
		return "podman", args
	}
	if p.opts.DockerHost != "" {
		args = append([]string{"--host", p.opts.DockerHost}, args...)
	}
	return "docker", args
}

func (p *upgradePlan) compose(ctx context.Context, args ...string) (string, error) {
	name, argv := p.composeArgv(args...)
	return p.opts.run(ctx, name, argv...)
}

func (p *upgradePlan) composeArgv(args ...string) (string, []string) {
	name, command := ComposeArgs(p.record.ComposeCommand, p.record.ComposeFile(), args...)
	prefix := []string{"ZOOMIES_IMAGE=" + p.image}
	if p.opts.DockerHost != "" {
		prefix = append(prefix, "DOCKER_HOST="+p.opts.DockerHost)
	}
	for n, arg := range command {
		if arg == "--env-file" && n+1 < len(command) {
			command[n+1] = p.record.EnvFile
		}
	}
	return "env", append(append(prefix, name), command...)
}

func (p *upgradePlan) pullRunnerImages(ctx context.Context) error {
	if p.opts.DockerHost == "" && !p.record.Deployment.Containerised() {
		return nil
	}
	images, err := p.docker(ctx, "image", "ls", "--format", "{{.Repository}}:{{.Tag}}")
	if err != nil {
		return fmt.Errorf("read cached runner images: %w", err)
	}
	seen := map[string]bool{}
	for _, image := range strings.Fields(images) {
		if !strings.HasPrefix(image, "ghcr.io/eyupio/zoomies-runner") || strings.HasSuffix(image, ":<none>") || seen[image] {
			continue
		}
		seen[image] = true
		fmt.Fprintln(p.opts.Out, "Refreshing "+image+" for future jobs; existing runners keep their image.")
		if _, err := p.docker(ctx, "pull", image); err != nil {
			return fmt.Errorf("pull %s; the deployment has not been restarted: %w", image, err)
		}
	}
	return nil
}

// Only the image line changes. Secrets, comments and hand-edited settings stay
// byte-for-byte intact, and the original is available for a failed restart.
func replaceEnvImage(path, image string) ([]byte, os.FileMode, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, 0, err
	}
	info, err := os.Stat(path)
	if err != nil {
		return nil, 0, err
	}
	value, err := quoteEnvValue("ZOOMIES_IMAGE", image)
	if err != nil {
		return nil, 0, err
	}
	lines := strings.Split(string(data), "\n")
	found := false
	for n, line := range lines {
		key, _, ok := strings.Cut(strings.TrimPrefix(strings.TrimSpace(line), "export "), "=")
		if ok && strings.TrimSpace(key) == "ZOOMIES_IMAGE" {
			lines[n] = "ZOOMIES_IMAGE=" + value
			found = true
		}
	}
	updated := strings.Join(lines, "\n")
	if !found {
		if !strings.HasSuffix(updated, "\n") {
			updated += "\n"
		}
		updated += "ZOOMIES_IMAGE=" + value + "\n"
	}
	if err := writeFileAtomic(path, []byte(updated), info.Mode().Perm()); err != nil {
		return nil, 0, err
	}
	return data, info.Mode().Perm(), nil
}

func (p *upgradePlan) upgradeCompose(ctx context.Context) error {
	fmt.Fprintln(p.opts.Out, "Pulling "+p.image)
	if _, err := p.compose(ctx, "pull", "zoomies"); err != nil {
		return err
	}
	previous, err := ParseEnvFile(p.record.EnvFile)
	if err != nil {
		return err
	}
	var unmove func() error
	if len(p.move) > 0 {
		unmove = p.moveComposeSettings(ctx)
	}
	old, mode, err := replaceEnvImage(p.record.EnvFile, p.image)
	if err != nil {
		return err
	}
	_, err = p.compose(ctx, "up", "-d", "--no-deps", "--force-recreate", "--timeout", strconv.Itoa(int(serviceStopTimeout.Seconds())), "zoomies")
	if err == nil {
		var running string
		running, err = p.docker(ctx, "inspect", "--format", "{{.State.Running}}", containerOr(p.record))
		if err == nil && strings.TrimSpace(running) != "true" {
			err = fmt.Errorf("the upgraded container did not stay running")
		}
	}
	if err != nil {
		// The files go back as they were before the move as well: the image
		// being rolled back to may predate the settings it would now find
		// only in the database.
		var restore error
		if unmove != nil {
			restore = unmove()
		} else {
			restore = writeFileAtomic(p.record.EnvFile, old, mode)
		}
		if restore == nil {
			rollback, cancel := context.WithTimeout(context.WithoutCancel(ctx), serviceStopTimeout+time.Minute)
			defer cancel()
			p.image = previous["ZOOMIES_IMAGE"]
			if p.image == "" {
				p.image = p.record.Image
			}
			_, restore = p.compose(rollback, "up", "-d", "--no-deps", "--force-recreate", "--timeout", strconv.Itoa(int(serviceStopTimeout.Seconds())), "zoomies")
		}
		return errors.Join(err, restore)
	}
	p.record.Image = p.image
	_, err = WriteDeploymentRecord(p.opts.ConfigDir, p.record)
	return err
}

func (p *upgradePlan) upgradeDocker(ctx context.Context) error {
	fmt.Fprintln(p.opts.Out, "Pulling "+p.image)
	if _, err := p.docker(ctx, "pull", p.image); err != nil {
		return err
	}
	old := p.replacement
	if err := p.client.ContainerStop(ctx, old.ID, serviceStopTimeout); err != nil {
		return err
	}
	moved := len(p.move) > 0 && p.moveDockerSettings(ctx)
	backup := old.Name + "-before-upgrade"
	if err := p.client.ContainerRename(ctx, old.ID, backup); err != nil {
		if old.Running {
			_ = p.client.ContainerStart(context.WithoutCancel(ctx), old.ID)
		}
		return err
	}
	id, err := p.client.CreateReplacement(ctx, old)
	if err == nil {
		err = p.client.ContainerStart(ctx, id)
	}
	if err == nil {
		var state *backend.ContainerInspect
		state, err = p.client.ContainerInspect(ctx, id)
		if err == nil && (state.State == nil || !state.State.Running) {
			err = fmt.Errorf("replacement container did not stay running")
		}
	}
	if err != nil {
		rollback, cancel := context.WithTimeout(context.WithoutCancel(ctx), serviceStopTimeout+time.Minute)
		defer cancel()
		var restore error
		if id != "" {
			restore = p.client.RemoveContainerKeepingVolumes(rollback, id, true)
		}
		if restore == nil {
			restore = p.client.ContainerRename(rollback, old.ID, old.Name)
		}
		if restore == nil && old.Running {
			restore = p.client.ContainerStart(rollback, old.ID)
		}
		return errors.Join(err, restore)
	}
	if _, _, err := replaceEnvImage(p.record.EnvFile, p.image); err != nil {
		return fmt.Errorf("new container is running but its environment file could not be updated: %w", err)
	}
	if moved {
		p.commentDockerEnvFile()
	}
	p.record.Image = p.image
	if _, err := WriteDeploymentRecord(p.opts.ConfigDir, p.record); err != nil {
		return err
	}
	if err := p.client.RemoveContainerKeepingVolumes(ctx, old.ID, false); err != nil {
		return fmt.Errorf("new container is running; remove the stopped %s container when convenient: %w", backup, err)
	}
	return nil
}

// Native services name an absolute executable even when --prefix was relative.
func upgradeBinaryPath(path string) string {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return path
	}
	return absolute
}

func launchdBinary(data []byte) (string, error) {
	decoder := xml.NewDecoder(strings.NewReader(string(data)))
	arguments := false
	for {
		token, err := decoder.Token()
		if err != nil {
			return "", err
		}
		start, ok := token.(xml.StartElement)
		if !ok {
			continue
		}
		if start.Name.Local == "key" {
			var key string
			if err := decoder.DecodeElement(&key, &start); err != nil {
				return "", err
			}
			arguments = key == "ProgramArguments"
		} else if arguments && start.Name.Local == "string" {
			var binary string
			err := decoder.DecodeElement(&binary, &start)
			return binary, err
		}
	}
}

