	"github.com/eyupio/zoomies/internal/config"
)

const composeHealthCheck = `{"Test":["CMD","/usr/local/bin/zoomies","healthcheck","--url","http://127.0.0.1:8080"],"Interval":30000000000}`

// waitFixture is a Compose upgrade whose controller fails its health check
// `failures` times before it answers, and reports `status` while it does.
func waitFixture(t *testing.T, failures int, status, healthcheck string) (UpgradeOptions, *bytes.Buffer, *[]string) {
	t.Helper()
	opts, rec := upgradeFixture(t, DeploymentCompose)
	// A controller: an agent serves nothing, so it has nothing to wait for.
	rec.Mode, rec.Image = ModeSingle, stockControllerRepository+":v0.1"
	if _, err := WriteDeploymentRecord(opts.ConfigDir, rec); err != nil {
		t.Fatal(err)
	}
	opts.Mode, opts.Image = ModeSingle, stockControllerRepository+":v9.0"
	var out bytes.Buffer
	opts.Out = &out
	opts.servePoll = time.Millisecond
	opts.progressEvery = time.Nanosecond
	opts.serveTimeout = time.Minute
	var calls []string
	probes := 0
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		calls = append(calls, line)
		switch {
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case strings.Contains(line, "{{json .Config.Healthcheck}}"):
			return healthcheck, nil
		case name == "docker" && len(args) > 1 && args[0] == "exec":
			probes++
			if probes <= failures {
				return "", errors.New("connection refused")
			}
			return "", nil
		case strings.Contains(line, "{{.State.Status}}"):
			return status, nil
		case strings.Contains(line, "logs --tail 1"):
			return `zoomies  | {"time":"2026-09-24T18:47:19Z","level":"INFO","msg":"copied the database before migrating it","migrations":1}`, nil
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
	return opts, &out, &calls
}

// The upgrade used to report itself complete while the controller was still
// migrating its database and answering nothing, which reads as an outage with
// no explanation. It waits for the controller now, and says why it is waiting.
func TestAnUpgradeWaitsForTheControllerToAnswer(t *testing.T) {
	opts, out, calls := waitFixture(t, 3, "running", composeHealthCheck)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	text := out.String()
	waiting := strings.Index(text, "Waiting for the controller to answer")
	answering := strings.Index(text, "The controller is answering")
	complete := strings.Index(text, "Upgrade complete")
	if waiting < 0 || answering < waiting || complete < answering {
		t.Fatalf("output does not wait, then answer, then complete:\n%s", text)
	}
	// The latest log line is what shows a slow start is a migration.
	if !strings.Contains(text, "latest: copied the database before migrating it") {
		t.Fatalf("output never said what the controller was doing:\n%s", text)
	}
	// The container's own check, run in it, rather than a guess at a URL.
	want := "docker exec zoomies /usr/local/bin/zoomies healthcheck --url http://127.0.0.1:8080"
	if !slices.Contains(*calls, want) {
		t.Fatalf("calls = %q, want %q", *calls, want)
	}
}

func TestAnAgentUpgradeDoesNotWait(t *testing.T) {
	opts, _ := upgradeFixture(t, DeploymentCompose)
	var out bytes.Buffer
	opts.Out = &out
	opts.run = func(_ context.Context, name string, args ...string) (string, error) {
		line := name + " " + strings.Join(args, " ")
		switch {
		case strings.Contains(line, "config --images"):
			return opts.Image, nil
		case name == "docker" && len(args) > 0 && args[0] == "exec":
			t.Errorf("an agent was health-checked: %s", line)
		case name == "docker" && len(args) > 0 && args[0] == "inspect":
			return "true", nil
		}
		return "", nil
	}
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
}

func TestAControllerThatAnswersAtOnceIsNotWaitedOnAloud(t *testing.T) {
	opts, out, _ := waitFixture(t, 0, "running", composeHealthCheck)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(out.String(), "Waiting for the controller") {
		t.Fatalf("output = %q, announced a wait there was no need for", out.String())
	}
}

// A controller that stops after the upgrade is an error, and one that must
// not be rolled back: it may already have migrated the database, which the
// older image cannot open.
func TestAControllerThatStopsAfterTheUpgradeFailsIt(t *testing.T) {
	opts, out, calls := waitFixture(t, 1000, "exited", composeHealthCheck)
	err := Upgrade(context.Background(), opts)
	if err == nil {
		t.Fatal("an upgrade whose controller stopped reported success")
	}
	for _, want := range []string{"container is exited", "zoomies logs", "not rolled back"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q does not say %q", err, want)
		}
	}
	if strings.Contains(out.String(), "Upgrade complete") {
		t.Fatalf("output = %q, called the upgrade complete", out.String())
	}
	ups := 0
	for _, c := range *calls {
		if strings.Contains(c, " up -d ") {
			ups++
		}
	}
	if ups != 1 {
		t.Fatalf("the service was brought up %d times, want once and no rollback: %q", ups, *calls)
	}
}

func TestAControllerStillStartingAtTheDeadlineSaysNotToStopIt(t *testing.T) {
	opts, _, _ := waitFixture(t, 1000, "running", composeHealthCheck)
	opts.serveTimeout = 20 * time.Millisecond
	err := Upgrade(context.Background(), opts)
	if err == nil {
		t.Fatal("an upgrade whose controller never answered reported success")
	}
	for _, want := range []string{"has not answered", "still running", "do not stop it"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q does not say %q", err, want)
		}
	}
}

func TestAContainerWithNoHealthCheckIsNotWaitedOn(t *testing.T) {
	opts, out, _ := waitFixture(t, 1000, "running", `{"Test":["NONE"]}`)
	if err := Upgrade(context.Background(), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "declares no health check") || !strings.Contains(out.String(), "Upgrade complete") {
		t.Fatalf("output = %q", out.String())
	}
}

func TestHealthCommandRunsWhatTheContainerDeclares(t *testing.T) {
	for _, tc := range []struct {
		inspect string
		want    []string
	}{
		{composeHealthCheck, []string{"/usr/local/bin/zoomies", "healthcheck", "--url", "http://127.0.0.1:8080"}},
		{`{"Test":["CMD-SHELL","curl -f http://localhost/"]}`, []string{"/bin/sh", "-c", "curl -f http://localhost/"}},
		{`{"Test":["NONE"]}`, nil},
		{`null`, nil},
		{``, nil},
	} {
		got, ok := healthCommand(tc.inspect)
		if ok != (tc.want != nil) || !slices.Equal(got, tc.want) {
			t.Errorf("healthCommand(%q) = %q, %v; want %q", tc.inspect, got, ok, tc.want)
		}
	}
}

func TestLogLineMessageEchoesTheMessage(t *testing.T) {
	for in, want := range map[string]string{
		`zoomies  | {"level":"INFO","msg":"applied database migration","migration":"0054"}`: "applied database migration",
		`{"msg":"copied the database"}`:             "copied the database",
		"first\nlistening on http://0.0.0.0:8080\n": "listening on http://0.0.0.0:8080",
		"":                       "",
		strings.Repeat("x", 400): strings.Repeat("x", 157) + "...",
	} {
		if got := logLineMessage(in); got != want {
			t.Errorf("logLineMessage(%q) = %q, want %q", in, got, want)
		}
	}
}

// A native controller is asked on its own listener, which is a stored setting:
// every interface is reached over loopback, and TLS means https.
func TestANativeControllerIsAskedOnItsListener(t *testing.T) {
	cfg := config.Default()
	cfg.Server.Bind = "0.0.0.0:9443"
	cfg.Server.TLS.Mode = config.TLSSelfSigned
	if target, _ := nativeHealthTarget(cfg); target != "https://127.0.0.1:9443/healthz" {
		t.Fatalf("target = %q", target)
	}

	var answering atomic.Bool
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/healthz" || !answering.Load() {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(srv.Close)
	cfg.Server.Bind = strings.TrimPrefix(srv.URL, "http://")
	cfg.Server.TLS.Mode = config.TLSOff
	target, client := nativeHealthTarget(cfg)
	if host, _, _ := net.SplitHostPort(cfg.Server.Bind); !strings.Contains(target, host) {
		t.Fatalf("target = %q, not the listener %s", target, cfg.Server.Bind)
	}
	if err := probeHealth(t.Context(), client, target); err == nil || !strings.Contains(err.Error(), "503") {
		t.Fatalf("probe of a controller not yet answering = %v", err)
	}
	answering.Store(true)
	if err := probeHealth(t.Context(), client, target); err != nil {
		t.Fatalf("probe of an answering controller = %v", err)
	}
}

// Package logging configures the process-wide structured logger.
package logging

import (
	"context"
	"log/slog"
	"os"
	"strings"
)

// Options configures Setup.
type Options struct {
	Level  string // debug | info | warn | error
	Format string // json | text
	// AddSource includes file:line, which is useful in development and noisy
	// in production.
	AddSource bool
}

// Setup builds a logger and installs it as the slog default.
func Setup(o Options) *slog.Logger {
	var lvl slog.Level
	switch strings.ToLower(o.Level) {
	case "debug":
		lvl = slog.LevelDebug
	case "warn", "warning":
		lvl = slog.LevelWarn
	case "error":
		lvl = slog.LevelError
	default:
		lvl = slog.LevelInfo
	}

	opts := &slog.HandlerOptions{
		Level:       lvl,
		AddSource:   o.AddSource,
		ReplaceAttr: redact,
	}
	var h slog.Handler
	if strings.ToLower(o.Format) == "text" {
		h = slog.NewTextHandler(os.Stderr, opts)
	} else {
		h = slog.NewJSONHandler(os.Stderr, opts)
	}
	l := slog.New(h)
	slog.SetDefault(l)
	return l
}

// sensitiveKeys are attribute names whose values never reach the log, whatever
// a caller passes. It is cheaper to enforce this centrally than to trust every
// call site.
var sensitiveKeys = map[string]bool{
	"password":           true,
	"token":              true,
	"secret":             true,
	"private_key":        true,
	"jit_config":         true,
	"authorization":      true,
	"client_secret":      true,
	"webhook_secret":     true,
	"encryption_key":     true,
	"join_token":         true,
	"agent_token":        true,
	"cookie":             true,
	"registration_token": true,
}

func redact(_ []string, a slog.Attr) slog.Attr {
	if sensitiveKeys[strings.ToLower(a.Key)] {
		return slog.String(a.Key, "[redacted]")
	}
	return a
}

// ctxKey is the context key carrying a request-scoped logger.
type ctxKey struct{}

// WithLogger returns a context carrying l.
func WithLogger(ctx context.Context, l *slog.Logger) context.Context {
	return context.WithValue(ctx, ctxKey{}, l)
}

// FromContext returns the request-scoped logger, or the default.
func FromContext(ctx context.Context) *slog.Logger {
	if l, ok := ctx.Value(ctxKey{}).(*slog.Logger); ok && l != nil {
		return l
	}
	return slog.Default()
}

package logging

import (
	"bytes"
	"context"
	"encoding/json"
	"log/slog"
	"strings"
	"testing"
)

// The level an operator typed decides what is logged, and a word nobody
// recognises must not silence the process: an unreadable log.level should
// leave the default in place rather than turn logging off.
func TestTheLevelIsReadFromWhatTheOperatorWrote(t *testing.T) {
	cases := []struct {
		level string
		want  slog.Level
	}{
		{"debug", slog.LevelDebug},
		{"DEBUG", slog.LevelDebug},
		{"warn", slog.LevelWarn},
		{"warning", slog.LevelWarn},
		{"error", slog.LevelError},
		{"info", slog.LevelInfo},
		{"", slog.LevelInfo},
		{"chatty", slog.LevelInfo},
	}
	for _, tc := range cases {
		t.Run(tc.level, func(t *testing.T) {
			l := setupForTest(t, Options{Level: tc.level})
			if !l.Enabled(context.Background(), tc.want) {
				t.Errorf("level %q does not log at %s", tc.level, tc.want)
			}
			if tc.want > slog.LevelDebug && l.Enabled(context.Background(), tc.want-4) {
				t.Errorf("level %q logs below %s as well", tc.level, tc.want)
			}
		})
	}
}

// The format is JSON unless the operator asked for text: a log shipped to a
// collector is parsed, and the one a person reads over SSH is not.
func TestTheFormatIsJSONUnlessTextWasAskedFor(t *testing.T) {
	for _, format := range []string{"", "json", "anything else"} {
		l := setupForTest(t, Options{Format: format})
		if _, ok := l.Handler().(*slog.JSONHandler); !ok {
			t.Errorf("format %q gave a %T, want JSON", format, l.Handler())
		}
	}
	for _, format := range []string{"text", "TEXT"} {
		l := setupForTest(t, Options{Format: format})
		if _, ok := l.Handler().(*slog.TextHandler); !ok {
			t.Errorf("format %q gave a %T, want text", format, l.Handler())
		}
	}
}

// Setup installs what it built, because everything that logs through the
// package default -- every library, and every call site that never took a
// logger -- has to be redacting too.
func TestSetupInstallsTheLoggerAsTheDefault(t *testing.T) {
	l := setupForTest(t, Options{Level: "debug"})
	if slog.Default() != l {
		t.Error("the logger Setup built was not installed as the default")
	}
}

// The redaction is central precisely so that no call site can forget it: a
// value under one of these keys never reaches the log, whatever case it was
// written in and whatever kind of value it holds.
func TestASensitiveValueNeverReachesTheLog(t *testing.T) {
	var buf bytes.Buffer
	l := slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{ReplaceAttr: redact}))

	secret := "s3cr3t-do-not-log"
	for key := range sensitiveKeys {
		buf.Reset()
		l.Info("something happened", strings.ToUpper(key), secret)
		if strings.Contains(buf.String(), secret) {
			t.Errorf("%q was logged in full under %q", secret, key)
		}
		var line map[string]any
		if err := json.Unmarshal(buf.Bytes(), &line); err != nil {
			t.Fatalf("unmarshalling the log line: %v", err)
		}
		if got := line[strings.ToUpper(key)]; got != "[redacted]" {
			t.Errorf("%s = %v, want [redacted]", key, got)
		}
	}
}

// Everything else is logged as it was passed. Redacting by guesswork would
// cost an operator the field they were reading the log for.
func TestAnOrdinaryAttributeIsLeftAlone(t *testing.T) {
	for _, key := range []string{"host", "pool", "runner", "tokens_remaining", "secretive"} {
		a := redact(nil, slog.String(key, "visible"))
		if a.Value.String() != "visible" {
			t.Errorf("%s = %q, want it logged as it was passed", key, a.Value)
		}
	}
}

// A request-scoped logger travels on the context so that every line a handler
// writes carries the request ID, without the request ID being threaded
// through every function it calls.
func TestTheRequestLoggerTravelsOnTheContext(t *testing.T) {
	var buf bytes.Buffer
	scoped := slog.New(slog.NewJSONHandler(&buf, nil)).With("request_id", "abc123")

	ctx := WithLogger(context.Background(), scoped)
	FromContext(ctx).Info("handled")
	if !strings.Contains(buf.String(), "abc123") {
		t.Errorf("log = %q, want the request's own logger to have written it", buf.String())
	}
}

// A context that carries none -- background work, a startup path -- still
// logs, through the default rather than through nothing.
func TestAContextWithNoLoggerFallsBackToTheDefault(t *testing.T) {
	l := setupForTest(t, Options{})
	if got := FromContext(context.Background()); got != l {
		t.Errorf("FromContext gave %p, want the default logger %p", got, l)
	}
	//nolint:staticcheck // a nil logger under the key is the same absence as no key at all.
	if got := FromContext(context.WithValue(context.Background(), ctxKey{}, (*slog.Logger)(nil))); got != l {
		t.Error("a nil logger on the context was returned instead of the default")
	}
}

// setupForTest runs Setup and puts the process-wide default back afterwards,
// so one test's level cannot decide another's.
func setupForTest(t *testing.T, o Options) *slog.Logger {
	t.Helper()
	before := slog.Default()
	t.Cleanup(func() { slog.SetDefault(before) })
	return Setup(o)
}

// Package machine works out what host this process is running on: which
// distribution and release, and how much machine there is to use.
//
// It is its own package because two callers need the same answer and neither
// should depend on the other: the agent reports these facts to the controller
// so a pool asking for Ubuntu 24.04 can be placed correctly, and the
// configuration loader uses them to give an unnamed host a name that says what
// it is instead of whatever the cloud provider called it.
package machine

import (
	"context"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
)

// Facts is what this host actually is: which distribution and release it
// runs, and how much of it there is.
//
// The controller needs all of it. The distribution and release decide whether
// a pool asking for Ubuntu 24.04 may be placed here -- "linux" cannot pick a
// runner image -- and the size is what lets a host be named for what it is
// rather than for whatever the cloud provider called it.
type Facts struct {
	// OS is the kernel, as Go names it: linux, darwin, windows.
	OS string
	// Distro and OSVersion are the distribution and its release, e.g.
	// "ubuntu" and "24.04". Empty when the host cannot say, which is not an
	// error: an unstated platform simply constrains nothing.
	Distro    string
	OSVersion string
	Arch      string
	// CPUs and MemoryMB are what this agent may actually use, which is not
	// always what the machine has -- an agent in a container gets the cgroup's
	// share, and reporting the host's 64 cores from inside a two-core cgroup
	// would size every pool wrong.
	CPUs     int
	MemoryMB int64
}

// Spec renders the machine in the naming grammar's terms, so that a host can
// be named for what it is.
func (m Facts) Spec(machine string) naming.Spec {
	os := m.Distro
	if naming.NormalizeOS(os) == "" {
		os = m.OS
	}
	return naming.Spec{
		CPUs:     float64(m.CPUs),
		MemoryGB: int(m.MemoryMB / 1024),
		OS:       os,
		Version:  m.OSVersion,
		Arch:     m.Arch,
		Suffix:   machine,
	}
}

// Detect works out what this host is. Every probe is best-effort: a field it
// cannot establish is left empty rather than guessed, because a host that
// claims the wrong platform is worse than one that claims none.
func Detect() Facts { return detect("/") }

// detect is Detect against an arbitrary filesystem root, which is what makes
// the Linux probes testable without a Linux host.
func detect(root string) Facts {
	m := Facts{OS: runtime.GOOS, Arch: runtime.GOARCH, CPUs: runtime.NumCPU()}
	switch runtime.GOOS {
	case "darwin":
		m.Distro = naming.OSMacOS
		m.OSVersion = macOSVersion()
		m.MemoryMB = sysctlMB("hw.memsize")
	case "windows":
		m.Distro = naming.OSWindows
		m.OSVersion, m.MemoryMB = windowsFacts()
	default:
		m.Distro, m.OSVersion = readOSRelease(filepath.Join(root, "etc", "os-release"))
		m.MemoryMB = readMemTotalMB(filepath.Join(root, "proc", "meminfo"))
	}
	// A cgroup limit is the real ceiling when there is one. The compose
	// deployment runs the controller's embedded agent in a container, so this
	// is the common case rather than an exotic one.
	if quota := cgroupCPUQuota(root); quota > 0 && quota < m.CPUs {
		m.CPUs = quota
	}
	if limit := cgroupMemoryMB(root); limit > 0 && (m.MemoryMB == 0 || limit < m.MemoryMB) {
		m.MemoryMB = limit
	}
	return m
}

// readOSRelease reads the distribution and release from /etc/os-release, the
// one file every Linux distribution Zoomies supports agrees on.
func readOSRelease(path string) (distro, version string) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", ""
	}
	for _, line := range strings.Split(string(b), "\n") {
		key, value, ok := strings.Cut(strings.TrimSpace(line), "=")
		if !ok {
			continue
		}
		value = strings.Trim(strings.TrimSpace(value), `"'`)
		switch key {
		case "ID":
			distro = value
		case "VERSION_ID":
			version = value
		}
	}
	// Normalise so that a host reporting "Ubuntu" and a pool asking for
	// "ubuntu" are the same platform. An ID outside the catalogue is dropped:
	// it would never match a pool, and keeping it would put a value in the
	// column that only looks like a promise.
	return naming.NormalizeOS(distro), version
}

// readMemTotalMB reads MemTotal from /proc/meminfo, which is in kibibytes.
func readMemTotalMB(path string) int64 {
	b, err := os.ReadFile(path)
	if err != nil {
		return 0
	}
	for _, line := range strings.Split(string(b), "\n") {
		rest, ok := strings.CutPrefix(line, "MemTotal:")
		if !ok {
			continue
		}
		fields := strings.Fields(rest)
		if len(fields) == 0 {
			return 0
		}
		kb, err := strconv.ParseInt(fields[0], 10, 64)
		if err != nil {
			return 0
		}
		return kb / 1024
	}
	return 0
}

// cgroupCPUQuota reads a cgroup v2 CPU limit as a whole number of cores,
// rounding up: a container limited to 1.5 cores can still burst onto two.
//
// "max" means unlimited, and so does an absent file, which is the case on a
// host running the agent directly.
func cgroupCPUQuota(root string) int {
	b, err := os.ReadFile(filepath.Join(root, "sys", "fs", "cgroup", "cpu.max"))
	if err != nil {
		return 0
	}
	fields := strings.Fields(string(b))
	if len(fields) != 2 || fields[0] == "max" {
		return 0
	}
	quota, err1 := strconv.ParseFloat(fields[0], 64)
	period, err2 := strconv.ParseFloat(fields[1], 64)
	if err1 != nil || err2 != nil || period <= 0 || quota <= 0 {
		return 0
	}
	return int(math.Ceil(quota / period))
}

// cgroupMemoryMB reads a cgroup v2 memory limit. "max" means unlimited.
func cgroupMemoryMB(root string) int64 {
	b, err := os.ReadFile(filepath.Join(root, "sys", "fs", "cgroup", "memory.max"))
	if err != nil {
		return 0
	}
	v := strings.TrimSpace(string(b))
	if v == "max" {
		return 0
	}
	bytes, err := strconv.ParseInt(v, 10, 64)
	if err != nil || bytes <= 0 {
		return 0
	}
	return bytes / (1024 * 1024)
}

// macOSVersion asks sw_vers, because macOS has no os-release. It is only ever
// a development host -- agents run on Linux -- so a failure is silent.
func macOSVersion() string { return firstWord(runProbe("sw_vers", "-productVersion")) }

// sysctlMB reads a byte-valued sysctl and returns it in mebibytes.
func sysctlMB(key string) int64 {
	bytes, err := strconv.ParseInt(firstWord(runProbe("sysctl", "-n", key)), 10, 64)
	if err != nil || bytes <= 0 {
		return 0
	}
	return bytes / (1024 * 1024)
}

// runProbe runs a short-lived read-only command, returning "" if anything at
// all goes wrong. Detection must never be the reason an agent fails to start.
func runProbe(name string, args ...string) string {
	path, err := exec.LookPath(name)
	if err != nil {
		return ""
	}
	// A bounded context, not just a wait delay: a probe that hangs must not
	// hold up the agent's start-up.
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, path, args...).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func firstWord(s string) string {
	if f := strings.Fields(s); len(f) > 0 {
		return f[0]
	}
	return ""
}

// Hostname is this machine's short name, or "localhost" when the host will not
// say. It is the discriminator in a canonical host name.
func Hostname() string {
	h, err := os.Hostname()
	if err != nil || strings.TrimSpace(h) == "" {
		return "localhost"
	}
	return h
}

// DefaultHostName is the name an unnamed host is given: what it is, then which
// one it is, in the grammar of internal/naming --
// "zoomies-16vcpu-32gb-ubuntu-2404-build01".
//
// A machine that would say nothing about itself falls back to its bare
// hostname rather than to the bare prefix, because "zoomies" is not a name and
// the hostname at least distinguishes two hosts.
func DefaultHostName() string {
	host := Hostname()
	spec := Detect().Spec(host)
	if spec.Empty() {
		return naming.Slug(host)
	}
	return spec.String()
}

