func TestSuggestIsStable(t *testing.T) {
	pools := []*store.Pool{
		pool("b-pool", "b-pool", "linux", "x64"),
		pool("a-pool", "a-pool", "linux", "x64"),
	}
	first := Suggest(pools, []string{"ubuntu-latest"})["ubuntu-latest"]
	for range 20 {
