//go:build ignore

// Command gen_catalogue writes the runner image catalogue everywhere outside Go
// that has to agree with it.
//
// internal/naming's catalogue is the list of operating systems a pool may ask
// for. Four other files have to say the same thing: the Makefile, so a
// contributor can build one variant by hand; both workflows, so every variant
// is actually built and published; and docs/naming.md, so an operator can see
// what is on offer. Kept by hand, that is four places to remember and a runner
// that will not start when somebody forgets one -- swapping Fedora 42 for
// Fedora 43 should be a row in images.go, not an archaeology exercise.
//
// So the four are generated. Each file carries a begin/end marker and this
// command rewrites what is between them, leaving everything else alone: these
// are files people edit for other reasons, and a generator that owned the whole
// file would own decisions it has no opinion about.
//
// Run it from the repository root after editing the catalogue:
//
//	go run internal/naming/gen_catalogue.go
//
// The tests in internal/naming fail, naming this command, when a file has
// drifted -- which is the case where somebody edited one of them by hand.
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"

	"github.com/eyupio/zoomies/internal/naming"
)

// The markers each generated block sits between. The comment syntax differs by
// file type; the marker word does not, so `grep -r zoomies:catalogue` finds
// every one of them.
const (
	marker      = "zoomies:catalogue"
	beginMarker = marker + "-begin"
	endMarker   = marker + "-end"
)

func main() {
	root, err := repoRoot()
	if err != nil {
		log.Fatal(err)
	}
	images := naming.Images()
	for _, f := range []struct {
		path string
		body string
	}{
		{"Makefile", makefileBlock(images)},
		{filepath.Join(".github", "workflows", "ci.yml"), matrixBlock(images)},
		{filepath.Join(".github", "workflows", "release.yml"), matrixBlock(images)},
		{filepath.Join("docs", "naming.md"), docsBlock(images)},
	} {
		path := filepath.Join(root, f.path)
		if err := rewrite(path, f.body); err != nil {
			log.Fatalf("%s: %v", f.path, err)
		}
		fmt.Println("wrote the catalogue into", f.path)
	}
}

// rewrite replaces the marked block in path with body, leaving the markers and
// their indentation exactly as they were.
func rewrite(path, body string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	lines := strings.Split(string(b), "\n")
	begin, end := -1, -1
	for i, line := range lines {
		switch {
		case strings.Contains(line, beginMarker):
			if begin >= 0 {
				return fmt.Errorf("two %s markers", beginMarker)
			}
			begin = i
		case strings.Contains(line, endMarker):
			if end >= 0 {
				return fmt.Errorf("two %s markers", endMarker)
			}
			end = i
		}
	}
	if begin < 0 || end < 0 || end < begin {
		return fmt.Errorf("no %s ... %s block to write into", beginMarker, endMarker)
	}
	out := append([]string{}, lines[:begin+1]...)
	out = append(out, strings.Split(body, "\n")...)
	out = append(out, lines[end:]...)
	return os.WriteFile(path, []byte(strings.Join(out, "\n")), 0o644)
}

// makefileBlock renders the variant table `make image-runner` drives.
func makefileBlock(images []naming.Image) string {
	var tags []string
	def := ""
	width := 0
	for _, img := range images {
		tags = append(tags, img.Tag())
		if img.Default {
			def = img.Tag()
		}
		width = max(width, len(img.Tag()))
	}
	var b strings.Builder
	fmt.Fprintf(&b, "RUNNER_VARIANTS := %s\n", strings.Join(tags, " "))
	fmt.Fprintf(&b, "RUNNER_VARIANT_DEFAULT := %s\n\n", def)
	b.WriteString("# base | family | os | version\n")
	for _, img := range images {
		fmt.Fprintf(&b, "variant.%-*s := %s %s %s %s\n",
			width, img.Tag(), img.Base, img.Family, img.OS, img.Version)
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// matrixBlock renders the `strategy.matrix` both workflows build from: one row
// per variant and architecture, because each architecture is built on a
// machine of its own kind and the rows are then merged into one manifest. The
// arm64 images used to be cross-built under QEMU on an x64 builder, and its
// aarch64 emulation segfaulted in ldconfig on Ubuntu 22.04's glibc; a native
// arm64 builder has no emulator to fail. `platforms` stays the variant's whole
// set on every row, since it is what the manifest has to cover. The rows are
// column-aligned because they are read as a table, not as YAML.
func matrixBlock(images []naming.Image) string {
	tagWidth, baseWidth, osWidth, versionWidth := 0, 0, 0, 0
	for _, img := range images {
		tagWidth = max(tagWidth, len(img.Tag()))
		baseWidth = max(baseWidth, len(quote(img.Base))+1)
		osWidth = max(osWidth, len(img.OS)+1)
		versionWidth = max(versionWidth, len(quote(img.Version))+1)
	}
	var b strings.Builder
	b.WriteString("        include:\n")
	for _, img := range images {
		for _, arch := range img.Arches {
			fmt.Fprintf(&b, "          - { tag: %-*s arch: %-6s base: %-*s family: %s, os: %-*s version: %-*s platforms: %s%s }\n",
				tagWidth+1, img.Tag()+",",
				arch+",",
				baseWidth, quote(img.Base)+",",
				img.Family,
				osWidth, img.OS+",",
				versionWidth, quote(img.Version)+",",
				quote(platforms(img)),
				defaultField(img)+fullField(img))
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// platforms renders a variant's architectures as the `platforms:` value buildx
// takes. It comes from the catalogue rather than the job, because the variants
// are not all publishable for the same set -- and a workflow that asked for one
// nothing can build would fail the whole matrix rather than the row that means
// it.
func platforms(img naming.Image) string {
	out := make([]string, 0, len(img.Arches))
	for _, arch := range img.Arches {
		out = append(out, "linux/"+arch)
	}
	return strings.Join(out, ",")
}

// defaultField marks the one variant that carries the unqualified tags. Only
// the default row has the key at all: a `default: false` on every other row
// would be four more things to keep true for no reader's benefit.
func defaultField(img naming.Image) string {
	if img.Default {
		return ", default: true"
	}
	return ""
}

// fullField marks a variant that is also built as runner-full, on the same
// terms as defaultField: only the rows that are carry the key.
func fullField(img naming.Image) string {
	if img.Full {
		return ", full: true"
	}
	return ""
}

// quote renders a YAML scalar that has to stay a string. A version like 24.04
// is a float to YAML, and an image reference carries a colon.
func quote(s string) string { return `"` + s + `"` }

// docsBlock renders the table on the site that says what an operator may ask
// for.
func docsBlock(images []naming.Image) string {
	var b strings.Builder
	b.WriteString("| Tag | Base | Architectures | `zoomies-runner-full` |\n")
	b.WriteString("| --- | --- | --- | --- |\n")
	for _, img := range images {
		full := "—"
		if img.Full {
			full = "yes"
		}
		fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s |\n", img.Tag(), img.Base, strings.Join(img.Arches, ", "), full)
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// repoRoot walks up from the working directory looking for go.mod, so that the
// command works both from the repository root and from the package it lives in.
func repoRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("no go.mod above %s: run this from the repository", dir)
		}
		dir = parent
	}
}

package naming

import (
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"
)

// The catalogue in this package says which operating systems a pool may ask
// for. Four files outside Go have to say the same thing -- both workflows, the
// Makefile and the site -- and gen_catalogue.go writes all four, so the tests
// here are about a file somebody edited by hand rather than regenerating.
//
// They compare meaning rather than bytes, because that is the failure that
// matters: an operating system half-added, where either a pool can name an
// image nothing publishes, or an image is published that no pool can ask for.
// Neither shows up until a runner refuses to start.

// regenerate is what every failure in this file tells the reader to do.
const regenerate = "run `make generate` and commit the result"

func TestWorkflowMatricesCoverTheCatalogue(t *testing.T) {
	for _, wf := range []struct{ file, job string }{
		{"ci.yml", "runner-images"},
		{"release.yml", "runner-images"},
	} {
		t.Run(wf.file, func(t *testing.T) {
			got, arches := runnerMatrix(t, wf.file, wf.job)
			want := map[string]matrixEntry{}
			for _, img := range Images() {
				plats := make([]string, 0, len(img.Arches))
				for _, arch := range img.Arches {
					plats = append(plats, "linux/"+arch)
				}
				want[img.Tag()] = matrixEntry{
					Base: img.Base, Family: img.Family, OS: img.OS, Version: img.Version,
					Platforms: strings.Join(plats, ","), Full: img.Full,
				}
			}
			for tag, w := range want {
				g, ok := got[tag]
				if !ok {
					t.Errorf("%s builds no %s image, but the catalogue publishes one; %s", wf.file, tag, regenerate)
					continue
				}
				if g != w {
					t.Errorf("%s builds %s as %+v, but the catalogue says %+v; %s", wf.file, tag, g, w, regenerate)
				}
				// Each architecture is its own row, built on a machine of that
				// architecture, and the rows are merged into one manifest. A
				// platform with no row of its own would be named by the manifest
				// and built by nothing.
				if built := strings.Join(arches[tag], ","); built != w.Platforms {
					t.Errorf("%s builds %s on %s machines, but it is published for %s; %s", wf.file, tag, built, w.Platforms, regenerate)
				}
			}
			for tag := range got {
				if _, ok := want[tag]; !ok {
					t.Errorf("%s builds %s, which is not in the catalogue, so no pool can ask for it; %s", wf.file, tag, regenerate)
				}
			}
		})
	}
}

// matrixEntry is the part of a matrix row that has to agree with the catalogue.
//
// Platforms is in here because a variant's architectures are a claim the
// registry has to be able to satisfy: a catalogue row saying arm64 that the
// workflow does not build for arm64 gives a pool an image reference that
// resolves to nothing.
type matrixEntry struct {
	Base      string `yaml:"base"`
	Family    string `yaml:"family"`
	OS        string `yaml:"os"`
	Version   string `yaml:"version"`
	Platforms string `yaml:"platforms"`
	// Full is whether the row also builds runner-full. A catalogue row that
	// says so and a matrix that does not is a tag a pool can name and the
	// registry does not have.
	Full bool `yaml:"full"`
}

func runnerMatrix(t *testing.T, file, job string) (map[string]matrixEntry, map[string][]string) {
	t.Helper()
	var wf struct {
		Jobs map[string]struct {
			Strategy struct {
				Matrix struct {
					Include []struct {
						Tag         string `yaml:"tag"`
						Arch        string `yaml:"arch"`
						matrixEntry `yaml:",inline"`
					} `yaml:"include"`
				} `yaml:"matrix"`
			} `yaml:"strategy"`
		} `yaml:"jobs"`
	}
	b, err := os.ReadFile(filepath.Join("..", "..", ".github", "workflows", file))
	if err != nil {
		t.Fatalf("reading the workflow: %v", err)
	}
	if err := yaml.Unmarshal(b, &wf); err != nil {
		t.Fatalf("parsing %s: %v", file, err)
	}
	j, ok := wf.Jobs[job]
	if !ok {
		t.Fatalf("%s has no %s job", file, job)
	}
	out := map[string]matrixEntry{}
	arches := map[string][]string{}
	for _, row := range j.Strategy.Matrix.Include {
		if prev, ok := out[row.Tag]; ok && prev != row.matrixEntry {
			t.Errorf("%s's %s rows for %s disagree about what they build", file, job, row.Tag)
		}
		out[row.Tag] = row.matrixEntry
		arches[row.Tag] = append(arches[row.Tag], "linux/"+row.Arch)
	}
	if len(out) == 0 {
		t.Fatalf("%s's %s job builds nothing", file, job)
	}
	return out, arches
}

// The Makefile builds the same variants by hand, because a contributor
// debugging a Fedora runner wants `make image-runner RUNNER_VARIANT=fedora-42`
// and not a workflow run. It drifts from the catalogue just as easily.
func TestMakefileBuildsTheCatalogue(t *testing.T) {
	b, err := os.ReadFile(filepath.Join("..", "..", "Makefile"))
	if err != nil {
		t.Fatalf("reading the Makefile: %v", err)
	}
	// The rows are column-aligned, so compare on fields rather than on the
	// exact spacing a contributor is free to adjust.
	rows := map[string]string{}
	var listed []string
	for _, line := range strings.Split(string(b), "\n") {
		fields := strings.Fields(line)
		switch {
		case len(fields) >= 2 && fields[0] == "RUNNER_VARIANTS" && fields[1] == ":=":
			listed = fields[2:]
		case len(fields) >= 2 && strings.HasPrefix(fields[0], "variant.") && fields[1] == ":=":
			rows[strings.TrimPrefix(fields[0], "variant.")] = strings.Join(fields[2:], " ")
		}
	}
	if len(listed) == 0 {
		t.Fatal("the Makefile no longer lists RUNNER_VARIANTS")
	}
	for _, img := range Images() {
		want := strings.Join([]string{img.Base, img.Family, img.OS, img.Version}, " ")
		got, ok := rows[img.Tag()]
		if !ok {
			t.Errorf("the Makefile has no row building %s; %s", img.Tag(), regenerate)
			continue
		}
		if got != want {
			t.Errorf("the Makefile builds %s as %q, but the catalogue says %q; %s", img.Tag(), got, want, regenerate)
		}
		if !slices.Contains(listed, img.Tag()) {
			t.Errorf("%s has a row but is not in RUNNER_VARIANTS, so `make images-runner` skips it; %s", img.Tag(), regenerate)
		}
	}
	for _, tag := range listed {
		if _, ok := FindImage(splitTag(tag)); !ok {
			t.Errorf("the Makefile builds %q, which is not in the catalogue; %s", tag, regenerate)
		}
	}
}

// splitTag turns an image tag back into the OS and version FindImage takes.
func splitTag(tag string) (string, string) {
	os, version, _ := strings.Cut(tag, "-")
	return os, ExpandVersion(os, version)
}

// The site's table is what an operator reads before choosing a pool's platform,
// and it is the copy nothing else checks: a stale row here sends somebody to
// name an image that was swapped out two releases ago.
func TestDocsListTheCatalogue(t *testing.T) {
	b, err := os.ReadFile(filepath.Join("..", "..", "docs", "naming.md"))
	if err != nil {
		t.Fatalf("reading the naming page: %v", err)
	}
	rows := map[string]string{}
	for _, line := range strings.Split(string(b), "\n") {
		cells := strings.Split(strings.Trim(strings.TrimSpace(line), "|"), "|")
		if len(cells) != 4 {
			continue
		}
		tag := strings.Trim(strings.TrimSpace(cells[0]), "`")
		if _, ok := FindImage(splitTag(tag)); !ok {
			continue
		}
		rows[tag] = strings.Trim(strings.TrimSpace(cells[1]), "`") + " " + strings.TrimSpace(cells[2]) + " " + strings.TrimSpace(cells[3])
	}
	for _, img := range Images() {
		full := "—"
		if img.Full {
			full = "yes"
		}
		want := img.Base + " " + strings.Join(img.Arches, ", ") + " " + full
		switch got, ok := rows[img.Tag()]; {
		case !ok:
			t.Errorf("the naming page does not list %s, which the catalogue publishes; %s", img.Tag(), regenerate)
		case got != want:
			t.Errorf("the naming page lists %s as %q, but the catalogue says %q; %s", img.Tag(), got, want, regenerate)
		}
	}
	if len(rows) != len(Images()) {
		t.Errorf("the naming page lists %d variants, the catalogue has %d; %s", len(rows), len(Images()), regenerate)
	}
}

// The catalogue is also named in prose, on the configuration page, where a
// generated block would read as a list bolted into a sentence. So it is
// checked instead: an operator told to name an image needs the list of images
// beside the setting that takes one.
// TestTheLandingSurfacesNameEveryVariant holds the two hand-maintained pages
// that list the catalogue in prose.
//
// The generator writes four files and docs/naming.md is the only page among
// them, so README.md and docs/index.md would otherwise go silently stale the
// day a variant is added or a version moves -- and both are the first thing a
// reader meets, which is the worst place to be wrong about what is published.
// A test rather than a fifth generator target because these are sentences
// written for a person, not a table: what must not drift is the set of names,
// not the words around them.
func TestTheLandingSurfacesNameEveryVariant(t *testing.T) {
	for _, page := range []string{
		filepath.Join("..", "..", "README.md"),
		filepath.Join("..", "..", "docs", "index.md"),
	} {
		b, err := os.ReadFile(page)
		if err != nil {
			t.Fatalf("reading %s: %v", page, err)
		}
		for _, img := range Images() {
			name := PrettyOS(img.OS) + " " + img.Version
			if !strings.Contains(string(b), name) {
				t.Errorf("%s never names %q, so the page a reader meets first no longer says what is published",
					filepath.Base(page), name)
			}
		}
	}
}

func TestConfigurationPageNamesEveryVariant(t *testing.T) {
	b, err := os.ReadFile(filepath.Join("..", "..", "docs", "configuration.md"))
	if err != nil {
		t.Fatalf("reading the configuration page: %v", err)
	}
	for _, img := range Images() {
		if !strings.Contains(string(b), "`"+img.Tag()+"`") {
			t.Errorf("the configuration page never mentions the %s image, so nothing tells an operator they may ask for it", img.Tag())
		}
	}
}

package naming

import (
	"fmt"
	"slices"
	"strings"
)

// RunnerImageRepo is where the images built from deploy/Dockerfile.runner are
// published. One repository with a tag per operating system, rather than a
// repository per operating system, so that `docker pull` autocompletion and
// the GHCR package page both show the whole catalogue at once.
const RunnerImageRepo = "ghcr.io/eyupio/zoomies-runner"

// RunnerFullImageRepo is where the runner-full target of the same Dockerfile is
// published, under the same tags as RunnerImageRepo, for the variants whose
// catalogue row is Full.
const RunnerFullImageRepo = "ghcr.io/eyupio/zoomies-runner-full"

// Image is one variant of the runner image: an operating system, the version
// of it, and the architectures that variant is published for.
type Image struct {
	// OS and Version are the platform the variant provides, in the same
	// spelling a Spec uses.
	OS      string
	Version string
	// Base is the upstream image the variant is built FROM. It is here rather
	// than only in the Dockerfile because the catalogue is what the docs, the
	// release matrix and the pool validator all read.
	Base string
	// Family is the package manager the variant installs with, which is the
	// only thing deploy/Dockerfile.runner has to branch on.
	Family string
	// Arches lists the architectures the variant is published for.
	Arches []string
	// Default marks the variant that :latest points at, and the one a pool
	// gets when it has not said which operating system it wants.
	Default bool
	// Full marks a variant that is also published as RunnerFullImageRepo:
	// the runner with the language toolchains the setup-* actions would
	// otherwise download already in its tool cache. Only Ubuntu carries it,
	// because Python's prebuilt interpreters -- the ones setup-python
	// installs -- are built for Ubuntu and nothing else.
	Full bool
}

// Tag is the image tag this variant is published under, e.g. "ubuntu-2404".
// It is the OS half of a Spec, which is what makes an image tag and a pool
// name agree by construction rather than by an operator remembering to keep
// them in step.
func (i Image) Tag() string {
	if v := CompactVersion(i.Version); v != "" {
		return i.OS + "-" + v
	}
	return i.OS
}

// Ref is the fully qualified image reference for this variant.
func (i Image) Ref() string { return RunnerImageRepo + ":" + i.Tag() }

// Describe renders the variant for prose: "Ubuntu 24.04 (amd64, arm64)".
func (i Image) Describe() string {
	return fmt.Sprintf("%s %s (%s)", PrettyOS(i.OS), i.Version, strings.Join(i.Arches, ", "))
}

// Supports reports whether this variant is published for an architecture. An
// empty arch is not a mismatch -- the caller simply has not said -- but an
// architecture Zoomies does not build for at all is.
func (i Image) Supports(arch string) bool {
	if strings.TrimSpace(arch) == "" {
		return true
	}
	return slices.Contains(i.Arches, NormalizeArch(arch))
}

// The package-manager families deploy/Dockerfile.runner knows how to drive.
const (
	FamilyAPT = "apt"
	FamilyDNF = "dnf"
)

// The architecture sets a variant can be published for. They are package-level
// slices so that callers cannot accidentally alias one variant's list into
// another's; runnerImages hands out copies.
//
// A variant's Arches is not a wish: it is what CI actually builds, because the
// generated workflow matrices are written from it. A row claiming an
// architecture nothing publishes gives a pool a tag that does not exist, which
// is a runner that will not start rather than a validation error.
var (
	bothArches = []string{ArchAMD64, ArchARM64}
)

// runnerImages is the catalogue, and the one place an operating system is added
// or swapped. A row here plus `make generate` is the whole of it: the generator
// rewrites both workflows' matrices, the Makefile's build variants and the
// table on the site from these rows, and the Dockerfile already handles both
// package families. The pool validator reads the same list to tell an operator
// what they may ask for.
//
// Alpine is deliberately absent. actions/runner ships glibc binaries and .NET
// dependencies that musl does not satisfy, so an Alpine variant would build
// and then fail at the first job, which is worse than not offering it.
var runnerImages = []Image{
	{OS: OSUbuntu, Version: "24.04", Base: "ubuntu:24.04@sha256:224a1869083a311ef3f13648a154ba79832fbef6364d31493642ca03082da254", Family: FamilyAPT, Arches: bothArches, Default: true, Full: true},
	{OS: OSUbuntu, Version: "26.04", Base: "ubuntu:26.04@sha256:da6fc2be547864451aa253836dd926da33623312df4a9a243e35dc877c378a78", Family: FamilyAPT, Arches: bothArches, Full: true},
	{OS: OSUbuntu, Version: "22.04", Base: "ubuntu:22.04@sha256:829f6df217bcbae2b371026e81711d1a787c61b2967ad09d015063663ebafbf7", Family: FamilyAPT, Arches: bothArches, Full: true},
	{OS: OSDebian, Version: "13", Base: "debian:13-slim@sha256:a99cfc517144bc59b1978475ec53b46ecabec7e43635402ee5b77cc54cd1b20a", Family: FamilyAPT, Arches: bothArches},
	{OS: OSDebian, Version: "12", Base: "debian:12-slim@sha256:88200866dfff7ea7f5cbcb6ec7c8a701889efe6fe859fe64d6990e4b07ea4171", Family: FamilyAPT, Arches: bothArches},
	{OS: OSFedora, Version: "42", Base: "fedora:42@sha256:99e203b80b1c3d8f7e161ec10a68fd02b081ef83a3963553e513c82846b97814", Family: FamilyDNF, Arches: bothArches},
	{OS: OSRocky, Version: "9", Base: "rockylinux/rockylinux:9@sha256:8101994123cf3d0a8fee517bee7f39e555c7d92bd2d9eb3303cc988a0eeed00f", Family: FamilyDNF, Arches: bothArches},
}

// Images returns the catalogue in the order the docs and the UI list it, with
// the default variant first.
func Images() []Image {
	out := make([]Image, len(runnerImages))
	copy(out, runnerImages)
	return out
}

// DefaultImage returns the variant :latest points at.
func DefaultImage() Image {
	for _, i := range runnerImages {
		if i.Default {
			return i
		}
	}
	return runnerImages[0]
}

// DefaultRunnerImage is the image reference a pool gets when it names neither
// an image nor an operating system.
func DefaultRunnerImage() string { return RunnerImageRepo + ":" + RunnerImageTag }

// RunnerImageTag is stamped by the container build independently of the binary
// version. Native builds retain the released channel. Container builds use dev
// or the release tag, including its leading v, as published by the workflows.
var RunnerImageTag = "latest"

// SplitImage separates an image reference into its repository, its tag with the
// colon still on it, and its digest with the @ still on it.
//
// Splitting on the last colon is wrong twice over, and both ways produce a
// reference that looks plausible and pulls nothing: a registry may carry a port,
// so registry.example.com:5000/zoomies would lose its host, and a digest carries
// a colon of its own inside sha256:....
func SplitImage(ref string) (repo, tag, digest string) {
	if i := strings.Index(ref, "@"); i >= 0 {
		ref, digest = ref[:i], ref[i:]
	}
	// A colon after the last slash is a tag; one before it belongs to the
	// registry's port.
	if i := strings.LastIndex(ref, ":"); i >= 0 && !strings.Contains(ref[i+1:], "/") {
		ref, tag = ref[:i], ref[i:]
	}
	return ref, tag, digest
}

// PublishedRunnerTag reports whether a runner image tag is one this build's own
// catalogue accounts for: the moving channels, the channel this binary was
// stamped with, and every variant in the catalogue under any of them.
//
// It answers the only question a caller translating between the stock runner
// image and its Docker variant can answer without asking a registry. One step
// of one workflow publishes both images, so a tag this build hands out exists
// for both or for neither -- while a tag somebody pinned from another build
// promises nothing: a run whose second build did not finish leaves that commit
// tag on one image and not the other, and a release old enough predates the
// variant altogether. A pool moved onto a tag the registry lacks stops running
// every job, including the ones that never touch Docker.
func PublishedRunnerTag(tag string) bool {
	tag = strings.TrimPrefix(strings.TrimSpace(tag), ":")
	// No tag is the registry's "latest", which both images carry.
	if tag == "" {
		return true
	}
	for _, i := range runnerImages {
		// The released channel publishes the bare alias rather than
		// <variant>-latest, which is why the alias stands on its own.
		if tag == i.Tag() {
			return true
		}
	}
	for _, channel := range channels() {
		if tag == channel {
			return true
		}
		for _, i := range runnerImages {
			if tag == i.Tag()+"-"+channel {
				return true
			}
		}
	}
	return false
}

// channels lists the tags a runner image is published under that are not one
// variant's alias: the two that follow a branch, the one that follows the
// newest release, and whichever this binary was built to ask for.
func channels() []string {
	out := []string{"latest", "main", "dev"}
	if tag := strings.TrimSpace(RunnerImageTag); tag != "" && !slices.Contains(out, tag) {
		out = append(out, tag)
	}
	return out
}

// FindImage returns the catalogue entry for an operating system and version.
//
// An empty version means "whichever one we publish", which is how a pool that
// says only "ubuntu" still gets a working image. A version that is not
// published is a miss rather than a silent downgrade: quietly running Ubuntu
// 24.04 for a pool that asked for 20.04 is exactly the kind of surprise this
// package exists to remove.
func FindImage(os, version string) (Image, bool) {
	o := NormalizeOS(os)
	if o == "" {
		return Image{}, false
	}
	want := CompactVersion(version)
	var fallback Image
	found := false
	for _, i := range runnerImages {
		if i.OS != o {
			continue
		}
		if want != "" && CompactVersion(i.Version) == want {
			return i, true
		}
		if !found || i.Default {
			fallback, found = i, true
		}
	}
	if want != "" || !found {
		return Image{}, false
	}
	return fallback, true
}

// RunnerImageFor returns the image reference for a platform, and whether the
// catalogue publishes one. Callers that get false should keep whatever image
// they already had rather than substitute a different operating system.
func RunnerImageFor(os, version string) (string, bool) {
	i, ok := FindImage(os, version)
	if !ok {
		return "", false
	}
	ref := i.Ref()
	// The released channel uses bare platform aliases, not <platform>-latest.
	if RunnerImageTag != "latest" {
		ref += "-" + RunnerImageTag
	}
	return ref, true
}

// ResolveRunnerImage picks the image a pool's runners boot.
//
// A pool that names an image gets it unchanged: an operator who has built
// their own is not second-guessed. Otherwise the pool's platform picks the
// variant, so a pool called zoomies-4vcpu-debian-12 boots the Debian 12 image
// without anyone keeping the two in step by hand. A pool that names neither
// gets the instance default.
func ResolveRunnerImage(poolImage, os, version, instanceDefault string) string {
	if img := strings.TrimSpace(poolImage); img != "" {
		return img
	}
	if ref, ok := RunnerImageFor(os, version); ok {
		return ref
	}
	return instanceDefault
}

// SupportedPlatforms renders the catalogue as the sentence an error message
// uses to tell an operator what they may ask for.
func SupportedPlatforms() string {
	out := make([]string, 0, len(runnerImages))
	for _, i := range runnerImages {
		out = append(out, PrettyOS(i.OS)+" "+i.Version)
	}
	return strings.Join(out, ", ")
}

package naming

import (
	"strings"
	"testing"
)

func TestCatalogueTagsMatchPoolNames(t *testing.T) {
	// An image tag and the OS half of a pool name are the same string by
	// construction. If that ever stops being true, a pool named for Ubuntu
	// 24.04 could quietly run a Debian image.
	for _, img := range Images() {
		spec := Spec{OS: img.OS, Version: img.Version}
		name := PoolName(spec)
		if !strings.HasSuffix(name, img.Tag()) {
			t.Errorf("pool name %q does not end in the image tag %q", name, img.Tag())
		}
		if got, want := img.Ref(), RunnerImageRepo+":"+img.Tag(); got != want {
			t.Errorf("Ref = %q, want %q", got, want)
		}
	}
}

func TestCatalogueIsWellFormed(t *testing.T) {
	defaults := 0
	seen := map[string]bool{}
	for _, img := range Images() {
		if NormalizeOS(img.OS) != img.OS {
			t.Errorf("catalogue entry %q is not a normalised OS", img.OS)
		}
		if img.Family != FamilyAPT && img.Family != FamilyDNF {
			t.Errorf("%s: family %q is not one deploy/Dockerfile.runner can drive", img.Tag(), img.Family)
		}
		if img.Base == "" {
			t.Errorf("%s: no base image", img.Tag())
		}
		if len(img.Arches) == 0 {
			t.Errorf("%s: published for no architecture", img.Tag())
		}
		for _, a := range img.Arches {
			if NormalizeArch(a) != a {
				t.Errorf("%s: architecture %q is not normalised", img.Tag(), a)
			}
		}
		if seen[img.Tag()] {
			t.Errorf("%s: duplicate tag", img.Tag())
		}
		seen[img.Tag()] = true
		if img.Default {
			defaults++
		}
	}
	if defaults != 1 {
		t.Errorf("the catalogue has %d default variants; :latest can only point at one", defaults)
	}
}

func TestFindImage(t *testing.T) {
	if img, ok := FindImage("ubuntu", "22.04"); !ok || img.Tag() != "ubuntu-2204" {
		t.Errorf("FindImage(ubuntu, 22.04) = %q, %v", img.Tag(), ok)
	}
	// An OS with no version gets whichever one we publish, preferring the
	// default, so a pool that says only "ubuntu" still starts.
	if img, ok := FindImage("Ubuntu", ""); !ok || img.Tag() != DefaultImage().Tag() {
		t.Errorf("FindImage(Ubuntu, \"\") = %q, %v; want the default variant", img.Tag(), ok)
	}
	// A version we do not publish is a miss, not a silent substitution.
	if _, ok := FindImage("ubuntu", "20.04"); ok {
		t.Error("FindImage substituted a different Ubuntu for one we do not publish")
	}
	if _, ok := FindImage("plan9", ""); ok {
		t.Error("FindImage claimed an operating system that is not in the catalogue")
	}
}

func TestRunnerImageFor(t *testing.T) {
	ref, ok := RunnerImageFor("debian", "12")
	if !ok || ref != RunnerImageRepo+":debian-12" {
		t.Errorf("RunnerImageFor(debian, 12) = %q, %v", ref, ok)
	}
	if ref, ok := RunnerImageFor("", ""); ok {
		t.Errorf("RunnerImageFor with no platform returned %q; the caller keeps its own default", ref)
	}
}

func TestImageSupports(t *testing.T) {
	img := DefaultImage()
	if !img.Supports("arm64") || !img.Supports("amd64") {
		t.Errorf("%s should be published for both architectures", img.Tag())
	}
	if !img.Supports("") {
		t.Error("an unstated architecture is not a mismatch")
	}
	if img.Supports("riscv64") {
		t.Error("Supports accepted an architecture nothing publishes")
	}
}

func TestDefaultRunnerImage(t *testing.T) {
	if got, want := DefaultRunnerImage(), RunnerImageRepo+":latest"; got != want {
		t.Errorf("DefaultRunnerImage = %q, want %q", got, want)
	}
	if !strings.Contains(SupportedPlatforms(), "Ubuntu 24.04") {
		t.Errorf("SupportedPlatforms = %q, which does not name the default", SupportedPlatforms())
	}
}

func TestRunnerImagesFollowBuildChannelAndKeepOverrides(t *testing.T) {
	original := RunnerImageTag
	t.Cleanup(func() { RunnerImageTag = original })
	for _, tag := range []string{"latest", "dev", "main", "sha-abc1234", "v1.2.3", "v1.3.0-rc1"} {
		t.Run(tag, func(t *testing.T) {
			RunnerImageTag = tag
			fallback := DefaultRunnerImage()
			if want := RunnerImageRepo + ":" + tag; fallback != want {
				t.Fatalf("default = %q, want %q", fallback, want)
			}
			for _, variant := range Images() {
				want := variant.Ref()
				if tag != "latest" {
					want += "-" + tag
				}
				if got := ResolveRunnerImage("", variant.OS, variant.Version, fallback); got != want {
					t.Errorf("platform %s = %q, want %q", variant.Tag(), got, want)
				}
			}
			for _, override := range []string{RunnerImageRepo + ":latest", "registry.example/runner:custom", "registry.example/runner@sha256:abcd"} {
				if got := ResolveRunnerImage(override, "debian", "12", fallback); got != override {
					t.Errorf("pool override changed to %q", got)
				}
				if got := ResolveRunnerImage("", "", "", override); got != override {
					t.Errorf("instance override changed to %q", got)
				}
			}
			if got := ResolveRunnerImage("", "", "", fallback); got != fallback {
				t.Errorf("fallback = %q, want %q", got, fallback)
			}
		})
	}
}

// SplitImage is tested on its own because its callers cannot reach half of
// it: a stock reference never carries a registry port, so the guard that keeps
// a port from being read as a tag is invisible through them -- a reference with
// one is refused for having the wrong repository long before the split matters.
// Asserting it here is what makes it a tested rule rather than a comment.
func TestSplitImageKeepsARegistryPortOutOfTheTag(t *testing.T) {
	const digest = "@sha256:8c2f1a9e5b3d4c6a7e8f0b1d2c3a4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f"
	for _, tc := range []struct{ ref, repo, tag, digest string }{
		{"ghcr.io/eyupio/zoomies:v1.2.3", "ghcr.io/eyupio/zoomies", ":v1.2.3", ""},
		{"ghcr.io/eyupio/zoomies", "ghcr.io/eyupio/zoomies", "", ""},
		// The colon belongs to the registry, and reading it as a tag would
		// leave the repository as a bare hostname that pulls nothing.
		{"registry.example.com:5000/zoomies", "registry.example.com:5000/zoomies", "", ""},
		{"registry.example.com:5000/zoomies:v1.2.3", "registry.example.com:5000/zoomies", ":v1.2.3", ""},
		// A digest has a colon of its own, inside it.
		{"ghcr.io/eyupio/zoomies" + digest, "ghcr.io/eyupio/zoomies", "", digest},
		{"ghcr.io/eyupio/zoomies:v1.2.3" + digest, "ghcr.io/eyupio/zoomies", ":v1.2.3", digest},
		{"registry.example.com:5000/zoomies" + digest, "registry.example.com:5000/zoomies", "", digest},
	} {
		t.Run(tc.ref, func(t *testing.T) {
			repo, tag, dg := SplitImage(tc.ref)
			if repo != tc.repo || tag != tc.tag || dg != tc.digest {
				t.Errorf("SplitImage(%q) = (%q, %q, %q), want (%q, %q, %q)",
					tc.ref, repo, tag, dg, tc.repo, tc.tag, tc.digest)
			}
		})
	}
}

// The rule the Docker swap rests on: a tag this build hands out is published
// for the stock runner image and its Docker variant by one step of one
// workflow, so it exists for both or for neither. A tag somebody pinned from
// another build promises nothing -- the registry carries eight commit tags for
// one image and not the other, from runs whose second build never finished --
// and moving a pool onto a tag that is not there would stop it running every
// job, including the ones that never touch Docker.
func TestPublishedRunnerTagAcceptsWhatThisBuildHandsOut(t *testing.T) {
	previous := RunnerImageTag
	t.Cleanup(func() { RunnerImageTag = previous })
	RunnerImageTag = "v1.4.0"
	variant := DefaultImage().Tag()
	for _, tag := range []string{
		"", ":latest", "latest", "main", "dev", "v1.4.0",
		variant, variant + "-main", variant + "-dev", variant + "-v1.4.0",
	} {
		if !PublishedRunnerTag(tag) {
			t.Errorf("PublishedRunnerTag(%q) = false; this build hands that tag out", tag)
		}
	}
	for _, tag := range []string{
		"sha-b966fb6", variant + "-sha-b966fb6", "v0.1-alpha", variant + "-v0.1-alpha",
		"alpine-3", "alpine-3-dev", "anything-else",
	} {
		if PublishedRunnerTag(tag) {
			t.Errorf("PublishedRunnerTag(%q) = true; nothing here publishes that tag", tag)
		}
	}
}

package naming

import "math/rand/v2"

// Kennel is the word list a generated name draws its memorable half from.
//
// Cocker spaniels, as cocker spaniels are actually named. The mark is a cocker
// spaniel doing zoomies, so the fleet is a kennel. Every word is one segment of
// lowercase letters -- nothing to sanitise away -- and short enough that the
// shape half of a name survives the length budget alongside it.
//
// It is the same list the pool wizard offers, in web/src/lib/pools/names.ts.
// TestKennelMatchesTheWizard fails if the two drift apart, because a fleet
// whose pools are named from one list and whose runners are named from another
// looks like two products.
var Kennel = []string{
	"banjo",
	"biscuit",
	"boogie",
	"bramble",
	"bubbles",
	"cocoa",
	"crumpet",
	"custard",
	"digby",
	"disco",
	"flapjack",
	"gizmo",
	"hazel",
	"jellybean",
	"jitterbug",
	"maple",
	"marmalade",
	"muffin",
	"noodle",
	"pancake",
	"pepper",
	"pickles",
	"popcorn",
	"rascal",
	"rocket",
	"rusty",
	"scampi",
	"toffee",
	"truffle",
	"waffles",
	"wiggles",
	"ziggy",
}

// KennelWord returns one word from the kennel.
//
// The randomness is cosmetic and math/rand is the right amount of machinery
// for it: nothing depends on a word being unguessable. What a name depends on
// for uniqueness is the token beside it, which comes from crypto/rand.
func KennelWord() string { return Kennel[rand.IntN(len(Kennel))] }

package naming

import (
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"
)

// The wizard names pools from its own copy of the kennel, in TypeScript,
// because the name has to appear in a form field before anything is created.
// Two lists that drift apart give a fleet pools called one thing and runners
// called another, which reads as two products rather than one -- so the lists
// are compared here rather than trusted to stay equal.
func TestKennelMatchesTheWizard(t *testing.T) {
	path := filepath.Join("..", "..", "web", "src", "lib", "pools", "names.ts")
	src, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading the wizard's word list: %v", err)
	}
	block := regexp.MustCompile(`(?s)KENNEL: readonly string\[\] = \[(.*?)\];`).FindSubmatch(src)
	if block == nil {
		t.Fatalf("%s no longer declares KENNEL the way this test reads it", path)
	}
	var wizard []string
	for _, m := range regexp.MustCompile(`'([a-z]+)'`).FindAllStringSubmatch(string(block[1]), -1) {
		wizard = append(wizard, m[1])
	}
	if !slices.Equal(wizard, Kennel) {
		t.Errorf("the wizard's kennel and this package's have drifted apart:\n  wizard: %v\n  Go:     %v", wizard, Kennel)
	}
}

func TestKennelWordsFitInAName(t *testing.T) {
	seen := map[string]bool{}
	for _, word := range Kennel {
		// A word that needed sanitising would arrive in a name as something
		// other than what this list says, and a duplicate would quietly halve
		// an already small pool of words.
		if Slug(word) != word {
			t.Errorf("kennel word %q is not already a name segment; Slug makes it %q", word, Slug(word))
		}
		if seen[word] {
			t.Errorf("kennel word %q appears twice", word)
		}
		seen[word] = true
		// The budget: the brand, the longest shape a fleet can really have, the
		// word, and the token, all inside GitHub's limit.
		spec := Spec{CPUs: 192, MemoryGB: 768, OS: OSUbuntu, Version: "24.04", Arch: ArchARM64}
		name := RunnerName(spec.String(), word+"-a3f9qz2m")
		if !strings.Contains(name, word) || len(name) > MaxNameLength {
			t.Errorf("kennel word %q does not fit: %q is %d characters", word, name, len(name))
		}
	}
}

func TestKennelWordComesFromTheKennel(t *testing.T) {
	for range 100 {
		if word := KennelWord(); !slices.Contains(Kennel, word) {
			t.Fatalf("KennelWord returned %q, which is not in the kennel", word)
		}
	}
}

package naming

import (
	"strings"
)

// PoolName is the canonical name for a pool of the given shape.
//
// It carries no suffix: a pool *is* its shape, and two pools with the same
// shape are the same pool. That is also what makes the name usable in a
// workflow's runs-on, which is the name's main job.
func PoolName(spec Spec) string { return spec.WithSuffix("").String() }

// HostName is the canonical name for a machine: its shape, plus enough of the
// machine's own name to tell two identical machines apart.
//
// The machine name goes last because it is the part an operator scans for --
// the eye stops at the end of the line -- and because it is the part most
// likely to be truncated on a host whose hostname is a cloud provider's idea
// of a name.
func HostName(spec Spec, machine string) string {
	return spec.WithSuffix(shortMachine(machine)).String()
}

// Labels are the labels a pool of this shape advertises.
//
// The canonical name comes first: it is the one a workflow author writes, and
// the only one that says how much machine they are asking for. The kernel and
// architecture labels follow because actions/runner advertises them anyway,
// and because a pool that declares them is a pool the scheduler will refuse to
// hand an x64 job to when it is arm64 -- which is the whole point of naming
// the architecture in the first place.
func Labels(spec Spec) []string {
	out := make([]string, 0, 3)
	if name := PoolName(spec); name != Prefix {
		out = append(out, name)
	}
	if k := Kernel(spec.OS); k != "" {
		out = append(out, k)
	}
	if a := ArchLabel(spec.Arch); a != "" {
		out = append(out, a)
	}
	return out
}

// shortMachine reduces a hostname to the part that identifies the machine.
//
// A fully qualified name repeats the same domain on every host in the fleet,
// which is precisely the information a name should not spend characters on.
func shortMachine(machine string) string {
	if host, _, ok := strings.Cut(strings.TrimSpace(machine), "."); ok {
		machine = host
	}
	return Slug(machine)
}

// Base is the branded form of a name that other names are built from: lowercase,
// hyphenated, and carrying the prefix exactly once.
//
// A pool called "gpu" and a pool called "zoomies-gpu" are the same pool as far
// as this grammar is concerned, and neither should produce "zoomies-zoomies-gpu".
func Base(name string) string {
	s := Slug(name)
	switch {
	case s == "":
		return Prefix
	case s == Prefix, strings.HasPrefix(s, Prefix+"-"):
		return s
	}
	return Prefix + "-" + s
}

// RunnerName is the name one runner registers under: what its pool is made of,
// then a discriminator that tells it from its siblings.
//
// GitHub shows this name in the runner list, in the job header, and in the "Set
// up job" step of every job's log -- the three places somebody looks when a job
// went somewhere surprising. "zoomies-4vcpu-ubuntu-2404-biscuit-a3f9qz2m" answers
// "how much machine, running what" there, without a page load; and because the
// shape is rendered by the same grammar as the pool's own name, Parse reads a
// runner's name back into the pool's Spec plus the discriminator.
//
// Two things must survive a name that will not fit. The prefix, because it is
// what marks a registration as this fleet's rather than one somebody made by
// hand -- store.IsRunnerName, and the reaper behind it, know a runner by no
// other sign. And the discriminator, because GitHub requires the name to be
// unique within the target and two runners that truncated to the same string
// would be one registration fighting itself. So the shape in the middle is what
// gives way, a whole segment at a time: a name cut mid-word ("...ubuntu-24")
// claims a platform that does not exist, where a name one segment shorter only
// says less than it could.
func RunnerName(pool, discriminator string) string {
	tail := Slug(discriminator)
	if room := MaxNameLength - len(Prefix) - 1; len(tail) > room {
		tail = strings.TrimRight(tail[:max(room, 0)], "-")
	}
	base := Base(pool)
	if tail == "" {
		return truncate(base)
	}
	parts := strings.Split(base, "-")
	for len(parts) > 1 && len(strings.Join(parts, "-"))+1+len(tail) > MaxNameLength {
		parts = parts[:len(parts)-1]
	}
	return truncate(strings.Join(parts, "-") + "-" + tail)
}

package naming

import (
	"strings"
	"testing"
)

func TestBaseCarriesTheBrandExactlyOnce(t *testing.T) {
	cases := map[string]string{
		"":                          Prefix,
		"gpu":                       "zoomies-gpu",
		"zoomies":                   "zoomies",
		"zoomies-gpu":               "zoomies-gpu",
		"Zoomies GPU":               "zoomies-gpu",
		"zoomies-4vcpu-ubuntu-2404": "zoomies-4vcpu-ubuntu-2404",
		// Not the prefix, however much it looks like it: a pool called
		// "zoomiesish" is somebody's own word, not a branded name.
		"zoomiesish": "zoomies-zoomiesish",
	}
	for in, want := range cases {
		if got := Base(in); got != want {
			t.Errorf("Base(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestRunnerNameKeepsTheShapeAndTheDiscriminator(t *testing.T) {
	spec := Spec{CPUs: 4, OS: OSUbuntu, Version: "24.04"}
	got := RunnerName(spec.String(), "biscuit-a3f9qz2m")
	if want := "zoomies-4vcpu-ubuntu-2404-biscuit-a3f9qz2m"; got != want {
		t.Errorf("RunnerName = %q, want %q", got, want)
	}
	// A pool named by hand still gets the brand, and gets it once.
	if got := RunnerName("gpu", "biscuit-a3f9qz2m"); got != "zoomies-gpu-biscuit-a3f9qz2m" {
		t.Errorf("RunnerName from an invented pool name = %q", got)
	}
}

// What happens when a name will not fit is the whole design: the brand is what
// marks the registration as ours to reap, and the discriminator is what makes
// it unique in the target. Only the shape in the middle may be spent.
func TestRunnerNameSpendsTheShapeRatherThanTheBrandOrTheToken(t *testing.T) {
	long := strings.Repeat("verylongpoolname-", 5)
	got := RunnerName(long, "jellybean-a3f9qz2m")
	switch {
	case len(got) > MaxNameLength:
		t.Errorf("RunnerName = %q, %d characters, more than GitHub accepts", got, len(got))
	case !strings.HasPrefix(got, Prefix+"-"):
		t.Errorf("RunnerName = %q, which the reaper would not recognise as ours", got)
	case !strings.HasSuffix(got, "-jellybean-a3f9qz2m"):
		t.Errorf("RunnerName = %q, which has lost the discriminator that makes it unique", got)
	}
	// Segments go whole. A name cut mid-word claims a platform that does not
	// exist -- "ubuntu-24" is not a release anyone ships.
	spec := Spec{CPUs: 4, OS: OSUbuntu, Version: "24.04"}
	got = RunnerName(spec.String(), strings.Repeat("d", 30))
	for _, part := range strings.Split(got, "-") {
		if part == "ubuntu" || part == "2404" || part == "4vcpu" || len(part) == 30 || part == Prefix {
			continue
		}
		t.Errorf("RunnerName = %q, which contains %q -- a segment cut in half", got, part)
	}
}

func TestRunnerNameWithoutADiscriminator(t *testing.T) {
	// Nothing in Zoomies mints one of these, but a caller that passes an empty
	// discriminator should get a usable name rather than a trailing hyphen.
	if got := RunnerName("zoomies-gpu", ""); got != "zoomies-gpu" {
		t.Errorf("RunnerName with no discriminator = %q", got)
	}
}

// Package naming owns the grammar Zoomies uses for the names an operator reads
// and writes: a pool's, a host's, and the runners' derived from them.
//
// The problem it solves is that "linux-x64" tells you almost nothing. When a
// job is slow, when a bill is too big, or when a job landed somewhere it had no
// business landing, the questions are always the same: how much machine was
// that, which operating system, which architecture. A name that answers them
// turns three page loads into a glance -- and a pool's name is copied into
// every workflow file that uses it, so it is read far more often than it is
// written.
//
// The grammar is:
//
//	zoomies-<cpu>vcpu[-<memory>gb]-<os>-<version>[-<arch>][-<suffix>]
//
// so a pool is "zoomies-4vcpu-ubuntu-2404", a host running it is
// "zoomies-16vcpu-ubuntu-2404-tuck", and a runner of that pool is
// "zoomies-4vcpu-ubuntu-2404-biscuit-a3f9qz2m". Every part after the prefix is
// optional and omitted when it is not known, because a half-described host is
// still better named than one called "ip-10-0-4-17".
//
// The suffix slot is what makes two things of the same shape tellable apart: a
// machine name for a host, and for a runner a word from the kennel and a random
// token. RunnerName explains why a runner needs both, and why the shape rather
// than the prefix or the token is what gives way when a name will not fit.
//
// Two conventions keep names short enough to read:
//
//   - The version loses its dots: Ubuntu 24.04 is "2404", Debian 12 is "12".
//     Parse puts them back, so the round trip is lossless for the versions
//     these operating systems actually ship.
//   - amd64 is left off, because it is the overwhelming default and a name
//     that says it for every runner stops carrying information. arm64 is
//     always spelled out.
package naming

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Prefix brands every name this package builds. It is not configurable: the
// point of the prefix is that an operator looking at a list of runners in
// GitHub's UI, or containers on a host, can tell at a glance which ones are
// Zoomies' to reap.
const Prefix = "zoomies"

// MaxNameLength is the longest name this package will emit. GitHub rejects a
// runner name over 64 characters, and a pool's name is what a runner's labels
// are built from, so the limit is enforced here rather than discovered when a
// registration is refused.
const MaxNameLength = 64

// Spec is a name in structured form: what the thing is made of, in the order
// the grammar renders it.
//
// Every field is optional. A zero Spec renders as the bare prefix, which is
// what a host that has told us nothing about itself deserves to be called.
type Spec struct {
	// CPUs is the vCPU allocation: a pool's per-runner share, or a host's
	// total. Fractions round up, because half a core still needs a whole one
	// to run on and "0vcpu" would be a lie.
	CPUs float64
	// MemoryGB is the memory allocation. It is omitted from the name when
	// zero, which is the common case: most fleets size on CPU alone, and a
	// name that carries every dimension stops being readable.
	MemoryGB int
	// OS is a normalised operating system: ubuntu, debian, alpine, fedora,
	// rocky, macos or windows. Use NormalizeOS to get one.
	OS string
	// Version is the OS version as the operator writes it -- "24.04", "12",
	// "3.22". The compact form used in names is derived, not stored.
	Version string
	// Arch is a normalised architecture: amd64 or arm64. Use NormalizeArch.
	Arch string
	// Suffix distinguishes two things with the same shape: a machine name for
	// a host, a random token for a runner. Pools have none, because a pool is
	// its shape.
	Suffix string
}

// String renders the Spec in the canonical grammar.
func (s Spec) String() string {
	parts := make([]string, 0, 7)
	parts = append(parts, Prefix)
	if cpus := s.vCPU(); cpus > 0 {
		parts = append(parts, strconv.Itoa(cpus)+"vcpu")
	}
	if s.MemoryGB > 0 {
		parts = append(parts, strconv.Itoa(s.MemoryGB)+"gb")
	}
	// An operating system the grammar does not know is left out entirely
	// rather than passed through: a name has to parse back into the Spec that
	// built it, and an unrecognised word would come back as a suffix.
	if os := NormalizeOS(s.OS); os != "" {
		parts = append(parts, os)
		if v := CompactVersion(s.Version); v != "" {
			parts = append(parts, v)
		}
	}
	// amd64 is the default and says nothing; every other architecture is
	// named, so a name without one is a promise that it is the usual thing.
	if arch := NormalizeArch(s.Arch); arch != "" && arch != ArchAMD64 {
		parts = append(parts, arch)
	}
	if suffix := Slug(s.Suffix); suffix != "" {
		parts = append(parts, suffix)
	}
	return truncate(strings.Join(parts, "-"))
}

// vCPU is the whole number of vCPUs the name reports. A fractional allocation
// rounds up: 1.5 vCPU is advertised as 2, because the runner can burst onto a
// second core and a workflow author reading the label is sizing a job, not
// auditing a cgroup.
func (s Spec) vCPU() int {
	if s.CPUs <= 0 {
		return 0
	}
	return int(math.Ceil(s.CPUs))
}

// Describe renders the Spec as the sentence the UI and the CLI print beside a
// name, e.g. "4 vCPU, Ubuntu 24.04, arm64". It is empty when the Spec says
// nothing worth a sentence.
func (s Spec) Describe() string {
	var parts []string
	if n := s.vCPU(); n > 0 {
		parts = append(parts, strconv.Itoa(n)+" vCPU")
	}
	if s.MemoryGB > 0 {
		parts = append(parts, strconv.Itoa(s.MemoryGB)+" GB")
	}
	if p := s.Platform(); p != "" {
		parts = append(parts, p)
	}
	return strings.Join(parts, ", ")
}

// Platform renders just the operating system and architecture, e.g.
// "Ubuntu 24.04, arm64". It is what the Pools and Hosts pages show in the
// column beside the name.
func (s Spec) Platform() string {
	var parts []string
	if os := PrettyOS(s.OS); os != "" {
		if v := strings.TrimSpace(s.Version); v != "" {
			os += " " + v
		}
		parts = append(parts, os)
	}
	if a := NormalizeArch(s.Arch); a != "" {
		parts = append(parts, a)
	}
	return strings.Join(parts, ", ")
}

// Empty reports whether the Spec carries nothing but the prefix.
func (s Spec) Empty() bool { return s.String() == Prefix }

// WithSuffix returns a copy carrying a different discriminator, which is how a
// pool's shape becomes a runner's name.
func (s Spec) WithSuffix(suffix string) Spec {
	s.Suffix = suffix
	return s
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

// Parse reads a name built by this package back into a Spec.
//
// It reports false for anything that is not in the grammar -- including names
// an operator invented, which stay legal everywhere Zoomies accepts a name.
// Parsing is best-effort by design: a caller uses it to enrich a display, so a
// name that only half fits still yields the parts that do.
func Parse(name string) (Spec, bool) {
	fields := strings.Split(strings.ToLower(strings.TrimSpace(name)), "-")
	if len(fields) == 0 || fields[0] != Prefix {
		return Spec{}, false
	}
	fields = fields[1:]

	var s Spec
	i := 0
	if i < len(fields) {
		if n, ok := suffixedNumber(fields[i], "vcpu"); ok {
			s.CPUs, i = float64(n), i+1
		}
	}
	if i < len(fields) {
		if n, ok := suffixedNumber(fields[i], "gb"); ok {
			s.MemoryGB, i = n, i+1
		}
	}
	if i < len(fields) && knownOS[fields[i]] {
		s.OS, i = fields[i], i+1
		if i < len(fields) && isVersion(fields[i]) {
			s.Version, i = ExpandVersion(s.OS, fields[i]), i+1
		}
	}
	// An unnamed architecture is amd64: that is the whole reason it is left
	// out, so parsing has to put it back or a round trip would lose it.
	s.Arch = ArchAMD64
	if i < len(fields) && knownArch[fields[i]] {
		s.Arch, i = NormalizeArch(fields[i]), i+1
	}
	if i < len(fields) {
		s.Suffix = strings.Join(fields[i:], "-")
	}
	return s, true
}

// suffixedNumber parses "4vcpu" or "16gb" into its number.
func suffixedNumber(field, unit string) (int, bool) {
	digits, ok := strings.CutSuffix(field, unit)
	if !ok || digits == "" {
		return 0, false
	}
	n, err := strconv.Atoi(digits)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

func isVersion(field string) bool {
	if field == "" {
		return false
	}
	for _, r := range field {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------
// Normalisation
// ---------------------------------------------------------------------------

// The architectures Zoomies runs on. They are Go's names, because that is what
// an agent reports about itself and what a container image manifest lists, and
// inventing a third vocabulary would only need translating twice.
const (
	ArchAMD64 = "amd64"
	ArchARM64 = "arm64"
)

// The operating systems the naming grammar knows. An OS outside this list is
// not rejected anywhere -- it simply does not get a canonical name, which is
// the honest outcome for a platform Zoomies has not been taught about.
const (
	OSUbuntu  = "ubuntu"
	OSDebian  = "debian"
	OSAlpine  = "alpine"
	OSFedora  = "fedora"
	OSRocky   = "rocky"
	OSMacOS   = "macos"
	OSWindows = "windows"
)

var knownOS = map[string]bool{
	OSUbuntu: true, OSDebian: true, OSAlpine: true,
	OSFedora: true, OSRocky: true, OSMacOS: true, OSWindows: true,
}

var knownArch = map[string]bool{
	ArchAMD64: true, ArchARM64: true, "x64": true, "x86_64": true,
	"aarch64": true, "arm": true,
}

// osAliases maps what a host actually calls itself -- Go's GOOS, the ID= field
// of /etc/os-release, the names operators type -- onto the grammar's OS.
var osAliases = map[string]string{
	"darwin": OSMacOS, "macos": OSMacOS, "mac": OSMacOS, "osx": OSMacOS,
	"ubuntu": OSUbuntu, "debian": OSDebian, "raspbian": OSDebian,
	"alpine": OSAlpine, "fedora": OSFedora,
	"rocky": OSRocky, "rockylinux": OSRocky, "almalinux": OSRocky,
	"rhel": OSRocky, "centos": OSRocky,
	"windows": OSWindows,
}

// prettyOS is how each OS is spelled in prose, where "ubuntu" looks careless.
var prettyOS = map[string]string{
	OSUbuntu: "Ubuntu", OSDebian: "Debian", OSAlpine: "Alpine",
	OSFedora: "Fedora", OSRocky: "Rocky Linux",
	OSMacOS: "macOS", OSWindows: "Windows",
}

// NormalizeOS maps an operating system identifier onto the grammar's spelling,
// returning "" for one the grammar does not know.
//
// It deliberately does not turn "linux" into a distribution: a host that only
// says "linux" has not said which one, and guessing Ubuntu would produce a
// name that claims a fact nobody established.
func NormalizeOS(s string) string {
	v := strings.ToLower(strings.TrimSpace(s))
	if alias, ok := osAliases[v]; ok {
		return alias
	}
	if knownOS[v] {
		return v
	}
	return ""
}

// PrettyOS renders an operating system for prose. It returns "" for one the
// grammar does not know, so a caller can fall back to whatever it was told.
func PrettyOS(s string) string { return prettyOS[NormalizeOS(s)] }

// NormalizeArch maps an architecture onto amd64 or arm64, returning "" for
// anything else. The label spellings GitHub uses (x64, arm) are accepted
// because they are what a workflow's runs-on contains.
func NormalizeArch(s string) string {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case ArchAMD64, "x64", "x86_64", "amd":
		return ArchAMD64
	case ArchARM64, "aarch64", "arm":
		return ArchARM64
	}
	return ""
}

// Kernel maps an OS onto the kernel family GitHub's runner labels use, which
// is the "linux" in runs-on: [self-hosted, linux, x64].
func Kernel(os string) string {
	switch NormalizeOS(os) {
	case OSMacOS:
		return "macos"
	case OSWindows:
		return "windows"
	case "":
		return ""
	}
	return "linux"
}

// ArchLabel maps an architecture onto the label actions/runner advertises for
// it, which is "x64" rather than "amd64".
func ArchLabel(arch string) string {
	switch NormalizeArch(arch) {
	case ArchAMD64:
		return "x64"
	case ArchARM64:
		return "arm64"
	}
	return ""
}

// CompactVersion strips the punctuation out of a version so it survives as one
// field of a dash-separated name: "24.04" becomes "2404", "3.22" becomes
// "322", "12" stays "12".
//
// Only the first two components are kept. A point release is a patch level,
// and a pool named for one would have to be renamed every few weeks.
func CompactVersion(v string) string {
	v = strings.TrimSpace(v)
	if v == "" {
		return ""
	}
	parts := strings.FieldsFunc(v, func(r rune) bool { return r == '.' || r == '_' })
	var b strings.Builder
	for i, p := range parts {
		if i == 2 {
			break
		}
		for _, r := range p {
			if r >= '0' && r <= '9' {
				b.WriteRune(r)
			}
		}
	}
	return b.String()
}

// ExpandVersion is CompactVersion's inverse, which needs to know the operating
// system because only its own conventions say where the dot went.
//
// Ubuntu is YY.MM, always four digits. Everything else numbers its releases
// with a single major component, so the compact form is already the version.
func ExpandVersion(os, compact string) string {
	compact = strings.TrimSpace(compact)
	if compact == "" {
		return ""
	}
	if NormalizeOS(os) == OSUbuntu && len(compact) == 4 {
		return compact[:2] + "." + compact[2:]
	}
	return compact
}

// Slug reduces arbitrary text to the character set the grammar allows:
// lowercase letters, digits and single dashes.
//
// Everything Zoomies names ends up as a container name, a hostname and a
// GitHub runner name at once, and the intersection of what those three accept
// is narrower than any of them alone.
func Slug(s string) string {
	var b strings.Builder
	lastDash := true // leading dashes are dropped
	for _, r := range strings.ToLower(strings.TrimSpace(s)) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			b.WriteRune(r)
			lastDash = false
		default:
			if !lastDash {
				b.WriteByte('-')
				lastDash = true
			}
		}
	}
	return strings.TrimRight(b.String(), "-")
}

// truncate keeps a name inside MaxNameLength without leaving it ending in a
// dash, which several of the systems these names are handed to reject.
func truncate(s string) string {
	if len(s) <= MaxNameLength {
		return s
	}
	return strings.TrimRight(s[:MaxNameLength], "-")
}

// Validate reports what is wrong with a name a human typed, in a sentence the
// API can hand straight back. A name outside the grammar is fine; a name that
// no container runtime or GitHub registration would accept is not.
func Validate(name string) error {
	n := strings.TrimSpace(name)
	switch {
	case n == "":
		return fmt.Errorf("a name is required")
	case len(n) > MaxNameLength:
		return fmt.Errorf("%q is %d characters; GitHub rejects a runner name over %d, so keep the name it is built from shorter",
			n, len(n), MaxNameLength)
	case Slug(n) != strings.ToLower(n):
		return fmt.Errorf("%q may only contain lowercase letters, digits and single dashes, because the name becomes a container name, a hostname and a GitHub runner name at once",
			n)
	}
	return nil
}

package naming

import (
	"strings"
	"testing"
)

func TestSpecString(t *testing.T) {
	cases := []struct {
		name string
		spec Spec
		want string
	}{
		{"nothing known", Spec{}, "zoomies"},
		{"the shape of a pool", Spec{CPUs: 4, OS: "ubuntu", Version: "24.04", Arch: "amd64"}, "zoomies-4vcpu-ubuntu-2404"},
		{"arm64 is spelled out", Spec{CPUs: 8, OS: "ubuntu", Version: "24.04", Arch: "arm64"}, "zoomies-8vcpu-ubuntu-2404-arm64"},
		{"memory when it is set", Spec{CPUs: 2, MemoryGB: 8, OS: "debian", Version: "12"}, "zoomies-2vcpu-8gb-debian-12"},
		{"a fraction of a core rounds up", Spec{CPUs: 1.5, OS: "ubuntu", Version: "22.04"}, "zoomies-2vcpu-ubuntu-2204"},
		{"a host carries its machine name", Spec{CPUs: 16, OS: "ubuntu", Version: "24.04", Suffix: "tuck"}, "zoomies-16vcpu-ubuntu-2404-tuck"},
		{"an unknown OS is left out", Spec{CPUs: 4, OS: "plan9", Version: "4"}, "zoomies-4vcpu"},
		{"a version without an OS says nothing", Spec{Version: "24.04"}, "zoomies"},
		{"cpus alone", Spec{CPUs: 4}, "zoomies-4vcpu"},
		{"macos", Spec{CPUs: 8, OS: "darwin", Version: "15", Arch: "arm64"}, "zoomies-8vcpu-macos-15-arm64"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := c.spec.String(); got != c.want {
				t.Errorf("String() = %q, want %q", got, c.want)
			}
		})
	}
}

func TestSpecStringStaysWithinGitHubsLimit(t *testing.T) {
	s := Spec{CPUs: 64, MemoryGB: 512, OS: "ubuntu", Version: "24.04", Arch: "arm64",
		Suffix: strings.Repeat("long", 40)}
	got := s.String()
	if len(got) > MaxNameLength {
		t.Fatalf("String() is %d characters, over the %d GitHub allows: %q", len(got), MaxNameLength, got)
	}
	if strings.HasSuffix(got, "-") {
		t.Errorf("String() = %q, which ends in a dash a container runtime would reject", got)
	}
}

func TestParseRoundTrip(t *testing.T) {
	specs := []Spec{
		{CPUs: 4, OS: OSUbuntu, Version: "24.04", Arch: ArchAMD64},
		{CPUs: 8, OS: OSUbuntu, Version: "22.04", Arch: ArchARM64},
		{CPUs: 2, MemoryGB: 8, OS: OSDebian, Version: "12", Arch: ArchAMD64},
		{CPUs: 16, OS: OSFedora, Version: "42", Arch: ArchAMD64, Suffix: "build01"},
		{CPUs: 1, OS: OSRocky, Version: "9", Arch: ArchARM64, Suffix: "k3f9qz"},
	}
	for _, want := range specs {
		name := want.String()
		got, ok := Parse(name)
		if !ok {
			t.Fatalf("Parse(%q) did not recognise a name this package built", name)
		}
		if got != want {
			t.Errorf("Parse(%q) = %+v, want %+v", name, got, want)
		}
	}
}

func TestParseRejectsForeignNames(t *testing.T) {
	for _, name := range []string{"", "linux-x64", "blacksmith-4vcpu-ubuntu-2404", "zoomiesx-4vcpu"} {
		if _, ok := Parse(name); ok {
			t.Errorf("Parse(%q) claimed a name that is not in the grammar", name)
		}
	}
}

func TestParseIsBestEffort(t *testing.T) {
	// A name that only half fits still yields the parts that do, because the
	// caller is enriching a display rather than validating input.
	got, ok := Parse("zoomies-gpu-builders")
	if !ok {
		t.Fatalf("Parse rejected a branded name with a free-form body")
	}
	if got.CPUs != 0 || got.OS != "" {
		t.Errorf("Parse invented facets: %+v", got)
	}
	if got.Suffix != "gpu-builders" {
		t.Errorf("Suffix = %q, want the whole body", got.Suffix)
	}
}

func TestNormalizeOS(t *testing.T) {
	cases := map[string]string{
		"Ubuntu": OSUbuntu, "darwin": OSMacOS, "macOS": OSMacOS,
		"centos": OSRocky, "raspbian": OSDebian, "windows": OSWindows,
		// "linux" names a kernel, not a distribution: guessing one would put a
		// fact into a name that nobody established.
		"linux": "", "plan9": "", "": "",
	}
	for in, want := range cases {
		if got := NormalizeOS(in); got != want {
			t.Errorf("NormalizeOS(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestNormalizeArch(t *testing.T) {
	cases := map[string]string{
		"amd64": ArchAMD64, "x64": ArchAMD64, "x86_64": ArchAMD64,
		"arm64": ArchARM64, "aarch64": ArchARM64, "arm": ArchARM64,
		"riscv64": "", "": "",
	}
	for in, want := range cases {
		if got := NormalizeArch(in); got != want {
			t.Errorf("NormalizeArch(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestVersionCompaction(t *testing.T) {
	cases := []struct{ in, compact, os, back string }{
		{"24.04", "2404", OSUbuntu, "24.04"},
		{"22.04", "2204", OSUbuntu, "22.04"},
		{"12", "12", OSDebian, "12"},
		{"9.4", "94", OSRocky, "94"},
		{"3.22.1", "322", OSAlpine, "322"},
		{"", "", OSUbuntu, ""},
	}
	for _, c := range cases {
		if got := CompactVersion(c.in); got != c.compact {
			t.Errorf("CompactVersion(%q) = %q, want %q", c.in, got, c.compact)
		}
		if got := ExpandVersion(c.os, c.compact); got != c.back {
			t.Errorf("ExpandVersion(%q, %q) = %q, want %q", c.os, c.compact, got, c.back)
		}
	}
}

func TestSlug(t *testing.T) {
	cases := map[string]string{
		"Build Box 01":  "build-box-01",
		"  spaced  ":    "spaced",
		"a//b__c":       "a-b-c",
		"---":           "",
		"ip-10-0-4-17":  "ip-10-0-4-17",
		"CAPS_and.dots": "caps-and-dots",
	}
	for in, want := range cases {
		if got := Slug(in); got != want {
			t.Errorf("Slug(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestPoolAndHostNames(t *testing.T) {
	spec := Spec{CPUs: 16, OS: OSUbuntu, Version: "24.04", Arch: ArchAMD64}
	if got, want := PoolName(spec), "zoomies-16vcpu-ubuntu-2404"; got != want {
		t.Errorf("PoolName = %q, want %q", got, want)
	}
	// A pool's name is its shape, so a stray suffix must not survive into one.
	if got := PoolName(spec.WithSuffix("build01")); got != "zoomies-16vcpu-ubuntu-2404" {
		t.Errorf("PoolName kept a suffix: %q", got)
	}
	if got, want := HostName(spec, "build01.fleet.example.com"), "zoomies-16vcpu-ubuntu-2404-build01"; got != want {
		t.Errorf("HostName = %q, want %q", got, want)
	}
}

func TestLabels(t *testing.T) {
	got := Labels(Spec{CPUs: 8, OS: OSUbuntu, Version: "24.04", Arch: ArchARM64})
	want := []string{"zoomies-8vcpu-ubuntu-2404-arm64", "linux", "arm64"}
	if len(got) != len(want) {
		t.Fatalf("Labels = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("Labels = %v, want %v", got, want)
		}
	}
	if got := Labels(Spec{}); len(got) != 0 {
		t.Errorf("Labels of an empty spec = %v, want none", got)
	}
}

func TestDescribe(t *testing.T) {
	s := Spec{CPUs: 4, MemoryGB: 16, OS: OSUbuntu, Version: "24.04", Arch: ArchARM64}
	if got, want := s.Describe(), "4 vCPU, 16 GB, Ubuntu 24.04, arm64"; got != want {
		t.Errorf("Describe = %q, want %q", got, want)
	}
	if got := (Spec{}).Describe(); got != "" {
		t.Errorf("Describe of an empty spec = %q, want empty", got)
	}
}

func TestValidate(t *testing.T) {
	if err := Validate("zoomies-4vcpu-ubuntu-2404"); err != nil {
		t.Errorf("Validate rejected a canonical name: %v", err)
	}
	if err := Validate("my-own-pool"); err != nil {
		t.Errorf("Validate rejected a name outside the grammar, which stays legal: %v", err)
	}
	for _, bad := range []string{"", "Has Spaces", strings.Repeat("a", MaxNameLength+1)} {
		if err := Validate(bad); err == nil {
			t.Errorf("Validate(%q) accepted a name no runtime would take", bad)
		}
	}
}

package provider

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// RunContractTests exercises every rule the contract states against any
// implementation.
//
// It is exported from the production package, rather than being a test helper
// somewhere, so that a provider's own test file is one line and the suite is
// the definition of done -- including for a provider written outside this
// package, which cannot import another package's tests.
//
// open is called once per case and returns a provider pointed at whatever that
// provider needs: the fake needs nothing, and a real one is expected to skip
// itself when its infrastructure is not there. Every case cleans up the
// machines it made, because the second thing a suite like this must not do is
// leave a resource behind on somebody's cluster; the first is create one it
// cannot find again.
func RunContractTests(t *testing.T, name string, open func(*testing.T) Provider) {
	t.Helper()
	t.Run(name, func(t *testing.T) {
		t.Run("what it says it can do is what its type can do", func(t *testing.T) {
			p := open(t)
			if err := CheckCapabilities(p); err != nil {
				t.Errorf("%v", err)
			}
			if p.Kind() != p.Capabilities().Kind {
				t.Errorf("Kind() = %q but Capabilities().Kind = %q; they name the same provider",
					p.Kind(), p.Capabilities().Kind)
			}
			if !p.Kind().Valid() {
				t.Errorf("Kind() = %q, which is not a kind the store can hold: no row could ever select this provider", p.Kind())
			}
		})

		t.Run("its contract range contains the version this build speaks", func(t *testing.T) {
			p := open(t)
			if err := checkContract(p.Kind(), p.Capabilities()); err != nil {
				t.Errorf("%v", err)
			}
		})

		// A deadline that is zero is a call with no supervision, and one that
		// gives a whole create less time than a single request is a create that
		// is cancelled halfway by arithmetic rather than by a decision.
		t.Run("its deadlines are positive and grow with the work they cover", func(t *testing.T) {
			p := open(t)
			d := p.Capabilities().Deadlines
			for _, c := range []struct {
				name string
				d    time.Duration
			}{
				{"Call", d.Call}, {"Allocate", d.Allocate}, {"Create", d.Create}, {"Delete", d.Delete},
			} {
				if c.d <= 0 {
					t.Errorf("Deadlines.%s = %s; a call with no deadline can wedge the fleet", c.name, c.d)
				}
			}
			if d.Call > d.Allocate {
				t.Errorf("Deadlines.Call = %s is longer than Allocate = %s", d.Call, d.Allocate)
			}
			if d.Allocate > d.Create {
				t.Errorf("Deadlines.Allocate = %s is longer than Create = %s", d.Allocate, d.Create)
			}
			if _, ok := p.(Bootstrapper); ok && d.Bootstrap <= 0 {
				t.Errorf("Deadlines.Bootstrap = %s on a provider that bootstraps", d.Bootstrap)
			}
		})

		// Preflight is the call an operator runs against a provider that is not
		// working. Returning an error instead of findings would leave the page
		// with a status code where the remedy should be.
		t.Run("preflight reports what to fix rather than failing", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Call)
			defer cancel()
			r := p.Preflight(ctx)
			for i, f := range r.Findings {
				switch {
				case f.Code == "":
					t.Errorf("finding %d has no code; nothing can document or suppress it", i)
				case f.Title == "":
					t.Errorf("finding %s has no title", f.Code)
				case f.Severity != config.SeverityError && f.Severity != config.SeverityWarning && f.Severity != config.SeverityInfo:
					t.Errorf("finding %s has severity %q, which is not one of the three", f.Code, f.Severity)
				}
			}
		})

		// The rule the whole design rests on: identity before existence. A
		// provider that creates during Allocate leaves the controller with a
		// resource it has not written down.
		t.Run("allocate picks an identity and creates nothing", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Allocate)
			defer cancel()
			owner, spec := newSpec()
			ref, err := p.Allocate(ctx, spec)
			if err != nil {
				t.Fatalf("Allocate: %v", err)
			}
			if ref.Zero() {
				t.Fatal("Allocate returned a ref naming nothing; there is no identity to persist")
			}
			if ref.Name != spec.Name {
				t.Errorf("Allocate returned name %q for a machine the caller named %q", ref.Name, spec.Name)
			}
			if _, err := p.Inspect(ctx, ref); !errors.Is(err, ErrNotFound) {
				t.Errorf("Inspect after Allocate = %v, want not found: an allocate that created something is an unrecorded machine", err)
			}
			ms, err := p.List(ctx, owner)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if n := countNamed(ms, spec.Name); n != 0 {
				t.Errorf("List found %d machines named %q after an allocate alone", n, spec.Name)
			}
		})

		// A create that is re-issued after an outcome nobody heard must not
		// buy a second machine. This is the property that makes "a timeout is
		// not evidence that creation failed" safe to act on.
		t.Run("creating twice for one identity builds one machine", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Create)
			defer cancel()
			owner, spec := newSpec()
			ref := mustCreate(t, ctx, p, spec)
			if _, err := p.Create(ctx, ref, spec); err != nil {
				t.Fatalf("second Create for the same ref: %v", err)
			}
			ms, err := p.List(ctx, owner)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if n := countNamed(ms, spec.Name); n != 1 {
				t.Errorf("List found %d machines named %q after two creates for one ref; a second machine is a second bill nobody is tracking", n, spec.Name)
			}
		})

		t.Run("a machine it created is in the list for its owner", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Create)
			defer cancel()
			owner, spec := newSpec()
			mustCreate(t, ctx, p, spec)
			ms, err := p.List(ctx, owner)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if countNamed(ms, spec.Name) != 1 {
				t.Errorf("a machine this owner created is not in its own sweep; nothing would ever find it again")
			}
			for _, m := range ms {
				if m.Ref.Name != spec.Name {
					continue
				}
				if !m.Phase.Known() {
					t.Errorf("phase %q is not one the contract defines; an unrecognised phase is read as unknown, which authorises nothing", m.Phase)
				}
				if p.Capabilities().CanMarkOwnership && !m.Owner.Matches(owner) {
					t.Errorf("the marks read back from the resource are not the ones we wrote: %+v", m.Owner)
				}
			}
		})

		// "Already deleted" is the desired end state, not a failure, and the
		// two answers below are what a delete that crossed with somebody's
		// console gets.
		t.Run("deleting a machine that is already gone is success", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Delete)
			defer cancel()
			_, spec := newSpec()
			ref := mustCreate(t, ctx, p, spec)
			deleteMachine(t, ctx, p, ref)

			op, err := p.Delete(ctx, ref)
			if err != nil {
				t.Errorf("Delete of a machine that is gone = %v, want no error", err)
			}
			if !op.Zero() {
				t.Errorf("Delete of a machine that is gone returned handle %q; there is nothing to follow", op.Handle)
			}
			if _, err := p.Inspect(ctx, ref); !errors.Is(err, ErrNotFound) {
				t.Errorf("Inspect of a deleted machine = %v, want not found: a delete is not complete until an inspect cannot find it", err)
			}
		})

		// After a restart the controller asks about handles the provider may
		// have forgotten, and it must get an answer rather than a panic.
		t.Run("an operation handle it never issued is not found", func(t *testing.T) {
			p := open(t)
			ctx, cancel := contextFor(t, p.Capabilities().Deadlines.Call)
			defer cancel()
			_, err := p.Operation(ctx, OperationRef{Kind: OpCreate, Handle: "handle-that-was-never-issued"})
			if !errors.Is(err, ErrNotFound) {
				t.Errorf("Operation on an unknown handle = %v, want not found", err)
			}
		})

		// A provider that ignores its context is a provider that holds the
		// reconcile pass open for as long as its own timeouts allow.
		t.Run("every call honours a context that is already cancelled", func(t *testing.T) {
			p := open(t)
			ctx, cancel := context.WithCancel(context.Background())
			cancel()
			_, spec := newSpec()
			ref := MachineRef{Zone: "zone", ID: "1", Name: spec.Name}
			calls := map[string]func() error{
				"Allocate":  func() error { _, err := p.Allocate(ctx, spec); return err },
				"Create":    func() error { _, err := p.Create(ctx, ref, spec); return err },
				"Inspect":   func() error { _, err := p.Inspect(ctx, ref); return err },
				"List":      func() error { _, err := p.List(ctx, spec.Owner); return err },
				"Delete":    func() error { _, err := p.Delete(ctx, ref); return err },
				"Operation": func() error { _, err := p.Operation(ctx, OperationRef{Kind: OpCreate, Handle: "h"}); return err },
			}
			if pc, ok := p.(PowerController); ok {
				calls["Start"] = func() error { _, err := pc.Start(ctx, ref); return err }
				calls["Stop"] = func() error { _, err := pc.Stop(ctx, ref, true); return err }
			}
			if b, ok := p.(Bootstrapper); ok {
				calls["Bootstrap"] = func() error { _, err := b.Bootstrap(ctx, ref, Bootstrap{}); return err }
			}
			if d, ok := p.(Discoverer); ok {
				calls["Discover"] = func() error { _, err := d.Discover(ctx); return err }
			}
			for name, call := range calls {
				if err := call(); err == nil {
					t.Errorf("%s returned no error for a cancelled context", name)
				}
			}
		})

		// The forward-compatibility rule, checked here because it is the one a
		// provider can break by inventing a phase of its own.
		t.Run("a phase this build does not know is unknown, and unknown is not gone", func(t *testing.T) {
			if got := ParsePhase("a-phase-from-a-later-contract"); got != PhaseUnknown {
				t.Errorf("ParsePhase of an unrecognised phase = %q, want %q", got, PhaseUnknown)
			}
			if PhaseUnknown.Gone() {
				t.Error("an unknown phase reads as gone; a machine we failed to read would be recorded as deleted")
			}
			if PhaseUnknown.AuthorisesDelete() {
				t.Error("an unknown phase authorises a delete; we would destroy a machine we could not identify")
			}
		})
	})
}

// contextFor bounds a case by the provider's own budget for the call, so that a
// suite run against real infrastructure fails with a deadline rather than
// hanging a CI job.
func contextFor(t *testing.T, d time.Duration) (context.Context, context.CancelFunc) {
	t.Helper()
	if d <= 0 {
		d = time.Minute
	}
	return context.WithTimeout(context.Background(), d)
}

// newSpec mints one machine's identity the way the controller does, so that the
// suite exercises the real name grammar a sweep filters on.
func newSpec() (Owner, MachineSpec) {
	id := store.NewID(store.PrefixMachine)
	owner := Owner{
		ControllerID: store.NewID(store.PrefixController),
		ProviderID:   store.NewID(store.PrefixProvider),
		MachineID:    id,
		Fingerprint:  store.NewSecret(12),
		CreatedAt:    time.Now().UTC(),
	}
	return owner, MachineSpec{
		Name:  store.NewMachineName(id),
		Owner: owner,
		Shape: Shape{CPUs: 2, MemoryMB: 2048, DiskMB: 20480, Platform: store.Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "amd64"}},
	}
}

// mustCreate allocates, creates and waits, and registers the cleanup before the
// machine exists -- the same ordering the controller uses, and for the same
// reason: a resource created before anything was written down is a resource
// nothing will clean up.
func mustCreate(t *testing.T, ctx context.Context, p Provider, spec MachineSpec) MachineRef {
	t.Helper()
	ref, err := p.Allocate(ctx, spec)
	if err != nil {
		t.Fatalf("Allocate: %v", err)
	}
	t.Cleanup(func() {
		cleanup, cancel := contextFor(t, p.Capabilities().Deadlines.Delete)
		defer cancel()
		if op, err := p.Delete(cleanup, ref); err == nil {
			awaitOp(t, cleanup, p, op)
		}
	})
	op, err := p.Create(ctx, ref, spec)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	awaitOp(t, ctx, p, op)
	return ref
}

func deleteMachine(t *testing.T, ctx context.Context, p Provider, ref MachineRef) {
	t.Helper()
	op, err := p.Delete(ctx, ref)
	if err != nil {
		t.Fatalf("Delete: %v", err)
	}
	awaitOp(t, ctx, p, op)
}

// awaitOp follows an operation to its end. A zero handle is a synchronous
// provider's answer and there is nothing to follow.
func awaitOp(t *testing.T, ctx context.Context, p Provider, op OperationRef) {
	t.Helper()
	if op.Zero() {
		return
	}
	for {
		st, err := p.Operation(ctx, op)
		if err != nil {
			t.Fatalf("Operation(%s): %v", op.Handle, err)
		}
		if st.Done {
			if !st.OK {
				t.Fatalf("operation %s finished badly: %s", op.Handle, st.Detail)
			}
			return
		}
		select {
		case <-ctx.Done():
			t.Fatalf("operation %s did not finish within the provider's own deadline: %s", op.Handle, st.Detail)
		case <-time.After(10 * time.Millisecond):
		}
	}
}

func countNamed(ms []Machine, name string) int {
	n := 0
	for _, m := range ms {
		if m.Ref.Name == name && !m.Phase.Gone() {
			n++
		}
	}
	return n
}

package provider

import "testing"

// The suite is the definition of done for a provider, so the provider this
// repository ships with it has to pass it -- and pass it with a capability
// taken away, because the "no PowerController" path is one a real provider will
// take and a suite that only ever saw the full-featured fake would never have
// exercised the type assertion at all.
func TestTheFakeObeysTheContractItPolices(t *testing.T) {
	RunContractTests(t, "fake", func(t *testing.T) Provider {
		return NewFake()
	})
	RunContractTests(t, "fake that cannot stop a machine", func(t *testing.T) Provider {
		return NewFake(FakeWithoutPower())
	})
	RunContractTests(t, "fake with no optional capabilities at all", func(t *testing.T) Provider {
		return NewFake(FakeWithoutPower(), FakeWithoutBootstrap(), FakeWithoutDiscovery())
	})
}

package provider

import (
	"errors"
	"strings"
	"time"
)

// FailureKind is why a provider call failed, in the terms the reconciler's next
// move is decided in. Every category exists because something different happens
// next; a category nothing branches on would be prose, and prose belongs in
// Error.Message.
type FailureKind string

const (
	// FailureConfig is a setting that is wrong. Nothing but an edit will fix it.
	FailureConfig FailureKind = "config"
	// FailureAuth is a credential the provider rejected outright.
	FailureAuth FailureKind = "auth"
	// FailurePermission is a credential that is valid and not allowed to do
	// this. It is kept apart from FailureAuth because the advice differs: one is
	// "this token is wrong", the other is "this token is right and lacks a
	// privilege on a path", and an operator sent to the wrong one of those loses
	// an afternoon. The message names the privilege and the path.
	FailurePermission FailureKind = "permission"
	// FailureUnreachable is a provider we could not talk to. It is never
	// evidence about a resource: nothing may be created, deleted or failed on
	// the strength of it.
	FailureUnreachable FailureKind = "unreachable"
	// FailureQuota is a refusal for want of resources or a limit. Retryable,
	// slowly, and never by asking for more.
	FailureQuota FailureKind = "quota"
	// FailureConflict is something else holding the resource -- a lock, a
	// migration, an identifier another caller took. Resolved by observation.
	FailureConflict FailureKind = "conflict"
	// FailureNotFound is a resource that is not there. For a delete that is
	// success, which is why it is a category rather than an error to report.
	FailureNotFound FailureKind = "not_found"
	// FailureRefused is a definite refusal of the provider's own, in its words.
	FailureRefused FailureKind = "refused"
	// FailureAmbiguous is the one that matters: we do not know whether it
	// happened. A timeout on a create is this, not a failure. A machine whose
	// last operation ended here is reconciled by identity before anything else
	// is attempted, and is NEVER retried blindly.
	FailureAmbiguous FailureKind = "ambiguous"
	// FailureInternal is anything we could not classify, including a kind from a
	// newer contract than this build knows. It retries nothing.
	FailureInternal FailureKind = "internal"
)

// Valid reports whether k is a category this build knows. It is the check
// KindOf makes before trusting a kind that arrived from anywhere but this
// package's own constants.
func (k FailureKind) Valid() bool {
	switch k {
	case FailureConfig, FailureAuth, FailurePermission, FailureUnreachable,
		FailureQuota, FailureConflict, FailureNotFound, FailureRefused,
		FailureAmbiguous, FailureInternal:
		return true
	}
	return false
}

// The sentinels. Every *Error unwraps to exactly one of them, so a caller that
// only asks "was this a not-found" keeps using errors.Is and only a caller that
// wants the remedy or the retry-after reaches for errors.As -- the shape
// github.RateLimitedError already has.
var (
	ErrConfig      = errors.New("provider: configuration is wrong")
	ErrAuth        = errors.New("provider: credential was rejected")
	ErrPermission  = errors.New("provider: credential is not allowed to do that")
	ErrUnreachable = errors.New("provider: could not be reached")
	ErrQuota       = errors.New("provider: refused for want of capacity")
	ErrConflict    = errors.New("provider: resource is held by something else")
	ErrNotFound    = errors.New("provider: resource not found")
	ErrRefused     = errors.New("provider: refused")
	ErrAmbiguous   = errors.New("provider: the outcome of that operation is unknown")
	// ErrUnsupported is a build and a provider that cannot work together: no
	// factory for a kind, or a contract range that does not contain this
	// build's version.
	ErrUnsupported = errors.New("provider: contract version not supported")
)

// sentinels maps a category to the error a caller matches with errors.Is.
var sentinels = map[FailureKind]error{
	FailureConfig:      ErrConfig,
	FailureAuth:        ErrAuth,
	FailurePermission:  ErrPermission,
	FailureUnreachable: ErrUnreachable,
	FailureQuota:       ErrQuota,
	FailureConflict:    ErrConflict,
	FailureNotFound:    ErrNotFound,
	FailureRefused:     ErrRefused,
	FailureAmbiguous:   ErrAmbiguous,
}

// Error is a provider failure with enough structure for the reconciler to
// decide and enough prose for the page to show.
//
// The category is the Kind field alone. It is deliberately not inferred from
// whatever the cause happens to wrap: the classification that decides whether a
// machine is retried or looked at has to be made where the answer is known --
// inside the transport, which is the only layer that knows whether a deadline
// passed before or after the request body went out -- and never rediscovered
// higher up from an error string.
type Error struct {
	Kind FailureKind
	// Op is what was being attempted, in prose written at the call site, so
	// that the message says which step of which machine's life failed.
	Op string
	// Ref is the resource, when there is one.
	Ref string
	// Message is the provider's own words. It is shown verbatim: a provider's
	// sentence about which storage is full is worth more than ours about a
	// status code.
	Message string
	// Remedy is what to change, concretely. An operator who gets a refusal is
	// owed the next action, not the status code.
	Remedy string
	// RetryAfter is how long the provider asked us to wait. Zero means it did
	// not say, and the caller keeps its own backoff.
	RetryAfter time.Duration
	// Cause is what went wrong underneath, kept for the message and for a
	// caller that wants it. It is not unwrapped into: see the type comment.
	Cause error
}

func (e *Error) Error() string {
	var b strings.Builder
	if e.Op != "" {
		b.WriteString(e.Op)
		if e.Ref != "" {
			b.WriteString(" ")
			b.WriteString(e.Ref)
		}
		b.WriteString(": ")
	} else if e.Ref != "" {
		b.WriteString(e.Ref)
		b.WriteString(": ")
	}
	b.WriteString(e.sentinel().Error())
	switch {
	case e.Message != "":
		b.WriteString(": ")
		b.WriteString(e.Message)
	case e.Cause != nil:
		b.WriteString(": ")
		b.WriteString(e.Cause.Error())
	}
	if e.Remedy != "" {
		b.WriteString(" Fix: ")
		b.WriteString(e.Remedy)
	}
	return b.String()
}

// Unwrap answers the sentinel for this failure's category, so errors.Is keeps
// working for every caller that only wants to know what sort of refusal it was.
func (e *Error) Unwrap() error { return e.sentinel() }

// sentinel is the error for this failure's category, and ErrUnsupported's
// stablemate for a kind this build does not know: an unrecognised category is
// internal, which retries nothing.
func (e *Error) sentinel() error {
	if s, ok := sentinels[e.Kind]; ok {
		return s
	}
	return errInternal
}

// errInternal is unexported because there is nothing useful a caller can do
// with "we could not classify this" beyond what KindOf already tells it, and an
// exported sentinel for it would invite code to branch on the unclassifiable.
var errInternal = errors.New("provider: unclassified provider failure")

// KindOf reports a failure's category, answering FailureInternal for anything it
// does not recognise -- the safe direction, because internal retries nothing and
// deletes nothing. A kind from a newer contract than this build knows lands
// there too, which is the forward-compatibility rule stated in ContractVersion.
//
// A context cancellation is the caller's own doing rather than a provider
// failure, and is not classified here: check errors.Is(err, context.Canceled)
// before asking this.
func KindOf(err error) FailureKind {
	if err == nil {
		return ""
	}
	var pe *Error
	if errors.As(err, &pe) {
		if pe.Kind.Valid() {
			return pe.Kind
		}
		return FailureInternal
	}
	// A provider may also return a bare sentinel, which is the whole point of
	// exporting them.
	for kind, sentinel := range sentinels {
		if errors.Is(err, sentinel) {
			return kind
		}
	}
	return FailureInternal
}

// Retryable reports whether the same call is worth making again.
//
// It is false for config, auth, permission, ambiguous and internal. The first
// three because nothing but a person changes the answer; internal because we do
// not know what happened; and ambiguous because an operation whose outcome is
// unknown must never be repeated -- its only legal next move is observation,
// and a retry is how one machine becomes two machines and one invoice.
func Retryable(err error) bool {
	switch KindOf(err) {
	case FailureUnreachable, FailureQuota, FailureConflict, FailureNotFound, FailureRefused:
		return true
	}
	return false
}

// RetryAfter is when a caller may try again, given the time it is asking at.
//
// A time already in the past is no answer -- clocks drift and responses queue --
// so it reports unknown and the caller keeps its own backoff rather than
// resuming straight into the same refusal. That is the rule
// github.RateLimitedError.RetryAt already follows, for the same reason.
func RetryAfter(err error, now time.Time) (time.Time, bool) {
	var pe *Error
	if !errors.As(err, &pe) || pe.RetryAfter == 0 {
		return time.Time{}, false
	}
	at := now.Add(pe.RetryAfter)
	if !at.After(now) {
		return time.Time{}, false
	}
	return at, true
}

package provider

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"
)

// Every category has to survive the trip through errors.Is, because that is how
// the reconciler asks its questions. A kind from a newer contract lands on
// internal, which retries nothing and deletes nothing -- the safe direction, and
// the one the contract promises.
func TestEveryFailureIsClassifiedAndTheUnrecognisedOnesAreInternal(t *testing.T) {
	for _, tc := range []struct {
		name     string
		err      error
		want     FailureKind
		sentinel error
	}{
		{"a configuration mistake", &Error{Kind: FailureConfig}, FailureConfig, ErrConfig},
		{"a rejected credential", &Error{Kind: FailureAuth}, FailureAuth, ErrAuth},
		{"a credential without the privilege", &Error{Kind: FailurePermission}, FailurePermission, ErrPermission},
		{"a provider we could not reach", &Error{Kind: FailureUnreachable}, FailureUnreachable, ErrUnreachable},
		{"no capacity", &Error{Kind: FailureQuota}, FailureQuota, ErrQuota},
		{"something else holding it", &Error{Kind: FailureConflict}, FailureConflict, ErrConflict},
		{"a resource that is not there", &Error{Kind: FailureNotFound}, FailureNotFound, ErrNotFound},
		{"a refusal in the provider's own words", &Error{Kind: FailureRefused}, FailureRefused, ErrRefused},
		{"an outcome nobody heard", &Error{Kind: FailureAmbiguous}, FailureAmbiguous, ErrAmbiguous},
		{"something we could not classify", &Error{Kind: FailureInternal}, FailureInternal, nil},
		{"a category from a later contract", &Error{Kind: "hibernated"}, FailureInternal, nil},
		{"a bare error from a provider that said nothing", errors.New("boom"), FailureInternal, nil},
		{"a bare sentinel", ErrNotFound, FailureNotFound, ErrNotFound},
		{"a wrapped provider error", fmt.Errorf("while creating: %w", &Error{Kind: FailureQuota}), FailureQuota, ErrQuota},
		{"a cancelled context, which is the caller's own doing", context.Canceled, FailureInternal, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := KindOf(tc.err); got != tc.want {
				t.Errorf("KindOf = %q, want %q", got, tc.want)
			}
			if tc.sentinel != nil && !errors.Is(tc.err, tc.sentinel) {
				t.Errorf("errors.Is against %v is false; a caller asking the cheap question would miss it", tc.sentinel)
			}
		})
	}
	if got := KindOf(nil); got != "" {
		t.Errorf("KindOf(nil) = %q; a call that worked has no failure category", got)
	}
}

// Retryable is the whole of the reconciler's "try again?" decision, and the
// ambiguous row is the one that costs money: an operation whose outcome is
// unknown must be resolved by looking, never by repeating, because repeating a
// create that already worked buys a second machine nobody is tracking.
func TestAnAmbiguousOutcomeIsNeverRetriedAndNeitherIsAnythingAPersonMustFix(t *testing.T) {
	for _, tc := range []struct {
		kind FailureKind
		want bool
	}{
		{FailureConfig, false},
		{FailureAuth, false},
		{FailurePermission, false},
		{FailureAmbiguous, false},
		{FailureInternal, false},
		{FailureUnreachable, true},
		{FailureQuota, true},
		{FailureConflict, true},
		{FailureNotFound, true},
		{FailureRefused, true},
	} {
		t.Run(string(tc.kind), func(t *testing.T) {
			if got := Retryable(&Error{Kind: tc.kind}); got != tc.want {
				t.Errorf("Retryable(%s) = %t, want %t", tc.kind, got, tc.want)
			}
		})
	}
	if Retryable(nil) {
		t.Error("Retryable(nil) is true; a call that worked would be made again")
	}
	if Retryable(errors.New("boom")) {
		t.Error("an unclassified failure is retryable; we would repeat an operation we know nothing about")
	}
}

// A retry time already in the past is no answer -- clocks drift and responses
// queue -- so the caller keeps its own backoff rather than resuming straight
// into the same refusal.
func TestARetryTimeAlreadyInThePastIsNoAnswer(t *testing.T) {
	now := time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)
	for _, tc := range []struct {
		name string
		err  error
		want time.Duration
		ok   bool
	}{
		{"the provider asked for a minute", &Error{Kind: FailureQuota, RetryAfter: time.Minute}, time.Minute, true},
		{"the provider said nothing", &Error{Kind: FailureQuota}, 0, false},
		{"a duration that has already elapsed", &Error{Kind: FailureQuota, RetryAfter: -time.Minute}, 0, false},
		{"not a provider failure at all", errors.New("boom"), 0, false},
		{"wrapped, because callers wrap", fmt.Errorf("creating: %w", &Error{Kind: FailureQuota, RetryAfter: time.Hour}), time.Hour, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			at, ok := RetryAfter(tc.err, now)
			if ok != tc.ok {
				t.Fatalf("RetryAfter said %t, want %t", ok, tc.ok)
			}
			if ok && !at.Equal(now.Add(tc.want)) {
				t.Errorf("RetryAfter = %s, want %s", at, now.Add(tc.want))
			}
		})
	}
}

// The message is read by an operator on a page, so it has to say what was being
// done, to what, in whose words, and what to change. A status code on its own
// sends somebody to the wrong half of the system.
func TestAFailureSaysWhatWasBeingDoneAndWhatToChange(t *testing.T) {
	err := &Error{
		Kind:    FailurePermission,
		Op:      "clone the template",
		Ref:     "zoomies-mach-abc",
		Message: "the credential may not write to this storage",
		Remedy:  "Grant the credential space on the storage the provider is configured with.",
	}
	got := err.Error()
	for _, want := range []string{"clone the template", "zoomies-mach-abc", "not allowed", "may not write", "Fix: Grant"} {
		if !strings.Contains(got, want) {
			t.Errorf("the message %q does not contain %q", got, want)
		}
	}

	// A failure with a cause and no words of its own still says something.
	cause := &Error{Kind: FailureUnreachable, Cause: context.DeadlineExceeded}
	if !strings.Contains(cause.Error(), context.DeadlineExceeded.Error()) {
		t.Errorf("a failure with only a cause says %q", cause.Error())
	}

	// The category is the Kind field and nothing else. An error carrying a
	// cause that happens to be another category must not be reclassified by it:
	// only the transport knows which side of the request the failure fell on.
	mixed := &Error{Kind: FailureUnreachable, Cause: ErrAmbiguous}
	if got := KindOf(mixed); got != FailureUnreachable {
		t.Errorf("KindOf = %q; the cause reclassified the failure", got)
	}
	if errors.Is(mixed, ErrAmbiguous) {
		t.Error("a failure classified as unreachable also matches ambiguous; a caller would resolve it by looking at a resource nothing ever touched")
	}
}

package provider

import (
	"context"
	"fmt"
	"slices"
	"sync"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The fake provider lives in the production package rather than a _test.go
// file, for the reason github.FakeGitHub does: the store, controller and API
// tests all need a provider to run the whole system against, and three subtly
// different fakes would be worse than one honest one. "Honest" means it
// enforces the rules that actually bite -- a name is unique, one ref is one
// machine however many times Create is called, a resource that is gone is gone
// -- so a test that passes against it has some claim to passing against real
// infrastructure.
//
// It is in-memory rather than an HTTP server on purpose. The wire is not what
// is under test here; the reconciler's behaviour around ambiguity, restart and
// ownership is. A provider's own HTTP-level fake belongs to that provider's
// package, where the wire IS what is under test.
//
// Its limitations, so that a test does not read more into a pass than is there:
//
//   - Time does not pass. SetDelay is the only wait, and nothing ages: an idle
//     machine never becomes idle by itself.
//   - Nothing is durable. A fake is one test's worth of state; a restart in a
//     test restarts the controller around a fake that remembers everything, as
//     real infrastructure would.
//   - Concurrency is serialised behind one mutex, so it can show a reconciler
//     exceeding a create limit but cannot reproduce a hypervisor's own races.
//   - Costs, addresses and versions are made up, and no bytes ever leave the
//     process.

// Fake is an in-memory provider with knobs for the cases that are hard to reach
// against real infrastructure.
//
// It is an interface rather than a struct because the optional capabilities
// have to be ABSENT FROM THE TYPE when they are turned off -- that is the rule
// the contract states, and a struct with a flag on it would satisfy
// PowerController whatever the flag said, which is precisely the "no
// PowerController" path the reconciler needs exercised.
type Fake interface {
	Provider

	// Machines is every machine the fake is holding, live ones only.
	Machines() []Machine
	// Calls is every call made to the fake, in order, as "create <name>". It is
	// what a call-budget assertion and a "there was no second create" assertion
	// read.
	Calls() []string
	// Bootstraps is every payload pushed into a guest, kept whole so that a
	// test can scan every byte of one for a credential that should never have
	// been in it.
	Bootstraps() []Bootstrap

	// PlantOrphan puts a machine wearing our marks behind the fake's back: a
	// resource with no row, which the ownership sweep must report and never
	// delete.
	PlantOrphan(name string, owner Owner)
	// PlantForeign puts a machine wearing our naming grammar and somebody
	// else's marks: another fleet's machine, which must be quarantined rather
	// than adopted or deleted.
	PlantForeign(name string)
	// Vanish removes a resource without a delete, the way a person with a
	// console does.
	Vanish(machineID string)

	// SetFailure makes every call to an operation fail; SetFailureOnce makes
	// the next one fail. The operation names are the method names in lower
	// case: "allocate", "create", "inspect", "list", "delete", "operation",
	// "start", "stop", "bootstrap", "discover", "preflight".
	SetFailure(op string, k FailureKind, message string)
	SetFailureOnce(op string, k FailureKind, message string)
	ClearFailures()
	// SetQuota caps how many machines the fake will hold; creates past it are
	// refused with FailureQuota.
	SetQuota(max int)
	// SetDelay makes an operation take time, honoured against ctx.Done() so a
	// test can prove a deadline is enforced.
	SetDelay(op string, d time.Duration)
	// SetAsync makes an operation's handle stay unfinished for n polls, which
	// is how a create that takes minutes is reproduced in microseconds.
	SetAsync(op string, polls int)

	// SetAmbiguousAfterWork does the work and then answers FailureAmbiguous:
	// the request went out, the machine exists, and we never heard. It is the
	// case the whole design turns on, because retrying it buys a second
	// machine.
	SetAmbiguousAfterWork(op string)
	// SetAmbiguousBeforeWork answers FailureAmbiguous having done nothing: the
	// same answer, the opposite truth. A reconciler that can tell these two
	// apart without asking the provider is guessing.
	SetAmbiguousBeforeWork(op string)
}

// FakeOption turns off one of the fake's optional capabilities.
type FakeOption func(*fakeOptions)

type fakeOptions struct{ power, bootstrap, discovery bool }

// FakeWithoutPower builds a fake that cannot stop a machine without destroying
// it, so the reconciler's "delete rather than stop" path is exercised.
func FakeWithoutPower() FakeOption { return func(o *fakeOptions) { o.power = false } }

// FakeWithoutBootstrap builds a fake that cannot push the enrolment payload
// into the guest, and declares BootstrapMetadata instead.
func FakeWithoutBootstrap() FakeOption { return func(o *fakeOptions) { o.bootstrap = false } }

// FakeWithoutDiscovery builds a fake whose configuration form has to ask for
// identifiers rather than offer them.
func FakeWithoutDiscovery() FakeOption { return func(o *fakeOptions) { o.discovery = false } }

// NewFake returns a fake provider carrying every capability except the ones the
// options took away. What it returns is a different concrete type for each set
// of capabilities, which is the only way an absent capability can be genuinely
// absent.
func NewFake(opts ...FakeOption) Fake {
	o := fakeOptions{power: true, bootstrap: true, discovery: true}
	for _, opt := range opts {
		opt(&o)
	}
	c := newFakeCore(o)
	p, b, d := powerOps{c}, bootstrapOps{c}, discoverOps{c}
	switch {
	case o.power && o.bootstrap && o.discovery:
		return fakeAll{c, p, b, d}
	case o.power && o.bootstrap:
		return fakePowerBootstrap{c, p, b}
	case o.power && o.discovery:
		return fakePowerDiscovery{c, p, d}
	case o.bootstrap && o.discovery:
		return fakeBootstrapDiscovery{c, b, d}
	case o.power:
		return fakePower{c, p}
	case o.bootstrap:
		return fakeBootstrap{c, b}
	case o.discovery:
		return fakeDiscovery{c, d}
	default:
		return c
	}
}

// The capability sets, one concrete type each. They carry no logic: the
// embedded *fakeCore answers Provider and the knobs at depth one, which
// shadows the same methods reached through the operation helpers, and each
// helper contributes exactly the optional methods its capability names.
type (
	fakeAll struct {
		*fakeCore
		powerOps
		bootstrapOps
		discoverOps
	}
	fakePowerBootstrap struct {
		*fakeCore
		powerOps
		bootstrapOps
	}
	fakePowerDiscovery struct {
		*fakeCore
		powerOps
		discoverOps
	}
	fakeBootstrapDiscovery struct {
		*fakeCore
		bootstrapOps
		discoverOps
	}
	fakePower struct {
		*fakeCore
		powerOps
	}
	fakeBootstrap struct {
		*fakeCore
		bootstrapOps
	}
	fakeDiscovery struct {
		*fakeCore
		discoverOps
	}
)

type powerOps struct{ *fakeCore }
type bootstrapOps struct{ *fakeCore }
type discoverOps struct{ *fakeCore }

// fakeMachine is one machine the fake is holding.
type fakeMachine struct {
	ref     MachineRef
	phase   Phase
	owner   Owner
	address string
	detail  string
	// planted marks a machine that arrived behind the fake's back, so that a
	// foreign fleet's machines do not eat the quota we set for ours.
	planted bool
}

// fakeOp is one asynchronous operation. apply is the effect the operation has
// when it finishes, held until then so that a create in flight is a machine
// that exists and is not yet running.
type fakeOp struct {
	kind   OpKind
	polls  int
	ok     bool
	detail string
	apply  func()
}

type fakeFailure struct {
	kind    FailureKind
	message string
	once    bool
}

// fakeAmbiguity is which side of the work an operation loses its answer on.
type fakeAmbiguity int

const (
	ambiguousAfterWork fakeAmbiguity = iota + 1
	ambiguousBeforeWork
)

type fakeCore struct {
	caps Capabilities
	zone string

	mu         sync.Mutex
	nextID     int
	nextOp     int
	machines   []*fakeMachine
	ops        map[string]*fakeOp
	calls      []string
	bootstraps []Bootstrap
	failures   map[string]*fakeFailure
	ambiguous  map[string]fakeAmbiguity
	delays     map[string]time.Duration
	async      map[string]int
	quota      int
}

func newFakeCore(o fakeOptions) *fakeCore {
	boot := BootstrapMetadata
	if o.bootstrap {
		boot = BootstrapGuestAgent
	}
	return &fakeCore{
		caps: Capabilities{
			MinContract:      ContractVersion,
			MaxContract:      ContractVersion,
			Kind:             store.ProviderFake,
			Label:            "Fake provider",
			Bootstrap:        boot,
			CanStartStop:     o.power,
			CanDiscover:      o.discovery,
			CanMarkOwnership: true,
			AsyncOperations:  true,
			CostUnit:         "machine-hour",
			Deadlines: Deadlines{
				Call:      5 * time.Second,
				Allocate:  5 * time.Second,
				Create:    30 * time.Second,
				Bootstrap: 30 * time.Second,
				Delete:    30 * time.Second,
			},
		},
		zone:      "zone-a",
		ops:       map[string]*fakeOp{},
		failures:  map[string]*fakeFailure{},
		ambiguous: map[string]fakeAmbiguity{},
		delays:    map[string]time.Duration{},
		async:     map[string]int{},
	}
}

func (f *fakeCore) Kind() store.ProviderKind   { return f.caps.Kind }
func (f *fakeCore) Capabilities() Capabilities { return f.caps }

// ---------------------------------------------------------------------------
// The knobs
// ---------------------------------------------------------------------------

func (f *fakeCore) Machines() []Machine {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]Machine, 0, len(f.machines))
	for _, m := range f.machines {
		out = append(out, m.view())
	}
	return out
}

func (f *fakeCore) Calls() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.calls)
}

func (f *fakeCore) Bootstraps() []Bootstrap {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.bootstraps)
}

func (f *fakeCore) PlantOrphan(name string, owner Owner) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.plant(name, owner)
}

func (f *fakeCore) PlantForeign(name string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.plant(name, Owner{
		ControllerID: "ctl_somebodyelse",
		ProviderID:   "prv_somebodyelse",
		MachineID:    "mach_somebodyelse",
		Fingerprint:  "somebodyelses",
	})
}

func (f *fakeCore) plant(name string, owner Owner) {
	f.nextID++
	f.machines = append(f.machines, &fakeMachine{
		ref:     MachineRef{Zone: f.zone, ID: fmt.Sprintf("%d", 100+f.nextID), Name: name},
		phase:   PhaseRunning,
		owner:   owner,
		planted: true,
	})
}

func (f *fakeCore) Vanish(machineID string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.machines = slices.DeleteFunc(f.machines, func(m *fakeMachine) bool { return m.ref.ID == machineID })
}

func (f *fakeCore) SetFailure(op string, k FailureKind, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures[op] = &fakeFailure{kind: k, message: message}
}

func (f *fakeCore) SetFailureOnce(op string, k FailureKind, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.failures[op] = &fakeFailure{kind: k, message: message, once: true}
}

func (f *fakeCore) ClearFailures() {
	f.mu.Lock()
	defer f.mu.Unlock()
	clear(f.failures)
	clear(f.ambiguous)
}

func (f *fakeCore) SetQuota(max int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.quota = max
}

func (f *fakeCore) SetDelay(op string, d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.delays[op] = d
}

func (f *fakeCore) SetAsync(op string, polls int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.async[op] = polls
}

func (f *fakeCore) SetAmbiguousAfterWork(op string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.ambiguous[op] = ambiguousAfterWork
}

func (f *fakeCore) SetAmbiguousBeforeWork(op string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.ambiguous[op] = ambiguousBeforeWork
}

// ---------------------------------------------------------------------------
// The contract
// ---------------------------------------------------------------------------

func (f *fakeCore) Preflight(ctx context.Context) Report {
	// Preflight reports rather than fails, so an injected failure comes back as
	// a finding: an operator with a wrong credential must still get a page that
	// says which credential and what to change.
	if err := f.begin(ctx, "preflight", ""); err != nil {
		return Report{Findings: []config.Finding{{
			Code:     "provider.preflight_failed",
			Severity: config.SeverityError,
			Setting:  "provider.credential",
			Title:    "The fake provider refused the connection check",
			Detail:   err.Error(),
			Fix:      "This is the in-memory fake; a test asked it to refuse.",
		}}}
	}
	return Report{Reachable: true, Version: "fake-1"}
}

func (f *fakeCore) Allocate(ctx context.Context, spec MachineSpec) (MachineRef, error) {
	if err := f.begin(ctx, "allocate", spec.Name); err != nil {
		return MachineRef{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if m := f.findLocked(MachineRef{Name: spec.Name}); m != nil {
		return MachineRef{}, f.fail("allocate", FailureConflict, spec.Name,
			fmt.Sprintf("a machine named %q already exists", spec.Name),
			"Names are unique per provider; the caller has reused one.")
	}
	// Identity is minted and nothing is created: the counter moving is the only
	// trace an allocate leaves, which is what lets the caller persist the
	// identity before anything can exist to be lost.
	f.nextID++
	return MachineRef{Zone: f.zone, ID: fmt.Sprintf("%d", 100+f.nextID), Name: spec.Name}, nil
}

func (f *fakeCore) Create(ctx context.Context, ref MachineRef, spec MachineSpec) (OperationRef, error) {
	if err := f.begin(ctx, "create", ref.Name); err != nil {
		return OperationRef{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()

	// One ref is one machine, however many times this is called. It is the
	// rule that makes a re-issued create after an unknown outcome safe.
	if m := f.findLocked(ref); m != nil {
		return f.opLocked(OpCreate, true, "machine already exists", nil), nil
	}
	if f.quota > 0 && f.liveLocked() >= f.quota {
		return OperationRef{}, f.fail("create", FailureQuota, ref.Name,
			fmt.Sprintf("no capacity for another machine: %d of %d in use", f.liveLocked(), f.quota),
			"Free a machine or raise the provider's ceiling.")
	}
	m := &fakeMachine{ref: ref, phase: PhaseCreating, owner: spec.Owner, detail: "creating"}
	f.machines = append(f.machines, m)
	op := f.opLocked(OpCreate, true, "created", func() {
		m.phase = PhaseRunning
		m.address = "198.51.100." + m.ref.ID
		m.detail = "running"
	})
	if f.ambiguous["create"] == ambiguousAfterWork {
		// The machine exists and the caller will never hear so. Anything but an
		// Inspect from here buys a second machine.
		return OperationRef{}, f.fail("create", FailureAmbiguous, ref.Name,
			"the connection dropped after the request went out",
			"Look for the machine by the identity you allocated; do not create another.")
	}
	return op, nil
}

func (f *fakeCore) Inspect(ctx context.Context, ref MachineRef) (Machine, error) {
	if err := f.begin(ctx, "inspect", ref.Name); err != nil {
		return Machine{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	m := f.findLocked(ref)
	if m == nil {
		return Machine{}, f.fail("inspect", FailureNotFound, ref.Name, "no such machine", "")
	}
	return m.view(), nil
}

func (f *fakeCore) List(ctx context.Context, owner Owner) ([]Machine, error) {
	if err := f.begin(ctx, "list", ""); err != nil {
		return nil, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	var out []Machine
	for _, m := range f.machines {
		// Ours by mark, or somebody else's wearing our name grammar. The second
		// is the half a sweep cannot do without: it is how a foreign fleet's
		// machine is told from an orphan of our own.
		if m.owner.ControllerID == owner.ControllerID || store.IsMachineName(m.ref.Name) {
			out = append(out, m.view())
		}
	}
	return out, nil
}

func (f *fakeCore) Delete(ctx context.Context, ref MachineRef) (OperationRef, error) {
	if err := f.begin(ctx, "delete", ref.Name); err != nil {
		return OperationRef{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	m := f.findLocked(ref)
	if m == nil {
		// The desired end state has been reached, so there is nothing to
		// follow and nothing to report.
		return OperationRef{}, nil
	}
	m.phase = PhaseDeleting
	m.detail = "deleting"
	op := f.opLocked(OpDelete, true, "deleted", func() {
		f.machines = slices.DeleteFunc(f.machines, func(x *fakeMachine) bool { return x == m })
	})
	if f.ambiguous["delete"] == ambiguousAfterWork {
		return OperationRef{}, f.fail("delete", FailureAmbiguous, ref.Name,
			"the connection dropped after the request went out",
			"Inspect the machine: a delete that was issued cannot be un-issued.")
	}
	return op, nil
}

func (f *fakeCore) Operation(ctx context.Context, ref OperationRef) (OperationStatus, error) {
	if err := f.begin(ctx, "operation", ref.Handle); err != nil {
		return OperationStatus{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	op, ok := f.ops[ref.Handle]
	if !ok {
		// An unknown handle is not-found rather than a panic: after a restart
		// the controller asks about handles the provider may have forgotten.
		return OperationStatus{}, f.fail("operation", FailureNotFound, ref.Handle,
			"no such operation", "")
	}
	if op.polls > 0 {
		op.polls--
		return OperationStatus{Detail: "in progress"}, nil
	}
	if op.apply != nil {
		op.apply()
		op.apply = nil
	}
	return OperationStatus{Done: true, OK: op.ok, Detail: op.detail}, nil
}

func (p powerOps) Start(ctx context.Context, ref MachineRef) (OperationRef, error) {
	return p.power(ctx, "start", OpStart, ref, PhaseRunning, "started")
}

func (p powerOps) Stop(ctx context.Context, ref MachineRef, graceful bool) (OperationRef, error) {
	detail := "stopped"
	if graceful {
		detail = "shut down"
	}
	return p.power(ctx, "stop", OpStop, ref, PhaseStopped, detail)
}

func (f *fakeCore) power(ctx context.Context, name string, kind OpKind, ref MachineRef, to Phase, detail string) (OperationRef, error) {
	if err := f.begin(ctx, name, ref.Name); err != nil {
		return OperationRef{}, err
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	m := f.findLocked(ref)
	if m == nil {
		return OperationRef{}, f.fail(name, FailureNotFound, ref.Name, "no such machine", "")
	}
	return f.opLocked(kind, true, detail, func() { m.phase, m.detail = to, detail }), nil
}

func (b bootstrapOps) Bootstrap(ctx context.Context, ref MachineRef, payload Bootstrap) (OperationRef, error) {
	if err := b.begin(ctx, "bootstrap", ref.Name); err != nil {
		return OperationRef{}, err
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	m := b.findLocked(ref)
	if m == nil {
		return OperationRef{}, b.fail("bootstrap", FailureNotFound, ref.Name, "no such machine", "")
	}
	// Kept whole, because what a test wants to ask of a payload is what is NOT
	// in it.
	b.bootstraps = append(b.bootstraps, payload)
	return b.opLocked(OpBootstrap, true, "bootstrapped", nil), nil
}

func (d discoverOps) Discover(ctx context.Context) (Discovery, error) {
	if err := d.begin(ctx, "discover", ""); err != nil {
		return Discovery{}, err
	}
	return Discovery{
		Nodes: []Choice{{Value: d.zone, Label: d.zone, Consequence: "Machines are created here."}},
	}, nil
}

// ---------------------------------------------------------------------------
// Plumbing
// ---------------------------------------------------------------------------

// begin records the call, serves the delay against the caller's deadline, and
// applies whatever failure a test asked for. It is one function so that every
// operation gets the same treatment and a new one cannot quietly skip the
// cancellation check.
func (f *fakeCore) begin(ctx context.Context, op, ref string) error {
	f.mu.Lock()
	call := op
	if ref != "" {
		call = op + " " + ref
	}
	f.calls = append(f.calls, call)
	delay := f.delays[op]
	ambiguity := f.ambiguous[op]
	failure := f.failures[op]
	if failure != nil && failure.once {
		delete(f.failures, op)
	}
	f.mu.Unlock()

	if err := ctx.Err(); err != nil {
		// Returned untouched: a cancellation is the caller's own doing and
		// classifying it as a provider failure would have the reconciler blame
		// the hypervisor for its own shutdown.
		return err
	}
	if delay > 0 {
		t := time.NewTimer(delay)
		defer t.Stop()
		select {
		case <-t.C:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	if failure != nil {
		return f.fail(op, failure.kind, ref, failure.message, "")
	}
	if ambiguity == ambiguousBeforeWork {
		return f.fail(op, FailureAmbiguous, ref,
			"the connection dropped before the request went out",
			"Look before acting: this answer is the same whether or not the work happened.")
	}
	return nil
}

func (f *fakeCore) fail(op string, kind FailureKind, ref, message, remedy string) error {
	return &Error{Kind: kind, Op: op, Ref: ref, Message: message, Remedy: remedy}
}

// opLocked mints an operation handle. polls comes from SetAsync, so an
// operation a test made slow is unfinished for exactly as long as it asked.
func (f *fakeCore) opLocked(kind OpKind, ok bool, detail string, apply func()) OperationRef {
	f.nextOp++
	handle := fmt.Sprintf("op-%s-%d", kind, f.nextOp)
	f.ops[handle] = &fakeOp{kind: kind, polls: f.async[string(kind)], ok: ok, detail: detail, apply: apply}
	return OperationRef{Kind: kind, Handle: handle}
}

// findLocked matches by native identifier, and by name when the caller has
// nothing else -- the shape a provider that only knows its own name after
// creation has to support.
func (f *fakeCore) findLocked(ref MachineRef) *fakeMachine {
	for _, m := range f.machines {
		switch {
		case ref.ID != "" && m.ref.ID == ref.ID:
			return m
		case ref.ID == "" && ref.Name != "" && m.ref.Name == ref.Name:
			return m
		}
	}
	return nil
}

// liveLocked counts the machines this fake made, which is what a quota bounds.
// Planted ones belong to somebody else and are not ours to be charged for.
func (f *fakeCore) liveLocked() int {
	n := 0
	for _, m := range f.machines {
		if !m.planted {
			n++
		}
	}
	return n
}

func (m *fakeMachine) view() Machine {
	return Machine{
		Ref:     m.ref,
		Phase:   m.phase,
		Owner:   m.owner,
		Address: m.address,
		Detail:  m.detail,
	}
}

// ---------------------------------------------------------------------------
// The factory
// ---------------------------------------------------------------------------

// FakeFactory builds fakes, so that a test can exercise the registry, the
// version handshake and the settings schema without a real provider.
type FakeFactory struct {
	opts []FakeOption
	caps Capabilities
}

// NewFakeFactory returns a factory whose fakes carry the capabilities these
// options leave. Its description is taken from a fake it builds, so the factory
// cannot describe one thing and build another -- a test that wants that
// disagreement has to write its own factory, and one does.
func NewFakeFactory(opts ...FakeOption) *FakeFactory {
	return &FakeFactory{opts: opts, caps: NewFake(opts...).Capabilities()}
}

func (f *FakeFactory) Kind() store.ProviderKind { return store.ProviderFake }
func (f *FakeFactory) Describe() Capabilities   { return f.caps }

func (f *FakeFactory) Settings() []SettingSpec {
	return []SettingSpec{{
		Key:         "zone",
		Label:       "Zone",
		Kind:        SettingChoice,
		Required:    true,
		Help:        "Where machines are created.",
		Consequence: "Every machine this provider buys is created here.",
		Discovers:   "nodes",
		Default:     "zone-a",
	}}
}

// Validate is offline, as the contract requires: it reads the answers and
// dials nothing.
func (f *FakeFactory) Validate(settings map[string]string) []config.Finding {
	if settings["zone"] == "" {
		return []config.Finding{{
			Code:     "provider.zone_missing",
			Severity: config.SeverityError,
			Setting:  "provider.settings.zone",
			Title:    "This provider has no zone",
			Detail:   "Machines cannot be created without somewhere to create them.",
			Fix:      "Choose a zone.",
		}}
	}
	return nil
}

func (f *FakeFactory) New(_ context.Context, _ Config) (Provider, error) {
	return NewFake(f.opts...), nil
}

// DiscoverDraft answers as the built fake would, so a test of the wizard's
// draft discovery exercises the same path a real driver takes.
func (f *FakeFactory) DiscoverDraft(ctx context.Context, _ Config) (Discovery, error) {
	d, ok := NewFake(f.opts...).(Discoverer)
	if !ok {
		return Discovery{}, ErrUnsupported
	}
	return d.Discover(ctx)
}

package provider

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// newFakeMachine mints an identity the way the controller does, so the fake's
// tests exercise the real name grammar a cluster-wide sweep filters on.
func newFakeMachine(t *testing.T) (Owner, MachineSpec) {
	t.Helper()
	owner, spec := newSpec()
	return owner, spec
}

func mustAllocate(t *testing.T, f Fake, spec MachineSpec) MachineRef {
	t.Helper()
	ref, err := f.Allocate(context.Background(), spec)
	if err != nil {
		t.Fatalf("Allocate: %v", err)
	}
	return ref
}

// The single most important thing the fake enforces: one identity is one
// machine. A fake that quietly built a second one would let every restart and
// ambiguity test in the controller pass while the real failure -- two machines,
// one row, one invoice -- went unnoticed.
func TestTheFakeBuildsOneMachinePerIdentityHoweverOftenCreateIsCalled(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	owner, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)

	for range 3 {
		if _, err := f.Create(ctx, ref, spec); err != nil {
			t.Fatalf("Create: %v", err)
		}
	}
	if got := len(f.Machines()); got != 1 {
		t.Fatalf("the fake holds %d machines after three creates for one ref", got)
	}
	ms, err := f.List(ctx, owner)
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(ms) != 1 || ms[0].Ref != ref {
		t.Errorf("List = %+v, want the one machine at %+v", ms, ref)
	}
}

// Names are unique per provider because the name is the primary ownership mark:
// two machines answering to one name make a sweep's evidence meaningless.
func TestTheFakeRefusesASecondMachineWearingAnExistingName(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	_, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	if _, err := f.Create(ctx, ref, spec); err != nil {
		t.Fatalf("Create: %v", err)
	}
	_, err := f.Allocate(ctx, spec)
	if KindOf(err) != FailureConflict {
		t.Fatalf("Allocate for a name in use = %v, want a conflict", err)
	}
	if !errors.Is(err, ErrConflict) {
		t.Error("the refusal does not match ErrConflict")
	}
}

// Allocate mints identity and creates nothing. That ordering is what lets the
// controller write the identity down before anything can exist to be lost.
func TestAllocatingTwiceMintsTwoIdentitiesAndCreatesNothing(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	_, spec := newFakeMachine(t)
	first := mustAllocate(t, f, spec)
	second := mustAllocate(t, f, spec)
	if first.ID == second.ID {
		t.Errorf("two allocates returned one identity, %q", first.ID)
	}
	if got := len(f.Machines()); got != 0 {
		t.Fatalf("the fake holds %d machines after two allocates and no create", got)
	}
	if _, err := f.Inspect(ctx, first); !errors.Is(err, ErrNotFound) {
		t.Errorf("Inspect of an allocated-but-uncreated ref = %v, want not found", err)
	}
}

// The two knobs the whole design turns on. Both answers are identical to the
// caller and the truths behind them are opposite, which is exactly why a
// reconciler may not decide between them without looking.
func TestAnAmbiguousAnswerHidesBothOutcomesEquallyWell(t *testing.T) {
	for _, tc := range []struct {
		name      string
		arrange   func(Fake)
		wantFound bool
	}{
		{"the work happened and the answer was lost", func(f Fake) { f.SetAmbiguousAfterWork("create") }, true},
		{"nothing happened and the answer was lost", func(f Fake) { f.SetAmbiguousBeforeWork("create") }, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			f := NewFake()
			_, spec := newFakeMachine(t)
			ref := mustAllocate(t, f, spec)
			tc.arrange(f)

			op, err := f.Create(ctx, ref, spec)
			if KindOf(err) != FailureAmbiguous {
				t.Fatalf("Create = %v, want an ambiguous outcome", err)
			}
			if Retryable(err) {
				t.Error("an ambiguous create reads as retryable; the retry is what buys the second machine")
			}
			if !op.Zero() {
				t.Error("an ambiguous create handed back a handle; the point of the case is that there is nothing to follow")
			}
			_, err = f.Inspect(ctx, ref)
			if found := err == nil; found != tc.wantFound {
				t.Errorf("Inspect after the ambiguous create found the machine = %t, want %t (err %v)", found, tc.wantFound, err)
			}
		})
	}
}

// A quota is how the fake reproduces the refusal that is retryable but not
// solvable: there is no capacity, and asking again immediately only spends the
// next window on refusals.
func TestTheFakeStopsCreatingOnceItsQuotaIsSpent(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	f.SetQuota(2)
	for i := range 3 {
		_, spec := newFakeMachine(t)
		ref := mustAllocate(t, f, spec)
		_, err := f.Create(ctx, ref, spec)
		switch {
		case i < 2 && err != nil:
			t.Fatalf("create %d: %v", i, err)
		case i == 2:
			if KindOf(err) != FailureQuota {
				t.Fatalf("the third create = %v, want a quota refusal", err)
			}
			if !Retryable(err) {
				t.Error("a quota refusal is not retryable; capacity does come back")
			}
		}
	}
	// Somebody else's machines are not ours to be charged for.
	f.PlantForeign(store.NewMachineName(store.NewID(store.PrefixMachine)))
	if got := len(f.Machines()); got != 3 {
		t.Fatalf("the fake holds %d machines, want two of ours and one foreign", got)
	}
}

// A provider that ignores its deadline holds the reconcile pass open. The fake
// waits against the caller's context so a test can prove the deadline is the
// thing that ends the call.
func TestASlowCallIsEndedByTheCallersDeadlineAndNotItsOwn(t *testing.T) {
	f := NewFake()
	f.SetDelay("inspect", time.Minute)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()

	start := time.Now()
	_, err := f.Inspect(ctx, MachineRef{ID: "1", Name: "zoomies-mach-none"})
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Inspect = %v, want the caller's deadline", err)
	}
	if elapsed := time.Since(start); elapsed > 10*time.Second {
		t.Fatalf("Inspect took %s; it served its own delay rather than the caller's deadline", elapsed)
	}
}

// An operation that finishes the instant it is issued cannot show the case that
// matters -- a create still running when the next pass comes round -- so the
// fake can hold one open for a counted number of polls.
func TestAnAsynchronousOperationIsUnfinishedUntilItHasBeenPolledEnough(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	f.SetAsync("create", 2)
	_, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	op, err := f.Create(ctx, ref, spec)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	for i := range 2 {
		st, err := f.Operation(ctx, op)
		if err != nil {
			t.Fatalf("poll %d: %v", i, err)
		}
		if st.Done {
			t.Fatalf("poll %d reported done; the create was asked to take two polls", i)
		}
	}
	st, err := f.Operation(ctx, op)
	if err != nil {
		t.Fatalf("Operation: %v", err)
	}
	if !st.Done || !st.OK {
		t.Fatalf("Operation = %+v, want a finished, successful create", st)
	}
	m, err := f.Inspect(ctx, ref)
	if err != nil {
		t.Fatalf("Inspect: %v", err)
	}
	if m.Phase != PhaseRunning {
		t.Errorf("phase = %q after the create finished, want %q", m.Phase, PhaseRunning)
	}

	// After a restart the controller re-asks about handles it stored, so a
	// finished operation has to keep answering, and one nobody issued has to
	// answer too.
	if again, err := f.Operation(ctx, op); err != nil || !again.Done {
		t.Errorf("re-polling a finished operation = %+v, %v", again, err)
	}
	if _, err := f.Operation(ctx, OperationRef{Kind: OpCreate, Handle: "never-issued"}); !errors.Is(err, ErrNotFound) {
		t.Errorf("Operation on an unknown handle = %v, want not found", err)
	}
}

// A machine somebody destroyed from a console is the case where the row and the
// world disagree, and the fake has to be able to produce it without a delete.
func TestAResourceThatVanishesIsNotFoundRatherThanStale(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	_, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	if _, err := f.Create(ctx, ref, spec); err != nil {
		t.Fatalf("Create: %v", err)
	}
	f.Vanish(ref.ID)
	if _, err := f.Inspect(ctx, ref); !errors.Is(err, ErrNotFound) {
		t.Errorf("Inspect after the machine vanished = %v, want not found", err)
	}
	// Deleting what is already gone is the desired end state, not a failure.
	op, err := f.Delete(ctx, ref)
	if err != nil || !op.Zero() {
		t.Errorf("Delete of a vanished machine = %+v, %v; want a zero operation and no error", op, err)
	}
}

// The sweep needs both halves: our own machines with no row, and somebody
// else's wearing our naming grammar. One is an orphan to report, the other is
// another fleet's machine to leave completely alone, and a List that returned
// only the first could not tell them apart.
func TestTheSweepSeesOurOrphansAndSomebodyElsesMachines(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	owner, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	if _, err := f.Create(ctx, ref, spec); err != nil {
		t.Fatalf("Create: %v", err)
	}
	orphanName := store.NewMachineName(store.NewID(store.PrefixMachine))
	orphanOwner := owner
	orphanOwner.MachineID = store.NewID(store.PrefixMachine)
	orphanOwner.Fingerprint = store.NewSecret(12)
	f.PlantOrphan(orphanName, orphanOwner)
	foreignName := store.NewMachineName(store.NewID(store.PrefixMachine))
	f.PlantForeign(foreignName)

	ms, err := f.List(ctx, owner)
	if err != nil {
		t.Fatalf("List: %v", err)
	}
	if len(ms) != 3 {
		t.Fatalf("List returned %d machines, want ours, the orphan and the foreign one", len(ms))
	}
	for _, m := range ms {
		switch m.Ref.Name {
		case spec.Name:
			if !m.Owner.Matches(owner) {
				t.Errorf("our own machine does not carry our marks: %+v", m.Owner)
			}
		case orphanName:
			if m.Owner.MachineID == owner.MachineID {
				t.Error("the orphan carries the same machine mark as a machine we have a row for")
			}
		case foreignName:
			if m.Owner.Matches(owner) || m.Owner.Zero() {
				t.Errorf("a foreign machine must carry somebody else's marks, not ours and not none: %+v", m.Owner)
			}
		default:
			t.Errorf("List returned a machine nobody planted: %q", m.Ref.Name)
		}
	}
}

// A failure that keeps applying and one that applies once are different tests:
// the first is a provider that is down, the second is the flake that a single
// retry fixes.
func TestAFailureInjectedOnceAppliesOnce(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	f.SetFailureOnce("list", FailureUnreachable, "the connection was refused")
	if _, err := f.List(ctx, Owner{}); KindOf(err) != FailureUnreachable {
		t.Fatalf("the first List = %v, want unreachable", err)
	}
	if _, err := f.List(ctx, Owner{}); err != nil {
		t.Fatalf("the second List = %v, want the one-shot failure to be spent", err)
	}

	f.SetFailure("list", FailureAuth, "the token was rejected")
	for i := range 2 {
		if _, err := f.List(ctx, Owner{}); KindOf(err) != FailureAuth {
			t.Fatalf("List %d = %v, want the standing failure", i, err)
		}
	}
	f.ClearFailures()
	if _, err := f.List(ctx, Owner{}); err != nil {
		t.Fatalf("List after ClearFailures = %v", err)
	}
}

// Preflight reports and never fails, because an operator whose credential is
// wrong needs the page to say which credential and what to change -- not a
// status code from the one call that was meant to explain it.
func TestPreflightReportsAFailureAsSomethingToFix(t *testing.T) {
	f := NewFake()
	if r := f.Preflight(context.Background()); !r.OK() || r.Version == "" {
		t.Fatalf("a healthy preflight = %+v", r)
	}
	f.SetFailure("preflight", FailureAuth, "the token was rejected")
	r := f.Preflight(context.Background())
	if r.OK() {
		t.Fatal("a preflight that could not authenticate reads as OK")
	}
	if len(r.Findings) == 0 {
		t.Fatal("a failed preflight produced no findings; the page would have nothing to show")
	}
	if !strings.Contains(r.Findings[0].Detail, "rejected") {
		t.Errorf("the finding does not carry the provider's own words: %+v", r.Findings[0])
	}
}

// The fake exists to be asked what happened. Calls are what a "there was no
// second create" assertion reads, and payloads are kept whole because what a
// test wants to ask of one is what is NOT in it.
func TestTheFakeRecordsEveryCallAndKeepsEveryPayloadWhole(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	_, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	if _, err := f.Create(ctx, ref, spec); err != nil {
		t.Fatalf("Create: %v", err)
	}
	b, ok := f.(Bootstrapper)
	if !ok {
		t.Fatal("the default fake cannot bootstrap")
	}
	payload := Bootstrap{
		Files:    []File{{Path: "/etc/zoomies/zoomies.env", Mode: 0o600, Content: []byte("ZOOMIES_JOIN_TOKEN=join_abc\n")}},
		Commands: [][]string{{"/bin/chmod", "0600", "/etc/zoomies/zoomies.env"}},
	}
	if _, err := b.Bootstrap(ctx, ref, payload); err != nil {
		t.Fatalf("Bootstrap: %v", err)
	}

	calls := f.Calls()
	want := []string{"allocate " + spec.Name, "create " + spec.Name, "bootstrap " + spec.Name}
	if len(calls) != len(want) {
		t.Fatalf("Calls() = %v, want %v", calls, want)
	}
	for i := range want {
		if calls[i] != want[i] {
			t.Errorf("call %d = %q, want %q", i, calls[i], want[i])
		}
	}
	got := f.Bootstraps()
	if len(got) != 1 || len(got[0].Files) != 1 || string(got[0].Files[0].Content) != string(payload.Files[0].Content) {
		t.Fatalf("Bootstraps() = %+v, want the payload as it was sent", got)
	}
}

// A capability a provider does not have has to be absent from its type. If the
// fake kept the method and refused, every controller test would exercise a path
// that cannot exist in a real provider written to this contract.
func TestACapabilityTurnedOffIsAbsentFromTheTypeRatherThanRefusing(t *testing.T) {
	for _, tc := range []struct {
		name                  string
		opts                  []FakeOption
		power, boot, discover bool
	}{
		{"everything", nil, true, true, true},
		{"no power", []FakeOption{FakeWithoutPower()}, false, true, true},
		{"no bootstrap", []FakeOption{FakeWithoutBootstrap()}, true, false, true},
		{"no discovery", []FakeOption{FakeWithoutDiscovery()}, true, true, false},
		{"nothing optional at all", []FakeOption{FakeWithoutPower(), FakeWithoutBootstrap(), FakeWithoutDiscovery()}, false, false, false},
		{"power alone", []FakeOption{FakeWithoutBootstrap(), FakeWithoutDiscovery()}, true, false, false},
		{"bootstrap alone", []FakeOption{FakeWithoutPower(), FakeWithoutDiscovery()}, false, true, false},
		{"discovery alone", []FakeOption{FakeWithoutPower(), FakeWithoutBootstrap()}, false, false, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f := NewFake(tc.opts...)
			if _, ok := f.(PowerController); ok != tc.power {
				t.Errorf("implements PowerController = %t, want %t", ok, tc.power)
			}
			if _, ok := f.(Bootstrapper); ok != tc.boot {
				t.Errorf("implements Bootstrapper = %t, want %t", ok, tc.boot)
			}
			if _, ok := f.(Discoverer); ok != tc.discover {
				t.Errorf("implements Discoverer = %t, want %t", ok, tc.discover)
			}
			// And what it says about itself agrees with what it is, which is
			// the check the registry makes before handing it to anyone.
			if err := CheckCapabilities(f); err != nil {
				t.Errorf("%v", err)
			}
		})
	}
}

// Stopping a machine instead of destroying it is the only thing a fake with
// power can do that one without cannot, so it is worth proving it works rather
// than only that the method is there.
func TestAFakeThatCanStopAMachineKeepsItAfterStopping(t *testing.T) {
	ctx := context.Background()
	f := NewFake()
	_, spec := newFakeMachine(t)
	ref := mustAllocate(t, f, spec)
	op, err := f.Create(ctx, ref, spec)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if _, err := f.Operation(ctx, op); err != nil {
		t.Fatalf("Operation: %v", err)
	}
	power, ok := f.(PowerController)
	if !ok {
		t.Fatal("the default fake cannot stop a machine")
	}
	stop, err := power.Stop(ctx, ref, true)
	if err != nil {
		t.Fatalf("Stop: %v", err)
	}
	if _, err := f.Operation(ctx, stop); err != nil {
		t.Fatalf("Operation: %v", err)
	}
	m, err := f.Inspect(ctx, ref)
	if err != nil {
		t.Fatalf("Inspect: %v", err)
	}
	if m.Phase != PhaseStopped {
		t.Errorf("phase = %q after a stop, want %q: a stop that destroyed the machine is a delete", m.Phase, PhaseStopped)
	}
	start, err := power.Start(ctx, ref)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	if _, err := f.Operation(ctx, start); err != nil {
		t.Fatalf("Operation: %v", err)
	}
	if m, _ := f.Inspect(ctx, ref); m.Phase != PhaseRunning {
		t.Errorf("phase = %q after a start, want %q", m.Phase, PhaseRunning)
	}
}

// Package provider defines what Zoomies asks an infrastructure provider to do,
// and what it promises in return.
//
// A provider rents machines. It is asked for one when a pool has queued work
// and no host in the fleet can run it, and asked to destroy one when the fleet
// no longer needs it. That is the whole of its job: a provider performs
// infrastructure operations and decides nothing. How many machines should
// exist, how long each step may take, when to give up and what may be deleted
// all belong to one reconciler in the controller, for every provider, so that a
// second provider is a new package rather than a new branch in the controller.
//
// The package holds the contract and nothing else -- no SQL, no HTTP, no
// controller. It imports internal/store for the domain vocabulary a provider
// has to speak and internal/config for the finding type its preflight reports
// in, and a test holds that import set exactly where it is: a contract that has
// learned a particular hypervisor's words has stopped being one.
//
// NewFake is an in-memory provider that obeys the same rules, and
// RunContractTests is the suite every provider must pass. Both are exported
// from the production package on purpose; see fake.go and conformance.go.
package provider

import (
	"context"
	"crypto/subtle"
	"log/slog"
	"net"
	"net/http"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// ContractVersion is the provider contract this build speaks. It is bumped when
// a change would make a provider written for the previous version behave
// wrongly rather than merely miss a field: adding a field to MachineSpec, a
// method to an optional capability interface, or a FailureKind never raises it.
//
// The policy, stated once here because it is what a provider author needs:
//
//   - The controller refuses to build a provider whose declared range does not
//     contain ContractVersion, names both numbers and says which side to
//     upgrade. Machines that provider already owns stay visible, drainable and
//     deletable: a version mismatch must never strand a running machine.
//   - An unknown FailureKind reads as FailureInternal, which retries nothing
//     and asks for a person.
//   - An unknown Phase reads as PhaseUnknown, and PhaseUnknown never authorises
//     a delete. What we do not recognise, we leave alone.
//
// One version is supported, because every provider is in-tree. Accepting a
// range is a decision for whenever an out-of-tree provider exists, and
// docs/providers.md records that it was considered and deferred.
const ContractVersion = 1

// Provider is the infrastructure surface Zoomies uses. It is an interface so
// that tests can run the whole reconciler against a fake with no network, and
// so that a second provider is a new package rather than a new branch in the
// controller.
//
// Every method takes ctx first and must honour its deadline. The reconciler
// sets one on every call from Capabilities().Deadlines, floored by the
// operator's configuration; a provider that blocks past it can wedge the fleet.
//
// Nothing here reads a clock for its own decisions, opens a database, or
// retries. Backoff is the caller's, as it is in internal/github.
type Provider interface {
	Kind() store.ProviderKind
	Capabilities() Capabilities

	// Preflight checks configuration, credentials and prerequisites without
	// changing anything, and never returns an error: it reports what an
	// operator must fix. backend.Probe is the model -- "an agent on a host with
	// no Docker must still start and say so".
	Preflight(ctx context.Context) Report

	// Allocate picks the identity a Create will use and creates nothing. The
	// controller persists what this returns BEFORE calling Create, so a create
	// whose outcome is unknown is reconciled by identity rather than retried.
	// A provider whose identity is only knowable after creation returns a ref
	// carrying Name alone and must make that name findable through List.
	Allocate(ctx context.Context, spec MachineSpec) (MachineRef, error)

	// Create starts building the machine at ref. It returns as soon as the work
	// is under way; the OperationRef is how it is followed. Calling it twice for
	// one ref must not build two machines.
	Create(ctx context.Context, ref MachineRef, spec MachineSpec) (OperationRef, error)

	// Inspect reports one machine. It returns ErrNotFound when the resource is
	// gone, which callers read as "already deleted", not as a failure. The
	// Machine it returns carries the ownership marks as the provider read them
	// back, never as the caller supplied them.
	Inspect(ctx context.Context, ref MachineRef) (Machine, error)

	// List returns every machine the provider can see that carries this owner's
	// controller mark, plus any carrying our name grammar and somebody else's
	// mark -- the caller needs both to tell an orphan from a foreign resource.
	// It is the ownership sweep behind the orphan review page, so it must be
	// cheap: one call where the API allows one.
	List(ctx context.Context, owner Owner) ([]Machine, error)

	// Delete removes a machine. Deleting one that is already gone returns a zero
	// OperationRef and no error, because the desired end state has been reached.
	// It never verifies ownership itself -- the controller does that, against
	// the store and a fresh Inspect, before it calls this.
	Delete(ctx context.Context, ref MachineRef) (OperationRef, error)

	// Operation reports an asynchronous operation's progress. It is the whole of
	// restart recovery: a controller that comes back holding only a stored
	// OperationRef asks this rather than acting again. An unknown handle is
	// ErrNotFound, never a panic.
	Operation(ctx context.Context, op OperationRef) (OperationStatus, error)
}

// PowerController is implemented by providers that can stop a machine without
// destroying it. Optional, because a provider that can only create and delete is
// still useful and pretending otherwise would have the reconciler issue stops
// that silently do nothing.
//
// It is a separate interface found by type assertion rather than a method on
// Provider that answers "unsupported", for the reason backend.TimedCreator is:
// a method that is always going to refuse is a method the reconciler will keep
// calling.
type PowerController interface {
	Start(ctx context.Context, ref MachineRef) (OperationRef, error)
	Stop(ctx context.Context, ref MachineRef, graceful bool) (OperationRef, error)
}

// Bootstrapper is implemented by providers that can push the enrolment payload
// into the guest themselves. A provider that cannot declares
// Capabilities().Bootstrap = BootstrapMetadata, and the payload travels in the
// machine's creation metadata instead.
type Bootstrapper interface {
	Bootstrap(ctx context.Context, ref MachineRef, p Bootstrap) (OperationRef, error)
}

// Discoverer fills the guided form: the nodes, storages, networks and templates
// this credential can actually see. Optional because a provider with no such
// concepts should not have to fake one.
type Discoverer interface {
	Discover(ctx context.Context) (Discovery, error)
}

// Factory builds a Provider from one stored configuration row. The controller
// holds one Registry of factories and builds a provider per row, cached until
// the row's updated_at moves, so a credential change takes effect without a
// restart.
type Factory interface {
	Kind() store.ProviderKind
	// Describe is the capability set without an instance, for the page that
	// lists the kinds a build supports. It must agree with what New builds:
	// Registry.New refuses a factory whose description and provider disagree.
	Describe() Capabilities
	// Settings is the schema the configuration form, the validator and the
	// documentation share, so that a new setting cannot appear in one of the
	// three and be missing from the other two.
	Settings() []SettingSpec
	// Validate checks the non-secret answers offline: no network, no credential.
	// It is what the form runs as somebody types, which is why it may not dial
	// anything -- Preflight is the call that does.
	Validate(settings map[string]string) []config.Finding
	New(ctx context.Context, cfg Config) (Provider, error)
}

// DraftDiscoverer is a Factory that can answer what a credential sees before
// there is a provider to build: the address and the credential are enough to
// list what exists, and a form asks that question while the placement answers
// -- which New refuses to build without -- are still blank. A factory that
// does not implement it is asked through a fully built provider instead.
type DraftDiscoverer interface {
	DiscoverDraft(ctx context.Context, cfg Config) (Discovery, error)
}

// Config carries what a factory needs and nothing more. The credential arrives
// as plaintext, unsealed by the controller for the life of this call: the store
// keeps it sealed and unsealing is the caller's job, exactly as
// github.AppFactory takes an already-decrypted private key.
type Config struct {
	ProviderID string
	Owner      Owner
	Endpoint   string
	// Settings holds the non-secret answers, keyed by SettingSpec.Key.
	Settings map[string]string
	// Credential is PLAINTEXT. A provider keeps it for the life of the client
	// it builds, never writes it anywhere, and never logs it.
	Credential string
	CAPEM      string
	// Insecure records that certificate verification was turned off. It is
	// carried rather than refused because a homelab hypervisor's certificate is
	// usually its own, and the validator warns about it instead.
	Insecure  bool
	Deadlines Deadlines
	// DialContext, when set, opens every connection the provider makes to its
	// endpoint. The controller sets it for a provider reached over a private
	// connection -- a hypervisor on a home network with no address the
	// controller can route to -- and a provider that opens its own sockets
	// must use it rather than the network, with no proxy in between: the
	// endpoint's host is then a name for TLS to verify and nothing else. A
	// provider that ignores it would dial an address that does not exist from
	// where the controller is, and report the hypervisor down.
	DialContext func(ctx context.Context, network, address string) (net.Conn, error)
	// HTTPClient replaces the client a provider would build for itself. Tests
	// use it; production leaves it nil so that CAPEM, Insecure and DialContext
	// take effect, which a ready-made client cannot know about.
	HTTPClient *http.Client
	Logger     *slog.Logger
}

// BootstrapMode says how the enrolment payload reaches the guest.
type BootstrapMode string

const (
	// BootstrapGuestAgent means the provider writes the payload into a running
	// guest itself, and implements Bootstrapper.
	BootstrapGuestAgent BootstrapMode = "guest_agent"
	// BootstrapMetadata means the payload travels in the machine's creation
	// metadata, so it is readable by anyone who can read that metadata.
	BootstrapMetadata BootstrapMode = "metadata"
	// BootstrapNone means the provider cannot carry a payload at all; the image
	// has to arrive already able to enrol.
	BootstrapNone BootstrapMode = "none"
)

// Capabilities is what a provider can do, declared rather than discovered.
//
// The three Can* flags describe the optional interfaces above, and a provider
// whose flag and type disagree is refused when it is built: a flag that says
// yes where the type says no would have the reconciler call a method that is
// not there, and one that says no where the type says yes silently loses a
// capability an operator paid for.
type Capabilities struct {
	MinContract, MaxContract int
	Kind                     store.ProviderKind
	Label                    string
	Bootstrap                BootstrapMode
	CanStartStop             bool // true iff this Provider also implements PowerController
	CanDiscover              bool // ... Discoverer
	// CanMarkOwnership reports whether the provider can write our marks onto
	// the resource itself. A provider that cannot leaves Machine.Owner zero,
	// and the store stays the only record of who made it.
	CanMarkOwnership bool
	// AsyncOperations reports whether Create and Delete return an OperationRef
	// worth polling. A synchronous provider returns a zero one and sets this
	// false, so the reconciler does not poll a handle that will never move.
	AsyncOperations bool
	// CostUnit is what Machine.Cost is measured in, e.g. "machine-hour". Empty
	// when the provider has no opinion, which is not the same as free.
	CostUnit  string
	Deadlines Deadlines
	// EndpointExample is what an address for this kind looks like, scheme
	// and port included, so the form can show one and fill the port in for
	// somebody who typed only a host name.
	EndpointExample string
	// EndpointSource, CredentialSource and CASource say where the three
	// answers every kind is asked for are found -- the address, the
	// credential and the certificate -- in the provider's own console's
	// terms. The form's labels are the same for every kind; where to look
	// is not.
	EndpointSource   string
	CredentialSource string
	CASource         string
	// Guide is what has to exist before a provider of this kind can rent a
	// machine, in the order it is done: the credential to create, the image
	// to prepare, the block of identifiers to set aside. The form shows it
	// before it asks its first question, because every one of these is a
	// thing the operator does elsewhere, and a form that asks for the result
	// without saying how to get it is a form that gets abandoned.
	Guide []GuideStep
}

// GuideStep is one thing to do before a provider of some kind can be used.
type GuideStep struct {
	Title string
	// Detail says what to do and why, in prose the form shows as written.
	Detail string
	// Command is a shell snippet to copy, or empty when the step is done in
	// a console rather than a terminal.
	Command string
}

// Deadlines are the provider's own honest budgets. The controller applies the
// larger of these and the operator's configuration, so a provider may ask for
// longer but never for less supervision than the operator asked for.
type Deadlines struct {
	Call      time.Duration // one API request
	Allocate  time.Duration
	Create    time.Duration // the whole asynchronous create, not the request that starts it
	Bootstrap time.Duration
	Delete    time.Duration
}

// Owner is what a create stamps on the resource and what a delete verifies
// against the row. None of it is authenticated: anybody with provider access can
// forge it. That is why the store is the authority and this is tamper-evidence
// -- it catches a recycled identifier, another controller's resource, and one
// somebody made by hand, which are the three cases that actually happen.
type Owner struct {
	ControllerID string    // ctl_... -- the lease holder that created it
	ProviderID   string    // prv_...
	MachineID    string    // mach_...
	Fingerprint  string    // minted with the row, never reused
	CreatedAt    time.Time // the controller's clock, never the provider's
}

// Zero reports whether a resource carried no marks at all, which is a different
// thing from carrying somebody else's: one is an unmarked resource, the other is
// a resource with an owner, and only the second is evidence of a second fleet.
func (o Owner) Zero() bool {
	return o.ControllerID == "" && o.ProviderID == "" && o.MachineID == "" && o.Fingerprint == ""
}

// Matches reports whether marks read back from a resource are the ones we wrote.
//
// It compares the controller, the machine and the fingerprint, and the
// fingerprint in constant time: the mark is readable by anybody with audit
// rights on the infrastructure, so nothing here is a secret, but a comparison
// that leaks its answer through timing is a habit worth not having in the one
// function that stands between a sweep and a delete.
func (o Owner) Matches(want Owner) bool {
	if o.ControllerID != want.ControllerID || o.MachineID != want.MachineID {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(o.Fingerprint), []byte(want.Fingerprint)) == 1
}

// MachineRef is the durable identity of one machine. Everything in it is minted
// by Allocate and written to the row before any call that could create anything.
type MachineRef struct {
	// Zone is the node or region the machine lives in. Empty for a provider
	// with no such concept.
	Zone string
	// ID is the provider's native identity. Empty when only Name is knowable
	// before the resource exists, in which case List must find it by Name.
	ID string
	// Name is ours, minted by store.NewMachineName. It is unique per provider
	// and is the primary ownership mark, because it is the one thing a
	// cluster-wide sweep can filter on without reading every resource's config.
	Name string
}

// Zero reports whether a ref names nothing at all. A ref with only a Name is
// not zero: that is the shape a provider returns when identity is only knowable
// after creation.
func (r MachineRef) Zero() bool { return r.Zone == "" && r.ID == "" && r.Name == "" }

// OpKind says which operation a handle belongs to, so a controller that comes
// back holding a handle knows what finishing it means.
type OpKind string

const (
	OpCreate    OpKind = "create"
	OpStart     OpKind = "start"
	OpStop      OpKind = "stop"
	OpBootstrap OpKind = "bootstrap"
	OpDelete    OpKind = "delete"
)

// OperationRef is a provider-side handle for asynchronous work, durable across a
// controller restart. That durability is the whole point: the reconciler stores
// the handle on the machine row before it considers the call done, so a
// controller that comes back holding nothing but the handle asks what happened
// rather than doing the work again. A good handle encodes everything needed to
// find the task -- the zone included -- because nothing else about it is stored.
type OperationRef struct {
	Kind   OpKind
	Handle string // opaque to everything but the provider that issued it
}

// Zero reports whether there is nothing to follow: a synchronous provider's
// answer, and a delete of a resource that was already gone.
func (o OperationRef) Zero() bool { return o.Handle == "" }

// OperationStatus is one asynchronous operation's progress. Done and OK are
// separate because "finished" and "worked" are different questions, and a
// caller that conflated them would treat a failed create as a machine.
type OperationStatus struct {
	Done bool
	OK   bool
	// Detail is the provider's own completion text, shown verbatim to an
	// operator: it is usually the only sentence that says which storage was
	// full or which privilege was missing.
	Detail string
}

// Phase is the provider's view of one machine. It is coarse on purpose: the
// reconciler wants to know whether the resource exists and whether it is
// running, and every finer distinction a particular provider offers is detail
// for an operator rather than an input to a decision.
type Phase string

const (
	// PhaseUnknown is a machine we could not classify. It never authorises a
	// delete and never reads as gone, because "we could not tell" and "it is
	// not there" lead to opposite decisions.
	PhaseUnknown  Phase = "unknown"
	PhaseCreating Phase = "creating"
	PhaseStopped  Phase = "stopped"
	PhaseRunning  Phase = "running"
	PhaseDeleting Phase = "deleting"
	// PhaseGone is the provider saying the resource does not exist. It is the
	// only phase that lets a delete be recorded as complete.
	PhaseGone Phase = "gone"
)

// ParsePhase reads a phase a provider reported, answering PhaseUnknown for
// anything this build does not recognise -- a phase from a newer contract
// included. The alternative, carrying the unrecognised string through, would
// let a comparison somewhere downstream decide something about it.
func ParsePhase(s string) Phase {
	switch Phase(s) {
	case PhaseCreating, PhaseStopped, PhaseRunning, PhaseDeleting, PhaseGone:
		return Phase(s)
	}
	return PhaseUnknown
}

// Known reports whether this phase is one the contract defines.
func (p Phase) Known() bool { return ParsePhase(string(p)) == p && p != PhaseUnknown }

// Gone reports whether the provider is sure the resource no longer exists. Only
// PhaseGone is: an unknown phase is a machine we failed to read, and reading it
// as gone would let a delete be recorded complete on a machine still running.
func (p Phase) Gone() bool { return p == PhaseGone }

// AuthorisesDelete reports whether a delete may be issued against a machine in
// this phase. An unknown phase does not, which is the forward-compatibility rule
// that costs a stuck machine and saves somebody else's.
func (p Phase) AuthorisesDelete() bool {
	switch p {
	case PhaseCreating, PhaseStopped, PhaseRunning, PhaseDeleting:
		return true
	}
	return false
}

// Machine is one machine as the provider sees it now. It carries no timestamp
// the provider invented: a provider's clock is never authoritative, for the
// reason the controller already discards an agent's own sample time. The
// controller stamps observed_at itself.
type Machine struct {
	Ref   MachineRef
	Phase Phase
	// Owner is the marks as read back from the resource, zero when it carries
	// none. It is never the marks the caller supplied, because a value echoed
	// back proves nothing about what is written on the machine.
	Owner Owner
	// Locked is non-empty when another operation holds the resource: a reason
	// to wait, not a failure, and not a reason to create a second machine.
	Locked string
	// Address is where the guest will reach the controller from, when known.
	Address string
	// Detail is one operator-facing sentence.
	Detail string
	// Cost is per Capabilities().CostUnit, zero when the provider has no
	// opinion.
	Cost float64
}

// MachineSpec is what to build. It carries NO provider credential and has no
// field one could be put in: the guest gets a single-use join token and nothing
// else, and the type is the enforcement.
type MachineSpec struct {
	// Name is the machine's name as Zoomies will know it, minted by
	// store.NewMachineName before anything is created.
	Name  string
	Owner Owner
	Shape Shape
	// Bootstrap is rendered by the controller: files and commands only.
	Bootstrap Bootstrap
}

// Shape is the one machine shape a provider offers, as the operator configured
// it. Placement carries the provider's own answers -- which node, which storage,
// which template -- keyed by SettingSpec.Key, so that a provider with concepts
// this package has never heard of needs no field here and no migration.
type Shape struct {
	CPUs      float64
	MemoryMB  int64
	DiskMB    int64
	Platform  store.Platform
	Placement map[string]string
}

// Bootstrap is what goes inside the guest: files, and the commands that install
// them. Nothing here is a provider credential.
//
// Commands are argv arrays rather than shell lines, and deliberately so: a
// payload that is never pasted into a shell has no quoting to get wrong and no
// injection class to police.
type Bootstrap struct {
	Files    []File
	Commands [][]string
}

// File is one file to write into the guest. Mode is carried because some
// transports have no way to set one, and the enrolment file must not be
// world-readable -- a provider that cannot set a mode writes the file and then
// runs a command that fixes it.
type File struct {
	Path    string
	Mode    uint32
	Content []byte
}

// SettingKind is how one setting is asked for, so the form, the CLI and the
// documentation render it the same way.
type SettingKind string

const (
	SettingText   SettingKind = "text"
	SettingNumber SettingKind = "number"
	SettingBool   SettingKind = "bool"
	SettingChoice SettingKind = "choice"
	SettingList   SettingKind = "list"
	// SettingSecret is never echoed back to a client and never written to an
	// audit row.
	SettingSecret SettingKind = "secret"
)

// SettingSpec is one answer a provider needs, described once so that the form,
// the validator and the documentation cannot drift apart.
type SettingSpec struct {
	Key      string
	Label    string
	Kind     SettingKind
	Required bool
	// Advanced puts the setting behind a disclosure, because a form that asks
	// eleven questions to do the common thing gets abandoned.
	Advanced bool
	// Help is one operator-facing sentence.
	Help string
	// Consequence says what choosing it means, in the voice the pool form
	// already uses for a choice that costs something.
	Consequence string
	// Discovers names the Discovery list that fills the choices, e.g. "nodes",
	// so a provider that implements Discoverer offers a menu rather than asking
	// somebody to type an identifier they have to go and look up.
	Discovers string
	Default   string
	// Source says where the answer is found when discovery cannot fill it in:
	// which page of the provider's own console, or which command on one of
	// its machines. Help says what the setting is; this says where to look.
	Source string
}

// Report is a preflight result. Its findings are config.Finding so the problems
// drawer, the startup print and the setup wizard render them with no
// translation, and so that "what is wrong with this provider" reads the same as
// "what is wrong with this configuration".
type Report struct {
	// Reachable is whether we got an answer at all. It is separate from the
	// findings because a provider that cannot be reached has one problem, not
	// eleven, and listing the eleven checks we could not run would bury it.
	Reachable bool
	// Version is the provider's own version string, kept for the qualification
	// record: "it worked" is worth little without "against what".
	Version  string
	Findings []config.Finding
}

// OK reports whether preflight found nothing that stops this provider being
// used. Warnings do not: they weaken the posture and say so, exactly as they do
// at startup.
func (r Report) OK() bool {
	if !r.Reachable {
		return false
	}
	for _, f := range r.Findings {
		if f.Severity == config.SeverityError {
			return false
		}
	}
	return true
}

// Discovery is what a credential can actually see, for the guided form. The
// lists are named for the concepts the first providers have; a provider with no
// such concept leaves them empty rather than inventing one.
type Discovery struct {
	Nodes     []Choice
	Storages  []Choice
	Bridges   []Choice
	Templates []Choice
}

// Choice is one option in a guided form. Consequence is what picking it means,
// because a list of identifiers with no consequences is a list somebody guesses
// at.
type Choice struct{ Value, Label, Consequence string }

package provider

import (
	"context"
	"errors"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/store"
)

// The contract is only a contract for as long as it is one package's worth of
// vocabulary. Once it imports the controller, the scheduler or a provider of
// its own, "write a provider" stops meaning "write a leaf package" and a second
// provider becomes a change to the middle of the system.
func TestTheProviderContractImportsNothingBeyondItsDomainTypes(t *testing.T) {
	pkg, err := build.ImportDir(".", 0)
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	want := map[string]bool{
		"github.com/eyupio/zoomies/internal/store":  true,
		"github.com/eyupio/zoomies/internal/config": true,
	}
	got := map[string]bool{}
	for _, path := range pkg.Imports {
		if isStdlib(path) {
			continue
		}
		got[path] = true
	}
	for path := range got {
		if !want[path] {
			t.Errorf("internal/provider imports %s; the contract may only speak the domain types", path)
		}
	}
	for path := range want {
		if !got[path] {
			t.Errorf("internal/provider no longer imports %s; if that is deliberate, this list is what has to change", path)
		}
	}
}

func isStdlib(path string) bool {
	first, _, _ := strings.Cut(path, "/")
	return !strings.Contains(first, ".")
}

// A contract that has learned one hypervisor's words has stopped being one: the
// second provider would then be written against the first provider's vocabulary
// rather than against the contract, which is exactly the shape this package
// exists to avoid.
func TestTheContractNamesNothingProxmoxSpecific(t *testing.T) {
	// Comments count, not only code. A type named after one provider is caught
	// by review; a comment explaining the contract in one provider's terms is
	// what actually teaches the next author the wrong vocabulary.
	banned := regexp.MustCompile(`(?i)proxmox|\bpve\b|vmid|upid|qemu`)

	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatalf("reading this package: %v", err)
	}
	files := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		files++
		fset := token.NewFileSet()
		file, err := parser.ParseFile(fset, name, nil, parser.ParseComments|parser.SkipObjectResolution)
		if err != nil {
			t.Fatalf("parsing %s: %v", name, err)
		}
		report := func(pos token.Pos, what, text string) {
			if m := banned.FindString(text); m != "" {
				t.Errorf("%s: %s names %q, which belongs to one provider and not to the contract",
					fset.Position(pos), what, m)
			}
		}
		ast.Inspect(file, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.Ident:
				report(x.Pos(), "identifier "+x.Name, x.Name)
			case *ast.BasicLit:
				if x.Kind == token.STRING {
					report(x.Pos(), "string literal", x.Value)
				}
			}
			return true
		})
		for _, group := range file.Comments {
			for _, c := range group.List {
				report(c.Pos(), "comment", c.Text)
			}
		}
	}
	if files == 0 {
		t.Fatal("no source files were scanned at all; the walk is wrong, not the contract")
	}
}

// Each optional capability is its own interface, found by type assertion. A
// method on Provider that a provider without the capability had to implement
// would be a method that always refuses -- and a method that always refuses is
// one the reconciler keeps calling.
func TestEveryOptionalCapabilityIsItsOwnInterface(t *testing.T) {
	required := reflect.TypeOf((*Provider)(nil)).Elem()
	for _, name := range []string{"Start", "Stop", "Bootstrap", "Discover"} {
		if _, ok := required.MethodByName(name); ok {
			t.Errorf("Provider has %s; an optional capability on the required interface has to be answered by every provider", name)
		}
	}
	for _, tc := range []struct {
		iface reflect.Type
		want  []string
	}{
		{reflect.TypeOf((*PowerController)(nil)).Elem(), []string{"Start", "Stop"}},
		{reflect.TypeOf((*Bootstrapper)(nil)).Elem(), []string{"Bootstrap"}},
		{reflect.TypeOf((*Discoverer)(nil)).Elem(), []string{"Discover"}},
	} {
		if got := tc.iface.NumMethod(); got != len(tc.want) {
			t.Errorf("%s has %d methods, want %d", tc.iface, got, len(tc.want))
		}
		for _, name := range tc.want {
			if _, ok := tc.iface.MethodByName(name); !ok {
				t.Errorf("%s has no %s", tc.iface, name)
			}
		}
	}
}

// The marks are tamper-evidence, and what they have to catch is a recycled
// identifier: the same machine ID at the same provider, made by somebody else
// after ours was destroyed. The fingerprint is the half that settles that.
func TestOwnerMatchesOnlyWhenEveryMarkAgrees(t *testing.T) {
	ours := Owner{ControllerID: "ctl_1", ProviderID: "prv_1", MachineID: "mach_1", Fingerprint: "abcdef"}
	for _, tc := range []struct {
		name string
		read Owner
		want bool
	}{
		{"the marks we wrote", ours, true},
		{"another controller's machine", Owner{ControllerID: "ctl_2", MachineID: "mach_1", Fingerprint: "abcdef"}, false},
		{"a recycled identifier with a fresh fingerprint", Owner{ControllerID: "ctl_1", MachineID: "mach_1", Fingerprint: "fedcba"}, false},
		{"another machine of ours", Owner{ControllerID: "ctl_1", MachineID: "mach_2", Fingerprint: "abcdef"}, false},
		{"a resource wearing no marks at all", Owner{}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.read.Matches(ours); got != tc.want {
				t.Errorf("Matches = %t, want %t", got, tc.want)
			}
		})
	}
	if !(Owner{}).Zero() {
		t.Error("an owner with no marks is not zero; an unmarked resource and a foreign one would be treated alike")
	}
	if ours.Zero() {
		t.Error("marks we wrote read as no marks at all")
	}
}

// A ref carrying only a name is the shape a provider returns when its native
// identity is only knowable after creation. Reading it as "no identity" would
// throw away the one thing that makes such a provider recoverable.
func TestARefCarryingOnlyANameIsStillAnIdentity(t *testing.T) {
	if (MachineRef{Name: "zoomies-mach-abc"}).Zero() {
		t.Error("a ref with a name reads as zero")
	}
	if !(MachineRef{}).Zero() {
		t.Error("a ref naming nothing does not read as zero")
	}
	if !(OperationRef{Kind: OpCreate}).Zero() {
		t.Error("an operation with no handle does not read as zero; a synchronous provider's answer would be polled forever")
	}
}

// The forward-compatibility rule, in the direction that costs money if it is
// wrong: what we cannot read, we leave alone.
func TestAPhaseThisBuildDoesNotKnowIsNeitherGoneNorDeletable(t *testing.T) {
	for _, tc := range []struct {
		in                     string
		want                   Phase
		gone, authorisesDelete bool
	}{
		{"running", PhaseRunning, false, true},
		{"stopped", PhaseStopped, false, true},
		{"creating", PhaseCreating, false, true},
		{"deleting", PhaseDeleting, false, true},
		{"gone", PhaseGone, true, false},
		{"unknown", PhaseUnknown, false, false},
		{"hibernating-from-a-later-contract", PhaseUnknown, false, false},
		{"", PhaseUnknown, false, false},
	} {
		t.Run(tc.in, func(t *testing.T) {
			got := ParsePhase(tc.in)
			if got != tc.want {
				t.Fatalf("ParsePhase(%q) = %q, want %q", tc.in, got, tc.want)
			}
			if got.Gone() != tc.gone {
				t.Errorf("%q.Gone() = %t, want %t", got, got.Gone(), tc.gone)
			}
			if got.AuthorisesDelete() != tc.authorisesDelete {
				t.Errorf("%q.AuthorisesDelete() = %t, want %t", got, got.AuthorisesDelete(), tc.authorisesDelete)
			}
		})
	}
}

// A preflight that could not reach the provider has one problem, not none: a
// report with no findings and no answer must not read as "everything is fine".
func TestAPreflightThatReachedNothingIsNotOK(t *testing.T) {
	for _, tc := range []struct {
		name string
		r    Report
		want bool
	}{
		{"reached, nothing to fix", Report{Reachable: true}, true},
		{"reached, a warning", Report{Reachable: true, Findings: []config.Finding{{Severity: config.SeverityWarning}}}, true},
		{"reached, something to fix", Report{Reachable: true, Findings: []config.Finding{{Severity: config.SeverityError}}}, false},
		{"never reached", Report{}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.r.OK(); got != tc.want {
				t.Errorf("OK() = %t, want %t", got, tc.want)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// The registry
// ---------------------------------------------------------------------------

// lyingFactory describes one thing and builds another. Every field is what a
// real factory would get right, which is the point: the disagreement is the
// only thing under test.
type lyingFactory struct {
	caps  Capabilities
	build func() Provider
}

func (f lyingFactory) Kind() store.ProviderKind { return store.ProviderFake }
func (f lyingFactory) Describe() Capabilities   { return f.caps }
func (f lyingFactory) Settings() []SettingSpec  { return nil }
func (f lyingFactory) Validate(map[string]string) []config.Finding {
	return nil
}
func (f lyingFactory) New(context.Context, Config) (Provider, error) { return f.build(), nil }

func fakeCaps(opts ...FakeOption) Capabilities { return NewFake(opts...).Capabilities() }

// A version mismatch is an operator's problem to solve, so the refusal has to
// name both numbers and say which half to upgrade. "Unsupported" alone sends
// somebody to the release notes of the wrong side.
func TestARegistryRefusesAFactoryFromAnotherContract(t *testing.T) {
	for _, tc := range []struct {
		name     string
		min, max int
		want     string
	}{
		{"a provider written for a later contract", ContractVersion + 1, ContractVersion + 2, "upgrade Zoomies"},
		{"a provider written for an earlier one", ContractVersion - 2, ContractVersion - 1, "upgrade the provider"},
		{"a range containing nothing", 2, 1, "contains nothing"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			caps := fakeCaps()
			caps.MinContract, caps.MaxContract = tc.min, tc.max
			_, err := NewRegistry(lyingFactory{caps: caps, build: func() Provider { return NewFake() }})
			if !errors.Is(err, ErrUnsupported) {
				t.Fatalf("NewRegistry = %v, want an unsupported-contract refusal", err)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("the refusal is %q; it does not say %q, so it does not say what to do", err, tc.want)
			}
		})
	}
}

// A provider that claims a capability its type does not have would have the
// reconciler call a method that is not there; one that hides a capability it
// does have gets a machine deleted and bought again where a stop would have
// done. Both are caught where the provider is built, not mid-create.
func TestARegistryRefusesAProviderWhoseCapabilitiesDisagreeWithItsType(t *testing.T) {
	for _, tc := range []struct {
		name  string
		caps  Capabilities
		build func() Provider
		want  string
	}{
		{
			name:  "says it can stop machines and cannot",
			caps:  fakeCaps(),
			build: func() Provider { return NewFake(FakeWithoutPower()) },
			want:  "CanStartStop",
		},
		{
			name:  "can stop machines and says it cannot",
			caps:  fakeCaps(FakeWithoutPower()),
			build: func() Provider { return NewFake() },
			want:  "CanStartStop",
		},
		{
			name:  "says it can fill the form and cannot",
			caps:  fakeCaps(),
			build: func() Provider { return NewFake(FakeWithoutDiscovery()) },
			want:  "CanDiscover",
		},
		{
			name:  "claims to push the payload into the guest and cannot",
			caps:  fakeCaps(),
			build: func() Provider { return NewFake(FakeWithoutBootstrap()) },
			want:  "bootstrap mode",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r, err := NewRegistry(lyingFactory{caps: tc.caps, build: tc.build})
			if err != nil {
				t.Fatalf("NewRegistry: %v", err)
			}
			_, err = r.New(context.Background(), store.ProviderFake, Config{})
			if err == nil {
				t.Fatal("the registry built a provider whose capabilities do not match its type")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("the refusal is %q; it does not name %q", err, tc.want)
			}
		})
	}
}

// The factory's description is what the "what can this build do" page renders
// without building anything, so a description that disagrees with the provider
// is a promise made to an operator that the fleet then breaks.
func TestARegistryRefusesAFactoryThatDescribesOneProviderAndBuildsAnother(t *testing.T) {
	// Both halves are internally consistent; only the two sides disagree.
	r, err := NewRegistry(lyingFactory{
		caps:  fakeCaps(FakeWithoutPower()),
		build: func() Provider { return NewFake(FakeWithoutPower()) },
	})
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	if _, err := r.New(context.Background(), store.ProviderFake, Config{}); err != nil {
		t.Fatalf("a factory that agrees with itself was refused: %v", err)
	}

	r, err = NewRegistry(lyingFactory{
		caps:  fakeCaps(FakeWithoutDiscovery()),
		build: func() Provider { return NewFake() },
	})
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	// The instance is self-consistent, so only the comparison against the
	// description can catch this one.
	if _, err := r.New(context.Background(), store.ProviderFake, Config{}); err == nil {
		t.Fatal("a factory described one provider and built another, and the registry accepted it")
	}
}

func TestARegistryHasNoFactoryForAKindThisBuildCannotSpeak(t *testing.T) {
	r, err := NewRegistry(NewFakeFactory())
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	if _, err := r.Get(store.ProviderProxmox); !errors.Is(err, ErrUnsupported) {
		t.Errorf("Get for an unregistered kind = %v, want unsupported", err)
	}
	if _, err := r.New(context.Background(), store.ProviderProxmox, Config{}); !errors.Is(err, ErrUnsupported) {
		t.Errorf("New for an unregistered kind = %v, want unsupported", err)
	}
	if got := r.Kinds(); len(got) != 1 || got[0] != store.ProviderFake {
		t.Errorf("Kinds() = %v, want just the fake", got)
	}
	if _, err := r.Get(store.ProviderFake); err != nil {
		t.Errorf("Get for the registered kind: %v", err)
	}
}

// Two factories for one kind means one of them is never reached, and which one
// depends on argument order -- a bug that only shows up as "the provider did
// not behave like the code I was reading".
func TestARegistryRefusesTwoFactoriesForOneKind(t *testing.T) {
	if _, err := NewRegistry(NewFakeFactory(), NewFakeFactory()); err == nil {
		t.Fatal("two factories for one kind were accepted")
	}
	if _, err := NewRegistry(nil, NewFakeFactory()); err != nil {
		t.Fatalf("a nil factory should be skipped, not refused: %v", err)
	}
}

// The registry is what the controller holds, so its answers have to be stable:
// a list that reshuffles between requests makes a page that flickers.
func TestARegistryListsItsKindsInAStableOrder(t *testing.T) {
	r, err := NewRegistry(NewFakeFactory())
	if err != nil {
		t.Fatalf("NewRegistry: %v", err)
	}
	first := r.Kinds()
	for range 5 {
		if got := r.Kinds(); !reflect.DeepEqual(got, first) {
			t.Fatalf("Kinds() = %v then %v", first, got)
		}
	}
}

// The fake's own factory is the one every other package's tests will build a
// registry from, so it has to be a well-formed factory in its own right.
func TestTheFakeFactoryBuildsWhatItDescribes(t *testing.T) {
	for _, opts := range [][]FakeOption{
		nil,
		{FakeWithoutPower()},
		{FakeWithoutBootstrap()},
		{FakeWithoutDiscovery()},
		{FakeWithoutPower(), FakeWithoutBootstrap(), FakeWithoutDiscovery()},
	} {
		r, err := NewRegistry(NewFakeFactory(opts...))
		if err != nil {
			t.Fatalf("NewRegistry: %v", err)
		}
		p, err := r.New(context.Background(), store.ProviderFake, Config{Deadlines: Deadlines{Call: time.Second}})
		if err != nil {
			t.Fatalf("New: %v", err)
		}
		if err := CheckCapabilities(p); err != nil {
			t.Errorf("%v", err)
		}
	}
	if got := NewFakeFactory().Validate(map[string]string{}); len(got) != 1 {
		t.Errorf("Validate of an empty settings map returned %d findings, want the missing zone", len(got))
	}
	if got := NewFakeFactory().Validate(map[string]string{"zone": "zone-a"}); len(got) != 0 {
		t.Errorf("Validate of a complete settings map returned %v", got)
	}
	if len(NewFakeFactory().Settings()) == 0 {
		t.Error("the factory offers no settings at all; the form would have nothing to render")
	}
}

// Belt and braces on the layout: the suite lives in the production package so
// that a provider's own test is one line, and a file that moved would only be
// noticed when somebody tried to write the second provider.
func TestTheConformanceSuiteShipsWithThePackage(t *testing.T) {
	if _, err := os.Stat(filepath.Join(".", "conformance.go")); err != nil {
		t.Fatalf("conformance.go is not in the production package: %v", err)
	}
}

package proxmox

// Bootstrap: how the enrolment payload gets inside a machine.
//
// It goes through the QEMU guest agent, and the reason is not preference. The
// usual way to hand a guest arbitrary user-data is
// cicustom=user=<storage>:snippets/<file>, and that cannot be driven from the
// API at all: the storage upload endpoint accepts content of iso, vztmpl or
// import, and snippets is not in the enum. Every tool that uses cicustom places
// the file over SSH, which would mean Zoomies holding shell credentials to a
// hypervisor -- a far larger trust boundary than a scoped API token, and one
// this integration is not willing to ask for. The cloud-init fields that are
// settable through the API carry no arbitrary user-data.
//
// What the guest agent buys, beyond being reachable at all:
//
//   - The credential never enters the machine's metadata, so it is not readable
//     by a Proxmox user holding VM.Config.Cloudinit or VM.Audit, and never
//     lands in a seed image on shared storage.
//   - exec-status returns the guest's own exit code and standard error, which
//     becomes the machine's failure reason. "The agent did not install" is not
//     something anybody can act on; "zoomies-agent.service not found" is.
//
// What it costs is two privileges -- VM.GuestAgent.FileWrite and
// VM.GuestAgent.Unrestricted -- and a template that ships qemu-guest-agent.
// Preflight names both, because a template prepared without them produces
// machines that boot, cost money and never join.
//
// Nothing here builds a shell command line. Commands are argv arrays the whole
// way down, so there is no quoting to get wrong and no injection class to
// police.

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
)

const (
	// guestAgentPollInterval is how often a guest that has just started is
	// asked whether its agent is up. A guest answers within seconds of
	// finishing its boot, and giving up on the first refusal would spend a
	// whole reconcile backoff on a machine that was two seconds from ready.
	guestAgentPollInterval = 2 * time.Second
	// guestExecPollInterval is how often a command running inside the guest is
	// asked whether it has finished. The commands here are a chmod and a
	// systemctl, which is to say milliseconds.
	guestExecPollInterval = 500 * time.Millisecond
	// maxAgentFileBytes is what the API will carry in one file-write. Checking
	// it here turns "400: value is too long" into a sentence naming the file.
	maxAgentFileBytes = 61440
)

// chmodCommand is the program that fixes a file's mode. It is an absolute path
// because there is no shell in this path to search one.
const chmodCommand = "/bin/chmod"

// execHandlePrefix marks an operation handle that is a process inside a guest
// rather than a cluster task. The guest agent has no UPID to give -- it returns
// a process id, which means nothing without the node and the guest it belongs
// to -- so the handle carries all three. It is durable in the only sense that
// matters here: a controller that restarts can still ask what the command did.
const execHandlePrefix = "guest-exec:"

// Bootstrap writes the enrolment payload into a running guest and starts the
// agent.
//
// The handle it returns follows the last command, which is the one that starts
// the agent and the only one whose outcome a machine's life depends on. The
// preparation before it -- the files, and the chmod each one needs -- is
// awaited here, because a handle for each would need somewhere to be stored and
// there is one column for one handle.
func (p *Provider) Bootstrap(ctx context.Context, ref provider.MachineRef, payload provider.Bootstrap) (provider.OperationRef, error) {
	node, vmid, err := p.locate(ref, "install the agent inside a machine")
	if err != nil {
		return provider.OperationRef{}, err
	}
	if _, set := ctx.Deadline(); !set {
		// This is the one call here that waits for something, so it is the one
		// that needs a floor under it: a caller that set no deadline would
		// otherwise have this poll a guest that is never going to answer for
		// as long as the process lives. The budget is this provider's own.
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, p.caps.Deadlines.Bootstrap)
		defer cancel()
	}
	if err := p.awaitGuestAgent(ctx, node, vmid); err != nil {
		return provider.OperationRef{}, err
	}

	for _, f := range payload.Files {
		if len(f.Content) > maxAgentFileBytes {
			return provider.OperationRef{}, &provider.Error{
				Kind: provider.FailureConfig, Op: "write a file inside a machine", Ref: vmRef(node, vmid),
				Message: fmt.Sprintf("%s is %d bytes and the guest agent carries at most %d", f.Path, len(f.Content), maxAgentFileBytes),
				Remedy:  "shorten what goes into the guest; a certificate bundle with everything in it is the usual cause",
			}
		}
		if err := p.client.AgentFileWrite(ctx, node, vmid, f.Path, f.Content); err != nil {
			return provider.OperationRef{}, err
		}
		if f.Mode == 0 {
			continue
		}
		// file-write has no mode parameter, so the file lands at whatever the
		// guest agent's umask gives it -- world-readable, on a file holding a
		// join token. The chmod goes immediately after each write rather than
		// once at the end, because the window between the two is the only time
		// that credential is readable by anything else on the machine.
		if err := p.runInGuest(ctx, node, vmid, []string{chmodCommand, fmt.Sprintf("%04o", f.Mode), f.Path}); err != nil {
			return provider.OperationRef{}, err
		}
	}

	if len(payload.Commands) == 0 {
		// The files are all there was. There is nothing to follow, and the
		// caller reads that as a bootstrap that is done.
		return provider.OperationRef{}, nil
	}
	for _, argv := range payload.Commands[:len(payload.Commands)-1] {
		if err := p.runInGuest(ctx, node, vmid, argv); err != nil {
			return provider.OperationRef{}, err
		}
	}
	last := payload.Commands[len(payload.Commands)-1]
	pid, err := p.client.AgentExec(ctx, node, vmid, last, "")
	if err != nil {
		return provider.OperationRef{}, err
	}
	return provider.OperationRef{Kind: provider.OpBootstrap, Handle: execHandle(node, vmid, pid)}, nil
}

// awaitGuestAgent waits for the guest to answer, which is how a machine says it
// has booted far enough to be given its enrolment.
//
// It waits rather than reporting the first refusal because the two are
// indistinguishable from outside: a guest thirty seconds into its boot and a
// template with no agent installed both answer "QEMU guest agent is not
// running". The context bounds the wait, and when it runs out the last refusal
// is what is reported -- with the remedy that is nearly always right.
func (p *Provider) awaitGuestAgent(ctx context.Context, node string, vmid int) error {
	timer := time.NewTimer(guestAgentPollInterval)
	defer timer.Stop()
	for {
		err := p.client.AgentPing(ctx, node, vmid)
		if err == nil {
			return nil
		}
		if ctx.Err() != nil {
			return p.guestAgentSilent(node, vmid, err)
		}
		timer.Reset(guestAgentPollInterval)
		select {
		case <-timer.C:
		case <-ctx.Done():
			return p.guestAgentSilent(node, vmid, err)
		}
	}
}

// guestAgentSilent is a guest that never answered, said in the terms an
// operator can act on. It is a refusal rather than an unknown outcome: nothing
// was asked of the machine, so nothing can have happened to it.
func (p *Provider) guestAgentSilent(node string, vmid int, cause error) error {
	if errors.Is(cause, context.Canceled) {
		return cause
	}
	return &provider.Error{
		Kind: provider.FailureRefused, Op: "reach the guest agent", Ref: vmRef(node, vmid),
		Message: fmt.Sprintf("VM %d on %s did not answer its guest agent", vmid, node),
		Remedy: "the enrolment is written through the QEMU guest agent: check that the template has qemu-guest-agent installed and enabled, " +
			"and that the machine has agent: enabled=1",
		Cause: cause,
	}
}

// runInGuest runs one command inside the guest and waits for it, turning a
// non-zero exit into the guest's own account of what went wrong.
func (p *Provider) runInGuest(ctx context.Context, node string, vmid int, argv []string) error {
	pid, err := p.client.AgentExec(ctx, node, vmid, argv, "")
	if err != nil {
		return err
	}
	timer := time.NewTimer(guestExecPollInterval)
	defer timer.Stop()
	for {
		status, err := p.execStatus(ctx, node, vmid, pid)
		if err != nil {
			return err
		}
		if status.Done {
			if status.OK {
				return nil
			}
			return &provider.Error{
				Kind: provider.FailureRefused, Op: "run " + argv[0] + " inside a machine", Ref: vmRef(node, vmid),
				Message: status.Detail,
				Remedy:  "the message is the guest's own; what it names is in the template rather than in this fleet",
			}
		}
		timer.Reset(guestExecPollInterval)
		select {
		case <-timer.C:
		case <-ctx.Done():
			return &provider.Error{
				Kind: provider.FailureRefused, Op: "run " + argv[0] + " inside a machine", Ref: vmRef(node, vmid),
				Message: fmt.Sprintf("%s was still running inside VM %d when this call ran out of time", argv[0], vmid),
				Remedy:  "nothing is forced; the machine is looked at again on the next pass",
				Cause:   ctx.Err(),
			}
		}
	}
}

// execStatus reports what a command inside a guest is doing, and is where the
// guest's own standard error becomes the sentence a machine's page carries.
//
// A refusal is answered as not-found rather than as a failure, and deliberately
// so: the guest agent reaps a process the moment its status is read, so a
// handle asked about twice -- a controller that restarted between reading the
// answer and recording it -- is a process the agent has genuinely forgotten.
// Not-found sends the caller to look at the machine, which for a bootstrap
// means asking whether the credential was spent; a failure would have it retry
// a poll that can never succeed again. A cluster that could not be reached is
// not that, and is passed through so the poll is simply tried again.
func (p *Provider) execStatus(ctx context.Context, node string, vmid, pid int) (provider.OperationStatus, error) {
	status, err := p.client.AgentExecStatus(ctx, node, vmid, pid)
	if err != nil {
		switch provider.KindOf(err) {
		case provider.FailureUnreachable, provider.FailureAmbiguous:
			return provider.OperationStatus{}, err
		}
		if errors.Is(err, context.Canceled) {
			return provider.OperationStatus{}, err
		}
		return provider.OperationStatus{}, &provider.Error{
			Kind: provider.FailureNotFound, Op: "read what a command inside a machine did", Ref: vmRef(node, vmid),
			Message: fmt.Sprintf("the guest agent on VM %d no longer knows about process %d", vmid, pid),
			Cause:   err,
		}
	}
	if !bool(status.Exited) {
		return provider.OperationStatus{Detail: "installing the agent inside the machine"}, nil
	}
	if status.ExitCode == 0 && status.Signal == 0 {
		return provider.OperationStatus{Done: true, OK: true, Detail: guestOutput(status)}, nil
	}
	return provider.OperationStatus{Done: true, Detail: guestFailure(status)}, nil
}

// guestFailure is the failure as the guest told it: how it ended, and what it
// wrote. It is shown verbatim, because the guest's own sentence about a missing
// unit is worth more than ours about an exit code.
func guestFailure(status AgentExecStatus) string {
	var b strings.Builder
	if status.Signal != 0 {
		b.WriteString("killed by signal " + strconv.Itoa(status.Signal.Int()))
	} else {
		b.WriteString("exited " + strconv.Itoa(status.ExitCode.Int()))
	}
	if said := guestOutput(status); said != "" {
		b.WriteString(": ")
		b.WriteString(said)
	}
	return b.String()
}

// guestOutput is what the command wrote, standard error first: a program that
// failed says why there, and its standard output is usually the part that
// succeeded.
func guestOutput(status AgentExecStatus) string {
	for _, said := range []string{status.ErrData, status.OutData} {
		if said = strings.TrimSpace(said); said != "" {
			return said
		}
	}
	return ""
}

// execHandle renders a handle for a process inside a guest.
func execHandle(node string, vmid, pid int) string {
	return fmt.Sprintf("%s%s:%d:%d", execHandlePrefix, node, vmid, pid)
}

// parseExecHandle reads one back, reporting whether it was one at all: anything
// else is a cluster task, and Operation asks the cluster about it instead.
func parseExecHandle(handle string) (node string, vmid, pid int, ok bool) {
	rest, found := strings.CutPrefix(handle, execHandlePrefix)
	if !found {
		return "", 0, 0, false
	}
	// The node is first and may contain nothing surprising, so the two numbers
	// are taken from the end -- which is also what keeps a node name with a
	// colon in it from making a handle unreadable.
	rest, pidText, ok := cutLast(rest, ":")
	if !ok {
		return "", 0, 0, false
	}
	node, vmidText, ok := cutLast(rest, ":")
	if !ok || node == "" {
		return "", 0, 0, false
	}
	vmid, err := strconv.Atoi(vmidText)
	if err != nil {
		return "", 0, 0, false
	}
	pid, err = strconv.Atoi(pidText)
	if err != nil {
		return "", 0, 0, false
	}
	return node, vmid, pid, true
}

func cutLast(s, sep string) (before, after string, found bool) {
	i := strings.LastIndex(s, sep)
	if i < 0 {
		return s, "", false
	}
	return s[:i], s[i+len(sep):], true
}

package proxmox

// Discovery: what this credential can actually see, for the guided form.
//
// A form that asks somebody to type a node name, a storage name, a bridge and a
// VMID is a form four operators in five get wrong once, and every one of those
// mistakes is only discovered when the first machine fails to build. Asking the
// cluster instead turns all four into menus -- and each option carries the
// consequence of picking it, because a list of identifiers with no consequences
// is a list somebody guesses at.

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/provider"
)

// Discover lists the nodes, storages, bridges and templates this token can see.
//
// A node that will not answer is skipped rather than fatal: a cluster with one
// node down still has a form to fill in, and the storages and bridges the other
// nodes offer are still the right answers. Only a discovery that found nothing
// at all is reported as an error, because an empty menu with no explanation
// sends an operator looking for a bug in the wizard.
func Discover(ctx context.Context, c *Client) (provider.Discovery, error) {
	nodes, err := c.Nodes(ctx)
	if err != nil {
		return provider.Discovery{}, err
	}
	sort.Slice(nodes, func(i, j int) bool { return nodes[i].Node < nodes[j].Node })

	var d provider.Discovery
	var online []string
	for _, n := range nodes {
		d.Nodes = append(d.Nodes, provider.Choice{
			Value: n.Node, Label: n.Node, Consequence: describeNode(n),
		})
		if n.Online() {
			online = append(online, n.Node)
		}
	}

	storages := map[string]*seenStorage{}
	bridges := map[string]*seenBridge{}
	var firstErr error
	var answered int
	for _, node := range online {
		nodeErr := false
		if found, err := c.Storages(ctx, node); err != nil {
			nodeErr = true
			if firstErr == nil {
				firstErr = err
			}
		} else {
			for _, s := range found {
				// Only storages that can hold a disk image are offered: the
				// others cannot take a clone at all, and listing them invites
				// the one mistake this menu exists to prevent.
				if !s.Accepts("images") || !bool(s.Enabled) {
					continue
				}
				seen, ok := storages[s.Storage]
				if !ok {
					seen = &seenStorage{storage: s}
					storages[s.Storage] = seen
				}
				seen.nodes = append(seen.nodes, node)
				if int64(s.Avail) > int64(seen.storage.Avail) {
					seen.storage.Avail = s.Avail
				}
			}
		}
		if found, err := c.Bridges(ctx, node); err != nil {
			nodeErr = true
			if firstErr == nil {
				firstErr = err
			}
		} else {
			for _, b := range found {
				seen, ok := bridges[b.Iface]
				if !ok {
					seen = &seenBridge{iface: b}
					bridges[b.Iface] = seen
				}
				seen.nodes = append(seen.nodes, node)
			}
		}
		if !nodeErr {
			answered++
		}
	}

	// One call answers for the whole cluster, so templates cost nothing extra
	// however many nodes there are.
	guests, err := c.ClusterVMs(ctx)
	if err != nil && firstErr == nil {
		firstErr = err
	}
	if err == nil {
		d.Templates = describeTemplates(guests)
	}

	if answered == 0 && len(online) > 0 && firstErr != nil {
		return provider.Discovery{}, firstErr
	}
	d.Storages = describeStorages(storages, len(online))
	d.Bridges = describeBridges(bridges, len(online))
	return d, nil
}

type seenStorage struct {
	storage Storage
	nodes   []string
}

type seenBridge struct {
	iface NetworkInterface
	nodes []string
}

func describeNode(n Node) string {
	if !n.Online() {
		return fmt.Sprintf("%s -- machines placed here will not be built until it comes back", n.Status)
	}
	parts := []string{"online"}
	if n.MaxCPU > 0 {
		parts = append(parts, fmt.Sprintf("%d processors", n.MaxCPU.Int()))
	}
	if n.MaxMem > 0 {
		parts = append(parts, gibibytes(n.MaxMem)+" of memory")
	}
	return strings.Join(parts, ", ")
}

func describeStorages(seen map[string]*seenStorage, nodes int) []provider.Choice {
	out := make([]provider.Choice, 0, len(seen))
	for name, s := range seen {
		var parts []string
		switch {
		case bool(s.storage.Shared):
			parts = append(parts, "shared across the cluster")
		case len(s.nodes) < nodes:
			// The trap this menu exists to name: a local storage looks fine
			// until a machine is placed on a node that cannot see it.
			parts = append(parts, "only on "+join(s.nodes)+" -- a machine on another node cannot use it")
		}
		if s.storage.Avail > 0 {
			parts = append(parts, gibibytes(s.storage.Avail)+" free")
		}
		if s.storage.Type != "" {
			parts = append(parts, s.storage.Type)
		}
		out = append(out, provider.Choice{Value: name, Label: name, Consequence: strings.Join(parts, ", ")})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Value < out[j].Value })
	return out
}

func describeBridges(seen map[string]*seenBridge, nodes int) []provider.Choice {
	out := make([]provider.Choice, 0, len(seen))
	for name, b := range seen {
		var parts []string
		if len(b.nodes) < nodes {
			parts = append(parts, "only on "+join(b.nodes)+" -- a machine on another node would have no network")
		} else {
			parts = append(parts, "on every node")
		}
		if c := strings.TrimSpace(b.iface.Comments); c != "" {
			parts = append(parts, c)
		} else if b.iface.CIDR != "" {
			parts = append(parts, b.iface.CIDR)
		}
		out = append(out, provider.Choice{Value: name, Label: name, Consequence: strings.Join(parts, ", ")})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Value < out[j].Value })
	return out
}

func describeTemplates(guests []ClusterVM) []provider.Choice {
	var out []provider.Choice
	for _, g := range guests {
		// Only QEMU templates: a container template is not something this
		// provider can clone into a machine that runs an agent.
		if g.Type != "qemu" || !bool(g.Template) {
			continue
		}
		label := g.Name
		if label == "" {
			label = "VMID " + strconv.Itoa(g.VMID.Int())
		}
		out = append(out, provider.Choice{
			Value:       strconv.Itoa(g.VMID.Int()),
			Label:       label,
			Consequence: fmt.Sprintf("VMID %d on %s", g.VMID.Int(), g.Node),
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Value < out[j].Value })
	return out
}

// gibibytes renders a byte count the way the console does, because an operator
// comparing a menu against the Proxmox UI should not have to convert.
func gibibytes(n Int) string {
	const gib = 1 << 30
	if n <= 0 {
		return "0 GiB"
	}
	return fmt.Sprintf("%.0f GiB", float64(n)/gib)
}

package proxmox

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/provider"
)

func choice(t *testing.T, choices []provider.Choice, value string) provider.Choice {
	t.Helper()
	for _, c := range choices {
		if c.Value == value {
			return c
		}
	}
	t.Fatalf("no choice %q; got %v", value, values(choices))
	return provider.Choice{}
}

func values(choices []provider.Choice) []string {
	out := make([]string, 0, len(choices))
	for _, c := range choices {
		out = append(out, c.Value)
	}
	return out
}

// Offering a storage a clone cannot land on invites exactly the mistake the
// menu exists to prevent, and the operator only finds out when the first
// machine fails to build.
func TestTheGuidedFormOffersOnlyStoragesThatCanHoldADisk(t *testing.T) {
	f := newFakePVE(t, nil)

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	if got := values(found.Storages); len(got) != 2 {
		t.Fatalf("storages = %v, want only the ones that hold images", got)
	}
	choice(t, found.Storages, "local-lvm")
	choice(t, found.Storages, "ceph")
	for _, c := range found.Storages {
		if c.Value == "local" {
			t.Error("a storage that only holds ISOs and container templates was offered for a clone")
		}
	}
}

// A local storage looks fine in a list until a machine is placed on a node that
// cannot see it, so the consequence has to say which nodes have it.
func TestAStorageOnlySomeNodesCanSeeSaysSo(t *testing.T) {
	f := newFakePVE(t, nil)

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	local := choice(t, found.Storages, "local-lvm")
	if !strings.Contains(local.Consequence, "only on pve-1") {
		t.Errorf("consequence = %q, which does not say where it is", local.Consequence)
	}
	shared := choice(t, found.Storages, "ceph")
	if !strings.Contains(shared.Consequence, "shared") {
		t.Errorf("consequence = %q, which does not say it is shared", shared.Consequence)
	}
	if !strings.Contains(shared.Consequence, "GiB free") {
		t.Errorf("consequence = %q, which does not say how much room there is", shared.Consequence)
	}
}

// A machine on a node whose bridge is missing has no network and can never
// enrol -- a failure that looks like a broken image rather than a wrong menu.
func TestABridgeMissingFromANodeSaysSo(t *testing.T) {
	f := newFakePVE(t, nil)

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	everywhere := choice(t, found.Bridges, "vmbr0")
	if !strings.Contains(everywhere.Consequence, "every node") {
		t.Errorf("consequence = %q", everywhere.Consequence)
	}
	partial := choice(t, found.Bridges, "vmbr1")
	for _, want := range []string{"only on pve-1", "no network"} {
		if !strings.Contains(partial.Consequence, want) {
			t.Errorf("consequence = %q does not mention %q", partial.Consequence, want)
		}
	}
}

// Templates come from the one cluster-wide call, so a form for a ten-node
// cluster costs the same as one for a single machine.
func TestTemplatesComeFromTheOneClusterCall(t *testing.T) {
	f := newFakePVE(t, nil)

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	template := choice(t, found.Templates, "9000")
	if template.Label != "ubuntu-24.04-template" {
		t.Errorf("label = %q, want the template's name", template.Label)
	}
	if !strings.Contains(template.Consequence, "VMID 9000 on pve-1") {
		t.Errorf("consequence = %q, which does not say where it is", template.Consequence)
	}
	for _, c := range found.Templates {
		if c.Value == "100" {
			t.Error("somebody else's running machine was offered as a template")
		}
	}
	var sweeps int
	for _, r := range f.Requests() {
		if strings.HasSuffix(r, "/cluster/resources") {
			sweeps++
		}
	}
	if sweeps != 1 {
		t.Errorf("the cluster listing was asked for %d times, want once", sweeps)
	}
}

// An offline node is still worth showing: the answer to "why can nothing be
// built here" is the same list an operator is choosing from.
func TestANodeThatIsDownIsOfferedWithItsConsequence(t *testing.T) {
	f := newFakePVE(t, nil)

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	if got := values(found.Nodes); len(got) != 3 {
		t.Fatalf("nodes = %v, want every node in the cluster", got)
	}
	down := choice(t, found.Nodes, "pve-3")
	if !strings.Contains(down.Consequence, "offline") {
		t.Errorf("consequence = %q, which does not say why nothing can be built there", down.Consequence)
	}
	up := choice(t, found.Nodes, "pve-1")
	for _, want := range []string{"online", "8 processors", "32 GiB"} {
		if !strings.Contains(up.Consequence, want) {
			t.Errorf("consequence = %q does not mention %q", up.Consequence, want)
		}
	}
}

// A cluster with one node down still has a form to fill in, and the answers the
// other nodes gave are still the right ones.
func TestANodeThatWillNotAnswerDoesNotEmptyTheForm(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetError(http.MethodGet, "/pve-2/storage", http.StatusInternalServerError, "storage status unavailable")

	found, err := Discover(context.Background(), f.client(t))
	if err != nil {
		t.Fatalf("Discover: %v", err)
	}
	choice(t, found.Storages, "local-lvm")
	choice(t, found.Bridges, "vmbr0")
}

// A discovery that saw nothing at all is an error, because an empty menu with
// no explanation sends an operator looking for a bug in the wizard.
func TestDiscoveryFailsOnlyWhenNothingCouldBeSeen(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetError(http.MethodGet, "/nodes", http.StatusForbidden, "Permission check failed (/nodes, Sys.Audit)")

	_, err := Discover(context.Background(), f.client(t))
	if got := provider.KindOf(err); got != provider.FailurePermission {
		t.Fatalf("kind = %q, want %q (%v)", got, provider.FailurePermission, err)
	}
}

package proxmox

// A fake Proxmox VE cluster.
//
// It speaks the real /api2/json shapes over httptest.NewTLSServer, and its
// certificate is what the client is given as its CA -- so every test in this
// package exercises verified TLS rather than skipping it, and the one test that
// leaves the CA out proves the verification is really there.
//
// The knobs exist because the failures worth designing for cannot be produced
// by a happy-path double: a task that stays running and then fails, a clone
// whose answer is lost after the virtual machine was made, a locked guest, a
// storage with no room, a guest agent that never answers.

import (
	"encoding/json"
	"encoding/pem"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

const tokenID = "zoomies@pve!fleet"
const tokenSecret = "11111111-2222-3333-4444-555555555555"

// v is the path prefix every endpoint sits behind, for route tables that read
// like the API documentation.
const v = APIPath

type fakeVM struct {
	vmid        int
	node        string
	name        string
	status      string
	tags        string
	description string
	template    bool
	lock        string
	agent       string
	files       map[string]string
}

type fakeTask struct {
	node string
	// pending is how many more polls answer "running" before the task stops.
	pending int
	exit    string
}

type injected struct {
	method  string
	suffix  string
	status  int
	message string
}

type fakePVE struct {
	*httptest.Server
	t *testing.T

	mu       sync.Mutex
	seen     []*http.Request
	vms      map[int]*fakeVM
	tasks    map[string]*fakeTask
	nodes    []Node
	storages map[string][]Storage
	bridges  map[string][]NetworkInterface
	perms    Permissions
	errors   []injected
	stalls   []injected
	seq      int

	agentSilent    bool
	ambiguousClone bool
	quota          bool

	stop chan struct{}
}

// newFakePVE starts a cluster with two online nodes, one offline node, a
// template and somebody else's virtual machine -- the shape a real homelab
// cluster has, so that a test about ownership has something to get wrong.
// Routes given here replace the built-in handler for the same pattern.
func newFakePVE(t *testing.T, routes map[string]http.HandlerFunc) *fakePVE {
	t.Helper()
	f := &fakePVE{
		t:     t,
		vms:   map[int]*fakeVM{},
		tasks: map[string]*fakeTask{},
		nodes: []Node{
			{Node: "pve-1", Status: "online", MaxCPU: 8, MaxMem: 32 << 30},
			{Node: "pve-2", Status: "online", MaxCPU: 8, MaxMem: 32 << 30},
			{Node: "pve-3", Status: "offline"},
		},
		storages: map[string][]Storage{
			"pve-1": {
				{Storage: "local", Type: "dir", Content: "iso,vztmpl", Enabled: true, Active: true},
				{Storage: "local-lvm", Type: "lvmthin", Content: "images,rootdir", Enabled: true, Active: true, Avail: 500 << 30, Total: 1 << 40},
				{Storage: "ceph", Type: "rbd", Content: "images", Enabled: true, Active: true, Shared: true, Avail: 2 << 40, Total: 4 << 40},
			},
			"pve-2": {
				{Storage: "ceph", Type: "rbd", Content: "images", Enabled: true, Active: true, Shared: true, Avail: 2 << 40, Total: 4 << 40},
			},
		},
		bridges: map[string][]NetworkInterface{
			"pve-1": {
				{Iface: "vmbr0", Type: "bridge", Active: true, CIDR: "10.0.0.10/24"},
				{Iface: "vmbr1", Type: "bridge", Active: true, Comments: "lab only"},
			},
			"pve-2": {
				{Iface: "vmbr0", Type: "bridge", Active: true, CIDR: "10.0.0.11/24"},
			},
		},
		perms: Permissions{
			"/vms": {
				"VM.Clone": true, "VM.Allocate": true, "VM.Audit": true, "VM.PowerMgmt": true,
				"VM.Config.Disk": true, "VM.Config.CPU": true, "VM.Config.Memory": true,
				"VM.Config.Network": true, "VM.Config.Options": true,
				"VM.GuestAgent.FileWrite": true, "VM.GuestAgent.Unrestricted": true,
			},
			"/storage/local-lvm": {"Datastore.AllocateSpace": true},
		},
		stop: make(chan struct{}),
	}
	f.vms[9000] = &fakeVM{vmid: 9000, node: "pve-1", name: "ubuntu-24.04-template", status: "stopped", template: true, agent: "enabled=1"}
	f.vms[100] = &fakeVM{vmid: 100, node: "pve-1", name: "someone-elses-vm", status: "running", description: "the finance database"}

	mux := http.NewServeMux()
	for pattern, h := range routes {
		mux.HandleFunc(pattern, h)
	}
	for pattern, h := range f.routes() {
		if _, taken := routes[pattern]; taken {
			continue
		}
		mux.HandleFunc(pattern, h)
	}

	f.Server = httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_ = r.ParseForm()
		f.mu.Lock()
		f.seen = append(f.seen, r)
		f.mu.Unlock()

		if !strings.HasPrefix(r.Header.Get("Authorization"), "PVEAPIToken="+tokenID+"=") {
			writeFailure(w, http.StatusUnauthorized, "authentication failure")
			return
		}
		if f.stalled(r) {
			// The request has arrived and will never be answered, which is the
			// only way to produce the outcome nobody heard.
			select {
			case <-r.Context().Done():
			case <-f.stop:
			case <-time.After(5 * time.Second):
			}
			return
		}
		if in, ok := f.errorFor(r); ok {
			writeFailure(w, in.status, in.message)
			return
		}
		mux.ServeHTTP(w, r)
	}))
	t.Cleanup(func() {
		close(f.stop)
		f.Close()
	})
	return f
}

// client builds a client that verifies this server's certificate, which is the
// point: a test that skipped verification would not notice the day the client
// stopped doing it.
func (f *fakePVE) client(t *testing.T) *Client {
	t.Helper()
	c, err := New(Options{Endpoint: f.URL, TokenID: tokenID, Secret: tokenSecret, CAPEM: f.caPEM(t)})
	if err != nil {
		t.Fatalf("building a client: %v", err)
	}
	return c
}

func (f *fakePVE) caPEM(t *testing.T) string {
	t.Helper()
	cert := f.Certificate()
	if cert == nil {
		t.Fatal("the fake cluster has no certificate")
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: cert.Raw}))
}

// ---------------------------------------------------------------------------
// Knobs
// ---------------------------------------------------------------------------

// SetError answers a matching call with a status and a message. The path is a
// suffix so a test can name "/qemu/9000/clone" without the whole prefix.
func (f *fakePVE) SetError(method, suffix string, status int, message string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.errors = append(f.errors, injected{method: method, suffix: suffix, status: status, message: message})
}

// SetStall makes a matching call reach the server and never be answered, which
// is the only way to produce the failure the whole ambiguity rule exists for.
func (f *fakePVE) SetStall(method, suffix string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.stalls = append(f.stalls, injected{method: method, suffix: suffix})
}

// SetTaskPending keeps a task "running" for the next n polls.
func (f *fakePVE) SetTaskPending(upid string, n int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if t, ok := f.tasks[upid]; ok {
		t.pending = n
	}
}

// SetTaskFailure ends a task with Proxmox's own words instead of "OK".
func (f *fakePVE) SetTaskFailure(upid, reason string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if t, ok := f.tasks[upid]; ok {
		t.exit = reason
	}
}

// SetAmbiguousClone makes a clone create the virtual machine and then fail, so
// the answer says nothing about what happened -- the case that decides whether
// this fleet ends up paying for a machine nobody is tracking.
func (f *fakePVE) SetAmbiguousClone() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.ambiguousClone = true
}

// SetQuotaExhausted refuses every clone for want of space.
func (f *fakePVE) SetQuotaExhausted() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.quota = true
}

// SetGuestAgentSilent leaves the guest agent unanswering, which is what a
// machine that booted but never came up looks like.
func (f *fakePVE) SetGuestAgentSilent() {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.agentSilent = true
}

// SetLock puts another operation's lock on a guest.
func (f *fakePVE) SetLock(vmid int, lock string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if vm, ok := f.vms[vmid]; ok {
		vm.lock = lock
	}
}

// SetForeignVM adds a guest that is nothing to do with this fleet.
func (f *fakePVE) SetForeignVM(vmid int, name string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.vms[vmid] = &fakeVM{vmid: vmid, node: "pve-1", name: name, status: "running"}
}

// SetPermissions replaces what the token may do.
func (f *fakePVE) SetPermissions(p Permissions) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.perms = p
}

// SetVMDescription is how a test puts an ownership block on a guest.
func (f *fakePVE) SetVMDescription(vmid int, description, tags string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if vm, ok := f.vms[vmid]; ok {
		vm.description, vm.tags = description, tags
	}
}

// Requests returns every call made, as "METHOD /path".
func (f *fakePVE) Requests() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]string, 0, len(f.seen))
	for _, r := range f.seen {
		out = append(out, r.Method+" "+r.URL.Path)
	}
	return out
}

// request returns the first recorded call for "METHOD /path", with its form
// already parsed, so a test can assert on what was actually sent.
func (f *fakePVE) request(method, path string) *http.Request {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.seen {
		if r.Method == method && r.URL.Path == path {
			return r
		}
	}
	return nil
}

func (f *fakePVE) vm(vmid int) *fakeVM {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.vms[vmid]
}

func (f *fakePVE) errorFor(r *http.Request) (injected, bool) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, in := range f.errors {
		if in.method == r.Method && strings.HasSuffix(r.URL.Path, in.suffix) {
			return in, true
		}
	}
	return injected{}, false
}

func (f *fakePVE) stalled(r *http.Request) bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, in := range f.stalls {
		if in.method == r.Method && strings.HasSuffix(r.URL.Path, in.suffix) {
			return true
		}
	}
	return false
}

// newUPID mints a task handle in the wire's own shape, nine hex digits of
// process start included, because that is the form a parser written from one
// example gets wrong.
func (f *fakePVE) newUPID(node, kind, id string) string {
	f.seq++
	return fmt.Sprintf("UPID:%s:0005%04X:1%08X:65F0A1B2:%s:%s:%s:", node, f.seq, f.seq, kind, id, tokenID)
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

func (f *fakePVE) routes() map[string]http.HandlerFunc {
	return map[string]http.HandlerFunc{
		"GET " + v + "/version": func(w http.ResponseWriter, r *http.Request) {
			writeData(w, map[string]any{"version": "8.2.4", "release": "8.2", "repoid": "5e5fc8b5"})
		},
		"GET " + v + "/access/permissions": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			writeData(w, f.perms)
		},
		"GET " + v + "/nodes": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			out := make([]map[string]any, 0, len(f.nodes))
			for _, n := range f.nodes {
				// maxmem arrives as a string here and as a number in
				// /cluster/resources: the same field, two wire forms.
				out = append(out, map[string]any{
					"node": n.Node, "status": n.Status, "maxcpu": n.MaxCPU.Int(),
					"maxmem": strconv.FormatInt(int64(n.MaxMem), 10),
				})
			}
			writeData(w, out)
		},
		"GET " + v + "/nodes/{node}/storage": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			list, ok := f.storages[r.PathValue("node")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "no such node")
				return
			}
			out := make([]map[string]any, 0, len(list))
			for _, s := range list {
				// enabled, active and shared are 0 or 1, never true or false.
				out = append(out, map[string]any{
					"storage": s.Storage, "type": s.Type, "content": s.Content,
					"enabled": boolToInt(bool(s.Enabled)), "active": boolToInt(bool(s.Active)),
					"shared": boolToInt(bool(s.Shared)), "avail": int64(s.Avail), "total": int64(s.Total),
				})
			}
			writeData(w, out)
		},
		"GET " + v + "/nodes/{node}/network": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			list, ok := f.bridges[r.PathValue("node")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "no such node")
				return
			}
			out := make([]map[string]any, 0, len(list))
			for _, b := range list {
				out = append(out, map[string]any{
					"iface": b.Iface, "type": b.Type, "active": boolToInt(bool(b.Active)),
					"cidr": b.CIDR, "comments": b.Comments,
				})
			}
			writeData(w, out)
		},
		"GET " + v + "/cluster/resources": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			out := []map[string]any{}
			for _, vm := range f.vms {
				out = append(out, map[string]any{
					"vmid": vm.vmid, "node": vm.node, "name": vm.name, "status": vm.status,
					"type": "qemu", "tags": vm.tags,
					// template is 1 or absent, never false.
					"template": boolToInt(vm.template),
					// maxmem is a string here on some releases.
					"maxmem": "17179869184",
				})
			}
			writeData(w, out)
		},
		"GET " + v + "/cluster/nextid": func(w http.ResponseWriter, r *http.Request) {
			asked := r.URL.Query().Get("vmid")
			id, _ := strconv.Atoi(asked)
			f.mu.Lock()
			defer f.mu.Unlock()
			if _, taken := f.vms[id]; taken {
				writeFailure(w, http.StatusBadRequest, fmt.Sprintf("VM %d already exists", id))
				return
			}
			writeData(w, asked)
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/clone": func(w http.ResponseWriter, r *http.Request) {
			node, template := r.PathValue("node"), pathInt(r, "vmid")
			newid, _ := strconv.Atoi(r.PostFormValue("newid"))
			f.mu.Lock()
			defer f.mu.Unlock()
			if f.quota {
				writeFailure(w, http.StatusInternalServerError, "unable to create image: storage 'local-lvm' is full (no space left on device)")
				return
			}
			if src, ok := f.vms[template]; ok && src.lock != "" {
				writeFailure(w, http.StatusInternalServerError, fmt.Sprintf("VM %d is locked (%s)", template, src.lock))
				return
			}
			if _, taken := f.vms[newid]; taken {
				writeFailure(w, http.StatusInternalServerError, fmt.Sprintf("VM %d already exists", newid))
				return
			}
			f.vms[newid] = &fakeVM{vmid: newid, node: node, name: r.PostFormValue("name"),
				status: "stopped", description: r.PostFormValue("description"), agent: "enabled=1"}
			upid := f.newUPID(node, "qmclone", strconv.Itoa(newid))
			f.tasks[upid] = &fakeTask{node: node, exit: "OK"}
			if f.ambiguousClone {
				// The machine now exists and the caller will never learn it.
				writeFailure(w, http.StatusInternalServerError, "clone failed: got timeout")
				return
			}
			writeData(w, upid)
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/config": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			vm, ok := f.vms[pathInt(r, "vmid")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			if vm.lock != "" {
				writeFailure(w, http.StatusInternalServerError, fmt.Sprintf("VM %d is locked (%s)", vm.vmid, vm.lock))
				return
			}
			if tags := r.PostFormValue("tags"); tags != "" {
				vm.tags = tags
			}
			if d := r.PostFormValue("description"); d != "" {
				vm.description = d
			}
			writeData(w, nil)
		},
		"GET " + v + "/nodes/{node}/qemu/{vmid}/config": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			vm, ok := f.vms[pathInt(r, "vmid")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			out := map[string]any{
				"name": vm.name, "description": vm.description, "tags": vm.tags,
				"agent": vm.agent,
				// cores is a number, memory a string: both happen.
				"cores": 2, "memory": "4096",
			}
			if vm.template {
				out["template"] = 1
			}
			writeData(w, out)
		},
		"GET " + v + "/nodes/{node}/qemu/{vmid}/status/current": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			vm, ok := f.vms[pathInt(r, "vmid")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			out := map[string]any{
				// vmid is a string here, a number in /cluster/resources.
				"vmid": strconv.Itoa(vm.vmid), "name": vm.name, "status": vm.status,
				"qmpstatus": vm.status, "tags": vm.tags, "agent": boolToInt(vm.agent != ""),
			}
			if vm.lock != "" {
				out["lock"] = vm.lock
			}
			if vm.template {
				out["template"] = 1
			}
			writeData(w, out)
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/status/{action}": func(w http.ResponseWriter, r *http.Request) {
			node, action := r.PathValue("node"), r.PathValue("action")
			f.mu.Lock()
			defer f.mu.Unlock()
			vm, ok := f.vms[pathInt(r, "vmid")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			if vm.lock != "" {
				writeFailure(w, http.StatusInternalServerError, fmt.Sprintf("VM %d is locked (%s)", vm.vmid, vm.lock))
				return
			}
			if action == "start" {
				vm.status = "running"
			} else {
				vm.status = "stopped"
			}
			upid := f.newUPID(node, "qm"+action, strconv.Itoa(vm.vmid))
			f.tasks[upid] = &fakeTask{node: node, exit: "OK"}
			writeData(w, upid)
		},
		"PUT " + v + "/nodes/{node}/qemu/{vmid}/resize": func(w http.ResponseWriter, r *http.Request) {
			writeData(w, nil)
		},
		"DELETE " + v + "/nodes/{node}/qemu/{vmid}": func(w http.ResponseWriter, r *http.Request) {
			node := r.PathValue("node")
			f.mu.Lock()
			defer f.mu.Unlock()
			vmid := pathInt(r, "vmid")
			if _, ok := f.vms[vmid]; !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			delete(f.vms, vmid)
			upid := f.newUPID(node, "qmdestroy", strconv.Itoa(vmid))
			f.tasks[upid] = &fakeTask{node: node, exit: "OK"}
			writeData(w, upid)
		},
		"GET " + v + "/nodes/{node}/tasks/{upid}/status": func(w http.ResponseWriter, r *http.Request) {
			upid := r.PathValue("upid")
			f.mu.Lock()
			defer f.mu.Unlock()
			task, ok := f.tasks[upid]
			if !ok {
				writeFailure(w, http.StatusNotFound, "no such task")
				return
			}
			out := map[string]any{"upid": upid, "node": task.node, "type": "qmclone", "id": "143"}
			if task.pending > 0 {
				task.pending--
				out["status"] = "running"
				writeData(w, out)
				return
			}
			out["status"] = "stopped"
			out["exitstatus"] = task.exit
			writeData(w, out)
		},
		"GET " + v + "/nodes/{node}/tasks/{upid}/log": func(w http.ResponseWriter, r *http.Request) {
			writeData(w, []map[string]any{
				{"n": 1, "t": "create full clone of drive scsi0"},
				{"n": "2", "t": "TASK ERROR: storage 'local-lvm' is full"},
			})
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/agent/ping": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			silent := f.agentSilent
			f.mu.Unlock()
			if silent {
				writeFailure(w, http.StatusInternalServerError, "QEMU guest agent is not running")
				return
			}
			writeData(w, nil)
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/agent/file-write": func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			defer f.mu.Unlock()
			vm, ok := f.vms[pathInt(r, "vmid")]
			if !ok {
				writeFailure(w, http.StatusNotFound, "Configuration file does not exist")
				return
			}
			if vm.files == nil {
				vm.files = map[string]string{}
			}
			vm.files[r.PostFormValue("file")] = r.PostFormValue("content")
			writeData(w, nil)
		},
		"POST " + v + "/nodes/{node}/qemu/{vmid}/agent/exec": func(w http.ResponseWriter, r *http.Request) {
			writeData(w, map[string]any{"pid": 4242})
		},
		"GET " + v + "/nodes/{node}/qemu/{vmid}/agent/exec-status": func(w http.ResponseWriter, r *http.Request) {
			// exited is 1, exitcode a number, and the guest's own stderr is
			// what an operator is shown when a bootstrap fails.
			writeData(w, map[string]any{"exited": 1, "exitcode": 0, "out-data": "enabled zoomies-agent", "err-data": ""})
		},
	}
}

func writeData(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]any{"data": v})
}

// writeFailure answers the way Proxmox does when a call is refused: a status
// and a sentence, with the data member explicitly null.
func writeFailure(w http.ResponseWriter, status int, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": nil, "message": message})
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func pathInt(r *http.Request, name string) int {
	n, _ := strconv.Atoi(r.PathValue(name))
	return n
}

// formValue is what a test asserts a call actually sent.
func formValue(r *http.Request, key string) string {
	if r == nil {
		return ""
	}
	return r.PostForm.Get(key)
}

// queryValue is the same for the parameters that ride on the URL.
func queryValue(r *http.Request, key string) string {
	if r == nil {
		return ""
	}
	return r.URL.Query().Get(key)
}

package proxmox

// Ownership marks: what this fleet writes on a guest so that a sweep can tell
// its own machines from everybody else's.
//
// Two places, because they answer two different questions. Tags appear in the
// one cluster-wide listing, so they are how a sweep filters thousands of guests
// down to a handful without asking each one for its configuration. The
// description holds the whole record -- controller, provider, machine,
// fingerprint, when -- and is read back from the guest's own configuration.
//
// Neither is authenticated. Any Proxmox user with configuration rights can
// write both, so nothing here is proof of anything: the store is the authority
// and these are tamper-evidence. What they catch is a recycled identifier,
// another controller's guest, and one somebody made by hand -- the three cases
// that actually happen -- and a delete requires the row and the marks to agree.

import (
	"encoding/json"
	"sort"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
)

// FleetTag is on every guest this fleet created. It is what a sweep filters on
// and what an operator sorts by in the Proxmox console.
const FleetTag = "zoomies"

// machineTagPrefix begins the per-machine tag, so a guest in the console names
// the row on the machines page without a lookup.
const machineTagPrefix = "zoomies-"

// tagSeparator is how Proxmox joins a guest's tags on the wire. It accepts
// several separators on the way in and writes this one on the way out.
const tagSeparator = ";"

// ownershipBlock is the JSON written into a guest's description. It is nested
// under one key so that a description this fleet did not write, but which
// happens to be JSON, cannot be mistaken for one of ours.
type ownershipBlock struct {
	Zoomies ownershipRecord `json:"zoomies"`
}

type ownershipRecord struct {
	Controller  string `json:"controller"`
	Provider    string `json:"provider"`
	Machine     string `json:"machine"`
	Fingerprint string `json:"fingerprint"`
	CreatedAt   string `json:"created_at,omitempty"`
}

// descriptionPreamble is the sentence an operator reads in the Proxmox console
// before they reach the machine-readable half. A guest that appears in somebody
// else's cluster with no explanation is a guest somebody deletes by hand.
const descriptionPreamble = "Managed by Zoomies. Deleting or renaming this guest by hand will leave the fleet with a machine it cannot account for."

// Describe renders the description to write on a guest.
//
// The human sentence comes first because that is what the console shows in a
// narrow column, and the machine-readable block is one line so that an operator
// who adds a note of their own does not have to preserve its shape -- DecodeOwner
// reads whichever line still parses.
func Describe(owner provider.Owner, name string) string {
	rec := ownershipRecord{
		Controller:  owner.ControllerID,
		Provider:    owner.ProviderID,
		Machine:     owner.MachineID,
		Fingerprint: owner.Fingerprint,
	}
	if !owner.CreatedAt.IsZero() {
		// UTC, always: a hypervisor's timezone is not ours, and a mark that
		// read differently depending on where it was written would be useless
		// as evidence.
		rec.CreatedAt = owner.CreatedAt.UTC().Format(time.RFC3339Nano)
	}
	blob, err := json.Marshal(ownershipBlock{Zoomies: rec})
	if err != nil {
		// Nothing in the record can fail to encode; a description without the
		// block is still better than no description at all.
		return descriptionPreamble
	}
	lines := []string{descriptionPreamble}
	if name != "" {
		lines = append(lines, "Machine "+name+".")
	}
	return strings.Join(append(lines, string(blob)), "\n")
}

// DecodeOwner reads the marks back out of a description, reporting whether it
// found any.
//
// It scans line by line rather than parsing the whole description, because an
// operator who appends a note to a guest's description has not thereby
// disowned it -- and a sweep that read that as "unmarked" would quarantine a
// machine the fleet is quite sure about.
func DecodeOwner(description string) (provider.Owner, bool) {
	for _, line := range strings.Split(description, "\n") {
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "{") {
			continue
		}
		var block ownershipBlock
		if err := json.Unmarshal([]byte(line), &block); err != nil {
			continue
		}
		rec := block.Zoomies
		if rec.Controller == "" && rec.Machine == "" && rec.Fingerprint == "" {
			continue
		}
		owner := provider.Owner{
			ControllerID: rec.Controller,
			ProviderID:   rec.Provider,
			MachineID:    rec.Machine,
			Fingerprint:  rec.Fingerprint,
		}
		// A timestamp that will not parse loses the timestamp and nothing else.
		// What a delete checks is the controller, the machine and the
		// fingerprint, and refusing the whole block over a date would turn a
		// machine we own into one nobody may touch.
		if rec.CreatedAt != "" {
			if at, err := time.Parse(time.RFC3339Nano, rec.CreatedAt); err == nil {
				owner.CreatedAt = at.UTC()
			}
		}
		return owner, true
	}
	return provider.Owner{}, false
}

// Tags are the tags to write on a guest: the fleet's, and the machine's own.
func Tags(owner provider.Owner) []string {
	tags := []string{FleetTag}
	if t := MachineTag(owner.MachineID); t != "" {
		tags = append(tags, t)
	}
	return tags
}

// MachineTag is the per-machine tag, or "" for an identifier with nothing
// usable in it. The machine's own identifier follows the prefix, with its own
// prefix dropped: "mach_k3f9qz2mx7ab" is already self-describing next to
// "zoomies-", and a tag has a grammar to stay inside.
func MachineTag(machineID string) string {
	fragment := machineID
	if _, rest, ok := strings.Cut(machineID, "_"); ok && rest != "" {
		fragment = rest
	}
	if fragment = sanitiseTag(fragment); fragment == "" {
		return ""
	}
	return machineTagPrefix + fragment
}

// EncodeTags renders tags for the wire, merging in any the guest already
// carries so that a tag an operator added by hand survives being configured.
// The result is sorted, because a set written in a different order every pass
// would rewrite a guest's configuration for nothing.
func EncodeTags(existing string, add []string) string {
	seen := map[string]bool{}
	var all []string
	for _, t := range append(ParseTags(existing), add...) {
		t = sanitiseTag(t)
		if t == "" || seen[t] {
			continue
		}
		seen[t] = true
		all = append(all, t)
	}
	sort.Strings(all)
	return strings.Join(all, tagSeparator)
}

// ParseTags splits a guest's tags. Proxmox writes them separated by semicolons
// and accepts commas and spaces, so all three are read.
func ParseTags(s string) []string {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r == ';' || r == ',' || r == ' ' || r == '\t'
	})
	out := make([]string, 0, len(fields))
	for _, f := range fields {
		if t := sanitiseTag(f); t != "" {
			out = append(out, t)
		}
	}
	return out
}

// HasFleetTag reports whether a guest's tags claim it for this fleet. It is a
// hint and not proof: it is what narrows a cluster-wide listing down to the
// guests worth reading a description for.
func HasFleetTag(tags string) bool {
	for _, t := range ParseTags(tags) {
		if t == FleetTag {
			return true
		}
	}
	return false
}

// sanitiseTag makes a tag Proxmox will accept: lower case, and nothing outside
// letters, digits, hyphen, underscore and full stop. A tag Proxmox rejects
// fails the whole configuration call, which would leave a guest running and
// unmarked -- the one state this file exists to prevent.
func sanitiseTag(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(strings.TrimSpace(s)) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '_', r == '.':
			b.WriteRune(r)
		default:
			// Dropped rather than replaced: a substitute character would make
			// two different identifiers collide on one tag.
		}
	}
	// Proxmox requires the first character to be a letter, a digit or an
	// underscore, so a tag that would start with punctuation is trimmed to
	// where it does.
	return strings.TrimLeft(b.String(), "-.")
}

package proxmox

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/provider"
)

// The marks are how a sweep tells this fleet's guests from everybody else's, so
// what is written has to be exactly what is read back. A fingerprint that did
// not survive the round trip would make every machine look like somebody
// else's, and nothing would ever be deleted again.
func TestTheOwnershipBlockSurvivesARoundTrip(t *testing.T) {
	created := time.Date(2026, 3, 4, 9, 15, 30, 0, time.UTC)
	tests := []struct {
		name  string
		owner provider.Owner
	}{
		{"a complete set of marks", provider.Owner{
			ControllerID: "ctl_k3f9qz2mx7ab", ProviderID: "prv_ab2c3d4e5f6g",
			MachineID: "mach_z7y6x5w4v3u2", Fingerprint: "9f8e7d6c5b4a", CreatedAt: created,
		}},
		{"no timestamp, which is not a reason to disown a machine", provider.Owner{
			ControllerID: "ctl_k3f9qz2mx7ab", MachineID: "mach_z7y6x5w4v3u2", Fingerprint: "9f8e7d6c5b4a",
		}},
		{"a timestamp somewhere else in the world", provider.Owner{
			ControllerID: "ctl_k3f9qz2mx7ab", MachineID: "mach_z7y6x5w4v3u2", Fingerprint: "9f8e7d6c5b4a",
			CreatedAt: created.In(time.FixedZone("AEST", 10*3600)),
		}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			description := Describe(tc.owner, "zoomies-mach-z7y6x5w4v3u2")
			got, ok := DecodeOwner(description)
			if !ok {
				t.Fatalf("the description we wrote carries no marks:\n%s", description)
			}
			if !got.Matches(tc.owner) {
				t.Errorf("the marks read back do not match the ones written: %+v vs %+v", got, tc.owner)
			}
			if got.ProviderID != tc.owner.ProviderID {
				t.Errorf("ProviderID = %q, want %q", got.ProviderID, tc.owner.ProviderID)
			}
			if !got.CreatedAt.Equal(tc.owner.CreatedAt) {
				t.Errorf("CreatedAt = %v, want %v", got.CreatedAt, tc.owner.CreatedAt)
			}
			if !strings.Contains(description, descriptionPreamble) {
				t.Error("the description says nothing to the operator who reads it in the console")
			}
		})
	}
}

// An operator who adds a note to a guest's description has not disowned it, and
// a sweep that read that as "unmarked" would quarantine a machine the fleet is
// quite sure about.
func TestADescriptionSomebodyEditedStillNamesItsOwner(t *testing.T) {
	owner := provider.Owner{ControllerID: "ctl_one", MachineID: "mach_two", Fingerprint: "three"}
	edited := "do not delete -- Ana\n" + Describe(owner, "zoomies-mach-two") + "\nrebooted 2026-03-04"

	got, ok := DecodeOwner(edited)
	if !ok {
		t.Fatalf("an edited description lost its marks:\n%s", edited)
	}
	if !got.Matches(owner) {
		t.Errorf("marks = %+v, want %+v", got, owner)
	}
}

// Everything that is not one of our blocks has to read as "no marks", because
// the alternative is deleting a guest on the strength of a coincidence.
func TestADescriptionThatIsNobodysCarriesNoMarks(t *testing.T) {
	tests := []struct {
		name, description string
	}{
		{"nothing at all", ""},
		{"somebody's prose", "the finance database -- do not touch"},
		{"somebody else's JSON", `{"terraform":{"workspace":"prod"}}`},
		{"our shape with nothing in it", `{"zoomies":{}}`},
		{"JSON that does not parse", `{"zoomies":{"controller":`},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if owner, ok := DecodeOwner(tc.description); ok {
				t.Errorf("marks were found where there are none: %+v", owner)
			}
		})
	}
}

// The marks are readable and writable by anybody with configuration rights, so
// they are tamper-evidence rather than proof: what they catch is a recycled
// identifier and another controller's guest.
func TestMarksThatAreNotOursDoNotMatch(t *testing.T) {
	ours := provider.Owner{ControllerID: "ctl_one", MachineID: "mach_two", Fingerprint: "three"}
	tests := []struct {
		name  string
		found provider.Owner
	}{
		{"another controller's machine", provider.Owner{ControllerID: "ctl_other", MachineID: "mach_two", Fingerprint: "three"}},
		{"our controller, a machine we do not know", provider.Owner{ControllerID: "ctl_one", MachineID: "mach_other", Fingerprint: "three"}},
		{"the right names and a forged fingerprint", provider.Owner{ControllerID: "ctl_one", MachineID: "mach_two", Fingerprint: "guessed"}},
		{"no marks at all", provider.Owner{}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if tc.found.Matches(ours) {
				t.Errorf("%+v was accepted as ours", tc.found)
			}
		})
	}
}

// A tag Proxmox refuses fails the whole configuration call, which would leave a
// machine running and unmarked -- the one state the marks exist to prevent.
func TestATagStaysInsideProxmoxsGrammar(t *testing.T) {
	tests := []struct {
		name, machineID, want string
	}{
		{"a generated identifier", "mach_k3f9qz2mx7ab", "zoomies-k3f9qz2mx7ab"},
		{"a fixture's readable name", "mach_demo-linux", "zoomies-demo-linux"},
		{"capitals, which Proxmox lower-cases anyway", "mach_ABCdef", "zoomies-abcdef"},
		{"characters a tag may not carry", "mach_a b/c:d", "zoomies-abcd"},
		{"an identifier with no prefix", "k3f9qz2mx7ab", "zoomies-k3f9qz2mx7ab"},
		{"nothing usable", "mach_///", ""},
		{"nothing at all", "", ""},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := MachineTag(tc.machineID); got != tc.want {
				t.Errorf("MachineTag(%q) = %q, want %q", tc.machineID, got, tc.want)
			}
		})
	}
}

// Configuring a machine must not quietly remove a tag an operator added, and it
// must write the same string every pass -- a set in a different order each time
// would rewrite a guest's configuration for nothing.
func TestTagsAnOperatorAddedSurviveBeingConfigured(t *testing.T) {
	owner := provider.Owner{MachineID: "mach_k3f9qz2mx7ab"}
	got := EncodeTags("production;do-not-delete", Tags(owner))
	want := "do-not-delete;production;zoomies;zoomies-k3f9qz2mx7ab"
	if got != want {
		t.Errorf("EncodeTags = %q, want %q", got, want)
	}
	if again := EncodeTags(got, Tags(owner)); again != got {
		t.Errorf("a second pass rewrote the tags: %q then %q", got, again)
	}
}

// The fleet tag is what narrows a cluster-wide listing down to the guests worth
// reading a description for, so it has to be found however Proxmox joined them.
func TestTheFleetTagIsWhatASweepFiltersOn(t *testing.T) {
	tests := []struct {
		tags string
		want bool
	}{
		{"zoomies;zoomies-abc", true},
		{"production,zoomies", true},
		{"zoomies zoomies-abc", true},
		{"ZOOMIES", true},
		{"zoomies-abc", false},
		{"production", false},
		{"", false},
	}
	for _, tc := range tests {
		t.Run(tc.tags, func(t *testing.T) {
			if got := HasFleetTag(tc.tags); got != tc.want {
				t.Errorf("HasFleetTag(%q) = %v, want %v", tc.tags, got, tc.want)
			}
		})
	}
}

// The marks have to survive the wire as well as the round trip in memory: the
// configuration endpoint is where a sweep reads them back from, and a delete
// requires what it finds there to agree with the row.
func TestTheMarksAreReadBackFromTheGuestsOwnConfiguration(t *testing.T) {
	owner := provider.Owner{
		ControllerID: "ctl_k3f9qz2mx7ab", ProviderID: "prv_ab2c3d4e5f6g",
		MachineID: "mach_z7y6x5w4v3u2", Fingerprint: "9f8e7d6c5b4a",
		CreatedAt: time.Date(2026, 3, 4, 9, 15, 30, 0, time.UTC),
	}
	f := newFakePVE(t, nil)
	f.SetForeignVM(143, "zoomies-mach-z7y6x5w4v3u2")
	f.SetVMDescription(143, Describe(owner, "zoomies-mach-z7y6x5w4v3u2"), EncodeTags("", Tags(owner)))

	cfg, err := f.client(t).VMConfig(context.Background(), "pve-1", 143)
	if err != nil {
		t.Fatalf("VMConfig: %v", err)
	}
	got, ok := DecodeOwner(cfg.Description)
	if !ok {
		t.Fatalf("the guest carries no marks: %q", cfg.Description)
	}
	if !got.Matches(owner) {
		t.Errorf("marks = %+v, want %+v", got, owner)
	}
	if !HasFleetTag(cfg.Tags) {
		t.Errorf("tags = %q, which a sweep would not find", cfg.Tags)
	}
}

package proxmox

// Preflight: everything that can be checked before a single virtual machine
// exists, reported as findings an operator can act on.
//
// It never returns an error. A provider that cannot be reached, a token that
// was refused, a storage that cannot hold a disk and a template that is not a
// template are all answers rather than failures, and they are reported in
// config.Finding so the problems drawer, the startup print and the setup wizard
// render them with no translation at all. That is what makes "validate the
// prerequisites before provisioning" a button rather than a hope.

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/version"
)

// The setting keys findings name. They are the provider row's own settings
// rather than zoomies.yaml keys, because that is where these answers live: a
// credential in a configuration file is a credential in a backup, a
// diagnostics bundle and a screenshot.
const (
	SettingNodes      = "nodes"
	SettingStorage    = "storage"
	SettingBridge     = "bridge"
	SettingTemplateID = "template_id"
	SettingPool       = "pool"
	SettingVMIDMin    = "vmid_min"
	SettingVMIDMax    = "vmid_max"
	SettingTokenID    = "api_token_id"
	SettingInsecure   = "insecure_skip_verify"
)

// Prereqs is the configured half of a provider: what an operator said this
// fleet may use, and therefore what preflight has to confirm exists.
type Prereqs struct {
	// Nodes are the nodes machines may be placed on.
	Nodes []string
	// Storage is where a clone's disk lands.
	Storage string
	// Bridge is the network a machine's interface is attached to.
	Bridge string
	// TemplateNode is where the template lives; empty means the first node.
	TemplateNode string
	// TemplateID is the template's VMID.
	TemplateID int
	// Pool is an optional Proxmox pool new guests are put in, which is also a
	// path privileges can be granted on.
	Pool string
	// VMIDMin and VMIDMax bound the identifiers this provider may take. The
	// range is the point: an unbounded provider would allocate identifiers
	// somebody else's automation is entitled to.
	VMIDMin, VMIDMax int
	// GuestAgent says the bootstrap goes through the QEMU guest agent, which
	// needs two privileges most roles do not include.
	GuestAgent bool
}

// Preflight checks configuration, credentials and prerequisites, changing
// nothing.
func Preflight(ctx context.Context, c *Client, p Prereqs) provider.Report {
	pf := &preflight{client: c, prereqs: p}

	// The range needs no hypervisor, so it is checked first and answered even
	// when nothing else can be: a provider with no range configured is
	// misconfigured whether or not the cluster is up.
	pf.checkVMIDRange()
	pf.checkVerification()

	v, err := c.Version(ctx)
	if err != nil {
		pf.explainFailure(err, "reach the cluster")
		return pf.report
	}
	pf.report.Reachable = true
	pf.report.Version = v.Version
	pf.checkVersion(v)

	pf.checkPrivileges(ctx)
	pf.checkResources(ctx)
	return pf.report
}

type preflight struct {
	client  *Client
	prereqs Prereqs
	report  provider.Report
}

func (pf *preflight) add(f config.Finding) { pf.report.Findings = append(pf.report.Findings, f) }

// explainFailure turns a call that failed into the one finding it deserves.
// A cluster that cannot be reached has one problem, not eleven, and listing the
// checks that could not run would bury it.
func (pf *preflight) explainFailure(err error, attempt string) {
	var pe *provider.Error
	message := err.Error()
	remedy := ""
	if errors.As(err, &pe) {
		message, remedy = pe.Message, pe.Remedy
	}
	switch provider.KindOf(err) {
	case provider.FailureAuth:
		pf.add(config.Finding{
			Code: "proxmox.credentials_refused", Severity: config.SeverityError, Setting: SettingTokenID,
			Title:  "the API token was refused",
			Detail: message,
			Fix:    fallback(remedy, "check the token id and its secret; the secret is shown once, when the token is created"),
		})
	case provider.FailurePermission:
		pf.add(config.Finding{
			Code: "proxmox.privilege_missing", Severity: config.SeverityError, Setting: SettingTokenID,
			Title:  "the API token may not " + attempt,
			Detail: message,
			Fix:    fallback(remedy, "grant the token the privilege this call needs"),
		})
	default:
		pf.add(config.Finding{
			Code: "proxmox.unreachable", Severity: config.SeverityError, Setting: "endpoint",
			Title:  "could not " + attempt,
			Detail: message,
			Fix:    fallback(remedy, "check the endpoint, that the node is up, and that this controller can reach port "+DefaultPort),
		})
	}
}

func (pf *preflight) checkVMIDRange() {
	lo, hi := pf.prereqs.VMIDMin, pf.prereqs.VMIDMax
	switch {
	case lo <= 0 || hi <= 0:
		pf.add(config.Finding{
			Code: "proxmox.vmid_range", Severity: config.SeverityError, Setting: SettingVMIDMin,
			Title:  "no VMID range is configured",
			Detail: "without one this provider would allocate identifiers anywhere in the cluster, including ones somebody else's automation is entitled to.",
			Fix:    "set vmid_min and vmid_max to a range nothing else uses, for example 9000 to 9099.",
		})
	case lo > hi:
		pf.add(config.Finding{
			Code: "proxmox.vmid_range", Severity: config.SeverityError, Setting: SettingVMIDMin,
			Title:  fmt.Sprintf("the VMID range %d-%d runs backwards", lo, hi),
			Detail: "no identifier can be allocated from it, so no machine can be created.",
			Fix:    "set vmid_min below vmid_max.",
		})
	case lo < 100:
		pf.add(config.Finding{
			Code: "proxmox.vmid_range_reserved", Severity: config.SeverityWarning, Setting: SettingVMIDMin,
			Title:  fmt.Sprintf("the VMID range starts at %d", lo),
			Detail: "Proxmox reserves identifiers below 100 for itself, so the first creations in this range will be refused.",
			Fix:    "start the range at 100 or above.",
		})
	}
}

func (pf *preflight) checkVerification() {
	if !pf.client.insecure {
		return
	}
	pf.add(config.Finding{
		Code: "proxmox.insecure_tls", Severity: config.SeverityWarning, Setting: SettingInsecure,
		Title: "this cluster's certificate is not verified",
		Detail: "anything able to intercept the connection can read this token and use it to create and destroy " +
			"virtual machines, and nothing else will ever mention it.",
		Fix: "paste the cluster's CA certificate from /etc/pve/pve-root-ca.pem into ca_pem and turn verification back on.",
	})
}

func (pf *preflight) checkVersion(v VersionInfo) {
	if version.CompareBuilds(v.Version, MinPVEVersion) != version.SkewBehind {
		return
	}
	pf.add(config.Finding{
		Code: "proxmox.version_unqualified", Severity: config.SeverityWarning, Setting: "endpoint",
		Title: fmt.Sprintf("Proxmox VE %s is older than the %s this integration is qualified against", v.Version, MinPVEVersion),
		Detail: "the endpoints it uses were checked against " + MinPVEVersion + " and later; on an older release a call may " +
			"behave differently, and nobody has run the qualification to find out.",
		Fix: "upgrade the cluster, or treat this provider as unqualified and watch the first machines it builds.",
	})
}

// privilege is one thing the token must be allowed to do, the paths that would
// grant it, and why it is needed. The why is in the finding, because an
// operator granting a privilege deserves to know what it buys.
type privilege struct {
	name  string
	paths []string
	why   string
}

func (pf *preflight) requiredPrivileges() []privilege {
	vms := []string{"/vms"}
	if pool := strings.TrimSpace(pf.prereqs.Pool); pool != "" {
		// A grant on the pool covers the guests inside it, so either path is a
		// real answer and an operator who chose the tighter one is right.
		vms = append(vms, "/pool/"+pool)
	}
	template := append([]string{fmt.Sprintf("/vms/%d", pf.prereqs.TemplateID)}, vms...)
	storage := []string{"/storage"}
	if s := strings.TrimSpace(pf.prereqs.Storage); s != "" {
		storage = append([]string{"/storage/" + s}, storage...)
	}

	required := []privilege{
		{"VM.Clone", template, "cloning the template is how every machine starts"},
		{"VM.Allocate", vms, "creating a machine and destroying it again"},
		{"VM.Config.Disk", vms, "giving a machine its disk"},
		{"VM.Config.CPU", vms, "giving a machine its processors"},
		{"VM.Config.Memory", vms, "giving a machine its memory"},
		{"VM.Config.Network", vms, "attaching a machine to the bridge"},
		{"VM.Config.Options", vms, "writing this fleet's ownership marks onto a machine"},
		{"VM.PowerMgmt", vms, "starting a machine and shutting it down"},
		{"VM.Audit", vms, "inspecting machines, and the sweep that tells this fleet's guests from everybody else's"},
		{"Datastore.AllocateSpace", storage, "the disk a clone allocates"},
	}
	if pf.prereqs.GuestAgent {
		// One privilege, not two. Proxmox accepts either VM.GuestAgent.FileWrite
		// or VM.GuestAgent.Unrestricted for writing a file into a guest, and
		// requires Unrestricted for running a command in one -- so Unrestricted
		// alone is enough for both halves of the bootstrap, and asking for
		// FileWrite as well refuses a token that was granted exactly what the
		// runbook asks for.
		required = append(required,
			privilege{"VM.GuestAgent.Unrestricted", vms, "writing the enrolment file inside a machine and running the one command that starts its agent, then reading back what it said when it failed"},
		)
	}
	return required
}

func (pf *preflight) checkPrivileges(ctx context.Context) {
	perms, err := pf.client.Permissions(ctx)
	if err != nil {
		pf.explainFailure(err, "read the token's own permissions")
		return
	}
	for _, want := range pf.requiredPrivileges() {
		if hasAnyPrivilege(perms, want.paths, want.name) {
			continue
		}
		path := want.paths[0]
		pf.add(config.Finding{
			Code: "proxmox.privilege_missing", Severity: config.SeverityError, Setting: SettingTokenID,
			Title:  fmt.Sprintf("the API token is missing %s on %s", want.name, path),
			Detail: want.why + " will be refused without it.",
			Fix: fmt.Sprintf("grant it: pveum acl modify %s --tokens '%s' --roles <a role holding %s>, or Datacenter -> Permissions -> API Tokens in the console.",
				path, pf.client.TokenID(), want.name),
		})
	}
}

// hasAnyPrivilege reports whether a privilege is held on any of the paths that
// would grant it.
func hasAnyPrivilege(perms Permissions, paths []string, name string) bool {
	for _, path := range paths {
		if hasPrivilege(perms, path, name) {
			return true
		}
	}
	return false
}

// hasPrivilege reports whether a token holds one privilege on one path.
//
// Proxmox answers with the paths a token has anything on, each privilege
// carrying a propagate flag, so a grant on "/" with propagation covers
// "/vms/9000" and one without it covers "/" alone. Walking the path upwards is
// what makes a cluster-wide role mean what an operator thinks it means -- a
// check that only looked at the exact path would tell somebody holding
// PVEVMAdmin on / that they are missing every privilege they have.
func hasPrivilege(perms Permissions, path, name string) bool {
	for at := path; ; {
		if propagate, ok := perms[at][name]; ok && (at == path || bool(propagate)) {
			return true
		}
		if at == "/" {
			return false
		}
		if i := strings.LastIndex(at, "/"); i > 0 {
			at = at[:i]
		} else {
			at = "/"
		}
	}
}

func (pf *preflight) checkResources(ctx context.Context) {
	nodes, err := pf.client.Nodes(ctx)
	if err != nil {
		pf.explainFailure(err, "list the cluster's nodes")
		return
	}
	known := map[string]Node{}
	for _, n := range nodes {
		known[n.Node] = n
	}

	wanted := pf.prereqs.Nodes
	if len(wanted) == 0 {
		pf.add(config.Finding{
			Code: "proxmox.node_missing", Severity: config.SeverityError, Setting: SettingNodes,
			Title:  "no node is configured",
			Detail: "there is nowhere for a machine to be built.",
			Fix:    "choose at least one node; this cluster offers " + join(nodeNames(nodes)) + ".",
		})
		return
	}

	var usable []string
	for _, name := range wanted {
		node, ok := known[name]
		switch {
		case !ok:
			pf.add(config.Finding{
				Code: "proxmox.node_missing", Severity: config.SeverityError, Setting: SettingNodes,
				Title:  fmt.Sprintf("this cluster has no node called %q", name),
				Detail: "either the name is wrong or the API token cannot see the node. The cluster reports " + join(nodeNames(nodes)) + ".",
				Fix:    "correct the node name, or grant the token Sys.Audit on /nodes so it can see the whole cluster.",
			})
		case !node.Online():
			pf.add(config.Finding{
				Code: "proxmox.node_offline", Severity: config.SeverityWarning, Setting: SettingNodes,
				Title:  fmt.Sprintf("node %s is %s", name, node.Status),
				Detail: "machines placed there will not be built until it comes back.",
				Fix:    "bring the node back, or take it out of this provider's nodes while it is down.",
			})
		default:
			usable = append(usable, name)
		}
	}

	for _, node := range usable {
		pf.checkStorage(ctx, node)
		pf.checkBridge(ctx, node)
	}
	pf.checkTemplate(ctx, usable)
}

func (pf *preflight) checkStorage(ctx context.Context, node string) {
	want := strings.TrimSpace(pf.prereqs.Storage)
	if want == "" {
		pf.add(config.Finding{
			Code: "proxmox.storage_missing", Severity: config.SeverityError, Setting: SettingStorage,
			Title:  "no storage is configured",
			Detail: "a clone has nowhere to put the machine's disk.",
			Fix:    "choose a storage that accepts disk images.",
		})
		return
	}
	storages, err := pf.client.Storages(ctx, node)
	if err != nil {
		pf.explainFailure(err, "list the storages on "+node)
		return
	}
	for _, s := range storages {
		if s.Storage != want {
			continue
		}
		switch {
		case !s.Accepts("images"):
			pf.add(config.Finding{
				Code: "proxmox.storage_no_images", Severity: config.SeverityError, Setting: SettingStorage,
				Title:  fmt.Sprintf("storage %s on %s does not hold disk images", want, node),
				Detail: fmt.Sprintf("it is configured for %q, so a clone into it will be refused.", s.Content),
				Fix:    "choose a storage whose content types include images, or add images to this one.",
			})
		case !bool(s.Enabled) || !bool(s.Active):
			pf.add(config.Finding{
				Code: "proxmox.storage_inactive", Severity: config.SeverityError, Setting: SettingStorage,
				Title:  fmt.Sprintf("storage %s is not active on %s", want, node),
				Detail: "a clone into a storage that is disabled or offline fails at the first machine.",
				Fix:    "enable the storage on this node, or place machines on a node where it is active.",
			})
		}
		return
	}
	pf.add(config.Finding{
		Code: "proxmox.storage_missing", Severity: config.SeverityError, Setting: SettingStorage,
		Title:  fmt.Sprintf("node %s has no storage called %q", node, want),
		Detail: "machines placed on this node cannot be given a disk. It offers " + join(storageNames(storages)) + ".",
		Fix:    "choose a storage this node can see -- a shared one if machines are placed on several nodes.",
	})
}

func (pf *preflight) checkBridge(ctx context.Context, node string) {
	want := strings.TrimSpace(pf.prereqs.Bridge)
	if want == "" {
		pf.add(config.Finding{
			Code: "proxmox.bridge_missing", Severity: config.SeverityError, Setting: SettingBridge,
			Title:  "no network bridge is configured",
			Detail: "a machine with no network cannot reach this controller, so it can never enrol.",
			Fix:    "choose the bridge the rest of this network uses, usually vmbr0.",
		})
		return
	}
	bridges, err := pf.client.Bridges(ctx, node)
	if err != nil {
		pf.explainFailure(err, "list the network bridges on "+node)
		return
	}
	for _, b := range bridges {
		if b.Iface == want {
			return
		}
	}
	pf.add(config.Finding{
		Code: "proxmox.bridge_missing", Severity: config.SeverityError, Setting: SettingBridge,
		Title:  fmt.Sprintf("node %s has no bridge called %q", node, want),
		Detail: "a machine built there would have no network and could never enrol. It offers " + join(bridgeNames(bridges)) + ".",
		Fix:    "use a bridge that exists on every node this provider places on.",
	})
}

func (pf *preflight) checkTemplate(ctx context.Context, usable []string) {
	if pf.prereqs.TemplateID <= 0 {
		pf.add(config.Finding{
			Code: "proxmox.template_missing", Severity: config.SeverityError, Setting: SettingTemplateID,
			Title:  "no template is configured",
			Detail: "every machine starts as a clone of one.",
			Fix:    "prepare a template as the runbook describes and give its VMID here.",
		})
		return
	}
	node := strings.TrimSpace(pf.prereqs.TemplateNode)
	if node == "" && len(usable) > 0 {
		node = usable[0]
	}
	if node == "" {
		return // The node findings above already say why nothing could be checked.
	}

	cfg, err := pf.client.VMConfig(ctx, node, pf.prereqs.TemplateID)
	if err != nil {
		if errors.Is(err, provider.ErrNotFound) {
			pf.add(config.Finding{
				Code: "proxmox.template_missing", Severity: config.SeverityError, Setting: SettingTemplateID,
				Title:  fmt.Sprintf("node %s has no guest with VMID %d", node, pf.prereqs.TemplateID),
				Detail: "there is nothing to clone.",
				Fix:    "give the VMID of the prepared template, and the node it lives on.",
			})
			return
		}
		pf.explainFailure(err, fmt.Sprintf("read the configuration of template %d on %s", pf.prereqs.TemplateID, node))
		return
	}
	if !bool(cfg.Template) {
		pf.add(config.Finding{
			Code: "proxmox.template_not_a_template", Severity: config.SeverityError, Setting: SettingTemplateID,
			Title:  fmt.Sprintf("VMID %d on %s is a virtual machine, not a template", pf.prereqs.TemplateID, node),
			Detail: "cloning a running guest copies whatever state it is in, and this fleet would be cloning something somebody else is using.",
			Fix:    "convert it to a template in the console, or point at one that already is.",
		})
		return
	}
	if pf.prereqs.GuestAgent && !cfg.AgentEnabled() {
		pf.add(config.Finding{
			Code: "proxmox.template_no_agent", Severity: config.SeverityWarning, Setting: SettingTemplateID,
			Title:  fmt.Sprintf("the QEMU guest agent is not enabled on template %d", pf.prereqs.TemplateID),
			Detail: "the agent is how the enrolment reaches a machine without ever putting it in the guest's metadata; machines cloned from this template will boot and never enrol.",
			Fix:    "set agent: 1 (Options -> QEMU Guest Agent) on the template, and make sure the guest has qemu-guest-agent installed.",
		})
	}
}

func fallback(s, or string) string {
	if strings.TrimSpace(s) != "" {
		return s
	}
	return or
}

func nodeNames(nodes []Node) []string {
	out := make([]string, 0, len(nodes))
	for _, n := range nodes {
		out = append(out, n.Node)
	}
	return out
}

func storageNames(storages []Storage) []string {
	out := make([]string, 0, len(storages))
	for _, s := range storages {
		if s.Accepts("images") {
			out = append(out, s.Storage)
		}
	}
	return out
}

func bridgeNames(bridges []NetworkInterface) []string {
	out := make([]string, 0, len(bridges))
	for _, b := range bridges {
		out = append(out, b.Iface)
	}
	return out
}

// join lists what the cluster actually offers, because a finding that says a
// name is wrong and does not say what the right ones are sends somebody to the
// console to look.
func join(names []string) string {
	switch len(names) {
	case 0:
		return "nothing this token can see"
	case 1:
		return names[0]
	default:
		return strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
	}
}

package proxmox

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
)

// healthyPrereqs is a configuration the fake cluster can actually satisfy: one
// node, a storage that node can see and the token may allocate on, a bridge
// that exists, and the prepared template.
func healthyPrereqs() Prereqs {
	return Prereqs{
		Nodes: []string{"pve-1"}, Storage: "local-lvm", Bridge: "vmbr0",
		TemplateNode: "pve-1", TemplateID: 9000,
		VMIDMin: 9100, VMIDMax: 9199, GuestAgent: true,
	}
}

func codes(r provider.Report) []string {
	out := make([]string, 0, len(r.Findings))
	for _, f := range r.Findings {
		out = append(out, f.Code)
	}
	return out
}

func finding(t *testing.T, r provider.Report, code string) config.Finding {
	t.Helper()
	for _, f := range r.Findings {
		if f.Code == code {
			return f
		}
	}
	t.Fatalf("no %s finding; got %v", code, codes(r))
	return config.Finding{}
}

// Preflight is what an operator presses before anything is created, so a
// cluster that is ready has to come back with nothing to say.
func TestAClusterThatIsReadyPassesPreflight(t *testing.T) {
	f := newFakePVE(t, nil)

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	if !report.Reachable {
		t.Fatalf("the cluster answered but was reported unreachable: %v", codes(report))
	}
	if !report.OK() {
		t.Errorf("a ready cluster raised %v", codes(report))
	}
	if report.Version != "8.2.4" {
		t.Errorf("Version = %q; the qualification record is worth little without it", report.Version)
	}
}

// A missing privilege has to name the privilege and the path, because "403" or
// "check your permissions" sends an operator reading eleven role definitions to
// find out which of them they need.
func TestAMissingPrivilegeBecomesAFindingNamingIt(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetPermissions(Permissions{
		"/vms": {
			"VM.Allocate": true, "VM.Audit": true, "VM.PowerMgmt": true,
			"VM.Config.Disk": true, "VM.Config.CPU": true, "VM.Config.Memory": true,
			"VM.Config.Network": true, "VM.Config.Options": true,
			"VM.GuestAgent.FileWrite": true, "VM.GuestAgent.Unrestricted": true,
		},
		"/storage/local-lvm": {"Datastore.AllocateSpace": true},
	})

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	if report.OK() {
		t.Fatal("a token that cannot clone the template was reported as ready")
	}
	got := finding(t, report, "proxmox.privilege_missing")
	if got.Severity != config.SeverityError {
		t.Errorf("severity = %q, want error: nothing can be built without it", got.Severity)
	}
	for _, want := range []string{"VM.Clone", "/vms/9000"} {
		if !strings.Contains(got.Title, want) {
			t.Errorf("the title %q does not name %q", got.Title, want)
		}
	}
	for _, want := range []string{"pveum acl modify", "/vms/9000", tokenID, "VM.Clone"} {
		if !strings.Contains(got.Fix, want) {
			t.Errorf("the fix %q does not name %q", got.Fix, want)
		}
	}
	if !strings.Contains(got.Detail, "clon") {
		t.Errorf("the detail %q does not say what the privilege buys", got.Detail)
	}
}

// The bootstrap privileges are only asked for when the bootstrap needs them: a
// fleet told to leave the guest agent alone must not be warned about privileges
// it will never use.
func TestTheGuestAgentPrivilegesAreOnlyRequiredWhenTheAgentIsUsed(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetPermissions(Permissions{
		"/vms": {
			"VM.Clone": true, "VM.Allocate": true, "VM.Audit": true, "VM.PowerMgmt": true,
			"VM.Config.Disk": true, "VM.Config.CPU": true, "VM.Config.Memory": true,
			"VM.Config.Network": true, "VM.Config.Options": true,
		},
		"/storage/local-lvm": {"Datastore.AllocateSpace": true},
	})

	without := healthyPrereqs()
	without.GuestAgent = false
	if report := Preflight(context.Background(), f.client(t), without); !report.OK() {
		t.Errorf("a fleet that does not use the guest agent was refused: %v", codes(report))
	}

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	if report.OK() {
		t.Fatal("a bootstrap through the guest agent was accepted without the privileges it needs")
	}
	if !strings.Contains(finding(t, report, "proxmox.privilege_missing").Title, "VM.GuestAgent") {
		t.Error("the finding does not name the guest agent privilege")
	}
}

// A cluster-wide role is how most operators grant this, and a check that only
// looked at the exact path would tell somebody holding PVEVMAdmin on / that
// they are missing every privilege they have.
func TestAPrivilegeGrantedHigherUpCountsWhenItPropagates(t *testing.T) {
	tests := []struct {
		name  string
		perms Permissions
		path  string
		want  bool
	}{
		{"granted on the path itself", Permissions{"/vms": {"VM.Clone": true}}, "/vms", true},
		{"granted on the path itself without propagation", Permissions{"/vms": {"VM.Clone": false}}, "/vms", true},
		{"granted at the root and propagating", Permissions{"/": {"VM.Clone": true}}, "/vms/9000", true},
		{"granted at the root and not propagating", Permissions{"/": {"VM.Clone": false}}, "/vms/9000", false},
		{"granted one level up and propagating", Permissions{"/vms": {"VM.Clone": true}}, "/vms/9000", true},
		{"granted further down, which covers nothing above it", Permissions{"/vms/9000": {"VM.Clone": true}}, "/vms", false},
		{"a different privilege entirely", Permissions{"/vms": {"VM.Audit": true}}, "/vms", false},
		{"a token with nothing at all", Permissions{}, "/vms", false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := hasPrivilege(tc.perms, tc.path, "VM.Clone"); got != tc.want {
				t.Errorf("hasPrivilege(%v, %q) = %v, want %v", tc.perms, tc.path, got, tc.want)
			}
		})
	}
}

// A pool is the tighter way to grant this, and an operator who chose it is
// right: privileges on the pool cover the guests inside it.
func TestAPrivilegeGrantedOnThePoolIsEnough(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetPermissions(Permissions{
		"/pool/zoomies": {
			"VM.Clone": true, "VM.Allocate": true, "VM.Audit": true, "VM.PowerMgmt": true,
			"VM.Config.Disk": true, "VM.Config.CPU": true, "VM.Config.Memory": true,
			"VM.Config.Network": true, "VM.Config.Options": true,
			"VM.GuestAgent.FileWrite": true, "VM.GuestAgent.Unrestricted": true,
		},
		"/storage/local-lvm": {"Datastore.AllocateSpace": true},
	})
	prereqs := healthyPrereqs()
	prereqs.Pool = "zoomies"

	if report := Preflight(context.Background(), f.client(t), prereqs); !report.OK() {
		t.Errorf("a token scoped to the pool it creates in was refused: %v", codes(report))
	}
}

// Preflight never returns an error: a cluster that cannot be reached is an
// answer an operator can act on, and one problem rather than eleven.
func TestPreflightReportsASilentClusterRatherThanFailing(t *testing.T) {
	c, err := New(Options{Endpoint: "https://" + deadAddress(t), TokenID: tokenID, Secret: tokenSecret, Insecure: true})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	report := Preflight(context.Background(), c, healthyPrereqs())
	if report.Reachable {
		t.Error("a cluster that never answered was reported reachable")
	}
	if report.OK() {
		t.Error("a cluster that never answered was reported as ready")
	}
	got := finding(t, report, "proxmox.unreachable")
	if got.Severity != config.SeverityError {
		t.Errorf("severity = %q, want error", got.Severity)
	}
	if got.Fix == "" {
		t.Error("the finding says nothing to do about it")
	}
	// Listing the ten checks that could not run would bury the one that matters.
	if len(report.Findings) > 2 {
		t.Errorf("an unreachable cluster produced %d findings: %v", len(report.Findings), codes(report))
	}
}

// A refused credential and a missing privilege lead to different afternoons, so
// preflight keeps them apart even when both arrive as a failed call.
func TestARefusedTokenIsAFindingOfItsOwn(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetError(http.MethodGet, "/version", http.StatusUnauthorized, "authentication failure")

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	got := finding(t, report, "proxmox.credentials_refused")
	if !strings.Contains(got.Fix, "secret") {
		t.Errorf("the fix %q does not say what to check", got.Fix)
	}
}

// The range needs no hypervisor, so it is answered even when nothing else can
// be: a provider with no range configured is misconfigured either way.
func TestAVMIDRangeIsCheckedEvenWhenTheClusterIsSilent(t *testing.T) {
	c, err := New(Options{Endpoint: "https://" + deadAddress(t), TokenID: tokenID, Secret: tokenSecret, Insecure: true})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	tests := []struct {
		name     string
		lo, hi   int
		wantCode string
	}{
		{"no range at all", 0, 0, "proxmox.vmid_range"},
		{"a range that runs backwards", 9199, 9100, "proxmox.vmid_range"},
		{"a range inside what Proxmox reserves", 50, 99, "proxmox.vmid_range_reserved"},
		{"a range of one", 9100, 9100, ""},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			prereqs := healthyPrereqs()
			prereqs.VMIDMin, prereqs.VMIDMax = tc.lo, tc.hi
			report := Preflight(context.Background(), c, prereqs)
			has := false
			for _, code := range codes(report) {
				if code == tc.wantCode {
					has = true
				}
				if strings.HasPrefix(code, "proxmox.vmid_range") && tc.wantCode == "" {
					t.Errorf("a usable range raised %s", code)
				}
			}
			if tc.wantCode != "" && !has {
				t.Errorf("got %v, want %s", codes(report), tc.wantCode)
			}
		})
	}
}

// Every resource an operator named has to exist and be usable, and every
// finding has to say what the cluster does offer -- one that says a name is
// wrong without saying what is right sends somebody to the console to look.
func TestEveryConfiguredResourceIsChecked(t *testing.T) {
	tests := []struct {
		name     string
		adjust   func(*Prereqs)
		wantCode string
		wantIn   string
	}{
		{"a node this cluster does not have", func(p *Prereqs) { p.Nodes = []string{"pve-9"} }, "proxmox.node_missing", "pve-1"},
		{"a node that is down", func(p *Prereqs) { p.Nodes = []string{"pve-1", "pve-3"} }, "proxmox.node_offline", "pve-3"},
		{"no node at all", func(p *Prereqs) { p.Nodes = nil }, "proxmox.node_missing", "pve-2"},
		{"a storage that node cannot see", func(p *Prereqs) { p.Storage = "nvme-fast" }, "proxmox.storage_missing", "local-lvm"},
		{"a storage that holds no disk images", func(p *Prereqs) { p.Storage = "local" }, "proxmox.storage_no_images", "iso,vztmpl"},
		{"a bridge that does not exist", func(p *Prereqs) { p.Bridge = "vmbr9" }, "proxmox.bridge_missing", "vmbr0"},
		{"no bridge at all", func(p *Prereqs) { p.Bridge = "" }, "proxmox.bridge_missing", "vmbr0"},
		{"a template that is not there", func(p *Prereqs) { p.TemplateID = 9999 }, "proxmox.template_missing", "9999"},
		{"a running machine offered as a template", func(p *Prereqs) { p.TemplateID = 100 }, "proxmox.template_not_a_template", "100"},
		{"no template at all", func(p *Prereqs) { p.TemplateID = 0 }, "proxmox.template_missing", "clone"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			f := newFakePVE(t, nil)
			prereqs := healthyPrereqs()
			tc.adjust(&prereqs)

			report := Preflight(context.Background(), f.client(t), prereqs)
			got := finding(t, report, tc.wantCode)
			if !strings.Contains(got.Title+" "+got.Detail+" "+got.Fix, tc.wantIn) {
				t.Errorf("the finding does not mention %q: %+v", tc.wantIn, got)
			}
			if got.Setting == "" {
				t.Error("the finding names no setting, so the wizard cannot point at the field")
			}
		})
	}
}

// A template with the guest agent switched off produces machines that boot and
// never enrol, which is a slow and baffling failure to debug from the outside.
func TestATemplateWithoutTheGuestAgentIsWarnedAbout(t *testing.T) {
	f := newFakePVE(t, nil)
	f.mu.Lock()
	f.vms[9000].agent = ""
	f.mu.Unlock()

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	got := finding(t, report, "proxmox.template_no_agent")
	if got.Severity != config.SeverityWarning {
		t.Errorf("severity = %q, want a warning: the machine may still be built", got.Severity)
	}
	if !strings.Contains(got.Fix, "qemu-guest-agent") {
		t.Errorf("the fix %q does not say what the template needs", got.Fix)
	}
}

// An unqualified release is not a broken one. Refusing would strand an operator
// whose cluster may work perfectly well; the warning is what tells them nobody
// has checked.
func TestAnUnqualifiedProxmoxWarnsRatherThanStops(t *testing.T) {
	f := newFakePVE(t, map[string]http.HandlerFunc{
		"GET " + v + "/version": func(w http.ResponseWriter, r *http.Request) {
			writeData(w, map[string]any{"version": "7.4-17", "release": "7.4"})
		},
	})

	report := Preflight(context.Background(), f.client(t), healthyPrereqs())
	got := finding(t, report, "proxmox.version_unqualified")
	if got.Severity != config.SeverityWarning {
		t.Errorf("severity = %q, want a warning", got.Severity)
	}
	if !report.OK() {
		t.Errorf("an older release stopped a provider that is otherwise ready: %v", codes(report))
	}
	if !strings.Contains(got.Title, MinPVEVersion) {
		t.Errorf("the title %q does not say what was qualified", got.Title)
	}
}

// Verification turned off is the setting that weakens the posture most, so it
// is said every time preflight runs rather than once in a log nobody kept.
func TestVerificationTurnedOffIsAWarningEveryTime(t *testing.T) {
	f := newFakePVE(t, nil)
	c, err := New(Options{Endpoint: f.URL, TokenID: tokenID, Secret: tokenSecret, Insecure: true})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	for i := range 2 {
		report := Preflight(context.Background(), c, healthyPrereqs())
		got := finding(t, report, "proxmox.insecure_tls")
		if got.Severity != config.SeverityWarning {
			t.Errorf("pass %d: severity = %q, want a warning", i, got.Severity)
		}
		if !strings.Contains(got.Fix, "pve-root-ca.pem") {
			t.Errorf("pass %d: the fix %q does not say what to paste", i, got.Fix)
		}
	}
}

package proxmox

// The provider itself: everything internal/provider asks of an infrastructure
// provider, spoken to one Proxmox VE cluster.
//
// Three things about the shape of this file are decided by the Proxmox API
// rather than by taste, and are what to understand before changing it.
//
//   - A clone is asynchronous and holds a lock on the new guest until it
//     finishes, so nothing can be sized, tagged or started while it runs.
//     Create therefore does the one thing that can be done in a single call --
//     the clone, carrying the guest's name and its ownership record, both of
//     which the clone endpoint accepts -- and hands back the task handle.
//     Sizing, tagging and starting belong to Start, which runs at the first
//     moment the guest is unlocked.
//   - Start is given a ref and no spec, so the shape a machine was asked for
//     has to survive the gap between the two calls without living in this
//     process's memory: a controller may restart in between, and a machine
//     that came back the template's size rather than the operator's would be
//     wrong in a way nothing would ever report. It travels in the guest's own
//     description, beside the ownership record, and is read back there.
//   - Nothing here waits for a task. Every call returns as soon as the cluster
//     has taken the work, and the UPID it returns is what follows it, because
//     one reconcile step is budgeted for about two requests and a full clone
//     takes minutes. The one exception is the guest agent, which has no task
//     to hand back at all; bootstrap.go says what it does instead.
//
// Nothing in this package decides how many machines should exist, when to give
// up or what may be deleted. That is one reconciler's job for every provider.

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"math"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/config"
	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// The budgets this provider asks for. They are its own honest estimate of how
// long each piece of work takes on a cluster that is behaving; the controller
// applies the larger of these and the operator's configuration, so these are a
// floor under supervision and never a way around it.
const (
	callBudget      = 30 * time.Second
	allocateBudget  = time.Minute
	createBudget    = 20 * time.Minute
	bootstrapBudget = 10 * time.Minute
	deleteBudget    = 15 * time.Minute
)

// allocateAttempts bounds the re-picking of an identifier somebody took between
// the listing and the assertion. It is small on purpose: a handful of races is
// a busy cluster, and a hundred of them is a range with nothing free in it,
// which is a different answer and has its own finding.
const allocateAttempts = 5

// shutdownGrace is how long a guest is given to shut itself down before the
// power is pulled, on the way to being destroyed. Its host has already been
// drained by the time anything here runs, so nothing is mid-job; the grace is
// for the filesystem, not for the work.
const shutdownGrace = 60 * time.Second

// Provider rents virtual machines from one Proxmox VE cluster.
//
// It holds the credential for the life of the client it built and writes it
// nowhere. Everything else it needs is in the settings the operator answered,
// parsed once here so that a mistake in them is an error when the provider is
// built rather than a failure at the first clone.
type Provider struct {
	client   *Client
	settings settings
	caps     provider.Capabilities
	log      *slog.Logger
}

// NewProvider builds a provider for one stored configuration row.
//
// It never dials: an unreachable cluster is Preflight's answer to give, for the
// reason backend.Probe reports an absent Docker rather than failing to
// construct -- a controller that would not start because a hypervisor was
// rebooting could not even show an operator why.
func NewProvider(cfg provider.Config) (*Provider, error) {
	set, findings := parseSettings(cfg.Settings)
	if err := refuse(findings); err != nil {
		return nil, err
	}
	tokenID, secret, err := splitCredential(set.tokenID, cfg.Credential)
	if err != nil {
		return nil, err
	}
	log := cfg.Logger
	if log == nil {
		log = slog.Default()
	}
	client, err := New(Options{
		Endpoint:    cfg.Endpoint,
		TokenID:     tokenID,
		Secret:      secret,
		CAPEM:       cfg.CAPEM,
		Insecure:    cfg.Insecure,
		DialContext: cfg.DialContext,
		HTTPClient:  cfg.HTTPClient,
		Logger:      log,
	})
	if err != nil {
		return nil, err
	}
	return &Provider{
		client:   client,
		settings: set,
		caps:     capabilities(cfg.Deadlines),
		log:      log.With("component", "provider.proxmox"),
	}, nil
}

func (p *Provider) Kind() store.ProviderKind { return store.ProviderProxmox }

func (p *Provider) Capabilities() provider.Capabilities { return p.caps }

// capabilities is what this provider can do, declared rather than discovered.
//
// The deadlines are the larger of this provider's own and the operator's, kept
// in the order the contract requires: a call may not be budgeted more than the
// allocate it is part of, and an allocate no more than a create.
func capabilities(operator provider.Deadlines) provider.Capabilities {
	d := provider.Deadlines{
		Call:      longest(callBudget, operator.Call),
		Allocate:  longest(allocateBudget, operator.Allocate),
		Create:    longest(createBudget, operator.Create),
		Bootstrap: longest(bootstrapBudget, operator.Bootstrap),
		Delete:    longest(deleteBudget, operator.Delete),
	}
	d.Allocate = longest(d.Allocate, d.Call)
	d.Create = longest(d.Create, d.Allocate)
	return provider.Capabilities{
		MinContract:      provider.ContractVersion,
		MaxContract:      provider.ContractVersion,
		Kind:             store.ProviderProxmox,
		Label:            "Proxmox VE",
		Bootstrap:        provider.BootstrapGuestAgent,
		CanStartStop:     true,
		CanDiscover:      true,
		CanMarkOwnership: true,
		AsyncOperations:  true,
		// No cost unit: a cluster somebody already owns has no per-machine
		// price this integration could honestly quote, which is not the same
		// as a machine being free.
		CostUnit:        "",
		Deadlines:       d,
		EndpointExample: "https://pve.example.com:8006",
		EndpointSource: "The URL you open the Proxmox console at, port 8006 included: https://<any node>:8006. " +
			"HTTPS only; the token would otherwise cross the network in the clear.",
		CredentialSource: "Datacenter -> Permissions -> API Tokens. Add a token to a dedicated user (zoomies@pve) with " +
			"privilege separation on; Proxmox shows the secret once. Paste the whole line, user@realm!tokenid=secret.",
		CASource: "/etc/pve/pve-root-ca.pem on any node -- the certificate, not the .key beside it. " +
			"Leave it empty when the cluster's certificate is signed by a public CA.",
		Guide: guide(),
	}
}

// guide is what has to exist on the cluster before this provider can rent a
// machine. It is served with the kind, so the wizard shows it before its first
// question and the CLI can print it, and the docs page says the same things
// at more length.
//
// Proxmox ships no templates, and the standard answer is a distribution's
// cloud image imported with qm: the commands below are that recipe for the
// one image that has been qualified, and the only step that cannot be a
// command is the one done inside the guest.
func guide() []provider.GuideStep {
	return []provider.GuideStep{
		{
			Title: "A Proxmox VE 8 cluster this controller can reach",
			Detail: "The API listens on port 8006 over HTTPS on every node; https://<node>:8006 is the address " +
				"the form asks for. A cluster on a home network with no route from the controller can be " +
				"reached through `zoomies gateway` instead: run it beside the cluster and choose a private connection.",
		},
		{
			Title: "An API token that can clone, start and delete guests",
			Detail: "Datacenter -> Permissions -> Users: add zoomies@pve. Then API Tokens: add a token to it with " +
				"privilege separation on, and copy the whole line Proxmox prints once, user@realm!tokenid=secret. " +
				"Grant the token VM.Clone on the template, and VM.Allocate, VM.Audit, VM.Config.*, VM.PowerMgmt " +
				"and VM.GuestAgent.Unrestricted on /vms, plus Datastore.AllocateSpace on the storage. The check " +
				"after saving names any privilege that is missing. Or, on any node, as root:",
			Command: `pveum user add zoomies@pve
pveum role add Zoomies -privs "VM.Clone VM.Allocate VM.Audit VM.Config.Disk VM.Config.CPU VM.Config.Memory VM.Config.Network VM.Config.Options VM.PowerMgmt VM.GuestAgent.Unrestricted Datastore.AllocateSpace"
pveum acl modify /vms -user zoomies@pve -role Zoomies
pveum acl modify /storage/local-lvm -user zoomies@pve -role Zoomies
pveum user token add zoomies@pve ci --privsep 1`,
		},
		{
			Title: "A template with Docker, the guest agent and the Zoomies agent in it",
			Detail: "Proxmox ships no templates. Start from Ubuntu 24.04's cloud image, which is the one that has " +
				"been qualified: import it as a VM, boot it once, install what a runner needs inside, and convert " +
				"it. Inside the guest: the Docker engine, qemu-guest-agent, and `zoomies agent install`, which " +
				"leaves the agent's service disabled for this controller to enable in each clone. Never leave an " +
				"enrolled agent (/var/lib/zoomies/work/agent.json) in the template. On the node, as root:",
			Command: `wget https://cloud-images.ubuntu.com/noble/current/noble-server-cloudimg-amd64.img
qm create 9000 --name zoomies-template --memory 4096 --cores 2 --cpu host --ostype l26 \
  --net0 virtio,bridge=vmbr0 --scsihw virtio-scsi-pci --agent enabled=1 --serial0 socket --vga serial0
qm set 9000 --scsi0 local-lvm:0,import-from=$PWD/noble-server-cloudimg-amd64.img --boot order=scsi0
qm set 9000 --ide2 local-lvm:cloudinit --ciuser ubuntu --sshkeys ~/.ssh/id_ed25519.pub --ipconfig0 ip=dhcp
qm resize 9000 scsi0 32G && qm start 9000
# inside the guest, over ssh:
#   curl -fsSL https://get.docker.com | sh && sudo apt-get install -y qemu-guest-agent
#   curl -fsSL https://zoomies.sh/install.sh | sh -s -- --no-init && sudo zoomies agent install
#   sudo cloud-init clean && sudo poweroff
qm template 9000`,
		},
		{
			Title: "A block of VMIDs nothing else allocates from",
			Detail: "Zoomies takes the lowest free identifier inside the block, so it is both a budget and a blast " +
				"radius: a guest outside it is, by construction, not one of ours. 9000-9099 is the default; keep it " +
				"out of whatever your other tooling numbers from, and out of the template's own VMID.",
		},
	}
}

func longest(a, b time.Duration) time.Duration {
	if b > a {
		return b
	}
	return a
}

// Preflight checks configuration, credentials and prerequisites, changing
// nothing and never failing: what it reports is what an operator must fix.
func (p *Provider) Preflight(ctx context.Context) provider.Report {
	return Preflight(ctx, p.client, p.settings.prereqs())
}

// Discover lists what this credential can actually see, for the guided form.
func (p *Provider) Discover(ctx context.Context) (provider.Discovery, error) {
	return Discover(ctx, p.client)
}

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

// Allocate picks the node and the VMID a machine will have, and creates
// nothing. The caller writes what this returns down before anything can exist
// to be lost, which is what makes a create whose answer never came back
// something to look for rather than something to do again.
//
// The identifier is the lowest free one inside the configured range, computed
// from the cluster's own listing and then asserted free. Proxmox's "next free
// id" endpoint is not used to pick: it knows about the whole cluster and
// nothing about the range an operator allowed this provider, so a fleet driven
// by it would take identifiers somebody else's automation is entitled to. Its
// assertion form is used as the last check before the clone, and a refusal
// there means somebody won the race for that identifier -- a re-pick, not a
// failure.
func (p *Provider) Allocate(ctx context.Context, spec provider.MachineSpec) (provider.MachineRef, error) {
	guests, err := p.client.ClusterVMs(ctx)
	if err != nil {
		return provider.MachineRef{}, err
	}
	node, err := p.placeOn(guests)
	if err != nil {
		return provider.MachineRef{}, err
	}
	taken := make([]int, 0, len(guests))
	for _, g := range guests {
		taken = append(taken, g.VMID.Int())
	}

	for range allocateAttempts {
		vmid, err := NextFreeVMID(taken, p.settings.vmidMin, p.settings.vmidMax)
		if err != nil {
			return provider.MachineRef{}, err
		}
		err = p.client.AssertVMIDFree(ctx, vmid)
		switch provider.KindOf(err) {
		case "":
			return provider.MachineRef{Zone: node, ID: strconv.Itoa(vmid), Name: spec.Name}, nil
		case provider.FailureConflict, provider.FailureConfig:
			// Somebody took it between the listing and now. Proxmox reports
			// that from two places -- its parameter check and the cluster's
			// own -- so both are read as "taken" and the next identifier is
			// tried; anything else, a missing privilege above all, is the
			// caller's to see.
			taken = append(taken, vmid)
		default:
			return provider.MachineRef{}, err
		}
	}
	return provider.MachineRef{}, &provider.Error{
		Kind: provider.FailureConflict, Op: "allocate a VMID",
		Message: fmt.Sprintf("every identifier picked from %d-%d was taken by something else while it was being claimed",
			p.settings.vmidMin, p.settings.vmidMax),
		Remedy: "another tool is allocating inside this provider's VMID range; give Zoomies a block of its own",
	}
}

// placeOn chooses which node a machine is built on: the configured one with
// the fewest guests on it, and the first one configured when they are level.
//
// Spreading rather than filling is the only default that does not quietly put
// a whole fleet on one node, and counting every guest rather than only ours
// means a node somebody else has already filled is the last one chosen. The
// count comes from the listing Allocate already has, so this costs no call.
func (p *Provider) placeOn(guests []ClusterVM) (string, error) {
	if len(p.settings.nodes) == 0 {
		return "", &provider.Error{
			Kind: provider.FailureConfig, Op: "choose a node",
			Message: "this provider has no node configured, so there is nowhere to build a machine",
			Remedy:  "set nodes to at least one node of the cluster",
		}
	}
	counts := map[string]int{}
	for _, g := range guests {
		counts[g.Node]++
	}
	best := p.settings.nodes[0]
	for _, node := range p.settings.nodes[1:] {
		if counts[node] < counts[best] {
			best = node
		}
	}
	return best, nil
}

// ---------------------------------------------------------------------------
// Building
// ---------------------------------------------------------------------------

// Create clones the template into the identity Allocate picked.
//
// The clone carries the guest's name and its ownership record, which are the
// two marks that make it findable and provably ours from the moment it exists:
// a guest created with neither, whose answer was then lost, is a machine
// nothing could tell from somebody else's. Applying the tags and the machine's
// shape is Start's, because a clone holds a lock on its target until it
// finishes and nothing may be written to a locked guest; the shape a machine
// was asked for is recorded in that same description here, which is how Start
// knows it without having been told.
//
// Calling it twice for one ref builds one machine. That is what makes a create
// re-issued after an outcome nobody heard safe, and it is checked here by
// asking what is at the identifier before anything is cloned.
func (p *Provider) Create(ctx context.Context, ref provider.MachineRef, spec provider.MachineSpec) (provider.OperationRef, error) {
	node, vmid, err := p.locate(ref, "create a machine")
	if err != nil {
		return provider.OperationRef{}, err
	}

	switch existing, err := p.client.VMStatus(ctx, node, vmid); {
	case err == nil && existing.Name != "" && existing.Name != ref.Name:
		return provider.OperationRef{}, &provider.Error{
			Kind: provider.FailureConflict, Op: "create a machine", Ref: vmRef(node, vmid),
			Message: fmt.Sprintf("VMID %d on %s is already a guest called %q, so this machine's identifier belongs to something else",
				vmid, node, existing.Name),
			Remedy: "nothing has been created; the machine is given a new identifier, and a VMID range nothing else allocates from stops this happening",
		}
	case err == nil:
		// Already built, by an earlier call whose answer may never have
		// arrived. There is nothing to follow and nothing to do again.
		return provider.OperationRef{}, nil
	case errors.Is(err, provider.ErrNotFound):
	default:
		return provider.OperationRef{}, err
	}

	req := CloneRequest{
		NewID:       vmid,
		Name:        ref.Name,
		Full:        p.settings.fullClone,
		Storage:     p.settings.storage,
		Pool:        p.settings.pool,
		Description: describeMachine(spec.Owner, ref.Name, spec.Shape),
	}
	if node != p.templateNode() {
		// Proxmox only allows a clone to land on another node when the
		// template's disk is on shared storage, and says so plainly when it
		// is not -- so this is left off entirely for the ordinary case rather
		// than sending a node that is already the right one.
		req.Target = node
	}
	upid, err := p.client.CloneVM(ctx, p.templateNode(), p.settings.templateID, req)
	if err != nil {
		return provider.OperationRef{}, err
	}
	return provider.OperationRef{Kind: provider.OpCreate, Handle: upid}, nil
}

// Start sizes a machine, marks it, and powers it on.
//
// All three are here because a clone locks its target until it finishes, and
// this is the first call that runs after it: the guest is stopped, unlocked,
// and about to be handed to an operating system that will read its processors
// and memory once at boot. The shape comes off the guest's own description,
// where Create recorded it, so that a controller which restarted between the
// two calls still builds the machine the operator asked for.
func (p *Provider) Start(ctx context.Context, ref provider.MachineRef) (provider.OperationRef, error) {
	node, vmid, err := p.locate(ref, "start a machine")
	if err != nil {
		return provider.OperationRef{}, err
	}
	status, err := p.client.VMStatus(ctx, node, vmid)
	if err != nil {
		return provider.OperationRef{}, err
	}
	if status.Status == statusRunning {
		// Already running: there is nothing to follow, and configuring a
		// running guest would change nothing it has already read.
		return provider.OperationRef{}, nil
	}
	if status.Lock != "" {
		return provider.OperationRef{}, lockedError("start a machine", node, vmid, status.Lock)
	}

	cfg, err := p.client.VMConfig(ctx, node, vmid)
	if err != nil {
		return provider.OperationRef{}, err
	}
	if err := p.configure(ctx, node, vmid, cfg); err != nil {
		return provider.OperationRef{}, err
	}
	upid, err := p.client.StartVM(ctx, node, vmid)
	if err != nil {
		return provider.OperationRef{}, err
	}
	return provider.OperationRef{Kind: provider.OpStart, Handle: upid}, nil
}

// configure gives a guest the shape it was asked for, the network the operator
// chose, and the tags that let a cluster-wide listing find it.
//
// It is idempotent: every value is written absolutely rather than adjusted, so
// a pass that failed halfway is fixed by running again. The disk is the one
// exception -- Proxmox will not shrink one, and a shape asking for less than
// the template has is honoured by leaving the disk alone rather than by
// risking a filesystem.
func (p *Provider) configure(ctx context.Context, node string, vmid int, cfg VMConfig) error {
	shape, haveShape := decodeShape(cfg.Description)
	params := url.Values{
		// The guest agent is how the enrolment reaches this machine without
		// ever entering its metadata, so it is switched on here as well as in
		// the template: a template prepared without it would otherwise produce
		// machines that boot, cost money and never join.
		"agent": {"1"},
		// Never on boot. A machine this fleet rents is started when the fleet
		// starts it; one that came back by itself after a hypervisor reboot
		// would be a host nothing is accounting for.
		"onboot": {"0"},
	}
	if p.settings.bridge != "" {
		params.Set("net0", netDevice(cfg.Net0, p.settings.bridge))
	}
	if p.settings.ipConfig != "" {
		params.Set("ipconfig0", p.settings.ipConfig)
	}
	if p.settings.nameserver != "" {
		params.Set("nameserver", p.settings.nameserver)
	}
	if haveShape {
		if shape.Cores > 0 {
			params.Set("cores", strconv.Itoa(shape.Cores))
			params.Set("sockets", "1")
		}
		if shape.MemoryMB > 0 {
			params.Set("memory", strconv.FormatInt(shape.MemoryMB, 10))
		}
	} else {
		// The record is written by the clone, so its absence means this guest
		// was made by something else or by an older build. Everything above
		// still applies; the size is the one thing that cannot be guessed, and
		// silently building the template's size is worth saying out loud.
		p.log.Warn("a machine carries no record of the shape it was asked for, so it keeps the template's processors, memory and disk",
			"node", node, "vmid", vmid,
			"fix", "delete this machine and let the fleet build another, which will carry the record")
	}
	if owner, ok := DecodeOwner(cfg.Description); ok {
		// Merged with whatever the guest already carries, so a tag an operator
		// added by hand survives being configured.
		params.Set("tags", EncodeTags(cfg.Tags, Tags(owner)))
	}

	if _, err := p.client.ConfigureVM(ctx, node, vmid, params); err != nil {
		return err
	}
	if !haveShape || shape.DiskMB <= 0 {
		return nil
	}
	return p.growDisk(ctx, node, vmid, cfg, shape.DiskMB)
}

// growDisk grows the boot disk to the shape's size, and only ever grows it.
//
// A resize that is not needed is not attempted at all: Proxmox refuses a size
// that is not larger than the current one, and a provider that asked anyway
// would turn every start of an already-correct machine into a failure.
func (p *Provider) growDisk(ctx context.Context, node string, vmid int, cfg VMConfig, wantMB int64) error {
	disk, spec := bootDisk(cfg)
	if disk == "" {
		p.log.Warn("a machine has no disk this build recognises, so its size is left as the template's",
			"node", node, "vmid", vmid)
		return nil
	}
	haveMB, ok := diskSizeMB(spec)
	if !ok {
		// A size that cannot be read is left alone rather than guessed at:
		// Proxmox refuses a resize that is not an increase, so a guess that is
		// too small turns every start of this machine into a failure, and a
		// machine that came up slightly smaller than it was asked for beats a
		// machine that never comes up at all.
		p.log.Warn("a machine's disk does not say how big it is, so its size is left as the template's",
			"node", node, "vmid", vmid, "disk", disk)
		return nil
	}
	if haveMB >= wantMB {
		return nil
	}
	return p.client.ResizeDisk(ctx, node, vmid, disk, strconv.FormatInt(wantMB, 10)+"M")
}

// Stop powers a machine down without destroying it.
//
// Graceful is a shutdown the guest performs itself, with the power pulled after
// it if it will not: a shutdown that hangs on a wedged guest would otherwise
// leave a machine nothing can destroy, because Proxmox will not remove one that
// is running.
func (p *Provider) Stop(ctx context.Context, ref provider.MachineRef, graceful bool) (provider.OperationRef, error) {
	node, vmid, err := p.locate(ref, "stop a machine")
	if err != nil {
		return provider.OperationRef{}, err
	}
	var upid string
	if graceful {
		upid, err = p.client.ShutdownVM(ctx, node, vmid, shutdownGrace, true)
	} else {
		upid, err = p.client.StopVM(ctx, node, vmid)
	}
	if err != nil {
		return provider.OperationRef{}, err
	}
	return provider.OperationRef{Kind: provider.OpStop, Handle: upid}, nil
}

// ---------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------

// Inspect reports one guest: what it is doing, what holds it, and the ownership
// marks as they are written on it.
//
// The marks are read back from the guest's own configuration and never echoed
// from what a caller supplied, because a value handed back proves nothing about
// what is on the machine -- and what stands between a sweep and a delete is
// exactly that difference.
func (p *Provider) Inspect(ctx context.Context, ref provider.MachineRef) (provider.Machine, error) {
	node, vmid, err := p.locate(ref, "inspect a machine")
	if err != nil {
		return provider.Machine{}, err
	}
	status, err := p.client.VMStatus(ctx, node, vmid)
	if err != nil {
		return provider.Machine{}, err
	}
	m := provider.Machine{
		Ref:    provider.MachineRef{Zone: node, ID: strconv.Itoa(vmid), Name: status.Name},
		Phase:  phaseOf(status.Status),
		Locked: status.Lock,
		Detail: describeStatus(node, vmid, status),
	}
	cfg, err := p.client.VMConfig(ctx, node, vmid)
	if err != nil {
		// The guest answered a moment ago, so a configuration that cannot be
		// read is a refusal to report rather than a machine to guess about:
		// returning it with no marks would read as an unmarked resource, which
		// is a different thing and authorises different decisions.
		return provider.Machine{}, err
	}
	if owner, ok := DecodeOwner(cfg.Description); ok {
		m.Owner = owner
	}
	if m.Ref.Name == "" {
		m.Ref.Name = cfg.Name
	}
	return m, nil
}

// List is the ownership sweep: every guest that wears this fleet's tag or its
// naming grammar, with the marks each one carries.
//
// The cluster-wide listing is one call however many nodes there are, which is
// what makes the sweep cheap. The marks themselves are not in it -- a guest's
// description is only readable from its own configuration -- so each candidate
// costs one more call, and the tag is what keeps "each candidate" to this
// fleet's own machines rather than to every guest in the cluster.
//
// A guest that cannot be read fails the whole call rather than being left out.
// A sweep that silently returned fewer machines than exist would read as rows
// whose resources have gone, and that answer drains hosts.
func (p *Provider) List(ctx context.Context, owner provider.Owner) ([]provider.Machine, error) {
	guests, err := p.client.ClusterVMs(ctx)
	if err != nil {
		return nil, err
	}
	var out []provider.Machine
	for _, g := range guests {
		// Templates are never machines, and a container cannot run an agent
		// this fleet installs.
		if g.Type != "qemu" || bool(g.Template) {
			continue
		}
		// Ours by tag, or wearing our naming grammar: the second is how an
		// orphan of our own is told from another fleet's machine, and the
		// caller needs both to tell those apart.
		if !HasFleetTag(g.Tags) && !store.IsMachineName(g.Name) {
			continue
		}
		vmid := g.VMID.Int()
		m := provider.Machine{
			Ref:    provider.MachineRef{Zone: g.Node, ID: strconv.Itoa(vmid), Name: g.Name},
			Phase:  phaseOf(g.Status),
			Detail: fmt.Sprintf("VMID %d on %s", vmid, g.Node),
		}
		cfg, err := p.client.VMConfig(ctx, g.Node, vmid)
		switch {
		case errors.Is(err, provider.ErrNotFound):
			// Destroyed between the listing and this read. It is gone, which
			// is what leaving it out of the answer says.
			continue
		case err != nil:
			return nil, err
		}
		if got, ok := DecodeOwner(cfg.Description); ok {
			m.Owner = got
		}
		out = append(out, m)
	}
	return out, nil
}

// Operation reports an asynchronous operation's progress, and is the whole of
// restart recovery: a controller holding nothing but a stored handle asks this
// rather than doing the work again.
//
// Two kinds of handle arrive here. A UPID is a cluster task and carries its own
// node, so nothing else about it needs to have been stored. A guest-exec handle
// is bootstrap.go's, and is explained there.
func (p *Provider) Operation(ctx context.Context, op provider.OperationRef) (provider.OperationStatus, error) {
	if node, vmid, pid, ok := parseExecHandle(op.Handle); ok {
		return p.execStatus(ctx, node, vmid, pid)
	}
	upid, err := ParseUPID(op.Handle)
	if err != nil {
		// A handle this build cannot read names no node, so there is nowhere
		// to ask about it. Not-found is the honest answer and the one the
		// contract requires: it authorises nothing on its own, and the caller
		// goes and looks at the machine instead.
		return provider.OperationStatus{}, &provider.Error{
			Kind: provider.FailureNotFound, Op: "follow an operation", Ref: op.Handle,
			Message: err.Error(),
		}
	}
	task, err := p.client.Task(ctx, upid.Node, upid.Raw)
	if err != nil {
		return provider.OperationStatus{}, err
	}
	switch {
	case !task.Done():
		return provider.OperationStatus{Detail: "in progress on " + upid.Node}, nil
	case task.OK():
		return provider.OperationStatus{Done: true, OK: true, Detail: "finished on " + upid.Node}, nil
	}
	// Proxmox's own words for the failure, and its task log behind them: the
	// exit status says "storage 'local-lvm' is full" and the log says which
	// disk it was copying at the time, and an operator reading a machine's
	// page is owed both.
	detail := task.ExitStatus
	if detail == "" {
		detail = "the task ended without saying why"
	}
	if log, err := p.client.TaskLog(ctx, upid.Node, upid.Raw, taskLogLines); err == nil {
		if log = strings.TrimSpace(log); log != "" {
			detail += "\n" + log
		}
	}
	return provider.OperationStatus{Done: true, Detail: detail}, nil
}

// taskLogLines is how much of a failed task's log is carried into the message.
// Enough for the lines that name the storage or the file, and not so much that
// a machine's page becomes a log viewer.
const taskLogLines = 20

// ---------------------------------------------------------------------------
// Removing
// ---------------------------------------------------------------------------

// Delete destroys a guest, having first stopped it if it is running.
//
// Proxmox refuses to destroy a running guest, so a delete that finds one issues
// a shutdown and hands that task back as the delete's handle. The caller then
// follows it, finds the resource still there, and asks again -- one more pass,
// and every state of it durable. Stopping and destroying inside one call would
// mean waiting on a task, which is the thing this provider does not do.
//
// Deleting a guest that is already gone is success: the desired end state has
// been reached, so there is nothing to follow and nothing to report.
func (p *Provider) Delete(ctx context.Context, ref provider.MachineRef) (provider.OperationRef, error) {
	node, vmid, err := p.locate(ref, "destroy a machine")
	if err != nil {
		return provider.OperationRef{}, err
	}
	status, err := p.client.VMStatus(ctx, node, vmid)
	switch {
	case errors.Is(err, provider.ErrNotFound):
		return provider.OperationRef{}, nil
	case err != nil:
		return provider.OperationRef{}, err
	}
	if status.Lock != "" {
		return provider.OperationRef{}, lockedError("destroy a machine", node, vmid, status.Lock)
	}
	if status.Status == statusRunning {
		upid, err := p.client.ShutdownVM(ctx, node, vmid, shutdownGrace, true)
		if err != nil {
			return provider.OperationRef{}, err
		}
		return provider.OperationRef{Kind: provider.OpDelete, Handle: upid}, nil
	}
	upid, err := p.client.DeleteVM(ctx, node, vmid)
	switch {
	case errors.Is(err, provider.ErrNotFound):
		return provider.OperationRef{}, nil
	case err != nil:
		return provider.OperationRef{}, err
	}
	return provider.OperationRef{Kind: provider.OpDelete, Handle: upid}, nil
}

// ---------------------------------------------------------------------------
// The shape a machine was asked for
// ---------------------------------------------------------------------------

// shapeBlock is the shape a machine was asked for, recorded on the guest at
// the moment it is cloned.
//
// It is a separate line of the description from the ownership record, and a
// separate object, so that neither decoder can be confused by the other and
// neither has learnt anything about the other's job. What it exists for is the
// call that sizes a machine: that call is handed a reference and no
// specification, and a controller may have restarted between the clone and it.
type shapeBlock struct {
	Shape recordedShape `json:"zoomies_shape"`
}

type recordedShape struct {
	Cores    int   `json:"cores,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	DiskMB   int64 `json:"disk_mb,omitempty"`
}

func (r recordedShape) zero() bool { return r.Cores == 0 && r.MemoryMB == 0 && r.DiskMB == 0 }

// describeMachine renders the description a clone carries: the ownership
// record, and the shape the machine was asked for.
func describeMachine(owner provider.Owner, name string, shape provider.Shape) string {
	described := Describe(owner, name)
	rec := recordedShape{Cores: coresFor(shape.CPUs), MemoryMB: shape.MemoryMB, DiskMB: shape.DiskMB}
	if rec.zero() {
		return described
	}
	blob, err := json.Marshal(shapeBlock{Shape: rec})
	if err != nil {
		// A description without the shape still identifies the machine, and
		// the guest keeps the template's size with a warning rather than not
		// being created at all.
		return described
	}
	return described + "\n" + string(blob)
}

// decodeShape reads the recorded shape back, reporting whether one was there.
// It scans line by line for the same reason DecodeOwner does: an operator who
// appends a note to a guest's description has not thereby changed its shape.
func decodeShape(description string) (recordedShape, bool) {
	for _, line := range strings.Split(description, "\n") {
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "{") {
			continue
		}
		var block shapeBlock
		if err := json.Unmarshal([]byte(line), &block); err != nil {
			continue
		}
		if block.Shape.zero() {
			continue
		}
		return block.Shape, true
	}
	return recordedShape{}, false
}

// coresFor turns the contract's fractional processors into the whole ones
// Proxmox allocates, rounding up: a runner given less than it was promised is
// a slow build nobody can explain, and half a core is not a thing a guest can
// be given.
func coresFor(cpus float64) int {
	if cpus <= 0 {
		return 0
	}
	return int(math.Ceil(cpus))
}

// ---------------------------------------------------------------------------
// Plumbing
// ---------------------------------------------------------------------------

// statusRunning is the one status string that means a guest is up. Proxmox
// writes "running" or "stopped" and nothing else for a guest it can see.
const statusRunning = "running"

// phaseOf maps Proxmox's statuses onto the contract's phases. Anything this
// build does not recognise is unknown, which authorises no delete and never
// reads as gone: what we cannot classify, we leave alone.
func phaseOf(status string) provider.Phase {
	switch status {
	case statusRunning:
		return provider.PhaseRunning
	case "stopped", "paused", "suspended":
		return provider.PhaseStopped
	}
	return provider.PhaseUnknown
}

// describeStatus is the one operator-facing sentence a machine's page shows.
func describeStatus(node string, vmid int, s VMStatus) string {
	detail := fmt.Sprintf("VMID %d on %s is %s", vmid, node, s.Status)
	if s.Lock != "" {
		detail += fmt.Sprintf(", held by a %s", s.Lock)
	}
	return detail
}

// locate turns a ref into the node and identifier every call needs, refusing a
// ref that names neither rather than guessing at one.
func (p *Provider) locate(ref provider.MachineRef, op string) (string, int, error) {
	node := strings.TrimSpace(ref.Zone)
	if node == "" {
		return "", 0, &provider.Error{
			Kind: provider.FailureInternal, Op: op, Ref: ref.Name,
			Message: "this machine has no node recorded, and a guest cannot be found without one",
			Remedy:  "the row was written before the node was chosen; release this machine and let the fleet build another",
		}
	}
	vmid, err := strconv.Atoi(strings.TrimSpace(ref.ID))
	if err != nil || vmid <= 0 {
		return "", 0, &provider.Error{
			Kind: provider.FailureInternal, Op: op, Ref: ref.Name,
			Message: fmt.Sprintf("%q is not a VMID, so there is no guest to act on", ref.ID),
			Remedy:  "release this machine and let the fleet build another",
		}
	}
	return node, vmid, nil
}

// lockedError is another operation holding a guest: something to wait for and
// observe, never something to force or to build a second machine over.
func lockedError(op, node string, vmid int, lock string) error {
	return &provider.Error{
		Kind: provider.FailureConflict, Op: op, Ref: vmRef(node, vmid),
		Message: fmt.Sprintf("VM %d on %s is held by a %s", vmid, node, lock),
		Remedy:  "nothing is forced; the operation holding it is waited for",
	}
}

// templateNode is where the template lives: the node an operator named, or the
// first node this provider may place on, which is the arrangement a
// single-node cluster has.
func (p *Provider) templateNode() string {
	if p.settings.templateNode != "" {
		return p.settings.templateNode
	}
	if len(p.settings.nodes) > 0 {
		return p.settings.nodes[0]
	}
	return ""
}

// netDevice is the network interface to write, keeping whatever hardware
// address the guest already has.
//
// Carrying the address over is what makes configuring a machine twice harmless:
// an interface written without one has Proxmox generate a new address, and a
// machine that changes its address takes a new DHCP lease and a new IP with it,
// which loses any reservation somebody made for it. The template's own model is
// kept for the same reason -- it is the operator's choice, not ours.
func netDevice(existing, bridge string) string {
	device := "virtio"
	if model, mac, ok := strings.Cut(firstField(existing), "="); ok && looksLikeMAC(mac) {
		device = model + "=" + mac
	}
	return device + ",bridge=" + bridge
}

func firstField(s string) string {
	field, _, _ := strings.Cut(s, ",")
	return strings.TrimSpace(field)
}

// looksLikeMAC is the shape Proxmox writes a hardware address in, and enough of
// a check to tell one from a property that happens to carry an "=".
func looksLikeMAC(s string) bool {
	return len(s) == len("AA:BB:CC:DD:EE:FF") && strings.Count(s, ":") == 5
}

// bootDisk is the disk a machine's operating system is on, and its
// configuration string. The order is the one a cloud image is imported with:
// scsi0 is what every current Proxmox template uses and virtio0 what the older
// ones do.
func bootDisk(cfg VMConfig) (string, string) {
	switch {
	case cfg.SCSI0 != "":
		return "scsi0", cfg.SCSI0
	case cfg.VirtIO0 != "":
		return "virtio0", cfg.VirtIO0
	}
	return "", ""
}

// diskSizeMB reads the size out of a disk's configuration string --
// "local-lvm:vm-143-disk-0,size=20G" -- reporting whether there was one. A disk
// whose size cannot be read is left alone rather than guessed at.
func diskSizeMB(spec string) (int64, bool) {
	for _, part := range strings.Split(spec, ",") {
		value, ok := strings.CutPrefix(strings.TrimSpace(part), "size=")
		if !ok {
			continue
		}
		return parseSize(value)
	}
	return 0, false
}

// parseSize reads Proxmox's own size grammar: a number and an optional unit,
// where a bare number is bytes.
func parseSize(value string) (int64, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return 0, false
	}
	unit := value[len(value)-1]
	digits := value
	var scale float64 = 1.0 / (1 << 20) // bytes, when there is no unit at all
	switch unit {
	case 'K', 'k':
		scale = 1.0 / 1024
	case 'M', 'm':
		scale = 1
	case 'G', 'g':
		scale = 1024
	case 'T', 't':
		scale = 1024 * 1024
	default:
		unit = 0
	}
	if unit != 0 {
		digits = value[:len(value)-1]
	}
	n, err := strconv.ParseFloat(digits, 64)
	if err != nil || n < 0 {
		return 0, false
	}
	return int64(n * scale), true
}

// refuse turns a settings check into the error a build fails with, naming every
// answer that is wrong rather than only the first: an operator fixing a form
// should not have to submit it four times to be told four things.
func refuse(findings []config.Finding) error {
	var wrong []string
	for _, f := range findings {
		if f.Severity == config.SeverityError {
			wrong = append(wrong, f.Title)
		}
	}
	if len(wrong) == 0 {
		return nil
	}
	return &provider.Error{
		Kind: provider.FailureConfig, Op: "build a Proxmox provider",
		Message: strings.Join(wrong, "; "),
		Remedy:  "correct this provider's settings; the provider's page lists each one and what it is for",
	}
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

// The settings an operator answers, beyond the endpoint and the credential.
// Preflight names several of these in its findings, which is why those keys
// live beside it rather than here.
const (
	SettingTemplateNode  = "template_node"
	SettingFullClone     = "full_clone"
	SettingIPConfig      = "ipconfig0"
	SettingNameserver    = "nameserver"
	SettingControllerURL = "controller_url"
)

// defaultIPConfig is what a cloud image is told about its network when nobody
// says otherwise. A machine with no address can never enrol, and a cloud-init
// guest given no ipconfig at all is given no network configuration.
const defaultIPConfig = "ip=dhcp"

// settings is one provider row's answers, parsed once.
type settings struct {
	nodes            []string
	storage          string
	bridge           string
	templateNode     string
	templateID       int
	pool             string
	vmidMin, vmidMax int
	fullClone        bool
	ipConfig         string
	nameserver       string
	tokenID          string
}

// prereqs is the configured half of this provider in preflight's terms.
func (s settings) prereqs() Prereqs {
	return Prereqs{
		Nodes:        s.nodes,
		Storage:      s.storage,
		Bridge:       s.bridge,
		TemplateNode: s.templateNode,
		TemplateID:   s.templateID,
		Pool:         s.pool,
		VMIDMin:      s.vmidMin,
		VMIDMax:      s.vmidMax,
		// Always: the qualified bootstrap is the guest agent, so the two
		// privileges it needs are prerequisites rather than extras.
		GuestAgent: true,
	}
}

// parseSettings reads a row's answers and says what is wrong with them.
//
// One function feeds three callers -- the form's offline validation, the
// provider that is built from the row, and the preflight that checks the
// answers against the cluster -- so a setting cannot be understood one way in
// the wizard and another way by the thing that clones a template.
func parseSettings(in map[string]string) (settings, []config.Finding) {
	get := func(key string) string { return strings.TrimSpace(in[key]) }
	s := settings{
		nodes:        splitList(get(SettingNodes)),
		storage:      get(SettingStorage),
		bridge:       get(SettingBridge),
		templateNode: get(SettingTemplateNode),
		pool:         get(SettingPool),
		nameserver:   get(SettingNameserver),
		tokenID:      get(SettingTokenID),
		fullClone:    true,
		ipConfig:     defaultIPConfig,
	}
	// Absent and empty are different answers here: clearing this is how a
	// template with no cloud-init drive at all is described, and a default
	// applied over that would put a setting on a guest that cannot use it.
	if raw, answered := in[SettingIPConfig]; answered {
		s.ipConfig = strings.TrimSpace(raw)
	}
	if raw := get(SettingFullClone); raw != "" {
		// A linked clone is quick and cheap and ties the machine's life to the
		// template's: the template can then never be deleted or altered while
		// a machine made from it lives. Full is the default for that reason,
		// and this is how an operator who understands the trade takes it.
		s.fullClone = raw != "false" && raw != "0" && raw != "no"
	}

	var findings []config.Finding
	add := func(f config.Finding) { findings = append(findings, f) }

	if len(s.nodes) == 0 {
		add(config.Finding{
			Code: "proxmox.node_missing", Severity: config.SeverityError, Setting: SettingNodes,
			Title:  "no node is configured",
			Detail: "there is nowhere for a machine to be built.",
			Fix:    "choose at least one node of the cluster; the form lists the ones this token can see.",
		})
	}
	if s.storage == "" {
		add(config.Finding{
			Code: "proxmox.storage_missing", Severity: config.SeverityError, Setting: SettingStorage,
			Title:  "no storage is configured",
			Detail: "a clone has nowhere to put the machine's disk.",
			Fix:    "choose a storage that accepts disk images.",
		})
	}
	if s.bridge == "" {
		add(config.Finding{
			Code: "proxmox.bridge_missing", Severity: config.SeverityError, Setting: SettingBridge,
			Title:  "no network bridge is configured",
			Detail: "a machine with no network cannot reach this controller, so it can never enrol.",
			Fix:    "choose the bridge the rest of this network uses, usually vmbr0.",
		})
	}

	var err error
	if raw := get(SettingTemplateID); raw != "" {
		if s.templateID, err = strconv.Atoi(raw); err != nil || s.templateID <= 0 {
			s.templateID = 0
		}
	}
	if s.templateID <= 0 {
		add(config.Finding{
			Code: "proxmox.template_missing", Severity: config.SeverityError, Setting: SettingTemplateID,
			Title:  "no template is configured",
			Detail: "every machine starts as a clone of one, and a template is named by its VMID.",
			Fix:    "prepare a template as the runbook describes and give its VMID here.",
		})
	}

	s.vmidMin, s.vmidMax = atoiOrZero(get(SettingVMIDMin)), atoiOrZero(get(SettingVMIDMax))
	switch {
	case s.vmidMin <= 0 || s.vmidMax <= 0:
		add(config.Finding{
			Code: "proxmox.vmid_range", Severity: config.SeverityError, Setting: SettingVMIDMin,
			Title:  "no VMID range is configured",
			Detail: "without one this provider would allocate identifiers anywhere in the cluster, including ones somebody else's automation is entitled to.",
			Fix:    "set vmid_min and vmid_max to a range nothing else uses, for example 9000 to 9099.",
		})
	case s.vmidMin > s.vmidMax:
		add(config.Finding{
			Code: "proxmox.vmid_range", Severity: config.SeverityError, Setting: SettingVMIDMin,
			Title:  fmt.Sprintf("the VMID range %d-%d runs backwards", s.vmidMin, s.vmidMax),
			Detail: "no identifier can be allocated from it, so no machine can be created.",
			Fix:    "set vmid_min below vmid_max.",
		})
	}
	return s, findings
}

// splitList reads a setting that holds several answers. Commas are what the
// form writes and whitespace is what somebody typing one out by hand uses, so
// both are accepted.
func splitList(s string) []string {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || r == ' ' || r == '\t' || r == '\n' || r == '\r'
	})
	out := make([]string, 0, len(fields))
	for _, f := range fields {
		if f = strings.TrimSpace(f); f != "" {
			out = append(out, f)
		}
	}
	return out
}

func atoiOrZero(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return n
}

// splitCredential separates the token's name from its secret.
//
// Proxmox prints a new token as "user@realm!tokenid=secret" and that is what
// gets pasted, so the whole thing arrives as the credential and is split here.
// An operator who keeps the two apart -- the name in a setting, the secret in
// the credential -- is right as well, and gets the same answer: the name is
// not a secret, and it is what every message asking for a privilege has to
// quote.
func splitCredential(tokenID, credential string) (string, string, error) {
	credential = strings.TrimSpace(credential)
	tokenID = strings.TrimSpace(tokenID)
	if credential == "" {
		return "", "", &provider.Error{
			Kind: provider.FailureConfig, Op: "build a Proxmox provider",
			Message: "this provider has no API token",
			Remedy:  "paste the token exactly as Proxmox printed it when it was created: user@realm!tokenid=secret",
		}
	}
	if name, secret, ok := strings.Cut(credential, "="); ok &&
		strings.Contains(name, "@") && strings.Contains(name, "!") {
		return strings.TrimSpace(name), strings.TrimSpace(secret), nil
	}
	return tokenID, credential, nil
}

// ---------------------------------------------------------------------------
// The factory
// ---------------------------------------------------------------------------

// Factory builds Proxmox providers. It is what the registry holds, and what the
// page listing the kinds a build supports is rendered from.
type Factory struct{}

// NewFactory returns the factory to register.
func NewFactory() Factory { return Factory{} }

func (Factory) Kind() store.ProviderKind { return store.ProviderProxmox }

// Describe is this kind's capabilities without an instance. It is built from
// the same function the instance's are, so the two cannot disagree.
func (Factory) Describe() provider.Capabilities { return capabilities(provider.Deadlines{}) }

// Settings is the schema the configuration form, the validator and the
// documentation share.
func (Factory) Settings() []provider.SettingSpec {
	return []provider.SettingSpec{
		{
			Key: SettingNodes, Label: "Nodes", Kind: provider.SettingList, Required: true,
			Discovers:   "nodes",
			Help:        "The cluster nodes machines may be built on.",
			Consequence: "Machines are spread across these, fewest guests first. A node not named here is never touched.",
			Source:      "The node names in the tree on the left of the Proxmox console, or `pvesh get /nodes` on any node.",
		},
		{
			Key: SettingTemplateID, Label: "Template VMID", Kind: provider.SettingChoice, Required: true,
			Discovers:   "templates",
			Help:        "The prepared template every machine is cloned from.",
			Consequence: "What is in the template is what a runner gets: Zoomies installs nothing that is not already there.",
			Source:      "The number beside the template in the console tree; `qm list` on its node shows every guest with its VMID.",
		},
		{
			Key: SettingStorage, Label: "Storage", Kind: provider.SettingChoice, Required: true,
			Discovers:   "storages",
			Help:        "Where a clone's disk lands.",
			Consequence: "A storage only one node can see means machines can only be built on that node.",
			Source:      "Datacenter -> Storage. It has to allow the Disk image content type, and a storage only one node can see confines machines to that node.",
		},
		{
			Key: SettingBridge, Label: "Network bridge", Kind: provider.SettingChoice, Required: true,
			Discovers:   "bridges",
			Default:     "vmbr0",
			Help:        "The bridge a machine's network interface is attached to.",
			Consequence: "A machine that cannot reach this controller from this bridge boots, costs money and never joins.",
			Source:      "A node -> System -> Network. vmbr0 is the bridge a default install creates; `ip link` inside a working guest shows which one it is on.",
		},
		{
			Key: SettingVMIDMin, Label: "Lowest VMID", Kind: provider.SettingNumber, Required: true,
			Default:     "9000",
			Help:        "The bottom of the block of VM identifiers Zoomies may allocate from.",
			Consequence: "The range is a blast radius as well as a budget: a guest outside it is, by construction, not one of ours.",
			Source:      "Your choice, not something to look up. Pick a block no other tooling numbers from; `qm list` on each node shows what is taken.",
		},
		{
			Key: SettingVMIDMax, Label: "Highest VMID", Kind: provider.SettingNumber, Required: true,
			Default:     "9099",
			Help:        "The top of that block.",
			Consequence: "It also caps how many machines can exist at once, whatever the fleet's other limits say.",
			Source:      "The top of the same block. The template itself must sit outside it.",
		},
		{
			Key: SettingTemplateNode, Label: "Template's node", Kind: provider.SettingChoice, Advanced: true,
			Discovers:   "nodes",
			Help:        "Where the template itself lives. Empty means the first node above.",
			Consequence: "Cloning to a different node needs the template's disk on shared storage; Proxmox refuses it otherwise.",
			Source:      "The node the template appears under in the console tree.",
		},
		{
			Key: SettingPool, Label: "Resource pool", Kind: provider.SettingText, Advanced: true,
			Help:        "A Proxmox pool new guests are put in.",
			Consequence: "A pool is also a path privileges can be granted on, which is how this token is kept away from the rest of the cluster.",
			Source:      "Datacenter -> Permissions -> Pools; the pool must already exist.",
		},
		{
			Key: SettingFullClone, Label: "Full clone", Kind: provider.SettingBool, Advanced: true,
			Default:     "true",
			Help:        "Copy the template's disk rather than referring to it.",
			Consequence: "A linked clone is quicker and smaller, and the template can then never be deleted or changed while a machine made from it lives.",
		},
		{
			Key: SettingIPConfig, Label: "Cloud-init IP configuration", Kind: provider.SettingText, Advanced: true,
			Default:     defaultIPConfig,
			Help:        "What a cloud image is told about its network, in Proxmox's ipconfig0 grammar.",
			Consequence: "Clear it for a template that has no cloud-init drive; a machine with no address can never enrol.",
		},
		{
			Key: SettingNameserver, Label: "Nameserver", Kind: provider.SettingText, Advanced: true,
			Help:        "A resolver for cloud-init to write into the guest. Empty leaves whatever DHCP provides.",
			Consequence: "A machine that cannot resolve this controller's name never joins.",
		},
		{
			Key: SettingControllerURL, Label: "Controller URL for machines", Kind: provider.SettingText, Advanced: true,
			Help:        "How a machine on this cluster reaches this controller, when that is not the fleet's external URL.",
			Consequence: "Machines on a private network usually cannot use the address a browser does.",
			Source:      "The address a machine on this bridge would use to reach the controller: usually the external URL, or its LAN address when the cluster is on the same network.",
		},
		{
			Key: SettingTokenID, Label: "API token id", Kind: provider.SettingText, Advanced: true,
			Help:        "user@realm!tokenid. Leave it empty when the token is pasted whole as user@realm!tokenid=secret.",
			Consequence: "It is not a secret: it is what every message asking for a privilege to be granted has to quote.",
			Source:      "Datacenter -> Permissions -> API Tokens, as user@realm!tokenid.",
		},
	}
}

// Validate checks the answers offline, dialling nothing: it is what the form
// runs as somebody types, and Preflight is the call that talks to the cluster.
func (Factory) Validate(settings map[string]string) []config.Finding {
	_, findings := parseSettings(settings)
	return findings
}

// New builds one provider. It takes a context because the contract does; there
// is nothing to dial here, because reachability is Preflight's answer to give.
func (Factory) New(_ context.Context, cfg provider.Config) (provider.Provider, error) {
	return NewProvider(cfg)
}

// DiscoverDraft lists what a credential can see with nothing but the address
// and the credential, which is the state a wizard is in when it wants the
// menu: the node, storage and template it is about to ask for are exactly the
// settings NewProvider would refuse to build without.
func (Factory) DiscoverDraft(ctx context.Context, cfg provider.Config) (provider.Discovery, error) {
	tokenID, secret, err := splitCredential(cfg.Settings[SettingTokenID], cfg.Credential)
	if err != nil {
		return provider.Discovery{}, err
	}
	log := cfg.Logger
	if log == nil {
		log = slog.Default()
	}
	client, err := New(Options{
		Endpoint:    cfg.Endpoint,
		TokenID:     tokenID,
		Secret:      secret,
		CAPEM:       cfg.CAPEM,
		Insecure:    cfg.Insecure,
		DialContext: cfg.DialContext,
		HTTPClient:  cfg.HTTPClient,
		Logger:      log,
	})
	if err != nil {
		return provider.Discovery{}, err
	}
	return Discover(ctx, client)
}

package proxmox

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"strconv"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/provider"
	"github.com/eyupio/zoomies/internal/store"
)

// The suite every provider must pass, run against a fake cluster that speaks
// the real API over TLS. It is first in this file because it is the definition
// of done: everything below it is a Proxmox-specific rule the contract has no
// opinion about.
func TestTheProxmoxProviderObeysTheContract(t *testing.T) {
	provider.RunContractTests(t, "proxmox", func(t *testing.T) provider.Provider {
		return newTestProvider(t, newFakePVE(t, nil), nil)
	})
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// newTestProvider builds a provider pointed at a fake cluster, through the
// factory and the registry rather than around them, so that every test here
// also exercises the handshake a real deployment goes through.
func newTestProvider(t *testing.T, f *fakePVE, overrides map[string]string) *Provider {
	t.Helper()
	settings := map[string]string{
		SettingNodes:      "pve-1",
		SettingTemplateID: "9000",
		SettingStorage:    "local-lvm",
		SettingBridge:     "vmbr0",
		SettingVMIDMin:    "9100",
		SettingVMIDMax:    "9199",
	}
	for k, v := range overrides {
		if v == "" {
			delete(settings, k)
			continue
		}
		settings[k] = v
	}
	p, err := NewProvider(provider.Config{
		ProviderID: "prv_test",
		Endpoint:   f.URL,
		Settings:   settings,
		// Pasted whole, exactly as Proxmox prints a new token.
		Credential: tokenID + "=" + tokenSecret,
		CAPEM:      f.caPEM(t),
		Logger:     slog.New(slog.DiscardHandler),
	})
	if err != nil {
		t.Fatalf("building a provider: %v", err)
	}
	return p
}

// newSpec mints one machine's identity the way the controller does.
func newSpec(cpus float64, memoryMB, diskMB int64) (provider.Owner, provider.MachineSpec) {
	id := store.NewID(store.PrefixMachine)
	owner := provider.Owner{
		ControllerID: store.NewID(store.PrefixController),
		ProviderID:   "prv_test",
		MachineID:    id,
		Fingerprint:  store.NewSecret(12),
	}
	return owner, provider.MachineSpec{
		Name:  store.NewMachineName(id),
		Owner: owner,
		Shape: provider.Shape{CPUs: cpus, MemoryMB: memoryMB, DiskMB: diskMB},
	}
}

// buildMachine allocates and creates one machine, and waits for its clone.
func buildMachine(t *testing.T, p *Provider, spec provider.MachineSpec) provider.MachineRef {
	t.Helper()
	ctx := context.Background()
	ref, err := p.Allocate(ctx, spec)
	if err != nil {
		t.Fatalf("Allocate: %v", err)
	}
	op, err := p.Create(ctx, ref, spec)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if !op.Zero() {
		status, err := p.Operation(ctx, op)
		if err != nil {
			t.Fatalf("Operation: %v", err)
		}
		if !status.Done || !status.OK {
			t.Fatalf("the clone did not finish: %+v", status)
		}
	}
	return ref
}

// execCommands is every command this provider asked a guest to run, as the
// argv arrays they were sent as.
func execCommands(t *testing.T, f *fakePVE) [][]string {
	t.Helper()
	f.mu.Lock()
	defer f.mu.Unlock()
	var out [][]string
	for _, r := range f.seen {
		if r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/agent/exec") {
			out = append(out, r.PostForm["command"])
		}
	}
	return out
}

