// Every call has to send what the API actually expects; a parameter with the
// wrong name is a machine that is built with the wrong shape or not at all.
func TestEveryCallSendsTheParametersProxmoxExpects(t *testing.T) {
	f := newFakePVE(t, nil)
	c := f.client(t)
	ctx := context.Background()

	if _, err := c.CloneVM(ctx, "pve-1", 9000, CloneRequest{
		NewID: 143, Name: "zoomies-mach-abc", Full: true, Storage: "local-lvm", Target: "pve-1",
		Pool: "zoomies", Description: "Managed by Zoomies",
	}); err != nil {
		t.Fatalf("CloneVM: %v", err)
	}
	clone := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/9000/clone")
	for key, want := range map[string]string{
		"newid": "143", "name": "zoomies-mach-abc", "full": "1", "storage": "local-lvm",
		"target": "pve-1", "pool": "zoomies", "description": "Managed by Zoomies",
	} {
		if got := formValue(clone, key); got != want {
			t.Errorf("clone %s = %q, want %q", key, got, want)
		}
	}

	if _, err := c.ConfigureVM(ctx, "pve-1", 143, map[string][]string{
		"cores": {"4"}, "memory": {"8192"}, "net0": {"virtio,bridge=vmbr0"}, "tags": {"zoomies;zoomies-abc"},
	}); err != nil {
		t.Fatalf("ConfigureVM: %v", err)
	}
	config := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/143/config")
	if got := formValue(config, "net0"); got != "virtio,bridge=vmbr0" {
		t.Errorf("net0 = %q", got)
	}
	if got := formValue(config, "tags"); got != "zoomies;zoomies-abc" {
		t.Errorf("tags = %q", got)
	}

	if err := c.ResizeDisk(ctx, "pve-1", 143, "scsi0", "+40G"); err != nil {
		t.Fatalf("ResizeDisk: %v", err)
	}
	resize := f.request(http.MethodPut, v+"/nodes/pve-1/qemu/143/resize")
	if formValue(resize, "disk") != "scsi0" || formValue(resize, "size") != "+40G" {
		t.Errorf("resize sent disk=%q size=%q", formValue(resize, "disk"), formValue(resize, "size"))
	}

	if _, err := c.ShutdownVM(ctx, "pve-1", 143, 90*time.Second, true); err != nil {
		t.Fatalf("ShutdownVM: %v", err)
	}
	shutdown := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/143/status/shutdown")
	if formValue(shutdown, "timeout") != "90" || formValue(shutdown, "forceStop") != "1" {
		t.Errorf("shutdown sent timeout=%q forceStop=%q", formValue(shutdown, "timeout"), formValue(shutdown, "forceStop"))
	}

	if _, err := c.DeleteVM(ctx, "pve-1", 143); err != nil {
		t.Fatalf("DeleteVM: %v", err)
	}
	del := f.request(http.MethodDelete, v+"/nodes/pve-1/qemu/143")
	// Without both of these a destroyed guest leaves backups, replication jobs
	// and unreferenced disks behind, still costing somebody money.
	if queryValue(del, "purge") != "1" || queryValue(del, "destroy-unreferenced-disks") != "1" {
		t.Errorf("delete sent %q", del.URL.RawQuery)
	}
}

// The bootstrap payload is argv, never a shell line: a payload that is never
// pasted into a shell has no quoting to get wrong.
func TestACommandForTheGuestIsSentAsArgvRatherThanAShellLine(t *testing.T) {
	f := newFakePVE(t, nil)
	c := f.client(t)
	ctx := context.Background()

	if err := c.AgentPing(ctx, "pve-1", 100); err != nil {
		t.Fatalf("AgentPing: %v", err)
	}
	if err := c.AgentFileWrite(ctx, "pve-1", 100, "/etc/zoomies/agent.env", []byte("ZOOMIES_JOIN_TOKEN=join_abc\n")); err != nil {
		t.Fatalf("AgentFileWrite: %v", err)
	}
	if got := f.vm(100).files["/etc/zoomies/agent.env"]; !strings.Contains(got, "join_abc") {
		t.Errorf("the guest did not receive the file: %q", got)
	}

	pid, err := c.AgentExec(ctx, "pve-1", 100, []string{"systemctl", "enable", "--now", "zoomies-agent"}, "")
	if err != nil {
		t.Fatalf("AgentExec: %v", err)
	}
	if pid != 4242 {
		t.Errorf("pid = %d, want 4242", pid)
	}
	exec := f.request(http.MethodPost, v+"/nodes/pve-1/qemu/100/agent/exec")
	if got := exec.PostForm["command"]; len(got) != 4 || got[0] != "systemctl" || got[3] != "zoomies-agent" {
		t.Errorf("command = %q, want one value per argument", got)
	}

	status, err := c.AgentExecStatus(ctx, "pve-1", 100, pid)
	if err != nil {
		t.Fatalf("AgentExecStatus: %v", err)
	}
	if !bool(status.Exited) || status.ExitCode != 0 {
		t.Errorf("exited=%v exitcode=%d, want a finished, successful command", status.Exited, status.ExitCode)
	}
}

// A guest agent that never answers is what a machine that booted but never came
// up looks like, and it has to read as a refusal rather than as success.
func TestAGuestAgentThatNeverAnswersIsAFailureAndNotASuccess(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetGuestAgentSilent()

	err := f.client(t).AgentPing(context.Background(), "pve-1", 100)
	if err == nil {
		t.Fatal("a silent guest agent was reported as answering")
	}
	if !strings.Contains(err.Error(), "guest agent is not running") {
		t.Errorf("the reason does not say what is wrong: %v", err)
	}
}

// Proxmox writes its complaint in the HTTP status line as often as in the body.
// A client that only read the body would throw away the only sentence it sent.
func TestProxmoxsMessageInTheStatusLineIsNotLost(t *testing.T) {
	const sentence = "storage 'local-lvm' does not exist"
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	t.Cleanup(func() { _ = ln.Close() })
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		buf := make([]byte, 4096)
		_, _ = conn.Read(buf)
		const body = `{"data":null}`
		fmt.Fprintf(conn, "HTTP/1.1 500 %s\r\nContent-Type: application/json\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s",
			sentence, len(body), body)
	}()

	// Loopback plain HTTP is the one case this client accepts, which is what
	// makes this test possible without a certificate.
	c, err := New(Options{Endpoint: "http://" + ln.Addr().String(), TokenID: tokenID, Secret: tokenSecret})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	_, err = c.Version(context.Background())
	if err == nil {
		t.Fatal("a 500 was accepted as an answer")
	}
	if !strings.Contains(err.Error(), sentence) {
		t.Errorf("the message in the status line was lost: %v", err)
	}
}

// deadAddress is an address nothing is listening on, for the cases about a
// request that never left this machine.
func deadAddress(t *testing.T) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	addr := ln.Addr().String()
	if err := ln.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	return addr
}

// The worst case this package has to survive: the virtual machine was made and
// the answer saying so was lost. It has to arrive as an unknown outcome, and
// the machine has to be findable afterwards -- because the only safe next move
// is to look for it, and a retry would leave one nobody is tracking running and
// billing.
func TestACloneWhoseAnswerWasLostIsUnknownRatherThanFailed(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetAmbiguousClone()
	c := f.client(t)

	_, err := c.CloneVM(context.Background(), "pve-1", 9000, CloneRequest{NewID: 143, Name: "zoomies-mach-abc"})
	if got := provider.KindOf(err); got != provider.FailureAmbiguous {
		t.Fatalf("kind = %q, want %q (%v)", got, provider.FailureAmbiguous, err)
	}
	if provider.Retryable(err) {
		t.Error("an unknown outcome was reported as retryable")
	}

	guests, err := c.ClusterVMs(context.Background())
	if err != nil {
		t.Fatalf("ClusterVMs: %v", err)
	}
	var found bool
	for _, g := range guests {
		if g.Name == "zoomies-mach-abc" {
			found = true
		}
	}
	if !found {
		t.Fatal("the machine the clone made is not findable by name, so an ambiguous create could never be reconciled")
	}
}

// A cluster with no room refuses in its own words. It is worth waiting for and
// is never fixed by asking again immediately, which is a different answer from
// "the call was refused".
func TestAStorageWithNoRoomIsAQuotaRefusal(t *testing.T) {
	f := newFakePVE(t, nil)
	f.SetQuotaExhausted()

	_, err := f.client(t).CloneVM(context.Background(), "pve-1", 9000, CloneRequest{NewID: 143})
	if got := provider.KindOf(err); got != provider.FailureQuota {
		t.Fatalf("kind = %q, want %q (%v)", got, provider.FailureQuota, err)
	}
	if !strings.Contains(err.Error(), "local-lvm") {
		t.Errorf("the refusal does not say which storage is full: %v", err)
	}
	if !provider.Retryable(err) {
		t.Error("a full storage is worth trying again once there is room")
	}
}

// A cluster on a home network has no address the controller can route to. The
// controller hands the client a dialer for the private connection instead, and
// the client has to use it for every socket -- and consult no proxy, which
// would take the connection straight back out of the tunnel -- while the
// endpoint's host stays the name the certificate is verified against.
func TestClientDialsThroughTheProvidedDialerAndUsesNoProxy(t *testing.T) {
	f := newFakePVE(t, nil)
	t.Setenv("HTTPS_PROXY", "http://127.0.0.1:1")
	var dialled []string
	c, err := New(Options{
		// example.com is what httptest's certificate is issued for, and it is
		// not where the fake listens: only the dialer can get there.
		Endpoint: "https://example.com:8006",
		TokenID:  tokenID, Secret: tokenSecret, CAPEM: f.caPEM(t),
		DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
			dialled = append(dialled, address)
			return (&net.Dialer{}).DialContext(ctx, network, f.Listener.Addr().String())
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if tr := c.http.Transport.(*http.Transport); tr.Proxy != nil {
		t.Fatal("a proxy could take the connection out of the private tunnel")
	}
	if _, err := c.Version(context.Background()); err != nil {
		t.Fatalf("Version through the dialer: %v", err)
	}
	if len(dialled) == 0 || dialled[0] != "example.com:8006" {
		t.Fatalf("the dialer was asked for %v, want the endpoint's host and port", dialled)
	}
}

package proxmox

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// UPID is Proxmox's identifier for one asynchronous task.
//
// It is the durable operation handle this provider returns from every call that
// starts work: a clone, a start, a shutdown, a delete. Everything needed to ask
// about the task later is inside the string, the node included, so a controller
// that restarts holding nothing but the stored handle can still find out what
// happened rather than doing the work again.
//
// The wire form is eight colon-separated fields and a trailing colon:
//
//	UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:zoomies@pve!fleet:
//	     node  pid      pstart   start    type    id  user
//
// pstart is eight or nine hex digits -- nine on a node that has been up long
// enough for the kernel's boot-relative counter to overflow eight -- which is
// the detail a parser written from one example gets wrong, and gets wrong only
// on the machines that have been running longest.
type UPID struct {
	// Raw is the string exactly as Proxmox wrote it. It is what is stored and
	// what is sent back, because a handle rewritten from its parts is a handle
	// that can differ from the one the task actually has.
	Raw       string
	Node      string
	PID       uint64
	PStart    uint64
	StartTime time.Time
	// Type is the worker kind: "qmclone", "qmstart", "qmshutdown", "qmdestroy".
	Type string
	// ID is what the task is about -- a VMID for a guest task -- and is empty
	// for tasks that are about nothing in particular.
	ID   string
	User string
}

// String returns the handle as Proxmox wrote it.
func (u UPID) String() string { return u.Raw }

// Zero reports whether this is the absent handle.
func (u UPID) Zero() bool { return u.Raw == "" }

// ParseUPID reads a task handle.
//
// It validates the shape -- the prefix, the field count, the trailing colon,
// and that the three numeric fields are hexadecimal -- and deliberately does
// not validate the rest. The worker types are Proxmox's to add to, and a
// release that invents one must not make a task we are already waiting on
// unreadable.
//
// A caller that only wants the node should not depend on this succeeding: the
// node a machine's resource lives on is recorded on its own row, and that is
// the answer to fall back on. Refusing to poll a task because its handle looked
// unfamiliar would strand a real virtual machine, which is the one outcome
// nothing here may cause.
func ParseUPID(s string) (UPID, error) {
	const prefix = "UPID:"
	if !strings.HasPrefix(s, prefix) {
		return UPID{}, fmt.Errorf("proxmox: %q is not a task handle; one starts with %q", elide(s), prefix)
	}
	if !strings.HasSuffix(s, ":") {
		return UPID{}, fmt.Errorf("proxmox: task handle %q is cut short; one ends with a colon", elide(s))
	}
	// The trailing colon closes the last field rather than opening another, so
	// it is dropped before splitting; eight fields remain, the first of which
	// is the "UPID" marker itself.
	parts := strings.Split(strings.TrimSuffix(s, ":"), ":")
	if len(parts) != 8 {
		return UPID{}, fmt.Errorf("proxmox: task handle %q has %d fields, want 8", elide(s), len(parts))
	}

	u := UPID{Raw: s, Node: parts[1], Type: parts[5], ID: parts[6], User: parts[7]}
	if u.Node == "" {
		return UPID{}, fmt.Errorf("proxmox: task handle %q names no node, so there is nowhere to ask about it", elide(s))
	}
	var err error
	if u.PID, err = hexField(s, "process id", parts[2]); err != nil {
		return UPID{}, err
	}
	if u.PStart, err = hexField(s, "process start", parts[3]); err != nil {
		return UPID{}, err
	}
	started, err := hexField(s, "start time", parts[4])
	if err != nil {
		return UPID{}, err
	}
	u.StartTime = time.Unix(int64(started), 0).UTC()
	return u, nil
}

func hexField(upid, name, text string) (uint64, error) {
	n, err := strconv.ParseUint(text, 16, 64)
	if err != nil {
		return 0, fmt.Errorf("proxmox: task handle %q has %s %q, which is not hexadecimal", elide(upid), name, text)
	}
	return n, nil
}

// elide keeps a malformed handle out of a log line at full length. Whatever
// produced it is not necessarily Proxmox, and an error message is not the place
// to reprint an arbitrary string somebody else chose.
func elide(s string) string {
	const max = 80
	if len(s) <= max {
		return s
	}
	return s[:max] + "..."
}

package proxmox

import (
	"strings"
	"testing"
	"time"
)

// The handle is how a controller that restarted finds out what happened to work
// it started, so the cases that matter are the ones that would make a real task
// unreadable rather than the ones that look untidy.
func TestATaskHandleIsReadWithoutLosingTheTaskItNames(t *testing.T) {
	for _, tc := range []struct {
		name string
		raw  string
		want UPID
	}{
		{
			name: "a clone",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:zoomies@pve!fleet:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmclone", ID: "143", User: "zoomies@pve!fleet",
			},
		},
		{
			// Proxmox writes eight or nine hex digits here: nine once the node
			// has been up long enough for the counter to need them. A parser
			// written against one example fails on exactly the machines that
			// have been running longest, which is the worst possible set.
			name: "a node that has been up a long time",
			raw:  "UPID:pve-1:00051234:1089ABCDE:65F0A1B2:qmstart:143:root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x1089ABCDE,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmstart", ID: "143", User: "root@pam",
			},
		},
		{
			// A task about nothing in particular leaves the field empty rather
			// than omitting it, so the field count is still eight.
			name: "a task about nothing in particular",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:srvreload::root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "srvreload", ID: "", User: "root@pam",
			},
		},
		{
			name: "a hyphenated node name",
			raw:  "UPID:pve-node-02:0000ffff:00000001:65F0A1B2:qmdestroy:9001:zoomies@pve:",
			want: UPID{
				Node: "pve-node-02", PID: 0xffff, PStart: 1,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "qmdestroy", ID: "9001", User: "zoomies@pve",
			},
		},
		{
			// Nothing here knows the full list of worker types, and a Proxmox
			// release that adds one must not make a task we are waiting on
			// unreadable.
			name: "a worker type this build has never heard of",
			raw:  "UPID:pve-1:00051234:0089ABCD:65F0A1B2:somethingnew:143:root@pam:",
			want: UPID{
				Node: "pve-1", PID: 0x51234, PStart: 0x89ABCD,
				StartTime: time.Unix(0x65F0A1B2, 0).UTC(),
				Type:      "somethingnew", ID: "143", User: "root@pam",
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParseUPID(tc.raw)
			if err != nil {
				t.Fatalf("ParseUPID(%q): %v", tc.raw, err)
			}
			tc.want.Raw = tc.raw
			if got != tc.want {
				t.Errorf("ParseUPID(%q)\n got %+v\nwant %+v", tc.raw, got, tc.want)
			}
			// The handle is sent back to Proxmox exactly as it arrived: one
			// rebuilt from its parts can differ from the one the task has.
			if got.String() != tc.raw {
				t.Errorf("String() = %q, want the handle unchanged", got.String())
			}
		})
	}
}

// A malformed handle is refused with a message that says which part of it is
// wrong, because the thing that produced it is not necessarily Proxmox.
func TestAHandleThatIsNotATaskIsRefusedAndSaysWhy(t *testing.T) {
	for _, tc := range []struct {
		name  string
		raw   string
		wants string
	}{
		{"empty", "", "starts with"},
		{"another identifier entirely", "mach_k3f9qz2mx7ab", "starts with"},
		{"cut short", "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam", "cut short"},
		{"too few fields", "UPID:pve-1:00051234:qmclone:", "fields"},
		{"too many fields", "UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:extra:", "fields"},
		{"no node", "UPID::00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:", "names no node"},
		{"a process id that is not a number", "UPID:pve-1:notahexnum:0089ABCD:65F0A1B2:qmclone:143:root@pam:", "hexadecimal"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseUPID(tc.raw)
			if err == nil {
				t.Fatalf("ParseUPID(%q) was accepted", tc.raw)
			}
			if !strings.Contains(err.Error(), tc.wants) {
				t.Errorf("error was %q, want it to mention %q", err, tc.wants)
			}
		})
	}
}

// An arbitrary string is not reprinted at full length into a log line or an
// error an operator reads.
func TestARefusalDoesNotReprintAWholeUnreasonableString(t *testing.T) {
	_, err := ParseUPID(strings.Repeat("x", 4096))
	if err == nil {
		t.Fatal("4 KiB of nonsense was accepted as a task handle")
	}
	if len(err.Error()) > 200 {
		t.Errorf("the refusal was %d bytes long; it quotes its input without limit", len(err.Error()))
	}
}

// The absent handle. A machine that has no operation in flight carries an empty
// one, and every caller asks this rather than comparing to "" -- so that a
// synchronous provider returning no handle and a machine between operations
// answer the same way.
func TestTheAbsentHandleIsTellableFromARealOne(t *testing.T) {
	var none UPID
	if !none.Zero() {
		t.Error("the zero handle does not report itself as absent")
	}
	got, err := ParseUPID("UPID:pve-1:00051234:0089ABCD:65F0A1B2:qmclone:143:root@pam:")
	if err != nil {
		t.Fatalf("ParseUPID: %v", err)
	}
	if got.Zero() {
		t.Error("a real task handle reports itself as absent")
	}
}

package provider

import (
	"context"
	"fmt"
	"slices"

	"github.com/eyupio/zoomies/internal/store"
)

// Registry holds the provider factories a build supports, keyed by kind, the
// way backend.Registry holds the backends an agent has. One registry is built
// at startup and a provider is built from it per configuration row.
type Registry struct {
	factories map[store.ProviderKind]Factory
}

// NewRegistry builds a registry, refusing a factory this build cannot work
// with rather than discovering it during the first create.
//
// It refuses two things. A kind that is not one the store knows, because a row
// with that kind could never be written and a factory for it is dead code with
// a typo in it. And a contract range that does not contain ContractVersion: the
// message names both numbers and says which side to upgrade, because "version
// mismatch" without the numbers sends an operator to the release notes of the
// wrong half.
//
// It cannot check here that a factory's declared capabilities match the
// provider it builds -- that needs an instance, and building one needs a
// credential and a context. Registry.New makes that check at the moment the
// instance exists, which is the earliest it can be made and still before the
// reconciler has called anything.
func NewRegistry(fs ...Factory) (*Registry, error) {
	r := &Registry{factories: make(map[store.ProviderKind]Factory, len(fs))}
	for _, f := range fs {
		if f == nil {
			continue
		}
		kind := f.Kind()
		if !kind.Valid() {
			return nil, fmt.Errorf("provider: %q is not a provider kind this build knows", kind)
		}
		if err := checkContract(kind, f.Describe()); err != nil {
			return nil, err
		}
		if _, dup := r.factories[kind]; dup {
			return nil, fmt.Errorf("provider: two factories are registered for %q; one of them is the wrong kind", kind)
		}
		r.factories[kind] = f
	}
	return r, nil
}

// Get returns the factory for a kind, or ErrUnsupported when this build has
// none. The message names the kind, because the row that asked for it is the
// thing an operator has to go and change.
func (r *Registry) Get(k store.ProviderKind) (Factory, error) {
	f, ok := r.factories[k]
	if !ok {
		return nil, fmt.Errorf("%w: this build has no %q provider", ErrUnsupported, k)
	}
	return f, nil
}

// Kinds returns the registered kinds, sorted, so that a list rendered to an
// operator does not reshuffle itself between requests.
func (r *Registry) Kinds() []store.ProviderKind {
	out := make([]store.ProviderKind, 0, len(r.factories))
	for k := range r.factories {
		out = append(out, k)
	}
	slices.Sort(out)
	return out
}

// New builds the provider for one configuration row and checks that what it
// says about itself is true before handing it to anyone.
//
// The checks are here rather than in the reconciler because a capability that
// lies is a programming error in a provider, and the honest moment to catch one
// is when the provider is built: a reconciler that discovered it would discover
// it mid-create, on a machine somebody is paying for.
func (r *Registry) New(ctx context.Context, kind store.ProviderKind, cfg Config) (Provider, error) {
	f, err := r.Get(kind)
	if err != nil {
		return nil, err
	}
	p, err := f.New(ctx, cfg)
	if err != nil {
		return nil, err
	}
	if p == nil {
		return nil, fmt.Errorf("provider: the %q factory returned no provider and no error", kind)
	}
	if p.Kind() != kind {
		return nil, fmt.Errorf("provider: the %q factory built a %q provider", kind, p.Kind())
	}
	if err := checkContract(kind, p.Capabilities()); err != nil {
		return nil, err
	}
	if err := CheckCapabilities(p); err != nil {
		return nil, err
	}
	if err := checkDescription(f, p); err != nil {
		return nil, err
	}
	return p, nil
}

// CheckCapabilities reports whether a provider's declared capabilities agree
// with its type.
//
// Each optional capability is a separate interface found by type assertion, so
// the flag and the method set can disagree, and both directions are bugs worth
// naming. A flag that says yes where the type says no has the reconciler call a
// method that is not there; a flag that says no where the type says yes loses a
// capability silently, and the machine an operator expected to be stopped is
// deleted and bought again instead.
//
// It is exported because the conformance suite runs it against every provider
// and a provider's own tests may want it directly.
func CheckCapabilities(p Provider) error {
	caps := p.Capabilities()
	_, power := p.(PowerController)
	if caps.CanStartStop != power {
		return fmt.Errorf("provider: %s says CanStartStop=%t but %s PowerController; make the two agree",
			p.Kind(), caps.CanStartStop, implements(power))
	}
	_, discover := p.(Discoverer)
	if caps.CanDiscover != discover {
		return fmt.Errorf("provider: %s says CanDiscover=%t but %s Discoverer; make the two agree",
			p.Kind(), caps.CanDiscover, implements(discover))
	}
	_, boot := p.(Bootstrapper)
	if wantBoot := caps.Bootstrap == BootstrapGuestAgent; wantBoot != boot {
		return fmt.Errorf("provider: %s declares bootstrap mode %q but %s Bootstrapper; a provider that pushes the payload itself implements it, and one that does not says so",
			p.Kind(), caps.Bootstrap, implements(boot))
	}
	return nil
}

func implements(ok bool) string {
	if ok {
		return "implements"
	}
	return "does not implement"
}

// checkDescription holds a factory's description and its instances together. A
// page that lists what a kind can do is rendered from Describe() without
// building anything, so a description that disagrees with the provider is a
// promise made to an operator that the fleet then breaks.
func checkDescription(f Factory, p Provider) error {
	d, c := f.Describe(), p.Capabilities()
	switch {
	case d.CanStartStop != c.CanStartStop:
		return fmt.Errorf("provider: the %s factory describes CanStartStop=%t and builds %t", p.Kind(), d.CanStartStop, c.CanStartStop)
	case d.CanDiscover != c.CanDiscover:
		return fmt.Errorf("provider: the %s factory describes CanDiscover=%t and builds %t", p.Kind(), d.CanDiscover, c.CanDiscover)
	case d.Bootstrap != c.Bootstrap:
		return fmt.Errorf("provider: the %s factory describes bootstrap mode %q and builds %q", p.Kind(), d.Bootstrap, c.Bootstrap)
	}
	return nil
}

// checkContract is the version handshake, in one place so that the factory and
// the instance are held to the same range.
func checkContract(kind store.ProviderKind, caps Capabilities) error {
	if caps.MinContract > caps.MaxContract {
		return fmt.Errorf("%w: the %s provider declares contract range %d..%d, which contains nothing",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract)
	}
	if ContractVersion < caps.MinContract {
		return fmt.Errorf("%w: the %s provider speaks contract %d..%d and this build speaks %d; upgrade Zoomies",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract, ContractVersion)
	}
	if ContractVersion > caps.MaxContract {
		return fmt.Errorf("%w: the %s provider speaks contract %d..%d and this build speaks %d; upgrade the provider",
			ErrUnsupported, kind, caps.MinContract, caps.MaxContract, ContractVersion)
	}
	return nil
}

// Package qr encodes a short string as a QR code and renders it as SVG.
//
// It exists for one picture: the otpauth:// address an authenticator app
// scans when somebody turns two-step verification on. That is a few hundred
// bytes at most, so this is the smallest encoder that serves it -- byte mode
// only, error correction level M only, versions 1 to 10 -- rather than a
// dependency that would also do kanji, micro codes and PNG. Rendering on the
// server keeps the secret out of any third-party script, and SVG keeps it
// sharp at any size with no image library.
//
// The numbers are ISO/IEC 18004's. Where a table is written out below it is
// copied from the standard rather than derived, because a derived table that
// is subtly wrong still produces a picture, just not one a phone can read.
package qr

import (
	"errors"
	"fmt"
	"strings"
)

// ErrTooLong is returned for data that does not fit in the largest version
// this encoder supports.
var ErrTooLong = errors.New("qr: data is too long for a version 10 code at error correction level M")

// ecBlocks is one version's error correction layout at level M: the error
// correction codewords per block, then the blocks in each of the two groups
// and the data codewords each of their blocks holds.
type ecBlocks struct {
	ecPerBlock       int
	g1Blocks, g1Data int
	g2Blocks, g2Data int
}

// levelM is ISO/IEC 18004 table 9, level M, versions 1 to 10.
var levelM = [...]ecBlocks{
	1:  {10, 1, 16, 0, 0},
	2:  {16, 1, 28, 0, 0},
	3:  {26, 1, 44, 0, 0},
	4:  {18, 2, 32, 0, 0},
	5:  {24, 2, 43, 0, 0},
	6:  {16, 4, 27, 0, 0},
	7:  {18, 4, 31, 0, 0},
	8:  {22, 2, 38, 2, 39},
	9:  {22, 3, 36, 2, 37},
	10: {26, 4, 43, 1, 44},
}

// alignment is the row and column centres of the alignment patterns, from
// annex E.
var alignment = [...][]int{
	1: nil, 2: {6, 18}, 3: {6, 22}, 4: {6, 26}, 5: {6, 30},
	6: {6, 34}, 7: {6, 22, 38}, 8: {6, 24, 42}, 9: {6, 26, 46}, 10: {6, 28, 50},
}

const maxVersion = 10

func (b ecBlocks) dataCodewords() int { return b.g1Blocks*b.g1Data + b.g2Blocks*b.g2Data }

// Code is an encoded symbol: a square of modules, true for dark.
type Code struct {
	Version int
	Mask    int
	Size    int
	modules [][]bool
	// reservedMap marks function modules, which data and masks skip.
	reservedMap [][]bool
}

// Dark reports whether the module at row y, column x is dark.
func (c *Code) Dark(x, y int) bool { return c.modules[y][x] }

// Encode builds the smallest symbol that holds data, with the mask that
// scores lowest on the standard's penalty rules.
func Encode(data []byte) (*Code, error) {
	version := 0
	for v := 1; v <= maxVersion; v++ {
		// Mode indicator (4 bits), a character count (8 bits below version
		// 10, 16 from it), then the bytes.
		countBits := 8
		if v >= 10 {
			countBits = 16
		}
		if 4+countBits+8*len(data) <= 8*levelM[v].dataCodewords() {
			version = v
			break
		}
	}
	if version == 0 {
		return nil, ErrTooLong
	}
	codewords := interleave(version, dataCodewords(version, data))

	best := (*Code)(nil)
	bestScore := 0
	for mask := 0; mask < 8; mask++ {
		c := withMask(version, codewords, mask)
		if score := c.penalty(); best == nil || score < bestScore {
			best, bestScore = c, score
		}
	}
	return best, nil
}

// withMask lays the codewords out under one mask.
func withMask(version int, codewords []byte, mask int) *Code {
	c := newCode(version)
	c.Mask = mask
	c.placeData(codewords, mask)
	c.placeFormat(mask)
	return c
}

// dataCodewords renders data as a byte-mode segment padded out to the
// version's capacity.
func dataCodewords(version int, data []byte) []byte {
	var bits bitBuffer
	bits.put(0b0100, 4)
	if version >= 10 {
		bits.put(len(data), 16)
	} else {
		bits.put(len(data), 8)
	}
	for _, b := range data {
		bits.put(int(b), 8)
	}
	capacity := 8 * levelM[version].dataCodewords()
	// Up to four zero bits of terminator, then zeros to the byte boundary.
	for i := 0; i < 4 && len(bits) < capacity; i++ {
		bits = append(bits, false)
	}
	for len(bits)%8 != 0 {
		bits = append(bits, false)
	}
	out := bits.bytes()
	for pad := 0; len(out) < capacity/8; pad++ {
		if pad%2 == 0 {
			out = append(out, 0xEC)
		} else {
			out = append(out, 0x11)
		}
	}
	return out
}

// interleave splits the data into the version's blocks, appends each
// block's error correction, and interleaves them as the symbol stores them.
func interleave(version int, data []byte) []byte {
	b := levelM[version]
	var blocks [][]byte
	pos := 0
	for i := 0; i < b.g1Blocks; i++ {
		blocks = append(blocks, data[pos:pos+b.g1Data])
		pos += b.g1Data
	}
	for i := 0; i < b.g2Blocks; i++ {
		blocks = append(blocks, data[pos:pos+b.g2Data])
		pos += b.g2Data
	}
	ecc := make([][]byte, len(blocks))
	for i, blk := range blocks {
		ecc[i] = reedSolomon(blk, b.ecPerBlock)
	}
	var out []byte
	longest := b.g1Data
	if b.g2Data > longest {
		longest = b.g2Data
	}
	for i := 0; i < longest; i++ {
		for _, blk := range blocks {
			if i < len(blk) {
				out = append(out, blk[i])
			}
		}
	}
	for i := 0; i < b.ecPerBlock; i++ {
		for _, e := range ecc {
			out = append(out, e[i])
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Reed-Solomon over GF(256) with the QR polynomial x^8+x^4+x^3+x^2+1.
// ---------------------------------------------------------------------------

var gfExp, gfLog = func() (exp [512]byte, log [256]byte) {
	x := 1
	for i := 0; i < 255; i++ {
		exp[i] = byte(x)
		log[x] = byte(i)
		x <<= 1
		if x&0x100 != 0 {
			x ^= 0x11D
		}
	}
	for i := 255; i < 512; i++ {
		exp[i] = exp[i-255]
	}
	return exp, log
}()

func gfMul(a, b byte) byte {
	if a == 0 || b == 0 {
		return 0
	}
	return gfExp[int(gfLog[a])+int(gfLog[b])]
}

// generator returns the degree-n generator polynomial, highest term first.
func generator(n int) []byte {
	g := []byte{1}
	for i := 0; i < n; i++ {
		next := make([]byte, len(g)+1)
		for j, c := range g {
			next[j] ^= c
			next[j+1] ^= gfMul(c, gfExp[i])
		}
		g = next
	}
	return g
}

// reedSolomon returns the n error correction codewords for data.
func reedSolomon(data []byte, n int) []byte {
	g := generator(n)
	rem := make([]byte, n)
	for _, d := range data {
		factor := d ^ rem[0]
		copy(rem, rem[1:])
		rem[n-1] = 0
		for j := 0; j < n; j++ {
			rem[j] ^= gfMul(g[j+1], factor)
		}
	}
	return rem
}

// ---------------------------------------------------------------------------
// Module placement
// ---------------------------------------------------------------------------

func newCode(version int) *Code {
	size := 17 + 4*version
	c := &Code{Version: version, Size: size, modules: make([][]bool, size)}
	reserved := make([][]bool, size)
	for i := range c.modules {
		c.modules[i] = make([]bool, size)
		reserved[i] = make([]bool, size)
	}
	c.reservedMap = reserved
	c.placeFunctionPatterns()
	return c
}

// set places a function module, which data placement and masking skip.
func (c *Code) set(x, y int, dark bool) {
	c.modules[y][x] = dark
	c.reservedMap[y][x] = true
}

func (c *Code) placeFunctionPatterns() {
	n := c.Size
	// Finder patterns, with their separators, in three corners.
	for _, at := range [][2]int{{0, 0}, {n - 7, 0}, {0, n - 7}} {
		for dy := -1; dy <= 7; dy++ {
			for dx := -1; dx <= 7; dx++ {
				x, y := at[0]+dx, at[1]+dy
				if x < 0 || y < 0 || x >= n || y >= n {
					continue
				}
				ring := max(abs(dx-3), abs(dy-3))
				c.set(x, y, ring != 2 && ring != 4)
			}
		}
	}
	// Timing patterns.
	for i := 8; i < n-8; i++ {
		c.set(i, 6, i%2 == 0)
		c.set(6, i, i%2 == 0)
	}
	// Alignment patterns, everywhere they do not collide with a finder.
	// Three of the grid's corners are finder patterns; every other centre,
	// including the ones on the timing lines, gets a pattern.
	centres := alignment[c.Version]
	last := len(centres) - 1
	for i, cy := range centres {
		for j, cx := range centres {
			if (i == 0 && j == 0) || (i == 0 && j == last) || (i == last && j == 0) {
				continue
			}
			for dy := -2; dy <= 2; dy++ {
				for dx := -2; dx <= 2; dx++ {
					c.set(cx+dx, cy+dy, max(abs(dx), abs(dy)) != 1)
				}
			}
		}
	}
	// Reserve the format areas (written once the mask is chosen) and the
	// dark module.
	for i := 0; i < 9; i++ {
		c.reservedMap[8][i] = true
		c.reservedMap[i][8] = true
	}
	for i := 0; i < 8; i++ {
		c.reservedMap[8][n-1-i] = true
		c.reservedMap[n-1-i][8] = true
	}
	c.set(8, n-8, true)
	// Version information, from version 7.
	if c.Version >= 7 {
		bits := versionBits(c.Version)
		for i := 0; i < 18; i++ {
			dark := bits>>uint(i)&1 == 1
			a, b := i/3, n-11+i%3
			c.set(a, b, dark)
			c.set(b, a, dark)
		}
	}
}

// placeData writes the codewords in the standard's two-column zigzag, from
// the bottom-right corner, applying the mask as it goes.
func (c *Code) placeData(codewords []byte, mask int) {
	n := c.Size
	bit := 0
	total := len(codewords) * 8
	upward := true
	for right := n - 1; right >= 1; right -= 2 {
		if right == 6 {
			// The vertical timing pattern takes a whole column.
			right = 5
		}
		for i := 0; i < n; i++ {
			y := i
			if upward {
				y = n - 1 - i
			}
			for dx := 0; dx < 2; dx++ {
				x := right - dx
				if c.reservedMap[y][x] {
					continue
				}
				dark := false
				if bit < total {
					dark = codewords[bit/8]>>uint(7-bit%8)&1 == 1
					bit++
				}
				if maskAt(mask, x, y) {
					dark = !dark
				}
				c.modules[y][x] = dark
			}
		}
		upward = !upward
	}
}

// maskAt is the eight data masks of table 10.
func maskAt(mask, x, y int) bool {
	switch mask {
	case 0:
		return (x+y)%2 == 0
	case 1:
		return y%2 == 0
	case 2:
		return x%3 == 0
	case 3:
		return (x+y)%3 == 0
	case 4:
		return (y/2+x/3)%2 == 0
	case 5:
		return (x*y)%2+(x*y)%3 == 0
	case 6:
		return ((x*y)%2+(x*y)%3)%2 == 0
	default:
		return ((x+y)%2+(x*y)%3)%2 == 0
	}
}

// formatBits is the 15-bit format word for level M and a mask: a BCH(15,5)
// code, XORed with the standard's fixed pattern so it is never all light.
func formatBits(mask int) int {
	const levelMBits = 0b00
	data := levelMBits<<3 | mask
	rem := data << 10
	for i := 14; i >= 10; i-- {
		if rem>>uint(i)&1 == 1 {
			rem ^= 0x537 << uint(i-10)
		}
	}
	return (data<<10 | rem) ^ 0x5412
}

// versionBits is the 18-bit version word: a BCH(18,6) code.
func versionBits(version int) int {
	rem := version << 12
	for i := 17; i >= 12; i-- {
		if rem>>uint(i)&1 == 1 {
			rem ^= 0x1F25 << uint(i-12)
		}
	}
	return version<<12 | rem
}

func (c *Code) placeFormat(mask int) {
	n := c.Size
	bits := formatBits(mask)
	bitAt := func(i int) bool { return bits>>uint(i)&1 == 1 }
	// Around the top-left finder: bits 0-5 down column 8, then 6-7 skipping
	// the timing row, 8 on the corner, 9-14 along row 8.
	for i := 0; i <= 5; i++ {
		c.modules[i][8] = bitAt(i)
	}
	c.modules[7][8] = bitAt(6)
	c.modules[8][8] = bitAt(7)
	c.modules[8][7] = bitAt(8)
	for i := 9; i < 15; i++ {
		c.modules[8][14-i] = bitAt(i)
	}
	// The second copy, split between the other two finders.
	for i := 0; i < 8; i++ {
		c.modules[8][n-1-i] = bitAt(i)
	}
	for i := 8; i < 15; i++ {
		c.modules[n-15+i][8] = bitAt(i)
	}
	c.modules[n-8][8] = true
}

// penalty scores a finished symbol by the four rules of section 7.8.3; the
// lowest-scoring mask is the one a scanner finds easiest.
func (c *Code) penalty() int {
	n := c.Size
	score := 0
	// Rule 1: runs of five or more in a row or column.
	for y := 0; y < n; y++ {
		for _, line := range [2]func(i int) bool{
			func(i int) bool { return c.modules[y][i] },
			func(i int) bool { return c.modules[i][y] },
		} {
			run := 1
			for i := 1; i < n; i++ {
				if line(i) == line(i-1) {
					run++
					continue
				}
				if run >= 5 {
					score += run - 2
				}
				run = 1
			}
			if run >= 5 {
				score += run - 2
			}
		}
	}
	// Rule 2: two-by-two blocks of one colour.
	for y := 0; y < n-1; y++ {
		for x := 0; x < n-1; x++ {
			d := c.modules[y][x]
			if c.modules[y][x+1] == d && c.modules[y+1][x] == d && c.modules[y+1][x+1] == d {
				score += 3
			}
		}
	}
	// Rule 3: anything that looks like a finder pattern.
	pattern := []bool{true, false, true, true, true, false, true, false, false, false, false}
	for y := 0; y < n; y++ {
		for x := 0; x+len(pattern) <= n; x++ {
			fwdRow, revRow, fwdCol, revCol := true, true, true, true
			for k, p := range pattern {
				if c.modules[y][x+k] != p {
					fwdRow = false
				}
				if c.modules[y][x+len(pattern)-1-k] != p {
					revRow = false
				}
				if c.modules[x+k][y] != p {
					fwdCol = false
				}
				if c.modules[x+len(pattern)-1-k][y] != p {
					revCol = false
				}
			}
			for _, hit := range []bool{fwdRow, revRow, fwdCol, revCol} {
				if hit {
					score += 40
				}
			}
		}
	}
	// Rule 4: how far the dark proportion is from half.
	dark := 0
	for y := 0; y < n; y++ {
		for x := 0; x < n; x++ {
			if c.modules[y][x] {
				dark++
			}
		}
	}
	percent := dark * 100 / (n * n)
	score += abs(percent-50) / 5 * 10
	return score
}

// SVG renders the symbol with the four-module quiet zone the standard asks
// for, as one path. The colours are the caller's: the page draws it dark on
// light in both themes, because a scanner wants contrast, not a theme.
func (c *Code) SVG(dark, light string) string {
	const quiet = 4
	size := c.Size + 2*quiet
	var path strings.Builder
	for y := 0; y < c.Size; y++ {
		for x := 0; x < c.Size; x++ {
			if !c.modules[y][x] {
				continue
			}
			// Runs along a row become one rectangle, which keeps a version
			// 10 symbol to a few kilobytes.
			start := x
			for x+1 < c.Size && c.modules[y][x+1] {
				x++
			}
			fmt.Fprintf(&path, "M%d %dh%dv1h-%dz", start+quiet, y+quiet, x-start+1, x-start+1)
		}
	}
	return fmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" shape-rendering="crispEdges">`+
		`<rect width="%d" height="%d" fill="%s"/><path d="%s" fill="%s"/></svg>`,
		size, size, size, size, light, path.String(), dark)
}

// bitBuffer is a big-endian bit stream.
type bitBuffer []bool

func (b *bitBuffer) put(v, n int) {
	for i := n - 1; i >= 0; i-- {
		*b = append(*b, v>>uint(i)&1 == 1)
	}
}

func (b bitBuffer) bytes() []byte {
	out := make([]byte, len(b)/8)
	for i, bit := range b {
		if bit {
			out[i/8] |= 1 << uint(7-i%8)
		}
	}
	return out
}

func abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

package qr

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
	"testing"
)

// The error correction is the part a mistake hides in best: a symbol with
// wrong ECC still draws, and still scans on a good camera, until one module
// is smudged. The vector is the standard worked example, "HELLO WORLD" as a
// version 1-M symbol.
func TestReedSolomonMatchesTheWorkedExample(t *testing.T) {
	data := []byte{32, 91, 11, 120, 209, 114, 220, 77, 67, 64, 236, 17, 236, 17, 236, 17}
	want := []byte{196, 35, 39, 119, 235, 215, 231, 226, 93, 23}
	if got := reedSolomon(data, 10); !bytes.Equal(got, want) {
		t.Fatalf("reedSolomon = %v, want %v", got, want)
	}
}

func TestFormatAndVersionWordsMatchTheStandardsTables(t *testing.T) {
	for _, tc := range []struct {
		mask int
		want string
	}{
		{0, "101010000010010"},
		{1, "101000100100101"},
		{2, "101111001111100"},
		{3, "101101101001011"},
		{4, "100010111111001"},
		{5, "100000011001110"},
		{6, "100111110010111"},
		{7, "100101010100000"},
	} {
		if got := fmt.Sprintf("%015b", formatBits(tc.mask)); got != tc.want {
			t.Errorf("formatBits(M, %d) = %s, want %s", tc.mask, got, tc.want)
		}
	}
	for _, tc := range []struct {
		version int
		want    string
	}{
		{7, "000111110010010100"},
		{8, "001000010110111100"},
		{10, "001010010011010011"},
	} {
		if got := fmt.Sprintf("%018b", versionBits(tc.version)); got != tc.want {
			t.Errorf("versionBits(%d) = %s, want %s", tc.version, got, tc.want)
		}
	}
}

// readCodewords walks a finished symbol the way a scanner does -- the same
// zigzag, skipping function modules, removing the mask -- and returns the
// bytes it finds. Placement and reading written separately would agree on a
// shared mistake; this one leans on newCode only for which modules are
// function modules, which the finder, timing and alignment checks pin down.
func readCodewords(c *Code, n int) []byte {
	ref := newCode(c.Version)
	var bits bitBuffer
	upward := true
	for right := c.Size - 1; right >= 1; right -= 2 {
		if right == 6 {
			right = 5
		}
		for i := 0; i < c.Size; i++ {
			y := i
			if upward {
				y = c.Size - 1 - i
			}
			for dx := 0; dx < 2; dx++ {
				x := right - dx
				if ref.reservedMap[y][x] {
					continue
				}
				bits = append(bits, c.Dark(x, y) != maskAt(c.Mask, x, y))
			}
		}
		upward = !upward
	}
	return bits.bytes()[:n]
}

func TestEverySupportedVersionRoundTripsItsCodewords(t *testing.T) {
	for v := 1; v <= maxVersion; v++ {
		b := levelM[v]
		// The longest payload the version holds, so the version chosen is v.
		countBits := 8
		if v >= 10 {
			countBits = 16
		}
		n := (8*b.dataCodewords() - 4 - countBits) / 8
		data := bytes.Repeat([]byte("otpauth://totp/"), 20)[:n]
		c, err := Encode(data)
		if err != nil {
			t.Fatalf("version %d: %v", v, err)
		}
		if c.Version != v || c.Size != 17+4*v {
			t.Fatalf("%d bytes chose version %d (size %d), want %d", n, c.Version, c.Size, v)
		}
		want := interleave(v, dataCodewords(v, data))
		if got := readCodewords(c, len(want)); !bytes.Equal(got, want) {
			t.Errorf("version %d: the codewords read back differ from the ones placed", v)
		}
	}
}

func TestTheFunctionPatternsAreWhereAScannerLooks(t *testing.T) {
	c, err := Encode([]byte("otpauth://totp/Zoomies:ada?secret=JBSWY3DPEHPK3PXP&issuer=Zoomies"))
	if err != nil {
		t.Fatal(err)
	}
	finder := []string{"1111111", "1000001", "1011101", "1011101", "1011101", "1000001", "1111111"}
	for _, at := range [][2]int{{0, 0}, {c.Size - 7, 0}, {0, c.Size - 7}} {
		for dy, row := range finder {
			for dx, ch := range row {
				if c.Dark(at[0]+dx, at[1]+dy) != (ch == '1') {
					t.Fatalf("the finder at %v is wrong at (%d,%d)", at, dx, dy)
				}
			}
		}
	}
	for i := 8; i < c.Size-8; i++ {
		if c.Dark(i, 6) != (i%2 == 0) || c.Dark(6, i) != (i%2 == 0) {
			t.Fatalf("the timing pattern is broken at %d", i)
		}
	}
	if !c.Dark(8, c.Size-8) {
		t.Fatal("the dark module is light")
	}
	// Both copies of the format word say level M and the chosen mask.
	var first, second int
	for i := 0; i <= 5; i++ {
		first |= b2i(c.Dark(8, i)) << i
	}
	first |= b2i(c.Dark(8, 7))<<6 | b2i(c.Dark(8, 8))<<7 | b2i(c.Dark(7, 8))<<8
	for i := 9; i < 15; i++ {
		first |= b2i(c.Dark(14-i, 8)) << i
	}
	for i := 0; i < 8; i++ {
		second |= b2i(c.Dark(c.Size-1-i, 8)) << i
	}
	for i := 8; i < 15; i++ {
		second |= b2i(c.Dark(8, c.Size-15+i)) << i
	}
	if first != formatBits(c.Mask) || second != first {
		t.Fatalf("format words %015b and %015b, want %015b", first, second, formatBits(c.Mask))
	}
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

func TestTooMuchDataIsRefusedRatherThanTruncated(t *testing.T) {
	if _, err := Encode(bytes.Repeat([]byte("a"), 300)); !errors.Is(err, ErrTooLong) {
		t.Fatalf("300 bytes = %v, want ErrTooLong", err)
	}
}

func TestTheSVGIsSelfContainedAndCarriesTheQuietZone(t *testing.T) {
	c, err := Encode([]byte("hello"))
	if err != nil {
		t.Fatal(err)
	}
	svg := c.SVG("#000", "#fff")
	for _, want := range []string{`viewBox="0 0 29 29"`, `fill="#fff"`, `fill="#000"`, `M4 4h7v1h-7z`} {
		if !strings.Contains(svg, want) {
			t.Errorf("the SVG does not contain %q", want)
		}
	}
	for _, banned := range []string{"<script", "href", "http://example"} {
		if strings.Contains(svg, banned) {
			t.Errorf("the SVG contains %q", banned)
		}
	}
}

package scheduler

import (
	"math"

	"github.com/eyupio/zoomies/internal/store"
)

// Allocation is what one runner of p is limited to when it is created on h,
// and where those limits came from.
//
// It is the enforcement half of the resource model, and it closes the gap the
// charge left open. Reserve charges a pool that sets no limit one slot's share
// of the host, so the books balance -- and until now the runner itself was
// given no limit at all, so the books balanced while eight runners each took
// every core on the machine. A pool's own limits win where it set them; where
// it did not, the runner is given exactly what it was charged, as a cgroup
// limit the container backends apply.
//
// It is per field, as Reserve is, and for the same reason: a pool that sets
// memory and leaves CPU alone has said something about memory and nothing
// about CPU. Disk and the pids limit pass through untouched -- disk has no
// share to give (it is a measurement, not a budget) and a pids limit is not a
// thing the machine's size says anything about.
//
// A docker-in-docker runner's sidecar is given what this function hands back
// as spec.Resources, and what that is depends on where the figure came from.
// A limit an operator typed is given to both containers in full -- the build
// runs in the daemon, so it needs the same figure the runner was promised --
// and Reserve charges the host for both. A defaulted figure is one slot's
// share, and store.Resources.SplitWithDaemon divides it between the pair
// before either container is created, because a slot is one runner however
// many containers it takes to run it; Reserve charges one share to match.
//
// A slot too small to give both halves what a runner needs is refused rather
// than divided -- see ShareFloor -- because handing the daemon whatever is
// left over is no limit at all, which is how one build takes the machine.
//
// A default is only given where it would bind. The process backend applies no
// limit at all, so a defaulted figure on one of its runners would be a number
// on the Runners page saying the opposite of the truth. And a daemon that
// cannot apply a CPU quota -- rootless Docker on a host that delegates only
// memory and pids to the user -- refuses the container rather than ignoring
// the request, so a default sent there would fail every create on the host.
// The host's own probe says what its daemon can do, and a probe from an agent
// too old to say is read as "nothing", which is what every host did before.
//
// An automatic pool with a minimum above the slot share is given the minimum
// instead -- see MinimumSlot -- because a share smaller than the least the
// operator said a runner may have is a runner set up to be killed.
//
// With defaults off the pool's limits are the whole answer, which is what
// every fleet had before this existed.
func Allocation(p *store.Pool, h *store.Host, defaults bool) (store.Resources, string) {
	res := p.Resources
	source := ""
	if res.CPUs > 0 || res.MemoryMB > 0 {
		source = store.AllocationFromPool
	}
	if !defaults || h == nil || p.Backend == store.BackendProcess {
		return res, source
	}
	info, _ := h.BackendInfo.Find(p.Backend)
	limits := hostLimits(h, p.Backend)
	alloc := h.Allocatable()
	def := HostShare(h)
	// A share under the pool's minimum is raised to it, which is what Reserve
	// charges: the minimum is the least a runner is given, never the most.
	floor := MinimumSlot(p)
	def.CPUs = max(def.CPUs, floor.CPUs)
	def.MemoryMB = max(def.MemoryMB, floor.MemoryMB)
	if res.CPUs <= 0 && alloc.CPUsKnown && limits.CPU && def.CPUs > 0 {
		// The share is a request to the daemon, and a daemon refuses a quota
		// above its own core count whatever the agent's machine has: a
		// Docker Desktop VM on a ten-core laptop has four. The host is sized
		// by its daemon, so this is a belt on braces, for a row whose size
		// and probe disagree.
		if info.CPUs > 0 && def.CPUs > float64(info.CPUs) {
			def.CPUs = float64(info.CPUs)
		}
		res.CPUs = def.CPUs
		source = store.AllocationFromHost
	}
	if res.MemoryMB <= 0 && alloc.MemoryKnown && limits.Memory && def.MemoryMB > 0 {
		res.MemoryMB = def.MemoryMB
		source = store.AllocationFromHost
	}
	return res, source
}

// HostShare is one slot's share of a host: the CPU and memory a runner of a
// pool that sets neither is given by Allocation, before the host's daemon is
// asked whether it can apply them. Zero on a field the host has not measured.
//
// It is exported so that the problem which warns about an over-provisioned
// host can say what each runner's default share would be in the same figures
// Allocation hands out, rather than in a second sum that could drift from it.
func HostShare(h *store.Host) store.Resources {
	if h == nil {
		return store.Resources{}
	}
	alloc := h.Allocatable()
	var out store.Resources
	if alloc.CPUsKnown {
		out.CPUs = shareCPUs(alloc.CPUs, h.Capacity)
	}
	if alloc.MemoryKnown {
		out.MemoryMB = int64(share(float64(alloc.MemoryMB), h.Capacity))
	}
	return out
}

// DefaultsBind reports which default limits would bind on this host at all:
// whether any available container backend on it has said it can apply a CPU
// quota, and a memory limit. It is what a problem about the host asks before
// it names "each runner's default share", because on a host offering only
// the process backend, or one whose daemon cannot apply the limit, or one
// whose agent has not said, the share is never given and a sentence naming
// it would say the opposite of the truth.
func DefaultsBind(h *store.Host) (cpu, memory bool) {
	for _, info := range h.BackendInfo {
		if !info.Available || info.Kind == store.BackendProcess || !info.Limits.Known {
			continue
		}
		cpu = cpu || info.Limits.CPU
		memory = memory || info.Limits.Memory
	}
	return cpu, memory
}

// hostLimits is what the host's daemon for this backend said it can enforce.
// Unknown is every field false, which defaults nothing.
func hostLimits(h *store.Host, kind store.BackendKind) store.LimitSupport {
	info, ok := h.BackendInfo.Find(kind)
	if !ok || !info.Limits.Known {
		return store.LimitSupport{}
	}
	return info.Limits
}

// shareCPUs is one slot's worth of CPU, floored to the hundredth the pool
// form takes limits in. Floored rather than rounded: three runners rounded
// up from 0.667 to 0.67 would together be promised a hundredth of a core the
// host does not have, and the daemon refuses a quota above the machine.
func shareCPUs(total float64, capacity int) float64 {
	return math.Floor(share(total, capacity)*100) / 100
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A pool that sets no limit used to get a runner with no limit, charged one
// slot's share of the host it never had to honour. Eight such runners on an
// eight-slot host each took every core, and that is the overload this exists
// to end: the runner is given exactly what it was charged.
func TestAnUnlimitedPoolIsGivenOneSlotsShareOfItsHost(t *testing.T) {
	// 16 CPUs less the floor's 0.8 is 15.2, and 32 GB less the memory floor's
	// twentieth (1638 MB) is 31130 MB; four slots share both.
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)

	got, source := Allocation(p, h, true)
	if got.CPUs != 3.8 || got.MemoryMB != 7782 {
		t.Fatalf("allocation = %+v, want 3.8 CPUs and 7782 MB, one slot's share of the host", got)
	}
	if source != store.AllocationFromHost {
		t.Errorf("source = %q, want %q", source, store.AllocationFromHost)
	}
	// The charge and the allocation are the same figure, which is what makes
	// the books honest: what a host promises away is what its runners can
	// actually take.
	if charge := Reserve(p, h); charge.CPUs < got.CPUs || charge.MemoryMB != got.MemoryMB {
		t.Errorf("Reserve = %+v differs from the allocation %+v", charge, got)
	}
}

// Per field, as the charge is. A pool that set memory has said something about
// memory and nothing about CPU, so the pool answers for one and the host for
// the other -- and the source says the host had a hand in it, because that is
// what decides which setting an operator is sent to when a job runs out.
func TestAPartlyLimitedPoolKeepsItsOwnLimitsAndFillsTheRest(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 2048)
	p.Resources.PidsLimit = 512
	p.Resources.DiskGB = 10

	got, source := Allocation(p, h, true)
	if got.MemoryMB != 2048 || got.CPUs != 3.8 || got.PidsLimit != 512 || got.DiskGB != 10 {
		t.Fatalf("allocation = %+v, want the pool's memory, pids and disk with the host's CPU share", got)
	}
	if source != store.AllocationFromHost {
		t.Errorf("source = %q, want %q because the CPU came from the host", source, store.AllocationFromHost)
	}

	p = limited("builders", 2, 2048)
	if got, source := Allocation(p, h, true); got != p.Resources || source != store.AllocationFromPool {
		t.Errorf("a fully limited pool was changed: %+v from %q", got, source)
	}
}

// Defaults off is the fleet as it was: the pool's limits are the whole answer,
// and a pool with none gets none. An operator who turns them off is warned at
// startup, and the allocation has to honour the choice rather than the warning.
func TestDefaultsOffLeavesAnUnlimitedPoolUnlimited(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)
	if got, source := Allocation(p, h, false); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q with defaults off, want nothing", got, source)
	}
}

// A host that never measured itself has no share to give, so its runners are
// created as they always were. It is the same rule that places such a host by
// slots alone: a figure nobody reported constrains nothing, and inventing one
// would be worse than the overload it was meant to prevent.
func TestAnUnmeasuredHostGivesNoDefault(t *testing.T) {
	h := testHost("host_a", 4, 0)
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	p := limited("builders", 0, 0)
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on an unmeasured host, want nothing", got, source)
	}
	// Half measured: the CPU share is given, the memory is not.
	h.CPUs = 8
	got, source := Allocation(p, h, true)
	if got.CPUs != 1.87 || got.MemoryMB != 0 || source != store.AllocationFromHost {
		t.Fatalf("allocation = %+v from %q on a host that measured only its CPUs", got, source)
	}
}

// A daemon that cannot apply a quota refuses the container rather than
// ignoring the request: rootless Docker on a host that delegates only memory
// and pids to the user says so in its own probe, and a default CPU limit sent
// there would fail every create on the host. So each field is defaulted only
// where the daemon said it can bind it, and a probe from an agent too old to
// say defaults nothing -- which is what every host did before.
func TestADefaultIsOnlyGivenWhereTheDaemonCanEnforceIt(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)

	h.BackendInfo[0].Limits = store.LimitSupport{Known: true, CPU: false, Memory: true}
	got, source := Allocation(p, h, true)
	if got.CPUs != 0 || got.MemoryMB != 7782 || source != store.AllocationFromHost {
		t.Fatalf("allocation = %+v from %q on a daemon without CFS quotas, want memory alone", got, source)
	}
	h.BackendInfo[0].Limits = store.LimitSupport{}
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q from an agent that never said what its daemon can do", got, source)
	}
	h.BackendInfo = nil
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on a host with no probe at all", got, source)
	}
}

// The process backend applies no limit, so a defaulted figure on one of its
// runners would be a number on the Runners page saying the opposite of the
// truth. Such a runner is recorded as what it is: unlimited.
func TestAProcessPoolGetsNoDefault(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	h.Backends = store.StringSlice{"process"}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendProcess, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	p := limited("builders", 0, 0)
	p.Backend = store.BackendProcess
	if got, source := Allocation(p, h, true); got != (store.Resources{}) || source != "" {
		t.Fatalf("allocation = %+v from %q on a process pool, want nothing", got, source)
	}
	// The pool's own limits still travel, because the warning about them is
	// the pool's to earn.
	p = limited("builders", 2, 2048)
	p.Backend = store.BackendProcess
	if got, source := Allocation(p, h, true); got != p.Resources || source != store.AllocationFromPool {
		t.Fatalf("allocation = %+v from %q, want the pool's own limits", got, source)
	}
}

// The charge does not move with the throttle. Reserve and Allocation both
// divide by the operator's capacity, never the effective one: if they did not,
// stepping a host from four slots to two would double the charge on every
// runner already there, and the host card's committed figure would jump for
// runners that had not changed.
func TestTheShareIsAShareOfTheConfiguredCapacityWhateverTheThrottle(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	p := limited("builders", 0, 0)
	before, _ := Allocation(p, h, true)
	charge := Reserve(p, h)
	h.Throttle = store.HostThrottle{Level: 2}
	after, _ := Allocation(p, h, true)
	if after != before || Reserve(p, h) != charge {
		t.Fatalf("the throttle moved the share: %+v -> %+v, charge %+v -> %+v", before, after, charge, Reserve(p, h))
	}
}

// The share is floored to the hundredth, never rounded up: three runners
// rounded up from 0.667 to 0.67 would together be promised a hundredth of a
// core the host does not have, and the daemon refuses a quota above the
// machine.
func TestTheCPUShareIsFlooredToTheHundredth(t *testing.T) {
	if got := shareCPUs(2, 3); got != 0.66 {
		t.Errorf("shareCPUs(2, 3) = %v, want 0.66", got)
	}
	if got := shareCPUs(7.5, 3); got != 2.5 {
		t.Errorf("shareCPUs(7.5, 3) = %v, want 2.5 exactly", got)
	}
	if got := shareCPUs(4, 0); got != 0 {
		t.Errorf("shareCPUs(4, 0) = %v, want 0 for a host with no slots", got)
	}
}

// A share is a request to the daemon, and a daemon refuses a quota above its
// own core count however many cores the agent's machine has -- a Docker
// Desktop VM on a ten-core laptop has four. The host is sized by its daemon,
// so this only matters for a row whose size and probe disagree, and then the
// share is capped rather than the create refused.
func TestTheDefaultShareNeverExceedsTheDaemonsOwnCores(t *testing.T) {
	h := sized("host_a", 1, 10, 32*1024, 500*1024)
	h.BackendInfo[0].CPUs = 4
	p := limited("builders", 0, 0)
	got, _ := Allocation(p, h, true)
	if got.CPUs != 4 {
		t.Fatalf("allocation = %v CPUs, want the daemon's 4 rather than the agent's share of 10", got.CPUs)
	}
}

// A problem that names "each runner's default share" has to ask first whether
// a share is ever given: a host offering only the process backend, or a
// daemon that cannot apply the limit, gives none.
func TestDefaultsBindSaysWhichFieldsAHostCanBeGivenADefaultOn(t *testing.T) {
	h := sized("host_a", 4, 16, 32*1024, 500*1024)
	if cpu, memory := DefaultsBind(h); !cpu || !memory {
		t.Fatalf("a daemon that enforces both reported %v/%v", cpu, memory)
	}
	h.BackendInfo[0].Limits = store.LimitSupport{Known: true, CPU: false, Memory: true}
	if cpu, memory := DefaultsBind(h); cpu || !memory {
		t.Fatalf("a daemon without CFS quotas reported %v/%v", cpu, memory)
	}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendProcess, Available: true, Limits: store.LimitSupport{Known: true, CPU: true, Memory: true}}}
	if cpu, memory := DefaultsBind(h); cpu || memory {
		t.Fatalf("a process-only host reported %v/%v", cpu, memory)
	}
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true}}
	if cpu, memory := DefaultsBind(h); cpu || memory {
		t.Fatalf("an agent that has not said reported %v/%v", cpu, memory)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// partlyUsed is the host the automatic-pool tests share: 8 cores and 16 GB
// allocatable over two slots, so a slot's share is 3.75 cores (after the
// host's CPU reserve) and 8 GB. One slot is taken by a fixed-size runner of
// another pool holding 5 cores and 10 GB, which leaves one free slot and 2.5
// cores and 6 GB to go with it -- less than a whole share, more than a runner
// needs.
func partlyUsed(t *testing.T, auto *store.Pool) *hostSet {
	t.Helper()
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	h.ActiveRunners = 1
	big := limited("big", 5, 10*1024)
	r := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy}
	return newHostSet([]*store.Host{h}, []*store.Pool{big, auto}, map[string][]*store.Runner{big.ID: {r}}, now)
}

func automatic(name string, minCPUs float64, minMemoryMB int64) *store.Pool {
	p := testPool(name, name)
	p.Resources.MinCPUs, p.Resources.MinMemoryMB = minCPUs, minMemoryMB
	return p
}

// The report that found this: an automatic pool on a host with a free slot and
// room for a runner several times over, refused because it only ever asked for
// a whole slot's share. With a minimum it runs, on what the host has left.
func TestAnAutomaticPoolWithAMinimumRunsOnWhatIsLeftOfASlot(t *testing.T) {
	p := automatic("auto", 1, 2048)
	hs := partlyUsed(t, p)

	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].hostID != "h" {
		t.Fatalf("placed %+v, want one runner on the partly used host", placed)
	}
	size := placed[0].size
	if size == nil {
		t.Fatal("the runner was placed at a whole share on a host without one left")
	}
	// All of what is left, not the minimum: the minimum is a floor.
	if size.CPUs != 2.5 || size.MemoryMB != 6*1024 {
		t.Errorf("size = %g CPU and %d MB, want what the host has left: 2.5 and 6144", size.CPUs, size.MemoryMB)
	}
	// The charge is what the runner is created with, and the host's slot and
	// room are both gone.
	if hs.free["h"] != 0 {
		t.Errorf("free slots = %d, want 0", hs.free["h"])
	}
}

// Without a minimum nothing changes: an automatic pool is still a whole slot
// or nothing, and the refusal now says what to do about it instead of telling
// the operator to lower limits the pool does not have.
func TestAnAutomaticPoolWithoutAMinimumStillWantsAWholeShare(t *testing.T) {
	p := automatic("auto", 0, 0)
	hs := partlyUsed(t, p)

	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v on a host without a whole share left, with no minimum", got)
	}
	b := hs.why(p)
	if !strings.Contains(b.fix, "minimum") || strings.Contains(b.fix, "limits") {
		t.Errorf("fix = %q, want it to point at a minimum, not at limits the pool does not set", b.fix)
	}
}

// A minimum is a way down, never the first choice: a host with a whole share
// left gets a runner at the whole share.
func TestAnAutomaticMinimumNeverShrinksARunnerThatHasAWholeShare(t *testing.T) {
	h := sized("idle", 2, 8, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)

	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size != nil {
		t.Fatalf("placed %+v, want one runner at the standard share", placed)
	}
}

// Below the minimum is still no.
func TestAnAutomaticPoolDoesNotGoBelowItsMinimum(t *testing.T) {
	p := automatic("auto", 1, 8*1024)
	hs := partlyUsed(t, p)
	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v with 6 GB left under an 8 GB minimum", got)
	}
}

// A docker-in-docker slot is split between the runner and its daemon, and the
// pool's minimum is per container, so the slot is never cut below twice the
// minimum -- and no further than that: the operator's minimum, not the
// comfortable figure a pool nobody sized is held to, is what the pair needs.
func TestAnAutomaticDinDSlotIsNotCutBelowTwiceItsMinimum(t *testing.T) {
	p := automatic("auto", 0.5, 1024)
	p.DockerMode = store.DockerDinD
	floor := ShareFloor(p)
	if floor.CPUs != 1 || floor.MemoryMB != 2048 {
		t.Fatalf("ShareFloor = %+v, want twice the minimum: 1 core and 2 GB", floor)
	}

	for _, tc := range []struct {
		name   string
		used   float64
		placed bool
	}{
		{"exactly twice the minimum left", 6.5, true},
		{"less than twice the minimum left", 6.6, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 2, 8, hostFor(16*1024), 100000)
			h.ActiveRunners = 1
			big := limited("big", tc.used, 13*1024)
			r := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy}
			hs := newHostSet([]*store.Host{h}, []*store.Pool{big, p}, map[string][]*store.Runner{big.ID: {r}}, now)
			left := hs.leftFor(h, p)
			got := hs.placeAvoiding(p, 1, nil)
			if (len(got) == 1) != tc.placed {
				t.Fatalf("with %g cores left, placed %+v; want placed=%v against the pair's %g", left.CPUs, got, tc.placed, floor.CPUs)
			}
		})
	}
}

// A reduced automatic runner is charged what its row says it was given, once:
// its allocation is the whole of a (smaller) slot, shared with its daemon, not
// a per-container figure to double.
func TestAReducedAutomaticRunnerIsChargedWhatItWasGiven(t *testing.T) {
	p := automatic("auto", 1, 2048)
	p.DockerMode = store.DockerDinD
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	r := &store.Runner{ID: "r", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocationSource: store.AllocationReduced, AllocatedCPUs: 2.5, AllocatedMemoryMB: 6144}
	got := RunnerCharge(p, h, r)
	if got.CPUs != 2.5 || got.MemoryMB != 6144 {
		t.Errorf("charge = %+v, want 2.5 cores and 6144 MB", got)
	}
}

// A minimum above a small host's share is not a way up: it leaves the share as
// the least the pool asks for there.
func TestAnAutomaticMinimumAboveTheShareChangesNothing(t *testing.T) {
	h := sized("h", 4, 8, hostFor(8*1024), 100000)
	p := automatic("auto", 4, 8*1024)
	if got, want := MinimumReserve(p, h), Reserve(p, h); got != want {
		t.Errorf("MinimumReserve = %+v, want the share %+v", got, want)
	}
}

// End to end through Decide: a queued job for the automatic pool becomes a
// create on the partly used host, carrying the reduced size, with a reason
// that does not name a standard size the pool never set.
func TestAQueuedJobOnAnAutomaticPoolIsCreatedReduced(t *testing.T) {
	h := sized("h", 2, 8, hostFor(16*1024), 100000)
	h.ActiveRunners = 1
	big := limited("big", 5, 10*1024)
	auto := automatic("auto", 1, 2048)
	busy := &store.Runner{ID: "r1", PoolID: big.ID, HostID: h.ID, State: store.RunnerBusy, CreatedAt: now}
	s := snap([]*store.Pool{big, auto}, []*store.Runner{busy}, []*store.Job{queued("j1", time.Minute, "auto")}, []*store.Host{h})

	var creates []Action
	for _, a := range actionsOf(Decide(s).Actions, ActionCreate) {
		if a.PoolID == auto.ID {
			creates = append(creates, a)
		}
	}
	if len(creates) != 1 {
		t.Fatalf("creates for the automatic pool = %+v, want one", creates)
	}
	if creates[0].Size == nil || creates[0].Size.MemoryMB != 6*1024 {
		t.Errorf("size = %+v, want the 6 GB left carried on the action", creates[0].Size)
	}
	if !strings.Contains(creates[0].Reason, "reduced to 2.5 CPU and 6 GB") || strings.Contains(creates[0].Reason, "standard") {
		t.Errorf("reason = %q, want the reduced size and no standard the pool never set", creates[0].Reason)
	}
}

// The report behind this: an automatic docker-in-docker pool with a minimum,
// and a 4-core, 3 GB machine set to one slot. Its share is 2.8 GB, under the
// 4 GB a pair nobody sized is held to and over twice the minimum the operator
// typed, so it runs the pool -- at that share -- and saying so is information,
// not a reason it cannot. Without a minimum it still cannot, and with one the
// whole machine cannot cover the refusal names the minimum as the operator's to
// lower.
func TestAnAutomaticDinDPoolRunsAtItsMinimumOnASmallHostAndSaysSoAsInformation(t *testing.T) {
	h := sized("small", 1, 4, hostFor(2867), 100000)
	withMin := automatic("auto", 0, 1024)
	withMin.DockerMode = store.DockerDinD

	if !HostFits(h, withMin) {
		t.Fatalf("a 2.8 GB share was refused for a pool whose pair needs 2 GB: %s", HostShortfall(h, withMin))
	}
	if s := HostShortfall(h, withMin); s != "" {
		t.Errorf("shortfall = %q, want none", s)
	}
	note := HostReduction(h, withMin)
	if !strings.Contains(note, "2.8 GB") || !strings.Contains(note, "4 GB") || !strings.Contains(note, "minimum") {
		t.Errorf("reduction = %q, want the share, the comfortable size and the minimum", note)
	}

	noMin := automatic("plain", 0, 0)
	noMin.DockerMode = store.DockerDinD
	if HostFits(h, noMin) || !strings.Contains(HostShortfall(h, noMin), "a runner is killed before it takes a job below 4 GB") {
		t.Errorf("a pool nobody sized was placed on a thin slot: %q", HostShortfall(h, noMin))
	}

	high := automatic("high", 0, 2048)
	high.DockerMode = store.DockerDinD
	if got := HostShortfall(h, high); !strings.Contains(got, "this pool's minimum of 2 GB a container") {
		t.Errorf("shortfall = %q, want it to name the pool's own minimum", got)
	}
}

package scheduler

import (
	"math"
	"slices"
)

// ElasticCPUWorkload is one live runner in the host CPU ledger. Every live
// workload belongs in the input, including ones that may not burst: their base
// is already promised and therefore is not spare CPU.
type ElasticCPUWorkload struct {
	ID        string
	BaseCPUs  float64
	MaxCPUs   float64
	Demanding bool
	// Idle is a live runner waiting for a job. Idle runners are charged
	// together only the largest single guarantee among them, not the sum: at
	// most one of them can be handed the next job before the following plan,
	// and CPU they are not using is the whole point of lending.
	Idle bool
}

// ElasticCPUPlan lends a host's genuinely unpromised CPU to demanding
// workloads with max-min fairness.
//
// total is the host's allocatable CPU after its operator reserve. startReserve
// protects an imminent runner when compatible work is queued. A workload with
// MaxCPUs at or below BaseCPUs stays at its guarantee. Returned targets always
// include every workload, so an agent can restore a runner whose demand ended.
//
// Idle workloads are charged collectively as a start reserve -- the largest
// idle guarantee -- rather than each in full, or a host holding warm runners
// would never have anything to lend. The oversubscription that allows is
// bounded: when a second idle runner turns busy it is charged in full on the
// very next plan, and the plan is complete, so the lent CPU comes back then.
func ElasticCPUPlan(total, startReserve float64, workloads []ElasticCPUWorkload) map[string]float64 {
	targets := make(map[string]float64, len(workloads))
	ordered := slices.Clone(workloads)
	slices.SortFunc(ordered, func(a, b ElasticCPUWorkload) int {
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})

	committed, idleReserve := 0.0, 0.0
	var active []ElasticCPUWorkload
	for _, w := range ordered {
		base := max(w.BaseCPUs, 0)
		targets[w.ID] = base
		if w.Idle {
			idleReserve = max(idleReserve, base)
			continue
		}
		committed += base
		if w.Demanding && w.MaxCPUs > base+cpuEpsilon {
			active = append(active, w)
		}
	}
	spare := max(total-max(startReserve, 0)-idleReserve-committed, 0)

	// Water-fill rather than divide once: a runner with a low ceiling gives
	// what it cannot use back to the remaining runners instead of stranding it.
	for spare > cpuEpsilon && len(active) > 0 {
		share := spare / float64(len(active))
		next := active[:0]
		used := 0.0
		for _, w := range active {
			room := w.MaxCPUs - targets[w.ID]
			give := min(share, room)
			if give > 0 {
				targets[w.ID] += give
				used += give
			}
			if room-give > cpuEpsilon {
				next = append(next, w)
			}
		}
		if used <= cpuEpsilon {
			break
		}
		spare -= used
		active = next
	}

	// The daemon works in hundredths of a core. Floor each target so rounding
	// can never promise more CPU than total, even across many runners.
	for id, target := range targets {
		targets[id] = math.Floor((target+cpuEpsilon)*100) / 100
	}
	return targets
}

package scheduler

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func TestElasticCPUPlanLendsIdleCPUAndProtectsAStart(t *testing.T) {
	work := []ElasticCPUWorkload{{ID: "busy", BaseCPUs: 2, MaxCPUs: 8, Demanding: true}}
	if got := ElasticCPUPlan(8, 0, work)["busy"]; got != 8 {
		t.Fatalf("without queued work target = %v, want 8", got)
	}
	if got := ElasticCPUPlan(8, 2, work)["busy"]; got != 6 {
		t.Fatalf("with one start protected target = %v, want 6", got)
	}
}

func TestElasticCPUPlanIsFairAndReturnsUnusedCeilings(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "a", BaseCPUs: 2, MaxCPUs: 3, Demanding: true},
		{ID: "b", BaseCPUs: 2, MaxCPUs: 8, Demanding: true},
	}
	got := ElasticCPUPlan(8, 0, work)
	if got["a"] != 3 || got["b"] != 5 {
		t.Fatalf("targets = %v, want a=3 and b=5", got)
	}
}

func TestElasticCPUPlanCountsWorkloadsThatCannotBurst(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "fixed", BaseCPUs: 4, MaxCPUs: 4},
		{ID: "busy", BaseCPUs: 2, MaxCPUs: 8, Demanding: true},
	}
	got := ElasticCPUPlan(8, 0, work)
	if got["fixed"] != 4 || got["busy"] != 4 {
		t.Fatalf("targets = %v, want fixed=4 and busy=4", got)
	}
}

func TestElasticCPUPlanRestoresTheBaseWithoutDemand(t *testing.T) {
	got := ElasticCPUPlan(8, 0, []ElasticCPUWorkload{{ID: "quiet", BaseCPUs: 2, MaxCPUs: 8}})
	if got["quiet"] != 2 {
		t.Fatalf("quiet target = %v, want its base 2", got["quiet"])
	}
}

// Warm runners were the owners' commonest disappointment: sixteen CPUs, four
// slots, one busy job and three idle runners left nothing to lend, because
// every idle guarantee was charged in full. Only one of them can be handed the
// next job before the following plan, so only one is held back.
func TestElasticCPUPlanHoldsBackOneIdleGuaranteeNotAll(t *testing.T) {
	work := []ElasticCPUWorkload{
		{ID: "busy", BaseCPUs: 4, MaxCPUs: 16, Demanding: true},
		{ID: "idle-1", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
		{ID: "idle-2", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
		{ID: "idle-3", BaseCPUs: 4, MaxCPUs: 4, Idle: true},
	}
	got := ElasticCPUPlan(16, 0, work)
	if got["busy"] != 12 {
		t.Fatalf("busy target = %v, want 12: three idle runners hold back one guarantee between them", got["busy"])
	}
	for _, id := range []string{"idle-1", "idle-2", "idle-3"} {
		if got[id] != 4 {
			t.Errorf("%s target = %v, want its guarantee of 4", id, got[id])
		}
	}

	// One of them takes a job. The next plan charges it in full, and the
	// boost shrinks back so that everyone has their guarantee again.
	work[1].Idle = false
	got = ElasticCPUPlan(16, 0, work)
	if got["busy"] != 8 {
		t.Fatalf("after an idle runner turned busy the boost is %v, want 8", got["busy"])
	}
	// The two busy runners and the one idle guarantee still held back fit.
	if sum := got["busy"] + got["idle-1"] + 4; sum > 16 {
		t.Fatalf("busy targets plus the idle reserve are %v, more than the host's 16", sum)
	}
}

// A boost being used is load the plan chose, and the next plan takes it back
// for a start. Read as pressure it held new starts and kept a host on its
// throttle rung for doing what the plan asked.
func TestLentCPUInUseIsNotHostPressure(t *testing.T) {
	now := time.Now()
	cpu := 97.0
	h := &store.Host{CPUs: 16, Usage: store.HostUsage{CPUPercent: &cpu, SampledAt: now, LentCPUPercent: 40}}
	if hostUnderCPUPressure(h, now) {
		t.Error("a host at 97% with 40% of it lent CPU in use was under CPU pressure")
	}
	if !hostCalm(h) {
		t.Error("a host at 97% with 40% of it lent CPU in use was not calm")
	}
	h.Usage.LentCPUPercent = 0
	if !hostUnderCPUPressure(h, now) || hostCalm(h) {
		t.Error("a host at 97% with nothing lent was not judged under pressure")
	}
}

package scheduler

import (
	"fmt"
	"time"
)

// These thresholds decide when CPU lent to a runner comes back because the
// runner is not using it, and how long the controller then waits before
// lending to that runner again. They are deliberately far apart from the
// thresholds that lend in the first place, because the failure being designed
// out is a quota that moves on every heartbeat.
const (
	// LoanInUseShare is how much of a loan a runner must be using, above its
	// guarantee, for the loan to count as used. A quarter, not a half: a
	// build's usage is spiky between link and compile steps, and a loan that
	// is doing a quarter of its job on average is still shortening the job.
	// Below it, a runner lent two cores that uses its guarantee and a sliver
	// is holding CPU a neighbour could use.
	LoanInUseShare = 0.25
	// LoanReclaimSamples is how many fresh samples in a row must show a loan
	// unused before it is withdrawn. One low sample is a link step or a test
	// waiting on a socket; three -- a minute and a half at the default sample
	// interval -- is a job that has settled below what it was given.
	LoanReclaimSamples = 3
	// LoanBackoff is how long a runner whose loan was withdrawn waits before
	// it may be lent again on ordinary demand. Without it, a runner that
	// saturates its guarantee but not a loan is demanding again on the very
	// next sample, and is lent, wastes it and loses it in a loop.
	LoanBackoff = 5 * time.Minute
	// LoanBackoffMax caps the backoff, which doubles each time a loan is
	// wasted again straight after one. A job whose demand really has changed
	// is never kept waiting longer than this.
	LoanBackoffMax = 30 * time.Minute
	// LoanSaturatedShare is the share of its current limit a runner must use
	// to count as pressing against it. Short of the whole limit, because a
	// cgroup at its quota still reads a little under it once the sample's
	// window is averaged.
	LoanSaturatedShare = 0.95
)

// LoanMemory is what the planner remembers about one runner's loan between
// heartbeats. The zero value is a runner nothing is known about.
type LoanMemory struct {
	// LastSampleAt is the sample the memory was last advanced by. A heartbeat
	// that carries the same sample again counts for nothing: the thresholds
	// are counted in samples, not heartbeats.
	LastSampleAt time.Time
	// LowSamples is how many fresh samples in a row showed the current loan
	// unused.
	LowSamples int
	// WastedAt is when a loan was last withdrawn as unused; zero when none
	// has been, or the backoff has been spent by a loan that was used.
	WastedAt time.Time
	// Strikes is how many loans in a row were withdrawn unused. It doubles the
	// backoff, and a loan that is used clears it.
	Strikes int
	// WastedPeakCPUs is the most CPU the runner used while it held the loan
	// that was withdrawn. It is what makes a saturated guarantee a new signal
	// or an old one: see DecideLoan.
	WastedPeakCPUs float64
	// PeakCPUs is the most CPU the runner has used under its current loan.
	PeakCPUs float64
}

// LoanInput is one runner at one heartbeat. Now is passed in rather than
// read, so the decision is a function of its input and can be tested one
// heartbeat at a time.
type LoanInput struct {
	Now time.Time
	// SampledAt is when UsedCPUs was measured; zero is no sample at all.
	SampledAt time.Time
	// BaseCPUs is the runner's guarantee and LimitCPUs the quota it holds
	// now: above BaseCPUs while it is lent CPU, equal to it otherwise.
	BaseCPUs  float64
	LimitCPUs float64
	UsedCPUs  float64
	// HolderBaseCPUs and HolderUsedCPUs are the guarantee and use of the
	// container the loan is actually given to, where that is not the whole
	// runner: a docker-in-docker pair's loan goes to its busier half alone,
	// so the pair's sum -- the idle half's share included -- would read a
	// daemon using two lent cores as a loan barely touched. Zero means the
	// runner is one container, and BaseCPUs and UsedCPUs are the holder's.
	HolderBaseCPUs float64
	HolderUsedCPUs float64
	// Saturated is a signal besides UsedCPUs that the runner is pressing
	// against its limit: the cgroup's throttling counters rose, or the busier
	// half of a docker-in-docker pair is at its own quota.
	Saturated bool
	// Demanding is the ordinary entry test: the runner is using most of its
	// guarantee or being throttled at it.
	Demanding bool
	Memory    LoanMemory
}

// LoanCode is a stable name for a loan decision, for metrics and tests.
type LoanCode string

const (
	LoanNotDemanding    LoanCode = "not_demanding"
	LoanLend            LoanCode = "lend"
	LoanInUse           LoanCode = "in_use"
	LoanWatching        LoanCode = "watching"
	LoanReclaimed       LoanCode = "reclaimed"
	LoanBackingOff      LoanCode = "backing_off"
	LoanBackoffOverride LoanCode = "backoff_overridden"
)

// LoanDecision says whether a runner may take part in this heartbeat's
// water-fill, and why, in words an operator reading a log can act on.
type LoanDecision struct {
	Lend   bool
	Code   LoanCode
	Reason string
	Memory LoanMemory
}

// Backoff is how long the runner waits after its latest wasted loan.
func (m LoanMemory) Backoff() time.Duration {
	d := LoanBackoff
	for i := 1; i < m.Strikes && d < LoanBackoffMax; i++ {
		d *= 2
	}
	return min(d, LoanBackoffMax)
}

// DecideLoan decides whether a runner should be lent CPU at this heartbeat.
//
// A runner that holds a loan keeps it while it uses at least a quarter of it;
// after LoanReclaimSamples fresh samples below that, the loan is withdrawn and
// the runner backs off. During the backoff it is lent again only when it
// presses against its guarantee and did not while it held the wasted loan --
// that is a job whose demand changed, not the same job asking again. A job
// that used a sliver more than its guarantee under the loan is expected to
// saturate its guarantee without it, and re-lending on that would be the
// flap this exists to stop.
func DecideLoan(in LoanInput) LoanDecision {
	m := in.Memory
	fresh := !in.SampledAt.IsZero() && in.SampledAt.After(m.LastSampleAt)
	if fresh {
		m.LastSampleAt = in.SampledAt
	}
	lent := in.LimitCPUs > in.BaseCPUs+cpuEpsilon
	loan := in.LimitCPUs - in.BaseCPUs

	if !m.WastedAt.IsZero() {
		since := in.Now.Sub(m.WastedAt)
		if since < m.Backoff() {
			// A sample can still show the loan for a heartbeat after it was
			// withdrawn, because the agent moves the quota only once it has
			// the plan. That is not the runner holding a loan, and judging it
			// as one would lend the CPU straight back.
			pressing := !lent && (in.UsedCPUs >= LoanSaturatedShare*in.LimitCPUs || in.Saturated)
			// The wasted loan's peak is what separates a new demand from the
			// old one: a job that stayed under its guarantee while it was lent
			// more, and now fills it, has started doing something else.
			if pressing && m.WastedPeakCPUs < LoanSaturatedShare*in.BaseCPUs {
				m.WastedAt, m.WastedPeakCPUs, m.LowSamples, m.PeakCPUs = time.Time{}, 0, 0, 0
				return LoanDecision{Lend: true, Code: LoanBackoffOverride, Memory: m, Reason: fmt.Sprintf(
					"lent again before its backoff ended: now at its %.2f CPU limit, where it used only %.2f while it last held a loan",
					in.LimitCPUs, in.Memory.WastedPeakCPUs)}
			}
			m.LowSamples, m.PeakCPUs = 0, 0
			return LoanDecision{Code: LoanBackingOff, Memory: m, Reason: fmt.Sprintf(
				"not lent: its last loan went unused, and it waits another %s before it is lent again",
				(m.Backoff() - since).Round(time.Second))}
		}
		if since >= m.Backoff()+LoanBackoffMax {
			// Long enough ago that the next waste is a new story, not a
			// repeat of the last one.
			m.WastedAt, m.WastedPeakCPUs, m.Strikes = time.Time{}, 0, 0
		}
	}

	if lent {
		if fresh {
			m.PeakCPUs = max(m.PeakCPUs, in.UsedCPUs)
		}
		holderBase, holderUsed := in.BaseCPUs, in.UsedCPUs
		if in.HolderBaseCPUs > 0 {
			holderBase, holderUsed = in.HolderBaseCPUs, in.HolderUsedCPUs
		}
		floor := holderBase + LoanInUseShare*loan
		if holderUsed >= floor {
			m.LowSamples, m.Strikes, m.WastedAt, m.WastedPeakCPUs = 0, 0, time.Time{}, 0
			return LoanDecision{Lend: true, Code: LoanInUse, Memory: m, Reason: fmt.Sprintf(
				"keeps its loan: using %.2f CPUs where the loan is, at least a quarter of the %.2f lent above a %.2f share",
				holderUsed, loan, holderBase)}
		}
		if fresh {
			m.LowSamples++
		}
		if m.LowSamples < LoanReclaimSamples {
			return LoanDecision{Lend: true, Code: LoanWatching, Memory: m, Reason: fmt.Sprintf(
				"keeps its loan for now: using %.2f CPUs where the loan is, under %.2f, for %d of %d samples before it is taken back",
				holderUsed, floor, m.LowSamples, LoanReclaimSamples)}
		}
		m.Strikes++
		m.WastedAt, m.WastedPeakCPUs = in.Now, m.PeakCPUs
		m.LowSamples, m.PeakCPUs = 0, 0
		return LoanDecision{Code: LoanReclaimed, Memory: m, Reason: fmt.Sprintf(
			"loan taken back: used at most %.2f CPUs of %.2f for %d samples in a row; not lent again for %s unless its demand changes",
			m.WastedPeakCPUs, in.LimitCPUs, LoanReclaimSamples, m.Backoff())}
	}

	m.LowSamples, m.PeakCPUs = 0, 0
	if in.Demanding {
		return LoanDecision{Lend: true, Code: LoanLend, Memory: m, Reason: fmt.Sprintf(
			"may be lent CPU: using %.2f CPUs of its %.2f guarantee, or throttled at it", in.UsedCPUs, in.BaseCPUs)}
	}
	return LoanDecision{Code: LoanNotDemanding, Memory: m, Reason: fmt.Sprintf(
		"not lent: using %.2f CPUs of its %.2f guarantee, short of what would count as demand", in.UsedCPUs, in.BaseCPUs)}
}

package scheduler

import (
	"strings"
	"testing"
	"time"
)

// beat is one heartbeat of one runner: what the agent measured and what quota
// the runner held when it did.
type beat struct {
	after     time.Duration // since the first heartbeat
	limit     float64
	used      float64
	saturated bool
	demanding bool
	stale     bool // the same sample as the previous heartbeat
	// holderBase and holderUsed are a docker-in-docker pair's busier half.
	holderBase, holderUsed float64
	want                   LoanCode
}

// Each case is a runner followed across heartbeats, because what this rule
// exists to get right -- reclaim once, back off, and do not flap -- only shows
// over a sequence. A guarantee of 2 CPUs throughout; a loan is a limit of 4.
func TestDecideLoanFollowsARunnerAcrossHeartbeats(t *testing.T) {
	const base = 2.0
	s := 30 * time.Second
	cases := []struct {
		name  string
		beats []beat
	}{
		{"a runner using its guarantee is lent", []beat{
			{after: 0, limit: 2, used: 1.9, demanding: true, want: LoanLend},
		}},
		// Codex review: the pair's sum counts the idle half's share as if it
		// were the loan's, and read a daemon using two lent cores as a loan
		// barely touched.
		{"a docker-in-docker daemon using its loan keeps it though the pair's sum is low", []beat{
			{after: 0, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: 2 * s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
			{after: 3 * s, limit: 4, used: 2.4, holderBase: 1, holderUsed: 2.3, want: LoanInUse},
		}},
		{"a docker-in-docker pair whose busier half ignores its loan loses it", []beat{
			{after: 0, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.6, holderBase: 1, holderUsed: 1.1, want: LoanReclaimed},
		}},
		{"a quiet runner is not lent", []beat{
			{after: 0, limit: 2, used: 0.4, want: LoanNotDemanding},
		}},
		{"a runner using a quarter of its loan holds it", []beat{
			{after: 0, limit: 4, used: 2.5, want: LoanInUse},
			{after: s, limit: 4, used: 3.9, want: LoanInUse},
		}},
		{"an unused loan is watched, then reclaimed after three samples", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.2, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.0, want: LoanReclaimed},
		}},
		{"one busy sample resets the count", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 3.5, want: LoanInUse},
			{after: 3 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 5 * s, limit: 4, used: 2.1, want: LoanReclaimed},
		}},
		{"a heartbeat repeating a sample does not count towards a reclaim", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, stale: true, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, stale: true, want: LoanWatching},
			{after: 3 * s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4 * s, limit: 4, used: 2.1, want: LoanReclaimed},
		}},
		{"a reclaimed runner saturating its guarantee is not lent again straight away", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			// The agent has not moved the quota yet: still no loan.
			{after: 3 * s, limit: 4, used: 2.1, demanding: true, want: LoanBackingOff},
			{after: 4 * s, limit: 2, used: 2.0, demanding: true, saturated: true, want: LoanBackingOff},
			{after: 4*s + 3*time.Minute, limit: 2, used: 2.0, demanding: true, saturated: true, want: LoanBackingOff},
		}},
		{"after the backoff a demanding runner is lent again", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 2*s + LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanLend},
		}},
		{"a second wasted loan doubles the backoff", []beat{
			{after: 0, limit: 4, used: 2.1, want: LoanWatching},
			{after: s, limit: 4, used: 2.1, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 2*s + LoanBackoff, limit: 4, used: 2.1, want: LoanWatching},
			{after: 3*s + LoanBackoff, limit: 4, used: 2.1, want: LoanWatching},
			{after: 4*s + LoanBackoff, limit: 4, used: 2.1, want: LoanReclaimed},
			{after: 4*s + 2*LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanBackingOff},
			{after: 4*s + 3*LoanBackoff, limit: 2, used: 2.0, demanding: true, want: LoanLend},
		}},
		{"a runner that was quiet under its loan and now fills its guarantee is lent inside the backoff", []beat{
			{after: 0, limit: 4, used: 0.5, want: LoanWatching},
			{after: s, limit: 4, used: 0.6, want: LoanWatching},
			{after: 2 * s, limit: 4, used: 0.5, want: LoanReclaimed},
			{after: 3 * s, limit: 2, used: 0.5, want: LoanBackingOff},
			{after: 4 * s, limit: 2, used: 1.98, demanding: true, want: LoanBackoffOverride},
			{after: 5 * s, limit: 4, used: 3.8, want: LoanInUse},
		}},
	}
	start := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var m LoanMemory
			sampled := time.Time{}
			for i, b := range tc.beats {
				now := start.Add(b.after)
				if !b.stale {
					sampled = now.Add(-time.Second)
				}
				d := DecideLoan(LoanInput{
					Now: now, SampledAt: sampled, BaseCPUs: base, LimitCPUs: b.limit, UsedCPUs: b.used,
					HolderBaseCPUs: b.holderBase, HolderUsedCPUs: b.holderUsed,
					Saturated: b.saturated, Demanding: b.demanding, Memory: m,
				})
				if d.Code != b.want {
					t.Fatalf("heartbeat %d: %s (%q), want %s", i, d.Code, d.Reason, b.want)
				}
				if d.Lend != (b.want == LoanLend || b.want == LoanInUse || b.want == LoanWatching || b.want == LoanBackoffOverride) {
					t.Fatalf("heartbeat %d: lend = %v for %s", i, d.Lend, d.Code)
				}
				if strings.TrimSpace(d.Reason) == "" {
					t.Fatalf("heartbeat %d: %s has no reason an operator can read", i, d.Code)
				}
				m = d.Memory
			}
		})
	}
}

// The flap this rule exists to stop: a job that sized its workers to a little
// over its guarantee is demanding at the guarantee, wastes any loan, and was
// lent, reclaimed and lent again every few heartbeats. Across an hour it may
// change its quota only a handful of times.
func TestDecideLoanDoesNotFlapOnAJobThatUsesALittleMoreThanItsGuarantee(t *testing.T) {
	const base = 2.0
	start := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	var m LoanMemory
	limit, changes := base, 0
	for i := range 120 {
		now := start.Add(time.Duration(i) * 30 * time.Second)
		used := min(limit, 2.2)
		d := DecideLoan(LoanInput{
			Now: now, SampledAt: now, BaseCPUs: base, LimitCPUs: limit, UsedCPUs: used,
			Saturated: used >= limit*LoanSaturatedShare, Demanding: used >= 0.8*base, Memory: m,
		})
		m = d.Memory
		next := base
		if d.Lend {
			next = 4
		}
		if next != limit {
			changes++
		}
		limit = next
	}
	// Lent and reclaimed at 0, 5, 15 and 35 minutes, then held off for the
	// capped half hour: under a dozen changes, where a rule without memory
	// makes one every few heartbeats.
	if changes > 12 {
		t.Fatalf("the quota changed %d times in an hour, want a handful", changes)
	}
}

func TestLoanBackoffIsCapped(t *testing.T) {
	if got := (LoanMemory{Strikes: 20}).Backoff(); got != LoanBackoffMax {
		t.Fatalf("backoff after twenty strikes = %s, want the cap %s", got, LoanBackoffMax)
	}
	if got := (LoanMemory{Strikes: 1}).Backoff(); got != LoanBackoff {
		t.Fatalf("backoff after one strike = %s, want %s", got, LoanBackoff)
	}
}

package scheduler

import (
	"math"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// HostAdmissionReason is empty when measured pressure permits new runners.
// Connectivity, configured capacity and manual cordons remain separate facts.
func HostAdmissionReason(h *store.Host, now time.Time) string {
	if !h.Usage.Fresh(now) {
		return ""
	}
	if h.Usage.CPUHeld {
		return "new starts held after sustained CPU pressure; they resume when CPU usage falls below 85%"
	}
	if v := h.Usage.MemoryAvailableMB; v != nil && *v <= h.MemoryReserve() {
		return "new starts held because available memory is at or below the host reserve"
	}
	return ""
}

func hostUnderCPUPressure(h *store.Host, now time.Time) bool {
	// Lent CPU in use is load the elastic plan chose, and the next plan
	// takes it back for a start, so it is not pressure.
	v := h.Usage.UnlentCPUPercent()
	return h.Usage.Fresh(now) && v != nil && *v >= 85
}

func (hs *hostSet) pending(h *store.Host, pools []*store.Pool, runners map[string][]*store.Runner) Reservation {
	var out Reservation
	for _, p := range pools {
		if p == nil {
			continue
		}
		for _, r := range runners[p.ID] {
			if r == nil || r.HostID != h.ID || !r.State.Live() {
				continue
			}
			starting := r.State == store.RunnerProvisioning || r.State == store.RunnerRegistering
			if starting {
				hs.warming[h.ID]++
			}
			if starting || r.CreatedAt.After(h.Usage.SampledAt) ||
				(r.ContainerStartedAt != nil && r.ContainerStartedAt.After(h.Usage.SampledAt)) {
				res := RunnerCharge(p, h, r)
				out.CPUs += res.CPUs
				out.MemoryMB += res.MemoryMB
			}
		}
	}
	return out
}

func (hs *hostSet) score(h *store.Host, p *store.Pool) float64 {
	if h.Capacity <= 0 {
		return -1
	}
	want, left, alloc := Reserve(p, h), hs.left[h.ID], hs.alloc[h.ID]
	score, dimensions := 0.0, 0.0
	if alloc.CPUsKnown && alloc.CPUs > 0 {
		cpu := left.CPUs
		if measured, ok := hs.observedCPU[h.ID]; ok {
			cpu = min(cpu, measured)
		}
		score += max(cpu-want.CPUs, 0) / alloc.CPUs
		dimensions++
	}
	if alloc.MemoryKnown && alloc.MemoryMB > 0 {
		score += float64(max(left.MemoryMB-want.MemoryMB, 0)) / float64(alloc.MemoryMB)
		dimensions++
	}
	if dimensions > 0 {
		return score / dimensions
	}
	// Preserve the old greatest-free-slots choice when there are no resource
	// specifications. Missing telemetry must not make an existing fleet stop.
	return float64(hs.free[h.ID]-1) / float64(h.Capacity)
}

func (hs *hostSet) prefer(h, best *store.Host, p *store.Pool) bool {
	if hs.preferReadiness {
		a, b := hs.readyDelay(h, p), hs.readyDelay(best, p)
		// A small timing difference is noise; headroom breaks near ties.
		if a+5*time.Second < b {
			return true
		}
		if b+5*time.Second < a {
			return false
		}
	}
	a, b := hs.alloc[h.ID], hs.alloc[best.ID]
	if !a.CPUsKnown && !a.MemoryKnown && !b.CPUsKnown && !b.MemoryKnown {
		return hs.free[h.ID] > hs.free[best.ID]
	}
	score, bestScore := hs.score(h, p), hs.score(best, p)
	return score > bestScore+cpuEpsilon ||
		(math.Abs(score-bestScore) <= cpuEpsilon && hs.free[h.ID] > hs.free[best.ID])
}

// A serial admission queue costs one estimated service interval per start.
// Unknown hosts use a bounded prior and remain eligible; metrics never relax fit.
func (hs *hostSet) readyDelay(h *store.Host, p *store.Pool) time.Duration {
	d := hs.readiness[p.ID][h.ID]
	if d <= 0 {
		d = time.Minute
	}
	d = min(max(d, 5*time.Second), 10*time.Minute)
	return time.Duration(hs.warming[h.ID]+1) * d
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func withUsage(h *store.Host, cpu float64, memoryMB int64) *store.Host {
	h.Usage = store.HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &memoryMB, SampledAt: now}
	return h
}

func TestPlacementUsesHostSizeAndMeasuredHeadroomInsteadOfFreeSlots(t *testing.T) {
	p := limited("build", 2, 2048)
	for _, tc := range []struct {
		name string
		a, b *store.Host
		want string
	}{
		{"larger machine", sized("a", 4, 4, 8192, 100000), sized("b", 4, 16, 32768, 100000), "b"},
		{"busy machine has more slots", withUsage(sized("a", 10, 16, 32768, 100000), 90, 28000), withUsage(sized("b", 4, 16, 32768, 100000), 20, 28000), "b"},
		{"outside work consumes memory", withUsage(sized("a", 10, 16, 32768, 100000), 10, 1024), withUsage(sized("b", 4, 8, 16384, 100000), 40, 12000), "b"},
		{"equal measurements break ties by ID", withUsage(sized("a", 4, 8, 16384, 100000), 20, 12000), withUsage(sized("b", 4, 8, 16384, 100000), 20, 12000), "a"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			hs := newHostSet([]*store.Host{tc.b, tc.a}, []*store.Pool{p}, nil, now)
			if got := hs.place(p, 1); len(got) != 1 || got[0] != tc.want {
				t.Fatalf("placed on %v, want %s", got, tc.want)
			}
		})
	}
}

// placeAvoiding is a preference, not a refusal: a host named in avoid is
// skipped in favour of any other eligible host, but is still used once it is
// the only one left, because a host that failed a create a few minutes ago is
// still better than no host at all.
func TestPlaceAvoidingPrefersAnyOtherEligibleHost(t *testing.T) {
	a := sized("a", 4, 16, 32768, 100000)
	b := sized("b", 4, 16, 32768, 100000)
	p := limited("build", 2, 2048)

	hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, map[string]bool{"a": true}); len(got) != 1 || got[0].hostID != "b" {
		t.Fatalf("placed on %v, want the host not in avoid", got)
	}

	hs = newHostSet([]*store.Host{a}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, map[string]bool{"a": true}); len(got) != 1 || got[0].hostID != "a" {
		t.Fatalf("placed on %v, want the only host even though it is avoided", got)
	}
}

func TestPlacementRebalancesEachNewReservationAcrossPools(t *testing.T) {
	a := withUsage(sized("a", 8, 16, 32768, 100000), 10, 30000)
	b := withUsage(sized("b", 8, 16, 32768, 100000), 10, 30000)
	p, q := limited("one", 4, 4096), limited("two", 4, 4096)
	hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p, q}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 || got[0] != "a" {
		t.Fatal(got)
	}
	if got := hs.place(q, 1); len(got) != 1 || got[0] != "b" {
		t.Fatalf("second pool ignored first reservation: %v", got)
	}
}

func TestPendingStartsAreChargedBetweenPassesWithoutChargingBusyMemoryTwice(t *testing.T) {
	p := limited("build", 1, 4096)
	for _, state := range []store.RunnerState{store.RunnerProvisioning, store.RunnerRegistering, store.RunnerBusy} {
		t.Run(string(state), func(t *testing.T) {
			h := withUsage(sized("host_a", 4, 8, 16384, 100000), 20, 6656)
			h.ActiveRunners = 1
			r := testRunner("existing", p, state, time.Minute)
			hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
			got := hs.place(p, 1)
			if state == store.RunnerBusy && len(got) != 1 {
				t.Fatal("busy memory was subtracted twice")
			}
			if state != store.RunnerBusy && len(got) != 0 {
				t.Fatal("another pass reused memory promised to a pending start")
			}
		})
	}
}

func TestPressureHoldsNewWorkButLeavesBusyRunnersAndManualLimitsAlone(t *testing.T) {
	p := limited("build", 1, 1024)
	h := withUsage(sized("host_a", 4, 8, 16384, 100000), 99, 12000)
	h.Usage.CPUHeld = true
	h.ActiveRunners = 1
	r := testRunner("busy", p, store.RunnerBusy, time.Minute)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 2); len(got) != 0 {
		t.Fatalf("held host got %v", got)
	}
	if !strings.Contains(hs.why(p).what, "pressure") {
		t.Fatal("hold had no useful reason")
	}
	if r.State != store.RunnerBusy || h.Capacity != 4 || h.Cordoned {
		t.Fatal("pressure changed existing work or operator settings")
	}
	h.Usage.CPUHeld = false
	*h.Usage.CPUPercent = 30
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatal("recovery did not allow new work")
	}
	h.Cordoned = true
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("recovery undid manual cordon")
	}
}

func TestBusyCPUAllowsOnlyOneStartUntilItRegisters(t *testing.T) {
	p := limited("build", 1, 1024)
	h := withUsage(sized("host_a", 8, 16, 32768, 100000), 90, 28000)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 4); len(got) != 1 {
		t.Fatalf("got %d simultaneous starts under pressure", len(got))
	}
	r := testRunner("pending", p, store.RunnerProvisioning, time.Second)
	hs = newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("next pass ignored pending startup")
	}
}

func TestStaleAndMissingUsageRetainReservationGuards(t *testing.T) {
	p := limited("build", 2, 4096)
	h := withUsage(sized("host_a", 8, 8, 16384, 100000), 99, 0)
	h.Usage.CPUHeld = true
	h.Usage.SampledAt = now.Add(-store.HostUsageMaxAge)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 8); len(got) != 3 {
		t.Fatalf("stale reading blocked work or erased reservations: %v", got)
	}
	h.Usage.SampledAt = now
	hs = newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatal("fresh zero memory was treated as missing")
	}
	old := newHostSet([]*store.Host{testHost("a", 2, 0), testHost("b", 5, 1)}, []*store.Pool{p}, nil, now)
	if got := old.place(p, 1); len(got) != 1 || got[0] != "b" {
		t.Fatalf("old agent no longer placed by slots: %v", got)
	}
}

// The reserve is held back inside Allocatable, and a pool that leaves its size
// to the host asks for a share of that same figure. Taking the reserve off the
// measured sample as well made measured headroom permanently one reserve
// tighter than the share, so a host cut into a single slot could never fit the
// runner it was sized for: it reported "short of memory" at every pass, on an
// idle machine with tens of gigabytes free, and its slot was never used.
func TestASingleSlotHostFitsTheRunnerItsOwnSizeAsksFor(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 1, 8, 31*1024, 100000)
	withUsage(h, 10, h.Allocatable().MemoryMB)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatalf("placed on %v, want the idle host's only slot", got)
	}
}

// An idle host that is using more for its own operating system than the reserve
// guessed -- Docker, containerd and a VPN on a 31 GB machine is enough -- has
// less measured free memory than its allocatable figure. A pool that leaves its
// size to the host asks for a share of allocatable, and on a host of one slot
// that share is the whole of it, so comparing the share with what was measured
// free refused the slot at every pass, on a machine running nothing. The Hosts
// page, which counts from allocatable, said the slot was free all along.
//
// This is the case the test above does not cover: there, measured free memory
// was set exactly equal to allocatable, the one value at which it worked.
func TestAnIdleHostTakesAHostSizedRunnerWhenItsOperatingSystemUsesMoreThanTheReserve(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 1, 4, 31*1024, 100000)
	// Three gigabytes in use by the machine itself, against a reserve of
	// about one and a half.
	withUsage(h, 5, h.MemoryMB-3*1024)
	if avail, alloc := *h.Usage.MemoryAvailableMB, h.Allocatable().MemoryMB; avail >= alloc {
		t.Fatalf("the fixture does not reproduce the fault: %d MB available is not below %d MB allocatable", avail, alloc)
	}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 1 {
		t.Fatalf("placed on %v, want the idle host's only slot", got)
	}
}

// What the measured check is for still holds once the host runs work of ours:
// a second host-sized runner is refused when what is measured free cannot
// carry it, because the runners already there are using that memory.
func TestAHostAlreadyRunningOurWorkStillMeasuresBeforeTakingMore(t *testing.T) {
	p := testPool("build", "build")
	h := sized("host_a", 2, 8, 32*1024, 100000)
	h.ActiveRunners = 1
	r := testRunner("existing", p, store.RunnerBusy, time.Minute)
	r.HostID = h.ID
	// The busy runner is using most of the machine.
	withUsage(h, 40, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, map[string][]*store.Runner{p.ID: {r}}, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatalf("placed on %v; a host whose runner is using its memory must not be handed another share it has not got", got)
	}
}

// A pool that states its size is asking for that much, so an idle host must
// have it free: the leniency is for a share the host chose, not for a figure
// an operator wrote down.
func TestAnIdleHostStillRefusesAStatedSizeItHasNotGotFree(t *testing.T) {
	p := limited("build", 2, 8192)
	h := sized("host_a", 1, 4, 16*1024, 100000)
	withUsage(h, 5, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 1); len(got) != 0 {
		t.Fatalf("placed on %v; an 8 GB runner does not fit in 6 GB free, whatever the host is otherwise doing", got)
	}
}

package scheduler

import (
	"fmt"
	"math"
	"slices"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// The modes of scheduler.history_sizing.
const (
	// HistoryOff places runners on the pool's size and the host's room alone,
	// as the fleet always did.
	HistoryOff = "off"
	// HistoryShadow works out what the jobs waiting are known to need and
	// says where it would have placed differently, without doing so. It is
	// the default for the reason placement_mode's shadow is: an operator sees
	// what the policy would do on their own fleet before it does it.
	HistoryShadow = "shadow"
	// HistoryOn places and sizes the runner for the largest known need among
	// the jobs waiting on its pool.
	HistoryOn = "on"
)

const (
	// ProfilePercentile is the share of a job's recent runs its requirement
	// covers. The ninetieth, not the peak of peaks: one run that pulled a
	// cold cache should not size every run after it, and one that did less
	// than usual should not shrink them.
	ProfilePercentile = 0.9
	// ProfileMemoryMargin is added on top of that percentile for memory. A
	// job that used 5 GB on its heaviest ordinary run is killed at exactly 5
	// GB the next time its test data grows, so it is given a fifth more.
	//
	// CPU gets no margin on purpose. A build uses every core it is given, so
	// its peak is its limit; a margin on it would ask for a fifth more CPU
	// every run and ratchet the requirement up to the largest host. Memory
	// does not ratchet the same way: a job does not use memory because it is
	// there.
	ProfileMemoryMargin = 1.2
	// ProfileOOMGrowth is how much more than its peak a run the kernel killed
	// for memory is taken to have needed. Its peak is the limit it hit, which
	// is by definition not enough; half as much again is a guess, but a
	// guess that moves the next run off a host that has already failed it.
	ProfileOOMGrowth = 1.5
	// profileMemoryStep rounds a memory requirement up, so the figure in a
	// reason reads as a size rather than a measurement.
	profileMemoryStep = 64
)

// Requirement is what one queued job is expected to need, from the runs of it
// the fleet has measured. The zero value is "nothing known", which constrains
// nothing: a job with no history is placed exactly as it was before history
// sizing existed.
type Requirement struct {
	CPUs     float64 `json:"cpus,omitempty"`
	MemoryMB int64   `json:"memory_mb,omitempty"`
	// Samples is how many measured runs it was taken from, and OOMKilled how
	// many of them the kernel killed for memory.
	Samples   int `json:"samples,omitempty"`
	OOMKilled int `json:"oom_killed,omitempty"`
}

// Known reports whether the requirement says anything at all.
func (r Requirement) Known() bool { return r.CPUs > 0 || r.MemoryMB > 0 }

// String says the requirement the way a reason does: "~6 GB and 4 CPU".
func (r Requirement) String() string {
	parts := []string{}
	if r.MemoryMB > 0 {
		parts = append(parts, "~"+formatMB(r.MemoryMB))
	}
	if r.CPUs > 0 {
		parts = append(parts, "~"+formatCPUs(r.CPUs)+" CPU")
	}
	return strings.Join(parts, " and ")
}

// Profile turns a job's recent measured runs into its requirement: the
// ninetieth percentile of their peaks, with a margin on memory, and a run the
// kernel killed for memory counted as having needed more than it had.
func Profile(peaks []store.JobPeak) Requirement {
	var cpus []float64
	var mem []int64
	out := Requirement{}
	for _, p := range peaks {
		out.Samples++
		if p.OOMKilled {
			out.OOMKilled++
		}
		if p.CPUs > 0 {
			cpus = append(cpus, p.CPUs)
		}
		if p.MemoryMB > 0 {
			m := p.MemoryMB
			if p.OOMKilled {
				m = int64(math.Ceil(float64(m) * ProfileOOMGrowth))
			}
			mem = append(mem, m)
		}
	}
	if len(cpus) > 0 {
		slices.Sort(cpus)
		out.CPUs = math.Ceil(cpus[percentileIndex(len(cpus))]*100) / 100
	}
	if len(mem) > 0 {
		slices.Sort(mem)
		m := math.Ceil(float64(mem[percentileIndex(len(mem))]) * ProfileMemoryMargin)
		out.MemoryMB = int64(math.Ceil(m/profileMemoryStep)) * profileMemoryStep
	}
	return out
}

// percentileIndex is the nearest-rank position of ProfilePercentile in n
// sorted samples.
func percentileIndex(n int) int {
	i := int(math.Ceil(ProfilePercentile*float64(n))) - 1
	return clamp(i, 0, n-1)
}

// requirementFor is one queued job's requirement on p: its profile, never
// below the pool's minimum where it says anything at all.
func (t *tick) requirementFor(p *store.Pool, j *store.Job) Requirement {
	r := Profile(t.history[store.JobUsageKey{Repo: j.Repo, Workflow: j.Workflow, JobName: j.JobName, PoolID: p.ID}])
	if !r.Known() {
		return Requirement{}
	}
	if r.CPUs > 0 {
		r.CPUs = max(r.CPUs, p.Resources.MinCPUs)
	}
	if r.MemoryMB > 0 {
		r.MemoryMB = max(r.MemoryMB, p.Resources.MinMemoryMB)
	}
	return r
}

// poolNeed is the requirement a runner created for p's queue is placed for.
//
// GitHub, not Zoomies, decides which of the jobs waiting an idle runner takes,
// so a runner created for this queue may be handed any of them. It is placed
// for the largest of them: the heavy job the runner might be given is the one
// a small host kills.
//
// A job no host that could run this pool has the allocatable room for is left
// out, and said so in the second value: holding every runner back for it
// would keep the light jobs beside it waiting for ever, and a larger host is
// the only thing that helps it.
func (t *tick) poolNeed(p *store.Pool, queued []*store.Job) (Requirement, string) {
	var fitting []Requirement
	var unfit Requirement
	for _, j := range queued {
		r := t.requirementFor(p, j)
		if !r.Known() {
			continue
		}
		if t.hosts.anyCouldHold(p, r) {
			fitting = append(fitting, r)
			continue
		}
		if r.MemoryMB > unfit.MemoryMB || (r.MemoryMB == unfit.MemoryMB && r.CPUs > unfit.CPUs) {
			unfit = r
		}
	}
	note := ""
	if unfit.Known() {
		note = fmt.Sprintf("jobs waiting on pool %s are known to need %s, and no host that can run the pool has that much to give", p.Name, unfit)
	}
	if len(fitting) == 0 {
		return Requirement{}, note
	}
	need := Requirement{}
	for _, r := range fitting {
		need.CPUs, need.MemoryMB = max(need.CPUs, r.CPUs), max(need.MemoryMB, r.MemoryMB)
		need.Samples += r.Samples
		need.OOMKilled += r.OOMKilled
	}
	if t.hosts.anyCouldHold(p, need) {
		return need, note
	}
	// The heaviest by memory and the heaviest by CPU are different jobs, and
	// no one host has both. The one that is killed for want of it is memory.
	slices.SortFunc(fitting, func(a, b Requirement) int {
		if a.MemoryMB != b.MemoryMB {
			return int(b.MemoryMB - a.MemoryMB)
		}
		switch {
		case a.CPUs > b.CPUs:
			return -1
		case a.CPUs < b.CPUs:
			return 1
		}
		return 0
	})
	return fitting[0], note
}

// anyCouldHold reports whether any host that could run p has the allocatable
// room for r at all, busy or not.
func (hs *hostSet) anyCouldHold(p *store.Pool, r Requirement) bool {
	for _, h := range hs.hosts {
		if !HostCouldRun(h, p) {
			continue
		}
		a := hs.alloc[h.ID]
		if a.CPUsKnown && a.CPUs+cpuEpsilon < r.CPUs {
			continue
		}
		if a.MemoryKnown && a.MemoryMB < r.MemoryMB {
			continue
		}
		return true
	}
	return false
}

// shortOf says what h cannot give a runner of p that needs r, or "" when it
// can. Memory is asked first: it is what a job is killed for.
func (hs *hostSet) shortOf(h *store.Host, p *store.Pool, r Requirement) string {
	left, a := hs.leftFor(h, p), hs.alloc[h.ID]
	if a.MemoryKnown && r.MemoryMB > 0 && left.MemoryMB < r.MemoryMB {
		return fmt.Sprintf("held off %s: jobs waiting need ~%s, it has %s", hostName(h), formatMB(r.MemoryMB), formatMB(max(left.MemoryMB, 0)))
	}
	if a.CPUsKnown && r.CPUs > 0 && left.CPUs+cpuEpsilon < r.CPUs {
		return fmt.Sprintf("held off %s: jobs waiting need ~%s CPU, it has %s", hostName(h), formatCPUs(r.CPUs), formatCPUs(max(left.CPUs, 0)))
	}
	return ""
}

// heldOff is every host that would take a runner of p now but is short of r,
// with the sentence saying by how much, in host order.
func (hs *hostSet) heldOff(p *store.Pool, r Requirement) map[string]string {
	out := map[string]string{}
	for _, h := range hs.hosts {
		if !hs.eligibleAsSized(h, p) {
			continue
		}
		if s := hs.shortOf(h, p, r); s != "" {
			out[h.ID] = s
		}
	}
	return out
}

// sortedPhrases joins the held-off sentences in host order.
func (hs *hostSet) sortedPhrases(m map[string]string) string {
	var out []string
	for _, h := range hs.hosts {
		if s, ok := m[h.ID]; ok {
			out = append(out, s)
		}
	}
	return strings.Join(out, "; ")
}

// sizeForNeed raises the charge of a runner placed for a known need, on each
// field the pool leaves to the host, and returns the size to create it at, or
// the size it already had when nothing moved. A field the pool states is left
// alone: the operator wrote that limit, and a runner is never given more than
// it -- the need then only decides the host.
func sizeForNeed(p *store.Pool, res Reservation, size *store.Resources, need Requirement) (Reservation, *store.Resources) {
	raised := false
	if p.Resources.CPUs <= 0 && need.CPUs > res.CPUs+cpuEpsilon {
		res.CPUs, raised = need.CPUs, true
	}
	if p.Resources.MemoryMB <= 0 && need.MemoryMB > res.MemoryMB {
		res.MemoryMB, raised = need.MemoryMB, true
	}
	if !raised {
		return res, size
	}
	grant := p.Resources
	grant.MinCPUs, grant.MinMemoryMB = 0, 0
	grant.CPUs = res.CPUs / fieldFactor(p, p.Resources.CPUs > 0)
	grant.MemoryMB = res.MemoryMB / int64(fieldFactor(p, p.Resources.MemoryMB > 0))
	return res, &grant
}

func hostName(h *store.Host) string {
	if h.Name != "" {
		return h.Name
	}
	return h.ID
}

package scheduler

import (
	"reflect"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestProfileIsTheNinetiethPercentileOfRecentPeaksWithAMarginOnMemory(t *testing.T) {
	ten := func(mb int64) []store.JobPeak {
		var out []store.JobPeak
		for i := range 10 {
			out = append(out, store.JobPeak{CPUs: float64(i + 1), MemoryMB: mb + int64(i)*100})
		}
		return out
	}
	for _, tc := range []struct {
		name  string
		peaks []store.JobPeak
		want  Requirement
	}{
		{"no runs say nothing", nil, Requirement{}},
		{
			// One run is its own percentile. 2000 MB with a fifth more is
			// 2400, rounded up to the next 64 MB.
			"one run", []store.JobPeak{{CPUs: 1.5, MemoryMB: 2000}},
			Requirement{CPUs: 1.5, MemoryMB: 2432, Samples: 1},
		},
		{
			// Of ten runs the ninth is the ninetieth percentile: the one
			// heaviest run does not size every run after it. 1800 MB with a
			// fifth more is 2160, rounded up to 2176.
			"ten runs", ten(1000),
			Requirement{CPUs: 9, MemoryMB: 2176, Samples: 10},
		},
		{
			// A killed run's peak is the limit it hit, so it counts as having
			// needed half as much again: 3000 * 1.5 * 1.2 = 5400, to 5440.
			"a run killed for memory", []store.JobPeak{{CPUs: 2, MemoryMB: 3000, OOMKilled: true}},
			Requirement{CPUs: 2, MemoryMB: 5440, Samples: 1, OOMKilled: 1},
		},
		{
			// CPU gets no margin: a build uses what it is given, and a margin
			// would ratchet it up on every run.
			"cpu only", []store.JobPeak{{CPUs: 4}},
			Requirement{CPUs: 4, Samples: 1},
		},
		{
			"a kill with no sample is counted and constrains nothing", []store.JobPeak{{OOMKilled: true}},
			Requirement{Samples: 1, OOMKilled: 1},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := Profile(tc.peaks); got != tc.want {
				t.Fatalf("Profile = %+v, want %+v", got, tc.want)
			}
		})
	}
}

// historyFleet is the shape of the failure this exists for: an automatic pool
// with a 1 CPU / 1 GB minimum, a small host that the plain policy picks for
// the next runner, and a larger one with room left. The small host sorts
// first so a tie in headroom goes to it, as it did on the day.
func historyFleet(t *testing.T, mode string, peakMB int64) (Snapshot, *store.Pool) {
	t.Helper()
	p := testPool("linux", "self-hosted")
	p.Resources = store.Resources{MinCPUs: 1, MinMemoryMB: 1024}
	small := sized("a-small", 1, 4, hostFor(3072), 100000)
	big := sized("b-big", 2, 16, hostFor(16384), 100000)
	busy := testRunner("r_busy", p, store.RunnerBusy, 0)
	busy.HostID = "b-big"
	big.ActiveRunners = 1
	job := queued("go-controller", 0, "self-hosted")
	job.Workflow = "CI"
	s := snap([]*store.Pool{p}, []*store.Runner{busy}, []*store.Job{job}, []*store.Host{small, big})
	s.HistorySizing = mode
	if peakMB > 0 {
		key := store.JobUsageKey{Repo: job.Repo, Workflow: job.Workflow, JobName: job.JobName, PoolID: p.ID}
		s.JobHistory = map[store.JobUsageKey][]store.JobPeak{key: {{CPUs: 2, MemoryMB: peakMB}, {CPUs: 2, MemoryMB: peakMB}}}
	}
	return s, p
}

func TestHistorySizingPlacesAHeavyJobAwayFromTheSmallHost(t *testing.T) {
	for _, tc := range []struct {
		name        string
		mode        string
		peakMB      int64
		wantHost    string
		wantHistory string
	}{
		// Without history, and with history off, the fleet places exactly as
		// it always did -- which is on the small host.
		{"no history places as before", HistoryOn, 0, "a-small", ""},
		{"history off places as before", HistoryOff, 5000, "a-small", ""},
		// Shadow works the answer out and changes nothing.
		{"shadow records and changes nothing", HistoryShadow, 5000, "a-small",
			"shadow: history sizing would have held off a-small: jobs waiting need ~5.9 GB, it has 3 GB"},
		{"on holds the small host off", HistoryOn, 5000, "b-big",
			"placed for the jobs waiting, which need ~5.9 GB and ~2 CPU; held off a-small: jobs waiting need ~5.9 GB, it has 3 GB"},
		// A light job fits both, so nothing is held off.
		{"a light job goes where it always went", HistoryOn, 500, "a-small", "placed for the jobs waiting, which need ~1 GB and ~2 CPU"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s, _ := historyFleet(t, tc.mode, tc.peakMB)
			pp := only(t, Decide(s))
			creates := actionsOf(pp.Actions, ActionCreate)
			if len(creates) != 1 {
				t.Fatalf("creates = %d (%s), want 1", len(creates), pp.Reason)
			}
			if creates[0].HostID != tc.wantHost {
				t.Fatalf("HostID = %q, want %q (%s)", creates[0].HostID, tc.wantHost, pp.Reason)
			}
			if pp.History != tc.wantHistory {
				t.Fatalf("History = %q, want %q", pp.History, tc.wantHistory)
			}
			if tc.mode == HistoryOn && tc.wantHistory != "" && !strings.Contains(creates[0].Reason, tc.wantHistory) {
				t.Fatalf("the create's reason %q does not say what history did", creates[0].Reason)
			}
		})
	}
}

// Shadow is meant to be safe to leave on: the plan it produces has to be the
// plan off produces, action for action, or it is not a shadow.
func TestShadowHistorySizingChangesNoAction(t *testing.T) {
	off, _ := historyFleet(t, HistoryOff, 5000)
	shadow, _ := historyFleet(t, HistoryShadow, 5000)
	if a, b := Decide(off).Actions, Decide(shadow).Actions; !reflect.DeepEqual(a, b) {
		t.Fatalf("shadow changed the plan:\noff    %+v\nshadow %+v", a, b)
	}
}

// A host whose runner share is smaller than the job's known need is given a
// runner sized to it, where the pool leaves its size to the host. Without it
// the heavy job is placed on a big host and still killed at a slot's share.
func TestHistorySizingRaisesAnAutomaticRunnerToTheKnownNeed(t *testing.T) {
	p := testPool("linux", "self-hosted")
	h := sized("big", 4, 16, hostFor(16384), 100000)
	job := queued("go-controller", 0, "self-hosted")
	s := snap([]*store.Pool{p}, nil, []*store.Job{job}, []*store.Host{h})
	s.HistorySizing = HistoryOn
	s.JobHistory = map[store.JobUsageKey][]store.JobPeak{
		{Repo: job.Repo, JobName: job.JobName, PoolID: p.ID}: {{CPUs: 3, MemoryMB: 5000}},
	}
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].Size == nil || !creates[0].SizedFromHistory {
		t.Fatalf("creates = %+v, want one sized from history", creates)
	}
	if got, share := creates[0].Size, Reserve(p, h); got.MemoryMB != 6016 || got.CPUs != share.CPUs {
		// A quarter of the host's CPU is already above the 3 CPU need, so it
		// stays the share; memory's share is 4 GB, below the 6016 MB need,
		// so memory alone is raised.
		t.Fatalf("Size = %+v, want 6016 MB and the host's %s CPU share", got, formatCPUs(share.CPUs))
	}
	if !strings.Contains(creates[0].Reason, "sized to") {
		t.Fatalf("reason %q does not say the runner was sized up", creates[0].Reason)
	}

	// A pool that states its size is never given more than it: the need then
	// chooses the host and nothing else.
	fixed := limited("fixed", 2, 2048)
	fixed.Labels = p.Labels
	s = snap([]*store.Pool{fixed}, nil, []*store.Job{job}, []*store.Host{h})
	s.HistorySizing = HistoryOn
	s.JobHistory = map[store.JobUsageKey][]store.JobPeak{
		{Repo: job.Repo, JobName: job.JobName, PoolID: fixed.ID}: {{CPUs: 3, MemoryMB: 5000}},
	}
	pp = only(t, Decide(s))
	creates = actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].Size != nil {
		t.Fatalf("creates = %+v, want one at the pool's own size", creates)
	}
}

// Every host that could take the runner is short of what the job needs, and
// a larger one will have room when its work finishes: that is a wait, said in
// the words the operator reads, not a create onto the host that will kill it.
func TestHistorySizingHoldsOffEveryHostTooSmallForNow(t *testing.T) {
	s, _ := historyFleet(t, HistoryOn, 8400) // ~9.9 GB; b-big has 8 GB left, 16 GB in all
	pp := only(t, Decide(s))
	if n := len(actionsOf(pp.Actions, ActionCreate)); n != 0 {
		t.Fatalf("creates = %d, want none", n)
	}
	want := "held off a-small: jobs waiting need ~9.9 GB, it has 3 GB; held off b-big: jobs waiting need ~9.9 GB, it has 8 GB"
	if pp.Blocked != want {
		t.Fatalf("Blocked = %q, want %q", pp.Blocked, want)
	}
	if !pp.BlockedAtCapacity || pp.HistoryUnfit != "" {
		t.Fatalf("BlockedAtCapacity = %t, HistoryUnfit = %q: a wait, not a misfit", pp.BlockedAtCapacity, pp.HistoryUnfit)
	}
	if !strings.Contains(pp.Reason, want) {
		t.Fatalf("Reason %q does not carry why", pp.Reason)
	}
}

// A job no host could ever hold is not allowed to hold every other job back:
// it is left out of the requirement and reported, because only a larger host
// helps it.
func TestAJobNoHostCanEverFitIsReportedAndDoesNotBlockThePool(t *testing.T) {
	s, _ := historyFleet(t, HistoryOn, 64*1024)
	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "a-small" {
		t.Fatalf("creates = %+v, want one placed as before", creates)
	}
	if !strings.Contains(pp.HistoryUnfit, "no host that can run the pool has that much to give") {
		t.Fatalf("HistoryUnfit = %q", pp.HistoryUnfit)
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A host that runs a pool smaller than a larger one would is said once, as
// information, and only then: a host that gives the pool its full size, one
// that cannot run it at all and a pool that set no minimum to shrink to all
// say nothing, because a note on every host is a note nobody reads.
func TestAHostSaysItRunsAPoolSmallerOnlyWhenItDoes(t *testing.T) {
	big := sized("big", 2, 16, hostFor(32*1024), 100000)
	thinCPU := sized("thin-cpu", 2, 3, hostFor(32*1024), 100000)
	small := sized("small", 1, 4, hostFor(2867), 100000)

	dind := func(p *store.Pool) *store.Pool { p.DockerMode = store.DockerDinD; return p }
	fixed := func(cpus, minCPUs float64) *store.Pool {
		p := limited("fixed", cpus, 1024)
		p.Resources.MinCPUs = minCPUs
		return p
	}

	cases := []struct {
		name string
		host *store.Host
		pool *store.Pool
		want []string // empty: no sentence
	}{
		{"no host", nil, automatic("auto", 0, 1024), nil},
		{"no pool", big, nil, nil},
		{"a host that cannot run it", small, dind(automatic("plain", 0, 0)), nil},
		{"an automatic pool at its full share", big, dind(automatic("auto", 0.5, 1024)), nil},
		{"an automatic pair short of CPU", thinCPU, dind(automatic("auto", 0.5, 1024)),
			[]string{"CPU, split between the runner and its Docker daemon", "above this pool's minimum"}},
		{"an automatic pair short of memory", small, dind(automatic("auto", 0, 1024)),
			[]string{"of memory, split between the runner and its Docker daemon"}},
		{"a fixed pool whose standard fits", big, fixed(4, 1), nil},
		{"a fixed pool with no minimum", thinCPU, fixed(8, 0), nil},
		{"a fixed pool cut to its minimum", thinCPU, fixed(8, 1),
			[]string{"smaller than this pool's standard size", "never less than this pool's minimum"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := HostReduction(tc.host, tc.pool)
			if len(tc.want) == 0 {
				if got != "" {
					t.Errorf("HostReduction = %q, want nothing", got)
				}
				return
			}
			for _, w := range tc.want {
				if !strings.Contains(got, w) {
					t.Errorf("HostReduction = %q, want it to contain %q", got, w)
				}
			}
		})
	}
}

// A CPU minimum the operator typed is theirs to lower, so a machine too small
// for it names it as what the runner is charged -- and, for a pair, that it is
// needed twice over. A share under the minimum alone is not a shortfall: the
// runner is given the minimum (TestAMinimumAboveTheShareIsGivenRatherThanRefused).
func TestAMinimumTheWholeMachineCannotCoverNamesIt(t *testing.T) {
	h := sized("thin-cpu", 2, 3, hostFor(32*1024), 100000)
	p := automatic("auto", 2, 0)
	p.DockerMode = store.DockerDinD
	got := HostShortfall(h, p)
	for _, w := range []string{"CPU to place on", "this pool's minimum of 2 CPU a container", "twice over for a runner and its Docker daemon"} {
		if !strings.Contains(got, w) {
			t.Errorf("shortfall = %q, want it to contain %q", got, w)
		}
	}
}

package scheduler

import (
	"fmt"
	"slices"

	"github.com/eyupio/zoomies/internal/store"
)

// osLabels and archLabels split store.ImplicitLabels into the two dimensions a
// pool can genuinely contradict. "self-hosted" belongs to neither: every pool
// in Zoomies is self-hosted, so a job asking for it constrains nothing.
var (
	osLabels   = map[string]bool{"linux": true, "windows": true, "macos": true}
	archLabels = map[string]bool{"x64": true, "arm": true, "arm64": true}
)

const (
	// noMatch is the score of a pool that cannot run a job at all. It is
	// negative so that callers can sort scores and reject anything below zero.
	noMatch = -1
	// exactScore is what a pool scores when it advertises precisely the labels
	// the job asked for. Surplus labels count down from here, which keeps every
	// matching score non-negative for any sane label set.
	exactScore = 1 << 16
)

// Matches reports whether a pool advertising poolLabels may run a job whose
// runs-on listed jobLabels.
//
// The rule mirrors what GitHub itself does. Labels every actions/runner binary
// advertises (store.ImplicitLabels) do not constrain pool selection, because
// "runs-on: [self-hosted, linux, x64]" is how nearly every workflow is written
// and it is not a request for a particular pool. The one exception is a pool
// that declares its own os or arch: that is a promise about the machine, so a
// job asking for a different one must not land there.
func Matches(poolLabels, jobLabels []string) bool {
	return matches(store.NormalizeLabels(poolLabels), store.NormalizeLabels(jobLabels), true)
}

// PoolMatches is Matches for a whole pool, which knows whether its runners
// advertise the implicit labels at all. A pool registered with
// --no-default-labels carries exactly the labels it lists, so a job asking
// for self-hosted or linux must find those among them: GitHub would never
// offer that job to such a runner, and a runner started for it would sit
// idle while the job waited.
func PoolMatches(p *store.Pool, jobLabels []string) bool {
	return matches(store.NormalizeLabels(p.Labels), store.NormalizeLabels(jobLabels), !p.NoDefaultLabels)
}

// matches is Matches over already-normalised label sets. implicit says
// whether the pool's runners advertise store.ImplicitLabels.
func matches(pool, job []string, implicit bool) bool {
	for _, l := range job {
		if implicit && store.ImplicitLabels[l] {
			continue
		}
		if !slices.Contains(pool, l) {
			return false
		}
	}
	return !contradicts(pool, job, osLabels) && !contradicts(pool, job, archLabels)
}

// contradicts reports whether the job asked for a label from dim that the pool
// lacks while declaring a different label from the same dimension. A pool that
// declares nothing in a dimension makes no promise and contradicts nothing.
func contradicts(pool, job []string, dim map[string]bool) bool {
	declares := slices.ContainsFunc(pool, func(l string) bool { return dim[l] })
	if !declares {
		return false
	}
	return slices.ContainsFunc(job, func(l string) bool {
		return dim[l] && !slices.Contains(pool, l)
	})
}

// Score ranks how well a pool fits a job. Higher is better; a negative score
// means the pool cannot run the job at all.
//
// Every matching pool satisfies all of the job's explicit labels by
// construction, so the only thing left to rank on is surplus: capability the
// job never asked for. Preferring the smallest surplus keeps a specialised
// pool (say gpu + cuda12) free for the jobs that actually need it.
func Score(poolLabels, jobLabels []string) int {
	return score(poolLabels, jobLabels, true)
}

// score is Score for a pool that may not advertise the implicit labels.
func score(poolLabels, jobLabels []string, implicit bool) int {
	pool := store.NormalizeLabels(poolLabels)
	job := store.NormalizeLabels(jobLabels)
	if !matches(pool, job, implicit) {
		return noMatch
	}
	surplus := 0
	for _, l := range pool {
		if !slices.Contains(job, l) {
			surplus++
		}
	}
	return max(exactScore-surplus, 0)
}

// Eligible reports whether a pool may run a job at all, and when it may not,
// says why in the operator's words.
//
// The three tests are asked in the order an operator would ask them. A
// disabled pool was disabled on purpose. A pool belonging to another GitHub
// App installation cannot run the job whatever its labels say: Zoomies would
// mint the runner's registration in the wrong GitHub target, and the job would
// sit queued while a runner waited for it somewhere it can never be offered.
// Labels come last, because they are the only one of the three an operator
// changes by editing a workflow.
func Eligible(p *store.Pool, j *store.Job) (bool, string) {
	switch {
	case p == nil || j == nil:
		return false, ""
	case !p.Enabled:
		return false, "the pool is disabled"
	case j.InstallationID == "":
		return false, "no GitHub App installation here covers that repository"
	case p.InstallationID != j.InstallationID:
		return false, "the pool belongs to another GitHub App installation"
	case !PoolMatches(p, j.Labels):
		return false, "the pool does not advertise those labels"
	}
	return true, ""
}

// BestPool returns the pool that best fits a job, or nil when no pool is
// eligible for it -- which the caller surfaces as a configuration problem
// rather than silently dropping the job.
//
// Ties break on pool name and then pool ID, so the same job always lands in
// the same pool. Anything else would make the controller disagree with itself
// across restarts, and make a scaling decision impossible to explain.
func BestPool(pools []*store.Pool, j *store.Job) *store.Pool {
	best, _ := bestPool(pools, j, nil)
	return best
}

// bestPool is BestPool that also explains an empty answer, given the target
// each installation manages so that the explanation can name one.
//
// The explanation names the nearest miss rather than every pool's objection.
// A job whose labels match a pool in another installation is a different
// problem from one whose labels match nothing here -- the first is a pool on
// the wrong installation, the second is a workflow asking for a machine this
// fleet does not offer -- and only the first is worth a sentence, because the
// second is what the Jobs page already says.
func bestPool(pools []*store.Pool, j *store.Job, targets map[string]string) (*store.Pool, string) {
	var best *store.Pool
	bestScore := noMatch
	var elsewhere *store.Pool
	for _, p := range pools {
		if p == nil {
			continue
		}
		if ok, _ := Eligible(p, j); !ok {
			// A pool that would take the job but for its installation is the
			// near miss worth reporting. Ties break the same way matches do,
			// so the sentence does not change between passes.
			if p.Enabled && PoolMatches(p, j.Labels) &&
				(elsewhere == nil || lessPool(p, elsewhere)) {
				elsewhere = p
			}
			continue
		}
		s := score(p.Labels, j.Labels, !p.NoDefaultLabels)
		if s < 0 {
			continue
		}
		if best == nil || s > bestScore || (s == bestScore && lessPool(p, best)) {
			best, bestScore = p, s
		}
	}
	if best != nil || elsewhere == nil {
		return best, ""
	}
	if j.InstallationID == "" {
		return nil, fmt.Sprintf("its labels match pool %s, but no GitHub App installation here covers %s", elsewhere.Name, j.Repo)
	}
	return nil, fmt.Sprintf("its labels match pool %s, which belongs to installation %s",
		elsewhere.Name, installationName(elsewhere.InstallationID, targets))
}

// installationName prefers the target an installation manages -- the
// organisation or repository an operator recognises -- and falls back to the
// identifier when the caller did not supply the targets.
func installationName(id string, targets map[string]string) string {
	if t := targets[id]; t != "" {
		return t
	}
	return id
}

// lessPool is the total order used wherever two pools would otherwise tie.
func lessPool(a, b *store.Pool) bool {
	if a.Name != b.Name {
		return a.Name < b.Name
	}
	return a.ID < b.ID
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

func TestMatches(t *testing.T) {
	tests := []struct {
		name string
		pool []string
		job  []string
		want bool
	}{
		{"exact match", []string{"gpu"}, []string{"gpu"}, true},
		{"pool is a superset", []string{"gpu", "cuda12"}, []string{"gpu"}, true},
		{"job label missing from pool", []string{"gpu"}, []string{"gpu", "cuda12"}, false},
		{"job asks only for implicit labels", []string{"gpu"},
			[]string{"self-hosted", "linux", "x64"}, true},
		{"implicit-only job and label-less pool", nil, []string{"self-hosted", "linux", "x64"}, true},
		{"label-less pool cannot serve a real label", nil, []string{"gpu"}, false},
		{"empty job labels match anything", []string{"gpu"}, nil, true},
		{"pool declares the os the job asked for",
			[]string{"linux", "gpu"}, []string{"self-hosted", "linux", "gpu"}, true},
		{"os contradiction",
			[]string{"windows", "gpu"}, []string{"self-hosted", "linux", "gpu"}, false},
		{"arch contradiction",
			[]string{"linux", "arm64", "gpu"}, []string{"self-hosted", "linux", "x64", "gpu"}, false},
		{"pool declares no arch, so any arch matches",
			[]string{"linux", "gpu"}, []string{"self-hosted", "arm64", "gpu"}, true},
		{"pool declares an arch the job did not ask for",
			[]string{"linux", "arm64", "gpu"}, []string{"self-hosted", "linux", "gpu"}, true},
		{"case and whitespace are normalised",
			[]string{" GPU ", "Cuda12"}, []string{"gpu", " cuda12"}, true},
		{"self-hosted alone never contradicts",
			[]string{"linux", "x64"}, []string{"self-hosted"}, true},
		{"duplicate labels do not change the answer",
			[]string{"gpu", "gpu"}, []string{"gpu", "GPU"}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := Matches(tc.pool, tc.job); got != tc.want {
				t.Fatalf("Matches(%v, %v) = %v, want %v", tc.pool, tc.job, got, tc.want)
			}
			score := Score(tc.pool, tc.job)
			if (score >= 0) != tc.want {
				t.Fatalf("Score(%v, %v) = %d, which disagrees with Matches", tc.pool, tc.job, score)
			}
		})
	}
}

func TestScorePrefersTheLeastSurplus(t *testing.T) {
	job := []string{"self-hosted", "linux", "gpu"}
	exact := Score([]string{"gpu"}, job)
	oneSurplus := Score([]string{"gpu", "cuda12"}, job)
	twoSurplus := Score([]string{"gpu", "cuda12", "bigmem"}, job)

	if !(exact > oneSurplus && oneSurplus > twoSurplus) {
		t.Fatalf("scores are not ordered by surplus: exact=%d one=%d two=%d",
			exact, oneSurplus, twoSurplus)
	}
	if twoSurplus < 0 {
		t.Fatalf("a matching pool scored negative: %d", twoSurplus)
	}
	// A label the job did ask for is not surplus, even an implicit one.
	if got := Score([]string{"linux", "gpu"}, job); got != exact {
		t.Fatalf("Score with a requested implicit label = %d, want %d", got, exact)
	}
	if got := Score([]string{"windows"}, job); got >= 0 {
		t.Fatalf("Score for a contradicting pool = %d, want negative", got)
	}
}

// job is a queued job on the one installation the label tests use, so that a
// case exercises the label rule rather than the installation rule.
func job(labels ...string) *store.Job {
	return &store.Job{InstallationID: "ins_one", Repo: "acme/widgets",
		State: store.JobQueued, Labels: store.StringSlice(labels)}
}

func TestBestPool(t *testing.T) {
	general := &store.Pool{ID: "p1", Name: "general", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
	gpu := &store.Pool{ID: "p2", Name: "gpu", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64", "gpu"}, Enabled: true}
	bigGPU := &store.Pool{ID: "p3", Name: "gpu-big", InstallationID: "ins_one", Labels: store.StringSlice{"linux", "x64", "gpu", "bigmem"}, Enabled: true}
	disabled := &store.Pool{ID: "p4", Name: "arm", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: false}
	pools := []*store.Pool{bigGPU, disabled, gpu, general, nil}

	tests := []struct {
		name string
		job  []string
		want string
	}{
		{"implicit-only job takes the least specific pool", []string{"self-hosted", "linux", "x64"}, "general"},
		{"gpu job takes the smallest pool that has a gpu", []string{"self-hosted", "gpu"}, "gpu"},
		{"bigmem job needs the big pool", []string{"gpu", "bigmem"}, "gpu-big"},
		{"nothing claims an unknown label", []string{"windows-2022"}, ""},
		{"a disabled pool is never chosen", []string{"gpu", "arm64"}, ""},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := BestPool(pools, job(tc.job...))
			switch {
			case got == nil && tc.want != "":
				t.Fatalf("BestPool(%v) = nil, want %s", tc.job, tc.want)
			case got != nil && got.Name != tc.want:
				t.Fatalf("BestPool(%v) = %s, want %q", tc.job, got.Name, tc.want)
			}
		})
	}
}

func TestBestPoolTieBreaksOnName(t *testing.T) {
	// Two pools that fit the job equally well: the name decides, whatever order
	// the caller happened to pass them in.
	beta := &store.Pool{ID: "p-beta", Name: "beta", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	alpha := &store.Pool{ID: "p-alpha", Name: "alpha", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}

	for _, pools := range [][]*store.Pool{{beta, alpha}, {alpha, beta}} {
		got := BestPool(pools, job("gpu"))
		if got == nil || got.Name != "alpha" {
			t.Fatalf("BestPool = %v, want alpha", got)
		}
	}

	// Same name (only possible mid-rename) falls back to the ID.
	a := &store.Pool{ID: "p-a", Name: "same", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	b := &store.Pool{ID: "p-b", Name: "same", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}
	if got := BestPool([]*store.Pool{b, a}, job("gpu")); got != a {
		t.Fatalf("BestPool = %v, want the lower ID", got)
	}
}

func TestEligibleAsksTheThreeQuestionsInOrder(t *testing.T) {
	pool := func(f func(*store.Pool)) *store.Pool {
		p := &store.Pool{ID: "p1", Name: "linux-x64", InstallationID: "ins_one",
			Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
		f(p)
		return p
	}
	tests := []struct {
		name   string
		pool   *store.Pool
		job    *store.Job
		want   bool
		reason string
	}{
		{
			name: "a pool on the job's own installation whose labels fit takes it",
			pool: pool(func(*store.Pool) {}),
			job:  job("linux", "x64"),
			want: true,
		},
		{
			name:   "a disabled pool is refused before anything else is asked",
			pool:   pool(func(p *store.Pool) { p.Enabled = false; p.InstallationID = "ins_other" }),
			job:    job("windows"),
			reason: "the pool is disabled",
		},
		{
			name:   "a job no installation covers is refused before its labels are read",
			pool:   pool(func(*store.Pool) {}),
			job:    &store.Job{Repo: "nobody/here", Labels: store.StringSlice{"linux", "x64"}},
			reason: "no GitHub App installation here covers that repository",
		},
		{
			name:   "a pool on another installation is refused however well its labels fit",
			pool:   pool(func(p *store.Pool) { p.InstallationID = "ins_two" }),
			job:    job("linux", "x64"),
			reason: "the pool belongs to another GitHub App installation",
		},
		{
			name:   "and only then are the labels the answer",
			pool:   pool(func(*store.Pool) {}),
			job:    job("windows"),
			reason: "the pool does not advertise those labels",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			ok, reason := Eligible(tc.pool, tc.job)
			if ok != tc.want {
				t.Fatalf("Eligible = %v, want %v (%q)", ok, tc.want, reason)
			}
			if reason != tc.reason {
				t.Fatalf("reason = %q, want %q", reason, tc.reason)
			}
		})
	}
}

// A job that goes unclaimed because the pool advertising its labels is on
// another installation looks, from the Jobs page, exactly like a mislabelled
// workflow. The two need different fixes, so the plan says which it is.
func TestAnUnclaimedJobSaysWhenThePoolIsOnAnotherInstallation(t *testing.T) {
	theirs := &store.Pool{ID: "p_theirs", Name: "linux-x64", InstallationID: "ins_two",
		Labels: store.StringSlice{"linux", "x64"}, Enabled: true}
	pools := []*store.Pool{theirs}
	targets := map[string]string{"ins_two": "globex"}

	_, reason := bestPool(pools, job("linux", "x64"), targets)
	if want := "its labels match pool linux-x64, which belongs to installation globex"; reason != want {
		t.Fatalf("reason = %q, want %q", reason, want)
	}

	// Without the targets the identifier is all there is to name it by, which
	// is still better than saying nothing.
	if _, reason := bestPool(pools, job("linux", "x64"), nil); !strings.Contains(reason, "ins_two") {
		t.Fatalf("reason = %q, want it to fall back to the identifier", reason)
	}

	// A repository no installation covers is a different sentence: adding a
	// pool would not help, installing the App on that target would.
	orphan := &store.Job{Repo: "nobody/here", State: store.JobQueued, Labels: store.StringSlice{"linux", "x64"}}
	if _, reason := bestPool(pools, orphan, targets); !strings.Contains(reason, "no GitHub App installation here covers nobody/here") {
		t.Fatalf("reason = %q, want it to name the uncovered repository", reason)
	}

	// Labels that match nothing get no sentence at all: the page already says
	// no pool claims the job, and a reason repeating that is noise.
	if _, reason := bestPool(pools, job("windows"), targets); reason != "" {
		t.Fatalf("reason = %q, want none for a plain label mismatch", reason)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// limits.runners is a ceiling on the whole fleet, not on a pool or a pass: it
// counts the runners already live in every pool, it is shared between pools,
// and a pool it holds back must say that it did -- otherwise the operator
// reads "the next pass will continue" about a shortfall no pass will clear.
func TestTheRunnerCeilingCountsTheWholeFleetAndSaysSoWhenItBinds(t *testing.T) {
	cases := []struct {
		name        string
		ceiling     int
		wantCreates int
		wantCeiling bool
	}{
		{"no ceiling leaves every job served", 0, 6, false},
		{"a ceiling above demand changes nothing", 20, 6, false},
		{"a ceiling below demand allows only the difference", 3, 2, true},
		{"a fleet already at its ceiling creates nothing", 1, 0, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			a, z := testPool("aaa", "aaa"), testPool("zzz", "zzz")
			var jobs []*store.Job
			for _, id := range []string{"a1", "a2", "a3"} {
				jobs = append(jobs, queued(id, time.Minute, "aaa"))
			}
			for _, id := range []string{"z1", "z2", "z3"} {
				jobs = append(jobs, queued(id, time.Minute, "zzz"))
			}
			// One runner is already live in pool aaa, busy on something else:
			// it holds a place under the ceiling though it serves none of the
			// queued jobs.
			busy := testRunner("run_busy", a, store.RunnerBusy, time.Minute)
			s := snap([]*store.Pool{a, z}, []*store.Runner{busy}, jobs, []*store.Host{testHost("host_a", 16, 1)})
			s.Policy.MaxRunners = tc.ceiling

			plan := Decide(s)
			if got := countOf(plan.Actions, ActionCreate); got != tc.wantCreates {
				t.Fatalf("creates = %d, want %d", got, tc.wantCreates)
			}
			named := false
			for _, pp := range plan.Pools {
				if strings.Contains(pp.Reason, "limits.runners") {
					named = true
				}
			}
			if named != tc.wantCeiling {
				t.Fatalf("a pool's reason names limits.runners = %v, want %v: %+v", named, tc.wantCeiling, plan.Pools)
			}
		})
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The room a pool with a minimum has on a host is the number of runners the
// pass would really place there: as many at the standard size as fit, then one
// more at whatever the machine can spare above the minimum. Counting only the
// standard calls a host that runs a second, smaller runner one that cannot,
// and pool.max_above_room and pool.host_overcommitted then warn about room the
// fleet is using. Counting every runner at the minimum promises the opposite:
// a reduced runner is given all the host can spare, so there is never a
// second one behind it.
func TestHostRoomCountsTheRunnersAMinimumReallyPlaces(t *testing.T) {
	tests := []struct {
		name     string
		memoryMB int64
		pool     *store.Pool
		wantFits int
	}{
		{"a host with room for one standard and one reduced runner holds two", 12 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 2},
		{"a host that fits two standard runners exactly holds two", 16 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 2},
		{"a leftover below the minimum is not a runner", 10 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 1},
		{"a host below the standard holds one runner given all it has, not several at the minimum", 7 * 1024,
			withMinimum("m", 2, 8*1024, 0, 3*1024), 1},
		{"a host below the minimum holds nothing", 3 * 1024,
			withMinimum("m", 2, 8*1024, 0, 4*1024), 0},
		{"a pool with no minimum counts the standard alone", 12 * 1024,
			limited("m", 2, 8*1024), 1},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 8, 32, hostFor(tc.memoryMB), 500*1024)
			got := HostRoomFor(h, tc.pool)
			if got.Fits != tc.wantFits {
				t.Errorf("HostRoomFor = %+v, want fits %d", got, tc.wantFits)
			}
			// The pass is the arithmetic's witness: the count must be what
			// placement actually does on the same empty machine.
			hs := newHostSet([]*store.Host{h}, []*store.Pool{tc.pool}, nil, now)
			if placed := hs.placeAvoiding(tc.pool, 8, nil); len(placed) != tc.wantFits {
				t.Errorf("the pass placed %d runners, want the %d the room promises", len(placed), tc.wantFits)
			}
		})
	}
}

// When a pool with a minimum is blocked, the resource named is the one short
// of the minimum, not the one short of the standard. A host with memory for a
// reduced runner and no CPU for one is out of CPU; "short of memory" would send
// the operator to add memory the pool could already run in.
func TestABlockedPoolWithAMinimumNamesWhatIsShortOfTheMinimum(t *testing.T) {
	tests := []struct {
		name string
		left Reservation
		want string
	}{
		{"memory above the minimum and CPU below it is short of CPU",
			Reservation{CPUs: 1, MemoryMB: 6 * 1024, DiskMB: 100 * 1024}, "short of CPU"},
		{"CPU above the minimum and memory below it is short of memory",
			Reservation{CPUs: 3, MemoryMB: 3 * 1024, DiskMB: 100 * 1024}, "short of memory"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h := sized("h", 8, 32, hostFor(32*1024), 500*1024)
			p := withMinimum("m", 4, 8*1024, 2, 4*1024)
			hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
			hs.left[h.ID] = tc.left
			hs.promisedMemory[h.ID] = tc.left.MemoryMB
			if placed := hs.placeAvoiding(p, 1, nil); len(placed) != 0 {
				t.Fatalf("placed %+v on a host short of the minimum", placed)
			}
			if got := hs.why(p).what; !strings.Contains(got, tc.want) {
				t.Errorf("why = %q, want it to say %q", got, tc.want)
			}
		})
	}
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The report that found this: a runner of a pool that left its size to the
// host was killed for want of memory, and raising the pool's minimum could not
// help -- a minimum above the slot share left the host out altogether, so the
// only way to give a runner more was to lower the host's capacity. The minimum
// is the least a runner may have, so a share under it is raised to it: each
// runner is given and charged the minimum, and the host holds as many as its
// machine covers rather than none.
func TestAMinimumAboveTheShareIsGivenRatherThanRefused(t *testing.T) {
	// 16 GB over eight slots is a 2 GB share; the pool will take no less
	// than 4 GB.
	h := sized("h", 8, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 0, 4096)

	if field := ShareTooSmall(h, p); field != "" {
		t.Fatalf("ShareTooSmall = %q, want a share under the minimum to be raised to it", field)
	}
	if !HostFits(h, p) {
		t.Fatalf("the host was refused: %s", HostShortfall(h, p))
	}
	if got := Reserve(p, h).MemoryMB; got != 4096 {
		t.Errorf("charge = %d MB, want the 4096 MB minimum", got)
	}
	got, source := Allocation(p, h, true)
	if got.MemoryMB != 4096 || source != store.AllocationFromHost {
		t.Errorf("Allocation = %+v from %q, want 4096 MB from the host", got, source)
	}

	// The slots are eight and the machine covers four runners of 4 GB: the
	// room says four, and the pass places four -- all of them whole, not
	// reduced.
	room := HostRoomFor(h, p)
	if room.Room != 4 || room.LimitedBy != "memory" {
		t.Errorf("HostRoomFor = %+v, want room for 4, limited by memory", room)
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 8, nil)
	if len(placed) != 4 {
		t.Fatalf("the pass placed %d runners, want the 4 the room promises", len(placed))
	}
	for _, pl := range placed {
		if pl.size != nil {
			t.Errorf("a runner was placed reduced to %+v, want every one at the minimum", *pl.size)
		}
	}

	note := HostReduction(h, p)
	for _, w := range []string{"2 GB of memory", "4 GB", "fewer of them than its 8 slots"} {
		if !strings.Contains(note, w) {
			t.Errorf("HostReduction = %q, want it to contain %q", note, w)
		}
	}
}

// The minimum is the floor, never the size: where the share is larger, the
// runner is given all of it.
func TestAShareAboveTheMinimumIsGivenWhole(t *testing.T) {
	h := sized("h", 2, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)

	got, _ := Allocation(p, h, true)
	share := HostShare(h)
	if got.MemoryMB != share.MemoryMB || got.CPUs != share.CPUs {
		t.Errorf("Allocation = %+v, want the whole share %+v rather than the minimum", got, share)
	}
	if HostReduction(h, p) != "" {
		t.Errorf("HostReduction = %q on a host whose share covers the minimum", HostReduction(h, p))
	}
}

// A docker-in-docker slot carries a runner and its daemon, and the minimum is
// per container, so a share under it is raised to twice the minimum -- which
// the backend then splits, giving each container the minimum.
func TestADinDSlotUnderItsMinimumIsGivenTwiceIt(t *testing.T) {
	h := sized("h", 8, 16, hostFor(16*1024), 100000)
	p := automatic("auto", 1, 2048)
	p.DockerMode = store.DockerDinD

	got, _ := Allocation(p, h, true)
	if got.MemoryMB != 4096 || got.CPUs != 2 {
		t.Errorf("Allocation = %+v, want the pair's 2 CPU and 4096 MB", got)
	}
	runner, daemon := got.SplitWithDaemon()
	if runner.MemoryMB != 2048 || daemon.MemoryMB != 2048 {
		t.Errorf("split = %+v and %+v, want the 2048 MB minimum each", runner, daemon)
	}
	if r := Reserve(p, h); r.MemoryMB != 4096 || r.CPUs != 2 {
		t.Errorf("charge = %+v, want one slot of the pair's 2 CPU and 4096 MB", r)
	}
}

// A pool with no minimum is exactly what it was: a share too thin to run a
// runner refuses the host, because nobody said the runner should be larger.
func TestAThinShareWithNoMinimumIsStillRefused(t *testing.T) {
	h := sized("h", 32, 8, hostFor(16*1024), 100000)
	p := automatic("auto", 0, 0)
	if field := ShareTooSmall(h, p); field != "cpu" {
		t.Errorf("ShareTooSmall = %q, want the 0.2 CPU share refused", field)
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// withMinimum is a fixed-size pool that will accept a smaller runner when no
// host has room for the standard.
func withMinimum(name string, cpus float64, memoryMB int64, minCPUs float64, minMemoryMB int64) *store.Pool {
	p := limited(name, cpus, memoryMB)
	p.Resources.MinCPUs = minCPUs
	p.Resources.MinMemoryMB = minMemoryMB
	return p
}

// The case the minimum exists for: a machine a little short of the standard
// size. Without a minimum the job waits for a host that is never coming; with
// one it runs, and with as much of the standard as the host can spare rather
// than the minimum, because the minimum is what the operator will accept and
// not what they asked for.
func TestAHostJustShortOfTheStandardRunsTheJobWithAllItCanSpare(t *testing.T) {
	h := sized("short", 1, 16, hostFor(30*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].hostID != "short" {
		t.Fatalf("placed %+v, want one runner on the short host", placed)
	}
	size := placed[0].size
	if size == nil {
		t.Fatal("the runner was placed at the standard size on a host that has no room for it")
	}
	if size.MemoryMB != 30*1024 {
		t.Errorf("memory = %d MB, want the 30 GB the host has, not the %d MB minimum", size.MemoryMB, p.Resources.MinMemoryMB)
	}
	if size.CPUs != 8 {
		t.Errorf("CPU = %g, want the standard 8: the host has room for all of it", size.CPUs)
	}

	// The pool with no minimum is exactly what it was: it does not fit.
	plain := limited("big", 8, 32*1024)
	hs = newHostSet([]*store.Host{h}, []*store.Pool{plain}, nil, now)
	if got := hs.placeAvoiding(plain, 1, nil); len(got) != 0 {
		t.Fatalf("a pool with no minimum was placed on a host too small for it: %+v", got)
	}
}

// A minimum never shrinks a runner the fleet could have given the full size
// to: the standard goes on any host with room for it, even when a short host
// would score better, and the reduced size is only the fallback.
func TestTheStandardSizeWinsWhereverAHostHasRoomForIt(t *testing.T) {
	short := sized("a-short", 4, 16, hostFor(30*1024), 100000)
	whole := sized("b-whole", 1, 16, hostFor(32*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)

	hs := newHostSet([]*store.Host{short, whole}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 2, nil)
	if len(placed) != 2 {
		t.Fatalf("placed %+v, want two runners", placed)
	}
	if placed[0].hostID != "b-whole" || placed[0].size != nil {
		t.Errorf("first runner = %+v, want the standard size on the host with room for it", placed[0])
	}
	if placed[1].hostID != "a-short" || placed[1].size == nil {
		t.Errorf("second runner = %+v, want a reduced size on the short host once the whole one is full", placed[1])
	}
}

// Below the minimum is still no: a floor is a floor.
func TestAHostBelowTheMinimumTakesNothing(t *testing.T) {
	h := sized("tiny", 1, 16, hostFor(20*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.placeAvoiding(p, 1, nil); len(got) != 0 {
		t.Fatalf("placed %+v below the pool's 24 GB minimum", got)
	}
	if HostFits(h, p) {
		t.Error("HostFits says a 20 GB host can run a pool whose minimum is 24 GB")
	}
	if HostShortfall(h, p) == "" {
		t.Error("no shortfall named for a host below the minimum")
	}
}

// A reduced runner is charged what it was given. Charging it the standard
// would read a host filled with reduced runners as over-committed and refuse
// the next one it had room for.
func TestAReducedRunnerIsChargedWhatItWasGiven(t *testing.T) {
	h := sized("short", 2, 16, hostFor(40*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 16*1024)
	reduced := &store.Runner{ID: "r1", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocatedCPUs: 8, AllocatedMemoryMB: 20 * 1024, AllocationSource: store.AllocationReduced}
	runners := map[string][]*store.Runner{p.ID: {reduced}}

	if got := Reserved(h, []*store.Pool{p}, runners); got.MemoryMB != 20*1024 {
		t.Errorf("reserved memory = %d MB, want the 20 GB the reduced runner was given", got.MemoryMB)
	}
	// 40 GB less the 20 GB promised leaves 20: short of the standard, above
	// the minimum, so the second runner is reduced too, to what is left.
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil || placed[0].size.MemoryMB != 20*1024 {
		t.Fatalf("placed %+v, want a second runner reduced to the 20 GB left", placed)
	}
}

// A docker-in-docker runner gives its daemon the same limits it has, so the
// pair is charged twice what each is given, and a reduced pair splits what the
// host can spare between them.
func TestAReducedDockerInDockerPairSplitsWhatIsLeft(t *testing.T) {
	h := sized("short", 1, 16, hostFor(12*1024), 100000)
	p := withMinimum("builds", 4, 8*1024, 2, 4*1024)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil {
		t.Fatalf("placed %+v, want one reduced pair", placed)
	}
	if got := placed[0].size.MemoryMB; got != 6*1024 {
		t.Errorf("each container = %d MB, want 6 GB: half of the 12 GB the host can spare", got)
	}
}

// A reduced docker-in-docker runner's row holds the per-container limit --
// what ReducedSize hands to the backend, and what the previous test reads off
// placed[0].size -- not the host-side charge that placement actually
// subtracted. RunnerCharge has to double a typed field back to recover that
// charge, the same doubling Reserve applies to a full-size pair. Get the
// factor backwards and a host already holding one of these runners is read as
// half as loaded as it is: exactly the mismatch Reserve's own comment warns
// about ("a host read as half committed while its containers' quotas added up
// to every core it had").
func TestAReducedDockerInDockerRunnerIsChargedTwiceItsRow(t *testing.T) {
	h := sized("short", 1, 16, hostFor(12*1024), 100000)
	p := withMinimum("builds", 4, 8*1024, 2, 4*1024)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	placed := hs.placeAvoiding(p, 1, nil)
	if len(placed) != 1 || placed[0].size == nil {
		t.Fatalf("placed %+v, want one reduced pair", placed)
	}
	grant := *placed[0].size

	r := &store.Runner{ID: "r1", PoolID: p.ID, HostID: h.ID, State: store.RunnerBusy,
		AllocatedCPUs: grant.CPUs, AllocatedMemoryMB: grant.MemoryMB, AllocationSource: store.AllocationReduced}

	got := RunnerCharge(p, h, r)
	if got.CPUs != grant.CPUs*2 {
		t.Errorf("CPU charge = %g, want double the row's per-container %g: a docker-in-docker pair is charged for both containers", got.CPUs, grant.CPUs)
	}
	if got.MemoryMB != grant.MemoryMB*2 {
		t.Errorf("memory charge = %d MB, want double the row's per-container %d MB", got.MemoryMB, grant.MemoryMB)
	}

	// Reserved sums RunnerCharge across a host's live runners -- the figure
	// the next reconcile pass trusts to know what room is left. It must agree
	// with what the placement pass just subtracted for this exact runner.
	runners := map[string][]*store.Runner{p.ID: {r}}
	if reserved := Reserved(h, []*store.Pool{p}, runners); reserved != got {
		t.Errorf("Reserved = %+v, want it to match RunnerCharge's %+v for the host's one live runner", reserved, got)
	}
}

// The create's reason says the runner is smaller than its pool asks for, and
// the action carries the size, so the Runners page and the scaling history
// both explain a slow job on a reduced runner.
func TestAReducedCreateSaysSoInItsReason(t *testing.T) {
	h := sized("short", 1, 16, hostFor(30*1024), 100000)
	p := withMinimum("big", 8, 32*1024, 4, 24*1024)
	p.Labels = store.NormalizeLabels([]string{"big"})
	s := snap([]*store.Pool{p}, nil, []*store.Job{queued("j1", time.Minute, "big")}, []*store.Host{h})
	creates := actionsOf(Decide(s).Actions, ActionCreate)
	if len(creates) != 1 {
		t.Fatalf("creates = %+v, want one", creates)
	}
	if creates[0].Size == nil || creates[0].Size.MemoryMB != 30*1024 {
		t.Errorf("size = %+v, want 30 GB carried on the action", creates[0].Size)
	}
	if !strings.Contains(creates[0].Reason, "reduced to 8 CPU and 30 GB") {
		t.Errorf("reason = %q, want it to say the runner was reduced and to what", creates[0].Reason)
	}
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// A runner registered with --no-default-labels advertises only its own labels,
// so GitHub never offers it a job asking for self-hosted, linux or x64. Were
// the scheduler to match such a job anyway, it would start a runner the job can
// never reach and the job would wait while the pool reported itself busy.
func TestAPoolWithoutDefaultLabelsMatchesOnlyWhatItLists(t *testing.T) {
	bare := &store.Pool{Labels: store.StringSlice{"gpu"}, NoDefaultLabels: true}
	listed := &store.Pool{Labels: store.StringSlice{"gpu", "self-hosted", "linux"}, NoDefaultLabels: true}
	usual := &store.Pool{Labels: store.StringSlice{"gpu"}}

	tests := []struct {
		name string
		pool *store.Pool
		job  []string
		want bool
	}{
		{"its own label alone", bare, []string{"gpu"}, true},
		{"self-hosted it does not advertise", bare, []string{"self-hosted", "gpu"}, false},
		{"an os it does not advertise", bare, []string{"linux", "gpu"}, false},
		{"implicit labels it lists itself", listed, []string{"self-hosted", "linux", "gpu"}, true},
		{"an arch it still does not list", listed, []string{"x64", "gpu"}, false},
		{"an ordinary pool is unchanged", usual, []string{"self-hosted", "linux", "gpu"}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := PoolMatches(tc.pool, tc.job); got != tc.want {
				t.Fatalf("PoolMatches(%v, %v) = %v, want %v", tc.pool.Labels, tc.job, got, tc.want)
			}
		})
	}
}

func TestBestPoolPassesOverAPoolWithoutDefaultLabelsForASelfHostedJob(t *testing.T) {
	// Named to sort first, so only the label rule can keep it from winning.
	bare := &store.Pool{ID: "p1", Name: "a-bare", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, NoDefaultLabels: true, Enabled: true}
	usual := &store.Pool{ID: "p2", Name: "b-usual", InstallationID: "ins_one", Labels: store.StringSlice{"gpu"}, Enabled: true}

	if got := BestPool([]*store.Pool{bare, usual}, job("self-hosted", "gpu")); got == nil || got.Name != "b-usual" {
		t.Fatalf("BestPool = %v, want b-usual", got)
	}
	if got := BestPool([]*store.Pool{bare, usual}, job("gpu")); got == nil || got.Name != "a-bare" {
		t.Fatalf("BestPool = %v, want a-bare for a job that names only gpu", got)
	}
	if ok, why := Eligible(bare, job("self-hosted", "gpu")); ok || why == "" {
		t.Fatalf("Eligible = %v, %q; want a refusal with a reason", ok, why)
	}
}

package scheduler

import (
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

func dur(d time.Duration) *store.Duration {
	v := store.Duration(d)
	return &v
}

// A pool that overrides nothing follows the fleet, and keeps following it.
//
// This is what makes the fleet's figures worth changing: a pool that had them
// copied onto it at creation would be frozen on whatever they were that day,
// and an operator raising scheduler.provision_timeout for a fleet on a slow
// registry would raise it for no pool at all.
func TestAPoolThatOverridesNothingFollowsTheFleet(t *testing.T) {
	fleet := Policy{
		ScaleUpDelay:      10 * time.Second,
		MaxRunnerLifetime: 24 * time.Hour,
		ProvisionTimeout:  10 * time.Minute,
		DrainTimeout:      5 * time.Minute,
		MaxCreatesPerTick: 4,
	}
	got := fleet.For(&store.Pool{Name: "zoomies-plain"})
	if got != fleet {
		t.Errorf("For() = %+v, want the fleet's own %+v", got, fleet)
	}
	if got := fleet.For(nil); got != fleet {
		t.Errorf("For(nil) = %+v, want the fleet's own %+v", got, fleet)
	}
}

// Each override replaces exactly one figure and leaves the rest alone, so a
// pool that has something to say about registering does not thereby have
// something to say about draining.
func TestAnOverrideReplacesOneFigure(t *testing.T) {
	fleet := Policy{
		ScaleUpDelay:      10 * time.Second,
		MaxRunnerLifetime: 24 * time.Hour,
		ProvisionTimeout:  10 * time.Minute,
		DrainTimeout:      5 * time.Minute,
		MaxCreatesPerTick: 4,
	}
	pool := &store.Pool{Name: "zoomies-windows", RunnerSettings: store.RunnerSettings{
		ProvisionTimeout: dur(45 * time.Minute),
	}}
	got := fleet.For(pool)
	if got.ProvisionTimeout != 45*time.Minute {
		t.Errorf("provision timeout = %s, want the pool's 45m", got.ProvisionTimeout)
	}
	if got.DrainTimeout != fleet.DrainTimeout || got.ScaleUpDelay != fleet.ScaleUpDelay ||
		got.MaxRunnerLifetime != fleet.MaxRunnerLifetime {
		t.Errorf("one override changed the others: %+v", got)
	}
}

// Zero is a real answer rather than "unset", which is the whole reason these
// are pointers. A pool on an air-gapped registry that pulls for half an hour
// means "never fail a runner for taking too long to register", and a type that
// read its zero as "nothing said" would give it the fleet's ten minutes back.
func TestZeroIsAnAnswerAndNotAnAbsence(t *testing.T) {
	fleet := Policy{ProvisionTimeout: 10 * time.Minute, DrainTimeout: 5 * time.Minute}
	pool := &store.Pool{Name: "zoomies-airgapped", RunnerSettings: store.RunnerSettings{
		ProvisionTimeout: dur(0),
	}}
	if got := fleet.For(pool); got.ProvisionTimeout != 0 {
		t.Errorf("provision timeout = %s, want 0: the pool asked for no timeout at all", got.ProvisionTimeout)
	}
}

// The fleet-wide create budget is not a pool's to raise. It is shared between
// pools, so a pool that could lift its own share would be taking the
// protection from the others.
func TestTheCreateBudgetIsNotOverridable(t *testing.T) {
	fleet := Policy{MaxCreatesPerTick: 4}
	pool := &store.Pool{Name: "zoomies-greedy", RunnerSettings: store.RunnerSettings{
		ScaleUpDelay: dur(0),
	}}
	if got := fleet.For(pool); got.MaxCreatesPerTick != 4 {
		t.Errorf("max creates per tick = %d, want the fleet's 4", got.MaxCreatesPerTick)
	}
}

// Set is what every surface asks before it says a pool has overrides at all.
func TestSetSaysWhetherAPoolOverridesAnything(t *testing.T) {
	if (store.RunnerSettings{}).Set() {
		t.Error("an empty RunnerSettings reports itself as set")
	}
	if !(store.RunnerSettings{DockerWait: dur(2 * time.Minute)}).Set() {
		t.Error("a pool with a docker wait reports itself as unset")
	}
	if !(store.RunnerSettings{ProvisionTimeout: dur(0)}).Set() {
		t.Error("an override of zero reports itself as unset; zero is an answer")
	}
}

package scheduler

import (
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// A top-priority pool with a deep backlog used to take every create of every
// tick, so a lower tier's jobs waited for as long as that backlog lasted. The
// share across tiers bounds that wait to one interval, without taking a burst
// at the top away from it before a lower tier has waited at all.
func TestCreateBudgetIsSharedAcrossPrioritiesOnlyAfterAFullInterval(t *testing.T) {
	const interval = 30 * time.Second
	cases := []struct {
		name      string
		lowWaited time.Duration
		interval  time.Duration
		budget    int
		wantHigh  int
		wantLow   int
		deferred  bool
		// first is the pool whose create executes first. The share goes
		// ahead of the tier it was taken from, so that registration
		// admission cutting a plan short cannot cut the share out of it.
		first string
	}{
		{"a lower tier that has waited a full interval gets a share", interval, interval, 3, 2, 1, true, "low"},
		{"a lower tier that waited longer than an interval gets a share", 2 * interval, interval, 3, 2, 1, true, "low"},
		{"a lower tier that has not waited an interval does not take from the top", interval - time.Second, interval, 3, 3, 0, false, "high"},
		{"with no interval priority alone decides", time.Hour, 0, 3, 3, 0, false, "high"},
		{"an uncapped tick serves both tiers in priority order", interval, interval, 0, 5, 1, false, "high"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			high, low := testPool("high", "high"), testPool("low", "low")
			high.Priority, low.Priority = 10, 0
			var jobs []*store.Job
			for _, id := range []string{"h1", "h2", "h3", "h4", "h5"} {
				jobs = append(jobs, queued(id, time.Minute, "high"))
			}
			jobs = append(jobs, queued("l1", tc.lowWaited, "low"))
			s := snap([]*store.Pool{high, low}, nil, jobs, []*store.Host{testHost("host_a", 20, 0)})
			s.Policy.MaxCreatesPerTick = tc.budget
			s.Policy.Interval = tc.interval

			plan := Decide(s)
			byName := map[string]PoolPlan{}
			for _, pp := range plan.Pools {
				byName[pp.PoolName] = pp
			}
			if got := countOf(byName["high"].Actions, ActionCreate); got != tc.wantHigh {
				t.Errorf("high creates = %d, want %d", got, tc.wantHigh)
			}
			if got := countOf(byName["low"].Actions, ActionCreate); got != tc.wantLow {
				t.Errorf("low creates = %d, want %d", got, tc.wantLow)
			}
			if len(plan.Actions) == 0 || plan.Actions[0].PoolName != tc.first {
				t.Errorf("first action = %+v, want a create for %s", plan.Actions, tc.first)
			}
			said := strings.Contains(byName["high"].Reason, "deferred for fairness across priorities")
			if said != tc.deferred {
				t.Errorf("high reason = %q, want deferred-for-fairness %v", byName["high"].Reason, tc.deferred)
			}
		})
	}
}

// The share is one create per waiting pool, not a split of the budget: it
// stops the starvation, and priority still decides everything after it.
func TestTheShareAcrossPrioritiesIsOneCreatePerWaitingPool(t *testing.T) {
	high, mid, low := testPool("high", "high"), testPool("mid", "mid"), testPool("low", "low")
	high.Priority, mid.Priority, low.Priority = 10, 5, 0
	var jobs []*store.Job
	for _, id := range []string{"h1", "h2", "h3", "h4"} {
		jobs = append(jobs, queued(id, time.Minute, "high"))
	}
	jobs = append(jobs, queued("m1", time.Minute, "mid"), queued("m2", time.Minute, "mid"),
		queued("l1", time.Minute, "low"), queued("l2", time.Minute, "low"))
	s := snap([]*store.Pool{high, mid, low}, nil, jobs, []*store.Host{testHost("host_a", 20, 0)})
	s.Policy.MaxCreatesPerTick = 4
	s.Policy.Interval = 30 * time.Second

	got := map[string]int{}
	reasons := map[string]string{}
	for _, pp := range Decide(s).Pools {
		got[pp.PoolName] = countOf(pp.Actions, ActionCreate)
		reasons[pp.PoolName] = pp.Reason
	}
	if got["high"] != 2 || got["mid"] != 1 || got["low"] != 1 {
		t.Fatalf("creates = %v, want high 2, mid 1, low 1", got)
	}
	// mid is above the lowest pool that took a share, so its shortfall is the
	// share's doing too; low's is only the budget.
	for _, name := range []string{"high", "mid"} {
		if !strings.Contains(reasons[name], "deferred for fairness across priorities") {
			t.Errorf("%s reason = %q, want it to say it was deferred for fairness", name, reasons[name])
		}
	}
	if strings.Contains(reasons["low"], "deferred for fairness") || !strings.Contains(reasons["low"], "global limit") {
		t.Errorf("low reason = %q, want only the global limit", reasons["low"])
	}
}

package scheduler

import (
	"github.com/eyupio/zoomies/internal/store"
	"slices"
	"strings"
	"testing"
	"time"
)

func TestProvisioningControlsAndLimits(t *testing.T) {
	p := testPool("linux", "linux")
	j := queued("job", time.Second, "linux")
	snap := Snapshot{Now: now, Pools: []*store.Pool{p}, Hosts: []*store.Host{testHost("host_a", 10, 0)}, Jobs: []*store.Job{j}, Policy: testPolicy()}
	snap.Policy.ScaleUpDelay = time.Minute
	createsFor := func() int {
		n := 0
		for _, p := range Decide(snap).Pools {
			n += creates(p.Actions)
		}
		return n
	}
	if n := createsFor(); n != 0 {
		t.Fatalf("delay bypassed: %d", n)
	}
	j.ProvisionNow = true
	if n := createsFor(); n != 1 {
		t.Fatalf("run now did not bypass delay: %d", n)
	}
	for _, state := range []string{"paused", "deleted"} {
		j.Provisioning = state
		if n := createsFor(); n != 0 {
			t.Fatalf("%s created %d", state, n)
		}
	}
	j.Provisioning = ""
	p.MaxRunners = 0
	if n := createsFor(); n != 0 {
		t.Fatalf("run now bypassed pool maximum: %d", n)
	}
	p.MaxRunners = 10
	snap.Hosts[0].Capacity = 0
	if n := createsFor(); n != 0 {
		t.Fatalf("run now bypassed host capacity: %d", n)
	}
}

func TestProvisioningFairnessAcrossPassesAndPriority(t *testing.T) {
	a, b := testPool("a", "a"), testPool("b", "b")
	ja, jb := queued("a", time.Minute, "a"), queued("b", time.Minute, "b")
	snap := Snapshot{Now: now, Pools: []*store.Pool{b, a}, Jobs: []*store.Job{jb, ja}, Hosts: []*store.Host{testHost("host_a", 10, 0)}, Policy: testPolicy(), LastProvisioned: map[string]time.Time{a.ID: ago(time.Second), b.ID: ago(time.Minute)}}
	snap.Policy.MaxCreatesPerTick = 1
	winner := func() string {
		for _, p := range Decide(snap).Pools {
			if creates(p.Actions) > 0 {
				return p.PoolID
			}
		}
		return ""
	}
	if got := winner(); got != b.ID {
		t.Fatalf("least recently served pool: %s", got)
	}
	snap.LastProvisioned[b.ID] = now
	if got := winner(); got != a.ID {
		t.Fatalf("next pass did not rotate: %s", got)
	}
	jb.ProvisionNow = true
	if got := winner(); got != b.ID {
		t.Fatalf("run now not prioritised: %s", got)
	}
	a.Priority = 10
	if got := winner(); got != a.ID {
		t.Fatalf("run now bypassed pool priority: %s", got)
	}
}

func TestProvisioningOrderingIsStable(t *testing.T) {
	a, b, c := queued("a", time.Minute), queued("b", time.Minute), queued("c", time.Second)
	c.ProvisionNow = true
	got := sortedJobs([]*store.Job{b, c, a})
	if got[0] != c || got[1] != a || got[2] != b {
		t.Fatalf("ordering: %+v", got)
	}
}

func TestExecutionOrderPreservesFairAllocation(t *testing.T) {
	a, b := testPool("a", "a"), testPool("b", "b")
	a.MinRunners, b.MinRunners = 2, 2
	snap := Snapshot{Now: now, Pools: []*store.Pool{a, b}, Hosts: []*store.Host{testHost("host", 10, 0)}, Policy: testPolicy(), LastProvisioned: map[string]time.Time{a.ID: now}}
	snap.Policy.MaxCreatesPerTick = 4
	plan := Decide(snap)
	want := []string{b.ID, a.ID, b.ID, a.ID}
	if len(plan.Actions) != len(want) {
		t.Fatalf("actions: %+v", plan.Actions)
	}
	for i, a := range plan.Actions {
		if a.PoolID != want[i] {
			t.Fatalf("action %d: %s, want %s", i, a.PoolID, want[i])
		}
	}
	if plan.Pools[0].PoolID != a.ID {
		t.Fatal("display order changed")
	}
	a.Priority = 10
	plan = Decide(snap)
	if plan.Actions[0].PoolID != a.ID || plan.Actions[1].PoolID != a.ID {
		t.Fatal("execution lost priority tiers")
	}
}

// The order pools are served in has to be a total order, or which pool gets
// the one create a tight budget allows depends on how the caller happened to
// collect them rather than on who has waited. Here a pool with nothing queued
// but a minimum to keep warm sits between two with jobs: it beats the first on
// ID, loses to the second on ID, and the second beats the first on wait -- a
// cycle, so the winner was whichever pool the sort left in front. Every
// arrangement of the names, which is what sets the input order, must serve the
// pool whose job has waited longest.
func TestTheOldestWaitingPoolIsServedFirstWhateverOrderThePoolsArriveIn(t *testing.T) {
	names := []string{"n1", "n2", "n3"}
	for _, perm := range [][3]int{{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}} {
		t.Run(strings.Join([]string{names[perm[0]], names[perm[1]], names[perm[2]]}, "-"), func(t *testing.T) {
			recent := testPool(names[perm[0]], "recent")
			recent.ID = "pool_1"
			warm := testPool(names[perm[1]], "warm")
			warm.ID = "pool_2"
			warm.MinRunners = 1
			oldest := testPool(names[perm[2]], "oldest")
			oldest.ID = "pool_3"

			s := snap([]*store.Pool{recent, warm, oldest}, nil, []*store.Job{
				queued("j_recent", time.Minute, "recent"),
				queued("j_oldest", 10*time.Minute, "oldest"),
			}, []*store.Host{testHost("host_a", 10, 0)})
			s.Policy.MaxCreatesPerTick = 1

			var served []string
			for _, p := range Decide(s).Pools {
				if creates(p.Actions) > 0 {
					served = append(served, p.PoolID)
				}
			}
			if !slices.Equal(served, []string{"pool_3"}) {
				t.Fatalf("served %v, want only the pool whose job has waited longest (pool_3)", served)
			}
		})
	}
}

package scheduler

import (
	"github.com/eyupio/zoomies/internal/store"
	"testing"
	"time"
)

func TestReadinessPlacementRespectsFitAndStartupBacklog(t *testing.T) {
	for _, tc := range []struct {
		name  string
		busy  int
		small bool
		want  string
	}{
		{"faster history", 0, false, "a"},
		{"startup queue reverses preference", 3, false, "b"},
		{"history never overrides memory fit", 0, true, "b"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := limited("build", 2, 2048)
			a, b := sized("a", 8, 16, 32768, 100000), sized("b", 8, 16, 32768, 100000)
			if tc.small {
				a = sized("a", 8, 16, 1024, 100000)
			}
			rs := map[string][]*store.Runner{}
			for range tc.busy {
				rs[p.ID] = append(rs[p.ID], &store.Runner{HostID: "a", PoolID: p.ID, State: store.RunnerRegistering})
			}
			hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p}, rs, now)
			hs.preferReadiness = true
			hs.readiness = map[string]map[string]time.Duration{p.ID: {"a": 10 * time.Second, "b": 25 * time.Second}}
			got := hs.place(p, 1)
			if len(got) != 1 || got[0] != tc.want {
				t.Fatalf("placement=%v want %s", got, tc.want)
			}
		})
	}
}

func TestReadinessWithoutEvidenceFallsBackToHeadroom(t *testing.T) {
	p := limited("build", 2, 2048)
	a, b := sized("a", 4, 4, 8192, 100000), sized("b", 4, 16, 32768, 100000)
	hs := newHostSet([]*store.Host{a, b}, []*store.Pool{p}, nil, now)
	hs.preferReadiness = true
	if got := hs.place(p, 1); len(got) != 1 || got[0] != "b" {
		t.Fatalf("placement=%v", got)
	}
}

package scheduler

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/eyupio/zoomies/internal/store"
)

// Reservation is what one runner of a pool is charged against the host it is
// placed on. It is the admission half of the resource model: the reporting
// half taught agents to measure their machines, and this is what decides that
// the ninth 4 GB runner does not go on a 32 GB box.
//
// It is a charge, not an enforcement. What actually binds a runner is the
// cgroup limit the container backend applies from the same pool `resources`,
// and the process backend applies none at all -- so a reservation says what
// the fleet has promised away, and only the container backends make the
// promise true.
type Reservation struct {
	CPUs     float64
	MemoryMB int64
	DiskMB   int64
}

// cpuEpsilon absorbs the rounding of a share that does not divide evenly. Eight
// slots on a 30-CPU host are 3.75 each, which is exact, but seven are not, and
// a host must not refuse the last runner it has room for because the eighth
// subtraction left 2.7755575615628914e-16 of a CPU owing.
const cpuEpsilon = 1e-6

// comfortableRunnerCPUs and comfortableRunnerMemoryMB are what a container
// needs to do real work without crawling through a build, rather than merely
// enough to avoid being killed. They match the figures
// controller.overprovisionedSlotMemoryMB and its CPU counterpart judge a
// plain runner's slot against, so the two warnings never disagree about what
// "comfortable" means.
const (
	comfortableRunnerCPUs     = 1.0
	comfortableRunnerMemoryMB = 2048
)

// Reserve is what one runner of p costs on h.
//
// It is pure, and it is per field. A pool that sets a memory limit and no CPU
// limit has said something about memory and nothing about CPU, so the limit
// answers for memory and the fallback answers for CPU; charging zero for the
// half the operator left alone would let a fleet promise away a machine it had
// measured.
//
// The fallback is the host's own allocatable share per slot, and it is chosen
// so that nothing changes on upgrade: a host carrying only pools with no
// limits charges each runner exactly one slot's worth, so its capacity is what
// admits work, exactly as it did before any of this existed.
//
// Disk has no fallback. Free disk is a measurement rather than a budget, and
// dividing what is left into shares would turn every fill of the cache into a
// refusal to place work that had always placed. What guards it instead is the
// reserve floor: a pool that asks for disk is charged it, and a host at or
// below its reserve takes nothing.
//
// A docker-in-docker runner is two containers, and what it is charged follows
// what the two are given. A limit an operator typed says what the job may
// have; the daemon is given the same, so the pair is charged twice, and a host
// too small for what was typed says so. A fallback share is the machine cut
// into slots, and there the pair splits one slot between them -- see
// store.Resources.SplitWithDaemon -- so it is charged one.
//
// Both halves of that have to stay true together. Charging one share while
// giving each container a whole one is the bug this once had: a host read as
// half committed while its containers' quotas added up to every core it had,
// the daemon lost the reserve the arithmetic said was being kept for it, and
// creates timed out on a machine the fleet believed was idle. Giving the pair
// one share while charging two is the mirror of it, and is what an operator
// meets as a fleet that will not use the machines it has: eight slots that
// hold four runners, a page promising room the pass refuses, and an
// overcommit warning whose advice -- fewer slots -- makes it worse every time
// it is taken, down to one slot holding nothing at all.
func Reserve(p *store.Pool, h *store.Host) Reservation {
	alloc := h.Allocatable()
	res := Reservation{
		CPUs:     p.Resources.CPUs,
		MemoryMB: p.Resources.MemoryMB,
		DiskMB:   p.Resources.DiskGB * 1024,
	}
	cpuFromHost, memoryFromHost := res.CPUs <= 0, res.MemoryMB <= 0
	// A minimum above the slot share is a slot of the minimum's size: the
	// runner is given it and charged it, and the host holds fewer runners
	// than its slots rather than none -- see MinimumSlot.
	floor := MinimumSlot(p)
	if cpuFromHost {
		res.CPUs = max(share(alloc.CPUs, h.Capacity), floor.CPUs)
	}
	if memoryFromHost {
		res.MemoryMB = max(int64(share(float64(alloc.MemoryMB), h.Capacity)), floor.MemoryMB)
	}
	if p.DockerMode == store.DockerDinD {
		// Only what the operator typed doubles. A share is one slot, and the
		// pair is given one slot between them.
		if !cpuFromHost {
			res.CPUs *= 2
		}
		if !memoryFromHost {
			res.MemoryMB *= 2
		}
		// Disk has no fallback, so a figure here is always one somebody typed.
		res.DiskMB *= 2
	}
	return res
}

// RunnerCharge is what one live runner is charged on its host: what its row
// says it was given, where it was given less than its pool's standard size,
// and the pool's own charge otherwise.
//
// The row is the only place a reduced runner's size is written down. Charging
// it the standard instead would have the fleet believe a host it had filled
// with reduced runners was over-committed, and refuse the next one it had room
// for; charging the standard is right for every other runner, because that is
// what it was given.
func RunnerCharge(p *store.Pool, h *store.Host, r *store.Runner) Reservation {
	res := Reserve(p, h)
	if r == nil || (r.AllocationSource != store.AllocationReduced && r.AllocationSource != store.AllocationHistory) {
		return res
	}
	if r.AllocatedCPUs > 0 {
		res.CPUs = r.AllocatedCPUs * fieldFactor(p, p.Resources.CPUs > 0)
	}
	if r.AllocatedMemoryMB > 0 {
		res.MemoryMB = r.AllocatedMemoryMB * int64(fieldFactor(p, p.Resources.MemoryMB > 0))
	}
	return res
}

// fieldFactor is how many containers one field of a runner's size is given
// for: two for a docker-in-docker runner's typed figure, because the daemon is
// given the same limit, and one for a field taken from the host, which is one
// slot the pair shares -- the same distinction Reserve draws.
func fieldFactor(p *store.Pool, typed bool) float64 {
	if typed && p.DockerMode == store.DockerDinD {
		return 2
	}
	return 1
}

// MinimumReserve is the least one runner of p may be charged on h: the pool's
// minimum on each field that has one below its standard, and the standard on
// every other field. It is Reserve for a pool with no minimum.
//
// A field the pool leaves to the host has this host's slot share as its
// standard, raised to the minimum where the share is smaller (MinimumSlot), so
// the minimum is where a reduction stops and never a way up past the
// standard. And an automatic docker-in-docker slot is never cut below
// what it takes to split between a runner and its daemon (ShareFloor), which
// is the same line ShareTooSmall holds a whole slot to.
func MinimumReserve(p *store.Pool, h *store.Host) Reservation {
	res := Reserve(p, h)
	if !p.Resources.Reducible() {
		return res
	}
	floor := ShareFloor(p)
	if m := p.Resources.MinCPUs; m > 0 {
		typed := p.Resources.CPUs > 0
		v := m * fieldFactor(p, typed)
		if !typed {
			v = max(v, floor.CPUs)
		}
		res.CPUs = min(res.CPUs, v)
	}
	if m := p.Resources.MinMemoryMB; m > 0 {
		typed := p.Resources.MemoryMB > 0
		v := m * int64(fieldFactor(p, typed))
		if !typed {
			v = max(v, floor.MemoryMB)
		}
		res.MemoryMB = min(res.MemoryMB, v)
	}
	return res
}

// ReducedSize is what a runner of p is given on a host with only left to
// spare, where that is less than the pool's standard: as much of the standard
// as there is, never below the minimum. It returns the charge against the host
// and the limits each container is created with, and false when even the
// minimum does not fit.
//
// It gives the most the host can spare rather than the minimum, because the
// minimum is a floor the operator will accept, not a size they asked for: a
// 30 GB machine under a 32 GB pool with a 24 GB minimum should run the job
// with 30, not 24. CPU is rounded down to a hundredth of a core, so the charge
// never exceeds what is left.
//
// A field the pool leaves to the host is given explicitly here -- the share,
// or what is left of it -- because the runner is created at exactly what it
// is charged: a reduced runner's row is the only record of its size.
func ReducedSize(p *store.Pool, h *store.Host, left Reservation, known store.HostAllocation) (Reservation, store.Resources, bool) {
	floor := MinimumReserve(p, h)
	if !p.Resources.Reducible() || !fits(left, floor, known) {
		return Reservation{}, store.Resources{}, false
	}
	charge := Reserve(p, h)
	cpuFactor := fieldFactor(p, p.Resources.CPUs > 0)
	memFactor := int64(fieldFactor(p, p.Resources.MemoryMB > 0))
	if known.CPUsKnown && left.CPUs+cpuEpsilon < charge.CPUs && floor.CPUs < charge.CPUs {
		each := math.Floor(left.CPUs/cpuFactor*100+cpuEpsilon) / 100
		charge.CPUs = max(each*cpuFactor, floor.CPUs)
	}
	if known.MemoryKnown && left.MemoryMB < charge.MemoryMB && floor.MemoryMB < charge.MemoryMB {
		charge.MemoryMB = max(left.MemoryMB/memFactor*memFactor, floor.MemoryMB)
	}
	if !fits(left, charge, known) {
		return Reservation{}, store.Resources{}, false
	}
	grant := p.Resources
	grant.MinCPUs, grant.MinMemoryMB = 0, 0
	grant.CPUs = charge.CPUs / cpuFactor
	grant.MemoryMB = charge.MemoryMB / memFactor
	return charge, grant, true
}

// share is one slot's worth of a host-wide figure.
func share(total float64, capacity int) float64 {
	if capacity < 1 || total <= 0 {
		return 0
	}
	return total / float64(capacity)
}

// Reserved is what the live runners already on h have promised away.
//
// It is the same sum newHostSet seeds a pass with, and it is exported because
// the Hosts page has to show it: an operator can see what a machine is and
// what it has left, and without this cannot see what the fleet has committed
// on it -- which is the number that explains why a host with free slots is
// taking nothing.
//
// Only live rows count, exactly as the slot count does: the snapshot keeps
// failed runners so the Runners page can show them, and charging a host for a
// runner that is gone would shrink the fleet every time one failed.
//
// Disk is deliberately absent. Free disk is a measurement of the filesystem as
// it is now, so what the runners already there have written is in the figure
// already; adding their reservations to it would charge the same bytes twice.
func Reserved(h *store.Host, pools []*store.Pool, runners map[string][]*store.Runner) Reservation {
	var out Reservation
	if h == nil {
		return out
	}
	for _, p := range pools {
		if p == nil {
			continue
		}
		for _, r := range runners[p.ID] {
			if r == nil || r.HostID != h.ID || !r.State.Live() {
				continue
			}
			res := RunnerCharge(p, h, r)
			out.CPUs += res.CPUs
			out.MemoryMB += res.MemoryMB
		}
	}
	return out
}

// HostFits reports whether one runner of the pool would fit on an empty host:
// whether this is the size of machine the pool could ever run on, before
// anything running on it is counted.
//
// Room left on the host is separate, and is the scheduler's own accounting
// during a pass -- the same split HostCanRun already makes for slots.
func HostFits(h *store.Host, p *store.Pool) bool {
	if ShareTooSmall(h, p) != "" {
		return false
	}
	alloc := h.Allocatable()
	whole := Reservation{CPUs: alloc.CPUs, MemoryMB: alloc.MemoryMB, DiskMB: alloc.DiskMB}
	// A machine too small for the standard size can still take a runner at
	// the pool's minimum, which is what a minimum is for.
	return fits(whole, MinimumReserve(p, h), alloc)
}

// ShareTooSmall names the field whose slot share is below what a runner needs
// to be a runner, and is empty when the host can back this pool.
//
// It exists because the two halves of sizing are checked in different places
// and must not disagree. A figure an operator types is refused below a quarter
// of a core or 512 MB, because underneath those the runner binary is killed
// before it takes a job or crawls through one in a way that reads as a broken
// image. A pool that leaves its size to the host is given the host's own
// share, and nothing was checking that -- so a 32-slot capacity on an
// eight-core machine handed every runner 0.23 of a core, which the same
// operator would have been refused for typing.
//
// It is answered by refusing the placement rather than by rounding the share
// up. Rounding up is over-provisioning by another name: the whole point of the
// share is that the slots add up to the machine, and a floor applied to each
// of them adds up to more than there is. The host is cut into more slots than
// it has runners' worth of room, and the fix is the capacity, which
// HostShortfall says.
//
// A pool with a minimum on the field is the exception, and not a rounding:
// its operator said the least a runner may have, so a thinner share is raised
// to that and the runner is charged it (MinimumSlot). The charge is what keeps
// that honest -- the host admits as many runners as its machine covers, not as
// many as it has slots -- which is exactly what rounding without one did not.
//
// Only a pool that left the size to the host is asked, and only on a field the
// agent has measured: a fixed size answers for itself at the API, and a host
// that has measured nothing is placed by slots alone exactly as it was before
// any of this existed.
func ShareTooSmall(h *store.Host, p *store.Pool) string {
	if h == nil || p == nil || !p.Automatic() {
		return ""
	}
	alloc := h.Allocatable()
	share := HostShare(h)
	// A docker-in-docker runner is two containers sharing one slot, so the
	// slot has to carry two runners' worth of floor rather than one. Refusing
	// the host here is what keeps the split honest: a slot that cannot be
	// divided without starving the runner is not a slot this pool can use, and
	// saying so names the capacity to change -- where dividing it anyway would
	// hand the daemon whatever was left, which on a small enough slot is
	// nothing at all, and no limit is how a build takes the machine.
	//
	// A field with a minimum is never too small: its runners are given the
	// minimum where the share is less (MinimumSlot), so the host holds fewer
	// of them rather than none.
	need := ShareFloor(p)
	given := MinimumSlot(p)
	if alloc.CPUsKnown && given.CPUs <= 0 && share.CPUs < need.CPUs {
		return "cpu"
	}
	if alloc.MemoryKnown && given.MemoryMB <= 0 && share.MemoryMB < need.MemoryMB {
		return "memory"
	}
	return ""
}

// MinimumSlot is, on each field an automatic pool has a minimum for, the least
// one of its slots is given: the minimum per container, twice over for a
// runner that shares its slot with a Docker daemon. It is zero on a field with
// no minimum, and on a pool that typed its own size.
//
// A slot's share smaller than this is raised to it rather than refused. The
// minimum is the operator saying the least a runner of the pool may have, and
// a share under it used to leave the host out altogether -- so a runner killed
// for want of memory could not be given more by raising the minimum, only by
// lowering the host's capacity, which is a setting on another page for every
// pool on the host. The runner is charged what it is given, so the host
// admits as many of them as its machine covers and no more: slots and room
// are both honoured, and whichever runs out first binds.
//
// A share above the minimum is still what the runner is given. The minimum is
// the floor, never the size: a runner is given all of the slot it lands in.
func MinimumSlot(p *store.Pool) Reservation {
	if p == nil || !p.Automatic() {
		return Reservation{}
	}
	floor := ShareFloor(p)
	var out Reservation
	if p.Resources.MinCPUs > 0 {
		out.CPUs = floor.CPUs
	}
	if p.Resources.MinMemoryMB > 0 {
		out.MemoryMB = floor.MemoryMB
	}
	return out
}

// ShareFloor is the least one slot may be worth on a host this pool can use:
// what a runner needs to be one, or -- where the runner brings a daemon into
// the same slot -- what each of the two needs to keep up with its own half of
// the job, doubled into one figure for the slot they share.
//
// The two containers of a defaulted docker-in-docker pair are not judged by
// the bare minimum that only keeps a runner from being killed
// (store.MinRunnerCPUs, store.MinRunnerMemoryMB): stability over performance
// means each half has to clear what any runner needs to do real work, the
// same comfortableRunnerCPUs and comfortableRunnerMemoryMB a plain runner's
// slot is judged against. A slot too thin for that is refused rather than
// split into two containers that will not keep up -- see
// TestASplitTooThinForBothContainersIsRefused -- which trades density for a
// daemon that answers its creates.
//
// A minimum the operator typed replaces it on its field. The comfortable
// figure is a judgement made for a pool nobody sized; a pool whose operator
// said "never less than 1 GB a container" has been sized, and refusing a host
// whose share gives each container 1.4 GB would be overruling them -- which is
// how an automatic docker-in-docker pool with a minimum used to sit queued
// beside a 3 GB machine that could run it. The minimum is per container, so a
// pair's slot needs it twice; and it is never taken below what keeps a runner
// alive, which the API already refuses to store.
func ShareFloor(p *store.Pool) Reservation {
	floor := comfortFloor(p)
	if p == nil || !p.Automatic() {
		return floor
	}
	pair := 1.0
	if p.DockerMode == store.DockerDinD {
		pair = 2
	}
	if m := p.Resources.MinCPUs; m > 0 && p.Resources.CPUs <= 0 {
		floor.CPUs = max(m, store.MinRunnerCPUs) * pair
	}
	if m := p.Resources.MinMemoryMB; m > 0 && p.Resources.MemoryMB <= 0 {
		floor.MemoryMB = max(m, store.MinRunnerMemoryMB) * int64(pair)
	}
	return floor
}

// comfortFloor is ShareFloor for a pool nobody gave a minimum: the bare
// minimum for one runner, or a comfortable figure for each of a pair.
func comfortFloor(p *store.Pool) Reservation {
	if p != nil && p.DockerMode == store.DockerDinD && p.Automatic() {
		return Reservation{CPUs: comfortableRunnerCPUs * 2, MemoryMB: comfortableRunnerMemoryMB * 2}
	}
	return Reservation{CPUs: store.MinRunnerCPUs, MemoryMB: store.MinRunnerMemoryMB}
}

// fits is the one comparison, so that the empty-host question and the
// room-left-during-a-pass question can never drift apart. A figure the agent
// never measured constrains nothing: an agent that predates the fields places
// by slots alone, which is what keeps an upgrade from emptying a fleet.
func fits(left, want Reservation, known store.HostAllocation) bool {
	if known.DiskKnown {
		// A host at or below its disk reserve takes no runner at all, however
		// little the pool asks for. The reserve is the room the machine needs
		// to do the work -- an image layer, a checkout, a log -- and not a
		// budget to be spent down to nothing.
		if known.DiskMB <= 0 || left.DiskMB < want.DiskMB {
			return false
		}
	}
	if known.CPUsKnown && left.CPUs+cpuEpsilon < want.CPUs {
		return false
	}
	if known.MemoryKnown && left.MemoryMB < want.MemoryMB {
		return false
	}
	return true
}

// HostReduction says when a host can run p, but gives its runners less than
// the pool would get on a larger machine: an automatic pool whose share there
// is below the comfortable size and above the minimum its operator set, or a
// fixed pool whose standard does not fit and whose minimum does. An automatic
// pool whose minimum is above the share is said too: its runners there are
// given the minimum, and the host holds fewer of them than it has slots. It is
// empty otherwise.
//
// It is information, not a warning. The minimum is the operator saying what
// they will accept, and a runner at it is the pool working as configured; the
// sentence is there so the smaller runners on that host are not a surprise.
func HostReduction(h *store.Host, p *store.Pool) string {
	if h == nil || p == nil || !HostFits(h, p) {
		return ""
	}
	alloc := h.Allocatable()
	if p.Automatic() {
		share := HostShare(h)
		comfort := comfortFloor(p)
		per := ""
		if p.DockerMode == store.DockerDinD {
			per = ", split between the runner and its Docker daemon"
		}
		// A share under the minimum is raised to it, so the runners there are
		// not smaller -- the host holds fewer of them. That is the sentence,
		// because a host running three of an eight-slot pool is otherwise a
		// puzzle.
		given := MinimumSlot(p)
		switch {
		case alloc.MemoryKnown && given.MemoryMB > share.MemoryMB:
			return fmt.Sprintf("its slot share is %s of memory, less than this pool's minimum, so its runners there are given %s%s and it holds fewer of them than its %s",
				formatMB(share.MemoryMB), formatMB(given.MemoryMB), per, plural(h.Capacity, "slot"))
		case alloc.CPUsKnown && given.CPUs > share.CPUs+cpuEpsilon:
			return fmt.Sprintf("its slot share is %s CPU, less than this pool's minimum, so its runners there are given %s CPU%s and it holds fewer of them than its %s",
				formatCPUs(share.CPUs), formatCPUs(given.CPUs), per, plural(h.Capacity, "slot"))
		case alloc.MemoryKnown && share.MemoryMB < comfort.MemoryMB:
			return fmt.Sprintf("its slot share is %s of memory%s, less than the %s this pool's runners get room to work in on a larger machine; they run there at that share, above this pool's minimum",
				formatMB(share.MemoryMB), per, formatMB(comfort.MemoryMB))
		case alloc.CPUsKnown && share.CPUs < comfort.CPUs:
			return fmt.Sprintf("its slot share is %s CPU%s, less than the %s this pool's runners get room to work in on a larger machine; they run there at that share, above this pool's minimum",
				formatCPUs(share.CPUs), per, formatCPUs(comfort.CPUs))
		}
		return ""
	}
	if !p.Resources.Reducible() {
		return ""
	}
	whole := Reservation{CPUs: alloc.CPUs, MemoryMB: alloc.MemoryMB, DiskMB: alloc.DiskMB}
	if fits(whole, Reserve(p, h), alloc) {
		return ""
	}
	return "it is smaller than this pool's standard size, so its runners there get what the machine can spare -- never less than this pool's minimum"
}

// HostShortfall says why one runner of p could not fit on an empty h, in terms
// an operator can act on: what the machine has to place on, and what this pool
// is charged for a runner. It is empty when the runner would fit, so it is
// also the sentence for "why is this host not in the count".
//
// The charge is the number worth spelling out, because it is the one nothing
// on the pool shows. A pool that asks for 8 CPU and gives its jobs Docker in
// Docker is charged 16 on every host -- the sidecar gets the same limits -- so
// a 12-CPU machine refuses it, and an operator reading the pool's own "8 CPU"
// against a "12 vCPU" host card has no way to see why.
func HostShortfall(h *store.Host, p *store.Pool) string {
	// The share first, because it is a different fix from every case below:
	// nothing about the pool is wrong, and sending an operator to lower a
	// limit it does not set would send them to the wrong screen.
	if field := ShareTooSmall(h, p); field != "" {
		share := HostShare(h)
		need := ShareFloor(p)
		dind := p.DockerMode == store.DockerDinD
		pair := ""
		if dind {
			pair = ", because this pool's runners share their slot with a Docker daemon"
		}
		switch field {
		case "cpu":
			return fmt.Sprintf("it is set to %s, which divides its %s allocatable CPU into shares of %s each, and a runner needs at least %s to keep up with its own job%s",
				plural(h.Capacity, "slot"), formatCPUs(h.Allocatable().CPUs),
				formatCPUs(share.CPUs), formatCPUs(need.CPUs), pair)
		default:
			return fmt.Sprintf("it is set to %s, which divides its %s of allocatable memory into shares of %s each, and a runner is killed before it takes a job below %s%s",
				plural(h.Capacity, "slot"), formatMB(h.Allocatable().MemoryMB),
				formatMB(share.MemoryMB), formatMB(need.MemoryMB), pair)
		}
	}
	alloc := h.Allocatable()
	left := Reservation{CPUs: alloc.CPUs, MemoryMB: alloc.MemoryMB, DiskMB: alloc.DiskMB}
	want := MinimumReserve(p, h)
	if fits(left, want, alloc) {
		return ""
	}
	dind := p.DockerMode == store.DockerDinD
	switch {
	case alloc.DiskKnown && alloc.DiskMB <= 0:
		// The reserve floor, not a limit anyone typed. Sending an operator to
		// lower the pool's disk request would be sending them to the wrong
		// screen: this host refuses every pool until space is freed on it.
		return "its work directory is at or below its disk reserve, so it takes no runner of any pool"
	case alloc.DiskKnown && left.DiskMB < want.DiskMB:
		return fmt.Sprintf("it has %s of disk free to place on, and one runner of this pool is charged %s%s",
			formatMB(left.DiskMB), formatMB(want.DiskMB), charged(p.Resources.DiskGB > 0, dind))
	case alloc.CPUsKnown && left.CPUs+cpuEpsilon < want.CPUs:
		return fmt.Sprintf("it has %s CPU to place on, and one runner of this pool is charged %s%s",
			formatCPUs(left.CPUs), formatCPUs(want.CPUs), charged(p.Resources.CPUs > 0, dind)+minimumCharged(p, "cpu"))
	case alloc.MemoryKnown && left.MemoryMB < want.MemoryMB:
		return fmt.Sprintf("it has %s of memory to place on, and one runner of this pool is charged %s%s",
			formatMB(left.MemoryMB), formatMB(want.MemoryMB), charged(p.Resources.MemoryMB > 0, dind)+minimumCharged(p, "memory"))
	}
	return "it is too small for this pool's limits"
}

// charged explains the one case where the number an operator sees on the pool
// is not the number the host is charged. A defaulted field needs no such
// sentence even though it doubles too: its doubled share is capped at the
// machine it is being compared against, so it can never be what a host is too
// small for.
func charged(set, dind bool) string {
	if set && dind {
		return ", twice what it asks for, because a docker-in-docker runner is charged for its sidecar too"
	}
	return ""
}

// minimumCharged names the pool's own minimum where it is what a runner of an
// automatic pool is charged, because that is a figure the operator set and can
// lower -- and nothing else in the sentence says where the charge came from.
func minimumCharged(p *store.Pool, field string) string {
	floor := MinimumSlot(p)
	pair := ""
	if p.DockerMode == store.DockerDinD {
		pair = ", twice over for a runner and its Docker daemon, which share one slot"
	}
	switch {
	case field == "cpu" && floor.CPUs > 0:
		return fmt.Sprintf(", this pool's minimum of %s CPU a container%s", formatCPUs(max(p.Resources.MinCPUs, store.MinRunnerCPUs)), pair)
	case field == "memory" && floor.MemoryMB > 0:
		return fmt.Sprintf(", this pool's minimum of %s a container%s", formatMB(max(p.Resources.MinMemoryMB, store.MinRunnerMemoryMB)), pair)
	}
	return ""
}

// FormatCPUs is formatCPUs for the problems that quote a host's share, so the
// figure an operator reads there is rendered by the one function that renders
// it everywhere else.
func FormatCPUs(v float64) string { return formatCPUs(v) }

// formatCPUs writes a CPU count the way the pool form takes one: whole where
// it is whole, and a share where the host's capacity did not divide evenly.
// Two decimals is where a share stops being worth reading -- the rounding this
// absorbs is the same one cpuEpsilon exists for.
func formatCPUs(v float64) string {
	s := strings.TrimRight(strings.TrimRight(strconv.FormatFloat(v, 'f', 2, 64), "0"), ".")
	if s == "" || s == "-" {
		return "0"
	}
	return s
}

// formatMB writes a size in the unit an operator would say it in.
func formatMB(mb int64) string {
	if mb >= 1024 && mb%1024 == 0 {
		return strconv.FormatInt(mb/1024, 10) + " GB"
	}
	if mb >= 1024 {
		return strconv.FormatFloat(float64(mb)/1024, 'f', 1, 64) + " GB"
	}
	return strconv.FormatInt(mb, 10) + " MB"
}

// HostRoom is how many runners of p an empty h could hold, and which of the
// machine's figures ran out first.
//
// It is the arithmetic behind "this host has room for four of these", and it
// is the scheduler's rather than the browser's for the same reason HostFits
// is: the charge a runner carries is not the figure on the pool -- a
// docker-in-docker slot is charged for its sidecar too, and an unmeasured
// field constrains nothing -- and a count worked out from the pool's own
// numbers would disagree with where the fleet actually places runners.
//
// The slot count is part of the answer, not a separate one: a host set to six
// slots holds six runners however much machine is left over, and a host whose
// slots outrun its machine is the overload this function exists to show. Both
// are returned, so a caller can say which is binding.
type HostRoom struct {
	// Slots is what the operator set, less any active throttle: the ceiling
	// the scheduler would honour whatever the machine could take.
	Slots int
	// Fits is how many runners of this size the machine itself has room for,
	// ignoring the slot count. It is zero on a host too small for one.
	Fits int
	// Room is the smaller of the two, which is what the pool can actually
	// expect from this host.
	Room int
	// LimitedBy names what ran out: "slots", "cpu", "memory", "disk", or ""
	// where the host has measured nothing and only its slots bind.
	LimitedBy string
}

// HostRoomFor counts the room on an empty host. Live runners are deliberately
// not subtracted: this answers "how big is this machine, in runners of this
// pool", which is the question a pool's size and a host's capacity are chosen
// against, and it does not change every time a job starts.
func HostRoomFor(h *store.Host, p *store.Pool) HostRoom {
	out := HostRoom{Slots: h.EffectiveCapacity()}
	// A host cut into shares too small to run a runner holds none of this
	// pool, whatever its slot count says. Reporting the slot count here would
	// promise room the pass refuses.
	if field := ShareTooSmall(h, p); field != "" {
		out.Fits, out.Room, out.LimitedBy = 0, 0, field
		return out
	}
	alloc := h.Allocatable()
	// The same gate fits() applies: a host at or below its disk reserve takes
	// no runner of any pool, so a pool that asks for no disk still has no room
	// here. Skipping it left the pool page and pool.max_above_room counting
	// runners the pass will never place.
	if alloc.DiskKnown && alloc.DiskMB <= 0 {
		out.Fits, out.Room, out.LimitedBy = 0, 0, "disk"
		return out
	}
	want := Reserve(p, h)

	fits := -1
	limit := ""
	consider := func(n int, by string) {
		if fits == -1 || n < fits {
			fits, limit = n, by
		}
	}
	if alloc.CPUsKnown && want.CPUs > 0 {
		consider(int((alloc.CPUs+cpuEpsilon)/want.CPUs), "cpu")
	}
	if alloc.MemoryKnown && want.MemoryMB > 0 {
		consider(int(alloc.MemoryMB/want.MemoryMB), "memory")
	}
	// Disk only where the pool asks for it. Free disk is a measurement rather
	// than a budget -- see Reserve -- so dividing what is left into runners
	// would put a machine's cache on the pool's account.
	if alloc.DiskKnown && want.DiskMB > 0 {
		consider(int(alloc.DiskMB/want.DiskMB), "disk")
	}
	// A pool with a minimum runs one more runner than the standard count
	// wherever what is left after the standard ones still covers the minimum,
	// because that is what the pass places: the standard wherever it fits, and
	// then one runner given all the host can spare. Only one -- a reduced
	// runner takes the whole remainder, so there is never a second behind it.
	// Counting the standard alone called a host the pool runs on one it cannot
	// use; counting every runner at the minimum promised runners the pass
	// never makes.
	if fits >= 0 && MinimumReserve(p, h) != want {
		n := float64(fits)
		rest := Reservation{
			CPUs:     alloc.CPUs - n*want.CPUs,
			MemoryMB: alloc.MemoryMB - int64(fits)*want.MemoryMB,
			DiskMB:   alloc.DiskMB - int64(fits)*want.DiskMB,
		}
		if _, _, ok := ReducedSize(p, h, rest, alloc); ok {
			fits++
		}
	}
	if fits == -1 {
		// Nothing measured: the host places by slots alone, exactly as it did
		// before any of this existed.
		out.Fits, out.Room, out.LimitedBy = out.Slots, out.Slots, ""
		return out
	}
	out.Fits = max(fits, 0)
	out.Room = min(out.Fits, out.Slots)
	out.LimitedBy = limit
	if out.Slots < out.Fits {
		out.LimitedBy = "slots"
	}
	return out
}

package scheduler

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// sized is a host that has told the fleet how big it is: CPUs, memory and the
// free disk behind its work directory, which is what the reporting half of
// this work taught agents to measure.
func sized(id string, capacity, cpus int, memoryMB, diskFreeMB int64) *store.Host {
	h := testHost(id, capacity, 0)
	h.CPUs = cpus
	h.MemoryMB = memoryMB
	h.DiskTotalMB = diskFreeMB * 2
	h.DiskFreeMB = diskFreeMB
	// A measured host whose daemon can apply every limit, which is what a
	// rootful Docker on cgroup v2 reports and the shape most tests want.
	h.BackendInfo = store.HostBackends{{Kind: store.BackendDocker, Available: true,
		Limits: store.LimitSupport{Known: true, CPU: true, Memory: true, Pids: true}}}
	return h
}

// limited is a pool that says what one of its runners may consume.
func limited(name string, cpus float64, memoryMB int64) *store.Pool {
	p := testPool(name, name)
	p.Resources = store.Resources{CPUs: cpus, MemoryMB: memoryMB}
	return p
}

// hostFor is the machine that leaves want MB allocatable once its own reserve
// is held back. The reserve scales with the machine, so it cannot be added as
// a constant: a test that wrote 32*1024+512 would be describing a floor that
// only applies to small hosts.
func hostFor(want int64) int64 {
	total := want
	for range 8 {
		got := total - (&store.Host{MemoryMB: total}).MemoryReserve()
		if got == want {
			return total
		}
		total += want - got
	}
	return total
}

// The headline case for the whole reservation model, and the one an operator
// would recognise: a host advertises 32 GB, a pool asks for 4 GB a runner, and
// the ninth runner is the one that would have been killed rather than run.
func TestAHostAdmitsWhatItsMemoryCoversAndRefusesTheNext(t *testing.T) {
	// Capacity is deliberately far above what memory allows, so that only the
	// memory rule can be what stops the ninth. The machine is sized so that
	// exactly 32 GB is left after the reserve, which scales with it: a
	// twentieth of the whole, capped, and never under the flat floor.
	h := sized("host_a", 32, 32, hostFor(32*1024), 500*1024)
	p := limited("big", 0, 4096)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	got := hs.place(p, 12)
	if len(got) != 8 {
		t.Fatalf("placed %d runners on a 32 GB host at 4 GB each, want 8", len(got))
	}
	if more := hs.place(p, 1); len(more) != 0 {
		t.Errorf("the ninth runner was placed on a host with nothing left: %v", more)
	}
}

// Two pools drawing on one host is the case a per-pool check would get wrong:
// each fits on its own, and the host cannot carry both. The slot model already
// had this property and the resource model has to keep it, or the second pool
// is promised memory the first has already been given.
func TestTwoPoolsCannotOversubscribeOneHostsMemory(t *testing.T) {
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	first := limited("first", 0, 6*1024)
	second := limited("second", 0, 4*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{first, second}, nil, now)
	if got := hs.place(first, 1); len(got) != 1 {
		t.Fatalf("the first pool was refused a host with 8 GB free: %v", got)
	}
	// 2 GB is left and the second pool wants 4.
	if got := hs.place(second, 1); len(got) != 0 {
		t.Errorf("the second pool was promised memory the first already has: %v", got)
	}
}

// A docker-in-docker pool's build runs in a sidecar that the backend gives the
// same limits as the runner, so the host carries twice what the pool asked
// for. Charging it once would let a fleet promise away a machine twice over.
func TestADockerInDockerRunnerIsChargedForItsSidecar(t *testing.T) {
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	p := limited("dind", 0, 4096)
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	got := hs.place(p, 4)
	if len(got) != 1 {
		t.Fatalf("placed %d dind runners on an 8 GB host at 4 GB each, want 1", len(got))
	}

	// The same pool without the sidecar fits twice, which is what says the
	// difference above came from the sidecar and not from the arithmetic.
	plain := limited("plain", 0, 4096)
	hs = newHostSet([]*store.Host{sized("host_b", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)}, []*store.Pool{plain}, nil, now)
	if got := hs.place(plain, 4); len(got) != 2 {
		t.Fatalf("placed %d plain runners, want 2", len(got))
	}
}

// A slot is one runner, whatever the runner brought with it.
//
// A defaulted docker-in-docker pair splits one slot between its two containers
// -- store.Resources.SplitWithDaemon -- so four slots are four runners, the
// same as any other pool. The arithmetic that used to charge two shares for
// such a pair is why an operator was told a twelve-core host with four slots
// had room for two, and then told to halve its capacity to match; the advice
// converged on one slot, which held nothing.
func TestADefaultedDockerInDockerPairSharesOneSlot(t *testing.T) {
	h := sized("host_a", 4, 12, 32*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 4); len(got) != 4 {
		t.Fatalf("placed %d defaulted dind runners on a 12-CPU host with 4 slots, want 4", len(got))
	}

	// A pool that typed its own figures is charged for both containers, which
	// is what says the slot -- not the sidecar -- is what changed above: the
	// daemon is given what the job was promised, so the host pays for it.
	// 2 CPU typed is charged 4 with the daemon, so an 11-CPU machine takes two
	// rather than the five it would take at the figure on the pool.
	typed := limited("typed", 2, 4*1024)
	typed.DockerMode = store.DockerDinD
	hs = newHostSet([]*store.Host{sized("host_b", 4, 12, 32*1024, 500*1024)}, []*store.Pool{typed}, nil, now)
	if got := hs.place(typed, 4); len(got) != 2 {
		t.Fatalf("placed %d dind runners of 2 typed CPU on a 12-CPU host, want 2 at twice the charge", len(got))
	}
}

// The invariant underneath that number, stated in the two functions that have
// to agree: what a host is charged for a runner is never less than what its
// backend is told to give one. A charge below the limit is a host promising
// away room it has already handed to a cgroup, which is how a machine reading
// as half committed runs out of cores.
func TestAHostIsNeverChargedLessThanItsRunnersAreGiven(t *testing.T) {
	for _, capacity := range []int{1, 2, 3, 4, 8} {
		for _, mode := range []store.DockerMode{store.DockerNone, store.DockerDinD} {
			h := sized("host_a", capacity, 12, 32*1024, 500*1024)
			p := testPool("builders", "builders")
			p.DockerMode = mode
			// A dind pool's spec creates two containers with these limits;
			// every other pool creates one.
			containers := 1.0
			if mode == store.DockerDinD {
				containers = 2
			}
			given, source := Allocation(p, h, true)
			charge := Reserve(p, h)
			// What the backend hands out: one container of the given limits,
			// or -- where those came from the host's slot and the pool brings
			// a daemon -- the two halves that slot is split into.
			handed := given
			if mode == store.DockerDinD {
				if source == store.AllocationFromHost {
					runner, daemon := given.SplitWithDaemon()
					handed = store.Resources{
						CPUs:     runner.CPUs + daemon.CPUs,
						MemoryMB: runner.MemoryMB + daemon.MemoryMB,
					}
				} else {
					handed = store.Resources{CPUs: containers * given.CPUs, MemoryMB: int64(containers) * given.MemoryMB}
				}
			}
			if charge.CPUs+cpuEpsilon < handed.CPUs {
				t.Errorf("capacity %d, %s: charged %v CPU and handed out %v across its containers",
					capacity, mode, charge.CPUs, handed.CPUs)
			}
			if charge.MemoryMB < handed.MemoryMB {
				t.Errorf("capacity %d, %s: charged %d MB and handed out %d MB across its containers",
					capacity, mode, charge.MemoryMB, handed.MemoryMB)
			}
		}
	}
}

// A host with one slot must still be able to run the pool it was joined for,
// as long as that one slot is big enough to give both containers of the pair
// a comfortable share. Charging two shares for a defaulted pair would refuse
// every one of them on every small host in the fleet -- an upgrade that
// empties a fleet rather than protecting it -- so the charge stays one share;
// what changed is that the share itself now has to clear a real floor. See
// TestASplitTooThinForBothContainersIsRefused for the host this one is not.
func TestASingleSlotHostStillPlacesAWellSizedDefaultedDockerInDockerRunner(t *testing.T) {
	h := sized("host_ample", 1, 4, 8*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	if !HostFits(h, p) {
		t.Fatalf("a one-slot host with room for both containers was refused the pool it exists for: %s", HostShortfall(h, p))
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 2); len(got) != 1 {
		t.Fatalf("placed %d runners on a one-slot host, want 1", len(got))
	}
}

// Stability over performance: a defaulted docker-in-docker pair still splits
// one slot between a runner and the daemon that builds for it, and a slot too
// thin to give both of them a comfortable share -- a core and 2 GB each, not
// half of the bare minimum that only keeps a runner from being killed -- is
// refused rather than handed to a daemon that cannot keep up with its own
// job. That daemon timing out on a create is the backend_busy fault this
// refusal exists to prevent, not merely warn about after the fact.
func TestASplitTooThinForBothContainersIsRefused(t *testing.T) {
	// 2 CPUs less the half-core floor is 1.5, which split between a runner
	// and its daemon is 0.75 each: enough to avoid store.MinRunnerCPUs, not
	// enough to keep a nested dockerd answering under load.
	h := sized("host_thin", 1, 2, 4*1024, 500*1024)
	p := testPool("builders", "builders")
	p.DockerMode = store.DockerDinD

	if field := ShareTooSmall(h, p); field != "cpu" {
		t.Fatalf("ShareTooSmall = %q, want cpu: 1.5 allocatable CPU split between a runner and its daemon is not a comfortable core each", field)
	}
	if HostFits(h, p) {
		t.Error("a one-slot host with 1.5 CPU to split between two containers was accepted for a pair that needs a core each")
	}
	why := HostShortfall(h, p)
	for _, want := range []string{"1.5 allocatable CPU", "needs at least 2", "Docker daemon"} {
		if !strings.Contains(why, want) {
			t.Errorf("HostShortfall = %q, want it to mention %q", why, want)
		}
	}
	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 2); len(got) != 0 {
		t.Fatalf("placed %d runners on a host too thin for the pair, want 0: %v", len(got), got)
	}
}

// The upgrade property, and the one that decides whether this change is safe
// to ship: a host carrying only pools that set no limits admits exactly what
// its capacity admitted before any of this existed. The fallback share is what
// makes that true -- each runner is charged one slot's worth of the machine,
// so the slot count is still what runs out.
func TestAHostOfUnlimitedPoolsStillAdmitsItsCapacity(t *testing.T) {
	for _, capacity := range []int{1, 3, 4, 7, 8} {
		h := sized("host_a", capacity, 30, 30*1024, 500*1024)
		p := testPool("unlimited", "unlimited")

		hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
		got := hs.place(p, capacity+3)
		if len(got) != capacity {
			t.Errorf("capacity %d admitted %d runners; the upgrade changed what a host takes", capacity, len(got))
		}
	}
}

// What the fallback share is actually for. The upgrade property above holds
// with or without it -- a pool charged nothing is bounded by slots, and so is
// a pool charged one slot's worth -- so the case that separates them is a host
// carrying both kinds at once. An unlimited pool that costs nothing lets a
// fleet hand the same memory to a pool that asked for it by name.
func TestAnUnlimitedPoolStillSpendsTheMemoryItTakes(t *testing.T) {
	h := sized("host_a", 2, 8, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	unlimited := testPool("unlimited", "unlimited")
	named := limited("named", 0, 6*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{unlimited, named}, nil, now)
	if got := hs.place(unlimited, 1); len(got) != 1 {
		t.Fatalf("the unlimited pool was refused an empty host: %v", got)
	}
	// Half the machine is one slot's worth and is now spoken for, so the 6 GB
	// pool does not fit beside it even though a slot is free.
	if got := hs.place(named, 1); len(got) != 0 {
		t.Errorf("6 GB was promised on a host with 4 GB left: %v", got)
	}
}

// An agent that predates the resource fields reports nothing, and nothing is
// not zero. Reading an unmeasured host as an empty one would refuse every
// placement on it, which on a fleet mid-upgrade is every host.
func TestAHostThatReportedNoResourcesIsStillPlacedBySlots(t *testing.T) {
	h := testHost("host_old", 3, 0) // no CPUs, no memory, no disk
	p := limited("big", 8, 64*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 5); len(got) != 3 {
		t.Fatalf("placed %d runners on an unmeasured host with 3 slots, want 3: %v", len(got), got)
	}
}

// The reservation is rebuilt from the runner rows on every pass -- there is no
// second table holding it -- so which rows count is the whole of the
// arithmetic. Live rows count and terminal ones do not, exactly as the host's
// own slot count does: a failed runner is not holding any memory, and charging
// the host for it would shrink the fleet a little with every failure.
func TestOnlyLiveRunnersHoldAReservation(t *testing.T) {
	p := limited("big", 0, 4096)
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024)
	// One live runner is holding 4 GB; the failed and removed rows are not.
	h.ActiveRunners = 1
	runners := map[string][]*store.Runner{p.ID: {
		onHost(testRunner("r_live", p, store.RunnerBusy, 0), "host_a"),
		onHost(testRunner("r_failed", p, store.RunnerFailed, 0), "host_a"),
		onHost(testRunner("r_gone", p, store.RunnerRemoved, 0), "host_a"),
	}}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	if got := hs.place(p, 3); len(got) != 1 {
		t.Fatalf("placed %d runners beside one live 4 GB runner on an 8 GB host, want 1: %v", len(got), got)
	}
}

// Disk is a gate rather than a budget: a host with less free space than its
// reserve takes no runner at all, whatever the pool asks for, because the
// reserve is the room the machine needs to do the work rather than something
// to spend down. Nothing evicts to make room -- retention is ZF-105's.
func TestAHostBelowItsDiskReserveTakesNothing(t *testing.T) {
	full := sized("host_full", 4, 16, 16*1024, store.MinHostReserveDiskMB-1)
	roomy := sized("host_roomy", 4, 16, 16*1024, 200*1024)
	p := testPool("unlimited", "unlimited")

	hs := newHostSet([]*store.Host{full, roomy}, []*store.Pool{p}, nil, now)
	for _, id := range hs.place(p, 4) {
		if id == "host_full" {
			t.Fatalf("a runner was placed on a host below its disk reserve")
		}
	}

	// And the operator is told which resource it was, because "no capacity"
	// would send them to wait for a job that finishing will not help: a runner
	// leaves its caches behind on purpose.
	only := newHostSet([]*store.Host{full}, []*store.Pool{p}, nil, now)
	b := only.why(p)
	if !strings.Contains(b.what, "low on disk") {
		t.Errorf("the reason does not name the disk: %q", b.what)
	}
	if !strings.Contains(b.fix, "free space") {
		t.Errorf("the fix does not say what to free: %q", b.fix)
	}
}

// A machine too small for one runner is a different answer from a machine that
// is busy, and an operator told to wait for the second when they have the
// first waits for ever.
func TestAHostTooSmallForThePoolSaysSoRatherThanSayingItIsFull(t *testing.T) {
	h := sized("host_small", 4, 4, 4*1024, 200*1024)
	p := limited("huge", 0, 32*1024)

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	b := hs.why(p)
	if !strings.Contains(b.what, "too small for this pool's limits") {
		t.Errorf("the reason does not say the machine is too small: %q", b.what)
	}
	if b.atCapacity {
		t.Error("a host too small for the pool was reported as merely busy")
	}
	if !strings.Contains(b.fix, "lower this pool's") {
		t.Errorf("the fix does not name the pool's own limits: %q", b.fix)
	}
}

// The other half of that distinction: a host large enough for the pool that
// has already promised its memory away is short of memory, not too small, and
// waiting is exactly the right advice.
func TestAHostWhoseMemoryIsSpentSaysItIsShortOfMemory(t *testing.T) {
	p := limited("big", 0, 6*1024)
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 200*1024)
	h.ActiveRunners = 1
	runners := map[string][]*store.Runner{p.ID: {onHost(testRunner("r1", p, store.RunnerBusy, 0), "host_a")}}

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, runners, now)
	b := hs.why(p)
	if !strings.Contains(b.what, "short of memory") {
		t.Errorf("the reason does not name memory: %q", b.what)
	}
	if strings.Contains(b.what, "too small") {
		t.Errorf("a host that fits the pool was called too small: %q", b.what)
	}
}

// HostCanRun is the one placement rule, so the wizard's count, the
// capacity-demand signal and image prewarming inherit the fit without asking
// for it. A host that cannot hold one runner of the pool is not a host that
// can run it, whatever else is true of it.
func TestHostCanRunAsksWhetherARunnerFits(t *testing.T) {
	small := sized("host_small", 4, 2, 2*1024, 200*1024)
	big := sized("host_big", 4, 16, 32*1024, 200*1024)
	p := limited("huge", 0, 16*1024)

	if HostCanRun(small, p, now) {
		t.Error("a host with 2 GB was offered a pool that reserves 16")
	}
	if !HostCanRun(big, p, now) {
		t.Error("a host with 32 GB was refused a pool that reserves 16")
	}
}

// The reserve is the operator's, and an agent reports what it sees rather than
// what it may have: memory an operator held back for the machine is not
// memory the fleet may promise to a job.
func TestTheOperatorsReserveIsHeldBackFromPlacement(t *testing.T) {
	p := limited("big", 0, 4096)
	h := sized("host_a", 8, 16, 12*1024, 200*1024)
	h.ReserveMemoryMB = 8 * 1024

	hs := newHostSet([]*store.Host{h}, []*store.Pool{p}, nil, now)
	if got := hs.place(p, 3); len(got) != 1 {
		t.Fatalf("placed %d runners in the 4 GB left after an 8 GB reserve, want 1: %v", len(got), got)
	}
}

// onHost puts a test runner somewhere other than the helper's default host.
func onHost(r *store.Runner, hostID string) *store.Runner {
	r.HostID = hostID
	return r
}

// The case that sent an operator to this function: the wizard's placement step
// counts two Linux amd64 hosts, its review step counts one, and the 12-CPU
// machine is the one that vanished -- because docker-in-docker charges its
// sidecar too, so an 8-CPU pool costs 16 and the "8 CPU" on the pool is not a
// number anything on screen can be compared against.
func TestTheShortfallNamesTheDoubledDockerInDockerCharge(t *testing.T) {
	h := sized("host_a", 8, 12, 31*1024, 500*1024)
	p := limited("builders", 8, 0)
	p.DockerMode = store.DockerDinD

	// 11.4 rather than 12: the floor under the CPU reserve keeps a
	// twentieth of the machine for the daemon, and the shortfall names what
	// may actually be placed on, which is the figure the pass fits against.
	got := HostShortfall(h, p)
	for _, want := range []string{"11.4 CPU", "charged 16", "sidecar"} {
		if !strings.Contains(got, want) {
			t.Errorf("HostShortfall = %q, want it to mention %q", got, want)
		}
	}
	// The same pool without the sidecar fits the same machine, which is what
	// makes the doubling worth naming rather than describing as a limit.
	p.DockerMode = store.DockerNone
	if got := HostShortfall(h, p); got != "" {
		t.Errorf("HostShortfall = %q for a pool that fits", got)
	}
}

// A host that never measured itself constrains nothing, so it is placed by its
// slot count alone. That is deliberate -- it is what stops an upgrade emptying
// a fleet -- and the shortfall has to agree with it, or the wizard would name a
// size problem the scheduler does not have.
func TestAnUnmeasuredHostHasNoShortfall(t *testing.T) {
	h := testHost("host_a", 6, 0)
	p := limited("builders", 64, 512*1024)

	if got := HostShortfall(h, p); got != "" {
		t.Errorf("HostShortfall = %q for a host that has reported no size", got)
	}
}

// Disk is the dimension with no fallback and its own floor, so a pool that asks
// for more of it than a host has left is refused in the host's terms rather
// than in the pool's.
func TestTheShortfallNamesTheDiskAPoolAskedFor(t *testing.T) {
	h := sized("host_a", 8, 8, 32*1024, 40*1024)
	p := limited("archivers", 0, 0)
	p.Resources = store.Resources{DiskGB: 200}

	got := HostShortfall(h, p)
	if !strings.Contains(got, "disk") || !strings.Contains(got, "charged 200 GB") {
		t.Errorf("HostShortfall = %q, want the disk the pool asked for", got)
	}
}

// A host cut into more slots than it has runners' worth of room cannot back a
// pool that leaves its size to the host.
//
// The two halves of sizing are checked in different places, and this is what
// keeps them agreeing. A figure an operator types is refused below a quarter
// of a core; the share a host hands out was not checked at all, so a 32-slot
// capacity on an eight-core machine gave every runner 0.23 of a core -- which
// the same operator would have been refused for typing, and which the runner
// binary cannot keep up with.
//
// It is answered by refusing the host rather than by rounding the share up.
// Rounding up is over-provisioning by another name: the slots are meant to add
// up to the machine, and a floor applied to each of them adds up to more than
// there is.
func TestAHostCutTooFineCannotBackAnAutomaticPool(t *testing.T) {
	automatic := &store.Pool{Name: "zoomies-auto"}

	// Eight cores, 32 slots. Allocatable is 8 - max(0.5, 0.4) = 7.5, so each
	// slot is 0.23 -- under the floor.
	tooFine := &store.Host{
		Name: "sliced-1", Capacity: 32, CPUs: 8, MemoryMB: 65536,
	}
	if field := ShareTooSmall(tooFine, automatic); field != "cpu" {
		t.Errorf("ShareTooSmall = %q, want cpu: 32 slots on eight cores is 0.23 each", field)
	}
	if HostFits(tooFine, automatic) {
		t.Error("a host handing out 0.23 of a core per runner was accepted")
	}
	why := HostShortfall(tooFine, automatic)
	if !strings.Contains(why, "slot") || !strings.Contains(why, "0.23") {
		t.Errorf("the shortfall does not say the slot count is the cause: %q", why)
	}
	// The room agrees with the placement, or the page promises slots the pass
	// refuses.
	if room := HostRoomFor(tooFine, automatic); room.Room != 0 || room.LimitedBy != "cpu" {
		t.Errorf("room = %+v, want none, limited by cpu", room)
	}

	// The same machine at four slots is 1.87 each, which is fine.
	sensible := &store.Host{Name: "sliced-1", Capacity: 4, CPUs: 8, MemoryMB: 65536}
	if field := ShareTooSmall(sensible, automatic); field != "" {
		t.Errorf("ShareTooSmall = %q on a host handing out 1.87 of a core, want none", field)
	}
	if !HostFits(sensible, automatic) {
		t.Error("a host handing out 1.87 of a core per runner was refused")
	}

	// Memory answers for itself: 64 slots on 32 GB is 512 MB each, and 128 is
	// 256 -- under the floor with CPU to spare.
	thin := &store.Host{Name: "thin-1", Capacity: 128, CPUs: 128, MemoryMB: 32768}
	if field := ShareTooSmall(thin, automatic); field != "memory" {
		t.Errorf("ShareTooSmall = %q, want memory", field)
	}

	// A pool that names its own size answers for it at the API, so the share
	// is not its question and the floor is not applied to it here.
	fixed := &store.Pool{Name: "zoomies-fixed", Resources: store.Resources{CPUs: 2, MemoryMB: 4096}}
	if field := ShareTooSmall(tooFine, fixed); field != "" {
		t.Errorf("ShareTooSmall = %q for a pool that sets its own size, want none", field)
	}

	// A host that has measured nothing is placed by slots alone, exactly as it
	// was before any of this existed. Refusing it would empty a fleet the
	// moment it upgraded.
	unmeasured := &store.Host{Name: "old-1", Capacity: 32}
	if field := ShareTooSmall(unmeasured, automatic); field != "" {
		t.Errorf("ShareTooSmall = %q on a host that has measured nothing, want none", field)
	}
	if !HostFits(unmeasured, automatic) {
		t.Error("a host that has measured nothing was refused")
	}
}

package scheduler

import (
	"testing"

	"github.com/eyupio/zoomies/internal/store"
)

// The room is the machine, not the slot count -- and where the two disagree,
// which one wins is the whole answer.
//
// A host set to more slots than its machine can back is the failure that looks
// like health: the free slots are counted on every page, and every create for
// one of them is refused for want of memory. A host set to fewer is an
// operator's own ceiling and is honoured as one.
func TestHostRoomIsTheSmallerOfTheMachineAndTheSlots(t *testing.T) {
	tests := []struct {
		name      string
		host      *store.Host
		pool      *store.Pool
		wantFits  int
		wantRoom  int
		wantLimit string
	}{
		{
			name: "the machine runs out first",
			// Ten cores less the half-core floor is 9.5, which is four
			// two-core runners; twenty gigabytes less 512 MB is four more.
			host:      sized("host_a", 8, 10, 20*1024, 500*1024),
			pool:      limited("standard", 2, 4096),
			wantFits:  4,
			wantRoom:  4,
			wantLimit: "cpu",
		},
		{
			name:      "the operator's ceiling is lower and is honoured",
			host:      sized("host_b", 2, 10, 20*1024, 500*1024),
			pool:      limited("standard", 2, 4096),
			wantFits:  4,
			wantRoom:  2,
			wantLimit: "slots",
		},
		{
			name:      "memory is the tighter of the two",
			host:      sized("host_c", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 500*1024),
			pool:      limited("hungry", 1, 4096),
			wantFits:  2,
			wantRoom:  2,
			wantLimit: "memory",
		},
		{
			name: "a machine too small for one runner has room for none",
			host: sized("host_d", 4, 2, 2*1024, 500*1024),
			pool: limited("huge", 8, 16384),
			// Not a negative, and not the slot count either: a host that
			// cannot hold one is a host with no room, and the count has to
			// say so rather than promising four.
			wantFits:  0,
			wantRoom:  0,
			wantLimit: "cpu",
		},
		{
			// The pass refuses every runner on a host at its disk reserve,
			// however little the pool asks for, so a pool that states no disk
			// must not be told the host has room. The pool page and the
			// pool.max_above_room warning add these figures up.
			name: "a host at its disk reserve has room for none, whatever the pool asks for",
			host: func() *store.Host {
				h := sized("host_e", 4, 8, 32*1024, 500*1024)
				h.DiskFreeMB = 0
				return h
			}(),
			pool:      limited("light", 1, 1024),
			wantFits:  0,
			wantRoom:  0,
			wantLimit: "disk",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := HostRoomFor(tc.host, tc.pool)
			if got.Fits != tc.wantFits || got.Room != tc.wantRoom || got.LimitedBy != tc.wantLimit {
				t.Errorf("HostRoomFor = %+v, want fits %d, room %d, limited by %s",
					got, tc.wantFits, tc.wantRoom, tc.wantLimit)
			}
		})
	}
}

// A docker-in-docker slot is two containers, so the room it leaves is half what
// the pool's own figures suggest. An operator reading "2 CPU" against a ten-core
// host and being told there is room for two has to be told why, and this is the
// arithmetic the sentence comes from.
func TestARunnerWithASidecarTakesTwiceTheRoom(t *testing.T) {
	h := sized("host_a", 8, 10, 20*1024, 500*1024)
	p := limited("dind", 2, 4096)
	p.DockerMode = store.DockerDinD

	got := HostRoomFor(h, p)
	if got.Fits != 2 {
		t.Errorf("fits = %d, want 2: the pair is charged 4 CPU and 8 GB on a machine with 9.5 and 19.5", got.Fits)
	}
}

// A host that has measured nothing places by its slots alone, exactly as it did
// before any of this existed -- which is what stops an upgrade emptying a fleet
// of agents too old to report their machines.
func TestAnUnmeasuredHostPlacesBySlots(t *testing.T) {
	h := testHost("host_old", 6, 0)
	p := limited("standard", 2, 4096)

	got := HostRoomFor(h, p)
	if got.Room != 6 || got.LimitedBy != "" {
		t.Errorf("HostRoomFor = %+v, want all six slots and nothing named as the limit", got)
	}
}

// Package scheduler decides how many runners each pool should have.
//
// Decide is a pure function: it takes a snapshot of the fleet and returns a
// plan. It reads no clock, opens no database and performs no I/O, so the whole
// scaling behaviour of the product is reproducible in a table test and
// explainable in the UI -- every action carries the sentence that justified it,
// in the operator's words rather than in counters they have to interpret.
//
// The caller gathers the snapshot, executes the plan and records the reasons.
package scheduler

import (
	"cmp"
	"fmt"
	"math"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// Snapshot is everything the scheduler needs to decide, gathered by the caller.
type Snapshot struct {
	Readiness       map[string]map[string]time.Duration
	PreferReadiness bool
	// Now is the decision time. It is a field rather than a clock read so that
	// a test can place a runner exactly one second either side of a timeout.
	Now             time.Time
	LastProvisioned map[string]time.Time
	// Pools is every pool, enabled or not; a disabled pool still gets drained.
	Pools []*store.Pool
	// Runners holds the non-removed runners of each pool, keyed by pool ID.
	Runners map[string][]*store.Runner
	// Jobs holds queued and in-progress jobs. Only queued jobs create demand:
	// an in-progress job is already represented by the busy runner running it.
	Jobs []*store.Job
	// ActiveByRepository and QueuedByRepository make repository fair-share
	// state explicit at the scheduler boundary rather than hiding database reads
	// inside the policy engine.
	ActiveByRepository map[string]int
	QueuedByRepository map[string]int
	// Hosts is every registered agent host, with ActiveRunners filled in.
	Hosts []*store.Host
	// Installations is every configured GitHub App installation. Eligibility
	// is decided from the identifiers a pool and a job already carry, so this
	// is here only so that an explanation can name the organisation or
	// repository an operator recognises instead of an opaque identifier.
	Installations []*store.Installation
	Policy        Policy
	// Jitter spreads the start-failure backoff, keyed by pool ID and redrawn
	// on every pass. It arrives here rather than being drawn here for the same
	// reason Now does: the scheduler reads no clock and no random source, so a
	// decision is reproducible from its inputs alone and a test can place a
	// pool exactly either side of its wait.
	//
	// Values outside [0,1) are clamped, and a pool with no entry gets none --
	// a caller that has not thought about jitter keeps the old behaviour.
	Jitter map[string]float64
	// HeldInstallations is every installation GitHub is rate-limiting, keyed
	// by ID, with the moment its quota returns. A pool on a held installation
	// creates nothing: the create would be refused identically, spend another
	// call against a quota that is already gone, and leave a failed row whose
	// only message is the refusal. The poller and the reap already stand down
	// from a held installation; this is the scheduler doing the same.
	HeldInstallations map[string]time.Time
	// JobHistory is the recent measured runs of each queued job, keyed by the
	// job and the pool that ran them, and HistorySizing is
	// scheduler.history_sizing: off, shadow or on. The caller reads the
	// history; the profile, and what it means for placement, are decided
	// here. An empty mode is off.
	JobHistory    map[store.JobUsageKey][]store.JobPeak
	HistorySizing string
}

const (
	// failedRetention is how long a failed runner stays on the Runners page
	// before the reap removes it. Removing it at once, as the scheduler used
	// to, freed nothing -- a failed runner holds no host slot -- and took the
	// only record of why it failed off the page within a second of it
	// appearing. Ten minutes is long enough to read, and the failures still
	// on the page are also what the start backoff below is decided on.
	failedRetention = 10 * time.Minute

	// startBackoff is how long a pool waits after a runner fails to start
	// before it creates another; each further failure doubles the wait, up to
	// maxStartBackoff. Without it a runner that dies on creation is replaced
	// in the same pass that notices, and a pool whose image cannot be pulled
	// creates, fails and removes a runner every second -- two GitHub API
	// calls a time, until the installation's hourly quota is spent on nothing.
	startBackoff    = 10 * time.Second
	maxStartBackoff = 5 * time.Minute

	// startBackoffJitter is how much of a pool's wait may be added to it, at
	// most. Without it every pool broken by the same thing -- a daemon that
	// went down, a registry that stopped answering -- counts the same doubling
	// from the same failure and retries in the same second, so the recovery
	// arrives as the same thundering herd that broke it.
	startBackoffJitter = 0.2
)

// Policy carries the tunables from config.Scheduler.
//
// Every duration here is disabled by a zero or negative value, so a caller that
// leaves a field unset gets "no timeout" instead of a fleet that reaps itself.
type Policy struct {
	// ScaleUpDelay is how long a job must have been queued before it counts as
	// demand, which damps churn when jobs arrive in bursts.
	ScaleUpDelay time.Duration
	// MaxRunnerLifetime drains a runner that has lived this long, the next
	// time it is not busy. It bounds how long a persistent runner's state and
	// credentials live; reap never drains a busy runner, so it is no answer to
	// a hung job.
	MaxRunnerLifetime time.Duration
	// ProvisionTimeout fails a runner that never finished registering.
	ProvisionTimeout time.Duration
	// DrainTimeout fails a runner that has been draining this long with no job
	// left on it. The agent task queue is in memory by design, so a controller
	// restart drops a stop that was already issued; without this the row stays
	// in draining, holds its host slot and leaves its pool one runner short for
	// as long as the controller runs. A runner still finishing a job is never
	// touched by it -- that wait is what a drain is -- so this bounds only the
	// drain that has nothing to wait for. Zero leaves a drain unbounded.
	DrainTimeout time.Duration
	// MaxCreatesPerTick caps creates across the whole fleet in one pass, so a
	// thundering herd of queued jobs cannot fill every host at once. Pools are
	// shared fairly among pools at the same priority; zero means no cap.
	MaxCreatesPerTick int
	// MaxRunners is limits.runners: the most live runners the whole fleet may
	// hold, across every pool. Zero means no ceiling. Unlike the per-tick
	// budget it does not refill on the next pass -- only a runner ending makes
	// room -- so a pool it holds back says which setting did it.
	MaxRunners int
	// Interval is how often the reconcile loop runs. A lower-priority pool
	// whose oldest queued job has waited at least this long is owed one
	// create before a higher tier spends the rest of the budget, so a deep
	// backlog at the top cannot starve every other pool pass after pass.
	// Zero turns that share off and priority alone decides.
	Interval time.Duration
}

// For is this policy as one pool sees it: the fleet's figures, with whatever
// that pool overrides of them applied.
//
// It is a method on the fleet's policy rather than a field on the pool so
// that a pool which overrides nothing keeps following the fleet -- including
// after an operator changes the fleet's figure, which a value copied onto the
// pool at creation would not. That is the same reason a pool's size is left
// to the host it lands on rather than frozen at the share it had on the day.
//
// MaxCreatesPerTick is deliberately not overridable. It is a fleet-wide
// budget shared between pools, and a pool that could raise its own share of
// it would be taking the protection from the others.
func (p Policy) For(pool *store.Pool) Policy {
	if pool == nil || !pool.RunnerSettings.Set() {
		return p
	}
	rs := pool.RunnerSettings
	if rs.ScaleUpDelay != nil {
		p.ScaleUpDelay = rs.ScaleUpDelay.Duration()
	}
	if rs.MaxRunnerLifetime != nil {
		p.MaxRunnerLifetime = rs.MaxRunnerLifetime.Duration()
	}
	if rs.ProvisionTimeout != nil {
		p.ProvisionTimeout = rs.ProvisionTimeout.Duration()
	}
	if rs.DrainTimeout != nil {
		p.DrainTimeout = rs.DrainTimeout.Duration()
	}
	return p
}

// ActionKind is what the caller must do to a runner.
type ActionKind string

const (
	// ActionCreate asks for a new runner on a named host.
	ActionCreate ActionKind = "create"
	// ActionDrain asks a runner to finish its current job and stop. It is only
	// ever emitted for a runner that is not busy.
	ActionDrain ActionKind = "drain"
	// ActionRemove tears down a runner that is already dead.
	ActionRemove ActionKind = "remove"
	// ActionFail marks a runner that never came up as failed, so that the
	// failure is visible instead of the pool silently sitting one short.
	ActionFail ActionKind = "fail"
)

// Action is one change the caller should make to the fleet.
type Action struct {
	Kind     ActionKind `json:"kind"`
	PoolID   string     `json:"pool_id"`
	PoolName string     `json:"pool_name"`
	// RunnerID is empty for ActionCreate, which has no runner yet.
	RunnerID string `json:"runner_id,omitempty"`
	// HostID is the host chosen for an ActionCreate, empty otherwise.
	HostID string `json:"host_id,omitempty"`
	// Reason is operator-facing, e.g. "3 jobs queued > 30s".
	Reason string `json:"reason"`
	// Size is set on an ActionCreate that no host had room for at the pool's
	// standard size: what the runner is created with instead, at or above the
	// pool's minimum. Nil means the standard.
	Size *store.Resources `json:"size,omitempty"`
	// SizedFromHistory says Size is above the standard rather than below it:
	// the runner was sized for what the jobs waiting are known to need.
	SizedFromHistory bool `json:"sized_from_history,omitempty"`
}

// sizePhrase says a runner size the way the reason for a create does.
func sizePhrase(cpus float64, memoryMB int64) string {
	parts := []string{}
	if cpus > 0 {
		parts = append(parts, formatCPUs(cpus)+" CPU")
	}
	if memoryMB > 0 {
		parts = append(parts, formatMB(memoryMB))
	}
	return strings.Join(parts, " and ")
}

// PoolPlan is the decision for one pool.
type PoolPlan struct {
	PoolID   string `json:"pool_id"`
	PoolName string `json:"pool_name"`
	// Current is the number of live runners left after this tick's reaping;
	// a runner being failed or retired no longer counts towards the pool.
	Current int `json:"current"`
	// Desired is the runner count the pool is aiming at.
	Desired int `json:"desired"`
	// QueuedMatched counts every queued job this pool claims, including jobs
	// still inside ScaleUpDelay and therefore not yet driving a create.
	QueuedMatched int `json:"queued_matched"`
	// QuotaDeferredJobs counts queued jobs which did not contribute to desired
	// capacity because their repository reached the pool's best-effort scale-up
	// limit. It is separate from Blocked because admitted work may still scale.
	QuotaDeferredJobs int `json:"quota_deferred_jobs,omitempty"`
	// QuotaDeferredRepositories names the repositories represented by those
	// deferred jobs, in stable order.
	QuotaDeferredRepositories []string `json:"quota_deferred_repositories,omitempty"`
	// eligible is the number of queued jobs that drove Desired: past the
	// scale-up delay and admitted by the repository limit. The scale-up reason
	// is written from it, so it names the jobs the pool is scaling for rather
	// than every job on the queue.
	eligible int
	// Reason is the sentence shown in the UI, e.g.
	// "scaled linux-x64 2 -> 4: 3 jobs queued > 30s". It is empty when the
	// pool's size did not change.
	Reason string `json:"reason,omitempty"`
	// Blocked is set when this pool needed runners and the fleet had nowhere to
	// put them: no host offers its backend, matches its host selector, or has
	// room left. It holds the sentence naming which, and it is what the
	// problems drawer reports -- a pool in this state looks completely healthy
	// while its jobs queue forever, so it has to be said out loud somewhere.
	//
	// It stays empty when the shortfall was only this tick's create budget,
	// which the next pass clears on its own and which no operator can act on.
	Blocked string `json:"blocked,omitempty"`
	// BlockedFix is what to change to unblock it, kept apart from Blocked
	// because the problems drawer shows the two differently.
	BlockedFix string `json:"blocked_fix,omitempty"`
	// BlockedAtCapacity distinguishes a fleet that is merely full -- every host
	// could run this pool and all of them are busy, which the next finished job
	// clears -- from one where no host can ever run it. Both are worth saying;
	// only the second is a fault.
	BlockedAtCapacity bool `json:"blocked_at_capacity,omitempty"`
	// BlockedNoEligibleHost is the other half of that distinction: not one host
	// in the fleet could run this pool, so no job finishing anywhere will ever
	// clear it. It is the state a new machine fixes and a finished job does not,
	// which is why it is reported separately rather than folded into
	// BlockedAtCapacity -- that field means "the fleet is working and full", and
	// the problems drawer and the usage record both read it as such.
	BlockedNoEligibleHost bool `json:"blocked_no_eligible_host,omitempty"`
	// BlockedAlternatives are the backends the hosts this pool otherwise fits
	// already offer. "Point this pool at a backend they already offer" is half
	// the fix for a pool blocked on its backend, and an operator cannot act on
	// it without being told which backend that is -- so the answer travels with
	// the reason, to the problems drawer, the pool page and the CLI.
	BlockedAlternatives []string `json:"blocked_alternatives,omitempty"`
	// Failing is set when the pool's recent runners died before they ever
	// registered and the scheduler is holding off creating more for a while.
	// It says how many failed, the latest reason and when the next attempt
	// is, because a pool in this state has jobs waiting on runners that keep
	// failing, and the problems drawer has to be able to say why.
	Failing string `json:"failing,omitempty"`
	// FailingFault is the category behind that, taken from the most recent
	// failed runner. The sentence above says how many and when; this says what
	// to do, and they are different questions -- "the last four runners failed
	// to start" is a pool to look at, and "because the image could not be
	// pulled" is a tag to fix.
	//
	// It travels in the plan rather than being looked up again by each reader
	// for the reason the rest of this struct does: the problems drawer, the
	// pool page and a job's explanation all ask, and three lookups against a
	// fleet that has moved on is three answers.
	FailingFault store.FaultKind `json:"failing_fault,omitempty"`
	// Held is set when the pool's installation is inside a GitHub rate-limit
	// backoff. It says until when, because the pool is otherwise healthy and
	// its jobs are waiting on nothing the operator can see.
	Held string `json:"held,omitempty"`
	// History is what the jobs waiting on this pool are known to need and
	// what that did to placement: the hosts held off and the size given, or,
	// under shadow, what it would have done. Empty when nothing is known or
	// it changed nothing.
	History string `json:"history,omitempty"`
	// HistoryUnfit is set when a job waiting on this pool is known to need
	// more than any host that can run the pool has to give. Such a job is
	// placed as it always was, and is likely to fail the way it did before;
	// only a larger host fixes it, which is why it is reported.
	HistoryUnfit string   `json:"history_unfit,omitempty"`
	Actions      []Action `json:"actions,omitempty"`
}

// Plan is one tick's worth of decisions.
type Plan struct {
	Pools []PoolPlan `json:"pools"`
	// Actions is every pool's actions flattened, in execution order.
	Actions []Action `json:"actions,omitempty"`
	// Unmatched holds queued jobs no pool will run, each with the reason the
	// nearest pool refused it. They will never run, so the UI surfaces them as
	// a configuration problem.
	Unmatched []UnmatchedJob `json:"unmatched,omitempty"`
}

// UnmatchedJob is a queued job no pool claimed, and why.
type UnmatchedJob struct {
	Job *store.Job `json:"job"`
	// Reason is empty when the job's labels simply match no pool here, which
	// is the case the Jobs page already explains on its own. It is set when
	// something less obvious refused the job -- a pool that advertises exactly
	// those labels but belongs to another GitHub App installation.
	Reason string `json:"reason,omitempty"`
}

// Decide turns a snapshot of the fleet into the actions that move it towards
// what the queue is asking for. It is deterministic: the same snapshot always
// yields the same plan, down to the order of the actions.
func Decide(s Snapshot) Plan {
	pools := sortedPools(s.Pools)
	demand, unmatched := assign(pools, s.Jobs, targetsOf(s.Installations))

	t := &tick{
		now:                s.Now,
		policy:             s.Policy,
		hosts:              newHostSet(s.Hosts, pools, s.Runners, s.Now),
		budget:             s.Policy.MaxCreatesPerTick,
		activeByRepository: s.ActiveByRepository,
		poolCount:          len(pools),
		jitter:             s.Jitter,
		lastProvisioned:    s.LastProvisioned,
		held:               s.HeldInstallations,
		stillRunning:       runnersWithAJob(s.Jobs),
		history:            s.JobHistory,
		historySizing:      s.HistorySizing,
	}
	t.hosts.readiness, t.hosts.preferReadiness = s.Readiness, s.PreferReadiness
	if t.budget <= 0 {
		// An unset cap must not stall the fleet; host capacity still bounds us.
		t.budget = math.MaxInt
	}

	plan := Plan{Pools: make([]PoolPlan, 0, len(pools)), Unmatched: unmatched}
	for _, p := range pools {
		pp := t.decidePool(p, s.Runners[p.ID], demand[p.ID])
		plan.Pools = append(plan.Pools, pp)
	}
	if limit := s.Policy.MaxRunners; limit > 0 {
		// Counted after the reap, from what each pool still holds, so a runner
		// this pass is failing or removing does not keep its place under the
		// ceiling for one pass longer than it keeps its host slot.
		live := 0
		for _, pp := range plan.Pools {
			live += pp.Current
		}
		if room := max(limit-live, 0); room < t.budget {
			t.budget, t.atCeiling = room, true
		}
	}
	t.allocate(pools, plan.Pools, s.Runners, demand)
	// Finish cleanup before starting replacements, then preserve the exact
	// allocation order when registration admission admits only part of a plan.
	for _, pp := range plan.Pools {
		for _, action := range pp.Actions {
			if action.Kind != ActionCreate {
				plan.Actions = append(plan.Actions, action)
			}
		}
	}
	plan.Actions = append(plan.Actions, t.creates...)
	return plan
}

// tick is the mutable state of a single Decide call: capacity handed out so
// far, and the create budget left for the pools that have not been served yet.
type tick struct {
	creates []Action
	now     time.Time
	policy  Policy
	hosts   *hostSet
	budget  int
	// atCeiling says the budget was cut to what limits.runners leaves, so a
	// pool left short is told that rather than blamed on the tick.
	atCeiling          bool
	activeByRepository map[string]int
	poolCount          int
	jitter             map[string]float64
	lastProvisioned    map[string]time.Time
	held               map[string]time.Time
	// stillRunning is every runner with a job in progress on it, whatever the
	// row says its state is. A runner given up as lost is failed while its job
	// is still running, and the late-report path keeps that workload alive
	// on purpose; the reap has to know not to take it back.
	stillRunning map[string]bool
	// history and historySizing are Snapshot.JobHistory and HistorySizing.
	history       map[store.JobUsageKey][]store.JobPeak
	historySizing string
}

// assign maps every queued job onto the pool that will run it, and collects the
// ones nothing claims, each with the reason it went unclaimed.
func assign(pools []*store.Pool, jobs []*store.Job, targets map[string]string) (map[string][]*store.Job, []UnmatchedJob) {
	demand := make(map[string][]*store.Job, len(pools))
	var unmatched []UnmatchedJob
	for _, j := range sortedJobs(jobs) {
		if j.State != store.JobQueued || j.Provisioning != "" {
			continue
		}
		p, reason := bestPool(pools, j, targets)
		if p == nil {
			unmatched = append(unmatched, UnmatchedJob{Job: j, Reason: reason})
			continue
		}
		demand[p.ID] = append(demand[p.ID], j)
	}
	return demand, unmatched
}

// targetsOf indexes installations by identifier so that an explanation can
// name the organisation or repository one manages.
func targetsOf(insts []*store.Installation) map[string]string {
	if len(insts) == 0 {
		return nil
	}
	out := make(map[string]string, len(insts))
	for _, i := range insts {
		if i != nil {
			out[i.ID] = i.Target
		}
	}
	return out
}

// decidePool applies the reap, scale-up and scale-down rules to one pool.
func (t *tick) decidePool(p *store.Pool, runners []*store.Runner, queued []*store.Job) PoolPlan {
	plan := PoolPlan{PoolID: p.ID, PoolName: p.Name, QueuedMatched: len(queued)}

	actions, remaining := t.reap(p, sortedRunners(runners))
	plan.Actions = actions

	live, busy, draining := 0, 0, 0
	for _, r := range remaining {
		if r.State.Live() {
			live++
		}
		switch r.State {
		case store.RunnerBusy:
			busy++
		case store.RunnerDraining:
			draining++
		}
	}
	plan.Current = live

	if !p.Enabled {
		t.disable(p, &plan, remaining, live)
		return plan
	}

	eligible := 0
	quotaRepositories := map[string]bool{}
	admitted := map[string]int{}
	for _, j := range queued {
		// The delay is asked about first because it is the cheaper reason to
		// be waiting and the one nobody can act on. A job still inside it
		// would not have driven a create whatever the repository limit said,
		// so counting it as deferred by that limit made the pool's reason
		// read "3 jobs deferred by the repository limit for acme/widgets"
		// about jobs the next few seconds were going to release anyway --
		// and sent an operator to change a setting that was not the cause.
		if !j.ProvisionNow && t.now.Sub(j.QueuedAt) < t.policy.For(p).ScaleUpDelay {
			continue
		}
		if p.RepositoryScaleUpLimit > 0 && t.activeByRepository[p.ID+"\x00"+j.Repo]+admitted[j.Repo] >= p.RepositoryScaleUpLimit {
			plan.QuotaDeferredJobs++
			quotaRepositories[j.Repo] = true
			continue
		}
		eligible++
		admitted[j.Repo]++
	}
	for repo := range quotaRepositories {
		plan.QuotaDeferredRepositories = append(plan.QuotaDeferredRepositories, repo)
	}
	slices.Sort(plan.QuotaDeferredRepositories)
	// Idle runners are already counted in live, so subtracting live from the
	// target is what stops the scheduler from creating a runner for a job an
	// idle one will pick up within the second. A draining runner is counted on
	// both sides: it still holds a slot on its host until it is gone, which is
	// what keeps the pool under its maximum, but it will never take a job, so
	// it must not stand in for the runner a queued job is waiting on.
	plan.Desired = clamp(max(p.MinRunners, busy+draining+eligible), p.MinRunners, p.MaxRunners)
	plan.eligible = eligible
	plan.Failing, plan.FailingFault = t.holdAfterStartFailures(p, runners)
	plan.Held = t.holdWhileRateLimited(p)

	switch {
	case plan.Desired < live:
		t.scaleDown(p, &plan, remaining, live)
	}
	return plan
}

// holdAfterStartFailures decides whether a pool's recent failures should stop
// it creating for now, and returns the sentence that says so, or "" when it
// may go ahead.
//
// Only runners that died before registering count: they are evidence that
// the pool cannot start a runner at the moment -- an image that will not
// pull, a host that cannot reach GitHub -- whereas a runner that ran jobs
// and then failed says nothing about the next create. The wait doubles with
// each failure still on the page, so a broken pool settles at one attempt
// every few minutes rather than one a second; it recovers on its own, because
// a pass that creates nothing adds no failure and the wait simply runs out.
func (t *tick) holdAfterStartFailures(p *store.Pool, runners []*store.Runner) (string, store.FaultKind) {
	failed := startFailures(runners, t.now)
	if len(failed) == 0 {
		return "", ""
	}
	wait := maxStartBackoff
	if shift := len(failed) - 1; shift < 8 && startBackoff<<shift < maxStartBackoff {
		wait = startBackoff << shift
	}
	wait = jittered(wait, t.jitter[p.ID])
	since := t.now.Sub(failedAt(failed[0]))
	if since >= wait {
		return "", ""
	}
	which := "the last runner"
	if len(failed) > 1 {
		which = "the last " + plural(len(failed), "runner")
	}
	return fmt.Sprintf("%s failed to start, most recently %s ago (%s); trying again in %s",
		which, formatDuration(since.Truncate(time.Second)), summarise(failed[0].Message),
		formatDuration((wait - since).Round(time.Second))), failed[0].FaultKind
}

// holdWhileRateLimited returns the sentence that says a pool's installation
// is inside a GitHub rate-limit backoff, or "" when it is not.
//
// It is a hold on creates only. Draining and removing a runner ask GitHub for
// nothing, so a held pool still scales down.
func (t *tick) holdWhileRateLimited(p *store.Pool) string {
	until, ok := t.held[p.InstallationID]
	if !ok || !t.now.Before(until) {
		return ""
	}
	return fmt.Sprintf("GitHub is rate-limiting this pool's installation; not asking it to register runners for %s",
		formatDuration(until.Sub(t.now).Round(time.Second)))
}

func firstNonEmpty(a, b string) string {
	if a != "" {
		return a
	}
	return b
}

// jittered lengthens a wait by up to startBackoffJitter of itself.
//
// It only ever adds. Shortening a backoff would let the pool that is failing
// hardest come back soonest, which is the opposite of what the doubling is
// for; spreading the herd is worth a little extra wait and nothing else.
func jittered(d time.Duration, f float64) time.Duration {
	if f <= 0 {
		return d
	}
	if f > 1 {
		f = 1
	}
	return d + time.Duration(float64(d)*startBackoffJitter*f)
}

// startFailures returns the runners that failed before ever registering and
// whose failure is still on the page, newest first.
func startFailures(runners []*store.Runner, now time.Time) []*store.Runner {
	var out []*store.Runner
	for _, r := range runners {
		if r.State == store.RunnerFailed && r.RegisteredAt == nil && now.Sub(failedAt(r)) < failedRetention {
			out = append(out, r)
		}
	}
	slices.SortStableFunc(out, func(a, b *store.Runner) int {
		return failedAt(b).Compare(failedAt(a))
	})
	return out
}

// recentBusyHosts is the hosts a runner of this pool most recently failed to
// start on with FaultBackendBusy, whose failure is still on the page --
// startFailures' own window, so a host stops being avoided exactly when it
// stops counting toward the pool's own start-failure backoff.
//
// It is what grant steers a replacement away from where it can: the daemon
// that timed out on the last create is not evidence the pool is broken --
// holdAfterStartFailures already treats FaultBackendBusy like any other start
// failure and waits regardless of which host caused it -- but it is evidence
// that this particular host, right now, is one to try last rather than
// first, if the fleet has anywhere else to offer.
func recentBusyHosts(runners []*store.Runner, now time.Time) map[string]bool {
	var out map[string]bool
	for _, r := range startFailures(runners, now) {
		if r.FaultKind != store.FaultBackendBusy || r.HostID == "" {
			continue
		}
		if out == nil {
			out = map[string]bool{}
		}
		out[r.HostID] = true
	}
	return out
}

// runnersWithAJob is the set of runners a job in progress is attributed to.
func runnersWithAJob(jobs []*store.Job) map[string]bool {
	out := map[string]bool{}
	for _, j := range jobs {
		if j.State == store.JobInProgress && j.RunnerID != "" {
			out[j.RunnerID] = true
		}
	}
	return out
}

// drainingFor is how long a runner has been draining.
//
// A row written before the column existed has no draining_since, and its age
// is the only clock left. That over-counts -- a long-lived runner drained a
// moment ago looks overdue at once -- but the alternative is a drain from
// before the upgrade that no timeout can ever reach, which is the state this
// rule exists to end.
func drainingFor(r *store.Runner, now time.Time) time.Duration {
	if r.DrainingSince != nil {
		return now.Sub(*r.DrainingSince)
	}
	return r.Age(now)
}

// failedAt is when a runner failed. The store stamps finished_at on the
// transition; a row without one falls back to its creation, which is the
// conservative reading for a failure of unknown age.
func failedAt(r *store.Runner) time.Time {
	if r.FinishedAt != nil {
		return *r.FinishedAt
	}
	return r.CreatedAt
}

// summarise keeps a runner's failure message to one clause of a sentence. The
// full text is on the Runners page; here it is the hint, not the report.
//
// The cut is by bytes and the message is not: it comes from a daemon, a
// registry or GitHub, and a limit that landed inside a character left half of
// one behind -- which reaches the problems drawer and the pool page as a
// replacement glyph in the middle of a word. Dropping the partial character is
// what the reader wanted from the ellipsis anyway.
func summarise(message string) string {
	message = strings.Join(strings.Fields(message), " ")
	if message == "" {
		return "no reason was recorded"
	}
	const limit = 160
	if len(message) > limit {
		return strings.ToValidUTF8(message[:limit-1], "") + "…"
	}
	return message
}

// allocate shares creation capacity after every pool's desired size has been
// calculated. Priority tiers are exhausted from highest to lowest; within a
// tier each backlogged pool receives one slot per round.
func (t *tick) allocate(pools []*store.Pool, plans []PoolPlan, runners map[string][]*store.Runner, demand map[string][]*store.Job) {
	tiers := append([]*store.Pool(nil), pools...)
	slices.SortStableFunc(tiers, func(a, b *store.Pool) int {
		if c := cmp.Compare(b.Priority, a.Priority); c != 0 {
			return c
		}
		// Under a small per-tick budget, start with the least recently served
		// backlogged pool. Round-robin within a pass alone starves later pools.
		// Explicit run-now demand comes first within its configured priority tier.
		aq, bq := demand[a.ID], demand[b.ID]
		aNow, bNow := len(aq) > 0 && aq[0].ProvisionNow, len(bq) > 0 && bq[0].ProvisionNow
		if aNow != bNow {
			if aNow {
				return -1
			}
			return 1
		}
		latest := func(id string) time.Time {
			last := t.lastProvisioned[id]
			for _, r := range runners[id] {
				if r != nil && r.CreatedAt.After(last) {
					last = r.CreatedAt
				}
			}
			return last
		}
		if c := latest(a.ID).Compare(latest(b.ID)); c != 0 {
			return c
		}
		// Waiting is only comparable between pools that have something waiting,
		// so having demand is its own key ahead of the wait. Comparing wait
		// only when both had demand and falling to the ID otherwise made a
		// pool with none -- a warm minimum -- order by ID against pools ordered
		// by wait: a cycle, and a sort left to pick whichever it met first.
		if (len(aq) > 0) != (len(bq) > 0) {
			if len(aq) > 0 {
				return -1
			}
			return 1
		}
		if len(aq) > 0 {
			if c := aq[0].QueuedAt.Compare(bq[0].QueuedAt); c != 0 {
				return c
			}
		}
		return strings.Compare(a.ID, b.ID)
	})
	byID := make(map[string]*PoolPlan, len(plans))
	for i := range plans {
		byID[plans[i].PoolID] = &plans[i]
	}

	// The share across tiers is granted before any tier is served, so that
	// what is left is what priority then decides.
	shared, floor := t.shareAcrossTiers(tiers, byID, runners, demand)
	for start := 0; start < len(tiers); {
		end := start + 1
		for end < len(tiers) && tiers[end].Priority == tiers[start].Priority {
			end++
		}
		active := append([]*store.Pool(nil), tiers[start:end]...)
		for len(active) > 0 && t.budget > 0 {
			next := active[:0]
			for _, p := range active {
				pp := byID[p.ID]
				if !p.Enabled || pp.Desired <= pp.Current+creates(pp.Actions) {
					continue
				}
				if why := firstNonEmpty(pp.Failing, pp.Held); why != "" {
					// Held back, not blocked: there is somewhere to put a
					// runner, and the pool will try again on its own once the
					// wait is out. The reason still says what went unserved.
					pp.Reason = cannotScale(p.Name, pp.Current, pp.Desired, why)
					continue
				}
				if !t.grant(p, pp, runners[p.ID], demand[p.ID]) {
					continue
				}
				if pp.Desired > pp.Current+creates(pp.Actions) {
					next = append(next, p)
				}
				if t.budget == 0 {
					break
				}
			}
			active = next
		}
		start = end
		if t.budget == 0 {
			break
		}
	}
	for _, p := range pools {
		pp := byID[p.ID]
		got := creates(pp.Actions)
		if !p.Enabled || pp.Desired <= pp.Current+got || pp.Blocked != "" || pp.Failing != "" || pp.Held != "" {
			continue
		}
		why := fmt.Sprintf("this tick's global limit of %s is exhausted; the next pass will continue", plural(t.policy.MaxCreatesPerTick, "new runner"))
		// The runner ceiling is the binding reason when it holds: no share
		// across priorities makes room it does not have.
		if t.atCeiling {
			why = fmt.Sprintf("the fleet holds the %s limits.runners allows; a runner ending makes room, or raise limits.runners",
				plural(t.policy.MaxRunners, "live runner"))
		} else if shared > 0 && p.Priority > floor {
			why = fmt.Sprintf("deferred for fairness across priorities: %s of this tick's global limit of %s went to lower-priority pools whose jobs had waited a full scheduling interval; the next pass will continue",
				plural(shared, "create"), plural(t.policy.MaxCreatesPerTick, "new runner"))
		}
		pp.Reason = cannotScale(p.Name, pp.Current+got, pp.Desired, why)
	}
}

// shareAcrossTiers grants one create to every pool below the highest tier
// with demand whose oldest queued job has waited a full interval, before that
// tier is served. Without it a top-priority pool with a deep backlog takes
// the whole budget every pass and a lower tier waits for as long as the
// backlog lasts -- priority should order the fleet's work, not stop some of
// it. A lower tier that has not yet waited an interval takes nothing, so a
// burst at the top still gets the tick to itself.
//
// It returns how many creates it granted and the lowest priority that
// received one; a pool above that priority left short this tick was deferred
// by the share, and its reason says so.
func (t *tick) shareAcrossTiers(tiers []*store.Pool, byID map[string]*PoolPlan, runners map[string][]*store.Runner, demand map[string][]*store.Job) (granted, floor int) {
	if t.policy.Interval <= 0 || t.policy.MaxCreatesPerTick <= 0 {
		// An uncapped tick serves every tier anyway; there is nothing to share.
		return 0, 0
	}
	wants := func(p *store.Pool) bool {
		pp := byID[p.ID]
		return p.Enabled && pp.Desired > pp.Current+creates(pp.Actions) && pp.Failing == "" && pp.Held == ""
	}
	top, found := 0, false
	for _, p := range tiers {
		if wants(p) {
			top, found = p.Priority, true
			break
		}
	}
	if !found {
		return 0, 0
	}
	for _, p := range tiers {
		if t.budget == 0 {
			break
		}
		if p.Priority >= top || !wants(p) || !t.waitedAnInterval(demand[p.ID]) {
			continue
		}
		if t.grant(p, byID[p.ID], runners[p.ID], demand[p.ID]) {
			granted++
			// tiers is sorted highest first, so the last grant is the lowest.
			floor = p.Priority
		}
	}
	return granted, floor
}

// waitedAnInterval reports whether any of these queued jobs has waited at
// least one reconcile interval, measured against the snapshot's time.
func (t *tick) waitedAnInterval(queued []*store.Job) bool {
	for _, j := range queued {
		if !j.QueuedAt.IsZero() && t.now.Sub(j.QueuedAt) >= t.policy.Interval {
			return true
		}
	}
	return false
}

func creates(actions []Action) int {
	n := 0
	for _, a := range actions {
		if a.Kind == ActionCreate {
			n++
		}
	}
	return n
}

func (t *tick) grant(p *store.Pool, plan *PoolPlan, runners []*store.Runner, queued []*store.Job) bool {
	var need Requirement
	var heldOff map[string]string
	if t.historySizing == HistoryOn || t.historySizing == HistoryShadow {
		need, plan.HistoryUnfit = t.poolNeed(p, queued)
		if need.Known() {
			heldOff = t.hosts.heldOff(p, need)
		}
	}
	enforce := t.historySizing == HistoryOn && need.Known()
	if enforce {
		t.hosts.need = &need
	}
	placed := t.hosts.placeAvoiding(p, 1, recentBusyHosts(runners, t.now))
	t.hosts.need = nil
	if len(placed) == 0 && enforce && len(heldOff) > 0 {
		// Some host would have taken a runner at the pool's own size, and
		// every one of them is short of what the jobs waiting are known to
		// need. That is a wait for a larger host to free up, not a fleet with
		// nowhere to go: poolNeed only asks for what some host has.
		held := t.hosts.sortedPhrases(heldOff)
		plan.History = held
		plan.Reason = cannotScale(p.Name, plan.Current+creates(plan.Actions), plan.Desired, held)
		plan.Blocked = held
		plan.BlockedFix = "wait for work on a larger host to finish, or add a host with that much room; the requirement is the jobs' own recent peaks, and scheduler.history_sizing=shadow places them as before"
		plan.BlockedAtCapacity = true
		return false
	}
	if len(placed) == 0 {
		b := t.hosts.why(p)
		plan.Reason = cannotScale(p.Name, plan.Current+creates(plan.Actions), plan.Desired, sentence(b.what, b.fix))
		plan.Blocked, plan.BlockedFix = b.what, b.fix
		plan.BlockedAtCapacity, plan.BlockedAlternatives = b.atCapacity, b.alternatives
		plan.BlockedNoEligibleHost = b.noEligibleHost
		return false
	}
	busy := 0
	for _, r := range runners {
		if r.State == store.RunnerBusy {
			busy++
		}
	}
	// The reason counts the jobs the pool is scaling for. Counting the queue
	// here instead used to say "3 jobs queued" for a pool the repository
	// limit let scale for one of them, which reads as a shortfall.
	delay := t.policy.For(p).ScaleUpDelay
	expedited := false
	for _, j := range queued {
		if j.ProvisionNow {
			expedited = true
			delay = 0
			break
		}
	}
	reason := upReason(p, busy, plan.eligible, delay)
	if expedited {
		reason += " (includes Run now demand)"
	}
	if plan.QuotaDeferredJobs > 0 {
		reason += fmt.Sprintf(" (%s deferred by the repository limit for %s)",
			plural(plan.QuotaDeferredJobs, "job"), strings.Join(plan.QuotaDeferredRepositories, ", "))
	}
	if size := placed[0].size; size != nil && placed[0].raised {
		reason += fmt.Sprintf(" (sized to %s)", sizePhrase(size.CPUs, size.MemoryMB))
	} else if size != nil {
		// Said in the reason as well as carried, so the Runners page and the
		// scaling history both show that this runner is smaller than its pool
		// asks for, and why.
		if p.Automatic() {
			// An automatic pool has no standard of its own to name: its
			// standard is a slot's share of whichever host it lands on.
			reason += fmt.Sprintf(" (reduced to %s: no host with a free slot had a whole share of it left)",
				sizePhrase(size.CPUs, size.MemoryMB))
		} else {
			reason += fmt.Sprintf(" (reduced to %s: no host had room for the standard %s)",
				sizePhrase(size.CPUs, size.MemoryMB), sizePhrase(p.Resources.CPUs, p.Resources.MemoryMB))
		}
	}
	switch {
	case enforce:
		note := fmt.Sprintf("placed for the jobs waiting, which need %s", need)
		if held := t.hosts.sortedPhrases(heldOff); held != "" {
			note += "; " + held
		}
		plan.History = note
		reason += " (" + note + ")"
	case need.Known():
		// Shadow: the placement stands, and what history sizing would have
		// done differently is recorded beside it rather than in the reason,
		// which describes what actually happened.
		if held, ok := heldOff[placed[0].hostID]; ok {
			plan.History = "shadow: history sizing would have " + held
		}
	}
	action := Action{Kind: ActionCreate, PoolID: p.ID, PoolName: p.Name, HostID: placed[0].hostID, Reason: reason, Size: placed[0].size, SizedFromHistory: placed[0].raised}
	plan.Actions = append(plan.Actions, action)
	t.creates = append(t.creates, action)
	t.budget--
	plan.Reason = scaled(p.Name, plan.Current, plan.Current+creates(plan.Actions), reason)
	return true
}

// reap removes from consideration the runners the scheduler can no longer count
// on, and returns the actions that clean them up. A busy runner is never
// touched here: only an explicit operator drain interrupts a running job.
func (t *tick) reap(p *store.Pool, runners []*store.Runner) (actions []Action, remaining []*store.Runner) {
	var removes, fails, retires []Action
	// The pool's own timings, where it has any. A pool that pulls a large
	// image and a pool that boots in seconds do not agree about how long
	// registering should take, and reaping both by the slower one leaves the
	// faster pool holding a dead runner's slot.
	pol := t.policy.For(p)
	for _, r := range runners {
		age := r.Age(t.now)
		switch {
		case r.State == store.RunnerRemoved:
			// Already gone; it neither costs capacity nor needs an action.
			// Whatever it left on its host is the agent's to clean up, and
			// it does so on its own once the retention window has passed.
		case r.State == store.RunnerFailed:
			// A failed runner holds no host slot, so there is nothing to free
			// by removing it quickly, and everything to lose: the message on
			// it is the only record of why it failed. It stays on the page
			// for the retention, then goes.
			//
			// Unless a job is still running on it. A host that went quiet
			// long enough to be given up as lost has its runners failed, and
			// when it comes back with the job still going the workload is
			// deliberately left to finish. Removing the row now would remove
			// the container under that job for no reason but tidiness; the
			// removal waits until the job has ended, which the reap sees on
			// a later pass.
			if t.now.Sub(failedAt(r)) >= failedRetention && !t.stillRunning[r.ID] {
				removes = append(removes, t.action(ActionRemove, p, r, fmt.Sprintf(
					"runner failed %s ago; its failure has been on the Runners page long enough",
					formatDuration(t.now.Sub(failedAt(r)).Truncate(time.Minute)))))
			}
		case starting(r.State) && pol.ProvisionTimeout > 0 && age > pol.ProvisionTimeout:
			fails = append(fails, t.action(ActionFail, p, r, fmt.Sprintf(
				"stuck in %s for %s, past the %s provision timeout; check the host's agent log",
				r.State, formatDuration(age), formatDuration(pol.ProvisionTimeout))))
		case r.State == store.RunnerDraining && r.CurrentJobID == "" &&
			pol.DrainTimeout > 0 && drainingFor(r, t.now) > pol.DrainTimeout:
			// Only a drain with nothing left to wait for. A runner draining
			// with a job still on it is doing exactly what a drain asks, for
			// as long as that job takes; there is no maximum job duration in
			// this system by design, and inventing one here would kill
			// somebody's build from the wrong end of the fleet.
			fails = append(fails, t.action(ActionFail, p, r, fmt.Sprintf(
				"draining with no job for %s, past the %s drain timeout; its stop was never carried out, so the slot is being taken back",
				formatDuration(drainingFor(r, t.now)), formatDuration(pol.DrainTimeout))))
		case pol.MaxRunnerLifetime > 0 && age > pol.MaxRunnerLifetime &&
			r.State != store.RunnerBusy && r.State != store.RunnerDraining && !t.stillRunning[r.ID]:
			retires = append(retires, t.action(ActionDrain, p, r, fmt.Sprintf(
				"runner reached the %s maximum lifetime",
				formatDuration(pol.MaxRunnerLifetime))))
		case staleImage(p, r) && r.State != store.RunnerBusy && r.State != store.RunnerDraining && !t.stillRunning[r.ID]:
			// The pool's page says one image and this runner was made from
			// another. A warm runner kept from before the change would take
			// the next job onto the old image -- for a pool that just gained
			// a Docker daemon, onto an image with no client for it -- while
			// every page says the pool is fixed. It is replaced instead; the
			// scale-up rules below make a new one from the right image in the
			// same tick when the pool still wants it.
			retires = append(retires, t.action(ActionDrain, p, r, fmt.Sprintf(
				"pool image is now %s; this runner was made from %s", p.Image, r.Image)))
		default:
			remaining = append(remaining, r)
		}
	}
	// Cleanup first: removing dead runners frees host capacity for the creates
	// that follow in the same tick.
	actions = append(actions, removes...)
	actions = append(actions, fails...)
	actions = append(actions, retires...)
	return actions, remaining
}

// staleImage reports whether a runner was made from an image other than the
// one its pool now names. A pool with no image of its own runs the instance
// default, which the runner row records and the pool row does not, so those
// are never compared.
func staleImage(p *store.Pool, r *store.Runner) bool {
	return p.Image != "" && r.Image != "" && r.Image != p.Image
}

// disable drains a disabled pool to zero. Its busy runners are left alone, so
// disabling a pool never kills a job that is already running.
func (t *tick) disable(p *store.Pool, plan *PoolPlan, remaining []*store.Runner, live int) {
	plan.Desired = 0
	n := 0
	for _, r := range remaining {
		if r.State == store.RunnerBusy || r.State == store.RunnerDraining || t.stillRunning[r.ID] {
			continue
		}
		plan.Actions = append(plan.Actions, t.action(ActionDrain, p, r, "pool is disabled"))
		n++
	}
	if n > 0 {
		plan.Reason = scaled(p.Name, live, live-n, "pool is disabled")
	}
}

// scaleDown first stops surplus runners that have not finished starting, then
// drains idle runners that have waited out the pool's idle timeout. Starting
// capacity has never run a job and has no useful warmth to preserve: when
// queued demand disappears (most commonly because GitHub cancelled the job),
// making it finish booting only to wait through the idle timeout wastes the
// host resources the cancellation just released.
//
// A starting row whose job is already in progress is excluded. The job event
// normally advances that row to busy, but stillRunning is the durable guard
// for the short window where the row has not caught up yet.
func (t *tick) scaleDown(p *store.Pool, plan *PoolPlan, remaining []*store.Runner, live int) {
	surplus := live - max(plan.Desired, p.MinRunners)
	if surplus <= 0 {
		return
	}

	starting := t.unneededStarting(remaining)
	stopStarting := min(surplus, len(starting))
	for _, r := range starting[:stopStarting] {
		plan.Actions = append(plan.Actions, t.action(ActionDrain, p, r,
			"queued demand disappeared before this runner finished starting"))
	}
	surplus -= stopStarting

	idle := t.drainable(p, remaining)
	stopIdle := min(surplus, len(idle))
	timeout := p.IdleTimeout.Duration()
	for _, r := range idle[:stopIdle] {
		reason := "surplus idle runner"
		if timeout > 0 {
			reason = fmt.Sprintf("idle for %s, over the %s idle timeout",
				formatDuration(r.IdleFor(t.now)), formatDuration(timeout))
		}
		plan.Actions = append(plan.Actions, t.action(ActionDrain, p, r, reason))
	}

	stopped := stopStarting + stopIdle
	if stopped == 0 {
		return
	}
	var reasons []string
	if stopStarting > 0 {
		reasons = append(reasons, plural(stopStarting, "runner")+" still starting after demand disappeared")
	}
	if stopIdle > 0 {
		what := plural(stopIdle, "runner") + " idle"
		if timeout > 0 {
			what += " > " + formatDuration(timeout)
		}
		reasons = append(reasons, what)
	}
	plan.Reason = scaled(p.Name, live, live-stopped, strings.Join(reasons, " and "))
}

// unneededStarting orders capacity that may be cancelled before it becomes
// useful. Provisioning comes before registering, and newer rows come first:
// preserve the runner closest to being ready when only part of a burst became
// surplus. A job already known to be running always wins over a stale runner
// state and keeps its workload.
func (t *tick) unneededStarting(runners []*store.Runner) []*store.Runner {
	var out []*store.Runner
	for _, r := range runners {
		if starting(r.State) && !t.stillRunning[r.ID] {
			out = append(out, r)
		}
	}
	slices.SortStableFunc(out, func(a, b *store.Runner) int {
		if a.State != b.State {
			if a.State == store.RunnerProvisioning {
				return -1
			}
			return 1
		}
		if c := b.CreatedAt.Compare(a.CreatedAt); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

// drainable returns the idle runners that have waited out the pool's idle
// timeout, longest-idle first so that the coldest runner goes first.
//
// A runner's row can read idle while a job is already running on it: the
// agent's report and GitHub's in_progress delivery arrive in either order,
// and an idle report that lands after the job started puts the row back to
// idle with the idle clock it had before. Drained on that row, the runner is
// stopped mid-job and killed when the stop times out -- a job GitHub reports
// as "the self-hosted runner lost communication", and the fleet as exit 137.
// A job in progress is the durable answer, as it is for a starting runner.
func (t *tick) drainable(p *store.Pool, runners []*store.Runner) []*store.Runner {
	timeout := p.IdleTimeout.Duration()
	var out []*store.Runner
	for _, r := range runners {
		if r.State == store.RunnerIdle && r.IdleFor(t.now) >= timeout && !t.stillRunning[r.ID] {
			out = append(out, r)
		}
	}
	slices.SortStableFunc(out, func(a, b *store.Runner) int {
		return idleSince(a).Compare(idleSince(b))
	})
	return out
}

func (t *tick) action(kind ActionKind, p *store.Pool, r *store.Runner, reason string) Action {
	return Action{Kind: kind, PoolID: p.ID, PoolName: p.Name, RunnerID: r.ID, Reason: reason}
}

// ---------------------------------------------------------------------------
// Host selection
// ---------------------------------------------------------------------------

// hostSet tracks what is left on each host as the plan is built, so that two
// pools cannot both be promised the last free slot -- or the last four
// gigabytes -- on the same host.
type hostSet struct {
	readiness       map[string]map[string]time.Duration
	preferReadiness bool
	hosts           []*store.Host
	free            map[string]int
	observedCPU     map[string]float64
	warming         map[string]int
	// left is the room still unpromised on each host, and alloc what the host
	// had to begin with. They are separate because the second says which
	// figures were measured at all, and an unmeasured figure constrains
	// nothing.
	left  map[string]Reservation
	alloc map[string]store.HostAllocation
	// promisedMemory is the memory still unpromised on each host by
	// reservation alone, before measured headroom is taken into account, and
	// ours says whether the host is running or starting any runner of ours.
	// Together they let an idle host take a share the host itself chose
	// without its operating system's own use counting against it; see
	// memoryLeft.
	promisedMemory map[string]int64
	ours           map[string]bool
	now            time.Time
	// need is set while a runner is being placed for a known requirement
	// under scheduler.history_sizing=on: a host that cannot hold it is not
	// eligible, and the runner is sized up to it where its pool allows.
	need *Requirement
}

// newHostSet seeds each host with its allocatable resources less what the
// runners already on it have been promised.
//
// Only live runners count, exactly as the slot count does: the snapshot keeps
// failed rows so the Runners page can show them, and charging a host for a
// runner that is gone would shrink the fleet every time one failed.
//
// Disk is the exception, and deliberately: free disk is a measurement of the
// filesystem as it is now, so what the runners already there have written is
// in the number already. Subtracting their reservations too would charge the
// same bytes twice. It is charged only for the runners this pass adds, which
// have written nothing yet.
func newHostSet(hosts []*store.Host, pools []*store.Pool, runners map[string][]*store.Runner, now time.Time) *hostSet {
	hs := &hostSet{
		hosts:          sortedHosts(hosts),
		free:           make(map[string]int, len(hosts)),
		observedCPU:    make(map[string]float64, len(hosts)),
		warming:        make(map[string]int, len(hosts)),
		left:           make(map[string]Reservation, len(hosts)),
		alloc:          make(map[string]store.HostAllocation, len(hosts)),
		promisedMemory: make(map[string]int64, len(hosts)),
		ours:           make(map[string]bool, len(hosts)),
		now:            now,
	}
	for _, h := range hs.hosts {
		hs.free[h.ID] = h.Free()
		a := h.Allocatable()
		hs.alloc[h.ID] = a
		hs.left[h.ID] = Reservation{CPUs: a.CPUs, MemoryMB: a.MemoryMB, DiskMB: a.DiskMB}
	}
	for _, h := range hs.hosts {
		// One sum, shared with the host view: what the page shows a host has
		// promised away and what a pass starts from must be the same number,
		// or an operator reads one figure and the scheduler acts on another.
		res := Reserved(h, pools, runners)
		l := hs.left[h.ID]
		l.CPUs -= res.CPUs
		l.MemoryMB -= res.MemoryMB
		hs.promisedMemory[h.ID] = l.MemoryMB
		hs.ours[h.ID] = hostRunsOurs(h, runners)
		pending := hs.pending(h, pools, runners)
		if h.Usage.Fresh(now) {
			if v := h.Usage.MemoryAvailableMB; v != nil {
				// The host sample already includes running work, and what the
				// operating system itself is using is the reserve's whole
				// job -- so the reserve is not taken off here. It is already
				// inside Allocatable, which is what a slot's size is measured
				// against; charging it a second time here makes measured
				// headroom permanently one reserve tighter than the figure a
				// pool asks for, and a host cut into a single slot then wants
				// its whole allocatable memory and can never have that much
				// left. That host reported "short of memory" at every pass,
				// at any size of machine, and its slot was never filled.
				// Subtract only starts whose demand the sample cannot yet
				// contain, then take the tighter of measured headroom and
				// reservation headroom.
				available := *v - pending.MemoryMB
				l.MemoryMB = min(l.MemoryMB, max(available, 0))
			}
			// CPU runners are using because it was lent them is not
			// taken: the next elastic plan gives it back to a start.
			if v := h.Usage.UnlentCPUPercent(); v != nil {
				hs.observedCPU[h.ID] = max(float64(h.CPUs)*(1-*v/100)-h.CPUReserve()-pending.CPUs, 0)
			}
		}
		hs.left[h.ID] = l
	}
	return hs
}

// placement is one runner placed by a pass: the host it goes on and, where no
// host had room for the pool's standard size, the smaller size it was given.
type placement struct {
	hostID string
	// size is nil for a runner at the pool's standard size.
	size *store.Resources
	// raised says size is larger than the standard, not smaller: the runner
	// was sized up to what the jobs waiting are known to need.
	raised bool
}

// place reserves up to n slots for the pool and returns the chosen host IDs.
// It may return fewer than n, or none at all, when the fleet is out of room.
func (hs *hostSet) place(p *store.Pool, n int) []string {
	var ids []string
	for _, pl := range hs.placeAvoiding(p, n, nil) {
		ids = append(ids, pl.hostID)
	}
	return ids
}

// placeAvoiding is place steered away from a set of hosts where another
// eligible one exists.
//
// It exists for the one create that already knows a specific host is a bad
// idea: a replacement for a job whose last runner just failed with
// FaultBackendBusy on that host. Avoiding it is worth doing only as long as
// somewhere else can take the runner -- pick still returns an avoided host
// rather than refuse the placement once it is the only one left, because a
// host that failed one create a few minutes ago is still better than no host
// at all.
//
// A runner goes at the pool's standard size wherever any host has room for
// it. Only when none has does a pool with a minimum fall back to a reduced
// size on the host that can spare the most -- so a minimum never shrinks a
// runner the fleet could have given the full size to.
func (hs *hostSet) placeAvoiding(p *store.Pool, n int, avoid map[string]bool) []placement {
	out := make([]placement, 0, n)
	for len(out) < n {
		var size *store.Resources
		h := hs.pick(p, avoid)
		res := Reservation{}
		if h != nil {
			res = Reserve(p, h)
		} else {
			var grant store.Resources
			h, res, grant = hs.pickReduced(p, avoid)
			if h == nil {
				break
			}
			size = &grant
		}
		raised := false
		if hs.need != nil {
			before := size
			res, size = sizeForNeed(p, res, size, *hs.need)
			raised = size != before
		}
		hs.free[h.ID]--
		hs.warming[h.ID]++
		l := hs.left[h.ID]
		l.CPUs -= res.CPUs
		l.MemoryMB -= res.MemoryMB
		l.DiskMB -= res.DiskMB
		hs.left[h.ID] = l
		hs.promisedMemory[h.ID] -= res.MemoryMB
		hs.ours[h.ID] = true
		if cpu, ok := hs.observedCPU[h.ID]; ok {
			hs.observedCPU[h.ID] = max(cpu-res.CPUs, 0)
		}
		out = append(out, placement{hostID: h.ID, size: size, raised: raised})
	}
	return out
}

// pickReduced is pick for a runner below its standard size: the host, among
// those that could take one otherwise, that can give it the most. It returns
// the host, the charge against it and the size to create the runner at, or a
// nil host when not even the minimum fits anywhere.
func (hs *hostSet) pickReduced(p *store.Pool, avoid map[string]bool) (*store.Host, Reservation, store.Resources) {
	if !p.Resources.Reducible() {
		return nil, Reservation{}, store.Resources{}
	}
	type option struct {
		h      *store.Host
		charge Reservation
		grant  store.Resources
		worth  float64
	}
	var best, bestAvoided *option
	for _, h := range hs.hosts {
		if hs.free[h.ID] <= 0 || !HostCanRun(h, p, hs.now) ||
			(hostUnderCPUPressure(h, hs.now) && hs.warming[h.ID] > 0) ||
			(hs.need != nil && hs.shortOf(h, p, *hs.need) != "") {
			continue
		}
		charge, grant, ok := ReducedSize(p, h, hs.leftFor(h, p), hs.alloc[h.ID])
		if !ok {
			continue
		}
		// How much of the standard this host can give, as a share of it: the
		// bigger the runner, the better the job goes. The standard is this
		// host's own, which for a field left to the host is its slot share.
		standard := Reserve(p, h)
		worth := 0.0
		if standard.CPUs > 0 {
			worth += charge.CPUs / standard.CPUs
		}
		if standard.MemoryMB > 0 {
			worth += float64(charge.MemoryMB) / float64(standard.MemoryMB)
		}
		o := &option{h: h, charge: charge, grant: grant, worth: worth}
		slot := &best
		if avoid[h.ID] {
			slot = &bestAvoided
		}
		if *slot == nil || o.worth > (*slot).worth || (o.worth == (*slot).worth && h.ID < (*slot).h.ID) {
			*slot = o
		}
	}
	if best == nil {
		best = bestAvoided
	}
	if best == nil {
		return nil, Reservation{}, store.Resources{}
	}
	return best.h, best.charge, best.grant
}

// pick prefers the host with the most proportional headroom after placing
// this pool's runner. It averages the CPU and memory fractions left, after
// eligibility has enforced every limit. The score is recomputed after every
// placement, across pools.
// Hosts with no CPU/memory specifications retain the slot rule; the host ID
// breaks exact ties.
//
// avoid is consulted only once every other eligible host has been ruled out:
// an avoided host is tracked alongside the rest and returned only when it is
// the best -- or only -- one left, so a hint to go elsewhere never turns into
// a refusal the fleet had room to avoid.
func (hs *hostSet) pick(p *store.Pool, avoid map[string]bool) *store.Host {
	var best, bestAvoided *store.Host
	for _, h := range hs.hosts {
		if !hs.eligible(h, p) {
			continue
		}
		if avoid[h.ID] {
			if bestAvoided == nil || hs.prefer(h, bestAvoided, p) {
				bestAvoided = h
			}
			continue
		}
		if best == nil || hs.prefer(h, best, p) {
			best = h
		}
	}
	if best != nil {
		return best
	}
	return bestAvoided
}

func (hs *hostSet) eligible(h *store.Host, p *store.Pool) bool {
	return hs.eligibleAsSized(h, p) && (hs.need == nil || hs.shortOf(h, p, *hs.need) == "")
}

// eligibleAsSized is eligible without a job history's requirement: whether h
// would take a runner of p at the pool's own size.
func (hs *hostSet) eligibleAsSized(h *store.Host, p *store.Pool) bool {
	return hs.free[h.ID] > 0 && hs.hasRoom(h, p) && HostCanRun(h, p, hs.now) &&
		!(hostUnderCPUPressure(h, hs.now) && hs.warming[h.ID] > 0)
}

// hasRoom reports whether what is still unpromised on the host covers one more
// runner of this pool.
func (hs *hostSet) hasRoom(h *store.Host, p *store.Pool) bool {
	return fits(hs.leftFor(h, p), Reserve(p, h), hs.alloc[h.ID])
}

// leftFor is the room on h as a runner of p sees it: left, with memory
// answered by memoryLeft.
func (hs *hostSet) leftFor(h *store.Host, p *store.Pool) Reservation {
	l := hs.left[h.ID]
	l.MemoryMB = hs.memoryLeft(h, p)
	return l
}

// memoryLeft is how much memory h can still give a runner of p.
//
// Usually the tighter of what is unpromised and what was measured free. The
// measurement is what catches work the reservations cannot see -- the runners
// already on the host using what they were promised, or something outside
// Zoomies using the machine -- and a runner must not be handed memory that is
// not there.
//
// The exception is an idle host and a pool that leaves its size to the host.
// Then the runner's share is carved out of allocatable, which is the machine
// less the reserve set aside for its own operating system -- and measured free
// memory is the machine less what that operating system actually uses. On a
// host whose system uses more than the reserve guessed, the second is always
// the smaller, so a share of the whole machine never fits it: a host of one
// slot refused its only slot at every pass, idle, with most of its memory
// free, and reported itself short of memory for it. Nothing of ours is there
// to protect, so the measurement has nothing to say that the pressure hold
// does not already say -- that stops every start once free memory falls to the
// reserve -- and reservation alone decides.
//
// A stated size keeps the measured check even on an idle host. An operator
// who wrote 8 GB meant the job needs it, and 6 GB free is not 8.
func (hs *hostSet) memoryLeft(h *store.Host, p *store.Pool) int64 {
	if p.Resources.MemoryMB <= 0 && !hs.ours[h.ID] {
		return hs.promisedMemory[h.ID]
	}
	return hs.left[h.ID].MemoryMB
}

// hostRunsOurs reports whether any live runner of ours is on h, in any pool.
func hostRunsOurs(h *store.Host, runners map[string][]*store.Runner) bool {
	for _, rs := range runners {
		for _, r := range rs {
			if r != nil && r.HostID == h.ID && r.State.Live() {
				return true
			}
		}
	}
	return false
}

// HostCanRun is the placement rule, in one place: a host may take a runner for
// a pool when it is available, offers the pool's backend and satisfies the
// pool's host selector, and is a machine one of its runners would fit on at
// all. The wizard's "matching hosts" count, the capacity-demand signal and
// image prewarming all ask this same question, and each used to answer it with
// a copy of its own that a new rule here would have left behind. Room left on
// the host is the scheduler's own accounting and is checked separately.
func HostCanRun(h *store.Host, p *store.Pool, now time.Time) bool {
	return HostAvailable(h, now) && HostCouldRun(h, p)
}

// HostCouldRun is that same rule with the weather left out: whether this host
// and this pool are configured to go together at all, whatever the host is
// doing at the moment.
//
// The split is what lets an edit be judged. Cordoning a host, or waiting for
// its agent, changes where a runner goes today; changing its labels or its
// reserve can change whether a pool has anywhere to go at all, and only the
// second is a conflict between two things an operator typed.
func HostCouldRun(h *store.Host, p *store.Pool) bool {
	return HostOffers(h, p) && HostIsPlatform(h, p) && HostSelects(h, p) && HostFits(h, p)
}

// HostIsPlatform reports whether a host is the machine the pool asked for.
//
// It is separate from HostSelects because it is not a selector: a selector is
// something an operator writes about their own fleet, and this is a promise the
// pool makes about what its runners are -- the same promise that picks the
// runner image. An empty field on either side constrains nothing, so a pool
// with no platform still goes anywhere and a host whose agent has not reported
// one is never ruled out.
func HostIsPlatform(h *store.Host, p *store.Pool) bool {
	return p.Platform.Matches(h.Platform())
}

// HostAvailable reports whether a host may take new runners at all: its agent
// is heartbeating, an operator has not cordoned it, and its agent speaks a
// protocol this controller understands. Fresh pressure measurements may also
// temporarily hold new starts without changing connectivity or the cordon.
//
// An incompatible agent is excluded here rather than refused at the door, so
// its existing runners keep working and are drained as normal. A fleet
// mid-upgrade shrinks host by host instead of falling over all at once.
func HostAvailable(h *store.Host, now time.Time) bool {
	return h.Healthy(now) && !h.Cordoned && !h.Incompatible && HostAdmissionReason(h, now) == ""
}

// HostOffers reports whether a host's agent offers the pool's backend.
func HostOffers(h *store.Host, p *store.Pool) bool {
	return slices.Contains(h.Backends, string(p.Backend))
}

// HostSelects reports whether a host satisfies the pool's host selector: every
// key of the selector answers with the value the selector asks for, and an
// empty selector means "any host".
//
// A host answers for its own labels and, for `os` and `arch`, for what its
// agent reported about the machine -- see Host.SelectorValue. So a pool may ask
// for arm64 or windows across a fleet nobody has labelled, which is the case
// this indirection exists for.
func HostSelects(h *store.Host, p *store.Pool) bool {
	for k, v := range p.HostSelector {
		if h.SelectorValue(k) != v {
			return false
		}
	}
	return true
}

// blockage is why one pool could not be placed: what is true, what to change,
// and the two facts the callers treat differently -- whether the fleet is
// merely full, and which other backends would work right now.
type blockage struct {
	what string
	fix  string
	// atCapacity is the one case that is not a misconfiguration: every host
	// could run this pool and all of them are busy.
	atCapacity bool
	// noEligibleHost is its opposite: not one host could take this pool's
	// runner whatever it finished. Waiting does not clear this one -- only a
	// host that can run the pool does, whether an operator adds it or a
	// provider rents it.
	noEligibleHost bool
	// alternatives are the backends offered by the hosts that match this pool
	// in every other way, in the order a pool would sensibly move to them.
	alternatives []string
}

// why explains why no host could take a runner for p, naming the counts an
// operator can act on. It is split into what is true and what to change,
// because the problems drawer shows those as two different things; sentence
// joins them for the one-line scaling reason.
func (hs *hostSet) why(p *store.Pool) blockage {
	if len(hs.hosts) == 0 {
		return blockage{
			what: "no agent hosts are registered, so there is nowhere to put a runner",
			fix:  "run 'zoomies agent' on a machine that can host runners, using a join token from the Hosts page",
			// An empty fleet is the purest form of "no host can ever run this":
			// there is nothing to wait for, and it is exactly the shortfall a
			// host provisioner exists to answer.
			noEligibleHost: true,
		}
	}
	var unhealthy, cordoned, incompatible, backend, platform, selector, tooSmall, full int
	var shortCPU, shortMemory, lowDisk, held, warming, throttled, committed int
	var detail string
	for _, h := range hs.hosts {
		switch {
		case !h.Healthy(hs.now):
			unhealthy++
		case h.Cordoned:
			cordoned++
		case h.Incompatible:
			incompatible++
		case !slices.Contains(h.Backends, string(p.Backend)):
			backend++
			// The agent's own probe usually names the fix -- a socket that is
			// not readable, a daemon that is not running -- and "without the
			// docker backend" alone sends an operator looking in the wrong
			// place. Take the first host that has an explanation.
			if detail == "" {
				if info, ok := h.BackendInfo.Find(p.Backend); ok && !info.Available && info.Detail != "" {
					detail = h.Name + " reports: " + info.Detail
				}
			}
		case !HostIsPlatform(h, p):
			platform++
		case !HostSelects(h, p):
			selector++
		case HostAdmissionReason(h, hs.now) != "":
			held++
			if detail == "" {
				detail = h.Name + ": " + HostAdmissionReason(h, hs.now)
			}
		case hostUnderCPUPressure(h, hs.now) && hs.warming[h.ID] > 0:
			warming++
		case h.Throttle.Active() && hs.free[h.ID] <= 0 && h.ActiveRunners < h.Capacity:
			// Slots the operator configured and the throttle has taken back.
			// It is its own count because "at capacity" would send an
			// operator to raise a capacity that is not the problem: the host
			// is being pushed too hard at the slots it already has.
			throttled++
			if detail == "" {
				detail = h.Name + ": " + ThrottleReason(h)
			}
		case hs.alloc[h.ID].DiskKnown && hs.alloc[h.ID].DiskMB <= 0:
			// The disk gate is asked before the sizing one, because a host at
			// its reserve refuses every pool and "too small for this pool's
			// limits" would send the operator to change limits that were never
			// the problem.
			lowDisk++
		case !HostFits(h, p):
			// The machine itself is too small for one runner of this pool, so
			// nothing finishing on it will ever make room. That is a different
			// answer from "wait", and an operator told to wait for it would
			// wait for ever.
			tooSmall++
		case hs.free[h.ID] <= 0:
			full++
		default:
			// It has a slot and is the right kind of machine, so what is left
			// on it is what ran out. Naming which resource is the difference
			// between adding memory and adding a host.
			//
			// It is measured against the minimum, because that is what the
			// pass has already failed to place: a host with memory for a
			// reduced runner and no CPU for one is short of CPU, and naming
			// memory would send the operator to add what the pool could
			// already run in.
			left, alloc, want := hs.leftFor(h, p), hs.alloc[h.ID], MinimumReserve(p, h)
			switch {
			case alloc.DiskKnown && (alloc.DiskMB <= 0 || left.DiskMB < want.DiskMB):
				lowDisk++
			case alloc.MemoryKnown && left.MemoryMB < want.MemoryMB:
				shortMemory++
				if hs.ours[h.ID] {
					committed++
				}
			case alloc.CPUsKnown && left.CPUs+cpuEpsilon < want.CPUs:
				shortCPU++
				if hs.ours[h.ID] {
					committed++
				}
			default:
				full++
			}
		}
	}
	var parts []string
	add := func(n int, what string) {
		if n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, what))
		}
	}
	add(unhealthy, "unhealthy")
	add(cordoned, "cordoned")
	add(incompatible, "running an agent this controller cannot talk to")
	add(backend, "without the "+string(p.Backend)+" backend")
	add(platform, "not "+p.Platform.Describe())
	add(selector, "not matching the pool's host selector")
	add(tooSmall, "too small for this pool's limits")
	add(shortMemory, "short of memory")
	add(shortCPU, "short of CPU")
	add(lowDisk, "low on disk")
	add(held, "holding new starts while host pressure clears")
	add(warming, "starting one runner at a time while CPU is busy")
	add(throttled, "throttled after sustained pressure")
	add(full, "at capacity")
	// onlyFull is the fleet whose every host is out of slots, as opposed to one
	// that is also short of memory or CPU. Both are "at capacity" to a caller,
	// but the fix text below tells them apart, so it asks this rather than
	// atCapacity.
	onlyFull := full+throttled == len(hs.hosts)
	b := blockage{
		what: fmt.Sprintf("no host can take a new %s runner (%s)",
			p.Backend, strings.Join(parts, ", ")),
		// A throttled host is full at the slots it has left, and to a
		// provisioner that is the same fact as full: more hosts is the one
		// answer that helps either way, so a fleet blocked only by throttles
		// asks for capacity exactly as a full one does.
		//
		// A host whose memory or CPU is promised to runners of ours is full in
		// the same sense: a free slot it cannot use until a job finishes and
		// returns what it holds. It counts only where a runner of ours is
		// there to return it -- a shortfall with none is pressure from outside
		// the fleet, which no job of ours finishing will ease, and it stays in
		// neither flag as it always has. Disk is never counted, because a
		// finishing runner leaves its caches behind on purpose.
		atCapacity: full+throttled+committed == len(hs.hosts),
		// Not one host was merely full, committed, throttled, held or warming,
		// so nothing finishing -- and no pressure easing -- frees a slot this
		// pool could use. The counts above already say which way each host
		// failed; this says only that none of them can be waited out.
		//
		// Full, committed and throttled hosts are waited out until a job ends
		// or the pressure eases, and a held or warming host lifts on its own;
		// each is a reason to wait rather than to buy. A machine takes minutes
		// to clone, and a hold raised by a thirty-second CPU spike is gone
		// before the clone finishes. Held and warming count in NEITHER flag on
		// purpose. In this one a held host would say no host could ever run
		// the pool, which is how a spike buys virtual machines and tells an
		// external provisioner to scale from zero; in atCapacity it would ask
		// for the same machines from the other direction. Counted in neither,
		// the pool is simply skipped and the next pass decides again, a minute
		// older and usually clear.
		noEligibleHost: full+throttled+committed+held+warming == 0,
	}
	if detail != "" {
		// The agent's own words about the backend it could not use. They name
		// the fix far more precisely than any count can.
		b.what += ". " + detail
	}
	switch {
	case throttled > 0 && held+warming == 0:
		// A throttle outlasts the pressure that raised it, so "wait for it
		// to clear" is only half the answer: a host that keeps being pushed
		// past its size is a host with too many slots, or pools whose limits
		// let a job take more of it than a slot's worth.
		b.fix = "wait for the throttle to lift, lower those hosts' capacity or the pools' limits so their runners fit the machine, or add a host; running jobs continue"
	case held+warming > 0:
		b.fix = "wait for host pressure to clear, reduce other work on those hosts, or add a compatible host; running jobs continue"
	case onlyFull:
		b.fix = "wait for a job to finish, raise a host's capacity, or add a host"
	case lowDisk > 0 && lowDisk+unhealthy+cordoned == len(hs.hosts):
		// Disk is the one of the three that no job finishing will return: a
		// runner that exits leaves its caches behind on purpose, so telling an
		// operator to wait here is telling them to wait for nothing.
		b.fix = "free space on those hosts' work directories, lower the pool's disk request, or add a host"
	case tooSmall > 0 && tooSmall+unhealthy+cordoned == len(hs.hosts):
		b.fix = "lower this pool's CPU or memory limits, or add a host large enough to run one"
	case shortMemory+shortCPU > 0 && shortMemory+shortCPU+unhealthy+cordoned == len(hs.hosts):
		switch {
		case p.Automatic() && !p.Resources.Reducible():
			// An automatic pool has no limits to lower. What it can be given
			// is a minimum, which lets a runner start with what is left of a
			// host's slot rather than waiting for a whole one.
			b.fix = "wait for a runner to finish, give this pool a minimum CPU and memory so a runner can start with less than a whole share of a host, or add a host"
		case p.Resources.Reducible():
			b.fix = "wait for a runner to finish, lower this pool's minimum, or add a host"
		default:
			b.fix = "wait for a runner to finish, lower this pool's limits, or add a host"
		}
	case incompatible > 0 && incompatible+unhealthy+cordoned == len(hs.hosts):
		// The one blockage whose fix is a version rather than a resource, and
		// the one an operator is least likely to guess: nothing is broken, the
		// hosts are up, and the fleet has simply stopped placing on them.
		b.fix = "upgrade the agent on those hosts to this controller's release; their existing runners keep working and are drained as normal"
	case unhealthy == len(hs.hosts):
		b.fix = "check that the zoomies agent is running on those hosts and can reach this controller"
	case platform > 0 && platform+unhealthy+cordoned == len(hs.hosts):
		// Naming the platform is the difference between an operator adding a
		// host and adding the *right* one: a pool that wants Ubuntu 24.04
		// arm64 will keep failing to place on the amd64 box they just built
		// unless the message says so.
		b.fix = fmt.Sprintf("add a %s host, or change this pool's platform to one your fleet already has",
			p.Platform.Describe())
	case backend > 0 && backend+unhealthy+cordoned == len(hs.hosts):
		// Only a pool blocked on its backend can be unblocked by changing it,
		// so that is the only case that carries alternatives. Offering them for
		// a full fleet or an unmatched selector would send an operator to
		// change the one thing that was never the problem.
		b.alternatives = hs.otherBackends(p)
		b.fix = fmt.Sprintf("make the %s backend usable on one of those hosts%s",
			p.Backend, hs.switchTo(p, b.alternatives))
	default:
		b.fix = "add a host, raise a host's capacity, uncordon one, or relax the pool's host selector"
	}
	return b
}

// backendOrder is the order alternatives are offered in: the two container
// backends first, since they are interchangeable as far as isolation goes, and
// the process backend last because moving to it means jobs stop being contained
// at all. It is a suggestion, never a change Zoomies makes by itself.
var backendOrder = []store.BackendKind{store.BackendDocker, store.BackendPodman, store.BackendProcess}

// otherBackends lists what the hosts that fit this pool in every other way --
// healthy, uncordoned, selected, with room -- do offer instead of the backend
// it asks for. It is the answer to "point this pool at a backend they already
// offer", which is not actionable until somebody says which one.
func (hs *hostSet) otherBackends(p *store.Pool) []string {
	offered := map[string]int{}
	for _, h := range hs.hosts {
		if hs.free[h.ID] <= 0 || !h.Healthy(hs.now) || h.Cordoned || h.Incompatible || !HostSelects(h, p) {
			continue
		}
		for _, kind := range h.Backends {
			if kind != string(p.Backend) {
				offered[kind]++
			}
		}
	}
	var out []string
	for _, kind := range backendOrder {
		if offered[string(kind)] > 0 {
			out = append(out, string(kind))
		}
	}
	return out
}

// switchTo turns the alternatives into the second half of the fix, or into an
// honest full stop when there is no second half: a fleet that offers nothing
// else needs a daemon fixed, and saying "or use another backend" to an operator
// who has none is how a problems drawer stops being believed.
func (hs *hostSet) switchTo(p *store.Pool, alternatives []string) string {
	switch len(alternatives) {
	case 0:
		return "; they offer no other backend to switch this pool to"
	case 1:
		return fmt.Sprintf(", or point this pool at %s, which %s already offers",
			alternatives[0], plural(hs.offering(p, alternatives[0]), "host"))
	default:
		var parts []string
		for _, kind := range alternatives {
			parts = append(parts, fmt.Sprintf("%s (%s)", kind, plural(hs.offering(p, kind), "host")))
		}
		return ", or point this pool at a backend they already offer: " + strings.Join(parts, ", ")
	}
}

// offering counts the hosts that would take this pool if it asked for kind.
func (hs *hostSet) offering(p *store.Pool, kind string) int {
	n := 0
	for _, h := range hs.hosts {
		if hs.free[h.ID] > 0 && h.Healthy(hs.now) && !h.Cordoned && !h.Incompatible &&
			slices.Contains(h.Backends, kind) && HostSelects(h, p) {
			n++
		}
	}
	return n
}

// sentence is why() as one line, for the scaling reason an operator reads in a
// pool's history.
func sentence(what, fix string) string {
	if fix == "" {
		return what
	}
	return what + "; " + fix
}

// ---------------------------------------------------------------------------
// Reasons
// ---------------------------------------------------------------------------

// scaled renders the sentence the UI and the scaling_events table show:
// "scaled linux-x64 2 -> 4: 3 jobs queued > 30s".
func scaled(pool string, from, to int, why string) string {
	return fmt.Sprintf("scaled %s %d -> %d: %s", pool, from, to, why)
}

// cannotScale renders the same sentence for a scale-up that could not happen,
// because an operator needs to see the demand that went unserved.
func cannotScale(pool string, from, to int, why string) string {
	return fmt.Sprintf("cannot scale %s %d -> %d: %s", pool, from, to, why)
}

// upReason names the demand behind a scale-up. Jobs win over the pool minimum
// because that is what the operator is watching when a queue is backing up.
func upReason(p *store.Pool, busy, eligible int, delay time.Duration) string {
	if eligible == 0 || busy+eligible < p.MinRunners {
		return fmt.Sprintf("pool minimum is %s", plural(p.MinRunners, "runner"))
	}
	if delay <= 0 {
		return plural(eligible, "job") + " queued"
	}
	return fmt.Sprintf("%s queued > %s", plural(eligible, "job"), formatDuration(delay))
}

func plural(n int, unit string) string {
	if n == 1 {
		return "1 " + unit
	}
	return fmt.Sprintf("%d %ss", n, unit)
}

// FormatDuration renders a duration the way every scheduler sentence does, so
// a caller outside the package that names one of its constants -- the wizard
// naming the throttle's recovery -- reads the same as the host card.
func FormatDuration(d time.Duration) string { return formatDuration(d) }

// formatDuration is time.Duration.String() without the trailing zero units, so
// an operator reads "5m" and "6h" rather than "5m0s" and "6h0m0s".
func formatDuration(d time.Duration) string {
	s := d.String()
	if strings.HasSuffix(s, "m0s") {
		s = s[:len(s)-2]
	}
	if strings.HasSuffix(s, "h0m") {
		s = s[:len(s)-2]
	}
	return s
}

// ---------------------------------------------------------------------------
// Deterministic ordering
// ---------------------------------------------------------------------------

func sortedPools(in []*store.Pool) []*store.Pool {
	out := compact(in)
	slices.SortStableFunc(out, func(a, b *store.Pool) int {
		if c := strings.Compare(a.Name, b.Name); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

func sortedRunners(in []*store.Runner) []*store.Runner {
	out := compact(in)
	slices.SortStableFunc(out, func(a, b *store.Runner) int {
		if c := a.CreatedAt.Compare(b.CreatedAt); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

func sortedJobs(in []*store.Job) []*store.Job {
	out := compact(in)
	slices.SortStableFunc(out, func(a, b *store.Job) int {
		if a.ProvisionNow != b.ProvisionNow {
			if a.ProvisionNow {
				return -1
			}
			return 1
		}
		if c := a.QueuedAt.Compare(b.QueuedAt); c != 0 {
			return c
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out
}

func sortedHosts(in []*store.Host) []*store.Host {
	out := compact(in)
	slices.SortStableFunc(out, func(a, b *store.Host) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// compact copies a slice without its nil entries, so that sorting never
// reorders the caller's own slice and a stray nil cannot panic a decision.
func compact[T any](in []*T) []*T {
	out := make([]*T, 0, len(in))
	for _, v := range in {
		if v != nil {
			out = append(out, v)
		}
	}
	return out
}

// idleSince is the instant a runner became idle, or its creation time when the
// agent never reported one.
func idleSince(r *store.Runner) time.Time {
	if r.LastIdleAt != nil {
		return *r.LastIdleAt
	}
	return r.CreatedAt
}

func starting(s store.RunnerState) bool {
	return s == store.RunnerProvisioning || s == store.RunnerRegistering
}

func clamp(v, lo, hi int) int {
	if hi < lo {
		// A pool whose max is below its min is a misconfiguration; the hard cap
		// wins, because exceeding it is what costs money.
		return hi
	}
	return min(max(v, lo), hi)
}

package scheduler

import (
	"encoding/json"
	"fmt"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// now is the decision time every test uses; ages are expressed relative to it.
var now = time.Date(2025, 3, 4, 12, 0, 0, 0, time.UTC)

func ago(d time.Duration) time.Time { return now.Add(-d) }

// testPolicy is the shipped default policy, with the scale-up delay off so that
// a test opts into it explicitly.
func testPolicy() Policy {
	return Policy{
		ScaleUpDelay:      0,
		MaxRunnerLifetime: 6 * time.Hour,
		ProvisionTimeout:  5 * time.Minute,
		DrainTimeout:      15 * time.Minute,
		MaxCreatesPerTick: 10,
	}
}

// testInstallation is the one GitHub App installation almost every test runs
// under: a pool and a job that share it are eligible for each other, so a case
// that says nothing about installations exercises the label rule alone. The
// cross-installation cases name their own.
const testInstallation = "ins_acme"

func testPool(name string, labels ...string) *store.Pool {
	return &store.Pool{
		ID:             "pool_" + name,
		Name:           name,
		InstallationID: testInstallation,
		Labels:         store.NormalizeLabels(labels),
		Backend:        store.BackendDocker,
		MaxRunners:     10,
		IdleTimeout:    store.Duration(5 * time.Minute),
		Ephemeral:      true,
		Enabled:        true,
	}
}

func testHost(id string, capacity, active int) *store.Host {
	return &store.Host{
		ID: id, Name: id, Capacity: capacity, ActiveRunners: active,
		Backends: store.StringSlice{"docker"}, LastHeartbeat: now,
	}
}

func testRunner(id string, p *store.Pool, state store.RunnerState, age time.Duration) *store.Runner {
	return &store.Runner{ID: id, PoolID: p.ID, HostID: "host_a", Name: id, State: state, CreatedAt: ago(age)}
}

// idleRunner is a runner that has been idle for idleFor and alive a little
// longer, which is the shape every scale-down test needs.
func idleRunner(id string, p *store.Pool, idleFor time.Duration) *store.Runner {
	r := testRunner(id, p, store.RunnerIdle, idleFor+time.Minute)
	since := ago(idleFor)
	r.LastIdleAt = &since
	return r
}

func queued(id string, waited time.Duration, labels ...string) *store.Job {
	return &store.Job{
		ID: id, Repo: "acme/widgets", JobName: id, State: store.JobQueued,
		InstallationID: testInstallation,
		Labels:         store.StringSlice(labels), QueuedAt: ago(waited),
	}
}

// snap assembles a snapshot, filing each runner under its own pool.
func snap(pools []*store.Pool, runners []*store.Runner, jobs []*store.Job, hosts []*store.Host) Snapshot {
	byPool := map[string][]*store.Runner{}
	for _, r := range runners {
		byPool[r.PoolID] = append(byPool[r.PoolID], r)
	}
	return Snapshot{Now: now, Pools: pools, Runners: byPool, Jobs: jobs, Hosts: hosts,
		Installations: []*store.Installation{{ID: testInstallation, Target: "acme", TargetType: store.TargetOrg}},
		Policy:        testPolicy()}
}

func actionsOf(as []Action, kind ActionKind) []Action {
	var out []Action
	for _, a := range as {
		if a.Kind == kind {
			out = append(out, a)
		}
	}
	return out
}

// A runner that just failed to start with FaultBackendBusy is not sent
// straight back to the host that failed it: grant steers the next create for
// this pool toward any other eligible host instead, via recentBusyHosts, so
// one host having a busy moment does not collect every retry in a row.
func TestACreateAvoidsTheHostItsPoolsLastRunnerFailedBusyOn(t *testing.T) {
	p := testPool("shared", "self-hosted")
	failed := testRunner("r_busy", p, store.RunnerFailed, time.Minute)
	failed.HostID = "host_a"
	failed.FaultKind = store.FaultBackendBusy
	job := queued("job-1", time.Minute, "self-hosted")
	s := snap([]*store.Pool{p}, []*store.Runner{failed}, []*store.Job{job},
		[]*store.Host{testHost("host_a", 4, 0), testHost("host_b", 4, 0)})

	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 {
		t.Fatalf("creates = %d, want 1", len(creates))
	}
	if creates[0].HostID != "host_b" {
		t.Fatalf("HostID = %q, want the host that did not just fail this pool a create", creates[0].HostID)
	}
}

// Avoiding the host that just failed is a preference, not a refusal: when it
// is the only host this pool can use, the create still goes there rather than
// leaving the job queued for a host that is never going to appear.
func TestACreateStillUsesTheOnlyHostAfterABusyFailureThere(t *testing.T) {
	p := testPool("shared", "self-hosted")
	failed := testRunner("r_busy", p, store.RunnerFailed, time.Minute)
	failed.HostID = "host_a"
	failed.FaultKind = store.FaultBackendBusy
	job := queued("job-1", time.Minute, "self-hosted")
	s := snap([]*store.Pool{p}, []*store.Runner{failed}, []*store.Job{job},
		[]*store.Host{testHost("host_a", 4, 0)})

	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "host_a" {
		t.Fatalf("creates = %+v, want one create still using the pool's only host", creates)
	}
}

// A non-busy start failure says nothing about which host to avoid: an image
// that will not pull fails the same way on every host, so steering away from
// this one would only rebalance a failure that is not the host's fault.
func TestANonBusyStartFailureDoesNotSteerTheNextCreate(t *testing.T) {
	p := testPool("shared", "self-hosted")
	failed := testRunner("r_bad_image", p, store.RunnerFailed, time.Minute)
	failed.HostID = "host_a"
	failed.FaultKind = store.FaultImage
	job := queued("job-1", time.Minute, "self-hosted")
	s := snap([]*store.Pool{p}, []*store.Runner{failed}, []*store.Job{job},
		[]*store.Host{testHost("host_a", 4, 0), testHost("host_b", 4, 0)})

	pp := only(t, Decide(s))
	creates := actionsOf(pp.Actions, ActionCreate)
	if len(creates) != 1 || creates[0].HostID != "host_a" {
		t.Fatalf("creates = %+v, want the ordinary best-headroom host, unsteered by a non-busy failure", creates)
	}
}

func TestRepositoryScaleUpLimitDoesNotConsumeAnotherRepositoriesCapacity(t *testing.T) {
	p := testPool("shared", "self-hosted")
	p.RepositoryScaleUpLimit = 1
	blocked := queued("blocked", time.Minute, "self-hosted")
	other := queued("other", time.Minute, "self-hosted")
	other.Repo = "acme/other"
	s := snap([]*store.Pool{p}, nil, []*store.Job{blocked, other}, []*store.Host{testHost("host_a", 2, 0)})
	s.ActiveByRepository = map[string]int{p.ID + "\x00acme/widgets": 1}
	plan := Decide(s)
	if got := len(actionsOf(plan.Actions, ActionCreate)); got != 1 {
		t.Fatalf("creates = %d, want one for unblocked repository", got)
	}
	if plan.Pools[0].Blocked != "" {
		t.Fatalf("blocked = %q, want admitted work to keep the pool unblocked", plan.Pools[0].Blocked)
	}
	if plan.Pools[0].QuotaDeferredJobs != 1 || !slices.Equal(plan.Pools[0].QuotaDeferredRepositories, []string{"acme/widgets"}) {
		t.Fatalf("quota deferral = %+v", plan.Pools[0])
	}
}

func TestRepositoryScaleUpLimitWithWarmIdleRunnerIsOnlyAThrottle(t *testing.T) {
	p := testPool("shared", "self-hosted")
	p.RepositoryScaleUpLimit = 1
	idle := idleRunner("warm", p, time.Minute)
	job := queued("deferred", time.Minute, "self-hosted")
	s := snap([]*store.Pool{p}, []*store.Runner{idle}, []*store.Job{job}, []*store.Host{testHost("host_a", 2, 1)})
	s.ActiveByRepository = map[string]int{p.ID + "\x00" + job.Repo: 1}

	pp := only(t, Decide(s))
	if pp.Blocked != "" || countOf(pp.Actions, ActionCreate) != 0 {
		t.Fatalf("plan = %+v, want a deferral rather than pool blockage or creation", pp)
	}
	if pp.QuotaDeferredJobs != 1 || pp.Current != 1 || pp.Desired != 0 {
		t.Fatalf("plan = %+v, want the not-yet-expired idle runner retained and the job reported deferred", pp)
	}
}

func TestRepositoryScaleUpLimitPreservesMinimumForNonEphemeralPool(t *testing.T) {
	p := testPool("durable", "self-hosted")
	p.RepositoryScaleUpLimit, p.MinRunners, p.Ephemeral = 1, 2, false
	job := queued("deferred", time.Minute, "self-hosted")
	s := snap([]*store.Pool{p}, nil, []*store.Job{job}, []*store.Host{testHost("host_a", 4, 0)})
	s.ActiveByRepository = map[string]int{p.ID + "\x00" + job.Repo: 1}

	pp := only(t, Decide(s))
	if pp.Desired != 2 || countOf(pp.Actions, ActionCreate) != 2 {
		t.Fatalf("plan = %+v, want min_runners to create two durable warm runners", pp)
	}
	if pp.QuotaDeferredJobs != 1 || pp.Blocked != "" {
		t.Fatalf("plan = %+v, want quota metadata separate from blocked", pp)
	}
}

// A job that has not waited out the scale-up delay is not deferred by the
// repository limit; it is just new.
//
// Both make a job wait, and only one of them is something an operator can do
// anything about. Charging the limit for a job the delay was holding anyway
// put "1 job deferred by the repository limit for acme/widgets" on a pool
// whose queue the next few seconds were going to release on its own, and sent
// whoever read it to raise a setting that was not the cause.
func TestTheRepositoryLimitIsNotBlamedForTheScaleUpDelay(t *testing.T) {
	p := testPool("shared", "self-hosted")
	p.RepositoryScaleUpLimit = 1
	fresh := queued("fresh", time.Second, "self-hosted")

	s := snap([]*store.Pool{p}, nil, []*store.Job{fresh}, []*store.Host{testHost("host_a", 2, 0)})
	s.Policy.ScaleUpDelay = 30 * time.Second
	s.ActiveByRepository = map[string]int{p.ID + "\x00" + fresh.Repo: 1}

	pp := only(t, Decide(s))
	if pp.QuotaDeferredJobs != 0 || len(pp.QuotaDeferredRepositories) != 0 {
		t.Fatalf("plan = %+v, want a job inside the scale-up delay charged to the delay, not the repository limit", pp)
	}
	if countOf(pp.Actions, ActionCreate) != 0 {
		t.Fatal("a job inside the scale-up delay drove a create")
	}

	// The same job, once it is old enough, is the limit's to defer.
	s.Jobs = []*store.Job{queued("fresh", time.Minute, "self-hosted")}
	pp = only(t, Decide(s))
	if pp.QuotaDeferredJobs != 1 || !slices.Equal(pp.QuotaDeferredRepositories, []string{"acme/widgets"}) {
		t.Fatalf("plan = %+v, want the job deferred by the repository limit once it is past the delay", pp)
	}
}

func countOf(as []Action, kind ActionKind) int { return len(actionsOf(as, kind)) }

func runnerIDs(as []Action, kind ActionKind) []string {
	var out []string
	for _, a := range actionsOf(as, kind) {
		out = append(out, a.RunnerID)
	}
	return out
}

func hostIDs(as []Action) []string {
	var out []string
	for _, a := range actionsOf(as, ActionCreate) {
		out = append(out, a.HostID)
	}
	return out
}

// only returns the single pool plan in a plan, failing when there is not
// exactly one.
func only(t *testing.T, p Plan) PoolPlan {
	t.Helper()
	if len(p.Pools) != 1 {
		t.Fatalf("expected 1 pool plan, got %d", len(p.Pools))
	}
	return p.Pools[0]
}

// ---------------------------------------------------------------------------
// Scale up
// ---------------------------------------------------------------------------

func TestScaleUpFromZero(t *testing.T) {
	p := testPool("linux-x64", "linux", "x64")
	s := snap([]*store.Pool{p}, nil,
		[]*store.Job{
			queued("j1", time.Minute, "self-hosted", "linux", "x64"),
			queued("j2", time.Minute, "self-hosted", "linux", "x64"),
			queued("j3", time.Minute, "self-hosted", "linux", "x64"),
		},
		[]*store.Host{testHost("host_a", 8, 0)})

	plan := Decide(s)
	pp := only(t, plan)
	if pp.Current != 0 || pp.Desired != 3 || pp.QueuedMatched != 3 {
		t.Fatalf("got current=%d desired=%d queued=%d, want 0/3/3", pp.Current, pp.Desired, pp.QueuedMatched)
	}
	if n := countOf(pp.Actions, ActionCreate); n != 3 {
		t.Fatalf("got %d creates, want 3", n)
	}
	if want := "scaled linux-x64 0 -> 3: 3 jobs queued"; pp.Reason != want {
		t.Fatalf("reason = %q, want %q", pp.Reason, want)
	}
	for _, a := range pp.Actions {
		if a.HostID != "host_a" || a.PoolID != p.ID || a.PoolName != p.Name || a.RunnerID != "" {
			t.Fatalf("unexpected create action %+v", a)
		}
	}
	if len(plan.Actions) != len(pp.Actions) {
		t.Fatalf("flattened actions = %d, want %d", len(plan.Actions), len(pp.Actions))
	}
	if len(plan.Unmatched) != 0 {
		t.Fatalf("unexpected unmatched jobs: %v", plan.Unmatched)
	}
}

func TestScaleUpReasonNamesTheDelay(t *testing.T) {
	p := testPool("linux-x64", "linux", "x64")
	s := snap([]*store.Pool{p}, nil,
		[]*store.Job{queued("j1", time.Minute, "linux"), queued("j2", time.Minute, "linux")},
		[]*store.Host{testHost("host_a", 8, 0)})
	s.Policy.ScaleUpDelay = 30 * time.Second

	pp := only(t, Decide(s))
	if want := "scaled linux-x64 0 -> 2: 2 jobs queued > 30s"; pp.Reason != want {
		t.Fatalf("reason = %q, want %q", pp.Reason, want)
	}
	if got := actionsOf(pp.Actions, ActionCreate)[0].Reason; got != "2 jobs queued > 30s" {
		t.Fatalf("action reason = %q", got)
	}
}

func TestScaleUpRespectsScaleUpDelay(t *testing.T) {
	p := testPool("linux-x64", "linux")
	s := snap([]*store.Pool{p}, nil,
		[]*store.Job{queued("j1", time.Second, "linux")},
		[]*store.Host{testHost("host_a", 8, 0)})
	s.Policy.ScaleUpDelay = 30 * time.Second

	pp := only(t, Decide(s))
	if len(pp.Actions) != 0 || pp.Reason != "" {
		t.Fatalf("a job queued 1s ago scaled the pool: %+v", pp)
	}
	if pp.Desired != 0 {
		t.Fatalf("desired = %d, want 0", pp.Desired)
	}
	if pp.QueuedMatched != 1 {
		t.Fatalf("queued matched = %d, want 1: the job is still demand, just not yet actionable", pp.QueuedMatched)
	}
}

func TestScaleUpAtTheDelayBoundary(t *testing.T) {
	p := testPool("linux-x64", "linux")
	s := snap([]*store.Pool{p}, nil,
		[]*store.Job{queued("j1", 30*time.Second, "linux")},
		[]*store.Host{testHost("host_a", 8, 0)})
	s.Policy.ScaleUpDelay = 30 * time.Second

	if n := countOf(only(t, Decide(s)).Actions, ActionCreate); n != 1 {
		t.Fatalf("a job queued for exactly the delay produced %d creates, want 1", n)
	}
}

func TestScaleUpRespectsPoolMax(t *testing.T) {
	p := testPool("linux-x64", "linux")
	p.MaxRunners = 2
	jobs := []*store.Job{
		queued("j1", time.Minute, "linux"), queued("j2", time.Minute, "linux"),
		queued("j3", time.Minute, "linux"), queued("j4", time.Minute, "linux"),
	}
	pp := only(t, Decide(snap([]*store.Pool{p}, nil, jobs, []*store.Host{testHost("host_a", 8, 0)})))

	if pp.Desired != 2 {
		t.Fatalf("desired = %d, want 2 (the pool max)", pp.Desired)
	}
	if n := countOf(pp.Actions, ActionCreate); n != 2 {
		t.Fatalf("got %d creates, want 2", n)
	}
	if want := "scaled linux-x64 0 -> 2: 4 jobs queued"; pp.Reason != want {
		t.Fatalf("reason = %q, want %q", pp.Reason, want)
	}
}

func TestScaleUpRespectsMaxCreatesPerTick(t *testing.T) {
	p := testPool("linux-x64", "linux")
	var jobs []*store.Job
	for _, id := range []string{"j1", "j2", "j3", "j4", "j5"} {
		jobs = append(jobs, queued(id, time.Minute, "linux"))
	}
	s := snap([]*store.Pool{p}, nil, jobs, []*store.Host{testHost("host_a", 8, 0)})
	s.Policy.MaxCreatesPerTick = 2

	pp := only(t, Decide(s))
	if n := countOf(pp.Actions, ActionCreate); n != 2 {
		t.Fatalf("got %d creates, want 2", n)
	}
	if pp.Desired != 5 {
		t.Fatalf("desired = %d, want 5: the cap limits this tick, not the target", pp.Desired)
	}
	if want := "cannot scale linux-x64 2 -> 5: this tick's global limit of 2 new runners is exhausted; the next pass will continue"; pp.Reason != want {
		t.Fatalf("reason = %q, want %q", pp.Reason, want)
	}
}

func TestMaxCreatesPerTickIsAFleetBudget(t *testing.T) {
	first, second := testPool("aaa", "aaa"), testPool("zzz", "zzz")
	s := snap([]*store.Pool{second, first},
		nil,
		[]*store.Job{queued("j1", time.Minute, "aaa"), queued("j2", time.Minute, "zzz")},
		[]*store.Host{testHost("host_a", 8, 0)})
	s.Policy.MaxCreatesPerTick = 1

	plan := Decide(s)
	if len(plan.Actions) != 1 || plan.Actions[0].PoolName != "aaa" {
		t.Fatalf("the budget was not spent on the first pool by name: %+v", plan.Actions)
	}
	want := "cannot scale zzz 0 -> 1: this tick's global limit of 1 new runner is exhausted; the next pass will continue"
	if got := plan.Pools[1].Reason; got != want {
		t.Fatalf("reason = %q, want %q", got, want)
	}
}

func TestCreateBudgetIsRoundRobinAcrossUnequalShortfalls(t *testing.T) {
	a, b, c := testPool("aaa", "aaa"), testPool("bbb", "bbb"), testPool("ccc", "ccc")
	jobs := []*store.Job{queued("a1", time.Minute, "aaa"), queued("a2", time.Minute, "aaa"), queued("a3", time.Minute, "aaa"),
		queued("b1", time.Minute, "bbb"), queued("c1", time.Minute, "ccc"), queued("c2", time.Minute, "ccc")}
	s := snap([]*store.Pool{c, a, b}, nil, jobs, []*store.Host{testHost("host_a", 20, 0)})
	s.Policy.MaxCreatesPerTick = 4

	plan := Decide(s)
	want := map[string]int{"aaa": 2, "bbb": 1, "ccc": 1}
	for _, pp := range plan.Pools {
		if got := countOf(pp.Actions, ActionCreate); got != want[pp.PoolName] {
			t.Errorf("%s creates = %d, want %d", pp.PoolName, got, want[pp.PoolName])
		}
	}
	if !strings.Contains(plan.Pools[2].Reason, "global limit") {
		t.Fatalf("deferred pool reason = %q, want global budget", plan.Pools[2].Reason)
	}
}

func TestCreateBudgetHonoursPriorityAndReportsCapacitySeparately(t *testing.T) {
	highA, highB := testPool("high-a", "ha"), testPool("high-b", "hb")
	low := testPool("low", "low")
	highA.Priority, highB.Priority, low.Priority = 10, 10, 0
	jobs := []*store.Job{queued("ha1", time.Minute, "ha"), queued("ha2", time.Minute, "ha"),
		queued("hb1", time.Minute, "hb"), queued("hb2", time.Minute, "hb"), queued("low1", time.Minute, "low")}
	s := snap([]*store.Pool{low, highB, highA}, nil, jobs, []*store.Host{testHost("host_a", 3, 0)})
	s.Policy.MaxCreatesPerTick = 5

	plan := Decide(s)
	if countOf(plan.Pools[0].Actions, ActionCreate) != 2 || countOf(plan.Pools[1].Actions, ActionCreate) != 1 {
		t.Fatalf("high-priority tier was not served round-robin: %+v", plan.Actions)
	}
	if plan.Pools[1].Blocked == "" || !strings.Contains(plan.Pools[1].Reason, "at capacity") {
		t.Fatalf("capacity-deferred high pool = %+v, want host-capacity reason", plan.Pools[1])
	}
	if plan.Pools[2].Blocked == "" || !strings.Contains(plan.Pools[2].Reason, "at capacity") {
		t.Fatalf("capacity-deferred low pool = %+v, want host-capacity reason", plan.Pools[2])
	}
}

func TestMinRunnersScalesUpWithoutDemand(t *testing.T) {
	p := testPool("linux-x64", "linux")
	p.MinRunners = 2
	pp := only(t, Decide(snap([]*store.Pool{p}, nil, nil, []*store.Host{testHost("host_a", 8, 0)})))

	if pp.Desired != 2 || countOf(pp.Actions, ActionCreate) != 2 {
		t.Fatalf("got desired=%d creates=%d, want 2/2", pp.Desired, countOf(pp.Actions, ActionCreate))
	}
	if want := "scaled linux-x64 0 -> 2: pool minimum is 2 runners"; pp.Reason != want {
		t.Fatalf("reason = %q, want %q", pp.Reason, want)
	}
}

// Pool membership is a live predicate, not a list captured by the pool wizard.
// A host that joins after the pool was created must be considered on the very
// next pass when its backend, platform and selector values fit the pool.
func TestNewMatchingHostAutomaticallyExpandsAnExistingPool(t *testing.T) {
	p := testPool("linux", "self-hosted")
	p.MinRunners = 1
	p.HostSelector = store.StringMap{"arch": "arm64"}

	before := only(t, Decide(snap([]*store.Pool{p}, nil, nil, nil)))
	if !strings.Contains(before.Blocked, "no agent hosts") {
		t.Fatalf("before host joined = %+v, want the existing pool blocked on having no host", before)
	}

	joined := testHost("new-host", 4, 0)
	joined.Arch = "arm64"
	after := only(t, Decide(snap([]*store.Pool{p}, nil, nil, []*store.Host{joined})))
	if after.Blocked != "" || countOf(after.Actions, ActionCreate) != 1 {
		t.Fatalf("after matching host joined = %+v, want one runner created without editing the pool", after)
	}
	if after.Actions[0].HostID != joined.ID {
		t.Fatalf("runner host = %q, want newly joined host %q", after.Actions[0].HostID, joined.ID)
	}
}

