// A pool that cannot start a runner waits, and the wait doubles with each
// failure. Every pool broken by the same thing -- a daemon that went down, a
// registry that stopped answering -- counts the same doubling from the same
// failure, so without jitter they all come back in the same second and the
// recovery arrives as the same herd that broke them.
func TestTheStartBackoffIsSpreadByTheJitterTheSnapshotCarries(t *testing.T) {
	p := testPool("builders", "self-hosted")
	// One start failure: the wait is the base backoff, and the pool is exactly
	// far enough past it to be let go with no jitter at all.
	failed := testRunner("run_dead", p, store.RunnerFailed, time.Minute)
	when := ago(startBackoff + time.Second)
	failed.FinishedAt = &when

	held := func(jitter float64) bool {
		s := snap([]*store.Pool{p}, []*store.Runner{failed}, []*store.Job{queued("job_1", time.Minute, "self-hosted")},
			[]*store.Host{testHost("host_a", 4, 0)})
		s.Jitter = map[string]float64{p.ID: jitter}
		return only(t, Decide(s)).Failing != ""
	}

	if held(0) {
		t.Fatal("with no jitter the wait is out, so the pool may try again")
	}
	// The same pool, at the same instant, with the jitter drawn high: the wait
	// is longer and it is still holding.
	if !held(1) {
		t.Fatal("the jitter was not applied, so every pool that broke together retries together")
	}
}

// Jitter only ever lengthens a wait. Shortening it would let the pool failing
// hardest come back soonest, which is the opposite of what the doubling is for.
func TestJitterNeverShortensAWait(t *testing.T) {
	for _, f := range []float64{0, 0.5, 1, 2, -1} {
		if got := jittered(time.Minute, f); got < time.Minute {
			t.Fatalf("jittered(1m, %v) = %s, which is shorter than the wait it spreads", f, got)
		}
		if got := jittered(time.Minute, f); got > time.Minute+time.Duration(startBackoffJitter*float64(time.Minute)) {
			t.Fatalf("jittered(1m, %v) = %s, which is past the share it may add", f, got)
		}
	}
}

// A pool whose installation GitHub is rate-limiting creates nothing. The
// request would be refused identically, spend another call against a quota
// that is already gone, and leave a failed row whose only message is the
// refusal -- and the pool would then back off from its own failures on top of
// the hold GitHub asked for. Scaling down asks GitHub for nothing, so it
// still happens.
func TestARateLimitedInstallationHoldsCreatesButNotDrains(t *testing.T) {
	p := testPool("linux-x64", "linux", "x64")
	s := snap([]*store.Pool{p}, nil,
		[]*store.Job{queued("j1", time.Minute, "linux", "x64")},
		[]*store.Host{testHost("host_a", 8, 0)})
	s.HeldInstallations = map[string]time.Time{testInstallation: now.Add(7 * time.Minute)}

	pp := only(t, Decide(s))
	if n := countOf(pp.Actions, ActionCreate); n != 0 {
		t.Fatalf("got %d creates for a held installation, want 0", n)
	}
	if pp.Held == "" || !strings.Contains(pp.Held, "7m") {
		t.Fatalf("Held = %q, want it to say how long the hold lasts", pp.Held)
	}
	if !strings.Contains(pp.Reason, "rate-limiting") {
		t.Fatalf("reason = %q, want it to name the hold", pp.Reason)
	}
	if pp.Blocked != "" {
		t.Fatalf("Blocked = %q; a hold is not a placement failure", pp.Blocked)
	}

	// An expired hold is no hold. The controller drops these as it reads
	// them, but the scheduler must not depend on that.
	s.HeldInstallations[testInstallation] = now.Add(-time.Second)
	pp = only(t, Decide(s))
	if n := countOf(pp.Actions, ActionCreate); n != 1 {
		t.Fatalf("got %d creates after the hold expired, want 1", n)
	}
	if pp.Held != "" {
		t.Fatalf("Held = %q after the hold expired, want empty", pp.Held)
	}

	// Another installation's hold is not this pool's.
	s.HeldInstallations = map[string]time.Time{"ins_someoneelse": now.Add(time.Hour)}
	if pp := only(t, Decide(s)); countOf(pp.Actions, ActionCreate) != 1 {
		t.Fatalf("a hold on another installation stopped this pool creating")
	}

	// And a held pool still scales down.
	s.HeldInstallations = map[string]time.Time{testInstallation: now.Add(time.Hour)}
	s.Jobs = nil
	s.Runners[p.ID] = []*store.Runner{idleRunner("r1", p, time.Hour)}
	pp = only(t, Decide(s))
	if n := countOf(pp.Actions, ActionDrain); n != 1 {
		t.Fatalf("got %d drains while held, want 1: draining asks GitHub for nothing", n)
	}
}

// A host that goes quiet is given up as lost and its runners are failed, and
// when it comes back with a job still running the workload is deliberately
// left to finish. The reap must not undo that: removing the row removes the
// container, and the job with it, for no reason but tidiness.
func TestAFailedRunnerStillRunningAJobIsNotReaped(t *testing.T) {
	p := testPool("linux-x64", "linux")
	r := testRunner("r1", p, store.RunnerFailed, 11*time.Minute)
	hosts := []*store.Host{testHost("host_a", 8, 1)}
	running := &store.Job{ID: "job_1", PoolID: p.ID, RunnerID: "r1", State: store.JobInProgress,
		Repo: "acme/widgets", InstallationID: testInstallation}

	pp := only(t, Decide(snap([]*store.Pool{p}, []*store.Runner{r}, []*store.Job{running}, hosts)))
	if got := actionsOf(pp.Actions, ActionRemove); len(got) != 0 {
		t.Fatalf("a failed runner with a job still on it was removed: %+v", got)
	}

	// Once the job has ended the row goes the way every failed row goes.
	running.State = store.JobCompleted
	pp = only(t, Decide(snap([]*store.Pool{p}, []*store.Runner{r}, []*store.Job{running}, hosts)))
	if got := actionsOf(pp.Actions, ActionRemove); len(got) != 1 || got[0].RunnerID != "r1" {
		t.Fatalf("the failed runner was not removed once its job had finished: %+v", pp.Actions)
	}
}

// An empty fleet is demand, not a full fleet.
//
// Until this was said out loud, a pool with queued jobs and nowhere at all to
// put a runner reported neither blockage: `why` answers the empty fleet before
// it counts anything, so `atCapacity` stayed false and the only signal a host
// provisioner listens for was never raised. Scaling from zero -- the whole
// point of renting a host -- was silent.
func TestAPoolWithNoHostsAtAllStillSaysItsJobsHaveNowhereToGo(t *testing.T) {
	pp := only(t, Decide(snap([]*store.Pool{testPool("linux-x64", "linux")}, nil,
		[]*store.Job{queued("j1", time.Minute, "linux")}, nil)))

	if !pp.BlockedNoEligibleHost {
		t.Fatalf("plan = %+v, want an empty fleet reported as one no job will clear", pp)
	}
	// The two flags mean different things and the distinction is load-bearing:
	// "full" is a fleet working, and problems.go and the usage record both read
	// it that way.
	if pp.BlockedAtCapacity {
		t.Fatal("an empty fleet is not a fleet at capacity")
	}
	if pp.Blocked == "" {
		t.Fatal("a blocked pool still has to say so in words")
	}
}

// The fleet being busy and the fleet being wrong are different answers, and an
// operator told to wait for the second one waits for ever.
func TestAFullFleetIsStillDistinguishedFromAFleetThatCanNeverRunThePool(t *testing.T) {
	for _, tc := range []struct {
		name  string
		hosts []*store.Host
		// pool and runners are optional: the rows about memory and CPU need a
		// pool that states a size and a runner already holding part of a host.
		pool           *store.Pool
		runners        []*store.Runner
		atCapacity     bool
		noEligibleHost bool
	}{
		{
			name:       "every host busy",
			hosts:      []*store.Host{testHost("host_a", 1, 1), testHost("host_b", 2, 2)},
			atCapacity: true,
		},
		{
			name: "every host offering another backend",
			hosts: func() []*store.Host {
				h := testHost("host_a", 8, 0)
				h.Backends = store.StringSlice{"process"}
				return []*store.Host{h}
			}(),
			noEligibleHost: true,
		},
		{
			name: "one host busy and one that could never run it",
			hosts: func() []*store.Host {
				other := testHost("host_b", 8, 0)
				other.Backends = store.StringSlice{"process"}
				return []*store.Host{testHost("host_a", 1, 1), other}
			}(),
			// Neither: one host is only busy, so a finished job would clear it.
		},
		{
			// A pressure hold is the most transient blockage there is: a job
			// spikes the CPU, new starts pause for a few seconds, and it
			// clears on its own. Reading it as "no host can ever run this"
			// would clone virtual machines for a thirty-second spike -- and
			// tell an external provisioner to scale from zero as well -- while
			// the hold lifts long before the first clone finishes.
			name: "every host under a momentary pressure hold",
			hosts: func() []*store.Host {
				h := withUsage(sized("host_a", 4, 4, 8192, 100000), 99, 12000)
				h.Usage.CPUHeld = true
				return []*store.Host{h}
			}(),
			// Neither: the hold is waited out, not bought around.
		},
		{
			// And a hold on one host does not excuse the rest: the others are
			// wrong in a way no waiting fixes, but this one is not.
			name: "one host held and one that could never run it",
			hosts: func() []*store.Host {
				h := withUsage(sized("host_a", 4, 4, 8192, 100000), 99, 12000)
				h.Usage.CPUHeld = true
				other := testHost("host_b", 8, 0)
				other.Backends = store.StringSlice{"process"}
				return []*store.Host{h, other}
			}(),
			// Neither: the held host clears itself.
		},
		{
			// A throttle is the fleet being busy, not the fleet being wrong.
			// It asks for capacity like a full host does, because more hosts
			// is the answer either way -- but it lifts on its own, so a fleet
			// blocked only by throttles must never read as one no host can
			// ever run. That would buy a machine for a fleet that needed a
			// minute, and the machine would outlive the pressure.
			name: "every host throttled back to no slots",
			hosts: func() []*store.Host {
				h := testHost("host_a", 4, 1)
				h.Throttle = store.HostThrottle{Level: store.MaxThrottleLevel}
				return []*store.Host{h}
			}(),
			atCapacity: true,
		},
		{
			// And a throttle on one host does not excuse the rest: the others
			// are wrong in a way no waiting fixes, but this one is not, so
			// there is still something to wait for.
			name: "one host throttled and one that could never run it",
			hosts: func() []*store.Host {
				h := testHost("host_a", 4, 1)
				h.Throttle = store.HostThrottle{Level: store.MaxThrottleLevel}
				other := testHost("host_b", 8, 0)
				other.Backends = store.StringSlice{"process"}
				return []*store.Host{h, other}
			}(),
			// Neither: the throttled host clears itself.
		},
		{
			// A host with a free slot whose memory is promised to a runner
			// that is still working is the ordinary busy state: the job
			// finishing returns it. Reading it as "no host could ever run
			// this pool" raises an error, and tells an external provisioner
			// to scale from zero, for a fleet that needed a minute.
			name: "every host's memory promised to a runner that will finish",
			hosts: func() []*store.Host {
				h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 200*1024)
				h.ActiveRunners = 1
				return []*store.Host{h}
			}(),
			pool:       limited("linux", 0, 6*1024),
			runners:    []*store.Runner{onHost(testRunner("r1", limited("linux", 0, 6*1024), store.RunnerBusy, 0), "host_a")},
			atCapacity: true,
		},
		{
			// CPU is returned by a finishing job exactly as memory is.
			name: "every host's CPU promised to a runner that will finish",
			hosts: func() []*store.Host {
				h := sized("host_a", 8, 8, 64*1024, 200*1024)
				h.ActiveRunners = 1
				return []*store.Host{h}
			}(),
			pool:       limited("linux", 6, 1024),
			runners:    []*store.Runner{onHost(testRunner("r1", limited("linux", 6, 1024), store.RunnerBusy, 0), "host_a")},
			atCapacity: true,
		},
		{
			// Memory the host has lost to something that is not ours is not
			// returned by any job of ours finishing, so it stays what it was:
			// neither flag, and the pool is simply skipped until it eases.
			name: "memory lost to work outside the fleet",
			hosts: []*store.Host{
				withUsage(sized("host_a", 8, 16, 16*1024, 200*1024), 10, 1024),
			},
			pool:           limited("linux", 0, 6*1024),
			noEligibleHost: true,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pool := tc.pool
			if pool == nil {
				pool = testPool("linux-x64", "linux")
			}
			pp := only(t, Decide(snap([]*store.Pool{pool}, tc.runners,
				[]*store.Job{queued("j1", time.Minute, "linux")}, tc.hosts)))

			if pp.BlockedAtCapacity != tc.atCapacity {
				t.Errorf("BlockedAtCapacity = %v, want %v (%s)", pp.BlockedAtCapacity, tc.atCapacity, pp.Blocked)
			}
			if pp.BlockedNoEligibleHost != tc.noEligibleHost {
				t.Errorf("BlockedNoEligibleHost = %v, want %v (%s)", pp.BlockedNoEligibleHost, tc.noEligibleHost, pp.Blocked)
			}
		})
	}
}

// A fleet blocked only by memory that live runners hold is at capacity to the
// callers that count it, but the operator is still told the more specific
// thing: the limits are what to change, not only the number of hosts. Folding
// it into the plain "at capacity" advice would have hidden that.
func TestAMemoryCommittedFleetKeepsTheAdviceAboutMemory(t *testing.T) {
	p := limited("linux", 0, 6*1024)
	h := sized("host_a", 8, 16, 8*1024+store.MinHostReserveMemoryMB, 200*1024)
	h.ActiveRunners = 1
	runners := []*store.Runner{onHost(testRunner("r1", p, store.RunnerBusy, 0), "host_a")}

	pp := only(t, Decide(snap([]*store.Pool{p}, runners, []*store.Job{queued("j1", time.Minute, "linux")}, []*store.Host{h})))
	if !strings.Contains(pp.BlockedFix, "lower this pool's limits") {
		t.Errorf("BlockedFix = %q, want the advice about the pool's limits", pp.BlockedFix)
	}
}

package scheduler

import (
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The throttle ladder. Each constant was chosen against another, and the
// relationships are pinned by tests in internal/controller (invariants_test.go)
// and documented in docs/architecture.md.
const (
	// ThrottleStep is the least time between one rung and the next up. The
	// CPU hold that feeds it needs 30 s of saturation, so the first rung can
	// come half a minute after the pressure starts; the second waits for the
	// first to have had an effect, because a quota lowered on a live
	// container takes a scheduling period or two to show in a load average
	// that itself averages over a minute.
	ThrottleStep = 2 * time.Minute
	// ThrottleRecovery is how long a host has to stay calm before it climbs
	// down one rung. Longer than a step up on purpose: a host that recovered
	// in a minute and was pushed straight back over would otherwise oscillate
	// with the ladder rather than settle on it.
	ThrottleRecovery = 5 * time.Minute
	// StaleThrottleReset is how long a host may go without a fresh usage
	// sample before its throttle is lifted anyway. The measurements the
	// ladder climbs on have stopped coming -- an agent downgraded to a build
	// that does not send them, or a host that went away -- and a host that
	// cannot be measured is placed by its configured capacity, exactly as the
	// holds already fall back. It is longer than the time a host is given up
	// on as lost, so a host that comes back is not still throttled for
	// pressure nobody can see.
	StaleThrottleReset = 10 * time.Minute

	// LoadPerCPUOverwhelmed is the one-minute load average per CPU at which a
	// host counts as overwhelmed: twice as many runnable tasks as there are
	// cores to run them, which is the shape a machine takes when its CPU
	// occupancy has already pinned at 100% and stopped saying anything.
	// LoadPerCPUCalm is where it is calm again -- one runnable task per core,
	// where nothing is queued behind anything.
	LoadPerCPUOverwhelmed = 2.0
	LoadPerCPUCalm        = 1.0
	// cpuCalmPercent is the CPU occupancy below which a host is calm, and it
	// is the same figure that releases the admission hold, so the two never
	// disagree about whether a host has recovered.
	cpuCalmPercent = 85.0
)

// NextThrottle is the ladder: given a host as it stands, with the measurements
// its agent last sent and the rung it is on, it returns the rung it should be
// on now. It is pure, and the controller persists the result when it differs.
//
// Three things can be true of a host with a fresh sample. It is overwhelmed:
// the CPU hold has tripped, the load average is past twice its cores, or its
// memory is at the reserve -- and then it climbs a rung, if ThrottleStep has
// passed since the last one. It is calm: CPU under 85%, load under one per
// core, memory above the reserve -- and then a calm streak runs, and after
// ThrottleRecovery it climbs down a rung and the streak starts again. Or it
// is neither, in the band between, where the rung is kept and the streak is
// broken: a host at 90% CPU is not overwhelmed, and it is not a host to give
// slots back to either.
//
// Without a fresh sample nothing moves, until StaleThrottleReset has passed
// since the last one; then the throttle is lifted, because a host nobody can
// measure is placed by its configured capacity.
func NextThrottle(h *store.Host, now time.Time) store.HostThrottle {
	t := h.Throttle
	if !h.Usage.Fresh(now) {
		if t.Active() && !h.Usage.SampledAt.IsZero() && now.Sub(h.Usage.SampledAt) >= StaleThrottleReset {
			return store.HostThrottle{}
		}
		if t.Active() && h.Usage.SampledAt.IsZero() {
			// Nothing was ever measured, so nothing can have decided this;
			// a row can only look like this after the usage was cleared.
			return store.HostThrottle{}
		}
		return t
	}
	overwhelmed, reason := hostOverwhelmed(h)
	switch {
	case overwhelmed:
		t.CalmSince = nil
		if t.Level >= store.MaxThrottleLevel {
			return t
		}
		if t.ChangedAt != nil && now.Sub(*t.ChangedAt) < ThrottleStep {
			return t
		}
		t.Level++
		at := now
		t.ChangedAt = &at
		t.Reason = reason
		if t.Since == nil {
			since := now
			t.Since = &since
		}
		return t
	case hostCalm(h):
		if !t.Active() {
			return store.HostThrottle{}
		}
		if t.CalmSince == nil {
			since := now
			t.CalmSince = &since
			return t
		}
		if now.Sub(*t.CalmSince) < ThrottleRecovery {
			return t
		}
		t.Level--
		at := now
		t.ChangedAt = &at
		t.CalmSince = &at
		if t.Level <= 0 {
			return store.HostThrottle{}
		}
		return t
	default:
		t.CalmSince = nil
		return t
	}
}

// hostOverwhelmed reports whether a host's fresh measurements say it has been
// pushed past what it can do, and which measurement says so, in the words the
// throttle's reason carries.
//
// Overwhelmed means pressure beyond the plan, not use of it. A host whose
// every runner is inside its CPU quota is running exactly the work it was
// sized for, and with the quotas summing to the machine less its reserve that
// work sits at 95% CPU all day: a hold that read that as overload would
// throttle a healthy host, watch it calm down, lift the throttle and throttle
// it again, for ever. So the CPU hold counts only while the host carries a
// runner with no quota -- the one kind of runner that can take more than its
// share -- and the load average is what says a host has been pushed past its
// cores by anything at all, quotas included: CFS dequeues a throttled task, so
// load climbs past the core count only when more is runnable than the plan
// allows for.
func hostOverwhelmed(h *store.Host) (bool, string) {
	u := h.Usage
	if u.CPUHeld && h.UnlimitedRunners > 0 {
		return true, fmt.Sprintf("CPU has been at or above 95%% for 30 s with %s here that no CPU limit binds",
			plural(h.UnlimitedRunners, "runner"))
	}
	if u.LoadAverage1 != nil && h.CPUs > 0 && *u.LoadAverage1 >= LoadPerCPUOverwhelmed*float64(h.CPUs) {
		return true, fmt.Sprintf("the 1-minute load average is %.1f, at least twice the host's %d CPUs", *u.LoadAverage1, h.CPUs)
	}
	if v := u.MemoryAvailableMB; v != nil && *v <= h.MemoryReserve() {
		return true, "available memory is at or below the host's reserve"
	}
	return false, ""
}

// hostCalm reports whether every fresh measurement says the host has room
// again. Each figure is judged only where it was measured: a host that reports
// CPU alone is calm when its CPU is.
//
// The CPU bar is reachable from every rung: a throttled host's quotas sum to
// three quarters of the machine or less, so a host whose runners are all
// inside them falls under 85% the moment the quotas take. A host that stays
// above it is carrying something the quotas do not bind.
func hostCalm(h *store.Host) bool {
	u := h.Usage
	if u.CPUHeld {
		return false
	}
	// Judged without CPU runners are using because it was lent them: the
	// throttle withdraws every boost anyway, and counting it here would hold a
	// host on its rung for doing what the plan asked.
	if v := u.UnlentCPUPercent(); v != nil && *v >= cpuCalmPercent {
		return false
	}
	if u.LoadAverage1 != nil && h.CPUs > 0 && *u.LoadAverage1 >= LoadPerCPUCalm*float64(h.CPUs) {
		return false
	}
	if v := u.MemoryAvailableMB; v != nil && *v <= h.MemoryReserve() {
		return false
	}
	return true
}

// ThrottleReason is the throttle as one sentence for the Hosts page and the
// problems drawer: what it took, why, what it is doing to the jobs already
// running, and how it ends. Empty when the host is not throttled.
//
// The clause about running jobs is only said where it can be true. A runner
// with no CPU limit has nothing to scale, and a host that offers only the
// process backend has no container to update, so an operator there is told
// what the throttle took and not what it cannot do.
func ThrottleReason(h *store.Host) string {
	t := h.Throttle
	if !t.Active() {
		return ""
	}
	slots := fmt.Sprintf("throttled to %d of %d slots (step %d of %d) after sustained pressure: %s",
		h.EffectiveCapacity(), h.Capacity, t.Level, store.MaxThrottleLevel, t.Reason)
	jobs := "running jobs continue"
	if limited := h.ActiveRunners - h.UnlimitedRunners; limited > 0 && hostCanThrottleContainers(h) {
		jobs = fmt.Sprintf("running jobs continue, the %s with a CPU limit at %d%% of it",
			plural(limited, "runner"), int(t.CPUFactor()*100))
	}
	return fmt.Sprintf("%s; %s, and the throttle lifts one step after %s of calm",
		slots, jobs, formatDuration(ThrottleRecovery))
}

// hostCanThrottleContainers reports whether the host offers a backend whose
// workloads have a quota to lower: any container backend does, and the
// process backend does not.
func hostCanThrottleContainers(h *store.Host) bool {
	for _, kind := range h.Backends {
		if kind != string(store.BackendProcess) {
			return true
		}
	}
	return false
}

package scheduler

import (
	"strings"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/eyupio/zoomies/internal/store"
)

// pressed is a measured host with a fresh sample of the given shape, carrying
// two live runners of which one has no CPU quota -- the shape on which a CPU
// hold can mean something.
func pressed(now time.Time, cpu float64, held bool, load float64, memory int64) *store.Host {
	h := sized("host_a", 4, 8, 16*1024, 500*1024)
	h.ActiveRunners, h.UnlimitedRunners = 2, 1
	h.Usage = store.HostUsage{CPUPercent: &cpu, CPUHeld: held, LoadAverage1: &load, MemoryAvailableMB: &memory, SampledAt: now}
	return h
}

// A host whose every runner is inside its CPU quota is running exactly the
// work it was sized for, and with the quotas summing to the machine less its
// reserve that work sits at 95% CPU all day. The hold that reads that as
// overload must not climb the ladder: a throttle that took a healthy host,
// watched it calm down, lifted and took it again would run that loop for
// ever, slowing every job on the host for most of every cycle.
func TestAFullHostInsideItsQuotasIsNeverThrottledForItsCPU(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	h := pressed(now, 96, true, 15, 8192)
	h.CPUs, h.ActiveRunners, h.UnlimitedRunners = 16, 4, 0
	for i := 0; i < 10; i++ {
		at := now.Add(time.Duration(i) * ThrottleStep)
		h.Usage.SampledAt = at
		if got := NextThrottle(h, at); got.Active() {
			t.Fatalf("a full, in-quota host was throttled on step %d: %+v", i, got)
		}
	}
	// The same host with one runner nothing binds is a different host: that
	// runner can take more than its share, and the hold is about it.
	h.UnlimitedRunners = 1
	h.Usage.SampledAt = now
	if got := NextThrottle(h, now); !got.Active() || !strings.Contains(got.Reason, "1 runner here that no CPU limit binds") {
		t.Fatalf("a host with an unlimited runner under a CPU hold was not throttled: %+v", got)
	}
}

// The ladder climbs one rung per step while the pressure keeps coming back,
// and stops at the top: a fourth rung would leave a host taking nothing, which
// is a cordon, and a cordon is the operator's.
func TestAnOverwhelmedHostClimbsOneRungPerStepUpToTheTop(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	h := pressed(now, 99, true, 4, 8192)

	got := NextThrottle(h, now)
	if got.Level != 1 || got.Since == nil || !got.Since.Equal(now) || got.ChangedAt == nil || !strings.Contains(got.Reason, "CPU") {
		t.Fatalf("first step = %+v, want rung 1 with the CPU hold as its reason", got)
	}
	// Still overwhelmed a minute later: too soon for the next rung. The
	// quota lowered on the live containers has to be given time to show in
	// a load average that itself averages over a minute.
	h.Throttle = got
	later := now.Add(ThrottleStep - time.Second)
	h.Usage.SampledAt = later
	if got = NextThrottle(h, later); got.Level != 1 {
		t.Fatalf("a second rung came %s after the first, before ThrottleStep: %+v", ThrottleStep-time.Second, got)
	}
	later = now.Add(ThrottleStep)
	h.Usage.SampledAt = later
	if got = NextThrottle(h, later); got.Level != 2 || !got.ChangedAt.Equal(later) || !got.Since.Equal(now) {
		t.Fatalf("second step = %+v, want rung 2 with the episode still dated from the first", got)
	}
	h.Throttle = got
	later = later.Add(ThrottleStep)
	h.Usage.SampledAt = later
	got = NextThrottle(h, later)
	h.Throttle = got
	later = later.Add(ThrottleStep)
	h.Usage.SampledAt = later
	if got = NextThrottle(h, later); got.Level != store.MaxThrottleLevel {
		t.Fatalf("level = %d after four overwhelmed steps, want the top rung %d and no further", got.Level, store.MaxThrottleLevel)
	}
	if h.Throttle = got; h.EffectiveCapacity() != 1 {
		t.Fatalf("effective capacity at the top rung = %d, want the one slot a throttle never takes", h.EffectiveCapacity())
	}
}

// Each of the three signals climbs the ladder on its own, and names itself:
// the reason is what the Hosts page shows, and "sustained pressure" alone
// would send an operator to look at the CPU when the memory was the problem.
func TestEachPressureSignalNamesItself(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	cases := []struct {
		name string
		host *store.Host
		want string
	}{
		{"the CPU hold, with a runner no limit binds", pressed(now, 99, true, 1, 8192), "CPU has been at or above 95% for 30 s with 1 runner here that no CPU limit binds"},
		{"a load average past twice the cores", pressed(now, 60, false, 17, 8192), "load average is 17.0, at least twice the host's 8 CPUs"},
		{"memory at the reserve", pressed(now, 60, false, 1, store.MinHostReserveMemoryMB), "available memory is at or below the host's reserve"},
	}
	for _, tc := range cases {
		got := NextThrottle(tc.host, now)
		if got.Level != 1 || !strings.Contains(got.Reason, tc.want) {
			t.Errorf("%s: throttle = %+v, want rung 1 mentioning %q", tc.name, got, tc.want)
		}
	}
	// And a host that is merely busy climbs nothing: 90% CPU, a load of one
	// per core and memory to spare is a host doing its job.
	if got := NextThrottle(pressed(now, 90, false, 8, 8192), now); got.Active() {
		t.Errorf("a busy host was throttled: %+v", got)
	}
}

// Coming down is slower than going up, on purpose. A host that recovered in a
// minute and was pushed straight back over would otherwise oscillate with the
// ladder rather than settle on it, so a rung is given back only after a
// stretch of calm long enough to mean something -- and the stretch starts
// again if the calm breaks.
func TestAThrottleLiftsOneRungPerStretchOfCalmAndABusySampleBreaksTheStretch(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	h := pressed(now, 20, false, 1, 8192)
	at := now.Add(-ThrottleStep)
	h.Throttle = store.HostThrottle{Level: 2, Since: &at, ChangedAt: &at, Reason: "CPU has been at or above 95% for 30 s"}

	got := NextThrottle(h, now)
	if got.Level != 2 || got.CalmSince == nil || !got.CalmSince.Equal(now) {
		t.Fatalf("the first calm sample = %+v, want the streak to start and the rung to stay", got)
	}
	h.Throttle = got
	// A busy sample in the band between calm and overwhelmed breaks the
	// streak without moving the rung.
	busy := now.Add(time.Minute)
	h.Usage.SampledAt = busy
	*h.Usage.CPUPercent = 90
	if got = NextThrottle(h, busy); got.Level != 2 || got.CalmSince != nil {
		t.Fatalf("a busy sample = %+v, want the rung kept and the streak broken", got)
	}
	h.Throttle = got
	*h.Usage.CPUPercent = 20
	calm := busy.Add(time.Minute)
	h.Usage.SampledAt = calm
	got = NextThrottle(h, calm)
	h.Throttle = got
	almost := calm.Add(ThrottleRecovery - time.Second)
	h.Usage.SampledAt = almost
	if got = NextThrottle(h, almost); got.Level != 2 {
		t.Fatalf("a rung was given back a second before ThrottleRecovery: %+v", got)
	}
	done := calm.Add(ThrottleRecovery)
	h.Usage.SampledAt = done
	got = NextThrottle(h, done)
	if got.Level != 1 || got.CalmSince == nil || !got.CalmSince.Equal(done) || got.Reason == "" {
		t.Fatalf("after ThrottleRecovery = %+v, want rung 1, the streak restarted and the reason kept", got)
	}
	h.Throttle = got
	last := done.Add(ThrottleRecovery)
	h.Usage.SampledAt = last
	if got = NextThrottle(h, last); got != (store.HostThrottle{}) {
		t.Fatalf("the last rung did not clear the episode: %+v", got)
	}
}

// A host nobody can measure any more is placed by its configured capacity,
// exactly as the holds fall back -- but not at once. One missed sample is a
// slow heartbeat; ten minutes of them is an agent downgraded to a build that
// does not measure, or a host that went away, and a host that comes back
// must not still be throttled for pressure nobody can see.
func TestAThrottleOutlivesAMissedSampleAndNotAStaleOne(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	h := pressed(now, 99, true, 4, 8192)
	h.Throttle = NextThrottle(h, now)
	if !h.Throttle.Active() {
		t.Fatal("setup: the host was not throttled")
	}
	stale := now.Add(store.HostUsageMaxAge + time.Second)
	if got := NextThrottle(h, stale); got != h.Throttle {
		t.Fatalf("a stale sample moved the throttle: %+v", got)
	}
	if got := NextThrottle(h, now.Add(StaleThrottleReset)); got.Active() {
		t.Fatalf("the throttle survived %s without a sample: %+v", StaleThrottleReset, got)
	}
	// A throttle with no measurement behind it at all cannot have been
	// decided by anything, and is cleared.
	h.Usage = store.HostUsage{}
	if got := NextThrottle(h, now); got.Active() {
		t.Fatalf("a throttle with no usage behind it survived: %+v", got)
	}
}

// The scheduler counts a throttled host as its own kind of blockage. "At
// capacity" would send an operator to raise a capacity that is not the
// problem: the host is being pushed too hard at the slots it already has, and
// the fix is fewer slots or tighter pools, not more of either.
func TestAThrottledHostIsNamedAsSuchWhenNothingCanBePlaced(t *testing.T) {
	// The package clock, so the host's heartbeat and the sample are fresh
	// against the snapshot's Now.
	h := pressed(now, 60, false, 1, 8192)
	at := now.Add(-time.Minute)
	h.Throttle = store.HostThrottle{Level: 2, Since: &at, ChangedAt: &at, Reason: "CPU has been at or above 95% for 30 s"}
	// Four slots, two live runners with a limit each: full at the throttle's
	// two, not at the operator's four.
	p := limited("builders", 1, 1024)
	p.MaxRunners = 4
	runners := []*store.Runner{
		testRunner("run_1", p, store.RunnerBusy, time.Minute),
		testRunner("run_2", p, store.RunnerBusy, time.Minute),
	}
	h.ActiveRunners, h.UnlimitedRunners = 2, 0
	plan := Decide(snap([]*store.Pool{p}, runners, []*store.Job{queued("job_1", time.Minute, "builders")}, []*store.Host{h}))
	if len(plan.Actions) != 0 {
		t.Fatalf("a throttled host at its effective capacity was given a runner: %+v", plan.Actions)
	}
	pp := plan.Pools[0]
	if !strings.Contains(pp.Blocked, "1 throttled after sustained pressure") || !strings.Contains(pp.Blocked, "throttled to 2 of 4 slots") {
		t.Errorf("Blocked = %q, want the throttled count and the host's own reason", pp.Blocked)
	}
	if !strings.Contains(pp.BlockedFix, "lower those hosts' capacity") {
		t.Errorf("BlockedFix = %q, want the throttle's fix", pp.BlockedFix)
	}
	// To a provisioner a throttled host is a full one: more hosts is the one
	// answer that helps either way, so the signal it listens for is raised.
	if !pp.BlockedAtCapacity {
		t.Error("a fleet blocked only by throttles did not ask for capacity")
	}
	// Two runners, both with a limit: the sentence says what the throttle is
	// doing to them, and which step it is on.
	if got := ThrottleReason(h); !strings.Contains(got, "step 2 of 3") || !strings.Contains(got, "the 2 runners with a CPU limit at 50% of it") {
		t.Errorf("ThrottleReason = %q", got)
	}
	// A runner nothing binds is not promised a slowdown it will not get, and
	// a host with only the process backend has no container to slow at all.
	h.UnlimitedRunners = 2
	if got := ThrottleReason(h); strings.Contains(got, "CPU limit at") || !strings.Contains(got, "running jobs continue") {
		t.Errorf("ThrottleReason for unlimited runners = %q", got)
	}
	h.UnlimitedRunners = 0
	h.Backends = store.StringSlice{"process"}
	if got := ThrottleReason(h); strings.Contains(got, "CPU limit at") {
		t.Errorf("ThrottleReason for a process-only host = %q", got)
	}
}

// A failure message is not ASCII, and the ellipsis must not be paid for with
// half a character.
//
// The text comes from a daemon, a registry or GitHub, so the byte the limit
// lands on is routinely in the middle of one. What used to come out the other
// side reached the problems drawer and the pool page with a replacement glyph
// in the middle of a word -- which reads as Zoomies having mangled the message
// rather than shortened it.
func TestSummariseCutsBetweenCharacters(t *testing.T) {
	// A message whose 159th byte falls inside a three-byte character.
	message := strings.Repeat("a", 158) + "→" + strings.Repeat("b", 40)
	got := summarise(message)
	if !utf8.ValidString(got) {
		t.Fatalf("summarise produced invalid UTF-8: %q", got)
	}
	if !strings.HasSuffix(got, "…") {
		t.Fatalf("summarise = %q, want it to end in an ellipsis", got)
	}
	if strings.ContainsRune(got, utf8.RuneError) {
		t.Fatalf("summarise = %q, which carries a replacement character", got)
	}

	// A message that fits is returned whole, whatever it is made of.
	short := "could not pull ghcr.io/acme/runner: manifest unknown — check the tag"
	if got := summarise(short); got != short {
		t.Fatalf("summarise(%q) = %q, want it unchanged", short, got)
	}
	if got := summarise("   "); got != "no reason was recorded" {
		t.Fatalf("summarise of whitespace = %q", got)
	}
}

package store

import (
	"testing"
)

func hostForSessions(t *testing.T, s *Store) *Host {
	t.Helper()
	h := &Host{Name: "host-a", Capacity: 2}
	if err := s.CreateHost(t.Context(), h); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	return h
}

// Restarting is the ordinary thing an agent does, and it must never look like
// a duplicate. The agent's unit restarts always, so a controller that flagged
// every session change would flag every host that had ever been upgraded.
func TestAnAgentRestartingIsNotADuplicate(t *testing.T) {
	s := newTestStore(t)
	h := hostForSessions(t, s)

	for _, session := range []string{"ses_a", "ses_a", "ses_b", "ses_b", "ses_c"} {
		alternated, err := s.RecordAgentSession(t.Context(), h.ID, session)
		if err != nil {
			t.Fatalf("RecordAgentSession(%s): %v", session, err)
		}
		if alternated {
			t.Fatalf("session %s was called an alternation; an agent only ever moves forward", session)
		}
	}
	got, err := s.GetHost(t.Context(), h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.AgentSessionAlternations != 0 || got.AgentSessionAltAt != nil {
		t.Fatalf("alternations = %d at %v, want none recorded", got.AgentSessionAlternations, got.AgentSessionAltAt)
	}
}

// The signal itself. A session id is minted at start-up and never reused, so
// going back to one this host has already left behind is something a single
// agent cannot do however often it restarts: it means two of them hold this
// host's token and are splitting its tasks.
func TestTwoAgentsSharingAHostAreSeenAlternating(t *testing.T) {
	s := newTestStore(t)
	h := hostForSessions(t, s)
	ctx := t.Context()

	if alt, _ := s.RecordAgentSession(ctx, h.ID, "ses_one"); alt {
		t.Fatal("the first session cannot be an alternation")
	}
	if alt, _ := s.RecordAgentSession(ctx, h.ID, "ses_two"); alt {
		t.Fatal("the second session on its own looks exactly like a restart")
	}
	// Back to the first: this is the moment a restart cannot explain.
	alt, err := s.RecordAgentSession(ctx, h.ID, "ses_one")
	if err != nil {
		t.Fatalf("RecordAgentSession: %v", err)
	}
	if !alt {
		t.Fatal("going back to a session the host had left behind was not reported")
	}

	// And it keeps being reported as they carry on swapping.
	if alt, _ := s.RecordAgentSession(ctx, h.ID, "ses_two"); !alt {
		t.Fatal("the swap back was not reported")
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.AgentSessionAlternations != 2 {
		t.Fatalf("alternations = %d, want 2", got.AgentSessionAlternations)
	}
	if got.AgentSessionAltAt == nil {
		t.Fatal("no time recorded for the last alternation; the problem could never age out")
	}
}

// An agent that predates the header sends nothing, and a controller must not
// read that as a host whose session has changed.
func TestAnAgentWithNoSessionIsNotRecorded(t *testing.T) {
	s := newTestStore(t)
	h := hostForSessions(t, s)
	ctx := t.Context()

	if _, err := s.RecordAgentSession(ctx, h.ID, "ses_one"); err != nil {
		t.Fatalf("RecordAgentSession: %v", err)
	}
	alt, err := s.RecordAgentSession(ctx, h.ID, "")
	if err != nil {
		t.Fatalf("RecordAgentSession(empty): %v", err)
	}
	if alt {
		t.Fatal("an empty session was treated as an alternation")
	}
	got, _ := s.GetHost(ctx, h.ID)
	if got.AgentSessionID != "ses_one" {
		t.Fatalf("agent_session_id = %q, want the real session left in place", got.AgentSessionID)
	}
}

package store

import "testing"

// Allocatable is the arithmetic every placement decision starts from, and the
// distinction it has to keep is between a figure that was measured and one
// that never was. Zero means both things on a host row, and reading "nobody
// looked" as "nothing left" would refuse work on every host of a fleet the
// moment it upgraded past the agents that report these.
func TestAllocatableSeparatesUnmeasuredFromEmpty(t *testing.T) {
	cases := []struct {
		name string
		host Host
		want HostAllocation
	}{{
		name: "an agent that reports nothing has measured nothing",
		host: Host{},
		want: HostAllocation{},
	}, {
		// A twentieth of 16 GB is 819 MB, which is above the 512 MB floor, so
		// the fraction answers for memory here and the floor answers for CPU.
		name: "the floors apply when the operator has set no reserve",
		host: Host{CPUs: 8, MemoryMB: 16384, DiskTotalMB: 100_000, DiskFreeMB: 50_000},
		want: HostAllocation{
			CPUs: 8 - MinHostReserveCPUs, MemoryMB: 16384 - 819, DiskMB: 50_000 - MinHostReserveDiskMB,
			CPUsKnown: true, MemoryKnown: true, DiskKnown: true,
		},
	}, {
		// Both floors grow with the machine: a daemon minding sixty-four
		// containers needs more than the half core and half gigabyte that
		// serve a daemon minding four, and a fixed figure would be a rounding
		// error on a host that size. Memory is capped where holding more back
		// stops buying anything -- a twentieth of 256 GB is 12.8 GB, and the
		// daemon will never want that much.
		name: "both floors are a twentieth of a large machine, and memory is capped",
		host: Host{CPUs: 64, MemoryMB: 262_144},
		want: HostAllocation{
			CPUs: 64 - 64*MinHostReserveCPUFraction, MemoryMB: 262_144 - MaxHostReserveMemoryMB,
			CPUsKnown: true, MemoryKnown: true,
		},
	}, {
		// The flat floor still answers on a small machine, where a twentieth
		// is less than the daemon needs however small the box is.
		name: "the memory floor answers on a small machine",
		host: Host{CPUs: 2, MemoryMB: 4096},
		want: HostAllocation{
			CPUs: 2 - MinHostReserveCPUs, MemoryMB: 4096 - MinHostReserveMemoryMB,
			CPUsKnown: true, MemoryKnown: true,
		},
	}, {
		name: "an operator's larger reserve wins over the floor",
		host: Host{
			CPUs: 8, MemoryMB: 16384, DiskTotalMB: 100_000, DiskFreeMB: 50_000,
			ReserveCPUs: 2, ReserveMemoryMB: 4096, ReserveDiskMB: 20_000,
		},
		want: HostAllocation{
			CPUs: 6, MemoryMB: 12288, DiskMB: 30_000,
			CPUsKnown: true, MemoryKnown: true, DiskKnown: true,
		},
	}, {
		// The failure this prevents is a negative allocation reading as a very
		// large one somewhere downstream. A machine smaller than its own
		// reserve has no room to run a job in, and saying zero is the honest
		// answer rather than a bug.
		name: "a host smaller than its reserve allocates nothing, and still counts as measured",
		host: Host{CPUs: 1, MemoryMB: 256, DiskTotalMB: 8000, DiskFreeMB: 100},
		want: HostAllocation{CPUsKnown: true, MemoryKnown: true, DiskKnown: true, CPUs: 1 - MinHostReserveCPUs},
	}, {
		// A disk that is genuinely full still reported a total, which is what
		// says a measurement happened at all -- the encoding ZF-103a chose.
		name: "a full disk is measured, an unmeasured one is not",
		host: Host{CPUs: 4, MemoryMB: 8192, DiskTotalMB: 100_000, DiskFreeMB: 0},
		want: HostAllocation{
			CPUs: 4 - MinHostReserveCPUs, MemoryMB: 8192 - MinHostReserveMemoryMB,
			CPUsKnown: true, MemoryKnown: true, DiskKnown: true,
		},
	}, {
		name: "a host that measured its size but not its disk",
		host: Host{CPUs: 4, MemoryMB: 8192},
		want: HostAllocation{
			CPUs: 4 - MinHostReserveCPUs, MemoryMB: 8192 - MinHostReserveMemoryMB,
			CPUsKnown: true, MemoryKnown: true,
		},
	}}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.host.Allocatable(); got != tc.want {
				t.Errorf("Allocatable() = %+v, want %+v", got, tc.want)
			}
		})
	}
}

// The controller runs on the host whose agent is embedded, so that host holds
// back room for it on top of the floors meant for the daemon and the agent. The
// case that made this necessary: twelve cores held back six tenths of one, and
// with the runners flat out that was all the machine left for the scheduler,
// the database writer and the API as well as dockerd.
//
// The allowance is added to the floor rather than folded into it, and an
// operator's own reserve still wins where it is larger -- someone who held
// back four cores on the controller's host meant four.
func TestTheControllersOwnHostHoldsBackRoomForTheController(t *testing.T) {
	plain := Host{CPUs: 12, MemoryMB: 31 * 1024}
	embedded := plain
	embedded.Embedded = true

	if got, want := embedded.CPUReserve()-plain.CPUReserve(), ControllerReserveCPUs; got != want {
		t.Errorf("the controller's host holds back %.2f more CPU than another, want %.2f", got, want)
	}
	if got, want := embedded.MemoryReserve()-plain.MemoryReserve(), ControllerReserveMemoryMB; got != want {
		t.Errorf("the controller's host holds back %d MB more memory than another, want %d", got, want)
	}
	if got, want := plain.Allocatable().CPUs-embedded.Allocatable().CPUs, ControllerReserveCPUs; got != want {
		t.Errorf("the controller's host has %.2f fewer CPUs to place on, want %.2f: the reserve must reach allocatable", got, want)
	}

	// On a small machine the allowance is still the whole allowance: folding it
	// into a floor the machine already hit would leave the daemon less.
	small := Host{CPUs: 2, MemoryMB: 4096, Embedded: true}
	if got, want := small.CPUReserve(), MinHostReserveCPUs+ControllerReserveCPUs; got != want {
		t.Errorf("a two-core controller host holds back %.2f CPU, want the floor and the allowance, %.2f", got, want)
	}

	operator := embedded
	operator.ReserveCPUs = 4
	if got := operator.CPUReserve(); got != 4 {
		t.Errorf("an operator's reserve of 4 cores on the controller's host became %.2f; the larger figure stands", got)
	}
}

package store

import (
	"context"
	"errors"
	"testing"
)

// An import of pools is one change or none. If the last row of a document is
// refused by the database, the rows before it must not have landed either,
// or the fleet matches neither the file nor what was there before.
func TestApplyPoolsWritesEveryPoolOrNone(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	inst, existing, _ := seedPool(t, s)

	fresh := &Pool{Name: "zoomies-fresh", InstallationID: inst.ID, Backend: BackendDocker,
		MaxRunners: 2, DockerMode: DockerNone, Enabled: true}
	// A second pool under the existing one's name breaks the unique index,
	// after the first create has already been executed inside the transaction.
	clash := &Pool{Name: existing.Name, InstallationID: inst.ID, Backend: BackendDocker,
		MaxRunners: 1, DockerMode: DockerNone, Enabled: true}
	err := s.ApplyPools(ctx, []*Pool{fresh, clash}, nil)
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("ApplyPools error = %v, want ErrConflict", err)
	}
	if _, err := s.GetPoolByName(ctx, "zoomies-fresh"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("the pool before the refused one was kept: %v", err)
	}

	edited := *existing
	edited.MaxRunners = 9
	missing := &Pool{ID: "pool_gone", Name: "zoomies-gone", InstallationID: inst.ID, Backend: BackendDocker,
		MaxRunners: 1, DockerMode: DockerNone, Enabled: true}
	if err := s.ApplyPools(ctx, nil, []*Pool{&edited, missing}); !errors.Is(err, ErrNotFound) {
		t.Fatalf("updating a pool that is not there: error = %v, want ErrNotFound", err)
	}
	got, err := s.GetPool(ctx, existing.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.MaxRunners == 9 {
		t.Fatal("the update before the refused one was kept")
	}

	fresh = &Pool{Name: "zoomies-fresh", InstallationID: inst.ID, Backend: BackendDocker,
		MaxRunners: 2, DockerMode: DockerNone, Enabled: true}
	if err := s.ApplyPools(ctx, []*Pool{fresh}, []*Pool{&edited}); err != nil {
		t.Fatalf("ApplyPools: %v", err)
	}
	if got, _ := s.GetPool(ctx, existing.ID); got.MaxRunners != 9 {
		t.Fatalf("max_runners = %d after the apply, want 9", got.MaxRunners)
	}
	if _, err := s.GetPoolByName(ctx, "zoomies-fresh"); err != nil {
		t.Fatalf("the created pool is not there: %v", err)
	}
}

package store

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// The layout one backup has on disk, shared so that a copy this package takes
// before a migration is restorable by exactly the command that restores a copy
// an operator took by hand. Two namings for one thing would mean a
// pre-migration copy nobody could put back without knowing it was special.
const (
	// BackupDirPrefix begins the name of one backup's directory; the rest is
	// the instant it was taken.
	BackupDirPrefix = "zoomies-"
	// BackupDBName is the database inside it.
	BackupDBName = "zoomies.db"
	// PreMigrationDir is where this package puts the copy it takes before
	// applying migrations, beside the database.
	//
	// Its own directory rather than the operator's: retention here deletes,
	// and the directory somebody points `zoomies backup --dir` at is often
	// shared. A rule that kept "the last two" in there would eventually take
	// one of theirs.
	PreMigrationDir = "pre-migration"
	// preMigrationKeep is how many of these are worth having. One is the
	// upgrade that just happened; two covers the upgrade before it, which is
	// the one an operator reaches for when the first went unnoticed. More
	// would be a copy of the whole database per release, kept forever, on the
	// disk the fleet also needs.
	preMigrationKeep = 2
)

// Backup writes a consistent copy of the database to dest.
//
// It is `VACUUM INTO` rather than a file copy, and that is the whole reason
// this exists in the store: a running instance keeps a write-ahead log, so
// copying the .db file alone produces something that is missing every recent
// commit, and copying all three files while a write is in flight produces
// something that is missing part of one. VACUUM INTO takes a consistent read snapshot, so
// what lands is one file, already checkpointed, with no WAL beside it -- a
// database an operator can move, verify and open anywhere.
//
// The documentation used to send operators to the sqlite3 command line for
// this. That binary is not in the container image, so the instructions could
// not be followed by most of the people reading them.
//
// It works on a store opened read-only, which is how `zoomies backup` uses it:
// VACUUM INTO only reads the source, and taking a backup must not be a reason
// to migrate the database being backed up.
func (s *Store) Backup(ctx context.Context, dest string) error {
	if strings.TrimSpace(dest) == "" {
		return errors.New("store: a backup needs a destination path")
	}
	abs, err := filepath.Abs(dest)
	if err != nil {
		return fmt.Errorf("store: resolving %q: %w", dest, err)
	}
	// Refusing an existing file rather than overwriting it: the destination of
	// a backup is nearly always a name derived from the date, and the one time
	// it is not, the file already there is somebody's older backup. Losing that
	// to a typo is the failure this guards.
	if _, err := os.Stat(abs); err == nil {
		return fmt.Errorf("store: %s already exists; a backup never overwrites one", abs)
	} else if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("store: checking %s: %w", abs, err)
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o750); err != nil {
		return fmt.Errorf("store: creating %s: %w", filepath.Dir(abs), err)
	}

	if _, err := s.read.ExecContext(ctx, `VACUUM INTO ?`, abs); err != nil {
		return fmt.Errorf("store: copying the database to %s: %w", abs, err)
	}
	// A backup holds every sealed secret this instance has and every account's
	// password hash. VACUUM INTO creates the file with the process umask,
	// which on a default Debian image is world-readable.
	if err := os.Chmod(abs, 0o600); err != nil {
		return fmt.Errorf("store: tightening permissions on %s: %w", abs, err)
	}
	return nil
}

// IntegrityCheck asks SQLite whether the database is internally consistent.
//
// It is what makes a backup a backup rather than a file: a copy nobody has
// opened is a copy nobody knows about, and the moment to find out is while the
// original is still there. `PRAGMA integrity_check` walks every page, index
// and constraint, so it is not instant on a large database and is not run on
// the ordinary startup path.
func (s *Store) IntegrityCheck(ctx context.Context) error {
	rows, err := s.read.QueryContext(ctx, `PRAGMA integrity_check`)
	if err != nil {
		return fmt.Errorf("store: checking the integrity of %s: %w", s.path, err)
	}
	defer rows.Close()
	var problems []string
	for rows.Next() {
		var line string
		if err := rows.Scan(&line); err != nil {
			return fmt.Errorf("store: checking the integrity of %s: %w", s.path, err)
		}
		// SQLite answers a healthy database with the single row "ok".
		if line != "ok" {
			problems = append(problems, line)
		}
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("store: checking the integrity of %s: %w", s.path, err)
	}
	if len(problems) > 0 {
		return fmt.Errorf("store: %s is corrupt: %s", s.path, strings.Join(problems, "; "))
	}
	return nil
}

// HasSealedSecrets reports whether anything in this database is encrypted with
// the instance key.
//
// It answers one question, asked at startup: may a new key be generated? A
// fresh install has nothing sealed and a generated key is right; a database
// with installations in it has a GitHub App private key and a webhook secret
// that only the original key opens, and generating a new one there produces an
// instance that starts, looks healthy, and fails inside its first GitHub call.
//
// A provider's credential is the same trap one layer out: a controller that
// generated a fresh key would start, show its hypervisor as configured, and
// fail inside the first call that tried to rent a machine.
//
// So are an account's authenticator secret and an offsite backup remote's
// credentials: an instance with no installation yet can still have both, and a
// fresh key would fail every enrolled sign-in and orphan every archive already
// uploaded under a passphrase. A two-step enrolment nobody confirmed is not
// counted; nothing depends on it and starting again replaces it.
func (s *Store) HasSealedSecrets(ctx context.Context) (bool, error) {
	var n int
	err := s.read.QueryRowContext(ctx, `SELECT (SELECT COUNT(*) FROM installations
		WHERE (private_key_enc IS NOT NULL AND LENGTH(private_key_enc) > 0)
		   OR (webhook_secret_enc IS NOT NULL AND LENGTH(webhook_secret_enc) > 0)
		) + (SELECT COUNT(*) FROM settings WHERE key='tailcat.identity.v1' AND value<>'')
		  + (SELECT COUNT(*) FROM providers
		WHERE (credentials_enc IS NOT NULL AND LENGTH(credentials_enc) > 0)
		   OR (tailcat_address_enc IS NOT NULL AND LENGTH(tailcat_address_enc) > 0))
		  + (SELECT COUNT(*) FROM user_two_step
		WHERE enabled_at IS NOT NULL AND LENGTH(secret_enc) > 0)
		  + (SELECT COUNT(*) FROM backup_remotes
		WHERE (secret_key_enc IS NOT NULL AND LENGTH(secret_key_enc) > 0)
		   OR (passphrase_enc IS NOT NULL AND LENGTH(passphrase_enc) > 0))
		  + (SELECT COUNT(*) FROM instance_settings WHERE secret=1 AND value<>'')`).Scan(&n)
	if err != nil {
		return false, fmt.Errorf("store: counting sealed secrets: %w", err)
	}
	return n > 0, nil
}

// backupBeforeMigrate copies the database before any migration touches it.
//
// It is the one moment a rollback is both most likely to be wanted and least
// likely to have been prepared for: an operator upgrading is not thinking
// about backups, migrations are one-way, and an older binary will now refuse
// to open a database that has moved on. This costs a file copy once per
// release and buys the only rollback there is.
//
// It runs only when there is something to lose. A database being created has
// no rows and no pending-migration risk worth a copy, and an in-memory one has
// nowhere to put it.
func (s *Store) backupBeforeMigrate(ctx context.Context, pending []string) (string, error) {
	if len(pending) == 0 || s.path == "" {
		return "", nil
	}
	abs, err := filepath.Abs(s.path)
	if err != nil {
		return "", err
	}
	root := filepath.Join(filepath.Dir(abs), PreMigrationDir)
	dest := filepath.Join(root, BackupDirPrefix+s.Now().Format("20060102-150405"))
	if err := s.Backup(ctx, filepath.Join(dest, BackupDBName)); err != nil {
		return "", err
	}
	// Pruning after rather than before: a failure to tidy up must not stop an
	// upgrade, and the copy that matters most is the one just taken.
	if err := pruneDirs(root, preMigrationKeep); err != nil {
		slog.Warn("could not prune old pre-migration copies", "dir", root, "error", err)
	}
	return dest, nil
}

// pruneDirs keeps the newest keep directories under root and removes the rest.
//
// It only considers directories this package names, and sorts by that name:
// the timestamp is in it, so the order does not depend on a modification time
// that copying between machines rewrites.
func pruneDirs(root string, keep int) error {
	entries, err := os.ReadDir(root)
	if err != nil {
		return err
	}
	var ours []string
	for _, e := range entries {
		if e.IsDir() && strings.HasPrefix(e.Name(), BackupDirPrefix) {
			ours = append(ours, e.Name())
		}
	}
	sort.Strings(ours)
	if len(ours) <= keep {
		return nil
	}
	var errs []error
	for _, name := range ours[:len(ours)-keep] {
		if err := os.RemoveAll(filepath.Join(root, name)); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

package store

import (
	"context"
	"errors"
	"testing"
)

// A destination has to survive the round trip whole: the offsite pass reads
// these rows and signs requests with what comes back, so a field that silently
// did not persist is a bucket nobody can write to -- or, worse, the wrong one.
func TestABackupRemoteComesBackAsItWasWritten(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	pathStyle := true

	r := &BackupRemote{
		Name: "offsite", Endpoint: "https://s3.eu-west-2.amazonaws.com", Region: "eu-west-2",
		Bucket: "acme-zoomies", Prefix: "prod", AccessKeyID: "AKIAEXAMPLE",
		PathStyle: &pathStyle, Keep: 30, Enabled: true,
	}
	if err := s.CreateBackupRemote(ctx, r); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	if !HasPrefix(r.ID, PrefixBackupRemote) {
		t.Errorf("the id %q does not say what it is", r.ID)
	}

	got, err := s.GetBackupRemoteByName(ctx, "offsite")
	if err != nil {
		t.Fatalf("GetBackupRemoteByName: %v", err)
	}
	if got.Endpoint != r.Endpoint || got.Region != "eu-west-2" || got.Bucket != "acme-zoomies" ||
		got.Prefix != "prod" || got.AccessKeyID != "AKIAEXAMPLE" || got.Keep != 30 || !got.Enabled {
		t.Fatalf("the destination came back as %+v", got)
	}
	if got.PathStyle == nil || !*got.PathStyle {
		t.Errorf("path style came back as %v; an explicit choice must not read as unset", got.PathStyle)
	}

	// Unset is a third answer, not false: it means "choose from the endpoint",
	// which is what every deployment that has never heard of the setting wants.
	r.PathStyle = nil
	if err := s.UpdateBackupRemote(ctx, r); err != nil {
		t.Fatalf("UpdateBackupRemote: %v", err)
	}
	if got, err = s.GetBackupRemote(ctx, r.ID); err != nil {
		t.Fatalf("GetBackupRemote: %v", err)
	}
	if got.PathStyle != nil {
		t.Errorf("path style came back as %v after being cleared", *got.PathStyle)
	}
}

// The secrets go in by their own statement, and the form that carries the rest
// of the row must not be able to wipe them: an operator editing the retention
// on a page they opened yesterday is not rotating the key.
func TestWritingABackupRemotesFormLeavesItsSecretsAlone(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	r := &BackupRemote{Name: "offsite", Endpoint: "http://minio:9000", Bucket: "backups", Enabled: true}
	if err := s.CreateBackupRemote(ctx, r); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	if err := s.SetBackupRemoteSecrets(ctx, r.ID, []byte("sealed-secret"), []byte("sealed-passphrase")); err != nil {
		t.Fatalf("SetBackupRemoteSecrets: %v", err)
	}

	r.Keep = 7
	if err := s.UpdateBackupRemote(ctx, r); err != nil {
		t.Fatalf("UpdateBackupRemote: %v", err)
	}
	got, err := s.GetBackupRemote(ctx, r.ID)
	if err != nil {
		t.Fatalf("GetBackupRemote: %v", err)
	}
	if string(got.SecretKeyEnc) != "sealed-secret" || string(got.PassphraseEnc) != "sealed-passphrase" {
		t.Fatalf("the form wiped the secrets: %q / %q", got.SecretKeyEnc, got.PassphraseEnc)
	}
	if got.Keep != 7 {
		t.Errorf("keep came back as %d", got.Keep)
	}

	// And clearing is explicit, which is how a passphrase is removed from a
	// destination that should send the plain archive.
	if err := s.SetBackupRemoteSecrets(ctx, r.ID, got.SecretKeyEnc, nil); err != nil {
		t.Fatalf("clearing the passphrase: %v", err)
	}
	if got, err = s.GetBackupRemote(ctx, r.ID); err != nil {
		t.Fatalf("GetBackupRemote: %v", err)
	}
	if len(got.PassphraseEnc) != 0 || string(got.SecretKeyEnc) != "sealed-secret" {
		t.Errorf("clearing one secret disturbed the other: %q / %q", got.SecretKeyEnc, got.PassphraseEnc)
	}
}

// The name is the address -- the API route, the log line, the problems drawer
// entry -- so two destinations may not share one. The database says so rather
// than the handler, because a second writer would eventually forget.
func TestTwoBackupRemotesCannotShareAName(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	first := &BackupRemote{Name: "offsite", Endpoint: "http://minio:9000", Bucket: "a", Enabled: true}
	if err := s.CreateBackupRemote(ctx, first); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	second := &BackupRemote{Name: "offsite", Endpoint: "http://minio:9000", Bucket: "b", Enabled: true}
	if err := s.CreateBackupRemote(ctx, second); !errors.Is(err, ErrConflict) {
		t.Fatalf("the second destination called offsite was accepted: %v", err)
	}

	if err := s.DeleteBackupRemote(ctx, first.ID); err != nil {
		t.Fatalf("DeleteBackupRemote: %v", err)
	}
	if _, err := s.GetBackupRemote(ctx, first.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("the deleted destination is still there: %v", err)
	}
	if err := s.DeleteBackupRemote(ctx, first.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("deleting it twice answered %v", err)
	}
	remotes, err := s.ListBackupRemotes(ctx)
	if err != nil || len(remotes) != 0 {
		t.Errorf("the list holds %d destinations, %v", len(remotes), err)
	}
}

package store

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// onDiskStore is a real file rather than :memory:, because everything backup
// and restore is about happens to a file.
func onDiskStore(t *testing.T) (*Store, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	s, err := Open(context.Background(), Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s, path
}

// A backup is only a backup if the copy opens on its own. The documentation
// used to say to copy the database file, which on a running instance leaves
// every recent commit behind in the write-ahead log; VACUUM INTO is what makes
// the copy whole and self-contained.
func TestABackupOpensOnItsOwnAndHasTheRows(t *testing.T) {
	ctx := context.Background()
	s, _ := onDiskStore(t)
	inst := &Installation{AppID: 7, InstallationID: 9, Target: "acme", TargetType: TargetOrg}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	dest := filepath.Join(t.TempDir(), "backup", "copy.db")
	if err := s.Backup(ctx, dest); err != nil {
		t.Fatalf("Backup: %v", err)
	}

	// No write-ahead log beside it: that is what "self-contained" means, and a
	// copy with a WAL is one that needs the other two files to be whole.
	for _, side := range []string{dest + "-wal", dest + "-shm"} {
		if _, err := os.Stat(side); !errors.Is(err, os.ErrNotExist) {
			t.Errorf("the copy has a %s beside it", filepath.Base(side))
		}
	}

	copied, err := Open(ctx, Options{Path: dest, ReadOnly: true})
	if err != nil {
		t.Fatalf("opening the copy: %v", err)
	}
	defer copied.Close()
	if err := copied.IntegrityCheck(ctx); err != nil {
		t.Errorf("the copy does not pass its own integrity check: %v", err)
	}
	got, err := copied.GetInstallation(ctx, inst.ID)
	if err != nil {
		t.Fatalf("the installation is not in the copy: %v", err)
	}
	if got.Target != "acme" {
		t.Errorf("target = %q, want acme", got.Target)
	}
}

// The copy holds every sealed secret and every password hash this instance
// has. VACUUM INTO creates it with the process umask, which on a stock image
// is world-readable.
func TestABackupIsReadableOnlyByItsOwner(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("file modes are a POSIX question")
	}
	ctx := context.Background()
	s, _ := onDiskStore(t)
	dest := filepath.Join(t.TempDir(), "copy.db")
	if err := s.Backup(ctx, dest); err != nil {
		t.Fatalf("Backup: %v", err)
	}
	info, err := os.Stat(dest)
	if err != nil {
		t.Fatalf("Stat: %v", err)
	}
	if perm := info.Mode().Perm(); perm != 0o600 {
		t.Errorf("the backup is mode %04o; want 0600", perm)
	}
}

// The destination of a backup is nearly always a name derived from the date,
// and the one time it is not, the file already there is somebody's older
// backup. Overwriting it on a typo is the failure worth refusing.
func TestABackupNeverOverwritesOne(t *testing.T) {
	ctx := context.Background()
	s, _ := onDiskStore(t)
	dest := filepath.Join(t.TempDir(), "copy.db")
	if err := os.WriteFile(dest, []byte("somebody's older backup"), 0o600); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}
	err := s.Backup(ctx, dest)
	if err == nil {
		t.Fatal("the backup overwrote an existing file")
	}
	kept, rerr := os.ReadFile(dest)
	if rerr != nil || string(kept) != "somebody's older backup" {
		t.Errorf("the existing file was changed: %q, %v", kept, rerr)
	}
}

// Opening read-only must not migrate, because migrating is a write and the
// caller asked to look rather than to touch. A backup being verified has to
// come back exactly as it was written.
func TestAReadOnlyOpenRefusesWritesAndLeavesTheFileAlone(t *testing.T) {
	ctx := context.Background()
	s, path := onDiskStore(t)
	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	before, err := os.Stat(path)
	if err != nil {
		t.Fatalf("Stat: %v", err)
	}

	ro, err := Open(ctx, Options{Path: path, ReadOnly: true})
	if err != nil {
		t.Fatalf("read-only Open: %v", err)
	}
	defer ro.Close()

	if err := ro.CreateInstallation(ctx, &Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: TargetOrg}); !errors.Is(err, ErrReadOnly) {
		t.Errorf("a write on a read-only store returned %v; want ErrReadOnly", err)
	}
	// The refusal names the decision rather than the file, because "attempt to
	// write a readonly database" sends the reader to check permissions.
	if err := ro.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	after, err := os.Stat(path)
	if err != nil {
		t.Fatalf("Stat: %v", err)
	}
	if after.ModTime() != before.ModTime() || after.Size() != before.Size() {
		t.Error("a read-only open changed the file")
	}
}

// Rolling a release back is a thing operators do under pressure, and an older
// binary against a newer schema reads columns whose meaning it does not know
// and writes rows the newer one will not accept -- silently. This is the
// moment to say the database went forward with the release.
func TestOpeningADatabaseFromANewerBuildIsRefused(t *testing.T) {
	ctx := context.Background()
	s, path := onDiskStore(t)
	if _, err := s.exec(ctx, `INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)`,
		"9999_from_the_future.sql", ms(s.Now())); err != nil {
		t.Fatalf("planting a future migration: %v", err)
	}
	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	for _, ro := range []bool{false, true} {
		_, err := Open(ctx, Options{Path: path, ReadOnly: ro})
		if !errors.Is(err, ErrSchemaNewer) {
			t.Errorf("read_only=%v: Open returned %v; want ErrSchemaNewer", ro, err)
		}
		// Naming the migration is the difference between "upgrade something"
		// and knowing which release to go back to.
		if err != nil && !strings.Contains(err.Error(), "9999_from_the_future.sql") {
			t.Errorf("read_only=%v: the refusal does not name the migration: %v", ro, err)
		}
	}
}

// The question this answers is asked once, at startup, before deciding whether
// a new encryption key may be generated.
func TestHasSealedSecretsSeesTheOneThingAKeyOpens(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)

	has, err := s.HasSealedSecrets(ctx)
	if err != nil {
		t.Fatalf("HasSealedSecrets: %v", err)
	}
	if has {
		t.Error("a fresh database reports sealed secrets, so a first run would refuse to generate a key")
	}

	inst := &Installation{
		AppID: 1, InstallationID: 2, Target: "acme", TargetType: TargetOrg,
		PrivateKeyEnc: []byte("sealed"),
	}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}
	has, err = s.HasSealedSecrets(ctx)
	if err != nil {
		t.Fatalf("HasSealedSecrets: %v", err)
	}
	if !has {
		t.Error("an installation with a sealed private key does not count as a sealed secret")
	}
}

// Every column the instance key seals has to count, or a database whose only
// sealed values are one of these gets a silently generated replacement key:
// every authenticator secret then stops opening, and an offsite passphrase is
// lost along with the archives that were uploaded under it.
func TestHasSealedSecretsSeesTwoStepBackupRemoteAndTailcatSecrets(t *testing.T) {
	ctx := context.Background()
	for _, tc := range []struct {
		name string
		seed func(t *testing.T, s *Store)
		want bool
	}{
		{"a confirmed authenticator secret", func(t *testing.T, s *Store) {
			u := seedTwoStepUser(t, s, "ada")
			if err := s.BeginTwoStep(ctx, u.ID, []byte("sealed")); err != nil {
				t.Fatal(err)
			}
			if err := s.ConfirmTwoStep(ctx, u.ID, 1, []string{"h"}); err != nil {
				t.Fatal(err)
			}
		}, true},
		// Nothing is signed in with it yet, and starting again replaces it, so it
		// is not worth refusing a first run for.
		{"an enrolment nobody confirmed", func(t *testing.T, s *Store) {
			u := seedTwoStepUser(t, s, "ada")
			if err := s.BeginTwoStep(ctx, u.ID, []byte("sealed")); err != nil {
				t.Fatal(err)
			}
		}, false},
		{"a backup remote's secret key", func(t *testing.T, s *Store) {
			r := seedBackupRemote(t, s)
			if err := s.SetBackupRemoteSecrets(ctx, r.ID, []byte("sealed"), nil); err != nil {
				t.Fatal(err)
			}
		}, true},
		{"a backup remote's passphrase", func(t *testing.T, s *Store) {
			r := seedBackupRemote(t, s)
			if err := s.SetBackupRemoteSecrets(ctx, r.ID, nil, []byte("sealed")); err != nil {
				t.Fatal(err)
			}
		}, true},
		{"a backup remote with no secrets", func(t *testing.T, s *Store) {
			seedBackupRemote(t, s)
		}, false},
		{"a provider's private connection address", func(t *testing.T, s *Store) {
			p := seedProvider(t, s)
			if err := s.SetProviderTailcatAddress(ctx, p.ID, []byte("sealed")); err != nil {
				t.Fatal(err)
			}
		}, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			s := newTestStore(t)
			tc.seed(t, s)
			has, err := s.HasSealedSecrets(ctx)
			if err != nil {
				t.Fatalf("HasSealedSecrets: %v", err)
			}
			if has != tc.want {
				t.Errorf("HasSealedSecrets = %v with %s, want %v", has, tc.name, tc.want)
			}
		})
	}
}

func seedBackupRemote(t *testing.T, s *Store) *BackupRemote {
	t.Helper()
	r := &BackupRemote{
		Name: "offsite", Endpoint: "https://s3.example", Bucket: "backups", Enabled: true,
	}
	if err := s.CreateBackupRemote(context.Background(), r); err != nil {
		t.Fatalf("CreateBackupRemote: %v", err)
	}
	return r
}

func TestAPrivateConnectionIdentityPreventsGeneratingAReplacementKey(t *testing.T) {
	s := newTestStore(t)
	if err := s.SetSetting(context.Background(), "tailcat.identity.v1", "sealed-identity", true); err != nil {
		t.Fatal(err)
	}
	has, err := s.HasSealedSecrets(context.Background())
	if err != nil || !has {
		t.Fatalf("private connection identity was not protected: %v", err)
	}
}

// A backup destination is data, even when its filename resembles SQL.
func TestBackupBindsTheDestinationAsData(t *testing.T) {
	ctx := context.Background()
	s, _ := onDiskStore(t)
	inst := &Installation{AppID: 7, InstallationID: 9, Target: "acme", TargetType: TargetOrg}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatal(err)
	}
	dest := filepath.Join(t.TempDir(), "operator's-copy'; DROP TABLE installations; --.db")
	if err := s.Backup(ctx, dest); err != nil {
		t.Fatal(err)
	}
	copy, err := Open(ctx, Options{Path: dest, ReadOnly: true})
	if err != nil {
		t.Fatal(err)
	}
	defer copy.Close()
	for _, db := range []*Store{s, copy} {
		rows, err := db.ListInstallations(ctx)
		if err != nil || len(rows) != 1 || rows[0].Target != "acme" {
			t.Fatalf("backup changed data: %v %v", rows, err)
		}
	}
}

package store

import (
	"context"
	"errors"
	"testing"
	"time"
)

func TestBootstrapRevocationRacesRedemption(t *testing.T) {
	for range 30 {
		s := newTestStore(t)
		ctx := context.Background()
		tok := &JoinToken{TokenHash: "race", ExpiresAt: s.Now().Add(time.Hour)}
		if err := s.CreateJoinToken(ctx, tok); err != nil {
			t.Fatal(err)
		}
		start := make(chan struct{})
		revoked, redeemed := make(chan error, 1), make(chan error, 1)
		go func() { <-start; revoked <- s.RevokeUnusedJoinToken(ctx, tok.ID) }()
		go func() {
			<-start
			_, err := s.RedeemJoinToken(ctx, "race", JoinClaim{HostID: "host"}, s.Now())
			redeemed <- err
		}()
		close(start)
		r, d := <-revoked, <-redeemed
		if r == nil {
			if !errors.Is(d, ErrNotFound) {
				t.Fatalf("revoked token redeemed: %v", d)
			}
		} else if !errors.Is(r, ErrJoinTokenUsed) || d != nil {
			t.Fatalf("outcomes: revoke=%v redeem=%v", r, d)
		}
	}
}

func TestBootstrapRevocationFailsClosedOnStoreError(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	tok := &JoinToken{TokenHash: "retained", ExpiresAt: s.Now().Add(time.Hour)}
	if err := s.CreateJoinToken(ctx, tok); err != nil {
		t.Fatal(err)
	}
	if _, err := s.exec(ctx, `CREATE TRIGGER deny_revoke BEFORE DELETE ON join_tokens BEGIN SELECT RAISE(ABORT, 'injected revocation failure'); END`); err != nil {
		t.Fatal(err)
	}
	if err := s.RevokeUnusedJoinToken(ctx, tok.ID); err == nil {
		t.Fatal("revocation failure was swallowed")
	}
	if _, err := s.GetJoinToken(ctx, tok.ID); err != nil {
		t.Fatal("failed revocation lost original credential")
	}
}

package store

import (
	"strings"

	"github.com/eyupio/zoomies/internal/naming"
)

// The brand, as it appears on GitHub.
//
// Two names cross the boundary into somebody else's account: the name of every
// runner Zoomies registers, and the labels a workflow's `runs-on` has to spell
// out. Both are read far more often than they are written -- in the runner list
// on GitHub, in a job's "Set up job" step, in every workflow file in the
// organisation -- so both are short, both start with the product name, and
// neither carries anything a reader would have to decode.
const (
	// Brand is the product name, lowercased, as it appears in a label.
	Brand = "zoomies"

	// BrandLabel is the one label every Zoomies pool answers to. It is what
	// makes `runs-on: zoomies` mean "any runner this fleet has", which is the
	// line a repository can adopt before anyone has decided which pool it
	// belongs in.
	BrandLabel = Brand

	// BrandPrefix is what every name this fleet puts in front of somebody
	// else's eyes starts with: a pool's name, and the runner names derived
	// from it.
	BrandPrefix = Brand + "-"

	// RunnerNamePrefix is what every name NewRunnerName mints starts with. The
	// reaper uses it to tell a registration Zoomies created from one somebody
	// else registered by hand, so it must not appear in front of anything else.
	RunnerNamePrefix = BrandPrefix

	// runnerNameEntropy is how many random bytes go into a runner name. Five
	// encodes to eight base32 characters, which is a name a person can read
	// back over a call and still leaves a collision within one target
	// vanishingly unlikely.
	//
	// The kennel word beside it does not reduce this. Thirty-two words is five
	// bits, which makes two runners share a word about as often as two people
	// in a room of eight share a birthday -- fine for something an operator
	// says out loud, useless as the thing GitHub relies on for uniqueness.
	runnerNameEntropy = 5

	// maxLabelSegment bounds the part of a label derived from something an
	// operator typed. GitHub allows longer, but a label nobody can read at a
	// glance defeats the point of branding it.
	maxLabelSegment = 40
)

// NewRunnerName mints the name one runner of this pool registers under: the
// brand, the pool's shape, a word from the kennel, and a token.
//
// This used to be the brand and eight random characters, on the argument that
// GitHub shows a runner name in narrow columns and the useful facts are a click
// away in Zoomies. The argument was wrong about where the reader is. Somebody
// looking at GitHub's runner list, or at the "Set up job" line of a log, is
// there precisely because they do not yet know which pool they are looking at;
// asking them to go and find out is asking them to leave. What made the old
// name too long was carrying the pool's *invented* name as well as the brand,
// and naming/RunnerName solves that by dropping shape segments rather than the
// brand when a name will not fit.
//
// A nil pool -- a runner Zoomies is naming before it knows where it goes -- gets
// the brand and the discriminator, which is exactly the old name plus a word.
func NewRunnerName(p *Pool) string {
	return naming.RunnerName(runnerBase(p), naming.KennelWord()+"-"+NewSecret(runnerNameEntropy))
}

// runnerBase is the part of a runner's name that says what it is.
//
// The pool's shape wins over the pool's name because the shape is the half a
// reader on GitHub cannot get anywhere else: "4vcpu-ubuntu-2404" answers the
// question they are asking, where "biscuit" is a handle for a thing they are
// not looking at. A pool that has no shape to report -- no resources, no
// platform, which is what a pool created before either was recorded looks like
// -- falls back to its own name, because a name that says something an operator
// chose beats a name that says nothing at all.
func runnerBase(p *Pool) string {
	if p == nil {
		return Brand
	}
	if spec := p.Spec(); !spec.Empty() {
		return spec.String()
	}
	return p.Name
}

// IsRunnerName reports whether name looks like one NewRunnerName minted, which
// is as much as anything outside this package can know about a registration it
// finds on GitHub.
func IsRunnerName(name string) bool {
	return strings.HasPrefix(NormalizeLabel(name), RunnerNamePrefix)
}

// MachineNamePrefix is what every name NewMachineName mints starts with. A
// sweep looking for machines this fleet rented matches on it, so nothing else
// may be named this way.
const MachineNamePrefix = BrandPrefix + PrefixMachine + "-"

// NewMachineName is what the provider records a machine as. It carries the
// "zoomies-" prefix for the same reason a runner name does: a cluster-wide
// sweep must never mistake somebody else's VM for one of ours, and on a
// hypervisor an operator shares with other work that mistake deletes something
// nobody asked us to touch.
//
// The machine's own ID is what follows, so a VM in the Proxmox console and a
// row on the machines page name each other without a lookup.
func NewMachineName(machineID string) string {
	_, fragment, ok := strings.Cut(machineID, "_")
	if !ok || fragment == "" {
		fragment = machineID
	}
	return MachineNamePrefix + SanitizeLabel(fragment)
}

// IsMachineName reports whether name looks like one NewMachineName minted,
// which is as much as a sweep can know about a guest it finds at a provider.
func IsMachineName(name string) bool {
	return strings.HasPrefix(NormalizeLabel(name), MachineNamePrefix)
}

// BrandLabels returns labels with BrandLabel guaranteed present, normalised.
//
// Adding it is not cosmetic: it is what lets a workflow ask for this fleet
// without naming one of its pools, and what the migration wizard rewrites
// `runs-on: ubuntu-latest` to when the operator has not chosen a pool. A pool
// that did not answer to it would be invisible to both.
func BrandLabels(in []string) []string {
	return NormalizeLabels(append([]string{BrandLabel}, in...))
}

// BrandedLabel turns a pool name into the label a workflow writes: the brand,
// then the name with everything GitHub dislikes replaced by a hyphen.
//
// A pool already named for the brand is returned as it is, so that naming a
// pool "zoomies-gpu" does not produce "zoomies-zoomies-gpu".
func BrandedLabel(name string) string {
	s := SanitizeLabel(name)
	switch {
	case s == "":
		return BrandLabel
	case s == Brand || strings.HasPrefix(s, RunnerNamePrefix):
		return s
	default:
		return RunnerNamePrefix + s
	}
}

// BrandedName returns a pool name carrying the brand, which every pool name
// has to.
//
// A pool's name is not private to Zoomies. It is what BrandedLabel turns into
// the label a workflow's `runs-on` spells out, it is the word in an audit line
// somebody reads months later, and it is how the pool is named in the runner
// list of an account that also has runners nobody here registered. A pool
// called "gpu" makes all of those say something that could have come from
// anywhere, and renaming it afterwards does not un-write the workflows already
// pointing at it -- so a name arriving without the brand gains it here rather
// than being refused, which is the treatment BrandLabels already gives a label
// list, for the same reason.
//
// An empty name is returned unchanged: "a pool needs a name" is a better thing
// for an operator to be told than a pool called "zoomies-".
func BrandedName(name string) string {
	s := strings.TrimSpace(name)
	if s == "" || IsBrandedName(s) {
		return s
	}
	return BrandPrefix + strings.TrimLeft(s, "-")
}

// IsBrandedName reports whether name already carries the brand, comparing the
// way GitHub compares labels so that "Zoomies-GPU" is not given a second one.
func IsBrandedName(name string) bool {
	s := NormalizeLabel(name)
	return s == Brand || strings.HasPrefix(s, BrandPrefix)
}

// SanitizeLabel reduces an arbitrary string to the characters GitHub accepts in
// a runner label: lowercase letters, digits and hyphens, with no hyphen at
// either end.
func SanitizeLabel(s string) string {
	s = NormalizeLabel(s)
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			b.WriteRune(r)
		default:
			b.WriteRune('-')
		}
	}
	out := strings.Trim(collapseHyphens(b.String()), "-")
	if len(out) > maxLabelSegment {
		out = strings.Trim(out[:maxLabelSegment], "-")
	}
	return out
}

// collapseHyphens turns runs of hyphens into one, so that "Ubuntu 24.04"
// sanitises to "ubuntu-24-04" rather than "ubuntu-24-04" with a gap where the
// space and the dot both became hyphens.
func collapseHyphens(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	prev := rune(0)
	for _, r := range s {
		if r == '-' && prev == '-' {
			continue
		}
		b.WriteRune(r)
		prev = r
	}
	return b.String()
}

// RunsOn renders the shortest `runs-on` value that reaches a pool advertising
// these labels.
//
// A pool with one label of its own is reached by that label alone, which is the
// whole reason the labels are branded: "runs-on: zoomies-linux-x64" says where
// the job runs, and a reviewer of the pull request that introduced it does not
// have to know what "self-hosted, linux, x64" resolves to in this
// organisation. Where a pool really does need several labels to be identified,
// the list form is rendered instead, because dropping one would send jobs
// somewhere else.
func RunsOn(labels []string) string {
	var specific []string
	for _, l := range NormalizeLabels(labels) {
		if ImplicitLabels[l] || l == BrandLabel {
			continue
		}
		specific = append(specific, l)
	}
	switch len(specific) {
	case 1:
		return specific[0]
	case 0:
		// Nothing but the brand and the labels every self-hosted runner
		// already has. The brand still names this fleet; "self-hosted" is the
		// last resort and matches any of them.
		for _, l := range NormalizeLabels(labels) {
			if l == BrandLabel {
				return BrandLabel
			}
		}
		return "self-hosted"
	default:
		return "[" + strings.Join(specific, ", ") + "]"
	}
}

package store

import (
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/naming"
)

func TestNewRunnerNameCarriesTheShapeOfItsPool(t *testing.T) {
	pool := &Pool{
		Name:      "zoomies-biscuit-docker-linux",
		Resources: Resources{CPUs: 4, MemoryMB: 8 * 1024},
		Platform:  Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "amd64"},
	}
	// The point of the shape: somebody reading GitHub's runner list learns how
	// much machine the job got and what it ran on, without leaving the page.
	const want = "zoomies-4vcpu-8gb-ubuntu-2404-"
	name := NewRunnerName(pool)
	if !strings.HasPrefix(name, want) {
		t.Fatalf("NewRunnerName = %q, want it to start with %q", name, want)
	}
	// And the shape is the pool's, not the pool's invented name: the operator
	// chose "biscuit-docker-linux" for a thing the reader is not looking at.
	//
	// Asserted on the part of that name no kennel word can be. Every runner
	// name ends in one drawn from naming.Kennel, "biscuit" among them, so a
	// test that looked for the word alone failed roughly one run in thirty
	// for a reason that had nothing to do with pools.
	if strings.Contains(name, "docker-linux") {
		t.Errorf("NewRunnerName = %q, want the pool's shape rather than its name", name)
	}
}

func TestNewRunnerNameFallsBackToThePoolName(t *testing.T) {
	// A pool recorded before resources and platform were: there is no shape to
	// report, and the name the operator chose says more than nothing does.
	pool := &Pool{Name: "zoomies-biscuit-docker-linux"}
	if name := NewRunnerName(pool); !strings.HasPrefix(name, "zoomies-biscuit-docker-linux-") {
		t.Errorf("NewRunnerName = %q, want it to fall back to the pool's own name", name)
	}
	// And a runner being named before it has a pool is still ours to reap.
	if name := NewRunnerName(nil); !IsRunnerName(name) {
		t.Errorf("NewRunnerName(nil) = %q, want a name the reaper recognises", name)
	}
}

func TestNewRunnerNameIsBrandedUniqueAndShortEnoughForGitHub(t *testing.T) {
	pools := []*Pool{
		nil,
		{Name: "zoomies-4vcpu-ubuntu-2404", Resources: Resources{CPUs: 4},
			Platform: Platform{OS: "ubuntu", OSVersion: "24.04"}},
		// The worst case a real fleet can produce: every dimension named, on a
		// pool whose own name is as long as the store will take.
		{Name: strings.Repeat("long-", 12), Resources: Resources{CPUs: 192, MemoryMB: 768 * 1024},
			Platform: Platform{OS: "ubuntu", OSVersion: "24.04", Arch: "arm64"}},
		{Name: strings.Repeat("long-", 12)},
	}
	seen := map[string]bool{}
	for _, pool := range pools {
		for range 200 {
			name := NewRunnerName(pool)
			if !strings.HasPrefix(name, "zoomies-") {
				t.Fatalf("runner name %q is not branded", name)
			}
			// GitHub refuses a longer one, and it refuses it at registration --
			// several seconds into provisioning a runner somebody is waiting for.
			if len(name) > 64 {
				t.Fatalf("runner name %q is %d characters, more than GitHub accepts", name, len(name))
			}
			// The token is the last two segments' worth of the name and is what
			// makes it unique; truncation that ate it would produce collisions
			// only under load, which is the worst time to find out.
			if seen[name] {
				t.Fatalf("runner name %q was minted twice in 200 tries", name)
			}
			seen[name] = true
			if !IsRunnerName(name) {
				t.Fatalf("IsRunnerName(%q) = false, want true for a name we just minted", name)
			}
		}
	}
}

func TestNewRunnerNameReadsBackAsItsPoolsSpec(t *testing.T) {
	// A runner's name is in the grammar, so anything holding one can recover
	// what it was made of -- which is what makes the name worth its characters.
	pool := &Pool{
		Name:      "zoomies-8vcpu-debian-12-arm64",
		Resources: Resources{CPUs: 8},
		Platform:  Platform{OS: "debian", OSVersion: "12", Arch: "arm64"},
	}
	spec, ok := naming.Parse(NewRunnerName(pool))
	if !ok {
		t.Fatal("a runner name does not parse back into the grammar that built it")
	}
	if spec.CPUs != 8 || spec.OS != "debian" || spec.Version != "12" || spec.Arch != "arm64" {
		t.Errorf("parsed %+v, want the pool's 8 vCPU Debian 12 arm64 shape", spec)
	}
	if spec.Suffix == "" {
		t.Error("parsed no discriminator, so two runners of this pool would share a name")
	}
}

func TestIsRunnerNameRejectsSomebodyElsesRunner(t *testing.T) {
	for _, name := range []string{"", "runner-01", "gh-zoomies-1", "zoomies", "azoomies-x"} {
		if IsRunnerName(name) {
			t.Errorf("IsRunnerName(%q) = true, want false: the reaper would delete a registration it does not own", name)
		}
	}
	// GitHub does not promise the case it echoes back, and deleting the wrong
	// runner is worse than being generous here.
	if !IsRunnerName("Zoomies-A3F9QZ2M") {
		t.Error("IsRunnerName does not recognise its own name in a different case")
	}
}

func TestBrandLabelsAlwaysCarryTheBrand(t *testing.T) {
	cases := []struct {
		name string
		in   []string
		want []string
	}{
		{"empty", nil, []string{"zoomies"}},
		{"adds the brand", []string{"gpu"}, []string{"gpu", "zoomies"}},
		{"does not duplicate it", []string{"Zoomies", "gpu"}, []string{"gpu", "zoomies"}},
		{"normalises the rest", []string{" GPU ", "gpu"}, []string{"gpu", "zoomies"}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := BrandLabels(c.in)
			if strings.Join(got, ",") != strings.Join(c.want, ",") {
				t.Fatalf("BrandLabels(%v) = %v, want %v", c.in, got, c.want)
			}
		})
	}
}

func TestBrandedLabel(t *testing.T) {
	cases := []struct{ in, want string }{
		{"linux-x64", "zoomies-linux-x64"},
		{"GPU", "zoomies-gpu"},
		{"Ubuntu 24.04", "zoomies-ubuntu-24-04"},
		{"zoomies-gpu", "zoomies-gpu"},
		{"zoomies", "zoomies"},
		{"", "zoomies"},
		{"---", "zoomies"},
		{strings.Repeat("a", 60), "zoomies-" + strings.Repeat("a", 40)},
	}
	for _, c := range cases {
		if got := BrandedLabel(c.in); got != c.want {
			t.Errorf("BrandedLabel(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestSanitizeLabelCollapsesRunsOfPunctuation(t *testing.T) {
	if got := SanitizeLabel("big  builders!!"); got != "big-builders" {
		t.Fatalf("SanitizeLabel = %q, want %q", got, "big-builders")
	}
}

// A pool name is what a workflow's runs-on ends up spelling and what GitHub
// shows next to runners somebody else may also have registered, so a name
// arriving without the brand has to come out of here with it.
func TestBrandedNameAlwaysCarriesTheBrand(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"adds the brand", "gpu", "zoomies-gpu"},
		{"keeps one it already has", "zoomies-gpu", "zoomies-gpu"},
		{"does not duplicate it in another case", "Zoomies-GPU", "Zoomies-GPU"},
		{"the brand alone is branded enough", "zoomies", "zoomies"},
		{"trims what an operator pasted", "  gpu  ", "zoomies-gpu"},
		{"does not double the hyphen", "-gpu", "zoomies-gpu"},
		{"a name that only looks branded is not", "zoomiesgpu", "zoomies-zoomiesgpu"},
		// "a pool needs a name" is a better thing to be told than to be given
		// a pool called "zoomies-".
		{"leaves an empty name empty", "   ", ""},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := BrandedName(c.in); got != c.want {
				t.Fatalf("BrandedName(%q) = %q, want %q", c.in, got, c.want)
			}
			if c.want != "" && !IsBrandedName(c.want) {
				t.Fatalf("IsBrandedName(%q) = false for a name BrandedName just produced", c.want)
			}
		})
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"strings"
	"testing"
)

func TestCleanupRetriesOnlySettleTheirOwnFailure(t *testing.T) {
	for _, hostFirst := range []bool{false, true} {
		name := "GitHub recovers first"
		if hostFirst {
			name = "host recovers first"
		}
		t.Run(name, func(t *testing.T) {
			s := newTestStore(t)
			ctx := context.Background()
			_, pool, host := seedPool(t, s)
			r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "cleanup-test"}
			if err := s.CreateRunner(ctx, r); err != nil {
				t.Fatal(err)
			}
			// A later failure invalidates an earlier completion stamp too.
			if err := s.ClearCleanupFailure(ctx, r.ID); err != nil {
				t.Fatal(err)
			}
			if err := s.RecordCleanupFailure(ctx, r.ID, "container is in use"); err != nil {
				t.Fatal(err)
			}
			if err := s.RecordRegistrationCleanupFailure(ctx, r.ID, "registration deletion refused"); err != nil {
				t.Fatal(err)
			}
			got, err := s.GetRunner(ctx, r.ID)
			if err != nil {
				t.Fatal(err)
			}
			if !strings.Contains(got.CleanupError, "container") || !strings.Contains(got.CleanupError, "registration") || got.CleanedUpAt != nil {
				t.Fatalf("both failures must remain visible: %+v", got)
			}
			// And each is readable on its own, so what is said about the row can
			// name the half that needs doing rather than whichever keyword the
			// joined sentence happens to contain.
			if got.HostCleanupError != "container is in use" || got.RegistrationCleanupError != "registration deletion refused" {
				t.Fatalf("halves = %q / %q", got.HostCleanupError, got.RegistrationCleanupError)
			}
			first, last := s.RecordRegistrationDeleted, s.ClearCleanupFailure
			remaining := "container is in use"
			if hostFirst {
				first, last = last, first
				remaining = "registration deletion refused"
			}
			// Duplicate success must also leave the other failure standing.
			for range 2 {
				if err := first(ctx, r.ID); err != nil {
					t.Fatal(err)
				}
			}
			got, err = s.GetRunner(ctx, r.ID)
			if err != nil {
				t.Fatal(err)
			}
			if got.CleanupError != remaining || got.CleanupFailedAt == nil || got.CleanedUpAt != nil {
				t.Fatalf("first recovery hid the remaining failure: %+v", got)
			}
			if err := last(ctx, r.ID); err != nil {
				t.Fatal(err)
			}
			got, err = s.GetRunner(ctx, r.ID)
			if err != nil {
				t.Fatal(err)
			}
			if got.CleanupError != "" || got.CleanupFailedAt != nil || got.CleanupAttempts != 2 {
				t.Fatalf("both recoveries must clear errors and keep the attempt count: %+v", got)
			}
		})
	}
}

func TestCleanupMigrationPreservesExistingFailureSources(t *testing.T) {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	// The columns before 0022, with a stale completion stamp on a failed
	// cleanup: that is an existing database the migration must repair.
	_, err = db.Exec(`CREATE TABLE runners (id TEXT PRIMARY KEY, cleanup_error TEXT NOT NULL, cleaned_up_at INTEGER);
		INSERT INTO runners VALUES ('host', 'remove_runner failed: daemon unavailable', 123),
		('github', 'the GitHub runner registration could not be deleted: denied', 123),
		('clean', '', 123);`)
	if err != nil {
		t.Fatal(err)
	}
	body, err := migrationFS.ReadFile("migrations/0022_cleanup_failure_sources.sql")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(string(body)); err != nil {
		t.Fatal(err)
	}
	for _, id := range []string{"host", "github", "clean"} {
		var combined, host, registration string
		var cleaned sql.NullInt64
		if err := db.QueryRow(`SELECT cleanup_error, host_cleanup_error, registration_cleanup_error, cleaned_up_at FROM runners WHERE id=?`, id).Scan(&combined, &host, &registration, &cleaned); err != nil {
			t.Fatal(err)
		}
		switch id {
		case "host":
			if host != combined || registration != "" || cleaned.Valid {
				t.Fatalf("host failure was not preserved: %q, %q, %v", host, registration, cleaned)
			}
		case "github":
			if registration != combined || host != "" || cleaned.Valid {
				t.Fatalf("registration failure was not preserved: %q, %q, %v", host, registration, cleaned)
			}
		case "clean":
			if host != "" || registration != "" || !cleaned.Valid || cleaned.Int64 != 123 {
				t.Fatal("migration changed a row with no recorded failure")
			}
		}
	}
}

// A host failure that arrives after the host confirmed the removal is about
// an attempt the confirmation overtook, and the two travel on separate
// requests, so the store refuses it as it writes rather than trusting a
// caller's copy of the row that may predate the confirmation.
func TestAHostFailureAfterTheHostConfirmedRemovalIsRefused(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "confirmed", State: RunnerRemoved}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ConfirmRunnerCleanup(ctx, r.ID, true); err != nil {
		t.Fatal(err)
	}

	err := s.RecordCleanupFailure(ctx, r.ID, "removal of container confirmed-dind is already in progress")
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("RecordCleanupFailure on a confirmed removal = %v, want ErrConflict", err)
	}
	got, err := s.GetRunner(ctx, r.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.HostRemovedAt == nil || got.HostCleanupError != "" || got.CleanupError != "" || got.CleanupAttempts != 0 {
		t.Fatalf("a late failure re-opened a confirmed removal: %+v", got)
	}

	// A runner with no row is still not an error: there is nothing to record.
	if err := s.RecordCleanupFailure(ctx, "run_gone", "x"); err != nil {
		t.Fatalf("RecordCleanupFailure on a missing runner = %v, want nil", err)
	}
}

