func TestADeploymentReviewDoesNotStartTheSchedulingClock(t *testing.T) {
	now := time.Date(2026, 9, 9, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	job, err := s.UpsertJob(ctx, &Job{GitHubJobID: 9301, Repo: "acme/review", State: JobWaiting, Matched: true})
	if err != nil || job.EligibleAt != nil {
		t.Fatalf("a held job was marked eligible: %+v, %v", job, err)
	}
	now = now.Add(time.Hour)
	job, err = s.UpsertJob(ctx, &Job{GitHubJobID: 9301, Repo: "acme/review", State: JobQueued, Matched: true})
	if err != nil || job.EligibleAt == nil || !job.EligibleAt.Equal(now) {
		t.Fatalf("approval did not start the scheduling clock: %+v, %v", job, err)
	}
	if !job.QueuedAt.Equal(now) {
		t.Fatal("queue wait still includes the deployment review")
	}
	approved := now
	now = now.Add(time.Minute)
	job, err = s.UpsertJob(ctx, &Job{GitHubJobID: 9301, Repo: "acme/review", State: JobQueued, Matched: true})
	if err != nil || !job.QueuedAt.Equal(approved) || !job.EligibleAt.Equal(approved) {
		t.Fatalf("a replay moved the approval boundary: %+v, %v", job, err)
	}
}

func TestCleanupCompletesOnlyAfterBothPositiveConfirmations(t *testing.T) {
	for _, hostFirst := range []bool{false, true} {
		name := "registration first"
		if hostFirst {
			name = "host first"
		}
		t.Run(name, func(t *testing.T) {
			now := time.Date(2026, 9, 9, 12, 0, 0, 0, time.UTC)
			s := newTestStoreAt(t, func() time.Time { return now })
			ctx := context.Background()
			_, pool, host := seedPool(t, s)
			r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "confirmed-cleanup"}
			if err := s.CreateRunner(ctx, r); err != nil {
				t.Fatal(err)
			}
			if err := s.ClearCleanupFailure(ctx, r.ID); err != nil {
				t.Fatal(err)
			}
			got, err := s.GetRunner(ctx, r.ID)
			if err != nil || got.CleanedUpAt != nil {
				t.Fatalf("a successful stop is not removal: %+v, %v", got, err)
			}
			if done, err := s.ConfirmRunnerCleanup(ctx, r.ID, hostFirst); err != nil || done {
				t.Fatalf("first confirmation completed cleanup: %v, %v", done, err)
			}
			got, err = s.GetRunner(ctx, r.ID)
			if err != nil || got.CleanedUpAt != nil {
				t.Fatalf("first confirmation stamped completion: %+v, %v", got, err)
			}
			now = now.Add(2 * time.Minute)
			if done, err := s.ConfirmRunnerCleanup(ctx, r.ID, !hostFirst); err != nil || !done {
				t.Fatalf("second confirmation did not complete cleanup: %v, %v", done, err)
			}
			got, err = s.GetRunner(ctx, r.ID)
			if err != nil || got.CleanedUpAt == nil || !got.CleanedUpAt.Equal(now) {
				t.Fatalf("completion must use the final confirmation: %+v, %v", got, err)
			}
			now = now.Add(time.Hour)
			for _, side := range []bool{hostFirst, !hostFirst} {
				if done, err := s.ConfirmRunnerCleanup(ctx, r.ID, side); err != nil || done {
					t.Fatalf("duplicate confirmation counted another completion: %v, %v", done, err)
				}
			}
			after, err := s.GetRunner(ctx, r.ID)
			if err != nil || !after.CleanedUpAt.Equal(*got.CleanedUpAt) {
				t.Fatalf("redelivery overwrote the cleanup timing: %+v, %v", after, err)
			}
		})
	}
}

func TestTimingMigrationPreservesEstimatesWithoutInventingConfirmations(t *testing.T) {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	_, err = db.Exec(`CREATE TABLE runners (id TEXT PRIMARY KEY, cleaned_up_at INTEGER);
 INSERT INTO runners VALUES ('old', 123), ('unknown', NULL);
 CREATE TABLE jobs (id TEXT PRIMARY KEY, state TEXT, eligible_at INTEGER);
 INSERT INTO jobs VALUES ('held', 'waiting', 100), ('queued', 'queued', 200);`)
	if err != nil {
		t.Fatal(err)
	}
	body, err := migrationFS.ReadFile("migrations/0023_runner_confirmed_timings.sql")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec(string(body)); err != nil {
		t.Fatal(err)
	}
	for _, id := range []string{"old", "unknown"} {
		var cleaned, estimated, host, issued sql.NullInt64
		if err := db.QueryRow(`SELECT cleaned_up_at, cleanup_estimated_at, host_removed_at, create_task_issued_at FROM runners WHERE id=?`, id).Scan(&cleaned, &estimated, &host, &issued); err != nil {
			t.Fatal(err)
		}
		if cleaned.Valid || host.Valid || issued.Valid {
			t.Fatal("migration invented an observed timing")
		}
		if (id == "old" && (!estimated.Valid || estimated.Int64 != 123)) || (id == "unknown" && estimated.Valid) {
			t.Fatal("migration did not preserve the historical estimate")
		}
	}
	for _, id := range []string{"held", "queued"} {
		var eligible sql.NullInt64
		if err := db.QueryRow(`SELECT eligible_at FROM jobs WHERE id=?`, id).Scan(&eligible); err != nil {
			t.Fatal(err)
		}
		if (id == "held" && eligible.Valid) || (id == "queued" && (!eligible.Valid || eligible.Int64 != 200)) {
			t.Fatalf("wrong eligibility for %s: %+v", id, eligible)
		}
	}
}

package store

import (
	"context"
	"errors"
	"testing"
	"time"
)

// The usage ledger exists so runner-hours outlive the runner row, and a
// runner's session is normally written when its cleanup is confirmed. A host,
// pool or installation that goes first takes the runner rows with it, and a
// runner still live or not yet confirmed clean would then have no session and
// drop out of the usage report for good -- short by exactly the hours an
// operator reconciles against the cloud bill. The delete writes the session as
// the row goes, as PruneRunners does.
func TestDeletingAHostPoolOrInstallationKeepsItsRunnersInTheUsageLedger(t *testing.T) {
	for _, tc := range []struct {
		name string
		del  func(t *testing.T, s *Store, inst *Installation, pool *Pool, host *Host)
	}{
		{"host", func(t *testing.T, s *Store, _ *Installation, _ *Pool, host *Host) {
			if _, err := s.DeleteHost(context.Background(), host.ID); err != nil {
				t.Fatalf("DeleteHost: %v", err)
			}
		}},
		{"pool", func(t *testing.T, s *Store, _ *Installation, pool *Pool, _ *Host) {
			if _, _, err := s.DeletePool(context.Background(), pool.ID); err != nil {
				t.Fatalf("DeletePool: %v", err)
			}
		}},
		{"installation", func(t *testing.T, s *Store, inst *Installation, _ *Pool, _ *Host) {
			if _, err := s.DeleteInstallation(context.Background(), inst.ID); err != nil {
				t.Fatalf("DeleteInstallation: %v", err)
			}
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			day := time.Date(2026, 5, 10, 0, 0, 0, 0, time.UTC)
			now := day
			s := newTestStoreAt(t, func() time.Time { return now })
			ctx := context.Background()
			inst, pool, host := seedPool(t, s)
			pricedPool(t, s, pool, 0.36)

			// Removed, cleanup unconfirmed: no session yet.
			unconfirmed := runnerLife(t, s, &now, pool, host, "unconfirmed", day.Add(time.Hour), day.Add(3*time.Hour), 0)
			// Confirmed: its session was written at the time and must stay as it was.
			done := confirmed(t, s, &now, pool, host, "done", day.Add(4*time.Hour), day.Add(5*time.Hour))
			recorded := sessionsFor(t, s, done.ID)
			if len(recorded) != 1 {
				t.Fatalf("a confirmed runner has %d sessions, want 1", len(recorded))
			}
			// Still live when the delete comes.
			now = day.Add(6 * time.Hour)
			live := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "live", State: RunnerIdle}
			if err := s.CreateRunner(ctx, live); err != nil {
				t.Fatal(err)
			}
			now = day.Add(7 * time.Hour)

			tc.del(t, s, inst, pool, host)

			for _, r := range []*Runner{unconfirmed, done, live} {
				if _, err := s.GetRunner(ctx, r.ID); !errors.Is(err, ErrNotFound) {
					t.Fatalf("runner %s survived the delete: %v", r.Name, err)
				}
			}
			for _, r := range []*Runner{unconfirmed, live} {
				got := sessionsFor(t, s, r.ID)
				if len(got) != 1 {
					t.Fatalf("runner %s has %d sessions after the delete, want 1", r.Name, len(got))
				}
				if got[0].PoolID != pool.ID || got[0].HostID != host.ID || got[0].InstallationID != inst.ID {
					t.Fatalf("the session of %s lost its owners: %+v", r.Name, got[0])
				}
				if got[0].CostPerRunnerHour == nil || *got[0].CostPerRunnerHour != 0.36 {
					t.Fatalf("the session of %s was not priced at the rate when it ran: %v", r.Name, got[0].CostPerRunnerHour)
				}
			}
			if got := sessionsFor(t, s, unconfirmed.ID)[0].FinishedAt; !got.Equal(day.Add(3 * time.Hour)) {
				t.Fatalf("the removed runner's session ends %v, want when it was removed", got)
			}
			if got := sessionsFor(t, s, live.ID)[0].FinishedAt; !got.Equal(now) {
				t.Fatalf("the live runner's session ends %v, want when the delete took it", got)
			}
			if got := sessionsFor(t, s, done.ID); len(got) != 1 || !got[0].RecordedAt.Equal(recorded[0].RecordedAt) {
				t.Fatalf("a session already recorded was rewritten: %+v", got)
			}
			if n := sessionCount(t, s); n != 3 {
				t.Fatalf("%d sessions after the delete, want one per runner", n)
			}
		})
	}
}

