package store

// FaultKind is why the fleet, rather than the workflow, is the reason a job
// went wrong -- in the terms the operator's next move is decided in.
//
// GitHub records a job whose runner died exactly as it records a job whose
// tests failed: "failure". An operator reading that list has no way to tell
// the afternoon their code was broken from the afternoon their fleet was, and
// the two need completely different people. This is the fleet's own half of
// that answer.
//
// Every kind exists because something different is done about it -- a memory
// limit is raised, a registry credential is fixed, a host is looked at. A kind
// nothing acts on would be prose, and prose belongs in the fault's message.
type FaultKind string

const (
	// FaultHostLost is a host that stopped answering while it was running the
	// job. The runner went with the machine, and nothing here could stop it.
	FaultHostLost FaultKind = "host_lost"
	// FaultOutOfMemory is a runner killed for exceeding its memory limit. It
	// is kept apart from FaultRunnerExited because it is the commonest fleet
	// fault by a distance and the only one an operator fixes by typing a
	// number.
	FaultOutOfMemory FaultKind = "out_of_memory"
	// FaultOutOfDisk is a host with no room left. The job is only ever the one
	// unlucky enough to be running when the disk filled.
	FaultOutOfDisk FaultKind = "out_of_disk"
	// FaultRemoved is an operator who took the runner away with force while it
	// was working. It is a fleet fault because the workflow did nothing wrong,
	// but it is the one kind that needs no fixing: somebody meant it.
	FaultRemoved FaultKind = "removed"
	// FaultImage is a runner image that could not be pulled or would not
	// start: a tag that is not there, a registry that refused the credential.
	FaultImage FaultKind = "image"
	// FaultRegistration is GitHub refusing to register the runner -- a JIT
	// config it would not mint, an App whose permissions have moved. The
	// container may be perfectly healthy; it has nothing to attach to.
	FaultRegistration FaultKind = "registration"
	// FaultBackend is the container backend refusing the work or not
	// answering: a Docker socket that is not there, a daemon that never became
	// ready. This is the "cannot start the runner container" case.
	FaultBackend FaultKind = "backend"
	// FaultContainerConflict needs ownership inspection, not socket repair.
	FaultContainerConflict FaultKind = "container_conflict"
	// FaultBackendBusy is the daemon that is there and did not answer in time.
	// It is kept apart from FaultBackend because it is the one backend failure
	// where nothing is wrong with the backend: the host is carrying more work
	// than dockerd can keep up with, and the fix is on the pool's limits or
	// the host's capacity rather than on the socket. Sent to check whether the
	// daemon is running, an operator finds it running and stops believing the
	// fault line.
	FaultBackendBusy FaultKind = "backend_busy"
	// FaultConfig is a setting the runner itself refused. Nothing but an edit
	// fixes it, and until it is edited every runner in the pool will do the
	// same thing.
	FaultConfig FaultKind = "config"
	// FaultRunnerExited is a runner that stopped and could not be narrowed
	// further, including a kind reported by an agent newer than this build. It
	// is the unclassified case on purpose: guessing a kind would send somebody
	// to fix the wrong thing, and "read the runner's log" is honest.
	FaultRunnerExited FaultKind = "runner_exited"
)

// The two domains a failure can belong to. They are the whole point of the
// taxonomy: everything else is detail within one of them.
const (
	// FaultDomainWorkflow is the workflow's own outcome -- code that did not
	// compile, a test that did not pass. The fleet did its part.
	FaultDomainWorkflow = "workflow"
	// FaultDomainFleet is Zoomies' own: the job never got a working runner, or
	// lost the one it had.
	FaultDomainFleet = "fleet"
)

// allFaultKinds is the closed set, in the order the UI and the docs list them:
// the ones that happen to a running job first, then the ones that stop a runner
// ever taking one.
var allFaultKinds = []FaultKind{
	FaultHostLost, FaultOutOfMemory, FaultOutOfDisk, FaultRemoved,
	FaultImage, FaultRegistration, FaultBackend, FaultBackendBusy, FaultContainerConflict, FaultConfig, FaultRunnerExited,
}

// FaultKinds returns the closed set. The docs test and the UI's label table
// both read it, so a kind added here and nowhere else fails a test rather than
// rendering as a raw identifier.
func FaultKinds() []FaultKind { return append([]FaultKind(nil), allFaultKinds...) }

// Valid reports whether k is a kind this build knows. It is the check made
// before trusting a kind that arrived from anywhere but this package's own
// constants -- an agent, or a row written by a newer build.
func (k FaultKind) Valid() bool {
	for _, known := range allFaultKinds {
		if k == known {
			return true
		}
	}
	return false
}

// Normalise answers a kind this build knows for any kind at all: itself when it
// is known, FaultRunnerExited for anything else that is set, and empty for
// empty. An unrecognised kind reading as "we could not narrow it" is the safe
// direction -- it tells the operator to go and look, which is true.
func (k FaultKind) Normalise() FaultKind {
	switch {
	case k == "":
		return ""
	case k.Valid():
		return k
	}
	return FaultRunnerExited
}

// Fix is what to do about a fault of this kind, written for the person who has
// to do it. Empty for a kind that needs nothing done.
func (k FaultKind) Fix() string {
	switch k {
	case FaultHostLost:
		return "check that the host is up and its zoomies agent can still reach this controller; a machine that reboots takes its runners with it."
	case FaultOutOfMemory:
		return "raise the pool's memory limit, or put the pool on a host with more memory. The runner's page names the limit it was given."
	case FaultOutOfDisk:
		return "free space on the host, or give it a larger disk. Runner images and workflow caches are the usual weight."
	case FaultRemoved:
		return "nothing, unless the removal was a mistake: somebody removed this runner with force while it was working."
	case FaultImage:
		return "check the pool's image tag and that the host can reach the registry it is on."
	case FaultRegistration:
		return "check that the GitHub App is still installed on the repository and still holds its runner permissions."
	case FaultContainerConflict:
		return "this runner's container name is held by a container Zoomies would not touch, was taken again after Zoomies removed its own, or is reserved to nothing the daemon can show with no create of this runner's on record; the runner's message says which. Inspect the container's Zoomies ownership labels and parent runner, and check for duplicate agents sharing the daemon, but do not remove an active runner or a container owned by another workload."
	case FaultBackend:
		return "check the container backend on the host: the socket the agent names on the host's page, and whether the daemon is running."
	case FaultBackendBusy:
		return "the daemon is there and did not answer in time, or was too slow to finish creating a container, so it is the host that is overloaded rather than the backend that is broken: lower the host's capacity or the pool's maximum runners, or give the pool CPU and memory limits so the daemon keeps a share of the machine. The host's throttle steps it down on its own while the pressure lasts."
	case FaultConfig:
		return "read the runner's log for the setting it named, and correct it on the pool; every runner in this pool will do the same until it is."
	case FaultRunnerExited:
		return "read the runner's last output on its page; a runner that stops mid-job has usually run out of memory or disk."
	}
	return ""
}

// FaultDomain names who a completed job's failure belongs to. Empty for a job
// that did not fail, which is different from not knowing.
//
// It is deliberately a method on the job rather than on the kind: a job with no
// fault is the fleet saying nothing went wrong on its side, and whether that
// makes the failure the workflow's depends on whether the job failed at all.
func (j *Job) FaultDomain() string {
	switch {
	case j.FleetFailed():
		return FaultDomainFleet
	case IsFailedConclusion(j.Conclusion):
		return FaultDomainWorkflow
	}
	return ""
}

// FleetFailed reports whether this fleet is the reason the job went wrong. It
// is the Go spelling of the SQL predicate the store's counts use, so the
// Overview's split and the Jobs page's filter cannot disagree.
//
// Either half alone is enough on purpose. The two are written together, but a
// row from before the kind existed carries only the message, and a fleet fault
// whose message went missing is still a fleet fault -- keying on one of them
// would quietly hand a job back to the workflow it did not belong to.
func (j *Job) FleetFailed() bool { return j.RunnerFault != "" || j.FaultKind != "" }

// WorkflowFailed reports whether the job failed on its own merits: GitHub
// concluded it failed and this fleet has nothing to confess.
func (j *Job) WorkflowFailed() bool {
	return !j.FleetFailed() && IsFailedConclusion(j.Conclusion)
}

package store

import (
	"context"
	"path/filepath"
	"testing"
	"time"
)

// The closed set has to stay closed at every edge it can be crossed at: an
// agent newer than this controller, a row written by a newer build, a query
// parameter somebody typed. Every one of those reaches Normalise, and the safe
// direction is "we could not narrow it" -- which sends somebody to look --
// rather than a category nothing can render or, worse, silence.
func TestAnUnknownFaultKindReadsAsUnclassifiedRatherThanAbsent(t *testing.T) {
	for _, tc := range []struct {
		in   FaultKind
		want FaultKind
	}{
		{"", ""},
		{FaultOutOfMemory, FaultOutOfMemory},
		{"quantum_decoherence", FaultRunnerExited},
		{"OUT_OF_MEMORY", FaultRunnerExited},
	} {
		if got := tc.in.Normalise(); got != tc.want {
			t.Errorf("FaultKind(%q).Normalise() = %q, want %q", tc.in, got, tc.want)
		}
	}
	for _, k := range FaultKinds() {
		if !k.Valid() {
			t.Errorf("%q is in the closed set and does not pass Valid", k)
		}
		// Every kind exists because something different is done about it, and
		// the remedy is where that is written down. A kind with no fix is a
		// category that earns nobody anything.
		if k.Fix() == "" {
			t.Errorf("%q has no fix; a category nothing acts on is prose", k)
		}
	}
}

// Whose a failure is has to be answered the same way by the Go predicate and by
// the SQL behind the counts, or the Overview's tile and the list it links to
// disagree about somebody's afternoon.
func TestTheFaultDomainAgreesWithTheFilters(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	now := time.Now().UTC().Truncate(time.Millisecond)

	mk := func(ghID int64, conclusion string, fault FaultKind, message string) *Job {
		t.Helper()
		j, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: ghID, Repo: "acme/widgets", State: JobCompleted,
			Conclusion: conclusion, QueuedAt: now, CompletedAt: &now,
		})
		if err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}
		if fault != "" {
			if _, _, err := s.SetJobRunnerFault(ctx, j.ID, message, fault); err != nil {
				t.Fatalf("SetJobRunnerFault: %v", err)
			}
			j, err = s.GetJob(ctx, j.ID)
			if err != nil {
				t.Fatalf("GetJob: %v", err)
			}
		}
		return j
	}

	ours := mk(1, "failure", FaultOutOfMemory, "runner zoomies-a stopped: out of memory")
	theirs := mk(2, "failure", "", "")
	fine := mk(3, "success", "", "")

	if ours.FaultDomain() != FaultDomainFleet || !ours.FleetFailed() || ours.WorkflowFailed() {
		t.Fatalf("a job the fleet broke reads as %+v", ours)
	}
	if theirs.FaultDomain() != FaultDomainWorkflow || theirs.FleetFailed() || !theirs.WorkflowFailed() {
		t.Fatalf("a test failure reads as %+v", theirs)
	}
	if fine.FaultDomain() != "" || fine.Failed() {
		t.Fatalf("a success reads as %+v", fine)
	}

	// The three filters, which are the SQL spelling of the three predicates.
	for _, tc := range []struct {
		name   string
		filter JobFilter
		want   []string
	}{
		{"failed", JobFilter{FailedOnly: true}, []string{ours.ID, theirs.ID}},
		{"ours", JobFilter{FaultedOnly: true}, []string{ours.ID}},
		{"theirs", JobFilter{WorkflowFailedOnly: true}, []string{theirs.ID}},
		{"by category", JobFilter{FaultKinds: []FaultKind{FaultOutOfMemory}}, []string{ours.ID}},
		// A category nothing matched is an empty list, never the whole table:
		// a filter that silently widened would read as a fleet in better shape
		// than it is.
		{"a category with nothing in it", JobFilter{FaultKinds: []FaultKind{FaultOutOfDisk}}, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, total, err := s.ListJobs(ctx, tc.filter, Page{Limit: 10})
			if err != nil {
				t.Fatalf("ListJobs: %v", err)
			}
			if total != len(tc.want) {
				t.Fatalf("matched %d jobs, want %d", total, len(tc.want))
			}
			ids := map[string]bool{}
			for _, j := range got {
				ids[j.ID] = true
			}
			for _, want := range tc.want {
				if !ids[want] {
					t.Fatalf("job %s is missing from the %s list", want, tc.name)
				}
			}
		})
	}

	// And the count behind the Overview's split, which has to be the same
	// judgement as the filters rather than a second one.
	st, err := s.StatsSince(ctx, now.Add(-time.Hour), false)
	if err != nil {
		t.Fatalf("StatsSince: %v", err)
	}
	if st.Failed != 2 || st.FleetFailed != 1 {
		t.Fatalf("failed = %d, of them ours = %d; want 2 and 1", st.Failed, st.FleetFailed)
	}
	counts, err := s.JobFaultCountsSince(ctx, now.Add(-time.Hour), false)
	if err != nil {
		t.Fatalf("JobFaultCountsSince: %v", err)
	}
	if counts[FaultOutOfMemory] != 1 || len(counts) != 1 {
		t.Fatalf("fault counts = %v, want one out_of_memory", counts)
	}
}

// Every job that already carried a fault is a fleet failure, and the migration
// has to say so. Leaving them empty would hand a year of the fleet's own
// failures back to the workflows that did nothing wrong, the moment the split
// started being counted -- and the number on the tile would be the first thing
// anybody saw of the feature.
func TestTheMigrationClaimsFaultsWrittenBeforeTheCategoryExisted(t *testing.T) {
	path := filepath.Join(t.TempDir(), "zoomies.db")
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	// Wind the category off a database that has the prose, which is what every
	// deployment upgrading to this build looks like.
	for _, stmt := range []string{
		`DELETE FROM schema_migrations WHERE name IN ('0034_job_fault_kind.sql', '0062_job_indexes_for_scans.sql')`,
		`DROP INDEX idx_jobs_fault_kind`,
		`DROP INDEX idx_jobs_faulted`,
		`ALTER TABLE jobs DROP COLUMN fault_kind`,
	} {
		if _, err := s.write.ExecContext(ctx, stmt); err != nil {
			t.Fatalf("winding the category off: %v: %s", err, stmt)
		}
	}
	for _, stmt := range []string{
		`INSERT INTO jobs (id, github_job_id, state, conclusion, queued_at, completed_at, runner_fault)
			VALUES ('job_lost', 8801, 'completed', 'failure', ?, ?, 'runner zoomies-old stopped while this job was running: exited with code 137')`,
		`INSERT INTO jobs (id, github_job_id, state, conclusion, queued_at, completed_at, runner_fault)
			VALUES ('job_theirs', 8802, 'completed', 'failure', ?, ?, '')`,
	} {
		if _, err := s.write.ExecContext(ctx, stmt, now.UnixMilli(), now.UnixMilli()); err != nil {
			t.Fatalf("writing an old row: %v", err)
		}
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	migrated, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open after the migration: %v", err)
	}
	t.Cleanup(func() { migrated.Close() })

	lost, err := migrated.GetJob(ctx, "job_lost")
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	// Unclassified, which is the truth: the message was never categorised, and
	// reading a category back out of the prose would be a guess.
	if lost.FaultKind != FaultRunnerExited {
		t.Fatalf("an existing fault got the category %q, want runner_exited", lost.FaultKind)
	}
	if lost.FaultDomain() != FaultDomainFleet {
		t.Fatalf("an existing fault reads as %q, want fleet", lost.FaultDomain())
	}
	theirs, err := migrated.GetJob(ctx, "job_theirs")
	if err != nil {
		t.Fatalf("GetJob: %v", err)
	}
	if theirs.FaultKind != "" || theirs.FaultDomain() != FaultDomainWorkflow {
		t.Fatalf("a test failure was claimed by the fleet: %q/%q", theirs.FaultKind, theirs.FaultDomain())
	}
}

// The counts behind the Overview's split and the runner half that reaches no
// job at all. Both windows fall back to a creation stamp on purpose: a failure
// with no completion is the one an operator most wants to see, and a window
// that dropped it would hide exactly the fleet that is in trouble.
func TestTheFaultCountsSeeFailuresThatNeverFinished(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	now := time.Now().UTC().Truncate(time.Millisecond)
	since := now.Add(-time.Hour)

	// A job whose runner died before GitHub closed it: no completion stamp.
	open, err := s.UpsertJob(ctx, &Job{
		GitHubJobID: 41, Repo: "acme/widgets", State: JobInProgress, QueuedAt: now,
	})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	if _, _, err := s.SetJobRunnerFault(ctx, open.ID, "runner zoomies-a stopped", FaultHostLost); err != nil {
		t.Fatalf("SetJobRunnerFault: %v", err)
	}
	counts, err := s.JobFaultCountsSince(ctx, since, false)
	if err != nil {
		t.Fatalf("JobFaultCountsSince: %v", err)
	}
	if counts[FaultHostLost] != 1 {
		t.Fatalf("fault counts = %v, want the unfinished job counted under host_lost", counts)
	}

	// And a window that ends before it was queued does not.
	if counts, err := s.JobFaultCountsSince(ctx, now.Add(time.Hour), false); err != nil {
		t.Fatalf("JobFaultCountsSince: %v", err)
	} else if len(counts) != 0 {
		t.Fatalf("counts from a window after the failure = %v, want none", counts)
	}
}

// The runner side is the half no job ever sees: a runner that fails before it
// registers leaves its job queued, so nothing is marked failed and every other
// count reads as a fleet that is merely busy.
func TestFailedRunnerCountsAndTheListBehindThem(t *testing.T) {
	ctx := context.Background()
	// The clock is the test's, so "newest first" is tested rather than a tie
	// SQLite happened to break the right way.
	now := time.Now().UTC().Truncate(time.Millisecond)
	clock := now
	s := newTestStoreAt(t, func() time.Time { return clock })
	since := now.Add(-time.Hour)

	_, pool, host := seedPool(t, s)
	mk := func(id string, state RunnerState, fault FaultKind, message string) {
		t.Helper()
		r := &Runner{ID: id, PoolID: pool.ID, HostID: host.ID, Name: id, State: RunnerProvisioning}
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		if state == RunnerFailed {
			clock = clock.Add(time.Second)
			if _, err := s.FailRunner(ctx, id, message, fault); err != nil {
				t.Fatalf("FailRunner: %v", err)
			}
		}
	}
	mk("run_image", RunnerFailed, FaultImage, "pulling ghcr.io/acme/runner:v9: manifest unknown")
	mk("run_backend", RunnerFailed, FaultBackend, "dial unix /var/run/docker.sock: no such file")
	mk("run_fine", RunnerProvisioning, "", "")

	counts, err := s.RunnerFaultCountsSince(ctx, since)
	if err != nil {
		t.Fatalf("RunnerFaultCountsSince: %v", err)
	}
	if counts[FaultImage] != 1 || counts[FaultBackend] != 1 || len(counts) != 2 {
		t.Fatalf("runner fault counts = %v, want one image and one backend", counts)
	}

	// Newest first, because the most recent failure is the one whose message
	// the problems drawer and the job's explanation both quote.
	failed, err := s.FailedRunnersForPoolSince(ctx, pool.ID, since, 10)
	if err != nil {
		t.Fatalf("FailedRunnersForPoolSince: %v", err)
	}
	if len(failed) != 2 {
		t.Fatalf("failed runners = %d, want the two that failed and not the one still starting", len(failed))
	}
	if failed[0].ID != "run_backend" || failed[0].FaultKind != FaultBackend {
		t.Fatalf("newest failed runner = %+v, want run_backend carrying its category", failed[0])
	}
	// The limit is a cap on the read, not a filter on the meaning.
	if one, err := s.FailedRunnersForPoolSince(ctx, pool.ID, since, 1); err != nil {
		t.Fatalf("FailedRunnersForPoolSince: %v", err)
	} else if len(one) != 1 || one[0].ID != "run_backend" {
		t.Fatalf("limited to one = %+v, want the newest", one)
	}
	if none, err := s.FailedRunnersForPoolSince(ctx, "pool_other", since, 10); err != nil {
		t.Fatalf("FailedRunnersForPoolSince: %v", err)
	} else if len(none) != 0 {
		t.Fatalf("another pool's failures leaked in: %+v", none)
	}
}

// The guard on a repeating timeline entry. A pool stuck in a start loop tries
// again every pass, and one entry per attempt on every waiting job turns a
// timeline into the log file it exists to save somebody reading.
func TestTheLastTimelineEntryIsWhatTheDedupeReads(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	j, err := s.UpsertJob(ctx, &Job{GitHubJobID: 51, State: JobQueued, QueuedAt: time.Now()})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	// A job with no history answers empty rather than failing: it is the
	// ordinary state of a job nothing has happened to yet.
	if kind, err := s.LastJobEventKind(ctx, j.ID); err != nil || kind != "" {
		t.Fatalf("LastJobEventKind on a fresh job = %q (%v), want empty", kind, err)
	}
	now := time.Now().UTC()
	for i, kind := range []JobEventKind{JobEventQueued, JobEventClaimed, JobEventRunnerStartFailed} {
		if err := s.AppendJobEvent(ctx, &JobEvent{
			JobID: j.ID, Kind: kind, Source: "controller", At: now.Add(time.Duration(i) * time.Second),
		}); err != nil {
			t.Fatalf("AppendJobEvent: %v", err)
		}
	}
	if kind, err := s.LastJobEventKind(ctx, j.ID); err != nil || kind != JobEventRunnerStartFailed {
		t.Fatalf("LastJobEventKind = %q (%v), want the newest entry", kind, err)
	}
	if kind, err := s.LastJobEventKind(ctx, "job_missing"); err != nil || kind != "" {
		t.Fatalf("LastJobEventKind for a job that does not exist = %q (%v), want empty and no error", kind, err)
	}
}

package store

import "context"

// PendingHostCleanup recovers removal intent from completed jobs and failed
// host removals. A keyset cursor prevents offline hosts starving later rows.
// Natural exits with an explicit log-retention window stay with the agent.
func (s *Store) PendingHostCleanup(ctx context.Context, afterID string, limit int) ([]*Runner, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT `+runnerCols+` FROM runners
		WHERE id > ? AND state IN ('removed', 'failed') AND host_removed_at IS NULL
		AND (host_cleanup_error != '' OR EXISTS
			(SELECT 1 FROM jobs WHERE jobs.runner_id=runners.id AND jobs.state='completed'))
		AND NOT EXISTS (SELECT 1 FROM jobs WHERE jobs.runner_id=runners.id AND jobs.state='in_progress')
		ORDER BY id LIMIT ?`, afterID, min(max(limit, 1), 200))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Runner
	for rows.Next() {
		r, err := scanRunner(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

package store

import (
	"context"
	"database/sql/driver"
	"fmt"
	"time"
)

// HostIncidents is what has recently gone wrong on a host's own machinery, as
// opposed to what the controller decided about it (the throttle) or what the
// host measured (the usage).
//
// Both halves used to exist only somewhere an operator could not see them.
// The runtime cooldown lived in the agent's memory and surfaced as one log
// line on the host; an image that would not pull reached the controller as a
// failed runner, which is cleaned up and gone within minutes, so a host whose
// egress blocks a registry showed only runners that never registered. Kept on
// the host row, each one survives a controller restart and is on the host
// card and in the problems drawer until the evidence says it is over.
//
// The two halves are written by different paths -- the heartbeat and a task
// result -- so each is set by its own statement on its own JSON path and one
// never writes the other back stale.
type HostIncidents struct {
	Runtime   *RuntimeIncident   `json:"runtime,omitempty"`
	ImagePull *ImagePullIncident `json:"image_pull,omitempty"`
}

// RuntimeIncident is the agent's container-runtime cooldown as the controller
// last heard it: the runtime failed, new starts are held, and one recovery
// attempt is due at RetryAt.
type RuntimeIncident struct {
	// Failures is how many runtime failures in a row, capped by the agent.
	Failures int `json:"failures"`
	// Kind is "unavailable" (the daemon could not be reached) or "timeout"
	// (it was reached and did not answer in time).
	Kind  string `json:"kind"`
	Error string `json:"error,omitempty"`
	// RetryAt is on the controller's clock: the agent sends how long is left
	// rather than a time, so a host whose clock is wrong cannot move it.
	RetryAt time.Time `json:"retry_at"`
	// Since is when the controller first heard of this episode, and
	// ObservedAt when it last heard anything new about it. Neither is
	// rewritten on a beat that says nothing new.
	Since      time.Time `json:"since"`
	ObservedAt time.Time `json:"observed_at"`
}

// ImagePullIncident is the last start or prewarm on a host that failed
// because its image could not be made ready, named by the registry it comes
// from and the pool that asked for it.
type ImagePullIncident struct {
	PoolID   string `json:"pool_id"`
	Pool     string `json:"pool"`
	Image    string `json:"image"`
	Registry string `json:"registry"`
	// Source is "start" or "prewarm": which of the agent's results said so.
	Source     string    `json:"source"`
	Error      string    `json:"error,omitempty"`
	Since      time.Time `json:"since"`
	ObservedAt time.Time `json:"observed_at"`
}

func (h HostIncidents) Value() (driver.Value, error) { return marshalJSON(h) }

func (h *HostIncidents) Scan(value any) error {
	*h = HostIncidents{}
	switch v := value.(type) {
	case string:
		return unmarshalJSON(v, h)
	case []byte:
		return unmarshalJSON(string(v), h)
	case nil:
		// A row from before the column, or one nothing has happened to.
		return nil
	default:
		return fmt.Errorf("host incidents: unexpected database value %T", value)
	}
}

// SetHostRuntimeIncident records or, with nil, clears a host's runtime
// cooldown without touching the image-pull half of the column.
func (s *Store) SetHostRuntimeIncident(ctx context.Context, id string, inc *RuntimeIncident) error {
	if inc == nil {
		return s.setHostIncident(ctx, id, "$.runtime", nil)
	}
	return s.setHostIncident(ctx, id, "$.runtime", inc)
}

// SetHostImagePullIncident records or, with nil, clears a host's image-pull
// incident without touching the runtime half of the column.
func (s *Store) SetHostImagePullIncident(ctx context.Context, id string, inc *ImagePullIncident) error {
	if inc == nil {
		return s.setHostIncident(ctx, id, "$.image_pull", nil)
	}
	return s.setHostIncident(ctx, id, "$.image_pull", inc)
}

// setHostIncident takes an untyped nil to clear, which is why both callers
// above unwrap their typed nil first.
func (s *Store) setHostIncident(ctx context.Context, id, path string, inc any) error {
	query := `UPDATE hosts SET incidents=json_remove(COALESCE(incidents,'{}'), ?) WHERE id=?`
	args := []any{path, id}
	if inc != nil {
		body, err := marshalJSON(inc)
		if err != nil {
			return err
		}
		query = `UPDATE hosts SET incidents=json_set(COALESCE(incidents,'{}'), ?, json(?)) WHERE id=?`
		args = []any{path, body, id}
	}
	res, err := s.exec(ctx, query, args...)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "host", id)
}

