	if got.Capacity != 0 || len(got.Labels) != 0 || !got.Cordoned || got.ReserveCPUs != 1 {
		t.Fatalf("explicit zero or empty labels were not applied independently: %+v", got)
	}
}

func TestHostFeaturesFollowWhatTheAgentReports(t *testing.T) {
	// A feature is the agent's claim about itself, re-read from every
	// heartbeat: an agent rolled back to a release that cannot move a live
	// quota must stop being recorded as one that can, or an elastic pool keeps
	// counting runners there as boostable when they are held at their share.
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()
	if host.Supports("elastic-cpu") {
		t.Fatal("a host that has claimed nothing supports elastic CPU")
	}
	host.Features = StringSlice{"elastic-cpu"}
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Supports("elastic-cpu") {
		t.Fatalf("features = %v, want the agent's claim kept", got.Features)
	}
	host.Features = nil
	if err := s.SetHostReported(ctx, host); err != nil {
		t.Fatal(err)
	}
	if got, err = s.GetHost(ctx, host.ID); err != nil {
		t.Fatal(err)
	} else if got.Supports("elastic-cpu") {
		t.Fatalf("features = %v, want an empty report to withdraw the claim", got.Features)
	}
}

package store

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"time"
)

// HostThrottle is how far the controller has stepped a host down after its
// measurements said it was overwhelmed, and why.
//
// It is a ladder rather than a switch. The pressure holds refuse every new
// start while CPU or memory is acutely short, and release the moment a sample
// says otherwise; a host that is overwhelmed on and off for an hour spends that
// hour bouncing in and out of them, taking a fresh runner each time it is let
// back in. The throttle is what outlasts a sample: each rung takes a quarter
// of the host's slots and, down to half, a quarter of every runner's CPU
// quota; it climbs while the pressure keeps coming back, and it comes down one
// rung at a time after a stretch of calm long enough to mean something.
//
// The controller owns every field. A heartbeat carries the measurements the
// decision is made from and never the decision, so a host cannot talk its way
// off its own rung.
type HostThrottle struct {
	// Level is the rung, 0 for none up to MaxThrottleLevel.
	Level int `json:"level,omitempty"`
	// Since is when this episode started: the first step up from zero.
	Since *time.Time `json:"since,omitempty"`
	// ChangedAt is the last step in either direction, which is what the next
	// step up is paced from.
	ChangedAt *time.Time `json:"changed_at,omitempty"`
	// CalmSince is the start of the calm streak the next step down waits on,
	// nil while the host is not calm.
	CalmSince *time.Time `json:"calm_since,omitempty"`
	// Reason is the sentence for the last step up: which measurement did it.
	Reason string `json:"reason,omitempty"`
}

// MaxThrottleLevel is the top rung. Three rungs leave a host a quarter of its
// slots; a fourth would take it to nothing, and a host taking nothing is a
// cordon, which is the operator's to apply and the operator's to see.
const MaxThrottleLevel = 3

// throttleStepFraction is what one rung takes of the slots, and of every
// runner's CPU quota down to MinCPUFactor.
const throttleStepFraction = 0.25

// Active reports whether the host is on any rung at all.
func (t HostThrottle) Active() bool { return t.Level > 0 }

// Factor is the share of a host's slots the current rung leaves: 1 on no
// rung, then 0.75, 0.5 and 0.25.
func (t HostThrottle) Factor() float64 {
	level := min(max(t.Level, 0), MaxThrottleLevel)
	return 1 - throttleStepFraction*float64(level)
}

// MinCPUFactor is the least share of its CPU quota a running job is ever left
// with. Half speed doubles a job's time, which the timeout-minutes most
// workflows set survives; a quarter turns "slow" into "timed out", and a
// throttle that made jobs fail would be doing the thing it exists to prevent.
// The top rung therefore takes slots and nothing else.
const MinCPUFactor = 0.5

// CPUFactor is the share of its CPU quota each runner on the host is left:
// the rung's factor, floored at MinCPUFactor.
func (t HostThrottle) CPUFactor() float64 {
	return max(MinCPUFactor, t.Factor())
}

func (t HostThrottle) Value() (driver.Value, error) { return marshalJSON(t) }

func (t *HostThrottle) Scan(value any) error {
	*t = HostThrottle{}
	switch v := value.(type) {
	case string:
		return unmarshalJSON(v, t)
	case []byte:
		return unmarshalJSON(string(v), t)
	case nil:
		return nil
	default:
		return fmt.Errorf("host throttle: unexpected database value %T", value)
	}
}

// ErrThrottleMoved is returned by SetHostThrottle when the host is no longer
// on the rung the caller decided from: another decider -- the heartbeat, the
// housekeeping pass, or an operator's clear -- wrote first.
var ErrThrottleMoved = errors.New("the host's throttle was decided elsewhere first")

// SetHostThrottle records the controller's decision for one host, provided
// the host is still on the rung the decision was made from.
//
// Its own statement, like the reserve and the usage: the path a heartbeat's
// facts take through UpdateHost and SetHostReported cannot reach this column,
// and an operator's PATCH cannot either. The throttle is decided from what a
// host measured, never written by what a host said.
//
// The write is conditional on fromLevel because two things decide a throttle
// -- every heartbeat, and the housekeeping tick -- and an operator can clear
// one between a read and the write that follows it. A step recorded twice
// would be two audit rows for one decision, and a stale rung written back
// over an operator's clear would be a lift silently undone; a caller that
// finds the rung moved leaves the decision to whoever moved it.
func (s *Store) SetHostThrottle(ctx context.Context, id string, throttle HostThrottle, fromLevel int) error {
	res, err := s.exec(ctx, `UPDATE hosts SET throttle=? WHERE id=? AND COALESCE(json_extract(throttle, '$.level'), 0)=?`,
		throttle, id, fromLevel)
	if err != nil {
		return wrapWrite(err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	var exists int
	if err := s.read.QueryRowContext(ctx, `SELECT 1 FROM hosts WHERE id=?`, id).Scan(&exists); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		return err
	}
	return ErrThrottleMoved
}

package store

import (
	"context"
	"errors"
	"testing"
	"time"
)

// A throttled host takes fewer runners, and the number it takes is what every
// slot count on it has to be measured against: the scheduler's free-slot rule
// and the Hosts page's "n of m slots" both read it, and a page that promised
// slots the pass then refused would be worse than a page saying nothing.
func TestAThrottleTakesAQuarterOfTheSlotsPerRungAndNeverTheLastOne(t *testing.T) {
	cases := []struct {
		capacity, level, want int
	}{
		{4, 0, 4}, {4, 1, 3}, {4, 2, 2}, {4, 3, 1},
		// A small host reaches its floor early: a throttle is not a cordon,
		// and a host with one slot left is still a host in the fleet.
		{2, 1, 1}, {2, 3, 1}, {1, 3, 1},
		{16, 1, 12}, {16, 2, 8}, {16, 3, 4},
		// A capacity of zero is the operator's "take nothing", and the
		// throttle has nothing to add to it.
		{0, 2, 0},
		// A level past the top rung is treated as the top rung.
		{8, 9, 2},
	}
	for _, tc := range cases {
		h := Host{Capacity: tc.capacity, Throttle: HostThrottle{Level: tc.level}}
		if got := h.EffectiveCapacity(); got != tc.want {
			t.Errorf("capacity %d at level %d: effective = %d, want %d", tc.capacity, tc.level, got, tc.want)
		}
	}
	h := Host{Capacity: 4, ActiveRunners: 2, Throttle: HostThrottle{Level: 2}}
	if h.Free() != 0 || h.Available(time.Now()) {
		t.Fatalf("a host at its throttled capacity still offered slots: free=%d", h.Free())
	}
	h.Throttle = HostThrottle{}
	if h.Free() != 2 {
		t.Fatalf("lifting the throttle did not give the slots back: free=%d", h.Free())
	}
}

// The throttle survives a restart and cannot be reached by the paths a host
// writes through: it is the controller's decision about the host, and a host
// that could rewrite it on a heartbeat could talk its way off its own rung.
func TestAThrottleIsStoredByItsOwnStatementAndSurvivesTheHostsOwnWrites(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	h := &Host{Name: "pressed", Capacity: 4, Backends: StringSlice{"docker"}, Labels: StringMap{}}
	if err := s.CreateHost(ctx, h); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	since := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	want := HostThrottle{Level: 2, Since: &since, ChangedAt: &since, Reason: "CPU has been at or above 95% for 30 s"}
	if err := s.SetHostThrottle(ctx, h.ID, want, 0); err != nil {
		t.Fatalf("SetHostThrottle: %v", err)
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.Throttle.Level != 2 || got.Throttle.Reason != want.Reason || got.Throttle.Since == nil || !got.Throttle.Since.Equal(since) {
		t.Fatalf("throttle = %+v after a round trip, want %+v", got.Throttle, want)
	}
	if got.EffectiveCapacity() != 2 {
		t.Fatalf("effective capacity = %d, want 2 from a level-2 throttle on 4 slots", got.EffectiveCapacity())
	}

	// The heartbeat's path and the operator's path both leave it alone.
	got.Capacity = 8
	if err := s.UpdateHost(ctx, got); err != nil {
		t.Fatalf("UpdateHost: %v", err)
	}
	if err := s.SetHostReported(ctx, got); err != nil {
		t.Fatalf("SetHostReported: %v", err)
	}
	if err := s.SetHostUsage(ctx, h.ID, HostUsage{}); err != nil {
		t.Fatalf("SetHostUsage: %v", err)
	}
	again, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if again.Throttle.Level != 2 {
		t.Fatalf("a host's own write moved its throttle: %+v", again.Throttle)
	}
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{}, 2); err != nil {
		t.Fatalf("SetHostThrottle: %v", err)
	}
	if again, _ = s.GetHost(ctx, h.ID); again.Throttle.Active() || again.EffectiveCapacity() != 8 {
		t.Fatalf("clearing the throttle did not give the host its capacity back: %+v", again)
	}
	if err := s.SetHostThrottle(ctx, "host_missing", HostThrottle{Level: 1}, 0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("a throttle written for a host that does not exist: %v", err)
	}
	// Two deciders, one decision. The write says which rung it was decided
	// from, and a rung that has moved since -- a heartbeat that got there
	// first, or an operator's clear -- refuses the stale one rather than
	// recording it twice or undoing the clear.
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{Level: 1}, 0); err != nil {
		t.Fatalf("SetHostThrottle from rung 0: %v", err)
	}
	if err := s.SetHostThrottle(ctx, h.ID, HostThrottle{Level: 1}, 0); !errors.Is(err, ErrThrottleMoved) {
		t.Fatalf("a decision from a rung the host has left was written: %v", err)
	}
	if got, _ := s.GetHost(ctx, h.ID); got.Throttle.Level != 1 {
		t.Fatalf("the refused write moved the rung: %+v", got.Throttle)
	}
}

// A host's row counts its live runners on every read, and now also how many
// of them nothing binds: a sustained CPU hold means overload only on a host
// carrying a runner that can take more than its share, so the count has to
// come from the rows rather than from memory, and it has to leave finished
// runners out exactly as the slot count does.
func TestAHostCountsTheLiveRunnersNoCPULimitBinds(t *testing.T) {
	s := newTestStore(t)
	_, p, h := seedPool(t, s)
	ctx := context.Background()
	limited := &Runner{PoolID: p.ID, HostID: h.ID, Name: "limited", AllocatedCPUs: 2, AllocationSource: AllocationFromHost}
	unlimited := &Runner{PoolID: p.ID, HostID: h.ID, Name: "unlimited"}
	finished := &Runner{PoolID: p.ID, HostID: h.ID, Name: "finished"}
	for _, r := range []*Runner{limited, unlimited, finished} {
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
	}
	if _, err := s.TransitionRunner(ctx, finished.ID, RunnerFailed, "gone"); err != nil {
		t.Fatalf("TransitionRunner: %v", err)
	}
	got, err := s.GetHost(ctx, h.ID)
	if err != nil {
		t.Fatalf("GetHost: %v", err)
	}
	if got.ActiveRunners != 2 || got.UnlimitedRunners != 1 {
		t.Fatalf("active = %d, unlimited = %d; want 2 live of which 1 has no CPU limit", got.ActiveRunners, got.UnlimitedRunners)
	}
}

// The throttle column is JSON, and it has to come back from every shape the
// driver hands over: a string, bytes, and the NULL a row written before the
// column existed would have carried had the migration not defaulted it.
func TestAThrottleScansFromEveryShapeTheDriverOffers(t *testing.T) {
	since := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	want := HostThrottle{Level: 2, Since: &since, Reason: "memory at the reserve"}
	v, err := want.Value()
	if err != nil {
		t.Fatalf("Value: %v", err)
	}
	raw, ok := v.(string)
	if !ok {
		t.Fatalf("Value() = %T, want the JSON as a string", v)
	}
	for name, in := range map[string]any{"string": raw, "bytes": []byte(raw)} {
		var got HostThrottle
		if err := got.Scan(in); err != nil {
			t.Fatalf("Scan(%s): %v", name, err)
		}
		if got.Level != 2 || got.Reason != want.Reason || got.Since == nil || !got.Since.Equal(since) {
			t.Fatalf("Scan(%s) = %+v, want %+v", name, got, want)
		}
	}
	var empty HostThrottle
	if err := empty.Scan(nil); err != nil || empty.Active() {
		t.Fatalf("Scan(nil) = %+v, %v; want an inactive throttle and no error", empty, err)
	}
	if err := empty.Scan(42); err == nil {
		t.Fatal("a number scanned as a throttle")
	}
}

package store

import (
	"context"
	"database/sql/driver"
	"fmt"
	"math"
	"time"
)

// HostUsage is a recent whole-host measurement, separate from reservations.
// Pointers distinguish an idle/full host from a host that could not measure.
// The controller owns the timestamps and the sustained-CPU hold.
type HostUsage struct {
	CPUPercent        *float64 `json:"cpu_percent,omitempty"`
	MemoryAvailableMB *int64   `json:"memory_available_mb,omitempty"`
	// LoadAverage1 is the kernel's one-minute load average for the whole
	// machine. CPU occupancy stops at 100%; this keeps counting the tasks
	// queued behind the cores, so it is what says how far past its size a
	// host has been pushed rather than merely that it is busy.
	LoadAverage1 *float64   `json:"load_average_1m,omitempty"`
	SampledAt    time.Time  `json:"sampled_at,omitempty"`
	CPUHighSince *time.Time `json:"cpu_high_since,omitempty"`
	CPUHeld      bool       `json:"cpu_held,omitempty"`
	// LentCPUPercent is the part of CPUPercent that runners were using out of
	// CPU elastic CPU lent them, as a share of the whole host. The controller
	// works it out from the same heartbeat's runner samples; whatever an agent
	// put here is replaced. A boost doing its job is load the plan chose, and
	// judging admission and the throttle on it would have a boost trip the
	// very hold that then withdraws it.
	LentCPUPercent float64 `json:"lent_cpu_percent,omitempty"`
}

// UnlentCPUPercent is the host's CPU less what runners were using of CPU lent
// to them: the load the plan did not account for. Nil where CPU was not
// measured.
func (u HostUsage) UnlentCPUPercent() *float64 {
	if u.CPUPercent == nil {
		return nil
	}
	v := max(*u.CPUPercent-max(u.LentCPUPercent, 0), 0)
	return &v
}

const HostUsageMaxAge = 90 * time.Second

// CPUHoldWindow is how long CPU has to sit at or above 95% before new starts
// are held. It is a constant rather than a literal because the throttle
// ladder is paced against it: a rung may not be climbed faster than the hold
// that feeds it can trip, and internal/controller pins the two together.
const CPUHoldWindow = 30 * time.Second

func (u HostUsage) Fresh(now time.Time) bool {
	return !u.SampledAt.IsZero() && !now.Before(u.SampledAt) && now.Sub(u.SampledAt) < HostUsageMaxAge
}

// ObserveHostUsage validates just the measurements an agent may supply. A
// forged timestamp cannot keep a reading fresh, or shorten a pressure hold.
// Sustained CPU pressure pauses admission after 30 seconds above 95%; a
// reading below 85% releases it. Busy runners are never changed by this state.
//
// lentPercent is the controller's own figure for the share of the host that
// runners were using out of lent CPU, and both thresholds are judged without
// it. The recorded CPUPercent stays the raw measurement.
func ObserveHostUsage(previous, measured HostUsage, lentPercent float64, memoryMB int64, now time.Time) HostUsage {
	u := HostUsage{SampledAt: now}
	if v := measured.CPUPercent; v != nil && !math.IsNaN(*v) && !math.IsInf(*v, 0) && *v >= 0 && *v <= 100 {
		raw := *v
		u.CPUPercent = &raw
		if !math.IsNaN(lentPercent) && lentPercent > 0 {
			u.LentCPUPercent = min(lentPercent, raw)
		}
		value := *u.UnlentCPUPercent()
		if previous.Fresh(now) && previous.CPUPercent != nil {
			u.CPUHeld = previous.CPUHeld && value >= 85
		}
		if value >= 95 {
			since := now
			if previous.Fresh(now) && previous.CPUHighSince != nil {
				since = *previous.CPUHighSince
			}
			u.CPUHighSince = &since
			u.CPUHeld = u.CPUHeld || now.Sub(since) >= CPUHoldWindow
		}
	}
	if v := measured.MemoryAvailableMB; v != nil && *v >= 0 && memoryMB > 0 && *v <= memoryMB {
		value := *v
		u.MemoryAvailableMB = &value
	}
	// A load average has no ceiling -- that is the point of it -- but it is
	// never negative, and a NaN or an infinity is an agent that read
	// something other than /proc/loadavg. A figure that is only a load
	// average, with no CPU and no memory, is still a measurement.
	if v := measured.LoadAverage1; v != nil && !math.IsNaN(*v) && !math.IsInf(*v, 0) && *v >= 0 {
		value := *v
		u.LoadAverage1 = &value
	}
	if u.CPUPercent == nil && u.MemoryAvailableMB == nil && u.LoadAverage1 == nil {
		return HostUsage{}
	}
	return u
}

func (u HostUsage) Value() (driver.Value, error) { return marshalJSON(u) }

func (u *HostUsage) Scan(value any) error {
	*u = HostUsage{}
	switch v := value.(type) {
	case string:
		return unmarshalJSON(v, u)
	case []byte:
		return unmarshalJSON(string(v), u)
	case nil:
		return nil
	default:
		return fmt.Errorf("host usage: unexpected database value %T", value)
	}
}

// SetHostUsage cannot write an operator's capacity, cordon or reserves.
func (s *Store) SetHostUsage(ctx context.Context, id string, usage HostUsage) error {
	res, err := s.exec(ctx, `UPDATE hosts SET usage=? WHERE id=?`, usage, id)
	if err != nil {
		return wrapWrite(err)
	}
	return affected(res, "host", id)
}

package store

import (
	"math"
	"testing"
	"time"
)

func TestCPUAdmissionRequiresSustainedPressureAndHasRecoveryHysteresis(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	observe := func(old HostUsage, cpu float64, seconds int) HostUsage {
		return ObserveHostUsage(old, HostUsage{CPUPercent: &cpu}, 0, 8192, now.Add(time.Duration(seconds)*time.Second))
	}
	u := observe(HostUsage{}, 98, 0)
	if u.CPUHeld {
		t.Fatal("one high sample stopped new work")
	}
	u = observe(u, 98, 15)
	if u.CPUHeld {
		t.Fatal("less than 30 seconds of pressure stopped new work")
	}
	u = observe(u, 98, 30)
	if !u.CPUHeld {
		t.Fatal("sustained saturation did not hold admission")
	}
	u = observe(u, 90, 60)
	if !u.CPUHeld {
		t.Fatal("a small CPU dip released the hold")
	}
	u = observe(u, 84, 90)
	if u.CPUHeld {
		t.Fatal("recovered CPU did not release the hold")
	}
	u = observe(u, 98, 120)
	if u.CPUHeld {
		t.Fatal("old pressure was reused after recovery")
	}
	u = observe(u, 98, 240)
	if u.CPUHeld {
		t.Fatal("a stale observation counted as sustained pressure")
	}
}

// A load average is the one figure with no upper bound, so the validation is
// about the lower one and about numbers that are not numbers: a negative,
// a NaN or an infinity is an agent reading the wrong file, and none of them
// may become a reading the throttle then acts on.
func TestLoadAverageIsKeptWhenSaneAndDroppedWhenNot(t *testing.T) {
	now := time.Now()
	for _, v := range []float64{0, 0.5, 17.25, 400} {
		load := v
		u := ObserveHostUsage(HostUsage{}, HostUsage{LoadAverage1: &load}, 0, 8192, now)
		if u.LoadAverage1 == nil || *u.LoadAverage1 != v || !u.Fresh(now) {
			t.Fatalf("a load average of %v was not kept: %+v", v, u)
		}
	}
	for _, v := range []float64{-1, math.NaN(), math.Inf(1), math.Inf(-1)} {
		load := v
		u := ObserveHostUsage(HostUsage{}, HostUsage{LoadAverage1: &load}, 0, 8192, now)
		if u.LoadAverage1 != nil || u.Fresh(now) {
			t.Fatalf("a load average of %v became a measurement: %+v", v, u)
		}
	}
}

func TestUsageIgnoresAgentTimestampsAndRejectsImpossibleValues(t *testing.T) {
	now := time.Now()
	zero, full := 0.0, int64(0)
	future := now.Add(time.Hour)
	u := ObserveHostUsage(HostUsage{}, HostUsage{CPUPercent: &zero, MemoryAvailableMB: &full,
		SampledAt: future, CPUHighSince: &future, CPUHeld: true}, 0, 8192, now)
	if u.CPUHeld || u.CPUHighSince != nil || !u.SampledAt.Equal(now) || u.CPUPercent == nil || u.MemoryAvailableMB == nil {
		t.Fatalf("agent control fields or measured zero were mishandled: %+v", u)
	}
	if u.Fresh(now.Add(HostUsageMaxAge)) || u.Fresh(now.Add(-time.Second)) {
		t.Fatal("stale/future sample is fresh")
	}
	for _, cpu := range []float64{-1, 101, math.NaN(), math.Inf(1)} {
		if got := ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 0, 8192, now); !got.SampledAt.IsZero() {
			t.Fatalf("invalid CPU accepted: %v", cpu)
		}
	}
	for _, mem := range []int64{-1, 8193} {
		if got := ObserveHostUsage(u, HostUsage{MemoryAvailableMB: &mem}, 0, 8192, now); got.MemoryAvailableMB != nil {
			t.Fatalf("invalid memory accepted: %d", mem)
		}
	}
}

func TestUsageRoundTripCannotUndoCordonCapacityOrReserves(t *testing.T) {
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	ctx := t.Context()
	if err := s.SetHostCordoned(ctx, host.ID, true); err != nil {
		t.Fatal(err)
	}
	capacity, reserve := 0, 1
	if err := s.PatchHost(ctx, host.ID, HostChanges{Capacity: &capacity, ReserveCPUs: &reserve}); err != nil {
		t.Fatal(err)
	}
	cpu, mem := 97.0, int64(2048)
	u := HostUsage{CPUPercent: &cpu, MemoryAvailableMB: &mem, SampledAt: s.Now(), CPUHeld: true}
	if err := s.SetHostUsage(ctx, host.ID, u); err != nil {
		t.Fatal(err)
	}
	h, err := s.GetHost(ctx, host.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !h.Cordoned || h.Capacity != 0 || h.ReserveCPUs != 1 || !h.Usage.CPUHeld || h.Usage.CPUPercent == nil || *h.Usage.CPUPercent != cpu {
		t.Fatalf("usage or operator state lost: %+v", h)
	}
}

// A host at full CPU because its runners are using the CPU they were lent is
// doing what the plan chose. Holding new starts for it would punish a boost
// for working; CPU nobody lent still holds them.
func TestLentCPUInUseDoesNotTripTheSustainedCPUHold(t *testing.T) {
	now := time.Now()
	cpu := 99.0
	u := HostUsage{}
	for s := 0; s <= 40; s += 10 {
		u = ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 30, 8192, now.Add(time.Duration(s)*time.Second))
	}
	if u.CPUHeld || u.CPUHighSince != nil {
		t.Fatalf("a host at 99%% with 30%% of it lent CPU in use was held: %+v", u)
	}
	if *u.CPUPercent != 99 || u.LentCPUPercent != 30 || *u.UnlentCPUPercent() != 69 {
		t.Fatalf("usage = %+v, want the raw 99%% recorded beside 30%% lent", u)
	}

	u = HostUsage{}
	for s := 0; s <= 40; s += 10 {
		u = ObserveHostUsage(u, HostUsage{CPUPercent: &cpu}, 2, 8192, now.Add(time.Duration(s)*time.Second))
	}
	if !u.CPUHeld {
		t.Fatalf("a host at 99%% with only 2%% of it lent was not held: %+v", u)
	}
}

package store

import "strings"

// Runner labels somebody else operates.
//
// A job whose labels all name GitHub's own runners, or a hosted-runner
// vendor's, runs where its labels say. This fleet has no pool for it and never
// will, so it is neither this fleet's work nor this fleet's fault, and every
// question the product answers about "our jobs" has to be able to leave it out
// -- the Jobs page's default view, the Overview's counts, the usage figures and
// the unmatched warning alike.
//
// The lists live here rather than in internal/migrate, which is where the
// migration wizard first needed them, because internal/store is what the SQL
// asking the same question is written against and internal/migrate imports it.
// migrate.IsHostedLabel and migrate.IsManagedLabel are now the wizard's names
// for these.

// hostedPrefixes are the runner labels GitHub itself provides, as of the runner
// images published for github.com.
//
// It is a prefix list, not an exact one: GitHub keeps adding sizes and versions
// ("ubuntu-22.04-arm", "windows-11-arm", the larger-runner names an
// organisation configures), and a list of only the exact names we shipped with
// would go quietly blind as they change.
var hostedPrefixes = []string{"ubuntu-", "windows-", "macos-"}

// vendorPrefixes are the label shapes of the hosted-runner vendors that sit in
// front of GitHub Actions -- Blacksmith, BuildJet, WarpBuild, Namespace, Depot
// and Ubicloud.
//
// They belong beside GitHub's own for the same reason: a repository on
// "blacksmith-4vcpu-ubuntu-2404" is renting somebody else's machines by the
// minute, and this fleet has no more to do with that job than with one on
// "ubuntu-latest". A prefix list again, and for the same reason -- every one of
// these vendors keeps adding sizes.
var vendorPrefixes = []string{
	"blacksmith",
	"buildjet-",
	"warp-",
	"namespace-profile-",
	"nscloud-",
	"depot-",
	"ubicloud",
}

// IsHostedLabel reports whether label is one of GitHub's own runner labels.
func IsHostedLabel(label string) bool {
	return hasAnyPrefix(NormalizeLabel(label), hostedPrefixes)
}

// IsManagedLabel reports whether label names a runner somebody else operates:
// GitHub's own, or one of the vendors above. The distinction that matters to an
// operator is not "GitHub or not" but "rented or ours".
func IsManagedLabel(label string) bool {
	l := NormalizeLabel(label)
	return hasAnyPrefix(l, hostedPrefixes) || hasAnyPrefix(l, vendorPrefixes)
}

func hasAnyPrefix(label string, prefixes []string) bool {
	if label == "" {
		return false
	}
	for _, p := range prefixes {
		if strings.HasPrefix(label, p) {
			return true
		}
	}
	return false
}

// HostedJob reports whether every label a job asked for names a runner somebody
// else operates. Such a job is theirs to run: it being unmatched here is what
// the workflow asked for rather than a job going nowhere.
//
// A job with no labels at all is not hosted. GitHub always sends the labels it
// resolved, so an empty set means a delivery we could not read rather than a
// job nobody has to run, and guessing "somebody else's" about it would hide it
// from the one page that could show the gap.
func HostedJob(labels []string) bool {
	if len(labels) == 0 {
		return false
	}
	for _, l := range labels {
		if !IsManagedLabel(l) {
			return false
		}
	}
	return true
}

// hostedJobSQL is HostedJob in SQL, over the JSON array the labels are stored
// as. The two spellings are built from the same prefix lists, because a page
// that hides a vendor's job while the warning above it still counts one is
// worse than either behaviour on its own.
//
// The caller names the jobs table as its own query spells it, because pools
// have labels too and a query that joins the two cannot say `labels` at all.
func hostedJobSQL(jobs string) string {
	tests := make([]string, 0, len(hostedPrefixes)+len(vendorPrefixes))
	for _, p := range append(append([]string{}, hostedPrefixes...), vendorPrefixes...) {
		// The prefixes are literal words and hyphens, but ESCAPE keeps that
		// from being load-bearing: a vendor prefix with an underscore in it
		// would otherwise match anything.
		tests = append(tests, `value NOT LIKE '`+likeEscape(p)+`%' ESCAPE '\'`)
	}
	return `(json_array_length(` + jobs + `.labels) > 0 AND NOT EXISTS (
		SELECT 1 FROM json_each(` + jobs + `.labels) WHERE ` + strings.Join(tests, " AND ") + `))`
}

package store

import "testing"

// The prefixes are what tells a runner this fleet could own from one it never
// will, and both halves of the product read them: the migration wizard offers
// to migrate the labels, and the Jobs page decides from them whether a job is
// this fleet's business at all.
func TestManagedLabelsAreTheOnesSomebodyElseOperates(t *testing.T) {
	for _, tc := range []struct {
		label   string
		hosted  bool
		managed bool
	}{
		{"ubuntu-latest", true, true},
		{"ubuntu-22.04-arm", true, true},
		{"windows-11-arm", true, true},
		// GitHub's own images are written both ways in the wild, and a label
		// is case-insensitive to GitHub, so it must be here too.
		{"macOS-14", true, true},
		{"blacksmith-4vcpu-ubuntu-2404", false, true},
		{"buildjet-8vcpu-ubuntu-2204", false, true},
		{"ubicloud-standard-2", false, true},
		// Ours, or an organisation's own invention. Neither is somebody
		// else's to run, and a job asking for one waits on this fleet.
		{"self-hosted", false, false},
		{"gpu", false, false},
		{"ubuntu", false, false},
		{"", false, false},
	} {
		if got := IsHostedLabel(tc.label); got != tc.hosted {
			t.Errorf("IsHostedLabel(%q) = %v, want %v", tc.label, got, tc.hosted)
		}
		if got := IsManagedLabel(tc.label); got != tc.managed {
			t.Errorf("IsManagedLabel(%q) = %v, want %v", tc.label, got, tc.managed)
		}
	}
}

// A job is somebody else's only when every label says so. One label this fleet
// could answer makes the job ours to run, or ours to explain.
func TestOneLabelThisFleetCouldAnswerMakesTheJobOurs(t *testing.T) {
	for _, tc := range []struct {
		name   string
		labels []string
		want   bool
	}{
		{"a vendor's", []string{"blacksmith-4vcpu-ubuntu-2404"}, true},
		{"GitHub's own", []string{"ubuntu-latest"}, true},
		{"mixed", []string{"ubuntu-latest", "gpu"}, false},
		{"ours", []string{"self-hosted", "linux", "x64"}, false},
		// A delivery we could not read the labels of, rather than a job
		// nobody has to run: guessing "somebody else's" would hide it.
		{"none at all", nil, false},
	} {
		if got := HostedJob(tc.labels); got != tc.want {
			t.Errorf("HostedJob(%v) [%s] = %v, want %v", tc.labels, tc.name, got, tc.want)
		}
	}
}

package store

import (
	"crypto/rand"
	"encoding/base32"
	"strings"
)

// ID prefixes. Every identifier the operator can see is prefixed so that a
// copied ID is self-describing when it turns up in a log line or a bug report.
const (
	PrefixInstallation = "ins"
	PrefixPool         = "pool"
	PrefixHost         = "host"
	PrefixRunner       = "run"
	PrefixJob          = "job"
	PrefixAudit        = "aud"
	PrefixUser         = "usr"
	PrefixSession      = "ses"
	PrefixToken        = "tok"
	PrefixJoin         = "join"
	PrefixScaling      = "scl"
	PrefixDelivery     = "whd"
	PrefixJobEvent     = "jev"
	PrefixController   = "ctl"
	PrefixProvider     = "prv"
	// PrefixBackupRemote names an offsite backup destination kept in the
	// database, so a row id in a log line says what it is without a lookup.
	PrefixBackupRemote = "bkr"
	PrefixMachine      = "mach"
	// PrefixMachineOp is minted per attempt rather than per machine: it is the
	// operation ID an operator quotes when a create is stuck, and two attempts
	// sharing one would make a log line ambiguous about which of them it came
	// from.
	PrefixMachineOp = "mop"
	// The OAuth rows behind /mcp: a client that may ask for a grant, a
	// request waiting at the consent screen, and a grant -- one person's MCP
	// connection -- that every code and token descends from.
	PrefixOAuthClient  = "oac"
	PrefixOAuthRequest = "oar"
	PrefixOAuthGrant   = "ocg"
	PrefixAIContext    = "aic"
)

var idEncoding = base32.NewEncoding("abcdefghijklmnopqrstuvwxyz234567").WithPadding(base32.NoPadding)

// NewID returns a random, URL-safe, double-click-selectable identifier such as
// "pool_k3f9qz2mx7ab". Randomness (not a counter) keeps IDs unguessable, which
// matters because some of them appear in URLs handed to a browser.
func NewID(prefix string) string {
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic("zoomies: entropy source unavailable: " + err.Error())
	}
	return prefix + "_" + idEncoding.EncodeToString(b[:])
}

// generatedIDLength is how many characters NewID's random part always has:
// eight bytes of base32 with no padding. It is a property of NewID, so a
// change to the byte count above has to change this too, and a test holds the
// two together.
const generatedIDLength = 13

// LooksGenerated reports whether id has the exact shape NewID produces: a
// prefix, an underscore, and thirteen characters of the base32 alphabet.
//
// It exists for the one caller that needs to tell a fixture apart from a real
// row. The demo seed names its rows with readable identifiers such as
// "pool_demolinux", and a check that only looked for the "demo" prefix would
// also match a real identifier that happened to start that way -- which, at
// four letters over a 32-character alphabet, one row in a million does. A
// fixture is never this shape, so the shape is what settles it.
func LooksGenerated(id string) bool {
	_, rest, ok := strings.Cut(id, "_")
	if !ok || len(rest) != generatedIDLength {
		return false
	}
	for i := 0; i < len(rest); i++ {
		c := rest[i]
		if (c < 'a' || c > 'z') && (c < '2' || c > '7') {
			return false
		}
	}
	return true
}

// HasPrefix reports whether id looks like an ID minted for the given kind.
func HasPrefix(id, prefix string) bool {
	return strings.HasPrefix(id, prefix+"_")
}

// NewSecret returns n bytes of base32 entropy, used for tokens that are shown
// to a human once and stored only as a hash.
func NewSecret(n int) string {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		panic("zoomies: entropy source unavailable: " + err.Error())
	}
	return idEncoding.EncodeToString(b)
}

package store

import (
	"strings"
	"testing"
)

// LooksGenerated is what tells a seeded fixture from a real row, so it has to
// agree with NewID exactly: a generated identifier always passes, and the
// readable identifiers the demo seed writes never do.
func TestLooksGeneratedAgreesWithNewID(t *testing.T) {
	for range 200 {
		id := NewID(PrefixPool)
		if !LooksGenerated(id) {
			t.Fatalf("NewID produced %q, which LooksGenerated does not recognise", id)
		}
	}
	for _, id := range []string{
		"pool_demolinux", "ins_demoacme", "host_demoa", "run_demo00", "job_demo051",
		"usr_demo_alice", "pool_", "nounderscore", "",
		// Right length, wrong alphabet: base32 here has no 0, 1, 8 or 9 and no
		// upper case.
		"pool_abcdefghijk01", "pool_ABCDEFGHIJKLM",
		// Right alphabet, wrong length.
		"pool_abcdefghijkl", "pool_abcdefghijklmn",
	} {
		if LooksGenerated(id) {
			t.Errorf("LooksGenerated(%q) = true, want false", id)
		}
	}
}

// The length constant is a property of NewID's byte count, and a change to
// one without the other would silently make every real identifier look like a
// fixture, or every fixture look real.
func TestGeneratedIDLengthMatchesNewID(t *testing.T) {
	_, rest, _ := strings.Cut(NewID(PrefixJob), "_")
	if len(rest) != generatedIDLength {
		t.Fatalf("NewID's random part is %d characters, generatedIDLength says %d", len(rest), generatedIDLength)
	}
}

package store

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// One installation's rows, as a set
// ---------------------------------------------------------------------------
//
// Deleting an installation removes what a foreign key reaches -- its pools and
// their runners -- and leaves the history behind on purpose, because a job
// record outliving the pool it ran in is what the Jobs page and the usage
// report are for. Two things want the history as well: moving an App to a new
// machine, which should take its past with it, and removing a team's history
// cleanly, which should leave nothing that names it. Both are the same set,
// defined once here, so an export and a purge cannot disagree about what
// "everything about this installation" means.

// ArchiveTable is one table's share of an installation: its column names and
// its rows, in rowid order so the same rows always render the same bytes.
type ArchiveTable struct {
	Table   string           `json:"table"`
	Columns []string         `json:"columns"`
	Rows    [][]ArchiveValue `json:"rows"`
}

// ArchiveValue is one SQLite value carried through JSON. Integers, reals, text
// and NULL are themselves; a blob is {"base64": ...}, because a bare string
// would come back as text and SQLite would keep it as text.
type ArchiveValue struct{ V any }

// MarshalJSON renders the value.
func (v ArchiveValue) MarshalJSON() ([]byte, error) {
	if b, ok := v.V.([]byte); ok {
		return json.Marshal(map[string]string{"base64": base64.StdEncoding.EncodeToString(b)})
	}
	return json.Marshal(v.V)
}

// UnmarshalJSON reads a value back, keeping an integer an integer: decoding
// every number as a float would round a millisecond timestamp past 2^53 and
// turn a count into 3.0.
func (v *ArchiveValue) UnmarshalJSON(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var x any
	if err := dec.Decode(&x); err != nil {
		return err
	}
	switch t := x.(type) {
	case json.Number:
		if i, err := strconv.ParseInt(t.String(), 10, 64); err == nil {
			v.V = i
			return nil
		}
		f, err := t.Float64()
		if err != nil {
			return err
		}
		v.V = f
	case map[string]any:
		s, ok := t["base64"].(string)
		if !ok || len(t) != 1 {
			return errors.New("an archive value is an object that is not a blob")
		}
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			return err
		}
		v.V = b
	case string, nil, bool:
		v.V = t
	default:
		return fmt.Errorf("an archive value is a %T, which no column holds", t)
	}
	return nil
}

// installationTable is one table in the set and how its rows are found. where
// is a predicate over the table; args builds its arguments from the scope.
type installationTable struct {
	name  string
	where string
	args  func(sc *installationScope) []any
	// importable is false for a table whose rows name something that belongs
	// to the machine rather than the fleet -- a runner row points at a host
	// that exists on the instance it came from and nowhere else. Its history
	// travels as the runner's session, which has no such key.
	importable bool
}

const inList = ` IN (SELECT value FROM json_each(?))`

// installationTables is the set, in the order an import inserts it: a row
// always comes after the row its foreign key names. A purge deletes it in
// reverse.
var installationTables = []installationTable{
	{"installations", `id = ?`, func(sc *installationScope) []any { return []any{sc.id} }, true},
	{"pools", `id` + inList, func(sc *installationScope) []any { return []any{sc.pools} }, true},
	{"runners", `id` + inList, func(sc *installationScope) []any { return []any{sc.runners} }, false},
	{"pool_prewarms", `pool_id` + inList, func(sc *installationScope) []any { return []any{sc.pools} }, false},
	{"jobs", `id` + inList, func(sc *installationScope) []any { return []any{sc.jobs} }, true},
	{"job_events", `job_id` + inList, func(sc *installationScope) []any { return []any{sc.jobs} }, true},
	{"webhook_deliveries", `installation_id = ?`, func(sc *installationScope) []any { return []any{sc.id} }, true},
	{"scaling_events", `pool_id` + inList, func(sc *installationScope) []any { return []any{sc.pools} }, true},
	{"runner_sessions", `runner_id` + inList, func(sc *installationScope) []any { return []any{sc.sessions} }, true},
	{"usage_daily", `installation_id = ? OR (installation_id = '' AND pool_id` + inList + `)`,
		func(sc *installationScope) []any { return []any{sc.id, sc.pools} }, true},
	{"usage_capacity_samples", `pool_id` + inList, func(sc *installationScope) []any { return []any{sc.pools} }, true},
	{"capacity_demand_deliveries", `pool_id` + inList, func(sc *installationScope) []any { return []any{sc.pools} }, true},
	{"audit_events", `target_id` + inList, func(sc *installationScope) []any { return []any{sc.named} }, true},
}

// installationScope is the IDs the set is drawn from, each list a JSON array
// so one parameter carries it into json_each.
type installationScope struct {
	id                                    string
	pools, runners, jobs, sessions, named string
}

type querier interface {
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
}

// scopeInstallation works out the IDs that belong to one installation.
//
// Its pools are the ones it has now and the ones its history names -- a pool
// deleted last month still has scaling events and sessions -- less any pool
// that belongs to another installation now, so a pool moved between
// installations is never taken from the one that holds it.
//
// A job belongs to it when the job says so, or says nothing and ran in one of
// its pools; a job another installation claims is never counted, whichever
// pool it names.
func scopeInstallation(ctx context.Context, q querier, id string) (*installationScope, error) {
	sc := &installationScope{id: id}
	pools, err := collect(ctx, q, `SELECT id FROM pools WHERE installation_id = ?1
		UNION SELECT pool_id FROM runner_sessions WHERE installation_id = ?1
		UNION SELECT pool_id FROM jobs WHERE installation_id = ?1 AND pool_id <> ''
		EXCEPT SELECT id FROM pools WHERE installation_id <> ?1`, id)
	if err != nil {
		return nil, err
	}
	sc.pools = jsonList(pools)
	runners, err := collect(ctx, q, `SELECT id FROM runners WHERE pool_id`+inList, sc.pools)
	if err != nil {
		return nil, err
	}
	sc.runners = jsonList(runners)
	jobs, err := collect(ctx, q, `SELECT id FROM jobs WHERE installation_id = ? OR (installation_id = '' AND pool_id`+inList+`)`, id, sc.pools)
	if err != nil {
		return nil, err
	}
	sc.jobs = jsonList(jobs)
	sessions, err := collect(ctx, q, `SELECT runner_id FROM runner_sessions WHERE installation_id = ? OR (installation_id = '' AND pool_id`+inList+`)`, id, sc.pools)
	if err != nil {
		return nil, err
	}
	sc.sessions = jsonList(sessions)
	// IDs are prefixed and unique across kinds, so an audit row names one of
	// these exactly when its target_id is one of them, whatever its kind says.
	named := append(append(append(append([]string{id}, pools...), runners...), jobs...), sessions...)
	sc.named = jsonList(named)
	return sc, nil
}

func collect(ctx context.Context, q querier, query string, args ...any) ([]string, error) {
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, rows.Err()
}

func jsonList(ids []string) string {
	if ids == nil {
		ids = []string{}
	}
	b, _ := json.Marshal(ids)
	return string(b)
}

// ExportInstallation reads every row that belongs to one installation, in one
// read transaction so the tables agree with each other. The installation's
// secret columns are returned as stored -- sealed under this instance's key --
// and it is the caller's job to decide what, if anything, leaves with them.
func (s *Store) ExportInstallation(ctx context.Context, id string) ([]ArchiveTable, error) {
	tx, err := s.read.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()
	var exists int
	if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM installations WHERE id = ?`, id).Scan(&exists); err != nil {
		return nil, err
	}
	if exists == 0 {
		return nil, fmt.Errorf("installation %s: %w", id, ErrNotFound)
	}
	sc, err := scopeInstallation(ctx, tx, id)
	if err != nil {
		return nil, err
	}
	out := make([]ArchiveTable, 0, len(installationTables))
	for _, t := range installationTables {
		at, err := dumpTable(ctx, tx, t, sc)
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", t.name, err)
		}
		out = append(out, at)
	}
	return out, nil
}

func dumpTable(ctx context.Context, q querier, t installationTable, sc *installationScope) (ArchiveTable, error) {
	rows, err := q.QueryContext(ctx, `SELECT * FROM `+t.name+` WHERE `+t.where+` ORDER BY rowid`, t.args(sc)...)
	if err != nil {
		return ArchiveTable{}, err
	}
	defer rows.Close()
	cols, err := rows.Columns()
	if err != nil {
		return ArchiveTable{}, err
	}
	at := ArchiveTable{Table: t.name, Columns: cols, Rows: [][]ArchiveValue{}}
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return ArchiveTable{}, err
		}
		row := make([]ArchiveValue, len(cols))
		for i, v := range vals {
			row[i] = ArchiveValue{V: v}
		}
		at.Rows = append(at.Rows, row)
	}
	return at, rows.Err()
}

// PurgeInstallation deletes every row ExportInstallation would have written,
// in one transaction, and returns the IDs of the runner rows that went so the
// caller can announce them. Rows that belong to any other installation are
// out of scope by construction: nothing is deleted except by the IDs the
// scope names.
func (s *Store) PurgeInstallation(ctx context.Context, id string) ([]string, error) {
	var runners []string
	err := s.tx(ctx, func(tx *sql.Tx) error {
		var exists int
		if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM installations WHERE id = ?`, id).Scan(&exists); err != nil {
			return err
		}
		if exists == 0 {
			return fmt.Errorf("installation %s: %w", id, ErrNotFound)
		}
		sc, err := scopeInstallation(ctx, tx, id)
		if err != nil {
			return err
		}
		if err := json.Unmarshal([]byte(sc.runners), &runners); err != nil {
			return err
		}
		for i := len(installationTables) - 1; i >= 0; i-- {
			t := installationTables[i]
			if _, err := tx.ExecContext(ctx, `DELETE FROM `+t.name+` WHERE `+t.where, t.args(sc)...); err != nil {
				return fmt.Errorf("purging %s: %w", t.name, err)
			}
		}
		return nil
	})
	return runners, err
}

// ImportedInstallation says what an import wrote and what it left out.
type ImportedInstallation struct {
	InstallationID string         `json:"installation_id"`
	Rows           map[string]int `json:"rows"`
	Skipped        map[string]int `json:"skipped"`
}

// ErrArchiveShape is an archive this build cannot read: a table it does not
// hold, a column it has never had, or rows for more than one installation.
var ErrArchiveShape = errors.New("the archive does not fit this instance's schema")

// ImportInstallation writes an exported installation into this database, in
// one transaction: all of it or none. Every row keeps its ID, so the history
// an audit row or a session names is still the history it names.
//
// The installation's secret columns must already be sealed under this
// instance's key; the store has no business with a passphrase. An
// installation, job or other row whose ID or unique key is already here is
// ErrConflict, because silently keeping one of two would decide for the
// operator which history is true.
func (s *Store) ImportInstallation(ctx context.Context, tables []ArchiveTable) (*ImportedInstallation, error) {
	byName := map[string]ArchiveTable{}
	for _, t := range tables {
		if _, dup := byName[t.Table]; dup {
			return nil, fmt.Errorf("%w: %s appears twice", ErrArchiveShape, t.Table)
		}
		byName[t.Table] = t
	}
	known := map[string]bool{}
	for _, t := range installationTables {
		known[t.name] = true
	}
	for name := range byName {
		if !known[name] {
			return nil, fmt.Errorf("%w: it has a table called %q, which is not part of an installation", ErrArchiveShape, name)
		}
	}
	if inst := byName["installations"]; len(inst.Rows) != 1 {
		return nil, fmt.Errorf("%w: it must hold exactly one installation, and holds %d", ErrArchiveShape, len(inst.Rows))
	}
	out := &ImportedInstallation{Rows: map[string]int{}, Skipped: map[string]int{}}
	err := s.tx(ctx, func(tx *sql.Tx) error {
		for _, spec := range installationTables {
			t, ok := byName[spec.name]
			if !ok || len(t.Rows) == 0 {
				continue
			}
			if !spec.importable {
				out.Skipped[spec.name] = len(t.Rows)
				continue
			}
			have, err := tableColumns(ctx, tx, spec.name)
			if err != nil {
				return err
			}
			// The statement is built from the schema's own spelling of each
			// column, never the archive's: the archive is a file anyone can
			// hand the import, and a name that reaches the SQL only because it
			// matched is one careless edit away from injection.
			cols := make([]string, len(t.Columns))
			seen := map[string]bool{}
			for i, c := range t.Columns {
				name, ok := have[c]
				if !ok {
					return fmt.Errorf("%w: %s.%s is not a column here; the archive came from a newer Zoomies, so upgrade this instance first",
						ErrArchiveShape, spec.name, c)
				}
				if seen[name] {
					return fmt.Errorf("%w: %s names the column %s twice", ErrArchiveShape, spec.name, name)
				}
				seen[name] = true
				cols[i] = name
			}
			stmt := `INSERT INTO ` + spec.name + ` (` + strings.Join(cols, ", ") + `) VALUES (` +
				strings.TrimSuffix(strings.Repeat("?, ", len(t.Columns)), ", ") + `)`
			for _, row := range t.Rows {
				if len(row) != len(t.Columns) {
					return fmt.Errorf("%w: a row in %s has %d values for %d columns", ErrArchiveShape, spec.name, len(row), len(t.Columns))
				}
				args := make([]any, len(row))
				for i, v := range row {
					args[i] = v.V
					if spec.name == "installations" && t.Columns[i] == "id" {
						out.InstallationID, _ = v.V.(string)
					}
				}
				if _, err := tx.ExecContext(ctx, stmt, args...); err != nil {
					if isUnique(err) {
						return fmt.Errorf("%s already holds a row this archive has (%v): %w", spec.name, err, ErrConflict)
					}
					return fmt.Errorf("writing %s: %w", spec.name, err)
				}
			}
			out.Rows[spec.name] = len(t.Rows)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// tableColumns maps each of a table's columns to its name as the schema
// spells it. The import looks an archive's column up here and writes the
// value it finds, so only the schema's own strings ever reach SQL.
func tableColumns(ctx context.Context, tx *sql.Tx, table string) (map[string]string, error) {
	rows, err := tx.QueryContext(ctx, `SELECT name FROM pragma_table_info(?)`, table)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]string{}
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			return nil, err
		}
		out[n] = n
	}
	return out, rows.Err()
}

package store

import (
	"context"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
	"time"
)

// installationHistory is one installation with a little of everything the
// set covers: a pool, a runner that has gone (and so has a session), one still
// here, a job with an event, a delivery, a scaling event, a capacity sample,
// an audit row naming each kind, and a rolled-up usage day.
type installationHistory struct {
	inst   *Installation
	pool   *Pool
	gone   *Runner
	live   *Runner
	job    *Job
	target string
}

func seedInstallationHistory(t *testing.T, s *Store, now *time.Time, host *Host, target string, jobID int64) installationHistory {
	t.Helper()
	ctx := context.Background()
	inst := &Installation{AppID: 1, InstallationID: jobID, Target: target, TargetType: TargetOrg,
		PrivateKeyEnc: []byte("sealed-" + target), WebhookSecretEnc: []byte("secret-" + target)}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}
	pool := &Pool{Name: target + "-linux", InstallationID: inst.ID, Labels: StringSlice{target},
		Backend: BackendDocker, MaxRunners: 4, Ephemeral: true, DockerMode: DockerNone, Enabled: true}
	if err := s.CreatePool(ctx, pool); err != nil {
		t.Fatalf("CreatePool: %v", err)
	}
	pricedPool(t, s, pool, 0.5)
	start := time.Date(2026, 5, 9, 9, 0, 0, 0, time.UTC)
	gone := confirmed(t, s, now, pool, host, target+"-gone", start, start.Add(90*time.Minute))
	*now = start.Add(26 * time.Hour)
	live := &Runner{PoolID: pool.ID, HostID: host.ID, Name: target + "-live"}
	if err := s.CreateRunner(ctx, live); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	job, err := s.UpsertJob(ctx, &Job{GitHubJobID: jobID, Repo: target + "/app", Workflow: "build",
		State: JobQueued, InstallationID: inst.ID, PoolID: pool.ID, QueuedAt: *now})
	if err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
	if err := s.AppendJobEvent(ctx, &JobEvent{JobID: job.ID, Kind: "queued", Source: "webhook", At: *now}); err != nil {
		t.Fatalf("AppendJobEvent: %v", err)
	}
	if err := s.RecordDelivery(ctx, &WebhookDelivery{DeliveryID: "d-" + target, Event: "workflow_job",
		Status: "accepted", InstallationID: inst.ID, ReceivedAt: *now}); err != nil {
		t.Fatalf("RecordDelivery: %v", err)
	}
	if err := s.AppendScalingEvent(ctx, &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 0, To: 1,
		Reason: "one queued", CreatedAt: *now}); err != nil {
		t.Fatalf("AppendScalingEvent: %v", err)
	}
	if err := s.RecordUsageCapacity(ctx, pool.ID, *now, true); err != nil {
		t.Fatalf("RecordUsageCapacity: %v", err)
	}
	for _, target := range [][2]string{{"installation", inst.ID}, {"pool", pool.ID}, {"runner", gone.ID}, {"job", job.ID}} {
		if err := s.AppendAudit(ctx, &AuditEvent{Action: target[0] + ".update", TargetKind: target[0],
			TargetID: target[1], CreatedAt: *now}); err != nil {
			t.Fatalf("AppendAudit: %v", err)
		}
	}
	return installationHistory{inst: inst, pool: pool, gone: gone, live: live, job: job, target: target}
}

func exportRows(t *testing.T, s *Store, id string) []byte {
	t.Helper()
	tables, err := s.ExportInstallation(context.Background(), id)
	if err != nil {
		t.Fatalf("ExportInstallation(%s): %v", id, err)
	}
	b, err := json.Marshal(tables)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func usageFigures(t *testing.T, s *Store, id string) []UsageRow {
	t.Helper()
	rows, err := s.Usage(context.Background(), time.Date(2026, 5, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC), UsageByInstallation)
	if err != nil {
		t.Fatalf("Usage: %v", err)
	}
	var out []UsageRow
	for _, r := range rows {
		if r.Key == id {
			out = append(out, r)
		}
	}
	return out
}

func tableRows(t *testing.T, tables []ArchiveTable) map[string]int {
	t.Helper()
	out := map[string]int{}
	for _, tb := range tables {
		out[tb.Table] = len(tb.Rows)
	}
	return out
}

func twoInstallations(t *testing.T) (*Store, installationHistory, installationHistory) {
	t.Helper()
	now := time.Date(2026, 5, 9, 8, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	host := &Host{Name: "vm-1", Capacity: 8, Embedded: true, Backends: StringSlice{"docker"}}
	if err := s.CreateHost(context.Background(), host); err != nil {
		t.Fatalf("CreateHost: %v", err)
	}
	a := seedInstallationHistory(t, s, &now, host, "acme", 101)
	b := seedInstallationHistory(t, s, &now, host, "globex", 202)
	now = time.Date(2026, 5, 12, 0, 0, 0, 0, time.UTC)
	if _, err := s.RollUpUsage(context.Background(), now); err != nil {
		t.Fatalf("RollUpUsage: %v", err)
	}
	return s, a, b
}

// The export is everything about one installation and nothing about another:
// every table in the set has this installation's rows in it, and none of the
// neighbour's.
func TestAnInstallationsExportHoldsItsWholeHistoryAndNoOtherInstallations(t *testing.T) {
	s, a, b := twoInstallations(t)
	tables, err := s.ExportInstallation(context.Background(), a.inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]int{
		"installations": 1, "pools": 1, "runners": 2, "pool_prewarms": 0, "jobs": 1, "job_events": 1,
		"webhook_deliveries": 1, "scaling_events": 1, "runner_sessions": 1, "usage_daily": 1,
		"usage_capacity_samples": 1, "capacity_demand_deliveries": 0, "audit_events": 4,
	}
	if got := tableRows(t, tables); !reflect.DeepEqual(got, want) {
		t.Errorf("rows per table = %v, want %v", got, want)
	}
	raw, _ := json.Marshal(tables)
	for _, other := range []string{b.inst.ID, b.pool.ID, b.gone.ID, b.live.ID, b.job.ID, b.target} {
		if strings.Contains(string(raw), other) {
			t.Errorf("the export of %s names %s, which belongs to the other installation", a.target, other)
		}
	}
}

// The acceptance for ZF-210b: exporting and purging one installation leaves
// the other's rows, and the figures computed from them, exactly as they were.
func TestPurgingOneInstallationLeavesTheOthersRowsAndFiguresByteIdentical(t *testing.T) {
	s, a, b := twoInstallations(t)
	ctx := context.Background()
	beforeRows, beforeFigures := exportRows(t, s, b.inst.ID), usageFigures(t, s, b.inst.ID)
	if len(beforeFigures) == 0 {
		t.Fatal("the other installation has no usage figures, so the comparison would prove nothing")
	}

	_ = exportRows(t, s, a.inst.ID)
	runners, err := s.PurgeInstallation(ctx, a.inst.ID)
	if err != nil {
		t.Fatalf("PurgeInstallation: %v", err)
	}
	if len(runners) != 2 {
		t.Errorf("the purge reported %d runners gone, want 2", len(runners))
	}

	if after := exportRows(t, s, b.inst.ID); string(after) != string(beforeRows) {
		t.Errorf("the other installation's rows changed:\nbefore %s\nafter  %s", beforeRows, after)
	}
	if after := usageFigures(t, s, b.inst.ID); !reflect.DeepEqual(after, beforeFigures) {
		t.Errorf("the other installation's figures changed:\nbefore %+v\nafter  %+v", beforeFigures, after)
	}
	if _, err := s.ExportInstallation(ctx, a.inst.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("exporting the purged installation gave %v, want ErrNotFound", err)
	}
	// Nothing anywhere still names what went: that is the difference between
	// a purge and the ordinary delete, which leaves history behind.
	for _, id := range []string{a.inst.ID, a.pool.ID, a.gone.ID, a.live.ID, a.job.ID} {
		for _, q := range []string{
			`SELECT COUNT(*) FROM audit_events WHERE target_id = ?`,
			`SELECT COUNT(*) FROM jobs WHERE id = ?1 OR pool_id = ?1 OR installation_id = ?1`,
			`SELECT COUNT(*) FROM job_events WHERE job_id = ?`,
			`SELECT COUNT(*) FROM runner_sessions WHERE runner_id = ?1 OR pool_id = ?1 OR installation_id = ?1`,
			`SELECT COUNT(*) FROM usage_daily WHERE pool_id = ?1 OR installation_id = ?1`,
			`SELECT COUNT(*) FROM scaling_events WHERE pool_id = ?`,
			`SELECT COUNT(*) FROM usage_capacity_samples WHERE pool_id = ?`,
			`SELECT COUNT(*) FROM webhook_deliveries WHERE installation_id = ?`,
		} {
			var n int
			if err := s.read.QueryRowContext(ctx, q, id).Scan(&n); err != nil {
				t.Fatalf("%s: %v", q, err)
			}
			if n != 0 {
				t.Errorf("%d rows still name %s after the purge: %s", n, id, q)
			}
		}
	}
}

// A job another installation claims stays with it even when it names a pool
// of the one being purged: the job's own installation is the stronger claim.
func TestAPurgeLeavesAJobAnotherInstallationClaims(t *testing.T) {
	s, a, b := twoInstallations(t)
	ctx := context.Background()
	stray, err := s.UpsertJob(ctx, &Job{GitHubJobID: 999, Repo: "globex/app", Workflow: "build", State: JobQueued,
		InstallationID: b.inst.ID, PoolID: a.pool.ID, QueuedAt: time.Date(2026, 5, 10, 12, 0, 0, 0, time.UTC)})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.PurgeInstallation(ctx, a.inst.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := s.GetJob(ctx, stray.ID); err != nil {
		t.Errorf("the other installation's job went with the purge: %v", err)
	}
}

// A pool that has since moved to another installation belongs to that one,
// even though the purged installation's old sessions still name it.
func TestAPurgeLeavesAPoolThatHasMovedToAnotherInstallation(t *testing.T) {
	s, a, b := twoInstallations(t)
	ctx := context.Background()
	a.pool.InstallationID = b.inst.ID
	if err := s.UpdatePool(ctx, a.pool); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PurgeInstallation(ctx, a.inst.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := s.GetPool(ctx, a.pool.ID); err != nil {
		t.Errorf("the purge took a pool another installation now holds: %v", err)
	}
}

// An archive goes back in whole onto an empty database, and what comes out of
// the new one is what went into the old one -- except the runners, whose rows
// point at hosts that only the old instance has.
func TestAnExportedInstallationImportsOntoAFreshDatabase(t *testing.T) {
	s, a, _ := twoInstallations(t)
	ctx := context.Background()
	tables, err := s.ExportInstallation(ctx, a.inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	raw, _ := json.Marshal(tables)
	var carried []ArchiveTable
	if err := json.Unmarshal(raw, &carried); err != nil {
		t.Fatalf("the archive does not read back: %v", err)
	}

	fresh := newTestStore(t)
	got, err := fresh.ImportInstallation(ctx, carried)
	if err != nil {
		t.Fatalf("ImportInstallation: %v", err)
	}
	if got.Skipped["runners"] != 2 || got.Rows["runner_sessions"] != 1 || got.Rows["audit_events"] != 4 {
		t.Errorf("import = %+v", got)
	}
	again, err := fresh.ExportInstallation(ctx, a.inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	for i := range tables {
		if tables[i].Table == "runners" {
			continue
		}
		w, _ := json.Marshal(tables[i])
		g, _ := json.Marshal(again[i])
		if string(w) != string(g) {
			t.Errorf("%s did not survive the round trip:\nwant %s\ngot  %s", tables[i].Table, w, g)
		}
	}
	inst, err := fresh.GetInstallation(ctx, a.inst.ID)
	if err != nil || string(inst.PrivateKeyEnc) != "sealed-acme" {
		t.Errorf("the installation came back as %+v, %v", inst, err)
	}

	// A second import of the same archive is a conflict, all or nothing.
	if _, err := fresh.ImportInstallation(ctx, carried); !errors.Is(err, ErrConflict) {
		t.Errorf("a second import gave %v, want ErrConflict", err)
	}
}

// An archive's column names reach an INSERT, so a name the schema does not
// have must be refused before it gets there.
func TestAnImportRefusesATableOrColumnTheSchemaDoesNotHave(t *testing.T) {
	s, a, _ := twoInstallations(t)
	ctx := context.Background()
	tables, err := s.ExportInstallation(ctx, a.inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		name   string
		mutate func([]ArchiveTable) []ArchiveTable
	}{
		{"an unknown table", func(ts []ArchiveTable) []ArchiveTable {
			return append(ts, ArchiveTable{Table: "users", Columns: []string{"id"}, Rows: [][]ArchiveValue{{{V: "usr_x"}}}})
		}},
		{"an unknown column", func(ts []ArchiveTable) []ArchiveTable {
			ts[1].Columns = append([]string(nil), ts[1].Columns...)
			ts[1].Columns[0] = "id) VALUES (1); DROP TABLE users; --"
			return ts
		}},
		{"a column named twice", func(ts []ArchiveTable) []ArchiveTable {
			ts[0].Columns = append([]string(nil), ts[0].Columns...)
			ts[0].Columns[len(ts[0].Columns)-1] = ts[0].Columns[0]
			return ts
		}},
		{"no installation", func(ts []ArchiveTable) []ArchiveTable { return ts[1:] }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			cp := append([]ArchiveTable(nil), tables...)
			fresh := newTestStore(t)
			if _, err := fresh.ImportInstallation(ctx, tc.mutate(cp)); !errors.Is(err, ErrArchiveShape) {
				t.Errorf("import gave %v, want ErrArchiveShape", err)
			}
			if list, _ := fresh.ListInstallations(ctx); len(list) != 0 {
				t.Errorf("a refused import left %d installations behind", len(list))
			}
		})
	}
}

// The archive carries the usage_daily rows the source had already rolled up
// and the sessions they came from, but not the watermark. On the new machine
// the roll-up therefore starts from the oldest imported session and computes
// days the archive already holds; a plain INSERT aborted on the primary key,
// every hour, for the whole instance -- and with the watermark never written
// the sessions could never be pruned either.
func TestTheUsageRollUpSucceedsAfterAnImportAndCountsNothingTwice(t *testing.T) {
	s, a, _ := twoInstallations(t)
	ctx := context.Background()
	tables, err := s.ExportInstallation(ctx, a.inst.ID)
	if err != nil {
		t.Fatal(err)
	}
	fresh := newTestStore(t)
	if _, err := fresh.ImportInstallation(ctx, tables); err != nil {
		t.Fatalf("ImportInstallation: %v", err)
	}
	imported := usageDays(t, fresh)
	if len(imported) == 0 {
		t.Fatal("the archive carried no usage days, so this test proves nothing")
	}

	until := time.Date(2026, 5, 12, 0, 0, 0, 0, time.UTC)
	for pass := 1; pass <= 2; pass++ {
		if _, err := fresh.RollUpUsage(ctx, until); err != nil {
			t.Fatalf("roll-up pass %d after the import: %v", pass, err)
		}
	}
	if _, _, ok, err := fresh.UsageRollupRange(ctx); err != nil || !ok {
		t.Fatalf("the roll-up wrote no watermark: ok=%v, %v", ok, err)
	}
	if got := usageDays(t, fresh); !reflect.DeepEqual(got, imported) {
		t.Fatalf("the roll-up changed the imported days:\nwant %+v\ngot  %+v", imported, got)
	}
}

package store

import (
	"context"
	"strings"
	"testing"
	"time"
)

// usageJob records a job on a runner in the given state.
func usageJob(t *testing.T, s *Store, n int, name, pool, runner string, state JobState, queued time.Time) *Job {
	t.Helper()
	j := &Job{
		GitHubJobID: int64(5000 + n), Repo: "eyupio/zoomies", Workflow: "CI", JobName: name,
		Labels: StringSlice{"self-hosted"}, State: state, QueuedAt: queued, Matched: true,
		PoolID: pool, RunnerID: runner,
	}
	if state == JobCompleted {
		done := queued.Add(time.Hour)
		j.StartedAt, j.CompletedAt, j.Conclusion = &queued, &done, "success"
	}
	out, _, err := s.ApplyJob(context.Background(), j)
	if err != nil {
		t.Fatalf("recording job %d: %v", n, err)
	}
	return out
}

// Samples arrive on every heartbeat, out of order after a reconnect, and
// before and after the job. Only the job GitHub says is running is charged,
// and a later, smaller sample must not lower what was already seen.
func TestRecordJobUsageRaisesOnlyTheRunningJobsPeaks(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	running := usageJob(t, s, 1, "Go (controller)", "pool_a", "run_1", JobInProgress, versionsEpoch)
	done := usageJob(t, s, 2, "Go (controller)", "pool_a", "run_1", JobCompleted, versionsEpoch.Add(-time.Hour))

	for _, sample := range []struct {
		cpus float64
		mb   int64
	}{{1.5, 900}, {3.9, 2800}, {0.2, 100}, {0, 0}} {
		if err := s.RecordJobUsage(ctx, "run_1", sample.cpus, sample.mb); err != nil {
			t.Fatalf("RecordJobUsage: %v", err)
		}
	}
	got, err := s.GetJob(ctx, running.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.PeakCPUs != 3.9 || got.PeakMemoryMB != 2800 {
		t.Fatalf("running job's peaks = %v CPU, %d MB, want 3.9 and 2800", got.PeakCPUs, got.PeakMemoryMB)
	}
	other, err := s.GetJob(ctx, done.ID)
	if err != nil {
		t.Fatal(err)
	}
	if other.PeakCPUs != 0 || other.PeakMemoryMB != 0 {
		t.Fatalf("a finished job was charged a later sample: %v CPU, %d MB", other.PeakCPUs, other.PeakMemoryMB)
	}
}

// A step killed with exit 137 leaves a runner that finishes the job, so the
// kill is reported after GitHub has closed it. It is recorded all the same,
// once, and a fault the runner reported first keeps its own words.
func TestMarkJobOOMKilledMarksTheRunnersLastJobOnce(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	usageJob(t, s, 1, "older", "pool_a", "run_1", JobCompleted, versionsEpoch.Add(-2*time.Hour))
	last := usageJob(t, s, 2, "Go (controller)", "pool_a", "run_1", JobCompleted, versionsEpoch)

	j, marked, err := s.MarkJobOOMKilled(ctx, "run_1", "runner r1 was killed for memory")
	if err != nil || !marked {
		t.Fatalf("MarkJobOOMKilled = %v, %v; want the job marked", marked, err)
	}
	if j.ID != last.ID || !j.OOMKilled || j.FaultKind != FaultOutOfMemory || j.RunnerFault != "runner r1 was killed for memory" {
		t.Fatalf("marked %+v, want the runner's last job, out of memory", j)
	}
	if _, again, err := s.MarkJobOOMKilled(ctx, "run_1", "a second report"); err != nil || again {
		t.Fatalf("a second report marked it again (%v, %v)", again, err)
	}

	// A fault recorded first keeps its sentence and category.
	lost := usageJob(t, s, 3, "lost", "pool_a", "run_2", JobInProgress, versionsEpoch)
	if _, _, err := s.SetJobRunnerFault(ctx, lost.ID, "runner exited with code 137", FaultOutOfMemory); err != nil {
		t.Fatal(err)
	}
	j, marked, err = s.MarkJobOOMKilled(ctx, "run_2", "ignored")
	if err != nil || !marked || j.RunnerFault != "runner exited with code 137" {
		t.Fatalf("MarkJobOOMKilled = %+v, %v, %v", j, marked, err)
	}

	if j, marked, err := s.MarkJobOOMKilled(ctx, "run_none", "x"); j != nil || marked || err != nil {
		t.Fatalf("a runner with no job marked %+v, %v, %v", j, marked, err)
	}
}

// The history a profile is taken from is the job's own measured runs, per
// pool, newest first, at most JobUsageHistoryLimit of them -- and a run that
// was never measured is not in it at all, because a zero is "unknown", not
// "needed nothing".
func TestJobUsageHistoryIsEachPoolsRecentMeasuredRuns(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	n := 0
	record := func(pool string, mb int64, oom bool, at time.Time) {
		n++
		runner := "run_" + strings.Repeat("x", n)
		usageJob(t, s, n, "Go (controller)", pool, runner, JobInProgress, at)
		if mb > 0 {
			if err := s.RecordJobUsage(ctx, runner, 2, mb); err != nil {
				t.Fatal(err)
			}
		}
		done := at.Add(time.Hour)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: int64(5000 + n), State: JobCompleted, Conclusion: "failure",
			Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", StartedAt: &at, CompletedAt: &done}); err != nil {
			t.Fatal(err)
		}
		if oom {
			if _, _, err := s.MarkJobOOMKilled(ctx, runner, "killed"); err != nil {
				t.Fatal(err)
			}
		}
	}
	for i := range JobUsageHistoryLimit + 5 {
		record("pool_a", int64(1000+i), false, versionsEpoch.Add(time.Duration(i)*time.Hour))
	}
	record("pool_b", 3000, true, versionsEpoch)
	record("pool_b", 0, false, versionsEpoch.Add(time.Hour)) // never measured

	got, err := s.JobUsageHistory(ctx, []JobUsageKey{{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)"}})
	if err != nil {
		t.Fatalf("JobUsageHistory: %v", err)
	}
	a := got[JobUsageKey{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", PoolID: "pool_a"}]
	if len(a) != JobUsageHistoryLimit || a[0].MemoryMB != int64(1000+JobUsageHistoryLimit+4) {
		t.Fatalf("pool_a history = %d runs, newest %+v; want %d, newest first", len(a), a[0], JobUsageHistoryLimit)
	}
	b := got[JobUsageKey{Repo: "eyupio/zoomies", Workflow: "CI", JobName: "Go (controller)", PoolID: "pool_b"}]
	if len(b) != 1 || !b[0].OOMKilled || b[0].MemoryMB != 3000 {
		t.Fatalf("pool_b history = %+v, want the one measured, killed run", b)
	}
}

// The history is read for every distinct queued job on every pass, so it must
// seek its index rather than walk a jobs table that grows without bound.
func TestJobUsageHistorySeeksItsIndex(t *testing.T) {
	s := newTestStore(t)
	rows, err := s.read.QueryContext(t.Context(), "EXPLAIN QUERY PLAN "+jobUsageHistorySQL, "r", "w", "j", 10)
	if err != nil {
		t.Fatalf("EXPLAIN QUERY PLAN: %v", err)
	}
	defer rows.Close()
	var plan []string
	for rows.Next() {
		var id, parent, notused int
		var detail string
		if err := rows.Scan(&id, &parent, &notused, &detail); err != nil {
			t.Fatal(err)
		}
		plan = append(plan, detail)
	}
	if joined := strings.Join(plan, "\n"); !strings.Contains(joined, "idx_jobs_usage_profile") {
		t.Fatalf("the history lookup does not use its index:\n%s", joined)
	}
}

// job_stats carries the heaviest job in each group and how many were killed
// for memory, so "which of our jobs need big hosts" is one call.
func TestJobStatsCarryPeakUsageAndMemoryKills(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	usageJob(t, s, 1, "light", "pool_a", "run_1", JobInProgress, versionsEpoch)
	usageJob(t, s, 2, "heavy", "pool_a", "run_2", JobInProgress, versionsEpoch)
	for _, u := range []struct {
		runner string
		cpus   float64
		mb     int64
	}{{"run_1", 0.5, 400}, {"run_2", 3.5, 5200}} {
		if err := s.RecordJobUsage(ctx, u.runner, u.cpus, u.mb); err != nil {
			t.Fatal(err)
		}
	}
	for n := 1; n <= 2; n++ {
		done := versionsEpoch.Add(time.Hour)
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: int64(5000 + n), State: JobCompleted, Conclusion: "failure",
			Repo: "eyupio/zoomies", StartedAt: &versionsEpoch, CompletedAt: &done}); err != nil {
			t.Fatal(err)
		}
	}
	if _, _, err := s.MarkJobOOMKilled(ctx, "run_2", "killed"); err != nil {
		t.Fatal(err)
	}
	res, err := s.JobStats(ctx, JobFilter{}, []string{GroupByJobName})
	if err != nil {
		t.Fatalf("JobStats: %v", err)
	}
	by := map[string]JobStatsGroup{}
	for _, g := range res.Groups {
		by[g.Keys[GroupByJobName]] = g
	}
	heavy := by["heavy"]
	if heavy.PeakCPUs == nil || *heavy.PeakCPUs != 3.5 || heavy.PeakMemoryMB == nil || *heavy.PeakMemoryMB != 5200 || heavy.OOMKilled != 1 {
		t.Fatalf("heavy = %+v", heavy)
	}
	if light := by["light"]; light.OOMKilled != 0 || light.PeakMemoryMB == nil || *light.PeakMemoryMB != 400 {
		t.Fatalf("light = %+v", light)
	}
}

package store

import (
	"context"
	"database/sql"
	"fmt"
	"slices"
	"testing"
	"time"
)

var versionsEpoch = time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)

// versionJob records a completed job with the given timings and stamps it. A
// blank version leaves the job the way one recorded before migration 0060 is:
// never stamped.
func versionJob(t *testing.T, s *Store, n int, version, name string, queued time.Time, wait, run time.Duration, conclusion string) *Job {
	t.Helper()
	ctx := context.Background()
	started, done := queued.Add(wait), queued.Add(wait+run)
	j, _, err := s.ApplyJob(ctx, &Job{
		GitHubJobID: int64(1000 + n), Repo: "acme/widgets", Workflow: "ci", JobName: name,
		Labels: StringSlice{"self-hosted"}, State: JobCompleted, Conclusion: conclusion,
		QueuedAt: queued, StartedAt: &started, CompletedAt: &done, Matched: true, PoolID: "pool_a",
	})
	if err != nil {
		t.Fatalf("recording job %d: %v", n, err)
	}
	if version != "" {
		j, err = s.StampJobVersions(ctx, j.ID, JobVersions{
			ControllerVersion: version, ControllerChannel: "stable", AgentVersion: "agent-" + version, HostID: "host_1",
		})
		if err != nil {
			t.Fatalf("stamping job %d: %v", n, err)
		}
	}
	return j
}

// A job's numbers belong to the build that produced them. If a later delivery
// -- the completion, a re-run, the poller repeating the claim -- could restamp
// the row, a release comparison would move jobs between releases whenever the
// controller was upgraded mid-flight.
func TestJobVersionsAreStampedOnceAndSurviveLaterUpdates(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	j, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 1, Repo: "acme/widgets", JobName: "build", State: JobQueued,
		Labels: StringSlice{"self-hosted"}, PoolID: "pool_a", Matched: true})
	if err != nil {
		t.Fatal(err)
	}
	if j.ControllerVersion != "" || j.HostID != "" {
		t.Fatalf("a new job carries versions: %+v", j)
	}

	// The claim knows the controller; the host is not known yet.
	got, err := s.StampJobVersions(ctx, j.ID, JobVersions{ControllerVersion: "v1.3.2", ControllerChannel: "stable"})
	if err != nil {
		t.Fatal(err)
	}
	if got.ControllerVersion != "v1.3.2" || got.ControllerChannel != "stable" || got.AgentVersion != "" || got.HostID != "" {
		t.Fatalf("claim stamp = %+v, want the controller's pair only", got)
	}

	// The runner's pickup fills in the host's pair and must not touch the first.
	got, err = s.StampJobVersions(ctx, j.ID, JobVersions{
		ControllerVersion: "v1.3.3", ControllerChannel: "edge", AgentVersion: "v1.3.1", HostID: "host_a"})
	if err != nil {
		t.Fatal(err)
	}
	if got.ControllerVersion != "v1.3.2" || got.ControllerChannel != "stable" || got.AgentVersion != "v1.3.1" || got.HostID != "host_a" {
		t.Fatalf("pickup stamp = %+v, want the controller's pair kept and the host's added", got)
	}

	// Nothing after that moves any of it, not another stamp and not a status update.
	if _, err := s.StampJobVersions(ctx, j.ID, JobVersions{
		ControllerVersion: "v9", ControllerChannel: "x", AgentVersion: "v9", HostID: "host_b"}); err != nil {
		t.Fatal(err)
	}
	started, done := versionsEpoch, versionsEpoch.Add(time.Minute)
	final, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: 1, State: JobCompleted, Conclusion: "success",
		StartedAt: &started, CompletedAt: &done})
	if err != nil {
		t.Fatal(err)
	}
	reread, err := s.GetJob(ctx, j.ID)
	if err != nil {
		t.Fatal(err)
	}
	for name, job := range map[string]*Job{"the update's result": final, "a fresh read": reread} {
		if job.ControllerVersion != "v1.3.2" || job.ControllerChannel != "stable" || job.AgentVersion != "v1.3.1" || job.HostID != "host_a" {
			t.Errorf("%s = %+v, want the first stamps", name, job)
		}
	}
}

// Old rows stay NULL rather than being guessed at, and an empty stamp writes
// nothing: "unknown" has to be distinguishable from a release with no name.
func TestAnUnstampedJobIsNullInTheDatabase(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	j := versionJob(t, s, 1, "", "build", versionsEpoch, time.Second, time.Second, "success")
	if _, err := s.StampJobVersions(ctx, j.ID, JobVersions{}); err != nil {
		t.Fatal(err)
	}
	var v, c, a, h sql.NullString
	if err := s.read.QueryRowContext(ctx, `SELECT controller_version, controller_channel, agent_version, host_id FROM jobs WHERE id = ?`, j.ID).
		Scan(&v, &c, &a, &h); err != nil {
		t.Fatal(err)
	}
	if v.Valid || c.Valid || a.Valid || h.Valid {
		t.Fatalf("stamped nothing but the row holds %v %v %v %v", v, c, a, h)
	}
}

// The usage ledger is what outlives the job rows, so the release has to be in it.
func TestARunnerSessionCarriesTheReleaseOfItsJob(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "zoomies-1", Ephemeral: true}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	j := versionJob(t, s, 1, "v1.3.3", "build", versionsEpoch, time.Second, time.Minute, "success")
	if _, err := s.exec(ctx, `UPDATE runners SET current_job_id = ?, state = 'removed', finished_at = ? WHERE id = ?`,
		j.ID, ms(versionsEpoch.Add(time.Hour)), r.ID); err != nil {
		t.Fatal(err)
	}
	if err := s.tx(ctx, func(tx *sql.Tx) error { return recordRunnerSession(ctx, tx, r.ID, ms(versionsEpoch.Add(2*time.Hour))) }); err != nil {
		t.Fatal(err)
	}
	// The job row goes at retention; the session keeps what it learned.
	if _, err := s.PruneJobs(ctx, versionsEpoch.Add(24*time.Hour)); err != nil {
		t.Fatal(err)
	}
	sessions, err := s.RunnerSessions(ctx, time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC), time.Date(2100, 1, 1, 0, 0, 0, 0, time.UTC))
	if err != nil || len(sessions) != 1 {
		t.Fatalf("sessions = %v, %v", sessions, err)
	}
	if got := sessions[0]; got.ControllerVersion != "v1.3.3" || got.ControllerChannel != "stable" || got.AgentVersion != "agent-v1.3.3" || got.HostID != host.ID {
		t.Fatalf("session = %+v, want the job's release and the runner's host", got)
	}
}

func ids(jobs []*Job) []string {
	out := make([]string, len(jobs))
	for i, j := range jobs {
		out[i] = j.ID
	}
	return out
}

// since is inclusive and until exclusive, so that the last 30 days and the 30
// before them, cut at the same instant, share no job and lose none.
func TestSinceIsInclusiveAndUntilExclusive(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	at := func(m int) time.Time { return versionsEpoch.Add(time.Duration(m) * time.Minute) }
	var made []*Job
	for m := 0; m < 4; m++ {
		made = append(made, versionJob(t, s, m, "v1", "build", at(m), time.Second, time.Second, "success"))
	}
	since, until := at(1), at(3)
	got, total, err := s.ListJobs(ctx, JobFilter{Since: &since, Until: &until}, Page{Limit: 10, Sort: "queued_at", Desc: false})
	if err != nil {
		t.Fatal(err)
	}
	want := []string{made[1].ID, made[2].ID}
	if !slices.Equal(ids(got), want) || total != 2 {
		t.Fatalf("[minute 1, minute 3) = %v (total %d), want minutes 1 and 2 %v", ids(got), total, want)
	}
}

// Offset paging repeats or drops a row whenever a job is queued between two
// pages. A keyset cursor must not, because that is why it exists.
func TestCursorPagingReturnsEveryJobOnceWhileNewJobsArrive(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	var original []string
	// Ten of the 31 share a timestamp, so the tie-break is exercised too.
	for n := 0; n < 31; n++ {
		queued := versionsEpoch.Add(time.Duration(n/3) * time.Minute)
		original = append(original, versionJob(t, s, n, "v1", "build", queued, time.Second, time.Second, "success").ID)
	}
	var seen []string
	var cursor *JobCursor
	arrivals := 0
	for pages := 0; ; pages++ {
		if pages > 50 {
			t.Fatal("the cursor never ran out")
		}
		got, _, next, err := s.ListJobsAfter(ctx, JobFilter{}, cursor, 4)
		if err != nil {
			t.Fatal(err)
		}
		seen = append(seen, ids(got)...)
		// A job arrives between every two pages, newer than everything read.
		arrivals++
		versionJob(t, s, 1000+arrivals, "v1", "arrival", versionsEpoch.Add(time.Duration(100+arrivals)*time.Hour), time.Second, time.Second, "success")
		if next == nil {
			break
		}
		token, err := ParseJobCursor(next.Encode())
		if err != nil || token.ID != next.ID || !token.QueuedAt.Equal(next.QueuedAt) {
			t.Fatalf("the cursor did not survive its own encoding: %+v -> %+v (%v)", next, token, err)
		}
		cursor = &token
	}
	slices.Sort(seen)
	slices.Sort(original)
	if !slices.Equal(seen, original) {
		t.Fatalf("paging returned %d jobs, want the %d that existed when it began, each once\n got %v\nwant %v",
			len(seen), len(original), seen, original)
	}
}

