package store

import (
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// The lock is what stops a second controller on the same host, and it has to
// hold between processes rather than only between goroutines -- a lock the
// same process can take twice would pass a test and protect nothing.
func TestTheDatabaseLockIsRefusedToASecondProcess(t *testing.T) {
	db := filepath.Join(t.TempDir(), "zoomies.db")

	release, err := Lock(db)
	if err != nil {
		t.Fatalf("Lock: %v", err)
	}

	// A second process, because flock is per open file description: this
	// process asking again would be granted it. The helper fails unless the
	// lock is refused, so this asserts on its exit status.
	helper := exec.Command(os.Args[0], "-test.run=TestLockHelperProcess", "-test.v")
	helper.Env = append(os.Environ(), "ZOOMIES_TEST_LOCK_DB="+db)
	out, err := helper.CombinedOutput()
	if err != nil {
		t.Fatalf("the helper did not see the lock held:\n%s", out)
	}
	// And prove the helper actually ran rather than skipping itself, which is
	// the way this test lies to you.
	if !strings.Contains(string(out), "TestLockHelperProcess") || strings.Contains(string(out), "SKIP") {
		t.Fatalf("the helper process did not run its assertion:\n%s", out)
	}

	if err := release(); err != nil {
		t.Fatalf("release: %v", err)
	}
	// And once released, the next controller starts.
	again, err := Lock(db)
	if err != nil {
		t.Fatalf("the lock was not released: %v", err)
	}
	if err := again(); err != nil {
		t.Fatal(err)
	}
}

// TestLockHelperProcess is the second process. It fails unless the lock is
// already held, which is what the test above is asserting.
func TestLockHelperProcess(t *testing.T) {
	db := os.Getenv("ZOOMIES_TEST_LOCK_DB")
	if db == "" {
		t.Skip("not the helper process")
	}
	if _, err := Lock(db); !errors.Is(err, ErrLocked) {
		t.Fatalf("Lock in a second process = %v, want ErrLocked", err)
	}
}

// An in-memory database belongs to one process by construction, so locking one
// would only make every test that opens a store contend with the others.
func TestAnInMemoryDatabaseIsNotLocked(t *testing.T) {
	release, err := Lock(":memory:")
	if err != nil {
		t.Fatalf("Lock(:memory:) = %v", err)
	}
	if err := release(); err != nil {
		t.Fatal(err)
	}
	// Two of them at once, as the test suite does constantly.
	a, err := Lock(":memory:")
	if err != nil {
		t.Fatal(err)
	}
	b, err := Lock(":memory:")
	if err != nil {
		t.Fatalf("a second in-memory store was refused: %v", err)
	}
	_ = a()
	_ = b()
}

// The lock file sits beside the database, because the database is what two
// controllers contend for.
func TestTheLockSitsBesideTheDatabase(t *testing.T) {
	if got, want := LockPath("/var/lib/zoomies/zoomies.db"), "/var/lib/zoomies/zoomies.db.lock"; got != want {
		t.Errorf("LockPath = %q, want %q", got, want)
	}
}

//go:build unix

package store

import (
	"errors"
	"fmt"
	"os"
	"syscall"
)

// lockFile takes a BSD advisory lock, which the kernel drops when the process
// exits however it exits. That is the property that matters here: a controller
// killed with SIGKILL must not leave a lock behind that an operator has to
// find and remove before the service will start again.
func lockFile(path string) (func() error, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("opening the database lock at %s: %w", path, err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		f.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, ErrLocked
		}
		return nil, fmt.Errorf("locking %s: %w", path, err)
	}
	return func() error {
		// Unlock before closing so the error, if there is one, is reportable;
		// closing the descriptor would release it anyway.
		err := syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		if cerr := f.Close(); err == nil {
			err = cerr
		}
		return err
	}, nil
}

//go:build windows

package store

import (
	"errors"
	"fmt"
	"os"

	"golang.org/x/sys/windows"
)

// lockFile takes an exclusive byte-range lock on the whole file, which Windows
// releases when the handle closes -- including when the process dies, however
// it dies. That is the same property flock gives on POSIX, and the reason the
// lock is a kernel object rather than a pid written into a file: a controller
// killed by the service manager must not leave a lock behind that an operator
// has to find and delete before the service will start again.
func lockFile(path string) (func() error, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("opening the database lock at %s: %w", path, err)
	}
	h := windows.Handle(f.Fd())
	ol := new(windows.Overlapped)
	if err := windows.LockFileEx(h, windows.LOCKFILE_EXCLUSIVE_LOCK|windows.LOCKFILE_FAIL_IMMEDIATELY, 0, 1, 0, ol); err != nil {
		f.Close()
		if errors.Is(err, windows.ERROR_LOCK_VIOLATION) {
			return nil, ErrLocked
		}
		return nil, fmt.Errorf("locking %s: %w", path, err)
	}
	return func() error {
		err := windows.UnlockFileEx(h, 0, 1, 0, ol)
		if cerr := f.Close(); err == nil {
			err = cerr
		}
		return err
	}, nil
}

package store

import (
	"context"
	"testing"
	"time"
)

// The three predicates the fleet's arithmetic rests on.
//
// Pending and Offers are read by the machine-demand calculation to decide how
// much capacity is already on its way, so an error here is not a wrong label:
// it is a fleet that buys a second machine because it forgot about the first,
// or one that never buys because it counted a machine that will never arrive.
// They are spelled out state by state rather than derived, because deriving
// them from the lifecycle order is exactly the change that would silently
// reclassify a state somebody adds later.
func TestWhatEachMachineStateCountsAs(t *testing.T) {
	for _, tc := range []struct {
		state    MachineState
		pending  bool
		offers   bool
		terminal bool
	}{
		// Nothing exists yet, but something is coming: a reservation counts.
		{MachinePlanned, true, true, false},
		{MachineCreating, true, true, false},
		{MachineStarting, true, true, false},
		{MachineBootstrapping, true, true, false},
		{MachineEnrolling, true, true, false},
		// It has arrived, so its capacity is a host row rather than a promise.
		{MachineReady, false, true, false},
		// On its way out: its slots are being given up, so counting them would
		// keep a shortfall closed with capacity that is leaving.
		{MachineDraining, false, false, false},
		{MachineDeleting, false, false, false},
		// Gone, and the only state that is finished with.
		{MachineDeleted, false, false, true},
		// Both of these still need attention and may still have a resource
		// behind them, which is why neither is terminal.
		{MachineFailed, false, false, false},
		{MachineQuarantined, false, false, false},
	} {
		t.Run(string(tc.state), func(t *testing.T) {
			if !tc.state.Valid() {
				t.Fatalf("%s is not a state the store recognises", tc.state)
			}
			if got := tc.state.Pending(); got != tc.pending {
				t.Errorf("Pending() = %v, want %v", got, tc.pending)
			}
			if got := tc.state.Offers(); got != tc.offers {
				t.Errorf("Offers() = %v, want %v", got, tc.offers)
			}
			if got := tc.state.Terminal(); got != tc.terminal {
				t.Errorf("Terminal() = %v, want %v", got, tc.terminal)
			}
			// Pending capacity is capacity on offer. A state that was pending
			// and not offering would be one the fleet waits for and never
			// counts, which is how a queue stalls behind machines it already
			// has.
			if tc.state.Pending() && !tc.state.Offers() {
				t.Error("a pending machine must count towards what the fleet has coming")
			}
		})
	}

	if MachineState("melting").Valid() {
		t.Error("an unknown state was accepted; the CHECK constraint and this list would then disagree")
	}
}

// The two small enums the operation columns are constrained to. An unknown
// value must not be accepted here, because the database's CHECK constraint
// would refuse the write afterwards and the refusal would name a column rather
// than the thing that was wrong.
func TestOnlyRealOperationsAndOutcomesAreAccepted(t *testing.T) {
	for _, k := range []MachineOpKind{MachineOpCreate, MachineOpStart, MachineOpStop, MachineOpBootstrap, MachineOpDelete} {
		if !k.Valid() {
			t.Errorf("%s is not accepted as an operation", k)
		}
	}
	if MachineOpKind("reboot").Valid() {
		t.Error("an operation the machine cannot be doing was accepted")
	}
	if !MachineOpNone.Valid() {
		t.Error("the absent operation is what an idle machine's column holds and has to be legal")
	}

	for _, o := range []MachineOpOutcome{MachineOpSucceeded, MachineOpFailed, MachineOpReleased} {
		if !o.Valid() {
			t.Errorf("%s is not accepted as an outcome", o)
		}
	}
	if MachineOpOutcome("probably").Valid() {
		t.Error("an outcome nothing can act on was accepted")
	}
	// Releasing a claim is not a verdict, so it must be a legal outcome: a
	// guard that refused after the claim was taken has to hand the machine
	// back without counting an attempt against it.
	if !MachineOpReleased.Valid() {
		t.Error("giving a claim back is not accepted as an outcome")
	}
}

// The three lookups the reconciler reaches for: by the resource it believes it
// owns, by provider, and the idle clock it stamps.
//
// Finding a machine by its resource is how an ambiguous create is resolved --
// the identity was written before anything was built, so the question after a
// lost response is "whose is this?" rather than "make another".
func TestAMachineIsFoundByTheResourceItNames(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)

	m := seedMachine(t, s, p.ID, MachinePlanned)
	if err := s.SetMachineResource(ctx, m.ID, "pve-1", "143", "fingerprint", "ctl_one"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}

	found, err := s.GetMachineByResource(ctx, p.ID, "pve-1", "143")
	if err != nil {
		t.Fatalf("GetMachineByResource: %v", err)
	}
	if found.ID != m.ID {
		t.Errorf("found %s, want %s", found.ID, m.ID)
	}

	// A resource on another node is a different resource, however familiar the
	// identifier looks: VM 143 exists on every node of a cluster.
	if _, err := s.GetMachineByResource(ctx, p.ID, "pve-2", "143"); err == nil {
		t.Error("a machine on one node answered for the same id on another")
	}
	if _, err := s.GetMachineByResource(ctx, p.ID, "pve-1", "144"); err == nil {
		t.Error("a machine answered for an id it does not have")
	}
}

// What a pass reads is every machine of one provider that it can still do
// something about -- which is all of them except the ones already confirmed
// gone. A deleted machine's row is kept for the record of what was rented and
// what it cost, but putting it in front of the reconcile pass on every tick
// would mean the list grows without bound on a fleet that is working normally.
//
// A machine belonging to another provider is never in it. Two providers are
// two hypervisors, and a pass that mixed them would ask one of them about a
// resource the other owns.
func TestAPassSeesEveryMachineItCanStillActOnAndNoOthers(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	mine := seedProvider(t, s)
	theirs := &Provider{Kind: ProviderFake, Name: "another-lab", MachineCapacity: 2,
		MachineBackend: BackendDocker, MaxMachines: 4, MaxCreatesInFlight: 1, Enabled: true}
	if err := s.CreateProvider(ctx, theirs); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}

	want := map[string]bool{}
	for _, state := range []MachineState{MachinePlanned, MachineReady, MachineQuarantined, MachineFailed} {
		want[seedMachine(t, s, mine.ID, state).ID] = true
	}
	// Neither of these may appear: one is finished with, the other is not ours.
	gone := seedMachine(t, s, mine.ID, MachineDeleted)
	elsewhere := seedMachine(t, s, theirs.ID, MachineReady)

	got, err := s.ListMachinesForProvider(ctx, mine.ID)
	if err != nil {
		t.Fatalf("ListMachinesForProvider: %v", err)
	}
	if len(got) != len(want) {
		t.Fatalf("listed %d machines, want %d; every pass reads this list and a missing row is a machine "+
			"nothing is tending", len(got), len(want))
	}
	for _, m := range got {
		switch m.ID {
		case gone.ID:
			t.Error("a machine already confirmed gone is still put in front of every pass")
		case elsewhere.ID:
			t.Error("another provider's machine was listed for this one")
		default:
			if !want[m.ID] {
				t.Errorf("%s was listed and is not one of this provider's", m.ID)
			}
		}
	}
	// A failed or quarantined machine still needs attention -- and may still
	// have a resource costing money behind it -- so neither is filtered out
	// with the deleted ones.
	if len(want) != 4 {
		t.Fatal("the test no longer covers the two states that are finished with in the fleet's eyes but not in the provider's")
	}
}

// The idle clock is stamped once when a machine's host empties and cleared the
// moment a runner lands on it. Clearing matters more than stamping: a machine
// that took work and kept a stale idle stamp would be drained out from under
// the job it had just been given.
func TestTheIdleClockIsClearedTheMomentWorkArrives(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineReady)

	since := s.Now().Add(-20 * time.Minute).UTC().Truncate(time.Millisecond)
	if err := s.SetMachineIdleSince(ctx, m.ID, &since); err != nil {
		t.Fatalf("SetMachineIdleSince: %v", err)
	}
	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatalf("GetMachine: %v", err)
	}
	if got.IdleSince == nil || !got.IdleSince.Equal(since) {
		t.Fatalf("idle_since = %v, want %s", got.IdleSince, since)
	}

	if err := s.SetMachineIdleSince(ctx, m.ID, nil); err != nil {
		t.Fatalf("clearing SetMachineIdleSince: %v", err)
	}
	if got, err = s.GetMachine(ctx, m.ID); err != nil {
		t.Fatalf("GetMachine: %v", err)
	}
	if got.IdleSince != nil {
		t.Errorf("idle_since = %v after work arrived, want it cleared", got.IdleSince)
	}
}

package store

import (
	"slices"
	"time"
)

// ---------------------------------------------------------------------------
// Providers
// ---------------------------------------------------------------------------

// ProviderKind selects the infrastructure a provider rents machines from. It is
// the key the provider registry resolves a factory with, and it is CHECKed in
// the schema, so a kind this build does not know cannot be written and then
// read back as something to act on.
type ProviderKind string

const (
	ProviderProxmox ProviderKind = "proxmox"
	ProviderFake    ProviderKind = "fake"
)

func (k ProviderKind) Valid() bool {
	switch k {
	case ProviderProxmox, ProviderFake:
		return true
	}
	return false
}

// Provider is one place machines can be rented from: the credential, the one
// machine shape it offers, and the ceilings an operator put on it.
//
// The ceilings are the safe default rather than a convenience: MaxMachines is
// zero on a row nobody has configured, which refuses everything. A provider
// that bought machines the moment its credential was accepted would spend money
// on the strength of a connection test.
type Provider struct {
	ID   string       `json:"id"`
	Kind ProviderKind `json:"kind"`
	Name string       `json:"name"`
	// Endpoint, CAPEM and InsecureSkipVerify are how this controller reaches
	// the provider. InsecureSkipVerify is recorded rather than refused because
	// a homelab hypervisor's certificate is usually its own, but it weakens
	// the connection and the validator says so.
	Endpoint           string `json:"endpoint,omitempty"`
	CAPEM              string `json:"ca_pem,omitempty"`
	InsecureSkipVerify bool   `json:"insecure_skip_verify,omitempty"`
	// Settings holds the non-secret answers to the provider's own SettingSpecs
	// -- which node, which storage, which template. It is a map rather than a
	// column per key so that a second provider needs no migration.
	Settings StringMap `json:"settings"`
	// CredentialsEnc is sealed with the instance key and never leaves this
	// process in plaintext. HasSealedSecrets counts it, so a controller that
	// has lost its key refuses to generate a new one rather than starting and
	// failing inside its first call to the hypervisor.
	CredentialsEnc []byte `json:"-"`
	// TailcatAddressEnc is the sealed address of a `zoomies gateway` in front
	// of the provider's API, for a hypervisor on a home network the controller
	// cannot otherwise reach. Empty means the endpoint is dialled directly.
	// Sealed for the same reason the credential is: the address is a lasting
	// capability to open connections to that API, not a name.
	TailcatAddressEnc []byte `json:"-"`

	// The one machine shape this provider offers. Every machine it buys is
	// this shape, and a second shape is a second provider row.
	MachineLabels   StringMap   `json:"machine_labels"`
	MachineCapacity int         `json:"machine_capacity"`
	MachineBackend  BackendKind `json:"machine_backend"`
	MachinePlatform Platform    `json:"machine_platform"`
	MachineCPUs     float64     `json:"machine_cpus,omitempty"`
	MachineMemoryMB int64       `json:"machine_memory_mb,omitempty"`
	MachineDiskMB   int64       `json:"machine_disk_mb,omitempty"`

	// PoolSelector narrows which pools this provider may buy for, the way a
	// pool's HostSelector narrows where its runners may be placed. Empty means
	// every pool, which is what one provider and one fleet want.
	PoolSelector StringMap `json:"pool_selector"`
	// MaxMachines is the ceiling on machines this provider may own at once;
	// MaxCreatesInFlight is the ceiling on how many it may be creating. The
	// second exists because a hypervisor cloning four templates at once is
	// slower at all four than it would have been at one.
	MaxMachines        int      `json:"max_machines"`
	MaxCreatesInFlight int      `json:"max_creates_in_flight"`
	IdleTimeout        Duration `json:"idle_timeout"`
	CostPerMachineHour float64  `json:"cost_per_machine_hour,omitempty"`
	Enabled            bool     `json:"enabled"`

	// Paused is the operator's kill switch and PausedUntil the breaker's. They
	// are separate columns because a breaker that expired must not un-press a
	// switch a person pressed.
	Paused              bool       `json:"paused"`
	PausedReason        string     `json:"paused_reason,omitempty"`
	PausedUntil         *time.Time `json:"paused_until,omitempty"`
	ConsecutiveFailures int        `json:"consecutive_failures,omitempty"`
	LastCheckAt         *time.Time `json:"last_check_at,omitempty"`
	LastCheckError      string     `json:"last_check_error,omitempty"`
	LastSweepAt         *time.Time `json:"last_sweep_at,omitempty"`
	CreatedAt           time.Time  `json:"created_at"`
	UpdatedAt           time.Time  `json:"updated_at"`
}

// ---------------------------------------------------------------------------
// Machines
// ---------------------------------------------------------------------------

// MachineState is the lifecycle of one rented machine, from a row that names
// nothing to a host that runs jobs.
type MachineState string

const (
	MachinePlanned       MachineState = "planned"       // the reservation exists; nothing has been created
	MachineCreating      MachineState = "creating"      // identity persisted; a create may or may not have happened
	MachineStarting      MachineState = "starting"      // the resource exists and is being powered on
	MachineBootstrapping MachineState = "bootstrapping" // the guest is up; the agent is being installed
	MachineEnrolling     MachineState = "enrolling"     // the agent has its credential and has not joined
	MachineReady         MachineState = "ready"         // a host row exists and is linked
	MachineDraining      MachineState = "draining"      // cordoned; waiting for its runners to finish
	MachineDeleting      MachineState = "deleting"      // a delete was issued and is not confirmed
	MachineDeleted       MachineState = "deleted"       // the provider confirmed the resource is gone
	MachineFailed        MachineState = "failed"        // we gave up on the lifecycle; the resource may still exist
	MachineQuarantined   MachineState = "quarantined"   // ownership could not be proved; only an operator moves it
)

func (s MachineState) Valid() bool {
	switch s {
	case MachinePlanned, MachineCreating, MachineStarting, MachineBootstrapping,
		MachineEnrolling, MachineReady, MachineDraining, MachineDeleting,
		MachineDeleted, MachineFailed, MachineQuarantined:
		return true
	}
	return false
}

// Terminal is deleted alone. Failed and quarantined still need attention, and a
// failed machine may still have a resource behind it.
func (s MachineState) Terminal() bool { return s == MachineDeleted }

// Pending is a machine the fleet is waiting on: it has no host yet, so its
// capacity is a reservation rather than a fact.
func (s MachineState) Pending() bool {
	switch s {
	case MachinePlanned, MachineCreating, MachineStarting, MachineBootstrapping, MachineEnrolling:
		return true
	}
	return false
}

// Offers is a machine whose capacity counts towards satisfying demand.
func (s MachineState) Offers() bool { return s.Pending() || s == MachineReady }

// MachineOpKind is the one kind of operation that may be in flight against a
// machine. The empty string is "none", and the schema CHECKs the set.
type MachineOpKind string

const (
	MachineOpNone      MachineOpKind = ""
	MachineOpCreate    MachineOpKind = "create"
	MachineOpStart     MachineOpKind = "start"
	MachineOpStop      MachineOpKind = "stop"
	MachineOpBootstrap MachineOpKind = "bootstrap"
	MachineOpDelete    MachineOpKind = "delete"
)

func (k MachineOpKind) Valid() bool {
	switch k {
	case MachineOpNone, MachineOpCreate, MachineOpStart, MachineOpStop, MachineOpBootstrap, MachineOpDelete:
		return true
	}
	return false
}

// MachineOperation is one pass's claim on a machine's next step.
//
// Timeout is required, and ClaimMachineOperation refuses a claim without one:
// a claim with no deadline is a claim a controller that dies mid-operation
// holds for ever, and the machine behind it would never be looked at again.
type MachineOperation struct {
	// ID is minted per attempt when it is empty, and is what a log line and an
	// operator quote. Holder is the controller taking the step, so a machine
	// stuck mid-create names the controller to go and look at.
	ID      string
	Kind    MachineOpKind
	Holder  string
	Timeout time.Duration
}

// MachineOpOutcome is how an operation ended, which decides what happens to the
// retry accounting rather than to the state -- the state is TransitionMachine's.
type MachineOpOutcome string

const (
	// MachineOpSucceeded clears the provider's complaint and the backoff.
	MachineOpSucceeded MachineOpOutcome = "succeeded"
	// MachineOpFailed counts an attempt and sets the next one.
	MachineOpFailed MachineOpOutcome = "failed"
	// MachineOpReleased gives the claim back without a verdict: a guard that
	// refused after the claim was taken, or a controller shutting down. It
	// must not count an attempt, because nothing about the machine went wrong
	// and counting it would walk the backoff up towards giving up.
	MachineOpReleased MachineOpOutcome = "released"
)

func (o MachineOpOutcome) Valid() bool {
	switch o {
	case MachineOpSucceeded, MachineOpFailed, MachineOpReleased:
		return true
	}
	return false
}

// MachineErrorSource says which of the two independent systems complained. They
// have a column each for the reason 0022 gives about runner cleanup: a success
// on one must not erase the other's complaint, and an operator reading one
// error has to know which half to go and look at.
type MachineErrorSource string

const (
	// MachineErrorProvider is the hypervisor or cloud API.
	MachineErrorProvider MachineErrorSource = "provider"
	// MachineErrorBootstrap is everything inside the guest: the agent install,
	// the enrolment, the handshake back.
	MachineErrorBootstrap MachineErrorSource = "bootstrap"
)

func (s MachineErrorSource) Valid() bool {
	return s == MachineErrorProvider || s == MachineErrorBootstrap
}

// Machine is one rented machine: the row that exists before the resource does,
// and outlives it by exactly as long as it takes to prove the resource is gone.
type Machine struct {
	ID         string       `json:"id"`
	ProviderID string       `json:"provider_id"`
	Name       string       `json:"name"`
	State      MachineState `json:"state"`
	Message    string       `json:"message,omitempty"`
	// PoolID records which pool's unmet demand asked for this machine. It is
	// not ownership -- a machine serves every pool its labels match -- and it
	// exists so the machine page can answer "why does this exist".
	PoolID string `json:"pool_id,omitempty"`

	// OwnerControllerID and OwnerFingerprint are written before the first call
	// that can create anything. The fingerprint is tamper-evidence rather than
	// a credential: anybody with audit rights on the hypervisor can read it,
	// and its job is to tell "the VM I created at 143" apart from "a VM
	// somebody else created at 143 after mine was destroyed".
	OwnerControllerID string `json:"owner_controller_id,omitempty"`
	OwnerFingerprint  string `json:"owner_fingerprint,omitempty"`
	// ResourceZone and ResourceID are the provider's own identity for this
	// machine -- a node and a VM id. Written once, never moved.
	ResourceZone   string    `json:"resource_zone,omitempty"`
	ResourceID     string    `json:"resource_id,omitempty"`
	ResourceDetail StringMap `json:"resource_detail,omitempty"`
	Address        string    `json:"address,omitempty"`
	// OwnershipVerifiedAt is the last time a fresh observation agreed that this
	// resource is ours. OwnershipError is what disagreed. A delete needs the
	// first and the absence of the second.
	OwnershipVerifiedAt *time.Time `json:"ownership_verified_at,omitempty"`
	OwnershipError      string     `json:"ownership_error,omitempty"`

	// HostID is the enrolment link, and the only thing that grants this
	// controller deletion authority over a host. It is written by
	// LinkMachineHost after a token this row minted was redeemed, and by
	// nothing else -- there is no route that attaches a machine to a host an
	// operator already had.
	HostID      string    `json:"host_id,omitempty"`
	JoinTokenID string    `json:"join_token_id,omitempty"`
	Capacity    int       `json:"capacity,omitempty"`
	Labels      StringMap `json:"labels,omitempty"`

	// The operation in flight, if any. OpHandle is the provider's own handle
	// for the call -- a task id -- and is what recovery asks about after a
	// restart. OpOutcomeUnknown marks a call that went out and was never
	// answered, which is the one thing a retry must not treat as "it failed".
	OpID             string        `json:"op_id,omitempty"`
	OpKind           MachineOpKind `json:"op_kind,omitempty"`
	OpHandle         string        `json:"op_handle,omitempty"`
	OpHolder         string        `json:"op_holder,omitempty"`
	OpStartedAt      *time.Time    `json:"op_started_at,omitempty"`
	OpDeadlineAt     *time.Time    `json:"op_deadline_at,omitempty"`
	OpOutcomeUnknown bool          `json:"op_outcome_unknown,omitempty"`

	Attempts       int        `json:"attempts,omitempty"`
	NextAttemptAt  *time.Time `json:"next_attempt_at,omitempty"`
	ProviderError  string     `json:"provider_error,omitempty"`
	BootstrapError string     `json:"bootstrap_error,omitempty"`

	CreatedAt            time.Time  `json:"created_at"`
	UpdatedAt            time.Time  `json:"updated_at"`
	ReservationExpiresAt *time.Time `json:"reservation_expires_at,omitempty"`
	CreateStartedAt      *time.Time `json:"create_started_at,omitempty"`
	CreatedOKAt          *time.Time `json:"created_ok_at,omitempty"`
	StartedAt            *time.Time `json:"started_at,omitempty"`
	BootstrappedAt       *time.Time `json:"bootstrapped_at,omitempty"`
	EnrolledAt           *time.Time `json:"enrolled_at,omitempty"`
	ReadyAt              *time.Time `json:"ready_at,omitempty"`
	IdleSince            *time.Time `json:"idle_since,omitempty"`
	DrainingAt           *time.Time `json:"draining_at,omitempty"`
	DeleteStartedAt      *time.Time `json:"delete_started_at,omitempty"`
	// DeletedAt is when the provider confirmed the resource was gone, by an
	// inspect that could not find it. A 200 from the delete call is not that,
	// which is why only ConfirmMachineDeleted writes this.
	DeletedAt *time.Time `json:"deleted_at,omitempty"`
}

// Owns reports whether this row believes a resource exists in the provider. It
// is deliberately NOT a state test: a failed machine whose VM was created still
// costs money and still counts against max_machines, and a planned one costs
// nothing. The SQL half of this predicate lives in CountOwnedMachines, and a
// test holds the two definitions equal -- live_rows_test.go's reason.
func (m *Machine) Owns() bool { return m.ResourceID != "" && m.DeletedAt == nil }

// validMachineTransitions is the allow-list Store.TransitionMachine enforces. It
// is here rather than in the reconciler for the same reason the runner one is: a
// pass that has just lost a race, or a provider that answered oddly, must not be
// able to talk a machine into a state that makes the fleet's accounting wrong.
//
// The absences are the design:
//   - nothing returns to planned: you never go back to "nothing exists";
//   - deleting leads only to deleted or quarantined, because a delete that was
//     issued cannot be un-issued; if we cannot tell, an operator is asked;
//   - quarantined never returns to ready: a machine whose ownership we could not
//     prove does not silently rejoin the fleet;
//   - failed may still reach deleting, because a later sweep can find a resource
//     we believed never existed;
//   - draining returns to ready, so demand coming back cancels a drain rather
//     than paying for a new machine.
var validMachineTransitions = map[MachineState][]MachineState{
	MachinePlanned:       {MachineCreating, MachineFailed, MachineDeleted, MachineQuarantined},
	MachineCreating:      {MachineStarting, MachineBootstrapping, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineStarting:      {MachineBootstrapping, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineBootstrapping: {MachineEnrolling, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineEnrolling:     {MachineReady, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineReady:         {MachineDraining, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineDraining:      {MachineReady, MachineDeleting, MachineFailed, MachineQuarantined},
	MachineDeleting:      {MachineDeleted, MachineQuarantined},
	MachineDeleted:       {},
	MachineFailed:        {MachineDeleting, MachineDeleted, MachineQuarantined},
	MachineQuarantined:   {MachineDeleting, MachineDeleted},
}

// CanTransitionMachine reports whether from -> to is a legal machine state
// change. A self-transition is always legal, because a pass re-reporting the
// state a machine is already in is not an error and must not become one.
func CanTransitionMachine(from, to MachineState) bool {
	if from == to {
		return true
	}
	return slices.Contains(validMachineTransitions[from], to)
}

package store

import (
	"context"
	"errors"
	"reflect"
	"strings"
	"testing"
	"time"
)

func seedProvider(t *testing.T, s *Store) *Provider {
	t.Helper()
	p := &Provider{
		Kind: ProviderFake, Name: "lab", Endpoint: "https://pve.example:8006",
		MachineCapacity: 2, MachineBackend: BackendDocker, MaxMachines: 4,
		MaxCreatesInFlight: 1, IdleTimeout: Duration(15 * time.Minute), Enabled: true,
	}
	if err := s.CreateProvider(context.Background(), p); err != nil {
		t.Fatalf("CreateProvider: %v", err)
	}
	return p
}

// seedMachine writes a machine straight into a state, which is how a test
// reaches one without replaying the whole lifecycle to get there.
func seedMachine(t *testing.T, s *Store, providerID string, state MachineState) *Machine {
	t.Helper()
	m := &Machine{ProviderID: providerID, State: state}
	if err := s.CreateMachine(context.Background(), m); err != nil {
		t.Fatalf("CreateMachine in %s: %v", state, err)
	}
	return m
}

var everyMachineState = []MachineState{
	MachinePlanned, MachineCreating, MachineStarting, MachineBootstrapping,
	MachineEnrolling, MachineReady, MachineDraining, MachineDeleting,
	MachineDeleted, MachineFailed, MachineQuarantined,
}

// Every column of a machine has to survive a round trip. The driver binds
// positionally and ignores a surplus argument, so an argument without a
// placeholder shifts every later column onto its neighbour's value -- and on
// this row that means a machine coming back pointing at somebody else's
// resource. Comparing the whole struct is what keeps the two lists honest.
func TestAMachineComesBackAsItWasWritten(t *testing.T) {
	now := time.Date(2026, 9, 13, 8, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	p := seedProvider(t, s)

	stamp := func(offset time.Duration) *time.Time {
		t := now.Add(offset)
		return &t
	}
	want := &Machine{
		ProviderID: p.ID, Name: "zoomies-mach-abcdefghijklm", State: MachineReady,
		Message: "running", PoolID: pool.ID,
		OwnerControllerID: "ctl_a", OwnerFingerprint: "fingerprint",
		ResourceZone: "pve-1", ResourceID: "143",
		ResourceDetail: StringMap{"template": "9000"}, Address: "10.0.0.5",
		OwnershipVerifiedAt: stamp(time.Minute), OwnershipError: "",
		HostID: host.ID, JoinTokenID: "join_abc", Capacity: 2,
		Labels: StringMap{"zone": "lab"},
		OpID:   "mop_abcdefghijklm", OpKind: MachineOpBootstrap, OpHandle: "UPID:pve-1:1",
		OpHolder: "ctl_a", OpStartedAt: stamp(time.Minute), OpDeadlineAt: stamp(5 * time.Minute),
		OpOutcomeUnknown: true,
		Attempts:         2, NextAttemptAt: stamp(time.Hour),
		ProviderError: "the node was busy", BootstrapError: "the agent would not install",
		ReservationExpiresAt: stamp(2 * time.Hour), CreateStartedAt: stamp(time.Second),
		CreatedOKAt: stamp(2 * time.Second), StartedAt: stamp(3 * time.Second),
		BootstrappedAt: stamp(4 * time.Second), EnrolledAt: stamp(5 * time.Second),
		ReadyAt: stamp(6 * time.Second), IdleSince: stamp(7 * time.Second),
		DrainingAt: stamp(8 * time.Second), DeleteStartedAt: stamp(9 * time.Second),
		DeletedAt: stamp(10 * time.Second),
	}
	if err := s.CreateMachine(ctx, want); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}
	got, err := s.GetMachine(ctx, want.ID)
	if err != nil {
		t.Fatalf("GetMachine: %v", err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("the machine came back changed:\n got  %+v\n want %+v", got, want)
	}
}

// The allow-list lives in the store rather than in the reconciler so that a
// pass which has just lost a race, or a provider that answered oddly, cannot
// talk a machine into a state that makes the fleet's accounting wrong. This
// walks every pair, so a state added to the map without a thought about what
// may reach it fails here rather than in production.
func TestAMachineOnlyMovesThroughStatesItsLifecycleAllows(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)

	for _, from := range everyMachineState {
		for _, to := range everyMachineState {
			m := seedMachine(t, s, p.ID, from)
			got, err := s.TransitionMachine(ctx, m.ID, to, "")
			want := CanTransitionMachine(from, to)
			switch {
			case want && err != nil:
				t.Errorf("%s -> %s was refused: %v", from, to, err)
			case !want && !errors.Is(err, ErrInvalidTransition):
				t.Errorf("%s -> %s returned %v, want ErrInvalidTransition", from, to, err)
			case want && got.State != to:
				t.Errorf("%s -> %s left the machine in %s", from, to, got.State)
			}
		}
	}

	// A state nothing defines is refused before the row is read, so a typo in
	// a caller cannot write a value the CHECK constraint would then have to
	// catch.
	m := seedMachine(t, s, p.ID, MachineReady)
	if _, err := s.TransitionMachine(ctx, m.ID, MachineState("retired"), ""); !errors.Is(err, ErrInvalidTransition) {
		t.Errorf("transition to an invented state = %v, want ErrInvalidTransition", err)
	}
}

// A transition stamps the phase it enters, once. The machine page's timeline is
// derived from these stamps, so a stamp that moved every time a pass repeated
// itself would make the timeline say a machine had been created twice.
func TestEachPhaseIsStampedWhenItIsFirstEntered(t *testing.T) {
	now := time.Date(2026, 9, 13, 10, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachinePlanned)

	if _, err := s.TransitionMachine(ctx, m.ID, MachineCreating, "asking for a VM"); err != nil {
		t.Fatal(err)
	}
	first := now
	now = now.Add(time.Minute)
	// Repeating the state a machine is already in is legal and must change
	// nothing: a pass that reports "still creating" is not a second create.
	got, err := s.TransitionMachine(ctx, m.ID, MachineCreating, "")
	if err != nil {
		t.Fatal(err)
	}
	if got.CreateStartedAt == nil || !got.CreateStartedAt.Equal(first) {
		t.Fatalf("create_started_at = %v, want the first entry at %v", got.CreateStartedAt, first)
	}
	if got.Message != "asking for a VM" {
		t.Errorf("an empty message overwrote the one an operator can read: %q", got.Message)
	}

	// Draining is the exception: it can be cancelled and started again, and
	// the drain timeout has to count from the latest one.
	for _, to := range []MachineState{MachineBootstrapping, MachineEnrolling, MachineReady, MachineDraining} {
		if _, err := s.TransitionMachine(ctx, m.ID, to, ""); err != nil {
			t.Fatalf("%s: %v", to, err)
		}
	}
	now = now.Add(time.Hour)
	if _, err := s.TransitionMachine(ctx, m.ID, MachineReady, ""); err != nil {
		t.Fatal(err)
	}
	now = now.Add(time.Hour)
	again, err := s.TransitionMachine(ctx, m.ID, MachineDraining, "")
	if err != nil {
		t.Fatal(err)
	}
	if again.DrainingAt == nil || !again.DrainingAt.Equal(now) {
		t.Fatalf("draining_at = %v after a second drain, want %v: the drain timeout would count from the abandoned one", again.DrainingAt, now)
	}
	if again.ReadyAt == nil || !again.ReadyAt.After(first) {
		t.Fatalf("ready_at = %v, want the first time this machine was ready", again.ReadyAt)
	}
}

// deleted_at is what stops a machine counting against its provider's ceiling
// and against the bill. Only a provider that looked and could not find the
// resource may write it, so a state change -- which is only ever what this
// controller believes -- must not.
func TestAStateChangeNeverConfirmsADelete(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineDeleting)

	got, err := s.TransitionMachine(ctx, m.ID, MachineDeleted, "the delete call returned 200")
	if err != nil {
		t.Fatal(err)
	}
	if got.DeletedAt != nil {
		t.Fatal("moving to deleted stamped deleted_at; a 200 from a delete call is not a confirmation that the resource is gone")
	}
}

// "Counts against the ceiling" is defined twice: Machine.Owns for the
// reconciler's arithmetic, and the WHERE clause in CountOwnedMachines for the
// budget. Nothing held the two equal, so a machine that stopped counting in one
// and not the other would have a provider buying a machine it already pays for.
// This test is the equation -- live_rows_test.go's reason, one layer out.
func TestAMachineCountsAgainstItsProviderExactlyWhileItHasAResource(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	now := s.Now()

	owned := 0
	for _, state := range everyMachineState {
		for _, withResource := range []bool{false, true} {
			for _, confirmedGone := range []bool{false, true} {
				m := seedMachine(t, s, p.ID, state)
				if withResource {
					// The machine's own id stands in for a VM id; what matters
					// here is that each row names a different resource.
					if err := s.SetMachineResource(ctx, m.ID, "pve-1", m.ID, "fp", "ctl_1"); err != nil {
						t.Fatalf("SetMachineResource: %v", err)
					}
				}
				if confirmedGone {
					if _, err := s.ConfirmMachineDeleted(ctx, m.ID, now); err != nil {
						t.Fatalf("ConfirmMachineDeleted: %v", err)
					}
				}
				if withResource && !confirmedGone {
					owned++
				}
			}
		}
	}

	rows, _, err := s.ListMachines(ctx, MachineFilter{IncludeDeleted: true}, Page{Limit: 500})
	if err != nil {
		t.Fatalf("ListMachines: %v", err)
	}
	goSays := 0
	for _, m := range rows {
		if m.Owns() {
			goSays++
		}
	}
	sqlSays, err := s.CountOwnedMachines(ctx)
	if err != nil {
		t.Fatalf("CountOwnedMachines: %v", err)
	}
	if goSays != owned || sqlSays[p.ID] != owned {
		t.Fatalf("Owns() counts %d machines and CountOwnedMachines counts %d, with %d holding a resource: "+
			"the two halves of the ownership predicate disagree", goSays, sqlSays[p.ID], owned)
	}
	if owned == 0 || owned == len(rows) {
		t.Fatalf("%d of %d rows own a resource; the test needs both kinds to mean anything", owned, len(rows))
	}
}

// Two passes, or two controllers, reaching the same machine at once is the
// ordinary case on a fleet with a standby. The claim is one statement so that
// the decision is made inside the write: a read both of them could make first
// decides nothing, and two passes each believing they own a create is how one
// machine becomes two VMs.
func TestOnlyOnePassCanClaimAnOperation(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachinePlanned)
	now := s.Now()

	first, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_a", Timeout: 5 * time.Minute}, now)
	if err != nil {
		t.Fatalf("the first claim was refused: %v", err)
	}
	if first.OpID == "" || first.OpHolder != "ctl_a" {
		t.Fatalf("the claim did not record who holds it: %+v", first)
	}

	_, err = s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_b", Timeout: 5 * time.Minute}, now)
	if !errors.Is(err, ErrMachineBusy) {
		t.Fatalf("the second claim = %v, want ErrMachineBusy", err)
	}
	// The refusal names the holder, because the operator reading it wants to
	// know which controller to go and look at.
	if msg := err.Error(); !strings.Contains(msg, "ctl_a") {
		t.Errorf("the refusal does not name the controller holding the machine: %s", msg)
	}

	// And finishing it gives the claim back, so the next pass can take a step.
	if err := s.FinishMachineOperation(ctx, m.ID, first.OpID, MachineOpSucceeded, "created", nil); err != nil {
		t.Fatalf("FinishMachineOperation: %v", err)
	}
	if _, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpStart, Holder: "ctl_b", Timeout: time.Minute}, now); err != nil {
		t.Fatalf("claiming after a finished operation: %v", err)
	}
}

// A claim needs a deadline because a controller that dies mid-operation must
// not hold a machine for ever. An expired one is therefore takeable -- and
// taking it must leave every piece of evidence about the call that went out, or
// the pass taking over has nothing to ask the provider about.
func TestAnExpiredClaimIsTakeableAndTakingItMutatesNothing(t *testing.T) {
	now := time.Date(2026, 9, 13, 9, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineCreating)

	claimed, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_dead", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.SetMachineOperationHandle(ctx, m.ID, claimed.OpID, "UPID:pve-1:0000A1"); err != nil {
		t.Fatal(err)
	}
	if err := s.MarkMachineOutcomeUnknown(ctx, m.ID, claimed.OpID, "the request timed out after it went out"); err != nil {
		t.Fatal(err)
	}
	if err := s.SetMachineResource(ctx, m.ID, "pve-1", "143", "fp", "ctl_dead"); err != nil {
		t.Fatal(err)
	}

	// Still held while the deadline stands.
	now = now.Add(30 * time.Second)
	if _, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_live", Timeout: time.Minute}, now); !errors.Is(err, ErrMachineBusy) {
		t.Fatalf("a live claim was taken from its holder: %v", err)
	}

	now = now.Add(2 * time.Minute)
	taken, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_live", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatalf("an expired claim was not takeable, so the machine is stuck for ever: %v", err)
	}
	if taken.OpHolder != "ctl_live" {
		t.Errorf("op_holder = %q after the takeover, want ctl_live", taken.OpHolder)
	}
	if taken.OpHandle != "UPID:pve-1:0000A1" {
		t.Errorf("op_handle = %q; the takeover threw away the only evidence of what the dead controller's call did", taken.OpHandle)
	}
	if !taken.OpOutcomeUnknown {
		t.Error("the takeover cleared op_outcome_unknown, so the next pass would read silence as failure and create a second machine")
	}
	if taken.ResourceID != "143" || taken.ResourceZone != "pve-1" {
		t.Errorf("the takeover moved the machine's identity: %s on %s", taken.ResourceID, taken.ResourceZone)
	}
	if taken.State != MachineCreating {
		t.Errorf("state = %s after a takeover; a claim is not a lifecycle change", taken.State)
	}
}

// A machine has one resource for its whole life. A second identity would be a
// leak with a row pointing away from it: the first VM still exists, still
// costs money, and nothing left in the database names it.
func TestAMachineKeepsTheResourceItWasFirstGiven(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineCreating)

	if err := s.SetMachineResource(ctx, m.ID, "pve-1", "143", "fingerprint-1", "ctl_a"); err != nil {
		t.Fatalf("SetMachineResource: %v", err)
	}
	err := s.SetMachineResource(ctx, m.ID, "pve-2", "144", "fingerprint-2", "ctl_b")
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("a second resource = %v, want ErrConflict", err)
	}

	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.ResourceID != "143" || got.ResourceZone != "pve-1" || got.OwnerFingerprint != "fingerprint-1" {
		t.Fatalf("the refused write still changed the row: %s on %s, fingerprint %q",
			got.ResourceID, got.ResourceZone, got.OwnerFingerprint)
	}

	// Two machines cannot name one resource either, which is what the sweep
	// relies on when it asks whose a VM is.
	other := seedMachine(t, s, p.ID, MachineCreating)
	if err := s.SetMachineResource(ctx, other.ID, "pve-1", "143", "fingerprint-3", "ctl_a"); !errors.Is(err, ErrConflict) {
		t.Fatalf("a second machine took the same VM: %v", err)
	}
}

// The pass that stamps the confirmation is the one that publishes the deletion
// and frees the budget, so exactly one caller may stamp it however many
// controllers and retries arrive at the same answer at once.
func TestConfirmingADeleteStampsExactlyOnce(t *testing.T) {
	now := time.Date(2026, 9, 13, 11, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineDeleting)
	if err := s.SetMachineResource(ctx, m.ID, "pve-1", "143", "fp", "ctl_a"); err != nil {
		t.Fatal(err)
	}

	first, err := s.ConfirmMachineDeleted(ctx, m.ID, now)
	if err != nil || !first {
		t.Fatalf("ConfirmMachineDeleted = %v, %v; want the first confirmation to count", first, err)
	}
	later := now.Add(time.Hour)
	again, err := s.ConfirmMachineDeleted(ctx, m.ID, later)
	if err != nil {
		t.Fatal(err)
	}
	if again {
		t.Fatal("a second confirmation also counted, so the deletion would be published twice and the budget freed twice")
	}

	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.DeletedAt == nil || !got.DeletedAt.Equal(now) {
		t.Fatalf("deleted_at = %v, want the first confirmation at %v", got.DeletedAt, now)
	}
	if got.Owns() {
		t.Fatal("a machine whose resource is confirmed gone still counts against its provider")
	}
}

// A restored database is a copy: the machines it names may have been deleted,
// rebuilt or handed to somebody else since the backup was taken. Ownership is
// what a delete needs, so a restore takes the proof away and each machine has
// to earn it again before this copy may destroy anything.
func TestARestoredDatabaseMarksEveryMachineUnverified(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	now := s.Now()

	var ids []string
	for range 3 {
		m := seedMachine(t, s, p.ID, MachineReady)
		if err := s.SetMachineOwnershipVerified(ctx, m.ID, now); err != nil {
			t.Fatal(err)
		}
		ids = append(ids, m.ID)
	}
	untouched := seedMachine(t, s, p.ID, MachinePlanned)

	n, err := s.MarkMachinesUnverified(ctx)
	if err != nil {
		t.Fatalf("MarkMachinesUnverified: %v", err)
	}
	if n != 3 {
		t.Fatalf("MarkMachinesUnverified = %d, want the 3 machines that had a proof", n)
	}
	for _, id := range ids {
		got, err := s.GetMachine(ctx, id)
		if err != nil {
			t.Fatal(err)
		}
		if got.OwnershipVerifiedAt != nil {
			t.Fatalf("machine %s kept its proof of ownership across a restore", id)
		}
		if got.State != MachineReady {
			t.Fatalf("machine %s was moved out of its state by the restore: %s", id, got.State)
		}
	}
	if got, err := s.GetMachine(ctx, untouched.ID); err != nil || got.OwnershipVerifiedAt != nil {
		t.Fatalf("the machine that never had a proof was changed: %v, %v", got, err)
	}
}

// An observation that failed takes the last good one with it. Leaving
// yesterday's stamp behind would let a check that has since gone wrong keep
// authorising deletions, which is the whole thing ownership exists to stop.
func TestAFailedOwnershipCheckTakesTheProofWithIt(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineReady)

	if err := s.SetMachineOwnershipVerified(ctx, m.ID, s.Now()); err != nil {
		t.Fatal(err)
	}
	if err := s.SetMachineOwnershipError(ctx, m.ID, "VM 143 says it belongs to machine mach_91c"); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.OwnershipVerifiedAt != nil {
		t.Fatal("a failed ownership check left the previous proof standing")
	}
	if got.OwnershipError == "" {
		t.Fatal("nothing records what disagreed, so nobody can act on it")
	}

	// And a later check that agrees settles the complaint.
	if err := s.SetMachineOwnershipVerified(ctx, m.ID, s.Now()); err != nil {
		t.Fatal(err)
	}
	if got, err = s.GetMachine(ctx, m.ID); err != nil || got.OwnershipError != "" {
		t.Fatalf("a successful check left the old complaint behind: %q, %v", got.OwnershipError, err)
	}
}

// The two error columns belong to two independent systems: a hypervisor that
// would not answer, and an agent install inside the guest that failed. A
// success on one must not erase the other's complaint, which is the rule 0022
// wrote down for runner cleanup.
func TestAProviderSuccessDoesNotSettleTheGuestsComplaint(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineBootstrapping)
	now := s.Now()

	if err := s.RecordMachineFailure(ctx, m.ID, MachineErrorBootstrap, "the agent would not install", now.Add(time.Minute)); err != nil {
		t.Fatal(err)
	}
	if err := s.RecordMachineFailure(ctx, m.ID, MachineErrorProvider, "the node was unreachable", now.Add(time.Minute)); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Attempts != 2 || got.NextAttemptAt == nil {
		t.Fatalf("attempts = %d, next attempt = %v; the backoff has nothing to count from", got.Attempts, got.NextAttemptAt)
	}

	claimed, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpBootstrap, Holder: "ctl_a", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.FinishMachineOperation(ctx, m.ID, claimed.OpID, MachineOpSucceeded, "", nil); err != nil {
		t.Fatal(err)
	}
	got, err = s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.ProviderError != "" || got.Attempts != 0 || got.NextAttemptAt != nil {
		t.Fatalf("a success left the provider's complaint or its backoff behind: %q, %d attempts, next %v",
			got.ProviderError, got.Attempts, got.NextAttemptAt)
	}
	if got.BootstrapError == "" {
		t.Fatal("a reachable hypervisor settled a complaint about the guest, which nothing has fixed")
	}
}

// Giving a claim back because a guard refused, or because the controller is
// stopping, is not the machine's fault. Counting it as an attempt would walk
// the backoff up towards giving up on a machine nothing has gone wrong with.
func TestReleasingAClaimDoesNotCountAnAttempt(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachinePlanned)
	now := s.Now()

	claimed, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_a", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.FinishMachineOperation(ctx, m.ID, claimed.OpID, MachineOpReleased, "", nil); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Attempts != 0 {
		t.Fatalf("attempts = %d after a released claim, want 0", got.Attempts)
	}
	if got.OpID != "" || got.OpKind != MachineOpNone {
		t.Fatalf("the claim was not given back: %q %q", got.OpID, got.OpKind)
	}

	// A failure is the other half of the same writer, and does count.
	again, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_a", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatal(err)
	}
	retry := now.Add(30 * time.Second)
	if err := s.FinishMachineOperation(ctx, m.ID, again.OpID, MachineOpFailed, "the clone failed", &retry); err != nil {
		t.Fatal(err)
	}
	if got, err = s.GetMachine(ctx, m.ID); err != nil {
		t.Fatal(err)
	} else if got.Attempts != 1 || got.ProviderError != "the clone failed" {
		t.Fatalf("a failed operation recorded %d attempts and %q", got.Attempts, got.ProviderError)
	}
}

// A pass whose claim expired and was taken by somebody else must not be able to
// finish the operation it no longer holds: the controller that took it over is
// the one that will answer for it.
func TestAPassThatLostItsClaimCannotFinishTheOperation(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineCreating)
	now := s.Now()

	first, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_a", Timeout: time.Minute}, now)
	if err != nil {
		t.Fatal(err)
	}
	taken, err := s.ClaimMachineOperation(ctx, m.ID,
		MachineOperation{Kind: MachineOpCreate, Holder: "ctl_b", Timeout: time.Minute}, now.Add(2*time.Minute))
	if err != nil {
		t.Fatal(err)
	}
	if err := s.FinishMachineOperation(ctx, m.ID, first.OpID, MachineOpFailed, "gave up", nil); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetMachine(ctx, m.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.OpID != taken.OpID || got.OpHolder != "ctl_b" {
		t.Fatalf("the previous holder finished an operation it had lost: op %q held by %q", got.OpID, got.OpHolder)
	}
	if got.Attempts != 0 {
		t.Fatalf("attempts = %d; the lost pass counted an attempt against somebody else's operation", got.Attempts)
	}
}

// host_id is the only thing that grants this controller deletion authority over
// a host, so it is written once, by the redemption of a token this machine
// minted, and never moved.
func TestAMachineIsEnrolledAsExactlyOneHost(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, _, host := seedPool(t, s)
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineEnrolling)
	now := s.Now()

	if err := s.LinkMachineHost(ctx, m.ID, host.ID, "join_abc", now); err != nil {
		t.Fatalf("LinkMachineHost: %v", err)
	}
	other := &Host{Name: "vm-2", Capacity: 2}
	if err := s.CreateHost(ctx, other); err != nil {
		t.Fatal(err)
	}
	if err := s.LinkMachineHost(ctx, m.ID, other.ID, "join_def", now); !errors.Is(err, ErrConflict) {
		t.Fatalf("re-linking a machine = %v, want ErrConflict", err)
	}

	// And two machines cannot claim one host, which is what stops a second row
	// acquiring authority over a host somebody already enrolled.
	second := seedMachine(t, s, p.ID, MachineEnrolling)
	if err := s.LinkMachineHost(ctx, second.ID, host.ID, "join_ghi", now); !errors.Is(err, ErrConflict) {
		t.Fatalf("two machines claimed one host: %v", err)
	}

	got, err := s.GetMachineByHost(ctx, host.ID)
	if err != nil {
		t.Fatalf("GetMachineByHost: %v", err)
	}
	if got.ID != m.ID || got.JoinTokenID != "join_abc" || got.EnrolledAt == nil {
		t.Fatalf("the enrolment link does not name the token that made it: %+v", got)
	}
}

// A machine name is what a sweep matches on a hypervisor an operator also runs
// their own guests on. Mistaking somebody else's VM for one of ours deletes
// something nobody asked us to touch, so the brand is not decoration.
func TestAMachineNameSaysWhichFleetRentedIt(t *testing.T) {
	s := newTestStore(t)
	m := seedMachine(t, s, seedProvider(t, s).ID, MachinePlanned)

	if !IsMachineName(m.Name) {
		t.Fatalf("CreateMachine named a machine %q, which IsMachineName does not recognise", m.Name)
	}
	for _, name := range []string{"debian-12", "zoomies", "zoomies-linux-x64-corgi-abcdefgh", "", "mach_abc"} {
		if IsMachineName(name) {
			t.Errorf("IsMachineName(%q) = true, so a sweep would treat it as ours", name)
		}
	}
}

// A machine still carrying a resource is never pruned however old it is: the
// row is the only record that something was rented and may still be running,
// and deleting it is how a fleet loses a VM it is still paying for.
func TestPruningKeepsEveryMachineThatMayStillExist(t *testing.T) {
	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	s := newTestStoreAt(t, func() time.Time { return now })
	ctx := context.Background()
	p := seedProvider(t, s)

	gone := seedMachine(t, s, p.ID, MachineDeleting)
	if err := s.SetMachineResource(ctx, gone.ID, "pve-1", "143", "fp", "ctl_a"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ConfirmMachineDeleted(ctx, gone.ID, now); err != nil {
		t.Fatal(err)
	}
	if _, err := s.TransitionMachine(ctx, gone.ID, MachineDeleted, ""); err != nil {
		t.Fatal(err)
	}
	neverBuilt := seedMachine(t, s, p.ID, MachineFailed)
	stillOut := seedMachine(t, s, p.ID, MachineFailed)
	if err := s.SetMachineResource(ctx, stillOut.ID, "pve-1", "144", "fp", "ctl_a"); err != nil {
		t.Fatal(err)
	}
	live := seedMachine(t, s, p.ID, MachineReady)

	n, ids, err := s.PruneMachines(ctx, now.Add(time.Hour))
	if err != nil {
		t.Fatalf("PruneMachines: %v", err)
	}
	if n != 2 || len(ids) != 2 {
		t.Fatalf("PruneMachines removed %d rows (%v), want the confirmed-deleted one and the one that never existed", n, ids)
	}
	for _, id := range []string{gone.ID, neverBuilt.ID} {
		if !contains(ids, id) {
			t.Errorf("%s was kept, though nothing of it exists", id)
		}
	}
	for _, id := range []string{stillOut.ID, live.ID} {
		if _, err := s.GetMachine(ctx, id); err != nil {
			t.Errorf("%s was pruned while its resource may still exist: %v", id, err)
		}
	}
}

// The recovery cursor is a keyset rather than an offset, so one machine stuck
// behind an unreachable node cannot starve the rest of the queue.
func TestPendingWorkPagesPastTheMachinesItHasAlreadySeen(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)

	want := map[string]bool{}
	for range 5 {
		want[seedMachine(t, s, p.ID, MachineCreating).ID] = true
	}
	settled := seedMachine(t, s, p.ID, MachineDeleting)
	if _, err := s.TransitionMachine(ctx, settled.ID, MachineDeleted, ""); err != nil {
		t.Fatal(err)
	}

	seen := map[string]int{}
	cursor := ""
	for range 10 {
		page, err := s.PendingMachineWork(ctx, cursor, 2)
		if err != nil {
			t.Fatalf("PendingMachineWork: %v", err)
		}
		if len(page) == 0 {
			break
		}
		for _, m := range page {
			seen[m.ID]++
			cursor = m.ID
		}
	}
	for id := range want {
		if seen[id] != 1 {
			t.Errorf("machine %s was served %d times, want once", id, seen[id])
		}
	}
	if seen[settled.ID] != 0 {
		t.Errorf("a machine whose life is over is still offered as work")
	}
}

// A token minted for one machine travels inside a guest, where it is readable
// by more people than one an operator pastes into a terminal. Recording which
// machine it belongs to is what a later slice checks the redemption against.
func TestAJoinTokenRemembersTheMachineItWasMintedFor(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	p := seedProvider(t, s)
	m := seedMachine(t, s, p.ID, MachineBootstrapping)

	tok := &JoinToken{
		TokenHash: "hash", Prefix: "zjt_", Capacity: 2,
		ExpiresAt: s.Now().Add(time.Hour), MachineID: m.ID, ExpectedName: m.Name,
	}
	if err := s.CreateJoinToken(ctx, tok); err != nil {
		t.Fatalf("CreateJoinToken: %v", err)
	}
	got, err := s.GetJoinToken(ctx, tok.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.MachineID != m.ID || got.ExpectedName != m.Name {
		t.Fatalf("the token came back scoped to %q/%q, want %q/%q", got.MachineID, got.ExpectedName, m.ID, m.Name)
	}

	// A token an operator asked for by hand carries neither, and still works.
	plain := &JoinToken{TokenHash: "hash-2", Prefix: "zjt_", ExpiresAt: s.Now().Add(time.Hour)}
	if err := s.CreateJoinToken(ctx, plain); err != nil {
		t.Fatal(err)
	}
	if got, err = s.GetJoinToken(ctx, plain.ID); err != nil || got.MachineID != "" {
		t.Fatalf("an unscoped join token came back scoped to %q: %v", got.MachineID, err)
	}
}

// A forced host delete that forgets the machine behind it has to be one
// transaction. Done as two writes, a failure or a cancelled request between them
// leaves the machine row gone and the host standing: the VM is still billed and
// nothing records that it exists.
func TestDeletingAHostForgetsItsMachineOnlyWhenTheHostGoesToo(t *testing.T) {
	ctx := context.Background()
	s := newTestStore(t)
	_, _, host := seedPool(t, s)
	prov := seedProvider(t, s)
	m := &Machine{ProviderID: prov.ID, State: MachineReady, HostID: host.ID}
	if err := s.CreateMachine(ctx, m); err != nil {
		t.Fatalf("CreateMachine: %v", err)
	}

	// The host is not there to delete, so the machine must not be forgotten
	// either.
	if _, err := s.DeleteHostForgettingMachine(ctx, "host_missing", m.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleting a missing host = %v, want ErrNotFound", err)
	}
	if _, err := s.GetMachine(ctx, m.ID); err != nil {
		t.Fatalf("the machine was forgotten although the host delete failed: %v", err)
	}

	if _, err := s.DeleteHostForgettingMachine(ctx, host.ID, m.ID); err != nil {
		t.Fatalf("DeleteHostForgettingMachine: %v", err)
	}
	if _, err := s.GetHost(ctx, host.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("the host survived: %v", err)
	}
	if _, err := s.GetMachine(ctx, m.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("the machine survived its host: %v", err)
	}
}

ALTER TABLE runners ADD COLUMN image_pull_ms INTEGER;
ALTER TABLE runners ADD COLUMN container_started_at INTEGER;
ALTER TABLE runners ADD COLUMN registered_at INTEGER;

ALTER TABLE pools ADD COLUMN pull_policy TEXT NOT NULL DEFAULT 'if-not-present'
  CHECK (pull_policy IN ('if-not-present','always','pinned-only'));
ALTER TABLE runners ADD COLUMN image_digest TEXT NOT NULL DEFAULT '';

CREATE TABLE pool_prewarms (
  pool_id TEXT NOT NULL REFERENCES pools(id) ON DELETE CASCADE,
  host_id TEXT NOT NULL REFERENCES hosts(id) ON DELETE CASCADE,
  image TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('pending','succeeded','failed')),
  digest TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL,
  PRIMARY KEY(pool_id, host_id)
);

-- Optional accounting metadata and a fair-share guard for repositories.
ALTER TABLE pools ADD COLUMN repository_concurrency_limit INTEGER NOT NULL DEFAULT 0
    CHECK (repository_concurrency_limit >= 0);
ALTER TABLE pools ADD COLUMN cost_per_runner_hour REAL
    CHECK (cost_per_runner_hour IS NULL OR cost_per_runner_hour >= 0);

-- What GitHub says about a job beyond its state: the branch and attempt it ran
-- for, and the steps it ran, so a failed job can say which step failed without
-- the operator leaving for GitHub.
ALTER TABLE jobs ADD COLUMN head_branch TEXT NOT NULL DEFAULT '';
ALTER TABLE jobs ADD COLUMN head_sha    TEXT NOT NULL DEFAULT '';
ALTER TABLE jobs ADD COLUMN run_attempt INTEGER NOT NULL DEFAULT 0;
ALTER TABLE jobs ADD COLUMN steps       TEXT NOT NULL DEFAULT '[]';

-- The fleet's own side of a failure: what the runner executing this job said
-- when it stopped before GitHub reported the job over. GitHub will call such a
-- job "failure" like any other; this column is what tells the two apart.
ALTER TABLE jobs ADD COLUMN runner_fault TEXT NOT NULL DEFAULT '';

-- One row per thing Zoomies observed or did about a job, in the order it
-- happened. The jobs row holds the current truth; this holds how it got there.
CREATE TABLE job_events (
    id          TEXT PRIMARY KEY,
    job_id      TEXT NOT NULL,
    at          INTEGER NOT NULL,
    kind        TEXT NOT NULL,
    source      TEXT NOT NULL DEFAULT '',
    message     TEXT NOT NULL DEFAULT '',
    runner_id   TEXT NOT NULL DEFAULT '',
    runner_name TEXT NOT NULL DEFAULT ''
);
CREATE INDEX idx_job_events_job ON job_events(job_id, at);

-- Platform: what a pool's runners are, and what a host actually is.
--
-- Before this, a pool said which backend it wanted and nothing about the
-- machine underneath, so the scheduler could put a Debian-image runner on a
-- macOS host and only the job's failure would say so. These columns are what
-- the placement rule and the pool's default image both read.
--
-- Every column is nullable-by-default-empty, so an existing fleet keeps
-- working unchanged: an empty platform means "makes no promise", which is
-- exactly the behaviour those pools have today.

ALTER TABLE pools ADD COLUMN os         TEXT NOT NULL DEFAULT '';
ALTER TABLE pools ADD COLUMN os_version TEXT NOT NULL DEFAULT '';
ALTER TABLE pools ADD COLUMN arch       TEXT NOT NULL DEFAULT '';

-- Hosts already reported os (the kernel) and arch. distro and os_version are
-- what tell an Ubuntu 22.04 machine from a Debian 12 one -- "linux" cannot
-- pick a runner image -- and cpus/memory are what make a host's name and the
-- Hosts page say how much machine it is.
ALTER TABLE hosts ADD COLUMN distro     TEXT    NOT NULL DEFAULT '';
ALTER TABLE hosts ADD COLUMN os_version TEXT    NOT NULL DEFAULT '';
ALTER TABLE hosts ADD COLUMN cpus       INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hosts ADD COLUMN memory_mb  INTEGER NOT NULL DEFAULT 0;

-- What a host has, and what its operator has set aside.
--
-- Two different kinds of number live here, which is why they are separate
-- columns rather than one. The disk figures are observations: the agent
-- measures the filesystem its work directory sits on and reports them, and a
-- host resized or filled up says so on its next heartbeat. The reserves are
-- the operator's, like capacity is today -- what to hold back from placement
-- for the machine's own sake -- and nothing an agent sends may write them.
ALTER TABLE hosts ADD COLUMN disk_total_mb INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hosts ADD COLUMN disk_free_mb INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hosts ADD COLUMN reserve_cpus INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hosts ADD COLUMN reserve_memory_mb INTEGER NOT NULL DEFAULT 0;
ALTER TABLE hosts ADD COLUMN reserve_disk_mb INTEGER NOT NULL DEFAULT 0;

-- A lifecycle retry must not overwrite the first create delivered to a host.
ALTER TABLE runners ADD COLUMN create_task_issued_at INTEGER;
ALTER TABLE runners ADD COLUMN host_removed_at INTEGER;

-- Earlier cleanup stamps represented the first success signal, not confirmed
-- removal on both sides. Keep them as historical estimates, never as proof.
ALTER TABLE runners ADD COLUMN cleanup_estimated_at INTEGER;
UPDATE runners SET cleanup_estimated_at=cleaned_up_at, cleaned_up_at=NULL;

-- A deployment review still held by GitHub is not eligible for placement.
UPDATE jobs SET eligible_at=NULL WHERE state='waiting';

-- Recover unfinished host removals without repeatedly scanning runner history
-- or all jobs on busy fleets.
CREATE INDEX idx_runners_pending_host_cleanup ON runners(id)
    WHERE state IN ('removed', 'failed') AND host_removed_at IS NULL;
CREATE INDEX idx_jobs_runner_state ON jobs(runner_id, state);

-- One observation per pool/minute, recording whether placement hit host capacity.
-- Deliberately no FK: history remains meaningful after a pool is deleted.
CREATE TABLE usage_capacity_samples (
    pool_id TEXT NOT NULL,
    at INTEGER NOT NULL,
    blocked INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (pool_id, at)
);
CREATE INDEX idx_usage_capacity_at ON usage_capacity_samples(at);

ALTER TABLE jobs ADD COLUMN provisioning TEXT NOT NULL DEFAULT '' CHECK (provisioning IN ('', 'paused', 'deleted'));
ALTER TABLE jobs ADD COLUMN provision_now INTEGER NOT NULL DEFAULT 0 CHECK (provision_now IN (0,1));
CREATE INDEX jobs_provisioning_queue ON jobs(state, provisioning, provision_now, queued_at, id);
CREATE INDEX runners_provisioning_order ON runners(pool_id, created_at);

-- Measurements expire independently of agent connectivity. Existing hosts
-- keep reservation-based placement until their agents report usage.
ALTER TABLE hosts ADD COLUMN usage TEXT NOT NULL DEFAULT '{}';

CREATE TABLE user_preferences (
    user_id     TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    preferences TEXT    NOT NULL DEFAULT '{}',
    updated_at  INTEGER NOT NULL
);

-- Optional GitHub lookups are durable work, never part of an ingestion ACK.
CREATE TABLE control_enrichment (
 kind TEXT NOT NULL,
 target TEXT NOT NULL,
 generation INTEGER NOT NULL DEFAULT 1,
 next_attempt INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY (kind, target)
);
CREATE INDEX control_enrichment_due ON control_enrichment(next_attempt);

-- Which release ran a job, so that build times and stability can be compared
-- across releases.
--
-- The four columns are stamped once, when the controller claims a job or a
-- runner picks it up, and never rewritten: a job's numbers belong to the build
-- that produced them, and a later update from GitHub says nothing about it.
-- They are NULL on every job recorded before this migration, on purpose. The
-- release that was running at the time is not something a timestamp can
-- recover, and a guess would put a job under a release it never saw.
--
-- controller_version and controller_channel are the running controller's build
-- (version.Version and its install channel). agent_version is what the host
-- reported on its last heartbeat before the job was assigned to it, and
-- host_id is that host. Each is stamped independently, because a job is
-- claimed before it has a host.
ALTER TABLE jobs ADD COLUMN controller_version TEXT;
ALTER TABLE jobs ADD COLUMN controller_channel TEXT;
ALTER TABLE jobs ADD COLUMN agent_version TEXT;
ALTER TABLE jobs ADD COLUMN host_id TEXT;

-- The job statistics group a bounded window of jobs by release, and by job
-- name. Each index leads with the column the window is cut on, so the query
-- reads the window rather than the table.
CREATE INDEX idx_jobs_queued_version ON jobs(queued_at, controller_version);
CREATE INDEX idx_jobs_name_queued ON jobs(job_name, queued_at);

-- The same three facts in the usage ledger, copied from the job when the
-- runner's session is written, so a release comparison outlives
-- retention.jobs the way the runner-hours do. host_id is already there.
ALTER TABLE runner_sessions ADD COLUMN controller_version TEXT;
ALTER TABLE runner_sessions ADD COLUMN controller_channel TEXT;
ALTER TABLE runner_sessions ADD COLUMN agent_version TEXT;

-- An installation owner may enable AI Context for that installation's
-- repositories without being a fleet administrator. Ownership grants no source
-- access: readers and connection consent stay explicit and separate.
CREATE TABLE ai_context_installation_owners (
    installation_id TEXT NOT NULL REFERENCES installations(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (installation_id, user_id)
);
CREATE INDEX idx_ai_context_owner_user ON ai_context_installation_owners(user_id);

-- The IDs of GitHub Actions OIDC tokens already used for a Zoomies-only
-- upload. A token is valid for minutes and an upload is not idempotent, so
-- each ID is admitted once; rows are pruned after the token has expired.
CREATE TABLE ai_context_upload_tokens (
    token_id TEXT PRIMARY KEY,
    repository_id TEXT NOT NULL REFERENCES ai_context_repositories(id) ON DELETE CASCADE,
    expires_at INTEGER NOT NULL
);
CREATE INDEX idx_ai_context_upload_tokens_expiry ON ai_context_upload_tokens(expires_at);

package store

import (
	"context"
	"database/sql"
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// atSchemaBefore builds a database carrying every migration up to but not
// including the named one.
//
// It names the migration rather than counting back from the end, because
// counting drifts. These fixtures were written as len(migs)-2 when 0045 was
// the last one; adding 0046 silently re-pointed all three at a different
// upgrade, and the tests went on running under their old names against a
// database one migration further forward than they describe. Naming it means
// the next migration added moves nothing.
func atSchemaBefore(t *testing.T, name string) string {
	t.Helper()
	migs, err := loadMigrations()
	if err != nil {
		t.Fatalf("loadMigrations: %v", err)
	}
	for i, m := range migs {
		if m.name == name {
			return atSchema(t, i)
		}
	}
	t.Fatalf("no migration called %s, so this fixture is describing an upgrade that does not exist", name)
	return ""
}

// atSchema builds a database carrying only the first n migrations, which is
// what a release older than this one left behind.
//
// It applies the real embedded SQL rather than a hand-written schema dump: a
// fixture written by hand drifts from what the migrations actually produce,
// and then the upgrade it is testing is an upgrade from a database that never
// existed.
func atSchema(t *testing.T, n int) string {
	t.Helper()
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")

	migs, err := loadMigrations()
	if err != nil {
		t.Fatalf("loadMigrations: %v", err)
	}
	if n > len(migs) {
		t.Fatalf("this build has %d migrations, so it cannot be rolled back to %d", len(migs), n)
	}

	// Applied straight onto the file rather than through Open, which would
	// migrate to head on the way past. Trimming the ledger afterwards was the
	// first attempt and is wrong: it leaves the columns the later migrations
	// added, so re-applying them fails on a duplicate and the fixture is a
	// database that never existed.
	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatalf("sql.Open: %v", err)
	}
	defer db.Close()
	if _, err := db.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)`); err != nil {
		t.Fatalf("creating the ledger: %v", err)
	}
	for _, m := range migs[:n] {
		if _, err := db.ExecContext(ctx, m.sql); err != nil {
			t.Fatalf("applying %s: %v", m.name, err)
		}
		if _, err := db.ExecContext(ctx,
			`INSERT INTO schema_migrations (name, applied_at) VALUES (?, 0)`, m.name); err != nil {
			t.Fatalf("recording %s: %v", m.name, err)
		}
	}
	if err := db.Close(); err != nil {
		t.Fatalf("closing the fixture: %v", err)
	}
	return path
}

// A database from an older release has to open on this binary and come out at
// head. It is the upgrade every operator does, and until now nothing ran it.
//
// v0.1-alpha shipped one migration and v0.2-beta ten, so both are real points
// somebody's database is sitting at right now.
func TestADatabaseFromAnOlderReleaseMigratesToHead(t *testing.T) {
	ctx := context.Background()
	for _, tc := range []struct {
		name string
		at   int
	}{
		{"v0.1-alpha, which shipped 0001_init.sql alone", 1},
		{"v0.2-beta, which shipped through 0010", 10},
	} {
		t.Run(tc.name, func(t *testing.T) {
			path := atSchema(t, tc.at)

			s, err := Open(ctx, Options{Path: path})
			if err != nil {
				t.Fatalf("opening a %s database: %v", tc.name, err)
			}
			defer s.Close()

			applied, err := s.AppliedMigrations(ctx)
			if err != nil {
				t.Fatal(err)
			}
			migs, err := loadMigrations()
			if err != nil {
				t.Fatal(err)
			}
			if len(applied) != len(migs) {
				t.Fatalf("the ledger has %d migrations after the upgrade, want %d", len(applied), len(migs))
			}
			if err := s.IntegrityCheck(ctx); err != nil {
				t.Errorf("the upgraded database does not pass its integrity check: %v", err)
			}

			// And it is a working fleet database, not just a schema: the
			// columns the later migrations added are readable and writable.
			inst := &Installation{AppID: 1, InstallationID: 2, Target: "acme", TargetType: TargetOrg}
			if err := s.CreateInstallation(ctx, inst); err != nil {
				t.Fatalf("the upgraded database will not take an installation: %v", err)
			}
			if _, err := s.GetInstallation(ctx, inst.ID); err != nil {
				t.Fatalf("reading it back: %v", err)
			}
		})
	}
}

// The providers migration is the first one to add a column to a table that
// already has rows in a real fleet's database, and the first to add tables that
// point at two of them. An upgrade that left an existing join token unreadable
// -- because a NOT NULL column arrived without a default -- would take every
// agent enrolment with it, and the failure would arrive at the worst moment:
// after the upgrade, on a fleet that was working.
func TestADatabaseWithRowsInItStillTakesTheProviderTables(t *testing.T) {
	ctx := context.Background()
	path := atSchema(t, len(shippedMigrations)-1)

	// A join token written by the older release, with none of the columns the
	// upgrade is about to add.
	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.ExecContext(ctx, `INSERT INTO join_tokens
		(id, token_hash, prefix, created_by, labels, capacity, created_at, expires_at, used_by_id)
		VALUES ('join_old', 'hash', 'zjt_', 'alice', '{}', 2, 1, 9999999999999, '')`); err != nil {
		t.Fatalf("planting a join token at the old schema: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("opening a database from the release before providers: %v", err)
	}
	defer s.Close()

	tokens, err := s.ListJoinTokens(ctx)
	if err != nil {
		t.Fatalf("reading a join token written before the upgrade: %v", err)
	}
	if len(tokens) != 1 || tokens[0].MachineID != "" || tokens[0].ExpectedName != "" {
		t.Fatalf("the pre-upgrade join token came back as %+v, want it unscoped and readable", tokens)
	}

	// And the new tables work on an upgraded database, not only on one this
	// build created from nothing.
	p := &Provider{Kind: ProviderFake, Name: "lab", MaxMachines: 2}
	if err := s.CreateProvider(ctx, p); err != nil {
		t.Fatalf("the upgraded database will not take a provider: %v", err)
	}
	m := &Machine{ProviderID: p.ID}
	if err := s.CreateMachine(ctx, m); err != nil {
		t.Fatalf("the upgraded database will not take a machine: %v", err)
	}
	if _, err := s.GetMachine(ctx, m.ID); err != nil {
		t.Fatalf("reading it back: %v", err)
	}
	if err := s.IntegrityCheck(ctx); err != nil {
		t.Errorf("the upgraded database does not pass its integrity check: %v", err)
	}
}

// A migration that fails has to stop startup and leave the ledger clean, so
// the next start tries it again. The failure mode this prevents is the worst
// one available: a half-applied migration recorded as done, which nothing will
// ever try again and which no later migration can assume the shape of.
func TestAFailingMigrationStopsStartupAndIsTriedAgain(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()

	broken := []migration{
		{name: "9001_first_half_works.sql", sql: `CREATE TABLE half_applied (id TEXT PRIMARY KEY)`},
		{name: "9002_this_one_does_not.sql", sql: `CREATE TABLE nope (id TEXT PRIMARY KEY); THIS IS NOT SQL`},
	}
	err = s.applyMigrations(ctx, broken, map[string]bool{})
	if err == nil {
		t.Fatal("a migration full of nonsense was applied without complaint")
	}
	// Naming the file is the difference between "the database will not open"
	// and knowing which change to look at.
	if !strings.Contains(err.Error(), "9002_this_one_does_not.sql") {
		t.Errorf("the failure does not name the migration: %v", err)
	}

	applied, err := s.AppliedMigrations(ctx)
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, a := range applied {
		names = append(names, a.Name)
	}
	// The one that worked is recorded and the one that failed is not: each
	// migration is its own transaction, so a failure costs only itself.
	if !contains(names, "9001_first_half_works.sql") {
		t.Errorf("the migration that succeeded was rolled back too: %v", names)
	}
	if contains(names, "9002_this_one_does_not.sql") {
		t.Fatalf("the failed migration is in the ledger, so it will never be tried again: %v", names)
	}

	// Fixed and re-run: it applies, and the one before it is not applied twice.
	fixed := []migration{
		broken[0],
		{name: "9002_this_one_does_not.sql", sql: `CREATE TABLE now_it_works (id TEXT PRIMARY KEY)`},
	}
	seen := map[string]bool{"9001_first_half_works.sql": true}
	if err := s.applyMigrations(ctx, fixed, seen); err != nil {
		t.Fatalf("the fixed migration did not apply on the re-run: %v", err)
	}
	if _, err := s.exec(ctx, `INSERT INTO now_it_works (id) VALUES ('x')`); err != nil {
		t.Errorf("the re-run did not actually create the table: %v", err)
	}
}

// A store that could not be opened must not be left half-built: Open closes
// both pools itself, so a caller that got an error has nothing to clean up and
// no file handle leaks into the next attempt.
func TestAFailedOpenLeavesNothingBehind(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.exec(ctx, `INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)`,
		"9999_from_the_future.sql", ms(s.Now())); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	bad, err := Open(ctx, Options{Path: path})
	if !errors.Is(err, ErrSchemaNewer) {
		t.Fatalf("Open = %v, want ErrSchemaNewer", err)
	}
	if bad != nil {
		t.Error("Open returned a store alongside its error, which a caller will not close")
	}
}

func contains(haystack []string, needle string) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

// preMigrationCopies lists the backups this package took before migrating.
func preMigrationCopies(t *testing.T, dbPath string) []string {
	t.Helper()
	entries, err := os.ReadDir(filepath.Join(filepath.Dir(dbPath), PreMigrationDir))
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		t.Fatalf("reading the pre-migration directory: %v", err)
	}
	var out []string
	for _, e := range entries {
		// Only the ones this package names: anything else in there is
		// somebody's, and counting it would make the retention assertion
		// below pass or fail on a directory retention never touches.
		if e.IsDir() && strings.HasPrefix(e.Name(), BackupDirPrefix) {
			out = append(out, e.Name())
		}
	}
	sort.Strings(out)
	return out
}

// Migrations are one-way and the binary that wrote a database refuses to open
// it once a newer one has moved it on. So the moment before a migration is
// when a rollback is most likely to be wanted and least likely to have been
// prepared for -- an operator upgrading is not thinking about backups.
func TestUpgradingCopiesTheDatabaseFirst(t *testing.T) {
	ctx := context.Background()
	path := atSchema(t, 1)

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()

	copies := preMigrationCopies(t, path)
	if len(copies) != 1 {
		t.Fatalf("the upgrade left %v pre-migration copies, want one", copies)
	}

	// It is a real database, and the layout `zoomies restore` takes: a copy
	// nobody can put back without knowing it is special is not a rollback.
	dir := filepath.Join(filepath.Dir(path), PreMigrationDir, copies[0])
	old, err := Open(ctx, Options{Path: filepath.Join(dir, BackupDBName), ReadOnly: true})
	if err != nil {
		t.Fatalf("the copy does not open: %v", err)
	}
	defer old.Close()
	if err := old.IntegrityCheck(ctx); err != nil {
		t.Errorf("the copy does not pass its integrity check: %v", err)
	}
	// And it is the database as it was *before* the upgrade, which is the
	// whole point: one migration, not the whole ledger.
	applied, err := old.AppliedMigrations(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(applied) != 1 {
		t.Errorf("the copy has %d migrations; it was taken after the upgrade, not before it", len(applied))
	}
}

// A fresh install has no rows to lose, and putting an empty copy beside every
// one of them would teach operators that the directory is noise.
func TestAFirstStartTakesNoCopy(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()
	if copies := preMigrationCopies(t, path); len(copies) != 0 {
		t.Errorf("a first start left %v behind", copies)
	}
}

// A ledger that exists and is empty is what a crash between creating the table
// and applying the first migration leaves behind. There is still nothing to
// lose, and a copy of an empty database beside every such start would be noise
// -- so this is a separate case from the fresh file above, which never gets as
// far as reading the ledger at all.
func TestAnEmptyLedgerTakesNoCopyEither(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")

	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.ExecContext(ctx, `CREATE TABLE schema_migrations (
		name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()
	if copies := preMigrationCopies(t, path); len(copies) != 0 {
		t.Errorf("a database with an empty ledger was copied: %v", copies)
	}
}

// Opening a database that is already at head is the ordinary case -- every
// restart -- and it must not copy the database each time.
func TestAnOpenWithNothingPendingTakesNoCopy(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	first, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	if err := first.Close(); err != nil {
		t.Fatal(err)
	}

	again, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	defer again.Close()
	if copies := preMigrationCopies(t, path); len(copies) != 0 {
		t.Errorf("restarting on an up-to-date database copied it: %v", copies)
	}
}

// Two is what is worth keeping: the upgrade that just happened, and the one
// before it -- which is the one an operator reaches for when the first went
// unnoticed. More would be a copy of the whole database per release, kept
// forever, on the disk the fleet also needs.
func TestOnlyTheLastTwoCopiesAreKept(t *testing.T) {
	ctx := context.Background()
	path := atSchema(t, 1)
	root := filepath.Join(filepath.Dir(path), PreMigrationDir)

	// Three upgrades' worth, planted with names a year apart so the order is
	// unambiguous, plus something that is not ours.
	for _, stamp := range []string{"20240101-000000", "20250101-000000", "20260101-000000"} {
		if err := os.MkdirAll(filepath.Join(root, BackupDirPrefix+stamp), 0o700); err != nil {
			t.Fatal(err)
		}
	}
	stranger := filepath.Join(root, "notes")
	if err := os.MkdirAll(stranger, 0o700); err != nil {
		t.Fatal(err)
	}

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer s.Close()

	copies := preMigrationCopies(t, path)
	// The newest two: the one this open just took, and 20260101.
	if len(copies) != preMigrationKeep {
		t.Fatalf("kept %v, want %d", copies, preMigrationKeep)
	}
	if contains(copies, BackupDirPrefix+"20240101-000000") {
		t.Errorf("the oldest copy survived: %v", copies)
	}
	if _, err := os.Stat(stranger); err != nil {
		t.Errorf("retention removed a directory this package did not name: %v", err)
	}
}

// The platform role is the first change to reach the users table since the
// first schema, and the first rebuild of a table another one points at. Two
// things could go wrong quietly: a column dropped on the way through, and
// every session deleted by the cascade a DROP fires. Both would surface
// after the upgrade, on a fleet that was working.
func TestThePlatformRoleRebuildKeepsEveryRowItsIndexesAndTheSessions(t *testing.T) {
	ctx := context.Background()
	// From before the rebuild, so that it runs against these rows. Seeding
	// into a fixture that had already applied 0044 was the first attempt and
	// tested nothing: the rebuild had run against an empty users table.
	path := atSchemaBefore(t, "0044_platform_role.sql")

	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatal(err)
	}
	seed := func(query string, args ...any) {
		t.Helper()
		if _, err := db.ExecContext(ctx, query, args...); err != nil {
			t.Fatalf("%s: %v", query, err)
		}
	}
	// Two administrators, the second enabled and older than the first is
	// not: the promotion has to pick by creation time, not by row order.
	seed(`INSERT INTO users (id, username, email, display_name, role, password_hash,
		oidc_subject, disabled, must_change_password, created_at)
		VALUES ('usr_late','late','late@example.com','Late','admin','hash','sub-late',0,0,2000)`)
	seed(`INSERT INTO users (id, username, email, display_name, role, password_hash,
		oidc_subject, disabled, must_change_password, created_at)
		VALUES ('usr_first','first','first@example.com','First','admin','hash','sub-first',0,0,1000)`)
	// An older administrator who has since been disabled is not the one
	// still operating the instance.
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_gone','gone','admin','hash',1,500)`)
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_view','viewer','viewer','hash',0,3000)`)
	seed(`INSERT INTO sessions (id, user_id, token_hash, user_agent, ip, created_at, expires_at)
		VALUES ('ses_one','usr_first','hash-one','curl','127.0.0.1',1000,9999999)`)
	seed(`INSERT INTO sessions (id, user_id, token_hash, created_at, expires_at)
		VALUES ('ses_two','usr_view','hash-two',1000,9999999)`)
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_one','scraper','admin','usr_first','["a"]','hash-tok','zoo_abc',0,1000)`)
	db.Close()

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("upgrading: %v", err)
	}
	defer s.Close()

	// Every row is still there, with its columns.
	u, err := s.GetUser(ctx, "usr_first")
	if err != nil {
		t.Fatal(err)
	}
	if u.Role != RolePlatform {
		t.Errorf("the account that installed the instance is %q, want platform; an upgrade that promotes nobody leaves an instance whose timers nobody can change", u.Role)
	}
	if u.Email != "first@example.com" || u.DisplayName != "First" || u.OIDCSubject != "sub-first" {
		t.Errorf("columns were lost in the rebuild: %+v", u)
	}
	// Who else is promoted is 0045's business, and
	// TestAnUpgradeLeavesEveryAdministratorWithWhatTheyHad is where that
	// lives. What matters here is that a role nobody held is not invented:
	// the viewer is still a viewer.
	if got, err := s.GetUser(ctx, "usr_view"); err != nil || got.Role != RoleViewer {
		t.Errorf("the viewer came back as %+v (%v)", got, err)
	}

	// The sessions survived the cascade a DROP would otherwise have fired.
	var sessions int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM sessions`).Scan(&sessions); err != nil {
		t.Fatal(err)
	}
	if sessions != 2 {
		t.Errorf("%d sessions after the upgrade, want 2: dropping a table a foreign key points at deletes them", sessions)
	}

	// And the token, with the role it had.
	var tokenRole string
	if err := s.read.QueryRowContext(ctx, `SELECT role FROM api_tokens WHERE id = 'tok_one'`).Scan(&tokenRole); err != nil {
		t.Fatalf("the api token did not survive: %v", err)
	}
	// Its role is 0045's business too; what this test is asking is whether
	// the row survived the rebuild at all.
	if tokenRole == "" {
		t.Error("the api token came back with no role")
	}

	// The indexes came back with the tables.
	if _, err := s.exec(ctx, `INSERT INTO users (id, username, role, password_hash, created_at)
		VALUES ('usr_dup','first','viewer','hash',4000)`); err == nil {
		t.Error("a duplicate username was accepted, so the unique index did not come back")
	}
	for _, name := range []string{"idx_users_username", "idx_users_oidc", "idx_api_tokens_hash"} {
		var found string
		err := s.read.QueryRowContext(ctx,
			`SELECT name FROM sqlite_master WHERE type = 'index' AND name = ?`, name).Scan(&found)
		if err != nil {
			t.Errorf("index %s is missing after the rebuild: %v", name, err)
		}
	}
	if err := s.IntegrityCheck(ctx); err != nil {
		t.Errorf("integrity check after the rebuild: %v", err)
	}

	// And the new role is now a value the column accepts.
	if _, err := s.exec(ctx, `INSERT INTO users (id, username, role, password_hash, created_at)
		VALUES ('usr_plat','second-platform','platform','hash',5000)`); err != nil {
		t.Errorf("the rebuilt CHECK still refuses the platform role: %v", err)
	}
}

// A self-hosted fleet whose operations are shared between several
// administrators is the ordinary case, and an upgrade that leaves one of them
// able to take a backup and the others not -- or that stops a nightly
// `zoomies backup` running on an administrator's token -- has taken something
// away without saying so. Everything that held administrator keeps what
// administrator meant.
func TestAnUpgradeLeavesEveryAdministratorWithWhatTheyHad(t *testing.T) {
	ctx := context.Background()
	// From before the role existed at all, which is what a released build
	// left behind.
	path := atSchemaBefore(t, "0044_platform_role.sql")

	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatal(err)
	}
	seed := func(query string, args ...any) {
		t.Helper()
		if _, err := db.ExecContext(ctx, query, args...); err != nil {
			t.Fatalf("%s: %v", query, err)
		}
	}
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_first','first','admin','hash',0,1000)`)
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_second','second','admin','hash',0,2000)`)
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_third','third','admin','hash',0,3000)`)
	// Disabled today, but what it finds when somebody enables it is what it
	// had.
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_away','away','admin','hash',1,4000)`)
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_op','op','operator','hash',0,5000)`)
	// The nightly backup's credential, and one somebody already revoked.
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_nightly','nightly backup','admin','usr_first','["backups:write"]','hash-a','zoo_a',0,1000)`)
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_gone','retired','admin','usr_first','["*"]','hash-b','zoo_b',1,1000)`)
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_view','dashboard','viewer','usr_op','["*"]','hash-c','zoo_c',0,1000)`)
	db.Close()

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("upgrading: %v", err)
	}
	defer s.Close()

	for _, id := range []string{"usr_first", "usr_second", "usr_third", "usr_away"} {
		u, err := s.GetUser(ctx, id)
		if err != nil {
			t.Fatal(err)
		}
		if u.Role != RolePlatform {
			t.Errorf("%s came up from the upgrade as %q; an administrator who could take a backup yesterday must still be able to today", id, u.Role)
		}
	}
	if u, err := s.GetUser(ctx, "usr_op"); err != nil || u.Role != RoleOperator {
		t.Errorf("the operator was promoted: %+v (%v)", u, err)
	}

	roleOf := func(id string) string {
		t.Helper()
		var role string
		if err := s.read.QueryRowContext(ctx, `SELECT role FROM api_tokens WHERE id = ?`, id).Scan(&role); err != nil {
			t.Fatal(err)
		}
		return role
	}
	if got := roleOf("tok_nightly"); got != string(RolePlatform) {
		t.Errorf("the nightly backup's token is %q; it would start answering 403 with nothing said to anybody", got)
	}
	if got := roleOf("tok_gone"); got != string(RoleAdmin) {
		t.Errorf("a revoked token was rewritten to %q; it authorises nothing and the audit trail should not read as though somebody changed it", got)
	}
	if got := roleOf("tok_view"); got != string(RoleViewer) {
		t.Errorf("a viewer token became %q", got)
	}
}

// An operator who has already run 0044 can create an account at administrator
// meaning the new administrator -- one that cannot take a backup or lift the
// recovery fence -- and mean it. Restoring authority somebody held the day
// before the split is the point of 0045; granting authority somebody
// deliberately withheld after it is the one thing worse than the regression
// 0045 exists to fix. So the promotion stops at the moment 0044 ran.
func TestAnUpgradeDoesNotPromoteWhatWasMadeAfterTheRoleSplit(t *testing.T) {
	ctx := context.Background()
	// Through 0044 but not 0045: the state of anybody tracking main between
	// the two, the project's own fleet among them.
	path := atSchemaBefore(t, "0045_upgrade_keeps_what_admins_had.sql")

	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=foreign_keys(1)")
	if err != nil {
		t.Fatal(err)
	}
	var split int64
	if err := db.QueryRowContext(ctx,
		`SELECT applied_at FROM schema_migrations WHERE name = '0044_platform_role.sql'`).Scan(&split); err != nil {
		t.Fatalf("0044 left no ledger row, so 0045 has nothing to bound itself by: %v", err)
	}
	seed := func(query string, args ...any) {
		t.Helper()
		if _, err := db.ExecContext(ctx, query, args...); err != nil {
			t.Fatalf("%s: %v", query, err)
		}
	}
	// One from before the split, which is owed what it had.
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_before','before','admin','hash',0,?)`, split-1000)
	// And one made afterwards, deliberately, at the administrator the split
	// left behind.
	seed(`INSERT INTO users (id, username, role, password_hash, disabled, created_at)
		VALUES ('usr_after','after','admin','hash',0,?)`, split+1000)
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_before','old','admin','usr_before','["*"]','hash-a','zoo_a',0,?)`, split-1000)
	seed(`INSERT INTO api_tokens (id, name, role, user_id, scopes, token_hash, prefix, revoked, created_at)
		VALUES ('tok_after','new','admin','usr_after','["*"]','hash-b','zoo_b',0,?)`, split+1000)
	db.Close()

	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("upgrading: %v", err)
	}
	defer s.Close()

	if u, err := s.GetUser(ctx, "usr_before"); err != nil || u.Role != RolePlatform {
		t.Errorf("the account that predates the split came up as %+v (%v); it is owed what it had", u, err)
	}
	if u, err := s.GetUser(ctx, "usr_after"); err != nil || u.Role != RoleAdmin {
		t.Errorf("an account created after the split came up as %+v (%v); the upgrade granted authority somebody withheld on purpose", u, err)
	}

	roleOf := func(id string) string {
		t.Helper()
		var role string
		if err := s.read.QueryRowContext(ctx, `SELECT role FROM api_tokens WHERE id = ?`, id).Scan(&role); err != nil {
			t.Fatal(err)
		}
		return role
	}
	if got := roleOf("tok_before"); got != string(RolePlatform) {
		t.Errorf("a token minted before the split is %q; it would start answering 403 with nothing said to anybody", got)
	}
	if got := roleOf("tok_after"); got != string(RoleAdmin) {
		t.Errorf("a token minted after the split was elevated to %q", got)
	}
}

// Package store owns Zoomies' persistent state: the SQLite schema, the domain
// types that map onto it, and every query the rest of the program runs.
//
// Nothing outside this package touches SQL. Everything the controller needs to
// know across a restart lives here -- deliberately, because the project this
// one replaces scattered runtime state across dotfiles inside runner working
// directories, where it could not be queried, backed up or audited.
package store

import (
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"math"
	"slices"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/naming"
)

// ---------------------------------------------------------------------------
// Enumerations
// ---------------------------------------------------------------------------

// TargetType says whether an installation manages runners for a whole
// organisation or for a single repository.
type TargetType string

const (
	TargetOrg  TargetType = "org"
	TargetRepo TargetType = "repo"
)

func (t TargetType) Valid() bool { return t == TargetOrg || t == TargetRepo }

// BackendKind selects how an agent materialises a runner on its host.
type BackendKind string

const (
	BackendDocker  BackendKind = "docker"
	BackendPodman  BackendKind = "podman"
	BackendProcess BackendKind = "process"
)

func (b BackendKind) Valid() bool {
	switch b {
	case BackendDocker, BackendPodman, BackendProcess:
		return true
	}
	return false
}

type PullPolicy string

const (
	PullIfNotPresent PullPolicy = "if-not-present"
	PullAlways       PullPolicy = "always"
	PullPinnedOnly   PullPolicy = "pinned-only"
)

func (p PullPolicy) Valid() bool {
	return p == PullIfNotPresent || p == PullAlways || p == PullPinnedOnly
}

// DockerMode controls whether jobs running on a pool's runners can themselves
// talk to a Docker daemon. Both non-none values weaken isolation, so both are
// surfaced as warnings by the config validator and in the UI problems drawer.
type DockerMode string

const (
	// DockerNone is the default: jobs get no Docker daemon at all.
	DockerNone DockerMode = "none"
	// DockerDinD runs a private, per-runner dockerd sidecar. The job can build
	// images but cannot see the host's containers.
	DockerDinD DockerMode = "dind"
	// DockerHostSocket bind-mounts the host's docker.sock into the runner.
	// Any job on this pool can trivially become root on the host.
	DockerHostSocket DockerMode = "host-socket"
)

func (d DockerMode) Valid() bool {
	switch d {
	case DockerNone, DockerDinD, DockerHostSocket:
		return true
	}
	return false
}

// Dangerous reports whether this mode materially weakens the isolation between
// a workflow job and the host it runs on.
func (d DockerMode) Dangerous() bool { return d == DockerHostSocket }

// GivesDaemon reports whether jobs on a pool with this mode get a Docker
// daemon at all. It is the question the pool's image has to answer as well: a
// daemon is worth nothing to a job whose image has no client to reach it with,
// so the image a pool runs is decided by this rather than by the mode's name.
func (d DockerMode) GivesDaemon() bool { return d == DockerDinD || d == DockerHostSocket }

// RunnerState is the runner lifecycle state machine:
//
//	provisioning -> registering -> idle -> busy -> draining -> removed
//	                                   \-> failed (from any state)
type RunnerState string

const (
	RunnerProvisioning RunnerState = "provisioning"
	RunnerRegistering  RunnerState = "registering"
	RunnerIdle         RunnerState = "idle"
	RunnerBusy         RunnerState = "busy"
	RunnerDraining     RunnerState = "draining"
	RunnerRemoved      RunnerState = "removed"
	RunnerFailed       RunnerState = "failed"
)

func (s RunnerState) Valid() bool {
	switch s {
	case RunnerProvisioning, RunnerRegistering, RunnerIdle, RunnerBusy,
		RunnerDraining, RunnerRemoved, RunnerFailed:
		return true
	}
	return false
}

// Terminal reports whether a runner in this state will never do more work.
func (s RunnerState) Terminal() bool { return s == RunnerRemoved || s == RunnerFailed }

// Live reports whether a runner in this state counts against a pool's max, i.e.
// it exists (or is about to exist) and consumes host capacity.
func (s RunnerState) Live() bool { return !s.Terminal() }

// Assignable reports whether GitHub could hand this runner a job right now.
func (s RunnerState) Assignable() bool { return s == RunnerIdle || s == RunnerBusy }

// validRunnerTransitions is the allow-list enforced by Store.TransitionRunner.
// Keeping it here rather than in the caller means an agent cannot report a
// nonsensical state and corrupt the fleet's accounting.
var validRunnerTransitions = map[RunnerState][]RunnerState{
	RunnerProvisioning: {RunnerRegistering, RunnerDraining, RunnerFailed, RunnerRemoved},
	RunnerRegistering:  {RunnerIdle, RunnerBusy, RunnerDraining, RunnerFailed, RunnerRemoved},
	RunnerIdle:         {RunnerBusy, RunnerDraining, RunnerFailed, RunnerRemoved},
	RunnerBusy:         {RunnerIdle, RunnerDraining, RunnerFailed, RunnerRemoved},
	RunnerDraining:     {RunnerRemoved, RunnerFailed},
	RunnerRemoved:      {},
	RunnerFailed:       {RunnerRemoved},
}

// CanTransition reports whether from -> to is a legal runner state change.
func CanTransition(from, to RunnerState) bool {
	if from == to {
		return true
	}
	return slices.Contains(validRunnerTransitions[from], to)
}

// JobState mirrors the lifecycle GitHub reports over workflow_job webhooks.
type JobState string

const (
	// JobWaiting is a job GitHub is holding for a deployment review. It is not
	// demand: nothing may run it until somebody approves it, and GitHub sends
	// a real "queued" delivery when they do. Recording it as queued made the
	// scheduler start a runner that idled out and was started again on the
	// next pass, for as long as the review took.
	JobWaiting    JobState = "waiting"
	JobQueued     JobState = "queued"
	JobInProgress JobState = "in_progress"
	JobCompleted  JobState = "completed"
)

func (s JobState) Valid() bool {
	switch s {
	case JobWaiting, JobQueued, JobInProgress, JobCompleted:
		return true
	}
	return false
}

// Role is the RBAC level attached to a user or an API token.
type Role string

const (
	// RoleViewer may read everything except secrets.
	RoleViewer Role = "viewer"
	// RoleOperator may additionally act on the fleet: drain, delete, restart
	// runners, cordon hosts, and create or edit pools.
	RoleOperator Role = "operator"
	// RoleAdmin may additionally manage users, tokens, installations and settings.
	RoleAdmin Role = "admin"
	// RolePlatform is whoever runs the process rather than the fleet: the
	// address it binds, the files it reads, the timers it keeps, the fence
	// it lifts and the backups it holds.
	//
	// It sits above administrator because an instance can be operated by
	// one team for another -- a platform team running Zoomies for a
	// product team -- and until now there was nowhere to put that half:
	// the fleet's administrator was the top rung and read the bind address
	// and the database path along with everything else. On an instance
	// where one team does both, the account that installed it holds this
	// as well, and nothing looks any different.
	RolePlatform Role = "platform"
)

func (r Role) Valid() bool {
	switch r {
	case RoleViewer, RoleOperator, RoleAdmin, RolePlatform:
		return true
	}
	return false
}

// Roles is the closed set, lowest first. It exists so that a refusal can name
// the roles there are rather than the roles somebody remembered: every "use
// viewer, operator or admin" in this repository was written before the fourth
// one, and each was a message telling an operator that a role they had just
// read about in the documentation did not exist.
func Roles() []Role { return []Role{RoleViewer, RoleOperator, RoleAdmin, RolePlatform} }

// RoleList renders the closed set for a sentence: "viewer, operator, admin or
// platform".
func RoleList() string {
	all := Roles()
	names := make([]string, len(all))
	for i, r := range all {
		names[i] = string(r)
	}
	return strings.Join(names[:len(names)-1], ", ") + " or " + names[len(names)-1]
}

// rank orders roles so that AtLeast can compare them.
func (r Role) rank() int {
	switch r {
	case RoleViewer:
		return 1
	case RoleOperator:
		return 2
	case RoleAdmin:
		return 3
	case RolePlatform:
		return 4
	}
	return 0
}

// AtLeast reports whether r carries at least the authority of want.
func (r Role) AtLeast(want Role) bool { return r.rank() >= want.rank() && r.rank() > 0 }

// ---------------------------------------------------------------------------
// Helper column types
// ---------------------------------------------------------------------------

// StringSlice is a []string persisted as a JSON array in a TEXT column.
type StringSlice []string

func (s *StringSlice) Scan(v any) error {
	*s = nil
	switch t := v.(type) {
	case nil:
		return nil
	case []byte:
		if len(t) == 0 {
			return nil
		}
		return json.Unmarshal(t, s)
	case string:
		if t == "" {
			return nil
		}
		return json.Unmarshal([]byte(t), s)
	}
	return fmt.Errorf("store: cannot scan %T into StringSlice", v)
}

func (s StringSlice) Value() (driver.Value, error) {
	if s == nil {
		s = StringSlice{}
	}
	b, err := json.Marshal([]string(s))
	return string(b), err
}

// StringMap is a map[string]string persisted as a JSON object in a TEXT column.
type StringMap map[string]string

func (m *StringMap) Scan(v any) error {
	*m = nil
	switch t := v.(type) {
	case nil:
		return nil
	case []byte:
		if len(t) == 0 {
			return nil
		}
		return json.Unmarshal(t, m)
	case string:
		if t == "" {
			return nil
		}
		return json.Unmarshal([]byte(t), m)
	}
	return fmt.Errorf("store: cannot scan %T into StringMap", v)
}

func (m StringMap) Value() (driver.Value, error) {
	if m == nil {
		m = StringMap{}
	}
	b, err := json.Marshal(map[string]string(m))
	return string(b), err
}

// HostBackend is one line of an agent's capability probe: what it found, or
// what stopped it finding anything.
//
// It mirrors backend.Info, which the store cannot name because the backend
// package is built on top of this one. Only the fields an operator or the
// scheduler needs are kept; the host's Docker socket path is deliberately not
// among them, since nothing reads it back and it is a detail of the machine
// rather than of the fleet.
type HostBackend struct {
	Kind BackendKind `json:"kind"`
	// Available is false when the daemon did not answer. Detail then explains
	// why in the agent's own words, which is usually the whole fix.
	Available bool   `json:"available"`
	Version   string `json:"version,omitempty"`
	Rootless  bool   `json:"rootless"`
	Endpoint  string `json:"endpoint,omitempty"`
	Detail    string `json:"detail,omitempty"`
	// SupportsDinD reports whether this backend can give a job its own Docker
	// daemon in a sidecar.
	SupportsDinD bool `json:"supports_dind"`
	// CPUs and MemoryMB are the machine the daemon runs on, as it reported
	// them, kept beside the limits it can apply because a default CPU share
	// is a request to that daemon: one above its own core count is refused
	// outright, however many cores the agent's machine has.
	CPUs     int   `json:"cpus,omitempty"`
	MemoryMB int64 `json:"memory_mb,omitempty"`
	// Limits is whether the daemon behind this backend can enforce a CPU
	// quota, a memory limit and a pids limit at all. A rootless daemon on
	// cgroup v1, or on cgroup v2 with no cpu controller delegated to the user,
	// refuses a container that asks for a CPU quota rather than ignoring it
	// -- so a default limit sent to such a host would fail every create, and
	// the controller has to know before it sends one.
	Limits LimitSupport `json:"limits"`
	// SharedFolder is what the agent said is wrong with the host's shared
	// folder: a containerised agent whose container does not mount it from
	// the host. Empty when nothing is.
	SharedFolder string `json:"shared_folder,omitempty"`
}

// LimitSupport is what a container daemon said about the limits it can apply.
// Known is false from an agent too old to ask, and nothing may read that as
// "cannot": it is read as "do not default anything here", which is what every
// host did before defaults existed.
type LimitSupport struct {
	Known  bool `json:"known"`
	CPU    bool `json:"cpu"`
	Memory bool `json:"memory"`
	Pids   bool `json:"pids"`
}

// HostBackends is a probe result persisted as a JSON array in a TEXT column.
type HostBackends []HostBackend

func (b *HostBackends) Scan(v any) error {
	*b = nil
	switch t := v.(type) {
	case nil:
		return nil
	case []byte:
		if len(t) == 0 {
			return nil
		}
		return json.Unmarshal(t, b)
	case string:
		if t == "" {
			return nil
		}
		return json.Unmarshal([]byte(t), b)
	}
	return fmt.Errorf("store: cannot scan %T into HostBackends", v)
}

func (b HostBackends) Value() (driver.Value, error) {
	if b == nil {
		b = HostBackends{}
	}
	s, err := json.Marshal([]HostBackend(b))
	return string(s), err
}

// Kinds returns the backends that answered, sorted, which is what a pool is
// matched against.
func (b HostBackends) Kinds() StringSlice {
	var out StringSlice
	for _, i := range b {
		if i.Available {
			out = append(out, string(i.Kind))
		}
	}
	slices.Sort(out)
	return out
}

// Find returns what the probe said about one backend, if it said anything.
func (b HostBackends) Find(kind BackendKind) (HostBackend, bool) {
	for _, i := range b {
		if i.Kind == kind {
			return i, true
		}
	}
	return HostBackend{}, false
}

// ---------------------------------------------------------------------------
// Domain types
// ---------------------------------------------------------------------------

// Installation is one GitHub App installation and the org or repo it targets.
// APIBaseURL and UploadBaseURL are non-empty for GitHub Enterprise Server.
type Installation struct {
	ID             string     `json:"id"`
	AppID          int64      `json:"app_id"`
	InstallationID int64      `json:"installation_id"`
	Target         string     `json:"target"`      // "acme" or "acme/widgets"
	TargetType     TargetType `json:"target_type"` // org | repo
	APIBaseURL     string     `json:"api_base_url"`
	UploadBaseURL  string     `json:"upload_base_url"`
	// PrivateKeyEnc holds the PEM private key sealed with the instance key.
	// It is never rendered by the API.
	PrivateKeyEnc []byte `json:"-"`
	// WebhookSecretEnc holds the sealed HMAC secret for this installation.
	WebhookSecretEnc []byte    `json:"-"`
	AppSlug          string    `json:"app_slug"`
	CreatedAt        time.Time `json:"created_at"`
	UpdatedAt        time.Time `json:"updated_at"`
	// Health fields, refreshed by the controller's installation prober.
	LastCheckedAt *time.Time `json:"last_checked_at,omitempty"`
	LastError     string     `json:"last_error,omitempty"`
}

// Healthy reports whether the last credential check succeeded.
func (i *Installation) Healthy() bool { return i.LastError == "" }

// Platform is the machine a pool's runners need, or the machine a host is.
//
// It exists because "backend: docker" says how a runner is made and nothing
// about what it is made of. A pool asking for Ubuntu 24.04 on arm64 must not
// have its runners placed on a Debian amd64 host, and until the fleet can
// state the platform on both sides there is no way to stop it.
//
// Every field is optional. An empty field is a promise nobody made, and
// matches anything -- which is what keeps a fleet built before platforms
// existed working exactly as it did.
type Platform struct {
	// OS is a distribution, normalised by naming.NormalizeOS: ubuntu, debian,
	// fedora, rocky, macos, windows. Not a kernel: "linux" does not say which
	// image a runner should be started from.
	OS string `json:"os,omitempty"`
	// OSVersion is the release, as an operator writes it: "24.04", "12".
	OSVersion string `json:"os_version,omitempty"`
	// Arch is amd64 or arm64, normalised by naming.NormalizeArch.
	Arch string `json:"arch,omitempty"`
}

// Normalized returns the platform with each field in its canonical spelling,
// dropping anything Zoomies does not recognise rather than storing a value the
// scheduler would then never match.
func (p Platform) Normalized() Platform {
	return Platform{
		OS:        naming.NormalizeOS(p.OS),
		OSVersion: strings.TrimSpace(p.OSVersion),
		Arch:      naming.NormalizeArch(p.Arch),
	}
}

// Empty reports whether the platform constrains nothing.
func (p Platform) Empty() bool { return p == Platform{} }

// Matches reports whether a host of platform h can run a pool that asks for p.
//
// Comparison is one-directional on purpose: every field the pool leaves empty
// is a question it did not ask, and a host that has not reported a field
// cannot be ruled out by it either. The result is that adding a platform to a
// pool narrows placement, and never widens it.
func (p Platform) Matches(h Platform) bool {
	p, h = p.Normalized(), h.Normalized()
	if p.OS != "" && h.OS != "" && p.OS != h.OS {
		return false
	}
	if p.Arch != "" && h.Arch != "" && p.Arch != h.Arch {
		return false
	}
	if p.OSVersion != "" && h.OSVersion != "" &&
		naming.CompactVersion(p.OSVersion) != naming.CompactVersion(h.OSVersion) {
		return false
	}
	return true
}

// Describe renders the platform for the UI and for scheduler explanations,
// e.g. "Ubuntu 24.04, arm64". It is empty when the platform promises nothing.
func (p Platform) Describe() string {
	return naming.Spec{OS: p.OS, Version: p.OSVersion, Arch: p.Arch}.Platform()
}

// Resources caps what a single runner may consume on its host. Zero means
// "unlimited", which is the backend's own default.
type Resources struct {
	CPUs      float64 `json:"cpus,omitempty"`       // e.g. 2 => --cpus=2
	MemoryMB  int64   `json:"memory_mb,omitempty"`  // e.g. 4096
	DiskGB    int64   `json:"disk_gb,omitempty"`    // advisory; enforced where the backend can
	PidsLimit int64   `json:"pids_limit,omitempty"` // container pids cgroup limit
	// MinCPUs and MinMemoryMB are the least a runner of a fixed-size pool may
	// be given when no host has room for the full size above. CPUs and
	// MemoryMB stay the standard the fleet places at wherever it can; the
	// minimum is what lets a host a little short of that -- a 30 GB machine
	// under a 32 GB pool -- run the job anyway instead of leaving it queued.
	// Such a runner is given as much of the standard as the host can spare,
	// never less than this. On a pool, zero is "the fleet's": the controller
	// reads runners.minimum_* in its place (controller.EffectiveMinimum)
	// rather than it being copied here, so the stored zero is what keeps the
	// pool following that setting. Zero with no fleet minimum is none.
	MinCPUs     float64 `json:"min_cpus,omitempty"`
	MinMemoryMB int64   `json:"min_memory_mb,omitempty"`
}

// Reducible reports whether a runner of these resources may be placed below
// its standard size: some field has a minimum under its standard. A field the
// pool leaves to the host has a slot's share of that host as its standard, so
// any minimum on it counts -- which is what lets an automatic pool run on a
// host with a free slot but less than a whole share of it left. Whether the
// minimum is below a particular host's share is the scheduler's to judge.
func (r Resources) Reducible() bool {
	return (r.MinCPUs > 0 && (r.CPUs <= 0 || r.MinCPUs < r.CPUs)) ||
		(r.MinMemoryMB > 0 && (r.MemoryMB <= 0 || r.MinMemoryMB < r.MemoryMB))
}

// CPUBurstMode says what a pool does with CPU that its live runners have not
// reserved. The empty value is deliberately off so an upgrade never changes
// an existing pool's quotas.
type CPUBurstMode string

const (
	CPUBurstOff       CPUBurstMode = "off"
	CPUBurstObserve   CPUBurstMode = "observe"
	CPUBurstAutomatic CPUBurstMode = "automatic"
)

func (m CPUBurstMode) Valid() bool {
	return m == "" || m == CPUBurstOff || m == CPUBurstObserve || m == CPUBurstAutomatic
}

// CPUBurstPolicy lets an automatically-sized container runner borrow CPU that
// no live runner or imminent start has been promised. Memory is intentionally
// absent: lowering a live memory limit can kill the job it is meant to help.
type CPUBurstPolicy struct {
	Mode CPUBurstMode `json:"mode,omitempty"`
	// MaxCPUs is the most CPU one logical runner may use. Zero means the
	// host's allocatable CPU. For a DinD runner it covers the runner and its
	// sidecar together, just like an automatic slot does.
	MaxCPUs float64 `json:"max_cpus,omitempty"`
	// SizeForCeiling says whether an automatic pool's runners start with the
	// environment that tells Rust, the JVM and .NET how many CPUs to size
	// their workers for: the ceiling rather than the guarantee. Those
	// toolchains read the quota once, at start, and a loan that arrives later
	// is CPU they have no worker to use. Nil is on, so every automatic pool
	// gets it without an edit; false is an operator turning it off.
	SizeForCeiling *bool `json:"size_for_ceiling,omitempty"`
}

// SizesForCeiling reports whether runners of this policy are started with
// their toolchains sized for the ceiling. Only a pool that really lends CPU
// does: sizing for a ceiling that is never lent only adds context switches.
func (p CPUBurstPolicy) SizesForCeiling() bool {
	return p.Enforces() && (p.SizeForCeiling == nil || *p.SizeForCeiling)
}

func (p CPUBurstPolicy) Observes() bool {
	return p.Mode == CPUBurstObserve || p.Mode == CPUBurstAutomatic
}

func (p CPUBurstPolicy) Enforces() bool { return p.Mode == CPUBurstAutomatic }

// SplitWithDaemon divides limits a runner was given by its host's slot between
// the runner and the docker-in-docker daemon that runs beside it.
//
// It exists because the two containers are one runner. A slot is the unit a
// machine is cut into, and an operator who sets a host to eight slots is
// saying it may carry eight runners -- not four, because half of them brought
// a daemon. So the pair is given one slot's share and splits it, and the
// scheduler charges the host one share for the pair: the arithmetic the page
// shows, the quota the daemon applies, and the room the scheduler counts are
// then the same number, which is what stops a host reading as half idle while
// its containers' quotas add up to every core it has.
//
// The halves are even, because the work is on both sides of the pair: a build
// runs in the daemon, and everything else in the job -- the checkout, the
// toolchain, the test run -- is in the runner. A slot too small to give both
// halves what a runner needs is refused rather than divided, so nothing here
// has to decide which half to starve.
//
// Limits an operator typed are not split: those say what the job may have, the
// daemon is given the same, and scheduler.Reserve charges the host for both.
func (r Resources) SplitWithDaemon() (runner, daemon Resources) {
	runner, daemon = r, r
	// An even split, and nothing clever for a share too small to take one: a
	// slot that cannot carry both halves is refused before a runner is placed
	// on it -- scheduler.ShareFloor -- because the alternative here is giving
	// the daemon whatever is left over, and a leftover of nothing is no limit
	// at all, which is how one build takes the machine.
	if r.CPUs > 0 {
		runner.CPUs = r.CPUs / 2
		daemon.CPUs = r.CPUs - runner.CPUs
	}
	if r.MemoryMB > 0 {
		runner.MemoryMB = r.MemoryMB / 2
		daemon.MemoryMB = r.MemoryMB - runner.MemoryMB
	}
	// Pids and disk are not divided. A pids limit is a guard against a fork
	// bomb rather than a budget, and halving it would refuse a legitimate
	// build on a pool that never asked for less; disk is the cache and the
	// image store, which the daemon holds for the pair.
	return runner, daemon
}

// RunnerSettings is a pool's answer where it disagrees with the fleet's.
//
// Every field is a pointer, and that is the type's whole meaning: nil is "the
// fleet decides", and it keeps deciding -- a pool that overrides nothing
// follows scheduler.provision_timeout when an operator changes it, rather
// than being frozen on whatever it read the day the pool was made. A field
// that is set overrides it, including when what it is set to is zero, because
// zero is a real answer for each of these: "never fail a runner for taking
// too long to register" is a thing a pool on a slow air-gapped registry has
// every reason to say.
//
// These are the settings whose right answer is a property of the pool rather
// than of the fleet. A pool pulling a twelve-gigabyte Windows image and a
// pool booting Alpine do not agree about how long registering should take,
// and a fleet that has to pick one picks the slower -- which leaves the fast
// pool holding a dead runner's slot for ten minutes. IdleTimeout is not here
// because it is already a pool field, and was from the start.
type RunnerSettings struct {
	// ProvisionTimeout fails a runner of this pool that never finishes
	// registering. Overrides scheduler.provision_timeout.
	ProvisionTimeout *Duration `json:"provision_timeout,omitempty"`
	// DrainTimeout fails a runner of this pool that has been draining this
	// long with no job left on it. Overrides scheduler.drain_timeout.
	DrainTimeout *Duration `json:"drain_timeout,omitempty"`
	// MaxRunnerLifetime drains a runner of this pool that has lived this long,
	// the next time it is not busy. Overrides scheduler.max_runner_lifetime.
	// It never ends a job, exactly as the fleet's own does not.
	MaxRunnerLifetime *Duration `json:"max_runner_lifetime,omitempty"`
	// ScaleUpDelay is how long a job for this pool must have been queued
	// before it counts as demand. Overrides scheduler.scale_up_delay.
	ScaleUpDelay *Duration `json:"scale_up_delay,omitempty"`
	// DockerWait is how long a runner of this pool waits for the Docker
	// daemon it was promised before refusing to take a job. Overrides
	// runners.docker_wait, and means nothing on a pool whose docker_mode is
	// none -- there is no daemon to wait for.
	DockerWait *Duration `json:"docker_wait,omitempty"`
}

// Set reports whether this pool overrides anything at all, which is what the
// UI asks before it draws a panel and what an explanation asks before it says
// a figure came from the pool.
func (r RunnerSettings) Set() bool {
	return r.ProvisionTimeout != nil || r.DrainTimeout != nil || r.MaxRunnerLifetime != nil ||
		r.ScaleUpDelay != nil || r.DockerWait != nil
}

// Supports reports whether this host's agent advertises a feature. The
// controller passes the agent package's constant; the store does not know
// what any feature means, only that the agent claimed it.
func (h *Host) Supports(feature string) bool {
	return slices.Contains(h.Features, feature)
}

// Automatic reports whether this pool leaves its runners' size to the host
// they land on: one slot's share of whichever machine the scheduler picks,
// charged and enforced as such.
//
// It is what a pool means by asking for no CPU and no memory, and it is the
// shape a pool has unless somebody chose otherwise. Disk and the pids limit
// are deliberately not part of the question: neither has a share to be given
// (free disk is a measurement rather than a budget) so a pool may cap its
// cache's disk and still leave its size to the host.
func (p *Pool) Automatic() bool {
	return p.Resources.CPUs <= 0 && p.Resources.MemoryMB <= 0
}

type CacheScope string

const (
	CacheScopePool       CacheScope = "pool"
	CacheScopeRepository CacheScope = "repository"
)

func (s CacheScope) Valid() bool { return s == CacheScopePool || s == CacheScopeRepository }

// CacheConfig describes disposable accelerator data mounted at /opt/zoomies-cache.
// It is not persistent workflow storage and may be evicted. Source is either an
// absolute host directory prefix or a named-volume prefix.
type CacheConfig struct {
	Enabled bool       `json:"enabled"`
	Scope   CacheScope `json:"scope"`
	// SizeLimit is enforced by evicting whole cache entries, least recently
	// modified first, in the gap between one runner and the next. Only a cache
	// in a host directory can be measured, so a limit is refused on a named
	// volume rather than accepted and quietly ignored. Zero is unlimited.
	SizeLimit int64  `json:"size_limit,omitempty"`
	Source    string `json:"source,omitempty"`
	// Repository names the repository a repository-scoped cache belongs to,
	// as "owner/name". A repository-targeted installation supplies it on its
	// own; an organisation-targeted one cannot, because the fleet it serves has
	// many repositories, and this is what lets such a pool have a repository
	// cache without an installation of its own per repository.
	Repository string `json:"repository,omitempty"`
	// Tools keeps the pool's tool cache -- where setup-python, setup-node,
	// setup-go and setup-java unpack what they download -- between runners,
	// in the host's shared folder, with the same scope as the cache above. A
	// job that can write to it can replace a tool the next job runs, which is
	// why it follows the cache's scope rather than being fleet-wide.
	Tools bool `json:"tools,omitempty"`
}

// Pool is a named group of interchangeable runners: what labels they answer to,
// how they are built, and how many of them may exist.
type Pool struct {
	ID             string      `json:"id"`
	Name           string      `json:"name"`
	InstallationID string      `json:"installation_id"`
	Labels         StringSlice `json:"labels"`
	// NoDefaultLabels registers runners with only Labels, without the
	// self-hosted, operating-system and architecture labels actions/runner
	// adds itself -- config.sh's --no-default-labels. GitHub adds those labels
	// to every just-in-time runner regardless, so only a non-ephemeral pool
	// can honour it.
	NoDefaultLabels bool        `json:"no_default_labels,omitempty"`
	RunnerGroup     string      `json:"runner_group,omitempty"`
	Backend         BackendKind `json:"backend"`
	// Platform is the machine this pool's runners need. It picks the runner
	// image when the pool names none, and it stops the scheduler placing a
	// runner on a host that is not that machine.
	Platform      Platform   `json:"platform"`
	Image         string     `json:"image"`
	PullPolicy    PullPolicy `json:"pull_policy"`
	RunnerVersion string     `json:"runner_version,omitempty"`
	MinRunners    int        `json:"min_runners"`
	MaxRunners    int        `json:"max_runners"`
	// RepositoryScaleUpLimit is a best-effort throttle on runner creation
	// attributable to any one repository. GitHub may assign queued work to any
	// compatible idle runner, so this is not a strict execution concurrency cap.
	// Zero leaves the pool unrestricted.
	RepositoryScaleUpLimit int `json:"repository_scale_up_limit,omitempty"`
	// CostPerRunnerHour is administrator supplied; Zoomies never embeds prices.
	CostPerRunnerHour *float64       `json:"cost_per_runner_hour,omitempty"`
	Priority          int            `json:"priority"`
	IdleTimeout       Duration       `json:"idle_timeout"`
	Ephemeral         bool           `json:"ephemeral"`
	DockerMode        DockerMode     `json:"docker_mode"`
	Resources         Resources      `json:"resources"`
	CPUBurst          CPUBurstPolicy `json:"cpu_burst"`
	Cache             CacheConfig    `json:"cache"`
	// HostSelector matches Host.Labels; empty means "any host".
	// RunnerSettings is what this pool overrides of the fleet's own runner
	// timings. Every field is nil on a pool that follows the fleet, which is
	// every pool until somebody says otherwise.
	RunnerSettings RunnerSettings `json:"runner_settings"`
	HostSelector   StringMap      `json:"host_selector"`
	// Env is injected into every runner this pool creates.
	Env StringMap `json:"env"`
	// RunAsRoot disables the backend's default of dropping to an unprivileged
	// user inside the runner. Flagged as dangerous.
	RunAsRoot bool      `json:"run_as_root"`
	Enabled   bool      `json:"enabled"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// Spec is the pool in the naming grammar's terms: how much machine each of its
// runners gets, and which machine that is. It is what names the pool, what
// labels it, and what the Pools page prints beside it.
func (p *Pool) Spec() naming.Spec {
	return naming.Spec{
		CPUs:     p.Resources.CPUs,
		MemoryGB: int(p.Resources.MemoryMB / 1024),
		OS:       p.Platform.OS,
		Version:  p.Platform.OSVersion,
		Arch:     p.Platform.Arch,
	}
}

// CanonicalName is the name this pool would be given by `zoomies pools create`
// today. A pool whose name already equals it needs no explanation in the UI.
func (p *Pool) CanonicalName() string { return naming.PoolName(p.Spec()) }

type PoolPrewarm struct {
	PoolID    string    `json:"pool_id"`
	HostID    string    `json:"host_id"`
	HostName  string    `json:"host_name,omitempty"`
	Image     string    `json:"image"`
	State     string    `json:"state"`
	Digest    string    `json:"digest,omitempty"`
	Error     string    `json:"error,omitempty"`
	UpdatedAt time.Time `json:"updated_at"`
}

// Duration is a time.Duration that marshals to and from a Go duration string
// ("5m", "1h30s") so config files and API payloads stay readable.
type Duration time.Duration

func (d Duration) Duration() time.Duration { return time.Duration(d) }
func (d Duration) String() string          { return time.Duration(d).String() }

func (d Duration) MarshalJSON() ([]byte, error) { return json.Marshal(time.Duration(d).String()) }

// durationNeedsUnit is the one answer both decoders give to a bare number. The
// JSON side used to read 300 as nanoseconds and the YAML side as seconds, so
// the same file meant different things depending on how it arrived; a unit is
// unambiguous, and the OpenAPI schema has always said a duration is a string.
const durationNeedsUnit = `a duration is written with its unit, like "30s", "5m" or "1h30m"`

func (d *Duration) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return fmt.Errorf("%s", durationNeedsUnit)
	}
	return d.parse(s)
}

// UnmarshalYAML lets a pool definition write idle_timeout: 5m.
func (d *Duration) UnmarshalYAML(unmarshal func(any) error) error {
	var s string
	if err := unmarshal(&s); err != nil {
		return fmt.Errorf("%s", durationNeedsUnit)
	}
	return d.parse(s)
}

func (d *Duration) parse(s string) error {
	p, err := time.ParseDuration(s)
	if err != nil {
		return fmt.Errorf("invalid duration %q: %w; %s", s, err, durationNeedsUnit)
	}
	*d = Duration(p)
	return nil
}

func (d Duration) MarshalYAML() (any, error) { return time.Duration(d).String(), nil }

// DinDDanger is the one sentence Dangerous returns that a fleet may ask not to
// be told again -- see security.docker_in_docker_expected. It is named so that
// the setting matches on the sentence rather than re-deriving which one it
// meant.
const DinDDanger = "docker-in-docker sidecar: runners get a privileged container"

// Dangerous returns the list of pool settings that weaken the default security
// posture, phrased for direct display in the UI's problems drawer.
func (p *Pool) Dangerous() []string {
	var out []string
	if !p.Ephemeral {
		out = append(out, "persistent runners: job state and credentials leak between workflow runs")
	}
	if p.DockerMode == DockerHostSocket {
		out = append(out, "host docker socket mounted: any job on this pool can become root on the host")
	}
	if p.DockerMode == DockerDinD {
		out = append(out, DinDDanger)
	}
	if p.RunAsRoot {
		out = append(out, "runners execute as root inside the container")
	}
	return out
}

// Host is an agent process and the machine it runs on.
type Host struct {
	Connection string `json:"connection"`
	ID         string `json:"id"`
	Name       string `json:"name"`
	// Address is how the host reported itself; the controller never dials it.
	// Agents always connect outbound to the controller.
	Address string `json:"address,omitempty"`
	// Embedded marks the agent that runs inside the controller process.
	Embedded bool `json:"embedded"`
	// Capacity is the maximum number of concurrent runners this host accepts.
	Capacity int `json:"capacity"`
	// Backends lists the runner backends this host can actually service. It is
	// what a pool's backend is matched against, so it holds only the kinds the
	// agent found available.
	Backends StringSlice `json:"backends"`
	// BackendInfo is the agent's last full probe, including the backends that
	// were not available and why. It is what the UI shows an operator whose
	// host is not taking work; the scheduler reads Backends, never this.
	BackendInfo HostBackends `json:"backend_info,omitempty"`
	Labels      StringMap    `json:"labels"`
	// OS is the kernel the agent runs on (Go's GOOS), kept as reported so an
	// operator sees what the machine said about itself.
	OS string `json:"os"`
	// Distro and OSVersion are the distribution and release, which is what
	// decides whether an Ubuntu 24.04 pool may be placed here.
	Distro    string `json:"distro,omitempty"`
	OSVersion string `json:"os_version,omitempty"`
	Arch      string `json:"arch"`
	// CPUs and MemoryMB are the machine's size, reported by the agent. They
	// are what the host's canonical name and the Hosts page say out loud.
	CPUs     int       `json:"cpus,omitempty"`
	MemoryMB int64     `json:"memory_mb,omitempty"`
	Usage    HostUsage `json:"usage,omitempty"`
	// Throttle is the controller's answer to a host that its measurements say
	// is overwhelmed: how far it has stepped the host's admission and its
	// runners' CPU quotas down, and why. It is the controller's alone -- a
	// heartbeat carries the measurements it is decided from and never the
	// decision -- and it is written by its own statement, like the reserve.
	Throttle HostThrottle `json:"throttle,omitempty"`
	// Incidents is the runtime cooldown the agent last reported and the
	// last image that would not pull here. Each half has its own setter;
	// neither UpdateHost nor SetHostReported writes it.
	Incidents HostIncidents `json:"incidents,omitempty"`
	// DiskTotalMB and DiskFreeMB measure the filesystem holding the agent's
	// work directory, which is where a runner's checkout and its caches land.
	// Free is what a runner may use rather than what is unused, since the two
	// differ by the reserve the filesystem keeps for root.
	//
	// Zero is "not measured": an agent too old to report it, or one on a
	// platform with no portable way to ask. It is not "full", and nothing may
	// read it as such -- refusing to place work on every host that predates
	// the field would empty a fleet on upgrade.
	DiskTotalMB int64 `json:"disk_total_mb,omitempty"`
	DiskFreeMB  int64 `json:"disk_free_mb,omitempty"`
	// ReserveCPUs, ReserveMemoryMB and ReserveDiskMB are the operator's, like
	// Capacity: what to hold back from placement for the machine's own sake.
	// An agent reports what it sees and never writes these, so a host cannot
	// talk its way out of the room its operator kept for it.
	ReserveCPUs     int    `json:"reserve_cpus,omitempty"`
	ReserveMemoryMB int64  `json:"reserve_memory_mb,omitempty"`
	ReserveDiskMB   int64  `json:"reserve_disk_mb,omitempty"`
	Version         string `json:"version"`
	// Features is what the agent says it can do beyond running a backend,
	// re-read from every heartbeat. An agent that advertises "elastic-cpu"
	// can move a live runner's CPU quota; one that does not keeps every runner
	// of an elastic pool at its guaranteed share, and the pool cannot tell.
	// Recorded so the question is answered while a pool is being edited and
	// on the host's own card, not by the next heartbeat after the fact.
	Features StringSlice `json:"features"`
	// Cordoned hosts keep their existing runners but accept no new ones.
	Cordoned bool `json:"cordoned"`
	// ProtocolVersion is the agent protocol this host last reported speaking,
	// or 0 from an agent old enough not to say. Incompatible is what this
	// controller concluded from it.
	//
	// Incompatible excludes the host from placement exactly as a cordon does,
	// and does nothing else: its runners keep working, its agent keeps
	// draining and stopping them, and nothing is refused. A protocol mismatch
	// answered by refusing the heartbeat would restart every agent in the
	// fleet at once, which is the outage the upgrade was meant to avoid.
	ProtocolVersion int       `json:"protocol_version,omitempty"`
	Incompatible    bool      `json:"incompatible"`
	LastHeartbeat   time.Time `json:"last_heartbeat"`
	CreatedAt       time.Time `json:"created_at"`
	// TokenHash authenticates the agent on every request.
	TokenHash string `json:"-"`
	// AgentSessionID is the session the agent last identified itself with, and
	// AgentSessionPrev the one before it. An agent mints a session when it
	// starts, so a restart moves the id forward once and never back.
	//
	// Seeing AgentSessionPrev again is therefore something one agent cannot
	// do: it means two of them share this host's credentials -- a cloned VM,
	// or a copied state directory -- and are splitting its tasks.
	// AgentSessionAlternations counts how often that has happened and
	// AgentSessionAltAt when it last did, so the problem ages out on its own
	// once the duplicate is gone.
	AgentSessionID           string     `json:"agent_session_id,omitempty"`
	AgentSessionPrev         string     `json:"-"`
	AgentSessionAlternations int        `json:"agent_session_alternations,omitempty"`
	AgentSessionAltAt        *time.Time `json:"agent_session_alt_at,omitempty"`
	// Live counters, filled by the store on read.
	ActiveRunners int `json:"active_runners"`
	// UnlimitedRunners is how many of those live runners were created with no
	// CPU quota: a pool with none and defaults off, a process-backend pool, a
	// host whose daemon cannot apply one, or a row from before allocations
	// were recorded. They are the runners a sustained CPU hold can mean
	// something about -- a host whose every runner is inside its quota is
	// running the work it was sized for, however busy that looks.
	UnlimitedRunners int `json:"unlimited_runners,omitempty"`
}

// Platform is what this machine is, in the terms a pool asks in.
//
// The distribution wins over the kernel: "linux" cannot pick an image, and a
// pool asking for Ubuntu 24.04 needs to know it landed on Ubuntu. macOS and
// Windows report no distribution, so for them the kernel is the answer.
func (h *Host) Platform() Platform {
	os := h.Distro
	if naming.NormalizeOS(os) == "" {
		os = h.OS
	}
	return Platform{OS: os, OSVersion: h.OSVersion, Arch: h.Arch}.Normalized()
}

// Spec is the host in the naming grammar's terms: how much machine it is, what
// it runs, and which machine it is.
//
// The machine part is taken back out of a name that is already canonical, so
// that re-deriving a host's name yields the name it already has rather than
// nesting one inside the other on every heartbeat.
func (h *Host) Spec() naming.Spec {
	machine := h.Name
	if parsed, ok := naming.Parse(machine); ok {
		machine = parsed.Suffix
	}
	p := h.Platform()
	return naming.Spec{
		CPUs:     float64(h.CPUs),
		MemoryGB: int(h.MemoryMB / 1024),
		OS:       p.OS,
		Version:  p.OSVersion,
		Arch:     p.Arch,
		Suffix:   machine,
	}
}

// CanonicalName is the name this machine would be given by `zoomies agent
// join` today, which is what the UI offers when a host is called something
// that says nothing.
func (h *Host) CanonicalName() string { return h.Spec().String() }

// HeartbeatTimeout is how long a host may go silent before it is considered
// unhealthy. It is three times the agent's default heartbeat interval.
const HeartbeatTimeout = 90 * time.Second

// Healthy reports whether the agent has checked in recently enough.
func (h *Host) Healthy(now time.Time) bool {
	return now.Sub(h.LastHeartbeat) < HeartbeatTimeout
}

// Available reports whether the scheduler may place a new runner here.
func (h *Host) Available(now time.Time) bool {
	return h.Healthy(now) && !h.Cordoned && h.ActiveRunners < h.EffectiveCapacity()
}

// EffectiveCapacity is how many runners this host takes right now: its
// configured capacity, stepped down by an active throttle. Capacity is the
// operator's and the throttle never writes it; this is the two read together,
// and it is what every slot count on the host is measured against while the
// throttle stands.
//
// It never falls below one while the capacity is at least one. A throttle is
// a host being pushed too hard, not a host being taken out of the fleet: the
// pressure holds already refuse every new start while the pressure is acute,
// and the throttle is what outlasts them. A host it took to zero would look
// exactly like a cordon, and an operator reading "0 slots" would go looking
// for who cordoned it.
func (h *Host) EffectiveCapacity() int {
	if h.Capacity <= 0 || !h.Throttle.Active() {
		return h.Capacity
	}
	return max(1, int(math.Floor(float64(h.Capacity)*h.Throttle.Factor())))
}

// The selector keys every host answers for without an operator typing
// anything. The agent reports the OS and architecture of the machine it runs
// on, so a pool can ask for arm64 or windows without a fleet being hand
// labelled first -- which is what "label every ARM box before you can select
// one" used to cost.
const (
	LabelOS   = "os"
	LabelArch = "arch"
)

// SelectorValue returns what this host answers for one host-selector key.
//
// An operator's own label wins over the reported fact, so a fleet that already
// labels `arch` by hand keeps the meaning it chose -- including a deliberate
// lie, like calling an amd64 box `arch=legacy` to keep pools off it. Only when
// no label claims the key does the agent's report answer for it.
func (h *Host) SelectorValue(key string) string {
	if v, ok := h.Labels[key]; ok {
		return v
	}
	switch key {
	case LabelOS:
		return h.OS
	case LabelArch:
		return h.Arch
	}
	return ""
}

// Free returns the number of additional runners this host can take, against
// its effective capacity: a throttled host has fewer slots free than its
// configured capacity would say, and that is the number the scheduler and the
// Hosts page both have to use, or the page promises slots the pass refuses.
func (h *Host) Free() int {
	if n := h.EffectiveCapacity() - h.ActiveRunners; n > 0 {
		return n
	}
	return 0
}

// Where a runner's resource limits came from.
const (
	// AllocationFromPool means the pool set the limit itself.
	AllocationFromPool = "pool"
	// AllocationFromHost means the pool left the limit unset and the runner
	// was given one slot's share of the host it was placed on.
	AllocationFromHost = "host"
	// AllocationReduced means no host had room for the pool's standard size,
	// and the runner was given what one could spare, at or above the pool's
	// minimum. The figures on the row are what it was given, and what its
	// host is charged for it.
	AllocationReduced = "reduced"
	// AllocationHistory means the runner was sized up, above the host's share,
	// to what the jobs waiting on its pool are known to need from their recent
	// runs (scheduler.history_sizing=on). Like a reduced runner, the figures
	// on the row are what it was given and what its host is charged.
	AllocationHistory = "history"
)

// Runner is one runner instance: a row that the controller creates in
// "provisioning" and an agent then materialises, reports on, and tears down.
type Runner struct {
	ID     string      `json:"id"`
	PoolID string      `json:"pool_id"`
	HostID string      `json:"host_id"`
	Name   string      `json:"name"`
	State  RunnerState `json:"state"`
	// GitHubRunnerID is assigned once GitHub acknowledges the registration.
	GitHubRunnerID int64 `json:"github_runner_id,omitempty"`
	// ContainerID (or PID, for the process backend) identifies the workload
	// on the host. Opaque to the controller.
	ContainerID   string      `json:"container_id,omitempty"`
	Ephemeral     bool        `json:"ephemeral"`
	Labels        StringSlice `json:"labels"`
	Image         string      `json:"image,omitempty"`
	ImageDigest   string      `json:"image_digest,omitempty"`
	RunnerVersion string      `json:"runner_version,omitempty"`
	// CurrentJobID points at the jobs row this runner is executing, if any.
	CurrentJobID       string         `json:"current_job_id,omitempty"`
	CreatedAt          time.Time      `json:"created_at"`
	ImagePullDuration  *time.Duration `json:"image_pull_duration,omitempty"`
	ContainerStartedAt *time.Time     `json:"container_started_at,omitempty"`
	RegisteredAt       *time.Time     `json:"registered_at,omitempty"`
	// TaskIssuedAt is when this runner's lifecycle task was last handed to its
	// host, stamped again on every redelivery.
	//
	// The task queue is in memory by design, so a controller restart drops it.
	// What the restart must not drop is the time: without this a provisioning
	// row is indistinguishable from one whose create was issued a second ago,
	// and the provision timeout is counted from the wrong end.
	TaskIssuedAt *time.Time `json:"task_issued_at,omitempty"`
	// CreateTaskIssuedAt is the first delivery to the host, never enqueue or retry.
	CreateTaskIssuedAt *time.Time `json:"create_task_issued_at,omitempty"`
	HostRemovedAt      *time.Time `json:"host_removed_at,omitempty"`
	// CleanupEstimatedAt preserves pre-RC timestamps that did not require both confirmations.
	CleanupEstimatedAt *time.Time `json:"cleanup_estimated_at,omitempty"`
	// CleanupError, CleanupFailedAt and CleanupAttempts record a stop or
	// remove the agent could not complete, or a registration GitHub would not
	// delete.
	//
	// They exist because a terminal row had nowhere to put that. The result
	// came back for a runner already marked removed, the state machine refused
	// the transition -- correctly; a removed runner cannot become failed -- and
	// it was dropped at debug level. The container stayed on the host and
	// nobody was told.
	CleanupError    string     `json:"cleanup_error,omitempty"`
	CleanupFailedAt *time.Time `json:"cleanup_failed_at,omitempty"`
	CleanupAttempts int        `json:"cleanup_attempts,omitempty"`
	// HostCleanupError and RegistrationCleanupError are the two halves
	// CleanupError is joined from: what the host said about its container,
	// and what GitHub said about the registration. They are kept apart
	// because the two need different things done, and one sentence read
	// back for a keyword could only say one of them -- a busy registration
	// named alongside a container still on its host was all an operator was
	// told about, and the container was the part that needed them.
	HostCleanupError         string `json:"host_cleanup_error,omitempty"`
	RegistrationCleanupError string `json:"registration_cleanup_error,omitempty"`
	// RegistrationDeletedAt is when GitHub confirmed the registration was gone.
	// Unset on a terminal runner is the ghost: a row this fleet has finished
	// with, and a registration still on somebody's organisation.
	RegistrationDeletedAt *time.Time `json:"registration_deleted_at,omitempty"`
	// CleanedUpAt is the end of the cleanup interval: the moment nothing of
	// this runner is left, on the host or on GitHub. It is the counterpart of
	// CreatedAt at the other end of the life, and the measurement contract's
	// end of that interval.
	CleanedUpAt *time.Time `json:"cleaned_up_at,omitempty"`
	// DrainingSince is when the runner entered draining, and is the clock the
	// drain timeout is counted from. Created-at is the wrong one: a runner that
	// worked all day before being drained is not overdue the moment it drains.
	DrainingSince *time.Time `json:"draining_since,omitempty"`
	StartedAt     *time.Time `json:"started_at,omitempty"`
	// LastIdleAt is when the runner most recently became idle; the scale-down
	// path measures the idle timeout from here.
	LastIdleAt  *time.Time `json:"last_idle_at,omitempty"`
	FinishedAt  *time.Time `json:"finished_at,omitempty"`
	Message     string     `json:"message,omitempty"`
	JobsHandled int        `json:"jobs_handled"`
	// ResourceSample carries sample freshness and optional runtime diagnostics.
	ResourceSample json.RawMessage `json:"resource_sample,omitempty"`
	// CPUPercent and MemoryBytes are best-effort samples from the agent.
	CPUPercent  float64 `json:"cpu_percent,omitempty"`
	MemoryBytes int64   `json:"memory_bytes,omitempty"`
	// AllocatedCPUs and AllocatedMemoryMB are the limits this runner's
	// workload was created with, and AllocationSource says whether they came
	// from the pool's own resources or from the host's default share of its
	// machine. They are recorded here rather than recomputed because the
	// question they answer is historical: a runner killed for exceeding a
	// memory limit needs to say which limit, and a pool edited since or a host
	// whose capacity moved would give a different answer today. Zero and
	// empty on rows from before the allocation was recorded.
	AllocatedCPUs     float64 `json:"allocated_cpus,omitempty"`
	AllocatedMemoryMB int64   `json:"allocated_memory_mb,omitempty"`
	AllocationSource  string  `json:"allocation_source,omitempty"`
	// SizedForCPUs is the CPU count the runner's toolchains were told to size
	// their workers for when it started (see CPUBurstPolicy.SizeForCeiling),
	// or zero when they were told nothing. Recorded rather than recomputed,
	// because a pool edited since would give a different answer than the one
	// the running job was started with.
	SizedForCPUs int `json:"sized_for_cpus,omitempty"`
	// FaultKind categorises why a failed runner failed. Message says it in the
	// backend's or GitHub's own words; this is what makes "every runner in this
	// pool fails to start, and always for the same reason" visible from
	// anywhere but one runner's page.
	FaultKind FaultKind `json:"fault_kind,omitempty"`
}

// Age returns how long the runner has existed.
func (r *Runner) Age(now time.Time) time.Duration { return now.Sub(r.CreatedAt) }

// IdleFor returns how long the runner has been idle, or 0 if it is not idle.
func (r *Runner) IdleFor(now time.Time) time.Duration {
	if r.State != RunnerIdle || r.LastIdleAt == nil {
		return 0
	}
	return now.Sub(*r.LastIdleAt)
}

// The provisioning states an operator can put a queued job into. The empty
// string is the fourth and the default: ready, provisioning demand as usual.
const (
	// ProvisioningPaused holds a job's demand without taking the job out of
	// the queue. It is still waiting, and resuming it is one click.
	ProvisioningPaused = "paused"
	// ProvisioningDeleted is the operator saying this work should not be run
	// here at all. It is restorable, which is why the row survives, but until
	// it is restored the job is no longer part of what the fleet is waiting on.
	ProvisioningDeleted = "deleted"
)

// Job is a GitHub Actions workflow job as Zoomies observed it.
type Job struct {
	// Provisioning is operator-owned and never overwritten by GitHub deliveries.
	// Empty means ready; paused and deleted suppress this job's scale-up demand.
	Provisioning string `json:"provisioning"`
	ProvisionNow bool   `json:"provision_now"`
	// CancelRequestedAt is when an operator's cancellation of this job's
	// workflow run was accepted by GitHub. Like Provisioning it is the fleet's
	// own note, never written by a delivery, because GitHub's completion event
	// is still what settles the conclusion -- and that event can be minutes
	// behind, which is exactly the window this exists to describe.
	CancelRequestedAt *time.Time `json:"cancel_requested_at,omitempty"`

	ID          string      `json:"id"`
	GitHubJobID int64       `json:"github_job_id"`
	GitHubRunID int64       `json:"github_run_id"`
	Repo        string      `json:"repo"`     // "acme/widgets"
	Workflow    string      `json:"workflow"` // workflow name
	JobName     string      `json:"job_name"`
	Labels      StringSlice `json:"labels"`
	State       JobState    `json:"state"`
	Conclusion  string      `json:"conclusion,omitempty"` // success|failure|cancelled|skipped
	// InstallationID is the installation whose GitHub App covers this job's
	// repository, resolved at ingest. It is what stops a pool from claiming
	// work in a target it has no credentials for; empty means no installation
	// here covers the repository, which is a reason rather than a wildcard.
	InstallationID string     `json:"installation_id,omitempty"`
	PoolID         string     `json:"pool_id,omitempty"`
	RunnerID       string     `json:"runner_id,omitempty"`
	RunnerName     string     `json:"runner_name,omitempty"`
	HTMLURL        string     `json:"html_url,omitempty"`
	QueuedAt       time.Time  `json:"queued_at"`
	StartedAt      *time.Time `json:"started_at,omitempty"`
	CompletedAt    *time.Time `json:"completed_at,omitempty"`
	// Matched records whether any enabled pool claimed this job's labels. An
	// unmatched queued job is a configuration problem worth surfacing.
	Matched bool `json:"matched"`
	// EligibleAt is when this job first became something this fleet could act
	// on, which is the start of the scheduling-latency interval the
	// measurement contract defines. It is stamped the first time Matched
	// becomes true and never moved afterwards.
	//
	// Nil is "not eligible yet", or a job from before the column existed. It
	// is deliberately not zero: a zero time reads as 1970 and would make every
	// latency computed from it enormous rather than obviously absent.
	//
	// The interval it starts ends at Runner.TaskIssuedAt. Neither the queue
	// wait before eligibility nor a configured scale-up delay belongs in it --
	// the first is GitHub's and the operator's, the second is a setting doing
	// what it was set to do.
	EligibleAt *time.Time `json:"eligible_at,omitempty"`
	// HeadBranch, HeadSHA and RunAttempt say what the job ran for. A failure
	// on a release branch and one on a feature branch are different news.
	HeadBranch string `json:"head_branch,omitempty"`
	HeadSHA    string `json:"head_sha,omitempty"`
	RunAttempt int    `json:"run_attempt,omitempty"`
	// RunNumber is GitHub's own sequential number for the workflow run this job
	// belongs to -- the "#1009" its Actions UI shows next to the workflow name,
	// so an operator can find the same run there. workflow_job deliveries never
	// carry it, so it arrives late, backfilled from a workflow_run lookup once
	// one is made; zero means that lookup has not happened yet.
	RunNumber int64 `json:"run_number,omitempty"`
	// Steps are the job's steps as GitHub last reported them. The completed
	// delivery carries every step with its conclusion, which is how a failed
	// job can say which step it stopped at.
	Steps JobSteps `json:"steps"`
	// RunnerFault is the fleet's own side of a failure: what the runner that
	// was executing this job said when it stopped before GitHub reported the
	// job over. GitHub records such a job as "failure" like any test failure;
	// this is what tells "the tests failed" from "the runner died".
	RunnerFault string `json:"runner_fault,omitempty"`
	// FaultKind is the same fact as a category, so a thousand of these can be
	// counted rather than only read one at a time. It is set with RunnerFault
	// and never without it; empty means the fleet has nothing to confess.
	FaultKind FaultKind `json:"fault_kind,omitempty"`
	// ControllerVersion, ControllerChannel, AgentVersion and HostID say which
	// build ran the job and where, so that jobs can be compared across
	// releases. They are stamped once by StampJobVersions -- the controller's
	// pair when a pool claims the job, the host's pair when a runner takes it --
	// and never rewritten by a later delivery. Empty on a job recorded before
	// migration 0060, and on one nothing here ever claimed; neither is
	// backfilled, because no timestamp says which release was running.
	ControllerVersion string `json:"controller_version,omitempty"`
	ControllerChannel string `json:"controller_channel,omitempty"`
	AgentVersion      string `json:"agent_version,omitempty"`
	HostID            string `json:"host_id,omitempty"`
	// PeakCPUs and PeakMemoryMB are the most the job's runner was measured
	// using while the job ran on it; zero is "never measured". They are what
	// the next run of the same job is sized and placed from.
	PeakCPUs     float64 `json:"peak_cpus,omitempty"`
	PeakMemoryMB int64   `json:"peak_memory_mb,omitempty"`
	// OOMKilled says the kernel killed the runner, or a step's process inside
	// it, for its memory limit while this job ran. A killed job's peak is the
	// limit it hit rather than what it needed, which the profile allows for.
	OOMKilled bool `json:"oom_killed,omitempty"`
}

// JobStep is one step of a workflow job as GitHub reported it.
type JobStep struct {
	Number      int        `json:"number"`
	Name        string     `json:"name"`
	Status      string     `json:"status"` // queued | in_progress | completed
	Conclusion  string     `json:"conclusion,omitempty"`
	StartedAt   *time.Time `json:"started_at,omitempty"`
	CompletedAt *time.Time `json:"completed_at,omitempty"`
}

// JobSteps is persisted as a JSON array in a TEXT column.
type JobSteps []JobStep

func (s *JobSteps) Scan(v any) error {
	*s = nil
	switch t := v.(type) {
	case nil:
		return nil
	case []byte:
		if len(t) == 0 {
			return nil
		}
		return json.Unmarshal(t, s)
	case string:
		if t == "" {
			return nil
		}
		return json.Unmarshal([]byte(t), s)
	}
	return fmt.Errorf("store: cannot scan %T into JobSteps", v)
}

func (s JobSteps) Value() (driver.Value, error) {
	if s == nil {
		s = JobSteps{}
	}
	b, err := json.Marshal([]JobStep(s))
	return string(b), err
}

// JobEventKind names one thing that happened to a job.
type JobEventKind string

const (
	// JobEventQueued: GitHub announced the job and it is waiting for a runner.
	JobEventQueued JobEventKind = "queued"
	// JobEventWaiting: GitHub is holding the job for a deployment review, so
	// nothing here can start it yet. The time it spends here is GitHub's, and
	// the timeline says so rather than folding it into the queue wait.
	JobEventWaiting JobEventKind = "waiting"
	// JobEventApproved: the review passed and the job joined the queue. This
	// is the moment the queue wait starts for a job that was held.
	JobEventApproved JobEventKind = "approved"
	// JobEventClaimed: an enabled pool answers the job's labels.
	JobEventClaimed JobEventKind = "claimed"
	// JobEventUnmatched: no enabled pool does, so nothing here will start it.
	JobEventUnmatched JobEventKind = "unmatched"
	// JobEventStarted: a runner picked the job up.
	JobEventStarted JobEventKind = "started"
	// JobEventCompleted: GitHub reported the job over, with its conclusion.
	JobEventCompleted JobEventKind = "completed"
	// JobEventRunnerLost: the runner executing the job stopped before GitHub
	// reported the job over. This is the fleet's fault, not the workflow's.
	JobEventRunnerLost JobEventKind = "runner_lost"
	// JobEventRunnerReturned: the runner reported lost is alive after all, and
	// this job is still running on it. It only ever follows a runner_lost on
	// the same job, and it exists because the timeline had no way to withdraw
	// one: a job that finishes normally after its runner was written off read
	// as a contradiction, and an operator had to guess which entry to believe.
	JobEventRunnerReturned JobEventKind = "runner_returned"
	// JobEventCancelRequested records an operator request sent to GitHub. The
	// eventual completed event remains authoritative for the outcome.
	JobEventCancelRequested JobEventKind = "cancel_requested"
	// JobEventRunnerStartFailed: a runner this pool started for work like this
	// one died before it could take a job. The job itself is untouched -- it is
	// still queued, and the next runner may well run it -- which is exactly why
	// it needs saying. A pool that cannot start a container looks, from the
	// job's side, identical to a pool that is merely busy, and an operator
	// watching a queue that never moves had nowhere to find out which.
	JobEventRunnerStartFailed JobEventKind = "runner_start_failed"
	// JobEventRerunRequested records a re-run this fleet asked GitHub for. As
	// with a cancel, GitHub remains authoritative: the re-run arrives as new
	// jobs with a higher run attempt, and this entry is only the record that
	// somebody here asked.
	JobEventRerunRequested JobEventKind = "rerun_requested"
	// JobEventOOMKilled records the kernel killing the job's runner, or one of
	// its steps, for its memory limit. It may land after completed: a runner
	// whose step was killed finishes the job and says so only as it exits.
	JobEventOOMKilled JobEventKind = "oom_killed"
)

// JobEvent is one entry in a job's timeline: what happened, who observed it,
// and the sentence the UI shows for it.
type JobEvent struct {
	ID    string       `json:"id"`
	JobID string       `json:"job_id"`
	Kind  JobEventKind `json:"kind"`
	// Source is who saw it happen: "webhook", "poller", "agent" or
	// "controller". A timeline that is all "poller" is a controller that no
	// webhook is reaching, which is worth being able to see.
	Source     string    `json:"source"`
	Message    string    `json:"message"`
	RunnerID   string    `json:"runner_id,omitempty"`
	RunnerName string    `json:"runner_name,omitempty"`
	At         time.Time `json:"at"`
}

// JobChange reports what an upsert actually changed, so the caller can write
// the timeline from the transition rather than from the delivery: webhook
// deliveries are at-least-once, and a redelivered "queued" must not add a
// second "queued" entry.
type JobChange struct {
	// Created is true when the store had never seen this job.
	Created bool
	// PreviousState is the state before the upsert; empty when Created.
	PreviousState JobState
	// StateChanged is true when the job moved forward through its lifecycle.
	StateChanged bool
	// Claimed is true when the job was unclaimed before and a pool claims it now.
	Claimed bool
	// RunnerLinked is true when the job was linked to one of this fleet's
	// runner rows for the first time.
	RunnerLinked bool
}

// FailedConclusions are the GitHub conclusions that count a job as failed
// wherever Zoomies says "failed": the Overview's count, the Jobs page's filter
// and Job.Failed. cancelled and skipped are not here, because a person or a
// condition on the job chose them; nor is stale, Zoomies' own word for a job
// GitHub stopped talking about. The UI keeps the same list in status.ts.
var FailedConclusions = []string{"failure", "timed_out", "startup_failure"}

// IsFailedConclusion reports whether a conclusion is one of FailedConclusions.
func IsFailedConclusion(conclusion string) bool {
	return slices.Contains(FailedConclusions, conclusion)
}

// Failed reports whether a job went wrong on either side: GitHub concluded it
// did, or a runner of this fleet stopped under it, which GitHub may still be
// waiting to hear about. It is the Go spelling of the SQL predicate the store's
// queries use, so a count and a listing cannot disagree.
func (j *Job) Failed() bool {
	return IsFailedConclusion(j.Conclusion) || j.RunnerFault != ""
}

// FailedStep returns the step a job stopped at: the first step that did not
// succeed, on a job that has completed. Nil when every step succeeded or was
// skipped, or while the job is still running.
//
// It says where, not whether. Whether a job counts as failed is Failed's call,
// made from the job's own conclusion; this is set for a cancelled job too,
// because its completion message says which step the cancel landed in. The
// first step that did not succeed is the one whose output the operator wants,
// because every step after it is skipped or cancelled as a consequence.
func (j *Job) FailedStep() *JobStep {
	if j.State != JobCompleted {
		return nil
	}
	for i := range j.Steps {
		st := &j.Steps[i]
		switch st.Conclusion {
		case "", "success", "skipped", "neutral":
			continue
		}
		return st
	}
	return nil
}

// Cancelling reports whether this job is on its way out because somebody
// cancelled its workflow run, and GitHub has not yet said so.
//
// GitHub owns the conclusion, so the row still reads `queued` or `in_progress`
// for as long as its completion delivery takes -- and the fleet used to report
// the job as waiting or running for that whole window. It is neither: the
// queued half raises no demand and the running half has had its runner taken
// away. Once the job completes this is history, and the conclusion says what
// happened.
func (j *Job) Cancelling() bool {
	return j.CancelRequestedAt != nil && j.State != JobCompleted
}

// RemovedFromQueue reports whether an operator took this job out of the queue.
//
// Zoomies cannot unqueue a job at GitHub, so the row stays `queued` for as
// long as GitHub keeps offering it -- which is why every figure that answers
// "how much work is waiting?" has to exclude these by hand. An operator who
// empties the queue and then reads a queue depth of forty on the Overview has
// been told the removal did nothing. A paused job is not removed: it is on
// hold, still waiting, and the Queue page lists it by default.
func (j *Job) RemovedFromQueue() bool { return j.Provisioning == ProvisioningDeleted }

// QueueWait returns how long the job waited before a runner picked it up.
func (j *Job) QueueWait() time.Duration {
	if j.StartedAt == nil {
		return 0
	}
	return j.StartedAt.Sub(j.QueuedAt)
}

// Duration returns how long the job executed, or 0 if it has not finished.
func (j *Job) Duration() time.Duration {
	if j.StartedAt == nil || j.CompletedAt == nil {
		return 0
	}
	return j.CompletedAt.Sub(*j.StartedAt)
}

// AuditEvent records one mutating action, who performed it, and what changed.
type AuditEvent struct {
	ID         string    `json:"id"`
	ActorID    string    `json:"actor_id"`
	ActorName  string    `json:"actor_name"`
	ActorKind  string    `json:"actor_kind"` // user | token | agent | system | webhook
	Action     string    `json:"action"`     // "pool.create", "runner.drain", ...
	TargetKind string    `json:"target_kind"`
	TargetID   string    `json:"target_id"`
	Before     string    `json:"before,omitempty"` // JSON, secrets redacted
	After      string    `json:"after,omitempty"`
	IP         string    `json:"ip,omitempty"`
	CreatedAt  time.Time `json:"created_at"`
}

// CapacityDemandDelivery is the durable deduplication and delivery record for
// one kind of capacity signal for a pool.
type CapacityDemandDelivery struct {
	PoolID, EventType, EventID, Payload string
	ObservedSince                       time.Time
	AttemptedAt, DeliveredAt            *time.Time
	StatusCode, Attempts                int
	LastError                           string
}

// ScalingEvent records one scheduler decision, with the reason in the words the
// UI shows: "scaled linux-x64 2 -> 4: 3 jobs queued > 30s".
type ScalingEvent struct {
	ID        string    `json:"id"`
	PoolID    string    `json:"pool_id"`
	PoolName  string    `json:"pool_name"`
	From      int       `json:"from"`
	To        int       `json:"to"`
	Reason    string    `json:"reason"`
	CreatedAt time.Time `json:"created_at"`
}

// Direction returns "up", "down" or "hold".
func (e *ScalingEvent) Direction() string {
	switch {
	case e.To > e.From:
		return "up"
	case e.To < e.From:
		return "down"
	}
	return "hold"
}

// WebhookDelivery records one inbound webhook so that delivery failures are
// visible instead of silently dropped.
type WebhookDelivery struct {
	ID         string `json:"id"`
	DeliveryID string `json:"delivery_id"`
	Event      string `json:"event"`
	Action     string `json:"action,omitempty"`
	Repo       string `json:"repo,omitempty"`
	Status     string `json:"status"` // accepted | rejected | error
	Error      string `json:"error,omitempty"`
	// InstallationID is the installation whose webhook secret verified this
	// delivery. It is not necessarily the one that owns the repository: when
	// no installation covers the repository every configured secret is tried,
	// and knowing which one answered is how "your secrets are out of step with
	// your installations" is told from "this delivery was forged".
	InstallationID string    `json:"installation_id,omitempty"`
	ReceivedAt     time.Time `json:"received_at"`
}

// ControllerLease is the running control plane, as the database knows it.
//
// It is what a second controller reads before it starts: a file lock catches
// another process on the same host, and this catches the copy on a shared
// filesystem or on another machine, which no lock on this host can see.
type ControllerLease struct {
	// Holder is the controller instance, minted fresh on every start, so that
	// a restarted controller can tell its own old row from a live rival's.
	Holder string `json:"holder"`
	// Host, PID and Version are for the operator staring at the refusal: they
	// have to be able to go and find the thing that is already running.
	Host       string    `json:"host,omitempty"`
	PID        int       `json:"pid,omitempty"`
	Version    string    `json:"version,omitempty"`
	AcquiredAt time.Time `json:"acquired_at"`
	RenewedAt  time.Time `json:"renewed_at"`
}

// Stale reports whether a lease has not been renewed inside ttl, which is what
// lets a controller that was killed rather than stopped be replaced without an
// operator having to force it.
func (l *ControllerLease) Stale(now time.Time, ttl time.Duration) bool {
	return l == nil || !now.Before(l.RenewedAt.Add(ttl))
}

// Describe names the holder in the one sentence an operator gets.
func (l *ControllerLease) Describe() string {
	if l == nil {
		return "nobody"
	}
	where := l.Host
	if where == "" {
		where = "an unnamed host"
	}
	if l.PID > 0 {
		return fmt.Sprintf("%s (pid %d) on %s", l.Holder, l.PID, where)
	}
	return fmt.Sprintf("%s on %s", l.Holder, where)
}

// User is a local account authenticated with an argon2id password hash.
type User struct {
	ID           string `json:"id"`
	Username     string `json:"username"`
	Email        string `json:"email,omitempty"`
	DisplayName  string `json:"display_name,omitempty"`
	Role         Role   `json:"role"`
	PasswordHash string `json:"-"`
	// Subject is set for accounts provisioned through OIDC; such accounts have
	// no password hash and cannot log in with one.
	OIDCSubject string     `json:"oidc_subject,omitempty"`
	Disabled    bool       `json:"disabled"`
	CreatedAt   time.Time  `json:"created_at"`
	LastLoginAt *time.Time `json:"last_login_at,omitempty"`
	// MustChangePassword is set for the bootstrap admin created by the installer.
	MustChangePassword bool `json:"must_change_password"`
}

// Session is a browser login session, keyed by a hashed cookie value.
type Session struct {
	ID        string    `json:"id"`
	UserID    string    `json:"user_id"`
	TokenHash string    `json:"-"`
	UserAgent string    `json:"user_agent,omitempty"`
	IP        string    `json:"ip,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	ExpiresAt time.Time `json:"expires_at"`
}

// APIToken is a long-lived credential for automation, scoped by role and
// optionally limited to a set of pools.
type APIToken struct {
	ID   string `json:"id"`
	Name string `json:"name"`
	Role Role   `json:"role"`
	// OwnerRole is the role of the identity that minted this token, which is
	// not the same question as Role: 0045 promoted every administrator's token
	// to platform to keep what it could already do, so Role says what a token
	// may reach and this says whose it is. Empty means a token from before the
	// column existed, which is nobody's secret and stays visible to whoever
	// could see it before.
	OwnerRole Role   `json:"owner_role,omitempty"`
	UserID    string `json:"user_id,omitempty"`
	// Scopes optionally narrows a token further than its role, e.g.
	// ["pools:read", "runners:write"].
	Scopes     StringSlice `json:"scopes"`
	TokenHash  string      `json:"-"`
	Prefix     string      `json:"prefix"` // first chars, shown in the UI to identify a token
	CreatedAt  time.Time   `json:"created_at"`
	ExpiresAt  *time.Time  `json:"expires_at,omitempty"`
	LastUsedAt *time.Time  `json:"last_used_at,omitempty"`
	Revoked    bool        `json:"revoked"`
}

// Expired reports whether the token is past its expiry.
func (t *APIToken) Expired(now time.Time) bool {
	return t.ExpiresAt != nil && now.After(*t.ExpiresAt)
}

// JoinToken is a short-lived, single-use credential that lets a new agent
// register itself with the controller.
type JoinToken struct {
	ID        string     `json:"id"`
	TokenHash string     `json:"-"`
	Prefix    string     `json:"prefix"`
	CreatedBy string     `json:"created_by"`
	Labels    StringMap  `json:"labels"`
	Capacity  int        `json:"capacity"`
	CreatedAt time.Time  `json:"created_at"`
	ExpiresAt time.Time  `json:"expires_at"`
	UsedAt    *time.Time `json:"used_at,omitempty"`
	UsedByID  string     `json:"used_by_id,omitempty"`
	// MachineID and ExpectedName scope a token to the one machine it was
	// minted for. Empty on the tokens an operator hands out by hand, which are
	// theirs to look after; set on the ones that travel inside a guest, where
	// the credential is readable by more people than the person who asked for
	// it. Scoping is what stops a copied VM image enrolling as somebody else.
	MachineID    string `json:"machine_id,omitempty"`
	ExpectedName string `json:"expected_name,omitempty"`
}

// Usable reports whether the token can still be redeemed.
func (t *JoinToken) Usable(now time.Time) bool {
	return t.UsedAt == nil && now.Before(t.ExpiresAt)
}

// Setting is a single key/value row in the settings table. Values marked secret
// are stored sealed and never leave the process in plaintext.
type Setting struct {
	Key       string    `json:"key"`
	Value     string    `json:"value"`
	Secret    bool      `json:"secret"`
	UpdatedAt time.Time `json:"updated_at"`
}

// ---------------------------------------------------------------------------
// Label matching
// ---------------------------------------------------------------------------

// ImplicitLabels are the labels the actions/runner binary always advertises.
// Workflows list them in runs-on, but they say nothing about what a pool must
// provide, so matching ignores them.
var ImplicitLabels = map[string]bool{
	"self-hosted": true,
	"linux":       true,
	"windows":     true,
	"macos":       true,
	"x64":         true,
	"arm":         true,
	"arm64":       true,
}

// NormalizeLabel lowercases and trims a label. GitHub treats runner labels
// case-insensitively, and operators reliably get the case wrong.
func NormalizeLabel(s string) string { return strings.ToLower(strings.TrimSpace(s)) }

// NormalizeLabels returns a de-duplicated, lowercased, sorted copy.
//
// Pool and job labels are normalized once on the way out of the store
// (queries_fleet.go, queries_events.go), so most calls -- above all
// internal/scheduler's Matches/Score/Eligible, which compare every queued
// job against every pool on each reconcile tick -- pass a slice that is
// already normalized. isNormalized checks that in a single allocation-free
// pass and lets that common case skip the map and sort below entirely.
func NormalizeLabels(in []string) []string {
	if len(in) > 0 && isNormalized(in) {
		return in
	}
	seen := make(map[string]bool, len(in))
	out := make([]string, 0, len(in))
	for _, l := range in {
		n := NormalizeLabel(l)
		if n == "" || seen[n] {
			continue
		}
		seen[n] = true
		out = append(out, n)
	}
	slices.Sort(out)
	return out
}

// isNormalized reports whether in is already de-duplicated, lowercased, and
// strictly increasing -- i.e. exactly what NormalizeLabels would produce from
// it. Strictly increasing (rather than merely sorted) is what rules out a
// duplicate in the same pass as the ordering check.
func isNormalized(in []string) bool {
	for i, l := range in {
		if l == "" || NormalizeLabel(l) != l {
			return false
		}
		if i > 0 && in[i-1] >= l {
			return false
		}
	}
	return true
}

// The floors under a host's reserve. An operator's reserve is what to hold
// back from placement for the machine's own sake, and zero is not a safe
// answer for two of the three resources. A host with no memory left over for
// the kernel and its page cache does not run jobs slowly, it has one of them
// killed; a work directory with nothing left on it fails a checkout before a
// job's first step. Both failures land on a job rather than on the machine, so
// the operator who did not set a reserve never learns it was theirs to set.
//
// CPU has a floor too, and it is there for the daemon rather than for the
// jobs. A CPU quota is a share of the one resource that is never exhausted,
// only contended, and a contended machine does still finish the job -- but
// the runners' quotas are not the only thing on the machine. dockerd,
// containerd and the agent have to answer in the gaps the quotas leave, and a
// host whose quotas add up to every core leaves none: the daemon stops
// answering, creates time out, and the fleet reads a busy host as a broken
// one. Half a core, or a twentieth of the machine on a large one, is what
// those three need to keep answering while every runner is flat out.
const (
	MinHostReserveMemoryMB int64 = 512
	// MinHostReserveMemoryFraction raises the memory reserve in step with the
	// machine, exactly as the CPU fraction below does and for the same reason.
	// A flat 512 MB is the right floor on a small box and far too little on a
	// large one: a 64 GB host booked down to its last half gigabyte has no
	// page cache left, and the daemon minding sixty-four containers is the
	// first thing to suffer for it. It is capped, because a tenth of a very
	// large machine is more than the daemon will ever want -- MaxHostReserveMemoryMB
	// is where holding more back stops buying anything.
	MinHostReserveMemoryFraction float64 = 0.05
	MaxHostReserveMemoryMB       int64   = 8192
	MinHostReserveDiskMB         int64   = 2048
	// MinHostReserveCPUs is the least CPU held back from placement, and
	// MinHostReserveCPUFraction raises it in step with the machine: a
	// sixty-four core host runs a daemon with sixty-four containers to mind.
	MinHostReserveCPUs        float64 = 0.5
	MinHostReserveCPUFraction float64 = 0.05
)

// The controller's own room, held back on top of the floors above on the one
// host it runs on.
//
// The floors are sized for dockerd, containerd and the agent. On the host
// whose agent is embedded, the controller is on the machine too -- the
// scheduler, the single database writer every heartbeat and webhook waits on,
// the API and the event stream -- and it answers in the same gaps. A twelve
// core host held back six tenths of a core for all of that, and with its
// runners flat out that was the controller's share of the machine: the fleet
// slowed down at the moment it was busiest, because what schedules it was
// starved by what it had scheduled. A core and a gigabyte is enough for the
// controller to keep answering; it is added to the floor rather than folded
// into it, so a small host is not left with less for its daemon than it had.
const (
	ControllerReserveCPUs     float64 = 1
	ControllerReserveMemoryMB int64   = 1024
)

// MemoryReserve is what is held back from placement on this host's memory: the
// operator's reserve, or the floor when that is larger. Zero on a host that
// has not reported its memory, where there is nothing to hold back from.
//
// It is a function rather than a constant for the reason CPUReserve is: the
// floor depends on the machine, and a caller that applied a flat figure to a
// 64 GB box and a 2 GB one would be wrong about one of them.
func (h *Host) MemoryReserve() int64 {
	if h.MemoryMB <= 0 {
		return 0
	}
	floor := min(max(MinHostReserveMemoryMB, int64(MinHostReserveMemoryFraction*float64(h.MemoryMB))), MaxHostReserveMemoryMB)
	if h.Embedded {
		floor += ControllerReserveMemoryMB
	}
	return max(h.ReserveMemoryMB, floor)
}

// The least machine a runner can be given and still be one.
//
// Below these the runner binary cannot keep up with its own job: it is killed
// before it takes one, or it crawls through it in a way that reads as a broken
// image rather than as a limit somebody set. They bound a figure an operator
// types, and they bound the share a host hands out on a pool that leaves its
// size to the host -- a machine cut into more slots than it has runners' worth
// of room is the same mistake either way, and it must be refused in both
// places or the two disagree about the same limit.
const (
	MinRunnerCPUs     float64 = 0.25
	MinRunnerMemoryMB int64   = 512
)

// CPUReserve is what is held back from placement on this host's CPUs: the
// operator's reserve, or the floor when that is larger. Zero on a host that
// has not reported its CPUs, where there is nothing to hold back from.
func (h *Host) CPUReserve() float64 {
	if h.CPUs <= 0 {
		return 0
	}
	floor := max(MinHostReserveCPUs, MinHostReserveCPUFraction*float64(h.CPUs))
	if h.Embedded {
		floor += ControllerReserveCPUs
	}
	return max(float64(h.ReserveCPUs), floor)
}

// HostAllocation is what the scheduler may hand out on a host: the machine as
// its agent measured it, less what its operator and the floors above hold
// back.
//
// Each figure carries whether it is known, and that is the whole point of the
// type. Zero means two different things on a host row -- "the agent measured
// none left" and "no agent ever measured it" -- and reading the second as the
// first would empty a fleet the moment it upgraded, which is the failure the
// reporting half of this work was careful to avoid.
type HostAllocation struct {
	CPUs     float64
	MemoryMB int64
	DiskMB   int64

	CPUsKnown   bool
	MemoryKnown bool
	DiskKnown   bool
}

// Allocatable is the machine less its reserve, floored at zero.
//
// A measured host that is smaller than its own reserve allocates nothing, and
// that is the right answer rather than a bug: it is a machine with no room to
// run a job in, and it says so instead of accepting one and killing it.
func (h *Host) Allocatable() HostAllocation {
	a := HostAllocation{
		CPUsKnown:   h.CPUs > 0,
		MemoryKnown: h.MemoryMB > 0,
		// A host that reports a total but no free space has measured a full
		// disk; one that reports neither has measured nothing.
		DiskKnown: h.DiskTotalMB > 0,
	}
	if a.CPUsKnown {
		a.CPUs = max(float64(h.CPUs)-h.CPUReserve(), 0)
	}
	if a.MemoryKnown {
		a.MemoryMB = max(h.MemoryMB-h.MemoryReserve(), 0)
	}
	if a.DiskKnown {
		a.DiskMB = max(h.DiskFreeMB-max(h.ReserveDiskMB, MinHostReserveDiskMB), 0)
	}
	return a
}

