package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

const MaxProvisioningSelection = 5000

var ErrProvisioningSelectionTooLarge = errors.New("more than 5000 items match; narrow the filters before selecting all")

// ProvisioningSelection freezes the identities behind an all-matching selection.
// Later arrivals are never silently included in an operator's confirmation.
func (s *Store) ProvisioningSelection(ctx context.Context, f JobFilter) ([]string, error) {
	f.States = []JobState{JobQueued}
	f.ManagedOnly = true
	where, args := jobWhere(f)
	rows, err := s.read.QueryContext(ctx, "SELECT id FROM jobs "+where+" ORDER BY queued_at, id LIMIT ?", append(args, MaxProvisioningSelection+1)...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	ids := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	if len(ids) > MaxProvisioningSelection {
		return nil, ErrProvisioningSelectionTooLarge
	}
	return ids, rows.Err()
}

type ProvisioningResult struct {
	ID    string `json:"id"`
	OK    bool   `json:"ok"`
	Error string `json:"error,omitempty"`
}

// ControlProvisioning changes only operator state, in one transaction. A job
// that started since selection is skipped, and webhook replay cannot undo it.
func (s *Store) ControlProvisioning(ctx context.Context, ids []string, action string) ([]ProvisioningResult, error) {
	state, urgent := "", false
	switch action {
	case "pause":
		state = ProvisioningPaused
	case "resume":
	case "delete":
		state = ProvisioningDeleted
	case "run_now":
		urgent = true
	default:
		return nil, fmt.Errorf("unknown provisioning action %q", action)
	}
	if len(ids) == 0 || len(ids) > MaxProvisioningSelection {
		return nil, fmt.Errorf("select between 1 and %d items", MaxProvisioningSelection)
	}
	results := []ProvisioningResult{}
	err := s.tx(ctx, func(tx *sql.Tx) error {
		seen := map[string]bool{}
		for _, id := range ids {
			if seen[id] {
				continue
			}
			seen[id] = true
			j, err := scanJob(tx.QueryRowContext(ctx, "SELECT "+jobCols+" FROM jobs WHERE id=?", id))
			if errors.Is(err, sql.ErrNoRows) {
				results = append(results, ProvisioningResult{ID: id, Error: "This item no longer exists."})
				continue
			}
			if err != nil {
				return err
			}
			if j.State != JobQueued || (!j.Matched && j.RunnerID == "" && HostedJob(j.Labels)) {
				results = append(results, ProvisioningResult{ID: id, Error: "This item is no longer queued for this fleet."})
				continue
			}
			if _, err = tx.ExecContext(ctx, "UPDATE jobs SET provisioning=?, provision_now=? WHERE id=?", state, boolInt(urgent), id); err != nil {
				return err
			}
			results = append(results, ProvisioningResult{ID: id, OK: true})
		}
		return nil
	})
	return results, err
}

// MarkCancelRequested stamps the jobs of a workflow run an operator has
// cancelled, and returns the ids it actually changed.
//
// Only jobs that have not finished: a sibling that completed before the
// cancellation landed ran to its own conclusion, and saying it was cancelled
// would be a worse lie than the one this fixes. A job already stamped keeps
// its first stamp, so a second cancellation of the same run -- an ordinary one
// followed by a forced one -- does not restart the clock.
func (s *Store) MarkCancelRequested(ctx context.Context, ids []string, at time.Time) ([]string, error) {
	if len(ids) == 0 {
		return nil, nil
	}
	var changed []string
	err := s.tx(ctx, func(tx *sql.Tx) error {
		changed = changed[:0]
		for _, id := range ids {
			res, err := tx.ExecContext(ctx, `UPDATE jobs SET cancel_requested_at=?
				WHERE id=? AND state != ? AND cancel_requested_at IS NULL`,
				ms(at), id, string(JobCompleted))
			if err != nil {
				return err
			}
			if n, err := res.RowsAffected(); err == nil && n > 0 {
				changed = append(changed, id)
			}
		}
		return nil
	})
	return changed, err
}

// LastProvisioned includes removed runners so quick jobs and restarts do not
// reset a pool's place in the fairness rotation.
func (s *Store) LastProvisioned(ctx context.Context) (map[string]time.Time, error) {
	rows, err := s.read.QueryContext(ctx, "SELECT pool_id, MAX(created_at) FROM runners GROUP BY pool_id")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]time.Time{}
	for rows.Next() {
		var id string
		var stamp int64
		if err := rows.Scan(&id, &stamp); err != nil {
			return nil, err
		}
		out[id] = at(stamp)
	}
	return out, rows.Err()
}

func (s *Store) ProvisioningCounts(ctx context.Context, f JobFilter) (map[string]int, error) {
	f.States = []JobState{JobQueued}
	f.ManagedOnly = true
	f.Provisioning = nil
	where, args := jobWhere(f)
	rows, err := s.read.QueryContext(ctx, "SELECT CASE WHEN provisioning != '' THEN provisioning WHEN provision_now=1 THEN 'expedited' ELSE 'ready' END,COUNT(*) FROM jobs "+where+" GROUP BY 1", args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]int{"ready": 0, "expedited": 0, "paused": 0, "deleted": 0}
	for rows.Next() {
		var key string
		var n int
		if err := rows.Scan(&key, &n); err != nil {
			return nil, err
		}
		out[key] = n
	}
	return out, rows.Err()
}

package store

import (
	"context"
	"path/filepath"
	"testing"
	"time"
)

func TestProvisioningSurvivesReplayAndRestart(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "queue.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	j, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued, Labels: StringSlice{"self-hosted"}, Repo: "acme/app"})
	if err != nil {
		t.Fatal(err)
	}
	for _, action := range []string{"pause", "delete", "run_now", "resume"} {
		if _, err := s.ControlProvisioning(ctx, []string{j.ID}, action); err != nil {
			t.Fatal(err)
		}
		replay, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued})
		if err != nil {
			t.Fatal(err)
		}
		want := ""
		if action == "pause" {
			want = "paused"
		}
		if action == "delete" {
			want = "deleted"
		}
		if replay.Provisioning != want || replay.ProvisionNow != (action == "run_now") {
			t.Fatalf("%s lost on replay: %+v", action, replay)
		}
	}
	if _, err := s.ControlProvisioning(ctx, []string{j.ID}, "pause"); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	s, err = Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	got, err := s.GetJob(ctx, j.ID)
	if err != nil || got.Provisioning != "paused" {
		t.Fatalf("restart: %+v %v", got, err)
	}
}

func TestProvisioningSelectionAndStaleItems(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	makeJob := func(id int64, repo, branch string) *Job {
		j, err := s.UpsertJob(ctx, &Job{GitHubJobID: id, State: JobQueued, Repo: repo, HeadBranch: branch, Labels: StringSlice{"self-hosted", "linux"}})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	first := makeJob(1, "acme/one", "main")
	second := makeJob(2, "acme/two", "main")
	makeJob(3, "acme/one", "dev")
	ids, err := s.ProvisioningSelection(ctx, JobFilter{Repos: []string{"acme/one", "acme/two"}, Branches: []string{"main"}, Labels: []string{"linux"}})
	if err != nil || len(ids) != 2 {
		t.Fatalf("selection: %v %v", ids, err)
	}
	late := makeJob(4, "acme/one", "main")
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: second.GitHubJobID, State: JobInProgress}); err != nil {
		t.Fatal(err)
	}
	results, err := s.ControlProvisioning(ctx, append(ids, first.ID, "missing"), "delete")
	if err != nil || len(results) != 3 {
		t.Fatalf("deduplicated results: %+v %v", results, err)
	}
	ok := 0
	for _, r := range results {
		if r.OK {
			ok++
		}
	}
	if ok != 1 {
		t.Fatalf("expected only still-queued original item to change: %+v", results)
	}
	got, _ := s.GetJob(ctx, late.ID)
	if got.Provisioning != "" {
		t.Fatal("later arrival included")
	}
	selected, err := s.ProvisioningSelection(ctx, JobFilter{Provisioning: []string{"deleted"}})
	if err != nil || len(selected) != 1 || selected[0] != first.ID {
		t.Fatalf("deleted filter: %v %v", selected, err)
	}
	counts, err := s.ProvisioningCounts(ctx, JobFilter{Branches: []string{"main"}, Provisioning: []string{"deleted"}})
	if err != nil || counts["deleted"] != 1 || counts["ready"] != 1 {
		t.Fatalf("faceted counts: %v %v", counts, err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{late.ID}, "invalid"); err == nil {
		t.Fatal("invalid action accepted")
	}
}

// Removing a job from the queue has to move the numbers an operator reads, or
// the removal reads as having done nothing. The Overview's queue depth, the
// pool bars beside it and the queue gauges all come from StatsSince and
// ListQueuedJobs, and an operator who empties the queue and then finds the
// tile still holding its old number has been told the button is broken.
//
// Pausing is a different word and stays counted: that job is on hold, still
// waiting, and the Queue page lists it by default.
func TestRemovingAJobFromTheQueueStopsItCountingAsWaiting(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	queue := func(id int64) *Job {
		j, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: id, State: JobQueued, Repo: "acme/app", PoolID: "pool_1",
			Matched: true, Labels: StringSlice{"self-hosted", "linux"},
		})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	ready, paused, removed := queue(1), queue(2), queue(3)
	if _, err := s.ControlProvisioning(ctx, []string{paused.ID}, "pause"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{removed.ID}, "delete"); err != nil {
		t.Fatal(err)
	}

	// Both scopes: the Overview counts each of them, and the tile follows the
	// "other runners" switch between the two.
	for _, managedOnly := range []bool{false, true} {
		st, err := s.StatsSince(ctx, time.Time{}, managedOnly)
		if err != nil {
			t.Fatal(err)
		}
		if st.Queued != 2 {
			t.Errorf("managedOnly=%v: queued = %d, want the ready and the paused job only", managedOnly, st.Queued)
		}
	}

	jobs, err := s.ListQueuedJobs(ctx)
	if err != nil {
		t.Fatal(err)
	}
	ids := make([]string, len(jobs))
	for i, j := range jobs {
		ids[i] = j.ID
	}
	if len(ids) != 2 || ids[0] != ready.ID || ids[1] != paused.ID {
		t.Errorf("queued demand = %v, want %v and %v", ids, ready.ID, paused.ID)
	}

	// Restoring it puts the number back: the row was never anywhere else.
	if _, err := s.ControlProvisioning(ctx, []string{removed.ID}, "resume"); err != nil {
		t.Fatal(err)
	}
	st, err := s.StatsSince(ctx, time.Time{}, true)
	if err != nil {
		t.Fatal(err)
	}
	if st.Queued != 3 {
		t.Errorf("queued after restoring = %d, want 3", st.Queued)
	}
}

// The sweep that retires jobs GitHub stopped talking about is the one caller
// that wants the removed rows too. Removing a job suppresses this fleet's
// demand for it; it says nothing about whether GitHub still has the work, and
// a row left queued for ever would sit in the Queue's removed view for ever.
func TestStaleQueuedJobsIncludeTheOnesRemovedFromTheQueue(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	old := time.Now().Add(-48 * time.Hour)
	j, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobQueued, Repo: "acme/app", QueuedAt: old})
	if err != nil {
		t.Fatal(err)
	}
	fresh, err := s.UpsertJob(ctx, &Job{GitHubJobID: 2, State: JobQueued, Repo: "acme/app", QueuedAt: time.Now()})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.ControlProvisioning(ctx, []string{j.ID}, "delete"); err != nil {
		t.Fatal(err)
	}
	stale, err := s.ListStaleQueuedJobs(ctx, time.Now().Add(-24*time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if len(stale) != 1 || stale[0].ID != j.ID {
		t.Fatalf("stale queued jobs = %+v, want only the removed one queued %v ago", stale, time.Since(old))
	}
	if _, err := s.GetJob(ctx, fresh.ID); err != nil {
		t.Fatal(err)
	}
}

// A cancellation reaches GitHub at once; GitHub's completion delivery can be
// minutes behind it. For that whole window the row still reads `queued` or
// `in_progress`, and the fleet used to report the work as waiting or running:
// a queue depth nobody could clear, and a running count for work whose runner
// had already been taken away.
func TestACancelledRunStopsCountingAsWaitingOrRunning(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	job := func(id int64, state JobState) *Job {
		j, err := s.UpsertJob(ctx, &Job{
			GitHubJobID: id, GitHubRunID: 7, State: state, Repo: "acme/app",
			PoolID: "pool_1", Matched: true, Labels: StringSlice{"self-hosted"},
		})
		if err != nil {
			t.Fatal(err)
		}
		return j
	}
	queued, running, done := job(1, JobQueued), job(2, JobInProgress), job(3, JobQueued)
	finished, err := s.UpsertJob(ctx, &Job{GitHubJobID: 3, State: JobCompleted, Conclusion: "success"})
	if err != nil {
		t.Fatal(err)
	}
	_ = done

	at := time.Now()
	changed, err := s.MarkCancelRequested(ctx, []string{queued.ID, running.ID, finished.ID}, at)
	if err != nil {
		t.Fatal(err)
	}
	// The finished sibling ran to its own conclusion; calling it cancelled
	// would be a worse lie than the one this fixes.
	if len(changed) != 2 {
		t.Fatalf("stamped %v, want only the two jobs the run still owned", changed)
	}

	st, err := s.StatsSince(ctx, time.Time{}, true)
	if err != nil {
		t.Fatal(err)
	}
	if st.Queued != 0 || st.Running != 0 {
		t.Errorf("queued = %d, running = %d, want 0 and 0 once the run was cancelled", st.Queued, st.Running)
	}
	if jobs, err := s.ListQueuedJobs(ctx); err != nil || len(jobs) != 0 {
		t.Errorf("queued demand = %v (%v), want none", jobs, err)
	}

	// A second cancellation -- an ordinary one followed by a forced one --
	// must not restart the clock.
	later := at.Add(time.Minute)
	if changed, err := s.MarkCancelRequested(ctx, []string{queued.ID}, later); err != nil || len(changed) != 0 {
		t.Fatalf("a repeated cancellation changed %v (%v), want nothing", changed, err)
	}
	got, err := s.GetJob(ctx, queued.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.CancelRequestedAt == nil || !got.CancelRequestedAt.Equal(at.Truncate(time.Millisecond)) {
		t.Errorf("cancel_requested_at = %v, want the first request at %v", got.CancelRequestedAt, at)
	}
	if !got.Cancelling() {
		t.Error("a queued job whose run was cancelled must report itself as cancelling")
	}

	// Once GitHub reports the job over, the stamp is history and the
	// conclusion says what happened.
	closed, err := s.UpsertJob(ctx, &Job{GitHubJobID: 1, State: JobCompleted, Conclusion: "cancelled"})
	if err != nil {
		t.Fatal(err)
	}
	if closed.CancelRequestedAt == nil {
		t.Error("a delivery must not clear the fleet's own note that a cancellation was asked for")
	}
	if closed.Cancelling() {
		t.Error("a completed job is not still cancelling")
	}
}

// The Jobs page's Running and Queued views ask for this, and its history
// views do not: a cancelled job belongs in the record, badged for what it is.
func TestTheCancellingFilterHasThreeAnswers(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	for i, state := range []JobState{JobQueued, JobInProgress} {
		if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: int64(i + 1), State: state, Repo: "acme/app"}); err != nil {
			t.Fatal(err)
		}
	}
	cancelled, err := s.UpsertJob(ctx, &Job{GitHubJobID: 3, State: JobQueued, Repo: "acme/app"})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.MarkCancelRequested(ctx, []string{cancelled.ID}, time.Now()); err != nil {
		t.Fatal(err)
	}
	yes, no := true, false
	for _, tc := range []struct {
		name   string
		filter *bool
		want   int
	}{
		{"unasked is every job", nil, 3},
		{"false is the work still in hand", &no, 2},
		{"true is what is on its way out", &yes, 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			jobs, total, err := s.ListJobs(ctx, JobFilter{Cancelling: tc.filter}, Page{Limit: 10})
			if err != nil || total != tc.want || len(jobs) != tc.want {
				t.Fatalf("got %d jobs (total %d, %v), want %d", len(jobs), total, err, tc.want)
			}
		})
	}
}

package store

import (
	"context"
	"fmt"
	"testing"
	"time"
)

// Retention is the only thing standing between a controller and a database that
// grows for ever, and three of its five queries had no test at all: a cutoff
// comparison written the wrong way round deletes everything or nothing, and
// both look like a working fleet until somebody goes looking for last week.
//
// Each of these seeds one row either side of the cutoff and checks that exactly
// the old one goes, which is the whole contract: strictly older than the
// cutoff, and the count is what the caller logs.

func TestPruningScalingEventsKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, _ := seedPool(t, s)
	now := time.Now()

	old := &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 0, To: 1,
		Reason: "old", CreatedAt: now.Add(-48 * time.Hour)}
	recent := &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 1, To: 2,
		Reason: "recent", CreatedAt: now.Add(-time.Hour)}
	for _, e := range []*ScalingEvent{old, recent} {
		if err := s.AppendScalingEvent(ctx, e); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
	}

	n, err := s.PruneScalingEvents(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneScalingEvents: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d rows, want 1: the count is what the controller logs when somebody asks where their history went", n)
	}
	left, err := s.ListScalingEvents(ctx, "", 10)
	if err != nil {
		t.Fatalf("ListScalingEvents: %v", err)
	}
	if len(left) != 1 || left[0].Reason != "recent" {
		t.Fatalf("scaling events after the prune = %+v, want just the recent one", left)
	}
}

func TestPruningDeliveriesKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	for _, d := range []*WebhookDelivery{
		{DeliveryID: "old", Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-48 * time.Hour)},
		{DeliveryID: "recent", Event: "workflow_job", Status: "accepted", ReceivedAt: now.Add(-time.Hour)},
	} {
		if err := s.RecordDelivery(ctx, d); err != nil {
			t.Fatalf("RecordDelivery: %v", err)
		}
	}

	n, err := s.PruneDeliveries(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneDeliveries: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d deliveries, want 1", n)
	}
	left, err := s.ListDeliveries(ctx, "", 10)
	if err != nil {
		t.Fatalf("ListDeliveries: %v", err)
	}
	if len(left) != 1 || left[0].DeliveryID != "recent" {
		t.Fatalf("deliveries after the prune = %+v, want just the recent one", left)
	}
}

func TestPruningSamplesKeepsTheOnesInsideTheWindow(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	for _, at := range []time.Time{now.Add(-48 * time.Hour), now.Add(-time.Hour)} {
		if err := s.RecordSample(ctx, FleetSample{At: at, TotalRunners: 1}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
	}

	n, err := s.PruneSamples(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneSamples: %v", err)
	}
	if n != 1 {
		t.Errorf("pruned %d samples, want 1", n)
	}
	left, err := s.ListSamples(ctx, now.Add(-72*time.Hour))
	if err != nil {
		t.Fatalf("ListSamples: %v", err)
	}
	if len(left) != 1 {
		t.Fatalf("samples after the prune = %d, want 1: the sparkline is drawn from these, and a prune that took both would flatten it", len(left))
	}
	// Which one survived, not merely how many: counting alone passes just as
	// happily when the comparison is the wrong way round and the prune has kept
	// the ancient sample and deleted the recent one.
	if kept := left[0].At; kept.Before(now.Add(-24 * time.Hour)) {
		t.Errorf("the sample left behind is from %s, which is older than the cutoff: the prune kept the wrong side", kept.UTC())
	}
}

// Each prune deletes a bounded batch so the single writer is never held for
// long, and a pass used to run exactly one. Retention then stopped bounding a
// table as soon as its inflow beat 500 jobs or 1000 rows an hour, and turning
// retention on for an old database drained a backlog at that rate for months.
// A pass now repeats the batch, each one its own transaction, until a batch
// comes back short. These seed more than one batch of old rows and one recent
// row, and expect the whole backlog gone and the recent row kept.

func TestPruningJobsDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	old := now.Add(-48 * time.Hour)
	done := old.Add(time.Minute)

	const backlog = 1200
	for i := 1; i <= backlog; i++ {
		j, err := s.UpsertJob(ctx, &Job{GitHubJobID: int64(i), State: JobCompleted, Conclusion: "success", QueuedAt: old, CompletedAt: &done})
		if err != nil {
			t.Fatalf("UpsertJob: %v", err)
		}
		// Timelines go with their job in every batch, not just the first.
		if i%100 == 0 {
			if err := s.AppendJobEvent(ctx, &JobEvent{JobID: j.ID, Kind: JobEventQueued, Source: "webhook", Message: "queued", At: old}); err != nil {
				t.Fatalf("AppendJobEvent: %v", err)
			}
		}
	}
	if _, err := s.UpsertJob(ctx, &Job{GitHubJobID: backlog + 1, State: JobQueued, QueuedAt: now}); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}

	n, err := s.PruneJobs(ctx, now.Add(-24*time.Hour))
	if err != nil {
		t.Fatalf("PruneJobs: %v", err)
	}
	if n != backlog {
		t.Errorf("pruned %d jobs in one pass, want %d", n, backlog)
	}
	var jobs, events int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM jobs`).Scan(&jobs); err != nil {
		t.Fatal(err)
	}
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM job_events`).Scan(&events); err != nil {
		t.Fatal(err)
	}
	if jobs != 1 || events != 0 {
		t.Fatalf("after the prune there are %d jobs and %d events, want the one recent job and no events", jobs, events)
	}
}

func TestPruningDeliveriesDrainsABacklogLargerThanOneBatchInOnePass(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now()

	const backlog = 2500
	for i := 0; i < backlog; i++ {
