		}
	}
	if err := s.AppendScalingEvent(ctx, &ScalingEvent{PoolID: pool.ID, PoolName: pool.Name, From: 1, To: 2, Reason: "recent", CreatedAt: now.Add(-time.Hour)}); err != nil {
