// A pass must not be able to hold the writer, batch after batch, for as long
// as a backlog is deep: the bound leaves the rest for the next hourly pass, and
// a cancelled context ends the pass between batches.
func TestABatchedPruneStopsAtTheBoundAndWhenTheContextEnds(t *testing.T) {
	always := func(size int64) func(context.Context) (int64, error) {
		return func(context.Context) (int64, error) { return size, nil }
	}
	ctx, cancel := context.WithCancel(context.Background())
	calls := 0
	cancelling := func(context.Context) (int64, error) {
		calls++
		if calls == 3 {
			cancel()
		}
		return 10, nil
	}
	short := func() func(context.Context) (int64, error) {
		sizes := []int64{10, 10, 4}
		return func(context.Context) (int64, error) {
			n := sizes[0]
			sizes = sizes[1:]
			return n, nil
		}
	}

	tests := []struct {
		name string
		ctx  context.Context
		fn   func(context.Context) (int64, error)
		want int64
	}{
		{"a short batch ends the pass", context.Background(), short(), 24},
		{"a backlog that never runs short stops at the bound", context.Background(), always(10), 10 * 5},
		{"a cancelled context ends the pass between batches", ctx, cancelling, 30},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := pruneInBatches(tt.ctx, 10, 5, tt.fn)
			if err != nil {
				t.Fatalf("pruneInBatches: %v", err)
			}
			if got != tt.want {
				t.Errorf("pruned %d rows, want %d", got, tt.want)
			}
		})
	}
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
)

type AIContextRepository struct {
	Freshness  *AIContextFreshness     `json:"freshness,omitempty"`
	SetupState string                  `json:"setup_state,omitempty"`
	SetupPRURL string                  `json:"setup_pr_url,omitempty"`
	ID         string                  `json:"id"`
	Key        aicontext.RepositoryKey `json:"repository"`
	FullName   string                  `json:"full_name"`
	Config     aicontext.Config        `json:"config"`
	Revision   int64                   `json:"revision"`
	// Available is a verified repository-access state, not whether a snapshot
	// exists. Access removal closes this gate before retained blobs are read.
	Available bool      `json:"available"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// MarshalJSON derives shareable setup guidance from the saved destination, so
// it remains available after the preparation wizard has finished.
func (r AIContextRepository) MarshalJSON() ([]byte, error) {
	type repository AIContextRepository
	return json.Marshal(struct {
		repository
		Instructions  string `json:"instructions"`
		BadgeMarkdown string `json:"badge_markdown"`
	}{repository: repository(r), Instructions: aicontext.AssistantInstructions(r.Key, r.FullName, r.Config), BadgeMarkdown: aicontext.BadgeMarkdown(r.Key, r.FullName)})
}

const aiContextColumns = `id, installation_id, github_host, repository_id, full_name, config_json, revision, available, created_at, updated_at`

const aiContextReadColumns = aiContextColumns + `, COALESCE((SELECT state FROM ai_context_setups WHERE repository_id=ai_context_repositories.id),''), COALESCE((SELECT pr_url FROM ai_context_setups WHERE repository_id=ai_context_repositories.id),''), COALESCE((SELECT json_object('state',state,'desired_commit',desired_commit,'published_commit',published_commit,'snapshot_id',digest,'checked_at',checked_at,'failure',failure) FROM ai_context_freshness WHERE repository_id=ai_context_repositories.id),'null')`

func scanAIContext(sc interface{ Scan(...any) error }) (*AIContextRepository, error) {
	var r AIContextRepository
	var config, freshness string
	var available int
	var created, updated int64
	err := sc.Scan(&r.ID, &r.Key.InstallationID, &r.Key.GitHubHost, &r.Key.RepositoryID, &r.FullName, &config, &r.Revision, &available, &created, &updated, &r.SetupState, &r.SetupPRURL, &freshness)
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal([]byte(config), &r.Config); err != nil {
		return nil, err
	}
	if freshness != "null" {
		var stored struct {
			State           string `json:"state"`
			DesiredCommit   string `json:"desired_commit"`
			PublishedCommit string `json:"published_commit"`
			Digest          string `json:"snapshot_id"`
			CheckedAt       int64  `json:"checked_at"`
			Failure         string `json:"failure"`
		}
		if err := json.Unmarshal([]byte(freshness), &stored); err != nil {
			return nil, err
		}
		r.Freshness = &AIContextFreshness{State: stored.State, DesiredCommit: stored.DesiredCommit, PublishedCommit: stored.PublishedCommit, Digest: stored.Digest, CheckedAt: at(stored.CheckedAt), Failure: stored.Failure}
	}
	r.Available, r.CreatedAt, r.UpdatedAt = available == 1, at(created), at(updated)
	return &r, nil
}

func (s *Store) CreateAIContextRepository(ctx context.Context, r *AIContextRepository) error {
	if err := r.Key.Validate(); err != nil {
		return err
	}
	if err := r.Config.Validate(); err != nil {
		return err
	}
	if r.FullName == "" || len(r.FullName) > 255 {
		return fmt.Errorf("context needs the repository's full name")
	}
	if r.ID == "" {
		r.ID = NewID(PrefixAIContext)
	}
	body, err := json.Marshal(r.Config)
	if err != nil {
		return err
	}
	now := s.Now()
	_, err = s.exec(ctx, `INSERT INTO ai_context_repositories (`+aiContextColumns+`) VALUES (?,?,?,?,?,?,1,0,?,?)`,
		r.ID, r.Key.InstallationID, r.Key.GitHubHost, r.Key.RepositoryID, r.FullName, string(body), ms(now), ms(now))
	if err != nil {
		return wrapWrite(err)
	}
	r.Revision, r.Available, r.CreatedAt, r.UpdatedAt = 1, false, now, now
	return nil
}

func (s *Store) GetAIContextRepository(ctx context.Context, id string) (*AIContextRepository, error) {
	r, err := scanAIContext(s.read.QueryRowContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories WHERE id=?`, id))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, fmt.Errorf("context repository %s: %w", id, ErrNotFound)
	}
	return r, err
}

// SaveAIContextConfig is compare-and-swap: resuming yesterday's wizard cannot
// silently replace the exclusions or destination somebody changed today.
func (s *Store) SaveAIContextConfig(ctx context.Context, id string, revision int64, config aicontext.Config) error {
	if err := config.Validate(); err != nil {
		return err
	}
	if revision < 1 {
		return ErrConflict
	}
	body, err := json.Marshal(config)
	if err != nil {
		return err
	}
	res, err := s.exec(ctx, `UPDATE ai_context_repositories SET config_json=?, revision=revision+1, updated_at=? WHERE id=? AND revision=? AND NOT EXISTS (SELECT 1 FROM ai_context_setups WHERE repository_id=ai_context_repositories.id)`, string(body), ms(s.Now()), id, revision)
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return ErrConflict
	}
	return nil
}

func (s *Store) SetAIContextAvailable(ctx context.Context, id string, available bool) error {
	res, err := s.exec(ctx, `UPDATE ai_context_repositories SET available=?, updated_at=? WHERE id=?`, boolInt(available), ms(s.Now()), id)
	if err != nil {
		return err
	}
	return affected(res, "context repository", id)
}

func (s *Store) DeleteAIContextRepository(ctx context.Context, id string) error {
	res, err := s.exec(ctx, `DELETE FROM ai_context_repositories WHERE id=?`, id)
	if err != nil {
		return err
	}
	return affected(res, "context repository", id)
}

// ReplaceAIContextMembers also removes consent for users losing membership.
// Adding the user back later must not quietly re-enable an old app connection.
func (s *Store) ReplaceAIContextMembers(ctx context.Context, repositoryID string, users []string) error {
	if len(users) > 200 {
		return fmt.Errorf("select at most 200 context readers")
	}
	return wrapWrite(s.tx(ctx, func(tx *sql.Tx) error {
		var exists int
		if err := tx.QueryRowContext(ctx, `SELECT 1 FROM ai_context_repositories WHERE id=?`, repositoryID).Scan(&exists); errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		} else if err != nil {
			return err
		}
		// The temporary selection is held in Go; all changes still commit as
		// one writer transaction, so a failed member insert retains old grants.
		old := map[string]bool{}
		rows, err := tx.QueryContext(ctx, `SELECT user_id FROM ai_context_members WHERE repository_id=?`, repositoryID)
		if err != nil {
			return err
		}
		for rows.Next() {
			var user string
			if err := rows.Scan(&user); err != nil {
				rows.Close()
				return err
			}
			old[user] = true
		}
		if err := rows.Err(); err != nil {
			rows.Close()
			return err
		}
		rows.Close()
		if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_members WHERE repository_id=?`, repositoryID); err != nil {
			return err
		}
		seen := map[string]bool{}
		for _, user := range users {
			if user == "" || seen[user] {
				return fmt.Errorf("select each context reader once")
			}
			seen[user] = true
			if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_members(repository_id,user_id) VALUES(?,?)`, repositoryID, user); err != nil {
				return err
			}
		}
		for user := range old {
			if !seen[user] {
				if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_connection_repositories WHERE repository_id=? AND grant_id IN (SELECT id FROM oauth_grants WHERE user_id=?)`, repositoryID, user); err != nil {
					return err
				}
			}
		}
		return nil
	}))
}

func (s *Store) AIContextUserAccess(ctx context.Context, repositoryID, userID string) (bool, error) {
	var allowed int
	err := s.read.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM ai_context_members m
		JOIN ai_context_repositories r ON r.id=m.repository_id JOIN users u ON u.id=m.user_id
		WHERE m.repository_id=? AND m.user_id=? AND r.available=1 AND u.disabled=0)`, repositoryID, userID).Scan(&allowed)
	return allowed == 1, err
}

// ReplaceAIContextConnectionAccess is called only after explicit consent.
// Ownership, live user membership and connection revocation are checked here
// as well as by the caller; a cached identity cannot restore revoked access.
func (s *Store) ReplaceAIContextConnectionAccess(ctx context.Context, grantID, userID string, repositories []string) error {
	if len(repositories) > 100 {
		return fmt.Errorf("select at most 100 repositories for one connection")
	}
	return s.tx(ctx, func(tx *sql.Tx) error {
		var active int
		err := tx.QueryRowContext(ctx, `SELECT 1 FROM oauth_grants g JOIN users u ON u.id=g.user_id JOIN oauth_clients c ON c.id=g.client_id
			WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0`, grantID, userID).Scan(&active)
		if errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		}
		if err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_connection_repositories WHERE grant_id=?`, grantID); err != nil {
			return err
		}
		seen := map[string]bool{}
		for _, repository := range repositories {
			if seen[repository] {
				return fmt.Errorf("select each context repository once")
			}
			seen[repository] = true
			var allowed int
			err := tx.QueryRowContext(ctx, `SELECT 1 FROM ai_context_members m JOIN ai_context_repositories r ON r.id=m.repository_id WHERE m.repository_id=? AND m.user_id=? AND r.available=1`, repository, userID).Scan(&allowed)
			if errors.Is(err, sql.ErrNoRows) {
				return ErrNotFound
			}
			if err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_connection_repositories(grant_id,repository_id) VALUES(?,?)`, grantID, repository); err != nil {
				return err
			}
		}
		return nil
	})
}

func (s *Store) AIContextConnectionAccess(ctx context.Context, repositoryID, grantID, userID string) (bool, error) {
	var allowed int
	err := s.read.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM ai_context_connection_repositories a
		JOIN oauth_grants g ON g.id=a.grant_id JOIN oauth_clients c ON c.id=g.client_id
		JOIN ai_context_members m ON m.repository_id=a.repository_id AND m.user_id=g.user_id
		JOIN ai_context_repositories r ON r.id=a.repository_id JOIN users u ON u.id=g.user_id
		WHERE a.repository_id=? AND g.id=? AND g.user_id=? AND r.available=1 AND u.disabled=0
		AND g.revoked_at IS NULL AND c.revoked_at IS NULL)`, repositoryID, grantID, userID).Scan(&allowed)
	return allowed == 1, err
}

// ListAIContextRepositories bounds configuration metadata separately from source
// retrieval. Ordering includes the ID so equally named drafts cannot skip rows.
func (s *Store) ListAIContextRepositories(ctx context.Context, limit, offset int) ([]AIContextRepository, int, error) {
	return s.ListAIContextRepositoriesFiltered(ctx, limit, offset, "", "")
}

func (s *Store) ListAIContextRepositoriesFiltered(ctx context.Context, limit, offset int, installationID, query string) ([]AIContextRepository, int, error) {
	return s.listAIContextRepositories(ctx, limit, offset, installationID, query, "")
}

// ListAIContextRepositoriesOwnedBy is the same page restricted to installations
// the user owns, so an owner's listing cannot reach another installation's rows
// however the filters are combined.
func (s *Store) ListAIContextRepositoriesOwnedBy(ctx context.Context, limit, offset int, installationID, query, userID string) ([]AIContextRepository, int, error) {
	if userID == "" {
		return nil, 0, fmt.Errorf("an owner is required")
	}
	return s.listAIContextRepositories(ctx, limit, offset, installationID, query, userID)
}

func (s *Store) listAIContextRepositories(ctx context.Context, limit, offset int, installationID, query, ownerID string) ([]AIContextRepository, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a page size between 1 and 100 and a non-negative offset")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const where = ` WHERE (?='' OR installation_id=?) AND full_name LIKE ? ESCAPE '\'
		AND (?='' OR installation_id IN (SELECT o.installation_id FROM ai_context_installation_owners o JOIN users u ON u.id=o.user_id WHERE o.user_id=? AND u.disabled=0))`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) FROM ai_context_repositories`+where, installationID, installationID, pattern, ownerID, ownerID).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories`+where+` ORDER BY full_name,id LIMIT ? OFFSET ?`, installationID, installationID, pattern, ownerID, ownerID, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := make([]AIContextRepository, 0)
	for rows.Next() {
		row, err := scanAIContext(rows)
		if err != nil {
			return nil, 0, err
		}
		out = append(out, *row)
	}
	return out, total, rows.Err()
}

func (s *Store) AIContextMembers(ctx context.Context, repositoryID string) ([]string, error) {
	if _, err := s.GetAIContextRepository(ctx, repositoryID); err != nil {
		return nil, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT user_id FROM ai_context_members WHERE repository_id=? ORDER BY user_id`, repositoryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}

// AIContextChoice exposes only repository names a person already has source
// membership for. Configuration, source and other users' grants stay private.
type AIContextChoice struct {
	ID       string `json:"id"`
	FullName string `json:"full_name"`
}

type AIContextConnectionSelection struct {
	Items                 []AIContextChoice `json:"items"`
	Total                 int               `json:"total"`
	Limit                 int               `json:"limit"`
	Offset                int               `json:"offset"`
	SelectedRepositoryIDs []string          `json:"selected_repository_ids"`
}

// AIContextConnectionChoices checks the live owner/client/grant on every query,
// so revocation closes both metadata discovery and the subsequent consent write.
func (s *Store) AIContextConnectionChoices(ctx context.Context, grantID, userID string, limit, offset int) (*AIContextConnectionSelection, error) {
	if limit < 1 || limit > 100 || offset < 0 {
		return nil, fmt.Errorf("choose a page size between 1 and 100 and a non-negative offset")
	}
	const active = `EXISTS(SELECT 1 FROM oauth_grants g JOIN users u ON u.id=g.user_id JOIN oauth_clients c ON c.id=g.client_id WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0)`
	var valid bool
	if err := s.read.QueryRowContext(ctx, `SELECT `+active, grantID, userID).Scan(&valid); err != nil {
		return nil, err
	}
	if !valid {
		return nil, ErrNotFound
	}
	const eligible = ` FROM ai_context_repositories r JOIN ai_context_members m ON m.repository_id=r.id WHERE m.user_id=? AND r.available=1 AND ` + active
	out := &AIContextConnectionSelection{Items: []AIContextChoice{}, SelectedRepositoryIDs: []string{}, Limit: limit, Offset: offset}
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+eligible, userID, grantID, userID).Scan(&out.Total); err != nil {
		return nil, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+eligible+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, userID, grantID, userID, limit, offset)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var choice AIContextChoice
		if err := rows.Scan(&choice.ID, &choice.FullName); err != nil {
			rows.Close()
			return nil, err
		}
		out.Items = append(out.Items, choice)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	// Return the complete eligible selection, not merely the current page. A
	// save on page one must not quietly revoke choices made on page two.
	rows, err = s.read.QueryContext(ctx, `SELECT r.id`+eligible+` AND EXISTS(SELECT 1 FROM ai_context_connection_repositories a WHERE a.repository_id=r.id AND a.grant_id=?) ORDER BY r.id`, userID, grantID, userID, grantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out.SelectedRepositoryIDs = append(out.SelectedRepositoryIDs, id)
	}
	return out, rows.Err()
}

func (s *Store) FindAIContextRepository(ctx context.Context, key aicontext.RepositoryKey) (*AIContextRepository, error) {
	if err := key.Validate(); err != nil {
		return nil, err
	}
	row, err := scanAIContext(s.read.QueryRowContext(ctx, `SELECT `+aiContextReadColumns+` FROM ai_context_repositories WHERE github_host=? AND installation_id=? AND repository_id=?`, key.GitHubHost, key.InstallationID, key.RepositoryID))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return row, err
}

// Reader metadata is gated in the query, before paging: an ordinary fleet
// viewer cannot enumerate private drafts, names or configuration.
func (s *Store) ListAIContextReaderRepositories(ctx context.Context, userID string, limit, offset int, query string) ([]AIContextChoice, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a bounded page and search query")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const from = ` FROM ai_context_repositories r JOIN ai_context_members m ON m.repository_id=r.id JOIN users u ON u.id=m.user_id WHERE m.user_id=? AND u.disabled=0 AND r.available=1 AND r.full_name LIKE ? ESCAPE '\'`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+from, userID, pattern).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+from+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, userID, pattern, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []AIContextChoice{}
	for rows.Next() {
		var c AIContextChoice
		if err := rows.Scan(&c.ID, &c.FullName); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
	}
	return out, total, rows.Err()
}

// ListAIContextGrantedRepositories reveals only repositories selected for this
// connection, never the owner's wider membership or other connections' grants.
func (s *Store) ListAIContextGrantedRepositories(ctx context.Context, grantID, userID string, limit, offset int, query string) ([]AIContextChoice, int, error) {
	if limit < 1 || limit > 100 || offset < 0 || len(query) > 200 {
		return nil, 0, fmt.Errorf("choose a bounded page and search query")
	}
	pattern := "%" + strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(query) + "%"
	const from = ` FROM ai_context_repositories r JOIN ai_context_connection_repositories a ON a.repository_id=r.id JOIN oauth_grants g ON g.id=a.grant_id JOIN oauth_clients c ON c.id=g.client_id JOIN ai_context_members m ON m.repository_id=r.id AND m.user_id=g.user_id JOIN users u ON u.id=g.user_id WHERE g.id=? AND g.user_id=? AND g.revoked_at IS NULL AND c.revoked_at IS NULL AND u.disabled=0 AND r.available=1 AND r.full_name LIKE ? ESCAPE '\'`
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*)`+from, grantID, userID, pattern).Scan(&total); err != nil {
		return nil, 0, err
	}
	rows, err := s.read.QueryContext(ctx, `SELECT r.id,r.full_name`+from+` ORDER BY r.full_name,r.id LIMIT ? OFFSET ?`, grantID, userID, pattern, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []AIContextChoice{}
	for rows.Next() {
		var choice AIContextChoice
		if err := rows.Scan(&choice.ID, &choice.FullName); err != nil {
			return nil, 0, err
		}
		out = append(out, choice)
	}
	return out, total, rows.Err()
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"time"

	"github.com/eyupio/zoomies/internal/aicontext"
)

// ClaimAIContextMaintenance atomically replaces a settled proposal. Source
// availability closes before publication and never falls back to old context.
func (s *Store) ClaimAIContextMaintenance(ctx context.Context, operation *AIContextSetup, previousHash string, config aicontext.Config) error {
	if err := config.Validate(); err != nil {
		return err
	}
	if operation.Revision < 2 || len(operation.PlanHash) != 64 || len(operation.PlanJSON) > 4<<20 || len(previousHash) != 64 {
		return fmt.Errorf("invalid reviewed maintenance plan")
	}
	encoded, err := json.Marshal(config)
	if err != nil {
		return err
	}
	token, now := NewID("ctxlease"), s.Now()
	err = s.tx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `UPDATE ai_context_repositories SET config_json=?,revision=revision+1,available=0,updated_at=? WHERE id=? AND revision=? AND EXISTS(SELECT 1 FROM ai_context_setups WHERE repository_id=? AND plan_hash=? AND lease_until<=?)`, string(encoded), ms(now), operation.RepositoryID, operation.Revision-1, operation.RepositoryID, previousHash, ms(now))
		if err != nil {
			return err
		}
		n, err := res.RowsAffected()
		if err != nil {
			return err
		}
		if n != 1 {
			return ErrConflict
		}
		if _, err = tx.ExecContext(ctx, `UPDATE ai_context_setups SET revision=?,plan_hash=?,plan_json=?,state='pending',pr_number=0,pr_url='',lease_token=?,lease_until=?,updated_at=? WHERE repository_id=?`, operation.Revision, operation.PlanHash, operation.PlanJSON, token, ms(now.Add(5*time.Minute)), ms(now), operation.RepositoryID); err != nil {
			return err
		}
		if _, err = tx.ExecContext(ctx, `DELETE FROM ai_context_freshness WHERE repository_id=?`, operation.RepositoryID); err != nil {
			return err
		}
		if config.Disabled {
			for _, table := range []string{"ai_context_connection_repositories", "ai_context_members", "ai_context_snapshots"} {
				if _, err = tx.ExecContext(ctx, `DELETE FROM `+table+` WHERE repository_id=?`, operation.RepositoryID); err != nil {
					return err
				}
			}
		}
		return nil
	})
	if err == nil {
		operation.LeaseToken = token
		operation.State = "pending"
	}
	return err
}

package store

import (
	"errors"
	"strings"
	"testing"
)

func TestContextRemovalIsAtomicAndCannotResurrectConsentOrOldSource(t *testing.T) {
	s := newTestStore(t)
	r, u, g := contextFixture(t, s)
	old := &AIContextSetup{RepositoryID: r.ID, Revision: r.Revision, PlanHash: strings.Repeat("a", 64), PlanJSON: "{}"}
	if err := s.ClaimAIContextSetup(t.Context(), old); err != nil {
		t.Fatal(err)
	}
	if err := s.CompleteAIContextSetup(t.Context(), r.ID, old.LeaseToken, 1, "https://github.com/acme/widgets/pull/1"); err != nil {
		t.Fatal(err)
	}
	if err := s.ReplaceAIContextMembers(t.Context(), r.ID, []string{u.ID}); err != nil {
		t.Fatal(err)
	}
	snapshot := retainedContext(t, r, strings.Repeat("b", 40))
	digest := snapshotDigest(t, snapshot)
	if err := s.PublishAIContextSnapshot(t.Context(), r.ID, r.Revision, snapshot); err != nil {
		t.Fatal(err)
	}
	if err := s.ReplaceAIContextConnectionAccess(t.Context(), g.ID, u.ID, []string{r.ID}); err != nil {
		t.Fatal(err)
	}
	config := r.Config
	config.Disabled = true
	config.SetupGeneration++
	next := &AIContextSetup{RepositoryID: r.ID, Revision: r.Revision + 1, PlanHash: strings.Repeat("c", 64), PlanJSON: "{}"}
	if err := s.ClaimAIContextMaintenance(t.Context(), next, strings.Repeat("d", 64), config); !errors.Is(err, ErrConflict) {
		t.Fatal("stale plan replaced setup", err)
	}
	if _, err := s.GetAIContextSnapshot(t.Context(), r.ID, digest); err != nil {
		t.Fatal("failed claim deleted source", err)
	}
	if err := s.ClaimAIContextMaintenance(t.Context(), next, old.PlanHash, config); err != nil {
		t.Fatal(err)
	}
	if _, err := s.GetAIContextSnapshot(t.Context(), r.ID, digest); !errors.Is(err, ErrNotFound) {
		t.Fatal("removed snapshot retained", err)
	}
	members, err := s.AIContextMembers(t.Context(), r.ID)
	if err != nil || len(members) != 0 {
		t.Fatal("removed members retained", err)
	}
	if err := s.PublishAIContextSnapshot(t.Context(), r.ID, r.Revision, snapshot); !errors.Is(err, ErrConflict) {
		t.Fatal("old in-flight publication succeeded", err)
	}
	removed, _ := s.GetAIContextRepository(t.Context(), r.ID)
	if err := s.PublishAIContextSnapshot(t.Context(), r.ID, removed.Revision, retainedContext(t, removed, strings.Repeat("b", 40))); err == nil {
		t.Fatal("disabled context accepted source")
	}
	if err := s.ReplaceAIContextMembers(t.Context(), r.ID, []string{u.ID}); err != nil {
		t.Fatal(err)
	}
	if err := s.SetAIContextAvailable(t.Context(), r.ID, true); err != nil {
		t.Fatal(err)
	}
	if allowed, err := s.AIContextConnectionAccess(t.Context(), r.ID, g.ID, u.ID); err != nil || allowed {
		t.Fatal("old connection consent resurrected", err)
	}
	competing := *next
	if err := s.ClaimAIContextMaintenance(t.Context(), &competing, next.PlanHash, config); !errors.Is(err, ErrConflict) {
		t.Fatal("duplicate maintenance changed state", err)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
)

// MaxContextInstallationOwners bounds one installation's owner list so an
// administrator's replace call stays a single small transaction.
const MaxContextInstallationOwners = 50

// AIContextInstallationOwners lists the users who may enable AI Context for an
// installation, in a stable order.
func (s *Store) AIContextInstallationOwners(ctx context.Context, installationID string) ([]string, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT user_id FROM ai_context_installation_owners WHERE installation_id=? ORDER BY user_id`, installationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}

// ReplaceAIContextInstallationOwners makes the owner list exactly users. Unknown
// installations and users are refused rather than skipped, so a typo cannot look
// like a successful delegation.
func (s *Store) ReplaceAIContextInstallationOwners(ctx context.Context, installationID string, users []string) error {
	if len(users) > MaxContextInstallationOwners {
		return fmt.Errorf("select at most %d installation owners", MaxContextInstallationOwners)
	}
	return wrapWrite(s.tx(ctx, func(tx *sql.Tx) error {
		var exists int
		if err := tx.QueryRowContext(ctx, `SELECT 1 FROM installations WHERE id=?`, installationID).Scan(&exists); errors.Is(err, sql.ErrNoRows) {
			return ErrNotFound
		} else if err != nil {
			return err
		}
		for _, user := range users {
			if err := tx.QueryRowContext(ctx, `SELECT 1 FROM users WHERE id=? AND disabled=0`, user).Scan(&exists); errors.Is(err, sql.ErrNoRows) {
				return fmt.Errorf("%w: choose existing, enabled users as installation owners", ErrNotFound)
			} else if err != nil {
				return err
			}
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM ai_context_installation_owners WHERE installation_id=?`, installationID); err != nil {
			return err
		}
		for _, user := range users {
			if _, err := tx.ExecContext(ctx, `INSERT INTO ai_context_installation_owners VALUES(?,?,?)`, installationID, user, ms(s.Now())); err != nil {
				return err
			}
		}
		return nil
	}))
}

// UserOwnsAIContextInstallation checks live state: a disabled user owns nothing.
func (s *Store) UserOwnsAIContextInstallation(ctx context.Context, installationID, userID string) (bool, error) {
	var owns int
	err := s.read.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM ai_context_installation_owners o JOIN users u ON u.id=o.user_id
		WHERE o.installation_id=? AND o.user_id=? AND u.disabled=0)`, installationID, userID).Scan(&owns)
	return owns == 1, err
}

// AIContextInstallationRef is the installation set a user owns, with
// just enough to label it. It is the whole of what an owner learns about the
// fleet's installations.
type AIContextInstallationRef struct {
	ID         string `json:"id"`
	Target     string `json:"target"`
	TargetType string `json:"target_type"`
}

func (s *Store) AIContextOwnedInstallations(ctx context.Context, userID string) ([]AIContextInstallationRef, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT i.id,i.target,i.target_type FROM installations i
		JOIN ai_context_installation_owners o ON o.installation_id=i.id JOIN users u ON u.id=o.user_id
		WHERE o.user_id=? AND u.disabled=0 ORDER BY i.target,i.id`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []AIContextInstallationRef{}
	for rows.Next() {
		var ref AIContextInstallationRef
		if err := rows.Scan(&ref.ID, &ref.Target, &ref.TargetType); err != nil {
			return nil, err
		}
		out = append(out, ref)
	}
	return out, rows.Err()
}

// AllAIContextInstallations lists every installation for an administrator's
// picker, in the same minimal shape owners see.
func (s *Store) AllAIContextInstallations(ctx context.Context) ([]AIContextInstallationRef, error) {
	rows, err := s.read.QueryContext(ctx, `SELECT id,target,target_type FROM installations ORDER BY target,id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []AIContextInstallationRef{}
	for rows.Next() {
		var ref AIContextInstallationRef
		if err := rows.Scan(&ref.ID, &ref.Target, &ref.TargetType); err != nil {
			return nil, err
		}
		out = append(out, ref)
	}
	return out, rows.Err()
}

package store

import (
	"errors"
	"testing"
)

func TestInstallationOwnershipIsScopedLiveAndCascades(t *testing.T) {
	s := newTestStore(t)
	r, owner, _ := contextFixture(t, s)
	installation := r.Key.InstallationID
	other := &User{Username: "not-an-owner", Role: RoleViewer}
	if err := s.CreateUser(t.Context(), other); err != nil {
		t.Fatal(err)
	}

	if owns, err := s.UserOwnsAIContextInstallation(t.Context(), installation, owner.ID); err != nil || owns {
		t.Fatal("nobody owns an installation until an administrator says so", owns, err)
	}
	if err := s.ReplaceAIContextInstallationOwners(t.Context(), installation, []string{"nobody"}); !errors.Is(err, ErrNotFound) {
		t.Fatal("an unknown user must be refused, not skipped", err)
	}
	if err := s.ReplaceAIContextInstallationOwners(t.Context(), "missing", nil); !errors.Is(err, ErrNotFound) {
		t.Fatal("an unknown installation must be refused", err)
	}
	if err := s.ReplaceAIContextInstallationOwners(t.Context(), installation, []string{owner.ID}); err != nil {
		t.Fatal(err)
	}
	if owns, _ := s.UserOwnsAIContextInstallation(t.Context(), installation, owner.ID); !owns {
		t.Fatal("owner not recorded")
	}
	if owns, _ := s.UserOwnsAIContextInstallation(t.Context(), installation, other.ID); owns {
		t.Fatal("ownership leaked to another user")
	}

	// Ownership confers no source access.
	if allowed, _ := s.AIContextUserAccess(t.Context(), r.ID, owner.ID); allowed {
		t.Fatal("owning an installation must not make anyone a reader")
	}

	rows, total, err := s.ListAIContextRepositoriesOwnedBy(t.Context(), 50, 0, "", "", owner.ID)
	if err != nil || total != 1 || len(rows) != 1 {
		t.Fatal("owner listing", total, err)
	}
	if _, total, _ = s.ListAIContextRepositoriesOwnedBy(t.Context(), 50, 0, "", "", other.ID); total != 0 {
		t.Fatal("a non-owner listed repositories")
	}
	if _, total, _ = s.ListAIContextRepositoriesOwnedBy(t.Context(), 50, 0, installation, "", other.ID); total != 0 {
		t.Fatal("naming the installation must not widen a non-owner's listing")
	}

	refs, err := s.AIContextOwnedInstallations(t.Context(), owner.ID)
	if err != nil || len(refs) != 1 || refs[0].ID != installation {
		t.Fatal("owned installations", refs, err)
	}

	// A disabled user owns nothing, without anyone having to clean up.
	owner.Disabled = true
	if err := s.UpdateUser(t.Context(), owner); err != nil {
		t.Fatal(err)
	}
	if owns, _ := s.UserOwnsAIContextInstallation(t.Context(), installation, owner.ID); owns {
		t.Fatal("a disabled owner kept their authority")
	}
	owner.Disabled = false
	if err := s.UpdateUser(t.Context(), owner); err != nil {
		t.Fatal(err)
	}

	if err := s.DeleteUser(t.Context(), owner.ID); err != nil {
		t.Fatal(err)
	}
	if ids, _ := s.AIContextInstallationOwners(t.Context(), installation); len(ids) != 0 {
		t.Fatal("deleting a user left them as an owner", ids)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

type AIContextSetup struct {
	RepositoryID string    `json:"repository_id"`
	Revision     int64     `json:"revision"`
	PlanHash     string    `json:"plan_hash"`
	PlanJSON     string    `json:"-"`
	State        string    `json:"state"`
	PRNumber     int       `json:"pr_number"`
	PRURL        string    `json:"pr_url"`
	LeaseToken   string    `json:"-"`
	LeaseUntil   time.Time `json:"-"`
}

func (s *Store) GetAIContextSetup(ctx context.Context, id string) (*AIContextSetup, error) {
	var r AIContextSetup
	var lease int64
	err := s.read.QueryRowContext(ctx, `SELECT repository_id,revision,plan_hash,plan_json,state,pr_number,pr_url,lease_token,lease_until FROM ai_context_setups WHERE repository_id=?`, id).Scan(&r.RepositoryID, &r.Revision, &r.PlanHash, &r.PlanJSON, &r.State, &r.PRNumber, &r.PRURL, &r.LeaseToken, &lease)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	r.LeaseUntil = at(lease)
	return &r, err
}

// ClaimAIContextSetup freezes the reviewed configuration before any write.
// The lease serialises calls across restarts; retries retain the same plan.
func (s *Store) ClaimAIContextSetup(ctx context.Context, r *AIContextSetup) error {
	if len(r.PlanJSON) > 4<<20 || len(r.PlanHash) != 64 || r.Revision < 1 {
		return fmt.Errorf("invalid context setup plan")
	}
	token := NewID("ctxlease")
	now := s.Now()
	err := s.tx(ctx, func(tx *sql.Tx) error {
		var revision int64
		if err := tx.QueryRowContext(ctx, `SELECT revision FROM ai_context_repositories WHERE id=?`, r.RepositoryID).Scan(&revision); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return ErrNotFound
			}
			return err
		}
		if revision != r.Revision {
			return ErrConflict
		}
		_, err := tx.ExecContext(ctx, `INSERT INTO ai_context_setups(repository_id,revision,plan_hash,plan_json,state,updated_at) VALUES(?,?,?,?,'pending',?) ON CONFLICT(repository_id) DO NOTHING`, r.RepositoryID, r.Revision, r.PlanHash, r.PlanJSON, ms(now))
		if err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `UPDATE ai_context_setups SET lease_token=?,lease_until=?,updated_at=? WHERE repository_id=? AND revision=? AND plan_hash=? AND state='pending' AND lease_until<=?`, token, ms(now.Add(5*time.Minute)), ms(now), r.RepositoryID, r.Revision, r.PlanHash, ms(now))
		if err != nil {
			return err
		}
		n, err := res.RowsAffected()
		if err != nil {
			return err
		}
		if n != 1 {
			return ErrConflict
		}
		return nil
	})
	if err == nil {
		r.LeaseToken = token
		r.State = "pending"
	}
	return err
}

func (s *Store) ReleaseAIContextSetup(ctx context.Context, id, token string) error {
	_, err := s.exec(ctx, `UPDATE ai_context_setups SET lease_token='',lease_until=0 WHERE repository_id=? AND lease_token=?`, id, token)
	return err
}

func (s *Store) CompleteAIContextSetup(ctx context.Context, id, token string, number int, url string) error {
	if number <= 0 || url == "" {
		return fmt.Errorf("setup needs the reviewed pull request identity")
	}
	res, err := s.exec(ctx, `UPDATE ai_context_setups SET state='awaiting_merge',pr_number=?,pr_url=?,lease_token='',lease_until=0,updated_at=? WHERE repository_id=? AND lease_token=? AND state='pending'`, number, url, ms(s.Now()), id, token)
	if err != nil {
		return err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n != 1 {
		return ErrConflict
	}
	return nil
}

