	}
	sess := &Session{UserID: u.ID, TokenHash: "hash-1", ExpiresAt: s.Now().Add(time.Hour)}
	if err := s.CreateSession(ctx, sess); err != nil {
		t.Fatalf("CreateSession: %v", err)
