		t.Fatalf("pool round-tripped wrong: %+v", got)
	}
	if got.CostPerRunnerHour == nil || *got.CostPerRunnerHour != 0.25 {
		t.Fatalf("cost_per_runner_hour = %v, want 0.25", got.CostPerRunnerHour)
	}
