func TestUsageHistoryOutcomesAndHostAttribution(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "history-runner", State: RunnerIdle}
	if err := s.CreateRunner(ctx, r); err != nil {
		t.Fatal(err)
	}
	if _, err := s.exec(ctx, `UPDATE runners SET created_at=?,finished_at=? WHERE id=?`, ms(usageAt(0)), ms(usageAt(120)), r.ID); err != nil {
		t.Fatal(err)
	}
	for i, c := range []string{"success", "failure", "cancelled", "", "success"} {
		start, done := usageAt(30), usageAt(60)
		j := &Job{GitHubJobID: int64(990 + i), Repo: "acme/history", PoolID: pool.ID, RunnerID: r.ID, State: JobCompleted, QueuedAt: usageAt(0), StartedAt: &start, CompletedAt: &done, Conclusion: c}
		if i == 4 {
			j.RunnerFault = "runner disappeared"
		}
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatal(err)
		}
	}
	row := usageRow(t, s, usageAt(0), usageAt(120), UsageByHost, host.ID)
	if row.Succeeded != 1 || row.Failed != 2 || row.Cancelled != 1 || row.Unknown != 1 {
		t.Fatalf("outcomes: %+v", row)
	}
	if row.AllocatedRunnerSeconds == nil || *row.AllocatedRunnerSeconds != 7200 {
		t.Fatalf("host allocation: %+v", row)
	}
	if len(row.History) != 2 || row.History[0].Queued != 5 || row.History[0].Succeeded != 0 || row.History[1].Succeeded != 1 || row.History[1].Failed != 2 {
		t.Fatalf("half-open buckets: %+v", row.History)
	}
	if row.History[0].ExecutionSeconds != 9000 || row.History[1].ExecutionSeconds != 0 {
		t.Fatalf("execution clipping: %+v", row.History)
	}
}

func TestUsageHistoryIncludesOngoingWorkWithoutInventingFutureTime(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)
	s.now = func() time.Time { return usageAt(90) }
	seedUsageJob(t, s, pool.ID, "acme/ongoing", 0, mins(30), nil)
	row := usageRow(t, s, usageAt(0), usageAt(180), UsageByPool, pool.ID)
	if row.JobExecutionSeconds != 3600 || row.PeakConcurrency != 1 || row.JobsCompleted != 0 {
		t.Fatalf("ongoing work: %+v", row)
	}
	if row.History[0].ExecutionSeconds != 1800 || row.History[1].ExecutionSeconds != 1800 || row.History[2].ExecutionSeconds != 0 {
		t.Fatalf("time beyond observation: %+v", row.History)
	}
}

func TestUsageCapacityCoalescesAndPrunesWithoutInventingCoverage(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, _ := seedPool(t, s)
	for _, blocked := range []bool{false, true, false, true} {
		if err := s.RecordUsageCapacity(ctx, pool.ID, usageAt(1), blocked); err != nil {
			t.Fatal(err)
		}
	}
	row := usageRow(t, s, usageAt(0), usageAt(120), UsageByPool, pool.ID)
	if row.History[0].CapacitySamples != 1 || row.History[0].CapacityReached != 1 || row.History[1].CapacitySamples != 0 {
		t.Fatalf("coverage: %+v", row.History)
	}
	n, err := s.PruneUsageCapacity(ctx, usageAt(2))
	if err != nil || n != 1 {
		t.Fatalf("prune: %d %v", n, err)
	}
	rows, err := s.Usage(ctx, usageAt(0), usageAt(120), UsageByPool)
	if err != nil || len(rows) != 0 {
		t.Fatalf("pruned: %+v %v", rows, err)
	}
}

// A week asked for in hours is a week of hours, whatever the window's length
// would have chosen for itself: the activity matrix draws a week as a punch
// card, one square an hour, and the rule that cuts a week into days is the
// rule for a caller that did not say.
func TestUsageHistoryTakesTheIntervalItIsAskedFor(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	_, pool, _ := seedPool(t, s)
	seedUsageJob(t, s, pool.ID, "acme/hours", 0, mins(30), mins(90))

	week := usageAt(7 * 24 * 60)
	rows, err := s.UsageWithInterval(ctx, usageAt(0), week, UsageByPool, UsageHourly)
	if err != nil {
		t.Fatalf("hourly: %v", err)
	}
	if len(rows) != 1 || len(rows[0].History) != 7*24 {
		t.Fatalf("a week in hours: %d rows, %d buckets", len(rows), len(rows[0].History))
	}
	if h := rows[0].History; h[0].Queued != 1 || h[0].Started != 1 || h[1].Unknown != 1 {
		t.Fatalf("the job is in the hours it happened in: %+v %+v", h[0], h[1])
	}

	// The same week, left to the rule, is seven days.
	rows, err = s.UsageWithInterval(ctx, usageAt(0), week, UsageByPool, UsageAutoInterval)
	if err != nil {
		t.Fatalf("auto: %v", err)
	}
	if len(rows[0].History) != 7 {
		t.Fatalf("a week left to the rule: %d buckets", len(rows[0].History))
	}

	// And a day asked for in days is one bucket, where the rule would give 24.
	rows, err = s.UsageWithInterval(ctx, usageAt(0), usageAt(24*60), UsageByPool, UsageDaily)
	if err != nil {
		t.Fatalf("daily: %v", err)
	}
	if len(rows[0].History) != 1 || rows[0].History[0].Unknown != 1 {
		t.Fatalf("a day in days: %+v", rows[0].History)
	}

	// And in eight hours it is three, each starting eight hours after the
	// last, which is what lets a calendar cut every day into the same squares.
	rows, err = s.UsageWithInterval(ctx, usageAt(0), usageAt(24*60), UsageByPool, "8h")
	if err != nil {
		t.Fatalf("eight-hourly: %v", err)
	}
	h := rows[0].History
	if len(h) != 3 || h[0].Queued != 1 || h[0].Unknown != 1 {
		t.Fatalf("a day in eight hours: %+v", h)
	}
	if !h[1].From.Equal(usageAt(8*60)) || !h[2].From.Equal(usageAt(16*60)) {
		t.Fatalf("eight-hour buckets start at %v and %v", h[1].From, h[2].From)
	}
}

// Only the widths a day divides into are widths: a five-hour bucket would
// straddle midnight, and a calendar has nowhere to put the half on the wrong
// day.
func TestOnlyTheWidthsADayDividesIntoAreKnown(t *testing.T) {
	for _, known := range []UsageInterval{UsageAutoInterval, UsageHourly, "2h", "3h", "4h", "6h", "8h", "12h", UsageDaily} {
		if !known.Known() {
			t.Errorf("%q is not known", known)
		}
	}
	for _, unknown := range []UsageInterval{"5h", "24h", "1h", "minute", "week"} {
		if unknown.Known() {
			t.Errorf("%q is known", unknown)
		}
	}
}

package store

import (
	"context"
	"testing"
	"time"
)

var usageEpoch = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)

// seedUsageJob writes one job whose lifecycle timestamps are offsets in minutes
// from usageEpoch. A nil offset leaves that timestamp unset, which is how a job
// that never started or never finished is expressed.
func seedUsageJob(t *testing.T, s *Store, poolID, repo string, queued int, started, completed *int) {
	t.Helper()
	at := func(m int) time.Time { return usageEpoch.Add(time.Duration(m) * time.Minute) }
	j := &Job{
		GitHubJobID: int64(len(repo)*1000 + queued),
		Repo:        repo,
		Workflow:    "build",
		State:       JobQueued,
		PoolID:      poolID,
		QueuedAt:    at(queued),
	}
	if started != nil {
		v := at(*started)
		j.StartedAt, j.State = &v, JobInProgress
	}
	if completed != nil {
		v := at(*completed)
		j.CompletedAt, j.State = &v, JobCompleted
	}
	if _, err := s.UpsertJob(context.Background(), j); err != nil {
		t.Fatalf("UpsertJob: %v", err)
	}
}

func usageAt(m int) time.Time { return usageEpoch.Add(time.Duration(m) * time.Minute) }

func mins(m int) *int { return &m }

func usageRow(t *testing.T, s *Store, from, to time.Time, group UsageGroup, key string) UsageRow {
	t.Helper()
	rows, err := s.Usage(context.Background(), from, to, group)
	if err != nil {
		t.Fatalf("Usage: %v", err)
	}
	for _, r := range rows {
		if r.Key == key {
			return r
		}
	}
	t.Fatalf("Usage returned no row for %q; got %+v", key, rows)
	return UsageRow{}
}

// The average is the mean of the jobs that actually started. Dividing one
// observed 60s wait by ten jobs, nine of which are still queued, reported six
// seconds during exactly the incident an operator is looking at the page for.
func TestAverageQueueWaitCountsOnlyJobsThatStarted(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)
	seedUsageJob(t, s, pool.ID, "acme/one", 0, mins(1), mins(5))
	for i := 1; i < 10; i++ {
		seedUsageJob(t, s, pool.ID, "acme/one", i, nil, nil)
	}
	row := usageRow(t, s, usageAt(-10), usageAt(60), UsageByPool, pool.ID)
	if row.AverageQueueWaitSeconds == nil {
		t.Fatal("average queue wait is nil, but one job started")
	}
	if got := *row.AverageQueueWaitSeconds; got != 60 {
		t.Fatalf("average queue wait = %vs, want 60s over the one job with an observed wait", got)
	}
	if row.Jobs != 10 || row.JobsStarted != 1 {
		t.Fatalf("jobs = %d, started = %d, want 10 and 1", row.Jobs, row.JobsStarted)
	}
}

// An interval in which nothing got off the queue has no average to report, and
// saying so is the difference between "fast" and "nothing is moving".
func TestAverageQueueWaitIsAbsentWhenNothingStarted(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)
	seedUsageJob(t, s, pool.ID, "acme/one", 0, nil, nil)
	row := usageRow(t, s, usageAt(-10), usageAt(60), UsageByPool, pool.ID)
	if row.AverageQueueWaitSeconds != nil {
		t.Fatalf("average queue wait = %v, want nil when no job started", *row.AverageQueueWaitSeconds)
	}
}

// Counting a job once per lifecycle event, rather than once per interval it
// spans, is what lets an operator add two months together.
func TestJobCountsAreAdditiveAcrossAdjacentIntervals(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)
	// Queued in the first hour, started and finished in the second.
	seedUsageJob(t, s, pool.ID, "acme/one", 10, mins(70), mins(80))
	// Wholly inside the first hour.
	seedUsageJob(t, s, pool.ID, "acme/one", 20, mins(25), mins(30))

	first := usageRow(t, s, usageAt(0), usageAt(60), UsageByPool, pool.ID)
	second := usageRow(t, s, usageAt(60), usageAt(120), UsageByPool, pool.ID)
	whole := usageRow(t, s, usageAt(0), usageAt(120), UsageByPool, pool.ID)

	if first.Jobs+second.Jobs != whole.Jobs || whole.Jobs != 2 {
		t.Fatalf("queued counts %d + %d != %d", first.Jobs, second.Jobs, whole.Jobs)
	}
	if first.JobsStarted+second.JobsStarted != whole.JobsStarted || whole.JobsStarted != 2 {
		t.Fatalf("started counts %d + %d != %d", first.JobsStarted, second.JobsStarted, whole.JobsStarted)
	}
	if first.JobsCompleted+second.JobsCompleted != whole.JobsCompleted || whole.JobsCompleted != 2 {
		t.Fatalf("completed counts %d + %d != %d", first.JobsCompleted, second.JobsCompleted, whole.JobsCompleted)
	}
	if first.Jobs != 2 || first.JobsCompleted != 1 {
		t.Fatalf("first hour = %d queued, %d completed, want 2 and 1", first.Jobs, first.JobsCompleted)
	}
}

// A job that spans a whole interval without a lifecycle event in it still
// contributes the time it spent running, which is what the interval is about.
func TestExecutionSecondsAreClippedToTheInterval(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)
	seedUsageJob(t, s, pool.ID, "acme/one", 0, mins(5), mins(125))
	row := usageRow(t, s, usageAt(60), usageAt(120), UsageByPool, pool.ID)
	if row.JobExecutionSeconds != 3600 {
		t.Fatalf("execution seconds = %v, want the full hour it ran inside the window", row.JobExecutionSeconds)
	}
	if row.Jobs != 0 || row.JobsStarted != 0 || row.JobsCompleted != 0 {
		t.Fatalf("a job with no lifecycle event in the window was counted: %+v", row)
	}
}

// Runner-hours belong to the pool that kept the runner alive; pretending a
// repository owns a share of an idle runner would be an invented number.
func TestAllocationIsAbsentForGroupingsThatCannotAttributeIt(t *testing.T) {
	s := newTestStore(t)
	_, pool, host := seedPool(t, s)
	r := &Runner{PoolID: pool.ID, HostID: host.ID, Name: "runner-1", State: RunnerIdle}
	if err := s.CreateRunner(context.Background(), r); err != nil {
		t.Fatalf("CreateRunner: %v", err)
	}
	seedUsageJob(t, s, pool.ID, "acme/one", 0, mins(1), mins(5))

	byPool := usageRow(t, s, usageAt(-10), usageAt(60), UsageByPool, pool.ID)
	if byPool.AllocatedRunnerSeconds == nil {
		t.Fatal("allocated runner seconds is nil for a pool, which can attribute it")
	}
	byRepo := usageRow(t, s, usageAt(-10), usageAt(60), UsageByRepository, "acme/one")
	if byRepo.AllocatedRunnerSeconds != nil {
		t.Fatalf("allocated runner seconds = %v by repository, want nil", *byRepo.AllocatedRunnerSeconds)
	}
	if !UsageAllocationAttributable(UsageByInstallation) || UsageAllocationAttributable(UsageByWorkflow) {
		t.Fatal("UsageAllocationAttributable disagrees with what Usage actually fills in")
	}
}

// A job with no pool reaches no installation, and the grouping reaches the
// installation through the pool. That NULL used to fail the whole query, so a
// window containing one such job answered with an error rather than a report.
//
// The job that used to demonstrate it was one GitHub ran on its own hosted
// runners; those are now excluded from usage altogether. A queued job no pool
// has claimed is the case that remains, and it is one this fleet should see:
// nothing ran it, which is the fleet's problem rather than somebody else's
// work.
func TestUsageByInstallationTolerantOfJobsWithoutAPool(t *testing.T) {
	s := newTestStore(t)
	seedUsageJob(t, s, "", "acme/widgets", 0, nil, nil)

	rows, err := s.Usage(context.Background(), usageAt(0), usageAt(10), UsageByInstallation)
	if err != nil {
		t.Fatalf("Usage by installation with a pool-less job: %v", err)
	}
	if len(rows) != 1 || rows[0].Key != "" || rows[0].Jobs != 1 {
		t.Fatalf("got %+v, want one row under the empty key counting the job", rows)
	}
}

// TestUsageCountsOnlyThisFleetsJobs is what makes the page a report about this
// fleet rather than about the organisation's whole Actions bill.
//
// A job GitHub ran on one of its own hosted runners consumed no runner-hour
// here, waited in no queue of ours and cost this fleet nothing. Counting it
// inflates every figure on the page -- and grouped by installation it invents a
// row under the empty key for runners that were never ours.
func TestUsageCountsOnlyThisFleetsJobs(t *testing.T) {
	s := newTestStore(t)
	_, pool, _ := seedPool(t, s)

	// Ours: claimed by a pool, started and finished inside the window.
	seedUsageJob(t, s, pool.ID, "acme/widgets", 0, mins(1), mins(3))
	// Somebody else's: no pool ever claimed it, and it ran to completion
	// elsewhere. Longer, and overlapping ours, so neither its runner-hours nor
	// its concurrency can hide in the other's. The differing queue minute is
	// what gives it a GitHub job ID of its own -- seeded with the same one it
	// would upsert over the first and the fixture would prove nothing.
	seedUsageJob(t, s, "", "acme/widgets", 1, mins(1), mins(6))

	byRepo := usageRow(t, s, usageAt(-10), usageAt(60), UsageByRepository, "acme/widgets")
	if byRepo.Jobs != 1 || byRepo.JobsStarted != 1 || byRepo.JobsCompleted != 1 {
		t.Errorf("counted %d queued, %d started, %d completed; the hosted job is in the report",
			byRepo.Jobs, byRepo.JobsStarted, byRepo.JobsCompleted)
	}
	// Two minutes of execution, not seven: the hosted job's five are not this
	// fleet's to report.
	if want := (2 * time.Minute).Seconds(); byRepo.JobExecutionSeconds != want {
		t.Errorf("execution = %.0fs, want %.0fs", byRepo.JobExecutionSeconds, want)
	}
	// And concurrency is what this fleet actually ran at once. The two jobs
	// overlap, so an unfiltered report would say two.
	if byRepo.PeakConcurrency != 1 {
		t.Errorf("peak concurrency = %d, want 1: the hosted job was never running here",
			byRepo.PeakConcurrency)
	}

	// Grouped by installation there is one row, the pool's, and no empty-key
	// row invented for machines that were never ours.
	rows, err := s.Usage(context.Background(), usageAt(-10), usageAt(60), UsageByInstallation)
	if err != nil {
		t.Fatalf("Usage by installation: %v", err)
	}
	for _, r := range rows {
		if r.Key == "" {
			t.Errorf("a row appeared under the empty key: %+v", r)
		}
	}
}

package store

import (
	"context"
	"fmt"
	"strconv"
)

// SettingRecoveryFenced is the key the recovery fence lives under.
//
// It is a row in this database rather than a line in zoomies.yaml, and that is
// deliberate: the fence belongs to the *data*, not to the host. A restored
// database is fenced wherever it is put, and a copy of it taken to a second
// machine arrives fenced too -- which is the case the fence exists for, since
// two controllers reconciling one fleet's runners from the same rows is how a
// restore turns into an outage.
//
// The `settings` table it uses shares a name with the settings API and none of
// its data: that API renders the effective configuration, which this is not.
const SettingRecoveryFenced = "recovery.fenced"

// SettingRecoveryFencedReason says why, so the problem the controller raises
// can name the restore rather than the flag.
const SettingRecoveryFencedReason = "recovery.fenced_reason"

// RecoveryFence is the fence's state, and why it is on.
type RecoveryFence struct {
	Fenced bool   `json:"fenced"`
	Reason string `json:"reason,omitempty"`
}

// RecoveryFenced reads the fence.
func (s *Store) RecoveryFenced(ctx context.Context) (RecoveryFence, error) {
	raw, err := s.GetSetting(ctx, SettingRecoveryFenced)
	if err != nil {
		return RecoveryFence{}, err
	}
	if raw == "" {
		return RecoveryFence{}, nil
	}
	on, err := strconv.ParseBool(raw)
	if err != nil {
		// A value nobody can parse is not a reason to run unfenced. The fence
		// is the safe side of this question, and an unreadable setting is
		// exactly the sort of thing a half-finished restore leaves behind.
		return RecoveryFence{Fenced: true, Reason: fmt.Sprintf("%s is set to %q, which is not a yes or a no", SettingRecoveryFenced, raw)}, nil
	}
	if !on {
		return RecoveryFence{}, nil
	}
	reason, err := s.GetSetting(ctx, SettingRecoveryFencedReason)
	if err != nil {
		return RecoveryFence{Fenced: true}, err
	}
	return RecoveryFence{Fenced: true, Reason: reason}, nil
}

// SetRecoveryFence turns the fence on with a reason, or off.
func (s *Store) SetRecoveryFence(ctx context.Context, fenced bool, reason string) error {
	if !fenced {
		if err := s.DeleteSetting(ctx, SettingRecoveryFencedReason); err != nil {
			return err
		}
		return s.DeleteSetting(ctx, SettingRecoveryFenced)
	}
	if err := s.SetSetting(ctx, SettingRecoveryFenced, "true", false); err != nil {
		return err
	}
	return s.SetSetting(ctx, SettingRecoveryFencedReason, reason, false)
}

// ---------------------------------------------------------------------------
// Credentials a restore invalidates
// ---------------------------------------------------------------------------

// DeleteAllSessions signs everyone out.
//
// A restore brings back sessions that were live when the backup was taken, and
// a browser cookie from that afternoon still matches one. Whoever was signed in
// then is signed in now, on a machine they may no longer have anything to do
// with -- so a restore ends every session and everyone signs in again.
func (s *Store) DeleteAllSessions(ctx context.Context) (int64, error) {
	res, err := s.exec(ctx, `DELETE FROM sessions`)
	if err != nil {
		return 0, fmt.Errorf("store: ending every session: %w", err)
	}
	return res.RowsAffected()
}

// DeleteUnusedJoinTokens removes the join tokens that were never redeemed.
//
// An unused join token is a credential that enrols a new host, and the backup
// froze it in the state where it still works. The ones already redeemed are
// left: they are history, they cannot be used again, and deleting them would
// take the record of how each host got here.
func (s *Store) DeleteUnusedJoinTokens(ctx context.Context) (int64, error) {
	res, err := s.exec(ctx, `DELETE FROM join_tokens WHERE used_at IS NULL`)
	if err != nil {
		return 0, fmt.Errorf("store: removing unused join tokens: %w", err)
	}
	return res.RowsAffected()
}

// MarkMachinesUnverified takes away every machine's proof of ownership.
//
// A restored database is a copy, and the machines it names may have been
// deleted, rebuilt or handed to somebody else since the backup was taken. The
// stamp is what a delete needs, so clearing it means this copy has to look at
// each resource and agree it is still ours before it may destroy anything --
// which is the difference between a restore and a fleet that deletes a VM
// somebody else is now using.
//
// Nothing else is touched: the rows, the resources and the hosts are all still
// there, and re-proving ownership is a pass's ordinary work.
func (s *Store) MarkMachinesUnverified(ctx context.Context) (int64, error) {
	res, err := s.exec(ctx, `UPDATE machines SET ownership_verified_at=NULL
		WHERE ownership_verified_at IS NOT NULL`)
	if err != nil {
		return 0, fmt.Errorf("store: marking every machine's ownership unverified: %w", err)
	}
	return res.RowsAffected()
}

// RevokeAllAPITokens disables every API token without deleting its row, so the
// audit trail still says what each one was and when it stopped working.
func (s *Store) RevokeAllAPITokens(ctx context.Context) (int64, error) {
	res, err := s.exec(ctx, `UPDATE api_tokens SET revoked=1 WHERE revoked=0`)
	if err != nil {
		return 0, fmt.Errorf("store: revoking API tokens: %w", err)
	}
	return res.RowsAffected()
}

// ResetAgentTokens forgets every host's agent credential, so each agent has to
// join again.
//
// The behaviour it relies on already exists: an agent whose token this database
// no longer holds exits with the command to re-join rather than retrying
// forever. Hosts, pools and history are kept -- this invalidates the credential
// and nothing else.
func (s *Store) ResetAgentTokens(ctx context.Context) (int64, error) {
	res, err := s.exec(ctx, `UPDATE hosts SET token_hash='' WHERE token_hash<>''`)
	if err != nil {
		return 0, fmt.Errorf("store: resetting agent tokens: %w", err)
	}
	return res.RowsAffected()
}

