import (
	"context"
	"fmt"
	"math/rand"
	"sort"
	"strings"
	"testing"
	"time"
)

// The usage report used to ask for the jobs around in a window as one
// condition on two columns, which neither index could serve. It now asks three
// questions the indexes can. Both have to name the same jobs, including the
// ones a tidy table would not have: finished with no finish time, and still
// open with a stale one.
func TestTheUsageWindowNamesTheSameJobsAsTheConditionItReplaced(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	base := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	rng := rand.New(rand.NewSource(3))

	states := []string{"waiting", "queued", "in_progress", "completed"}
	for i := 0; i < 600; i++ {
		queued := base.Add(time.Duration(rng.Intn(20*24)) * time.Hour)
		state := states[rng.Intn(len(states))]
		var completed any
		switch rng.Intn(3) {
		case 0: // a finish time, plausibly after the queue time
			completed = queued.Add(time.Duration(rng.Intn(48)) * time.Hour).UnixMilli()
		case 1: // none: unfinished, or finished with the stamp lost
			completed = nil
		default: // a stamp on a job that is not finished
			completed = queued.Add(time.Hour).UnixMilli()
		}
		if _, err := s.write.ExecContext(ctx, `INSERT INTO jobs (id, github_job_id, state, queued_at, completed_at)
			VALUES (?, ?, ?, ?, ?)`, fmt.Sprintf("job_%04d", i), 5000+i, state, queued.UnixMilli(), completed); err != nil {
			t.Fatal(err)
		}
	}

	ids := func(query string, args ...any) string {
		rows, err := s.read.QueryContext(ctx, query, args...)
		if err != nil {
			t.Fatalf("%v\n%s", err, query)
		}
		defer rows.Close()
		var out []string
		for rows.Next() {
			var id string
			if err := rows.Scan(&id); err != nil {
				t.Fatal(err)
			}
			out = append(out, id)
		}
		sort.Strings(out)
		return strings.Join(out, ",")
	}

	for _, w := range []struct{ from, to time.Duration }{
		{0, 24 * time.Hour}, {5 * 24 * time.Hour, 12 * 24 * time.Hour}, {-time.Hour, 21 * 24 * time.Hour},
		{19 * 24 * time.Hour, 40 * 24 * time.Hour}, {30 * 24 * time.Hour, 31 * 24 * time.Hour},
	} {
		from, to := base.Add(w.from), base.Add(w.to)
		want := ids(`SELECT id FROM jobs WHERE queued_at < ? AND COALESCE(completed_at, ?) >= ?`, ms(to), ms(to), ms(from))
		got := ids(`SELECT id FROM `+usageJobsInWindowSQL, usageWindowArgs(from, to)...)
		if got != want {
			t.Errorf("window %s to %s: the three ranges name different jobs than the one condition\n got  %s\n want %s", from, to, got, want)
		}
		if want == "" && w.from == 0 {
			t.Error("the fixture put no job in the first window, so it proves nothing")
		}
	}
}

package store

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The write-ahead log grows while a reader holds an old snapshot, because a
// checkpoint cannot move pages past what that reader may still need. That is
// SQLite working as designed. What must not happen is the file staying at its
// high-water mark for ever afterwards: a backup verification or a long report
// on a busy fleet would leave a log hundreds of megabytes long on the disk the
// runners' images and caches share, for the life of the process.
func TestTheWriteAheadLogShrinksOnceTheReaderHoldingItBackIsDone(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "zoomies.db")
	s, err := Open(ctx, Options{Path: path})
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { s.Close() })

	if _, err := s.exec(ctx, `CREATE TABLE wal_probe (id INTEGER PRIMARY KEY, body TEXT NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	body := strings.Repeat("x", 4096)
	write := func(n int) {
		t.Helper()
		for range n {
			if _, err := s.exec(ctx, `INSERT INTO wal_probe (body) VALUES (?)`, body); err != nil {
				t.Fatal(err)
			}
		}
	}
	walSize := func() int64 {
		t.Helper()
		fi, err := os.Stat(path + "-wal")
		if err != nil {
			return 0
		}
		return fi.Size()
	}

	// A reader holds a snapshot open while a good deal is written: a query the
	// way the store makes them, one statement on the read pool, still being
	// read. (Not a transaction on the read pool -- both pools share a DSN that
	// begins every transaction IMMEDIATE, so one would take the write lock.)
	write(10)
	rows, err := s.read.QueryContext(ctx, `SELECT id FROM wal_probe`)
	if err != nil {
		t.Fatal(err)
	}
	if !rows.Next() {
		t.Fatal("the probe table is empty")
	}
	write(6000)
	grown := walSize()
	if err := rows.Close(); err != nil {
		t.Fatal(err)
	}

	// The reader is gone; ordinary writing carries on, and the automatic
	// checkpoints it triggers can now reach the end of the log.
	write(3000)
	settled := walSize()
	t.Logf("log while held: %d MB; after the reader finished and writing went on: %d MB", grown>>20, settled>>20)

	if grown < 16<<20 {
		t.Fatalf("the log only reached %d MB while held; the fixture has not reproduced a large one", grown>>20)
	}
	if settled > walSizeLimit {
		t.Errorf("the log is still %d MB after the reader that held it back finished, against %d MB while held and a limit of %d MB; it never gives the space back", settled>>20, grown>>20, walSizeLimit>>20)
	}
}

package store

import (
	"context"
	"database/sql"
	"errors"
	"strings"
	"time"
)

// ---------------------------------------------------------------------------
// Workflow runs
// ---------------------------------------------------------------------------

// WorkflowRun is one workflow run as this fleet has seen it: the jobs GitHub
// reported under one run, summed up into the row the Workflows page lists. It
// is the "#1009" an operator finds in GitHub's Actions tab, so the two can be
// read side by side.
//
// It is derived, never stored. Only workflow_job deliveries are ingested, so
// everything known about a run is what its jobs said, and a row of its own
// would be one more thing for a late or missing delivery to leave stale. The
// summary is over the latest attempt of each job name, which is what GitHub's
// own run page shows: re-running the failed jobs writes new job rows under the
// same run, and a run whose second attempt passed is a run that passed.
type WorkflowRun struct {
	Repo        string
	GitHubRunID int64
	Workflow    string
	// RunNumber is GitHub's own sequential number for the run. Zero until a
	// job of the run has had it backfilled, since workflow_job deliveries do
	// not carry it.
	RunNumber int64
	// RunAttempt is the highest attempt any job of the run reported.
	RunAttempt     int
	HeadBranch     string
	HeadSHA        string
	InstallationID string
	// HTMLURL is the run's page on GitHub, cut from a job's own URL.
	HTMLURL string
	// State is the run's, worked out from its jobs: running while any job is,
	// then queued while any job waits for a runner, then waiting while any is
	// held for a review, and completed once every job is.
	State JobState
	// Conclusion is the run's once it is completed, worst outcome first: a
	// failure on either side, then cancelled, then action required, then
	// success. Empty while the run is not completed.
	Conclusion string
	// QueuedAt is when the first job was queued, StartedAt when the first job
	// started, and CompletedAt when the last job finished -- set only once
	// every job has, because a run with a job still to go has not completed.
	QueuedAt    time.Time
	StartedAt   *time.Time
	CompletedAt *time.Time
	Jobs        RunJobCounts
	// Managed is whether this fleet has a hand in any job of the run, in the
	// sense of JobFilter.ManagedOnly.
	Managed bool
	// Hosted is whether every job's labels name runners somebody else operates.
	Hosted bool
	// Cancelling is whether an operator's cancellation of the run has been
	// accepted by GitHub and not yet confirmed by its jobs completing.
	Cancelling bool
}

// RunJobCounts is how a run's jobs are getting on, counted over the latest
// attempt of each. Failed counts failures on either side, so Faulted -- the
// failures this fleet caused -- is always part of it, and a job whose runner
// stopped under it is a failure whatever conclusion GitHub recorded: the
// fault wins, as it does on the Overview, so the outcomes never count one
// job twice.
type RunJobCounts struct {
	Total      int `json:"total"`
	Waiting    int `json:"waiting"`
	Queued     int `json:"queued"`
	InProgress int `json:"in_progress"`
	Completed  int `json:"completed"`
	Succeeded  int `json:"succeeded"`
	Failed     int `json:"failed"`
	Cancelled  int `json:"cancelled"`
	Skipped    int `json:"skipped"`
	Faulted    int `json:"faulted"`
	// Unmatched counts the queued jobs no enabled pool claims and nobody else
	// is about to run: the ones the Jobs page's unmatched filter finds.
	Unmatched int `json:"unmatched"`
	// Expedited, Paused and Removed count what an operator has done to the
	// run's queued jobs' provisioning demand -- Run now, Pause and Delete
	// from queue on the Queue page. They are part of Queued, not beside it:
	// GitHub goes on calling a paused job queued, and so does the run. The
	// row needs them so a Pause pressed on the run can be refused, with a
	// reason, once every queued job of it is already paused.
	Expedited int `json:"expedited"`
	Paused    int `json:"paused"`
	Removed   int `json:"removed"`
}

// Controllable is how many of the run's queued jobs a run-level provisioning
// action reaches: the queued ones an operator has not removed from the queue.
// A removed job was stood down on purpose, and is restored from the Queue
// page's Removed view rather than swept back in by a Run now on its run.
func (c RunJobCounts) Controllable() int {
	return c.Queued - c.Removed
}

// QueueWait is how long the run waited before any of its jobs was picked up.
func (r *WorkflowRun) QueueWait() time.Duration {
	if r.StartedAt == nil {
		return 0
	}
	return r.StartedAt.Sub(r.QueuedAt)
}

// Duration is how long the run took from its first job starting to its last
// finishing, or 0 while it has not finished.
func (r *WorkflowRun) Duration() time.Duration {
	if r.StartedAt == nil || r.CompletedAt == nil {
		return 0
	}
	return r.CompletedAt.Sub(*r.StartedAt)
}

// runStateSQL and runConclusionSQL are the run's state and conclusion as SQL
// over its jobs' aggregates, so a page can be filtered by them rather than by
// its jobs' states -- "runs with a queued job" is not "queued runs", because a
// run with one job running and another queued is running.
const runStateSQL = `CASE
	WHEN SUM(state = 'in_progress') > 0 THEN 'in_progress'
	WHEN SUM(state = 'queued') > 0 THEN 'queued'
	WHEN SUM(state = 'waiting') > 0 THEN 'waiting'
	ELSE 'completed' END`

func runConclusionSQL() string {
	return `CASE
	WHEN SUM(state != 'completed') > 0 THEN ''
	WHEN SUM(` + failedJobSQL() + `) > 0 THEN 'failure'
	WHEN SUM(conclusion = 'cancelled') > 0 THEN 'cancelled'
	WHEN SUM(conclusion = 'action_required') > 0 THEN 'action_required'
	WHEN SUM(conclusion = 'success') > 0 THEN 'success'
	WHEN SUM(conclusion = 'skipped') > 0 THEN 'skipped'
	ELSE MAX(conclusion) END`
}

var workflowRunSortCols = map[string]string{
	"queued_at":    "queued_at",
	"started_at":   "started_at",
	"completed_at": "completed_at",
	"repo":         "repo",
	"workflow":     "workflow",
	"run_number":   "run_number",
	"state":        "run_state",
	"jobs":         "total",
	"duration":     "(COALESCE(completed_at,0) - COALESCE(started_at,0))",
	"queue_wait":   "(COALESCE(started_at,0) - queued_at)",
}

// ListWorkflowRuns returns a filtered page of workflow runs and the matching
// total, newest first by default.
//
// The filter is a job filter, read two ways. Its status half -- states,
// conclusions, the failed and faulted switches, cancelling -- is applied to
// the run's own derived status, so a run is listed under the state it is in
// rather than under every state one of its jobs is in. Everything else names
// a job, and keeps a run whenever any job of it matches: a run in a
// repository, a run with a job on this pool, a run with a job still unmatched.
func (s *Store) ListWorkflowRuns(ctx context.Context, f JobFilter, p Page) ([]*WorkflowRun, int, error) {
	if runs, total, ok, err := s.listWorkflowRunsNewestFirst(ctx, f, p); err != nil || ok {
		return runs, total, err
	}
	from, args := workflowRunsFrom(f)
	var total int
	if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) `+from, args...).Scan(&total); err != nil {
		return nil, 0, err
	}
	q := `SELECT ` + workflowRunCols + ` ` + from +
		` ORDER BY ` + p.orderBy(workflowRunSortCols, "queued_at DESC") + `, repo ASC, github_run_id ASC LIMIT ? OFFSET ?`
	args = append(args, p.limit(50, 500), max(p.Offset, 0))
	return s.queryWorkflowRuns(ctx, q, args, total)
}

const workflowRunCols = `repo, github_run_id, workflow, run_number, run_attempt, head_branch, head_sha,
		installation_id, html_url, run_state, run_conclusion, queued_at, started_at, completed_at,
		total, waiting, queued, in_progress, completed, succeeded, failed, cancelled, skipped,
		faulted, unmatched, expedited, paused, removed, managed, hosted, cancelling`

func (s *Store) queryWorkflowRuns(ctx context.Context, q string, args []any, total int) ([]*WorkflowRun, int, error) {
	rows, err := s.read.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	var out []*WorkflowRun
	for rows.Next() {
		r, err := scanWorkflowRun(rows)
		if err != nil {
			return nil, 0, err
		}
		out = append(out, r)
	}
	return out, total, rows.Err()
}

// listWorkflowRunsNewestFirst answers the listing's default question -- the
// newest runs, with no condition on a run's own status -- without summing
// every job in the table to answer it. ok is false when the question is not
// that one, or the shortcut cannot prove its answer, and the caller does it
// the long way.
//
// The long way windows and aggregates every job row before it can sort, so its
// cost is the whole retained history however small the page: nineteen seconds
// at four hundred thousand jobs. This takes the runs that have a job among the
// newest few thousand, sums only those, and keeps the answer only when it can
// show that no other run could have ranked above it.
//
// The proof is the one line that makes it exact rather than approximate. A
// run's queued_at is the earliest of its latest-attempt jobs. Let M be the
// queued_at of the newest-but-Jth job in the table. Every run with a job at or
// after M is a candidate and is summed in full; every other run has all of its
// jobs, of every attempt, before M, so its own queued_at is before M too. If
// the page's last row is at or after M, nothing outside the candidates can
// outrank it, and the page is the page the long way would have returned. If it
// is not, J grows fourfold; and if it will not settle, the long way runs.
func (s *Store) listWorkflowRunsNewestFirst(ctx context.Context, f JobFilter, p Page) ([]*WorkflowRun, int, bool, error) {
	// Only the default order, and only a filter that says nothing about a run's
	// status: those are applied to the sums, which is what this avoids.
	if _, known := workflowRunSortCols[p.Sort]; known && !(p.Sort == "queued_at" && p.Desc) {
		return nil, 0, false, nil
	}
	if len(f.States) > 0 || len(f.Conclusions) > 0 || f.FailedOnly || f.FaultedOnly ||
		f.WorkflowFailedOnly || f.Cancelling != nil {
		return nil, 0, false, nil
	}
	limit, offset := p.limit(50, 500), max(p.Offset, 0)
	need := offset + limit

	where, whereArgs := jobWhere(f)
	var total int
	if err := s.read.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM (SELECT 1 FROM jobs `+where+` GROUP BY repo, github_run_id)`, whereArgs...).Scan(&total); err != nil {
		return nil, 0, false, err
	}
	if total <= need {
		// Everything is on this page, so there is nothing to rank against.
		return nil, 0, false, nil
	}

	for newest := max(need*20, 1000); newest <= 200_000; newest *= 4 {
		var bound int64
		err := s.read.QueryRowContext(ctx,
			`SELECT queued_at FROM jobs ORDER BY queued_at DESC, id ASC LIMIT 1 OFFSET ?`, newest-1).Scan(&bound)
		if errors.Is(err, sql.ErrNoRows) {
			// Fewer jobs than that: the whole table is cheap to sum.
			return nil, 0, false, nil
		}
		if err != nil {
			return nil, 0, false, err
		}
		restrict := ` WHERE (repo, github_run_id) IN (SELECT repo, github_run_id FROM jobs WHERE queued_at >= ?)`
		from, args := workflowRunsFromRestricted(f, restrict, []any{bound})
		q := `SELECT ` + workflowRunCols + ` ` + from +
			` ORDER BY queued_at DESC, repo ASC, github_run_id ASC LIMIT ?`
		runs, _, err := s.queryWorkflowRuns(ctx, q, append(args, need), total)
		if err != nil {
			return nil, 0, false, err
		}
		if len(runs) < need || ms(runs[need-1].QueuedAt) < bound {
			continue
		}
		return runs[offset:need], total, true, nil
	}
	return nil, 0, false, nil
}

// workflowRunsFrom renders the FROM and WHERE of a run listing: the jobs
// reduced to the latest attempt of each, summed per run, and narrowed by the
// filter's two halves.
func workflowRunsFrom(f JobFilter) (string, []any) {
	return workflowRunsFromRestricted(f, "", nil)
}

// workflowRunsFromRestricted is workflowRunsFrom over only the jobs a WHERE
// clause on the jobs table keeps, applied before the window is computed so that
// the window sees those rows and no others. restrictArgs are that clause's
// placeholders.
func workflowRunsFromRestricted(f JobFilter, restrict string, restrictArgs []any) (string, []any) {
	// The job half of the filter keeps a run whenever any of its jobs matches.
	// The status half is cleared here and applied to the run's own aggregates
	// below, since a job's state says nothing about its run's.
	jobs := f
	jobs.States, jobs.Conclusions = nil, nil
	jobs.FailedOnly, jobs.FaultedOnly, jobs.WorkflowFailedOnly = false, false, false
	jobs.Cancelling = nil
	where, args := jobWhere(jobs)
	inner := `WHERE run_attempt = latest_attempt`
	if where != "" {
		inner += ` AND (repo, github_run_id) IN (SELECT repo, github_run_id FROM jobs ` + where + `)`
	}

	var cond []string
	if len(f.States) > 0 {
		ph := make([]string, len(f.States))
		for i, st := range f.States {
			ph[i] = "?"
			args = append(args, string(st))
		}
		cond = append(cond, `run_state IN (`+strings.Join(ph, ",")+`)`)
	}
	if len(f.Conclusions) > 0 {
		ph := make([]string, len(f.Conclusions))
		for i, c := range f.Conclusions {
			ph[i] = "?"
			args = append(args, c)
		}
		cond = append(cond, `run_conclusion IN (`+strings.Join(ph, ",")+`)`)
	}
	switch {
	case f.FaultedOnly:
		cond = append(cond, `faulted > 0`)
	case f.WorkflowFailedOnly:
		cond = append(cond, `workflow_failed > 0`)
	case f.FailedOnly:
		cond = append(cond, `failed > 0`)
	}
	if f.Cancelling != nil {
		if *f.Cancelling {
			cond = append(cond, `cancelling > 0`)
		} else {
			cond = append(cond, `cancelling = 0`)
		}
	}
	outer := ""
	if len(cond) > 0 {
		outer = ` WHERE ` + strings.Join(cond, " AND ")
	}

	// The window finds, for each job name within a run, the newest attempt
	// any job of that name reported, and a job is kept when it belongs to
	// that attempt: re-running the failed jobs writes new rows under the same
	// names, and those are the rows GitHub's run page shows. It is the
	// attempt that is compared rather than a rank, because two jobs of one
	// attempt may share a display name -- GitHub does not require job names
	// to be unique -- and ranking them would keep one and lose the other.
	// hosted and managed are worked out per job here, where the label
	// predicates can see the row, and only summed up below.
	from := `FROM (
	SELECT repo, github_run_id, MAX(workflow) AS workflow, MAX(run_number) AS run_number,
		MAX(run_attempt) AS run_attempt, MAX(head_branch) AS head_branch, MAX(head_sha) AS head_sha,
		MAX(installation_id) AS installation_id, MAX(html_url) AS html_url,
		MIN(queued_at) AS queued_at, MIN(started_at) AS started_at,
		CASE WHEN SUM(state != 'completed') = 0 THEN MAX(completed_at) END AS completed_at,
		COUNT(*) AS total,
		SUM(state = 'waiting') AS waiting, SUM(state = 'queued') AS queued,
		SUM(state = 'in_progress') AS in_progress, SUM(state = 'completed') AS completed,
		SUM(conclusion = 'success' AND NOT ` + fleetFailedJobSQL() + `) AS succeeded,
		SUM(` + failedJobSQL() + `) AS failed,
		SUM(conclusion = 'cancelled' AND NOT ` + fleetFailedJobSQL() + `) AS cancelled,
		SUM(conclusion = 'skipped' AND NOT ` + fleetFailedJobSQL() + `) AS skipped,
		SUM(` + fleetFailedJobSQL() + `) AS faulted, SUM(` + workflowFailedJobSQL() + `) AS workflow_failed,
		SUM(matched = 0 AND state = 'queued' AND NOT hosted) AS unmatched,
		SUM(state = 'queued' AND provisioning = '' AND provision_now = 1) AS expedited,
		SUM(state = 'queued' AND provisioning = '` + ProvisioningPaused + `') AS paused,
		SUM(state = 'queued' AND provisioning = '` + ProvisioningDeleted + `') AS removed,
		MAX(managed) AS managed, MIN(hosted) AS hosted,
		SUM(cancel_requested_at IS NOT NULL AND state != 'completed') AS cancelling,
		` + runStateSQL + ` AS run_state, ` + runConclusionSQL() + ` AS run_conclusion
	FROM (
		SELECT jobs.*, ` + hostedJobSQL("jobs") + ` AS hosted, ` + managedJobSQL("jobs") + ` AS managed,
			MAX(run_attempt) OVER (PARTITION BY repo, github_run_id, job_name) AS latest_attempt
		FROM jobs` + restrict + `
	) AS jobs
	` + inner + `
	GROUP BY repo, github_run_id
) AS runs` + outer
	// The restriction's placeholders come first in the statement, inside the
	// subquery, ahead of the filter's.
	return from, append(append([]any{}, restrictArgs...), args...)
}

func scanWorkflowRun(sc interface{ Scan(...any) error }) (*WorkflowRun, error) {
	var r WorkflowRun
	var queued int64
	var started, completed sql.NullInt64
	var managed, hosted, cancelling int
	err := sc.Scan(&r.Repo, &r.GitHubRunID, &r.Workflow, &r.RunNumber, &r.RunAttempt, &r.HeadBranch,
		&r.HeadSHA, &r.InstallationID, &r.HTMLURL, &r.State, &r.Conclusion, &queued, &started, &completed,
		&r.Jobs.Total, &r.Jobs.Waiting, &r.Jobs.Queued, &r.Jobs.InProgress, &r.Jobs.Completed,
		&r.Jobs.Succeeded, &r.Jobs.Failed, &r.Jobs.Cancelled, &r.Jobs.Skipped, &r.Jobs.Faulted,
		&r.Jobs.Unmatched, &r.Jobs.Expedited, &r.Jobs.Paused, &r.Jobs.Removed, &managed, &hosted, &cancelling)
	if err != nil {
		return nil, err
	}
	r.QueuedAt = at(queued)
	r.StartedAt, r.CompletedAt = atp(started), atp(completed)
	r.Managed, r.Hosted, r.Cancelling = managed == 1, hosted == 1, cancelling > 0
	r.HTMLURL = runURL(r.HTMLURL)
	return &r, nil
}

// runURL is the run's page on GitHub, given a job's. A job's URL is the run's
// with "/job/<id>" on the end, so the run's is what comes before that; a URL
// that already names the run is left as it is.
func runURL(jobURL string) string {
	if i := strings.Index(jobURL, "/job/"); i >= 0 {
		return jobURL[:i]
	}
	return jobURL
}

package store

import (
	"context"
	"fmt"
	"math/rand"
	"testing"
	"time"
)

// seedRuns writes three runs' worth of jobs: one that failed and was re-run
// to success, one still going, and one in another repository that somebody
// else's runners ran.
func seedRuns(t *testing.T, s *Store, now time.Time) {
	t.Helper()
	ctx := context.Background()
	at := func(d time.Duration) *time.Time {
		v := now.Add(d)
		return &v
	}
	seed := []*Job{
		// Run 1: build passed; test failed, was re-run, and passed.
		{GitHubJobID: 11, GitHubRunID: 1, Repo: "acme/widgets", Workflow: "CI", JobName: "build", RunNumber: 300, RunAttempt: 1, HeadBranch: "main",
			HTMLURL: "https://github.com/acme/widgets/actions/runs/1/job/11", Labels: StringSlice{"self-hosted"}, Matched: true, PoolID: "pool_a",
			State: JobCompleted, Conclusion: "success", QueuedAt: now, StartedAt: at(10 * time.Second), CompletedAt: at(time.Minute)},
		{GitHubJobID: 12, GitHubRunID: 1, Repo: "acme/widgets", Workflow: "CI", JobName: "test", RunNumber: 300, RunAttempt: 1, HeadBranch: "main",
			HTMLURL: "https://github.com/acme/widgets/actions/runs/1/job/12", Labels: StringSlice{"self-hosted"}, Matched: true, PoolID: "pool_a",
			State: JobCompleted, Conclusion: "failure", QueuedAt: now, StartedAt: at(20 * time.Second), CompletedAt: at(2 * time.Minute)},
		{GitHubJobID: 13, GitHubRunID: 1, Repo: "acme/widgets", Workflow: "CI", JobName: "test", RunNumber: 300, RunAttempt: 2, HeadBranch: "main",
			HTMLURL: "https://github.com/acme/widgets/actions/runs/1/job/13", Labels: StringSlice{"self-hosted"}, Matched: true, PoolID: "pool_a",
			State: JobCompleted, Conclusion: "success", QueuedAt: now.Add(5 * time.Minute), StartedAt: at(5*time.Minute + 10*time.Second), CompletedAt: at(7 * time.Minute)},
		// Run 2: one job running, the other still queued, on a second pool.
		{GitHubJobID: 21, GitHubRunID: 2, Repo: "acme/widgets", Workflow: "CI", JobName: "build", RunAttempt: 1, HeadBranch: "feature/x",
			Labels: StringSlice{"self-hosted"}, Matched: true, PoolID: "pool_a",
			State: JobInProgress, QueuedAt: now.Add(time.Minute), StartedAt: at(time.Minute + 5*time.Second)},
		{GitHubJobID: 22, GitHubRunID: 2, Repo: "acme/widgets", Workflow: "CI", JobName: "test", RunAttempt: 1, HeadBranch: "feature/x",
			Labels: StringSlice{"self-hosted", "arm64"}, Matched: true, PoolID: "pool_b",
			State: JobQueued, QueuedAt: now.Add(time.Minute)},
		// Run 3: another repository, run on GitHub's own runners.
		{GitHubJobID: 31, GitHubRunID: 3, Repo: "acme/site", Workflow: "Pages", JobName: "deploy", RunAttempt: 1,
			Labels: StringSlice{"ubuntu-latest"}, HTMLURL: "https://github.com/acme/site/actions/runs/3/job/31",
			State: JobCompleted, Conclusion: "success", QueuedAt: now.Add(2 * time.Minute), StartedAt: at(2*time.Minute + 5*time.Second), CompletedAt: at(3 * time.Minute)},
	}
	for _, j := range seed {
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatalf("seeding job %d: %v", j.GitHubJobID, err)
		}
	}
}

// A run is what GitHub's Actions tab lists, so the Workflows page has to sum
// its jobs up the way GitHub's run page does: over the latest attempt of each
// job, and running while anything in it still is. Counting the superseded
// attempt would report a run that passed on its re-run as a failure.
func TestWorkflowRunsSumUpTheLatestAttemptOfEachJob(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	seedRuns(t, s, now)

	runs, total, err := s.ListWorkflowRuns(ctx, JobFilter{}, Page{Sort: "queued_at"})
	if err != nil {
		t.Fatalf("ListWorkflowRuns: %v", err)
	}
	if total != 3 || len(runs) != 3 {
		t.Fatalf("got %d runs (total %d), want 3", len(runs), total)
	}

	rerun := runs[0]
	if rerun.GitHubRunID != 1 || rerun.RunNumber != 300 || rerun.RunAttempt != 2 || rerun.Workflow != "CI" || rerun.HeadBranch != "main" {
		t.Fatalf("first run = %+v, want run 1 (#300) at attempt 2", rerun)
	}
	if rerun.State != JobCompleted || rerun.Conclusion != "success" {
		t.Fatalf("run 1 is %s/%q, want completed/success: the failed attempt was superseded", rerun.State, rerun.Conclusion)
	}
	if rerun.Jobs != (RunJobCounts{Total: 2, Completed: 2, Succeeded: 2}) {
		t.Fatalf("run 1 job counts = %+v, want two jobs both succeeded", rerun.Jobs)
	}
	if rerun.HTMLURL != "https://github.com/acme/widgets/actions/runs/1" {
		t.Fatalf("run 1 URL = %q, want the run's page rather than a job's", rerun.HTMLURL)
	}
	if !rerun.QueuedAt.Equal(now) || rerun.StartedAt == nil || !rerun.StartedAt.Equal(now.Add(10*time.Second)) {
		t.Fatalf("run 1 queued %v, started %v; want the first job's", rerun.QueuedAt, rerun.StartedAt)
	}
	if rerun.CompletedAt == nil || !rerun.CompletedAt.Equal(now.Add(7*time.Minute)) {
		t.Fatalf("run 1 completed %v, want the last job's", rerun.CompletedAt)
	}
	if !rerun.Managed || rerun.Hosted {
		t.Fatalf("run 1 managed=%v hosted=%v, want this fleet's own", rerun.Managed, rerun.Hosted)
	}

	going := runs[1]
	if going.GitHubRunID != 2 || going.State != JobInProgress || going.Conclusion != "" {
		t.Fatalf("run 2 = %s/%q, want in_progress with no conclusion", going.State, going.Conclusion)
	}
	if going.Jobs != (RunJobCounts{Total: 2, Queued: 1, InProgress: 1}) {
		t.Fatalf("run 2 job counts = %+v, want one running and one queued", going.Jobs)
	}
	if going.CompletedAt != nil {
		t.Fatalf("run 2 completed %v, want nothing while a job is still queued", going.CompletedAt)
	}
	if going.QueueWait() != 5*time.Second || going.Duration() != 0 {
		t.Fatalf("run 2 waited %v and took %v, want 5s and nothing yet", going.QueueWait(), going.Duration())
	}

	theirs := runs[2]
	if theirs.Repo != "acme/site" || theirs.Managed || !theirs.Hosted {
		t.Fatalf("run 3 = %+v, want acme/site on somebody else's runners", theirs)
	}
}

// The status half of the filter is the run's own: a run with a queued job
// beside a running one is running, not queued, and a run whose only failure
// was re-run to success has not failed. Everything else keeps a run when any
// job of it matches, so the run stays whole on the page.
func TestWorkflowRunsAreFilteredByTheirOwnStatusAndByAnyJob(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	seedRuns(t, s, now)
	// Run 4: the runner died under its only job, which GitHub still believes
	// is running.
	started := now.Add(3 * time.Minute)
	lost, err := s.UpsertJob(ctx, &Job{GitHubJobID: 41, GitHubRunID: 4, Repo: "acme/widgets", Workflow: "Nightly", JobName: "soak",
		RunAttempt: 1, Labels: StringSlice{"self-hosted"}, Matched: true, PoolID: "pool_a", RunnerID: "run_x",
		State: JobInProgress, QueuedAt: now.Add(3 * time.Minute), StartedAt: &started})
	if err != nil {
		t.Fatalf("seeding run 4: %v", err)
	}
	if _, _, err := s.SetJobRunnerFault(ctx, lost.ID, "runner exited with code 137", FaultRunnerExited); err != nil {
		t.Fatalf("SetJobRunnerFault: %v", err)
	}

	ids := func(f JobFilter) []int64 {
		t.Helper()
		runs, _, err := s.ListWorkflowRuns(ctx, f, Page{Sort: "queued_at"})
		if err != nil {
			t.Fatalf("ListWorkflowRuns(%+v): %v", f, err)
		}
		out := make([]int64, 0, len(runs))
		for _, r := range runs {
			out = append(out, r.GitHubRunID)
		}
		return out
	}
	same := func(got, want []int64) bool {
		if len(got) != len(want) {
			return false
		}
		for i := range got {
			if got[i] != want[i] {
				return false
			}
		}
		return true
	}
	no := false
	for _, tc := range []struct {
		name   string
		filter JobFilter
		want   []int64
	}{
		{"running runs", JobFilter{States: []JobState{JobInProgress}}, []int64{2, 4}},
		{"queued runs: none, since run 2 is running", JobFilter{States: []JobState{JobQueued}}, nil},
		{"successful runs, the re-run included", JobFilter{Conclusions: []string{"success"}}, []int64{1, 3}},
		{"failed runs, on either side", JobFilter{FailedOnly: true}, []int64{4}},
		{"the fleet's own failures", JobFilter{FaultedOnly: true}, []int64{4}},
		{"the workflows' own failures", JobFilter{WorkflowFailedOnly: true}, nil},
		{"runs this fleet has a hand in", JobFilter{ManagedOnly: true}, []int64{1, 2, 4}},
		{"a repository", JobFilter{Repos: []string{"acme/site"}}, []int64{3}},
		{"a workflow", JobFilter{Workflows: []string{"Nightly"}}, []int64{4}},
		{"a job on a pool keeps its whole run", JobFilter{PoolIDs: []string{"pool_b"}}, []int64{2}},
		{"a search over job names", JobFilter{Search: "deploy"}, []int64{3}},
		{"work still in hand", JobFilter{States: []JobState{JobInProgress}, Cancelling: &no}, []int64{2, 4}},
	} {
		if got := ids(tc.filter); !same(got, tc.want) {
			t.Errorf("%s: runs %v, want %v", tc.name, got, tc.want)
		}
	}

	// The run a pool filter keeps arrives whole, not reduced to the job that
	// matched: an operator asked which runs touch the pool, not which jobs.
	runs, _, err := s.ListWorkflowRuns(ctx, JobFilter{PoolIDs: []string{"pool_b"}}, Page{})
	if err != nil {
		t.Fatalf("ListWorkflowRuns by pool: %v", err)
	}
	if len(runs) != 1 || runs[0].Jobs.Total != 2 {
		t.Fatalf("run by pool = %+v, want run 2 with both its jobs counted", runs)
	}

	// Paging counts runs, not jobs.
	page, total, err := s.ListWorkflowRuns(ctx, JobFilter{}, Page{Sort: "queued_at", Limit: 1, Offset: 1})
	if err != nil {
		t.Fatalf("ListWorkflowRuns page: %v", err)
	}
	if total != 4 || len(page) != 1 || page[0].GitHubRunID != 2 {
		t.Fatalf("page = %v runs of %d, want run 2 alone of 4", len(page), total)
	}
}

// Opening a run is a job listing narrowed to it, so the run's row and the
// jobs under it come from the same rows and cannot disagree.
func TestJobsCanBeListedByTheirRun(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	seedRuns(t, s, time.Now().UTC().Truncate(time.Millisecond))

	jobs, total, err := s.ListJobs(ctx, JobFilter{Repos: []string{"acme/widgets"}, RunIDs: []int64{1}}, Page{Sort: "queued_at", Desc: false})
	if err != nil {
		t.Fatalf("ListJobs by run: %v", err)
	}
	if total != 3 || len(jobs) != 3 {
		t.Fatalf("got %d jobs (total %d), want the three attempts of run 1", len(jobs), total)
	}
	for _, j := range jobs {
		if j.GitHubRunID != 1 {
			t.Fatalf("job %d belongs to run %d, want run 1 only", j.GitHubJobID, j.GitHubRunID)
		}
	}
}

// Every job of a run is counted once. GitHub does not require job names to be
// unique, so two jobs of one attempt may share a name and both still count;
// and a job whose runner stopped under it is the fleet's failure whatever
// conclusion GitHub recorded, so it is never a success as well.
func TestWorkflowRunsCountEachJobOnce(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	started, done := now.Add(time.Second), now.Add(time.Minute)
	seed := []*Job{
		{GitHubJobID: 51, JobName: "build", Conclusion: "success"},
		{GitHubJobID: 52, JobName: "build", Conclusion: "failure"},
		{GitHubJobID: 53, JobName: "deploy", Conclusion: "success"},
	}
	for _, j := range seed {
		j.GitHubRunID, j.RunAttempt, j.Repo, j.Workflow = 5, 1, "acme/widgets", "CI"
		j.State, j.QueuedAt, j.StartedAt, j.CompletedAt = JobCompleted, now, &started, &done
		j.Labels, j.Matched, j.PoolID = StringSlice{"self-hosted"}, true, "pool_a"
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatalf("seeding job %d: %v", j.GitHubJobID, err)
		}
	}
	deploy, err := s.GetJobByGitHubID(ctx, 53)
	if err != nil {
		t.Fatalf("GetJobByGitHubID: %v", err)
	}
	if _, _, err := s.SetJobRunnerFault(ctx, deploy.ID, "runner exited with code 137", FaultRunnerExited); err != nil {
		t.Fatalf("SetJobRunnerFault: %v", err)
	}

	runs, total, err := s.ListWorkflowRuns(ctx, JobFilter{}, Page{})
	if err != nil {
		t.Fatalf("ListWorkflowRuns: %v", err)
	}
	if total != 1 || len(runs) != 1 {
		t.Fatalf("got %d runs (total %d), want the one", len(runs), total)
	}
	run := runs[0]
	if run.Jobs != (RunJobCounts{Total: 3, Completed: 3, Succeeded: 1, Failed: 2, Faulted: 1}) {
		t.Fatalf("job counts = %+v, want three jobs: one succeeded, two failed of which one is the fleet's", run.Jobs)
	}
	if run.State != JobCompleted || run.Conclusion != "failure" {
		t.Fatalf("run = %s/%q, want completed as a failure", run.State, run.Conclusion)
	}
}

// A run row can offer Pause and Run now only if it knows what its queued
// jobs already carry: Pause pressed on a run whose every queued job is paused
// has to be refused with a reason, and a Run now on the run must not sweep
// back in a job an operator removed from the queue on purpose.
func TestWorkflowRunsCountWhatAnOperatorDidToTheirQueuedJobs(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Millisecond)
	seed := []*Job{
		{GitHubJobID: 61, JobName: "build"},
		{GitHubJobID: 62, JobName: "test"},
		{GitHubJobID: 63, JobName: "lint"},
		{GitHubJobID: 64, JobName: "package"},
	}
	for _, j := range seed {
		j.GitHubRunID, j.RunAttempt, j.Repo, j.Workflow = 6, 1, "acme/widgets", "CI"
		j.State, j.QueuedAt = JobQueued, now
		j.Labels, j.Matched, j.PoolID = StringSlice{"self-hosted"}, true, "pool_a"
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatalf("seeding job %d: %v", j.GitHubJobID, err)
		}
	}
	id := func(githubID int64) string {
		t.Helper()
		j, err := s.GetJobByGitHubID(ctx, githubID)
		if err != nil {
			t.Fatalf("GetJobByGitHubID(%d): %v", githubID, err)
		}
		return j.ID
	}
	for _, step := range []struct {
		action string
		job    int64
	}{{"run_now", 61}, {"pause", 62}, {"delete", 63}} {
		if _, err := s.ControlProvisioning(ctx, []string{id(step.job)}, step.action); err != nil {
			t.Fatalf("%s job %d: %v", step.action, step.job, err)
		}
	}

	runs, _, err := s.ListWorkflowRuns(ctx, JobFilter{}, Page{})
	if err != nil {
		t.Fatalf("ListWorkflowRuns: %v", err)
	}
	if len(runs) != 1 {
		t.Fatalf("got %d runs, want the one", len(runs))
	}
	got := runs[0].Jobs
	want := RunJobCounts{Total: 4, Queued: 4, Expedited: 1, Paused: 1, Removed: 1}
	if got != want {
		t.Fatalf("job counts = %+v, want %+v: the four queued jobs, one each expedited, paused and removed", got, want)
	}
	// The three the run's own controls reach: the removed one is restored
	// from the Queue page, not swept up with its siblings.
	if got.Controllable() != 3 {
		t.Fatalf("controllable = %d, want 3", got.Controllable())
	}

	// The run's provisioning selection is what a run-level action acts on,
	// and it leaves the removed job alone.
	ids, err := s.ProvisioningSelection(ctx, JobFilter{
		Repos: []string{"acme/widgets"}, RunIDs: []int64{6},
		Provisioning: []string{"ready", "expedited", ProvisioningPaused},
	})
	if err != nil {
		t.Fatalf("ProvisioningSelection: %v", err)
	}
	if len(ids) != 3 {
		t.Fatalf("selection = %v, want the three queued jobs not removed", ids)
	}
	for _, sel := range ids {
		if sel == id(63) {
			t.Fatalf("selection %v includes the removed job", ids)
		}
	}
}

// A run's jobs arrive as separate deliveries, often before the lookup of the
// run's number has come back, so the number is written to the whole run --
// and never over a number a job already has.
func TestARunsNumberIsRecordedOnEveryJobOfTheRun(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	for i, id := range []int64{8101, 8102} {
		if _, _, err := s.ApplyJob(ctx, &Job{GitHubJobID: id, GitHubRunID: 8100, Repo: "acme/widgets",
			JobName: fmt.Sprintf("job-%d", i), State: JobQueued}); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.SetRunNumberForRun(ctx, "acme/widgets", 8100, 42); err != nil {
		t.Fatal(err)
	}
	for _, id := range []int64{8101, 8102} {
		j, err := s.GetJobByGitHubID(ctx, id)
		if err != nil {
			t.Fatal(err)
		}
		if j.RunNumber != 42 {
			t.Errorf("job %d run number = %d, want 42", id, j.RunNumber)
		}
	}
}

// The shortcut that answers "the newest runs" without summing every job is only
// allowed to exist because it is exact. This builds the cases that would catch
// it being merely close: runs whose jobs were queued days apart because one was
// re-run, re-runs the filter does not keep, and a great many runs queued in the
// same second so that the order is decided by the tie-break.
func TestTheNewestRunsShortcutAnswersExactlyWhatSummingEveryJobWould(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()
	now := time.Date(2026, 6, 1, 12, 0, 0, 0, time.UTC)
	rng := rand.New(rand.NewSource(7))

	tx, err := s.write.BeginTx(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	insert, err := tx.PrepareContext(ctx, `INSERT INTO jobs (id, github_job_id, github_run_id, repo, workflow, job_name,
		labels, state, conclusion, pool_id, runner_id, queued_at, started_at, completed_at, matched, run_attempt, head_branch)
		VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
	if err != nil {
		t.Fatal(err)
	}
	jobID := 0
	add := func(run int, repo, job string, attempt int, queued time.Time, matched bool) {
		jobID++
		pool := ""
		if matched {
			pool = "pool_a"
		}
		state, conclusion := "completed", "success"
		var started, completed any = queued.Add(5 * time.Second).UnixMilli(), queued.Add(time.Minute).UnixMilli()
		if rng.Intn(10) == 0 {
			state, conclusion, started, completed = "queued", "", nil, nil
		}
		if _, err := insert.ExecContext(ctx, fmt.Sprintf("job_%06d", jobID), 1_000_000+jobID, run, repo, "CI", job,
			`["self-hosted"]`, state, conclusion, pool, "", queued.UnixMilli(), started, completed, matched, attempt, "main"); err != nil {
			t.Fatal(err)
		}
	}
	for run := 1; run <= 1200; run++ {
		repo := fmt.Sprintf("acme/r%d", run%4)
		// Coarse minutes, so that dozens of runs share a queue time.
		queued := now.Add(-time.Duration(rng.Intn(600)) * time.Minute)
		matched := rng.Intn(5) != 0
		for _, job := range []string{"build", "test", "lint"} {
			add(run, repo, job, 1, queued, matched)
		}
		switch r := rng.Intn(10); {
		case r < 8:
			// One job re-run days later, so the run's newest job is far newer
			// than its own queued_at.
			add(run, repo, "test", 2, queued.Add(72*time.Hour), matched)
		case r == 8 && rng.Intn(8) == 0:
			// Every job re-run days later, and the re-run is not one this
			// fleet had a hand in: the old attempt is what the filter keeps.
			// The single re-runs are common enough that the newest thousand jobs
			// in the table are all re-runs, so the shortcut's first guess is
			// wrong and the proof is what has to catch it.
			for _, job := range []string{"build", "test", "lint"} {
				add(run, repo, job, 2, queued.Add(96*time.Hour), false)
			}
		}
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}

	slow := func(f JobFilter, p Page) ([]*WorkflowRun, int) {
		from, args := workflowRunsFrom(f)
		var total int
		if err := s.read.QueryRowContext(ctx, `SELECT COUNT(*) `+from, args...).Scan(&total); err != nil {
			t.Fatal(err)
		}
		q := `SELECT ` + workflowRunCols + ` ` + from + ` ORDER BY ` + p.orderBy(workflowRunSortCols, "queued_at DESC") +
			`, repo ASC, github_run_id ASC LIMIT ? OFFSET ?`
		runs, _, err := s.queryWorkflowRuns(ctx, q, append(args, p.limit(50, 500), max(p.Offset, 0)), total)
		if err != nil {
			t.Fatal(err)
		}
		return runs, total
	}

	shortcuts := 0
	for name, f := range map[string]JobFilter{
		"no filter":      {},
		"one repository": {Repos: []string{"acme/r1"}},
		"this fleet's":   {ManagedOnly: true},
		"a pool":         {PoolIDs: []string{"pool_a"}},
	} {
		for _, p := range []Page{{Limit: 50}, {Limit: 25, Offset: 100}, {Limit: 500}, {Limit: 10, Offset: 900, Sort: "queued_at", Desc: true}} {
			want, wantTotal := slow(f, p)
			got, gotTotal, ok, err := s.listWorkflowRunsNewestFirst(ctx, f, p)
			if err != nil {
				t.Fatalf("%s %+v: %v", name, p, err)
			}
			if !ok {
				continue
			}
			shortcuts++
			if gotTotal != wantTotal || len(got) != len(want) {
				t.Fatalf("%s %+v: shortcut says %d of %d, the long way says %d of %d", name, p, len(got), gotTotal, len(want), wantTotal)
			}
			for i := range want {
				if fmt.Sprintf("%+v", *got[i]) != fmt.Sprintf("%+v", *want[i]) {
					t.Fatalf("%s %+v: row %d differs\nshortcut: %+v\nlong way: %+v", name, p, i, *got[i], *want[i])
				}
			}
		}
	}
	if shortcuts < 6 {
		t.Fatalf("the shortcut answered only %d of the 16 questions; the test is not exercising it", shortcuts)
	}

	// And it stands aside for anything it cannot prove.
	for name, tc := range map[string]struct {
		f JobFilter
		p Page
	}{
		"a status filter":  {JobFilter{States: []JobState{JobQueued}}, Page{Limit: 50}},
		"another sort":     {JobFilter{}, Page{Limit: 50, Sort: "repo", Desc: true}},
		"oldest first":     {JobFilter{}, Page{Limit: 50, Sort: "queued_at"}},
		"everything shown": {JobFilter{}, Page{Limit: 500, Offset: 1000}},
	} {
		if _, _, ok, err := s.listWorkflowRunsNewestFirst(ctx, tc.f, tc.p); err != nil || ok {
			t.Errorf("%s was answered by the shortcut (ok=%v, err=%v)", name, ok, err)
		}
	}
}

package store

import (
	"context"
	"database/sql"
	"os"
	"regexp"
	"sync"
	"testing"
	"time"
)

// The writer's queue is what a busy instance runs out of first, so what the
// observer is told has to be what happened: one report per write, the wait a
// write spent behind another, and the hold of the write that kept it waiting.
func TestTheObserverIsToldHowLongEachWriteWaitedAndHeld(t *testing.T) {
	s := newTestStore(t)
	ctx := context.Background()

	var mu sync.Mutex
	var waits, holds []time.Duration
	s.ObserveWrites(func(waited, held time.Duration) {
		mu.Lock()
		defer mu.Unlock()
		waits, holds = append(waits, waited), append(holds, held)
	})

	// A transaction that holds the writer, and a write that arrives while it
	// does. The margins are generous on purpose: this is about the shape of
	// what is reported, not the scheduler's punctuality.
	const hold = 150 * time.Millisecond
	inside := make(chan struct{})
	done := make(chan error, 1)
	go func() {
		done <- s.tx(ctx, func(*sql.Tx) error {
			close(inside)
			time.Sleep(hold)
			return nil
		})
	}()
	<-inside
	if _, err := s.exec(ctx, `SELECT 1`); err != nil {
		t.Fatalf("exec: %v", err)
	}
	if err := <-done; err != nil {
		t.Fatalf("tx: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	if len(waits) != 2 {
		t.Fatalf("the observer heard about %d writes, want 2: every write is reported, once", len(waits))
	}
	// Not by position: the observer runs after the writer is released, so the
	// write that waited can finish and report before the transaction that held
	// it up gets round to reporting. The longest hold is the transaction's and
	// the longest wait is the other write's, whichever order they arrived in.
	if longest := max(holds[0], holds[1]); longest < hold*2/3 {
		t.Errorf("the longest hold reported is %v, want about %v: a hold reported short hides the write that caused the queue", longest, hold)
	}
	if longest := max(waits[0], waits[1]); longest < hold/3 {
		t.Errorf("the longest wait reported is %v, want a good part of %v: the wait is the figure that says the writer is saturated", longest, hold)
	}
}

// Nothing observing is the state every CLI command and test runs in, and a
// write must not care.
func TestAWriteNeedsNoObserver(t *testing.T) {
	s := newTestStore(t)
	s.ObserveWrites(nil)
	if _, err := s.exec(context.Background(), `SELECT 1`); err != nil {
		t.Fatalf("exec with no observer: %v", err)
	}
}

// lockWriter is the one place the writer is taken, because a lock taken
// anywhere else is a write the measurement cannot see -- and a backup, which
// holds the writer for a whole VACUUM INTO, is exactly the write most worth
// seeing.
func TestTheWriterIsOnlyEverTakenThroughLockWriter(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	direct := regexp.MustCompile(`\bwmu\.Lock\(\)`)
	found := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !regexp.MustCompile(`\.go$`).MatchString(name) || regexp.MustCompile(`_test\.go$`).MatchString(name) {
			continue
		}
		b, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		found += len(direct.FindAll(b, -1))
	}
	if found != 1 {
		t.Errorf("wmu.Lock() appears %d times in the store; want once, inside lockWriter, so every write is measured", found)
	}
}

// Package toolscan reads GitHub Actions workflows for the toolchains their jobs
// install, so a fleet can have them in place before the jobs arrive.
//
// Every setup-python, setup-node, setup-go, setup-java and setup-dotnet step
// downloads what it is asked for unless the runner's tool cache already holds
// it, and on an ephemeral runner the tool cache starts empty every time. What
// a pool's jobs ask for is written down in their workflows, so it can be read
// ahead of time rather than discovered one download at a time.
//
// It is pure: it takes a file and returns what the file asks for. Fetching the
// files and deciding which pool would run each job are the controller's.
//
// Only what can be known from the file is reported as known. A version that
// comes from an expression, or from a file in the repository such as
// .python-version or go.mod, is reported with the reason it is not resolved
// rather than guessed at or dropped: an operator reading the result has to be
// able to tell "nothing asks for Python" from "something does, and it says
// which in a file this did not read".
package toolscan

import (
	"fmt"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// Tool is a toolchain a setup action installs.
type Tool string

// The toolchains this package recognises, by the action that installs each.
const (
	Python Tool = "python"
	Node   Tool = "node"
	Go     Tool = "go"
	Java   Tool = "java"
	DotNet Tool = "dotnet"
)

// setupAction describes one setup action: the inputs that name versions
// directly, and the ones that name a file the versions are read from.
type setupAction struct {
	tool         Tool
	versionInput string
	fileInputs   []string
}

// setupActions is keyed by the action's owner/name in lower case, which is how
// GitHub resolves `uses:` -- case-insensitively.
var setupActions = map[string]setupAction{
	"actions/setup-python": {Python, "python-version", []string{"python-version-file"}},
	"actions/setup-node":   {Node, "node-version", []string{"node-version-file"}},
	"actions/setup-go":     {Go, "go-version", []string{"go-version-file"}},
	"actions/setup-java":   {Java, "java-version", []string{"java-version-file"}},
	"actions/setup-dotnet": {DotNet, "dotnet-version", []string{"global-json-file"}},
}

// maxCombinations bounds how far a matrix is expanded. GitHub itself refuses a
// matrix of more than 256 jobs, so a file that asks for more is not one that
// runs.
const maxCombinations = 256

// Requirement is one toolchain version one job asks for.
type Requirement struct {
	// Workflow is the file's path in its repository, and Job the job's key in
	// it.
	Workflow string `json:"workflow"`
	Job      string `json:"job"`
	// Labels are the job's runs-on labels. Nil means they are not known from
	// the file -- an expression this package could not resolve -- which is
	// different from a job with no labels at all.
	Labels []string `json:"labels"`
	Tool   Tool     `json:"tool"`
	// Version is the version or range as the workflow writes it, after any
	// matrix value has been substituted: "3.12", "22.x", "lts/*". Empty when
	// Unresolved is set.
	Version string `json:"version,omitempty"`
	// Distribution is setup-java's distribution input, which decides which
	// JDK a version means. Empty for every other tool.
	Distribution string `json:"distribution,omitempty"`
	// Unresolved says why the version could not be read from the file.
	Unresolved string `json:"unresolved,omitempty"`
}

// workflow is the part of a workflow file this package reads. Everything is a
// yaml.Node so that values keep the text they were written as: to a YAML
// decoder `python-version: 3.10` is the float 3.1, and GitHub passes the text
// "3.10" to the action.
type workflow struct {
	Jobs map[string]struct {
		RunsOn   yaml.Node `yaml:"runs-on"`
		Strategy struct {
			Matrix yaml.Node `yaml:"matrix"`
		} `yaml:"strategy"`
		Steps []struct {
			Uses string               `yaml:"uses"`
			With map[string]yaml.Node `yaml:"with"`
		} `yaml:"steps"`
	} `yaml:"jobs"`
}

// Scan returns every toolchain requirement in one workflow file, in a stable
// order. A file that is not valid YAML is an error; a job this package cannot
// fully read is not -- what it can read is returned, and what it cannot is
// marked Unresolved.
func Scan(path, content string) ([]Requirement, error) {
	var wf workflow
	if err := yaml.Unmarshal([]byte(content), &wf); err != nil {
		return nil, fmt.Errorf("toolscan: %s is not valid YAML: %w", path, err)
	}
	jobs := make([]string, 0, len(wf.Jobs))
	for name := range wf.Jobs {
		jobs = append(jobs, name)
	}
	sort.Strings(jobs)

	var out []Requirement
	seen := map[string]bool{}
	for _, name := range jobs {
		job := wf.Jobs[name]
		combos, matrixNote := expandMatrix(&job.Strategy.Matrix)
		for _, combo := range combos {
			labels := runsOn(&job.RunsOn, combo)
			for _, step := range job.Steps {
				action, ok := setupActions[actionName(step.Uses)]
				if !ok {
					continue
				}
				for _, r := range stepRequirements(action, step.With, combo) {
					r.Workflow, r.Job, r.Labels = path, name, labels
					// A matrix this package could not read explains a
					// missing matrix value better than the value does.
					if matrixNote != "" && strings.HasPrefix(r.Unresolved, "set by matrix.") {
						r.Unresolved = matrixNote
					}
					key := fmt.Sprintf("%s\x00%q\x00%s\x00%s\x00%s\x00%s", r.Job, r.Labels, r.Tool, r.Version, r.Distribution, r.Unresolved)
					if seen[key] {
						continue
					}
					seen[key] = true
					out = append(out, r)
				}
			}
		}
	}
	return out, nil
}

// actionName turns `actions/setup-python@v6` into "actions/setup-python". A
// local action (./path) or a Docker one (docker://) is not a setup action.
func actionName(uses string) string {
	name, _, _ := strings.Cut(strings.TrimSpace(uses), "@")
	return strings.ToLower(name)
}

// stepRequirements reads the versions one setup step asks for.
func stepRequirements(action setupAction, with map[string]yaml.Node, combo map[string]string) []Requirement {
	distribution := ""
	if action.tool == Java {
		if n, ok := with["distribution"]; ok {
			d, unresolved := substitute(n.Value, combo)
			if unresolved == "" {
				distribution = d
			}
		}
	}

	n, ok := with[action.versionInput]
	if !ok || strings.TrimSpace(nodeText(&n)) == "" {
		for _, in := range action.fileInputs {
			if f, ok := with[in]; ok && strings.TrimSpace(f.Value) != "" {
				return []Requirement{{Tool: action.tool, Distribution: distribution,
					Unresolved: fmt.Sprintf("read from %s in the repository", strings.TrimSpace(f.Value))}}
			}
		}
		// No version at all: setup-go and setup-dotnet then read go.mod or
		// global.json on their own, and the others use whatever is on PATH.
		return []Requirement{{Tool: action.tool, Distribution: distribution,
			Unresolved: "no version given; the action falls back to the repository or the runner"}}
	}

	var out []Requirement
	for _, v := range versions(&n) {
		value, unresolved := substitute(v, combo)
		if unresolved != "" {
			out = append(out, Requirement{Tool: action.tool, Distribution: distribution, Unresolved: unresolved})
			continue
		}
		out = append(out, Requirement{Tool: action.tool, Version: value, Distribution: distribution})
	}
	return out
}

// versions splits a version input into the versions it names. setup-python,
// setup-java and setup-dotnet all take several, one per line, and YAML also
// lets a workflow write them as a sequence.
func versions(n *yaml.Node) []string {
	var raw []string
	if n.Kind == yaml.SequenceNode {
		for _, c := range n.Content {
			raw = append(raw, c.Value)
		}
	} else {
		raw = strings.Split(n.Value, "\n")
	}
	var out []string
	for _, v := range raw {
		if v = strings.TrimSpace(v); v != "" {
			out = append(out, v)
		}
	}
	return out
}

// nodeText is a node's text whichever kind it is, for "is anything written
// here".
func nodeText(n *yaml.Node) string {
	if n.Kind == yaml.SequenceNode {
		return strings.Join(versions(n), "\n")
	}
	return n.Value
}

// substitute replaces ${{ matrix.<key> }} with the combination's value. Any
// other expression -- an input, an env var, a step's output -- is not
// knowable from the file, and is reported as the reason.
func substitute(s string, combo map[string]string) (string, string) {
	var b strings.Builder
	rest := s
	for {
		i := strings.Index(rest, "${{")
		if i < 0 {
			b.WriteString(rest)
			return strings.TrimSpace(b.String()), ""
		}
		j := strings.Index(rest[i:], "}}")
		if j < 0 {
			return "", fmt.Sprintf("the expression in %q is not closed", s)
		}
		expr := strings.TrimSpace(rest[i+3 : i+j])
		key, ok := strings.CutPrefix(expr, "matrix.")
		if !ok {
			return "", fmt.Sprintf("set by the expression ${{ %s }}", expr)
		}
		v, ok := combo[key]
		if !ok {
			return "", fmt.Sprintf("set by matrix.%s, which the matrix does not list as a value", key)
		}
		b.WriteString(rest[:i])
		b.WriteString(v)
		rest = rest[i+j+2:]
	}
}

// runsOn reads a job's labels, or nil when they are not knowable.
//
// runs-on is a label, a list of labels, or a mapping with a group and labels;
// a runner group is not a label and does not narrow which pool matches here,
// so only the labels are kept.
func runsOn(n *yaml.Node, combo map[string]string) []string {
	var raw []string
	switch n.Kind {
	case yaml.ScalarNode:
		raw = []string{n.Value}
	case yaml.SequenceNode:
		for _, c := range n.Content {
			raw = append(raw, c.Value)
		}
	case yaml.MappingNode:
		for i := 0; i+1 < len(n.Content); i += 2 {
			if n.Content[i].Value != "labels" {
				continue
			}
			v := n.Content[i+1]
			if v.Kind == yaml.SequenceNode {
				for _, c := range v.Content {
					raw = append(raw, c.Value)
				}
			} else {
				raw = append(raw, v.Value)
			}
		}
	default:
		return nil
	}
	labels := []string{}
	for _, l := range raw {
		v, unresolved := substitute(l, combo)
		if unresolved != "" {
			return nil
		}
		// `runs-on: ${{ matrix.os }}` whose value is itself a list arrives
		// here as one comma-free value per combination, so no splitting is
		// needed; a label is never empty.
		if v != "" {
			labels = append(labels, v)
		}
	}
	return labels
}

// expandMatrix returns the matrix's combinations, as key to value, and a note
// when the matrix could not be read in full. A job with no matrix has one
// combination, the empty one.
//
// Only scalar values are substituted. A matrix value that is itself a mapping
// or a list (`include: [{os: ..., versions: [...]}]`) is left out of the
// combination, so a step that uses it is reported as unresolved rather than
// given a wrong answer.
func expandMatrix(m *yaml.Node) ([]map[string]string, string) {
	if m.Kind == 0 {
		return []map[string]string{{}}, ""
	}
	if m.Kind != yaml.MappingNode {
		// `matrix: ${{ fromJSON(...) }}` is built at run time.
		return []map[string]string{{}}, "set by a matrix built at run time"
	}
	var axes []axis
	var include, exclude []map[string]string
	for i := 0; i+1 < len(m.Content); i += 2 {
		key, val := m.Content[i].Value, m.Content[i+1]
		switch key {
		case "include":
			include = mappings(val)
		case "exclude":
			exclude = mappings(val)
		default:
			if val.Kind != yaml.SequenceNode {
				continue
			}
			var vs []string
			for _, c := range val.Content {
				if c.Kind == yaml.ScalarNode {
					vs = append(vs, c.Value)
				}
			}
			if len(vs) > 0 {
				axes = append(axes, axis{key, vs})
			}
		}
	}

	combos := []map[string]string{{}}
	for _, a := range axes {
		var next []map[string]string
		for _, c := range combos {
			for _, v := range a.values {
				n := make(map[string]string, len(c)+1)
				for k, x := range c {
					n[k] = x
				}
				n[a.key] = v
				next = append(next, n)
				if len(next) > maxCombinations {
					return combos, "set by a matrix larger than GitHub runs"
				}
			}
		}
		combos = next
	}

	kept := combos[:0]
	for _, c := range combos {
		if !matchesAny(c, exclude) {
			kept = append(kept, c)
		}
	}
	combos = kept

	// With no axes, every include entry is a job of its own: that is what
	// makes `include` alone a list of jobs.
	if len(axes) == 0 {
		if len(include) == 0 {
			return []map[string]string{{}}, ""
		}
		return include, ""
	}

	// Otherwise an include entry extends every combination whose axis values
	// it agrees with, and one that agrees with none is a combination of its
	// own. That is GitHub's rule.
	for _, inc := range include {
		extended := false
		for _, c := range combos {
			if agrees(c, inc, axes) {
				// Never an axis value: GitHub does not let an include
				// overwrite one of the matrix's own.
				for k, v := range inc {
					if !isAxisKey(k, axes) {
						c[k] = v
					}
				}
				extended = true
			}
		}
		if !extended {
			n := make(map[string]string, len(inc))
			for k, v := range inc {
				n[k] = v
			}
			combos = append(combos, n)
		}
	}
	if len(combos) == 0 {
		return []map[string]string{{}}, ""
	}
	return combos, ""
}

// axis is one of a matrix's own keys and the values it takes.
type axis struct {
	key    string
	values []string
}

// mappings reads an include or exclude list, keeping scalar values only.
func mappings(n *yaml.Node) []map[string]string {
	if n.Kind != yaml.SequenceNode {
		return nil
	}
	var out []map[string]string
	for _, item := range n.Content {
		if item.Kind != yaml.MappingNode {
			continue
		}
		m := map[string]string{}
		for i := 0; i+1 < len(item.Content); i += 2 {
			if item.Content[i+1].Kind == yaml.ScalarNode {
				m[item.Content[i].Value] = item.Content[i+1].Value
			}
		}
		out = append(out, m)
	}
	return out
}

func matchesAny(c map[string]string, patterns []map[string]string) bool {
	for _, p := range patterns {
		match := true
		for k, v := range p {
			if c[k] != v {
				match = false
				break
			}
		}
		if match && len(p) > 0 {
			return true
		}
	}
	return false
}

// agrees reports whether an include entry's values for the matrix's own axes
// match a combination; keys that are not axes do not have to.
func agrees(c, inc map[string]string, axes []axis) bool {
	for k, v := range inc {
		if isAxisKey(k, axes) && c[k] != v {
			return false
		}
	}
	return true
}

func isAxisKey(k string, axes []axis) bool {
	for _, a := range axes {
		if a.key == k {
			return true
		}
	}
	return false
}

package toolscan

import (
	"reflect"
	"testing"
)

// scan is Scan for a test: a file that does not parse is the test's mistake.
func scan(t *testing.T, content string) []Requirement {
	t.Helper()
	got, err := Scan(".github/workflows/ci.yml", content)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	return got
}

// brief is what most tests compare: the job, its labels, the tool and the
// version, one string per requirement.
func brief(rs []Requirement) []string {
	var out []string
	for _, r := range rs {
		s := r.Job + " " + string(r.Tool) + " "
		if r.Unresolved != "" {
			s += "? " + r.Unresolved
		} else {
			s += r.Version
		}
		if r.Distribution != "" {
			s += " (" + r.Distribution + ")"
		}
		out = append(out, s)
	}
	return out
}

func TestScanReadsEverySetupAction(t *testing.T) {
	got := scan(t, `
jobs:
  build:
    runs-on: [self-hosted, linux]
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-python@v6
        with:
          python-version: "3.12"
      - uses: actions/setup-node@v5
        with:
          node-version: 22.x
      - uses: actions/setup-go@v6
        with:
          go-version: "1.27"
      - uses: actions/setup-java@v5
        with:
          distribution: temurin
          java-version: 21
      - uses: actions/setup-dotnet@v5
        with:
          dotnet-version: 8.0.x
`)
	want := []string{
		"build python 3.12",
		"build node 22.x",
		"build go 1.27",
		"build java 21 (temurin)",
		"build dotnet 8.0.x",
	}
	if !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q\nwant %q", brief(got), want)
	}
	for _, r := range got {
		if !reflect.DeepEqual(r.Labels, []string{"self-hosted", "linux"}) {
			t.Errorf("%s: labels %q", r.Tool, r.Labels)
		}
	}
}

// An unquoted 3.10 is the float 3.1 to a YAML decoder, and the version a
// workflow asks for is the text GitHub hands the action. Reading it as a
// number would report Python 3.1, which nobody asked for.
func TestScanKeepsAVersionAsItIsWritten(t *testing.T) {
	got := scan(t, `
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/setup-python@v6
        with:
          python-version: 3.10
`)
	if want := []string{"test python 3.10"}; !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q, want %q", brief(got), want)
	}
}

// A matrix is how most workflows ask for several versions, and the labels are
// often in it too; each combination is a job GitHub runs.
func TestScanExpandsAMatrix(t *testing.T) {
	got := scan(t, `
jobs:
  test:
    runs-on: ${{ matrix.runner }}
    strategy:
      matrix:
        runner: [linux-x64, linux-arm64]
        python: ["3.11", "3.12"]
        exclude:
          - runner: linux-arm64
            python: "3.11"
    steps:
      - uses: actions/setup-python@v6
        with:
          python-version: ${{ matrix.python }}
`)
	var labelled []string
	for _, r := range got {
		labelled = append(labelled, r.Labels[0]+" "+r.Version)
	}
	want := []string{"linux-x64 3.11", "linux-x64 3.12", "linux-arm64 3.12"}
	if !reflect.DeepEqual(labelled, want) {
		t.Fatalf("got %q, want %q", labelled, want)
	}
}

// include adds a key to the combinations it matches, and a combination of its
// own when it matches none; a matrix of nothing but includes is a list of jobs.
func TestScanFollowsMatrixInclude(t *testing.T) {
	got := scan(t, `
jobs:
  test:
    runs-on: linux
    strategy:
      matrix:
        include:
          - node: "22"
          - node: "24"
            experimental: true
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: ${{ matrix.node }}
`)
	if want := []string{"test node 22", "test node 24"}; !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q, want %q", brief(got), want)
	}
}

// setup-python, setup-java and setup-dotnet each take several versions, one
// per line; every one of them is a download.
func TestScanSplitsAMultilineVersionInput(t *testing.T) {
	got := scan(t, `
jobs:
  test:
    runs-on: linux
    steps:
      - uses: actions/setup-dotnet@v5
        with:
          dotnet-version: |
            8.0.x
            10.0.x
`)
	if want := []string{"test dotnet 8.0.x", "test dotnet 10.0.x"}; !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q, want %q", brief(got), want)
	}
}

// What is not in the file is said to be not in the file. Dropping it would read
// as "this job needs no Python", and guessing would prefill the wrong version.
func TestScanSaysWhyAVersionIsUnresolved(t *testing.T) {
	got := scan(t, `
jobs:
  a:
    runs-on: linux
    steps:
      - uses: actions/setup-go@v6
        with:
          go-version-file: go.mod
  b:
    runs-on: linux
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: ${{ inputs.node }}
  c:
    runs-on: linux
    strategy:
      matrix: ${{ fromJSON(needs.plan.outputs.matrix) }}
    steps:
      - uses: actions/setup-python@v6
        with:
          python-version: ${{ matrix.python }}
`)
	want := []string{
		"a go ? read from go.mod in the repository",
		"b node ? set by the expression ${{ inputs.node }}",
		"c python ? set by a matrix built at run time",
	}
	if !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q\nwant %q", brief(got), want)
	}
}

// Labels that come from an expression the file cannot answer are unknown, not
// empty: an empty list would match any pool.
func TestScanLeavesUnknowableLabelsNil(t *testing.T) {
	got := scan(t, `
jobs:
  a:
    runs-on: ${{ inputs.runner }}
    steps:
      - uses: actions/setup-go@v6
        with:
          go-version: "1.27"
`)
	if len(got) != 1 || got[0].Labels != nil {
		t.Fatalf("got %+v, want one requirement with nil labels", got)
	}
}

// runs-on as a mapping names a runner group and labels; the group is not a
// label.
func TestScanReadsLabelsFromARunnerGroupMapping(t *testing.T) {
	got := scan(t, `
jobs:
  a:
    runs-on:
      group: builders
      labels: [linux, x64]
    steps:
      - uses: actions/setup-go@v6
        with:
          go-version: "1.27"
`)
	if len(got) != 1 || !reflect.DeepEqual(got[0].Labels, []string{"linux", "x64"}) {
		t.Fatalf("got %+v", got)
	}
}

// GitHub resolves uses: case-insensitively, and pinning by commit is the norm
// in a careful repository -- neither should hide a step.
func TestScanRecognisesPinnedAndOddlyCasedActions(t *testing.T) {
	got := scan(t, `
jobs:
  a:
    runs-on: linux
    steps:
      - uses: Actions/Setup-Go@4d34df0c2316fe8122ab82dc22947d607c0c91f9 # v5
        with:
          go-version: "1.26"
      - uses: ./local/setup-go
      - uses: someone/setup-python@v1
        with:
          python-version: "3.12"
`)
	if want := []string{"a go 1.26"}; !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q, want %q", brief(got), want)
	}
}

// The same requirement from two steps, or two combinations that only differ in
// a key the step does not use, is one requirement.
func TestScanReportsARequirementOnce(t *testing.T) {
	got := scan(t, `
jobs:
  a:
    runs-on: linux
    strategy:
      matrix:
        shard: [1, 2, 3]
    steps:
      - uses: actions/setup-node@v5
        with:
          node-version: "24"
`)
	if want := []string{"a node 24"}; !reflect.DeepEqual(brief(got), want) {
		t.Fatalf("got %q, want %q", brief(got), want)
	}
}

func TestScanRefusesAFileThatIsNotYAML(t *testing.T) {
	if _, err := Scan("bad.yml", "jobs: [\n"); err == nil {
		t.Fatal("expected an error")
	}
}

package version

import (
	"regexp"
	"strconv"
	"strings"
)

// Skew is how one build relates to another.
type Skew string

const (
	// SkewNone means the two are the same release.
	SkewNone Skew = ""
	// SkewBehind means the first build is an earlier release than the second.
	SkewBehind Skew = "behind"
	// SkewAhead means it is a later one, which for an agent against its
	// controller is the direction nobody tests.
	SkewAhead Skew = "ahead"
	// SkewDiffers means they are not the same and nothing here can say which
	// came first: a development build, a fork's tag, anything not shaped like
	// a release. Saying "differs" is the honest answer, and it is still worth
	// saying -- a fleet running two builds is a fleet whose behaviour has two
	// explanations.
	SkewDiffers Skew = "differs"
)

// CompareBuilds says how build a stands to build b.
//
// It compares releases, not commits. Two builds of one tag are the same
// release: a fleet where they differ has been rebuilt, which is worth knowing
// in a bug report and is not skew, and treating it as skew made every
// development fleet warn about itself constantly.
//
// The parser is deliberately small. It understands the shape this project
// tags -- v0.1-alpha, v1.2.3, 1.2 -- and answers SkewDiffers for anything
// else rather than guessing an order it cannot defend. A wrong order is worse
// than no order: it would tell an operator to upgrade the wrong side.
func CompareBuilds(a, b string) Skew {
	a, b = strings.TrimSpace(a), strings.TrimSpace(b)
	if a == "" || b == "" || a == b {
		return SkewNone
	}
	na, oka := parseRelease(a)
	nb, okb := parseRelease(b)
	if !oka || !okb {
		return SkewDiffers
	}
	for i := range na.parts {
		switch {
		case na.parts[i] < nb.parts[i]:
			return SkewBehind
		case na.parts[i] > nb.parts[i]:
			return SkewAhead
		}
	}
	// Same numbers, different text: a pre-release against the release it leads
	// to. "v1.0-rc1" is behind "v1.0", and an empty pre-release is the later
	// of the two, which is the one rule of pre-release ordering that matters
	// here and the one this project's own tags need.
	switch {
	case na.pre == nb.pre:
		// The same release written two ways -- "v1.2" and "v1.2.0", or with
		// and without the leading v. A person reading the two would say they
		// match, and so does this.
		return SkewNone
	case na.pre == "":
		return SkewAhead
	case nb.pre == "":
		return SkewBehind
	case na.pre < nb.pre:
		return SkewBehind
	default:
		return SkewAhead
	}
}

// release is a tag broken into the three numbers and whatever followed them.
type release struct {
	parts [3]int
	pre   string
}

// parseRelease reads "v1.2.3-rc1" and its shorter forms. Missing numbers are
// zero, so "v1.2" and "v1.2.0" are the same release, which is what a person
// reading the two would say.
func parseRelease(s string) (release, bool) {
	var out release
	s = strings.TrimPrefix(strings.TrimSpace(s), "v")
	if s == "" {
		return out, false
	}
	// The pre-release marker is the first hyphen or plus after the numbers.
	if i := strings.IndexAny(s, "-+"); i >= 0 {
		out.pre, s = s[i+1:], s[:i]
	}
	fields := strings.Split(s, ".")
	if len(fields) == 0 || len(fields) > 3 {
		return out, false
	}
	for i, f := range fields {
		n, err := strconv.Atoi(f)
		if err != nil || n < 0 {
			return out, false
		}
		out.parts[i] = n
	}
	return out, true
}

// releaseLike matches a version stamped from a release tag: 0.2-beta, v1.4.0.
// A build from main is stamped main-sha-abc1234 and matches nothing here.
var releaseLike = regexp.MustCompile(`^v?\d+\.\d+`)

// describeSuffix matches what `git describe` adds to a tag once commits have
// landed on top of it -- v0.2-beta-5-gabc1234 -- which is a local build of
// something past that release rather than the release itself.
var describeSuffix = regexp.MustCompile(`-\d+-g[0-9a-f]{7,}(-dirty)?$`)

// mainBuild matches the version CI stamps into every artifact built from the
// default branch. The moving dev tag carries those artifacts; the commit in
// the stamp is still what makes two concrete builds distinguishable.
var mainBuild = regexp.MustCompile(`^main-sha-[0-9a-f]{7,}$`)

// Release reports the release a build came from, and whether it came from one
// at all.
//
// Two callers need the same answer for different reasons, which is why it lives
// here rather than beside either of them. The update check asks so that it does
// not tell a controller running :dev -- stamped main-sha-abc1234, and usually
// *ahead* of the newest release -- to downgrade. InstallTag builds on the same
// answer to distinguish immutable versioned releases from the moving dev
// channel.
func Release(v string) (string, bool) {
	v = strings.TrimSpace(v)
	if v == "" || !releaseLike.MatchString(v) || describeSuffix.MatchString(v) {
		return "", false
	}
	return strings.TrimPrefix(v, "v"), true
}

// InstallTag returns the downloadable channel that carries this build.
//
// Releases have an immutable v-prefixed tag. Builds from main share the moving
// dev tag, which CI updates for the binary and every stock image on each push.
// A local git-describe build has neither, so callers must not pretend it can be
// downloaded from this repository.
func InstallTag(v string) (string, bool) {
	v = strings.TrimSpace(v)
	if release, ok := Release(v); ok {
		return "v" + release, true
	}
	if v == "dev" || mainBuild.MatchString(v) {
		return "dev", true
	}
	return "", false
}

// Channel is the image/download tag operators should use for this build, or
// empty for a local or otherwise unpublished build.
func Channel(v string) string {
	tag, _ := InstallTag(v)
	return tag
}

package version

import "testing"

// The comparison exists to tell an operator which side to upgrade, so the
// answer it must never get wrong is the direction. A wrong order sends them to
// the wrong machine; "differs" sends them to look, which is always safe.
func TestCompareBuildsOrdersReleasesAndRefusesToGuess(t *testing.T) {
	cases := []struct {
		a, b string
		want Skew
	}{
		// The same release, however it is written.
		{"v1.2.3", "v1.2.3", SkewNone},
		{"v1.2", "v1.2.0", SkewNone},
		{"1.2.3", "v1.2.3", SkewNone},
		{"", "v1.2.3", SkewNone},
		{"v1.2.3", "", SkewNone},

		// Ordered.
		{"v1.2.3", "v1.2.4", SkewBehind},
		{"v1.2.4", "v1.2.3", SkewAhead},
		{"v1.2.3", "v1.3.0", SkewBehind},
		{"v2.0.0", "v1.9.9", SkewAhead},
		{"v0.1-alpha", "v0.2", SkewBehind},

		// A pre-release leads to the release it names.
		{"v1.0-rc1", "v1.0", SkewBehind},
		{"v1.0", "v1.0-rc1", SkewAhead},
		{"v1.0-rc1", "v1.0-rc2", SkewBehind},

		// Two builds of one tag are the same release. Treating a rebuild as
		// skew made every development fleet warn about itself.
		{"dev", "dev", SkewNone},

		// Nothing here can order these, and guessing would be worse than
		// saying so.
		{"dev", "v1.2.3", SkewDiffers},
		{"v1.2.3", "some-fork-build", SkewDiffers},
		{"v1.2.3.4", "v1.2.3", SkewDiffers},
		{"v1.x", "v1.2", SkewDiffers},
	}

	for _, tc := range cases {
		if got := CompareBuilds(tc.a, tc.b); got != tc.want {
			t.Errorf("CompareBuilds(%q, %q) = %q, want %q", tc.a, tc.b, got, tc.want)
		}
	}
}

// Whatever the pair, reversing it reverses the answer. It is the property a
// direction has to have, and the one a hand-written comparator loses first.
func TestCompareBuildsIsSymmetric(t *testing.T) {
	opposite := map[Skew]Skew{
		SkewNone: SkewNone, SkewDiffers: SkewDiffers,
		SkewBehind: SkewAhead, SkewAhead: SkewBehind,
	}
	builds := []string{"", "dev", "v0.1-alpha", "v0.1", "v0.2", "v1.0-rc1", "v1.0", "v1.2.3", "weird"}
	for _, a := range builds {
		for _, b := range builds {
			forward, back := CompareBuilds(a, b), CompareBuilds(b, a)
			if back != opposite[forward] {
				t.Errorf("CompareBuilds(%q,%q) = %q but CompareBuilds(%q,%q) = %q", a, b, forward, b, a, back)
			}
		}
	}
}

func TestInstallTagNamesThePublishedChannel(t *testing.T) {
	for _, tc := range []struct {
		build string
		tag   string
		ok    bool
	}{
		{"1.2.3", "v1.2.3", true},
		{"v1.2.3", "v1.2.3", true},
		{"0.2-beta", "v0.2-beta", true},
		{"main-sha-117bc18", "dev", true},
		{"dev", "dev", true},
		{"v0.2-beta-276-g394254b", "", false},
		{"some-fork-build", "", false},
	} {
		t.Run(tc.build, func(t *testing.T) {
			got, ok := InstallTag(tc.build)
			if got != tc.tag || ok != tc.ok {
				t.Errorf("InstallTag(%q) = %q, %v; want %q, %v", tc.build, got, ok, tc.tag, tc.ok)
			}
			if channel := Channel(tc.build); channel != tc.tag {
				t.Errorf("Channel(%q) = %q, want %q", tc.build, channel, tc.tag)
			}
		})
	}
}

// Package version carries build metadata stamped in at link time.
package version

import (
	"fmt"
	"runtime"
	"runtime/debug"
)

// These are overridden with -ldflags "-X github.com/eyupio/zoomies/internal/version.Version=..."
var (
	Version = "dev"
	Commit  = ""
	Date    = ""
)

func init() {
	if info, ok := debug.ReadBuildInfo(); ok {
		Commit, Date = fill(Commit, Date, info.Settings)
	}
}

// fill decides the commit and the date, taking each from the link-time stamp
// when there is one and from the build information Go embeds otherwise.
//
// Each independently, which is the point: this used to give up entirely the
// moment a commit had been stamped, so a build that passed one and not the
// other -- the container image, which had no DATE build argument -- reported
// no date at all, and `zoomies version` on a compose install was quieter than
// the same release installed natively.
func fill(commit, date string, settings []debug.BuildSetting) (string, string) {
	if commit != "" && date != "" {
		return commit, date
	}
	for _, s := range settings {
		switch s.Key {
		case "vcs.revision":
			if commit == "" {
				commit = s.Value
			}
		case "vcs.time":
			if date == "" {
				date = s.Value
			}
		}
	}
	return commit, date
}

// Short returns a compact "v1.2.3 (abc1234)" style identifier.
func Short() string {
	if len(Commit) >= 7 {
		return fmt.Sprintf("%s (%s)", Version, Commit[:7])
	}
	return Version
}

// String returns the full human readable version banner line.
func String() string {
	return fmt.Sprintf("zoomies %s %s/%s %s", Short(), runtime.GOOS, runtime.GOARCH, runtime.Version())
}

// UserAgent is sent on every outbound GitHub API call.
func UserAgent() string { return "zoomies/" + Version }

package version

import (
	"runtime/debug"
	"testing"
)

// A build stamps what it knows. The container image stamps a commit and, until
// it was given a DATE build argument, no date -- and this used to abandon the
// build information the moment a commit was present, so the image reported no
// date at all while the same release installed natively reported one.
func TestEachStampIsFilledInOnItsOwn(t *testing.T) {
	embedded := []debug.BuildSetting{
		{Key: "vcs.revision", Value: "1a2b3c4d5e6f"},
		{Key: "vcs.time", Value: "2026-09-06T08:00:00Z"},
	}
	cases := []struct {
		name                 string
		commit, date         string
		wantCommit, wantDate string
		settings             []debug.BuildSetting
	}{
		{"nothing stamped", "", "", "1a2b3c4d5e6f", "2026-09-06T08:00:00Z", embedded},
		{"a commit stamped, no date", "deadbeef", "", "deadbeef", "2026-09-06T08:00:00Z", embedded},
		{"both stamped", "deadbeef", "yesterday", "deadbeef", "yesterday", embedded},
		{"nothing anywhere", "", "", "", "", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			commit, date := fill(tc.commit, tc.date, tc.settings)
			if commit != tc.wantCommit || date != tc.wantDate {
				t.Fatalf("fill = %q, %q; want %q, %q", commit, date, tc.wantCommit, tc.wantDate)
			}
		})
	}
}

{#
  Sharing and search metadata for zoomies.sh.

  Material's own social plugin is not used: it renders a card image per page
  with Cairo and Pillow, which would put two native libraries into the docs
  build for a picture the brand pack already supplies. These blocks are the part
  that matters -- a title, a description, one card image, and a machine-readable
  description of what the project is, absolute, on every page -- and they cost
  nothing.

  Everything here is derived from the page rather than written twice: the
  description falls back to site_description, the canonical URL is the one
  MkDocs already computes, the breadcrumb is read out of the navigation, and the
  modified date comes from git by way of hooks/seo.py.
#}
{% extends "base.html" %}

{#
  Locally hosted faces, so the page makes no third-party font request. Material
  would otherwise put a Google Fonts stylesheet in the head, and a
  render-blocking request to a host the reader cannot reach is what left the tab
  spinning with nothing to show. The @font-face rules and the woff2 files live
  in stylesheets/ beside this theme's CSS.
#}
{% block fonts %}
  <style>:root{--md-text-font:"InterVariable";--md-code-font:"JetBrains Mono"}</style>
{% endblock %}

{#
  The home page's title in a search result. Its heading is the tagline, written
  to be read under the logo, and Material would put that in the tab and the
  result too -- "Give your GitHub Actions runners the Zoomies." says nothing to
  someone searching for self-hosted runners. The social_title already says what
  Zoomies is, so the result uses it as well. Every other page keeps Material's
  rule: its own title, then the site's name.
#}
{% block htmltitle %}
  {% if page and page.is_homepage and page.meta and page.meta.social_title %}
    <title>{{ page.meta.social_title }}</title>
  {% else %}
    {{ super() }}
  {% endif %}
{% endblock %}

{% block extrahead %}
  {#
    The page's own title, not the abbreviation the sidebar uses: a navigation
    entry is trimmed to fit a column, and "FAQ -- Zoomies" is a worse thing to
    find in a search result than the sentence the page opens with.
  #}
  {% set page_title = (page.meta.title if page and page.meta and page.meta.title else (page.title if page else none)) %}
  {% set title = config.site_name %}
  {% if page_title and not page.is_homepage %}
    {% set title = page_title ~ " — " ~ config.site_name %}
  {% endif %}
  {#
    A page may name the title it wants to be shared under. The home page needs
    one: its heading is written to be read on the page, where the logo is
    already above it, and a link pasted into a chat window has neither. Anything
    else falls back to the rule above.
  #}
  {% if page and page.meta and page.meta.social_title %}
    {% set title = page.meta.social_title %}
  {% endif %}
  {% set description = config.site_description %}
  {% if page and page.meta and page.meta.description %}
    {% set description = page.meta.description %}
  {% endif %}
  {% set image = config.site_url ~ "brand/social-card.png" %}
  {% set canonical = page.canonical_url if page else config.site_url %}
  {% set modified = page.meta.git_date if page and page.meta else none %}

  {#
    Everything here is public documentation and is meant to be found, so the
    directives are the permissive ones: a full snippet rather than the ~160
    characters a search engine otherwise truncates to, and a large preview
    image rather than a thumbnail.

    The exceptions are the 404 template, which has no page behind it and is
    rendered at a different address every time it is served, and a page whose
    front matter says `noindex: true` -- notes written for contributors, which
    are published so links to them work but are not an answer to anything
    someone searches for. overrides/sitemap.xml leaves those out too.
  #}
  {% if page and not (page.meta and page.meta.noindex) %}
  <meta name="robots" content="index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1" />
  {% else %}
  <meta name="robots" content="noindex, follow" />
  {% endif %}

  <meta property="og:type" content="{{ 'article' if page and not page.is_homepage else 'website' }}" />
  <meta property="og:locale" content="en_GB" />
  <meta property="og:site_name" content="{{ config.site_name }}" />
  <meta property="og:title" content="{{ title }}" />
  <meta property="og:description" content="{{ description | striptags | trim }}" />
  <meta property="og:url" content="{{ canonical }}" />
  <meta property="og:image" content="{{ image }}" />
  <meta property="og:image:type" content="image/png" />
  <meta property="og:image:width" content="1200" />
  <meta property="og:image:height" content="630" />
  <meta property="og:image:alt" content="The Zoomies logo: a cocker spaniel curling through a circular motion path" />
  {% if modified %}
  <meta property="article:modified_time" content="{{ modified }}" />
  {% endif %}
  <meta name="twitter:card" content="summary_large_image" />
  <meta name="twitter:title" content="{{ title }}" />
  <meta name="twitter:description" content="{{ description | striptags | trim }}" />
  <meta name="twitter:image" content="{{ image }}" />
  <meta name="twitter:image:alt" content="The Zoomies logo: a cocker spaniel curling through a circular motion path" />

  {#
    The structured description search engines and AI assistants read. It says
    what Zoomies is, what it runs on and what it costs, because those are the
    three questions someone asks before installing a runner controller.

    It is on the home page only. Repeating one application's description on
    every page of its documentation is how a site ends up with fifteen
    competing answers to "what is this".

    The WebSite entry beside it describes the site's own search for consumers
    of the markup. Material reads ?q= on load, so the URL runs the query.
    Google retired the sitelinks search box; this does not enable one in Search.
  #}
  {% if page and page.is_homepage %}
  <script type="application/ld+json">
    {
      "@context": "https://schema.org",
      "@graph": [
        {
          "@type": "SoftwareApplication",
          "@id": "{{ config.site_url }}#software",
          "name": "Zoomies",
          "alternateName": "Zoomies runner fleet controller",
          "applicationCategory": "DeveloperApplication",
          "applicationSubCategory": "Continuous integration",
          "operatingSystem": "Linux",
          "url": "{{ config.site_url }}",
          "downloadUrl": "{{ config.site_url }}quickstart/",
          "installUrl": "{{ config.site_url }}install.sh",
          "codeRepository": "{{ config.repo_url }}",
          "license": "https://www.gnu.org/licenses/agpl-3.0.html",
          "description": {{ description | striptags | trim | tojson }},
          "image": "{{ image }}",
          "featureList": [
            "Ephemeral runners, one job per container",
            "GitHub App authentication with single-use JIT registrations",
            "Webhook-driven autoscaling, with polling as a fallback",
            "Multi-host agents that connect outbound only",
            "A live web UI for the whole fleet, with Prometheus metrics and an audit log",
            "Runner images for Ubuntu, Debian, Fedora and Rocky Linux",
            "A migration wizard that rewrites runs-on and opens one pull request per repository",
            "A one-line installer"
          ],
          "offers": { "@type": "Offer", "price": "0", "priceCurrency": "USD" },
          "isAccessibleForFree": true,
          "author": {
            "@type": "Organization",
            "name": "Zoomies contributors",
            "url": "{{ config.repo_url }}"
          },
          "keywords": "self-hosted GitHub Actions runner, ephemeral runners, autoscaling CI runners, GitHub Actions runner controller, self-hosted CI"
        },
        {
          "@type": "WebSite",
          "@id": "{{ config.site_url }}#website",
          "url": "{{ config.site_url }}",
          "name": "{{ config.site_name }}",
          "description": {{ description | striptags | trim | tojson }},
          "inLanguage": "en-GB",
          "about": { "@id": "{{ config.site_url }}#software" },
          "potentialAction": {
            "@type": "SearchAction",
