//go:build drill

package drill

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/agent"
)

// hammerWorkers is how many goroutines each hammer a noisy host's heartbeat
// and its task poll. It is far past anything one agent does -- an agent sends
// one heartbeat an interval and holds one poll -- and enough that, before the
// per-host limits, the noisy host's polls alone would have crossed the
// fleet-wide shed threshold on a controller holding only them.
const hammerWorkers = 32

// The agent-edge drill: one host hammering heartbeats and polls does not slow
// another host's work.
//
// A host is the untrusted edge. Its agent's token reaches only its own rows,
// but every call it makes still costs the controller something every other
// host shares: a write behind the single writer, a held connection counted
// against the fleet-wide poll threshold. The limits are per host so that a
// broken retry loop or a stolen token is that host's problem. The claim is the
// pair: the noisy host is refused, visibly, and the quiet host's task arrives
// inside one poll interval regardless -- asserted against the clock, not
// merely recorded.
func TestAHostHammeringTheAgentRoutesDoesNotDelayAnotherHostsTasks(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "agent-edge")
	defer rec.write()

	quiet := f.hostViews()
	if len(quiet) != 1 {
		t.Fatalf("the fleet has %d hosts before the noisy one joins, want the drill's agent alone", len(quiet))
	}
	quietID := quiet[0].ID

	noisyID, noisyToken := f.joinBareHost("drill-noisy")
	rec.note("noisy host joined", noisyID)

	ctx, stop := context.WithCancel(context.Background())
	var wg sync.WaitGroup
	defer func() { stop(); wg.Wait() }()
	var beats, refused, polls, emptyAtOnce atomic.Int64
	for range hammerWorkers {
		wg.Add(2)
		go func() {
			defer wg.Done()
			for ctx.Err() == nil {
				status := f.agentCall(ctx, noisyID, noisyToken, http.MethodPost, agent.PathHeartbeat,
					agent.HeartbeatRequest{ProtocolVersion: agent.ProtocolVersion, Version: "drill"})
				beats.Add(1)
				if status == http.StatusTooManyRequests {
					refused.Add(1)
				}
			}
		}()
		go func() {
			defer wg.Done()
			for ctx.Err() == nil {
				started := time.Now()
				status := f.agentCall(ctx, noisyID, noisyToken, http.MethodGet, agent.PathTasks+"?wait=25", nil)
				polls.Add(1)
				if status == http.StatusOK && time.Since(started) < time.Second {
					emptyAtOnce.Add(1)
				}
			}
		}()
	}
	rec.faultInjected(fmt.Sprintf("%d goroutines hammering heartbeat and %d hammering the task poll as one host", hammerWorkers, hammerWorkers))

	// Let the hammer reach its stride before any work is queued, so the
	// delivery below is measured under it rather than beside it.
	waitFor(t, waitProcessUp, "the noisy host to be refused on its heartbeats and its polls", func() bool {
		return refused.Load() > 0 && emptyAtOnce.Load() > 0
	})

	label := "drill-agent-edge"
	poolID := f.createPool("drill-edge", label)
	// From the job being queued to a workload on the quiet host is the
	// poller finding it, the pass that creates the runner and queues its task,
	// and the task's delivery -- the whole path the hammer could slow down.
	queued := time.Now()
	f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner to be created for the pool", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	waitFor(t, waitWorkloadUp, "a workload to appear on the quiet host", func() bool {
		return len(f.liveWorkloads()) == 1
	})
	delivered := time.Since(queued)
	rec.note("runner", runner.Name)
	rec.note("task delivered to the quiet host", delivered.Round(100*time.Millisecond).String())
	if delivered > agent.DefaultPollWait {
		t.Errorf("the quiet host's job took %s to become a workload under the hammer; it must arrive within one poll interval (%s)",
			delivered, agent.DefaultPollWait)
	}

	// The quiet host kept its heartbeats: its budget is its own.
	if !f.hostHealthy(quietID) {
		t.Error("the quiet host went unhealthy while another host was being refused")
	}

	stop()
	wg.Wait()

	// The refusals are on the scrape, which is where an operator watching a
	// fleet would see one host misbehaving.
	rate := f.counter(`zoomies_agent_requests_limited_total{limit="rate"}`)
	poll := f.counter(`zoomies_agent_requests_limited_total{limit="poll"}`)
	rec.note("noisy host", fmt.Sprintf("%d heartbeats (%d refused), %d polls (%d answered at once)",
		beats.Load(), refused.Load(), polls.Load(), emptyAtOnce.Load()))
	rec.note("scrape", fmt.Sprintf("limited rate=%v poll=%v", rate, poll))
	if rate < 1 || poll < 1 {
		t.Errorf("zoomies_agent_requests_limited_total shows rate=%v poll=%v; both limits should have been reached and counted", rate, poll)
	}
	rec.recovered()
	rec.pass("one host hammering heartbeats and polls was refused and counted, and another host's task still arrived inside one poll interval")
}

// joinBareHost enrols a host from the test process with a join token, the
// way an agent does, and returns its identity. It offers no backend, so
// nothing is ever placed on it and it can only make noise.
func (f *fleet) joinBareHost(name string) (string, string) {
	f.t.Helper()
	var token struct {
		Token string `json:"token"`
	}
	f.api.post("/join-tokens", map[string]any{"capacity": 2}, &token)
	body, _ := json.Marshal(agent.JoinRequest{
		ProtocolVersion: agent.ProtocolVersion, JoinToken: token.Token, Name: name,
		OS: "linux", Arch: "amd64", Capacity: 2,
	})
	resp, err := http.Post(f.baseURL+agent.PathJoin, "application/json", bytes.NewReader(body))
	if err != nil {
		f.t.Fatalf("joining %s: %v", name, err)
	}
	defer resp.Body.Close()
	var out agent.JoinResponse
	if resp.StatusCode != http.StatusOK || json.NewDecoder(resp.Body).Decode(&out) != nil || out.AgentToken == "" {
		f.t.Fatalf("joining %s answered %d", name, resp.StatusCode)
	}
	return out.HostID, out.AgentToken
}

// agentCall makes one agent request and returns its status, or zero when the
// request did not complete.
func (f *fleet) agentCall(ctx context.Context, hostID, token, method, path string, body any) int {
	var rdr io.Reader
	if body != nil {
		raw, _ := json.Marshal(body)
		rdr = bytes.NewReader(raw)
	}
	req, err := http.NewRequestWithContext(ctx, method, f.baseURL+path, rdr)
	if err != nil {
		return 0
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set(agent.HeaderHostID, hostID)
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0
	}
	_, _ = io.Copy(io.Discard, resp.Body)
	resp.Body.Close()
	return resp.StatusCode
}

// hostHealthy asks the API whether a host is healthy, which is the heartbeat's
// whole purpose seen from the operator's side.
func (f *fleet) hostHealthy(id string) bool {
	f.t.Helper()
	var h struct {
		Healthy bool `json:"healthy"`
	}
	f.api.get("/hosts/"+id, &h)
	return h.Healthy
}

// counter reads one series off the controller's scrape, or zero if it is not
// there.
func (f *fleet) counter(series string) float64 {
	f.t.Helper()
	resp, err := http.Get(f.baseURL + "/metrics")
	if err != nil {
		return 0
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	for _, line := range strings.Split(string(raw), "\n") {
		if rest, ok := strings.CutPrefix(line, series+" "); ok {
			v, _ := strconv.ParseFloat(strings.TrimSpace(rest), 64)
			return v
		}
	}
	return 0
}

//go:build drill

package drill

import "testing"

// The second fault drill: the agent is killed in the middle of a job.
//
// This is the fault an operator causes themselves -- an upgrade, a restart, a
// machine rebooting its services -- and the one with the most to lose, because
// the agent is the process on the same host as the work. Two things have to
// hold and they are separate claims. The runner must survive the agent dying,
// or every agent restart is a lost build. And the agent must come back as the
// host it already was, from the credentials in its work directory, or a
// restart means re-joining a fleet by hand on every machine.
//
// Both hold. What this drill found is the third thing, at the end: the
// adopted runner's exit code died with the old agent, so a build that
// succeeded is recorded as removed or failed depending on which path gets
// there first.
func TestKillingTheAgentMidJobLeavesTheWorkRunning(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "agent-restart")
	defer rec.write()

	label := "drill-agent-restart"
	poolID := f.createPool("drill-agent", label)
	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner to be created for the pool", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	// The stub can publish its started marker before the backend has written
	// runner.pid. Wait for that durable record too: killing the agent earlier
	// interrupts creation, and the survival check cannot identify the process.
	waitFor(t, waitWorkloadUp, "a workload and its persisted PID to appear on the host", func() bool {
		return len(f.liveWorkloads()) == 1 && f.workloadRunning(runner.Name)
	})
	rec.note("workload on host", f.liveWorkloads()[0])

	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	waitFor(t, waitJobDone, "the fleet to see the job start", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID && (r.State == "busy" || r.State == "draining") {
				return true
			}
		}
		return false
	})

	hostsBefore := f.hostIDs()
	rec.faultInjected("killed the agent while the job was running")
	f.agent.kill()

	// The claim that matters most on this path: the runner is a process doing
	// somebody's work, and the agent going away is not a reason to end it.
	f.requireStillRunning(runner.Name, "killing the agent must not take the job with it")
	rec.note("workload after the agent died", "still running")

	f.restartAgent()
	waitFor(t, waitRecovery, "the agent to be back", func() bool {
		return len(f.hostIDs()) > 0
	})
	if after := f.hostIDs(); len(after) != len(hostsBefore) {
		t.Fatalf("the fleet has hosts %v after the restart but had %v before; an agent that comes back as a second host leaves the first one to be reaped and its runners with it",
			after, hostsBefore)
	}
	rec.note("host after the restart", "the same one, no second host")

	// And the fleet finishes what was running: the restarted agent picked the
	// runner back up rather than leaving it for a timeout.
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}
	waitFor(t, waitRecovery, "the runner to reach a terminal state after the agent came back", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID {
				return r.State == "removed" || r.State == "failed"
			}
		}
		return false
	})
	waitFor(t, waitRecovery, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	rec.recovered()
	rec.note("host workloads after the restarted agent finished the job", "0")

	// An unknown process exit must not turn a successful job into a failed
	// runner depending on which report won the race.
	final := f.runnerByID(runner.ID, poolID)
	if final.State != "removed" {
		t.Errorf("runner ended in state %q after a successful job, want removed", final.State)
	}
	rec.note("runner state after the restart finished the job", final.State)

	rec.pass("an agent killed mid-job left the work running, came back as the same host, and the job was finished and cleaned up; its runner is consistently removed")
}

// hostIDs is the fleet's own list of hosts, which is how a drill tells a
// restart from a second machine appearing.
func (f *fleet) hostIDs() []string {
	f.t.Helper()
	var out struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
	}
	f.api.get("/hosts", &out)
	ids := make([]string, 0, len(out.Items))
	for _, h := range out.Items {
		ids = append(ids, h.ID)
	}
	return ids
}

//go:build drill

package drill

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/eyupio/zoomies/internal/github"
)

// The unattended drill: a controller comes up from its environment alone, with
// authentication on, and a provisioner drives it to a joined agent without a
// browser and without reading a line of its log.
//
// This is what a compose file or a Terraform module has to be able to do:
// nobody is watching, so the setup token printed to the log is a step nobody
// takes. The provisioner writes a token it generated into a 0600 file, starts
// the controller with ZOOMIES_BOOTSTRAP_ADMIN and ZOOMIES_BOOTSTRAP_TOKEN_FILE,
// waits on /readyz for bootstrap_required to go false, and then uses the token
// it already holds -- as a platform account -- to mint a join token and enrol
// an agent. It runs the real binary as the two processes a compose file would
// start; it is not a `docker compose up`.
func TestAnUnattendedControllerIsUsableWithNoHumanStep(t *testing.T) {
	requireBinary(t)
	rec := newRecord(t, "unattended-bootstrap")
	defer rec.write()

	gh := github.NewFake()
	t.Cleanup(gh.Close)
	f := &fleet{t: t, gh: gh, port: freePort(t), stateDir: t.TempDir()}
	f.baseURL = fmt.Sprintf("http://127.0.0.1:%d", f.port)

	secret := make([]byte, 32)
	if _, err := rand.Read(secret); err != nil {
		t.Fatalf("generating the provisioner's token: %v", err)
	}
	token := hex.EncodeToString(secret)
	tokenFile := filepath.Join(t.TempDir(), "bootstrap-token")
	if err := os.WriteFile(tokenFile, []byte(token+"\n"), 0o600); err != nil {
		t.Fatalf("writing the token file: %v", err)
	}

	f.controller = f.spawn("controller", []string{"controller"}, append(baseEnv(f.stateDir),
		fmt.Sprintf("ZOOMIES_BIND=127.0.0.1:%d", f.port),
		"ZOOMIES_DB_PATH="+filepath.Join(f.stateDir, "zoomies.db"),
		"ZOOMIES_GITHUB_API_BASE_URL="+gh.URL(),
		"ZOOMIES_AGENT_EMBEDDED=false",
		"ZOOMIES_BOOTSTRAP_ADMIN=provisioner",
		"ZOOMIES_BOOTSTRAP_TOKEN_FILE="+tokenFile,
	))

	// One endpoint answers "can I use this yet", and it is the only thing the
	// provisioner watches.
	waitFor(t, waitProcessUp, "/readyz to report the instance usable", func() bool {
		resp, err := http.Get(f.baseURL + "/readyz")
		if err != nil {
			return false
		}
		defer resp.Body.Close()
		var body struct {
			OK                bool  `json:"ok"`
			BootstrapRequired *bool `json:"bootstrap_required"`
		}
		if json.NewDecoder(resp.Body).Decode(&body) != nil {
			return false
		}
		return body.OK && body.BootstrapRequired != nil && !*body.BootstrapRequired
	})
	rec.note("ready", "/readyz reported bootstrap_required false")

	// Without the token the API is closed: authentication is on, which is
	// what makes the rest of this worth anything.
	resp, err := http.Get(f.baseURL + "/api/v1/hosts")
	if err != nil {
		t.Fatalf("GET /hosts: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusUnauthorized {
		t.Fatalf("an anonymous GET /hosts answered %s; the instance must not be open", resp.Status)
	}

	f.api = &apiClient{t: t, base: f.baseURL + "/api/v1", token: token}
	var me struct {
		Role string `json:"role"`
	}
	f.api.get("/auth/session", &me)
	if me.Role != "platform" {
		t.Fatalf("the provisioner's token is %q; want platform", me.Role)
	}

	// The platform account mints a join token through the API, and an agent
	// joins with it.
	var join struct {
		Token string `json:"token"`
	}
	f.api.post("/join-tokens", map[string]any{"capacity": 2}, &join)
	if join.Token == "" {
		t.Fatal("the join token came back empty")
	}
	agentDir := t.TempDir()
	work := filepath.Join(agentDir, "work")
	if err := os.MkdirAll(work, 0o750); err != nil {
		t.Fatalf("creating the agent work directory: %v", err)
	}
	f.agent = f.spawn("agent", []string{"agent"}, append(baseEnv(agentDir),
		"ZOOMIES_CONTROLLER_URL="+f.baseURL,
		"ZOOMIES_JOIN_TOKEN="+join.Token,
		"ZOOMIES_AGENT_BACKEND=process",
		"ZOOMIES_AGENT_CAPACITY=2",
		"ZOOMIES_WORK_DIR="+work,
		"ZOOMIES_AGENT_ALLOW_INSECURE_HTTP=true",
		"ZOOMIES_AGENT_RUNNER_DOWNLOAD_URL=http://127.0.0.1:1/never",
	))

	waitFor(t, waitProcessUp, "the agent to join and report healthy", func() bool {
		var out struct {
			Items []struct {
				Healthy bool `json:"healthy"`
			} `json:"items"`
		}
		f.api.get("/hosts", &out)
		return len(out.Items) == 1 && out.Items[0].Healthy
	})
	rec.note("joined", "one agent joined with a join token the bootstrap account minted, and is healthy")

	// Who bootstrapped and how is in the audit log, not only in a log line.
	var audit struct {
		Items []struct {
			Action    string `json:"action"`
			ActorKind string `json:"actor_kind"`
			After     any    `json:"after"`
		} `json:"items"`
	}
	f.api.get("/audit?action=auth.bootstrap", &audit)
	if len(audit.Items) != 1 || audit.Items[0].ActorKind != "system" {
		t.Fatalf("the audit log has %+v; want one auth.bootstrap row by the system", audit.Items)
	}
	if after, _ := json.Marshal(audit.Items[0].After); !strings.Contains(string(after), "environment_token") {
		t.Fatalf("the auth.bootstrap row says %s; want the environment token method", after)
	}

	// The negative half, and the only look at the output: an instance that
	// bootstrapped itself has no setup token to print, and a secret it never
	// minted is never written out.
	out := f.controller.output()
	if strings.Contains(out, "setup token") {
		t.Error("the controller printed a setup token although the environment had already created the first account")
	}
	if strings.Contains(out, token) {
		t.Error("the controller wrote the provisioner's token to its output")
	}

	rec.pass("a controller started with ZOOMIES_BOOTSTRAP_ADMIN and ZOOMIES_BOOTSTRAP_TOKEN_FILE reports bootstrap_required false on /readyz, " +
		"the provisioner's own token is a platform identity that mints a join token, and the agent it enrols is healthy -- " +
		"with no browser, no setup token and no log read")
}

package drill

import "time"

// The drills' waits.
//
// These are much shorter than the end-to-end harness's, and for a good reason:
// nothing here crosses a network or pulls an image. GitHub is a fake in this
// process, the runner is a stub already on disk, and the two Zoomies binaries
// are starting locally. A drill that needs minutes is a drill that has hung.
//
// The file carries no build tag so budget_test.go can check these against the
// Makefile's timeout in ordinary CI, the same way the e2e harness does.
const (
	waitProcessUp     = 30 * time.Second
	waitRunnerCreated = 60 * time.Second
	waitWorkloadUp    = 60 * time.Second
	waitJobDone       = 60 * time.Second
	waitRunnerGone    = 60 * time.Second
	// waitPromptCleanup is how long the removal path itself gets to delete a
	// GitHub registration. It is deliberately far shorter than the rest: the
	// reaper's first sweep is a minute after the controller starts, and an
	// assertion looser than that would be satisfied by the backstop instead of
	// by the code under test.
	waitPromptCleanup = 15 * time.Second
	// waitStaysUp is how long a fault drill watches a runner it expects to have
	// survived. Short, because it is watching for a death that has already been
	// set in motion rather than for one that might happen later.
	waitStaysUp = 3 * time.Second
	// waitRecovery is what a fault drill allows for the fleet to come back
	// after something is killed. It is the longest wait here because a
	// restarted controller has to re-derive its task queue from the rows.
	waitRecovery = 90 * time.Second
)

// drillBudget is the longest one drill may legitimately take.
const drillBudget = waitProcessUp + waitRunnerCreated + waitWorkloadUp +
	waitJobDone + waitRunnerGone + waitPromptCleanup + waitRecovery + waitStaysUp

package drill

import (
	"os"
	"path/filepath"
	"regexp"
	"testing"
	"time"
)

// The drills' waits must fit inside the timeout the Makefile gives them, for
// the same reason the end-to-end harness's must: a drill killed by `go test`
// is reported as a timeout, which names nothing, instead of as the thing it
// was actually stuck on.
//
// No build tag, so it runs on every ordinary `go test ./...` rather than only
// where somebody has built the binary and asked for the drill tier.
func TestTheDrillsFitInsideTheMakefilesTimeout(t *testing.T) {
	root := repoRootFrom(t)
	raw, err := os.ReadFile(filepath.Join(root, "Makefile"))
	if err != nil {
		t.Fatalf("reading the Makefile: %v", err)
	}
	re := regexp.MustCompile(`(?m)^\s+.*-tags drill.*-timeout (\S+)`)
	matches := re.FindAllStringSubmatch(string(raw), -1)
	if len(matches) == 0 {
		t.Fatal("no `go test -tags drill ... -timeout` line found in the Makefile; " +
			"if the target was renamed, update this test rather than deleting it")
	}
	for _, m := range matches {
		limit, err := time.ParseDuration(m[1])
		if err != nil {
			t.Fatalf("the Makefile's drill timeout %q is not a duration: %v", m[1], err)
		}
		if limit <= drillBudget {
			t.Errorf("the Makefile allows %s but one drill's waits need %s", limit, drillBudget)
		}
	}
}

func repoRootFrom(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		dir = filepath.Dir(dir)
	}
	t.Fatal("could not find the repository root from the test's working directory")
	return ""
}

//go:build drill

package drill

import "testing"

// The first fault drill: the controller is killed in the middle of a job.
//
// A control plane is allowed to die. A job is not. The runner is a process on
// somebody's machine doing somebody's work, and the only thing that should
// follow from the controller going away is that nothing new gets decided until
// it comes back -- not that the work is torn down, not that the fleet forgets
// it, and not that the agent gives up and has to be re-joined by hand.
//
// Every layer of this is already tested in process: the agent's poll loop
// backs off and retries, the task queue is re-derived from the rows on start,
// and adoption reattaches what is already running. What no in-process test can
// show is the three of them surviving the same event, with a real process
// holding a real job while the thing that decided to start it is not there.
func TestKillingTheControllerMidJobLeavesTheWorkRunning(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "controller-restart")
	defer rec.write()

	label := "drill-controller-restart"
	poolID := f.createPool("drill-restart", label)
	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner to be created for the pool", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	// The stub can publish its started marker before the backend has written
	// runner.pid. Wait for that durable record too: the survival check below
	// reads it, and without it a live process looks like a dead one.
	waitFor(t, waitWorkloadUp, "a workload and its persisted PID to appear on the host", func() bool {
		return len(f.liveWorkloads()) == 1 && f.workloadRunning(runner.Name)
	})
	rec.note("workload on host", f.liveWorkloads()[0])

	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	waitFor(t, waitJobDone, "the fleet to see the job start", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID && (r.State == "busy" || r.State == "draining") {
				return true
			}
		}
		return false
	})
	rec.note("job in progress on", runner.Name)

	// The fault. kill() waits for the process to be gone, so whatever the
	// controller does on its way out has already happened by the next line.
	rec.faultInjected("killed the controller while the job was running")
	f.controller.kill()

	f.requireStillRunning(runner.Name, "a control plane that takes the work down with it is worse than one that simply stops")
	rec.note("workload after the controller died", "still running")

	// The same address and the same database: this is a restart, not a new
	// fleet. The agent is not told; it has to notice on its own.
	f.startControllerOn(f.stateDir)
	survived := f.runnerByID(runner.ID, poolID)
	if survived.State == "failed" || survived.State == "removed" {
		t.Fatalf("the runner came back from the restart in state %q, but its job is still running on this host; the outage was the controller's, not the runner's", survived.State)
	}
	rec.note("runner state after the restart", survived.State)

	// The job finishes while the new controller is the one watching. Nothing
	// re-joined the agent and nothing re-created the runner: if the fleet
	// cleans this up, the agent found its way back on its own.
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}

	waitFor(t, waitRecovery, "the runner to reach a terminal state under the new controller", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID {
				return r.State == "removed" || r.State == "failed"
			}
		}
		return false
	})
	final := f.runnerByID(runner.ID, poolID)
	if final.State != "removed" {
		t.Errorf("runner ended in state %q, want removed", final.State)
	}
	waitFor(t, waitRecovery, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	// Recovery is measured to here rather than to the controller answering
	// again: a fleet is not recovered when its API is up, it is recovered when
	// work is moving through it.
	rec.recovered()
	rec.note("host workloads after the restart finished the job", "0")

	// The usage ledger: the runner's session is written once, when its
	// cleanup is confirmed, and a second restart -- with an agent that may
	// report its results again -- must not write another. Two would double
	// this runner's hours in every report that covers them.
	waitFor(t, waitPromptCleanup, "the runner's usage session to be written", func() bool {
		return f.runnerSessions(runner.ID) == 1
	})
	f.controller.kill()
	f.startControllerOn(f.stateDir)
	f.runnerByID(runner.ID, poolID)
	if n := f.runnerSessions(runner.ID); n != 1 {
		t.Errorf("the runner has %d usage sessions after a second restart, want exactly 1", n)
	}
	rec.note("usage sessions for the runner after a second restart", "1")
	rec.pass("a controller killed mid-job left the work running, and the fleet finished and cleaned it up after the restart")
}

// Package drill is the runtime tier: it runs the built binary, as a real
// controller and a real remote agent, against an in-process fake GitHub, and
// watches a workload actually appear on this machine and go away again.
//
// It is behind the "drill" build tag. Everything else in this repository tests
// the code in the test process; this is the only place that qualifies the
// product as the operator gets it -- two processes, a join token, a backend
// touching the host -- and the only place ZF-302's fault drills can run
// repeatably, because the GitHub side is a fake rather than somebody's real
// organisation.
//
// See README.md in this directory for what it needs and what it asserts.
package drill

//go:build drill

package drill

import (
	"strings"
	"testing"
)

// dockerBackend is named once: the drill asks the host about this backend, the
// pool runs on it, and the problem has to name it, and those three have to be
// the same string.
const dockerBackend = "docker"

// The fifth fault drill: a host whose Docker socket is not there.
//
// This is the fault an operator is most likely to cause by accident -- a
// daemon that did not come back after a reboot, a socket a hardening pass
// moved, an agent running as a user that is not in the `docker` group -- and
// the one where saying nothing is worst. The jobs still queue, the pool still
// looks configured, and a fleet that quietly places nothing is
// indistinguishable from a fleet with nothing to do.
//
// So the drill asks for the two things a person needs and nothing more: the
// host says which backend is unusable and why, and the pool that cannot place
// anything says so as a problem an operator would see, with a fix.
//
// What it deliberately does not cover is the recovery half. Starting a daemon
// needs a daemon, and this tier has none -- that is what makes it something
// every pull request can afford. A socket that is not there is exactly what a
// stopped daemon looks like from the outside, and that half is honest here;
// the rest belongs on the reference host the roadmap asks the owner for.
func TestAHostWithNoDockerSocketSaysWhichBackendIsUnusable(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "docker-socket")
	defer rec.write()

	const name = "drill-docker-host"
	rec.faultInjected("joined a host whose Docker socket is not there")
	f.startBrokenDockerAgent(name)

	// It joins. An agent that refused to start on a host with no daemon would
	// take the fleet's only way of telling anybody about it with it.
	var broken hostView
	waitFor(t, waitProcessUp, "the host with no Docker to appear", func() bool {
		for _, h := range f.hostViews() {
			if h.Name == name {
				broken = h
				return true
			}
		}
		return false
	})
	rec.note("host joined", broken.ID)

	// And it says which backend is unusable, where it looked, and why -- the
	// three things that turn "it is not working" into something to go and fix.
	var docker struct {
		found     bool
		available bool
		endpoint  string
		detail    string
	}
	for _, b := range broken.BackendInfo {
		if b.Kind == dockerBackend {
			docker.found, docker.available = true, b.Available
			docker.endpoint, docker.detail = b.Endpoint, b.Detail
		}
	}
	if !docker.found {
		t.Fatalf("the host reports no docker backend at all: %+v", broken.BackendInfo)
	}
	if docker.available {
		t.Fatalf("the host says its docker backend is available, with no socket at %s", docker.endpoint)
	}
	if !strings.Contains(docker.endpoint, "zoomies-drill-docker.sock") {
		t.Errorf("the host does not say where it looked: endpoint %q", docker.endpoint)
	}
	if docker.detail == "" {
		t.Errorf("the host says the backend is unavailable and not why; an operator has nothing to act on")
	}
	rec.note("host says the backend is unusable", docker.detail)

	// The pool below is kept to this host by that label, so the machine the
	// drill runs on cannot answer for it. Checking the label arrived first is
	// what stops a selector that matches nothing looking like a fleet that
	// placed nothing.
	key, value, _ := strings.Cut(brokenDockerLabel, "=")
	if broken.Labels[key] != value {
		t.Fatalf("the broken host is not labelled %s: %v", brokenDockerLabel, broken.Labels)
	}

	// A pool on that backend with work waiting is the case that must not be
	// silent. It is an error rather than a warning because there is nothing
	// here that time will fix.
	poolID := f.createPoolOn("drilldocker", dockerBackend, map[string]string{key: value}, "drill-docker")
	f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", "drill-docker"})

	var problem problemView
	waitFor(t, waitRunnerCreated, "the fleet to raise a problem for the pool that cannot place", func() bool {
		for _, p := range f.problems() {
			if p.Code == "pool.no_capacity" && strings.Contains(p.Title, "drilldocker") {
				problem = p
				return true
			}
		}
		return false
	})
	if problem.Severity != "error" {
		t.Errorf("a pool with work waiting and nowhere to run it is %q; want error, because nothing here clears on its own", problem.Severity)
	}
	if problem.Detail == "" || problem.Fix == "" {
		t.Errorf("the problem says what is wrong without saying what to do: %+v", problem)
	}
	// And it is blocked on the socket rather than on the selector that pinned
	// it. A drill whose selector matched nothing would raise this same problem
	// for the wrong reason and pass anyway, which is the failure mode of
	// testing a fault by arranging a fleet.
	if !strings.Contains(problem.Detail, "without the "+dockerBackend+" backend") {
		t.Errorf("the problem does not name the backend the host could not offer: %q", problem.Detail)
	}
	rec.note("problem raised", problem.Title+" -- "+problem.Detail)

	// And nothing was started anyway. A fleet that answered an unusable
	// backend by trying would leave half-made runners behind on every pass.
	if runners := f.runners(poolID); len(runners) != 0 {
		t.Errorf("the fleet created %d runner(s) for a pool whose backend is unusable", len(runners))
	}
	if live := f.liveWorkloads(); len(live) != 0 {
		t.Errorf("the host holds %v for a backend that is not there", live)
	}
	rec.note("started anyway", "nothing")
	rec.pass("a host whose Docker socket is missing joined, named the backend it could not use and where it looked, and the pool that could not place raised an error saying what to do")
}

//go:build drill

package drill

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/github"
	"github.com/eyupio/zoomies/internal/store"
)

// fleet is one drill's world: a fake GitHub, a controller process, and a
// remote agent process, all real except GitHub.
//
// The two Zoomies processes are the built binary, started the way an operator
// starts them. That is the point of this tier: every other test in the
// repository exercises the code inside the test process, where a restart is a
// struct being rebuilt and an agent is a goroutine. Here a restart is a
// process dying, the agent is on the other end of a socket having joined with
// a token, and the backend puts something on the host.
type fleet struct {
	t   *testing.T
	gh  *github.FakeGitHub
	api *apiClient

	controller *process
	agent      *process
	// agentEnv is what the agent was started with, so a drill can kill it and
	// start it again as the same host: its credentials are in the work
	// directory, so a restart needs no second join token.
	agentEnv []string

	baseURL string
	// port and stateDir are kept so a drill can stop the controller and start
	// another on the same address -- against the same database, or against one
	// it has just restored.
	port     int
	stateDir string
	// agentWork is the directory inside the agent's state directory where the
	// backend lays out runners. The drill watches it to see a workload appear.
	agentWork string

	installationID string
}

// process is one child binary, with its output kept for the failure message.
type process struct {
	name string
	cmd  *exec.Cmd
	stop context.CancelFunc

	mu   sync.Mutex
	logs bytes.Buffer
	done chan struct{}
}

func (p *process) output() string {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.logs.String()
}

// kill stops the process abruptly, which is what a drill wants when it is
// testing what a crash does. Waiting for it to exit is deliberate: a drill
// that carried on while the old process still held its port or its database
// lock would be testing the wrong thing.
func (p *process) kill() {
	p.stop()
	<-p.done
}

// newFleet stands up the whole thing and tears it down on cleanup.
func newFleet(t *testing.T) *fleet {
	t.Helper()
	requireBinary(t)

	gh := github.NewFake()
	t.Cleanup(gh.Close)
	gh.AddRepo("acme/api")

	f := &fleet{t: t, gh: gh}
	f.startController()
	f.connectInstallation()
	f.startAgent()
	return f
}

// startController runs the built binary as a controller pointed at the fake.
func (f *fleet) startController() {
	t := f.t
	t.Helper()
	f.port = freePort(t)
	f.stateDir = t.TempDir()
	f.startControllerOn(f.stateDir)
}

// startControllerOn runs the built binary as a controller against one state
// directory, on this fleet's address.
//
// The directory is a parameter because a restore drill's whole point is that
// the second controller comes up on a different one: the database it was given
// rather than the database it wrote.
func (f *fleet) startControllerOn(dir string) {
	t := f.t
	t.Helper()
	port := f.port
	f.baseURL = fmt.Sprintf("http://127.0.0.1:%d", port)

	f.controller = f.spawn("controller", []string{"controller"}, append(baseEnv(dir),
		fmt.Sprintf("ZOOMIES_BIND=127.0.0.1:%d", port),
		"ZOOMIES_DISABLE_AUTH=true", // loopback only; the validator allows it there
		"ZOOMIES_DB_PATH="+filepath.Join(dir, "zoomies.db"),
		// The whole reason this tier can run without credentials.
		"ZOOMIES_GITHUB_API_BASE_URL="+f.gh.URL(),
		// A remote agent is the point; the embedded one would hide the join.
		"ZOOMIES_AGENT_EMBEDDED=false",
		// Webhooks cannot reach a test process, so the poller is what notices
		// a queued job. Short, because a drill's patience is its runtime.
		"ZOOMIES_POLL_FALLBACK=true",
		"ZOOMIES_POLL_INTERVAL=2s",
	))
	f.api = &apiClient{t: t, base: f.baseURL + "/api/v1"}
	waitFor(t, waitProcessUp, "the controller to become healthy", func() bool {
		resp, err := http.Get(f.baseURL + "/healthz")
		if err != nil {
			return false
		}
		resp.Body.Close()
		return resp.StatusCode == http.StatusOK
	})
}

// run executes the built binary as a one-shot command against a state
// directory, the way an operator runs `zoomies backup` on the machine holding
// the data. It returns what the command printed.
func (f *fleet) run(dir string, args ...string) string {
	t := f.t
	t.Helper()
	cmd := exec.Command(builtBinary(), args...)
	cmd.Env = append(baseEnv(dir), "ZOOMIES_DB_PATH="+filepath.Join(dir, "zoomies.db"))
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("zoomies %s: %v\noutput: %q", strings.Join(args, " "), err, string(out))
	}
	return string(out)
}

// connectInstallation registers the fake's app with the controller.
func (f *fleet) connectInstallation() {
	t := f.t
	t.Helper()
	var inst struct {
		ID string `json:"id"`
	}
	f.api.post("/installations", map[string]any{
		"app_id":          f.gh.AppID(),
		"installation_id": f.gh.InstallationID(),
		"target":          "acme",
		"target_type":     "org",
		"private_key":     generateAppKey(t),
		"webhook_secret":  drillWebhookSecret,
		// Named on the installation rather than left to the global setting, so
		// the row itself says which GitHub this fleet is talking to.
		"api_base_url": f.gh.URL(),
	}, &inst)
	if inst.ID == "" {
		t.Fatal("the installation came back without an ID")
	}
	f.installationID = inst.ID
}

// startAgent joins a second binary as a remote agent, with a join token.
func (f *fleet) startAgent() {
	t := f.t
	t.Helper()
	var token struct {
		Token string `json:"token"`
	}
	f.api.post("/join-tokens", map[string]any{"capacity": 2}, &token)
	if token.Token == "" {
		t.Fatal("the join token came back empty")
	}

	dir := t.TempDir()
	f.agentWork = filepath.Join(dir, "work")
	if err := os.MkdirAll(f.agentWork, 0o750); err != nil {
		t.Fatalf("creating the agent work directory: %v", err)
	}
	// Before the agent starts: the backend looks for the runner tree the first
	// time it is asked to create anything.
	if err := stageStubRunner(f.agentWork); err != nil {
		t.Fatalf("staging the stub runner: %v", err)
	}

	f.agentEnv = append(baseEnv(dir),
		"ZOOMIES_CONTROLLER_URL="+f.baseURL,
		"ZOOMIES_AGENT_BACKEND=process",
		"ZOOMIES_AGENT_CAPACITY=2",
		"ZOOMIES_WORK_DIR="+f.agentWork,
		// Plain HTTP to a loopback controller is what a drill has; the agent
		// refuses it otherwise, and rightly.
		"ZOOMIES_AGENT_ALLOW_INSECURE_HTTP=true",
		// Nothing should be downloaded: the stub tree is staged and the pool
		// pins its version. Saying so means a drill that somehow reaches for
		// the network fails here rather than hanging.
		"ZOOMIES_AGENT_RUNNER_DOWNLOAD_URL=http://127.0.0.1:1/never",
	)
	// The join token is passed to the first start only. A restart that carried
	// one would prove nothing about a restart: an agent has to come back as the
	// host it already is, from the credentials it wrote.
	f.agent = f.spawn("agent", []string{"agent"},
		append(f.agentEnv, "ZOOMIES_JOIN_TOKEN="+token.Token))

	waitFor(t, waitProcessUp, "the agent to join and appear as a host", func() bool {
		var out struct {
			Items []struct {
				ID string `json:"id"`
			} `json:"items"`
		}
		f.api.get("/hosts", &out)
		return len(out.Items) > 0
	})
}

// brokenDockerLabel is how a pool asks for the host whose Docker socket is
// missing, and it exists because the drill's own machine is in the fleet.
// ZOOMIES_AGENT_BACKEND names an agent's default backend rather than its only
// one -- every agent probes for all of them and reports what it finds -- so on
// a CI runner with Docker installed the drill's first agent offers docker too.
// A docker pool with no selector then places there quite happily, and a drill
// about a host that cannot run anything silently tests a host that can.
const brokenDockerLabel = "drill=docker-broken"

// startBrokenDockerAgent joins a second agent whose Docker socket is not there.
//
// It is a second machine rather than a reconfigured first one, because that is
// the shape of the fault in a real fleet: one host's daemon is down and the
// others are fine, and what matters is whether the fleet says which. The name
// is set explicitly because both agents are on this machine and would
// otherwise claim the same host row.
func (f *fleet) startBrokenDockerAgent(name string) *process {
	t := f.t
	t.Helper()
	var token struct {
		Token string `json:"token"`
	}
	f.api.post("/join-tokens", map[string]any{"capacity": 2}, &token)
	if token.Token == "" {
		t.Fatal("the join token came back empty")
	}
	dir := t.TempDir()
	work := filepath.Join(dir, "work")
	if err := os.MkdirAll(work, 0o750); err != nil {
		t.Fatalf("creating the work directory: %v", err)
	}
	return f.spawn("docker-agent", []string{"agent"}, append(baseEnv(dir),
		"ZOOMIES_CONTROLLER_URL="+f.baseURL,
		"ZOOMIES_JOIN_TOKEN="+token.Token,
		"ZOOMIES_AGENT_NAME="+name,
		"ZOOMIES_AGENT_BACKEND=docker",
		// The label a pool selects it by, so the drill's own machine cannot
		// answer for it.
		"ZOOMIES_AGENT_LABELS="+brokenDockerLabel,
		// A socket that is not there is what a stopped daemon looks like from
		// the outside, and it is the one version of this fault a tier with no
		// daemon can produce honestly.
		"ZOOMIES_DOCKER_HOST=unix:///nonexistent/zoomies-drill-docker.sock",
		"ZOOMIES_AGENT_CAPACITY=2",
		"ZOOMIES_WORK_DIR="+work,
		"ZOOMIES_AGENT_ALLOW_INSECURE_HTTP=true",
		"ZOOMIES_AGENT_RUNNER_DOWNLOAD_URL=http://127.0.0.1:1/never",
	))
}

// hostViews is the fleet's hosts as the API renders them, which is where a
// backend says whether it is usable and why not.
func (f *fleet) hostViews() []hostView {
	f.t.Helper()
	var out struct {
		Items []hostView `json:"items"`
	}
	f.api.get("/hosts", &out)
	return out.Items
}

type hostView struct {
	ID          string            `json:"id"`
	Name        string            `json:"name"`
	Labels      map[string]string `json:"labels"`
	BackendInfo []struct {
		Kind      string `json:"kind"`
		Available bool   `json:"available"`
		Endpoint  string `json:"endpoint"`
		Detail    string `json:"detail"`
	} `json:"backend_info"`
}

// problems is the problems drawer's own list, which is where an operator meets
// a pool that cannot place anything.
func (f *fleet) problems() []problemView {
	f.t.Helper()
	var out struct {
		Items []problemView `json:"items"`
	}
	f.api.get("/problems", &out)
	return out.Items
}

type problemView struct {
	Code     string `json:"code"`
	Severity string `json:"severity"`
	Title    string `json:"title"`
	Detail   string `json:"detail"`
	Fix      string `json:"fix"`
}

// restartAgent starts the agent again as the host it already is, which is what
// an operator's `systemctl restart zoomies-agent` does.
func (f *fleet) restartAgent() {
	f.t.Helper()
	f.agent = f.spawn("agent", []string{"agent"}, f.agentEnv)
}

// spawn starts the built binary and keeps its output for the failure message.
func (f *fleet) spawn(name string, args, env []string) *process {
	t := f.t
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	cmd := exec.CommandContext(ctx, builtBinary(), args...)
	cmd.Env = env
	p := &process{name: name, cmd: cmd, stop: cancel, done: make(chan struct{})}
	cmd.Stdout, cmd.Stderr = &syncWriter{p: p}, &syncWriter{p: p}
	if err := cmd.Start(); err != nil {
		cancel()
		t.Fatalf("starting the %s: %v", name, err)
	}
	go func() {
		_ = cmd.Wait()
		close(p.done)
	}()
	t.Cleanup(func() {
		cancel()
		<-p.done
		if t.Failed() {
			t.Logf("%s output:\n%s", name, p.output())
		}
	})
	return p
}

type syncWriter struct{ p *process }

func (w *syncWriter) Write(b []byte) (int, error) {
	w.p.mu.Lock()
	defer w.p.mu.Unlock()
	return w.p.logs.Write(b)
}

// baseEnv is what both binaries need: a state and config directory of their
// own, and nothing inherited that could point them somewhere real.
func baseEnv(dir string) []string {
	return []string{
		"PATH=" + os.Getenv("PATH"),
		"HOME=" + dir,
		"ZOOMIES_STATE_DIR=" + dir,
		"ZOOMIES_CONFIG_DIR=" + dir,
		"ZOOMIES_LOG_FORMAT=text",
		"ZOOMIES_LOG_LEVEL=debug",
		// The fake GitHub a drill writes onto its installation is on loopback,
		// which the API refuses unless told this is a network the operator
		// owns -- as it is.
		"ZOOMIES_ALLOW_PRIVATE_EGRESS=true",
	}
}

// deliverJob posts a signed workflow_job webhook, the way GitHub drives a
// controller in production.
//
// The fallback poller only finds *queued* jobs -- it is the webhook's backstop,
// not a second channel -- so a drill that only added jobs to the fake would
// watch a runner sit idle until its timeout and never see the job it was made
// for. Delivering the webhook is what makes the drill exercise the path a real
// installation uses, and it is what puts the timing in the drill's hands: a
// fault drill needs to choose the moment a job starts.
func (f *fleet) deliverJob(action string, job github.QueuedJob, runnerName, conclusion string) {
	f.t.Helper()
	payload := map[string]any{
		"id":            job.ID,
		"run_id":        job.RunID,
		"name":          job.JobName,
		"workflow_name": job.WorkflowName,
		"labels":        job.Labels,
		"status":        action,
		"runner_name":   runnerName,
		"created_at":    job.QueuedAt.Format(time.RFC3339),
		"html_url":      job.HTMLURL,
	}
	if action == "in_progress" || action == "completed" {
		payload["started_at"] = job.QueuedAt.Add(time.Second).Format(time.RFC3339)
	}
	if action == "completed" {
		payload["completed_at"] = job.QueuedAt.Add(2 * time.Second).Format(time.RFC3339)
		payload["conclusion"] = conclusion
	}
	body, err := json.Marshal(map[string]any{
		"action":       action,
		"workflow_job": payload,
		"repository":   map[string]any{"full_name": job.Repo},
		"installation": map[string]any{"id": f.gh.InstallationID()},
	})
	if err != nil {
		f.t.Fatalf("encoding the webhook body: %v", err)
	}

	req, err := http.NewRequest(http.MethodPost, f.baseURL+"/webhooks/github", bytes.NewReader(body))
	if err != nil {
		f.t.Fatalf("building the webhook request: %v", err)
	}
	mac := hmac.New(sha256.New, []byte(drillWebhookSecret))
	mac.Write(body)
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(github.EventTypeHeader, "workflow_job")
	req.Header.Set(github.DeliveryIDHeader, fmt.Sprintf("drill-%d-%s", job.ID, action))
	req.Header.Set(github.SignatureHeader, "sha256="+hex.EncodeToString(mac.Sum(nil)))

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		f.t.Fatalf("delivering the %s webhook: %v", action, err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	if resp.StatusCode >= 300 {
		f.t.Fatalf("delivering the %s webhook: %s\n%s", action, resp.Status, raw)
	}
}

// drillWebhookSecret signs the drill's deliveries. It is a fixed string
// because both ends of the signature are this test.
const drillWebhookSecret = "drill-webhook-secret"

// drillRunnerSize is what one drill runner is charged on the host it lands on.
//
// Every drill says it, rather than taking the fleet's default, because the
// default is two cores and four gigabytes -- the whole of the 2 vCPU, 4 GB
// machine CI runs these on. A host with no room for one runner of a pool
// places nothing, so an unsized drill pool fails every drill in the same
// unhelpful way: a timeout waiting for a runner that the fleet was right to
// refuse. These are the smallest figures a pool is allowed to ask for, which
// is the right size for a runner that sleeps: what the drills are about is the
// lifecycle, not the arithmetic, and both of the agent's slots have to fit on
// the smallest machine any of this runs on.
var drillRunnerSize = map[string]any{"cpus": 0.25, "memory_mb": 512}

// createPoolOn makes a pool on a named backend, kept to the hosts a selector
// picks out. The runner version is pinned to the staged stub either way: a pool
// that went looking for a download would hang rather than say what is wrong
// with the host.
//
// The selector is not optional decoration. A drill about one host's fault has
// to be able to say which host it means, or the fleet's other machine answers
// for it and the fault is never met.
func (f *fleet) createPoolOn(name, backend string, selector map[string]string, labels ...string) string {
	f.t.Helper()
	var pool struct {
		ID string `json:"id"`
	}
	f.api.post("/pools", map[string]any{
		"installation_id": f.installationID,
		"name":            name,
		"labels":          labels,
		"backend":         backend,
		"host_selector":   selector,
		"resources":       drillRunnerSize,
		"min_runners":     0,
		"max_runners":     1,
		"idle_timeout":    "1m",
		"ephemeral":       true,
		"runner_version":  stubVersion,
	}, &pool)
	if pool.ID == "" {
		f.t.Fatal("the pool came back without an ID")
	}
	return pool.ID
}

// createPool makes a pool on the process backend, pinned to the staged stub.
func (f *fleet) createPool(name string, labels ...string) string {
	f.t.Helper()
	var pool struct {
		ID string `json:"id"`
	}
	f.api.post("/pools", map[string]any{
		"installation_id": f.installationID,
		"name":            name,
		"labels":          labels,
		"backend":         "process",
		"resources":       drillRunnerSize,
		"min_runners":     0,
		"max_runners":     1,
		"idle_timeout":    "1m",
		"ephemeral":       true,
		"runner_version":  stubVersion,
	}, &pool)
	if pool.ID == "" {
		f.t.Fatal("the pool came back without an ID")
	}
	return pool.ID
}

// runners is the controller's view, including the ones it has finished with.
func (f *fleet) runners(poolID string) []runnerView {
	f.t.Helper()
	var out struct {
		Items []runnerView `json:"items"`
	}
	f.api.get("/runners?include_removed=true&pool_id="+poolID, &out)
	return out.Items
}

type runnerView struct {
	ID          string `json:"id"`
	Name        string `json:"name"`
	State       string `json:"state"`
	JobsHandled int    `json:"jobs_handled"`
	ContainerID string `json:"container_id"`
}

// registeredWithGitHub reports whether the fake holds a registration under one
// name. Naming the runner matters: a drill that counted registrations would be
// racing whatever replacement the scheduler is entitled to create.
func (f *fleet) registeredWithGitHub(name string) bool {
	for _, r := range f.gh.Runners() {
		if r.Name == name {
			return true
		}
	}
	return false
}

// runnerDir is where the process backend laid a runner out. The backend's
// handle is the directory itself, so this is the same path it reports.
func (f *fleet) runnerDir(name string) string {
	return filepath.Join(f.agentWork, "runners", name)
}

// liveWorkloads is what is actually on the host: the process backend's handle
// is the runner's directory, so a directory with the stub's marker in it is a
// workload that really started.
func (f *fleet) liveWorkloads() []string {
	f.t.Helper()
	entries, err := os.ReadDir(filepath.Join(f.agentWork, "runners"))
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		f.t.Fatalf("reading the agent's runner directory: %v", err)
	}
	var live []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		dir := filepath.Join(f.agentWork, "runners", e.Name())
		if _, err := os.Stat(startedMarker(dir)); err == nil {
			live = append(live, e.Name())
		}
	}
	return live
}

// workloadRunning reports whether the runner's process is actually alive,
// which is a different question from whether its directory is still there.
//
// A fault drill has to ask the sharper one: the marker file the stub writes
// outlives the process that wrote it, so a runner killed along with its agent
// leaves a directory that looks exactly like a running one.
func (f *fleet) workloadRunning(name string) bool {
	f.t.Helper()
	raw, err := os.ReadFile(filepath.Join(f.runnerDir(name), "runner.pid"))
	if err != nil {
		return false
	}
	pid, err := strconv.Atoi(strings.TrimSpace(string(raw)))
	if err != nil || pid <= 0 {
		return false
	}
	proc, err := os.FindProcess(pid)
	if err != nil {
		return false
	}
	// Signal 0 asks the kernel whether the process is there without touching
	// it, which is the only way to tell a live runner from a dead one's
	// leftovers.
	return proc.Signal(syscall.Signal(0)) == nil
}

// requireStillRunning fails unless the runner's process is alive now and stays
// alive for a moment.
//
// The moment is the point. A death that follows the agent's own -- a parent
// death signal, a killed process group -- arrives a beat later, so an
// assertion made the instant after the fault would be satisfied by a process
// that is already doomed.
func (f *fleet) requireStillRunning(name, why string) {
	f.t.Helper()
	deadline := time.Now().Add(waitStaysUp)
	for time.Now().Before(deadline) {
		if !f.workloadRunning(name) {
			f.t.Fatalf("the runner process is gone: %s", why)
		}
		time.Sleep(200 * time.Millisecond)
	}
}

