type apiClient struct {
	t    *testing.T
	base string
	// token is sent as a bearer credential when set. Most drills run with
	// authentication off; the bootstrap drill is the one whose point is that
	// it is on and the provisioner still gets in.
	token string
}

func (c *apiClient) do(method, path string, body, out any) {
	c.t.Helper()
	var r io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			c.t.Fatalf("marshalling the request body: %v", err)
		}
		r = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, c.base+path, r)
	if err != nil {
		c.t.Fatalf("building the request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		c.t.Fatalf("%s %s: %v", method, path, err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	if resp.StatusCode >= 300 {
		c.t.Fatalf("%s %s: %s\n%s", method, path, resp.Status, raw)
	}
	if out != nil && len(raw) > 0 {
		if err := json.Unmarshal(raw, out); err != nil {
			c.t.Fatalf("%s %s: decoding the response: %v\n%s", method, path, err, raw)
		}
	}
}

func (c *apiClient) get(path string, out any)        { c.do(http.MethodGet, path, nil, out) }
func (c *apiClient) post(path string, body, out any) { c.do(http.MethodPost, path, body, out) }

func builtBinary() string {
	dir, err := os.Getwd()
	if err != nil {
		return "zoomies"
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "zoomies")
		}
		dir = filepath.Dir(dir)
	}
	return "zoomies"
}

// requireBinary refuses to run rather than skipping: this tier exists to be
// the thing that cannot quietly not happen.
func requireBinary(t *testing.T) {
	t.Helper()
	if _, err := os.Stat(builtBinary()); err != nil {
		t.Fatalf("the zoomies binary is not at %s; run `make build-nogui` first", builtBinary())
	}
}

func waitFor(t *testing.T, limit time.Duration, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(limit)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(200 * time.Millisecond)
	}
	t.Fatalf("timed out after %s waiting for %s", limit, what)
}

func freePort(t *testing.T) int {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("finding a free port: %v", err)
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

// generateAppKey mints an RSA key for the fake's App.
//
// It is generated rather than checked in: the API parses the key to mint a JWT
// with it, so a placeholder string would be refused at the door, and a real
// key in the repository is a key somebody has to explain.
func generateAppKey(t *testing.T) string {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatalf("generating an app key: %v", err)
	}
	return string(pem.EncodeToMemory(&pem.Block{
		Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key),
	}))
}

var _ = store.RunnerIdle // the state names the drills assert on

// runnerSessions counts the usage ledger's sessions for one runner, read
// straight from the controller's database. There is no route for the
// sessions, and a drill asserting on the ledger should not need one: opening
// read-only neither migrates nor writes, so it cannot disturb the controller
// that owns the file.
func (f *fleet) runnerSessions(id string) int {
	f.t.Helper()
	s, err := store.Open(context.Background(), store.Options{Path: filepath.Join(f.stateDir, "zoomies.db"), ReadOnly: true})
	if err != nil {
		f.t.Fatalf("opening the controller's database read-only: %v", err)
	}
	defer s.Close()
	all, err := s.RunnerSessions(context.Background(), time.Unix(0, 0), time.Now().Add(time.Hour))
	if err != nil {
		f.t.Fatalf("reading runner sessions: %v", err)
	}
	n := 0
	for _, x := range all {
		if x.RunnerID == id {
			n++
		}
	}
	return n
}

//go:build drill

package drill

import (
	"net/http"
	"testing"
)

// The third fault drill: GitHub refuses to mint runner configurations.
//
// This is the fault with the least to see and the most to get wrong. A runner
// is registered by asking GitHub for a just-in-time configuration, and that
// call failing is not a fleet problem, a host problem or a pool problem --
// there is nothing wrong with any of them, and there is nothing an operator
// can do but wait. So the two things that matter are that the fleet does not
// make it worse (no half-built runner left on the host, no registration left
// on GitHub, no runaway retry against an endpoint that is already unhappy) and
// that it comes back on its own, without anybody restarting anything.
func TestAFailingJITEndpointLeavesNothingBehindAndRecovers(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "jit-endpoint")
	defer rec.write()

	label := "drill-jit"
	poolID := f.createPool("drill-jit", label)

	// The fault is injected before there is any work, so the very first
	// attempt meets it: a drill that broke the endpoint afterwards would be
	// testing a retry rather than a start.
	rec.faultInjected("the just-in-time configuration endpoint answers 500")
	f.gh.SetError("generate-jitconfig", http.StatusInternalServerError, "the drill broke this on purpose")

	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	// The fleet tries, and says so on the runner rather than silently doing
	// nothing: an operator looking at this pool has to be able to see that
	// something was attempted and what refused it.
	waitFor(t, waitRunnerCreated, "the fleet to try to create a runner", func() bool {
		return len(f.runners(poolID)) > 0
	})
	waitFor(t, waitRunnerCreated, "the attempt to be recorded as failed", func() bool {
		for _, r := range f.runners(poolID) {
			if r.State == "failed" {
				return true
			}
		}
		return false
	})
	rec.note("first attempt", "failed, as the endpoint refuses")

	// Nothing was left behind by the attempt. This is the half that would hurt
	// silently: a directory on the host nobody owns, or a registration on
	// GitHub for a runner that never existed.
	if live := f.liveWorkloads(); len(live) != 0 {
		t.Errorf("the host holds %v after a registration that never succeeded; a failed start must not leave a workload", live)
	}
	if got := f.gh.Runners(); len(got) != 0 {
		t.Errorf("GitHub holds %d registration(s) after a failed configuration; there is nothing there to register", len(got))
	}
	rec.note("left behind by the failure", "nothing on the host, nothing on GitHub")

	// GitHub recovers. Nothing is restarted and nothing is asked again by
	// hand: the fleet is expected to try again by itself, which is the whole
	// claim of a drill about a transient fault.
	f.gh.ClearErrors()
	waitFor(t, waitRecovery, "a workload to appear once the endpoint is back", func() bool {
		return len(f.liveWorkloads()) == 1
	})
	rec.recovered()
	rec.note("recovered by itself", f.liveWorkloads()[0])

	// And the job it was all for actually runs.
	var runner runnerView
	waitFor(t, waitRunnerCreated, "the fleet to have a runner that is not the failed one", func() bool {
		for _, r := range f.runners(poolID) {
			if r.State != "failed" {
				runner = r
				return true
			}
		}
		return false
	})
	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}
	waitFor(t, waitRunnerGone, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	rec.note("job run after the recovery", runner.Name)
	rec.pass("a refused runner configuration failed the attempt without leaving a workload or a registration behind, and the fleet placed a runner by itself once GitHub answered again")
}

//go:build drill

package drill

import (
	"testing"
	"time"
)

// The lifecycle drill: a queued job becomes a real process on this machine,
// and everything is taken away again afterwards.
//
// This is the one that runs on every pull request, and it is the first thing
// in this repository that qualifies the product as an operator gets it. Every
// other test builds a controller in the test process and calls its methods.
// Here the controller is the built binary, the agent is a second copy of that
// binary on the other end of a socket having joined with a token, and the
// backend puts a process on the host. The only fake is GitHub.
//
// What it is really pinning is the seam nothing else can: that the decision the
// scheduler makes actually reaches a host, that the host does something real
// with it, and that the fleet's own accounting agrees with the world afterwards
// -- on GitHub's side and on the host's.
func TestAQueuedJobBecomesARealWorkloadAndIsCleanedUp(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "lifecycle")
	defer rec.write()

	label := "drill-lifecycle"
	poolID := f.createPool("drill", label)

	// GitHub has work. The controller finds it by polling, because a fake
	// cannot deliver a webhook to a process behind no address.
	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	// 1. The fleet decides to create a runner, and the remote agent gets it.
	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner to be created for the pool", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	rec.note("runner created", runner.Name)

	// 2. A real process appears on this host. This is the assertion the whole
	//    tier exists for: not "the row says provisioning" but "there is a
	//    workload, laid out by the backend, running."
	waitFor(t, waitWorkloadUp, "a workload to appear on the host", func() bool {
		return len(f.liveWorkloads()) == 1
	})
	rec.note("workload on host", f.liveWorkloads()[0])

	// 3. And GitHub has the registration the runner was minted with.
	waitFor(t, waitWorkloadUp, "the runner to be registered with GitHub", func() bool {
		return len(f.gh.Runners()) == 1
	})
	registered := f.gh.Runners()[0]
	if registered.Name != runner.Name {
		t.Errorf("GitHub registered %q but the fleet made %q; the names must match or nothing can be reconciled",
			registered.Name, runner.Name)
	}

	// 4. The job runs and finishes. A stub runner does not talk to GitHub, so
	//    the drill drives both sides: the fake's state, and the webhook GitHub
	//    would have sent. That is what makes a fault drill possible at all --
	//    the timing is ours.
	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	waitFor(t, waitJobDone, "the fleet to see the job start", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID && (r.State == "busy" || r.State == "draining" || r.State == "removed") {
				return true
			}
		}
		return false
	})
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	// The runner is ephemeral, so the real one would exit here of its own
	// accord. Telling the stub to do the same is what makes step 5 a test of
	// Zoomies noticing rather than of Zoomies tearing something down.
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}

	// 5. The runner goes away by itself, because it is ephemeral.
	waitFor(t, waitRunnerGone, "the runner to reach a terminal state", func() bool {
		for _, r := range f.runners(poolID) {
			if r.ID == runner.ID {
				return r.State == "removed" || r.State == "failed"
			}
		}
		return false
	})
	final := f.runnerByID(runner.ID, poolID)
	if final.State != "removed" {
		t.Errorf("runner ended in state %q, want removed", final.State)
	}
	rec.note("runner terminal state", final.State)

	// 6. The two checks that make this a drill rather than an assertion about
	//    Zoomies' own opinion of itself. They are asserted separately, and the
	//    registration one is asserted *promptly*, for a reason worth spelling
	//    out.
	//
	//    On *this* path the registration check cannot be tight, and it is worth
	//    saying why rather than writing a sharp-looking assertion that is not.
	//    An ephemeral runner that finishes its job exits by itself; the agent
	//    reports it gone and applyRunnerState marks the row removed, which does
	//    not delete anything on GitHub. Nothing needs to, because real GitHub
	//    removes a just-in-time runner's registration itself once it has run
	//    its one job. The fake does not model that, so what clears it here is
	//    the reaper's sweep -- the backstop, a minute in.
	//
	//    So this asserts the weaker true thing: the fleet does not leave a
	//    registration behind for ever. TestRemovingARunnerDeletesItsRegistration
	//    is where the sharp version lives, on the path where deleting it really
	//    is Zoomies' job.
	waitFor(t, waitRunnerGone, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	rec.note("host workloads after cleanup", "0")

	waitFor(t, waitRunnerGone, "GitHub to hold no registration for this run", func() bool {
		return len(f.gh.Runners()) == 0
	})
	rec.note("github registrations after cleanup", "0")
	rec.pass("a queued job became a real process on this host and everything was cleaned up")
}

// runnerByID re-reads one runner from the controller.
func (f *fleet) runnerByID(id, poolID string) runnerView {
	f.t.Helper()
	for _, r := range f.runners(poolID) {
		if r.ID == id {
			return r
		}
	}
	f.t.Fatalf("runner %s is no longer listed", id)
	return runnerView{}
}

