package drill

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// A row in the drill record is a claim that a named commit was proven to do
// something. Four rows in that file once claimed a commit passed a drill it
// reliably fails, because the runs had used an older build and the row was
// stamped from `git rev-parse HEAD` rather than from the binary.
//
// So the binary is asked, and where the answer might still not describe what
// ran, the row says so instead of asserting.
func TestTheRecordNamesTheBinaryItRanNotTheCheckout(t *testing.T) {
	stamp, caveat := provenance(builtBinary())
	if stamp == "" {
		t.Fatal("a row would be written with no commit at all")
	}
	// This tier refuses to run without a built binary, so the stamp here is
	// the real one and the caveat says whether it can be trusted.
	t.Logf("stamp=%q caveat=%q", stamp, caveat)

	if got := builtCommit(builtBinary()); got == "" {
		t.Error("the binary did not report the commit it was built from, so every row falls back to the checkout")
	}
}

// The stale build is the case that produced the false rows, and it is the one
// worth holding: a binary that is not this commit has to be called out.
func TestAStaleBinaryIsCalledOutRatherThanStamped(t *testing.T) {
	// A stand-in binary that reports a commit no checkout is on.
	dir := t.TempDir()
	fake := filepath.Join(dir, "zoomies")
	script := "#!/bin/sh\nprintf '{\"commit\":\"0000000\"}\\n'\n"
	if err := os.WriteFile(fake, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}

	stamp, caveat := provenance(fake)
	if stamp != "0000000" {
		t.Errorf("the row was stamped %q; it must name the commit the binary reports", stamp)
	}
	if !strings.Contains(caveat, "rebuild") {
		t.Errorf("a binary built from another commit produced the caveat %q; it has to tell somebody to rebuild", caveat)
	}
}

// A binary that says nothing must not be silently attributed to the checkout.
func TestABinaryThatNamesNoCommitSaysSo(t *testing.T) {
	dir := t.TempDir()
	mute := filepath.Join(dir, "zoomies")
	if err := os.WriteFile(mute, []byte("#!/bin/sh\nexit 1\n"), 0o755); err != nil {
		t.Fatal(err)
	}

	_, caveat := provenance(mute)
	if !strings.Contains(caveat, "may not be about the code that ran") {
		t.Errorf("a binary reporting no commit produced the caveat %q", caveat)
	}
}

//go:build drill

package drill

import (
	"io"
	"net/http"
	"strings"
	"testing"
	"time"
)

// The fourth fault drill: GitHub takes the installation's quota away.
//
// A rate limit is the fault most likely to happen to a real fleet and the one
// least visible from inside it: nothing has crashed, nothing is misconfigured,
// and the fleet simply stops doing anything. That is why the product answers
// it with a stand-down that is *visible* -- a gauge per installation, so an
// operator watching a fleet that has gone quiet can tell "out of quota" from
// "nothing to do", which no other series here distinguishes.
//
// The drill's claim is the pair: the fleet holds off while the quota is gone,
// and it starts again by itself when the reset passes. The second half is what
// nothing in process can prove, because the hold is a wall-clock deadline the
// controller keeps for itself.
func TestARateLimitedInstallationStandsDownAndComesBack(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "rate-limit")
	defer rec.write()

	label := "drill-rate-limit"
	poolID := f.createPool("drill-quota", label)

	// A 403 with the rate-limit headers is how GitHub says it, and the reset
	// is put a few seconds out so the drill can watch the recovery rather than
	// the fifteen-minute backoff a limit with no reset would earn.
	reset := time.Now().Add(10 * time.Second)
	rec.faultInjected("GitHub answers 403 with no quota remaining")
	f.gh.SetRateLimit(5000, 0, reset)
	f.gh.SetError("", http.StatusForbidden, "API rate limit exceeded for installation")

	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	// The stand-down is per installation and it is on the scrape, which is the
	// only place it shows: a fleet holding off looks exactly like an idle one
	// everywhere else.
	waitFor(t, waitRecovery, "the controller to report the installation as paused", func() bool {
		return f.gaugeIsOne("zoomies_github_paused")
	})
	rec.note("stand-down visible on /metrics", "zoomies_github_paused is 1")

	if live := f.liveWorkloads(); len(live) != 0 {
		t.Errorf("the host holds %v while GitHub is refusing every call; a fleet out of quota must not spend it starting runners it cannot register", live)
	}

	// The quota comes back. Nothing is restarted: the hold is a deadline the
	// controller keeps for itself, and passing it is the whole test.
	f.gh.ClearErrors()
	f.gh.SetRateLimit(5000, 5000, time.Now().Add(time.Hour))
	waitFor(t, waitRecovery, "a workload to appear once the quota is back", func() bool {
		return len(f.liveWorkloads()) == 1
	})
	rec.recovered()
	rec.note("recovered by itself", f.liveWorkloads()[0])

	waitFor(t, waitRecovery, "the installation to stop being reported as paused", func() bool {
		return !f.gaugeIsOne("zoomies_github_paused")
	})
	rec.note("stand-down cleared", "zoomies_github_paused is 0")

	// And the job it was all for runs.
	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner that is not one of the failed attempts", func() bool {
		for _, r := range f.runners(poolID) {
			if r.State != "failed" {
				runner = r
				return true
			}
		}
		return false
	})
	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}
	waitFor(t, waitRunnerGone, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	rec.pass("an installation out of quota was held off and said so on its scrape, then came back by itself when the reset passed and ran the job")
}

// gaugeIsOne reports whether any sample of a gauge is 1 on the controller's own
// scrape.
//
// The scrape rather than the API on purpose: this is the signal an operator's
// monitoring actually watches, and a stand-down that is only visible to a
// reader of the logs is not visible at all.
func (f *fleet) gaugeIsOne(name string) bool {
	f.t.Helper()
	resp, err := http.Get(f.baseURL + "/metrics")
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(body), "\n") {
		if strings.HasPrefix(line, name) && strings.HasSuffix(strings.TrimSpace(line), " 1") {
			return true
		}
	}
	return false
}

//go:build drill

package drill

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// A record is one drill's row: what was expected, what happened, how long
// recovery took, whether cleanup was clean, and whether a person has to do
// anything.
//
// It is written whatever the outcome, because a drill that failed is the one
// worth reading. The last column is the one the roadmap actually wants: a
// drill that recovers on its own and a drill that needs somebody to go and
// delete a container are different findings, and only the row can say which.
type record struct {
	t         *testing.T
	name      string
	startedAt time.Time
	notes     []string
	expected  string
	// recoveredAt is set by a fault drill when the fleet is working again, so
	// the row can carry a recovery time rather than a total runtime.
	recoveredAt time.Time
	faultAt     time.Time
	// found is what this drill turned up that a person has to decide about. A
	// drill can pass and still have found something -- that is most of what
	// they are for -- and until this existed the record could only say "none"
	// or "something crashed, go and look".
	found string
}

func newRecord(t *testing.T, name string) *record {
	t.Helper()
	return &record{t: t, name: name, startedAt: time.Now()}
}

// note records an observation, in the order they happened, stamped with how
// far into the drill it was.
//
// The elapsed time is not decoration. A drill can pass for the wrong reason --
// a slower backstop tidying up after the path under test failed to -- and the
// first sign of that is a step taking far longer than it should. The row
// carries the timings so that a pass which quietly became a different pass is
// visible.
func (r *record) note(what, value string) {
	r.notes = append(r.notes, fmt.Sprintf("%s @%s: %s", what,
		time.Since(r.startedAt).Round(100*time.Millisecond), value))
}

// pass states what the drill was expected to show. It is called at the end
// rather than the start so that the sentence describes what actually held; a
// drill that fails earlier writes its row without one.
func (r *record) pass(expected string) { r.expected = expected }

// finding records what this drill turned up for a person to act on, whatever
// its outcome. It is the last column, and the one the record is read for.
func (r *record) finding(what string) { r.found = what }

// faultInjected and recovered bracket a fault drill's recovery time.
func (r *record) faultInjected(what string) {
	r.faultAt = time.Now()
	r.note("fault injected", what)
}

func (r *record) recovered() { r.recoveredAt = time.Now() }

// write appends the row to the drill record in roadmap/validation/.
//
// One file rather than one per run, because the value of these is the history:
// a drill that has recovered cleanly forty times and then did not is a finding
// that only exists if the forty are there to compare against. Appending is all
// this side does; keeping the file is the workflow's half, and until a run
// commits it the history is one run long.
func (r *record) write() {
	r.t.Helper()
	dir := recordDir()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		r.t.Errorf("creating the drill record directory: %v", err)
		return
	}
	path := filepath.Join(dir, recordFileName)

	outcome := "passed"
	if r.t.Failed() {
		outcome = "FAILED"
	}
	recovery := "n/a"
	if !r.faultAt.IsZero() {
		if r.recoveredAt.IsZero() {
			recovery = "never"
		} else {
			recovery = r.recoveredAt.Sub(r.faultAt).Round(100 * time.Millisecond).String()
		}
	}
	// A drill that failed has left this machine in whatever state it failed
	// in, and saying so is the point of the column.
	human := "none"
	switch {
	case r.t.Failed():
		human = "check for a leftover runner directory under the drill's work dir"
	case r.found != "":
		human = r.found
	}
	expected := r.expected
	if expected == "" {
		expected = "(the drill did not reach its own statement of what it proves)"
	}

	// The commit comes from the binary that ran, and any doubt about whether
	// this row is really about that commit is carried in the same column an
	// operator reads for everything else that was unclear.
	stamp, caveat := provenance(builtBinary())
	if caveat != "" {
		if human == "none" || human == "" {
			human = caveat
		} else {
			human = caveat + "; " + human
		}
	}

	row := fmt.Sprintf("| %s | %s | %s | %s | %s | %s | %s | %s | %s |\n",
		time.Now().UTC().Format(time.RFC3339), stamp, runLink(), r.name, outcome,
		expected, strings.Join(r.notes, "; "), recovery, human)

	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		r.t.Errorf("opening the drill record: %v", err)
		return
	}
	defer f.Close()
	if info, err := f.Stat(); err == nil && info.Size() == 0 {
		if _, err := f.WriteString(recordHeader); err != nil {
			r.t.Errorf("writing the drill record header: %v", err)
			return
		}
	}
	if _, err := f.WriteString(row); err != nil {
		r.t.Errorf("writing the drill record row: %v", err)
	}
}

const recordHeader = `# Drill record

Each row is one run of one drill against the built binary, with a fake GitHub
and a real workload on the machine that ran it. Appended rather than replaced:
a drill that has recovered cleanly forty times and then did not is a finding
that only exists if the forty are there to compare against.

**Human action needed** is the column to read first. A drill that recovers on
its own and one that leaves something for a person to delete are different
findings, and only the row says which. **Run** is where the row came from, so
a row that reads oddly a month later can be taken back to the logs that
produced it; a row written on a developer's machine says so instead.

The rows below are appended by the drill job on every push to the default
branch. A pull request's rows stay in that run's job summary: they describe a
commit that may never exist, and the comparison this file is for is the
default branch against itself.

| When | Commit | Run | Drill | Outcome | What it proves | Observed | Recovery | Human action needed |
| --- | --- | --- | --- | --- | --- | --- | --- | --- |
`

// recordFileName is the evidence log a drill appends to. Named once because
// dirtyTree has to exclude the same file this writes to.
const recordFileName = "drills.md"

func recordDir() string {
	if d := os.Getenv("ZOOMIES_DRILL_RECORD_DIR"); d != "" {
		return d
	}
	return filepath.Join(filepath.Dir(builtBinary()), "roadmap", "validation")
}

// runLink is where this row came from. A row is worth keeping only if it can
// be taken back to the run that wrote it: the observations are a summary, and
// the logs are the rest.
func runLink() string {
	server, repo, id := os.Getenv("GITHUB_SERVER_URL"), os.Getenv("GITHUB_REPOSITORY"), os.Getenv("GITHUB_RUN_ID")
	if server == "" || repo == "" || id == "" {
		return "local"
	}
	return fmt.Sprintf("%s/%s/actions/runs/%s", server, repo, id)
}

// provenance is the commit this row is evidence about, and a caveat when it
// might not be.
//
// It asks the binary rather than git, because the binary is what a drill runs
// and git is only what the checkout happens to be pointing at. Four rows in
// this file once said a commit passed a drill that commit reliably fails: the
// runs had used a build several hours older than the change, and `git
// rev-parse HEAD` cheerfully stamped the commit whose code was never
// executed. A row that asserts something untrue is worse than no row, because
// the whole point of the file is to be the record of what has been proven.
//
// Two ways it can still be wrong, and both are said out loud rather than
// guessed at:
//
//   - the binary was built from a different commit than the checkout is on,
//     which means somebody forgot to rebuild;
//   - the working tree is dirty, so the binary was built from a commit plus
//     changes nobody can name later.
func provenance(bin string) (string, string) {
	built := builtCommit(bin)
	head := headCommit()
	switch {
	case built == "":
		return orUnknown(head), "the binary reported no commit, so this row names the checkout's HEAD and may not be about the code that ran"
	case head != "" && !strings.HasPrefix(head, built) && !strings.HasPrefix(built, head):
		return built, "the checkout is on " + head + ": the binary was built from a different commit, so rebuild before trusting this row"
	case dirtyTree():
		return built, "the working tree was dirty, so the binary is that commit plus changes this row cannot name"
	}
	return built, ""
}

// builtCommit asks the binary what it was built from.
func builtCommit(bin string) string {
	out, err := exec.Command(bin, "version", "--json").Output()
	if err != nil {
		return ""
	}
	var v struct {
		Commit string `json:"commit"`
	}
	if err := json.Unmarshal(out, &v); err != nil {
		return ""
	}
	return strings.TrimSpace(v.Commit)
}

func headCommit() string {
	out, err := exec.Command("git", "rev-parse", "--short", "HEAD").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// dirtyTree reports whether the checkout has changes to the code under test
// that no commit names.
//
// The record itself is excluded, and has to be: a drill appends its row to it,
// so the first drill of a run dirties the tree for every drill after it. The
// first version of this said "the working tree was dirty" on seven rows out of
// eight, all of them because of the file they were being written to. A caveat
// that is nearly always there is one people stop reading, which costs more
// than it was ever going to save.
func dirtyTree() bool {
	out, err := exec.Command("git", "status", "--porcelain", "--", ".",
		":(exclude)*/"+recordFileName).Output()
	if err != nil {
		return false
	}
	return strings.TrimSpace(string(out)) != ""
}

func orUnknown(s string) string {
	if s == "" {
		return "unknown"
	}
	return s
}

//go:build drill

package drill

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The rows are the deliverable, and a row is only useful if it can be taken
// back to the run that wrote it: what the file holds is a summary, and the
// logs are the rest of the story.
func TestARowSaysWhichRunWroteIt(t *testing.T) {
	t.Setenv("GITHUB_SERVER_URL", "https://github.com")
	t.Setenv("GITHUB_REPOSITORY", "eyupio/zoomies")
	t.Setenv("GITHUB_RUN_ID", "12345")

	if got := runLink(); got != "https://github.com/eyupio/zoomies/actions/runs/12345" {
		t.Fatalf("run link = %q, want the run's address", got)
	}
}

// A drill run on a developer's machine has no run to point at, and a link to
// nowhere would be worse than saying so.
func TestARowWrittenOffCISaysSo(t *testing.T) {
	t.Setenv("GITHUB_SERVER_URL", "https://github.com")
	t.Setenv("GITHUB_REPOSITORY", "eyupio/zoomies")
	t.Setenv("GITHUB_RUN_ID", "")

	if got := runLink(); got != "local" {
		t.Fatalf("run link = %q off CI, want it to say the row is local", got)
	}
}

// Appending is the whole design: the value of these rows is the comparison,
// and a writer that replaced the file would leave one run's worth of history
// however many times it ran.
func TestASecondRowLeavesTheFirstWhereItIs(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("ZOOMIES_DRILL_RECORD_DIR", dir)

	first := newRecord(t, "first")
	first.pass("the first thing")
	first.write()
	second := newRecord(t, "second")
	second.pass("the second thing")
	second.write()

	body, err := os.ReadFile(filepath.Join(dir, "drills.md"))
	if err != nil {
		t.Fatalf("reading the record: %v", err)
	}
	if !strings.Contains(string(body), "| first |") {
		t.Fatalf("the first drill's row is gone after a second one was written:\n%s", body)
	}
	if !strings.Contains(string(body), "| second |") {
		t.Fatalf("the second drill's row was not written:\n%s", body)
	}
	if n := strings.Count(string(body), "# Drill record"); n != 1 {
		t.Fatalf("the record carries its header %d times, want once", n)
	}
}

// A row with more cells than the header renders as a table with a column
// nobody can read the name of, and the file is read by people rather than by
// a parser -- so the two have to agree, in the writer and in what it has
// already written.
func TestEveryRowFitsTheHeader(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("ZOOMIES_DRILL_RECORD_DIR", dir)
	fresh := newRecord(t, "fresh")
	fresh.pass("that a row and its header agree")
	fresh.write()

	written, err := os.ReadFile(filepath.Join(dir, "drills.md"))
	if err != nil {
		t.Fatalf("reading the record: %v", err)
	}
	for _, path := range []string{"", filepath.Join("..", "..", "roadmap", "validation", "drills.md")} {
		body := string(written)
		name := "a record this test wrote"
		if path != "" {
			b, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("reading %s: %v", path, err)
			}
			body, name = string(b), path
		}
		want := -1
		for _, line := range strings.Split(body, "\n") {
			if !strings.HasPrefix(line, "| ") || strings.HasPrefix(line, "| --- ") {
				continue
			}
			cells := strings.Count(line, " | ")
			if want < 0 {
				want = cells
				continue
			}
			if cells != want {
				t.Errorf("%s has a row with %d separators where the header has %d:\n%s", name, cells, want, line)
			}
		}
		if want < 0 {
			t.Errorf("%s has no table in it at all", name)
		}
	}
}

//go:build drill

package drill

import (
	"net/http"
	"slices"
	"testing"
)

// Removing a runner must take its GitHub registration with it, promptly.
//
// This is the sharp version of the cleanup assertion, and it needs its own
// drill because the lifecycle path cannot carry it. There, the runner finishes
// its job and exits, the agent reports it gone, and the row is marked removed
// without anything being deleted on GitHub -- correctly, because real GitHub
// removes a just-in-time runner itself once it has run its job.
//
// An operator removing an idle runner is the other case, and the one the
// roadmap named: GitHub will not tidy that up, so if Zoomies does not, the
// organisation's runner list fills with dead entries. Here deleting the
// registration really is removeRunner's job, and the drill holds it to doing so
// well inside the reaper's first sweep -- otherwise the assertion would be
// satisfied by the backstop, which is how the first version of the lifecycle
// drill passed with the deletion commented out.
func TestRemovingARunnerDeletesItsRegistration(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "removal")
	defer rec.write()

	label := "drill-removal"
	poolID := f.createPool("drillrm", label)

	// A queued job is only the way to get a runner made; this drill is about
	// what happens when one is taken away without ever finishing work.
	f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})

	var runner runnerView
	waitFor(t, waitRunnerCreated, "a runner to be created", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	waitFor(t, waitWorkloadUp, "the runner to be registered with GitHub", func() bool {
		return f.registeredWithGitHub(runner.Name)
	})
	rec.note("registered with github", runner.Name)

	// Remove it the way an operator does.
	f.api.do(http.MethodDelete, "/runners/"+runner.ID+"?force=true", nil, nil)
	rec.note("removal requested", runner.Name)

	// Both assertions name the runner that was removed rather than counting
	// what is left, because the job is still queued and the scheduler is right
	// to put a replacement on the host straight away. Counting would have this
	// drill fail on correct behaviour -- and worse, a version of it that waited
	// for zero would pass or fail on which of the two happened first.
	waitFor(t, waitPromptCleanup, "GitHub's registration to be deleted by the removal itself", func() bool {
		return !f.registeredWithGitHub(runner.Name)
	})
	rec.note("github registration after removal", "gone")

	waitFor(t, waitRunnerGone, "the removed runner's workload to be gone from the host", func() bool {
		return !slices.Contains(f.liveWorkloads(), runner.Name)
	})
	rec.note("host workload after removal", "gone")
	rec.pass("removing a runner deleted its GitHub registration without waiting for the reaper")
}

//go:build drill

package drill

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The mechanical half of ZF-203's acceptance: take a backup from a running
// fleet, stop it, restore into a clean state directory, and start a controller
// on what came back.
//
// It is a drill rather than a unit test because every part of it is about the
// product as an operator has it: `zoomies backup` and `zoomies restore` are
// commands run against a database on disk, the controller is a process that
// reads a fence at startup and refuses readiness, and the thing being proved
// is that the file travelled. None of that exists inside the test process.
//
// It now runs a job on the restored fleet too, which is the half Gate F's
// sixth bullet asks for and the half that is easy to skip: a controller that
// answers readiness has proved that it starts, not that it works. The agent is
// never told any of this happened -- it is still polling the address it joined
// -- so a restore that lost the host row or its credentials would leave a
// fleet that looks healthy and can place nothing.
//
// What remains an owner action against a real organisation is the same journey
// against real GitHub, and that is recorded in roadmap/validation/ instead.
func TestABackupCanBeRestoredIntoACleanDirectoryAndComesBackFenced(t *testing.T) {
	f := newFleet(t)
	rec := newRecord(t, "restore")
	defer rec.write()
	// Something worth restoring: a pool this drill made, which is a row the
	// restored database either has or does not.
	label := "drill-restore"
	poolID := f.createPool("drillrestore", label)
	rec.note("created pool", poolID)

	// Taken while the controller is running, which is the case VACUUM INTO
	// exists for: copying the file here would leave the pool in the
	// write-ahead log.
	backups := t.TempDir()
	out := f.run(f.stateDir, "backup", "--dir", backups)
	if !strings.Contains(out, "integrity ok") {
		t.Fatalf("the backup did not check out:\n%s", out)
	}
	src := onlyDir(t, backups)
	rec.note("backed up", filepath.Base(src))

	f.controller.kill()
	rec.note("stopped the controller", "kill")

	// A clean directory: nothing here but the encryption key and what the
	// restore puts in it. The key is the operator's to carry across -- the
	// backup deliberately does not contain it -- and restoring without it is
	// refused, which is a thing this drill proves by having to do the work.
	fresh := t.TempDir()
	carryKey(t, f.stateDir, fresh)
	rec.note("carried the encryption key across", "encryption.key")
	out = f.run(fresh, "restore", src)
	if !strings.Contains(out, "Restored") {
		t.Fatalf("restore did not report success:\n%s", out)
	}
	rec.note("restored", "into a clean state directory")

	f.startControllerOn(fresh)

	// Fenced: serving, and doing nothing. This is the assertion the whole
	// drill exists for -- a restored fleet that came up acting would already
	// have created runners against an organisation whose state it last saw
	// when the backup was taken.
	resp, err := http.Get(f.baseURL + "/readyz")
	if err != nil {
		t.Fatalf("readiness: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusServiceUnavailable {
		t.Errorf("a restored controller answered readiness with %d; want 503 while fenced", resp.StatusCode)
	}
	var ready struct {
		OK     bool   `json:"ok"`
		Fenced bool   `json:"fenced"`
		Reason string `json:"reason"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&ready); err != nil {
		t.Fatalf("decoding the readiness body: %v", err)
	}
	if !ready.Fenced || ready.OK {
		t.Errorf("readiness does not say it is fenced: %+v", ready)
	}
	if !strings.Contains(ready.Reason, filepath.Base(src)) {
		t.Errorf("the reason does not name the backup it came from: %q", ready.Reason)
	}
	rec.note("came back fenced", ready.Reason)

	// The data travelled.
	var pools struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
	}
	f.api.get("/pools", &pools)
	var found bool
	for _, p := range pools.Items {
		if p.ID == poolID {
			found = true
		}
	}
	if !found {
		t.Errorf("the pool created before the backup is not in the restored fleet: %+v", pools.Items)
	}

	// And the fence lifts.
	var lifted struct {
		Fenced bool `json:"fenced"`
	}
	f.api.post("/recovery/unfence", nil, &lifted)
	if lifted.Fenced {
		t.Fatal("the fence did not lift")
	}
	waitFor(t, waitProcessUp, "readiness to come back", func() bool {
		r, err := http.Get(f.baseURL + "/readyz")
		if err != nil {
			return false
		}
		r.Body.Close()
		return r.StatusCode == http.StatusOK
	})
	rec.note("lifted the fence", "the fleet is ready again")

	// And it works: a queued job becomes a runner on the host that was already
	// there. Nothing re-joined the agent -- the restored database carries the
	// host it had when the backup was taken, and the agent is still polling
	// the address it has always polled.
	job := f.gh.AddQueuedJob("acme/api", "CI", "build", []string{"self-hosted", label})
	var runner runnerView
	waitFor(t, waitRunnerCreated, "the restored fleet to create a runner", func() bool {
		for _, r := range f.runners(poolID) {
			runner = r
			return true
		}
		return false
	})
	waitFor(t, waitWorkloadUp, "a workload to appear on the host", func() bool {
		return len(f.liveWorkloads()) == 1
	})
	rec.note("job placed after the restore", runner.Name)

	f.gh.StartJob(job.ID, runner.Name)
	f.deliverJob("in_progress", job, runner.Name, "")
	f.gh.CompleteJob(job.ID, "success")
	f.deliverJob("completed", job, runner.Name, "success")
	if err := finishJob(f.runnerDir(runner.Name)); err != nil {
		t.Fatalf("telling the stub runner its job is over: %v", err)
	}
	waitFor(t, waitRunnerGone, "the workload to be gone from the host", func() bool {
		return len(f.liveWorkloads()) == 0
	})
	rec.recovered()
	rec.note("host workloads after the restored fleet finished the job", "0")
	rec.pass("a backup taken from a running fleet restores into an empty state directory, " +
		"comes back fenced, serves again once the fence is lifted, and runs a job on the host it had before")
}

// carryKey copies the instance encryption key from one state directory to
// another, which is exactly the step docs/backup-and-restore.md tells an
// operator to take by hand.
func carryKey(t *testing.T, from, to string) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(from, "encryption.key"))
	if err != nil {
		t.Fatalf("reading the encryption key the controller generated: %v", err)
	}
	if err := os.WriteFile(filepath.Join(to, "encryption.key"), raw, 0o600); err != nil {
		t.Fatalf("putting the encryption key in place: %v", err)
	}
}

// onlyDir returns the single directory under root.
func onlyDir(t *testing.T, root string) string {
	t.Helper()
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Fatalf("reading %s: %v", root, err)
	}
	var dirs []string
	for _, e := range entries {
		if e.IsDir() {
			dirs = append(dirs, filepath.Join(root, e.Name()))
		}
	}
	if len(dirs) != 1 {
		t.Fatalf("want one directory under %s, found %v", root, dirs)
	}
	return dirs[0]
}

//go:build drill

package drill

import (
	"fmt"
	"os"
	"path/filepath"
)

// The process backend expects an actions/runner release laid out under
// <work-dir>/_tools/<version>/, and skips its download entirely when
// bin/Runner.Listener is already there. That short-circuit is what lets a
// drill run with no network and no real runner: we stage a stub.
//
// A stub is honest here in a way it would not be elsewhere. What this tier
// qualifies is Zoomies -- that the controller decides to create a runner, that
// the task reaches a remote agent, that the backend puts a real process on the
// host with the right layout and environment, and that everything is taken
// away again afterwards. Whether Microsoft's runner binary can talk to GitHub
// is not this repository's behaviour, and putting the real one here would
// trade the whole drill for a download.
//
// What the stub does have to be is a *real process* that stays up until it is
// stopped, because the lifecycle under test is exactly "it is running, then it
// is not". It ends the way a real ephemeral runner ends -- by exiting once its
// job is over -- rather than by being killed, so that what the drill watches
// is Zoomies noticing a workload finished rather than Zoomies tearing one down.
const (
	toolsDirName = "_tools"
	listenerPath = "bin/Runner.Listener"
	// stubVersion is what the pool pins, so the backend looks for the tree we
	// staged rather than the version it would otherwise fetch.
	stubVersion = "2.999.0-drill"
)

// stubRunner is the script staged as Runner.Listener.
//
// It writes a file the drill can watch for, so "the workload started" is
// observed from the host rather than inferred from a Zoomies row, then waits
// to be killed. The trap makes it exit promptly on the backend's TERM, which
// is what a drill measuring recovery time needs.
//
// The trap is installed before that file exists, and the order is the whole
// contract with the drill: a shell that has not installed its handler yet is
// killed outright by the signal, so a drill that signals on the strength of
// the marker must not be able to arrive in between the two. Losing that race
// costs the drill the thing it is there to measure -- cleanup never runs, the
// marker it watches is left behind, and a prompt exit is recorded as a process
// killed by a signal.
const stubRunner = `#!/bin/sh
set -eu
: "${ACTIONS_RUNNER_INPUT_JITCONFIG:=}"
dir="$(cd "$(dirname "$0")/.." && pwd)"
cleanup() { rm -f "$dir/drill-started"; exit 0; }
# TERM is the backend stopping us, which is what a drain or a forced removal
# looks like from in here.
trap cleanup TERM INT
# Record that a real process reached this point, and with what. The drill waits
# for this, so nothing above it may be skippable and nothing below it may be
# needed to handle a signal.
{
  echo "pid=$$"
  echo "jit_present=$([ -n "${ACTIONS_RUNNER_INPUT_JITCONFIG}" ] && echo yes || echo no)"
} > "$dir/drill-started"
# Otherwise wait for the drill to say the job is over, and exit the way an
# ephemeral runner does. The sleep is short and backgrounded so the trap is
# handled promptly rather than after a long uninterruptible sleep.
while [ ! -f "$dir/drill-stop" ]; do
  sleep 0.2 &
  wait $!
done
cleanup
`

// stageStubRunner writes the stub release into an agent's work directory. It
// must run before the agent starts, because the backend looks for the tree the
// first time it is asked to create anything.
func stageStubRunner(workDir string) error {
	dir := filepath.Join(workDir, toolsDirName, stubVersion)
	if err := os.MkdirAll(filepath.Join(dir, "bin"), 0o750); err != nil {
		return fmt.Errorf("staging the stub runner tree: %w", err)
	}
	listener := filepath.Join(dir, listenerPath)
	if err := os.WriteFile(listener, []byte(stubRunner), 0o750); err != nil {
		return fmt.Errorf("writing the stub runner: %w", err)
	}
	// config.sh is only reached on the registration-token path; an ephemeral
	// pool hands over a JIT config instead. Staging it anyway means a drill
	// that deliberately uses a non-ephemeral pool fails on the behaviour it is
	// testing rather than on a missing file.
	config := filepath.Join(dir, "config.sh")
	if err := os.WriteFile(config, []byte("#!/bin/sh\nexit 0\n"), 0o750); err != nil {
		return fmt.Errorf("writing the stub config script: %w", err)
	}
	return nil
}

// startedMarker is the file the stub writes inside a runner's directory. Its
// presence is the drill's evidence that a workload really ran on this host.
func startedMarker(runnerDir string) string {
	return filepath.Join(runnerDir, "drill-started")
}

// finishJob tells the stub its job is over, so it exits as an ephemeral runner
// does. The drill calls this instead of killing anything: what is under test is
// Zoomies noticing a finished workload, and killing it would test the reaper.
func finishJob(runnerDir string) error {
	return os.WriteFile(filepath.Join(runnerDir, "drill-stop"), []byte("done\n"), 0o640)
}

package e2e

import "time"

// The waits the scenario is allowed, and the budget they add up to.
//
// These live in a file with no build tag on purpose. The roadmap found this
// harness with waits totalling twenty-seven minutes behind a Makefile timeout
// of twenty, which means the scenario could never have reached its own last
// assertion: `go test` would have killed it first, and the run would have been
// reported as a timeout rather than as whatever it was actually stuck on. A
// guard for that is worth nothing if it only compiles under the tag that needs
// real GitHub credentials, so budget_test.go runs in ordinary CI and reads the
// number out of the Makefile.
//
// Each wait is generous, because the thing being waited for crosses a real
// network to GitHub and a real image pull. What matters is that their sum
// stays under what the Makefile allows, with room for the cleanup that runs
// after the last one.
const (
	waitControllerHealthy = 30 * time.Second
	waitRunnerCreated     = 5 * time.Minute
	waitRunnerRegistered  = 4 * time.Minute
	waitJobCompleted      = 8 * time.Minute
	waitRunnerDestroyed   = 4 * time.Minute
	// waitCleanup is the ledger's, not the scenario's: it runs after the
	// scenario has finished or failed, and it is the part that must not be cut
	// short, because what it is doing is deleting a pool and an installation
	// from somebody's real organisation.
	waitCleanup = 2 * time.Minute
)

// The installer scenario's waits. It creates nothing on GitHub and pulls one
// small base image rather than a runner image, so it is much the cheaper of
// the two -- but it still crosses a registry, and a machine that has never
// pulled the image pays for that once.
const (
	waitInstallerImage = 3 * time.Minute
	// waitInstalledControllerHealthy is longer than the other scenario's
	// equivalent because this controller is starting for the first time on a
	// fresh database, so it migrates before it listens.
	waitInstalledControllerHealthy = 90 * time.Second
	// waitInstallerSteps covers `zoomies init` and `zoomies uninstall`: making
	// an account, writing the files, creating the administrator, and taking it
	// all off again.
	waitInstallerSteps = 3 * time.Minute
)

// installerBudget is the longest the installer scenario may legitimately take.
const installerBudget = waitInstallerImage + waitInstalledControllerHealthy + waitInstallerSteps

// scenarioBudget is the longest the GitHub scenario may legitimately take,
// cleanup included.
const scenarioBudget = waitControllerHealthy + waitRunnerCreated + waitRunnerRegistered +
	waitJobCompleted + waitRunnerDestroyed + waitCleanup

// totalBudget is what one `go test` invocation may need, because the
// scenarios run in the same binary under one -timeout. Adding a scenario and
// forgetting this is how a suite starts being killed partway through its
// second one and reporting a timeout rather than a result.
const totalBudget = scenarioBudget + installerBudget

package e2e

import (
	"os"
	"path/filepath"
	"regexp"
	"testing"
	"time"
)

// The harness's waits must fit inside the timeout the Makefile gives it.
//
// "The harness's" means every scenario's, summed: they run in one test binary
// under one -timeout, so a suite whose scenarios each fit but whose total does
// not is killed partway through the last one.
//
// They did not: the scenario asked for twenty-seven minutes of waiting behind
// `-timeout 20m`, so it could never have reached its own last assertion. A run
// that was going to fail on a leftover registration would have been reported
// as a timeout instead, which is the worst kind of red -- it names nothing.
//
// This test has no build tag, so it runs on every ordinary `go test ./...`
// rather than only when somebody has real GitHub credentials.
func TestTheScenarioFitsInsideTheMakefilesTimeout(t *testing.T) {
	root := repoRootFrom(t)
	raw, err := os.ReadFile(filepath.Join(root, "Makefile"))
	if err != nil {
		t.Fatalf("reading the Makefile: %v", err)
	}

	// Every e2e target's -timeout, so adding one cannot quietly skip this.
	re := regexp.MustCompile(`(?m)^\s+\$\(GO\) test .*-tags e2e.*-timeout (\S+)`)
	matches := re.FindAllStringSubmatch(string(raw), -1)
	if len(matches) == 0 {
		t.Fatal("no `go test -tags e2e ... -timeout` line found in the Makefile; " +
			"if the target was renamed, update this test rather than deleting it")
	}
	for _, m := range matches {
		limit, err := time.ParseDuration(m[1])
		if err != nil {
			t.Fatalf("the Makefile's e2e timeout %q is not a duration: %v", m[1], err)
		}
		if limit <= totalBudget {
			t.Errorf("the Makefile allows %s but the scenarios' waits and cleanup need %s "+
				"(%s for the GitHub scenario, %s for the installer); "+
				"the suite would be killed before its own last assertion",
				limit, totalBudget, scenarioBudget, installerBudget)
		}
	}
}

// repoRootFrom walks up to the directory holding go.mod. It is duplicated from
// the tagged half of this package rather than shared, because this test has to
// compile without the e2e tag and that half does not.
func repoRootFrom(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		dir = filepath.Dir(dir)
	}
	t.Fatal("could not find the repository root from the test's working directory")
	return ""
}

// Package e2e holds the Docker-based end-to-end test. It is behind the "e2e"
// build tag and additionally skips itself unless the GitHub credentials it
// needs are present, so `go test ./...` on a laptop or in CI never tries to
// talk to GitHub.
//
// See README.md in this directory for what it asserts and how to run it.
package e2e

//go:build e2e

package e2e

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"math/rand/v2"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This test proves the whole product works end to end: a real controller, a
// real GitHub App, a real workflow run, a real container.
//
// See README.md in this directory for the environment it needs, and result.go
// for the vocabulary it reports in. The two things to know before reading it:
// nothing is created until every prerequisite has been checked, and everything
// created is written to a ledger outside the temp directory before it exists,
// so a run killed at any point leaves a record of what to go and remove.

const scenarioName = "ephemeral_runner_runs_a_real_job"

func TestEphemeralRunnerRunsARealJob(t *testing.T) {
	runID := newRunID()
	label := "zoomies-e2e-" + runID
	res := &Result{
		Scenario: scenarioName, RunID: runID, Commit: commit(),
		StartedAt: time.Now(), Category: NotRun,
	}
	t.Cleanup(func() {
		// A run nobody asked for writes nothing. Every result file carries the
		// run id in its name, so recording "not_run" on each invocation would
		// pile up a file per `make test-e2e` on a laptop, and none of them
		// would say anything: not_run is for a scenario a real run left out,
		// not for a run that was never requested.
		if !requested() {
			return
		}
		res.FinishedAt = time.Now()
		if err := res.write(resultsDir(t)); err != nil {
			t.Errorf("writing the result record: %v", err)
		}
	})

	if !requested() {
		t.Skip("set ZOOMIES_E2E=1 to run the end-to-end test; see test/e2e/README.md")
	}

	e, missing := preflight()
	if len(missing) > 0 {
		res.Category, res.Reason = Blocked, strings.Join(missing, "; ")
		if required() {
			// In required mode a prerequisite that is not there is a finding,
			// not a shrug. This is the difference between a gate that means
			// something and one that goes green having done nothing.
			t.Fatalf("blocked: %s", res.Reason)
		}
		t.Skipf("blocked: %s", res.Reason)
	}

	// The sweep runs before this run creates anything, so its findings belong
	// to earlier runs and cannot be confused with this one's.
	res.SweptFromEarlierRuns = sweep(t, runID, e)

	ledger, err := openLedger(runID, label, e)
	if err != nil {
		res.Category, res.Reason = Blocked, fmt.Sprintf("the ledger could not be opened: %v", err)
		t.Fatal(res.Reason)
	}
	// The controller starts before this cleanup is registered, so that cleanup
	// order puts them the right way round: t.Cleanup runs last-registered
	// first, and tidying up has to happen while the API it deletes through is
	// still listening.
	base := controller(t)
	api := &client{t: t, base: base + "/api/v1"}

	// Cleanup runs however the test ends, and it is the only place that
	// removes what this run made. Anything it cannot remove is recorded on the
	// result rather than dropped, because it is sitting on a real organisation.
	t.Cleanup(func() {
		tidyUp(t, ledger, e, label, base)
		res.ResidualCleanup = ledger.outstanding()
		if len(res.ResidualCleanup) == 0 {
			if err := ledger.close(); err != nil {
				t.Errorf("closing the ledger: %v", err)
			}
		}
		if res.Category == NotRun && !t.Failed() {
			res.Category = Passed
		}
		if t.Failed() && res.Category != Blocked {
			res.Category = Failed
			if res.Reason == "" {
				res.Reason = "an assertion failed; see the test output"
			}
		}
	})

	// 1. Connect the GitHub App.
	var inst struct {
		ID string `json:"id"`
	}
	api.post("/installations", map[string]any{
		"app_id":          mustInt(t, e.appID),
		"installation_id": mustInt(t, e.installationID),
		"target":          e.target,
		"target_type":     e.targetType,
		"private_key":     e.privateKey,
	}, &inst)
	if inst.ID == "" {
		t.Fatal("the installation was created but came back without an ID")
	}
	if err := ledger.created("installation", inst.ID); err != nil {
		t.Fatalf("recording the installation in the ledger: %v", err)
	}

	// 2. It must verify, or nothing else can work.
	var health struct {
		OK                 bool     `json:"ok"`
		Message            string   `json:"message"`
		MissingPermissions []string `json:"missing_permissions"`
	}
	api.post("/installations/"+inst.ID+"/verify", nil, &health)
	if !health.OK {
		t.Fatalf("the installation did not verify: %s (missing: %v)",
			health.Message, health.MissingPermissions)
	}

	// 3. A pool carrying this run's own label, so that two runs against one
	//    organisation cannot take each other's jobs or each other's runners.
	var pool struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	}
	api.post("/pools", map[string]any{
		"installation_id": inst.ID,
		"name":            "e2e-" + runID,
		"labels":          []string{label},
		"backend":         "docker",
		"min_runners":     0,
		"max_runners":     1,
		"idle_timeout":    "1m",
		"ephemeral":       true,
		"docker_mode":     "none",
	}, &pool)
	if err := ledger.created("pool", pool.ID); err != nil {
		t.Fatalf("recording the pool in the ledger: %v", err)
	}

	// The audit log must have recorded that.
	var audit struct {
		Items []struct {
			Action   string `json:"action"`
			TargetID string `json:"target_id"`
		} `json:"items"`
	}
	api.get("/audit?action=pool.create", &audit)
	if len(audit.Items) == 0 {
		t.Error("creating a pool was not written to the audit log")
	}

	// 4. Trigger the workflow, asking for this run's label.
	marker := fmt.Sprintf("zoomies-e2e-%s-%d", runID, time.Now().UnixNano())
	res.Marker = marker
	res.RunURL = dispatchWorkflow(t, e, marker, label)

	// 5. A runner must appear, register, and pick the job up.
	var runnerID string
	waitFor(t, waitRunnerCreated, "a runner to be created for the pool", func() bool {
		var out struct {
			Items []struct {
				ID    string `json:"id"`
				State string `json:"state"`
			} `json:"items"`
		}
		api.get("/runners?pool_id="+pool.ID+"&include_removed=true", &out)
		for _, r := range out.Items {
			runnerID = r.ID
			return true
		}
		return false
	})
	t.Logf("runner %s created", runnerID)

	waitFor(t, waitRunnerRegistered, "the runner to reach idle or busy", func() bool {
		var r struct {
			State string `json:"state"`
		}
		api.get("/runners/"+runnerID, &r)
		return r.State == "idle" || r.State == "busy" || r.State == "removed"
	})

	// 6. The job must complete successfully -- and it must be *this run's*
	//    job. Without the marker assertion the scenario would pass on any
	//    completed job in the pool, including one a concurrent run dispatched.
	var ourJob struct {
		ID         string `json:"id"`
		State      string `json:"state"`
		Conclusion string `json:"conclusion"`
		RunnerID   string `json:"runner_id"`
	}
	waitFor(t, waitJobCompleted, "this run's job to complete", func() bool {
		var out struct {
			Items []struct {
				ID         string   `json:"id"`
				State      string   `json:"state"`
				Conclusion string   `json:"conclusion"`
				RunnerID   string   `json:"runner_id"`
				Labels     []string `json:"labels"`
			} `json:"items"`
		}
		api.get("/jobs?pool_id="+pool.ID, &out)
		for _, j := range out.Items {
			if j.State != "completed" {
				continue
			}
			// The pool's label is unique to this run, so a job carrying it is
			// ours by construction; the marker is asserted on the run itself
			// below, where GitHub can be asked what it dispatched.
			for _, l := range j.Labels {
				if l == label {
					ourJob.ID, ourJob.State = j.ID, j.State
					ourJob.Conclusion, ourJob.RunnerID = j.Conclusion, j.RunnerID
					return true
				}
			}
		}
		return false
	})
	if ourJob.Conclusion != "success" {
		t.Fatalf("the job completed with conclusion %q, want success", ourJob.Conclusion)
	}
	if ourJob.RunnerID == "" {
		t.Error("the completed job is not linked to the runner that ran it")
	}
	assertDispatchedRun(t, e, marker)

	// 7. The ephemeral runner must go away by itself.
	waitFor(t, waitRunnerDestroyed, "the ephemeral runner to be destroyed", func() bool {
		var r struct {
			State string `json:"state"`
		}
		api.get("/runners/"+runnerID, &r)
		return r.State == "removed" || r.State == "failed"
	})

	var final struct {
		State       string `json:"state"`
		JobsHandled int    `json:"jobs_handled"`
	}
	api.get("/runners/"+runnerID, &final)
	if final.State != "removed" {
		t.Errorf("runner ended in state %q, want removed", final.State)
	}
	if final.JobsHandled != 1 {
		t.Errorf("runner handled %d jobs, want exactly 1 (it is ephemeral)", final.JobsHandled)
	}

	// 8. The numbers the Overview draws, from this run's own job.
	//
	//    The tiers below this one can assert that the figures are computed;
	//    only this one can say they are computed from a real job, and the
	//    Overview is where an operator looks the moment their first job
	//    finishes. A run whose timestamps are missing or out of order renders
	//    as a job that took no time at all.
	var timing struct {
		QueuedAt    string `json:"queued_at"`
		StartedAt   string `json:"started_at"`
		CompletedAt string `json:"completed_at"`
	}
	api.get("/jobs/"+ourJob.ID, &timing)
	queued, started, completed := parseTime(t, timing.QueuedAt, "queued_at"),
		parseTime(t, timing.StartedAt, "started_at"), parseTime(t, timing.CompletedAt, "completed_at")
	if started.Before(queued) || completed.Before(started) {
		t.Errorf("the job's timestamps are out of order: queued %s, started %s, completed %s",
			timing.QueuedAt, timing.StartedAt, timing.CompletedAt)
	}
	if d := completed.Sub(started); d <= 0 {
		t.Errorf("the job ran for %s; the Overview would show it as having taken no time", d)
	}

	var stats struct {
		Window       string `json:"window"`
		Completed    int    `json:"completed"`
		Succeeded    int    `json:"succeeded"`
		MedianWaitMS int64  `json:"median_wait_ms"`
		Fleet        struct {
			Completed int `json:"completed"`
			Succeeded int `json:"succeeded"`
		} `json:"fleet"`
	}
	api.get("/stats", &stats)
	if stats.Window == "" {
		t.Error("the statistics payload names no window, so the Overview cannot say what period it is showing")
	}
	if stats.Completed < 1 || stats.Succeeded < 1 {
		t.Errorf("stats report %d completed and %d succeeded after a successful run", stats.Completed, stats.Succeeded)
	}
	// The fleet-scoped half is the one that answers "what did *my* runners
	// do", and it is the figure the Overview shows by default.
	if stats.Fleet.Completed < 1 || stats.Fleet.Succeeded < 1 {
		t.Errorf("fleet-scoped stats report %d completed and %d succeeded; this job ran on a runner this controller created",
			stats.Fleet.Completed, stats.Fleet.Succeeded)
	}
	if stats.MedianWaitMS < 0 {
		t.Errorf("median wait is %dms", stats.MedianWaitMS)
	}

	// 9. The two checks that are the point of running this against reality.
	//    Both ask something other than Zoomies, because "did Zoomies clean up?"
	//    answered by Zoomies is not evidence.
	orphans, err := githubRunnersWithLabel(e, label)
	if err != nil {
		t.Errorf("checking GitHub for leftover registrations: %v", err)
	} else if len(orphans) > 0 {
		names := make([]string, 0, len(orphans))
		for _, o := range orphans {
			names = append(names, fmt.Sprintf("%s (id %d, %s)", o.Name, o.ID, o.Status))
		}
		t.Errorf("GitHub still holds %d registration(s) for this run after the runner was removed: %s",
			len(orphans), strings.Join(names, ", "))
	}
	left, err := containersForPool(pool.ID)
	if err != nil {
		t.Errorf("checking the host for leftover containers: %v", err)
	} else if len(left) > 0 {
		t.Errorf("the host still has %d container(s) for this run's pool: %s",
			len(left), strings.Join(left, "; "))
	}
}

// parseTime reads one of the API's timestamps, failing with the field's name:
// "cannot parse" on its own does not say which of three it was.
func parseTime(t *testing.T, value, field string) time.Time {
	t.Helper()
	if value == "" {
		t.Fatalf("the completed job carries no %s", field)
	}
	at, err := time.Parse(time.RFC3339, value)
	if err != nil {
		t.Fatalf("%s = %q, which is not RFC 3339: %v", field, value, err)
	}
	return at
}

// sweep clears what earlier runs left behind, before this run creates
// anything, and returns what it found.
//
// It reports rather than tidies quietly: a sweep that keeps finding things is
// a harness that keeps crashing, and that is worth seeing in the result file.
func sweep(t *testing.T, runID string, e env) []string {
	t.Helper()
	stale, err := staleLedgers(runID, e)
	if err != nil {
		t.Logf("could not read the ledger directory: %v", err)
		return nil
	}
	var found []string
	for _, rec := range stale {
		runners, err := githubRunnersWithLabel(e, rec.Label)
		if err != nil {
			t.Logf("could not check GitHub for run %s's runners: %v", rec.RunID, err)
			continue
		}
		cleared := true
		for _, r := range runners {
			if err := deleteGitHubRunner(e, r.ID); err != nil {
				t.Logf("could not delete runner %d left by run %s: %v", r.ID, rec.RunID, err)
				cleared = false
				continue
			}
			found = append(found, fmt.Sprintf("run %s: deleted GitHub runner %s (id %d)", rec.RunID, r.Name, r.ID))
		}
		if len(runners) == 0 {
			found = append(found, fmt.Sprintf("run %s: ledger left open with %d resource(s), no GitHub runners remained",
				rec.RunID, len(rec.Resources)))
		}
		if cleared {
			dropLedger(rec.RunID)
		}
	}
	for _, line := range found {
		t.Logf("sweep: %s", line)
	}
	return found
}

// tidyUp removes what this run created, in the order that makes each step
// possible: the pool goes first and forcibly, because its runners have to be
// gone before the installation that registered them can be deleted.
func tidyUp(t *testing.T, l *ledger, e env, label, base string) {
	t.Helper()
	api := &tolerantClient{t: t, base: base + "/api/v1"}
	deadline := time.Now().Add(waitCleanup)
	for _, r := range l.rec.Resources {
		if r.RemovedAt != nil || r.Kind != "pool" {
			continue
		}
		if api.delete("/pools/" + r.ID + "?force=true") {
			l.removed("pool", r.ID)
		}
	}
	// The pool's runners must actually be gone before the installation is
	// deleted, or the registrations outlive the credential that could remove
	// them.
	for time.Now().Before(deadline) {
		var out struct {
			Items []json.RawMessage `json:"items"`
		}
		if !api.get("/runners?include_removed=false", &out) || len(out.Items) == 0 {
			break
		}
		time.Sleep(3 * time.Second)
	}
	for _, r := range l.rec.Resources {
		if r.RemovedAt != nil || r.Kind != "installation" {
			continue
		}
		if api.delete("/installations/" + r.ID) {
			l.removed("installation", r.ID)
		}
	}
	sweepGitHub(t, e, label)
}

// sweepGitHub is the last resort: whatever Zoomies could not be made to
// remove, take off GitHub directly so the organisation is left clean.
func sweepGitHub(t *testing.T, e env, label string) {
	t.Helper()
	runners, err := githubRunnersWithLabel(e, label)
	if err != nil || len(runners) == 0 {
		return
	}
	for _, r := range runners {
		if err := deleteGitHubRunner(e, r.ID); err != nil {
			t.Errorf("could not delete leftover GitHub runner %d: %v", r.ID, err)
			continue
		}
		t.Logf("cleanup: deleted GitHub runner %s (id %d) directly", r.Name, r.ID)
	}
}

