// controller
// --------------------------------------------------------------------------

func resultsDir(t *testing.T) string {
	t.Helper()
	if d := os.Getenv("ZOOMIES_E2E_RESULTS_DIR"); d != "" {
		return d
	}
	return filepath.Join(filepath.Dir(builtBinary()), "roadmap", "validation", "e2e")
}

// controller starts a real zoomies controller against a throwaway database and
// returns its base URL.
func controller(t *testing.T) string {
	t.Helper()

	bin := builtBinary()
	port := freePort(t)
	dir := t.TempDir()
	base := fmt.Sprintf("http://127.0.0.1:%d", port)

	ctx, cancel := context.WithCancel(context.Background())
	cmd := exec.CommandContext(ctx, bin, "controller")
	cmd.Env = append(os.Environ(),
		fmt.Sprintf("ZOOMIES_BIND=127.0.0.1:%d", port),
		"ZOOMIES_DISABLE_AUTH=true", // loopback only; the config validator allows it there
		"ZOOMIES_DB_PATH="+filepath.Join(dir, "zoomies.db"),
		"ZOOMIES_STATE_DIR="+dir,
		"ZOOMIES_CONFIG_DIR="+dir,
		"ZOOMIES_WORK_DIR="+filepath.Join(dir, "work"),
		"ZOOMIES_AGENT_EMBEDDED=true",
		"ZOOMIES_AGENT_BACKEND=docker",
		"ZOOMIES_AGENT_CAPACITY=2",
		// A test host is not reachable from GitHub, so this exercises the
		// polling path rather than the webhook path. The webhook path is
		// covered by the integration tests against the fake GitHub.
		"ZOOMIES_POLL_FALLBACK=true",
		"ZOOMIES_POLL_INTERVAL=10s",
		"ZOOMIES_LOG_FORMAT=text",
		"ZOOMIES_LOG_LEVEL=debug",
	)
	var logs bytes.Buffer
	cmd.Stdout = &logs
	cmd.Stderr = &logs
	if err := cmd.Start(); err != nil {
		cancel()
		t.Fatalf("starting the controller: %v", err)
	}
	// Cleanup runs last-registered-first, so this stops the controller only
	// after tidyUp has finished deleting through its API.
	t.Cleanup(func() {
		cancel()
		_ = cmd.Wait()
		if t.Failed() {
			t.Logf("controller output:\n%s", logs.String())
		}
	})

	waitFor(t, waitControllerHealthy, "the controller to become healthy", func() bool {
		resp, err := http.Get(base + "/healthz")
		if err != nil {
			return false
		}
		resp.Body.Close()
		return resp.StatusCode == http.StatusOK
	})
	return base
}

// --------------------------------------------------------------------------
// helpers
// --------------------------------------------------------------------------

type client struct {
	t    *testing.T
	base string
}

func (c *client) do(method, path string, body any, out any) {
	c.t.Helper()
	status, raw, err := call(method, c.base+path, body, out)
	if err != nil {
		c.t.Fatalf("%s %s: %v", method, path, err)
	}
	if status >= 300 {
		c.t.Fatalf("%s %s: %d\n%s", method, path, status, raw)
	}
}

func (c *client) get(path string, out any)        { c.do(http.MethodGet, path, nil, out) }
func (c *client) post(path string, body, out any) { c.do(http.MethodPost, path, body, out) }

// tolerantClient is the cleanup's client: a failure is reported and moved past
// rather than fatal, because the next step may still remove something and a
// t.Fatal inside a cleanup would skip the rest of it.
type tolerantClient struct {
	t    *testing.T
	base string
}

func (c *tolerantClient) delete(path string) bool {
	c.t.Helper()
	status, raw, err := call(http.MethodDelete, c.base+path, nil, nil)
	if err != nil {
		c.t.Errorf("cleanup: DELETE %s: %v", path, err)
		return false
	}
	if status >= 300 && status != http.StatusNotFound {
		c.t.Errorf("cleanup: DELETE %s: %d\n%s", path, status, raw)
		return false
	}
	return true
}

func (c *tolerantClient) get(path string, out any) bool {
	c.t.Helper()
	status, _, err := call(http.MethodGet, c.base+path, nil, out)
	return err == nil && status < 300
}

func call(method, url string, body, out any) (int, []byte, error) {
	var r io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return 0, nil, fmt.Errorf("marshalling the request body: %w", err)
		}
		r = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, url, r)
	if err != nil {
		return 0, nil, fmt.Errorf("building the request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, nil, err
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	if resp.StatusCode < 300 && out != nil && len(raw) > 0 {
		if err := json.Unmarshal(raw, out); err != nil {
			return resp.StatusCode, raw, fmt.Errorf("decoding the response: %w", err)
		}
	}
	return resp.StatusCode, raw, nil
}

// dispatchWorkflow triggers the fixture workflow and returns a link to the run
// it started. The label goes with the marker so the workflow asks for this
// run's pool rather than a shared one.
func dispatchWorkflow(t *testing.T, e env, marker, label string) string {
	t.Helper()
	cmd := exec.Command("gh", "workflow", "run", "zoomies-e2e.yml",
		"--repo", e.repo, "-f", "marker="+marker, "-f", "label="+label)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("triggering the workflow in %s: %v\n%s", e.repo, err, out)
	}
	t.Logf("dispatched zoomies-e2e.yml in %s with marker %s and label %s", e.repo, marker, label)
	return "https://github.com/" + e.repo + "/actions/workflows/zoomies-e2e.yml"
}

// assertDispatchedRun asks GitHub that a run carrying this marker exists and
// succeeded. It is the check that ties the job Zoomies ran to the job this
// test asked for; without it the scenario passes on whatever happened to be
// in the pool.
func assertDispatchedRun(t *testing.T, e env, marker string) {
	t.Helper()
	out, err := exec.Command("gh", "run", "list", "--repo", e.repo,
		"--workflow", "zoomies-e2e.yml", "--limit", "20",
		"--json", "databaseId,displayTitle,conclusion,url").Output()
	if err != nil {
		t.Errorf("asking GitHub for the dispatched run: %v", ghError(err))
		return
	}
	var runs []struct {
		DatabaseID   int64  `json:"databaseId"`
		DisplayTitle string `json:"displayTitle"`
		Conclusion   string `json:"conclusion"`
		URL          string `json:"url"`
	}
	if err := json.Unmarshal(out, &runs); err != nil {
		t.Errorf("decoding the run list: %v", err)
		return
	}
	for _, r := range runs {
		if strings.Contains(r.DisplayTitle, marker) {
			if r.Conclusion != "success" {
				t.Errorf("the dispatched run %s concluded %q, want success", r.URL, r.Conclusion)
			}
			return
		}
	}
	t.Logf("no run titled with marker %s found; GitHub does not always put a dispatch input in the title, "+
		"so this is reported rather than failed", marker)
}

func waitFor(t *testing.T, limit time.Duration, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(limit)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(3 * time.Second)
	}
	t.Fatalf("timed out after %s waiting for %s", limit, what)
}

func freePort(t *testing.T) int {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("finding a free port: %v", err)
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

// newRunID is this run's identity. It is short, lower-case and alphanumeric
// because it becomes part of a GitHub runner label and a pool name.
func newRunID() string {
	const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
	b := make([]byte, 8)
	for i := range b {
		b[i] = alphabet[rand.IntN(len(alphabet))]
	}
	return string(b)
}

func mustInt(t *testing.T, s string) int64 {
	t.Helper()
	var n int64
	if _, err := fmt.Sscanf(s, "%d", &n); err != nil {
		t.Fatalf("%q is not a number: %v", s, err)
	}
	return n
}

//go:build e2e

package e2e

import (
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"strings"

	"github.com/eyupio/zoomies/internal/backend"
)

// Everything here asks GitHub and the Docker host directly, rather than asking
// Zoomies.
//
// That is the whole point. The failure this harness exists to catch is a
// registration left behind on an organisation after a runner is gone, and
// Zoomies' own /runners endpoint cannot see it: the row says "removed" exactly
// when Zoomies believes it removed it, which is the belief under test. Asking
// the controller whether the controller was right is not evidence.
//
// The calls go through the gh CLI, as the workflow dispatch already does, so
// this test needs no GitHub token of its own in its environment.

// ghRunner is one self-hosted runner as GitHub sees it.
type ghRunner struct {
	ID     int64  `json:"id"`
	Name   string `json:"name"`
	Status string `json:"status"`
	Labels []struct {
		Name string `json:"name"`
	} `json:"labels"`
}

// runnersPath is the API path for the target's self-hosted runners.
func (e env) runnersPath() string {
	if e.targetType == "repo" {
		return "/repos/" + e.target + "/actions/runners"
	}
	return "/orgs/" + e.target + "/actions/runners"
}

// githubRunnersWithLabel lists the registrations GitHub currently holds that
// carry one label. Per-run labels are what make this answer belong to this run
// rather than to whatever else the organisation is doing.
func githubRunnersWithLabel(e env, label string) ([]ghRunner, error) {
	out, err := exec.Command("gh", "api", "--paginate", e.runnersPath()).Output()
	if err != nil {
		return nil, fmt.Errorf("asking GitHub for %s's runners: %w", e.target, ghError(err))
	}
	// --paginate concatenates pages, so decode as a stream rather than once.
	dec := json.NewDecoder(strings.NewReader(string(out)))
	var found []ghRunner
	for {
		var page struct {
			Runners []ghRunner `json:"runners"`
		}
		if err := dec.Decode(&page); err != nil {
			break
		}
		for _, r := range page.Runners {
			for _, l := range r.Labels {
				if l.Name == label {
					found = append(found, r)
					break
				}
			}
		}
	}
	return found, nil
}

// deleteGitHubRunner removes one registration. It is used only by the sweep,
// on the leavings of a run that did not finish: the scenario itself asserts
// that Zoomies removed the registration, and doing it here would hide exactly
// the fault being looked for.
func deleteGitHubRunner(e env, id int64) error {
	cmd := exec.Command("gh", "api", "-X", "DELETE", fmt.Sprintf("%s/%d", e.runnersPath(), id))
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("deleting runner %d from %s: %w\n%s", id, e.target, err, out)
	}
	return nil
}

// containersForPool lists the workload containers still on this host that
// belong to one pool, by the labels the backend stamps on every workload it
// creates (internal/backend.Spec.Labels).
//
// The host is asked directly for the same reason GitHub is: a controller that
// has lost track of a container will report it gone, and the container will
// still be holding the disk and, if it is a docker-in-docker sidecar, still
// running as root.
func containersForPool(poolID string) ([]string, error) {
	cmd := exec.Command("docker", "ps", "-a",
		"--filter", "label="+backend.LabelManaged+"=true",
		"--filter", "label="+backend.LabelPoolID+"="+poolID,
		"--format", "{{.ID}} {{.Names}} {{.Status}}")
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("asking the Docker daemon what is still running: %w", err)
	}
	var found []string
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line != "" {
			found = append(found, line)
		}
	}
	return found, nil
}

// ghError unwraps an ExitError so the message carries what gh printed rather
// than "exit status 1".
func ghError(err error) error {
	var ee *exec.ExitError
	if errors.As(err, &ee) && len(ee.Stderr) > 0 {
		return fmt.Errorf("%w: %s", err, strings.TrimSpace(string(ee.Stderr)))
	}
	return err
}

//go:build e2e

package e2e

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// The installer scenario's prerequisites, which are deliberately not the
// GitHub scenario's.
//
// Setting a host up touches nothing on GitHub: it makes a service account,
// writes /etc/zoomies, seals a key and creates an administrator. So this
// scenario needs Docker and a Linux binary and nothing else, and it is worth
// keeping that true -- it means a gate with no GitHub App still runs the half
// of the product that a first-time operator meets first.

// installerImage is the throwaway host the installer is let loose on. It has
// to carry useradd, which the Debian base does.
func installerImage() string {
	return orDefault(os.Getenv("ZOOMIES_E2E_INSTALLER_IMAGE"), "debian:stable-slim")
}

// installerPreflight checks what this scenario needs before it creates
// anything, in the same spirit as preflight: a prerequisite found halfway
// through is a container left running on somebody's machine.
func installerPreflight() []string {
	var missing []string

	if _, err := exec.LookPath("docker"); err != nil {
		missing = append(missing, "docker is not on PATH: the installer is run inside a throwaway container")
	} else if out, err := exec.Command("docker", "info", "--format", "{{.ServerVersion}}").CombinedOutput(); err != nil {
		missing = append(missing, fmt.Sprintf("the Docker daemon is not reachable: %s", strings.TrimSpace(string(out))))
	}

	bin := builtBinary()
	info, err := os.Stat(bin)
	switch {
	case err != nil:
		missing = append(missing, "the zoomies binary is not built; run `make build` first")
	case info.IsDir():
		missing = append(missing, bin+" is a directory, not the zoomies binary")
	default:
		// The binary is bind-mounted into a Linux container and executed
		// there, so a darwin or windows build cannot run however healthy it
		// looks on this host. Saying so here beats "exec format error" from
		// inside a container sixty seconds later.
		if !isLinuxELF(bin) {
			missing = append(missing, fmt.Sprintf(
				"%s is not a Linux executable, so it cannot run inside the container this scenario installs into; "+
					"build one with GOOS=linux go build -o zoomies ./cmd/zoomies", bin))
		}
	}
	return missing
}

// isLinuxELF reports whether the file starts with the ELF magic. It is a
// cheap, dependency-free check for "this will run in a Linux container",
// which is the only thing the scenario needs to know.
func isLinuxELF(path string) bool {
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	var magic [4]byte
	if _, err := f.Read(magic[:]); err != nil {
		return false
	}
	return magic == [4]byte{0x7f, 'E', 'L', 'F'}
}

//go:build e2e

package e2e

import (
	"context"
	"fmt"
	"net/http"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This scenario proves the other half of the product: not "does a runner run a
// job", but "does `zoomies init` turn a bare machine into a working
// controller, and does `zoomies uninstall` give the machine back".
//
// It is the half that unit tests cannot reach. Setting a host up means making
// a system account, writing into /etc and /var/lib, sealing a key at mode
// 0600 and creating an administrator in a real database -- none of which can
// be asserted honestly against a temporary directory, because the guards that
// matter are the ones keyed to the real system paths. `serviceUserToRemove`
// is the clearest case: it refuses to delete the account unless the install
// really is the one that owns /etc/zoomies, so a test pointed somewhere else
// proves nothing about the code that runs for an operator.
//
// So the machine is a throwaway container, and the installer is let loose on
// it exactly as it would be on a VM.

const installerScenario = "installer_provisions_and_removes_a_host"

// Where a default install puts things. They are spelled out rather than read
// from the installer, because the point is to check the paths an operator was
// promised against the paths that appeared.
const (
	sysConfigDir = "/etc/zoomies"
	sysStateDir  = "/var/lib/zoomies"
	sysKeyFile   = sysConfigDir + "/encryption.key"
	sysConfig    = sysConfigDir + "/zoomies.yaml"
	sysDatabase  = sysStateDir + "/zoomies.db"
	// serviceAccount is the unprivileged account the installer creates, and
	// the only one uninstall will ever delete.
	serviceAccount = "zoomies"
)

func TestInstallerProvisionsAndRemovesAHost(t *testing.T) {
	runID := newRunID()
	res := &Result{
		Scenario: installerScenario, RunID: runID, Commit: commit(),
		StartedAt: time.Now(), Category: NotRun,
	}
	t.Cleanup(func() {
		if !requested() {
			return
		}
		res.FinishedAt = time.Now()
		if err := res.write(resultsDir(t)); err != nil {
			t.Errorf("writing the result record: %v", err)
		}
	})

	if !requested() {
		t.Skip("set ZOOMIES_E2E=1 to run the end-to-end tests; see test/e2e/README.md")
	}

	// Deliberately not preflight(): this scenario touches nothing on GitHub,
	// so a gate with no App installed should still run it.
	if missing := installerPreflight(); len(missing) > 0 {
		res.Category, res.Reason = Blocked, strings.Join(missing, "; ")
		if required() {
			t.Fatalf("blocked: %s", res.Reason)
		}
		t.Skipf("blocked: %s", res.Reason)
	}

	// Registered before the container exists, so that it runs *after* the
	// container's own removal: cleanups run last-registered-first, and a
	// throwaway host that could not be removed is litter on the machine
	// running the test. A scenario that passed and left one behind has not
	// finished, so its failure has to reach the category.
	t.Cleanup(func() {
		if res.Category == NotRun && !t.Failed() {
			res.Category = Passed
		}
		if t.Failed() && res.Category != Blocked {
			res.Category = Failed
			if res.Reason == "" {
				res.Reason = "an assertion failed; see the test output"
			}
		}
	})

	port := freePort(t)
	host := newInstallerHost(t, runID, port)

	// 1. Set the machine up, unattended, from an answer file -- which is the
	//    path configuration management takes and the only one a test can
	//    drive, since the interactive one waits for a person.
	host.write("/tmp/answers.yaml", installerAnswers())
	out, err := host.run("zoomies", "init", "--non-interactive", "--answers", "/tmp/answers.yaml")
	if err != nil {
		t.Fatalf("zoomies init failed: %v\n%s", err, out)
	}
	t.Logf("installer output:\n%s", out)

	// The summary is what the operator is left reading, so it has to name the
	// key they now have to back up. Losing it loses every stored secret.
	if !strings.Contains(out, sysKeyFile) {
		t.Errorf("the installer never told the operator where the encryption key is:\n%s", out)
	}

	// 2. What it actually put on the machine, asked of the filesystem rather
	//    than of the installer's own summary.
	for _, want := range []struct {
		path, mode, owner, why string
	}{
		{sysConfigDir, "750", "zoomies:zoomies", "the configuration directory"},
		{sysStateDir, "750", "zoomies:zoomies", "the state directory"},
		// 0600 is the whole promise about the key: anything that can read the
		// config must not thereby be able to decrypt the App's private key.
		{sysKeyFile, "600", "zoomies:zoomies", "the encryption key"},
		{sysConfig, "640", "zoomies:zoomies", "the configuration"},
	} {
		got, err := host.run("stat", "-c", "%a %U:%G", want.path)
		if err != nil {
			t.Errorf("%s (%s) was not created: %v\n%s", want.path, want.why, err, got)
			continue
		}
		if fields := strings.Fields(strings.TrimSpace(got)); len(fields) != 2 {
			t.Errorf("stat of %s returned %q", want.path, got)
		} else if fields[0] != want.mode || fields[1] != want.owner {
			t.Errorf("%s is mode %s owned by %s, want mode %s owned by %s",
				want.path, fields[0], fields[1], want.mode, want.owner)
		}
	}

	// 3. The key is in its own file and nowhere else. A key written into
	//    zoomies.yaml would be copied by every backup and every configuration
	//    management run that touches the config.
	cfg, err := host.run("cat", sysConfig)
	if err != nil {
		t.Fatalf("reading the configuration the installer wrote: %v\n%s", err, cfg)
	}
	if !strings.Contains(cfg, `encryption_key: ""`) {
		t.Errorf("the configuration does not carry an empty encryption_key, so the key may have been written into it:\n%s", cfg)
	}
	if !strings.Contains(cfg, "encryption_key_file: "+sysKeyFile) {
		t.Errorf("the configuration does not point at %s:\n%s", sysKeyFile, cfg)
	}

	// 4. The service account: a real system user that cannot be logged into.
	//    An account with a shell is a way onto the machine that the runners'
	//    own isolation was supposed to have closed.
	passwd, err := host.run("getent", "passwd", serviceAccount)
	if err != nil {
		t.Fatalf("the installer did not create the %s system account: %v\n%s", serviceAccount, err, passwd)
	}
	if !strings.Contains(passwd, "nologin") && !strings.Contains(passwd, "/bin/false") {
		t.Errorf("the %s account has a login shell, which it must not: %s", serviceAccount, strings.TrimSpace(passwd))
	}

	// 5. The database exists and carries the administrator that was asked for.
	if out, err := host.run("test", "-s", sysDatabase); err != nil {
		t.Fatalf("no database at %s: %v\n%s", sysDatabase, err, out)
	}

	// 6. The decisive one: the controller this install configured actually
	//    serves. Everything above is evidence about files; this is the
	//    deployment working, asked from outside the container over the port
	//    the operator was told to use.
	host.startController(t)
	base := fmt.Sprintf("http://127.0.0.1:%d", port)
	waitFor(t, waitInstalledControllerHealthy, "the installed controller to become healthy", func() bool {
		resp, err := http.Get(base + "/healthz")
		if err != nil {
			return false
		}
		resp.Body.Close()
		return resp.StatusCode == http.StatusOK
	})

	// And it must be serving with authentication on. The safe configuration is
	// the default, so an install that left the API open is a failed install
	// however healthy it reports.
	resp, err := http.Get(base + "/api/v1/pools")
	if err != nil {
		t.Fatalf("asking the installed controller for its pools: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusUnauthorized {
		t.Errorf("GET /api/v1/pools on a fresh install answered %d, want 401: "+
			"a default install must not leave the API open", resp.StatusCode)
	}
	host.stopController(t)

	// 7. Give the machine back. An installer that cannot be undone is one
	//    nobody can safely try.
	out, err = host.run("zoomies", "uninstall", "--yes", "--non-interactive", "--deregister=false")
	if err != nil {
		t.Fatalf("zoomies uninstall failed: %v\n%s", err, out)
	}
	t.Logf("uninstall output:\n%s", out)
	if !strings.Contains(out, "nothing was left behind") {
		t.Errorf("uninstall did not report a clean removal:\n%s", out)
	}

	// 8. And prove it, by asking the machine rather than believing the report.
	//    This is the same principle as the GitHub scenario's last two checks:
	//    "did it clean up?" answered by the thing that was supposed to clean
	//    up is not evidence.
	for _, path := range []string{sysConfigDir, sysStateDir} {
		if out, err := host.run("test", "-e", path); err == nil {
			t.Errorf("%s is still on the machine after uninstall:\n%s", path, out)
		}
	}
	// The account is the one uninstall is most cautious about, because
	// deleting the wrong one is unrecoverable. A default install at the
	// default paths is the case where it may, and must.
	if out, err := host.run("getent", "passwd", serviceAccount); err == nil {
		t.Errorf("the %s account outlived the install it was created for: %s",
			serviceAccount, strings.TrimSpace(out))
	}
}

// installerAnswers is the answer file the scenario installs from.
//
// It asks for the process backend and no pool, because this scenario is about
// what setup does to the machine rather than about running a job -- that is
// the other scenario's subject, and it needs a GitHub App this one
// deliberately does without.
func installerAnswers() string {
	return strings.Join([]string{
		"mode: single",
		"deployment: native",
		"backend: process",
		"capacity: 1",
		// The container publishes this port, so the check comes from outside.
		"bind: 0.0.0.0:8099",
		"external_url: http://127.0.0.1:8099",
		"tls:",
		`  mode: "off"`,
		"github:",
		"  skip: true",
		"admin:",
		"  username: e2e-admin",
		"  password: a-long-enough-password-123",
		"pool:",
		"  skip: true",
		"service:",
		"  manager: none",
		"",
	}, "\n")
}

// --------------------------------------------------------------------------
// the throwaway machine
// --------------------------------------------------------------------------

// installerHost is a disposable container the installer is allowed to change
// however it likes. Everything the scenario asserts is asked of it from
// outside, through docker.
type installerHost struct {
	t    *testing.T
	name string
}

// newInstallerHost starts the container and registers its removal. The
// container is the cleanup: whatever the installer did to it goes when it
// does, which is why this scenario can afford to let a real installer run at
// the real system paths.
func newInstallerHost(t *testing.T, runID string, port int) *installerHost {
	t.Helper()
	h := &installerHost{t: t, name: "zoomies-e2e-installer-" + runID}

	bin, err := filepath.Abs(builtBinary())
	if err != nil {
		t.Fatalf("resolving the binary's path: %v", err)
	}

	// Pull first and separately, so that a slow or failed pull is reported as
	// what it is rather than as the container failing to start.
	pullCtx, cancelPull := context.WithTimeout(context.Background(), waitInstallerImage)
	defer cancelPull()
	if out, err := exec.CommandContext(pullCtx, "docker", "pull", installerImage()).CombinedOutput(); err != nil {
		t.Fatalf("pulling %s within %s: %v\n%s", installerImage(), waitInstallerImage, err, out)
	}

	out, err := exec.Command("docker", "run", "-d", "--name", h.name,
		"-p", fmt.Sprintf("127.0.0.1:%d:8099", port),
		"-v", bin+":/usr/local/bin/zoomies:ro",
		installerImage(), "sleep", "infinity").CombinedOutput()
	if err != nil {
		t.Fatalf("starting the throwaway host: %v\n%s", err, out)
	}
	t.Cleanup(func() {
		if out, err := exec.Command("docker", "rm", "-f", h.name).CombinedOutput(); err != nil {
			// This is litter on the machine running the test, so it is worth
			// a failure rather than a log line.
			t.Errorf("could not remove the throwaway host %s: %v\n%s", h.name, err, out)
		}
	})
	return h
}

// run executes a command on the machine and returns its combined output.
//
// Every command is bounded by waitInstallerSteps rather than left to run for
// ever: an installer that hangs waiting for a prompt it should never have
// reached would otherwise be reported as the whole suite timing out, which
// names nothing. The budget is shared with the Makefile's -timeout through
// budget_test.go.
func (h *installerHost) run(name string, args ...string) (string, error) {
	h.t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), waitInstallerSteps)
	defer cancel()
	full := append([]string{"exec", h.name, name}, args...)
	out, err := exec.CommandContext(ctx, "docker", full...).CombinedOutput()
	if ctx.Err() != nil {
		return string(out), fmt.Errorf("%s did not finish within %s: %w", name, waitInstallerSteps, ctx.Err())
	}
	return string(out), err
}

// write puts a file on the machine. It goes through a here-document rather
// than `docker cp` so that the scenario needs no temporary file on the host
// running it.
func (h *installerHost) write(path, body string) {
	h.t.Helper()
	cmd := exec.Command("docker", "exec", "-i", h.name, "sh", "-c", "cat > "+path)
	cmd.Stdin = strings.NewReader(body)
	if out, err := cmd.CombinedOutput(); err != nil {
		h.t.Fatalf("writing %s on the throwaway host: %v\n%s", path, err, out)
	}
}

// startController runs the controller the install configured, in the
// background, reading the configuration the installer wrote and nothing else.
// Passing no flags is the point: what is under test is whether the file the
// installer produced is enough to run from.
func (h *installerHost) startController(t *testing.T) {
	t.Helper()
	// The PID is recorded rather than found again later with pkill, which is
	// in procps and so is not in a slim base image. Depending on it would
	// make this scenario fail on the image it names by default.
	out, err := h.run("sh", "-c",
		"nohup zoomies controller --config "+sysConfig+" > /tmp/controller.log 2>&1 & echo $! > /tmp/controller.pid")
	if err != nil {
		t.Fatalf("starting the installed controller: %v\n%s", err, out)
	}
}

// stopController stops it again, so that uninstall is not asked to delete a
// database out from under a running process.
func (h *installerHost) stopController(t *testing.T) {
	t.Helper()
	if out, err := h.run("sh", "-c", "kill -TERM \"$(cat /tmp/controller.pid)\" 2>/dev/null || true"); err != nil {
		t.Logf("stopping the installed controller: %v\n%s", err, out)
	}
	// The listener has to be gone before uninstall runs, and a controller
	// stops in well under a second once it has been asked to.
	time.Sleep(2 * time.Second)
	if log, err := h.run("cat", "/tmp/controller.log"); err == nil && t.Failed() {
		t.Logf("installed controller log:\n%s", log)
	}
}

//go:build e2e

package e2e

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// A ledger is the list of real things one run has created, written to disk
// before each is created and closed only when they have all been removed.
//
// It exists because the resources are somebody's: a GitHub App installation
// and a pool on a real organisation, and runners registered against it. The
// previous harness deleted them in its last step, so any failure before that
// step -- including a timeout, which it was guaranteed to hit -- left them
// behind with nothing recording that they existed.
//
// It lives outside the test's temp directory on purpose. t.TempDir is removed
// when the test ends however it ends, which is exactly the moment the record
// of what was not cleaned up becomes useful. It is also the reason the sweep
// can work at all: a later run reads these files, not a database that went
// away with the process that wrote it.
type ledger struct {
	path string
	rec  ledgerRecord
}

type ledgerRecord struct {
	RunID     string    `json:"run_id"`
	StartedAt time.Time `json:"started_at"`
	Commit    string    `json:"commit"`
	// Label is the per-run label this run's pool advertises and its workflow
	// asks for. It is how the sweep recognises a stale run's runners on
	// GitHub, and how two concurrent runs stay out of each other's way.
	Label string `json:"label"`
	// Target and TargetType name where on GitHub the leavings would be.
	Target     string `json:"target"`
	TargetType string `json:"target_type"`
	// Resources are what this run made, appended as each is created.
	Resources []resource `json:"resources"`
	// ClosedAt is set only when every resource has been removed. An open
	// ledger is a run that did not finish tidying up, whether it crashed, was
	// killed, or failed its cleanup.
	ClosedAt *time.Time `json:"closed_at,omitempty"`
}

type resource struct {
	Kind      string     `json:"kind"` // installation | pool
	ID        string     `json:"id"`
	CreatedAt time.Time  `json:"created_at"`
	RemovedAt *time.Time `json:"removed_at,omitempty"`
}

// ledgerDir is where ledgers live. It must survive the test process, so it is
// never t.TempDir.
func ledgerDir() string {
	if d := os.Getenv("ZOOMIES_E2E_LEDGER_DIR"); d != "" {
		return d
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(os.TempDir(), "zoomies-e2e-ledgers")
	}
	return filepath.Join(home, ".zoomies", "e2e-ledgers")
}

// openLedger creates a run's ledger before anything is created.
func openLedger(runID, label string, e env) (*ledger, error) {
	dir := ledgerDir()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("creating the ledger directory %s: %w", dir, err)
	}
	l := &ledger{
		path: filepath.Join(dir, runID+".json"),
		rec: ledgerRecord{
			RunID: runID, StartedAt: time.Now(), Commit: commit(),
			Label: label, Target: e.target, TargetType: e.targetType,
		},
	}
	return l, l.save()
}

func (l *ledger) save() error {
	raw, err := json.MarshalIndent(l.rec, "", "  ")
	if err != nil {
		return fmt.Errorf("encoding the ledger: %w", err)
	}
	return os.WriteFile(l.path, append(raw, '\n'), 0o644)
}

// created records a resource. It is called immediately after the thing exists,
// and its error is fatal to the caller: a resource that exists without a
// ledger entry is one nothing will ever clean up.
func (l *ledger) created(kind, id string) error {
	l.rec.Resources = append(l.rec.Resources, resource{Kind: kind, ID: id, CreatedAt: time.Now()})
	return l.save()
}

func (l *ledger) removed(kind, id string) {
	now := time.Now()
	for i := range l.rec.Resources {
		if l.rec.Resources[i].Kind == kind && l.rec.Resources[i].ID == id {
			l.rec.Resources[i].RemovedAt = &now
		}
	}
	_ = l.save()
}

// outstanding is what this run created and has not removed.
func (l *ledger) outstanding() []string {
	var out []string
	for _, r := range l.rec.Resources {
		if r.RemovedAt == nil {
			out = append(out, r.Kind+" "+r.ID)
		}
	}
	return out
}

// close marks the ledger finished and deletes it. A ledger is only worth
// keeping while it describes something still on GitHub; one whose resources
// are all gone is noise the next sweep would have to read past.
func (l *ledger) close() error {
	if rem := l.outstanding(); len(rem) > 0 {
		return fmt.Errorf("not closing the ledger: %s still exist", strings.Join(rem, ", "))
	}
	now := time.Now()
	l.rec.ClosedAt = &now
	if err := l.save(); err != nil {
		return err
	}
	return os.Remove(l.path)
}

// staleLedgers returns the open ledgers left by earlier runs against this same
// target, oldest first. An open ledger is by definition a run that did not
// finish tidying up.
func staleLedgers(runID string, e env) ([]ledgerRecord, error) {
	entries, err := os.ReadDir(ledgerDir())
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var out []ledgerRecord
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(ledgerDir(), entry.Name()))
		if err != nil {
			continue
		}
		var rec ledgerRecord
		if json.Unmarshal(raw, &rec) != nil {
			continue
		}
		// This run's own ledger is not stale, and neither is one describing
		// somebody else's organisation: cleaning that would be reaching into a
		// target this run was never given.
		if rec.RunID == runID || rec.ClosedAt != nil || rec.Target != e.target {
			continue
		}
		out = append(out, rec)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].StartedAt.Before(out[j].StartedAt) })
	return out, nil
}

// dropLedger removes a stale ledger once its leavings have been dealt with.
func dropLedger(runID string) {
	_ = os.Remove(filepath.Join(ledgerDir(), runID+".json"))
}

//go:build e2e

package e2e

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// builtBinary is the zoomies the scenarios run: the one `make build` left in
// the repository root, never one built on the fly.
//
// It lives in an ordinary file rather than beside the scenario that reads it,
// because preflight.go and installer.go are ordinary files too and a _test.go
// file's symbols are invisible to them. Keeping it here is what makes
// `go build -tags e2e ./...` compile.
func builtBinary() string {
	dir, err := os.Getwd()
	if err != nil {
		return "zoomies"
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "zoomies")
		}
		dir = filepath.Dir(dir)
	}
	return "zoomies"
}

// env is everything the scenario needs from outside itself.
type env struct {
	appID          string
	installationID string
	privateKey     string
	target         string
	targetType     string
	repo           string
}

// required reports whether a missing prerequisite is a failure rather than a
// skip. A gate runs in this mode; a laptop does not.
func required() bool { return os.Getenv("ZOOMIES_E2E_REQUIRED") != "" }

// requested reports whether this run was asked to do anything at all.
func requested() bool { return os.Getenv("ZOOMIES_E2E") != "" || required() }

// preflight checks every prerequisite before anything is created.
//
// "Before anything is created" is the whole change. The previous harness
// checked its environment and Docker up front but looked for the gh CLI in the
// middle of the scenario, after it had already made a GitHub App installation
// and a pool on a real organisation -- and then called t.Skip, which is exit
// code zero. A green run could therefore mean "we created two things on your
// organisation, could not continue, left them there, and told you nothing".
//
// So every check that can be made without side effects is made here, and the
// scenario does not begin until they all hold.
func preflight() (env, []string) {
	e := env{
		appID:          os.Getenv("ZOOMIES_E2E_APP_ID"),
		installationID: os.Getenv("ZOOMIES_E2E_INSTALLATION_ID"),
		target:         os.Getenv("ZOOMIES_E2E_TARGET"),
		targetType:     orDefault(os.Getenv("ZOOMIES_E2E_TARGET_TYPE"), "org"),
		repo:           os.Getenv("ZOOMIES_E2E_REPO"),
	}
	keyFile := os.Getenv("ZOOMIES_E2E_PRIVATE_KEY_FILE")

	var missing []string
	for _, v := range []struct{ name, value string }{
		{"ZOOMIES_E2E_APP_ID", e.appID},
		{"ZOOMIES_E2E_INSTALLATION_ID", e.installationID},
		{"ZOOMIES_E2E_PRIVATE_KEY_FILE", keyFile},
		{"ZOOMIES_E2E_TARGET", e.target},
		{"ZOOMIES_E2E_REPO", e.repo},
	} {
		if v.value == "" {
			missing = append(missing, v.name+" is not set")
		}
	}
	switch e.targetType {
	case "org", "repo":
	default:
		missing = append(missing, fmt.Sprintf("ZOOMIES_E2E_TARGET_TYPE is %q; it must be org or repo", e.targetType))
	}
	if keyFile != "" {
		pem, err := os.ReadFile(keyFile)
		switch {
		case err != nil:
			missing = append(missing, fmt.Sprintf("ZOOMIES_E2E_PRIVATE_KEY_FILE %s cannot be read: %v", keyFile, err))
		case !strings.Contains(string(pem), "PRIVATE KEY"):
			missing = append(missing, fmt.Sprintf("%s does not look like a PEM private key", keyFile))
		default:
			e.privateKey = string(pem)
		}
	}

	// The tools, all of them, up front.
	for _, tool := range []struct{ bin, why string }{
		{"docker", "the runner backend needs a Docker daemon on this host"},
		{"gh", "the workflow is dispatched and GitHub is queried through the gh CLI"},
		{"git", "the result records the commit under test"},
	} {
		if _, err := exec.LookPath(tool.bin); err != nil {
			missing = append(missing, fmt.Sprintf("%s is not on PATH: %s", tool.bin, tool.why))
		}
	}
	// A Docker binary that cannot reach a daemon is the same problem as no
	// Docker, and it is worth finding here rather than sixty seconds into a
	// runner that will never start.
	if _, err := exec.LookPath("docker"); err == nil {
		if out, err := exec.Command("docker", "info", "--format", "{{.ServerVersion}}").CombinedOutput(); err != nil {
			missing = append(missing, fmt.Sprintf("the Docker daemon is not reachable: %s", strings.TrimSpace(string(out))))
		}
	}
	// gh must actually be authenticated, for the same reason.
	if _, err := exec.LookPath("gh"); err == nil {
		if out, err := exec.Command("gh", "auth", "status").CombinedOutput(); err != nil {
			missing = append(missing, fmt.Sprintf("the gh CLI is not authenticated: %s", strings.TrimSpace(string(out))))
		}
	}
	if _, err := os.Stat(builtBinary()); err != nil {
		missing = append(missing, "the zoomies binary is not built; run `make build` first")
	}
	return e, missing
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

package proxmox

import "time"

// The waits this harness allows, and the budget they add up to.
//
// The end-to-end harness next door was once found with waits totalling
// twenty-seven minutes behind a Makefile timeout of twenty, which means it
// could never have reached its own last assertion: `go test` would have killed
// it first and reported a timeout rather than whatever it was stuck on. That is
// worse here than it is there. This harness creates virtual machines, and a run
// killed between the clone and the delete leaves them running on somebody's
// cluster; the closing reconciliation, which is the step that decides
// qualification, is the last thing to run and therefore the first thing a
// too-short timeout throws away.
//
// So the numbers live in a file with no build tag, budget_test.go checks them
// against the Makefile in ordinary CI, and the harness itself refuses to start
// when `go test`'s own deadline cannot fit them -- fast, and before anything
// has been created.
//
// Each wait is generous, because every one of them crosses a real network to a
// real hypervisor. None is so generous that it stops meaning anything: a
// prepared template that takes four minutes to clone and boot on a
// qualification cluster is a finding, not a slow day, and the run should say so
// rather than wait.
const (
	// waitControllerHealthy covers a start and, in the restart case, a restart
	// that has to re-derive its machine work from the rows.
	waitControllerHealthy = 60 * time.Second
	// waitProviderChecked is the live preflight: one round trip to the cluster
	// for the version, the privileges, the storage and the template.
	waitProviderChecked = 2 * time.Minute
	// waitFirstMachine is queued work to a machine row. Nothing has been built
	// yet -- this is the controller's own loop -- so it is short, and a long one
	// means the demand never reached the provider rather than that the
	// hypervisor is slow.
	waitFirstMachine = 90 * time.Second
	// waitMachineCreated is the hypervisor's half: clone the template, then
	// power the guest on.
	waitMachineCreated = 4 * time.Minute
	// waitMachineReady is the guest's: the agent answering, the bootstrap
	// running inside it, and the host joining this controller.
	waitMachineReady = 4 * time.Minute
	// waitJobCompleted is a real job on a real repository, including whatever
	// the runner has to pull before it can start.
	waitJobCompleted = 5 * time.Minute
	// waitMachineDrained is a cordoned machine waiting for its runners to
	// finish. The job it ran is already over by the time a drain is asked for,
	// so this covers the pass that notices rather than the work.
	waitMachineDrained = 2 * time.Minute
	// waitMachineDeleted is the delete and, more to the point, the inspect that
	// proves the resource is gone. A 200 from the delete call is not that.
	waitMachineDeleted = 3 * time.Minute
	// waitMachineFailed is how long an induced failure gets to be recorded as
	// one. It is the longest single wait because giving up is deliberately not
	// the first thing the reconciler does: it retries with backoff first.
	waitMachineFailed = 6 * time.Minute
	// waitReconciliation is the closing inventory listing, which is two calls
	// to the cluster and a comparison.
	waitReconciliation = 5 * time.Minute
	// waitCleanup is the harness's, not the scenario's. It runs after the
	// scenario has finished or failed and it must not be cut short: what it is
	// doing is deleting virtual machines, a pool and an installation from
	// somebody's real cluster and organisation.
	waitCleanup = 15 * time.Minute
	// waitSetup covers everything before the first cycle: the admin, the
	// installation, the provider and the pools.
	waitSetup = 5 * time.Minute
)

// qualificationCycles is the number of full create, enrol, run, drain and
// delete cycles the procedure asks for. It is a constant rather than a setting
// because the evidence is "p95 of 20": a run that chose its own denominator
// could report a p95 of three and still call itself a qualification.
const qualificationCycles = 20

// cycleBudget is one full cycle's worst case.
const cycleBudget = waitFirstMachine + waitMachineCreated + waitMachineReady +
	waitJobCompleted + waitMachineDrained + waitMachineDeleted

// The five fault cases, each budgeted as what it actually does rather than as a
// share of the whole: a restart adds a controller start to a cycle, an induced
// bootstrap failure never reaches a job, and an induced delete failure pays for
// the delete twice.
const (
	scaleFromZeroBudget    = cycleBudget
	multiPoolBurstBudget   = cycleBudget + waitMachineCreated
	restartMidCreateBudget = cycleBudget + waitControllerHealthy
	bootstrapFailureBudget = waitFirstMachine + waitMachineCreated + waitMachineFailed + waitMachineDeleted
	deleteFailureBudget    = cycleBudget + waitMachineDeleted
)

// qualificationBudget is the longest a complete run may legitimately take,
// cleanup included. The Makefile's -timeout must exceed it, and so must
// whatever deadline `go test` was actually given.
const qualificationBudget = waitSetup + waitControllerHealthy + waitProviderChecked +
	qualificationCycles*cycleBudget +
	scaleFromZeroBudget + multiPoolBurstBudget + restartMidCreateBudget +
	bootstrapFailureBudget + deleteFailureBudget +
	waitReconciliation + waitCleanup

// reserveForTheEnd is what must still be left when a cycle begins, so that a
// run which cannot fit another one stops and reconciles instead of being killed
// part-way through building a machine.
//
// This is the whole reason the harness looks at its own deadline. A cycle
// interrupted by `go test`'s timeout leaves a VM on the cluster and no
// reconciliation to notice it, which is precisely the failure this procedure
// exists to detect.
const reserveForTheEnd = waitReconciliation + waitCleanup

package proxmox

import (
	"os"
	"path/filepath"
	"regexp"
	"testing"
	"time"
)

// The harness's waits must fit inside the timeout its Makefile target gives it.
//
// A qualification run that is killed by `go test` does not merely fail: it
// fails having left virtual machines on somebody's cluster, and it throws away
// the closing reconciliation, which is the step that would have found them.
// This test has no build tag, so it runs on every ordinary `go test ./...`
// rather than only where there is a cluster to run against.
func TestTheQualificationFitsInsideItsMakefileTimeout(t *testing.T) {
	root := repoRoot(t)
	raw, err := os.ReadFile(filepath.Join(root, "Makefile"))
	if err != nil {
		t.Fatalf("reading the Makefile: %v", err)
	}

	// Only the targets that run this package: the e2e harness next door has its
	// own budget and its own, much shorter, timeout.
	re := regexp.MustCompile(`(?m)^\s+\$\(GO\) test .*-tags e2e.*-timeout (\S+) \./test/e2e/proxmox`)
	matches := re.FindAllStringSubmatch(string(raw), -1)
	if len(matches) == 0 {
		t.Fatal("no `go test -tags e2e ... -timeout <d> ./test/e2e/proxmox` line found in the Makefile; " +
			"if the target was renamed, update this test rather than deleting it")
	}
	for _, m := range matches {
		limit, err := time.ParseDuration(m[1])
		if err != nil {
			t.Fatalf("the Makefile's proxmox timeout %q is not a duration: %v", m[1], err)
		}
		if limit <= qualificationBudget {
			t.Errorf("the Makefile allows %s but the qualification's waits and cleanup need %s; "+
				"the run would be killed with machines still on the cluster", limit, qualificationBudget)
		}
	}
}

// Every wait has to be inside a budget, or adding one moves the real worst case
// without moving the number the Makefile is checked against.
//
// The arithmetic is spelled out here rather than trusted: the cycle budget is
// the one that is multiplied by twenty, so a wait left out of it is twenty
// times as wrong as it looks.
func TestEveryWaitIsInsideTheBudgetItIsCheckedBy(t *testing.T) {
	sum := waitFirstMachine + waitMachineCreated + waitMachineReady +
		waitJobCompleted + waitMachineDrained + waitMachineDeleted
	if cycleBudget != sum {
		t.Errorf("cycleBudget is %s but its phases add up to %s; a phase was added without being budgeted for", cycleBudget, sum)
	}
	// The fault cases and the fixed costs, against the whole.
	whole := waitSetup + waitControllerHealthy + waitProviderChecked +
		qualificationCycles*cycleBudget +
		scaleFromZeroBudget + multiPoolBurstBudget + restartMidCreateBudget +
		bootstrapFailureBudget + deleteFailureBudget +
		waitReconciliation + waitCleanup
	if qualificationBudget != whole {
		t.Errorf("qualificationBudget is %s but its parts add up to %s", qualificationBudget, whole)
	}
	if qualificationCycles != 20 {
		t.Errorf("the procedure asks for 20 cycles and this build would run %d; "+
			"the evidence is written as p95 of 20 and a different denominator is a different claim", qualificationCycles)
	}
}

// The reserve must cover everything that happens after the last cycle, or a run
// that stops in time still has no time to tidy up and reconcile.
func TestTheReserveCoversTheStepsThatRunAfterTheLastCycle(t *testing.T) {
	if reserveForTheEnd < waitReconciliation+waitCleanup {
		t.Errorf("the reserve is %s but the reconciliation and cleanup need %s; "+
			"a run that stopped in time would still be killed during cleanup", reserveForTheEnd, waitReconciliation+waitCleanup)
	}
}

// repoRoot walks up to the directory holding go.mod.
func repoRoot(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		dir = filepath.Dir(dir)
	}
	t.Fatal("could not find the repository root from the test's working directory")
	return ""
}

// Package proxmox is the live qualification harness for the Proxmox VE
// provider: twenty create, enrol, run, drain and delete cycles against a real
// hypervisor, the five fault cases the roadmap names, and a closing inventory
// reconciliation that fails on any owned resource nobody can account for.
//
// It needs a disposable Proxmox VE cluster -- a VMID range reserved for this
// and nothing else, an API token, a prepared template, a storage -- and a
// GitHub installation that can queue real jobs, because a machine that never
// ran a job has not been qualified for anything. Without those it skips itself,
// naming every one that is missing; see README.md for the variables and
// roadmap/validation/proxmox-qualification.md for the procedure and the
// evidence it produces.
//
// **Fixture success is not live qualification.** The fixture suite -- the whole
// machine lifecycle against provider.Fake, and the Proxmox client against an
// httptest server -- proves the logic and the wire format and proves nothing
// whatever about a hypervisor. Only a green run of this harness against a real
// cluster, with its evidence filled into the qualification record, is that.
//
// Only the scenarios themselves are behind the "e2e" build tag. The budget, the
// ledger, the preflight, the inventory check and the evidence record are
// ordinary code with ordinary tests, so that a harness that cannot be run here
// is still compiled, vetted and tested here: the failure designed out is a
// qualification harness that has quietly stopped building, discovered by the
// one person who had a cluster and an afternoon.
package proxmox

//go:build e2e

package proxmox

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

// The machinery the scenarios stand on: a real controller process, an API
// client that speaks to it as an administrator, and the polling that watches a
// machine become a host and go away again.
//
// It is a separate file from the scenarios for the reason test/drill's is: the
// scenarios should read as the procedure, and the procedure is not "start a
// process, scrape a setup token, mint an API token".

// ---------------------------------------------------------------------------
// The controller
// ---------------------------------------------------------------------------

// controllerProcess is one real zoomies controller, started from the built
// binary against a throwaway database.
//
// It binds a routable address rather than loopback, which every other harness in
// this repository can avoid and this one cannot: the machines it builds are on
// the cluster's network, and a controller they cannot reach is a controller they
// can never enrol with. That makes authentication mandatory -- the validator
// refuses to disable it on a public bind, and rightly -- so this also does the
// first-administrator dance and mints itself an API token.
type controllerProcess struct {
	t     *testing.T
	e     env
	dir   string
	base  string
	port  int
	token string

	mu      sync.Mutex
	logs    bytes.Buffer
	cmd     *exec.Cmd
	cancel  context.CancelFunc
	cookies *cookieJar
}

func startController(t *testing.T, e env) *controllerProcess {
	t.Helper()
	u, err := url.Parse(e.controllerURL)
	if err != nil || u.Port() == "" {
		t.Fatalf("the controller URL %q has no port to bind", e.controllerURL)
	}
	port, err := strconv.Atoi(u.Port())
	if err != nil {
		t.Fatalf("the controller URL %q has no numeric port", e.controllerURL)
	}
	c := &controllerProcess{t: t, e: e, dir: t.TempDir(), port: port,
		base: fmt.Sprintf("http://127.0.0.1:%d", port)}
	c.start()
	t.Cleanup(c.stop)
	c.authenticate()
	return c
}

// start launches the process and waits for it to answer. It is called again by
// restart, so it must be safe to run against a database that already has rows.
func (c *controllerProcess) start() {
	c.t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	cmd := exec.CommandContext(ctx, builtBinary(), "controller")
	cmd.Env = append(os.Environ(),
		// 0.0.0.0, because the guests are elsewhere. This is the whole reason
		// the rest of the authentication dance below exists.
		fmt.Sprintf("ZOOMIES_BIND=0.0.0.0:%d", c.port),
		"ZOOMIES_EXTERNAL_URL="+c.e.controllerURL,
		// Plain http on a lab network, so the session cookie must not be
		// Secure or it would be thrown away and every login would appear to do
		// nothing. The configuration warns about this; the warning is correct.
		"ZOOMIES_COOKIE_SECURE=false",
		"ZOOMIES_DB_PATH="+filepath.Join(c.dir, "zoomies.db"),
		"ZOOMIES_STATE_DIR="+c.dir,
		"ZOOMIES_CONFIG_DIR="+c.dir,
		"ZOOMIES_WORK_DIR="+filepath.Join(c.dir, "work"),
		// No agent here. A controller that could run the jobs itself would
		// never need a machine, and "scale from zero" would prove nothing.
		"ZOOMIES_AGENT_EMBEDDED=false",
		// This host is not reachable from GitHub, so the queue is discovered by
		// polling. The webhook path is covered by the integration tests.
		"ZOOMIES_POLL_FALLBACK=true",
		"ZOOMIES_POLL_INTERVAL=10s",
		"ZOOMIES_PROVIDER_ENABLED=true",
		"ZOOMIES_PROVIDER_INTERVAL=10s",
		// Nothing waits before buying: the procedure times the fleet's
		// response, and a delay would be measured as the hypervisor's.
		"ZOOMIES_PROVIDER_SCALE_UP_DELAY=0",
		// Long, because this harness decides when a machine is drained and
		// deleted. A fleet tidying up underneath the measurements would make
		// every timing somebody else's.
		"ZOOMIES_PROVIDER_IDLE_TIMEOUT=45m",
		"ZOOMIES_PROVIDER_SCALE_DOWN_COOLDOWN=45m",
		"ZOOMIES_LOG_FORMAT=text",
		"ZOOMIES_LOG_LEVEL=debug",
	)
	cmd.Stdout, cmd.Stderr = &lockedWriter{c: c}, &lockedWriter{c: c}
	if err := cmd.Start(); err != nil {
		cancel()
		c.t.Fatalf("starting the controller: %v", err)
	}
	c.mu.Lock()
	c.cmd, c.cancel = cmd, cancel
	c.mu.Unlock()

	waitFor(c.t, waitControllerHealthy, "the controller to become healthy", func() bool {
		resp, err := http.Get(c.base + "/healthz")
		if err != nil {
			return false
		}
		resp.Body.Close()
		return resp.StatusCode == http.StatusOK
	})
}

// stop ends the process. It is the cleanup, so it must not fail the test on the
// way out; a controller that has already died is the normal case after a kill.
func (c *controllerProcess) stop() {
	c.mu.Lock()
	cancel, cmd := c.cancel, c.cmd
	c.cancel, c.cmd = nil, nil
	c.mu.Unlock()
	if cancel == nil {
		return
	}
	cancel()
	if cmd != nil {
		_ = cmd.Wait()
	}
}

// restart stops and starts the same controller against the same database. It is
// what the restart-mid-create case is: the rows are all the new process has, and
// what it does with them is the whole question.
func (c *controllerProcess) restart() {
	c.t.Helper()
	c.stop()
	c.start()
}

// output is everything the controller has printed, for a failure to quote.
func (c *controllerProcess) output() string {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.logs.String()
}

type lockedWriter struct{ c *controllerProcess }

func (w *lockedWriter) Write(p []byte) (int, error) {
	w.c.mu.Lock()
	defer w.c.mu.Unlock()
	return w.c.logs.Write(p)
}

var setupTokenRE = regexp.MustCompile(`setup token: (\S+)`)

// authenticate creates the first administrator and mints an API token.
//
// The setup token is read out of the controller's own log, which is exactly the
// proof of ownership the design intends: "no account exists yet" is a condition
// an attacker can also satisfy, and holding the log is what distinguishes the
// operator from them.
func (c *controllerProcess) authenticate() {
	c.t.Helper()
	password := "qualification-" + randomHex(12)

	var setup string
	waitFor(c.t, waitControllerHealthy, "the setup token to be printed", func() bool {
		m := setupTokenRE.FindStringSubmatch(c.output())
		if len(m) == 2 {
			setup = m[1]
		}
		return setup != ""
	})

	// The bootstrap and the login carry an Origin of this controller's own
	// address: a client that sends none is treated as a plain one, but one that
	// then holds a session cookie is treated as a browser, and the cross-site
	// check would refuse it.
	post := func(path string, body any, out any) {
		status, raw, err := call(http.MethodPost, c.base+path, body, out, map[string]string{"Origin": c.base}, c.jar())
		if err != nil {
			c.t.Fatalf("POST %s: %v", path, err)
		}
		if status >= 300 {
			c.t.Fatalf("POST %s: %d\n%s", path, status, raw)
		}
	}
	post("/api/v1/auth/bootstrap", map[string]any{
		"username": "qualification", "password": password, "setup_token": setup,
	}, nil)
	post("/api/v1/auth/login", map[string]any{"username": "qualification", "password": password}, nil)

	var token struct {
		Token string `json:"token"`
	}
	post("/api/v1/tokens", map[string]any{
		"name": "proxmox-qualification", "role": "admin", "expires_in": "24h",
	}, &token)
	if token.Token == "" {
		c.t.Fatal("the API token came back empty, so nothing else in this run could be authorised")
	}
	c.token = token.Token
}

// jar is this process's cookie jar, held across the two cookie-authenticated
// calls above and used by nothing else: every other call in this harness is a
// bearer token, which the cross-site check exempts because a browser cannot send
// one.
func (c *controllerProcess) jar() *cookieJar {
	if c.cookies == nil {
		c.cookies = &cookieJar{}
	}
	return c.cookies
}

// ---------------------------------------------------------------------------
// The API client
// ---------------------------------------------------------------------------

type client struct {
	t    *testing.T
	base string
	tok  string
}

func newClient(t *testing.T, c *controllerProcess) *client {
	return &client{t: t, base: c.base + "/api/v1", tok: c.token}
}

func (c *client) headers() map[string]string {
	return map[string]string{"Authorization": "Bearer " + c.tok}
}

func (c *client) do(method, path string, body, out any) {
	c.t.Helper()
	status, raw, err := call(method, c.base+path, body, out, c.headers(), nil)
	if err != nil {
		c.t.Fatalf("%s %s: %v", method, path, err)
	}
	if status >= 300 {
		c.t.Fatalf("%s %s: %d\n%s", method, path, status, raw)
	}
}

func (c *client) get(path string, out any)         { c.do(http.MethodGet, path, nil, out) }
func (c *client) post(path string, body, out any)  { c.do(http.MethodPost, path, body, out) }
func (c *client) patch(path string, body, out any) { c.do(http.MethodPatch, path, body, out) }
func (c *client) del(path string)                  { c.do(http.MethodDelete, path, nil, nil) }

// try is the cleanup's client: a failure is reported and moved past rather than
// fatal, because the next step may still remove something and a t.Fatal inside a
// cleanup would skip the rest of it.
func (c *client) try(method, path string, body, out any) bool {
	c.t.Helper()
	status, raw, err := call(method, c.base+path, body, out, c.headers(), nil)
	if err != nil {
		c.t.Errorf("cleanup: %s %s: %v", method, path, err)
		return false
	}
	if status >= 300 && status != http.StatusNotFound {
		c.t.Errorf("cleanup: %s %s: %d\n%s", method, path, status, raw)
		return false
	}
	return true
}

// cookieJar is the two cookies the bootstrap and login exchange. net/http/cookiejar
// would do, and this is four lines and carries nothing across hosts.
type cookieJar struct{ cookies []*http.Cookie }

func call(method, rawURL string, body, out any, headers map[string]string, jar *cookieJar) (int, []byte, error) {
	var r io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return 0, nil, fmt.Errorf("marshalling the request body: %w", err)
		}
		r = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, rawURL, r)
	if err != nil {
		return 0, nil, fmt.Errorf("building the request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	if jar != nil {
		for _, c := range jar.cookies {
			req.AddCookie(c)
		}
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, nil, err
	}
	defer resp.Body.Close()
	if jar != nil {
		jar.cookies = append(jar.cookies, resp.Cookies()...)
	}
	raw, _ := io.ReadAll(resp.Body)
	if resp.StatusCode < 300 && out != nil && len(raw) > 0 {
		if err := json.Unmarshal(raw, out); err != nil {
			return resp.StatusCode, raw, fmt.Errorf("decoding the response: %w", err)
		}
	}
	return resp.StatusCode, raw, nil
}

// ---------------------------------------------------------------------------
// What the API says about a machine
// ---------------------------------------------------------------------------

// machineView is the part of GET /machines this procedure reads. It is written
// out rather than imported from internal/controller so that a field renamed in
// the API breaks this harness loudly, here, rather than silently becoming a zero
// value that every assertion then passes on.
type machineView struct {
	ID             string `json:"id"`
	Name           string `json:"name"`
	State          string `json:"state"`
	Message        string `json:"message"`
	ProviderID     string `json:"provider_id"`
	PoolID         string `json:"pool_id"`
	ResourceZone   string `json:"resource_zone"`
	ResourceID     string `json:"resource_id"`
	HostID         string `json:"host_id"`
	HostName       string `json:"host_name"`
	Address        string `json:"address"`
	ProviderError  string `json:"provider_error"`
	BootstrapError string `json:"bootstrap_error"`
	Attempts       int    `json:"attempts"`
	SafeToDelete   bool   `json:"safe_to_delete"`
	Timeline       []struct {
		Phase string    `json:"phase"`
		At    time.Time `json:"at"`
	} `json:"timeline"`
	DeletedAt *time.Time `json:"deleted_at"`
}

// vmid is the identifier the provider gave this machine, or zero before it has
// one.
func (m machineView) vmid() int {
	n, err := strconv.Atoi(m.ResourceID)
	if err != nil {
		return 0
	}
	return n
}

// at is when the machine reached one phase, from the timeline the API renders.
// The timeline is the controller's own timestamps rather than this harness's
// observations, so a timing taken from it is not limited by how often this polls.
func (m machineView) at(phase string) (time.Time, bool) {
	for _, e := range m.Timeline {
		if e.Phase == phase {
			return e.At, true
		}
	}
	return time.Time{}, false
}

// complaint is what a machine says is wrong with it, naming which of the two
// independent systems complained. They are separate columns for a reason: the
// hypervisor and the guest are different things to go and look at.
func (m machineView) complaint() string {
	var parts []string
	if m.ProviderError != "" {
		parts = append(parts, "provider: "+m.ProviderError)
	}
	if m.BootstrapError != "" {
		parts = append(parts, "bootstrap: "+m.BootstrapError)
	}
	if m.Message != "" {
		parts = append(parts, m.Message)
	}
	if len(parts) == 0 {
		return "no complaint recorded"
	}
	return strings.Join(parts, "; ")
}

type machineList struct {
	Items []machineView `json:"items"`
}

// machines is every machine this fleet has, deleted ones included. Deleted rows
// are what prove a delete was confirmed rather than merely issued.
func (c *client) machines() []machineView {
	c.t.Helper()
	var out machineList
	c.get("/machines?include_deleted=true&limit=200", &out)
	return out.Items
}

func (c *client) machine(id string) machineView {
	c.t.Helper()
	var m machineView
	c.get("/machines/"+id, &m)
	return m
}

// watch polls one machine until a condition holds, recording when each state was
// first seen on the way.
//
// The observations are how the two phases with no server-side timestamp are
// timed -- a guest that has begun answering, a machine that has begun draining
// -- and they are bounded by the poll interval, which the evidence says out
// loud. Everything else is read from the timeline, which is exact.
type watch struct {
	firstSeen map[string]time.Time
	last      machineView
}

func newWatch() *watch { return &watch{firstSeen: map[string]time.Time{}} }

func (w *watch) seen(state string) (time.Time, bool) {
	at, ok := w.firstSeen[state]
	return at, ok
}

// watchInterval is how often a machine is asked about. It is the resolution of
// every observed timing in the evidence, so it is recorded there.
const watchInterval = 2 * time.Second

// until polls until cond holds or the limit passes. It returns whether the
// condition held, rather than failing: several cases here are about a machine
// that is expected not to get somewhere, and those want to say so in their own
// words.
func (w *watch) until(c *client, id string, limit time.Duration, cond func(machineView) bool) bool {
	c.t.Helper()
	deadline := time.Now().Add(limit)
	for {
		m := c.machine(id)
		w.last = m
		if _, ok := w.firstSeen[m.State]; !ok {
			w.firstSeen[m.State] = time.Now()
		}
		if cond(m) {
			return true
		}
		if time.Now().After(deadline) {
			return false
		}
		time.Sleep(watchInterval)
	}
}

// ---------------------------------------------------------------------------
// Waiting, and the deadline this harness is under
// ---------------------------------------------------------------------------

func waitFor(t *testing.T, limit time.Duration, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(limit)
	for {
		if cond() {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("timed out after %s waiting for %s", limit, what)
		}
		time.Sleep(3 * time.Second)
	}
}

// remaining is how much of `go test`'s own deadline is left, and whether there
// is one at all.
func remaining(t *testing.T) (time.Duration, bool) {
	d, ok := t.Deadline()
	if !ok {
		return 0, false
	}
	return time.Until(d), true
}

// assertTimeToFinish refuses to go on unless there is time for what is left plus
// the reconciliation and the cleanup.
//
// This is the guard budget.go exists for, made to bite at run time as well as in
// CI. A run killed by `go test` mid-cycle leaves a virtual machine on the
// cluster and skips the reconciliation that would have found it, so a harness
// that can see it will not finish should stop while it can still tidy up and say
// why.
func assertTimeToFinish(t *testing.T, need time.Duration, what string) {
	t.Helper()
	left, ok := remaining(t)
	if !ok {
		return
	}
	if left < need+reserveForTheEnd {
		t.Fatalf("stopping before %s: it needs %s and the reconciliation and cleanup need %s, "+
			"but this run has %s left. Give `go test` a longer -timeout (make test-e2e-proxmox uses one "+
			"that fits the whole procedure); carrying on would leave machines on the cluster and never reconcile them",
			what, need, reserveForTheEnd, left.Round(time.Second))
	}
}

// ---------------------------------------------------------------------------
// GitHub
// ---------------------------------------------------------------------------

// dispatchWorkflow triggers the fixture workflow and returns the marker it was
// dispatched with. The label goes with the marker so the workflow asks for this
// run's pool rather than a shared one.
func dispatchWorkflow(t *testing.T, e env, label string) string {
	t.Helper()
	marker := fmt.Sprintf("zoomies-pve-%s-%d", label, time.Now().UnixNano())
	cmd := exec.Command("gh", "workflow", "run", e.workflow,
		"--repo", e.repo, "-f", "marker="+marker, "-f", "label="+label)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("triggering %s in %s: %v\n%s", e.workflow, e.repo, err, out)
	}
	return marker
}

// githubRunnersWithLabel lists the registrations GitHub currently holds that
// carry one label.
//
// It asks GitHub rather than Zoomies, and that is the point: the failure this
// looks for is a registration left behind after a machine is destroyed, and the
// row says "removed" exactly when Zoomies believes it removed it -- which is the
// belief under test.
func githubRunnersWithLabel(e env, label string) ([]string, error) {
	path := "/orgs/" + e.target + "/actions/runners"
	if e.targetType == "repo" {
		path = "/repos/" + e.target + "/actions/runners"
	}
	out, err := exec.Command("gh", "api", "--paginate", path).Output()
	if err != nil {
		return nil, fmt.Errorf("asking GitHub for %s's runners: %w", e.target, err)
	}
	dec := json.NewDecoder(strings.NewReader(string(out)))
	var found []string
	for {
		var page struct {
			Runners []struct {
				ID     int64  `json:"id"`
				Name   string `json:"name"`
				Status string `json:"status"`
				Labels []struct {
					Name string `json:"name"`
				} `json:"labels"`
			} `json:"runners"`
		}
		if err := dec.Decode(&page); err != nil {
			break
		}
		for _, r := range page.Runners {
			for _, l := range r.Labels {
				if l.Name == label {
					found = append(found, fmt.Sprintf("%s (id %d, %s)", r.Name, r.ID, r.Status))
					break
				}
			}
		}
	}
	return found, nil
}

// ---------------------------------------------------------------------------
// The one call in this harness that changes the cluster
// ---------------------------------------------------------------------------

// setProtection turns Proxmox's own protection flag on or off, which is how the
// induced delete failure is induced: a protected guest refuses to be destroyed,
// and the fleet has to notice, record the refusal and try again once it is
// cleared.
//
// It lives in the tagged half deliberately. inventory.go is read-only, because
// the closing reconciliation must not be able to change what it is measuring;
// this is the scenario's hand on the cluster, not the check's.
func (c *Cluster) setProtection(ctx context.Context, node string, vmid int, on bool) error {
	form := url.Values{"protection": {map[bool]string{true: "1", false: "0"}[on]}}
	path := fmt.Sprintf("%s/nodes/%s/qemu/%d/config", c.base, url.PathEscape(node), vmid)
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, path, strings.NewReader(form.Encode()))
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", c.auth)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	resp, err := c.http.Do(req)
	if err != nil {
		return fmt.Errorf("setting protection on VM %d: %w", vmid, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 2048))
		return fmt.Errorf("setting protection on VM %d: %s: %s", vmid, resp.Status, strings.TrimSpace(string(body)))
	}
	return nil
}

// ---------------------------------------------------------------------------
// Odds and ends
// ---------------------------------------------------------------------------

// newRunID is this run's identity. It is short, lower case and alphanumeric
// because it becomes part of a GitHub runner label and a pool name.
func newRunID() string { return randomHex(4) }

func randomHex(n int) string {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		// A run that cannot read the system's randomness has bigger problems,
		// and a fixed identity would make two runs collide on one organisation.
		panic("cannot read randomness for this run's identity: " + err.Error())
	}
	return hex.EncodeToString(b)[:n]
}

package proxmox

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

// The inventory half: what is actually on the cluster, and whether every owned
// thing on it can be accounted for.
//
// It speaks the Proxmox API itself rather than through internal/provider/proxmox,
// and that duplication is the point. The question this answers is "did the code
// under test leave anything behind", and a check that asks the code under test
// cannot answer it: a bug in how the provider recognises its own guests would
// hide exactly the guests it failed to delete. The end-to-end harness next door
// asks GitHub and the Docker daemon directly for the same reason.
//
// Everything here is read-only. Nothing in this file can change a cluster.

// fleetTag and machineNamePrefix are how an owned guest is recognised. They are
// written out rather than imported so that this check has its own idea of what
// the fleet's marks look like; a test holds the two definitions equal, which is
// the whole value of writing them twice.
const (
	fleetTag          = "zoomies"
	machineNamePrefix = "zoomies-mach-"
)

// Range is the block of VMIDs this qualification was given. Nothing outside it
// is this procedure's business -- a guest at 150 on a cluster somebody else also
// uses is not evidence of anything.
type Range struct{ Min, Max int }

func (r Range) contains(vmid int) bool { return vmid >= r.Min && vmid <= r.Max }
func (r Range) String() string         { return fmt.Sprintf("%d-%d", r.Min, r.Max) }

// ClusterOptions is how to reach one Proxmox VE cluster read-only.
type ClusterOptions struct {
	// Endpoint is the cluster as the operator wrote it: https://pve:8006.
	Endpoint string
	// Token is the whole credential -- "user@realm!tokenid=secret" -- or just
	// the identifier when Secret is given separately.
	Token  string
	Secret string
	// CAPEMFile pins the cluster's own certificate, which is what a Proxmox
	// cluster usually has. Insecure turns verification off; it is offered
	// because a homelab cluster's certificate is its own and refusing would
	// mean the qualification could not be run, and it is reported in the
	// evidence so that a run made without verification says so.
	CAPEMFile string
	Insecure  bool
}

// Cluster is a read-only Proxmox VE client.
type Cluster struct {
	base     string
	auth     string
	insecure bool
	http     *http.Client
}

// NewCluster builds the client. It never dials: an unreachable cluster is
// something the preflight reports, not something a constructor panics about.
func NewCluster(opts ClusterOptions) (*Cluster, error) {
	endpoint := strings.TrimRight(strings.TrimSpace(opts.Endpoint), "/")
	if endpoint == "" {
		return nil, fmt.Errorf("no cluster endpoint")
	}
	if !strings.Contains(endpoint, "://") {
		endpoint = "https://" + endpoint
	}
	u, err := url.Parse(endpoint)
	if err != nil {
		return nil, fmt.Errorf("%q is not an address: %w", opts.Endpoint, err)
	}
	if u.Scheme != "https" {
		// A hypervisor credential over plain HTTP is a hypervisor credential on
		// the wire. The provider refuses this too.
		return nil, fmt.Errorf("%q is not https; a Proxmox API token must not cross a network in the clear", opts.Endpoint)
	}
	if u.Port() == "" {
		u.Host += ":8006"
	}

	token, secret := strings.TrimSpace(opts.Token), strings.TrimSpace(opts.Secret)
	if secret == "" {
		id, rest, ok := strings.Cut(token, "=")
		if !ok || strings.TrimSpace(rest) == "" {
			return nil, fmt.Errorf("the token is not user@realm!tokenid=secret; " +
				"paste it whole, or give the secret separately")
		}
		token, secret = strings.TrimSpace(id), strings.TrimSpace(rest)
	}
	if !strings.Contains(token, "!") {
		return nil, fmt.Errorf("%q is not a token identifier; it is user@realm!tokenid", token)
	}

	tlsCfg := &tls.Config{MinVersion: tls.VersionTLS12, InsecureSkipVerify: opts.Insecure}
	if opts.CAPEMFile != "" {
		pem, err := os.ReadFile(opts.CAPEMFile)
		if err != nil {
			return nil, fmt.Errorf("reading the cluster's CA certificate %s: %w", opts.CAPEMFile, err)
		}
		pool := x509.NewCertPool()
		if !pool.AppendCertsFromPEM(pem) {
			return nil, fmt.Errorf("%s holds no certificate this can use", opts.CAPEMFile)
		}
		tlsCfg.RootCAs = pool
	}
	return &Cluster{
		base:     u.String() + "/api2/json",
		auth:     "PVEAPIToken=" + token + "=" + secret,
		insecure: opts.Insecure,
		http: &http.Client{
			Timeout:   30 * time.Second,
			Transport: &http.Transport{TLSClientConfig: tlsCfg},
		},
	}, nil
}

// Verified reports whether this client checked the cluster's certificate. The
// evidence says so either way: a qualification run with verification off is
// still a qualification, but it is a different one.
func (c *Cluster) Verified() bool { return !c.insecure }

// get reads one endpoint. Proxmox wraps every answer in {"data": ...}.
func (c *Cluster) get(ctx context.Context, path string, out any) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.base+path, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", c.auth)
	resp, err := c.http.Do(req)
	if err != nil {
		// The credential is in the header, and an http.Client error quotes the
		// URL but never the headers; the message is safe as it stands.
		return fmt.Errorf("GET %s: %w", path, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		return fmt.Errorf("GET %s: %s", path, resp.Status)
	}
	var body struct {
		Data json.RawMessage `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return fmt.Errorf("decoding %s: %w", path, err)
	}
	if out == nil {
		return nil
	}
	if err := json.Unmarshal(body.Data, out); err != nil {
		return fmt.Errorf("decoding %s's data: %w", path, err)
	}
	return nil
}

// Version is what the cluster says it is, verbatim. "It worked" is worth little
// without "against what", and the qualification record has a row for it.
func (c *Cluster) Version(ctx context.Context) (string, error) {
	var v struct {
		Version string `json:"version"`
		Release string `json:"release"`
		RepoID  string `json:"repoid"`
	}
	if err := c.get(ctx, "/version", &v); err != nil {
		return "", err
	}
	out := v.Version
	if v.Release != "" && !strings.Contains(out, v.Release) {
		out += "/" + v.Release
	}
	if v.RepoID != "" {
		out += " (" + v.RepoID + ")"
	}
	return out, nil
}

// Guest is one virtual machine as the cluster lists it.
type Guest struct {
	VMID     int    `json:"vmid"`
	Node     string `json:"node"`
	Name     string `json:"name"`
	Status   string `json:"status"`
	Type     string `json:"type"`
	Template int    `json:"template"`
	Tags     string `json:"tags"`
	Pool     string `json:"pool"`
}

// Ours reports whether this guest wears one of the fleet's marks. It is a
// hint and not proof -- anybody with configuration rights can write both marks
// -- but a guest wearing them that nothing can account for is the finding this
// whole procedure is looking for.
func (g Guest) Ours() bool {
	if strings.HasPrefix(strings.ToLower(g.Name), machineNamePrefix) {
		return true
	}
	for _, t := range strings.FieldsFunc(g.Tags, func(r rune) bool {
		return r == ';' || r == ',' || r == ' '
	}) {
		if strings.EqualFold(strings.TrimSpace(t), fleetTag) {
			return true
		}
	}
	return false
}

func (g Guest) String() string {
	return fmt.Sprintf("VM %d on %s (%q, %s)", g.VMID, g.Node, g.Name, g.Status)
}

// Volume is one disk image on the configured storage. A guest that is destroyed
// without its disks leaves these, which is the failure mode that costs an
// operator storage rather than CPU and is therefore the one nobody notices.
type Volume struct {
	VolID  string `json:"volid"`
	VMID   int    `json:"vmid"`
	Size   int64  `json:"size"`
	Format string `json:"format"`
}

// Inventory is one look at the cluster, stamped with when it was taken.
type Inventory struct {
	TakenAt  time.Time `json:"taken_at"`
	Endpoint string    `json:"endpoint"`
	Node     string    `json:"node"`
	Storage  string    `json:"storage"`
	Verified bool      `json:"tls_verified"`
	Guests   []Guest   `json:"guests"`
	Volumes  []Volume  `json:"volumes"`
}

// InRange is the guests inside a VMID range, templates excluded: a template is
// the thing machines are made from, not a machine.
func (inv Inventory) InRange(r Range) []Guest {
	var out []Guest
	for _, g := range inv.Guests {
		if r.contains(g.VMID) && g.Template == 0 {
			out = append(out, g)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].VMID < out[j].VMID })
	return out
}

// Take lists every guest on the cluster and every volume on one storage.
//
// One cluster-wide call for the guests rather than one per node, because a
// machine that ended up on a node nobody expected is exactly the kind of thing
// this is meant to find.
func (c *Cluster) Take(ctx context.Context, node, storage string) (Inventory, error) {
	inv := Inventory{TakenAt: time.Now().UTC(), Node: node, Storage: storage, Verified: c.Verified(), Endpoint: c.base}
	var guests []Guest
	if err := c.get(ctx, "/cluster/resources?type=vm", &guests); err != nil {
		return inv, err
	}
	inv.Guests = guests
	if storage != "" && node != "" {
		var volumes []Volume
		if err := c.get(ctx, "/nodes/"+url.PathEscape(node)+"/storage/"+url.PathEscape(storage)+"/content", &volumes); err != nil {
			return inv, err
		}
		inv.Volumes = volumes
	}
	return inv, nil
}

// Description reads one guest's configured description, which is where the
// ownership record is written. It is only asked for a guest already found in
// the range, because it is one call per guest.
func (c *Cluster) Description(ctx context.Context, node string, vmid int) (string, error) {
	var cfg struct {
		Description string `json:"description"`
		Tags        string `json:"tags"`
	}
	path := "/nodes/" + url.PathEscape(node) + "/qemu/" + strconv.Itoa(vmid) + "/config"
	if err := c.get(ctx, path, &cfg); err != nil {
		return "", err
	}
	return cfg.Description, nil
}

// ---------------------------------------------------------------------------
// The reconciliation
// ---------------------------------------------------------------------------

// Verdict is what one resource on the cluster turned out to be.
type Verdict string

const (
	// Accounted: a machine this run created and confirmed deleted, or a guest
	// that was in the range before the run and is not ours.
	Accounted Verdict = "accounted"
	// LeftBehind: ours, and the run that made it never removed it. Its ledger
	// names it, so the run knew about it -- this is litter, not a mystery.
	LeftBehind Verdict = "left_behind"
	// BelievedDeleted: ours, a ledger says it was deleted, and it is still
	// there. This is the worst of the three: the fleet's own accounting is
	// wrong, which is what the machine row exists to prevent.
	BelievedDeleted Verdict = "believed_deleted"
	// Unexplained: wearing this fleet's marks and named by no ledger at all.
	Unexplained Verdict = "unexplained"
	// Foreign: inside the range, not ours, and not there when the run began.
	// Reported rather than failed: the range was supposed to be reserved, and
	// somebody else using it is a finding for a person.
	Foreign Verdict = "foreign"
)

// Finding is one resource and what became of it.
type Finding struct {
	Verdict Verdict `json:"verdict"`
	VMID    int     `json:"vmid"`
	Node    string  `json:"node,omitempty"`
	Name    string  `json:"name,omitempty"`
	Detail  string  `json:"detail"`
	// RunID is the ledger that explains this resource, when one does.
	RunID string `json:"run_id,omitempty"`
}

// Reconciliation is the closing count, and the thing that decides
// qualification. Its one rule: no owned resource may be left unexplained.
type Reconciliation struct {
	TakenAt time.Time `json:"taken_at"`
	Range   Range     `json:"range"`
	Storage string    `json:"storage"`

	VMsAtStart  int `json:"vms_in_range_at_start"`
	VMsAtEnd    int `json:"vms_in_range_at_end"`
	Created     int `json:"machines_created"`
	Confirmed   int `json:"machines_confirmed_deleted"`
	DisksLeft   int `json:"disks_left_on_storage"`
	Unexplained int `json:"unexplained_owned_resources"`

	Findings []Finding `json:"findings"`
}

// OK is the whole verdict. An orphan found and deliberately left is a finding a
// person records; an orphan nobody noticed is a failure of this procedure
// rather than of the code, so anything owned and unaccounted for fails.
func (r Reconciliation) OK() bool { return r.Unexplained == 0 && r.DisksLeft == 0 }

// Reconcile accounts for every resource in the range against what the ledgers
// say was created.
//
// It is pure so that it can be tested without a cluster, which matters more
// than it sounds: this is the step that decides whether the qualification
// passed, and it would otherwise be the only step nobody could exercise until
// somebody had a hypervisor.
func Reconcile(inv Inventory, ledgers []LedgerRecord, r Range) Reconciliation {
	out := Reconciliation{TakenAt: inv.TakenAt, Range: r, Storage: inv.Storage}

	// What the runs say they did, keyed by the identifier the cluster uses.
	type claim struct {
		runID   string
		removed bool
		name    string
	}
	claims := map[int]claim{}
	preexisting := map[int]bool{}
	for _, led := range ledgers {
		for _, v := range led.PreexistingVMIDs {
			preexisting[v] = true
		}
		if led.Range.Min != 0 || led.Range.Max != 0 {
			out.VMsAtStart = len(led.PreexistingVMIDs)
		}
		for _, res := range led.Resources {
			if res.Kind != KindMachine || res.VMID == 0 {
				continue
			}
			out.Created++
			if res.RemovedAt != nil {
				out.Confirmed++
			}
			claims[res.VMID] = claim{runID: led.RunID, removed: res.RemovedAt != nil, name: res.Name}
		}
	}

	live := map[int]bool{}
	for _, g := range inv.InRange(r) {
		out.VMsAtEnd++
		live[g.VMID] = true
		c, claimed := claims[g.VMID]
		switch {
		case claimed && c.removed:
			out.Unexplained++
			out.Findings = append(out.Findings, Finding{
				Verdict: BelievedDeleted, VMID: g.VMID, Node: g.Node, Name: g.Name, RunID: c.runID,
				Detail: "the run recorded this machine as deleted and the guest is still on the cluster; " +
					"the fleet's accounting disagrees with the hypervisor",
			})
		case claimed:
			out.Unexplained++
			out.Findings = append(out.Findings, Finding{
				Verdict: LeftBehind, VMID: g.VMID, Node: g.Node, Name: g.Name, RunID: c.runID,
				Detail: "created by this run and never removed; delete it by hand and record why the run did not",
			})
		case g.Ours():
			out.Unexplained++
			out.Findings = append(out.Findings, Finding{
				Verdict: Unexplained, VMID: g.VMID, Node: g.Node, Name: g.Name,
				Detail: "wears this fleet's marks and no ledger names it; it belongs to another controller, " +
					"or to a run whose ledger was lost",
			})
		case preexisting[g.VMID]:
			out.Findings = append(out.Findings, Finding{
				Verdict: Accounted, VMID: g.VMID, Node: g.Node, Name: g.Name,
				Detail: "was in the range before the run began and is not ours",
			})
		default:
			out.Findings = append(out.Findings, Finding{
				Verdict: Foreign, VMID: g.VMID, Node: g.Node, Name: g.Name,
				Detail: "appeared in the reserved range during the run and is not ours; " +
					"the range was supposed to be reserved for this and nothing else",
			})
		}
	}

	// A guest a ledger claims, which the cluster no longer has, is the good
	// case and needs no row of its own. Its disks are another matter.
	for _, v := range inv.Volumes {
		if !r.contains(v.VMID) || live[v.VMID] {
			continue
		}
		c, claimed := claims[v.VMID]
		if !claimed {
			continue
		}
		out.DisksLeft++
		out.Findings = append(out.Findings, Finding{
			Verdict: LeftBehind, VMID: v.VMID, Name: v.VolID, RunID: c.runID,
			Detail: "the guest is gone and this disk image is still on " + inv.Storage +
				"; a destroy that did not take its disks costs storage rather than CPU, which is why nobody notices it",
		})
	}

	sort.SliceStable(out.Findings, func(i, j int) bool {
		if out.Findings[i].Verdict != out.Findings[j].Verdict {
			return out.Findings[i].Verdict < out.Findings[j].Verdict
		}
		return out.Findings[i].VMID < out.Findings[j].VMID
	})
	return out
}

package proxmox

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// A cluster that answers the three read-only calls preflight makes, and nothing
// else. Anything it is asked for beyond those fails the test: preflight's
// contract is that every call in it is a GET that changes nothing, and a fake
// that quietly served a POST would let that stop being true.
func fakeCluster(t *testing.T, guests []Guest, volumes []Volume) *Cluster {
	t.Helper()
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			t.Errorf("preflight made a %s to %s; it must change nothing", r.Method, r.URL.Path)
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		if got := r.Header.Get("Authorization"); !strings.HasPrefix(got, "PVEAPIToken=") {
			t.Errorf("Authorization = %q, want a PVEAPIToken", got)
		}
		write := func(v any) {
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{"data": v})
		}
		switch {
		case r.URL.Path == "/api2/json/version":
			write(map[string]string{"version": "8.2.4", "release": "8.2"})
		case r.URL.Path == "/api2/json/cluster/resources":
			write(guests)
		case strings.HasSuffix(r.URL.Path, "/content"):
			write(volumes)
		default:
			t.Errorf("preflight asked for %s, which it has no business reading", r.URL.Path)
			w.WriteHeader(http.StatusNotFound)
		}
	}))
	t.Cleanup(srv.Close)

	c, err := NewCluster(ClusterOptions{
		Endpoint: srv.URL, Token: "zoomies@pve!qualify=secret", Insecure: true,
	})
	if err != nil {
		t.Fatalf("building the cluster client: %v", err)
	}
	return c
}

func preflightEnv() env {
	return env{
		endpoint: "https://pve.example.com:8006", node: "pve1", storage: "local-lvm",
		templateID: 9000, vmidMin: 9100, vmidMax: 9199,
	}
}

// A cluster that is ready reports the facts the record needs and complains
// about nothing.
func TestAReadyClusterYieldsTheEvidenceRatherThanAComplaint(t *testing.T) {
	c := fakeCluster(t, []Guest{
		{VMID: 9000, Node: "pve1", Name: "ubuntu-2404-template", Type: "qemu", Template: 1, Status: "stopped"},
		{VMID: 101, Node: "pve1", Name: "somebody-elses-vm", Type: "qemu", Status: "running"},
	}, nil)

	facts, missing := preflightCluster(context.Background(), c, preflightEnv())
	if len(missing) > 0 {
		t.Fatalf("a ready cluster was refused: %v", missing)
	}
	// The release is appended only when it adds something: "8.2.4/8.2" would be
	// the same fact twice, and the version is a row somebody reads.
	if facts.Version != "8.2.4" {
		t.Errorf("version = %q, want the version without its redundant release", facts.Version)
	}
	if facts.TemplateName != "ubuntu-2404-template" {
		t.Errorf("template name = %q", facts.TemplateName)
	}
	// A guest outside the reserved range is none of this run's business, and
	// subtracting it at the end would excuse a leftover.
	if len(facts.PreexistingVMIDs) != 0 {
		t.Errorf("a guest outside the range was counted as pre-existing: %v", facts.PreexistingVMIDs)
	}
}

// A cluster that cannot be reached is one problem, not eleven.
//
// Every check below the first fails when the cluster is down, and listing them
// all buries the only sentence that matters.
func TestAClusterThatDoesNotAnswerIsOneProblemRatherThanEvery(t *testing.T) {
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
	}))
	t.Cleanup(srv.Close)
	c, err := NewCluster(ClusterOptions{Endpoint: srv.URL, Token: "u@pve!t=s", Insecure: true})
	if err != nil {
		t.Fatalf("building the client: %v", err)
	}

	_, missing := preflightCluster(context.Background(), c, preflightEnv())
	if len(missing) != 1 {
		t.Fatalf("an unreachable cluster produced %d complaints, want one:\n%s",
			len(missing), strings.Join(missing, "\n"))
	}
	if !strings.Contains(missing[0], "did not answer") {
		t.Errorf("the complaint does not say the cluster did not answer: %q", missing[0])
	}
}

// The template has to exist and has to be a template: the provider clones from
// one, and cloning a running guest is a different operation.
func TestATemplateThatIsAbsentOrIsNotATemplateStopsTheRun(t *testing.T) {
	t.Run("absent", func(t *testing.T) {
		c := fakeCluster(t, []Guest{{VMID: 500, Node: "pve1", Name: "other", Type: "qemu"}}, nil)
		_, missing := preflightCluster(context.Background(), c, preflightEnv())
		if !strings.Contains(strings.Join(missing, "\n"), "no template to clone") {
			t.Errorf("a missing template was not reported: %v", missing)
		}
	})
	t.Run("not a template", func(t *testing.T) {
		c := fakeCluster(t, []Guest{
			{VMID: 9000, Node: "pve1", Name: "not-a-template", Type: "qemu", Template: 0, Status: "running"},
		}, nil)
		_, missing := preflightCluster(context.Background(), c, preflightEnv())
		joined := strings.Join(missing, "\n")
		if !strings.Contains(joined, "is not a template") {
			t.Errorf("a running guest was accepted as a template: %v", missing)
		}
		if !strings.Contains(joined, "cloning a running guest is a different operation") {
			t.Errorf("the complaint does not say why that matters: %v", missing)
		}
	})
}

// A leftover in the reserved range makes the closing reconciliation
// meaningless: it could not tell this run's litter from the last run's. So it
// stops the run, and the message says to record it rather than just delete it.
func TestAnEarlierRunsLeftoverInTheRangeStopsTheQualification(t *testing.T) {
	c := fakeCluster(t, []Guest{
		{VMID: 9000, Node: "pve1", Name: "ubuntu-2404-template", Type: "qemu", Template: 1},
		{VMID: 9142, Node: "pve1", Name: "zoomies-mach-abc", Type: "qemu", Status: "running"},
	}, nil)

	facts, missing := preflightCluster(context.Background(), c, preflightEnv())
	joined := strings.Join(missing, "\n")
	if !strings.Contains(joined, "already wears this fleet's marks") {
		t.Fatalf("a leftover in the reserved range was accepted: %v", missing)
	}
	if !strings.Contains(joined, "record it in the qualification") {
		t.Errorf("the complaint says to delete it but not to record it: %v", missing)
	}
	// It is still counted, because the reconciliation subtracts what was there
	// before whether or not it should have been.
	if len(facts.PreexistingVMIDs) != 1 || facts.PreexistingVMIDs[0] != 9142 {
		t.Errorf("pre-existing = %v, want the leftover recorded", facts.PreexistingVMIDs)
	}
}

// A guest in the range that is not ours is recorded and not complained about:
// the range was supposed to be reserved, but somebody else's VM is a fact the
// reconciliation subtracts rather than a prerequisite this run failed.
func TestSomebodyElsesGuestInTheRangeIsCountedAndNotRefused(t *testing.T) {
	c := fakeCluster(t, []Guest{
		{VMID: 9000, Node: "pve1", Name: "ubuntu-2404-template", Type: "qemu", Template: 1},
		{VMID: 9150, Node: "pve1", Name: "database-01", Type: "qemu", Status: "running"},
	}, nil)

	facts, missing := preflightCluster(context.Background(), c, preflightEnv())
	if len(missing) > 0 {
		t.Fatalf("a stranger's VM in the range stopped the run: %v", missing)
	}
	if len(facts.Preexisting) != 1 || facts.PreexistingVMIDs[0] != 9150 {
		t.Errorf("it was not recorded as pre-existing: %v", facts.PreexistingVMIDs)
	}
}

// The broken template is optional, but naming one that does not exist is a
// typo that would be found at the fault case rather than here.
func TestABrokenTemplateThatDoesNotExistIsReportedBeforeAnythingIsBuilt(t *testing.T) {
	e := preflightEnv()
	e.brokenTemplateID = 9001
	c := fakeCluster(t, []Guest{
		{VMID: 9000, Node: "pve1", Name: "ubuntu-2404-template", Type: "qemu", Template: 1},
	}, nil)

	_, missing := preflightCluster(context.Background(), c, e)
	joined := strings.Join(missing, "\n")
	if !strings.Contains(joined, "ZOOMIES_PROXMOX_BROKEN_TEMPLATE") {
		t.Fatalf("a broken template that does not exist was accepted: %v", missing)
	}
	if !strings.Contains(joined, "leave it unset") {
		t.Errorf("the complaint does not say it is optional: %v", missing)
	}
}

// The node name is checked as the doubt it is, not asserted: a node with no
// guests at all is invisible to a guest listing, so a cluster that returned
// nothing must not be read as a wrong node name.
func TestAWrongNodeNameIsDoubtedAndAnEmptyClusterIsNot(t *testing.T) {
	e := preflightEnv()
	c := fakeCluster(t, []Guest{
		{VMID: 9000, Node: "pve2", Name: "ubuntu-2404-template", Type: "qemu", Template: 1},
	}, nil)
	_, missing := preflightCluster(context.Background(), c, e)
	if !strings.Contains(strings.Join(missing, "\n"), "check the node name") {
		t.Errorf("a node no guest is on was not doubted: %v", missing)
	}

	// No guests at all: the template is missing, but the node is not accused.
	empty := fakeCluster(t, nil, nil)
	_, missing = preflightCluster(context.Background(), empty, e)
	if strings.Contains(strings.Join(missing, "\n"), "check the node name") {
		t.Errorf("an empty cluster was read as a wrong node name: %v", missing)
	}
}

// The version is a row in the record, so it carries the release when the
// release says something the version does not -- and does not repeat it when it
// does not.
func TestTheRecordedVersionCarriesTheReleaseOnlyWhenItAddsSomething(t *testing.T) {
	for _, tc := range []struct{ version, release, want string }{
		{"8.2.4", "8.2", "8.2.4"},
		{"8.2.4", "", "8.2.4"},
		{"pve-manager/8.2.4", "bookworm", "pve-manager/8.2.4/bookworm"},
	} {
		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			_ = json.NewEncoder(w).Encode(map[string]any{
				"data": map[string]string{"version": tc.version, "release": tc.release},
			})
		}))
		c, err := NewCluster(ClusterOptions{Endpoint: srv.URL, Token: "u@pve!t=s", Insecure: true})
		if err != nil {
			t.Fatalf("building the client: %v", err)
		}
		got, err := c.Version(context.Background())
		srv.Close()
		if err != nil {
			t.Fatalf("reading the version: %v", err)
		}
		if got != tc.want {
			t.Errorf("version %q release %q read as %q, want %q", tc.version, tc.release, got, tc.want)
		}
	}
}

// A run made without checking the cluster's certificate is still a
// qualification, but it is a different one -- so the client says which it was,
// and the evidence carries it.
func TestAClientSaysWhetherItCheckedTheClustersCertificate(t *testing.T) {
	verified, err := NewCluster(ClusterOptions{Endpoint: "https://pve.example.com:8006", Token: "u@pve!t=s"})
	if err != nil {
		t.Fatalf("building a verifying client: %v", err)
	}
	if !verified.Verified() {
		t.Error("a client that checks certificates says it does not")
	}
	skipped, err := NewCluster(ClusterOptions{Endpoint: "https://pve.example.com:8006", Token: "u@pve!t=s", Insecure: true})
	if err != nil {
		t.Fatalf("building a non-verifying client: %v", err)
	}
	if skipped.Verified() {
		t.Error("a client that skips verification claims to have verified")
	}
}

// A hypervisor credential over plain HTTP is a hypervisor credential on the
// wire, and a token pasted wrong is a run that fails at the first call.
func TestAClusterCredentialIsRefusedBeforeItCanBeSentAnywhereUnsafe(t *testing.T) {
	for _, tc := range []struct{ name, endpoint, token, secret, want string }{
		{"plain http", "http://pve.example.com:8006", "u@pve!t=s", "", "not https"},
		{"no endpoint", "", "u@pve!t=s", "", "no cluster endpoint"},
		{"secretless token", "https://pve.example.com:8006", "u@pve!t", "", "paste it whole"},
		{"not a token id", "https://pve.example.com:8006", "zoomies@pve", "secret", "is not a token identifier"},
	} {
		_, err := NewCluster(ClusterOptions{Endpoint: tc.endpoint, Token: tc.token, Secret: tc.secret})
		if err == nil {
			t.Errorf("%s was accepted", tc.name)
			continue
		}
		if !strings.Contains(err.Error(), tc.want) {
			t.Errorf("%s said %q, want it to mention %q", tc.name, err, tc.want)
		}
		if strings.Contains(err.Error(), "secret") && tc.name == "not a token id" {
			t.Errorf("%s put the secret in the error: %v", tc.name, err)
		}
	}

	// And the port Proxmox listens on is assumed rather than demanded.
	c, err := NewCluster(ClusterOptions{Endpoint: "https://pve.example.com", Token: "u@pve!t=s"})
	if err != nil {
		t.Fatalf("an endpoint with no port was refused: %v", err)
	}
	if !strings.Contains(c.base, ":8006/api2/json") {
		t.Errorf("base = %q, want the default port and the API path", c.base)
	}
}

package proxmox

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// A ledger is the list of real things one run is about to create, written to
// disk before each of them exists and closed only when they have all been
// removed.
//
// It is the same discipline the machine row has, for the same reason. A machine
// row exists before its virtual machine does, because a create whose outcome is
// unknown can only be reconciled by an identity that was persisted first; a run
// killed between the clone and the row would otherwise own a VM it has no record
// of. This harness is in exactly that position with respect to a whole cluster:
// if it dies between asking for demand and seeing the machine, something it
// caused still exists and nothing names it.
//
// So the order is: claim the blast radius first -- the cluster, the node, the
// storage, the VMID range and everything already in that range -- and only then
// do anything that could cause a guest to be built. A ledger with no machines in
// it still tells a person exactly where to look, which is the answer that
// matters when the harness died before it could say anything else.
//
// It lives outside the test's temp directory on purpose. t.TempDir is removed
// when the test ends however it ends, which is exactly the moment the record of
// what was not cleaned up becomes useful.
type Ledger struct {
	path string
	rec  LedgerRecord
}

// ResourceKind is the sort of thing a ledger entry names.
type ResourceKind string

const (
	KindInstallation ResourceKind = "installation"
	KindPool         ResourceKind = "pool"
	KindProvider     ResourceKind = "provider"
	// KindMachine is a machine row and, once the provider has allocated one,
	// the guest behind it. The two are one entry because they are one thing to
	// clean up: deleting the row without the guest is how an orphan is made.
	KindMachine ResourceKind = "machine"
)

// LedgerRecord is one run's whole record, as it is written to disk.
type LedgerRecord struct {
	RunID     string    `json:"run_id"`
	StartedAt time.Time `json:"started_at"`
	Commit    string    `json:"commit"`
	// Label is the per-run label this run's pools advertise and its workflows
	// ask for. It is how leftovers are recognised on GitHub and how two
	// concurrent runs stay out of each other's way.
	Label string `json:"label"`

	// The blast radius, written before anything is created.
	Cluster string `json:"cluster"`
	Node    string `json:"node"`
	Storage string `json:"storage"`
	Range   Range  `json:"vmid_range"`
	// PreexistingVMIDs is everything that was in the range before this run
	// began. Without it a guest found at the end cannot be told from one that
	// was always there, and the reconciliation would either accuse the cluster's
	// owner or excuse this run.
	PreexistingVMIDs []int `json:"preexisting_vmids"`

	// Target and TargetType name where on GitHub the leavings would be.
	Target     string `json:"target,omitempty"`
	TargetType string `json:"target_type,omitempty"`

	Resources []Resource `json:"resources"`
	// ClosedAt is set only when every resource has been removed. An open ledger
	// is a run that did not finish tidying up, whether it crashed, was killed,
	// or failed its cleanup.
	ClosedAt *time.Time `json:"closed_at,omitempty"`
}

// Resource is one thing this run made.
type Resource struct {
	Kind      ResourceKind `json:"kind"`
	ID        string       `json:"id"`
	Name      string       `json:"name,omitempty"`
	CreatedAt time.Time    `json:"created_at"`
	// Node and VMID are filled in when the provider allocates them, which is
	// after the row exists. A machine entry with no VMID is a machine that was
	// planned and may never have reached the cluster -- and the range on the
	// record is what says where to look for it anyway.
	Node      string     `json:"node,omitempty"`
	VMID      int        `json:"vmid,omitempty"`
	RemovedAt *time.Time `json:"removed_at,omitempty"`
}

// LedgerDir is where ledgers live. It must survive the test process, so it is
// never t.TempDir.
func LedgerDir() string {
	if d := os.Getenv("ZOOMIES_PROXMOX_LEDGER_DIR"); d != "" {
		return d
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(os.TempDir(), "zoomies-proxmox-ledgers")
	}
	return filepath.Join(home, ".zoomies", "proxmox-ledgers")
}

// openLedger claims this run's blast radius, before anything is created.
func openLedger(runID, label string, e env, preexisting []int) (*Ledger, error) {
	dir := LedgerDir()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("creating the ledger directory %s: %w", dir, err)
	}
	l := &Ledger{
		path: filepath.Join(dir, runID+".json"),
		rec: LedgerRecord{
			RunID: runID, StartedAt: time.Now().UTC(), Commit: commit(), Label: label,
			Cluster: e.endpoint, Node: e.node, Storage: e.storage,
			Range:            Range{Min: e.vmidMin, Max: e.vmidMax},
			PreexistingVMIDs: preexisting,
			Target:           e.target, TargetType: e.targetType,
		},
	}
	return l, l.save()
}

func (l *Ledger) save() error {
	raw, err := json.MarshalIndent(l.rec, "", "  ")
	if err != nil {
		return fmt.Errorf("encoding the ledger: %w", err)
	}
	return os.WriteFile(l.path, append(raw, '\n'), 0o644)
}

// created records a resource. Its error is fatal to the caller: a resource that
// exists without a ledger entry is one nothing will ever clean up.
func (l *Ledger) created(kind ResourceKind, id, name string) error {
	l.rec.Resources = append(l.rec.Resources, Resource{
		Kind: kind, ID: id, Name: name, CreatedAt: time.Now().UTC(),
	})
	return l.save()
}

// placed fills in where a machine ended up. It is separate from created because
// the row exists before the provider has chosen a node and a VMID, and the
// ledger must not wait for them: the window between the row and the identifier
// is exactly the window in which a run can die owning something it cannot name.
func (l *Ledger) placed(id, node string, vmid int) error {
	for i := range l.rec.Resources {
		if l.rec.Resources[i].ID == id {
			l.rec.Resources[i].Node, l.rec.Resources[i].VMID = node, vmid
			return l.save()
		}
	}
	return fmt.Errorf("no ledger entry for %s, so its resource %s/%d would go unrecorded", id, node, vmid)
}

// removed marks a resource gone. It is called when the removal has been
// confirmed, never when it has merely been asked for.
func (l *Ledger) removed(kind ResourceKind, id string) {
	now := time.Now().UTC()
	for i := range l.rec.Resources {
		if l.rec.Resources[i].Kind == kind && l.rec.Resources[i].ID == id && l.rec.Resources[i].RemovedAt == nil {
			l.rec.Resources[i].RemovedAt = &now
		}
	}
	_ = l.save()
}

// outstanding is what this run created and has not removed, in a sentence each.
func (l *Ledger) outstanding() []string { return l.rec.Outstanding() }

// Outstanding is the same question asked of a record read back from disk, which
// is how the sweep and the standalone check ask it.
func (r LedgerRecord) Outstanding() []string {
	var out []string
	for _, res := range r.Resources {
		if res.RemovedAt != nil {
			continue
		}
		line := string(res.Kind) + " " + res.ID
		if res.VMID != 0 {
			line += fmt.Sprintf(" (VM %d on %s)", res.VMID, res.Node)
		}
		out = append(out, line)
	}
	return out
}

// close marks the ledger finished and deletes it. A ledger is only worth keeping
// while it describes something still on the cluster; one whose resources are all
// gone is noise the next sweep would have to read past.
func (l *Ledger) close() error {
	if rem := l.outstanding(); len(rem) > 0 {
		return fmt.Errorf("not closing the ledger: %s still exist", strings.Join(rem, ", "))
	}
	now := time.Now().UTC()
	l.rec.ClosedAt = &now
	if err := l.save(); err != nil {
		return err
	}
	return os.Remove(l.path)
}

// record is the ledger as it stands, for the evidence and the reconciliation.
func (l *Ledger) record() LedgerRecord { return l.rec }

// ReadLedgers returns every ledger in a directory, oldest first. The standalone
// inventory check reads them rather than a database, because the database that
// knew about these machines went away with the controller that wrote it.
func ReadLedgers(dir string) ([]LedgerRecord, error) {
	entries, err := os.ReadDir(dir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var out []LedgerRecord
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		rec, err := ReadLedger(filepath.Join(dir, entry.Name()))
		if err != nil {
			// A file that is not a ledger is reported rather than skipped: a
			// half-written one is the shape a killed run leaves, and reading
			// past it silently is how its machines get forgotten.
			return out, fmt.Errorf("%s is not a ledger: %w", entry.Name(), err)
		}
		out = append(out, rec)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].StartedAt.Before(out[j].StartedAt) })
	return out, nil
}

// ReadLedger reads one.
func ReadLedger(path string) (LedgerRecord, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return LedgerRecord{}, err
	}
	var rec LedgerRecord
	if err := json.Unmarshal(raw, &rec); err != nil {
		return LedgerRecord{}, err
	}
	if rec.RunID == "" {
		return LedgerRecord{}, fmt.Errorf("no run id")
	}
	return rec, nil
}

// staleLedgers returns the open ledgers left by earlier runs against this same
// cluster and range, oldest first. An open ledger is by definition a run that
// did not finish tidying up.
func staleLedgers(runID string, e env) ([]LedgerRecord, error) {
	all, err := ReadLedgers(LedgerDir())
	if err != nil {
		return nil, err
	}
	var out []LedgerRecord
	for _, rec := range all {
		// This run's own ledger is not stale, and neither is one describing
		// somebody else's cluster: acting on that would be reaching into a
		// cluster this run was never given.
		if rec.RunID == runID || rec.ClosedAt != nil || rec.Cluster != e.endpoint {
			continue
		}
		out = append(out, rec)
	}
	return out, nil
}

// dropLedger removes a stale ledger once its leavings have been dealt with.
func dropLedger(runID string) {
	_ = os.Remove(filepath.Join(LedgerDir(), runID+".json"))
}

// commit is the revision under test. A record that cannot name its commit is
// still worth writing, so a failure here becomes the string rather than an
// error.
func commit() string {
	out, err := exec.Command("git", "rev-parse", "--short", "HEAD").Output()
	if err != nil {
		return "unknown"
	}
	return strings.TrimSpace(string(out))
}

package proxmox

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// A ledger directory the test can look inside. The real one is deliberately
// outside t.TempDir -- it has to outlive the run that wrote it -- so the
// environment override is how a test gets to see one at all.
func ledgerDir(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	t.Setenv("ZOOMIES_PROXMOX_LEDGER_DIR", dir)
	return dir
}

func testEnv() env {
	return env{
		endpoint: "https://pve.example.com:8006",
		node:     "pve1",
		storage:  "local-lvm",
		vmidMin:  9000, vmidMax: 9099,
		target: "example-org", targetType: "org",
	}
}

// The blast radius is on disk before anything could have been created.
//
// This is the whole point of the file. A run killed between asking for a
// machine and seeing it caused something that exists and that nothing names, so
// the cluster, the node, the storage, the range and what was already in it are
// written first -- while there is still nothing to write about.
func TestALedgerNamesWhereToLookBeforeThereIsAnythingToFind(t *testing.T) {
	dir := ledgerDir(t)
	l, err := openLedger("run_abc", "zoomies-pve-run_abc", testEnv(), []int{9001, 9002})
	if err != nil {
		t.Fatalf("opening the ledger: %v", err)
	}

	rec, err := ReadLedger(filepath.Join(dir, "run_abc.json"))
	if err != nil {
		t.Fatalf("the ledger was not on disk immediately: %v", err)
	}
	if rec.Cluster != "https://pve.example.com:8006" || rec.Node != "pve1" || rec.Storage != "local-lvm" {
		t.Errorf("the ledger does not name the cluster it may touch: %+v", rec)
	}
	if rec.Range != (Range{Min: 9000, Max: 9099}) {
		t.Errorf("range = %v, want 9000-9099", rec.Range)
	}
	if len(rec.PreexistingVMIDs) != 2 {
		t.Errorf("what was already in the range was not recorded: %v", rec.PreexistingVMIDs)
	}
	if len(rec.Resources) != 0 {
		t.Errorf("a ledger with nothing created yet lists resources: %v", rec.Resources)
	}
	if rec.ClosedAt != nil {
		t.Error("a ledger is open until its resources are gone")
	}
	if got := l.record().RunID; got != "run_abc" {
		t.Errorf("record().RunID = %q", got)
	}
}

// Each resource reaches the disk as it is recorded, not when the run ends.
//
// A ledger held in memory and written at the end is no ledger at all: the run
// that needs it is the one that did not get to the end.
func TestEveryResourceIsOnDiskTheMomentItIsRecorded(t *testing.T) {
	dir := ledgerDir(t)
	l, err := openLedger("run_def", "label", testEnv(), nil)
	if err != nil {
		t.Fatalf("opening the ledger: %v", err)
	}
	if err := l.created(KindMachine, "mach_1", "zoomies-qualify-1"); err != nil {
		t.Fatalf("recording a machine: %v", err)
	}

	rec, err := ReadLedger(filepath.Join(dir, "run_def.json"))
	if err != nil {
		t.Fatalf("reading it back: %v", err)
	}
	if len(rec.Resources) != 1 || rec.Resources[0].ID != "mach_1" {
		t.Fatalf("the machine was not written when it was recorded: %+v", rec.Resources)
	}
	if rec.Resources[0].VMID != 0 {
		t.Error("a machine has no VMID until the provider has allocated one")
	}
}

// The identifier arrives after the row, and the ledger takes it separately.
//
// The window between "there is a machine row" and "it has a VMID" is exactly
// the window in which a run can die owning a guest it cannot name, so the row
// is recorded first and the identifier filled in when it is known.
func TestAMachineIsRecordedBeforeItHasAnIdentifierAndPlacedWhenItDoes(t *testing.T) {
	dir := ledgerDir(t)
	l, _ := openLedger("run_ghi", "label", testEnv(), nil)
	if err := l.created(KindMachine, "mach_1", "zoomies-qualify-1"); err != nil {
		t.Fatalf("recording a machine: %v", err)
	}
	if err := l.placed("mach_1", "pve1", 9042); err != nil {
		t.Fatalf("placing it: %v", err)
	}

	rec, _ := ReadLedger(filepath.Join(dir, "run_ghi.json"))
	if rec.Resources[0].VMID != 9042 || rec.Resources[0].Node != "pve1" {
		t.Errorf("the identifier was not recorded: %+v", rec.Resources[0])
	}

	// And a placement with nothing to place it on is refused loudly rather than
	// dropped: a VMID nobody wrote down is a guest nobody will find.
	err := l.placed("mach_missing", "pve1", 9043)
	if err == nil {
		t.Fatal("placing a resource with no ledger entry was accepted")
	}
	for _, want := range []string{"mach_missing", "9043"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("the refusal does not name %s: %v", want, err)
		}
	}
}

// Removal is recorded per kind and identifier, and only once.
func TestRemovalMarksTheOneResourceItNamesAndLeavesTheRestOutstanding(t *testing.T) {
	l, _ := openLedger("run_jkl", "label", testEnv(), nil)
	for _, r := range []struct {
		kind     ResourceKind
		id, name string
	}{
		{KindMachine, "mach_1", "one"},
		{KindMachine, "mach_2", "two"},
		{KindPool, "pool_1", "pool"},
	} {
		if err := l.created(r.kind, r.id, r.name); err != nil {
			t.Fatalf("recording %s: %v", r.id, err)
		}
	}
	if err := l.placed("mach_2", "pve1", 9042); err != nil {
		t.Fatalf("placing mach_2: %v", err)
	}

	l.removed(KindMachine, "mach_1")

	out := l.outstanding()
	if len(out) != 2 {
		t.Fatalf("outstanding = %v, want the two that are left", out)
	}
	joined := strings.Join(out, "; ")
	if strings.Contains(joined, "mach_1") {
		t.Errorf("a removed resource is still outstanding: %s", joined)
	}
	// A guest that reached the cluster says where it is, because that is what
	// somebody reading this has to go and look at.
	if !strings.Contains(joined, "VM 9042 on pve1") {
		t.Errorf("an outstanding machine does not say where it is: %s", joined)
	}

	// The same kind and id under a different kind is a different resource.
	l.removed(KindPool, "mach_2")
	if len(l.outstanding()) != 2 {
		t.Errorf("removing a pool removed a machine: %v", l.outstanding())
	}
}

// A ledger is closed only when it describes nothing, and closing deletes it.
//
// Closing early would delete the only record of what is still on the cluster,
// which is the failure this whole file exists to prevent.
func TestALedgerRefusesToCloseWhileAnythingItNamesStillExists(t *testing.T) {
	dir := ledgerDir(t)
	l, _ := openLedger("run_mno", "label", testEnv(), nil)
	if err := l.created(KindMachine, "mach_1", "one"); err != nil {
		t.Fatalf("recording a machine: %v", err)
	}

	err := l.close()
	if err == nil {
		t.Fatal("a ledger with an outstanding machine was closed")
	}
	if !strings.Contains(err.Error(), "mach_1") {
		t.Errorf("the refusal does not say what is still there: %v", err)
	}
	if _, statErr := os.Stat(filepath.Join(dir, "run_mno.json")); statErr != nil {
		t.Errorf("a refused close removed the ledger anyway: %v", statErr)
	}

	l.removed(KindMachine, "mach_1")
	if err := l.close(); err != nil {
		t.Fatalf("closing a ledger with nothing left: %v", err)
	}
	if _, statErr := os.Stat(filepath.Join(dir, "run_mno.json")); !os.IsNotExist(statErr) {
		t.Error("a closed ledger is kept; the next sweep has to read past it")
	}
}

// Reading a directory of ledgers puts them in the order they were started, and
// a file that is not a ledger is reported rather than skipped.
//
// A half-written file is the shape a killed run leaves. Reading past it quietly
// is how its machines get forgotten, which is the one outcome this cannot have.
func TestReadingLedgersIsOldestFirstAndNeverSkipsOneItCannotParse(t *testing.T) {
	dir := t.TempDir()
	write := func(name string, rec LedgerRecord) {
		t.Helper()
		raw, err := json.Marshal(rec)
		if err != nil {
			t.Fatalf("encoding %s: %v", name, err)
		}
		if err := os.WriteFile(filepath.Join(dir, name), raw, 0o644); err != nil {
			t.Fatalf("writing %s: %v", name, err)
		}
	}
	base := time.Date(2026, 9, 14, 1, 0, 0, 0, time.UTC)
	write("b.json", LedgerRecord{RunID: "second", StartedAt: base.Add(time.Hour)})
	write("a.json", LedgerRecord{RunID: "first", StartedAt: base})
	// Not a ledger, and not named like one: skipped without complaint.
	if err := os.WriteFile(filepath.Join(dir, "notes.txt"), []byte("hello"), 0o644); err != nil {
		t.Fatalf("writing the decoy: %v", err)
	}

	got, err := ReadLedgers(dir)
	if err != nil {
		t.Fatalf("reading the ledgers: %v", err)
	}
	if len(got) != 2 || got[0].RunID != "first" || got[1].RunID != "second" {
		t.Fatalf("ledgers came back as %v, want oldest first", got)
	}

	// Now one that claims to be a ledger and is not.
	if err := os.WriteFile(filepath.Join(dir, "c.json"), []byte("{not json"), 0o644); err != nil {
		t.Fatalf("writing the broken ledger: %v", err)
	}
	got, err = ReadLedgers(dir)
	if err == nil {
		t.Fatal("an unreadable ledger was skipped silently")
	}
	if !strings.Contains(err.Error(), "c.json") {
		t.Errorf("the error does not name the file: %v", err)
	}
	if len(got) == 0 {
		t.Error("the ledgers read before the broken one were thrown away with it")
	}

	// A directory that was never created is no ledgers, not an error: the first
	// run on a machine has not written one yet.
	none, err := ReadLedgers(filepath.Join(dir, "nothing-here"))
	if err != nil || none != nil {
		t.Errorf("ReadLedgers on a missing directory = %v, %v", none, err)
	}
}

// A JSON file with no run id is not a ledger, however well it parses.
func TestALedgerWithoutARunIdIsRefused(t *testing.T) {
	path := filepath.Join(t.TempDir(), "x.json")
	if err := os.WriteFile(path, []byte(`{"cluster":"https://pve.example.com:8006"}`), 0o644); err != nil {
		t.Fatalf("writing: %v", err)
	}
	if _, err := ReadLedger(path); err == nil {
		t.Fatal("a ledger with no run id was accepted; nothing could be said about which run left it")
	}
}

// Stale means somebody else's unfinished run against this same cluster -- not
// this run, not a finished one, and never another cluster's.
//
// Acting on another cluster's ledger would be reaching into a cluster this run
// was never given, which is the one thing a harness holding hypervisor
// credentials must not do.
func TestStaleLedgersAreOtherUnfinishedRunsOnThisClusterAndNothingElse(t *testing.T) {
	dir := ledgerDir(t)
	e := testEnv()
	closed := time.Now().UTC()
	write := func(rec LedgerRecord) {
		t.Helper()
		raw, _ := json.Marshal(rec)
		if err := os.WriteFile(filepath.Join(dir, rec.RunID+".json"), raw, 0o644); err != nil {
			t.Fatalf("writing %s: %v", rec.RunID, err)
		}
	}
	base := time.Date(2026, 9, 14, 1, 0, 0, 0, time.UTC)
	write(LedgerRecord{RunID: "mine", StartedAt: base, Cluster: e.endpoint})
	write(LedgerRecord{RunID: "older", StartedAt: base.Add(-time.Hour), Cluster: e.endpoint})
	write(LedgerRecord{RunID: "newer", StartedAt: base.Add(time.Hour), Cluster: e.endpoint})
	write(LedgerRecord{RunID: "tidied", StartedAt: base, Cluster: e.endpoint, ClosedAt: &closed})
	write(LedgerRecord{RunID: "elsewhere", StartedAt: base, Cluster: "https://other.example.com:8006"})

	got, err := staleLedgers("mine", e)
	if err != nil {
		t.Fatalf("reading stale ledgers: %v", err)
	}
	var ids []string
	for _, rec := range got {
		ids = append(ids, rec.RunID)
	}
	if strings.Join(ids, ",") != "older,newer" {
		t.Errorf("stale ledgers = %v, want the two unfinished runs on this cluster, oldest first", ids)
	}

	dropLedger("older")
	got, _ = staleLedgers("mine", e)
	if len(got) != 1 || got[0].RunID != "newer" {
		t.Errorf("after dropping one, stale = %v", got)
	}
}

// Outstanding asked of a record read back from disk says the same thing as
// asked of a live ledger -- that is how the sweep and the standalone check ask
// it, and they are the ones asking when the run that wrote it is gone.
func TestOutstandingReadsTheSameFromDiskAsItDoesInMemory(t *testing.T) {
	dir := ledgerDir(t)
	l, _ := openLedger("run_pqr", "label", testEnv(), nil)
	if err := l.created(KindMachine, "mach_1", "one"); err != nil {
		t.Fatalf("recording: %v", err)
	}
	if err := l.placed("mach_1", "pve1", 9042); err != nil {
		t.Fatalf("placing: %v", err)
	}

	rec, err := ReadLedger(filepath.Join(dir, "run_pqr.json"))
	if err != nil {
		t.Fatalf("reading back: %v", err)
	}
	if strings.Join(rec.Outstanding(), "|") != strings.Join(l.outstanding(), "|") {
		t.Errorf("from disk: %v; in memory: %v", rec.Outstanding(), l.outstanding())
	}
}

// The commit is evidence, and a record that cannot name one is still worth
// writing -- so this never fails, it only ever says "unknown".
func TestTheCommitIsAStringEvenWhereThereIsNoGit(t *testing.T) {
	if got := commit(); got == "" {
		t.Error("commit() returned an empty string; the record would claim no revision at all")
	}
}

// Where the ledgers go: the override, then the home directory. Never t.TempDir,
// which is removed at exactly the moment the record becomes useful.
func TestTheLedgerDirectoryIsOverridableAndOtherwiseOutlivesTheRun(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("ZOOMIES_PROXMOX_LEDGER_DIR", dir)
	if got := LedgerDir(); got != dir {
		t.Errorf("LedgerDir() = %q, want the override %q", got, dir)
	}

	t.Setenv("ZOOMIES_PROXMOX_LEDGER_DIR", "")
	got := LedgerDir()
	if !strings.Contains(got, "proxmox-ledgers") {
		t.Errorf("LedgerDir() = %q, want somewhere named for what it holds", got)
	}
	if strings.HasPrefix(got, dir) {
		t.Errorf("LedgerDir() = %q, which is inside the test's own temp directory", got)
	}
}

package proxmox

import (
	"context"
	"fmt"
	"net"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

// Everything this harness needs from outside itself, and every check that can
// be made before anything exists.
//
// "Before anything exists" is the rule the whole file is written to. The
// end-to-end harness next door once looked for the gh CLI in the middle of its
// scenario, after it had already made an installation and a pool on a real
// organisation, and then skipped -- which is exit code zero. Here the stakes are
// higher again: half a prerequisite means a provider row pointed at a cluster,
// and a provider row pointed at a cluster builds virtual machines. So every
// check that can be made without changing anything is made here, including the
// read-only ones against the cluster itself, and nothing is created until they
// all hold.

// env is the whole configuration of one qualification run.
type env struct {
	// The cluster.
	endpoint   string
	token      string
	secret     string
	caPEMFile  string
	insecure   bool
	node       string
	storage    string
	bridge     string
	pool       string
	templateID int
	// brokenTemplateID is a template that cannot bootstrap -- no guest agent,
	// or no network -- used by the induced bootstrap failure. It is optional:
	// without one that case induces the failure by pointing the machines at a
	// controller address nothing answers on, and the evidence says which method
	// was used.
	brokenTemplateID int
	vmidMin          int
	vmidMax          int
	// controllerURL is how a guest on the cluster reaches this controller. It
	// defaults to the address this host uses to reach the cluster, which is
	// right on a flat network and wrong behind NAT -- hence the override.
	controllerURL string

	// The machine shape and the runner backend inside the guest, which are
	// evidence: a timing without the shape it was measured on is not a
	// measurement, and one combination is what this procedure qualifies.
	cpus     int
	memoryMB int
	diskMB   int
	backend  string

	// GitHub. The names are the end-to-end harness's, because it is the same
	// App, the same organisation and the same fixture workflow; asking for a
	// second set of credentials for the same thing is how a procedure stops
	// being run.
	appID          string
	installationID string
	privateKey     string
	target         string
	targetType     string
	repo           string
	workflow       string
}

// vmidRange is the block this run may allocate inside.
func (e env) vmidRange() Range { return Range{Min: e.vmidMin, Max: e.vmidMax} }

// required reports whether a missing prerequisite is a failure rather than a
// skip. A person qualifying a cluster runs in this mode; a laptop does not.
func required() bool { return os.Getenv("ZOOMIES_PROXMOX_REQUIRED") != "" }

// the six variables without which there is nothing to qualify against.
var clusterVars = []string{
	"ZOOMIES_PROXMOX_URL",
	"ZOOMIES_PROXMOX_TOKEN",
	"ZOOMIES_PROXMOX_NODE",
	"ZOOMIES_PROXMOX_TEMPLATE",
	"ZOOMIES_PROXMOX_STORAGE",
	"ZOOMIES_PROXMOX_VMID_RANGE",
}

// requested reports whether this run was asked to do anything at all. Any one of
// the six means somebody meant to: the rest then being absent is a blockage to
// report, not a laptop to be quiet on.
func requested() bool {
	if required() {
		return true
	}
	for _, v := range clusterVars {
		if os.Getenv(v) != "" {
			return true
		}
	}
	return false
}

// skipReason is the sentence a run that was never asked for is skipped with. It
// names every variable rather than the first, because somebody reading it is
// about to go and set all of them.
func skipReason() string {
	return "no Proxmox cluster was given, so there is nothing to qualify against.\n" +
		"This harness needs a DISPOSABLE Proxmox VE cluster and a GitHub installation:\n" +
		"  " + strings.Join(clusterVars, "\n  ") + "\n" +
		"  ZOOMIES_E2E_APP_ID, ZOOMIES_E2E_INSTALLATION_ID, ZOOMIES_E2E_PRIVATE_KEY_FILE,\n" +
		"  ZOOMIES_E2E_TARGET, ZOOMIES_E2E_REPO\n" +
		"See test/e2e/proxmox/README.md, and roadmap/validation/proxmox-qualification.md\n" +
		"for the procedure this produces the evidence for. Fixture success is not live qualification."
}

// preflight reads the environment and checks everything that can be checked
// without a network. It creates nothing and dials nothing.
func preflight() (env, []string) {
	e := env{
		endpoint:      strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_URL")),
		token:         strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_TOKEN")),
		secret:        strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_TOKEN_SECRET")),
		caPEMFile:     strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_CA_PEM_FILE")),
		insecure:      truthy(os.Getenv("ZOOMIES_PROXMOX_INSECURE")),
		node:          strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_NODE")),
		storage:       strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_STORAGE")),
		bridge:        orDefault(os.Getenv("ZOOMIES_PROXMOX_BRIDGE"), "vmbr0"),
		pool:          strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_POOL")),
		controllerURL: strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_CONTROLLER_URL")),

		cpus:     atoiOr(os.Getenv("ZOOMIES_PROXMOX_CPUS"), 2),
		memoryMB: atoiOr(os.Getenv("ZOOMIES_PROXMOX_MEMORY_MB"), 2048),
		diskMB:   atoiOr(os.Getenv("ZOOMIES_PROXMOX_DISK_MB"), 0),
		backend:  orDefault(os.Getenv("ZOOMIES_PROXMOX_BACKEND"), "docker"),

		appID:          strings.TrimSpace(os.Getenv("ZOOMIES_E2E_APP_ID")),
		installationID: strings.TrimSpace(os.Getenv("ZOOMIES_E2E_INSTALLATION_ID")),
		target:         strings.TrimSpace(os.Getenv("ZOOMIES_E2E_TARGET")),
		targetType:     orDefault(os.Getenv("ZOOMIES_E2E_TARGET_TYPE"), "org"),
		repo:           strings.TrimSpace(os.Getenv("ZOOMIES_E2E_REPO")),
		workflow:       orDefault(os.Getenv("ZOOMIES_PROXMOX_WORKFLOW"), "zoomies-e2e.yml"),
	}

	var missing []string
	add := func(format string, args ...any) { missing = append(missing, fmt.Sprintf(format, args...)) }

	for _, v := range []struct{ name, value string }{
		{"ZOOMIES_PROXMOX_URL", e.endpoint},
		{"ZOOMIES_PROXMOX_TOKEN", e.token},
		{"ZOOMIES_PROXMOX_NODE", e.node},
		{"ZOOMIES_PROXMOX_STORAGE", e.storage},
		{"ZOOMIES_E2E_APP_ID", e.appID},
		{"ZOOMIES_E2E_INSTALLATION_ID", e.installationID},
		{"ZOOMIES_E2E_TARGET", e.target},
		{"ZOOMIES_E2E_REPO", e.repo},
	} {
		if v.value == "" {
			add("%s is not set", v.name)
		}
	}

	e.templateID = atoiOr(os.Getenv("ZOOMIES_PROXMOX_TEMPLATE"), 0)
	if e.templateID <= 0 {
		add("ZOOMIES_PROXMOX_TEMPLATE is not a template VMID; every machine starts as a clone of one")
	}
	e.brokenTemplateID = atoiOr(os.Getenv("ZOOMIES_PROXMOX_BROKEN_TEMPLATE"), 0)

	// The range is the one setting that makes this safe to run at all: without
	// it the provider would allocate identifiers anywhere in the cluster,
	// including ones somebody else's automation is entitled to.
	switch min, max, err := parseRange(os.Getenv("ZOOMIES_PROXMOX_VMID_RANGE")); {
	case err != nil:
		add("ZOOMIES_PROXMOX_VMID_RANGE %v", err)
	case max-min+1 < qualificationCycles:
		// Not strictly required -- the cycles are sequential and reuse
		// identifiers -- but a range smaller than the number of machines the
		// procedure builds is almost always a typo, and finding out at cycle
		// nineteen wastes an afternoon.
		add("ZOOMIES_PROXMOX_VMID_RANGE %d-%d holds %d identifiers and the procedure builds %d machines; "+
			"reserve at least that many", min, max, max-min+1, qualificationCycles)
	default:
		e.vmidMin, e.vmidMax = min, max
	}
	if e.templateID > 0 && e.vmidMin > 0 && e.vmidRange().contains(e.templateID) {
		add("the template %d is inside the VMID range %s this run allocates from; "+
			"the closing reconciliation would count the template as a machine, and a cycle could try to take its identifier",
			e.templateID, e.vmidRange())
	}

	switch e.backend {
	case "docker", "podman", "process":
	default:
		add("ZOOMIES_PROXMOX_BACKEND is %q; the guest runs runners with docker, podman or process", e.backend)
	}
	switch e.targetType {
	case "org", "repo":
	default:
		add("ZOOMIES_E2E_TARGET_TYPE is %q; it must be org or repo", e.targetType)
	}
	if keyFile := strings.TrimSpace(os.Getenv("ZOOMIES_E2E_PRIVATE_KEY_FILE")); keyFile == "" {
		add("ZOOMIES_E2E_PRIVATE_KEY_FILE is not set")
	} else {
		pem, err := os.ReadFile(keyFile)
		switch {
		case err != nil:
			add("ZOOMIES_E2E_PRIVATE_KEY_FILE %s cannot be read: %v", keyFile, err)
		case !strings.Contains(string(pem), "PRIVATE KEY"):
			add("%s does not look like a PEM private key", keyFile)
		default:
			e.privateKey = string(pem)
		}
	}
	if e.caPEMFile != "" {
		if _, err := os.Stat(e.caPEMFile); err != nil {
			add("ZOOMIES_PROXMOX_CA_PEM_FILE %s cannot be read: %v", e.caPEMFile, err)
		}
	}

	// The tools, all of them, up front. Docker is not among them: the runner
	// backend runs inside the guest this harness builds, not on this host.
	for _, tool := range []struct{ bin, why string }{
		{"gh", "the workflow is dispatched and GitHub is asked about leftover registrations through the gh CLI"},
		{"git", "the evidence records the commit under test"},
	} {
		if _, err := exec.LookPath(tool.bin); err != nil {
			add("%s is not on PATH: %s", tool.bin, tool.why)
		}
	}
	if _, err := exec.LookPath("gh"); err == nil {
		if out, err := exec.Command("gh", "auth", "status").CombinedOutput(); err != nil {
			add("the gh CLI is not authenticated: %s", strings.TrimSpace(string(out)))
		}
	}
	if _, err := os.Stat(builtBinary()); err != nil {
		add("the zoomies binary is not built; run `make build-nogui` first")
	}

	// How a guest reaches this controller. This is the prerequisite people get
	// wrong: a controller bound to loopback can be talked to from this machine
	// and from nowhere else, so every machine it builds enrols never.
	if e.controllerURL == "" && e.endpoint != "" {
		if addr, err := outboundAddress(e.endpoint); err != nil {
			add("could not work out which address a machine would reach this controller on (%v); "+
				"set ZOOMIES_PROXMOX_CONTROLLER_URL to a URL the guests can reach, with a port", err)
		} else {
			e.controllerURL = "http://" + net.JoinHostPort(addr, strconv.Itoa(freePortNumber()))
		}
	} else if e.controllerURL != "" {
		if u, err := url.Parse(e.controllerURL); err != nil || u.Host == "" || u.Port() == "" {
			add("ZOOMIES_PROXMOX_CONTROLLER_URL %q is not a URL with a port; "+
				"write it as http://10.0.0.5:8080 -- the port is what this controller binds", e.controllerURL)
		}
	}
	return e, missing
}

// clusterFacts is what a read-only look at the cluster established, and most of
// it is evidence: the version and the template are rows in the qualification
// record, and the identifiers already in the range are what the closing
// reconciliation subtracts.
type clusterFacts struct {
	Version          string
	TemplateName     string
	PreexistingVMIDs []int
	Preexisting      []Guest
}

// preflightCluster asks the cluster whether this run could work, changing
// nothing. Every call in it is a GET.
func preflightCluster(ctx context.Context, c *Cluster, e env) (clusterFacts, []string) {
	var facts clusterFacts
	var missing []string
	add := func(format string, args ...any) { missing = append(missing, fmt.Sprintf(format, args...)) }

	version, err := c.Version(ctx)
	if err != nil {
		// One problem, not eleven: a cluster that cannot be reached fails every
		// check below and listing them all would bury this.
		return facts, []string{fmt.Sprintf("the cluster at %s did not answer: %v", e.endpoint, err)}
	}
	facts.Version = version

	inv, err := c.Take(ctx, e.node, e.storage)
	if err != nil {
		return facts, []string{fmt.Sprintf("the cluster answered its version but not its inventory: %v", err)}
	}

	var sawNode, sawTemplate bool
	for _, g := range inv.Guests {
		if g.Node == e.node {
			sawNode = true
		}
		if g.VMID == e.templateID {
			sawTemplate = true
			facts.TemplateName = g.Name
			if g.Template == 0 {
				add("VM %d is not a template; the provider clones from a template, and cloning a running guest is a different operation", e.templateID)
			}
		}
	}
	if !sawNode && len(inv.Guests) > 0 {
		// Weak evidence -- a node with no guests at all is invisible here -- so
		// it is worded as the doubt it is rather than asserted.
		add("no guest on this cluster is on node %q; check the node name, because a machine has to be built somewhere", e.node)
	}
	if !sawTemplate {
		add("no guest with VMID %d exists on this cluster, so there is no template to clone", e.templateID)
	}
	if e.brokenTemplateID > 0 {
		found := false
		for _, g := range inv.Guests {
			if g.VMID == e.brokenTemplateID {
				found = true
			}
		}
		if !found {
			add("ZOOMIES_PROXMOX_BROKEN_TEMPLATE %d does not exist; leave it unset to induce the bootstrap failure another way", e.brokenTemplateID)
		}
	}

	// What is already in the range. A guest wearing this fleet's marks in a
	// range reserved for this procedure is a leftover, and starting a
	// qualification on top of one would make the closing reconciliation
	// meaningless: it could not tell this run's litter from the last run's.
	for _, g := range inv.InRange(e.vmidRange()) {
		facts.PreexistingVMIDs = append(facts.PreexistingVMIDs, g.VMID)
		facts.Preexisting = append(facts.Preexisting, g)
		if g.Ours() {
			add("%s is inside the reserved range %s and already wears this fleet's marks; "+
				"it is an earlier run's leftover. Delete it, record it in the qualification, and start again",
				g, e.vmidRange())
		}
	}
	return facts, missing
}

// outboundAddress is the address on this host that a packet to the cluster
// leaves from, which is the address a guest on that cluster can almost always
// reach this controller on. It dials nothing: a UDP "connection" only asks the
// routing table.
func outboundAddress(endpoint string) (string, error) {
	host := endpoint
	if u, err := url.Parse(endpoint); err == nil && u.Host != "" {
		host = u.Hostname()
	}
	conn, err := net.Dial("udp", net.JoinHostPort(host, "8006"))
	if err != nil {
		return "", err
	}
	defer conn.Close()
	addr, ok := conn.LocalAddr().(*net.UDPAddr)
	if !ok {
		return "", fmt.Errorf("the local address is not an IP address")
	}
	return addr.IP.String(), nil
}

// freePortNumber asks the kernel for a port nothing is using. It is used only to
// build the default controller URL, before the controller binds it; the window
// between the two is this harness's own and nothing else on the host is racing
// for it.
func freePortNumber() int {
	l, err := net.Listen("tcp", "0.0.0.0:0")
	if err != nil {
		return 8080
	}
	defer l.Close()
	return l.Addr().(*net.TCPAddr).Port
}

// parseRange reads "9000-9099".
func parseRange(raw string) (int, int, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return 0, 0, fmt.Errorf("is not set; reserve a block of VMIDs for this and nothing else, for example 9000-9099")
	}
	lo, hi, ok := strings.Cut(raw, "-")
	if !ok {
		return 0, 0, fmt.Errorf("%q is not a range; write it as 9000-9099", raw)
	}
	min, err := strconv.Atoi(strings.TrimSpace(lo))
	if err != nil {
		return 0, 0, fmt.Errorf("%q does not begin with a number", raw)
	}
	max, err := strconv.Atoi(strings.TrimSpace(hi))
	if err != nil {
		return 0, 0, fmt.Errorf("%q does not end with a number", raw)
	}
	if min <= 0 || max <= 0 {
		return 0, 0, fmt.Errorf("%q is not a range of VMIDs; they start at 100", raw)
	}
	if min > max {
		return 0, 0, fmt.Errorf("%q runs backwards", raw)
	}
	return min, max, nil
}

func orDefault(v, def string) string {
	if strings.TrimSpace(v) == "" {
		return def
	}
	return strings.TrimSpace(v)
}

func atoiOr(raw string, def int) int {
	n, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return def
	}
	return n
}

func truthy(raw string) bool {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "1", "true", "yes", "on":
		return true
	}
	return false
}

// builtBinary is the zoomies this harness runs. It is the built one, not one
// this test builds: qualification is of the artefact.
func builtBinary() string {
	dir, err := os.Getwd()
	if err != nil {
		return "zoomies"
	}
	for range 6 {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "zoomies")
		}
		dir = filepath.Dir(dir)
	}
	return "zoomies"
}

package proxmox

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// clearCluster unsets everything preflight reads, so a test starts from a
// laptop rather than from whatever the machine running it happens to export.
func clearCluster(t *testing.T) {
	t.Helper()
	for _, v := range []string{
		"ZOOMIES_PROXMOX_REQUIRED", "ZOOMIES_PROXMOX_URL", "ZOOMIES_PROXMOX_TOKEN",
		"ZOOMIES_PROXMOX_TOKEN_SECRET", "ZOOMIES_PROXMOX_NODE", "ZOOMIES_PROXMOX_TEMPLATE",
		"ZOOMIES_PROXMOX_STORAGE", "ZOOMIES_PROXMOX_VMID_RANGE", "ZOOMIES_PROXMOX_BRIDGE",
		"ZOOMIES_PROXMOX_POOL", "ZOOMIES_PROXMOX_CPUS", "ZOOMIES_PROXMOX_MEMORY_MB",
		"ZOOMIES_PROXMOX_DISK_MB", "ZOOMIES_PROXMOX_BACKEND", "ZOOMIES_PROXMOX_INSECURE",
		"ZOOMIES_PROXMOX_CA_PEM_FILE", "ZOOMIES_PROXMOX_CONTROLLER_URL",
		"ZOOMIES_PROXMOX_BROKEN_TEMPLATE", "ZOOMIES_PROXMOX_WORKFLOW",
		"ZOOMIES_E2E_APP_ID", "ZOOMIES_E2E_INSTALLATION_ID", "ZOOMIES_E2E_PRIVATE_KEY_FILE",
		"ZOOMIES_E2E_TARGET", "ZOOMIES_E2E_TARGET_TYPE", "ZOOMIES_E2E_REPO",
	} {
		t.Setenv(v, "")
	}
}

// A laptop is quiet and a qualification machine is not.
//
// The distinction is the whole reason `required` exists: where somebody is
// qualifying a cluster, a skip looks exactly like a pass, and a procedure whose
// failure mode is "looked fine" is not a procedure.
func TestAQualificationRunIsOnlySilentWhereNobodyAskedForOne(t *testing.T) {
	clearCluster(t)
	if requested() {
		t.Error("a machine with none of the settings was taken as having asked for a qualification")
	}

	// Any one of the six means somebody meant to: the rest being absent is then
	// a blockage to report, not a laptop to be quiet on.
	for _, v := range clusterVars {
		clearCluster(t)
		t.Setenv(v, "something")
		if !requested() {
			t.Errorf("%s was set and the run still considered itself unasked-for", v)
		}
	}

	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_REQUIRED", "1")
	if !requested() || !required() {
		t.Error("ZOOMIES_PROXMOX_REQUIRED did not make a missing prerequisite a failure")
	}
}

// The skip names every variable, because whoever reads it is about to set them
// all -- and it says plainly that the fixture suite is not this.
func TestTheSkipNamesEverySettingAndRefusesToBeMistakenForQualification(t *testing.T) {
	reason := skipReason()
	for _, v := range clusterVars {
		if !strings.Contains(reason, v) {
			t.Errorf("the skip does not name %s", v)
		}
	}
	for _, want := range []string{
		"DISPOSABLE",
		"ZOOMIES_E2E_APP_ID",
		"roadmap/validation/proxmox-qualification.md",
		"Fixture success is not live qualification",
	} {
		if !strings.Contains(reason, want) {
			t.Errorf("the skip does not say %q", want)
		}
	}
}

// Every missing prerequisite is named at once, and nothing is dialled to find
// them out.
//
// Half a prerequisite means a provider row pointed at a cluster, and a provider
// row pointed at a cluster builds virtual machines. So the answer to "what is
// missing" has to be complete before anything is created, and being told one
// item per attempt is how somebody gives up and starts guessing.
func TestPreflightNamesEveryMissingPrerequisiteAtOnce(t *testing.T) {
	clearCluster(t)
	_, missing := preflight()
	if len(missing) == 0 {
		t.Fatal("preflight with nothing set found nothing missing")
	}
	joined := strings.Join(missing, "\n")
	for _, want := range []string{
		"ZOOMIES_PROXMOX_URL", "ZOOMIES_PROXMOX_TOKEN", "ZOOMIES_PROXMOX_NODE",
		"ZOOMIES_PROXMOX_STORAGE", "ZOOMIES_PROXMOX_TEMPLATE", "ZOOMIES_PROXMOX_VMID_RANGE",
	} {
		if !strings.Contains(joined, want) {
			t.Errorf("preflight did not report %s missing:\n%s", want, joined)
		}
	}
}

// The defaults are the ones the README documents, and an unset setting is not
// the same as one set to something unusable.
func TestPreflightFillsInTheDefaultsItDocuments(t *testing.T) {
	clearCluster(t)
	e, _ := preflight()
	for _, tc := range []struct{ name, got, want string }{
		{"bridge", e.bridge, "vmbr0"},
		{"backend", e.backend, "docker"},
		{"target type", e.targetType, "org"},
		{"workflow", e.workflow, "zoomies-e2e.yml"},
	} {
		if tc.got != tc.want {
			t.Errorf("%s defaulted to %q, want %q", tc.name, tc.got, tc.want)
		}
	}
	if e.cpus != 2 || e.memoryMB != 2048 || e.diskMB != 0 {
		t.Errorf("machine shape defaulted to %d cpus / %d MB / %d MB disk", e.cpus, e.memoryMB, e.diskMB)
	}
}

// The machine shape is evidence, so a value nobody can read falls back to the
// documented default rather than to zero: a qualification claiming two cores
// when it ran on none is worse than one that says what it actually used.
func TestAnUnreadableNumberFallsBackToTheDocumentedDefault(t *testing.T) {
	for _, tc := range []struct {
		raw  string
		def  int
		want int
	}{
		{"", 2048, 2048},
		{"   ", 2048, 2048},
		{"not a number", 2048, 2048},
		{"4096", 2048, 4096},
		{"  4096  ", 2048, 4096},
		{"0", 2048, 0},
	} {
		if got := atoiOr(tc.raw, tc.def); got != tc.want {
			t.Errorf("atoiOr(%q, %d) = %d, want %d", tc.raw, tc.def, got, tc.want)
		}
	}
	for _, tc := range []struct{ raw, def, want string }{
		{"", "vmbr0", "vmbr0"},
		{"  ", "vmbr0", "vmbr0"},
		{"  vmbr1 ", "vmbr0", "vmbr1"},
	} {
		if got := orDefault(tc.raw, tc.def); got != tc.want {
			t.Errorf("orDefault(%q, %q) = %q, want %q", tc.raw, tc.def, got, tc.want)
		}
	}
}

// Turning off certificate verification takes a word that means yes. Anything
// else leaves it on, because the failure of guessing here is a credential sent
// to whoever answered.
func TestOnlyAWordMeaningYesTurnsCertificateCheckingOff(t *testing.T) {
	for _, raw := range []string{"1", "true", "TRUE", "yes", "on", " On "} {
		if !truthy(raw) {
			t.Errorf("truthy(%q) = false", raw)
		}
	}
	for _, raw := range []string{"", "0", "false", "no", "off", "maybe", "2", "y"} {
		if truthy(raw) {
			t.Errorf("truthy(%q) = true", raw)
		}
	}
}

// The range is the setting that makes this safe to run at all: without it the
// provider would allocate identifiers anywhere in the cluster, including ones
// somebody else's automation is entitled to. So every way of getting it wrong
// is refused, and the refusal says how to write it.
func TestAVMIDRangeIsRefusedEveryWayItCanBeWrong(t *testing.T) {
	for _, tc := range []struct {
		raw            string
		min, max       int
		wantErr        string
		wantAcceptance bool
	}{
		{raw: "9000-9099", min: 9000, max: 9099, wantAcceptance: true},
		{raw: "  9000 - 9099 ", min: 9000, max: 9099, wantAcceptance: true},
		{raw: "9000-9000", min: 9000, max: 9000, wantAcceptance: true},
		{raw: "", wantErr: "9000-9099"},
		{raw: "9000", wantErr: "is not a range"},
		{raw: "nine-9099", wantErr: "does not begin with a number"},
		{raw: "9000-ninety", wantErr: "does not end with a number"},
		{raw: "0-9099", wantErr: "they start at 100"},
		{raw: "9099-9000", wantErr: "runs backwards"},
	} {
		min, max, err := parseRange(tc.raw)
		if tc.wantAcceptance {
			if err != nil {
				t.Errorf("parseRange(%q): %v", tc.raw, err)
			} else if min != tc.min || max != tc.max {
				t.Errorf("parseRange(%q) = %d-%d, want %d-%d", tc.raw, min, max, tc.min, tc.max)
			}
			continue
		}
		if err == nil {
			t.Errorf("parseRange(%q) = %d-%d, want a refusal", tc.raw, min, max)
			continue
		}
		if !strings.Contains(err.Error(), tc.wantErr) {
			t.Errorf("parseRange(%q) said %q, want it to mention %q", tc.raw, err, tc.wantErr)
		}
	}
}

// A range smaller than the procedure needs is a typo, and finding out at cycle
// nineteen wastes an afternoon.
func TestARangeTooSmallForTheProcedureIsRefusedBeforeTheFirstCycle(t *testing.T) {
	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_VMID_RANGE", "9000-9001")
	_, missing := preflight()
	joined := strings.Join(missing, "\n")
	if !strings.Contains(joined, "ZOOMIES_PROXMOX_VMID_RANGE") {
		t.Fatalf("a two-identifier range for a %d-machine procedure was accepted:\n%s", qualificationCycles, joined)
	}
}

// The template is a VMID, not a name: every machine starts as a clone of one,
// and a template that cannot be identified is not a prerequisite half-met.
func TestATemplateThatIsNotAVMIDIsRefused(t *testing.T) {
	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_TEMPLATE", "ubuntu-24.04-template")
	_, missing := preflight()
	if !strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_TEMPLATE") {
		t.Error("a template named rather than numbered was accepted")
	}
}

// The runner backend inside the guest is one of the three this product has.
func TestTheGuestRunnerBackendIsOneOfTheThreeThatExist(t *testing.T) {
	for _, backend := range []string{"docker", "podman", "process"} {
		clearCluster(t)
		t.Setenv("ZOOMIES_PROXMOX_BACKEND", backend)
		_, missing := preflight()
		if strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_BACKEND") {
			t.Errorf("%s was refused as a guest backend", backend)
		}
	}
	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_BACKEND", "kubernetes")
	_, missing := preflight()
	if !strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_BACKEND") {
		t.Error("a backend this product does not have was accepted")
	}
}

// A CA file that cannot be read is named, rather than becoming a handshake
// failure twenty minutes later.
func TestACertificateAuthorityFileThatCannotBeReadIsReportedHere(t *testing.T) {
	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_CA_PEM_FILE", filepath.Join(t.TempDir(), "absent.pem"))
	_, missing := preflight()
	if !strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_CA_PEM_FILE") {
		t.Error("an unreadable CA file was left to fail during the handshake")
	}
}

// The setting people get wrong: a guest enrols by calling back, so a controller
// address without a port -- or one that is not a URL -- is a fleet of machines
// that build correctly and never join.
func TestAControllerAddressAGuestCannotCallBackOnIsRefused(t *testing.T) {
	for _, raw := range []string{"not a url", "http://controller", "controller:8080"} {
		clearCluster(t)
		t.Setenv("ZOOMIES_PROXMOX_CONTROLLER_URL", raw)
		_, missing := preflight()
		if !strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_CONTROLLER_URL") {
			t.Errorf("%q was accepted as an address a guest could reach", raw)
		}
	}

	clearCluster(t)
	t.Setenv("ZOOMIES_PROXMOX_CONTROLLER_URL", "http://10.0.0.5:8080")
	_, missing := preflight()
	if strings.Contains(strings.Join(missing, "\n"), "ZOOMIES_PROXMOX_CONTROLLER_URL") {
		t.Errorf("a reachable address was refused:\n%s", strings.Join(missing, "\n"))
	}
}

// The range on the env and the range on the wire are the same range.
func TestTheRangeTheRunMayAllocateInIsTheRangeItWasGiven(t *testing.T) {
	e := env{vmidMin: 9000, vmidMax: 9099}
	if got := e.vmidRange(); got != (Range{Min: 9000, Max: 9099}) {
		t.Errorf("vmidRange() = %v", got)
	}
	if got := e.vmidRange().String(); got != "9000-9099" {
		t.Errorf("the range reads as %q", got)
	}
}

// Qualification is of the built artefact, not of one the test compiles: a
// binary built here with different flags is not the thing being qualified.
func TestTheBinaryUnderQualificationIsTheBuiltOneBesideGoMod(t *testing.T) {
	got := builtBinary()
	if filepath.Base(got) != "zoomies" {
		t.Errorf("builtBinary() = %q, want the zoomies binary", got)
	}
	if got != "zoomies" {
		if _, err := os.Stat(filepath.Join(filepath.Dir(got), "go.mod")); err != nil {
			t.Errorf("builtBinary() = %q, which is not beside a go.mod: %v", got, err)
		}
	}
}

// A port for the default controller URL, asked of the kernel rather than
// guessed, and a usable one even when it cannot be.
func TestAPortIsAskedForRatherThanPickedOutOfTheAir(t *testing.T) {
	p := freePortNumber()
	if p <= 0 || p > 65535 {
		t.Errorf("freePortNumber() = %d", p)
	}
}

//go:build e2e

package proxmox

import (
	"context"
	"fmt"
	"os"
	"strconv"
	"strings"
	"testing"
	"time"
)

// The live qualification: twenty create, enrol, run, drain and delete cycles
// against a real Proxmox VE cluster, the five fault cases the roadmap names, and
// the closing inventory reconciliation that decides all of it.
//
// roadmap/validation/proxmox-qualification.md is the procedure, and this file
// produces exactly the evidence its tables ask for. The two must not disagree:
// if a case here stops matching a row there, the row is the specification and
// this is what has drifted.
//
// Two things to know before reading it. Nothing is created until every
// prerequisite holds, including the read-only ones against the cluster itself.
// And the blast radius -- the cluster, the node, the storage, the VMID range and
// everything already in it -- is written to a ledger outside the temp directory
// before the first call that could build anything, so a run killed at any point
// leaves a record of where to go and look.

// fixture is everything the cases share: one controller, one provider, one
// installation and two pools.
type fixture struct {
	t       *testing.T
	e       env
	rec     *Record
	led     *Ledger
	cluster *Cluster
	ctl     *controllerProcess
	api     *client

	runID          string
	installationID string
	providerID     string
	settings       map[string]string
	pools          []poolRef
}

// poolRef is one pool and the label that is unique to it, which is what keeps
// two pools -- and two concurrent runs against one organisation -- out of each
// other's jobs.
type poolRef struct {
	ID    string
	Name  string
	Label string
}

func TestProxmoxQualification(t *testing.T) {
	if !requested() {
		t.Skip(skipReason())
	}

	// Before anything: is there time to finish? A run killed part-way leaves
	// virtual machines behind and never reaches the reconciliation that would
	// have found them, so this is the first assertion rather than a comment.
	if left, ok := remaining(t); ok && left < qualificationBudget {
		t.Fatalf("this procedure's waits add up to %s and `go test` has given it %s.\n"+
			"Run it with a timeout that fits: `make test-e2e-proxmox`. Starting now would build machines "+
			"and be killed before the closing reconciliation could account for them",
			qualificationBudget, left.Round(time.Second))
	}

	e, missing := preflight()
	if len(missing) > 0 {
		blocked(t, missing)
	}

	cluster, err := NewCluster(ClusterOptions{
		Endpoint: e.endpoint, Token: e.token, Secret: e.secret,
		CAPEMFile: e.caPEMFile, Insecure: e.insecure,
	})
	if err != nil {
		blocked(t, []string{"the cluster credential is unusable: " + err.Error()})
	}
	ctx, cancel := context.WithTimeout(context.Background(), waitProviderChecked)
	facts, missing := preflightCluster(ctx, cluster, e)
	cancel()
	if len(missing) > 0 {
		blocked(t, missing)
	}

	runID := newRunID()
	rec := newRecord(runID)
	t.Cleanup(func() {
		path := recordPath(runID)
		if err := rec.Write(path); err != nil {
			t.Errorf("writing the qualification evidence: %v", err)
			return
		}
		t.Logf("evidence: %s", path)
	})

	// The ledger claims the blast radius before anything is created, and the
	// sweep reports what earlier runs left, before this run adds to it.
	led, err := openLedger(runID, "zoomies-pve-"+runID, e, facts.PreexistingVMIDs)
	if err != nil {
		blocked(t, []string{"the ledger could not be opened: " + err.Error()})
	}
	sweep(t, runID, e)

	f := &fixture{t: t, e: e, rec: rec, led: led, cluster: cluster, runID: runID}
	f.describeSetup(facts)

	// The controller starts before the cleanup below is registered, so that
	// cleanup order puts them the right way round: t.Cleanup runs
	// last-registered first, and tidying up has to happen while the API it
	// deletes through is still listening.
	f.ctl = startController(t, e)
	f.api = newClient(t, f.ctl)
	t.Cleanup(func() { f.tidyUp() })

	f.connectGitHub()
	f.createProvider()
	f.createPools()

	// The cases, in the record's order. Each is a subtest so that one failing
	// does not take the reconciliation with it -- the reconciliation is the step
	// that decides qualification, and a failed run is exactly when it matters.
	t.Run("scale from zero", f.scaleFromZero)
	t.Run("twenty cycles", f.twentyCycles)
	t.Run("multi-pool burst", f.multiPoolBurst)
	t.Run("controller restart mid-create", f.restartMidCreate)
	t.Run("bootstrap failure", f.bootstrapFailure)
	t.Run("delete failure", f.deleteFailure)
	t.Run("closing inventory reconciliation", f.reconcile)
}

// blocked is a prerequisite that is not there. It is a failure when somebody
// asked for a qualification and a skip on a laptop, and it is never silent:
// before this distinction existed, a harness that had never once talked to a
// hypervisor reported the same green as one that had run the whole procedure.
func blocked(t *testing.T, missing []string) {
	t.Helper()
	msg := "blocked, so nothing was created:\n  " + strings.Join(missing, "\n  ")
	if required() {
		t.Fatal(msg)
	}
	t.Skip(msg)
}

// sweep reports what earlier runs left behind, before this run creates
// anything, so that its findings belong to them and cannot be confused with
// this one's.
//
// It reports and does not delete. A stale ledger names virtual machines on
// somebody's cluster, and a harness that quietly destroyed them would be
// destroying the evidence of its own last failure.
func sweep(t *testing.T, runID string, e env) {
	t.Helper()
	stale, err := staleLedgers(runID, e)
	if err != nil {
		t.Logf("sweep: could not read the ledger directory: %v", err)
		return
	}
	for _, rec := range stale {
		t.Logf("sweep: run %s (%s) never closed its ledger and may have left: %s",
			rec.RunID, rec.StartedAt.Format(time.RFC3339), strings.Join(rec.Outstanding(), ", "))
	}
	if len(stale) > 0 {
		t.Logf("sweep: %d earlier run(s) did not finish tidying up; "+
			"`go run ./test/e2e/proxmox/verify` says what is still on the cluster", len(stale))
	}
}

