	}
}

// ---------------------------------------------------------------------------
// One cycle
// ---------------------------------------------------------------------------

// cycleResult is what one cycle observed, and the phases it timed.
type cycleResult struct {
	machineID string
	name      string
	vmid      int
	node      string
	jobOK     bool
	notes     []string
}

// runCycle is the procedure's unit: queued work with nowhere to go, a machine
// bought for it, a guest that enrols, a real job, a drain and a delete that is
// not complete until an inspect cannot find the resource.
func (f *fixture) runCycle(t *testing.T, pool poolRef, timed bool) cycleResult {
	t.Helper()
	var out cycleResult

	before := map[string]bool{}
	for _, m := range f.api.machines() {
		before[m.ID] = true
	}

	dispatchedAt := time.Now()
	_ = dispatchWorkflow(t, f.e, pool.Label)

	// 1. A machine row must appear. Nothing has been built yet: this is the
	//    fleet deciding, and a long wait here means the demand never reached the
	//    provider rather than that the hypervisor is slow.
	var id string
	waitFor(t, waitFirstMachine, "a machine to be planned for "+pool.Name, func() bool {
		for _, m := range f.api.machines() {
			if !before[m.ID] {
				id = m.ID
				return true
			}
		}
		return false
	})
	out.machineID = id
	name := f.api.machine(id).Name
	out.name = name
	if err := f.led.created(KindMachine, id, name); err != nil {
		t.Fatalf("recording the machine in the ledger: %v", err)
	}

	// 2. As soon as the provider has chosen an identifier, write it down. The
	//    window between the row and the identifier is the one in which a run can
	//    die owning a guest it cannot name.
	w := newWatch()
	if !w.until(f.api, id, waitMachineCreated, func(m machineView) bool { return m.ResourceID != "" }) {
		t.Fatalf("machine %s has no resource after %s: %s", id, waitMachineCreated, w.last.complaint())
	}
	out.vmid, out.node = w.last.vmid(), w.last.ResourceZone
	if err := f.led.placed(id, out.node, out.vmid); err != nil {
		t.Fatalf("recording where the machine was built: %v", err)
	}
	if !f.e.vmidRange().contains(out.vmid) {
		t.Fatalf("machine %s was built at VMID %d, outside the reserved range %s; "+
			"the range is the one thing that keeps this procedure off somebody else's guests",
			id, out.vmid, f.e.vmidRange())
	}

	// 3. It must become a host.
	if !w.until(f.api, id, waitMachineReady, func(m machineView) bool {
		return m.State == "ready" || m.State == "failed" || m.State == "quarantined"
	}) {
		t.Fatalf("machine %s stopped at %q after %s: %s", id, w.last.State, waitMachineReady, w.last.complaint())
	}
	if w.last.State != "ready" {
		t.Fatalf("machine %s ended %q rather than ready: %s", id, w.last.State, w.last.complaint())
	}
	if w.last.HostID == "" {
		t.Errorf("machine %s is ready and linked to no host, so nothing could ever be scheduled on it", id)
	}

	// 4. A real job, on that machine.
	job := f.waitForJob(t, pool)
	out.jobOK = job.Conclusion == "success"
	if !out.jobOK {
		t.Errorf("the job on %s concluded %q, want success", pool.Name, job.Conclusion)
	}

	// 5. Drain, and wait for the last runner to finish.
	drainAt := time.Now()
	f.api.post("/machines/"+id+"/drain", map[string]any{}, nil)
	if !w.until(f.api, id, waitMachineDrained, func(m machineView) bool {
		return f.runnersOn(m.HostID) == 0
	}) {
		t.Fatalf("machine %s still has %d runner(s) %s after being drained",
			id, f.runnersOn(w.last.HostID), waitMachineDrained)
	}
	drainedAt := time.Now()

	// 6. Delete, and do not believe it until an inspect cannot find it.
	f.api.del("/machines/" + id)
	if !w.until(f.api, id, waitMachineDeleted, func(m machineView) bool { return m.State == "deleted" }) {
		t.Fatalf("machine %s is %q %s after the delete was issued: %s",
			id, w.last.State, waitMachineDeleted, w.last.complaint())
	}
	if w.last.DeletedAt == nil {
		t.Errorf("machine %s says deleted and carries no confirmation timestamp; "+
			"only an inspect that could not find the resource writes that one", id)
	}
	f.led.removed(KindMachine, id)

	if timed {
		f.timeCycle(w.last, job, dispatchedAt, drainAt, drainedAt)
	}
	return out
}

// jobView is the part of GET /jobs this procedure reads.
type jobView struct {
	ID          string    `json:"id"`
	State       string    `json:"state"`
	Conclusion  string    `json:"conclusion"`
	RunnerID    string    `json:"runner_id"`
	Labels      []string  `json:"labels"`
	QueuedAt    time.Time `json:"queued_at"`
	StartedAt   time.Time `json:"started_at"`
	CompletedAt time.Time `json:"completed_at"`
}

// waitForJob waits for this pool's job to finish. The pool's label is unique to
// this run, so a job carrying it is ours by construction.
func (f *fixture) waitForJob(t *testing.T, pool poolRef) jobView {
	t.Helper()
	var found jobView
	waitFor(t, waitJobCompleted, "a job to complete on "+pool.Name, func() bool {
		var out struct {
			Items []jobView `json:"items"`
		}
		f.api.get("/jobs?pool_id="+pool.ID, &out)
		for _, j := range out.Items {
			if j.State != "completed" {
				continue
			}
			var full jobView
			f.api.get("/jobs/"+j.ID, &full)
			found = full
			return true
		}
		return false
	})
	if found.RunnerID == "" {
		t.Errorf("the completed job on %s is not linked to the runner that ran it", pool.Name)
	}
	return found
}

// runnersOn is how many live runners a host still has. It is asked of the
// controller because the question is about the fleet's own accounting: a drain
// is finished when nothing is running on the machine.
func (f *fixture) runnersOn(hostID string) int {
	if hostID == "" {
		return 0
	}
	var out struct {
		Items []struct {
			State string `json:"state"`
		} `json:"items"`
	}
	f.api.get("/runners?host_id="+hostID+"&include_removed=false", &out)
	return len(out.Items)
}

// timeCycle files one cycle's phases into the evidence.
//
// Everything that can come from the machine's timeline does, because those are
// the controller's own timestamps and are exact; only the two phases with no
// timestamp of their own -- a guest that has begun answering, a drain that has
// finished -- are this harness's observations, and the record says so.
func (f *fixture) timeCycle(m machineView, job jobView, dispatchedAt, drainAt, drainedAt time.Time) {
	at := func(phase string) (time.Time, bool) { return m.at(phase) }
	span := func(name string, from, to time.Time, ok bool) {
		if ok && !from.IsZero() && !to.IsZero() {
			f.rec.timings.add(name, to.Sub(from))
		}
	}

	queued := job.QueuedAt
	if queued.IsZero() {
		// GitHub's own queue time is the honest denominator; without it, when
		// this run asked for the work is the next best thing.
		queued = dispatchedAt
	}
	creating, okCreating := at("creating")
	span("queue to create issued", queued, creating, okCreating)

	running, okRunning := at("starting")
	if !okRunning {
		// A provider whose create leaves the guest running skips starting, and
		// the phase then ends where the create did.
		running, okRunning = at("created")
	}
	span("create to resource running", creating, running, okCreating && okRunning)

	bootstrapped, okBootstrapped := at("bootstrapped")
	span("running to guest agent answering", running, bootstrapped, okRunning && okBootstrapped)

	ready, okReady := at("ready")
	span("bootstrap to host joined", bootstrapped, ready, okBootstrapped && okReady)
	span("host joined to first job started", ready, job.StartedAt, okReady && !job.StartedAt.IsZero())

	span("drain requested to last runner finished", drainAt, drainedAt, true)

	deleting, okDeleting := at("deleting")
	deleted, okDeleted := at("deleted")
	span("delete issued to resource confirmed gone", deleting, deleted, okDeleting && okDeleted)
}

// ---------------------------------------------------------------------------
// The cases
// ---------------------------------------------------------------------------

// scaleFromZero is the first case for a reason: it is the only moment in the
// whole procedure when the fleet demonstrably has nothing at all. A pool with no
// eligible host is not the same as a full fleet, and this is where the
// difference is worth money.
func (f *fixture) scaleFromZero(t *testing.T) {
	assertTimeToFinish(t, scaleFromZeroBudget, "scale from zero")
	row := CaseRow{Number: 2, Case: "Scale from zero — no hosts at all, then queued work"}
	defer func() { f.finish(t, &row) }()

	var hosts struct {
		Items []struct {
			ID   string `json:"id"`
			Name string `json:"name"`
		} `json:"items"`
	}
	f.api.get("/hosts", &hosts)
	if len(hosts.Items) > 0 {
		t.Fatalf("the fleet already has %d host(s); this case can only prove anything from nothing", len(hosts.Items))
	}
	if ms := f.api.machines(); len(ms) > 0 {
		t.Fatalf("the fleet already has %d machine(s) before the first cycle", len(ms))
	}

	start := time.Now()
	res := f.runCycle(t, f.pools[0], true)
	row.Timings = "from an empty fleet to a deleted machine: " + round(time.Since(start))
	row.Observed = fmt.Sprintf("no hosts and no machines at the start; VM %d on %s served the job and was destroyed",
		res.vmid, res.node)
}

// twentyCycles is the body of the procedure. Twenty, sequentially, so that each
// timing belongs to one machine and the percentiles mean what they say.
func (f *fixture) twentyCycles(t *testing.T) {
	row := CaseRow{Number: 1, Case: fmt.Sprintf("%d full cycles", qualificationCycles)}
	defer func() { f.finish(t, &row) }()

	done := 0
	for i := 1; i <= qualificationCycles; i++ {
		// Before each one rather than once at the start: a cycle that ran long
		// has eaten into what is left, and the run must stop while there is
		// still time to delete what it has built and reconcile the cluster.
		assertTimeToFinish(t, cycleBudget, fmt.Sprintf("cycle %d of %d", i, qualificationCycles))
		res := f.runCycle(t, f.pools[0], true)
		done++
		t.Logf("cycle %d/%d: machine %s at VMID %d on %s, job %s",
			i, qualificationCycles, res.machineID, res.vmid, res.node,
			map[bool]string{true: "succeeded", false: "FAILED"}[res.jobOK])
	}
	row.Observed = fmt.Sprintf("%d of %d cycles completed; every machine was built inside %s",
		done, qualificationCycles, f.e.vmidRange())
	row.Timings = "see the timings table; every figure carries the count it came from"
}

// multiPoolBurst is two pools wanting a machine at the same moment. The failure
// it looks for is the fleet buying the same shortfall twice, or buying one
// machine and leaving the second pool waiting for ever.
func (f *fixture) multiPoolBurst(t *testing.T) {
	assertTimeToFinish(t, multiPoolBurstBudget, "the multi-pool burst")
	row := CaseRow{Number: 3, Case: "Multi-pool burst — two pools demanding at once"}
	defer func() { f.finish(t, &row) }()

	before := map[string]bool{}
	for _, m := range f.api.machines() {
		before[m.ID] = true
	}
	for _, p := range f.pools {
		_ = dispatchWorkflow(t, f.e, p.Label)
	}

	// Both pools must end up with a machine of their own: one machine cannot
	// carry two pools' labels, so a fleet that bought one has left a pool
	// waiting.
	var fresh []machineView
	waitFor(t, waitFirstMachine+waitMachineCreated, "a machine for each of the two pools", func() bool {
		fresh = nil
		for _, m := range f.api.machines() {
			if !before[m.ID] {
				fresh = append(fresh, m)
			}
		}
		return len(fresh) >= len(f.pools)
	})
	for _, m := range fresh {
		if err := f.led.created(KindMachine, m.ID, m.Name); err != nil {
			t.Fatalf("recording a burst machine in the ledger: %v", err)
		}
	}
	if len(fresh) > len(f.pools) {
		t.Errorf("two pools wanted one machine each and the fleet bought %d; "+
			"overlapping demand has been counted twice", len(fresh))
	}

	// Each must reach ready, run its pool's job, and then be taken away again.
	for i, p := range f.pools {
		id := fresh[min(i, len(fresh)-1)].ID
		w := newWatch()
		if !w.until(f.api, id, waitMachineReady+waitMachineCreated, func(m machineView) bool {
			return m.State == "ready" || m.State == "failed" || m.State == "quarantined"
		}) || w.last.State != "ready" {
			t.Fatalf("burst machine %s for %s ended %q: %s", id, p.Name, w.last.State, w.last.complaint())
		}
		if err := f.led.placed(id, w.last.ResourceZone, w.last.vmid()); err != nil {
			t.Fatalf("recording where a burst machine was built: %v", err)
		}
	}
	for _, p := range f.pools {
		job := f.waitForJob(t, p)
		if job.Conclusion != "success" {
			t.Errorf("the burst job on %s concluded %q, want success", p.Name, job.Conclusion)
		}
	}
	for _, m := range fresh {
		f.deleteMachine(t, m.ID)
	}
	row.Observed = fmt.Sprintf("%d pools demanded at once and the fleet bought %d machine(s), one each",
		len(f.pools), len(fresh))
}

// restartMidCreate kills the controller while a create is in flight.
//
// The failure this exists for is the natural reflex: the call did not come back,
// so try again -- and now there are two virtual machines and a row that knows
// about one. The cluster is asked afterwards, not the controller, because the
// controller's opinion of how many VMs it made is the thing under test.
func (f *fixture) restartMidCreate(t *testing.T) {
	assertTimeToFinish(t, restartMidCreateBudget, "the restart mid-create")
	row := CaseRow{Number: 4, Case: "Controller restart mid-create"}
	defer func() { f.finish(t, &row) }()

	before := map[string]bool{}
	for _, m := range f.api.machines() {
		before[m.ID] = true
	}
	_ = dispatchWorkflow(t, f.e, f.pools[0].Label)

	var id string
	waitFor(t, waitFirstMachine, "a machine to be planned", func() bool {
		for _, m := range f.api.machines() {
			if !before[m.ID] {
				id = m.ID
				return true
			}
		}
		return false
	})
	m := f.api.machine(id)
	if err := f.led.created(KindMachine, id, m.Name); err != nil {
		t.Fatalf("recording the machine in the ledger: %v", err)
	}

	// Restart at the instant the create is under way: the row exists, an
	// identifier has been persisted, and the outcome of the call is unknown.
	w := newWatch()
	if !w.until(f.api, id, waitMachineCreated, func(m machineView) bool {
		return m.State == "creating" || m.ResourceID != ""
	}) {
		t.Fatalf("machine %s never reached a create to be interrupted: %s", id, w.last.complaint())
	}
	name := w.last.Name
	f.ctl.restart()
	row.Observed = fmt.Sprintf("restarted while %s was %q", id, w.last.State)

	if !w.until(f.api, id, waitMachineCreated+waitMachineReady, func(m machineView) bool {
		return m.State == "ready" || m.State == "failed" || m.State == "quarantined"
	}) {
		t.Fatalf("machine %s is %q after the restart: %s", id, w.last.State, w.last.complaint())
	}
	if err := f.led.placed(id, w.last.ResourceZone, w.last.vmid()); err != nil {
		t.Fatalf("recording where the machine was built: %v", err)
	}
	if w.last.State != "ready" {
		t.Errorf("machine %s ended %q after a restart mid-create: %s", id, w.last.State, w.last.complaint())
	}

	// The assertion that matters, and it is the cluster's answer rather than
	// the fleet's: one machine, one guest.
	guests := f.guestsNamed(t, name)
	if len(guests) != 1 {
		t.Errorf("the cluster has %d guests named %q after a restart mid-create, want exactly 1: %v",
			len(guests), name, guests)
	}
	row.Observed += fmt.Sprintf("; the cluster holds %d guest named %q afterwards", len(guests), name)
	f.deleteMachine(t, id)
}

// bootstrapFailure gives a machine a guest it cannot bootstrap, and asks that
// the fleet say what went wrong rather than quietly build another.
//
// Two ways to induce it, and the evidence names which was used. A deliberately
// broken template is the procedure's preferred one, because it is the failure
// operators actually have; without one, the machines are given a controller
// address nothing answers on, which fails the same step for a reason the guest
// can also report.
func (f *fixture) bootstrapFailure(t *testing.T) {
	assertTimeToFinish(t, bootstrapFailureBudget, "the induced bootstrap failure")
	row := CaseRow{Number: 5, Case: "Bootstrap failure — a deliberately broken template"}
	defer func() { f.finish(t, &row) }()

	broken := map[string]string{}
	for k, v := range f.settings {
		broken[k] = v
	}
	method := ""
	if f.e.brokenTemplateID > 0 {
		broken["template_id"] = strconv.Itoa(f.e.brokenTemplateID)
		method = fmt.Sprintf("cloned the deliberately broken template %d", f.e.brokenTemplateID)
	} else {
		// TEST-NET-1, which is reserved for documentation and routes nowhere:
		// the guest comes up, the bootstrap runs, and the agent can never reach
		// a controller.
		broken["controller_url"] = "http://192.0.2.1:8080"
		method = "pointed the machines at a controller address nothing answers on (no broken template was supplied)"
	}
	f.api.patch("/providers/"+f.providerID, map[string]any{"settings": broken}, nil)
	defer f.api.patch("/providers/"+f.providerID, map[string]any{"settings": f.settings}, nil)
	row.Observed = method

	before := map[string]bool{}
	for _, m := range f.api.machines() {
		before[m.ID] = true
	}
	_ = dispatchWorkflow(t, f.e, f.pools[0].Label)

	var id string
	waitFor(t, waitFirstMachine, "a machine to be planned for the broken configuration", func() bool {
		for _, m := range f.api.machines() {
			if !before[m.ID] {
				id = m.ID
				return true
			}
		}
		return false
	})
	if err := f.led.created(KindMachine, id, f.api.machine(id).Name); err != nil {
		t.Fatalf("recording the machine in the ledger: %v", err)
	}

	w := newWatch()
	if !w.until(f.api, id, waitMachineCreated+waitMachineFailed, func(m machineView) bool {
		return m.State == "failed" || m.State == "ready"
	}) {
		t.Fatalf("machine %s neither failed nor became ready within %s; it is %q: %s",
			id, waitMachineCreated+waitMachineFailed, w.last.State, w.last.complaint())
	}
	if err := f.led.placed(id, w.last.ResourceZone, w.last.vmid()); err != nil {
		t.Fatalf("recording where the failed machine was built: %v", err)
	}
	if w.last.State == "ready" {
		t.Fatalf("machine %s enrolled anyway, so this case induced nothing: %s", id, method)
	}
	// The two error columns are two systems. A guest that could not be
	// bootstrapped is not a hypervisor complaint, and an operator reading one
	// has to know which half to go and look at.
	if w.last.BootstrapError == "" {
		t.Errorf("machine %s failed with no bootstrap_error (provider_error %q); "+
			"the guest's own complaint is what says what to fix", id, w.last.ProviderError)
	}
	row.Observed += "; failed with " + w.last.complaint()
	row.Human = "none — the machine failed with an explanation and its guest was destroyed"

	// It failed, and its guest exists. Nothing may leave it there.
	f.deleteMachine(t, id)
}

// deleteFailure makes one delete fail and asks that the fleet keep trying.
//
// Proxmox's own protection flag is the fault, because it is a refusal the
// hypervisor really does make, it is reversible, and it cannot be mistaken for
// the machine having been destroyed. A delete that failed must not be recorded
// as a delete that succeeded: that is how an orphan is made.
func (f *fixture) deleteFailure(t *testing.T) {
	assertTimeToFinish(t, deleteFailureBudget, "the induced delete failure")
	row := CaseRow{Number: 6, Case: "Deletion retry — a delete that fails once"}
	defer func() { f.finish(t, &row) }()

	before := map[string]bool{}
	for _, m := range f.api.machines() {
		before[m.ID] = true
	}
	_ = dispatchWorkflow(t, f.e, f.pools[0].Label)

	var id string
	waitFor(t, waitFirstMachine, "a machine to be planned", func() bool {
		for _, m := range f.api.machines() {
			if !before[m.ID] {
				id = m.ID
				return true
			}
		}
		return false
	})
	if err := f.led.created(KindMachine, id, f.api.machine(id).Name); err != nil {
		t.Fatalf("recording the machine in the ledger: %v", err)
	}
	w := newWatch()
	if !w.until(f.api, id, waitMachineCreated+waitMachineReady, func(m machineView) bool {
		return m.State == "ready" || m.State == "failed" || m.State == "quarantined"
	}) || w.last.State != "ready" {
		t.Fatalf("machine %s ended %q rather than ready: %s", id, w.last.State, w.last.complaint())
	}
	if err := f.led.placed(id, w.last.ResourceZone, w.last.vmid()); err != nil {
		t.Fatalf("recording where the machine was built: %v", err)
	}
	node, vmid := w.last.ResourceZone, w.last.vmid()

	ctx, cancel := context.WithTimeout(context.Background(), waitMachineDeleted)
	defer cancel()
	if err := f.cluster.setProtection(ctx, node, vmid, true); err != nil {
		t.Fatalf("could not protect VM %d to make its delete fail: %v", vmid, err)
	}
	// Clearing it is not optional: a protected guest nothing can destroy is the
	// one leftover this procedure could create and never clean up.
	defer func() {
		clear, cancel := context.WithTimeout(context.Background(), waitMachineDeleted)
		defer cancel()
		if err := f.cluster.setProtection(clear, node, vmid, false); err != nil {
			t.Errorf("could not clear the protection flag on VM %d; it must be cleared by hand "+
				"or nothing will ever destroy it: %v", vmid, err)
		}
	}()

	f.api.post("/machines/"+id+"/drain", map[string]any{}, nil)
	f.api.del("/machines/" + id)
	if !w.until(f.api, id, waitMachineDeleted, func(m machineView) bool {
		return m.Attempts > 0 && m.ProviderError != ""
	}) {
		t.Fatalf("the delete of protected VM %d was not recorded as having failed: state %q, attempts %d, %s",
			vmid, w.last.State, w.last.Attempts, w.last.complaint())
	}
	if w.last.State == "deleted" {
		t.Fatalf("machine %s was recorded as deleted while its guest is still on the cluster; "+
			"a 200 from a delete call is not evidence that a resource is gone", id)
	}
	row.Observed = fmt.Sprintf("VM %d refused to be destroyed while protected; the fleet recorded %d attempt(s) and %s",
		vmid, w.last.Attempts, w.last.complaint())

	// Clear the fault and let the retry through.
	clearCtx, clearCancel := context.WithTimeout(context.Background(), waitMachineDeleted)
	err := f.cluster.setProtection(clearCtx, node, vmid, false)
	clearCancel()
	if err != nil {
		t.Fatalf("could not clear the protection flag on VM %d: %v", vmid, err)
	}
	if !w.until(f.api, id, waitMachineDeleted, func(m machineView) bool { return m.State == "deleted" }) {
		t.Fatalf("machine %s did not recover once the fault was cleared; it is %q after %s: %s",
			id, w.last.State, waitMachineDeleted, w.last.complaint())
	}
	f.led.removed(KindMachine, id)
	row.Observed += "; it was destroyed on a later attempt once the flag was cleared"
	row.Human = "none — the retry succeeded without anybody intervening"
}

// reconcile is the case that decides qualification, and it is deliberately last.
//
// It asks the cluster, not the fleet: every VM in the range and every disk on
// the storage, accounted for against the ledger this run wrote before it created
// anything. No owned resource may be left unexplained.
func (f *fixture) reconcile(t *testing.T) {
	row := CaseRow{Number: 7, Case: "Closing inventory reconciliation"}
	defer func() { f.finish(t, &row) }()

	// Anything still alive is deleted first, or the reconciliation would be
	// measuring the harness's unfinished business rather than the product's.
	for _, m := range f.api.machines() {
		if m.State != "deleted" {
			f.deleteMachine(t, m.ID)
		}
	}

	ctx, cancel := context.WithTimeout(context.Background(), waitReconciliation)
	defer cancel()
	inv, err := f.cluster.Take(ctx, f.e.node, f.e.storage)
	if err != nil {
		t.Fatalf("listing the cluster for the closing reconciliation: %v", err)
	}
	rec := Reconcile(inv, []LedgerRecord{f.led.record()}, f.e.vmidRange())
	f.rec.Reconciliation = &rec

	for _, fnd := range rec.Findings {
		if fnd.Verdict == Accounted {
			continue
		}
		t.Logf("reconciliation: %s VM %d (%s): %s", fnd.Verdict, fnd.VMID, fnd.Name, fnd.Detail)
	}
	if !rec.OK() {
		row.Human = fmt.Sprintf("%d owned resource(s) and %d disk(s) are still on the cluster; "+
			"delete them by hand and record why", rec.Unexplained, rec.DisksLeft)
		t.Fatalf("%d unexplained owned resource(s) and %d disk(s) left on %s. "+
			"An orphan found and deliberately left is a finding; an orphan nobody noticed is a failure of this procedure",
			rec.Unexplained, rec.DisksLeft, f.e.storage)
	}
	row.Observed = fmt.Sprintf("%d created, %d confirmed deleted, %d VM(s) left in %s, %d disk(s) left on %s",
		rec.Created, rec.Confirmed, rec.VMsAtEnd, rec.Range, rec.DisksLeft, f.e.storage)

	// And the other half of "gone": GitHub must not still be holding
	// registrations for machines that no longer exist.
	for _, p := range f.pools {
		left, err := githubRunnersWithLabel(f.e, p.Label)
		if err != nil {
			t.Errorf("checking GitHub for leftover registrations on %s: %v", p.Name, err)
			continue
		}
		if len(left) > 0 {
			t.Errorf("GitHub still holds %d registration(s) carrying %s after every machine was destroyed: %s",
				len(left), p.Label, strings.Join(left, ", "))
		}
	}
}

// ---------------------------------------------------------------------------
// Helpers the cases share
// ---------------------------------------------------------------------------

// finish writes one case's row, whatever happened to it. A case that failed is
// the one worth reading, and the row is where a person is told what to do about
// it.
func (f *fixture) finish(t *testing.T, row *CaseRow) {
	row.Outcome = "passed"
	if t.Failed() {
		row.Outcome = "FAILED"
		if row.Human == "" {
			row.Human = "read this run's log, then run `go run ./test/e2e/proxmox/verify` " +
				"against the cluster: a failed case may have left a guest behind"
		}
	}
	if row.Human == "" {
		row.Human = "none"
	}
	f.rec.addCase(*row)
}

// deleteMachine takes one machine away and waits for the resource to be
// confirmed gone.
func (f *fixture) deleteMachine(t *testing.T, id string) {
	t.Helper()
	f.api.post("/machines/"+id+"/drain", map[string]any{}, nil)
	f.api.del("/machines/" + id)
	w := newWatch()
	if !w.until(f.api, id, waitMachineDrained+waitMachineDeleted, func(m machineView) bool {
		return m.State == "deleted"
	}) {
		t.Errorf("machine %s is %q rather than deleted after %s: %s",
			id, w.last.State, waitMachineDrained+waitMachineDeleted, w.last.complaint())
		return
	}
	f.led.removed(KindMachine, id)
}

// guestsNamed asks the cluster how many guests carry one name. It is how "one
// machine, one resource" is asserted: the fleet's own count of what it built is
// the thing being doubted.
func (f *fixture) guestsNamed(t *testing.T, name string) []string {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), waitReconciliation)
	defer cancel()
	inv, err := f.cluster.Take(ctx, f.e.node, "")
	if err != nil {
		t.Errorf("listing the cluster: %v", err)
		return nil
	}
	var found []string
	for _, g := range inv.Guests {
		if g.Name == name {
			found = append(found, g.String())
		}
	}
	return found
}

// tidyUp removes everything this run created, in the order that makes each step
// possible, and records whatever it could not.
//
// It runs however the test ends. Anything left in the ledger afterwards is on
// somebody's real cluster, so it goes into the evidence rather than being
// dropped.
func (f *fixture) tidyUp() {
	t := f.t
	deadline := time.Now().Add(waitCleanup)

	// Machines first, and through the product, so that a machine the fleet
	// still owns is destroyed by the code that owns it.
	for _, res := range f.led.record().Resources {
		if res.Kind != KindMachine || res.RemovedAt != nil || time.Now().After(deadline) {
			continue
		}
		if !f.api.try("POST", "/machines/"+res.ID+"/drain", map[string]any{}, nil) {
			continue
		}
		if !f.api.try("DELETE", "/machines/"+res.ID, nil, nil) {
			continue
		}
		w := newWatch()
		if w.until(f.api, res.ID, waitMachineDeleted, func(m machineView) bool { return m.State == "deleted" }) {
			f.led.removed(KindMachine, res.ID)
			continue
		}
		t.Errorf("cleanup: machine %s (VM %d on %s) is %q and was not destroyed; "+
			"it is still on the cluster", res.ID, res.VMID, res.Node, w.last.State)
	}

	for _, res := range f.led.record().Resources {
		if res.RemovedAt != nil {
			continue
		}
		switch res.Kind {
		case KindPool:
			if f.api.try("DELETE", "/pools/"+res.ID+"?force=true", nil, nil) {
				f.led.removed(KindPool, res.ID)
			}
		}
	}
	for _, res := range f.led.record().Resources {
		if res.RemovedAt != nil {
			continue
		}
		switch res.Kind {
		case KindProvider:
			if f.api.try("DELETE", "/providers/"+res.ID, nil, nil) {
				f.led.removed(KindProvider, res.ID)
			}
		case KindInstallation:
			if f.api.try("DELETE", "/installations/"+res.ID, nil, nil) {
				f.led.removed(KindInstallation, res.ID)
			}
		}
	}

	f.rec.Residual = f.led.outstanding()
	if len(f.rec.Residual) == 0 {
		if err := f.led.close(); err != nil {
			t.Errorf("closing the ledger: %v", err)
		}
		return
	}
	t.Errorf("this run left %d thing(s) behind, which are on a real cluster or organisation now: %s. "+
		"The ledger at %s names them, and `go run ./test/e2e/proxmox/verify` will find the guests",
		len(f.rec.Residual), strings.Join(f.rec.Residual, ", "), LedgerDir())
}

func mustInt(t *testing.T, s string) int64 {
	t.Helper()
	n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		t.Fatalf("%q is not a number: %v", s, err)
	}
	return n
}

func readFile(t *testing.T, path string) string {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading %s: %v", path, err)
	}
	return string(raw)
}

package proxmox

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// The evidence one run produces, in the shape roadmap/validation/proxmox-qualification.md
// asks for.
//
// It is written whatever the outcome, because a run that failed is the one worth
// reading, and it is written to a file of its own rather than into the record:
// the record states the procedure, and a harness that edited it could quietly
// make the procedure describe whatever happened. A person copies these tables
// in, having read them.
//
// The vocabulary is the drill record's -- what was expected, what was observed,
// and the last column, "human action needed", which is the one the record is
// read for. A run that recovers on its own and a run that leaves somebody a VM
// to delete are different findings, and only the row says which.

// phaseOrder is the seven timings the qualification record asks for, in the
// order it asks for them. Written here rather than derived from whatever the
// run happened to measure, so that a phase nobody managed to time is an empty
// row rather than an absent one.
var phaseOrder = []string{
	"queue to create issued",
	"create to resource running",
	"running to guest agent answering",
	"bootstrap to host joined",
	"host joined to first job started",
	"drain requested to last runner finished",
	"delete issued to resource confirmed gone",
}

// Timings collects one phase's durations across the cycles.
//
// Every figure it reports carries the count it came from. That is not
// decoration: "p95" of three samples is a sentence about three machines, and the
// record says "p95 of 20" precisely so that a run which managed four cycles
// cannot be read as having done twenty.
type Timings struct {
	samples map[string][]time.Duration
}

func newTimings() *Timings { return &Timings{samples: map[string][]time.Duration{}} }

// add records one observation. A negative or zero duration is dropped rather
// than averaged in: it means two timestamps arrived out of order, and a phase
// that took no time would drag a percentile towards a figure no machine ever
// achieved.
func (t *Timings) add(phase string, d time.Duration) {
	if d <= 0 {
		return
	}
	t.samples[phase] = append(t.samples[phase], d)
}

// stat is the p50, the p95 and the count they came from.
//
// Nearest-rank, not interpolated: with twenty samples an interpolated p95 is a
// number halfway between two machines, and the question being asked is "how slow
// was the slow one".
func (t *Timings) stat(phase string) (p50, p95 time.Duration, n int) {
	xs := append([]time.Duration(nil), t.samples[phase]...)
	if len(xs) == 0 {
		return 0, 0, 0
	}
	sort.Slice(xs, func(i, j int) bool { return xs[i] < xs[j] })
	at := func(q float64) time.Duration {
		i := int(math.Ceil(q*float64(len(xs)))) - 1
		return xs[max(i, 0)]
	}
	return at(0.5), at(0.95), len(xs)
}

// CaseRow is one row of the record's "The runs" table.
type CaseRow struct {
	Number   int    `json:"number"`
	Case     string `json:"case"`
	Outcome  string `json:"outcome"`
	Timings  string `json:"timings"`
	Observed string `json:"observed"`
	// Human is what a person has to do about this row. "none" is the good
	// value and the only one that needs no explanation.
	Human string `json:"human_action_needed"`
}

// SetupRow is one row of the record's setup table: a number without the setup
// that produced it is not evidence.
type SetupRow struct {
	Label string `json:"label"`
	Value string `json:"value"`
}

// Record is the whole of one run's evidence.
type Record struct {
	RunID      string     `json:"run_id"`
	Commit     string     `json:"commit"`
	RunLink    string     `json:"run_link,omitempty"`
	StartedAt  time.Time  `json:"started_at"`
	FinishedAt time.Time  `json:"finished_at"`
	Setup      []SetupRow `json:"setup"`
	Cases      []CaseRow  `json:"cases"`
	// Reconciliation is the closing count. Absent means the run never reached
	// it, which is itself the finding: the reconciliation is the step that
	// decides qualification.
	Reconciliation *Reconciliation `json:"reconciliation,omitempty"`
	// Residual is what this run created and could not remove. Empty is the only
	// good value.
	Residual []string `json:"residual_cleanup,omitempty"`

	timings *Timings
}

func newRecord(runID string) *Record {
	return &Record{RunID: runID, Commit: commit(), RunLink: runLink(), StartedAt: time.Now().UTC(), timings: newTimings()}
}

func (r *Record) setup(label, value string) {
	r.Setup = append(r.Setup, SetupRow{Label: label, Value: strings.TrimSpace(value)})
}

func (r *Record) addCase(row CaseRow) { r.Cases = append(r.Cases, row) }

// Markdown renders the tables the qualification record holds, filled in.
func (r *Record) Markdown() string {
	var b strings.Builder
	fmt.Fprintf(&b, "# Proxmox VE qualification — evidence from run %s\n\n", r.RunID)
	fmt.Fprintf(&b, "Produced by `test/e2e/proxmox` at %s, on commit %s",
		r.FinishedAt.Format(time.RFC3339), r.Commit)
	if r.RunLink != "" {
		fmt.Fprintf(&b, ", from %s", r.RunLink)
	}
	b.WriteString(".\n\nThese are the tables `roadmap/validation/proxmox-qualification.md` asks for. " +
		"Read them, then copy them into that record; nothing edits it automatically, because the record " +
		"states the procedure and a harness that rewrote it could make the procedure describe whatever happened.\n\n")

	b.WriteString("## Setup\n\n| | |\n| --- | --- |\n")
	for _, row := range r.Setup {
		fmt.Fprintf(&b, "| %s | %s |\n", row.Label, orDash(row.Value))
	}

	b.WriteString("\n## The runs\n\n")
	b.WriteString("| # | Case | Outcome | Timings | What was observed | Human action needed |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	for _, c := range r.Cases {
		fmt.Fprintf(&b, "| %d | %s | %s | %s | %s | %s |\n",
			c.Number, c.Case, c.Outcome, orDash(c.Timings), orDash(c.Observed), orDash(c.Human))
	}

	b.WriteString("\n## Timings\n\n")
	b.WriteString("Each with the count it came from: a percentile without its denominator is not a measurement.\n\n")
	b.WriteString("| Phase | p50 | p95 | n |\n| --- | --- | --- | --- |\n")
	for _, phase := range phaseOrder {
		p50, p95, n := r.timings.stat(phase)
		if n == 0 {
			fmt.Fprintf(&b, "| %s | — | — | 0 (never measured) |\n", phase)
			continue
		}
		fmt.Fprintf(&b, "| %s | %s | %s | %d |\n", phase, round(p50), round(p95), n)
	}

	b.WriteString("\n## The closing reconciliation\n\n")
	if r.Reconciliation == nil {
		b.WriteString("**The run never reached the reconciliation.** Nothing here is qualified: " +
			"the closing count is the step that decides it, and a run that stopped before it has not " +
			"established that it left nothing behind. Run `go run ./test/e2e/proxmox/verify` " +
			"against the cluster before anything else.\n")
	} else {
		rec := r.Reconciliation
		b.WriteString("| | Count | Notes |\n| --- | --- | --- |\n")
		fmt.Fprintf(&b, "| VMs in the range at the start | %d | range %s on %s |\n", rec.VMsAtStart, rec.Range, rec.Storage)
		fmt.Fprintf(&b, "| Machines created during the runs | %d | |\n", rec.Created)
		fmt.Fprintf(&b, "| Machines confirmed deleted | %d | confirmed by an inspect that could not find the resource |\n", rec.Confirmed)
		fmt.Fprintf(&b, "| VMs in the range at the end | %d | |\n", rec.VMsAtEnd)
		fmt.Fprintf(&b, "| Disks left on the storage | %d | |\n", rec.DisksLeft)
		fmt.Fprintf(&b, "| Unexplained owned resources | %d | **must be zero** |\n", rec.Unexplained)
		if len(rec.Findings) > 0 {
			b.WriteString("\nEach resource in the range, and what became of it:\n\n")
			b.WriteString("| Verdict | VMID | Node | Name | Detail |\n| --- | --- | --- | --- | --- |\n")
			for _, f := range rec.Findings {
				fmt.Fprintf(&b, "| %s | %d | %s | %s | %s |\n",
					f.Verdict, f.VMID, orDash(f.Node), orDash(f.Name), f.Detail)
			}
		}
	}

	if len(r.Residual) > 0 {
		b.WriteString("\n## Left behind by this run\n\n")
		b.WriteString("This run created these and could not remove them. They are on somebody's cluster " +
			"or organisation now, and a person has to deal with them.\n\n")
		for _, line := range r.Residual {
			fmt.Fprintf(&b, "* %s\n", line)
		}
	}
	return b.String()
}

// Write saves the evidence as Markdown, with a JSON sibling so that a later run
// can be compared with this one without anybody parsing a table.
func (r *Record) Write(path string) error {
	r.FinishedAt = time.Now().UTC()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("creating the evidence directory: %w", err)
	}
	if err := os.WriteFile(path, []byte(r.Markdown()), 0o644); err != nil {
		return fmt.Errorf("writing the evidence: %w", err)
	}
	raw, err := json.MarshalIndent(struct {
		*Record
		Timings map[string]map[string]any `json:"timings"`
	}{Record: r, Timings: r.timingsJSON()}, "", "  ")
	if err != nil {
		return fmt.Errorf("encoding the evidence: %w", err)
	}
	return os.WriteFile(strings.TrimSuffix(path, ".md")+".json", append(raw, '\n'), 0o644)
}

func (r *Record) timingsJSON() map[string]map[string]any {
	out := map[string]map[string]any{}
	for _, phase := range phaseOrder {
		p50, p95, n := r.timings.stat(phase)
		out[phase] = map[string]any{"p50_ms": p50.Milliseconds(), "p95_ms": p95.Milliseconds(), "n": n}
	}
	return out
}

// recordPath is where the evidence goes: beside the qualification record it
// fills in, named for the commit and the run, so two runs never overwrite one
// another and a figure can always be taken back to the code that produced it.
func recordPath(runID string) string {
	if p := strings.TrimSpace(os.Getenv("ZOOMIES_PROXMOX_RECORD")); p != "" {
		return p
	}
	root := filepath.Dir(builtBinary())
	return filepath.Join(root, "roadmap", "validation",
		fmt.Sprintf("proxmox-qualification-%s-%s.md", commit(), runID))
}

// runLink is where this evidence came from, when it came from CI. A figure is
// worth keeping only if it can be taken back to the run that produced it.
func runLink() string {
	server, repo, id := os.Getenv("GITHUB_SERVER_URL"), os.Getenv("GITHUB_REPOSITORY"), os.Getenv("GITHUB_RUN_ID")
	if server == "" || repo == "" || id == "" {
		return ""
	}
	return fmt.Sprintf("%s/%s/actions/runs/%s", server, repo, id)
}

// round is a duration a person reads: a qualification timing in nanoseconds
// says nothing a hundred milliseconds does not.
func round(d time.Duration) string { return d.Round(100 * time.Millisecond).String() }

func orDash(s string) string {
	if strings.TrimSpace(s) == "" {
		return "—"
	}
	return s
}

package proxmox

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// A phase that took no time did not happen: two timestamps arrived out of
// order. Averaging that in drags a percentile towards a figure no machine ever
// achieved, and the whole point of these numbers is that somebody can plan
// against them.
func TestATimingThatCannotHaveHappenedIsDroppedRatherThanAveragedIn(t *testing.T) {
	ts := newTimings()
	ts.add("create to resource running", 0)
	ts.add("create to resource running", -5*time.Second)
	if _, _, n := ts.stat("create to resource running"); n != 0 {
		t.Errorf("a zero and a negative sample were counted: n = %d", n)
	}

	ts.add("create to resource running", 30*time.Second)
	if p50, p95, n := ts.stat("create to resource running"); n != 1 || p50 != 30*time.Second || p95 != 30*time.Second {
		t.Errorf("one sample reads as p50=%s p95=%s n=%d", p50, p95, n)
	}
}

// Nearest-rank, not interpolated. With twenty samples an interpolated p95 is a
// number halfway between two machines, and the question being asked is "how
// slow was the slow one".
func TestThePercentilesAreMachinesThatExistedRatherThanNumbersBetweenThem(t *testing.T) {
	ts := newTimings()
	for i := 1; i <= 20; i++ {
		ts.add("create to resource running", time.Duration(i)*time.Second)
	}
	p50, p95, n := ts.stat("create to resource running")
	if n != 20 {
		t.Fatalf("n = %d, want 20", n)
	}
	if p50 != 10*time.Second {
		t.Errorf("p50 = %s, want the tenth of twenty", p50)
	}
	if p95 != 19*time.Second {
		t.Errorf("p95 = %s, want the nineteenth of twenty", p95)
	}
	// Every reported figure is one somebody actually waited.
	for _, d := range []time.Duration{p50, p95} {
		if d%time.Second != 0 {
			t.Errorf("%s is not one of the samples; the percentile was interpolated", d)
		}
	}
}

// A phase nobody managed to time is an empty row rather than an absent one, and
// it says so in words.
//
// A run that managed four cycles must not be readable as having done twenty,
// and a table that silently omits what it could not measure is exactly how that
// happens.
func TestTheTimingsTableShowsEveryPhaseAndSaysWhichWereNeverMeasured(t *testing.T) {
	r := newRecord("run_abc")
	r.timings.add(phaseOrder[0], 2*time.Second)

	md := r.Markdown()
	for _, phase := range phaseOrder {
		if !strings.Contains(md, "| "+phase+" |") {
			t.Errorf("the timings table has no row for %q", phase)
		}
	}
	if !strings.Contains(md, "0 (never measured)") {
		t.Error("a phase with no samples does not say it was never measured")
	}
	if !strings.Contains(md, "a percentile without its denominator is not a measurement") {
		t.Error("the table does not say why every figure carries its count")
	}
}

// A run that stopped before the reconciliation has not qualified anything, and
// the evidence says so rather than reading as a run with a blank section.
func TestEvidenceFromARunThatNeverReconciledRefusesToLookLikeAPass(t *testing.T) {
	r := newRecord("run_abc")
	md := r.Markdown()
	if !strings.Contains(md, "**The run never reached the reconciliation.**") {
		t.Error("a run with no closing count does not say so")
	}
	if !strings.Contains(md, "Nothing here is qualified") {
		t.Error("a run with no closing count does not say what that means")
	}
	if !strings.Contains(md, "go run ./test/e2e/proxmox/verify") {
		t.Error("it does not say what to run against the cluster first")
	}
}

// The full evidence: the setup that produced the numbers, the cases, the
// closing count, and anything this run could not remove.
func TestTheEvidenceCarriesTheSetupTheCasesTheCountAndWhatWasLeftBehind(t *testing.T) {
	r := newRecord("run_abc")
	r.setup("Proxmox VE version", "  pve-manager/8.2.4  ")
	r.setup("Node(s)", "")
	r.addCase(CaseRow{
		Number: 1, Case: "scale from zero", Outcome: "pass",
		Timings: "4m 12s", Observed: "one machine, one job", Human: "none",
	})
	r.Reconciliation = &Reconciliation{
		Range: Range{Min: 9000, Max: 9099}, Storage: "local-lvm",
		VMsAtStart: 1, Created: 20, Confirmed: 20, VMsAtEnd: 1,
		Findings: []Finding{{Verdict: Accounted, VMID: 9001, Detail: "was here before the run"}},
	}
	r.Residual = []string{"machine mach_9 (VM 9042 on pve1)"}

	md := r.Markdown()
	for _, want := range []string{
		"evidence from run run_abc",
		"| Proxmox VE version | pve-manager/8.2.4 |",
		// A setup row nobody filled in is a dash, so a missing fact is visible
		// rather than an empty cell somebody reads past.
		"| Node(s) | — |",
		"| 1 | scale from zero | pass | 4m 12s | one machine, one job | none |",
		"| Machines confirmed deleted | 20 |",
		"| Unexplained owned resources | 0 | **must be zero** |",
		"## Left behind by this run",
		"machine mach_9 (VM 9042 on pve1)",
		"accounted | 9001",
	} {
		if !strings.Contains(md, want) {
			t.Errorf("the evidence does not contain %q:\n%s", want, md)
		}
	}
	// It is evidence to be read and copied, never a thing that edits the record
	// it fills in -- a harness that rewrote the procedure could make the
	// procedure describe whatever happened.
	if !strings.Contains(md, "nothing edits it automatically") {
		t.Error("the evidence does not say it does not rewrite the qualification record")
	}
}

// Written as Markdown for a person and JSON for the next run, side by side.
func TestWritingTheEvidenceLeavesBothSomethingToReadAndSomethingToCompare(t *testing.T) {
	r := newRecord("run_abc")
	r.timings.add(phaseOrder[0], 2500*time.Millisecond)
	path := filepath.Join(t.TempDir(), "nested", "proxmox-qualification-run_abc.md")

	if err := r.Write(path); err != nil {
		t.Fatalf("writing the evidence: %v", err)
	}
	if r.FinishedAt.IsZero() {
		t.Error("the evidence does not say when it finished")
	}

	md, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading the Markdown back: %v", err)
	}
	if !strings.Contains(string(md), "run_abc") {
		t.Error("the Markdown does not name the run")
	}

	raw, err := os.ReadFile(strings.TrimSuffix(path, ".md") + ".json")
	if err != nil {
		t.Fatalf("the JSON sibling was not written: %v", err)
	}
	var out struct {
		RunID   string                    `json:"run_id"`
		Timings map[string]map[string]any `json:"timings"`
		Cases   []CaseRow                 `json:"cases"`
	}
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("the JSON sibling does not parse: %v", err)
	}
	if out.RunID != "run_abc" {
		t.Errorf("run id in the JSON = %q", out.RunID)
	}
	// Every phase is present with its count, so two runs can be compared
	// without anybody parsing a table -- and a phase measured in one run and
	// not the other is visible as n=0 rather than as a missing key.
	if len(out.Timings) != len(phaseOrder) {
		t.Errorf("the JSON carries %d phases, want all %d", len(out.Timings), len(phaseOrder))
	}
	first := out.Timings[phaseOrder[0]]
	if first["n"].(float64) != 1 || first["p50_ms"].(float64) != 2500 {
		t.Errorf("the measured phase came back as %v", first)
	}
	if out.Timings[phaseOrder[1]]["n"].(float64) != 0 {
		t.Error("an unmeasured phase is missing its zero count")
	}
}

// Two runs never overwrite one another, and a figure can always be taken back
// to the code that produced it.
func TestEvidenceIsNamedForItsRunAndItsCommitUnlessToldOtherwise(t *testing.T) {
	t.Setenv("ZOOMIES_PROXMOX_RECORD", "")
	got := recordPath("run_abc")
	if !strings.Contains(got, "run_abc") {
		t.Errorf("recordPath = %q, does not name the run", got)
	}
	if !strings.Contains(got, commit()) {
		t.Errorf("recordPath = %q, does not name the commit", got)
	}
	if filepath.Base(filepath.Dir(got)) != "validation" {
		t.Errorf("recordPath = %q, want it beside the qualification record it fills in", got)
	}

	t.Setenv("ZOOMIES_PROXMOX_RECORD", "/tmp/somewhere/else.md")
	if got := recordPath("run_abc"); got != "/tmp/somewhere/else.md" {
		t.Errorf("the override was ignored: %q", got)
	}
}

// Where the evidence came from, when it came from CI -- and nothing at all when
// it did not, rather than a link that goes nowhere.
func TestEvidenceLinksBackToTheRunThatProducedItOnlyWhenThereWasOne(t *testing.T) {
	for _, v := range []string{"GITHUB_SERVER_URL", "GITHUB_REPOSITORY", "GITHUB_RUN_ID"} {
		t.Setenv(v, "")
	}
	if got := runLink(); got != "" {
		t.Errorf("runLink() off CI = %q, want nothing rather than a broken link", got)
	}
	if r := newRecord("run_abc"); r.RunLink != "" {
		t.Errorf("a record made off CI carries a run link: %q", r.RunLink)
	}

	t.Setenv("GITHUB_SERVER_URL", "https://github.com")
	t.Setenv("GITHUB_REPOSITORY", "eyupio/zoomies")
	t.Setenv("GITHUB_RUN_ID", "12345")
	want := "https://github.com/eyupio/zoomies/actions/runs/12345"
	if got := runLink(); got != want {
		t.Errorf("runLink() = %q, want %q", got, want)
	}
	r := newRecord("run_abc")
	if r.RunLink != want {
		t.Errorf("the record did not pick the link up: %q", r.RunLink)
	}
	if !strings.Contains(r.Markdown(), want) {
		t.Error("the evidence does not say which CI run produced it")
	}

	// One of the three missing is not a link: a URL assembled from two of them
	// points at the wrong thing, which is worse than pointing at nothing.
	t.Setenv("GITHUB_RUN_ID", "")
	if got := runLink(); got != "" {
		t.Errorf("runLink() with no run id = %q", got)
	}
}

// Durations are rounded to something a person reads, and a fact nobody filled
// in shows as a dash rather than as an empty cell.
func TestAFigureIsRoundedForReadingAndAMissingOneIsVisible(t *testing.T) {
	if got := round(2*time.Minute + 34*time.Second + 567*time.Millisecond); got != "2m34.6s" {
		t.Errorf("round() = %q", got)
	}
	if got := orDash(""); got != "—" {
		t.Errorf("orDash(%q) = %q, want a dash", "", got)
	}
	if got := orDash("pve1"); got != "pve1" {
		t.Errorf("orDash(%q) = %q", "pve1", got)
	}
}

// Command verify is the closing inventory check, on its own.
//
// It lists every VM in the configured VMID range and every disk on the
// configured storage, accounts for each one against the ledgers the
// qualification harness wrote, and exits non-zero if any owned resource is left
// unexplained.
//
// It exists separately from the harness for two reasons. The first is that the
// harness can die -- killed, timed out, or failing early -- and the question
// "did it leave anything on the cluster" then has to be answerable by something
// that is still alive; the ledgers outlive the run precisely so that this can
// read them. The second is that a qualification is a claim about a cluster, and
// a claim nobody can re-check an hour later is not much of one.
//
// It reads. It never deletes: a resource nobody can account for is a finding for
// a person, and a tool that tidied one away would destroy the evidence that the
// procedure exists to produce.
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/eyupio/zoomies/test/e2e/proxmox"
)

func main() {
	var (
		endpoint = flag.String("url", os.Getenv("ZOOMIES_PROXMOX_URL"), "the cluster, e.g. https://pve.example.com:8006")
		token    = flag.String("token", os.Getenv("ZOOMIES_PROXMOX_TOKEN"), "user@realm!tokenid=secret")
		node     = flag.String("node", os.Getenv("ZOOMIES_PROXMOX_NODE"), "the node whose storage is listed")
		storage  = flag.String("storage", os.Getenv("ZOOMIES_PROXMOX_STORAGE"), "the storage the machines' disks live on")
		vmids    = flag.String("range", os.Getenv("ZOOMIES_PROXMOX_VMID_RANGE"), "the reserved VMID range, e.g. 9000-9099")
		caFile   = flag.String("ca", os.Getenv("ZOOMIES_PROXMOX_CA_PEM_FILE"), "the cluster's own CA certificate")
		insecure = flag.Bool("insecure", os.Getenv("ZOOMIES_PROXMOX_INSECURE") != "", "do not verify the cluster's certificate")
		ledgers  = flag.String("ledgers", proxmox.LedgerDir(), "directory holding the harness's ledgers")
		out      = flag.String("json", "", "also write the reconciliation to this file as JSON")
	)
	flag.Parse()

	if err := run(options{
		endpoint: *endpoint, token: *token, node: *node, storage: *storage,
		vmids: *vmids, caFile: *caFile, insecure: *insecure, ledgers: *ledgers, jsonOut: *out,
	}, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "proxmox-verify: %v\n", err)
		os.Exit(1)
	}
}

type options struct {
	endpoint, token, node, storage, vmids, caFile, ledgers, jsonOut string
	insecure                                                        bool
}

func run(o options, w io.Writer) error {
	missing := []string{}
	for _, f := range []struct{ flag, value string }{
		{"-url", o.endpoint}, {"-token", o.token}, {"-node", o.node},
		{"-storage", o.storage}, {"-range", o.vmids},
	} {
		if strings.TrimSpace(f.value) == "" {
			missing = append(missing, f.flag)
		}
	}
	if len(missing) > 0 {
		return fmt.Errorf("nothing to check: %s missing.\n"+
			"Each also reads its ZOOMIES_PROXMOX_* variable, so the same environment that ran the "+
			"qualification runs this", strings.Join(missing, ", "))
	}
	rng, err := parseRange(o.vmids)
	if err != nil {
		return err
	}

	cluster, err := proxmox.NewCluster(proxmox.ClusterOptions{
		Endpoint: o.endpoint, Token: o.token, CAPEMFile: o.caFile, Insecure: o.insecure,
	})
	if err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	inv, err := cluster.Take(ctx, o.node, o.storage)
	if err != nil {
		return fmt.Errorf("listing the cluster: %w", err)
	}
	records, err := proxmox.ReadLedgers(o.ledgers)
	if err != nil {
		// A ledger that cannot be read is reported and the check goes on: the
		// guests are on the cluster whether or not the file describing them
		// parses, and stopping here would leave them unexamined.
		fmt.Fprintf(w, "warning: %v\n", err)
	}
	if len(records) == 0 {
		fmt.Fprintf(w, "no ledgers in %s: every owned guest in %s will be reported as unexplained, "+
			"because nothing claims it\n", o.ledgers, rng)
	}

	rec := proxmox.Reconcile(inv, records, rng)
	report(rec, w)
	if o.jsonOut != "" {
		raw, err := json.MarshalIndent(rec, "", "  ")
		if err != nil {
			return fmt.Errorf("encoding the reconciliation: %w", err)
		}
		if err := os.WriteFile(o.jsonOut, append(raw, '\n'), 0o644); err != nil {
			return fmt.Errorf("writing the reconciliation: %w", err)
		}
	}
	if !rec.OK() {
		return fmt.Errorf("%d unexplained owned resource(s) and %d disk(s) left on %s; "+
			"this cluster is not clean, and nothing here has deleted anything",
			rec.Unexplained, rec.DisksLeft, o.storage)
	}
	return nil
}

// report prints the reconciliation the way the qualification record wants it
// read: the counts first, then every resource that is not simply accounted for.
func report(rec proxmox.Reconciliation, w io.Writer) {
	fmt.Fprintf(w, "range %s on %s, taken %s\n", rec.Range, rec.Storage, rec.TakenAt.Format(time.RFC3339))
	fmt.Fprintf(w, "  %-34s %d\n", "VMs in the range at the start", rec.VMsAtStart)
	fmt.Fprintf(w, "  %-34s %d\n", "machines created during the runs", rec.Created)
	fmt.Fprintf(w, "  %-34s %d\n", "machines confirmed deleted", rec.Confirmed)
	fmt.Fprintf(w, "  %-34s %d\n", "VMs in the range at the end", rec.VMsAtEnd)
	fmt.Fprintf(w, "  %-34s %d\n", "disks left on the storage", rec.DisksLeft)
	fmt.Fprintf(w, "  %-34s %d\n", "unexplained owned resources", rec.Unexplained)
	for _, f := range rec.Findings {
		if f.Verdict == proxmox.Accounted {
			continue
		}
		fmt.Fprintf(w, "\n%s: VM %d", strings.ToUpper(string(f.Verdict)), f.VMID)
		if f.Node != "" {
			fmt.Fprintf(w, " on %s", f.Node)
		}
		if f.Name != "" {
			fmt.Fprintf(w, " (%s)", f.Name)
		}
		if f.RunID != "" {
			fmt.Fprintf(w, ", run %s", f.RunID)
		}
		fmt.Fprintf(w, "\n  %s\n", f.Detail)
	}
	if rec.OK() {
		fmt.Fprintln(w, "\nevery owned resource in the range is accounted for")
	}
}

// parseRange reads "9000-9099". It is duplicated from the harness rather than
// shared, because this command has to keep working when the harness's build tag
// does not apply -- and because a range read two different ways is a bug worth
// having a test for on both sides.
func parseRange(raw string) (proxmox.Range, error) {
	lo, hi, ok := strings.Cut(strings.TrimSpace(raw), "-")
	if !ok {
		return proxmox.Range{}, fmt.Errorf("%q is not a range; write it as 9000-9099", raw)
	}
	var r proxmox.Range
	if _, err := fmt.Sscanf(strings.TrimSpace(lo), "%d", &r.Min); err != nil {
		return proxmox.Range{}, fmt.Errorf("%q does not begin with a number", raw)
	}
	if _, err := fmt.Sscanf(strings.TrimSpace(hi), "%d", &r.Max); err != nil {
		return proxmox.Range{}, fmt.Errorf("%q does not end with a number", raw)
	}
	if r.Min <= 0 || r.Max < r.Min {
		return proxmox.Range{}, fmt.Errorf("%q is not a usable range of VMIDs", raw)
	}
	return r, nil
}

package main

import (
	"bytes"
	"strings"
	"testing"
	"time"

	"github.com/eyupio/zoomies/test/e2e/proxmox"
)

// The range this command reads must be the range the harness reads.
//
// parseRange is deliberately duplicated -- this command has to keep working
// when the harness's build tag does not apply -- and a duplicated parser is
// only safe while both sides are held to the same cases. A range read one way
// here and another way there would have this command declare a cluster clean
// because it was looking at the wrong hundred identifiers.
func TestARangeIsReadTheSameWayTheHarnessReadsIt(t *testing.T) {
	for _, tc := range []struct {
		raw      string
		want     proxmox.Range
		wantFail bool
	}{
		{raw: "9000-9099", want: proxmox.Range{Min: 9000, Max: 9099}},
		{raw: "  9000 - 9099  ", want: proxmox.Range{Min: 9000, Max: 9099}},
		{raw: "9000-9000", want: proxmox.Range{Min: 9000, Max: 9000}},
		{raw: "", wantFail: true},
		{raw: "9000", wantFail: true},
		{raw: "9000-", wantFail: true},
		{raw: "-9099", wantFail: true},
		{raw: "nine-thousand", wantFail: true},
		{raw: "9099-9000", wantFail: true},
		{raw: "0-9099", wantFail: true},
		{raw: "-1-9099", wantFail: true},
	} {
		got, err := parseRange(tc.raw)
		switch {
		case tc.wantFail && err == nil:
			t.Errorf("parseRange(%q) = %v, want a refusal", tc.raw, got)
		case !tc.wantFail && err != nil:
			t.Errorf("parseRange(%q): %v", tc.raw, err)
		case !tc.wantFail && got != tc.want:
			t.Errorf("parseRange(%q) = %v, want %v", tc.raw, got, tc.want)
		}
	}
}

// A refusal names every missing setting at once, and dials nothing.
//
// Somebody running this is usually running it in a hurry, after a harness died
// and before they know what is on their cluster. Being told about one missing
// flag per attempt is three round trips they do not have time for, and a
// refusal that had already opened a connection would be a refusal that could
// hang instead.
func TestRunSaysEverythingThatIsMissingBeforeItDialsAnything(t *testing.T) {
	var out bytes.Buffer
	err := run(options{ledgers: t.TempDir()}, &out)
	if err == nil {
		t.Fatal("run with nothing configured returned no error")
	}
	for _, flag := range []string{"-url", "-token", "-node", "-storage", "-range"} {
		if !strings.Contains(err.Error(), flag) {
			t.Errorf("the refusal does not name %s: %v", flag, err)
		}
	}
	if !strings.Contains(err.Error(), "ZOOMIES_PROXMOX_") {
		t.Errorf("the refusal does not say the settings also come from the environment: %v", err)
	}
	if out.Len() > 0 {
		t.Errorf("a refusal wrote a report: %q", out.String())
	}
}

// A range that cannot be read is refused before the cluster is dialled, for the
// same reason: the connection is the slow part, and the range is the setting
// that decides what the command is even looking at.
func TestARangeThatCannotBeReadIsRefusedBeforeTheCluster(t *testing.T) {
	var out bytes.Buffer
	err := run(options{
		endpoint: "https://pve.invalid:8006", token: "u@pve!t=s",
		node: "pve1", storage: "local-lvm", vmids: "nine thousand",
		ledgers: t.TempDir(),
	}, &out)
	if err == nil {
		t.Fatal("an unreadable range was accepted")
	}
	if !strings.Contains(err.Error(), "9000-9099") {
		t.Errorf("the refusal does not show the shape it wants: %v", err)
	}
}

// The report leads with the counts and then shows only what needs a person.
//
// An accounted resource printed alongside an unexplained one is how a hundred
// clean lines hide the one that matters, and this report is read at the end of
// a run that took hours.
func TestTheReportShowsTheCountsAndOnlyTheFindingsThatNeedSomebody(t *testing.T) {
	var out bytes.Buffer
	report(proxmox.Reconciliation{
		TakenAt:     time.Date(2026, 9, 14, 3, 4, 5, 0, time.UTC),
		Range:       proxmox.Range{Min: 9000, Max: 9099},
		Storage:     "local-lvm",
		VMsAtStart:  1,
		VMsAtEnd:    2,
		Created:     20,
		Confirmed:   19,
		DisksLeft:   1,
		Unexplained: 1,
		Findings: []proxmox.Finding{
			{Verdict: proxmox.Accounted, VMID: 9001, Detail: "created and confirmed deleted"},
			{
				Verdict: proxmox.LeftBehind, VMID: 9042, Node: "pve1",
				Name: "zoomies-qualify-9042", RunID: "run_abc", Detail: "its ledger names it and it is still here",
			},
		},
	}, &out)

	got := out.String()
	// The counts are matched without their padding: the alignment is a
	// formatting choice, and pinning it here would make widening a label a
	// test failure rather than a formatting change.
	for _, want := range []string{
		"range 9000-9099 on local-lvm",
		"2026-09-14T03:04:05Z",
		"VMs in the range at the end",
		"unexplained owned resources",
		"LEFT_BEHIND: VM 9042 on pve1 (zoomies-qualify-9042), run run_abc",
		"its ledger names it and it is still here",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("the report does not contain %q:\n%s", want, got)
		}
	}
	if strings.Contains(got, "9001") {
		t.Errorf("the report printed an accounted resource:\n%s", got)
	}
	if strings.Contains(got, "every owned resource in the range is accounted for") {
		t.Errorf("a report with an unexplained resource said the cluster was clean:\n%s", got)
	}
}

// And says so plainly when there is nothing to report, because "no output" and
// "nothing found" have to be told apart by somebody deciding whether a
// qualification passed.
func TestACleanReportSaysSoRatherThanSayingNothing(t *testing.T) {
	var out bytes.Buffer
	report(proxmox.Reconciliation{
		Range: proxmox.Range{Min: 9000, Max: 9099}, Storage: "local-lvm",
		Created: 20, Confirmed: 20,
		Findings: []proxmox.Finding{{Verdict: proxmox.Accounted, VMID: 9001, Detail: "gone"}},
	}, &out)
	if !strings.Contains(out.String(), "every owned resource in the range is accounted for") {
		t.Errorf("a clean reconciliation did not say so:\n%s", out.String())
	}
}

//go:build e2e

package e2e

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// Category is how one scenario ended, and it is the only vocabulary a run
// reports in.
//
// The distinction that matters is between NotRun and Blocked. Before this, a
// missing prerequisite was a skip and a skip is exit code zero, so a harness
// that had never once talked to GitHub reported the same green as one that had
// run the whole scenario. Blocked says "this could not start, and that is a
// finding"; NotRun says "nobody asked it to". Only Passed is a pass.
type Category string

const (
	// Passed: the scenario ran and every assertion held.
	Passed Category = "passed"
	// Failed: the scenario ran and something did not hold.
	Failed Category = "failed"
	// NotRun: nothing was attempted, because this run was not asked to.
	NotRun Category = "not_run"
	// Blocked: the scenario was asked for and could not start, because a
	// prerequisite was missing. In required mode this is a failure.
	Blocked Category = "blocked"
)

// Result is the record one scenario writes, whatever happens to it. It is
// written even when the scenario never started, because "we do not know" is
// the answer a gate needs to be able to read.
type Result struct {
	Scenario string   `json:"scenario"`
	Category Category `json:"category"`
	// Reason says why, in a sentence a person can act on. Empty only when the
	// scenario passed.
	Reason string `json:"reason,omitempty"`
	// Commit is the revision under test, so a result file found later can be
	// tied to the code it was produced by.
	Commit string `json:"commit"`
	// RunID is this run's identity, and the suffix on every label and name it
	// creates. It is what makes two concurrent runs safe and what a sweep uses
	// to recognise the leavings of a run that never finished.
	RunID string `json:"run_id"`
	// RunURL is the workflow run on GitHub, when there was one to link to.
	RunURL string `json:"run_url,omitempty"`
	// Marker is the value this run dispatched the workflow with, and asserted
	// on the job that came back. Without it the scenario could pass on a run
	// somebody else triggered.
	Marker     string    `json:"marker,omitempty"`
	StartedAt  time.Time `json:"started_at"`
	FinishedAt time.Time `json:"finished_at"`
	// ResidualCleanup is what this run created and could not remove. Empty is
	// the only good value; anything in it is somebody's real organisation
	// carrying this test's litter.
	ResidualCleanup []string `json:"residual_cleanup,omitempty"`
	// SweptFromEarlierRuns is what the start-up sweep found and cleared before
	// this run began. It is reported rather than silently tidied, because a
	// sweep that keeps finding things is a harness that keeps crashing.
	SweptFromEarlierRuns []string `json:"swept_from_earlier_runs,omitempty"`
}

// write saves the result as JSON, one file per scenario per run.
func (r *Result) write(dir string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("creating the results directory: %w", err)
	}
	raw, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return fmt.Errorf("encoding the result: %w", err)
	}
	name := fmt.Sprintf("%s-%s.json", r.Scenario, r.RunID)
	return os.WriteFile(filepath.Join(dir, name), append(raw, '\n'), 0o644)
}

// commit is the revision under test. A result that cannot name its commit is
// still worth writing, so a failure here becomes the string rather than an
// error: the alternative is losing the whole record to a missing git.
func commit() string {
	out, err := exec.Command("git", "rev-parse", "--short", "HEAD").Output()
	if err != nil {
		return "unknown"
	}
	return strings.TrimSpace(string(out))
}

// Command verify reads the end-to-end harness's result files and exits
// non-zero unless every scenario passed.
//
// It exists so that "the gate is green" is a statement about scenarios rather
// than about `go test`'s exit code. A test binary can exit zero for reasons
// that have nothing to do with the product -- every scenario skipped, no
// scenario compiled in, a filter that matched nothing -- and the whole point
// of the required mode is that those are not passes. Reading the records back
// makes the check say what it means: this many scenarios ran, and this is what
// each of them concluded.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type result struct {
	Scenario        string   `json:"scenario"`
	Category        string   `json:"category"`
	Reason          string   `json:"reason"`
	RunID           string   `json:"run_id"`
	Commit          string   `json:"commit"`
	ResidualCleanup []string `json:"residual_cleanup"`
}

func main() {
	dir := flag.String("dir", "roadmap/validation/e2e", "directory holding the scenario result files")
	flag.Parse()

	if err := verify(*dir, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "e2e: %v\n", err)
		os.Exit(1)
	}
}

// verify reads every result in dir, reports each on w, and returns an error
// unless all of them passed cleanly.
func verify(dir string, w io.Writer) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return fmt.Errorf("no results in %s: %w\n"+
			"the harness writes one file per scenario; if it wrote none, it never ran", dir, err)
	}
	var results []result
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return fmt.Errorf("reading %s: %w", e.Name(), err)
		}
		var r result
		if err := json.Unmarshal(raw, &r); err != nil {
			return fmt.Errorf("%s is not a result file: %w", e.Name(), err)
		}
		results = append(results, r)
	}
	if len(results) == 0 {
		return fmt.Errorf("no scenario results in %s; a run that produced no record is not a pass", dir)
	}
	sort.Slice(results, func(i, j int) bool { return results[i].Scenario < results[j].Scenario })

	var bad int
	for _, r := range results {
		line := fmt.Sprintf("  %-40s %s", r.Scenario, r.Category)
		if r.Reason != "" {
			line += ": " + r.Reason
		}
		// Litter counts against a run even when its assertions held: a
		// scenario that passed and left a runner registered on somebody's
		// organisation has not finished.
		if len(r.ResidualCleanup) > 0 {
			line += fmt.Sprintf("\n    LEFT BEHIND: %s", strings.Join(r.ResidualCleanup, ", "))
			bad++
		} else if r.Category != "passed" {
			bad++
		}
		fmt.Fprintln(w, line)
	}
	if bad > 0 {
		return fmt.Errorf("%d of %d scenarios did not pass cleanly", bad, len(results))
	}
	fmt.Fprintf(w, "all %d scenarios passed\n", len(results))
	return nil
}

package main

import (
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func write(t *testing.T, dir, name, body string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

const passed = `{"scenario":"a","category":"passed","run_id":"r1","commit":"abc"}`

// The whole reason this command exists. `go test` exits zero for reasons that
// have nothing to do with the product -- every scenario skipped, none
// compiled in, a -run filter that matched nothing -- and a gate that reads
// that exit code calls all of them a pass. An empty results directory is the
// shape all of those take on disk.
func TestNoResultsIsNotAPass(t *testing.T) {
	if err := verify(t.TempDir(), io.Discard); err == nil {
		t.Fatal("an empty results directory was accepted; a run that recorded nothing is not a pass")
	}
	if err := verify(filepath.Join(t.TempDir(), "nope"), io.Discard); err == nil {
		t.Fatal("a missing results directory was accepted")
	}
}

// Blocked is the category that exists to stop a missing prerequisite reading
// as success, so it must not read as success here either.
func TestOnlyPassedIsAPass(t *testing.T) {
	for _, category := range []string{"failed", "blocked", "not_run", ""} {
		dir := t.TempDir()
		write(t, dir, "a.json", `{"scenario":"a","category":"`+category+`","reason":"why"}`)
		if err := verify(dir, io.Discard); err == nil {
			t.Errorf("category %q was accepted as a pass", category)
		}
	}
	dir := t.TempDir()
	write(t, dir, "a.json", passed)
	if err := verify(dir, io.Discard); err != nil {
		t.Fatalf("a passed scenario was rejected: %v", err)
	}
}

// A scenario whose assertions all held but which left a runner registered on
// somebody's organisation has not finished. Counting it as a pass is how a
// harness quietly fills an organisation's runner list.
func TestAPassThatLeftLitterIsNotAPass(t *testing.T) {
	dir := t.TempDir()
	write(t, dir, "a.json",
		`{"scenario":"a","category":"passed","residual_cleanup":["pool pool_123"]}`)
	var sb strings.Builder
	err := verify(dir, &sb)
	if err == nil {
		t.Fatal("a passed scenario that left resources behind was accepted")
	}
	if !strings.Contains(sb.String(), "LEFT BEHIND") {
		t.Errorf("the report does not say what was left behind:\n%s", sb.String())
	}
}

// One failure among many must sink the run, and the report has to name which.
func TestOneFailureAmongPassesFailsTheRun(t *testing.T) {
	dir := t.TempDir()
	write(t, dir, "a.json", `{"scenario":"a","category":"passed"}`)
	write(t, dir, "b.json", `{"scenario":"b","category":"failed","reason":"the runner never registered"}`)
	write(t, dir, "c.json", `{"scenario":"c","category":"passed"}`)
	var sb strings.Builder
	if err := verify(dir, &sb); err == nil {
		t.Fatal("a run containing a failure was accepted")
	}
	if !strings.Contains(sb.String(), "the runner never registered") {
		t.Errorf("the report does not name the failure:\n%s", sb.String())
	}
}

// A file that is not a result is a broken harness, not something to read past:
// silently ignoring it would let a malformed write become a smaller run that
// still passes.
func TestAMalformedResultIsAnError(t *testing.T) {
	dir := t.TempDir()
	write(t, dir, "a.json", passed)
	write(t, dir, "b.json", "{not json")
	if err := verify(dir, io.Discard); err == nil {
		t.Fatal("a malformed result file was ignored")
	}
}

// Command fakegithub serves the in-process GitHub fake on a loopback port, so
// that a browser can reach it.
//
// The Playwright suite drives the real binary, and everything below the browser
// already runs against `internal/github`'s fake -- but that fake is an
// in-process test server, so the one client that could never reach it was the
// one an operator uses. Connecting an App, verifying it, and watching a runner
// appear were therefore tested at every layer except the page they happen on.
//
// This is that fake with a port. It is a test-only program: it mints nothing,
// verifies no signature, and answers every App as though the credentials were
// perfect, which is exactly what makes it useless to anything but a test and
// safe to point a browser at.
package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/eyupio/zoomies/internal/github"
)

func main() {
	flag.Parse()

	fake := github.NewFake()
	defer fake.Close()

	// Something for a fleet to see. The names match the demo seed's, so a
	// spec that connects this fake and one that reads the seeded fixture are
	// looking at the same organisation.
	for _, repo := range []string{"acme/widgets", "acme/site", "acme/infra"} {
		fake.AddRepo(repo)
	}

	// One line, parsed by the harness that started it: the URL to hand to an
	// installation, and the two identifiers the connect form asks for.
	//
	// No flush: os.Stdout is unbuffered, and asking a pipe to sync fails with
	// "invalid argument" -- which, guarded, exited this program the instant it
	// had said where it was, so the harness read an address nothing was
	// listening on.
	fmt.Printf("fakegithub url=%s app_id=%d installation_id=%d\n",
		fake.URL(), fake.AppID(), fake.InstallationID())

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	<-ctx.Done()
}

//go:build load

// Package load builds a fleet with a history and measures the reads an
// operator's pages make against it.
//
// It is a separate tier for the same reason the drills are: it takes tens of
// seconds and writes a record rather than an exit code. The fixture is here and
// not in the demo seed on purpose -- the seed is what a person points at a
// running controller to look at a fleet, and ten thousand jobs is not something
// anybody should be able to do to a real database by setting an environment
// variable.
package load

import (
	"context"
	"fmt"
	"math/rand/v2"
	"testing"
	"time"

	"github.com/eyupio/zoomies/internal/store"
)

// The shape of the fixture. Ten hosts is a fleet somebody runs; ten thousand
// jobs is a busy month of history, which is what the retention windows allow
// and therefore what the queries have to stay honest over.
const (
	hosts      = 10
	pools      = 5
	jobs       = 10_000
	runners    = 2_000
	auditRows  = 5_000
	historyFor = 30 * 24 * time.Hour
)

// build writes the fixture through the store's own writer, which is the only
// way it can be written: the store owns the single write connection, and a
// fixture that went around it would be measuring a database no controller
// could have produced.
func build(t *testing.T, s *store.Store) {
	t.Helper()
	ctx := context.Background()
	started := time.Now()
	now := time.Now()
	// Deterministic: a measurement whose fixture changes between runs cannot be
	// compared with the last one, which is the whole point of recording it.
	rng := rand.New(rand.NewPCG(1, 2))

	inst := &store.Installation{
		AppID: 1234, InstallationID: 5678, Target: "acme", TargetType: store.TargetOrg,
		AppSlug: "zoomies-load", PrivateKeyEnc: []byte("sealed"), WebhookSecretEnc: []byte("sealed"),
	}
	if err := s.CreateInstallation(ctx, inst); err != nil {
		t.Fatalf("CreateInstallation: %v", err)
	}

	hostIDs := make([]string, 0, hosts)
	for i := range hosts {
		h := &store.Host{
			Name: fmt.Sprintf("builder-%02d", i), Address: "127.0.0.1", Capacity: 8,
			Backends: store.StringSlice{string(store.BackendDocker)}, LastHeartbeat: now,
		}
		if err := s.CreateHost(ctx, h); err != nil {
			t.Fatalf("CreateHost: %v", err)
		}
		hostIDs = append(hostIDs, h.ID)
	}

	poolIDs := make([]string, 0, pools)
	for i := range pools {
		p := &store.Pool{
			Name: fmt.Sprintf("linux-x64-%02d", i), InstallationID: inst.ID,
			Labels:  []string{"self-hosted", "linux", "x64", fmt.Sprintf("pool-%02d", i)},
			Backend: store.BackendDocker, Image: "ghcr.io/eyupio/zoomies-runner:test",
			DockerMode: store.DockerNone,
			MinRunners: 0, MaxRunners: 20, Enabled: true,
		}
		if err := s.CreatePool(ctx, p); err != nil {
			t.Fatalf("CreatePool: %v", err)
		}
		poolIDs = append(poolIDs, p.ID)
	}

	runnerIDs := make([]string, 0, runners)
	for i := range runners {
		r := &store.Runner{
			PoolID: poolIDs[i%len(poolIDs)], HostID: hostIDs[i%len(hostIDs)],
			Name:  fmt.Sprintf("zoomies-load-%05d", i),
			State: store.RunnerRemoved,
		}
		if i < 40 {
			// A live tail, so the lists a page shows first are not all history.
			r.State = store.RunnerIdle
		}
		if err := s.CreateRunner(ctx, r); err != nil {
			t.Fatalf("CreateRunner: %v", err)
		}
		runnerIDs = append(runnerIDs, r.ID)
	}

	conclusions := []string{"success", "success", "success", "failure", "cancelled"}
	for i := range jobs {
		age := time.Duration(rng.Int64N(int64(historyFor)))
		queued := now.Add(-age)
		j := &store.Job{
			GitHubJobID:    int64(100_000 + i),
			GitHubRunID:    int64(900_000 + i/10),
			Repo:           fmt.Sprintf("acme/service-%02d", i%20),
			Workflow:       "CI",
			JobName:        fmt.Sprintf("build-%03d", i%50),
			Labels:         store.NormalizeLabels([]string{"self-hosted", "linux", "x64"}),
			State:          store.JobCompleted,
			Conclusion:     conclusions[i%len(conclusions)],
			InstallationID: inst.ID,
			PoolID:         poolIDs[i%len(poolIDs)],
			RunnerID:       runnerIDs[i%len(runnerIDs)],
			RunnerName:     fmt.Sprintf("zoomies-load-%05d", i%runners),
			QueuedAt:       queued,
			Matched:        true,
		}
		started := queued.Add(time.Duration(rng.Int64N(int64(2 * time.Minute))))
		completed := started.Add(time.Duration(rng.Int64N(int64(20 * time.Minute))))
		j.StartedAt, j.CompletedAt = &started, &completed
		if i%97 == 0 {
			// A queue with something in it: the Overview and the scheduler both
			// read this, and a fixture with none would measure the easy case.
			j.State, j.Conclusion, j.StartedAt, j.CompletedAt = store.JobQueued, "", nil, nil
		}
		if _, err := s.UpsertJob(ctx, j); err != nil {
			t.Fatalf("UpsertJob %d: %v", i, err)
		}
	}

	// The Overview's sparkline and its feed, which are read on every page load
	// and were empty in the first version of this fixture -- so the two fastest
	// figures in the record were measuring nothing.
	for i := range 24 * 60 {
		if err := s.RecordSample(ctx, store.FleetSample{
			At: now.Add(-time.Duration(i) * time.Minute), QueuedJobs: i % 7, RunningJobs: i % 11,
			IdleRunners: 3, BusyRunners: i % 5, TotalRunners: 8,
		}); err != nil {
			t.Fatalf("RecordSample: %v", err)
		}
	}
	for i := range 500 {
		if err := s.AppendScalingEvent(ctx, &store.ScalingEvent{
			PoolID: poolIDs[i%len(poolIDs)], PoolName: fmt.Sprintf("linux-x64-%02d", i%len(poolIDs)),
			From: i % 4, To: (i % 4) + 1,
			Reason:    fmt.Sprintf("%d jobs queued > 30s", 1+i%3),
			CreatedAt: now.Add(-time.Duration(i) * time.Minute),
		}); err != nil {
			t.Fatalf("AppendScalingEvent: %v", err)
		}
	}

	actions := []string{"pool.update", "runner.drain", "host.cordon", "token.create", "settings.update"}
	for i := range auditRows {
		if err := s.AppendAudit(ctx, &store.AuditEvent{
			ActorID: "usr_load", ActorName: "loadtest", ActorKind: "user",
			Action:     actions[i%len(actions)],
			TargetKind: "pool", TargetID: poolIDs[i%len(poolIDs)],
			CreatedAt: now.Add(-time.Duration(rng.Int64N(int64(historyFor)))),
		}); err != nil {
			t.Fatalf("AppendAudit: %v", err)
		}
	}

	t.Logf("fixture: %d hosts, %d pools, %d runners, %d jobs, %d audit rows in %s",
		hosts, pools, runners, jobs, auditRows, time.Since(started).Round(time.Millisecond))
}

