import { defineConfig, devices } from '@playwright/test';
import { SETUP_TOKEN_FILE } from './tests/support/fixtures';

/**
 * Playwright drives the real binary, not a mock server: the tests boot
 * `zoomies controller` against a temporary SQLite database with auth disabled
 * on loopback, so what they exercise is the same code an operator runs.
 */
const PORT = 8099;
/**
 * The first-run project gets its own controller, because it needs the opposite
 * of what the others do: authentication on, and an empty fleet. `session.boot()`
 * short-circuits to `ready` when auth is disabled, so bootstrap and sign-in are
 * literally unreachable under the shared server.
 */
const FIRST_RUN_PORT = 8098;
/**
 * The diagnostics project gets its own controller too, and for the same kind
 * of reason: the shared fixture is deliberately a fleet with nothing wrong
 * with it, so the pages that explain a fleet in trouble have nothing to show
 * there. This one seeds the same fleet and then breaks three things in it.
 */
const STUCK_PORT = 8097;
/**
 * The connect project gets its own controller and its own GitHub.
 *
 * The suite's fake GitHub is in-process, so a browser cannot reach it: the
 * connect and verify pages were tested at every layer except the one they live
 * on. This fixture runs the same fake as a program on a loopback port, beside a
 * controller with nothing seeded, and leaves its address in a file the spec
 * reads.
 */
const CONNECT_PORT = 8096;
/**
 * The status project gets its own controller: authentication on, the
 * diagnostics fleet seeded, and status.mode public. The status page is for a
 * reader with no account, and under the shared server -- authentication off --
 * every request is an administrator, so "signed out" could not be tested.
 */
const STATUS_PORT = 8095;
const FAKE_GITHUB_FILE = 'test-results/fakegithub.json';

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  workers: 1,
  reporter: process.env.CI ? [['html'], ['github']] : 'list',
  timeout: 30_000,
  expect: { timeout: 7_000 },
  use: {
    baseURL: `http://127.0.0.1:${PORT}`,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
      testIgnore:
        /(first-run|two-step|mcp-oauth|diagnostics|connect|ai-context|status-page)\.spec\.ts/,
    },
    // Read-only monitoring on a phone is a stated requirement, so it is tested.
    {
      name: 'mobile',
      use: { ...devices['Pixel 7'] },
      testIgnore:
        /(first-run|two-step|mcp-oauth|diagnostics|connect|ai-context|status-page)\.spec\.ts/,
    },
    {
      name: 'first-run',
      // Two-step verification and the MCP consent screen need authentication
      // on and a real account, so they ride on this controller, after the
      // spec that creates the account.
      testMatch: /(first-run|two-step|mcp-oauth)\.spec\.ts/,
      use: { ...devices['Desktop Chrome'], baseURL: `http://127.0.0.1:${FIRST_RUN_PORT}` },
    },
    {
      name: 'diagnostics',
      testMatch: /diagnostics\.spec\.ts/,
      use: { ...devices['Desktop Chrome'], baseURL: `http://127.0.0.1:${STUCK_PORT}` },
    },
    {
      name: 'status',
      testMatch: /status-page\.spec\.ts/,
      use: { ...devices['Desktop Chrome'], baseURL: `http://127.0.0.1:${STATUS_PORT}` },
    },
    {
      name: 'connect',
      testMatch: /(connect|ai-context)\.spec\.ts/,
      use: { ...devices['Desktop Chrome'], baseURL: `http://127.0.0.1:${CONNECT_PORT}` },
    },
  ],
  webServer: [
    {
      command: `node tests/support/serve.mjs ${PORT}`,
      url: `http://127.0.0.1:${PORT}/healthz`,
      reuseExistingServer: !process.env.CI,
      timeout: 60_000,
      stdout: 'pipe',
      stderr: 'pipe',
    },
    {
      command: `node tests/support/serve-firstrun.mjs ${FIRST_RUN_PORT} ${SETUP_TOKEN_FILE}`,
      url: `http://127.0.0.1:${FIRST_RUN_PORT}/healthz`,
      // Never reused: the bootstrap route closes for ever once an account
      // exists, so this suite needs a database nobody has touched.
      reuseExistingServer: false,
      timeout: 60_000,
      stdout: 'pipe',
      stderr: 'pipe',
    },
    {
      command: `node tests/support/serve-connect.mjs ${CONNECT_PORT} ${FAKE_GITHUB_FILE}`,
      url: `http://127.0.0.1:${CONNECT_PORT}/healthz`,
      // Never reused: the spec connects an installation, and a database that
      // already has one answers the question the spec is asking.
      reuseExistingServer: false,
      timeout: 60_000,
      stdout: 'pipe',
      stderr: 'pipe',
    },
    {
      command: `node tests/support/serve-status.mjs ${STATUS_PORT}`,
      url: `http://127.0.0.1:${STATUS_PORT}/healthz`,
      reuseExistingServer: !process.env.CI,
      timeout: 60_000,
      stdout: 'pipe',
      stderr: 'pipe',
    },
    {
      command: `node tests/support/serve-stuck.mjs ${STUCK_PORT}`,
      url: `http://127.0.0.1:${STUCK_PORT}/healthz`,
      reuseExistingServer: !process.env.CI,
      timeout: 60_000,
      stdout: 'pipe',
      stderr: 'pipe',
    },
  ],
});

/*
 * Zoomies stylesheet entry point.
 *
 * Order matters: tokens first so Tailwind's @theme can reference them, then
 * Tailwind, then the small set of global rules that are genuinely global.
 */

@import './lib/styles/tokens.css';

/* Shared controls added to the handful of specialised tables that are not
   DataGrids. Component-scoped styles cannot reach action-created elements. */
.managed-table-frame {
  overflow-x: auto;
}
table[data-managed-table='true'] {
  max-width: none;
}
table[data-managed-table='true'] .managed-table-heading {
  position: relative;
  overflow: visible;
}
.managed-table-move,
.managed-table-resizer {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--z-text-muted);
}
.managed-table-move {
  width: var(--z-space-5);
  margin-left: calc(-1 * var(--z-space-2));
  margin-right: var(--z-space-1);
  border-radius: var(--z-radius-sm);
  cursor: grab;
  letter-spacing: -0.18rem;
  /* The drag is the gesture, so the browser must not read it as a scroll of
     the frame the table sits in and take the pointer away mid-column. */
  touch-action: none;
}
.managed-table-move:hover {
  background: var(--z-surface-hover);
  color: var(--z-text);
}
.managed-table-resizer {
  position: absolute;
  top: 0;
  right: calc(-1 * var(--z-space-1));
  width: var(--z-space-3);
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}
/*
  The handle straddles the boundary it drags, so half of the last column's
  falls outside the table -- and counts towards its scrollWidth, which made
  every managed table report itself four pixels wider than its frame. There is
  no boundary out there to straddle, so that one sits level with the edge.
*/
tr > *:last-child .managed-table-resizer {
  right: 0;
}
.managed-table-resizer::after {
  content: '';
  position: absolute;
  top: 25%;
  bottom: 25%;
  left: 50%;
  width: var(--z-border-width);
  background: var(--z-border-strong);
  opacity: 0;
}
.managed-table-heading:hover .managed-table-resizer::after,
.managed-table-resizer:focus-visible::after {
  opacity: 1;
}
/* The column in the air, and the one it would land on. The native drag
   protocol drew both for us; the gesture that replaced it draws its own. */
.managed-table-heading.managed-table-dragging {
  opacity: 0.55;
}
.managed-table-heading.managed-table-drop-target {
  box-shadow: inset var(--z-focus-width) 0 var(--z-focus-colour);
}
/* Read by a finger: the heading takes the touch height the rest of the product
   uses, both controls grow into it, and the resize handle stops waiting for a
   hover that will never come. See the same block in DataGrid.svelte. */
@media (pointer: coarse) {
  table[data-managed-table='true'] .managed-table-heading {
    height: var(--z-control-touch);
  }
  .managed-table-move {
    width: var(--z-space-6);
    height: var(--z-control-touch);
  }
  .managed-table-resizer {
    right: calc(-1 * var(--z-space-3));
    width: var(--z-space-6);
  }
  .managed-table-resizer::after {
    opacity: 1;
  }
}
@media (max-width: 768px) {
  table[data-managed-table='true'] {
    width: 100% !important;
  }
  .managed-table-move,
  .managed-table-resizer {
    display: none;
  }
}
@import 'tailwindcss';

/* Four Latin faces, declared by hand. See the file for why. */
@import './lib/styles/fonts.css';

/*
 * Map the tokens onto Tailwind's theme so `bg-surface`, `text-muted`,
 * `rounded-md` and friends resolve to the same custom properties that
 * hand-written CSS uses. There is exactly one source of truth.
 */
@theme inline {
  --color-bg: var(--z-bg);
  --color-surface: var(--z-surface);
  --color-raised: var(--z-surface-raised);
  --color-sunken: var(--z-surface-sunken);
  --color-hover: var(--z-surface-hover);
  --color-border: var(--z-border);
  --color-border-strong: var(--z-border-strong);
  --color-fg: var(--z-text);
  --color-muted: var(--z-text-muted);
  --color-subtle: var(--z-text-subtle);
  --color-inverse: var(--z-text-inverse);

  --color-accent: var(--z-accent);
  --color-accent-hover: var(--z-accent-hover);
  --color-accent-subtle: var(--z-accent-subtle);
  --color-accent-border: var(--z-accent-border);
  --color-accent-contrast: var(--z-accent-contrast);

  --color-idle: var(--z-idle);
  --color-idle-subtle: var(--z-idle-subtle);
  --color-idle-border: var(--z-idle-border);
  --color-busy: var(--z-busy);
  --color-busy-subtle: var(--z-busy-subtle);
  --color-busy-border: var(--z-busy-border);
  --color-pending: var(--z-pending);
  --color-pending-subtle: var(--z-pending-subtle);
  --color-pending-border: var(--z-pending-border);
  --color-draining: var(--z-draining);
  --color-draining-subtle: var(--z-draining-subtle);
  --color-draining-border: var(--z-draining-border);
  --color-danger: var(--z-danger);
  --color-danger-hover: var(--z-danger-hover);
  --color-danger-subtle: var(--z-danger-subtle);
  --color-danger-border: var(--z-danger-border);
  --color-danger-contrast: var(--z-danger-contrast);
  --color-neutral: var(--z-neutral);
  --color-neutral-subtle: var(--z-neutral-subtle);
  --color-neutral-border: var(--z-neutral-border);

  /* The brand constants, for the few places that need the identity rather
     than a semantic role: the chip behind the monochrome mark, and the
     illustrative fills that may use Runner Blue at full strength. */
  --color-brand-black: var(--z-brand-black);
  --color-brand-blue: var(--z-brand-runner-blue);
  --color-brand-cyan: var(--z-brand-fast-cyan);
  --color-mark-chip: var(--z-mark-chip);

  --font-sans: var(--z-font-sans);
  --font-mono: var(--z-font-mono);

  --text-2xs: var(--z-text-2xs);
  --text-2xs--line-height: var(--z-leading-2xs);
  --text-xs: var(--z-text-xs);
  --text-xs--line-height: var(--z-leading-xs);
  --text-sm: var(--z-text-sm);
  --text-sm--line-height: var(--z-leading-sm);
  --text-base: var(--z-text-base);
  --text-base--line-height: var(--z-leading-base);
  --text-lg: var(--z-text-lg);
  --text-lg--line-height: var(--z-leading-lg);
  --text-xl: var(--z-text-xl);
  --text-xl--line-height: var(--z-leading-xl);
  --text-2xl: var(--z-text-2xl);
  --text-2xl--line-height: var(--z-leading-2xl);
  --text-3xl: var(--z-text-3xl);
  --text-3xl--line-height: var(--z-leading-3xl);

  --radius-sm: var(--z-radius-sm);
  --radius-md: var(--z-radius-md);
  --radius-lg: var(--z-radius-lg);

  --shadow-sm: var(--z-shadow-sm);
  --shadow-md: var(--z-shadow-md);
  --shadow-lg: var(--z-shadow-lg);

  --font-weight-normal: var(--z-weight-normal);
  --font-weight-medium: var(--z-weight-medium);
  --font-weight-semibold: var(--z-weight-semibold);
  --font-weight-bold: var(--z-weight-bold);

  --tracking-tight: var(--z-tracking-tight);
  --tracking-wide: var(--z-tracking-wide);
  --tracking-wider: var(--z-tracking-wider);

  --ease-out: var(--z-ease);

  /* Tailwind derives its whole spacing scale from this one step, so `p-3` is
     `--z-space-3` by arithmetic rather than by a mapping that could drift. */
  --spacing: 0.25rem;
}

/* ------------------------------------------------------------------------ */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  /* The theme paints the whole viewport, including overscroll. */
  background: var(--z-bg);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--z-bg);
  color: var(--z-text);
  font-family: var(--z-font-sans);
  font-size: var(--z-text-sm);
  line-height: var(--z-leading-sm);
  font-weight: var(--z-weight-normal);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  font-feature-settings:
    'cv05' 1,
    'ss03' 1; /* single-storey g, rounded quotes */
}

/* Numbers in tables must line up. */
table,
.tabular {
  font-variant-numeric: tabular-nums;
}

code,
kbd,
samp,
pre,
.mono {
  font-family: var(--z-font-mono);
  font-size: 0.95em;
}

/*
 * A visible focus ring, everywhere, always. :focus-visible means a mouse click
 * does not draw one but a keyboard tab does -- which is the behaviour that makes
 * a permanent focus ring acceptable to designers and keyboard users at once.
 */
:focus-visible {
  outline: var(--z-focus-width) solid var(--z-focus-colour);
  outline-offset: var(--z-focus-offset);
  border-radius: var(--z-radius-sm);
}
:focus:not(:focus-visible) {
  outline: none;
}

::selection {
  background: var(--z-accent-subtle);
  color: var(--z-text);
}

/*
 * Scrollbars that belong to the theme rather than to the browser.
 *
 * Only where there is a pointer to aim with. On a touchscreen the thumb is not
 * a control -- a finger scrolls the content, never the bar -- and the browser's
 * own overlay scrollbar, which takes no space and fades when idle, is the right
 * thing there. Styling it would turn it into a permanent column down the edge
 * of a phone.
 *
 * Two mechanisms, deliberately kept apart. Chromium and WebKit draw from the
 * `::-webkit-scrollbar` pseudo-elements, which is the only way to get a thumb
 * that is inset in its track and rounded. The standard `scrollbar-width` and
 * `scrollbar-color` properties must not be set alongside them: a browser that
 * knows both ignores the pseudo-elements the moment the standard properties are
 * set, and draws its own thin bar instead -- which, in a hairline border grey,
 * is what an operator used to get here. So the standard properties are set only
 * where the pseudo-elements are unknown, which today means Firefox.
 */
@media (pointer: fine) {
  @supports not selector(::-webkit-scrollbar) {
    * {
      scrollbar-width: auto;
      scrollbar-color: var(--z-scrollbar-thumb) var(--z-scrollbar-track);
    }
  }
  *::-webkit-scrollbar {
    width: var(--z-scrollbar-size);
    height: var(--z-scrollbar-size);
  }
  *::-webkit-scrollbar-track,
  *::-webkit-scrollbar-corner {
    background: var(--z-scrollbar-track);
  }
  /*
   * The transparent border is the inset: the whole column is the hit target,
   * and the visible thumb is the column less the inset on each side. It darkens
   * under the pointer and again while held, like any other control here.
   */
  *::-webkit-scrollbar-thumb {
    background-color: var(--z-scrollbar-thumb);
    border: var(--z-scrollbar-inset) solid transparent;
    border-radius: var(--z-radius-full);
    background-clip: content-box;
  }
  *::-webkit-scrollbar-thumb:hover {
    background-color: var(--z-scrollbar-thumb-hover);
  }
  *::-webkit-scrollbar-thumb:active {
    background-color: var(--z-scrollbar-thumb-active);
  }
}

/* Visually hidden but available to assistive technology. */
/*
 * Visible to a screen reader, invisible to everyone else.
 *
 * The one-pixel box and the negative margin that cancels it are the standard
 * recipe, and the reason it is not `display: none` or `visibility: hidden` is
 * that both of those take the text out of the accessibility tree as well.
 */
.sr-only {
  position: absolute;
  width: var(--z-nudge-1);
  height: var(--z-nudge-1);
  padding: 0;
  margin: calc(-1 * var(--z-nudge-1));
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* The skip link is the first focusable thing on the page. */
.skip-link {
  position: absolute;
  left: var(--z-space-4);
  top: -100px;
  z-index: var(--z-layer-toast);
  padding: var(--z-space-2) var(--z-space-4);
  background: var(--z-accent);
  color: var(--z-accent-contrast);
  border-radius: var(--z-radius-md);
  transition: top var(--z-motion-fast) var(--z-ease);
}
.skip-link:focus {
  top: var(--z-space-4);
}

/**
 * The two column gestures -- pick a heading up and move it, and pull a column's
 * edge -- driven by pointer events, so a finger can do both.
 *
 * Reordering used to be the HTML5 drag-and-drop protocol, which a touchscreen
 * does not speak: a browser raises `dragstart` for a mouse and a stylus, and
 * from a finger only after a long press on Android and never on iOS. So a
 * column order was a preference an operator could set with a mouse and not with
 * a finger, on the one phone layout -- Rows -- that has columns to arrange at
 * all. Pointer events are one code path for mouse, pen and touch alike, which
 * is also one behaviour to keep working rather than two.
 *
 * Resizing was already pointer-driven but listened on the document and never
 * captured the pointer, which holds up for a mouse and not for a finger: a
 * touch that the browser takes over mid-drag (a back-swipe, a second finger, a
 * notification) raises `pointercancel` and no `pointerup`, leaving the listener
 * attached and the column following a finger that had long since let go.
 */

/**
 * How far a pointer travels before a press on the grip becomes a drag.
 *
 * A finger never presses a 24px target without moving a pixel or two, so
 * without a threshold every tap on the grip would reorder the columns.
 */
const DRAG_THRESHOLD_PX = 4;

/**
 * The column under a point, or the empty string if the point is not over one.
 *
 * `elementsFromPoint` rather than `elementFromPoint`: the heading carries the
 * grip and the resize handle on top of it, and the one nearest the pointer is
 * whichever control it happens to be over. Searching down the stack finds the
 * heading under them either way.
 */
function columnAt(root: HTMLElement, x: number, y: number): string {
  for (const element of document.elementsFromPoint(x, y)) {
    if (!root.contains(element)) continue;
    const cell = element.closest<HTMLElement>('[data-table-column]');
    const id = cell?.dataset.tableColumn;
    if (id) return id;
  }
  return '';
}

/**
 * Hold the pointer for the rest of the gesture, so the drag survives the finger
 * leaving the control it started on.
 *
 * Tolerated when it fails: a synthetic pointer dispatched by a test has no
 * capture to take, and a gesture that works without capture is better than a
 * gesture that throws before it begins.
 */
function capture(node: HTMLElement, pointerId: number): void {
  try {
    node.setPointerCapture(pointerId);
  } catch {
    /* as above */
  }
}

export interface ColumnDragHandlers {
  /** The column the pointer is over now, or '' for none. Called as it moves. */
  over(id: string): void;
  /** Where the pointer was lifted, after a drag that really began. */
  drop(id: string): void;
  /**
   * Nothing happened: a press that never travelled far enough to be a drag, or
   * one the browser took the pointer back from. Told apart from a drop so that
   * an interrupted drag abandons the column rather than posting it wherever the
   * finger last happened to be.
   */
  cancel(): void;
}

/**
 * Drag a column by its grip, reporting what the pointer is over as it moves.
 *
 * `root` bounds the hit test to this table: two grids on one page must not be
 * able to drop a column into each other.
 */
export function startColumnDrag(
  event: PointerEvent,
  root: HTMLElement,
  handlers: ColumnDragHandlers,
): void {
  // A secondary touch is a second finger on the screen, not a second drag.
  if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
  const grip = event.currentTarget as HTMLElement;
  event.preventDefault();
  event.stopPropagation();
  // preventDefault suppresses the focus the press would have moved, and the
  // grip is also the keyboard control for the same job -- so it takes focus
  // explicitly, and the arrow keys carry on from wherever the drag ended.
  grip.focus();
  capture(grip, event.pointerId);

  const startX = event.clientX;
  const startY = event.clientY;
  // One abort for the three listeners, so there is one way for the gesture to
  // end and no way to leave two of them attached.
  const gesture = new AbortController();
  const { signal } = gesture;
  let dragging = false;

  const finish = (target: string | null): void => {
    gesture.abort();
    if (target === null) handlers.cancel();
    else handlers.drop(target);
  };

  grip.addEventListener(
    'pointermove',
    (move: PointerEvent) => {
      if (move.pointerId !== event.pointerId) return;
      if (
        !dragging &&
        Math.abs(move.clientX - startX) < DRAG_THRESHOLD_PX &&
        Math.abs(move.clientY - startY) < DRAG_THRESHOLD_PX
      )
        return;
      dragging = true;
      move.preventDefault();
      handlers.over(columnAt(root, move.clientX, move.clientY));
    },
    { signal },
  );
  grip.addEventListener(
    'pointerup',
    (up: PointerEvent) => {
      if (up.pointerId !== event.pointerId) return;
      // A press that never became a drag is a press: reporting a target the
      // operator never aimed at is how a stray tap rearranges a table.
      finish(dragging ? columnAt(root, up.clientX, up.clientY) : null);
    },
    { signal },
  );
  grip.addEventListener(
    'pointercancel',
    (cancel: PointerEvent) => {
      if (cancel.pointerId === event.pointerId) finish(null);
    },
    { signal },
  );
}

export interface ColumnResizeHandlers {
  /** The width the pointer is asking for, as it moves. */
  move(width: number): void;
  /** The gesture is over; the last width offered is the one to keep. */
  done(): void;
}

/**
 * Pull a column's trailing edge, from `startWidth` as the pointer went down.
 *
 * A cancelled gesture keeps the width it had reached rather than snapping back:
 * the operator was dragging towards a width, and an interruption they did not
 * ask for is a poor reason to throw away the part of it they had.
 */
export function startColumnResize(
  event: PointerEvent,
  startWidth: number,
  handlers: ColumnResizeHandlers,
): void {
  if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
  const handle = event.currentTarget as HTMLElement;
  event.preventDefault();
  event.stopPropagation();
  handle.focus();
  capture(handle, event.pointerId);

  const startX = event.clientX;
  const gesture = new AbortController();
  const { signal } = gesture;
  const finish = (ended: PointerEvent): void => {
    if (ended.pointerId !== event.pointerId) return;
    gesture.abort();
    handlers.done();
  };

  handle.addEventListener(
    'pointermove',
    (move: PointerEvent) => {
      if (move.pointerId !== event.pointerId) return;
      move.preventDefault();
      handlers.move(startWidth + move.clientX - startX);
    },
    { signal },
  );
  handle.addEventListener('pointerup', finish, { signal });
  handle.addEventListener('pointercancel', finish, { signal });
}

import { prefs } from '../state/prefs.svelte';
import { startColumnDrag, startColumnResize } from './columnGesture';

export interface TableLayoutOptions {
  /** Stable preference key, shared with no other table. */
  id: string;
  /** Stable column ids in the order the component renders them. */
  columns: readonly string[];
}

const MIN_WIDTH = 56;
const MAX_WIDTH = 640;

/**
 * Add the same resize and reorder behaviour to the few hand-written tables
 * that are too small or specialised to be DataGrids. The action owns only a
 * colgroup and the two controls it adds to each heading; the component keeps
 * owning every row and cell.
 */
export function tableLayout(node: HTMLTableElement, initial: TableLayoutOptions) {
  let options = initial;
  let applying = false;
  const widths: Record<string, number> = {};
  const defaults: Record<string, number> = {};
  const disposers: Array<() => void> = [];

  node.dataset.managedTable = 'true';
  const frame = node.parentElement;
  frame?.classList.add('managed-table-frame');

  let colgroup = node.querySelector<HTMLTableColElement>('colgroup[data-table-layout]');
  if (!colgroup) {
    colgroup = document.createElement('colgroup');
    colgroup.dataset.tableLayout = 'true';
    node.insertBefore(colgroup, node.firstChild);
  }

  function cells(row: HTMLTableRowElement): HTMLElement[] {
    return Array.from(row.children).filter(
      (child): child is HTMLElement => child instanceof HTMLTableCellElement,
    );
  }

  function tagSourceCells(): void {
    for (const row of node.querySelectorAll<HTMLTableRowElement>('tr')) {
      const rowCells = cells(row);
      for (let index = 0; index < rowCells.length; index += 1) {
        if (!rowCells[index]!.dataset.tableColumn && options.columns[index]) {
          rowCells[index]!.dataset.tableColumn = options.columns[index]!;
        }
      }
    }
  }

  function measure(columnID: string): number {
    const candidates = Array.from(
      node.querySelectorAll<HTMLElement>(`[data-table-column="${CSS.escape(columnID)}"]`),
    ).slice(0, 21);
    const content = candidates.reduce((largest, cell) => Math.max(largest, cell.scrollWidth), 0);
    return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, content + 20));
  }

  /**
   * How the table is sized, and in what units its columns are written.
   *
   * `share` is the case a table gets before anybody has touched it: the
   * measured columns want more room than the frame has, so the table takes the
   * frame and the columns take it in the proportions they asked for. Writing
   * the table `100%` and leaving the columns in pixels is not enough -- a
   * colgroup in absolute units wins, and the table went on being drawn at the
   * measured total inside a frame two hundred pixels narrower, which is a
   * sideways scroll on a table nobody had resized.
   *
   * `measure` is every other case: on a phone, and once an operator has
   * resized a column, the explicit measure wins and the frame scrolls if it
   * must. Shrinking every other column to keep the table inside the window
   * would make the resize handle lie about what it did.
   */
  function sizing(): { mode: 'share' | 'measure'; total: number } {
    const total = prefs
      .columnOrder(options.id, options.columns)
      .reduce((sum, id) => sum + (widths[id] ?? defaults[id] ?? MIN_WIDTH), 0);
    const custom = options.columns.some((id) => widths[id] !== undefined);
    const phone = matchMedia('(max-width: 768px)').matches;
    const share = !phone && !custom && frame !== null && total >= frame.clientWidth && total > 0;
    return { mode: share ? 'share' : 'measure', total };
  }

  function setTableWidth(): void {
    if (matchMedia('(max-width: 768px)').matches) {
      node.style.removeProperty('width');
      return;
    }
    const { mode, total } = sizing();
    node.style.width = mode === 'share' ? '100%' : `${Math.ceil(total)}px`;
  }

  function apply(): void {
    if (applying) return;
    applying = true;
    tagSourceCells();
    const order = prefs.columnOrder(options.id, options.columns);
    for (const id of order) {
      const saved = prefs.columnWidth(options.id, id);
      if (saved !== undefined) widths[id] = saved;
      if (defaults[id] === undefined) defaults[id] = measure(id);
    }
    for (const row of node.querySelectorAll<HTMLTableRowElement>('tr')) {
      const byID = new Map(cells(row).map((cell) => [cell.dataset.tableColumn ?? '', cell]));
      const desired = order.flatMap((id) => {
        const cell = byID.get(id);
        return cell ? [cell] : [];
      });
      const present = cells(row);
      if (desired.some((cell, index) => present[index] !== cell)) {
        for (const cell of desired) row.appendChild(cell);
      }
    }
    // Decided before the columns are written, because it decides their units.
    const layout = sizing();
    const existing = new Map(
      Array.from(colgroup!.children).map((col) => [(col as HTMLElement).dataset.tableColumn, col]),
    );
    const desiredCols: HTMLTableColElement[] = [];
    for (const id of order) {
      let col = existing.get(id) as HTMLTableColElement | undefined;
      if (!col) {
        col = document.createElement('col');
        col.dataset.tableColumn = id;
      }
      const want = widths[id] ?? defaults[id] ?? MIN_WIDTH;
      col.style.width =
        layout.mode === 'share' ? `${((want / layout.total) * 100).toFixed(4)}%` : `${want}px`;
      desiredCols.push(col);
    }
    if (desiredCols.some((col, index) => colgroup!.children[index] !== col)) {
      for (const col of desiredCols) colgroup!.appendChild(col);
    }
    setTableWidth();
    applying = false;
  }

  function move(source: string, target: string): void {
    if (!source || source === target) return;
    const order = prefs.columnOrder(options.id, options.columns);
    const from = order.indexOf(source);
    const to = order.indexOf(target);
    if (from < 0 || to < 0) return;
    order.splice(from, 1);
    order.splice(to, 0, source);
    prefs.setColumnOrder(options.id, order);
    apply();
  }

  function addControls(): void {
    for (const heading of node.querySelectorAll<HTMLTableCellElement>('thead th')) {
      const id = heading.dataset.tableColumn;
      if (!id || heading.querySelector('[data-table-layout-control]')) continue;
      heading.classList.add('managed-table-heading');
      const label = heading.textContent?.trim() || 'this';

      const grip = document.createElement('button');
      grip.type = 'button';
      grip.className = 'managed-table-move';
      grip.dataset.tableLayoutControl = 'true';
      grip.textContent = '⋮⋮';
      grip.title = 'Drag to reposition; use left and right arrow keys for keyboard control';
      grip.setAttribute('aria-label', `Reposition ${label} column`);
      const onGripKey = (event: KeyboardEvent): void => {
        if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
        event.preventDefault();
        const order = prefs.columnOrder(options.id, options.columns);
        const index = order.indexOf(id);
        const target = order[index + (event.key === 'ArrowLeft' ? -1 : 1)];
        if (target) move(id, target);
      };
      const clearDragMarks = (): void => {
        for (const th of node.querySelectorAll<HTMLElement>('thead th')) {
          th.classList.remove('managed-table-drop-target', 'managed-table-dragging');
        }
      };
      const onGripPointerDown = (event: PointerEvent): void => {
        // As in the grid: the last heading crossed stays the target, so a drag
        // that ends a little off the heading row still lands.
        let target = '';
        startColumnDrag(event, node, {
          over: (over) => {
            if (over) target = over;
            heading.classList.add('managed-table-dragging');
            for (const th of node.querySelectorAll<HTMLElement>('thead th')) {
              th.classList.toggle(
                'managed-table-drop-target',
                th.dataset.tableColumn === target && target !== id,
              );
            }
          },
          drop: (dropped) => {
            if (dropped) target = dropped;
            clearDragMarks();
            if (target) move(id, target);
          },
          cancel: clearDragMarks,
        });
      };
      grip.addEventListener('keydown', onGripKey);
      grip.addEventListener('pointerdown', onGripPointerDown);
      disposers.push(() => grip.removeEventListener('keydown', onGripKey));
      disposers.push(() => grip.removeEventListener('pointerdown', onGripPointerDown));
      heading.insertBefore(grip, heading.firstChild);

      const resize = document.createElement('button');
      resize.type = 'button';
      resize.className = 'managed-table-resizer';
      resize.dataset.tableLayoutControl = 'true';
      resize.title = 'Drag to resize; double-click to restore the default width';
      resize.setAttribute('aria-label', `Resize ${label} column`);
      const onPointerDown = (event: PointerEvent): void => {
        startColumnResize(event, heading.getBoundingClientRect().width, {
          move: (width) => {
            widths[id] = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, width));
            apply();
          },
          done: () => {
            if (widths[id] !== undefined) prefs.setColumnWidth(options.id, id, widths[id]);
          },
        });
      };
      const onResizeKey = (event: KeyboardEvent): void => {
        if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
        event.preventDefault();
        const current = heading.getBoundingClientRect().width;
        widths[id] = Math.max(
          MIN_WIDTH,
          Math.min(MAX_WIDTH, current + (event.key === 'ArrowRight' ? 8 : -8)),
        );
        prefs.setColumnWidth(options.id, id, widths[id]!);
        apply();
      };
      const onDoubleClick = (): void => {
        delete widths[id];
        prefs.clearColumnWidth(options.id, id);
        apply();
      };
      resize.addEventListener('pointerdown', onPointerDown);
      resize.addEventListener('keydown', onResizeKey);
      resize.addEventListener('dblclick', onDoubleClick);
      disposers.push(() => resize.removeEventListener('pointerdown', onPointerDown));
      disposers.push(() => resize.removeEventListener('keydown', onResizeKey));
      disposers.push(() => resize.removeEventListener('dblclick', onDoubleClick));
      heading.appendChild(resize);
    }
  }

  const onViewport = (): void => setTableWidth();
  tagSourceCells();
  addControls();
  apply();
  const observer = new MutationObserver(() => {
    if (applying) return;
    queueMicrotask(() => {
      tagSourceCells();
      addControls();
      apply();
    });
  });
  observer.observe(node.tBodies.item(0) ?? node, { childList: true, subtree: true });
  addEventListener('resize', onViewport);

  return {
    update(next: TableLayoutOptions) {
      options = next;
      tagSourceCells();
      addControls();
      apply();
    },
    destroy() {
      observer.disconnect();
      removeEventListener('resize', onViewport);
      for (const dispose of disposers) dispose();
      frame?.classList.remove('managed-table-frame');
    },
  };
}

/**
 * Whether an address only the controller's own machine can reach.
 *
 * The same rule as `loopbackHost` in `internal/config`: localhost, any name
 * under `.localhost`, and the loopback ranges. Two dialogs had a copy of this
 * each and they did not agree -- one knew about `.localhost` and the whole
 * `127.0.0.0/8` range, the other matched exactly `127.0.0.1` -- so a controller
 * reached on `127.0.0.2` was refused by the host flow and accepted by the
 * GitHub App dialog, which is the one that bakes the address into an App for
 * ever.
 */
export function isLoopbackHost(host: string): boolean {
  const bare = host.replace(/^\[|\]$/g, '').toLowerCase();
  if (bare === 'localhost' || bare.endsWith('.localhost')) return true;
  if (bare === '::1' || bare === '0:0:0:0:0:0:0:1') return true;
  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(bare);
}

/**
 * The same question asked of a whole URL. An address that will not parse is
 * not treated as local: the caller's next step is to complain about it, and
 * "this is only reachable from here" would be the wrong complaint.
 */
export function isLoopbackURL(raw: string): boolean {
  try {
    return isLoopbackHost(new URL(raw).hostname);
  } catch {
    return false;
  }
}

/**
 * The Zoomies API client.
 *
 * Hand-written rather than generated, but every signature is derived from
 * `schema.d.ts`, which is generated from `api/openapi.yaml`. If the API changes
 * shape, this file stops compiling -- which is the point.
 *
 * Error handling follows the contract in docs/api-surface.md:
 *   401  the session is gone. Clear it and go to the login page.
 *   403  the message names the role required. Show it in the server's words.
 *   422  `errors` names the offending fields so a form can attach them.
 */
import { supportHint } from '$lib/errors';
import type {
  Body,
  ErrorCode,
  FieldError,
  Job,
  OptionalBody,
  Query,
  Result,
  SignInChallenge,
} from './types';

const BASE = '/api/v1';

/* -- errors -------------------------------------------------------------- */

export interface ApiErrorInit {
  status: number;
  code: ErrorCode;
  message: string;
  field?: string;
  detail?: string;
  errors?: FieldError[];
}

/**
 * Every failure the client throws. Never a bare `Error`, so callers can always
 * ask what happened without parsing strings.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly code: ErrorCode;
  readonly field: string | undefined;
  readonly detail: string | undefined;
  readonly errors: FieldError[] | undefined;

  constructor(init: ApiErrorInit) {
    super(init.message);
    this.name = 'ApiError';
    this.status = init.status;
    this.code = init.code;
    this.field = init.field;
    this.detail = init.detail;
    this.errors = init.errors;
  }

  /** Signed in, but not allowed. The server's message says which role is needed. */
  get isForbidden(): boolean {
    return this.status === 403;
  }

  /** The request conflicts with the current state -- a runner already terminal, say. */
  get isConflict(): boolean {
    return this.status === 409;
  }

  get isNotFound(): boolean {
    return this.status === 404;
  }

  /** The network, not the server. Nothing the operator did is at fault. */
  get isOffline(): boolean {
    return this.status === 0;
  }

  /** Field errors keyed by field name, ready to hand to a form. */
  fieldErrors(): Record<string, string> {
    const out: Record<string, string> = {};
    for (const e of this.errors ?? []) out[e.field] = e.message;
    if (this.field && !out[this.field]) out[this.field] = this.message;
    return out;
  }
}

/* -- the 401 hook --------------------------------------------------------
 * The client must not import the session or the router: they both import the
 * client. The shell registers a handler at boot instead.
 * --------------------------------------------------------------------- */

type UnauthorizedHandler = () => void;
let unauthorized: UnauthorizedHandler | undefined;

/** Register what happens when the server says the session is gone. */
export function onUnauthorized(handler: UnauthorizedHandler): void {
  unauthorized = handler;
}

/* -- query strings -------------------------------------------------------- */

export type QueryValue = string | number | boolean | null | undefined | readonly string[];
export type QueryInput = Record<string, QueryValue | readonly number[]>;

/**
 * Serialise a query object the way the API expects: `form` style with
 * `explode: true`, so an array repeats its key (`?state=idle&state=busy`).
 * Empty values are dropped rather than sent blank.
 */
export function toQuery(query: QueryInput | undefined): string {
  if (!query) return '';
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null || value === '') continue;
    if (Array.isArray(value)) {
      for (const v of value as readonly (string | number)[]) {
        if (v === undefined || v === null || v === '') continue;
        params.append(key, String(v));
      }
    } else {
      params.append(key, String(value));
    }
  }
  const s = params.toString();
  return s ? `?${s}` : '';
}

/* -- the request ---------------------------------------------------------- */

export interface RequestOptions {
  query?: QueryInput;
  body?: unknown;
  signal?: AbortSignal;
  /** Do not run the global 401 handler -- used by the boot probe and the login form. */
  allow401?: boolean;
}

type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

async function request<T>(method: Method, path: string, options: RequestOptions = {}): Promise<T> {
  const headers: Record<string, string> = { Accept: 'application/json' };
  const init: RequestInit = {
    method,
    headers,
    // Cookie auth. Bearer tokens are for the CLI, not for this UI.
    credentials: 'same-origin',
  };
  if (options.signal) init.signal = options.signal;
  if (options.body !== undefined) {
    headers['Content-Type'] = 'application/json';
    init.body = JSON.stringify(options.body);
  }

  let response: Response;
  try {
    response = await fetch(`${BASE}${path}${toQuery(options.query)}`, init);
  } catch (cause) {
    if (cause instanceof DOMException && cause.name === 'AbortError') throw cause;
    throw new ApiError({
      status: 0,
      code: 'internal',
      message: 'Could not reach the Zoomies API. Check that the controller is still running.',
      detail: cause instanceof Error ? cause.message : undefined,
    });
  }

  if (response.status === 204 || response.status === 205) return undefined as T;

  const isJson = (response.headers.get('content-type') ?? '').includes('application/json');
  const payload: unknown = isJson ? await response.json().catch(() => undefined) : undefined;

  if (response.ok) return payload as T;

  if (response.status === 401 && !options.allow401) unauthorized?.();

  throw new ApiError(errorFrom(response.status, payload));
}

interface ErrorBody {
  error?: { code?: ErrorCode; message?: string; field?: string; detail?: string };
  errors?: FieldError[];
}

function errorFrom(status: number, payload: unknown): ApiErrorInit {
  const body = (payload ?? {}) as ErrorBody;
  const inner = body.error ?? {};
  return {
    status,
    code: inner.code ?? defaultCode(status),
    message: inner.message ?? defaultMessage(status),
    field: inner.field,
    detail: inner.detail,
    errors: body.errors,
  };
}

function defaultCode(status: number): ErrorCode {
  if (status === 400) return 'bad_request';
  if (status === 401) return 'unauthorized';
  if (status === 403) return 'forbidden';
  if (status === 404) return 'not_found';
  if (status === 409) return 'conflict';
  if (status === 422) return 'unprocessable';
  if (status === 429) return 'rate_limited';
  return 'internal';
}

function defaultMessage(status: number): string {
  switch (status) {
    case 401:
      return 'Your session has expired. Sign in again to continue.';
    case 403:
      return 'You do not have permission to do that.';
    case 404:
      return 'That no longer exists. It may have been removed since the page loaded.';
    case 409:
      return 'That conflicts with the current state. Reload the page and try again.';
    case 429:
      return 'Too many attempts. Wait a moment and try again.';
    default:
      return `The server returned ${status}. ${supportHint()}`;
  }
}

/** The low-level verbs. Prefer the named helpers below; these are the escape hatch. */
export const api = {
  get: <T>(path: string, options?: RequestOptions) => request<T>('GET', path, options),
  post: <T>(path: string, options?: RequestOptions) => request<T>('POST', path, options),
  put: <T>(path: string, options?: RequestOptions) => request<T>('PUT', path, options),
  patch: <T>(path: string, options?: RequestOptions) => request<T>('PATCH', path, options),
  del: <T>(path: string, options?: RequestOptions) => request<T>('DELETE', path, options),
};

