/**
 * The brand, as it appears on GitHub.
 *
 * This is the browser's half of internal/store/brand.go. The two have to agree
 * exactly: the server brands the labels it stores, and the wizard shows the
 * operator what it is about to store. A disagreement would show one label in
 * the preview and save another.
 */

/** The product name, lowercased, as it appears in a label. */
export const BRAND = 'zoomies';

/** The one label every Zoomies pool answers to. */
export const BRAND_LABEL = BRAND;

/** What every runner name starts with. */
export const RUNNER_NAME_PREFIX = `${BRAND}-`;

/** The labels GitHub attaches to every self-hosted runner by itself. */
export const IMPLICIT_LABELS: readonly string[] = [
  'self-hosted',
  'linux',
  'windows',
  'macos',
  'x64',
  'arm64',
  'arm',
];

/** How long the part of a label derived from a pool name may be. */
const MAX_LABEL_SEGMENT = 40;

export function isImplicit(label: string): boolean {
  return IMPLICIT_LABELS.includes(label.trim().toLowerCase());
}

/** Lowercase and trim, which is how GitHub compares two labels. */
export function normalizeLabel(label: string): string {
  return label.trim().toLowerCase();
}

/** Lowercase, de-duplicate and sort, which is what the server stores. */
export function normalizeLabels(labels: readonly string[]): string[] {
  const seen = new Set<string>();
  for (const label of labels) {
    const l = normalizeLabel(label);
    if (l !== '') seen.add(l);
  }
  return [...seen].sort();
}

/**
 * Reduce an arbitrary string to the characters GitHub accepts in a label:
 * lowercase letters, digits and single hyphens, trimmed.
 */
export function sanitizeLabel(value: string): string {
  const collapsed = normalizeLabel(value)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return collapsed.slice(0, MAX_LABEL_SEGMENT).replace(/-+$/, '');
}

/**
 * The label a pool of this name should answer to: the brand, then the name.
 * A name that already starts with the brand keeps it rather than gaining a
 * second one.
 */
export function brandedLabel(name: string): string {
  const s = sanitizeLabel(name);
  if (s === '' || s === BRAND) return BRAND_LABEL;
  return s.startsWith(RUNNER_NAME_PREFIX) ? s : RUNNER_NAME_PREFIX + s;
}

/**
 * The name a pool of this name will be saved under: the brand, then the name.
 *
 * The server brands every pool name on the way in, so a field left saying
 * "gpu" would be showing the operator a name that is not the one they get.
 * A name that already carries the brand keeps it rather than gaining a second.
 * An empty name stays empty, because "give the pool a name" is what should be
 * said about it, not "zoomies-".
 */
export function brandedName(name: string): string {
  const s = name.trim();
  const lower = normalizeLabel(s);
  if (s === '' || lower === BRAND || lower.startsWith(RUNNER_NAME_PREFIX)) return s;
  return RUNNER_NAME_PREFIX + s.replace(/^-+/, '');
}

/** These labels, with the brand guaranteed present. */
export function brandLabels(labels: readonly string[]): string[] {
  return normalizeLabels([BRAND_LABEL, ...labels]);
}

/**
 * The shortest `runs-on` value that reaches a pool with these labels.
 *
 * One label of its own is enough, and it is what a workflow should write:
 * "runs-on: zoomies-linux-x64" says where the job runs. Where a pool needs
 * several labels to be identified, the list form is rendered instead, because
 * dropping one would send the job somewhere else.
 */
export function runsOn(labels: readonly string[]): string {
  const all = normalizeLabels(labels);
  const specific = all.filter((l) => !isImplicit(l) && l !== BRAND_LABEL);
  if (specific.length === 1) return specific[0]!;
  if (specific.length === 0) return all.includes(BRAND_LABEL) ? BRAND_LABEL : 'self-hosted';
  return `[${specific.join(', ')}]`;
}

/** The workflow snippet a `runs-on` value belongs in. */
export function runsOnSnippet(labels: readonly string[]): string {
  return `jobs:\n  build:\n    runs-on: ${runsOn(labels)}`;
}

/**
 * Loading route code over a connection that drops things.
 *
 * Every page but the login form arrives as its own content-hashed chunk,
 * fetched the moment somebody navigates to it. Two ordinary events break that
 * fetch, and neither is a bug in the page being opened:
 *
 *  * A phone on a flaky link -- a VPN reconnecting, a lift, a tunnel -- loses
 *    the request. Nothing is wrong; the bytes stopped arriving.
 *  * The controller was upgraded while the tab sat open. Chunk names carry a
 *    content hash, so the URL the open page holds is gone from the new build
 *    and the server answers 404. Every navigation from that tab fails until it
 *    is reloaded.
 *
 * Both look identical to `import()`, and both are fixed by the thing an
 * operator does out of habit anyway: reload. So this does it for them -- a
 * couple of quiet retries first, then a single reload, and only once the
 * controller has been proven reachable. That last condition is the point: when
 * the network really is down, reloading trades a working shell for the
 * browser's offline page, so the caller's error state is the better answer.
 */

/** How long to wait before each retry, in milliseconds. */
const RETRY_DELAYS = [200, 700] as const;

/**
 * Where a spent reload is recorded, so a chunk that is broken rather than
 * missing cannot put the tab in a reload loop.
 */
const RELOAD_KEY = 'zoomies.chunk-reload';

/**
 * The controller version a reload has already been spent on. An upgrade is a
 * new reason to reload however recently one was spent; the same upgrade twice
 * is a loop.
 */
const RELOAD_VERSION_KEY = 'zoomies.chunk-reload-version';

/** A second failure this soon after a reload is not one a reload fixes. */
const RELOAD_COOLDOWN = 30_000;

const sleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Load a route chunk, retrying a failure that looks transient.
 *
 * @param load the route's `() => import(...)`.
 * @param abandoned true once a later navigation has superseded this one, so a
 *   retry is not spent on a page nobody is waiting for any more.
 */
export async function loadChunk<T>(
  load: () => Promise<T>,
  abandoned: () => boolean = () => false,
): Promise<T> {
  let last: unknown;
  try {
    return await load();
  } catch (cause) {
    last = cause;
  }
  for (const delay of RETRY_DELAYS) {
    if (abandoned()) throw last;
    await sleep(delay);
    if (abandoned()) throw last;
    try {
      return await load();
    } catch (cause) {
      last = cause;
    }
  }
  throw last;
}

/**
 * Reload the page to recover from a chunk that would not load, if a reload is
 * both likely to help and safe to spend.
 *
 * @returns true when a reload is under way, so the caller should keep waiting
 *   rather than rendering an error the operator has no time to read.
 */
export async function reloadForFailedChunk(): Promise<boolean> {
  const now = Date.now();
  let spent: number;
  let reloadedFor: string | null;
  try {
    spent = Number(sessionStorage.getItem(RELOAD_KEY) ?? 0);
    reloadedFor = sessionStorage.getItem(RELOAD_VERSION_KEY);
  } catch {
    // Private mode, or storage denied. Without somewhere to record the reload
    // there is no way to stop it repeating, so leave it to the operator.
    return false;
  }

  const health = await controllerHealth();
  // Nothing is answering. Reloading now would trade a working shell for the
  // browser's offline page, so the caller's error state is the better answer.
  if (!health) return false;

  // An upgrade is what actually renames chunks, and the controller says which
  // version it is. Seeing a version this tab has not already reloaded for is
  // proof that a reload will help, so it is spent whatever the cooldown says:
  // the cooldown exists to stop a broken chunk looping, and a version that has
  // moved is not that. Without this, an upgrade landing within thirty seconds
  // of any earlier failure left the tab stuck on an error for a page that a
  // single reload would have fixed -- and every other page in that tab still
  // running code the fleet had moved on from.
  const upgraded = health.version !== '' && health.version !== reloadedFor;
  if (!upgraded && Number.isFinite(spent) && now - spent < RELOAD_COOLDOWN) return false;

  try {
    sessionStorage.setItem(RELOAD_KEY, String(now));
    if (health.version !== '') sessionStorage.setItem(RELOAD_VERSION_KEY, health.version);
  } catch {
    return false;
  }
  location.reload();
  return true;
}

/**
 * What the controller is, if it is there at all.
 *
 * A cheap unauthenticated request, uncached, answers two questions at once:
 * whether this phone is online, and which build is now being served. The
 * second is what tells "the upgrade moved the chunk" from "the request was
 * dropped", which are the two things that break an `import()` and want
 * different answers.
 *
 * It asks `/api/v1/meta` rather than `/healthz`. Liveness deliberately touches
 * nothing and says nothing but `{"ok":true}`, so reading a version from it got
 * an empty string every time and the upgrade case below could never fire --
 * which left the tab on an error for exactly the failure a reload fixes. Meta
 * is the route that already carries the build, it is already unauthenticated
 * because the shell needs it before anybody signs in, and it is equally cheap.
 *
 * Version and commit are both taken, because either moving means a new build
 * and new chunk names. A response with neither is still a reachable controller
 * -- an older one, or a proxy answering the probe -- so the identity is
 * optional and its absence falls back to the cooldown alone.
 */
async function controllerHealth(): Promise<{ version: string } | null> {
  try {
    const res = await fetch('/api/v1/meta', { cache: 'no-store', credentials: 'same-origin' });
    if (!res.ok) return null;
    const body: unknown = await res.json().catch(() => null);
    if (!body || typeof body !== 'object') return { version: '' };
    const meta = body as { version?: unknown; commit?: unknown };
    const parts = [meta.version, meta.commit].filter(
      (v): v is string => typeof v === 'string' && v !== '',
    );
    return { version: parts.join(' ') };
  } catch {
    return null;
  }
}

/**
 * Turning an API failure into something an operator can act on.
 *
 * The sign-in and first-run cards are the same screen at two moments in a
 * controller's life, and they meet the same failures: a controller that never
 * answered, a rate limiter, an origin check, a password that was refused. They
 * used to disagree about all of it -- Login.svelte separated four kinds and
 * Bootstrap.svelte printed `failure.message` raw -- so the two halves of the
 * first five minutes read as two different products. This is the one ladder
 * both of them climb.
 */
import { ApiError } from './api/client';

/**
 * The server's sentences are terse and lowercase, because they are also read
 * in a terminal and in a log line. On a card they are prose, so they start
 * with a capital and end with a full stop.
 *
 * Only ever the first letter and the last mark: not a word is changed, because
 * a 403 names the role required. Two things are left as written. A message that
 * opens with an identifier (`limits.job_stats_window ...`, `pool_ab12 ...`)
 * keeps its case, since a capital would name a setting that does not exist; and
 * one that ends in a path, an address or a colon takes no full stop, which
 * would be copied along with the address.
 */
export function sentence(text: string): string {
  const trimmed = text.trim();
  if (trimmed === '') return '';
  const identifier = /^\S*[._]\S*(\s|$)/.test(trimmed);
  const capitalised = identifier ? trimmed : trimmed.charAt(0).toUpperCase() + trimmed.slice(1);
  const open = /[.!?:]$/.test(capitalised) || /\S*\/\S*$/.test(capitalised);
  return open ? capitalised : `${capitalised}.`;
}

/**
 * What actually went wrong, in the operator's terms.
 *
 * A controller that never answered and a password that was refused look
 * identical in a generic "that did not work", and they need completely
 * different next steps. A 401 or 403 is shown in the server's own words: it
 * distinguishes a wrong password from a disabled account, from an account that
 * signs in through SSO, and -- on a 403 -- from the origin check refusing the
 * request, which is a proxy or external_url problem that "wrong password"
 * would send the operator off to fix in entirely the wrong place.
 */
export function authFailureText(error: unknown): string {
  if (!(error instanceof ApiError)) {
    if (error instanceof Error && error.message) return sentence(error.message);
    return 'That did not work, and the controller did not say why. Its logs will.';
  }
  if (error.status === 0) {
    return 'The controller did not answer. Check that it is running and that this address can reach it.';
  }
  if (error.status === 429) {
    return 'Too many attempts from this address. Wait a minute, then try again.';
  }
  if (error.status >= 500) {
    return 'The controller answered with an error. Its logs will say more than this page can.';
  }
  return sentence(error.message);
}

/**
 * The one sentence every "we could not tell you why" ends with.
 *
 * It used to say the controller log would have the cause, which assumes the
 * reader can read that log. On an instance one team operates while another
 * uses the fleet they cannot: the log belongs to the process, and the person
 * reading this runs pools on it. Naming the request ID and who to hand it to
 * is true for both — someone running their own instance is "whoever operates
 * this instance", and its log is theirs to open.
 *
 * One function rather than nine sentences, because nine sentences is how the
 * ninth came to say something the other eight had stopped saying.
 */
export function supportHint(requestId?: string): string {
  return requestId
    ? `Quote ${requestId} to whoever operates this instance; the cause is in its log.`
    : 'Quote the request ID to whoever operates this instance; the cause is in its log.';
}

/**
 * The fault vocabulary: whose a failure is, and what kind of failure it was.
 *
 * GitHub records a job whose runner died exactly as it records a job whose
 * tests failed. The server decides which is which -- it is the only side that
 * can -- and sends `fault_domain`, `fault_kind` and `fault_fix` on every job.
 * This file is the browser's half: the short label a badge shows and the
 * sentence a panel shows, neither of which belongs in a Go string.
 *
 * It is kept apart from status.ts for the same reason outcomes.ts is: that file
 * imports icon components and cannot be loaded outside a browser, and these
 * labels are wanted by tests that run in Node.
 */
import type { FaultKind } from '$lib/api/types';

/** Whose a failure is. Empty on a job that did not fail. */
export type FaultDomain = 'fleet' | 'workflow' | '';

interface FaultMeta {
  /** Two or three words, for a badge beside the outcome. */
  label: string;
  /** What happened, for the panel. The remedy comes from the server. */
  detail: string;
}

/**
 * Every category, in the order the docs list them: the ones that happen to a
 * running job first, then the ones that stop a runner ever taking one.
 *
 * The detail says what happened rather than what to do. What to do is
 * `fault_fix`, which the server sends with the job: one table of remedies, read
 * by the UI, the CLI and the problems drawer, rather than three that drift.
 */
const FAULTS: Record<FaultKind, FaultMeta> = {
  host_lost: {
    label: 'Host lost',
    detail:
      'The host stopped answering while it was running this job, and the runner went with the machine.',
  },
  out_of_memory: {
    label: 'Out of memory',
    detail: 'The runner was killed for exceeding its memory limit.',
  },
  out_of_disk: {
    label: 'Out of disk',
    detail: 'The host ran out of room. This job was the one running when the disk filled.',
  },
  removed: {
    label: 'Removed',
    detail: 'Somebody removed this runner with force while it was working.',
  },
  image: {
    label: 'Image',
    detail: 'The runner image could not be pulled or would not start.',
  },
  registration: {
    label: 'Registration',
    detail: 'GitHub would not register the runner, so it had nothing to attach to.',
  },
  backend: {
    label: 'Container backend',
    detail: 'The container backend on the host refused the work or did not answer.',
  },
  container_conflict: {
    label: 'Container name conflict',
    detail:
      'A container still occupies this name, and it could not be safely reclaimed. Check its ownership and whether another agent uses the same daemon.',
  },
  backend_busy: {
    label: 'Backend overloaded',
    detail:
      'The container backend on the host is there and did not answer in time, or was too slow to finish creating a container. The daemon is running; the machine is carrying more work than it can keep up with.',
  },
  config: {
    label: 'Configuration',
    detail:
      'The runner refused a setting it was given. Every runner in this pool will do the same until it is changed.',
  },
  runner_exited: {
    label: 'Runner stopped',
    detail: 'The runner stopped and the fleet could not narrow down why.',
  },
};

/**
 * The label for a category. A kind this build does not know falls back to its
 * own identifier made readable, rather than to nothing: a fleet running a newer
 * controller should show an unfamiliar word, not an empty badge.
 */
export function faultLabel(kind: string | null | undefined): string {
  if (!kind) return '';
  const known = FAULTS[kind as FaultKind];
  if (known) return known.label;
  return kind.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
}

/** What happened, for a panel. Empty for a category this build does not know. */
export function faultDetail(kind: string | null | undefined): string {
  if (!kind) return '';
  return FAULTS[kind as FaultKind]?.detail ?? '';
}

/** Every category this build knows, for a filter's options. */
export const FAULT_KINDS = Object.keys(FAULTS) as FaultKind[];

/**
 * Whose a failure is, from the fields the server sends.
 *
 * It reads `fault_domain` and falls back to the same rule the server applies,
 * because a job delivered by an older controller carries the prose and not the
 * domain, and reading such a job as the workflow's would blame somebody for a
 * failure that was ours.
 */
export function faultDomain(job: {
  fault_domain?: string | null;
  fault_kind?: string | null;
  runner_fault?: string | null;
  conclusion?: string | null;
}): FaultDomain {
  if (job.fault_domain === 'fleet' || job.fault_domain === 'workflow') return job.fault_domain;
  if (job.fault_kind || job.runner_fault) return 'fleet';
  return '';
}

/** Whether this deployment, rather than the workflow, is why a job went wrong. */
export function fleetFailed(job: {
  fault_domain?: string | null;
  fault_kind?: string | null;
  runner_fault?: string | null;
}): boolean {
  return faultDomain(job) === 'fleet';
}

/**
 * What in a frame is actually news.
 *
 * Kept apart from `entries.ts`, which imports the state map and its icon
 * components and so cannot be loaded outside a browser, for the same reason
 * `outcomes.ts` is kept apart from `status.ts`: this is the half a person
 * would argue about, and it is tested in Node.
 *
 * The rule every function here exists to enforce is that **a frame is not an
 * event**. A host publishes one whenever a heartbeat moves its CPU reading; a
 * machine publishes one on every step of an operation it is already in; a
 * runner publishes one for each state on the way up. A feed fed by frames is a
 * feed nobody reads -- and worse, it is one an operator turns off, losing the
 * lines that were worth having. So each of these answers the narrower
 * question: what is different about this that a person would want to be told,
 * and nothing that is merely different.
 */
import type {
  Host,
  Installation,
  Job,
  Machine,
  MachineState,
  Problem,
  Provider,
  RunnerState,
} from '../api/types';
import { outcomeOf } from '../outcomes';
import { problemKey } from '../problems/identity';

/* -- hosts ---------------------------------------------------------------- */

/**
 * The five facts about a host worth a line. Everything else a host frame
 * carries -- its load, its free slots, when it last spoke -- moves every
 * thirty seconds and says nothing that has not already been said by the
 * capacity map.
 */
export interface HostSignal {
  healthy: boolean;
  cordoned: boolean;
  /** The throttle rung the controller has it on; 0 for none. */
  throttle: number;
  /** An agent too old to talk to Zoomies at all. */
  incompatible: boolean;
  /** Whether pressure is holding new runners off this host right now. */
  holding: boolean;
}

export type HostChange =
  | 'joined'
  | 'unreachable'
  | 'recovered'
  | 'cordoned'
  | 'uncordoned'
  | 'throttled'
  | 'calm'
  | 'holding'
  | 'admitting'
  | 'incompatible';

export function hostSignal(host: Host): HostSignal {
  return {
    healthy: host.healthy !== false,
    cordoned: host.cordoned === true,
    throttle: host.throttle?.level ?? 0,
    incompatible: host.incompatible === true,
    holding: Boolean(host.admission_reason),
  };
}

/**
 * What changed between two readings of a host, worst first.
 *
 * A host seen for the first time has joined the fleet, which is news exactly
 * once; the caller is responsible for not calling this for every host in the
 * first snapshot it loads.
 */
export function hostChanges(next: HostSignal, previous: HostSignal | undefined): HostChange[] {
  if (!previous) return ['joined'];
  const out: HostChange[] = [];
  if (next.healthy !== previous.healthy) out.push(next.healthy ? 'recovered' : 'unreachable');
  if (next.incompatible && !previous.incompatible) out.push('incompatible');
  if (next.cordoned !== previous.cordoned) out.push(next.cordoned ? 'cordoned' : 'uncordoned');
  // Every rung is its own line: a host climbing the ladder is a host under
  // worsening pressure, which is the thing an operator is watching for.
  if (next.throttle > previous.throttle) out.push('throttled');
  else if (next.throttle === 0 && previous.throttle > 0) out.push('calm');
  // The hold is not the throttle: a throttle takes slots away for minutes, a
  // hold is this moment's pressure refusing the next start. Both are answers
  // to "why is nothing starting here", and only the transitions are reported
  // -- the reason's wording moves with the load and would flap.
  if (next.holding !== previous.holding) out.push(next.holding ? 'holding' : 'admitting');
  return out;
}

/* -- runners ---------------------------------------------------------------- */

/**
 * The two moments in an ordinary runner's life worth a line.
 *
 * Not the six states it passes through: a fleet of ephemeral runners would
 * write one line per state per job, which is a log rather than a feed. A
 * runner reaching `idle` for the first time is the one that says the pool can
 * actually start containers -- the success the failures are the exception to
 * -- and a runner removed is the end of it. Coming back to idle from a job is
 * neither: the job's own line already said that.
 */
export type RunnerMilestone = 'ready' | 'retired';

export function runnerMilestone(
  next: RunnerState | undefined,
  previous: RunnerState | undefined,
): RunnerMilestone | null {
  if (!next || next === previous) return null;
  if (next === 'idle') return previous === 'busy' ? null : 'ready';
  if (next === 'removed') return 'retired';
  return null;
}

/* -- elastic CPU ------------------------------------------------------------ */

/**
 * A runner's elastic-CPU state changing: it was lent spare CPU, or had it
 * taken back, or the host it is on came under enough pressure to slow it.
 *
 * The state rather than the factor, because the factor moves with every
 * heartbeat and the six states are what the runner's own page shows. A
 * runner seen for the first time says nothing: the state it is already in is
 * not something that just happened.
 */
export function cpuChange(next: string | undefined, previous: string | undefined): string | null {
  if (!next || previous === undefined || next === previous) return null;
  return next;
}

/* -- machines -------------------------------------------------------------- */

/**
 * The states of a rented machine worth a line: it is costing money, it is
 * earning it, it is going away, or it went wrong. The steps between -- being
 * powered on, being bootstrapped, enrolling -- are progress rather than news,
 * and the machine's own page has them with their timings.
 */
const MACHINE_NEWS: ReadonlySet<MachineState> = new Set<MachineState>([
  'creating',
  'ready',
  'draining',
  'deleted',
  'failed',
  'quarantined',
]);

/** The state a machine has reached that is worth telling somebody, or null. */
export function machineChange(
  next: Pick<Machine, 'state'>,
  previous: MachineState | undefined,
): MachineState | null {
  const state = next.state;
  if (!state || state === previous) return null;
  return MACHINE_NEWS.has(state) ? state : null;
}

/* -- jobs ------------------------------------------------------------------ */

/**
 * What a finished job is worth saying, and on whose account.
 *
 * Every finished job is news of some kind -- this is the one category where a
 * frame that changes nothing does not exist, because a job is reported over
 * exactly once. What differs is which category it lands in: the failures are
 * what an operator acts on and stay on by default, and the rest are the panel
 * this feed replaced, which on a fleet finishing a job a minute is the noisiest
 * thing here and is a switch of its own for that reason.
 *
 * `runner_lost` is kept apart from `failed` although GitHub records both as a
 * failure: the runner stopped under the job, so that one is the fleet's own,
 * and telling the two apart is what the Overview is for.
 */
export type JobNews = 'runner_lost' | 'failed' | 'succeeded' | 'cancelled' | 'unknown';

export function jobNews(job: Job): JobNews | null {
  if (job.state !== 'completed') return null;
  if (job.runner_fault) return 'runner_lost';
  const outcome = outcomeOf(job);
  return outcome === 'failed' ? 'failed' : outcome;
}

/** Whether this is one of the two an operator is meant to act on. */
export function jobFailure(news: JobNews): boolean {
  return news === 'failed' || news === 'runner_lost';
}

/* -- providers and installations ------------------------------------------- */

export type ProviderChange =
  'paused' | 'resumed' | 'disabled' | 'enabled' | 'unreachable' | 'reachable';

export interface ProviderSignal {
  enabled: boolean;
  paused: boolean;
  /** Whether the last preflight had something to complain about. */
  failing: boolean;
}

export function providerSignal(provider: Provider): ProviderSignal {
  return {
    enabled: provider.enabled !== false,
    paused: provider.paused === true,
    failing: Boolean(provider.last_check_error),
  };
}

export function providerChanges(
  next: ProviderSignal,
  previous: ProviderSignal | undefined,
): ProviderChange[] {
  // A provider first seen is a provider somebody has just added, and adding
  // one is an audit entry rather than an incident.
  if (!previous) return [];
  const out: ProviderChange[] = [];
  if (next.enabled !== previous.enabled) out.push(next.enabled ? 'enabled' : 'disabled');
  if (next.paused !== previous.paused) out.push(next.paused ? 'paused' : 'resumed');
  if (next.failing !== previous.failing) out.push(next.failing ? 'unreachable' : 'reachable');
  return out;
}

export type InstallationChange = 'connected' | 'failing' | 'working';

export function installationChange(
  next: Installation,
  previous: boolean | undefined,
): InstallationChange | null {
  const healthy = next.healthy !== false;
  if (previous === undefined) return healthy ? null : 'failing';
  if (healthy === previous) return null;
  return healthy ? 'working' : 'failing';
}

/* -- problems -------------------------------------------------------------- */

/**
 * The problems in this report that were not in the last one.
 *
 * Identity is the drawer's, not the prose's, so "5 deliveries were rejected"
 * becoming "6 deliveries were rejected" is the same problem and is reported
 * once. `seen` is updated in place: the caller holds the set for as long as
 * the tab is open, and a problem that clears and comes back is news again.
 */
export function newProblems(items: readonly Problem[], seen: Set<string>): Problem[] {
  const live = new Set(items.map(problemKey));
  for (const key of seen) if (!live.has(key)) seen.delete(key);
  const out: Problem[] = [];
  for (const problem of items) {
    const key = problemKey(problem);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(problem);
  }
  return out;
}

/**
 * One line of the Overview's feed, whatever it is about.
 *
 * Every entry is the same four things -- a mark in one of the six status
 * tones, what happened, what it happened to, and when -- so that a feed
 * carrying nine kinds of news still reads as one list rather than nine
 * stacked widgets. The detail line underneath is the controller's own
 * sentence where there is one: the scheduler's reason, the throttle's
 * explanation, the hypervisor's complaint. Paraphrasing those is how a
 * dashboard stops being trustworthy.
 *
 * The tones are the fixed status mapping every other page uses, and they are
 * used for the same meanings: danger for something that went wrong, draining
 * for something going away, pending for something under way or under
 * pressure, idle for something that came good, neutral for a fact.
 */
import {
  Boxes,
  CircleMinus,
  Plug,
  Minus,
  Plus,
  ScrollText,
  ServerCog,
  TrendingDown,
  TrendingUp,
} from '@lucide/svelte';
import type { LucideIcon } from '@lucide/svelte';
import type {
  AuditEvent,
  Host,
  Installation,
  Job,
  Machine,
  MachineState,
  Pool,
  Problem,
  Provider,
  Runner,
  ScalingEvent,
  WebhookDelivery,
} from '../api/types';
import { faultLabel } from '../faults';
import { formatDuration, pluralise, shortId } from '../format';
import {
  cpuResourceStatus,
  deliveryStatus,
  hostStatus,
  jobStatus,
  machineStatus,
  managedJob,
  runnerStatus,
  severityStatus,
  ELSEWHERE,
  RUNNER_LOST,
  type StatusTone,
} from '../status';
import type { FeedCategoryID } from './categories';
import {
  jobFailure,
  type HostChange,
  type InstallationChange,
  type JobNews,
  type ProviderChange,
  type RunnerMilestone,
} from './changes';

export interface FeedEntry {
  /**
   * Stable for the fact rather than for the frame, so the same thing arriving
   * twice -- a fetch and the replay of the frame it overlapped with -- is one
   * line. A repeated key in a keyed list is a framework error, not a cosmetic
   * one.
   */
  id: string;
  category: FeedCategoryID;
  /** When it happened, as the payload said, or when it arrived. */
  at: string;
  tone: StatusTone;
  icon: LucideIcon;
  /** What happened, in the fewest words that are still true. */
  title: string;
  /** The controller's own sentence about it, where there is one. */
  detail?: string;
  /** What it happened to, and the page that has the whole of it. */
  target?: { label: string; href?: string };
  /**
   * True for a job no runner of this fleet ran. The panel keeps these and
   * shows them only when the Overview is asked for every runner GitHub
   * reports on, which is the same switch its other job panels read.
   */
  elsewhere?: boolean;
}

/** Now, in the shape every timestamp in the API has. */
export function now(): string {
  return new Date().toISOString();
}

/* -- scaling --------------------------------------------------------------- */

/**
 * A scheduler decision.
 *
 * `index` is only there for a controller old enough to have written a
 * decision without an id; two decisions in the same second on the same pool
 * would otherwise share a key.
 */
export function scalingEntry(event: ScalingEvent, index: number): FeedEntry {
  const from = event.from;
  const to = event.to;
  const direction =
    from === undefined || to === undefined || to === from ? 'hold' : to > from ? 'up' : 'down';
  const counts = from !== undefined && to !== undefined ? ` ${from} → ${to}` : '';
  return {
    id: `scaling:${event.id ?? `${event.pool_id ?? ''}:${event.created_at ?? ''}:${index}`}`,
    category: 'scaling',
    at: event.created_at ?? '',
    tone: direction === 'up' ? 'pending' : direction === 'down' ? 'draining' : 'neutral',
    icon: direction === 'up' ? TrendingUp : direction === 'down' ? TrendingDown : Minus,
    title:
      direction === 'up'
        ? `Scaled up${counts}`
        : direction === 'down'
          ? `Scaled down${counts}`
          : 'Held',
    detail: event.reason || undefined,
    target: {
      label: event.pool_name ?? 'Unnamed pool',
      href: event.pool_id ? `/pools/${event.pool_id}` : undefined,
    },
  };
}

/* -- runners --------------------------------------------------------------- */

/**
 * A runner that failed. The fix is the detail rather than the message where
 * there is one: a runner that died before ever taking a job is the case this
 * exists for, and nothing else in the fleet says why a pool's containers will
 * not start.
 */
export function runnerFailureEntry(runner: Runner): FeedEntry | null {
  if (runner.state !== 'failed' || !runner.id) return null;
  const status = runnerStatus('failed');
  return {
    id: `runner:${runner.id}:failed`,
    category: 'runners',
    at: runner.finished_at ?? runner.created_at ?? '',
    tone: status.tone,
    icon: status.icon,
    title: 'A runner failed',
    detail: runner.fault_fix || runner.message || undefined,
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/**
 * A runner reaching the two moments of an ordinary life: ready for work, and
 * gone when the work was done.
 *
 * This is the half of the fleet that goes right, and it is here because a
 * panel that only ever reports failures teaches an operator that silence is
 * the good state -- which is the same thing as teaching them not to read it.
 */
export function runnerMilestoneEntry(
  runner: Runner,
  milestone: RunnerMilestone,
  at: string,
): FeedEntry | null {
  if (!runner.id) return null;
  const ready = milestone === 'ready';
  const status = runnerStatus(ready ? 'idle' : 'removed');
  const handled = runner.jobs_handled ?? 0;
  return {
    id: `runner:${runner.id}:${milestone}`,
    category: 'runner-lifecycle',
    at: (ready ? runner.registered_at : runner.finished_at) ?? at,
    tone: ready ? 'idle' : 'neutral',
    icon: status.icon,
    title: ready ? 'A runner is ready for work' : 'A runner finished and was removed',
    detail: ready
      ? [runner.pool_name, runner.host_name].filter(Boolean).join(' · ') || undefined
      : // What it was for, which is the only thing that distinguishes an
        // ephemeral runner's end from a scale-down taking an idle one away.
        [
          handled > 0 ? pluralise(handled, 'job') : 'no jobs',
          runner.pool_name ?? '',
          runner.host_name ?? '',
        ]
          .filter(Boolean)
          .join(' · '),
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/* -- elastic CPU ------------------------------------------------------------ */

/**
 * A runner lent spare CPU, or having it taken back.
 *
 * The title is the controller's own label -- "Squirrel spotted — maximum
 * zoomies" -- because that vocabulary is the product's, it is what the
 * runner's own page says, and a feed that translated it into "CPU allocation
 * factor 1.8" would be describing a different system from the one beside it
 * -- unless the operator has turned that vocabulary off, when it says the
 * same thing plainly instead.
 */
export function cpuEntry(
  runner: Runner,
  state: string,
  at: string,
  quirky = true,
): FeedEntry | null {
  if (!runner.id) return null;
  const cpu = runner.cpu_resource;
  const status = cpuResourceStatus(state, cpu?.label, quirky);
  const current = cpu?.current_cpus;
  const guaranteed = cpu?.guaranteed_cpus;
  return {
    id: `cpu:${runner.id}:${state}:${at}`,
    category: 'cpu',
    at,
    tone: status.tone,
    icon: status.icon,
    title: status.label,
    detail:
      current !== undefined && guaranteed !== undefined
        ? `${formatCPUs(current)} CPUs now against a guarantee of ${formatCPUs(guaranteed)}` +
          (runner.host_name ? ` · ${runner.host_name}` : '')
        : status.hint,
    target: { label: runner.name ?? shortId(runner.id), href: `/runners/${runner.id}` },
  };
}

/** CPUs as the runner's own page prints them: whole where they are whole. */
function formatCPUs(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}

/* -- jobs ------------------------------------------------------------------ */

/**
 * One finished job, in the shape the recent-outcomes panel used to give it:
 * what it was, how it ended, the step it stopped at or the fault behind it,
 * the repository and branch, and how long it took. That panel is gone, and
 * this is where its rows went -- a job ending is news like anything else, and
 * two reverse-chronological lists on one page, each with its own idea of what
 * belongs on it, is one list too many.
 *
 * The failures land in their own category, so an operator on a busy fleet can
 * switch off the hundred jobs that succeeded without switching off the two
 * that did not.
 */
export function jobEntry(job: Job, news: JobNews, at = now()): FeedEntry | null {
  if (!job.id) return null;
  const failure = jobFailure(news);
  const status = news === 'runner_lost' ? RUNNER_LOST : jobStatus('completed', job.conclusion);
  return {
    id: `job:${job.id}`,
    category: failure ? 'jobs' : 'outcomes',
    at: job.completed_at ?? job.started_at ?? at,
    tone: failure ? 'danger' : status.tone,
    icon: status.icon,
    title: jobTitle(job, news),
    detail: jobDetail(job, news),
    // Kept rather than dropped, and hidden unless the page is asked for
    // everything: GitHub reports every job in the repositories an installation
    // covers, and on an organisation that also uses hosted runners most of
    // them are somebody else's.
    elsewhere: !managedJob(job),
    target: {
      label: `${job.workflow ?? 'Unknown workflow'} / ${job.job_name ?? 'unnamed job'}`,
      href: `/jobs?q=${encodeURIComponent(job.job_name ?? '')}&repo=${encodeURIComponent(job.repo ?? '')}`,
    },
  };
}

function jobTitle(job: Job, news: JobNews): string {
  if (news === 'runner_lost') return 'A job’s runner stopped under it';
  if (news === 'failed') return 'A job failed';
  switch ((job.conclusion ?? '').toLowerCase()) {
    case 'success':
      return 'A job succeeded';
    case 'cancelled':
      return 'A job was cancelled';
    case 'skipped':
      return 'A job was skipped';
    default:
      return 'A job finished';
  }
}

/**
 * The one line under it, in the order the outcomes panel read: why it ended
 * that way, where it came from, and how long it took.
 *
 * The fault's category rather than "the runner stopped under it" for the
 * fleet's own failures, because the sentence above already says that and the
 * word that differs between two lines is the one worth the space.
 */
function jobDetail(job: Job, news: JobNews): string | undefined {
  const why =
    news === 'runner_lost'
      ? faultLabel(job.fault_kind).toLowerCase() || 'the runner stopped under it'
      : news === 'failed' && job.failed_step
        ? `at ${job.failed_step.name ?? `step ${job.failed_step.number ?? '?'}`}`
        : '';
  const parts = [
    !managedJob(job) ? ELSEWHERE.label.toLowerCase() : '',
    why,
    job.repo ?? '',
    job.head_branch ?? '',
    formatDuration(job.duration_ms),
  ].filter((part) => part && part !== '--');
  return parts.length > 0 ? parts.join(' · ') : undefined;
}

/* -- hosts ----------------------------------------------------------------- */

const HOST_NEWS: Record<HostChange, { title: string; tone: StatusTone }> = {
  joined: { title: 'A host joined the fleet', tone: 'idle' },
  unreachable: { title: 'A host stopped answering', tone: 'danger' },
  recovered: { title: 'A host is answering again', tone: 'idle' },
  cordoned: { title: 'A host was cordoned', tone: 'draining' },
  uncordoned: { title: 'A host was uncordoned', tone: 'idle' },
  throttled: { title: 'A host was throttled', tone: 'pending' },
  calm: { title: 'A host’s throttle lifted', tone: 'idle' },
  holding: { title: 'A host is holding new runners', tone: 'pending' },
  admitting: { title: 'A host is taking runners again', tone: 'idle' },
  incompatible: { title: 'A host’s agent is too old for Zoomies', tone: 'danger' },
};

export function hostEntry(host: Host, change: HostChange, at: string): FeedEntry | null {
  if (!host.id) return null;
  const news = HOST_NEWS[change];
  const status = hostStatus(host);
  return {
    id: `host:${host.id}:${change}:${at}`,
    category: 'hosts',
    at,
    tone: news.tone,
    icon: change === 'joined' ? Plus : status.icon,
    title: news.title,
    detail:
      change === 'holding'
        ? host.admission_reason || undefined
        : change === 'throttled'
          ? host.throttle_reason || status.hint
          : change === 'incompatible'
            ? host.incompatible_reason || undefined
            : change === 'unreachable'
              ? status.hint
              : undefined,
    target: { label: host.name ?? shortId(host.id), href: '/hosts' },
  };
}

export function hostRemovedEntry(id: string, name: string | undefined, at: string): FeedEntry {
  return {
    id: `host:${id}:removed:${at}`,
    category: 'hosts',
    at,
    tone: 'neutral',
    icon: CircleMinus,
    title: 'A host was removed',
    target: { label: name ?? shortId(id), href: '/hosts' },
  };
}

/* -- machines and providers ------------------------------------------------- */

const MACHINE_NEWS: Record<string, string> = {
  creating: 'A machine is being rented',
  ready: 'A machine became a host',
  draining: 'A machine is draining',
  deleted: 'A machine was returned',
  failed: 'A machine failed',
  quarantined: 'A machine was quarantined',
};

export function machineEntry(machine: Machine, state: MachineState, at: string): FeedEntry {
  const status = machineStatus(state);
  return {
    id: `machine:${machine.id}:${state}`,
    category: 'machines',
    at: machine.updated_at ?? at,
    tone: status.tone,
    icon: status.icon,
    title: MACHINE_NEWS[state] ?? `A machine is ${status.label.toLowerCase()}`,
    detail:
      machine.provider_error ||
      machine.bootstrap_error ||
      machine.ownership_error ||
      machine.message ||
      undefined,
    target: { label: machine.name, href: `/machines/${machine.id}` },
  };
}

const PROVIDER_NEWS: Record<ProviderChange, { title: string; tone: StatusTone }> = {
  paused: { title: 'A provider was paused', tone: 'draining' },
  resumed: { title: 'A provider was resumed', tone: 'idle' },
  disabled: { title: 'A provider was disabled', tone: 'draining' },
  enabled: { title: 'A provider was enabled', tone: 'idle' },
  unreachable: { title: 'A provider could not be reached', tone: 'danger' },
  reachable: { title: 'A provider answered again', tone: 'idle' },
};

export function providerEntry(
  provider: Provider,
  change: ProviderChange,
  at: string,
): FeedEntry | null {
  if (!provider.id) return null;
  const news = PROVIDER_NEWS[change];
  return {
    id: `provider:${provider.id}:${change}:${at}`,
    category: 'machines',
    at,
    tone: news.tone,
    icon: ServerCog,
    title: news.title,
    detail:
      change === 'unreachable'
        ? provider.last_check_error || undefined
        : change === 'paused'
          ? provider.paused_reason || undefined
          : undefined,
    target: { label: provider.name ?? shortId(provider.id), href: `/providers/${provider.id}` },
  };
}

/* -- pools ------------------------------------------------------------------ */

export function poolEntry(pool: Pool, change: 'created' | 'updated', at: string): FeedEntry | null {
  if (!pool.id) return null;
  return {
    id: `pool:${pool.id}:${change}:${at}`,
    category: 'pools',
    at,
    tone: change === 'created' ? 'idle' : 'neutral',
    icon: change === 'created' ? Plus : Boxes,
    title: change === 'created' ? 'A pool was created' : 'A pool changed',
    target: { label: pool.name ?? shortId(pool.id), href: `/pools/${pool.id}` },
  };
}

export function poolRemovedEntry(id: string, name: string | undefined, at: string): FeedEntry {
  return {
    id: `pool:${id}:deleted:${at}`,
    category: 'pools',
    at,
    tone: 'neutral',
    icon: CircleMinus,
    title: 'A pool was deleted',
    target: { label: name ?? shortId(id), href: '/pools' },
  };
}

/* -- GitHub ------------------------------------------------------------------ */

const INSTALLATION_NEWS: Record<InstallationChange, { title: string; tone: StatusTone }> = {
  connected: { title: 'A GitHub App was connected', tone: 'idle' },
  failing: { title: 'The GitHub App connection is failing', tone: 'danger' },
  working: { title: 'The GitHub App connection is working again', tone: 'idle' },
};

export function installationEntry(
  installation: Installation,
  change: InstallationChange,
  at: string,
): FeedEntry | null {
  if (!installation.id) return null;
  const news = INSTALLATION_NEWS[change];
  return {
    id: `installation:${installation.id}:${change}:${at}`,
    category: 'github',
    at,
    tone: news.tone,
    icon: Plug,
    title: news.title,
    detail: change === 'failing' ? installation.last_error || undefined : undefined,
    target: {
      label: installation.target ?? shortId(installation.id),
      href: '/installations',
    },
  };
}

/**
 * A delivery Zoomies would not take. An accepted one is the system
 * working, and there are thousands of them.
 */
export function deliveryEntry(delivery: WebhookDelivery): FeedEntry | null {
  if (delivery.status !== 'rejected' && delivery.status !== 'error') return null;
  const status = deliveryStatus(delivery.status);
  const event = [delivery.event, delivery.action].filter(Boolean).join('.');
  return {
    id: `webhook:${delivery.id ?? delivery.delivery_id ?? now()}`,
    category: 'github',
    at: delivery.received_at ?? now(),
    tone: status.tone,
    icon: status.icon,
    title:
      delivery.status === 'rejected'
        ? 'A webhook delivery was rejected'
        : 'A webhook delivery could not be handled',
    detail: delivery.error || status.hint,
    target: {
      label: event || delivery.repo || 'delivery',
      href: '/installations',
    },
  };
}

/* -- problems and the record ------------------------------------------------- */

export function problemEntry(problem: Problem, at: string): FeedEntry {
  const status = severityStatus(problem.severity);
  return {
    id: `problem:${problem.code}:${problem.target_id ?? ''}:${at}`,
    category: 'problems',
    at: problem.since ?? at,
    tone: status.tone,
    icon: status.icon,
    title: problem.title ?? 'A problem was raised',
    detail: problem.fix || problem.detail || undefined,
    target: { label: problem.code ?? 'problem' },
  };
}

/**
 * One recorded action. The action name is printed as it was recorded rather
 * than translated into prose: it is what the Audit page filters on and what a
 * support conversation quotes.
 */
export function auditEntry(event: AuditEvent): FeedEntry | null {
  if (!event.id || !event.action) return null;
  const actor = event.actor_name || event.actor_kind || 'somebody';
  const target =
    event.target_kind && event.target_id
      ? `${event.target_kind} ${shortId(event.target_id)}`
      : undefined;
  return {
    id: `audit:${event.id}`,
    category: 'audit',
    at: event.created_at ?? now(),
    tone: 'neutral',
    icon: ScrollText,
    title: `${actor} ran ${event.action}`,
    detail: target,
    target: {
      label: 'Audit',
      href: `/audit?action=${encodeURIComponent(event.action)}`,
    },
  };
}

/**
 * Formatting helpers. Every number an operator reads goes through one of these,
 * so "4m ago" means the same thing on every page.
 */

/**
 * What a value that is not there reads as, on every page. The formatters below
 * answer with it for a null, and a page that has no formatter to call (a tile
 * whose figure is simply not known yet) writes the same thing, so a table cell
 * and the tile above it cannot disagree about what "nothing to show" looks like.
 */
export const NO_VALUE = '--';

/* -- the shared clock ----------------------------------------------------
 * A thousand runner rows must not mean a thousand timers. One interval ticks,
 * and every RelativeTime on screen recomputes from it.
 * --------------------------------------------------------------------- */

type Tick = (now: number) => void;

const tickers = new Set<Tick>();
let clock: ReturnType<typeof setInterval> | null = null;

/** How often relative times refresh. Ten seconds keeps "just now" honest. */
export const CLOCK_INTERVAL_MS = 10_000;

function fire(): void {
  const now = Date.now();
  for (const fn of tickers) fn(now);
}

/**
 * Subscribe to the shared clock. Returns the unsubscribe function; the last
 * unsubscriber stops the interval, so an idle page costs nothing.
 */
export function onClockTick(fn: Tick): () => void {
  tickers.add(fn);
  if (clock === null && typeof window !== 'undefined') {
    clock = setInterval(fire, CLOCK_INTERVAL_MS);
    document.addEventListener('visibilitychange', onVisible);
  }
  return () => {
    tickers.delete(fn);
    if (tickers.size === 0 && clock !== null) {
      clearInterval(clock);
      clock = null;
      document.removeEventListener('visibilitychange', onVisible);
    }
  };
}

function onVisible(): void {
  // A backgrounded tab throttles timers, so catch up the moment it returns.
  if (document.visibilityState === 'visible') fire();
}

/* -- time ---------------------------------------------------------------- */

export type TimeInput = string | number | Date | null | undefined;

/** Milliseconds since the epoch, or null when there is no usable value. */
export function toMillis(value: TimeInput): number | null {
  if (value === null || value === undefined || value === '') return null;
  const ms = value instanceof Date ? value.getTime() : new Date(value).getTime();
  return Number.isNaN(ms) ? null : ms;
}

/** The ISO 8601 form, which is what a timestamp's tooltip shows. */
export function toIso(value: TimeInput): string {
  const ms = toMillis(value);
  return ms === null ? '' : new Date(ms).toISOString();
}

const ABSOLUTE = new Intl.DateTimeFormat(undefined, {
  dateStyle: 'medium',
  timeStyle: 'medium',
});

/** The local wall-clock rendering, for detail panels and tooltips. */
export function formatAbsolute(value: TimeInput): string {
  const ms = toMillis(value);
  return ms === null ? NO_VALUE : ABSOLUTE.format(ms);
}

/** Both forms, for a `title` attribute: local time first, then the exact ISO value. */
export function formatTimestampTitle(value: TimeInput): string {
  const ms = toMillis(value);
  if (ms === null) return 'No timestamp recorded';
  return `${ABSOLUTE.format(ms)} (${new Date(ms).toISOString()})`;
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * "4m ago", "in 2h", "just now". Past and future both read naturally, which
 * matters because token expiry and job queue times sit in the same table.
 */
export function relativeTime(value: TimeInput, now: number = Date.now()): string {
  const ms = toMillis(value);
  if (ms === null) return NO_VALUE;
  const delta = now - ms;
  const abs = Math.abs(delta);
  const past = delta >= 0;

  if (abs < 10_000) return 'just now';
  const unit =
    abs < MINUTE
      ? `${Math.round(abs / 1000)}s`
      : abs < HOUR
        ? `${Math.round(abs / MINUTE)}m`
        : abs < DAY
          ? `${Math.round(abs / HOUR)}h`
          : abs < 7 * DAY
            ? `${Math.round(abs / DAY)}d`
            : null;
  if (unit === null) return formatAbsolute(ms);
  return past ? `${unit} ago` : `in ${unit}`;
}

/* -- durations ------------------------------------------------------------ */

function pad(n: number): string {
  return n < 10 ? `0${n}` : String(n);
}

/**
 * A humanised duration: "820ms", "4.2s", "1m 04s", "3h 12m", "2d 04h".
 * Two units at most -- more than that is noise in a table cell.
 */
export function formatDuration(ms: number | null | undefined): string {
  if (ms === null || ms === undefined || Number.isNaN(ms)) return NO_VALUE;
  const value = Math.max(0, Math.round(ms));
  if (value < 1000) return `${value}ms`;
  const seconds = value / 1000;
  if (seconds < 10) return `${seconds.toFixed(1)}s`;
  if (seconds < 60) return `${Math.round(seconds)}s`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ${pad(Math.floor(seconds % 60))}s`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ${pad(minutes % 60)}m`;
  const days = Math.floor(hours / 24);
  return `${days}d ${pad(hours % 24)}h`;
}

/** How long ago something started, as a duration rather than a relative time. */
export function elapsedSince(value: TimeInput, now: number = Date.now()): string {
  const ms = toMillis(value);
  return ms === null ? NO_VALUE : formatDuration(now - ms);
}

const GO_UNITS: Record<string, number> = {
  ns: 1e-6,
  us: 1e-3,
  µs: 1e-3,
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
};

/**
 * Parse a Go duration string ("5m", "1h30s") into milliseconds. Returns null
 * for anything it does not understand, so a form can report it as invalid.
 */
export function parseGoDuration(input: string | null | undefined): number | null {
  if (!input) return null;
  const text = input.trim();
  if (text === '0') return 0;
  const pattern = /(\d+(?:\.\d+)?)(ns|us|µs|ms|s|m|h)/g;
  let total = 0;
  let matched = 0;
  let consumed = 0;
  for (const m of text.matchAll(pattern)) {
    const amount = Number(m[1]);
    const unit = GO_UNITS[m[2] ?? ''];
    if (unit === undefined || Number.isNaN(amount)) return null;
    total += amount * unit;
    matched += 1;
    consumed += m[0].length;
  }
  if (matched === 0 || consumed !== text.length) return null;
  return total;
}

/** Render milliseconds as the Go duration string the API expects. */
export function toGoDuration(ms: number): string {
  if (ms <= 0) return '0s';
  const parts: string[] = [];
  let rest = Math.round(ms);
  const hours = Math.floor(rest / 3_600_000);
  rest -= hours * 3_600_000;
  const minutes = Math.floor(rest / 60_000);
  rest -= minutes * 60_000;
  const seconds = rest / 1000;
  if (hours) parts.push(`${hours}h`);
  if (minutes) parts.push(`${minutes}m`);
  if (seconds) parts.push(`${Number(seconds.toFixed(3))}s`);
  return parts.join('') || '0s';
}

/** A Go duration string, spelled out for a person: "5m" becomes "5m". */
export function formatGoDuration(input: string | null | undefined): string {
  const ms = parseGoDuration(input);
  return ms === null ? (input ?? NO_VALUE) : formatDuration(ms);
}

/**
 * A Go duration, as a period a sentence can name: "24h0m0s" becomes
 * "24 hours".
 *
 * The API says what window a figure covers and the page used to claim one of
 * its own in prose, which is how the Overview came to promise waits "over the
 * last hour" for figures the controller computes over a day. Returns an empty
 * string for anything it cannot read, so a caller leaves the claim out
 * altogether rather than making a worse one.
 */
export function describeWindow(input: string | null | undefined): string {
  const ms = parseGoDuration(input);
  if (ms === null || ms <= 0) return '';
  const units: [number, string, number][] = [
    // A day only once there is more than one of them: the default window is a
    // day, and "the last 24 hours" is how an operator says it -- "the last 1
    // day" is how nothing says it.
    [86_400_000, 'day', 2],
    [3_600_000, 'hour', 1],
    [60_000, 'minute', 1],
    [1000, 'second', 1],
  ];
  for (const [size, name, least] of units) {
    if (ms < size * least) continue;
    // Only whole units read as a period; 90 minutes is not "1 hour", and
    // rounding it to one would be the same lie in a smaller font.
    if (ms % size !== 0) continue;
    return pluralise(ms / size, name);
  }
  return formatDuration(ms);
}

/* -- numbers -------------------------------------------------------------- */

const NUMBER = new Intl.NumberFormat();

/** Grouped digits. Pair with the `.tabular` class so columns line up. */
export function formatNumber(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  return NUMBER.format(value);
}

/** Compact digits for tiles: 12.4k, 3.1M. */
export function formatCompact(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  if (Math.abs(value) < 10_000) return NUMBER.format(value);
  if (Math.abs(value) < 1_000_000) return `${(value / 1000).toFixed(1)}k`;
  return `${(value / 1_000_000).toFixed(1)}M`;
}

const BYTE_UNITS = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'] as const;

/** Binary-scaled bytes: 1536 becomes "1.5 KB". */
export function formatBytes(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  let n = value;
  let unit = 0;
  while (Math.abs(n) >= 1024 && unit < BYTE_UNITS.length - 1) {
    n /= 1024;
    unit += 1;
  }
  const digits = unit === 0 ? 0 : Math.abs(n) < 10 ? 1 : 0;
  return `${n.toFixed(digits)} ${BYTE_UNITS[unit]}`;
}

/** Megabytes as the API reports them (`memory_mb`). */
export function formatMegabytes(value: number | null | undefined): string {
  if (value === null || value === undefined) return NO_VALUE;
  return formatBytes(value * 1024 * 1024);
}

/**
 * A ratio in the range 0..1 as a percentage. Utilisation arrives as a double,
 * so this is what every bar and tile uses.
 */
export function formatPercent(value: number | null | undefined, digits = 0): string {
  if (value === null || value === undefined || Number.isNaN(value)) return NO_VALUE;
  return `${(value * 100).toFixed(digits)}%`;
}

/** Clamp to 0..1, for anything that drives a width. */
export function ratio(value: number | null | undefined): number {
  if (value === null || value === undefined || Number.isNaN(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

/* -- words ---------------------------------------------------------------- */

/** "1 runner", "3 runners". Pass the plural when it is irregular. */
export function pluralise(count: number, one: string, many = `${one}s`): string {
  return `${formatNumber(count)} ${count === 1 ? one : many}`;
}

/** A list read aloud: "a, b and c". British serial comma rules, so none. */
export function joinWords(items: readonly string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] ?? '';
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/** Shorten an identifier for a dense cell, keeping the prefix that means something. */
export function shortId(id: string | null | undefined, keep = 8): string {
  if (!id) return NO_VALUE;
  const underscore = id.indexOf('_');
  if (underscore > 0 && id.length > underscore + keep + 1) {
    return `${id.slice(0, underscore + 1)}${id.slice(underscore + 1, underscore + 1 + keep)}…`;
  }
  return id.length > keep * 2 ? `${id.slice(0, keep * 2)}…` : id;
}

/** `owner/repo` split for two-line rendering in a cell. */
export function splitRepo(repo: string | null | undefined): { owner: string; name: string } {
  const [owner = '', name = ''] = (repo ?? '').split('/');
  return { owner, name };
}

/**
 * What to suggest for a host's capacity and reserve, from what the machine is
 * and what a runner in this fleet asks for.
 *
 * Pure, and imported by a unit test. The numbers are a starting point an
 * operator can see the reasoning of, not a promise: the scheduler still
 * places by fit, and a host above its recommendation is one where jobs can
 * wait on slots that read as free.
 */
import type { Pool } from '../api/types';

/** The machine, as the host reported it. Zero means it has not said. */
export interface HostShape {
  cpus: number;
  memoryMb: number;
}

/** What one runner asks for: the largest ask across the enabled pools. */
export interface RunnerAsk {
  cpus: number;
  memoryMb: number;
  /** Where the ask came from, for the sentence under the slider. */
  source: 'pools' | 'default';
  /**
   * The pool whose figures won, when one did. It is the other half of the
   * sentence: an operator told a runner here asks for eight cores can go and
   * look at the pool that says so.
   */
  pool?: string;
  /**
   * Whether the ask was doubled because a slot is a pair. It is the figure
   * that needs explaining: an operator who typed 2 cores on the pool and
   * reads 4 here has to be told which of the two is wrong, and neither is.
   */
  pair: boolean;
}

/**
 * The default a pool created today gets, where the fleet has not said.
 *
 * It is the same pair of figures `runners.default_cpus` and
 * `runners.default_memory_mb` start at, and it stands in only until those have
 * been read -- on the first paint, or where the call for them failed. Passing
 * the fleet's own is what keeps this page's recommendation and the pool
 * wizard's sliders describing the same fleet.
 */
export const DEFAULT_ASK: RunnerAsk = { cpus: 2, memoryMb: 4096, source: 'default', pair: false };

export function runnerAsk(
  pools: readonly Pool[],
  fleetDefault?: { cpus?: number; memory_mb?: number } | null,
): RunnerAsk {
  const fallbackCPUs =
    fleetDefault?.cpus && fleetDefault.cpus > 0 ? fleetDefault.cpus : DEFAULT_ASK.cpus;
  const fallbackMemoryMb =
    fleetDefault?.memory_mb && fleetDefault.memory_mb > 0
      ? fleetDefault.memory_mb
      : DEFAULT_ASK.memoryMb;
  let cpus = 0;
  let memoryMb = 0;
  let winner = '';
  // Whether the figure that won is a pair's, which is the only thing the
  // sentence has to explain. A dind pool that does not win says nothing here:
  // this function has no host in hand, so it cannot know whether that pool
  // places on the machine being adjusted, and inflating every host in the
  // fleet for one pool would be a recommendation nobody could act on.
  // `host.overprovisioned` is the half that does know, host by host.
  let cpuPair = false;
  let memoryPair = false;
  let anyPair = false;
  for (const pool of pools) {
    if (pool.enabled !== true) continue;
    // A docker-in-docker slot is two containers where the pool typed its own
    // limits: the daemon runs the build, so it is given what the job was
    // promised and the machine carries both. A pool that leaves its size to
    // the host puts the pair in one slot between them and asks for no more
    // than anybody else.
    const typed = (pool.resources?.cpus ?? 0) > 0 || (pool.resources?.memory_mb ?? 0) > 0;
    const containers = pool.docker_mode === 'dind' && typed ? 2 : 1;
    anyPair = anyPair || containers > 1;
    const wantCpus = (pool.resources?.cpus ?? 0) * containers;
    const wantMemoryMb = (pool.resources?.memory_mb ?? 0) * containers;
    if (wantCpus > cpus) {
      cpus = wantCpus;
      cpuPair = containers > 1;
      winner = pool.name ?? winner;
    }
    if (wantMemoryMb > memoryMb) {
      memoryMb = wantMemoryMb;
      memoryPair = containers > 1;
      if (winner === '') winner = pool.name ?? '';
    }
  }
  if (cpus <= 0 && memoryMb <= 0) {
    // Nothing was set anywhere, so the fleet's default answers -- twice over
    // only where a pool typed a daemon's worth beside it, which nothing here
    // did. A pool that leaves its size to the host puts its runner and its
    // daemon in one slot, so its ask is one runner's like everybody else's.
    if (!anyPair)
      return { cpus: fallbackCPUs, memoryMb: fallbackMemoryMb, source: 'default', pair: false };
    return {
      cpus: fallbackCPUs * 2,
      memoryMb: fallbackMemoryMb * 2,
      source: 'default',
      pair: true,
    };
  }
  const ask: RunnerAsk = {
    cpus: cpus > 0 ? cpus : fallbackCPUs,
    memoryMb: memoryMb > 0 ? memoryMb : fallbackMemoryMb,
    source: 'pools',
    pair: cpuPair || memoryPair,
  };
  if (winner !== '') ask.pool = winner;
  return ask;
}

/**
 * Cores to hold back for the machine itself: one on anything up to sixteen,
 * then one more for every sixteen. Never the whole machine.
 */
export function recommendedReserveCores(cpus: number): number {
  if (cpus <= 1) return 0;
  return Math.min(cpus - 1, Math.max(1, Math.ceil(cpus / 16)));
}

/**
 * Memory to hold back: a tenth of the machine, between one and eight
 * gigabytes, on the nearest notch of the slider -- so the recommendation is
 * somewhere the slider can actually stop.
 */
export function recommendedReserveMemoryMb(memoryMb: number): number {
  if (memoryMb <= 1024) return 0;
  const tenth = Math.min(memoryMb - 512, Math.max(1024, Math.min(8192, memoryMb * 0.1)));
  let best = 0;
  for (const n of memoryNotches(memoryMb)) {
    if (Math.abs(n - tenth) <= Math.abs(best - tenth)) best = n;
  }
  return best;
}

/**
 * Disk to hold back for the machine: a tenth of the filesystem, between the
 * scheduler's own two-gigabyte floor and sixty-four gigabytes, on the nearest
 * notch of the slider. Runner checkouts and caches land here, so the reserve
 * is what stops a full disk turning into a job that fails part-way through.
 */
export function recommendedReserveDiskMb(diskTotalMb: number): number {
  if (diskTotalMb <= 4096) return 0;
  const tenth = Math.min(diskTotalMb - 2048, Math.max(2048, Math.min(65536, diskTotalMb * 0.1)));
  let best = 0;
  for (const n of diskNotches(diskTotalMb)) {
    if (Math.abs(n - tenth) <= Math.abs(best - tenth)) best = n;
  }
  return best;
}

/** How many runners of this ask fit on what is left after the reserve. At least one. */
export function recommendedCapacity(
  host: HostShape,
  reserveCores: number,
  reserveMb: number,
  ask: RunnerAsk,
): number {
  const byCpu = host.cpus > 0 ? Math.floor((host.cpus - reserveCores) / ask.cpus) : Infinity;
  const byMemory =
    host.memoryMb > 0 ? Math.floor((host.memoryMb - reserveMb) / ask.memoryMb) : Infinity;
  const fit = Math.min(byCpu, byMemory);
  return Number.isFinite(fit) ? Math.max(1, fit) : 0;
}

/** The notches of the capacity slider: every count up to a ceiling worth seeing. */
export function capacityCeiling(host: HostShape, recommended: number, current: number): number {
  const sized = host.cpus > 0 ? Math.max(host.cpus, recommended * 2) : Math.max(8, current * 2);
  return Math.max(4, sized, current);
}

/** The notches of the memory slider: half a gigabyte, then doubling-ish steps, then gigabytes. */
export function memoryNotches(memoryMb: number): number[] {
  if (memoryMb <= 512) return [0];
  const top = memoryMb - 512;
  const out = [0];
  const steps = [512, 1024, 2048, 3072, 4096, 6144, 8192, 12288, 16384, 24576, 32768];
  for (const s of steps) if (s <= top) out.push(s);
  let next = 49152;
  while (next <= top) {
    out.push(next);
    next += 16384;
  }
  return out;
}

/**
 * The notches of the disk slider: two gigabytes -- the scheduler's floor --
 * and then doublings. A disk is two orders of magnitude larger than memory,
 * and a slider that stepped it in gigabytes would be a thousand notches long.
 */
export function diskNotches(diskTotalMb: number): number[] {
  if (diskTotalMb <= 4096) return [0];
  const top = diskTotalMb - 2048;
  const out = [0];
  for (let step = 2048; step <= top; step *= 2) out.push(step);
  return out;
}

/** "4 GB", "512 MB". */
export function memoryLabel(mb: number): string {
  if (mb === 0) return 'none';
  if (mb < 1024) return `${mb} MB`;
  return `${(mb / 1024).toLocaleString(undefined, { maximumFractionDigits: 1 })} GB`;
}

export interface Overcommit {
  /** Cores the runners would ask for, over what is placeable. Zero when they fit. */
  cpus: number;
  memoryMb: number;
}

/** What `capacity` runners of the ask would take beyond the room the reserve leaves. */
export function overcommit(
  host: HostShape,
  capacity: number,
  reserveCores: number,
  reserveMb: number,
  ask: RunnerAsk,
): Overcommit {
  return {
    cpus: host.cpus > 0 ? Math.max(0, capacity * ask.cpus - (host.cpus - reserveCores)) : 0,
    memoryMb:
      host.memoryMb > 0 ? Math.max(0, capacity * ask.memoryMb - (host.memoryMb - reserveMb)) : 0,
  };
}

/**
 * The activity matrix's arithmetic: which square an interval is, how it is
 * painted, what its label says, and how a job arriving over the stream lands
 * in it.
 *
 * Pure functions with no DOM and no clock of their own, so the calendar can be
 * tested in Node and so the Overview and the Usage page -- which draw the same
 * squares from the same usage buckets -- cannot drift in what a square means.
 */
import type { Job, UsageRow } from '../api/types';
import { formatNumber, pluralise, toMillis } from '../format';
import { outcomeOf } from '../outcomes';

export { outcomeOf };

/** One interval of the usage history, exactly as `GET /usage` reports it. */
export type ActivityBucket = NonNullable<UsageRow['history']>[number];

/**
 * The API's interval widths: an hour, a day, and every whole number of hours a
 * day divides into. The route's own rule is hourly up to 48 hours and daily
 * beyond; the rest are asked for, by the ranges that cut a day into squares.
 */
export type Interval = 'hour' | '2h' | '3h' | '4h' | '6h' | '8h' | '12h' | 'day';

/**
 * What the squares are coloured by. Outcomes is the default and the one the
 * Overview opens on; the others recolour the same squares by a different
 * figure, so a queue that backs up every Monday or a pool that hits its
 * ceiling every night is a shape rather than a table.
 */
export type ActivityMode = 'outcomes' | 'queue' | 'runtime' | 'capacity';

export const MODES: ReadonlyArray<{ value: ActivityMode; label: string }> = [
  { value: 'outcomes', label: 'Job outcomes' },
  { value: 'queue', label: 'Queued jobs' },
  { value: 'runtime', label: 'Runner time' },
  { value: 'capacity', label: 'Capacity reached' },
];

/** Four steps of colour above "nothing", as a contribution graph has. */
export type Level = 0 | 1 | 2 | 3 | 4;

/**
 * What kind of square this is. Colour never carries it alone: a failing square
 * has a hole in it, a waiting square is hollow, and an unobserved one is
 * dashed, so the calendar reads in greyscale and to anyone who cannot tell
 * the green from the red.
 */
export type CellKind = 'quiet' | 'healthy' | 'failing' | 'waiting' | 'active' | 'unsampled';

/** The status hues a square may use. Fixed meanings; see docs/ui-guidelines.md. */
export type CellTone = 'idle' | 'danger' | 'pending' | 'busy';

export interface CellPaint {
  kind: CellKind;
  tone: CellTone;
  level: Level;
}

export const HOUR_MS = 3_600_000;
export const DAY_MS = 24 * HOUR_MS;

/** The width of one bucket, in milliseconds. */
export function intervalWidth(interval: Interval): number {
  if (interval === 'day') return DAY_MS;
  if (interval === 'hour') return HOUR_MS;
  return parseInt(interval, 10) * HOUR_MS;
}

/** How many buckets of this width a day is cut into: one, three for eight hours, 24 for an hour. */
export function slicesPerDay(interval: Interval): number {
  return Math.round(DAY_MS / intervalWidth(interval));
}

/**
 * The most buckets narrower than a day the API will cut a row into: a
 * fortnight of hours, or 56 days of four hours, or 112 of eight.
 */
export const MAX_SUB_DAILY_BUCKETS = 14 * 24;

/**
 * The square a window of this length is drawn in: the narrowest of the
 * widths the Overview's ranges use that the API will cut the whole window
 * into. A week is the punch card of hours, a month six squares a day, a
 * quarter three, and anything longer whole days -- so a window chosen on the
 * Usage page is drawn the way the Overview draws one as long.
 *
 * Measured in elapsed time, which is what the API bounds: a fortnight that
 * takes in a clock change is an hour longer than 336 hours, and gets
 * four-hour squares rather than a refusal.
 */
export function matrixInterval(span: number): Interval {
  for (const interval of ['hour', '4h', '8h'] as const) {
    if (span <= MAX_SUB_DAILY_BUCKETS * intervalWidth(interval)) return interval;
  }
  return 'day';
}

export function emptyBucket(from: string): ActivityBucket {
  return {
    from,
    queued: 0,
    started: 0,
    succeeded: 0,
    failed: 0,
    cancelled: 0,
    unknown: 0,
    execution_seconds: 0,
    allocated_seconds: 0,
    capacity_samples: 0,
    capacity_reached: 0,
  };
}

/** Add one bucket's figures into another, in place. */
export function addInto(target: ActivityBucket, source: ActivityBucket): void {
  target.queued += source.queued;
  target.started += source.started;
  target.succeeded += source.succeeded;
  target.failed += source.failed;
  target.cancelled += source.cancelled;
  target.unknown += source.unknown;
  target.execution_seconds += source.execution_seconds;
  target.allocated_seconds += source.allocated_seconds;
  target.capacity_samples += source.capacity_samples;
  target.capacity_reached += source.capacity_reached;
}

/** How many jobs finished in a bucket, however they finished. */
export function completedIn(b: ActivityBucket): number {
  return b.succeeded + b.failed + b.cancelled + b.unknown;
}

/**
 * Every row's history summed into one series, oldest first. The report is
 * grouped -- by pool, by repository -- and the matrix is about the fleet, so
 * the groups are added back together here.
 */
export function mergeHistories(rows: readonly UsageRow[]): ActivityBucket[] {
  const map = new Map<number, ActivityBucket>();
  for (const row of rows) {
    for (const b of row.history ?? []) {
      const at = toMillis(b.from);
      if (at === null) continue;
      const existing = map.get(at);
      if (existing) addInto(existing, b);
      else map.set(at, { ...b });
    }
  }
  return [...map.entries()].sort((a, b) => a[0] - b[0]).map(([, b]) => b);
}

/**
 * A complete series for a window: one bucket per interval from `from`, with
 * whatever the API reported laid over it.
 *
 * The API leaves out a group with nothing to say and a window with no jobs at
 * all comes back with no history whatsoever, so the empty squares of a quiet
 * fortnight have to be made here rather than read.
 */
export function fillWindow(
  buckets: readonly ActivityBucket[],
  from: Date,
  count: number,
  interval: Interval,
): ActivityBucket[] {
  const width = intervalWidth(interval);
  const start = from.getTime();
  const out: ActivityBucket[] = [];
  for (let i = 0; i < count; i++) out.push(emptyBucket(new Date(start + i * width).toISOString()));
  for (const b of buckets) {
    const at = toMillis(b.from);
    if (at === null) continue;
    const i = Math.floor((at - start) / width);
    const target = out[i];
    if (target) addInto(target, b);
  }
  return out;
}

/** Midnight at the start of `at`'s local day. */
export function startOfLocalDay(at: Date): Date {
  return new Date(at.getFullYear(), at.getMonth(), at.getDate());
}

/** The same local time, `days` calendar days later. Survives daylight saving. */
export function addDays(at: Date, days: number): Date {
  return new Date(at.getFullYear(), at.getMonth(), at.getDate() + days, at.getHours());
}

/** The calendar date, `YYYY-MM-DD`, in local time: what the Jobs and Usage pages filter by. */
export function localDate(at: Date): string {
  const two = (n: number) => String(n).padStart(2, '0');
  return `${at.getFullYear()}-${two(at.getMonth() + 1)}-${two(at.getDate())}`;
}

/** Monday is 0. A calendar that starts on Sunday is a calendar for shops. */
export function weekday(at: Date): number {
  return (at.getDay() + 6) % 7;
}

export interface CalendarWindow {
  /** Midnight at the start of the first Monday, local time. */
  from: Date;
  /** Exactly `days` elapsed days after `from`, so every bucket has a day. */
  to: Date;
  days: number;
}

/**
 * The window a calendar of `weeks` columns ending today covers: from the
 * Monday `weeks - 1` weeks ago, through the end of today.
 *
 * `to` is elapsed rather than calendar time on purpose. The API cuts elapsed
 * 24-hour buckets from `from`, so asking for a `to` that is a whole number of
 * them is what keeps bucket `i` and calendar day `i` the same thing across a
 * daylight-saving change -- an hour adrift within the day, never a day out.
 */
export function calendarWindow(weeks: number, now: Date = new Date()): CalendarWindow {
  const today = startOfLocalDay(now);
  const monday = addDays(today, -weekday(today));
  const from = addDays(monday, -7 * (weeks - 1));
  const tomorrow = addDays(today, 1);
  const days = Math.round((tomorrow.getTime() - from.getTime()) / DAY_MS);
  return { from, to: new Date(from.getTime() + days * DAY_MS), days };
}

export interface RangeWindow {
  /** Midnight at the start of the first day, local time. */
  from: Date;
  /** `count` whole buckets after `from`, elapsed rather than calendar time. */
  to: Date;
  /** How many buckets the window is. */
  count: number;
  interval: Interval;
}

/**
 * The window of the last `days` days, today included, cut into buckets of
 * the given width. A day of hours is a row of twenty-four squares; a week of
 * them is the punch card that shows when the fleet is busy; a month of
 * four-hour buckets is a calendar with six squares to the day.
 */
export function rangeWindow(days: number, interval: Interval, now: Date = new Date()): RangeWindow {
  const from = addDays(startOfLocalDay(now), -(days - 1));
  const count = days * slicesPerDay(interval);
  return { from, to: new Date(from.getTime() + count * intervalWidth(interval)), count, interval };
}

export interface CalendarCell {
  /** Index into the series this cell was cut from. */
  index: number;
  /** When the cell begins on the local clock: the calendar day, or the hour a slice of it starts at. */
  date: Date;
  bucket: ActivityBucket;
}

export interface CalendarColumn {
  /** The month's short name, on the column where a month begins. */
  label: string | null;
  /**
   * Seven days, Monday first, each `slices` cells long and in order through
   * the day -- so weekday `r`'s slice `k` is `cells[r * slices + k]`. Null
   * where the window has no such day.
   */
  cells: Array<CalendarCell | null>;
}

const MONTH = {
  short: new Intl.DateTimeFormat(undefined, { month: 'short' }),
  narrow: new Intl.DateTimeFormat(undefined, { month: 'narrow' }),
};

/**
 * Buckets laid out as a contribution graph: a column per week, a row per
 * weekday. `first` is the local day of bucket 0.
 *
 * A day is `slices` buckets, one after another -- one for daily buckets,
 * three for eight-hour ones -- so bucket `i` is slice `i % slices` of day
 * `i / slices`, and each day of the week holds that many cells side by side.
 * A range that could only draw a month as five columns of squares draws it
 * as five columns of six instead, and the band has something to fill itself
 * with that is not white.
 *
 * Placed by index rather than by the time a bucket starts, which is what the
 * window above guarantees: the API cuts elapsed buckets from `from`, so after
 * a daylight-saving change a slice is an hour adrift of the clock it is
 * labelled with -- an hour out within the day, never a day out.
 */
export function calendar(
  buckets: readonly ActivityBucket[],
  first: Date,
  slices = 1,
): CalendarColumn[] {
  const columns: CalendarColumn[] = [];
  const offset = weekday(first);
  const hours = 24 / slices;
  buckets.forEach((bucket, index) => {
    const day = Math.floor(index / slices);
    const slice = index % slices;
    const column = Math.floor((day + offset) / 7);
    const row = (day + offset) % 7;
    let col = columns[column];
    if (!col) {
      col = { label: null, cells: Array.from({ length: 7 * slices }, () => null) };
      columns[column] = col;
    }
    const date = addDays(first, day);
    if (slice > 0) date.setHours(slice * hours);
    col.cells[row * slices + slice] = { index, date, bucket };
  });
  monthLabels(columns).forEach((label, c) => {
    columns[c]!.label = label;
  });
  return columns;
}

/**
 * A month's name above the week it begins in, for whichever columns are on
 * screen. Two adjacent labels would overlap at this width, so the earlier
 * gives way, which is the first column when the window happens to start in
 * the last days of a month.
 *
 * A year on a phone is columns a few pixels across, and "May" and "Jun" four
 * of them apart run into each other; there the caller asks for the one-letter
 * names instead, which the row of them still reads as a year.
 */
export function monthLabels(
  columns: readonly CalendarColumn[],
  width: 'short' | 'narrow' = 'short',
): Array<string | null> {
  const labels: Array<string | null> = columns.map(() => null);
  let previous = -1;
  columns.forEach((col, c) => {
    const start = col.cells.find((cell) => cell !== null);
    if (!start) return;
    const month = start.date.getMonth() + 12 * start.date.getFullYear();
    if (month !== previous) labels[c] = MONTH[width].format(start.date);
    previous = month;
  });
  for (let c = 0; c + 1 < labels.length; c++) {
    if (labels[c] && labels[c + 1]) labels[c] = null;
  }
  return labels;
}

export interface HourRow {
  /** Midnight of the local day this row is. */
  date: Date;
  /** Twenty-four slots; null where the window has no such hour. */
  cells: Array<CalendarCell | null>;
}

/**
 * Hourly buckets laid out with a row per local day and a column per hour.
 * Each bucket is placed by the local time it starts at, so a daylight-saving
 * change puts an hour in the slot it was actually lived in.
 */
export function hourGrid(buckets: readonly ActivityBucket[]): HourRow[] {
  const rows = new Map<number, HourRow>();
  buckets.forEach((bucket, index) => {
    const at = toMillis(bucket.from);
    if (at === null) return;
    const date = new Date(at);
    const day = startOfLocalDay(date);
    let row = rows.get(day.getTime());
    if (!row) {
      row = { date: day, cells: Array.from({ length: 24 }, () => null) };
      rows.set(day.getTime(), row);
    }
    const hour = date.getHours();
    const existing = row.cells[hour];
    // The hour a clock change repeats is two buckets in one slot.
    if (existing) addInto(existing.bucket, bucket);
    else row.cells[hour] = { index, date, bucket: { ...bucket } };
  });
  return [...rows.values()].sort((a, b) => a.date.getTime() - b.date.getTime());
}

/**
 * The darkness of a square: nothing, then quarters of the busiest square in
 * the window, as a contribution graph does it. The busiest square is always
 * the darkest, so a fleet that runs ten jobs a day and one that runs a
 * thousand both get a calendar with a full range of colour.
 */
export function level(value: number, max: number): Level {
  if (value <= 0 || max <= 0) return 0;
  return Math.min(4, Math.max(1, Math.ceil((4 * value) / max))) as Level;
}

/**
 * The share of a square's completions that failed, banded. Fixed bands rather
 * than quarters of the worst square: "half of everything failed" should look
 * the same on a good week as on a bad one.
 */
export function failureLevel(failed: number, completed: number): Level {
  if (failed <= 0) return 0;
  const share = completed > 0 ? failed / completed : 1;
  if (share < 0.1) return 1;
  if (share < 0.25) return 2;
  if (share < 0.5) return 3;
  return 4;
}

/** The share of observed pool-minutes that were blocked on capacity, banded the same way. */
export function capacityLevel(reached: number, samples: number): Level {
  if (samples <= 0 || reached <= 0) return 0;
  const share = reached / samples;
  if (share < 0.05) return 1;
  if (share < 0.25) return 2;
  if (share < 0.5) return 3;
  return 4;
}

/** The busiest square in each figure, which is what the quarters are cut from. */
export interface Scale {
  completed: number;
  queued: number;
  execution: number;
}

export function scaleOf(buckets: readonly ActivityBucket[]): Scale {
  let completed = 0;
  let queued = 0;
  let execution = 0;
  for (const b of buckets) {
    completed = Math.max(completed, completedIn(b));
    queued = Math.max(queued, b.queued);
    execution = Math.max(execution, b.execution_seconds);
  }
  return { completed, queued, execution };
}

/** How one square is painted under a mode. */
export function paint(b: ActivityBucket, mode: ActivityMode, scale: Scale): CellPaint {
  switch (mode) {
    case 'queue': {
      const l = level(b.queued, scale.queued);
      return { kind: l ? 'active' : 'quiet', tone: 'pending', level: l };
    }
    case 'runtime': {
      const l = level(b.execution_seconds, scale.execution);
      return { kind: l ? 'active' : 'quiet', tone: 'busy', level: l };
    }
    case 'capacity': {
      if (b.capacity_samples === 0) return { kind: 'unsampled', tone: 'pending', level: 0 };
      const l = capacityLevel(b.capacity_reached, b.capacity_samples);
      return { kind: l ? 'active' : 'quiet', tone: 'pending', level: l };
    }
    default: {
      const completed = completedIn(b);
      if (b.failed > 0) {
        return { kind: 'failing', tone: 'danger', level: failureLevel(b.failed, completed) };
      }
      if (completed > 0) {
        return { kind: 'healthy', tone: 'idle', level: level(completed, scale.completed) };
      }
      const waiting = Math.max(b.queued, b.started);
      if (waiting > 0) {
        return { kind: 'waiting', tone: 'pending', level: level(waiting, scale.queued) };
      }
      return { kind: 'quiet', tone: 'idle', level: 0 };
    }
  }
}

/** Whether any square in the series carries capacity telemetry at all. */
export function hasCapacity(buckets: readonly ActivityBucket[]): boolean {
  return buckets.some((b) => b.capacity_samples > 0);
}

/* -- words ---------------------------------------------------------------- */

const DAY_LONG = new Intl.DateTimeFormat(undefined, {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});
const DAY_SHORT = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' });
const DAY_WEEKDAY = new Intl.DateTimeFormat(undefined, {
  weekday: 'short',
  day: 'numeric',
  month: 'short',
});
const CLOCK = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });

/**
 * "Tuesday 9 September 2026", "9 Sep, 14:00 to 15:00", or "Tue 9 Sep, 08:00
 * to 16:00". A slice of a day names its weekday, because in the calendar it
 * sits in that weekday's row; an hour is a week at most and its row says the
 * date.
 */
export function intervalName(at: Date, interval: Interval): string {
  if (interval === 'day') return DAY_LONG.format(at);
  if (interval === 'hour') {
    const end = new Date(at.getTime() + HOUR_MS);
    return `${DAY_SHORT.format(at)}, ${CLOCK.format(at)} to ${CLOCK.format(end)}`;
  }
  // The wall clock rather than elapsed time: a slice is the stretch of the
  // day its square stands for, so the last one ends at midnight even on the
  // day the clocks change.
  const end = new Date(at);
  end.setHours(at.getHours() + intervalWidth(interval) / HOUR_MS);
  return `${DAY_WEEKDAY.format(at)}, ${CLOCK.format(at)} to ${CLOCK.format(end)}`;
}

/**
 * What a square is, as a noun for the words around it: "the selected day",
 * "the selected hour", and for a slice of a day, "the selected hours".
 */
export function intervalNoun(interval: Interval): 'day' | 'hour' | 'hours' {
  if (interval === 'day') return 'day';
  return interval === 'hour' ? 'hour' : 'hours';
}

/** Seconds as the hours an invoice is written in: "6.4 h". */
export function hours(seconds: number): string {
  return `${(seconds / 3600).toFixed(seconds >= 36_000 ? 0 : 1)} h`;
}

/** The one line a square is summed up in: "38 jobs finished, 2 failed". */
export function headline(b: ActivityBucket): string {
  const completed = completedIn(b);
  if (completed > 0) {
    const finished = `${pluralise(completed, 'job')} finished`;
    return b.failed > 0 ? `${finished}, ${formatNumber(b.failed)} failed` : finished;
  }
  if (b.queued > 0 || b.started > 0) {
    return `${pluralise(Math.max(b.queued, b.started), 'job')} queued, none finished`;
  }
  return 'No jobs';
}

/**
 * Everything a square knows, as one sentence. It is the square's accessible
 * name and the text a screen reader gets, so nothing may live only in the
 * tooltip.
 */
export function describe(b: ActivityBucket, at: Date, interval: Interval): string {
  const parts = [
    `${headline(b)}: ${b.succeeded} succeeded, ${b.failed} failed, ${b.cancelled} cancelled or skipped, ${b.unknown} unknown`,
    `${b.queued} queued, ${b.started} started`,
  ];
  if (b.execution_seconds > 0) parts.push(`${hours(b.execution_seconds)} executing`);
  if (b.capacity_samples > 0) {
    parts.push(
      `${formatNumber(b.capacity_reached)} of ${formatNumber(b.capacity_samples)} observed pool-minutes at capacity`,
    );
  }
  return `${intervalName(at, interval)}. ${parts.join('; ')}.`;
}

/** The window's totals, for the panel's header. */
export interface Summary {
  completed: number;
  succeeded: number;
  failed: number;
  cancelled: number;
  unknown: number;
  queued: number;
  execution_seconds: number;
  /** Intervals with any activity at all. */
  active: number;
}

export function summarise(buckets: readonly ActivityBucket[]): Summary {
  const s: Summary = {
    completed: 0,
    succeeded: 0,
    failed: 0,
    cancelled: 0,
    unknown: 0,
    queued: 0,
    execution_seconds: 0,
    active: 0,
  };
  for (const b of buckets) {
    s.succeeded += b.succeeded;
    s.failed += b.failed;
    s.cancelled += b.cancelled;
    s.unknown += b.unknown;
    s.queued += b.queued;
    s.execution_seconds += b.execution_seconds;
    if (completedIn(b) > 0 || b.queued > 0 || b.started > 0) s.active += 1;
  }
  s.completed = s.succeeded + s.failed + s.cancelled + s.unknown;
  return s;
}

/* -- the stream ------------------------------------------------------------- */

/**
 * The jobs already counted since the last fetch, per count. A `job.updated`
 * frame arrives once per change of state and again whenever GitHub adds a
 * detail to a finished job, so without this a job that failed at step three
 * would be counted as failed twice.
 */
export interface Seen {
  queued: Set<string>;
  started: Set<string>;
  completed: Set<string>;
}

export function newSeen(): Seen {
  return { queued: new Set(), started: new Set(), completed: new Set() };
}

/** The bucket a moment falls in, or -1 when it is outside the series. */
export function bucketIndex(
  series: readonly ActivityBucket[],
  at: number,
  interval: Interval,
): number {
  const width = intervalWidth(interval);
  let lo = 0;
  let hi = series.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const start = toMillis(series[mid]?.from) ?? 0;
    if (at < start) hi = mid - 1;
    else if (at >= start + width) lo = mid + 1;
    else return mid;
  }
  return -1;
}

/**
 * Fold one job frame into the series, returning a new series when a square
 * changed and null when nothing did.
 *
 * Only moments after `since` -- when the series was fetched -- are counted:
 * anything earlier is already in it. Counts move; runner time does not, since
 * a frame cannot say how much of a job's running fell inside which hour, and
 * a guess there would be a claim on a page that is read by finance. The next
 * fetch carries the exact figure.
 */
export function foldJob(
  series: readonly ActivityBucket[],
  interval: Interval,
  job: Job,
  since: number,
  seen: Seen,
): ActivityBucket[] | null {
  if (!job.id) return null;
  const id = job.id;
  const touched = new Map<number, ActivityBucket>();
  const bucket = (at: string | null | undefined): ActivityBucket | null => {
    const ms = toMillis(at);
    if (ms === null || ms < since) return null;
    const i = bucketIndex(series, ms, interval);
    if (i < 0) return null;
    let copy = touched.get(i);
    if (!copy) {
      copy = { ...series[i]! };
      touched.set(i, copy);
    }
    return copy;
  };
  if (!seen.queued.has(id)) {
    const b = bucket(job.queued_at);
    if (b) {
      b.queued += 1;
      seen.queued.add(id);
    }
  }
  if (!seen.started.has(id) && (job.state === 'in_progress' || job.state === 'completed')) {
    const b = bucket(job.started_at);
    if (b) {
      b.started += 1;
      seen.started.add(id);
    }
  }
  if (!seen.completed.has(id) && job.state === 'completed') {
    const b = bucket(job.completed_at);
    if (b) {
      b[outcomeOf(job)] += 1;
      seen.completed.add(id);
    }
  }
  if (touched.size === 0) return null;
  return series.map((b, i) => touched.get(i) ?? b);
}

/**
 * The capacity map's arithmetic: every host figure as a share of the machine,
 * so seven different measurements can sit on one 0-100% axis and be read
 * against each other.
 *
 * Pure, and imported by a unit test, so nothing here touches the DOM or the
 * clock: the caller passes `now`.
 */
import type { Host, HostSample } from '../api/types';
import type { SeriesPoint } from './plot';

export type MetricKey =
  'cpu' | 'memory' | 'load' | 'slots' | 'cpu_committed' | 'memory_committed' | 'disk';

export interface Metric {
  key: MetricKey;
  /** The chip and the legend. */
  label: string;
  /** Beside a figure, where the chip's words would not fit: "CPU 72%". */
  short: string;
  /** What the figure is a share of, for the tooltip and assistive text. */
  hint: string;
  /**
   * How the line is drawn. Hosts take the colour, so a metric has to carry
   * its identity in the stroke, exactly as the usage chart's executing and
   * allocated lines do: `''` is solid.
   */
  dash: string;
  /** Measured by the agent, as opposed to promised by the scheduler. */
  measured: boolean;
}

/** In the order the chips appear: what is happening first, what is promised after. */
export const METRICS: readonly Metric[] = [
  {
    key: 'cpu',
    label: 'CPU used',
    short: 'CPU',
    hint: 'of the whole machine, measured',
    dash: '',
    measured: true,
  },
  {
    key: 'memory',
    label: 'Memory used',
    short: 'Memory',
    hint: 'of the whole machine, measured',
    dash: '8 4',
    measured: true,
  },
  {
    key: 'load',
    label: 'Load per CPU',
    short: 'Load',
    hint: 'one-minute load average against the CPU count; over 100% is a queue behind the cores',
    dash: '2 4',
    measured: true,
  },
  {
    key: 'slots',
    label: 'Runner slots',
    short: 'Slots',
    hint: 'runners on the host against the slots it is taking',
    dash: '12 4 2 4',
    measured: false,
  },
  {
    key: 'cpu_committed',
    label: 'CPU committed',
    short: 'CPU rsv',
    hint: 'what live runners have reserved, of what may be placed on',
    dash: '4 3',
    measured: false,
  },
  {
    key: 'memory_committed',
    label: 'Memory committed',
    short: 'Mem rsv',
    hint: 'what live runners have reserved, of what may be placed on',
    dash: '1 3',
    measured: false,
  },
  {
    key: 'disk',
    label: 'Disk used',
    short: 'Disk',
    hint: 'of the work directory filesystem',
    dash: '16 6',
    measured: false,
  },
];

export const DEFAULT_METRICS: readonly MetricKey[] = ['cpu', 'slots'];

function share(used: number | null | undefined, total: number | null | undefined): number | null {
  if (used === null || used === undefined || total === null || total === undefined) return null;
  if (!Number.isFinite(used) || !Number.isFinite(total) || total <= 0) return null;
  return Math.max(0, (100 * used) / total);
}

/**
 * One sample's figure for a metric, as a percentage, or null where the host
 * has not said. Only load may exceed 100: a load of twice the CPUs is a real
 * thing and the reason a throttle steps up, so it is not clipped away.
 */
export function metricValue(s: HostSample, metric: MetricKey): number | null {
  switch (metric) {
    case 'cpu':
      return s.cpu_percent === undefined ? null : Math.max(0, Math.min(100, s.cpu_percent));
    case 'memory':
      return s.memory_available_mb === undefined || !s.memory_mb
        ? null
        : share(s.memory_mb - s.memory_available_mb, s.memory_mb);
    case 'load':
      return s.load_average_1m === undefined ? null : share(s.load_average_1m, s.cpus);
    case 'slots':
      return share(s.active_runners, s.capacity);
    case 'cpu_committed':
      return s.reserved_cpus === undefined ? null : share(s.reserved_cpus, s.allocatable_cpus);
    case 'memory_committed':
      return s.reserved_memory_mb === undefined
        ? null
        : share(s.reserved_memory_mb, s.allocatable_memory_mb);
    case 'disk':
      return !s.disk_total_mb
        ? null
        : share(s.disk_total_mb - (s.disk_free_mb ?? 0), s.disk_total_mb);
  }
}

/** The figure as the operator would say it: "3 / 6 slots", "12.4 GB of 32 GB". */
export function metricText(s: HostSample, metric: MetricKey): string {
  const pct = metricValue(s, metric);
  if (pct === null) return 'Not measured';
  const gb = (mb: number) =>
    `${(mb / 1024).toLocaleString(undefined, { maximumFractionDigits: 1 })} GB`;
  switch (metric) {
    case 'slots':
      return `${s.active_runners} / ${s.capacity} slots`;
    case 'load':
      return `${(s.load_average_1m ?? 0).toLocaleString(undefined, { maximumFractionDigits: 1 })} on ${s.cpus ?? 0} CPUs`;
    case 'memory':
      return `${gb((s.memory_mb ?? 0) - (s.memory_available_mb ?? 0))} of ${gb(s.memory_mb ?? 0)}`;
    case 'cpu_committed':
      return `${(s.reserved_cpus ?? 0).toLocaleString(undefined, { maximumFractionDigits: 1 })} of ${(s.allocatable_cpus ?? 0).toLocaleString(undefined, { maximumFractionDigits: 1 })} CPUs`;
    case 'memory_committed':
      return `${gb(s.reserved_memory_mb ?? 0)} of ${gb(s.allocatable_memory_mb ?? 0)}`;
    case 'disk':
      return `${gb((s.disk_total_mb ?? 0) - (s.disk_free_mb ?? 0))} of ${gb(s.disk_total_mb ?? 0)}`;
    case 'cpu':
      return `${pct.toFixed(0)}%`;
  }
}

/**
 * The host as it is right now, in the shape of a sample, so the newest point
 * of every series is the same figure the card beside the chart shows. A
 * measurement that has gone stale is left out, as the controller's own
 * sampler leaves it out: a host that stopped reporting draws a gap.
 */
export function liveSample(host: Host, now: number): HostSample {
  const usage = host.usage_fresh ? host.usage : undefined;
  const reserved = host.reserved_known === true && host.resources_known === true;
  return {
    host_id: host.id ?? '',
    at: new Date(now).toISOString(),
    capacity: host.effective_capacity ?? host.capacity ?? 0,
    active_runners: host.active_runners ?? 0,
    cpu_percent: usage?.cpu_percent,
    load_average_1m: usage?.load_average_1m,
    memory_available_mb: usage?.memory_available_mb,
    cpus: host.cpus,
    memory_mb: host.memory_mb,
    allocatable_cpus: host.allocatable_cpus,
    allocatable_memory_mb: host.allocatable_memory_mb,
    reserved_cpus: reserved ? host.reserved_cpus : undefined,
    reserved_memory_mb: reserved ? host.reserved_memory_mb : undefined,
    disk_total_mb: host.disk_total_mb,
    disk_free_mb: host.disk_free_mb,
  };
}

/**
 * The finest slot a sample is kept at, in seconds, for a window whose points
 * fold `bucket` seconds each. The controller writes one sample a minute, so a
 * window drawn by the minute or coarser keeps one sample per minute and folds
 * from there; a window drawn finer than a minute keeps every slot the stream
 * fills, which is what lets the last ten minutes show a heartbeat at a time.
 */
export function grainOf(bucket: number): number {
  return Math.min(bucket, 60);
}

/** The slot a sample falls in: its instant, floored to the grain. */
function slotOf(at: number, grain: number): number {
  return Math.floor(at / (grain * 1000)) * grain * 1000;
}

/**
 * The slots a window covers, `bucket` seconds to a point: the last slot of
 * the last point is the current one, so the right-hand edge of every window
 * is now, and every point is a whole bucket ending on a slot boundary rather
 * than a partial one aligned to the clock.
 */
export function windowSlots(
  now: number,
  seconds: number,
  bucket: number,
): { start: number; end: number; count: number; grain: number } {
  const grain = grainOf(bucket);
  const count = Math.ceil(seconds / bucket);
  const end = slotOf(now, grain);
  const start = end - (count * bucket - grain) * 1000;
  return { start, end, count, grain };
}

/**
 * Samples keyed by host, one per slot inside the window; later inputs win.
 * `seconds` is how far back the window reaches and `grain` how fine a slot
 * is kept: a minute for the windows drawn by the minute, and finer for the
 * ones that show the last few minutes as the stream delivered them.
 */
export function mergeHostSamples(
  history: readonly HostSample[],
  live: readonly HostSample[],
  now: number,
  seconds: number,
  grain = 60,
): Map<string, HostSample[]> {
  const end = slotOf(now, grain);
  const start = end - (seconds - grain) * 1000;
  const byHost = new Map<string, Map<number, HostSample>>();
  for (const s of [...history, ...live]) {
    const at = slotOf(new Date(s.at ?? '').getTime(), grain);
    if (!Number.isFinite(at) || at < start || at > end) continue;
    let slots = byHost.get(s.host_id);
    if (!slots) byHost.set(s.host_id, (slots = new Map()));
    slots.set(at, s);
  }
  const out = new Map<string, HostSample[]>();
  for (const [id, slots] of byHost) {
    out.set(
      id,
      [...slots.entries()].sort(([a], [b]) => a - b).map(([, s]) => s),
    );
  }
  return out;
}

/**
 * One host's line for one metric: a point per bucket carrying the peak of
 * its slots, and a gap wherever nothing was observed. A spike is never
 * averaged away by a wider window, which is the same promise the fleet trend
 * makes.
 */
export function hostSeries(
  samples: readonly HostSample[],
  metric: MetricKey,
  now: number,
  seconds: number,
  bucket: number,
): SeriesPoint[] {
  const { start, end, count, grain } = windowSlots(now, seconds, bucket);
  const peaks: (number | null)[] = Array.from({ length: count }, () => null);
  for (const s of samples) {
    const at = slotOf(new Date(s.at ?? '').getTime(), grain);
    if (!Number.isFinite(at) || at < start || at > end) continue;
    const i = Math.floor((at - start) / (bucket * 1000));
    const value = metricValue(s, metric);
    if (value === null) continue;
    peaks[i] = Math.max(peaks[i] ?? value, value);
  }
  return peaks.map((value, i) => ({ at: start + i * bucket * 1000, value }));
}

/**
 * How many absent intervals in a row a line is drawn across. One missing
 * minute between two observed ones is the sampler having been a moment late
 * for the minute, or a tab that slept through it, and a line broken at every
 * such minute reads as a machine flickering in and out of existence. Two in
 * a row is a host that has stopped reporting, and that stays a gap: a flat
 * line is what a healthy, quiet machine draws too.
 */
export const BRIDGE = 1;

/**
 * The bridge for a window drawn `bucket` seconds to a point. By the minute
 * it is the one above. Finer than that, the stored samples are still a minute
 * apart and a heartbeat thirty seconds, so the line joins across a minute of
 * silence between observations; the ninety seconds after which the controller
 * counts a host lost stays a gap, as it does at every other resolution.
 */
export function bridgeFor(bucket: number): number {
  return bucket >= 60 ? BRIDGE : Math.ceil(60 / bucket);
}

/**
 * The observed points of a line, grouped into the runs one stroke joins. A
 * point inside a run that was not observed is left out of it, so the line
 * passes straight from the reading before to the reading after and no marker
 * claims a figure for that minute.
 */
export function lineRuns(
  points: readonly SeriesPoint[],
  bridge = BRIDGE,
): { i: number; value: number }[][] {
  const out: { i: number; value: number }[][] = [];
  let run: { i: number; value: number }[] = [];
  let missing = 0;
  points.forEach((p, i) => {
    if (p.value === null) {
      missing += 1;
      return;
    }
    if (run.length && missing > bridge) {
      out.push(run);
      run = [];
    }
    missing = 0;
    run.push({ i, value: p.value });
  });
  if (run.length) out.push(run);
  return out;
}

/**
 * The top of the lane above the axis, or 0 when nothing needs one. Every
 * figure but load is a share of the machine and stops at 100; load may pass
 * it, and the highest load in view sets the lane's own scale, rounded up to
 * the next 50 so the label is a round number.
 */
export function overflowCeiling(peak: number | null): number {
  if (peak === null || !Number.isFinite(peak) || peak <= 100) return 0;
  return Math.ceil(peak / 50) * 50;
}

/**
 * The windows on offer: how far back, in seconds, and how many seconds one
 * point folds. The three shortest are drawn finer than the controller's
 * minute samples, from what the stream delivers while the page is open: a
 * heartbeat is thirty seconds, so ten-second points show each one where a
 * minute-by-minute line would show the last of every two. Their history is
 * still the minute samples, so the first minutes after opening the page are
 * drawn a minute at a time and fill in as the stream arrives.
 */
export const WINDOWS = [
  {
    value: '1m',
    label: '1m',
    name: 'The last minute, in 10-second points',
    seconds: 60,
    bucket: 10,
  },
  {
    value: '5m',
    label: '5m',
    name: 'The last 5 minutes, in 10-second points',
    seconds: 300,
    bucket: 10,
  },
  {
    value: '10m',
    label: '10m',
    name: 'The last 10 minutes, in 10-second points',
    seconds: 600,
    bucket: 10,
  },
  { value: '1h', label: '1h', name: 'The last hour, minute by minute', seconds: 3600, bucket: 60 },
  {
    value: '6h',
    label: '6h',
    name: 'The last 6 hours, in 5-minute peaks',
    seconds: 21600,
    bucket: 300,
  },
  {
    value: '24h',
    label: '24h',
    name: 'The last 24 hours, in 15-minute peaks',
    seconds: 86400,
    bucket: 900,
  },
  {
    value: '7d',
    label: '7d',
    name: 'The last 7 days, in hourly peaks',
    seconds: 604800,
    bucket: 3600,
  },
] as const;
export type WindowKey = (typeof WINDOWS)[number]['value'];
export type Window = (typeof WINDOWS)[number];

/** The furthest back any window reaches, and the furthest any sub-minute one does. */
export const LONGEST_WINDOW: Window = WINDOWS[WINDOWS.length - 1]!;
export const LONGEST_FINE_WINDOW: Window = [...WINDOWS].reverse().find((w) => w.bucket < 60)!;

/** Series colours are the categorical ramp, in the order the hosts are listed. */
export function hostTone(index: number): string {
  return `var(--z-chart-${(index % 6) + 1})`;
}

/* -- what the chart draws from -------------------------------------------- */

/**
 * The share of the machine above which the scheduler treats a host as under
 * pressure: from 85% it places one runner at a time there, and a throttled
 * host does not climb back down while it stays above it. Every figure on the
 * map is a share of the machine, so the same band is drawn for all of them.
 */
export const PRESSURE = 85;

/** One host's line for one metric, as the chart receives it. */
export interface HostLine {
  id: string;
  host: Host;
  /** The host's place in the fleet's list, which is what its colour is. */
  index: number;
  metric: Metric;
  tone: string;
  points: SeriesPoint[];
  /** The newest observed point, or null where the line has none in view. */
  last: { i: number; value: number } | null;
}

/**
 * Every line the chart shows: a line per chosen metric for every host that is
 * not hidden, in the fleet's order so a host keeps its colour when its
 * neighbours are switched off. Colour follows the host, never its rank.
 */
export function hostLines(
  hosts: readonly Host[],
  hidden: readonly string[],
  byHost: ReadonlyMap<string, readonly HostSample[]>,
  metrics: readonly Metric[],
  now: number,
  seconds: number,
  bucket: number,
): HostLine[] {
  const out: HostLine[] = [];
  hosts.forEach((host, index) => {
    if (hidden.includes(host.id ?? '')) return;
    const samples = byHost.get(host.id ?? '') ?? [];
    for (const metric of metrics) {
      const points = hostSeries(samples, metric.key, now, seconds, bucket);
      let last: HostLine['last'] = null;
      for (let i = points.length - 1; i >= 0; i--) {
        const v = points[i]?.value;
        if (v !== null && v !== undefined) {
          last = { i, value: v };
          break;
        }
      }
      out.push({
        id: `${host.id}:${metric.key}`,
        host,
        index,
        metric,
        tone: hostTone(index),
        points,
        last,
      });
    }
  });
  return out;
}

/**
 * The measurement the chart leads with: the first chosen one, in the chips'
 * order. It is the one whose value is written at the end of every line, the
 * one the summary speaks about and the one a lone host's wash is drawn
 * under, so that the chart has a headline even when four things are on it.
 */
export function leadMetric(enabled: readonly MetricKey[]): Metric | null {
  return METRICS.find((m) => enabled.includes(m.key)) ?? null;
}

/** The highest value of one metric across every line, and where it was. */
export function peakOf(
  lines: readonly HostLine[],
  metric: MetricKey,
): { line: HostLine; i: number; value: number } | null {
  let best: { line: HostLine; i: number; value: number } | null = null;
  for (const line of lines) {
    if (line.metric.key !== metric) continue;
    line.points.forEach((p, i) => {
      if (p.value !== null && (best === null || p.value > best.value))
        best = { line, i, value: p.value };
    });
  }
  return best;
}

/** The drawing's edges, in pixels, for a plot `width` wide. */
export interface Frame {
  W: number;
  H: number;
  LEFT: number;
  RIGHT: number;
  TOP: number;
  BOTTOM: number;
  SPAN: number;
  /** The lane above the axis for load past the cores, or 0 without one. */
  LANE: number;
  /** Where 100% sits: the top of the drawing, or under the lane. */
  AXIS_TOP: number;
  /** A phone's shape: taller, and with fewer labels along the bottom. */
  narrow: boolean;
  /**
   * How far past RIGHT the end-of-line value is written, and the leader back
   * to its line drawn. Narrower on a phone, where every pixel of the gutter
   * is a pixel not spent on the chart.
   */
  END_GAP: number;
}

/**
 * The frame is drawn at the width the panel has, one unit to one pixel,
 * rather than a fixed picture scaled to fit: a label drawn at eleven units
 * and stretched to a wide screen is a label at nineteen pixels, which is
 * what made the old axis look like a heading. The left gutter holds the
 * percentages and the right one the value at the end of each line; both are
 * the same in every plot so the plots stacked in the per-host layout share
 * one x axis.
 *
 * Both were sized for a laptop, and on a phone that is 88 of 294 pixels --
 * nearly a third of the drawing spent on four glyphs a side, which is why
 * the chart visibly stopped short of the panel it sat in. A narrow plot cuts
 * each to what the widest label it can carry actually measures: "100%" at
 * the 2xs size, and no padding for a laptop's comfort. The labels themselves
 * stay, on a phone as anywhere -- being readable from the right-hand edge
 * alone is the point of them.
 */
export function plotFrame(
  width: number,
  options: { compact?: boolean; lane?: boolean; axis?: boolean } = {},
): Frame {
  const W = Math.max(280, Math.round(width));
  const narrow = W < 560;
  const H = options.compact ? (narrow ? 132 : 116) : narrow ? 300 : 248;
  const LANE = options.lane ? (options.compact ? 22 : 40) : 0;
  const LEFT = narrow ? 36 : 42;
  const END_GAP = narrow ? 5 : 8;
  const RIGHT = W - (narrow ? 36 : 46);
  const TOP = 12;
  const BOTTOM = H - (options.axis === false ? 10 : 26);
  return {
    W,
    H,
    LEFT,
    RIGHT,
    TOP,
    BOTTOM,
    SPAN: RIGHT - LEFT,
    LANE,
    AXIS_TOP: TOP + LANE,
    narrow,
    END_GAP,
  };
}

/** The x of point `i`, of `count` across the frame. */
export function scaleX(frame: Frame, count: number): (i: number) => number {
  return (i) => frame.LEFT + (i * frame.SPAN) / Math.max(1, count - 1);
}

/**
 * The y of a value. The axis is 0-100% and stays so; a value past it is
 * drawn in the lane, on the lane's own scale up to `overflow`, so a load of
 * eight times the cores is still a spike and the axis keeps its room.
 */
export function scaleY(frame: Frame, overflow: number): (value: number) => number {
  return (value) => {
    if (value <= 100 || !overflow)
      return frame.AXIS_TOP + (1 - Math.min(value, 100) / 100) * (frame.BOTTOM - frame.AXIS_TOP);
    return frame.AXIS_TOP - ((Math.min(value, overflow) - 100) / (overflow - 100)) * frame.LANE;
  };
}

/** Which point a pointer is over, from where it is across the frame. */
export function indexAtX(frame: Frame, count: number, viewX: number): number {
  const i = Math.round(((viewX - frame.LEFT) / frame.SPAN) * Math.max(1, count - 1));
  return Math.max(0, Math.min(count - 1, i));
}

/**
 * The host whose line passes nearest a pointer at point `i`, within
 * `tolerance` pixels, or null where none does. Pointing at a line is how a
 * reader asks which host it is, and on a chart of twenty lines the legend
 * alone cannot answer that.
 */
export function nearestHost(
  lines: readonly HostLine[],
  i: number,
  viewY: number,
  y: (value: number) => number,
  tolerance: number,
): string | null {
  let best: { id: string; distance: number } | null = null;
  for (const line of lines) {
    const v = line.points[i]?.value;
    if (v === null || v === undefined) continue;
    const distance = Math.abs(y(v) - viewY);
    if (distance <= tolerance && (best === null || distance < best.distance))
      best = { id: line.host.id ?? '', distance };
  }
  return best?.id ?? null;
}

/**
 * What every chart in here shares: a figure drawn over time, the frame it is
 * drawn in, where the labels along the bottom go, how labels that want the
 * same height are pushed apart, and what a round axis is.
 *
 * It exists because the capacity map, the fleet trend and the usage chart
 * answered the same questions and there is one right answer to each. Pure,
 * and imported by unit tests, so nothing here touches the DOM or the clock:
 * the caller passes the instants.
 */

/**
 * Where to put the labels along the bottom: on round times -- the hour, the
 * quarter hour, midnight -- rather than at four evenly spaced instants that
 * happen to be 11:19 and 19:19. The step is the smallest of the candidates
 * that fits about five labels in the window, and the ticks are the multiples
 * of it in local time, so a day's chart is labelled at 00:00, 06:00, 12:00,
 * a minute's at :10, :20, :30, and a fortnight's every second midnight.
 */
export function timeTicks(start: number, end: number, target = 5): number[] {
  const MINUTE = 60_000;
  const DAY = 86400;
  // Up to a day the steps are the round times a clock has; past it they are
  // whole days, because a usage report is read over a fortnight or a quarter
  // and a step of "a day" would print thirty labels over one another. A
  // multi-day step lands on a local midnight rather than on a named weekday:
  // evenly spaced is what the axis is for, and the label says the date.
  const steps = [
    10,
    15,
    30,
    60,
    120,
    300,
    600,
    900,
    1800,
    3600,
    7200,
    10800,
    21600,
    43200,
    DAY,
    2 * DAY,
    3 * DAY,
    7 * DAY,
    14 * DAY,
    28 * DAY,
    91 * DAY,
    365 * DAY,
  ].map((s) => s * 1000);
  const span = end - start;
  const step = steps.find((s) => span / s <= target) ?? steps[steps.length - 1]!;
  // Multiples of the step in local time, which is what the labels say.
  const offset = new Date(start).getTimezoneOffset() * MINUTE;
  const first = Math.ceil((start - offset) / step) * step + offset;
  const out: number[] = [];
  for (let at = first; at <= end; at += step) out.push(at);
  return out;
}

/**
 * Where the labels at the ends of the lines go. Each wants to sit level with
 * its line, and two lines that end within a label's height of each other
 * would print on top of one another; so, taken from the top, each is pushed
 * down until it clears the one above, and if the last is then past the
 * bottom the stack is walked back up. The answer is in the callers' order.
 */
export function spreadLabels(
  wanted: readonly number[],
  gap: number,
  min: number,
  max: number,
): number[] {
  const order = wanted.map((y, i) => ({ y, i })).sort((a, b) => a.y - b.y);
  const placed = order.map((o) => Math.max(min, Math.min(max, o.y)));
  for (let k = 1; k < placed.length; k++) placed[k] = Math.max(placed[k]!, placed[k - 1]! + gap);
  for (let k = placed.length - 1; k >= 0; k--) {
    const ceiling = k === placed.length - 1 ? max : placed[k + 1]! - gap;
    placed[k] = Math.max(min, Math.min(placed[k]!, ceiling));
  }
  const out = new Array<number>(wanted.length);
  order.forEach((o, k) => (out[o.i] = placed[k]!));
  return out;
}

/**
 * A round axis for a chart whose ceiling is whatever it happened to see. The
 * capacity map's figures are all shares of a machine and its axis is 0-100%
 * for good; a count of jobs has no such ceiling, and an axis that simply
 * topped out at the peak labelled its gridlines 4.25 and 8.5 -- halves of a
 * job nobody can queue. The step is the first of 1, 2 or 5 times a power of
 * ten that fits the peak into `divisions` bands, so the labels are the round
 * numbers an operator would have picked, and the top of the axis is a
 * whole number of steps above zero.
 *
 * `fractional` lets the step fall below one, for the axes whose unit divides:
 * a quarter of an hour of runner time is a real quantity, and a fleet whose
 * busiest day ran twenty minutes of jobs would otherwise be drawn against a
 * one-hour axis with nothing but the baseline under it.
 */
export function countAxis(
  peak: number,
  divisions = 4,
  fractional = false,
): { ceiling: number; values: number[] } {
  // Nothing to scale to: an axis with one step on it, so an empty chart is
  // still a chart and the first job to land has somewhere to be drawn.
  if (!(peak > 0)) return { ceiling: 1, values: [0, 1] };
  // Rounded at every step: 3 * 0.1 is 0.30000000000000004, and a gridline
  // labelled that is worse than no gridline at all.
  const round = (value: number) => Number(value.toPrecision(12));
  const target = peak / Math.max(1, divisions);
  const exponent = Math.floor(Math.log10(target));
  const magnitude = 10 ** (fractional ? exponent : Math.max(0, exponent));
  const step =
    [1, 2, 5, 10].map((m) => round(m * magnitude)).find((s) => s >= target) ??
    round(magnitude * 10);
  const ceiling = round(Math.max(step, Math.ceil(peak / step) * step));
  const values: number[] = [];
  for (let i = 0; i * step <= ceiling + step / 2; i++) values.push(round(i * step));
  return { ceiling, values };
}

/* -- the figures a trend draws -------------------------------------------- */

/**
 * One figure on a trend: what it is called, and how its line is drawn.
 *
 * Colour and stroke carry two different things, and which two is the chart's
 * to decide -- the capacity map gives a colour to each host and a stroke to
 * each measurement, the fleet trend a colour to each state and a stroke to
 * whether the figure counts jobs or runners. What is fixed is that a figure
 * is never told apart by colour alone: two lines within about twenty points
 * of CIEDE2000 are two lines an operator has to squint at, and the nearer of
 * such a pair is drawn dashed so the legend swatch carries a stroke as well
 * as a hue. See docs/ui-guidelines.md.
 */
export interface Series {
  key: string;
  /** The chip, the legend row and the reading. */
  label: string;
  /** What the figure counts, for the tooltip and assistive text. */
  hint: string;
  tone: string;
  /** An SVG dash pattern. `''` is solid. */
  dash: string;
}

/** One reading of a figure. `null` is a gap, and never a zero. */
export interface SeriesPoint {
  at: number;
  value: number | null;
}

/** One figure's line over the window, as a plot receives it. */
export interface SeriesLine<S extends Series = Series> {
  series: S;
  points: SeriesPoint[];
  /** The newest observed point, for the label at the end and the pulse. */
  last: { i: number; value: number } | null;
}

/** A line from a figure and its points, with the newest reading found. */
export function seriesLine<S extends Series>(series: S, points: SeriesPoint[]): SeriesLine<S> {
  let last: { i: number; value: number } | null = null;
  points.forEach((p, i) => {
    if (p.value !== null) last = { i, value: p.value };
  });
  return { series, points, last };
}

/**
 * The observed points of a line, grouped into the runs one stroke joins. An
 * interval nobody sampled is left out, so the line passes from the reading
 * before to the reading after and no marker claims a figure for it: a gap is
 * a gap, and never a zero, because an outage and an empty queue are opposite
 * news.
 */
export function seriesRuns(points: readonly SeriesPoint[]): Array<{ i: number; value: number }[]> {
  const out: Array<{ i: number; value: number }[]> = [];
  let run: { i: number; value: number }[] = [];
  points.forEach((p, i) => {
    if (p.value === null) {
      if (run.length) out.push(run);
      run = [];
    } else run.push({ i, value: p.value });
  });
  if (run.length) out.push(run);
  return out;
}

/** The highest figure across every line, and which line and point it was at. */
export function seriesPeak<S extends Series>(
  lines: readonly SeriesLine<S>[],
): { line: SeriesLine<S>; i: number; value: number } | null {
  let best: { line: SeriesLine<S>; i: number; value: number } | null = null;
  for (const line of lines)
    line.points.forEach((p, i) => {
      if (p.value !== null && (best === null || p.value > best.value))
        best = { line, i, value: p.value };
    });
  return best;
}

/**
 * The figure whose line passes nearest a pointer at point `i`, within
 * `tolerance` pixels, or null where none does. Pointing at a line is how a
 * reader asks what it is, and with five of them on one chart the legend
 * alone cannot answer that.
 */
export function nearestSeries<S extends Series>(
  lines: readonly SeriesLine<S>[],
  i: number,
  viewY: number,
  y: (value: number) => number,
  tolerance: number,
): S['key'] | null {
  let best: { key: S['key']; distance: number } | null = null;
  for (const line of lines) {
    const v = line.points[i]?.value;
    if (v === null || v === undefined) continue;
    const distance = Math.abs(y(v) - viewY);
    if (distance <= tolerance && (best === null || distance < best.distance))
      best = { key: line.series.key, distance };
  }
  return best?.key ?? null;
}

/* -- the frame ------------------------------------------------------------- */

/** The drawing's edges, in pixels, for a trend `width` wide. */
export interface TrendFrame {
  W: number;
  H: number;
  LEFT: number;
  RIGHT: number;
  TOP: number;
  BOTTOM: number;
  SPAN: number;
  /** A phone's shape: taller, and with fewer labels along the bottom. */
  narrow: boolean;
}

/**
 * The frame is drawn at the width the panel has, one unit to one pixel,
 * rather than a fixed picture stretched to fit: the old chart drew 760 units
 * and let the browser scale them, so its eleven-unit axis text arrived on a
 * wide screen at nineteen pixels and read as a heading. The left gutter is
 * sized for the widest figure the axis will print, and the right one holds
 * the newest value at the end of each line -- sized the same way, so a fleet
 * sitting in single digits doesn't reserve room for "128.4h".
 */
export function trendFrame(
  width: number,
  options: { digits?: number; labels?: boolean } = {},
): TrendFrame {
  const W = Math.max(280, Math.round(width));
  const narrow = W < 560;
  const H = narrow ? 236 : 196;
  const digits = Math.max(1, options.digits ?? 3);
  const LEFT = 16 + 7 * digits;
  const RIGHT = W - (options.labels === false ? 10 : 16 + 7 * digits);
  const TOP = 14;
  return { W, H, LEFT, RIGHT, TOP, BOTTOM: H - 26, SPAN: RIGHT - LEFT, narrow };
}

/** The x of point `i`, of `count` across the frame. */
export function trendX(frame: TrendFrame, count: number): (i: number) => number {
  return (i) => frame.LEFT + (i * frame.SPAN) / Math.max(1, count - 1);
}

/** The y of a figure on an axis running from zero to `ceiling`. */
export function trendY(frame: TrendFrame, ceiling: number): (value: number) => number {
  return (value) =>
    frame.BOTTOM - (Math.min(value, ceiling) / Math.max(1, ceiling)) * (frame.BOTTOM - frame.TOP);
}

/** Which point a pointer is over, from where it is across the frame. */
export function trendIndexAtX(frame: TrendFrame, count: number, viewX: number): number {
  const i = Math.round(((viewX - frame.LEFT) / frame.SPAN) * Math.max(1, count - 1));
  return Math.max(0, Math.min(count - 1, i));
}

import type { FleetSample, Host, Pool, Stats } from '../api/types';
import { seriesLine, type Series, type SeriesLine, type SeriesPoint } from './plot';

export function finite(value: number | undefined): number | null {
  return value !== undefined && Number.isFinite(value) ? Math.max(0, value) : null;
}
export function percent(used: number | null, total: number | null): number | null {
  return used !== null && total !== null && total > 0 ? (100 * used) / total : null;
}

/**
 * Whether a queue depth is worth its tile's warning colour, against
 * ui.queue_warning_threshold. The setting defaults to 1, which is the fixed
 * "anything queued at all" behaviour this replaces; a fleet whose queue
 * normally sits above zero can raise it so the colour still means something.
 */
export function queueTone(
  value: number | null | undefined,
  threshold: number | undefined,
): 'warning' | 'neutral' {
  return (value ?? 0) >= (threshold ?? 1) ? 'warning' : 'neutral';
}

/** Read controller aggregates, never the paginated runner cache. */
export function poolSignals(pools: readonly Pool[], stats: Stats | null) {
  return pools.map((pool) => {
    const latest = stats?.pools?.find((p) => p.pool_id === pool.id);
    const queued = finite(latest?.queued ?? pool.queued_jobs);
    const live = finite(latest?.live ?? pool.counts?.live);
    const max = finite(latest?.max ?? pool.max_runners);
    return {
      pool,
      queued,
      live,
      max,
      busy: finite(latest?.busy ?? pool.counts?.busy),
      idle: finite(latest?.idle ?? pool.counts?.idle),
      atCeiling:
        pool.enabled === true &&
        queued !== null &&
        queued > 0 &&
        live !== null &&
        max !== null &&
        max > 0 &&
        live >= max,
      headroom: live !== null && max !== null ? Math.max(0, max - live) : null,
    };
  });
}

/** Slot headroom is not a promise that a particular runner fits. */
export function hostSignals(host: Host) {
  const capacity = finite(host.capacity);
  const used = finite(host.active_runners);
  const free =
    finite(host.free) ?? (capacity !== null && used !== null ? Math.max(0, capacity - used) : null);
  const eligible = host.healthy === true && host.cordoned !== true && host.incompatible !== true;
  const state = host.incompatible
    ? 'Incompatible'
    : host.healthy === false
      ? 'Offline'
      : host.cordoned
        ? 'Cordoned'
        : host.healthy !== true
          ? 'Unknown'
          : free === 0
            ? 'No free slots'
            : 'Available slots';
  return {
    capacity,
    used,
    free,
    eligible,
    state,
    cpu:
      host.resources_known === true && host.reserved_known === true
        ? percent(finite(host.reserved_cpus), finite(host.allocatable_cpus))
        : null,
    memory:
      host.resources_known === true && host.reserved_known === true
        ? percent(finite(host.reserved_memory_mb), finite(host.allocatable_memory_mb))
        : null,
    diskFree:
      host.resources_known === true && (host.disk_total_mb ?? 0) > 0
        ? percent(finite(host.disk_free_mb), finite(host.disk_total_mb))
        : null,
  };
}

/** Fill missing minutes with null; never draw an outage as zero demand. */
export function minuteSeries(
  points: readonly SeriesPoint[],
  now: number,
  minutes = 60,
): SeriesPoint[] {
  const end = Math.floor(now / 60_000) * 60_000;
  const byMinute: Record<number, number | null> = {};
  for (const p of points)
    if (Number.isFinite(p.at)) byMinute[Math.floor(p.at / 60_000) * 60_000] = p.value;
  return Array.from({ length: minutes }, (_, i) => {
    const at = end - (minutes - 1 - i) * 60_000;
    return { at, value: byMinute[at] ?? null };
  });
}

/** Keep one sample per minute. Later inputs win, so streamed data beats a fetch. */
export function mergeSamples(
  history: readonly FleetSample[],
  live: readonly FleetSample[],
  now: number,
  minutes = 60,
): FleetSample[] {
  const byMinute: Record<number, FleetSample> = {};
  const end = Math.floor(now / 60_000) * 60_000;
  for (const point of [...history, ...live]) {
    const at = Math.floor(new Date(point.at ?? '').getTime() / 60_000) * 60_000;
    if (Number.isFinite(at) && at >= end - (minutes - 1) * 60_000 && at <= end)
      byMinute[at] = point;
  }
  return Object.entries(byMinute)
    .sort(([a], [b]) => Number(a) - Number(b))
    .map(([, point]) => point);
}

/**
 * A minute series folded into wider intervals, each carrying the peak of its
 * minutes. Peaks rather than means because a queue that hit twelve for two
 * minutes is what an operator looking at a day wants to see, and a mean of
 * fifteen minutes would round it away. An interval with no observed minute
 * stays a gap.
 */
export function foldMinutes(points: readonly SeriesPoint[], step: number): SeriesPoint[] {
  if (step <= 1) return [...points];
  const out: SeriesPoint[] = [];
  for (let i = 0; i < points.length; i += step) {
    const slice = points.slice(i, i + step);
    const known = slice.map((p) => p.value).filter((v): v is number => v !== null);
    out.push({
      at: slice[0]?.at ?? 0,
      value: known.length ? Math.max(...known) : null,
    });
  }
  return out;
}

/* -- what the fleet trend draws ------------------------------------------- */

export type SignalKey = 'queue' | 'running' | 'idle' | 'busy' | 'live';

/**
 * A fleet figure. Its colour is the status colour the fleet already uses for
 * that state everywhere else, so an operator who has learnt that amber is
 * pending and teal is busy reads this chart without a legend, and its stroke
 * says whether the figure counts jobs or runners: the two busy figures --
 * the jobs running and the runners running them -- are one colour and can be
 * read against each other.
 */
export interface Signal extends Series {
  key: SignalKey;
  /** Jobs come from GitHub; runners are ours. It is what the stroke says. */
  jobs: boolean;
}

/** In the order the chips appear: the demand first, then what is meeting it. */
export const SIGNALS: readonly Signal[] = [
  {
    key: 'queue',
    label: 'Queued jobs',
    hint: 'jobs waiting for a runner',
    tone: 'var(--z-pending)',
    dash: '',
    jobs: true,
  },
  {
    key: 'running',
    label: 'Running jobs',
    hint: 'jobs a runner has picked up',
    tone: 'var(--z-busy)',
    dash: '8 4',
    jobs: true,
  },
  {
    key: 'idle',
    label: 'Idle runners',
    hint: 'runners registered and waiting for work',
    tone: 'var(--z-idle)',
    dash: '',
    jobs: false,
  },
  {
    key: 'busy',
    label: 'Busy runners',
    hint: 'runners executing a job',
    tone: 'var(--z-busy)',
    dash: '',
    jobs: false,
  },
  {
    key: 'live',
    label: 'Live runners',
    hint: 'every runner short of removed: provisioning, registering, idle, busy, draining',
    tone: 'var(--z-neutral)',
    dash: '2 4',
    jobs: false,
  },
];

// Demand and the two halves of the answer to it. Queued against idle is the
// question the page is opened with -- is anything waiting, and was there
// anything free -- and running is what says whether the fleet is working or
// merely awake.
export const DEFAULT_SIGNALS: readonly SignalKey[] = ['queue', 'running', 'idle'];

/**
 * One sample's figure for a signal. `others` chooses between the jobs the
 * whole organisation reported and the ones this fleet is responsible for;
 * runner counts are always ours, because nobody else's runners are visible
 * from here.
 */
export function signalValue(sample: FleetSample, key: SignalKey, others: boolean): number | null {
  switch (key) {
    case 'queue':
      return (others ? sample.queued_jobs : sample.fleet_queued_jobs) ?? null;
    case 'running':
      return (others ? sample.running_jobs : sample.fleet_running_jobs) ?? null;
    case 'idle':
      return sample.idle_runners ?? null;
    case 'busy':
      return sample.busy_runners ?? null;
    case 'live':
      return sample.total_runners ?? null;
  }
}

/** The signal the chart leads with: the first chosen one, in the chips' order. */
export function leadSignal(enabled: readonly SignalKey[]): Signal | null {
  return SIGNALS.find((s) => enabled.includes(s.key)) ?? null;
}

/** One signal's line over the window, as the chart receives it. */
export type SignalLine = SeriesLine<Signal>;

/** A line for every chosen signal, in the chips' order. */
export function signalLines(
  samples: readonly FleetSample[],
  enabled: readonly SignalKey[],
  others: boolean,
  now: number,
  minutes: number,
  step: number,
): SignalLine[] {
  return SIGNALS.filter((signal) => enabled.includes(signal.key)).map((signal) =>
    seriesLine(
      signal,
      foldMinutes(
        minuteSeries(
          samples.map((s) => ({
            at: new Date(s.at ?? '').getTime(),
            value: signalValue(s, signal.key, others),
          })),
          now,
          minutes,
        ),
        step,
      ),
    ),
  );
}

/**
 * The stretches in view where jobs were queued with no idle runner to take
 * them. It is this chart's pressure band: the capacity map can draw a line
 * at 85% because every figure on it is a share of a machine, and a count of
 * jobs has no such threshold -- but "something was waiting and nothing was
 * free" is the moment an operator is looking for, and it can be found
 * without knowing what a healthy queue depth is for this fleet.
 *
 * It is judged a minute at a time and then folded, which is why it takes the
 * minute series and the width of a point rather than the drawn lines: a
 * fifteen-minute point carries each figure's peak, and the most idle runners
 * there were at any moment in a quarter of an hour is not an answer to
 * whether anything was free when the queue was deep. Folded the other way
 * round -- was there a minute in this interval when work waited and nothing
 * was free -- the band survives zooming out, which is the zoom an operator
 * asking "did we run short overnight" is on.
 *
 * Contiguous intervals come back as one run, so the chart shades a spell of
 * starvation as one band rather than a picket fence, and an interval nobody
 * sampled ends the run rather than extending it across the unknown.
 */
export function starvedRuns(
  queue: SignalLine | null,
  idle: SignalLine | null,
  step = 1,
): Array<{ from: number; to: number }> {
  if (!queue || !idle) return [];
  const out: Array<{ from: number; to: number }> = [];
  queue.points.forEach((p, minute) => {
    const free = idle.points[minute]?.value;
    if (p.value === null || p.value <= 0 || free === null || free === undefined || free !== 0)
      return;
    const i = Math.floor(minute / Math.max(1, step));
    const open = out[out.length - 1];
    if (open && open.to >= i - 1) open.to = i;
    else out.push({ from: i, to: i });
  });
  return out;
}

/**
 * The usage chart's figures: a report's intervals as lines.
 *
 * Pure, and imported by a unit test, so nothing here touches the DOM or the
 * clock: the caller passes `now`. The matrix draws the same buckets as
 * squares, so what a figure means is settled in one place and the two cannot
 * drift.
 *
 * Two measures rather than one chart, because two units do not share an axis:
 * a count of jobs and a number of hours drawn against the same gridlines
 * would put "twelve" and "twelve hours" at the same height and invite the
 * reader to compare them. Which figures of the chosen measure are drawn is
 * the operator's to say, one chip each.
 */
import { intervalWidth, type ActivityBucket, type Interval } from './activity';
import { seriesLine, type Series, type SeriesLine } from './plot';
import { formatNumber, toMillis } from '../format';

export type UsageMeasure = 'jobs' | 'runtime';

export type UsageKey =
  'queued' | 'succeeded' | 'failed' | 'cancelled' | 'unknown' | 'execution' | 'allocated';

export interface UsageFigure extends Series {
  key: UsageKey;
  measure: UsageMeasure;
  /** Demand, or what became of it. A hairline separates the two. */
  demand: boolean;
  /** What the figure reads from one interval, in the unit its axis carries. */
  read: (bucket: ActivityBucket) => number;
}

/** The two measures, as the control that chooses between them takes them. */
export const USAGE_MEASURES = [
  { value: 'jobs', label: 'Jobs', name: 'Job demand and outcomes, counted per interval' },
  { value: 'runtime', label: 'Runner time', name: 'Executing and allocated runner time, in hours' },
] as const;

/**
 * The figures, in the order their chips appear: demand first, then what
 * became of it.
 *
 * The colours are the console's fixed status colours, so a red line is a
 * failure here as it is everywhere else, and the two pairs that sit within
 * about twenty points of CIEDE2000 of one another -- allocated against
 * queued, cancelled against the greys -- are told apart by their stroke as
 * well: allocated runner time is the envelope the executing line sits
 * inside, and cancelled work is the outcome the fleet had no hand in. Both
 * read as reference quantities, which is what a dashed line already means.
 * See docs/ui-guidelines.md.
 */
export const USAGE_FIGURES: readonly UsageFigure[] = [
  {
    key: 'queued',
    measure: 'jobs',
    demand: true,
    label: 'Queued',
    hint: 'jobs that joined the queue in this interval',
    tone: 'var(--z-accent)',
    dash: '',
    read: (b) => b.queued,
  },
  {
    key: 'succeeded',
    measure: 'jobs',
    demand: false,
    label: 'Succeeded',
    hint: 'jobs that finished successfully',
    tone: 'var(--z-idle)',
    dash: '',
    read: (b) => b.succeeded,
  },
  {
    key: 'failed',
    measure: 'jobs',
    demand: false,
    label: 'Failed',
    hint: 'jobs that finished in a failure',
    tone: 'var(--z-danger)',
    dash: '',
    read: (b) => b.failed,
  },
  {
    key: 'cancelled',
    measure: 'jobs',
    demand: false,
    label: 'Cancelled / skipped',
    hint: 'jobs cancelled or skipped before they could finish',
    tone: 'var(--z-neutral)',
    dash: '6 4',
    read: (b) => b.cancelled,
  },
  {
    key: 'unknown',
    measure: 'jobs',
    demand: false,
    label: 'Unknown',
    hint: 'jobs GitHub reported no conclusion for',
    tone: 'var(--z-pending)',
    dash: '',
    read: (b) => b.unknown,
  },
  {
    key: 'execution',
    measure: 'runtime',
    demand: true,
    label: 'Executing',
    hint: 'hours a job spent running',
    tone: 'var(--z-busy)',
    dash: '',
    read: (b) => b.execution_seconds / 3600,
  },
  {
    key: 'allocated',
    measure: 'runtime',
    demand: false,
    label: 'Allocated',
    hint: 'hours a runner was held for this work, executing or not',
    tone: 'var(--z-accent)',
    dash: '6 4',
    read: (b) => b.allocated_seconds / 3600,
  },
];

/**
 * What the chart opens on. Queued against succeeded and failed is the
 * question the page is opened with -- how much work arrived, and how much of
 * it came out well -- and the two quieter outcomes are a chip away and
 * remembered once switched on.
 */
export const DEFAULT_FIGURES: readonly UsageKey[] = [
  'queued',
  'succeeded',
  'failed',
  'execution',
  'allocated',
];

/**
 * The figures a report can draw. A runner idles on behalf of a pool and never
 * on behalf of a repository or a workflow, so at those groupings allocated
 * time is not the group's to claim -- the table drops the column for the same
 * reason, and a line of somebody else's hours would be worse than no line.
 */
export function usageFigures(measure: UsageMeasure, attributable: boolean): UsageFigure[] {
  return USAGE_FIGURES.filter(
    (f) => f.measure === measure && (attributable || f.key !== 'allocated'),
  );
}

/**
 * A line for every chosen figure, over the report's own intervals.
 *
 * An interval that has not begun is a gap and never a zero: a report to the
 * end of today is a window with hours still in it, and a line that ran along
 * the floor from now until midnight would read as a fleet that had stopped.
 * The interval `now` falls inside is drawn, because it is being filled and
 * an operator watching work land wants to see it land.
 */
export function usageLines(
  buckets: readonly ActivityBucket[],
  figures: readonly UsageFigure[],
  now: number,
): SeriesLine<UsageFigure>[] {
  return figures.map((figure) =>
    seriesLine(
      figure,
      buckets.map((bucket) => {
        const at = toMillis(bucket.from) ?? 0;
        return { at, value: at > now ? null : figure.read(bucket) };
      }),
    ),
  );
}

/** Whether an interval is still being filled, so its figures are not final. */
export function inProgress(bucket: ActivityBucket, interval: Interval, now: number): boolean {
  const at = toMillis(bucket.from);
  return at !== null && at <= now && at + intervalWidth(interval) > now;
}

/**
 * The stretches in view where a pool had nowhere to put a runner.
 *
 * It is the usage chart's version of the fleet trend's starvation band and
 * the capacity map's pressure line: the condition the lines are read against,
 * and the one an operator scanning a fortnight is looking for. Neighbouring
 * intervals come back as one run, so a bad afternoon is one band rather than
 * a picket fence, and an interval with no capacity observations at all ends
 * the run rather than carrying it across the unknown -- the fleet may well
 * have had room in the hour nobody recorded.
 */
export function capacityRuns(
  buckets: readonly ActivityBucket[],
): Array<{ from: number; to: number }> {
  const out: Array<{ from: number; to: number }> = [];
  buckets.forEach((bucket, i) => {
    if (bucket.capacity_samples === 0 || bucket.capacity_reached === 0) return;
    const open = out[out.length - 1];
    if (open && open.to >= i - 1) open.to = i;
    else out.push({ from: i, to: i });
  });
  return out;
}

const HOURS = new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 });

/** Jobs are counted whole; runner time is not, and 0.25 h is a real figure. */
export function usageFormat(measure: UsageMeasure): (value: number) => string {
  return measure === 'runtime' ? (value) => HOURS.format(value) : formatNumber;
}

import type { Job, WorkflowRun } from '$lib/api/types';
import {
  CANCELLING,
  jobStatus,
  QUEUE_EXPEDITED,
  QUEUE_PAUSED,
  QUEUE_REMOVED,
  RUN_FAILING,
  toneTokens,
} from '$lib/status';
import type { StatusMeta } from '$lib/status';

export interface ActivityStatus {
  status: StatusMeta;
  label: string;
  motion: string;
  /**
   * The pose of the rest of a workflow's pack, where it differs from the
   * leader's. A run with a failed job among ones still running is both things
   * at once, and one pose for all three dogs would have to lie about half of it.
   */
  packMotion?: string;
  detail: string;
}

/**
 * `quirky` is passed in by the caller rather than read here -- see the note
 * on `runnerStatus` in `$lib/status` for why this module stays free of it too.
 */
export function queuedActivity(
  job: Pick<Job, 'provisioning' | 'provision_now' | 'cancel_requested_at'>,
  quirky = true,
): ActivityStatus {
  if (job.cancel_requested_at)
    return {
      status: CANCELLING,
      label: quirky ? 'Coming to heel' : CANCELLING.label,
      motion: 'draining',
      detail: CANCELLING.hint ?? 'Cancellation requested.',
    };
  const state = job.provisioning || (job.provision_now ? 'expedited' : 'ready');
  if (state === 'paused')
    return {
      status: QUEUE_PAUSED,
      label: quirky ? 'Stay there' : QUEUE_PAUSED.label,
      motion: 'throttled',
      detail: QUEUE_PAUSED.hint!,
    };
  if (state === 'deleted')
    return {
      status: QUEUE_REMOVED,
      label: quirky ? 'Back in the kennel' : QUEUE_REMOVED.label,
      motion: 'removed',
      detail: QUEUE_REMOVED.hint!,
    };
  if (state === 'expedited') {
    // Still the queued tone -- nothing is running yet -- but the priority
    // glyph rather than the queued clock, or a job somebody pressed Run now
    // on is drawn exactly like the Ready rows around it.
    const status = {
      ...jobStatus('queued'),
      key: state,
      label: 'Run now',
      icon: QUEUE_EXPEDITED.icon,
    };
    return {
      status,
      label: quirky ? 'First walkies' : status.label,
      motion: 'registering',
      detail:
        'Prioritised within pool priority. Still waiting for a runner; this job is not running yet.',
    };
  }
  const status = { ...jobStatus('queued'), key: 'ready', label: 'Ready' };
  return {
    status,
    label: quirky ? 'Sit, wait' : status.label,
    motion: 'idle',
    detail:
      'Queued and ready for normal provisioning. Waiting for a matching runner and available capacity.',
  };
}

export function workflowActivity(
  run: Pick<WorkflowRun, 'state' | 'conclusion' | 'cancelling' | 'jobs'>,
  quirky = true,
): ActivityStatus {
  const status = run.cancelling ? CANCELLING : jobStatus(run.state, run.conclusion);
  if (run.cancelling)
    return {
      status,
      label: quirky ? 'Calling the pack' : status.label,
      motion: 'draining',
      detail: 'Cancellation requested. Waiting for the workflow and its jobs to stop.',
    };
  // A failure among jobs still running or waiting is known now, not when the
  // run's own state catches up, so the row turns before GitHub's does. The
  // leader shows the hurt; the pack behind it is still on the move.
  const failed = run.jobs?.failed ?? 0;
  if (run.state !== 'completed' && failed > 0) {
    const total = run.jobs?.total ?? 0;
    const running = run.state === 'in_progress';
    const count = total ? `${failed} of its ${total} jobs` : `${failed} of its jobs`;
    return {
      status: RUN_FAILING,
      label: quirky ? 'Pack in trouble' : RUN_FAILING.label,
      motion: 'failed',
      packMotion: running ? 'busy' : 'idle',
      detail: `${count} ${failed === 1 ? 'has' : 'have'} failed while the rest ${running ? 'are still running' : 'are still waiting to run'}, so the workflow will end in failure unless ${failed === 1 ? 'it is' : 'they are'} re-run. Expand the row to see which.`,
    };
  }
  if (run.state === 'queued' || run.state === 'waiting')
    return {
      status,
      label: quirky ? 'Pack waiting' : status.label,
      motion: 'idle',
      detail: `${status.label}. The workflow is waiting to run. The pack represents the workflow, not a count of its jobs.`,
    };
  if (run.state === 'in_progress')
    return {
      status,
      label: quirky ? 'Pack on the move' : status.label,
      motion: 'busy',
      detail:
        'The workflow is running. Individual jobs may still be queued or already finished; expand the row to see each one.',
    };
  if (run.state === 'completed' && run.conclusion?.toLowerCase() === 'success')
    return {
      status,
      label: quirky ? 'Good pack!' : status.label,
      motion: 'registering',
      detail: 'The workflow completed successfully.',
    };
  if (status.tone === 'danger')
    return {
      status,
      label: quirky ? 'Pack needs help' : status.label,
      motion: 'failed',
      detail: `${status.label}. Expand the workflow to inspect its jobs and errors.`,
    };
  if (run.state === 'completed')
    return {
      status,
      label: quirky ? 'Pack resting' : status.label,
      motion: 'removed',
      detail: `Workflow finished: ${status.label.toLowerCase()}.`,
    };
  return {
    status: { ...status, ...toneTokens('neutral') },
    label: status.label,
    motion: 'unknown',
    detail: 'No recognised workflow status has been reported yet.',
  };
}

/**
 * The filter state the Jobs and Workflows pages share, held in the URL.
 *
 * The two pages ask the same questions of two levels of the same thing -- a
 * run, and the jobs inside it -- and take the same keys, so one address bar
 * serves both: a link into Jobs carrying `?failed=true` means the same on
 * Workflows, and the views row reads the same either way. The keys are the
 * API's own, so the address bar and the request agree and a pasted link
 * reproduces exactly what the sender was looking at.
 */
import {
  JOB_STATES,
  PROVISIONING_STATUSES,
  WAITING_PROVISIONING,
  type JobState,
  type ProvisioningStatus,
} from '../api/types';
import { router } from '../router';
import type { JobFilterState } from './JobFilters.svelte';
import { currentJobView, DEFAULT_JOB_STATE, JOB_VIEWS, type JobView } from './views';

/** Every key a filter lives under, so "has this page been asked anything?" has one answer. */
const FILTER_KEYS = [
  'q',
  'repo',
  'workflow',
  'pool_id',
  'label',
  'conclusion',
  'state',
  'provisioning',
  'since',
  'until',
  'unmatched',
  'failed',
  'faulted',
  'all',
] as const;

/** The status keys a view owns. A patch touching one of them is choosing a view. */
const STATUS_KEYS = [
  'state',
  'conclusion',
  'failed',
  'faulted',
  'unmatched',
  'provisioning',
] as const;

export interface JobFilterHandle {
  /** Nobody has asked the page anything: it answers "what is running?". */
  readonly defaulted: boolean;
  readonly filters: JobFilterState;
  /** The status view in force, or `''` when the filters are something no button says. */
  readonly view: JobView | '';
  /** Whether the view is one of the two that describe work still in hand. */
  readonly inHand: boolean;
  /**
   * A search or facet is doing some of the narrowing. The dates are left out on
   * purpose: an empty window has its own advice, to widen it.
   */
  readonly narrowed: boolean;
  patch(next: Partial<JobFilterState>): void;
  clearFilters(): void;
  setView(next: JobView): void;
}

export function jobFilterState(): JobFilterHandle {
  /**
   * Nobody has asked this page anything yet, so it answers the question it is
   * opened with: what is running.
   *
   * Scoped to a URL with no filter at all, not to an absent `state`, because
   * seven of the ten links into these pages carry a filter and no state -- the
   * problems panel's unmatched link, the Overview's failed and outcome links,
   * a date range off the activity matrix. Each of those said what it wanted,
   * and narrowing it to running would answer a different question than the one
   * the sender asked. The address bar is left alone the way Queue's
   * provisioning statuses and Settings' tab are: an absent key means the
   * default, and pressing "All" writes every state out in full so that the two
   * stay distinguishable.
   */
  const defaulted = $derived.by(() => {
    const query = router.query;
    return !FILTER_KEYS.some((key) => query.has(key));
  });

  /**
   * Which of the queue's provisioning statuses to show.
   *
   * Validated rather than asserted, for the reason `state` is: the address bar
   * is whatever somebody pasted, and a cast would send the typo to the server
   * as a filter matching nothing.
   *
   * The default is the interesting part. A view narrowed to queued work means
   * "what is waiting for a runner here", and a job an operator removed from
   * the queue is not -- it stopped counting towards the queue depth on the
   * Overview and towards the Jobs page's own "Queued now" figure, so a list
   * that still carried it disagreed with the number directly above it. Every
   * other view narrows nothing: a removed job belongs in the history the page
   * is, badged as removed, and `All` has to show it. The filter is written
   * into the chips either way, so a shorter list always says why it is
   * shorter.
   */
  const provisioning = $derived.by<ProvisioningStatus[]>(() => {
    const asked = router
      .paramList('provisioning')
      .filter((v): v is ProvisioningStatus =>
        (PROVISIONING_STATUSES as readonly string[]).includes(v),
      );
    if (asked.length > 0) return asked;
    const states = defaulted ? [...DEFAULT_JOB_STATE] : router.paramList('state');
    return states.length === 1 && states[0] === 'queued' ? [...WAITING_PROVISIONING] : [];
  });

  const filters = $derived<JobFilterState>({
    q: router.param('q'),
    repo: router.paramList('repo'),
    workflow: router.paramList('workflow'),
    pool_id: router.paramList('pool_id'),
    label: router.paramList('label'),
    conclusion: router.paramList('conclusion'),
    // Validated rather than asserted: `?state=` is whatever was in the address
    // bar, and a cast sends the typo straight to the server as a filter that
    // matches nothing, so the page comes back empty with no explanation.
    state: defaulted
      ? [...DEFAULT_JOB_STATE]
      : router
          .paramList('state')
          .filter((value): value is JobState => (JOB_STATES as readonly string[]).includes(value)),
    provisioning,
    since: router.param('since'),
    until: router.param('until'),
    unmatched: router.param('unmatched') === 'true',
    failed: router.param('failed') === 'true',
    faulted: router.param('faulted') === 'true',
    all: router.param('all') === 'true',
  });

  const view = $derived(currentJobView(filters));

  /**
   * A job whose workflow run has been cancelled is neither waiting nor
   * running: the queued half raises no demand and the running half has had its
   * runner taken away. GitHub's completion delivery decides the conclusion and
   * can be minutes behind, and for that whole window the two views listed work
   * nobody was going to do -- beside the tiles above them, which had already
   * stopped counting it. Every other view is history and shows it, badged.
   */
  const inHand = $derived(view === 'queued' || view === 'running');

  /**
   * Whether an empty grid is the search's doing. The empty states speak for
   * the status view and the switches, and a search that matched nothing under
   * "running" used to be told "nothing is running right now" -- false while
   * other jobs ran -- or "no jobs have run on this fleet", with a switch that
   * cannot fix a search.
   */
  const narrowed = $derived(
    Boolean(filters.q) ||
      filters.repo.length > 0 ||
      filters.workflow.length > 0 ||
      filters.pool_id.length > 0 ||
      filters.label.length > 0 ||
      filters.conclusion.length > 0,
  );

  /**
   * Merge a filter change into the URL.
   *
   * Only the keys the caller actually passed are written: `setQuery` removes a
   * key whose value is undefined, so spreading a partial object would quietly
   * clear every filter it did not mention.
   */
  function patch(next: Partial<JobFilterState>): void {
    const out: Record<string, string | readonly string[] | null> = { offset: null };
    const choosingStatus = STATUS_KEYS.some((key) => next[key] !== undefined);

    /*
     * Narrowing something else never moves the status. The status in force is
     * written down as part of the same change, because it is only ever implied
     * by what is absent -- the default when nothing is asked, and "every
     * status" when a link asked for something narrower and said nothing about
     * status. Without this, one keystroke in the search box took the page from
     * "running" to every job the fleet has ever run, and removing the last chip
     * from a link that asked for every status took it the other way, down to
     * running. Both are the page answering a question nobody asked.
     */
    if (!choosingStatus) {
      out.state = filters.state.length > 0 ? filters.state : [...JOB_STATES];
    }

    /*
     * A view owns the queue statuses along with the rest of the status keys.
     * Pressing All after looking at what was removed from the queue has to
     * show everything, rather than keeping the narrower filter the last view
     * left behind; clearing the key lets the new view's own default apply.
     * Narrowing something else leaves it alone, because the operator was
     * still looking at that.
     */
    if (choosingStatus && next.provisioning === undefined) out.provisioning = null;

    /*
     * The two switches own the status they contradict, the way a view button
     * does. `unmatched` is queued-and-unclaimed on the server, so a state
     * beside it can only subtract -- and from the default view, where the
     * status has just been written down, `state=in_progress&unmatched=true`
     * matched nothing at all and left the operator on an empty page with no
     * sign of why. "Failed" is the server's own reckoning of a job that went
     * wrong, which is not a state either.
     */
    if (next.unmatched === true) {
      out.state = [];
      out.conclusion = [];
    }
    if (next.failed === true) out.state = [];
    if (next.faulted === true) out.state = [];

    for (const [key, value] of Object.entries(next)) {
      if (typeof value === 'boolean') out[key] = value ? 'true' : null;
      else if (Array.isArray(value)) out[key] = value;
      else out[key] = (value as string) || null;
    }
    router.setQuery(out);
  }

  /**
   * Clearing every filter is a return to the default view, not to everything:
   * a page with nothing asked of it is the page an operator arrives at, and
   * "All" is one button away and says so.
   */
  function clearFilters(): void {
    router.setQuery({ ...Object.fromEntries(FILTER_KEYS.map((k) => [k, null])), offset: null });
  }

  function setView(next: JobView): void {
    const chosen = JOB_VIEWS.find((v) => v.id === next);
    if (chosen) patch(chosen.filters);
  }

  return {
    get defaulted() {
      return defaulted;
    },
    get filters() {
      return filters;
    },
    get view() {
      return view;
    },
    get inHand() {
      return inHand;
    },
    get narrowed() {
      return narrowed;
    },
    patch,
    clearFilters,
    setView,
  };
}

/**
 * The provisioning controls, in one place.
 *
 * Run now, Pause, Resume and Delete from queue are what the Queue page is
 * for, and the first three are offered again on the Workflows page -- on a
 * run's own row, for every queued job of it at once, and on each job inside
 * an opened run. Three pages naming one action three ways is how an operator
 * comes to believe there are three actions, so the verbs, the icons, the
 * reason each gives when it is already in force, and what the confirmation
 * says all come from here.
 */
import { Pause, Play, Trash2, Zap } from '@lucide/svelte';
import type { Body, Job } from '$lib/api/types';
import { QUEUE_STATUS_LABELS } from '$lib/status';
import type { RowAction } from '$lib/components/RowActions.svelte';

export type ProvisioningAction = Body<'controlProvisioning'>['action'];
/** The actions a whole run offers: everything but removal, which is a decision about one job. */
export type RunProvisioningAction = Body<'controlWorkflowRunProvisioning'>['action'];

export interface ProvisioningActionMeta {
  id: ProvisioningAction;
  label: string;
  icon: typeof Zap;
  danger?: boolean;
}

export const PROVISIONING_ACTIONS: readonly ProvisioningActionMeta[] = [
  { id: 'run_now', label: 'Run now', icon: Zap },
  { id: 'pause', label: 'Pause', icon: Pause },
  { id: 'resume', label: 'Resume', icon: Play },
  { id: 'delete', label: 'Delete from queue', icon: Trash2, danger: true },
];

/** The three a run's row offers, in the same order the Queue page puts them. */
export const RUN_PROVISIONING_ACTIONS: readonly ProvisioningActionMeta[] =
  PROVISIONING_ACTIONS.filter((a) => a.id !== 'delete');

export function provisioningActionLabel(action: ProvisioningAction | undefined): string {
  return PROVISIONING_ACTIONS.find((a) => a.id === action)?.label ?? 'Update provisioning';
}

/**
 * Why an action is refused on a job it is already in force on. A control
 * that refuses without a reason is a control that gets reported as broken.
 */
export const PROVISIONING_IN_FORCE: Record<ProvisioningAction, string> = {
  run_now: 'Already prioritised to run now.',
  pause: 'Already paused.',
  resume: 'Already provisioning normally, with nothing to restore.',
  delete: 'Already removed from the queue.',
};

/** What the confirmation says the action will do, for one item or many. */
export function provisioningDescription(action: ProvisioningAction | undefined): string {
  switch (action) {
    case 'pause':
      return 'Hold new runner demand for these items until you resume them.';
    case 'delete':
      return 'Remove these items from provisioning demand, so they stop counting as queued work anywhere. You can restore them from the Removed view.';
    case 'run_now':
      return 'Resume and prioritise these items within their pool priority, without waiting for the scale-up delay.';
    default:
      return 'Restore normal provisioning demand and clear any Run now priority.';
  }
}

/** The status a queued job's demand is in, in the Queue page's four words. */
export function provisioningStatus(
  job: Pick<Job, 'provisioning' | 'provision_now'>,
): keyof typeof QUEUE_STATUS_LABELS {
  if (job.provisioning === 'paused' || job.provisioning === 'deleted') return job.provisioning;
  return job.provision_now ? 'expedited' : 'ready';
}

/** Whether an action on a job in this status would change nothing. */
export function provisioningInForce(
  action: ProvisioningAction,
  status: keyof typeof QUEUE_STATUS_LABELS,
): boolean {
  return (
    (action === 'pause' && status === 'paused') ||
    (action === 'delete' && status === 'deleted') ||
    (action === 'run_now' && status === 'expedited') ||
    (action === 'resume' && status === 'ready')
  );
}

/**
 * Why a job cannot have its demand controlled at all, or nothing when it
 * can. Only a queued job this fleet has a hand in raises demand: once
 * something has started it there is nothing to hold, and a job whose labels
 * all name somebody else's runners was never this fleet's to hurry.
 */
export function provisioningUnavailable(
  job: Pick<Job, 'state' | 'matched' | 'hosted' | 'runner_id' | 'cancel_requested_at'>,
): string | undefined {
  if (job.cancel_requested_at)
    return 'Its workflow run is being cancelled; the fleet has already stood it down.';
  if (job.state === 'completed') return 'This job has already finished.';
  if (job.state === 'in_progress') return 'This job is already running.';
  if (job.state === 'waiting')
    return 'This job is waiting for a review or an environment, not for a runner.';
  if (job.hosted && !job.matched && !job.runner_id)
    return 'This job runs on somebody else’s runners, so there is no demand here to shape.';
  return undefined;
}

/**
 * The row actions for one job, in the Queue page's order, each refused with
 * a reason where it would change nothing. `include` narrows the set: the
 * Workflows page leaves removal to the Queue page.
 */
export function jobProvisioningActions(
  job: Pick<
    Job,
    | 'state'
    | 'matched'
    | 'hosted'
    | 'runner_id'
    | 'cancel_requested_at'
    | 'provisioning'
    | 'provision_now'
  >,
  onSelect: (action: ProvisioningAction) => void,
  include: readonly ProvisioningActionMeta[] = PROVISIONING_ACTIONS,
): RowAction[] {
  const unavailable = provisioningUnavailable(job);
  const status = provisioningStatus(job);
  return include.map((a) => {
    const inForce = provisioningInForce(a.id, status);
    return {
      id: a.id,
      label: a.label,
      icon: a.icon,
      danger: a.danger,
      disabled: Boolean(unavailable) || inForce,
      reason: unavailable ?? (inForce ? PROVISIONING_IN_FORCE[a.id] : undefined),
      onSelect: () => onSelect(a.id),
    };
  });
}

/**
 * The Jobs page's status views.
 *
 * Status is the filter this page is opened for -- "what is running now", "what
 * went wrong" -- and it used to be three clicks down a facet menu. A view is a
 * whole answer rather than one value of one key, because the questions an
 * operator asks are not all the same key: "Failed" is the server's own
 * reckoning of a job that went wrong, which includes a runner that died under
 * one, and no conclusion value says that.
 *
 * Each view therefore writes every status-shaped key, so pressing a button
 * gives exactly the view it names and never half of the last one. The narrower
 * filters -- repository, workflow, pool, labels, dates -- are untouched, so
 * switching view keeps the operator where they were looking.
 */
import { JOB_STATES, type JobState } from '../api/types';
import { jobStatus, RUNNER_LOST, type StatusMeta } from '../status';

export type JobView = 'running' | 'queued' | 'failed' | 'faulted' | 'finished' | 'all';

/** The keys a view owns outright. Everything else on the page is orthogonal to it. */
export interface JobStatusFilters {
  state: JobState[];
  conclusion: string[];
  failed: boolean;
  /** The half of `failed` this fleet caused, rather than the workflows. */
  faulted: boolean;
  unmatched: boolean;
}

export interface JobViewDef {
  id: JobView;
  label: string;
  /** The status whose shape and colour the button wears, where one fits. */
  status?: StatusMeta;
  /** One line an operator can act on, for the tooltip. */
  hint: string;
  filters: JobStatusFilters;
}

const NOTHING: JobStatusFilters = {
  state: [],
  conclusion: [],
  failed: false,
  faulted: false,
  unmatched: false,
};

/**
 * The order is the lifecycle an operator reads left to right -- running, then
 * waiting, then what went wrong, then what is done -- with the way out on the
 * end. "All" is last because it is the widest, not because it is the default.
 */
export const JOB_VIEWS: readonly JobViewDef[] = [
  {
    id: 'running',
    label: 'Running',
    status: jobStatus('in_progress'),
    hint: 'Jobs a runner is working on right now.',
    filters: { ...NOTHING, state: ['in_progress'] },
  },
  {
    id: 'queued',
    label: 'Queued',
    status: jobStatus('queued'),
    hint: 'Jobs GitHub has queued and nothing has started yet.',
    filters: { ...NOTHING, state: ['queued'] },
  },
  {
    id: 'failed',
    label: 'Failed',
    status: jobStatus('completed', 'failure'),
    hint: 'Failing conclusions, and runners that stopped under a job.',
    filters: { ...NOTHING, failed: true },
  },
  {
    /*
     * The half of "Failed" that is this deployment's doing. It sits beside it
     * rather than inside a facet menu because it is the question somebody
     * arrives with -- "is CI broken, or is our CI broken" -- and because it is
     * the only one of the two that anybody here can fix.
     */
    id: 'faulted',
    label: 'Our failures',
    status: RUNNER_LOST,
    hint: 'Failures this fleet caused: a runner that never started, or one that stopped under the job. GitHub records these as ordinary failures, so nothing on GitHub tells them apart.',
    filters: { ...NOTHING, faulted: true },
  },
  {
    id: 'finished',
    label: 'Finished',
    status: jobStatus('completed'),
    hint: 'Every job that has ended, however it ended.',
    filters: { ...NOTHING, state: ['completed'] },
  },
  {
    id: 'all',
    /*
     * Written out in full rather than left absent, because an absent `state`
     * is what the page's default reads as "running". Four repeated keys in the
     * address bar is the price of "all" and "ask me nothing" being different
     * things, and it is the shape Queue's provisioning statuses already use.
     */
    label: 'All',
    hint: 'Every job in this view, whatever its status.',
    filters: { ...NOTHING, state: [...JOB_STATES] },
  },
];

/**
 * What a page nobody has asked anything of shows.
 *
 * Running is the question this page is opened with, so it is what the page
 * answers before being asked. It applies to a bare `/jobs` only: a link that
 * carries a filter has already said what it wants, and narrowing it to running
 * would answer a different question than the one the sender asked.
 */
export const DEFAULT_JOB_STATE: readonly JobState[] = ['in_progress'];

function sameSet(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && [...a].sort().join() === [...b].sort().join();
}

/**
 * A state filter reduced to what it actually narrows. No states and every
 * state narrow nothing, so both are the same view -- which is what lets "All"
 * write itself out in full without becoming a view of its own.
 */
function narrowing(state: readonly string[]): string {
  const set = [...new Set(state)].sort();
  return set.length === 0 || set.length >= JOB_STATES.length ? '' : set.join(',');
}

/**
 * Which view the filters currently in force are, or `''` when they are
 * something a button does not say -- a conclusion facet, the unmatched
 * switch, two states at once. No button is pressed then, which is the truth:
 * the chips above the grid are what is narrowing it.
 */
export function currentJobView(value: JobStatusFilters): JobView | '' {
  for (const view of JOB_VIEWS) {
    if (
      narrowing(value.state) === narrowing(view.filters.state) &&
      sameSet(value.conclusion, view.filters.conclusion) &&
      value.failed === view.filters.failed &&
      value.faulted === view.filters.faulted &&
      value.unmatched === view.filters.unmatched
    ) {
      return view.id;
    }
  }
  return '';
}

/**
 * Keyboard plumbing: the layer stack, the focus trap, and the global shortcuts
 * from docs/ui-guidelines.md section 4.
 *
 * The layer stack exists so that Escape closes exactly one thing. A dropdown
 * inside a dialog inside the command palette must unwind in the order it was
 * opened, and every overlay in the inventory registers itself here rather than
 * listening for Escape on its own.
 */

/** Overlay kinds, in the order they tend to nest. */
export type LayerKind = 'dropdown' | 'palette' | 'sheet' | 'drawer' | 'dialog' | 'tooltip';

export interface Layer {
  id: number;
  kind: LayerKind;
  close: () => void;
}

let nextLayerId = 1;
const stack: Layer[] = [];

export const layers = {
  /** Register an open overlay. Returns the id to hand back to `remove`. */
  push(kind: LayerKind, close: () => void): number {
    const id = nextLayerId++;
    stack.push({ id, kind, close });
    return id;
  },
  /** Deregister an overlay, whether it closed itself or was closed for it. */
  remove(id: number): void {
    const i = stack.findIndex((l) => l.id === id);
    if (i >= 0) stack.splice(i, 1);
  },
  top(): Layer | undefined {
    return stack[stack.length - 1];
  },
  /** Close the topmost overlay. Returns false when there was nothing to close. */
  closeTop(): boolean {
    const layer = stack[stack.length - 1];
    if (!layer) return false;
    layer.close();
    return true;
  },
  get size(): number {
    return stack.length;
  },
};

/* -- focus ---------------------------------------------------------------- */

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
  'summary',
].join(',');

/** The panels currently trapping focus, outermost first. */
const traps: HTMLElement[] = [];

/** Every focusable descendant, in document order, skipping hidden ones. */
export function focusableWithin(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    (el) => el.offsetParent !== null || el.getClientRects().length > 0,
  );
}

/**
 * A Svelte action that traps Tab inside `node` and restores focus to whatever
 * was focused before, on teardown. Dialogs and drawers both use it; nothing
 * else should need to.
 */
export function trapFocus(node: HTMLElement, initial?: HTMLElement | null) {
  const restoreTo = document.activeElement as HTMLElement | null;
  traps.push(node);

  function focusFirst(): void {
    const target =
      initial ??
      node.querySelector<HTMLElement>('[data-autofocus]') ??
      focusableWithin(node)[0] ??
      node;
    target.focus();
  }

  function onKeydown(e: KeyboardEvent): void {
    if (e.key !== 'Tab') return;
    // Only the innermost open overlay owns Tab. Two traps on separate
    // subtrees -- a confirmation dialog raised from inside a drawer -- each
    // pulled focus into their own panel, so every Tab in the dialog landed
    // on its first control.
    if (traps[traps.length - 1] !== node) return;
    const items = focusableWithin(node);
    if (items.length === 0) {
      e.preventDefault();
      node.focus();
      return;
    }
    const first = items[0];
    const last = items[items.length - 1];
    if (!first || !last) return;
    const active = document.activeElement;
    // Focus can be outside the panel entirely -- the browser blurs an element
    // that becomes hidden or unavailable, and lands on <body>. From there a
    // Tab would walk the page behind an open modal, so it is pulled back in
    // rather than let go.
    if (!node.contains(active)) {
      e.preventDefault();
      (e.shiftKey ? last : first).focus();
      return;
    }
    if (e.shiftKey && active === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && active === last) {
      e.preventDefault();
      first.focus();
    }
  }

  if (!node.hasAttribute('tabindex')) node.setAttribute('tabindex', '-1');
  // Listened for on the document, in capture, rather than on the panel: a
  // keystroke made while focus has slipped outside the panel never reaches a
  // handler bound to the panel, which is exactly the case the pull-back above
  // exists to answer.
  document.addEventListener('keydown', onKeydown, true);
  // A frame's delay lets a transition finish laying the panel out first.
  requestAnimationFrame(focusFirst);

  return {
    destroy(): void {
      document.removeEventListener('keydown', onKeydown, true);
      const i = traps.lastIndexOf(node);
      if (i >= 0) traps.splice(i, 1);
      // A frame's delay, because the overlay's own teardown also clears the
      // `inert` it put on the rest of the page, and an inert element cannot
      // take focus -- restoring in the same turn silently did nothing.
      requestAnimationFrame(() => {
        // An overlay opened by a redirect rather than a click -- GitHub sending
        // the operator back with a code in the URL -- was focused on <body>
        // when it mounted, and focusing <body> back is a no-op that leaves the
        // keyboard at the very top of the document. Fall back to the page's own
        // landing points, the same chain a route change uses.
        const target =
          restoreTo && restoreTo !== document.body && document.contains(restoreTo)
            ? restoreTo
            : (document.getElementById('page-heading') ?? document.getElementById('main'));
        target?.focus();
      });
    },
  };
}

/* -- global shortcuts ------------------------------------------------------ */

export const isMac =
  typeof navigator !== 'undefined' &&
  /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent);

/** The modifier label for this platform: ⌘ on a Mac, Ctrl everywhere else. */
export const modKey = isMac ? '⌘' : 'Ctrl';

/** True when the event target is somewhere a bare letter means "type a letter". */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  const tag = target.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
}

/** The `g` then letter jumps, in the order the navigation lists them. */
export const GO_KEYS: ReadonlyArray<{ key: string; path: string; label: string }> = [
