/**
 * Whether one repository in a plan can be migrated, and why not when it cannot.
 *
 * This lives on its own because two places need the same answer: the
 * Repositories step, which decides what an operator may tick, and the wizard,
 * which decides what to tick by default and which repositories to name in the
 * call that opens the pull requests. Those two disagreeing is how a repository
 * that is greyed out on screen ends up in the request anyway.
 */

import type { MigrationRepo } from '$lib/api/types';

/** The API's MaxApplyRepos limit: a migration opens at most this many pull requests. */
export const MAX_SELECTED_REPOSITORIES = 25;

/** How many runs-on lines the migration would rewrite in this repository. */
export function jobsIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).reduce((n, w) => n + (w.rewrites ?? []).length, 0);
}

/** How many files it would change. */
export function filesIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).filter((w) => (w.rewrites ?? []).length > 0).length;
}

/** How many runs-on lines it would deliberately leave alone. */
export function skipsIn(repo: MigrationRepo): number {
  return (repo.workflows ?? []).reduce((n, w) => n + (w.skips ?? []).length, 0);
}

/**
 * Whether this repository is one the operator can choose.
 *
 * The test is "it asks for a runner somebody else operates", not "it would
 * change under the mapping guessed so far" -- the labels are mapped on the
 * next step. Being archived is the exception worth spelling out: an archived
 * repository can ask for as many rented runners as it likes, and GitHub still
 * refuses every write to it, so counting its labels alone would tick it, walk
 * the operator through mapping and review, and only then report that nothing
 * could be opened.
 */
export function isMigratable(repo: MigrationRepo): boolean {
  return !repo.error && !repo.archived && (repo.hosted_labels ?? []).length > 0;
}

/**
 * One line saying what this repository would get out of the migration, or why
 * it is not on offer.
 *
 * The order is the order an operator needs the answers in: a repository that
 * could not be read explains itself first, one that cannot be written to next,
 * then what would change, then what was found but not yet mapped -- and only
 * then the several different ways of having nothing to do. "Already on
 * Zoomies" and "nothing to move" look identical in a plan and mean opposite
 * things -- finished work, and work nobody has started -- so they are never
 * collapsed into one sentence.
 */
export function noteFor(repo: MigrationRepo): string {
  if (repo.error) return repo.error;
  if (repo.archived) return 'Archived — accepts no pull requests';

  const jobs = jobsIn(repo);
  const files = filesIn(repo);
  const skipped = skipsIn(repo);
  const labels = repo.hosted_labels ?? [];

  if (jobs > 0) {
    const moved = `${jobs} ${jobs === 1 ? 'job' : 'jobs'} in ${files} ${files === 1 ? 'file' : 'files'}`;
    return repo.on_zoomies ? `${moved}; the rest already on Zoomies` : moved;
  }
  if (labels.length > 0) {
    return `Runs on ${labels.join(', ')}; choose what those become on the next step`;
  }
  if ((repo.workflows ?? []).length === 0) return 'No workflows';
  if (repo.on_zoomies) {
    return skipped > 0 ? `Already on Zoomies; ${skipped} left alone` : 'Already on Zoomies';
  }
  return skipped > 0 ? `Nothing to move; ${skipped} left alone` : 'Nothing to move';
}

/**
 * How a finished job is counted. Kept apart from the state map in status.ts,
 * which imports icon components and so cannot be loaded outside a browser,
 * because the activity matrix's arithmetic counts jobs the same way and is
 * tested in Node.
 */

/** The conclusions GitHub counts as a job going wrong, as the failed filter does. */
export const FAILING_CONCLUSIONS: ReadonlySet<string> = new Set([
  'failure',
  'timed_out',
  'startup_failure',
]);

/** The four ways a completed job is counted, matching the store's split. */
export type Outcome = 'succeeded' | 'failed' | 'cancelled' | 'unknown';

/**
 * Whether a job went wrong on either side: a failing conclusion, or a runner
 * that stopped under it -- including one GitHub still believes is running.
 */
export function jobFailed(job: {
  conclusion?: string | null;
  runner_fault?: string | null;
}): boolean {
  return Boolean(job.runner_fault) || FAILING_CONCLUSIONS.has((job.conclusion ?? '').toLowerCase());
}

/**
 * Which of the four counts a finished job lands in. Unknown is never a
 * success: a job GitHub stopped reporting is not a job that went well.
 */
export function outcomeOf(job: {
  conclusion?: string | null;
  runner_fault?: string | null;
}): Outcome {
  if (jobFailed(job)) return 'failed';
  const conclusion = (job.conclusion ?? '').toLowerCase();
  if (conclusion === 'success') return 'succeeded';
  if (conclusion === 'cancelled' || conclusion === 'skipped') return 'cancelled';
  return 'unknown';
}

/**
 * The one place the browser knows how long a password has to be.
 *
 * It is `auth.MinPasswordLength` in Go and `minLength: 12` in
 * api/openapi.yaml, and it was a literal in two Svelte components that had no
 * way of noticing when it changed. Length rather than a zoo of character
 * classes is the deliberate choice -- see internal/auth/auth.go, which explains
 * why.
 */
export const MIN_PASSWORD_LENGTH = 12;

/**
 * A hint that helps rather than scolds. It counts up to the minimum and then
 * says what actually makes a password stronger, which is more of it.
 */
export function passwordStrength(password: string): string {
  if (password.length === 0) {
    return `At least ${MIN_PASSWORD_LENGTH} characters. A phrase works well.`;
  }
  if (password.length < MIN_PASSWORD_LENGTH) {
    return `${password.length} of ${MIN_PASSWORD_LENGTH} characters.`;
  }
  // Length is the thing worth asking for, and the one thing it cannot promise
  // is variety: twenty of the same character is twenty characters long, and
  // calling that "Strong." on the account that owns the whole fleet is the one
  // claim this hint is not entitled to make.
  if (new Set(password).size < 6) {
    return 'Long, but it repeats. A few unrelated words beat one character held down.';
  }
  if (password.length < 20) return 'Good. Longer is stronger than more punctuation.';
  return 'Long enough. Store it somewhere you will still have it next month.';
}

/**
 * What deleting a pool will actually do, in the order an operator cares about.
 *
 * Both places that offer the deletion -- the list and the pool's own page --
 * showed this, in two copies that had to be kept in step by hand. The wording
 * is deliberate: it names what happens to *running work* rather than to rows,
 * because the difference between "drained, then removed" and "destroyed
 * immediately" is somebody's build.
 */
import { pluralise } from '$lib/format';

export interface PoolCounts {
  live?: number;
  busy?: number;
  /** Jobs still queued and matched to this pool -- not yet on a runner. */
  queued?: number;
}

export function deletionConsequences(counts: PoolCounts, force: boolean): string[] {
  const live = counts.live ?? 0;
  const busy = counts.busy ?? 0;
  const queued = counts.queued ?? 0;
  const lines = [
    live === 0
      ? 'It has no runners right now, so nothing is interrupted.'
      : force
        ? `${pluralise(live, 'runner')} will be destroyed immediately.`
        : `${pluralise(live, 'runner')} will be drained, then removed.`,
  ];
  if (busy > 0) {
    lines.push(
      force
        ? `${pluralise(busy, 'job')} running right now will be interrupted.`
        : `${pluralise(busy, 'job')} running right now will be allowed to finish first.`,
    );
  }
  if (queued > 0) {
    lines.push(
      `${pluralise(queued, 'queued job')} asking for this pool will be removed from the queue too, ` +
        'the same as deleting it from the Queue page. You can restore it from the Removed view.',
    );
  }
  lines.push('The runners are deregistered from GitHub either way.');
  return lines;
}

import type { Host } from '$lib/api/types';

/** The selector keys a host answers for from its agent's report, not a label. */
export const REPORTED_KEYS = ['os', 'arch'] as const;

/** Mirrors Host.SelectorValue in the Go store. */
export function hostSelectorValue(host: Host, key: string): string {
  const labels = host.labels ?? {};
  if (key in labels) return labels[key] ?? '';
  if (key === 'os') return host.os ?? '';
  if (key === 'arch') return host.arch ?? '';
  return '';
}

/** Whether a host satisfies every entry of a selector. Empty means any host. */
export function hostMatchesSelector(host: Host, selector: Record<string, string>): boolean {
  return Object.entries(selector).every(([key, value]) => hostSelectorValue(host, key) === value);
}

/** Values currently reported for a selector key, including a disconnected saved value. */
export function reportedValues(
  hosts: readonly Host[],
  key: string,
  extra: string,
): { value: string; hosts: number }[] {
  const counts: Record<string, number> = {};
  for (const host of hosts) {
    const value = hostSelectorValue(host, key);
    if (value) counts[value] = (counts[value] ?? 0) + 1;
  }
  if (extra && counts[extra] === undefined) counts[extra] = 0;
  return Object.entries(counts)
    .map(([value, count]) => ({ value, hosts: count }))
    .sort((a, b) => b.hosts - a.hosts || a.value.localeCompare(b.value));
}

/**
 * The name a new pool arrives with, and the dice that roll another one.
 *
 * A blank name field is the first thing an operator meets in the wizard, and
 * the name they invent to get past it -- "test", "pool1" -- is then in every
 * runner name, every audit line and every `runs-on` for the life of the fleet.
 * Renaming a pool later does not un-write the workflows that already point at
 * it. So the wizard fills one in instead.
 *
 * The name it fills in is the pool's shape -- `zoomies-4vcpu-ubuntu-2404`, the
 * grammar in docs/naming.md -- because that is what a workflow author reading a
 * `runs-on` needs to know before they send a job to it, and because it is the
 * same name `zoomies init` suggests for a machine of that size. The wizard used
 * to lead with a kennel word instead, which left an operator who met both with
 * two conventions for one thing.
 *
 * The spaniel is still here, and still earns its place: it is what tells two
 * pools of the same shape apart, and what names a pool created before anything
 * about it is known. The brand prefix is not optional either -- it is what marks
 * a runner in the GitHub UI as ours rather than GitHub's.
 */

import type { BackendKind, Host } from '$lib/api/types';
import { RUNNER_NAME_PREFIX, sanitizeLabel } from '$lib/brand';

/**
 * Cocker spaniels, as cocker spaniels are actually named.
 *
 * The mark is a cocker spaniel doing zoomies, so the fleet is a kennel. Every
 * word here is one segment of lowercase letters -- no spaces, nothing to
 * sanitise away -- and short enough that the infrastructure half of the name
 * survives the length budget below.
 */
export const KENNEL: readonly string[] = [
  'banjo',
  'biscuit',
  'boogie',
  'bramble',
  'bubbles',
  'cocoa',
  'crumpet',
  'custard',
  'digby',
  'disco',
  'flapjack',
  'gizmo',
  'hazel',
  'jellybean',
  'jitterbug',
  'maple',
  'marmalade',
  'muffin',
  'noodle',
  'pancake',
  'pepper',
  'pickles',
  'popcorn',
  'rascal',
  'rocket',
  'rusty',
  'scampi',
  'toffee',
  'truffle',
  'waffles',
  'wiggles',
  'ziggy',
];

/**
 * How long a generated name may be.
 *
 * `sanitizeLabel` truncates at 40 characters, so a longer name would produce a
 * label that is a chopped-off version of it -- two strings an operator has to
 * hold in their head at once, for no gain.
 */
const MAX_NAME = 40;

/** The value every entry agrees on, or "" when they do not all agree. */
function agreed(values: readonly (string | undefined)[]): string {
  let found = '';
  for (const value of values) {
    const clean = sanitizeLabel(value ?? '');
    if (clean === '') continue;
    if (found === '') found = clean;
    else if (found !== clean) return '';
  }
  return found;
}

function offersBackend(host: Host, backend: BackendKind): boolean {
  const info = (host.backend_info ?? []).find((entry) => entry.kind === backend);
  return info?.available === true || (host.backends ?? []).includes(backend);
}

/**
 * The size every pool in this fleet gets unless it says otherwise.
 *
 * It is passed in rather than assumed because it is a fleet setting, and
 * because of what the name does with it: a figure every pool shares says
 * nothing about any of them. See `shape`.
 */
export interface FleetSize {
  cpus?: number;
  memory_mb?: number;
}

/**
 * The parts of a draft a name is made of.
 *
 * Structural rather than the wizard's own PoolDraft, so this module owes the
 * wizard nothing: a draft satisfies it by having the fields, and the naming
 * rules can be read without opening a component.
 */
export interface NameShape {
  backend: BackendKind;
  /**
   * How the pool decides its runners' size. A pool that leaves it to the host
   * has no size to be named for: its runners are 3.8 cores here and 7.6 on the
   * next machine to join, so `4vcpu` in the name would be a promise it stopped
   * keeping the day the fleet grew.
   */
  sizing: 'automatic' | 'fixed';
  cpus: string;
  memory_mb: string;
  platform_os: string;
  platform_os_version: string;
  platform_arch: string;
}

/**
 * A version with its dots taken out: 24.04 becomes 2404, 12 stays 12.
 *
 * The same rule as naming.CompactVersion in Go, because the name a pool is
 * suggested here has to be the name `zoomies init` would suggest for the same
 * machine -- an operator who meets both should meet one convention.
 */
function compactVersion(v: string): string {
  return v
    .trim()
    .split(/[._]/)
    .slice(0, 2)
    .map((part) => part.replace(/\D/g, ''))
    .join('');
}

/**
 * What a pool of this draft is made of, most significant part first.
 *
 * This is the shape half of the grammar in docs/naming.md: how much machine,
 * running what. The draft's own fields win, and where it has not said, the
 * connected hosts answer -- but only when every host that could run this pool
 * agrees, because a name that picked one of two answers is a name that lies
 * about half the fleet.
 *
 * Architecture follows the same rule the rest of the grammar does: amd64 is the
 * overwhelming default and saying it on every pool stops the word carrying
 * information, so only the others are spelled out.
 */
export function shape(
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string[] {
  const parts: string[] = [];

  // Size is stated when the pool has one of its own and it is not what every
  // pool here gets. Naming it unconditionally would put the same two words on
  // every pool in the fleet -- which is the argument that keeps amd64 out of
  // these names, applied to the figure it applies to twice as hard. A pool
  // that asks for more than the fleet's usual is exactly the pool a workflow
  // author is choosing, and it says so.
  //
  // A pool that leaves the size to its host says nothing at all: the figure
  // the sliders happen to be holding is not this pool's, and a name built from
  // it would advertise a size the pool does not have on any machine.
  if (draft.sizing !== 'automatic') {
    const cpus = Math.ceil(Number(draft.cpus));
    if (Number.isFinite(cpus) && cpus > 0 && cpus !== defaultCPUs(fleetDefault)) {
      parts.push(`${cpus}vcpu`);
    }
    const gb = Math.floor(Number(draft.memory_mb) / 1024);
    if (Number.isFinite(gb) && gb > 0 && gb !== defaultGB(fleetDefault)) parts.push(`${gb}gb`);
  }

  const offering = hosts.filter((host) => offersBackend(host, draft.backend));
  const from = offering.length > 0 ? offering : hosts;

  const os = sanitizeLabel(draft.platform_os) || agreed(from.map((host) => host.platform?.os));
  if (os !== '') {
    parts.push(os);
    const version =
      compactVersion(draft.platform_os_version) ||
      compactVersion(unanimous(from.map((host) => host.platform?.os_version)));
    if (version !== '') parts.push(version);
  }

  const arch =
    sanitizeLabel(draft.platform_arch) || agreed(from.map((host) => host.platform?.arch));
  if (arch !== '' && arch !== 'amd64') parts.push(arch);

  return parts;
}

/**
 * The fleet's default in the units a name is written in: whole cores rounded
 * the way a pool's own figure is, and whole gigabytes. A fleet that has not
 * said, or a call that did not pass it, has no default to compare against and
 * every figure is worth stating.
 */
function defaultCPUs(fleetDefault?: FleetSize | null): number {
  const cpus = fleetDefault?.cpus;
  return cpus !== undefined && cpus > 0 ? Math.ceil(cpus) : -1;
}

function defaultGB(fleetDefault?: FleetSize | null): number {
  const mb = fleetDefault?.memory_mb;
  return mb !== undefined && mb > 0 ? Math.floor(mb / 1024) : -1;
}

/** The raw value every entry agrees on, before sanitising, or "". */
function unanimous(values: readonly (string | undefined)[]): string {
  let found = '';
  for (const value of values) {
    const clean = (value ?? '').trim();
    if (clean === '') continue;
    if (found === '') found = clean;
    else if (found !== clean) return '';
  }
  return found;
}

/**
 * The name for a pool of this draft, and the kennel word it falls back on.
 *
 * A pool is named for its shape, which is the same name `zoomies init` prints
 * for a machine of that size and platform -- so the wizard and the installer
 * stop offering an operator two conventions for the same thing.
 *
 * The kennel word earns its place where the shape cannot carry the name on its
 * own. A pool created before anything about it is known has no shape to be
 * named for, and two pools of the same shape are two pools GitHub needs two
 * names for; in both cases a spaniel tells them apart, which
 * `zoomies-4vcpu-ubuntu-2404-2` never would.
 *
 * Over budget, the least significant parts go first -- architecture, then the
 * release, then the operating system -- because the size is what an operator is
 * choosing between and the word is what they recognise the pool by.
 */
export function poolName(
  word: string,
  draft: NameShape,
  hosts: readonly Host[],
  taken: readonly string[] = [],
  fleetDefault?: FleetSize | null,
): string {
  const parts = named(draft, hosts, fleetDefault);
  const spelled = new Set(taken.map((name) => sanitizeLabel(name)));
  const bare = fit(parts);
  if (parts.length > 0 && !spelled.has(sanitizeLabel(bare))) return bare;
  return nicknamedPoolName(word, draft, hosts, fleetDefault);
}

/**
 * The same name with a spaniel in it whether it needs one or not.
 *
 * This is what the dice ask for. A pool whose shape is already unique is
 * offered a name without a word, so a button that only sometimes changed
 * anything would read as broken -- and an operator who wants a handle for a
 * pool is entitled to one without having to invent it themselves.
 */
export function nicknamedPoolName(
  word: string,
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string {
  return fit(named(draft, hosts, fleetDefault), sanitizeLabel(word) || 'pool');
}

/**
 * The shape, plus the marker a process-backend pool carries.
 *
 * That backend is a different thing to ask for at the same shape -- its jobs get
 * the host itself rather than a container -- and a workflow author choosing
 * between two pools needs the name to say which. `zoomies init` marks it the
 * same way.
 */
function named(
  draft: NameShape,
  hosts: readonly Host[],
  fleetDefault?: FleetSize | null,
): string[] {
  const parts = shape(draft, hosts, fleetDefault);
  if (draft.backend === 'process') parts.push('host');
  return parts;
}

/**
 * These parts as a branded name, dropping the least significant until it fits.
 *
 * `keep` is never dropped: when it is there at all it is the only thing telling
 * this pool from one of the same shape, so a budget that spent it would produce
 * the name it was added to avoid.
 */
function fit(parts: readonly string[], keep = ''): string {
  const kept = [...parts];
  const tail = keep === '' ? '' : `-${keep}`;
  while (kept.length > 0) {
    const candidate = RUNNER_NAME_PREFIX + kept.join('-') + tail;
    if (candidate.length <= MAX_NAME) return candidate;
    kept.pop();
  }
  return (RUNNER_NAME_PREFIX + keep).slice(0, MAX_NAME).replace(/-+$/, '');
}

/**
 * A word from the kennel, never the one already on screen.
 *
 * Rolling the dice and getting the same name back reads as a broken button,
 * so the previous word is taken out of the hat rather than left to chance.
 */
export function spinWord(previous?: string): string {
  const choices = KENNEL.filter((word) => word !== previous);
  const pool = choices.length > 0 ? choices : KENNEL;
  return pool[Math.floor(Math.random() * pool.length)] ?? 'biscuit';
}

/**
 * The notches a runner's size moves between, and the words for them.
 *
 * Pure, and imported by a unit test. The sliders exist because the three
 * figures they carry -- how much of a machine one runner gets, and how much
 * disk its cache may keep -- are the settings an operator is least equipped to
 * type into an empty box: a number field accepts 3000 MB as readily as 4096,
 * and neither the field nor the pool says which of them the hosts can actually
 * back. A notch is a value somebody has a reason to choose.
 *
 * The arithmetic that says how many runners a fleet has room for is the
 * controller's, not this file's: what a runner is charged is not always what
 * the pool says -- a docker-in-docker slot is charged for its sidecar too --
 * and a browser that worked it out again would disagree with where the fleet
 * actually places runners. This file's counting is only what a slider needs
 * before the server's answer lands.
 */

/**
 * The CPU notches: shares of a core below one, then whole cores, then the
 * steps a build machine is actually bought in. A quarter core is the floor the
 * API enforces -- below it the runner binary cannot keep up with its own job.
 */
export const CPU_NOTCHES: readonly number[] = [
  0.25, 0.5, 1, 1.5, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64,
];

/** The memory notches, in megabytes. 512 MB is the API's floor. */
export const MEMORY_NOTCHES: readonly number[] = [
  512, 1024, 2048, 3072, 4096, 6144, 8192, 12288, 16384, 24576, 32768, 49152, 65536, 98304, 131072,
];

/**
 * The disk notches, in gigabytes, with zero for "no limit".
 *
 * Disk is the one runner limit that is genuinely optional: it is advisory on
 * every backend, and what stops a host filling up is its own disk reserve
 * rather than a figure on a pool. A pool that asks for it is charged it, which
 * is why it belongs on the same panel as the other two.
 */
export const DISK_NOTCHES: readonly number[] = [
  0, 10, 20, 40, 60, 80, 120, 160, 240, 320, 480, 640,
];

/**
 * The cache notches, in gigabytes, with zero for "no limit". The limit is kept
 * by evicting whole entries between one runner and the next, so it is a
 * high-water mark on a host's disk rather than an allocation.
 */
export const CACHE_NOTCHES: readonly number[] = [
  0, 1, 2, 5, 10, 20, 30, 50, 75, 100, 150, 200, 300, 500,
];

const BYTES_PER_GB = 1024 * 1024 * 1024;

/** Bytes as the API carries a cache limit, from the gigabytes a slider moves in. */
export function cacheBytes(gb: number): number {
  return Math.round(gb * BYTES_PER_GB);
}

/**
 * The gigabytes a stored cache limit comes to. It is not snapped to a notch:
 * a limit typed as 7 GB is 7 GB, and the slider takes it in as a notch of its
 * own the way it takes any other figure set off the notches.
 */
export function cacheGb(bytes: number | undefined): number {
  if (!bytes || bytes <= 0) return 0;
  return Math.round((bytes / BYTES_PER_GB) * 100) / 100;
}

/** The notch nearest a value, so a figure typed elsewhere lands on the slider. */
export function nearest(notches: readonly number[], value: number): number {
  let best = notches[0] ?? 0;
  for (const n of notches) {
    if (Math.abs(n - value) < Math.abs(best - value)) best = n;
  }
  return best;
}

/**
 * A notch list that includes a value the notches do not have.
 *
 * A pool created through the API, or before these sliders existed, can hold
 * 3000 MB; snapping it to 3072 the moment its page opens would change a pool
 * an operator came to read. The value joins the list instead, and the slider
 * moves off it onto the notches.
 */
export function withValue(notches: readonly number[], value: number): number[] {
  if (!Number.isFinite(value) || value <= 0 || notches.includes(value)) return [...notches];
  return [...notches, value].sort((a, b) => a - b);
}

/** "2 cores", "half a core", "1 core". */
export function cpuLabel(cpus: number): string {
  if (cpus === 0.5) return 'half a core';
  if (cpus === 0.25) return 'a quarter core';
  if (cpus === 1) return '1 core';
  return `${trimNumber(cpus)} cores`;
}

/** "4 GB", "512 MB". */
export function memoryLabel(mb: number): string {
  if (mb <= 0) return 'none';
  if (mb < 1024) return `${mb} MB`;
  return `${trimNumber(mb / 1024)} GB`;
}

/** "no limit" is a real answer for disk and for the cache, and reads as one. */
export function gbLabel(gb: number): string {
  return gb <= 0 ? 'no limit' : `${trimNumber(gb)} GB`;
}

function trimNumber(value: number): string {
  return value.toLocaleString(undefined, { maximumFractionDigits: 1 });
}

/** One runner's size as a phrase: "2 cores and 4 GB". */
export function sizeLabel(cpus: number, memoryMb: number): string {
  return `${cpuLabel(cpus)} and ${memoryLabel(memoryMb)}`;
}

/**
 * What a runner of this pool is charged, which is twice the size it was given
 * where the pool gives its jobs a daemon of their own: the build runs in that
 * daemon, so it is given the same limits and the machine carries the pair.
 *
 * It is asked only about a size somebody typed. A pool sized by its host puts
 * the runner and the daemon in one slot between them, so it is charged one --
 * a slot is one runner, whatever the runner brought with it.
 *
 * It is the figure the fleet's room is counted from, and the one an operator
 * reading "2 cores" against a ten-core host cannot otherwise arrive at.
 */
export function chargedSize(
  cpus: number,
  memoryMb: number,
  dockerMode: string | undefined,
): { cpus: number; memoryMb: number; pair: boolean } {
  const pair = dockerMode === 'dind';
  const factor = pair ? 2 : 1;
  return { cpus: cpus * factor, memoryMb: memoryMb * factor, pair };
}

/**
 * How many runners of a size a machine has room for, on an empty host.
 *
 * This is the browser's copy of the controller's arithmetic, and it is used
 * for one thing: the sentence under a slider while the server's own answer is
 * still in flight. Where the two disagree the server wins, because it knows
 * what the fleet is actually charged.
 */
export function roomOn(
  machine: { cpus: number; memoryMb: number },
  charge: { cpus: number; memoryMb: number },
): number {
  let room = Infinity;
  if (machine.cpus > 0 && charge.cpus > 0)
    room = Math.min(room, Math.floor(machine.cpus / charge.cpus));
  if (machine.memoryMb > 0 && charge.memoryMb > 0)
    room = Math.min(room, Math.floor(machine.memoryMb / charge.memoryMb));
  return Number.isFinite(room) ? Math.max(0, room) : 0;
}

/**
 * What ran out on a host, as the clause that follows what the machine is.
 *
 * The distinction it carries is the one an operator acts on: a host held to
 * fewer runners than its machine could take is an operator's own ceiling and
 * is working as asked, while one whose machine runs out first is a host that
 * will refuse creates for slots every page counts as free.
 */
export function limitPhrase(limitedBy: string | undefined): string {
  switch (limitedBy) {
    case 'cpu':
      return 'its cores run out first';
    case 'memory':
      return 'its memory runs out first';
    case 'disk':
      return 'its disk runs out first';
    case 'slots':
      return 'held there by its slot count';
    default:
      return '';
  }
}

import type { Problem, Settings } from '$lib/api/types';
import { parseGoDuration } from '$lib/format';

const remedies: Record<string, { key: string; value: unknown }> = {
  'scheduler.default_runner_limits_off': { key: 'scheduler.default_runner_limits', value: true },
  'scheduler.host_throttling_off': { key: 'scheduler.host_throttling', value: true },
  'agent.bootstrap_cpu_grace_short': { key: 'agent.bootstrap_cpu_grace', value: '2m' },
  'runners.docker_wait_short': { key: 'runners.docker_wait', value: '3m' },
  'scheduler.provision_timeout_short': { key: 'scheduler.provision_timeout', value: '20m' },
};
export function isStartupFinding(problem: Problem): boolean {
  return !!remedies[problem.code ?? ''];
}

/** Only fix current findings. Never write through an environment pin or clear a pending restart. */
export function startupFix(settings: Settings, problems: readonly Problem[]) {
  const changes: Record<string, unknown> = {};
  const blocked: string[] = [];
  const pending: string[] = [];
  for (const problem of problems) {
    const remedy = remedies[problem.code ?? ''];
    if (!remedy) continue;
    const row = settings.settings?.find((s) => s.key === remedy.key);
    if (
      !row?.editable ||
      row.source === 'environment' ||
      settings.pinned_by_environment?.includes(remedy.key)
    ) {
      blocked.push(remedy.key);
    } else if (row.pending) {
      pending.push(remedy.key);
    } else {
      changes[remedy.key] = remedy.value;
      if (remedy.key === 'scheduler.provision_timeout') {
        const wait = settings.settings?.find((s) => s.key === 'runners.docker_wait')?.value;
        const milliseconds = typeof wait === 'string' ? (parseGoDuration(wait) ?? 0) : 0;
        // Leave five minutes beyond creation and Docker readiness, including a
        // deliberately long wait. parseGoDuration returns milliseconds.
        changes[remedy.key] = `${Math.max(20, Math.ceil(milliseconds / 60000) + 15)}m`;
      }
    }
  }
  return { changes, blocked, pending };
}

/**
 * The smallest workflow that proves a fleet works.
 *
 * A new operator's first job used to need a real repository's workflow edited
 * and pushed, or the migration wizard, which opens pull requests on real
 * repositories. Neither is a thing to do to find out whether the thing you have
 * just installed runs a job at all. This is the alternative: a file that
 * touches nothing of theirs, starts by hand, and prints the one fact that says
 * where it ran.
 *
 * `workflow_dispatch` and not a push trigger, so the file does not fire on every
 * commit afterwards -- it is a probe, and it should sit there until somebody
 * presses the button.
 */
import { runsOn } from '../brand';

/** What the Actions tab lists it as. */
export const TEST_JOB_NAME = 'Zoomies test job';

/** Where it goes in a repository. */
export const TEST_JOB_FILE = '.github/workflows/zoomies-test.yml';

/**
 * The complete file for a pool with these labels.
 *
 * It asks for the pool by the same `runs-on` value everything else in the
 * product prints, so a pool labelled with several labels gets the list form and
 * the job reaches that pool and no other.
 */
export function testJobWorkflow(labels: readonly string[]): string {
  return [
    `name: ${TEST_JOB_NAME}`,
    'on: workflow_dispatch',
    'jobs:',
    '  hello:',
    `    runs-on: ${runsOn(labels)}`,
    '    steps:',
    // The sleep is the point of the third line: a job that finishes in
    // milliseconds is over before an operator has looked from GitHub to this
    // page, and they would see a runner appear and vanish without ever having
    // seen it busy.
    '      - run: |',
    '          echo "Hello from $(hostname)"',
    '          uname -a',
    '          sleep 5',
    '',
  ].join('\n');
}

/**
 * The provider wizard's draft, and the words it renders with.
 *
 * Pure, and in a `.ts` rather than in the form's `<script module>`, for one
 * reason: the unit tests run under Node with no Svelte compiler, so machinery
 * kept inside a component is machinery nothing can test without a browser.
 * `PoolWizardForm.svelte` keeps its draft in a module block for the same
 * purpose; this is the same idea one file further out.
 *
 * Numbers are held as strings because that is what a text input gives back,
 * and because '' and '0' are different answers -- one is "not filled in", the
 * other is a deliberate zero, and `max_machines: 0` is the setting that rents
 * nothing. They become numbers exactly once, in `toProviderBody`.
 */
import type {
  BackendKind,
  Provider,
  ProviderChoice,
  ProviderDiscovery,
  ProviderInput,
  ProviderKindName,
  ProviderSetting,
} from '../api/types';

export interface WizardStepDef {
  id: string;
  title: string;
  description?: string;
}

/**
 * The steps, in the order the questions are asked: where it is and how we
 * sign in, what it should build, how big a machine is, what it may spend, and
 * then what the controller makes of all that.
 */
export const WIZARD_STEPS: readonly WizardStepDef[] = [
  {
    id: 'connect',
    title: 'Connect',
    description: 'Where Zoomies reaches the provider, and what it signs in with.',
  },
  {
    id: 'placement',
    title: 'Placement',
    description: "The driver's own settings: where a machine is built and from what.",
  },
  {
    id: 'machine',
    title: 'Machine',
    description: 'The one machine shape this provider offers. A second shape is a second provider.',
  },
  {
    id: 'limits',
    title: 'Limits',
    description: 'The ceilings. Nothing is rented until the first of these is above zero.',
  },
  { id: 'review', title: 'Review', description: 'What the controller makes of it.' },
];

/** Which API field names live on which step, so a rejection lands on the right one. */
export const STEP_FIELDS: readonly (readonly string[])[] = [
  [
    'kind',
    'name',
    'endpoint',
    'connection',
    'tailcat_address',
    'credential',
    'ca_pem',
    'insecure_skip_verify',
  ],
  ['settings'],
  [
    'machine_capacity',
    'machine_backend',
    'machine_cpus',
    'machine_memory_mb',
    'machine_disk_mb',
    'machine_platform',
    'machine_labels',
  ],
  ['max_machines', 'max_creates_in_flight', 'idle_timeout', 'cost_per_machine_hour', 'enabled'],
  [],
];

/** Human labels for the field names the API rejects things under. */
export const FIELD_LABELS: Readonly<Record<string, string>> = {
  kind: 'Kind',
  name: 'Name',
  endpoint: 'Address',
  connection: 'Connection',
  tailcat_address: 'Private connection address',
  credential: 'Credential',
  ca_pem: 'Certificate authority',
  insecure_skip_verify: 'Certificate verification',
  settings: 'Placement settings',
  machine_capacity: 'Runner slots per machine',
  machine_backend: 'Backend',
  machine_cpus: 'vCPUs',
  machine_memory_mb: 'Memory',
  machine_disk_mb: 'Disk',
  machine_platform: 'Operating system',
  machine_labels: 'Machine labels',
  max_machines: 'Maximum machines',
  max_creates_in_flight: 'Machines built at once',
  idle_timeout: 'Idle timeout',
  cost_per_machine_hour: 'Cost per machine-hour',
  enabled: 'Enabled',
};

/**
 * Which step a field belongs to. A driver's own setting arrives as
 * `settings.<key>`, which is the placement step whatever the key is; anything
 * unrecognised falls back to the review step, where every message is shown at
 * once.
 */
export function stepForField(field: string): number {
  const key = field.startsWith('settings.') ? 'settings' : field;
  const index = STEP_FIELDS.findIndex((fields) => fields.includes(key));
  return index === -1 ? WIZARD_STEPS.length - 1 : index;
}

export interface ProviderDraft {
  /**
   * Plain strings, not the generated unions. Every control in the form binds a
   * string, and a draft typed as the union would make the two disagree the
   * moment a `<select>` was involved; the narrowing happens once, on the way
   * out, in `toProviderBody`.
   */
  kind: string;
  name: string;
  endpoint: string;
  ca_pem: string;
  insecure_skip_verify: boolean;
  /** How the controller reaches the address: 'direct' or 'tailcat'. */
  connection: string;
  /**
   * The gateway's address. Handled as the credential is: never populated from
   * a provider that already exists, and an empty box on an edit means "leave
   * the stored one alone". `tailcat_configured` is what the form is told
   * instead, so it can show that one is set without holding it.
   */
  tailcat_address: string;
  tailcat_configured: boolean;
  /**
   * Never populated from a provider that already exists: the controller seals
   * it and never gives it back, so an empty box on an edit means "leave the
   * stored one alone" rather than "erase it".
   */
  credential: string;
  /** The driver's own answers, keyed by SettingSpec.key. */
  settings: Record<string, string>;
  machine_labels: Record<string, string>;
  machine_capacity: string;
  machine_backend: string;
  machine_cpus: string;
  machine_memory_mb: string;
  machine_disk_mb: string;
  machine_os: string;
  machine_os_version: string;
  machine_arch: string;
  max_machines: string;
  max_creates_in_flight: string;
  idle_timeout: string;
  cost_per_machine_hour: string;
  enabled: boolean;
}

export function emptyDraft(): ProviderDraft {
  return {
    kind: '',
    name: '',
    endpoint: '',
    ca_pem: '',
    insecure_skip_verify: false,
    connection: 'direct',
    tailcat_address: '',
    tailcat_configured: false,
    credential: '',
    settings: {},
    machine_labels: {},
    machine_capacity: '2',
    machine_backend: 'docker',
    machine_cpus: '',
    machine_memory_mb: '',
    machine_disk_mb: '',
    machine_os: '',
    machine_os_version: '',
    machine_arch: '',
    // Zero rents nothing, which is the safe default and the one an operator
    // has to change on purpose before any money is spent.
    max_machines: '0',
    max_creates_in_flight: '1',
    idle_timeout: '15m',
    cost_per_machine_hour: '',
    enabled: true,
  };
}

function fromNumber(value: number | undefined): string {
  return value === undefined || value === null ? '' : String(value);
}

export function draftFromProvider(provider: Provider): ProviderDraft {
  const base = emptyDraft();
  return {
    ...base,
    kind: provider.kind ?? '',
    name: provider.name ?? '',
    endpoint: provider.endpoint ?? '',
    insecure_skip_verify: provider.insecure_skip_verify === true,
    connection: provider.connection === 'tailcat' ? 'tailcat' : 'direct',
    tailcat_configured: provider.connection === 'tailcat',
    settings: { ...(provider.settings ?? {}) },
    machine_labels: { ...(provider.machine_labels ?? {}) },
    machine_capacity: fromNumber(provider.machine_capacity) || base.machine_capacity,
    machine_backend: provider.machine_backend ?? base.machine_backend,
    machine_cpus: fromNumber(provider.machine_cpus),
    machine_memory_mb: fromNumber(provider.machine_memory_mb),
    machine_disk_mb: fromNumber(provider.machine_disk_mb),
    machine_os: provider.machine_platform?.os ?? '',
    machine_os_version: provider.machine_platform?.os_version ?? '',
    machine_arch: provider.machine_platform?.arch ?? '',
    max_machines: fromNumber(provider.max_machines) || '0',
    max_creates_in_flight: fromNumber(provider.max_creates_in_flight) || '1',
    idle_timeout: msToDuration(provider.idle_timeout_ms) || base.idle_timeout,
    cost_per_machine_hour: fromNumber(provider.cost_per_machine_hour),
    enabled: provider.enabled !== false,
  };
}

/** A Go duration from milliseconds, in the units an operator typed them in. */
function msToDuration(ms: number | undefined): string {
  if (!ms || ms <= 0) return '';
  if (ms % 3_600_000 === 0) return `${ms / 3_600_000}h`;
  if (ms % 60_000 === 0) return `${ms / 60_000}m`;
  return `${Math.round(ms / 1000)}s`;
}

/**
 * Fill in the answers the driver has a default for, without touching one the
 * operator has already given.
 *
 * A form that comes filled in is the difference between a wizard and an
 * interrogation -- `AddHostFlow` arrives with the controller address already
 * in it for the same reason -- and a default the driver published is a better
 * answer than an empty box every time.
 */
export function applySettingDefaults(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
): ProviderDraft {
  const settings = { ...draft.settings };
  let changed = false;
  for (const spec of specs) {
    if (!spec.default) continue;
    if (settings[spec.key] !== undefined && settings[spec.key] !== '') continue;
    settings[spec.key] = spec.default;
    changed = true;
  }
  return changed ? { ...draft, settings } : draft;
}

function num(value: string): number | undefined {
  const trimmed = value.trim();
  if (trimmed === '') return undefined;
  const n = Number(trimmed);
  return Number.isFinite(n) ? n : undefined;
}

/**
 * The request body.
 *
 * `complete` is for an edit: a PATCH leaves what it does not name alone, so a
 * field an operator cleared has to be sent as its empty value or clearing it
 * does nothing. The credential is the one exception in both directions -- an
 * empty one is never sent, because the server reads that as "keep the stored
 * one" and sending it would be the only way to make a blank box erase a
 * working credential.
 */
export function toProviderBody(
  draft: ProviderDraft,
  options: { complete?: boolean } = {},
): ProviderInput {
  const complete = options.complete === true;
  const body: ProviderInput = {
    name: draft.name.trim(),
    endpoint: draft.endpoint.trim(),
    insecure_skip_verify: draft.insecure_skip_verify,
    connection: draft.connection === 'tailcat' ? 'tailcat' : 'direct',
    settings: trimmedMap(draft.settings),
    machine_labels: trimmedMap(draft.machine_labels),
    machine_capacity: num(draft.machine_capacity) ?? 2,
    machine_backend: draft.machine_backend as BackendKind,
    max_machines: num(draft.max_machines) ?? 0,
    max_creates_in_flight: num(draft.max_creates_in_flight) ?? 1,
    enabled: draft.enabled,
  };
  if (draft.kind !== '') body.kind = draft.kind as ProviderKindName;
  if (draft.credential.trim() !== '') body.credential = draft.credential;
  // Only ever sent alongside a private connection, and never empty: the
  // server reads an empty one as "keep the stored address", and naming
  // 'direct' is what clears it.
  if (draft.connection === 'tailcat' && draft.tailcat_address.trim() !== '')
    body.tailcat_address = draft.tailcat_address.trim();
  if (draft.ca_pem.trim() !== '' || complete) body.ca_pem = draft.ca_pem.trim();

  const platform: NonNullable<ProviderInput['machine_platform']> = {};
  if (draft.machine_os !== '') platform.os = draft.machine_os as NonNullable<typeof platform.os>;
  if (draft.machine_os_version.trim() !== '') platform.os_version = draft.machine_os_version.trim();
  if (draft.machine_arch !== '')
    platform.arch = draft.machine_arch as NonNullable<typeof platform.arch>;
  if (Object.keys(platform).length > 0 || complete) body.machine_platform = platform;

  assignNumber(body, 'machine_cpus', draft.machine_cpus, complete);
  assignNumber(body, 'machine_memory_mb', draft.machine_memory_mb, complete);
  assignNumber(body, 'machine_disk_mb', draft.machine_disk_mb, complete);
  assignNumber(body, 'cost_per_machine_hour', draft.cost_per_machine_hour, complete);

  const idle = draft.idle_timeout.trim();
  if (idle !== '' || complete) body.idle_timeout = idle;
  return body;
}

type NumericField =
  'machine_cpus' | 'machine_memory_mb' | 'machine_disk_mb' | 'cost_per_machine_hour';

function assignNumber(
  body: ProviderInput,
  field: NumericField,
  value: string,
  complete: boolean,
): void {
  const parsed = num(value);
  if (parsed !== undefined) body[field] = parsed;
  else if (complete) body[field] = 0;
}

function trimmedMap(map: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(map)) {
    const k = key.trim();
    if (k === '') continue;
    out[k] = value.trim();
  }
  return out;
}

/** A Go duration, as the API's Duration type spells one. */
const DURATION = /^\d+(\.\d+)?(ns|us|µs|ms|s|m|h)$/;

/**
 * Whether an address names the machine the controller is on, which is the one
 * case where plain HTTP carries nothing off the box.
 *
 * The server decides this too and its answer is the one that counts -- the form
 * asks it on every keystroke. This exists so the wizard does not offer
 * "or switch certificate checking off" as a way round a rule that is not about
 * certificates: a provider saved that way is refused by the driver at its first
 * call, long after the row was written.
 */
export function isLoopbackEndpoint(endpoint: string): boolean {
  let host: string;
  try {
    host = new URL(endpoint).hostname;
  } catch {
    return false;
  }
  host = host.replace(/^\[|\]$/g, '');
  if (host.toLowerCase() === 'localhost') return true;
  if (host === '::1') return true;
  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(host);
}

/**
 * What is wrong with the draft, keyed by the field name the API would use.
 *
 * Client rules only. Anything that needs the hypervisor -- whether the node
 * exists, whether the token may clone -- is the preflight's to answer, and
 * guessing at it here would produce a form that disagrees with the button
 * beside it.
 */
export function draftErrors(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
  options: { editing?: boolean } = {},
): Record<string, string> {
  const out: Record<string, string> = {};
  if (draft.kind === '') out.kind = 'Choose which kind of provider this is.';
  if (draft.name.trim() === '') out.name = 'Give this provider a name you will recognise.';
  const endpoint = draft.endpoint.trim();
  if (endpoint === '') out.endpoint = 'Give the address Zoomies reaches the provider on.';
  else if (!/^https?:\/\//i.test(endpoint))
    out.endpoint = 'The address needs a scheme: https://pve.example.com:8006.';
  else if (/^http:\/\//i.test(endpoint) && !isLoopbackEndpoint(endpoint))
    out.endpoint =
      'Plain HTTP would send the credential across the network in the clear, and that credential can ' +
      'create and destroy machines. Use https. Turning certificate verification off does not permit this.';
  // An edit leaves the stored credential alone, so an empty box is an answer
  // there and a missing one only on the way in.
  if (!options.editing && draft.credential.trim() === '')
    out.credential = 'A credential is needed before anything can be created.';
  if (draft.connection === 'tailcat') {
    const address = draft.tailcat_address.trim();
    if (address === '' && !draft.tailcat_configured)
      out.tailcat_address =
        'Paste the address zoomies gateway printed. It begins with tc and is the whole of the connection.';
    else if (address !== '' && !/^tc[A-Za-z0-9_-]{16,}$/.test(address))
      out.tailcat_address =
        'That does not look like a Tailcat address. Copy the whole address the gateway printed, beginning with tc.';
  }

  for (const spec of specs) {
    const value = (draft.settings[spec.key] ?? '').trim();
    const field = `settings.${spec.key}`;
    if (spec.required && value === '') {
      out[field] = `${spec.label} is needed.`;
      continue;
    }
    if (value !== '' && spec.kind === 'number' && num(value) === undefined) {
      out[field] = `${spec.label} has to be a number.`;
    }
  }

  const capacity = num(draft.machine_capacity);
  if (capacity === undefined || capacity < 1)
    out.machine_capacity = 'A machine has to offer at least one runner slot.';
  for (const [field, label] of [
    ['machine_cpus', 'vCPUs'],
    ['machine_memory_mb', 'Memory'],
    ['machine_disk_mb', 'Disk'],
    ['cost_per_machine_hour', 'Cost per machine-hour'],
  ] as const) {
    const raw = draft[field];
    if (raw.trim() === '') continue;
    const parsed = num(raw);
    if (parsed === undefined || parsed < 0) out[field] = `${label} has to be a number, or empty.`;
  }

  const max = num(draft.max_machines);
  if (max === undefined || max < 0 || !Number.isInteger(max))
    out.max_machines = 'A whole number of machines, or zero to rent nothing.';
  const inFlight = num(draft.max_creates_in_flight);
  if (inFlight === undefined || inFlight < 1)
    out.max_creates_in_flight = 'At least one, or nothing would ever be built.';
  const idle = draft.idle_timeout.trim();
  if (idle !== '' && !DURATION.test(idle)) out.idle_timeout = 'A duration like 15m, 1h or 90s.';
  return out;
}

/**
 * Whether this draft would rent anything at all, and why not.
 *
 * A provider saved with a ceiling of zero is a legal answer and the default
 * one, so this is a note beside the setting rather than an error on it.
 */
export function willRentNothing(draft: ProviderDraft): string {
  if (!draft.enabled) return 'This provider is switched off, so nothing will be built.';
  if ((num(draft.max_machines) ?? 0) === 0)
    return 'The ceiling is zero, so nothing will be built until it is raised.';
  return '';
}

/* -- the terminal's version of the form ------------------------------------- */

/**
 * The driver settings the CLI spells as flags of their own. Everything else a
 * driver asks for goes through `--setting key=value`, which is the CLI's own
 * rule (cmd/zoomies/providers_add.go) and is repeated here so the two agree.
 */
const SETTING_FLAGS: Readonly<Record<string, string>> = {
  nodes: '--nodes',
  template_id: '--template',
  storage: '--storage',
  bridge: '--bridge',
};

/** Quote one shell word, only when it needs it, so the line stays readable. */
export function shellWord(value: string): string {
  if (value === '') return "''";
  if (/^[A-Za-z0-9_@%+=:,./-]+$/.test(value)) return value;
  return `'${value.replace(/'/g, `'\\''`)}'`;
}

/**
 * The `zoomies providers add` line that would create what the form holds, or
 * the `edit` that would save it -- for the operator who would rather run it
 * from a terminal, or keep it in a script, than click through five steps.
 *
 * The credential is never in it. The CLI asks for the token on the terminal,
 * or reads it from a file, and a line that carried it would end up in a shell
 * history; the same goes for a private connection's address. The certificate
 * is a file on the CLI's side, so it is named as one. The result is a line to
 * paste, and the two placeholders in it are the two things only the operator
 * has.
 */
export function providerCommand(
  draft: ProviderDraft,
  options: { editing?: boolean; existingName?: string; specs?: readonly ProviderSetting[] } = {},
): string {
  const defaults = new Map((options.specs ?? []).map((spec) => [spec.key, spec.default ?? '']));
  const parts: string[] = ['zoomies', 'providers'];
  if (options.editing) {
    parts.push('edit', shellWord(options.existingName || draft.name.trim() || '<name>'));
    if (draft.name.trim() !== '' && draft.name.trim() !== options.existingName)
      parts.push('--name', shellWord(draft.name.trim()));
  } else {
    parts.push('add', shellWord(draft.kind || '<kind>'));
    parts.push('--name', shellWord(draft.name.trim() || '<name>'));
  }
  parts.push('--endpoint', shellWord(draft.endpoint.trim() || '<https://...>'));
  if (draft.ca_pem.trim() !== '') parts.push('--endpoint-ca-file', '<ca.pem>');
  if (draft.insecure_skip_verify) parts.push('--endpoint-insecure');
  if (draft.connection === 'tailcat') parts.push('--gateway', '<address zoomies gateway printed>');

  // The driver's answers in a fixed order -- the named flags first, then the
  // rest alphabetically -- so the same draft always renders the same line.
  // A value that is the driver's own default is left out on a create, where
  // the CLI supplies it too; an edit sends what was typed.
  const settings = trimmedMap(draft.settings);
  const isDefault = (key: string, value: string) =>
    !options.editing && defaults.has(key) && defaults.get(key) === value;
  const min = settings.vmid_min ?? '';
  const max = settings.vmid_max ?? '';
  if ((min !== '' || max !== '') && !(isDefault('vmid_min', min) && isDefault('vmid_max', max)))
    parts.push('--vmid-range', `${min}-${max}`);
  const named = Object.keys(SETTING_FLAGS);
  const rank = (key: string) => (named.includes(key) ? named.indexOf(key) : named.length);
  const keys = Object.keys(settings)
    .filter((key) => key !== 'vmid_min' && key !== 'vmid_max' && settings[key] !== '')
    .sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));
  for (const key of keys) {
    const value = settings[key] ?? '';
    if (isDefault(key, value)) continue;
    const flag = SETTING_FLAGS[key];
    if (flag) parts.push(flag, shellWord(value));
    else parts.push('--setting', shellWord(`${key}=${value}`));
  }

  const labels = trimmedMap(draft.machine_labels);
  const labelWords = Object.entries(labels).map(([k, v]) => `${k}=${v}`);
  if (labelWords.length > 0) parts.push('--labels', shellWord(labelWords.join(',')));
  const capacity = num(draft.machine_capacity);
  if (capacity !== undefined && capacity !== 2) parts.push('--capacity', String(capacity));
  if (draft.machine_backend && draft.machine_backend !== 'docker')
    parts.push('--backend', draft.machine_backend);
  for (const [field, flag] of [
    ['machine_cpus', '--cpus'],
    ['machine_memory_mb', '--memory-mb'],
    ['machine_disk_mb', '--disk-mb'],
  ] as const) {
    const value = num(draft[field]);
    if (value !== undefined && value > 0) parts.push(flag, String(value));
  }
  const ceiling = num(draft.max_machines);
  if (ceiling !== undefined && ceiling > 0) parts.push('--max-machines', String(ceiling));
  const inFlight = num(draft.max_creates_in_flight);
  if (inFlight !== undefined && inFlight !== 1) parts.push('--max-in-flight', String(inFlight));
  const idle = draft.idle_timeout.trim();
  if (idle !== '' && idle !== '15m') parts.push('--idle-timeout', idle);
  const cost = num(draft.cost_per_machine_hour);
  if (cost !== undefined && cost > 0) parts.push('--cost-per-hour', String(cost));
  if (!draft.enabled) parts.push('--enabled=false');

  // One flag pair per line past the first, because a line this long is read
  // as a list, and a list is what a script keeps.
  const lines: string[] = [];
  let current = '';
  for (const word of parts) {
    const isFlag = word.startsWith('--');
    if (isFlag && current !== '') {
      lines.push(current);
      current = '  ' + word;
    } else {
      current = current === '' ? word : `${current} ${word}`;
    }
  }
  if (current !== '') lines.push(current);
  return lines.join(' \\\n');
}

/* -- filling the form in ------------------------------------------------------ */

/**
 * An address the way the driver expects one, from what somebody typed: a bare
 * host name gets the scheme, and a host with no port gets the port the
 * example uses, because "pve.home" is what people type and
 * "https://pve.home:8006" is what the API needs. Anything already complete,
 * or too odd to parse, is left exactly as it was.
 */
export function normaliseEndpoint(raw: string, example: string | undefined): string {
  let value = raw.trim();
  if (value === '') return '';
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) value = `https://${value}`;
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return raw;
  }
  if (url.port === '' && example) {
    try {
      const port = new URL(example).port;
      if (port !== '') url.port = port;
    } catch {
      /* no usable example: the address is left without a port */
    }
  }
  // URL adds a trailing slash to a bare origin; the API wants the origin.
  return url.toString().replace(/\/$/, '');
}

/**
 * A name to suggest from the address, for the box left empty: the host's own
 * first label -- "pve" from https://pve.example.com:8006 -- which is what an
 * operator calls the cluster when they talk about it.
 */
export function suggestName(endpoint: string, fallback: string): string {
  try {
    const host = new URL(endpoint).hostname.replace(/^\[|\]$/g, '');
    const label = host.split('.')[0] ?? '';
    const slug = label
      .toLowerCase()
      .replace(/[^a-z0-9-]+/g, '-')
      .replace(/^-+|-+$/g, '');
    if (slug !== '' && !/^\d+$/.test(slug)) return slug;
  } catch {
    /* not an address yet */
  }
  return fallback;
}

/** The choices discovery offers for one setting, or none when it offers nothing. */
export function choicesFor(
  spec: ProviderSetting,
  discovery: ProviderDiscovery | null,
): ProviderChoice[] {
  if (!discovery || !spec.discovers) return [];
  const list = (discovery as unknown as Record<string, ProviderChoice[] | undefined>)[
    spec.discovers
  ];
  return Array.isArray(list) ? list : [];
}

/**
 * Fill in what discovery leaves no choice about, without touching an answer
 * the operator gave.
 *
 * A list with one entry is not a question, so it is answered. A default the
 * driver published -- vmbr0 -- that the cluster turns out not to have is
 * replaced when there is one thing to replace it with, and left alone
 * otherwise: a wrong default the operator can see beats a guess they cannot.
 */
export function applyDiscovery(
  draft: ProviderDraft,
  specs: readonly ProviderSetting[],
  discovery: ProviderDiscovery | null,
): ProviderDraft {
  if (!discovery) return draft;
  const settings = { ...draft.settings };
  let changed = false;
  for (const spec of specs) {
    const choices = choicesFor(spec, discovery);
    if (choices.length !== 1) continue;
    const only = choices[0]?.value ?? '';
    if (only === '') continue;
    const current = (settings[spec.key] ?? '').trim();
    const untouched = current === '' || current === (spec.default ?? '');
    const offered = choices.some((c) => c.value === current);
    if (current === only || (!untouched && offered)) continue;
    if (!untouched && !offered && spec.kind !== 'list') continue;
    settings[spec.key] = only;
    changed = true;
  }
  return changed ? { ...draft, settings } : draft;
}

/**
 * What a rented machine is doing, worked out from the row alone.
 *
 * Pure, and in a `.ts` rather than a component, for the reason
 * `insights/signals.ts` is: the arithmetic behind "this one has been
 * bootstrapping for eleven minutes" and "these three need a person" is what
 * goes wrong, and it is testable here without a browser.
 *
 * Nothing here reads a clock of its own. `now` is passed in, so a test can say
 * what time it is and a component can hand it the same tick it renders with.
 */
import type { Machine, MachineState, Provider } from '../api/types';

/**
 * The lifecycle as the band draws it: the states a machine passes through on
 * its way to being a host. Deleting, deleted, failed and quarantined are exits
 * from the flow rather than steps of it, and are counted separately.
 */
export const MACHINE_FLOW: readonly MachineState[] = [
  'planned',
  'creating',
  'starting',
  'bootstrapping',
  'enrolling',
  'ready',
  'draining',
];

/** The states a machine is in while the fleet is still waiting for it. */
const PENDING: ReadonlySet<MachineState> = new Set([
  'planned',
  'creating',
  'starting',
  'bootstrapping',
  'enrolling',
]);

/** The phases a timeline entry can carry, as a sentence for the page. */
const PHASES: Readonly<Record<string, string>> = {
  planned: 'Planned',
  creating: 'Creating the machine',
  created: 'Machine created',
  starting: 'Powering on',
  bootstrapped: 'Agent installed',
  enrolled: 'Enrolled with the controller',
  ready: 'Ready for work',
  draining: 'Draining',
  deleting: 'Deleting',
  deleted: 'Resource confirmed gone',
};

/**
 * What a phase is called on the page. Two consecutive rows both reading
 * "Creating" say nothing, and those rows are exactly the diagnosis: a clone
 * that never finished is a problem at the hypervisor, and a machine that
 * cloned and never enrolled is a problem inside the guest.
 */
export function phaseLabel(phase: string | undefined): string {
  if (!phase) return 'Unknown';
  return PHASES[phase] ?? phase.charAt(0).toUpperCase() + phase.slice(1);
}

/**
 * The state a timeline phase belongs to, so a row is drawn in the colour the
 * rest of the product gives that part of a machine's life. The timeline has
 * more entries than there are states -- "created" and "creating" are two marks
 * on one state -- because what an operator wants to know is which half of a
 * slow create is slow.
 */
const PHASE_STATES: Readonly<Record<string, MachineState>> = {
  planned: 'planned',
  creating: 'creating',
  created: 'creating',
  starting: 'starting',
  bootstrapped: 'bootstrapping',
  enrolled: 'enrolling',
  ready: 'ready',
  draining: 'draining',
  deleting: 'deleting',
  deleted: 'deleted',
};

export function phaseState(phase: string | undefined): MachineState | undefined {
  return phase ? PHASE_STATES[phase] : undefined;
}

export interface MachineSignals {
  /** Whether the fleet is still waiting for this machine to become a host. */
  pending: boolean;
  /** Whether it holds a resource somebody is being billed for. */
  owns: boolean;
  /** How long it has been in its current state, or null when that is unknown. */
  elapsedMs: number | null;
  /** The operation in flight, as a word, or '' when none is. */
  operation: string;
  /**
   * Whether an operator has to look at this one. It is deliberately not "the
   * state is failed": a machine whose ownership nothing could confirm, and one
   * whose last call went out and was never answered, are both running
   * hardware nothing will tidy up on its own.
   */
  needsReview: boolean;
  /** Why, in one sentence, or '' when it does not. */
  reviewReason: string;
  /** The row's own reading of whether a delete would be safe. */
  safeToDelete: boolean;
  safeToDeleteWhy: string;
}

export function machineSignals(machine: Machine, now: number = Date.now()): MachineSignals {
  const since = machine.updated_at ? Date.parse(machine.updated_at) : Number.NaN;
  const state = machine.state;
  return {
    pending: state !== undefined && PENDING.has(state),
    owns: Boolean(machine.resource_id) && !machine.deleted_at,
    elapsedMs: Number.isFinite(since) ? Math.max(0, now - since) : null,
    operation: machine.operation ?? '',
    ...review(machine),
    safeToDelete: machine.safe_to_delete === true,
    safeToDeleteWhy: machine.safe_to_delete_why ?? '',
  };
}

function review(machine: Machine): { needsReview: boolean; reviewReason: string } {
  if (machine.state === 'quarantined') {
    return {
      needsReview: true,
      reviewReason:
        machine.ownership_error ||
        'Nothing could prove this resource is ours, so nothing here will act on it.',
    };
  }
  if (machine.ownership_error) return { needsReview: true, reviewReason: machine.ownership_error };
  if (machine.state === 'failed') {
    return {
      needsReview: true,
      reviewReason:
        machine.provider_error ||
        machine.bootstrap_error ||
        'This machine never became a host. Its resource may still exist.',
    };
  }
  if (machine.outcome_unknown) {
    return {
      needsReview: true,
      reviewReason: 'A call went out and was never answered, so what happened is not known yet.',
    };
  }
  return { needsReview: false, reviewReason: '' };
}

/** Every machine an operator has to look at, in the order they were listed. */
export function machinesNeedingReview(machines: readonly Machine[]): Machine[] {
  return machines.filter((m) => review(m).needsReview);
}

export interface LifecycleStep {
  state: MachineState;
  count: number;
}

/**
 * How many machines are at each step of the flow.
 *
 * Deleted machines are left out rather than counted as zero: a fleet that has
 * been running for a month has hundreds of them, and a band whose largest
 * number is the history is a band nobody reads.
 */
export function lifecycleCounts(machines: readonly Machine[]): LifecycleStep[] {
  const counts = new Map<MachineState, number>();
  for (const state of MACHINE_FLOW) counts.set(state, 0);
  for (const machine of machines) {
    const state = machine.state;
    if (state === undefined || !counts.has(state)) continue;
    counts.set(state, (counts.get(state) ?? 0) + 1);
  }
  return MACHINE_FLOW.map((state) => ({ state, count: counts.get(state) ?? 0 }));
}

/**
 * What a machine has cost so far, or null when its provider has no opinion.
 *
 * A provider with no price is the common case -- a hypervisor in a cupboard
 * has no hourly rate -- and inventing one would be worse than saying nothing.
 */
export function machineCost(
  machine: Machine,
  provider: Pick<Provider, 'cost_per_machine_hour'> | undefined,
  now: number = Date.now(),
): number | null {
  const rate = provider?.cost_per_machine_hour ?? 0;
  if (rate <= 0) return null;
  const from = machine.created_at ? Date.parse(machine.created_at) : Number.NaN;
  if (!Number.isFinite(from)) return null;
  const to = machine.deleted_at ? Date.parse(machine.deleted_at) : now;
  if (!Number.isFinite(to)) return null;
  return (Math.max(0, to - from) / 3_600_000) * rate;
}

/**
 * A cost as a figure. Two decimals, because that is what an invoice has, and
 * an empty string rather than "0.00" when there is no price to report -- a
 * zero reads as free, which is a different claim from "nobody said".
 */
export function formatCost(value: number | null): string {
  return value === null ? '' : value.toFixed(2);
}

/**
 * The roles, in one place, in the words an operator sees.
 *
 * There were two copies of this list -- one in the accounts panel, one in the
 * tokens panel -- and they had already drifted: an administrator "also manages
 * accounts, tokens, installations and settings" in the first and "everything,
 * including accounts and settings" in the second. A third place printed the
 * bare id, so an operator was told their role was `admin` on one screen and
 * Administrator on the next.
 *
 * `internal/auth/rbac.go` is where the roles are actually enforced; this is
 * only how they are named and described.
 */
import type { Role } from './api/types';

export interface RoleOption {
  value: Role;
  label: string;
  /** One sentence, in ascending order of what it can do. */
  description: string;
}

export const ROLE_OPTIONS: readonly RoleOption[] = [
  { value: 'viewer', label: 'Viewer', description: 'Reads everything except secrets.' },
  { value: 'operator', label: 'Operator', description: 'Acts on the fleet and manages pools.' },
  {
    value: 'admin',
    label: 'Administrator',
    description: 'Also manages accounts, tokens, installations and settings.',
  },
  {
    value: 'platform',
    label: 'Platform',
    description: 'Also operates the process itself: its timers, backups and recovery.',
  },
];

/**
 * The display name for a role. Unknown values are shown as they arrived rather
 * than hidden: a role this build does not know about is worth seeing.
 */
export function roleLabel(role: string | undefined | null): string {
  if (!role) return 'Unknown';
  return ROLE_OPTIONS.find((option) => option.value === role)?.label ?? role;
}

/**
 * A History API router, small enough to read in one sitting.
 *
 * Two things make it worth having rather than reaching for a framework:
 *
 *  * Route components are loaded with dynamic `import()`, so the grids, the
 *    log viewer and the pool wizard never reach a visitor who only looks at the
 *    Overview. That is most of how the app shell stays under budget. A chunk
 *    that does not arrive is retried and, if need be, recovered by a reload;
 *    see `chunks.ts` for why that is worth doing rather than reporting.
 *  * Query state is first class. Every grid keeps its filters and paging in the
 *    URL so a view can be pasted into a chat window, and `setQuery` replaces
 *    them without unmounting the page.
 *
 * Reactivity comes from `createSubscriber`, which lets a plain `.ts` module
 * take part in Svelte's dependency tracking without being a `.svelte.ts`.
 */
