const NOT_FOUND: RouteDef = {
  name: 'not-found',
  path: '*',
  title: 'Page not found',
  component: NotFound as Component<Record<string, never>>,
};

/* -- matching -------------------------------------------------------------- */

/**
 * A path segment as typed, or as it was if it is not valid percent-encoding.
 * decodeURIComponent throws on a stray `%`, and a throw here would leave the
 * app on its loading skeleton for good; an id that does not decode simply
 * matches nothing, and the page says so.
 */
function decodeSegment(v: string): string {
  try {
    return decodeURIComponent(v);
  } catch {
    return v;
  }
}

/**
 * A `:param?` segment may be absent, so `/settings/:page?` matches `/settings`
 * as well as `/settings/users`. Only a trailing segment can be optional; an
 * absent one is simply missing from the params.
 */
function match(pathname: string): { route: RouteDef; params: Record<string, string> } {
  const parts = pathname.replace(/\/+$/, '').split('/').filter(Boolean);
  for (const route of ROUTES) {
    const pattern = route.path.split('/').filter(Boolean);
    const required = pattern.filter((p) => !p.endsWith('?')).length;
    if (parts.length < required || parts.length > pattern.length) continue;
    const params: Record<string, string> = {};
    let ok = true;
    for (let i = 0; i < pattern.length; i++) {
      const raw = pattern[i] ?? '';
      const optional = raw.endsWith('?');
      const p = optional ? raw.slice(0, -1) : raw;
      const v = parts[i];
      if (v === undefined) {
        if (optional) break;
        ok = false;
        break;
      }
      if (p.startsWith(':')) params[p.slice(1)] = decodeSegment(v);
      else if (p !== v) {
        ok = false;
        break;
      }
    }
    if (ok) return { route, params };
  }
  return { route: NOT_FOUND, params: {} };
}

/* -- state ----------------------------------------------------------------- */

let invalidate: (() => void) | null = null;
const subscribe = createSubscriber((update) => {
  invalidate = update;
  return () => {
    invalidate = null;
  };
});

let currentPath = '/';
let currentSearch = '';
let currentRoute: RouteDef = NOT_FOUND;
let currentParams: Record<string, string> = {};
let currentComponent: Component<Record<string, never>> | null = null;
let currentTitle = '';
let loading = false;
let loadError: Error | null = null;
let navigationToken = 0;
/** Bumped on every completed navigation, so pages can key off a fresh mount. */
let navigationCount = 0;
/**
 * The full path (with its query and hash) navigated away from, each time
 * `navigate` pushes a new entry. `back` uses this to know whether the actual
 * browser back button lands somewhere in this app -- a runner opened from a
 * filtered grid should return to that grid, filters and all, not a bare
 * `/runners` -- or whether the page was opened directly, in which case there
 * is nothing behind it to go back to.
 */
let previousPath: string | null = null;

/**
 * Route components already fetched, so a revisit is synchronous.
 *
 * A dynamic import of a module the browser has already parsed still resolves on
 * a later microtask, so returning to a page visited a moment ago cleared the
 * component and set `loading` for one frame -- long enough to paint the
 * skeleton and replace it again. Between two pages an operator is flipping
 * between, that is a flicker on every keystroke of `g j`, `g r`, `g j`.
 */
const loaded = new Map<RouteDef, Component<Record<string, never>>>();

function changed(): void {
  invalidate?.();
}

async function apply(): Promise<void> {
  const token = ++navigationToken;
  currentPath = location.pathname;
  currentSearch = location.search;
  const found = match(currentPath);
  const sameRoute = found.route === currentRoute;
  currentRoute = found.route;
  currentParams = found.params;
  currentTitle = found.route.title;
  loadError = null;

  const ready = found.route.component ?? loaded.get(found.route);
  if (ready) {
    currentComponent = ready;
    loading = false;
  } else if (!sameRoute || currentComponent === null) {
    loading = true;
    currentComponent = null;
    changed();
    const load = found.route.load;
    try {
      const module = load ? await loadChunk(load, () => token !== navigationToken) : undefined;
      if (token !== navigationToken) return;
      currentComponent = module?.default ?? null;
      if (currentComponent) loaded.set(found.route, currentComponent);
    } catch (cause) {
      if (token !== navigationToken) return;
      // A chunk goes missing for two reasons -- a dropped request, or an
      // upgrade that renamed it under an open tab -- and a reload fixes both.
      // While one is on its way, stay on the skeleton: an error that replaces
      // itself half a second later is worse than no error at all.
      if (await reloadForFailedChunk()) return;
      loadError =
        cause instanceof Error
          ? cause
          : new Error('That page could not be loaded. Check your connection and try again.');
    }
    loading = false;
  }

  navigationCount += 1;
  document.title = currentTitle === 'Overview' ? 'Zoomies' : `${currentTitle} · Zoomies`;
  setCanonical();
  changed();
}

/**
 * Point the page's canonical address at the route being shown.
 *
 * Every route is served the same HTML by the Go binary, so without this the
 * whole app claims to be the root. The query string is deliberately dropped:
 * grids keep their filters and paging there, and `/runners?state=busy&page=3`
 * is the runners page, not a page of its own.
 */
function setCanonical(): void {
  const href = location.origin + location.pathname;
  const link = document.querySelector<HTMLLinkElement>('link[rel="canonical"]');
  if (link) link.href = href;
  const og = document.querySelector<HTMLMetaElement>('meta[property="og:url"]');
  if (og) og.content = href;
}

/* -- link interception ------------------------------------------------------ */

function onClick(e: MouseEvent): void {
  if (e.defaultPrevented || e.button !== 0) return;
  if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const anchor = (e.target as HTMLElement | null)?.closest?.('a');
  if (!anchor) return;
  if (anchor.target && anchor.target !== '_self') return;
  if (anchor.hasAttribute('download') || anchor.hasAttribute('data-native')) return;
  if ((anchor.getAttribute('rel') ?? '').includes('external')) return;
  const href = anchor.getAttribute('href');
  if (!href || href.startsWith('#') || href.startsWith('mailto:')) return;
  const url = new URL(anchor.href, location.href);
  if (url.origin !== location.origin) return;
  // The API and the OpenAPI document are served by the Go binary, not by us.
  if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/webhooks/')) return;
  e.preventDefault();
  navigate(url.pathname + url.search + url.hash);
}

/* -- the public surface ------------------------------------------------------ */

export interface NavigateOptions {
  /** Replace the current entry instead of pushing a new one. Filters use this. */
  replace?: boolean;
  /** Keep the scroll position. Grids that change a page do. */
  keepScroll?: boolean;
}

/** Go somewhere. Same-origin paths only; use a plain link for anything external. */
export function navigate(to: string, options: NavigateOptions = {}): void {
  const url = new URL(to, location.href);
  const target = url.pathname + url.search + url.hash;
  const current = location.pathname + location.search + location.hash;
  if (target === current) return;
  // A tab that has been open across a deployment goes to the new build here.
  // A navigation discards the page's state anyway, so this costs nothing that
  // was not already being thrown away, and it is the difference between an
  // operator seeing the fleet's current UI and seeing whichever one their
  // phone happened to load last week. See $lib/state/upgrade.
  if (upgrade.claimReload()) {
    location.assign(target);
    return;
  }
  if (options.replace) history.replaceState({}, '', target);
  else {
    previousPath = current;
    history.pushState({}, '', target);
  }
  if (!options.keepScroll) window.scrollTo(0, 0);
  void apply();
}

/** Build an href with query parameters, for links that carry filter state. */
export function href(
  path: string,
  query?: Record<string, string | number | undefined | null>,
): string {
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(query ?? {})) {
    if (v === undefined || v === null || v === '') continue;
    params.set(k, String(v));
  }
  const s = params.toString();
  return s ? `${path}?${s}` : path;
}

export const router = {
  /** Start listening. Returns the teardown, for symmetry; the shell never calls it. */
  start(): () => void {
    addEventListener('popstate', () => {
      // What was behind the entry just left is no longer known -- only the
      // browser's own history stack has that -- so `back` falls through to
      // its fallback rather than guessing.
      previousPath = null;
      void apply();
    });
    document.addEventListener('click', onClick);
    void apply();
    return () => {
      document.removeEventListener('click', onClick);
    };
  },

  get pathname(): string {
    subscribe();
    return currentPath;
  },
  get route(): RouteDef {
    subscribe();
    return currentRoute;
  },
  get params(): Record<string, string> {
    subscribe();
    return currentParams;
  },
  /** The page component, or null while its chunk is still in flight. */
  get component(): Component<Record<string, never>> | null {
    subscribe();
    return currentComponent;
  },
  get loading(): boolean {
    subscribe();
    return loading;
  },
  get error(): Error | null {
    subscribe();
    return loadError;
  },
  /** The page name shown in the top bar and announced on navigation. */
  get title(): string {
    subscribe();
    return currentTitle;
  },
  /** Increments once per completed navigation. Handy as a `{#key}` value. */
  get navigation(): number {
    subscribe();
    return navigationCount;
  },

  /** A detail page can name itself once it knows what it is looking at. */
  setTitle(title: string): void {
    if (currentTitle === title) return;
    currentTitle = title;
    document.title = `${title} · Zoomies`;
    changed();
  },

  /* -- query state ------------------------------------------------------- */

  /** The current query string, parsed. Reactive: reading it in a page tracks it. */
  get query(): URLSearchParams {
    subscribe();
    return new URLSearchParams(currentSearch);
  },

  /** One query parameter, or the fallback when it is absent. */
  param(name: string, fallback = ''): string {
    subscribe();
    return new URLSearchParams(currentSearch).get(name) ?? fallback;
  },

  /** A repeated query parameter, as the API's `explode: true` style produces. */
  paramList(name: string): string[] {
    subscribe();
    return new URLSearchParams(currentSearch).getAll(name);
  },

  /** A numeric query parameter, clamped to a sensible fallback. */
  paramNumber(name: string, fallback: number): number {
    subscribe();
    const raw = new URLSearchParams(currentSearch).get(name);
    const n = raw === null ? Number.NaN : Number(raw);
    return Number.isFinite(n) ? n : fallback;
  },

  /**
   * Merge into the query string without a full navigation. `null` removes a
   * key, an array repeats it. Replaces the history entry by default, so
   * typing in a filter does not fill the back button with keystrokes.
   */
  setQuery(
    patch: Record<string, string | number | boolean | readonly string[] | null | undefined>,
    options: NavigateOptions = {},
  ): void {
    const params = new URLSearchParams(currentSearch);
    for (const [key, value] of Object.entries(patch)) {
      params.delete(key);
      if (value === null || value === undefined || value === '') continue;
      if (Array.isArray(value)) for (const v of value) params.append(key, String(v));
      else params.set(key, String(value));
    }
    const search = params.toString();
    const target = `${location.pathname}${search ? `?${search}` : ''}`;
    if (target === location.pathname + location.search) return;
    if (options.replace === false) history.pushState({}, '', target);
    else history.replaceState({}, '', target);
    currentSearch = location.search;
    changed();
  },

  /** Drop every query parameter. The "clear all" in FilterBar calls this. */
  clearQuery(options: NavigateOptions = {}): void {
    if (!currentSearch) return;
    if (options.replace === false) history.pushState({}, '', location.pathname);
    else history.replaceState({}, '', location.pathname);
    currentSearch = '';
    changed();
  },

  navigate,
  href,

  /**
   * Return to wherever this page was opened from, if that is somewhere in
   * this app, or `fallback` if it was not (a direct load, a bookmark, a link
   * from outside). Used by a detail page's delete action, where "go back" and
   * "go to the list this thing lived in" usually mean the same page but not
   * always -- a runner opened from a pool's own runner list should return
   * there, filters intact, not a bare list route.
   */
  back(fallback: string): void {
    if (previousPath) history.back();
    else navigate(fallback);
  },
};

import type { Runner } from '../api/types';
import { cpuResourceStatus, runnerStatus, toneTokens, type StatusTone } from '../status';

type StatusRunner = Pick<Runner, 'state' | 'cpu_resource'>;

interface Activity {
  label: string;
  title: string;
  detail: string;
  tone: StatusTone;
}

const activityQuirky: Record<string, Activity> = {
  maximum_zoomies: {
    label: 'Squirrel spotted',
    title: 'Maximum zoomies',
    detail: 'A major CPU boost is active. This runner is borrowing spare host capacity.',
    tone: 'busy',
  },
  zoomies: {
    label: 'Rabbit spotted',
    title: 'Extra zoomies',
    detail: 'Extra CPU is available to this runner while its host has room to spare.',
    tone: 'busy',
  },
  throttled: {
    label: 'Leash tightened',
    title: 'Host pressure protection',
    detail: 'CPU has been reduced to protect the host. It can recover as pressure eases.',
    tone: 'draining',
  },
};

/**
 * The same three states, said plainly, for when the kennel vocabulary is off.
 *
 * The two boosts each get a word of their own. They both said "Boost active"
 * once, and an operator scanning the grid could not tell an extra boost from
 * a maximum one without learning which icon was which.
 */
const activityStandard: Record<string, Activity> = {
  maximum_zoomies: {
    label: 'Zoomies',
    title: 'Maximum boost',
    detail: 'A major CPU boost is active. This runner is borrowing spare host capacity.',
    tone: 'busy',
  },
  zoomies: {
    label: 'Extra',
    title: 'Extra boost',
    detail: 'Extra CPU is available to this runner while its host has room to spare.',
    tone: 'busy',
  },
  throttled: {
    label: 'Throttled',
    title: 'Host pressure protection',
    detail: 'CPU has been reduced to protect the host. It can recover as pressure eases.',
    tone: 'draining',
  },
};

const quietCPUQuirky: Record<string, string> = {
  observing: 'Nose to the wind: spare CPU is being observed, without changing this allocation.',
  guaranteed: 'Steady paws: this runner has its guaranteed CPU allocation.',
  sit_and_stay: 'Sit and stay: elastic CPU is off for this pool.',
};

const quietCPUStandard: Record<string, string> = {
  observing: 'Spare CPU is being observed, without changing this allocation.',
  guaranteed: 'This runner has its guaranteed CPU allocation.',
  sit_and_stay: 'Elastic CPU is off for this pool.',
};

/**
 * Lifecycle stays authoritative. Only an active allocation replaces Busy/Idle.
 *
 * `quirky` is passed in by the caller rather than read here -- see the note
 * on `runnerStatus` in `../status` for why this module stays free of it too.
 */
export function runnerDisplayStatus(runner: StatusRunner, quirky = true) {
  const lifecycle = runnerStatus(runner.state, quirky);
  const canBoost = runner.state === 'busy' || runner.state === 'idle';
  const resource = runner.cpu_resource;
  const activity = quirky ? activityQuirky : activityStandard;
  const active = canBoost ? activity[resource?.state ?? ''] : undefined;
  const key = active ? resource!.state! : lifecycle.key;
  const detail = active?.detail ?? lifecycle.hint ?? 'No runner state has been reported.';
  const quietCPU = quirky ? quietCPUQuirky : quietCPUStandard;
  const cpuDetail = !active && canBoost ? quietCPU[resource?.state ?? ''] : undefined;
  const icon = active ? cpuResourceStatus(resource!.state, undefined, quirky).icon : lifecycle.icon;
  return {
    key,
    label: active?.label ?? lifecycle.label,
    title: active?.title ?? lifecycle.label,
    detail,
    cpuDetail,
    lifecycle,
    active: Boolean(active),
    canBoost,
    icon,
    ...toneTokens(active?.tone ?? lifecycle.tone),
  };
}

const STATES = [
  'busy',
  'zoomies',
  'maximum_zoomies',
  'idle',
  'provisioning',
  'registering',
  'throttled',
  'draining',
  'failed',
  'removed',
  'unknown',
] as const;
export type StandardMotionState = (typeof STATES)[number];
/**
 * Four silhouettes, so a glance at a 32px pack tells working from about to
 * work, waiting and winding down. A Record rather than a list, so a new state
 * cannot ship without someone choosing its pose.
 */
export type StandardPose = 'run' | 'stand' | 'sit' | 'lie';
const POSES: Record<StandardMotionState, StandardPose> = {
  busy: 'run',
  zoomies: 'run',
  maximum_zoomies: 'run',
  provisioning: 'stand',
  throttled: 'stand',
  idle: 'sit',
  registering: 'sit',
  failed: 'sit',
  unknown: 'sit',
  draining: 'lie',
  removed: 'lie',
};

/** Stable phases keep a fleet (and each workflow pack) from moving in lockstep. */
export function standardMotion(state: string, seed: string) {
  const motion = STATES.includes(state as StandardMotionState)
    ? (state as StandardMotionState)
    : 'unknown';
  let hash = 2166136261;
  for (const char of seed) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619) >>> 0;
  const fraction = (hash % 1000) / 1000;
  // A second and third slice of the same hash for the slow gestures and the
  // blink. Reusing the gait's shorter phase would start every
  // idle dog on a page -- and all three in a pack -- glancing up and blinking
  // within the same moment; these spread across the whole period instead.
  const gestureFraction = ((hash >>> 10) % 1000) / 1000;
  const blinkFraction = ((hash >>> 20) % 1000) / 1000;
  const running = ['busy', 'zoomies', 'maximum_zoomies'].includes(motion);
  const walking = motion === 'busy';
  const stride =
    (motion === 'maximum_zoomies' ? 0.56 : motion === 'zoomies' ? 0.8 : walking ? 1.6 : 0.64) +
    fraction * (walking ? 0.12 : 0.02);
  const spin = (motion === 'maximum_zoomies' ? 10 : 16) + fraction * 3;
  const gesture = 6 + fraction * 3;
  const blink = 5.9 + fraction * 2;
  return {
    state: motion,
    pose: POSES[motion],
    running,
    walking,
    spinning: motion === 'maximum_zoomies' || motion === 'zoomies',
    still: ['failed', 'removed', 'unknown'].includes(motion),
    stride,
    phase: -fraction * stride,
    spin,
    spinPhase: -fraction * spin,
    gesture,
    gesturePhase: -gestureFraction * gesture,
    blink,
    blinkPhase: -blinkFraction * blink,
  };
}

/**
 * Rendering one backup.
 *
 * The rules are here rather than in the panel because the table's badges and
 * the restore dialog's sentences have to agree about what a backup is: which
 * source it came from, whether this host's key opens it, and whether a restore
 * of it would be refused before anything moved.
 */
import {
  Archive,
  ArchiveRestore,
  Clock,
  CloudDownload,
  KeyRound,
  Terminal,
  Upload,
