  /** Names kept for the one frame that cannot carry them: a delete. */
  #names = new Map<string, string>();
  /** What has already been fetched, so a past is fetched once per mode. */
  #seeded = new Set<string>();
  /** The one request behind both job categories, per mode. */
  #jobFetches = new Map<string, Promise<Job[]>>();

  /* -- reads -------------------------------------------------------------- */

  /**
   * Everything this tab has to show, newest first, in the categories this
   * browser has left on.
   */
  get entries(): readonly FeedEntry[] {
    // A job no runner of this fleet ran is kept and hidden rather than
    // dropped, because the switch that asks for it is on the page beside this
    // panel and flipping it should not need a round trip.
    const others = prefs.otherRunners;
    const wanted = this.#captured.filter(
      (entry) => this.shows(entry.category) && (others || !entry.elsewhere),
    );
    if (this.shows('scaling')) {
      wanted.push(...fleet.scalingEvents.map((event, index) => scalingEntry(event, index)));
    }
    if (this.shows('runners')) {
      for (const runner of fleet.runners) {
        const entry = runnerFailureEntry(runner);
        if (entry) wanted.push(entry);
      }
    }
    return wanted.sort((a, b) => (toMillis(b.at) ?? 0) - (toMillis(a.at) ?? 0)).slice(0, CAPACITY);
  }

  /** The categories with the answer for this browser, in their listed order. */
  get categories(): readonly FeedCategoryView[] {
    return FEED_CATEGORIES.map((category) => ({ category, on: this.shows(category.id) }));
  }

  /** Whether this browser shows a category: its choice, or the default. */
  shows(id: FeedCategoryID): boolean {
    return prefs.feedChoice(id) ?? feedCategory(id)?.on ?? false;
  }

  /** How many categories are off, for the sentence the panel shows. */
  get hidden(): number {
    return FEED_CATEGORIES.filter((category) => !this.shows(category.id)).length;
  }

  /**
   * How many entries this tab holds that this browser's choices keep off the
   * page. Without it an empty panel can only guess why it is empty, and on a
   * fleet where nothing has happened yet it blamed a filter nobody had touched.
   */
  get silenced(): number {
    const others = prefs.otherRunners;
    let held = this.#captured.filter(
      (entry) => !this.shows(entry.category) && (others || !entry.elsewhere),
    ).length;
    if (!this.shows('scaling')) held += fleet.scalingEvents.length;
    if (!this.shows('runners')) {
      held += fleet.runners.filter((runner) => runnerFailureEntry(runner) !== null).length;
    }
    return held;
  }

  /* -- writes -------------------------------------------------------------- */

  /**
   * Show or hide a category. Turning one on fetches its past if it has one and
   * this tab has not already: an operator who has just asked for job failures
   * should not have to wait for the next one to see the switch worked.
   */
  setShown(id: FeedCategoryID, on: boolean): void {
    prefs.setFeedChoice(id, on);
    if (on && this.#started) void this.#seed(id);
  }

  /* -- lifecycle ----------------------------------------------------------- */

  /** Subscribe and seed. Called once, after sign-in, beside the fleet cache. */
  start(): void {
    if (this.#started) return;
    this.#started = true;

    this.#unsubscribers.push(
      events.subscribe(['runner.created', 'runner.updated'], (runner) => this.#runner(runner)),
      events.subscribe('runner.deleted', ({ id }) => this.#forget(id)),
      events.subscribe('host.updated', (host) => this.#host(host)),
      events.subscribe('host.deleted', ({ id }) => {
        this.#hosts.delete(id);
        this.#push(hostRemovedEntry(id, this.#names.get(id), now()));
      }),
      events.subscribe('machine.updated', (machine) => {
        if (!machine.id) return;
        const change = machineChange(machine, this.#machines.get(machine.id));
        if (machine.state) this.#machines.set(machine.id, machine.state);
        this.#names.set(machine.id, machine.name);
        if (change) this.#push(machineEntry(machine, change, now()));
      }),
      events.subscribe('provider.updated', (provider) => this.#provider(provider)),
      events.subscribe('pool.created', (pool) => this.#pool(pool, 'created')),
      events.subscribe('pool.updated', (pool) => this.#pool(pool, 'updated')),
      events.subscribe('pool.deleted', ({ id }) =>
        this.#push(poolRemovedEntry(id, this.#names.get(id), now())),
      ),
      events.subscribe('installation.updated', (installation) => {
        if (!installation.id) return;
        const change = installationChange(installation, this.#installations.get(installation.id));
        this.#installations.set(installation.id, installation.healthy !== false);
        if (change) {
          const entry = installationEntry(installation, change, now());
          if (entry) this.#push(entry);
        }
      }),
      events.subscribe('webhook.delivery', (delivery) => {
        const entry = deliveryEntry(delivery);
        if (entry) this.#push(entry);
      }),
      events.subscribe('job.updated', (job) => {
        const news = jobNews(job);
        if (!news) return;
        const entry = jobEntry(job, news);
        if (entry) this.#push(entry);
      }),
      events.subscribe('problems.updated', (payload) => {
        const raised = newProblems(payload.items ?? [], this.#problems);
        // Until the snapshot has landed, everything the controller reports is
        // simply everything it was already reporting before this tab opened.
        if (!fleet.loaded) return;
        const at = now();
        for (const problem of raised) this.#push(problemEntry(problem, at));
      }),
      events.subscribe('audit', (event) => {
        const entry = auditEntry(event);
        if (entry) this.#push(entry);
      }),
    );

    // The fleet's snapshot is what "seen before" means: without it every host
    // in the first frame after a reconnect would read as a host that had just
    // joined, and a reconnect is exactly when a burst of them arrives.
    this.#stopWatching = $effect.root(() => {
      $effect(() => {
        if (!fleet.loaded) return;
        void fleet.shape;
        this.#prime();
      });
      // The Overview's own switch widens what counts as this fleet's work, and
      // the past already fetched answered the narrower question. Asking again
      // is one request, once, and it is what makes the switch mean the same
      // thing in this panel as in the ones beside it.
      $effect(() => {
        if (!prefs.otherRunners) return;
        for (const id of ['jobs', 'outcomes'] as const) if (this.shows(id)) void this.#seed(id);
      });
    });

    for (const category of FEED_CATEGORIES) {
      if (this.shows(category.id)) void this.#seed(category.id);
    }
  }

  /** Disconnect and forget everything. Called on sign-out. */
  stop(): void {
    for (const off of this.#unsubscribers) off();
    this.#unsubscribers = [];
    this.#stopWatching?.();
    this.#stopWatching = null;
    this.#started = false;
    this.#captured = [];
    this.#hosts.clear();
    this.#runners.clear();
    this.#cpu.clear();
    this.#machines.clear();
    this.#providers.clear();
    this.#installations.clear();
    this.#problems.clear();
    this.#names.clear();
    this.#seeded.clear();
  }

  /* -- internals ------------------------------------------------------------ */

  /**
   * A runner frame: the two milestones of an ordinary life, and the elastic
   * CPU moving under it. The failures are not here -- they are derived from
   * the fleet cache, which holds every failed runner already.
   */
  #runner(runner: Runner): void {
    if (!runner.id) return;
    const state = runner.state;
    const previous = this.#runners.get(runner.id);
    if (state) this.#runners.set(runner.id, state);
    const cpu = runner.cpu_resource?.state;
    const seenCPU = this.#cpu.get(runner.id);
    if (cpu) this.#cpu.set(runner.id, cpu);
    // Before the snapshot has landed there is nothing to compare against that
    // is not simply this tab's ignorance, and after a reconnect the replay
    // would otherwise announce a fleet that has been running all morning.
    if (!fleet.loaded) return;
    const at = now();
    const milestone = runnerMilestone(state, previous);
    if (milestone) {
      const entry = runnerMilestoneEntry(runner, milestone, at);
      if (entry) this.#push(entry);
    }
    const lent = cpuChange(cpu, seenCPU);
    if (lent) {
      const entry = cpuEntry(runner, lent, at, prefs.quirkyStatus);
      if (entry) this.#push(entry);
    }
    // A removed runner is gone from the fleet cache too, and on a fleet of
    // ephemeral runners these maps would otherwise grow by one entry per job
    // for as long as the tab is open.
    if (state === 'removed') this.#forget(runner.id);
  }

  #forget(id: string): void {
    this.#runners.delete(id);
    this.#cpu.delete(id);
  }

  #host(host: Host): void {
    if (!host.id) return;
    if (host.name) this.#names.set(host.id, host.name);
    const next = hostSignal(host);
    const previous = this.#hosts.get(host.id);
    this.#hosts.set(host.id, next);
    // Until the first snapshot has landed there is nothing to compare against
    // that is not simply this tab's ignorance.
    if (!previous && !fleet.loaded) return;
    const at = now();
    for (const change of hostChanges(next, previous)) {
      const entry = hostEntry(host, change, at);
      if (entry) this.#push(entry);
    }
  }

  #pool(pool: Pool, change: 'created' | 'updated'): void {
    if (!pool.id) return;
    if (pool.name) this.#names.set(pool.id, pool.name);
    const entry = poolEntry(pool, change, now());
    if (entry) this.#push(entry);
  }

  #provider(provider: Provider): void {
    if (!provider.id) return;
    if (provider.name) this.#names.set(provider.id, provider.name);
    const next = providerSignal(provider);
    const previous = this.#providers.get(provider.id);
    this.#providers.set(provider.id, next);
    const at = now();
    for (const change of providerChanges(next, previous)) {
      const entry = providerEntry(provider, change, at);
      if (entry) this.#push(entry);
    }
  }

  /** Learn what the fleet already holds, without reporting any of it. */
  #prime(): void {
    for (const host of fleet.hosts) {
      if (!host.id) continue;
      if (host.name) this.#names.set(host.id, host.name);
      if (!this.#hosts.has(host.id)) this.#hosts.set(host.id, hostSignal(host));
    }
    for (const runner of fleet.runners) {
      if (!runner.id) continue;
      if (runner.state && !this.#runners.has(runner.id)) this.#runners.set(runner.id, runner.state);
      const cpu = runner.cpu_resource?.state;
      if (cpu && !this.#cpu.has(runner.id)) this.#cpu.set(runner.id, cpu);
    }
    for (const pool of fleet.pools) {
      if (pool.id && pool.name) this.#names.set(pool.id, pool.name);
    }
    // Primed rather than reported: the problems the controller was already
    // raising when this tab opened are not news, and `newProblems` forgets a
    // problem that has cleared, so the same fault happening again is.
    newProblems(fleet.problems, this.#problems);
  }

  /**
   * Fetch a category's past, once per tab and once per mode.
   *
   * A failure is silent on purpose: the feed is a panel on a dashboard, and a
   * category that could not be backfilled still fills from the stream.
   */
  async #seed(id: FeedCategoryID): Promise<void> {
    if (id !== 'jobs' && id !== 'outcomes' && id !== 'audit') return;
    // The jobs the fetch asks for depend on the Overview's own switch, so the
    // mode is part of what "already seeded" means: asking for every runner's
    // jobs after opening on this fleet's own is a second, different past.
    const key = id === 'audit' ? id : `${id}:${prefs.otherRunners ? 'all' : 'ours'}`;
    if (this.#seeded.has(key)) return;
    this.#seeded.add(key);
    try {
      if (id === 'audit') {
        const page = await listAudit({ limit: SEED_LIMIT });
        for (const event of page.items ?? []) {
          const entry = auditEntry(event);
          if (entry) this.#push(entry);
        }
        return;
      }
      // Both job categories come out of one request: they are the same
      // fetch filtered two ways, and a tab that shows both should not ask
      // for it twice.
      for (const job of await this.#completedJobs(prefs.otherRunners)) {
        const news = jobNews(job);
        if (!news) continue;
        const entry = jobEntry(job, news);
        if (entry) this.#push(entry);
      }
    } catch {
      // Left unseeded rather than surfaced: see above. Another tab, or this
      // one after a reload, will try again.
      this.#seeded.delete(key);
    }
  }

  /** The recently finished jobs, fetched once per mode and shared. */
  #completedJobs(all: boolean): Promise<Job[]> {
    const key = all ? 'all' : 'ours';
    let pending = this.#jobFetches.get(key);
    if (!pending) {
      pending = listJobs({
        state: ['completed'],
        managed: all ? undefined : true,
        limit: SEED_LIMIT,
        sort: 'completed_at',
        order: 'desc',
      })
        .then((page) => page.items ?? [])
        .catch((cause: unknown) => {
          this.#jobFetches.delete(key);
          throw cause;
        });
      this.#jobFetches.set(key, pending);
    }
    return pending;
  }

  /**
   * Add one entry, replacing an earlier report of the same fact.
   *
   * A category that is off is not merely hidden, it is not kept: the bound is
   * shared, and a fleet with automation against its API would otherwise spend
   * the whole of it on an audit trail nobody asked to see.
   */
  #push(entry: FeedEntry): void {
    if (!this.shows(entry.category)) return;
    const rest = this.#captured.filter((seen) => seen.id !== entry.id);
    this.#captured = [entry, ...rest].slice(0, CAPACITY);
  }
}

export const feed = new Feed();

/**
 * The live fleet cache.
 *
 * Every page reads from here rather than polling. SSE frames are applied to the
 * collections; a reconnect triggers one authoritative fetch so a replay gap
 * cannot leave the screen wrong.
 *
 * PERFORMANCE, and the reason this file looks the way it does:
 *
 * The rows live in plain `Map`s inside a single `$state.raw`. They are NOT deep
 * reactive state. A busy fleet has thousands of runners, and wrapping each of
 * them in a reactive proxy costs a proxy allocation per row plus a dependency
 * per field read -- which is exactly the shape of jank that makes a dashboard
 * feel slow on a second monitor. Instead the Maps are mutated in place and a
 * version counter is bumped inside a fresh container object; because the
 * container is `$state.raw`, reassigning it invalidates every reader once.
 * Coarse invalidation of a few hundred visible rows is far cheaper than fine
 * invalidation of several thousand invisible ones.
 *
 * Bumps are coalesced on an animation frame, so a burst of forty SSE frames
 * repaints once rather than forty times.
 *
 * Two counters come out of a bump. `version` moves on every change and is what
 * a component reading a row depends on. `shape` moves only when something
 * other than a live metric changed -- a runner appearing, changing state, pool,
 * host or job; a host flipping health -- and is what a server-side grid
 * refetches on. A runner's heartbeat updates its CPU and memory every thirty
 * seconds, and on a fleet of fifty runners that is a frame every second or so;
 * a grid that refetched on each of those would be a round trip per heartbeat,
 * for two columns it can read from this cache instead.
 */
import {
  ApiError,
  getPoolDefaults,
  listHosts,
  listPools,
  listProblems,
  listRunners,
  listScalingEvents,
  getStats,
} from '../api/client';
import { events, type SseStatus } from '../api/sse';
import type { Host, Pool, Problem, Resources, Runner, ScalingEvent, Stats } from '../api/types';
import { toasts } from './toasts.svelte';

interface FleetData {
  version: number;
  shape: number;
  pools: Map<string, Pool>;
  runners: Map<string, Runner>;
  hosts: Map<string, Host>;
}

function emptyData(): FleetData {
  return { version: 0, shape: 0, pools: new Map(), runners: new Map(), hosts: new Map() };
}

/**
 * The fields a frame may change without the fleet's shape having changed: the
 * live metrics an agent reports on every heartbeat.
 */
const VOLATILE = new Set([
  'cpu_percent',
  'memory_bytes',
  'last_heartbeat',
  'resource_sample',
  'usage',
]);

/** True when two rows differ in anything but a live metric. */
function shapeDiffers(a: Record<string, unknown> | undefined, b: Record<string, unknown>): boolean {
  if (!a) return true;
  for (const key of new Set([...Object.keys(a), ...Object.keys(b)])) {
    if (VOLATILE.has(key)) continue;
    if (JSON.stringify(a[key]) !== JSON.stringify(b[key])) return true;
  }
  return false;
}

/** How many scaling decisions the Overview keeps in memory. */
const SCALING_LIMIT = 50;
/** The API's maximum page size; enough to warm the cache and the palette. */
const RUNNER_PAGE = 500;

class Fleet {
  #data = $state.raw<FleetData>(emptyData());
  // These are small, so ordinary reactive state is the right trade here.
  #stats = $state<Stats | null>(null);
  #problems = $state<Problem[]>([]);
  #problemsOk = $state(true);
  #scaling = $state<ScalingEvent[]>([]);
  #connection = $state<SseStatus>('offline');
  #loaded = $state(false);
  #runnerDefaults = $state<Resources | null>(null);
  #loading = $state(false);
  #error = $state<ApiError | null>(null);

  #frame: number | null = null;
  #unsubscribers: Array<() => void> = [];
  #started = false;
  #reconciling: Promise<void> | null = null;
  /** Set by a mutation that changed more than a live metric; read by #touch. */
  #shapeChanged = false;
  /**
   * Frames that arrived while a reconcile was in flight. They are newer than
   * the responses the reconcile is waiting on, so they are applied on top of
   * the new Maps once those land rather than to the old Maps the reconcile
   * is about to throw away.
   */
  #deferred: Array<() => void> = [];
  #overflow = false;

  /* -- reads -------------------------------------------------------------- */

  /** The SSE connection state. The top bar renders this and never hides it. */
  get connection(): SseStatus {
    return this.#connection;
  }
  /** True once the first authoritative fetch has landed. */
  get loaded(): boolean {
    return this.#loaded;
  }
  get loading(): boolean {
    return this.#loading;
  }
  get error(): ApiError | null {
    return this.#error;
  }
  get stats(): Stats | null {
    return this.#stats;
  }
  get problems(): readonly Problem[] {
    return this.#problems;
  }
  /** True when there is genuinely nothing wrong, which is the common case. */
  get problemsOk(): boolean {
    return this.#problemsOk;
  }
  get scalingEvents(): readonly ScalingEvent[] {
    return this.#scaling;
  }
  /**
   * The size a pool that says nothing gets, as this fleet's settings say.
   *
   * It is fleet state rather than a constant because a host is sized against
   * it: "how many runners fit here" is asked on the Hosts page before any pool
   * exists, and answering it with a figure of the browser's own would
   * recommend a capacity the fleet would never place.
   */
  get runnerDefaults(): Resources | null {
    return this.#runnerDefaults;
  }
  /** Bumped once per applied change. Useful as a `{#key}` or effect dependency. */
  get version(): number {
    return this.#data.version;
  }
  /**
   * Bumped only when something other than a live metric changed. A grid that
   * fetches its rows from the server refetches on this, not on `version`.
   */
  get shape(): number {
    return this.#data.shape;
  }

  get pools(): Pool[] {
    return [...this.#data.pools.values()];
  }
  get runners(): Runner[] {
    return [...this.#data.runners.values()];
  }
  get hosts(): Host[] {
    return [...this.#data.hosts.values()];
  }

  pool(id: string | undefined): Pool | undefined {
    return id ? this.#data.pools.get(id) : undefined;
  }
  runner(id: string | undefined): Runner | undefined {
    return id ? this.#data.runners.get(id) : undefined;
  }
  host(id: string | undefined): Host | undefined {
    return id ? this.#data.hosts.get(id) : undefined;
  }

  /** Live runners belonging to one pool. Used by the pool detail page. */
  runnersInPool(poolId: string): Runner[] {
    return this.runners.filter((r) => r.pool_id === poolId);
  }

  /* -- lifecycle ----------------------------------------------------------- */

  /** Connect the stream and load the first snapshot. Called once, after sign-in. */
  start(): void {
    if (this.#started) return;
    this.#started = true;

    this.#unsubscribers.push(
      events.onStatus((status) => {
        const wasBroken = this.#connection !== 'live';
        this.#connection = status;
        // Every reconnect ends with one reconciling fetch, because the replay
        // buffer is finite and we cannot know whether it covered the gap. A
        // first load that failed is retried the same way: the controller that
        // was restarting under it is back, and nobody should have to press
        // anything to find that out.
        const stale = this.#loaded || this.#error !== null;
        if (status === 'live' && wasBroken && stale) void this.reconcile();
      }),
    );

    // Every handler goes through #live so that a frame landing mid-reconcile
    // waits for the new Maps instead of being applied to the old ones.
    this.#unsubscribers.push(
      events.subscribe(['runner.created', 'runner.updated'], (runner) =>
        this.#live(() => {
          if (!runner.id) return;
          // A removed runner is gone from the API's own listing, which is
          // what a reconcile replaces this cache with, so keeping it here
          // would make the two disagree until the next reconnect. On a busy
          // fleet every ephemeral runner ends this way, so the Map would
          // otherwise grow without bound between reconnects, and the
          // palette's first few hundred entries would all be runners that no
          // longer exist.
          if (runner.state === 'removed') this.#delete(this.#data.runners, runner.id);
          else this.#set(this.#data.runners, runner.id, runner);
        }),
      ),
      events.subscribe('runner.deleted', ({ id }) =>
        this.#live(() => this.#delete(this.#data.runners, id)),
      ),
      events.subscribe(['pool.created', 'pool.updated'], (pool) =>
        this.#live(() => {
          if (pool.id) this.#set(this.#data.pools, pool.id, pool);
        }),
      ),
      events.subscribe('pool.deleted', ({ id }) =>
        this.#live(() => this.#delete(this.#data.pools, id)),
      ),
      events.subscribe('host.updated', (host) =>
        this.#live(() => {
          if (host.id) this.#set(this.#data.hosts, host.id, host);
        }),
      ),
      events.subscribe('host.deleted', ({ id }) =>
        this.#live(() => this.#delete(this.#data.hosts, id)),
      ),
      events.subscribe('stats', (stats) =>
        this.#live(() => {
          this.#stats = stats;
        }),
      ),
      events.subscribe('problems.updated', (payload) =>
        this.#live(() => {
          this.#problems = payload.items ?? [];
          this.#problemsOk = payload.ok !== false;
        }),
      ),
      events.subscribe('scaling', (event) =>
        this.#live(() => {
          // By id, because the same decision arrives twice whenever a replay
          // and a reconciling fetch overlap: the fetch already has it and the
          // stream delivers it again. Two identical rows in the feed read as
          // the scheduler having decided the same thing twice, which is a
          // fleet flapping -- and a keyed list with a repeated key is an
          // error in the framework, not a cosmetic one.
          const rest = event.id
            ? this.#scaling.filter((seen) => seen.id !== event.id)
            : this.#scaling;
          this.#scaling = [event, ...rest].slice(0, SCALING_LIMIT);
        }),
      ),
      // The server could not replay everything since the last id this tab
      // saw -- its buffer moved on, or the controller restarted and the ids
      // began again. Whatever is cached may describe a fleet that no longer
      // exists, so it is fetched afresh. A reconnect already reconciles; this
      // is the case where the connection never dropped from the browser's
      // point of view, or where the reconcile has already run.
      events.subscribe('resync', () => void this.reconcile()),
    );

    events.start();
    void this.reconcile();
  }

  /** Disconnect and forget everything. Called on sign-out. */
  stop(): void {
    for (const off of this.#unsubscribers) off();
    this.#unsubscribers = [];
    this.#started = false;
    events.stop();
    this.#data = emptyData();
    this.#stats = null;
    this.#problems = [];
    this.#scaling = [];
    this.#loaded = false;
    this.#error = null;
    this.#deferred = [];
    this.#overflow = false;
  }

  /**
   * One authoritative fetch. Called at start-up, after every reconnect, and by
   * the refresh button on the pages that read this cache; concurrent callers
   * share the in-flight promise rather than stampeding.
   *
   * Frames that arrive while it runs are held and replayed once the new Maps
   * are in place, because they are newer than anything the fetch returns: a
   * reconcile runs on every reconnect, which is exactly when the server's
   * replay burst lands, and applying that burst to Maps about to be replaced
   * lost it, while a fetched `stats` overwrote a fresher frame the server
   * would not send again until its numbers changed.
   */
  reconcile(): Promise<void> {
    if (this.#reconciling) return this.#reconciling;
    this.#loading = true;
    this.#reconciling = this.#fetchAll().finally(() => {
      this.#loading = false;
      this.#reconciling = null;
      // Whatever landed after #fetchAll's own replay and before this point
      // is applied now, to whichever Maps are current.
      this.#flushDeferred();
      if (this.#overflow) {
        this.#overflow = false;
        // A bounded replay may have a gap. Refresh after this promise settles.
        // Yield between attempts if a busy fleet keeps overflowing.
        setTimeout(() => {
          if (this.#started) void this.reconcile();
        }, 1000);
      }
    });
    return this.#reconciling;
  }

  async #fetchAll(): Promise<void> {
    try {
      const [pools, hosts, runners, stats, problems, scaling, defaults] = await Promise.all([
        listPools(),
        listHosts(),
        listRunners({ limit: RUNNER_PAGE }),
        getStats(),
        listProblems(),
        listScalingEvents({ limit: SCALING_LIMIT }),
        // The one call whose failure must not take the fleet with it: what it
        // answers is a starting figure for two recommendations, and the pages
        // that use it have a built-in fallback.
        getPoolDefaults().catch(() => null),
      ]);
      const next = emptyData();
      next.version = this.#data.version + 1;
      next.shape = this.#data.shape + 1;
      for (const pool of pools.items ?? []) if (pool.id) next.pools.set(pool.id, pool);
      for (const host of hosts.items ?? []) if (host.id) next.hosts.set(host.id, host);
      for (const runner of runners.items ?? []) if (runner.id) next.runners.set(runner.id, runner);
      this.#data = next;
      this.#stats = stats;
      this.#problems = problems.items;
      this.#problemsOk = problems.ok;
      this.#scaling = scaling.items ?? [];
      if (defaults?.resources) this.#runnerDefaults = defaults.resources;
      this.#loaded = true;
      this.#error = null;
      // The frames that arrived meanwhile, on top of the fresh snapshot, so
      // the first paint after a reconnect already shows them.
      this.#flushDeferred();
    } catch (cause) {
      // A failed reconcile is a UI state, not an exception: the stream may well
      // recover on its own, and the page keeps showing what it last knew.
      this.#error =
        cause instanceof ApiError
          ? cause
          : new ApiError({
              status: 0,
              code: 'internal',
              message: cause instanceof Error ? cause.message : 'The fleet could not be loaded.',
            });
    }
  }

  /* -- writes from pages ---------------------------------------------------- */

  /**
   * Warm the cache with rows a grid has already fetched, so the command palette
   * can find a runner the operator is looking at without a second request.
   */
  ingestRunners(rows: readonly Runner[]): void {
    for (const runner of rows) if (runner.id) this.#set(this.#data.runners, runner.id, runner);
  }

  ingestPools(rows: readonly Pool[]): void {
    for (const pool of rows) if (pool.id) this.#set(this.#data.pools, pool.id, pool);
  }

  ingestHosts(rows: readonly Host[]): void {
    for (const host of rows) if (host.id) this.#set(this.#data.hosts, host.id, host);
  }

  /**
   * Apply a change locally, then send it.
   *
   * The badge flips immediately; if the server refuses -- a 409 because the
   * runner is already terminal, say -- the row goes back and a toast explains
   * in the server's own words. The eventual truth arrives over SSE and needs no
   * toast of its own.
   *
   * Returns the request's result, or `undefined` when it failed. Failure is
   * reported to the operator here, so callers do not need to catch.
   */
  async optimistic<T>(
    id: string,
    patch: Partial<Runner> | Partial<Pool> | Partial<Host>,
    run: () => Promise<T>,
    failureTitle = 'That change was not applied',
  ): Promise<T | undefined> {
    const map = this.#mapFor(id);
    const previous = map?.get(id);
    if (map && previous) {
      map.set(id, { ...previous, ...patch });
      this.#touch();
    }
    try {
      return await run();
    } catch (cause) {
      if (map && previous) {
        map.set(id, previous);
        this.#touch();
      }
      toasts.fromError(cause, failureTitle);
      return undefined;
    }
  }

  /* -- internals ------------------------------------------------------------ */

  /** Run a frame's mutation now, or hold it until the reconcile in flight lands. */
  #live(apply: () => void): void {
    if (this.#reconciling) {
      if (this.#deferred.length >= 2048) {
        this.#deferred = [];
        this.#overflow = true;
      }
      this.#deferred.push(apply);
    } else apply();
  }

  #flushDeferred(): void {
    // A frame arriving during the flush is appended and taken in turn.
    const pending = this.#deferred;
    this.#deferred = [];
    for (const apply of pending) apply();
  }

  /** Write a row, noting whether the fleet's shape moved with it. */
  #set<T extends Record<string, unknown>>(map: Map<string, T>, id: string, next: T): void {
    if (shapeDiffers(map.get(id), next)) this.#shapeChanged = true;
    map.set(id, next);
    this.#touch();
  }

  #delete<T>(map: Map<string, T>, id: string): void {
    if (map.delete(id)) this.#shapeChanged = true;
    this.#touch();
  }

  #mapFor(id: string): Map<string, Record<string, unknown>> | undefined {
    const data = this.#data as unknown as {
      runners: Map<string, Record<string, unknown>>;
      pools: Map<string, Record<string, unknown>>;
      hosts: Map<string, Record<string, unknown>>;
    };
    if (data.runners.has(id)) return data.runners;
    if (data.pools.has(id)) return data.pools;
    if (data.hosts.has(id)) return data.hosts;
    return undefined;
  }

  /**
   * Publish the mutations made to the Maps. Coalesced on a frame so a burst of
   * SSE frames costs one render, and falls back to a microtask where there is
   * no animation frame (a hidden tab, a test runner).
   */
  #touch(): void {
    if (this.#frame !== null) return;
    const publish = () => {
      this.#frame = null;
      const shape = this.#shapeChanged ? this.#data.shape + 1 : this.#data.shape;
      this.#shapeChanged = false;
      this.#data = { ...this.#data, version: this.#data.version + 1, shape };
    };
    if (typeof requestAnimationFrame === 'function') {
      this.#frame = requestAnimationFrame(publish);
    } else {
      this.#frame = 1;
      queueMicrotask(publish);
    }
  }
}

export const fleet = new Fleet();

/**
 * What the fleet wants a person to know, and what that person has already read.
 *
 * The controller reports problems; it has no opinion about whether an operator
 * has seen them. That opinion lives here, per browser, because the two useful
 * answers are different for every operator: "I know about the privileged pool,
 * I chose it" is a settled decision, while an unhealthy host is news. Without
 * somewhere to put the first kind, a panel that is never clear stops being
 * read, which costs the operator the second kind too.
 *
 * Three rules keep a dismissal from becoming a way to hide a real fault:
 *
 *  * A dismissal is forgotten the moment the controller stops reporting the
 *    problem, so the same fault happening again is news again.
 *  * A dismissal only covers the severity it was made at. A warning that
 *    becomes an error comes back, because it is not the thing that was read.
 *  * A snooze is a dismissal with an expiry the operator picks -- 15 minutes,
 *    an hour, a day -- rather than "until resolved". It returns to the active
 *    list on its own once the clock passes that time, with no further click.
 *    A snooze can cover the one problem or every problem of its kind, so a
 *    planned outage that makes every pool short of capacity is put away once
 *    -- including a pool that runs short after the snooze was made.
 *
 * Dismissals are per-operator preference, not fleet state, so they are stored
 * beside the other preferences rather than on the server. Nothing here changes
 * what `GET /api/v1/problems`, `zoomies status` or an alerting rule sees.
 */
import type { Problem, Severity } from '../api/types';
import { onClockTick } from '../format';
import { problemKey, problemTypeKey } from '../problems/identity';
import { fleet } from './fleet.svelte';
import { storage } from './prefs.svelte';

// One definition of "the same fault", shared with the Overview's feed, which
// reports a problem the first time it is raised.
export { problemKey };

const DISMISSED_KEY = 'zoomies.problems.dismissed';

/** Worst first. The panel, the badge and the summary all read this order. */
export const SEVERITY_ORDER: readonly Severity[] = ['error', 'warning', 'info'];

/** What one of each is called in a sentence an operator reads. */
export const SEVERITY_NOUN: Record<Severity, string> = {
  error: 'error',
  warning: 'warning',
  info: 'note',
};

function severity(problem: Problem): Severity {
  return problem.severity ?? 'info';
}

function rank(value: Severity): number {
  const i = SEVERITY_ORDER.indexOf(value);
  return i < 0 ? SEVERITY_ORDER.length : i;
}

export interface SnoozeOption {
  id: string;
  /** What the menu item reads: "Snooze for 15 minutes". */
  label: string;
  ms: number;
}

/** The durations offered on every problem. Fixed and short, on purpose: a
 * custom picker is one more decision on the way to putting a fault down. */
export const SNOOZE_OPTIONS: readonly SnoozeOption[] = [
  { id: '15m', label: '15 minutes', ms: 15 * 60_000 },
  { id: '1h', label: '1 hour', ms: 60 * 60_000 },
  { id: '4h', label: '4 hours', ms: 4 * 60 * 60_000 },
  { id: '24h', label: '24 hours', ms: 24 * 60 * 60_000 },
];

interface Dismissal {
  /** The severity that was read. Anything worse comes back. */
  severity: Severity;
  /** When it was dismissed, so the drawer can say how old the decision is. */
  at: string;
  /** Set on a snooze: the moment it expires and the problem becomes active
   * again on its own. Absent on a plain "dismiss until resolved". */
  until?: string;
}

type Dismissals = Record<string, Dismissal>;

function load(): Dismissals {
  const raw = storage.get(DISMISSED_KEY);
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return {};
    return parsed as Dismissals;
  } catch {
    return {};
  }
}

export interface ProblemGroup {
  severity: Severity;
  items: readonly Problem[];
}

class Notifications {
  #dismissals = $state<Dismissals>(load());
  #open = $state(false);
  #showDismissed = $state(false);
  // Ticks off the same shared clock every other relative time on the page
  // reads, so a snooze expiring costs nothing beyond the timer already
  // running for "4m ago" elsewhere on screen.
  #now = $state(Date.now());

  constructor() {
    // A dismissal outlives nothing. Once the controller stops reporting a
    // problem the decision to ignore it is spent, so the fault recurring is
    // reported again rather than being silently swallowed by a click somebody
    // made last week. A snooze is spent the moment its clock runs out, for
    // the same reason. Sweeping here -- rather than at dismissal time -- is
    // what makes both true without any bookkeeping at the call sites.
    $effect.root(() => {
      $effect(() => onClockTick((now) => (this.#now = now)));
      $effect(() => {
        if (!fleet.loaded) return;
        this.#sweep(fleet.problems, this.#now);
      });
    });
  }

  /* -- reads -------------------------------------------------------------- */

  /** Everything the controller reports, worst first, dismissed or not. */
  get all(): readonly Problem[] {
    return fleet.problems;
  }

  /** What still wants a person: the badge, the banner and the panel show these. */
  get active(): readonly Problem[] {
    return fleet.problems.filter((p) => !this.isDismissed(p));
  }

  /** What has been read and put away. Reachable, never in the way. */
  get dismissed(): readonly Problem[] {
    return fleet.problems.filter((p) => this.isDismissed(p));
  }

  /** True when there is genuinely nothing wrong -- the common case. */
  get clear(): boolean {
    return fleet.problems.length === 0 && fleet.problemsOk;
  }

  get errorCount(): number {
    return this.active.filter((p) => severity(p) === 'error').length;
  }

  /** The worst severity still active, or null when nothing is. */
  get worst(): Severity | null {
    let worst: Severity | null = null;
    for (const p of this.active) {
      const s = severity(p);
      if (worst === null || rank(s) < rank(worst)) worst = s;
    }
    return worst;
  }

  /** The active problems grouped by severity, worst group first. */
  get groups(): readonly ProblemGroup[] {
    return this.group(this.active);
  }

  /** Group any list the same way, so the drawer's two lists read alike. */
  group(items: readonly Problem[]): readonly ProblemGroup[] {
    const out: ProblemGroup[] = [];
    for (const s of SEVERITY_ORDER) {
      const group = items.filter((p) => severity(p) === s);
      if (group.length > 0) out.push({ severity: s, items: group });
    }
    return out;
  }

  isDismissed(problem: Problem): boolean {
    return this.#covering(problem) !== undefined;
  }

  dismissedAt(problem: Problem): string | undefined {
    return this.#covering(problem)?.at;
  }

  /** When a snoozed problem comes back on its own, or undefined when it was
   * dismissed outright rather than snoozed. */
  snoozedUntil(problem: Problem): string | undefined {
    return this.#covering(problem)?.until;
  }

  /** Whether what is holding this problem back is a snooze of its whole kind,
   * so the drawer can say that restoring it brings the rest back too. */
  snoozedByType(problem: Problem): boolean {
    const own = this.#live(this.#dismissals[problemKey(problem)], problem);
    return !own && this.#live(this.#dismissals[problemTypeKey(problem)], problem);
  }

  /* -- the drawer ---------------------------------------------------------- */

  get open(): boolean {
    return this.#open;
  }

  set open(value: boolean) {
    this.#open = value;
    if (!value) this.#showDismissed = false;
  }

  /** Whether the drawer is currently listing what has been put away. */
  get showDismissed(): boolean {
    return this.#showDismissed;
  }

  set showDismissed(value: boolean) {
    this.#showDismissed = value;
  }

  /* -- writes -------------------------------------------------------------- */

  dismiss(problem: Problem): void {
    this.#dismissals = {
      ...this.#dismissals,
      [problemKey(problem)]: { severity: severity(problem), at: new Date().toISOString() },
    };
    this.#persist();
    this.#closeIfClear();
  }

  /** Put this one away for a fixed while rather than until it resolves. */
  snooze(problem: Problem, ms: number): void {
    const now = new Date();
    this.#dismissals = {
      ...this.#dismissals,
      [problemKey(problem)]: {
        severity: severity(problem),
        at: now.toISOString(),
        until: new Date(now.getTime() + ms).toISOString(),
      },
    };
    this.#persist();
    this.#closeIfClear();
  }

  /** Put every problem of this one's kind away for a fixed while, including
   * any raised after the snooze was made. */
  snoozeType(problem: Problem, ms: number): void {
    const now = new Date();
    this.#dismissals = {
      ...this.#dismissals,
      [problemTypeKey(problem)]: {
        severity: severity(problem),
        at: now.toISOString(),
        until: new Date(now.getTime() + ms).toISOString(),
      },
    };
    this.#persist();
    this.#closeIfClear();
  }

  /** Put away everything currently listed. The drawer's one bulk action. */
  dismissAll(): void {
    const next = { ...this.#dismissals };
    const at = new Date().toISOString();
    for (const problem of this.active) {
      next[problemKey(problem)] = { severity: severity(problem), at };
    }
    this.#dismissals = next;
    this.#persist();
    this.#closeIfClear();
  }

  /** Bring a problem back, lifting whichever decision was holding it: its
   * own, and a snooze of its kind, which brings the rest of that kind back
   * too -- a restore that left the problem hidden would be no restore. */
  restore(problem: Problem): void {
    const keys = [problemKey(problem), problemTypeKey(problem)].filter(
      (key) => key in this.#dismissals,
    );
    if (keys.length === 0) return;
    const next = { ...this.#dismissals };
    for (const key of keys) delete next[key];
    this.#dismissals = next;
    this.#persist();
  }

  restoreAll(): void {
    this.#dismissals = {};
    this.#persist();
  }

  /* -- internals ------------------------------------------------------------ */

  /**
   * Dismissing the last problem still asking for attention closes the panel
   * that was showing it: there is nothing left for it to hold open for.
   */
  #closeIfClear(): void {
    if (this.#open && this.active.length === 0) this.open = false;
  }

  /** The live dismissal covering a problem -- its own, or a snooze of its
   * kind -- or undefined when neither does. */
  #covering(problem: Problem): Dismissal | undefined {
    for (const key of [problemKey(problem), problemTypeKey(problem)]) {
      const record = this.#dismissals[key];
      if (this.#live(record, problem)) return record;
    }
    return undefined;
  }

  #live(record: Dismissal | undefined, problem: Problem): record is Dismissal {
    if (!record) return false;
    if (record.until !== undefined && new Date(record.until).getTime() <= this.#now) return false;
    // A warning that has since become an error was never read as an error.
    return rank(severity(problem)) >= rank(record.severity);
  }

  /** Drops a dismissal once the problem it covered stops being reported, or
   * once its snooze has run out -- the two ways a dismissal is spent. */
  #sweep(problems: readonly Problem[], now: number): void {
    const live = new Set([...problems.map(problemKey), ...problems.map(problemTypeKey)]);
    const next = { ...this.#dismissals };
    let changed = false;
    for (const [key, record] of Object.entries(next)) {
      const expired = record.until !== undefined && new Date(record.until).getTime() <= now;
      if (live.has(key) && !expired) continue;
      delete next[key];
      changed = true;
    }
    if (!changed) return;
    this.#dismissals = next;
    this.#persist();
  }

  #persist(): void {
    storage.set(DISMISSED_KEY, JSON.stringify(this.#dismissals));
  }
}

export const notifications = new Notifications();

/**
 * Per-operator preferences: whether the navigation is collapsed, which columns
 * a grid shows, how many rows it asks for, and which one-off notices have been
 * put away.
 *
 * Every localStorage access is wrapped, because private-browsing modes throw on
 * access rather than returning null, and a dashboard that will not boot in a
 * private window is a dashboard someone cannot demo.
 */

import { getOwnPreferences, replaceOwnPreferences } from '../api/client';
import type { TableLayoutPreference } from '../api/types';
import {
  DEFAULT_STATUS_STYLE,
  isStatusStyle,
  resolveStatusStyle,
  type StatusStyle,
} from './status-style';

const PREFS_KEY = 'zoomies.prefs';
const PREFS_ACCOUNT_KEY = 'zoomies.prefs.account';
/** Read by the inline script in index.html before first paint. */
const NAV_KEY = 'zoomies.nav.collapsed';

export const storage = {
  get(key: string): string | null {
    try {
      return localStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key: string, value: string): void {
    try {
      localStorage.setItem(key, value);
    } catch {
      // Nothing to do and nothing worth telling the operator: the session simply
      // does not persist.
    }
  },
  remove(key: string): void {
    try {
      localStorage.removeItem(key);
    } catch {
      /* as above */
    }
  },
};

/**
 * A choice this browser has made, read back: the stored JSON while it is
 * still one of the things that choice can be, and the fallback otherwise. A
 * value left behind by an older build -- a window that no longer exists, a
 * figure since renamed -- is not a reason to open a panel with nothing in it.
 */
export function remembered<T>(key: string, fallback: T, valid: (v: unknown) => v is T): T {
  try {
    const raw = storage.get(key);
    if (raw === null) return fallback;
    const parsed: unknown = JSON.parse(raw);
    return valid(parsed) ? parsed : fallback;
  } catch {
    return fallback;
  }
}

/** Remember a choice the moment it is made. */
export function remember(key: string, value: unknown): void {
  storage.set(key, JSON.stringify(value));
}

export interface GridPrefs {
  /** Column ids the operator has hidden. Stored as the exception, so new columns appear. */
  hidden?: string[];
  /**
   * Columns that start hidden which the operator has switched on. The mirror of
   * `hidden`, and kept apart from it so that a column added later as hidden by
   * default stays hidden for an operator who had already saved a `hidden` list.
   */
  shown?: string[];
  pageSize?: number;
  /** Column widths in CSS pixels, keyed by the stable column id. */
  widths?: Record<string, number>;
  /**
   * Column ids in the operator's preferred order. New columns are appended,
   * so a saved layout does not make a later release's column disappear.
   */
  order?: string[];
  /**
   * How this grid lays a row out on a phone, when the operator has said. Absent
   * means the default below, so changing that default moves every grid nobody
   * has decided for.
   */
  view?: GridView;
}

/**
 * How a grid lays a row out on a phone.
 *
 * `rows` keeps the table: one line per row, the columns at the widths they
 * declare, and the frame scrolling sideways to reach the ones that do not fit.
 * It is the same shape every wider window shows, so a fleet looks the same on a
 * phone as on the desk it was learned at, and scanning five runners for the one
 * that is different is what it is good at. `cards` gives each row a card and
 * each value a line of its own, which is how ten columns are read in 360 pixels
 * with nothing truncated.
 *
 * Rows is the default at every width, which is what makes it one product rather
 * than two; the operator who would rather read down says so, per grid or for
 * all of them, and is remembered.
 */
export const GRID_VIEWS = ['cards', 'rows'] as const;
export type GridView = (typeof GRID_VIEWS)[number];
export const DEFAULT_GRID_VIEW: GridView = 'rows';

interface StoredPrefs {
  navCollapsed?: boolean;
  grids?: Record<string, GridPrefs>;
  /**
   * Whether the Overview's job panels also show jobs no runner of this fleet
   * touched. GitHub reports every job in the repositories an installation
   * covers, so on an organisation that also uses hosted or vendor runners the
   * majority of them are somebody else's. Off by default, because a panel
   * headed "what the fleet is running" should mean it.
   */
  otherRunners?: boolean;
  /**
   * Notices this browser has been told to stop showing. They are stored as a
   * list of ids rather than a flag per notice so a notice that is retired
   * leaves nothing behind, and they live here rather than on the server
   * because a nudge is one operator's business, not the fleet's.
   */
  dismissed?: string[];
  /**
   * How far back the Overview's activity matrix looks. An operator who
   * widens it to the year should find it that way tomorrow morning; with no
   * choice recorded it starts at today, the range the fleet is running in.
   */
  activityRange?: ActivityRangeKey;
  /**
   * Which of the Overview feed's categories this browser shows, where a choice
   * has been made. Only the choices are stored, never the defaults: a category
   * added by a later release then arrives with the default its author gave it
   * rather than switched off by a preference written before it existed.
   */
  feed?: Record<string, boolean>;
  /**
   * The phone layout a grid takes when the operator has not chosen one for it
   * itself. One setting for the whole app: an operator who prefers to scan rows
   * prefers it on every page, and the per-grid choice is for the page that is
   * the exception.
   */
  gridView?: GridView;
  /**
   * Whether runner and job status use the fleet's own dog-park vocabulary and
   * the animated avatar, rather than plain state names and a standard icon.
   * Still written, derived from `statusStyle`, so an older build opened in
   * the same browser keeps what this one chose; read only when `statusStyle`
   * is missing.
   */
  quirkyStatus?: boolean;
  /**
   * The vocabulary and illustration status is drawn with. Off -- plain words
   * and icons -- until an operator chooses otherwise in Appearance.
   */
  statusStyle?: StatusStyle;
}

/** The quick ranges the activity matrix offers, as the buttons name them. */
export const ACTIVITY_RANGES = ['1d', '7d', '30d', '90d', '1y'] as const;
export type ActivityRangeKey = (typeof ACTIVITY_RANGES)[number];

/** The nav choice recorded under NAV_KEY, or undefined when none has been made. */
function navChoiceFromStorage(): boolean | undefined {
  const raw = storage.get(NAV_KEY);
  return raw === null ? undefined : raw === '1';
}

/**
 * Whether the window is the tablet width the guidelines collapse the nav at.
 *
 * Bounded at both ends. A phone has no sidebar to collapse -- it has a bar
 * along the bottom edge -- so recording "collapsed" for one is recording an
 * answer to a question that was never asked, and the same browser opened on a
 * desktop then starts with a nav the operator never chose to shrink.
 */
function tabletWidth(): boolean {
  try {
    return (
      typeof matchMedia === 'function' &&
      matchMedia('(min-width: 769px) and (max-width: 1180px)').matches
    );
  } catch {
    return false;
  }
}

function load(): StoredPrefs {
  const raw = storage.get(PREFS_KEY);
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? (parsed as StoredPrefs) : {};
  } catch {
    return {};
  }
}

/** The row counts a grid offers. */
export const PAGE_SIZES = [25, 50, 100, 200] as const;
export const DEFAULT_PAGE_SIZE = 50;

class Prefs {
  #navCollapsed = $state(false);
  #grids = $state<Record<string, GridPrefs>>({});
  #dismissed = $state<string[]>([]);
  #otherRunners = $state(false);
  #activityRange = $state<ActivityRangeKey>('1d');
  #gridView = $state<GridView>(DEFAULT_GRID_VIEW);
  #feed = $state<Record<string, boolean>>({});
  #statusStyle = $state<StatusStyle>(DEFAULT_STATUS_STYLE);
  #accountSync = false;
  #accountSave: ReturnType<typeof setTimeout> | null = null;

  constructor() {
    const stored = load();
    // An operator's choice, in either place it may have been recorded, wins.
    // With no choice made, a tablet-width window starts collapsed: the
    // guidelines promise icons-only navigation between 768 and 1180px, and the
    // inline script in index.html applies the same default before first paint.
    const chosen = stored.navCollapsed ?? navChoiceFromStorage();
    this.#navCollapsed = chosen ?? tabletWidth();
    this.#grids = stored.grids ?? {};
    this.#dismissed = stored.dismissed ?? [];
    this.#otherRunners = stored.otherRunners ?? false;
    // Validated, not trusted: the stored value is whatever this browser last
    // wrote, and a range this build no longer offers falls back to the day.
    this.#activityRange = (ACTIVITY_RANGES as readonly string[]).includes(
      stored.activityRange ?? '',
    )
      ? (stored.activityRange as ActivityRangeKey)
      : '1d';
    // Validated for the same reason, and for one more: a grid told to lay
    // itself out in a way this build does not have would render nothing.
    this.#gridView = (GRID_VIEWS as readonly string[]).includes(stored.gridView ?? '')
      ? (stored.gridView as GridView)
      : DEFAULT_GRID_VIEW;
    this.#feed = stored.feed ?? {};
    this.#statusStyle = resolveStatusStyle(stored);
    this.#applyNav();
  }

  get navCollapsed(): boolean {
    return this.#navCollapsed;
  }

  set navCollapsed(value: boolean) {
    this.#navCollapsed = value;
    this.#applyNav();
    storage.set(NAV_KEY, value ? '1' : '0');
    this.#persist();
  }

  toggleNav(): void {
    this.navCollapsed = !this.#navCollapsed;
  }

  /**
   * Whether the Overview's job panels include jobs this fleet had no hand in.
   * One preference for both panels: an operator deciding what "the fleet" means
   * on that page means it for the whole page.
   */
  get otherRunners(): boolean {
    return this.#otherRunners;
  }

  set otherRunners(value: boolean) {
    this.#otherRunners = value;
    this.#persist();
  }

  /** How far back the Overview's activity matrix looks. */
  get activityRange(): ActivityRangeKey {
    return this.#activityRange;
  }

  set activityRange(value: ActivityRangeKey) {
    this.#activityRange = value;
    this.#persist();
  }

  /**
   * The phone layout grids take unless one has been told otherwise. Set in
   * Settings; each grid's own toggle overrides it for that grid alone.
   */
  get gridView(): GridView {
    return this.#gridView;
  }

  set gridView(value: GridView) {
    this.#gridView = value;
    this.#persist();
  }

  /**
   * What this browser has decided about one of the Overview feed's categories,
   * or undefined where it has decided nothing. The default belongs to the
   * category rather than here, so a release that changes its mind about one
   * reaches every browser that has not overruled it.
   */
  feedChoice(category: string): boolean | undefined {
    return this.#feed[category];
  }

  setFeedChoice(category: string, on: boolean): void {
    this.#feed = { ...this.#feed, [category]: on };
    this.#persist();
  }

  /** How this grid lays a row out on a phone: its own choice, or the default. */
  gridViewFor(gridId: string): GridView {
    return this.#grids[gridId]?.view ?? this.#gridView;
  }

  setGridView(gridId: string, view: GridView): void {
    this.#grids = { ...this.#grids, [gridId]: { ...this.#grids[gridId], view } };
    this.#persist();
  }

  /**
   * Bring account-scoped table layouts into this browser after sign-in. The
   * first account seen migrates the older browser-only layouts; switching to a
   * different account never copies the previous person's layout into it.
   */
  async syncAccount(userID: string): Promise<void> {
    try {
      const remote = await getOwnPreferences();
      const layouts = remote.table_layouts ?? {};
      const previous = storage.get(PREFS_ACCOUNT_KEY);
      if (Object.keys(layouts).length > 0) {
        // The server document is a replacement, not an overlay. Clearing the
        // local layout fields first means a reset made on another browser is a
        // reset here too, and no layout leaks between two accounts sharing one
        // browser. Browser-only choices such as visibility and page size stay.
        const grids: Record<string, GridPrefs> = Object.fromEntries(
          Object.entries(this.#grids).map(([gridID, grid]) => {
            const { widths: _widths, order: _order, ...rest } = grid;
            return [gridID, rest];
          }),
        );
        for (const [gridID, layout] of Object.entries(layouts)) {
          grids[gridID] = {
            ...grids[gridID],
            widths: layout.widths ? { ...layout.widths } : undefined,
            order: layout.order ? [...layout.order] : undefined,
          };
        }
        this.#grids = grids;
      } else if (previous) {
        this.#grids = Object.fromEntries(
          Object.entries(this.#grids).map(([gridID, grid]) => {
            const { widths: _widths, order: _order, ...rest } = grid;
            return [gridID, rest];
          }),
        );
      }
      storage.set(PREFS_ACCOUNT_KEY, userID);
      this.#accountSync = true;
      this.#persist();
      // An existing installation has browser layouts but no server document;
      // the first successful sync upgrades them without waiting for a drag.
      if (Object.keys(layouts).length === 0 && !previous) this.#scheduleAccountSave(0);
    } catch {
      // Browser preferences remain fully functional while the controller is
      // offline or while an older controller has no account endpoint.
      this.#accountSync = false;
    }
  }

  disconnectAccount(): void {
    this.#accountSync = false;
    if (this.#accountSave !== null) clearTimeout(this.#accountSave);
    this.#accountSave = null;
  }

  /** Column ids this grid is hiding. */
  hiddenColumns(gridId: string): string[] {
    return this.#grids[gridId]?.hidden ?? [];
  }

  /**
   * A column with `hiddenByDefault` is visible only once the operator has
   * switched it on; every other column is visible unless they hid it.
   */
  isColumnVisible(gridId: string, columnId: string, hiddenByDefault = false): boolean {
    if (hiddenByDefault) return (this.#grids[gridId]?.shown ?? []).includes(columnId);
    return !this.hiddenColumns(gridId).includes(columnId);
  }

  setColumnVisible(
    gridId: string,
    columnId: string,
    visible: boolean,
    hiddenByDefault = false,
  ): void {
    if (hiddenByDefault) {
      const shown = (this.#grids[gridId]?.shown ?? []).filter((id) => id !== columnId);
      this.#grids = {
        ...this.#grids,
        [gridId]: { ...this.#grids[gridId], shown: visible ? [...shown, columnId] : shown },
      };
      this.#persist();
      return;
    }
    const hidden = this.hiddenColumns(gridId).filter((id) => id !== columnId);
    this.setHiddenColumns(gridId, visible ? hidden : [...hidden, columnId]);
  }

  setHiddenColumns(gridId: string, hidden: string[]): void {
    this.#grids = { ...this.#grids, [gridId]: { ...this.#grids[gridId], hidden } };
    this.#persist();
  }

  pageSize(gridId: string, fallback = DEFAULT_PAGE_SIZE): number {
    return this.#grids[gridId]?.pageSize ?? fallback;
  }

  setPageSize(gridId: string, pageSize: number): void {
    this.#grids = { ...this.#grids, [gridId]: { ...this.#grids[gridId], pageSize } };
    this.#persist();
  }

  /** A column's saved width, when the operator has resized it. */
  columnWidth(gridId: string, columnId: string): number | undefined {
    const value = this.#grids[gridId]?.widths?.[columnId];
    return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : undefined;
  }

  setColumnWidth(gridId: string, columnId: string, width: number): void {
    if (!Number.isFinite(width) || width <= 0) return;
    const current = this.#grids[gridId] ?? {};
    this.#grids = {
      ...this.#grids,
      [gridId]: {
        ...current,
        widths: { ...current.widths, [columnId]: Math.round(width) },
      },
    };
    this.#persist();
  }

  clearColumnWidth(gridId: string, columnId: string): void {
    const current = this.#grids[gridId];
    if (!current?.widths?.[columnId]) return;
    const widths = { ...current.widths };
    delete widths[columnId];
    this.#grids = { ...this.#grids, [gridId]: { ...current, widths } };
    this.#persist();
  }

  /**
   * Known columns in the saved order, followed by anything this build added.
   * Unknown ids are discarded rather than reserving invisible gaps forever.
   */
  columnOrder(gridId: string, columnIds: readonly string[]): string[] {
    const known = new Set(columnIds);
    const saved = (this.#grids[gridId]?.order ?? []).filter(
      (id, index, all) => known.has(id) && all.indexOf(id) === index,
    );
    return [...saved, ...columnIds.filter((id) => !saved.includes(id))];
  }

  setColumnOrder(gridId: string, order: readonly string[]): void {
    const current = this.#grids[gridId] ?? {};
    this.#grids = { ...this.#grids, [gridId]: { ...current, order: [...order] } };
    this.#persist();
  }

  resetColumnLayout(gridId: string): void {
    const current = this.#grids[gridId];
    if (!current) return;
    const { widths: _widths, order: _order, ...rest } = current;
    this.#grids = { ...this.#grids, [gridId]: rest };
    this.#persist();
  }

  /**
   * Whether runner and job status shows the fleet's dog-park vocabulary and
   * the animated avatar. Off swaps both for plain state names and a standard
   * icon, everywhere they appear.
   */
  get quirkyStatus(): boolean {
    return this.#statusStyle !== 'off';
  }

  set quirkyStatus(value: boolean) {
    this.#statusStyle = value ? (this.#statusStyle === 'off' ? 'cute' : this.#statusStyle) : 'off';
    this.#persist();
  }

  get statusStyle(): StatusStyle {
    return this.#statusStyle;
  }

  set statusStyle(value: StatusStyle) {
    if (!isStatusStyle(value)) return;
    this.#statusStyle = value;
    this.#persist();
  }

  /** Whether this browser has put a one-off notice away. */
  isDismissed(notice: string): boolean {
    return this.#dismissed.includes(notice);
  }

  dismiss(notice: string): void {
    if (this.#dismissed.includes(notice)) return;
    this.#dismissed = [...this.#dismissed, notice];
    this.#persist();
  }

  #applyNav(): void {
    if (typeof document === 'undefined') return;
    if (this.#navCollapsed) document.documentElement.setAttribute('data-nav', 'collapsed');
    else document.documentElement.removeAttribute('data-nav');
  }

  #persist(): void {
    storage.set(
      PREFS_KEY,
      JSON.stringify({
        navCollapsed: this.#navCollapsed,
        grids: this.#grids,
        dismissed: this.#dismissed,
        otherRunners: this.#otherRunners,
        activityRange: this.#activityRange,
        gridView: this.#gridView,
        feed: this.#feed,
        quirkyStatus: this.quirkyStatus,
        statusStyle: this.#statusStyle,
      } satisfies StoredPrefs),
    );
    this.#scheduleAccountSave();
  }

  #scheduleAccountSave(wait = 350): void {
    if (!this.#accountSync) return;
    if (this.#accountSave !== null) clearTimeout(this.#accountSave);
    this.#accountSave = setTimeout(() => {
      this.#accountSave = null;
      const tableLayouts: Record<string, TableLayoutPreference> = {};
      for (const [gridID, grid] of Object.entries(this.#grids)) {
        if (!grid.widths && !grid.order) continue;
        tableLayouts[gridID] = {
          ...(grid.widths ? { widths: grid.widths } : {}),
          ...(grid.order ? { order: grid.order } : {}),
        };
      }
      void replaceOwnPreferences({ table_layouts: tableLayouts }).catch(() => {
        // The local copy is authoritative until the next successful sign-in;
        // a layout gesture should never turn into an error toast.
      });
    }, wait);
  }
}

export const prefs = new Prefs();

/**
 * The one refresh: what the button in the page header does, and what `R` does.
 *
 * Zoomies stays current on its own -- a single SSE stream feeds the fleet cache
 * and the grids refetch off it -- so this is not how the screen keeps up. It is
 * for the moments the stream cannot answer for itself: a laptop opened after an
 * hour shut, a change somebody else made through the API, a controller that was
 * restarting when the last reconcile went out. Being able to ask costs one
 * request and settles the question; not being able to ask is what makes an
 * operator reload the whole application instead.
 *
 * A page says what refreshing means for it by rendering the control, and the
 * control registers the handler here so the keyboard shortcut and the button
 * can never disagree about what they do. Pages that have nothing to fetch --
 * the wizards, the not-found page -- register nothing and show no button,
 * because a control that does nothing is worse than no control.
 *
 * One refresh at a time. A second press while the first is in flight joins it
 * rather than starting another; a page that fans out to five requests must not
 * be able to send fifteen because somebody pressed the button three times.
 */
import { toasts } from './toasts.svelte';

/** What a page does when it is asked to refresh. May be async; may throw. */
export type RefreshHandler = () => void | Promise<void>;

/**
 * The spin is held for at least this long.
 *
 * A refresh that answers in twenty milliseconds -- which is the common case
 * against a controller on the same machine -- would otherwise flick the icon
 * once and leave the operator genuinely unsure whether anything happened. The
 * delay is the feedback, not the work.
 */
const MIN_SPIN_MS = 420;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

class Refresh {
  #handler = $state.raw<RefreshHandler | null>(null);
  #busy = $state(false);
  #at = $state<number | null>(null);
  /** Bumped once per completed refresh, for anything that announces them. */
  #count = $state(0);
  #running: Promise<void> | null = null;

  /** True when the page on screen has said what refreshing means for it. */
  get available(): boolean {
    return this.#handler !== null;
  }

  get busy(): boolean {
    return this.#busy;
  }

  /** When the last refresh finished, or null if this page has not had one. */
  get at(): number | null {
    return this.#at;
  }

  get count(): number {
    return this.#count;
  }

  /**
   * Register this page's handler. Returns the teardown; call it from an
   * `$effect`, which is also what makes leaving a page take its button away.
   */
  register(handler: RefreshHandler): () => void {
    this.#handler = handler;
    this.#at = null;
    this.#count = 0;
    return () => {
      if (this.#handler !== handler) return;
      this.#handler = null;
      this.#at = null;
      this.#count = 0;
    };
  }

  /** Refresh the page on screen. Safe to call when there is nothing to do. */
  run(): Promise<void> {
    if (this.#running) return this.#running;
    const handler = this.#handler;
    if (!handler) return Promise.resolve();
    this.#busy = true;
    const done = this.#cycle(handler).finally(() => {
      this.#busy = false;
      this.#running = null;
    });
    this.#running = done;
    return done;
  }

  async #cycle(handler: RefreshHandler): Promise<void> {
    const started = Date.now();
    try {
      await handler();
    } catch (cause) {
      // Most handlers report their own failures -- a grid renders its error,
      // the fleet cache keeps the last truth on screen. This is for the ones
      // that throw anyway, so a press is never silently swallowed.
      toasts.fromError(cause, 'This page could not be refreshed');
    } finally {
      const spent = Date.now() - started;
      if (spent < MIN_SPIN_MS) await sleep(MIN_SPIN_MS - spent);
      this.#at = Date.now();
      this.#count += 1;
    }
  }
}

/** The one refresh. Registered by whichever page is on screen. */
export const refresh = new Refresh();

/**
 * Who is signed in, and what the server said about itself before they were.
 *
 * `/meta` is safe to call unauthenticated and decides what the first screen is:
 * the bootstrap form when no account exists yet, otherwise the login form,
 * otherwise the application.
 */
import {
  ApiError,
  bootstrap as bootstrapRequest,
  changeOwnPassword,
  getMeta,
  getSession,
  login as loginRequest,
  logout as logoutRequest,
} from '../api/client';
import type { Identity, Meta, Role, SignInChallenge, TwoStepSignIn } from '../api/types';
import { atLeast } from '../api/types';
import { prefs } from './prefs.svelte';

export type SessionPhase =
  /** Still asking the server what it is. */
  | 'booting'
  /** No account exists; the first-run form is the only thing to show. */
  | 'bootstrap'
  /** Accounts exist but nobody is signed in. */
  | 'anonymous'
  /** Signed in, or authentication is switched off. */
  | 'ready'
  /** The controller could not be reached at all. */
  | 'failed';

class Session {
  #meta = $state<Meta | null>(null);
  #identity = $state<Identity | null>(null);
  #phase = $state<SessionPhase>('booting');
  #error = $state<ApiError | null>(null);

  get meta(): Meta | null {
    return this.#meta;
  }
  get identity(): Identity | null {
    return this.#identity;
  }
  get phase(): SessionPhase {
    return this.#phase;
  }
  /** Why the boot failed, when it did. */
  get error(): ApiError | null {
    return this.#error;
  }
  get role(): Role | undefined {
    return this.#identity?.role;
  }
  get authDisabled(): boolean {
    return this.#meta?.auth_disabled === true;
  }
  get oidcEnabled(): boolean {
    return this.#meta?.oidc_enabled === true;
  }
  /** The administrator reset this password and it has to change before anything else. */
  get mustChangePassword(): boolean {
    return this.#identity?.must_change_password === true;
  }
  /** A display name for the user menu, falling back to something truthful. */
  get displayName(): string {
    return this.#identity?.name ?? (this.authDisabled ? 'Authentication disabled' : 'Signed in');
  }

  /** True when the caller's role is at least `needed`. Gates mutating actions. */
  can(needed: Role): boolean {
    if (this.authDisabled) return true;
    return atLeast(this.#identity?.role, needed);
  }

  /** The boot sequence: what the server is, then who we are. */
  async boot(): Promise<void> {
    this.#phase = 'booting';
    this.#error = null;
    try {
      this.#meta = await getMeta();
    } catch (cause) {
      this.#error =
        cause instanceof ApiError
          ? cause
          : new ApiError({
              status: 0,
              code: 'internal',
              message: 'Could not reach the Zoomies controller.',
            });
      this.#phase = 'failed';
      return;
    }
    // Authentication being switched off wins over everything else. There is no
    // point creating the first administrator on a controller that will never
    // check who anybody is, and a first-run form on such an instance would be
    // a form that does nothing.
    if (this.#meta.auth_disabled) {
      this.#phase = 'ready';
      return;
    }
    if (this.#meta.bootstrap_required) {
      this.#phase = 'bootstrap';
      return;
    }
    await this.refresh();
  }

  /**
   * Re-read what the controller says about itself. Used after a settings
   * change: some of what `/meta` carries -- the external URL, whether runs may
   * be cancelled, how the capacity map opens -- is a setting an administrator
   * can move at runtime, and the pages that read it should not have to wait
   * for a reload to hear. A failure keeps the answer already held: the old
   * facts are at worst a little stale, and a page that lost them would be
   * worse than one running on them.
   */
  async reloadMeta(): Promise<void> {
    try {
      this.#meta = await getMeta();
    } catch {
      /* the answer already held stands */
    }
  }

  /** Re-read the identity. Used after login, bootstrap and a password change. */
  async refresh(): Promise<void> {
    try {
      this.#identity = await getSession();
      // Auth-disabled sessions resolve to a fixed identity with no row behind
      // it, so there is no account for a table layout to belong to.
      if (!this.authDisabled && this.#identity.kind === 'user' && this.#identity.id) {
        await prefs.syncAccount(this.#identity.id);
      }
      this.#phase = 'ready';
    } catch (cause) {
      this.#identity = null;
      // A 401 is the ordinary "not signed in" answer. Only an unreachable
      // controller is a failure worth its own screen.
      if (cause instanceof ApiError && cause.isOffline) {
        this.#error = cause;
        this.#phase = 'failed';
      } else {
        this.#phase = 'anonymous';
      }
    }
  }

  /**
   * Sign in. Throws an ApiError the form renders inline -- 401 and 429 both
   * matter. Resolves to the pending second step when the password was right
   * and the account has a code to give, or an authenticator to set up; the
   * sign-in page takes it from there and calls `completeTwoStep`.
   */
  async login(username: string, password: string): Promise<SignInChallenge | null> {
    const answer = await loginRequest({ username, password });
    if ('two_step' in answer) return answer;
    await this.#signedIn(answer);
    return null;
  }

  /** Finish a sign-in whose second step the server has just accepted. */
  async completeTwoStep(result: TwoStepSignIn): Promise<void> {
    await this.#signedIn(result.identity);
  }

  async #signedIn(identity: Identity): Promise<void> {
    this.#identity = identity;
    if (identity.kind === 'user' && identity.id) {
      await prefs.syncAccount(identity.id);
    }
    this.#phase = 'ready';
  }

  /** Create the first account. Only ever available while none exists. */
  async completeBootstrap(input: {
    username: string;
    password: string;
    setup_token: string;
    email?: string;
  }): Promise<Identity> {
    this.#identity = await bootstrapRequest(input);
    if (this.#identity.kind === 'user' && this.#identity.id) {
      await prefs.syncAccount(this.#identity.id);
    }
    this.#meta = this.#meta ? { ...this.#meta, bootstrap_required: false } : this.#meta;
    this.#phase = 'ready';
    return this.#identity;
  }

  /**
   * Check that the cookie the last call was supposed to set actually works.
   *
   * Bootstrap answers 201 with the new identity even when the session could
   * not be started -- the account exists either way, and the API says so. The
   * browser cannot tell that 201 from a working one, so it used to render the
   * product, take a 401 on its first fetch, and drop the operator on a sign-in
   * screen with no message a moment after a form that appeared to succeed.
   */
  async confirmSignedIn(): Promise<boolean> {
    try {
      this.#identity = await getSession();
      this.#phase = 'ready';
      return true;
    } catch {
      this.#identity = null;
      this.#phase = 'anonymous';
      return false;
    }
  }

  async changePassword(oldPassword: string | undefined, newPassword: string): Promise<void> {
    await changeOwnPassword({ old_password: oldPassword, new_password: newPassword });
    await this.refresh();
  }

  async logout(): Promise<void> {
    try {
      await logoutRequest();
    } finally {
      this.clear();
    }
  }

  /** Drop the identity without calling the server. The 401 handler uses this. */
  clear(): void {
    prefs.disconnectAccount();
    this.#identity = null;
    this.#phase = 'anonymous';
  }
}

export const session = new Session();

/** One choice controls the vocabulary and the illustration across all status surfaces. */
export const STATUS_STYLES = ['off', 'cute', 'standard'] as const;
export type StatusStyle = (typeof STATUS_STYLES)[number];

/**
 * What a browser that has never chosen starts on: a new install, and one whose
 * saved preferences were cleared or could not be read. Plain words are the
 * ones an operator new to the fleet can match against GitHub's own runner
 * page and against the docs, and the dogs are one press away in Appearance
 * for anyone who wants them.
 */
export const DEFAULT_STATUS_STYLE: StatusStyle = 'off';

export const STATUS_STYLE_OPTIONS = [
  { value: 'off', label: 'Off', name: 'Plain status names and icons' },
  { value: 'cute', label: 'Cute', name: 'Zoomies words and the original animated dog' },
  { value: 'standard', label: 'Standard', name: 'Zoomies words and the monochrome spaniel' },
] as const;

export function isStatusStyle(value: unknown): value is StatusStyle {
  return STATUS_STYLES.some((style) => style === value);
}

/**
 * The saved style, or the default where there is none.
 *
 * A browser from before the three-way choice stored only the old boolean, and
 * with it on it was showing the kennel words, so it keeps them: moving an
 * existing operator's screen under them on upgrade is not what changing the
 * default means. Anything else -- nothing stored, or a value this build does
 * not recognise -- is a browser that has not chosen, and gets the default.
 */
export function resolveStatusStyle(stored: {
  statusStyle?: unknown;
  quirkyStatus?: unknown;
}): StatusStyle {
  if (isStatusStyle(stored.statusStyle)) return stored.statusStyle;
  if (stored.quirkyStatus === true) return 'cute';
  if (stored.quirkyStatus === false) return 'off';
  return DEFAULT_STATUS_STYLE;
}

/**
 * Light, dark or whatever the operating system says.
 *
 * `system` is the default and writes no attribute, so `prefers-color-scheme`
 * decides. An explicit choice writes `data-theme` on `<html>` and persists. The
 * inline script in index.html applies the stored value before first paint; this
 * module only keeps it in sync afterwards -- it deliberately does not repeat
 * that work.
 *
 * The one thing an attribute on `<html>` cannot reach is the browser's own
 * chrome, which reads `<meta name="theme-color">`. The two tags in index.html
 * are media-scoped so the "system" default needs no JavaScript at all; an
 * explicit choice pins them here, because otherwise an operator on a dark
 * laptop who asks for the light theme still gets a black bar above a white
 * page.
 */
import { storage } from './prefs.svelte';

export type ThemeChoice = 'light' | 'dark' | 'system';
export type ResolvedTheme = 'light' | 'dark';

/**
 * The three choices as a segmented control offers them: the Appearance page
 * and the phone's menu both draw one, and the words are the same in each.
 */
export const THEME_OPTIONS: readonly { value: ThemeChoice; label: string; name: string }[] = [
  { value: 'system', label: 'System', name: 'Follow the operating system' },
  { value: 'light', label: 'Light', name: 'Always light, whatever the system says' },
  { value: 'dark', label: 'Dark', name: 'Always dark' },
];

const KEY = 'zoomies.theme';

/**
 * Point the browser chrome at the theme actually on screen.
 *
 * `system` hands the tags back their media queries so the operating system
 * keeps switching them with no JavaScript involved; an explicit choice pins one
 * tag on and the other off. `not all` is the standard way to say "never match".
 */
function pinBrowserChrome(choice: ThemeChoice): void {
  for (const which of ['light', 'dark'] as const) {
    const tag = document.querySelector(`meta[data-theme-colour="${which}"]`);
    if (!tag) continue;
    tag.setAttribute(
      'media',
      choice === 'system'
        ? `(prefers-color-scheme: ${which})`
        : choice === which
          ? 'all'
          : 'not all',
    );
  }
}

function stored(): ThemeChoice {
  const value = storage.get(KEY);
  return value === 'light' || value === 'dark' ? value : 'system';
}

class Theme {
  #choice = $state<ThemeChoice>('system');
  #systemDark = $state(false);

  constructor() {
    this.#choice = stored();
    // The stored choice was applied to <html> before first paint by the inline
    // script, which cannot reach the meta tags; catch them up here.
    if (typeof document !== 'undefined') pinBrowserChrome(this.#choice);
    if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
      const query = window.matchMedia('(prefers-color-scheme: dark)');
      this.#systemDark = query.matches;
      query.addEventListener('change', (e) => {
        this.#systemDark = e.matches;
      });
    }
  }

  /** What the operator chose, including `system`. */
  get choice(): ThemeChoice {
    return this.#choice;
  }

  /** What is actually on screen. */
  get resolved(): ResolvedTheme {
    if (this.#choice === 'system') return this.#systemDark ? 'dark' : 'light';
    return this.#choice;
  }

  set(choice: ThemeChoice): void {
    this.#choice = choice;
    if (typeof document === 'undefined') return;
    if (choice === 'system') {
      document.documentElement.removeAttribute('data-theme');
      storage.remove(KEY);
    } else {
      document.documentElement.setAttribute('data-theme', choice);
      storage.set(KEY, choice);
    }
    pinBrowserChrome(choice);
  }

  /** light → dark → system → light. What the top bar's toggle does. */
  cycle(): void {
    this.set(this.#choice === 'light' ? 'dark' : this.#choice === 'dark' ? 'system' : 'light');
  }
}

export const theme = new Theme();

/**
 * The toast queue.
 *
 * Toasts report the outcome of something the operator did. Background events --
 * a runner reaching `removed` on its own -- arrive over SSE and are shown by the
 * page changing, not by a notification.
 *
 * Successes dismiss themselves. Errors do not: an operator who looked away
 * should still find out that the drain was refused.
 */
import { sentence, supportHint } from '$lib/errors';
import { ApiError } from '../api/client';

export type ToastTone = 'info' | 'success' | 'warning' | 'error';

export interface ToastAction {
  label: string;
  run: () => void;
}

export interface Toast {
  id: number;
  tone: ToastTone;
  /** One line, sentence case, no full stop. */
  title: string;
  /** What happened and what to do about it. */
  message?: string;
  action?: ToastAction;
  /** Milliseconds until it dismisses itself; 0 means it stays. */
  timeout: number;
}

export interface ToastInput {
  tone?: ToastTone;
  title: string;
  message?: string;
  action?: ToastAction;
  timeout?: number;
}

const DEFAULT_TIMEOUT = 5000;
/** Beyond this the stack becomes a wall; the oldest self-dismissing one goes. */
const MAX_VISIBLE = 4;
/**
 * The ceiling when every toast on screen is one that stays until it is read.
 * Higher than MAX_VISIBLE, because an unread error is the one thing this queue
 * exists to protect; finite, because a failing loop must not bury the page it
 * is failing on.
 */
const MAX_STICKY = 8;

/**
 * Whether a tone interrupts.
 *
 * A warning is a partial failure -- retention applied to some copies, one
 * remote that refused -- so it belongs with the errors on both counts the two
 * regions exist for. It used to sit with the successes, which meant the one
 * message on the page that said something did not work was announced in the
 * queue that waits for a pause.
 */
function assertive(tone: ToastTone): boolean {
  return tone === 'error' || tone === 'warning';
}

let nextId = 1;

/**
 * Make room for one more.
 *
 * Eviction takes the oldest toast that was going to leave on its own anyway.
 * It used to take the oldest of any kind, so an operator who drained five
 * runners and had one refused watched the four successes push the refusal off
 * the screen before they could read it -- the exact opposite of what
 * "successes dismiss themselves, errors do not" is for.
 */
function evict(items: Toast[]): Toast[] {
  const kept = [...items];
  while (kept.length > MAX_VISIBLE) {
    const oldestTemporary = kept.findIndex((t) => t.timeout > 0);
    if (oldestTemporary === -1) break;
    kept.splice(oldestTemporary, 1);
  }
  return kept.length > MAX_STICKY ? kept.slice(-MAX_STICKY) : kept;
}

class Toasts {
  #items = $state<Toast[]>([]);

  get items(): readonly Toast[] {
    return this.#items;
  }

  /** Everything announced politely: successes and information. */
  get polite(): readonly Toast[] {
    return this.#items.filter((t) => !assertive(t.tone));
  }

  /** Errors and warnings, announced assertively because they interrupt a task. */
  get assertive(): readonly Toast[] {
    return this.#items.filter((t) => assertive(t.tone));
  }

  push(input: ToastInput): number {
    const tone = input.tone ?? 'info';
    const toast: Toast = {
      id: nextId++,
      tone,
      title: input.title,
      message: input.message,
      action: input.action,
      timeout: input.timeout ?? (tone === 'error' ? 0 : DEFAULT_TIMEOUT),
    };
    this.#items = evict([...this.#items, toast]);
    if (toast.timeout > 0) {
      setTimeout(() => this.dismiss(toast.id), toast.timeout);
    }
    return toast.id;
  }

  success(title: string, message?: string): number {
    return this.push({ tone: 'success', title, message });
  }

  info(title: string, message?: string): number {
    return this.push({ tone: 'info', title, message });
  }

  warning(title: string, message?: string): number {
    return this.push({ tone: 'warning', title, message });
  }

  error(title: string, message?: string, action?: ToastAction): number {
    return this.push({ tone: 'error', title, message, action });
  }

  /**
   * Report a failed request. The server's words are shown as they are -- on a
   * 403 they name the role required, and paraphrasing them would lose that --
   * but capitalised and stopped, because the server writes them for a log line
   * and this is a sentence under a sentence-case title. The detail is
   * often a Go error, a path or a URL, so it follows the message untouched.
   */
  fromError(cause: unknown, title: string, action?: ToastAction): number {
    if (cause instanceof ApiError) {
      const message = sentence(cause.message);
      return this.error(title, cause.detail ? `${message} ${cause.detail}` : message, action);
    }
    if (cause instanceof Error) return this.error(title, sentence(cause.message), action);
    return this.error(title, `The cause was not reported. ${supportHint()}`, action);
  }

  dismiss(id: number): void {
    this.#items = this.#items.filter((t) => t.id !== id);
  }

  clear(): void {
    this.#items = [];
  }
}

export const toasts = new Toasts();

/**
 * Whether the controller has been upgraded under this tab.
 *
 * A tab left open across a deployment goes on running the build it loaded, and
 * nothing tells it otherwise. The chunk recovery in `$lib/chunks` catches the
 * loud half of that -- a route whose code no longer exists 404s, and the tab
 * reloads -- but a tab that already holds every chunk it needs never fails, so
 * it can serve an old page indefinitely. On a phone, where a tab is backgrounded
 * for days rather than closed, that is the ordinary case rather than the odd
 * one: the fleet moves on and the screen in somebody's pocket does not.
 *
 * So the build is re-read when the tab comes back to the foreground, and the
 * next navigation is a full page load rather than a client-side one. The
 * navigation is the safe moment by construction -- it discards the page's state
 * anyway -- so nothing is lost, and an operator sees the current UI without
 * being asked to do anything about it.
 */

import { getMeta } from '$lib/api/client';

/** Where a tab records that it has already moved itself to a newer build. */
const RELOADED_KEY = 'zoomies.upgrade-reloaded';

/** How long after a check before another one is worth a request. */
const RECHECK_AFTER = 60_000;

class Upgrade {
  #booted = '';
  #pending = $state(false);
  #lastCheck = 0;

  /**
   * Record the build this tab is running, from the meta the shell already
   * fetched at boot. Called once; a second call is ignored, because the point
   * of reference is the code in this tab and that never changes.
   */
  note(version: string): void {
    if (this.#booted === '' && version !== '') this.#booted = version;
  }

  /** True once the controller has reported a build this tab is not running. */
  get pending(): boolean {
    return this.#pending;
  }

  /**
   * Ask the controller what it is now.
   *
   * Rate-limited, and silent about failures: a controller that cannot be
   * reached says nothing about whether this tab is current, and an operator
   * on a train does not need to hear about it.
   */
  async check(now: number = Date.now()): Promise<void> {
    if (this.#pending || this.#booted === '') return;
    if (now - this.#lastCheck < RECHECK_AFTER) return;
    this.#lastCheck = now;
    try {
      const meta = await getMeta();
      const version = meta.version ?? '';
      if (version !== '' && version !== this.#booted) this.#pending = true;
    } catch {
      /* as above */
    }
  }

  /**
   * Whether the next navigation should be a full page load, and claim it if so.
   *
   * Once per tab, and the record has to outlive the load it permits -- which is
   * why it is in session storage rather than in this object. A flag on the
   * instance is destroyed by the very reload it granted, so a rollout part way
   * through, or two controllers behind one address on different builds, answers
   * with a new version to each fresh document and every navigation in the tab
   * becomes a page load for as long as the rollout takes.
   *
   * Session storage is per tab and survives a reload, which is exactly the
   * scope wanted: one load to reach the current build, and never a loop.
   * Nowhere to record it is treated as "already claimed", because an old page
   * is a smaller problem than a tab that will not stay still.
   */
  claimReload(): boolean {
    if (!this.#pending) return false;
    try {
      if (sessionStorage.getItem(RELOADED_KEY) !== null) return false;
      sessionStorage.setItem(RELOADED_KEY, '1');
    } catch {
      return false;
    }
    return true;
  }

  /** Start watching. Returns the teardown, for symmetry with the router. */
  listen(): () => void {
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') void this.check();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => document.removeEventListener('visibilitychange', onVisible);
  }
}

export const upgrade = new Upgrade();

/**
 * Which of the guidelines' width ranges the window is in, as a rune.
 *
 * Nearly every responsive rule in this UI belongs in a media query and stays
 * there. This exists for the one thing CSS cannot do: the phone's navigation is
 * a different *component* rather than the same one restyled -- a bar of four
 * labelled sections and a menu, not a collapsible sidebar -- so the markup, and
 * not only the presentation, has to know. Reading it here rather than in each
 * component keeps one listener for the whole app and one place where the
 * threshold is written.
 *
 * The first value is read synchronously, so a phone never paints the desktop
 * shell for a frame before correcting itself.
 */

/** `--z-bp-md`, the phone threshold. See docs/ui-guidelines.md. */
const PHONE = '(max-width: 768px)';
/** Between the two thresholds: a desktop, but not one with room to spare. */
const NARROW = '(min-width: 769px) and (max-width: 1180px)';

class Viewport {
  #phone = $state(false);
  #narrow = $state(false);

  constructor() {
    // Absent in a non-browser build, and jsdom's is not complete; neither is
    // worth a crash on boot, and false is the desktop shell, which is the
    // safer thing to be wrong about.
    if (typeof matchMedia !== 'function') return;
    this.#watch(PHONE, (on) => (this.#phone = on));
    this.#watch(NARROW, (on) => (this.#narrow = on));
  }

  #watch(media: string, set: (on: boolean) => void): void {
    try {
      const query = matchMedia(media);
      set(query.matches);
      query.addEventListener('change', (event) => set(event.matches));
    } catch {
      /* as above */
    }
  }

  /** True below 768px: the phone layout. */
  get phone(): boolean {
    return this.#phone;
  }

  /**
   * True in the tablet range. The grids read it: a column the window has no
   * room to show properly waits for one that has, and which columns are on
   * screen decides how the rest of the width is divided, which is arithmetic
   * CSS cannot do.
   */
  get narrow(): boolean {
    return this.#narrow;
  }
}

export const viewport = new Viewport();

/**
 * The state map.
 *
 * Every status rendered anywhere in Zoomies comes from here, so an operator
 * learns one vocabulary. Each entry carries three things, and the shape is not
 * optional: colour is never the sole carrier of meaning (docs/ui-guidelines.md
 * section 1.1 and the accessibility checklist in section 6).
 *
 *   tone   which status token pair to use (`--z-busy`, `--z-busy-subtle`, ...)
 *   shape  the glyph StatusDot draws -- filled, hollow, dashed, slash, triangle, square
 *   icon   the Lucide icon Badge and the detail pages use
 *
 * An icon names a state, never an action. The Queue's Run now, Pause, Resume
 * and Delete are Zap, Pause, Play and a bin, Re-run is a turning arrow, and the
 * Runners page's Drain is the slashed circle; a status drawn with one of them
 * beside those buttons reads as something to press -- a column of busy
 * runners, each with a Play glyph, looked like runners waiting to be started.
 * One glyph also means one thing across the whole map: Activity is work
 * executing, whoever is doing it, and LoaderCircle is something still being
 * set up.
 */
import {
  Activity,
  Ban,
  ChevronsUp,
  Circle,
  CircleCheck,
  CircleDashed,
  CircleDot,
  CircleMinus,
  CircleQuestionMark,
  CircleSlash,
  CircleX,
  Clock,
  Cloud,
  Eye,
  Handshake,
  Hourglass,
  Info,
  LoaderCircle,
  Lock,
  Minus,
  Dog,
  OctagonPause,
  PawPrint,
  Rabbit,
  IterationCcw,
  Squirrel,
  TimerOff,
  TrendingDown,
  TrendingUp,
  TriangleAlert,
  Zap,
} from '@lucide/svelte';
import type { LucideIcon } from '@lucide/svelte';
import DogSitting from './icons/DogSitting.svelte';
import type {
  APIToken,
  Host,
  HostThrottle,
  JobEventKind,
  JobState,
  JoinToken,
  MachineState,
  ProvisioningStatus,
  Pool,
  Runner,
  RunnerState,
  Severity,
} from './api/types';

/** The six status hues from the token file. Nothing else may use them. */
export type StatusTone = 'idle' | 'busy' | 'pending' | 'draining' | 'danger' | 'neutral';

/**
 * The shape half of the encoding. `square` extends the five in the guidelines
 * for terminal states, which need to be distinguishable from `draining` at a
 * glance without inventing a colour.
 */
export type StatusShape = 'filled' | 'hollow' | 'dashed' | 'slash' | 'triangle' | 'square';

export interface StatusMeta {
  /** Stable key, useful for `data-` attributes and tests. */
  key: string;
  /** Sentence-case label, shown next to the shape. */
  label: string;
  tone: StatusTone;
  shape: StatusShape;
  icon: LucideIcon;
  /** The token holding this tone's foreground colour. */
  colour: string;
  /** The token for a badge or chart fill in this tone. */
  subtle: string;
  /** The token for a hairline in this tone. */
  border: string;
  /** One line an operator can act on. Used in tooltips and empty states. */
  hint?: string;
}

/** The CSS custom properties for a tone. */
export function toneTokens(tone: StatusTone): { colour: string; subtle: string; border: string } {
  return {
    colour: `var(--z-${tone})`,
    subtle: `var(--z-${tone}-subtle)`,
    border: `var(--z-${tone}-border)`,
  };
}

function meta(
  key: string,
  label: string,
  tone: StatusTone,
  shape: StatusShape,
  icon: LucideIcon,
  hint?: string,
): StatusMeta {
  return { key, label, tone, shape, icon, ...toneTokens(tone), hint };
}

/* -- runners -------------------------------------------------------------- */

/*
 * The two pending states were one dashed ring, and a runner stuck registering
 * looked exactly like one still being built -- which are different faults on
 * different machines. Draining was the slashed circle the Drain button itself
 * carries.
 */
const RUNNER: Record<RunnerState, StatusMeta> = {
  provisioning: meta(
    'provisioning',
    'Walkies!',
    'pending',
    'dashed',
    LoaderCircle,
    'The host is creating the container.',
  ),
  registering: meta(
    'registering',
    'Putting lead on',
    'pending',
    'dashed',
    Handshake,
    'Waiting for GitHub to accept the runner.',
  ),
  idle: meta('idle', 'Resting', 'idle', 'hollow', CircleDot, 'Registered and waiting for a job.'),
  busy: meta('busy', 'Walking!', 'busy', 'filled', Activity, 'Running a job right now.'),
  draining: meta(
    'draining',
    'Nearly home',
    'draining',
    'slash',
    Hourglass,
    'Finishing its current job, then exiting. No new work is sent to it.',
  ),
  failed: meta(
    'failed',
    'Slipped the lead',
    'danger',
    'triangle',
    CircleX,
    'The runner stopped unexpectedly. Its message says why.',
  ),
  removed: meta(
    'removed',
    'Back in the kennel',
    'neutral',
    'square',
    CircleMinus,
    'Gone, and deregistered from GitHub.',
  ),
};

const UNKNOWN = meta('unknown', 'Unknown', 'neutral', 'square', CircleQuestionMark);

/**
 * The same seven states, said plainly. Read instead of `RUNNER`'s label when
 * the operator has turned the kennel vocabulary off in Settings; the tone,
 * shape and icon -- already plain Lucide glyphs, not the avatar -- stay.
 */
const RUNNER_STANDARD_LABEL: Record<RunnerState, string> = {
  provisioning: 'Provisioning',
  registering: 'Registering',
  idle: 'Idle',
  busy: 'Busy',
  draining: 'Draining',
  failed: 'Failed',
  removed: 'Removed',
};

/**
 * `quirky` is passed in rather than read from a preference store here, so
 * that this module -- the one place every status comes from -- stays free of
 * Svelte's runtime and importable by the unit tests as plain TypeScript. Every
 * caller that renders to the page reads the operator's choice
 * (`prefs.quirkyStatus`) and passes it through; a caller that does not is a
 * caller with no rendered vocabulary of its own to switch, and gets the
 * kennel words, as it always has.
 */
export function runnerStatus(state: RunnerState | undefined, quirky = true): StatusMeta {
  if (!state) return UNKNOWN;
  const status = RUNNER[state] ?? UNKNOWN;
  return quirky ? status : { ...status, label: RUNNER_STANDARD_LABEL[state] };
}

/** Convenience for a row that has the whole runner to hand. */
export function runnerRowStatus(runner: Pick<Runner, 'state'>, quirky = true): StatusMeta {
  return runnerStatus(runner.state, quirky);
}

/** Every runner state with its label, for filter menus. */
export function runnerStatuses(quirky = true): StatusMeta[] {
  return (Object.keys(RUNNER) as RunnerState[]).map((state) => runnerStatus(state, quirky));
}

/**
 * Elastic CPU has its own dog-park vocabulary, backed by stable API states --
 * unless the operator has turned it off in Settings, when the same states get
 * a plain label and a standard Lucide icon instead of an animal one.
 *
 * `label` is the controller's, and the controller speaks the kennel's words,
 * so it is only taken when they are wanted. With them off, an Overview feed
 * line read "Squirrel spotted" beside a plain icon on a page where everything
 * else said "Maximum boost".
 *
 * The plain icons are a set: the two boosts rise and the throttle falls, so
 * which way a runner's CPU went is readable before the label is. The Runners
 * grid says "Extra" and "Zoomies" for the two boosts, so the icon backs the
 * word up rather than being the only thing that tells them apart.
 */
export function cpuResourceStatus(
  state: string | undefined,
  label?: string,
  quirky = true,
): StatusMeta {
  const said = quirky ? label : undefined;
  switch (state) {
    case 'maximum_zoomies':
      return quirky
        ? meta(state, said ?? 'Squirrel spotted — maximum zoomies', 'busy', 'filled', Squirrel)
        : meta(state, 'Maximum boost', 'busy', 'filled', Zap);
    case 'zoomies':
      return quirky
        ? meta(state, said ?? 'Rabbit spotted — extra zoomies', 'busy', 'filled', Rabbit)
        : meta(state, 'Extra boost', 'busy', 'filled', TrendingUp);
    case 'throttled':
      return quirky
        ? meta(state, said ?? 'Leash tightened — host under pressure', 'draining', 'slash', Dog)
        : meta(state, 'Throttled', 'draining', 'slash', TrendingDown);
    case 'observing':
      return quirky
        ? meta(
            state,
            said ?? 'Nose to the wind — watching spare CPU',
            'pending',
            'dashed',
            PawPrint,
          )
        : meta(state, 'Observing spare CPU', 'pending', 'dashed', Eye);
    case 'sit_and_stay': {
      // A pool with elastic CPU off: the runner is held at exactly its share,
      // not moving and doing as it was told. Neutral rather than idle, because
      // "guaranteed pace" is the elastic pool's word for a runner that may yet
      // be lent something, and this one never will be.
      const hint =
        'This pool has elastic CPU off, so the runner keeps its share and nothing is lent or taken back.';
      return quirky
        ? meta(
            state,
            said ?? 'Sit and stay — CPU held at its share',
            'neutral',
            'hollow',
            DogSitting,
            hint,
          )
        : meta(state, 'Held at its share', 'neutral', 'hollow', Lock, hint);
    }
    default:
      return quirky
        ? meta('guaranteed', said ?? 'Steady paws — guaranteed pace', 'idle', 'hollow', Circle)
        : meta('guaranteed', 'Guaranteed pace', 'idle', 'hollow', Circle);
  }
}

/* -- jobs -------------------------------------------------------------------
 * A job is GitHub's, so it is called what GitHub calls it. Every row on the
 * Jobs page is one workflow job with a link to the same job on GitHub, and an
 * operator reads the two side by side: "Failure" here is the failure they will
 * find there, and "Timed out" is the conclusion in the run's log. The kennel's
 * vocabulary belongs to the fleet's own objects -- a runner, and the CPU it is
 * lent -- and stops at this line. Lending it to the job lifecycle would have
 * made "Walking!" mean both a busy runner and a running job, and turned the Jobs
 * page into a second Runners page rather than the fleet's view of GitHub's
 * queue. What the fleet does to a job -- claims it, pauses its demand, loses a
 * runner under it -- is said plainly for the same reason: it is a note on a
 * job, beside GitHub's word for it.
 * ------------------------------------------------------------------------ */

const JOB_QUEUED = meta(
  'queued',
  'Queued',
  'pending',
  'dashed',
  Clock,
  'Waiting for a runner that answers its labels.',
);
const JOB_RUNNING = meta('in_progress', 'Running', 'busy', 'filled', Activity);
const JOB_WAITING = meta(
  'waiting',
  'Waiting',
  'neutral',
  'hollow',
  Clock,
  'Held by GitHub for a deployment review. Nothing runs it until someone approves it.',
);

const CONCLUSIONS: Record<string, StatusMeta> = {
  success: meta('success', 'Success', 'idle', 'filled', CircleCheck),
  failure: meta('failure', 'Failure', 'danger', 'triangle', CircleX),
  cancelled: meta('cancelled', 'Cancelled', 'neutral', 'square', Ban),
  skipped: meta('skipped', 'Skipped', 'neutral', 'hollow', Minus),
  timed_out: meta('timed_out', 'Timed out', 'danger', 'triangle', TimerOff),
  startup_failure: meta('startup_failure', 'Startup failure', 'danger', 'triangle', CircleX),
  action_required: meta('action_required', 'Action required', 'pending', 'triangle', TriangleAlert),
  neutral: meta('neutral', 'Neutral', 'neutral', 'hollow', Minus),
  stale: meta('stale', 'Stale', 'neutral', 'square', CircleMinus),
};

/** A job's status is its state, except once it is complete, when it is its conclusion. */
export function jobStatus(state: JobState | undefined, conclusion?: string | null): StatusMeta {
  if (state === 'waiting') return JOB_WAITING;
  if (state === 'queued') return JOB_QUEUED;
  if (state === 'in_progress') return JOB_RUNNING;
  if (state === 'completed') {
    const key = (conclusion ?? '').toLowerCase();
    return (
      CONCLUSIONS[key] ?? meta(key || 'completed', 'Completed', 'neutral', 'square', CircleCheck)
    );
  }
  return UNKNOWN;
}

/**
 * A workflow run still in hand with a job already failed under it.
 *
 * GitHub keeps the run "in progress" until its last job finishes, so a row that
 * read only the run's state went on saying Running for the twenty minutes after
 * the first job broke -- and an operator scanning the page for trouble found it
 * only in the counts column, or not at all. The failure is known the moment the
 * job reports it, so the run says so then: the outcome is already decided
 * unless somebody re-runs the job. Counted over the latest attempt of each job,
 * so a re-run that passes takes the run back to plain Running.
 */
export const RUN_FAILING: StatusMeta = meta(
  'failing',
  'Failing',
  'danger',
  'triangle',
  TriangleAlert,
  'A job of this run has already failed while others are still running or waiting. The run will end in failure unless the job is re-run.',
);

/** A queued job no enabled pool claims. Nothing here will start it. */
export const UNMATCHED: StatusMeta = meta(
  'unmatched',
  'Unmatched',
  'danger',
  'triangle',
  TriangleAlert,
  'No enabled pool here answers these labels, so nothing in this fleet will start it.',
);

/**
 * Whether a job is actually waiting on a pool that does not exist.
 *
 * `matched` alone is not that question. It records only that no enabled pool
 * claims the job's labels, which is equally true of every repository still on
 * GitHub-hosted or vendor runners -- jobs that run perfectly well, just not
 * here. Saying "will never run" about a job that already succeeded turns the
 * Jobs page into a wall of red during exactly the migration this fleet exists
 * to make, so the warning is kept for the one case it is true of: a job still
 * queued, with nothing to hand it to.
 */
export function stuckUnmatched(job: {
  matched?: boolean;
  state?: JobState;
  hosted?: boolean;
}): boolean {
  return job.matched === false && job.state === 'queued' && !job.hosted;
}

/**
 * The operator's vocabulary for a queued job's provisioning demand, in one
 * place: the Queue's status buttons, the Jobs page's filter chip and the badge
 * on a job row all read from here, so the same state is never called two
 * things on two pages. "Removed" rather than "deleted" throughout -- the row
 * is still there, and restoring it is one press.
 */
export const QUEUE_STATUS_LABELS: Record<ProvisioningStatus, string> = {
  ready: 'Ready',
  expedited: 'Run now',
  paused: 'Paused',
  deleted: 'Removed',
};

/**
 * What an operator has done to a queued job's provisioning demand, where they
 * have done anything. Undefined for the ordinary case, which needs no badge.
 *
 * A job stood down from the queue is still `queued` as far as GitHub is
 * concerned -- Zoomies cannot unqueue it -- so a list that showed only the
 * state called it plainly Queued and left the operator's own decision
 * invisible. These say it beside the state wherever a job is listed, which is
 * what keeps a page that shows the job honest about what the fleet will do
 * with it.
 */
export const QUEUE_PAUSED: StatusMeta = meta(
  'paused',
  'Paused',
  'draining',
  'hollow',
  OctagonPause,
  'An operator put this job\u2019s provisioning demand on hold. It is still waiting, and no new runner will be created for it until it is resumed.',
);

/**
 * The other thing an operator can do to a queued job: ask for it now. Not a
 * standing-down, so it is the queued tone rather than a warning one, but
 * still a decision the row has to show -- a Run now pressed on a job whose
 * row went on reading plainly Queued looked like a button that did nothing.
 */
export const QUEUE_EXPEDITED: StatusMeta = meta(
  'expedited',
  'Run now',
  'pending',
  'filled',
  ChevronsUp,
  'An operator asked for this job to run now. It is prioritised within its pool\u2019s priority tier and skips the scale-up delay; it is still waiting for a runner, and pool and host limits still apply.',
);

export const QUEUE_REMOVED: StatusMeta = meta(
  'removed',
  'Removed',
  'neutral',
  'square',
  CircleMinus,
  'An operator removed this job from the queue, so it no longer counts as work this fleet is waiting on. Restore it from the Queue page\u2019s Removed view.',
);

/**
 * The badge for a job an operator has stood down, or nothing for one they have
 * not touched. Only a job still queued can carry one: once something has run
 * it, what was done to its demand is history rather than status.
 */
/**
 * A job on its way out because somebody cancelled its workflow run, which
 * GitHub has not yet confirmed.
 *
 * GitHub owns the conclusion, so the row goes on reading `queued` or
 * `in_progress` until its completion delivery lands -- which can be minutes.
 * The job is neither by then: the queued half raises no demand and the running
 * half has had its runner taken away.
 */
export const CANCELLING: StatusMeta = meta(
  'cancelling',
  'Cancelling',
  'neutral',
  'square',
  CircleSlash,
  'Its workflow run was cancelled and GitHub has accepted the request. The fleet has already stopped work on it; the conclusion follows when GitHub reports it.',
);

export function queueStatus(job: {
  state?: JobState;
  provisioning?: string;
  provision_now?: boolean;
  cancel_requested_at?: string | null;
}): StatusMeta | undefined {
  // Cancelling outranks the rest, and is the one that applies to a running
  // job as well. A cancellation also pauses the run's queued jobs, so without
  // this a job somebody cancelled would be reported as one an operator had
  // merely put on hold.
  if (job.state !== 'queued' && job.state !== 'in_progress') return undefined;
  if (job.cancel_requested_at) return CANCELLING;
  if (job.state !== 'queued') return undefined;
  if (job.provisioning === 'paused') return QUEUE_PAUSED;
  if (job.provisioning === 'deleted') return QUEUE_REMOVED;
  if (job.provision_now) return QUEUE_EXPEDITED;
  return undefined;
}

/**
 * A job no runner of this fleet ran. The Overview's panels show these only
 * when asked to: GitHub reports every job in the repositories an installation
 * covers, and on an organisation that also uses hosted, vendor or another
 * self-hosted provider's runners, most of them are somebody else's.
 */
export const ELSEWHERE: StatusMeta = meta(
  'elsewhere',
  'Elsewhere',
  'neutral',
  'hollow',
  Cloud,
  'No runner of this fleet ran this job. It is listed because GitHub reports every job in the repositories this installation covers.',
);

/** A job one of this fleet's runners picked up. */
export function ranHere(job: { runner_id?: string }): boolean {
  return Boolean(job.runner_id);
}

/**
 * Whether this fleet has a hand in a job that is not queued: a pool claims its
 * labels, or a runner here ran it. It mirrors the server's `managed` filter,
 * and lives next to the places that use it so a panel's live frames and its
 * fetch cannot disagree about what belongs on the page -- which they did.
 */
export function managedJob(job: {
  matched?: boolean;
  pool_id?: string;
  runner_id?: string;
}): boolean {
  return Boolean(job.matched || job.pool_id || job.runner_id);
}

/**
 * A job whose labels all name runners somebody else operates: GitHub's own, or
 * a hosted-runner vendor's. It runs there, and is never stuck on this fleet's
 * account however long it queues.
 */
export const HOSTED: StatusMeta = meta(
  'hosted',
  'Hosted elsewhere',
  'neutral',
  'hollow',
  Cloud,
  "Its labels name GitHub's own runners or a hosted-runner vendor's, so it runs there rather than on this fleet.",
);

/**
 * A job whose runner stopped under it. GitHub records the job as an ordinary
 * failure; this badge is how the fleet owns up to having caused it.
 */
/** A job whose runner, or one of its steps, the kernel killed for memory. */
export const OOM_KILLED: StatusMeta = meta(
  'oom_killed',
  'Killed for memory',
  'danger',
  'triangle',
  TriangleAlert,
  "The kernel killed this job's runner, or one of its steps, for its memory limit. GitHub records an ordinary failure; the fault is the fleet's.",
);

export const RUNNER_LOST: StatusMeta = meta(
  'runner_lost',
  'Runner lost',
  'danger',
  'triangle',
  TriangleAlert,
  "The runner executing this job stopped before GitHub reported the job over. The failure is the fleet's, not the workflow's.",
);

/**
 * Whether a job went wrong on either side. The rule lives in outcomes.ts, so
 * the activity matrix can count jobs the same way without loading the icons
 * this file imports; it is re-exported here because this is where every page
 * looks for it.
 */
export { jobFailed } from './outcomes';

/**
 * One step of a job, coloured like the job it belongs to: a step still running
 * is busy, one that has not started is pending, and a finished one takes its
 * conclusion.
 */
export function stepStatus(step: { status?: string; conclusion?: string }): StatusMeta {
  if (step.status === 'completed' || step.conclusion) {
    return jobStatus('completed', step.conclusion);
  }
  if (step.status === 'in_progress') return JOB_RUNNING;
  return meta('queued', 'Not started', 'pending', 'hollow', Clock);
}

/* -- the job timeline ----------------------------------------------------- */

const JOB_EVENTS: Record<JobEventKind, StatusMeta> = {
  queued: JOB_QUEUED,
  waiting: JOB_WAITING,
  approved: meta(
    'approved',
    'Approved',
    'pending',
    'dashed',
    Clock,
    'The deployment review passed. The queue wait starts here.',
  ),
  claimed: meta('claimed', 'Claimed', 'idle', 'hollow', Circle),
  unmatched: UNMATCHED,
  started: JOB_RUNNING,
  completed: meta('completed', 'Completed', 'neutral', 'square', CircleCheck),
  runner_lost: RUNNER_LOST,
  runner_returned: meta(
    'runner_returned',
    'Runner returned',
    'idle',
    'hollow',
    CircleCheck,
    'The runner reported lost is alive after all and this job is still running on it. The entry above it stands as what the fleet believed at the time.',
  ),
  cancel_requested: meta(
    'cancel_requested',
    'Cancellation requested',
    'pending',
    'slash',
    CircleSlash,
    'Zoomies asked GitHub to cancel the workflow run and is waiting for GitHub to confirm the terminal state.',
  ),
  // Pending rather than danger, and the wording is the reason: this job has
  // not failed. A runner meant for work like it died on the way up, the job is
  // still queued, and the next runner may well run it -- drawn red it would
  // read as an outcome, which is the one thing it is not.
  runner_start_failed: meta(
    'runner_start_failed',
    'A runner failed to start',
    'pending',
    'dashed',
    TriangleAlert,
    'A runner this pool started for work like this job died before it could take one. This job is still queued; a pool that cannot start a container otherwise looks exactly like a pool that is merely busy.',
  ),
  rerun_requested: meta(
    'rerun_requested',
    'Re-run requested',
    'pending',
    'dashed',
    IterationCcw,
    "Zoomies asked GitHub to run this run's failed jobs again. They arrive as a new run attempt, so GitHub remains authoritative about what happens next.",
  ),
  oom_killed: OOM_KILLED,
};

/**
 * The status a timeline entry is drawn with. A `completed` entry takes the
 * job's own conclusion when it is known, so the last mark on a failed job's
 * timeline is red rather than a neutral "it ended".
 */
export function jobEventStatus(
  kind: JobEventKind | undefined,
  conclusion?: string | null,
): StatusMeta {
  if (kind === 'completed' && conclusion) return jobStatus('completed', conclusion);
  return kind ? (JOB_EVENTS[kind] ?? UNKNOWN) : UNKNOWN;
}

/* -- hosts ---------------------------------------------------------------- */

/**
 * The top rung of the throttle ladder, mirroring store.MaxThrottleLevel. Each
 * rung takes a quarter of the host's slots; a fourth would take it to nothing,
 * which is a cordon, and a cordon is the operator's to apply.
 */
export const MAX_THROTTLE_LEVEL = 3;

/** Whether the controller has a host on any rung at all. */
export function throttled(throttle: HostThrottle | undefined | null): boolean {
  return (throttle?.level ?? 0) > 0;
}

/**
 * What a throttled host's runners with a CPU limit are running at, as a
 * percentage of their allocation. Mirrors store.HostThrottle.CPUFactor: a
 * quarter off per rung, floored at half, because the top rung takes slots
 * only -- a job at a quarter of its CPU is a job that never finishes.
 */
export function throttleCpuPercent(throttle: HostThrottle | undefined | null): number {
  const level = Math.min(Math.max(throttle?.level ?? 0, 0), MAX_THROTTLE_LEVEL);
  return Math.max(50, 100 - 25 * level);
}

export function hostStatus(host: Pick<Host, 'healthy' | 'cordoned' | 'throttle'>): StatusMeta {
  if (host.healthy === false) {
    return meta(
      'unreachable',
      'Unreachable',
      'danger',
      'triangle',
      TriangleAlert,
      'No heartbeat recently. Check the agent on this host.',
    );
  }
  if (host.cordoned) {
    return meta(
      'cordoned',
      'Cordoned',
      'draining',
      'slash',
      CircleSlash,
      'Existing runners keep going; no new ones are placed here.',
    );
  }
  if (throttled(host.throttle)) {
    // Its own shape: a throttle is neither a cordon (the fleet did it, and
    // will undo it) nor unreachable (the agent is talking; that is how the
    // fleet knows). The step is in the hint because the badge is the one
    // place on the card an operator hovers to ask "how bad".
    return meta(
      'throttled',
      'Throttled',
      'pending',
      'dashed',
      CircleDashed,
      `Throttled, step ${host.throttle?.level} of ${MAX_THROTTLE_LEVEL}: the fleet is taking fewer new runners here after sustained pressure. It lifts one step after five minutes of calm.`,
    );
  }
  return meta('healthy', 'Healthy', 'idle', 'hollow', Circle);
}

/* -- machines -------------------------------------------------------------- */

/**
 * Where a rented machine is in its life.
 *
 * The tones are the fixed mapping every other page uses, and deliberately the
 * same ones a runner gets for the same idea: a machine being built reads as
 * pending exactly as a runner being provisioned does, so an operator learns one
 * vocabulary rather than two. The icons follow the same rule: a machine being
 * built takes a provisioning runner's glyph, one enrolling a registering
 * runner's, and one carrying work is drawn as a busy runner is. `hasRunners`
 * is what separates a machine that has arrived from one that is carrying work
 * -- the row itself cannot say, because a ready machine and a busy one are the
 * same state.
 */
export function machineStatus(state: MachineState | undefined, hasRunners = false): StatusMeta {
  switch (state) {
    case 'planned':
      return meta(
        'planned',
        'Planned',
        'pending',
        'dashed',
        CircleDashed,
        'The row exists and nothing has been created yet.',
      );
    case 'creating':
      return meta(
        'creating',
        'Creating',
        'pending',
        'dashed',
        LoaderCircle,
        'The provider is building the machine.',
      );
    case 'starting':
      return meta(
        'starting',
        'Starting',
        'pending',
        'dashed',
        LoaderCircle,
        'The machine exists and is being powered on.',
      );
    case 'bootstrapping':
      return meta(
        'bootstrapping',
        'Bootstrapping',
        'pending',
        'dashed',
        LoaderCircle,
        'The guest is up and the agent is being installed.',
      );
    case 'enrolling':
      return meta(
        'enrolling',
        'Enrolling',
        'pending',
        'dashed',
        Handshake,
        'The agent has its credential and has not joined yet.',
      );
    case 'ready':
      return hasRunners
        ? meta('busy', 'Running work', 'busy', 'filled', Activity, 'A host, with runners on it.')
        : meta('ready', 'Ready', 'idle', 'hollow', CircleDot, 'A host, waiting for work.');
    case 'draining':
      return meta(
        'draining',
        'Draining',
        'draining',
        'slash',
        CircleSlash,
        'Its runners finish; the machine is deleted when the last one does.',
      );
    case 'deleting':
      return meta(
        'deleting',
        'Deleting',
        'draining',
        'slash',
        CircleSlash,
        'A delete was issued and the provider has not confirmed the resource is gone.',
      );
    case 'failed':
      return meta(
        'failed',
        'Failed',
        'danger',
        'triangle',
        TriangleAlert,
        'The lifecycle was given up on. The resource behind it may still exist, and still cost money.',
      );
    case 'quarantined':
      return meta(
        'quarantined',
        'Quarantined',
        'danger',
        'triangle',
        TriangleAlert,
        'Ownership of this resource could not be proved, so nothing here will act on it. Only a person moves it.',
      );
    case 'deleted':
      return meta(
        'deleted',
        'Deleted',
        'neutral',
        'square',
        CircleMinus,
        'The provider confirmed the resource is gone.',
      );
    default:
      return UNKNOWN;
  }
}

/* -- pools ---------------------------------------------------------------- */

export function poolStatus(pool: Pick<Pool, 'enabled'>): StatusMeta {
  return pool.enabled === false
    ? meta(
        'disabled',
        'Disabled',
        'draining',
        'slash',
        CircleSlash,
        'Existing runners drain; no new ones are made.',
      )
    : meta('enabled', 'Enabled', 'idle', 'hollow', Circle);
}

/* -- problems and deliveries ---------------------------------------------- */

export function severityStatus(severity: Severity | undefined): StatusMeta {
  if (severity === 'error') return meta('error', 'Error', 'danger', 'triangle', TriangleAlert);
  if (severity === 'warning')
    return meta('warning', 'Warning', 'pending', 'triangle', TriangleAlert);
  return meta('info', 'Info', 'busy', 'hollow', Info);
}

export type DeliveryStatus = 'accepted' | 'rejected' | 'error';

export function deliveryStatus(status: DeliveryStatus | undefined): StatusMeta {
  if (status === 'accepted') return meta('accepted', 'Accepted', 'idle', 'filled', CircleCheck);
  if (status === 'rejected') {
    return meta(
      'rejected',
      'Rejected',
      'danger',
      'triangle',
      CircleX,
      'The signature did not verify. Check the webhook secret.',
    );
  }
  if (status === 'error') return meta('error', 'Error', 'danger', 'triangle', TriangleAlert);
  return UNKNOWN;
}

/** GitHub App connection health. */
export function installationStatus(healthy: boolean | undefined): StatusMeta {
  if (healthy === true) return meta('healthy', 'Connected', 'idle', 'hollow', Circle);
  if (healthy === false) {
    return meta(
      'unhealthy',
      'Not connected',
      'danger',
      'triangle',
      TriangleAlert,
      'Verify the installation to see which credential or permission is missing.',
    );
  }
  return meta('unchecked', 'Not checked', 'neutral', 'dashed', CircleDashed);
}

/** A user or token account state. */
export function accountStatus(disabled: boolean | undefined): StatusMeta {
  return disabled
    ? meta('disabled', 'Disabled', 'draining', 'slash', CircleSlash)
    : meta('active', 'Active', 'idle', 'hollow', Circle);
}

/* -- credentials ---------------------------------------------------------- */

/** How soon "expires soon" is: a week, so the warning lands on a working day. */
const EXPIRY_WARNING_MS = 7 * 24 * 60 * 60 * 1000;

/** Where an API token is in its life: revoked, expired, expiring, or good. */
export function apiTokenStatus(
  token: Pick<APIToken, 'revoked' | 'expires_at'>,
  now: number = Date.now(),
): StatusMeta {
  if (token.revoked) {
    return meta(
      'revoked',
      'Revoked',
      'draining',
      'slash',
      CircleSlash,
      'Switched off by an administrator.',
    );
  }
  if (!token.expires_at) {
    return meta(
      'never_expires',
      'Never expires',
      'pending',
      'triangle',
      TriangleAlert,
      'A token with no expiry stays valid until it is revoked.',
    );
  }
  const remaining = new Date(token.expires_at).getTime() - now;
  if (remaining <= 0) return meta('expired', 'Expired', 'neutral', 'square', CircleMinus);
  if (remaining < EXPIRY_WARNING_MS) {
    return meta(
      'expiring',
      'Expires soon',
      'pending',
      'dashed',
      Clock,
      'Create a replacement before it does.',
    );
  }
  return meta('active', 'Active', 'idle', 'hollow', Circle);
}

/** Whether a join token can still enrol a host. */
export function joinTokenStatus(token: Pick<JoinToken, 'used_at' | 'usable'>): StatusMeta {
  if (token.used_at) {
    return meta(
      'used',
      'Used',
      'neutral',
      'square',
      CircleMinus,
      'A join token enrols one host, once.',
    );
  }
  if (token.usable === false) {
    return meta(
      'expired',
      'Expired',
      'draining',
      'slash',
      CircleSlash,
      'Create a new one to add a host.',
    );
  }
  return meta('usable', 'Usable', 'idle', 'hollow', Circle);
}

/** Whether the webhook address answered the controller's own probe. */
export function reachabilityStatus(reachable: boolean | undefined): StatusMeta {
  if (reachable === true) return meta('reachable', 'Reachable', 'idle', 'filled', CircleCheck);
  if (reachable === false) {
    return meta(
      'unreachable',
      'Not reachable',
      'danger',
      'triangle',
      TriangleAlert,
      'Nothing answered at the webhook address, so GitHub cannot deliver to it either.',
    );
  }
  return meta('unchecked', 'Not checked', 'neutral', 'dashed', CircleDashed);
}

