/*
 * Fonts, subset to Latin and self-hosted.
 *
 * These faces are declared by hand rather than by importing @fontsource's own
 * stylesheets, because those pull in Cyrillic, Greek and Vietnamese subsets in
 * both woff and woff2 -- around forty files for an interface that is in English.
 * Declaring the four faces we actually use keeps the payload honest and lets us
 * set font-display and the unicode ranges deliberately.
 *
 * Self-hosted, so an air-gapped install makes no third-party font request and
 * neither does anyone else's browser.
 */

/* Inter Variable -- the whole weight axis in one file. */
@font-face {
  font-family: 'InterVariable';
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url('@fontsource-variable/inter/files/inter-latin-wght-normal.woff2')
    format('woff2-variations');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'InterVariable';
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  src: url('@fontsource-variable/inter/files/inter-latin-ext-wght-normal.woff2')
