/*
 * Zoomies design tokens.
 *
 * This file is the only place a colour, size, radius or duration is defined.
 * Everything else -- components, Tailwind utilities, hand-written CSS -- reads
 * from here. See docs/ui-guidelines.md for the reasoning and the measured
 * contrast ratios, and the brand pack in docs/brand.md for what is fixed.
 *
 * The palette comes from the Zoomies brand: near-black, white and cool grey,
 * with Runner Blue as the interactive accent and Fast Cyan reserved for the one
 * thing that is actually moving. The logo itself stays monochrome.
 *
 * Theming works in three states:
 *   light                    :root
 *   dark, by system setting  @media (prefers-color-scheme: dark) on :root:not([data-theme="light"])
 *   dark, chosen explicitly  :root[data-theme="dark"]
 * so an explicit choice wins in both directions and "system" needs no attribute.
 */

:root {
  /* ---------------------------------------------------------------------
   * Brand constants. These are the identity and do not change between
   * themes; the semantic tokens below are derived from them.
   * ------------------------------------------------------------------ */
  --z-brand-black: #080808;
  --z-brand-white: #ffffff;
  --z-brand-cool-grey: #b9bcc2;
  --z-brand-mid-grey: #666a73;
  --z-brand-runner-blue: #2f80ed;
  --z-brand-fast-cyan: #22d3ee;
  --z-brand-paw-black: #000000;
  /* Fixed illustration colours preserve the black-and-white spaniel in both
     themes. Its backdrop and collar use semantic surface/status colours. */
  --z-avatar-fur: #202630;
  --z-avatar-ink: #111722;
  --z-avatar-cream: #fffaf1;
  --z-avatar-shine: #47505e;
  --z-avatar-white: #ffffff;
  --z-avatar-tongue: #ed8f9f;
  --z-avatar-tongue-line: #c56779;
  --z-avatar-freckle: #b7b5b0;
  --z-avatar-tag: #f5d781;
  --z-avatar-tag-ink: #6b5524;
  --z-avatar-accent: #5eb89c;
  --z-avatar-size: 2.75rem;
  --z-status-icon-size: var(--z-space-6);
  /* The Standard spaniel is a black cocker with a white muzzle and toes,
     named by role rather than value so a theme can move a colour without
     redrawing the dog. Line is the outline, which traces the silhouette
     only: on a light row it is the coat's own black, which gives the white
     muzzle and toes an edge and leaves the black parts as they are. Of the
     dog's near side, the ear is the one part a shade off the coat, so the
     ear stays an ear at 32px instead of merging into the body. Far is the
     far-side legs. No line runs between a near leg and a far one, so they
     recede by value alone: a clear step off the coat, or a galloping dog's
     folded legs merge into one black lump under the belly. Rim is the ear's
     front edge, an offered forearm and the haunch's crease -- like the rim
     light in the mark; apart from the face's own lid and brow, they are the
     only light lines inside the dog. Ink is the features on the white
     blaze and stays dark in both themes. Every fill is solid so overlapping
     animated limbs stay opaque. */
  --z-standard-coat: var(--z-brand-black);
  --z-standard-line: var(--z-brand-black);
  --z-standard-ear: #2b2f36;
  --z-standard-rim: var(--z-brand-mid-grey);
  --z-standard-blaze: var(--z-brand-white);
  --z-standard-far: #34383f;
  --z-standard-ink: var(--z-brand-black);
  /* Speed lines and the scent trail: marks beside the dog
     rather than part of it, so a grey that reads on a light row. */
  --z-standard-cue: #4d525b;

  /* Two of these are the record rather than a value anything reads. Mid Grey
     is the brand's light-theme secondary text, but --z-text-muted darkens it
     to #5b6069 for the same reason the accent is darkened below: at 13px on
     white the brand value is 5.4:1, and body text that an operator reads all
     day should be past 7:1. Paw Black is the favicon artwork, which is a PNG,
     not a colour any rule sets. */

  /* ---------------------------------------------------------------------
   * Neutrals. A cool near-black spine, per the brand palette.
   * ------------------------------------------------------------------ */
  --z-bg: #f6f7f9;
  --z-surface: var(--z-brand-white);
  --z-surface-raised: var(--z-brand-white);
  --z-surface-sunken: #eef0f3;
  --z-surface-hover: #f1f3f6;
  --z-border: #e2e5ea;
  --z-border-strong: #c7cbd3;
  --z-text: #0b0c0e;
  --z-text-muted: #5b6069;
  --z-text-subtle: #666b74;
  --z-text-inverse: #f6f7f9;

  /* Brand accent -------------------------------------------------------
   * Runner Blue at full strength (#2F80ED) is 3.87:1 on white: fine for a
   * large shape, not fine for 13px text or for white text on a button. The
   * interactive accent is therefore a darkened Runner Blue at 5.5:1, and the
   * pure brand blue is kept for illustrative fills where 3:1 is the bar.
   * ------------------------------------------------------------------ */
  --z-accent: #1a63d8;
  --z-accent-hover: #154fb0;
  --z-accent-active: #113f8e;
  --z-accent-subtle: #e8f0fd;
  --z-accent-border: #bcd4f8;
  --z-accent-contrast: #ffffff;

  /* Status -------------------------------------------------------------
   * Fixed meanings. Do not reuse these hues for anything else; operators
   * learn them. Colour is never the only carrier -- see StatusDot. Busy is
   * Fast Cyan, which is the brand's "used sparingly" accent spent on the one
   * thing that is actually moving.
   *
   * The six are separated in lightness and chroma as well as hue, because a
   * legend is where they are read side by side and hue alone was not enough:
   * every one of them used to sit within a few points of L* 45, which left
   * draining and neutral -- two greys at the same lightness -- 6 points of
   * CIEDE2000 apart, where a legend dot wants around 20. Draining now carries
   * a plum cast and the far end of the lightness range (dark on light, light
   * on dark, because it is a state an operator has asked for and should be
   * able to find), and neutral is the only flat grey left, sitting quietly
   * at its contrast floor. No pair that can share a legend is now under 19,
   * and most are past 25. docs/ui-guidelines.md carries the measurements.
   * ------------------------------------------------------------------ */
  --z-idle: #0f7a3d;
  --z-idle-subtle: #e7f1eb;
  --z-idle-border: #bbd9c8;

  --z-busy: #00757f;
  --z-busy-subtle: #e9f3f4;
  --z-busy-border: #bddcde;

  --z-pending: #9a6100;
  --z-pending-subtle: #f6f2e9;
  --z-pending-border: #e6d8c1;

  --z-draining: #4d3f5c;
  --z-draining-subtle: #edecef;
  --z-draining-border: #d2cfd6;

  --z-danger: #bd2018;
  --z-danger-hover: #96190f;
  --z-danger-subtle: #faedec;
  --z-danger-border: #efc9c8;
  --z-danger-contrast: #ffffff;

  --z-neutral: #686d76;
  --z-neutral-subtle: #f4f4f5;
  --z-neutral-border: #dddee0;

  /* Categorical chart ramp, ordered for maximum adjacent separation. */
  --z-chart-1: #1a63d8;
  --z-chart-2: #9a6100;
  --z-chart-3: #0f7a3d;
  --z-chart-4: #00757f;
  --z-chart-5: #bd2018;
  --z-chart-6: #4d3f5c;

  /* Focus ----------------------------------------------------------------
   * One look, two mechanisms. `outline` is the global rule in app.css and is
   * what almost everything gets. `--z-focus-ring` draws the same ring as a
   * box-shadow, for the controls whose outline a scrolling or clipping parent
   * would cut off -- the command palette's input inside its rounded container
   * is the one that made this necessary. A consumer on a raised surface
   * overrides --z-focus-gap so the ring's inner gap matches what it sits on.
   * ------------------------------------------------------------------ */
  --z-focus-width: var(--z-border-width-thick);
  --z-focus-offset: 2px;
  --z-focus-colour: var(--z-accent);
  --z-focus-gap: var(--z-surface);
  --z-focus-ring:
    0 0 0 var(--z-focus-offset) var(--z-focus-gap),
    0 0 0 calc(var(--z-focus-offset) + var(--z-focus-width)) var(--z-focus-colour);

  /* Type ----------------------------------------------------------------
   * Inter, per the brand. Base is 13px, not 16px: this is a dense operational
   * tool, and 13px Inter at 450 stays comfortable while fitting a useful
   * number of runners on screen.
   * ------------------------------------------------------------------ */
  --z-font-sans:
    'InterVariable', 'Inter', 'Geist', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    'Segoe UI', Roboto, sans-serif;
  --z-font-mono:
    'JetBrains Mono', ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono',
    monospace;

  --z-text-2xs: 0.6875rem; /* 11px */
  --z-text-xs: 0.75rem; /* 12px */
  --z-text-sm: 0.8125rem; /* 13px -- default */
  --z-text-base: 0.875rem; /* 14px */
  --z-text-lg: 1rem; /* 16px */
  --z-text-xl: 1.25rem; /* 20px */
  --z-text-2xl: 1.75rem; /* 28px */
  --z-text-3xl: 2.25rem; /* 36px */

  --z-leading-2xs: 1rem;
  --z-leading-xs: 1.125rem;
  --z-leading-sm: 1.25rem;
  --z-leading-base: 1.375rem;
  --z-leading-lg: 1.5rem;
  --z-leading-xl: 1.75rem;
  --z-leading-2xl: 2.125rem;
  --z-leading-3xl: 2.625rem;

  --z-weight-normal: 450;
  --z-weight-medium: 500;
  --z-weight-semibold: 550;
  --z-weight-bold: 640;

  /* Spacing -- a 4px base, and only these steps exist. ------------------- */
  --z-space-1: 0.25rem;
  --z-space-2: 0.5rem;
  --z-space-3: 0.75rem;
  --z-space-4: 1rem;
  --z-space-5: 1.25rem;
  --z-space-6: 1.5rem;
  --z-space-8: 2rem;
  --z-space-10: 2.5rem;
  --z-space-12: 3rem;
  --z-space-16: 4rem;

  /* Radii ---------------------------------------------------------------- */
  --z-radius-sm: 4px;
  --z-radius-md: 8px;
  --z-radius-lg: 12px;
  --z-radius-full: 9999px;

  /* Borders --------------------------------------------------------------
   * Two weights, and the choice between them is meaning rather than taste:
   * the hairline separates things that belong together, the thick edge marks
   * the one that is selected, focused or wrong. A third weight would only
   * make the second one quieter.
   * ------------------------------------------------------------------ */
  --z-border-width: 1px;
  --z-border-width-thick: 2px;
  /* The rail down the side of a problem, a disabled pool or a failed step.
     Thicker than an edge because it is a flag, not a boundary. */
  --z-border-width-rail: 3px;

  /* Optical nudges -------------------------------------------------------
   * Below the 4px spacing grid on purpose. A checkbox aligned to the grid
   * sits visibly low against a 13px line, and the gap between a label and the
   * hint under it wants to be tighter than the smallest grid step. Anything
   * that can be on the spacing scale is on the spacing scale.
   * ------------------------------------------------------------------ */
  --z-nudge-1: 1px;
  --z-nudge-2: 2px;
  --z-nudge-3: 3px;

  /* Widths ---------------------------------------------------------------
   * Dialogs and drawers are cut to their content's comfortable measure, not
   * to the viewport, so each has three sizes and they are the three shapes we
   * actually put in one: a confirmation, a form, a table.
   * ------------------------------------------------------------------ */
  --z-width-dialog-sm: 400px;
  --z-width-dialog-md: 560px;
  --z-width-dialog-lg: 820px;
  --z-width-drawer-sm: 360px;
  --z-width-drawer-md: 520px;
  --z-width-drawer-lg: 760px;

  /* Controls -------------------------------------------------------------
   * The drawn controls -- the checkbox box, the switch thumb, the icon in a
   * button -- are sized to sit optically on a 13px line rather than on the
   * 4px spacing grid, so they get their own names. Everything larger (field
   * and button heights) is on the spacing scale and stays there.
   * ------------------------------------------------------------------ */
  --z-control-box: 15px;
  --z-control-thumb: 14px;
  --z-control-icon: 14px;
  /* iOS zooms the page when a focused field's text is under 16px, so under
     the phone breakpoint every text control steps up to this. */
  --z-control-font-touch: 16px;
  /* The smallest target a finger hits reliably, which both platforms' own
     guidance puts at 44 to 48 points. A control read by touch -- the chart
     chips, a segmented choice, a legend's switches -- takes this as its height
     where the pointer is coarse, and keeps its dense desktop height elsewhere. */
  --z-control-touch: 44px;

  /* Tracking -------------------------------------------------------------
   * Uppercase text needs air or it sets as a block; display text at 28px and
   * up needs the opposite. Body text is left alone.
   * ------------------------------------------------------------------ */
  --z-tracking-tight: -0.01em;
  --z-tracking-wide: 0.04em;
  --z-tracking-wider: 0.08em;
  /* How far a hover underline sits below a quiet link, clear of the
     descenders so "EyUp.io" does not read as a strikethrough. */
  --z-underline-offset: 0.15em;

  /* Breakpoints ----------------------------------------------------------
   * Two, and only two: phone below 768, sidebar above 1180. These are the
   * one place a raw px is unavoidable, because `@media (max-width: var(…))`
   * is not valid CSS -- a media query is evaluated before custom properties
   * exist. They are declared here so the number has a home, and so the few
   * places that need the same threshold in JavaScript can read it rather
   * than repeat it.
   * ------------------------------------------------------------------ */
  --z-bp-md: 768px;
  --z-bp-lg: 1180px;

  /* Elevation -- cool-tinted and restrained; in dark mode elevation is
     carried mostly by surface colour rather than shadow. ------------------ */
  --z-shadow-sm: 0 1px 2px rgb(8 12 20 / 0.06);
  --z-shadow-md: 0 4px 12px -2px rgb(8 12 20 / 0.1);
  --z-shadow-lg: 0 16px 40px -8px rgb(8 12 20 / 0.16);

  /* The veil behind a modal -- Dialog, Drawer, the command palette and the
     phone's navigation sheet. Made from the page's own ground, so it dims in
     light and in dark without a hard-coded black that only works in one of
     them; it needs no dark override for that reason. One recipe, because a
     Dialog opened over a Drawer must not dim the page by two amounts. */
  --z-scrim: color-mix(in srgb, var(--z-bg) 72%, transparent);
  --z-scrim-blur: 3px;

  /* Motion --------------------------------------------------------------- */
  --z-motion-fast: 120ms;
  --z-motion-base: 200ms;
  --z-motion-slow: 320ms;
  --z-ease: cubic-bezier(0.2, 0.8, 0.2, 1);

  /* Scrollbars ----------------------------------------------------------
   * The one control the browser draws for us, and so the one that is easiest
   * to leave too faint to find. The thumb borrows the weakest text colour,
   * which is never below 4.7:1 light or 4.8:1 dark on any surface it can sit
   * on -- past the 3:1 bar for a control -- and the column is wide enough to
   * aim at. The track is a tint rather than a colour so it reads on a white
   * card and a sunken well alike.
   * ------------------------------------------------------------------ */
  --z-scrollbar-size: 14px;
  --z-scrollbar-inset: 3px;
  --z-scrollbar-thumb: var(--z-text-subtle);
  --z-scrollbar-thumb-hover: var(--z-text-muted);
  --z-scrollbar-thumb-active: var(--z-text);
  --z-scrollbar-track: rgb(8 12 20 / 0.06);

  /* Layout --------------------------------------------------------------- */
  --z-nav-width: 232px;
  --z-nav-width-collapsed: 56px;
  --z-topbar-height: 52px;
  --z-content-max: 1600px;
  /* The Settings section's own rail, and the measure its pages are cut to: a
     list of accounts or a column of setting rows reads better at a comfortable
     width than stretched across a wide monitor. */
  --z-settings-rail-width: 200px;
  --z-settings-page-max: 960px;

  /* The window, which on a phone is not the same thing as 100%. A mobile
     browser answers a page that overflows sideways by laying the whole thing
     out in a wider block and showing it smaller, and everything positioned
     against the viewport is laid out in that block rather than against the
     screen -- so one row a few pixels past the edge took the problems drawer
     with it, off the side of the phone. `100%` is the widened block and
     `100vw` stays the window, so the smaller of the two is the window on a
     phone, and on a desktop it is the side that does not add a scrollbar. */
  --z-window-width: min(100vw, 100%);

  /* Mobile Chrome can place Android's gesture bar over the layout while
     reporting a zero safe-area inset. Keep a small floor so controls pinned
     to the bottom edge remain readable there; notched devices still supply
     their larger native inset. */
  --z-safe-bottom: max(env(safe-area-inset-bottom, 0px), var(--z-space-3));
  /* The top edge has no such floor: only the sign-in page's black band is
     drawn to the very top, and it wants the status bar's height and no more. */
  --z-safe-top: env(safe-area-inset-top, 0px);

  /* The chip the monochrome mark sits on. The brand sanctions the white
     knockout over dark surfaces, so one asset serves both themes when it is
     drawn on a near-black chip. */
  --z-mark-chip: var(--z-brand-black);

  /* The sign-in page's brand panel, which is Zoomies Black in both themes.
     What is drawn on it therefore cannot follow the theme -- the light
     theme's muted grey on black is barely 3:1 -- so these are the dark
     theme's values, fixed, and only that panel reads them. */
  --z-panel-bg: var(--z-brand-black);
  --z-panel-text: var(--z-brand-white);
  --z-panel-text-muted: var(--z-brand-cool-grey);
  --z-panel-text-subtle: #868b94;
  --z-panel-border: #262a31;
  --z-panel-raised: #121418;
  --z-panel-ring: rgb(255 255 255 / 0.07);

  /* Z-index. Named so that "what is on top of what" is answerable. -------- */
  --z-layer-sticky: 10;
  --z-layer-nav: 20;
  --z-layer-dropdown: 40;
  --z-layer-drawer: 50;
  --z-layer-dialog: 60;
  --z-layer-toast: 70;
  --z-layer-palette: 80;

  color-scheme: light;
}

/* The dark palette, shared by the system-preference and explicit cases. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --z-bg: #0a0b0d;
    --z-surface: #131519;
    --z-surface-raised: #1b1e23;
    --z-surface-sunken: #050607;
    --z-surface-hover: #1b1e23;
    --z-border: #262a31;
    --z-border-strong: #363b44;
    --z-text: #f4f5f7;
    --z-text-muted: var(--z-brand-cool-grey);
    --z-text-subtle: #868b94;
    --z-text-inverse: #0b0c0e;

    --z-accent: #78b4ff;
    --z-accent-hover: #9bc9ff;
    --z-accent-active: #b6d8ff;
    --z-accent-subtle: #10203a;
    --z-accent-border: #1e3a63;
    --z-accent-contrast: #08131f;

    --z-idle: #5fd68c;
    --z-idle-subtle: #111b17;
    --z-idle-border: #20402e;

    --z-busy: #3bd6e8;
    --z-busy-subtle: #0e1c1f;
    --z-busy-border: #174148;

    --z-pending: #f2b246;
    --z-pending-subtle: #1d1912;
    --z-pending-border: #3c2f19;

    --z-draining: #d0bee0;
    --z-draining-subtle: #201f25;
    --z-draining-border: #3c3842;

    --z-danger: #ff8d84;
    --z-danger-hover: #ffa9a2;
    --z-danger-subtle: #1d1516;
    --z-danger-border: #3f2727;
    --z-danger-contrast: #1a0a08;

    --z-neutral: #7f858e;
    --z-neutral-subtle: #16181a;
    --z-neutral-border: #27292d;

    --z-chart-1: #78b4ff;
    --z-chart-2: #f2b246;
    --z-chart-3: #5fd68c;
    --z-chart-4: #3bd6e8;
    --z-chart-5: #ff8d84;
    --z-chart-6: #d0bee0;

    --z-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
    --z-shadow-md: 0 4px 12px -2px rgb(0 0 0 / 0.6);
    --z-shadow-lg: 0 16px 40px -8px rgb(0 0 0 / 0.7);

    /* Zoomies Black would all but vanish into a dark row, so the coat
       lifts just far enough to read as a filled shape and still as a black
       dog -- any further and it is a grey one -- and the outline is only a
       step lighter, an edge rather than a sticker's keyline. The ear lifts
       a step above the coat so it still stands off the head. The far legs
       sit between the row and the coat, so they read as shadowed limbs; the
       blaze is a shade under white so it is not the brightest thing on the
       page; the cue moves to mid grey to stay visible on a dark row. */
    --z-standard-coat: #25282e;
    --z-standard-line: #3a3e46;
    --z-standard-ear: #3b4049;
    --z-standard-rim: #7a7f88;
    --z-standard-blaze: #eceef1;
    --z-standard-far: #1f2227;
    --z-standard-cue: var(--z-brand-mid-grey);

    --z-scrollbar-track: rgb(255 255 255 / 0.07);

    color-scheme: dark;
  }
}

:root[data-theme='dark'] {
  --z-bg: #0a0b0d;
  --z-surface: #131519;
  --z-surface-raised: #1b1e23;
  --z-surface-sunken: #050607;
  --z-surface-hover: #1b1e23;
  --z-border: #262a31;
  --z-border-strong: #363b44;
  --z-text: #f4f5f7;
  --z-text-muted: var(--z-brand-cool-grey);
  --z-text-subtle: #868b94;
  --z-text-inverse: #0b0c0e;

  --z-accent: #78b4ff;
  --z-accent-hover: #9bc9ff;
  --z-accent-active: #b6d8ff;
  --z-accent-subtle: #10203a;
  --z-accent-border: #1e3a63;
  --z-accent-contrast: #08131f;

  --z-idle: #5fd68c;
  --z-idle-subtle: #111b17;
  --z-idle-border: #20402e;

  --z-busy: #3bd6e8;
  --z-busy-subtle: #0e1c1f;
  --z-busy-border: #174148;

