/**
 * Sizes as a person writes them, and as the page writes them back.
 *
 * Pure, and imported by a unit test. A size field used to be a number box with
 * the unit in its label -- "Memory (MB)" -- so the operator who thinks in
 * gigabytes did the arithmetic, and the one who typed "4g" the way Docker
 * spells it was told nothing at all, because a number box reports anything it
 * cannot read as an empty string. Every size field now reads the spellings
 * people actually use -- 4gb, 4096mb, 4g, 4 GiB, 1.5 -- and, once the value is
 * committed, writes it back in the largest unit that says it exactly, so the
 * field shows what was understood rather than what was typed.
 *
 * A gigabyte here is 1024 megabytes. That is what the rest of the UI means by
 * GB, what Docker means by `4g`, and what a cgroup is given; offering a decimal
 * gigabyte beside it would make "4 GB" mean two different limits on one page.
 */

/**
 * A quantity a field can hold, named by the unit it is carried in: cores,
 * megabytes, gigabytes, a plain count, or a length of time in milliseconds.
 */
export type Quantity = 'cpus' | 'mb' | 'gb' | 'count' | 'ms';

/** What a parse makes of some text: a value, nothing (the field was cleared), or why not. */
export type Parsed = { ok: true; value: number | null } | { ok: false; error: string };

const MB_PER: Record<string, number> = {
  k: 1 / 1024,
  m: 1,
  g: 1024,
  t: 1024 * 1024,
  p: 1024 * 1024 * 1024,
};

/**
 * Reads a byte size into megabytes. A bare number is taken in `bare`, the unit
 * the field is labelled in, so "4096" in a megabyte field stays 4096 MB and "4"
 * in a gigabyte field stays 4 GB.
 */
function parseBytes(text: string, bare: 'mb' | 'gb'): number | undefined {
  const m = /^(\d+(?:\.\d+)?|\.\d+)\s*([kmgtp]?)(?:i?b)?$/i.exec(text);
  if (!m) return undefined;
  const n = Number(m[1]);
  const unit = (m[2] ?? '').toLowerCase();
  if (unit === '') {
    // "4b" would read as four megabytes, which nobody meant.
    if (/b$/i.test(text)) return undefined;
    return bare === 'gb' ? n * 1024 : n;
  }
  return n * (MB_PER[unit] ?? NaN);
}

/**
 * Reads a CPU figure. Cores are the unit, and fractions are allowed: "1.5",
 * "1.5 cores", "2 vCPUs". Millicores are read too, because "1500m" is how
 * anyone who has written a Kubernetes manifest spells one and a half cores.
 */
function parseCpus(text: string): number | undefined {
  const milli = /^(\d+)\s*m$/i.exec(text);
  if (milli) return Number(milli[1]) / 1000;
  const m = /^(\d+(?:\.\d+)?|\.\d+)\s*(?:v?cpus?|cores?|c)?$/i.exec(text);
  return m ? Number(m[1]) : undefined;
}

/** Milliseconds in each unit a duration can be written in, largest first. */
const MS_PER: [string, number][] = [
  ['w', 7 * 24 * 3600 * 1000],
  ['d', 24 * 3600 * 1000],
  ['h', 3600 * 1000],
  ['m', 60 * 1000],
  ['s', 1000],
  ['ms', 1],
];

/** Every spelling of a duration unit, to the short one `MS_PER` names. */
function durationUnit(word: string): string | undefined {
  const w = word.toLowerCase();
  if (w === 'ms' || /^millis(econds?)?$/.test(w)) return 'ms';
  if (/^(s|secs?|seconds?)$/.test(w)) return 's';
  if (/^(m|mins?|minutes?)$/.test(w)) return 'm';
  if (/^(h|hrs?|hours?)$/.test(w)) return 'h';
  if (/^(d|days?)$/.test(w)) return 'd';
  if (/^(w|wks?|weeks?)$/.test(w)) return 'w';
  return undefined;
}

/**
 * Reads a length of time into milliseconds: Go's own spelling ("1h30m",
 * "168h", "500ms"), the one a person says ("7 days", "2 weeks", "90 seconds"),
 * and anything between ("1d 12h", "1.5h"). A bare number is seconds, which is
 * what the one setting that ever took a bare number meant by it.
 */
function parseDuration(text: string): number | undefined {
  if (/^\d+(?:\.\d+)?$/.test(text)) return Number(text) * 1000;
  const part = /(\d+(?:\.\d+)?|\.\d+)\s*([a-z]+)\s*/giy;
  let total = 0;
  let at = 0;
  for (let m = part.exec(text); m; m = part.exec(text)) {
    const unit = durationUnit(m[2] ?? '');
    if (!unit) return undefined;
    total += Number(m[1]) * (MS_PER.find(([u]) => u === unit)?.[1] ?? NaN);
    at = part.lastIndex;
  }
  return at === text.length && at > 0 ? total : undefined;
}

const EXAMPLES: Record<Quantity, string> = {
  cpus: 'a number of cores, such as 2 or 1.5',
  mb: 'a size such as 4 GB, 4096 MB or 4g',
  gb: 'a size such as 40 GB, 1.5 TB or 500g',
  count: 'a whole number, such as 10',
  ms: 'a length of time, such as 30s, 5m, 1h30m or 7d',
};

/**
 * Reads what somebody typed into a size field, in the field's own unit.
 *
 * Megabytes and gigabytes come back whole, because that is what the API
 * carries: "1.5g" in a megabyte field is 1536, and a gigabyte field rounds to
 * the nearest gigabyte. The rounding is visible, because the field then shows
 * the value it kept. CPU keeps two decimal places, finer than any quota a
 * runtime applies.
 */
export function parseQuantity(input: string, quantity: Quantity): Parsed {
  const text = input
    .trim()
    .replace(/[\s_]+/g, ' ')
    .replace(/,/g, '');
  if (text === '') return { ok: true, value: null };
  let value: number | undefined;
  if (quantity === 'cpus') {
    const cpus = parseCpus(text);
    value = cpus === undefined ? undefined : Math.round(cpus * 100) / 100;
  } else if (quantity === 'count') {
    value = /^\d+$/.test(text) ? Number(text) : undefined;
  } else if (quantity === 'ms') {
    const ms = parseDuration(text);
    value = ms === undefined ? undefined : Math.round(ms);
  } else {
    const mb = parseBytes(text, quantity);
    if (mb !== undefined) value = quantity === 'gb' ? Math.round(mb / 1024) : Math.round(mb);
  }
  if (value === undefined || !Number.isFinite(value) || value < 0) {
    return { ok: false, error: `Write ${EXAMPLES[quantity]}.` };
  }
  return { ok: true, value };
}

const BYTE_UNITS = ['MB', 'GB', 'TB', 'PB'] as const;

/**
 * Writes a size in the largest unit that says it exactly, to two decimal
 * places: 4096 MB is "4 GB", 1536 MB is "1.5 GB", and 3000 MB stays "3000 MB",
 * because "2.93 GB" would be a different limit from the one that is set.
 */
export function formatQuantity(value: number, quantity: Quantity): string {
  if (!Number.isFinite(value)) return '';
  if (quantity === 'cpus') return `${trim(value)} ${value === 1 ? 'core' : 'cores'}`;
  if (quantity === 'count') return String(value);
  if (quantity === 'ms') return formatDuration(value);
  let at = quantity === 'gb' ? 1 : 0;
  let n = value;
  while (at < BYTE_UNITS.length - 1 && n >= 1024 && exact(n / 1024)) {
    n /= 1024;
    at++;
  }
  return `${trim(n)} ${BYTE_UNITS[at]}`;
}

/** Whether a figure survives being written to two decimal places. */
function exact(n: number): boolean {
  return Math.abs(Math.round(n * 100) - n * 100) < 1e-6;
}

function trim(n: number): string {
  return String(Math.round(n * 100) / 100);
}

/**
 * Writes a length of time in the largest units that say it exactly, largest
 * first: 3600000 is "1h", 5400000 is "1h 30m", 604800000 is "7d". Weeks are
 * read but not written, because "30d" says a retention period plainly and
 * "4w 2d" does not.
 */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms)) return '';
  if (ms === 0) return '0s';
  let left = Math.round(ms);
  const parts: string[] = [];
  for (const [unit, size] of MS_PER) {
    if (unit === 'w') continue;
    const n = Math.floor(left / size);
    if (n > 0) {
      parts.push(`${n}${unit}`);
      left -= n * size;
    }
  }
  return parts.join(' ');
}

/**
 * The same length of time in Go's spelling, which is what the controller's
 * settings API reads: days become hours, because Go has no day.
 */
export function goDuration(ms: number): string {
  let left = Math.round(ms);
  if (left === 0) return '0s';
  const out: string[] = [];
  for (const [unit, size] of [
    ['h', 3600 * 1000],
    ['m', 60 * 1000],
    ['s', 1000],
    ['ms', 1],
  ] as const) {
    const n = Math.floor(left / size);
    if (n > 0) {
      out.push(`${n}${unit}`);
      left -= n * size;
    }
  }
  return out.join('');
}

/**
 * Entry point. Mounts the shell and nothing else -- every decision about what
 * to render lives in App.svelte, so the boot sequence is readable in one file.
 */
import { mount } from 'svelte';
import './app.css';
import App from './App.svelte';

const target = document.getElementById('app');
if (!target) {
  throw new Error('The #app element is missing from index.html; the UI cannot mount.');
}

export default mount(App, { target });

/**
 * Entry point for /status, the page for readers with no account.
 *
 * Its own Vite entry rather than a route of the app, so it pulls in the
 * tokens and this one component and nothing else: no app shell, no router, no
 * event stream. vite.config.ts holds it to its own, much smaller, budget.
 */
import { mount } from 'svelte';
import '../lib/styles/tokens.css';
import StatusPage from './StatusPage.svelte';

// The operator's own theme choice, when this browser has made one; the
// system setting otherwise, which tokens.css follows with no attribute. Done
// here rather than inline in status.html because the page's CSP carries no
// hash for an inline script of its own.
try {
  const theme = localStorage.getItem('zoomies.theme');
  if (theme === 'dark' || theme === 'light') {
    document.documentElement.setAttribute('data-theme', theme);
  }
} catch {
  /* private mode: the system preference stands */
}

const target = document.getElementById('status');
if (!target) {
  throw new Error('The #status element is missing from status.html; the page cannot mount.');
}

export default mount(StatusPage, { target });

/**
 * How the status page says what GET /api/v1/status returns.
 *
 * Kept apart from the component, and free of imports, so the unit tests can
 * hold it and so the page's own entry stays a few kilobytes: it is the one
 * page in the build that people with no account load, often on a phone.
 */
import type { components } from '../lib/api/schema';

export type FleetStatus = components['schemas']['FleetStatus'];
export type FleetState = FleetStatus['state'];
export type CountBand = components['schemas']['CountBand'];

/**
 * The three states on the fixed status mapping in docs/ui-guidelines.md:
 * blocked is danger, degraded is pending, healthy is idle. They are the tones
 * an operator already reads on every other page, and each carries the shape
 * that goes with it, so colour is never the only thing saying which.
 */
export const STATE_PRESENTATION: Record<
  FleetState,
  { tone: 'danger' | 'pending' | 'idle'; shape: 'triangle' | 'dashed' | 'hollow'; headline: string }
> = {
  healthy: { tone: 'idle', shape: 'hollow', headline: 'The fleet is running normally' },
  degraded: {
    tone: 'pending',
    shape: 'dashed',
    headline: 'The fleet is running, with problems that may slow jobs down',
  },
  blocked: {
    tone: 'danger',
    shape: 'triangle',
    headline: 'Some jobs cannot run until the fleet’s operators act',
  },
};

const BAND_WORDS: Record<CountBand, string> = {
  none: 'none',
  few: 'a few',
  many: 'many',
  backed_up: 'backed up',
};

/** A band as a reader would say it. */
export function bandWords(band: CountBand): string {
  return BAND_WORDS[band] ?? band;
}

/** A wait in whole minutes, said the way a person would. */
export function waitWords(minutes: number): string {
  if (minutes <= 0) return 'under a minute';
  if (minutes === 1) return 'about a minute';
  if (minutes < 60) return `about ${minutes} minutes`;
  const hours = Math.round(minutes / 60);
  return hours === 1 ? 'about an hour' : `about ${hours} hours`;
}

/** How long ago an instant was, coarsely: the page refreshes every thirty seconds. */
export function sinceWords(iso: string | undefined, now: Date): string {
  if (!iso) return '';
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return '';
  const minutes = Math.max(0, Math.floor((now.getTime() - then) / 60_000));
  if (minutes < 1) return 'just now';
  if (minutes < 60) return minutes === 1 ? '1 minute ago' : `${minutes} minutes ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return hours === 1 ? '1 hour ago' : `${hours} hours ago`;
  return `${Math.floor(hours / 24)} days ago`;
}

/** How often the page asks again. Thirty seconds, as docs/ui.md promises. */
export const POLL_MS = 30_000;

import { vitePreprocess } from '@sveltejs/vite-plugin-svelte';

export default {
  preprocess: vitePreprocess(),
  compilerOptions: {
    // Runes mode everywhere. This is a Svelte 5 codebase; the legacy reactive
    // syntax is not used and should not compile.
    runes: true,
  },
};

/**
 * The accessibility checklist from docs/ui-guidelines.md section 6, as tests.
 *
 * These are the parts of that list a machine can check honestly: the landmark
 * structure a screen-reader user navigates by, an accessible name on every
 * control, alternative text or an explicit exemption on every image, a skip
 * link that really is the first thing in the tab order, a dialog that keeps
 * focus and gives it back, and no positive tabindex anywhere -- the one
 * mistake that quietly reorders the whole page for keyboard users.
 *
 * They run in both projects. A phone is not a different accessibility
 * standard.
 */
import { expect, test, type Page } from '@playwright/test';
import {
  browserOverride,
  FIXTURE,
  focusIsInMain,
  goto,
  isFocused,
  shiftTabTo,
} from './support/fixtures';

test.use(browserOverride);

// Every page in the navigation. It used to be four of the ten, which meant the
// audit of "every button has an accessible name" was an audit of the four
// pages least likely to be missing one.
const PAGES = [
  { path: '/', heading: 'Overview' },
  { path: '/pools', heading: 'Pools' },
  { path: '/runners', heading: 'Runners' },
  { path: '/workflows', heading: 'Workflows' },
  // Not in the navigation any more, and audited for that reason: it is the
  // page every link that names a job lands on.
  { path: '/jobs', heading: 'Jobs' },
  // The Queue puts four buttons on every row rather than a menu, which is four
  // times as many controls to get the name of right.
  { path: '/queue', heading: 'Queue' },
  { path: '/usage', heading: 'Usage' },
  { path: '/hosts', heading: 'Hosts' },
  { path: '/providers', heading: 'Providers' },
  // The three journey pages. They are not in the navigation, which is exactly
  // why they were missed: an operator setting a fleet up for the first time
  // spends more time on these than on anything in the sidebar, and every
  // control on them is one they have never seen before.
  { path: '/hosts/new', heading: 'Add a host' },
  { path: '/pools/new', heading: 'Create a pool' },
  { path: '/providers/new', heading: 'Add a provider' },
  // The two pages an operator reaches from a card rather than from the
  // navigation, and the pair a machine that is taking too long is diagnosed
  // from. Both are named after a fixture row, because a detail page with
  // nothing behind it is an error state rather than the page.
  { path: `/providers/${FIXTURE.providerId}`, heading: FIXTURE.provider },
  { path: `/machines/${FIXTURE.readyMachineId}`, heading: FIXTURE.readyMachine },
  { path: '/installations', heading: 'Installations' },
  { path: '/migrate', heading: 'Migrate repositories' },
  { path: '/audit', heading: 'Audit' },
  // Three of the settings pages: the one with a table and a row menu, the one
  // with the most controls on it, and the one that is nothing but switches --
  // each of which has to name itself without the label beside it.
  { path: '/settings/users', heading: 'Users' },
  { path: '/settings/configuration', heading: 'Configuration' },
  { path: '/settings/events', heading: 'Events' },
] as const;

/** The pages whose main content is a grid of rows to wait for. */
const GRID_PAGES = new Set(['/pools', '/runners', '/workflows', '/jobs', '/queue', '/audit']);

/**
 * Let the page finish rendering before auditing it.
 *
 * A grid page paints a skeleton first, so counting controls too early counts
 * the wrong page. Waiting for a real row is the honest signal.
 */
async function settle(page: Page, path: string): Promise<void> {
  await expect(page.getByRole('main')).toBeVisible();
  if (path === '/') {
    await expect(page.getByRole('region', { name: 'Recent events' })).toBeVisible();
    return;
  }
  if (GRID_PAGES.has(path)) {
    await expect(page.locator('tbody tr[data-row]').first()).toBeVisible();
    return;
  }
  // The rest settle on their own heading: a page with nothing seeded behind it
  // shows an empty state, which is a finished page and worth auditing too.
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
}

for (const { path, heading } of PAGES) {
  test(`${heading} has one h1 and the landmarks to navigate by`, async ({ page }) => {
    await goto(page, path, heading);
    await settle(page, path);

    await expect(page.getByRole('heading', { level: 1 })).toHaveCount(1);
    await expect(page.getByRole('main')).toHaveCount(1);
    // At least one navigation landmark, and the sections one is named so it
    // can be told apart from the grid's pagination.
    expect(await page.getByRole('navigation').count()).toBeGreaterThanOrEqual(1);
    await expect(page.getByRole('navigation', { name: 'Sections' })).toHaveCount(1);
  });
}

test('every button and link has an accessible name', async ({ page }) => {
  // This audit deliberately visits every route. On a loaded CI runner that is
  // valid work for more than the ordinary single-page 30 second budget.
  test.slow();

  // This one caught a real bug on the phone: the bottom bar hid each entry's
  // label with `display: none`, which took its accessible name with it, and a
  // screen reader announced eight links called "link". The bar shows its four
  // labels outright now, and the collapsed desktop sidebar hides its own off
  // screen rather than removing them -- so both projects assert the same
  // thing.

  // `getByRole` uses the browser's own name computation and skips anything
  // hidden from the accessibility tree, so this is the real question rather
  // than a guess at aria-label attributes.
  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    // An element with no accessible name has the empty one, so this asks for
    // exactly the offenders rather than comparing two counts taken at two
    // different moments.
    await expect(
      page.getByRole('button', { name: /^$/ }),
      `${path}: every button has an accessible name`,
    ).toHaveCount(0);
    await expect(
      page.getByRole('link', { name: /^$/ }),
      `${path}: every link has an accessible name`,
    ).toHaveCount(0);
  }
});

/*
 * A segmented option is named for the label it shows, and described after it.
 * Both halves have been got wrong in turn: a name that was the description
 * alone left the button reading "1m" with nothing by that name to ask for, and
 * a description that opened with the label again had a screen reader saying
 * "Rows -- Rows: the table". Voice control asks for what it can see, so the
 * label leads and is said once.
 */
test('a segmented option is asked for by the label it shows', async ({ page }) => {
  test.slow();

  let audited = 0;
  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    // Nothing in the accessibility tree marks a choice as segmented, so the
    // group is reached structurally; the names it is judged on are the
    // rendered ones.
    const seen = await page.locator('.segmented button').evaluateAll((buttons) =>
      buttons.map((button) => ({
        label: (button.textContent ?? '').trim(),
        name: (button.getAttribute('aria-label') ?? button.textContent ?? '').trim(),
      })),
    );
    audited += seen.length;

    const offenders = seen.filter(({ label, name }) => {
      if (label === '') return false;
      if (!name.startsWith(label)) return true;
      // What follows the label is the description, and it is a description of
      // the option rather than the option's name a second time. The separator
      // between the two is the component's to choose, so it is stepped over
      // rather than spelled out here.
      return name
        .slice(label.length)
        .replace(/^[\s\p{Pd}:,.-]+/u, '')
        .startsWith(label);
    });

    expect(
      offenders,
      `${path}: a segmented option's accessible name says its label once, first`,
    ).toEqual([]);
  }

  // An audit that found no buttons to audit passes for the wrong reason.
  expect(audited, 'no segmented choice was found on any page').toBeGreaterThan(0);
});

/*
 * A definition list may hold terms and descriptions, and groups of them, and
 * nothing else. Seven pages' summary tiles and a pool's configuration list each
 * put a paragraph or a bar directly inside one, which is invalid and which a
 * screen reader answers by losing the pairing of term and value altogether.
 */
test('a definition list holds only terms and their descriptions', async ({ page }) => {
  test.slow();

  const pools = (await page.request.get('/api/v1/pools').then((r) => r.json())) as {
    items: { id: string; name: string }[];
  };
  const pool = pools.items.find((p) => p.name === FIXTURE.linuxPool)!;
  const pages = [...PAGES, { path: `/pools/${pool.id}`, heading: FIXTURE.linuxPool }];

  let audited = 0;
  for (const { path, heading } of pages) {
    await goto(page, path, heading);
    await settle(page, path);

    const result = await page.evaluate(() => {
      const allowed = new Set(['DT', 'DD', 'SCRIPT', 'TEMPLATE']);
      const lists = Array.from(document.querySelectorAll('dl'));
      const offenders = lists.flatMap((list) =>
        Array.from(list.children)
          .filter((child) => {
            if (allowed.has(child.tagName)) return false;
            // A wrapper is allowed, but only around terms and descriptions.
            if (child.tagName === 'DIV') {
              return Array.from(child.children).some(
                (inner) => !['DT', 'DD'].includes(inner.tagName),
              );
            }
            return true;
          })
          .map((child) => `<${child.tagName.toLowerCase()} class="${child.className}">`),
      );
      return { lists: lists.length, offenders };
    });
    audited += result.lists;
    expect(result.offenders, `${path}: a definition list holds only dt and dd`).toEqual([]);
  }

  // An audit that found no list to audit passes for the wrong reason.
  expect(audited, 'no definition list was found on any page').toBeGreaterThan(0);
});

test('every image has alternative text or is hidden from assistive technology', async ({
  page,
}) => {
  test.slow();

  for (const { path, heading } of PAGES) {
    await goto(page, path, heading);
    await settle(page, path);

    const offenders = await page.evaluate(() =>
      Array.from(document.querySelectorAll('img'))
        .filter(
          (image) =>
            image.getAttribute('alt') === null &&
            image.getAttribute('aria-hidden') !== 'true' &&
            image.closest('[aria-hidden="true"]') === null,
        )
        .map((image) => image.outerHTML.slice(0, 120)),
    );
    expect(offenders, `${path}: images carry alt text or are marked decorative`).toEqual([]);

    // An <svg role="img"> is an image too, and every one that is exposed must
    // say what it shows. A status shape beside its own printed label is
    // deliberately hidden instead, so it is not read out twice.
    const unlabelled = await page.evaluate(() =>
      Array.from(document.querySelectorAll('svg[role="img"]'))
        .filter(
          (svg) =>
            (svg.getAttribute('aria-label') ?? '').trim() === '' &&
            svg.getAttribute('aria-hidden') !== 'true' &&
            svg.closest('[aria-hidden="true"]') === null,
        )
        .map((svg) => svg.outerHTML.slice(0, 120)),
    );
    expect(unlabelled, `${path}: every svg image is described`).toEqual([]);
  }
});

