/**
 * A column's width and its position, set by whatever the operator is pointing
 * with.
 *
 * Both were once the HTML5 drag-and-drop protocol and a pointer listener on the
 * document, which between them worked for a mouse and for nothing else: a
 * browser raises `dragstart` from a finger only after a long press on Android
 * and never on iOS, so the column order was a stored preference a phone could
 * read and not write -- on the Rows layout, which exists precisely so that a
 * phone has columns to arrange. This file holds both gestures to working under
 * a finger as well as a cursor, which is why it runs in both projects: the
 * desktop one drives a real mouse, and the mobile one a real touchscreen's
 * events at the width where the Rows layout lives.
 *
 * The gesture is driven by dispatched pointer events rather than by
 * `page.mouse`, because a mouse is the one input this was never broken for.
 * What the browser is left to decide is everything around them -- capture,
 * hit-testing, the styles that say a column is in the air.
 */
import { expect, test, type Locator, type Page } from '@playwright/test';
import { browserOverride, goto, grid, waitForRows } from './support/fixtures';

test.use(browserOverride);

/** The grid every test here uses: enough columns to have a middle. */
const GRID = { path: '/runners', heading: 'Runners', label: 'Runners' } as const;

/**
 * Open the grid in the layout that has columns.
 *
 * A phone starts every grid as cards, where there is nothing to resize and
 * nothing to reorder; Rows is the layout that keeps the table, and the one the
 * gesture is for. Pressed rather than written into storage, because a
 * preference set behind the UI's back is one this file would keep passing on
 * after the control that sets it broke.
 */
async function openGrid(page: Page, isMobile: boolean): Promise<Locator> {
  await goto(page, GRID.path, GRID.heading);
  if (isMobile) {
    const rows = page.getByRole('button', { name: /^Rows\b/ });
    await rows.click();
    await expect(rows).toHaveAttribute('aria-pressed', 'true');
  }
  const table = grid(page, GRID.label);
  await waitForRows(table);
  return table;
}

/** The column headings, in the order they are drawn. */
function order(table: Locator): Promise<string[]> {
  return table.evaluate((node) =>
    [...node.querySelectorAll<HTMLElement>('thead th[data-table-column]')].map(
      (th) => th.dataset.tableColumn ?? '',
    ),
  );
}

/** A heading's width as drawn, which is what a resize has to change. */
async function width(table: Locator, column: string): Promise<number> {
  return (await table.locator(`thead th[data-table-column="${column}"]`).boundingBox())!.width;
}

/**
 * One touch, start to finish, over the path given.
 *
 * Every event goes to the control the gesture started on, which is where the
 * browser sends them once the pointer is captured, and carries a point in the
 * window because the drop target is worked out by asking the document what is
 * under the finger.
 */
async function touchDrag(
  control: Locator,
  path: readonly { x: number; y: number }[],
  end: 'up' | 'cancel' = 'up',
): Promise<void> {
  const touch = { pointerId: 1, pointerType: 'touch', isPrimary: true, button: 0 };
  // `clientX` and `clientY` by name: a PointerEvent's `x` and `y` are read-only
  // aliases of them, so an init that carries only those leaves the event at the
  // top-left corner and every gesture in this file a no-op that still passes.
  const at = (point: { x: number; y: number }) => ({ clientX: point.x, clientY: point.y });
  const [first, ...rest] = path;
  await control.dispatchEvent('pointerdown', { ...touch, buttons: 1, ...at(first!) });
  for (const point of rest) {
    await control.dispatchEvent('pointermove', { ...touch, buttons: 1, ...at(point) });
  }
  await control.dispatchEvent(end === 'up' ? 'pointerup' : 'pointercancel', {
    ...touch,
    buttons: 0,
    ...at(rest.at(-1) ?? first!),
  });
}

/**
 * The middle of a control, where a finger lands on it.
 *
 * Scrolled to first: these are window coordinates, and the drop target is
 * found by asking the document what is at one of them. A heading below the
 * fold is at a point that is over nothing at all.
 */
async function centre(control: Locator): Promise<{ x: number; y: number }> {
  await control.scrollIntoViewIfNeeded();
  const box = (await control.boundingBox())!;
  return { x: box.x + box.width / 2, y: box.y + box.height / 2 };
}

test('a finger can pull a column wider, and the width outlives the visit', async ({
  page,
  isMobile,
}) => {
  const table = await openGrid(page, isMobile);
  const heading = table.locator('thead th[data-table-column="name"]');
  const before = await width(table, 'name');

  const from = await centre(heading.locator('.resizer'));
  await touchDrag(heading.locator('.resizer'), [
    from,
    { x: from.x + 20, y: from.y },
    { x: from.x + 70, y: from.y },
  ]);

  // The drag asked for 70 more pixels. Held loosely: the column has a ceiling,
  // and what matters is that the finger moved it at all.
  await expect
    .poll(() => width(table, 'name'), { message: 'the finger did not widen the column' })
    .toBeGreaterThan(before + 40);

  // Written through to the preference, not merely to the DOM: the reason to
  // resize a column is that it stays resized.
  const set = await width(table, 'name');
  await openGrid(page, isMobile);
  await expect.poll(() => width(table, 'name')).toBeCloseTo(set, 0);
});

test('a finger can drag a column past its neighbour, and it stays there', async ({
  page,
  isMobile,
}) => {
  const table = await openGrid(page, isMobile);
  const started = await order(table);
  const [first, second] = started;
  expect(second, 'the grid needs two columns to swap').toBeTruthy();

  const grip = table.locator(`thead th[data-table-column="${first}"] .move`);
  const from = await centre(grip);
  const onto = await centre(table.locator(`thead th[data-table-column="${second}"]`));
  await touchDrag(grip, [from, { x: from.x + 10, y: from.y }, onto]);

  await expect
    .poll(() => order(table), { message: 'the column did not move' })
    .toEqual([second, first, ...started.slice(2)]);

  await openGrid(page, isMobile);
  await expect.poll(() => order(table)).toEqual([second, first, ...started.slice(2)]);
});

test('a tap on the grip rearranges nothing', async ({ page, isMobile }) => {
  // A finger never presses a target without moving a pixel or two, so a press
  // that goes nowhere has to stay a press -- otherwise reaching for the grip
  // to read its tooltip, or to give it focus for the arrow keys, shuffles the
  // table.
  const table = await openGrid(page, isMobile);
  const started = await order(table);
  const grip = table.locator(`thead th[data-table-column="${started[0]}"] .move`);
  const from = await centre(grip);

  await touchDrag(grip, [from, { x: from.x + 2, y: from.y + 1 }]);

  await expect.poll(() => order(table)).toEqual(started);
});

test('a drag the browser takes back leaves the order alone', async ({ page, isMobile }) => {
  // `pointercancel` and no `pointerup` is what a gesture the system claims --
  // a back-swipe, a second finger, a notification -- looks like from here. The
  // column has to go back where it was rather than land wherever the finger
  // was when it was taken away.
  const table = await openGrid(page, isMobile);
  const started = await order(table);
  const [first, second] = started;

  const grip = table.locator(`thead th[data-table-column="${first}"] .move`);
  const from = await centre(grip);
  const onto = await centre(table.locator(`thead th[data-table-column="${second}"]`));
  await touchDrag(grip, [from, { x: from.x + 10, y: from.y }, onto], 'cancel');

  await expect.poll(() => order(table)).toEqual(started);
  // And nothing is left looking picked up.
  await expect(table.locator('thead th.dragging, thead th.drop-target')).toHaveCount(0);
});

test('a mouse still reorders columns, now that the drag protocol is gone', async ({
  page,
  isMobile,
}) => {
  // The gesture replaced `draggable` and `dragstart` outright rather than
  // sitting beside them, so the input it already worked for is the one at risk.
  // Driven by a real cursor, which is the desktop project's: a phone's Rows
  // layout scrolls sideways inside the frame, so a cursor dragged across it is
  // measuring that scroll as much as the gesture.
  test.skip(!!isMobile, 'a real cursor, in the desktop project');
  const table = await openGrid(page, isMobile);
  const started = await order(table);
  const [first, second] = started;

  const grip = table.locator(`thead th[data-table-column="${first}"] .move`);
  const from = await centre(grip);
  const onto = await centre(table.locator(`thead th[data-table-column="${second}"]`));
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  await page.mouse.move(from.x + 10, from.y);
  await page.mouse.move(onto.x, onto.y, { steps: 4 });
  await page.mouse.up();

  await expect
    .poll(() => order(table), { message: 'the mouse drag did not move the column' })
    .toEqual([second, first, ...started.slice(2)]);
});

test('the controls are big enough to hit with a finger', async ({ page, isMobile }) => {
  // docs/ui-guidelines.md puts a control read by a finger at
  // `--z-control-touch`, and these two were laid out for a cursor: a 12px edge
  // and a 20px grip. The measurement is the mobile project's, because the
  // desktop one is deliberately denser.
  test.skip(!isMobile, 'the touch sizes, in the Pixel 7 project');
  const table = await openGrid(page, isMobile);
  const heading = table.locator('thead th[data-table-column]').first();

  const grip = (await heading.locator('.move').boundingBox())!;
  const resizer = (await heading.locator('.resizer').boundingBox())!;
  expect(grip.height, 'the reposition grip is shorter than a fingertip').toBeGreaterThanOrEqual(44);
  expect(resizer.height, 'the resize handle is shorter than a fingertip').toBeGreaterThanOrEqual(
    44,
  );
  expect(resizer.width, 'the resize handle is narrower than a fingertip can aim').toBeGreaterThan(
    12,
  );

  // Neither gesture survives the browser deciding the drag was a scroll.
  for (const control of ['.move', '.resizer']) {
    const action = await heading
      .locator(control)
      .evaluate((node) => getComputedStyle(node).touchAction);
    expect(action, `${control} lets the browser scroll instead of dragging`).toBe('none');
  }

  // A handle that only appears on hover is a handle a touchscreen never sees.
  const line = await heading
    .locator('.resizer')
    .evaluate((node) => getComputedStyle(node, '::after').opacity);
  expect(Number(line), 'the resize handle is invisible until hovered').toBeGreaterThan(0);
});

/**
 * The command palette.
 *
 * It is the fastest path to everything, and the one an operator reaches for
 * when something is on fire: Ctrl+K, type the name of the runner in the
 * alert, land on its page. This protects that it opens and closes without
 * losing the keyboard, that it searches pages and the live fleet rather than a
 * hard-coded list, and that the highlighted option is exposed to assistive
 * technology rather than being a colour.
 */
import { expect, test } from '@playwright/test';
import {
  browserOverride,
  FIXTURE,
  goto,
  isFocused,
  pageHeading,
  paletteOpener,
} from './support/fixtures';

test.use(browserOverride);

const palette = (page: import('@playwright/test').Page) =>
  page.getByRole('dialog', { name: 'Command palette' });
const search = (page: import('@playwright/test').Page) =>
  palette(page).getByRole('combobox', { name: /Search pages, pools, runners and hosts/ });

test.beforeEach(async ({ page }) => {
  await goto(page, '/', 'Overview');
});

test('Ctrl+K opens it, Escape closes it and gives focus back', async ({ page }) => {
  // Start from a known place so "focus went back where it was" means something.
  const opener = paletteOpener(page);
  await opener.focus();
  expect(await isFocused(opener)).toBe(true);

  await page.keyboard.press('Control+k');
  await expect(palette(page)).toBeVisible();
  await expect(search(page)).toBeFocused();

  await page.keyboard.press('Escape');
  await expect(palette(page)).toBeHidden();
  // The trap hands focus back a frame after the palette has gone, so this waits
  // for it rather than sampling once: a single look on a slow runner can land
  // between the two.
  await expect(opener, 'focus returns to whatever opened the palette').toBeFocused();
});

test('typing a page name and pressing Enter goes there', async ({ page }) => {
  await page.keyboard.press('Control+k');
  await search(page).fill('jobs');

  const options = palette(page).getByRole('option');
  await expect(options.first()).toContainText('Jobs');

  await page.keyboard.press('Enter');
  await expect(palette(page)).toBeHidden();
  await expect(pageHeading(page, 'Jobs')).toBeVisible();
  await expect(page).toHaveURL(/\/jobs$/);
});

test('typing a runner name finds that runner and opens it', async ({ page }) => {
  await page.keyboard.press('Control+k');
  // The palette searches the live fleet cache, so this only passes because the
  // seeded runner is really there.
  await search(page).fill(FIXTURE.busyRunner);

  const first = palette(page).getByRole('option').first();
  await expect(first).toContainText(FIXTURE.busyRunner);
  await expect(first).toContainText('Runner');

  await page.keyboard.press('Enter');
  await expect(palette(page)).toBeHidden();
  await expect(pageHeading(page, FIXTURE.busyRunner)).toBeVisible();
  await expect(page).toHaveURL(/\/runners\/run_demo\d+$/);
});

test('the arrow keys move the selection and say so in the accessibility tree', async ({ page }) => {
  await page.keyboard.press('Control+k');
  await search(page).fill('demo');

  const options = palette(page).getByRole('option');
  await expect(options.first()).toBeVisible();
  const total = await options.count();
  expect(total, 'the fixture gives the palette something to move through').toBeGreaterThan(2);

  await expect(options.nth(0)).toHaveAttribute('aria-selected', 'true');
  await expect(search(page)).toHaveAttribute('aria-activedescendant', 'palette-option-0');

  await page.keyboard.press('ArrowDown');
  await expect(options.nth(0)).toHaveAttribute('aria-selected', 'false');
  await expect(options.nth(1)).toHaveAttribute('aria-selected', 'true');
  await expect(search(page)).toHaveAttribute('aria-activedescendant', 'palette-option-1');

  await page.keyboard.press('ArrowUp');
  await expect(options.nth(0)).toHaveAttribute('aria-selected', 'true');

  // Exactly one option is ever selected, whatever the arrows have been doing.
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('ArrowDown');
  await expect(palette(page).locator('[aria-selected="true"]')).toHaveCount(1);
});

/**
 * Settings: the configuration.
 *
 * This is the page that can change what the controller is, so the things worth
 * testing are the ones that stop it doing that by accident: that a change is
 * kept rather than lost at the next restart, that a value nothing can apply
 * says so instead of pretending, that a setting an environment variable is
 * holding is out of the way and explained rather than editable and futile, and
 * that a bad value is refused with a sentence somebody can act on.
 *
 * Every test puts back what it changed. The fixture's controller is shared with
 * the rest of the suite, and a retention window or a scheduler interval left
 * altered is a change every later spec runs against.
 */
import { expect, test, type Page } from '@playwright/test';
import { browserOverride, goto, openSection, reload } from './support/fixtures';

test.use(browserOverride);

/** One setting's row, found by the name a person reads rather than its key. */
const row = (page: Page, label: string) =>
  page.locator('.row').filter({ has: page.getByText(label, { exact: true }) });

async function openConfiguration(page: Page): Promise<void> {
  await goto(page, '/settings/configuration', 'Configuration');
}

test('a controller with no agent lists only the switch that would bring one back', async ({
  page,
}) => {
  // The fixture's controller runs no embedded agent, which is what a
  // controller-only instance is. Its agent settings describe nothing on this
  // process -- the joined hosts set their own -- so they are not offered; the
  // switch that would start one is. The fixture sets it from the environment,
  // so it is listed among the settings the environment holds.
  await openConfiguration(page);
  const held = page.getByRole('group', { name: /Held by the environment/i });
  await expect(held).toContainText('ZOOMIES_AGENT_EMBEDDED');
  await expect(row(page, 'Runner backend')).toHaveCount(0);
  await expect(row(page, 'Runners per host')).toHaveCount(0);
});

/** Change one setting through its own row, and wait for the row to settle. */
async function change(page: Page, label: string, value: string): Promise<void> {
  const target = row(page, label);
  await target.getByRole('button', { name: 'Change' }).click();
  const field = target.getByRole('textbox');
  await field.fill(value);
  await target.getByRole('button', { name: /^Save / }).click();
  await expect(target.getByRole('button', { name: 'Change' })).toBeVisible();
}

test('a change to a live setting is applied and kept', async ({ page }) => {
  await openConfiguration(page);

  // A retention window is safe to move: nothing else in the suite asserts it,
  // and the pruning it drives is not on any spec's path.
  await change(page, 'Keep webhook deliveries for', '96h');
  const target = row(page, 'Keep webhook deliveries for');
  // Shown in the largest whole unit, the way a person would say it.
  await expect(target).toContainText('4d');

  // Kept, not merely applied: the value is in the database, so the row now
  // says where it came from.
  await expect(target.getByText('Saved here')).toBeVisible();

  // A reload reads it back from the server rather than from anything the page
  // is still holding.
  await page.reload();
  await expect(row(page, 'Keep webhook deliveries for')).toContainText('4d');

  // Put it back, so the next spec sees the fixture it expects.
  await row(page, 'Keep webhook deliveries for').getByRole('button', { name: 'Reset' }).click();
  await expect(row(page, 'Keep webhook deliveries for').getByText('Saved here')).toBeHidden();
});

test('a setting the controller cannot apply to itself is stored and says it is waiting', async ({
  page,
}) => {
  await openConfiguration(page);

  // Rebinding a listener under live connections is not something a process can
  // do to itself. Refusing the edit, which is what this page used to do, never
  // stopped anybody wanting the change -- it only moved the work to a text
  // editor and left no record that anyone had asked.
  await change(page, 'Session lifetime', '48h');

  const target = row(page, 'Session lifetime');
  await expect(target.getByText('Waiting for a restart')).toBeVisible();
  await expect(page.getByRole('heading', { name: /waiting for a restart/i })).toBeVisible();

  await target.getByRole('button', { name: 'Reset' }).click();
  await expect(target.getByText('Waiting for a restart')).toBeHidden();
});

test('a value that will not parse is refused under the field that was typed in', async ({
  page,
}) => {
  await openConfiguration(page);

  const target = row(page, 'Scheduler interval');
  await target.getByRole('button', { name: 'Change' }).click();
  await target.getByRole('textbox').fill('soon');
  await target.getByRole('button', { name: /^Save / }).click();

  // Under the field, not in a toast that floats away while somebody is still
  // reading it -- and saying what shape was wanted, not only that this one was
  // wrong.
  const failure = target.getByRole('alert');
  await expect(failure).toContainText('Write a length of time');
  await expect(failure).toContainText('30s, 5m, 1h30m or 7d');

  await target.getByRole('button', { name: /^Cancel editing / }).click();
});

test('settings held by the environment are gathered at the end and name their variable', async ({
  page,
}) => {
  await openConfiguration(page);

  // The fixture's controller runs with ZOOMIES_DISABLE_AUTH set, which is
  // exactly the state this group exists for: the page shows one value, the
  // file may say another, and nothing an administrator does here changes it.
  const held = page.getByRole('group', { name: /Held by the environment/i });
  await expect(held).toBeVisible();
  await expect(held).toContainText('ZOOMIES_DISABLE_AUTH');
  await expect(held).toContainText('amend the environment file');

  // And it is not among the settings somebody can change, because it cannot be.
  await expect(row(page, 'Disable authentication')).toHaveCount(0);
});

test('the page can be searched and filtered down to what has been changed', async ({ page }) => {
  await openConfiguration(page);

  // Eighty-eight settings is too many to scroll, so the search matches the key,
  // the summary and the environment variable alike.
  await page.getByRole('textbox', { name: 'Search settings' }).fill('ZOOMIES_PROVISION_TIMEOUT');
  await expect(row(page, 'Provision timeout')).toBeVisible();
  await expect(row(page, 'Log level')).toHaveCount(0);

  await page.getByRole('textbox', { name: 'Search settings' }).fill('');
  await page.getByText(/^Changed/).click();
  await expect(page.getByRole('heading', { name: 'Configuration', exact: true })).toBeVisible();

  // Whatever the fixture has changed, nothing still at its default is listed.
  await expect(row(page, 'Provision timeout')).toHaveCount(0);
});

test('a link to one setting lands on it, whatever the page was filtered to', async ({ page }) => {
  // A problem that names a key used to land somebody on a list of eighty-eight
  // and leave them to find it. The filters are stood down for the link, because
  // one arriving while "Changed" is selected would otherwise open a page the
  // setting is not on.
  await openConfiguration(page);
  await page.getByText(/^Changed/).click();
  await expect(row(page, 'Provision timeout')).toHaveCount(0);

  await page.goto('/settings/configuration?setting=scheduler.provision_timeout');
  const sought = row(page, 'Provision timeout');
  await expect(sought).toBeVisible();
  // Marked, not merely scrolled to: a page that jumps and then looks exactly as
  // it did leaves somebody hunting for what moved.
  await expect(sought).toHaveClass(/sought/);
});

test('saving a setting after arriving from a link leaves the search and the scroll alone', async ({
  page,
}) => {
  // The link's effect used to read the settings it had just been handed, so
  // every save, refresh or import re-armed it: the search box emptied and the
  // page jumped back to the linked row, away from the one being edited.
  await goto(page, '/settings/configuration?setting=scheduler.provision_timeout', 'Configuration');
  await expect(row(page, 'Provision timeout')).toHaveClass(/sought/);

  const search = page.getByRole('textbox', { name: 'Search settings' });
  await search.fill('retention.webhooks');
  await change(page, 'Keep webhook deliveries for', '96h');
  await expect(search).toHaveValue('retention.webhooks');
  await expect(row(page, 'Provision timeout')).toHaveCount(0);

  // Put it back, so the next spec sees the fixture it expects.
  await row(page, 'Keep webhook deliveries for').getByRole('button', { name: 'Reset' }).click();
  await expect(row(page, 'Keep webhook deliveries for').getByText('Saved here')).toBeHidden();
  await expect(search).toHaveValue('retention.webhooks');
});

test('the search box takes the slash key, the way a list an operator reads does', async ({
  page,
}) => {
  await openConfiguration(page);
  const search = page.getByRole('textbox', { name: 'Search settings' });
  await expect(search).not.toBeFocused();
  await page.keyboard.press('/');
  await expect(search).toBeFocused();

  // And it is not swallowed while somebody is typing a value into a field,
  // which would put a stray slash in the middle of what they were editing.
  await search.fill('provision');
  await page.keyboard.press('/');
  await expect(search).toHaveValue('provision/');
});

/*
 * Which layout the host capacity map opens in is a fleet setting, and one
 * per page: the Overview is glanced at and the Hosts page is looked into, so
 * a fleet may want every host on one chart on the first and a chart per
 * host on the second. The setting is live -- the page an operator moves to
 * next opens the new way without a reload -- and it is a default rather than
 * a rule: an operator who picks the other layout keeps their pick in that
 * browser, for that page only.
 */
test('the capacity map opens in the layout the fleet chose for each page, until an operator picks', async ({
  page,
}) => {
