test('pausing a multi-page scan finishes the current batch and keeps unchecked repositories explicit', async ({
  page,
}) => {
  let releaseBatch!: () => void;
  const gate = new Promise<void>((resolve) => (releaseBatch = resolve));
  const cursors: string[] = [];
  await page.route('**/api/v1/migrations/plan', async (route) => {
    const request = route.request().postDataJSON();
    const cursor = request.cursor ?? '';
    cursors.push(cursor);
    const response = await route.fetch({ postData: { installation_id: request.installation_id } });
    const plan = await response.json();
    const example = plan.repositories.find((r: { repo: string }) => r.repo === FIXTURE.repos[0]);
    if (cursor === 'second') await gate;
    await route.fulfill({
      json: {
        ...plan,
        repositories: [{ ...example, repo: `acme/batch-${cursor || 'first'}` }],
        total_repos: 3,
        next_cursor: cursor === '' ? 'second' : cursor === 'second' ? 'third' : '',
      },
    });
  });
  await walkTo(page, 1);
  await page.getByRole('button', { name: 'Pause scan' }).click();
  releaseBatch();
  await expect(page.getByText('Repository scan paused')).toBeVisible();
  await expect(page.getByText(/Unchecked repositories will not be included/)).toBeVisible();
  expect(cursors).toEqual(['', 'second']);
  await expect(page.getByRole('button', { name: 'Continue with 2 selected' })).toBeEnabled();
  await page.getByRole('button', { name: 'Scan remaining repositories' }).click();
  await expect(page.getByText('Repository scan complete')).toBeVisible();
  await expect(
    page.getByRole('checkbox', { name: 'acme/batch-third', exact: false }),
  ).toBeChecked();
});

test('the review step offers the badge, ticked, and shows the line it would add', async ({
  page,
}) => {
  await walkTo(page, 4);

  // On by default: the badge is how the people who read a README find out
  // what runs its CI. It is a checkbox because the README is somebody else's.
  const box = page.getByRole('checkbox', { name: 'Add the badge to each README' });
  await expect(box).toBeChecked();

  // The exact line, not a description of one, beside the badge it renders.
  const preview = page.getByRole('img', { name: 'CI has the Zoomies' });
  await expect(preview).toBeVisible();
  // Visible is not loaded: an <img> with width and height attributes takes up
  // the same box whether its source resolved or a broken-image icon sits in
  // it, so the preview of a badge that 404s would pass the assertion above.
  // This one is about the asset actually being served with the UI.
  await expect
    .poll(() => preview.evaluate((el: HTMLImageElement) => el.naturalWidth))
    .toBeGreaterThan(0);
  await expect(
    page.getByText('[![CI has the Zoomies](https://zoomies.sh/badge.svg)'),
  ).toBeVisible();

  // Declining is one click, and the preview stays so it can be reconsidered.
  await box.uncheck();
  await expect(box).not.toBeChecked();
  await expect(preview).toBeVisible();
});

/**
 * Zoomies on a phone.
 *
 * docs/ui-guidelines.md makes read-only monitoring on a phone a requirement,
 * and the phone breakpoint has one rule that matters above the rest: nothing
 * scrolls sideways. An operator woken at 3am reading a dashboard one-handed
 * cannot chase a column that is off the right edge of the screen.
 *
 * These run only in the Pixel 7 project; the desktop project skips them.
 */
import { expect, test, type Locator, type Page } from '@playwright/test';
import {
  browserOverride,
  dataRows,
  documentWidth,
  FIXTURE,
  goto,
  grid,
  nav,
  menuEntry,
  navEntry,
  navMenu,
  openNavMenu,
  pageHeading,
  PRIMARY_SECTIONS,
  SECTIONS,
  sectionHeading,
} from './support/fixtures';

test.use(browserOverride);

test.skip(({ isMobile }) => !isMobile, 'the phone layout, in the Pixel 7 project');

/** How far the page can be scrolled sideways, which must be nowhere. */
async function expectNoSidewaysScroll(page: Page, where: string): Promise<void> {
  const { scrollWidth, clientWidth } = await documentWidth(page);
  expect(
    scrollWidth,
    `${where} is ${scrollWidth}px wide in a ${clientWidth}px window, so the page scrolls sideways`,
  ).toBeLessThanOrEqual(clientWidth);
}

test('the Overview is readable without scrolling sideways', async ({ page }) => {
  // This caught two real bugs: `.app` kept `align-items: flex-start` where the
  // row becomes a column, so the content column was sized to its content
  // rather than to the window, and the top bar's account trigger
  // ("Authentication disabled" on this instance) was long enough to push the
  // document past the edge on its own.

  await goto(page, '/', 'Overview');
  await expect(page.getByRole('region', { name: 'Recent events' })).toBeVisible();

  // The tiles stack rather than shrinking into unreadable columns.
  const tiles = page.getByRole('link', { name: /^(Queued jobs|Running jobs|Live runners)/ });
  await expect(tiles).toHaveCount(3);
  for (let i = 0; i < 3; i++) {
    await expect(tiles.nth(i)).toBeVisible();
  }
  // The problems summary is a line, not a panel, and the count that opens the
  // full list is in the top bar where it is on every other page too.
  await expect(page.getByText(/needs? your attention\.$/).first()).toBeVisible();
  await expect(page.getByRole('button', { name: /^Problems\./ })).toBeVisible();

  await expectNoSidewaysScroll(page, 'the Overview');
});

