  page,
}) => {
  const response = await page.request.get('/api/v1/provisioning?limit=1&sort=queued_at&order=asc');
  const { items } = await response.json();
  const job = items[0];
  const subject = `${job.repo} / ${job.job_name}`;

  await goto(page, '/queue', 'Queue');
  const runNow = page.getByRole('button', { name: `Run now: ${subject}`, exact: true }).first();
  await expect(runNow).toBeVisible();

  // Reached the way the keyboard reaches it, rather than by being clicked: a
  // click would say nothing about the tab order.
  await runNow.focus();
  await expect(runNow).toBeFocused();

  await page.keyboard.press('ArrowRight');
  await expect(
    page.getByRole('button', { name: `Pause: ${subject}`, exact: true }).first(),
  ).toBeFocused();

  /*
   * Resume is already in force on a ready item, and the arrow lands on it all
   * the same. An action that cannot be taken is refused, not removed: it stays
   * focusable so that the reason it gives is reachable without a pointer, and
   * so that confirming an action which makes its own button unavailable does
   * not drop focus to the top of the document.
   */
  await page.keyboard.press('ArrowRight');
  const resume = page
    .getByRole('button', { name: new RegExp(`^Resume: ${escapeRegExp(subject)}\\.`) })
    .first();
  await expect(resume).toBeFocused();
  await expect(resume).toHaveAttribute('aria-disabled', 'true');
  // The reason is part of what the control is called, so it is announced with it.
  await expect(resume).toHaveAccessibleName(/Already provisioning normally/);

  // Pressing it does nothing rather than opening a confirmation for a no-op.
  await resume.press('Enter');
  await expect(page.getByRole('dialog')).toHaveCount(0);

  await page.keyboard.press('ArrowRight');
  await expect(
    page.getByRole('button', { name: `Delete from queue: ${subject}`, exact: true }).first(),
  ).toBeFocused();
});

/*
 * The top bar is sticky too, so a bar pinned at the top of the page slid up
 * behind it: the bulk actions were there, and could be neither seen nor pressed
 * until the operator scrolled back to the top of a long queue.
 */
test('the bulk-action bar stays below the top bar while a long queue scrolls', async ({ page }) => {
  // A short window, so the page overflows however few items the fleet holds.
  await page.setViewportSize({ width: 1280, height: 420 });
  await goto(page, '/queue', 'Queue');
  const select = page.getByRole('button', { name: 'Select all matching', exact: true });
  await expect(select).toBeEnabled();

  await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await expect
    .poll(() => page.evaluate(() => window.scrollY), { message: 'the page did not scroll' })
    .toBeGreaterThan(0);

  // The bar has no role or name of its own, so it is found by its class.
  const topBar = await page.getByRole('banner').boundingBox();
  const bar = await page.locator('.selection-bar').boundingBox();
  expect(topBar, 'the top bar has a box').not.toBeNull();
  expect(bar, 'the selection bar has a box').not.toBeNull();
  expect(bar!.y).toBeGreaterThanOrEqual(topBar!.y + topBar!.height);

  // Where it is drawn is not enough: the press has to reach the button.
  const button = await select.boundingBox();
  const reached = await page.evaluate(
    ({ x, y }) => document.elementFromPoint(x, y)?.closest('button')?.textContent?.trim(),
    { x: button!.x + button!.width / 2, y: button!.y + button!.height / 2 },
  );
  expect(reached).toBe('Select all matching');
});

/**
 * The refresh control.
 *
 * Zoomies keeps itself current over one SSE stream, so this button is never
 * how a page keeps up. It is how an operator settles the question -- and the
 * only thing that makes it worth having is that it is the same control, in the
 * same place, with the same name, wherever they happen to be. So that is what
 * these protect: it is on every page that has something to fetch, it is not on
 * the pages that have not, it never sits ahead of the action that changes the
 * fleet, and the keyboard reaches it too.
 */
import { expect, test, type Page } from '@playwright/test';
import { browserOverride, goto, pageHeading, SECTIONS, sectionHeading } from './support/fixtures';

test.use(browserOverride);

/** The one control. Named, not guessed at: every page must call it this. */
function refreshButton(page: Page) {
  return page.getByRole('button', { name: 'Refresh', exact: true });
}

/**
 * Sections whose pages fetch something, and therefore have the button. Migrate
 * is the exception: it holds a flow rather than a view of the fleet. Settings
 * is a section of pages, and on a phone its own address is the list of them,
 * which fetches nothing -- so it is checked on a page that does.
 */
const REFRESHABLE = [
  ...SECTIONS.filter((section) => section.path !== '/migrate' && section.path !== '/settings').map(
    (section) => ({ path: section.path, label: section.label, heading: sectionHeading(section) }),
  ),
  { path: '/settings/users', label: 'Settings', heading: 'Users' },
];

for (const section of REFRESHABLE) {
  test(`${section.label} offers refresh, and pressing it leaves the page standing`, async ({
    page,
  }) => {
    await goto(page, section.path, section.heading);

    const refresh = refreshButton(page);
    await expect(refresh).toHaveCount(1);
    await expect(refresh).toBeVisible();
    await refresh.click();

    // The heading is the proof the page did not go anywhere: a refresh that
    // remounts the route would take the operator's scroll position, their
    // selection and their place in a form with it.
    await expect(pageHeading(page, section.heading)).toBeVisible();
    await expect(refresh).not.toHaveAttribute('aria-busy', 'true');
    await expect(refresh).toBeEnabled();
  });
}

test('a page with nothing to fetch offers nothing to press', async ({ page }) => {
  // The migration wizard holds a flow, not a view of the fleet. Refreshing it
  // would either do nothing or throw away what somebody has half-filled in,
  // and a control that succeeds at neither is worse than no control.
  await goto(page, '/migrate', 'Migrate repositories');
  await expect(refreshButton(page)).toHaveCount(0);
});

test('the refresh sits before the action that changes the fleet, not after it', async ({
  page,
}) => {
  // Reading order is the whole affordance. If refresh drifts past "Add a host"
  // on one page and not on another, an operator stops reaching for it without
  // looking -- which is the only reason it is uniform. Document order rather
  // than coordinates, because the row wraps on a phone and the claim is the
  // same either way.
  await goto(page, '/hosts', 'Hosts');
  const refresh = refreshButton(page);
  const add = page.getByRole('link', { name: 'Add a host' });
  await expect(refresh).toBeVisible();
  await expect(add).toBeVisible();

  const refreshFirst = await refresh.evaluate(
    (el, other) => Boolean(el.compareDocumentPosition(other) & Node.DOCUMENT_POSITION_FOLLOWING),
    await add.elementHandle(),
  );
  expect(refreshFirst, "refresh comes before the page's own action").toBe(true);
});

test('R refreshes the page, without taking the letter from anything else', async ({ page }) => {
  await goto(page, '/hosts', 'Hosts');
  const refresh = refreshButton(page);

  // The button reports the work whichever way it was started, which is what
  // makes the key and the button one gesture rather than two. The busy window
  // is the 420ms minimum spin, which a loaded runner can let pass between two
  // of Playwright's polls -- so the page records the attribute itself, from
  // before the key goes down, and the test asks whether it was ever set.
  await refresh.evaluate((el) => {
    const seen = { busy: false };
    (window as unknown as { __refreshSeen: typeof seen }).__refreshSeen = seen;
    new MutationObserver(() => {
      if (el.getAttribute('aria-busy') === 'true') seen.busy = true;
    }).observe(el, { attributes: true, attributeFilter: ['aria-busy'] });
  });
  await page.keyboard.press('r');
  await expect(refresh).toHaveAttribute('title', /^Refreshed /);
  await expect(refresh).not.toHaveAttribute('aria-busy', 'true');
  const seen = await page.evaluate(
    () => (window as unknown as { __refreshSeen: { busy: boolean } }).__refreshSeen.busy,
  );
  expect(seen, 'the button was busy while R refreshed').toBe(true);

  // `g r` is still Runners: the chord gets the key first, and a shortcut that
  // quietly ate half the navigation would be a bad trade for a refresh.
  await page.keyboard.press('g');
  await page.keyboard.press('r');
  await expect(pageHeading(page, 'Runners')).toBeVisible();

  // And in a search field an `r` is a letter, as it is everywhere else.
  await goto(page, '/pools', 'Pools');
  const search = page.getByRole('searchbox', { name: 'Search pools' });
  await search.click();
  await page.keyboard.press('r');
  await expect(search).toHaveValue('r');
});

test('the refresh says when it last landed', async ({ page }) => {
  // Somebody reaching for this button is usually asking "is this current?",
  // and the honest answer is a time, not a spinner.
  await goto(page, '/hosts', 'Hosts');
  const refresh = refreshButton(page);
  await expect(refresh).toHaveAttribute('title', /Fetch this page again/);

  await refresh.click();
  await expect(refresh).not.toHaveAttribute('aria-busy', 'true');
  await expect(refresh).toHaveAttribute('title', /^Refreshed .+\. Fetch it again\./);
});

import { expect, test, type Page, type TestInfo } from '@playwright/test';
import { browserOverride, goto, grid, waitForRows } from './support/fixtures';

test.use(browserOverride);

/*
 * The words each style draws the same two moments with. Off is what a browser
 * that has never chosen shows; Cute is here because its 44px avatar is the
 * harder thing to fit in a narrow column, and the no-clipping check below is
 * worth most against it.
 */
const STYLES = [
  {
    style: 'off',
    boosted: 'Zoomies',
    lifecycle: 'Busy',
    boost: 'Maximum boost',
    throttled: 'Throttled',
  },
  {
    style: 'cute',
    boosted: 'Squirrel spotted',
    lifecycle: 'Walking!',
    boost: 'Maximum zoomies',
    throttled: 'Leash tightened',
  },
] as const;

for (const words of STYLES)
  test(`one live status keeps details accessible without clipping in rows or cards (${words.style})`, async ({
    page,
    isMobile,
  }, testInfo) => {
    await page.addInitScript((style) => {
      if (!localStorage.getItem('zoomies.prefs'))
        localStorage.setItem('zoomies.prefs', JSON.stringify({ statusStyle: style }));
    }, words.style);
    await runStatusChecks(page, isMobile, testInfo, words);
  });

async function runStatusChecks(
  page: Page,
  isMobile: boolean,
  testInfo: TestInfo,
  words: (typeof STYLES)[number],
): Promise<void> {
  let cpuState = 'maximum_zoomies';
  let runner: Record<string, unknown> | undefined;
  const withCPU = (row: Record<string, unknown>) => ({
    ...row,
    cpu_resource: {
      state: cpuState,
      guaranteed_cpus: 2,
      current_cpus: cpuState === 'throttled' ? 1 : 3.8,
      ceiling_cpus: 4,
    },
  });
  await page.route('**/api/v1/runners?*', async (route) => {
    const response = await route.fetch();
    const data = await response.json();
    data.items = data.items.map((row: Record<string, unknown>) => {
      if (row.state !== 'busy') return row;
      const updated = withCPU(row);
      runner ??= updated;
      return updated;
    });
    await route.fulfill({ response, json: data });
  });
  await page.route('**/api/v1/events*', (route) =>
    route.fulfill({
      contentType: 'text/event-stream',
      body: runner
        ? `event: runner.updated\ndata: ${JSON.stringify(withCPU(runner))}\n\n`
        : ': connected\n\n',
    }),
  );
  await goto(page, '/runners', 'Runners');
  const table = grid(page, 'Runners');
  await waitForRows(table);
  if (isMobile) await page.getByRole('button', { name: /^Rows\b/ }).tap();
  await expect(table.getByRole('columnheader', { name: /Status/ })).toBeVisible();
  await expect(table.getByRole('columnheader', { name: /Zoomies/ })).toHaveCount(0);
  const status = table
    .getByRole('button', { name: `${words.boosted}: show status details` })
    .first();
  await status.scrollIntoViewIfNeeded();
  if (isMobile) await status.tap();
  else await status.click();
  const tip = page.locator('.runner-status-tip .bubble:popover-open');
  await expect(tip).toBeVisible();
  await expect(tip).toContainText(words.lifecycle);
  await expect(tip).toContainText(words.boost);
  await expect(tip).toContainText('3.8');
  const bounds = (await tip.boundingBox())!;
  expect(bounds.x).toBeGreaterThanOrEqual(0);
  expect(bounds.x + bounds.width).toBeLessThanOrEqual(page.viewportSize()!.width);
  await page.screenshot({
    path: testInfo.outputPath(`unified-status-${words.style}.png`),
    fullPage: true,
  });
  await page.keyboard.press('Escape');
  await expect(tip).toHaveCount(0);

  // A CPU-only SSE update must replace the label without a page navigation.
  cpuState = 'throttled';
  await page.evaluate(() => {
    window.dispatchEvent(new Event('offline'));
    window.dispatchEvent(new Event('online'));
  });
  const leash = table
    .getByRole('button', { name: `${words.throttled}: show status details` })
    .first();
  await expect(leash).toBeVisible();
  // Existing saved/narrow widths must wrap, never ellipsize the status.
  await table.locator('th[data-table-column="state"]').evaluate((node) => {
    (node as HTMLElement).style.width = '112px';
  });
  const clipped = await leash.evaluate((button) => {
    const label = button.querySelector('.label')!;
    const avatar = button.querySelector('svg')!.getBoundingClientRect();
    const cell = button.closest('td')!.getBoundingClientRect();
    const rect = label.getBoundingClientRect();
    const overlaps =
      avatar.left < rect.right &&
      avatar.right > rect.left &&
      avatar.top < rect.bottom &&
      avatar.bottom > rect.top;
    return (
      label.scrollWidth > label.clientWidth + 1 ||
      rect.right > cell.right + 1 ||
      avatar.left < cell.left - 1 ||
      avatar.right > cell.right + 1 ||
      overlaps
    );
  });
  expect(clipped).toBe(false);
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await expect
    .poll(() => leash.locator('svg').evaluate((svg) => svg.getAnimations({ subtree: true }).length))
    .toBe(0);
  if (isMobile) {
    await page.getByRole('button', { name: /^Cards\b/ }).tap();
    await expect(leash).toBeVisible();
    await leash.tap();
    await expect(tip).toContainText('Host pressure protection');
    await page.screenshot({
      path: testInfo.outputPath(`status-card-${words.style}.png`),
      fullPage: true,
    });
  }
}

/**
 * The Runners grid.
 *
 * This is where an operator spends an incident, so it protects the things
 * that make a grid trustworthy: the rows say what state each runner is in, a
 * narrowed view is a URL somebody can paste to a colleague and reload, the
 * columns an operator chose stay chosen, the keyboard alone can drive it, and
 * anything destructive names the runner it is about and does nothing at all
 * when you change your mind.
 */
import { expect, test, type Locator, type Page } from '@playwright/test';
import {
  browserOverride,
  cellUnder,
  dataRows,
  FIXTURE,
  goto,
  grid,
  pageHeading,
  reload,
  rowCount,
  waitForRows,
} from './support/fixtures';

test.use(browserOverride);

/**
 * Every state badge the grid can draw, from web/src/lib/status.ts, in the plain
 * words a browser that has not chosen the kennel's vocabulary is shown.
 */
const STATES = ['Provisioning', 'Registering', 'Idle', 'Busy', 'Draining', 'Failed', 'Removed'];

const runners = (page: Page) => grid(page, 'Runners');

/** Wait for the first page of rows rather than for the network to go quiet. */
async function runnerRows(page: Page): Promise<Locator> {
  return waitForRows(runners(page));
}

/** The name in a row, read from the row rather than assumed: rows are sorted. */
async function nameOf(row: Locator): Promise<string> {
  return (await row.getByRole('link').first().innerText()).trim();
}

test('the grid lists the seeded runners with their states', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  const rows = await runnerRows(page);

  // The seed writes twelve runners; the terminal ones are hidden by default,
  // and the scheduler works on the rest as it catches up -- draining the idle
  // ones, giving up on the ones no agent ever collects -- so the count is a
  // floor rather than an exact number. Three busy, three draining and one idle
  // survive indefinitely, because nothing is there to finish their jobs.
  expect(await rows.count()).toBeGreaterThanOrEqual(6);
  await expect(rowCount(page)).toContainText(/of \d+\s+runners/);

  const gridLocator = runners(page);
  await expect(await cellUnder(gridLocator, rows.first(), 'Status')).toBeVisible();

  const states = await gridLocator.locator('[data-runner-status] .label').allTextContents();
  expect(states.length).toBe(await rows.count());
  for (const label of states) {
    expect(STATES, `"${label.trim()}" is one of the states the product defines`).toContain(
      label.trim(),
    );
  }

  const busy = rows.filter({ hasText: FIXTURE.busyRunner });
  await expect(busy).toHaveCount(1);
  await expect(busy).toContainText('Busy');
  await expect(busy).toContainText(FIXTURE.linuxPool);
});

test('filtering by state narrows the rows and puts the filter in the URL', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  await runnerRows(page);
  const before = await dataRows(runners(page)).count();

  await page.getByRole('button', { name: 'Any state' }).click();
  await page
    .getByRole('group', { name: 'Filter by runner state' })
    .getByRole('checkbox', { name: 'Busy' })
    .check();
  await page.keyboard.press('Escape');

  await expect(page).toHaveURL(/[?&]state=busy/);
  await expect(page.getByRole('group', { name: 'Filters in effect' })).toContainText('Busy');

  const filtered = dataRows(runners(page));
  await expect(filtered.first()).toBeVisible();
  await expect(filtered).not.toHaveCount(before);
  for (const label of await runners(page)
    .locator('[data-runner-status] .label')
    .allTextContents()) {
    expect(label.trim(), 'every remaining row matches the filter').toBe('Busy');
  }
  const narrowed = await filtered.count();

  // The whole point of keeping filters in the URL: paste it, get the same view.
  await reload(page, 'Runners');
  await expect(page).toHaveURL(/[?&]state=busy/);
  await expect(dataRows(runners(page))).toHaveCount(narrowed);
  await expect(page.getByRole('button', { name: 'Busy', exact: true })).toBeVisible();
});

test('a hidden column stays hidden after a reload', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  await runnerRows(page);
  await expect(runners(page).getByRole('columnheader', { name: 'Host' })).toBeVisible();

  await page.getByRole('button', { name: 'Columns' }).click();
  await page
    .getByRole('group', { name: 'Column layout' })
    .getByRole('checkbox', { name: 'Host' })
    .uncheck();
  await expect(runners(page).getByRole('columnheader', { name: 'Host' })).toHaveCount(0);

  await reload(page, 'Runners');
  await runnerRows(page);
  await expect(runners(page).getByRole('columnheader', { name: 'Host' })).toHaveCount(0);
  // Only that column went: hiding one must not quietly hide others.
  await expect(runners(page).getByRole('columnheader', { name: 'Status' })).toBeVisible();
  await expect(runners(page).getByRole('columnheader', { name: 'Name' })).toBeVisible();
});

/*
 * The column chooser is a panel of checkboxes, not a menu, and closing it with
 * Escape from inside it must not strand the keyboard: the checkbox focus was on
 * is unmounted with the panel, and focus that falls to the document sends the
 * next Tab back to the top of the page. It returns to the button that opened it.
 */
test('escape closes the column chooser and returns focus to its button', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  await runnerRows(page);

  const columns = page.getByRole('button', { name: 'Columns' });
  // A panel of checkboxes, so it is announced as a dialog rather than as a
  // menu whose arrow keys do nothing.
  await expect(columns).toHaveAttribute('aria-haspopup', 'dialog');

  await columns.click();
  const checkbox = page
    .getByRole('group', { name: 'Column layout' })
    .getByRole('checkbox', { name: 'Host' });
  await checkbox.focus();
  await expect(checkbox).toBeFocused();

  await page.keyboard.press('Escape');
  await expect(page.getByRole('group', { name: 'Column layout' })).toHaveCount(0);
  await expect(columns).toBeFocused();
});

test('selecting rows reveals the bulk bar with the number selected', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  const rows = await runnerRows(page);
  const total = await rows.count();

  const bulk = page.getByRole('group', { name: /Actions for the selected/ });
  await expect(bulk).toHaveCount(0);

  await page.getByRole('checkbox', { name: /^Select every/ }).check();
  await expect(bulk).toBeVisible();
  await expect(bulk).toContainText(`${total} selected`);
  await expect(bulk.getByRole('button', { name: 'Drain' })).toBeVisible();
  await expect(bulk.getByRole('button', { name: 'Delete' })).toBeVisible();

  await bulk.getByRole('button', { name: 'Clear selection' }).click();
  await expect(bulk).toHaveCount(0);

  // One row, chosen from the keyboard, is counted the same way.
  await rows.first().focus();
  await page.keyboard.press(' ');
  await expect(bulk).toContainText('1 selected');
  await expect(page).toHaveURL(/\/runners$/);
});

test('clicking a row checkbox selects that row instead of opening the runner', async ({ page }) => {
  // This caught a bug that made mouse selection impossible: every cell holding
  // a control stopped the row's click from reaching the row -- the name cell
  // and the actions cell both did -- except the selection checkbox, so ticking
  // a row navigated to it and selected nothing. The keyboard path (Space on a
  // focused row) was unaffected, which is why the test above passed throughout.

  await goto(page, '/runners', 'Runners');
  const rows = await runnerRows(page);

  await rows.first().getByRole('checkbox').click();

  await expect(page, 'ticking a row must not navigate').toHaveURL(/\/runners$/);
  await expect(page.getByRole('group', { name: /Actions for the selected/ })).toContainText(
    '1 selected',
  );
});

test('draining a runner asks first, names it, and cancelling changes nothing', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  const rows = await runnerRows(page);
  const row = rows.filter({ hasText: FIXTURE.busyRunner }).first();
  const name = await nameOf(row);
  expect(name).toBe(FIXTURE.busyRunner);

  const trigger = page.getByRole('button', { name: `Actions for ${name}` });
  await trigger.click();
  await page.getByRole('menuitem', { name: 'Drain', exact: true }).click();

  const dialog = page.getByRole('dialog');
  await expect(dialog).toBeVisible();
  // Named, and counted: a destructive action must say what it is about.
  await expect(dialog.getByRole('heading', { name: 'Drain runner' })).toBeVisible();
  await expect(dialog).toContainText(name);
  // This expectation moved deliberately. The dialog used to say draining never
  // interrupts work in progress, which was not true: the stop task carries a
  // five-minute timeout and the runner is killed after it. The dialog now says
  // what it costs, and this asserts the honest sentence rather than the
  // comfortable one.
  await expect(dialog).toContainText(
    'The job it is running now has five minutes to finish. If it takes longer, the runner is stopped and GitHub marks that job failed.',
  );

  await dialog.getByRole('button', { name: 'Cancel' }).click();
  await expect(dialog).toBeHidden();

  // Nothing was asked of the controller, so the runner is exactly as it was.
  await expect(row).toContainText('Busy');
  await expect(page).toHaveURL(/\/runners$/);
  await reload(page, 'Runners');
  await expect(dataRows(runners(page)).filter({ hasText: FIXTURE.busyRunner })).toContainText(
    'Busy',
  );
});

test('opening a runner shows its detail page and its state timeline', async ({ page }) => {
  await goto(page, '/runners', 'Runners');
  const rows = await runnerRows(page);
  const row = rows.filter({ hasText: FIXTURE.busyRunner }).first();

  await row.getByRole('link', { name: FIXTURE.busyRunner }).click();

  await expect(pageHeading(page, FIXTURE.busyRunner)).toBeVisible();
  await expect(page).toHaveURL(/\/runners\/run_demo\d+$/);

  const timeline = page.getByRole('region', { name: 'Timeline' });
  await expect(timeline).toBeVisible();
  await expect(timeline.getByRole('listitem').first()).toBeVisible();
  // The states this runner passed through on the way to being busy.
  await expect(timeline).toContainText('Provisioning');
