/**
 * The scrollbar is a control an operator has to be able to find and take hold
 * of, which docs/ui-guidelines.md section 1.8 fixes at a token's width on a
 * pointer device and leaves to the browser's overlay bar on a phone.
 *
 * A file of its own because headless Chromium hides every scrollbar unless
 * told not to, and a hidden scrollbar measures exactly like a thin one --
 * nothing -- so the browser here is launched with that flag dropped, and a
 * launch option cannot change inside a describe block.
 */
import { expect, test } from '@playwright/test';
import { browserOverride, goto, grid, waitForRows } from './support/fixtures';

test.use({
  launchOptions: {
    ...('launchOptions' in browserOverride ? browserOverride.launchOptions : {}),
    ignoreDefaultArgs: ['--hide-scrollbars'],
  },
});

test('the scrollbar is wide enough to take hold of, and out of the way on a phone', async ({
  page,
  isMobile,
}) => {
  // The finished jobs are more rows than the grid shows at once, so the frame
  // around the table scrolls. Asked for by name rather than left to the page's
  // own view, which opens on what is running and on a quiet fleet is three
  // rows -- not enough to scroll, and the scrollbar is the whole subject here.
  // Reached structurally: nothing in the accessibility tree names a scroll
  // frame, and the grid is the element inside it.
  await goto(page, '/jobs?state=completed', 'Jobs');
  const jobs = grid(page, 'Jobs');
  await waitForRows(jobs);

  const measured = await jobs.evaluate((table) => {
    const frame = table.parentElement as HTMLElement;
    const style = getComputedStyle(frame);
    const borders = parseFloat(style.borderLeftWidth) + parseFloat(style.borderRightWidth);
    return {
      overflows: frame.scrollHeight > frame.clientHeight,
      // What the scrollbar takes out of the frame's width, which is its whole
      // hit target -- or nothing, for an overlay scrollbar.
      gutter: frame.offsetWidth - frame.clientWidth - borders,
      size: parseFloat(
        getComputedStyle(document.documentElement).getPropertyValue('--z-scrollbar-size'),
      ),
    };
  });
  expect(measured.overflows, 'the jobs grid has something to scroll').toBe(true);

  if (isMobile) {
    // A finger scrolls the content, never the bar, so the phone keeps the
    // browser's overlay scrollbar and no column is reserved for one.
    expect(measured.gutter, 'no column is reserved on a phone').toBe(0);
  } else {
    // The column is drawn at the token's width, and all of it is the target.
    // This is the regression guard: set `scrollbar-width` beside the
    // `::-webkit-scrollbar` rules and Chromium ignores them, draws its own
    // thin bar, and this stops being equal.
    expect(measured.gutter, 'the scrollbar column is the token width').toBe(measured.size);
  }
});

/**
 * Settings: the accounts and the API tokens, and the section they live in.
 *
 * These are the two places in the product where a mistake is expensive and
 * irreversible, so the protections are the point: deleting an account demands
 * its name typed out, a minted token is shown once and says so, and a revoked
 * token stops working immediately. None of it had a test.
 *
 * The seeded fixture has neither users nor tokens -- the demo seed refuses to
 * run at all on an instance that already has an account -- so each test makes
 * what it needs and takes it away again.
 */
import { randomBytes } from 'node:crypto';
import { expect, test, type Page } from '@playwright/test';
import { browserOverride, goto, openAccountMenu, pageHeading } from './support/fixtures';

test.use(browserOverride);

const dialog = (page: Page, name: string | RegExp) => page.getByRole('dialog', { name });

/**
 * A name nothing else in the suite will collide with. Random bytes rather than
 * Math.random(): these names become account usernames, and a scanner cannot
 * tell a test fixture from a credential.
 */
function unique(prefix: string): string {
  return `${prefix}-${randomBytes(4).toString('hex')}`;
}

/**
 * The page's own create button.
 *
 * An empty page carries two of them -- one in its header, one inside the
 * empty state, which is the guidelines' rule that an empty state names the
 * next step with the action inline. The first in document order is the
 * header's, and it is there whether the page is empty or not.
 */
const create = (page: Page, label: string) => page.getByRole('button', { name: label }).first();

/**
 * The section's own navigation: a rail beside the page on a desktop, a strip
 * above it on a tablet, and on a phone the list `/settings` itself shows.
 * Either way, every page is a link in a landmark named for the section.
 */
const settingsNav = (page: Page) => page.getByRole('navigation', { name: 'Settings' });

