// Boots a real `zoomies controller` for a Playwright project, and tears it down.
//
// The tests drive the actual binary rather than a mock: if the UI works here it
// works in production, because it is the same server. Two projects need two
// different servers -- one with authentication off and a seeded demo fleet for
// the monitoring pages, one with authentication on and an empty database for
// the first-run pages -- so the difference between them is a few environment
// variables and everything else lives here. It used to live in both, and the
// copies had already drifted in how they shut down.

import { spawn } from 'node:child_process';
import { mkdtempSync, mkdirSync, rmSync, existsSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';

/**
 * The settings every fixture shares, given the directory it runs out of.
 *
 * Exported so the screenshot runner -- which has its own lifecycle, because it
 * boots, drives a browser and stops within one script rather than living as
 * long as a Playwright project -- still agrees with the suite about where the
 * database goes and whether an agent runs.
 */
export function controllerEnv(dir, port) {
  return {
    ZOOMIES_BIND: `127.0.0.1:${port}`,
    ZOOMIES_DB_PATH: join(dir, 'zoomies.db'),
    ZOOMIES_STATE_DIR: dir,
    ZOOMIES_CONFIG_DIR: dir,
    ZOOMIES_WORK_DIR: join(dir, 'work'),
    // No agent: these tests are about the UI, and an embedded agent would try
    // to talk to a Docker daemon that CI does not guarantee.
    ZOOMIES_AGENT_EMBEDDED: 'false',
    ZOOMIES_POLL_FALLBACK: 'false',
    ZOOMIES_LOG_FORMAT: 'text',
    ZOOMIES_LOG_LEVEL: 'warn',
  };
}

/**
 * Start the controller and keep the process alive until it exits.
 *
 * @param {object} options
 * @param {string} options.port          Loopback port to bind.
 * @param {string} options.prefix        Temporary directory prefix, for readable `ls /tmp`.
 * @param {Record<string, string>} options.env  Settings this fixture differs by.
 * @param {string} [options.tokenFile]   Where to write the setup token the
 *   controller prints while it has no accounts. The first-run fixture needs it:
 *   the bootstrap route asks for the token as proof that whoever is creating
 *   the first administrator can read the controller's log, and a test is in the
 *   same position as the operator -- it has to go and get it.
 */
export function serveController({ port, prefix, env, tokenFile }) {
  const root = resolve(import.meta.dirname, '..', '..', '..');
  const binary = join(root, 'zoomies');

  if (!existsSync(binary)) {
    console.error(
      `zoomies binary not found at ${binary}.\n` +
        `Build it first:  make build   (or: go build -o zoomies ./cmd/zoomies)`,
    );
    process.exit(1);
  }

  const dir = mkdtempSync(join(tmpdir(), prefix));
  const cleanup = () => {
    try {
      rmSync(dir, { recursive: true, force: true });
    } catch {
      /* the OS will get it */
    }
  };

  const child = spawn(binary, ['controller'], {
    // stdout is piped only when somebody is watching for the setup token, and
    // is echoed on either way: a fixture that swallowed the controller's own
    // output would make a failed boot impossible to read in CI.
    stdio: tokenFile ? ['inherit', 'pipe', 'inherit'] : 'inherit',
    env: { ...process.env, ...controllerEnv(dir, port), ...env },
  });

  if (tokenFile) {
    let seen = false;
    child.stdout.on('data', (chunk) => {
      process.stdout.write(chunk);
      if (seen) return;
      const match = /setup token\s+(\S+)/.exec(String(chunk));
      if (!match) return;
      seen = true;
      mkdirSync(dirname(tokenFile), { recursive: true });
      writeFileSync(tokenFile, match[1]);
    });
  }

  // Ask it to stop, then wait: the exit handler below does the removal. Pulling
  // the SQLite directory out from under a controller still checkpointing its
  // WAL produced an error on the way out and, now and then, a hang.
  const stop = (signal) => child.kill(signal);
  process.on('SIGINT', () => stop('SIGINT'));
  process.on('SIGTERM', () => stop('SIGTERM'));
  process.on('exit', cleanup);
  child.on('exit', (code) => {
    cleanup();
    process.exit(code ?? 0);
  });

  return child;
}

/**
 * Shared helpers for the Zoomies end-to-end suite.
 *
 * Two rules shape everything in here:
 *
 *  * Never wait for `networkidle`. The app holds a Server-Sent Events
 *    connection open for its whole life, so the network is never idle and any
 *    such wait burns the timeout instead of proving anything. `goto()` below
 *    settles on `domcontentloaded` and then waits for a real thing on the page.
 *  * Prefer roles and accessible names over CSS. Where a CSS selector is used
 *    it is because nothing in the accessibility tree distinguishes what is
 *    being reached for -- the three lines of a problem entry, say, or a
 *    grid's body rows -- and each of those is commented at the point of use.
 *    The tests cannot add `data-testid`: the Svelte source is not theirs.
 */
import { readFileSync } from 'node:fs';
import { expect, type Locator, type Page } from '@playwright/test';

/**
 * A browser override for sandboxes where Playwright's own Chromium download is
 * absent and a compatible build sits somewhere else.
 *
 * CI installs the browser normally (`npx playwright install --with-deps
 * chromium`), leaves `PLAYWRIGHT_CHROMIUM` unset, and therefore gets `{}` --
 * no override at all. Every spec applies it with `test.use(browserOverride)`.
 */
/**
 * Where the first-run fixture leaves the setup token it saw the controller
 * print.
 *
 * The bootstrap route asks for that token: an empty database is not proof that
 * whoever is filling the first-run form deployed this controller, and being
 * able to read its log is. A test is in the same position as the operator, so
 * it fetches the token the same way -- out of the output. The path is defined
 * here and handed to the fixture on its command line, so the two cannot drift.
 */
export const SETUP_TOKEN_FILE = 'test-results/firstrun-setup-token';

/** The token the running first-run controller printed. */
export function setupToken(): string {
  return readFileSync(SETUP_TOKEN_FILE, 'utf8').trim();
}

export const browserOverride = process.env.PLAYWRIGHT_CHROMIUM
  ? { launchOptions: { executablePath: process.env.PLAYWRIGHT_CHROMIUM } }
  : {};

/**
 * The persistent navigation, in the fixed order docs/ui-guidelines.md gives.
 *
 * `heading` is the page's own <h1> where it says more than the nav entry does:
 * a nav label has to stay short enough to sit beside an icon, and a heading
 * does not. `lands` is where the address ends up when it is not the entry's
 * own path: Settings is a section of pages, so on a desktop `/settings` goes
 * straight to the first of them, while a phone shows the list of pages under
 * the section's own name.
 */
export const SECTIONS = [
  { path: '/', label: 'Overview' },
  { path: '/pools', label: 'Pools' },
  { path: '/runners', label: 'Runners' },
  { path: '/workflows', label: 'Workflows' },
  { path: '/usage', label: 'Usage' },
  { path: '/hosts', label: 'Hosts' },
  { path: '/providers', label: 'Providers' },
  { path: '/installations', label: 'Installations' },
  { path: '/migrate', label: 'Migrate', heading: 'Migrate repositories' },
  { path: '/ai-context', label: 'AI Context' },
  { path: '/audit', label: 'Audit' },
  {
    path: '/settings',
    label: 'Settings',
    heading: /^(Account|Settings)$/,
    lands: /\/settings(\/account)?$/,
  },
] as const;

/** The <h1> a section's page shows. */
export function sectionHeading(section: (typeof SECTIONS)[number]): string | RegExp {
  return 'heading' in section ? section.heading : section.label;
}

/** A path as a literal inside a pattern: every metacharacter escaped, not only the slashes. */
function escapeForPattern(path: string): string {
  return path.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
}

/** The address a section's entry ends up at, as a pattern the URL must match. */
export function sectionLanding(section: (typeof SECTIONS)[number]): RegExp {
  return 'lands' in section ? section.lands : new RegExp(`${escapeForPattern(section.path)}$`);
}

