import { serveController } from './controller.mjs';

serveController({
  port: process.argv[2] ?? '8099',
  prefix: 'zoomies-e2e-',
  env: {
    ZOOMIES_DISABLE_AUTH: 'true',
    // Seeds a deterministic fixture fleet so pages have content to assert on.
