    tone: 'pending',
    level: 3,
  });
  // No telemetry is not the same as never blocked.
  assert.equal(paint(series[1]!, 'capacity', scale).kind, 'unsampled');
});

test('a square says everything it knows in one sentence', () => {
  const at = new Date(2026, 8, 9, 14);
  const b = bucket(at.toISOString(), {
    succeeded: 35,
    failed: 2,
    cancelled: 1,
    queued: 40,
    started: 39,
    execution_seconds: 23_040,
    capacity_samples: 1440,
    capacity_reached: 3,
  });
  assert.equal(headline(b), '38 jobs finished, 2 failed');
  // The date is spelled the way the operator's locale spells it, so the test
  // asks the same formatter rather than assuming a British one.
  const day = new Intl.DateTimeFormat(undefined, {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(at);
  assert.equal(
    describe(b, at, 'day'),
    `${day}. 38 jobs finished, 2 failed: 35 succeeded, 2 failed, 1 cancelled or skipped, 0 unknown; 40 queued, 39 started; 6.4 h executing; 3 of 1,440 observed pool-minutes at capacity.`,
  );
  const clock = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
  const short = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short' }).format(at);
  assert.ok(
    describe(b, at, 'hour').startsWith(
      `${short}, ${clock.format(at)} to ${clock.format(new Date(at.getTime() + 3_600_000))}.`,
    ),
  );
  assert.equal(headline(bucket('x', { queued: 2 })), '2 jobs queued, none finished');
  assert.equal(headline(bucket('x')), 'No jobs');
  const totals = summarise([b, bucket('y', { queued: 1 })]);
  assert.equal(totals.completed, 38);
  assert.equal(totals.active, 2);
});

test('a job frame lands in the square its moment belongs to, and only once', () => {
  const first = new Date(2026, 8, 7);
  const series = fillWindow([], first, 7, 'day');
  const fetched = new Date(2026, 8, 9, 12).getTime();
  const seen = newSeen();
  const queuedAt = new Date(2026, 8, 9, 13).toISOString();
  const startedAt = new Date(2026, 8, 9, 13, 1).toISOString();
  const completedAt = new Date(2026, 8, 9, 13, 5).toISOString();

  const queued = foldJob(
    series,
    'day',
    { id: 'job_1', state: 'queued', queued_at: queuedAt } as never,
    fetched,
    seen,
  );
  assert.ok(queued, 'a queued frame after the fetch counts');
  assert.equal(queued[2]?.queued, 1);
  assert.notEqual(queued, series, 'the series is replaced, never mutated');
  assert.equal(series[2]?.queued, 0);

  const again = foldJob(
    queued,
    'day',
    { id: 'job_1', state: 'queued', queued_at: queuedAt } as never,
    fetched,
    seen,
  );
  assert.equal(again, null, 'the same frame twice changes nothing');

  const done = foldJob(
    queued,
    'day',
    {
      id: 'job_1',
      state: 'completed',
      queued_at: queuedAt,
      started_at: startedAt,
      completed_at: completedAt,
      conclusion: 'failure',
    } as never,
    fetched,
    seen,
  );
  assert.ok(done);
  assert.equal(done[2]?.queued, 1, 'still counted once as queued');
  assert.equal(done[2]?.started, 1);
  assert.equal(done[2]?.failed, 1);

  // A job that finished before the fetch is already in the series.
  const old = foldJob(
    done,
    'day',
    {
      id: 'job_0',
      state: 'completed',
      queued_at: new Date(2026, 8, 9, 8).toISOString(),
      started_at: new Date(2026, 8, 9, 8).toISOString(),
      completed_at: new Date(2026, 8, 9, 9).toISOString(),
      conclusion: 'success',
    } as never,
    fetched,
    seen,
  );
  assert.equal(old, null);

  // A runner that died under a job is the fleet's failure, however GitHub
  // concluded it.
  const lost = foldJob(
    done,
    'day',
    {
      id: 'job_2',
      state: 'completed',
      completed_at: completedAt,
      conclusion: 'cancelled',
      runner_fault: 'runner stopped',
    } as never,
    fetched,
    seen,
  );
  assert.equal(lost?.[2]?.failed, 2);
  assert.equal(lost?.[2]?.cancelled, 0);
});

test('a moment outside the series has no square', () => {
  const first = new Date(2026, 8, 7);
  const series = fillWindow([], first, 7, 'day');
  assert.equal(bucketIndex(series, addDays(first, 7).getTime(), 'day'), -1);
  assert.equal(bucketIndex(series, first.getTime() - 1, 'day'), -1);
  assert.equal(bucketIndex(series, addDays(first, 6).getTime() + 1, 'day'), 6);
});

test('a quick range is the last N days, today included, in the width asked for', () => {
  const now = new Date(2026, 8, 9, 15, 30);
  const week = rangeWindow(7, 'hour', now);
  assert.equal(week.from.getDate(), 3, 'six days ago');
  assert.equal(week.from.getHours(), 0, 'from local midnight');
  assert.equal(week.count, 7 * 24, 'a week of hours');
  assert.equal(week.to.getTime() - week.from.getTime(), 7 * 24 * 3_600_000);
  assert.equal(week.interval, 'hour');
  const today = rangeWindow(1, 'hour', now);
  assert.equal(today.from.getDate(), 9);
  assert.equal(today.count, 24);
  const month = rangeWindow(30, 'day', now);
  assert.equal(month.count, 30);
  assert.equal(month.from.getMonth(), 7, 'starts in August');
  assert.equal(month.from.getDate(), 11);
});

test('a month and a quarter cut every day into the same squares', () => {
  const now = new Date(2026, 8, 9, 15, 30);
  const month = rangeWindow(30, '4h', now);
  assert.equal(month.count, 30 * 6, 'six four-hour squares a day');
  assert.equal(month.from.getDate(), 11, 'from the same midnight as a month of days');
  assert.equal(month.to.getTime() - month.from.getTime(), 30 * 86_400_000);
  const quarter = rangeWindow(90, '8h', now);
  assert.equal(quarter.count, 90 * 3, 'three eight-hour squares a day');
  assert.equal(intervalWidth('8h'), 8 * 3_600_000);
  assert.equal(slicesPerDay('day'), 1);
  assert.equal(slicesPerDay('4h'), 6);
  assert.equal(slicesPerDay('hour'), 24);
});

test("a sliced calendar puts a day's squares side by side in its weekday's row", () => {
  // Wednesday 9 September, in eight-hour squares, so the window's first two
  // weekdays are blank and every day is three squares.
  const first = new Date(2026, 8, 9);
  const series = fillWindow(
    [bucket(new Date(2026, 8, 10, 8).toISOString(), { succeeded: 2 })],
    first,
    5 * 3,
    '8h',
  );
  const columns = calendar(series, first, 3);
  assert.equal(columns.length, 1);
  const cells = columns[0]!.cells;
  assert.equal(cells.length, 7 * 3, 'seven days of three');
  assert.deepEqual(
    cells.slice(0, 6),
    [null, null, null, null, null, null],
    'Monday and Tuesday are before the window',
  );
  // Thursday is row 3; its middle square is bucket 4, eight in the morning.
  const thursday = cells.slice(3 * 3, 4 * 3);
  assert.deepEqual(
    thursday.map((c) => c?.index),
    [3, 4, 5],
  );
  assert.equal(thursday[1]?.bucket.succeeded, 2);
  assert.equal(thursday[1]?.date.getHours(), 8, 'a slice starts at its hour on the local clock');
  assert.equal(thursday[1]?.date.getDate(), 10);
  assert.equal(thursday[2]?.date.getHours(), 16);
  // Month labels read the first square of a column, whatever the slices.
  assert.ok(columns[0]?.label?.startsWith('Sep'));
});

test('a slice says the stretch of the day it is, weekday and all', () => {
  const at = new Date(2026, 8, 10, 16);
  const name = intervalName(at, '8h');
  const clock = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
  // The last slice of a day ends at midnight on the clock.
  assert.ok(name.endsWith(`${clock.format(at)} to ${clock.format(new Date(2026, 8, 11))}`), name);
  const weekday = new Intl.DateTimeFormat(undefined, { weekday: 'short' }).format(at);
  assert.ok(name.includes(weekday), `${name} names its weekday`);
  assert.equal(intervalNoun('8h'), 'hours');
  assert.equal(intervalNoun('day'), 'day');
  assert.equal(intervalNoun('hour'), 'hour');
});

test('a calendar too cramped for month names gets their initials', () => {
  const first = new Date(2026, 0, 5); // a Monday
  const columns = calendar(fillWindow([], first, 10 * 7, 'day'), first);
  const initials = new Intl.DateTimeFormat(undefined, { month: 'narrow' });
  const narrow = monthLabels(columns, 'narrow').filter(Boolean);
  assert.deepEqual(narrow, [
    initials.format(new Date(2026, 0, 1)),
    initials.format(new Date(2026, 1, 1)),
    initials.format(new Date(2026, 2, 1)),
  ]);
  // The same columns, and the same columns labelled, as the short names.
  assert.deepEqual(
    monthLabels(columns, 'narrow').map((l) => l !== null),
    monthLabels(columns).map((l) => l !== null),
  );
});

test('a window of any length is drawn in the squares the Overview uses for one as long', () => {
  const days = (n: number) => n * 86_400_000;
  assert.equal(matrixInterval(days(1)), 'hour', 'a day is a row of hours');
  assert.equal(matrixInterval(days(7)), 'hour', 'a week is the punch card');
  assert.equal(matrixInterval(days(14)), 'hour', 'a fortnight is the most hours the API cuts');
  assert.equal(matrixInterval(days(30)), '4h');
  assert.equal(matrixInterval(days(56)), '4h');
  assert.equal(matrixInterval(days(90)), '8h');
  assert.equal(matrixInterval(days(112)), '8h');
  assert.equal(matrixInterval(days(113)), 'day');
  assert.equal(matrixInterval(days(366)), 'day');
  // A fortnight across a clock change is an hour over what the API cuts into
  // hours, so it is four-hourly rather than refused.
  assert.equal(matrixInterval(days(14) + 3_600_000), '4h');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildLabel } from '../src/lib/shell/build.ts';

// A release is named by its tag, because that is what an upgrade and a bug
// report say, and it links to the release's own page.
test('a release build is named by its tag and links to the release', () => {
  const got = buildLabel({
    version: '1.3.0 (abc1234)',
    version_channel: 'v1.3.0',
    commit: 'abc1234def',
  });
  assert.equal(got?.kind, 'Release');
  assert.equal(got?.name, 'v1.3.0');
  assert.equal(got?.href, 'https://github.com/eyupio/zoomies/releases/tag/v1.3.0');
});

// Every build from main is published under the same moving dev tag, so the
// tag cannot tell two apart: the commit is what identifies one.
test('a dev build is named by its commit and links to it', () => {
  const got = buildLabel({
    version: 'main-sha-abc1234 (abc1234)',
    version_channel: 'dev',
    commit: 'abc1234def5678',
  });
  assert.equal(got?.kind, 'Dev');
  assert.equal(got?.name, 'abc1234');
  assert.equal(got?.href, 'https://github.com/eyupio/zoomies/commit/abc1234def5678');
});

// A local build is on no channel and in no release; it says so rather than
// linking somewhere that does not have it.
test('a local build is labelled as one and links nowhere', () => {
  const got = buildLabel({ version: '1.3.0-4-gabc1234-dirty', commit: 'abc1234def' });
  assert.equal(got?.kind, 'Local build');
  assert.equal(got?.name, 'abc1234');
  assert.equal(got?.href, undefined);
});

test('nothing is said before the controller has answered', () => {
  assert.equal(buildLabel(null), null);
  assert.equal(buildLabel({}), null);
});

import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';

const src = join(import.meta.dirname, '..', 'src');

function* sources(dir: string): Generator<string> {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* sources(path);
    else if (/\.(svelte|css|ts)$/.test(entry.name) && !entry.name.endsWith('.d.ts')) yield path;
  }
}

// A var() naming a token that does not exist is not an error anywhere: the
// declaration is dropped at computed-value time, so `--z-radius-pill` quietly
// draws square corners and `--z-weight-regular` inherits whatever the parent
// had. Nothing else catches a misspelt token, so this does.
test('every design token a component reads is defined somewhere', () => {
  const used: [string, string][] = [];
  const defined = new Set<string>();
  for (const path of sources(src)) {
    const text = readFileSync(path, 'utf8');
    // A name built by interpolation (`--z-radius-${size}`) is checked by
    // whatever chooses the suffix, not here.
    for (const [, name] of text.matchAll(/var\(\s*(--z-[a-z0-9-]+)/g)) {
      if (!name!.endsWith('-')) used.push([name!, path]);
    }
    // A component may declare a local property for its own children, in a
    // rule or through style:--z-x; both count as a definition.
    for (const [, name] of text.matchAll(/(?:^|[\s;{"'`]|style:)(--z-[a-z0-9-]+)\s*[:=]/g)) {
      defined.add(name!);
    }
  }
  const missing = [...used].filter(([name]) => !defined.has(name));
  assert.deepEqual(
    missing.map(([name, path]) => `${name} (${path.slice(src.length + 1)})`),
    [],
  );
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { sentence } from '../src/lib/errors.ts';

// The server's refusals are lowercase and unpunctuated because they are also a
// log line. Shown in a toast under a sentence-case title they read as raw
// output, so they are capitalised and stopped -- and only that: not a word of
// them changes, because a 403 names the role required.
test('a server refusal is capitalised and given a full stop without changing a word', () => {
  const cases: [string, string][] = [
    ['your account is not allowed to do that', 'Your account is not allowed to do that.'],
    [
      'no such thing; it may have been removed since the page loaded',
      'No such thing; it may have been removed since the page loaded.',
    ],
    ['  needs the admin role.  ', 'Needs the admin role.'],
    ['Already a sentence!', 'Already a sentence!'],
    ['', ''],
  ];
  for (const [given, want] of cases) assert.equal(sentence(given), want);
});

// A setting key or an ID leading the message is the operator's own word for a
// thing: capitalising `limits.job_stats_window` names a setting that does not
// exist, and the string they would search for is gone.
test('a message that opens with an identifier keeps it exactly as written', () => {
  const cases: [string, string][] = [
    [
      'limits.job_stats_window caps the range at 90 days',
      'limits.job_stats_window caps the range at 90 days.',
    ],
    ['pool_abc123 is still draining', 'pool_abc123 is still draining.'],
  ];
  for (const [given, want] of cases) assert.equal(sentence(given), want);
});

// A message that ends in an address or a path is not a sentence a full stop can
// close: the stop would be copied with the URL.
test('a message that ends in an address or a path gains no full stop', () => {
  for (const given of [
    'the callback must be registered at https://ci.example/oauth/callback',
    'the database is at /var/lib/zoomies/zoomies.db',
    'cannot continue:',
  ]) {
    assert.equal(sentence(given), given.charAt(0).toUpperCase() + given.slice(1));
  }
});

/**
 * The fault vocabulary, which is pure and is read by every page that shows a
 * failure.
 *
 * `faults.ts` deliberately imports no icons, so it loads in Node as-is. That is
 * the whole reason it is a file of its own rather than part of `status.ts`, and
 * this walks the two things a Playwright pass cannot: every category the server
 * can send, and the older-controller case where a job carries the fleet's prose
 * and no domain at all.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  FAULT_KINDS,
  faultDetail,
  faultDomain,
  faultLabel,
  fleetFailed,
} from '../src/lib/faults.ts';

test('every category has a label and a sentence', () => {
  for (const kind of FAULT_KINDS) {
    assert.notEqual(faultLabel(kind), '', `${kind} has no label`);
    assert.notEqual(faultDetail(kind), '', `${kind} has no detail`);
  }
});

test('a category this build does not know reads as itself, never as nothing', () => {
  // A fleet whose controller is newer sends kinds this bundle has never heard
  // of. An empty badge would say the failure had no category, which is the one
  // thing that is not true of it.
  assert.equal(faultLabel('quantum_decoherence'), 'Quantum decoherence');
  assert.equal(faultDetail('quantum_decoherence'), '');
  assert.equal(faultLabel(''), '');
  assert.equal(faultLabel(null), '');
  assert.equal(faultLabel(undefined), '');
});

test("the domain is the server's answer, and the fallback never blames a workflow", () => {
  assert.equal(faultDomain({ fault_domain: 'fleet' }), 'fleet');
  assert.equal(faultDomain({ fault_domain: 'workflow' }), 'workflow');
  assert.equal(faultDomain({ conclusion: 'success' }), '');

  // A job from a controller too old to send the domain carries the prose and
  // the category only. Reading it as the workflow's would hand somebody a bug
  // hunt for a failure this fleet caused, which is the exact mistake the whole
  // split exists to prevent.
  assert.equal(
    faultDomain({ runner_fault: 'runner zoomies-a stopped', conclusion: 'failure' }),
    'fleet',
  );
  assert.equal(faultDomain({ fault_kind: 'out_of_memory' }), 'fleet');
  assert.equal(fleetFailed({ runner_fault: 'runner zoomies-a stopped' }), true);
  assert.equal(fleetFailed({ conclusion: 'failure' }), false);
});

test('a domain the server sends that this build does not know falls back rather than being trusted', () => {
  // Not 'fleet' and not 'workflow', so the fields decide. Trusting an unknown
  // string would put it straight into a comparison that fails every branch and
  // renders nothing.
  assert.equal(faultDomain({ fault_domain: 'cosmic', fault_kind: 'out_of_memory' }), 'fleet');
  assert.equal(faultDomain({ fault_domain: 'cosmic' }), '');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import type { Host, Job, Machine, Problem, Provider } from '../src/lib/api/types.ts';
import {
  cpuChange,
  hostChanges,
  hostSignal,
  installationChange,
  jobFailure,
  jobNews,
  machineChange,
  newProblems,
  providerChanges,
  providerSignal,
  runnerMilestone,
} from '../src/lib/feed/changes.ts';

function host(fields: Partial<Host> = {}): Host {
  return { id: 'hst_1', name: 'builder-1', healthy: true, ...fields } as Host;
}

test('a host that has only moved its CPU reading is not news', () => {
  // The case the whole module exists for: every host publishes a frame on
  // every heartbeat, and a feed that reported them would be a feed nobody
  // reads -- and then one an operator switches off, losing the lines that
  // mattered.
  const before = hostSignal(host({ cpu_percent: 4 } as Partial<Host>));
  const after = hostSignal(host({ cpu_percent: 91 } as Partial<Host>));
  assert.deepEqual(hostChanges(after, before), []);
});

test('a host is reported when it stops answering and again when it comes back', () => {
  const healthy = hostSignal(host());
  const silent = hostSignal(host({ healthy: false }));
  assert.deepEqual(hostChanges(silent, healthy), ['unreachable']);
  assert.deepEqual(hostChanges(healthy, silent), ['recovered']);
});

test('every rung of the throttle ladder is its own line, and calm is one line', () => {
  // A host climbing the ladder is a host under worsening pressure, which is
  // the thing an operator watches for; coming off it happens once.
  const none = hostSignal(host());
  const first = hostSignal(host({ throttle: { level: 1 } } as Partial<Host>));
  const second = hostSignal(host({ throttle: { level: 2 } } as Partial<Host>));
  assert.deepEqual(hostChanges(first, none), ['throttled']);
  assert.deepEqual(hostChanges(second, first), ['throttled']);
  assert.deepEqual(hostChanges(first, second), [], 'stepping back down is not news on its own');
  assert.deepEqual(hostChanges(none, first), ['calm']);
});

test('a host holding new runners under pressure says so once, and says when it stops', () => {
  // Not the same thing as a throttle: a throttle takes slots away for minutes,
  // a hold is this moment's pressure refusing the next start. Both answer
  // "why is nothing starting here".
  const easy = hostSignal(host());
  const pressed = hostSignal(host({ admission_reason: 'load average 19.2 on 8 CPUs' }));
  assert.deepEqual(hostChanges(pressed, easy), ['holding']);
  assert.deepEqual(hostChanges(easy, pressed), ['admitting']);
  // The reason's wording moves with the load; only the transition is news.
  const worse = hostSignal(host({ admission_reason: 'load average 24.7 on 8 CPUs' }));
  assert.deepEqual(hostChanges(worse, pressed), []);
});

test('a runner reaching idle for the first time is the success worth reporting', () => {
  // The half of the fleet that goes right. A panel that only ever reported
  // failures would teach an operator that silence is the good state, which is
  // the same thing as teaching them not to read it.
  assert.equal(runnerMilestone('idle', 'registering'), 'ready');
  assert.equal(runnerMilestone('idle', undefined), 'ready');
  assert.equal(runnerMilestone('removed', 'draining'), 'retired');
});

test('a runner coming back from a job is not ready news again', () => {
  // The job's own line already said that, and a persistent runner would
  // otherwise write one of these after every job it takes.
  assert.equal(runnerMilestone('idle', 'busy'), null);
});

test('the states on the way up are not milestones', () => {
  // Six states per ephemeral runner, one runner per job: a feed that carried
  // them all would be a log.
  assert.equal(runnerMilestone('registering', 'provisioning'), null);
  assert.equal(runnerMilestone('busy', 'idle'), null);
  assert.equal(runnerMilestone('draining', 'busy'), null);
  assert.equal(runnerMilestone('idle', 'idle'), null);
});

test('a runner is reported when its elastic CPU state changes, not when the factor moves', () => {
  // The six states are what the runner's own page shows; the factor behind
  // them moves with every heartbeat.
  assert.equal(cpuChange('zoomies', 'guaranteed'), 'zoomies');
  assert.equal(cpuChange('maximum_zoomies', 'zoomies'), 'maximum_zoomies');
  assert.equal(cpuChange('throttled', 'maximum_zoomies'), 'throttled');
  assert.equal(cpuChange('zoomies', 'zoomies'), null);
  // The lead coming off a runner whose pool lends nothing is news too: it was
  // slowed by its host, and it is back at its share.
  assert.equal(cpuChange('sit_and_stay', 'throttled'), 'sit_and_stay');
  assert.equal(cpuChange('sit_and_stay', 'sit_and_stay'), null);
});

test('a runner already lent CPU when this tab opened is not news', () => {
  // The state it is already in is not something that just happened, and a
  // reconnect delivers one frame per runner.
  assert.equal(cpuChange('maximum_zoomies', undefined), null);
});

test('a host nobody here has seen before has joined the fleet', () => {
  assert.deepEqual(hostChanges(hostSignal(host()), undefined), ['joined']);
});

test('two things going wrong on one host are two lines, worst first', () => {
  const before = hostSignal(host());
  const after = hostSignal(host({ healthy: false, cordoned: true }));
  assert.deepEqual(hostChanges(after, before), ['unreachable', 'cordoned']);
});

function machine(state: string): Machine {
  return { id: 'mach_1', state, name: 'zoomies-mach-1' } as unknown as Machine;
}

test('a machine is reported when it starts costing money, earns it, or goes wrong', () => {
  assert.equal(machineChange(machine('creating'), undefined), 'creating');
  assert.equal(machineChange(machine('ready'), 'enrolling'), 'ready');
  assert.equal(machineChange(machine('failed'), 'bootstrapping'), 'failed');
  assert.equal(machineChange(machine('quarantined'), 'ready'), 'quarantined');
});

test('the steps on the way up are progress rather than news', () => {
  // The machine's own page has them, with their timings. A feed that carried
  // five lines per machine would bury everything else on a fleet renting any
  // number of them.
  assert.equal(machineChange(machine('starting'), 'creating'), null);
  assert.equal(machineChange(machine('bootstrapping'), 'starting'), null);
  assert.equal(machineChange(machine('enrolling'), 'bootstrapping'), null);
});

test('a machine republished in the state it is already in says nothing', () => {
  assert.equal(machineChange(machine('ready'), 'ready'), null);
});

function job(fields: Partial<Job>): Job {
  return { id: 'job_1', state: 'completed', ...fields } as Job;
}

test('a finished job lands in the category its ending belongs to', () => {
  // The failures are what an operator acts on, so they are their own
  // category and stay on; everything else is the panel this feed replaced,
  // which on a busy fleet is the noisiest thing here.
  assert.equal(jobNews(job({ conclusion: 'failure' })), 'failed');
  assert.equal(jobNews(job({ conclusion: 'timed_out' })), 'failed');
  assert.equal(jobNews(job({ conclusion: 'success' })), 'succeeded');
  assert.equal(jobNews(job({ conclusion: 'cancelled' })), 'cancelled');
  assert.equal(jobFailure('failed'), true);
  assert.equal(jobFailure('runner_lost'), true);
  assert.equal(jobFailure('succeeded'), false);
});

test('a job that has not finished is not news yet', () => {
  // It is on the Overview twice already -- in the running list and in the
  // matrix -- and a feed that repeated every step of it would say nothing.
  assert.equal(jobNews(job({ state: 'in_progress' })), null);
  assert.equal(jobNews(job({ state: 'queued' })), null);
});

test('a job whose runner stopped under it is the fleet’s failure, and says so', () => {
  // GitHub records it as an ordinary failure. The distinction is the one an
  // operator on this page is paid to make, so it survives into the feed --
  // and it survives a conclusion that says the job succeeded, which is what a
  // runner dying between the last step and the report looks like.
  assert.equal(
    jobNews(job({ conclusion: 'failure', runner_fault: 'runner_lost' } as Partial<Job>)),
    'runner_lost',
  );
  assert.equal(
    jobNews(job({ conclusion: 'success', runner_fault: 'runner_lost' } as Partial<Job>)),
    'runner_lost',
  );
});

function provider(fields: Partial<Provider> = {}): Provider {
  return { id: 'prv_1', name: 'proxmox-lab', enabled: true, paused: false, ...fields } as Provider;
}

test('a provider is reported when somebody stops it and when it stops answering', () => {
  const running = providerSignal(provider());
  const paused = providerSignal(provider({ paused: true }));
  const failing = providerSignal(provider({ last_check_error: 'certificate expired' }));
  assert.deepEqual(providerChanges(paused, running), ['paused']);
  assert.deepEqual(providerChanges(running, paused), ['resumed']);
  assert.deepEqual(providerChanges(failing, running), ['unreachable']);
  assert.deepEqual(providerChanges(running, failing), ['reachable']);
});

test('a provider seen for the first time is not an incident', () => {
  // Somebody has just added it, which the audit log records. Reporting it as
  // a change would mean every reconnect announced the whole fleet.
  assert.deepEqual(providerChanges(providerSignal(provider()), undefined), []);
});

test('an installation already failing when the tab opened is still worth saying once', () => {
  assert.equal(installationChange({ id: 'ins_1', healthy: false }, undefined), 'failing');
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, undefined), null);
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, false), 'working');
  assert.equal(installationChange({ id: 'ins_1', healthy: true }, true), null);
});

function problem(code: string, title: string): Problem {
  return { code, title, severity: 'warning' } as Problem;
}

test('a problem is reported once, however many times it is republished', () => {
  const seen = new Set<string>();
  const first = [problem('host.unhealthy', '1 host is not answering')];
  assert.equal(newProblems(first, seen).length, 1);
  assert.equal(newProblems(first, seen).length, 0);
});

test('a problem whose prose has changed is the same problem', () => {
  // "5 webhook deliveries were rejected" becoming "6 webhook deliveries were
  // rejected" is one fault, and re-reporting it every minute is the nagging
  // this identity exists to stop.
  const seen = new Set<string>();
  newProblems([problem('webhook.rejected', '5 deliveries were rejected')], seen);
  assert.equal(
    newProblems([problem('webhook.rejected', '6 deliveries were rejected')], seen).length,
    0,
  );
});

test('a problem that cleared and came back is news again', () => {
  const seen = new Set<string>();
  const fault = [problem('host.unhealthy', '1 host is not answering')];
  newProblems(fault, seen);
  newProblems([], seen);
  assert.equal(newProblems(fault, seen).length, 1);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { STATE_PRESENTATION, bandWords, sinceWords, waitWords } from '../src/status/present.ts';

// The three states sit on the fixed status mapping, one tone and one shape
// each, so the status page reads the way every other page does and never
// leans on colour alone.
test('each fleet state has its own tone and its own shape', () => {
  assert.equal(STATE_PRESENTATION.blocked.tone, 'danger');
  assert.equal(STATE_PRESENTATION.degraded.tone, 'pending');
  assert.equal(STATE_PRESENTATION.healthy.tone, 'idle');
  const shapes = new Set(Object.values(STATE_PRESENTATION).map((p) => p.shape));
  assert.equal(shapes.size, 3);
});

test('bands and waits are said in words, never as the raw value', () => {
  assert.equal(bandWords('backed_up'), 'backed up');
  assert.equal(bandWords('few'), 'a few');
  assert.equal(waitWords(0), 'under a minute');
  assert.equal(waitWords(1), 'about a minute');
  assert.equal(waitWords(14), 'about 14 minutes');
  assert.equal(waitWords(125), 'about 2 hours');
});

test('since is coarse, and empty when there is nothing to say', () => {
  const now = new Date('2026-09-26T12:00:00Z');
  assert.equal(sinceWords(undefined, now), '');
  assert.equal(sinceWords('not a date', now), '');
  assert.equal(sinceWords('2026-09-26T11:59:40Z', now), 'just now');
  assert.equal(sinceWords('2026-09-26T11:15:00Z', now), '45 minutes ago');
  assert.equal(sinceWords('2026-09-26T09:00:00Z', now), '3 hours ago');
  assert.equal(sinceWords('2026-09-22T12:00:00Z', now), '4 days ago');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  METRICS,
  PRESSURE,
  WINDOWS,
  bridgeFor,
  hostLines,
  hostSeries,
  indexAtX,
  leadMetric,
  lineRuns,
  liveSample,
  mergeHostSamples,
  metricText,
  metricValue,
  nearestHost,
  overflowCeiling,
  peakOf,
  plotFrame,
  scaleX,
  scaleY,
  windowSlots,
} from '../src/lib/insights/hostSeries.ts';
import type { Host, HostSample } from '../src/lib/api/types.ts';

const sample = (over: Partial<HostSample> = {}): HostSample => ({
  host_id: 'host_a',
  at: '2026-03-01T09:00:00Z',
  capacity: 4,
  active_runners: 3,
  cpu_percent: 72,
  load_average_1m: 12,
  cpus: 8,
  memory_mb: 16384,
  memory_available_mb: 4096,
  allocatable_cpus: 7,
  allocatable_memory_mb: 15000,
  reserved_cpus: 6,
  reserved_memory_mb: 12000,
  disk_total_mb: 1000,
  disk_free_mb: 250,
  ...over,
});

test('every metric is a share of the machine, and only load may pass 100', () => {
  const s = sample();
  assert.equal(metricValue(s, 'cpu'), 72);
  assert.equal(metricValue(s, 'memory'), 75);
  assert.equal(metricValue(s, 'load'), 150);
  assert.equal(metricValue(s, 'slots'), 75);
  assert.equal(Math.round(metricValue(s, 'cpu_committed') ?? 0), 86);
  assert.equal(metricValue(s, 'memory_committed'), 80);
  assert.equal(metricValue(s, 'disk'), 75);
  assert.equal(metricText(s, 'slots'), '3 / 4 slots');
});

test('a figure the host never reported is a gap, not a zero', () => {
  // An agent too old to measure: absent, and drawn as nothing rather than as
  // an idle machine.
  const s = sample({
    cpu_percent: undefined,
    memory_available_mb: undefined,
    load_average_1m: undefined,
    reserved_cpus: undefined,
    disk_total_mb: 0,
  });
  assert.equal(metricValue(s, 'cpu'), null);
  assert.equal(metricValue(s, 'memory'), null);
  assert.equal(metricValue(s, 'load'), null);
  assert.equal(metricValue(s, 'cpu_committed'), null);
  assert.equal(metricValue(s, 'disk'), null);
  assert.equal(metricText(s, 'cpu'), 'Not measured');
  // A measured zero is a zero.
  assert.equal(metricValue(sample({ memory_available_mb: 16384 }), 'memory'), 0);
  assert.equal(metricValue(sample({ capacity: 0 }), 'slots'), null);
});

test('the live point comes from the host view and drops a stale measurement', () => {
  const host: Host = {
    id: 'host_a',
    capacity: 6,
    effective_capacity: 3,
    active_runners: 2,
    usage: { cpu_percent: 40, memory_available_mb: 100 },
    usage_fresh: false,
    resources_known: true,
    reserved_known: true,
    reserved_cpus: 4,
    allocatable_cpus: 8,
    cpus: 8,
    memory_mb: 1000,
  };
  const now = Date.UTC(2026, 2, 1, 9, 30);
  const live = liveSample(host, now);
  // A throttled host is measured against the slots it is actually taking.
  assert.equal(live.capacity, 3);
  assert.equal(live.cpu_percent, undefined);
  assert.equal(metricValue(live, 'cpu'), null);
  assert.equal(metricValue(live, 'cpu_committed'), 50);
  assert.equal(metricValue(liveSample({ ...host, usage_fresh: true }, now), 'cpu'), 40);
});

test('merging keeps one sample per host per minute and the newer input wins', () => {
  const now = Date.UTC(2026, 2, 1, 9, 59, 30);
  const history = [
    sample({ at: '2026-03-01T09:58:00Z', cpu_percent: 10 }),
    sample({ at: '2026-03-01T08:00:00Z', cpu_percent: 99 }), // outside the hour
    sample({ host_id: 'host_b', at: '2026-03-01T09:58:20Z', cpu_percent: 50 }),
  ];
  const live = [sample({ at: '2026-03-01T09:58:40Z', cpu_percent: 20 })];
  const merged = mergeHostSamples(history, live, now, 3600);
  assert.deepEqual([...merged.keys()].sort(), ['host_a', 'host_b']);
  const a = merged.get('host_a') ?? [];
  assert.equal(a.length, 1);
  assert.equal(a[0]?.cpu_percent, 20);

  const series = hostSeries(a, 'cpu', now, 3600, 60);
  assert.equal(series.length, 60);
  assert.equal(series[58]?.value, 20);
  assert.equal(series[59]?.value, null);
  // Folded into five-minute peaks, the gap either side stays a gap.
  const folded = hostSeries(a, 'cpu', now, 3600, 300);
  assert.equal(folded.length, 12);
  assert.equal(folded[11]?.value, 20);
  assert.equal(folded[10]?.value, null);
});

test('a short window keeps every ten-second slot and folds nothing away', () => {
  // The controller writes one sample a minute, but a heartbeat is thirty
  // seconds and the stream carries each one: a window drawn ten seconds to a
  // point shows both, where a minute-by-minute line kept only the later.
  const now = Date.UTC(2026, 2, 1, 9, 59, 55);
  const live = [
    sample({ at: '2026-03-01T09:59:00Z', cpu_percent: 10 }),
    sample({ at: '2026-03-01T09:59:30Z', cpu_percent: 40 }),
    sample({ at: '2026-03-01T09:59:34Z', cpu_percent: 45 }), // same slot as the one before
    sample({ at: '2026-03-01T09:58:50Z', cpu_percent: 99 }), // before the minute
  ];
  const fine = mergeHostSamples([], live, now, 60, 10).get('host_a') ?? [];
  assert.deepEqual(
    fine.map((s) => s.cpu_percent),
    [10, 45],
  );
  // By the minute the same samples are one point: the last one wins.
  const coarse = mergeHostSamples([], live, now, 60, 60).get('host_a') ?? [];
  assert.deepEqual(
    coarse.map((s) => s.cpu_percent),
    [45],
  );

  const series = hostSeries(fine, 'cpu', now, 60, 10);
  assert.equal(series.length, 6);
  assert.deepEqual(
    series.map((p) => p.value),
    [10, null, null, 45, null, null],
  );
  // The window ends on the current slot, so its right-hand edge is now.
  const slots = windowSlots(now, 60, 10);
  assert.equal(slots.end, Date.UTC(2026, 2, 1, 9, 59, 50));
  assert.equal(slots.start, Date.UTC(2026, 2, 1, 9, 59, 0));
  assert.equal(slots.count, 6);
  // And a wide window still ends on the current minute, a whole bucket back.
  const day = windowSlots(now, 86400, 900);
  assert.equal(day.end, Date.UTC(2026, 2, 1, 9, 59));
  assert.equal(day.count, 96);
  assert.equal(day.start, day.end - (96 * 900 - 60) * 1000);
});

test('a fine window bridges a minute of silence and a minute-wide one bridges a minute', () => {
  // At ten seconds a point the stored samples are six points apart and a
  // heartbeat three, so both join; ninety seconds, which is a lost host,
  // does not. By the minute the rule is the one the comment on BRIDGE gives.
  assert.equal(bridgeFor(10), 6);
  assert.equal(bridgeFor(60), 1);
  assert.equal(bridgeFor(900), 1);
  const at = (i: number) => Date.UTC(2026, 2, 1, 9, 0, i * 10);
  const v = (i: number, value: number | null) => ({ at: at(i), value });
  const points = [v(0, 10), ...Array.from({ length: 5 }, (_, i) => v(i + 1, null)), v(6, 20)];
  assert.deepEqual(
    lineRuns(points, bridgeFor(10)).map((run) => run.map((p) => p.i)),
    [[0, 6]],
  );
  const lost = [v(0, 10), ...Array.from({ length: 8 }, (_, i) => v(i + 1, null)), v(9, 20)];
  assert.deepEqual(
    lineRuns(lost, bridgeFor(10)).map((run) => run.map((p) => p.i)),
    [[0], [9]],
  );
  // Every window's span is a whole number of its points.
  for (const w of WINDOWS) assert.equal(w.seconds % w.bucket, 0, w.value);
});

test('a line is drawn across one missing minute and broken by two', () => {
  // The sampler a moment late for a minute, or a tab that slept through one,
  // is not a host that stopped reporting; a line broken at every such minute
  // would read as a machine flickering in and out of existence.
  const at = (i: number) => Date.UTC(2026, 2, 1, 9, i);
  const v = (i: number, value: number | null) => ({ at: at(i), value });
  const points = [v(0, 10), v(1, null), v(2, 30), v(3, null), v(4, null), v(5, 50), v(6, 60)];
  const runs = lineRuns(points);
  assert.deepEqual(
    runs.map((run) => run.map((p) => p.i)),
    [
      [0, 2],
      [5, 6],
    ],
  );
  // The bridged minute is not in the run: nothing claims a figure for it.
  assert.deepEqual(
    runs[0]?.map((p) => p.value),
    [10, 30],
  );
  // Leading and trailing gaps are no run at all.
  assert.deepEqual(
    lineRuns([v(0, null), v(1, 5), v(2, null)]).map((run) => run.map((p) => p.i)),
    [[1]],
  );
  assert.deepEqual(lineRuns([v(0, null), v(1, null)]), []);
  // With no bridging every gap breaks the line, which is what the fold's
  // wider intervals used to do too.
  assert.deepEqual(
    lineRuns(points, 0).map((run) => run.map((p) => p.i)),
    [[0], [2], [5, 6]],
  );
});

