test('a wider window keeps its minutes, and a folded interval carries its peak', () => {
  const now = Date.now();
  const merged = mergeSamples(
    [{ at: new Date(now - 5 * 3_600_000).toISOString(), fleet_queued_jobs: 8 }],
    [],
