  );
  assert.equal(merged.length, 1, 'a sample five hours back is inside a six-hour window');
  assert.equal(mergeSamples(merged, [], now).length, 0, 'and outside the hour');

  const folded = foldMinutes(
    [
      { at: 0, value: 5 },
      { at: 60_000, value: null },
      { at: 120_000, value: 3 },
