/*
 * The fleet trend draws several figures at once, and a fold takes the peak of
 * each one separately: a folded point is five readings from the same interval,
 * not one minute's snapshot of five figures. Reading them from one chosen
 * minute -- the minute the lead figure peaked in -- would have said the queue
 * was twelve while nine runners sat idle, which never happened.
 */
test('every figure carries its own peak through a fold, and a missed minute stays a gap', () => {
  const now = Date.parse('2026-09-12T12:02:59Z');
  const at = (minutes: number) => new Date(now - minutes * 60_000).toISOString();
  const lines = signalLines(
    [
      { at: at(2), fleet_queued_jobs: 12, idle_runners: 0 },
      { at: at(1), fleet_queued_jobs: 1, idle_runners: 9 },
    ],
    ['queue', 'idle'],
    false,
    now,
    3,
    3,
  );
  assert.deepEqual(
    lines.map((l) => l.series.key),
    ['queue', 'idle'],
  );
  assert.equal(lines[0]?.points[0]?.value, 12);
  assert.equal(lines[1]?.points[0]?.value, 9);

  // A minute nobody sampled is a gap in the line and never a zero: a
  // controller that was down and an empty queue are opposite news.
  const minutes = signalLines([{ at: at(2), fleet_queued_jobs: 4 }], ['queue'], false, now, 3, 1);
  assert.deepEqual(
    minutes[0]?.points.map((p) => p.value),
    [4, null, null],
  );
  assert.deepEqual(minutes[0]?.last, { i: 0, value: 4 });
  assert.deepEqual(seriesRuns(minutes[0]!.points), [[{ i: 0, value: 4 }]]);
});

/* Whose jobs the two job figures count is the caller's choice; runner counts
   are always this fleet's, because nobody else's runners are visible here. */
test('the job figures follow the fleet or the whole organisation, and the runner figures do not', () => {
  const sample = {
    at: '2026-09-12T12:00:00Z',
    queued_jobs: 20,
    fleet_queued_jobs: 3,
    running_jobs: 40,
    fleet_running_jobs: 5,
    idle_runners: 2,
    busy_runners: 5,
    total_runners: 9,
  };
  assert.equal(signalValue(sample, 'queue', false), 3);
  assert.equal(signalValue(sample, 'queue', true), 20);
  assert.equal(signalValue(sample, 'running', true), 40);
  for (const key of ['idle', 'busy', 'live'] as const)
    assert.equal(signalValue(sample, key, true), signalValue(sample, key, false));
  // A figure the controller did not report is unknown, not zero.
  assert.equal(signalValue({ at: sample.at }, 'live', false), null);
  // The lead figure is the first chosen one in the chips' order, whatever
  // order they were switched on in.
  assert.equal(leadSignal(['live', 'queue'])?.key, 'queue');
  assert.equal(leadSignal([]), null);
  assert.ok(DEFAULT_SIGNALS.every((k) => SIGNALS.some((s) => s.key === k)));
});

/*
 * The shaded band is this chart's pressure line: jobs waiting with nothing
 * idle to take them. A spell of it is one band rather than a picket fence,
 * and an interval nobody sampled ends the spell rather than joining across it
 * -- the fleet may well have recovered inside the minute nobody watched.
 */
test('starvation is queued work with nothing free, and an unobserved interval breaks the spell', () => {
  const line = (key: 'queue' | 'idle', values: Array<number | null>) => ({
    series: SIGNALS.find((s) => s.key === key)!,
    points: values.map((value, i) => ({ at: i * 60_000, value })),
    last: null,
  });
  assert.deepEqual(starvedRuns(line('queue', [1, 2, 0, 4, 5]), line('idle', [0, 0, 0, 0, 0])), [
    { from: 0, to: 1 },
    { from: 3, to: 4 },
  ]);
  assert.deepEqual(starvedRuns(line('queue', [1, null, 1]), line('idle', [0, 0, 0])), [
    { from: 0, to: 0 },
    { from: 2, to: 2 },
  ]);
  // Judged a minute at a time and folded afterwards, so zooming out keeps the
  // band: a quarter of an hour in which any minute ran short is shaded, where
  // folding the figures first would have compared the deepest queue with the
  // most idle runners the interval ever had and found nothing wrong.
  assert.deepEqual(
    starvedRuns(line('queue', [0, 5, 0, 0, 0, 0, 0, 0]), line('idle', [2, 0, 3, 3, 3, 3, 3, 3]), 4),
    [{ from: 0, to: 0 }],
  );
  // Two spells with a clear interval between them stay two bands rather than
  // one long one; two that land in neighbouring intervals are one band, which
  // is what shading a spell rather than its minutes means.
  const twelve = (starved: number[]) =>
    Array.from({ length: 12 }, (_, i) => (starved.includes(i) ? 0 : 3));
  assert.deepEqual(starvedRuns(line('queue', Array(12).fill(1)), line('idle', twelve([0, 9])), 4), [
    { from: 0, to: 0 },
    { from: 2, to: 2 },
  ]);
  assert.deepEqual(starvedRuns(line('queue', Array(12).fill(1)), line('idle', twelve([0, 5])), 4), [
    { from: 0, to: 1 },
  ]);
  // An idle runner, or an unknown count of them, is not starvation.
  assert.deepEqual(starvedRuns(line('queue', [3]), line('idle', [1])), []);
  assert.deepEqual(starvedRuns(line('queue', [3]), line('idle', [null])), []);
  assert.deepEqual(starvedRuns(null, line('idle', [0])), []);

  const peak = seriesPeak([line('queue', [1, 7, 2])]);
  assert.equal(peak?.value, 7);
  assert.equal(peak?.i, 1);
  assert.equal(seriesPeak([]), null);
});

/**
 * The badge a job wears for what has been done to it, which is pure decision
 * logic and the one thing standing between an operator and a list that lies.
 *
 * GitHub keeps calling a job `queued` or `in_progress` until its own
 * completion delivery lands, so a row that showed only the state said the
 * fleet was about to run work that had been cancelled, or removed from the
 * queue, or put on hold. Three sources say it -- the Jobs grid, the drawer and
 * the pool's list -- and all three read this function, so this is where the
 * precedence between them is worth pinning down.
 *
 * `status.ts` imports Lucide components, which cannot load outside a browser.
 * The hook below swaps them for plain functions, as the views test does, and
 * reads the names out of the file so adding an icon does not break this one.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { registerHooks } from 'node:module';

const LUCIDE = 'zoomies-test:lucide-stub';
const iconNames = (
  /import\s*\{([^}]*)\}\s*from\s*'@lucide\/svelte'/.exec(
    readFileSync(new URL('../src/lib/status.ts', import.meta.url), 'utf8'),
  )?.[1] ?? ''
)
  .split(',')
  .map((name) => name.trim())
  .filter((name) => name !== '');

registerHooks({
  resolve(specifier, context, next) {
    if (specifier === '@lucide/svelte')
      return { url: LUCIDE, format: 'module', shortCircuit: true };
    return next(specifier, context);
  },
  load(url, context, next) {
    if (url === LUCIDE)
      return {
        format: 'module',
        shortCircuit: true,
        source: iconNames.map((name) => `export function ${name}() {}`).join('\n'),
      };
    return next(url, context);
  },
});

const { queueStatus, QUEUE_STATUS_LABELS } = await import('../src/lib/status.ts');

const AT = '2026-01-01T00:00:00Z';

test('a job nobody has touched wears no badge', () => {
  // The ordinary case stays quiet: a badge on every row is a badge nobody
  // reads.
  for (const state of ['queued', 'in_progress'] as const) {
    assert.equal(queueStatus({ state }), undefined, state);
  }
});

test('a stood-down queued job says which way it was stood down', () => {
  assert.equal(queueStatus({ state: 'queued', provisioning: 'paused' })?.label, 'Paused');
  assert.equal(queueStatus({ state: 'queued', provisioning: 'deleted' })?.label, 'Removed');
});

test('a job asked to run now says so, and a hold outranks the ask', () => {
  // Run now is the one thing an operator can do to a queued job that is not
  // a standing-down, and a row that went on reading plainly Queued after it
  // was pressed looked like a button that did nothing. Pausing an expedited
  // job keeps the ask -- resuming brings it back -- but the hold is what the
  // fleet is doing now, so the hold is what the row says.
  assert.equal(queueStatus({ state: 'queued', provision_now: true })?.label, 'Run now');
  assert.equal(
    queueStatus({ state: 'queued', provisioning: 'paused', provision_now: true })?.label,
    'Paused',
  );
  assert.equal(queueStatus({ state: 'in_progress', provision_now: true }), undefined);
});

test('a cancellation outranks the pause it causes', () => {
  // Cancelling a run pauses its queued jobs, so a job somebody cancelled
  // carries both marks. Reporting the pause would tell an operator their own
  // cancellation was a hold, and send them looking for the Resume that undoes
  // it.
  assert.equal(
    queueStatus({ state: 'queued', provisioning: 'paused', cancel_requested_at: AT })?.label,
    'Cancelling',
  );
  // And it is the only one that applies to a running job, whose runner the
  // fleet has already taken away.
  assert.equal(queueStatus({ state: 'in_progress', cancel_requested_at: AT })?.label, 'Cancelling');
});

test('a finished job wears none of them', () => {
  // Once something has run it, what was done to its demand is history and the
  // conclusion is the status. A completed job badged "Cancelling" would read
  // as one still on its way out.
  for (const job of [
    { state: 'completed' as const, provisioning: 'deleted' },
    { state: 'completed' as const, cancel_requested_at: AT },
    { state: 'waiting' as const, provisioning: 'paused' },
  ]) {
    assert.equal(queueStatus(job), undefined, JSON.stringify(job));
  }
});

test('the badges and the Queue page read from one vocabulary', () => {
  // The Queue's status buttons, the Jobs page's filter chip and the badge on
  // a row all take their words from this map. Two names for one state is how
  // two pages come to disagree about what an operator did.
  assert.deepEqual(QUEUE_STATUS_LABELS, {
    ready: 'Ready',
    expedited: 'Run now',
    paused: 'Paused',
    deleted: 'Removed',
  });
  assert.equal(
    queueStatus({ state: 'queued', provisioning: 'deleted' })?.label,
    QUEUE_STATUS_LABELS.deleted,
  );
  assert.equal(
    queueStatus({ state: 'queued', provisioning: 'paused' })?.label,
    QUEUE_STATUS_LABELS.paused,
  );
  assert.equal(
    queueStatus({ state: 'queued', provision_now: true })?.label,
    QUEUE_STATUS_LABELS.expedited,
  );
});

