import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  DEFAULT_ASK,
  capacityCeiling,
  diskNotches,
  memoryNotches,
  overcommit,
  recommendedCapacity,
  recommendedReserveCores,
  recommendedReserveDiskMb,
  recommendedReserveMemoryMb,
  runnerAsk,
} from '../src/lib/hosts/recommend.ts';

test('the runner ask is the largest enabled pool asks for, or the default', () => {
  assert.deepEqual(runnerAsk([]), DEFAULT_ASK);
  const ask = runnerAsk([
    { enabled: true, resources: { cpus: 2, memory_mb: 4096 } },
    { enabled: true, resources: { cpus: 4, memory_mb: 2048 } },
    { enabled: false, resources: { cpus: 16, memory_mb: 65536 } },
  ]);
  assert.deepEqual(ask, { cpus: 4, memoryMb: 4096, source: 'pools', pair: false });
});

// A docker-in-docker slot is two containers with the same limits where the
// pool typed those limits, so the ask is twice its figures. A pool that leaves
// its size to the host asks for one runner's worth: its runner and its daemon
// split the slot they land in rather than taking two.
test('a docker-in-docker pool asks for both of its containers when it sized them', () => {
  assert.deepEqual(runnerAsk([{ enabled: true, docker_mode: 'dind', resources: {} }]), {
    cpus: 2,
    memoryMb: 4096,
    source: 'default',
    pair: false,
  });
  assert.deepEqual(
    runnerAsk([{ enabled: true, docker_mode: 'dind', resources: { cpus: 2, memory_mb: 4096 } }]),
    { cpus: 4, memoryMb: 8192, source: 'pools', pair: true },
  );
  // A dind pool that is not the largest ask leaves the figure alone, and
  // says nothing about a pair: this function has no host in hand, so it
  // cannot know whether that pool places on the machine being adjusted.
  assert.deepEqual(
    runnerAsk([
      { enabled: true, resources: { cpus: 2, memory_mb: 4096 } },
      { enabled: true, docker_mode: 'dind', resources: {} },
    ]),
    { cpus: 2, memoryMb: 4096, source: 'pools', pair: false },
  );
  // Twelve cores less a core held back is room for two pairs at four cores
  // each, which is what a pool that typed two cores asks for here.
  assert.equal(
    recommendedCapacity(
      { cpus: 12, memoryMb: 32768 },
      1,
      3072,
      runnerAsk([{ enabled: true, docker_mode: 'dind', resources: { cpus: 2, memory_mb: 4096 } }]),
    ),
    2,
  );
  // The same fleet with that pool sized by its host has room for five: the
  // pair shares a slot, so a slot is one runner.
  assert.equal(
    recommendedCapacity(
      { cpus: 12, memoryMb: 32768 },
      1,
      3072,
      runnerAsk([{ enabled: true, docker_mode: 'dind', resources: {} }]),
    ),
    5,
  );
});

test('the reserve keeps a core and a tenth of memory, and never the whole machine', () => {
  assert.equal(recommendedReserveCores(1), 0);
  assert.equal(recommendedReserveCores(2), 1);
  assert.equal(recommendedReserveCores(16), 1);
  assert.equal(recommendedReserveCores(48), 3);
  assert.equal(recommendedReserveMemoryMb(1024), 0);
  assert.equal(recommendedReserveMemoryMb(1536), 1024);
  assert.equal(recommendedReserveMemoryMb(32768), 3072);
  // A tenth of sixteen gigabytes is between two notches; the next one up.
  assert.equal(recommendedReserveMemoryMb(16384), 2048);
  assert.equal(recommendedReserveMemoryMb(262144), 8192);
});

test('the disk reserve is a tenth of the filesystem, on a notch the slider stops at', () => {
  // Nothing worth holding back on a disk barely larger than the floor.
  assert.equal(recommendedReserveDiskMb(4096), 0);
  assert.deepEqual(diskNotches(4096), [0]);
  // 100 GB: a tenth is 10 GB, and 8 GB is the notch nearest it.
  assert.equal(recommendedReserveDiskMb(102_400), 8192);
  // Capped, so a terabyte does not hold back a hundred gigabytes.
  assert.equal(recommendedReserveDiskMb(1_048_576), 65_536);
  // The notches double from the scheduler's own floor, and never reach the
  // whole disk -- a reserve that leaves nothing to place on is refused.
  assert.deepEqual(diskNotches(65_536), [0, 2048, 4096, 8192, 16_384, 32_768]);
  assert.ok((diskNotches(65_536).at(-1) ?? 0) < 65_536);
});

test('capacity is what fits after the reserve, on the tighter of CPU and memory', () => {
  const host = { cpus: 16, memoryMb: 32768 };
  // 15 cores / 2 = 7; 29.7 GB / 4 GB = 7.
  assert.equal(recommendedCapacity(host, 1, 3072, DEFAULT_ASK), 7);
  // Memory is the tighter one here.
  assert.equal(recommendedCapacity(host, 1, 3072, { cpus: 1, memoryMb: 8192, source: 'pools' }), 3);
  // A host that has said nothing about itself gets no recommendation.
  assert.equal(recommendedCapacity({ cpus: 0, memoryMb: 0 }, 0, 0, DEFAULT_ASK), 0);
  // Never zero on a machine, however small: one runner is what a host is for.
  assert.equal(recommendedCapacity({ cpus: 2, memoryMb: 2048 }, 1, 1024, DEFAULT_ASK), 1);
});

test('the sliders reach far enough to include what is set today', () => {
  assert.equal(capacityCeiling({ cpus: 16, memoryMb: 32768 }, 7, 6), 16);
  assert.equal(capacityCeiling({ cpus: 16, memoryMb: 32768 }, 7, 20), 20);
  assert.equal(capacityCeiling({ cpus: 0, memoryMb: 0 }, 0, 3), 8);
  assert.deepEqual(memoryNotches(4096), [0, 512, 1024, 2048, 3072]);
  assert.equal(memoryNotches(65536).at(-1), 49152);
});

test('overcommit says how far past the room the runners would reach', () => {
  const host = { cpus: 8, memoryMb: 16384 };
  assert.deepEqual(overcommit(host, 3, 1, 1024, DEFAULT_ASK), { cpus: 0, memoryMb: 0 });
  assert.deepEqual(overcommit(host, 6, 1, 1024, DEFAULT_ASK), { cpus: 5, memoryMb: 9216 });
});

// Lets the unit tests import the app's modules as the app does.
//
// Vite resolves `import { x } from '../format'` to format.ts; Node's module
// loader does not, and would otherwise confine the unit tests to modules that
// import nothing. The hook tries the `.ts` spelling of any extensionless
// relative import first, and falls back to Node's own resolution for anything
// else, so a bare package import is untouched.
import { register } from 'node:module';

register('./resolve.mjs', import.meta.url);

import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, resolve as resolvePath } from 'node:path';

// Vite's `$lib` alias, which the unit runner does not otherwise know about.
// Without it a module can only be unit-tested if it happens to import nothing
// across the alias -- which is not a property worth choosing test coverage by.
const LIB = pathToFileURL(
  resolvePath(dirname(fileURLToPath(import.meta.url)), '../src/lib') + '/',
).href;

export async function resolve(specifier, context, next) {
  if (specifier === '$lib' || specifier.startsWith('$lib/')) {
    const rest = specifier === '$lib' ? '' : specifier.slice('$lib/'.length);
    const url = LIB + rest;
    // The same extensionless-TypeScript retry the relative branch below does.
    if (!/\.[a-z]+$/i.test(url)) {
      try {
        return await next(`${url}.ts`, context);
      } catch {
        // Not a TypeScript module after all; fall through.
      }
    }
    return next(url, context);
  }
  if (specifier.startsWith('.') && !/\.[a-z]+$/i.test(specifier)) {
    try {
      return await next(`${specifier}.ts`, context);
    } catch {
      // Not a TypeScript module after all; let Node say what it is.
    }
  }
  return next(specifier, context);
}

// A Svelte component of our own -- an icon drawn for a status -- cannot be
// compiled here any more than Lucide's can, and nothing a unit test checks
// needs it to be: a state map only needs its icon to be a distinct value. So
// every `.svelte` import resolves to a stub, for every test at once, rather
// than each test that reaches one learning the same lesson.
export async function load(url, context, next) {
  if (url.endsWith('.svelte')) {
    return { format: 'module', shortCircuit: true, source: 'export default function () {}' };
  }
  return next(url, context);
}

