import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';

const css = readFileSync(
  join(import.meta.dirname, '..', 'src', 'lib', 'styles', 'tokens.css'),
  'utf8',
);

/** The declarations of the first block that opens with `selector`. */
function block(selector: string): string {
  const start = css.indexOf(`${selector} {`);
  assert.notEqual(start, -1, `${selector} is in tokens.css`);
  return css.slice(start, css.indexOf('\n}', start));
}

function token(scope: string, name: string): string {
  const found = new RegExp(`${name}:\\s*(#[0-9a-fA-F]{6});`).exec(scope);
  assert.ok(found, `${name} is a hex value in its block`);
  return found[1] as string;
}

function luminance(hex: string): number {
  const [r, g, b] = [1, 3, 5].map((i) => {
    const c = parseInt(hex.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  }) as [number, number, number];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function contrast(a: string, b: string): number {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x) as [number, number];
  return (hi + 0.05) / (lo + 0.05);
}

// Subtle is the weakest text in the product -- timestamps, breadcrumbs,
// placeholders -- and it sits on the page ground and inside sunken wells and
// hovered rows as often as on a white card. AA is 4.5:1 on each of them, not
// on the best one.
const LIGHT_SURFACES = ['--z-brand-white', '--z-bg', '--z-surface-sunken', '--z-surface-hover'];

test('subtle text reaches AA on every light surface it sits on', () => {
  const light = block(':root');
  const subtle = token(light, '--z-text-subtle');
  for (const surface of LIGHT_SURFACES.map((name) => token(light, name))) {
    assert.ok(
      contrast(subtle, surface) >= 4.5,
      `${subtle} on ${surface} is ${contrast(subtle, surface).toFixed(2)}:1`,
    );
  }
});

test('subtle text is still visibly weaker than muted text in the light theme', () => {
  const light = block(':root');
  const onGround = token(light, '--z-bg');
  const muted = contrast(token(light, '--z-text-muted'), onGround);
  const subtle = contrast(token(light, '--z-text-subtle'), onGround);
  assert.ok(
    muted - subtle >= 0.75,
    `muted ${muted.toFixed(2)}:1 against subtle ${subtle.toFixed(2)}:1`,
  );
});

test('subtle text reaches AA on every dark surface it sits on', () => {
  const dark = block(":root[data-theme='dark']");
  const subtle = token(dark, '--z-text-subtle');
  for (const name of ['--z-bg', '--z-surface', '--z-surface-raised', '--z-surface-sunken']) {
    const surface = token(dark, name);
    assert.ok(
      contrast(subtle, surface) >= 4.5,
      `${subtle} on ${surface} is ${contrast(subtle, surface).toFixed(2)}:1`,
    );
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatQuantity, goDuration, parseQuantity } from '../src/lib/units.ts';

function value(text: string, quantity: Parameters<typeof parseQuantity>[1]): number | null {
  const parsed = parseQuantity(text, quantity);
  assert.ok(parsed.ok, `${JSON.stringify(text)} was refused`);
  return parsed.value;
}

// Every spelling of four gigabytes an operator reaches for is the same limit.
// A field that took "4096" and refused "4g" taught people to do arithmetic the
// page could have done.
test('the spellings of four gigabytes all mean 4096 MB', () => {
  for (const text of [
    '4gb',
    '4GB',
    '4 GB',
    '4g',
    '4G',
    '4GiB',
    '4 gib',
    '4096mb',
    '4096',
    '4096 MB',
  ]) {
    assert.equal(value(text, 'mb'), 4096, text);
  }
});

test('a fraction of a gigabyte is kept in whole megabytes', () => {
  assert.equal(value('1.5g', 'mb'), 1536);
  assert.equal(value('0.5 GB', 'mb'), 512);
  assert.equal(value('1t', 'mb'), 1024 * 1024);
});

// A bare number means the field's own unit, so a disk figure of 40 is not
// silently forty megabytes.
test('a bare number is read in the unit the field is set in', () => {
  assert.equal(value('40', 'gb'), 40);
  assert.equal(value('1.5 TB', 'gb'), 1536);
  assert.equal(value('512mb', 'gb'), 1);
});

test('CPU takes decimals, cores and millicores', () => {
  assert.equal(value('1.5', 'cpus'), 1.5);
  assert.equal(value('1.5 cores', 'cpus'), 1.5);
  assert.equal(value('2 vCPUs', 'cpus'), 2);
  assert.equal(value('1500m', 'cpus'), 1.5);
  assert.equal(value('.25', 'cpus'), 0.25);
});

// Clearing a field is an answer -- "no limit", "the template decides" -- and
// must not read as a mistake.
test('an empty field is nothing rather than an error', () => {
  assert.deepEqual(parseQuantity('  ', 'mb'), { ok: true, value: null });
});

test('what cannot be read is refused with an example of what can', () => {
  for (const text of ['four gigs', '4 bananas', '-2', '4b', '1..5']) {
    const parsed = parseQuantity(text, 'mb');
    assert.equal(parsed.ok, false, text);
    if (!parsed.ok) assert.match(parsed.error, /4 GB/);
  }
  const cpu = parseQuantity('lots', 'cpus');
  assert.equal(cpu.ok, false);
});

// The field writes back what it understood, in the largest unit that says it
// exactly -- 4096mb becomes "4 GB" -- and never a rounded figure that would be
// a different limit from the one set.
test('a size is written back in the largest unit that says it exactly', () => {
  assert.equal(formatQuantity(4096, 'mb'), '4 GB');
  assert.equal(formatQuantity(1536, 'mb'), '1.5 GB');
  assert.equal(formatQuantity(512, 'mb'), '512 MB');
  assert.equal(formatQuantity(3000, 'mb'), '3000 MB');
  assert.equal(formatQuantity(1024 * 1024, 'mb'), '1 TB');
  assert.equal(formatQuantity(40, 'gb'), '40 GB');
  assert.equal(formatQuantity(2048, 'gb'), '2 TB');
  assert.equal(formatQuantity(1.5, 'cpus'), '1.5 cores');
  assert.equal(formatQuantity(1, 'cpus'), '1 core');
});

test('what the field writes back reads back as the same value', () => {
  for (const mb of [512, 1536, 3000, 4096, 12288, 131072]) {
    assert.equal(value(formatQuantity(mb, 'mb'), 'mb'), mb);
  }
  for (const cpus of [0.25, 1, 1.5, 12]) {
    assert.equal(value(formatQuantity(cpus, 'cpus'), 'cpus'), cpus);
  }
});

// A retention period is a number of days to the person setting it and a
// number of hours to Go. The field takes either, and anything between.
test('a duration reads Go spelling and the one people say', () => {
  const hour = 3600 * 1000;
  assert.equal(value('168h', 'ms'), 168 * hour);
  assert.equal(value('7d', 'ms'), 168 * hour);
  assert.equal(value('7 days', 'ms'), 168 * hour);
  assert.equal(value('1 week', 'ms'), 168 * hour);
  assert.equal(value('1h30m', 'ms'), 1.5 * hour);
  assert.equal(value('1h 30m', 'ms'), 1.5 * hour);
  assert.equal(value('1.5h', 'ms'), 1.5 * hour);
  assert.equal(value('90 seconds', 'ms'), 90 * 1000);
  assert.equal(value('500ms', 'ms'), 500);
  // A bare number is seconds, as runners.docker_wait always meant it.
  assert.equal(value('120', 'ms'), 120 * 1000);
  for (const text of ['soon', '5 fortnights', '1h and 5m', 'h']) {
    assert.equal(parseQuantity(text, 'ms').ok, false, text);
  }
});

test('a duration is written back in the largest units that say it exactly', () => {
  assert.equal(formatQuantity(90 * 1000, 'ms'), '1m 30s');
  assert.equal(formatQuantity(3600 * 1000, 'ms'), '1h');
  assert.equal(formatQuantity(36 * 3600 * 1000, 'ms'), '1d 12h');
  assert.equal(formatQuantity(720 * 3600 * 1000, 'ms'), '30d');
  assert.equal(formatQuantity(500, 'ms'), '500ms');
  assert.equal(formatQuantity(0, 'ms'), '0s');
  for (const ms of [500, 90_000, 5_400_000, 129_600_000, 2_592_000_000]) {
    assert.equal(value(formatQuantity(ms, 'ms'), 'ms'), ms);
  }
});

// The controller reads Go's spelling, which has no day.
test('a duration is sent in the spelling Go reads', () => {
  assert.equal(goDuration(720 * 3600 * 1000), '720h');
  assert.equal(goDuration(90 * 1000), '1m30s');
  assert.equal(goDuration(1500), '1s500ms');
  assert.equal(goDuration(0), '0s');
});

test('a count is a whole number and nothing else', () => {
  assert.equal(value('10', 'count'), 10);
  assert.equal(value('1,000', 'count'), 1000);
  assert.equal(parseQuantity('1.5', 'count').ok, false);
  assert.equal(formatQuantity(12, 'count'), '12');
});

/*
 * The usage chart's figures. The arithmetic is here rather than in the
 * component so that "this day has not happened yet" and "the fleet had
 * nowhere to put a runner" can be tested without a browser.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { emptyBucket, type ActivityBucket } from '../src/lib/insights/activity.ts';
import {
  capacityRuns,
  inProgress,
  usageFigures,
  usageFormat,
  usageLines,
} from '../src/lib/insights/usageSeries.ts';

const DAY = 86_400_000;
const first = new Date(2026, 8, 14).getTime();
const day = (i: number, fill: Partial<ActivityBucket> = {}): ActivityBucket => ({
  ...emptyBucket(new Date(first + i * DAY).toISOString()),
  ...fill,
});
const figure = (key: string) => usageFigures('jobs', true).filter((f) => f.key === key);

/*
 * A report runs to the end of its last day, so a window chosen today has
 * hours in it that have not happened. Drawn as zeroes, they are a line that
 * dives to the floor and stays there -- a fleet that stopped, rather than one
 * whose week is not over.
 */
test('an interval that has not begun is a gap, and the one being filled is drawn', () => {
  const buckets = [day(0, { queued: 4 }), day(1, { queued: 2 }), day(2), day(3)];
  const [queued] = usageLines(buckets, figure('queued'), first + DAY + 3_600_000);
  assert.deepEqual(
    queued?.points.map((p) => p.value),
    [4, 2, null, null],
  );
  // The newest reading is the interval being filled, which is what the label
  // at the end of the line and the meters below are showing.
  assert.deepEqual(queued?.last, { i: 1, value: 2 });
  // An interval with nothing in it is still an interval: zero jobs queued on
  // a day that happened is news, and a gap is not.
  const quiet = usageLines([day(0)], figure('queued'), first + DAY);
  assert.deepEqual(
    quiet[0]?.points.map((p) => p.value),
    [0],
  );

  assert.equal(inProgress(day(1), 'day', first + DAY + 60_000), true);
  assert.equal(inProgress(day(0), 'day', first + DAY + 60_000), false);
  assert.equal(inProgress(day(2), 'day', first + DAY + 60_000), false);
});

/*
 * A runner idles on behalf of a pool and never on behalf of a repository, so
 * at those groupings its hours are not the group's to claim. The table drops
 * the column; the chart drops the line, rather than drawing somebody else's
 * time as this repository's.
 */
test('allocated runner time is only drawn where it can be attributed', () => {
  assert.deepEqual(
    usageFigures('runtime', true).map((f) => f.key),
    ['execution', 'allocated'],
  );
  assert.deepEqual(
    usageFigures('runtime', false).map((f) => f.key),
    ['execution'],
  );
  // The job counts belong to whoever ran them, at every grouping.
  assert.deepEqual(usageFigures('jobs', false).length, usageFigures('jobs', true).length);

  // Hours, not seconds: the axis is read in the unit the tiles above use.
  const [executing] = usageLines(
    [day(0, { execution_seconds: 5400 })],
    usageFigures('runtime', true),
    first + DAY,
  );
  assert.equal(executing?.points[0]?.value, 1.5);
});

/*
 * The band is the fleet trend's starvation shading, drawn from what the
 * report already counts: the minutes a pool had work to place and nowhere to
 * put it.
 */
test('the capacity band is a spell, and an interval nobody observed ends it', () => {
  const buckets = [
    day(0, { capacity_samples: 10, capacity_reached: 2 }),
    day(1, { capacity_samples: 10, capacity_reached: 1 }),
    day(2, { capacity_samples: 10 }),
    day(3, { capacity_samples: 0 }),
    day(4, { capacity_samples: 10, capacity_reached: 5 }),
  ];
  assert.deepEqual(capacityRuns(buckets), [
    { from: 0, to: 1 },
    { from: 4, to: 4 },
  ]);
  // A report with no capacity observations at all -- a repository grouping,
  // or a fleet that predates the counting -- shades nothing rather than
  // claiming the fleet was never short.
  assert.deepEqual(capacityRuns([day(0), day(1)]), []);
  assert.deepEqual(capacityRuns([]), []);
});

/* Colour alone never tells two lines apart; nor does the stroke alone. */
test('no two figures on one chart are drawn the same way, and hours keep their fractions', () => {
  for (const measure of ['jobs', 'runtime'] as const) {
    const drawn = new Set<string>();
    for (const f of usageFigures(measure, true)) {
      const mark = `${f.tone} ${f.dash}`;
      assert.ok(!drawn.has(mark), `${f.key} is drawn exactly like another figure`);
      drawn.add(mark);
      assert.match(f.tone, /^var\(--z-/, `${f.key} must take a token, not a colour`);
    }
  }
  // A count of jobs is whole; a quarter of an hour of runner time is not.
  assert.equal(usageFormat('jobs')(3), usageFormat('runtime')(3));
  assert.notEqual(usageFormat('jobs')(1.23456), usageFormat('runtime')(1.23456));
  assert.ok(!usageFormat('runtime')(1.23456).includes('456'));
});

import { defineConfig, type Plugin } from 'vite';
import { svelte } from '@sveltejs/vite-plugin-svelte';
import tailwindcss from '@tailwindcss/vite';
import { gzipSync } from 'node:zlib';
import { resolve } from 'node:path';

/**
 * The budgets from docs/ui-guidelines.md §5, in bytes gzipped.
 *
 * They are enforced rather than aspirational: an operator dashboard that takes
 * a second to appear on a slow VPN is a dashboard people stop opening.
 */
const SHELL_BUDGET = 200 * 1024;
const ROUTE_BUDGET = 80 * 1024;

/**
 * The status page's budget, for the whole of it: /status is its own document
 * (status.html), read by people with no account and often on a phone, and it
 * is a few words and a poll -- the tokens, one component and the Svelte
 * runtime. It is built by a second pass (`vite build --mode status`) rather
 * than as a second input to this one, because two inputs share chunks and a
 * shared chunk moved bytes into the app shell; built apart, the shell is
 * exactly what it was.
 */
const STATUS_BUDGET = 30 * 1024;

/**
 * Route chunks allowed past the route budget, with the number each is allowed.
 *
 * Named here rather than waved through: xterm.js is a terminal emulator, it is
 * what it costs, and it loads only on the two pages that show a runner's
 * output. An entry appearing in this map is a decision somebody made; a route
 * quietly growing past the budget is not.
 */
const ROUTE_ALLOWANCES: Record<string, number> = {
  xterm: 96 * 1024,
};

/** The chunk name without Vite's content hash: `assets/xterm.ScmBfeDI.js` -> `xterm`. */
function chunkName(file: string): string {
  return file.replace(/^.*\//, '').replace(/\.[^.]+\.(js|css)$/, '');
}

function budgets(label: string, limit: number): Plugin {
  return {
    name: 'zoomies-budgets',
    apply: 'build',
    generateBundle(_options, bundle) {
      // The shell is the entry chunk, everything it imports statically, and
      // the CSS those import. A route is reached by a dynamic import and is
      // not in this set -- which is the fix for a shell number that used to
      // charge every route's stylesheet to the first paint.
      const shellFiles = new Set<string>();
      const walk = (file: string): void => {
        const chunk = bundle[file];
        if (!chunk || chunk.type !== 'chunk' || shellFiles.has(file)) return;
        shellFiles.add(file);
        for (const css of chunk.viteMetadata?.importedCss ?? []) shellFiles.add(css);
        for (const imported of chunk.imports) walk(imported);
      };
      for (const [file, chunk] of Object.entries(bundle)) {
        if (chunk.type === 'chunk' && chunk.isEntry) walk(file);
      }

      let shell = 0;
      const rows: Array<[string, number]> = [];
      const overweight: string[] = [];
      for (const [file, chunk] of Object.entries(bundle)) {
        const source =
          chunk.type === 'chunk'
            ? chunk.code
            : typeof chunk.source === 'string'
              ? chunk.source
              : '';
        if (!source) continue;
        const size = gzipSync(Buffer.from(source)).length;
        const isShell = shellFiles.has(file);
        if (isShell) {
          shell += size;
        } else {
          const name = chunkName(file);
          const allowed = ROUTE_ALLOWANCES[name] ?? ROUTE_BUDGET;
          if (size > allowed) {
            overweight.push(
              `${file} is ${kb(size)} gzipped, over the ${kb(allowed)} a route may be`,
            );
          }
        }
        rows.push([`${isShell ? 'shell ' : 'route '}${file}`, size]);
      }
      rows.sort((a, b) => b[1] - a[1]);
      this.info(
        `gzipped sizes:\n${rows.map(([n, s]) => `  ${kb(s).padStart(9)}  ${n}`).join('\n')}`,
      );
      this.info(`${label}: ${kb(shell)} of ${kb(limit)} budget`);
      if (shell > limit) {
        this.error(
          `${label} is ${kb(shell)} gzipped, over the ${kb(limit)} budget in ` +
            `docs/ui-guidelines.md. Move something to a lazily loaded route, or raise the ` +
            `budget deliberately in both places.`,
        );
      }
      if (overweight.length > 0) {
        this.error(
          `${overweight.join('\n')}\n` +
            `The route budget is in docs/ui-guidelines.md. Split the route, or name it in ` +
            `ROUTE_ALLOWANCES with what it is allowed and why.`,
        );
      }
    },
  };
}

const kb = (n: number): string => `${(n / 1024).toFixed(1)} KB`;

export default defineConfig(({ mode }) => {
  const status = mode === 'status';
  return {
    plugins: [
      tailwindcss(),
      svelte(),
      status ? budgets('status page', STATUS_BUDGET) : budgets('app shell', SHELL_BUDGET),
    ],
    resolve: {
      alias: { $lib: resolve(import.meta.dirname, 'src/lib') },
    },
    build: {
      // Straight into the directory the Go binary embeds.
      outDir: '../internal/api/webdist',
      // The status pass writes beside the app's output, never over it.
      emptyOutDir: !status,
      target: 'es2022',
      sourcemap: false,
      chunkSizeWarningLimit: 300,
      rollupOptions: {
        input: resolve(import.meta.dirname, status ? 'status.html' : 'index.html'),
        output: {
          // Content-hashed so the Go server can serve them immutable.
          entryFileNames: 'assets/[name].[hash].js',
          chunkFileNames: 'assets/[name].[hash].js',
          assetFileNames: 'assets/[name].[hash][extname]',
        },
      },
    },
    server: {
      port: 5173,
      strictPort: true,
      proxy: {
        // `make dev` runs a controller on 8080; the Vite dev server proxies the
        // API to it so the UI can be developed with hot reload.
        '/api': { target: 'http://127.0.0.1:8080', changeOrigin: false, ws: false },
        '/webhooks': { target: 'http://127.0.0.1:8080' },
        '/metrics': { target: 'http://127.0.0.1:8080' },
        '/healthz': { target: 'http://127.0.0.1:8080' },
      },
    },
  };
});
